local function load_and_init(relative_path)
    if runtime.stopping then return nil end
    runtime.phase = "load"
    runtime.module = relative_path
    update_diagnostics()
    lifecycle_log(relative_path, "LOAD", "begin")
    local record, err = load_record(relative_path)
    if not record then
        lifecycle_log(relative_path, "LOAD", "failed", tostring(err))
        fail_startup("load", relative_path, err)
        return nil
    end
    lifecycle_log(relative_path, "LOAD", "ok")
    runtime.phase = "init"
    runtime.module = record.name
    update_diagnostics()
    lifecycle_log(record.name, "INIT", "begin")
    record.initialized = true
    runtime.initialized_names[#runtime.initialized_names + 1] = record.name
    if runtime.stopping then return nil end
    local module = record.module
    if type(module.Init) == "function" then
        local ok, err = xpcall(function() module.Init(context) end, traceback)
        if not ok then
            lifecycle_log(record.name, "INIT", "failed", tostring(err))
            fail_startup("init", record.name, err)
            return nil
        end
    end
    if runtime.stopping then return nil end
    lifecycle_log(record.name, "INIT", "ok")
    return record
end

local function start_record(record)
    if runtime.stopping then return false end
    runtime.phase = "start"
    runtime.module = record.name
    update_diagnostics()
    lifecycle_log(record.name, "START", "begin")
    if runtime.stopping then return false end
    local module = record.module
    if type(module.Start) == "function" then
        local ok, err = xpcall(function() module.Start(context) end, traceback)
        if not ok then
            lifecycle_log(record.name, "START", "failed", tostring(err))
            fail_startup("start", record.name, err)
            return false
        end
    end
    if runtime.stopping then return false end
    record.started = true
    lifecycle_log(record.name, "START", "ok")
    return true
end

-- Load data-only metadata before the runtime modules.
do
    local chunk, why = compile_module("assets/metadata.lua", {})
    if not chunk then
        fail_startup("metadata", "assets/metadata.lua", why); return
    end
    local ok, metadata = pcall(chunk)
    if not ok or type(metadata) ~= "table" or metadata.schema_version ~= 1 then
        fail_startup("metadata", "assets/metadata.lua", "Enhanced source catalog invalid: " .. tostring(metadata)); return
    end
    context.EnhancedMetadata = metadata
    public.SourceMetadata = metadata
end
for _, relative_path in ipairs(FRAMEWORK_MODULES) do
    if not load_and_init(relative_path) then return end
end

for _, record in ipairs(runtime.loaded) do
    if not start_record(record) then return end
end

-- The compatibility facade binds and registers modules last. It owns no
-- gameplay controls or scheduler.
local compat_record = load_and_init(COMPAT_MODULE)
if not compat_record then return end
if not start_record(compat_record) then return end

for _, record in ipairs(runtime.loaded) do
    for _, item in ipairs(record.tick_callbacks) do
        runtime.tick_sources[#runtime.tick_sources + 1] = item
    end
end

if #runtime.tick_sources == 1 then
    local item = runtime.tick_sources[1]
    if #item.args == 0 then
        runtime.base_tick = item.callback
    else
        runtime.base_tick = function() return item.callback(table.unpack(item.args)) end
    end
elseif #runtime.tick_sources > 1 then
    -- Compatibility safety fallback. The current baseline supplies one source;
    -- hot domain paths must remain attached to a single source.
    runtime.base_tick = function()
        for index = 1, #runtime.tick_sources do
            local item = runtime.tick_sources[index]
            item.callback(table.unpack(item.args))
        end
    end
end

runtime.phase = "activate"
runtime.module = "loader"
update_diagnostics()
for _, record in ipairs(runtime.loaded) do
    lifecycle_log(record.name, "ACTIVATE", "begin")
    local handlers_ok, handlers_err = arm_record_handlers(record)
    if not handlers_ok then
        lifecycle_log(record.name, "ACTIVATE", "failed", tostring(handlers_err))
        fail_startup("activate", record.name, handlers_err)
        return
    end
    local tabs_ok, tabs_err = arm_record_tabs(record)
    if not tabs_ok then
        lifecycle_log(record.name, "ACTIVATE", "failed", tostring(tabs_err))
        fail_startup("activate", record.name, tabs_err)
        return
    end
    lifecycle_log(record.name, "ACTIVATE", "ok")
end

-- All controls and callback targets are now fully constructed. Apply queued
-- feature defaults/list/slider state first; any callbacks they trigger remain
-- queued until that state is complete.
local audited_controls = flush_test_control_audit()
if audited_controls ~= EXPECTED_PHYSICAL_CONTROLS then
    fail_startup("activate", "control-audit", ("cataloged %d/%d physical controls")
        :format(audited_controls, EXPECTED_PHYSICAL_CONTROLS))
    return
end
runtime.feature_methods_enabled = true
local initialized_methods = 0
local preserved_defaults = 0
for _, record in ipairs(runtime.loaded) do
    local methods_ok, methods_result = replay_feature_methods(record)
    if not methods_ok then
        fail_startup("activate", record.name, methods_result)
        return
    end
    initialized_methods = initialized_methods + (tonumber(methods_result) or 0)
    for _ in pairs(record.feature_defaults) do preserved_defaults = preserved_defaults + 1 end
end
bootstrap_log("LogInfo", ("Queued feature initialization complete (%d state calls, %d local defaults).")
    :format(initialized_methods, preserved_defaults))

runtime.callbacks_enabled = true
for _, record in ipairs(runtime.loaded) do
    local replay_ok, replay_err = replay_feature_callbacks(record)
    if not replay_ok then
        fail_startup("activate", record.name, replay_err)
        return
    end
end

local player_runtime = context.CScript and context.CScript.Player
if player_runtime and type(player_runtime.RearmRuntimeState) == "function" then
    local ok, result = pcall(player_runtime.RearmRuntimeState, "loader post-feature-replay")
    if not ok or result == false then
        fail_startup("activate", "modules/player.lua",
            "post-feature-replay runtime rearm failed: " .. tostring(result))
        return
    end
    bootstrap_log("LogInfo", "Player runtime rearm queued after feature replay.")
end

-- Registration queues include slider defaults and list initialization. Restore
-- saved values after those writes, callbacks and runtime rearm have completed.
local config_runtime = context.Config
if type(config_runtime) ~= "table" or type(config_runtime.FinalizeStartup) ~= "function" then
    fail_startup("activate", "core/config.lua", "Configuration service is unavailable")
    return
end
local config_ok, config_result = xpcall(config_runtime.FinalizeStartup, traceback)
if not config_ok or config_result ~= true then
    fail_startup("activate", "core/config.lua", "Settings restoration failed: " .. tostring(config_result))
    return
end

local native_loops_ok, native_loops_error = native_loop_owner.Activate()
if not native_loops_ok then
    fail_startup("activate", "owned-native-loop", native_loops_error)
    return
end
rebuild_runtime_tick()

runtime.phase = "ready"
runtime.module = "loader"
update_diagnostics()
bootstrap_log("LogInfo", ("READY version=%s build=%s phase=%s mode=%s modules=%d loops=%d controls=%d"):format(
    LOADER_VERSION, BUILD_ID, MIGRATION_PHASE, runtime.mode,
    #runtime.loaded, #runtime.tick_sources, runtime.compat_controls))
if __CSCRIPT_PREBOOT_HANDOFF ~= true then bootstrap_toast("CScript is ready.", 2500) end
