-- Narrow access to Cherax Enhanced services supplied by the loader context.
local Module = { Name = "bridges.cherax", MigrationPhase = "17.75" }

local service

-- Independent callback-domain accounting. No arguments/results are copied and
-- no clock is read on an unsampled call. Counters are bounded by registered
-- domains, not event/entity/feature IDs. Inclusive timings must not be summed.
local function create_performance(context)
    local rows, order = {}, {}
    local active, since = true, nil
    local capture, last_now, capture_serial
    local api = {}
    local function clock()
        if not os or type(os.clock) ~= "function" then return nil end
        local ok, value = pcall(os.clock)
        if ok and type(value) == "number" and value == value and value >= 0 and value < math.huge then
            return value
        end
    end
    local function row_for(label, stride)
        label = tostring(label or "callback")
        local row = rows[label]
        if row then return row end
        if #order >= 64 then label = "other_callbacks"; row = rows[label]; if row then return row end end
        row = { label = label, calls = 0, samples = 0, total = 0, maximum = 0,
            stride = math.max(1, math.floor(tonumber(stride) or 61)) }
        rows[label] = row; order[#order + 1] = row
        return row
    end
    local function capture_row(label)
        if not capture or capture.complete then return nil end
        local row = capture.rows[label]
        if row then return row end
        if capture.row_count >= 63 then label = "other_callbacks"; row = capture.rows[label] end
        if not row then
            row = { label=label, calls=0, samples=0, total=0, maximum=0 }
            capture.rows[label] = row; capture.row_count = capture.row_count + 1
        end
        return row
    end
    local function capture_finish(row, began, ended)
        if not row or began == nil or ended == nil or ended < began then return end
        local elapsed = (ended - began) * 1000
        row.samples = row.samples + 1; row.total = row.total + elapsed
        if elapsed > row.maximum then row.maximum = elapsed end
    end
    local function begin(row)
        if not active then return nil end
        row.calls = row.calls + 1
        local sampled = (row.calls - 1) % row.stride == 0
        local began
        if capture and not capture.complete then
            began = clock()
            if began and capture.started_clock then capture.elapsed_clock_ms = math.max(0,(began-capture.started_clock)*1000) end
            if (capture.elapsed_clock_ms or 0) >= capture.duration_ms then
                capture.complete = true
            end
        end
        local captured = capture_row(row.label)
        if captured then captured.calls = captured.calls + 1 end
        if not sampled and not captured then return nil end
        return began or clock(), sampled, captured
    end
    local function finish(row, began, sampled, captured)
        if began == nil then return end
        local ended = clock()
        if ended == nil or ended < began then return end
        local elapsed = (ended - began) * 1000
        if sampled ~= false then
            row.samples = row.samples + 1; row.total = row.total + elapsed
            if elapsed > row.maximum then row.maximum = elapsed end
        end
        capture_finish(captured, began, ended)
    end
    function api.Wrap(label, callback, stride)
        if type(callback) ~= "function" then return callback end
        local row = row_for(label, stride)
        local function returned(began, sampled, captured, ...)
            finish(row, began, sampled, captured)
            return ...
        end
        return function(...)
            local began, sampled, captured = begin(row)
            if began == nil then return callback(...) end
            -- A throwing callback retains the host's existing error policy.
            -- An unsuccessful sample is not misreported as a zero-cost sample.
            return returned(began, sampled, captured, callback(...))
        end
    end
    function api.Begin(label, stride)
        if not active then return nil end
        local row = row_for(label, stride)
        row.calls = row.calls + 1
        if (row.calls - 1) % row.stride ~= 0 then return nil end
        return clock()
    end
    function api.Finish(label, began)
        local row = rows[label]
        if row then finish(row, began) end
    end
    -- Internal, opt-in diagnosis. Scheduler timestamps bound the window; normal
    -- sampling resumes automatically, with no per-frame logging or file I/O.
    function api.StartCapture(duration_ms, label)
        duration_ms = duration_ms == nil and 30000 or tonumber(duration_ms)
        if not active or not duration_ms or duration_ms ~= duration_ms or duration_ms < 1000 or duration_ms > 30000 then
            return false, "capture duration must be 1000-30000 ms"
        end
        if capture and not capture.complete then return false, "capture already active" end
        capture_serial = (capture_serial or 0) + 1
        capture = { id=capture_serial, label=tostring(label or "capture"):gsub("[%c]", " "):sub(1,80),
            duration_ms=duration_ms, started_ms=last_now, started_clock=clock(), complete=false, rows={}, row_count=0 }
        return true, capture.id
    end
    function api.CaptureSnapshot()
        if not capture then return nil end
        local elapsed = math.min(capture.duration_ms, math.max(0,
            capture.elapsed_clock_ms or 0,
            (last_now or capture.started_ms or 0) - (capture.started_ms or last_now or 0)))
        local seconds = elapsed / 1000
        local result = { id=capture.id, label=capture.label, clock="os.clock", inclusive=true, fps_measurement=false,
            complete=capture.complete, elapsed_ms=elapsed, duration_ms=capture.duration_ms, rows={} }
        for _, row in pairs(capture.rows) do
            result.rows[#result.rows+1] = { label=row.label, calls=row.calls, samples=row.samples,
                total_ms=row.total, mean_ms=row.samples>0 and row.total/row.samples or 0,
                maximum_ms=row.maximum, calls_per_second=seconds>0 and row.calls/seconds or 0,
                ms_per_second=seconds>0 and row.total/seconds or 0 }
        end
        table.sort(result.rows, function(a,b) if a.total_ms==b.total_ms then return a.label<b.label end return a.total_ms>b.total_ms end)
        return result
    end
    function api.Snapshot()
        local result = { clock = "os.clock", inclusive = true, fps_measurement = false, rows = {} }
        for _, row in ipairs(order) do
            result.rows[#result.rows + 1] = { label = row.label, calls = row.calls, samples = row.samples,
                sampled_ms = row.total, mean_ms = row.samples > 0 and row.total / row.samples or 0,
                maximum_ms = row.maximum, stride = row.stride }
        end
        return result
    end
    local function flush(now)
        now = tonumber(now) or 0
        if since == nil or now < since then since = now; return false end
        if now - since < 15000 then return false end
        since = now
        local parts = {}
        for _, row in ipairs(order) do
            if row.calls > 0 then
                parts[#parts + 1] = ("%s calls=%d samples=%d avg=%.3f max=%.3f"):format(
                    row.label, row.calls, row.samples, row.samples > 0 and row.total / row.samples or 0, row.maximum)
            end
            row.calls, row.samples, row.total, row.maximum = 0, 0, 0, 0
        end
        if #parts > 0 and context.Logger and type(context.Logger.Info) == "function" then
            context.Logger.Info("Performance domains sampledClockMs inclusive (not FPS): " .. table.concat(parts, "; "), "Runtime")
        end
        return #parts > 0
    end
    function api.Flush(now)
        now = tonumber(now) or 0
        last_now = now
        if capture and not capture.complete then
            capture.started_ms = capture.started_ms or now
            if now < capture.started_ms or now - capture.started_ms >= capture.duration_ms then capture.complete = true end
        end
        local captured = capture_row("profiler.flush")
        if not captured then return flush(now) end
        captured.calls = captured.calls + 1
        local began = clock()
        local result = flush(now)
        capture_finish(captured, began, clock())
        return result
    end
    function api.Stop() active = false; if capture then capture.complete = true end end
    return api
end

-- Foreign Feature userdata exposes methods that are illegal for its actual type.
-- A C++ parameter-type exception is not recoverable by Lua pcall. GetType is
-- therefore the FIRST host call; method presence is never capability evidence.
local function create_foreign_features(enumeration)
    local api = {}
    local capabilities = {
        Button = {}, Custom = {}, InputColor3 = {}, InputColor4 = {},
        Toggle = { toggle = true },
        SliderIntToggle = { toggle = true, integer = true },
        SliderFloatToggle = { toggle = true, float = true },
        Combo = { list = true }, ComboToggles = { list = true, list_toggles = true },
        List = { list = true }, ListWithInfo = { list = true },
        InputInt = { integer = true }, SliderInt = { integer = true },
        InputFloat = { float = true }, SliderFloat = { float = true },
        InputText = { text = true },
    }
    function api.Describe(feature)
        if feature == nil or type(feature.GetType) ~= "function" then
            return nil, "Feature.GetType is unavailable"
        end
        local ok, actual = pcall(feature.GetType, feature)
        if not ok or actual == nil then return nil, "Feature.GetType failed" end
        for name, supported in pairs(capabilities) do
            if enumeration and enumeration[name] ~= nil and actual == enumeration[name] then
                local result = { type_name = name, type_id = actual }
                for capability, enabled in pairs(supported) do result[capability] = enabled end
                return result
            end
        end
        return nil, "Unknown Feature.GetType; typed access refused"
    end
    function api.Supports(feature, capability)
        local descriptor, reason = api.Describe(feature)
        if not descriptor then return false, reason end
        if descriptor[capability] ~= true then
            return false, descriptor.type_name .. " does not support " .. tostring(capability)
        end
        return true, descriptor
    end
    return api
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.Raw) ~= "table" or type(context.Logger) ~= "table" then
        error("bridges.cherax requires injected Raw and Logger services")
    end

    local raw = context.Raw
    service = {}
    local performance = create_performance(context)
    context.Performance = performance
    context.CScript.Performance = performance
    context.CScript.ForeignFeatures = create_foreign_features(raw.eFeatureType or eFeatureType)

    function service.Get(name)
        return raw[tostring(name)]
    end

    function service.Available(name, method)
        local api = raw[tostring(name)]
        if method == nil then return api ~= nil end
        return api ~= nil and type(api[tostring(method)]) == "function"
    end

    function service.Call(name, method, ...)
        local api = raw[tostring(name)]
        local fn = api and api[tostring(method)]
        if type(fn) ~= "function" then
            return false, ("Cherax API unavailable: %s.%s"):format(tostring(name), tostring(method))
        end
        return pcall(fn, ...)
    end

    function service.Hash(value)
        local utils = raw.Utils
        if not utils or type(utils.Joaat) ~= "function" then return nil, "Utils.Joaat is unavailable" end
        local ok, hash = pcall(utils.Joaat, tostring(value))
        if not ok then return nil, tostring(hash) end
        return hash
    end

    function service.Toast(message, duration, title)
        local gui = raw.GUI
        local toast_pos = raw.eToastPos
        if not gui or type(gui.AddToast) ~= "function" or not toast_pos or toast_pos.TOP_RIGHT == nil then
            return false, "GUI.AddToast is unavailable"
        end
        local copy = context.Core and context.Core.PresentationCopy
        if copy then message = copy.Message(message) end
        local ok, err = pcall(gui.AddToast, "CScript", tostring(message), duration or 4500, toast_pos.TOP_RIGHT)
        return ok, ok and nil or tostring(err)
    end

    function service.MenuRoot()
        local file_mgr = raw.FileMgr
        if not file_mgr or type(file_mgr.GetMenuRootPath) ~= "function" then return nil end
        local ok, path = pcall(file_mgr.GetMenuRootPath)
        if not ok or type(path) ~= "string" or path == "" then return nil end
        return path
    end

    function service.FileExists(path)
        local file_mgr = raw.FileMgr
        if not file_mgr or type(file_mgr.DoesFileExist) ~= "function" then return false end
        local ok, exists = pcall(file_mgr.DoesFileExist, path)
        return ok and exists == true
    end

    function service.ReadFile(path)
        local file_mgr = raw.FileMgr
        if not file_mgr or type(file_mgr.ReadFileContent) ~= "function" then
            return nil, "FileMgr.ReadFileContent is unavailable"
        end
        if type(file_mgr.DoesFileExist) == "function" then
            local exists_ok, exists = pcall(file_mgr.DoesFileExist, path)
            if not exists_ok then return nil, tostring(exists) end
            if not exists then return nil, "file does not exist" end
        end
        local ok, content = pcall(file_mgr.ReadFileContent, path)
        if not ok then return nil, tostring(content) end
        if type(content) ~= "string" then return nil, "file content is not a string" end
        return content
    end

    function service.WriteFile(path, content, append)
        local file_mgr = raw.FileMgr
        if not file_mgr or type(file_mgr.WriteFileContent) ~= "function" then
            return false, "FileMgr.WriteFileContent is unavailable"
        end
        local ok, result = pcall(file_mgr.WriteFileContent, path, tostring(content), append == true)
        if not ok then return false, tostring(result) end
        return result ~= false, result == false and "FileMgr rejected the write" or nil
    end

    context.Cherax = service
    context.Bridges.Cherax = service
    context.CScript.Bridges.Cherax = service
end

function Module.Start() end
function Module.Stop() end

function Module.Restore(context)
    if context and context.Performance then context.Performance.Stop(); context.Performance = nil end
    if context and context.CScript then context.CScript.Performance = nil; context.CScript.ForeignFeatures = nil end
    if context and context.Cherax == service then context.Cherax = nil end
    if context and context.Bridges and context.Bridges.Cherax == service then context.Bridges.Cherax = nil end
    if context and context.CScript and context.CScript.Bridges
        and context.CScript.Bridges.Cherax == service then context.CScript.Bridges.Cherax = nil end
end

return Module
