-- Stable Cherax feature resolution and owner-scoped feature registration.
local Module = { Name = "bridges.features", MigrationPhase = "17.75" }

local service

local function require_owner(owner)
    if type(owner) ~= "string" or owner == "" then error("feature owner must be a non-empty string", 3) end
    return owner
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.Cherax) ~= "table" or type(context.Logger) ~= "table" then
        error("bridges.features requires injected Cherax and Logger services")
    end

    local manager = context.Cherax.Get("FeatureMgr")
    local registry = {}
    local owners = {}
    local owner_order = {}
    local live_registry
    local live_registry_error
    local builtin_cache = {}
    local builtin_audited = {}
    local owned_hashes = {}
    service = {}

    local function trace(label)
        local runtime = context.CScript and context.CScript.Runtime
        if runtime and type(runtime.RecordApiCall) == "function" then runtime.RecordApiCall(label) end
    end

    local function normalized(value)
        return tostring(value or ""):lower():gsub("[^%w]+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    end

    local function feature_value(feature, method, field, ...)
        if not feature then return nil end
        local foreign=context.CScript and context.CScript.ForeignFeatures
        if method~="GetType" and (not foreign or not foreign.Describe(feature)) then return nil end
        local arguments = { ... }
        local ok, value = pcall(function()
            if type(feature[method]) == "function" then
                return feature[method](feature, table.unpack(arguments))
            end
            return feature[field]
        end)
        return ok and value or nil
    end

    local function feature_info(feature, table_hash)
        local foreign=context.CScript and context.CScript.ForeignFeatures
        if not foreign or not foreign.Describe(feature) then return nil end
        local hash = tonumber(feature_value(feature, "GetHash", "Hash")) or tonumber(table_hash) or 0
        local name = tostring(feature_value(feature, "GetName", "Name", false) or "")
        local feature_type = feature_value(feature, "GetType", "Type")
        return {
            feature = feature,
            hash = hash,
            name = name,
            normalized = normalized(name),
            type = feature_type,
        }
    end

    local function is_usable_toggle(info, excluded)
        if not info or not info.feature or info.name == "" then
            return false
        end

        if type(excluded) == "function" and excluded(info.feature) then
            return false
        end

        local foreign=context.CScript and context.CScript.ForeignFeatures
        return foreign~=nil and foreign.Supports(info.feature,"toggle")==true
    end

    local function normalize_token_word(word)
        word = normalized(word)

        if #word > 3
            and word:sub(-1) == "s" then

            word = word:sub(1, -2)
        end

        return word
    end


    local function contains_token(text, token)
        text = normalized(text)
        token = normalize_token_word(token)

        if text == ""
            or token == "" then
            return false
        end

        for word in text:gmatch("%w+") do
            if normalize_token_word(word) == token then
                return true
            end
        end

        return false
    end


    local function matches_token_sets(info, token_sets)
        for _, tokens in ipairs(token_sets or {}) do
            local matches = true

            for _, token in ipairs(tokens) do
                if not contains_token(
                    info.normalized,
                    token
                ) then
                    matches = false
                    break
                end
            end

            if matches then
                return true
            end
        end

        return false
    end


    local function matches_any_token(info, tokens)
        for _, token in ipairs(tokens or {}) do
            if contains_token(
                info.normalized,
                token
            ) then
                return true
            end
        end

        return false
    end

    function service.InvalidateLiveRegistry()
        live_registry = nil
        live_registry_error = nil
        builtin_cache, builtin_audited = {}, {}
        return true
    end

    local function get_live_registry()
        if live_registry then return live_registry end
        if live_registry_error then return nil, live_registry_error end
        if not manager or type(manager.GetAllFeatures) ~= "function" then
            live_registry_error = "FeatureMgr.GetAllFeatures is unavailable"
            return nil, live_registry_error
        end
        local ok, features = pcall(manager.GetAllFeatures)
        if not ok or (type(features) ~= "table" and type(features) ~= "userdata") then
            return nil, ok and "GetAllFeatures returned no iterable collection" or tostring(features)
        end
        -- Cherax's live host collections were observed as iterable userdata.
        -- A failed/oversized enumeration must not authorize a partial match.
        local snapshot, seen = {}, {}
        local iterated, failure = pcall(function()
            local count = 0
            for table_hash, feature in pairs(features) do
                count = count + 1
                if count > 32768 then error("feature registry exceeds bounded scan") end
                if feature ~= nil then
                    local info = feature_info(feature, table_hash)
                    if info and info.hash ~= 0 and not seen[info.hash] then
                        seen[info.hash] = true
                        snapshot[#snapshot + 1] = info
                    end
                end
            end
        end)
        if not iterated then return nil, tostring(failure) end
        table.sort(snapshot, function(a, b)
            if a.name == b.name then return a.hash < b.hash end
            return a.name < b.name
        end)
        live_registry = snapshot
        context.Logger.Info(
            ("Captured live Cherax feature registry (%d entries)."):format(#snapshot),
            "Features"
        )
        return live_registry
    end

    local function audit_builtin(key, spec, excluded, token_matches)
        if builtin_audited[key] then return end
        builtin_audited[key] = true
        local snapshot, err = get_live_registry()
        if not snapshot then
            context.Logger.Warn(("Builtin audit key=%s failed: %s"):format(tostring(key), tostring(err)), "Features")
            return
        end
        local candidates = {}
        for _, info in ipairs(snapshot) do
            if is_usable_toggle(info, excluded)
                and (matches_token_sets(info, spec.token_sets) or matches_any_token(info, spec.audit_tokens)) then
                candidates[#candidates + 1] = info
            end
        end
        context.Logger.Info(("Builtin audit key=%s candidates=%d tokenMatches=%d"):format(
            tostring(key), #candidates, #(token_matches or {})), "Features")
        for index = 1, math.min(#candidates, 24) do
            local info = candidates[index]
            context.Logger.Info(("Builtin candidate key=%s hash=0x%08X name=%s type=%s"):format(
                tostring(key), info.hash & 0xFFFFFFFF, info.name, tostring(info.type)), "Features")
        end
        if #candidates > 24 then
            context.Logger.Info(("Builtin audit key=%s omitted=%d additional candidates"):format(
                tostring(key), #candidates - 24), "Features")
        end
    end

    local function owner_record(owner)
        local record = owners[owner]
        if not record then
            record = { entries = {}, order = {} }
            owners[owner] = record
            owner_order[#owner_order + 1] = owner
        end
        return record
    end

    function service.Hash(key, prefix)
        return context.Cherax.Hash((prefix or "JinxRebound_") .. tostring(key))
    end

    function service.Resolve(id_or_name, index)
        trace("Feature.Resolve")
        if not manager then return nil end
        if type(id_or_name) == "string" and registry[id_or_name] then
            id_or_name = registry[id_or_name].hash
        end
        if type(id_or_name) == "number" and type(manager.GetFeature) == "function" then
            local ok, feature
            if index == nil then
                ok, feature = pcall(manager.GetFeature, id_or_name)
            else
                ok, feature = pcall(manager.GetFeature, id_or_name, index)
            end
            if ok then return feature end
        elseif type(id_or_name) == "string" and type(manager.GetFeatureByName) == "function" then
            local ok, feature
            if index == nil then
                ok, feature = pcall(manager.GetFeatureByName, id_or_name)
            else
                ok, feature = pcall(manager.GetFeatureByName, id_or_name, index)
            end
            if ok then return feature end
        end
        return nil
    end

    -- Built-ins resolve by validated numeric identity first. Exact-name and live
    -- token fallback are opt-in only because other Lua scripts can register
    -- identical display names in the shared FeatureMgr.
    function service.ResolveBuiltin(key, spec, options)
        key = tostring(key)
        spec = type(spec) == "table" and spec or {}
        options = type(options) == "table" and options or {}

        local validated_only =
            options.validated_only == true

        local allow_unvalidated =
            options.allow_unvalidated == true

        local resolution_mode =
            validated_only
            and "validated-only"
            or (
                allow_unvalidated
                and "allow-unvalidated"
                or "validated"
            )

        local cached =
            builtin_cache[key]

        if cached ~= nil
            and cached.resolution_mode == resolution_mode then

            return cached.unresolved ~= true and cached.feature or nil, cached
        end

        if cached ~= nil then
            builtin_cache[key] = nil
            builtin_audited[key] = nil
        end
        trace("Feature.ResolveBuiltin")

        local exact = {}
        for _, name in ipairs(spec.exact_names or {}) do exact[normalized(name)] = true end
        local function accept(feature, hash, strategy)
            local info =
                feature_info(
                    feature,
                    hash
                )

            if not is_usable_toggle(
                info,
                options.exclude
            ) then
                return nil
            end

            local exact_match =
                exact[info.normalized] == true

            local semantic_match =
                matches_token_sets(
                    info,
                    spec.token_sets
                )

            if strategy == "exact-name"
                or strategy == "exact-registry" then

                if not exact_match then
                    return nil
                end

            elseif strategy == "validated-hash" then

                -- A historical/current hash alone is not enough to prove identity.
                -- Permit a renamed feature, but require its name to still describe
                -- the expected feature.
                if not exact_match
                    and not semantic_match then

                    return nil
                end

            elseif strategy == "token" then

                if not semantic_match then
                    return nil
                end

            else
                return nil
            end

            info.strategy = strategy
            info.resolution_mode = resolution_mode
            builtin_cache[key] = info

            context.Logger.Info(
                (
                    "Builtin resolved key=%s "
                    .. "strategy=%s "
                    .. "hash=0x%08X "
                    .. "name=%s "
                    .. "type=%s"
                ):format(
                    key,
                    strategy,
                    info.hash & 0xFFFFFFFF,
                    info.name,
                    tostring(info.type)
                ),
                "Features"
            )

            return info.feature, info
        end

        -- A validated numeric identity is the only safe default. Different Lua
        -- scripts can expose identical display names through the shared manager.
        if manager
            and type(manager.GetFeature) == "function" then

            for _, hash in ipairs(
                spec.validated_hashes or {}
            ) do
                local ok, feature =
                    pcall(
                        manager.GetFeature,
                        hash
                    )

                if ok and feature then
                    local resolved, info =
                        accept(
                            feature,
                            hash,
                            "validated-hash"
                        )

                    if resolved then
                        return resolved, info
                    end
                end
            end
        end

        -- Never silently adopt a feature from another loaded Lua merely because
        -- its display name or tokens match a Cherax feature specification.
        if validated_only
            or not allow_unvalidated then

            local failure = {
                unresolved = true,
                resolution_mode = resolution_mode,

                strategy =
                    validated_only
                    and "validated-only-unresolved"
                    or "validated-unresolved",

                reason =
                    validated_only
                    and "no validated Cherax built-in hash matched"
                    or (
                        "no validated Cherax built-in hash matched; "
                        .. "unvalidated name/token fallback disabled"
                    ),

                token_matches = 0,
            }

            builtin_cache[key] =
                failure

            context.Logger.WarnOnce(
                "builtin_unresolved_" .. key,
                (
                    "Builtin unresolved key=%s "
                    .. "reason=%s"
                ):format(
                    key,
                    failure.reason
                ),
                "Features"
            )

            return nil, failure
        end

        -- Never accept the first GetFeatureByName result: distinct installed
        -- scripts can expose identical labels. Known hashes are checked first;
        -- all other resolutions require one unique complete-registry match.
        local snapshot, snapshot_error = get_live_registry()
        local token_matches, exact_matches = {}, {}
        if snapshot then
            for _, info in ipairs(snapshot) do
                if is_usable_toggle(info, options.exclude) then
                    if exact[info.normalized] then exact_matches[#exact_matches + 1] = info end
                    if matches_token_sets(info, spec.token_sets) then token_matches[#token_matches + 1] = info end
                end
            end
        end
        if #exact_matches == 1 then
            return accept(exact_matches[1].feature, exact_matches[1].hash, "exact-registry")
        end
        if #exact_matches > 1 then
            local failure = { unresolved = true, strategy = "ambiguous-exact-name", resolution_mode = resolution_mode,
                reason = "multiple installed controls have the same name", token_matches = #token_matches }
            builtin_cache[key] = failure
            return nil, failure
        end
        audit_builtin(key, spec, options.exclude, token_matches)
        if #token_matches == 1 then
            return accept(token_matches[1].feature, token_matches[1].hash, "token")
        end

        local detail = snapshot_error or (#token_matches > 1 and "ambiguous token match" or "no validated match")
        local failure = {
            unresolved = true,
            resolution_mode = resolution_mode,
            strategy = "unresolved",
            reason = detail,
            token_matches = #token_matches,
        }
        builtin_cache[key] = failure
        context.Logger.WarnOnce("builtin_unresolved_" .. key,
            ("Builtin unresolved key=%s reason=%s"):format(key, detail), "Features")
        return nil, failure
    end

    function service.InvalidateBuiltin(key)
        key = tostring(key)
        builtin_cache[key] = nil
        builtin_audited[key] = nil
        return true
    end

    function service.BuiltinStatus(key)
        local info = builtin_cache[tostring(key)]
        if not info then return { state = "NOT_PROBED" } end
        if info.unresolved == true then
            return { state = "UNAVAILABLE_CURRENT_BUILD", strategy = info.strategy, reason = info.reason }
        end
        return {
            state = "AVAILABLE",
            hash = info.hash,
            name = info.name,
            type = info.type,
            strategy = info.strategy,
        }
    end

    function service.LiveRegistryCount()
        local snapshot = get_live_registry()
        return snapshot and #snapshot or 0
    end

    function service.RegisterExisting(key, hash, owner)
        if type(key) ~= "string" or key == "" or type(hash) ~= "number" then
            return false, "existing feature requires string key and numeric hash"
        end
        if registry[key] then return false, "feature key already registered: " .. key end
        registry[key] = { hash = hash, owner = owner or "compat", existing = true }
        owned_hashes[hash]=true
        return true
    end

    function service.Add(owner, spec)
        owner = require_owner(owner)
        if type(spec) ~= "table" or type(spec.key) ~= "string" or spec.key == "" then
            error("feature spec requires a stable key", 2)
        end
        if registry[spec.key] then return nil, "feature key already registered: " .. spec.key end
        if not manager then return nil, "FeatureMgr is unavailable" end
        local hash = spec.hash
        if type(hash) ~= "number" then
            hash = service.Hash(spec.key, spec.prefix)
            if type(hash) ~= "number" then return nil, "unable to hash feature key: " .. spec.key end
        end
        local method = spec.player and "AddPlayerFeature" or "AddFeature"
        local add = manager[method]
        if type(add) ~= "function" then return nil, "FeatureMgr." .. method .. " is unavailable" end
        local copy = context.Core and context.Core.PresentationCopy
        local description = copy and copy.Description(spec.name, spec.description) or spec.description or ""
        local ok, result = pcall(add, hash, spec.name, spec.type, description,
            spec.callback, spec.nativeThreadExecution ~= false, spec.forceQueue == true)
        if not ok then return nil, tostring(result) end
        local entry = { key = spec.key, hash = hash, owner = owner, player = spec.player == true, result = result }
        registry[spec.key] = entry
        owned_hashes[hash]=true
        local record = owner_record(owner)
        record.entries[spec.key] = entry
        record.order[#record.order + 1] = spec.key
        return result, hash
    end

    local function legal_toggle(hash,index)
        if not owned_hashes[hash] then
            local foreign=context.CScript and context.CScript.ForeignFeatures
            if not foreign or not manager or type(manager.GetFeature)~="function" then
                return false,"Type-safe foreign feature access unavailable"
            end
            local got,feature
            if index==nil then got,feature=pcall(manager.GetFeature,hash)
            else got,feature=pcall(manager.GetFeature,hash,index) end
            if not got or not feature or not foreign.Supports(feature,"toggle") then
                return false,"Foreign feature type does not support toggles"
            end
        end
        return true
    end
    local function read_toggle_state(hash, index)
        local allowed,why=legal_toggle(hash,index)
        if not allowed then return false,nil,why end
        if not manager
            or type(manager.IsFeatureToggled) ~= "function" then

            return false,
                nil,
                "FeatureMgr.IsFeatureToggled is unavailable"
        end

        local ok, value

        if index == nil then
            ok, value =
                pcall(
                    manager.IsFeatureToggled,
                    hash
                )
        else
            ok, value =
                pcall(
                    manager.IsFeatureToggled,
                    hash,
                    index
                )
        end

        if not ok then
            return false,
                nil,
                tostring(value)
        end

        if type(value) ~= "boolean" then
            return false,
                nil,
                "FeatureMgr.IsFeatureToggled returned a non-boolean value"
        end

        return true, value
    end

    function service.IsToggled(id_or_name, index)
        local hash = id_or_name

        if type(id_or_name) == "string"
            and registry[id_or_name] then

            hash =
                registry[id_or_name].hash
        end

        if type(hash) ~= "number" then
            return false
        end

        local ok, toggled =
            read_toggle_state(
                hash,
                index
            )

        return ok
            and toggled == true
    end

    function service.SetToggled(
        id_or_name,
        enabled,
        index
    )
        local hash = id_or_name

        if type(id_or_name) == "string"
            and registry[id_or_name] then

            hash =
                registry[id_or_name].hash
        end

        if type(hash) ~= "number"
            or not manager
            or type(manager.ToggleFeature) ~= "function" then

            return false,
                "FeatureMgr.ToggleFeature is unavailable"
        end

        local wanted =
            enabled == true

        local read_ok, current, read_error =
            read_toggle_state(
                hash,
                index
            )

        if not read_ok then
            return false,
                read_error
        end

        if current == wanted then
            return true, false
        end

        local allowed,why=legal_toggle(hash,index)
        if not allowed then return false,why end

        local ok, err

        if index == nil then
            ok, err =
                pcall(
                    manager.ToggleFeature,
                    hash
                )
        else
            ok, err =
                pcall(
                    manager.ToggleFeature,
                    hash,
                    index
                )
        end

        if not ok then
            return false,
                tostring(err)
        end

        local verify_ok, observed, verify_error =
            read_toggle_state(
                hash,
                index
            )

        if not verify_ok then
            return false,
                verify_error
        end

        if observed ~= wanted then
            return false,
                "feature toggle did not reach requested state"
        end

        return true, true
    end

    function service.RemoveOwner(owner)
        owner = tostring(owner)

        local record =
            owners[owner]

        if not record then
            return true
        end

        local success = true

        for index = #record.order, 1, -1 do
            local key =
                record.order[index]

            local entry =
                record.entries[key]

            if entry then
                local method =
                    entry.player
                    and "RemovePlayerFeature"
                    or "RemoveFeature"

                local removed = false

                if manager
                    and type(manager[method]) == "function" then

                    local ok, result =
                        pcall(
                            manager[method],
                            entry.hash
                        )

                    removed =
                        ok
                        and result ~= false
                end

                if removed then
                    owned_hashes[entry.hash] = nil
                    registry[key] = nil
                    record.entries[key] = nil
                else
                    success = false

                    context.Logger.Warn(
                        (
                            "Could not remove owned feature "
                            .. "%s/%s hash=0x%08X"
                        ):format(
                            owner,
                            key,
                            entry.hash & 0xFFFFFFFF
                        ),
                        "Features"
                    )
                end
            end
        end

        if next(record.entries) == nil then
            owners[owner] = nil
        end

        return success
    end

    function service.RestoreAll()
        local success = true

        for index = #owner_order, 1, -1 do
            local owner =
                owner_order[index]

            if owners[owner]
                and not service.RemoveOwner(owner) then

                success = false
            end
        end

        local remaining = {}

        for _, owner in ipairs(owner_order) do
            if owners[owner] then
                remaining[#remaining + 1] =
                    owner
            end
        end

        owner_order = remaining

        return success
    end

    context.Features = service
    context.Bridges.Features = service
    context.CScript.Bridges.Features = service
end

function Module.Start() end

function Module.Stop() end

function Module.Restore(context)
    if service then service.RestoreAll() end
    if context and context.Features == service then context.Features = nil end
    if context and context.Bridges and context.Bridges.Features == service then
        context.Bridges.Features = nil
    end
    if context and context.CScript and context.CScript.Bridges
        and context.CScript.Bridges.Features == service then

        context.CScript.Bridges.Features = nil
    end
end

return Module
