-- Enhanced audio limiter patches, applied and restored as one transaction.
-- Reference: illusionyy/Windows-Game-Patches, source/GTA5_Enhanced.Patches/dllmain.cpp
-- blob 689f8db9f014652eee9f1d678bf046aedc770564, reviewed 2026-09-22.
-- The separate engine FPS ceiling remains in place.
local Module = { Name = "bridges.fps_limiter", MigrationPhase = "17.75" }
local service, module_context
local GAME = "GTA5_Enhanced.exe"
local MAX_ADDRESS = 0x00007FFFFFFFFFFF
local SPECS = {
    { key="async_audio", pattern="48 89 D9 89 FA E8 ? ? ? ? 80 3D ? ? ? ? 00 75 ? E8 ? ? ? ?", kind="rip_bool", offset=10 },
    { key="audio_timeout", pattern="81 C3 E8 03 00 00 39 D7 0F 94 C1 39 D8", patched="81 C3 00 00 00 00 39 D7 0F 94 C1 39 D8", kind="immediate", offset=2, bytes={0,0,0,0} },
    { key="audio_limiter_call", pattern="48 8B 0D ? ? ? ? BA FF FF FF FF E8 ? ? ? ? 0F B6", patched="48 8B 0D ? ? ? ? BA FF FF FF FF 90 90 90 90 90 0F B6", kind="call", offset=12, bytes={0x90,0x90,0x90,0x90,0x90} },
}
local function integer(v, lo, hi) return type(v)=="number" and v==v and v%1==0 and v>=lo and v<=hi end
local function address(v) return integer(v,0x10000,MAX_ADDRESS) end
local function equal(a,b)
    if #a~=#b then return false end
    for i=1,#a do if a[i]~=b[i] then return false end end
    return true
end
function Module.Init(context)
    module_context=context
    local raw=context.Cherax.Get("Memory")
    local state={phase="OFF",detail="Disabled. Enhanced audio limiters only; remaining engine ceiling is not removed.",
        requested=false,alive=true,busy=false,leases={},components={},active=false,image=nil}
    for _,s in ipairs(SPECS) do state.components[s.key]="NOT_PROBED" end
    local function read(a,n)
        if not address(a) or not address(a+n-1) then error("Invalid memory span",0) end
        local b={}
        for i=1,n do
            local v=raw.ReadUByte(a+i-1)
            if not integer(v,0,255) then error("Invalid byte read",0) end
            b[i]=v
        end
        return b
    end
    local function uint(a,n)
        local b=read(a,n);local value=0
        for i=n,1,-1 do value=(value<<8)|b[i] end
        return value
    end
    local function relative(a) local d=uint(a,4); return d>=0x80000000 and d-0x100000000 or d end
    local function writes_allowed()
        local r=context.CScript and context.CScript.Runtime
        if r and type(r.RuntimeWriteAllowed)=="function" then
            local ok,value=pcall(r.RuntimeWriteAllowed,"World");return ok and value==true
        end
        return true
    end
    local function inspect_image()
        for _,name in ipairs({"Scan","ReadUByte","WriteUByte","GetBaseAddress"}) do
            if not raw or type(raw[name])~="function" then error("Memory."..name.." unavailable",0) end
        end
        local base=raw.GetBaseAddress(GAME)
        if not address(base) or uint(base,2)~=0x5A4D then error("Enhanced PE image unavailable",0) end
        local pe=base+uint(base+0x3C,4)
        if pe<base+0x40 or pe>base+0x100000 or uint(pe,4)~=0x4550 or uint(pe+4,2)~=0x8664 then error("Enhanced PE64 header mismatch",0) end
        local count,opt=uint(pe+6,2),uint(pe+20,2)
        if not integer(count,1,96) or not integer(opt,0x70,0x1000) or uint(pe+24,2)~=0x20B then error("Enhanced PE section layout mismatch",0) end
        local size=uint(pe+24+56,4)
        if not integer(size,0x100000,0x7FFFFFFF) or not address(base+size-1) then error("Enhanced PE image size invalid",0) end
        local sections={}
        for i=0,count-1 do
            local h=pe+24+opt+i*40
            local start,length,flags=uint(h+12,4),uint(h+8,4),uint(h+36,4)
            if length>0 and start<size and start+length<=size then
