        return {base=base,pe=pe,size=size,sections=sections,timestamp=uint(pe+8,4)}
    end
    local function in_section(a,n,kind)
        if not address(a) then return false end
        for _,s in ipairs(state.image.sections) do
            if a>=s.start and a+n<=s.finish then
