    local function same_context(lease)
        if raw.GetBaseAddress(GAME)~=state.image.base then return false end
        if uint(state.image.base,2)~=0x5A4D or state.image.base+uint(state.image.base+0x3C,4)~=state.image.pe
            or uint(state.image.pe,4)~=0x4550 or uint(state.image.pe+8,4)~=state.image.timestamp
            or uint(state.image.pe+24+56,4)~=state.image.size then return false end
        for i,b in ipairs(lease.surrounding) do
            local a=lease.start+i-1
            if a<lease.address or a>=lease.address+#lease.original then
                if uint(a,1)~=b then return false end
            end
