        return true
    end
    local function restore_one(lease)
        if not lease.owned then return true end
        if not same_context(lease) then return false,"instruction context changed externally" end
        local current=read(lease.address,#lease.original)
        -- Whole-span preflight prevents partly restoring someone else's patch.
        for i,b in ipairs(current) do
