["CScript/bridges/memory.lua"]=[====[
-- Owner-scoped memory writes with one-time snapshots and conflict detection.
-- Existing compatibility and vehicle writes are deliberately not routed here.
local Module = { Name = "bridges.memory", MigrationPhase = "17.75" }

local service

local TYPE_ALIASES = {
    byte = "Byte", int8 = "Byte",
    ubyte = "UByte", uint8 = "UByte",
    short = "Short", int16 = "Short",
    ushort = "UShort", uint16 = "UShort",
    int = "Int", int32 = "Int",
    uint = "UInt", uint32 = "UInt",
    long = "Long", int64 = "Long", pointer = "Long",
    float = "Float", number = "Float",
    string = "String",
    v3 = "V3", vector3 = "V3",
}

local function required_string(value, label)
    if type(value) ~= "string" or value == "" then error(label .. " must be a non-empty string", 3) end
    return value
end

local function normal_type(value_type)
    local normalized = TYPE_ALIASES[tostring(value_type or ""):lower()]
    if not normalized then return nil, "unsupported memory value type: " .. tostring(value_type) end
    return normalized
end

local OWNERSHIP = {
    UNTOUCHED = "UNTOUCHED",
    OBSERVED = "OBSERVED",
    CSCRIPT_OWNED = "CSCRIPT_OWNED",
    EXTERNALLY_MODIFIED = "EXTERNALLY_MODIFIED",
    RESTORED = "RESTORED",
    UNAVAILABLE = "UNAVAILABLE",
}

local function owner_domain(owner)
    local prefix = tostring(owner or ""):match("^([^.]+)") or ""
    if prefix:match("^vehicle") then return "Vehicle" end
    if prefix:match("^weapons?") then return "Weapons" end
    if prefix:match("^player") then return "Player" end
    if prefix:match("^world") then return "World" end
    return "Other"
end

local function values_equal(left, right, value_type)
    if left == right then return true end
    if value_type == "Float" and type(left) == "number" and type(right) == "number" then
        local tolerance = math.max(0.00001, math.abs(right) * 0.000001)
        return math.abs(left - right) <= tolerance
    end
    if type(left) == "table" and type(right) == "table" then
        return left.x == right.x and left.y == right.y and left.z == right.z
    end
    return false
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.Cherax) ~= "table" or type(context.Logger) ~= "table" then
        error("bridges.memory requires injected Cherax and Logger services")
    end

    local raw = context.Cherax.Get("Memory")
    if type(raw) ~= "table" then error("Cherax Memory API is unavailable") end

    local owners = {}
    local address_owners = {}
    local owner_order = {}
    local blocked = {}
    local transitions = {}
    service = {}

    local function trace(label, amount)
        local runtime = context.CScript and context.CScript.Runtime
        if runtime and type(runtime.RecordInteropEvent) == "function" then
            runtime.RecordInteropEvent(label, amount)
        end
    end

    local function writes_allowed(owner)
        local runtime = context.CScript and context.CScript.Runtime
        if runtime and type(runtime.RuntimeWriteAllowed) == "function" then
            return runtime.RuntimeWriteAllowed(owner_domain(owner))
        end
        return true
    end

    local function transition(from_state, to_state)
        local key = tostring(from_state or OWNERSHIP.UNTOUCHED) .. "->" .. tostring(to_state)
        transitions[key] = (transitions[key] or 0) + 1
        trace("Ownership." .. key)
    end

    local function methods(value_type)
        local suffix, err = normal_type(value_type)
        if not suffix then return nil, nil, nil, err end
        local reader = raw["Read" .. suffix]
        local writer = raw["Write" .. suffix]
        if type(reader) ~= "function" or type(writer) ~= "function" then
            return nil, nil, nil, "Cherax Memory read/write unavailable for " .. suffix
        end
        return reader, writer, suffix
    end

    -- A UInt mask narrows authority within an exclusively owned address. It
    -- never permits two owners of the same word. Compare only owned bits and
    -- merge each write/restore with a fresh word so game-owned bits survive.
    local function entry_equal(entry, left, right)
        if entry.mask then
            return type(left)=="number" and type(right)=="number"
                and left>=0 and left<=0xFFFFFFFF and right>=0 and right<=0xFFFFFFFF
                and left%1==0 and right%1==0 and (left & entry.mask)==(right & entry.mask)
        end
        return values_equal(left,right,entry.valueType)
    end

    local function address_token(address)
        if type(address) ~= "number" or address == 0 then return nil, "memory address must be a non-zero number" end
        return tostring(address)
    end

    local function owner_record(owner, create)
        local record = owners[owner]
        if not record and create then
            record = { entries = {}, order = {} }
            owners[owner] = record
            owner_order[#owner_order + 1] = owner
        end
        return record
    end

    local function release_entry(entry, final_state, block_reason)
        if not entry then return end
        local owned = owners[entry.owner]
        local previous = entry.state or OWNERSHIP.OBSERVED
        entry.state = final_state
        transition(previous, final_state)
        if block_reason then
            blocked[entry.owner] = blocked[entry.owner] or {}
            blocked[entry.owner][entry.key] = {
                state = final_state,
                reason = tostring(block_reason),
                domain = owner_domain(entry.owner),
            }
        end
        if owned then
            owned.entries[entry.key] = nil
            if next(owned.entries) == nil then owners[entry.owner] = nil end
        end
        if address_owners[entry.token] == entry then address_owners[entry.token] = nil end
    end

    -- Optional identity proof supplied by a domain owner. A failed read is not
    -- proof that an object was replaced: retain its baseline for a later retry.
    local function check_identity(entry)
        if type(entry.guard) ~= "function" then return true end
        local called, same, detail = pcall(entry.guard)
        if called and same == true then return true end
        local reason = tostring(detail or (called and "object identity unavailable" or same))
        if called and same == false then
            reason = "object identity changed; old baseline not applied to replacement"
            release_entry(entry, OWNERSHIP.EXTERNALLY_MODIFIED, reason)
            context.Logger.WarnOnce("memory:identity:" .. entry.owner .. ":" .. entry.key, reason, "memory")
            return false, reason, "IDENTITY_CHANGED"
        end
        return false, reason, "UNAVAILABLE"
    end

    local function detect_external(entry)
        local same, reason = check_identity(entry)
        if not same then return false, reason end
        local ok, observed = pcall(entry.reader, entry.address)
        if not ok then return false, tostring(observed) end
        if entry_equal(entry, observed, entry.current) then return true, nil, observed end
        local reason = ("%s/%s changed outside CScript; write authority suspended until revalidation")
            :format(entry.owner, entry.key)
        release_entry(entry, OWNERSHIP.EXTERNALLY_MODIFIED, reason)
        context.Logger.WarnOnce("memory:external:" .. entry.owner .. ":" .. entry.key, reason, "memory")
        return false, reason
    end

    local function acquire(owner, key, address, value_type, guard, mask)
        owner = required_string(owner, "memory owner")
        key = required_string(key, "memory key")
        local owner_blocked = blocked[owner]
        if owner_blocked and owner_blocked[key] then
            return false, owner_blocked[key].reason
        end
        local token, address_err = address_token(address)
        if not token then return false, address_err end
        local reader, writer, suffix, type_err = methods(value_type)
        if not reader then return false, type_err end
        if mask~=nil and (suffix~="UInt" or type(mask)~="number" or mask%1~=0
            or mask<=0 or mask>0xFFFFFFFF) then
            return false,"a masked lease requires a nonzero UInt mask"
        end

        local owned = owner_record(owner, false)
        local existing = owned and owned.entries[key]
        if existing then
            if existing.address ~= address or existing.valueType ~= suffix or existing.mask~=mask then
                local message = ("ownership key changed target: %s/%s"):format(owner, key)
                context.Logger.ErrorOnce("memory:key:" .. owner .. ":" .. key, message, "memory")
                return false, message
            end
            local same, reason = check_identity(existing)
            if not same then return false, reason end
            return true, existing
        end

        local address_owner = address_owners[token]
        if address_owner then
            local message = ("address %s is already owned by %s/%s; rejected %s/%s"):format(
                token, address_owner.owner, address_owner.key, owner, key)
            context.Logger.ErrorOnce("memory:conflict:" .. token, message, "memory")
            return false, message
        end

        if guard ~= nil then
            if type(guard) ~= "function" then return false, "identity guard must be a function" end
            local called, same, detail = pcall(guard)
            if not called or same ~= true then return false, tostring(detail or same or "identity guard unavailable") end
        end
        local ok, original = pcall(reader, address)
        if not ok then return false, tostring(original) end
        owned = owned or owner_record(owner, true)
        local entry = {
            owner = owner,
            key = key,
            address = address,
            token = token,
            valueType = suffix,
            reader = reader,
            writer = writer,
            guard = guard,
            mask = mask,
            original = original,
            current = original,
            state = OWNERSHIP.OBSERVED,
        }
        transition(OWNERSHIP.UNTOUCHED, OWNERSHIP.OBSERVED)
        owned.entries[key] = entry
        owned.order[#owned.order + 1] = key
        address_owners[token] = entry
        return true, entry
    end

    function service.Read(address, value_type)
        local reader, _, _, err = methods(value_type)
        if not reader then return nil, err end
        local _, address_err = address_token(address)
        if address_err then return nil, address_err end
        local ok, value = pcall(reader, address)
        if not ok then return nil, tostring(value) end
        return value
    end

    function service.Snapshot(owner, key, address, value_type, guard, mask)
        local ok, entry = acquire(owner, key, address, value_type, guard, mask)
        if not ok then return false, entry end
        return true, entry.original
    end

    -- Capture debt before invoking a host writer: some hosts can write and then
    -- throw. Never turn an accepted call or a silent no-op into verified success.
    local function write_verified(entry, value)
        if entry.mask then
            if type(value)~="number" or value%1~=0 or value<0 or value>0xFFFFFFFF then
                return false,"masked UInt request is outside its type bounds"
            end
            local unchanged, reason, observed=detect_external(entry)
            if not unchanged then return false,reason end
            value=((observed & (~entry.mask)) | (value & entry.mask)) & 0xFFFFFFFF
        end
        local previous, previous_state = entry.current, entry.state
        entry.current = value
        if entry.state ~= OWNERSHIP.CSCRIPT_OWNED then
            transition(entry.state, OWNERSHIP.CSCRIPT_OWNED)
            entry.state = OWNERSHIP.CSCRIPT_OWNED
        end
        local called, result = pcall(entry.writer, entry.address, value)
        local same, identity_reason = check_identity(entry)
        if not same then return false, identity_reason end
        local read_ok, observed = pcall(entry.reader, entry.address)
        if read_ok and entry_equal(entry, observed, previous)
            and not entry_equal(entry, observed, value) then
            entry.current = previous
            transition(entry.state, previous_state)
            entry.state = previous_state
        end
        if not called or result == false then return false, tostring(result or "host rejected write") end
        if not read_ok then return false, tostring(observed) end
        if not entry_equal(entry, observed, value) then return false, "write readback did not match requested value" end
        trace(owner_domain(entry.owner) .. ".MemoryWrite")
        return true
    end

    function service.Write(owner, key, address, value, value_type, guard, mask)
        if not writes_allowed(owner) then return false, "runtime writes are suspended for " .. owner_domain(owner) end
        local ok, entry = acquire(owner, key, address, value_type, guard, mask)
        if not ok then return false, entry end
        local unchanged, external_err = detect_external(entry)
        if not unchanged then return false, external_err end
        local wrote, err = write_verified(entry, value)
        if not wrote then return false, err end
        return true
    end

    function service.WriteIfChanged(owner, key, address, value, value_type, guard, mask)
        if not writes_allowed(owner) then return false, "runtime writes are suspended for " .. owner_domain(owner) end
        local ok, entry = acquire(owner, key, address, value_type, guard, mask)
        if not ok then return false, entry end
        local unchanged, external_err = detect_external(entry)
        if not unchanged then return false, external_err end
        if entry_equal(entry, entry.current, value) then return true, false end
        local wrote, err = write_verified(entry, value)
        if not wrote then return false, err end
        return true, true
    end

    function service.Restore(owner, key)
        owner = tostring(owner)
        key = tostring(key)
        local owned = owners[owner]
        local entry = owned and owned.entries[key]
        if not entry then return true, false end
        trace("Memory.RestoreAttempt")
        local same, reason, identity_status = check_identity(entry)
        if not same then
            if identity_status == "IDENTITY_CHANGED" then
                return true, false, OWNERSHIP.EXTERNALLY_MODIFIED, reason
            end
            return false, reason
        end
        if entry.state ~= OWNERSHIP.CSCRIPT_OWNED then
            release_entry(entry, OWNERSHIP.RESTORED)
            return true, false
        end
        -- Verify restoration by reading the value back.
        -- Keep ownership/debt on read or write failure so the next cleanup can
        -- retry. A value changed by someone else is still left untouched.
        local read_ok, observed = pcall(entry.reader, entry.address)
        if not read_ok then return false, tostring(observed) end
        if entry_equal(entry, observed, entry.original) then
            release_entry(entry, OWNERSHIP.RESTORED)
            return true, false
        end
        if not entry_equal(entry, observed, entry.current) then
            local reason = ("%s/%s changed outside CScript; restoration skipped")
                :format(entry.owner, entry.key)
            release_entry(entry, OWNERSHIP.EXTERNALLY_MODIFIED, reason)
            context.Logger.WarnOnce("memory:external:" .. entry.owner .. ":" .. entry.key, reason, "memory")
            return true, false, OWNERSHIP.EXTERNALLY_MODIFIED, reason
        end
        local restored_value=entry.original
        if entry.mask then
            restored_value=((observed & (~entry.mask)) | (entry.original & entry.mask)) & 0xFFFFFFFF
        end
        local ok, err = pcall(entry.writer, entry.address, restored_value)
        local still_same, guard_reason, guard_status = check_identity(entry)
        if not still_same then
            if guard_status == "IDENTITY_CHANGED" then
