            end
            return false, guard_reason
        end
        -- The writer can mutate memory and then fail. Only the captured original
        -- reading back on the same record settles restoration; a return value
        -- alone neither proves success nor requires another stale write.
        local verified, value = pcall(entry.reader, entry.address)
        if not verified or not entry_equal(entry, value, entry.original) then
            local reason = verified and "restore readback did not match the captured original" or tostring(value)
            context.Logger.ErrorOnce("memory:restore_readback:" .. owner .. ":" .. key, reason, "memory")
            return false, reason
