        for owner, keys in pairs(blocked) do
            if owner_domain(owner) == domain then
                for key in pairs(keys) do keys[key] = nil; cleared = cleared + 1 end
                blocked[owner] = nil
            end
        end
        trace(domain .. ".OwnershipRevalidated", math.max(1, cleared))
        return true, cleared
    end

    function service.OwnerOf(address)
        local token = type(address) == "number" and tostring(address) or nil
        local entry = token and address_owners[token]
        if not entry then return nil end
        return entry.owner, entry.key, entry.valueType
    end

    function service.Stats()
        local owner_count, write_count, external_count = 0, 0, 0
        for _, owned in pairs(owners) do
            owner_count = owner_count + 1
