-- Studio storage runs file and FeatureMgr operations on the native scheduler.
-- Rendering queues requests and reads cached state. Feature identities come from
-- Cherax configuration; direct wardrobe and garage writes are unsupported.
local Module = { Name = "bridges.studio_storage", MigrationPhase = "17.75" }
local context, service
local MAX_BYTES, MAX_FILES = 1024 * 1024, 4096
local SPECS = {
    vehicle_name = { 3385011681, "Vehicle Name", {"InputText"} },
    vehicle_save = { 3018382944, "Save Current Vehicle", {"Button"} },
    vehicle_list = { 514776905, "Saved Vehicles", {"Combo", "List", "ListWithInfo"} },
    vehicle_load = { 521937511, "Load Vehicle", {"Button"} },
    garages = { 126717055, "Garages", {"Combo", "List", "ListWithInfo"}, "A list of all owned multiplayer garages." },
    personal = { 3383393326, "Vehicles", {"Combo", "List", "ListWithInfo"}, "A list of all saved multiplayer vehicles." },
    personal_request = { 1153085963, "Request Personal Vehicle", {"Button"}, "Request a specifc selected vehicle from your garage. This might take some seconds." },
    personal_return = { 2225114950, "Put Personal Vehicle Into Garage", {"Button"}, "Cleanup your personal vehicle and put it properly back into the gargage." },
    personal_convert = { 2816017279, "Convert Current Vehicle To PV", {"Button"}, "Let's you store almost any vehicle into a garage with all its modifications" },
    personal_delete = { 105643417, "Delete Vehicle from Garage", {"Button"}, "Deletes the selected vehicle from your garage." },
    outfit_slot = { 475508446, "Saved Outfit Slot", {"InputInt", "SliderInt"} },
    outfit_name = { 856561742, "Saved Outfit Name", {"InputText"} },
    outfit_save = { 2829892050, "Save Current Outfit", {"Button"} },
}
local function copy(v, seen)
    if type(v) ~= "table" then return v end
    seen = seen or {}; if seen[v] then return seen[v] end
    local out = {}; seen[v] = out
    for k, value in pairs(v) do out[k] = copy(value, seen) end
    return out
end
local function signature(raw)
    local h = 2166136261
    for i = 1, #raw do h = ((h ~ raw:byte(i)) * 16777619) & 0xffffffff end
    return ("%08x:%d"):format(h, #raw) -- display only; writes compare FULL bytes.
end
local function normalize(path) return tostring(path or ""):gsub("/", "\\"):gsub("\\+$", "") end
local function good_name(name)
    if type(name) ~= "string" then return false end
    local stem=name:match("^([^.]*)"):upper()
    local reserved=stem=="CON" or stem=="PRN" or stem=="AUX" or stem=="NUL" or stem:match("^COM[1-9]$") or stem:match("^LPT[1-9]$")
    return #name > 0 and #name <= 100
        and not name:find('[%z\1-\31<>:"/\\|?*]') and not name:find("[ .]$")
        and name ~= "." and name ~= ".."
        and not reserved
end

-- Bounded JSON reader retaining exact leaf tokens, object ordering and unknown
-- fields. Large integers and nulls are never round-tripped through Lua numbers.
local function json(raw)
    if type(raw) ~= "string" or #raw > MAX_BYTES then return nil, "File is missing or too large" end
    local at, nodes = 1, 0
    local function ws() local _, p = raw:find("^[ \t\r\n]*", at); at = (p or at - 1) + 1 end
    local function str()
        local start = at; if raw:sub(at, at) ~= '"' then error("Expected string") end
        at = at + 1; local out = {}
        while at <= #raw do
            local c = raw:sub(at, at); at = at + 1
            if c == '"' then return table.concat(out), raw:sub(start, at - 1) end
            if c:byte() < 32 then error("Control character in string") end
            if c == "\\" then
                c = raw:sub(at, at); at = at + 1
                local escapes = { ['"'] = '"', ['\\'] = '\\', ['/'] = '/', b = '\b', f = '\f', n = '\n', r = '\r', t = '\t' }
                if escapes[c] then out[#out + 1] = escapes[c]
                elseif c == "u" then
                    local hex = raw:sub(at, at + 3); if not hex:match("^%x%x%x%x$") then error("Invalid Unicode escape") end
                    local n = tonumber(hex, 16); at = at + 4
