                while true do
                    ws(); local key, token = str(); if node.lookup[key] then error("Duplicate JSON key: " .. key) end
                    ws(); if raw:sub(at, at) ~= ":" then error("Missing colon") end; at = at + 1
                    local child = parse(depth + 1); node.members[#node.members + 1] = { key = key, token = token, node = child }
                    node.lookup[key] = child; node.value[key] = child.value
                    ws(); c = raw:sub(at, at); if c == "}" then break end
                    if c ~= "," then error("Missing object separator") end; at = at + 1
                end
            end
            at = at + 1; return node
        elseif c == "[" then
            at = at + 1; ws(); local node = { kind = "array", value = {}, children = {} }
            if raw:sub(at, at) ~= "]" then
                while true do
                    local child = parse(depth + 1); node.children[#node.children + 1] = child; node.value[#node.children] = child.value
                    ws(); c = raw:sub(at, at); if c == "]" then break end
                    if c ~= "," then error("Missing array separator") end; at = at + 1
                end
            end
            at = at + 1; return node
        elseif c == '"' then local value, token = str(); return {kind="leaf", value=value, raw=token}
        end
        for _, literal in ipairs({"true", "false", "null"}) do
            if raw:sub(at, at + #literal - 1) == literal then
                at = at + #literal
                local value; if literal == "true" then value = true elseif literal == "false" then value = false end
                return { kind = "leaf", value = value, raw = literal }
            end
        end
        local token = raw:match("^-?%d+%.?%d*[eE]?[+-]?%d*", at)
        if not token or token:match("^-?0%d") or token:match("%.$") or token:match("[eE][+-]?$") then error("Invalid JSON number") end
        local n = tonumber(token); if not n or n ~= n or n == math.huge or n == -math.huge then error("Invalid number") end
        at = at + #token; return {kind="leaf", value=n, raw=token}
