end
local function encode(node)
    if node.kind == "leaf" then return node.raw end
    local out = {}
    if node.kind == "array" then
        for _, child in ipairs(node.children) do out[#out + 1] = encode(child) end
        return "[" .. table.concat(out, ",") .. "]"
    end
    for _, member in ipairs(node.members) do out[#out + 1] = member.token .. ":" .. encode(member.node) end
    return "{" .. table.concat(out, ",") .. "}"
end
local function merge(old, new)
    if old.kind ~= "object" or new.kind ~= "object" then return new end
    local result = { kind = "object", members = {}, lookup = {} }
    for _, member in ipairs(old.members) do
        local replacement = new.lookup[member.key]
        local node = replacement and merge(member.node, replacement) or member.node
        result.members[#result.members + 1] = {key=member.key,token=member.token,node=node}; result.lookup[member.key] = node
    end
    for _, member in ipairs(new.members) do
        if not result.lookup[member.key] then result.members[#result.members + 1] = member; result.lookup[member.key] = member.node end
    end
    return result
end
local function vehicle_json(raw)
    local node, err = json(raw); if not node then return nil, err end
    local d = node.value
