end

function Module.Init(ctx)
    context = ctx
    local state = { entries = {}, records = {}, caps = {}, diagnostics = {}, refresh = {cherax_vehicles=true,gta_personal_vehicles=true,gta_outfits=true},
        epoch = 0, sequence = 0, now = 0, status = "Ready", detail = "", stage = "idle", operation = nil, pending = nil }
    local index_origins,index_conflicts={},{}
    service = {}
    local function status(text, detail) state.status, state.detail = text, detail or "" end
    local function root_path()
        if not FileMgr or type(FileMgr.GetMenuRootPath) ~= "function" then return nil end
        local ok, root = pcall(FileMgr.GetMenuRootPath)
        if not ok or type(root) ~= "string" or root == "" then return nil end
        return normalize(root)
    end
    local function exists(path)
        if not FileMgr or type(FileMgr.DoesFileExist) ~= "function" then return nil end
        local ok, value = pcall(FileMgr.DoesFileExist, path); if not ok or type(value) ~= "boolean" then return nil end
        return value
    end
    local function read(path)
        if not FileMgr or type(FileMgr.ReadFileContent) ~= "function" then return nil end
        local ok, raw = pcall(FileMgr.ReadFileContent, path)
