        GetList="list",GetListIndex="list",SetListIndex="list",TriggerCallback="any",
        GetStringValue="text",SetStringValue="text"}
    local function foreign_call(f,method,...)
        if not f then error("Missing foreign feature",0) end
        local kind=f:GetType()
