    end
    local function list_snapshot(f)
        if not f then return nil end
        local ok, list, selected = pcall(function() return foreign_call(f,"GetList"), foreign_call(f,"GetListIndex") end)
        if not ok or (type(list) ~= "table" and type(list) ~= "userdata") or type(selected) ~= "number" then return nil end
