        state.caps.cherax_vehicles={discovery=not err,read=not err,write=not err and FileMgr and type(FileMgr.WriteFileContent)=="function" and type(FileMgr.DeleteFile)=="function",
            spawn=saved_list~=nil and saved_list.index_verified and feature("vehicle_load")~=nil,
            save_current=feature("vehicle_name")~=nil and feature("vehicle_save")~=nil,
            persistence=false,normal_ui_verified=false,reason=err or "Cherax JSON library; normal menu reload verification pending"}
        state.diagnostics.cherax_vehicles={directory=directory,count=#entries,serializer="Cherax Save Current Vehicle",raw_preservation=true}
    end
    local function refresh_game_sources()
        -- Read-only snapshots do not drive a dependent selector or assume its
        -- array index is a persistent game slot. Empty/read-failure stay distinct.
        local garages=list_snapshot(feature("garages")); local vehicles=list_snapshot(feature("personal"))
        local valid_garage=false
        if garages and garages.index_verified then for _,row in ipairs(garages.rows) do if row.index==garages.selected then valid_garage=true; break end end end
        local rows={}
        if garages then
            for _,row in ipairs(garages.rows) do rows[#rows+1]={id="gta_garage_list:"..state.epoch..":"..garages.revision..":"..row.index,
                source="gta_personal_vehicles",name=row.name,kind="garage",list_index=row.index,readable=true,revision=garages.revision,
                display_index=row.position,index_verified=garages.index_verified,
                selected=row.index==garages.selected,availability="Browse this garage through Cherax"} end
        end
        if vehicles then
            local garageName="Selected garage"
            if garages and garages.index_verified then for _,row in ipairs(garages.rows) do if row.index==garages.selected then garageName=row.name end end end
            for _,row in ipairs(vehicles.rows) do rows[#rows+1]={id="gta_vehicle_list:"..state.epoch..":"..(garages and garages.revision or "unknown")..":"..tostring(garages and garages.selected)..":"..vehicles.revision..":"..row.index,
                source="gta_personal_vehicles",name=row.name,kind="vehicle",garage=garageName,list_index=row.index,readable=true,
                display_index=row.position,index_verified=vehicles.index_verified,
                garage_index=garages and garages.selected,garage_revision=garages and garages.revision,
                revision=vehicles.revision,availability="Current Cherax garage list; game slot ID unverified"} end
        end
        state.entries.gta_personal_vehicles=rows
        -- These exact built-ins exist in the installed identity inventory. A
        -- matching button is discovery evidence, not a verified transaction:
        -- no public API exposes its slot mapping, backup or rollback contract.
        local workflows={}
        for _,key in ipairs({"personal_return","personal_convert","personal_delete"}) do
            local spec=SPECS[key]
            workflows[key]={hash=spec[1],name=spec[2],description=spec[4],identity_verified=feature(key)~=nil,
                target_verified=false,backup_verified=false,rollback_verified=false,persistence_verified=false}
        end
        local can_convert = valid_garage and garages and garages.index_verified
            and feature("personal_convert") ~= nil
        local can_delete = valid_garage and vehicles and vehicles.index_verified
            and feature("personal_delete") ~= nil
        local can_return = feature("personal_return") ~= nil
        state.caps.gta_personal_vehicles = {
            discovery = garages ~= nil or vehicles ~= nil, read = false,
            write = can_convert == true or can_delete == true,
            browse = garages ~= nil and garages.index_verified and vehicles ~= nil,
            request = valid_garage and vehicles ~= nil and vehicles.index_verified
                and feature("personal_request") ~= nil,
            convert = can_convert == true,
            delete = can_delete == true,
            return_current = can_return == true,
            update_current = false, persistence = false, full_roster = false,
            operation_reasons = {
                convert = "Select and browse the destination garage, then enter the vehicle.",
                delete = "Select a saved vehicle from the currently browsed garage.",
                return_current = "Cherax return-to-garage action is unavailable.",
                update_current = "Direct modification of a persistent GTA garage slot is unavailable."
            },
            reason = (garages and garages.index_conflict or vehicles and vehicles.index_conflict)
                and "Garage indices changed. Refresh before editing."
                or "Garage actions use Cherax's existing controls. GTA may reject unsupported vehicle storage."
        }
        state.diagnostics.gta_personal_vehicles = {
            garages=garages, vehicles=vehicles, selector_writes=0, game_writes=0,
            workflows=workflows, slot_identity_verified=can_delete == true,
            record_backup_verified=false, record_restore_verified=false
        }
        local slot=feature("outfit_slot"); local min,max
        if slot then local ok,a,b=pcall(function() return slot:GetIntLimitValues() end); if ok then min,max=a,b end end
        state.entries.gta_outfits={}
        state.caps.gta_outfits={discovery=false,read=false,write=false,persistence=false,
            reason="Wardrobe storage is unavailable: slot mapping and saving are unverified."}
        state.diagnostics.gta_outfits={observed_selector_min=min,observed_selector_max=max,capacity_validated=false,
            save_control_observed=feature("outfit_save")~=nil,name_control_observed=feature("outfit_name")~=nil,
            reason="Selector bounds do not establish GTA wardrobe capacity or storage source"}
    end
    local function destination(op)
        local record=state.records[op.id]
        if not record or not record.node or read(record.entry.path)~=op.original then return nil,"Selected entry changed; refresh and select it again" end
        return record
    end
    local function ticket_valid(ticket)
        if type(ticket)~="table" or type(ticket.subject_key)~="string" or ticket.subject_key==""
            or type(ticket.generation)~="number" or type(ticket.edit_revision)~="number"
            or ticket.edit_revision~=ticket.applied_revision or type(ticket.profile)~="table"
            or type(ticket.handle)~="number" or ticket.handle<=0
            or type(ticket.validate)~="function" then return false,"Wait for the current edit to finish" end
        local ok,valid=pcall(ticket.validate,ticket)
        if not ok or valid~=true then return false,"Vehicle or applied edit changed; prepare the save again" end
        if not GTA or type(GTA.GetLocalVehicle)~="function" or type(GTA.HandleToPointer)~="function" then
            return false,"Cherax current-vehicle identity API unavailable"
        end
        local identity_ok,identity=pcall(function()
            local current=GTA.GetLocalVehicle(); local target=GTA.HandleToPointer(ticket.handle)
            if not current or not target then return false end
            local a,b=current:GetAddress(),target:GetAddress()
            return type(a)=="number" and a>0 and a==b
        end)
        if not identity_ok or not identity then return false,"Enter the vehicle being edited to save it through Cherax" end
        return true
    end
    local function restore_selection(op)
        -- A character/session change can reuse the same displayed roster.
        -- Never restore a previous context's personal-vehicle selectors there.
        if op.personal and op.epoch~=state.epoch then return end
        if op.garage_selector and not op.keep_browse and feature("garages")==op.garage_selector then
            local snap=list_snapshot(op.garage_selector)
            if snap and snap.index_verified and snap.revision==op.entry.revision and snap.selected==op.entry.list_index then
                pcall(function() foreign_call(op.garage_selector,"SetListIndex",op.previous_garage); foreign_call(op.garage_selector,"TriggerCallback") end)
            end
        end
        if op.personal_selector and feature("personal")==op.personal_selector then
            local garages=list_snapshot(feature("garages")); local vehicles=list_snapshot(op.personal_selector)
            if garages and vehicles and garages.index_verified and vehicles.index_verified and garages.selected==op.entry.garage_index
                and garages.revision==op.entry.garage_revision and vehicles.revision==op.entry.revision
                and vehicles.selected==op.entry.list_index then
                pcall(function() foreign_call(op.personal_selector,"SetListIndex",op.previous_index) end)
            end
        end
        if op.name_feature and feature("vehicle_name")==op.name_feature then
            pcall(function() if foreign_call(op.name_feature,"GetStringValue")==op.temp_name then foreign_call(op.name_feature,"SetStringValue",op.previous_name) end end)
        end
        if op.list_feature and feature("vehicle_list")==op.list_feature then
            local snap=list_snapshot(op.list_feature); local same=snap and snap.index_verified and #snap.rows==#(op.list_rows or {})
            if same then for i,row in ipairs(snap.rows) do
                if row.index~=op.list_rows[i].index or row.name~=op.list_rows[i].name then same=false; break end
            end end
            if same then pcall(function() if foreign_call(op.list_feature,"GetListIndex")==op.owned_index then foreign_call(op.list_feature,"SetListIndex",op.previous_index) end end) end
        end
    end
    local function clean_temp(op)
        if op and op.temp_path and op.generated_raw then remove_owned(op.temp_path,op.generated_raw) end
    end
    local function finish(text,detail)
        local op=state.operation; if op then restore_selection(op); clean_temp(op) end
        state.operation=nil; state.pending=nil; state.stage="idle"; state.refresh.cherax_vehicles=true
        if op and op.personal then state.refresh.gta_personal_vehicles=true end
        status(text,detail)
    end
    local function backup(op)
        local root=root_path(); if not root or not FileMgr or type(FileMgr.CreateDir)~="function" then return nil end
        local dir=root.."\\Lua\\CScript\\studio_backups"
        local ok,value=pcall(FileMgr.CreateDir,dir); if not ok or value~=true then return nil end
        local stamp=(os and os.time and os.time()) or math.floor(state.now)
        local path=dir.."\\vehicle_"..stamp.."_"..state.epoch.."_"..state.sequence.."_"..signature(op.original):gsub(":","_")..".json"
        if exists(path)~=false then return nil end
        if not write(path,op.original) then return nil end
        local receipt="CSCRIPT_STUDIO_BACKUP_V1\nsource=cherax_vehicles\npath="..op.path.."\nrevision="..signature(op.original).."\noperation="..op.operation.."\n"
        if not write(path..".receipt.txt",receipt) then return nil end
        return path
    end
    local function named_destination(name)
        if not good_name(name) then return nil,"Choose a valid new file name" end
        local root=root_path(); if not root then return nil,"Cherax root unavailable" end
        local path=root.."\\Vehicles\\"..name..".json"
        if exists(path)~=false then return nil,"That name already exists or could not be checked" end
        return path
    end
    local function validate_capture(op,node)
        local p=op.ticket.profile; local d=node.value
        if d.model~=p.model or (op.ticket.model and d.model~=op.ticket.model) then return false,"Cherax saved a different vehicle model" end
        local mapping={primary="primaryColor",secondary="secondaryColor",pearl="pearlescentColor",wheel_color="wheelColor",wheel_type="wheelType",
            tint="windowTint",plate_index="plateTextIndex",plate_text="plateText",primary_custom="isPrimaryColorCustom",secondary_custom="isSecondaryColorCustom",
            interior_color="interiorColor",dashboard_color="dashBoardColor",drift_tyres="driftTyres"}
        for key,target in pairs(mapping) do
            if p[key]~=nil and d[target]~=p[key] then return false,"Cherax capture did not match current "..key end
        end
        if p.tyres_can_burst~=nil and d.bulletproofTyres~=(p.tyres_can_burst==false) then return false,"Cherax tyre state did not match" end
        for key,target in pairs({primary_rgb="customPrimaryColor",secondary_rgb="customSecondaryColor",tyre_smoke_rgb="tyreSmokeColor"}) do
            if p[key] and (key=="tyre_smoke_rgb" or key=="primary_rgb" and p.primary_custom==true or key=="secondary_rgb" and p.secondary_custom==true) then
                local rgb=d[target]; if type(rgb)~="table" or rgb.r~=p[key][1] or rgb.g~=p[key][2] or rgb.b~=p[key][3] then return false,"Cherax RGB capture did not match "..key end
            end
        end
        if p.extras then
            for index,value in pairs(p.extras) do
                if not d.extras or d.extras["extra"..index]~=value then return false,"Cherax extra capture did not match" end
            end
        end
        if p.neon_enabled then
            local names={[0]="left",[1]="right",[2]="front",[3]="back"}
            for index,key in pairs(names) do
                if p.neon_enabled[index]~=nil and (not d.neonKits or d.neonKits[key]~=p.neon_enabled[index]) then return false,"Cherax neon capture did not match" end
            end
        end
        if p.neon_rgb then
            local rgb=d.neonKits and d.neonKits.color
            if not rgb or rgb.r~=p.neon_rgb[1] or rgb.g~=p.neon_rgb[2] or rgb.b~=p.neon_rgb[3] then return false,"Cherax neon color did not match" end
        end
        -- Host-generated raw mod records remain authoritative. Their special
        -- toggle/xenon ordinal encoding is not rewritten or guessed here.
        return true
    end
    local function prepare_confirmation(op)
        state.stage="confirmation"; state.pending={token=op.token,id=op.id,name=op.name,operation=op.operation,
            revision=signature(op.original),source="cherax_vehicles",subject_key=op.ticket and op.ticket.subject_key,
            edit_revision=op.ticket and op.ticket.edit_revision,expires_ms=state.now+60000}
        status("Confirm "..op.operation:gsub("prepare_", ""),op.name.." · Cherax Saved Vehicles")
    end
    local function begin_serializer(op)
        local valid,problem=ticket_valid(op.ticket); if not valid then finish("Save failed",problem); return end
        local name,save=feature("vehicle_name"),feature("vehicle_save")
        if not name or not save then finish("Save failed","Cherax's current-vehicle serializer identity/type is unavailable"); return end
        local root=root_path(); if not root then finish("Save failed","Cherax directory unavailable"); return end
        op.temp_name="CScript_Studio_Capture_"..state.epoch.."_"..state.sequence.."_"..math.floor(state.now)
        op.temp_path=root.."\\Vehicles\\"..op.temp_name..".json"
        if exists(op.temp_path)~=false then finish("Save failed","Unique capture destination already exists or is unreadable"); return end
        local ok=pcall(function()
            op.name_feature=name; op.previous_name=foreign_call(name,"GetStringValue"); foreign_call(name,"SetStringValue",op.temp_name)
            if foreign_call(name,"GetStringValue")~=op.temp_name then error("Serializer name readback failed") end
            foreign_call(save,"TriggerCallback")
        end)
        if not ok then finish("Save failed","Cherax serializer could not be invoked"); return end
        op.deadline=state.now+6000; state.stage="capture"; status("Saving current vehicle","Waiting for Cherax's serializer")
    end
    local function commit(op)
        local record,err=destination(op); if not record then finish("Save failed",err); return end
        if op.ticket then local valid,problem=ticket_valid(op.ticket); if not valid then finish("Save failed",problem); return end end
        local backup_path=backup(op); if not backup_path then finish("Save failed","A recoverable backup could not be verified"); return end
        op.backup_path=backup_path
        -- Re-read after backup as well; background file edits invalidate the
        -- confirmation. Restore is never attempted against unrelated content.
        if read(op.path)~=op.original then finish("Save failed","Selected entry changed after backup"); return end
        if op.operation=="prepare_delete" then
            if not remove_owned(op.path,op.original) then finish("Delete failed","Original backup retained at "..backup_path); return end
        elseif op.operation=="prepare_rename" then
            local path,problem=named_destination(op.new_name); if not path then finish("Rename failed",problem); return end
            if not write(path,op.original) then finish("Rename failed","New file readback failed; original preserved"); return end
            if not remove_owned(op.path,op.original) then finish("Rename incomplete","Verified copy exists; original also remains. Backup: "..backup_path); return end
        else
            local generated,problem=vehicle_json(op.generated_raw); if not generated then finish("Save failed",problem); return end
            local merged=encode(merge(record.node,generated)).."\n"
            if not write(op.path,merged) then finish("Save failed","Destination readback failed. Backup retained at "..backup_path); return end
        end
        finish(op.operation=="prepare_delete" and "Deleted" or op.operation=="prepare_rename" and "Renamed" or "Saved",
            "Local file readback verified; normal Cherax menu reload pending. Backup: "..backup_path)
    end
    local function start_operation(op)
        if op.epoch~=state.epoch then finish("Cancelled","Studio context changed"); return end
        if op.id then local record,err=destination(op); if not record then finish("Save failed",err); return end end
        if op.operation=="save_new" or op.operation=="prepare_overwrite" then begin_serializer(op)
        elseif op.operation=="prepare_rename" or op.operation=="prepare_delete" then prepare_confirmation(op)
        elseif op.operation=="duplicate" then
            local path,err=named_destination(op.new_name); if not path then finish("Save failed",err); return end
            if not write(path,op.original) then finish("Save failed","Duplicate readback failed; original preserved"); return end
            finish("Saved","Duplicate copied byte-for-byte into Cherax Saved Vehicles; menu reload pending")
        elseif op.operation=="spawn" then
            local selector,load=feature("vehicle_list"),feature("vehicle_load"); local snap=list_snapshot(selector)
            if not snap or not snap.index_verified or not load then finish("Load unavailable","Cherax saved-vehicle controls or native list-index mapping could not be verified"); return end
            local matches={}; for _,row in ipairs(snap.rows) do
                if row.name==op.name or row.name==op.name..".json" or normalize(row.name):lower()==op.path:lower() then matches[#matches+1]=row.index end
            end
            if #matches~=1 then finish("Load unavailable","Refresh Cherax's Saved Vehicles list; selected file must have exactly one matching entry"); return end
            local ok=pcall(function()
                op.list_feature=selector; op.previous_index=snap.selected; op.owned_index=matches[1]; op.list_rows=copy(snap.rows)
                foreign_call(selector,"SetListIndex",op.owned_index)
                if foreign_call(selector,"GetListIndex")~=op.owned_index then error("Selection readback failed") end
            end)
            if not ok then finish("Load unavailable","Cherax selection readback failed"); return end
            op.deadline=state.now+150; state.stage="spawn_selected"
        else finish("Unavailable","Unknown storage action") end
    end

    function service.Refresh(source) state.refresh[source or "cherax_vehicles"]=true end
    function service.GetEntries(source,filter)
        local rows={}; filter=tostring(filter or ""):lower()
        for _,entry in ipairs(state.entries[source] or {}) do
            if filter=="" or entry.name:lower():find(filter,1,true) or tostring(entry.garage or ""):lower():find(filter,1,true) then rows[#rows+1]=copy(entry) end
        end
        return rows
    end
    function service.GetCapabilities(source)
        return copy(state.caps[source] or {discovery=false,read=false,write=false,persistence=false,reason="Waiting for storage discovery"})
    end
    function service.GetDiagnostics(source) return copy(state.diagnostics[source] or {}) end
    function service.GetStatus() return {status=state.status,detail=state.detail,
        stage=state.stage,busy=state.operation~=nil,cancel_pending=state.cancel==true} end
    function service.GetPendingConfirmation() return copy(state.pending) end
    function service.QueueVehicleAction(operation,id,name,ticket)
        if state.operation then return false,"Another library action is pending" end
        local allowed={spawn=true,save_new=true,prepare_overwrite=true,prepare_rename=true,duplicate=true,prepare_delete=true}
        if not allowed[operation] then return false,"Unsupported action" end
        local record=id and state.records[id]
        if operation~="save_new" and (not record or not record.node) then return false,"Select a readable Cherax Saved Vehicles entry" end
        if (operation=="save_new" or operation=="prepare_rename" or operation=="duplicate") and not good_name(name) then return false,"Choose a valid new file name" end
        if (operation=="save_new" or operation=="prepare_overwrite") and type(ticket)~="table" then return false,"Capture the settled live vehicle before saving" end
        state.sequence=state.sequence+1
        state.operation={operation=operation,id=id,new_name=name,name=record and record.entry.name or name,path=record and record.entry.path,
            original=record and record.raw,epoch=state.epoch,token=tostring(state.epoch)..":"..state.sequence,ticket=copy(ticket)}
        state.stage="queued"; status("Queued"); return true
    end
    function service.QueuePersonalAction(operation, id)
        if state.operation then return false, "Another garage action is pending" end
        local supported = {browse=true, request=true, convert=true, delete=true, return_current=true}
        if not supported[operation] then return false, "Unknown garage action" end
        local caps = state.caps.gta_personal_vehicles or {}
        if not caps[operation] then
            return false, (caps.operation_reasons or {})[operation] or "Garage action unavailable"
        end
        local selected
        if operation ~= "return_current" then
            for _, entry in ipairs(state.entries.gta_personal_vehicles or {}) do
                if entry.id == id then selected = entry; break end
            end
            local expected = (operation == "browse" or operation == "convert") and "garage" or "vehicle"
            if not selected or selected.kind ~= expected or selected.index_verified ~= true then
                return false, "Select the exact garage or vehicle again"
            end
        end
        state.sequence = state.sequence + 1
        state.operation = {personal=true, operation=operation, entry=copy(selected),
            epoch=state.epoch, sequence=state.sequence}
        state.stage = "personal_queued"
        status("Queued")
        return true
    end
    local function tick_personal(op)
        if state.stage=="personal_dispatched" then
            if state.now>=op.deadline then
                finish(op.result_status or "Garage action requested",
                    op.result_detail or "Cherax callback dispatched; refresh and verify in GTA.")
            end
            return
        end
        if op.operation=="return_current" then
            local action=feature("personal_return")
            if not action then finish("Unavailable","Return-to-garage control was removed"); return end
            local ok=pcall(function() foreign_call(action,"TriggerCallback") end)
            if not ok then finish("Return failed","Cherax callback failed"); return end
            op.result_status="Return requested"
            op.result_detail="Check the active personal vehicle in GTA."
            op.deadline=state.now+500; state.stage="personal_dispatched"
            return
        end
        local garage=feature("garages"); local vehicle=feature("personal")
        local garages=list_snapshot(garage); local vehicles=list_snapshot(vehicle)
        if not garages or not vehicles then finish("Unavailable","Cherax garage/vehicle lists could not be read"); return end
        local entry=op.entry
        if op.operation=="convert" then
            local action=feature("personal_convert")
            if not entry or not action or not garages.index_verified
                or garages.revision~=entry.revision or garages.selected~=entry.list_index then
                finish("Save cancelled","Browse the target garage and select it again"); return
            end
            -- GTA's own local ped must be driving the vehicle being saved.
            -- This does not alter another player's garage or force a server entitlement.
            local raw=context and context.Raw
            local natives=raw and raw.Natives
            if not natives or type(natives.InvokeInt)~="function" then
                finish("Save unavailable","Local vehicle context is unavailable"); return
            end
            local ped_ok,ped=pcall(natives.InvokeInt,0xD80958FC74E988A6)
            local veh_ok,veh=false,nil
            if ped_ok and type(ped)=="number" and ped>0 then
                veh_ok,veh=pcall(natives.InvokeInt,0x9A9112A0FE9A4713,ped,false)
            end
            local seat_ok,driver=false,nil
            if veh_ok and type(veh)=="number" and veh>0 then
                seat_ok,driver=pcall(natives.InvokeInt,0xBB40DD2270B65366,veh,-1,false)
            end
            if not ped_ok or not veh_ok or not seat_ok or type(veh)~="number" or veh<=0 or driver~=ped then
                finish("Save unavailable","Enter the vehicle as driver before saving"); return
            end
            local ok=pcall(function() foreign_call(action,"TriggerCallback") end)
            if not ok then finish("Save failed","Cherax storage callback rejected the request"); return end
            op.result_status="Storage requested"
            op.result_detail="Check the destination in GTA after refresh. Unsupported models may be rejected."
            op.deadline=state.now+1000; state.stage="personal_dispatched"
            return
        end
        if op.operation=="browse" then
            if garages.revision~=entry.revision then finish("Cancelled","Garage list changed; select the destination again"); return end
            if state.stage=="personal_queued" then
                if not garages.index_verified then finish("Browse unavailable","Native garage index mapping could not be verified"); return end
                op.previous_garage=garages.selected; op.original_vehicles=vehicles.revision
                op.garage_selector=garage; op.vehicle_selector=vehicle
                local ok=pcall(function()
                    foreign_call(garage,"SetListIndex",entry.list_index)
                    if foreign_call(garage,"GetListIndex")~=entry.list_index then error("Garage selection rejected") end
                    foreign_call(garage,"TriggerCallback")
                end)
                if not ok then finish("Browse failed","Cherax garage selection/callback failed"); return end
                op.deadline=state.now+5000; op.earliest=state.now+250
                state.stage="personal_browsing"; status("Loading garage","Waiting for the dependent vehicle list"); return
            end
            if garage~=op.garage_selector or vehicle~=op.vehicle_selector or garages.selected~=entry.list_index then
                finish("Cancelled","Another menu action changed the selected garage"); return
            end
            if not garages.index_verified then finish("Browse unavailable","Native garage index mapping could not be verified"); return end
            if state.now>=op.earliest and (op.previous_garage==entry.list_index or vehicles.revision~=op.original_vehicles) then
                if op.stable_revision~=vehicles.revision then op.stable_revision=vehicles.revision; op.stable_since=state.now
                elseif state.now-op.stable_since>=150 then
                    op.keep_browse=true; refresh_game_sources()
                    finish("Garage ready",#vehicles.rows==0 and "Cherax reports an empty vehicle list; no ownership data was changed"
                        or ("Read "..#vehicles.rows.." entries from "..entry.name..". Choose a vehicle, then Request Selected Vehicle.")); return
                end
            end
            if state.now>=op.deadline then finish("Browse unavailable","The dependent list did not show a verifiable update; no vehicle was requested") end
            return
        end
        local request=feature(op.operation=="delete" and "personal_delete" or "personal_request")
        local valid_garage=false
        for _,row in ipairs(garages.rows) do if row.index==entry.garage_index then valid_garage=true; break end end
        if not request or not valid_garage or not garages.index_verified or not vehicles.index_verified
            or garages.revision~=entry.garage_revision or garages.selected~=entry.garage_index
            or vehicles.revision~=entry.revision then finish("Request cancelled","Garage or vehicle list changed; browse and select the vehicle again"); return end
        if state.stage=="personal_queued" then
            op.personal_selector=vehicle; op.previous_index=vehicles.selected; op.garage_feature=garage; op.request_feature=request
            local ok=pcall(function()
                foreign_call(vehicle,"SetListIndex",entry.list_index)
                if foreign_call(vehicle,"GetListIndex")~=entry.list_index then error("Vehicle selection rejected") end
            end)
            if not ok then finish("Request failed","Selected vehicle could not be verified"); return end
            op.deadline=state.now+150; state.stage="personal_selected"; return
        end
        if vehicle~=op.personal_selector or garage~=op.garage_feature or request~=op.request_feature or vehicles.selected~=entry.list_index then
            finish("Request cancelled","Another menu action changed the destination"); return
        end
        if state.stage=="personal_selected" and state.now>=op.deadline then
            local ok=pcall(function() foreign_call(request,"TriggerCallback") end)
            if not ok then finish("Request failed","Cherax request callback failed"); return end
            op.deadline=state.now+1000; state.stage="personal_dispatched"
            if op.operation=="delete" then
                op.result_status="Delete requested"
                op.result_detail="Refresh the garage to verify deletion; the operation cannot be undone here."
            else
                op.result_status="Vehicle requested"
                op.result_detail="Check that your selected personal vehicle arrives in GTA."
            end
            status(op.result_status,op.result_detail)
        end
    end
    function service.ConfirmVehicle(token)
        if not state.pending or state.pending.token~=token then return false,"Confirmation expired" end
        state.confirm=token; return true
    end
    function service.CancelVehicle() state.cancel=true end
    function service.Invalidate(reason)
        index_origins,index_conflicts={},{}
        state.epoch=state.epoch+1; state.cancel=true; state.pending=nil; state.entries.gta_personal_vehicles={}; state.entries.gta_outfits={}
        state.refresh.gta_personal_vehicles=true; state.refresh.gta_outfits=true; state.invalid_reason=reason or "Studio context changed"
    end
    function service.Shutdown()
        state.epoch=state.epoch+1; state.cancel=false; state.confirm=nil
        if state.operation then finish("Cancelled","Studio storage stopped") end
        state.pending=nil; state.refresh={}
    end
    function service.Requested()
        return state.operation ~= nil or state.cancel == true or next(state.refresh) ~= nil
    end
    function service.Tick(now)
        state.now=tonumber(now) or (os and os.clock and os.clock()*1000) or state.now+16
        if state.cancel then
            state.cancel=false; state.confirm=nil
            if state.operation then
                if state.operation.personal and state.stage=="personal_dispatched" then
                    finish("Request already dispatched","The Cherax request was sent before cancellation; vehicle arrival remains unverified")
                else finish("Cancelled",state.invalid_reason or "No saved entry was changed") end
            end
            state.invalid_reason=nil
        end
        if not state.operation then
            if state.refresh.cherax_vehicles then state.refresh.cherax_vehicles=nil; refresh_library() end
            if state.refresh.gta_personal_vehicles or state.refresh.gta_outfits then
                state.refresh.gta_personal_vehicles=nil; state.refresh.gta_outfits=nil; refresh_game_sources()
            end
            return
        end
        local op=state.operation
        if op.epoch~=state.epoch then finish("Cancelled","Studio context changed"); return end
        if op.personal then tick_personal(op); return end
        if state.stage=="queued" then start_operation(op)
        elseif state.stage=="capture" then
            local valid,problem=ticket_valid(op.ticket); if not valid then finish("Save failed",problem); return end
            if feature("vehicle_name")~=op.name_feature then finish("Save failed","Cherax controls changed"); return end
            local ok,current=pcall(function() return foreign_call(op.name_feature,"GetStringValue") end)
            if not ok or current~=op.temp_name then finish("Save failed","Another menu action changed the save destination"); return end
            local raw=read(op.temp_path)
            if raw then
                local node,err=vehicle_json(raw)
                if node and raw~=op.stable_candidate then op.stable_candidate=raw; return end
                if node then
                    op.generated_raw=raw; local matches,why=validate_capture(op,node)
                    if not matches then finish("Save failed",why); return end
                    if op.operation=="prepare_overwrite" then restore_selection(op); prepare_confirmation(op)
                    else
                        local path,problem=named_destination(op.new_name); if not path then finish("Save failed",problem); return end
                        if not write(path,raw) then finish("Save failed","New file readback failed"); return end
                        finish("Saved","Current vehicle serialized by Cherax; local file readback verified; normal menu reload pending")
                    end
                    return
                end
            end
            if state.now>=op.deadline then finish("Save failed","Cherax did not produce a valid current-vehicle file; enter the bound vehicle and retry") end
        elseif state.stage=="confirmation" then
            if state.now>state.pending.expires_ms then finish("Cancelled","Confirmation expired; no saved entry was changed")
            elseif op.ticket then
                local valid,problem=ticket_valid(op.ticket); if not valid then finish("Cancelled",problem); return end
            end
            if state.operation and state.confirm then
                local token=state.confirm; state.confirm=nil
                if token~=op.token then finish("Cancelled","Confirmation no longer matches") else commit(op) end
            end
        elseif state.stage=="spawn_selected" and state.now>=op.deadline then
            local selector,load=feature("vehicle_list"),feature("vehicle_load")
            if selector~=op.list_feature or not load or read(op.path)~=op.original then finish("Load unavailable","Selected source or controls changed"); return end
            local snap=list_snapshot(selector); local same=snap and snap.index_verified and #snap.rows==#op.list_rows
            if same then for i,row in ipairs(snap.rows) do
                if row.index~=op.list_rows[i].index or row.name~=op.list_rows[i].name then same=false; break end
            end end
            if not same then finish("Load unavailable","Cherax's saved-vehicle list changed before loading"); return end
            local ok=pcall(function() if foreign_call(selector,"GetListIndex")~=op.owned_index then error("External selection changed") end; foreign_call(load,"TriggerCallback") end)
            if not ok then finish("Load unavailable","Cherax load callback could not be dispatched"); return end
            op.deadline=state.now+1000; state.stage="spawn_dispatched"; status("Spawn requested","Waiting for Cherax; this is a local spawn preset, not a personal-vehicle request")
        elseif state.stage=="spawn_dispatched" and state.now>=op.deadline then
            finish("Spawn requested","Cherax callback dispatched; actual spawn/readback requires game verification")
        end
    end
    context.StudioStorage=service; context.CScript=context.CScript or {}; context.CScript.StudioStorage=service
end
function Module.Start() end
function Module.Stop()
    if service then service.Shutdown() end
end
function Module.Restore(ctx)
    Module.Stop(); ctx=ctx or context
    if ctx and ctx.StudioStorage==service then ctx.StudioStorage=nil end
    if ctx and ctx.CScript and ctx.CScript.StudioStorage==service then ctx.CScript.StudioStorage=nil end
    service,context=nil,nil
end
return Module
