["CScript/core/cleanup.lua"]=[====[
-- Idempotent owner-scoped cleanup registry. The loader remains responsible for
-- invoking Module.Stop and Module.Restore in reverse initialization order.
local Module = { Name = "core.cleanup", MigrationPhase = "17.75" }

local service

local function identifier(value, label)
    if type(value) ~= "string" or value == "" then error(label .. " must be a non-empty string", 3) end
    return value
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.Logger) ~= "table" then
        error("core.cleanup requires the injected Logger service")
    end

    local owners = {}
    local owner_order = {}
    local running_all = false
    service = {}

    local function owner_record(owner, create)
        local record = owners[owner]
        if not record and create then
            record = { entries = {}, order = {}, ordered = {}, versions = {}, serial = 0, running = false }
            owners[owner] = record
            owner_order[#owner_order + 1] = owner
        end
        return record
    end

    function service.Register(owner, key, callback)
        owner = identifier(owner, "cleanup owner")
        key = identifier(key, "cleanup key")
        if type(callback) ~= "function" then error("cleanup callback must be a function", 2) end
        local record = owner_record(owner, true)
        if record.entries[key] then
            return false, ("cleanup key already registered: %s/%s"):format(owner, key)
        end
        record.serial = record.serial + 1
        record.entries[key] = callback
        record.versions[key] = record.serial
        if not record.ordered[key] then
            record.ordered[key] = true
            record.order[#record.order + 1] = key
        end
        return true
    end

    function service.Release(owner, key)
        local record = owners[tostring(owner)]
        key = tostring(key)
        if not record or not record.entries[key] then return false end
        record.entries[key], record.versions[key] = nil, nil
        return true
    end

    function service.Run(owner, reason)
        owner = tostring(owner)
        local record = owners[owner]
        if not record then return true end
        if record.running then return false, "Cleanup is already in progress" end
        record.running = true
        -- Freeze this pass. Reentrant registrations are obligations for the next
        -- pass, not an invitation to execute an unbounded callback chain.
        local batch = {}
        for index = #record.order, 1, -1 do
            local key = record.order[index]
            local callback = record.entries[key]
            if callback then batch[#batch + 1] = {key, callback, record.versions[key]} end
        end
        local success = true
        for _, item in ipairs(batch) do
            local key, callback, version = item[1], item[2], item[3]
            if record.entries[key] == callback and record.versions[key] == version then
                local ok, result = pcall(callback, reason)
                if ok and result ~= false then
                    -- Do not consume a newer registration made by the callback.
                    if record.entries[key] == callback and record.versions[key] == version then
                        record.entries[key], record.versions[key] = nil, nil
                    end
                else
                    success = false
                    if not ok and type(context.Logger.ErrorOnce) == "function" then
                        pcall(context.Logger.ErrorOnce, "cleanup:" .. owner .. ":" .. key, result, "cleanup")
                    end
                end
            end
        end
        record.running = false
        local order, ordered = {}, {}
        for _, key in ipairs(record.order) do
            if record.entries[key] and not ordered[key] then
                order[#order + 1], ordered[key] = key, true
            end
        end
        record.order, record.ordered = order, ordered
        if next(record.entries) ~= nil then return false, "Cleanup remains pending" end
        owners[owner] = nil
        for index = #owner_order, 1, -1 do
            if owner_order[index] == owner then table.remove(owner_order, index) end
        end
        return success
    end

    function service.RunAll(reason)
        if running_all then return false, "Cleanup is already in progress" end
        running_all = true
        local batch = {}
        for index = #owner_order, 1, -1 do
            local owner = owner_order[index]
            batch[#batch + 1] = {owner, owners[owner]}
        end
        local success = true
        for _, item in ipairs(batch) do
            local owner, record = item[1], item[2]
            if record and owners[owner] == record and not service.Run(owner, reason) then success = false end
        end
        running_all = false
        -- Retain ordering and references for failures and newly registered owners.
        return success and next(owners) == nil
    end

    function service.Has(owner, key)
        local record = owners[tostring(owner)]
        return record ~= nil and record.entries[tostring(key)] ~= nil
    end

    function service.OwnerCount()
        local count = 0
        for _ in pairs(owners) do count = count + 1 end
        return count
    end

    context.Cleanup = service
    context.Core.Cleanup = service
    context.CScript.Cleanup = service
end

function Module.Start() end
function Module.Stop() end

function Module.Restore(context, reason)
    if service and service.RunAll(reason or "module restore") ~= true then
        return false, "Cleanup remains pending"
    end
    if context and context.Cleanup == service then context.Cleanup = nil end
    if context and context.Core and context.Core.Cleanup == service then context.Core.Cleanup = nil end
    if context and context.CScript and context.CScript.Cleanup == service then context.CScript.Cleanup = nil end
    service = nil
    return true
end

return Module
