["CScript/core/config.lua"]=[====[
-- CScript configuration owner.
-- Owns settings/autoload persistence and the Settings configuration and unload controls.
local Module = { Name = "core.config", MigrationPhase = "17.75" }

local module_context
local service
local dependencies
local bound = false
local features_registered = false
local perf_generation, perf_stopped, perf_pending, perf_used_nonce = 0, false, nil, nil

local RETIRED_KEYS = {
    "protect_collision", "protect_auto_isolate",
    "vehicle_auto_lock_fire", "vehicle_rocket_range", "vehicle_rocket_range_unlimited", "vehicle_reset_rocket_range",
    "vehicle_missile_profile", "vehicle_missile_turn_rate", "vehicle_missile_turn_limit",
    "auto_repair", "keep_engine", "auto_flip", "auto_unlock", "keep_clean",
    "prevent_shuffle", "radio_silence", "vehicle_lab_continuous_repair",
    "vehicle_oppressor_rockets", "vehicle_lab_mk2_tracking", "vehicle_lab_mk2_profile", "vehicle_cannon_explosion",
    "vehicle_weapon_backend_diagnostics", "blame_player", "blame_kill_gun", "blame_kill",
    "movement_refinement_preset", "clear_wanted", "heal_armour_now", "refill_snacks_now", "refill_armour_now",
    "vehicle_wheelie", "vehicle_wheelie_strength",
    "vehicle_cannon_profile", "repair_now", "flip_now",
}
local RETIRED_SET = {}
for _, key in ipairs(RETIRED_KEYS) do RETIRED_SET[key] = true end
-- These removed controls were buttons/numeric selectors, so never invoke a
-- toggle getter/setter on retained host userdata while migrating their keys.
local RETIRED_NON_TOGGLES = { movement_refinement_preset=true, clear_wanted=true,
    vehicle_rocket_range=true, vehicle_reset_rocket_range=true, vehicle_missile_profile=true,
    vehicle_missile_turn_rate=true, vehicle_missile_turn_limit=true,
    heal_armour_now=true, refill_snacks_now=true, refill_armour_now=true,
    vehicle_wheelie_strength=true, vehicle_cannon_profile=true, repair_now=true, flip_now=true }
local REPORT_LIMIT = 64

local function is_retired_feature(key)
    return RETIRED_SET[key] == true
end

local function retired_feature_keys()
    return { table.unpack(RETIRED_KEYS) }
end

local ConfigStore = {
    path = nil,
    autoload_path = nil,
    auto_load = false,
    registered_count = 0,
}

local function require_binding(name, value)
    if value == nil then error("config compatibility binding missing " .. name, 3) end
    return value
end

local function clamp(value, minimum, maximum)
    value = tonumber(value)
    if not value or value ~= value or value == math.huge or value == -math.huge then return nil end
    return math.max(minimum, math.min(maximum, value))
end

local function resolve_paths()
    if ConfigStore.path then return ConfigStore.path, ConfigStore.autoload_path end
    local root = module_context and module_context.Root
    if type(root) ~= "string" or root == "" then return nil, nil end
    ConfigStore.path = root .. "\\settings.txt"
    ConfigStore.autoload_path = root .. "\\autoload.txt"
    return ConfigStore.path, ConfigStore.autoload_path
end

local function read_file(path)
    if not service or not path then return nil end
    local content = service.ReadText(path)
    return type(content) == "string" and content or nil
end

local function write_file(path, content)
    if not service or not path then return false, "Configuration path is unavailable" end
    return service.WriteText(path, tostring(content))
end

local function load_autoload_preference()
    local _, path = resolve_paths()
    local content = read_file(path)
    ConfigStore.auto_load = content ~= nil
        and content:find("CSCRIPT_AUTOLOAD_V1", 1, true) ~= nil
        and content:find("enabled=true", 1, true) ~= nil
    return ConfigStore.auto_load
end

local function save_autoload_preference(enabled)
    local _, path = resolve_paths()
    ConfigStore.auto_load = enabled == true
    return write_file(path, "CSCRIPT_AUTOLOAD_V1\nenabled=" .. tostring(ConfigStore.auto_load))
end

local function save_config_store()
    local path = resolve_paths()
    if not path then return false, "Configuration path is unavailable" end
    local lines = { "CSCRIPT_SETTINGS_V1" }
    for _, key in ipairs(dependencies.TOGGLE_KEYS) do
        if not is_retired_feature(key) and dependencies.feature_ref(key) then
            lines[#lines + 1] = key .. "|t|" .. (dependencies.is_on(key) and "1" or "0")
        end
    end
    for key in pairs(dependencies.CONFIG_COMBOS) do
        if not is_retired_feature(key) and dependencies.feature_ref(key) then
            lines[#lines + 1] = key .. "|c|" .. tostring(dependencies.list_index(key))
        end
    end
    for key, limits in pairs(dependencies.CONFIG_INTS) do
        if not is_retired_feature(key) and dependencies.feature_ref(key) then
            local value = clamp(dependencies.slider_int(key, limits.default), limits.minimum, limits.maximum)
            lines[#lines + 1] = key .. "|i|" .. tostring(math.floor(value + 0.5))
        end
    end
    for key, limits in pairs(dependencies.CONFIG_FLOATS) do
        if not is_retired_feature(key) and dependencies.feature_ref(key) then
            local value = clamp(dependencies.slider_float(key, limits.default), limits.minimum, limits.maximum)
            lines[#lines + 1] = key .. "|f|" .. ("%.3f"):format(value)
        end
    end
    local ok, detail = write_file(path, table.concat(lines, "\n"))
    if ok == true then
        local ui = module_context and module_context.CScript and module_context.CScript.UI
        if ui and type(ui.RequestNavigationSave) == "function" then
            local queued, result = pcall(ui.RequestNavigationSave)
            if not queued or result == false then
                dependencies.log_warn("Settings saved; navigation cleanup could not be queued.")
            end
        end
    end
    return ok, detail
end

-- Host setters may return nil on success. Verify the typed readback as well as
-- exceptions/explicit rejection; Lua numbers must never stand in for booleans.
local GETTERS = { t = "IsToggled", c = "GetListIndex", i = "GetIntValue", f = "GetFloatValue" }
local SETTERS = { c = "SetListIndex", i = "SetIntValue", f = "SetFloatValue" }
local function read_typed(feature, kind)
    local getter = feature and feature[GETTERS[kind]]
    if type(getter) ~= "function" then return false, "typed readback unavailable" end
    local ok, value = pcall(getter, feature)
    if not ok then return false, tostring(value) end
    if kind == "t" then
        if type(value) ~= "boolean" then return false, "boolean readback required" end
    elseif type(value) ~= "number" or value ~= value or math.abs(value) == math.huge
        or (kind ~= "f" and value % 1 ~= 0) then
        return false, "finite typed numeric readback required"
    end
    return true, value
end

local function apply_value(key, kind, wanted, feature)
    feature = feature or dependencies.feature_ref(key)
    local before_ok, before = read_typed(feature, kind)
    if not before_ok then return false, before end
    local ok, result, detail
    if kind == "t" then
        ok, result, detail = pcall(dependencies.set_toggle, key, wanted)
    else
        local setter = feature[SETTERS[kind]]
        if type(setter) ~= "function" then return false, "typed setter unavailable" end
        ok, result, detail = pcall(setter, feature, wanted)
    end
    if not ok or result == false or (kind == "t" and result ~= true) then
        return false, tostring(not ok and result or detail or "setter rejected")
    end
    local observed_ok, observed = read_typed(feature, kind)
    if not observed_ok then return false, observed end
    local matches = observed == wanted
    if kind == "f" then matches = math.abs(observed - wanted) <= 0.000001 * math.max(1, math.abs(wanted)) end
    if not matches then return false, "readback did not reach requested value" end
    return true, { key = key, kind = kind, before = before, value = observed }
end

local function new_report()
    return { applied = 0, failed = 0, invalid = 0, retired_ignored = 0, values = {}, failures = {} }
end

local function capture_result(report, key, ok, detail)
    if ok then
        report.applied = report.applied + 1
        if #report.values < REPORT_LIMIT then report.values[#report.values + 1] = detail end
    else
        report.failed = report.failed + 1
        if #report.failures < REPORT_LIMIT then
            report.failures[#report.failures + 1] = { key = key, reason = tostring(detail):sub(1, 240) }
        end
    end
end

local function retire_features()
    local report = { off = 0, changed = 0, unavailable = 0, failed = 0, failures = {} }
    for _, key in ipairs(RETIRED_KEYS) do
        local feature = dependencies.feature_ref(key)
        if not feature or RETIRED_NON_TOGGLES[key] then
            report.unavailable = report.unavailable + 1
        else
            local ok, detail = apply_value(key, "t", false, feature)
            if ok then
                report.off = report.off + 1
                if detail.before then report.changed = report.changed + 1 end
            else
                report.failed = report.failed + 1
                report.failures[#report.failures + 1] = { key = key, reason = tostring(detail):sub(1, 240) }
            end
        end
    end
    if report.changed > 0 or report.failed > 0 then
        local message = ("Retired settings: %d verified OFF, %d changed, %d failed, %d unavailable; saved files unchanged.")
            :format(report.off, report.changed, report.failed, report.unavailable)
        if report.failed > 0 or report.unavailable > 0 then dependencies.log_warn(message)
        else dependencies.log_info(message) end
    end
    return report
end

local function set_config_defaults()
    local report = new_report()
    report.retired = retire_features()
    local function apply(key, kind, value)
        if not is_retired_feature(key) and dependencies.feature_ref(key) then
            capture_result(report, key, apply_value(key, kind, value))
        end
    end
    for _, key in ipairs(dependencies.TOGGLE_KEYS) do apply(key, "t", false) end
    for _, key in ipairs({
        "op_crash_protection", "protect_sync_nodes", "protect_script_events",
        "protect_attachments",
        "protect_reactions", "modder_detection",
        "notifications_enabled", "protection_notifications", "protect_event_identity", "protect_script_schema",
        "protect_ped_motion", "protect_object_physics", "protect_vehicle_physics", "protect_remote_camera_data",
    }) do apply(key, "t", true) end

    for key, value in pairs(dependencies.CONFIG_COMBOS) do
        apply(key, "c", value)
    end
    for key, limits in pairs(dependencies.CONFIG_INTS) do
        apply(key, "i", limits.default)
    end
    for key, limits in pairs(dependencies.CONFIG_FLOATS) do
        apply(key, "f", limits.default)
    end
    return report.failed == 0 and report.retired.failed == 0, report
end

local function notify_load_result(report, silent_success)
    local failed = report.failed + report.invalid + report.retired.failed
    if failed > 0 then
        dependencies.toast(("%d setting%s could not be restored. See Cherax log.")
            :format(failed, failed == 1 and "" or "s"), 4500, "warning")
    elseif not silent_success then
        dependencies.toast("Saved settings loaded.", 3500, "success")
    end
end

local function request_perf_capture()
    return false
end

local function load_config_store(notify)
    local report = new_report()
    report.retired = retire_features()
    local path = resolve_paths()
    local content = read_file(path)
    if not content then return false, "No saved configuration was found", report end
    if not content:find("CSCRIPT_SETTINGS_V1", 1, true) then
        return false, "Unsupported configuration format", report
    end

    local toggle_set = {}
    for _, key in ipairs(dependencies.TOGGLE_KEYS) do toggle_set[key] = true end
    for line in content:gmatch("[^\r\n]+") do
        local key, kind, raw = line:match("^([%w_]+)|([tcif])|([^|]+)$")
        if key and is_retired_feature(key) then
            report.retired_ignored = report.retired_ignored + 1
        elseif key and kind == "t" and toggle_set[key] and dependencies.feature_ref(key) then
            if raw == "1" or raw == "true" or raw == "0" or raw == "false" then
                capture_result(report, key, apply_value(key, kind, raw == "1" or raw == "true"))
            else report.invalid = report.invalid + 1 end
        elseif key and kind == "c" and dependencies.CONFIG_COMBOS[key] ~= nil
            and dependencies.feature_ref(key) then
            local value = clamp(raw, 0, 10)
            if value then
                capture_result(report, key, apply_value(key, kind, math.floor(value)))
            else report.invalid = report.invalid + 1 end
        elseif key and kind == "i" and dependencies.CONFIG_INTS[key] and dependencies.feature_ref(key) then
            local limits = dependencies.CONFIG_INTS[key]
            local value = clamp(raw, limits.minimum, limits.maximum)
            if value then
                capture_result(report, key, apply_value(key, kind, math.floor(value + 0.5)))
            else report.invalid = report.invalid + 1 end
        elseif key and kind == "f" and dependencies.CONFIG_FLOATS[key] and dependencies.feature_ref(key) then
            local limits = dependencies.CONFIG_FLOATS[key]
            -- Normalize the former 1.277 default to neutral speed when loading saved settings.
            local normalized_raw = raw
            local migrated_speed = false
            if key == "vehicle_rocket_speed" then
                local old_value = tonumber(raw)
                if old_value and math.abs(old_value - 1.277) <= 0.0005 then
                    normalized_raw = "1.0"
                    migrated_speed = true
                end
            end
            local value = clamp(normalized_raw, limits.minimum, limits.maximum)
            if value then
                local ok, detail = apply_value(key, kind, value)
                capture_result(report, key, ok, detail)
                if ok and migrated_speed then
                    dependencies.log_info("Migrated legacy Rocket Speed default 1.277 -> neutral 1.0.")
                end
            else report.invalid = report.invalid + 1 end
        end
    end
    -- Split the legacy combined driver control only when the new key is absent.
    -- Explicit saved OFF always wins. Existing range values never become seconds.
    if not content:find("vehicle_chernobog_driver|t|",1,true) then
        local old=content:match("vehicle_driver_weapons|t|([^\r\n|]+)")
        if (old == "1" or old == "true" or old == "0" or old == "false")
            and dependencies.feature_ref("vehicle_chernobog_driver") then
            capture_result(report, "vehicle_chernobog_driver", apply_value("vehicle_chernobog_driver", "t", old=="1" or old=="true"))
        end
    end
    if dependencies.Weapons and type(dependencies.Weapons.SyncLoadoutPicker) == "function" then
        dependencies.Weapons.SyncLoadoutPicker()
    end
    local message = ("Loaded %d saved settings; %d failed, %d invalid, %d retired entries ignored.")
        :format(report.applied, report.failed, report.invalid, report.retired_ignored)
    if notify ~= false then notify_load_result(report, false) end
    if report.failed > 0 then dependencies.log_warn(message) else dependencies.log_info(message) end
    for _, failure in ipairs(report.failures) do
        dependencies.log_warn("Setting not restored: " .. failure.key .. "; " .. failure.reason)
    end
    if notify == true then request_perf_capture() end
    return true, report.applied, report
end

local function disable_all_toggles()
    local report = new_report()
    report.retired = retire_features()
    for _, key in ipairs(dependencies.TOGGLE_KEYS) do
        if not is_retired_feature(key) and dependencies.feature_ref(key) then
            capture_result(report, key, apply_value(key, "t", false))
        end
    end
    if report.failed > 0 or report.retired.failed > 0 then
        return false, ("Toggle cleanup: %d failed, %d retired OFF failures.")
            :format(report.failed, report.retired.failed), report
    end
    return true, nil, report
end

local function add_toggle(key, name, description, default, callback)
    local feature = FeatureMgr.AddFeature(
        dependencies.feature_id(key), name, eFeatureType.Toggle, description or "", callback
    )
    if feature and type(feature.SetDefaultValue) == "function" then
        pcall(function()
            feature:SetDefaultValue(default == true)
            if default == true and type(feature.Toggle) == "function" and not feature:IsToggled() then
                feature:Toggle(true)
            end
        end)
    end
    ConfigStore.registered_count = ConfigStore.registered_count + 1
    return feature
end

local function add_button(key, name, description, callback)
    local feature = FeatureMgr.AddFeature(
        dependencies.feature_id(key), name, eFeatureType.Button, description or "", callback
    )
    ConfigStore.registered_count = ConfigStore.registered_count + 1
    return feature
end

local function register_features()
    if features_registered then return true end
    add_toggle("auto_load_config", "Auto Load On Startup", "Load saved settings when CScript starts.", ConfigStore.auto_load,
        function(feature)
            local ok, err = save_autoload_preference(feature:IsToggled())
            if not ok then dependencies.toast("Could not save autoload preference: " .. tostring(err), 6000) end
        end)
    add_button("save_config", "Save Current Settings", "Saves current CScript settings.", function()
        local ok, err = save_config_store()
        if ok then dependencies.toast("Current settings saved.")
        else dependencies.toast("Settings save failed: " .. tostring(err), 6000) end
    end)
    add_button("load_config", "Load Saved Settings", "Loads only validated CScript settings from disk.", function()
        local ok, err = load_config_store(true)
        if not ok then dependencies.toast("Settings load failed: " .. tostring(err), 6000) end
    end)
    add_button("unload_cscript", "Unload CScript",
        "Restores CScript changes and stops Loader after cleanup finishes.", function()
            local runtime=module_context and module_context.CScript and module_context.CScript.Runtime
            if runtime and type(runtime.RequestUnload)=="function" then runtime.RequestUnload() end
        end)
    add_button("reset_config", "Reset Settings To Defaults", "Restores default CScript settings.", function()
        local runtime = module_context and module_context.CScript and module_context.CScript.Runtime
        if runtime and type(runtime.PanicReset) == "function" then runtime.PanicReset(false) end
        local ok, report = set_config_defaults()
        if dependencies.Weapons and type(dependencies.Weapons.SyncLoadoutPicker) == "function" then
            dependencies.Weapons.SyncLoadoutPicker()
        end
        if ok then dependencies.toast("Settings reset to defaults; saved file was not overwritten.", 5000)
        else dependencies.toast(("Defaults partially applied: %d failed, %d retired OFF failures; saved file unchanged.")
            :format(report.failed, report.retired.failed), 6000) end
    end)

    features_registered = true
    return ConfigStore.registered_count == 5
end

function Module.BindCompatibility(bindings)
    if not module_context then error("core.config must initialize before compatibility binding", 2) end
    if bound then return service end
    dependencies = bindings or {}
    for _, name in ipairs({
        "TOGGLE_KEYS", "CONFIG_COMBOS", "CONFIG_INTS", "CONFIG_FLOATS", "feature_ref", "is_on",
        "list_index", "slider_int", "slider_float", "set_toggle", "feature_id",
        "toast", "log_info", "log_warn", "Weapons",
    }) do require_binding(name, dependencies[name]) end
    load_autoload_preference()
    bound = true

    service.RegisterFeatures = register_features
    service.RegisteredCount = function() return ConfigStore.registered_count end
    service.SaveSettings = save_config_store
    service.LoadSettings = load_config_store
    service.SetDefaults = set_config_defaults
    service.DisableAllToggles = disable_all_toggles
    service.IsAutoLoadEnabled = function() return ConfigStore.auto_load end
    service.FinalizeStartup = function()
        if ConfigStore.auto_load then
            local ok, err, report = load_config_store(false)
            if ok then notify_load_result(report, true)
            else dependencies.log_warn("Autoload skipped: " .. tostring(err)) end
        else
            retire_features()
        end
        return true
    end
    return service
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.Cherax) ~= "table"
        or type(context.State) ~= "table" or type(context.Logger) ~= "table" then
        error("core.config requires injected Cherax, State, and Logger services")
    end

    module_context = context
    perf_generation = perf_generation + 1
    perf_stopped, perf_pending, perf_used_nonce = false, nil, nil
    local stores = {}
    local order = {}
    service = {
        CompatibilityOwned = false,
        IsRetiredFeature = is_retired_feature,
        RetiredFeatureKeys = retired_feature_keys,
        Formats = {
            Settings = { path = context.Root .. "\\settings.txt", encoding = "CSCRIPT_SETTINGS_V1" },
            Autoload = { path = context.Root .. "\\autoload.txt", encoding = "CSCRIPT_AUTOLOAD_V1" },
            Loadouts = { path = context.Root .. "\\loadouts.txt", encoding = "CSCRIPT_LOADOUT_V4" },
        },
    }

    function service.ReadText(path)
        return context.Cherax.ReadFile(path)
    end

    function service.WriteText(path, content)
        return context.Cherax.WriteFile(path, tostring(content), false)
    end

    function service.RegisterStore(owner, name, spec)
        owner = tostring(owner or "")
        name = tostring(name or "")
        if owner == "" or name == "" then return false, "owner/store name is required" end
        if type(spec) ~= "table" or type(spec.path) ~= "string" then
            return false, "config store requires a path"
        end
        if stores[name] then return false, "config store already registered: " .. name end
        stores[name] = { owner = owner, spec = spec }
        order[#order + 1] = name
        return true
    end

    function service.Load(name, default)
        local record = stores[tostring(name)]
        if not record then return false, "unknown config store: " .. tostring(name) end
        local content, err = service.ReadText(record.spec.path)
        if content == nil then return true, default, err end
        if type(record.spec.decode) ~= "function" then return true, content end
        local ok, value = pcall(record.spec.decode, content)
        if not ok then return false, tostring(value) end
        return true, value
    end

    function service.Save(name, value)
        local record = stores[tostring(name)]
        if not record then return false, "unknown config store: " .. tostring(name) end
        local content = value
        if type(record.spec.encode) == "function" then
            local ok, encoded = pcall(record.spec.encode, value)
            if not ok then return false, tostring(encoded) end
            content = encoded
        end
        return service.WriteText(record.spec.path, content)
    end

    function service.UnregisterOwner(owner)
        owner = tostring(owner)
        for index = #order, 1, -1 do
            local name = order[index]
            if stores[name] and stores[name].owner == owner then stores[name] = nil end
        end
    end

    context.Config = service
    context.Core.Config = service
    context.CScript.Config = service
    context.Modules.Config = Module
    context.State.Config.ServiceReady = true
    context.State.Config.CompatibilityOwned = false
end

function Module.Start() perf_stopped = false end
function Module.Stop()
    perf_stopped = true; perf_generation = perf_generation + 1; perf_pending = nil
end

function Module.Restore(context)
    perf_stopped = true; perf_generation = perf_generation + 1; perf_pending = nil
    context = context or module_context
    if context and context.State and context.State.Config then
        context.State.Config.ServiceReady = nil
        context.State.Config.CompatibilityOwned = nil
    end
    if context and context.Config == service then context.Config = nil end
    if context and context.Core and context.Core.Config == service then context.Core.Config = nil end
    if context and context.CScript and context.CScript.Config == service then context.CScript.Config = nil end
    if context and context.Modules and context.Modules.Config == Module then context.Modules.Config = nil end
    module_context = nil
    service = nil
    dependencies = nil
    bound = false
    features_registered = false
    ConfigStore = { path = nil, autoload_path = nil, auto_load = false, registered_count = 0 }
end

return Module
]====],
["CScript/core/events.lua"]=[====[
-- Central event ownership. Cherax callbacks remain directly registered; the
-- compatibility tick and hot collision handlers do not pass through this table.
local Module = { Name = "core.events", MigrationPhase = "17.75" }

local service, __public_stop, __public_context, __public_instance

local function require_id(value, label)
    if type(value) ~= "string" or value == "" then error(label .. " must be a non-empty string", 3) end
    return value
end

function Module.Init(context)
    if __public_stop then __public_stop() end
    if service then service.RestoreAll() end
    if type(context) ~= "table" or type(context.Cherax) ~= "table"
        or type(context.Cleanup) ~= "table" or type(context.SetFrameworkTick) ~= "function" then
        error("core.events requires injected Cherax, Cleanup, and tick services")
    end

    local authority = context.CScript and context.CScript.Entitlements
    local allowed = type(authority) == "table" and authority.IsAllowed
    assert(type(allowed) == "function", "Public event authorization is required")
    local stopped, retired = false, false
    __public_stop = function() stopped = true end
    local event_mgr = context.Cherax.Get("EventMgr")
    local lua_events = context.Raw.eLuaEvent
    local unload_event = lua_events and lua_events.ON_UNLOAD
    local node_event = lua_events and lua_events.CAN_APPLY_NODE_DATA
    local collision_event = lua_events and lua_events.SHOULD_COLLIDE
    local script_event = lua_events and lua_events.SCRIPTED_GAME_EVENT
    local records = {}
    local owner_order = {}
    local tick_snapshot = {}
    service = {}
    local service, instance = service, {}
    __public_context, __public_instance = context, instance

    local function owner_record(owner, create)
        local record = records[owner]
        if not record and create then
            record = { events = {}, ticks = {}, unloads = {}, order = {}, guards = {} }
            records[owner] = record
            owner_order[#owner_order + 1] = owner
        end
        return record
    end

    local function denied(event)
        if (node_event ~= nil and event == node_event)
            or (collision_event ~= nil and event == collision_event) then return true end
        if script_event ~= nil and event == script_event then return false end
        return nil
    end
    local function canonical_owner(owner)
        local name = owner:gsub("%.lua$", ""):gsub("/", ".")
        if name == "economy" then return "modules.economy_core" end
        return name:find(".", 1, true) and name or "modules." .. name
    end
    local function owned(owner, key, record, token)
        return __public_instance == instance
            and records[owner] == record and record.guards[key] == token
    end
    local function active(owner, key, record, token, cleanup)
        return token.ready and owned(owner, key, record, token)
            and not retired and (cleanup or not stopped)
    end
    local function release(record, key, token)
        token.ready = false
        if record.guards[key] == token then record.guards[key] = nil end
    end
    local function guarded(owner, key, event, callback, record, cleanup)
        assert(type(callback) == "function", "Public event callback is invalid")
        local token, module_name = {ready=false}, canonical_owner(owner)
        record.guards[key] = token
        local function wrap(target)
            assert(type(target) == "function", "Public event wrapper is invalid")
            return function(...)
                if not active(owner, key, record, token, cleanup) then return denied(event) end
                if not cleanup then
                    local ok, admitted = pcall(allowed, module_name, key)
                    if not ok or admitted ~= true then return denied(event) end
                    if not active(owner, key, record, token, cleanup) then return denied(event) end
                end
                return target(...)
            end
        end
        return wrap(callback), token, wrap
    end

    local function resolve_event(event)
        if type(event) ~= "string" then return event end
        if not lua_events then return nil end
        return lua_events[event] or lua_events["ON_" .. event]
    end

    local function refresh_ticks()
        local snapshot, seen = {}, {}
        for owner_index = 1, #owner_order do
            local record = records[owner_order[owner_index]]
            if record then
                for key_index = 1, #record.order do
                    local key = record.order[key_index]
                    local callback = record.ticks[key]
                    if callback and not seen[callback] then
                        seen[callback] = true
                        snapshot[#snapshot + 1] = callback
                    end
                end
            end
        end
        tick_snapshot = snapshot
        if __public_instance ~= instance then return end
        if #snapshot == 0 then
            context.SetFrameworkTick(nil)
            return
        end
        context.SetFrameworkTick(function()
            local current = tick_snapshot
            for index = 1, #current do current[index]() end
        end)
    end

    function service.Register(owner, key, event, callback)
        if retired or __public_instance ~= instance then
            return false, "Public event service is retired"
        end
        owner = require_id(owner, "event owner")
        key = require_id(key, "event key")
        if type(callback) ~= "function" then error("event callback must be a function", 2) end
        local resolved = resolve_event(event)
        if resolved == nil then return false, "Cherax event is unavailable: " .. tostring(event) end
        if not event_mgr or type(event_mgr.RegisterHandler) ~= "function" then
            return false, "Cherax EventMgr.RegisterHandler is unavailable"
        end
        local record = owner_record(owner, true)
        if record.events[key] or record.ticks[key] or record.unloads[key] or record.guards[key] then
            return false, ("event key already registered: %s/%s"):format(owner, key)
        end
        local cleanup = unload_event ~= nil and resolved == unload_event
        if retired or (stopped and not cleanup) then return false, "Public event service is stopped" end
        local token, wrap_callback
        callback, token, wrap_callback = guarded(owner, key, resolved, callback, record, cleanup)
        local performance = context.Performance
        if performance then
            local ok, measured = pcall(performance.Wrap, "event." .. owner .. "." .. key, callback, 127)
            if not ok or type(measured) ~= "function" then
                release(record, key, token)
                return false, "Public event instrumentation failed"
            end
            callback = wrap_callback(measured)
        end
        if not owned(owner, key, record, token) or retired or (stopped and not cleanup) then
            release(record, key, token)
            return false, "Public event registration was cancelled"
        end
        local ok, handler_id = pcall(event_mgr.RegisterHandler, resolved, callback)
        if not ok or handler_id == nil or handler_id == false then
            release(record, key, token)
            return false, tostring(handler_id)
        end
        if not owned(owner, key, record, token) or retired or (stopped and not cleanup) then
            if type(event_mgr.RemoveHandler) == "function" then pcall(event_mgr.RemoveHandler, handler_id) end
            release(record, key, token)
            return false, "Public event registration was cancelled"
        end
        token.ready = true
        record.events[key] = handler_id
        record.order[#record.order + 1] = key
        return true, handler_id
    end

    function service.RegisterHot(owner, key, event, callback)
        return service.Register(owner, key, event, callback)
    end

    function service.RegisterRender(owner, key, callback)
        return service.Register(owner, key, "ON_PRESENT", callback)
    end

    function service.RegisterSessionChange(owner, key, callback)
        return service.Register(owner, key, "ON_SESSION_CHANGE", callback)
    end

    function service.RegisterUnload(owner, key, callback)
        if retired or __public_instance ~= instance then
            return false, "Public event service is retired"
        end
        owner = require_id(owner, "event owner")
        key = require_id(key, "event key")
        if type(callback) ~= "function" then error("event callback must be a function", 2) end
        local record = owner_record(owner, true)
        if record.events[key] or record.ticks[key] or record.unloads[key] or record.guards[key] then
            return false, ("event key already registered: %s/%s"):format(owner, key)
        end
        local cleanup_key = "event-unload:" .. key
        if retired then return false, "Public event service is retired" end
        local token
        callback, token = guarded(owner, key, nil, callback, record, true)
        local called, ok, err = pcall(context.Cleanup.Register, owner, cleanup_key, callback)
        if not called or ok ~= true then
            release(record, key, token)
            return false, tostring(called and err or ok)
        end
        if not owned(owner, key, record, token) or retired then
            pcall(context.Cleanup.Release, owner, cleanup_key)
            release(record, key, token)
            return false, "Public cleanup registration was cancelled"
        end
        token.ready = true
        record.unloads[key] = cleanup_key
        record.order[#record.order + 1] = key
        return true
    end

    function service.RegisterTick(owner, key, callback)
        if retired or __public_instance ~= instance then
            return false, "Public event service is retired"
        end
        owner = require_id(owner, "tick owner")
        key = require_id(key, "tick key")
        if type(callback) ~= "function" then error("tick callback must be a function", 2) end
        local record = owner_record(owner, true)
        if record.events[key] or record.ticks[key] or record.unloads[key] or record.guards[key] then
            return false, ("event key already registered: %s/%s"):format(owner, key)
        end
        local performance = context.Performance
        if stopped or retired then return false, "Public event service is stopped" end
        local wrapped, token, wrap_callback = guarded(owner, key, nil, callback, record, false)
        if performance then
            local ok, measured = pcall(performance.Wrap, "framework." .. owner, wrapped, 61)
            if not ok or type(measured) ~= "function" then
                release(record, key, token)
                return false, "Public tick instrumentation failed"
            end
            wrapped = wrap_callback(measured)
        end
        if not owned(owner, key, record, token) or stopped or retired then
            release(record, key, token)
            return false, "Public tick registration was cancelled"
        end
        record.ticks[key] = wrapped
        record.order[#record.order + 1] = key
        local ok, err = pcall(refresh_ticks)
        if not ok or not owned(owner, key, record, token) or stopped or retired then
            if record.ticks[key] == wrapped then record.ticks[key] = nil end
            release(record, key, token)
            pcall(refresh_ticks)
            return false, tostring(err or "Public tick registration cancelled")
        end
        token.ready = true
        return true
    end

    function service.Unregister(owner, key)
        local record = records[tostring(owner)]
        key = tostring(key)
        if not record then return false end
        local was_guarded = record.guards[key] ~= nil
        if was_guarded then release(record, key, record.guards[key]) end
        local handler_id = record.events[key]
        if handler_id ~= nil then
            record.events[key] = nil
            if event_mgr and type(event_mgr.RemoveHandler) == "function" then pcall(event_mgr.RemoveHandler, handler_id) end
            return true
        end
        if record.ticks[key] then
            record.ticks[key] = nil
            refresh_ticks()
            return true
        end
        if record.unloads[key] then
            context.Cleanup.Release(tostring(owner), record.unloads[key])
            record.unloads[key] = nil
            return true
        end
        return was_guarded
    end

    function service.UnregisterOwner(owner)
        owner = tostring(owner)
        local record = records[owner]
        if not record then return true end
        records[owner] = nil
        for _, handler_id in pairs(record.events) do
            if event_mgr and type(event_mgr.RemoveHandler) == "function" then pcall(event_mgr.RemoveHandler, handler_id) end
        end
        for _, cleanup_key in pairs(record.unloads) do context.Cleanup.Release(owner, cleanup_key) end
        refresh_ticks()
        return true
    end

    function service.RestoreAll()
        stopped, retired = true, true
        for index = #owner_order, 1, -1 do
            local owner = owner_order[index]
            if records[owner] then service.UnregisterOwner(owner) end
        end
        for index = #owner_order, 1, -1 do owner_order[index] = nil end
    end

    function service.CountTicks()
        return #tick_snapshot
    end

    context.Events = service
    context.Core.Events = service
    context.CScript.Events = service
end

function Module.Start() end

function Module.Stop(context)
    if context ~= nil and context ~= __public_context then return false end
    context = __public_context
    if __public_stop then __public_stop() end
    if context and type(context.SetFrameworkTick) == "function" then context.SetFrameworkTick(nil) end
end

function Module.Restore(context)
    if context ~= nil and context ~= __public_context then return false end
    context = __public_context
    local restoring_service, restoring_instance = service, __public_instance
    if __public_stop then __public_stop() end
    if restoring_service then restoring_service.RestoreAll() end
    if __public_instance ~= restoring_instance then return false end
    if context and type(context.SetFrameworkTick) == "function" then context.SetFrameworkTick(nil) end
    if __public_instance ~= restoring_instance then return false end
    if context and context.Events == restoring_service then context.Events = nil end
    if context and context.Core and context.Core.Events == restoring_service then context.Core.Events = nil end
    if context and context.CScript and context.CScript.Events == restoring_service then context.CScript.Events = nil end
    service, __public_stop, __public_context, __public_instance = nil, nil, nil, nil
end

return Module
]====],
["CScript/core/logger.lua"]=[====[
-- Shared user-facing copy and disabled technical logging.
local Module = { Name = "core.logger", MigrationPhase = "17.75" }
local service
local presentation

local PURPOSE = {
    ["Instant Finish"] = "Instantly finish the heist. Wait until the minimap is active before using.",
    ["Dismember Vehicle"] = "Detaches doors, hood and trunk, and shatters windows.",
    ["Remote Godmode"] = "Attempts to protect the selected player while control is available.",
    ["Remove Passive Mode"] = "Requests passive-mode removal through a compatible loaded script.",
    ["Clear Ghosted to You"] = "Clears players ghosted to you while on foot and outside an organization.",
    ["Join Their CEO / MC"] = "Leaves your organization and joins the selected player's CEO or MC.",
    ["Kick From Organization"] = "Requests removal of the selected player from their CEO or MC.",
    ["Forced Camera Recovery"] = "Automatically restores an invalid camera.",
    ["Record Cherax Alerts"] = "Keeps recent protection alerts in memory.",
    ["Log Protection Status"] = "Shows the current protection status.",
    ["Auto Accept Confirmation"] = "Accepts confirmation screens; quit and leave-to-Story prompts remain manual.",
    ["Hunter Camera (Legacy)"] = "Hunter Cannon controls its camera automatically.",
    ["Instant Lock-On"] = "Currently unavailable.",
    ["Lock Onto Players"] = "Adds players and their vehicles as homing targets.",
    ["Lock Onto NPCs"] = "Adds NPCs and their vehicles as homing targets.",
    ["Lifetime (s)"] = "Sets new-shot duration; 0 keeps the normal duration.",
    ["Buff All Rockets"] = "Applies Deluxo rocket behavior to supported rocket weapons.",
    ["Power Multiplier"] = "Adjusts driving torque and aircraft acceleration assistance.",
    ["Ruiner Pimp"] = "Spawns Ruiner vehicles around the selected player.",
    ["Penis"] = "Spawns vehicles around the selected player.",
    ["About CScript"] = "Shows the current CScript version.",
}

local function clean(value)
    return tostring(value or ""):gsub("[%c]", " "):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
end

local function technical(text)
    local lower = text:lower()
    for _, token in ipairs({".lua", ".log", "stack traceback", "0x", "backend", "pointer", "signature", "source-backed",
        "read-back", "readback", "unverified", "verified", "runtime", "native", "thread", "probe", "contract", "17.75", "previous build", "v1.3", "live_retest", "phase=", "module=", "error=", "journal", "migration",
        "filemgr", "featuremgr", "natives.", "native.invoke", "api ", "api-", "diagnostic", "receipt", "sha256", "fingerprint",
        ".txt", ".json", ".dll", ".exe", ".ini", "bad argument", "attempt to ", "nil value", "[string", "cscriptruntime", "cscriptdata", "cscriptbuilds", "cscript_runtime", "scriptglobal", "scriptlocal", "c:\\", "d:\\"}) do
        if lower:find(token, 1, true) then return true end
    end
    return lower:find("[%w_]+=[%w_]") ~= nil or lower:find("[%w_]+%.[%w_]+%(") ~= nil
        or text:find("%u[%u%d]+_[%u%d_]+") ~= nil or lower:find("%a:[/\\]") ~= nil
end

local function message(raw, kind, fallback)
    local text = clean(raw)
    if text == "" then return "" end
    -- Preserve explicit Baller fault diagnostics, including native/chunk details.
    if text:match('^Baller stopped:') or text:match('^Baller blocked:') then
        return text:sub(1,320)
    end
    if text:match("^CScript %d+%.%d+[%.%d]*$") then return text end
    local first = text:match("^(.-[.!?])%s") or text
    if #first <= 160 and not technical(first) then return first end
    local lower = text:lower()
    if lower:find("cleanup", 1, true) or lower:find("restoration", 1, true) or lower:find("restore pending", 1, true) then
        return "Cleanup is still in progress. Try again shortly."
    elseif lower:find("organization", 1, true) and (lower:find("full", 1, true) or lower:find("capacity", 1, true)) then
        return "The organization is full. Try again later."
    elseif lower:find("disconnect", 1, true) or lower:find("target left", 1, true) then
        return "The player is no longer available. Select another player."
    elseif lower:find("already running", 1, true) or lower:find("already registered", 1, true) then
        return "CScript is already running. Unload it before trying again."
    elseif lower:find("save", 1, true) and (lower:find("failed", 1, true) or lower:find("rejected", 1, true) or lower:find("cannot", 1, true)) then
        return "Could not save your changes. Try again."
    elseif lower:find("session", 1, true) and lower:find("transition", 1, true) then
        return "Wait for the session to finish loading, then try again."
    elseif lower:find("control", 1, true) and (lower:find("denied", 1, true) or lower:find("unavailable", 1, true)) then
        return "Could not control the target. Try again."
    elseif lower:find("startup", 1, true) or lower:find("preflight", 1, true) then
        return "CScript could not start. Unload it and try again."
    end
    if fallback and clean(fallback) ~= "" and not technical(clean(fallback)) then return clean(fallback) end
    if kind == "success" then return "Check the result in game." end
    if kind == "warning" or kind == "error" then return "Could not complete the action. Try again." end
    return "This action is currently unavailable."
end

local function description(name, original)
    name = clean(name)
    if PURPOSE[name] then return PURPOSE[name] end
    local text = clean(original)
    local lower = text:lower()
    if lower:find("unavailable", 1, true) or lower:find("retired", 1, true) then return "Currently unavailable." end
    -- Select complete, plain purpose sentences; never cut a technical sentence mid-claim.
    for sentence in (text .. " "):gmatch("(.-[.!?])%s+") do
        local sentence = clean(sentence)
        if #sentence > 0 and #sentence <= 150 and not technical(sentence)
            and not sentence:lower():find("now ", 1, true) and not sentence:lower():find("previous", 1, true)
            and not sentence:lower():find("repaired", 1, true) and not sentence:lower():find("fixed", 1, true) then return sentence end
    end
    if text ~= "" and #text <= 150 and not technical(text) then return text end
    if name == "" then return "" end
    if name:lower():find("save", 1, true) then return "Saves the current settings." end
    if name:lower():find("teleport", 1, true) then return "Moves you to the selected destination." end
    return "Use " .. name:gsub("%.$", "") .. "."
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.Raw) ~= "table" or type(context.State) ~= "table" then
        error("core.logger requires injected Raw and State services")
    end
    local once = context.State.Core.LogOnce or {}
    context.State.Core.LogOnce = once
    service = {}
    local function disabled() return true end
    service.Info, service.Warn, service.Error = disabled, disabled, disabled
    local function once_only(key, text)
        key, text = tostring(key), tostring(text)
        if once[key] == text then return false end
        once[key] = text
        return true
    end
    service.ErrorOnce, service.WarnOnce = once_only, once_only
    function service.ClearOnce(key)
        if key == nil then for item in pairs(once) do once[item] = nil end
        else once[tostring(key)] = nil end
    end
    presentation = { Description = description, Message = message }
    context.Core.PresentationCopy = presentation
    context.CScript.PresentationCopy = presentation
    context.Logger, context.Core.Logger, context.CScript.Logger = service, service, service
end

function Module.Start() end
function Module.Stop() end
function Module.Restore(context)
    if service then service.ClearOnce() end
    if context and context.Logger == service then context.Logger = nil end
    if context and context.Core then
        if context.Core.Logger == service then context.Core.Logger = nil end
        if context.Core.PresentationCopy == presentation then context.Core.PresentationCopy = nil end
    end
    if context and context.CScript then
        if context.CScript.Logger == service then context.CScript.Logger = nil end
        if context.CScript.PresentationCopy == presentation then context.CScript.PresentationCopy = nil end
    end
end
return Module
]====],
["CScript/core/notifications.lua"]=[====[
-- Unified, presentation-agnostic notification queue.
-- Producers enqueue concise messages; modules.ui is the only renderer.
local Module = { Name = "core.notifications", MigrationPhase = "17.75" }

local context
local service
local next_id = 0
local queue = {}
local enabled, protection_enabled = true, true

local TYPES = {
    info = { name = "Info", priority = 10 },
    success = { name = "Success", priority = 20 },
    warning = { name = "Warning", priority = 30 },
    error = { name = "Error", priority = 40 },
    protection = { name = "Blocked", priority = 25 },
}

local function normalize_type(value)
    local key = tostring(value or "info"):lower()
    if not TYPES[key] then key = "info" end
    return key, TYPES[key]
end

local function compact_queue()
    while #queue > 24 do
        local drop_index, drop_priority = 1, math.huge
        for index, item in ipairs(queue) do
            local priority = tonumber(item.priority) or 0
            if priority < drop_priority then
                drop_index, drop_priority = index, priority
            end
        end
        table.remove(queue, drop_index)
    end
end

local function push(message, duration, kind, priority, title, detail, domain)
    if not enabled then return nil, "Notifications are disabled." end
    message = tostring(message or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if message == "" then return nil, "notification message is empty" end
    local type_key, spec = normalize_type(kind)
    if type_key == "protection" and not protection_enabled then return nil, "Protection notifications are disabled." end
    local copy = context and context.Core and context.Core.PresentationCopy
    if copy then message = copy.Message(message, type_key) end
    title, detail = spec.name, ""
    duration = math.max(1200, math.min(15000, tonumber(duration) or 4200))
    if type_key == "warning" then duration = math.max(duration, 6000) end
    if type_key == "error" then duration = math.max(duration, 7500) end
    priority = math.max(0, math.min(100, tonumber(priority) or spec.priority))
    domain = tostring(domain or ""):lower():gsub("[^%w%-%._]", "-"):sub(1, 80)

    -- Coalesce an identical warning/error without hiding distinct faults. The
    -- repeat counter keeps recurring failures visible without stacking copies.
    for _, item in ipairs(queue) do
        if item.kind == type_key and item.message == message then
            item.repeat_count = math.min(9999, (tonumber(item.repeat_count) or 1) + 1)
            item.duration_ms = math.min(15000, math.max(item.duration_ms or 0, duration)
                + ((type_key == "warning" or type_key == "error") and 900 or 0))
            item.priority = math.max(item.priority, priority)
            item.started_seconds = nil
            item.elapsed_ms = 0
            item.last_visible_seconds = nil
            item.title = tostring(title or spec.name)
            item.detail = tostring(detail or item.detail or ""):gsub("[\r\n]+", " "):sub(1, 120)
            if domain ~= "" then item.domain = domain end
            return item.id
        end
    end

    -- Information from a single lifecycle domain supersedes its obsolete prior
    -- information (for example Vehicle Studio preparing -> ready). Warnings and
    -- errors are deliberately excluded so distinct faults remain independently visible.
    if domain ~= "" and (type_key == "info" or type_key == "success") then
        for _, item in ipairs(queue) do
            if item.domain == domain and (item.kind == "info" or item.kind == "success") then
                item.kind = type_key
                item.title = tostring(title or spec.name)
                item.message = message
                item.detail = tostring(detail or ""):gsub("[\r\n]+", " "):sub(1, 120)
                item.duration_ms = duration
                item.priority = priority
                item.repeat_count = 1
                item.started_seconds = nil
                item.elapsed_ms = 0
                item.last_visible_seconds = nil
                return item.id
            end
        end
    end

    next_id = next_id + 1
    local item = {
        id = next_id,
        kind = type_key,
        title = tostring(title or spec.name),
        message = message,
        duration_ms = duration,
        priority = priority,
        domain = domain ~= "" and domain or nil,
        repeat_count = 1,
        started_seconds = nil,
        elapsed_ms = 0,
        last_visible_seconds = nil,
        detail = tostring(detail or ""):gsub("[\r\n]+", " "):sub(1, 120),
    }
    queue[#queue + 1] = item
    compact_queue()
    return item.id
end

local function snapshot(now_seconds, maximum)
    if not enabled then return {} end
    if __CSCRIPT_PREBOOT_SUPPRESS_NOTIFICATIONS == true then
        -- Keep queued startup notifications intact, but do not start/advance their
        -- visible lifetime while the real preboot owns the screen.
        for _, item in ipairs(queue) do item.last_visible_seconds = nil end
        return {}
    end
    now_seconds = tonumber(now_seconds) or 0
    maximum = math.max(1, math.min(6, tonumber(maximum) or 4))
    local alive = {}
    for _, item in ipairs(queue) do
        local elapsed_ms = math.max(0, tonumber(item.elapsed_ms) or 0)
        if item.last_visible_seconds ~= nil then
            elapsed_ms = elapsed_ms + math.max(0, (now_seconds - item.last_visible_seconds) * 1000)
        end
        item.elapsed_ms = elapsed_ms
        item.last_visible_seconds = nil
        if elapsed_ms < item.duration_ms then
            alive[#alive + 1] = item
        end
    end
    table.sort(alive, function(a, b)
        if a.priority == b.priority then return a.id < b.id end
        return a.priority > b.priority
    end)
    queue = alive
    local result = {}
    for index = 1, math.min(maximum, #alive) do
        local item = alive[index]
        if item.started_seconds == nil then item.started_seconds = now_seconds end
        item.last_visible_seconds = now_seconds
        item.progress = math.max(0, math.min(1, item.elapsed_ms / item.duration_ms))
        result[index] = item
    end
    return result
end

local function dismiss(id)
    id = tonumber(id)
    for index = #queue, 1, -1 do
        if queue[index].id == id then table.remove(queue, index); return true end
    end
    return false
end

local function clear()
    queue = {}
    return true
end

function Module.Init(module_context)
    if type(module_context) ~= "table" or type(module_context.CScript) ~= "table" then
        error("core.notifications received an invalid context")
    end
    context = module_context
    enabled, protection_enabled = true, true
    service = {
        Push = push,
        Info = function(message, duration, priority, domain) return push(message, duration, "info", priority, nil, nil, domain) end,
        Success = function(message, duration, priority, domain) return push(message, duration, "success", priority, nil, nil, domain) end,
        Warning = function(message, duration, priority, domain) return push(message, duration, "warning", priority, nil, nil, domain) end,
        Error = function(message, duration, priority, domain) return push(message, duration, "error", priority, nil, nil, domain) end,
        Protection = function(label)
            label = tostring(label or "Incoming traffic"):gsub("[\r\n]+", " "):sub(1, 84)
            return push(label .. " blocked.", 3200, "protection", nil, nil, nil, "protection")
        end,
        SetEnabled = function(value)
            enabled = value == true
            if not enabled then clear() end
            return enabled
        end,
        SetProtectionEnabled = function(value)
            protection_enabled = value == true
            if not protection_enabled then
                for index = #queue, 1, -1 do
                    if queue[index].kind == "protection" then table.remove(queue, index) end
                end
            end
            return protection_enabled
        end,
        IsEnabled = function() return enabled end,
        Detailed = function(message, detail, duration, kind, priority, title, domain)
            return push(message, duration, kind, priority, title, detail, domain)
        end,
        Snapshot = snapshot,
        Dismiss = dismiss,
        Clear = clear,
        Count = function() return #queue end,
    }
    module_context.Notifications = service
    module_context.CScript.Notifications = service
    module_context.Core.Notifications = service
end

function Module.Start() end
function Module.Stop() end

function Module.Restore(module_context)
    module_context = module_context or context
    clear()
    if module_context and module_context.CScript and module_context.CScript.Notifications == service then
        module_context.CScript.Notifications = nil
    end
    if module_context and module_context.Core and module_context.Core.Notifications == service then
        module_context.Core.Notifications = nil
    end
    if module_context and module_context.Notifications == service then module_context.Notifications = nil end
    context, service = nil, nil
end

return Module
]====],
["CScript/core/runtime.lua"]=[====[
-- Cross-domain runtime coordinator.
-- Owns the single compatibility scheduler, panic/session orchestration, and
-- overlay sampling cadence. Domain modules remain the owners of gameplay state.
local Module = { Name = "core.runtime", MigrationPhase = "17.75" }

local module_context
local public_api
local dependencies
local started = false
local bound = false

local State = {
    last_fast_tick = 0,
    last_slow_tick = 0,
    last_overlay_sample = 0,
    panicking = false,
    health = {
        tick_count = 0,
        last_tick_ms = 0,
        last_frame_ms = 0,
        last_fast_ms = 0,
        last_slow_ms = 0,
        repair_count = 0,
        master_errors = 0,
        identity = { ped = 0, model = 0, pending_ped = 0, pending_model = 0, pending_since_ms = 0 },
        repair_queue = {},
        last_repair_ms = { Player = -100000, Vehicle = -100000, Weapons = -100000 },
        last_repair_reason = nil,
    },
    frame_domains = { UI = true, Player = true, World = true, Weapons = true, Vehicle = true },
    diagnostic_actions = {},
    trace = { active = false, counts = {}, kind = "api" },
    test_session = {
        enabled = false,
        session_id = 0,
        sequence = 0,
        events = {},
        pending = {},
        counts = {},
        dropped = 0,
        controls = {},
        control_order = {},
    },
    combat = {
        sequence = 0,
        events = {},
        by_signature = {},
        dropped = 0,
        dirty = false,
        last_flush_ms = -100000,
        last_path = nil,
        last_error = nil,
        generation = 0,
    },
    interop = {
        compatibility_mode = false,
        manual_isolation = { Vehicle = false, Weapons = false, OptionalBuiltins = false, Player = false, World = false },
        requires_revalidation = { Vehicle = false, Weapons = false, OptionalBuiltins = false, Player = false, World = false },
    },
}

local DOMAIN_ORDER = { "UI", "Player", "World", "Weapons", "Vehicle" }
local INTEROP_DOMAIN_ORDER = { "Vehicle", "Weapons", "OptionalBuiltins", "Player", "World" }
local COMPATIBILITY_DOMAINS = { Vehicle = true, Weapons = true, OptionalBuiltins = true }
local MAX_DIAGNOSTIC_ACTIONS = 12
local TRACE_DURATION_MS = 10000
local INTEROP_TRACE_DURATION_MS = 30000
local TEST_EVENT_LIMIT = 512
local TEST_PENDING_LIMIT = 64
local TEST_CONTROL_LIMIT = 384
local COMBAT_EVENT_LIMIT = 256
local COMBAT_COALESCE_MS = 5000
local COMBAT_FLUSH_MS = 5000
local RUNTIME_REPAIR_COOLDOWN_MS = 1500
local IDENTITY_STABLE_MS = 120
local IDENTITY_SAMPLE_MS = 250
local COMBAT_QUIET_MS = 2000
