        local app_sale = type(snap.active_sale)=="table" and type(snap.active_sale.bunker_app_start)=="table"
            and snap.active_sale.bunker_app_start or {}
        local farm = type(snap.bunker_farm)=="table" and snap.bunker_farm or {}
        local raw = module_context and module_context.Raw or {}
        local natives = raw.Natives
        local economy = cscript and cscript.Economy
        local slot = economy and type(economy.CurrentSlot) == "function" and economy.CurrentSlot() or nil
        local bank, wallet
        local gb_request,gb_current,gb_route,gb_var1,gb_var2,gb_var3,gb_mission_hash,app_threads,gun_threads
        local app_flags,app_bunker,app_page,app_stage,app_scaleform
        local globals,utils,gta,locals=raw.ScriptGlobal,raw.Utils,raw.GTA,
