                if app_threads==1 and locals and type(locals.GetInt)=="function" then
                    local function al(index)local ok,v=pcall(locals.GetInt,ah,index);return ok and tonumber(v) or nil end
                    app_flags=al(147);app_bunker=al(159);app_page=al(160);app_stage=al(161);app_scaleform=al(340)
                end
            end
        end
        if natives and type(natives.InvokeInt) == "function" and (slot == 0 or slot == 1) then
            local bok, b = pcall(natives.InvokeInt, 0x76EF28DA05EA395A)
            local wok, w = pcall(natives.InvokeInt, 0xA40F9C2623F6A8B5, slot)
            bank = bok and tonumber(b) or nil
            wallet = wok and tonumber(w) or nil
        end
        return {
            selected = snap.selected_business,
            owned = status.owned,
            stock = status.stock ~= nil and status.stock or reads.PRODTOTALFORFACTORY5,
            supplies = status.supplies ~= nil and status.supplies or reads.MATTOTALFORFACTORY5,
            setup = reads.FACTORYSETUP5,
            mission = reads.MISSIONFORFACTORY5,
            bank = bank,
            wallet = wallet,
            balance = bank and wallet and (bank + wallet) or nil,
            auto_supplies = modes.auto_supplies,
            fast_production = modes.fast_production,
            supply_pending = modes.supply_pending,
            sale_start_phase = sale_start.phase,
            sale_start_route = sale_start.route,
            sale_start_destination = sale_start.destination,
            sale_start_reason = sale_start.reason,
            app_sale_phase = app_sale.phase,
            app_sale_reason = app_sale.reason,
            app_sale_selection = app_sale.last_selection,
            farm_active = farm.active,
            farm_phase = farm.phase,
            farm_cycles = farm.cycles,
            farm_last_stock = farm.last_stock,
            farm_last_supplies = farm.last_supplies,
            farm_last_balance_delta = farm.last_balance_delta,
            farm_last_cycle_payout = farm.last_cycle_payout,
            farm_reason = farm.reason,
            gb_request=gb_request,gb_current=gb_current,gb_route=gb_route,
            gb_var1=gb_var1,gb_var2=gb_var2,gb_var3=gb_var3,gb_mission_hash=gb_mission_hash,
            app_threads=app_threads,gun_threads=gun_threads,
            app_flags=app_flags,app_bunker=app_bunker,app_page=app_page,
            app_stage=app_stage,app_scaleform=app_scaleform,
            queued_actions = snap.queued_actions,
        }
    end

    local function bridge_response(id, verb, ok, detail)
