        local row = bridge_snapshot()
        local payload = '{"ok":' .. bridge_json_bool(ok == true)
            .. ',"verb":"' .. bridge_escape(verb) .. '"'
            .. ',"detail":"' .. bridge_escape(detail or '') .. '"'
