            .. ',"owned":' .. bridge_json_bool(row.owned)
            .. ',"stock":' .. bridge_json_number(row.stock)
            .. ',"supplies":' .. bridge_json_number(row.supplies)
            .. ',"setup":' .. bridge_json_number(row.setup)
            .. ',"mission":' .. bridge_json_number(row.mission)
            .. ',"bank":' .. bridge_json_number(row.bank)
            .. ',"wallet":' .. bridge_json_number(row.wallet)
            .. ',"balance":' .. bridge_json_number(row.balance)
            .. ',"auto_supplies":' .. bridge_json_bool(row.auto_supplies)
            .. ',"fast_production":' .. bridge_json_bool(row.fast_production)
            .. ',"supply_pending":' .. bridge_json_bool(row.supply_pending)
            .. ',"sale_start_phase":"' .. bridge_escape(row.sale_start_phase or "") .. '"'
            .. ',"sale_start_route":' .. bridge_json_number(row.sale_start_route)
            .. ',"sale_start_destination":"' .. bridge_escape(row.sale_start_destination or "") .. '"'
            .. ',"sale_start_reason":"' .. bridge_escape(row.sale_start_reason or "") .. '"'
