            .. ',"farm_cycles":' .. bridge_json_number(row.farm_cycles)
            .. ',"farm_last_stock":' .. bridge_json_number(row.farm_last_stock)
            .. ',"farm_last_supplies":' .. bridge_json_number(row.farm_last_supplies)
            .. ',"farm_last_balance_delta":' .. bridge_json_number(row.farm_last_balance_delta)
            .. ',"farm_last_cycle_payout":' .. bridge_json_number(row.farm_last_cycle_payout)
            .. ',"farm_reason":"' .. bridge_escape(row.farm_reason or "") .. '"'
            .. ',"gb_request":' .. bridge_json_number(row.gb_request)
            .. ',"gb_current":' .. bridge_json_number(row.gb_current)
            .. ',"gb_route":' .. bridge_json_number(row.gb_route)
            .. ',"gb_var1":' .. bridge_json_number(row.gb_var1)
            .. ',"gb_var2":' .. bridge_json_number(row.gb_var2)
            .. ',"gb_var3":' .. bridge_json_number(row.gb_var3)
            .. ',"gb_mission_hash":' .. bridge_json_number(row.gb_mission_hash)
            .. ',"app_threads":' .. bridge_json_number(row.app_threads)
            .. ',"gun_threads":' .. bridge_json_number(row.gun_threads)
            .. ',"app_flags":' .. bridge_json_number(row.app_flags)
            .. ',"app_bunker":' .. bridge_json_number(row.app_bunker)
            .. ',"app_page":' .. bridge_json_number(row.app_page)
            .. ',"app_stage":' .. bridge_json_number(row.app_stage)
            .. ',"app_scaleform":' .. bridge_json_number(row.app_scaleform)
            .. ',"queued_actions":' .. bridge_json_number(row.queued_actions) .. '}\n'
        local wrote, result = pcall(files.WriteFileContent, root .. "\\response_" .. id .. ".json", payload, false)
        return wrote and result ~= false
    end

    -- This receipt deliberately samples only the bounded performance APIs.
    -- It never invokes the gameplay/business snapshot used by other commands.
    local function bridge_perf_scalar(value)
        if type(value)=="boolean" then return bridge_json_bool(value) end
        if type(value)=="number" then return bridge_json_number(value) end
        if type(value)=="string" then
            return '"'..bridge_escape(clean_test_text(value,256))..'"'
        end
        return "null"
    end
    local function bridge_perf_object(row,fields)
        if type(row)~="table" then return "null" end
        local parts={}
        for _,key in ipairs(fields) do
            parts[#parts+1]='"'..key..'":'..bridge_perf_scalar(row[key])
        end
        return "{"..table.concat(parts,",").."}"
    end
    local function bridge_perf_table(row,fields,row_fields)
        if type(row)~="table" then return "null" end
        local body=bridge_perf_object(row,fields)
        local rows={}
        for i=1,math.min(64,#(row.rows or {})) do
            rows[#rows+1]=bridge_perf_object(row.rows[i],row_fields)
        end
        return body:sub(1,-2)..',"rows":['..table.concat(rows,",").."]}"
    end
    local function bridge_perf_sample(callback)
        if type(callback)~="function" then return nil end
        local ok,value=pcall(callback)
        return ok and type(value)=="table" and value or nil
    end
    local function bridge_status_snapshot(owner,name,method)
        local context=module_context
        local root=context and context.CScript
        local lifecycle=context and context.Runtime
        local function current()
            local domain=context and context.State and context.State[name]
            return started==true and bound==true and not State.unload
                and context==module_context and root and public_api~=nil and root.Runtime==public_api
                and context.Runtime==lifecycle and lifecycle and lifecycle.phase=="ready"
                and lifecycle.callbacks_enabled==true and not lifecycle.stopping and not lifecycle.stopped
                and root[name]==owner and type(domain)=="table" and domain.Started==true
        end
        if not current() or type(owner)~="table" or type(owner[method])~="function" then return nil end
        local callback=owner[method]
        -- Use only the published API, preserving its own authorization/lifecycle
        -- guards. Denied, throwing, replaced or retired owners produce null.
        local snapshot=bridge_perf_sample(callback)
        if not current() or owner[method]~=callback then return nil end
        return snapshot
    end
    local function bridge_perf_response(id,verb,ok,detail)
        local files,root=bridge_storage();if not files then return false end
        local performance=module_context and module_context.Performance
        local runtime=bridge_perf_sample(public_api and public_api.PerformanceSnapshot)
        local callbacks=bridge_perf_sample(performance and performance.Snapshot)
        local capture=bridge_perf_sample(performance and performance.CaptureSnapshot)
        local vehicle=module_context and module_context.CScript and module_context.CScript.Vehicle
        local flight=bridge_perf_sample(vehicle and vehicle.VehicleFlySnapshot)
        local weapons=module_context and module_context.CScript and module_context.CScript.Weapons
        local ammo=bridge_perf_sample(weapons and weapons.AmmoSnapshot)
        local names={}
        for _,name in ipairs(enabled_features()) do
            names[#names+1]=bridge_perf_scalar(name)
        end
        local status_fields=""
        if verb=="PERF_SNAPSHOT" and ok==true then
            local clear=bridge_status_snapshot(World,"World","ClearAreaSnapshot")
            local spawn=bridge_status_snapshot(Protections,"Protections","SpawnSnapshot")
            local clear_json=bridge_perf_object(clear,{"active","status","reason","verified_gone",
                "pending","remaining","failed","skipped_control","protected","unverified","already_gone",
                "native_errors","submitted_calls","failed_no_submission","failed_survived","cancelled_pending"})
            if clear then
                local samples={}
                local source=type(clear.failure_samples)=="table" and clear.failure_samples or {}
                for i=1,math.min(8,#source) do
                    samples[#samples+1]=bridge_perf_object(source[i],{"kind","model","attempts","submitted",
                        "submitted_calls","last_stage","last_error","authority"})
                end
                clear_json=clear_json:sub(1,-2)..',"stage_errors":'..bridge_perf_object(clear.stage_errors,
                    {"mission","allocation","write","typed","generic","control","free"})
                    ..',"failure_samples":['..table.concat(samples,",").."]}"
            end
            local spawn_json=bridge_perf_object(spawn,{"available","registered","armed","queued",
                "removal_pending","position_ready","radius","entries","creates","updates","blocked_total",
                "rejected_total","internal_errors","unresolved","traffic_observed"})
            if spawn then
                spawn_json=spawn_json:sub(1,-2)..',"enabled":'..bridge_perf_object(spawn.enabled,{"vehicle","ped","object"})
                    ..',"blocked":'..bridge_perf_object(spawn.blocked,{"vehicle","ped","object"})
                    ..',"ingress":'..bridge_perf_object(spawn.ingress,{"observed","host_entries","disabled_entries",
                        "authorization_denied","lifecycle_denied","forwarded","native_id","event","callbacks_enabled"}).."}"
            end
            status_fields=',"clear_area":'..clear_json..',"spawn_protection":'..spawn_json
        end
        local payload='{"schema_version":1,"ok":'..bridge_json_bool(ok==true)
            ..',"verb":'..bridge_perf_scalar(verb)..',"detail":'..bridge_perf_scalar(detail)
            ..',"enabled_features":['..table.concat(names,",")..']'
            ..',"game_fps":{"measured":false}'
            ..',"flight":'..bridge_perf_object(flight,{"status","level","boosted","requested_speed",
                "command_speed","measured_speed","observed_speed","previous_command_speed",
                "previous_boosted","previous_level","view","cockpit","look_x","look_y"})
            ..',"ammo":'..bridge_perf_object(ammo,{"status","requested","total","clip","ammo_type",
                "reported_max","verified","limited","method"})
            ..',"runtime":'..bridge_perf_table(runtime,
                {"unit","enabled","label","ticks","since_ms","sample_limit","row_limit","dropped_labels"},
                {"label","count","mean","p50","p95","max","sample_count"})
            ..',"callbacks":'..bridge_perf_table(callbacks,{"clock","inclusive","fps_measurement"},
                {"label","calls","samples","sampled_ms","mean_ms","maximum_ms","stride"})
            ..',"capture":'..bridge_perf_table(capture,
                {"id","label","clock","inclusive","fps_measurement","complete","elapsed_ms","duration_ms"},
                {"label","calls","samples","total_ms","mean_ms","maximum_ms","calls_per_second","ms_per_second"})
            ..status_fields.."}\n"
        local wrote,result=pcall(files.WriteFileContent,root.."\\response_"..id..".json",payload,false)
        return wrote and result~=false
    end
    local function complete_perf_bridge(now)
        local pending=dev_bridge.capture
        if not pending or (now>=pending.started_ms and now<pending.until_ms) then return end
        local performance=module_context and module_context.Performance
        local snap=bridge_perf_sample(performance and performance.CaptureSnapshot)
        if not snap or snap.complete~=true then return end
        -- One completion receipt replaces the initial acknowledgement.
        dev_bridge.capture=nil
        bridge_perf_response(pending.id,"PERF_START",true,"Capture complete.")
    end
    local function process_perf_bridge(verb,id,text,now)
        if verb~="PERF_START" and verb~="PERF_SNAPSHOT" then return false end
        local ok,detail=false,"Invalid performance command arguments."
        if verb=="PERF_SNAPSHOT" then
            if text:match("^[^|]+|[%w_%-]+$") then
                ok,detail=true,"Performance snapshot captured."
            end
        else
            local value=text:match("^[^|]+|[%w_%-]+|(%d+)$")
            local duration=value and tonumber(value)
            local performance=module_context and module_context.Performance
            if duration and duration>=1000 and duration<=30000 and duration%1==0 then
                if dev_bridge.capture then detail="Performance capture already active."
                elseif not performance or type(performance.StartCapture)~="function"
                    or not public_api or type(public_api.ResetPerformanceWindow)~="function" then
                    detail="Performance API unavailable."
                else
                    local called,a,b=pcall(performance.StartCapture,duration,"devbridge_"..id)
                    if called and a==true then
                        public_api.ResetPerformanceWindow("devbridge_"..id)
                        if State.performance then State.performance.capture_until=now+duration end
                        dev_bridge.capture={id=id,started_ms=now,until_ms=now+duration}
                        ok,detail=true,"Capture started."
                    else detail=tostring(called and (b or a) or a) end
                end
            end
        end
        bridge_perf_response(id,verb,ok,detail)
        return true
    end

    local function process_dev_bridge(now)
        if now - dev_bridge.last_poll_ms < 100 then return end
        dev_bridge.last_poll_ms = now
        local files, root = bridge_storage(); if not files then return end
        local command_path = root .. "\\command.txt"
        local exists_ok, exists = pcall(files.DoesFileExist, command_path)
        if not exists_ok or exists ~= true then return end
        local read_ok, text = pcall(files.ReadFileContent, command_path)
        pcall(files.DeleteFile, command_path)
        if not read_ok or type(text) ~= "string" or #text < 3 or #text > 256 then return end
        text = text:gsub("[\r\n]+$", "")
        local parts = {}; for part in text:gmatch("[^|]+") do parts[#parts + 1] = part end
        local verb, id = tostring(parts[1] or ""):upper(), tostring(parts[2] or "")
        if #id < 1 or #id > 64 or not id:match("^[%w_%-]+$") then return end
        if process_perf_bridge(verb,id,text,now) then return end
        local cscript = module_context and module_context.CScript
        local businesses = cscript and cscript.Businesses
        local automation = cscript and cscript.BusinessAutomation
        local ok, detail = false, "Unknown command."
        if verb == "PING" or verb == "SNAPSHOT" then
            ok, detail = true, verb == "PING" and "CScript runtime command bridge is ready." or "Snapshot captured."
        elseif verb == "REFRESH_BUNKER" then
            if businesses and type(businesses.SelectBusiness) == "function" then pcall(businesses.SelectBusiness, "bunker") end
            if businesses and type(businesses.Refresh) == "function" then
                local called, a, b = pcall(businesses.Refresh, "bunker")
                ok = called and a == true; detail = tostring(called and (b or a) or a)
            else detail = "Business API unavailable." end
        elseif verb == "SALE_READINESS" then
            if businesses and type(businesses.SaleReadiness)=='function' then
                local called,a,b=pcall(businesses.SaleReadiness);ok=called and a==true;detail=tostring(called and (b or a) or a)
            else detail='Sale readiness API unavailable.' end
        elseif verb == "WAREHOUSE_LAPTOP" then
            local teleports=cscript and cscript.Teleports
            if teleports and type(teleports.OpenWarehouseComputer)=='function' then
                local called,a,b=pcall(teleports.OpenWarehouseComputer,tonumber(parts[3]),tonumber(parts[4]))
                ok=called and a==true;detail=tostring(called and (b or a) or a)
            else detail='Warehouse computer API unavailable.' end
        elseif verb == "AUTOMATION" then
            local mode, enabled = tostring(parts[3] or ""), parts[4] == "1"
            if parts[4] ~= "0" and parts[4] ~= "1" then
                detail = "AUTOMATION requires 0 or 1."
            elseif automation and type(automation.Request) == "function" then
                local called, a, b = pcall(automation.Request, mode, "bunker", enabled)
                ok = called and a == true; detail = tostring(called and (b or a) or a)
            else detail = "Business automation API unavailable." end
        elseif verb == "START_BUNKER_APP_SALE" then
            if businesses and type(businesses.StartBunkerAppSale) == "function" then
                local called,a,b=pcall(businesses.StartBunkerAppSale)
                ok=called and a==true;detail=tostring(called and (b or a) or a)
            else detail="Bunker app sale API unavailable." end
        elseif verb == "START_BUNKER_FARM" then
            local repeat_mode = parts[3] ~= "0"
            if businesses and type(businesses.StartBunkerFarm) == "function" then
                local called,a,b=pcall(businesses.StartBunkerFarm,repeat_mode)
                ok=called and a==true;detail=tostring(called and (b or a) or a)
            else detail="Bunker Auto Farm API unavailable." end
        elseif verb == "STOP_BUNKER_FARM" then
            if businesses and type(businesses.StopBunkerFarm) == "function" then
                local called,a,b=pcall(businesses.StopBunkerFarm,"Stopped from DevBridge.")
                ok=called and a==true;detail=tostring(called and (b or a) or a)
            else detail="Bunker Auto Farm API unavailable." end
        elseif verb == "COMPLETE_SALE" then
            if businesses and type(businesses.CompleteActiveSale) == "function" then
                local called, a, b = pcall(businesses.CompleteActiveSale)
                ok = called and a == true; detail = tostring(called and (b or a) or a)
            else detail = "Business completion API unavailable." end
        elseif verb == "BUNKER_ENTRANCE" then
            local teleports = cscript and cscript.Teleports
            if teleports and type(teleports.TeleportDestination) == "function" then
                local called, a, b = pcall(teleports.TeleportDestination, "bunker")
                ok = called and a == true; detail = tostring(called and (b or a) or a)
            else
                detail = "Teleport Manager API unavailable."
            end
        elseif verb == "BUNKER_LAPTOP" then
            local raw = module_context and module_context.Raw or {}
            local natives, utils = raw.Natives, raw.Utils
            if not natives or type(natives.InvokeInt) ~= "function" or type(natives.InvokeVoid) ~= "function"
                or not utils or type(utils.Joaat) ~= "function" then
                detail = "Native teleport APIs unavailable."
            else
                local hash = utils.Joaat("am_mp_bunker")
                local threads = natives.InvokeInt(0x2C83A9DA6BFFC4F9, hash)
                if tonumber(threads) ~= 1 then
                    detail = "Bunker interior controller is not active."
                else
                    local ped = natives.InvokeInt(0xD80958FC74E988A6)
                    if type(ped) ~= "number" or ped <= 0 then
                        detail = "Local ped unavailable."
                    else
                        -- Use the laptop interaction area at floor height to avoid placing the ped inside the chair.
                        natives.InvokeVoid(0x239A3351AC1DA385, ped, 907.75335, -3207.2976, -98.18789, false, false, true)
                        natives.InvokeVoid(0x8E2530AA8ADA980E, ped, 24.1997)
                        ok, detail = true, "Moved to the Bunker laptop interaction area."
                    end
                end
            end
        else
            detail = "Unsupported fixed command: " .. verb
        end
        bridge_response(id, verb, ok, detail)
    end

    local function record_combat_diagnostic(category, action, detail, severity)
        local combat = State.combat
        if type(combat) ~= "table" then return false end
        local now = now_ms()
        combat.last_event_ms = now
        category = clean_test_text(category or "Combat", 80)
        action = clean_test_text(action or "transition", 96)
        detail = clean_test_text(detail or "", 320)
        severity = tostring(severity or "INFO"):upper()
        if severity ~= "PASS" and severity ~= "WARN" and severity ~= "FAIL" then severity = "INFO" end
        local signature = table.concat({ severity, category, action, detail }, "|")
        local previous = combat.by_signature[signature]
        if previous and now - (tonumber(previous.last_ms) or -100000) <= COMBAT_COALESCE_MS then
            previous.count = (tonumber(previous.count) or 1) + 1
            previous.last_ms = now
            combat.dirty = true
            return previous.sequence
        end
        combat.sequence = (tonumber(combat.sequence) or 0) + 1
        local item = {
            sequence = combat.sequence,
            first_ms = now,
            last_ms = now,
            count = 1,
            severity = severity,
            category = category,
            action = action,
            detail = detail,
            signature = signature,
        }
        combat.events[#combat.events + 1] = item
        combat.by_signature[signature] = item
        while #combat.events > COMBAT_EVENT_LIMIT do
            local removed = table.remove(combat.events, 1)
            if removed and combat.by_signature[removed.signature] == removed then
                combat.by_signature[removed.signature] = nil
            end
            combat.dropped = (tonumber(combat.dropped) or 0) + 1
        end
        combat.dirty = true
        return item.sequence
    end

    local function combat_diagnostic_snapshot()
        local combat = State.combat
        local recent = {}
        for index = math.max(1, #combat.events - 7), #combat.events do
            local item = combat.events[index]
            if item then
                recent[#recent + 1] = {
                    sequence = item.sequence,
                    severity = item.severity,
                    category = item.category,
                    action = item.action,
                    detail = item.detail,
                    count = item.count,
                }
            end
        end
        return {
            event_count = #combat.events,
            limit = COMBAT_EVENT_LIMIT,
            dropped = tonumber(combat.dropped) or 0,
            dirty = combat.dirty == true,
            generation = tonumber(combat.generation) or 0,
            last_path = combat.last_path,
            last_error = combat.last_error,
            recent = recent,
        }
    end

    local function current_test_context()
        local ui = module_context and module_context.CScript and module_context.CScript.UI
        if ui and type(ui.CurrentContext) == "function" then
            local ok, value = pcall(ui.CurrentContext)
            if ok and type(value) == "table" then
                return clean_test_text((value.category or "Unknown") .. " / " .. (value.page or "Unknown"), 96)
            elseif ok and value then
                return clean_test_text(value, 96)
            end
        end
        return "Unknown / Unknown"
    end

    local function append_test_event(event)
        local trace = State.test_session
        trace.sequence = (tonumber(trace.sequence) or 0) + 1
        event.sequence = trace.sequence
        event.at_ms = tonumber(event.at_ms) or now_ms()
        event.status = TEST_STATUSES[tostring(event.status)] and tostring(event.status) or "SUCCESS_UNVERIFIED"
        event.module = clean_test_text(event.module or "Unknown", 80)
        event.feature = clean_test_text(event.feature or "Unknown", 120)
        event.action = clean_test_text(event.action or "action", 96)
        event.context = clean_test_text(event.context or current_test_context(), 96)
        event.detail = clean_test_text(event.detail or "", TEST_CONTROL_LIMIT)
        trace.events[#trace.events + 1] = event
        trace.counts[event.status] = (tonumber(trace.counts[event.status]) or 0) + 1
        while #trace.events > TEST_EVENT_LIMIT do
            table.remove(trace.events, 1)
            trace.dropped = (tonumber(trace.dropped) or 0) + 1
        end
        return event.sequence
    end

    local function set_test_session_enabled(enabled)
        local trace = State.test_session
        enabled = enabled == true
        if trace.enabled == enabled then return true end
        if enabled then
            trace.enabled = true
            trace.session_id = (tonumber(trace.session_id) or 0) + 1
            trace.sequence, trace.events, trace.pending, trace.counts, trace.dropped = 0, {}, {}, {}, 0
            trace.started_at_ms = now_ms()
            trace.finished_at_ms, trace.last_path, trace.last_error = nil, nil, nil
            append_test_event({
                status = "SUCCESS_VERIFIED",
                module = "Runtime",
                feature = "Test Session Trace",
                action = "enabled",
                detail = "bounded session-local tracing enabled"
            })
            return true
        end
        local pending = trace.pending
        for token, item in pairs(pending) do
            append_test_event({
                status = "CANCELLED",
                module = item.module,
                feature = item.feature,
                action = item.action,
                context = item.context,
                started_at_ms = item.started_at_ms,
                duration_ms = math.max(0, now_ms() - (tonumber(item.started_at_ms) or now_ms())),
                detail = "trace disabled while action remained pending"
            })
            pending[token] = nil
        end
        append_test_event({
            status = "SUCCESS_VERIFIED",
            module = "Runtime",
            feature = "Test Session Trace",
            action = "disabled",
            detail = "trace stopped cleanly"
        })
        trace.enabled = false
        trace.finished_at_ms = now_ms()
        return true
    end

    local function begin_test_action(module_name, feature_name, action, detail, feature_hash)
        local trace = State.test_session
        if not trace.enabled then return nil end
        local pending_count = 0
        for _ in pairs(trace.pending) do pending_count = pending_count + 1 end
        if pending_count >= TEST_PENDING_LIMIT then
            append_test_event({
                status = "FAILED",
                module = "Runtime",
                feature = "Test Session Trace",
                action = "begin",
                detail = "bounded pending-action limit reached"
            })
            return nil
        end
        trace.next_token = (tonumber(trace.next_token) or 0) + 1
        local token = trace.next_token
        trace.pending[token] = {
            module = clean_test_text(module_name or "Unknown", 80),
            feature = clean_test_text(feature_name or "Unknown", 120),
            action = clean_test_text(action or "action", 96),
            detail = clean_test_text(detail or "", TEST_CONTROL_LIMIT),
            feature_hash = tonumber(feature_hash),
            context = current_test_context(),
            started_at_ms = now_ms(),
        }
        return token
    end

    local function end_test_action(token, status, detail, result)
        local trace = State.test_session
        local item = token and trace.pending[token]
        if not item then return false end
        trace.pending[token] = nil
        local now = now_ms()
        return append_test_event({
            status = status,
            module = item.module,
            feature = item.feature,
            action = item.action,
            context = item.context,
            feature_hash = item.feature_hash,
            started_at_ms = item.started_at_ms,
            duration_ms = math.max(0, now - item.started_at_ms),
            detail = (item.detail ~= "" and (item.detail .. " | ") or "") ..
                clean_test_text(detail or "", TEST_CONTROL_LIMIT),
            result = clean_test_text(result or "", 96),
            at_ms = now,
        }) ~= nil
    end

    local function record_test_event(status, module_name, feature_name, action, detail)
        if not State.test_session.enabled then return false end
        append_test_event({
            status = status,
            module = module_name,
            feature = feature_name,
            action = action,
            detail = detail
        })
        return true
    end

    local function register_control_audit(spec)
        spec = type(spec) == "table" and spec or {}
        local hash = tonumber(spec.hash)
        local key = hash and tostring(hash) or clean_test_text(spec.key or spec.name or "logical", 120)
        local trace = State.test_session
        if trace.controls[key] then return false, "duplicate control audit key" end
        if #trace.control_order >= TEST_CONTROL_LIMIT then return false, "control audit limit reached" end
        trace.controls[key] = {
            hash = hash,
            name = clean_test_text(spec.name or "Unknown", 120),
            module = clean_test_text(spec.module or "Unknown", 80),
            feature_type = clean_test_text(spec.feature_type or "Unknown", 48),
            description = clean_test_text(spec.description or "", 220),
            callback = spec.callback == true,
            player = spec.player == true,
            logical = spec.logical == true,
        }
        trace.control_order[#trace.control_order + 1] = key
        return true
    end

    local function clear_test_session()
        local trace = State.test_session
        trace.sequence, trace.events, trace.pending, trace.counts, trace.dropped = 0, {}, {}, {}, 0
        trace.started_at_ms = trace.enabled and now_ms() or nil
        trace.finished_at_ms, trace.last_path, trace.last_error = nil, nil, nil
        if trace.enabled then
            append_test_event({
                status = "SUCCESS_VERIFIED",
                module = "Runtime",
                feature = "Test Session Trace",
                action = "cleared",
                detail = "event buffer reset"
            })
        end
        return true
    end

    local function test_session_snapshot()
        local trace = State.test_session
        local pending_count = 0
        for _ in pairs(trace.pending) do pending_count = pending_count + 1 end
        local counts = {}
        for key in pairs(TEST_STATUSES) do counts[key] = tonumber(trace.counts[key]) or 0 end
        local recent = {}
        for index = math.max(1, #trace.events - 7), #trace.events do
            local item = trace.events[index]
            if item then
                recent[#recent + 1] = {
                    sequence = item.sequence,
                    status = item.status,
                    module = item.module,
                    feature = item.feature,
                    action = item.action,
                    detail = item.detail,
                    context = item.context,
                    duration_ms = item.duration_ms,
                }
            end
        end
        return {
            enabled = trace.enabled == true,
            session_id = tonumber(trace.session_id) or 0,
            event_count = #trace.events,
            pending_count = pending_count,
            control_count = #trace.control_order,
            dropped = tonumber(trace.dropped) or 0,
            counts = counts,
            recent = recent,
            last_path = trace.last_path,
            last_error = trace.last_error,
            limit = TEST_EVENT_LIMIT,
        }
    end

    local function record_api_call(label, amount)
        if not State.trace.active then return false end
        label = tostring(label or "")
        if label == "" then return false end
        State.trace.counts[label] = (tonumber(State.trace.counts[label]) or 0) + (tonumber(amount) or 1)
        return true
    end

    enabled_features = function()
        local result = {}
        if type(is_on) ~= "function" then return result end
        for _, key in ipairs(toggle_keys) do
            local ok, enabled = pcall(is_on, key)
            if ok and enabled == true then result[#result + 1] = tostring(key) end
        end
        table.sort(result)
        return result
    end

    local function write_verified_trace(content, stamp, prefix)
        return false, "Technical file logging is disabled."
    end

    local function safe_snapshot(callback)
        if type(callback) ~= "function" then return {} end
        local ok, value = pcall(callback)
        return ok and type(value) == "table" and value or {}
    end

    local function combat_diagnostic_report()
        local combat = State.combat
        local diagnostics = module_context and module_context.CScript and module_context.CScript.Diagnostics or {}
        local composition = safe_snapshot(Vehicle.CompositionSnapshot)
        local projectiles = safe_snapshot(Vehicle.ProjectileDiagnosticsSnapshot)
        local melee = safe_snapshot(Player.SuperMeleeDiagnostics)
        local controller = type(composition.controller) == "table" and composition.controller or {}
        local desired = type(controller.desired) == "table" and controller.desired or {}
        local effective = type(controller.effective) == "table" and controller.effective or {}
        local backend = type(controller.backend) == "table" and controller.backend or {}
        local status = type(controller.status) == "table" and controller.status or {}
        local lines = {
            "CSCRIPT_COMBAT_DIAGNOSTICS_V1",
            "Runtime=" .. clean_test_text(diagnostics.LoaderVersion or "Unavailable", 120),
            "Build=" .. clean_test_text(diagnostics.BuildId or "Unavailable", 120),
            "Loader=" .. clean_test_text(diagnostics.DesktopLoaderVersion or diagnostics.LoaderVersion or "Unavailable", 40),
            "Generation=" ..
            tostring(module_context and module_context.Runtime and module_context.Runtime.generation or combat
                .generation or 0),
            "GeneratedAt=" .. timestamp_label((os and os.time and os.time()) or 0),
            "Privacy=session-local state only; no credentials, IP addresses, or persistent player identity",
            "Classification=SOURCE/HARNESS REPAIRED - LIVE RETEST REQUIRED",
            "EventLimit=" .. tostring(COMBAT_EVENT_LIMIT),
            "Events=" .. tostring(#combat.events),
            "Dropped=" .. tostring(combat.dropped or 0),
            "",
            "[context]",
            "LocalPed=" .. tostring(controller.ped or 0),
            "LocalVehicle=" .. tostring(controller.vehicle or 0),
            "MountedWeapon=" .. tostring(controller.weapon_hash or composition.weapon_hash or 0),
            "WeaponInfo=" .. tostring(controller.weapon_ptr or composition.weapon_ptr or 0),
            "AmmoInfo=" .. tostring(controller.ammo_ptr or composition.ammo_ptr or 0),
            "PendingReason=" .. clean_test_text(controller.pending_reason or "none", 180),
            "",
            "[vehicle_combat]",
            "Feature|Desired|Effective|Backend|Status",
        }
        local feature_order = {
            "buff_all_rockets", "instant_lock", "lock_players", "lock_npcs",
            "infinite_lock_range", "rocket_speed", "rocket_range",
            "rapid_fire", "cannon_restoration",
        }
        for _, key in ipairs(feature_order) do
            lines[#lines + 1] = table.concat({ key, tostring(desired[key] == true),
                tostring(effective[key] == true), clean_test_text(backend[key] or "none", 60),
                clean_test_text(status[key] or "IDLE", 80) }, "|")
        end
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[cannon_timing]"
        local timing=type(composition.cannon_timing)=="table"and composition.cannon_timing or{}
        for _,key in ipairs({"manifest","supported_build","phase","active","binding_status","binding_error","cleanup_pending","has_obligations",
            "byte_obligations","terminal_published","terminal_flush_verified","byte_conflict","last_error"})do
            local value=timing[key]
            lines[#lines+1]=key.."="..clean_test_text(value==nil and"Unavailable"or value,180)
        end
        for index=1,4 do
            local site=type(timing.sites)=="table"and timing.sites[index]or{}
            lines[#lines+1]=("Site%d|name=%s|owned=%s|flush_pending=%s|error=%s"):format(index,
                clean_test_text(site.name or"Unavailable",60),tostring(site.owned==true),tostring(site.flush_pending==true),
                clean_test_text(site.error or"none",180))
        end
        lines[#lines+1]="Scope=four shared process-wide PLAYER_LAZER gates; cache ACK and byte restoration are separate"
        lines[#lines+1]=""
        lines[#lines + 1] = "[projectiles]"
        lines[#lines + 1] = "Observation=cached flight state only; no fresh identity, ownership or lifetime verification"
        for _, pair in ipairs({
            { "TrackedCount", projectiles.tracked_count }, { "ActiveTotal", projectiles.active_total },
            { "ActiveRows", projectiles.active_count }, { "ActiveLimit", projectiles.active_limit },
            { "ActiveTruncated", projectiles.active_truncated }, { "HistoryTotal", projectiles.history_total },
            { "HistoryRows", projectiles.history_count }, { "HistoryLimit", projectiles.history_limit },
            { "HistoryTruncated", projectiles.history_truncated },
        }) do
            local value = pair[2]
            lines[#lines + 1] = pair[1] .. "=" .. clean_test_text(value == nil and "Unavailable" or value, 60)
        end
        local function projectile_rows(kind, rows, fields)
            for index = 1, math.min(16, #rows) do
                local row, values = rows[index], { kind }
                for _, key in ipairs(fields) do
                    local value = row[key]
                    values[#values + 1] = key .. "=" .. clean_test_text(value == nil and "Unavailable" or value, 180)
                end
                lines[#lines + 1] = table.concat(values, "|")
            end
        end
        projectile_rows("Active", projectiles.active or {}, {
            "handle", "address", "model", "first_seen", "last_seen", "last_guidance_ms", "last_distance",
            "buff_guided_steps", "buff_target", "buff_target_address", "buff_target_lost",
            "fire_window_id", "fire_window_ms", "fire_window_target", "fire_window_target_address",
            "launch_generation", "launch_weapon", "launch_ammo", "template_ammo_ptr",
            "buff_missile_profile", "buff_guidance_authority", "owner_verified", "native_owner_query",
            "pending_resolution", "resolution_evidence",
            "first_loss_reason", "first_loss_ms", "first_loss_detail", "launch_sample_target", "launch_sample_target_address",
            "launch_lock_state", "launch_raw_target", "launch_target_address_known",
            "launch_pre_input_ms", "launch_pre_input_lock_state", "launch_pre_input_target", "launch_pre_input_target_address",
            "launch_pre_input_source_bound", "launch_pre_input_same_ms", "launch_fire_control", "launch_window_reason",
            "launch_window_ambiguous", "rearm_known_identity", "rearm_history_unavailable",
        })
        projectile_rows("History", projectiles.history or {}, {
            "handle", "address", "model", "first_seen_ms", "last_seen_ms", "end_sample_ms",
            "fire_window_ms", "weapon", "template_ammo_ptr", "target", "guided_steps", "reason",
            "expiry_cause", "guidance_authority", "missile_profile", "projectile_ammo_record",
            "last_distance", "last_guidance_ms", "buff_target_lost",
            "first_loss_reason", "first_loss_ms", "first_loss_detail", "launch_sample_target", "launch_sample_target_address",
            "launch_lock_state", "launch_raw_target", "launch_target_address_known",
            "launch_pre_input_ms", "launch_pre_input_lock_state", "launch_pre_input_target", "launch_pre_input_target_address",
            "launch_pre_input_source_bound", "launch_pre_input_same_ms", "launch_fire_control", "launch_window_reason",
            "launch_window_ambiguous", "fire_window_target", "fire_window_target_address",
            "rearm_known_identity", "rearm_history_unavailable", "native_owner_query", "owner_verified",
        })
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[super_melee]"
        for _, pair in ipairs({
            { "Strength",       melee.strength }, { "Backend", melee.backend },
            { "ModifierStatus", melee.modifier_status }, { "ModifierBaseline", melee.modifier_baseline },
            { "ModifierApplied", melee.modifier_applied }, { "PendingImpacts", melee.pending },
            { "OwnerReturns",    melee.owner_restores }, { "SwingId", melee.swing_id },
            { "LastTarget", melee.last_target }, { "LastOutcome", melee.last_outcome },
        }) do
            local value =
                pair[2]

            if value == nil then
                value = "Unavailable"
            end

            lines[#lines + 1] =
                tostring(pair[1])
                .. "="
                .. clean_test_text(
                    value,
                    180
                )
        end
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[events]"
        lines[#lines + 1] = "Sequence|FirstMs|LastMs|Count|Severity|Category|Action|Detail"
        for _, item in ipairs(combat.events) do
            lines[#lines + 1] = table.concat({ tostring(item.sequence), tostring(item.first_ms),
                tostring(item.last_ms), tostring(item.count), item.severity, item.category,
                item.action, item.detail }, "|")
        end
        return table.concat(lines, "\n")
    end

    local function export_combat_diagnostics(reason, notify)
        State.combat.last_path = nil
        State.combat.last_error = nil
        State.combat.last_flush_ms, State.combat.dirty = now_ms(), false
        return false, "Technical file logging is disabled."
    end

    local function run_combat_self_diagnostics()
        if type(Vehicle.RevalidateCombatBackends) == "function" then
            pcall(Vehicle.RevalidateCombatBackends)
        end
        local composition = safe_snapshot(Vehicle.CompositionSnapshot)
        local melee = safe_snapshot(Player.SuperMeleeDiagnostics)
        local controller = type(composition.controller) == "table" and composition.controller or {}
        local warnings, failures = 0, 0
        if not entity_exists(local_ped()) then warnings = warnings + 1 end
        if controller.pending_reason and controller.pending_reason ~= "none" then warnings = warnings + 1 end
        if tonumber(controller.vehicle or 0) ~= 0 and tonumber(controller.weapon_hash or 0) ~= 0
            and tonumber(controller.weapon_ptr or 0) == 0 then
            warnings = warnings + 1
        end
        if melee.modifier_status == "FAILED" then
            failures = failures + 1
        elseif melee.modifier_status == "PENDING" or melee.modifier_status == "UNAVAILABLE" then
            warnings = warnings + 1
        end
        local verdict = failures > 0 and "FAIL" or (warnings > 0 and "WARN" or "PASS")
        local detail = ("verdict=%s warnings=%d failures=%d ped=%s vehicle=%s weapon=%s weaponInfo=%s ammoInfo=%s pending=%s meleeBackend=%s modifier=%s")
            :format(verdict, warnings, failures, tostring(controller.ped or local_ped()),
                tostring(controller.vehicle or 0), tostring(controller.weapon_hash or 0),
                tostring(controller.weapon_ptr or composition.weapon_ptr or 0),
                tostring(controller.ammo_ptr or composition.ammo_ptr or 0),
                tostring(controller.pending_reason or "none"), tostring(melee.backend or "unavailable"),
                tostring(melee.modifier_status or "unavailable"))
        record_combat_diagnostic("Self Diagnostics", "safe read-only inspection", detail, verdict)
        local ok, path = export_combat_diagnostics("manual self-diagnostics", false)
        toast(ok and ("Combat self-diagnostics: " .. verdict) or "Combat self-diagnostics export failed.",
            5500, ok and (verdict == "FAIL" and "error" or (verdict == "WARN" and "warning" or "success")) or "error")
        return {
            verdict = verdict,
            warnings = warnings,
            failures = failures,
            detail = detail,
            exported = ok == true,
            path = ok and path or nil,
            error = ok and nil or tostring(path)
        }
    end

    local function test_session_report()
        local trace = State.test_session
        local diagnostics = module_context and module_context.CScript and module_context.CScript.Diagnostics or {}
        local ui = module_context and module_context.CScript and module_context.CScript.UI
        local memory = module_context and module_context.Memory
        local memory_stats = memory and type(memory.Stats) == "function" and memory.Stats() or {}
        local vehicle_manager = module_context and module_context.CScript and module_context.CScript.VehicleManager
        local vehicle = vehicle_manager and type(vehicle_manager.PreviewDiagnostics) == "function"
            and vehicle_manager.PreviewDiagnostics() or {}
        local player = module_context and module_context.CScript and module_context.CScript.Player
        local melee = player and type(player.SuperMeleeDiagnostics) == "function"
            and player.SuperMeleeDiagnostics() or {}
        local current = current_test_context()
        local lines = {
            "CSCRIPT_TEST_SESSION_TRACE_V1",
            "Runtime=" .. clean_test_text(diagnostics.LoaderVersion or "Unavailable", 120),
            "Build=" .. clean_test_text(diagnostics.BuildId or "Unavailable", 160),
            "Loader=" .. clean_test_text(diagnostics.DesktopLoaderVersion or diagnostics.LoaderVersion or "Unavailable", 40),
            "Generation=" ..
            tostring(module_context and module_context.Runtime and module_context.Runtime.generation or "Unavailable"),
            "SessionId=" .. tostring(trace.session_id or 0),
            "Enabled=" .. tostring(trace.enabled == true),
            "EventLimit=" .. tostring(TEST_EVENT_LIMIT),
            "Privacy=local-only; credentials, identifiers, IPs, and user-profile paths redacted",
            "EvidenceBoundary=SOURCE_OR_MOCK_ONLY_UNLESS_EXPLICITLY_RECORDED_SUCCESS_VERIFIED",
            "CurrentContext=" .. current,
            "PanicActive=" .. tostring(State.panicking == true),
            "",
            "[summary]",
            "Events=" .. tostring(#trace.events),
            "Dropped=" .. tostring(trace.dropped or 0),
        }
        for _, status in ipairs({ "SUCCESS_VERIFIED", "SUCCESS_UNVERIFIED", "FAILED", "UNAVAILABLE", "NO_OP", "CANCELLED" }) do
            lines[#lines + 1] = status .. "=" .. tostring(trace.counts[status] or 0)
        end
        local pending_count = 0
        for _ in pairs(trace.pending) do pending_count = pending_count + 1 end
        lines[#lines + 1] = "Pending=" .. tostring(pending_count)
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[owned_memory]"
        lines[#lines + 1] = "Owners=" .. tostring(memory_stats.owners or 0)
        lines[#lines + 1] = "Snapshots=" .. tostring(memory_stats.snapshots or 0)
        lines[#lines + 1] = "ExternallyModified=" .. tostring(memory_stats.externally_modified or 0)
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[active_handles]"
        lines[#lines + 1] = "VehicleStudioPhase=" .. clean_test_text(vehicle.phase or "Unavailable", 60)
        lines[#lines + 1] = "VehicleStudioLastStage=" .. clean_test_text(vehicle.last_stage or "Unavailable", 80)
        lines[#lines + 1] = "VehicleStudioPreviewVehicle=" .. tostring(vehicle.vehicle or 0)
        lines[#lines + 1] = "VehicleStudioCamera=" .. tostring(vehicle.camera or 0)
        lines[#lines + 1] = "SuperMeleePending=" .. tostring(melee.pending or 0)
        lines[#lines + 1] = "SuperMeleeOwnerRestores=" .. tostring(melee.owner_restores or 0)
        lines[#lines + 1] = "SuperMeleeLastOutcome=" .. clean_test_text(melee.last_outcome or "Unavailable", 100)
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[pending_actions]"
        if pending_count == 0 then lines[#lines + 1] = "None" end
        local pending_keys = {}
        for token in pairs(trace.pending) do pending_keys[#pending_keys + 1] = token end
        table.sort(pending_keys)
        for _, token in ipairs(pending_keys) do
            local item = trace.pending[token]
            lines[#lines + 1] = table.concat({ tostring(token), item.module, item.feature, item.action,
                item.context, tostring(item.started_at_ms or 0) }, "|")
        end
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[ordered_events]"
        lines[#lines + 1] = "Sequence|AtMs|DurationMs|Status|Module|Feature|Action|Context|Detail"
        for _, item in ipairs(trace.events) do
            lines[#lines + 1] = table.concat({
                tostring(item.sequence or 0), tostring(item.at_ms or 0), tostring(item.duration_ms or 0),
                item.status, item.module, item.feature, item.action, item.context, item.detail,
            }, "|")
        end
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[attention_required]"
        local attention = 0
        for _, item in ipairs(trace.events) do
            if item.status == "FAILED" or item.status == "UNAVAILABLE"
                or item.status == "SUCCESS_UNVERIFIED" then
                attention = attention + 1
                lines[#lines + 1] = table.concat({ tostring(item.sequence or 0), item.status,
                    item.module, item.feature, item.action, item.detail }, "|")
            end
        end
        if attention == 0 then lines[#lines + 1] = "None" end
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[control_audit]"
        lines[#lines + 1] = "ExpectedLogical=" .. tostring(diagnostics.Controls or "Unavailable")
        lines[#lines + 1] = "RegisteredAuditRows=" .. tostring(#trace.control_order)
        lines[#lines + 1] =
        "Hash|Module|Category|Page|Name|Type|Callback|Player|Logical|SourceStatus|RuntimeStatus|FailureBehavior"
        for _, key in ipairs(trace.control_order) do
            local item = trace.controls[key]
            local category, page = "Unmapped", "Unmapped"
            if ui and type(ui.ControlContext) == "function" then
                local ok, context = pcall(ui.ControlContext, item.hash, item.name)
                if ok and type(context) == "table" then
                    category = clean_test_text(context.category or category, 60)
                    page = clean_test_text(context.page or page, 80)
                end
            end
            local failure = item.callback and "callback boundary records FAILED without escaping into host UI"
                or "polled state; domain owner decides availability"
            lines[#lines + 1] = table.concat({
                item.hash and ("0x%08X"):format(item.hash) or "LOGICAL",
                item.module, category, page, item.name, item.feature_type,
                tostring(item.callback), tostring(item.player), tostring(item.logical),
                "SOURCE_VERIFIED", "LIVE_PENDING", failure,
            }, "|")
        end
        return table.concat(lines, "\n")
    end

    local function export_test_session_report()
        local trace = State.test_session
        local report = test_session_report()
        local now = now_ms()
        local ok, result = write_verified_trace(report,
            math.floor((os and os.time and os.time()) or now / 1000), "test-session-trace-")
        trace.last_path, trace.last_error = ok and result or nil, ok and nil or tostring(result)
        if ok then
            log_info(("Test Session Trace exported: events=%d controls=%d path=%s"):format(
                #trace.events, #trace.control_order, tostring(result)))
            toast("Test Session Trace exported and read-back verified.", 5000, "success")
        else
            log_error_once("test_session_trace_write", "Test Session Trace export failed: " .. tostring(result))
            toast("Test Session Trace export failed verification.", 6000, "error")
        end
        return ok, result
    end

    local function trace_report(now)
        local trace = State.trace
        local duration = math.max(0, (tonumber(now) or 0) - (tonumber(trace.started_at) or 0))
        local diagnostics = module_context and module_context.CScript and module_context.CScript.Diagnostics or {}
        local interop_trace = trace.kind == "kscript_interop"
        local lines = {
            interop_trace and "CSCRIPT_KSCRIPT_INTEROP_TRACE_V1" or "CSCRIPT_API_TRACE_V1",
            "Version=" .. tostring(diagnostics.LoaderVersion or "Unavailable"),
            "Build=" .. tostring(diagnostics.BuildId or "Unavailable"),
            ("DurationSeconds=%.1f"):format(duration / 1000),
            "SPDC_SCDCI_Status=NOT_REPRODUCED_ON_V0_7_3",
            "",
            "[frame_domains]",
        }
        for _, name in ipairs(DOMAIN_ORDER) do
            lines[#lines + 1] = name .. "=" .. (State.frame_domains[name] and "ENABLED" or "DISABLED")
        end
        if interop_trace then
            lines[#lines + 1] = ""
            lines[#lines + 1] = "[external_script_compatibility]"
            lines[#lines + 1] = "KScriptDetection=NOT_ATTEMPTED_MANUAL_MODE_ONLY"
            lines[#lines + 1] = "CompatibilityMode=" .. (State.interop.compatibility_mode and "ON" or "OFF")
            for _, name in ipairs(INTEROP_DOMAIN_ORDER) do
                local requested = State.interop.manual_isolation[name]
                    or (State.interop.compatibility_mode and COMPATIBILITY_DOMAINS[name])
                local pending = State.interop.requires_revalidation[name] == true
                lines[#lines + 1] = name .. "=" .. ((requested or pending) and "SUSPENDED" or "ACTIVE")
                    .. (pending and ";REVALIDATION_REQUIRED" or "")
            end
        end
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[enabled_frame_features]"
        if #(trace.enabled_features or {}) == 0 then lines[#lines + 1] = "None" end
        for _, key in ipairs(trace.enabled_features or {}) do lines[#lines + 1] = key end
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[aggregate_calls]"
        local keys = {}; for key in pairs(trace.counts or {}) do keys[#keys + 1] = key end; table.sort(keys)
        for _, key in ipairs(keys) do lines[#lines + 1] = key .. "=" .. tostring(trace.counts[key]) end
        return table.concat(lines, "\n")
    end

    local function finish_trace(now)
        if not State.trace.active then return false end
        State.trace.active = false
        State.trace.finished_at = now
        local report = trace_report(now)
        local interop_trace = State.trace.kind == "kscript_interop"
        local ok, result = write_verified_trace(report,
            math.floor((os and os.time and os.time()) or now / 1000),
            interop_trace and "kscript-interop-trace-" or "api-trace-")
        State.trace.last_report, State.trace.last_path, State.trace.last_error = report, ok and result or nil,
            ok and nil or result
        if ok then
            log_info(("API trace complete duration=%.1fs path=%s calls=%d"):format(
                math.max(0, now - (State.trace.started_at or now)) / 1000, tostring(result),
                (function()
                    local total = 0; for _, value in pairs(State.trace.counts) do total = total + value end; return total
                end)()))
            toast(interop_trace and "30-second K-Script interop trace saved and verified."
                or "10-second Cherax API trace saved and verified.", 5000)
        else
            log_error_once("api_trace_write", "API trace report write failed: " .. tostring(result))
            toast("API trace completed, but its report could not be verified.", 6000)
        end
        return ok, result
    end

    local function start_trace(duration_ms, kind)
        if State.trace.active then return false, "Cherax API trace is already running" end
        local now = now_ms()
        kind = kind == "kscript_interop" and "kscript_interop" or "api"
        local default_duration = kind == "kscript_interop" and INTEROP_TRACE_DURATION_MS or TRACE_DURATION_MS
        duration_ms = math.max(1000, math.min(60000, tonumber(duration_ms) or default_duration))
        State.trace = {
            active = true,
            kind = kind,
            started_at = now,
            ends_at = now + duration_ms,
            duration_ms = duration_ms,
            counts = {},
            enabled_features = enabled_features(),
        }
        return true
    end

    local function set_frame_domain(name, enabled)
        name = tostring(name or "")
        if State.frame_domains[name] == nil then return false, "unknown frame diagnostic domain" end
        State.frame_domains[name] = enabled == true
        return true
    end

    local function interop_requested(name)
        return State.interop.manual_isolation[name] == true
            or (State.interop.compatibility_mode == true and COMPATIBILITY_DOMAINS[name] == true)
    end

    local function runtime_write_allowed(name)
        name = tostring(name or "")
        if State.interop.manual_isolation[name] == nil then return true end
        if Protections and type(Protections.HighRiskWritesAllowed) == "function" then
            local ok, allowed = pcall(Protections.HighRiskWritesAllowed, name)
            if not ok then
                -- A protection-state read failure must not reopen a high-risk
                -- domain while its safety state is unknown.
                if name == "Vehicle" or name == "Weapons" or name == "OptionalBuiltins" then return false end
            elseif allowed == false then
                return false
            end
        end
        return not interop_requested(name) and State.interop.requires_revalidation[name] ~= true
    end

    local function domain_api(name)
        if name == "Vehicle" then return Vehicle end
        if name == "Weapons" then return Weapons end
        if name == "Player" then return Player end
        if name == "World" then return World end
        return nil
    end

    local function prepare_domain_suspend(name)
        local api = domain_api(name)
        local callback = api and api.SuspendRuntimeWrites
        if type(callback) ~= "function" and (name == "Player" or name == "World") then
            callback = api and api.PanicReset
        end
        if type(callback) == "function" then
            local ok, result, detail = pcall(callback)
            if not ok or result == false then
                return false, tostring(detail or result or "domain suspension failed")
            end
        end
        local memory = module_context and module_context.Memory
        if memory and type(memory.RestoreDomain) == "function" then
            local ok, result = pcall(memory.RestoreDomain, name)
            if not ok or result == false then return false, tostring(result or "owned-memory restoration failed") end
        end
        record_api_call(name .. ".RuntimeWritesSuspended")
        return true
    end

    local revalidate_interop_domain

    local function set_compatibility_mode(enabled)
        enabled = enabled == true
        if State.interop.compatibility_mode == enabled then return true end
        if enabled then
            for _, name in ipairs(INTEROP_DOMAIN_ORDER) do
                if COMPATIBILITY_DOMAINS[name] and not interop_requested(name)
                    and State.interop.requires_revalidation[name] ~= true then
                    local ok, err = prepare_domain_suspend(name)
                    if not ok then log_error_once("interop_suspend_" .. name, err) end
                end
            end
            State.interop.compatibility_mode = true
            log_info("External Script Compatibility enabled: Vehicle, Weapons, and Optional Built-ins suspended.")
            toast("K-Script Compatibility Mode enabled. High-risk CScript writes are suspended.", 5500)
        else
            State.interop.compatibility_mode = false

            local failures = {}

            for name in pairs(
                COMPATIBILITY_DOMAINS
            ) do
                if State.interop.manual_isolation[name] ~= true then
                    State.interop.requires_revalidation[name] = true

                    local ok, err =
                        revalidate_interop_domain(
                            name
                        )

                    if not ok then
                        failures[#failures + 1] =
                            name
                            .. ": "
                            .. tostring(err)
                    end
                end
            end

            if #failures > 0 then
                local detail =
                    table.concat(
                        failures,
                        " | "
                    )

                log_error_once(
                    "interop_resume",
                    detail
                )

                toast(
                    "Compatibility Mode disabled, but some CScript domains could not be revalidated.",
                    6500,
                    "warning"
                )

                return false, detail
            end

            log_info(
                "External Script Compatibility disabled; affected domains were automatically revalidated."
            )

            toast(
                "Compatibility Mode disabled. Suspended CScript domains resumed.",
                5000,
                "success"
            )
        end


        return true
    end

    local function set_interop_isolation(name, enabled)
        name = tostring(name or "")
        if State.interop.manual_isolation[name] == nil then return false, "unknown interop isolation domain" end
        enabled = enabled == true
        if enabled == State.interop.manual_isolation[name] then return true end
        if enabled and not interop_requested(name) and State.interop.requires_revalidation[name] ~= true then
            local ok, err = prepare_domain_suspend(name)
            if not ok then log_error_once("interop_manual_suspend_" .. name, err) end
        end
        State.interop.manual_isolation[name] =
            enabled

        if not enabled
            and not interop_requested(name) then
            State.interop.requires_revalidation[name] = true

            local ok, err =
                revalidate_interop_domain(
                    name
                )

            if not ok then
                return false,
                    tostring(err)
            end
        end

        return true
    end

    revalidate_interop_domain = function(name)
        name = tostring(name or "")
        if State.interop.manual_isolation[name] == nil then return false, "unknown interop isolation domain" end
        if interop_requested(name) then return false, name .. " is still explicitly suspended" end
        local memory = module_context and module_context.Memory
        if memory and type(memory.RevalidateDomain) == "function" then
            local ok, result = pcall(memory.RevalidateDomain, name)
            if not ok or result == false then return false, tostring(result or "memory revalidation failed") end
        end
        local api = domain_api(name)
        if api and type(api.RevalidateRuntimeState) == "function" then
            local ok, result, detail = pcall(api.RevalidateRuntimeState)
            if not ok or result == false then return false, tostring(detail or result or "module revalidation failed") end
        end
        if name == "OptionalBuiltins" and type(deps.revalidate_optional_builtins) == "function" then
            local ok, result = pcall(deps.revalidate_optional_builtins)
            if not ok or result == false then return false, tostring(result or "built-in revalidation failed") end
        end
        State.interop.requires_revalidation[name] = false
        record_api_call(name .. ".RuntimeStateRevalidated")
        return true
    end

    local function queue_diagnostic_action(kind, arguments)
        if #State.diagnostic_actions >= MAX_DIAGNOSTIC_ACTIONS then return false, "runtime diagnostic queue is full" end
        local action = { kind = tostring(kind or ""), arguments = {} }
        for key, value in pairs(type(arguments) == "table" and arguments or {}) do action.arguments[key] = value end
        local allowed = {
            set_domain = true,
            start_trace = true,
            start_interop_trace = true,
            set_compatibility = true,
            set_interop_isolation = true,
            revalidate_interop_domain = true,
        }
        if not allowed[action.kind] then return false, "unknown runtime diagnostic action" end
        State.diagnostic_actions[#State.diagnostic_actions + 1] = action
        return true
    end

    local function process_diagnostic_actions()
        local action = table.remove(State.diagnostic_actions, 1)
        if not action then return end
        local ok, err
        if action.kind == "set_domain" then
            ok, err = set_frame_domain(action.arguments.domain, action.arguments.enabled)
        elseif action.kind == "start_trace" then
            ok, err = start_trace(action.arguments.duration_ms, "api")
        elseif action.kind == "start_interop_trace" then
            ok, err = start_trace(action.arguments.duration_ms or INTEROP_TRACE_DURATION_MS, "kscript_interop")
        elseif action.kind == "set_compatibility" then
            ok, err = set_compatibility_mode(action.arguments.enabled)
        elseif action.kind == "set_interop_isolation" then
            ok, err = set_interop_isolation(action.arguments.domain, action.arguments.enabled)
        elseif action.kind == "revalidate_interop_domain" then
            ok, err = revalidate_interop_domain(action.arguments.domain)
        end
        if not ok then toast(tostring(err), 4500) end
    end

    local function diagnostic_snapshot()
        local domains, counts = {}, {}
        local any_disabled = false
        for _, name in ipairs(DOMAIN_ORDER) do
            domains[name] = State.frame_domains[name] == true
            any_disabled = any_disabled or not domains[name]
        end
        for key, value in pairs(State.trace.counts or {}) do counts[key] = value end
        local manual, suspended, revalidation = {}, {}, {}
        local any_interop = false
        for _, name in ipairs(INTEROP_DOMAIN_ORDER) do
            manual[name] = State.interop.manual_isolation[name] == true
            revalidation[name] = State.interop.requires_revalidation[name] == true
            suspended[name] = not runtime_write_allowed(name)
            any_interop = any_interop or suspended[name]
        end
        return {
            domains = domains,
            diagnostic_mode_active = any_disabled,
            trace = {
                active = State.trace.active == true,
                kind = State.trace.kind or "api",
                started_at = State.trace.started_at,
                ends_at = State.trace.ends_at,
                counts = counts,
                last_path = State.trace.last_path,
                last_error = State.trace.last_error,
            },
            health = {
                tick_count = tonumber(State.health and State.health.tick_count) or 0,
                last_tick_ms = tonumber(State.health and State.health.last_tick_ms) or 0,
                last_frame_ms = tonumber(State.health and State.health.last_frame_ms) or 0,
                last_fast_ms = tonumber(State.health and State.health.last_fast_ms) or 0,
                last_slow_ms = tonumber(State.health and State.health.last_slow_ms) or 0,
                repair_count = tonumber(State.health and State.health.repair_count) or 0,
                master_errors = tonumber(State.health and State.health.master_errors) or 0,
                identity = State.health and State.health.identity or nil,
                last_repair_reason = State.health and State.health.last_repair_reason or nil,
            },
            test_session = test_session_snapshot(),
            interop = {
                compatibility_mode = State.interop.compatibility_mode == true,
                manual_isolation = manual,
                suspended = suspended,
                requires_revalidation = revalidation,
                active = any_interop,
            },
        }
    end

    local function repair_domain_for_label(label)
        label = tostring(label or ""):lower()
        if label:find("^player_") then return "Player" end
        if label:find("^vehicle_") then return "Vehicle" end
        if label:find("^weapons_") then return "Weapons" end
        return nil
    end

    local function queue_runtime_repair(domain, reason, now)
        if domain ~= "Player" and domain ~= "Vehicle" and domain ~= "Weapons" then return false end
        local health = State.health
        if type(health) ~= "table" then return false end
        health.repair_queue = health.repair_queue or {}
        if health.repair_queue[domain] then return true end
        health.repair_queue[domain] = { reason = tostring(reason or "runtime callback failure"), queued_ms = tonumber(now) or now_ms() }
        return true
    end

    local function run_runtime_repair(domain, reason, now)
        local health = State.health
        health.last_repair_ms = health.last_repair_ms or {}
        local previous = tonumber(health.last_repair_ms[domain]) or -100000
        if now - previous < RUNTIME_REPAIR_COOLDOWN_MS then return false, "cooldown" end
        local callback
        if domain == "Player" then callback = Player and Player.RearmRuntimeState
        elseif domain == "Vehicle" then callback = Vehicle and Vehicle.RevalidateRuntimeState
        elseif domain == "Weapons" then callback = Weapons and Weapons.RevalidateRuntimeState end
        if type(callback) ~= "function" then return false, "rearm callback unavailable" end
        health.last_repair_ms[domain] = now
        local ok, result, detail
        if domain == "Player" then ok, result, detail = pcall(callback, reason)
        else ok, result, detail = pcall(callback) end
        if not ok or result == false then
            log_error_once("runtime_self_heal_" .. domain:lower(), tostring(detail or result or "rearm failed"))
            record_test_event("FAILED", "Runtime", "Self Heal " .. domain, "rearm", tostring(detail or result or "rearm failed"))
            return false, tostring(detail or result or "rearm failed")
        end
        health.repair_count = (tonumber(health.repair_count) or 0) + 1
        health.last_repair_reason = domain .. ":" .. tostring(reason or "runtime repair")
        State.last_fast_tick = 0
        State.last_slow_tick = 0
        log_info(("Runtime self-heal domain=%s reason=%s repairs=%d"):format(
            tostring(domain), tostring(reason or "runtime repair"), tonumber(health.repair_count) or 0))
        record_test_event("SUCCESS_VERIFIED", "Runtime", "Self Heal " .. domain, "rearm", tostring(reason or "runtime repair"))
        return true
    end

    local function process_runtime_repairs(now)
        local health = State.health
        local queue = health and health.repair_queue
        if type(queue) ~= "table" then return end
        for _, domain in ipairs({ "Player", "Vehicle", "Weapons" }) do
            local item = queue[domain]
            if item then
                local previous = tonumber(health.last_repair_ms and health.last_repair_ms[domain]) or -100000
                if now - previous >= RUNTIME_REPAIR_COOLDOWN_MS then
                    queue[domain] = nil
                    run_runtime_repair(domain, item.reason, now)
                end
            end
        end
    end

    local function sample_runtime_identity(now)
        local health = State.health
        if type(health) ~= "table" then return end
        health.identity = health.identity or { ped = 0, model = 0, pending_ped = 0, pending_model = 0, pending_since_ms = 0 }
        local previous = health.last_identity_sample_ms
        if previous and now >= previous and now - previous < IDENTITY_SAMPLE_MS then return end
        health.last_identity_sample_ms = now
        local identity = health.identity
        local ped, model = local_ped(), 0
        if not entity_exists(ped) then return end
        if Player and type(Player.RuntimeIdentitySnapshot) == "function" then
            local ok, snapshot = pcall(Player.RuntimeIdentitySnapshot)
            if ok and type(snapshot) == "table" then
                ped = tonumber(snapshot.ped) or ped
                model = tonumber(snapshot.model) or 0
            end
        end
        if not entity_exists(ped) then return end
        if identity.ped == 0 then
            identity.ped, identity.model = ped, model
            identity.pending_ped, identity.pending_model, identity.pending_since_ms = 0, 0, 0
            return
        end
        if identity.ped == ped and (identity.model == 0 or model == 0 or identity.model == model) then
            if model ~= 0 then identity.model = model end
            identity.pending_ped, identity.pending_model, identity.pending_since_ms = 0, 0, 0
            return
        end
        if identity.pending_ped ~= ped or (model ~= 0 and identity.pending_model ~= model) then
            identity.pending_ped, identity.pending_model, identity.pending_since_ms = ped, model, now
            return
        end
        if now - (tonumber(identity.pending_since_ms) or now) < IDENTITY_STABLE_MS then return end
        local old_ped, old_model = identity.ped, identity.model
        identity.ped, identity.model = ped, model
        identity.pending_ped, identity.pending_model, identity.pending_since_ms = 0, 0, 0
        local reason = ("local identity changed oldPed=%s oldModel=%s newPed=%s newModel=%s"):format(
            tostring(old_ped), tostring(old_model), tostring(ped), tostring(model))
        queue_runtime_repair("Player", reason, now)
        queue_runtime_repair("Vehicle", reason, now)
        queue_runtime_repair("Weapons", reason, now)
        log_info("Runtime self-heal event=LOCAL_IDENTITY_CHANGED " .. reason)
        record_combat_diagnostic("Lifecycle", "local identity changed", reason, "INFO")
    end

    -- Capture every tick briefly after a reset, then sample one in 61 ticks.
    -- Rings stay bounded; percentiles are computed only on request.
    local PERFORMANCE_SAMPLE_LIMIT = 128
    local PERFORMANCE_ROW_LIMIT = 64
    local performance_enabled = true -- Preserve the existing sampling default.
    local function reset_performance_window(label)
        if label ~= nil and type(label) ~= "string" then return false, "label must be a string" end
        State.performance = {
            -- Use the last scheduler timestamp; these UI-safe services must not
            -- call the native-backed gameplay clock.
            ticks = 0, since = State.health and State.health.last_tick_ms or 0,
            rows = {}, row_count = 0, dropped_labels = 0,
            label = tostring(label or "runtime"):gsub("[%c]", " "):sub(1, 80),
            enabled = performance_enabled,
        }
        return true
    end

    local function set_performance_enabled(enabled)
        if type(enabled) ~= "boolean" then return false, "enabled must be a boolean" end
        performance_enabled = enabled
        return reset_performance_window(State.performance and State.performance.label)
    end

    local function performance_snapshot()
        local perf = State.performance
        local snapshot = {
            enabled = performance_enabled, label = perf and perf.label or "runtime",
            ticks = perf and perf.ticks or 0, since_ms = perf and perf.since or nil,
            sample_limit = PERFORMANCE_SAMPLE_LIMIT, row_limit = PERFORMANCE_ROW_LIMIT,
            dropped_labels = perf and perf.dropped_labels or 0,
            unit = "sampledClockMs", live_verified = false, rows = {},
        }
        for label, row in pairs(perf and perf.rows or {}) do
            local samples = { table.unpack(row.samples) }
            table.sort(samples)
            local count = #samples
            snapshot.rows[#snapshot.rows + 1] = {
                label = label, count = row.count, mean = row.total / row.count,
                p50 = samples[math.max(1, math.ceil(count * 0.50))] or 0,
                p95 = samples[math.max(1, math.ceil(count * 0.95))] or 0,
                max = row.maximum, sample_count = count,
            }
        end
        table.sort(snapshot.rows, function(a, b) return a.label < b.label end)
        return snapshot
    end

    local function performance_clock()
        if not os or type(os.clock)~="function" then return nil end
        local ok,value=pcall(os.clock)
        return ok and type(value)=="number" and value==value and value>=0 and value<math.huge and value or nil
    end

    local function performance_record(label,began)
        if not began then return end
        local ended=performance_clock()
        if not ended or ended<began then return end
        local perf=State.performance
        if not perf then return end
        local elapsed=(ended-began)*1000
        local row=perf.rows[label]
        if not row then
            if perf.row_count >= PERFORMANCE_ROW_LIMIT then
                perf.dropped_labels = perf.dropped_labels + 1
                return
            end
            row={count=0,total=0,maximum=0,samples={},cursor=0};perf.rows[label]=row
            perf.row_count = perf.row_count + 1
        end
        row.count=row.count+1;row.total=row.total+elapsed
        row.maximum=math.max(row.maximum,elapsed)
        row.cursor = row.cursor % PERFORMANCE_SAMPLE_LIMIT + 1
        row.samples[row.cursor] = elapsed
    end

    local function performance_begin(now)
        if not performance_enabled then return end
        local perf=State.performance
        if not perf or now<perf.since then
            reset_performance_window(perf and perf.label)
            perf=State.performance
            perf.since=now
        end
        perf.ticks=perf.ticks+1
        perf.capture_until=perf.capture_until or now+45000
        perf.sampling=now<perf.capture_until or perf.ticks%61==1
        perf.began=perf.sampling and performance_clock() or nil
    end

    local function performance_finish(now)
        if not performance_enabled then return end
        local perf=State.performance
        if not perf then return end
        performance_record("whole_tick",perf.began)
        perf.sampling=false;perf.began=nil
        if now-(perf.last_report_ms or perf.since)<10000 then return end
        local ranked={}
        for label,row in pairs(perf.rows) do
            ranked[#ranked+1]={label=label,row=row}
        end
        table.sort(ranked,function(a,b)
            if a.row.total==b.row.total then return a.label<b.label end
            return a.row.total>b.row.total
        end)
        local parts={}
        for i=1,#ranked do
            local entry=ranked[i];local row=entry.row
            parts[#parts+1]=("%s samples=%d avg=%.3f max=%.3f")
                :format(entry.label,row.count,row.total/row.count,row.maximum)
        end
        if #parts>0 then
            pcall(log_info,"Performance sampledClockMs (not FPS): "..table.concat(parts,"; "))
        end
        perf.last_report_ms=now
    end

    local function safe(label, callback, ...)
        local began=State.performance and State.performance.sampling and performance_clock() or nil
        local ok, err = pcall(callback, ...)
        performance_record(label,began)
        if not ok then
            log_error_once("runtime_" .. label, err)
            record_test_event("FAILED", "Runtime", tostring(label), "scheduled callback", tostring(err))
            local domain = repair_domain_for_label(label)
            if domain then queue_runtime_repair(domain, "callback failure " .. tostring(label), now_ms()) end
        end
        return ok
    end

    local function timed_return(label,began,...)
        performance_record(label,began)
        return ...
    end
    local function timed(label,callback,...)
        local began=State.performance and State.performance.sampling and performance_clock() or nil
        if not began then return callback(...) end
        return timed_return(label,began,callback(...))
    end

    local function safe_requested(
        label,
        callback,
        default
    )
        if type(callback) ~= "function" then
            return default ~= false
        end

        local ok, result =
            pcall(callback)

        if not ok then
            log_error_once(
                "runtime_request_" .. tostring(label),
                tostring(result)
            )

            record_test_event(
                "FAILED",
                "Runtime",
                tostring(label),
                "request predicate",
                tostring(result)
            )
            local domain = repair_domain_for_label(label)
            if domain then queue_runtime_repair(domain, "request predicate failure " .. tostring(label), now_ms()) end

            return false
        end

        return result == true
    end

    local frame_callbacks = {
        UI = { "ui_frame", UI.FrameTick, UI.FrameRequested },
        Player = { "player_frame", Player.FrameTick, Player.FrameRequested },
        World = { "world_frame", World.FrameTick, World.FrameRequested },
        Weapons = { "weapons_frame", Weapons.FrameTick, Weapons.FrameRequested },
        Vehicle = { "vehicle_frame", Vehicle.FrameTick, Vehicle.FrameRequested },
    }

    local function frame_tick(now)
        if State.health then State.health.last_frame_ms = now end
        if type(Weapons.GravityRestoreTick)=="function"
            and safe_requested("gravity_cleanup",Weapons.GravityRestoreRequested,false) then
            safe("gravity_cleanup",Weapons.GravityRestoreTick,now)
        end
        if type(Vehicle.CannonTimingRestoreTick)=="function"
            and safe_requested("cannon_timing_cleanup",Vehicle.CannonTimingRestoreRequested,false)then
            safe("cannon_timing_cleanup",Vehicle.CannonTimingRestoreTick,now)
        end
        if type(Player.StoreIgnoreRestoreTick)=="function"
            and safe_requested("store_ignore_cleanup",Player.StoreIgnoreRestoreRequested,false) then
            local allow=State.frame_domains.Player==true and runtime_write_allowed("Player")
            safe("store_ignore_cleanup",Player.StoreIgnoreRestoreTick,now,allow)
        end
        if type(Player.SelectedEffectsTick) == "function"
            and safe_requested("selected_effects", Player.SelectedEffectsRequested, false) then
            local allow_scene = State.frame_domains.Player == true and runtime_write_allowed("Player")
            local allow_vehicle = State.frame_domains.Vehicle == true and runtime_write_allowed("Vehicle")
            local allow_world = State.frame_domains.World == true and runtime_write_allowed("World")
            safe("selected_effects", Player.SelectedEffectsTick, now, allow_scene, allow_vehicle, allow_world)
        end
        -- The scene is serviced once by this scheduler, outside ordinary Player
        -- dispatch, so Player errors/isolation cannot strand its cleanup.
        if type(Player.LesterRideTick) == "function"
            and safe_requested("lester_ride", Player.LesterRideRequested, false) then
            local allow_scene = State.frame_domains.Player == true
                and State.frame_domains.Vehicle == true
                and runtime_write_allowed("Player") and runtime_write_allowed("Vehicle")
            safe("lester_ride", Player.LesterRideTick, now, allow_scene)
        end
        if type(Session.FrameTick) == "function"
            and safe_requested("session_frame", Session.FrameRequested, true) then
            safe("session_frame", Session.FrameTick, now)
        end
        for _, name in ipairs(DOMAIN_ORDER) do
            local interop_blocked = (name == "Player" or name == "World") and not runtime_write_allowed(name)
            local spec = frame_callbacks[name]
            local requested =
                safe_requested(
                    name .. "_frame",
                    spec[3],
                    true
                )
            if State.frame_domains[name] and not interop_blocked and requested then
                if State.trace.active then record_api_call(name .. ".FrameTick") end
                safe(spec[1], spec[2], now)
            else
                if State.trace.active then
                    local suffix = interop_blocked and ".FrameTick.InteropSuspended"
                        or not requested and ".FrameTick.Idle" or ".FrameTick.Skipped"
                    record_api_call(name .. suffix)
                end
            end
        end
    end

    local function fast_tick(now)
        if State.health then State.health.last_fast_ms = now end
        safe("protections_fast", Protections.FastTick, now)
        safe("session_fast", Session.FastTick, now)

        local ped = local_ped()
        if not entity_exists(ped) then ped = 0 end
        if runtime_write_allowed("Weapons") then
            safe("weapons_fast", Weapons.FastTick, now, ped)
        else
            record_api_call("Weapons.FastTick.InteropSuspended")
        end
        if runtime_write_allowed("Player") then
            safe("player_fast", Player.FastTick, now, ped)
        else
            record_api_call("Player.FastTick.InteropSuspended")
        end
        -- Vehicle.FastTick also services the separately bound live Studio target.
        -- modules.vehicle suppresses only its ordinary gameplay mutation path.
        safe("vehicle_fast", Vehicle.FastTick, now, ped)
        -- Library/persistent work has its own serialized state machine, serviced
        -- after live studio edits by this same native-thread scheduler.
        local storage = module_context and module_context.StudioStorage
        if storage and type(storage.Tick) == "function"
            and (type(storage.Requested) ~= "function" or storage.Requested()) then
            safe("studio_storage", storage.Tick, now)
        end
        if runtime_write_allowed("World") and type(World.FastTick) == "function" then
            safe("world_fast", World.FastTick, now)
        elseif not runtime_write_allowed("World") then
            record_api_call("World.FastTick.InteropSuspended")
        end
    end

    local function slow_tick(now)
        if State.health then State.health.last_slow_ms = now end
        local ped = local_ped()
        if not entity_exists(ped) then return end
        if runtime_write_allowed("Weapons") then
            safe("weapons_slow", Weapons.SlowTick, now, ped)
        else
            record_api_call("Weapons.SlowTick.InteropSuspended")
        end
        if runtime_write_allowed("Player") then
            safe("player_slow", Player.SlowTick, now, ped)
        else
            record_api_call("Player.SlowTick.InteropSuspended")
        end
    end

    local function sample_overlay(now)
        local requested =
            safe_requested(
                "overlay",
                UI.OverlayRequested,
                false
            )

        if requested then
            State.overlay_sample_active = true
            safe(
                "overlay_sample",
                UI.SampleOverlay,
                now
            )
        elseif State.overlay_sample_active ~= false then
            State.overlay_sample_active = false
            safe(
                "overlay_clear",
                UI.ResetOverlay
            )
        end
    end

    local process_unload
    local function tick()
        if not started or not bound then return end
        if State.unload then process_unload(now_ms());return end
        local now = now_ms()
        performance_begin(now)
        -- Feature objects are re-resolved at most once per second, while their
        -- values remain live. External replacement is observed on the next epoch.
        module_context.FeatureCacheEpoch = math.floor(now / 1000)
        if State.health then
            State.health.tick_count = (tonumber(State.health.tick_count) or 0) + 1
            State.health.last_tick_ms = now
        end
        timed("runtime_identity",sample_runtime_identity,now)
        timed("runtime_repairs",process_runtime_repairs,now)
        timed("runtime_actions",process_diagnostic_actions)
        timed("runtime_commands",process_dev_bridge,now)
        if State.combat and State.combat.dirty == true
            and now - (tonumber(State.combat.last_event_ms) or now) >= COMBAT_QUIET_MS
            and now - (tonumber(State.combat.last_flush_ms) or -100000) >= COMBAT_FLUSH_MS then
            timed("runtime_diagnostics",export_combat_diagnostics,"interval",false)
        end
        if State.trace.active and now >= (State.trace.ends_at or 0) then finish_trace(now) end
        -- Combat stance prevention is a per-frame *reset flag*, not a
        -- 250 ms gameplay poll. Run it early before other domain work and
        -- never replay it from Player.FrameTick or Player.FastTick.
        if State.frame_domains.Player == true and runtime_write_allowed("Player")
            and type(Player.ActionModeFrameTick) == "function"
            and safe_requested("player_action_mode",Player.ActionModeFrameRequested,false) then
            safe("player_action_mode_frame",Player.ActionModeFrameTick,now)
        end
        frame_tick(now)

        local vehicle_writes =
            runtime_write_allowed(
                "Vehicle"
            )

        local combat_active =
            vehicle_writes
            and safe_requested(
                "vehicle_combat_active",
                Vehicle.CombatFeaturesActive,
                false
            )

        local projectiles_active =
            vehicle_writes
            and safe_requested(
                "vehicle_projectiles_active",
                Vehicle.HasTrackedProjectiles,
                false
            )

        if combat_active then
            safe(
                "vehicle_combat",
                Vehicle.CombatTick,
                now
            )
        elseif projectiles_active then
            safe(
                "vehicle_projectile_restore",
                Vehicle.RestoreProjectiles
            )
        end

        if now - State.last_fast_tick >= 250 then
            State.last_fast_tick = now
            fast_tick(now)
        end
        if now - State.last_slow_tick >= 3000 then
            State.last_slow_tick = now
            slow_tick(now)
        end
        if now - State.last_overlay_sample >= 166 then
            State.last_overlay_sample = now
            sample_overlay(now)
        end
        performance_finish(now)
        local performance = module_context and module_context.Performance
        if performance then performance.Flush(now) end
        complete_perf_bridge(now)
    end

    local function restore_fps_limiter()
        if World and type(World.RestoreFPSUnlock) == "function" then
            local ok, detail = pcall(World.RestoreFPSUnlock)
            if not ok then log_error_once("fps_world_reset", tostring(detail)) end
        end
        local fps = module_context and module_context.FPSLimiter
        if not fps or type(fps.Restore) ~= "function" then return true end
        local ok, restored, detail = pcall(fps.Restore)
        if not ok or restored ~= true then
            local message = tostring(ok and detail or restored)
            log_error_once("fps_restore", message)
            return false, message
        end
        return true
    end

    local function panic_reset(notify, cooperative_unload)
        if State.panicking then return false end
        State.panicking = true
        -- Attempt owned code restoration before unrelated domain/diagnostic
        -- callbacks, which can fail independently.
        local fps_ok, fps_error = restore_fps_limiter()
        local storage = module_context and module_context.StudioStorage
        if storage and type(storage.Invalidate) == "function" then pcall(storage.Invalidate, "panic") end
        local studio_ui = module_context and module_context.CScriptUI
        if studio_ui and type(studio_ui.stop_studio_camera) == "function" then
            safe("studio_camera_panic", studio_ui.stop_studio_camera, "panic")
        end
        record_combat_diagnostic("Lifecycle", "Panic", "Panic requested; restoring combat-owned state", "WARN")
        local failures={}
        local function restore(name,callback,...)
            local ok,result,detail=pcall(callback,...)
            if not ok or result==false then failures[#failures+1]=name..": "..tostring(detail or result) end
        end
        restore("toggles",Config.DisableAllToggles)
        local pocket=module_context and module_context.CScript and module_context.CScript.HangarPocket
        local pocket_pending=false
        if pocket and type(pocket.Stop)=="function" then
            local stopped,result,detail=pcall(pocket.Stop)
            local observed,snapshot=pcall(pocket.Snapshot)
            pocket_pending=observed and type(snapshot)=="table" and snapshot.cleanup_pending==true
            if not stopped or result==false and not (cooperative_unload and pocket_pending) then
                failures[#failures+1]="hangar: "..tostring(detail or result)
            end
        end
        local heist_runtime=module_context and module_context.CScript and module_context.CScript.HeistRuntimeProfiles
        if heist_runtime and type(heist_runtime.DrainUnload)=="function" then
            restore("heists",heist_runtime.DrainUnload)
        end
        local automation=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
        if automation then
            local ok,clean,detail=pcall(automation.Release)
            if not ok or clean~=true and not cooperative_unload then
                failures[#failures+1]="business automation: "..tostring(detail or clean or "restoration pending")
            end
        end
        if Session and type(Session.PanicReset)=="function" then restore("session",Session.PanicReset,cooperative_unload) end
        restore("vehicle",Vehicle.PanicReset)
        restore("camera",UI.StopCameraEffects)
        restore("spectating",Player.StopSpectating,true)
        restore("player",Player.PanicReset)
        restore("world",World.PanicReset)
        restore("weapons",Weapons.PanicReset,local_ped())
        if not cooperative_unload and type(Weapons.GravityRestoreTick)=="function" then
            restore("gravity",Weapons.GravityRestoreTick,now_ms())
        end
        if Protections and type(Protections.PanicReset)=="function" then restore("protections",Protections.PanicReset) end
        restore("overlay",UI.ResetOverlay)
        local ok,err=#failures==0,table.concat(failures,"; ")
        State.panicking = false
        if not fps_ok then
            return false, fps_error
        end
        if not ok then
            log_error_once("panic_reset", err)
            return false, tostring(err)
        end
        if cooperative_unload and pocket_pending then
            log_info("Cooperative unload: waiting for the Hangar cargo grant and patch restoration.")
            return true
        end
        if notify ~= false then
            toast("Panic reset complete. Local state restored.", 5000, "success", nil,
                "runtime-panic")
        end
        log_info("Panic reset completed.")
        record_test_event("SUCCESS_VERIFIED", "Runtime", "Panic", "reset",
            "domain cleanup completed without Lua error")
        record_combat_diagnostic("Lifecycle", "Panic", "Panic restore completed", "PASS")
        export_combat_diagnostics("Panic", false)
        return true
    end

    -- Runs on the existing gameplay scheduler before asking Cherax to destroy
    -- the VM. ON_UNLOAD cannot enqueue a job that survives that destruction.
    local function request_unload()
        if State.unload then return true end
        State.unload={phase="requested"}
        return true
    end
    process_unload=function(now)
        local pending=State.unload
        if not pending or pending.phase=="stopping" then return end
        if pending.phase=="requested" then
            local ok,detail=panic_reset(false,true)
            if not ok then
                State.unload=nil
                toast("Cleanup needs another attempt: "..tostring(detail),6500,"warning")
                return
            end
            pending.phase,pending.deadline,pending.next_tick="draining",now+3000,now
        end
        if now<pending.next_tick then return end
        pending.next_tick=now+100
        local ok,clean,detail=pcall(Player.DrainUnload,now)
        local vehicle_ok,vehicle_clean,vehicle_detail=pcall(Vehicle.DrainUnload,now)
        if not vehicle_ok then ok,detail=false,vehicle_clean end
        clean=clean==true and vehicle_clean==true
        local world_ok,world_clean,world_detail=pcall(World.DrainUnload,now)
        if not world_ok then ok,detail=false,world_clean end
        clean=clean==true and world_clean==true
        if type(Weapons.GravityRestoreTick)=="function" then
            local gravity_ok,gravity_clean,gravity_detail=pcall(Weapons.GravityRestoreTick,now)
            if not gravity_ok then ok,detail=false,gravity_clean
            elseif gravity_clean~=true then detail=gravity_detail or "Gravity Gun restoration is pending." end
            clean=clean==true and gravity_ok and gravity_clean==true
        end
        if Session and type(Session.DrainUnload)=="function" then
            local session_ok,session_clean,session_detail=pcall(Session.DrainUnload,now)
            if not session_ok then ok,detail=false,session_clean
            elseif session_clean~=true then detail=session_detail or "Phone resource cleanup is still pending." end
            clean=clean==true and session_ok and session_clean==true
        end
        local pocket=module_context and module_context.CScript and module_context.CScript.HangarPocket
        if pocket and type(pocket.DrainUnload)=="function" then
            local pocket_ok,pocket_clean,pocket_detail=pcall(pocket.DrainUnload,now)
            if not pocket_ok then ok,detail=false,pocket_clean
            elseif pocket_clean~=true then detail=pocket_detail or "Hangar cargo grant is still settling." end
            clean=clean==true and pocket_ok and pocket_clean==true
        end
        local heist_runtime=module_context and module_context.CScript and module_context.CScript.HeistRuntimeProfiles
        if heist_runtime and type(heist_runtime.DrainUnload)=="function" then
            local heist_ok,heist_clean,heist_detail=pcall(heist_runtime.DrainUnload,now)
            if not heist_ok then ok,detail=false,heist_clean
            elseif heist_clean~=true then detail=heist_detail or "Heist restoration is still pending." end
            clean=clean==true and heist_ok and heist_clean==true
        end
        local teleports=module_context and module_context.CScript and module_context.CScript.Teleports
        local automation=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
        if automation then
            local business_ok,business_clean,business_detail=pcall(automation.Release)
            if not business_ok then ok,detail=false,business_clean
            elseif business_clean~=true then detail=business_detail or "Business automation restoration is pending." end
            clean=clean==true and business_ok and business_clean==true
        end
        if teleports and type(teleports.DrainUnload)=="function" then
            local cargo_ok,cargo_clean,cargo_detail=pcall(teleports.DrainUnload,now)
            if not cargo_ok then ok,detail=false,cargo_clean
            elseif cargo_clean~=true then detail=cargo_detail or "CEO computer startup restoration is pending." end
            clean=clean==true and cargo_ok and cargo_clean==true
        end
        if ok and clean then
            local stop=(module_context and module_context.HostSetShouldUnload) or SetShouldUnload
            if type(stop)=="function" then
                pending.phase="stopping"
                log_info("Cooperative unload: gameplay cleanup complete; stopping Loader.")
                stop()
                return
            end
            ok,detail=false,"host unload entrypoint unavailable"
        end
        if not ok or now>=pending.deadline then
            State.unload=nil
            toast("Cleanup is still pending. Use Unload CScript again to retry.",6500,"warning")
            log_info("Cooperative unload deferred: "..tostring(detail or "owned remote state still needs control"))
        end
    end

    -- A session boundary invalidates session-owned state, not the user's
    -- settings. In particular, FPSLimiter owns process-image bytes, not a
    -- player/session object. Only explicit OFF/reset/unload (or a bridge fault)
    -- may release that lease; session changes must never synthesize OFF events.
    local function on_session_change()
        local failures = {}
        local function cleanup(name, callback, ...)
            local ok, result, detail = pcall(callback, ...)
            if not ok or result == false then
                local message = name .. ": " .. tostring(detail or result or "cleanup rejected")
                failures[#failures + 1] = message
                log_error_once("session_cleanup_" .. name, message)
            end
        end
        local storage = module_context and module_context.StudioStorage
        if storage and type(storage.Invalidate) == "function" then
            cleanup("storage", storage.Invalidate, "session change")
        end
        local studio_ui = module_context and module_context.CScriptUI
        if studio_ui and type(studio_ui.stop_studio_camera) == "function" then
            cleanup("studio_camera", studio_ui.stop_studio_camera, "session change")
        end
        record_combat_diagnostic("Lifecycle", "session generation change",
            "Clearing session-owned state; keeping requested settings and process FPS patch", "INFO")
        -- Queue World's existing guarded native cleanup even if another domain
        -- fails. This does not touch the FPS lease or replay toggle callbacks.
        cleanup("world", World.OnSessionChange)
        cleanup("vehicle", Vehicle.OnSessionChange)
        cleanup("camera_effects", UI.StopCameraEffects)
        cleanup("player", Player.OnSessionChange)
        cleanup("weapons", Weapons.OnSessionChange, local_ped())
        cleanup("overlay", UI.ResetOverlay)
        cleanup("protections", Protections.OnSessionChange)
        State.combat.generation = (tonumber(State.combat.generation) or 0) + 1
        -- Existing ticks re-resolve the new ped/vehicle from the still-current
        -- UI choices. Do not cache/replay an old ON after a user has chosen OFF.
        State.last_fast_tick, State.last_slow_tick, State.last_overlay_sample = 0, 0, 0
        if #failures > 0 then
            local detail = table.concat(failures, "; ")
            record_combat_diagnostic("Lifecycle", "session generation change",
                "Settings retained; cleanup reported: " .. detail, "WARN")
            return false, detail
        end
        record_combat_diagnostic("Lifecycle", "session generation change",
            "Session cleanup dispatched; requested settings retained", "INFO")
        log_info("Session change cleanup dispatched; toggle choices and FPS patch preserved.")
        return true
    end

    if #State.test_session.control_order == 0 then
        register_control_audit({
            key = "vehicle_rapid_fire_delay",
            name = "Rapid Fire Delay",
            module = "modules/vehicle.lua",
            feature_type = "SliderInt",
            callback = false,
            player = false,
            logical = true,
            description = "The logical-only cadence control counted in addition to registered host features."
        })
    end

    return {
        Tick = tick,
        PanicReset = panic_reset,
        RequestUnload = request_unload,
        OnSessionChange = on_session_change,
        RecordApiCall = record_api_call,
        RecordInteropEvent = record_api_call,
        RuntimeWriteAllowed = runtime_write_allowed,
        QueueDiagnosticAction = queue_diagnostic_action,
        SetFrameDomainEnabled = set_frame_domain,
        StartApiTrace = start_trace,
        FinishApiTrace = finish_trace,
        DiagnosticSnapshot = diagnostic_snapshot,
        PerformanceSnapshot = performance_snapshot,
        ResetPerformanceWindow = reset_performance_window,
        SetPerformanceEnabled = set_performance_enabled,
        SetTestSessionEnabled = set_test_session_enabled,
        TestSessionSnapshot = test_session_snapshot,
        BeginTestAction = begin_test_action,
        EndTestAction = end_test_action,
        RecordTestEvent = record_test_event,
        RegisterControlAudit = register_control_audit,
        ClearTestSession = clear_test_session,
        ExportTestSessionReport = export_test_session_report,
        TestSessionReport = test_session_report,
        RecordCombatDiagnostic = record_combat_diagnostic,
        CombatDiagnosticSnapshot = combat_diagnostic_snapshot,
        CombatDiagnosticReport = combat_diagnostic_report,
        ExportCombatDiagnostics = function(reason, notify)
            if reason and reason ~= "interval" then
                record_combat_diagnostic("Diagnostics", "export", tostring(reason), "INFO")
            end
            return export_combat_diagnostics(reason or "manual", notify ~= false)
        end,
        RunCombatSelfDiagnostics = run_combat_self_diagnostics,
        State = State,
    }
end

-- Preserve the one-loop contract. The callback is inert until compatibility
-- binding finishes after all domain modules have initialized and started.
Script.RegisterLooped(function()
    if not public_api
        or type(public_api.Tick) ~= "function" then
        return
    end

    local ok, err =
        pcall(
            public_api.Tick
        )

    if not ok then
        if type(State.health) == "table" then
            State.health.master_errors = (tonumber(State.health.master_errors) or 0) + 1
            State.health.repair_queue = State.health.repair_queue or {}
            local now = tonumber(State.health.last_tick_ms) or 0
            for _, domain in ipairs({ "Player", "Vehicle", "Weapons" }) do
                if not State.health.repair_queue[domain] then
                    State.health.repair_queue[domain] = { reason = "master tick failure", queued_ms = now }
                end
            end
        end
        local logger =
            module_context
            and module_context.Logger

        if logger
            and type(logger.ErrorOnce) == "function" then
            logger.ErrorOnce(
                "runtime_master_tick",
                "Runtime scheduler error: "
                .. tostring(err),
                "Runtime"
            )
        end
    end
end)

local function publish_state(context)
    local root = context.State.Runtime
    if type(root) ~= "table" then
        root = {}
        context.State.Runtime = root
    end
    root.MigrationPhase = Module.MigrationPhase
    root.Started = started
    root.Bound = bound
    root.Scheduler = State
end

function Module.BindCompatibility(bindings)
    if not module_context then error("core.runtime must initialize before compatibility binding", 2) end
    if bound then return public_api end
    dependencies = bindings or {}
    public_api = create_runtime(dependencies)
    bound = true
    module_context.CScript.Runtime = public_api
    module_context.Core.Runtime = public_api
    publish_state(module_context)
    return public_api
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table"
        or type(context.CScript) ~= "table" or type(context.Core) ~= "table" then
        error("core.runtime received an invalid context")
    end
    if module_context and module_context ~= context then
        error("core.runtime is already initialized by another context")
    end
    module_context = context
    State.frame_domains = { UI = true, Player = true, World = true, Weapons = true, Vehicle = true }
    State.performance = nil
    State.health = {
        tick_count = 0, last_tick_ms = 0, last_frame_ms = 0, last_fast_ms = 0, last_slow_ms = 0,
