-- Shared state namespaces used by the runtime and compatibility layer.
local Module = { Name = "core.state", MigrationPhase = "17.75" }

local SCOPE_NAMES = {
    "Vehicle",
    "Weapons",
    "Player",
    "World",
    "Session",
    "Protections",
    "Economy",
    "Heists",
    "Businesses",
    "UI",
    "Overlay",
    "Config",
    "Core",
}

local state
local initialized_context

local function clear_table(target)
    for key in pairs(target) do target[key] = nil end
end

function Module.Init(context)
    if type(context) ~= "table" then error("core.state missing loader context") end
    if type(context.CScript) ~= "table" then error("core.state missing CScript root") end
    if type(context.Runtime) ~= "table" then error("core.state missing loader runtime") end

    local root_core = context.CScript.Core
    local injected_core = context.Core
    if root_core ~= nil and type(root_core) ~= "table" then error("CScript.Core must be a table") end
    if injected_core ~= nil and type(injected_core) ~= "table" then error("context.Core must be a table") end
    if root_core and injected_core and root_core ~= injected_core then
        error("context.Core must reference CScript.Core")
    end
    local core = root_core or injected_core or {}
    context.CScript.Core = core
    context.Core = core

    if initialized_context then
        if initialized_context ~= context then error("core.state is already initialized by another context") end
        context.State = state
        core.State = state
        return state
    end

    state = { Runtime = context.Runtime }
    for index = 1, #SCOPE_NAMES do state[SCOPE_NAMES[index]] = {} end

    function state.Namespace(name)
        local namespace = state[name]
        if type(namespace) ~= "table" or name == "Runtime" then
            error("unknown CScript state namespace: " .. tostring(name), 2)
        end
        return namespace
    end

    function state.Reset(name)
        local namespace = state.Namespace(name)
        clear_table(namespace)
    end

    function state.ResetAll()
        for index = 1, #SCOPE_NAMES do clear_table(state[SCOPE_NAMES[index]]) end
    end

    context.State = state
    core.State = state
    initialized_context = context
    return state
end

function Module.Start() end
function Module.Stop() end

function Module.Restore(context)
    if state then state.ResetAll() end
    if context and context.State == state then context.State = nil end
    if context and context.Core and context.Core.State == state then context.Core.State = nil end
    initialized_context = nil
    state = nil
end

return Module
