        if not ticker_lease then return true end
        if host.Loaded()==false then ticker_lease=nil;return true end
        local address=resolve(ticker_lease)
        if not address then return false,'Cargo-message restoration pending: code changed or is unavailable.'end
        local original=bytes(PROFILE[4].original)
        for i,v in ipairs(original)do
            if ticker_lease.current[i]~=v then
                local ok,result=pcall(host.WriteByte,address+i-1,v)
                local read=host.ReadByte(address+i-1)
                if integer(read,0,255)then ticker_lease.current[i]=read end
                if not ok or result==false or read~=v then return false,'Cargo-message restoration did not verify.'end
            end
        end
        ticker_lease=nil;return true
    end
    function api.MuteTicker()
        if ticker_lease then
            if resolve(ticker_lease)then return true end
            return false,'Prior cargo-message lease needs restoration.'
        end
        local original=bytes(PROFILE[4].original)
        local first,last=ticker_bounds(original)
        if not first then return false,'Cargo-message statement boundaries are unavailable.'end
        local row={current=copy(original)}
        local address=resolve(row)
        if not address then return false,'Cargo-message code does not match the verified source.'end
        ticker_lease=row
        for i=first,last do
            if row.current[i]~=0 then
                local ok,result=pcall(host.WriteByte,address+i-1,0)
                local read=host.ReadByte(address+i-1)
                if integer(read,0,255)then row.current[i]=read end
                if not ok or result==false or read~=0 then
                    local restored,why=api.RestoreTicker()
                    return false,'Cargo-message preparation did not verify.'..(restored and '' or ' '..tostring(why))
                end
            end
        end
        return true
    end
    function api.Restore()
        if not lease and not grant_lease and not ticker_lease then return true end
        if host.Loaded()==false then lease=nil;grant_lease=nil;ticker_lease=nil;return true end
        local restored,why=api.RestoreTicker();if not restored then return false,why end
        if grant_lease then
            local a=resolve(grant_lease)
            if not a then return false,'Grant-loop restore pending: bytecode changed or is unavailable.'end
            local original=bytes(PROFILE[7].original)[29]
            if grant_lease.current[29]~=original then
                local ok,result=pcall(host.WriteByte,a+28,original)
                local read=host.ReadByte(a+28)
                if integer(read,0,255)then grant_lease.current[29]=read end
                if not ok or result==false or read~=original then return false,'Grant-loop restore did not verify.'end
            end
            grant_lease=nil
        end
        if not lease then return true end
        local address=resolve(lease)
        if not address then return false,'Capacity restore is pending: bytecode changed or is unavailable.' end
        for i,original in ipairs(bytes(PROFILE[1].original))do
            local offset=i-1
            if lease.current[i]~=original then
                local ok,result=pcall(host.WriteByte,address+offset,original)
                local read=host.ReadByte(address+offset)
                if integer(read,0,255)then lease.current[i]=read end
                if not ok or result==false or read~=original then return false,'Capacity restore did not verify.'end
            end
        end
        lease=nil;return true
    end
    local function apply(limit,step,verified)
        step=step or 50
        if not integer(limit,1,MAX)then return false,'Cargo limit must be 1..2147483647.'end
        if not integer(step,1,MAX_STEP)then return false,'Delivery size must be 1..2147483647.'end
        if lease or grant_lease then return false,'Prior capacity lease requires cleanup.'end
        if not verified then local ok,why=api.Verify();if not ok then return false,why end end
        lease={current=bytes(PROFILE[1].original)}
        local address=resolve(lease)
        if not address then lease=nil;return false,'Capacity code changed before patching.'end
        if step>50 then
            -- func_21021: when no physical slot remains, return instead of
            -- repeating the full 50-slot search for every reserve crate.
            grant_lease={current=bytes(PROFILE[7].original)}
            local a=resolve(grant_lease)
            if not a then grant_lease=nil;api.Restore();return false,'Grant-loop code changed before patching.'end
            local ok,result=pcall(host.WriteByte,a+28,50)
            local read=host.ReadByte(a+28)
            if integer(read,0,255)then grant_lease.current[29]=read end
            if not ok or result==false or read~=50 then
                api.Restore();return false,'Bounded grant-loop patch did not verify.'
            end
        end
        local desired=copy(lease.current)
        if limit<=250 then desired[40]=limit;desired[45]=limit
        else
            -- Same-size 32-bit capacity encoding; invalid/unowned branch stays 50.
            local tail={0x28,limit&255,(limit>>8)&255,(limit>>16)&255,(limit>>24)&255}
            for _,v in ipairs(bytes('38 00 61 63 28 1C 49 74 03 47 37 02 02 2E 01 01 00 00'))do tail[#tail+1]=v end
            for i,v in ipairs(tail)do desired[43+i]=v end
        end
        for i,value in ipairs(desired)do
          if lease.current[i]~=value then
            local offset=i-1
            local wrote,result=pcall(host.WriteByte,address+offset,value)
            local read=host.ReadByte(address+offset)
            if integer(read,0,255)then lease.current[i]=read end
            if not wrote or result==false or read~=value then
                local restored,detail=api.Restore()
                return false,'Capacity patch did not verify.'..(restored and '' or ' '..tostring(detail))
            end
          end
        end
        return true
    end
    function api.Apply(limit,step)return apply(limit,step,false)end
    function api.ApplyStep(limit,step,index)
        if not integer(limit,1,MAX)or not integer(step,1,MAX_STEP)then return false,'Invalid capacity preparation.'end
        if lease or grant_lease then return false,'Prior capacity lease requires cleanup.'end
        if index<=#PROFILE then
            local ok,why=api.VerifyStep(index)
            if ok==false then return false,why end
            return 'loading'
        end
        -- The two writable functions are resolved again here immediately
        -- before mutation, with the same full readback and rollback as Apply.
        return apply(limit,step,true)
    end
    function api.Pending()return lease~=nil or grant_lease~=nil or ticker_lease~=nil end
    return api
end

local REFILL_PROFILE={
{name="freemode_refill",script="freemode",before="2D 00 0C 00 00 43 D8 17 70 5D C7 17 7B 39 02 5D 28 BA 7A 39 03 71 39 04 38 03 38 02 59 E2 00 71 39 05 38 05 25 32 5B 62 00 71 39 06 38 06 75 5B 50 00 38 05 38 06 5D 62 B8 7A 70 5D 49 E9 7A 57 37 00 38 05 5D 5C 76 37 70 5D 49 E9 7A 71 58 28 00 38 05 5D 5C 76 37 71 70 5D A4 B8 7A 38 05 5D 62 B8 7A 25 64 70 5D A4 B8 7A 71 38 05 61 22 FC 1D 36 01 38 04 3D 01 39 04 38 06 3D 01 39 06 55 AA FF 38 05 3D 01 39 05 55 97 FF 38 03 38 04 02 39 03 38 03 38 02 59 5E 00 38 03 38 02 02 39 07 71 39 04 71 39 05 38 05 25 32 5B 4A 00 38 05 5D 5C 76 37 70 5D 49 E9 7A 71 58 32 00 38 05 5D 5C 76 37 71 70 5D A4 B8 7A 38 05 5D 62 B8 7A 25 64 70 5D A4 B8 7A 71 38 05 61 22 FC 1D 36 01 38 04 3D 01 39 04 38 04 38 07 57 03 00 55 09 00 38 05 3D 01 39 05 55 AF FF 38 03 38 04 02 39 03 55 58 00 38 03 38 02 5B 51 00 43 AA 46 70 5D 49 E9 7A 39 08 38 02 38 03 02 39 09 38 08 5D 06 4F 60 39 0A 38 08 70 08 2A 06 56 06 00 38 08 25 08 08 20 56 09 00 71 25 08 2C 09 03 42 39 08 71 39 0B 38 0B 38 09 5B 0F 00 38 0A 5D A9 49 60 38 0B 3D 01 39 0B 55 EA FF 5D 83 46 02 2E 00 00",after="2D 00 0C 00 00 43 D8 17 70 5D C7 17 7B 39 02 5D 28 BA 7A 39 03 71 39 04 38 03 38 02 59 E2 00 71 39 05 38 05 25 32 5B 62 00 71 39 06 38 06 75 5B 50 00 38 05 38 06 5D 62 B8 7A 70 5D 49 E9 7A 57 37 00 38 05 5D 5C 76 37 70 5D 49 E9 7A 71 58 28 00 38 05 5D 5C 76 37 71 70 5D A4 B8 7A 38 05 5D 62 B8 7A 25 64 70 5D A4 B8 7A 71 38 05 61 22 FC 1D 36 01 38 04 3D 01 39 04 38 06 3D 01 39 06 55 AA FF 38 05 3D 01 39 05 55 97 FF 38 03 38 04 02 39 03 38 03 38 02 59 5E 00 38 03 38 02 02 39 07 71 39 04 71 39 05 38 05 25 32 5B 4A 00 38 05 5D 5C 76 37 70 5D 49 E9 7A 71 58 32 00 38 05 5D 5C 76 37 71 70 5D A4 B8 7A 38 05 5D 62 B8 7A 25 64 70 5D A4 B8 7A 71 38 05 61 22 FC 1D 36 01 38 04 3D 01 39 04 38 04 38 07 57 03 00 55 09 00 38 05 3D 01 39 05 55 AF FF 38 03 38 04 02 39 03 55 58 00 38 03 38 02 5B 51 00 43 AA 46 70 5D 49 E9 7A 39 08 38 02 38 03 02 39 09 38 08 5D 06 4F 60 39 0A 38 09 25 32 59 14 00 25 32 39 09 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 71 39 0B 38 0B 38 09 5B 0F 00 38 0A 5D A9 49 60 38 0B 3D 01 39 0B 55 EA FF 5D 83 46 02 2E 00 00"},
{name="laptop_refill",script="appsmuggler",before="2D 00 0C 00 00 43 D8 17 70 5D ED 62 00 39 02 5D A2 D0 01 39 03 71 39 04 38 03 38 02 59 E2 00 71 39 05 38 05 25 32 5B 62 00 71 39 06 38 06 75 5B 50 00 38 05 38 06 5D 60 D0 01 70 5D AF BF 00 57 37 00 38 05 5D CB BF 00 70 5D AF BF 00 71 58 28 00 38 05 5D CB BF 00 71 70 5D 88 84 01 38 05 5D 60 D0 01 25 64 70 5D 88 84 01 71 38 05 61 22 FC 1D 36 01 38 04 3D 01 39 04 38 06 3D 01 39 06 55 AA FF 38 05 3D 01 39 05 55 97 FF 38 03 38 04 02 39 03 38 03 38 02 59 5E 00 38 03 38 02 02 39 07 71 39 04 71 39 05 38 05 25 32 5B 4A 00 38 05 5D CB BF 00 70 5D AF BF 00 71 58 32 00 38 05 5D CB BF 00 71 70 5D 88 84 01 38 05 5D 60 D0 01 25 64 70 5D 88 84 01 71 38 05 61 22 FC 1D 36 01 38 04 3D 01 39 04 38 04 38 07 57 03 00 55 09 00 38 05 3D 01 39 05 55 AF FF 38 03 38 04 02 39 03 55 58 00 38 03 38 02 5B 51 00 43 AA 46 70 5D AF BF 00 39 08 38 02 38 03 02 39 09 38 08 5D FB CF 01 39 0A 38 08 70 08 2A 06 56 06 00 38 08 25 08 08 20 56 09 00 71 25 08 2C 09 00 22 39 08 71 39 0B 38 0B 38 09 5B 0F 00 38 0A 5D 9E CA 01 38 0B 3D 01 39 0B 55 EA FF 5D 29 C9 01 2E 00 00",after="2D 00 0C 00 00 43 D8 17 70 5D ED 62 00 39 02 5D A2 D0 01 39 03 71 39 04 38 03 38 02 59 E2 00 71 39 05 38 05 25 32 5B 62 00 71 39 06 38 06 75 5B 50 00 38 05 38 06 5D 60 D0 01 70 5D AF BF 00 57 37 00 38 05 5D CB BF 00 70 5D AF BF 00 71 58 28 00 38 05 5D CB BF 00 71 70 5D 88 84 01 38 05 5D 60 D0 01 25 64 70 5D 88 84 01 71 38 05 61 22 FC 1D 36 01 38 04 3D 01 39 04 38 06 3D 01 39 06 55 AA FF 38 05 3D 01 39 05 55 97 FF 38 03 38 04 02 39 03 38 03 38 02 59 5E 00 38 03 38 02 02 39 07 71 39 04 71 39 05 38 05 25 32 5B 4A 00 38 05 5D CB BF 00 70 5D AF BF 00 71 58 32 00 38 05 5D CB BF 00 71 70 5D 88 84 01 38 05 5D 60 D0 01 25 64 70 5D 88 84 01 71 38 05 61 22 FC 1D 36 01 38 04 3D 01 39 04 38 04 38 07 57 03 00 55 09 00 38 05 3D 01 39 05 55 AF FF 38 03 38 04 02 39 03 55 58 00 38 03 38 02 5B 51 00 43 AA 46 70 5D AF BF 00 39 08 38 02 38 03 02 39 09 38 08 5D FB CF 01 39 0A 38 09 25 32 59 14 00 25 32 39 09 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 71 39 0B 38 0B 38 09 5B 0F 00 38 0A 5D 9E CA 01 38 0B 3D 01 39 0B 55 EA FF 5D 29 C9 01 2E 00 00"},
}
-- The source loops aggregate minus physical stock; bound materialization to
-- the existing 50 slots. Full same-size signatures are checked before writes.
function Module.NewRefillGuards(host)
    local rows={}
    for _,spec in ipairs(REFILL_PROFILE)do
        rows[#rows+1]={name=spec.name,script=spec.script,original=bytes(spec.before),desired=bytes(spec.after),current=bytes(spec.before)}
    end
    local api={}
    local function resolve(r)
        local ok,a=pcall(host.Scan,r.script,pattern(r.current))
        if not ok or not integer(a,1,9007199254740991)then return nil end
        for i,v in ipairs(r.current)do if host.ReadByte(a+i-1)~=v then return nil end end
        return a
    end
    local function write(r,target,address)
        local a=address or resolve(r);if not a then return false,'Reserve refill code mismatch: '..r.name end
        for i,v in ipairs(target)do
            if r.current[i]~=v then
                local ok,result=pcall(host.WriteByte,a+i-1,v)
                local read=host.ReadByte(a+i-1)
                if integer(read,0,255)then r.current[i]=read end
                if not ok or result==false or read~=v then return false,'Reserve refill write failed: '..r.name end
            end
        end
        return true
    end
    function api.Restore()
        local clean=true;local reason
        for i=#rows,1,-1 do
            local r=rows[i]
            if r.owned then
                local ok,why
                if host.Loaded(r.script)==false then ok=true else ok,why=write(r,r.original)end
                if ok then r.owned=false;r.current=copy(r.original)else clean=false;reason=why end
            end
        end
        return clean,reason
    end
    function api.Apply()
        local addresses={}
        for i,r in ipairs(rows)do addresses[i]=resolve(r);if not addresses[i]then return false,'Reserve refill profile unavailable: '..r.name end end
        for i,r in ipairs(rows)do
            r.owned=true
            local ok,why=write(r,r.desired,addresses[i])
            if not ok then api.Restore();return false,why end
        end
        return true
    end
    function api.ApplyStep(index)
        local r=rows[index<=#rows and index or index-#rows]
        if not r then return true end
        if index<=#rows then
            if not resolve(r)then return false,'Reserve refill profile unavailable: '..r.name end
        else
            r.owned=true
            local ok,why=write(r,r.desired)
            if not ok then api.Restore();return false,why end
        end
        return index==#rows*2 and true or 'loading'
    end
    return api
end

function Module.NewActions(host,busy)
    local state={busy=false,phase='IDLE'};local pending;local api={}
    function api.Request(kind,options)
        if kind~='open' and kind~='clear' and kind~='sale' then return false,'Unknown Hangar action.'end
        if state.busy or busy()then return false,'Stop cargo filling and wait for cleanup first.'end
        if type(host.InspectAction)~='function'then return false,'Hangar control APIs are unavailable.'end
        local scope,why=host.Scope();if not scope then return false,why end
        -- UI preflight reads only live ownership/inventory. Execution performs
        -- the whole-bytecode guard immediately before any native action.
        local view,err=host.InspectAction(scope,kind,false);if not view then return false,err end
        if kind=='open' or kind=='sale'then scope.computer_progressive=true end
        pending={scope=scope,kind=kind,before=view.stock,options=options}
        if kind=='sale' and (view.stock<1 or type(host.StartSale)~='function')then pending=nil;return false,'Sale launch requires accepted Hangar cargo and its app driver.'end
        state={busy=true,phase='QUEUED',reason=kind=='clear' and 'Cargo clear queued.' or (kind=='sale' and 'Hangar sale launch queued.' or 'Computer opening queued.')}
        return true,state.reason
    end
    local function finish(ok,why)
        if pending and pending.kind=='sale' and host.RestoreSaleSelection then
            local clean,detail=host.RestoreSaleSelection()
            if not clean then state.phase='RESTORING';state.reason=detail;pending.finishing={ok=ok,why=why};return end
        end
        state.stock=ok and pending and pending.kind=='clear' and 0 or nil;state.busy=false;state.ok=ok;state.phase=ok and 'COMPLETE' or 'STOPPED';state.reason=why;pending=nil end
    local function tick(now)
        local p=pending;if not p then return end
        if not host.Valid(p.scope)then return finish(false,'Character/session changed; action cancelled.')end
        if p.finishing then return finish(p.finishing.ok,p.finishing.why)end
        p.started=p.started or now
        if now-p.started>=30000 and not (p.native and not p.accepted) and not (p.kind=='sale' and p.scope.sale_dispatched) then return finish(false,'Hangar action timed out; no automatic retry.')end
        if p.kind=='sale' then
            local ok,why=host.StartSale(p.scope,p.options,now)
            if ok=='loading'then state.phase='STARTING_SALE';state.reason=why;return end
            return finish(ok==true,why)
        end
        if p.kind=='open' then
            local ok,why=host.OpenComputer(p.scope)
            if ok=='loading' then state.phase='OPENING';state.reason=why or 'Waiting for the Hangar screen to render; close Cherax to use it.';return end
            return finish(ok==true,why or (ok and 'Hangar computer opened; choose a sale in GTA.' or 'Computer could not open.'))
        end
        if not p.sent then
            local view,why=host.InspectAction(p.scope,'clear')
            if not view or view.stock~=p.before then return finish(false,why or 'Cargo changed before clearing; try again.')end
            p.sent=true;p.native=type(host.BeginClear)=='function'
            local ok,err=(p.native and host.BeginClear or host.ClearCargo)(p.scope,p.before)
            if ok~=true then return finish(false,err or 'Cargo clear failed.')end
            if p.native then state.phase='CLEARING';state.reason='Waiting for cargo removal to finish.';return end
            state.phase='VERIFYING';state.reason='Checking that all cargo was removed.';return
        end
        if p.native and not p.accepted then
            local status,why=host.PollClear(p.scope,p.before)
            if status=='pending' then state.reason=why or 'Waiting for the cargo checkout to settle.';return end
            if status~=true then return finish(false,why or 'Cargo checkout rejected; physical slots were preserved.')end
            p.accepted=true;p.started=now
            local cleared,err=host.ClearCargo(p.scope,p.before)
            if not cleared then return finish(false,err)end
            state.phase='VERIFYING';state.reason='Checking that all cargo was removed.';return
        end
        local view,why=host.ReadCargo(p.scope)
        if not view then return finish(false,why or 'Cargo readback unavailable.')end
        if view.stock~=0 or view.replica~=0 or view.physical_slots~=0 or (view.cached_slots or 0)~=0 then
            p.good_since=nil;return finish(false,'GTA retained or restored cargo; clearing was not confirmed.')
        end
        p.good_since=p.good_since or now
        if now-p.good_since>=2000 then return finish(true,'Cargo reads zero. Persistence after session changes remains unverified.')end
    end
    function api.Tick(now)local ok,why=pcall(tick,now);if not ok then finish(false,'Hangar action failed: '..tostring(why))end end
    function api.Cancel()
        if pending and pending.kind=='sale' and pending.scope.sale_dispatched and host.Valid(pending.scope)then
            state.reason='Hangar sale checkout is pending; waiting for GTA before unload.';return false
        end
        if pending and pending.native and not pending.accepted and host.Valid(pending.scope) then
            state.reason='Cargo checkout is pending; waiting for settlement before unload.';return false
        end
        if pending then finish(false,'Pending Hangar action cancelled.')end;return not state.busy
    end
    function api.TakeStock()local v=state.stock;state.stock=nil;return v end
    function api.Snapshot()return copy(state)end
    return api
end

function Module.New(host)
    local cfg={limit=100,step=50,type_index=7,delay_ms=1000,target_mode=0,target_value=2550000}
    local state={phase='IDLE',running=false,reason='Experimental cargo reserve. Live behaviour is unverified.',observed_grants=0,observed_cargo=0}
    local scope,request,last,patched,stop_requested,reserve_prepared=nil,nil,0,false,false,false
    local api={}
    local effective_limit=cfg.limit
    local function update_target(view,token)
        if cfg.target_mode==0 then effective_limit=cfg.limit;return true end
        state.quote_valid=false
        if type(host.Pricing)~='function'then return false,'Current Hangar pricing is unavailable.'end
        local price,why=host.Pricing(token,cfg.type_index);if not price then return false,why end
        local completion=state.running and {limit=state.target_limit,estimated_value=state.estimated_value}or nil
        local plan,err=Module.PlanValueTarget(view,cfg.type_index,cfg.target_value,price,completion);if not plan then return false,err end
        state.quote_valid=true;state.target_exact=plan.exact;state.target_value_delta=plan.value_delta
        state.target_exceeds_capacity=plan.target_exceeds_capacity==true
        state.max_achievable_value=plan.max_achievable_value
        effective_limit=plan.limit;state.target_limit=plan.limit;state.target_baseline_value=plan.baseline_value;state.estimated_value=plan.estimated_value
        state.target_selected_crates=plan.selected_crates;state.value_distance=plan.distance
        state.estimated_gross=plan.estimated_gross;state.estimated_fee=plan.estimated_fee;state.estimated_high_demand=plan.estimated_high_demand
        state.payout_basis={private_session=price.private_session,eligible_rivals=price.eligible_rivals,member=price.member==true}
        return true
    end
    local actions=Module.NewActions(host,function()return state.running or state.cleanup_pending or request~=nil end)
    function api.OpenComputer()return actions.Request('open')end
    function api.StartSale(type_index,ground)
        if type_index~=nil and not integer(type_index,1,8)then return false,'Choose a valid Hangar cargo type.'end
        return actions.Request('sale',{type_index=type_index,ground=ground~=false})
    end
    function api.CaptureFarmScope()return host.Scope()end
    function api.ValidFarmScope(token)return host.Valid(token)end
    function api.InventorySnapshot()
        local token,why=host.Scope();if not token then return nil,why end
        local view,detail=host.ReadCargo(token);if view then view.scope=token end
        return view,detail
    end
    function api.StopSale()return actions.Cancel()end
    function api.ClearCargo()return actions.Request('clear')end
    local function valid()return scope and host.Valid(scope)==true end
    local function cleanup()
        if request and valid()then
            local ok,why=host.CancelUnconsumed(scope,request)
            if not ok then state.cleanup_pending=true;state.reason=why;return false,why end
        end
        request=nil
        local ok,why=host.RestoreCapacity()
        state.cleanup_pending=not ok
        if ok then patched=false end
        return ok,why
    end
    local function finish(ok,why)
        state.running=false;state.ok=ok;state.reason=tostring(why);state.phase=ok and 'COMPLETE' or 'STOPPED'
        local clean,detail=cleanup()
        if not clean then state.phase='DRAINING';state.reason=tostring(why)..' '..tostring(detail) end
        return clean,detail
    end
    function api.Configure(options)
        if state.running or state.cleanup_pending or request or actions.Snapshot().busy then return false,'Stop and finish cleanup before changing supplier settings.'end
        local candidate=copy(cfg)
        for k,v in pairs(options or {})do
            local bounds=({limit={1,MAX},step={1,MAX_STEP},type_index={1,#TYPES},delay_ms={0,60000},target_mode={0,1},target_value={1,MAX}})[k]
            if not bounds or not integer(v,bounds[1],bounds[2])then return false,'Invalid Hangar setting: '..tostring(k)end
            candidate[k]=v
        end
        cfg=candidate;return true
    end
    function api.Start()
        if state.running or request or state.cleanup_pending or actions.Snapshot().busy then return false,'Supplier or Hangar action is active or cleanup is pending.'end
        local token,why=host.Scope();if not token then return false,why end
        if type(host.Prepare)=="function" then
            local ready,detail=host.Prepare(token)
            if ready~=true then return false,detail end
        end
        local view,err=host.Inspect(token,false);if not view then return false,err end
        state.stock=view.stock
        local planned,plan_error=update_target(view,token);if not planned then return false,plan_error end
        if view.stock>=effective_limit then
            if cfg.target_mode==1 and state.target_exceeds_capacity then
                -- Full stock is a successful no-op, not a rejected request.
                -- The native supplier must remain idle; UI toggle turns off.
                state.phase="COMPLETE";state.running=false;state.ok=true
                state.reason=("Hangar at capacity. Estimated sale payout: GTA$%d."):format(
                    state.estimated_value or 0)
                return true,state.reason
            end
            return false,'Existing cargo already meets the closest achievable target; no cargo was removed or added.'
        end
        scope=token;stop_requested=false;reserve_prepared=false
        local plan=state
        state={phase='ARMED',running=true,reason='Preparing selected cargo.',observed_grants=0,observed_cargo=0,
            start_stock=view.stock,stock=view.stock,physical_slots=view.physical_slots,reserve=math.max(0,view.stock-view.physical_slots),next_ms=0,
            target_limit=plan.target_limit,target_baseline_value=plan.target_baseline_value,estimated_value=plan.estimated_value,
            target_selected_crates=plan.target_selected_crates,value_distance=plan.value_distance,
            quote_valid=plan.quote_valid,target_exact=plan.target_exact,target_value_delta=plan.target_value_delta,
            target_exceeds_capacity=plan.target_exceeds_capacity,
            max_achievable_value=plan.max_achievable_value,
            estimated_gross=plan.estimated_gross,estimated_fee=plan.estimated_fee,estimated_high_demand=plan.estimated_high_demand,
            payout_basis=plan.payout_basis}
        return true,state.reason
    end
    function api.FillToValue(value,type_index)
