            if not host.Valid(s) or get(row[1])~=row[3]then return false,'Rooster fields changed before request.'end
            r.fields[#r.fields+1]={index=row[1],after=row[2],before=row[3]}
            if not set(row[1],row[2])then return false,'Rooster request field did not verify.'end
        end
