        end
        if c.active~=0 or c.stage==1 then return false,'Waiting for the native cargo transaction to settle.'end
        if r.dispatched and (c.quantity~=r.quantity or c.type_id~=r.type_id or c.stage~=0)then
            return false,'Rooster consumed or changed the request; waiting for native cleanup.'
        end
        if r.dispatched and (c.flags & 512)~=0 then
            if not set(s.flags_index,c.flags & ~512)then return false,'Could not clear the unconsumed ready marker.'end
        end
