    ["bridges/cherax.lua"] = [====[
-- Narrow access to Cherax Enhanced services supplied by the loader context.
local Module = { Name = "bridges.cherax", MigrationPhase = "17.75" }

local service

-- Independent callback-domain accounting. No arguments/results are copied and
-- no clock is read on an unsampled call. Counters are bounded by registered
-- domains, not event/entity/feature IDs. Inclusive timings must not be summed.
local function create_performance(context)
    local rows, order = {}, {}
    local active, since = true, nil
    local capture, last_now, capture_serial
    local api = {}
    local function clock()
        if not os or type(os.clock) ~= "function" then return nil end
        local ok, value = pcall(os.clock)
        if ok and type(value) == "number" and value == value and value >= 0 and value < math.huge then
            return value
        end
    end
    local function row_for(label, stride)
        label = tostring(label or "callback")
        local row = rows[label]
        if row then return row end
        if #order >= 64 then label = "other_callbacks"; row = rows[label]; if row then return row end end
        row = { label = label, calls = 0, samples = 0, total = 0, maximum = 0,
            stride = math.max(1, math.floor(tonumber(stride) or 61)) }
        rows[label] = row; order[#order + 1] = row
        return row
    end
    local function capture_row(label)
        if not capture or capture.complete then return nil end
        local row = capture.rows[label]
        if row then return row end
        if capture.row_count >= 63 then label = "other_callbacks"; row = capture.rows[label] end
        if not row then
            row = { label=label, calls=0, samples=0, total=0, maximum=0 }
            capture.rows[label] = row; capture.row_count = capture.row_count + 1
        end
        return row
    end
    local function capture_finish(row, began, ended)
        if not row or began == nil or ended == nil or ended < began then return end
        local elapsed = (ended - began) * 1000
        row.samples = row.samples + 1; row.total = row.total + elapsed
        if elapsed > row.maximum then row.maximum = elapsed end
    end
    local function begin(row)
        if not active then return nil end
        row.calls = row.calls + 1
        local sampled = (row.calls - 1) % row.stride == 0
        local began
        if capture and not capture.complete then
            began = clock()
            if began and capture.started_clock then capture.elapsed_clock_ms = math.max(0,(began-capture.started_clock)*1000) end
            if (capture.elapsed_clock_ms or 0) >= capture.duration_ms then
                capture.complete = true
            end
        end
        local captured = capture_row(row.label)
        if captured then captured.calls = captured.calls + 1 end
        if not sampled and not captured then return nil end
        return began or clock(), sampled, captured
    end
    local function finish(row, began, sampled, captured)
        if began == nil then return end
        local ended = clock()
        if ended == nil or ended < began then return end
        local elapsed = (ended - began) * 1000
        if sampled ~= false then
            row.samples = row.samples + 1; row.total = row.total + elapsed
            if elapsed > row.maximum then row.maximum = elapsed end
        end
        capture_finish(captured, began, ended)
    end
    function api.Wrap(label, callback, stride)
        if type(callback) ~= "function" then return callback end
        local row = row_for(label, stride)
        local function returned(began, sampled, captured, ...)
            finish(row, began, sampled, captured)
            return ...
        end
        return function(...)
            local began, sampled, captured = begin(row)
            if began == nil then return callback(...) end
            -- A throwing callback retains the host's existing error policy.
            -- An unsuccessful sample is not misreported as a zero-cost sample.
            return returned(began, sampled, captured, callback(...))
        end
    end
    function api.Begin(label, stride)
        if not active then return nil end
        local row = row_for(label, stride)
        row.calls = row.calls + 1
        if (row.calls - 1) % row.stride ~= 0 then return nil end
        return clock()
    end
    function api.Finish(label, began)
        local row = rows[label]
        if row then finish(row, began) end
    end
    -- Internal, opt-in diagnosis. Scheduler timestamps bound the window; normal
    -- sampling resumes automatically, with no per-frame logging or file I/O.
    function api.StartCapture(duration_ms, label)
        duration_ms = duration_ms == nil and 30000 or tonumber(duration_ms)
        if not active or not duration_ms or duration_ms ~= duration_ms or duration_ms < 1000 or duration_ms > 30000 then
            return false, "capture duration must be 1000-30000 ms"
        end
        if capture and not capture.complete then return false, "capture already active" end
        capture_serial = (capture_serial or 0) + 1
        capture = { id=capture_serial, label=tostring(label or "capture"):gsub("[%c]", " "):sub(1,80),
            duration_ms=duration_ms, started_ms=last_now, started_clock=clock(), complete=false, rows={}, row_count=0 }
        return true, capture.id
    end
    function api.CaptureSnapshot()
        if not capture then return nil end
        local elapsed = math.min(capture.duration_ms, math.max(0,
            capture.elapsed_clock_ms or 0,
            (last_now or capture.started_ms or 0) - (capture.started_ms or last_now or 0)))
        local seconds = elapsed / 1000
        local result = { id=capture.id, label=capture.label, clock="os.clock", inclusive=true, fps_measurement=false,
            complete=capture.complete, elapsed_ms=elapsed, duration_ms=capture.duration_ms, rows={} }
        for _, row in pairs(capture.rows) do
            result.rows[#result.rows+1] = { label=row.label, calls=row.calls, samples=row.samples,
                total_ms=row.total, mean_ms=row.samples>0 and row.total/row.samples or 0,
                maximum_ms=row.maximum, calls_per_second=seconds>0 and row.calls/seconds or 0,
                ms_per_second=seconds>0 and row.total/seconds or 0 }
        end
        table.sort(result.rows, function(a,b) if a.total_ms==b.total_ms then return a.label<b.label end return a.total_ms>b.total_ms end)
        return result
    end
    function api.Snapshot()
        local result = { clock = "os.clock", inclusive = true, fps_measurement = false, rows = {} }
        for _, row in ipairs(order) do
            result.rows[#result.rows + 1] = { label = row.label, calls = row.calls, samples = row.samples,
                sampled_ms = row.total, mean_ms = row.samples > 0 and row.total / row.samples or 0,
                maximum_ms = row.maximum, stride = row.stride }
        end
        return result
    end
    local function flush(now)
        now = tonumber(now) or 0
        if since == nil or now < since then since = now; return false end
        if now - since < 15000 then return false end
        since = now
        local parts = {}
        for _, row in ipairs(order) do
            if row.calls > 0 then
                parts[#parts + 1] = ("%s calls=%d samples=%d avg=%.3f max=%.3f"):format(
                    row.label, row.calls, row.samples, row.samples > 0 and row.total / row.samples or 0, row.maximum)
            end
            row.calls, row.samples, row.total, row.maximum = 0, 0, 0, 0
        end
        if #parts > 0 and context.Logger and type(context.Logger.Info) == "function" then
            context.Logger.Info("Performance domains sampledClockMs inclusive (not FPS): " .. table.concat(parts, "; "), "Runtime")
        end
        return #parts > 0
    end
    function api.Flush(now)
        now = tonumber(now) or 0
        last_now = now
        if capture and not capture.complete then
            capture.started_ms = capture.started_ms or now
            if now < capture.started_ms or now - capture.started_ms >= capture.duration_ms then capture.complete = true end
        end
        local captured = capture_row("profiler.flush")
        if not captured then return flush(now) end
        captured.calls = captured.calls + 1
        local began = clock()
        local result = flush(now)
        capture_finish(captured, began, clock())
        return result
    end
    function api.Stop() active = false; if capture then capture.complete = true end end
    return api
end

-- Foreign Feature userdata exposes methods that are illegal for its actual type.
-- A C++ parameter-type exception is not recoverable by Lua pcall. GetType is
-- therefore the FIRST host call; method presence is never capability evidence.
local function create_foreign_features(enumeration)
    local api = {}
    local capabilities = {
        Button = {}, Custom = {}, InputColor3 = {}, InputColor4 = {},
        Toggle = { toggle = true },
        SliderIntToggle = { toggle = true, integer = true },
        SliderFloatToggle = { toggle = true, float = true },
        Combo = { list = true }, ComboToggles = { list = true, list_toggles = true },
        List = { list = true }, ListWithInfo = { list = true },
        InputInt = { integer = true }, SliderInt = { integer = true },
        InputFloat = { float = true }, SliderFloat = { float = true },
        InputText = { text = true },
    }
    function api.Describe(feature)
        if feature == nil or type(feature.GetType) ~= "function" then
            return nil, "Feature.GetType is unavailable"
        end
        local ok, actual = pcall(feature.GetType, feature)
        if not ok or actual == nil then return nil, "Feature.GetType failed" end
        for name, supported in pairs(capabilities) do
            if enumeration and enumeration[name] ~= nil and actual == enumeration[name] then
                local result = { type_name = name, type_id = actual }
                for capability, enabled in pairs(supported) do result[capability] = enabled end
                return result
            end
        end
        return nil, "Unknown Feature.GetType; typed access refused"
    end
    function api.Supports(feature, capability)
        local descriptor, reason = api.Describe(feature)
        if not descriptor then return false, reason end
        if descriptor[capability] ~= true then
            return false, descriptor.type_name .. " does not support " .. tostring(capability)
        end
        return true, descriptor
    end
    return api
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.Raw) ~= "table" or type(context.Logger) ~= "table" then
        error("bridges.cherax requires injected Raw and Logger services")
    end

    local raw = context.Raw
    service = {}
    local performance = create_performance(context)
    context.Performance = performance
    context.CScript.Performance = performance
    context.CScript.ForeignFeatures = create_foreign_features(raw.eFeatureType or eFeatureType)

    function service.Get(name)
        return raw[tostring(name)]
    end

    function service.Available(name, method)
        local api = raw[tostring(name)]
        if method == nil then return api ~= nil end
        return api ~= nil and type(api[tostring(method)]) == "function"
    end

    function service.Call(name, method, ...)
        local api = raw[tostring(name)]
        local fn = api and api[tostring(method)]
        if type(fn) ~= "function" then
            return false, ("Cherax API unavailable: %s.%s"):format(tostring(name), tostring(method))
        end
        return pcall(fn, ...)
    end

    function service.Hash(value)
        local utils = raw.Utils
        if not utils or type(utils.Joaat) ~= "function" then return nil, "Utils.Joaat is unavailable" end
        local ok, hash = pcall(utils.Joaat, tostring(value))
        if not ok then return nil, tostring(hash) end
        return hash
    end

    function service.Toast(message, duration, title)
        local gui = raw.GUI
        local toast_pos = raw.eToastPos
        if not gui or type(gui.AddToast) ~= "function" or not toast_pos or toast_pos.TOP_RIGHT == nil then
            return false, "GUI.AddToast is unavailable"
        end
        local copy = context.Core and context.Core.PresentationCopy
        if copy then message = copy.Message(message) end
        local ok, err = pcall(gui.AddToast, "CScript", tostring(message), duration or 4500, toast_pos.TOP_RIGHT)
        return ok, ok and nil or tostring(err)
    end

    function service.MenuRoot()
        local file_mgr = raw.FileMgr
        if not file_mgr or type(file_mgr.GetMenuRootPath) ~= "function" then return nil end
        local ok, path = pcall(file_mgr.GetMenuRootPath)
        if not ok or type(path) ~= "string" or path == "" then return nil end
        return path
    end

    function service.FileExists(path)
        local file_mgr = raw.FileMgr
        if not file_mgr or type(file_mgr.DoesFileExist) ~= "function" then return false end
        local ok, exists = pcall(file_mgr.DoesFileExist, path)
        return ok and exists == true
    end

    function service.ReadFile(path)
        local file_mgr = raw.FileMgr
        if not file_mgr or type(file_mgr.ReadFileContent) ~= "function" then
            return nil, "FileMgr.ReadFileContent is unavailable"
        end
        if type(file_mgr.DoesFileExist) == "function" then
            local exists_ok, exists = pcall(file_mgr.DoesFileExist, path)
            if not exists_ok then return nil, tostring(exists) end
            if not exists then return nil, "file does not exist" end
        end
        local ok, content = pcall(file_mgr.ReadFileContent, path)
        if not ok then return nil, tostring(content) end
        if type(content) ~= "string" then return nil, "file content is not a string" end
        return content
    end

    function service.WriteFile(path, content, append)
        local file_mgr = raw.FileMgr
        if not file_mgr or type(file_mgr.WriteFileContent) ~= "function" then
            return false, "FileMgr.WriteFileContent is unavailable"
        end
        local ok, result = pcall(file_mgr.WriteFileContent, path, tostring(content), append == true)
        if not ok then return false, tostring(result) end
        return result ~= false, result == false and "FileMgr rejected the write" or nil
    end

    context.Cherax = service
    context.Bridges.Cherax = service
    context.CScript.Bridges.Cherax = service
end

function Module.Start() end
function Module.Stop() end

function Module.Restore(context)
    if context and context.Performance then context.Performance.Stop(); context.Performance = nil end
    if context and context.CScript then context.CScript.Performance = nil; context.CScript.ForeignFeatures = nil end
    if context and context.Cherax == service then context.Cherax = nil end
    if context and context.Bridges and context.Bridges.Cherax == service then context.Bridges.Cherax = nil end
    if context and context.CScript and context.CScript.Bridges
        and context.CScript.Bridges.Cherax == service then context.CScript.Bridges.Cherax = nil end
end

return Module
]====],
    ["bridges/features.lua"] = [====[
-- Stable Cherax feature resolution and owner-scoped feature registration.
local Module = { Name = "bridges.features", MigrationPhase = "17.75" }

local service

local function require_owner(owner)
    if type(owner) ~= "string" or owner == "" then error("feature owner must be a non-empty string", 3) end
    return owner
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.Cherax) ~= "table" or type(context.Logger) ~= "table" then
        error("bridges.features requires injected Cherax and Logger services")
    end

    local manager = context.Cherax.Get("FeatureMgr")
    local registry = {}
    local owners = {}
    local owner_order = {}
    local live_registry
    local live_registry_error
    local builtin_cache = {}
    local builtin_audited = {}
    local owned_hashes = {}
    service = {}

    local function trace(label)
        local runtime = context.CScript and context.CScript.Runtime
        if runtime and type(runtime.RecordApiCall) == "function" then runtime.RecordApiCall(label) end
    end

    local function normalized(value)
        return tostring(value or ""):lower():gsub("[^%w]+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    end

    local function feature_value(feature, method, field, ...)
        if not feature then return nil end
        local foreign=context.CScript and context.CScript.ForeignFeatures
        if method~="GetType" and (not foreign or not foreign.Describe(feature)) then return nil end
        local arguments = { ... }
        local ok, value = pcall(function()
            if type(feature[method]) == "function" then
                return feature[method](feature, table.unpack(arguments))
            end
            return feature[field]
        end)
        return ok and value or nil
    end

    local function feature_info(feature, table_hash)
        local foreign=context.CScript and context.CScript.ForeignFeatures
        if not foreign or not foreign.Describe(feature) then return nil end
        local hash = tonumber(feature_value(feature, "GetHash", "Hash")) or tonumber(table_hash) or 0
        local name = tostring(feature_value(feature, "GetName", "Name", false) or "")
        local feature_type = feature_value(feature, "GetType", "Type")
        return {
            feature = feature,
            hash = hash,
            name = name,
            normalized = normalized(name),
            type = feature_type,
        }
    end

    local function is_usable_toggle(info, excluded)
        if not info or not info.feature or info.name == "" then
            return false
        end

        if type(excluded) == "function" and excluded(info.feature) then
            return false
        end

        local foreign=context.CScript and context.CScript.ForeignFeatures
        return foreign~=nil and foreign.Supports(info.feature,"toggle")==true
    end

    local function normalize_token_word(word)
        word = normalized(word)

        if #word > 3
            and word:sub(-1) == "s" then

            word = word:sub(1, -2)
        end

        return word
    end


    local function contains_token(text, token)
        text = normalized(text)
        token = normalize_token_word(token)

        if text == ""
            or token == "" then
            return false
        end

        for word in text:gmatch("%w+") do
            if normalize_token_word(word) == token then
                return true
            end
        end

        return false
    end


    local function matches_token_sets(info, token_sets)
        for _, tokens in ipairs(token_sets or {}) do
            local matches = true

            for _, token in ipairs(tokens) do
                if not contains_token(
                    info.normalized,
                    token
                ) then
                    matches = false
                    break
                end
            end

            if matches then
                return true
            end
        end

        return false
    end


    local function matches_any_token(info, tokens)
        for _, token in ipairs(tokens or {}) do
            if contains_token(
                info.normalized,
                token
            ) then
                return true
            end
        end

        return false
    end

    function service.InvalidateLiveRegistry()
        live_registry = nil
        live_registry_error = nil
        builtin_cache, builtin_audited = {}, {}
        return true
    end

    local function get_live_registry()
        if live_registry then return live_registry end
        if live_registry_error then return nil, live_registry_error end
        if not manager or type(manager.GetAllFeatures) ~= "function" then
            live_registry_error = "FeatureMgr.GetAllFeatures is unavailable"
            return nil, live_registry_error
        end
        local ok, features = pcall(manager.GetAllFeatures)
        if not ok or (type(features) ~= "table" and type(features) ~= "userdata") then
            return nil, ok and "GetAllFeatures returned no iterable collection" or tostring(features)
        end
        -- Cherax's live host collections were observed as iterable userdata.
        -- A failed/oversized enumeration must not authorize a partial match.
        local snapshot, seen = {}, {}
        local iterated, failure = pcall(function()
            local count = 0
            for table_hash, feature in pairs(features) do
                count = count + 1
                if count > 32768 then error("feature registry exceeds bounded scan") end
                if feature ~= nil then
                    local info = feature_info(feature, table_hash)
                    if info and info.hash ~= 0 and not seen[info.hash] then
                        seen[info.hash] = true
                        snapshot[#snapshot + 1] = info
                    end
                end
            end
        end)
        if not iterated then return nil, tostring(failure) end
        table.sort(snapshot, function(a, b)
            if a.name == b.name then return a.hash < b.hash end
            return a.name < b.name
        end)
        live_registry = snapshot
        context.Logger.Info(
            ("Captured live Cherax feature registry (%d entries)."):format(#snapshot),
            "Features"
        )
        return live_registry
    end

    local function audit_builtin(key, spec, excluded, token_matches)
        if builtin_audited[key] then return end
        builtin_audited[key] = true
        local snapshot, err = get_live_registry()
        if not snapshot then
            context.Logger.Warn(("Builtin audit key=%s failed: %s"):format(tostring(key), tostring(err)), "Features")
            return
        end
        local candidates = {}
        for _, info in ipairs(snapshot) do
            if is_usable_toggle(info, excluded)
                and (matches_token_sets(info, spec.token_sets) or matches_any_token(info, spec.audit_tokens)) then
                candidates[#candidates + 1] = info
            end
        end
        context.Logger.Info(("Builtin audit key=%s candidates=%d tokenMatches=%d"):format(
            tostring(key), #candidates, #(token_matches or {})), "Features")
        for index = 1, math.min(#candidates, 24) do
            local info = candidates[index]
            context.Logger.Info(("Builtin candidate key=%s hash=0x%08X name=%s type=%s"):format(
                tostring(key), info.hash & 0xFFFFFFFF, info.name, tostring(info.type)), "Features")
        end
        if #candidates > 24 then
            context.Logger.Info(("Builtin audit key=%s omitted=%d additional candidates"):format(
                tostring(key), #candidates - 24), "Features")
        end
    end

    local function owner_record(owner)
        local record = owners[owner]
        if not record then
            record = { entries = {}, order = {} }
            owners[owner] = record
            owner_order[#owner_order + 1] = owner
        end
        return record
    end

    function service.Hash(key, prefix)
        return context.Cherax.Hash((prefix or "JinxRebound_") .. tostring(key))
    end

    function service.Resolve(id_or_name, index)
        trace("Feature.Resolve")
        if not manager then return nil end
        if type(id_or_name) == "string" and registry[id_or_name] then
            id_or_name = registry[id_or_name].hash
        end
        if type(id_or_name) == "number" and type(manager.GetFeature) == "function" then
            local ok, feature
            if index == nil then
                ok, feature = pcall(manager.GetFeature, id_or_name)
            else
                ok, feature = pcall(manager.GetFeature, id_or_name, index)
            end
            if ok then return feature end
        elseif type(id_or_name) == "string" and type(manager.GetFeatureByName) == "function" then
            local ok, feature
            if index == nil then
                ok, feature = pcall(manager.GetFeatureByName, id_or_name)
            else
                ok, feature = pcall(manager.GetFeatureByName, id_or_name, index)
            end
            if ok then return feature end
        end
        return nil
    end

    -- Built-ins resolve by validated numeric identity first. Exact-name and live
    -- token fallback are opt-in only because other Lua scripts can register
    -- identical display names in the shared FeatureMgr.
    function service.ResolveBuiltin(key, spec, options)
        key = tostring(key)
        spec = type(spec) == "table" and spec or {}
        options = type(options) == "table" and options or {}

        local validated_only =
            options.validated_only == true

        local allow_unvalidated =
            options.allow_unvalidated == true

        local resolution_mode =
            validated_only
            and "validated-only"
            or (
                allow_unvalidated
                and "allow-unvalidated"
                or "validated"
            )

        local cached =
            builtin_cache[key]

        if cached ~= nil
            and cached.resolution_mode == resolution_mode then

            return cached.unresolved ~= true and cached.feature or nil, cached
        end

        if cached ~= nil then
            builtin_cache[key] = nil
            builtin_audited[key] = nil
        end
        trace("Feature.ResolveBuiltin")

        local exact = {}
        for _, name in ipairs(spec.exact_names or {}) do exact[normalized(name)] = true end
        local function accept(feature, hash, strategy)
            local info =
                feature_info(
                    feature,
                    hash
                )

            if not is_usable_toggle(
                info,
                options.exclude
            ) then
                return nil
            end

            local exact_match =
                exact[info.normalized] == true

            local semantic_match =
                matches_token_sets(
                    info,
                    spec.token_sets
                )

            if strategy == "exact-name"
                or strategy == "exact-registry" then

                if not exact_match then
                    return nil
                end

            elseif strategy == "validated-hash" then

                -- A historical/current hash alone is not enough to prove identity.
                -- Permit a renamed feature, but require its name to still describe
                -- the expected feature.
                if not exact_match
                    and not semantic_match then

                    return nil
                end

            elseif strategy == "token" then

                if not semantic_match then
                    return nil
                end

            else
                return nil
            end

            info.strategy = strategy
            info.resolution_mode = resolution_mode
            builtin_cache[key] = info

            context.Logger.Info(
                (
                    "Builtin resolved key=%s "
                    .. "strategy=%s "
                    .. "hash=0x%08X "
                    .. "name=%s "
                    .. "type=%s"
                ):format(
                    key,
                    strategy,
                    info.hash & 0xFFFFFFFF,
                    info.name,
                    tostring(info.type)
                ),
                "Features"
            )

            return info.feature, info
        end

        -- A validated numeric identity is the only safe default. Different Lua
        -- scripts can expose identical display names through the shared manager.
        if manager
            and type(manager.GetFeature) == "function" then

            for _, hash in ipairs(
                spec.validated_hashes or {}
            ) do
                local ok, feature =
                    pcall(
                        manager.GetFeature,
                        hash
                    )

                if ok and feature then
                    local resolved, info =
                        accept(
                            feature,
                            hash,
                            "validated-hash"
                        )

                    if resolved then
                        return resolved, info
                    end
                end
            end
        end

        -- Never silently adopt a feature from another loaded Lua merely because
        -- its display name or tokens match a Cherax feature specification.
        if validated_only
            or not allow_unvalidated then

            local failure = {
                unresolved = true,
                resolution_mode = resolution_mode,

                strategy =
                    validated_only
                    and "validated-only-unresolved"
                    or "validated-unresolved",

                reason =
                    validated_only
                    and "no validated Cherax built-in hash matched"
                    or (
                        "no validated Cherax built-in hash matched; "
                        .. "unvalidated name/token fallback disabled"
                    ),

                token_matches = 0,
            }

            builtin_cache[key] =
                failure

            context.Logger.WarnOnce(
                "builtin_unresolved_" .. key,
                (
                    "Builtin unresolved key=%s "
                    .. "reason=%s"
                ):format(
                    key,
                    failure.reason
                ),
                "Features"
            )

            return nil, failure
        end

        -- Never accept the first GetFeatureByName result: distinct installed
        -- scripts can expose identical labels. Known hashes are checked first;
        -- all other resolutions require one unique complete-registry match.
        local snapshot, snapshot_error = get_live_registry()
        local token_matches, exact_matches = {}, {}
        if snapshot then
            for _, info in ipairs(snapshot) do
                if is_usable_toggle(info, options.exclude) then
                    if exact[info.normalized] then exact_matches[#exact_matches + 1] = info end
                    if matches_token_sets(info, spec.token_sets) then token_matches[#token_matches + 1] = info end
                end
            end
        end
        if #exact_matches == 1 then
            return accept(exact_matches[1].feature, exact_matches[1].hash, "exact-registry")
        end
        if #exact_matches > 1 then
            local failure = { unresolved = true, strategy = "ambiguous-exact-name", resolution_mode = resolution_mode,
                reason = "multiple installed controls have the same name", token_matches = #token_matches }
            builtin_cache[key] = failure
            return nil, failure
        end
        audit_builtin(key, spec, options.exclude, token_matches)
        if #token_matches == 1 then
            return accept(token_matches[1].feature, token_matches[1].hash, "token")
        end

        local detail = snapshot_error or (#token_matches > 1 and "ambiguous token match" or "no validated match")
        local failure = {
            unresolved = true,
            resolution_mode = resolution_mode,
            strategy = "unresolved",
            reason = detail,
            token_matches = #token_matches,
        }
        builtin_cache[key] = failure
        context.Logger.WarnOnce("builtin_unresolved_" .. key,
            ("Builtin unresolved key=%s reason=%s"):format(key, detail), "Features")
        return nil, failure
    end

    function service.InvalidateBuiltin(key)
        key = tostring(key)
        builtin_cache[key] = nil
        builtin_audited[key] = nil
        return true
    end

    function service.BuiltinStatus(key)
        local info = builtin_cache[tostring(key)]
        if not info then return { state = "NOT_PROBED" } end
        if info.unresolved == true then
            return { state = "UNAVAILABLE_CURRENT_BUILD", strategy = info.strategy, reason = info.reason }
        end
        return {
            state = "AVAILABLE",
            hash = info.hash,
            name = info.name,
            type = info.type,
            strategy = info.strategy,
        }
    end

    function service.LiveRegistryCount()
        local snapshot = get_live_registry()
        return snapshot and #snapshot or 0
    end

    function service.RegisterExisting(key, hash, owner)
        if type(key) ~= "string" or key == "" or type(hash) ~= "number" then
            return false, "existing feature requires string key and numeric hash"
        end
        if registry[key] then return false, "feature key already registered: " .. key end
        registry[key] = { hash = hash, owner = owner or "compat", existing = true }
        owned_hashes[hash]=true
        return true
    end

    function service.Add(owner, spec)
        owner = require_owner(owner)
        if type(spec) ~= "table" or type(spec.key) ~= "string" or spec.key == "" then
            error("feature spec requires a stable key", 2)
        end
        if registry[spec.key] then return nil, "feature key already registered: " .. spec.key end
        if not manager then return nil, "FeatureMgr is unavailable" end
        local hash = spec.hash
        if type(hash) ~= "number" then
            hash = service.Hash(spec.key, spec.prefix)
            if type(hash) ~= "number" then return nil, "unable to hash feature key: " .. spec.key end
        end
        local method = spec.player and "AddPlayerFeature" or "AddFeature"
        local add = manager[method]
        if type(add) ~= "function" then return nil, "FeatureMgr." .. method .. " is unavailable" end
        local copy = context.Core and context.Core.PresentationCopy
        local description = copy and copy.Description(spec.name, spec.description) or spec.description or ""
        local ok, result = pcall(add, hash, spec.name, spec.type, description,
            spec.callback, spec.nativeThreadExecution ~= false, spec.forceQueue == true)
        if not ok then return nil, tostring(result) end
        local entry = { key = spec.key, hash = hash, owner = owner, player = spec.player == true, result = result }
        registry[spec.key] = entry
        owned_hashes[hash]=true
        local record = owner_record(owner)
        record.entries[spec.key] = entry
        record.order[#record.order + 1] = spec.key
        return result, hash
    end

    local function legal_toggle(hash,index)
        if not owned_hashes[hash] then
            local foreign=context.CScript and context.CScript.ForeignFeatures
            if not foreign or not manager or type(manager.GetFeature)~="function" then
                return false,"Type-safe foreign feature access unavailable"
            end
            local got,feature
            if index==nil then got,feature=pcall(manager.GetFeature,hash)
            else got,feature=pcall(manager.GetFeature,hash,index) end
            if not got or not feature or not foreign.Supports(feature,"toggle") then
                return false,"Foreign feature type does not support toggles"
            end
        end
        return true
    end
    local function read_toggle_state(hash, index)
        local allowed,why=legal_toggle(hash,index)
        if not allowed then return false,nil,why end
        if not manager
            or type(manager.IsFeatureToggled) ~= "function" then

            return false,
                nil,
                "FeatureMgr.IsFeatureToggled is unavailable"
        end

        local ok, value

        if index == nil then
            ok, value =
                pcall(
                    manager.IsFeatureToggled,
                    hash
                )
        else
            ok, value =
                pcall(
                    manager.IsFeatureToggled,
                    hash,
                    index
                )
        end

        if not ok then
            return false,
                nil,
                tostring(value)
        end

        if type(value) ~= "boolean" then
            return false,
                nil,
                "FeatureMgr.IsFeatureToggled returned a non-boolean value"
        end

        return true, value
    end

    function service.IsToggled(id_or_name, index)
        local hash = id_or_name

        if type(id_or_name) == "string"
            and registry[id_or_name] then

            hash =
                registry[id_or_name].hash
        end

        if type(hash) ~= "number" then
            return false
        end

        local ok, toggled =
            read_toggle_state(
                hash,
                index
            )

        return ok
            and toggled == true
    end

