        owner = tostring(owner)

        local record =
            owners[owner]

        if not record then
            return true
        end

        local success = true

        for index = #record.order, 1, -1 do
            local key =
                record.order[index]

            local entry =
                record.entries[key]

            if entry then
                local method =
                    entry.player
                    and "RemovePlayerFeature"
                    or "RemoveFeature"

