            if existing.address ~= address or existing.valueType ~= suffix or existing.mask~=mask then
                local message = ("ownership key changed target: %s/%s"):format(owner, key)
                context.Logger.ErrorOnce("memory:key:" .. owner .. ":" .. key, message, "memory")
