        local ok, original = pcall(reader, address)
        if not ok then return false, tostring(original) end
        owned = owned or owner_record(owner, true)
        local entry = {
            owner = owner,
            key = key,
            address = address,
            token = token,
            valueType = suffix,
            reader = reader,
            writer = writer,
            guard = guard,
            mask = mask,
            original = original,
            current = original,
