        local denied = blocked[owner] and blocked[owner][key]
        return denied and denied.state or OWNERSHIP.UNTOUCHED
    end

    service.OwnershipStates = OWNERSHIP

    context.Memory = service
    context.Bridges.Memory = service
    context.CScript.Bridges.Memory = service
end

function Module.Start() end
function Module.Stop() end

function Module.Restore(context)
    if service and not service.RestoreAll() then error("one or more owned memory values could not be restored") end
    if context and context.Memory == service then context.Memory = nil end
