-- Typed native invocation with consistent defaults and contextual error logs.
local Module = { Name = "bridges.natives", MigrationPhase = "17.75" }

local service

function Module.Init(context)
    if type(context) ~= "table" or type(context.Cherax) ~= "table" or type(context.Logger) ~= "table" then
        error("bridges.natives requires injected Cherax and Logger services")
    end

    local raw = context.Cherax.Get("Natives")
    service = {}

    -- Normal global lookup reaches the shared preloader cache; rawget cannot.
    local preboot = __CSCRIPT_PREBOOT_CACHE
    local catalog = type(preboot) == "table" and preboot.native_catalog or nil
    service.Catalog = catalog
    service.CatalogCount = type(catalog) == "table" and tonumber(catalog.count) or 0
    function service.NameToHash(name)
        local row = type(catalog) == "table" and catalog.by_name and catalog.by_name[tostring(name or "")] or nil
        return row and row.hash or nil
    end
    function service.HashToName(hash)
        local key = tostring(hash or ""):upper()
        local row = type(catalog) == "table" and catalog.by_hash and catalog.by_hash[key] or nil
        return row and row.name or nil
    end

    local function trace(label)
        local runtime = context.CScript and context.CScript.Runtime
        if runtime and type(runtime.RecordApiCall) == "function" then runtime.RecordApiCall(label) end
    end

    local function try(method, hash, ...)
        trace("Native." .. tostring(method))
        local fn = raw and raw[method]
        if type(fn) ~= "function" then return false, "Natives." .. method .. " is unavailable" end
        local result = table.pack(pcall(fn, hash, ...))
        if not result[1] then
            context.Logger.ErrorOnce(("native:%s:%s"):format(method, tostring(hash)), result[2], "natives")
            return false, result[2]
        end
        return true, table.unpack(result, 2, result.n)
    end

    function service.Try(kind, hash, ...)
        local methods = {
            void = "InvokeVoid",
            bool = "InvokeBool",
            int = "InvokeInt",
            float = "InvokeFloat",
            pointer = "InvokePointer",
            string = "InvokeString",
            vector3 = raw and type(raw.InvokeVector3) == "function" and "InvokeVector3" or "InvokeV3",
            v3 = raw and type(raw.InvokeVector3) == "function" and "InvokeVector3" or "InvokeV3",
        }
        local method = methods[tostring(kind):lower()]
        if not method then return false, "unsupported native return type: " .. tostring(kind) end
        return try(method, hash, ...)
    end

    function service.Void(hash, ...)
        local ok, err = try("InvokeVoid", hash, ...)
        return ok, err
    end

    function service.Bool(hash, ...)
        local ok, value = try("InvokeBool", hash, ...)
        return ok and value == true or false
    end

    function service.Int(hash, ...)
        local ok, value = try("InvokeInt", hash, ...)
        return ok and type(value) == "number" and value or 0
    end

    function service.Float(hash, ...)
        local ok, value = try("InvokeFloat", hash, ...)
        return ok and type(value) == "number" and value or 0.0
    end

    function service.Pointer(hash, ...)
        local ok, value = try("InvokePointer", hash, ...)
        return ok and value or 0
    end

    function service.String(hash, ...)
        local ok, value = try("InvokeString", hash, ...)
        return ok and type(value) == "string" and value or ""
    end

    function service.Vector3(hash, ...)
        local method = raw and type(raw.InvokeVector3) == "function" and "InvokeVector3" or "InvokeV3"
        local result = table.pack(try(method, hash, ...))
        if not result[1] then return nil end
        return table.unpack(result, 2, result.n)
    end
    service.V3 = service.Vector3

    context.Natives = service
    context.Bridges.Natives = service
    context.CScript.Bridges.Natives = service
end

function Module.Start() end
function Module.Stop() end

function Module.Restore(context)
    if context and context.Natives == service then context.Natives = nil end
    if context and context.Bridges and context.Bridges.Natives == service then context.Bridges.Natives = nil end
    if context and context.CScript and context.CScript.Bridges
        and context.CScript.Bridges.Natives == service then context.CScript.Bridges.Natives = nil end
end

return Module
