            fast_supplies=mode~=nil and mode.quick==true and not mode.disabled or queued~=nil and queued.mode=="fast_supplies",
            supply_result=results[key],production_result=results[key],fast_production=lease~=nil and lease.scope.business==key and lease.active==true,
            production_queued=queue["production:"..tostring(key)]~=nil,supply_queued=queued~=nil,
