-- Each business owns a reversible lease. Pointer reservations prevent
-- concurrent profiles from sharing a tunable.
function Module.New(host,emit)
    local engines,owners,reservations,farms={},{},{},{}
    local clock=0
    local supply_next_ms=0
    local keys={"bunker","acid_lab","mc_cocaine","mc_meth","mc_cash","mc_weed","mc_documents","nightclub"}
    local api={}
    local function supported(key)return SUPPLY[key] or key=="nightclub" end
    local function engine(key)
        if engines[key] then return engines[key] end
        local proxy=setmetatable({}, {__index=host})
        function proxy.SupplyReady(scope,now)
            if now<supply_next_ms then return false,"Waiting for the previous supply acknowledgment to settle." end
            for _,other in pairs(engines) do
                for _,business in ipairs(keys) do
                    if other.Snapshot(business).supply_pending then return false,"A supply delivery is awaiting acknowledgment." end
                end
            end
            if host.TransactionsIdle then
                local ready,why=host.TransactionsIdle()
                if ready~=true then return false,why end
            end
            if host.SupplyReady then return host.SupplyReady(scope,now) end
            return true
        end
        function proxy.SupplySettled(now)
            supply_next_ms=now+1000
        end
        function proxy.ResolveProduction(scope)
            local rows,why=host.ResolveProduction(scope)
            if type(rows)~="table" then return nil,why end
            for _,row in ipairs(rows) do
                if row.pointer==nil or owners[row.pointer] and owners[row.pointer]~=key then
                    return nil,"A production tunable is owned by another active business."
                end
            end
            reservations[key]={}
            for _,row in ipairs(rows) do owners[row.pointer]=key;reservations[key][#reservations[key]+1]=row.pointer end
            return rows
        end
        engines[key]=new_single(proxy,emit);return engines[key]
    end
    local function release_reservations(key)
        for _,pointer in ipairs(reservations[key] or {}) do if owners[pointer]==key then owners[pointer]=nil end end
        reservations[key]=nil
    end
    local function inventory(key)
        local ok,scope,why=pcall(host.Scope,key)
        if not ok or not scope then return nil,tostring(ok and why or scope) end
        local read,state,err=pcall(host.Read,scope)
        if not read or type(state)~="table" then return nil,tostring(read and err or state) end
        if not integer(state.capacity,1,7000) or not integer(state.stock,0,state.capacity) then
            return nil,"Verified stock and capacity are required for Stock Farm."
        end
