        stop_farm(key,"STOPPED","Stopped by user.");return true
    end
    function api.StartAllStockFarms(keep_full)
        local report={started={},skipped={}}
        for _,key in ipairs(keys) do
            local ok,why=api.StartStockFarm(key,keep_full)
            if ok then report.started[#report.started+1]=key else report.skipped[key]=why end
        end
        return #report.started>0,report
    end
    function api.StopAllStockFarms()
        for key,farm in pairs(farms) do if farm.running then stop_farm(key,"STOPPED","Stopped by user.") end end
        return true
    end
    function api.StopStaffOrders(key)
        if key~="hangar" and key~="special_cargo" then return false,"Choose a staff-order business." end
        local e=engines[key]
        if not e then return true end
        local clean=e.Release()
        if clean then release_reservations(key) end
        return clean,clean and nil or "Staff-order settings are still restoring."
    end
    function api.Tick(now)
        if not integer(now,0,9007199254740991) or now<clock then return end
        clock=now
        for key,e in pairs(engines) do
            e.Tick(now)
            local s=e.Snapshot(key)
            if not s.fast_production and not s.cleanup_pending then release_reservations(key) end
        end
        for key,farm in pairs(farms) do
            if farm.running then
                local ok,why=pcall(function()
                    local valid,invalid_reason=host.Valid(farm.scope)
                    if not valid then return stop_farm(key,"FAILED",invalid_reason or "Character, session or ownership changed.") end
                    local state,err=inventory(key)
                    if not state then return stop_farm(key,"FAILED",err) end
                    if state.stock>farm.stock then farm.progress_ms=now end
                    farm.stock=state.stock;farm.target=state.capacity
                    local s=engine(key).Snapshot(key)
                    if state.stock==state.capacity then
                        if farm.phase~="FULL" then
                            engine(key).Request("production",key,false)
                            if SUPPLY[key] then engine(key).Request("fast_supplies",key,false) end
                            farm.phase="FULL";farm.cycles=farm.cycles+1
                            farm.running=farm.keep_full
                        end
                    elseif farm.phase=="FULL" then
                        if not s.cleanup_pending and not s.fast_production then
                            local armed,detail=arm(key,farm);if not armed then stop_farm(key,"FAILED",detail) end
                        end
                    elseif farm.phase=="STARTING" and s.fast_production then farm.phase="PRODUCING"
                    elseif farm.phase=="STARTING" and now-farm.since>=3000 then
                        stop_farm(key,"FAILED","Production override did not start; check the business notification.")
                    elseif farm.phase=="PRODUCING" then
                        if not s.fast_production or SUPPLY[key] and not s.auto_supplies then
                            return stop_farm(key,"FAILED","Production or supplies stopped; Stock Farm stopped with it.")
                        end
                        if now-farm.progress_ms>=180000 then
                            stop_farm(key,"FAILED",key=="nightclub" and "No stock increase for three minutes. Check technicians and linked businesses."
                                or "No stock increase for three minutes. Check business setup and supplies.")
                        end
                    end
                end)
                if not ok then stop_farm(key,"FAILED",tostring(why)) end
            end
        end
    end
    function api.Snapshot(key)
        local s=engine(key).Snapshot(key);local farm=farms[key]
        s.stock_farm_supported=supported(key)==true
        s.stock_farm=farm and {running=farm.running,phase=farm.phase,reason=farm.reason,stock=farm.stock,
            target=farm.target,cycles=farm.cycles,keep_full=farm.keep_full}
            or {running=false,phase="IDLE",cycles=0}
        return s
    end
    function api.Stop()
        api.StopAllStockFarms()
        for _,e in pairs(engines) do e.Stop() end
    end
    function api.Release()
        api.Stop();local complete=true
        for key,e in pairs(engines) do if e.Release() then release_reservations(key) else complete=false end end
        return complete
    end
    function api.CanHandoff()
        for _,farm in pairs(farms) do if farm.running then return false end end
        for _,e in pairs(engines) do if not e.CanHandoff() then return false end end
        return true
    end
    return api
end

-- Host binding is deliberately narrow: documented stat reads and named tunables.
-- No direct persistent product/supply writes are made by this module.
local function make_host(context)
    local raw=context.Raw or {};local core=context.CScript.Economy
    local g,n,m,u,gta=raw.ScriptGlobal,raw.Natives,raw.Memory,raw.Utils,raw.GTA
    local host={}
    function host.StockFarmBlocked(key)
        local businesses=context.CScript.Businesses
        if not businesses then return false end
        local row
        if key=="bunker" and type(businesses.BunkerFarmSnapshot)=="function" then row=businesses.BunkerFarmSnapshot()
        elseif SUPPLY[key] and type(businesses.MCFarmSnapshot)=="function" then row=businesses.MCFarmSnapshot(key) end
        if row and row.active then return true,"Sale farm owns this business until its cycle stops." end
        return false
    end
    local factory_ids={mc_cocaine={3,8,13,18},mc_meth={1,6,11,16},mc_cash={4,9,14,19},mc_weed={2,7,12,17},mc_documents={5,10,15,20}}
    local function get(index)return g.GetInt(index)end
    local function stat(slot,name)return core.ReadStat(core.QualifyStat(slot,name))end
    local function basic()
        return g and type(g.AreValid)=="function" and g.AreValid()==true and n and u
            and n.InvokeString(0xFCA9373EF340AC0A)=="1.73"
            and n.InvokeInt(0x2C83A9DA6BFFC4F9,u.Joaat("freemode"))==1
    end
    function host.TransactionsIdle()
        if not basic() or type(n.InvokeBool)~="function" then return false,"Native transaction context is unavailable." end
        local manager=context.CScript.Businesses
        if not manager or type(manager.NativeTransactionsIdle)~="function" then return false,"Native transaction validation is unavailable." end
        return manager.NativeTransactionsIdle()
    end
    function host.SupplyReady()
        local manager=context.CScript.Businesses
        if not manager then return false,"Business sale state is unavailable." end
        for _,key in ipairs({"bunker","mc_cocaine","mc_meth","mc_cash","mc_weed","mc_documents"}) do
            local state=key=="bunker" and manager.BunkerFarmSnapshot and manager.BunkerFarmSnapshot()
                or key~="bunker" and manager.MCFarmSnapshot and manager.MCFarmSnapshot(key)
            if state and state.active and (state.phase=="WAIT_SALE_CONTROLLER" or state.phase=="WAIT_COMPLETION_READY"
                or state.phase=="WAIT_SETTLEMENT") then return false,"Waiting for sale settlement before requesting supplies." end
        end
        return true
    end
