            mc_weed={"BIKER_WEED_CAPACITY",280958},mc_meth={"BIKER_METH_CAPACITY",280966},
            mc_cocaine={"BIKER_COCAINE_CAPACITY",280974},mc_documents={"BIKER_FAKEIDS_CAPACITY",280982},
            mc_cash={"BIKER_COUNTERCASH_CAPACITY",280990},
        }
