        return true,("Accelerated %d active staff order(s). New orders use the fast duration; cargo still requires GTA delivery."):format(changed)
    end
    -- This five-tunable profile and timer bootstrap filled Bunker stock from
    -- 25 to 100 in Enhanced 1.73 testing. Require source and pointer validation.
    local SPECS={
        {hash=215868155,after=1000},
        {hash=631477612,after=0},
        {hash=818645907,after=0},
        {hash=-1652502760,after=1},
        {hash=1647327744,after=1},
