        mc_cocaine={name="BIKER_CRACK_PRODUCTION_TIME",offset=17385,upgrades={{2070857577,17391},{-1539796661,17397}}},
        mc_documents={name="BIKER_FAKEIDS_PRODUCTION_TIME",offset=17386,upgrades={{1672482518,17389},{-518264160,17395}}},
        mc_cash={name="BIKER_COUNTERCASH_PRODUCTION_TIME",offset=17387,upgrades={{1690071006,17390},{-1454958662,17396}}},
        acid_lab={name="BIKER_ACID_PRODUCTION_TIME",offset=17388,upgrades={{494316332,17394}}},
