        if host.ReadCell(row)==nil or not m or type(m.WriteInt)~="function" then return false end
        local ok,result=pcall(m.WriteInt,row.pointer,value)
        if not ok or result==false then return false end
        return host.ReadCell(row)==value
    end
    function host.CaptureProductionTimer(scope)
        if not basic() or not gta or type(gta.GetLocalPlayerId)~="function" or type(n.InvokeInt)~="function" then
            return nil,"Production timer APIs unavailable."
        end
        local pok,player=pcall(gta.GetLocalPlayerId);player=pok and tonumber(player) or nil
        if not integer(player,0,31) then return nil,"Local player id unavailable." end
        if scope.business=="special_cargo" or scope.business=="hangar" then
            -- The paid order controller creates sourcing deadlines. Duration
            -- overrides affect future orders; captured deadlines stay unchanged.
