end
-- Reuses the native supplier and sale controller; never grants money or stock.
function Module.NewCargoFarm(host)
    local state={running=false,phase='IDLE',cycles=0}
    local token, last, entered, pending = nil, -1000, nil, nil
    local api={}
    local function finish(phase,why)
        state.running=false;state.phase=phase;state.reason=why
    end
    local function phase(name,now,why)
        state.phase=name;entered=now;state.reason=why
    end
    local function valid(view)
        if type(view)~='table' or type(view.scope)~='table' or not token then return false end
        for _,key in ipairs({'account','slot','generation','property','pid'}) do
            if view.scope[key]~=token[key] then return false end
        end
        return true
    end
    local function stop(why)
        finish('STOPPED',why or 'Auto Farm stopped.')
        -- Cancellation only releases work initiated by this farm. The native
        -- sale continues if GTA has already launched it.
        if pending=='fill' then pcall(host.StopFill) end
        if pending=='launch' then pcall(host.StopLaunch) end
