            return false,'Choose 1â€“50 crates and a cargo type.'
        end
        local ready,why=host.Ready();if ready~=true then return false,why end
        local view,err=host.Inventory()
        if not view or not view.coherent or type(view.scope)~='table' then return false,err or 'Cargo inventory is not synchronized.' end
