        if not integer(view.stock,0,50) then return stop('Inventory exceeded the farm limit; no sale was requested.') end
        state.stock=view.stock
        local sale,err=host.Sale()
        if not sale then return stop(err or 'Sale controller is unreadable.') end
        local timeout=({REFILL=60000,WAIT_FILL=180000,LAUNCH=60000,WAIT_LAUNCH=60000,FINISH=60000,SETTLING=180000})[state.phase]
        if timeout and now-entered>timeout then return stop(state.reason or 'Cargo operation timed out; not retrying.')end
