                    state.sale_stock=view.stock;phase('LAUNCH',now,'Cargo ready.');return
                end
                return stop(fill.reason or 'Refill ended before the cargo target was observed.')
            end
            if now-entered>180000 then return stop('Cargo refill timed out; no sale requested.') end
        elseif state.phase=='LAUNCH' then
            if sale.active then return stop('Another sale appeared before launch.') end
            if not view.coherent or view.stock~=state.sale_stock then return stop('Cargo changed before sale launch.') end
            pending='launch'
            local ok,message=host.Launch()
            if ok~=true then return stop(message or 'Native sale checkout could not start.') end
            phase('WAIT_LAUNCH',now,'Waiting for GTA to launch the sale.');return
        elseif state.phase=='WAIT_LAUNCH' then
            local launch=host.LaunchState()
            if sale.active and launch.phase=='COMPLETE' then
                pending=nil;state.sale_identity=sale.identity;phase('FINISH',now,'Waiting for the sale completion conditions.');return
            end
