            end
        elseif state.phase=='FINISH' then
            if not sale.active or sale.identity~=state.sale_identity then return stop('Sale instance changed before completion.') end
            local ok,message=host.Finish(state.sale_identity)
            state.reason=message
            if ok==true then phase('SETTLING',now,'Waiting for GTA to finish and consume cargo.');return end
            if now-entered>60000 then return stop(message or 'Sale could not be finished.') end
        elseif state.phase=='SETTLING' then
            if sale.active and sale.identity~=state.sale_identity then return stop('Sale instance changed during settlement.') end
            if not sale.active and view.coherent and view.stock<state.sale_stock then
                local idle,detail=host.Settled()
                if idle~=true then state.reason=detail;return end
