        if not ok then stop('Cargo Auto Farm stopped: '..tostring(why)) end
    end
    function api.Snapshot()return clone(state)end
    return api
end

local function make_cargo_host(context)
    local h={};local raw=context.Raw or {}
    local n,u,s,l=raw.Natives,raw.Utils,raw.Script,raw.ScriptLocal
    local function pocket()return context.CScript.HangarPocket end
    local function manager()return context.CScript.Businesses end
    local function count(name)
        if not n or not u then return nil end
        local ok,v=pcall(n.InvokeInt,0x2C83A9DA6BFFC4F9,u.Joaat(name))
        return ok and integer(v,0,32) and v or nil
    end
    function h.Inventory()
        local p=pocket()
        if not p or not p.InventorySnapshot then return nil,'Hangar inventory adapter is unavailable.' end
        return p.InventorySnapshot()
    end
    function h.Settled()
        local b=manager()
        if not b or not b.NativeTransactionsIdle then return false,'Transaction status is unavailable.'end
        return b.NativeTransactionsIdle()
    end
    function h.Ready()
        local p,b=pocket(),manager()
        if not p or not p.StartSale or not p.InventorySnapshot or not b or not b.CompleteActiveSale then
            return false,'Cargo source/sale adapters are unavailable.'
        end
        if not n or not u or not s or not s.ExecuteAsScript or not l or not l.GetPtr then
            return false,'Sale instance verification is unavailable.'
        end
        local snap=p.Snapshot()
        if snap.running or snap.cleanup_pending or snap.action.busy then return false,'Wait for existing Hangar actions to finish.'end
        if b.Snapshot and (b.Snapshot().active_sale_farms or 0)>0 then return false,'Stop other sale farms first.'end
        local sale,why=h.Sale();if not sale then return false,why end
        if sale.active then return false,'Finish the existing sale first.'end
        return h.Settled()
    end
    function h.Sale()
        for _,name in ipairs({'gb_biker_contraband_sell','gb_gunrunning','gb_contraband_sell'})do
            if count(name)~=0 then return nil,'Another sale controller is active or unreadable.'end
        end
        local ground,air=count('fm_content_smuggler_sell'),count('gb_smuggler')
        if ground==nil or air==nil or ground>1 or air>1 then return nil,'Hangar sale instances are ambiguous.'end
        -- Ground missions may retain their common gb_smuggler wrapper.
        local name=ground==1 and 'fm_content_smuggler_sell' or air==1 and 'gb_smuggler' or nil
        if not name then return {active=false}end
        local hash=u.Joaat(name);local tid
        local ok=pcall(s.ExecuteAsScript,hash,function()tid=n.InvokeInt(0xC30338E8088E2E21)end)
        local pointer=l.GetPtr(hash,ground==1 and 4232 or 1998)
