            return nil,'Sale thread identity is unavailable.'
        end
        return {active=true,identity=name..':'..tid..':'..pointer}
    end
    function h.Fill(limit,type_index)
        local p=pocket();local ok,why=p.Configure{limit=limit,step=math.min(50,limit),delay_ms=0,target_mode=0,type_index=type_index}
        if not ok then return false,why end
