    function h.FillState()return pocket().Snapshot()end
    function h.Launch()return pocket().StartSale(nil,true)end
    function h.LaunchState()return pocket().Snapshot().action end
    function h.StopLaunch()return pocket().StopSale()end
    function h.Finish(identity)
        local current,why=h.Sale()
        if not current or not current.active or current.identity~=identity then return false,why or 'Sale instance changed.'end
        return manager().CompleteActiveSale()
    end
    return h
end

local instance
function Module.Init(context)
    instance=Module.New(make_host(context),function(message)
        if context.Logger and context.Logger.Info then context.Logger.Info(message,"BusinessAutomation")end
        if context.Notifications and context.Notifications.Warning then context.Notifications.Warning(message,4500)end
    end)
    local cargo=Module.NewCargoFarm(make_cargo_host(context))
    context.CScript.CargoFarm=cargo
    local tick,release,can_handoff=instance.Tick,instance.Release,instance.CanHandoff
    instance.Tick=function(now)tick(now);cargo.Tick(now)end
    instance.Release=function()cargo.Stop("CScript stopped.");return release()end
    instance.CanHandoff=function()return not cargo.Snapshot().running and can_handoff()end
    context.CScript.BusinessAutomation=instance
end
function Module.Stop()
    if instance and instance.Release()~=true then error("Business automation restoration remains pending.") end
end
function Module.Restore(context)
    Module.Stop()
    if context and context.CScript then context.CScript.BusinessAutomation=nil;context.CScript.CargoFarm=nil end
    instance=nil
end
return Module
