local farm_finish_requests={}
local farm_finish_detail
-- Opaque, detached row identity; never expose internal farm tables to the UI.
-- Weak keys drop old farms naturally. Sequence is never reset on Stop/Init.
local farm_row_tokens=setmetatable({}, {__mode="k"})
local farm_row_sequence=0
local function farm_row_token(farm)
    if not farm or not farm.active then return nil end
    local token=farm_row_tokens[farm]
    if not token or token.account~=farm.account or token.slot~=farm.slot or token.generation~=farm.generation then
        farm_row_sequence=farm_row_sequence+1
        token={id=farm_row_sequence,account=farm.account,slot=farm.slot,generation=farm.generation}
        farm_row_tokens[farm]=token
    end
    return token.id
end
