-- One validated registry controls both normal browsing and ownership discovery.
local MAIN_BUSINESS_KEYS = {
    "nightclub", "bunker", "acid_lab", "hangar", "special_cargo", "vehicle_cargo",
    "mc_cocaine", "mc_meth", "mc_cash", "mc_weed", "mc_documents", "salvage_yard",
    "bail_office", "agency", "arcade", "auto_shop", "garment_factory",
    "car_wash", "weed_shop", "heli_tours",
}
local BUSINESS_BY_KEY = {}
for _, item in ipairs(BUSINESS_CATALOG) do BUSINESS_BY_KEY[item.key] = item end
local MAIN_BUSINESSES, MAIN_CATALOG = {}, {}
for _, key in ipairs(MAIN_BUSINESS_KEYS) do
    assert(BUSINESS_BY_KEY[key] and not MAIN_BUSINESSES[key], "Invalid main business key: " .. tostring(key))
    MAIN_BUSINESSES[key] = true
    MAIN_CATALOG[#MAIN_CATALOG + 1] = BUSINESS_BY_KEY[key]
end
local economy

local function nightclub_popularity_transaction(slot, core, value, label)
    if not core or type(core.RunTransaction) ~= "function" then
        return false, "Economy transaction service is unavailable"
    end
    return core.RunTransaction({
        action_key = "business:nightclub:popularity:" .. tostring(value),
        label = label, family = "Nightclub",
        expected_slot = slot,
        values = { CLUB_POPULARITY = value },
        order = { "CLUB_POPULARITY" },
        labels = { CLUB_POPULARITY = "Nightclub Popularity" },
        validate = function(current_slot)
            if current_slot ~= slot then return false, "character slot changed after Business refresh" end
            if not State or State.selected_business ~= "nightclub" then
                return false, "selected business changed after the action was queued"
            end
            local current = State.statuses and State.statuses.nightclub
            if not current or current.owned ~= true then return false, "Nightclub ownership is not validated" end
            if current.can_mutate ~= true then return false, current.reason or "Nightclub popularity is not mutation-ready" end
            return true
        end,
    })
end

local function business_transaction(status, values, label, action_key)
    local core = economy()
    if not core or type(core.RunTransaction) ~= "function" then
        return false, "Economy transaction service is unavailable"
    end
    local slot = status and status.character_slot
    local selected = status and status.key
    local order = {}
    for key in pairs(values or {}) do order[#order + 1] = key end
    table.sort(order)
    return core.RunTransaction({
        action_key = "business:" .. tostring(selected) .. ":" .. tostring(action_key),
        label = label, family = status and status.name or "Business",
        expected_slot = slot, values = values, order = order,
        validate = function(current_slot)
            if current_slot ~= slot then return false, "character slot changed after Business refresh" end
            if not State or State.selected_business ~= selected then
                return false, "selected business changed after the action was queued"
            end
            local current = State.statuses and State.statuses[selected]
            if not current or current.owned ~= true then return false, "business ownership is not validated" end
            if current.can_mutate ~= true then return false, current.reason or "business state is not mutation-ready" end
            for _, key in ipairs(order) do
                if not (current.read_values and current.read_values[key] ~= nil) then
                    return false, tostring(key) .. " is not readable; zero writes were performed"
                end
            end
            return true
        end,
    })
end

local function read_value(status, key)
    return status and status.read_values and status.read_values[key]
end

local function binding(name)
    local raw = module_context and module_context.Raw
    if raw and raw[name] ~= nil then return raw[name] end
    return type(_G) == "table" and _G[name] or nil
end

local THREAD_COUNT_HASH = 0x2C83A9DA6BFFC4F9
local NETWORK_GET_HOST_OF_SCRIPT = 0x1D6A14F1F9A736FC

-- One button, three exact current-build completion contracts. MC/Hangar remain
-- network-script-host gated. The Bunker contract is local-controller gated: the
-- live Enhanced sale proved the writable local gb_gunrunning controller can be
-- owned by a participant who is not NETWORK_GET_HOST_OF_SCRIPT. None of these
-- paths alters payout tunables, account stats, stock totals, or other missions.
local ACTIVE_SALE_PROFILES = {
    { key="hangar_ground",label="Hangar Ground Sale",script="fm_content_smuggler_sell",local_base=4232,host_required=true,
      evidence="Installed Enhanced fm_content_smuggler_sell: delivery snapshot f_60, success bit 11 and native outcome/phase transition" },
    {
        key = "mc", label = "MC Business Sale", script = "gb_biker_contraband_sell",
        local_base = 738, host_required = true,
        evidence = "Enhanced gb_biker_contraband_sell: f_122 delivered, f_174 required snapshot, f_957 route tier",
    },
    {
        key = "bunker", label = "Bunker Sale", script = "gb_gunrunning",
        local_base = 1275, host_required = false,
        evidence = "Enhanced gb_gunrunning: f_774 is the active delivery-unit count consumed by the host completion loops",
    },
    {
        key = "hangar", label = "Hangar Sale", script = "gb_smuggler",
        local_base = 1998, host_required = true,
        evidence = "Enhanced gb_smuggler: immutable f_1035 vehicle count, route drop total, host per-vehicle delivered bits and quantitative f_1078",
    },
}

local function active_sale_profile(key)
    for _,profile in ipairs(ACTIVE_SALE_PROFILES) do if profile.key==key then return profile end end
end

local function script_hash(name)
    local utils = binding("Utils")
    if not (utils and type(utils.Joaat) == "function") then return nil, "Utils.Joaat is unavailable" end
    local ok, value = pcall(utils.Joaat, tostring(name or ""))
    value = ok and tonumber(value) or nil
    if value == nil then return nil, "script hash could not be resolved" end
    return value
end

local function script_thread_count(hash)
    local natives = binding("Natives")
    if not (natives and type(natives.InvokeInt) == "function") then
        return nil, "Cherax script-thread detection is unavailable"
    end
    local ok, value = pcall(natives.InvokeInt, THREAD_COUNT_HASH, hash)
    value = ok and tonumber(value) or nil
    if value == nil then return nil, "script-thread detection failed" end
    return math.max(0, math.floor(value))
end

local function local_player_id()
    local gta = binding("GTA")
    if not (gta and type(gta.GetLocalPlayerId) == "function") then
        return nil, "local player id is unavailable"
    end
    local ok, value = pcall(gta.GetLocalPlayerId)
    value = ok and tonumber(value) or nil
    if value == nil or value < 0 or value > 31 then return nil, "local player id is invalid" end
    return math.floor(value)
end

local function active_sale_context(profile, hash)
    if script_thread_count(hash)~=1 then return nil,"Multiple sale instances are active."end
    local locals = binding("ScriptLocal")
    if not (locals and type(locals.GetInt) == "function" and type(locals.SetInt) == "function") then
        return nil, "Cherax ScriptLocal read/write access is unavailable"
    end
    local player, player_err = local_player_id()
    if player == nil then return nil, player_err end
    if profile.host_required ~= false then
        local natives = binding("Natives")
        if not (natives and type(natives.InvokeInt) == "function") then
            return nil, "Cherax script-host detection is unavailable"
        end
        local scripts=binding("Script")
        if not scripts or type(scripts.ExecuteAsScript)~="function" or type(natives.InvokeBool)~="function" then
            return nil,"Exact sale-thread host detection is unavailable."
        end
        local actual,host,thread
        local called=pcall(scripts.ExecuteAsScript,profile.script,function()
            actual=natives.InvokeInt(0x8A1C8B1738FFE87E)
            thread=natives.InvokeInt(0xC30338E8088E2E21)
            host=natives.InvokeBool(0x83CD99A1E6061AB5)
        end)
        if not called or type(actual)~="number" or actual%4294967296~=hash%4294967296
            or type(thread)~="number" or thread<=0 or natives.InvokeBool(0x46E9AE36D8FA6417,thread)~=true then
            return nil,"The active sale thread could not be validated."
        end
        if host~=true then return nil,profile.label.." requires the host of this sale script."end

    end
    return { profile = profile, hash = hash, locals = locals, player = player }
end

local function read_sale_local(ctx, index, minimum, maximum, label)
    local ok, value = pcall(ctx.locals.GetInt, ctx.hash, math.floor(index))
    value = ok and tonumber(value) or nil
    if value == nil or value % 1 ~= 0 or value < minimum or value > maximum then
        return nil, ("%s local %d is outside the validated %d..%d range")
            :format(label, index, minimum, maximum)
    end
    return math.floor(value)
end

local function write_sale_local(ctx, index, value, label)
    local ok, result = pcall(ctx.locals.SetInt, ctx.hash, math.floor(index), math.floor(value))
    if not ok or result == false then return false, label .. " write was rejected" end
    local observed, read_err = read_sale_local(ctx, index, -1, 1000, label)
    if observed == value then return true end
    local threads = script_thread_count(ctx.hash)
    if threads == 0 then return true, "sale script transitioned after accepting the completion trigger" end
    return false, read_err or (label .. " write did not verify")
end

-- gb_biker_contraband_sell: func_1296 pays kind 0 from f_978, which
-- func_493 recounts from f_7 bit 15. Other kinds use f_122; func_1295
-- adds f_167 for kinds 4/10/11/12. Keep payout evidence ahead of completion.
-- Enhanced freemode func_18148 clears Global_2699654 while announcement 86
-- is at the head of the four-row queue. MC func_889 needs that reward again
-- when its asynchronous inventory checkout completes. Finishing during the
-- start banner therefore removes stock without issuing the native payment.
-- The head kind alone clears the reward (including phase 0); readiness is
-- the queue leaving that condition, not a fixed elapsed-time delay.
function Module.NewMCStartBarrier(host)
    local api={}
    function api.Ready(token)
        local now=host.Now()
        if not token or type(now)~='number' then return false,'MC sale readiness is unavailable.' end
        if host.Read(2675867)~=4 then return false,'MC announcement layout does not match.' end
        for i=0,3 do
            local kind,phase=host.Read(2675869+i*80),host.Read(2675870+i*80)
            if type(kind)~='number' or type(phase)~='number' or phase%1~=0 or phase<0 or phase>5 then
                return false,'MC announcement state is unavailable.'
            end
            if kind==86 and (i==0 or phase~=0) then
                return false,'Waiting for the sale-start announcement before finishing.'
            end
        end
        return true
    end
    return api
end

function Module.NewMCDelivery(host)
    local api={}
    local function request()
        local token=host.Capture()
        if not token or not host.Valid(token) then return false,"MC controller identity changed." end
        local function get(i,lo,hi)
            local v=host.Read(i)
            if type(v)~="number" or v%1~=0 or v<lo or v>hi then
                error("MC sale is not ready (field "..i.."); wait for the sell vehicles to spawn.",0)
            end
            return v
        end
        get(743,1,1);get(752,1,1);get(753,0,0)
        local kind=get(755,0,12)
        get(1695,0,2);get(737,2,2);get(1723,8,8)
        local participant=token.participant
        if type(participant)~="number" or participant%1~=0 or participant<0 or participant>7 then
            return false,"MC participant could not be verified."
        end
        local p=1724+participant*29
        get(p+1,1,1);get(p+25,1,1000);get(p+26,0,1000)
        local required=get(912,1,100)
        local target=required
        if kind==4 or kind==10 or kind==11 or kind==12 then target=required+get(905,0,100) end
        local delivered=get(860,0,200)
        local rows={}
        if kind==0 then
            if required~=1 then return false,"MC single-vehicle layout does not match." end
            local flags=get(745,-2147483648,2147483647)
            local vehicles=get(1716,0,1)
            rows[#rows+1]={index=745,before=flags,after=flags|32768}
            rows[#rows+1]={index=1716,before=vehicles,after=1}
        end
        rows[#rows+1]={index=860,before=delivered,after=target}
        if host.BeforeCommit then
            local ready,why=host.BeforeCommit(token)
            if not ready then return false,why end
        end
        for _,r in ipairs(rows) do
            if not host.Valid(token) or host.Read(r.index)~=r.before then
                return false,"MC controller changed before completion."
            end
            if r.before~=r.after then
                if host.Write(r.index,r.after)==false or host.Read(r.index)~=r.after then
                    return false,"MC delivery write did not verify."
                end
            end
        end
        return true,"MC delivery completion requested; payment has not been verified."
    end
    function api.Request()
        local ok,result,detail=pcall(request)
        if not ok then return false,tostring(result) end
        return result,detail
    end
    return api
end

local function complete_mc_sale(ctx)
    local raw,scripts,globals=binding("Natives"),binding("Script"),binding("ScriptGlobal")
    local core=economy()
    if not raw or not scripts or type(scripts.ExecuteAsScript)~="function" or not globals
        or type(ctx.locals.GetPtr)~="function" then return false,"MC controller APIs are unavailable." end
    local function capture()
        if not globals.AreValid() or raw.InvokeString(0xFCA9373EF340AC0A)~="1.73"
            or script_thread_count(ctx.hash)~=1 then return nil end
        local scope=core and core.Snapshot and core.Snapshot()
        local slot=core and core.CurrentSlot and core.CurrentSlot()
        if not scope or not scope.account_verified or not scope.online or (slot~=0 and slot~=1) then return nil end
        local thread,participant
        scripts.ExecuteAsScript(ctx.profile.script,function()
            thread=raw.InvokeInt(0xC30338E8088E2E21)
            participant=raw.InvokeInt(0x57A3BDDAD8E5AA0A)
        end)
        local pointer=ctx.locals.GetPtr(ctx.hash,738)
        if type(thread)~="number" or thread<=0 or type(pointer)~="number" or pointer<=0 then return nil end
        return {identity=tostring(thread)..":"..tostring(pointer),participant=participant,
            account=scope.account_id,slot=slot,generation=scope.generation}
    end
    if not mc_start_barrier then
        mc_start_barrier=Module.NewMCStartBarrier({
            Now=function()return raw.InvokeInt(0x9CD27B0045628463)end,
            Read=function(i)return globals.GetInt(i)end,
        })
    end
    return Module.NewMCDelivery({Capture=capture,BeforeCommit=mc_start_barrier.Ready,Valid=function(token)
        local current=capture()
        return current and token and current.identity==token.identity and current.participant==token.participant
            and current.account==token.account and current.slot==token.slot and current.generation==token.generation or false
        end,Read=function(i)return ctx.locals.GetInt(ctx.hash,i)end,
        Write=function(i,v)return ctx.locals.SetInt(ctx.hash,i,v)end}).Request()
end

-- Supplied gb_gunrunning.c: func_120 initializes f_774 as vehicle/unit count.
-- Success uses per-unit delivered bit 6, f_816 drop totals, result 3 and phase 14.
-- Do not zero the vehicle count: func_1111 also needs it to count successful units.
function Module.NewBunkerDelivery(host)
    local function number(v,lo,hi)return type(v)=="number" and v==v and v%1==0 and v>=lo and v<=hi end
    local api={}
    local function request()
        local token=host.Capture()
        if not token or not host.Valid(token)then return false,"Bunker controller identity/host could not be verified."end
        local function get(i,lo,hi)
            local v=host.Read(i)
            if not number(v,lo,hi)then error("Bunker controller field is unavailable: "..i,0)end
            return v
        end
        local kind=get(1276,14,19)
        local state=get(1848,1,1)
        local phase=get(1856,3,13)
        local outcome=get(1857,0,0)
        local units=get(2049,1,8)
        get(1342,8,8)
        local multiplier=(kind==14 or kind==16 or kind==19) and 5 or 1
        local dropped=get(2091,0,units*multiplier)
        local rows={}
        for i=0,units-1 do
            get(1343+i*3,2,2)
            local flags=get(1344+i*3,-2147483648,2147483647)
            if flags==-1 or (flags & 32)~=0 then return false,"A delivery unit is already destroyed; no completion was attempted."end
            rows[#rows+1]={index=1344+i*3,before=flags,after=flags|64}
        end
        rows[#rows+1]={index=2091,before=dropped,after=units*multiplier}
        rows[#rows+1]={index=1857,before=outcome,after=3}
        rows[#rows+1]={index=1856,before=phase,after=14}
        for _,row in ipairs(rows)do
            if not host.Valid(token)then return false,"Bunker controller changed; remaining writes cancelled."end
            if host.Read(row.index)~=row.before then return false,"Bunker phase changed; remaining writes cancelled."end
            if row.before~=row.after then
                if host.Write(row.index,row.after)==false or host.Read(row.index)~=row.after then
                    return false,"Bunker completion request was not confirmed. It will not be replayed automatically."
                end
            end
        end
        token.outcome="REQUESTED";token.kind=kind;token.units=units;token.deliveries=units*multiplier
        return true,token
    end
    function api.Request()
        local ok,result,why=pcall(request)
        if not ok then return false,tostring(result)end
        return result,why
    end
    return api
end

local function complete_bunker_sale(ctx)
    local raw_natives=binding("Natives")
    local scripts=binding("Script")
    local globals=binding("ScriptGlobal")
    if not raw_natives or not scripts or type(scripts.ExecuteAsScript)~="function"
        or not globals or type(globals.AreValid)~="function" or type(ctx.locals.GetPtr)~="function"then
        return false,"Bunker controller API unavailable."
    end
    local core=economy()
    local function capture()
        if not globals.AreValid() or raw_natives.InvokeString(0xFCA9373EF340AC0A)~="1.73"
            or script_thread_count(ctx.hash)~=1 then return nil end
        -- For Bunker, stable local thread/pointer identity plus account/slot/generation
        -- is the authority boundary. Live Enhanced testing proved the local writable
        -- controller can belong to a non-network-host participant. NewBunkerDelivery
        -- revalidates that identity and exact readback before every remaining write.
        local scope=core and core.Snapshot and core.Snapshot()
        local slot=core and core.CurrentSlot and core.CurrentSlot()
        if not scope or not scope.account_verified or not scope.online or (slot~=0 and slot~=1)then return nil end
        local thread
        scripts.ExecuteAsScript(ctx.profile.script,function()thread=raw_natives.InvokeInt(0xC30338E8088E2E21)end)
        local pointer=ctx.locals.GetPtr(ctx.hash,1275)
        if type(thread)~="number" or thread<=0 or type(pointer)~="number" or pointer<=0 then return nil end
        return {identity=tostring(thread)..":"..tostring(pointer),account=scope.account_id,slot=slot,generation=scope.generation}
    end
    local operation=Module.NewBunkerDelivery({Capture=capture,
        Valid=function(token)
            local current=capture()
            return current and token and current.identity==token.identity and current.account==token.account
                and current.slot==token.slot and current.generation==token.generation or false
        end,
        Read=function(index)return ctx.locals.GetInt(ctx.hash,index)end,
        Write=function(index,value)return ctx.locals.SetInt(ctx.hash,index,value)end})
    local ok,result=operation.Request()
    if not ok then return false,result end
    return true,"Bunker completion requested. Payment has not been verified."
end

local function complete_hangar_sale(ctx)
    local reserve=module_context and module_context.CScript and module_context.CScript.HangarPocket
    local reserve_state=reserve and reserve.Snapshot and reserve.Snapshot()
    if reserve_state and (reserve_state.running or reserve_state.cleanup_pending or reserve_state.action and reserve_state.action.busy) then return false,"Stop Pocket Dimension and wait for its cargo transaction to settle before finishing a sale." end
    -- Enhanced gb_smuggler SHA256 98b43a6c2601960a6c8469861b93a374e7b970f0975527b05efea1f96cf9073a:
    -- func26 = f1035 * func28(route); func237 recounts delivered bits into f1078.
    -- End payload f10/f11 feeds func1331's partial-cargo/full-bulk money branch.
    -- f1035 is the original VEHICLE count, never a remaining-work counter.
    local function request()
        if not ctx or ctx.profile.script~='gb_smuggler' or ctx.profile.local_base~=1998 then return false,'Hangar sale profile changed.' end
        local raw,globals,scripts=binding('Natives'),binding('ScriptGlobal'),binding('Script')
        local core=economy()
        if not raw or not globals or not scripts or not core or type(ctx.locals.GetPtr)~='function' then
            return false,'Hangar controller identity APIs are unavailable.'
        end
        local function capture()
            if globals.AreValid()~=true or raw.InvokeString(0xFCA9373EF340AC0A)~='1.73' then return nil end
            local current=active_sale_context(ctx.profile,ctx.hash)
            if not current or current.locals~=ctx.locals or current.player~=ctx.player then return nil end
            -- func211/func5: owner payout belongs to the local organization boss.
            if type(globals.GetInt)~='function' or globals.GetInt(1893070)~=32
                or globals.GetInt(1893070+1+ctx.player*615+10)~=ctx.player then return nil end
            local scope=core.Snapshot();local slot=core.CurrentSlot()
            if not scope or scope.account_verified~=true or scope.online~=true or scope.account_id==nil
                or scope.generation==nil or (slot~=0 and slot~=1) then return nil end
            local thread
            scripts.ExecuteAsScript(ctx.profile.script,function()thread=raw.InvokeInt(0xC30338E8088E2E21)end)
            local pointer=ctx.locals.GetPtr(ctx.hash,1998)
            if type(thread)~='number' or thread<=0 or type(pointer)~='number' or pointer<=0 then return nil end
            return {thread=thread,pointer=pointer,account=scope.account_id,generation=scope.generation,slot=slot}
        end
        local token=capture();if not token then return false,'Hangar controller identity is unavailable.' end
        local function valid()
            local current=capture()
            return current and current.thread==token.thread and current.pointer==token.pointer
                and current.account==token.account and current.generation==token.generation and current.slot==token.slot
        end
        local guards={}
        local function get(index,lo,hi)
            local value=ctx.locals.GetInt(ctx.hash,index)
            if type(value)~='number' or value%1~=0 or value<lo or value>hi then
                error('Hangar sale contract is unavailable or changed (local '..tostring(index)..').',0)
            end
            guards[index]=value;return value
        end
        local route=get(2000,15,25)
        local phase=get(2768,0,19)
        -- Only these phases directly consume func51/53's per-vehicle success.
        -- Other phases have separate route/cleanup gates; do not fabricate them.
        if phase~=7 and phase~=14 then
            return false,('Hangar delivery phase %d is not ready for the verified completion path.'):format(phase)
        end
        local result=get(2769,0,2)
        if result==1 then return false,'Hangar sale already has a failed outcome.' end
        get(2004,8,8);get(2067,8,8)
        local vehicles=get(3033,1,8)
        local drops=({[15]=2,[16]=5,[17]=5,[18]=1,[19]=1,[20]=5,[21]=3,[22]=5,[23]=1,[24]=2,[25]=5})[route]
        local required=vehicles*drops
        local delivered=get(3076,0,required)
        local rows={{index=3076,before=delivered,after=required}}
        for i=0,vehicles-1 do
            get(2068+i*3,2,2)
            local flags=get(2069+i*3,-2147483648,2147483647)
            get(2070+i*3,-2147483648,2147483647)
            if (flags&32)~=0 then return false,'Hangar cargo was already lost; full delivery was not requested.' end
            rows[#rows+1]={index=2069+i*3,before=flags,after=flags|64}
        end
        local applied={}
        local function rollback()
            -- Never write into a replacement VM/account or undo a native outcome.
            local function can_restore()
                if not valid() then return false end
                local phase_read,current_phase=pcall(ctx.locals.GetInt,ctx.hash,2768)
                local result_read,current_result=pcall(ctx.locals.GetInt,ctx.hash,2769)
                return phase_read and result_read and current_phase==phase and current_result==result
            end
            for i=#applied,1,-1 do
                if not can_restore() then return end
                local row=applied[i]
                local read,current=pcall(ctx.locals.GetInt,ctx.hash,row.index)
                if read and current==row.after and can_restore() then
                    pcall(ctx.locals.SetInt,ctx.hash,row.index,row.before)
                end
            end
        end
        local function fail(why)
            pcall(rollback);return false,why
        end
        for _,row in ipairs(rows) do
            if not valid() then return fail('Hangar controller identity changed before delivery completion.') end
            for index,value in pairs(guards) do
                local read,current=pcall(ctx.locals.GetInt,ctx.hash,index)
                if not read or current~=value then return fail('Hangar delivery state changed or became unreadable before completion.') end
            end
            if row.before~=row.after then
                if not valid() then return fail('Hangar controller identity changed while checking delivery state.') end
                -- Record before entering a writer that may partially apply.
                applied[#applied+1]=row
                local called,wrote=pcall(ctx.locals.SetInt,ctx.hash,row.index,row.after)
                local read,current=pcall(ctx.locals.GetInt,ctx.hash,row.index)
                if not called or wrote==false or not read or current~=row.after then
                    return fail('Hangar delivery write did not verify; no automatic retry.')
                end
                guards[row.index]=row.after
            end
        end
        return true,('Hangar full-delivery completion requested (%d vehicles, %d/%d drops). Payment has not been verified.')
            :format(vehicles,required,required)
    end
    local ok,result,detail=pcall(request)
    if not ok then return false,'Hangar sale completion stopped: '..tostring(result) end
    return result,detail
end

