local function bunker_app_sale_host(profile,business)
    local BUNKER_APP_SOURCE=profile or BUNKER_APP_SOURCE
    local raw=module_context and module_context.Raw or {}
    local natives,utils,locals,globals,gta=raw.Natives,raw.Utils,binding("ScriptLocal"),raw.ScriptGlobal,raw.GTA
    local core=economy()
    if not natives or type(natives.InvokeInt)~="function" or type(natives.InvokeBool)~="function"
        or type(natives.InvokeVoid)~="function" or not utils or type(utils.Joaat)~="function"
        or not locals or type(locals.GetInt)~="function" or type(locals.SetInt)~="function"
        or not globals or type(globals.GetInt)~="function" or type(globals.SetInt)~="function"
        or not gta or type(gta.GetLocalPlayerId)~="function" or not core then
        return nil,"Bunker app driver APIs are unavailable."
    end
    local memory=raw.Memory
    if not memory or type(memory.ScanScript)~="function" or type(memory.ReadUByte)~="function"
        or type(memory.WriteUByte)~="function" then return nil,"Bunker background app memory APIs are unavailable." end
    local app_hash=utils.Joaat(BUNKER_APP_SOURCE.script)
    local gun_hash=utils.Joaat(BUNKER_APP_SOURCE.mc and "gb_biker_contraband_sell" or "gb_gunrunning")
    local host={}
    local function current_scope()
        local scope=type(core.Snapshot)=="function" and core.Snapshot() or nil
        local slot=type(core.CurrentSlot)=="function" and core.CurrentSlot() or nil
        local pok,pid=pcall(gta.GetLocalPlayerId);pid=pok and tonumber(pid) or nil
        if type(scope)~="table" or scope.account_verified~=true or scope.online~=true
            or (slot~=0 and slot~=1) or not pid or pid<0 or pid>31 then return nil end
        return {account=scope.account_id,generation=scope.generation,slot=slot,pid=math.floor(pid)}
    end
    local function same_scope(token)
        local scope=current_scope()
        return scope and token and scope.account==token.account and scope.generation==token.generation
            and scope.slot==token.slot and scope.pid==token.pid or false
    end
    local function threads(hash)
        local ok,v=pcall(natives.InvokeInt,THREAD_COUNT_HASH,hash);v=ok and tonumber(v) or nil
        return v and math.max(0,math.floor(v)) or nil
    end
    local function app_loaded()
        local ok,value=pcall(natives.InvokeBool,BUNKER_APP_NATIVE.HAS_SCRIPT_LOADED,BUNKER_APP_SOURCE.script)
        return ok and value or (ok and false or nil)
    end
    local terminated_owned_thread=false
    local quiet=Module.NewBunkerQuietApp({
        Loaded=app_loaded,Threads=function()
            local count=threads(app_hash)
            return terminated_owned_thread and count==1 and 0 or count
        end,
        Scan=function(pattern)return memory.ScanScript(app_hash,pattern) end,
        Read=memory.ReadUByte,Write=memory.WriteUByte,
    },BUNKER_APP_SOURCE.quiet_patches)
    local function release_quiet()
        if not quiet.Pending() then return true end
        local ok,why=quiet.Restore()
        if ok then pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.SET_SCRIPT_NO_LONGER_NEEDED,BUNKER_APP_SOURCE.script) end
        return ok,why
    end
    local function app_local(index)
        local ok,v=pcall(locals.GetInt,app_hash,index);v=ok and tonumber(v) or nil
        return v and math.floor(v) or nil
    end
    local function set_app_local(index,value)
        local ok,result=pcall(locals.SetInt,app_hash,index,value)
        if not ok or result==false then return false end
        return app_local(index)==value
    end
    local function sf_begin(handle,name)
        local ok,v=pcall(natives.InvokeBool,BUNKER_APP_NATIVE.BEGIN_SF,handle,name)
        return ok and v==true
    end
    local function sf_end()
        return pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.END_SF)
    end
    function host.Capture()
        local scope=current_scope();if not scope then return nil,"Verified GTA Online character context is unavailable." end
        local factory=5
        if BUNKER_APP_SOURCE.mc then
            local item=BUSINESS_BY_KEY[business]
            if not item or not item.factory_ids then return nil,"Unsupported MC business." end
            factory=nil
            for i=0,4 do
                local property=core.ReadStat(core.QualifyStat(scope.slot,"FACTORYSLOT"..i))
                for _,id in ipairs(item.factory_ids) do
                    if property==id then
                        if factory~=nil then return nil,"Duplicate MC factory assignment." end
                        factory=i
                    end
                end
            end
            if factory==nil then return nil,"MC business is not owned." end
        end
        local owned=type(core.ReadStat)=="function" and type(core.QualifyStat)=="function"
            and core.ReadStat(core.QualifyStat(scope.slot,"FACTORYSLOT"..factory)) or nil
        local stock=type(core.ReadStat)=="function" and type(core.QualifyStat)=="function"
            and core.ReadStat(core.QualifyStat(scope.slot,"PRODTOTALFORFACTORY"..factory)) or nil
        if not tonumber(owned) or tonumber(owned)<=0 then return nil,"Bunker ownership is not verified." end
        if not tonumber(stock) or tonumber(stock)<=0 then return nil,"Bunker has no stock to sell." end
        if threads(gun_hash) and threads(gun_hash)>0 then return nil,"A Bunker sell mission is already active." end
        local roster_ok,header=pcall(globals.GetInt,1893070)
        local boss_ok,boss=pcall(globals.GetInt,1893070+1+scope.pid*615+10)
        if not roster_ok or tonumber(header)~=32 or not boss_ok or tonumber(boss)~=scope.pid then
            return nil,"Register as a CEO/MC boss before starting Bunker Auto Farm."
        end
        if BUNKER_APP_SOURCE.mc then
            -- Collected appBikerBusiness bytecode: sale eligibility 0xD01 ->
            -- 0xA41A -> 0x3785 -> 0x3794(player,1). Requires local ownership
            -- AND roster.f_10.f_433==1, matching Session's MC type contract.
            local type_index=1893070+1+scope.pid*615+10+433
            local type_ok,boss_type=pcall(globals.GetInt,type_index)
            if not type_ok or boss_type~=1 then
                return nil,"Register as an MC President before starting an MC sale (organization type "..tostring(type_ok and boss_type or "unreadable")..")."
            end
        end
        local browser_ok,browser=pcall(globals.GetInt,BUNKER_APP_SOURCE.browser_global)
        if not browser_ok or tonumber(browser)~=0 then return nil,"Close the existing in-game computer before background farming." end
        local other_app=utils.Joaat(BUNKER_APP_SOURCE.mc and "appBunkerBusiness" or "appBikerBusiness")
        if threads(other_app)~=0 then return nil,"Close the other business laptop first." end
        if BUNKER_APP_SOURCE.mc then
            for _,name in ipairs({"gb_gunrunning","gb_smuggler"}) do
                if threads(utils.Joaat(name))~=0 then return nil,"Finish the current business sale first." end
            end
        end
        local app_threads=threads(app_hash)
        if app_threads~=0 then return nil,"Close the existing Bunker laptop before starting background farming." end
        local released,why=release_quiet();if not released then return nil,why end
        return {account=scope.account,generation=scope.generation,slot=scope.slot,pid=scope.pid,
            factory=factory,property=owned,app_preexisting=app_threads>0,app_started=false}
    end
    function host.Valid(token)return same_scope(token) end
    function host.EnsureApp(token)
        if not same_scope(token) then return false,"Character context changed before Bunker app start." end
        local count=threads(app_hash)
        if count==1 then
            return token.app_started==true and quiet.Pending(),"Existing Bunker app is not owned by this background launch."
        end
        if count and count>1 then return false,"Multiple Bunker app threads are active." end
        pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.REQUEST_SCRIPT,BUNKER_APP_SOURCE.script)
        local loaded_ok,loaded=pcall(natives.InvokeBool,BUNKER_APP_NATIVE.HAS_SCRIPT_LOADED,BUNKER_APP_SOURCE.script)
        if not loaded_ok then return false,"Bunker app load-state query failed." end
        if loaded~=true then return true,"loading" end
        local patched,patch_err=quiet.Apply()
        if not patched then return false,patch_err end
        local start_ok,thread=pcall(natives.InvokeInt,BUNKER_APP_NATIVE.START_NEW_SCRIPT,BUNKER_APP_SOURCE.script,BUNKER_APP_SOURCE.stack_size)
