    function host.Read(token)
        if not same_scope(token) then return nil,"Character context changed." end
        local count=threads(app_hash);if count==nil then return nil,"Bunker app thread state unavailable." end
        local controller=threads(gun_hash) or 0
        if count==0 then return {threads=0,controller_threads=controller,page=nil,stage=nil,scaleform=nil,overlay=false} end
        if count~=1 then return nil,"Multiple Bunker app threads are active." end
        if BUNKER_APP_SOURCE.mc then
            local handle,command,property,stage,overlay,quote=app_local(728),app_local(551),app_local(557),app_local(552),app_local(547),app_local(553)
            if handle==nil or command==nil or property==nil or stage==nil or overlay==nil or quote==nil then
