            app_local(BUNKER_APP_SOURCE.stage_local),app_local(BUNKER_APP_SOURCE.scaleform_local)
        if flags==nil or page==nil or stage==nil or scaleform==nil then return nil,"Bunker app locals are unavailable." end
        if page<0 or page>7 or stage<0 or stage>15 then return nil,"Bunker app local layout does not match this build." end
