    function host.BindBusiness(token)
        if not same_scope(token) or not BUNKER_APP_SOURCE.mc then return false,"MC context changed." end
        if not set_app_local(557,token.property) or not set_app_local(555,-1) or not set_app_local(553,-1) then
            return false,"MC selected business did not verify."
