        if not sf_begin(state.scaleform,"GET_CURRENT_SELECTION") then return nil,"Bunker selection query was rejected." end
        local ok,handle=pcall(natives.InvokeInt,BUNKER_APP_NATIVE.END_SF_RETURN)
        handle=ok and tonumber(handle) or nil
