        if not ok then return nil,false,"Bunker selection readiness query failed." end
        if ready~=true then return nil,false,nil end
        local rok,value=pcall(natives.InvokeInt,BUNKER_APP_NATIVE.SF_GET_INT,handle)
        value=rok and tonumber(value) or nil
        if not value or value%1~=0 then return nil,false,"Bunker selection result is invalid." end
        return math.floor(value),true,nil
    end
    function host.SelectCity(token,state)
        state=state or host.Read(token)
        if type(state)~="table" or not state.scaleform or state.scaleform<=0 then return false,"Bunker scaleform unavailable." end
        if state.page~=7 or state.overlay then return false,"Bunker Sell page is not ready for selection." end
