        state=state or host.Read(token)
        if type(state)~="table" or state.threads~=1 or (state.flags & 1)~=0 then
            return false,"Bunker app selection dispatch is already pending."
        end
        -- Reproduce func_574's result handles, rather than synthesizing a PAD edge.
        -- func_11 waits for both responses and owns all validation/transactions.
        local selection,why=host.QuerySelection(token,state)
