end

local function get_bunker_app_engine()
    if bunker_app_engine then return bunker_app_engine end
    local host,why=bunker_app_sale_host()
    if not host then return nil,why end
    bunker_app_engine=Module.NewBunkerAppSale(host)
    return bunker_app_engine
end

local function start_bunker_app_sale()
    local engine,why=get_bunker_app_engine();if not engine then return false,why end
    local now=State and tonumber(State.clock_ms) or 0
    if not now or now<=0 then
        local time=binding("Time")
        if time and type(time.GetEpocheMs)=="function" then
            local called,value=pcall(time.GetEpocheMs);if called then now=tonumber(value) or 0 end
        end
    end
    local ok,row=engine.Start(now or 0)
    if not ok then return false,row end
    return true,"Bunker Disruption Logistics sale start armed for Los Santos."
end

local function bunker_app_sale_snapshot()
    return bunker_app_engine and bunker_app_engine.Snapshot() or {phase="IDLE",ok=nil}
end

local function tick_bunker_app_sale(now)
    if not bunker_app_engine then return end
    local before=bunker_app_engine.Snapshot()
    local row=bunker_app_engine.Tick(now)
    if type(row)~="table" or row.phase==before.phase then return end
    if row.phase=="STARTED" then
        State.last_action={ok=true,key="start_bunker_app_sale",detail="Bunker sale controller started through Disruption Logistics."}
    elseif row.phase=="FAILED" then
        State.last_action={ok=false,key="start_bunker_app_sale",detail=tostring(row.reason or "Bunker app sale failed.")}
    end
end

