-- archive were independently verified in the supplied current Enhanced 1.73
-- source corpus. Keep them separate from Hangar cargo: these are bounded
-- progress meters owned directly by Rockstar's packed-stat helpers, while
-- Hangar inventory has its own 50-slot lifecycle and reconciliation rules.
local PACKED_BUSINESS_PROFILES = {
    salvage_reputation = {
        key = "salvage_reputation", minimum = 0, maximum = 100,
        entries = {
            { index = 51051, label = "Salvage Yard Reputation" },
        },
