    },
}

local function request_profile_packed_int_write(profile, index, value)
    if type(profile) ~= "table" then return false, "packed business profile is unavailable" end
    index, value = tonumber(index), tonumber(value)
    local allowed = false
    for _, entry in ipairs(profile.entries or {}) do
        if tonumber(entry.index) == index then allowed = true; break end
    end
    if not allowed then return false, "packed stat index is outside the validated business profile" end
    if not value or value % 1 ~= 0 or value < profile.minimum or value > profile.maximum then
        return false, ("packed business value must be an integer from %d through %d")
            :format(profile.minimum, profile.maximum)
    end
    local natives = module_context and module_context.Natives
    if not natives or type(natives.Try) ~= "function" then
        return false, "typed native service is unavailable"
    end
    local ok, err = natives.Try("void", SET_PACKED_STAT_INT_CODE, math.floor(index), math.floor(value), -1)
    if not ok then return false, "SET_PACKED_STAT_INT_CODE failed: " .. tostring(err) end
    return true
end

local function packed_business_transaction(status, profile, target_by_index, label, action_key)
    if type(status) ~= "table" or status.owned ~= true then
        return false, "business ownership is not validated"
    end
    if not State or State.selected_business ~= status.key then
        return false, "selected business changed after the action was queued"
    end
    local core = economy()
    if not core or type(core.CurrentSlot) ~= "function" then
        return false, "Economy character-slot service is unavailable"
    end
    local current_slot, slot_err = core.CurrentSlot()
    if current_slot == nil or current_slot ~= status.character_slot then
        return false, slot_err or "character slot changed after Business refresh"
    end

    local before, changed = {}, {}
    for _, entry in ipairs(profile.entries or {}) do
        local index = tonumber(entry.index)
        local value, err = read_packed_int(index)
        if value == nil then
            return false, tostring(err or entry.label .. " could not be read") .. "; zero writes were performed"
        end
        if value < profile.minimum or value > profile.maximum then
            return false, ("%s returned %s outside the validated %d..%d scale; zero writes were performed")
                :format(entry.label, tostring(value), profile.minimum, profile.maximum)
        end
        local target = tonumber(target_by_index and target_by_index[index])
        if target == nil or target % 1 ~= 0 or target < profile.minimum or target > profile.maximum then
            return false, ("%s target is outside the validated %d..%d scale; zero writes were performed")
                :format(entry.label, profile.minimum, profile.maximum)
        end
        before[index] = value
    end

    local function rollback()
        local restored = true
        for position = #changed, 1, -1 do
            local entry = changed[position]
            local ok = request_profile_packed_int_write(profile, entry.index, entry.before)
            local observed = read_packed_int(entry.index)
            if not ok or observed ~= entry.before then restored = false end
        end
        return restored
    end

    for _, entry in ipairs(profile.entries or {}) do
        local index = tonumber(entry.index)
        local target = math.floor(tonumber(target_by_index[index]))
        if before[index] ~= target then
            local ok, err = request_profile_packed_int_write(profile, index, target)
            if not ok then
                local restored = rollback()
                return false, ("%s write was rejected; %s")
                    :format(entry.label, restored and "prior writes were restored" or "rollback could not be fully verified")
            end
            changed[#changed + 1] = { index = index, before = before[index], label = entry.label }
            local observed, verify_err = read_packed_int(index)
            if observed ~= target then
                local restored = rollback()
                return false, ("%s did not verify at %d (observed %s%s); %s")
                    :format(entry.label, target, tostring(observed), verify_err and ": " .. tostring(verify_err) or "",
                        restored and "all changed packed stats were restored" or "rollback could not be fully verified")
            end
        end
    end

    local detail = #changed == 0 and (label .. " was already applied.")
        or ("%s applied and verified across %d packed stat%s."):format(label, #changed, #changed == 1 and "" or "s")
    if module_context and module_context.Logger and type(module_context.Logger.Info) == "function" then
        module_context.Logger.Info(("packed-business action=%s changed=%d evidence=%s")
            :format(tostring(action_key), #changed, tostring(profile.evidence)), "Businesses")
    end
    return true, detail
end





local function read_hangar_inventory(character_slot)
    local result = { occupied = 0, empty = 0, invalid = 0, by_type = {}, slots = {} }
    for _, name in ipairs(HANGAR_TYPE_ORDER) do result.by_type[name] = 0 end
    for offset = 0, HANGAR_PACKED_PROFILE.count - 1 do
        local index = HANGAR_PACKED_PROFILE.first + offset
        local value, err = read_packed_int(index, character_slot)
        if value == nil then return nil, err end
        result.slots[offset + 1] = value
        if value == 0 then
            result.empty = result.empty + 1
        else
            local kind = HANGAR_PACKED_PROFILE.types[value]
            if not kind then
                result.invalid = result.invalid + 1
            else
                result.occupied = result.occupied + 1
                result.by_type[kind] = (result.by_type[kind] or 0) + 1
            end
        end
    end
    result.capacity = HANGAR_PACKED_PROFILE.capacity
    return result
end

local function current_capacity_contract(key)
    local profile = TUNABLE_GLOBALS[key]
    if not profile then return nil, "No current Enhanced capacity profile is available." end
    local globals = binding("ScriptGlobal")
    local memory = binding("Memory")
    local utils = binding("Utils")

    local raw_value
    if globals and type(globals.GetInt) == "function" then
        local ok, value = pcall(globals.GetInt, profile.index)
        value = ok and tonumber(value) or nil
        if value ~= nil and value % 1 == 0 and value >= profile.min and value <= profile.max then
            raw_value = math.floor(value)
        end
    end

    -- Cherax exposes a semantic tunable resolver by hash. Current Enhanced
    -- tuneables_processing.c registers these exact names, so prefer agreement
    -- between the semantic pointer and the verified raw Global_262145 field.
    local semantic_value, semantic_hash, semantic_ptr
    if globals and type(globals.GetTunableByHash) == "function"
        and memory and type(memory.ReadInt) == "function"
        and utils and type(utils.Joaat) == "function" then
        local hash_ok, hash = pcall(utils.Joaat, profile.name)
        semantic_hash = hash_ok and tonumber(hash) or nil
        if semantic_hash then
            local ptr_ok, ptr = pcall(globals.GetTunableByHash, semantic_hash)
            semantic_ptr = ptr_ok and tonumber(ptr) or nil
            if semantic_ptr and semantic_ptr ~= 0 then
                local read_ok, value = pcall(memory.ReadInt, semantic_ptr)
                value = read_ok and tonumber(value) or nil
                if value ~= nil and value % 1 == 0 and value >= profile.min and value <= profile.max then
                    semantic_value = math.floor(value)
                end
            end
        end
    end

    if semantic_value ~= nil and raw_value ~= nil and semantic_value ~= raw_value then
        return nil, ("Current %s capacity resolver disagreement (semantic=%s raw=%s); zero business writes were performed.")
            :format(profile.name, tostring(semantic_value), tostring(raw_value))
    end
    local value = semantic_value or raw_value
    if value == nil then
        return nil, ("Current %s capacity could not be validated through semantic or raw Enhanced resolver; zero business writes were performed."):format(profile.name)
    end
    return {
        key = key, name = profile.name, global_index = profile.index, value = value,
        semantic_hash = semantic_hash, semantic_pointer = semantic_ptr,
        resolver = semantic_value ~= nil and raw_value ~= nil and "semantic+raw agreement"
            or semantic_value ~= nil and "semantic hash" or "verified raw global",
        minimum = profile.min, maximum = profile.max,
        source = "current Enhanced tuneables_processing.c registration + Cherax GetTunableByHash / verified Global_262145 fallback",
        policy = "read live before every capacity-backed write; reject semantic/raw disagreement; never assume the default value",
    }
end

local function current_capacity(key)
    local contract, err = current_capacity_contract(key)
    if not contract then return nil, err end
    return contract.value
end

local function capacity_target(key, percent)
    local capacity, err = current_capacity(key)
    if not capacity then return nil, err end
    percent = tonumber(percent)
    if percent == nil or percent % 1 ~= 0 or percent < 0 or percent > 100 then
        return nil, "Business target percentage must be a whole value from 0 to 100; zero writes were performed."
    end
    return math.floor((capacity * percent / 100) + 0.5)
end

local function add_capacity_contract(status, key, label)
    if type(status) ~= "table" then return nil end
    local contract = current_capacity_contract(key)
    if not contract then return nil end
    status.capacity_contracts = status.capacity_contracts or {}
    contract.label = label or contract.name
    status.capacity_contracts[#status.capacity_contracts + 1] = contract
    return contract.value
end

local function warehouse_capacity(property_id)
    property_id = tonumber(property_id)
    if not property_id or property_id % 1 ~= 0 or property_id < 1 or property_id > 22 then return nil end
    if property_id == 1 or property_id == 2 or property_id == 3 or property_id == 4
        or property_id == 5 or property_id == 9 then return 16 end
    if property_id == 10 or property_id == 11 or property_id == 12 or property_id == 13
        or property_id == 14 or property_id == 15 or property_id == 21 or property_id == 7 then return 42 end
    if property_id == 16 or property_id == 17 or property_id == 18 or property_id == 19
        or property_id == 20 or property_id == 22 or property_id == 6 or property_id == 8 then return 111 end
    return nil
end

local function named_stat_adapter(version, action_info, actions, required_fields, support_reason)
    return {
        version = version,
        mutation_validated = true,
        action_info = action_info,
        actions = actions,
        refresh = function(_, _, status)
            if not status or status.owned ~= true then
                return { can_mutate = false, management_support = "Unavailable",
                    reason = "Business ownership must be detected before any transaction." }
            end
            local required = type(required_fields) == "function" and required_fields(status) or required_fields
            for _, key in ipairs(required or {}) do
                local value = read_value(status, key)
                if value == nil then
                    return { can_mutate = false, management_support = "Unavailable",
                        reason = tostring(key) .. " could not be read, so CScript will perform zero writes." }
                end
                if tonumber(value) == nil or value ~= math.floor(value) or value < 0 then
                    return { can_mutate = false, management_support = "Unavailable",
                        reason = tostring(key) .. " returned an invalid current value, so CScript will perform zero writes." }
                end
            end
            return { can_mutate = true, management_support = "Experimental",
                reason = support_reason or "Only current-source-correlated named stats are changed; every action rereads, verifies, and rolls back on failure." }
        end,
    }
end

