-- stats. Every change is delegated to the existing Economy
-- snapshot/apply/reread/verify/rollback transaction guard.
local ADAPTERS = {
    nightclub = {
        version = "nightclub-popularity-v1",
        mutation_validated = true,
        action_info = {
            { key = "popularity_max", label = "Set Popularity to 100%", style = "primary",
