                return nightclub_popularity_transaction(slot, core, 1000, "Nightclub Popularity - 100%")
            end,
            popularity_zero = function(slot, core)
                return nightclub_popularity_transaction(slot, core, 0, "Nightclub Popularity - 0%")
            end,
        },
        refresh = function(_, _, status)
            local popularity
            for _, field in ipairs(status and status.readouts or {}) do
                if field.key == "CLUB_POPULARITY" and field.error == nil then popularity = tonumber(field.value) end
            end
            if status and status.owned ~= true then
                return { can_mutate = false, management_support = "Unavailable",
                    reason = "Nightclub popularity actions require a positive owned-business signal and a readable popularity value." }
            end
            if popularity == nil then
                return { can_mutate = false, management_support = "Unavailable",
                    reason = "Nightclub popularity could not be read." }
            end
            if popularity < 0 or popularity > 1000 or popularity ~= math.floor(popularity) then
                return { can_mutate = false, management_support = "Unavailable",
                    reason = "Nightclub popularity is outside the supported 0-1000 range." }
            end
            return { popularity = popularity, can_mutate = true, management_support = "Experimental",
                recommended_action = "Use a guarded popularity action below, then confirm the value on the live Nightclub screen.",
                reason = "Popularity is readable on the 0-1000 scale. Actions affect only that named stat and remain live-test required." }
        end,
    },
    hangar = {
        version = "silent-night-pocket-dimension-live-v2-fast",
        mutation_validated = true,
        action_info = {},
        actions = {},
        refresh = function(_, _, status)
            local inventory = status and status.hangar_inventory
            if status and status.owned ~= true then
                return { can_mutate = false, management_support = "Unavailable",
                    reason = "A detected owned Hangar is required." }
            end
            if type(inventory) ~= "table" then
                return { can_mutate = false, management_support = "Unavailable",
                    reason = "The 50-slot Hangar inventory could not be read; local editing is unavailable." }
            end
            if tonumber(inventory.invalid) and tonumber(inventory.invalid) > 0 then
                return { can_mutate = false, management_support = "Unavailable",
                    reason = "Local editing is unavailable while the Hangar inventory contains an unknown cargo value." }
            end
            return {
                can_mutate = true,
                management_support = "Staff sourcing + local slot editor",
                recommended_action = "Use Fast Staff Sourcing for quicker cargo from paid Rooster orders. The local slot editor changes only the visible slot projection.",
                reason = ("Accepted cargo: %s. Local slots: %s. Local edits do not add accepted cargo; GTA reconciles slots to the accepted total.")
                    :format(tostring(status.stock or "unavailable"),tostring(inventory.occupied or "unavailable")),
            }
        end,
    },
}

local function packed_profile_adapter(version, profile, action_key, action_label, action_style,
    target_factory, support_reason)
    return {
        version = version,
        mutation_validated = true,
        action_info = {
            { key = action_key, label = action_label, style = action_style or "primary",
                reason = support_reason },
        },
        actions = {
            [action_key] = function(_, _, status)
                return packed_business_transaction(status, profile, target_factory(), action_label, action_key)
            end,
        },
        refresh = function(_, _, status)
            if not status or status.owned ~= true then
                return { can_mutate = false, management_support = "Unavailable",
                    reason = "A positive owned-business signal is required before packed-stat management." }
            end
            local values = {}
            for _, entry in ipairs(profile.entries or {}) do
                local value, err = read_packed_int(entry.index)
                if value == nil then
                    return { can_mutate = false, management_support = "Unavailable",
                        reason = tostring(err or entry.label .. " could not be read") .. "; zero writes are allowed." }
                end
                if value < profile.minimum or value > profile.maximum then
                    return { can_mutate = false, management_support = "Unavailable",
                        reason = ("%s returned %s outside the validated %d..%d scale; zero writes are allowed.")
                            :format(entry.label, tostring(value), profile.minimum, profile.maximum) }
                end
                values[entry.index] = value
                status.read_values["PACKED_" .. tostring(entry.index)] = value
                status.readouts[#status.readouts + 1] = {
                    key = "PACKED_" .. tostring(entry.index), label = entry.label,
                    value = value, display_value = value, suffix = "%",
                    confidence = "CURRENT_ENHANCED_SOURCE+ARCHIVE_CORROBORATED",
                }
            end
            return {
                can_mutate = true,
                management_support = "Source-verified packed stat",
                read_support = "Current Enhanced packed stats",
                packed_business_profile = {
                    key = profile.key, values = values, minimum = profile.minimum, maximum = profile.maximum,
                    evidence = profile.evidence, source_revision = profile.source_revision,
                },
                recommended_action = support_reason,
                reason = support_reason .. " Every changed value is reread immediately and prior values are restored if verification fails.",
            }
        end,
    }
end

