-- Register controls through their owning modules. Preloader launches already
-- have a startup presentation; direct loads use the runtime presentation below.
local preboot_handoff = __CSCRIPT_PREBOOT_HANDOFF == true
local function startup_visual_stage(progress, phase, detail, ready)
