    :format(VERSION, AUTHOR,
        VehicleApi.RegisteredCount() + UIApi.RegisteredCount() + ConfigApi.RegisteredCount()
            + WeaponsApi.RegisteredCount() + WorldApi.RegisteredCount() + PlayerApi.RegisteredCount()
            + SessionApi.RegisteredCount() + ProtectionsApi.RegisteredCount(),
        WeaponsApi.WeaponCount, VehicleApi.RegisteredCount(), UIApi.RegisteredCount(), ConfigApi.RegisteredCount(),
        WeaponsApi.RegisteredCount(), WorldApi.RegisteredCount(), PlayerApi.RegisteredCount(),
