]====],
    ["modules/economy_core.lua"] = [====[
-- CScript Economy Core.
-- Native and file operations are kept out of renderer paths. Every mutation
-- validates the character, writes a verified local snapshot, applies as one
-- logical transaction, verifies, and rolls back on failure.
local Module = { Name = "modules.economy_core", MigrationPhase = "17.75" }

local STAT_GET_INT = 0x767FBC2AC802EF3D
local STAT_SET_INT = 0xB3271D7AB655B441
Module.ProfileNative = {
    GET_FLOAT=0xD7AE6C9C9C6AC54C, SET_FLOAT=0x4851997F37FE9B3C,
    GET_DAYS=0xE0E854F5280FB769, GET_HOURS=0xF2D4B2FE415AAFC3, GET_MINUTES=0x7583B4BE4C5A41B5,
    SET_MENTAL=0xF1EEA2DDA9FFA69D,
}
Module.Profile = {}
local NETWORK_IS_SESSION_STARTED = 0x9DE624D2FC4B603F
local NETWORK_GET_VC_BANK_BALANCE = 0x76EF28DA05EA395A
local NETWORK_GET_VC_WALLET_BALANCE = 0xA40F9C2623F6A8B5
local HAS_ACHIEVEMENT_BEEN_PASSED = 0x867365E111A3B6EB
local GIVE_ACHIEVEMENT_TO_PLAYER = 0xBEC7076D64130195
local GET_ACHIEVEMENT_PROGRESS = 0x1C186837D0619335
local HAS_FINALIZED_CHOSEN_CRIMINAL_CAREER = 0xB233964AC562A357
local GET_CHOSEN_CRIMINAL_CAREER = 0xA0A0D77ECEDD4136
local GET_PACKED_STAT_BOOL_CODE = 0xDA7EBFC49AE3F1B0
local GET_PACKED_STAT_INT_CODE = 0x0BC900A6FE73770C
local SET_PACKED_STAT_BOOL_CODE = 0xDB8A58AEAA67CD07
local GET_STAT_HASH_FOR_CHARACTER_STAT = 0xD69CE161FE614531
local MAX_HISTORY, MAX_EARNINGS, MONEY_REFRESH_MS = 80, 4096, 1000
local MAX_ACTION_QUEUE = 8
local DAY_SECONDS, WEEK_SECONDS = 86400, 7 * 86400
local HISTORY_RETENTION_SECONDS = 30 * 86400
local DEFAULT_DAILY_CAUTION, DEFAULT_WEEKLY_CAUTION = 30000000, 150000000
local EARNINGS_HEADER = "CSCRIPT_EARNINGS_HISTORY_V3"
local ACCOUNT_SNAPSHOT_HEADER = "CSCRIPT_ACCOUNT_SNAPSHOT_V1"
local PERSISTENCE_RETRY_MS, PERSISTENCE_MAX_ATTEMPTS = 500, 5
local ACCOUNT_ID_RETRY_MS = 2000

local module_context
local public_api
local State
local started = false
local tick_registered = false
local cached_paths
local cached_file_api
local final_save_completed = false
local final_save_attempted = false
local emergency_save_attempted = false

local function now_ms()
    local raw=module_context and module_context.Raw
    local time=raw and raw.Time
    local invalid=false
    if time and type(time.GetEpocheMs)=="function" then
        local ok,value=pcall(time.GetEpocheMs)
        if ok and type(value)=="number" and value==value and value>=0 and value<math.huge and value%1==0 then
            Module.clock_valid=true;return value
        end
        invalid=true
    end
    local utils=raw and raw.Utils
    if utils and type(utils.GetTime)=="function" then
        local ok,value=pcall(utils.GetTime)
        if ok and type(value)=="number" and value==value and value>=0 and value<math.huge then
            Module.clock_valid=not invalid;return math.floor(value*1000)
        end
    end
    Module.clock_valid=false
    return math.floor((os and os.clock and os.clock() or 0)*1000)
end

local function epoch()
    return os and type(os.time) == "function" and os.time() or math.floor(now_ms() / 1000)
end

local function clean(value, maximum)
    return tostring(value or ""):gsub("[\r\n|]", " "):gsub("^%s+", ""):gsub("%s+$", ""):sub(1, maximum or 180)
end

local function resolve_local_account_identity()
    local players = module_context and module_context.Raw and module_context.Raw.Players
    if not players and type(_G) == "table" then players = rawget(_G, "Players") end
    if not (players and type(players.GetById) == "function") then
        return nil, nil, "Cherax Players.GetById is unavailable"
    end
    for player_id = 0, 31 do
        local ok_player, player = pcall(players.GetById, player_id)
        local ok_local_method, local_method = pcall(function() return player and player.IsLocalPlayer end)
        if ok_player and player and ok_local_method and type(local_method) == "function" then
            local ok_local, is_local = pcall(function() return player:IsLocalPlayer() end)
            if ok_local and is_local == true then
                local ok_info_method, info_method = pcall(function() return player.GetGamerInfo end)
                if not ok_info_method or type(info_method) ~= "function" then
                    return nil, nil, "the local player's Rockstar identity is unavailable"
                end
                local ok_info, info = pcall(function() return player:GetGamerInfo() end)
                local rockstar_id = ok_info and info and tonumber(info.RockstarId) or nil
                if not rockstar_id or rockstar_id <= 0 or rockstar_id ~= math.floor(rockstar_id) then
                    return nil, nil, "the local Rockstar ID is not ready"
                end
                local account_name = "Rockstar account " .. tostring(math.floor(rockstar_id))
                local ok_name_method, name_method = pcall(function() return player.GetName end)
                if ok_name_method and type(name_method) == "function" then
                    local ok_name, name = pcall(function() return player:GetName() end)
                    if ok_name and type(name) == "string" and clean(name, 80) ~= "" then
                        account_name = clean(name, 80)
                    end
                end
                return math.floor(rockstar_id), account_name, nil
            end
        end
    end
    return nil, nil, "the local Rockstar account is not present in the Cherax player list yet"
end

local function encode(value)
    return (tostring(value or ""):gsub("[%%|\r\n]", function(character)
        return ({ ["%"] = "%25", ["|"] = "%7C", ["\r"] = "%0D", ["\n"] = "%0A" })[character]
    end))
end

local function decode(value)
    return (tostring(value or ""):gsub("%%0A", "\n"):gsub("%%0D", "\r")
        :gsub("%%7C", "|"):gsub("%%25", "%%"))
end

local function fields(line)
    local result = {}
    for field in (tostring(line or "") .. "|"):gmatch("(.-)|") do result[#result + 1] = decode(field) end
    return result
end

local function notify(kind, message, duration)
    local notifications = module_context and module_context.Notifications
    local method = notifications and notifications[tostring(kind or "Info"):gsub("^%l", string.upper)]
    if type(method) == "function" then method(clean(message), duration or 5000); return end
    if module_context and module_context.Cherax then
        module_context.Cherax.Toast(clean(message), duration or 5000, "CScript Economy")
    end
end

local function log_info(message)
    if module_context and module_context.Logger then module_context.Logger.Info(message, "Economy") end
end

local function log_error(message)
    if module_context and module_context.Logger then module_context.Logger.Error(message, "Economy") end
end

local function cache_file_mgr(files)
    if files == nil then return nil end
    -- Capture the callable values, not merely the mutable host table. Cherax can
    -- clear globals/services while ON_UNLOAD callbacks are still unwinding.
    return {
        GetMenuRootPath = files.GetMenuRootPath,
        DoesFileExist = files.DoesFileExist,
        ReadFileContent = files.ReadFileContent,
        WriteFileContent = files.WriteFileContent,
        CreateDir = files.CreateDir,
        FindFiles = files.FindFiles,
    }
end

local function live_file_mgr()
    return module_context and module_context.Raw and module_context.Raw.FileMgr
end

local function file_mgr()
    return cached_file_api or live_file_mgr()
end

local function refresh_cached_file_api()
    local candidate = cache_file_mgr(live_file_mgr())
    if not candidate or type(candidate.DoesFileExist) ~= "function"
        or type(candidate.ReadFileContent) ~= "function"
        or type(candidate.WriteFileContent) ~= "function"
        or type(candidate.CreateDir) ~= "function" then
        return false, "required FileMgr persistence APIs are unavailable"
    end
    cached_file_api = candidate
    return true
end

local function active_paths()
    return cached_paths or (State and State.paths)
end

local function ensure_directory(path)
    local files = file_mgr()
    if not files or type(files.CreateDir) ~= "function" then return false, "FileMgr.CreateDir is unavailable" end
    local ok, result = pcall(files.CreateDir, path)
    -- Cherax v5.48.1 returns false when the directory already exists. The
    -- binding's boolean is therefore not a reliable success signal; only a
    -- thrown host error means the readiness probe failed. Subsequent explicit
    -- existence/read/write operations still verify every required file.
    if not ok then return false, clean(result or "directory creation failed") end
    return true
end

local function canonical_text(content)
    if type(content) ~= "string" then return nil end
    if content:sub(1, 3) == "\239\187\191" then content = content:sub(4) end
    return content:gsub("\r\n", "\n"):gsub("\r", "\n")
end

local function file_exists(path)
    local files = file_mgr()
    if not files or type(files.DoesFileExist) ~= "function" then
        return nil, "FileMgr.DoesFileExist is unavailable"
    end
    local ok, exists = pcall(files.DoesFileExist, path)
    if not ok then return nil, "existence check failed: " .. clean(exists) end
    return exists == true
end

local function build_storage_paths(root, account_id)
    if type(root) ~= "string" or root == "" then return nil end
    account_id = tonumber(account_id)
    if not account_id or account_id <= 0 or account_id ~= math.floor(account_id) then return nil end
    account_id = math.floor(account_id)
    root = root:gsub("/+$", ""):gsub("\\+$", "")
    local economy = root .. "\\Lua\\CScriptData\\Economy"
    local old_economy = root .. "\\Lua\\CScript\\Economy"
    local data_root = root .. "\\Lua\\CScriptData"
    local snapshots = economy .. "\\HeistSnapshots"
    local earnings = economy .. "\\Earnings"
    local earnings_accounts = earnings .. "\\Accounts"
    local account_earnings = earnings_accounts .. "\\" .. tostring(account_id)
    return {
        account_id = account_id,
        root = economy,
        data_root = data_root,
        snapshots = snapshots,
        account_snapshots = economy .. "\\AccountSnapshots",
        earnings_root = earnings,
        earnings_accounts = earnings_accounts,
        account_earnings_root = account_earnings,
        history = economy .. "\\action_history.txt",
        earnings = account_earnings .. "\\history_v3.txt",
        earnings_backup = account_earnings .. "\\history_v3.txt.bak",
        earnings_backup_pending = account_earnings .. "\\history_v3.txt.bak.pending",
        earnings_emergency_legacy = account_earnings .. "\\history_v3.emergency.bak",
        earnings_emergency_prefix = account_earnings .. "\\history_v3.emergency-",
        legacy_shared_earnings = earnings .. "\\history_v2.txt",
        legacy_shared_earnings_backup = earnings .. "\\history_v2.txt.bak",
        legacy_earnings = economy .. "\\earnings_history.txt",
        settings = economy .. "\\settings.txt",
        old = {
            root = old_economy,
            snapshots = old_economy .. "\\HeistSnapshots",
            history = old_economy .. "\\action_history.txt",
            earnings = old_economy .. "\\Earnings\\history_v2.txt",
            earnings_backup = old_economy .. "\\Earnings\\history_v2.txt.bak",
            legacy_earnings = old_economy .. "\\earnings_history.txt",
            settings = old_economy .. "\\settings.txt",
        },
    }
end

local function menu_root_from_runtime()
    local runtime_root = module_context and module_context.Root
    if type(runtime_root) ~= "string" or runtime_root == "" then return nil end
    runtime_root = runtime_root:gsub("/", "\\"):gsub("\\+$", "")
    local lower = runtime_root:lower()
    if lower:sub(-12) == "\\lua\\cscript" then return runtime_root:sub(1, -13) end
    return nil
end

local function storage_paths(account_id)
    account_id = tonumber(account_id or (State and State.account_id))
    if not account_id or account_id <= 0 or account_id ~= math.floor(account_id) then
        return nil, "a verified local Rockstar ID is required for earnings storage"
    end
    account_id = math.floor(account_id)
    if cached_paths and tonumber(cached_paths.account_id) == account_id then return cached_paths end
    local files = file_mgr()
    local root
    if files and type(files.GetMenuRootPath) == "function" then
        local root_ok, resolved = pcall(files.GetMenuRootPath)
        if root_ok and type(resolved) == "string" and resolved ~= "" then root = resolved end
    end
    if not root then root = menu_root_from_runtime() end
    if not root then
        return nil, "Cherax menu root and FileMgr.GetMenuRootPath are unavailable"
    end
    local paths = build_storage_paths(root, account_id)
    if not paths then return nil, "Cherax menu root is unavailable" end
    -- The absolute paths are immutable module-owned unload state. State.paths is
    -- presentation/diagnostic state and must not be the final-save dependency.
    local ok, err = ensure_directory(paths.data_root)
    if not ok then return nil, err end
    ok, err = ensure_directory(paths.root)
    if not ok then return nil, err end
    ok, err = ensure_directory(paths.snapshots)
    if not ok then return nil, err end
    ok, err = ensure_directory(paths.account_snapshots)
    if not ok then return nil, err end
    ok, err = ensure_directory(paths.earnings_root)
    if not ok then return nil, err end
    ok, err = ensure_directory(paths.earnings_accounts)
    if not ok then return nil, err end
    ok, err = ensure_directory(paths.account_earnings_root)
    if not ok then return nil, err end
    cached_paths = paths
    return cached_paths
end

local function read_file(path)
    local files = file_mgr()
    if not files or type(files.DoesFileExist) ~= "function" or type(files.ReadFileContent) ~= "function" then
        return nil, "FileMgr read APIs are unavailable"
    end
    local exists, exists_err = file_exists(path)
    if exists == nil then return nil, exists_err end
    if not exists then return nil, "file does not exist" end
    local ok, content = pcall(files.ReadFileContent, path)
    if not ok or type(content) ~= "string" then return nil, clean(content or "read failed") end
    return content
end

local function write_file(path, content)
    local files = file_mgr()
    if not files or type(files.WriteFileContent) ~= "function" then
        return false, "FileMgr.WriteFileContent is unavailable"
    end
    local ok, result = pcall(files.WriteFileContent, path, tostring(content), false)
    if not ok or result == false then return false, clean(result or "write rejected") end
    local verify, err = read_file(path)
    if type(verify) ~= "string" then return false, "post-write read failed: " .. tostring(err) end
    if canonical_text(verify) ~= canonical_text(tostring(content)) then
        return false, "post-write verification failed: canonical content mismatch"
    end
    return true, #verify
end

local function timestamp_id()
    if os and type(os.date) == "function" then
        local ok, label = pcall(os.date, "%Y%m%d-%H%M%S")
        if ok and label then return label .. "-" .. tostring(now_ms() % 1000) end
    end
    return tostring(epoch()) .. "-" .. tostring(now_ms() % 1000)
end

local function trim(values, maximum)
    while #values > maximum do table.remove(values, 1) end
end

local function serialize_history(header, values)
    local lines = { header }
    for _, item in ipairs(values or {}) do
        lines[#lines + 1] = table.concat({
            encode(item.time), encode(item.kind), encode(item.label), encode(item.detail), encode(item.amount or "")
        }, "|")
    end
    return table.concat(lines, "\n")
end

local function parse_history(content, header)
    content = canonical_text(content)
    if type(content) ~= "string" or content:match("^([^\n]+)") ~= header then return {} end
    local result, first = {}, true
    for line in content:gmatch("[^\n]+") do
        if first then first = false else
            local item = fields(line)
            result[#result + 1] = {
                time = tonumber(item[1]) or 0, kind = item[2] or "info",
                label = item[3] or "Economy action", detail = item[4] or "",
                amount = tonumber(item[5]),
            }
        end
    end
    return result
end

local function source_bucket(source)
    source = clean(source or "Unknown", 80)
    local lower = source:lower()
    if lower == "heist" or lower == "heists" or lower:find("cayo", 1, true) then return "Heists" end
    if lower == "business" or lower == "businesses" then return "Businesses" end
    if lower == "mission" or lower == "missions" or lower == "job" or lower == "jobs" then return "Missions" end
    if lower == "safe" or lower == "safes" then return "Safes" end
    if lower == "other" or lower == "other / unknown" then return "Other / Unknown" end
    return "Unknown"
end

Module.Journal = { MAX_EPOCH = 1000000, MAX_COUNTER = 9007199254740991,
    ambiguity_message = "Some backup history could not be matched safely. Original backups were preserved." }

function Module.Journal.ValidInteger(value, maximum)
    return type(value) == "number" and value == value and value >= 0
        and value <= maximum and value == math.floor(value)
end

function Module.Journal.Epoch(lifetime, slot)
    return type(lifetime) == "table" and type(lifetime.journal_epochs) == "table"
        and lifetime.journal_epochs[slot] or 0
end

function Module.Journal.StampEvent(event)
    if event.journal_id then return end
    Module.Journal.nonce = Module.Journal.nonce or
        (timestamp_id() .. "-" .. tostring({}):gsub("[^%w]", ""))
    Module.Journal.sequence = (Module.Journal.sequence or 0) + 1
    event.journal_id = tostring(State.account_id) .. ":" .. tostring(event.character_slot)
        .. ":" .. Module.Journal.nonce .. ":" .. tostring(Module.Journal.sequence)
    event.journal_epoch = Module.Journal.Epoch(State.lifetime_by_slot, event.character_slot)
end

local function serialize_earnings()
    local account_id = tonumber(State.account_id)
    if not account_id or account_id <= 0 or account_id ~= math.floor(account_id) then
        error("cannot serialize earnings without a verified Rockstar account ID", 2)
    end
    local lines = { EARNINGS_HEADER, "account|" .. tostring(math.floor(account_id)) }
    for slot = 0, 1 do
        lines[#lines + 1] = table.concat({ "lifetime", tostring(slot),
            tostring(math.max(0, math.floor(tonumber(State.lifetime_by_slot[slot]) or 0))),
            tostring(Module.Journal.Epoch(State.lifetime_by_slot, slot)) }, "|")
    end
    for _, item in ipairs(State.earnings or {}) do
        lines[#lines + 1] = table.concat({
            "event", encode(item.time), encode(item.amount), encode(item.source), encode(item.confidence),
            encode(item.cash_delta), encode(item.bank_delta), encode(item.character_slot), encode(item.session_id),
            encode(item.detail), encode(item.journal_id), encode(item.journal_epoch or 0)
        }, "|")
    end
    return table.concat(lines, "\n")
end

local function parse_earnings(content, expected_account_id)
    local result, lifetime = {}, { [0] = 0, [1] = 0, journal_epochs = { [0] = 0, [1] = 0 } }
    expected_account_id = tonumber(expected_account_id)
    content = canonical_text(content)
    if type(content) ~= "string" then return result, lifetime, false, "journal is unreadable" end
    if content:match("^([^\n]+)") ~= EARNINGS_HEADER then
        return result, lifetime, false, "journal header is invalid"
    end
    local first, lifetime_seen, account_seen, record_index = true, {}, false, 0
    for line in content:gmatch("[^\n]+") do
        if first then first = false else
            record_index = record_index + 1
            local item = fields(line)
            if item[1] == "account" then
                local account_id = tonumber(item[2])
                if record_index ~= 1 or account_seen or not account_id or account_id <= 0
                    or account_id ~= math.floor(account_id) then
                    return {}, { [0] = 0, [1] = 0 }, false, "journal contains an invalid account record"
                end
                if expected_account_id and math.floor(account_id) ~= math.floor(expected_account_id) then
                    return {}, { [0] = 0, [1] = 0 }, false, "journal Rockstar account ID does not match the active account"
                end
                account_seen = true
            elseif item[1] == "lifetime" then
                if not account_seen then
                    return {}, { [0] = 0, [1] = 0 }, false, "journal account record must precede data"
                end
                local slot, amount = tonumber(item[2]), tonumber(item[3])
                local reset_epoch = 0
                if item[4] and item[4] ~= "" then reset_epoch = tonumber(item[4]) end
                if (slot ~= 0 and slot ~= 1)
                    or not Module.Journal.ValidInteger(amount, Module.Journal.MAX_COUNTER)
                    or not Module.Journal.ValidInteger(reset_epoch, Module.Journal.MAX_EPOCH) then
                    return {}, { [0] = 0, [1] = 0 }, false, "journal contains an invalid lifetime record"
                end
                if lifetime_seen[slot] then
                    return {}, { [0] = 0, [1] = 0 }, false, "journal contains a duplicate lifetime record"
                end
                lifetime_seen[slot], lifetime[slot] = true, math.floor(amount)
                lifetime.journal_epochs[slot] = reset_epoch
            elseif item[1] == "event" then
                if not account_seen then
                    return {}, { [0] = 0, [1] = 0 }, false, "journal account record must precede data"
                end
                local timestamp, amount, slot = tonumber(item[2]), tonumber(item[3]), tonumber(item[8])
                local cash_delta, bank_delta = tonumber(item[6]), tonumber(item[7])
                local confidence = item[5]
                local journal_id = item[11] and item[11] ~= "" and item[11] or nil
                local reset_epoch = 0
                if item[12] and item[12] ~= "" then reset_epoch = tonumber(item[12]) end
                if not Module.Journal.ValidInteger(timestamp, Module.Journal.MAX_COUNTER) or timestamp <= 0
                    or not Module.Journal.ValidInteger(amount, Module.Journal.MAX_COUNTER) or amount <= 0
                    or (slot ~= 0 and slot ~= 1 and slot ~= -1)
                    or (confidence ~= "verified" and confidence ~= "legacy")
                    or (slot == -1 and confidence ~= "legacy")
                    or not cash_delta or not Module.Journal.ValidInteger(math.abs(cash_delta), Module.Journal.MAX_COUNTER)
                    or not bank_delta or not Module.Journal.ValidInteger(math.abs(bank_delta), Module.Journal.MAX_COUNTER)
                    or not Module.Journal.ValidInteger(reset_epoch, Module.Journal.MAX_EPOCH)
                    or (journal_id and (#journal_id > 180 or journal_id:find("[^%w:_%-]")))
                    or clean(item[4], 80) == "" then
                    return {}, { [0] = 0, [1] = 0 }, false, "journal contains an invalid earnings event"
                end
                result[#result + 1] = {
                    time = math.floor(timestamp), amount = math.floor(amount), source = clean(item[4], 80),
                    confidence = confidence, cash_delta = math.floor(cash_delta), bank_delta = math.floor(bank_delta),
                    character_slot = slot, session_id = clean(item[9], 80),
                    detail = item[10] and item[10] ~= "" and item[10]:sub(1, 180) or nil,
                    journal_id = journal_id, journal_epoch = reset_epoch,
                }
            else
                return {}, { [0] = 0, [1] = 0 }, false, "journal contains an unknown record type"
            end
        end
    end
    if not account_seen then
        return {}, { [0] = 0, [1] = 0 }, false, "journal account record is missing"
    end
    if not lifetime_seen[0] or not lifetime_seen[1] then
        return {}, { [0] = 0, [1] = 0 }, false, "journal lifetime records are incomplete"
    end
    local ids = {}
    for _, event in ipairs(result) do
        if event.character_slot ~= -1
            and event.journal_epoch ~= lifetime.journal_epochs[event.character_slot] then
            return {}, { [0] = 0, [1] = 0 }, false, "journal event reset generation does not match its character"
        end
        if event.journal_id then
            if ids[event.journal_id] then
                return {}, { [0] = 0, [1] = 0 }, false, "journal contains a duplicate event identity"
            end
            ids[event.journal_id] = true
        end
    end
    return result, lifetime, true, nil
end


local Dirty = {}

function Dirty.Sync()
    State.persistence_dirty = State.history_dirty == true or State.earnings_dirty == true
    return State.persistence_dirty
end

function Dirty.History()
    State.history_dirty = true
    Dirty.Sync()
end

function Dirty.Earnings()
    State.earnings_dirty = true
    Dirty.Sync()
end

local function prune_earnings(current)
    current = tonumber(current) or epoch()
    local before_count = #(State.earnings or {})
    local retained = {}
    for _, item in ipairs(State.earnings or {}) do
        local timestamp = tonumber(item.time) or 0
        if timestamp > current - HISTORY_RETENTION_SECONDS then retained[#retained + 1] = item end
    end
    if #retained > MAX_EARNINGS then
        local positions = {}
        for index = 1, #retained do positions[index] = index end
        table.sort(positions, function(left, right)
            local a, b = retained[left], retained[right]
            local a_time, b_time = tonumber(a.time) or 0, tonumber(b.time) or 0
            local a_rank = a_time <= current and (a.confidence == "verified" and 2 or 1) or 0
            local b_rank = b_time <= current and (b.confidence == "verified" and 2 or 1) or 0
            if a_rank ~= b_rank then return a_rank > b_rank end
            if a_time ~= b_time then return a_time > b_time end
            return left > right
        end)
        local keep, selected = {}, {}
        for index = 1, MAX_EARNINGS do keep[positions[index]] = true end
        -- Select by recency, but keep ledger order and the newest event last.
        for index, item in ipairs(retained) do
            if keep[index] then selected[#selected + 1] = item end
        end
        retained = selected
    end
    State.earnings = retained
    local changed = #retained ~= before_count
    if changed then Dirty.Earnings() end
    return changed
end

local function set_persistence_failure(status, stage, message, block_writes)
    State.persistence_status = status
    State.persistence_stage = stage
    State.persistence_error = clean(message or "unknown persistence failure", 220)
    if block_writes == true then State.persistence_write_blocked = true end
    log_error(("Persistence %s stage=%s path=%s error=%s"):format(
        tostring(status), tostring(stage), tostring(active_paths() and active_paths().earnings or "Unavailable"),
        tostring(State.persistence_error)))
end

local function event_matches(left, right)
    return type(left) == "table" and type(right) == "table"
        and tonumber(left.time) == tonumber(right.time)
        and tonumber(left.amount) == tonumber(right.amount)
        and tostring(left.source) == tostring(right.source)
        and tostring(left.confidence) == tostring(right.confidence)
        and tonumber(left.cash_delta) == tonumber(right.cash_delta)
        and tonumber(left.bank_delta) == tonumber(right.bank_delta)
        and tonumber(left.character_slot) == tonumber(right.character_slot)
        and tostring(left.session_id) == tostring(right.session_id)
end

function Module.Journal.Fingerprint(item)
    if type(item) ~= "table" then return "" end
    return table.concat({
        tostring(math.floor(tonumber(item.time) or 0)),
        tostring(math.floor(tonumber(item.amount) or 0)),
        tostring(item.confidence or ""),
        tostring(math.floor(tonumber(item.cash_delta) or 0)),
        tostring(math.floor(tonumber(item.bank_delta) or 0)),
        tostring(math.floor(tonumber(item.character_slot) or -1)),
        tostring(item.session_id or ""),
        tostring(item.journal_epoch or 0),
    }, "|")
end

local function emergency_paths(paths)
    local result, seen = {}, {}
    local function add(path)
        path = tostring(path or "")
        if path ~= "" and not seen[path] then seen[path], result[#result + 1] = true, path end
    end
    if file_exists(paths.earnings_emergency_legacy) == true then add(paths.earnings_emergency_legacy) end
    local files = file_mgr()
    if files and type(files.FindFiles) == "function" then
        local ok, found = pcall(files.FindFiles, paths.account_earnings_root, ".bak", false)
        if ok and type(found) == "table" then
            for _, raw_path in pairs(found) do
                local path = tostring(raw_path or "")
                local name = path:match("[^\\/]+$") or path
                if name:match("^history_v3%.emergency%-.+%.bak$") then
                    if not path:find("[\\/]", 1) then path = paths.account_earnings_root .. "\\" .. path end
                    add(path)
                end
            end
        end
    end
    table.sort(result)
    return result
end

local function merge_emergency_snapshots(paths, base_events, base_lifetime)
    Module.Journal.recovery_ambiguous = false
    local snapshots = { { events = base_events or {}, lifetime = base_lifetime or { [0] = 0, [1] = 0 } } }
    local valid_count = 0
    for _, path in ipairs(emergency_paths(paths)) do
        local content = read_file(path)
        local snapshot_events, snapshot_lifetime, valid = parse_earnings(content, paths.account_id)
        if valid then
            valid_count = valid_count + 1
            snapshots[#snapshots + 1] = { events = snapshot_events, lifetime = snapshot_lifetime }
        end
    end
    local known_ids = {}
    for _, snapshot in ipairs(snapshots) do
        snapshot.blocked = {}
        for _, event in ipairs(snapshot.events) do
            local fingerprint = Module.Journal.Fingerprint(event)
            if event.journal_id and known_ids[event.journal_id]
                and known_ids[event.journal_id] ~= fingerprint then
                snapshot.blocked[event.character_slot] = true
                Module.Journal.recovery_ambiguous = true
            end
        end
        for _, event in ipairs(snapshot.events) do
            if event.journal_id and not snapshot.blocked[event.character_slot] then
                known_ids[event.journal_id] = Module.Journal.Fingerprint(event)
            end
        end
    end
    local events, lifetime = {}, { [0] = 0, [1] = 0, journal_epochs = { [0] = 0, [1] = 0 } }
    for slot = 0, 1 do
        for _, snapshot in ipairs(snapshots) do
            if not snapshot.blocked[slot] then
                lifetime.journal_epochs[slot] = math.max(lifetime.journal_epochs[slot],
                    Module.Journal.Epoch(snapshot.lifetime, slot))
            end
        end
        for _, snapshot in ipairs(snapshots) do
            if not snapshot.blocked[slot]
                and Module.Journal.Epoch(snapshot.lifetime, slot) == lifetime.journal_epochs[slot] then
                -- Snapshots contain cumulative counters, including pruned rows.
                lifetime[slot] = math.max(lifetime[slot], tonumber(snapshot.lifetime[slot]) or 0)
            end
        end
    end
    local counts, ids, unidentified, retained, merged = {}, {}, {}, { [0] = 0, [1] = 0 }, 0
    for snapshot_index, snapshot in ipairs(snapshots) do
        local occurrences = {}
        for _, event in ipairs(snapshot.events) do
            local slot = event.character_slot
            if not snapshot.blocked[slot] and (slot == -1
                or (Module.Journal.Epoch(snapshot.lifetime, slot) == lifetime.journal_epochs[slot]
                and (event.journal_epoch or 0) == lifetime.journal_epochs[slot])) then
                local identity = Module.Journal.Fingerprint(event)
                occurrences[identity] = (occurrences[identity] or 0) + 1
                local append = snapshot_index == 1
                if not append and event.journal_id and not ids[event.journal_id] then
                    if (unidentified[identity] or 0) > 0 then
                        -- An old reader may have omitted the trailing ID. Preserve
                        -- the existing row without guessing a replacement label.
                        unidentified[identity] = unidentified[identity] - 1
                        ids[event.journal_id] = true
                    else append = true end
                elseif not append and not event.journal_id
                    and occurrences[identity] > (counts[identity] or 0) then
                    if slot == -1 or (retained[slot] or 0) + event.amount <= lifetime[slot] then
                        append = true
                    else Module.Journal.recovery_ambiguous = true end
                end
                if append then
                    events[#events + 1] = event
                    counts[identity] = (counts[identity] or 0) + 1
                    if event.journal_id then ids[event.journal_id] = true
                    else unidentified[identity] = (unidentified[identity] or 0) + 1 end
                    if slot == 0 or slot == 1 then
                        retained[slot] = retained[slot] + event.amount
                        if event.journal_id then lifetime[slot] = math.max(lifetime[slot], retained[slot]) end
                    end
                    if snapshot_index > 1 then merged = merged + 1 end
                end
            end
        end
    end
    for slot = 0, 1 do
        if retained[slot] > lifetime[slot] then Module.Journal.recovery_ambiguous = true end
    end
    for slot = 0, 1 do
        if lifetime[slot] ~= tonumber(base_lifetime and base_lifetime[slot] or 0)
            or lifetime.journal_epochs[slot] ~= Module.Journal.Epoch(base_lifetime, slot) then
            merged = math.max(1, merged)
        end
    end
    return events, lifetime, merged, valid_count
end

local function commit_earnings(reason, required_event, allow_known_scope)
    if State.earnings_dirty ~= true and required_event == nil then
        return true, "UNCHANGED"
    end
    local paths = active_paths()
    if not paths then return false, "Economy persistence path is unavailable" end
    if tonumber(State.account_id) ~= tonumber(paths.account_id)
        or (allow_known_scope ~= true and State.account_verified ~= true) then
        return false, "earnings writes are paused until the active Rockstar account is verified"
    end
    if State.persistence_write_blocked then
        return false, State.persistence_error or "journal writes are blocked until the persistence error is repaired"
    end
    local path, backup = paths.earnings, paths.earnings_backup
    local exists, exists_err = file_exists(path)
    if exists == nil then
        set_persistence_failure("READ_ERROR", "EXISTS", exists_err, true)
        return false, exists_err
    end
    if exists then
        local previous, read_err = read_file(path)
        if type(previous) ~= "string" then
            set_persistence_failure("READ_ERROR", "BACKUP_SOURCE", read_err, true)
            return false, read_err
        end
        local _, _, valid, parse_err = parse_earnings(previous, paths.account_id)
        if not valid then
            set_persistence_failure("INVALID_JOURNAL", "BACKUP_SOURCE", parse_err, true)
            return false, parse_err
        end
        local pending = paths.earnings_backup_pending
        local pending_ok, pending_err = write_file(pending, previous)
        if not pending_ok then
            local status = tostring(pending_err):find("post%-write") and "VERIFY_ERROR" or "WRITE_ERROR"
            set_persistence_failure(status, "BACKUP_PENDING", pending_err, false)
            return false, pending_err
        end
        local pending_content, pending_read_err = read_file(pending)
        local _, _, pending_valid, pending_parse_err = parse_earnings(pending_content, paths.account_id)
        if not pending_valid then
            local failure = pending_read_err or pending_parse_err or "pending backup validation failed"
            set_persistence_failure("VERIFY_ERROR", "BACKUP_PENDING", failure, false)
            return false, failure
        end
        local backup_ok, backup_err = write_file(backup, pending_content)
        if not backup_ok then
            local status = tostring(backup_err):find("post%-write") and "VERIFY_ERROR" or "WRITE_ERROR"
            set_persistence_failure(status, "BACKUP", backup_err, false)
            return false, backup_err
        end
        local backup_content, backup_read_err = read_file(backup)
        local _, _, backup_valid, backup_parse_err = parse_earnings(backup_content, paths.account_id)
        if not backup_valid then
            local failure = backup_read_err or backup_parse_err or "backup validation failed"
            set_persistence_failure("VERIFY_ERROR", "BACKUP", failure, false)
            return false, failure
        end
    end

    local payload = serialize_earnings()
    local write_ok, write_detail = write_file(path, payload)
    if not write_ok then
        local status = tostring(write_detail):find("post%-write") and "VERIFY_ERROR" or "WRITE_ERROR"
        set_persistence_failure(status, "JOURNAL", write_detail, false)
        return false, write_detail
    end
    local reread, read_err = read_file(path)
    local events, lifetime, valid, parse_err = parse_earnings(reread, paths.account_id)
    if not valid then
        local failure = read_err or parse_err or "journal parse verification failed"
        set_persistence_failure("VERIFY_ERROR", "JOURNAL", failure, false)
        return false, failure
    end
    if required_event then
        local found = false
        for _, item in ipairs(events) do
            if event_matches(item, required_event) then found = true; break end
        end
        if not found then
            local failure = "committed earning was not present after independent reread"
            set_persistence_failure("VERIFY_ERROR", "EVENT", failure, false)
            return false, failure
        end
    end
    for slot = 0, 1 do
        if tonumber(lifetime[slot]) ~= tonumber(State.lifetime_by_slot[slot])
            or Module.Journal.Epoch(lifetime, slot) ~= Module.Journal.Epoch(State.lifetime_by_slot, slot) then
            local failure = "lifetime total did not match after independent reread"
            set_persistence_failure("VERIFY_ERROR", "LIFETIME", failure, false)
            return false, failure
        end
    end
    State.persistence_status = Module.Journal.recovery_ambiguous and "DEGRADED" or "READY"
    State.persistence_stage = "COMMIT"
    State.persistence_error = Module.Journal.recovery_ambiguous and Module.Journal.ambiguity_message or nil
    State.earnings_dirty = false
    Dirty.Sync()
    log_info(("Earnings commit reason=%s amount=%d path=%s events=%d bytes=%d status=READY"):format(
        clean(reason or "save", 40), required_event and tonumber(required_event.amount) or 0,
        path, #events, tonumber(write_detail) or #tostring(reread or "")))
    return true
end

local function save_histories(allow_known_scope)
    local paths = active_paths()
    if not paths then return false, "Economy persistence path is unavailable" end
    prune_earnings(epoch())
    local history_ok, history_err = true, nil
    if State.history_dirty == true then
        history_ok, history_err = write_file(paths.history,
            serialize_history("CSCRIPT_ECONOMY_HISTORY_V1", State.history))
        if history_ok then State.history_dirty = false end
    end
    local earnings_ok, earnings_err = true, nil
    if State.earnings_dirty == true then
        earnings_ok, earnings_err = commit_earnings("save", nil, allow_known_scope == true)
    end
    if not history_ok then
        set_persistence_failure("WRITE_ERROR", "ACTION_HISTORY", history_err, false)
    end
    Dirty.Sync()
    return history_ok and earnings_ok, history_err or earnings_err
end

local function emergency_save_earnings(primary_error)
    if emergency_save_attempted then return false, "emergency backup was already attempted" end
    if State.earnings_dirty ~= true then return false, "earnings journal is unchanged" end
    emergency_save_attempted = true
    local paths = active_paths()
    local files = cached_file_api
    if not paths then
        return false, "cached emergency journal path is unavailable"
    end
    if State.account_verified ~= true or tonumber(State.account_id) ~= tonumber(paths.account_id) then
        return false, "emergency journal write skipped because the active Rockstar account is not verified"
    end
    if State.persistence_authoritative ~= true and tonumber(State.verified_events_since_start or 0) <= 0 then
        return false, "PRE_STOP skipped untrusted persistence state"
    end
    if #(State.earnings or {}) == 0 and (tonumber(State.lifetime_by_slot[0]) or 0) == 0
        and (tonumber(State.lifetime_by_slot[1]) or 0) == 0 then
        return false, "empty persistence state is not eligible for an emergency snapshot"
    end
    local emergency_path = paths.earnings_emergency_prefix .. timestamp_id() .. ".bak"
    if not files or type(files.WriteFileContent) ~= "function" then
        return false, "cached FileMgr.WriteFileContent is unavailable"
    end
    local payload = serialize_earnings()
    local write_ok, write_result = pcall(files.WriteFileContent, emergency_path, payload, false)
    if not write_ok or write_result == false then
        return false, "emergency backup write rejected: " .. clean(write_result or primary_error or "unknown failure", 160)
    end
    if type(files.ReadFileContent) ~= "function" then
        return false, "emergency backup written but cached read verification is unavailable"
    end
    local read_ok, content = pcall(files.ReadFileContent, emergency_path)
    if not read_ok or canonical_text(content) ~= canonical_text(payload) then
        return false, "emergency backup did not match after independent reread"
    end
    local events, lifetime, valid, parse_err = parse_earnings(read_ok and content or nil, paths.account_id)
    if not valid then
        return false, "emergency backup verification failed: " .. clean(parse_err or content, 160)
    end
    if #events ~= #(State.earnings or {}) then
        return false, "emergency backup event count did not match"
    end
    for slot = 0, 1 do
        if tonumber(lifetime[slot]) ~= tonumber(State.lifetime_by_slot[slot])
            or Module.Journal.Epoch(lifetime, slot) ~= Module.Journal.Epoch(State.lifetime_by_slot, slot) then
            return false, "emergency backup lifetime total did not match"
        end
    end
    State.persistence_status, State.persistence_stage = "DEGRADED", "EMERGENCY_BACKUP"
    State.persistence_error = Module.Journal.recovery_ambiguous and Module.Journal.ambiguity_message or nil
    State.earnings_dirty = false
    Dirty.Sync()
    return true, emergency_path
end

local function final_save(reason)
    if final_save_completed then return true end
    if final_save_attempted then return false, "Economy final save was already attempted" end
    final_save_attempted = true
    if not State then return false, "Economy state is unavailable" end
    State.in_flight = nil
    local paths = active_paths()
    if paths and State.paths ~= paths then State.paths = paths end
    if State.persistence_authoritative ~= true or State.persistence_loaded ~= true then
        final_save_completed = true
        State.persistence_status = State.persistence_status == "PENDING" and "DEGRADED_READONLY"
            or State.persistence_status
        State.persistence_stage = "PRE_STOP_SKIPPED"
        local detail = "PRE_STOP skipped untrusted persistence state"
        State.persistence_error = State.persistence_error or detail
        log_info(("Persistence final-save reason=%s path=%s events=%d dirty=%s status=%s detail=%s"):format(
            clean(reason or "stop", 40), tostring(paths and paths.earnings or "Unavailable"),
            #(State.earnings or {}), tostring(State.persistence_dirty == true),
            tostring(State.persistence_status), detail))
        return false, detail
    end
    if not Dirty.Sync() then
        final_save_completed = true
        log_info(("Persistence final-save reason=%s path=%s events=%d dirty=false status=%s action=unchanged"):format(
            clean(reason or "stop", 40), tostring(paths and paths.earnings or "Unavailable"),
            #(State.earnings or {}), tostring(State.persistence_status)))
        return true
    end
    local ok, err = save_histories()
    local emergency_ok, emergency_detail = false, nil
    if not ok and State.earnings_dirty == true then
        emergency_ok, emergency_detail = emergency_save_earnings(err)
    end
    local succeeded = ok or emergency_ok
    final_save_completed = succeeded
    local path = paths and paths.earnings or "Unavailable"
    if not succeeded and paths then
        State.persistence_status, State.persistence_stage = "DEGRADED", "FINAL_SAVE"
        State.persistence_error = clean(emergency_detail or err or "final save failed", 220)
        log_error(("Persistence final-save failed path=%s error=%s"):format(path, State.persistence_error))
    end
    log_info(("Persistence final-save reason=%s path=%s events=%d dirty=%s status=%s%s"):format(
        clean(reason or "stop", 40), tostring(path), #(State.earnings or {}),
        tostring(State.persistence_dirty == true), tostring(State.persistence_status),
        ok and "" or (emergency_ok and (" emergency=" .. tostring(emergency_detail))
            or (" error=" .. clean(emergency_detail or err, 160)))))
    return succeeded, succeeded and nil or (emergency_detail or err)
end

local function add_history(kind, label, detail, amount)
    State.history[#State.history + 1] = {
        time = epoch(), kind = clean(kind, 24), label = clean(label, 80),
        detail = clean(detail, 180), amount = tonumber(amount),
    }
    trim(State.history, MAX_HISTORY)
    Dirty.History()
end

local function native_try(kind, hash, ...)
    if not module_context or not module_context.Natives then return false, "native bridge unavailable" end
    return module_context.Natives.Try(kind, hash, ...)
end

