        [883337077] = {"Missions", "Taxi work"},
        [-1077156170] = {"Missions", "Daily objective"},
        [-990286235] = {"Missions", "Bounty collected"},
    }
    local offsets = {0, 1, 2, 3, 5, 6, 7, 8, 9, 11}
    local state = {scope = nil, rows = nil, row_seeds = {}, last_now = nil,
        last_attempt = nil, serial = 0}
    local stats = {polls = 0, samples = 0, reads = 0, emitted = 0, seeded = 0,
        errors = 0, torn = 0, invalid_scope = 0, throttled = 0, resets = 0,
        scope_changes = 0, clock_resets = 0, zero_resets = 0, status = 'Unseeded'}
    local api = {}

    local function integer(value)
        return type(value) == 'number' and value == value and value % 1 == 0
    end

    local function clear_baseline(reason)
        state.rows, state.row_seeds = nil, {}
        stats.status = reason
    end

    local function same_row(a, b, count)
        for i = 1, count do
            if a[i] ~= b[i] then return false end
        end
        return true
    end

    local function zero_row(row)
        for i = 1, 10 do
            if row[i] ~= 0 then return false end
        end
        return true
    end

    local function read_int(index)
        stats.reads = stats.reads + 1
        local value = host.ReadInt(index)
        if not integer(value) or value < -2147483648 or value > 2147483647 then
            error('Income receipt integer unavailable')
        end
        return value
    end

    local function read_sample()
        if type(host.AreValid) ~= 'function' or type(host.ReadInt) ~= 'function'
            or host.AreValid() ~= true then error('Income receipt globals unavailable') end
        if read_int(4521047) ~= 16 then error('Income receipt layout unavailable') end
        local first, second = {}, {}
        for pass = 1, 2 do
            local target = pass == 1 and first or second
            for slot = 1, 15 do
                local row = {}
                local base = 4521047 + 1 + (slot - 1) * 12
                for i = 1, 10 do row[i] = read_int(base + offsets[i]) end
                target[slot] = row
            end
        end
        if read_int(4521047) ~= 16 or host.AreValid() ~= true then
            error('Income receipt layout changed')
        end
        for slot = 1, 15 do
            if not same_row(first[slot], second[slot], 10) then
                return nil, 'Torn'
            end
        end
        return second
    end

    function api.Reset()
        clear_baseline('Reset')
        state.scope = nil
        stats.resets = stats.resets + 1
        -- Keep the rate limit and evidence serial across resets.
    end

    function api.Snapshot()
        local snapshot = {}
        for key, value in pairs(stats) do snapshot[key] = value end
        snapshot.ready = state.rows ~= nil
        snapshot.last_sample_ms = state.last_attempt
        return snapshot
    end

    function api.Poll(scope, now_ms)
        stats.polls = stats.polls + 1
        local receipts = {}
        if type(scope) ~= 'table' or not integer(scope.account) or scope.account <= 0
            or (scope.slot ~= 0 and scope.slot ~= 1) or not integer(scope.epoch) then
            clear_baseline('Invalid scope')
            state.scope = nil
            stats.invalid_scope = stats.invalid_scope + 1
            return receipts
        end
        if not integer(now_ms) or now_ms < 0 then
            clear_baseline('Invalid clock')
            stats.clock_resets = stats.clock_resets + 1
            return receipts
        end
        if state.last_now ~= nil and now_ms < state.last_now then
            clear_baseline('Clock reversed')
            state.last_now, state.last_attempt = now_ms, now_ms
            stats.clock_resets = stats.clock_resets + 1
            return receipts
        end
        state.last_now = now_ms
        if state.scope == nil or state.scope.account ~= scope.account
            or state.scope.slot ~= scope.slot or state.scope.epoch ~= scope.epoch then
            clear_baseline('Scope changed')
            state.scope = {account = scope.account, slot = scope.slot, epoch = scope.epoch}
            stats.scope_changes = stats.scope_changes + 1
        end
        if state.last_attempt ~= nil and now_ms - state.last_attempt < 250 then
            stats.throttled = stats.throttled + 1
            return receipts
        end
        state.last_attempt = now_ms
        local ok, rows, reason = pcall(read_sample)
        if not ok or rows == nil then
            clear_baseline(reason or 'Read failed')
            stats.errors = stats.errors + 1
            if reason == 'Torn' then stats.torn = stats.torn + 1 end
            return receipts
        end
        stats.samples = stats.samples + 1
        if state.rows == nil then
            state.rows = rows
            stats.seeded = stats.seeded + 1
            stats.status = 'Seeded'
            return receipts
        end
        for slot = 1, 15 do
            local row, before = rows[slot], state.rows[slot]
            if zero_row(row) then
                if not zero_row(before) then
                    state.row_seeds[slot] = before
                    stats.zero_resets = stats.zero_resets + 1
                end
            else
                local reset_before = state.row_seeds[slot]
                state.row_seeds[slot] = nil
                -- Only the old tuple returning after a reset is ambiguous.
                -- A different valid callback must survive normal heist resets.
                local restored = reset_before and same_row(row, reset_before, 9)
                local changed = not same_row(row, before, 9)
                    or (before[10] == 0 and row[10] == 1)
                local mapping = source_map[row[3]]
                if not restored and changed and mapping and row[1] == -1135378931
                    and row[2] == 1445302971 and row[4] > 0
                    and row[5] == row[1] and row[6] == row[2] and row[7] == row[3]
                    and (row[10] == 0 or row[10] == 1) then
                    state.serial = state.serial + 1
                    receipts[#receipts + 1] = {category = mapping[1], label = mapping[2],
                        amount = row[4], observed_ms = now_ms,
                        evidence_id = 'income-receipt-' .. tostring(instance) .. '-' .. tostring(state.serial),
                        account = state.scope.account, slot = state.scope.slot, epoch = state.scope.epoch}
                    stats.emitted = stats.emitted + 1
                end
            end
        end
        state.rows = rows
        stats.status = 'Current'
        return receipts
    end

    return api
end

Module.Income={WindowMs=15000,GraceMs=1000}
function Module.Income.Reset()
    local income=Module.Income
    income.receipts,income.events,income.claims,income.seen,income.exclusions={},{},{},{},{}
    income.scope=nil
    if income.observer then income.observer.Reset() end
end
function Module.Income.ResetSlot(slot)
    if slot~=0 and slot~=1 then return end
    Module.Income.Reset()
    State.attribution_epoch=(State.attribution_epoch or 0)+1
    Module.Settlement.pending={}
    if State.baseline_valid and State.money_observation and State.money_observation.slot==slot then
        State.money_observation.attribution_epoch=State.attribution_epoch
    end
end
function Module.Income.ExcludeNegative(observation)
    local income=Module.Income
    income.exclusions=income.exclusions or {}
    income.exclusions[#income.exclusions+1]={account=observation.account,slot=observation.slot,epoch=observation.epoch,
        from_ms=observation.from_ms,to_ms=observation.to_ms+income.WindowMs}
    while #income.exclusions>16 do table.remove(income.exclusions,1) end
    local retained={}
    for _,receipt in ipairs(income.receipts or {}) do
        if receipt.account~=observation.account or receipt.slot~=observation.slot or receipt.epoch~=observation.epoch
            or receipt.observed_ms<observation.from_ms or receipt.observed_ms>observation.to_ms+income.WindowMs then retained[#retained+1]=receipt end
    end
    income.receipts=retained
end
function Module.Income.Claim(event)
    local income,observation=Module.Income,event and event._income_observation
    if not observation then return end
    local category
    if event.source~="Unknown" then category=source_bucket(event.source) end
    income.claims=income.claims or {}
    income.claims[#income.claims+1]={account=observation.account,slot=observation.slot,epoch=observation.epoch,
        from_ms=observation.from_ms,to_ms=observation.to_ms,amount=event.amount,category=category}
    while #income.claims>16 do table.remove(income.claims,1) end
end
function Module.Income.Track(event,observation)
    if type(observation)~="table" then return end
    local income=Module.Income
    income.events,income.receipts,income.claims,income.seen=income.events or {},income.receipts or {},income.claims or {},income.seen or {}
    event._income_observation=observation
    if event.source~="Unknown" or not observation.source_eligible then Module.Income.Claim(event);return end
    observation.amount,observation.balance_before=event.amount,event.balance_before
    local pending={event=event,observation=observation}
    income.events[#income.events+1]=pending
    if #income.events>16 then Module.Income.Reset() end
end
function Module.Income.Candidates(target,receipts,budget)
    local eligible={}
    for _,receipt in ipairs(receipts) do
        if receipt.account==target.account and receipt.slot==target.slot and receipt.epoch==target.epoch
            and receipt.observed_ms>=target.from_ms and receipt.observed_ms<=target.to_ms+Module.Income.WindowMs then
            eligible[#eligible+1]=receipt
        end
    end
    if #eligible>8 then return {} end
    local choices={}
    for mask=1,(1<<#eligible)-1 do
        budget.work=budget.work+1;if budget.work>2048 then return nil end
        local total,category,label,valid,selected=0,nil,nil,true,{}
        for index,receipt in ipairs(eligible) do
            if (mask & (1<<(index-1)))~=0 then
                total=total+receipt.amount
                if category and category~=receipt.category then valid=false end
                category=category or receipt.category
                if label and label~=receipt.label then label=false elseif label==nil then label=receipt.label end
                selected[#selected+1]=receipt
            end
        end
        if valid and total==target.amount and (not target.category or category==target.category) then
            choices[#choices+1]={receipts=selected,category=category,label=label}
        end
    end
    return choices
end
function Module.Income.Match(now)
    local income,nodes,retained,budget=Module.Income,{},{},{work=0}
    for _,pending in ipairs(income.events or {}) do
        local event,observation=pending.event,pending.observation
        if State.account_verified and State.account_id==observation.account and State.character_slot==observation.slot
            and State.attribution_epoch==observation.epoch and event.source=="Unknown"
            and now>=observation.to_ms and now-observation.to_ms<=income.WindowMs
            and event.amount==observation.amount and event.balance_before==observation.balance_before
            and observation.event_count<=(State.verified_events_since_start or 0)
            and (not Module.Journal or event.journal_epoch==Module.Journal.Epoch(State.lifetime_by_slot,observation.slot)) then
            retained[#retained+1]=pending
            local choices=income.Candidates(observation,income.receipts or {},budget);if not choices then return end
            nodes[#nodes+1]={pending=pending,target=observation,choices=choices,ready=now-observation.to_ms>=income.GraceMs}
        end
    end
    income.events=retained
    for _,claim in ipairs(income.claims or {}) do
        if now<=claim.to_ms+income.WindowMs then
            local choices=income.Candidates(claim,income.receipts or {},budget);if not choices then return end
            nodes[#nodes+1]={target=claim,choices=choices,ready=true,claim=true}
        end
    end
    local selected,used={},{ }
    for index,node in ipairs(nodes) do
        if node.ready and #node.choices==1 then
            local choice,conflict=node.choices[1],false
            for other_index,other in ipairs(nodes) do
                if other_index~=index then
                    for _,alternative in ipairs(other.choices) do
                        budget.work=budget.work+1;if budget.work>2048 then return end
                        for _,receipt in ipairs(choice.receipts) do
                            for _,candidate in ipairs(alternative.receipts) do
                                if receipt.evidence_id==candidate.evidence_id then conflict=true end
                            end
                        end
                    end
                end
            end
            if not conflict then
                selected[#selected+1]={node=node,choice=choice}
                for _,receipt in ipairs(choice.receipts) do used[receipt.evidence_id]=true end
            end
        end
    end
    local changed=true
    while changed do
        changed=false;used={}
        for _,selection in ipairs(selected) do
            if not selection.blocked then
                for _,receipt in ipairs(selection.choice.receipts) do used[receipt.evidence_id]=true end
            end
        end
        for _,selection in ipairs(selected) do
            if not selection.blocked and not selection.node.claim then
                for _,receipt in ipairs(income.receipts or {}) do
                    budget.work=budget.work+1;if budget.work>2048 then return end
                    local target=selection.node.target
                    if receipt.account==target.account and receipt.slot==target.slot and receipt.epoch==target.epoch
                        and receipt.observed_ms>=target.from_ms and receipt.observed_ms<=target.to_ms+income.WindowMs
                        and not used[receipt.evidence_id] then selection.blocked=true;changed=true;break end
                end
            end
        end
    end
    local consumed={}
    for _,selection in ipairs(selected) do
        if not selection.blocked then
            local node,choice=selection.node,selection.choice
            if node.pending then
                local event=node.pending.event
                event.source=choice.category
                event.detail=clean(choice.label or ({Heists="Heist income",Businesses="Business income",Missions="Mission income",Safes="Safe income"})[choice.category],180)
                event._income_generic=true
                Dirty.Earnings();update_cached_summary(epoch(),false);commit_earnings("source-attribution",event)
            end
            for _,receipt in ipairs(choice.receipts) do consumed[receipt.evidence_id]=true end
        end
    end
    local remaining={}
    for _,receipt in ipairs(income.receipts or {}) do if not consumed[receipt.evidence_id] then remaining[#remaining+1]=receipt end end
    income.receipts=remaining
end
function Module.Income.Poll(now)
    local income=Module.Income
    if income.last_now and now<income.last_now then income.Reset();income.next_poll=nil end
    income.last_now=now
    if now<(income.next_poll or 0) then return end
    income.next_poll=now+250
    if Module.clock_valid==false or State.persistence_loaded~=true or State.persistence_authoritative~=true then income.Reset();return end
    local account=resolve_local_account_identity()
    local slot=detect_character_slot()
    if slot==nil and State.money_observation then
        local observed=Module.Money.CurrentObservation(State.money_observation.slot,now)
        if observed then slot=observed.slot end
    end
    local transfer=Module.bank_transfer and Module.bank_transfer.Snapshot()
    if account and account~=State.account_id then
        Module.Money.BreakSourceScope();Module.Money.Drop();State.account_verified=false
    elseif not account and State.account_verified then
        Module.Money.BreakSourceScope();State.account_verified=false
    end
    if account~=State.account_id or not account or slot==nil
        or transfer and (transfer.pause_tracking or transfer.busy and transfer.accounting_excluded) then income.Reset();return end
    local scope={account=account,slot=slot,epoch=State.attribution_epoch or 0}
    local key=table.concat({account,slot,scope.epoch},":")
    if income.scope and income.scope~=key then income.Reset() end
    income.scope=key
    if not income.observer then
        income.observer=Module.NewIncomeReceiptObserver({
            ReadInt=function(index)return module_context.Raw.ScriptGlobal.GetInt(index)end,
            AreValid=function()local globals=module_context.Raw.ScriptGlobal;return globals and type(globals.AreValid)=="function" and globals.AreValid() or false end,
        })
    end
    local ok,receipts=pcall(income.observer.Poll,scope,now)
    if not ok or type(receipts)~="table" or not income.observer.Snapshot().ready then income.Reset();return end
    local kept={}
    for _,receipt in ipairs(income.receipts or {}) do if now-receipt.observed_ms<=income.WindowMs then kept[#kept+1]=receipt end end
    income.receipts=kept;income.events=income.events or {};income.seen=income.seen or {};income.claims=income.claims or {}
    local claims={};for _,claim in ipairs(income.claims) do if now<=claim.to_ms+income.WindowMs then claims[#claims+1]=claim end end;income.claims=claims
    for _,receipt in ipairs(receipts) do
        local valid=type(receipt)=="table" and receipt.account==account and receipt.slot==slot and receipt.epoch==scope.epoch
            and type(receipt.evidence_id)=="string" and receipt.evidence_id~="" and #receipt.evidence_id<=120
            and Module.Money.ValidBalance(receipt.amount) and receipt.amount>0
            and type(receipt.observed_ms)=="number" and receipt.observed_ms<=now and now-receipt.observed_ms<=income.WindowMs
            and (receipt.category=="Heists" or receipt.category=="Businesses" or receipt.category=="Missions" or receipt.category=="Safes")
            and type(receipt.label)=="string" and receipt.label~=""
        if valid and not income.seen[receipt.evidence_id] then
            income.seen[receipt.evidence_id]=receipt.observed_ms
            local excluded=false
            for _,boundary in ipairs(income.exclusions or {}) do
                if boundary.account==account and boundary.slot==slot and boundary.epoch==scope.epoch
                    and receipt.observed_ms>=boundary.from_ms and receipt.observed_ms<=boundary.to_ms then excluded=true end
            end
            if not excluded then income.receipts[#income.receipts+1]=receipt end
        end
    end
    for identity,time in pairs(income.seen) do if now-time>income.WindowMs then income.seen[identity]=nil end end
    local boundaries={};for _,boundary in ipairs(income.exclusions or {}) do if now<=boundary.to_ms then boundaries[#boundaries+1]=boundary end end
    income.exclusions=boundaries
    if #income.receipts>32 then income.Reset();return end
    income.Match(now)
end

Module.Money={Maximum=2147483647,BridgeMs=180000}
function Module.Money.ValidBalance(value)
    return type(value)=="number" and value==value and value>=0 and value<=Module.Money.Maximum and value%1==0
end
function Module.Money.BreakSourceScope()
    State.generation=(State.generation or 0)+1
    State.attribution_epoch=(State.attribution_epoch or 0)+1
    Module.Settlement.pending={}
end
function Module.Money.Drop(reason)
    State.baseline_valid,State.baseline_slot=false,nil
    State.baseline_cash,State.baseline_bank,State.baseline_total,State.previous_total=nil,nil,nil,nil
    State.money_observation=nil
    State.money_identity_epoch=(State.money_identity_epoch or 0)+1
    State.money_tracking_status=reason or "Waiting for a new balance baseline"
    if Module.Income and Module.Income.Reset then Module.Income.Reset() end
end
local function clear_money_baseline(preserve_observation)
    State.baseline_valid,State.baseline_slot=false,nil
    State.baseline_cash,State.baseline_bank,State.baseline_total=nil,nil,nil
    State.previous_total=nil
    if preserve_observation~=true then Module.Money.Drop() end
end
local function establish_money_baseline(slot,cash,bank,now)
    State.baseline_valid,State.baseline_slot=true,slot
    State.baseline_cash,State.baseline_bank=cash,bank
    State.baseline_total,State.previous_total=cash+bank,cash+bank
    State.cash,State.bank,State.total,State.money_status=cash,bank,cash+bank,"Current"
    if Module.clock_valid~=false then
        State.money_observation={account=State.account_id,slot=slot,epoch=State.money_identity_epoch or 0,
            cash=cash,bank=bank,total=cash+bank,observed_ms=now or now_ms(),attribution_epoch=State.attribution_epoch or 0}
    else State.money_observation=nil end
    update_cached_summary(epoch(),false)
end
function Module.Money.CurrentObservation(slot,now)
    local observed=State.money_observation
    if not observed or Module.clock_valid==false or now<observed.observed_ms
        or now-observed.observed_ms>Module.Money.BridgeMs
        or observed.account~=State.account_id or observed.slot~=slot
        or observed.epoch~=(State.money_identity_epoch or 0) then return nil end
    return observed
end
local function refresh_money(force)
    if not State.account_id or State.persistence_loaded~=true or State.persistence_authoritative~=true then
        State.money_status="Waiting for earnings history";return false
    end
    local now=now_ms()
    if not force and now>=(State.last_money_refresh_ms or -100000) and now-(State.last_money_refresh_ms or -100000)<MONEY_REFRESH_MS then return false end
    State.last_money_refresh_ms=now
    local account=resolve_local_account_identity()
    if not account then
        if State.account_verified then Module.Money.BreakSourceScope() end
        State.account_verified=false;State.money_status="Waiting for account identity";clear_money_baseline(true);return false
    end
    if account~=State.account_id then
        Module.Money.BreakSourceScope()
        State.account_verified=false;clear_money_baseline();State.money_status="Account changed; waiting for history";return false
    end
    State.account_verified=true
    local previous_slot=State.character_slot
    local slot,slot_err=detect_character_slot()
    local observed=State.money_observation
    if slot~=nil and (previous_slot~=nil and previous_slot~=slot or observed and observed.slot~=slot) then
        State.generation=(State.generation or 0)+1
        State.attribution_epoch=(State.attribution_epoch or 0)+1;Module.Settlement.pending={}
        clear_money_baseline();State.action_queue={}
        State.invalidation_reason="GTA Online character changed";invalidate_dependents(State.invalidation_reason)
    end
    State.online,State.character_slot=slot~=nil,slot
    State.character_label=slot~=nil and ("Character "..tostring(slot+1)) or "Unavailable"
    if slot==nil then
        State.cash,State.bank,State.total=nil,nil,nil;State.money_status=slot_err or "Waiting for character"
        clear_money_baseline(true);update_cached_summary(epoch(),false);return false
    end
    State.attribution_slot=slot
    local transfer=Module.bank_transfer and Module.bank_transfer.Snapshot()
    if transfer and (transfer.pause_tracking or transfer.busy and transfer.accounting_excluded) then
        if not State.money_transfer_excluded then
            State.attribution_epoch=(State.attribution_epoch or 0)+1;Module.Settlement.pending={}
        end
        State.money_transfer_excluded=true;clear_money_baseline()
        State.money_status="Bank transfer in progress";return false
    end
    State.money_transfer_excluded=false
    local cash,bank,money_err=read_money(slot)
    if cash==nil then
        State.cash,State.bank,State.total=nil,nil,nil;State.money_status=money_err
        clear_money_baseline(true);update_cached_summary(epoch(),false);return false
    end
    local after_account=resolve_local_account_identity()
    local after_slot=detect_character_slot()
    if after_account~=account or after_slot~=slot then
        if after_account and after_account~=account or after_slot~=nil and after_slot~=slot then
            Module.Money.BreakSourceScope();clear_money_baseline()
        else
            if not after_account and State.account_verified then Module.Money.BreakSourceScope() end
            clear_money_baseline(true)
        end
        State.account_verified=after_account==account
        State.money_status="Identity changed during balance read";return false
    end
    observed=Module.Money.CurrentObservation(slot,now)
    if not observed then
        if State.money_observation then Module.Money.BreakSourceScope() end
        clear_money_baseline();establish_money_baseline(slot,cash,bank,now)
        State.money_tracking_status="Balance baseline ready";return true
    end
    local recovered=State.baseline_valid~=true
    local cash_delta,bank_delta=cash-observed.cash,bank-observed.bank
    local total_delta=cash+bank-observed.total
    State.last_verified_delta=total_delta
    if total_delta<0 then
        Module.Income.ExcludeNegative({account=account,slot=slot,epoch=State.attribution_epoch or 0,from_ms=observed.observed_ms,to_ms=now})
    end
    if total_delta>0 then
        add_earning("Unknown",total_delta,recovered and "Net balance increase after a gap" or "Observed net cash and bank increase",{
            cash_delta=cash_delta,bank_delta=bank_delta,character_slot=slot,session_id=State.tracking_session_id,
            balance_before=observed.total,observation={account=account,slot=slot,epoch=State.attribution_epoch or 0,
                from_ms=observed.observed_ms,to_ms=now,event_count=(State.verified_events_since_start or 0)+1,
                source_eligible=cash_delta>=0 and bank_delta>=0 and observed.attribution_epoch==(State.attribution_epoch or 0)}})
    end
    establish_money_baseline(slot,cash,bank,now)
    State.money_tracking_status=recovered and "Balance tracking resumed" or "Balance tracking current"
    return true
end

local function save_settings()
    if not State.paths then return false, "Economy settings storage is unavailable" end
    local content = table.concat({
        "CSCRIPT_ECONOMY_SETTINGS_V2",
        "daily_caution=" .. tostring(math.max(0, math.floor(tonumber(State.daily_caution) or 0))),
        "weekly_caution=" .. tostring(math.max(0, math.floor(tonumber(State.weekly_caution) or 0))),
        "advanced=" .. tostring(State.advanced == true),
        "hud_enabled=" .. tostring(State.hud_enabled == true),
    }, "\n")
    local exists = file_exists(State.paths.settings)
    if exists == true then
        local previous = read_file(State.paths.settings)
        local header = canonical_text(previous)
        local first_line = type(header) == "string" and header:match("^([^\n]+)") or nil
        if type(first_line) == "string" and first_line:find("CSCRIPT_ECONOMY_SETTINGS_V", 1, true) == 1 then
            local backup_ok, backup_err = write_file(State.paths.settings .. ".bak", previous)
            if not backup_ok then return false, "settings backup failed: " .. tostring(backup_err) end
        end
    end
    return write_file(State.paths.settings, content)
end

local function copy_verified(source, destination, validator)
    local content, read_err = read_file(source)
    if type(content) ~= "string" then return false, read_err end
    if type(validator) == "function" then
        local valid, validation_err = validator(content, source)
        if valid ~= true then return false, validation_err or "source validation failed" end
    end
    local wrote, write_err = write_file(destination, content)
    if not wrote then return false, write_err end
    local reread, reread_err = read_file(destination)
    if type(reread) ~= "string" then return false, reread_err end
    if type(validator) == "function" then
        local valid, validation_err = validator(reread, destination)
        if valid ~= true then return false, validation_err or "destination validation failed" end
    end
    return true
end

local function migrate_legacy_tree(paths)
    local old = paths.old
    local migrated = false

    -- v1/v2 earnings files lack Rockstar account IDs and may combine logins.
    -- Preserve those journals without importing them into the active account;
    -- start tracking each verified RID separately.

    local copies = {
        { old.history, paths.history },
        { old.settings, paths.settings },
    }
    for _, item in ipairs(copies) do
        if file_exists(item[2]) == false and file_exists(item[1]) == true then
            local ok, err = copy_verified(item[1], item[2])
            if not ok then return false, "supporting Economy file migration failed: " .. tostring(err) end
            migrated = true
        end
    end

    local files = file_mgr()
    if files and type(files.FindFiles) == "function" then
        local ok, found = pcall(files.FindFiles, old.snapshots, ".snapshot", false)
        if ok and type(found) == "table" then
            for _, source in pairs(found) do
                source = tostring(source or "")
                local name = source:match("[^\\/]+$")
                if name and name ~= "" then
                    if not source:find("[\\/]", 1) then source = old.snapshots .. "\\" .. source end
                    local destination = paths.snapshots .. "\\" .. name
                    if file_exists(destination) == false then
                        local copy_ok, copy_err = copy_verified(source, destination, function(content, path)
                            local snapshot, snapshot_err = parse_snapshot(content, path)
                            return snapshot ~= nil, snapshot_err
                        end)
                        if not copy_ok then return false, "snapshot migration failed: " .. tostring(copy_err) end
                        migrated = true
                    end
                end
            end
        end
    end
    return true, migrated
end

local function load_settings(path)
    local content = canonical_text(read_file(path))
    if type(content) ~= "string" then return false, "settings file is unavailable" end
    local header = content:match("^([^\n]+)")
    if header ~= "CSCRIPT_ECONOMY_SETTINGS_V2" and header ~= "CSCRIPT_ECONOMY_SETTINGS_V1" then
        return false, "settings header is invalid"
    end
    if header == "CSCRIPT_ECONOMY_SETTINGS_V2" then
        State.daily_caution = DEFAULT_DAILY_CAUTION
        State.weekly_caution = DEFAULT_WEEKLY_CAUTION
    end
    State.advanced = content:match("advanced=([^\n]+)") == "true"
    State.hud_enabled = content:match("hud_enabled=([^\n]+)") == "true"
    return true
end

local function load_settings_with_backup(path)
    local ok, err = load_settings(path)
    if ok then return true end
    local backup = path .. ".bak"
    local backup_ok, backup_err = load_settings(backup)
    if not backup_ok then return false, err or backup_err end
    local content = read_file(backup)
    local restored, restore_err = write_file(path, content)
    if not restored then return false, "settings backup loaded but restore failed: " .. tostring(restore_err) end
    return true, "RECOVERED_BACKUP"
end

local function load_journal(paths)
    local main_exists, exists_err = file_exists(paths.earnings)
    if main_exists == nil then return nil, nil, "READ_ERROR", exists_err, true end
    if main_exists then
        local content, read_err = read_file(paths.earnings)
        local earnings, lifetime, valid, parse_err = parse_earnings(content, paths.account_id)
        if valid then return earnings, lifetime, "READY", nil, false end

        local backup_content, backup_read_err = read_file(paths.earnings_backup)
        local backup_events, backup_lifetime, backup_valid, backup_parse_err =
            parse_earnings(backup_content, paths.account_id)
        if backup_valid then
            if type(content) ~= "string" then
                return backup_events, backup_lifetime, "RECOVERED_BACKUP",
                    "main journal could not be read; backup loaded read-only: " .. tostring(read_err), true
            end
            local preserved = paths.earnings .. ".invalid-" .. timestamp_id()
            local preserved_ok, preserved_err = write_file(preserved, content)
            if not preserved_ok then
                return backup_events, backup_lifetime, "RECOVERED_BACKUP",
                    "backup loaded read-only; invalid journal preservation failed: " .. tostring(preserved_err), true
            end
            local restored, restore_err = write_file(paths.earnings, backup_content)
            local restored_content = restored and read_file(paths.earnings) or nil
            local restored_events, restored_lifetime, restored_valid, restored_parse_err =
                parse_earnings(restored_content, paths.account_id)
            if restored and restored_valid then
                return restored_events, restored_lifetime, "RECOVERED_BACKUP",
                    "invalid main journal was preserved and the verified backup was restored", false
            end
            return backup_events, backup_lifetime, "RECOVERED_BACKUP",
                "backup loaded read-only; restore failed: " .. tostring(restore_err or restored_parse_err), true
        end
        local status = type(content) == "string" and "INVALID_JOURNAL" or "READ_ERROR"
        return {}, { [0] = 0, [1] = 0 }, status,
            tostring(parse_err or read_err) .. "; backup: " .. tostring(backup_parse_err or backup_read_err), true
    end

    local backup_content = read_file(paths.earnings_backup)
    local backup_events, backup_lifetime, backup_valid, backup_err =
        parse_earnings(backup_content, paths.account_id)
    if backup_valid then
        local restored, restore_err = write_file(paths.earnings, backup_content)
        if restored then return backup_events, backup_lifetime, "RECOVERED_BACKUP", nil, false end
        return backup_events, backup_lifetime, "RECOVERED_BACKUP", tostring(restore_err), true
    end
    local emergency_events, emergency_lifetime, merged, valid_emergencies =
        merge_emergency_snapshots(paths, {}, { [0] = 0, [1] = 0 })
    if valid_emergencies > 0 then
        return emergency_events, emergency_lifetime, "RECOVERED_BACKUP",
            ("loaded %d verified emergency snapshot(s) for atomic recovery"):format(valid_emergencies), false
    end
    return {}, { [0] = 0, [1] = 0 }, "NEW", nil, false
end

local function load_persistence(stage)
    local api_ok, api_err = refresh_cached_file_api()
    if not api_ok then return false, "FILE_API", api_err end
    local account_id, account_name, account_err = resolve_local_account_identity()
    if not account_id then
        State.attribution_epoch=(State.attribution_epoch or 0)+1
        Module.Settlement.pending={}
        State.account_verified = false
        return false, "ACCOUNT_ID", account_err
    end
    if State.account_id and tonumber(State.account_id) ~= tonumber(account_id) then
        State.attribution_epoch=(State.attribution_epoch or 0)+1
        Module.Settlement.pending={}
        cached_paths = nil
    end
    State.account_id, State.account_name, State.account_verified = account_id, account_name, true
    local paths, path_err = storage_paths(account_id)
    if not paths then
        return false, "PATH", path_err
    end
    State.paths = paths
    local migration_ok, migrated_or_err = migrate_legacy_tree(paths)
    if not migration_ok then
        return false, "MIGRATE", migrated_or_err
    end
    local migrated = migrated_or_err == true
    local earnings, lifetime, status, journal_detail, blocked = load_journal(paths)
    if blocked == true then
        return false, status or "JOURNAL", journal_detail or "persistent journal is unavailable"
    end
    State.paths = paths
    State.history = parse_history(read_file(paths.history), "CSCRIPT_ECONOMY_HISTORY_V1")
    State.earnings, State.lifetime_by_slot = earnings, lifetime
    State.persistence_status = migrated and status == "READY" and "MIGRATED" or status
    State.persistence_stage = stage or "START"
    State.persistence_error = journal_detail
    State.persistence_write_blocked = false
    if status == "RECOVERED_BACKUP" and file_exists(paths.earnings) ~= true then
        Dirty.Earnings()
    end
    -- Shared v1/v2 journals are intentionally not imported because they do not
    -- identify the Rockstar account that earned each event.
    local merged, emergency_count
    State.earnings, State.lifetime_by_slot, merged, emergency_count =
        merge_emergency_snapshots(paths, State.earnings, State.lifetime_by_slot)
    if merged > 0 then
        State.persistence_status = "RECOVERED_BACKUP"
        Dirty.Earnings()
        journal_detail = ("merged %d verified event(s) from emergency snapshots"):format(merged)
        State.persistence_error = journal_detail
    end
    if Module.Journal.recovery_ambiguous then
        State.persistence_status = "DEGRADED"
        State.persistence_error = Module.Journal.ambiguity_message
    end
    local settings_ok, settings_detail = load_settings_with_backup(paths.settings)
    local settings_status = settings_ok and (settings_detail or "READY") or "UNAVAILABLE"
    if settings_detail == "RECOVERED_BACKUP" and State.persistence_status == "READY" then
        State.persistence_status = "RECOVERED_BACKUP"
    elseif not settings_ok and file_exists(paths.settings) == true then
        State.persistence_error = State.persistence_error or settings_detail
        if State.persistence_status == "READY" then State.persistence_status = "DEGRADED" end
    end
    prune_earnings(epoch())
    State.persistence_loaded, State.persistence_authoritative = true, true
    State.persistence_write_blocked = false
    State.persistence_failure_stage = nil
    State.persistence_retry_at_ms = nil
    if Dirty.Sync() then
        local committed, commit_err = commit_earnings(merged > 0 and "emergency-merge" or "startup-migration", nil)
        if not committed then
            State.persistence_loaded, State.persistence_authoritative = false, false
            return false, "START_COMMIT", commit_err
        end
    end
    local slot_counts = { [0] = 0, [1] = 0 }
    for _, item in ipairs(State.earnings) do
        if slot_counts[item.character_slot] ~= nil then slot_counts[item.character_slot] = slot_counts[item.character_slot] + 1 end
    end
    local exists_main, exists_backup = file_exists(paths.earnings), file_exists(paths.earnings_backup)
    local legacy_present = file_exists(paths.legacy_shared_earnings) == true
        or file_exists(paths.legacy_earnings) == true
    log_info(("Persistence load stage=%s account=%s name=%s path=%s main=%s backup=%s emergency=%d events=%d slots=%d/%d lifetime=%d/%d settings=%s status=%s legacySharedPreserved=%s%s"):format(
        tostring(stage or "START"), tostring(State.account_id), clean(State.account_name, 80),
        paths.earnings, tostring(exists_main == true), tostring(exists_backup == true),
        tonumber(emergency_count) or 0, #State.earnings,
        slot_counts[0], slot_counts[1], State.lifetime_by_slot[0] or 0, State.lifetime_by_slot[1] or 0,
        tostring(settings_status), tostring(State.persistence_status), tostring(legacy_present),
        journal_detail and (" detail=" .. clean(journal_detail, 120)) or ""))
    return true
end

local function attempt_persistence_bootstrap(stage)
    if State.persistence_loaded == true then return true end
    State.persistence_attempts = (tonumber(State.persistence_attempts) or 0) + 1
    local ok, failure_stage, failure = load_persistence(stage)
    if ok then
        State.persistence_retry_at_ms = nil
        refresh_money(true)
        update_cached_summary(epoch(), false)
        return true
    end
    State.persistence_failure_stage = tostring(failure_stage or "UNKNOWN")
    State.persistence_error = clean(failure or "persistent storage is unavailable", 220)
    State.persistence_write_blocked = true
    clear_money_baseline()
    if State.persistence_failure_stage == "ACCOUNT_ID" then
        State.persistence_status, State.persistence_stage = "PENDING_ACCOUNT", "ACCOUNT_ID_RETRY"
        State.persistence_retry_at_ms = now_ms() + ACCOUNT_ID_RETRY_MS
        State.persistence_attempts = 0
        State.money_status = "Waiting for Rockstar account identity"
        update_cached_summary(epoch(), false)
        return false
    end
    if State.persistence_attempts < PERSISTENCE_MAX_ATTEMPTS then
        State.persistence_status, State.persistence_stage = "PENDING", "START_RETRY"
        State.persistence_retry_at_ms = now_ms() + PERSISTENCE_RETRY_MS
        return false
    end
    State.persistence_status, State.persistence_stage = "DEGRADED_READONLY", "START_RETRY_EXHAUSTED"
    State.persistence_retry_at_ms = nil
    log_error(("Persistence load stage=%s path=%s main=%s backup=%s emergency=%d events=%d lifetime=%d/%d settings=UNAVAILABLE status=DEGRADED_READONLY failure_stage=%s error=%s"):format(
        tostring(stage or "START_RETRY"), tostring(active_paths() and active_paths().earnings or "Unavailable"),
        tostring(active_paths() and file_exists(active_paths().earnings) == true or false),
        tostring(active_paths() and file_exists(active_paths().earnings_backup) == true or false),
        active_paths() and #emergency_paths(active_paths()) or 0, #(State.earnings or {}),
        tonumber(State.lifetime_by_slot[0]) or 0, tonumber(State.lifetime_by_slot[1]) or 0,
        State.persistence_failure_stage, State.persistence_error))
    update_cached_summary(epoch(), false)
    return false
end

local function verify_active_account_scope(now)
    now = tonumber(now) or now_ms()
    if now - (tonumber(State.last_account_check_ms) or -100000) < ACCOUNT_ID_RETRY_MS then
        return State.account_verified == true
    end
    State.last_account_check_ms = now
    local account_id, account_name, account_err = resolve_local_account_identity()
    if not account_id then
        State.attribution_epoch=(State.attribution_epoch or 0)+1
        Module.Settlement.pending={}
        if State.account_verified == true then
            log_info("Rockstar account identity became unavailable; earnings tracking paused without changing the loaded journal.")
        end
        State.account_verified = false
        State.money_status = "Waiting for Rockstar account identity"
        State.account_error = clean(account_err, 180)
        clear_money_baseline(true)
        update_cached_summary(epoch(), false)
        return false
    end

    if State.account_id and tonumber(State.account_id) ~= tonumber(account_id) then
        local previous_id = tonumber(State.account_id)
        State.attribution_epoch=(State.attribution_epoch or 0)+1
        Module.Settlement.pending={}
        local saved, save_err = true, nil
        if State.persistence_loaded == true and State.persistence_authoritative == true
            and State.persistence_dirty == true then
            saved, save_err = save_histories(true)
        end
        if not saved then
            State.account_verified = false
            State.money_status = "Account changed; previous journal save failed"
            State.account_error = clean(save_err, 180)
            State.persistence_status, State.persistence_stage = "DEGRADED_READONLY", "ACCOUNT_SWITCH_SAVE"
            clear_money_baseline()
            log_error(("Rockstar account changed from %s to %s, but the previous account journal could not be finalized: %s")
                :format(tostring(previous_id), tostring(account_id), tostring(State.account_error)))
            return false
        end

        cached_paths = nil
        emergency_save_attempted = false
        State.account_id, State.account_name, State.account_verified = account_id, account_name, true
        State.profile_stats,State.profile_pending_verify,State.profile_last_change=nil,nil,nil
        State.action_queue={}
        State.account_error = nil
        State.paths = nil
        State.history, State.earnings, State.lifetime_by_slot = {}, {}, { [0] = 0, [1] = 0 }
        State.threshold_levels = {}
        State.persistence_status, State.persistence_stage = "PENDING", "ACCOUNT_SWITCH"
        State.persistence_error, State.persistence_failure_stage = nil, nil
        State.persistence_loaded, State.persistence_authoritative = false, false
        State.persistence_write_blocked = false
        State.history_dirty, State.earnings_dirty, State.persistence_dirty = false, false, false
        State.persistence_attempts, State.persistence_retry_at_ms = 0, now
        State.verified_events_since_start = 0
        State.last_money_refresh_ms = -100000
        State.tracking_session_id = timestamp_id() .. "-account-" .. tostring(account_id)
        clear_money_baseline()
        log_info(("Rockstar account changed from %s to %s; switching to an isolated earnings journal.")
            :format(tostring(previous_id), tostring(account_id)))
        return attempt_persistence_bootstrap("ACCOUNT_SWITCH")
    end

    local resumed = State.account_verified ~= true
    State.account_id, State.account_name, State.account_verified = account_id, account_name, true
    State.account_error = nil
    if resumed then
        clear_money_baseline(true)
        log_info(("Rockstar account identity verified for RID %s; earnings tracking will resume from a fresh balance baseline.")
            :format(tostring(account_id)))
    end
    return true
end

local function invalidate(reason)
    State.generation = (tonumber(State.generation) or 0) + 1
    State.online, State.character_slot, State.character_label = false, nil, "Refresh required"
    State.cash, State.bank, State.total = nil, nil, nil
    clear_money_baseline(true)
    State.last_money_refresh_ms, State.in_flight, State.transaction_status = -100000, nil, "IDLE"
    State.action_queue = {}
    State.profile_stats,State.profile_pending_verify,State.profile_last_change=nil,nil,nil
    State.recovery_cache = nil
    State.profile_progression_cache = nil
    State.achievement_cache = nil
    State.achievement_bulk = nil
    State.award_reward_cache = nil
    State.derived_award_cache = nil
    State.collectible_cache = nil
    State.career_progress_cache = nil
    State.award_completion = nil
    State.recovery_last_snapshot = nil
    State.tracking_session_id = timestamp_id() .. "-" .. tostring(State.generation)
    State.invalidation_reason = clean(reason or "Session changed", 120)
    invalidate_dependents(State.invalidation_reason)
    update_cached_summary(epoch(), false)
end

Module.Profile.TIME_STATS = {
    freemode = "MPPLY_TOTAL_TIME_SPENT_FREEMODE",
    missions = "MPPLY_TOTAL_TIME_MISSION_CREATO",
    deathmatches = "MPPLY_TOTAL_TIME_SPENT_DEATHMAT",
    races = "MPPLY_TOTAL_TIME_SPENT_RACES",
}

function Module.Profile.playing_time_minutes()
    local hash = stat_hash("MP_PLAYING_TIME")
    if not hash then return nil, "MP_PLAYING_TIME hash unavailable" end
    local ok_d, days = native_try("int", Module.ProfileNative.GET_DAYS, hash)
    local ok_h, hours = native_try("int", Module.ProfileNative.GET_HOURS, hash)
    local ok_m, minutes = native_try("int", Module.ProfileNative.GET_MINUTES, hash)
    if not ok_d or not ok_h or not ok_m then return nil, "MP_PLAYING_TIME components unavailable" end
    return math.max(0, tonumber(days) or 0)*1440 + math.max(0, tonumber(hours) or 0)*60
        + math.max(0, tonumber(minutes) or 0)
end

-- Enhanced source profile: freemode func_16678/12645 updates persistent
-- Mental State float 133, local f_272 and matchmaking band. func_24685 derives
-- K/D from signed INT kills / (deaths + suicides + suicides).
-- Gameplay clamps are not editor limits. The game can later recompute values;
-- immediate and delayed readback decide whether a requested transaction stuck.
Module.Profile.SIGNED_STAT_MIN = -2147483647
Module.Profile.SIGNED_STAT_MAX = 2147483647
Module.Profile.RANGES = {
    rank={1,8000,true}, rp={0,1787576850,true},
    mental_state={-2147483647,2147483647}, kd_ratio={-2147483647,2147483647},
    player_kills={-2147483647,2147483647,true}, player_deaths={-2147483647,2147483647,true},
    player_suicides={-2147483647,2147483647,true}, freemode_minutes={-2147483647,2147483647},
    tracked_total_minutes={-2147483647,2147483647}, freemode_raw={-2147483647,2147483647,true},
    tracked_total_raw={-2147483647,2147483647,true},
    missions_minutes={-2147483647,2147483647},
    deathmatches_minutes={-2147483647,2147483647},
    races_minutes={-2147483647,2147483647},
}
Module.Profile.COUNTERS = {
    player_kills="MPPLY_KILLS_PLAYERS", player_deaths="MPPLY_DEATHS_PLAYER",
    player_suicides="MPPLY_DEATHS_PLAYER_SUICIDE",
}

-- Original AISlop source catalog, preserving its names and MPX semantics.
-- This is data, not an additional script/runtime. Edits use the existing
-- character-scoped transaction, immediate readback and rollback path.
