 function r.Invalidate(reason)
  generation=generation+1;cancel_all(reason or 'Session changed.');observed=nil
  if type(backend.OnSessionChange)=='function'then pcall(backend.OnSessionChange)end
 end
 function r.Stop()active=false;cancel_all('Heist Tools stopped.');observed=nil;return true end
 function r.Tick()return true end -- Account-gated legacy cadence has no command ownership.
 function r.TickApartmentActions()return true end
 function r.RequestVisibleRefresh()return true end
 function r.Refresh()return r.Snapshot()end
 function r.RefreshAll()return r.Snapshot()end
 function r.GetFinishActionResult(f)
  local v=results[f or family];return v and v.action=='finish'and copy(v)or nil
 end
 function r.GetApartmentActionResult()return copy(results.apartment)end
 function r.SelectWorkspace()return true end
 function r.SetAutoDiscovery()return true end
 return r
end
local function host_clock()
 local raw=context_ref and context_ref.Raw or {}
 local time=raw.Time or Time
 if time and type(time.GetEpocheMs)=='function'then return time.GetEpocheMs()end
 return math.floor(os.clock()*1000)
end
function Module.Init(context)
 assert(context and context.CScript and context.Modules and context.State,'Heist Tools context unavailable')
