    ["modules/heist_registry.lua"] = [====[
-- CScript Heist Suite registry.
-- Adapters describe independently classified capabilities. The registry never
-- reads or writes GTA state and therefore remains safe to query from the UI.
local Module = { Name = "modules.heist_registry", MigrationPhase = "17.75" }

local module_context
local public_api
local adapters = {}
local ordered = {}

local SUPPORT = {
    VERIFIED = "VERIFIED",
    EXPERIMENTAL = "EXPERIMENTAL",
    READ_ONLY = "READ_ONLY",
    UNSUPPORTED = "UNSUPPORTED",
}

local MAPPING_CONFIDENCE = {
    LIVE_VERIFIED = true,
    LIVE_BOARD_CORROBORATED = true,
    REFERENCE_CORROBORATED = true,
    EXPERIMENTAL = true,
    RAW_ONLY = true,
    RAW_ONLY_BITFIELD_CANDIDATE = true,
    REJECTED_CURRENT_BUILD = true,
    UNAVAILABLE = true,
}

local DEFAULT_WORKSPACES = { "setup", "launch", "cuts", "utilities", "presets", "advanced" }
local WORKSPACES = { "setup", "loot", "board", "launch", "cuts", "utilities", "presets", "advanced" }
local WORKSPACE_SET = {}
for _, key in ipairs(WORKSPACES) do WORKSPACE_SET[key] = true end

local function valid_support(value)
    for _, support in pairs(SUPPORT) do if value == support then return true end end
    return false
end

local function normalized_keys(value)
    local result, seen = {}, {}
    for _, key in ipairs(type(value) == "table" and value or {}) do
        key = tostring(key or "")
        if key ~= "" and not seen[key] then
            seen[key], result[#result + 1] = true, key
        end
    end
    return result
end

local function append_unique(target, seen, source)
    for _, key in ipairs(source or {}) do
        if not seen[key] then seen[key], target[#target + 1] = true, key end
    end
end

local function register(adapter)
    if type(adapter) ~= "table" then return false, "heist adapter must be a table" end
    local key = tostring(adapter.key or "")
    if key == "" or not key:match("^[%w_]+$") then return false, "heist adapter key is invalid" end
    if adapters[key] then return false, "duplicate heist adapter: " .. key end
    if not valid_support(adapter.support) then return false, "invalid support classification for " .. key end
    if type(adapter.name) ~= "string" or adapter.name == "" then return false, "heist adapter name is required" end
    -- Discovery keys are separate from mutation prerequisites. Adapters
    -- without an explicit discovery list fall back to status_keys.
    adapter.required_status_keys = normalized_keys(adapter.required_status_keys or adapter.status_keys)
    adapter.optional_status_keys = normalized_keys(adapter.optional_status_keys)
    adapter.mutation_prerequisite_keys = normalized_keys(adapter.mutation_prerequisite_keys)
    adapter.diagnostic_keys = normalized_keys(adapter.diagnostic_keys)
    if #adapter.diagnostic_keys == 0 then
        local seen = {}
        append_unique(adapter.diagnostic_keys, seen, adapter.required_status_keys)
        append_unique(adapter.diagnostic_keys, seen, adapter.optional_status_keys)
    end
    adapter.status_keys = {}
    local seen = {}
    append_unique(adapter.status_keys, seen, adapter.required_status_keys)
    append_unique(adapter.status_keys, seen, adapter.optional_status_keys)
    adapter.presets = type(adapter.presets) == "table" and adapter.presets or {}
    adapter.capabilities = type(adapter.capabilities) == "table" and adapter.capabilities or {}
    adapter.field_metadata = type(adapter.field_metadata) == "table" and adapter.field_metadata or {}
    for field_key, metadata in pairs(adapter.field_metadata) do
        if type(field_key) ~= "string" or not field_key:match("^[%w_]+$") or type(metadata) ~= "table" then
            return false, ("invalid field metadata %s.%s"):format(key, tostring(field_key))
        end
        local confidence = tostring(metadata.mapping_confidence or "UNAVAILABLE")
        if not MAPPING_CONFIDENCE[confidence] then
            return false, ("invalid mapping confidence %s.%s=%s"):format(key, field_key, confidence)
        end
        metadata.mapping_confidence = confidence
    end
    adapter.workspaces = type(adapter.workspaces) == "table" and adapter.workspaces or DEFAULT_WORKSPACES
    for _, workspace in ipairs(adapter.workspaces) do
        if not WORKSPACE_SET[workspace] then return false, ("invalid workspace %s.%s"):format(key, tostring(workspace)) end
    end
    for capability, record in pairs(adapter.capabilities) do
        if type(record) ~= "table" or not valid_support(record.support) then
            return false, ("invalid capability classification %s.%s"):format(key, tostring(capability))
        end
    end
    adapters[key] = adapter
    ordered[#ordered + 1] = adapter
    return true
end

local function unregister(key)
    key = tostring(key or "")
    local adapter = adapters[key]
    if not adapter then return false end
    adapters[key] = nil
    for index = #ordered, 1, -1 do
        if ordered[index] == adapter then table.remove(ordered, index) end
    end
    return true
end

local function get(key) return adapters[tostring(key or "")] end
local function list()
    local copy = {}
    for index, adapter in ipairs(ordered) do copy[index] = adapter end
    return copy
end

local function capability(adapter_key, capability_key)
    local adapter = get(adapter_key)
    return adapter and adapter.capabilities[tostring(capability_key or "")] or nil
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.CScript) ~= "table" or type(context.Modules) ~= "table" then
        error("modules.heist_registry requires CScript and Modules services")
    end
    module_context = context
    adapters, ordered = {}, {}
    public_api = {
        Support = SUPPORT,
        Workspaces = WORKSPACES,
        WorkspaceSet = WORKSPACE_SET,
        MappingConfidence = MAPPING_CONFIDENCE,
        Register = register,
        Unregister = unregister,
        Get = get,
        List = list,
        Capability = capability,
        MigrationPhase = Module.MigrationPhase,
    }
    context.Modules.HeistRegistry = Module
    context.CScript.HeistRegistry = public_api
end

function Module.Restore(context)
    context = context or module_context
    if context and context.CScript and context.CScript.HeistRegistry == public_api then context.CScript.HeistRegistry = nil end
    if context and context.Modules and context.Modules.HeistRegistry == Module then context.Modules.HeistRegistry = nil end
    adapters, ordered, module_context, public_api = {}, {}, nil, nil
end

return Module
