    ["modules/heist_research.lua"] = [====[
-- CScript Heist Reference Research service.
--
-- This module is deliberately read-only with respect to GTA. It samples only
-- named stats already classified by a registered heist adapter, waits for a
-- stable before/after transition, and persists evidence outside the runtime.
-- It never promotes a mapping or creates a write surface automatically.
local Module = { Name = "modules.heist_research", MigrationPhase = "17.75" }

local module_context
local public_api
local State
local file_api
local paths
local started = false

local DB_HEADER = "CSCRIPT_HEIST_RESEARCH_DB_V1"
local REPORT_HEADER = "CSCRIPT_HEIST_REFERENCE_OBSERVATION_V1"
local CORRELATION_HEADER = "CSCRIPT_HEIST_RESEARCH_CORRELATION_V1"
local SAMPLE_INTERVAL_MS = 1000
local STABLE_SAMPLES = 3
local MAX_DURATION_MS = 60 * 1000
local MAX_CONSECUTIVE_READ_FAILURES = 5
local MAX_DATABASE_OBSERVATIONS = 512
local FAMILY_KEYS = { "apartment", "cayo", "casino", "doomsday" }
local FAMILY_SET = {}; for _, key in ipairs(FAMILY_KEYS) do FAMILY_SET[key] = true end

local function clean(value, maximum)
    return tostring(value or ""):gsub("[%c]", " "):gsub("^%s+", ""):gsub("%s+$", ""):sub(1, maximum or 160)
end

local function encode(value)
    return tostring(value or ""):gsub("([^%w%._%- ])", function(char) return ("%%%02X"):format(string.byte(char)) end)
end

local function decode(value)
    return tostring(value or ""):gsub("%%(%x%x)", function(hex) return string.char(tonumber(hex, 16)) end)
end

local function canonical(content)
    if type(content) ~= "string" then return nil end
    if content:sub(1, 3) == "\239\187\191" then content = content:sub(4) end
    return content:gsub("\r\n", "\n"):gsub("\r", "\n")
end

local function split(line)
    local result = {}
    for item in (tostring(line or "") .. "|"):gmatch("(.-)|") do result[#result + 1] = decode(item) end
    return result
end

local function now_ms()
    local utils = module_context and module_context.Raw and module_context.Raw.Utils
    if utils and type(utils.GetTime) == "function" then
        local ok, value = pcall(utils.GetTime); if ok and tonumber(value) then return math.floor(value * 1000) end
    end
    return math.floor((os and os.clock and os.clock() or 0) * 1000)
end

local function epoch()
    if os and type(os.time) == "function" then
        local ok, value = pcall(os.time); if ok and tonumber(value) then return math.floor(value) end
