end

local function read(path)
    local present, err = exists(path); if present == nil then return nil, err end
    if not present then return nil, "file does not exist" end
    local ok, content = pcall(file_api.ReadFileContent, path)
    if not ok or type(content) ~= "string" then return nil, tostring(content or "read failed") end
    return canonical(content)
end

local function write_verified(path, content)
    return false, "Technical file logging is disabled."
end

local function family_path(key)
    return paths and paths.families and paths.families[key]
end

local function resolve_paths()
    local ok, err = capture_file_api(); if not ok then return false, err end
    local root_ok, root = pcall(file_api.GetMenuRootPath)
    if not root_ok or type(root) ~= "string" or root == "" then return false, "Cherax menu root is unavailable" end
    root = root:gsub("[\\/]+$", "")
    local data = root .. "\\Lua\\CScriptData"
    local research = data .. "\\Research"
    local heists = research .. "\\Heists"
    for _, directory in ipairs({ data, research, heists }) do
        local made, make_err = ensure(directory); if not made then return false, make_err end
    end
    paths = { root = heists, families = {} }
    for _, key in ipairs(FAMILY_KEYS) do
        local directory = heists .. "\\" .. key:gsub("^%l", string.upper)
        local made, make_err = ensure(directory); if not made then return false, make_err end
        paths.families[key] = {
            root = directory, database = directory .. "\\observations_v1.txt",
            backup = directory .. "\\observations_v1.txt.bak",
            correlation = directory .. "\\correlation_v1.txt",
        }
    end
    State.path = heists
    return true
end

local function new_family_state()
    return { status = "PENDING", error = nil, observations = {}, by_id = {}, correlations = {} }
end

local function refresh_storage_status()
    local ready, empty, unavailable, failures = 0, 0, 0, {}
    for _, family in ipairs(FAMILY_KEYS) do
        local family_state = State.families[family]
        if family_state and family_state.status == "READY" then ready = ready + 1
        elseif family_state and family_state.status == "EMPTY" then empty = empty + 1
        else
            unavailable = unavailable + 1
            failures[#failures + 1] = family .. ":" .. clean(
                family_state and family_state.error or "not initialized", 120)
        end
    end
    if unavailable == 0 then
        State.status, State.error = ready > 0 and "READY" or "EMPTY", nil
    elseif ready + empty > 0 then
        State.status = "PARTIAL"
        State.error = "unavailable family research databases: " .. table.concat(failures, ", ")
    else
        State.status = "ERROR"
        State.error = "family research databases unavailable: " .. table.concat(failures, ", ")
    end
    return ready, empty, unavailable
end

local function observation_id(family, stamp, sequence, reference, feature, changes)
    local parts = { family, tostring(stamp), tostring(sequence), clean(reference, 24), clean(feature, 48) }
    for _, item in ipairs(changes or {}) do
        parts[#parts + 1] = item.key .. "_" .. tostring(item.before) .. "_" .. tostring(item.after)
    end
    return clean(table.concat(parts, "-"), 150):gsub("[^%w_-]", "_")
end

local function serialize_database(family_state)
    local lines = { DB_HEADER }
    for _, observation in ipairs(family_state.observations or {}) do
        lines[#lines + 1] = table.concat({ "observation", encode(observation.id), encode(observation.timestamp),
            encode(observation.runtime_version), encode(observation.build_id), encode(observation.cherax_build),
            encode(observation.reference), encode(observation.feature), encode(observation.before_label),
            encode(observation.after_label), encode(observation.character_slot), encode(observation.generation),
            encode(observation.classification), encode(observation.confidence), encode(observation.notes) }, "|")
        for _, item in ipairs(observation.changes or {}) do
            lines[#lines + 1] = table.concat({ "change", encode(observation.id), encode(item.key),
                encode(item.before), encode(item.after), encode(item.source), encode(item.purpose) }, "|")
        end
        for _, item in ipairs(observation.unchanged or {}) do
            lines[#lines + 1] = table.concat({ "unchanged", encode(observation.id), encode(item.key), encode(item.value) }, "|")
        end
    end
    return table.concat(lines, "\n")
end

local function parse_database(content)
    content = canonical(content)
    if type(content) ~= "string" or content:match("^([^\n]+)") ~= DB_HEADER then return nil, "research database header is invalid" end
    local observations, by_id, first = {}, {}, true
    for line in content:gmatch("[^\n]+") do
        if first then first = false else
            local fields = split(line)
            if fields[1] == "observation" then
                local item = {
                    id = clean(fields[2], 150), timestamp = tonumber(fields[3]) or 0,
                    runtime_version = clean(fields[4], 64), build_id = clean(fields[5], 128), cherax_build = clean(fields[6], 80),
                    reference = clean(fields[7], 40), feature = clean(fields[8], 96), before_label = clean(fields[9], 96),
                    after_label = clean(fields[10], 96), character_slot = tonumber(fields[11]), generation = tonumber(fields[12]),
                    classification = clean(fields[13], 40), confidence = clean(fields[14], 40), notes = clean(fields[15], 220),
                    changes = {}, unchanged = {},
                }
                if item.id == "" or by_id[item.id] then return nil, "research observation record is invalid" end
                by_id[item.id] = item; observations[#observations + 1] = item
            elseif fields[1] == "change" then
                local item, before, after = by_id[fields[2]], tonumber(fields[4]), tonumber(fields[5])
                if not item or not fields[3]:match("^[%w_]+$") or before == nil or after == nil then
                    return nil, "research change record is invalid"
                end
                item.changes[#item.changes + 1] = { key = fields[3], before = before, after = after,
                    source = clean(fields[6], 120), purpose = clean(fields[7], 120) }
            elseif fields[1] == "unchanged" then
                local item, value = by_id[fields[2]], tonumber(fields[4])
                if not item or not fields[3]:match("^[%w_]+$") or value == nil then return nil, "research unchanged record is invalid" end
                item.unchanged[#item.unchanged + 1] = { key = fields[3], value = value }
            else return nil, "unknown research database record" end
        end
    end
    return observations
end

local function rebuild_correlations(family_state)
    local correlations = {}
    for _, observation in ipairs(family_state.observations or {}) do
        for _, change in ipairs(observation.changes or {}) do
            local key = table.concat({ observation.feature, change.key, tostring(change.before), tostring(change.after) }, "|")
            local item = correlations[key] or { feature = observation.feature, key = change.key, before = change.before,
                after = change.after, occurrences = 0, references = {}, labels = {} }
            correlations[key] = item
            item.occurrences = item.occurrences + 1
            item.references[observation.reference] = true
            item.labels[(observation.before_label or "") .. " -> " .. (observation.after_label or "")] = true
        end
    end
    for _, item in pairs(correlations) do
        local reference_count = 0; for _ in pairs(item.references) do reference_count = reference_count + 1 end
        item.reference_count = reference_count
        item.suggestion = reference_count >= 2 and "MULTI_REFERENCE_CORROBORATED"
            or item.occurrences >= 2 and "REPEATED_OBSERVATION" or "SINGLE_OBSERVATION"
    end
    family_state.correlations = correlations
end

local function serialize_correlations(family, family_state)
    local diagnostics = module_context and module_context.CScript and module_context.CScript.Diagnostics or {}
    local lines = { CORRELATION_HEADER, "family=" .. family,
        "runtime=" .. tostring(diagnostics.LoaderVersion or "17.75"),
        "build=" .. tostring(diagnostics.BuildId or "Unavailable"), "automatic_mapping_promotion=false" }
    local keys = sorted_keys(family_state.correlations)
    for _, key in ipairs(keys) do
        local item = family_state.correlations[key]
        local references = {}; for value in pairs(item.references or {}) do references[#references + 1] = value end; table.sort(references)
        local labels = {}; for value in pairs(item.labels or {}) do labels[#labels + 1] = value end; table.sort(labels)
        lines[#lines + 1] = table.concat({ "correlation", encode(item.feature), encode(item.key), encode(item.before),
            encode(item.after), encode(item.occurrences), encode(item.reference_count), encode(item.suggestion),
            encode(table.concat(references, ",")), encode(table.concat(labels, "; ")) }, "|")
    end
    return table.concat(lines, "\n")
end

local function save_family(family)
    local family_state, family_paths = State.families[family], family_path(family)
    if not family_state or (family_state.status ~= "READY" and family_state.status ~= "EMPTY") or not family_paths then
        return false, "research database is not ready"
    end
    local content = serialize_database(family_state)
    if exists(family_paths.database) == true then
        local previous = read(family_paths.database)
        if type(previous) == "string" and parse_database(previous) then
            local backup_ok, backup_err = write_verified(family_paths.backup, previous)
            if not backup_ok then return false, "research backup failed: " .. tostring(backup_err) end
        end
    end
    local ok, err = write_verified(family_paths.database, content); if not ok then return false, err end
    rebuild_correlations(family_state)
    local correlation_ok, correlation_err = write_verified(family_paths.correlation, serialize_correlations(family, family_state))
    if not correlation_ok then return false, "correlation write failed: " .. tostring(correlation_err) end
    family_state.status, family_state.error = #family_state.observations > 0 and "READY" or "EMPTY", nil
    refresh_storage_status()
    return true
end

local function load_family(family)
    local family_state, family_paths = State.families[family], family_path(family)
    if not family_paths then family_state.status, family_state.error = "DEGRADED", "research path unavailable"; return false end
    local present, exists_err = exists(family_paths.database)
    if present == nil then family_state.status, family_state.error = "DEGRADED", exists_err; return false end
    local observations, parse_err
    if present then observations, parse_err = parse_database(read(family_paths.database))
    else observations = {} end
    if not observations and exists(family_paths.backup) == true then observations, parse_err = parse_database(read(family_paths.backup)) end
    if not observations then family_state.status, family_state.error = "DEGRADED", parse_err; return false end
    if #observations > MAX_DATABASE_OBSERVATIONS then
        local trimmed = {}; for index = #observations - MAX_DATABASE_OBSERVATIONS + 1, #observations do trimmed[#trimmed + 1] = observations[index] end
        observations = trimmed
    end
    family_state.observations, family_state.by_id = observations, {}
    for _, item in ipairs(observations) do family_state.by_id[item.id] = true end
    family_state.status, family_state.error = #observations > 0 and "READY" or "EMPTY", nil
    rebuild_correlations(family_state)
    if not present then
        local ok, err = save_family(family); if not ok then family_state.status, family_state.error = "DEGRADED", err; return false end
    else
        write_verified(family_paths.correlation, serialize_correlations(family, family_state))
    end
    return true
end

local function candidate_list(adapter)
    local result, seen = {}, {}
    for _, candidate in ipairs(adapter and adapter.reference_candidates or {}) do
        local key = type(candidate) == "table" and tostring(candidate.key or "") or tostring(candidate or "")
        if key:match("^[%w_]+$") and not seen[key] then
            seen[key] = true
            result[#result + 1] = { key = key,
                source = clean(type(candidate) == "table" and candidate.source or "classified adapter state", 120),
                purpose = clean(type(candidate) == "table" and candidate.purpose or "mapping research", 120) }
        end
    end
    return result
end

local function read_values(session, keys)
    local core = economy(); if not core then return nil, { { key = "runtime", error = "Economy core unavailable" } } end
    local values, failures = {}, {}
    for _, key in ipairs(keys or {}) do
        local qualified = session.metadata[key] and session.metadata[key].qualified or core.QualifyStat(session.character_slot, key)
        trace_api("STAT_GET_INT")
        local value, err = core.ReadStat(qualified)
        if value == nil then failures[#failures + 1] = { key = key, status = "REJECTED_CURRENT_BUILD", error = tostring(err) }
        else values[key] = value end
    end
    return values, failures
end

local function change_list(session, before, after)
    local changed, unchanged = {}, {}
    for _, key in ipairs(session.tracked_keys or {}) do
        if before[key] ~= after[key] then
            local meta = session.metadata[key] or {}
            changed[#changed + 1] = { key = key, before = before[key], after = after[key], source = meta.source, purpose = meta.purpose }
        else unchanged[#unchanged + 1] = { key = key, value = after[key] } end
    end
    return changed, unchanged
end

local function build_report(session, observation)
    local diagnostics = module_context and module_context.CScript and module_context.CScript.Diagnostics or {}
    local lines = { REPORT_HEADER,
        "runtime=" .. tostring(diagnostics.LoaderVersion or "17.75"),
        "build=" .. tostring(diagnostics.BuildId or "Unavailable"),
        "cherax=" .. tostring(session.cherax_build or "Cherax v5.48.1 EE BE b10713"),
        "family=" .. session.family, "reference=" .. session.reference, "feature=" .. session.feature,
        "before_label=" .. session.before_label, "after_label=" .. session.after_label,
        "timestamp=" .. tostring(observation.timestamp), "character=" .. tostring(session.character_slot),
        "generation=" .. tostring(session.generation), "classification=" .. observation.classification,
        "confidence=" .. observation.confidence, "read_only=true", "automatic_mapping_promotion=false",
        "reference_runtime_dependency=NONE", "notes=" .. session.notes, "", "[changes]" }
    for _, item in ipairs(observation.changes) do
        lines[#lines + 1] = table.concat({ item.key, tostring(item.before), tostring(item.after),
            clean(item.purpose, 120), clean(item.source, 120) }, "|")
    end
    lines[#lines + 1] = ""; lines[#lines + 1] = "[unchanged]"
    for _, item in ipairs(observation.unchanged) do lines[#lines + 1] = item.key .. "|" .. tostring(item.value) end
    lines[#lines + 1] = ""; lines[#lines + 1] = "[excluded]"
    for _, item in ipairs(session.excluded or {}) do lines[#lines + 1] = item.key .. "|" .. item.status .. "|" .. clean(item.error, 180) end
    lines[#lines + 1] = ""; lines[#lines + 1] = "decision=RESEARCH_ONLY; human board/reference corroboration is required before promotion."
    return table.concat(lines, "\n")
end

local function end_session(status, reason, silent)
    local session = State.session
    if type(session) ~= "table" or not session.active then return false, "no reference research session is active" end
    session.active, session.status, session.stop_reason, session.finished_at = false, status, clean(reason, 220), epoch()
    if not silent then notify(status == "CAPTURED" and "Success" or "Warning", reason) end
    log("Info", ("Reference research stopped family=%s status=%s samples=%d path=%s reason=%s"):format(
        tostring(session.family), tostring(status), tonumber(session.samples_taken) or 0,
        tostring(session.path or "Unavailable"), tostring(session.stop_reason)))
    return true, session.path or session.stop_reason
end

local function capture_observation(session, changes, unchanged)
    local stamp = epoch()
    State.sequence = (tonumber(State.sequence) or 0) + 1
    local diagnostics = module_context and module_context.CScript and module_context.CScript.Diagnostics or {}
    local family_state = State.families[session.family]
    local id = observation_id(session.family, stamp, State.sequence, session.reference, session.feature, changes)
    while family_state.by_id[id] do
        State.sequence = State.sequence + 1
        id = observation_id(session.family, stamp, State.sequence, session.reference, session.feature, changes)
    end
    local observation = {
        id = id, sequence = State.sequence, timestamp = stamp,
        runtime_version = tostring(diagnostics.LoaderVersion or "17.75"),
        build_id = tostring(diagnostics.BuildId or "Unavailable"),
        cherax_build = session.cherax_build, reference = session.reference, feature = session.feature,
        before_label = session.before_label, after_label = session.after_label,
        character_slot = session.character_slot, generation = session.generation,
        classification = #changes == 1 and "ISOLATED_OBSERVATION" or "COMPOUND_OBSERVATION",
        confidence = #changes == 1 and "SINGLE_OBSERVATION" or "COMPOUND_RESEARCH_ONLY",
        notes = session.notes, changes = copy_changes(changes), unchanged = unchanged,
    }
    family_state.observations[#family_state.observations + 1] = observation
    family_state.by_id[observation.id] = true
    while #family_state.observations > MAX_DATABASE_OBSERVATIONS do
        local removed = table.remove(family_state.observations, 1); family_state.by_id[removed.id] = nil
    end
    local saved, save_err = save_family(session.family)
    if not saved then
        table.remove(family_state.observations); family_state.by_id[observation.id] = nil
        return false, save_err
    end
    local family_paths = family_path(session.family)
    local report_path = family_paths.root .. "\\observation-" .. timestamp(stamp) .. "-" .. tostring(State.sequence) .. ".txt"
    local report_ok, report_err = write_verified(report_path, build_report(session, observation))
    if not report_ok then return false, report_err end
    session.last_observation, session.path = observation, report_path
    return true, report_path
end

local function start_session(family, generation, spec)
    family, spec = tostring(family or ""), type(spec) == "table" and spec or {}
    if not started or State.status == "ERROR" then return false, State.error or "Heist research storage is not ready" end
    if not FAMILY_SET[family] then return false, "research is limited to the four supported heist families" end
    if State.session and State.session.active then return false, "a reference research session is already active" end
    local family_state = State.families[family]
    if not family_state or (family_state.status ~= "READY" and family_state.status ~= "EMPTY") then
        return false, family_state and family_state.error or "family research database unavailable"
    end
    local adapter = registry() and registry().Get(family)
    local candidates = candidate_list(adapter)
    if #candidates == 0 then return false, "no evidence-sourced candidates are classified for this heist" end
    local reference = clean(spec.reference, 32)
    if reference ~= "Silent Night" and reference ~= "Codax" and reference ~= "Other" then return false, "select Silent Night, Codax, or Other" end
    local feature, before_label, after_label = clean(spec.feature, 96), clean(spec.before_label, 96), clean(spec.after_label, 96)
    if feature == "" or before_label == "" or after_label == "" then return false, "feature, before label, and after label are required" end
    local core = economy(); if not core then return false, "Economy core is unavailable" end
    local slot, slot_err = core.CurrentSlot(); if slot == nil then return false, clean(slot_err, 180) end
    local metadata = {}
    for _, candidate in ipairs(candidates) do metadata[candidate.key] = {
        source = candidate.source, purpose = candidate.purpose, qualified = core.QualifyStat(slot, candidate.key) }
    end
    local current_ms = now_ms()
    State.session = {
        active = true, status = "ARMING_BASELINE", family = family, generation = tonumber(generation) or 0,
        character_slot = slot, reference = reference, feature = feature, before_label = before_label,
        after_label = after_label, notes = clean(spec.notes, 220), cherax_build = clean(spec.cherax_build, 80),
        candidates = candidates, metadata = metadata, tracked_keys = {}, excluded = {}, samples_taken = 0,
        started_at = epoch(), started_ms = current_ms, deadline_ms = current_ms + MAX_DURATION_MS,
        next_sample_ms = current_ms, pending_signature = nil, pending_values = nil, pending_streak = 0,
        consecutive_read_failures = 0,
    }
    if State.session.cherax_build == "" then State.session.cherax_build = "Cherax v5.48.1 EE BE b10713" end
    log("Info", ("Reference research started family=%s reference=%s feature=%s candidates=%d generation=%d slot=%d"):format(
        family, reference, feature, #candidates, State.session.generation, slot))
    notify("Info", "Research started. Wait for Baseline Ready, then change the single labeled reference option.")
    return true
end

local function tick(generation)
    local session = State.session
    if not started or type(session) ~= "table" or not session.active then return end
    local current_ms = now_ms(); if current_ms < (session.next_sample_ms or 0) then return end
    session.next_sample_ms = current_ms + SAMPLE_INTERVAL_MS
    if tonumber(generation) ~= session.generation then end_session("ABORTED_CONTEXT_CHANGE", "Research stopped because the heist context changed.", false); return end
    if current_ms >= session.deadline_ms then end_session("COMPLETE_TIMEOUT", "No stable labeled change was captured within 60 seconds.", false); return end
    local core = economy(); if not core then end_session("FAILED_RUNTIME", "Economy read service became unavailable.", false); return end
    local slot = core.CurrentSlot(); if slot == nil or slot ~= session.character_slot then
        end_session("ABORTED_CHARACTER_CHANGE", "Research stopped because the GTA character changed.", false); return
    end
    local keys = session.initial_read_complete and session.tracked_keys or (function()
        local result = {}; for _, candidate in ipairs(session.candidates) do result[#result + 1] = candidate.key end; return result
    end)()
    local values, failures = read_values(session, keys)
    session.samples_taken = session.samples_taken + 1
    if not session.initial_read_complete then
        session.initial_read_complete, session.excluded, session.tracked_keys = true, failures, sorted_keys(values)
        if #session.tracked_keys == 0 then end_session("FAILED_NO_READABLE_CANDIDATES", "Every classified candidate was rejected on this build.", false); return end
    elseif #failures > 0 then
        session.consecutive_read_failures = session.consecutive_read_failures + 1
        session.status, session.last_read_failures = "READ_RETRY", failures
        if session.consecutive_read_failures >= MAX_CONSECUTIVE_READ_FAILURES then
            end_session("FAILED_READ_STABILITY", "Five consecutive samples contained rejected reads.", false)
        end
        return
    end
    session.consecutive_read_failures, session.last_read_failures = 0, nil
    local current_signature = signature(values, session.tracked_keys)
    if not session.baseline then
        if session.pending_signature == current_signature then session.pending_streak = session.pending_streak + 1
        else session.pending_signature, session.pending_values, session.pending_streak = current_signature, copy_values(values), 1 end
        if session.pending_streak >= STABLE_SAMPLES then
            session.baseline, session.accepted_values, session.accepted_signature = copy_values(values), copy_values(values), current_signature
            session.pending_signature, session.pending_values, session.pending_streak = nil, nil, 0
            session.status, session.baseline_at = "WATCHING", epoch()
            notify("Success", "Baseline Ready. Change the one labeled reference option now.")
        end
        return
    end
    if current_signature == session.accepted_signature then
        session.pending_signature, session.pending_values, session.pending_streak, session.status = nil, nil, 0, "WATCHING"
        return
    end
    if session.pending_signature == current_signature then session.pending_streak = session.pending_streak + 1
    else session.pending_signature, session.pending_values, session.pending_streak = current_signature, copy_values(values), 1 end
    session.status = "STABILIZING_CHANGE"
    if session.pending_streak < STABLE_SAMPLES then return end
    local changes, unchanged = change_list(session, session.accepted_values, session.pending_values)
    if #changes == 0 then return end
    local ok, result = capture_observation(session, changes, unchanged)
    if not ok then end_session("EXPORT_FAILED", "Stable change found, but the verified evidence write failed: " .. clean(result, 160), false); return end
    local label = #changes == 1 and "isolated change" or (tostring(#changes) .. "-field compound change")
    end_session("CAPTURED", "Research captured one " .. label .. " and saved a verified report.", false)
end

local function invalidate(reason)
    if State.session and State.session.active then end_session("ABORTED_CONTEXT_CHANGE", clean(reason or "Session changed", 160), false) end
end

local function clear_result()
    if State.session and State.session.active then return false, "stop the active research session first" end
    State.session = nil; return true
end

local function snapshot(family_key)
    local session = State.session
    local family = FAMILY_SET[tostring(family_key or "")] and tostring(family_key) or session and session.family
    local family_state = family and State.families[family]
    local correlation_count = 0
    for _ in pairs(family_state and family_state.correlations or {}) do correlation_count = correlation_count + 1 end
    return {
        status = session and session.status or "IDLE", active = session and session.active == true or false,
        family = family, path = session and session.path, root_path = State.path,
        reference = session and session.reference, feature = session and session.feature,
        before_label = session and session.before_label, after_label = session and session.after_label,
        tracked_keys = session and session.tracked_keys or {}, excluded = session and session.excluded or {},
        samples_taken = session and session.samples_taken or 0, pending_streak = session and session.pending_streak or 0,
        last_observation = session and session.last_observation, checkpoint_error = session and session.checkpoint_error,
        database_count = family_state and #(family_state.observations or {}) or 0,
        correlation_count = correlation_count, storage_status = State.status, storage_error = State.error,
        max_duration_ms = MAX_DURATION_MS, sample_interval_ms = SAMPLE_INTERVAL_MS,
        stable_samples = STABLE_SAMPLES, automatic_mapping_promotion = false,
    }
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table" or type(context.CScript) ~= "table"
        or type(context.CScript.Economy) ~= "table" or type(context.CScript.HeistRegistry) ~= "table" then
        error("modules.heist_research requires Economy and HeistRegistry")
    end
    module_context = context
    State = context.State.HeistResearch or {}; context.State.HeistResearch = State
    State.status, State.error, State.path, State.session, State.sequence = "PENDING", nil, nil, nil, 0
    State.families = {}; for _, key in ipairs(FAMILY_KEYS) do State.families[key] = new_family_state() end
    public_api = { Start = start_session, Stop = function() return end_session("COMPLETE_USER_STOP", "Research stopped by user.", false) end,
        Clear = clear_result, Tick = tick, Invalidate = invalidate, Snapshot = snapshot,
        MigrationPhase = Module.MigrationPhase }
    context.Modules.HeistResearch = Module
    context.CScript.HeistResearch = public_api
end

function Module.Start()
    local ok, err = resolve_paths()
    local ready, empty, unavailable = 0, 0, #FAMILY_KEYS
    if ok then
        for _, family in ipairs(FAMILY_KEYS) do load_family(family) end
        ready, empty, unavailable = refresh_storage_status()
    else State.status, State.error = "ERROR", err end
    started = true
    local level = (State.status == "READY" or State.status == "EMPTY") and "Info"
        or State.status == "PARTIAL" and "Warning" or "Error"
    log(level, ("Research persistence stage=START path=%s status=%s ready=%d empty=%d unavailable=%d error=%s"):format(
        tostring(State.path or "Unavailable"), tostring(State.status), ready, empty, unavailable,
        tostring(State.error or "None")))
end

function Module.Stop()
    if State and State.session and State.session.active then end_session("ABORTED_UNLOAD", "Research stopped because CScript is unloading.", true) end
    started = false
end

function Module.Restore(context)
    context = context or module_context
    started = false
    if context and context.CScript and context.CScript.HeistResearch == public_api then context.CScript.HeistResearch = nil end
    if context and context.Modules and context.Modules.HeistResearch == Module then context.Modules.HeistResearch = nil end
    if context and context.State then context.State.HeistResearch = {} end
