local CasinoBoardCuts=(function()
local TITLE='Casino Board Cuts'
local ROOT=1973762+1497+736
local ROSTER=ROOT+87+1
local CUTS=ROOT+92+1
local HOST=1973762+4356
local ACTIVE_SCRIPT=Utils.Joaat('gb_casino_heist_planning')
local running=false
local mode='host'
local applied_key=nil
local last_status=''
local last_poll=0

local function log(message)
 if Logger and Logger.LogInfo then
  pcall(Logger.LogInfo,'['..TITLE..' v2] '..tostring(message))
 end
end
local function say(message)
 log(message)
 if GUI and GUI.AddToast and eToastPos then
  pcall(GUI.AddToast,TITLE,tostring(message),5500,eToastPos.TOP_RIGHT)
 end
end
local function integer(v)
 return type(v)=='number' and v%1==0 and v>=-2147483648 and v<=2147483647
end
local function global(index)
 local v=ScriptGlobal.GetInt(index)
 assert(integer(v),'Unreadable casino board global '..tostring(index))
 return v
end
local function native_int(hash,...)
 local v=Natives.InvokeInt(hash,...)
 assert(integer(v),'Native integer unavailable.')
 return v
end
local function observe()
 assert(ScriptGlobal.AreValid()==true,'Script globals are not ready.')
 assert(Natives.InvokeBool(0xD83C2B94E7508980)==true,'Join GTA Online.')
 assert(native_int(0x2C83A9DA6BFFC4F9,ACTIVE_SCRIPT)==1,
  'Open the Casino finale planning board first.')
 assert(native_int(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller'))==0,
  'Already inside a mission; board writes are disabled.')
 assert(native_int(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller_2020'))==0,
  'Already inside a mission; board writes are disabled.')
 local pid=native_int(0x4F8644AF03D0E0D6)
 assert(pid>=0 and pid<=31,'Invalid local player.')
 assert(global(HOST)==pid,'This Casino board is not owned by the local player.')
 local count=global(ROOT+85)
 assert(count>=1 and count<=4,'Casino cut board has no valid crew.')
 local slots,seen,host_slot={}, {},nil
 for i=0,3 do
  local player=global(ROSTER+i)
  local cut=global(CUTS+i)
  assert(cut>=0 and cut<=999,'Casino cut slot is invalid.')
  if i<count then
   assert(player>=0 and player<=31 and not seen[player],
    'Casino cut roster has not stabilized.')
   seen[player]=true
   if player==pid then host_slot=i end
  end
  slots[#slots+1]={slot=i,player=player,cut=cut}
 end
 assert(host_slot~=nil,'Casino host is not in the planning roster.')
 local key=table.concat({pid,count,host_slot,slots[1].player,slots[2].player,
  slots[3].player,slots[4].player},':')
 return {pid=pid,count=count,host_slot=host_slot,slots=slots,key=key}
end
local function target_cuts(c)
 local result={}
 for i=0,3 do
  if i>=c.count then
   result[i+1]=0
  elseif mode=='equal' then
   local minimum=100//c.count
   result[i+1]=minimum+(i<100%c.count and 1 or 0)
  else
   -- Casino's board contract requires a 100% sum, not 100% for each member.
   result[i+1]=i==c.host_slot and 100-15*(c.count-1) or 15
  end
 end
 local total=0
 for _,v in ipairs(result)do total=total+v end
 assert(total==100,'Cut calculation failed validation.')
 return result
end
local function apply()
 local c=observe()
 local target=target_cuts(c)
 local different=false
 for i=0,3 do
  if c.slots[i+1].cut~=target[i+1] then different=true end
 end
 if not different then
  applied_key=c.key..':'..mode
  return 'Casino cuts already match '..mode..' mode.'
 end
 local fresh=observe()
 assert(fresh.key==c.key,'Casino crew changed before write.')
 for i=0,3 do
  assert(fresh.slots[i+1].cut==c.slots[i+1].cut,
   'Casino cuts changed externally before write.')
 end
 -- Host-owned shared planning structure: source gb_casino_heist_planning.c
 -- uParam0->f_1497.f_736.f_92[slot]. The game's owner loop propagates
 -- changes into Global_1978125[host].f_12[slot] and the own consumed cut.
 local attempted={}
 local ok,err=pcall(function()
  for i=0,3 do
   if c.slots[i+1].cut~=target[i+1] then
    attempted[#attempted+1]={index=CUTS+i,old=c.slots[i+1].cut,new=target[i+1]}
    ScriptGlobal.SetInt(CUTS+i,target[i+1])
    assert(global(CUTS+i)==target[i+1],'Casino board cut readback rejected.')
   end
  end
 end)
 if not ok then
  for i=#attempted,1,-1 do
   local a=attempted[i]
   pcall(function() if global(a.index)==a.new then ScriptGlobal.SetInt(a.index,a.old)end end)
  end
  error('Casino cut update failed; matching entries were restored: '..tostring(err))
 end
 applied_key=c.key..':'..mode
 local labels={}
 for i=0,c.count-1 do
  labels[#labels+1]='P'..(i+1)..'='..target[i+1]..'%'
 end
 log('BOARD_CUTS_STAGED host='..c.pid..' roster='..c.key..' cuts='..table.concat(labels,',')
  ..' | payment not confirmed | waiting for game script synchronization')
 return 'Casino cuts staged: '..table.concat(labels,', ')..'. Launch after the board updates.'
end
local function status()
 local ok,c=pcall(observe)
 if not ok then return 'Board unavailable: '..tostring(c)end
 local cuts={}
 for i=0,c.count-1 do
  cuts[#cuts+1]='P'..(i+1)..' '..c.slots[i+1].player..'='..c.slots[i+1].cut..'%'
 end
 local msg='Board host='..c.pid..' count='..c.count
  ..' cuts=['..table.concat(cuts,', ')..'] desired='..mode
 log(msg)
 return msg
end
local function set_mode(value)
 if value~='host' and value~='equal'then return false,'Unsupported Casino board mode.'end
 mode=value;applied_key=nil
 return true,'Casino board mode: '..value
end
return {Apply=apply,Observe=observe,Status=status,SetMode=set_mode,
 Reset=function()applied_key=nil;last_poll=0;last_status=''end}
end)()

local MaxPayout=(function()
-- Own-host payout prototype. Targets are configured limits, not verified server caps.
local TARGETS={cayo=2550000,casino=3600000,doomsday=2550000}
local CUT_GLOBAL=2692926 -- Global_2686124.f_6802: local player's consumed percentage.
local function finite(v)return type(v)=='number' and v==v and v>-math.huge and v<math.huge end
local function int(v,low,high)return finite(v) and v%1==0 and v>=(low or -2147483648) and v<=(high or 2147483647)end
local function f(v)return (string.unpack('f',string.pack('f',v)))end
local function mul(a,b)return f(f(a)*f(b))end
local function round(v)return math.floor(f(v)+0.5)end
local function estimate(r,cut)
 local function bounded(v)
  if not finite(v) or v<0 or v>2147483647 then return math.huge end
  local n=round(v);return int(n,0,2147483647) and n or math.huge
 end
 local v=bounded(mul(mul(r.pool,f(f(cut)/f(100))),r.cut_multiplier))
 if v==math.huge then return v end
 for _,factor in ipairs(r.settlement)do v=bounded(mul(v,factor));if v==math.huge then return v end end
 if r.ceiling>0 then v=math.min(v,round(r.ceiling))end
 if r.floor>0 then v=math.max(v,round(r.floor))end
 if r.quantum==10 then v=round(f(f(v)/f(10)))*10 end
 return int(v,0,2147483647) and v or math.huge
end
local function calculate(r,target)
 if type(r)~='table' or not TARGETS[r.family] or not int(target,1,TARGETS[r.family])then return nil,'Unknown family or target.'end
 if not finite(r.pool) or r.pool<=0 or r.pool>2147483647 or not finite(r.cut_multiplier) or r.cut_multiplier<=0 or r.cut_multiplier>100 then return nil,'No positive supported finale take is available.'end
 if type(r.settlement)~='table' or #r.settlement~=2 or not finite(r.floor) or r.floor<0 or not finite(r.ceiling) or r.ceiling<0 or (r.quantum~=1 and r.quantum~=10)then return nil,'Settlement inputs are unavailable.'end
 for _,v in ipairs(r.settlement)do if not finite(v) or v<=0 or v>100 then return nil,'Invalid settlement multiplier.'end end
 local lo,hi=0,999
 while lo<hi do local mid=(lo+hi+1)//2;if estimate(r,mid)<=target then lo=mid else hi=mid-1 end end
 if lo==0 or estimate(r,lo)<=0 then return nil,'No nonzero whole percentage fits the target.'end
 local amount=estimate(r,lo)
 if not int(amount,1,target)then return nil,'The observed client floor exceeds the target.'end
 -- A client ceiling may create a plateau. Avoid inflating the cut unnecessarily.
 local top=lo;lo,hi=1,top
 while lo<hi do local mid=(lo+hi)//2;if estimate(r,mid)>=amount then hi=mid else lo=mid+1 end end
 return {cut=lo,amount=amount,target=target,family=r.family,reward=r,server_cap_verified=false}
end
local function new_controller(h)
 local enabled,pending,blocked,blocked_owner,last=false,nil,nil,nil,-1
 local api={}
 local function restore(reason)
  local t=pending;if not t then return true end
  local ok,value=pcall(function()
   if not h.same_owner(t.ctx.owner_key)then return nil end
   if h.current_cut then return h.current_cut(t.ctx.owner_key)end
   local c=h.read();return c.cut
  end)
  if not ok or value==nil then pending=nil;h.log('RESTORE_SKIPPED changed/unavailable owned target | '..reason);return false end
  if value~=t.applied and value~=t.before and not (t.allow_previous and value==t.previous_value)then pending=nil;h.log('RESTORE_SKIPPED external edit | '..reason);return false end
  if value~=t.before then
   local wrote,accepted=pcall(h.write,t.before,t.ctx,value,nil,true)
   if not wrote or accepted~=true then h.log('RESTORE_FAILED | '..reason);return false end
  end
  pending=nil;h.log('RESTORED host percentage | '..reason);return true
 end
 function api.Enable(value)
  enabled=value==true;last=-1
  if enabled then blocked=nil;blocked_owner=nil;return true end
  blocked=nil;blocked_owner=nil;return restore('disabled/unload')
 end
 function api.Tick(force)
  if not enabled then return nil end
  local now=h.now();if not int(now,0,9007199254740991)then return {ok=false,message='Clock unavailable.'}end
  if not force and last>=0 and now>=last and now-last<50 then return nil end;last=now
  -- A failure may stay latched during one finale, but must not poison the next
  -- finale. This was leaving Cayo disabled after testing Casino/Doomsday.
  if blocked then
   local ok_ctx,ctx=pcall(function()return h.context and h.context(true)end)
   if ok_ctx and type(ctx)=='table' and ctx.phase=='active'
       and blocked_owner and ctx.owner_key~=blocked_owner then
    h.log('AUTO_REARM | old finish context ended; inspecting new finale')
    blocked=nil;blocked_owner=nil;pending=nil
   else
    return {ok=false,message=blocked}
   end
  end
  local ok,c,r=pcall(h.read)
  if not ok or type(c)~='table' or type(r)~='table'then
   if pending then
    restore('context unavailable')
    h.log('FINALE_ENDED | old own-cut context released; Max Payout stays armed')
   end
   return {ok=false,message='Waiting: '..tostring(ok and r or c)}
  end
  if pending and c.owner_key~=pending.ctx.owner_key then
   -- Old snapshots must never be replayed into a different mission.
   restore('controller/account changed')
   pending=nil
   h.log('AUTO_REARM | finale owner changed; next payout may be calculated')
  end
  if pending and c.roster_key~=pending.ctx.roster_key then
   restore('roster changed');blocked='Crew changed during this finale. Toggle off and on.'
   blocked_owner=c.owner_key;return {ok=false,message=blocked}
  end
  if pending and c.cut~=pending.applied then
   restore('external edit');blocked='Percentage changed elsewhere. Toggle off and on.'
   blocked_owner=c.owner_key;return {ok=false,message=blocked}
  end
  if c.phase=='settling' then
   -- The consumer reads the percentage during result processing. Do not undo
   -- an owned active adjustment merely because the active-objectives gate ends.
   return {ok=pending~=nil,message=pending and 'Result processing: retaining own percentage; payment unconfirmed.' or 'Waiting for active finale objectives.'}
  end
  if c.phase=='failed'then
   restore('failed finale');blocked='Finale failed. Awaiting a new finale or toggle off/on.'
   blocked_owner=c.owner_key;return {ok=false,message=blocked}
  end
  local p,why=calculate(r,TARGETS[c.family]);if not p then
   if pending then
    restore('reward became invalid');blocked=why;blocked_owner=c.owner_key
   end
   return {ok=false,message=why}
  end
  if pending and c.cut==p.cut then return {ok=true,message='Own payout estimate $'..p.amount,plan=p}end
  local previous=pending
  local tx={ctx={owner_key=c.owner_key,roster_key=c.roster_key,key=c.key,family=c.family},before=previous and previous.before or c.cut,applied=p.cut,previous_value=c.cut,allow_previous=true}
  -- Install before attempting a write so failure-after-write can roll back.
  pending=tx
  local ran,accepted=pcall(h.write,p.cut,c,c.cut,r,false)
  if not ran or accepted~=true then
   restore('apply failed');blocked='Payout write rejected. Toggle off and on.'
   blocked_owner=c.owner_key;return {ok=false,message=blocked}
  end
  tx.allow_previous=false
  h.log('MAX_PAYOUT_PLAN | family='..c.family..' | pool='..r.pool..' | cut='..p.cut..' | estimate='..p.amount..' | configured_target='..p.target..' | backend_cap_verified=false | payment_confirmed=false')
  return {ok=true,message='Own payout estimate $'..p.amount,plan=p}
 end
 function api.Unload()enabled=false;return restore('unload')end
 function api.Invalidate(reason)pending=nil;blocked=nil;blocked_owner=nil;last=-1;h.log('INVALIDATED old payout ownership | '..tostring(reason))end
 function api.Pending()return pending end
 return api
end

local function read_reward(c,a)
 local ok,result=pcall(function()
  local observations={}
  local function read(kind,index)
   local value=a[kind](index)
   assert(finite(value) and (kind=='gf' or int(value)),'Unreadable reward input '..kind..':'..index)
   observations[#observations+1]={kind=kind,index=index,value=value};return value
  end
  local function gi(i)return read('gi',i)end
  local function li(i)return read('li',i)end
  local function ti(i)return gi(262145+i)end
  local function tf(i)return read('gf',262145+i)end
  local function positive(v,why)assert(finite(v) and v>0 and v<=2147483647,why or 'Invalid positive take.');return v end
  local function factor(v)assert(finite(v) and v>0 and v<=100,'Invalid reward multiplier.');return v end
  local function eqhash(a,b)return a%4294967296==b%4294967296 end
  local function in_array(offset,count)
   local found=false
   for n=0,count-1 do local value=ti(offset+1+n);if value~=0 and eqhash(value,c.mission)then found=true end end
   return found
  end
  local function constants(values)
   for _,value in ipairs(values)do if eqhash(value,c.mission)then return true end end;return false
  end
  -- func2457/classic and func3346/2020, in source branch order.
  local wrapper=1
  if in_array(28892,6)then wrapper=tf(36208)
  elseif in_array(4725,6)then wrapper=tf(36209)
  elseif in_array(28084,6)then wrapper=tf(36210)
  elseif in_array(9617,8) or in_array(9626,8)then wrapper=tf(36211)
  elseif constants({1657186075,-1789688675,-1433171161,-1635197776,-1509298929,1367922159})then wrapper=tf(36212)
  elseif in_array(32767,6)then wrapper=tf(36214)
  elseif constants({-623391175,-1801970482,-589934703,-1591493106,1511571939,-590314610,-439469264,1240484981})then wrapper=tf(36215)
  elseif in_array(33579,6)then wrapper=tf(36216)
  elseif in_array(37055,6)then wrapper=tf(37071)
  elseif in_array(37067,3)then wrapper=tf(37072)
  elseif gi(2685155+19)==1 then wrapper=tf(38222)
  elseif gi(2685155+18)==1 then wrapper=tf(38223)end
  factor(wrapper)
  assert(gi(1574975)==0 and gi(1575068)==0,'Alternate reward/zero-award route is active.')
  local content=gi(4718592+203791);assert(content~=89 and content~=92,'Creator reward route is unsupported.')
  local difficulty=gi(4718592+3771);assert(int(difficulty,0,2),'Finale difficulty is unavailable.')
  local global=factor(tf(0));local ceiling,floor=tf(2403),tf(2407)
  assert(ceiling>=0 and ceiling<=2147483647 and floor>=0 and floor<=2147483647,'Client award clamps are invalid.')
  local event_eligible=(gi(2673276+194+1)&(1<<27))~=0
  local r={family=c.family,observations=observations,cut_multiplier=1,settlement={global,wrapper},
   ceiling=ceiling,floor=floor,quantum=c.family=='cayo' and 1 or 10,difficulty=difficulty,fees={}}
  if c.family=='cayo'then
   assert(gi(2685155+25)==1,'Cayo reward route is not active.')
   -- func3316 must not select a different family's additional same-transaction award.
   assert(not in_array(33606,7) and not in_array(36149,6) and not in_array(37659,8)
    and not in_array(37055,6) and not in_array(37067,3)
    and not in_array(36654+5,1) and gi(2685155+18)==0,'Additional same-transaction award context is active.')
   local base=1982548+1+c.pid*53+5
   local target=gi(base+9);assert(int(target,0,5),'Cayo primary target is unknown.')
   local primary=positive(ti(29585+target))
   if difficulty>0 then primary=round(mul(primary,factor(tf(29590+difficulty))))end
   local inventory=0
   local function bits(v,width)local n=0;for bit=0,width-1 do if (v&(1<<bit))~=0 then n=n+1 end end;return n end
   for kind=0,4 do
    local count=kind==4 and bits(gi(base+10+17),7) or (bits(gi(base+10+1+kind),24)+bits(gi(base+10+9+kind),8))
    local value=gi(base+10+19+kind);assert(value>=0,'Negative secondary loot value.')
    inventory=inventory+count*value;assert(int(inventory,0,2147483647),'Inventory ceiling overflow.')
   end
   local allowance=ti(29370);assert(allowance>=0,'Negative loot allowance.')
   local collected=li(61422);assert(collected>=0,'Collected secondary take is invalid.')
   assert(int(primary+inventory+allowance,1,2147483647) and int(primary+collected,1,2147483647),'Cayo source total would overflow.')
   r.gross=math.min(primary+collected,primary+inventory+allowance);positive(r.gross)
   local progress
   local override=gi(2686124+6898+35)
   if (gi(4718592+139796)&(1<<28))~=0 and override~=-2 then progress=override
   else progress=li(69376+1+c.participant*293+212)end
   local fence,pavel=tf(29594),tf(29595)
   assert(fence>=-1 and fence<=0 and pavel>-1 and pavel<=0,'Cayo fee signs are invalid.')
   local net=f(1)
   if progress>=ti(29593)then net=f(net+fence);r.fees.Fence=-fence*100 end
   net=f(net+pavel);assert(net>0,'Cayo fees consume the take.')
   r.pool=round(mul(r.gross,net));r.fees.Pavel=-pavel*100
   r.settlement={wrapper,global} -- modern wrapper runs before global multiplier.
   r.source='FMC2020 func3383..3397/880/3293; observed secondary take; primary and inventory clamp'
  elseif c.family=='casino'then
   assert(gi(2685155+22)==1,'Casino reward route is not active.')
   local base=1978125+1+c.pid*68+18
   local target=gi(base+7);assert(int(target,0,3),'Casino target is unknown.')
   local mapping={[0]=28436,[1]=28438,[2]=28437,[3]=28439}
   local gross=positive(ti(mapping[target]))
   if event_eligible then gross=round(mul(gross,factor(tf(38208))))end
   if difficulty>0 then gross=round(mul(gross,factor(tf(28416+difficulty))))end
   local daily,boxes=ti(28049),ti(28431);assert(daily>=0 and boxes>=0,'Optional loot allowance is invalid.')
   local ceiling_take=gross+daily*45+boxes*72;positive(ceiling_take)
   local take=li(20412+2686);assert(take>0,'Casino has no collected take. Collect vault loot before Instant Finish; payout is not ready.')
   local buyer=gi(1973728+8);assert(int(buyer,0,8),'Casino buyer is unknown.')
   local buyer_factor=factor(tf(28419+buyer//3));assert(buyer_factor<=1,'Casino buyer multiplier exceeds one.')
   local loss_units,loss_value=li(32786+c.pid*294+155),li(20412+1777)
   assert(loss_units>=0 and loss_value>=0,'Negative Casino loss input.')
   local losses=mul(loss_units,loss_value)
   assert(int(losses,0,2147483647),'Casino lost-take input is invalid.')
   r.gross=math.min(take,ceiling_take)
   local after=f(mul(r.gross,buyer_factor)-f(losses));positive(after,'Casino has no positive take after loss.')
   local discount=false
   local local_switch,host_switch=ti(28471),ti(28472)
   assert(int(local_switch,0,1) and int(host_switch,0,1),'Membership switches are invalid.')
   if local_switch==1 or host_switch==1 then
    local flags=gi(1970586+3);assert((flags&2)~=0 and (flags&4)==0,'Membership eligibility cache is stale.')
    local member=gi(1970586);assert(int(member,0,1),'Membership eligibility is unknown.');discount=member==1
   end
   local function selected(field,fallback)
    local n=gi(base+field);if n==0 then n=gi(1973728+fallback)end
    assert(int(n,0,5),'Casino crew choice is invalid.');return n
   end
   local gun,hacker=selected(10,13),selected(12,15)
   -- func2471(host,true): the valid-host condition is field !=0 OR true.
   -- Thus driver zero remains zero; Global1973728.f17 is NOT the fallback here.
   local driver=gi(base+14);assert(int(driver,0,5),'Casino driver choice is invalid.')
   local function fee(name,selection,normal,special)
    local percent=selection==0 and 0 or ti(normal+selection-1)
    if discount then local override=selection==0 and -1 or tf(special+selection-1);if override>=0 then percent=override end end
    assert(finite(percent) and percent>=0 and percent<100,'Invalid '..name..' fee.');r.fees[name]=percent;return f(f(percent)/f(100))
   end
   local lester=ti(28422);if discount then local v=tf(28488);if v>=0 then lester=v end end
   assert(lester>=0 and lester<100,'Invalid Lester fee.');r.fees.Lester=lester
   local fraction=f(f(lester)/f(100))
   fraction=f(fraction+fee('Gunman',gun,28448,28473))
   fraction=f(fraction+fee('Hacker',hacker,28453,28478))
   fraction=f(fraction+fee('Driver',driver,28458,28483));assert(fraction<1,'Casino fees consume the take.')
   r.pool=f(after-mul(after,fraction));r.buyer_factor=buyer_factor
   r.source='FMC func2469/2470..2485; observed current take and host loss; buyer before combined exact fees'
  elseif c.family=='doomsday'then
   local rows={act1={26,9263,38205,3,3},act2={27,9264,38206,8,8},act3={28,9265,38207,15,15}}
   local row=assert(rows[c.heist],'Doomsday act is unknown.')
   assert(gi(4718592+139900)==row[1],'Finale reward selector disagrees with Doomsday act.')
   local gross=positive(ti(row[2]))
   if event_eligible then gross=round(mul(gross,factor(tf(row[3]))))end
   if difficulty>0 then gross=round(mul(gross,factor(tf(9330+difficulty))))end
   local low,high=ti(8461),ti(8462);assert(low>=0 and high>=low,'Doomsday reward bounds are invalid.')
   gross=math.max(low,math.min(high,gross));positive(gross)
   local loss_units,loss_value=li(32786+c.pid*294+155),li(20412+1777)
   assert(loss_units>=0 and loss_value>=0,'Negative Doomsday loss input.')
   local loss=mul(loss_units,loss_value);assert(int(loss,0,2147483647),'Doomsday loss input is invalid.')
   r.gross=gross;r.pool=f(f(gross)-f(loss));positive(r.pool,'No positive Doomsday take remains.')
   local flow=gi(2685155+29)
   assert((c.heist=='act1' and flow==3) or (c.heist=='act2' and flow==8) or (c.heist=='act3' and (flow==14 or flow==15)),'Doomsday finale flow is inconsistent.')
   local passed=a.stat(c.prefix..'GANGOPS_FLOW_PASSED_BITSET');assert(int(passed),'Doomsday first/repeat award context is unreadable.')
   observations[#observations+1]={kind='stat',index=c.prefix..'GANGOPS_FLOW_PASSED_BITSET',value=passed}
   r.cut_multiplier=factor(tf((passed&(1<<row[5]))~=0 and 8456 or 8457))
   r.source='FMC func2514/2515..2517/2507/2456; event before difficulty; clamp before observed loss'
  else error('Unknown payout family.')end
  positive(r.pool)
  local key={c.family,r.pool,r.cut_multiplier,r.floor,r.ceiling,r.quantum}
  for _,o in ipairs(observations)do key[#key+1]=o.kind..':'..o.index..'='..tostring(o.value)end
  r.key=table.concat(key,'|');return r
 end)
 return ok and result or nil,not ok and tostring(result) or nil
end

