local TITLE='Heist Max Payout'
local function log(v)if Logger and Logger.LogInfo then pcall(Logger.LogInfo,'[Own Max Payout] '..tostring(v))end end
local function say(v)
 log(v)
 if GUI and GUI.AddToast and eToastPos then pcall(GUI.AddToast,TITLE,v,5000,eToastPos.TOP_RIGHT)end
end
local function ni(hash,...)local v=Natives.InvokeInt(hash,...);assert(int(v,-2147483648,4294967295),'Native integer unavailable.');return v end
local function nb(hash,...)local v=Natives.InvokeBool(hash,...);assert(type(v)=='boolean','Native boolean unavailable.');return v end
local function gi(i)local v=ScriptGlobal.GetInt(i);assert(int(v),'Global integer unavailable: '..i);return v end
local function gf(i)local v=ScriptGlobal.GetFloat(i);assert(finite(v),'Global float unavailable: '..i);return v end
local function li(hash,i)local v=ScriptLocal.GetInt(hash,i);assert(int(v),'Controller input unavailable: '..i);return v end
local function stat(name)
 local p=Memory.AllocInt();assert(int(p,65536,9007199254740991),'Stat buffer unavailable.')
 local ok,value=pcall(function()
  Memory.WriteInt(p,0)
  assert(nb(0x767FBC2AC802EF3D,Utils.Joaat(name),p,-1),'Read-only character stat unavailable: '..name)
  local n=Memory.ReadInt(p);assert(int(n),'Character stat is invalid.');return n
 end)
 local freed=pcall(Memory.Free,p);assert(freed,'Stat buffer could not be released.');assert(ok,value);return value
end
local function count(name)return ni(0x2C83A9DA6BFFC4F9,Utils.Joaat(name))end
local function rid(pid)
 local player=Players.GetById(pid);assert(player,'Network player unavailable.')
 if pid==ni(0x4F8644AF03D0E0D6)then assert(player:IsLocalPlayer()==true,'Local account identity mismatch.')end
 local info=player:GetGamerInfo();local value=info and info.RockstarId
 assert(int(value,1,9007199254740991),'Account identity is unavailable.');return value
end
local function identify(mission)
 local seen={};local found
 local function test(index,family,heist)
  local value=gi(index)
  if value~=0 and value%4294967296==mission%4294967296 then
   local k=family..':'..heist;if not seen[k]then assert(not found,'Ambiguous finale identity.');seen[k]=true;found={family=family,heist=heist}end
  end
 end
 for _,row in ipairs({{3,'act1'},{8,'act2'},{14,'act3'},{15,'act3'}})do test(266854+row[1],'doomsday',row[2])end
 -- Classic func841 recognizes only these three Casino finale approaches.
 -- The other eighteen entries in the same content array are setups.
 for _,index in ipairs({268205,268211,268218})do test(index,'casino','casino')end
 for i=0,10 do test(291682+i,'cayo','cayo')end
 assert(found,'No supported Cayo, Casino or Doomsday finale is identified.');return found
end
local verified={}
local session_epoch,session_unavailable,session_hook_ready=0,false,false
local function bytes(pattern)local out={};for s in pattern:gmatch('%x%x')do out[#out+1]=tonumber(s,16)end;return out end
local function check_bytes(address,values,full)
 local function match(i)assert(Memory.ReadUByte(address+i-1)==values[i],'Verified controller code changed.')end
 if full then for i=1,#values do match(i)end
 else
  for i=1,math.min(8,#values)do match(i)end
  for i=math.max(9,#values-7),#values do match(i)end
 end
end
local function verify(c,full)
 local cache=verified[c.owner_key]
 if not cache then
  cache={};local code_pages={}
  for _,s in ipairs(SIGNATURES[c.kind])do
   local ptr=Memory.ScanScript(c.hash,s.bytes);assert(int(ptr,65536,9007199254740991),'This controller build does not match the source profile ('..s.name..').')
   s.decoded=s.decoded or bytes(s.bytes);check_bytes(ptr,s.decoded,true)
   -- scrProgram indexes independently allocated 16 KiB pages. Logical PCs
   -- establish offsets inside their own page, never one whole-script base.
   local page,offset=s.pc//16384,s.pc%16384
   assert(offset+#s.decoded<=16384,'Source signature crosses a code-page boundary.')
   local base=ptr-offset
   assert(not code_pages[page] or code_pages[page]==base,'Signatures identify inconsistent addresses within one code page.')
   if not code_pages[page]then
    for other,other_base in pairs(code_pages)do
     assert(other==page or base+16384<=other_base or other_base+16384<=base,'Source code pages overlap unexpectedly.')
    end
    code_pages[page]=base
   end
   cache[#cache+1]={ptr=ptr,bytes=s.decoded}
  end
  verified={[c.owner_key]=cache};log('SOURCE_GUARD matched '..#cache..' exact source segments across code pages | kind='..c.kind..' | captured Enhanced 1158 scripts | live build equality limited to verified code')
 else for _,row in ipairs(cache)do check_bytes(row.ptr,row.bytes,full)end end
end
local host={log=log}
function host.now()local v=Time.GetEpocheMs();assert(int(v,0,9007199254740991),'Clock unavailable.');return v end
function host.context(allow_terminal)
 assert(session_hook_ready,'Session lifecycle guard is unavailable.')
 assert(ScriptGlobal.AreValid()==true,'Script globals are not ready.')
 local online,transition=nb(0xD83C2B94E7508980),nb(0x68049AEFF83D8F0A)
 if not online or transition then
  if not session_unavailable then session_epoch=session_epoch+1;verified={}end
  session_unavailable=true;error('GTA Online session is unavailable or changing.')
 end
 session_unavailable=false
 assert(nb(0x05095437424397FA),'Start the hosted finale first; no planning-board writes are made.')
 local pid=ni(0x4F8644AF03D0E0D6);assert(int(pid,0,31),'Local player is unavailable.')
 local slot=stat('MPPLY_LAST_MP_CHAR');assert(slot==0 or slot==1,'Active character is unavailable.')
 local account=rid(pid)
 local selected
 for _,row in ipairs({{'fm_mission_controller','classic',20412,9},{'fm_mission_controller_2020','modern',56504,6}})do
  local n=count(row[1]);assert(n==0 or n==1,'Ambiguous controller instance.')
  if n==1 then assert(not selected,'Multiple controllers are active.');selected=row end
 end
 assert(count('fm_mission_controller_v3')==0,'An unsupported controller family is active.')
 assert(selected,'Waiting for a finale controller.')
 local hash=Utils.Joaat(selected[1]);assert(int(hash,-2147483648,4294967295),'Script hash unavailable.')
 local thread,actual,is_host,participant,roster,entered
 Script.ExecuteAsScript(hash,function()
  entered=true;actual=ni(0x8A1C8B1738FFE87E);thread=ni(0xC30338E8088E2E21)
  is_host=nb(0x83CD99A1E6061AB5);participant=ni(0x57A3BDDAD8E5AA0A)
  local n=ni(0x18D0456E86604654);assert(int(n,1,4),'Controller crew count is invalid.')
  roster={};local seen={}
  for part=0,31 do if nb(0x6FF8FF40B6357D45,part)then
   local player=ni(0x24FB80D107371267,part);assert(int(player,0,31) and not seen[player],'Controller crew is ambiguous.')
   seen[player]=true;roster[#roster+1]={player=player,participant=part,account=rid(player)}
  end end
  assert(#roster==n and seen[pid],'Controller crew changed during observation.')
 end)
 assert(entered and int(actual,-2147483648,4294967295) and actual%4294967296==hash%4294967296 and int(thread,1,2147483647),'Exact controller thread is unavailable.')
 assert(nb(0x46E9AE36D8FA6417,thread),'Controller thread ended.')
 assert(is_host==true and ni(0xD3DEBE2991FE8098,thread)==pid,'Only your own hosted finale is supported.')
 assert(int(participant,0,31),'Local participant is unavailable.')
 local own_part=false;for _,row in ipairs(roster)do if row.player==pid and row.participant==participant then own_part=true end end
 assert(own_part,'Local participant index disagrees with the crew.')
 local ptr=ScriptLocal.GetPtr(hash,selected[3]);assert(int(ptr,65536,9007199254740991),'Controller allocation is unavailable.')
 local mission=gi(4858023);assert(mission~=0,'Mission identity is unavailable.')
 local family=identify(mission)
 assert((family.family=='cayo')==(selected[2]=='modern'),'Finale uses an unsupported controller route.')
 local c={hash=hash,kind=selected[2],script=selected[1],root=selected[3],pid=pid,slot=slot,prefix='MP'..slot..'_',
  account=account,mission=mission,family=family.family,heist=family.heist,participant=participant,roster=roster,ptr=ptr,thread=thread}
 c.owner_key=table.concat({session_epoch,c.family,c.heist,pid,slot,account,mission,hash,thread,ptr},':')
 verify(c,false)
 local owner_index=c.family=='cayo' and (1980570+1092) or c.family=='casino' and (1973762+4356) or (1969071+812+41)
 -- A direct solo launch can clear the old board owner. Exact script-host and
 -- participant checks above establish sole local ownership without that board.
 if #roster>1 then assert(gi(owner_index)==pid,'The finale planning owner is another player.')end
 local roster_parts={};for _,row in ipairs(roster)do roster_parts[#roster_parts+1]=row.participant..'='..row.player..'@'..row.account end
 c.roster_key=table.concat(roster_parts,',');c.key=c.owner_key..'|'..c.roster_key
 local state,flags=li(hash,c.root),li(hash,c.root+1);assert(int(state,0,30),'Controller phase is unknown.')
 local failure=false;for bit=20,23 do if (flags&(1<<bit))~=0 then failure=true end end
 if c.kind=='modern'then local f3=li(hash,c.root+3);failure=failure or (f3&(1<<26))~=0 or (f3&(1<<31))~=0 end
 local active=state==selected[4] and (flags&(1<<17))~=0 and (flags&(1<<19))~=0 and (flags&(1<<16))==0
 c.phase=failure and 'failed' or active and 'active' or 'settling'
 if not allow_terminal then assert(c.phase=='active','Wait for active, non-failed finale objectives.')end
 c.cut=gi(CUT_GLOBAL);assert(int(c.cut,0,999),'Consumed own percentage is outside the supported range.')
 return c
end
local function guard_original_cayo(c)
 if c.family~='cayo'then return end
 local current={};for _,row in ipairs(c.roster)do current[row.player]=true end
 local seen={};local matched=0
 for i=0,3 do
  local player,cut=gi(1981687+c.pid*27+i),gi(1981697+c.pid*27+i)
  assert(int(cut,0,999),'Original Cayo share is invalid.')
  if current[player]then assert(not seen[player],'Original Cayo crew is ambiguous.');seen[player]=true;matched=matched+1
  else assert(cut==0,'Departed Cayo shares could be redistributed; re-enter a stable finale.')end
 end
 assert(matched==#c.roster,'Original Cayo crew does not match the active crew.')
end
function host.read()
 local c=host.context(true)
 if c.phase~='active'then return c,{}end
 guard_original_cayo(c)
 local api={gi=gi,gf=gf,li=function(i)return li(c.hash,i)end,stat=stat}
 local r,why=read_reward(c,api);assert(r,why)
 return c,r
end
function host.same_owner(key)
 local ok,c=pcall(host.context,true);return ok and c.owner_key==key
end
function host.current_cut(key)
 local c=host.context(true);assert(c.owner_key==key,'Owned target changed.');return c.cut
end
function host.write(value,expected,before,reward,restoring)
 assert(int(value,0,999) and int(before,0,999),'Invalid own percentage write.')
 local c,r
 if restoring then c=host.context(true);assert(c.owner_key==expected.owner_key,'Restore target changed.')
 else
  c,r=host.read();assert(c.phase=='active' and c.key==expected.key,'Payout context changed before write.')
  assert(reward and r.key==reward.key,'Take, fees or reward changed before write.')
  local p=assert(calculate(r,TARGETS[c.family]));assert(value==p.cut and value>0,'Write does not match the bounded payout plan.')
 end
 assert(c.cut==before,'Consumed own percentage changed before write.')
 verify(c,true)
 ScriptGlobal.SetInt(CUT_GLOBAL,value)
 assert(gi(CUT_GLOBAL)==value,'The consumed own percentage did not retain the write.')
 local fresh=host.context(true);assert(fresh.owner_key==c.owner_key,'Controller changed after write.')
 if not restoring then
  assert(fresh.roster_key==c.roster_key,'Crew changed after write.')
  local fees={};for name,percent in pairs(r.fees)do fees[#fees+1]=name..'='..percent end;table.sort(fees)
  log('SOURCE_INPUTS | '..r.source..' | consumed_global='..CUT_GLOBAL..' | difficulty='..r.difficulty..' | gross='..r.gross..' | net_pool='..r.pool..' | fees='..table.concat(fees,',')..' | current_loot_only=true | remote_crew_unchanged=true')
 end
 return true
end
local controller=new_controller(host)
local feature_enabled=false;local last_message,last_ok
local function display_status(message)
 local value=tostring(message):gsub('^Waiting:%s*','')
 for _=1,3 do value=value:gsub('^.-:%d+:%s*','')end
 if value:find('Start the hosted finale first',1,true)
  or value:find('Waiting for a finale controller',1,true)
  or value:find('Wait for active, non-failed finale objectives',1,true)then
  return 'Armed. Applies automatically when the finale starts.'
 end
 return value
end

-- Casino's award source reads the mission's collected-take local.
-- Prepare that source only when Instant Finish is explicitly requested.
-- This is a guarded candidate; the server can still reject an award.
local function prepare_casino_take_for_finish()
 local c=host.context(false)
 if c.family~='casino'then return true,'No Casino take preparation needed.'end
 verify(c,true)
 assert(c.kind=='classic' and c.phase=='active',
  'Casino finale is not active in the verified classic controller.')
 assert(gi(2685155+22)==1,'Casino award route is not active.')
 local difference=gi(4718592+3771)
 assert(int(difference,0,2),'Casino difficulty is unreadable.')
 local pid=c.pid
 local base=1978125+1+pid*68+18
 local target=gi(base+7)
 assert(int(target,0,3),'Casino vault target is unavailable.')
 local mapping={[0]=28436,[1]=28438,[2]=28437,[3]=28439}
 local function ti(idx)return gi(262145+idx)end
 local function tf(idx)return gf(262145+idx)end
 local gross=ti(mapping[target])
 assert(int(gross,1,2147483647),'Casino gross take not configured.')
 local event=(gi(2673276+194+1)&(1<<27))~=0
 if event then
  local mult=tf(38208)
  assert(finite(mult)and mult>0 and mult<=100,'Invalid Casino event multiplier.')
  gross=round(mul(gross,mult))
 end
 if difference>0 then
  local mult=tf(28416+difference)
  assert(finite(mult)and mult>0 and mult<=100,'Invalid Casino difficulty multiplier.')
  gross=round(mul(gross,mult))
 end
 local daily,boxes=ti(28049),ti(28431)
 assert(int(daily,0,2147483647) and int(boxes,0,2147483647),
  'Casino optional-take values are invalid.')
 local amount=gross+daily*45+boxes*72
 assert(int(amount,1,2147483647),'Casino source take ceiling is invalid.')
 local index=20412+2686
 local current=li(c.hash,index)
 assert(int(current,0,2147483647),'Casino collected take is invalid.')
 assert(current<=amount,'Current take exceeds the computed Casino target ceiling.')
 if current==amount then return true,'Casino source take already at computed ceiling.'end
 local ok,error_message=pcall(function()
  assert(host.same_owner(c.owner_key),'Casino mission owner changed.')
  assert(li(c.hash,index)==current,'Casino take changed before the write.')
  ScriptLocal.SetInt(c.hash,index,amount)
  assert(li(c.hash,index)==amount,'Casino take write was rejected.')
 end)
 if not ok then
  pcall(function()
   if host.same_owner(c.owner_key) and li(c.hash,index)==amount then
    ScriptLocal.SetInt(c.hash,index,current)
   end
  end)
  return false,tostring(error_message)
 end
 log('CASINO_TAKE_PREPARED source=FMC.f_2686 before='..current
  ..' after='..amount..' | this is source state, not verified server payment')
 return true,'Casino take prepared from observed vault target.'
end

-- Cayo payout source is independent from Casino's. The mission controller uses
-- uLocal_59986.f_1376.f_60 (local 61422) for secondary take and caps it using
-- the *observed* scoutable loot inventory plus the safe allowance.
-- Prepare it only on an explicit Instant Finish, with own-script-host checks.
local function prepare_cayo_take_for_finish()
 local c=host.context(false)
 assert(c.family=='cayo' and c.kind=='modern','Not an active Cayo finale.')
 verify(c,true)
 guard_original_cayo(c)
 assert(gi(2685155+25)==1,'Cayo reward route is not active.')
 local base=1982548+1+c.pid*53+5
 local function bitcount(v,width)
  local n=0
  for b=0,width-1 do if (v&(1<<b))~=0 then n=n+1 end end
  return n
 end
 local inventory=0
 for kind=0,4 do
  local count
  if kind==4 then
   count=bitcount(gi(base+10+17),7)
  else
   count=bitcount(gi(base+10+1+kind),24)+bitcount(gi(base+10+9+kind),8)
  end
  local value=gi(base+10+19+kind)
  assert(int(value,0,2147483647),'Cayo secondary loot unit value is invalid.')
  inventory=inventory+count*value
  assert(int(inventory,0,2147483647),'Cayo available loot overflow.')
 end
 local allowance=gi(262145+29370)
 assert(int(allowance,0,2147483647),'Cayo loot allowance is invalid.')
 local ceiling=inventory+allowance
 assert(int(ceiling,0,2147483647),'Cayo source take ceiling is invalid.')
 local index=61422
 local current=li(c.hash,index)
 assert(int(current,0,2147483647),'Cayo current secondary take is invalid.')
 assert(current<=ceiling,'Cayo observed take exceeds the computed inventory ceiling.')
 if current==ceiling then return true,'Cayo take already matches observed available loot.'end
 local ok,why=pcall(function()
  assert(host.same_owner(c.owner_key),'Cayo controller changed during preparation.')
  assert(li(c.hash,index)==current,'Cayo collected take changed before submission.')
  ScriptLocal.SetInt(c.hash,index,ceiling)
  assert(li(c.hash,index)==ceiling,'Cayo take write did not stick.')
  assert(host.same_owner(c.owner_key),'Cayo controller changed during source write.')
 end)
 if not ok then
  pcall(function()
   if host.same_owner(c.owner_key) and li(c.hash,index)==ceiling then
    ScriptLocal.SetInt(c.hash,index,current)
   end
  end)
  return false,'Cayo source take preparation failed: '..tostring(why)
 end
 log('CAYO_TAKE_PREPARED | available='..inventory..' allowance='..allowance
  ..' | collected_before='..current..' submitted='..ceiling..' | payout still unconfirmed')
 return true,'Cayo source take prepared from observed available loot.'
end

local function prepare_heist_take_for_finish()
 local c=host.context(false)
 if c.family=='casino'then return prepare_casino_take_for_finish()end
 if c.family=='cayo'then return prepare_cayo_take_for_finish()end
 return true,'Doomsday uses its configured finale award.'
end

local function before_finish()
 if not feature_enabled then return true,'Max Payout is off.'end
 -- pcall returns: call succeeded, preparation succeeded, message.
 -- v2 mistakenly unpacked just two values and concatenated a boolean.
 local call_ok,prep_ok,prep_message=pcall(prepare_heist_take_for_finish)
 local preparation_ok=call_ok and prep_ok
 local detail=preparation_ok and tostring(prep_message)
   or ('Take preparation unavailable: '..tostring(call_ok and prep_message or prep_ok))
 if not preparation_ok then log('TAKE_PREP_UNAVAILABLE | '..detail)end
 local ok,r=pcall(controller.Tick,true)
 if not ok then return false,'Max Payout check failed: '..tostring(r)end
 if r and r.ok and r.plan then
  log('MAX_PAYOUT_BEFORE_FINISH | family='..r.plan.family
   ..' cut='..r.plan.cut..' estimate='..r.plan.amount..' configured_target='..r.plan.target)
  return true,detail..'; own cut prepared. Actual payment unconfirmed.',r.plan
 end
 return false,(preparation_ok and '' or (detail..' | '))
  ..(r and display_status(r.message) or 'Max Payout is not ready.')
end
local function set_enabled(value)
 feature_enabled=value==true
 last_message,last_ok=nil,nil
 return controller.Enable(feature_enabled)
end
local function session_changed()
 session_epoch=session_epoch+1;verified={}
 controller.Invalidate('CScript session changed')
end
return {Controller=controller,Host=host,BeforeFinish=before_finish,
 Calculate=calculate,Estimate=estimate,ReadReward=read_reward,Signatures=SIGNATURES,
 SetEnabled=set_enabled,Enabled=function()return feature_enabled end,
 Tick=function(force)return controller.Tick(force)end,
 BindLifecycle=function()session_hook_ready=true end,
 OnSessionChanged=session_changed}
end)()

local ApartmentSelector=(function()

-- Standalone apartment replay selector for Cherax / Enhanced.
-- One click switches the selected heist, completes setups and refreshes its finale.
-- Mapping: fmmc_launcher func_8950/8954, freemode func_19117/19186.
local TITLE='Apartment Heist Selector'
local ROWS={
 {name='The Fleeca Job',uid='33TxqLipLUintwlU_YDzMg',tunable=9188},
 {name='The Prison Break',uid='A6UBSyF61kiveglc58lm2Q',tunable=9193},
 {name='The Humane Labs Raid',uid='a_hWnpMUz0-7Yd_Rc5pJ4w',tunable=9200},
 {name='Series A Funding',uid='7r5AKL5aB0qe9HiDy3nW8w',tunable=9206},
 {name='The Pacific Standard Job',uid='hKSf9RCT8UiaZlykyGrMwg',tunable=9212},
}
local G={state=2635125,root=2635127,index=2635533,replay=2635534,cancel=2635546,
 board=1941554,flags=2635522,catalog=2634773,count=2635124}
local function integer(v)return type(v)=='number' and v%1==0 and v>=-2147483648 and v<=2147483647 end
local function equal_hash(a,b)return integer(a) and type(b)=='number' and a%4294967296==b%4294967296 end
local function new_controller(h)
 local pending,latest=nil,'Choose a heist to prepare its finale.'
 local c={}
 local function read()local ok,s=pcall(h.read);assert(ok and type(s)=='table','GTA heist state is unreadable.');return s end
 local function world(s)
  assert(s.session==true and s.activity==false and s.freemode==1 and s.classic==0 and s.modern==0,'Return to GTA Online freemode first.')
  assert(integer(s.pid) and s.pid>=0 and s.pid<=31 and (s.slot==0 or s.slot==1),'Character is unavailable.')
  assert(integer(s.board) and s.board>=-1 and s.board<=2,'Close the interactive planning screen first.')
  assert(s.catalog==true,'GTA heist catalog does not match this script.')
 end
 local function scope(p,s)
  world(s);assert(s.pid==p.pid and s.slot==p.slot and s.roots[p.choice]==p.root,'Character or heist context changed.')
 end
 local function write(k,v)assert(h.write(k,v)==true,'GTA rejected '..k..'.')end
 local function message(text)latest=text;return true,text end
 local function cancel_owned(p)
  local ok,s=pcall(read)
  if p.loading and ok and s.pid==p.pid and s.slot==p.slot and s.session==true and s.activity==false
   and s.root==p.root and s.replay==0 and (s.state==2 or s.state==3) and s.cancel==0 then
   pcall(h.write,'cancel',1)
  end
 end
 local function fail(why)
  if pending and h.trace then pcall(h.trace,pending,'failed')end
  if pending then cancel_owned(pending)end
  pending=nil;latest=tostring(why):gsub('^.-:%d+:%s*','');return false,latest
 end
 local function activate(p)
  scope(p,read());local ok,why=h.activate(p);assert(ok,why or 'Could not refresh the selected finale.')
  p.phase='verify';return message('Activating '..ROWS[p.choice].name..' finale...')
 end
 local function load_template(p,s)
  scope(p,s)
  if s.cancel~=0 or s.cloud~=0 then p.phase='idle';return message('Waiting for the previous heist request to settle...')end
  assert(s.state==0 or s.state==1 or s.state==10,'Heist loader has not settled.')
  assert(s.replay==0 and s.index==-1,'A different heist request is still running.')
  local changes={};local expected={root=s.root,index=s.index,replay=s.replay}
  local ok,why=pcall(function()
   for _,kv in ipairs({{'index',-1},{'replay',0},{'root',p.root}})do
    local fresh=read();scope(p,fresh)
    assert(fresh.state==s.state and fresh.cancel==0 and fresh.cloud==0,'Heist loader changed during selection.')
    for k,v in pairs(expected)do assert(fresh[k]==v,'Another selection replaced this request.')end
    local k,v=kv[1],kv[2];changes[#changes+1]={k=k,old=fresh[k],value=v};write(k,v);expected[k]=v
   end
   local fresh=read();scope(p,fresh)
   assert(fresh.root==p.root and fresh.state==s.state and fresh.replay==0 and fresh.index==-1 and fresh.cancel==0 and fresh.cloud==0,'Heist loader changed before publication.')
   p.loading=true;write('state',2)
  end)
  if not ok then
   local fresh=read()
   if fresh.pid==p.pid and fresh.slot==p.slot and fresh.state==s.state then
    for i=#changes,1,-1 do local x=changes[i];if read()[x.k]==x.value then pcall(h.write,x.k,x.old)end end
   end
   error(why)
  end
  p.phase='template';return message('Loading '..ROWS[p.choice].name..' setup data...')
 end
 local function begin(choice)
  assert(not pending,'A heist is already being prepared.')
  assert(integer(choice) and ROWS[choice],'Choose one of the five apartment heists.')
  local s=read();world(s)
  assert(integer(s.state) and s.state>=0 and s.state<=10,'Heist loader state is unavailable.')
  assert(s.state<7 or s.state==10,'A heist is launching. Return to freemode before switching.')
  local root=s.roots[choice];assert(integer(root) and root~=0,'Selected heist content is unavailable.')
  local p={pid=s.pid,slot=s.slot,root=root,choice=choice,started=h.now()}
  local saved_ok,saved=pcall(h.saved,p)
  if not saved_ok then saved=nil end
  pending=p
  if saved and equal_hash(saved.root,root) and integer(saved.mask) and saved.mask>0 and saved.count==({2,4,5,5,5})[choice]
   and s.cloud==0 and s.cancel==0 and s.replay==0 and (s.state==0 or s.state==1 or s.state==6 or s.state==10)then
   local ok,why=h.complete(p,saved);assert(ok,why or 'GTA did not accept the setup progress.')
   p.committed=true;return activate(p)
  end
  if h.preflight then local ok,why=h.preflight(p);assert(ok,why)end
  if s.state==0 or s.state==1 or s.state==10 then return load_template(p,s)end
  if s.state==2 then p.phase='wait';return message('Waiting for the current heist data load...')end
  assert(s.cancel==0 and s.cloud==0,'Another heist request is still cleaning up.')
  p.phase='cancel';p.previous_root=s.root;p.previous_state=s.state
  write('cancel',1)
  return message('Replacing the current apartment heist...')
 end
 function c.Select(choice)
  if pending then return false,'A heist is already being prepared.'end
  local ok,a,b=pcall(begin,choice);if not ok then return fail(a)end;return a,b
 end
 local function tick()
  local p=pending;if not p then return nil end
  local s=read();scope(p,s)
  local now=h.now()
  assert(now>=p.started and now-p.started<3000,p.committed
   and 'Heist data saved; board refresh timed out after 3 seconds. Check Show Status.'
   or 'Heist preparation timed out after 3 seconds. Check Show Status and the Cherax log.')
  if p.phase=='verify'then
   if h.confirm(p)then
    if h.trace then pcall(h.trace,p,'ready')end
    pending=nil;return message(ROWS[p.choice].name..' finale ready. Setups complete.')
   end
   return nil
  end
  if p.phase=='wait'then
   if s.state==2 then return nil end
   assert(s.state<7 or s.state==10,'GTA started launching a heist; switching stopped.')
   if s.state==0 or s.state==1 or s.state==10 then return load_template(p,s)end
   assert(s.cloud==0 and s.cancel==0,'Another request is cleaning up.')
   p.phase='cancel';p.previous_root=s.root;write('cancel',1);return message('Replacing the previous heist selection...')
  end
  if p.phase=='cancel'then
   if s.cancel==0 and (s.state==0 or s.state==1 or s.state==10)then return load_template(p,s)end
   assert(s.root==p.previous_root,'Another selection replaced the current heist.')
   return nil
  end
  if p.phase=='idle'then
   if s.cancel==0 and s.cloud==0 and (s.state==0 or s.state==1 or s.state==10)then return load_template(p,s)end
   return nil
  end
  if p.phase=='cleanup'then
   if s.cancel==0 and s.cloud==0 and (s.state==0 or s.state==1 or s.state==10)then return activate(p)end
   return nil
  end
  assert(s.root==p.root and s.replay==0 and s.index==-1,'Another request replaced this heist preparation.')
  if p.phase=='template'then
   if s.state==2 then return nil end
   assert(s.state==3 and s.cancel==0,'GTA did not retain the selected heist template.')
   local data,why=h.template(p);assert(data,why or 'Loaded setup data is incomplete.')
   local ok,reason=h.install(p,data);assert(ok,reason or 'GTA rejected the selected heist data.')
   p.committed=true;p.phase='cleanup';write('cancel',1)
   return message('Setups prepared. Activating the selected finale...')
  end
  return nil
 end
 function c.Tick()local ok,a,b=pcall(tick);if not ok then return fail(a)end;return a,b end
 function c.Status()return latest end
 function c.Stop()
  if pending then cancel_owned(pending)end
  pending=nil;latest='Stopped.'
 end
 return c
end

G.cloud=2625301;G.template=2635459;G.identity=1941984+10
G.blocked=2635547;G.dirty=1936441+1782;G.board_uid=1936441+1787;G.owner=1941984+58
G.phase=1936441;G.left=1941984;G.right=1941984+1
G.finale_phase=1938374+2768
local function gi(i)local ok,v=pcall(ScriptGlobal.GetInt,i);if ok and integer(v)then return v end end
local function gs(i)local ok,v=pcall(ScriptGlobal.GetString,i);if ok and type(v)=='string'then return v end end
local function nb(hash,...)local ok,v=pcall(Natives.InvokeBool,hash,...);if ok and type(v)=='boolean'then return v end end
local function ni(hash,...)local ok,v=pcall(Natives.InvokeInt,hash,...);if ok and integer(v)then return v end end
local function buffer_stat(name,kind)
 local ptr=Memory.AllocInt();assert(ptr and ptr~=0,'Stat buffer unavailable.')
 local ok,value=pcall(function()
  Memory.WriteInt(ptr,0)
  local native=kind=='bool' and 0x11B5E6D2AE73F48E or 0x767FBC2AC802EF3D
  assert(Natives.InvokeBool(native,Utils.Joaat(name),ptr,-1)==true,'Cannot read '..name)
  local v=Memory.ReadInt(ptr);assert(integer(v),'Invalid stat: '..name)
  if kind=='bool'then assert(v==0 or v==1,'Invalid boolean stat.');return v==1 end
  return v
 end)
 pcall(Memory.Free,ptr);assert(ok,value);return value
end
local function stat_read(p,key,kind)
 local name='MP'..p.slot..'_'..key
 if kind=='int' or kind=='bool'then return buffer_stat(name,kind)end
 local value
 if kind=='uid'then value=Natives.InvokeString(0x2365C388E393BBE2,Utils.Joaat(name))
 else value=Natives.InvokeString(0xE50384ACC2C3DB74,Utils.Joaat(name),-1)end
 assert(type(value)=='string','Cannot read '..key)
 if kind=='uid' and value=='STAT_UNKNOWN'then return '0'end
 return value
end
local function stat_write(p,key,kind,value)
 local native=({int=0xB3271D7AB655B441,bool=0x4B33C4243DE0C432,string=0xA87B2335D12531D7,uid=0x8CDDF1E452BABE11})[kind]
 return Natives.InvokeBool(native,Utils.Joaat('MP'..p.slot..'_'..key),value,true)==true
end
local function set_global(key,value)
 assert(G[key],'Unknown heist field.');ScriptGlobal.SetInt(G[key],value)
 return gi(G[key])==value
end
local function set_text(index,value)ScriptGlobal.SetString(index,value);assert(gs(index)==value,'GTA did not retain its heist cache refresh.')end
local host={now=function()return Time.GetEpocheMs()end,write=set_global}
function host.read()
 local s={session=nb(0xD83C2B94E7508980),activity=nb(0x05095437424397FA),pid=ni(0x4F8644AF03D0E0D6),
  slot=buffer_stat('MPPLY_LAST_MP_CHAR','int'),roots={}}
 s.freemode=ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('freemode'))
 s.classic=ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller'))
 s.modern=ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller_2020'))
 for _,k in ipairs({'board','state','root','index','replay','cancel','flags','cloud'})do s[k]=gi(G[k])end
 local count=gi(G.count);s.catalog=gi(G.catalog)==25 and integer(count) and count>=5 and count<=25
 for i,row in ipairs(ROWS)do
  local value=gi(262145+row.tunable);s.roots[i]=value
  if not equal_hash(value,Utils.Joaat(row.uid))then s.catalog=false end
  local matches=0
  if s.catalog then for j=0,count-1 do if equal_hash(gi(G.catalog+1+j*14+12),value)then matches=matches+1 end end end
  if matches~=1 then s.catalog=false end
 end
 return s
end
local function guard(p,template)
 assert(nb(0xD83C2B94E7508980)==true and nb(0x05095437424397FA)==false
  and ni(0x4F8644AF03D0E0D6)==p.pid and buffer_stat('MPPLY_LAST_MP_CHAR','int')==p.slot,'Character or session changed.')
 assert(ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller'))==0
  and ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller_2020'))==0,'A mission started during preparation.')
 if template then assert(gi(G.state)==3 and gi(G.root)==p.root and gi(G.replay)==0 and gi(G.cancel)==0,'Heist template ownership changed.')end
end
local function mission_data(read_string,read_depth)
 local d={missions={},depths={},mask=0,count=0};local ended=false
 for i=1,7 do
  local uid,depth=read_string(i),read_depth(i)
  assert(type(uid)=='string' and #uid<=23 and integer(depth),'Setup mission data is unreadable.')
  d.missions[i],d.depths[i]=uid,depth
  if uid=='' or uid=='.'then ended=true
  else
   assert(not ended and depth>=0 and depth<=6,'Setup mission order is incomplete.')
   d.mask=d.mask | (1<<((i-1)*3));d.count=d.count+1
  end
 end
 return d
end
function host.saved(p)
 local d=mission_data(function(i)return stat_read(p,'HEIST_MISSION_RCONT_ID_'..i,'string')end,
  function(i)return stat_read(p,'HEIST_MISSION_DEPTH_LV_'..i,'int')end)
 d.root=stat_read(p,'HEIST_MISSION_RCONT_ID_0','int');d.stage=stat_read(p,'HEIST_PLANNING_STAGE','int')
 return d
end
local function eligible_property(id)
 return integer(id) and ((id>=1 and id<=7) or (id>=34 and id<=43) or (id>=61 and id<=65) or (id>=73 and id<=85))
end
local function property(p)
 local owned={};local gate=gi(262145+17443);assert(gate==0 or gate==1,'Apartment ownership data unavailable.')
 for i=0,9 do
  local id=stat_read(p,i==0 and 'PROPERTY_HOUSE' or 'MULTI_PROPERTY_'..i,'int')
  if (i~=5 or gate==1) and eligible_property(id)then owned[#owned+1]=id end
 end
 assert(#owned>0,'A high-end apartment is required.')
 local leader=stat_read(p,'HEIST_LEADER_APART_ID','int')
 for _,id in ipairs(owned)do if leader==id then return id end end
 return owned[1]
end
function host.preflight(p)p.property=property(p);return true end
function host.template(p)
 guard(p,true)
 assert(gi(G.template)==p.root and gi(G.template+1)==7,'GTA has not finished loading this template.')
 local d=mission_data(function(i)return gs(G.template+2+(i-1)*7)end,
  function(i)return gi(G.template+2+(i-1)*7+6)end)
 assert(d.count==({2,4,5,5,5})[p.choice],'Loaded setup count does not match the selected heist.')
 for _,row in ipairs({{'reward',51},{'tutorial',53},{'mac',54},{'time',55}})do d[row[1]]=gi(G.template+row[2]);assert(integer(d[row[1]]),'Heist metadata unavailable.')end
 assert(d.reward>=0 and (d.tutorial==0 or d.tutorial==1),'Heist metadata is incomplete.')
 d.root=p.root;return d
end
local function fingerprint(d)
 return table.concat({d.root,d.mask,d.reward,d.tutorial,d.mac,d.time,table.concat(d.missions,'/'),table.concat(d.depths,'/')},'|')
end
local function transact(p,fields,validate)
 local attempted={}
 local ok,why=pcall(function()
  validate()
  for _,f in ipairs(fields)do f.before=stat_read(p,f.key,f.kind)end
  validate()
  for _,f in ipairs(fields)do
   validate();assert(stat_read(p,f.key,f.kind)==f.before,'Saved heist changed before '..f.key)
   if f.before~=f.value then
    attempted[#attempted+1]=f
    assert(stat_write(p,f.key,f.kind,f.value),'GTA rejected '..f.key)
    assert(stat_read(p,f.key,f.kind)==f.value,'Readback failed: '..f.key)
   end
  end
  validate()
  for _,f in ipairs(fields)do assert(stat_read(p,f.key,f.kind)==f.value,'Saved heist changed after '..f.key)end
 end)
 if ok then return true end
 local skipped=0
 for i=#attempted,1,-1 do
  local f=attempted[i]
  local restored=pcall(function()
   validate();local value=stat_read(p,f.key,f.kind)
   if value~=f.before then
    assert(value==f.value,'A newer value replaced the attempted write.')
    assert(stat_write(p,f.key,f.kind,f.before) and stat_read(p,f.key,f.kind)==f.before,'Could not restore the previous value.')
   end
  end)
  if not restored then skipped=skipped+1 end
 end
 return false,tostring(why)..(skipped>0 and ' Some previous data could not be restored; check the log.' or ' Previous heist data retained.')
end
function host.complete(p,d)
 guard(p,false);local expected=d.stage | d.mask
 return transact(p,{{key='HEIST_PLANNING_STAGE',kind='int',value=expected}},function()
  guard(p,false);assert(equal_hash(stat_read(p,'HEIST_MISSION_RCONT_ID_0','int'),p.root),'Saved heist changed.')
  assert(gi(G.cancel)==0 and gi(G.cloud)==0,'Heist loader changed.')
 end)
end
function host.install(p,d)
 guard(p,true);assert(property(p)==p.property,'Apartment ownership changed.')
 local signature=fingerprint(d)
 assert(fingerprint(host.template(p))==signature,'Heist template changed before preparation.')
 local fields={};local function add(k,t,v)fields[#fields+1]={key=k,kind=t,value=v}end
 for i=1,7 do add('HEIST_MISSION_RCONT_ID_'..i,'string',d.missions[i])end
 add('HEIST_MISSION_DEPTH_LV_0','int',-1)
 for i=1,7 do add('HEIST_MISSION_DEPTH_LV_'..i,'int',d.depths[i])end
 add('HEIST_PLANNING_STAGE','int',d.mask);add('HEIST_TOTAL_REWARD_COSMETIC','int',d.reward)
 add('HEIST_IS_TUTORIAL','bool',d.tutorial==1)
 add('HEIST_SESSION_ID_MACADDR','int',d.mac);add('HEIST_SESSION_ID_POSTIME','int',d.time)
 add('HEIST_LEADER_APART_ID','int',p.property)
 for i=0,7 do for j=0,3 do add('HEIST_MISSION_PLAYER_'..i..'_'..j,'uid','0');add('HEIST_MISSION_PLAYER_S_'..i..'_'..j,'string','0')end end
 for _,v in ipairs({'TUT','PRISON','HUMANE','NARC','ORNATE'})do add('CUTSCENE_MID_'..v,'int',0)end
 add('HEIST_PLANNING_DONE_PRINT','bool',false);add('HEIST_CUTS_DONE_FINALE','bool',false);add('HEIST_STRAND_INTRO_DONE','bool',true)
 add('HEIST_MISSION_RCONT_ID_0','int',p.root) -- Publish the selected heist last.
 local ok,why=transact(p,fields,function()guard(p,true)end)
 if not ok then return false,why end
 assert(fingerprint(host.template(p))==signature,'Heist template changed during preparation.')
 -- Clear the old UID before releasing state 3. Freemode can consume the
 -- cancellation and restore state 10 from this cache in the same frame.
 -- Clearing it only in activate() leaves that restore ahead of our next tick.
 guard(p,true)
 assert(equal_hash(stat_read(p,'HEIST_MISSION_RCONT_ID_0','int'),p.root),'Saved heist changed before identity refresh.')
 set_text(G.identity,'')
 return true
end
function host.activate(p)
 guard(p,false)
 local d=host.saved(p);assert(equal_hash(d.root,p.root) and d.mask>0 and (d.stage & d.mask)==d.mask,'Saved setups are incomplete.')
 local state=gi(G.state)
 assert((state==0 or state==1 or state==6 or state==10) and gi(G.cancel)==0 and gi(G.cloud)==0 and gi(G.replay)==0,'GTA is still processing the previous selection.')
 assert(set_global('root',p.root),'GTA did not retain the chosen heist.')
 set_text(G.identity,'') -- GTA resolves the saved root and reloads its own mission cache.
 local blocked=gi(G.blocked);assert(blocked==0 or blocked==1,'Heist activation latch unavailable.')
 if blocked==1 then assert(set_global('blocked',0),'Could not reactivate apartment planning.')end
 p.board_expected=gi(G.owner)==p.pid and ((gi(G.left)or 0)>0 or (gi(G.right)or 0)>0)
 return true
end
local function movie_update(handle,method,adder,args)
 assert(Natives.InvokeBool(0xF6E48914C7A8694E,handle,method)==true,'Board rejected '..method..'.')
 local ok,why=pcall(function()
  for _,value in ipairs(args)do Natives.InvokeVoid(adder,value)end
 end)
 local ended,end_error=pcall(Natives.InvokeVoid,0xC6796A8FFA375E53)
 assert(ok,why);assert(ended,end_error)
end
function host.update_display(p,handle)
 local reward=gi(1938374+2995)
 assert(integer(reward) and reward>=0,'Finale reward is unreadable.')
 local cuts={}
 for i=1,5 do
  cuts[i]=gi(1938374+3008+i)
  assert(integer(cuts[i]) and cuts[i]>=0 and cuts[i]<=9999,'Finale board percentages are unreadable.')
 end
 local title=Natives.InvokeString(0x7B5280EBA9840C72,'HTITLE_DEF')
 assert(type(title)=='string' and title~='' and title~='NULL','Board title label is unreadable.')
 local function stable()
  guard(p,false)
  local board=gs(G.board_uid)
  assert(gi(G.owner)==p.pid and gi(G.left)==handle and gi(G.finale_phase)==11
   and board and equal_hash(p.root,Utils.Joaat(board)) and gi(1938374+2995)==reward,'Finale board changed during display update.')
  for i=1,5 do assert(gi(1938374+3008+i)==cuts[i],'Board cuts changed during display update.')end
 end
 -- HEIST_MP INITIALISE_HEISTBOARD is a no-op after the first initialization.
 -- GTA's SET/ADD calls populate the model but leave existing title/pie items
 -- visible. The explicit UPDATE methods repaint those existing slots.
 stable()
 movie_update(handle,'UPDATE_HEIST_NAME',0xE83A3E3557A56640,{ROWS[p.choice].name,'','',title})
 stable()
 movie_update(handle,'UPDATE_PIECHART',0xC3D0841A0CC546A6,{reward,table.unpack(cuts)})
 stable();p.display_updated=true
end
function host.confirm(p)
 guard(p,false)
 local d=host.saved(p)
 if not equal_hash(d.root,p.root) or d.mask==0 or (d.stage & d.mask)~=d.mask or gi(G.root)~=p.root then return false end
 local state=gi(G.state);if state~=6 and state~=10 then return false end
 local cached,board=gs(G.identity),gs(G.board_uid)
 if not cached or cached=='' or not equal_hash(p.root,Utils.Joaat(cached))then return false end
 local left,right=gi(G.left),gi(G.right)
 local own=gi(G.owner)==p.pid
 local visible=own and ((left or 0)>0 or (right or 0)>0)
 if not p.board_expected and not visible then return true end
 if not own then return false end
 if not left or left<=0 or not right or right<=0
  or nb(0x85F01B8D5B90570E,left)~=true or nb(0x85F01B8D5B90570E,right)~=true then return false end
 -- This is the standing FINALE display, not the setup board. The live log
 -- shows its old board UID remains cached after the saved root changes.
 -- fmmc_launcher 9005 routes state 10 through 9017, which obtains the new
 -- UID, sets the title/reward and initializes the display, then publishes 11.
 -- Only re-enter that initialization from its idle standing state 11.
 local phase=gi(G.finale_phase)
 if not p.reinit_requested then
  if phase~=11 then return false end
  assert(set_global('finale_phase',10),'Could not reload the finale board.')
  p.reinit_requested=true
  pcall(host.trace,p,'finale_reload')
  return false
 end
 if phase~=11 or not board or board=='' or not equal_hash(p.root,Utils.Joaat(board))then return false end
 if not p.display_updated then host.update_display(p,left)end
 return p.display_updated==true
end
function host.trace(p,reason)
 if Logger and Logger.LogInfo then
  Logger.LogInfo('[Selector details] reason='..tostring(reason)..' phase='..tostring(p and p.phase)
   ..' elapsed_ms='..tostring(p and host.now()-p.started)..' state='..tostring(gi(G.state))..' root='..tostring(gi(G.root))
   ..' cancel='..tostring(gi(G.cancel))..' cloud='..tostring(gi(G.cloud))..' cached_uid='..tostring(gs(G.identity))
   ..' board_phase='..tostring(gi(G.phase))..' board_uid='..tostring(gs(G.board_uid))..' dirty='..tostring(gi(G.dirty))
   ..' owner='..tostring(gi(G.owner))..' left='..tostring(gi(G.left))..' right='..tostring(gi(G.right))
   ..' finale_phase='..tostring(gi(G.finale_phase))..' finale_reward='..tostring(gi(1938374+2995))
   ..' reinit_requested='..tostring(p and p.reinit_requested)..' display_updated='..tostring(p and p.display_updated))
 end
end
local selector=new_controller(host)
return {Controller=selector,Rows=ROWS,Host=host,NewController=new_controller}
end)()

local ApartmentBoard=(function()

-- Standalone Apartment Planning Board test for Cherax.
-- One feature. Does not load CScript or change finale cuts, payout or setups.
local TITLE = "Apartment Board Test"
local G = {
    owner=1941984+58, root=1936441+1787, count=1936441+1707,
    dirty=1936441+1782, status=1936441+1720+1,
    player_base=1877383+1,
}
local H={
    session=0xD83C2B94E7508980, activity=0x05095437424397FA,
    player=0x4F8644AF03D0E0D6, stat_int=0x767FBC2AC802EF3D,
    stat_string=0xE50384ACC2C3DB74,
}
local function number_ok(n)
    return type(n)=="number" and n==n and n%1==0
        and n>=-9007199254740991 and n<=9007199254740991
end
local function valid_time(n) return number_ok(n) and n>=0 end
local function valid_string(v) return type(v)=="string" and v~="" and v~="." end
local function same(a,b)
    return a.player==b.player and a.slot==b.slot and a.saved_root==b.saved_root
        and a.stage==b.stage and a.board_root==b.board_root and a.count==b.count
end
local function log(msg)
    if type(Logger)=="table" and type(Logger.LogInfo)=="function" then
        pcall(Logger.LogInfo,"["..TITLE.."] "..tostring(msg))
    end
end
local function say(msg)
    log(msg)
    if type(GUI)=="table" and type(GUI.AddToast)=="function" then
        pcall(function()GUI.AddToast(TITLE,tostring(msg),5500,eToastPos.TOP_RIGHT)end)
    end
end

-- This controller is unit-testable without GTA. Host actions are isolated.
local function new_controller(host)
    local pending,latest,last_poll=nil,"Ready",0
    local api={}
    local function result(ok,msg)latest=msg;return ok,msg end
    local function inspect()
        local ok,s=pcall(host.inspect)
        if not ok or type(s)~="table" then return nil,"Can't read the heist board." end
        if s.session~=true then return nil,"Enter GTA Online first." end
        if s.activity~=false then return nil,"Leave the current mission first." end
        if not number_ok(s.player) or s.player<0 or s.player>31 or (s.slot~=0 and s.slot~=1) then
            return nil,"Couldn't identify your character."
        end
        if not number_ok(s.saved_root) or not number_ok(s.stage) then
            return nil,"Saved heist isn't available."
        end
        if not s.board_open then return nil,"Open your apartment heist board first." end
        if s.owner~=s.player then return nil,"This isn't your planning board." end
        if not valid_string(s.board_uid) or not number_ok(s.board_root) then
            return nil,"Planning board isn't ready yet."
        end
        if s.board_root%4294967296~=s.saved_root%4294967296 then
            return nil,"The board shows a different heist."
        end
        if not number_ok(s.count) or s.count<1 or s.count>7
            or not number_ok(s.missions) or s.missions~=s.count then
            return nil,"Board entries: "..tostring(s.count).."; saved setups: "..tostring(s.missions)..". Press Log Board Details."
        end
        if not number_ok(s.dirty) then return nil,"Planning board isn't ready yet." end
        return s
    end
    function api.Check()
        local s,why=inspect()
        if not s then return result(false,why) end
        if pending then return result(true,"Waiting for the board to update.")end
        if s.dirty~=0 then return result(false,"The board is busy. Try again shortly.")end
        return result(true,"Planning board is ready.")
    end
    function api.Refresh()
        if pending then return result(false,"The board is already updating.")end
        local before,why=inspect()
        if not before then return result(false,why)end
        if before.dirty~=0 then return result(false,"The board is busy. Try again shortly.")end
        local now=host.now()
        if not valid_time(now) then return result(false,"Game timer isn't available.")end
        local s=inspect()
        if not s or not same(before,s) or s.dirty~=0 then
            return result(false,"Planning board changed. Check it again.")
        end
        local ok,accepted=pcall(host.set_dirty)
        if not ok or accepted~=true then return result(false,"Couldn't refresh the board.")end
        pending={snapshot=before,started=now,deadline=now+5000}
        last_poll=0
        return result(true,"Refreshing the planning board...")
    end
    function api.Tick()
        if not pending then return nil end
        local now=host.now()
        if not valid_time(now) or now<pending.started or now>=pending.deadline then
            pending=nil;return result(false,"The board didn't update. Open it again.")
        end
        if last_poll~=0 and now-last_poll<100 then return nil end
        last_poll=now
        local fresh=inspect()
        if not fresh or not same(fresh,pending.snapshot) then
            pending=nil;return result(false,"Heist or board changed. Try again.")
        end
        if fresh.dirty~=0 then return nil end
        local ok,matched=pcall(host.status_matches,fresh)
        if not ok or matched~=true then return nil end
        pending=nil
        return result(true,"Apartment board updated.")
    end
    function api.Snapshot()return{pending=pending~=nil,status=latest}end
    function api.Stop()pending=nil;latest="Stopped."end
    return api
end

local function read_bool(hash,...)
    local ok,value=pcall(Natives.InvokeBool,hash,...)
    if ok and type(value)=="boolean" then return value end
 return nil
end
local function read_int_native(hash,...)
    local ok,value=pcall(Natives.InvokeInt,hash,...)
    return ok and number_ok(value) and value or nil
end
local function global_int(i)
    local ok,v=pcall(ScriptGlobal.GetInt,i)
    return ok and number_ok(v) and v or nil
end
local function global_string(i)
    local ok,v=pcall(ScriptGlobal.GetString,i)
    return ok and type(v)=="string" and v or nil
end
local function read_stat(name)
    if type(Memory)~="table" or type(Memory.AllocInt)~="function" then return nil end
    local ok,ptr=pcall(Memory.AllocInt)
    if not ok or not number_ok(ptr) or ptr==0 then return nil end
    local value
    pcall(function()
        Memory.WriteInt(ptr,0)
        if Natives.InvokeBool(H.stat_int,Utils.Joaat(name),ptr,-1)==true then
            local n=Memory.ReadInt(ptr)
            if number_ok(n)then value=n end
        end
    end)
    pcall(Memory.Free,ptr)
    return value
end
local function get_missions(slot)
    local count,ended=0,false
    for i=1,7 do
        local name="MP"..slot.."_HEIST_MISSION_RCONT_ID_"..i
        local ok,s=pcall(Natives.InvokeString,H.stat_string,Utils.Joaat(name),-1)
        if not ok or type(s)~="string"then return nil end
        if not valid_string(s)then ended=true
        elseif ended then return nil
        else count=count+1 end
    end
    return count
end
local host={}
function host.now()
    local ok,t=pcall(function()return Time.GetEpocheMs()end)
    if ok and valid_time(t)then return t end
    return math.floor((os.clock()or 0)*1000)
end
function host.inspect()
    local session=read_bool(H.session)
    local activity=read_bool(H.activity)
    local player=read_int_native(H.player)
    local slot=read_stat("MPPLY_LAST_MP_CHAR")
    if session~=true or activity~=false or not player or slot~=0 and slot~=1 then
        return{session=session,activity=activity,player=player,slot=slot}
    end
    local saved_root=read_stat("MP"..slot.."_HEIST_MISSION_RCONT_ID_0")
    local stage=read_stat("MP"..slot.."_HEIST_PLANNING_STAGE")
    local board_uid=global_string(G.root)
    return {
        session=session,activity=activity,player=player,slot=slot,
        saved_root=saved_root,stage=stage,
        missions=get_missions(slot),
        board_open=valid_string(board_uid),board_uid=board_uid,
        board_root=valid_string(board_uid)and Utils.Joaat(board_uid)or nil,
        owner=global_int(G.owner),count=global_int(G.count),
        dirty=global_int(G.dirty)
    }
end
function host.set_dirty()
    -- The ONLY in-game write in this entire script.
    local ok=pcall(ScriptGlobal.SetInt,G.dirty,1)
    return ok and global_int(G.dirty)==1
end
function host.status_matches(s)
    local player_base=G.player_base+s.player*77
    for i=0,s.count-1 do
        local target=(s.stage&(1<<(i*3)))~=0 and 0 or -1
        if global_int(G.status+i)~=target or global_int(player_base+1+i)~=target then
            return false
        end
    end
    return true
end

local board=new_controller(host)
return {Controller=board,Host=host,NewController=new_controller}
end)()

