local function int32(old, key)
    local value = old[key]
    assert(type(value) == "number" and value % 1 == 0
        and value >= -2147483648 and value <= 2147483647,
        "Unreadable Cayo stat: " .. key)
    return value
end

local TYPES = { "CASH", "WEED", "COKE", "GOLD" }
local function replace_mask(old, mask, value)
    return (old & ~mask) | (value & mask)
end
local function utility_seed(value, mask)
    return (value & 0xFFFF) ~= 0 and value or (value | mask)
end
local function finite(value)
    return type(value) == "number" and value == value and math.abs(value) < math.huge
end
local function float32(value)
    return (string.unpack("<f", string.pack("<f", value)))
end
local function new_random(seed)
    seed = seed or 1
    assert(finite(seed), "Invalid setup seed.")
    local state = math.floor(seed) % 2147483647
    if state <= 0 then state = state + 2147483646 end
    return function(low, high)
        state = (state * 48271) % 2147483647
        return low + state % (high - low + 1)
    end
end
local function loot_masks(kind, first_run, random)
    local result = { I = {}, C = {} }
    for _, region in ipairs({ "I", "C" }) do
        for _, name in ipairs(TYPES) do result[region][name] = 0 end
        local normal = profile.loot.normal_types[region]
        local positions = {}
        for spot = 0, (region == "I" and 23 or 7) do
            if region ~= "I" or not first_run or (spot ~= 6 and spot ~= 7 and spot ~= 11 and spot ~= 12) then
                positions[#positions+1] = spot
            end
        end
        for i = #positions, 2, -1 do
            local j = random(1, i)
            positions[i], positions[j] = positions[j], positions[i]
        end
        for i, spot in ipairs(positions) do
            local name
            if kind == "MIXED" then name = normal[(i - 1) % #normal + 1]
            else
                for _, eligible in ipairs(normal) do if kind == eligible then name = kind end end
            end
            if name then result[region][name] = result[region][name] | (1 << spot) end
        end
        if region == "I" and first_run then result.I.WEED = result.I.WEED | 0xC0 end
    end
    return result
end
local function default_amount(old, name, target, random)
    local value = old["H4LOOT_" .. name:upper() .. "_V"]
    assert(value >= 0, "Invalid secondary loot value.")
    if value > 0 then return value end
    local g = old._globals or {}
    local low, high, multiplier = g[name .. "_min"], g[name .. "_max"], g["multiplier_" .. target]
    assert(finite(low) and finite(high) and low % 1 == 0 and high % 1 == 0
        and low > 0 and high >= low and high <= 10000000, "Normal loot defaults are unavailable.")
    assert(finite(multiplier) and multiplier >= 0.01 and multiplier <= 10, "Normal loot multiplier is unavailable.")
    -- Source func637: uniform integer range, ceil to $100, then target multiplier.
    local normal = math.ceil(float32(float32(random(low, high)) / 100)) * 100
    return multiplier == 1 and normal or math.ceil(float32(float32(normal) * float32(multiplier)))
end

function profile.build(selection, old)
    selection, old = selection or {}, old or {}
    local target = selection.target
    assert(type(target) == "number" and target % 1 == 0 and target >= 0 and target <= 5,
        "Choose a Target first.")
    for _, key in ipairs(profile.stat_keys) do int32(old, key) end
    for _, key in ipairs(profile.context_stat_keys) do int32(old, key) end
    assert(old.IH_SUB_OWNED > 0, "Own a Kosatka first.")
    local secondary = selection.secondary or "MIXED"
    assert(secondary == "CASH" or secondary == "WEED" or secondary == "COKE"
        or secondary == "GOLD" or secondary == "MIXED", "Choose a Secondary Target first.")
    local first_run = (old.H4_PROGRESS & 2) == 0
    local random = new_random(selection.seed)
    local masks = loot_masks(secondary, first_run, random)
    local weapons = old.H4CNF_WEAPONS
    if weapons < 1 or weapons > 5 then weapons = 1 end
    local values = {
        H4CNF_TARGET = target,
        H4_MISSIONS = old.H4_MISSIONS | 0xFFFF,
        H4CNF_BS_GEN = old.H4CNF_BS_GEN | 0x1FFFF,
        H4CNF_BS_ENTR = old.H4CNF_BS_ENTR | 0x3F,
        H4CNF_BS_ABIL = old.H4CNF_BS_ABIL | 0x3F,
        H4CNF_WEAPONS = weapons,
        H4CNF_APPROACH = old.H4CNF_APPROACH | 0xFF,
        H4CNF_GRAPPEL = utility_seed(old.H4CNF_GRAPPEL, 0x1111),
        H4CNF_UNIFORM = utility_seed(old.H4CNF_UNIFORM, 0x1111),
        H4CNF_BOLTCUT = utility_seed(old.H4CNF_BOLTCUT, first_run and 0x1141 or 0x1111),
        H4CNF_TROJAN = old.H4CNF_TROJAN >= 1 and old.H4CNF_TROJAN <= 5 and old.H4CNF_TROJAN or 1,
        H4CNF_WEP_DISRP = 3,
        H4CNF_ARM_DISRP = 3,
        H4CNF_HEL_DISRP = 3,
        H4LOOT_PAINT = old.H4LOOT_PAINT | 0x7F,
        H4LOOT_PAINT_SCOPED = old.H4LOOT_PAINT_SCOPED | 0x7F,
        H4_PROGRESS = old.H4_PROGRESS | 0x21,
    }
    for _, region in ipairs({ "I", "C" }) do
        local mask = region == "I" and 0xFFFFFF or 0xFF
        for _, name in ipairs(TYPES) do
            local key = "H4LOOT_" .. name .. "_" .. region
            values[key] = replace_mask(old[key], mask, masks[region][name])
            values[key .. "_SCOPED"] = replace_mask(old[key .. "_SCOPED"], mask, masks[region][name])
        end
    end
    for _, name in ipairs({ "cash", "weed", "coke", "gold", "paint" }) do
        values["H4LOOT_" .. name:upper() .. "_V"] = default_amount(old, name, target, random)
    end
    return values
end

