local function active(s)
 assert(s.phase==9 and has(s.flags,17) and has(s.flags,19) and not has(s.flags,16),
  'Wait until the finale has started and mission objectives are active.')
 for team=0,3 do assert(not has(s.flags,20+team),'The game already recorded a failed team. Restart this finale.')end
 assert(not has(s.gate,11),'The mission already has an end request.')
end
local function plan(s)
 active(s)
 local fields={}
 local function add(index,old,new)
  assert(integer(old) and integer(new),'Mission score is outside the supported integer range.')
  if old~=new then fields[#fields+1]={index=index,old=old,value=new}end
 end
 local flags=s.flags
 local occupied=0
 for team=0,s.teams-1 do
  if has(s.flags,team)then
   occupied=occupied+1
   local stage=li(s.hash,L.stage+team)
   assert(stage>=0 and (stage<=17 or stage==99999),'Mission objective stage is unreadable.')
   local score=li(s.hash,L.score+team)
   local goal=gi(4718592+3838+1+team*26988+59)
   assert(score>=0 and goal>=-1,'Mission goal is unreadable.')
   if goal==-1 then goal=math.max(1,li(s.hash,L.players+team))
   elseif goal==0 then goal=1 end
   local delta=math.max(0,goal-score)
   if delta>0 then
    -- Match func_767/768: increase total, earned score and active-stage score.
    add(L.score+team,score,score+delta)
    local bonus=li(s.hash,L.bonus_score+team)
    add(L.bonus_score+team,bonus,bonus+delta)
    if stage<17 then
     local current=li(s.hash,L.stage_score+team)
     add(L.stage_score+team,current,current+delta)
    end
   end
  end
  flags=flags|(1<<(9+team))
 end
 assert(occupied>0,'Mission teams have not become active yet.')
 add(L.flags,s.flags,flags)
 -- Publish only after all score/end-state data has been written and read back.
 add(L.result_gate,s.gate,s.gate|(1<<11))
 return fields
end
local function new_controller(h)
 local pending,last=nil,'IDLE: Start an apartment finale, then click Instant Finish.'
 local c={}
 local function trace(s,reason)
  if not s then log(reason);return end
  log(reason..' heist='..s.name..' mission='..s.mission..' pid='..s.pid
   ..' thread='..s.thread..' ptr='..s.pointer..' crew='..s.party..' teams='..s.teams
   ..' phase='..s.phase..' flags='..s.flags..' result_gate='..s.gate
   ..' crew_flags='..tostring(s.crew_flags))
 end
 local function same(s)
  local ok,fresh=pcall(h.capture)
  if ok and fresh.identity==s.identity and fresh.teams==s.teams then return fresh end
 end
 function c.Request()
  if pending then return false,'A finish request is already being observed.'end
  local s,fields,attempted
  local ok,why=pcall(function()
   s=h.capture();active(s);h.verify(s)
   local fresh=assert(same(s),'Mission changed during verification.');active(fresh)
   assert(fresh.flags==s.flags and fresh.gate==s.gate,'Mission state changed during verification.')
   fields=plan(s);attempted={}
   trace(s,'submit')
   for _,f in ipairs(fields)do
    local current=assert(same(s),'Mission changed before result submission.')
    assert(current.phase==9 and not has(current.flags,16),'GTA already started result processing.')
    for team=0,3 do assert(not has(current.flags,20+team),'A team failed before submission.')end
    assert(li(s.hash,f.index)==f.old,'Mission data changed before submission.')
    attempted[#attempted+1]=f
    ScriptLocal.SetInt(s.hash,f.index,f.value)
    assert(same(s),'Mission changed during a result write.')
    assert(li(s.hash,f.index)==f.value,'GTA rejected a result write.')
   end
   pending={context=s,started=h.now(),stamp=''}
  end)
  if not ok then
   -- Roll back only this exact still-active VM and values we still own.
   -- Once GTA begins result processing these fields belong to GTA.
   local current=s and same(s)
   local restore_ok=true
   if attempted and current and current.phase==9 and not has(current.flags,16)then
    for n=#attempted,1,-1 do
     local f=attempted[n]
     local restored=pcall(function()
      local fresh=assert(same(s));assert(fresh.phase==9 and not has(fresh.flags,16))
      if li(s.hash,f.index)==f.value then
       ScriptLocal.SetInt(s.hash,f.index,f.old)
       assert(li(s.hash,f.index)==f.old)
      end
     end)
     restore_ok=restore_ok and restored
    end
   end
   last='UNAVAILABLE: '..clean(why)
   if not restore_ok then last=last..' Some submitted values could not be restored.'end
   trace(current,last);return false,last
  end
  last='SUBMITTED: '..s.name..'. Waiting for GTA result processing.'
  return true,last
 end
 function c.Tick()
  if not pending then return nil end
  local p=pending
  local s=same(p.context)
  if not s then
   pending=nil;last='UNCONFIRMED: The mission context ended or changed before a result was observed.'
   log(last);return false,last
  end
  local stamp=s.phase..':'..s.flags..':'..s.gate
  if stamp~=p.stamp then trace(s,'observe');p.stamp=stamp end
  for team=0,3 do
   if has(s.flags,20+team)then
    pending=nil;last='FAILED: GTA recorded a failed team. Check the game result.'
    trace(s,last);return false,last
   end
  end
  if s.phase==12 and has(s.flags,16)then
   pending=nil;last='RESULT: GTA reached result processing. Check the result screen and payment.'
   trace(s,last);return true,last
  end
  if h.now()-p.started>=20000 then
   pending=nil;last='UNCONFIRMED: No result stage observed after 20 seconds. Check Show Status.'
   trace(s,last);return false,last
  end
  return nil
 end
 function c.Status()return last end
 function c.ShowStatus()
  local ok,s=pcall(h.capture)
  if ok then
   trace(s,'status')
   pcall(function()
    for team=0,s.teams-1 do
     assert(same(s),'Mission changed during status capture.')
     log('team='..team..' players='..li(s.hash,L.players+team)
      ..' stage='..li(s.hash,L.stage+team)..' score='..li(s.hash,L.score+team)
      ..' goal='..gi(4718592+3838+1+team*26988+59)
      ..' minimum='..gi(4718592+196663+1+team))
    end
   end)
  else log('status unavailable: '..clean(s))end
  return last
 end
 function c.Stop()
  if pending then last='UNCONFIRMED: Observation stopped before confirming a result.'end
  pending=nil
 end
 return c
end
local controller=new_controller(host)
return {Controller=controller,Host=host,NewController=new_controller,Active=active}
end)()


-- SOURCE f.lua; controller body copied without standalone UI registration.
local ApartmentSolo=(function()

-- Apartment Solo Launch, standalone prototype v2 / Enhanced 1.73.
-- Enable before opening your finale lobby. Start the job normally.
-- No auto-start, ready-state, cut, reward, objective, or bytecode writes.
-- Live mission entry and payment are not yet verified.
local TITLE='Apartment Solo Launch'
local ROWS={{9188,'The Fleeca Job'},{9193,'The Prison Break'},
 {9200,'The Humane Labs Raid'},{9206,'Series A Funding'},
 {9212,'The Pacific Standard Job'},{9213,'The Pacific Standard Job'},{9220,'The Pacific Standard Job'}}
-- Exact, unique collected-bytecode anchors: launcher solo normalization,
-- selected-job minimum assignment and catalogue ID lookup.
local SIGNATURES={
 '2D 00 02 00 00 61 00 00 48 64 A7 20 02 3F 2F 5D 9A C5 20 06 56 03 00 2E 00 00 72 61 00 00 48 48 B9 0E 72 71 61 00 00 48 46 BF 0E 36 01 71 71 61 00 00 48 64 37 00 03 3F 36 01 2E 00 00',
 '05 38 1B 4F E4 4E 42 20 38 1A 4F E4 4E 42 0F 5D C0 BD 28 2A 56 0F 00 61 00 00 48 64',
 '2D 01 04 00 00 38 00 40 03 2C 05 07 A6 56 04 00 70 2E 01 01 38 00 41 01 5D 85 EF 2B 56 13 00 38 00 5D 60 EF 2B 56 06 00 43 0F 27 2E 01 01 70 2E 01 01',
 '2D 01 12 00 00 37 03 2A 40 02 70 31 2B 2A 40 05 70 31 2B 2A 40 06 70 31 2B 2A 40 0B 70 31 2B 2A 40 0D 70 31 2B 2B 38 00 5D 0A ED 2B 39 11 38 11 70 57 08 00 25 0E 37 03 32 2E 01 0E 38 00 41 02 65 02 3F 00 00 00 09 00 3E 00 00 00 16 00 55 24 00 25 0E 38 11 61 6D 21 0C 64 57 33 02 3F 34 0E 32 2E 01 0E 25 0E 38 11 61 12 A8 0E 46 61 76 34 0E 32 2E 01 0E 25 0E 37 03 32 2E 01 0E',
}
local function integer(v)return type(v)=='number' and v%1==0 and v>=-2147483648 and v<=2147483647 end
local function bit(v,n)return integer(v) and (v&(1<<n))~=0 end
local function reason(err)return tostring(err):gsub('^.-:%d+:%s*','')end
local function log(text)
 if Logger and Logger.LogInfo then pcall(Logger.LogInfo,'['..TITLE..' v2] '..tostring(text))end
end
local function say(text)
 log(text)
 if GUI and GUI.AddToast then pcall(GUI.AddToast,TITLE,tostring(text),6500,eToastPos.TOP_RIGHT)end
end
local function ni(h,...)
 local ok,v=pcall(Natives.InvokeInt,h,...);assert(ok and integer(v),'Native state is unreadable.');return v
end
local function nb(h,...)
 local ok,v=pcall(Natives.InvokeBool,h,...);assert(ok and type(v)=='boolean','Native flag is unreadable.');return v
end
local function gi(i)
 local v=ScriptGlobal.GetInt(i);assert(integer(v),'Global state is unreadable.');return v
end
local function li(hash,i)
 local v=ScriptLocal.GetInt(hash,i);assert(integer(v),'Launcher local is unreadable.');return v
end
local function identify(hash)
 local found
 for _,row in ipairs(ROWS)do
  local known=gi(262145+row[1])
  if known~=0 and known%4294967296==hash%4294967296 then
   assert(not found or found==row[2],'Finale identity is ambiguous.');found=row[2]
  end
 end
 return found
end
local host={}
local epoch=1
function host.now()return Time.GetEpocheMs()end
function host.world()
 local s={session=nb(0xD83C2B94E7508980),epoch=epoch}
 if not s.session then return s end
 s.pid=ni(0x4F8644AF03D0E0D6);assert(s.pid>=0 and s.pid<=31,'Player is unavailable.')
 s.mission=gi(4858023)
 s.classic=ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller'))
 s.modern=ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller_2020'))
 s.launchers=ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fmmc_launcher'))
 assert(s.classic>=0 and s.modern>=0 and s.launchers>=0,'Script counts are unreadable.')
 return s
end
function host.catalogue_matches(c)
 return gi(c.header)==c.count and bit(gi(c.base+82),13)
  and ScriptGlobal.GetString(c.base)==c.id
  and (not c.content_index or gi(c.content_index)%4294967296==Utils.Joaat(c.id)%4294967296)
  and (not c.root_index or gi(c.root_index)%4294967296==c.root%4294967296)
end
function host.lobby()
 local w=host.world()
 assert(w.session and w.classic==0 and w.modern==0 and w.launchers==1,
  'Waiting for your apartment finale lobby.')
 local name=identify(w.mission);assert(name,'Waiting for a recognized apartment finale.')
 local hash=Utils.Joaat('fmmc_launcher')
 local s={hash=hash,pid=w.pid,mission=w.mission,name=name,epoch=w.epoch}
 Script.ExecuteAsScript(hash,function()
  local actual=ni(0x8A1C8B1738FFE87E)
  assert(actual%4294967296==hash%4294967296,'Launcher script context changed.')
  s.thread=ni(0xC30338E8088E2E21)
 end)
 assert(integer(s.thread) and s.thread>0 and nb(0x46E9AE36D8FA6417,s.thread),'Launcher instance is unavailable.')
 s.pointer=ScriptLocal.GetPtr(hash,20211)
 assert(type(s.pointer)=='number' and s.pointer>=65536,'Launcher allocation is unavailable.')
 local transition_host=nb(0x0B824797C9BF2159)
 local transition_started=nb(0x53FA83401D9C07FE)
 assert(transition_host or (not transition_started and gi(1942042)==s.pid),
  'Waiting for your own hosted finale lobby.')
 s.role=gi(1845473+s.pid*884)
 s.teams=gi(4722365)
 if transition_host then
  s.solo=gi(2688930)==1
  if s.role==-1 then s.role=0 end -- Before planning-role assignment.
 else
  local mask=gi(1941375)
  local count,local_only=0,true
  if mask>=1 and mask<=15 then
   for slot=0,3 do if bit(mask,slot)then
    count=count+1
    if gi(1936419+slot)~=s.pid then local_only=false end
   end end
  end
  s.solo=count==1 and local_only
 end
 s.metadata=bit(gi(1845360+s.pid*884),0) or bit(gi(2688934),5)
 local namespace,row=li(hash,20229),li(hash,20230)
 local table_info=({[63]={794993,1518,939205},[62]={962334,300,990836}})[namespace]
 assert(table_info and row>=0 and row<table_info[2],'Selected job catalogue is not ready.')
 local id=ScriptLocal.GetString(hash,20294)
 assert(type(id)=='string' and #id>0 and #id<=63,'Selected content ID is not ready.')
 local base=table_info[1]+1+row*95
 local metadata=table_info[3]+row*14
 -- func_9050 hashes the content ID against metadata.f_3. It separately
 -- obtains the mission ROOT from metadata.f_1 through func_9079/9081.
 -- Those hashes are not interchangeable, even for a correctly selected job.
 assert(gi(metadata+3)%4294967296==Utils.Joaat(id)%4294967296,
  'Selected content ID does not match its catalogue metadata.')
 if namespace==63 then
  assert(gi(metadata+1)%4294967296==s.mission%4294967296,
   'Catalogue root is still updating (catalogue='..gi(metadata+1)..', mission='..s.mission..').')
 end
 s.catalogue={id=id,base=base,index=base+75,header=table_info[1],count=table_info[2],
  content_index=metadata+3,root_index=namespace==63 and metadata+1 or nil,root=s.mission}
 assert(host.catalogue_matches(s.catalogue),'Selected job catalogue changed or is not loaded.')
 s.identity=table.concat({s.pid,s.epoch,s.mission%4294967296,s.thread,s.pointer,id,base},':')
 assert(ScriptLocal.GetPtr(hash,20211)==s.pointer,'Launcher allocation changed.')
 return s
end
function host.verify(s)
 assert(Memory and type(Memory.ScanScript)=='function','Script layout verification is unavailable.')
 for _,pattern in ipairs(SIGNATURES)do
  local ptr=Memory.ScanScript(s.hash,pattern)
  assert(type(ptr)=='number' and ptr>=65536,'This launcher does not match the tested Enhanced layout.')
 end
end
function host.read(kind,index,s)
 return kind=='l' and li(s.hash,index) or gi(index)
end
function host.write(kind,index,value,s)
 if kind=='l'then ScriptLocal.SetInt(s.hash,index,value)else ScriptGlobal.SetInt(index,value)end
 assert(host.read(kind,index,s)==value,'GTA rejected a minimum-player write.')
end
local function make_plan(h,s)
 assert(s.solo,'Waiting for exactly one player in your hosted lobby.')
 assert(s.role==0,'Select the first role/team for the solo host.')
 assert(integer(s.teams) and s.teams>=1 and s.teams<=4,'Team definitions are not ready.')
 local fields={}
 local function add(kind,index,value,minimum,maximum,catalogue)
  local old=h.read(kind,index,s)
  assert(integer(old) and old>=minimum and old<=maximum,'A player or crew minimum is not ready.')
  fields[#fields+1]={kind=kind,index=index,old=old,value=value,catalogue=catalogue,owned=false}
 end
 add('g',4722361,1,1,4) -- Global_4718592.f_3769, overall minimum.
 add('l',20211,1,1,4) -- iLocal_20196.f_15, invite-lobby copy.
 for team=0,s.teams-1 do
  add('g',4722368+team,team==0 and 1 or 0,0,4)
  local crew=h.read('g',4915256+team,s)
  assert(integer(crew) and (crew==11 or crew>=0 and crew<=4),'Controller crew minimum is not ready.')
  add('g',4915256+team,0,0,11)
 end
 -- trcmn role minima are independent of tcmin. Zero means no absent role
 -- can invalidate admission; role definitions/objectives themselves stay intact.
 if bit(h.read('g',4718606,s),6)then
  for team=0,s.teams-1 do for role=0,3 do add('g',4915262+team*5+role,0,0,4)end end
 end
 add('g',4722364,1,1,4) -- Default active team count.
 add('g',4722366,1,0,4) -- Minimum team count.
 add('g',4722365,1,1,4) -- Defined count: loader otherwise resets the default.
 add('g',s.catalogue.index,1,1,4,s.catalogue)
 if s.metadata then add('g',1048584,1,1,4)end
 return fields
end
local function new_controller(h)
 local enabled,transaction=false,nil
 local latest='OFF: Enable before opening an apartment finale lobby.'
 local c={}
 local function status(text)if latest~=text then latest=text;log(text)end;return text end
 local function world()local ok,w=pcall(h.world);return ok and w or nil end
 local function current(t)
  local ok,s=pcall(h.lobby)
  if ok and s.identity==t.context.identity then return s end
 end
 local function scope(t,w)
  return w and w.session and w.pid==t.context.pid and w.epoch==t.context.epoch
 end
 local function restore(t,catalogue_only)
  local w=world()
  if not scope(t,w)then return true end
  local s=current(t)
  local matching=w.mission==t.context.mission
  local cancelled=w.mission==0 and w.classic==0 and w.modern==0 and w.launchers==0
  local ordinary=not catalogue_only and matching and w.classic==0 and w.modern==0
   and (w.launchers==0 or s~=nil)
  local all=true
  for n=#t.fields,1,-1 do
   local f=t.fields[n]
   if f.owned then
    local eligible=f.catalogue and (matching or cancelled) and (w.classic==1 or w.launchers==0 or s~=nil)
     or not f.catalogue and ordinary and (f.kind~='l' or s~=nil)
    if eligible then
     local ok=pcall(function()
      local fresh=world();assert(scope(t,fresh),'Restoration context changed.')
      local cancelled_now=fresh.mission==0 and fresh.classic==0 and fresh.modern==0 and fresh.launchers==0
      assert(fresh.mission==t.context.mission or f.catalogue and cancelled_now,'Job changed during restoration.')
      if f.catalogue then
       if not h.catalogue_matches(f.catalogue)then f.owned=false;return end
      else
       assert(fresh.classic==0 and fresh.modern==0 and (fresh.launchers==0 or current(t)),
        'A new mission started during restoration.')
       if f.kind=='l'then assert(current(t),'Launcher instance changed.')end
      end
      if h.read(f.kind,f.index,t.context)==f.value then
       h.write(f.kind,f.index,f.old,t.context)
       assert(h.read(f.kind,f.index,t.context)==f.old,'Restoration readback failed.')
      end
      f.owned=false
     end)
     all=all and ok
    end
   end
  end
  return all
 end
 local function apply(s)
  local t={context=s,fields={},reapplications=0,started=h.now()}
  local ok,why=pcall(function()
   h.verify(s);t.fields=make_plan(h,s)
   transaction=t
   for _,f in ipairs(t.fields)do
    local fresh=assert(current(t),'Launcher changed during solo admission.')
    assert(fresh.solo and fresh.role==0,'The lobby crew or role changed.')
    assert(h.read(f.kind,f.index,s)==f.old,'A minimum changed before application.')
    if f.old~=f.value then
     f.owned=true -- Include setters that mutate then throw.
     h.write(f.kind,f.index,f.value,s)
     assert(current(t),'Launcher changed after a minimum write.')
     assert(h.read(f.kind,f.index,s)==f.value,'Solo minimum readback failed.')
    end
   end
  end)
  if not ok then
   enabled=false
   local restored=restore(t,false)
   if restored then transaction=nil end
   return status('FAILED: '..reason(why)..(restored and '' or ' Restoration is pending.'))
  end
  log('applied heist='..s.name..' mission='..s.mission..' thread='..s.thread..' fields='..#t.fields)
  return status('APPLIED: Solo admission settings are active. Start the finale normally.')
 end
 function c.SetEnabled(value)
  value=value==true
  if enabled==value then return true,latest end
  enabled=value
  if enabled then return true,status('WAITING: Open your hosted apartment finale lobby with one player.')end
  local t=transaction
  if t then
   local w=world()
   if not scope(t,w) or w.mission~=t.context.mission then restore(t,true);transaction=nil
   elseif w.classic>0 then
    t.mission_seen=true;restore(t,true)
    return true,status('MISSION: Solo Launch off; keeping this finale admission until it ends.')
   elseif current(t)then
    if restore(t,false)then transaction=nil
    else return false,status('RESTORING: Some owned minima could not be restored yet.')end
   else
    t.handoff=t.handoff or h.now()
    return true,status('HANDOFF: Waiting for the current launch to settle before restoring.')
   end
  end
  return true,status('OFF: Solo Launch disabled.')
 end
 function c.Tick()
  local w=world()
  if not w then return status('WAITING: GTA state is temporarily unreadable.')end
  local t=transaction
  if t then
   if not scope(t,w) or w.mission~=t.context.mission then
    -- Never replay snapshots into a new session, character or job.
    restore(t,true) -- Only an independently identified cancelled-job catalogue row.
    transaction=nil
    return status('WAITING: Previous launch context ended; old snapshots released.')
   end
   if w.classic==1 and w.modern==0 then
    t.mission_seen=true;restore(t,true)
    return status('MISSION: Apartment mission controller observed. Keep this Lua loaded through the result.')
   end
   if t.mission_seen then
    if restore(t,false)then transaction=nil
    else return status('RESTORING: Waiting to restore the finished mission minima.')end
    return status(enabled and 'WAITING: Mission ended. Waiting for your next solo lobby.' or 'OFF: Finished mission minima released.')
   end
   if w.launchers==0 then
    t.handoff=t.handoff or h.now()
    if h.now()-t.handoff<30000 then return status('HANDOFF: Waiting for the finale controller.')end
    if restore(t,false)then transaction=nil end
    return status('UNCONFIRMED: No mission controller observed after 30 seconds. Check Show Status.')
   end
   local s=current(t)
   if not s then return status('WAITING: Launcher identity is temporarily unavailable; no writes.')end
   t.handoff=nil
   if not enabled or not s.solo or s.role~=0 or s.metadata~=t.context.metadata then
    if not restore(t,false)then return status('RESTORING: Waiting to release the previous lobby settings.')end
    transaction=nil
    if not enabled then return status('OFF: Solo Launch disabled.')end
    if not s.solo or s.role~=0 then return status('WAITING: Solo Launch needs one host in the first role.')end
    local ok,fresh=pcall(h.lobby);if ok then return apply(fresh)end
    return status('WAITING: Lobby is changing.')
   end
   local ok,why=pcall(function()
    for _,f in ipairs(t.fields)do
     assert(current(t),'Launcher changed during minimum maintenance.')
     local value=h.read(f.kind,f.index,t.context)
     if value~=f.value then
      assert(f.owned and value==f.old,'A minimum was edited independently; stopping Solo Launch.')
      assert(t.reapplications<32,'GTA repeatedly reset the solo settings; check Show Status.')
      if f.catalogue then assert(h.catalogue_matches(f.catalogue),'Catalogue row changed.')end
      h.write(f.kind,f.index,f.value,t.context)
      assert(h.read(f.kind,f.index,t.context)==f.value,'Maintenance readback failed.')
      t.reapplications=t.reapplications+1
     end
    end
   end)
   if not ok then
    enabled=false
    if restore(t,false)then transaction=nil end
    return status('FAILED: '..reason(why))
   end
   return latest
  end
  if not enabled then return latest end
  if not w.session or w.classic~=0 or w.modern~=0 or w.launchers~=1 then
   return status('WAITING: Open your hosted apartment finale lobby before starting the mission.')
  end
  local ok,s=pcall(h.lobby)
  if not ok then return status('WAITING: '..reason(s))end
  if not s.solo or s.role~=0 then return status('WAITING: Solo Launch needs one host in the first role.')end
  return apply(s)
 end
 function c.IsEnabled()return enabled end
 function c.Status()return latest end
 function c.Reset()transaction=nil;status('WAITING: Session changed; prior snapshots discarded.')end
 function c.Unload()
  enabled=false
