 a.active=a.phase==9 and bit(a.flags,17) and bit(a.flags,19) and not bit(a.flags,16)
 for n=20,23 do if bit(a.flags,n)then a.active=false end end
 a.identity=table.concat({a.pid,a.slot,a.mission%4294967296,a.thread,a.pointer,a.index},':')
