local function active_ok(a)
 assert(a and a.active==true and a.phase==9 and bit(a.flags,17) and bit(a.flags,19)
  and not bit(a.flags,16),'Finale is not active.')
 for n=20,23 do assert(not bit(a.flags,n),'Finale already failed.')end
 assert(a.hard==true,'Use Hard difficulty for the 12M Bonus.')
 assert(a.deaths==0,'12M Bonus unavailable after a crew death.')
