local function plan(rows)
 assert(type(rows)=='table' and #rows==3,'Bonus data unavailable.')
 local fields,total={},0
 for i,r in ipairs(rows)do
  assert(type(r.flag)=='boolean' and integer(r.progress) and r.progress>=0 and r.progress<=FULL,'Invalid bonus state.')
  assert(r.disabled==false and integer(r.amount) and r.amount>0,'Bonus is unavailable for this job.')
  total=total+r.amount
  fields[#fields+1]={index=i,field='progress',old=r.progress,value=FULL,attempted=false}
 end
 assert(total==12000000,'Current game bonus amounts do not total 12M.')
 -- Seed first, then enable the game's result branch by clearing its latch.
 -- No "already earned" admission check: every new run is rearmed.
 for i,r in ipairs(rows)do
  fields[#fields+1]={index=i,field='flag',old=r.flag,value=false,attempted=false}
