 if ApartmentBonus.Controller.IsEnabled()then poll('apartment','bonus_status',ApartmentBonus.Controller.Tick)end
 if FLAGS.payout then
  local ok,r=pcall(ApartmentMax.Controller.Tick,3000000)
  if ok and r then message('apartment','payout_status',r.message);VIEW.apartment.payout_plan=detach(r.plan)end
  local ran,result=pcall(MaxPayout.Tick)
