local function binding(name)
    local raw = context_ref and context_ref.Raw
    if raw and raw[name] ~= nil then return raw[name] end
    return type(_G) == "table" and _G[name] or nil
end

local function log(level, message)
    local logger = context_ref and context_ref.Logger
    local callback = logger and logger[level]
    if type(callback) == "function" then callback(message, "HeistRuntime") end
end

local detection_messages = {}
local function log_detection(action, family, ready, reason)
    local key = tostring(action) .. ":" .. tostring(family)
    local value = tostring(ready) .. ":" .. tostring(reason)
    if detection_messages[key] == value then return end
    detection_messages[key] = value
    pcall(log, "Info", key .. " ready=" .. tostring(ready) .. " reason=" .. tostring(reason))
end

local function script_hash(name)
    local utils = binding("Utils")
    if not (utils and type(utils.Joaat) == "function") then return nil, "Utils.Joaat is unavailable" end
    local ok, result = pcall(utils.Joaat, name)
    if not ok then return nil, tostring(result) end
    local value = tonumber(result)
    if not value then return nil, "script hash was unavailable" end
    return value
end

local function thread_count(hash)
    if thread_query_fault then
        local now=runtime_time_ms()
        if now<thread_query_retry_ms and thread_query_retry_ms-now<=2000 then return nil,thread_query_fault end
        thread_query_fault=nil
    end
    local natives = binding("Natives")
    if not (natives and type(natives.InvokeInt) == "function") then
        thread_query_fault = "Cherax script-thread query is unavailable"
        thread_query_retry_ms=runtime_time_ms()+2000
        if not thread_query_warning_logged then
            log("Warning", thread_query_fault .. "; runtime detection will retry after two seconds.")
            thread_query_warning_logged = true
        end
        return nil, thread_query_fault
    end
    local ok, raw = pcall(natives.InvokeInt, THREAD_COUNT_HASH, hash)
    local value = ok and tonumber(raw) or nil
    if value == nil then
        thread_query_fault = ok and "script-thread query returned no value" or tostring(raw)
        thread_query_retry_ms=runtime_time_ms()+2000
        if not thread_query_warning_logged then
            log("Warning", "Script-thread detection unavailable: " .. thread_query_fault
                .. ". Retrying the read-only query after two seconds.")
            thread_query_warning_logged = true
        end
        return nil, thread_query_fault
    end
    return value
end

local function begin_explicit_thread_refresh()
    thread_query_fault = nil
    thread_query_retry_ms = 0
end

local function invalidate_runtime_detection()
    next_launch_tick_ms, next_launch_refresh_ms = 0, 0
    -- A real GTA session generation change may make a previously absent script
    -- available. Clear only cached detection state; rendering still performs no
    -- probe until the user or a guarded action requests an explicit refresh.
    app_cache = nil
    launch_cache = nil
    controller_cache = nil
    activity_cache = nil
    thread_query_fault = nil
    thread_query_warning_logged = false
    return true
end

local function board_status(family)
    local profile = BOARD_PROFILES[tostring(family or "")]
    if not profile then
        return { support = "UNSUPPORTED", ready = false, reason = "No current Enhanced board-refresh profile is validated for this heist." }
    end
    local script_local = binding("ScriptLocal")
    local available = script_local and type(script_local.GetInt) == "function"
        and type(script_local.SetInt) == "function"
    return {
        support = available and "EXPERIMENTAL" or "BLOCKED",
        ready = available == true,
        script = profile.script,
        local_index = profile.local_index,
        evidence = profile.evidence,
        source_revision = SOURCE_REVISION,
        observation = board_observations[profile.family] and board_observations[profile.family].state or "NOT_REQUESTED",
        reason = available and "Open this heist's planning board before requesting a refresh."
            or "This Cherax build does not expose the required ScriptLocal read/write capability.",
    }
end

-- Planning presentation scripts can be local-only. Do not require a network
-- script host or a heist roster to invalidate their cached screen.
local function board_identity(hash, index, allow_stopped)
    local core=context_ref and context_ref.CScript and context_ref.CScript.Economy
    local natives,locals,gta=binding("Natives"),binding("ScriptLocal"),binding("GTA")
    local ok,value=pcall(function()
        assert((started or allow_stopped==true) and core and type(core.CurrentSlot)=="function","character unavailable")
        local slot=core.CurrentSlot();assert(slot==0 or slot==1,"character unavailable")
        assert(natives.InvokeBool(0xD83C2B94E7508980)==true,"session unavailable")
        assert(natives.InvokeBool(0x520F3282A53D26B7)==false,"session transition")
        local pid=gta.GetLocalPlayerId();assert(type(pid)=="number" and pid>=0 and pid<=31,"player unavailable")
        local scope=table.concat({cut_generation,slot,pid},":")
        if not hash then return {scope=scope} end
        assert(thread_count(hash)==1,"planning script instance ambiguous")
        local ptr=locals.GetPtr(hash,index);assert(type(ptr)=="number" and ptr>=65536,"planning storage unavailable")
        return {scope=scope,key=scope..":"..tostring(ptr)}
    end)
    if not ok then return nil,"Board context unavailable: "..tostring(value) end
    return value
end

local function observe_boards()
    for family,observation in pairs(board_observations) do
        if observation.state=="SUBMITTED" or observation.state=="CLOSED_REOPEN_REQUIRED" then
            local scope=board_identity()
            local profile=BOARD_PROFILES[family]
            if not scope or scope.scope~=observation.identity.scope then
                observation.state="CONTEXT_CHANGED"
            else
                local count=thread_count(observation.hash)
                if count==0 then observation.state="CLOSED_REOPEN_REQUIRED"
                elseif count==1 then
                    local current=board_identity(observation.hash,profile.local_index)
                    if current and current.key~=observation.identity.key or observation.state=="CLOSED_REOPEN_REQUIRED" then
                        observation.state="REOPENED_UNVERIFIED"
                    elseif current then
                        local ok,value=pcall(binding("ScriptLocal").GetInt,observation.hash,profile.local_index)
                        local ready=ok and (profile.ready_values and profile.ready_values[value] or value==profile.ready_value)
                        if ready then observation.state="READY_DISPLAY_UNVERIFIED" end
                    end
                elseif count and count>1 then observation.state="CONTEXT_CHANGED" end
                if observation.state=="SUBMITTED" and runtime_time_ms()-observation.time>5000 then observation.state="UNOBSERVED_TIMEOUT" end
                if observation.state=="CLOSED_REOPEN_REQUIRED" and runtime_time_ms()-observation.time>30000 then observation.state="REOPEN_REQUIRED" end
            end
        end
    end
end

local function refresh_board(family)
    if not started then return false, "Heist runtime profiles are not ready." end
    begin_explicit_thread_refresh()
    local profile = BOARD_PROFILES[tostring(family or "")]
    if not profile then return false, "No current Enhanced board-refresh profile is validated for this heist." end
    local script_local = binding("ScriptLocal")
    if not (script_local and type(script_local.GetInt) == "function" and type(script_local.SetInt) == "function") then
        return false, "Board refresh is unavailable because Cherax ScriptLocal access is not exposed."
    end
    local hash, hash_err = script_hash(profile.script)
    if not hash then return false, hash_err end
    local threads, thread_err = thread_count(hash)
    if threads == nil then return false, thread_err end
    if threads ~= 1 then return false, "Open one planning screen, then retry Board Refresh." end

    local read_ok, before = pcall(script_local.GetInt, hash, profile.local_index)
    before = read_ok and tonumber(before) or nil
    if before == nil then
        return false, "The active planning board state could not be read safely. No write was attempted."
    end
    if before == profile.trigger_value then
        return true, "Planning board refresh is already pending."
    end
    local ready = profile.ready_values and profile.ready_values[before] == true
        or profile.ready_value ~= nil and before == profile.ready_value
    if not ready then
        return false, ("Planning board is not ready for refresh (state %s). No write was attempted."):format(tostring(before))
    end

    local identity,identity_err=board_identity(hash,profile.local_index)
    if not identity then return false,identity_err end
    board_observations[profile.family]={state="SUBMITTED",identity=identity,hash=hash,time=runtime_time_ms()}
    local write_ok, write_result = pcall(script_local.SetInt, hash, profile.local_index, profile.trigger_value)
    if not write_ok or write_result == false then
        board_observations[profile.family].state="SUBMISSION_FAILED"
        return false, "Board refresh writer rejected; any resulting state change remains unverified."
    end
    local verify_ok, observed = pcall(script_local.GetInt, hash, profile.local_index)
    observed = verify_ok and tonumber(observed) or nil
    if observed ~= profile.trigger_value then
        board_observations[profile.family].state="READBACK_UNVERIFIED"
        return false, ("Planning-board refresh trigger could not be verified (observed %s)."):format(tostring(observed))
    end
    log("Info", ("board-refresh family=%s script=%s local=%d before=%d after=%d source=%s"):format(
        profile.family, profile.script, profile.local_index, before, observed, SOURCE_REVISION))
    return true, "Planning screen reset requested. Reopen it to load saved selections; display not yet verified."
end

local global_service

local function local_player_id()
    local gta = binding("GTA")
    if gta and type(gta.GetLocalPlayerId) == "function" then
        local ok, value = pcall(gta.GetLocalPlayerId)
        value = ok and tonumber(value) or nil
        if value and value >= 0 and value <= 31 then return math.floor(value) end
    end
    return nil, "Local GTA player id is unavailable."
end

local function fmmc_context(require_local)
    local hash, hash_err = script_hash(FMMC_PROFILE.script)
    if not hash then return nil, hash_err end
    local threads, thread_err = thread_count(hash)
    if threads == nil then return nil, thread_err end
    if threads < 1 then return nil, "Open the heist finale/launcher screen first." end
    local globals, globals_err = global_service()
    if not globals then return nil, globals_err end
    local locals
    if require_local then
        locals = binding("ScriptLocal")
        if not (locals and type(locals.GetInt) == "function" and type(locals.SetInt) == "function") then
            return nil, "Cherax ScriptLocal read/write access is unavailable."
        end
    end
    return { hash = hash, globals = globals, locals = locals, threads = threads }
end

local function read_global_int(globals, index, label)
    local ok, raw = pcall(globals.GetInt, index)
    local value = ok and tonumber(raw) or nil
    if value == nil or value % 1 ~= 0 then
        return nil, (label or "Global") .. " could not be read safely."
    end
    return math.floor(value)
end

local function active_slot(bitset, slot)
    return math.floor(bitset / (2 ^ slot)) % 2 == 1
end

local function launch_build_status()
    local natives, memory = binding("Natives"), binding("Memory")
    if not (natives and type(natives.InvokeString) == "function"
        and memory and type(memory.GetBaseAddress) == "function") then
        return false, "Enhanced build identification is unavailable; launch writes are disabled."
    end
    local version_ok, version = pcall(natives.InvokeString, 0xFCA9373EF340AC0A)
    local module_ok, address = pcall(memory.GetBaseAddress, "GTA5_Enhanced.exe")
    if not version_ok or version ~= "1.73" or not module_ok or not tonumber(address) or tonumber(address) <= 0 then
        return false, "Launch profile requires GTA Enhanced Online 1.73 (source build 1158.13)."
    end
    return true
end

function HeistOps.script_identity(hash, local_index, script_name)
    local script, natives, locals = binding("Script"), binding("Natives"), binding("ScriptLocal")
    local label=tostring(script_name or hash)
    if not (script and type(script.ExecuteAsScript) == "function"
        and natives and type(natives.InvokeInt) == "function" and type(natives.InvokeBool) == "function"
        and locals and type(locals.GetPtr) == "function") then
        return nil, "Exact script identity services are unavailable."
    end
    local thread_id, actual_hash, network_ok, network_raw, host_ok, host_raw, flag_ok, host_flag
    local ok, context_error = pcall(script.ExecuteAsScript, hash, function()
        actual_hash = natives.InvokeInt(0x8A1C8B1738FFE87E)
        thread_id = natives.InvokeInt(0xC30338E8088E2E21)
        network_ok,network_raw=pcall(natives.InvokeBool,0x2910669969E9535E)
        if not network_ok or network_raw~=false then
            -- This getter is evaluated before Cherax restores the caller's
            -- context. The thread hash/id below prove which VM it describes.
            host_ok,host_raw=pcall(natives.InvokeInt,0xC7B4D79B01FA7A5C)
            flag_ok,host_flag=pcall(natives.InvokeBool,0x83CD99A1E6061AB5)
        end
    end)
    if not ok or type(thread_id) ~= "number" or thread_id <= 0 or thread_id % 1 ~= 0
        or type(actual_hash) ~= "number" or actual_hash % 4294967296 ~= hash % 4294967296 then
        return nil, ("Cherax did not enter the exact active script context (%s, thread=%s, hash=%s, error=%s).")
            :format(label,tostring(thread_id),tostring(actual_hash),tostring(not ok and context_error or nil))
    end
    local active_ok, active = pcall(natives.InvokeBool, 0x46E9AE36D8FA6417, thread_id)
    local ptr_ok, pointer = pcall(locals.GetPtr, hash, local_index)
    if not active_ok or active ~= true or not ptr_ok or type(pointer) ~= "number" or pointer < 65536 or pointer % 1 ~= 0 then
        return nil, "The active script thread or local allocation is unavailable ("..label..")."
    end
    local networked
    if network_ok and type(network_raw)=="boolean" then networked=network_raw end
    local function valid_player(value)
        return type(value)=="number" and value%1==0 and value>=0 and value<=31
    end
    local thread_ok,thread_host
    if networked~=false then
        -- The newer direct-thread getter is an independent consistency check;
        -- absence/unsupported return does not erase a valid exact-context host.
        thread_ok,thread_host=pcall(natives.InvokeInt,0xD3DEBE2991FE8098,thread_id)
    end
    local host=host_ok and valid_player(host_raw) and host_raw or nil
    local diagnostic=("script=%s thread=%s network=%s contextHost=%s:%s threadHost=%s:%s hostFlag=%s:%s")
        :format(label,tostring(thread_id),tostring(network_raw),tostring(host_ok),tostring(host_raw),
            tostring(thread_ok),tostring(thread_host),tostring(flag_ok),tostring(host_flag))
    if host~=nil and thread_ok and valid_player(thread_host) and thread_host~=host then
        return nil,"Exact script host getters disagree ("..diagnostic..")."
    end
    local pid=local_player_id()
    if host~=nil and pid~=nil and flag_ok and type(host_flag)=="boolean" and host_flag~=(host==pid) then
        return nil,"Exact script host flag and player disagree ("..diagnostic..")."
    end
    return { thread_id=thread_id, pointer=pointer, host=host, networked=networked,
        is_host=flag_ok and host_flag or false, host_diagnostic=diagnostic }
end

local function launcher_identity(ctx)
    if ctx.threads~=1 then return nil,"A unique launcher instance is unavailable." end
    return HeistOps.script_identity(ctx.hash,FMMC_PROFILE.minimum_players_local,FMMC_PROFILE.script)
end

local function same_launcher(left, right)
    return left ~= nil and right ~= nil and left.thread_id == right.thread_id and left.pointer == right.pointer
        and left.host == right.host and left.networked == right.networked
end

local function same_launcher_allocation(left,right)
    return left~=nil and right~=nil and left.thread_id==right.thread_id and left.pointer==right.pointer
end

local function launch_context(payout_only)
    local supported, build_err = launch_build_status()
    if not supported then return nil, build_err, "UNSUPPORTED_BUILD" end
    local ctx, err = fmmc_context(true)
    if not ctx then
        return nil, err, err == "Open the heist finale/launcher screen first." and "NOT_IN_LOBBY" or "INSTANCE_UNAVAILABLE"
    end
    local identity, identity_err = launcher_identity(ctx)
    if not identity then return nil, identity_err, "INSTANCE_UNAVAILABLE" end
    ctx.identity = identity
    local player_id, player_err = local_player_id()
    local leader, leader_err = read_global_int(ctx.globals, FMMC_PROFILE.leader_index, "Launcher leader")
    if player_id == nil or leader == nil then return nil, player_err or leader_err, "INSTANCE_UNAVAILABLE" end
    -- fmmc_launcher func_8710 uses the party leader before matchmaking;
    -- func_12578 runs the invite-lobby minimum-player gate for the transition
    -- host. That host role can already be local while the party field is -1.
    -- Neither role is inferred from NETWORK_IS_HOST_OF_THIS_SCRIPT.
    local host_ok,transition_host=pcall(binding("Natives").InvokeBool,0x0B824797C9BF2159)
    local phase_ok,transition_started=pcall(binding("Natives").InvokeBool,0x53FA83401D9C07FE)
    transition_host=host_ok and transition_host==true
    transition_started=phase_ok and transition_started==true
    ctx.player_id,ctx.party_leader,ctx.transition_host=player_id,leader,transition_host
    ctx.transition_started=transition_started
    ctx.leader=transition_host and player_id or (transition_started and -1 or leader)
    ctx.host_role=(transition_host or transition_started) and "transition" or "party"
    local mission, mission_err = read_global_int(ctx.globals, FMMC_PROFILE.mission_hash_index, "Launcher mission")
    if mission == nil or mission == 0 then return nil, mission_err or "Launcher mission is not populated.", "INSTANCE_UNAVAILABLE" end
    ctx.mission = mission
    -- Once the current family board owns its crew, the old matchmaking-party
    -- field may be cleared. Its real owner is independent of script hosting.
    -- A foreign active transition still cannot be overridden by stale board data.
    if payout_only and not transition_started and not transition_host then
        local family=HeistOps.identify(ctx.globals,mission)
        local layout,board=PAYOUT_ROSTERS[family],BOARD_PROFILES[family]
        if layout and board and thread_count(assert(script_hash(board.script)))==1
            and read_global_int(ctx.globals,layout.owner,"Planning owner")==player_id then
            ctx.leader=player_id;ctx.host_role="board"
        end
    end
    if ctx.leader ~= player_id then
        return nil,("Launcher host not confirmed (local=%s, partyLeader=%s, transitionHost=%s, threadHost=%s).")
            :format(tostring(player_id),tostring(leader),tostring(transition_host),tostring(identity.host)),"NOT_HOST"
    end
    return ctx
end

local function launcher_ownership_status(ctx)
    local current, _, state = launch_context()
    if not current then
        if state == "NOT_IN_LOBBY" or state == "NOT_HOST" then return false end
        return nil
    end
    return same_launcher(current.identity, ctx.identity)
        and current.mission == ctx.mission and current.leader == ctx.leader and current.host_role==ctx.host_role
end

local function launcher_still_owned(ctx)
    return launcher_ownership_status(ctx) == true
end

local function launcher_participant_matches(ctx, item)
    local bits = read_global_int(ctx.globals, FMMC_PROFILE.active_slots_index, "Active participant admission")
    local occupant = read_global_int(ctx.globals, FMMC_PROFILE.participant_base + item.slot - 1, "Participant admission")
    if bits == nil or occupant == nil then return nil end
    return active_slot(bits, item.slot - 1) and occupant == item.player
end

local function force_ready_status()
    local ctx, err, state = launch_context()
    if not ctx then
        return { support = "BLOCKED", state = state, ready = false, script = FMMC_PROFILE.script,
            reason = err, confidence = "B", evidence = FMMC_PROFILE.evidence }
    end
    local player_id, player_err = local_player_id()
    if player_id == nil then
        return { support = "BLOCKED", ready = false, script = FMMC_PROFILE.script,
            reason = player_err, confidence = "B", evidence = FMMC_PROFILE.evidence }
    end
    local leader, leader_err = ctx.leader, nil
    if leader == nil then
        return { support = "BLOCKED", ready = false, script = FMMC_PROFILE.script,
            reason = leader_err, confidence = "B", evidence = FMMC_PROFILE.evidence }
    end
    if leader ~= player_id then
        return { support = "EXPERIMENTAL", ready = false, script = FMMC_PROFILE.script,
            host = false, player_id = player_id, leader = leader,
            reason = "Force Ready is host-only; current fmmc_launcher leader does not match the local player.",
            confidence = "B", evidence = FMMC_PROFILE.evidence }
    end
    local bits, bits_err = read_global_int(ctx.globals, FMMC_PROFILE.active_slots_index, "Active participant bitset")
    if bits == nil then
        return { support = "BLOCKED", ready = false, script = FMMC_PROFILE.script,
            reason = bits_err, confidence = "B", evidence = FMMC_PROFILE.evidence }
    end
    local participants, all_ready = {}, true
    for slot = 0, 3 do
        if active_slot(bits, slot) then
            local pid, pid_err = read_global_int(ctx.globals, FMMC_PROFILE.participant_base + slot, "Participant slot")
            if pid == nil or pid < 0 or pid > 31 then
                return { support = "BLOCKED", ready = false, script = FMMC_PROFILE.script,
                    reason = pid_err or ("Active participant slot %d has invalid player id %s."):format(slot + 1, tostring(pid)),
                    confidence = "B", evidence = FMMC_PROFILE.evidence }
            end
            local state, state_err = read_global_int(ctx.globals,
                FMMC_PROFILE.readiness_base + (pid * FMMC_PROFILE.readiness_stride), "Participant readiness")
            if state == nil then
                return { support = "BLOCKED", ready = false, script = FMMC_PROFILE.script,
                    reason = state_err, confidence = "B", evidence = FMMC_PROFILE.evidence }
            end
            if state ~= FMMC_PROFILE.ready_value and state ~= FMMC_PROFILE.not_ready_value then
                return { support = "BLOCKED", ready = false, script = FMMC_PROFILE.script,
                    reason = ("Participant %d readiness state %d is outside the source-verified 6/7 toggle states."):format(pid, state),
                    confidence = "B", evidence = FMMC_PROFILE.evidence }
            end
            participants[#participants + 1] = { slot = slot + 1, player = pid, state = state,
                is_ready = state == FMMC_PROFILE.ready_value }
            if state ~= FMMC_PROFILE.ready_value then all_ready = false end
        end
    end
    if #participants < 1 then
        return { support = "EXPERIMENTAL", ready = false, script = FMMC_PROFILE.script, host = true,
            reason = "No active fmmc_launcher participant slots are populated yet.",
            confidence = "B", evidence = FMMC_PROFILE.evidence }
    end
    return {
        support = "EXPERIMENTAL", state = "SUPPORTED_READY", ready = true, script = FMMC_PROFILE.script, host = true,
        instance_id = ctx.identity.thread_id, identity = ctx.identity, mission = ctx.mission,
        player_id = player_id, leader = leader, players = #participants, participants = participants,
        all_ready = all_ready, ready_snapshot_available = ready_snapshot ~= nil,
        confidence = "B", live_status = "LIVE_TEST_REQUIRED",
        reason = all_ready and "All active launcher participants are already ready."
            or "Current Enhanced readiness fields are validated and can be changed with read-back verification.",
        evidence = FMMC_PROFILE.evidence, source_revision = SOURCE_REVISION,
    }
end

local function force_ready()
    if not started then return false, "Heist runtime profiles are not ready." end
    if ready_snapshot then return false, "Restore the existing Force Ready snapshot before applying another." end
    begin_explicit_thread_refresh()
    local status = force_ready_status()
    if not status.ready then return false, status.reason end
    local ctx, err = launch_context()
    if not ctx then return false, err end
    if not same_launcher(ctx.identity, status.identity) or ctx.mission ~= status.mission then
        return false, "Launcher changed during Force Ready admission."
    end
    local changed = {}
    local function rollback()
        local complete = true
        for index = #changed, 1, -1 do
            local item = changed[index]
            if not launcher_still_owned(ctx) then complete = false; break end
            local present = launcher_participant_matches(ctx, item)
            if present == nil then complete = false
            elseif present then
                local current = read_global_int(ctx.globals, item.index, "Ready rollback")
                if current == nil then complete = false
                elseif current == FMMC_PROFILE.ready_value then
                    local ok, accepted = pcall(ctx.globals.SetInt, item.index, item.before)
                    if not ok or accepted == false or read_global_int(ctx.globals, item.index, "Ready rollback verification") ~= item.before then complete = false end
                end
            end
        end
        if ready_snapshot then
            if complete then ready_snapshot = nil else ready_snapshot.restore_pending = true end
        end
        return complete
    end
    for _, item in ipairs(status.participants or {}) do
        if item.state ~= FMMC_PROFILE.ready_value then
            local index = FMMC_PROFILE.readiness_base + (item.player * FMMC_PROFILE.readiness_stride)
            if not launcher_still_owned(ctx) then rollback(); return false, "Launcher changed before the ready write; stale writes were cancelled." end
            if launcher_participant_matches(ctx, item) ~= true
                or read_global_int(ctx.globals, index, "Readiness admission") ~= item.state then
                rollback()
                return false, "A participant slot or readiness changed before admission; no stale readiness write was made."
            end
            changed[#changed + 1] = { index = index, before = item.state, player = item.player, slot = item.slot }
            ready_snapshot = { hash = ctx.hash, identity = ctx.identity, mission = ctx.mission,
                leader = status.leader, changed = changed, created_at = os.time and os.time() or 0 }
            local ok, result = pcall(ctx.globals.SetInt, index, FMMC_PROFILE.ready_value)
            if not ok or result == false then
                local restored = rollback()
                return false, ("Ready write was rejected for participant %d; rollback %s."):format(item.player, restored and "completed for still-owned slots" or "is pending")
            end
            local observed, verify_err = read_global_int(ctx.globals, index, "Participant readiness verification")
            if observed ~= FMMC_PROFILE.ready_value then
                local restored = rollback()
                return false, verify_err or ("Participant %d did not verify as ready; rollback %s."):format(item.player, restored and "completed for still-owned slots" or "is pending")
            end
        end
    end
    ready_snapshot = #changed > 0 and {
        hash = ctx.hash, identity = ctx.identity, mission = ctx.mission,
        leader = status.leader, changed = changed, created_at = os.time and os.time() or 0,
    } or nil
    launch_cache = nil
    log("Info", ("force-ready changed=%d source=%s"):format(#changed, SOURCE_REVISION))
    return true, #changed == 0 and "All active participants were already ready."
        or ("Forced %d active participant%s ready and verified."):format(#changed, #changed == 1 and "" or "s")
end

local function restore_ready_snapshot()
    local snapshot = ready_snapshot
    if not snapshot then return true, "No CScript Force Ready snapshot is active." end
    snapshot.restore_pending = true
    begin_explicit_thread_refresh()
    local ctx, err, context_state = launch_context()
    if not ctx then
        if context_state == "NOT_IN_LOBBY" or context_state == "NOT_HOST" then
            ready_snapshot = nil
            return true, "Launcher exit or host loss was observed; the stale Force Ready snapshot was discarded."
        end
        snapshot.restore_pending = true
        return false, "Launcher identity is temporarily unavailable; the Force Ready snapshot is retained without writes. " .. tostring(err)
    end
    local player_id, player_err = local_player_id()
    if player_id == nil then return false, player_err end
    local leader, leader_err = ctx.leader, nil
    if leader == nil then return false, leader_err end
    if ctx.hash ~= snapshot.hash or not same_launcher(ctx.identity, snapshot.identity)
        or ctx.mission ~= snapshot.mission or leader ~= snapshot.leader or leader ~= player_id then
        ready_snapshot = nil
        return false, "Launcher ownership changed; the stale Force Ready snapshot was discarded without writing."
    end
    local restored, skipped = 0, 0
    for _, item in ipairs(snapshot.changed or {}) do
        local current, read_err = read_global_int(ctx.globals, item.index, "Participant readiness restore")
        if current == nil then return false, read_err end
        local occupant = read_global_int(ctx.globals, FMMC_PROFILE.participant_base + item.slot - 1, "Participant identity restore")
        local bits = read_global_int(ctx.globals, FMMC_PROFILE.active_slots_index, "Active participant restore")
        local ownership = launcher_ownership_status(ctx)
        if ownership == nil or occupant == nil or bits == nil then
            return false, "Launcher or participant identity became unreadable during readiness restoration; the snapshot remains pending without writes."
        end
        if ownership == false then ready_snapshot = nil; return false, "Launcher changed during readiness restore; remaining writes were cancelled." end
        if current == FMMC_PROFILE.ready_value and occupant == item.player and bits and active_slot(bits, item.slot - 1) then
            local ok, result = pcall(ctx.globals.SetInt, item.index, item.before)
            if not ok or result == false then
                snapshot.restore_pending = true
                return false, ("Failed to restore participant %d readiness; snapshot retained for retry."):format(item.player)
            end
            local observed, verify_err = read_global_int(ctx.globals, item.index, "Participant readiness restore verification")
            if observed ~= item.before then
                snapshot.restore_pending = true
                return false, verify_err or ("Participant %d readiness restoration did not verify."):format(item.player)
            end
            restored = restored + 1
        elseif current == item.before then
            skipped = skipped + 1
        else
            -- GTA or another tool changed this field after CScript. Do not overwrite it.
            skipped = skipped + 1
        end
    end
    ready_snapshot = nil
    launch_cache = nil
    log("Info", ("force-ready restore restored=%d skipped=%d source=%s"):format(restored, skipped, SOURCE_REVISION))
    return true, ("Force Ready restore complete: %d restored, %d left untouched."):format(restored, skipped)
end

-- A catalogue row is a separate immutable job identity, not a launcher field.
-- Current func_9023 requires loaded bit13 plus exact content-ID correspondence.
local function solo_catalogue(ctx)
 local l,g=ctx.locals,ctx.globals
 if type(l.GetString)~="function" or type(g.GetString)~="function" then return nil end
 local ok,result=pcall(function()
  local namespace,row=l.GetInt(ctx.hash,20229),l.GetInt(ctx.hash,20230)
  local tables={[63]={794993,1518},[62]={962334,300}}
  local t=tables[namespace]
  if not t or type(row)~="number" or row%1~=0 or row<0 or row>=t[2] or g.GetInt(t[1])~=t[2] then return nil end
  local base=t[1]+1+row*95;local id=l.GetString(ctx.hash,20294)
  local flags=g.GetInt(base+82);local minimum=g.GetInt(base+75)
  if type(id)~="string" or #id<1 or #id>63 or g.GetString(base)~=id
   or type(flags)~="number" or flags%1~=0 or (flags & (1<<13))==0
   or type(minimum)~="number" or minimum%1~=0 or minimum<1 or minimum>4 then return nil end
  return {kind="catalogue",index=base+75,base=base,id=id,header=t[1],count=t[2],namespace=namespace,row=row,original=minimum,applied=1}
 end)
 return ok and result or nil
end
local function catalogue_matches(g,f)
 if not g or type(g.GetString)~="function" or type(g.GetInt)~="function" then return nil end
 local ok,result=pcall(function()
  if type(g.AreValid)=="function" and g.AreValid()~=true then return nil end
  local count,flags=g.GetInt(f.header),g.GetInt(f.base+82)
  if type(count)~="number" or type(flags)~="number" or flags%1~=0 then return nil end
  if count~=f.count or (flags & (1<<13))==0 then return false end
  local id=g.GetString(f.base)
  if type(id)~="string" then return nil end
  return id==f.id
 end)
 if not ok then return nil end
 return result
end
function HeistOps.restore_catalogue(f)
 local g=binding("ScriptGlobal")
 if not g or not launch_build_status() then return false end
 local matches=catalogue_matches(g,f)
 if matches==nil then return false end -- Unreadable is not proof that ownership ended.
 if matches==false then f.owned=false;return true end -- Row was replaced: never replay its former baseline.
 local current=read_global_int(g,f.index,"Catalogue cleanup")
 if current==nil then return false end
 if current~=f.applied then f.owned=false;return true end
 matches=catalogue_matches(g,f)
 if matches==nil then return false end
 if matches==false then f.owned=false;return true end
 local ok,accepted=pcall(g.SetInt,f.index,f.original)
 if not ok or accepted==false or read_global_int(g,f.index,"Catalogue cleanup verification")~=f.original then return false end
 f.owned=false;return true
end
-- A controller thread can exist before the Apartment cut board closes.
-- func_951 copies the active team count during state0: state0 alone is not
-- permission to rewrite admission. Fresh writes require its uncaptured zero.
function HeistOps.solo_write_phase(ctx,family,verify)
 if family~='apartment' and family~='casino' and family~='doomsday' then return {kind='legacy'} end
 local ok,result=pcall(function()
  local classic,modern=assert(script_hash('fm_mission_controller')),assert(script_hash('fm_mission_controller_2020'))
  local a,b=thread_count(classic),thread_count(modern)
  assert((a==0 or a==1) and (b==0 or b==1) and a+b<=1,'Controller instance is ambiguous or unreadable.')
  if a==0 and b==0 then return {kind='absent'} end
  assert(family=='apartment' and a==1 and b==0,
   'The finale controller has already started; new Solo Launch admission is unavailable.')
  assert(not ctx.transition_host and not ctx.transition_started
   and read_global_int(ctx.globals,1941142,'Apartment board phase')==5
   and read_global_int(ctx.globals,1845348+ctx.player_id*884+185,'Apartment player phase')==27,
   'Fresh Solo Launch needs the interactive Apartment board before team capture.')
  local identity,why=HeistOps.script_identity(classic,20412,'fm_mission_controller');assert(identity,why)
  assert(identity.networked==true,'The Apartment controller network context is not initialized.')
  local root,teams=ctx.locals.GetInt(classic,20412),ctx.locals.GetInt(classic,21405)
  assert(root==0 and teams==0,
   ('The Apartment controller has already captured its teams or left planning (state=%s, teams=%s).')
    :format(tostring(root),tostring(teams)))
  local key=tostring(identity.thread_id)..':'..tostring(identity.pointer)
  if verify~=false and HeistOps.solo_capture_guard~=key then
   HeistOps.guard(classic,'solo_team_capture');HeistOps.solo_capture_guard=key
  end
  local after,err=HeistOps.script_identity(classic,20412,'fm_mission_controller');assert(after,err)
  assert(same_launcher(identity,after) and ctx.locals.GetInt(classic,20412)==0 and ctx.locals.GetInt(classic,21405)==0,
   'The Apartment controller changed during uncaptured-team verification.')
  return {kind='apartment_board',hash=classic,identity=identity}
 end)
 if not ok then return nil,tostring(result) end
 return result
end
function HeistOps.solo_phase_matches(ctx,phase)
 if not phase then return true end
 local current=HeistOps.solo_write_phase(ctx,phase.family,false)
 return current and current.kind==phase.kind
  and (phase.kind~='apartment_board' or same_launcher(current.identity,phase.identity))
end
function HeistOps.solo_mission_status(family)
 local ok,result=pcall(function()
  local g=assert(global_service())
  local mission=g.GetInt(FMMC_PROFILE.mission_hash_index)
  local detected=HeistOps.identify(g,mission)
  if not detected or family and family~=detected then return nil end
  local active=HeistOps.controller(detected)
  if active then return {family=detected,state='IN_MISSION',reason='The current finale controller has active objectives.',ctx=active} end
  local preparing=HeistOps.controller(detected,true)
  if preparing and preparing.script=='fm_mission_controller' and preparing.root==9 then
   local flags=binding('ScriptLocal').GetInt(preparing.script_hash,preparing.profile.root+1)
   local veto=binding('ScriptLocal').GetInt(preparing.script_hash,preparing.profile.root+3)
   if type(flags)=='number' and flags%1==0 and type(veto)=='number' and veto%1==0
    and active_slot(flags,17) and not active_slot(flags,19) and not active_slot(flags,16)
    and not active_slot(veto,31) then
    for bit=20,23 do if active_slot(flags,bit) then return nil end end
    return {family=detected,state='PREPARING',reason='The current finale controller is loading its objective state.',ctx=preparing}
   end
  end
 end)
 return ok and result or nil
end
function HeistOps.solo_same_instance(state)
 local ok,result=pcall(function()
  local count=thread_count(state.hash)
  if count==0 then return false end
  if count~=1 then return nil end
  local g=assert(global_service())
  local mission=read_global_int(g,FMMC_PROFILE.mission_hash_index,'Retained Solo Launch mission')
  if mission==nil then return nil end
  if mission~=state.mission then return false end
  local identity=HeistOps.script_identity(state.hash,FMMC_PROFILE.minimum_players_local,FMMC_PROFILE.script)
  if not identity then return nil end
  return identity.thread_id==state.identity.thread_id and identity.pointer==state.identity.pointer
 end)
 if ok then return result end
 return nil
end
function HeistOps.hold_solo(state,reason,display)
 state.held=true;state.display_state=display or 'HELD'
 launch_event={state=state.display_state,reason=reason or 'Admission ownership is retained without writes while the board changes.'}
 HeistOps.solo_auto.state,HeistOps.solo_auto.reason=state.display_state,launch_event.reason
 local line='solo-launch state='..state.display_state..' instance='..tostring(state.identity.thread_id)..' reason='..launch_event.reason
 if state.hold_trace~=line then state.hold_trace=line;pcall(log,'Info',line) end
end
-- Casino/Doomsday return through the same launcher after controller results.
-- Preserve only already-owned admission minima; no new solo authorization is
-- inferred from a single player discovered during gameplay.
-- BEGIN VERIFIED SUCCESSOR RETURN
function HeistOps.successor_contract(g,family,mission)
 if family~='doomsday' then return nil end
 local origin,target=g.GetInt(266868),g.GetInt(266869)
 if type(origin)~='number' or origin%1~=0 or type(target)~='number' or target%1~=0
  or origin==0 or target==0 or origin==target or origin~=mission then return nil end
 return {origin=origin,target=target}
end
function HeistOps.remember_successor_result(lease,active,revision)
 local contract=lease.successor_contract
 if not contract or lease.successor_proof or lease.successor or active.root~=12 then return end
 local ok,result=pcall(HeistOps.classic_local_result,active)
 if not ok or not result or not result.entered or not result.success or result.player~=active.host_player
  or result.row_pass~=1 or type(result.amount)~='number' or result.amount%1~=0 or result.amount<0 or result.amount~=result.row_amount then return end
 if HeistOps.late_admission~=lease or lease.revision~=revision then return end
 if active.owner_rid~=lease.owner_rid or lease.controller~=active.controller_identity then return end
 lease.successor_proof={at=runtime_time_ms(),controller=active.controller_identity,
  launcher_thread=lease.identity.thread_id,launcher_pointer=lease.identity.pointer}
end
function HeistOps.successor_actor(lease,identity,owner)
 if identity.networked~=true or identity.host~=owner or identity.is_host~=true then return nil end
 local n,s=binding('Natives'),binding('Script')
 if not n or not s or type(s.ExecuteAsScript)~='function' then return nil end
 local ok,count=pcall(function()
  local count
  s.ExecuteAsScript(lease.hash,function()
   assert(n.InvokeInt(0x8A1C8B1738FFE87E)%4294967296==lease.hash%4294967296)
   assert(n.InvokeInt(0xC30338E8088E2E21)==identity.thread_id)
   assert(n.InvokeInt(0xC7B4D79B01FA7A5C)==owner and n.InvokeBool(0x83CD99A1E6061AB5)==true)
   count=n.InvokeInt(0x18D0456E86604654)
   assert(type(count)=='number' and count%1==0 and count>=1 and count<=4)
   local participant=n.InvokeInt(0x57A3BDDAD8E5AA0A)
   assert(type(participant)=='number' and participant%1==0 and participant>=0 and participant<32)
   assert(n.InvokeBool(0x6FF8FF40B6357D45,participant)==true)
   assert(n.InvokeInt(0x24FB80D107371267,participant)==owner)
   assert(n.InvokeInt(0x18D0456E86604654)==count)
  end)
  return count
 end)
 return ok and count or nil
end
function HeistOps.successor_return(lease,mission,scope,identity,owner,revision,cleanup)
 local contract,proof=lease.successor_contract,lease.successor_proof
 if not contract or not proof then return false,'successor result proof unavailable' end
 local g,l=binding('ScriptGlobal'),binding('ScriptLocal')
 local mapping_valid=g.GetInt(266868)==contract.origin and g.GetInt(266869)==contract.target
 if not mapping_valid then
  if lease.successor then lease.cleanup_only=true else return false,'successor tunables changed' end
 end
 if identity.thread_id~=proof.launcher_thread or identity.pointer~=proof.launcher_pointer then return false,'successor launcher changed' end
 if lease.scope~=scope.scope or lease.leader~=owner then return false,'successor actor scope changed' end
 if mission~=contract.target and not (lease.successor and mission==0) then return false,'successor job changed' end
 if cleanup and not lease.successor then return false,'explicit cleanup' end
 if not lease.successor and thread_count(script_hash('fm_mission_controller'))~=0 then return nil,'successor controller still active' end
 local actual=HeistOps.successor_actor(lease,identity,owner)
 if not actual then return nil,'successor participant or host unavailable' end
 local now=runtime_time_ms()
 if type(now)~='number' or now%1~=0 or now<proof.at then return nil,'successor clock unavailable' end
 local function current()
  return HeistOps.late_admission==lease and lease.revision==revision
   and g.GetInt(FMMC_PROFILE.mission_hash_index)==mission
 end
 if not current() then return nil,'successor observation cancelled' end
 if lease.successor then
  local release=cleanup==true or lease.cleanup_only or mission==0 or actual~=1 or now>=lease.successor.deadline
  if not cleanup and mission~=0 and actual==1 and now>=lease.successor.deadline then lease.successor.expired=true end
  if not current() then return nil,'successor release changed' end
  lease.native_launcher_count=actual
  return true,release and 'released' or 'successor'
 end
 if actual~=1 then return false,'successor crew changed' end
 if now<proof.at or now-proof.at>15000 then return false,'successor proof expired' end
 local launcher_stage=g.GetInt(1845348+owner*884+185)
 if launcher_stage~=8 and launcher_stage~=9 then return nil,'successor job import not complete' end
 -- The old launcher local is still1 on the first successor frame. Wait for
 -- func_13626's real job import before acquiring its fresh minimum baseline.
 local minimum=l.GetInt(lease.hash,20211)
 local declared=g.GetInt(4722361)
 local team_minimum=g.GetInt(4722368)
 if type(minimum)~='number' or minimum%1~=0 or minimum<1 or minimum>4
  or type(declared)~='number' or declared%1~=0 or declared<1 or declared>4
  or minimum~=declared then return nil,'successor minimum import pending' end
 if g.GetInt(4722364)~=1 or g.GetInt(4722365)~=1
  or type(team_minimum)~='number' or team_minimum%1~=0 or team_minimum<1 or team_minimum>4 then
  return nil,'successor single-team requirements unavailable'
 end
 if not pcall(HeistOps.guard,lease.hash,'return_successor_admission') then return nil,'successor source signature unavailable' end
 local fresh=HeistOps.script_identity(lease.hash,20211,FMMC_PROFILE.script)
 if not fresh or fresh.thread_id~=identity.thread_id or fresh.pointer~=identity.pointer
  or fresh.host~=owner or fresh.is_host~=true or fresh.networked~=true then return nil,'successor ownership changed' end
 if l.GetInt(lease.hash,20211)~=minimum or g.GetInt(4722361)~=declared or g.GetInt(4722368)~=team_minimum
  or not current() then return nil,'successor requirements changed during capture' end
 for _,field in ipairs(lease.fields) do
  if field.kind=='catalogue' and field.owned then
   if HeistOps.catalogue_cleanup and HeistOps.catalogue_cleanup~=field then return nil,'original catalogue cleanup pending' end
   field.mission,field.family=lease.mission,lease.family
   HeistOps.catalogue_cleanup=field
   local restored,clean=pcall(HeistOps.restore_catalogue,field)
   if restored and clean and HeistOps.catalogue_cleanup==field then HeistOps.catalogue_cleanup=nil end
  end
 end
 if not current() then return nil,'successor acquisition cancelled' end
 for _,field in ipairs(lease.fields) do if field.kind~='catalogue' then field.owned=false end end
 lease.fields={
  {kind='global',index=4722361,original=declared,applied=1,owned=true},
  {kind='global',index=4722368,original=team_minimum,applied=1,owned=true},
  {kind='local',index=20211,original=minimum,applied=1,owned=true}}
 lease.successor={mission=mission,deadline=now+60000,origin=lease.mission}
 lease.native_launcher_count=actual
 pcall(log,'Info','LateSoloAdmission family=doomsday state=SUCCESSOR_BOUND origin='..lease.mission..' mission='..mission..' nativeCrew='..actual..' freshMinimum='..minimum)
 return true,'successor'
end
-- END VERIFIED SUCCESSOR RETURN

function HeistOps.retain_late_admission(state)
 if state.family~='casino' and state.family~='doomsday' then return end
 if HeistOps.late_admission then return end
 if not state.owner_rid or state.character_slot==nil then
  pcall(log,'Warning','LateSoloAdmission family='..state.family..' state=HELD reason=initial_owner_not_recorded')
  return
 end
 local fields={}
 for _,f in ipairs(state.fields) do
  if f.owned and (f.kind=='catalogue'
   or f.kind=='local' and f.index==20211
   or f.kind=='global' and (f.index==4722361 or f.index>=4722368 and f.index<=4722371)) then
   fields[#fields+1]=f
  end
 end
 if #fields==0 then
  pcall(log,'Info','LateSoloAdmission family='..state.family..' state=RETIRED reason=no_owned_admission_intent')
  return
 end
 HeistOps.late_admission={family=state.family,mission=state.mission,
  hash=state.hash,identity=state.identity,scope=state.scope,leader=state.owner_pid,owner_rid=state.owner_rid,
  character_slot=state.character_slot,pending=true,
  fields=fields,started=runtime_time_ms(),successor_contract=state.successor_contract and
   {origin=state.successor_contract.origin,target=state.successor_contract.target} or nil}
 pcall(log,'Info','LateSoloAdmission family='..state.family..' state=CREATED reason=owned_intent_pending_controller originPid='..tostring(state.owner_pid)..' originThread='..tostring(state.identity.thread_id))
end
function HeistOps.tick_late_admission(cleanup)
 local lease=HeistOps.late_admission;if not lease then return true end
 if lease.servicing and cleanup~=true then return false end
 local previous=lease.servicing
 lease.servicing=true;lease.revision=(lease.revision or 0)+1
 local revision=lease.revision
 local function service()
 local g,l=binding('ScriptGlobal'),binding('ScriptLocal')
 local function retire(reason)
  if HeistOps.late_admission~=lease or lease.revision~=revision then return true end
  if lease.successor and lease.successor.expired and reason~='explicit cleanup' then reason='successor window expired' end
  for _,f in ipairs(lease.fields) do
   if f.owned and f.kind=='catalogue' and HeistOps.catalogue_cleanup and HeistOps.catalogue_cleanup~=f then return false end
  end
  -- A replaced job/crew owns its current values. Never replay this baseline.
  for _,f in ipairs(lease.fields) do
   if f.owned and f.kind=='catalogue' then
    f.mission,f.family=lease.mission,lease.family
    HeistOps.catalogue_cleanup=f
   else f.owned=false end
  end
  HeistOps.late_admission=nil
  if reason~='explicit cleanup' and reason~='same launcher released its job' then
   HeistOps.solo_retired={mission=lease.successor and lease.successor.mission or lease.mission,identity=lease.identity}
   HeistOps.solo_auto.state,HeistOps.solo_auto.reason='HELD',reason
  end
  pcall(log,'Info','LateSoloAdmission family='..lease.family..' state=RETIRED reason='..reason)
  return true
 end
 local function positive(phase,active)
  -- Controller/owner getters can yield. Prove the exact launcher again after
  -- all phase observations, then check the non-callback cancellation token.
  local identity=HeistOps.script_identity(lease.hash,20211,FMMC_PROFILE.script)
  if not identity then return nil,'final launcher identity unavailable' end
  if not same_launcher(identity,lease.identity) then return false,'launcher changed during phase read' end
  if HeistOps.late_admission~=lease or lease.revision~=revision then return false,'lease cancelled or replaced' end
  return true,phase,active
 end
 local function bind_launcher(identity,scope,owner,active,phase)
  local changed=not same_launcher(identity,lease.identity)
  if changed then
   -- A different VM/host acquires its own current baseline. Old locals are
   -- never restored or replayed into the new allocation.
   if identity.networked~=true or identity.host~=owner or identity.is_host~=true then
    return false,'replacement launcher is not owned by the same actor'
   end
   local guarded=pcall(HeistOps.guard,lease.hash,'late_solo_admission')
   if not guarded then return nil,'replacement launcher signature unavailable' end
   local baseline=l.GetInt(lease.hash,20211)
   if type(baseline)~='number' or baseline%1~=0 or baseline<1 or baseline>4 then return nil,'replacement launcher minimum unreadable' end
   local fresh=HeistOps.script_identity(lease.hash,20211,FMMC_PROFILE.script)
   if not same_launcher(fresh,identity) then return nil,'replacement launcher changed during baseline read' end
   if active and HeistOps.same(active)~=true then return nil,'controller changed during launcher baseline read' end
   local after=board_identity(nil,nil,cleanup)
   if not after or after.scope~=scope.scope then return nil,'scope changed during launcher baseline read' end
   if HeistOps.late_admission~=lease or lease.revision~=revision then return false,'lease cancelled or replaced' end
   for _,f in ipairs(lease.fields) do if f.kind=='local' then f.owned=false end end
   lease.fields[#lease.fields+1]={kind='local',index=20211,original=baseline,applied=1,owned=true}
   lease.identity=identity;lease.guarded=true
  end
  local remapped=lease.scope~=scope.scope or lease.leader~=owner or changed or lease.pending
  lease.scope,lease.leader,lease.pending=scope.scope,owner,false
  if active then lease.controller=active.controller_identity end
  if phase=='return' and remapped then lease.return_rebound=true end
  if remapped then
   pcall(log,'Info','LateSoloAdmission family='..lease.family..' state=REBOUND reason=same_owner_character_mission_verified phase='..phase..' pid='..owner..' launcherThread='..identity.thread_id..' freshLocalBaseline='..tostring(changed))
  end
  return positive(phase,active)
 end
 local function fence()
  if HeistOps.late_admission~=lease or lease.revision~=revision then return false,'lease cancelled or replaced' end
  local scope=board_identity(nil,nil,cleanup)
  if not scope then return nil,'session or character unavailable' end
  local slot=tonumber(scope.scope:match('^%d+:(%d+):'))
  if slot~=lease.character_slot then return false,'character changed' end
  local owner=local_player_id()
  local rids,members=HeistOps.member_rids({{player=owner}})
  if not rids then return nil,'owner Rockstar identity unavailable' end
  if members[owner]~=lease.owner_rid then return false,'owner Rockstar identity changed' end
  local mission=read_global_int(g,FMMC_PROFILE.mission_hash_index,'Late admission mission')
  if mission==nil then return nil,'mission unreadable' end
  local count=thread_count(lease.hash)
  if count~=1 then return nil,count==0 and 'waiting for activity launcher' or 'launcher ambiguous' end
  local identity=HeistOps.script_identity(lease.hash,20211,FMMC_PROFILE.script)
  if not identity then return nil,'launcher identity unreadable' end
  if lease.successor or mission~=lease.mission and mission~=0 then
   local valid,phase=HeistOps.successor_return(lease,mission,scope,identity,owner,revision,cleanup)
   if valid==true then return positive(phase) end
   return valid,phase
  end
  local invite=read_global_int(g,2688930,'Late admission invite crew')
  if invite==nil or invite<0 then return nil,'invite count unreadable' end
  local active=HeistOps.controller(lease.family,true)
  if active then
   if #active.participants~=1 or active.host_player~=owner then return false,'controller crew changed' end
   if active.owner_rid~=lease.owner_rid then return false,'controller owner identity changed' end
   if lease.controller and active.controller_identity~=lease.controller then return false,'controller identity changed' end
   local flags=l.GetInt(active.script_hash,active.profile.root+1)
   if type(flags)~='number' or flags%1~=0 then return nil,'controller phase unreadable' end
   if active.root<active.profile.state or not active_slot(flags,19) then return nil,'controller preparing' end
   if mission~=lease.mission then return nil,'controller mission not populated' end
   if not lease.pending and scope.scope~=lease.scope then return false,'bound controller scope changed' end
   local valid,phase,current=bind_launcher(identity,scope,owner,active,'controller')
   if valid==true then HeistOps.remember_successor_result(lease,active,revision) end
   return valid,phase,current
  end
  local controllers=thread_count(script_hash('fm_mission_controller'))
  if controllers~=0 then return nil,'controller ownership unavailable' end
  if not lease.controller then
   if cleanup and scope.scope==lease.scope and same_launcher(identity,lease.identity) then return positive('pending_cleanup') end
   return nil,'waiting for identified controller'
  end
  local actual=read_global_int(g,2688930,'Late admission invite crew')
  if actual==nil or actual<0 or actual%1~=0 then return nil,'return crew unreadable' end
  if actual>=2 then return false,'return crew changed' end
  if actual~=1 then return nil,'return crew transitional' end
  local leader=read_global_int(g,FMMC_PROFILE.leader_index,'Late admission owner')
  if leader==nil or leader==-1 then return nil,'launcher owner temporarily unavailable' end
  if leader%1~=0 or leader<0 or leader>31 then return nil,'launcher owner invalid' end
  if leader~=owner then return false,'launcher owner changed' end
  local changed=scope.scope~=lease.scope or not same_launcher(identity,lease.identity)
  if changed then
   if lease.return_rebound then return false,'return launcher handoff already bound' end
   -- A return VM is adopted only through the normal fresh launcher authority
   -- checks, with the recorded job, character and Rockstar owner still equal.
   local ctx=launch_context()
   if not ctx or ctx.mission~=lease.mission or ctx.player_id~=owner or not same_launcher(ctx.identity,identity) then
    return nil,'waiting for independently owned return launcher'
   end
  end
  return bind_launcher(identity,scope,owner,nil,mission==0 and 'released' or 'return')
 end
 local ok,valid,phase=pcall(fence)
 if not ok or valid==nil then
  local why=ok and phase or tostring(valid)
  if lease.hold_reason~=why then lease.hold_reason=why;pcall(log,'Info','LateSoloAdmission family='..lease.family..' state=HELD reason='..tostring(why)) end
  lease.unreadable_since=lease.unreadable_since or runtime_time_ms()
  if runtime_time_ms()-lease.unreadable_since>60000 then
   if lease.successor then lease.cleanup_only=true;return false end
   return retire('ownership unavailable for 60 seconds')
  end
  return false
 end
 lease.unreadable_since=nil;lease.hold_reason=nil
 if valid==false then return retire(phase) end
 if not lease.guarded then
  local guarded=pcall(HeistOps.guard,lease.hash,'late_solo_admission')
  if not guarded then
   pcall(log,'Warning','LateSoloAdmission family='..lease.family..' state=HELD reason=late_signature_unavailable')
   return false
  end
  local fresh,fresh_phase=fence()
  if fresh~=true then return fresh==false and retire(fresh_phase) or false end
  if fresh_phase~=phase then return false end
  lease.guarded=true
 end
 local release=cleanup==true or phase=='released'
 local values={}
 for _,f in ipairs(lease.fields) do if f.owned then
  local same,why=fence();if same~=true then return same==false and retire(why) or false end
  if why~=phase then return false end
  if f.kind=='catalogue' and catalogue_matches(g,f)~=true then return false end
  local current=f.kind=='local' and l.GetInt(lease.hash,f.index) or read_global_int(g,f.index,'Late admission minimum')
  if type(current)~='number' or current%1~=0 then return false end
  values[#values+1]=f.kind..':'..f.index..'='..current
  local target=release and f.original or f.applied
  -- A game reload of our own original minimum is repairable under all fences.
  -- An unrelated third value relinquishes this cell, never overwrites it.
  if current~=f.applied and current~=f.original then f.owned=false
  elseif current~=target then
   same,why=fence();if same~=true then return same==false and retire(why) or false end
   if not f.owned then return false end
   local fresh=f.kind=='local' and l.GetInt(lease.hash,f.index) or g.GetInt(f.index)
   if fresh~=current then return false end
   same,why=fence();if same~=true then return same==false and retire(why) or false end
   if why~=phase then return false end
   if f.kind=='catalogue' then
    if catalogue_matches(g,f)~=true then return false end
    -- Content getters are host callbacks too: they may unload this lease or
    -- replace the launcher after returning the former content ID.
    same,why=fence();if same~=true then return same==false and retire(why) or false end
    if why~=phase then return false end
   end
   if HeistOps.late_admission~=lease or lease.revision~=revision then return false end
   if f.kind=='local' then l.SetInt(lease.hash,f.index,target) else g.SetInt(f.index,target) end
   local after=f.kind=='local' and l.GetInt(lease.hash,f.index) or g.GetInt(f.index)
   if after~=target then return false end
   if fence()~=true then return false end
  end
  if release then f.owned=false end
 end end
 local line='LateSoloAdmission family='..lease.family..' phase='..phase..' inviteCrew='..tostring(g.GetInt(2688930))..' launcherCrew='..tostring(l.GetInt(lease.hash,18292))..' controllerCrew='..tostring(lease.controller and 1 or '-')..' error='..tostring(g.GetInt(2690054))..' minima='..table.concat(values,',')
 if line~=lease.trace then lease.trace=line;pcall(log,'Info',line) end
 if release then return retire(cleanup and 'explicit cleanup' or 'same launcher released its job') end
 return true
 end
 local ok,value=pcall(service)
 lease.servicing=previous
 return ok and value==true
end
function HeistOps.detach_solo(state,reason)
 HeistOps.retain_late_admission(state)
 for _,field in ipairs(state.fields) do
  if field.kind=='catalogue' and field.owned then
   field.mission,field.family=state.mission,state.family
   if not HeistOps.late_admission then HeistOps.catalogue_cleanup=field end
  end
 end
 solo_override=nil
 if HeistOps.solo_auto.enabled then HeistOps.trace_solo_handoff(state,reason) end
 launch_event={state='RELEASED',reason=reason or 'Launcher ownership ended; prior launcher values were not replayed.'}
end

function HeistOps.tick_catalogue_cleanup(force)
 local f=HeistOps.catalogue_cleanup
 if not f then return true end
 if not force then
  local n,g=binding("Natives"),binding("ScriptGlobal")
  if not n or type(n.InvokeBool)~="function" or not g or type(g.GetInt)~="function" then return false end
  if type(g.AreValid)=="function" then
   local valid,available=pcall(g.AreValid)
   if not valid or available~=true then return false end
  end
  local ok,transition=pcall(n.InvokeBool,0x53FA83401D9C07FE)
  if not ok or transition then return false end
  local mission=read_global_int(g,FMMC_PROFILE.mission_hash_index,"Catalogue handoff")
  -- A state0 controller may still be on the cut board. Only independently
  -- verified active objectives prove the admission handoff; count1 does not.
  if mission~=0 then
   if mission~=f.mission then return false end
   local status=HeistOps.solo_mission_status(f.family)
   if not status or status.state~='IN_MISSION' then return false end
  end
 end
 if HeistOps.restore_catalogue(f) then HeistOps.catalogue_cleanup=nil;return true end
 return false
end

local function solo_launch_status(family)
 local result={support="BLOCKED",ready=false,family=family,source_revision=SOURCE_REVISION,live_status="LIVE_RETEST_REQUIRED"}
 local ctx,why,state=launch_context();if not ctx then result.reason=why;result.state=state;return result end
 local detected,heist=HeistOps.identify(ctx.globals,ctx.mission)
 if detected~=family then result.reason="The active job is not a recognized finale in this family.";return result end
 local valid,guard=HeistOps.launch_guard(ctx.hash);if not valid then result.reason=guard;return result end
 local read=function(i)return read_global_int(ctx.globals,i,"Solo-launch field")end
 local ok,minimum=pcall(ctx.locals.GetInt,ctx.hash,FMMC_PROFILE.minimum_players_local)
 local teams,total=read(FMMC_PROFILE.team_count_index),read(FMMC_PROFILE.minimum_players_index)
 if not ok or not minimum or minimum<1 or minimum>4 or (not ctx.transition_host and (not teams or teams<1 or teams>4)) or not total or total<1 or total>4 then result.reason="Launcher player/team minimums are not ready.";return result end
 -- The invite lobby precedes the planning roster. Its real joined-player
 -- count is func_11040 -> func_10594, not Global_1938374.f_3001.
 local invite=ctx.transition_host==true
 local own_team
 if invite then
  local joined=read(2686124+1+2805)
  if joined and joined>=2 and joined<=4 then
   result.state='MULTIPLAYER';result.reason='Crew members joined; Solo Launch yields to the normal multiplayer requirements.';return result
  end
  if joined~=1 then result.reason="Wait for exactly one player in your hosted invite lobby (joined="..tostring(joined)..").";return result end
  if type(teams)~="number" or teams%1~=0 or teams<1 or teams>4 then
   result.reason=("Invite lobby team metadata is not initialized (teams=%s, playerMin=%s, localMin=%s).")
    :format(tostring(teams),tostring(total),tostring(minimum));return result
  end
 else
  local bits=read(FMMC_PROFILE.active_slots_index);local n,seen=0,{}
  if not bits or bits<1 or bits>15 then result.reason='Wait for a readable heist lobby crew.';return result end
  for slot=0,3 do if active_slot(bits,slot) then
   local pid=read(FMMC_PROFILE.participant_base+slot)
   if not pid or pid<0 or pid>31 or seen[pid] then result.reason='The launcher crew is changing.';return result end
   seen[pid]=true;n=n+1
  end end
  if n>1 then result.state='MULTIPLAYER';result.reason='Crew members joined; Solo Launch yields to the normal multiplayer requirements.';return result end
  if n~=1 or not seen[ctx.player_id] then result.reason="Wait for exactly one local-host participant.";return result end
  own_team=read(FMMC_PROFILE.player_team_base+ctx.player_id*FMMC_PROFILE.player_team_stride)
  if not own_team or own_team<0 or own_team>=teams then result.reason="Choose the host's role on the heist board first.";return result end
 end
 local classic=family=="apartment" or family=="casino" or family=="doomsday"
 local roles=teams
 if classic and solo_override and same_launcher_allocation(ctx.identity,solo_override.identity) and ctx.mission==solo_override.mission then
  for _,f in ipairs(solo_override.fields) do if f.index==FMMC_PROFILE.team_count_index then roles=f.original end end
 end
 local fields={{kind="global",index=FMMC_PROFILE.minimum_players_index,original=total,applied=1},
  {kind="local",index=FMMC_PROFILE.minimum_players_local,original=minimum,applied=1}}
 if invite and teams and teams>=1 and teams<=4 then
  local assigned=read(FMMC_PROFILE.player_team_base+ctx.player_id*FMMC_PROFILE.player_team_stride)
  if classic and (assigned==nil or assigned%1~=0 or assigned<-1 or assigned>=teams) then
   result.reason="Invite role assignment is invalid.";return result
  end
  own_team=assigned and assigned>=0 and assigned<teams and assigned or 0 -- -1 is provisional before board assignment.
 end
 if own_team~=nil then
  for team=0,roles-1 do
   local value=read(FMMC_PROFILE.team_minimum_base+team)
   if not value or value<0 or value>4 then result.reason="A role minimum is unreadable.";return result end
   fields[#fields+1]={kind="global",index=FMMC_PROFILE.team_minimum_base+team,original=value,applied=team==own_team and 1 or 0}
  end
 end
 -- Lobby player minima and controller crew minima are separate. The Enhanced
 -- controller copies f_3772 into its active team count (root.f_993), then tests
 -- tcmin and essential-role flags for each active team. Normalize both team
 -- counts, since func_10623 resets the active count from the defined count.
 -- Role definition records stay intact; this profile requires the first host role.
 if classic then
  if not solo_override then
   local phase,why=HeistOps.solo_write_phase(ctx,family)
   if not phase then result.reason=why;return result end
   phase.family=family;result.admission_phase=phase
  end
  if own_team~=0 then result.reason="Solo launch needs the host in the first role on the board.";return result end
  local verified,why=true,nil
  if not solo_override then verified,why=pcall(function() HeistOps.guard(ctx.hash,"apartment_solo_admission");HeistOps.guard(ctx.hash,"solo_catalogue") end) end
  if not verified then result.reason=tostring(why);return result end
  local defaults=read(FMMC_PROFILE.default_team_count_index)
  local crew=read(FMMC_PROFILE.controller_crew_minimum_base)
  if not defaults or defaults%1~=0 or defaults<1 or defaults>roles then result.reason="Apartment active team count is invalid.";return result end
  if not crew or crew%1~=0 or (crew~=11 and (crew<0 or crew>4)) then result.reason="Apartment controller crew minimum is invalid.";return result end
  fields[#fields+1]={kind="global",index=FMMC_PROFILE.default_team_count_index,original=defaults,applied=1}
  fields[#fields+1]={kind="global",index=FMMC_PROFILE.controller_crew_minimum_base,original=crew,applied=0}
  fields[#fields+1]={kind="global",index=FMMC_PROFILE.team_count_index,original=teams,applied=1}
  local catalogue=solo_catalogue(ctx)
  if not catalogue then result.reason="The selected job's loaded catalogue identity/minimum is unavailable.";return result end
  fields[#fields+1]=catalogue
  result.catalogue_minimum,result.catalogue_namespace,result.catalogue_row=catalogue.original,catalogue.namespace,catalogue.row
  result.default_teams,result.controller_crew_minimum=defaults,crew
 end
 result.roster_route=invite and "invite" or "planning"
 local pf=read(FMMC_PROFILE.metadata_player_flags_base+ctx.leader*FMMC_PROFILE.player_team_stride)
 local cf=read(FMMC_PROFILE.metadata_creator_flags_index)
 if pf==nil or cf==nil then result.reason="Launcher metadata source is unreadable.";return result end
 result.metadata_route=active_slot(pf,0) or active_slot(cf,5)
 if result.metadata_route then local value=read(FMMC_PROFILE.metadata_minimum_index);if not value or value<1 or value>4 then result.reason="Metadata minimum is invalid.";return result end
  fields[#fields+1]={kind="global",index=FMMC_PROFILE.metadata_minimum_index,original=value,applied=1};result.metadata_minimum=value
 end
 result.support,result.ready,result.state="EXPERIMENTAL",true,solo_override and "APPLYING" or "SUPPORTED_READY"
 result.identity,result.mission,result.instance_id=ctx.identity,ctx.mission,ctx.identity.thread_id
 result.detected_family,result.heist,result.teams=detected,heist,teams
 result.minimum_players,result.activity_minimum,result.team_minimum=minimum,total,read(FMMC_PROFILE.team_minimum_base)
 result.fields,result.override_active,result.own_team=fields,solo_override~=nil,own_team
 result.reason=classic and "Ready to apply the selected job minimum and single-team crew contract; mission entry needs live testing." or "Recognized finale: one local host, own role minimum one, empty role minima zero. Mission entry requires live testing."
 return result
end

local function read_launch_field(ctx, field)
    local ok, value
    if field.kind == "local" then ok, value = pcall(ctx.locals.GetInt, ctx.hash, field.index)
    else ok, value = pcall(ctx.globals.GetInt, field.index) end
    return ok and tonumber(value) or nil
end

-- Admission and restoration have different roster requirements. A friend
-- joining must stop new solo writes immediately, while the same verified owner
-- may still restore the original multiplayer minima before controller capture.
function HeistOps.solo_roster_matches(ctx,phase)
 if not phase then return true end
 local ok,result=pcall(function()
  local g=ctx.globals
  local role=read_global_int(g,FMMC_PROFILE.player_team_base+ctx.player_id*FMMC_PROFILE.player_team_stride,'Solo admission role')
  local classic=phase.family=='apartment' or phase.family=='casino' or phase.family=='doomsday'
  if ctx.transition_host then
   if read_global_int(g,2688930,'Solo invite crew')~=1 then return false end
   if classic then return role==0 or role==-1 end
   return role==phase.own_team or role==-1
  end
  local bits=read_global_int(g,FMMC_PROFILE.active_slots_index,'Solo board crew')
  if type(bits)~='number' or bits%1~=0 or bits<1 or bits>15 then return false end
  local count,owner=0,false
  for slot=0,3 do if active_slot(bits,slot) then
   count=count+1
   owner=read_global_int(g,FMMC_PROFILE.participant_base+slot,'Solo board participant')==ctx.player_id
   if not owner then return false end
  end end
  return count==1 and owner and role==(classic and 0 or phase.own_team)
 end)
 return ok and result==true
end
local function write_launch_field(ctx, field, value, phase, restoring)
    if not launcher_still_owned(ctx) or not HeistOps.solo_phase_matches(ctx,phase)
        or not restoring and not HeistOps.solo_roster_matches(ctx,phase) then return false end
    if field.kind=="catalogue" then
        local selected=solo_catalogue(ctx)
        if not selected or selected.index~=field.index or selected.id~=field.id or not catalogue_matches(ctx.globals,field) then return false end
    end
    local ok, accepted
    if field.kind == "local" then ok, accepted = pcall(ctx.locals.SetInt, ctx.hash, field.index, value)
    else ok, accepted = pcall(ctx.globals.SetInt, field.index, value) end
    return ok and accepted ~= false and read_launch_field(ctx, field) == value
        and HeistOps.solo_phase_matches(ctx,phase)
        and (restoring or HeistOps.solo_roster_matches(ctx,phase))
end

-- A bounded read-only handoff trace distinguishes lobby admission from mission entry.
-- Only armed after an actual override loses its launcher, never during idle gameplay.
function HeistOps.trace_solo_handoff(state, reason)
    if HeistOps.solo_handoff then return end
    HeistOps.solo_handoff={family=state.family,mission=state.mission,
        deadline=runtime_time_ms()+30000,fast_until=runtime_time_ms()+8000,next_poll=0,last=nil}
    log("Info", "solo-handoff begin family="..tostring(state.family).." reason="..tostring(reason))
end
function HeistOps.tick_solo_handoff(now)
    local trace=HeistOps.solo_handoff
    if not trace or now<trace.next_poll then return end
    if now>trace.deadline then
        log("Info","solo-handoff end controllerSeen="..tostring(trace.controller_seen==true).." playable=UNVERIFIED")
        HeistOps.solo_handoff=nil;return
    end
    trace.next_poll=now+(now<trace.fast_until and 100 or 1000)
    begin_explicit_thread_refresh()
    local function count(name)
        local hash=script_hash(name);return hash and thread_count(hash) or -1
    end
    local launcher=count("fmmc_launcher")
    local controller=count(trace.family=="cayo" and "fm_mission_controller_2020" or "fm_mission_controller")
    if controller and controller>0 then trace.controller_seen=true end
    local g=binding("ScriptGlobal")
    local function read(index)return g and read_global_int(g,index,"Solo handoff observation") or -1 end
    local controller_teams,controller_state,crew_rejected=-1,-1,-1
    if controller==1 and trace.family=="apartment" then
        local l,n,script=binding("ScriptLocal"),binding("Natives"),binding("Script")
        local h=script_hash("fm_mission_controller")
        local identity=HeistOps.script_identity(h,20412)
        if identity and l and type(l.GetInt)=="function" and script and type(script.ExecuteAsScript)=="function" then
            local observed
            local ok=pcall(script.ExecuteAsScript,h,function()
                if n.InvokeInt(0xC30338E8088E2E21)~=identity.thread_id
                    or n.InvokeInt(0x8A1C8B1738FFE87E)%4294967296~=h%4294967296
                    or l.GetPtr(h,20412)~=identity.pointer then return nil end
                local values={l.GetInt(h,21405),l.GetInt(h,20412),l.GetInt(h,20415)}
                if l.GetPtr(h,20412)~=identity.pointer then return nil end
                observed=values
            end)
            local after=ok and HeistOps.script_identity(h,20412) or nil
            if same_launcher(identity,after) and type(observed)=="table"
                and type(observed[1])=="number" and type(observed[2])=="number" and type(observed[3])=="number" then
                controller_teams,controller_state=observed[1],observed[2]
                crew_rejected=observed[3]%4294967296>=2147483648 and 1 or 0
            end
        end
    end
    local line=("launcher=%s controller=%s mission=%s joined=%s playerMin=%s defaultTeams=%s teams=%s minTeams=%s leader=%s crewMin=%s role=%s controllerTeams=%s controllerState=%s crewRejected=%s")
        :format(tostring(launcher),tostring(controller),tostring(read(FMMC_PROFILE.mission_hash_index)),
            tostring(read(2688930)),tostring(read(FMMC_PROFILE.minimum_players_index)),tostring(read(4722364)),
            tostring(read(FMMC_PROFILE.team_count_index)),tostring(read(4722366)),tostring(read(FMMC_PROFILE.leader_index)),
            tostring(read(FMMC_PROFILE.controller_crew_minimum_base)),
            tostring(read(FMMC_PROFILE.player_team_base+(local_player_id() or 0)*FMMC_PROFILE.player_team_stride)),
            tostring(controller_teams),tostring(controller_state),tostring(crew_rejected))
    if line~=trace.last then trace.last=line;log("Info","solo-handoff "..line) end
end

local function restore_solo_launch(reason)
    local state = solo_override
    if not state then return true, "No CScript solo-launch override is active." end
    launch_cache = nil
    local ctx, err, context_state = launch_context()
    if not ctx and context_state ~= "NOT_IN_LOBBY" and context_state ~= "NOT_HOST" then
        state.failed, state.restore_pending, state.restore_reason = true, true, reason
        launch_event = { state = "FAILED", reason = "Restoration is pending: launcher identity is unavailable; owned values were retained without writes. " .. tostring(err) }
        return false, launch_event.reason
    end
    if not ctx or not same_launcher_allocation(ctx.identity,state.identity) or ctx.mission~=state.mission or ctx.leader~=state.leader then
        HeistOps.detach_solo(state,"Launcher, mission, or host changed; stale launcher values were discarded without writes.")
        if reason=="toggle disabled" or reason=="Unload" or reason=="CScript stop" then HeistOps.tick_catalogue_cleanup(true) end
        return true,launch_event.reason
    end
    local phase,phase_error=HeistOps.solo_write_phase(ctx,state.family)
    if not phase then
        local active=HeistOps.solo_mission_status(state.family)
        local current=HeistOps.controller(state.family,true)
        local captured=current and current.script=='fm_mission_controller'
            and type(ctx.locals.GetInt(current.script_hash,current.profile.teams))=='number'
            and ctx.locals.GetInt(current.script_hash,current.profile.teams)>0
        if active or captured then
            HeistOps.detach_solo(state,'The controller captured admission; launcher baselines were not replayed into the mission.')
            if active and active.state=='IN_MISSION' then HeistOps.tick_catalogue_cleanup(false) end
            return true,launch_event.reason
        end
        state.failed,state.restore_pending,state.restore_reason=true,true,reason
        launch_event={state='RESTORING',reason='Restoration is retained without writes until the planning phase is verified. '..tostring(phase_error)}
        return false,launch_event.reason
    end
    phase.family=state.family
    state.identity=ctx.identity
    solo_override = nil
    local restored, untouched = 0, 0
    for index = #state.fields, 1, -1 do
        local field = state.fields[index]
        local current = read_launch_field(ctx, field)
        if field.kind=="catalogue" and catalogue_matches(ctx.globals,field)==false then field.owned=false end
        if field.owned and current == nil then
            solo_override = state
            state.failed, state.restore_pending, state.restore_reason = true, true, reason
            launch_event = { state = "FAILED", reason = "An owned launcher field is unreadable; restoration is retained for a later bounded retry." }
            return false, launch_event.reason
        end
        if field.owned and current == (field.applied or 1) then
            local restored_field
            if field.kind=='catalogue' then
                restored_field=HeistOps.solo_phase_matches(ctx,phase) and HeistOps.restore_catalogue(field)
                    and HeistOps.solo_phase_matches(ctx,phase)
            else restored_field=write_launch_field(ctx,field,field.original,phase,true) end
            if not restored_field then
                solo_override = state
                state.failed, state.restore_pending, state.restore_reason = true, true, reason
                launch_event = { state = "FAILED", reason = "An owned launcher minimum failed restoration; its snapshot is retained for retry." }
                return false, launch_event.reason
            end
            field.owned = false
            restored = restored + 1
        else untouched = untouched + 1 end
    end
    launch_event = { state = "RELEASED", reason = ("Solo override released (%s): %d restored, %d left untouched."):format(tostring(reason or "manual"), restored, untouched) }
    log("Info", "solo-launch state=RELEASED instance=" .. tostring(state.identity.thread_id) .. " " .. launch_event.reason)
    return true, launch_event.reason
end

-- Rebind an existing allocation without restoring common applied fields first.
-- Each original value remains the original lease baseline, not the value read
-- after our own override. New route fields acquire their own fresh snapshots.
local function reconcile_solo_launch(state,status,ctx,phase)
 assert(HeistOps.solo_phase_matches(ctx,phase) and HeistOps.solo_roster_matches(ctx,phase),
  'Solo Launch admission changed before route maintenance.')
 local fields,wanted={},{}
 for _,field in ipairs(state.fields) do
  fields[field.kind..':'..field.index..':'..tostring(field.id or '')]=field
 end
 for _,desired in ipairs(status.fields) do
  local key=desired.kind..':'..desired.index..':'..tostring(desired.id or '')
  local field=fields[key]
  if not field then
   field=desired;state.fields[#state.fields+1]=field;fields[key]=field
  end
  wanted[field]=true
  local current=read_launch_field(ctx,field)
  assert(current~=nil,'A retained launcher minimum is unreadable.')
  local value=desired.applied or 1
  assert(current==(field.applied or 1) or current==field.original,
   'A launcher minimum changed independently; retained admission cannot overwrite it.')
  if current~=value then
   assert(HeistOps.solo_phase_matches(ctx,phase),'Controller team capture stopped Solo Launch maintenance.')
   field.applied=value;field.owned=true
   assert(write_launch_field(ctx,field,value,phase),'Solo Launch route maintenance did not verify.')
   state.reapplications=state.reapplications+1
  else field.applied=value end
  if field.original==value then field.owned=false end
  field.retired=nil
 end
 for _,field in ipairs(state.fields) do
  if not wanted[field] and not field.retired then
   if field.owned and read_launch_field(ctx,field)==(field.applied or 1) then
    assert(HeistOps.solo_phase_matches(ctx,phase),'Controller team capture stopped Solo Launch route restoration.')
    if field.kind=='catalogue' then assert(HeistOps.restore_catalogue(field),'Prior catalogue restoration is pending.')
    else assert(write_launch_field(ctx,field,field.original,phase,true),'Prior route restoration did not verify.');field.owned=false end
   end
   field.retired=true
  end
 end
 assert(HeistOps.solo_phase_matches(ctx,phase) and HeistOps.solo_roster_matches(ctx,phase),
  'Solo Launch admission changed before route verification.')
 state.metadata_route,state.roster_route,state.own_team=status.metadata_route,status.roster_route,status.own_team
 state.field_count=#status.fields
 state.held,state.display_state,state.hold_trace=nil,nil,nil
 launch_event={state='APPLYING',reason='Scoped finale admission remains applied to the current launcher; actual mission entry is unverified.'}
 HeistOps.solo_auto.state,HeistOps.solo_auto.reason='ACTIVE',launch_event.reason
end

local function enable_solo_launch(family)
    if HeistOps.late_admission then
        HeistOps.tick_late_admission()
        if HeistOps.late_admission then return false,'The previous solo mission admission is still owned.','HELD' end
    end
    if not started then return false, "Heist runtime is stopped." end
    begin_explicit_thread_refresh()
    if solo_override then return not solo_override.failed, solo_override.failed and "Restore the failed solo override before retrying." or "The scoped solo override is already applying; mission entry is unverified." end
    local status = solo_launch_status(family)
    if not status.ready then return false, status.reason end
    local ctx, err = launch_context()
    if not ctx then return false, err end
    if not same_launcher(ctx.identity, status.identity) or ctx.mission ~= status.mission then return false, "Launcher changed during admission." end
    local phase=status.admission_phase or HeistOps.solo_write_phase(ctx,family)
    if not phase then return false,'Controller admission changed before Solo Launch could be applied.' end
    phase.family,phase.own_team=family,status.own_team
    if not HeistOps.solo_phase_matches(ctx,phase) or not HeistOps.solo_roster_matches(ctx,phase) then return false,'Controller or crew admission changed before Solo Launch could be applied.' end
    local fields=status.fields
    local arm_scope=board_identity()
    local arm_owner,arm_slot
    if family=='casino' or family=='doomsday' then
        local rids,members=HeistOps.member_rids({{player=ctx.player_id}})
        if not arm_scope or not rids then return false,'The initial solo owner identity is unavailable.','HELD' end
        arm_owner=members[ctx.player_id]
        arm_slot=tonumber(arm_scope.scope:match('^%d+:(%d+):'))
        if arm_slot~=0 and arm_slot~=1 then return false,'The initial character identity is unavailable.','HELD' end
    end
    local prior=HeistOps.catalogue_cleanup
    if prior then
        local adopted=false
        for _,field in ipairs(fields) do
            if field.kind=='catalogue' and field.index==prior.index and field.id==prior.id
                and catalogue_matches(ctx.globals,prior)==true and read_launch_field(ctx,field)==prior.applied then
                field.original,field.owned,field.transferred=prior.original,prior.owned,true
                HeistOps.catalogue_cleanup=nil;adopted=true;break
            end
        end
        if not adopted and not HeistOps.tick_catalogue_cleanup(true) then return false,'Prior job catalogue cleanup is pending.' end
    end
    local arm_successor=HeistOps.successor_contract(ctx.globals,family,ctx.mission)
    solo_override = { hash = ctx.hash, identity = ctx.identity, mission = ctx.mission, leader = ctx.leader,
        family = family, scope=arm_scope and arm_scope.scope, owner_rid=arm_owner, owner_pid=ctx.player_id, character_slot=arm_slot,
        fields = fields, metadata_route = status.metadata_route, roster_route = status.roster_route, own_team = status.own_team,
        field_count=#fields,original = status.minimum_players, reapplications = 0,successor_contract=arm_successor }
    for _, field in ipairs(fields) do
        local expected=field.transferred and field.applied or field.original
        if read_launch_field(ctx, field) ~= expected then
            restore_solo_launch('context changed during admission')
            return false,'A launcher minimum changed during admission; the transaction was cancelled.'
        end
        if expected ~= (field.applied or 1) then
            field.owned = true -- Include mutation-then-rejection in restoration.
            if not write_launch_field(ctx,field,field.applied or 1,phase) then
                if not HeistOps.solo_phase_matches(ctx,phase) then
                    HeistOps.hold_solo(solo_override,'Controller capture interrupted admission; owned values are retained without further writes.')
                    return false,launch_event.reason,'HELD'
                end
                local changed=solo_launch_status(family)
                local _,message=restore_solo_launch('write/read-back failed')
                if changed.state=='MULTIPLAYER' then return false,message,'MULTIPLAYER' end
                return false,'A launcher minimum did not verify. '..tostring(message)
            end
        end
    end
    if not HeistOps.solo_phase_matches(ctx,phase) then
        HeistOps.hold_solo(solo_override,'Controller capture interrupted admission verification; owned values are retained without further writes.')
        return false,launch_event.reason,'HELD'
    end
    if not HeistOps.solo_roster_matches(ctx,phase) then
        local changed=solo_launch_status(family)
        local _,message=restore_solo_launch('crew changed during admission verification')
        return false,message,changed.state=='MULTIPLAYER' and 'MULTIPLAYER' or nil
    end
    launch_cache = nil
    next_launch_tick_ms = 0
    launch_event = { state = "APPLYING", reason = "Scoped finale player and role minimums applied; actual mission entry is unverified." }
    log("Info", ("solo-launch state=APPLYING family=%s instance=%d mission=%s fields=%d metadataRoute=%s entry=LIVE_RETEST_REQUIRED"):format(
        tostring(family), ctx.identity.thread_id, tostring(ctx.mission), #fields, tostring(status.metadata_route)))
    if status.catalogue_minimum then
        log("Info",("solo-controller-admission activeTeams=%s->1 crewMin=%s->0 definedTeams=%s role=%s")
            :format(tostring(status.default_teams),tostring(status.controller_crew_minimum),tostring(status.teams),tostring(status.own_team)))
        log("Info",("solo-catalogue namespace=%s row=%s minimum=%s->1 definedTeams=%s->1"):format(tostring(status.catalogue_namespace),tostring(status.catalogue_row),tostring(status.catalogue_minimum),tostring(status.teams)))
    end
    return true, launch_event.reason
end

function HeistOps.set_solo_launch(enabled)
    HeistOps.solo_retired=nil -- An explicit toggle action uses fresh normal admission checks.
    if not enabled then HeistOps.solo_handoff=nil end
    if not started then return false, "Heist runtime is stopped." end
    local auto=HeistOps.solo_auto
    auto.enabled=enabled==true
    auto.next_poll=0
    if not auto.enabled then
        local ok,why=restore_solo_launch("toggle disabled")
        auto.state,auto.reason=ok and "OFF" or "RESTORING",why
        return HeistOps.tick_catalogue_cleanup(true) and ok,why
    end
    auto.state,auto.reason="WAITING","Waiting for your heist launch lobby."
    return true,auto.reason
end

function HeistOps.tick_solo_auto(now)
    local auto=HeistOps.solo_auto
    if not auto.enabled or solo_override or now<auto.next_poll then return end
    auto.next_poll=now+1000
    begin_explicit_thread_refresh()
    local ctx,why=launch_context()
    local function update(state,reason,stage,family)
        auto.state,auto.reason,auto.family=state,reason,family
        local line=("SoloLaunchAuto state=%s stage=%s family=%s mission=%s partyLeader=%s transitionHost=%s scriptHost=%s reason=%s")
            :format(state,stage,tostring(family),tostring(ctx and ctx.mission),tostring(ctx and ctx.party_leader),
                tostring(ctx and ctx.transition_host),tostring(ctx and ctx.identity.host),tostring(reason))
        if auto.trace~=line then auto.trace=line;pcall(log,"Info",line) end
    end
    -- The lobby can relinquish party authority after a mission starts. Report
    -- the independently verified current controller, without implying that an
    -- earlier override caused entry or relaxing any admission requirement.
    local mission_status=HeistOps.solo_mission_status()
    if mission_status then
        update(mission_status.state,mission_status.reason,'controller',mission_status.family);return
    end
    if not ctx then update("WAITING",why,"context");return end
    local retired=HeistOps.solo_retired
    if retired then
        if ctx.mission==retired.mission and same_launcher_allocation(ctx.identity,retired.identity) then
            update('HELD','Prior admission ownership changed; waiting for a fresh job or launcher.','retired');return
        end
        HeistOps.solo_retired=nil
    end
    local family=HeistOps.identify(ctx.globals,ctx.mission)
    if not family then update("WAITING","Waiting for a recognized heist finale.","mission");return end
    local status=solo_launch_status(family)
    if not status.ready then update(status.state=='MULTIPLAYER' and 'MULTIPLAYER' or 'WAITING',status.reason,"preflight",family);return end
    local ok,reason,held=enable_solo_launch(family)
    update(ok and 'ACTIVE' or held=='HELD' and 'HELD' or held=='MULTIPLAYER' and 'MULTIPLAYER' or 'FAILED',reason,'apply',family)
    if not ok and held~='HELD' and held~='MULTIPLAYER' then auto.enabled=false end -- A rejected write requires an explicit retry.
end

local function tick_launch_override(family, visible)
    pcall(HeistOps.tick_late_admission)
    if not started then return end
    if not visible and not solo_override and not ready_snapshot and not HeistOps.solo_auto.enabled and not HeistOps.solo_handoff and not HeistOps.catalogue_cleanup then return end
    local now = runtime_time_ms()
    if now < next_launch_tick_ms then return end
    next_launch_tick_ms = now + LAUNCH_TICK_MS
    HeistOps.tick_solo_handoff(now)
    HeistOps.tick_catalogue_cleanup(false)
    HeistOps.tick_solo_auto(now)
    local state = solo_override
    if ready_snapshot and ready_snapshot.restore_pending then restore_ready_snapshot() end
    if state and state.restore_pending then
        restore_solo_launch(state.restore_reason or "pending restoration")
    elseif state and not state.failed then
        local mission=HeistOps.solo_mission_status(state.family)
        if mission then
            if mission.state=='IN_MISSION' then
                HeistOps.detach_solo(state,'The exact finale controller has active objectives; admission handed off without replaying launcher values.')
                HeistOps.tick_catalogue_cleanup(false)
                HeistOps.solo_auto.state,HeistOps.solo_auto.reason,HeistOps.solo_auto.family=mission.state,mission.reason,mission.family
            else HeistOps.hold_solo(state,mission.reason,mission.state) end
        else
            local ctx,why=launch_context()
            local same=ctx and same_launcher_allocation(ctx.identity,state.identity)
                and ctx.mission==state.mission and ctx.leader==state.leader
            if not same then
                if HeistOps.solo_same_instance(state)==false then
                    restore_solo_launch('launcher allocation or job ended')
                    HeistOps.solo_auto.next_poll=0
                else HeistOps.hold_solo(state,'Waiting for launcher ownership to return; admission remains retained without writes. '..tostring(why or '')) end
            else
                state.identity=ctx.identity -- Same allocation; party authority was independently rechecked.
                local status=solo_launch_status(state.family)
                local phase,phase_error=HeistOps.solo_write_phase(ctx,state.family)
                if status.state=='MULTIPLAYER' and phase then
                    local restored,message=restore_solo_launch('real crew joined')
                    HeistOps.solo_auto.state,HeistOps.solo_auto.reason=restored and 'MULTIPLAYER' or 'RESTORING',message
                elseif not status.ready or not phase then
                    HeistOps.hold_solo(state,phase_error or status.reason)
                else
                    phase.family,phase.own_team=state.family,status.own_team
                    local ok,err=pcall(reconcile_solo_launch,state,status,ctx,phase)
                    if not ok then
                        if not HeistOps.solo_phase_matches(ctx,phase) then HeistOps.hold_solo(state,tostring(err))
                        else
                            local changed=solo_launch_status(state.family)
                            if not changed.ready and changed.state~='MULTIPLAYER' then
                                HeistOps.hold_solo(state,changed.reason)
                            else
                                local restored,message=restore_solo_launch('maintenance read-back failed')
                                HeistOps.solo_auto.state=restored and (changed.state=='MULTIPLAYER' and 'MULTIPLAYER' or 'FAILED') or 'RESTORING'
                                HeistOps.solo_auto.reason=tostring(err)..' '..tostring(message)
                                if changed.state~='MULTIPLAYER' then HeistOps.solo_auto.enabled=false end
                            end
                        end
                    end
                end
            end
        end
    end
    if (visible or solo_override or ready_snapshot) and (now >= next_launch_refresh_ms
        or launch_cache and family and launch_cache.family ~= family) then
        next_launch_refresh_ms = now + LAUNCH_REFRESH_MS
        refresh_launch_status(family or state and state.family)
    end
end


