                    result.active[#result.active + 1] = { key=item.key, script=item.script, label=item.label, threads=threads, hash=hash }
                end
            elseif not result.error then result.error = thread_err end
        elseif not result.error then result.error = hash_err end
    end
    if #result.active > 0 then result.status = "ACTIVE"
    elseif readable == 0 then result.status = "UNAVAILABLE"
