HeistOps.controllers={
 fm_mission_controller={root=20412,state=9,teams=21405,stage=29327,request=21470,trigger=20414,patch_offset=571,primary_signature=4,primary_patch_offset=173},
 fm_mission_controller_2020={root=56504,state=6,teams=58003,stage=66052,request=58089,patch_offset=88},
}
function HeistOps.controller(family,allow_result)
 local ok,result=pcall(function()
  assert(launch_build_status())
  local n,l,s=binding("Natives"),binding("ScriptLocal"),binding("Script")
  assert(n and l and l.GetPtr and s and s.ExecuteAsScript,"Controller identity services unavailable.")
  local name,hash,profile
  for candidate,p in pairs(HeistOps.controllers) do
   local h=assert(script_hash(candidate));local count=thread_count(h)
   assert(count==0 or count==1,"Controller instance is ambiguous.")
   if count==1 then assert(not name,"Multiple mission controllers are active.");name,hash,profile=candidate,h,p end
  end
  assert(name,"Start this finale before completing objectives.")
  local g=assert(global_service());local mission=g.GetInt(FMMC_PROFILE.mission_hash_index)
  local detected,heist=HeistOps.identify(g,mission)
  local family_names={apartment="Apartment",casino="Diamond Casino",cayo="Cayo Perico",doomsday="Doomsday"}
  assert(detected==family,detected and ("Heist mismatch: selected %s; detected %s."):format(
   family_names[family] or "unknown",family_names[detected] or "unknown") or heist)
  assert((family=="cayo")== (name=="fm_mission_controller_2020"),"This finale is using an unverified controller route.")
  local pid=assert(local_player_id());local tid,actual,host,participant,roster
  s.ExecuteAsScript(hash,function()
   actual=n.InvokeInt(0x8A1C8B1738FFE87E);tid=n.InvokeInt(0xC30338E8088E2E21)
   host=n.InvokeBool(0x83CD99A1E6061AB5);participant=n.InvokeInt(0x57A3BDDAD8E5AA0A)
   local count=n.InvokeInt(0x18D0456E86604654);assert(count>=1 and count<=4,"Controller roster unavailable.")
   roster={};local seen={}
   for i=0,31 do if n.InvokeBool(0x6FF8FF40B6357D45,i)==true then
    local player=n.InvokeInt(0x24FB80D107371267,i);assert(player>=0 and player<=31 and not seen[player],"Controller roster ambiguous.")
    seen[player]=true;roster[#roster+1]={slot=#roster+1,player=player,participant=i}
   end end
   assert(#roster==count and seen[pid],"Controller roster changed.")
  end)
  assert(actual%4294967296==hash%4294967296 and type(tid)=="number" and tid>0 and n.InvokeBool(0x46E9AE36D8FA6417,tid)==true,"Exact controller instance unavailable.")
  -- Resolve this same VM again with the context-bound host getter. A missing
  -- newer direct-thread getter must not erase valid exact-context host proof;
  -- every available host result must agree, and the controller flag stays mandatory.
  local exact,identity_error=HeistOps.script_identity(hash,profile.root,name);assert(exact,identity_error)
  assert(exact.thread_id==tid and exact.networked==true and host==true and exact.is_host==true and exact.host==pid,
   ("Finale host check failed (local=%s, hostFlag=%s, %s).")
    :format(tostring(pid),tostring(host),exact.host_diagnostic))
  local ptr=exact.pointer
  local root=l.GetInt(hash,profile.root);local f1=l.GetInt(hash,profile.root+1)
  assert(type(root)=="number" and type(f1)=="number","Controller state unreadable.")
  if not allow_result then
   assert(root==profile.state and active_slot(f1,17) and active_slot(f1,19) and not active_slot(f1,16),"Wait until finale objectives are active.")
   for bit=20,23 do assert(not active_slot(f1,bit),"A team already failed; restart the finale first.") end
   if name=="fm_mission_controller_2020" then
    local flags=l.GetInt(hash,profile.root+3)
    assert(not active_slot(flags,26) and not active_slot(flags,31),"Controller already recorded an invalid/failing team result.")
   end
   assert(not active_slot(l.GetInt(hash,profile.root+4),11),"Controller already has a forced result request.")
  end
  local rids,members=HeistOps.member_rids(roster);assert(rids,members)
  local economy=context_ref and context_ref.CScript and context_ref.CScript.Economy
  local slot=economy and economy.CurrentSlot and economy.CurrentSlot()
  assert(slot==0 or slot==1,'Controller character identity is unavailable.')
  local parts={cut_generation,slot,pid,mission,hash,tid,ptr}
  for _,row in ipairs(roster) do parts[#parts+1]=row.participant.."="..row.player.."@"..members[row.player] end
  return {family=family,heist=heist,script=name,script_hash=hash,profile=profile,controller_identity=table.concat(parts,":"),host_player=pid,host_participant_index=participant,participants=roster,mission=mission,pointer=ptr,thread_id=tid,root=root,participant_rids=rids,member_map=members,owner_rid=members[pid],character_slot=slot}
 end)
 if not ok then return nil,tostring(result) end;return result
end
function HeistOps.classic_party(ctx)
 if not ctx or type(ctx.participants)~='table' then
  return false,'Finale participants are unavailable.'
 end
 -- Admission/award requirements are not requirements of the objective
 -- success callbacks. The exact controller already validated the real roster.
 -- Do not invent missing players or reject a valid solo controller.
 if ctx.family~='cayo' and (#ctx.participants<1 or #ctx.participants>4) then
  return false,'The active finale roster is empty or invalid.'
 end
 return true
end
function HeistOps.member_rids(roster)
 local players=binding('Players')
 if not players or type(players.GetById)~='function' then
  return nil,'Player identity service is unavailable.'
 end
 local rids,seen,by_player={},{},{}
 for _,entry in ipairs(roster or {}) do
  local pid=entry.player
  if type(pid)~='number' or pid%1~=0 or pid<0 or pid>31 or by_player[pid] then
   return nil,'Finale participant index is invalid.'
  end
  local ok,value=pcall(function()
   local player=players.GetById(pid)
   local info=player and player:GetGamerInfo()
   return info and info.RockstarId
  end)
  if not ok or type(value)~='number' or value%1~=0 or value<1
    or value>9007199254740991 or seen[value] then
   return nil,'A unique Rockstar participant identity could not be read.'
  end
  seen[value]=true;by_player[pid]=value;rids[#rids+1]=value
 end
 if #rids==0 then return nil,'Finale roster is empty.' end
 table.sort(rids)
 return rids,by_player
end
-- These are the family's published/copied settlement inputs, not receipts
-- from each peer. Bind every occupied cell to the current Rockstar identity;
-- session player indices and slot order can change at launch.
function HeistOps.read_finish_party(family)
 local ctx,why=HeistOps.controller(family);if not ctx then return nil,why end
 local ok,result=pcall(function()
  local rids,members=HeistOps.member_rids(ctx.participants);assert(rids,members)
  local economy=context_ref and context_ref.CScript and context_ref.CScript.Economy
  local slot=economy and economy.CurrentSlot and economy.CurrentSlot()
  assert(slot==0 or slot==1,'The current character is unavailable.')
  assert(members[ctx.host_player],'The local controller owner is missing from the crew.')
  local g=assert(global_service());local cuts,rid_cuts,observed={},{},{}
  local function read(index) local value=g.GetInt(index);observed[index]=value;return value end
  local consumed=family=='apartment' and 2692687 or 2692926
  local maximum=family=='apartment' and 9999 or 999
  local function read_share(index)
   local value=read(index)
   assert(type(value)=='number' and value%1==0 and value>=0 and value<=maximum,'A settlement percentage is unreadable.')
   return value
  end
  local evidence='LOCAL_CONSUMED_SHARE'
  if #ctx.participants==1 then
   -- Guarded active-solo recalculation changes the consumed percentage only.
   -- Its original launch table is deliberately not a multiplayer receipt.
   cuts[ctx.host_player]=read_share(consumed)
  else
   local roster,shares,mirror
   if family=='apartment' then roster,shares,mirror=1936419,1936408,1941383;evidence='PUBLISHED_CREW_TABLE_AND_LOCAL_SHARE'
   elseif family=='doomsday' then roster,shares,mirror=1969929,1969934,1882858+ctx.host_player*321;evidence='PUBLISHED_CREW_TABLE_AND_LOCAL_SHARE'
   elseif family=='casino' then roster,shares=2689719,2689724;evidence='COPIED_SETTLEMENT_TABLE_AND_LOCAL_SHARE'
   elseif family=='cayo' then roster,shares=1981687+ctx.host_player*27,1981697+ctx.host_player*27;evidence='PUBLISHED_CREW_TABLE_AND_LOCAL_SHARE'
   else error('This heist has no verified settlement crew table.') end
   local seen={}
   for i=0,3 do
    local pid=read(roster+i);local share=read_share(shares+i)
    assert(type(pid)=='number' and pid%1==0 and pid>=-1 and pid<=31,'The settlement roster is unreadable.')
    if mirror then assert(read_share(mirror+i)==share,'The published and copied crew shares differ.') end
    if pid==-1 then assert(share==0,'An absent crew member retains a settlement share.')
    else
     assert(members[pid] and not seen[pid],'The settlement roster differs from the active crew.')
     seen[pid]=true;cuts[pid]=share
    end
   end
   for pid in pairs(members) do assert(seen[pid],'The settlement crew is incomplete.') end
   assert(read_share(consumed)==cuts[ctx.host_player],'The local consumed share differs from the crew table.')
  end
  for pid,rid in pairs(members) do rid_cuts[rid]=assert(cuts[pid],'A crew settlement share is missing.') end
  assert(HeistOps.same(ctx),'The controller changed while reading settlement shares.')
  local current,after=HeistOps.member_rids(ctx.participants);assert(current,after)
  for pid,rid in pairs(members) do assert(after[pid]==rid,'A crew identity changed while reading settlement shares.') end
  for index,value in pairs(observed) do assert(g.GetInt(index)==value,'Settlement shares changed while reading the crew.') end
  assert(economy.CurrentSlot()==slot,'The character changed while reading settlement shares.')
  return {family=ctx.family,heist=ctx.heist,mission=ctx.mission,count=#ctx.participants,
   identity=ctx.controller_identity,owner_rid=members[ctx.host_player],character_slot=slot,source_revision=SOURCE_REVISION,
   player_cuts=cuts,rid_cuts=rid_cuts,member_map=members,participant_rids=rids,share_evidence=evidence,
   local_solo=#ctx.participants==1 and ctx.participants[1].player==ctx.host_player}
 end)
 if not ok then return nil,tostring(result) end
 return result
end
function HeistOps.same(ctx)
 local current=HeistOps.controller(ctx.family,true)
 return current and current.controller_identity==ctx.controller_identity
end
