-- BEGIN ENDING CUTSCENE ADAPTER70
-- Exact finale ending gates and the controller's command-89 request bit.
-- The normal func5136/func19842 consumer handles this request outside the
-- menu's three-second/replay eligibility gate, then owns fade and cleanup.
-- This explicit host route never stops an arbitrary cutscene or sets outcomes.
HeistOps.ending_profiles={
 fm_mission_controller={signature='ending_skip_classic',ending=15619,request=20421,bit=11,initialization=15622,loader=12100,loader_signature='ending_loader_classic'},
 fm_mission_controller_2020={signature='ending_skip_modern',ending=55059,gate=55090,request=56513,bit=15},
}
function HeistOps.ending_valid(ctx)
 if not started or ctx.ending_generation~=cut_generation then return false end
 local exact=HeistOps.script_identity(ctx.script_hash,ctx.profile.root,ctx.script)
 if not exact then return nil end
 if exact.thread_id~=ctx.thread_id or exact.pointer~=ctx.pointer then return false end
 if exact.networked==false or exact.host~=nil and exact.host~=ctx.host_player then return false end
 if exact.networked~=true or exact.host==nil then return nil end
 if exact.is_host~=true then return false end
 local g=global_service();if not g then return nil end
 local mission=g.GetInt(FMMC_PROFILE.mission_hash_index)
 if type(mission)~='number'or mission%1~=0 then return nil end
 if mission%4294967296~=ctx.mission%4294967296 then return false end
 local current=HeistOps.controller(ctx.family,true)
 if not current then return nil end
 return current.controller_identity==ctx.controller_identity
end
function HeistOps.ending_phase(ctx)
 local p=assert(HeistOps.ending_profiles[ctx.script]);local l=assert(binding('ScriptLocal'))
 local function word(index)
  local value=l.GetInt(ctx.script_hash,index)
  assert(type(value)=='number'and value%1==0 and value>=-2147483648 and value<=4294967295,'Ending cutscene state unreadable.')
  return value
 end
 local ending=word(p.ending)
 ctx.ending_observation={ending=ending}
 if active_slot(ending,4)then return 'done'end
 if not active_slot(ending,3)or p.gate and not active_slot(word(p.gate),19)then return 'waiting'end
 local n=assert(binding('Natives'))
 local playing=n.InvokeBool(0xD3C2E180A40F031E)==true
 local observation=ctx.ending_observation;observation.playing=playing
 -- Casino may wait in case1 without playback until the 30s timeout. Wait for
 -- normal case0 setup and result initialization, then use the source's case2
 -- no-playback cleanup with the existing command89 request already latched.
 if not playing and ctx.family=='casino'then
  observation.initialization=word(p.initialization);observation.loader=word(p.loader)
  if active_slot(observation.initialization,12)and observation.loader==1 then return 'prepared'end
 end
 return playing and 'playing'or 'waiting'
end
function HeistOps.request_ending_skip(ctx,fence)
 local p=assert(HeistOps.ending_profiles[ctx.script]);local l=assert(binding('ScriptLocal'))
 local verified=pcall(HeistOps.guard,ctx.script_hash,p.signature)
 if not verified then return false,'source_signature_unavailable'end
 local loading=HeistOps.ending_phase(ctx)=='prepared'
 if loading and not pcall(HeistOps.guard,ctx.script_hash,p.loader_signature)then return false,'loader_signature_unavailable'end
 local before=l.GetInt(ctx.script_hash,p.request)
 assert(type(before)=='number'and before%1==0 and before>=-2147483648 and before<=4294967295,'Ending skip request unreadable.')
 -- Keep this request bound to the validated bitfield; do not overwrite other
 -- controller changes. The watcher consumes intent before entering this write.
 if l.GetInt(ctx.script_hash,p.request)~=before then return false end
 if not fence()then return false,'final_ownership_or_ending_unavailable'end
 if not active_slot(before,p.bit)then
  local accepted=l.SetInt(ctx.script_hash,p.request,before|(1<<p.bit))
  if accepted==false then return false,'request_write_rejected'end
 end
 local observed=l.GetInt(ctx.script_hash,p.request)
 if type(observed)~='number'or observed%1~=0 or not active_slot(observed,p.bit)then return false,'request_readback_unavailable'end
 if loading then
  -- This is the normal func5848(2) route, after case0 has completed. Do not
  -- set the timeout/failure flag or touch result inputs. Every observation
  -- below may invoke host services; exact ownership and intent are fenced last.
  if HeistOps.ending_phase(ctx)~='prepared'then return false,'loader_preparation_changed'end
  if not fence('prepared')then return false,'loader_ownership_or_ending_changed'end
  local accepted=l.SetInt(ctx.script_hash,p.loader,2)
  if accepted==false then return false,'loader_write_rejected'end
  if l.GetInt(ctx.script_hash,p.loader)~=2 then return false,'loader_readback_unavailable'end
  return true,'controller_ending_cleanup_requested'
 end
 return true,'controller_skip_requested'
end
HeistOps.ending_skip=Module.NewEndingCutsceneWatcher({Now=runtime_time_ms,Validate=HeistOps.ending_valid,
 Read=HeistOps.ending_phase,Request=HeistOps.request_ending_skip,Report=function(status)
  local o=status.observation or{}
  log('Info',('EndingCutscene family=%s state=%s phase=%s reason=%s ending=%s init=%s loader=%s playing=%s'):format(tostring(status.family),tostring(status.state),tostring(status.phase),tostring(status.reason),tostring(o.ending),tostring(o.initialization),tostring(o.loader),tostring(o.playing)))
 end})
function HeistOps.arm_ending_skip(ctx)
 local pin={};for key,value in pairs(ctx)do pin[key]=value end
 pin.ending_generation=cut_generation
 return HeistOps.ending_skip.Arm(pin)
end
-- END ENDING CUTSCENE ADAPTER70

