-- BEGIN NATIVE RESULTS ROUTE
HeistOps.native_results_profiles={
 fm_mission_controller={ending=15619,signature='native_results_classic'},
 fm_mission_controller_2020={ending=55059,signature='native_results_modern'},
}
local function success_branch_fence(tx,expected)
 local lease=assert(tx.success_branch);local ctx=tx.ctx
 assert(started and not tx.cancelled and cut_generation==lease.generation,'Completion was cancelled.')
 assert(HeistOps.same(ctx)==true,'Completion controller changed.')
 local l=assert(binding('ScriptLocal'))
 assert(l.GetInt(ctx.script_hash,ctx.profile.root)==ctx.profile.state,'Controller left active objectives.')
 local flags=l.GetInt(ctx.script_hash,ctx.profile.root+1)
 assert(type(flags)=='number' and flags%1==0 and active_slot(flags,17) and active_slot(flags,19)
  and not active_slot(flags,16),'Controller result is already processing.')
 if ctx.family=='cayo' then assert(active_slot(flags,14),'Cayo objectives are no longer active.') end
 for bit=20,23 do assert(not active_slot(flags,bit),'Controller recorded a team failure.') end
 assert(l.GetInt(ctx.script_hash,lease.index)==expected,'Ending selection changed.')
 assert(started and not tx.cancelled and cut_generation==lease.generation,'Completion was cancelled during validation.')
end
local function submission_owned(tx)
 assert(HeistOps.pending==tx and started and not tx.cancelled
  and tx.success_branch and cut_generation==tx.success_branch.generation,'Completion submission ownership ended.')
end
function HeistOps.add_result_initializer(tx)
 if tx.ctx.family~='casino' and tx.ctx.family~='doomsday' then return end
 local g=assert(global_service())
 local delegated,mode=g.GetInt(2685155+46+4),g.GetInt(1575068)
 assert(type(delegated)=='number' and delegated%1==0 and not active_slot(delegated,0),
  'The controller already delegated its ending job; start a fresh finale.')
 assert(mode==0,'Native controller results are unavailable in this game mode.')
 local found
 for i,sig in ipairs(HeistOps.signatures[tx.ctx.script])do
  if sig.name=='func_5850_native_initializer' then
   local bytes=sig.decoded or HeistOps.bytes(sig.bytes)
   assert(bytes[2]==2 and bytes[10]==0x56 and bytes[11]==3 and bytes[12]==0
    and bytes[13]==0x2e and bytes[14]==2 and bytes[15]==0,'Result initializer return branch changed.')
   assert(tx.addresses[i],'Result initializer code address unavailable.')
   tx.code_sites[#tx.code_sites+1]={signature=i,offset=10,original=3,value=0,result_initializer=true}
   found=true;break
  end
 end
 assert(found,'Native result initializer source guard unavailable.')
end
function HeistOps.result_initializer_pending(tx,same)
 local attempted=false
 for _,site in ipairs(tx.code_sites or {})do if site.result_initializer and site.attempted then attempted=true end end
 if not attempted or same==false or HeistOps.controller_ended(tx.ctx) then return false end
 if same~=true then return true end
 local ok,pending=pcall(function()
  local l,ctx=assert(binding('ScriptLocal')),tx.ctx
  local initialized=l.GetInt(ctx.script_hash,15622)
  local flags=l.GetInt(ctx.script_hash,ctx.profile.root+1)
  assert(type(initialized)=='number' and initialized%1==0 and type(flags)=='number' and flags%1==0,
   'Result initialization state unreadable.')
  if active_slot(initialized,12) or HeistOps.classic_failure(ctx) then return false end
  if active_slot(flags,16) then return true end
  for _,field in ipairs(tx.fields or {})do if field.attempted and field.index~=ctx.profile.trigger then
   local request=l.GetInt(ctx.script_hash,field.index)
   local stage=l.GetInt(ctx.script_hash,ctx.profile.stage+field.index-ctx.profile.request)
   assert(type(request)=='number' and request%1==0 and type(stage)=='number' and stage%1==0,
    'Result objective consumption unreadable.')
   if request==-1 and (stage==17 or stage==99999) then return true end
  end end
  return false
 end)
 return not ok or pending==true
end
function HeistOps.prepare_success_branch(tx)
 local p=assert(HeistOps.native_results_profiles[tx.ctx.script],'Native results route unavailable.')
 local generation=cut_generation
 assert(started,'Completion is stopped.')
 HeistOps.guard(tx.ctx.script_hash,p.signature)
 local before=assert(binding('ScriptLocal')).GetInt(tx.ctx.script_hash,p.ending)
 assert(type(before)=='number' and before%1==0 and before>=-2147483648 and before<=4294967295,
  'Ending selection is unreadable.')
 assert(not active_slot(before,3) and not active_slot(before,4),'The controller already selected an ending scene.')
 tx.success_branch={index=p.ending,original=before,generation=generation,owned=not active_slot(before,21)}
 success_branch_fence(tx,before)
end
function HeistOps.select_success_branch(tx)
 local lease=assert(tx.success_branch)
 success_branch_fence(tx,lease.original)
 if not lease.owned then return end
 -- Both selectors already implement bit21 as the no-scene branch. Result
 -- initialization, winner evaluation, rewards and Celebrations remain in GTA.
 local value=lease.original|(1<<21)
 lease.attempted=true
 local accepted=assert(binding('ScriptLocal')).SetInt(tx.ctx.script_hash,lease.index,value)
 assert(accepted~=false,'Native results selection was rejected.')
 success_branch_fence(tx,value)
end
function HeistOps.restore_success_branch(tx,same)
 local lease=tx.success_branch
 if not lease or not lease.owned or not lease.attempted or lease.committed then return true end
 if same==false then return true end
 if same~=true then return HeistOps.controller_ended(tx.ctx)==true end
 if lease.restoring then return false end
 lease.restoring=true
 local ok,result=pcall(function()
  local ctx,l=tx.ctx,assert(binding('ScriptLocal'))
  local flags=l.GetInt(ctx.script_hash,ctx.profile.root+1)
  local current=l.GetInt(ctx.script_hash,lease.index)
  local root=l.GetInt(ctx.script_hash,ctx.profile.root)
  assert(type(flags)=='number' and flags%1==0 and type(current)=='number' and current%1==0
   and type(root)=='number' and root%1==0,'Controller rollback state unreadable.')
  if active_slot(flags,16) or root~=ctx.profile.state
   or active_slot(current,3) or active_slot(current,4) then
   lease.committed=true;return true
  end
  for _,field in ipairs(tx.fields or {}) do
   if field.attempted and field.index~=ctx.profile.trigger then
    local team=field.index-ctx.profile.request
    local stage=l.GetInt(ctx.script_hash,ctx.profile.stage+team)
    local request=l.GetInt(ctx.script_hash,field.index)
    assert(type(stage)=='number' and stage%1==0 and type(request)=='number' and request%1==0,'Objective cleanup state unreadable.')
    if request==-1 and (stage==17 or stage==99999 or ctx.family=='cayo' and stage>=17) then
     lease.committed=true;return true
    end
   end
  end
  if not active_slot(current,21) then return true end
  if HeistOps.same(ctx)~=true then return false end
  -- Keep every unrelated bit the game changed after our selection.
  if l.GetInt(ctx.script_hash,lease.index)~=current then return false end
  local accepted=l.SetInt(ctx.script_hash,lease.index,current&~(1<<21))
  return accepted~=false and l.GetInt(ctx.script_hash,lease.index)==(current&~(1<<21))
 end)
 lease.restoring=false
 return ok and result==true
end
-- END NATIVE RESULTS ROUTE

function HeistOps.apartment_challenge_context(eligibility_only)
 local ctx,why=HeistOps.controller("apartment");if not ctx then return nil,why end
 local eligible,party_reason=HeistOps.classic_party(ctx)
 if not eligible then return nil,party_reason end
 local ok,err=pcall(function()
  if HeistOps.payout_guard_identity~=ctx.controller_identity then
   HeistOps.guard(ctx.script_hash,ctx.script);HeistOps.payout_guard_identity=ctx.controller_identity
  end
  local g=assert(global_service());ctx.difficulty=g.GetInt(4718592+3771)
  assert(type(ctx.difficulty)=="number" and ctx.difficulty%1==0 and ctx.difficulty>=0 and ctx.difficulty<=2,"Apartment difficulty is unreadable.")
  ctx.crew_deaths=0;ctx.participant_count=#ctx.participants
  -- func_2947 refuses Criminal Mastermind if any recorded crew death exists.
  -- Read this veto; bonus preparation must not erase deaths to manufacture it.
  for i=0,31 do
   local base=1927425+1+i*42
   local player,deaths=g.GetInt(base+1),g.GetInt(base+10)
   assert(type(player)=="number" and type(deaths)=="number","Challenge death history unreadable.")
   if player~=-1 and deaths>0 then ctx.crew_deaths=ctx.crew_deaths+deaths end
  end
  ctx.key=ctx.controller_identity..":"..ctx.difficulty..":"..ctx.crew_deaths
  if not eligibility_only then
   assert(ctx.difficulty==2,"The $12M total requires Hard difficulty for Criminal Mastermind.")
   assert(ctx.crew_deaths==0,"A crew death blocks Criminal Mastermind; All in Order and Loyalty remain separate awards.")
  end
 end)
 if not ok then return nil,tostring(err) end
 return ctx
end
function HeistOps.validate_apartment_challenge(expected)
 local current,why=HeistOps.apartment_challenge_context();if not current then return false,why end
 return current.key==expected.key,"Apartment bonus context changed."
end
HeistOps.finish_event={ready=false,reason="Start a finale to complete its objectives.",state="IDLE"}
-- Detached finish observations belong to one submitted controller identity.
-- Readers may retain the terminal result while that exact VM/crew remains;
-- another finale in the same family can never inherit the previous receipt.
function HeistOps.remember_classic_settlement()
 local receipt,event=HeistOps.classic_receipt,HeistOps.finish_event
 if not receipt or not event or event.family~=receipt.ctx.family then return end
 local states={SUBMITTED=true,AWAITING_RESULT=true,AWAITING_LOCAL_RESULT=true,
  CONTROLLER_PROCESSED_RESTORE_PENDING=true,RESTORE_PENDING=true,
  MISSION_FAILED=true,MISSION_FAILED_RESTORE_PENDING=true,REQUEST_TIMEOUT=true,
  OUTCOME_UNVERIFIED=true,LOCAL_FAILURE_OBSERVED=true,LOCAL_SUCCESS_OBSERVED=true,
  LOCAL_SUCCESS_BALANCE_OBSERVED=true}
 if not states[event.state] then return end
 receipt.event={family=receipt.ctx.family,heist=receipt.ctx.heist,
  identity=receipt.ctx.controller_identity,state=event.state,reason=event.reason,
  local_success=event.local_success==true,local_amount=event.local_amount,
  balance_delta=event.balance_delta,share_evidence=event.share_evidence,
  payment_verified=false,peer_payment_verified=false}
end
function HeistOps.classic_settlement_status()
 HeistOps.remember_classic_settlement()
 local receipt=HeistOps.classic_receipt
 if not receipt then return nil end
 local same=HeistOps.same(receipt.ctx)
 if same~=true then
  if same==false or HeistOps.controller_ended(receipt.ctx) then HeistOps.classic_receipt=nil end
  return nil
 end
 if not receipt.event then return nil end
 local result={};for key,value in pairs(receipt.event) do result[key]=value end
 return result
end
function HeistOps.refresh(family)
 HeistOps.remember_classic_settlement()
 if HeistOps.pending or HeistOps.classic_observation or (HeistOps.cayo_observation and not HeistOps.cayo_observation.passive) then return HeistOps.finish_event end
 if HeistOps.failed_until and runtime_time_ms()<HeistOps.failed_until
   and HeistOps.finish_event.family==family then return HeistOps.finish_event end
 local ctx,reason=HeistOps.controller(family)
 if not ctx then
  HeistOps.finish_event={ready=false,reason=reason,state="UNAVAILABLE",family=family}
  log_detection("InstantFinish",family,false,reason)
  return HeistOps.finish_event
 end
 local eligible,party_reason=HeistOps.classic_party(ctx)
 if not eligible then
  HeistOps.finish_event={ready=false,reason=party_reason,state="UNSUPPORTED_PARTY",family=family,heist=ctx.heist}
  log_detection("InstantFinish",family,false,party_reason)
  return HeistOps.finish_event
 end
 local ok,err=pcall(function()
  if family=='cayo' then HeistOps.read_guard(ctx,ctx.script);HeistOps.cayo_preflight(ctx)
  else HeistOps.classic_preflight(ctx) end
 end)
 HeistOps.finish_event={ready=ok,reason=ok and (family=="cayo" and "Request the Cayo crew result and observe the local payment." or "Complete active objectives through the controller's success callbacks.") or tostring(err),state=ok and "READY" or "UNAVAILABLE",family=family,heist=ctx.heist,live_status="LIVE_RETEST_REQUIRED"}
 log_detection("InstantFinish",family,ok,HeistOps.finish_event.reason)
 return HeistOps.finish_event
end
function HeistOps.code_address(tx,signature_index)
 local n,l,m,script=binding("Natives"),binding("ScriptLocal"),binding("Memory"),binding("Script")
 if thread_count(tx.ctx.script_hash)~=1 or l.GetPtr(tx.ctx.script_hash,tx.ctx.profile.root)~=tx.ctx.pointer then return nil end
 local tid;script.ExecuteAsScript(tx.ctx.script_hash,function() tid=n.InvokeInt(0xC30338E8088E2E21) end)
 if tid~=tx.ctx.thread_id or n.InvokeBool(0x46E9AE36D8FA6417,tid)~=true then return nil end
 signature_index=signature_index or 1
 local sig=HeistOps.signatures[tx.ctx.script][signature_index]
 sig.decoded=sig.decoded or HeistOps.bytes(sig.bytes)
 -- Resolve the whole expected function again. Never dereference the old code
 -- pointer after a host, roster, or script transition.
 local sites={}
 for _,site in ipairs(tx.code_sites or {}) do if site.signature==signature_index then
  -- This API returns the first fragment address. Existing patch operands are
  -- all in that fragment; reject a future cross-page site instead of adding
  -- a logical offset to an unrelated physical page.
  if site.offset<0 or site.offset>=math.min(#sig.decoded,16384-sig.pc%16384) then return nil end
  sites[#sites+1]=site
 end end
 for mask=(1<<#sites)-1,0,-1 do
  local bytes={};for i,v in ipairs(sig.decoded) do bytes[i]=v end
  for i,site in ipairs(sites) do if active_slot(mask,i-1) then bytes[site.offset+1]=site.value end end
  local first,matched=nil,true
  for _,part in ipairs(HeistOps.signature_segments(sig,bytes)) do
   local ptr=m.ScanScript(tx.ctx.script_hash,part.pattern)
   if type(ptr)~="number" or ptr<65536 or not HeistOps.matches(m,ptr,part.bytes) then matched=false;break end
   if not first then first=ptr end
  end
  if matched then return first end
 end
 return nil
end
function HeistOps.controller_ended(ctx)
 local n=binding("Natives");local tid=ctx and ctx.thread_id
 if not (n and type(n.InvokeBool)=="function" and type(tid)=="number" and tid>0 and tid%1==0) then return false end
 local ok,active=pcall(n.InvokeBool,0x46E9AE36D8FA6417,tid)
 return ok and (active==false or active==0)
end
function HeistOps.restore(reason,preserve_ending)
 if not preserve_ending then HeistOps.ending_skip.Cancel() end
 local tx=HeistOps.pending;if not tx then return true end
 if tx.submitting then tx.cancelled=true;return false end
 local same=HeistOps.same(tx.ctx)
 local m,l=binding("Memory"),binding("ScriptLocal");local all=true
 if same==nil and not HeistOps.controller_ended(tx.ctx) then
  for _,f in ipairs(tx.fields) do if f.attempted then all=false end end
  if tx.loot and tx.loot.attempted and not tx.loot.committed then all=false end
 end
 if same then
  -- Cleanup can run before Tick observes acknowledgement (for example unload).
  -- Detect committed objectives here too, so cleanup cannot erase paid loot.
  if tx.loot and tx.loot.attempted and not tx.loot.committed then
   local ok,consumed=pcall(function()
    local requests=0
    for _,field in ipairs(tx.fields) do
     if field.index~=tx.ctx.profile.trigger then
      requests=requests+1
      local stage=l.GetInt(tx.ctx.script_hash,tx.ctx.profile.stage+field.index-tx.ctx.profile.request)
      if l.GetInt(tx.ctx.script_hash,field.index)~=-1 or (stage~=17 and stage~=99999) then return false end
     end
    end
    return requests>0
   end)
   if ok and consumed then tx.loot.committed=true end
  end
  if tx.loot and tx.loot.attempted and not tx.loot.committed then
   local ok=pcall(function()
    assert(HeistOps.same(tx.ctx))
    local current=l.GetInt(tx.ctx.script_hash,tx.loot.index)
    assert(type(current)=='number' and current%1==0,'Casino take is unreadable during rollback.')
    if current==tx.loot.value then
     l.SetInt(tx.ctx.script_hash,tx.loot.index,tx.loot.original)
     assert(l.GetInt(tx.ctx.script_hash,tx.loot.index)==tx.loot.original,'Casino take rollback failed.')
    end
   end)
   all=all and ok
  end
  for i=#tx.fields,1,-1 do local f=tx.fields[i]
   if f.attempted then local ok=pcall(function()
    assert(HeistOps.same(tx.ctx))
    local current=l.GetInt(tx.ctx.script_hash,f.index)
    assert(type(current)=="number" and current==current and current%1==0,"Completion request is unreadable.")
    if current==f.value then l.SetInt(tx.ctx.script_hash,f.index,f.original);assert(l.GetInt(tx.ctx.script_hash,f.index)==f.original) end
   end);all=all and ok end
  end
 end
 if same~=false and not HeistOps.controller_ended(tx.ctx) then
  local readable,revoked=pcall(function()
   assert(HeistOps.same(tx.ctx)==true,'Controller ownership unreadable during request revocation.')
   for _,field in ipairs(tx.fields) do
    if field.attempted and field.index~=tx.ctx.profile.trigger then
     local current=l.GetInt(tx.ctx.script_hash,field.index)
     assert(type(current)=='number' and current%1==0,'Objective request revocation unreadable.')
     if current==field.value then return false end
    end
   end
   return true
  end)
  if not readable or not revoked then
   HeistOps.finish_event={ready=false,state='RESTORE_PENDING',payment_verified=false,
    reason='Objective request revocation is pending; its callback and prepared result inputs remain owned.'}
   return false
  end
 end
 local initializer_pending=HeistOps.result_initializer_pending(tx,same)
 for i=#(tx.code_sites or {}),1,-1 do local site=tx.code_sites[i]
  if site.attempted then
   if site.result_initializer and initializer_pending then all=false
   else
   local ok,address=pcall(HeistOps.code_address,tx,site.signature)
   if ok and address then
    local restored=pcall(function()
     local fresh=assert(HeistOps.code_address(tx,site.signature),"Code instance changed during restore")
     local at=fresh+site.offset;local value=m.ReadUByte(at)
     if value==site.value then m.WriteUByte(at,site.original);assert(m.ReadUByte(at)==site.original)
     elseif value~=site.original then error("Patch ownership changed") end
    end);all=all and restored
   elseif thread_count(tx.ctx.script_hash)~=0 then all=false end
   end
  end
 end
 local cayo_ok,cayo_clean=pcall(HeistOps.restore_cayo_score,tx,same)
 all=all and cayo_ok and cayo_clean
 local branch_ok,branch_restored=pcall(HeistOps.restore_success_branch,tx,same)
 all=all and branch_ok and branch_restored
 local score_ok,score_restored=pcall(HeistOps.restore_classic_score,tx,same)
 all=all and score_ok and score_restored
 local admission_ok,admission_restored=pcall(HeistOps.restore_classic_admission,tx,same)
 all=all and admission_ok and admission_restored
 if all then HeistOps.pending=nil end
 HeistOps.finish_event={ready=false,state=all and "RESTORED" or "RESTORE_PENDING",reason=reason or (same and "Temporary completion request restored." or "Controller ownership changed; script patch restored without replaying locals."),live_status="LIVE_RETEST_REQUIRED"}
 return all
end
-- Completion take preparation is independent of optional payment targets and
-- fee eligibility. The pure reader proves only the source-defined loot ceiling.
function HeistOps.casino_finish_take(ctx,preview)
 if preview==false then
  HeistOps.guard(ctx.script_hash,'reward_event')
  HeistOps.guard(ctx.script_hash,'classic_reward_owner')
 end
 local runtime=context_ref and context_ref.CScript and context_ref.CScript.HeistRuntimeProfiles
 assert(runtime and runtime.ReadFinishTakeSpec and runtime.ValidateFinishTakeSpec,'Casino take preparation is unavailable.')
 local spec,why=runtime.ReadFinishTakeSpec('casino');assert(spec,why)
 assert(spec.context.controller_identity==ctx.controller_identity,'Casino take belongs to another controller.')
 local l=assert(binding('ScriptLocal'))
 local before=l.GetInt(ctx.script_hash,20412+2686)
 assert(type(before)=='number' and before%1==0 and before>=0,'Casino collected take is unreadable.')
 assert(type(spec.amount)=='number' and spec.amount%1==0 and spec.amount>=0 and spec.amount<=2147483647,'Casino completion take is invalid.')
 local valid,reason=runtime.ValidateFinishTakeSpec(spec);assert(valid,reason)
 return {index=20412+2686,original=before,value=spec.amount,take_spec=spec}
end
-- func_815 rechecks these separate minima after func_871 acknowledges all
-- objectives. Derive the lease from actual controller assignments, including
-- f_168 subroles; board team assignments do not identify essential subroles.
function HeistOps.classic_admission_snapshot(ctx,teams)
 assert(ctx.script=="fm_mission_controller","Classic admission route changed.")
 local g,l=assert(global_service()),assert(binding("ScriptLocal"))
 assert(type(teams)=="number" and teams%1==0 and teams>=1 and teams<=4,"Controller teams are invalid.")
 assert(g.GetInt(4915255)==4 and g.GetInt(4915260)==4,"Controller admission arrays changed.")
 local mode=g.GetInt(4718606)
 assert(type(mode)=="number" and mode%1==0,"Controller subrole mode is unreadable.")
 local counts,roles,parts,fields={},{},{teams,mode&64},{}
 for team=0,teams-1 do
  counts[team]=0;roles[team]={0,0,0,0}
  assert(g.GetInt(4915261+team*5)==4,"Controller subrole array changed.")
 end
 for _,entry in ipairs(ctx.participants) do
  local participant=entry.participant
  assert(type(participant)=="number" and participant%1==0 and participant>=0 and participant<=31,"Controller participant is invalid.")
  local base=32786+participant*294
  local team,role,flags=l.GetInt(ctx.script_hash,base+1),l.GetInt(ctx.script_hash,base+168),l.GetInt(ctx.script_hash,base+127)
  assert(type(team)=="number" and team%1==0 and team>=0 and team<teams,"Controller team assignment is unavailable.")
  assert(type(role)=="number" and role%1==0 and role>=-1 and role<=3,"Controller subrole assignment is unavailable.")
  assert(type(flags)=="number" and flags%1==0 and (not active_slot(flags,22) or active_slot(flags,28)),"A controller participant is spectating; completion admission is unavailable.")
  counts[team]=counts[team]+1
  if active_slot(mode,6) and role>=0 then roles[team][role+1]=roles[team][role+1]+1 end
  parts[#parts+1]=table.concat({entry.player,participant,team,role},":")
 end
 local function field(index,maximum,kind)
  local original=g.GetInt(index)
  assert(type(original)=="number" and original%1==0 and original>=0 and (original<=4 or kind=="crew" and original==11),"Controller admission minimum is unreadable.")
  local applied=(original==11 and kind=="crew") and maximum or math.min(original,maximum)
  if kind=='subrole' and #ctx.participants>1 then
   assert(original<=maximum,("A required controller subrole is missing (%d assigned, %d required)."):format(maximum,original))
  end
  fields[#fields+1]={index=index,original=original,value=applied,kind=kind}
  parts[#parts+1]=index.."="..original
 end
 for team=0,teams-1 do
  -- Apartment func_2512 sums tcmin into its payout pool; keep those inputs.
  if ctx.family~="apartment" then field(4915256+team,counts[team],"crew")
  else
   local minimum=g.GetInt(4915256+team)
   assert(type(minimum)=='number' and minimum%1==0 and minimum>=0 and (minimum<=4 or minimum==11),'Apartment team minimum is unreadable.')
   -- func_828 (already whole-function guarded) resolves sentinel 11 through
   -- f_1772[team]. Keep the original global unchanged for the payout pool.
   if minimum==11 then
    local initial=l.GetInt(ctx.script_hash,ctx.profile.root+1773+team)
    assert(type(initial)=='number' and initial%1==0 and initial>=0 and initial<=4,'Apartment initial team count is unreadable.')
    if teams==1 then minimum=math.max(2,initial)
    else
     assert(initial>=1,'An empty dynamic Apartment team has an unverified admission branch.')
     minimum=initial
    end
   end
   assert(counts[team]>=minimum,("Apartment team %d needs %d crew members; %d are assigned."):format(team+1,minimum,counts[team]))
  end
  for role=0,3 do field(4915262+team*5+role,roles[team][role+1],"subrole") end
 end
 return {fields=fields,fingerprint=table.concat(parts,"|"),teams=teams,counts=counts,roles=roles}
end
function HeistOps.prepare_classic_admission(tx,teams)
 if tx.preview then HeistOps.read_guard(tx.ctx,"classic_completion_admission")
 else HeistOps.guard(tx.ctx.script_hash,"classic_completion_admission") end
 assert(HeistOps.same(tx.ctx),"Controller changed before admission preparation.")
 tx.admission=HeistOps.classic_admission_snapshot(tx.ctx,teams)
end
function HeistOps.apply_classic_admission(tx)
 local lease=assert(tx.admission);local g=assert(global_service())
 assert(HeistOps.same(tx.ctx),"Controller changed before admission write.")
 assert(HeistOps.classic_admission_snapshot(tx.ctx,lease.teams).fingerprint==lease.fingerprint,"Controller crew or subrole assignments changed before completion.")
 for _,f in ipairs(lease.fields) do
  if f.original~=f.value then
   assert(HeistOps.same(tx.ctx) and g.GetInt(f.index)==f.original,"Controller admission changed before write.")
   f.attempted=true;g.SetInt(f.index,f.value)
   assert(g.GetInt(f.index)==f.value,"Controller admission readback failed.")
  end
 end
end
function HeistOps.restore_classic_admission(tx,same)
 if not tx.admission then return true end
 -- Global mission data can belong to the next job. Never replay its old data
 -- after an identity change; preserve debt if the identity is only unreadable.
 if not same then return same==false or HeistOps.controller_ended(tx.ctx) end
 local g=assert(global_service());local all=true
 for i=#tx.admission.fields,1,-1 do
  local f=tx.admission.fields[i]
  if f.attempted then
   local ok=pcall(function()
    assert(HeistOps.same(tx.ctx),"Controller changed during admission restore.")
    local current=g.GetInt(f.index)
    assert(type(current)=="number" and current%1==0,"Controller admission is unreadable during restore.")
    if current==f.value then
     g.SetInt(f.index,f.original)
     assert(g.GetInt(f.index)==f.original,"Controller admission restore readback failed.")
    end
   end)
   all=all and ok
  end
 end
 return all
end
