-- func_767/768 award the remaining required score before the normal objective
-- result. A stage jump can run func_962 without that award; func_2077 then
-- correctly rejects a zero-score team even when no team-failure bit is set.
function HeistOps.classic_score_snapshot(ctx,teams)
 local g,l=assert(global_service()),assert(binding('ScriptLocal'))
 local snapshot={teams={},observations={},fields={}}
 local function read(kind,index,lo,hi,label)
  local value
  if kind=='local' then value=l.GetInt(ctx.script_hash,index) else value=g.GetInt(index) end
  assert(type(value)=='number' and value%1==0 and value>=lo and value<=hi,
   'Completion score '..label..' is unreadable or invalid.')
  snapshot.observations[#snapshot.observations+1]={kind=kind,index=index,value=value}
  return value
 end
 local mode=read('global',4718592+3794,0,3,'result mode')
 assert(mode~=3 and (mode~=1 or teams==1),
  'This competitive result mode cannot prove a passing result for every finale team.')
 snapshot.mode=mode
 -- func_255 may choose a per-stage alliance or its static fallback. Prove
 -- both available routes for every directed pair; no PED-state inference or
 -- rewriting of the game's alliance/result flags is necessary.
 if teams>1 then
  local alliance=read('global',4718592+3787,0,4294967295,'team alliance')
  local stages={}
  for team=0,teams-1 do stages[team]=read('global',1058150+14+1+team,-1,99999,'alliance stage') end
  for team=0,teams-1 do
   local flags=read('global',4718592+3838+1+team*26988+26719,0,4294967295,'stage alliance flags')
   for other=0,teams-1 do if team~=other then
    local bit=team*4+other
    assert(active_slot(alliance,bit),'Finale teams are not proven cooperative; completion would select competing winners.')
    if stages[team]>=0 and stages[team]<17 and active_slot(flags,stages[team])
     and stages[other]>=0 and stages[other]<17 then
     local dynamic=read('global',4718592+3838+1+team*26988+26721+1+stages[team],0,4294967295,'stage alliance')
     assert(active_slot(dynamic,bit),'The current objective uses an unverified competing-team alliance.')
    end
   end end
  end
 end
 local job=read('global',4718592+203791,-2147483648,2147483647,'job type')
 local flags=read('local',ctx.profile.root+2,-2147483648,4294967295,'award flags')
 local stored_player=read('local',3281,0,31,'local player')
 assert(stored_player==ctx.host_player,'Completion score belongs to another local player.')
 local local_mode
 local function add(team,index,original,value,label)
  assert(value>=0 and value<=2147483647 and value%1==0,'Completion score '..label..' would overflow.')
  local field={team=team,index=index,original=original,value=value,label=label}
  snapshot.fields[#snapshot.fields+1]=field
 end
 for team=0,teams-1 do
  local stage=read('local',ctx.profile.stage+team,0,99999,'objective stage')
  assert(stage<=17 or stage==99999,'Completion score objective stage is invalid.')
  local threshold=read('global',4718592+3838+1+team*26988+59,-1,2147483647,'required score')
  local required=threshold
  if threshold==-1 then
   local live=read('local',ctx.profile.root+1004+1+team,0,32,'live team count')
   required=math.max(live,1)
  elseif threshold==0 then
   if local_mode==nil then local_mode=read('global',2658296+1+stored_player*468+124,0,2147483647,'local mode') end
   required=local_mode==6 and 0 or 1
  end
  local score=read('local',ctx.profile.root+1232+1+team,0,2147483647,'base score')
  local bonus=read('local',18282+1+team,0,2147483647,'result bonus')
  assert(score+bonus<=2147483647,'Completion result score would overflow.')
  local delta=required-score
  if job==55 and active_slot(flags,21) then delta=1 end
  delta=math.max(delta,0)
  if stage>=17 then delta=0 end -- Do not rewrite an objective already consumed.
  local final=score+delta
  assert(final+bonus<=2147483647,'Completion result score would overflow.')
  assert(final+bonus>=required,'The existing result rule cannot reach the required passing score.')
  local row={team=team,stage=stage,threshold=threshold,required=required,score=score,bonus=bonus,delta=delta,value=final}
  snapshot.teams[#snapshot.teams+1]=row
  if delta>0 then
   local awarded=read('local',ctx.profile.root+2778+1+team,0,2147483647,'awarded score')
   local stage_score=read('local',ctx.profile.root+1237+1+team,0,2147483647,'current objective score')
   -- Keep the exact order of func_767 -> func_768.
   add(team,ctx.profile.root+2778+1+team,awarded,awarded+delta,'awarded score')
   add(team,ctx.profile.root+1232+1+team,score,final,'base score')
   if stage<17 then add(team,ctx.profile.root+1237+1+team,stage_score,stage_score+delta,'current objective score') end
  end
 end
 assert(HeistOps.same(ctx),'Controller changed during completion score preparation.')
 return snapshot
end
function HeistOps.prepare_classic_score(tx,teams)
 if tx.preview then HeistOps.read_guard(tx.ctx,'classic_score_award')
  else HeistOps.guard(tx.ctx.script_hash,'classic_score_award') end
 tx.score=HeistOps.classic_score_snapshot(tx.ctx,teams)
end
function HeistOps.validate_classic_score(tx)
 local score=assert(tx.score);local l,g=assert(binding('ScriptLocal')),assert(global_service())
 assert(HeistOps.same(tx.ctx),'Controller changed before completion score write.')
 local expected={}
 for _,field in ipairs(score.fields) do if field.attempted then expected[field.index]=field.value end end
 for _,observation in ipairs(score.observations) do
  local value,want
  if observation.kind=='local' then
   value=l.GetInt(tx.ctx.script_hash,observation.index)
   want=expected[observation.index] or observation.value
  else value=g.GetInt(observation.index);want=observation.value end
  assert(value==want,'Completion score inputs changed before objective submission.')
 end
end
function HeistOps.apply_classic_score(tx)
 local l=assert(binding('ScriptLocal'))
 HeistOps.validate_classic_score(tx)
 for _,field in ipairs(tx.score.fields) do
  HeistOps.validate_classic_score(tx)
  assert(l.GetInt(tx.ctx.script_hash,field.index)==field.original,'Completion score changed before write.')
  field.attempted=true
  l.SetInt(tx.ctx.script_hash,field.index,field.value)
  assert(l.GetInt(tx.ctx.script_hash,field.index)==field.value,'Completion score readback failed.')
 end
 HeistOps.validate_classic_score(tx)
end
function HeistOps.restore_classic_score(tx,same)
 if not tx.score then return true end
 local l=assert(binding('ScriptLocal'));local all=true
 if not same then
  if same==nil and not HeistOps.controller_ended(tx.ctx) then
   for _,field in ipairs(tx.score.fields) do if field.attempted then return false end end
  end
  return true -- Never replay locals into a replaced controller or foreign host.
 end
 for _,team in ipairs(tx.score.teams) do
  if not team.committed then
   local ok,stage=pcall(l.GetInt,tx.ctx.script_hash,tx.ctx.profile.stage+team.team)
   -- Normal objective advancement consumes the award. Preserve that progress
   -- through processed/celebration/result handling; a temporary patch restore
   -- must not erase the score the later winner calculation will read.
   if ok and team.stage<17 and (stage==17 or stage==99999) then team.committed=true end
  end
 end
 for i=#tx.score.fields,1,-1 do
  local field=tx.score.fields[i];local team=tx.score.teams[field.team+1]
  if field.attempted and not team.committed then
   local ok=pcall(function()
    assert(HeistOps.same(tx.ctx),'Controller changed during completion score cleanup.')
    local stage=l.GetInt(tx.ctx.script_hash,tx.ctx.profile.stage+field.team)
    assert(type(stage)=='number' and stage%1==0,'Objective stage is unreadable during score cleanup.')
    if stage~=team.stage then return end -- GTA advanced/reused this objective's score.
    local current=l.GetInt(tx.ctx.script_hash,field.index)
    assert(type(current)=='number' and current%1==0,'Completion score is unreadable during cleanup.')
    if current==field.value then
     l.SetInt(tx.ctx.script_hash,field.index,field.original)
     assert(l.GetInt(tx.ctx.script_hash,field.index)==field.original,'Completion score cleanup readback failed.')
    end
   end)
   all=all and ok
  end
 end
 return all
end

function HeistOps.classic_preflight(ctx,preview)
 assert(ctx and ctx.script=='fm_mission_controller','Classic completion requires the verified controller.')
 local eligible,why=HeistOps.classic_party(ctx);assert(eligible,why)
 -- A single locally accepted controller does not establish that the
 -- Pacific Standard finale can pass GTA's later four-player crew check.
 -- Refuse an objective request which would otherwise end as a failed job.
 if ctx.family=='apartment' then
  local minimum=ctx.heist=='fleeca' and 2 or 4
  if #ctx.participants<minimum then
   error(('Apartment %s requires %d real finale participants for a verified finish. Bonus awards are separate from mission settlement.'):format(tostring(ctx.heist),minimum))
  end
 end
 if preview==false then
  HeistOps.guard(ctx.script_hash,'classic_local_result')
  if ctx.family=='casino' then
   HeistOps.guard(ctx.script_hash,'reward_event')
   HeistOps.guard(ctx.script_hash,'classic_reward_owner')
  end
 end
 local m,l=assert(binding('Memory')),assert(binding('ScriptLocal'))
 assert(type(m.WriteUByte)=='function' and type(l.SetInt)=='function','Completion write services are unavailable.')
 local tx={ctx=ctx,fields={},preview=preview~=false,
  addresses=preview==false and HeistOps.guard(ctx.script_hash,ctx.script) or HeistOps.read_guard(ctx,ctx.script)}
 local p=ctx.profile;local teams=l.GetInt(ctx.script_hash,p.teams)
 assert(type(teams)=='number' and teams%1==0 and teams>=1 and teams<=4,'Controller team count is invalid.')
 local veto=l.GetInt(ctx.script_hash,p.root+3)
 assert(type(veto)=='number' and veto%1==0,'Controller crew result is unreadable.')
 assert(not active_slot(veto,31),'The controller already recorded a crew or subrole admission failure; restart with the required crew.')
 HeistOps.prepare_classic_admission(tx,teams)
 local mask=0
 for team=0,teams-1 do
  local stage=l.GetInt(ctx.script_hash,p.stage+team)
  assert(type(stage)=='number' and stage%1==0 and stage>=0 and (stage<=17 or stage==99999),'Objective stage is invalid.')
  assert(l.GetInt(ctx.script_hash,p.request+team)==-1,'A scripted objective jump is already queued.')
  if stage<17 then tx.fields[#tx.fields+1]={index=p.request+team,original=-1,value=17};mask=mask+2^(17+team) end
 end
 assert(#tx.fields>0,'All team objectives are already complete.')
 HeistOps.prepare_classic_score(tx,teams)
 if p.trigger then
  local trigger=l.GetInt(ctx.script_hash,p.trigger)
  assert(type(trigger)=='number' and trigger%1==0,'Controller objective trigger is unreadable.')
  assert((trigger&mask)==0,'An objective trigger is already pending.')
  tx.fields[#tx.fields+1]={index=p.trigger,original=trigger,value=trigger|mask}
 end
 -- Settlement percentages and optional maximum-payout plans are not
 -- prerequisites of the objective success callbacks. Keep any readable share
 -- evidence for result observation; exact controller identity already proves
 -- the current crew when those optional inputs are unavailable.
 local share_ok,party=pcall(HeistOps.read_finish_party,ctx.family)
 if not share_ok or not party then
  party={identity=ctx.controller_identity,character_slot=ctx.character_slot,
   member_map=ctx.member_map,owner_rid=ctx.owner_rid,participant_rids=ctx.participant_rids,
   share_evidence='CONTROLLER_CREW_ONLY'}
 end
 assert(party.identity==ctx.controller_identity,'The settlement crew changed during completion preparation.')
 tx.party=party
 if ctx.family=='casino' then tx.loot=HeistOps.casino_finish_take(ctx,preview~=false) end
 tx.local_before=HeistOps.classic_local_result(ctx)
 assert(not tx.local_before.entered and not tx.local_before.success,'The local finale result has already started; wait for a new finale.')
 tx.balance=HeistOps.balance_snapshot()
 assert(HeistOps.same(ctx),'Controller identity changed during completion preparation.')
 return tx
end
-- Experimental solo Enhanced Cayo route. State/score operands are
-- corroborated against the collected bytecode. The same one-team host-broadcast
-- result route accepts an exact 2-4 player crew; active cut rewriting stays solo.
function HeistOps.cayo_preflight(ctx)
 assert(type(ctx.participants)=='table' and #ctx.participants>=1 and #ctx.participants<=4,
  'The Cayo controller crew is unavailable.')
 local seen={}
 for _,row in ipairs(ctx.participants) do
  assert(type(row.player)=='number' and row.player%1==0 and row.player>=0 and row.player<=31 and not seen[row.player],
   'The Cayo controller crew is ambiguous.')
  seen[row.player]=true
 end
 assert(seen[ctx.host_player],'The Cayo controller host is missing from the crew.')
 local l=assert(binding('ScriptLocal'))
 assert(l.GetInt(ctx.script_hash,58003)==1,'This Cayo completion route requires one mission team.')
 assert(l.GetInt(ctx.script_hash,58089)==-1,'An objective jump is already pending.')
 local flags=l.GetInt(ctx.script_hash,56505)
 assert(type(flags)=='number' and flags%1==0 and active_slot(flags,14),'Wait until real Cayo objectives are active.')
 local stage=l.GetInt(ctx.script_hash,66052)
 assert(type(stage)=='number' and stage%1==0 and stage>=0 and stage<17,'Cayo objectives are already terminal or unreadable.')
 local score=l.GetInt(ctx.script_hash,58281)
 assert(type(score)=='number' and score%1==0 and score>=0 and score<=100000,'Cayo score is unreadable.')
 return score
end
function HeistOps.balance_snapshot()
 local ok,value=pcall(function()
  local economy=context_ref and context_ref.CScript and context_ref.CScript.Economy
  local slot=economy and economy.CurrentSlot and economy.CurrentSlot()
  assert(slot==0 or slot==1)
  local n=assert(binding('Natives'))
  local bank=n.InvokeInt(0x76EF28DA05EA395A)
  local wallet=n.InvokeInt(0xA40F9C2623F6A8B5,slot)
  assert(type(bank)=='number' and bank>=0 and type(wallet)=='number' and wallet>=0)
  return {slot=slot,total=bank+wallet}
 end)
 return ok and value or nil
end
function HeistOps.earning_anchor(ctx)
 local economy=context_ref and context_ref.CScript and context_ref.CScript.Economy
 if not economy or not economy.BeginEarningSettlement then return nil end
 -- Called only by scheduler/action work. Align the observed balance with the
 -- journal baseline before opening a lease; renderer status access stays cached.
 if economy.Refresh then economy.Refresh() end
 return economy.BeginEarningSettlement('Heists',ctx.controller_identity)
end
function HeistOps.track_cayo_income()
 local now=runtime_time_ms()
 if now<(HeistOps.next_income_poll or 0) then return end
 HeistOps.next_income_poll=now+5000
 local economy=context_ref and context_ref.CScript and context_ref.CScript.Economy
 if not economy or not economy.BeginEarningSettlement then return end
 local previous=HeistOps.cayo_observation
 if previous and not previous.passive then return end
 local ok,tx=pcall(function()
  local g=assert(global_service())
  local amount,flag=g.GetInt(2686124+3513+79),g.GetInt(1980496+1)
  -- A changed result belongs to the retained lease. Never refresh the baseline
  -- over its payment, including the last active-controller tick.
  if previous and (amount~=previous.before_result or flag~=previous.before_result_flag) then return end
  local observed_balance=HeistOps.balance_snapshot()
  -- Credit can precede the result globals. Keep its original baseline until the
  -- result arrives or the lease expires; unrelated credit stays unclassified.
  if previous and observed_balance and previous.balance
   and observed_balance.total>previous.balance.total then return end
  local ctx=HeistOps.controller('cayo');if not ctx then return end
  -- This source profile is established for the local solo host. Other heist
  -- families/participants stay unknown until their result semantics are proven.
  if #ctx.participants~=1 or ctx.participants[1].player~=ctx.host_player then return end
  if not previous or previous.ctx.controller_identity~=ctx.controller_identity then
   HeistOps.guard(ctx.script_hash,ctx.script)
  end
  local anchor=HeistOps.earning_anchor(ctx);if not anchor then return end
  local balance=HeistOps.balance_snapshot()
  if not balance or balance.slot~=anchor.slot or balance.total~=anchor.balance_before then return end
  return {ctx=ctx,generation=cut_generation,started=now,next_poll=0,passive=true,
   earning_anchor=anchor,balance=balance,before_result=amount,before_result_flag=flag}
 end)
 if ok and tx then HeistOps.cayo_observation=tx end
end
function HeistOps.restore_cayo_score(tx,same)
 local score=tx.cayo_score
 if not score or not score.attempted or score.committed then return true end
 if same==false then return true end
 if same~=true then return HeistOps.controller_ended(tx.ctx)==true end
 local ok,clean=pcall(function()
  local l=assert(binding('ScriptLocal'));local ctx=tx.ctx
  local root=l.GetInt(ctx.script_hash,56504)
  local flags=l.GetInt(ctx.script_hash,56505)
  local request=l.GetInt(ctx.script_hash,58089)
  local stage=l.GetInt(ctx.script_hash,66052)
  assert(type(root)=='number' and root%1==0 and type(flags)=='number' and flags%1==0
   and type(request)=='number' and request%1==0 and type(stage)=='number' and stage%1==0,
   'Cayo callback state unreadable during cleanup.')
  if root~=6 or active_slot(flags,16) or request==-1 and stage>=17 then
   score.committed=true;return true
  end
  local current=l.GetInt(ctx.script_hash,58281)
  assert(type(current)=='number' and current%1==0,'Cayo score cleanup read unavailable.')
  if current==score.value then
   assert(HeistOps.same(ctx)==true,'Cayo controller changed during score cleanup.')
   assert(l.GetInt(ctx.script_hash,58281)==current,'Cayo score changed during cleanup.')
   local accepted=l.SetInt(ctx.script_hash,58281,score.original)
   assert(accepted~=false,'Cayo score cleanup rejected.')
  end
  return l.GetInt(ctx.script_hash,58281)==score.original
 end)
 return ok and clean==true
end
function HeistOps.finish_cayo(ctx)
 if HeistOps.pending then return false,'A completion request is already pending.' end
 if HeistOps.cayo_observation and not HeistOps.cayo_observation.passive then return false,'The previous Cayo result is still being observed.' end
 local l,m=assert(binding('ScriptLocal')),assert(binding('Memory'))
 local tx,accepted
 local ok,err=pcall(function()
  local addresses=HeistOps.guard(ctx.script_hash,ctx.script)
  local score=HeistOps.cayo_preflight(ctx)
  local payout=context_ref and context_ref.CScript and context_ref.CScript.HeistPayout
  local auto_ok,auto=pcall(function()return payout and payout.AutomaticStatus and payout.AutomaticStatus()end)
  local expected
  if auto_ok and auto and auto.enabled and auto.state=='APPLIED' and auto.family=='cayo'
   and auto.scope=='ACTIVE_SOLO' and auto.plan and auto.plan.cuts and auto.plan.players then
   local cut=auto.plan.cuts[1]
   if assert(global_service()).GetInt(2692926)==cut and auto.plan.players[1] then expected=auto.plan.players[1].transaction_amount end
  end
  local g=assert(global_service())
  tx={ctx=ctx,generation=cut_generation,value=math.max(score,50),started=runtime_time_ms(),
   balance=HeistOps.balance_snapshot(),before_result=g.GetInt(2686124+3513+79),expected=expected,
   before_result_flag=g.GetInt(1980496+1),next_poll=0,earning_anchor=HeistOps.earning_anchor(ctx),
   cayo_score={original=score,value=math.max(score,50)},addresses=addresses,
   fields={{index=58089,original=-1,value=17}},code_sites={
    {signature=1,offset=88,original=0x72,value=0x71},
    {signature=1,offset=89,original=0x71,value=0x72}}}
  local signature=HeistOps.signatures[ctx.script][1]
  local bytes=signature.decoded or HeistOps.bytes(signature.bytes)
  assert(90<=math.min(#bytes,16384-signature.pc%16384),'Cayo callback operands cross an unverified code page.')
  HeistOps.prepare_success_branch(tx)
  tx.submitting=true;HeistOps.pending=tx
  HeistOps.select_success_branch(tx)
  assert(l.GetInt(ctx.script_hash,58281)==score,'Cayo score changed before submission.')
  success_branch_fence(tx,tx.success_branch.original|(1<<21));submission_owned(tx)
  tx.cayo_score.attempted=true
  l.SetInt(ctx.script_hash,58281,tx.value)
  assert(l.GetInt(ctx.script_hash,58281)==tx.value,'Cayo score readback failed.')
  for _,site in ipairs(tx.code_sites) do
   assert(HeistOps.same(ctx)==true,'Cayo controller changed before callback patch.')
   local at=assert(tx.addresses[site.signature])+site.offset
   assert(m.ReadUByte(at)==site.original,'Cayo callback source changed.')
   submission_owned(tx);site.attempted=true
   m.WriteUByte(at,site.value)
   assert(m.ReadUByte(at)==site.value,'Cayo callback patch readback failed.')
  end
  assert(l.GetInt(ctx.script_hash,58089)==-1,'A Cayo objective request is already pending.')
  assert(l.GetInt(ctx.script_hash,58281)==tx.value,'Cayo score changed before objective request.')
  success_branch_fence(tx,tx.success_branch.original|(1<<21));submission_owned(tx)
  tx.fields[1].attempted=true
  l.SetInt(ctx.script_hash,58089,17)
  local request,stage=l.GetInt(ctx.script_hash,58089),l.GetInt(ctx.script_hash,66052)
  assert(request==17 or request==-1 and type(stage)=='number' and stage>=17,'Cayo objective request was not observed.')
  accepted=true
 end)
 if tx then tx.submitting=false end
 if not ok then
  if tx and HeistOps.pending==tx then HeistOps.restore('Cayo objective submission failed; restoring owned changes.',true) end
  return false,tostring(err)
 end
 if not accepted then return false,'Cayo objective request was not submitted.' end
 HeistOps.cayo_observation=tx
 HeistOps.finish_event={ready=false,family='cayo',state='SUBMITTED',payment_verified=false,
  reason='Objective success requested; waiting for the controller result and reward settlement.',live_status='LIVE_RETEST_REQUIRED'}
 pcall(log,'Info',('Cayo objective request stage=17 score=%s predicted=%s; resultStateWritten=false paymentVerified=false')
  :format(tx.value,tostring(tx.expected)))
 return true,HeistOps.finish_event.reason
end
function HeistOps.tick_cayo_finish(tx)
 local now=runtime_time_ms()
 local same=HeistOps.same(tx.ctx)
 local function terminal(state,reason)
  local clean=HeistOps.restore(reason,true)
  HeistOps.finish_event={ready=false,family='cayo',state=clean and state or 'RESTORE_PENDING',reason=reason,payment_verified=false}
 end
 if same~=true then
  if same==false or HeistOps.controller_ended(tx.ctx) or now-tx.started>120000 then
   terminal('OUTCOME_UNVERIFIED','Cayo controller changed before completion processing was confirmed.')
  end
  return
 end
 local ok,result=pcall(function()
  local l=assert(binding('ScriptLocal'));local h=tx.ctx.script_hash
  local row={request=l.GetInt(h,58089),stage=l.GetInt(h,66052),flags=l.GetInt(h,56505),veto=l.GetInt(h,56507),requirements=l.GetInt(h,56508)}
  for _,key in ipairs({'request','stage','flags','veto','requirements'}) do
   local v=row[key];assert(type(v)=='number' and v%1==0,'Cayo result observation is unreadable.')
  end
  assert(HeistOps.same(tx.ctx)==true,'Cayo controller changed during result observation.')
  return row
 end)
 if not ok then return end
 local failed=active_slot(result.veto,26) or active_slot(result.veto,31) or active_slot(result.requirements,4)
 for bit=20,23 do failed=failed or active_slot(result.flags,bit) end
 if failed then terminal('MISSION_FAILED','The Cayo controller recorded a crew, subrole or team failure. No completion or payout is verified.');return end
 if result.request==-1 and result.stage>=17 then
  tx.acknowledged=true;tx.cayo_score.committed=true;tx.success_branch.committed=true
 end
 if active_slot(result.flags,16) then
  tx.cayo_score.committed=true;tx.success_branch.committed=true
  terminal('AWAITING_RESULT','Cayo objectives processed; the game still owns result readiness, rewards and return.')
 elseif not tx.acknowledged and now-tx.started>15000 then
  terminal('REQUEST_TIMEOUT','Cayo objective request was not consumed before its timeout.')
 elseif now-tx.started>120000 then
  terminal('OUTCOME_UNVERIFIED','Cayo objectives were acknowledged but result processing was not confirmed before timeout.')
 elseif tx.acknowledged then
  HeistOps.finish_event={ready=false,family='cayo',state='AWAITING_RESULT',payment_verified=false,
   reason='Cayo objectives acknowledged; waiting for the real controller crew and result checks.'}
 end
end

function HeistOps.observe_cayo_result()
 local tx=HeistOps.cayo_observation;if not tx then return end
 local economy=context_ref and context_ref.CScript and context_ref.CScript.Economy
 local lease_current=tx.earning_anchor and economy and economy.IsEarningSettlementCurrent
  and economy.IsEarningSettlementCurrent(tx.earning_anchor)
 if (tx.earning_anchor and not lease_current) or (tx.generation~=cut_generation and not lease_current)
  or local_player_id()~=tx.ctx.host_player then
  HeistOps.cayo_observation=nil
  HeistOps.finish_event={ready=false,family='cayo',state='PAYMENT_UNVERIFIED',reason='Session or player changed before payment could be checked.',payment_verified=false}
  pcall(log,'Info',HeistOps.finish_event.reason);return
 end
 local now=runtime_time_ms();if now<tx.next_poll then return end;tx.next_poll=now+500
 local elapsed=now-tx.started
 local balance=HeistOps.balance_snapshot()
 local ok,amount,result_flag,mission=pcall(function()
  local g=assert(global_service());return g.GetInt(2686124+3513+79),g.GetInt(1980496+1),g.GetInt(FMMC_PROFILE.mission_hash_index)
 end)
 if ok and type(mission)=='number' and mission~=0 and mission~=tx.ctx.mission then
  HeistOps.cayo_observation=nil
  HeistOps.finish_event={ready=false,family='cayo',state='PAYMENT_UNVERIFIED',
   reason='Another mission replaced the Cayo context before settlement correlation.',payment_verified=false}
  return
 end
 local delta=balance and tx.balance and balance.slot==tx.balance.slot and balance.total-tx.balance.total or nil
 local result_changed=ok and (amount~=tx.before_result or result_flag~=tx.before_result_flag)
 local signature=table.concat({tostring(amount),tostring(result_flag),tostring(delta)},':')
 if signature~=tx.last_signature then
  tx.last_signature=signature
  pcall(log,'Info',('Cayo settlement observation result=%s resultFlag=%s balanceDelta=%s predicted=%s; paymentVerified=false')
   :format(tostring(amount),tostring(result_flag),tostring(delta),tostring(tx.expected)))
 end
 if result_changed and result_flag==1 and type(amount)=='number' and amount>0 and delta and math.abs(delta-amount)<=1 then
  local count=thread_count(tx.ctx.script_hash)
  if count~=0 then
   local active=count==1 and HeistOps.controller('cayo',true)
   if not active or active.thread_id~=tx.ctx.thread_id or active.pointer~=tx.ctx.pointer then
    HeistOps.cayo_observation=nil
    HeistOps.finish_event={ready=false,family='cayo',state='PAYMENT_UNVERIFIED',
     reason='The Cayo controller instance changed before settlement correlation.',payment_verified=false}
    return
   end
  end
  if tx.earning_anchor and economy and economy.ConfirmEarningSettlement then
   tx.earning_attributed=economy.ConfirmEarningSettlement(tx.earning_anchor,amount,tx.balance.total,balance.total,
    'Cayo Perico: fresh result and matching observed balance increase')==true
  end
  HeistOps.finish_event={ready=false,family='cayo',state='PAYMENT_OBSERVED',reason=('Cayo result GTA$%d and matching balance increase observed; persistence not yet verified.'):format(amount),payment_verified=false}
  if tx.expected and math.abs(amount-tx.expected)>1 then
   HeistOps.finish_event.state='PAYMENT_MISMATCH'
   HeistOps.finish_event.reason=('Observed GTA$%d; predicted GTA$%d. Maximum payout was not confirmed.'):format(amount,tx.expected)
  end
 elseif elapsed>120000 then
  HeistOps.finish_event={ready=false,family='cayo',state='PAYMENT_UNVERIFIED',reason='No matching Cayo result and balance increase confirmed. Check the result screen.',payment_verified=false}
 else return end
 pcall(log,'Info',HeistOps.finish_event.reason)
 HeistOps.last_cayo_observation=tx;HeistOps.cayo_observation=nil
end

function HeistOps.finish(family)
 if next(cut_pending)~=nil then return false,'A cut publication is still pending cleanup; retry after its readback or restoration completes.' end
 if HeistOps.active_cut and HeistOps.active_cut.verified~=true then
  pcall(HeistOps.restore_active_cut)
  if HeistOps.active_cut then
   return false,'An active percentage write is still pending cleanup; retry after its readback or restoration completes.'
  end
 end
 if HeistOps.classic_observation then return false,"The previous finale result is still being observed." end
 if HeistOps.cayo_observation and not HeistOps.cayo_observation.passive then return false,"The previous Cayo result is still being observed." end
 if HeistOps.pending then return false,"A completion request is already pending." end
 local ctx,reason=HeistOps.controller(family);if not ctx then return false,reason end
 if family=="cayo" then return HeistOps.finish_cayo(ctx) end
 local prepared,tx=pcall(HeistOps.classic_preflight,ctx,false)
 if not prepared then return false,tostring(tx) end
 local m,l=binding("Memory"),binding("ScriptLocal")
 -- Preserve the four previously validated callback operands. func_962's
 -- first Boolean gates forced losses; false,true selects the existing
 -- completion consumers. GTA still owns winner, result and payout state.
 tx.code_sites={
  {signature=1,offset=ctx.profile.patch_offset,original=0x72,value=0x71},
  {signature=1,offset=ctx.profile.patch_offset+1,original=0x71,value=0x72},
  {signature=ctx.profile.primary_signature,offset=ctx.profile.primary_patch_offset,original=0x72,value=0x71},
  {signature=ctx.profile.primary_signature,offset=ctx.profile.primary_patch_offset+1,original=0x71,value=0x72},
 }
 tx.started=runtime_time_ms()
 local ok,err=pcall(function()
  HeistOps.add_result_initializer(tx)
  for _,site in ipairs(tx.code_sites) do
   local sig=HeistOps.signatures[ctx.script][site.signature]
   local bytes=sig.decoded or HeistOps.bytes(sig.bytes)
   assert(site.offset>=0 and site.offset<math.min(#bytes,16384-sig.pc%16384),
    "Completion patch is outside the first verified code-page fragment.")
  end
  -- Required Casino input validation finishes BEFORE even admission writes.
  if tx.loot then
   local fresh=HeistOps.casino_finish_take(ctx,false)
   assert(fresh.original==tx.loot.original and fresh.value==tx.loot.value,'Casino take changed before completion.')
  end
  assert(HeistOps.same(ctx),'Controller changed before completion submission.')
  HeistOps.prepare_success_branch(tx)
  tx.submitting=true
  HeistOps.pending=tx
  HeistOps.select_success_branch(tx)
  HeistOps.apply_classic_admission(tx)
  submission_owned(tx)
  HeistOps.apply_classic_score(tx)
  submission_owned(tx)
  if tx.loot then
   assert(HeistOps.same(ctx) and l.GetInt(ctx.script_hash,tx.loot.index)==tx.loot.original,'Casino take changed before write.')
   tx.loot.attempted=true
   submission_owned(tx)
   l.SetInt(ctx.script_hash,tx.loot.index,tx.loot.value)
   assert(l.GetInt(ctx.script_hash,tx.loot.index)==tx.loot.value,'Casino completion take readback failed.')
  end
  HeistOps.validate_classic_score(tx)
  for _,site in ipairs(tx.code_sites) do
   assert(HeistOps.same(ctx));local at=tx.addresses[site.signature]+site.offset
   assert(m.ReadUByte(at)==site.original);site.attempted=true
   submission_owned(tx)
   m.WriteUByte(at,site.value);assert(m.ReadUByte(at)==site.value)
  end
  -- Callback patching can yield to the host. Bind the score/result inputs
  -- again immediately before publishing the first objective request.
  HeistOps.validate_classic_score(tx)
  for _,f in ipairs(tx.fields) do
   assert(HeistOps.same(ctx));assert(l.GetInt(ctx.script_hash,f.index)==f.original)
   success_branch_fence(tx,tx.success_branch.original|(1<<21))
   submission_owned(tx)
   f.attempted=true;l.SetInt(ctx.script_hash,f.index,f.value)
   assert(l.GetInt(ctx.script_hash,f.index)==f.value)
  end
  assert(HeistOps.same(ctx))
 end)
 tx.submitting=false
 if not ok then if HeistOps.pending then HeistOps.restore("Completion submission failed; restoring owned changes.") end;return false,tostring(err) end
 HeistOps.finish_event={ready=false,state="SUBMITTED",family=ctx.family,heist=ctx.heist,
  reason="Source-defined team scores and objective success requests submitted. The game still performs result and payout processing."..(tx.loot and " Casino completion take prepared." or ""),live_status="LIVE_RETEST_REQUIRED",payment_verified=false}
 HeistOps.classic_receipt={ctx=ctx}
 HeistOps.remember_classic_settlement()
 return true,HeistOps.finish_event.reason
end
function HeistOps.classic_failure(ctx)
 if not ctx or ctx.script=="fm_mission_controller_2020" then return nil end
 local ok,reason=pcall(function()
  local l=assert(binding("ScriptLocal"))
  local flags=l.GetInt(ctx.script_hash,ctx.profile.root+1)
  if type(flags)~="number" or flags%1~=0 then return nil end
  local veto=l.GetInt(ctx.script_hash,ctx.profile.root+3)
  if type(veto)=='number' and veto%1==0 and active_slot(veto,31) then
   return 'The controller recorded a crew or subrole admission veto.'
  end
  for bit=20,23 do
   if active_slot(flags,bit) then
    local team=bit-20
    local failure=l.GetInt(ctx.script_hash,ctx.profile.root+2692+team)
    local detail=l.GetInt(ctx.script_hash,ctx.profile.root+1690+team)
    return "Team failure bit "..bit.." is set; reason="..tostring(failure).." detail="..tostring(detail).."."
   end
  end
 end)
 return ok and reason or nil
end
function HeistOps.classic_local_result(ctx)
 assert(ctx and ctx.script=='fm_mission_controller' and HeistOps.same(ctx),'Local result controller identity changed.')
 HeistOps.read_guard(ctx,'classic_local_result')
 local l=assert(binding('ScriptLocal'))
 local function read(index,lo,hi)
  local value=l.GetInt(ctx.script_hash,index)
  assert(type(value)=='number' and value%1==0 and value>=lo and value<=hi,'Local finale result is unreadable.')
  return value
 end
 local entered,success=read(15618,-2147483648,4294967295),read(15619,-2147483648,4294967295)
 local result={entered=active_slot(entered,0),success=active_slot(success,26),amount=read(1690,0,2147483647),
  player=read(19130,-1,31),row_amount=read(19131,0,2147483647),row_pass=read(19137,0,1)}
 assert(HeistOps.same(ctx),'Controller changed during local result read.')
 return result
end
-- The late local result row corroborates func_2089's final rounded amount.
-- Neither that row nor a balance increase is a backend acceptance receipt.
function HeistOps.observe_classic_result()
 local tx=HeistOps.classic_observation;if not tx then return end
 local now=runtime_time_ms()
 local function outcome(state,reason,done)
  HeistOps.finish_event={ready=false,family=tx.ctx.family,heist=tx.ctx.heist,state=state,reason=reason,
   local_success=tx.local_success==true,local_amount=tx.local_amount,balance_delta=tx.balance_delta,
   share_evidence=tx.party and tx.party.share_evidence,payment_verified=false,peer_payment_verified=false}
  HeistOps.remember_classic_settlement()
  if done then HeistOps.classic_observation=nil;HeistOps.failed_until=now+30000 end
  log_detection('InstantFinish',tx.ctx.family,false,reason)
 end
 -- These identity checks precede every static-local/balance read. Never read
 -- an old allocation merely because a new script has the same name.
 local economy=context_ref and context_ref.CScript and context_ref.CScript.Economy
 local slot_ok,slot=pcall(function() return economy and economy.CurrentSlot and economy.CurrentSlot() end)
 local ids,members=HeistOps.member_rids(tx.ctx.participants)
 local same=HeistOps.same(tx.ctx)
 local identity_ok=slot_ok and ids and slot==tx.party.character_slot and members[tx.ctx.host_player]==tx.party.owner_rid
 if identity_ok then
  for pid,rid in pairs(tx.party.member_map) do if members[pid]~=rid then identity_ok=false;break end end
 end
 if same~=true or not identity_ok then
  outcome(tx.local_success and 'LOCAL_SUCCESS_OBSERVED' or 'OUTCOME_UNVERIFIED',
   tx.local_success and 'Local passing result observed; the controller or crew then changed. Payment remains unverified.'
    or 'Controller or crew changed before a local passing result was observed. Check the game result.',true)
  return
 end
 local readable,result=pcall(HeistOps.classic_local_result,tx.ctx)
 if readable then
  local fresh_row=result.player~=tx.local_before.player or result.row_amount~=tx.local_before.row_amount or result.row_pass~=tx.local_before.row_pass
  if result.entered and result.success and not tx.local_before.success then
   tx.local_success=true
   if fresh_row and result.player==tx.ctx.host_player and result.row_pass==1 and result.row_amount==result.amount and result.amount%10==0 then
    tx.local_amount=result.amount
   end
  elseif result.entered and fresh_row and result.player==tx.ctx.host_player and result.row_pass==0 then
   outcome('LOCAL_FAILURE_OBSERVED','The local game result is a failure. No successful payout is verified.',true)
   return
  end
  if tx.local_success then
   local balance=HeistOps.balance_snapshot()
   if balance and tx.balance and balance.slot==tx.balance.slot and balance.slot==slot then tx.balance_delta=balance.total-tx.balance.total end
   if tx.local_amount and tx.local_amount>0 and tx.balance_delta==tx.local_amount then
    outcome('LOCAL_SUCCESS_BALANCE_OBSERVED',('Local passing result GTA$%d and the same balance increase observed; backend acceptance and peer payments remain unverified.'):format(tx.local_amount),true)
    return
   end
   outcome('LOCAL_SUCCESS_OBSERVED',tx.local_amount and ('Local passing result GTA$%d observed; waiting for local balance evidence.'):format(tx.local_amount)
    or 'The local game pass branch was observed; the final reward amount is still unverified.',false)
  end
 end
 if now<tx.observation_started or now>=tx.observation_deadline then
  outcome(tx.local_success and 'LOCAL_SUCCESS_OBSERVED' or 'OUTCOME_UNVERIFIED',tx.local_success
   and 'Local passing result observed; no matching balance increase was confirmed before the observation timeout.'
    or 'Objectives were processed, but a local passing result was not observed before the timeout. Check the game result.',true)
 end
end
-- func_871 can mark teams ended before func_815 rechecks crew/role minima.
-- Result bit16 is published only AFTER func_834/830/815/811 have run.
-- func_13207 distinguishes ended bits9..12 from failure bits20..23.
function HeistOps.classic_result_snapshot(ctx)
 if not ctx or ctx.script~='fm_mission_controller' then return nil end
 local ok,result=pcall(function()
  local l=assert(binding('ScriptLocal'));local p=ctx.profile
  local flags=l.GetInt(ctx.script_hash,p.root+1)
  local teams=l.GetInt(ctx.script_hash,p.teams)
  assert(type(flags)=='number' and flags%1==0 and type(teams)=='number' and teams%1==0 and teams>=1 and teams<=4)
  local result={flags=flags,teams=teams,root=l.GetInt(ctx.script_hash,p.root),processed=active_slot(flags,16),ended=true,failed=false,stages={},requests={},reasons={},scores={},bonuses={},
   restart_flags=l.GetInt(ctx.script_hash,p.root+4)}
  for team=0,teams-1 do
   result.ended=result.ended and active_slot(flags,9+team)
   result.failed=result.failed or active_slot(flags,20+team)
   result.stages[#result.stages+1]=tostring(l.GetInt(ctx.script_hash,p.stage+team))
   result.requests[#result.requests+1]=tostring(l.GetInt(ctx.script_hash,p.request+team))
   result.reasons[#result.reasons+1]=tostring(l.GetInt(ctx.script_hash,p.root+2692+team))
   result.scores[#result.scores+1]=tostring(l.GetInt(ctx.script_hash,p.root+1232+1+team))
   result.bonuses[#result.bonuses+1]=tostring(l.GetInt(ctx.script_hash,18282+1+team))
  end
  return result
 end)
 return ok and result or nil
end
function HeistOps.trace_classic_result(tx,result)
 if not result then return end
 local line=('family=%s heist=%s mission=%s root=%s flags=%s processed=%s ended=%s failed=%s stages=%s requests=%s reasons=%s scores=%s bonuses=%s restartFlags=%s')
  :format(tostring(tx.ctx.family),tostring(tx.ctx.heist),tostring(tx.ctx.mission),tostring(result.root),tostring(result.flags),
   tostring(result.processed),tostring(result.ended),tostring(result.failed),table.concat(result.stages,','),table.concat(result.requests,','),table.concat(result.reasons,','),
   table.concat(result.scores or {},','),table.concat(result.bonuses or {},','),tostring(result.restart_flags))
 if tx.score and not tx.score_traced then
  local rows={}
  for _,team in ipairs(tx.score.teams) do
   rows[#rows+1]=('team%d:required=%s,base=%s,bonus=%s,delta=%s,prepared=%s'):format(team.team,tostring(team.required),tostring(team.score),tostring(team.bonus),tostring(team.delta),tostring(team.value))
  end
  tx.score_traced=true
  pcall(log,'Info','ClassicFinishScore family='..tostring(tx.ctx.family)..' mode='..tostring(tx.score.mode)..' '..table.concat(rows,';'))
 end
 if tx.admission and not tx.admission_traced then
  local changes={}
  for _,f in ipairs(tx.admission.fields) do
   if f.original~=f.value then changes[#changes+1]=f.kind..':'..f.index..'='..f.original..'>'..f.value end
  end
  tx.admission_traced=true
  pcall(log,'Info','ClassicFinishAdmission family='..tostring(tx.ctx.family)..' changes='..table.concat(changes,','))
 end
 if tx.result_trace~=line then tx.result_trace=line;pcall(log,'Info','ClassicFinishTrace '..line) end
end
local CLASSIC_FINISH_REQUEST_TIMEOUT_MS=15000
local CLASSIC_FINISH_RESULT_TIMEOUT_MS=120000
function HeistOps.tick_finish()
 if HeistOps.pending and HeistOps.pending.submitting then return end
 HeistOps.track_cayo_income()
 HeistOps.observe_cayo_result()
 HeistOps.observe_classic_result()
 local tx=HeistOps.pending;if not tx then return end
 if tx.ctx.family=='cayo' then HeistOps.tick_cayo_finish(tx);return end
 if not HeistOps.same(tx.ctx) then
  local restored=HeistOps.restore("Controller identity changed before a verified outcome.")
  HeistOps.finish_event={ready=false,family=tx.ctx.family,heist=tx.ctx.heist,
   state=restored and "OUTCOME_UNVERIFIED" or "RESTORE_PENDING",
   reason="Controller ended or host changed before the result could be classified. Check the game result; payment is unverified.",payment_verified=false}
  HeistOps.failed_until=runtime_time_ms()+30000
  log_detection('InstantFinish',tx.ctx.family,false,HeistOps.finish_event.reason)
  return
 end
 local result=HeistOps.classic_result_snapshot(tx.ctx)
 HeistOps.trace_classic_result(tx,result)
 local failed=HeistOps.classic_failure(tx.ctx)
 if failed then
  local restored=HeistOps.restore("Controller reported a team failure; restoring owned changes.")
  HeistOps.finish_event={ready=false,family=tx.ctx.family,heist=tx.ctx.heist,
   state=restored and "MISSION_FAILED" or "MISSION_FAILED_RESTORE_PENDING",
   reason="The controller reported failure ("..failed.."). No payout or completion is verified.",payment_verified=false}
  HeistOps.failed_until=runtime_time_ms()+30000
  log_detection("InstantFinish",tx.ctx.family,false,HeistOps.finish_event.reason)
  return
 end
 local l=binding("ScriptLocal")
 local done=true
 for _,field in ipairs(tx.fields) do
  if field.index~=tx.ctx.profile.trigger then
   local team=field.index-tx.ctx.profile.request
   local readable,requested,stage=pcall(function()
    return l.GetInt(tx.ctx.script_hash,field.index),l.GetInt(tx.ctx.script_hash,tx.ctx.profile.stage+team)
   end)
   if not readable or type(requested)~="number" or type(stage)~="number" then
    HeistOps.restore("Controller objective state became unreadable; restoring owned completion changes.")
    HeistOps.finish_event={ready=false,state='OUTCOME_UNVERIFIED',family=tx.ctx.family,reason='Controller objective state became unreadable; payment is unverified.',payment_verified=false}
    return
   end
   if requested~=-1 or not (stage==17 or stage==99999) then done=false end
  end
 end
 if done and not tx.acknowledged then
  tx.acknowledged=true
  if tx.loot then tx.loot.committed=true end
  HeistOps.finish_event={ready=false,state='AWAITING_RESULT',family=tx.ctx.family,heist=tx.ctx.heist,
   reason='Objective requests acknowledged. Waiting for the controller result and final crew checks; payment is unverified.',payment_verified=false}
  log_detection('InstantFinish',tx.ctx.family,false,HeistOps.finish_event.reason)
 end
 if result and result.processed and result.ended and not result.failed then
  if tx.loot then tx.loot.committed=true end
  local restored=HeistOps.restore('Controller processed every active team without a team failure; restoring owned changes.',true)
  -- Celebration success also depends on the engine's winner/score evaluation
  -- (func3713 -> func2077). Processed objectives alone do not prove that result.
  HeistOps.finish_event={ready=false,state=restored and 'AWAITING_LOCAL_RESULT' or 'CONTROLLER_PROCESSED_RESTORE_PENDING',family=tx.ctx.family,heist=tx.ctx.heist,
   reason='Objectives processed without a team failure; observing the actual local game result and payment evidence.',payment_verified=false}
  if restored then
   tx.observation_started=runtime_time_ms();tx.observation_deadline=tx.observation_started+90000
   HeistOps.classic_observation=tx
   HeistOps.observe_classic_result()
  end
  log_detection('InstantFinish',tx.ctx.family,false,HeistOps.finish_event.reason)
 elseif tx.acknowledged and runtime_time_ms()-tx.started>CLASSIC_FINISH_RESULT_TIMEOUT_MS then
  local restored=HeistOps.restore('Controller result was not confirmed within the observation timeout; restoring owned changes.')
  HeistOps.finish_event={ready=false,state=restored and 'OUTCOME_UNVERIFIED' or 'RESTORE_PENDING',family=tx.ctx.family,
   reason='Objective requests were acknowledged, but a passing controller result was not confirmed; payment is unverified.',payment_verified=false}
  HeistOps.failed_until=runtime_time_ms()+30000
  log_detection('InstantFinish',tx.ctx.family,false,HeistOps.finish_event.reason)
 elseif not tx.acknowledged and runtime_time_ms()-tx.started>CLASSIC_FINISH_REQUEST_TIMEOUT_MS then
  local restored=HeistOps.restore('Controller did not acknowledge every objective within the timeout; owned requests were restored.')
  HeistOps.finish_event={ready=false,state=restored and 'REQUEST_TIMEOUT' or 'RESTORE_PENDING',family=tx.ctx.family,
   reason='Controller did not acknowledge every objective request; payment is unverified.',payment_verified=false}
  HeistOps.failed_until=runtime_time_ms()+30000
  log_detection('InstantFinish',tx.ctx.family,false,HeistOps.finish_event.reason)
 end
end

function HeistOps.tick()
 pcall(HeistOps.tick_late_admission)
 HeistOps.tick_finish()
 HeistOps.ending_skip.Tick()
 HeistOps.remember_classic_settlement()
end

-- Read-only, current-launcher-bound no-loss projections. Never a server cap.
-- Source: current-bytecode corroborated FMC 2469/2474/2480/2507/2512/2514,
-- FMC2020 3383..3396. Every input is captured and reread before cut writes.
-- These observers are shared by the payment projection and the independent
-- completion-take reader. Every branch input is retained for revalidation.
function HeistOps.reward_reads(ctx)
 local g=assert(global_service())
 assert(type(g.GetFloat)=='function','Float tunable reads are unavailable.')
 assert(string.pack and string.unpack,'Float32 arithmetic is unavailable.')
 local r={observations={}}
 function r.f(n)return (string.unpack('f',string.pack('f',n)))end
 function r.rnd(n)return math.floor(r.f(n)+0.5)end
 function r.read(index,kind)
  local n
  if kind=='float' then n=g.GetFloat(index) else n=g.GetInt(index) end
  assert(type(n)=='number' and n==n and n~=math.huge and n~=-math.huge,'A payout input is unreadable (global '..index..').')
  if kind~='float' then assert(n%1==0,'An integer payout input is invalid.') end
  r.observations[#r.observations+1]={index=index,kind=kind or 'int',value=n}
  return n
 end
 function r.read_local(index)
  assert(type(ctx.script_hash)=='number' and type(ctx.controller_identity)=='string','Bound controller identity is missing.')
  local n=assert(binding('ScriptLocal')).GetInt(ctx.script_hash,index)
  assert(type(n)=='number' and n%1==0,'A controller payout input is unreadable.')
  r.observations[#r.observations+1]={index=index,kind='local_int',script_hash=ctx.script_hash,value=n}
  return n
 end
 function r.native_bool(hash,argument)
  local invoke=assert(binding('Natives')).InvokeBool
  local n
  if argument==nil then n=invoke(hash) else n=invoke(hash,argument) end
  assert(type(n)=='boolean','An event eligibility native is unreadable.')
  r.observations[#r.observations+1]={index=hash,kind='native_bool',argument=argument,value=n}
  return n
 end
 function r.player_name(pid)
  local hash=0x6D0DE6A7B5DA71F8
  local n=assert(binding('Natives')).InvokeString(hash,pid)
  assert(type(n)=='string' and #n>0,'The event owner name is unreadable.')
  r.observations[#r.observations+1]={index=hash,kind='native_string',argument=pid,value=n}
  return n
 end
 function r.ti(offset)return r.read(262145+offset)end
 function r.tf(offset)return r.read(262145+offset,'float')end
 return r
end

-- FMC func1700/2515..2522: an activity flag selects the event branch;
-- activity=false instead consults category switches and the actual owner.
-- A clear activity flag never falls through to the owner branch.
function HeistOps.event_factor(r,offset,category,owner)
 local factor=r.tf(offset)
 assert(factor>=0 and factor<=100,'The event reward factor is invalid.')
 if factor==1 then return 1 end
 if r.native_bool(0x05095437424397FA) then
  return active_slot(r.read(2673471),27) and factor or 1
 end
 local disabled=r.ti(38231)
 assert(disabled==0 or disabled==1,'The event category switch is invalid.')
 if disabled==1 then return 1 end
 disabled=r.ti(38232+1+category)
 assert(disabled==0 or disabled==1,'The event category switch is invalid.')
 if disabled==1 then return 1 end
 if type(owner)=='function' then owner=owner() end
 if type(owner)~='number' or owner%1~=0 or owner<0 or owner>31 then return 1 end
 return not active_slot(r.read(1913133+owner*322),category) and factor or 1
end

-- FMC func2523(false,false), including its special/local and spectator-owner
-- branches. Script hosting is not a substitute for this reward owner.
function HeistOps.classic_event_owner(ctx,r,pid)
 if ctx.route=='controller' then HeistOps.read_guard(ctx,'classic_reward_owner') end
 if r.read(1575068)~=0 then return pid end
 local owner=r.read(1926465)
 if owner==-1 then
  local name_hash=r.read(2686124+6540)
  if name_hash~=-1 then
   for candidate=0,31 do
    if r.native_bool(0xB8DFD30D6973E135,candidate) then
     local hash=assert(binding('Utils')).Joaat(r.player_name(candidate))
     assert(type(hash)=='number' and hash%1==0,'The event owner name hash is unreadable.')
     if hash%4294967296==name_hash%4294967296 then return candidate end
    end
   end
  end
 end
 local character=r.read(1574928)
 assert(character==0 or character==1,'The reward-owner character index is unavailable.')
 local spectator=r.read(1575077+1+character)==1
 if not spectator then spectator=r.read(1574922+1+character)==8 end
 if spectator or active_slot(r.read(1845348+pid*884+36+18),14) then
  local selected=-1
  for candidate=0,31 do
   local base=1845348+candidate*884
   if not active_slot(r.read(base+36+18),14) and r.read(base+198)~=8 and r.read(base+57)~=0 then selected=candidate end
  end
  if selected~=-1 then return selected end
 end
 return owner
end

function HeistOps.casino_take_inputs(ctx,r,diff)
 local pid=ctx.host_player or ctx.owner_pid
 assert(type(pid)=='number' and pid>=0 and pid<=31,'The local Casino player is unavailable.')
 local owner=r.read(1893081+pid*615)
 assert(owner>=0 and owner<=31,'The Casino planning boss is unavailable.')
 local base=1978125+1+owner*68+18
 local target=r.read(base+7)
 assert(target>=0 and target<=3,'Casino target is unknown.')
 local rewards={[0]=28436,[1]=28438,[2]=28437,[3]=28439}
 local primary=r.ti(rewards[target])
 assert(primary>=0 and primary<=2147483647,'Casino primary reward is invalid.')
 local event=HeistOps.event_factor(r,38208,8,owner)
 primary=r.rnd(r.f(primary)*r.f(event))
 if diff>0 then
  local difficulty=r.tf(28416+diff)
  assert(difficulty>=0 and difficulty<=100,'Casino difficulty factor is invalid.')
  primary=r.rnd(r.f(primary)*r.f(difficulty))
 end
 local daily,boxes=r.ti(28049),r.ti(28431)
 assert(daily>=0 and boxes>=0,'Casino optional loot allowance is invalid.')
 local amount=primary+daily*45+boxes*72
 assert(amount>=0 and amount<=2147483647,'Casino completion take is invalid.')
 return amount,base,owner
end

-- Core completion does not depend on optional fee/cut/target calculations.
-- Its take stays bound to the same live controller and the exact source inputs.
function HeistOps.read_finish_take_spec(family)
 if family~='casino' then return nil,'This finale has no separate completion take input.' end
 local ctx,why=HeistOps.controller(family);if not ctx then return nil,why end
 local ok,result=pcall(function()
  HeistOps.read_guard(ctx,ctx.script)
  HeistOps.read_guard(ctx,'reward_event')
  local r=HeistOps.reward_reads(ctx)
  local diff=r.read(4718592+3771);assert(diff>=0 and diff<=2,'Finale difficulty is unknown.')
  local amount=HeistOps.casino_take_inputs(ctx,r,diff)
  assert(HeistOps.same(ctx),'Controller changed during take calculation.')
  return {family=family,amount=amount,context=ctx,observations=r.observations,
   source='FMC func2469: rounded primary event, rounded difficulty, then optional loot'}
 end)
 if not ok then return nil,tostring(result) end
 return result
end
function HeistOps.validate_finish_take_spec(spec)
 if type(spec)~='table' or type(spec.context)~='table' or type(spec.observations)~='table' then return false,'Completion take evidence is missing.' end
 local current,why=HeistOps.read_finish_take_spec(spec.family);if not current then return false,why end
 if current.context.controller_identity~=spec.context.controller_identity or current.amount~=spec.amount
  or #current.observations~=#spec.observations then return false,'Completion take context changed.' end
 for i,expected in ipairs(spec.observations)do
  local actual=current.observations[i]
  if actual.index~=expected.index or actual.kind~=expected.kind or actual.argument~=expected.argument or actual.script_hash~=expected.script_hash or actual.value~=expected.value then
   return false,'Completion take inputs changed.'
  end
 end
 return true
end

local function read_payout_spec(family,finish_take)
 local ctx,why=read_payout_context(family,finish_take==true and family=='casino')
 if not ctx then return nil,why end
 local active_cayo=ctx.route=='controller' and family=='cayo'
 local active_apartment=ctx.route=='controller' and family=='apartment'
 local active_casino=ctx.route=='controller' and family=='casino'
 local active_doomsday=ctx.route=='controller' and family=='doomsday'
 if ctx.route~='launcher' and not active_cayo and not active_apartment and not active_casino and not active_doomsday then return nil,'Open the identified finale lobby for automatic take and fee calculation.' end
 local globals,err=global_service();if not globals then return nil,err end
 local ok,result=pcall(function()
  local r=HeistOps.reward_reads(ctx)
  local f,rnd,read,read_local,ti,tf=r.f,r.rnd,r.read,r.read_local,r.ti,r.tf
  local observations=r.observations
  local function positive(n)assert(n>0 and n<=2147483647,'The observed reward is invalid.');return n end
  local diff=read(4718592+3771);assert(diff>=0 and diff<=2,'Finale difficulty is unknown.')
  local identity=assert(cut_identity(family));local pid=identity.pid
  assert(pid>=0 and pid<=31,'Planning owner is unknown.')
  -- These wrappers surround every finale reward. Non-neutral/unclassified event
  -- amounts are refused instead of silently modelling only the base transaction.
  local reward_multiplier=tf(0)
  assert(reward_multiplier>0 and reward_multiplier<=100,'The observed global reward multiplier is invalid.')
  -- The global reward factor is observed and included below. Actual award
  -- eligibility is decided by Rockstar after the finale, not by these cuts.
  assert(tf(2403)==0 and tf(2407)==0,'An additional reward floor or ceiling is active.')
  local gross,pool,fees,cut_multiplier,membership_multiplier=0,0,{},1,1
  local conditional_reward_ceiling=1
  local function conditional(offset)
   local n=tf(offset)
   assert(n>=0 and n<=100,'The conditional payout multiplier is unreadable.')
   if n>1 then conditional_reward_ceiling=math.min(100,f(conditional_reward_ceiling*n)) end
   return n
  end
  local membership_ceiling=false
  local projection='NO_LOSS_SOURCE_CEILING'
  local source
  if family=='apartment' or family=='doomsday' then
   local rows={fleeca={25,9258,38200},prison={22,9259,38201},humane={23,9260,38202},
    series_a={24,9261,38203},pacific={21,9262,38204},act1={26,9263,38205},act2={27,9264,38206},act3={28,9265,38207}}
   local row=assert(rows[ctx.heist],'Individual finale reward mapping is unknown.')
   assert(read(4718592+139900)==row[1],'Finale identity and reward selector disagree.')
   local reward_event
   if family=='doomsday' then
    if active_doomsday then HeistOps.read_guard(ctx,'reward_event') end
    reward_event=HeistOps.event_factor(r,row[3],row[1]-21,function()return HeistOps.classic_event_owner(ctx,r,pid)end)
   else reward_event=conditional(row[3]) end
   gross=positive(ti(row[2]))
   if family=='apartment' then
    gross=rnd(f(gross)*f(tf(9328+diff)))
    gross=math.max(ti(8425),math.min(ti(8426),gross))
    -- func_2512 applies this branch after the percentage. Use its larger
    -- observed branch as a ceiling when packed replay history is unavailable.
    cut_multiplier=math.max(tf(8423),tf(8424))
    assert(cut_multiplier>0 and cut_multiplier<=100,'Apartment reward multiplier is invalid.')
    -- func_2509 gates the final func_2512 member reward through these two
    -- switches and local/host membership. Membership is not proven by the
    -- cut roster; use the eligible branch as a conservative payout ceiling.
    -- Keep the source's separate rounding step before func_2766's multiplier.
    local local_switch,host_switch=ti(8571),ti(8572)
    assert((local_switch==0 or local_switch==1) and (host_switch==0 or host_switch==1),'Apartment membership reward switches are invalid.')
    local member=tf(8574);assert(member>=0 and member<=100,'Apartment membership reward multiplier is invalid.')
    if (local_switch==1 or host_switch==1) and member>1 then
     membership_multiplier=member;membership_ceiling=true
    end
    if active_apartment then
     local participant=ctx.host_participant_index
     assert(type(participant)=='number' and participant%1==0 and participant>=0 and participant<=31,'Controller host participant index is unknown.')
     -- FMC func2456 uses plLocal3281=PLAYER_ID(), not the network participant index.
     local loss=read_local(32785+1+pid*294+153+2)
     local extra=read_local(20412+2685);assert(loss>=0 and extra>=0,'Apartment loss inputs are invalid.')
     local crew=0
     for i=0,3 do local n=read(4915256+i);assert(n>=0 and n<=4,'Apartment crew minimum is invalid.');crew=crew+n end
     pool=positive(f(f(gross)-f(f(loss)*f(crew))-f(extra)))
     projection='OBSERVED_ACTIVE_SOLO_TAKE'
    end
    source='FMC func2514 -> func2512; reward selector 21..25; loss-free projection'
   else
    -- func2514 rounds the eligible act event before func2507 applies its
    -- separate difficulty rounding and minimum/maximum clamps.
    gross=rnd(f(gross)*f(reward_event))
    if diff>0 then gross=rnd(f(gross)*f(tf(9330+diff))) end
    gross=math.max(ti(8461),math.min(ti(8462),gross))
    if active_doomsday then
     assert(#ctx.active_slots==1 and #ctx.participants==1 and ctx.host_player==pid and ctx.participants[1].player==pid,'Active Doomsday payout requires one exact local host.')
     -- func2456 indexes uLocal32785 by plLocal3281=PLAYER_ID(), not
     -- the network participant index (which can differ from the player ID).
     assert(read(1574975)==0 and read(1575068)==0,'A special or zero-reward settlement route is active.')
     assert(read(4718592+203791)~=3,'A special fixed-reward job route is active.')
     local mode=read(2658296+1+pid*468+124)
     assert(mode~=2 and mode~=7,'An Apartment reward route precedes the Doomsday payout branch.')
     local loss=read_local(32785+1+pid*294+153+2)
     local multiplier=read_local(20412+1777)
     assert(loss>=0 and multiplier>=1 and multiplier<=4,'Doomsday loss inputs are invalid.')
     pool=positive(f(f(gross)-f(loss*multiplier)))
     -- func2507 rounds AFTER multiplying the live percentage and replay
     -- factor8456/8457. Use the larger eligible factor as a safe ceiling;
     -- do not multiply both branches or round the percentage beforehand.
     local replay_a,replay_b=tf(8456),tf(8457)
     assert(replay_a>0 and replay_a<=100 and replay_b>0 and replay_b<=100,'Doomsday replay reward multipliers are invalid.')
     cut_multiplier=math.max(replay_a,replay_b)
     membership_ceiling=replay_a~=replay_b
     projection='OBSERVED_ACTIVE_SOLO_TAKE'
     source='FMC func2514 -> func2507; observed act event before difficulty/clamp, solo loss*multiplier, live percentage before replay ROUND'
    else
     conditional(8456);conditional(8457)
     source='FMC func2514 -> func2507; reward selector 26..28; loss-free projection'
    end
   end
   if not active_apartment and not active_doomsday then pool=positive(gross) end
  elseif family=='cayo' then
   local base=1982548+1+pid*53+5
   local target=read(base+9);assert(target>=0 and target<=5,'Primary target is unknown.')
   gross=positive(ti(29585+target))
   if diff>0 then gross=rnd(f(gross)*f(tf(29590+diff)))end
   -- func3384 counts all spawned secondary stacks for the anti-inflation ceiling.
   -- This is an upper bound, not a promise that the crew can carry the inventory.
   local function bits(value,width)
    local n=0;for bit=0,width-1 do if (value & (1<<bit))~=0 then n=n+1 end end;return n
   end
   local primary=gross
   for kind=0,4 do
    local count
    if kind==4 then count=bits(read(base+10+17),7)
    else count=bits(read(base+10+1+kind),24)+bits(read(base+10+9+kind),8) end
    local value=read(base+10+19+kind);assert(value>=0,'Secondary loot value is invalid.')
    gross=gross+count*value
   end
   local allowance=ti(29370);assert(allowance>=0,'Loot allowance is invalid.');gross=gross+allowance
   local fence,pavel=tf(29594),tf(29595)
   assert(fence<=0 and fence>=-1 and pavel<=0 and pavel>-1,'Cayo fee signs are invalid.')
   -- Fence condition depends on finale-only host progress. Use the larger of the
   -- two source branches, which remains within the target if the fence is charged.
   local factor=math.max(f(f(1+fence)+pavel),f(1+pavel))
   if active_cayo then
    assert(#ctx.active_slots==1 and ctx.host_player==pid and ctx.participants[1].player==pid,'Active payout adjustment is available only to the single local host.')
    local original_host_rows=0
    for i=0,3 do
     local crew=read(1981687+pid*27+i);local share=read(1981697+pid*27+i)
     if crew==pid then original_host_rows=original_host_rows+1 else assert(share==0,'Departed crew shares are unresolved; active solo maximum unavailable.') end
    end
    assert(original_host_rows==1,'Original Cayo crew roster is ambiguous.')
    local collected=read_local(61422);assert(collected>=0,'Collected secondary take is invalid.')
    gross=math.min(gross,primary+collected)
    local progress
    local override=read(2686124+6898+35)
    if (read(4718592+139796)&(1<<28))~=0 and override~=-2 then progress=override
    else
     local participant=ctx.host_participant_index
     assert(type(participant)=='number' and participant%1==0 and participant>=0 and participant<=31,'Controller host participant index is unknown.')
     progress=read_local(69376+1+participant*293+212)
    end
    factor=f(1)
    if progress>=ti(29593) then factor=f(factor+fence) end
    factor=f(factor+pavel)
    projection='OBSERVED_ACTIVE_SOLO_TAKE'
   end
   pool=rnd(f(gross)*factor)
   fees={{name='Pavel',percent=-pavel*100}}
   source=active_cayo and 'FMC2020 func3383,3397,880; observed collected loot and actual fence branch; local solo host only'
    or 'FMC2020 func3383..3396; inventory ceiling; larger conditional fence branch'
  elseif family=='casino' then
   if active_casino then HeistOps.read_guard(ctx,'reward_event') end
   assert(ti(28471)==0 and ti(28472)==0,'A Casino fee-discount bonus is active; participant eligibility is unknown.')
   local base
   gross,base=HeistOps.casino_take_inputs(ctx,r,diff)
   local buyer=read(1973728+8);assert(buyer>=0 and buyer<=8,'Casino buyer is unknown.')
