   -- Its local planning fallback applies only when the boss is -1; this bound
   -- payout context already proves a real owner, so never use stale local data.
   local driver=read(base+14);assert(driver>=1 and driver<=5,'Casino driver is unknown.')
   fees={{name='Lester',percent=ti(28422)},
    {name='Gunman',percent=crew(10,13,28448)},
