    {name='Driver',percent=ti(28458+driver-1)}}
   local fraction=f(0)
   for _,fee in ipairs(fees)do assert(fee.percent>=0 and fee.percent<100,'Casino crew fee is invalid.');fraction=f(fraction+f(f(fee.percent)/100))end
   assert(fraction<1,'Casino crew fees consume the take.')
   local after_buyer=f(f(gross)*f(buyer_factor))
   if active_casino then
    local collected=read_local(20412+2686)
    local participant=ctx.host_participant_index
    assert(type(participant)=='number' and participant%1==0 and participant>=0 and participant<=31,'Controller host participant index is unknown.')
    -- FMC func2456 uses plLocal3281=PLAYER_ID(), not the network participant index.
    local loss=read_local(32785+1+pid*294+153+2)
    local multiplier=read_local(20412+1777)
    assert(collected>=0 and loss>=0 and multiplier>=1 and multiplier<=4,'Casino collected take/loss inputs are invalid.')
