    end
    after_buyer=f(f(f(gross)*f(buyer_factor))-f(loss*multiplier))
    projection=finish_take and (#ctx.active_slots==1 and 'INSTANT_FINISH_SOLO_TAKE' or 'INSTANT_FINISH_PARTY_TAKE_CEILING') or 'OBSERVED_ACTIVE_SOLO_TAKE'
   end
   -- func2474 subtracts an unrounded fee product, then applies each cut.
   pool=f(after_buyer-f(after_buyer*fraction))
   source='FMC func2469 -> func2480 -> func2474; buyer before crew; no intermediate net rounding'
  else error('No observed automatic payout formula exists for this family.')end
  positive(gross);positive(pool)
  if conditional_reward_ceiling>1 or reward_multiplier~=1 then
   membership_ceiling=true
   projection=projection..'_CONDITIONAL_UPPER_BOUND'
  end
  ctx.payout_observations=observations
  local spec={family=family,heist=ctx.heist,context=ctx,difficulty=diff,
   active_slots=ctx.active_slots,components={{name='Observed no-loss ceiling',amount=gross,multiplier=1}},
   fees=fees,fee_mode='combined',rounding='nearest',arithmetic='float32',source_pool=pool,
   formula_source=source,estimate_kind=projection,input_source=projection,observations=observations,
   finish_take=active_casino and finish_take==true or nil,
   cut_multiplier=cut_multiplier,settlement_multipliers={membership_multiplier,reward_multiplier,conditional_reward_ceiling},membership_ceiling=membership_ceiling,
   bonus_scope=membership_ceiling and 'Conditional payout upper bound only; award and membership eligibility are unverified.' or 'Base finale transaction; separate awards excluded.'}
  return spec
 end)
 if not ok then return nil,tostring(result) end
 local valid,message=validate_payout_context(family,ctx)
 if not valid then return nil,message end
 return result
