local function validate_payout_spec(spec)
 if type(spec)~='table' or type(spec.context)~='table' or type(spec.observations)~='table' then return false,'Observed payout context is missing.' end
 local valid,why=validate_payout_context(spec.family,spec.context);if not valid then return false,why end
 local current,err=read_payout_spec(spec.family,spec.finish_take==true);if not current then return false,err end
 if current.context.key~=spec.context.key or current.heist~=spec.heist or #current.observations~=#spec.observations then return false,'The payout source changed; recalculate.' end
 for i,expected in ipairs(spec.observations)do
  local actual=current.observations[i]
  if actual.index~=expected.index or actual.kind~=expected.kind or actual.argument~=expected.argument or actual.script_hash~=expected.script_hash or actual.value~=expected.value then return false,'Take, difficulty, crew fees or bonus inputs changed; recalculate.' end
 end
