function HeistOps.apply_active_cut(family,values,expected)
 if HeistOps.active_cut and HeistOps.active_cut.verified~=true then
  local ok,restored,why=pcall(HeistOps.restore_active_cut)
  if HeistOps.active_cut then return false,ok and (why or 'Active percentage cleanup is pending.') or tostring(restored) end
 end
 if (family~="cayo" and family~="apartment" and family~="casino" and family~="doomsday") or #expected.active_slots~=1 then return false,"Active payout adjustment requires a supported solo host." end
 local valid,why=validate_cut_request(CUT_PROFILES[family],values);if not valid then return false,why end
