 if family=="cayo" then for i=0,3 do
  local crew=g.GetInt(1981687+ctx.host_player*27+i);local share=g.GetInt(1981697+ctx.host_player*27+i)
  if crew==ctx.host_player then original_host_rows=original_host_rows+1 elseif share~=0 then return false,"Original party shares could redistribute; active solo adjustment unavailable." end
 end
 if original_host_rows~=1 then return false,"Original Cayo crew roster is ambiguous." end end
 if type(before)~="number" or before%1~=0 or before<0 or before>max_cut then return false,"Active player percentage is unreadable." end
 local previous=HeistOps.active_cut
 if previous and previous.ctx.controller_identity~=ctx.controller_identity then
  -- Never replay a previous controller's local-player state into a new VM.
  HeistOps.active_cut=nil;previous=nil
 end
 if previous and before~=previous.applied then return false,"Active percentage changed externally; preserved." end
 if previous and before==values[1] then return true,"Active cut already matches by readback." end
 local tx={family=family,ctx=ctx,index=index,before=previous and previous.before or before,previous_value=before,applied=values[1],expected=expected}
 HeistOps.active_cut=tx
 local ok,err=pcall(function()
  assert(validate_payout_context(family,expected));assert(HeistOps.same(ctx))
  assert(g.GetInt(index)==before,"Active percentage changed before write.")
  if family=='casino' or family=='doomsday' then
   HeistOps.guard(ctx.script_hash,'reward_event')
   HeistOps.guard(ctx.script_hash,'classic_reward_owner')
   assert(validate_payout_context(family,expected));assert(HeistOps.same(ctx))
  end
  tx.attempted=true
  g.SetInt(index,tx.applied)
  assert(g.GetInt(index)==tx.applied,"Active cut readback failed.")
  assert(validate_payout_context(family,expected));assert(HeistOps.same(ctx))
 end)
 if not ok then if tx.attempted then HeistOps.restore_active_cut() else HeistOps.active_cut=nil end;return false,tostring(err) end
