 if same==nil then
  -- An unavailable identity is not an ended scope. A positive liveness read
  -- for the captured thread can establish termination without replaying globals.
  if HeistOps.controller_ended(tx.ctx) then
   HeistOps.active_cut=nil;return false,"Controller thread ended; the old active percentage was not replayed."
  end
  return false,"Controller identity unavailable; active percentage restoration remains pending."
 end
 if same==false then HeistOps.active_cut=nil;return false,"Controller changed; the old active percentage was not replayed." end
 local g=assert(global_service());local current=g.GetInt(tx.index)
 if current~=tx.applied and current~=tx.before and current~=tx.previous_value then return false,"Active percentage changed externally; preserved." end
 local ok,err=pcall(function()
  assert(HeistOps.same(tx.ctx))
  assert(g.GetInt(tx.index)==current,"Active percentage changed before restore.")
  if current~=tx.before then g.SetInt(tx.index,tx.before) end
  assert(g.GetInt(tx.index)==tx.before,"Active percentage restoration failed.")
