local function payout_activity()
 local ok,family,route=pcall(function()
  assert(launch_build_status())
  local controller_count=0
  for name in pairs(HeistOps.controllers) do
   local count,query_error=thread_count(assert(script_hash(name)))
   assert(count~=nil,query_error)
   assert(count==0 or count==1,"Ambiguous controller instance.")
   controller_count=controller_count+count
  end
  assert(controller_count<=1,"Multiple controllers are active.")
  local launcher_count,query_error=thread_count(assert(script_hash(FMMC_PROFILE.script)))
  assert(launcher_count~=nil,query_error)
  assert(launcher_count==0 or launcher_count==1,"Ambiguous launcher instance.")
  if controller_count==0 and launcher_count==0 then return nil end
  local g=assert(global_service())
  local identified,reason=HeistOps.identify(g,g.GetInt(FMMC_PROFILE.mission_hash_index))
  assert(identified,reason)
  if identified=='apartment' and controller_count==1 and launcher_count==1 then
   local hash=assert(script_hash('fm_mission_controller'))
   if thread_count(hash)==1 and binding('ScriptLocal').GetInt(hash,HeistOps.controllers.fm_mission_controller.root)==0 then
