function HeistOps.can_handoff()
    if HeistOps.pending or HeistOps.active_cut or solo_override
        or HeistOps.catalogue_cleanup or HeistOps.late_admission or ready_snapshot or next(cut_pending) then return false end
    local apartment=context_ref and context_ref.Modules and context_ref.Modules.HeistAdapterApartment
    if apartment then
        if type(apartment.CanHandoff)=="function" then
            local called,clean,why=pcall(apartment.CanHandoff)
            if not called then return false,tostring(clean) end
            if clean~=true then return false,why or "Apartment planner cleanup remains pending." end
            return true
        end
        local ok,status=pcall(function()return apartment.ChallengeStatus()end)
        return ok and type(status)=="table" and status.enabled==false
    end
    return true
end


-- Source shop_controller: 16-cell header, fifteen 84-cell transaction rows.
-- Only observe the queue; GTA retains its checkout, retry and error policy.
function HeistOps.transaction_ready()
 local ok,ready,reason=pcall(function()
  local g,n=assert(binding('ScriptGlobal')),assert(binding('Natives'))
  assert(g.GetInt(4515492)==16,'Transaction queue is unavailable.')
  local alert=g.GetInt(4516981)
  assert(alert==0 or alert==1,'Transaction alert state is unavailable.')
  if alert==1 then
   if g.GetInt(4516987)==20 then return false,'Rockstar rejected a payment: too many requests. Wait before trying again.' end
   return false,"Close GTA's transaction alert before finishing another heist."
  end
  if n.InvokeBool(0xA65568121DF2EA26)~=false or n.InvokeBool(0x613F125BA3BD2EB9)~=false then
   return false,"Wait for GTA's current transaction to finish."
  end
  for slot=0,14 do
   local state=g.GetInt(4515492+1+slot*84+67)
   assert(type(state)=='number' and state%1==0 and state>=0 and state<=3,'Transaction state is unavailable.')
   if state~=0 then return false,"Wait for GTA's current transaction to finish." end
  end
  return true
 end)
 if not ok then return false,'Game transaction status is unavailable. Try again shortly.' end
 return ready==true,reason
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.CScript) ~= "table" or type(context.Modules) ~= "table" then
        error("modules.heist_runtime_profiles requires CScript and Modules services")
    end
    context_ref = context
    public_api = {
        -- The only retained legacy mutation entry point is Doomsday Instant Finish.
        InstantFinish=function(family)
            if family~='doomsday'then return false,'This legacy controller is retired for '..tostring(family)..'.'end
            local ready,why=HeistOps.transaction_ready()
            if not ready then return false,why end
            return HeistOps.finish('doomsday')
        end,
        RefreshFinishStatus=function(family)
            if family~='doomsday'then return {family=family,ready=false,state='RETIRED',reason='Use the replacement controller.'}end
            return HeistOps.refresh('doomsday')
        end,
        FinishStatus=function()return HeistOps.finish_event end,
        TransactionReady=HeistOps.transaction_ready,
        TickFinish=HeistOps.tick,
        RestoreFinish=HeistOps.restore,
        CanHandoff=HeistOps.can_handoff,
        HasPendingFinish=function()return HeistOps.pending~=nil or HeistOps.classic_observation~=nil or HeistOps.ending_skip.Requested()end,
        DrainUnload = function()
            HeistOps.ending_skip.Stop()
            HeistOps.solo_auto.enabled=false
            HeistOps.classic_observation=nil
            local payout=context_ref and context_ref.CScript and context_ref.CScript.HeistPayout
            if payout and type(payout.SetAutomatic)=="function" then payout.SetAutomatic(false) end
            local ok,reason=true,nil
            local prototype=context_ref and context_ref.CScript and context_ref.CScript.HeistPrototypes
            if prototype and type(prototype.Quiesce)=='function' then
                local called,clean=pcall(prototype.Quiesce)
                if not called or clean~=true then ok=false;reason='Replacement controller cleanup remains pending.'end
            end
            local apartment=context_ref and context_ref.Modules and context_ref.Modules.HeistAdapterApartment
            if apartment then
                local has_drain=type(apartment.DrainUnload)=="function"
                local stopped,result,detail=pcall(has_drain and apartment.DrainUnload or apartment.Stop)
                ok=stopped and result~=false and (not has_drain or result==true)
                if not ok then reason=tostring((stopped and detail or result) or "Apartment planner cleanup remains pending.") end
            end
            ok=HeistOps.restore("Unload: completion patch restored.") and ok
            if HeistOps.active_cut then ok=HeistOps.restore_active_cut() and ok end
            if solo_override then ok=restore_solo_launch("Unload") and ok end
            if ready_snapshot then ok=restore_ready_snapshot() and ok end
            ok=HeistOps.tick_late_admission(true) and ok
            ok=HeistOps.tick_catalogue_cleanup(true) and ok
            for _,tx in pairs(cut_pending) do ok=rollback_cuts(tx) and ok end
            if not ok then return false,reason end
            return HeistOps.can_handoff()
        end,
        SourceRevision=SOURCE_REVISION,
        MigrationPhase=Module.MigrationPhase,
    }
    context.Modules.HeistRuntimeProfiles = Module
    context.CScript.HeistRuntimeProfiles = public_api
end

function Module.Start()
 if not started then HeistOps.ending_skip.Rearm() end
 started = true
end
function Module.Stop()
    HeistOps.ending_skip.Stop()
    HeistOps.solo_auto.enabled=false
    HeistOps.classic_observation=nil
    -- A previous Stop may have quiesced the module with restoration pending.
    -- Keep its public retry path alive and allow later Stop/Restore attempts.
    if not started and HeistOps.can_handoff() then return true end
    pcall(HeistOps.restore, "Module stopped")
    if HeistOps.active_cut then pcall(HeistOps.restore_active_cut) end
    if ready_snapshot then pcall(restore_ready_snapshot) end
    if solo_override then pcall(restore_solo_launch, "CScript stop") end
    pcall(HeistOps.tick_late_admission,true)
    pcall(HeistOps.tick_catalogue_cleanup,true)
    if ready_snapshot or solo_override or HeistOps.catalogue_cleanup or HeistOps.late_admission then
        log("Warning", "Launcher restoration remains pending at stop; the public retry path is retained while this VM remains available.")
    end
    for _,tx in pairs(cut_pending) do rollback_cuts(tx) end
    if next(cut_pending) then log("Warning","Cut cleanup is unresolved at unload; no restoration claim. Restart will not replay these values.") end
    invalidate_runtime_detection()
    started = false
    if not HeistOps.can_handoff() then return false,"Heist restoration remains pending." end
    invalidate_cuts()
    return true
end
function Module.Restore(context)
    context = context or context_ref
    local clean,why=Module.Stop()
    if clean~=true then return false,why end
    if context and context.CScript and context.CScript.HeistRuntimeProfiles == public_api then
        context.CScript.HeistRuntimeProfiles = nil
    end
    if context and context.Modules and context.Modules.HeistRuntimeProfiles == Module then
        context.Modules.HeistRuntimeProfiles = nil
    end
    context_ref, public_api = nil, nil
end

return Module
