-- Local and selected-player controls, movement, survival, and observer tools.
local Module = { Name = "modules.player", MigrationPhase = "17.75" }

local module_context
local public_api
local friendly_cleanup_ready
local ghost_relationship_pending_raw
local dependencies
local bound = false
local started = false
local lifecycle_token
local store_ignore
local remote_guard44
local remote_protection_handoff44
local bst_pending46
local remote_proof_io44 = { ptr = nil, busy = false }
-- Return obligations survive Lua-only quiesce/rebind. Only the gameplay thread
-- may resolve them against fresh entity and player-connection identities.
local super_melee_owner_debts = {}
-- Diagnostic obligations, never mutation capabilities. Survives module rebind;
-- a new Lua VM cannot adopt these records as live entity identities.
local messiah_cleanup_evidence = { records = {}, unresolved = 0, overflow = 0, serial = 0 }
local MESSIAH_EVIDENCE_LIMIT = 128

-- Contact decisions are transient. No persistent entity collision flags are
-- written, so disabling this policy immediately leaves normal physics alone.
function Module.NewSelfIsolationController(d)
    local api, tracked, count = {}, {}, 0
    local handler_id, active, generation = nil, false, 0
    local blocked, failures, detail = 0, 0, "Not registered"
    local function integer(value)
        return type(value)=="number" and value==value and value>0
            and value<math.huge and value%1==0
    end
    local function identity(entity)
        if entity==nil or entity:IsPhysical()~=true then return nil end
        local address, info = entity:GetAddress(), entity.ModelInfo
        local model = info and info.Model
        if not integer(address) or type(model)~="number" or model~=model
            or math.abs(model)==math.huge or model%1~=0 then return nil end
        return address, model%4294967296
    end
    local function same_local(entity, address, model)
        local local_address, local_model = identity(entity)
        return local_address~=nil and local_address==address and local_model==model
    end
    local function actor(entity, address, model, player_id)
        local record = address and tracked[address]
        if not record or record.model~=model then return false end
        -- An allocator can recycle the same address for the same model.
        -- Require the original handle too; resolve only tracked candidates.
        if d.PointerToHandle(entity)~=record.handle then return false end
        local object = entity.NetObject
        if object==nil then return record.networked==false end
        return object.IsRemote==false and object.PlayerId==player_id
    end
    local function decide(entity_a, entity_b)
        if not active or d.Running()~=true or d.Enabled()~=true then return true end
        local player_id = d.GetLocalPlayerId()
        if type(player_id)~="number" or player_id%1~=0 or player_id<0 or player_id>31 then return true end
        local address_a, model_a = identity(entity_a)
        local address_b, model_b = identity(entity_b)
        if not address_a or not address_b or address_a==address_b then return true end
        local a = actor(entity_a,address_a,model_a,player_id)
        local b = actor(entity_b,address_b,model_b,player_id)
        if not a and not b then return true end
        if a and b then return false end
        local address, model = a and address_b or address_a, a and model_b or model_a
        if same_local(d.GetLocalPed(),address,model) then return false end
        return not same_local(d.GetLocalVehicle(),address,model)
    end
    function api.Track(record)
        if type(record)~="table" or not integer(record.address) or not integer(record.handle)
            or type(record.model)~="number" or record.model~=record.model
            or math.abs(record.model)==math.huge or record.model%1~=0
            or type(record.networked)~="boolean" then return false end
        if not tracked[record.address] then
            if count>=384 then return false end
            count=count+1
        end
        tracked[record.address]={handle=record.handle,model=record.model%4294967296,networked=record.networked}
        return true
    end
    function api.Reset()
        tracked,count={},0
    end
    function api.Register()
        if active then return true end
        local manager = d.EventMgr
        if not manager or type(manager.RegisterHandler)~="function"
            or type(manager.RemoveHandler)~="function" or d.Event==nil then
            detail="SHOULD_COLLIDE is unavailable"
            return false,detail
        end
        if type(d.Running)~="function" or type(d.Enabled)~="function"
            or type(d.GetLocalPlayerId)~="function" or type(d.GetLocalPed)~="function"
            or type(d.GetLocalVehicle)~="function" or type(d.PointerToHandle)~="function" then
            detail="Local contact identity API is unavailable"
            return false,detail
        end
        if handler_id~=nil then
            -- A failed removal retains its ID, but its closed generation can
            -- never veto again. Retry removal before creating another handler.
            local ok,result=pcall(manager.RemoveHandler,handler_id)
            if not ok or result==false then return false,"Contact handler removal is pending" end
            handler_id=nil
        end
        generation=generation+1
        local current=generation
        local ok,id=pcall(manager.RegisterHandler,d.Event,function(entity_a,entity_b)
            if current~=generation or not active then return true end
            local read,result=pcall(decide,entity_a,entity_b)
            if not read then failures=math.min(1000000000,failures+1);return true end
            if result==false then blocked=math.min(1000000000,blocked+1);return false end
            return true
        end)
        if not ok or type(id)~="number" or id<0 or id%1~=0 then
            detail="Contact handler registration failed"
            return false,detail
        end
        handler_id,active,detail=id,true,"Ready"
        return true
    end
    function api.Stop()
        active=false;generation=generation+1
        api.Reset()
        detail="Stopped"
        if handler_id~=nil then
            local ok,result=pcall(d.EventMgr.RemoveHandler,handler_id)
            if not ok or result==false then
                detail="Contact handler inert; removal pending"
                return false
            end
            handler_id=nil
        end
        return true
    end
    function api.Snapshot()
        return {registered=active,removal_pending=handler_id~=nil and not active,
            tracked=count,blocked=blocked,failures=failures,detail=detail}
    end
    return api
end

-- BEGIN LOCAL_AUTO_TP
function Module.NewAutoTeleportController(d)
    local api,s,ticking={},{generation=0,status="OFF",requests=0},false
    local H={exists=0x7239B21A38F536BA,dead=0x5F9532F3B5CC2551,model=0x9F47B058362C84B5,
        ped=0x524AC5ECEA15343E,vehicle_kind=0x6AC7003FA6E5575E,player_ped=0x43A66C31C68491C0,
        active=0xB8DFD30D6973E135,vehicle=0x9A9112A0FE9A4713,driver=0xBB40DD2270B65366,
        in_any=0x997ABD671D25CA0B,in_vehicle=0xA3EE4A07279BB9DB,entering=0xBB062B2B5722478E,
        networked=0xC7827959479DCC78,control=0x01BF60A500E28887,player_control=0x49C32D60007AFA47,
        collision=0xCCF1E97BEFDAE480,
        interior=0x2107BA504071A6BB,ready=0x6726BDCCC1932F0E,offset=0x1899F328B0E12848,
        transition=0x68049AEFF83D8F0A,switch=0xD9D2CFFF49FAB35F,cutscene=0x991251AFC3981F84,
        playing=0xD3C2E180A40F031E,gameplay=0x39B5D1B10383F0C8,faded=0xB16FCE9DDC7BA182,
        fading=0x797AC7CB535BA28F,frame=0xFC8202EFC642E6F2,
        request=0x07503F7948F491A7,move=0x239A3351AC1DA385,leave=0xD3DBCE61A490BE02}
    local function finite(n)return type(n)=="number" and n==n and math.abs(n)<math.huge end
    local function read(kind,hash,...)
        local ok,a,b,c=d.Try(kind,hash,...);assert(ok,"Teleport native unavailable")
        if kind=="bool" then
            assert(type(a)=="boolean" or a==0 or a==1,"Teleport boolean unavailable")
            return a==true or a==1
        end
        if kind=="int" then assert(finite(a) and a%1==0,"Teleport identity unavailable")end
        return a,b,c
    end
    local function vector(hash,...)
        local a,b,c=read("vector3",hash,...)
        if type(a)~="number" then
            assert(type(a)=="table" or type(a)=="userdata","Teleport position unavailable")
            a,b,c=a.x,a.y,a.z
        end
        assert(finite(a) and finite(b) and finite(c),"Teleport position unavailable")
        return {x=a,y=b,z=c}
    end
    local function same_connection(a,b)
        return a and b and a.rid==b.rid and a.cxn==b.cxn and a.local_id==b.local_id
