    local function wait_for(reason)
        s.status,s.detail="WAITING",reason
        return nil
    end
    function api.Cancel(reason)
        local pid,owner=s.pid,s.owner
        s.last_pid=pid or s.last_pid
        s.generation=s.generation+1;s.active,s.pid,s.owner,s.proof,s.exit=false,nil,nil,nil,nil
        s.status,s.detail="OFF",reason or "Off"
        if pid~=nil and d.Stopped then d.Stopped(pid,owner,s.detail)end
        return true
    end
    function api.Enable(pid,owner)
        if type(pid)~="number" or pid%1~=0 or pid<0 or pid>31 then
            return false,"Select an available player."
        end
        if d.Running()~=true then return false,"Player runtime unavailable."end
        local self_target=pid==d.LocalPlayer()
        local identity,session=self_target and {rid="self",cxn=0,local_id=pid}or d.Identity(pid),d.Session()
        if not identity or session==nil then return false,"Player connection identity unavailable."end
        if s.active and s.pid==pid and s.owner==owner then return true end
        api.Cancel("Replaced by a new Auto-tp selection")
        s.pid,s.owner,s.identity,s.session=pid,owner,identity,session
        s.active,s.status,s.detail=true,"ARMED","Waiting for the native frame"
        s.due,s.last_frame,s.requests=0,nil,0
        return true
    end
    function api.Requested()return s.active==true end
    function api.Target()return s.pid end
    function api.Prune()
