        if allow_missing and not present then return nil end
        if allow_missing and read("bool",H.dead,handle,false) then return nil end
        assert(present and not read("bool",H.dead,handle,false) and read("bool",kind,handle),"Entity unavailable or dead")
        local model,address=read("int",H.model,handle),d.Address(handle)
        assert(model~=0 and finite(address) and address%1==0 and address>=0x10000,"Entity allocation unavailable")
        return {handle=handle,model=model,address=address}
