        end
        if not read("bool",H.active,s.pid) then
            return wait_for("Waiting for the selected player to become active")
        end
        local lp=entity(d.LocalPed(),H.ped,true)
        if not lp then return wait_for("Waiting for your character to respawn") end
        local target=entity(read("int",H.player_ped,s.pid),H.ped,true)
        if not target then return wait_for("Waiting for the selected player to respawn or stream in") end
        local vehicle=current_vehicle(lp.handle)
        if vehicle==nil then return nil end
        local car=vehicle>0 and entity(vehicle,H.vehicle_kind,true) or nil
        if vehicle>0 and not car then return wait_for("Waiting for local vehicle transition") end
        local passenger=car~=nil and read("int",H.driver,vehicle,-1,false)~=lp.handle
        -- A passenger may move only their own ped, never the driver's vehicle.
