                (not proof.passenger and driver==proof.ped.handle),"Seat changed before local action")
            assert(same(proof.car,entity(proof.vehicle,H.vehicle_kind)),"Occupied vehicle allocation changed")
        end
        assert(not read("bool",H.networked,proof.mover.handle) or read("bool",H.control,proof.mover.handle),
            "Local entity control changed before teleport")
        if d.Available then
            local ready,reason=d.Available()
