local function require_binding(name, value)
    if value == nil then error("player compatibility binding missing " .. name, 3) end
    return value
end

local function new_store_ignore_guard(get_context, spec)
    spec = spec or {
        script = "am_hold_up",
        hash = 0x0C6DAC46,
        reference_hex =
        "",
        prefix = "2D 00 06 00 00 2C 01 00 86 3A C4 34 0A 25 1C 2C 08 01 B9",
        tail =
        "D8 3A 79 41 10 2C 05 00 AE 5D 96 59 00 2A 06 56 09 00 2C 01 00 D8 2C 05 00 7B 20 56 0F 00 2C 01 00 86 3A C4 34 0A 40 05 74 2C 08 00 BF 2E 00 00",
        tail_offset = 920,
        patches = { { offset = 19, patched_hex = "557F01000000062A" } },
    }
    local function bytes(hex)
        assert(type(hex) == "string", "Missing guard bytes.")
        hex = hex:gsub("%s", ""); assert(#hex % 2 == 0 and not hex:find("[^%x]"), "Invalid guard bytes.")
        return (hex:gsub("%x%x", function(v) return string.char(tonumber(v, 16)) end))
    end
    local reference = bytes(spec.reference_hex)
    local patches = {}
    assert(type(spec.script) == "string" and type(spec.hash) == "number" and #reference >= 8,
        "Invalid controller specification.")
    for i, p in ipairs(spec.patches) do
        assert(type(p.offset) == "number" and p.offset % 1 == 0 and p.offset >= 0 and p.offset + 8 <= #reference,
            "Invalid guard span.")
        local replacement = bytes(p.patched_hex); assert(#replacement == 8, "Guard must occupy one word.")
        for _, prior in ipairs(patches) do
            assert(p.offset >= prior.offset + 8 or p.offset + 8 <= prior.offset,
                "Overlapping guards.")
        end
        patches[i] = {
            offset = p.offset,
            original = string.unpack("<i8", reference, p.offset + 1),
            patched = string
                .unpack("<i8", replacement)
        }
    end
    assert(#patches > 0, "Missing guard spans.")
    local wanted, owner, busy, revision, next_check = false, nil, false, 0, 0
    local retry_after, retry_entry, retry_ptr, retry_reason = 0, nil, nil, nil
    local prefix_bytes, tail_bytes = bytes(spec.prefix), bytes(spec.tail)
    local state = {
        phase = "OFF",
        applied = false,
        owned = false,
        restore_pending = false,
        live_verified = false,
        last_scan_ms = 0,
        max_scan_ms = 0,
        scan_calls = 0,
        detail =
        "Store reaction guard is off."
    }
    local api = {}
    local function status(phase, detail, applied)
        state.phase, state.detail, state.applied = phase, detail, applied == true
        state.owned = owner ~= nil; state.restore_pending = owner ~= nil and not state.applied
    end
    local function address(p)
        return type(p) == "number" and p == p and p % 1 == 0 and p >= 0x10000 and
            p < 0x00007FFFFFFFFFFF - #reference
    end
    local function call(fn, ...)
        local token = revision
        if type(fn) ~= "function" then return false, "Required host API unavailable." end
        local r = table.pack(pcall(fn, ...))
        if token ~= revision then return false, "Request changed during host callback." end
        if not r[1] then return false, tostring(r[2]) end
        return true, table.unpack(r, 2, r.n)
    end
    local function context()
        local ok, c = call(get_context); if not ok or type(c) ~= "table" then return nil end
        local function usable(m)
            return (type(m) == "table" or type(m) == "userdata") and type(m.ScanScript) ==
                "function" and type(m.ReadLong) == "function" and type(m.WriteLong) == "function"
        end
        local m = c.Raw and c.Raw.Memory
        if not usable(m) then
            local got, v = call(c.Cherax and c.Cherax.Get, "Memory"); if got then m = v end
        end
        if not usable(m) then m = c.Memory end
        if not usable(m) then m = nil end
        return c, m
    end
    local function scan(m, pattern)
        local clock = os and os.clock
        local started = type(clock) == "function" and clock() or nil
        local ok, p = call(m.ScanScript, spec.hash, pattern)
        state.scan_calls = state.scan_calls + 1
        if started then
            local elapsed = math.max(0, (clock() - started) * 1000)
            state.last_scan_ms = elapsed; state.max_scan_ms = math.max(state.max_scan_ms, elapsed)
        end
        if ok and address(p) then return p end
    end
    local function recognized(fresh)
        for i, p in ipairs(patches) do
            if fresh.values[i] ~= p.original and fresh.values[i] ~= p.patched then
                return false,
                    "Foreign guard bytes preserved."
            end
        end
        return true
    end
    local function discover(m, full)
        local entry = scan(m, "2D"); if not entry then return nil, "Controller resource is temporarily unavailable." end
        local ptr, tail = scan(m, spec.prefix), scan(m, spec.tail)
        if not ptr or not tail or tail - ptr ~= spec.tail_offset then
            return nil,
                "Controller signature is unavailable or unsupported."
        end
        if full then
            local offsets = {}; for offset = 0, #reference - 8, 8 do offsets[#offsets + 1] = offset end
            if #reference % 8 ~= 0 then offsets[#offsets + 1] = #reference - 8 end
            for _, offset in ipairs(offsets) do
                local ok, word = call(m.ReadLong, ptr + offset)
                if not ok or type(word) ~= "number" or word % 1 ~= 0 then
                    return nil,
                        "Controller word could not be read."
                end
                local mask = -1
                for byte = 0, 7 do
                    for _, p in ipairs(patches) do
                        if offset + byte >= p.offset and offset + byte < p.offset + 8 then
                            mask = mask & ~(0xff << (byte * 8)); break
                        end
                    end
                end
                local original = string.unpack("<i8", reference, offset + 1)
                if (word & mask) ~= (original & mask) then
                    return nil,
                        "Controller function differs from the supported resource."
                end
            end
        end
        local fresh = { entry = entry, ptr = ptr, values = {} }
        for i, p in ipairs(patches) do
            local ok, v = call(m.ReadLong, ptr + p.offset)
            if not ok or type(v) ~= "number" or v % 1 ~= 0 then return nil, "Guard bytes could not be read." end
            fresh.values[i] = v
        end
        local ok, why = recognized(fresh); if not ok then return nil, why end
        if scan(m, "2D") ~= entry or scan(m, spec.prefix) ~= ptr or scan(m, spec.tail) ~= tail then
            return nil,
                "Controller resource changed during verification."
        end
        return fresh
    end
    local function segment_matches(m, ptr, expected)
        local offsets = {}; for offset = 0, #expected - 8, 8 do offsets[#offsets + 1] = offset end
        if #expected % 8 ~= 0 then offsets[#offsets + 1] = #expected - 8 end
        for _, offset in ipairs(offsets) do
            local ok, word = call(m.ReadLong, ptr + offset)
            if not ok or type(word) ~= "number" or word % 1 ~= 0 or word ~= string.unpack("<i8", expected, offset + 1) then return false end
        end
        return true
    end
    local function health(m)
        -- Both addresses are fresh. No cached code pointer is read here.
        -- ScanScript's documentation does not promise constant-time entry scans.
        local fresh = { entry = scan(m, "2D") }
        if not fresh.entry then return nil, "Controller resource is temporarily unavailable.", fresh end
        fresh.ptr = scan(m, spec.prefix)
        if not fresh.ptr then return nil, "Controller prefix is unavailable.", fresh end
        -- A matching prefix alone does not establish the resource's extent.
        -- Only an already fully proven owned allocation permits fixed reads.
        if not owner or fresh.entry ~= owner.entry or fresh.ptr ~= owner.ptr then
            return nil, "Controller identity requires complete proof.", fresh
        end
        -- Verified functions fit inside one codepage; fixed reads stay within it.
        if not segment_matches(m, fresh.ptr, prefix_bytes) or not segment_matches(m, fresh.ptr + spec.tail_offset, tail_bytes) then
            return nil, "Controller health signature differs from the supported resource.", fresh
        end
        fresh.values = {}
        for i, p in ipairs(patches) do
            local ok, v = call(m.ReadLong, fresh.ptr + p.offset)
            if not ok or type(v) ~= "number" or v % 1 ~= 0 then return nil, "Guard bytes could not be read.", fresh end
            fresh.values[i] = v
        end
        local ok, why = recognized(fresh); if not ok then return nil, why, fresh end
        return fresh, nil, fresh
    end
    local function same(a, b) return a and b and a.entry == b.entry and a.ptr == b.ptr end
    local function ownership(fresh)
        for i, p in ipairs(patches) do
            if fresh.values[i] == p.patched and (not owner or not owner.words[i]) then
                return false,
                    "An unowned controller guard is already present."
            end
        end
        return true
    end
    local function restore_now(m)
        if not owner then
            status("OFF", "Store reaction guard is off."); return true
        end
        local fresh, why = discover(m, true)
        if not fresh then
            status("RESTORE_PENDING", why); return false
        end
        if not same(fresh, owner) then
            if fresh.entry == owner.entry then
                status("RESTORE_PENDING",
                    "Controller entry is unchanged but its matching function moved; cleanup remains unresolved."); return false
            end
            owner = nil; status("OFF", "Previous controller resource was replaced."); return true
        end
        local accepted, reason = ownership(fresh); if not accepted then
            status("RESTORE_PENDING", reason); return false
        end
        for i, p in ipairs(patches) do
            if owner.words[i] then
                if fresh.values[i] == p.original then
                    owner.words[i] = nil
                else
                    local ok, err = call(m.WriteLong, fresh.ptr + p.offset, p.original)
                    if not ok then
                        status("RESTORE_PENDING", err); return false
                    end
                    local after, detail = discover(m, true)
                    if not after or not same(after, owner) or after.values[i] ~= p.original then
                        status("RESTORE_PENDING", detail or "Restore read-back did not verify the original bytes."); return false
                    end
                    local checked, note = ownership(after); if not checked then
                        status("RESTORE_PENDING", note); return false
                    end
                    owner.words[i] = nil; fresh = after
                end
            end
        end
        owner = nil; status("OFF", "Original store reaction observer restored."); return true
    end
    local function serialized(fn)
        if busy then return false end
        busy = true; local ok, r = pcall(fn); busy = false
        if not ok then
            status(owner and "RESTORE_PENDING" or "UNAVAILABLE", tostring(r)); return false
        end
        return r
    end
    function api.Cancel()
        wanted = false; revision = revision + 1; next_check = 0; retry_after = 0; state.applied = false
        status(owner and "RESTORE_PENDING" or "OFF", "Store reaction guard disable requested.")
    end

    function api.Restore()
        api.Cancel()
        if busy then return owner == nil end
        return serialized(function()
            if not owner then
                status("OFF", "Store reaction guard is off."); return true
            end
            local _, m = context(); if not m then
                status("RESTORE_PENDING", "Waiting for the memory API to restore the controller."); return false
            end
            return restore_now(m)
        end)
    end

    function api.Tick(now, enabled)
        enabled = enabled == true
        if wanted ~= enabled then
            wanted = enabled; revision = revision + 1; next_check = 0; retry_after = 0; state.applied = false
        end
        if busy then return false end
        if not wanted and not owner then
            status("OFF", "Store reaction guard is off."); return true
        end
        now = tonumber(now) or 0; if now < next_check then return state.applied end; next_check = now + 1000
        return serialized(function()
            local c, m = context()
            if not c then
                status(owner and "RESTORE_PENDING" or "UNAVAILABLE", "Required context is unavailable."); return false
            end
            -- Native availability belongs to gameplay Tick. Worker Restore is memory only.
            local n = c.Natives; local called, accepted, loaded = call(n and n.Try, "bool", 0xE6CC9F3BA0FB9EF1,
                spec.script)
            if not called or accepted ~= true or type(loaded) ~= "boolean" then
                status(owner and "RESTORE_PENDING" or "WAITING", "Controller availability could not be checked."); return false
            end
            if not loaded then
                owner = nil; retry_after = 0; next_check = now + 100; status(wanted and "WAITING" or "OFF",
                    "Store controller is not loaded; enable intent is retained."); return not wanted
            end
            if not m then
                status(owner and "RESTORE_PENDING" or "UNAVAILABLE", "Required memory API is unavailable."); return false
            end
            if not wanted then return restore_now(m) end
            local observed, why, identity
            local was_active = state.applied
            if owner or retry_after > 0 then observed, why, identity = health(m) end
            if was_active and retry_after == 0 and observed and same(observed, owner) then
                local complete = true
                for i, p in ipairs(patches) do if observed.values[i] ~= p.patched or not owner.words[i] then complete = false end end
                if complete then
                    status("ACTIVE", "Local store reactions are guarded; existing closure is not reversed.", true); return true
                end
            end
            if retry_after > now and identity and identity.entry == retry_entry and identity.ptr == retry_ptr then
                status(owner and "RESTORE_PENDING" or "WAITING",
                    retry_reason or why or "Unsupported controller proof is waiting before retry."); return false
            end
            local function defer(reason)
                if not identity then
                    local _, _, id = health(m); identity = id
                end
                retry_after = now + 30000; retry_entry = identity and identity.entry; retry_ptr = identity and
                    identity.ptr; retry_reason = reason
            end
            local fresh
            fresh, why = discover(m, true)
            if not fresh then
                defer(why); status(owner and "RESTORE_PENDING" or "WAITING", why); return false
            end
            if owner and not same(fresh, owner) then
                if fresh.entry == owner.entry then
                    local detail =
                    "Controller entry is unchanged but its matching function moved; cleanup remains unresolved."
                    identity = fresh; defer(detail); status("RESTORE_PENDING", detail); return false
                end
                owner = nil
            end
            local ok, note = ownership(fresh)
            if not ok then
                identity = fresh; defer(note); status(owner and "RESTORE_PENDING" or "CONFLICT", note); return false
            end
            retry_after = 0
            for i, p in ipairs(patches) do
                if fresh.values[i] ~= p.patched then
                    -- Ownership is recorded before each fallible/reentrant word write.
                    owner = owner or { entry = fresh.entry, ptr = fresh.ptr, words = {} }
                    owner.words[i] = true; status("APPLYING", "Applying the verified store reaction guard.")
                    local wrote, err = call(m.WriteLong, fresh.ptr + p.offset, p.patched)
                    if not wrote then
                        status("RESTORE_PENDING", err); return false
                    end
                    local after, detail = discover(m, true)
                    if not after or not same(after, owner) or after.values[i] ~= p.patched or not wanted then
                        status("RESTORE_PENDING", detail or "Guard read-back did not verify this request."); return false
                    end
                    ok, note = ownership(after); if not ok then
                        status("RESTORE_PENDING", note); return false
                    end
                    fresh = after
                end
            end
            status("ACTIVE", "Local store reactions are guarded; existing closure is not reversed.", true); return true
        end)
    end

    function api.Requested() return wanted or owner ~= nil end

    function api.CanHandoff() return owner == nil and not busy end

    function api.Snapshot()
        local s = {}; for k, v in pairs(state) do s[k] = v end
        s.script = spec.script; s.enabled = wanted; s.owned = owner ~= nil; s.restore_pending = owner ~= nil and
            not state.applied
        return s
    end

    return api
end

local function new_peds_store_guards(get_context)
    local specs = {
        {
            script = "gunclub_shop",
            hash = 0x1BEB0BF6,
            reference_hex =
            "",
            prefix = "2D 04 0F 00 00 38 00 41 09 2A 56 06 00 38 00 41 01 06 1F 2A 56 06 00 72 5D 16 30 0D 1F",
            tail = "00 55 17 00 38 02 5D 55 64 0F 38 03 5D 55 64 0F 38 00 41 0C 5D 55 64 0F 55 00 00 2E 04 00",
            tail_offset = 936,
            patches = {
                { offset = 85,  patched_hex = "55bb00005d61650f" },
                { offset = 519, patched_hex = "55b500002c050318" },
            }
        },
        {
            script = "clothes_shop_mp",
            hash = 0xC0F0BBC3,
            reference_hex =
            "",
            prefix = "2D 04 0F 00 00 38 00 41 09 2A 56 06 00 38 00 41 01 06 1F 2A 56 06 00 72 5D CC F8 16 1F",
            tail = "00 55 17 00 38 02 5D 63 F9 17 38 03 5D 63 F9 17 38 00 41 0C 5D 63 F9 17 55 00 00 2E 04 00",
            tail_offset = 936,
            patches = {
                { offset = 85,  patched_hex = "55bb00005d6ffa17" },
                { offset = 519, patched_hex = "55b500002c05027f" },
            }
        },
        {
            script = "clothes_shop_sp",
            hash = 0xF8A3166B,
            reference_hex =
            "",
            prefix = "2D 04 0F 00 00 38 00 41 09 2A 56 06 00 38 00 41 01 06 1F 2A 56 06 00 72 5D 78 C4 17 1F",
            tail = "00 55 17 00 38 02 5D 82 C4 18 38 03 5D 82 C4 18 38 00 41 0C 5D 82 C4 18 55 00 00 2E 04 00",
            tail_offset = 936,
            patches = {
                { offset = 85,  patched_hex = "55bb00005d8dc518" },
                { offset = 519, patched_hex = "55b500002c05012a" },
            }
        },
    }
    local guards = { new_store_ignore_guard(get_context) }
    for _, spec in ipairs(specs) do guards[#guards + 1] = new_store_ignore_guard(get_context, spec) end
    local wanted, busy, revision, next_check, index = false, false, 0, 0, 1
    local api = {}
    function api.Requested()
        if wanted then return true end
        for _, g in ipairs(guards) do if g.Requested() then return true end end
        return false
    end

    function api.CanHandoff()
        if busy then return false end
        for _, g in ipairs(guards) do if not g.CanHandoff() then return false end end
        return true
    end

    function api.Snapshot()
        local s = { phase = "OFF", applied = false, owned = false, restore_pending = false, enabled = wanted, live_verified = false, scripts = {} }
        local active, pending, blocked = 0, 0, 0
        for _, g in ipairs(guards) do
            local child = g.Snapshot(); s.scripts[child.script] = child
            if child.applied then active = active + 1 end
            s.owned = s.owned or child.owned
            if child.restore_pending then pending = pending + 1 end
            if child.phase == "CONFLICT" or child.phase == "UNAVAILABLE" then blocked = blocked + 1 end
        end
        s.restore_pending = pending > 0; s.applied = active > 0 and pending == 0 and blocked == 0
        s.phase = pending > 0 and "RESTORE_PENDING" or active > 0 and (blocked > 0 and "PARTIAL" or "ACTIVE") or
            wanted and "WAITING" or "OFF"
        s.detail = ("Store reactions: %d active, %d waiting, %d awaiting cleanup."):format(active, #guards - active,
            pending)
        return s
    end

    function api.Restore()
        wanted = false; revision = revision + 1; next_check = 0
        for _, g in ipairs(guards) do g.Cancel() end
        if busy then return api.CanHandoff() end
        busy = true; local ok, result = pcall(function()
            local clean = true; for _, g in ipairs(guards) do if not g.Restore() then clean = false end end
            return clean
        end); busy = false
        return ok and result and api.CanHandoff()
    end

    function api.Tick(now, enabled)
        enabled = enabled == true; now = tonumber(now) or 0
        if wanted ~= enabled then
            wanted = enabled; revision = revision + 1; next_check = 0
            if not wanted then for _, g in ipairs(guards) do g.Cancel() end end
        end
        if busy then return false end
        if not wanted and api.CanHandoff() then return true end
        if now < next_check then return api.Snapshot().applied end
        next_check = now + 250
        local token = revision; busy = true
        local ok = pcall(guards[index].Tick, now, wanted)
        busy = false; index = index % #guards + 1
        if not ok or token ~= revision then return false end
        return api.Snapshot().applied
    end

    return api
end
-- END STORE IGNORE GUARD

local function new_property_exit_guard(env)
    local api, records = {}, {}
    local epoch, cursor, due, running, last_clock = 0, 0, 0, false, nil
    local function integer(v) return type(v) == "number" and v == v and v % 1 == 0 and math.abs(v) < math.huge end
    local function supported(i)
        if not integer(i) then return false end
        return (i >= 0 and i <= 41) or (i >= 60 and i <= 80) or (i >= 83 and i <= 97 and i ~= 88)
            or (i >= 102 and i <= 111) or i == 122 or i == 124 or (i >= 128 and i <= 133)
            or i == 147 or (i >= 149 and i <= 153) or (i >= 155 and i <= 158) or (i >= 161 and i <= 179) or i == 181
    end
    local function connection(a, b)
        return a and b and a.rid ~= nil and a.cxn ~= nil and a.rid == b.rid and a.cxn == b.cxn
    end
    local function same_player(a, b)
        a, b = a and a.request, b and b.request
        return a and b and a.player_id == b.player_id and a.local_id == b.local_id and a.generation == b.generation
            and connection(a.identity, b.identity) and connection(a.local_identity, b.local_identity)
    end
    local function same(a, b)
        return same_player(a, b) and a.index == b.index and a.instance == b.instance and a.owner == b.owner
            and a.exit_type == b.exit_type and connection(a.request.owner_identity, b.request.owner_identity)
    end
    local function eligible(o, pid, local_id)
        return o and o.request and o.request.player_id == pid and o.request.local_id == local_id and pid ~= local_id
            and supported(o.index) and integer(o.instance) and o.instance >= 0 and o.instance < 32
            and integer(o.owner) and o.owner >= 0 and o.owner < 32 and o.request.owner_id == o.owner
            and integer(o.exit_type) and o.exit_type >= 0 and o.exit_type <= 15
    end
    function api.Reset()
        epoch = epoch + 1; records = {}; cursor = 0; due = 0; last_clock = nil
    end

    function api.Same(a, b) return same(a, b) end

    function api.Supports(index) return supported(index) end

    local function step(now)
        if not env.enabled() then
            api.Reset(); return
        end
        if not integer(now) then return end
        if last_clock and now < last_clock then due = now + 50 end
        last_clock = now
        if now < due then return end
        due = now + 50
        local token = epoch
        local local_id = env.local_id()
        if not integer(local_id) or local_id < 0 or local_id > 31 then
            api.Reset(); return
        end
        for _ = 1, 4 do
            if epoch ~= token or not env.enabled() then return end
            local pid = cursor; cursor = (cursor + 1) % 32
            if pid ~= local_id then
                local o = env.observe(pid)
                if epoch ~= token or not env.enabled() then return end
                local s = records[pid]
                if o and o.outside == true and s and same_player(o, s.observation) then
                    s.outside = (s.outside or 0) + 1
                    if s.outside >= 2 then records[pid] = nil end
                elseif eligible(o, pid, local_id) then
                    if not s or not same(o, s.observation) then
                        s = { observation = o, stable = 0, attempts = 0, next_send = 0 }; records[pid] = s
                    end
                    s.outside = 0
                    if o.ready ~= true then
                        s.stable = 0
                    else
                        s.stable = s.stable + 1
                        if s.stable >= 2 and s.attempts < 4 and now >= s.next_send
                            and (not s.deadline or now < s.deadline) then
                            local fresh = env.observe(pid)
                            if epoch ~= token or not env.enabled() then return end
                            local valid = same(o, fresh) and fresh.ready == true and env.valid(fresh)
                            if epoch ~= token or not env.enabled() then return end
                            if valid then
                                s.attempts = s.attempts + 1; s.next_send = now + 1000; s.deadline = s.deadline or
                                    now + 8000
                                env.send(fresh,
                                    { env.event, local_id, 0, fresh.index, fresh.instance, fresh.exit_type, 0, 0, -1 },
                                    function() return epoch == token and env.enabled() and epoch == token end)
                                if epoch ~= token or not env.enabled() then return end
                            end
                        end
                    end
                end
            end
        end
    end
    function api.Tick(now)
        if running then return end
        running = true
        local ok = pcall(step, now)
        running = false
        if not ok then due = (type(now) == "number" and now or 0) + 500 end
    end

    return api
end
-- END PROPERTY EXIT GUARD

-- BEGIN OUTFIT_CLEANUP_DEBT44
-- Bookkeeping only: an unload worker must not destroy a retained preview lease
-- or run entity/camera cleanup outside the existing gameplay scheduler.
local function outfit_resources_pending()
    local editor = State.outfit
    return type(editor) == "table" and ((tonumber(editor.preview_ped) or 0) ~= 0
        or (tonumber(editor.preview_cam) or 0) ~= 0 or (tonumber(editor.delete_ptr) or 0) ~= 0
        or editor.camera_lease ~= nil or editor.cleanup_pending == true)
end
-- END OUTFIT_CLEANUP_DEBT44

-- A local exit is a prerequisite, not completion of the requested trip.
-- Submit once, then wait for GTA's registration, collision world and control.
function Module.NewLocalInteriorExit(host)
    local active, latest, serial, revision = nil, nil, 0, 0
    local history, order = {}, {}
    local api = {}
    local function snapshot(s)
        return s and {
            token = s.token,
            active = s.active == true,
            phase = s.phase,
            detail = s.detail,
            status = s.status,
            label = s.label,
            local_id = s.local_id,
            requested = s.requested == true
        } or { active = false, status = "IDLE", phase = "idle" }
    end
    local function finish(s, status, detail)
        if active ~= s then return end
        s.active = false; s.status = status; s.phase = status:lower(); s.detail = detail
        active = nil; latest = s; history[s.token] = snapshot(s); order[#order + 1] = s.token
        if #order > 8 then history[table.remove(order, 1)] = nil end
        return snapshot(s)
    end
    function api.Begin(label, now, intent)
        if active then return nil, "Another interior exit is already in progress." end
        local captured_revision = revision
        if intent and intent() ~= true then return nil, "The requested trip was cancelled." end
        local s, why = host.Capture()
        if not s then return nil, why or "The current interior could not be resolved." end
        if active or revision ~= captured_revision or intent and intent() ~= true
            or active or revision ~= captured_revision then
            return nil, "The requested trip changed during capture."
        end
        revision = revision + 1
        serial = serial + 1; s.token = serial; s.label = tostring(label or "Interior trip")
        s.active = true; s.status = "PENDING"; s.phase = "queued"; s.intent = intent
        s.started = tonumber(now) or 0; s.deadline = s.started + 30000; s.last_poll = -100000
        s.detail = "Preparing to leave the current interior through GTA."
        active = s; latest = s
        return s.token
    end

    function api.Requested() return active ~= nil end

    function api.Snapshot() return snapshot(active or latest) end

    function api.Cancel(token, reason)
        if token == nil or active and token == active.token then revision = revision + 1 end
        if active and (token == nil or token == active.token) then
            return finish(active, "CANCELLED", reason or "Interior exit cancelled.")
        end
        return token and history[token] or snapshot(latest)
    end

    function api.Tick(now)
        local s = active; if not s then return end
        now = tonumber(now) or s.started
        local function current()
            if active ~= s or not s.active or s.intent and s.intent() ~= true or host.Valid(s) ~= true then return false end
            return active == s and s.active == true
        end
        if not current() then
            return finish(s, "CANCELLED",
                "Interior trip cancelled: player, session or request changed.")
        end
        if now < s.started then return finish(s, "FAILED", "The interior-exit clock changed; retry the trip.") end
        if now >= s.deadline then return finish(s, "FAILED", "GTA did not finish leaving the current interior in time.") end
        if now >= s.last_poll and now - s.last_poll < 100 then return end
        s.last_poll = now
        local o, why = host.Observe(s)
        if not current() then return finish(s, "CANCELLED", "Interior trip changed during observation.") end
        if not o then
            s.detail = why or "Waiting for current interior data."; return
        end
        if o.outside and o.control then
            s.phase = "confirming_exterior"; s.detail = "Confirming exterior registration and player control."
            s.outside_since = s.outside_since or now
            if now - s.outside_since >= 250 then
                return finish(s, "COMPLETE",
                    "GTA confirmed exterior registration and player control.")
            end
            return
        end
        s.outside_since = nil
        if o.changed then return finish(s, "CANCELLED", "You entered another interior while this trip was pending.") end
        if s.requested then
            s.phase = "leaving"; s.detail = "Waiting for GTA to finish the current interior exit."; return
        end
        if not o.control then
            s.phase = "waiting_for_control"; s.detail = "Waiting for the current interior transition to restore control."; return
        end
        if s.dispatching then return end
        s.dispatching = true
        local ok, accepted, detail = pcall(host.Request, s, current)
        s.dispatching = false
        if active ~= s or not s.active then return end
        if not current() then return finish(s, "CANCELLED", "Interior trip changed during the exit request.") end
        if not ok or accepted == false then
            return finish(s, "FAILED",
                ok and detail or "The interior exit request failed.")
        end
        if accepted == true then
            s.requested = true; s.phase = "leaving"; s.detail = detail or "GTA interior exit requested."
        else
            s.detail = detail or "Waiting for GTA's interior exit controller."
        end
    end

    function api.Poll(token, now)
        if active and active.token == token then api.Tick(now) end
        if active and active.token == token then return snapshot(active) end
        return history[token] or
            {
                token = token,
                active = false,
                status = "CANCELLED",
                phase = "cancelled",
                detail =
                "The interior-exit request is no longer current."
            }
    end

    return api
end

-- BEGIN SCRIPTED SCREENS55 CONTROLLER
-- Bounded, connection-pinned sender for the reviewed freemode script catalog.
-- This factory owns only Lua intent. Host.Send owns the single-recipient transport.
function Module.NewScriptedScreens(host)
    assert(type(host) == "table", "Scripted screens require a host adapter.")
    for _, name in ipairs({ "Capture", "Valid", "Now", "Send" }) do
        assert(type(host[name]) == "function", "Scripted screens require Host." .. name .. ".")
    end
    local modes = {
        online_intro = { selector = 20, label = "Online Intro" },
        iaa_hack = { selector = 209, label = "Doomsday Hack" },
        wizard_arcade = { selector = 270, label = "Wizard's Ruin" },
        space_monkey = { selector = 276, label = "Space Monkey 3" },
        badlands = { selector = 269, label = "Badlands Revenge II" },
        camhedz = { selector = 278, label = "Camhedz" },
    }
    local active, revision, serial, last_nonce = nil, 0, 0, 0
    local stopped, admitting, busy, reporting = false, false, false, false
    local cooldown = {} -- Only validated integer player IDs 0..31 can enter this table.
    local latest = { active = false, phase = "idle", detail = "", recipient_confirmed = false, dispatches = 0 }
    local api = {}

    local function integer(value, minimum, maximum)
        return type(value) == "number" and value == value and value % 1 == 0 and value >= minimum and value <= maximum
    end
    local function valid_time(value)
        return type(value) == "number" and value == value and value >= 0 and value <= 9007199254740991
    end
    local function copy(value)
        local result = {}; for key, item in pairs(value) do result[key] = item end; return result
    end
    local function clock()
        local ok, value = pcall(host.Now)
        if not ok then return nil, "The script clock could not be read: " .. tostring(value) end
        if not valid_time(value) then return nil, "The script clock returned an invalid time." end
        return value
    end
    local function cache(s)
        latest = {
            player_id = s.player_id,
            kind = s.kind,
            active = s.active,
            phase = s.phase,
            detail = s.detail,
            started_ms = s.started_ms,
            first_dispatch_ms = s.first_dispatch_ms,
            deadline_ms = s.deadline_ms,
            next_due_ms = s.next_due_ms,
            nonce = s.nonce,
            dispatches = s.dispatches,
            attempts = s.attempts,
            possibly_dispatched = s.begin_fenced == true or s.dispatches > 0,
            readiness_observed = s.ready_observed == true,
            transport = s.transport or "direct",
            recipient_confirmed = false
        }
    end
    local function finish(s, phase, detail)
        if active ~= s or not s.active then return end
        s.active = false; s.pin.active = false; active = nil; revision = revision + 1
        s.phase = phase; s.detail = s.label .. ": " .. tostring(detail)
        if phase ~= "dispatched" and (s.begin_fenced or s.dispatches > 0) then
            s.detail = s.detail .. " Already dispatched requests cannot be recalled."
        end
        cache(s)
        if type(host.Report) == "function" then
            reporting = true; pcall(host.Report, copy(latest)); reporting = false
        end
    end
    local function current(s, phase, now)
        -- Pure Lua only. This check must follow every host observation in a fence.
        return active == s and s.active and s.revision == revision and not stopped
            and s.pin.active == true and s.pin.player_id == s.player_id
            and s.pin.local_id == s.local_id and s.pin.generation == s.generation
            and (phase == nil or s.phase == phase)
            and (now == nil or (now >= s.started_ms and now >= s.last_now and now < s.deadline_ms))
    end
    local function time_error(s, now)
        if not valid_time(now) then return "failed", "The script clock returned an invalid time." end
        if now < s.started_ms or now < s.last_now then
            return "failed",
                "The script clock moved backwards; request stopped."
        end
        if now >= s.deadline_ms then
            return "expired",
                "The two-second dispatch deadline expired; remaining sends stopped."
        end
    end
    local function observe(s, phase, supplied_now)
        if not current(s, phase) then return nil, "cancelled", "The request is no longer current." end
        local now, why = supplied_now, nil
        if now == nil then now, why = clock() end
        if not current(s, phase) then return nil, "cancelled", "The request changed while reading the clock." end
        if now == nil then return nil, "failed", why end
        local code, detail = time_error(s, now)
        if code then return nil, code, detail end
        local ok, valid = pcall(host.Valid, s.pin)
        if not current(s, phase) then return nil, "cancelled", "The request changed during identity validation." end
        if not ok then return nil, "failed", "Player identity could not be checked: " .. tostring(valid) end
        if valid == nil then return nil, "unavailable", "Waiting for the captured player connection." end
        if valid ~= true then return nil, "cancelled", "Selected player, local actor or session changed." end
        local final, err = clock()
        if not current(s, phase) then return nil, "cancelled", "The request changed during final validation." end
        if final == nil then return nil, "failed", err end
        code, detail = time_error(s, final)
        if code then return nil, code, detail end
        if final < now then return nil, "failed", "The script clock moved backwards during validation." end
        if not current(s, phase, final) then return nil, "cancelled", "The request was cancelled before dispatch." end
        s.last_now = final
        return final
    end
    local function inputs(pid, kind)
        if not integer(pid, 0, 31) then return "Select a valid player (0 through 31)." end
        if type(kind) ~= "string" or not modes[kind] then return "Choose a scripted screen." end
    end
    local function admission_block(pid, now, own_admission)
        if stopped then return "Scripted screen actions are stopped; rearm the player runtime first." end
        if active or busy or reporting or (admitting and not own_admission) then
            return
            "Another scripted screen request is already in progress."
        end
        local previous = cooldown[pid]
        if previous then
            if now < previous.at then return "The script clock moved backwards; wait for a stable clock before retrying." end
            if now < previous.until_ms then
                return string.format(
                    "Wait %.1f seconds before another request for this player.", (previous.until_ms - now) / 1000)
            end
        end
    end
    function api.Availability(pid, kind, now)
        local why = inputs(pid, kind); if why then return false, why end
        if stopped or active or busy or reporting or admitting then
            return false, admission_block(pid, 0, false)
        end
        local token = revision
        if now == nil then now, why = clock() end
        if token ~= revision then return false, "The request state changed; retry the action." end
        if not valid_time(now) then return false, why or "The script clock returned an invalid time." end
        why = admission_block(pid, now, false)
        return why == nil, why
    end

    local function begin_request(pid, kind, anchor, pinned, retry_nonce)
        local why = inputs(pid, kind); if why then return false, why end
        if stopped or active or busy or reporting or admitting then
            return false, admission_block(pid, 0, false)
        end
        admitting = true
        local token, pin = revision, nil
        local function pending() return admitting and token == revision and not stopped and active == nil end
        local function reject(detail)
            admitting = false
            if type(pin) == "table" then pin.active = false end
            return false, detail
        end
        local began, err = clock()
        if not pending() then return reject("Request cancelled while reading the clock.") end
        if began == nil then return reject(err) end
        why = admission_block(pid, began, true); if why then return reject(why) end
        local ok, captured, capture_error
        if pinned then
            -- Each sequence owns its active flag and identity tables. Finishing
            -- it must not invalidate the enable-time anchor retained by a toggle.
            ok, captured = true, copy(anchor)
            for key, value in pairs(captured) do
                if type(value) == "table" then captured[key] = copy(value) end
            end
        else
            ok, captured, capture_error = pcall(host.Capture, pid)
        end
        if ok and type(captured) == "table" then pin = captured end
        if not pending() then return reject("Request cancelled while capturing the player.") end
        if not ok then return reject("Could not capture the selected player: " .. tostring(captured)) end
        if not pin then return reject(tostring(capture_error or "Selected player or source layout is unavailable.")) end
        if pin.active ~= true or pin.player_id ~= pid or not integer(pin.local_id, 0, 31) then
            return reject("The captured player identity is incomplete; select the player again.")
        end
        local local_id, generation = pin.local_id, pin.generation
        local checked, valid = pcall(host.Valid, pin)
        if not pending() then return reject("Request cancelled during identity validation.") end
        if not checked then return reject("Player identity could not be checked: " .. tostring(valid)) end
        if valid ~= true then return reject("Selected player, local actor or session changed.") end
        local now, clock_error = clock()
        if not pending() then return reject("Request cancelled during final admission checks.") end
        if now == nil then return reject(clock_error) end
        if now < began then return reject("The script clock moved backwards; retry the action.") end
        if now >= began + 2000 then return reject("Player capture exceeded the two-second deadline; retry the action.") end
        if pin.active ~= true or pin.player_id ~= pid or pin.local_id ~= local_id or pin.generation ~= generation then
            return reject("The captured player identity changed; retry the action.")
        end
        -- Keep identifiers positive and signed-32-bit, without clock-wrap reuse.
        -- Exhaustion fails closed instead of recycling an identifier in this VM.
        local nonce = retry_nonce
        if nonce ~= nil then
            if not integer(nonce, 1, last_nonce) then return reject("Retry requires an existing request identifier.") end
        else
            local next_serial = serial + 1
            nonce = math.max(last_nonce + 1, (math.floor(now) % 1000000000) + next_serial)
            if nonce > 2147483647 then return reject("Request identifiers are exhausted; reload the player runtime.") end
            serial, last_nonce = next_serial, nonce
        end
        local mode = modes[kind]
        active = {
            pin = pin,
            player_id = pid,
            local_id = local_id,
            generation = generation,
            revision = token,
            kind = kind,
            label = mode.label,
            selector = mode.selector,
            nonce = nonce,
            active = true,
            stage = 1,
            phase = "queued",
            detail = mode.label .. ": Request queued.",
            started_ms = began,
            deadline_ms = began + 2000,
            last_now = now,
            next_due_ms = now,
            attempts = 0,
            dispatches = 0,
            begin_fenced = false
        }
        cooldown[pid] = { at = now, until_ms = now + 5000 }
        admitting = false; cache(active)
        return true, active.detail
    end
    function api.Begin(pid, kind) return begin_request(pid, kind, nil, false) end

    function api.BeginPinned(pid, kind, anchor, nonce)
        if type(anchor) ~= "table" or anchor.active ~= true then
            return false, "The original player connection is unavailable; enable the action again."
        end
        return begin_request(pid, kind, anchor, true, nonce)
    end

    function api.Selector(kind) return modes[kind] and modes[kind].selector end

    function api.IsKnownKind(kind) return type(kind) == "string" and modes[kind] ~= nil end

    local function payload(s, stage)
        -- freemode func_348/25436: three header cells + 21 data cells + flags.
        -- func_25400 ACK: the same header/data with no trailing flags cell.
        local args = { stage == 1 and 1541018842 or 1757622014, s.local_id, 0 }
        for offset = 0, 20 do args[4 + offset] = 0 end
        for _, offset in ipairs({ 1, 2, 9, 16, 19, 20 }) do args[4 + offset] = -1 end
        args[4] = s.selector; args[7] = 48; args[21] = s.nonce
        if stage == 1 then args[25] = 0 end
        return args
    end
    local function can_observe_ready(s)
        if type(host.CanObserveReady) ~= "function" then return false end
        local ok, available = pcall(host.CanObserveReady, s.pin)
        return ok and available == true and current(s)
    end

    function api.ObserveReady(actual_sender, args)
        -- Event callbacks only queue a matching cue. All host/native/connection
        -- checks run on the scheduler turn and again at the dispatch fence.
        local s = active
        if not s or not current(s) or not s.wait_for_ready or s.stage ~= 2
            or s.phase ~= "waiting_ready" or s.dispatches ~= 1 or s.ready_queued or actual_sender ~= s.player_id
            or type(args) ~= "table" then
            return false
        end
        local count = 0
        for key, value in next, args do
            count = count + 1
            if count > 24 or not integer(key, 1, 24)
                or not integer(value, -2147483648, 2147483647) then
                return false
            end
        end
        if count ~= 24 or rawget(args, 1) ~= -1634378433
            or rawget(args, 2) ~= actual_sender or rawget(args, 3) ~= 0 then
            return false
        end
        local expected = payload(s, 2)
        for index = 4, 24 do if rawget(args, index) ~= expected[index] then return false end end
        s.ready_queued = true
        return true
    end

    local function dispatch(s)
        local stage = s.stage
        local previous_phase = s.phase
        local phase = stage == 1 and "sending_begin" or stage == 2 and "sending_ack1" or "sending_ack2"
        local args = payload(s, stage)
        -- Consume before entering the host; neither reentry nor an exception retries it.
        s.stage = stage + 1; s.phase = phase; s.attempts = s.attempts + 1
        s.detail = s.label .. ": dispatching " .. (stage == 1 and "begin" or "ACK") .. " request."
        cache(s)
        local fenced, fence_code, fence_error, identity_paused = false, nil, nil, false
        local function fence()
            local now, code, why = observe(s, phase)
            if now == nil then
                identity_paused = code == "unavailable"
                fence_code, fence_error = code, why; return false
            end
            if s.ack_from_ready then
                local eligible = can_observe_ready(s)
                -- Eligibility calls the live host adapter. Its callbacks can
                -- invalidate the earlier identity/time observation.
                now, code, why = observe(s, phase)
                if now == nil then
                    identity_paused = code == "unavailable"
                    fence_code, fence_error = code, why; return false
                end
                if not eligible then
                    fence_code, fence_error = "unavailable", "Freemode host changed before the readiness ACK."
                    return false
                end
            end
            if not current(s, phase, now) then return false end
            -- observe ended with pure current/revision/phase/deadline checks.
            fenced = true
            if stage == 1 then
                s.begin_fenced = true
                -- Timestamp the actual guarded transport boundary. Queuing or
                -- a refused identity fence does not start recipient supervision.
                s.first_dispatch_ms = s.first_dispatch_ms or now
            end
            return true
        end
        local called, accepted, result = pcall(host.Send, s.player_id, args, fence)
        if not current(s, phase) then return false end
        if not called then
            finish(s, "failed", "Transport failed: " .. tostring(accepted)); return false
        end
        if accepted ~= true then
            if identity_paused and not fenced then
                -- The adapter returned normally after refusing its final
                -- fence: this stage never reached the transport. Keep the
                -- original deadline; exceptions/uncertain sends never retry.
                s.stage, s.phase = stage, previous_phase
                s.detail = s.label .. ": " .. tostring(fence_error)
                cache(s); return false
            end
            finish(s, fence_code or "failed", fence_error or ("Transport rejected the request: " .. tostring(result)))
            return false
        end
        if not fenced then
            finish(s, "failed", "Transport omitted the required final dispatch fence."); return false
        end
        s.dispatches = s.dispatches + 1
        if stage == 3 or (stage == 2 and s.ack_from_ready) then
            finish(s, "dispatched", "Request sent.")
            return false
        end
        local now, code, why = observe(s, phase)
        local paused = now == nil and code == "unavailable"
        if now == nil and not paused then
            finish(s, code, why); return false
        end
        -- A successful stage stays consumed if identity becomes unreadable
        -- immediately afterwards. Only the unsent remainder waits for recovery.
        now = now or s.last_now
        s.phase = stage == 1 and (s.wait_for_ready and "waiting_ready" or "begin_dispatched") or "waiting_ack2"
        s.next_due_ms = now + (stage == 2 and 20 or (s.wait_for_ready and 500 or 0))
        s.detail = s.label .. ": " .. (paused and tostring(why) or stage == 1 and
            (s.wait_for_ready and "waiting for recipient readiness." or "begin dispatched; preparing first ACK.")
            or "waiting before the final ACK.")
        cache(s)
        return not paused
    end
    function api.Tick(now)
        if busy or admitting or reporting or not active then return end
        busy = true
        local s = active
        local ok, err = pcall(function()
            local observed, code, why = observe(s, nil, now)
            if observed == nil then
                if code == "unavailable" then
                    s.detail = s.label .. ": " .. tostring(why); cache(s); return
                end
                finish(s, code, why); return
            end
            if s.stage == 1 then
                s.wait_for_ready = can_observe_ready(s)
                if not current(s) then return end
            elseif s.stage == 2 and s.wait_for_ready then
                local available = can_observe_ready(s)
                if not current(s) then return end
                if available and s.ready_queued then
                    s.ack_from_ready, s.ready_observed, s.transport = true, true, "ready_ack"
                    s.next_due_ms = observed
                elseif available and observed < s.next_due_ms then
                    return
                else
                    -- Optional cue unavailable or grace elapsed: retain the
                    -- original bounded direct path, never an extra ACK stream.
                    s.wait_for_ready, s.ready_queued = false, false
                    s.next_due_ms = observed
                end
            end
            if observed < s.next_due_ms then return end
            local budget = s.stage == 1 and not s.wait_for_ready and 2 or 1
            for _ = 1, budget do
                if not dispatch(s) then return end
            end
        end)
        if not ok then finish(s, "failed", "Scripted screen dispatch failed: " .. tostring(err)) end
        busy = false
    end

    function api.Cancel(reason)
        revision = revision + 1
        if active then finish(active, "cancelled", tostring(reason or "Remaining sends cancelled.")) end
        return copy(latest)
    end

    function api.Prune()
        local s = active
        if not s then return end
        local ok, valid = pcall(host.Valid, s.pin)
        if current(s) and ok and valid == false then
            api.Cancel("Selected player, local actor or session changed.")
        end
    end

    function api.Stop(reason)
        stopped = true; api.Cancel(reason or "Player runtime stopped; remaining sends cancelled.")
        return true
    end

    function api.Rearm()
        -- A newer Stop invoked by Report must win over this earlier rearm.
        stopped = false; api.Cancel("Runtime rearmed; previous pending sends cancelled.")
        return true
    end

    function api.Requested() return active ~= nil end

    function api.Snapshot() return copy(latest) end

    return api
end

-- Repeated intent stays positioned to the connection captured when it was enabled.
-- This companion advances the one-shot sender; it does not own another transport.
function Module.NewScriptedScreenRepeater(host, sender)
    assert(type(host) == "table" and type(sender) == "table", "Scripted screen repeats require a host and sender.")
    for _, name in ipairs({ "Capture", "Same", "Ready", "Now", "OnDisabled", "Observe", "CancelPending", "Cleanup" }) do
        assert(type(host[name]) == "function", "Scripted screen repeats require Host." .. name .. ".")
    end
    for _, name in ipairs({ "BeginPinned", "IsKnownKind", "Selector", "Availability", "Tick", "Requested", "Snapshot", "Cancel", "Stop", "Rearm" }) do
        assert(type(sender[name]) == "function", "Scripted screen repeats require Sender." .. name .. ".")
    end
    local entries, attempts = {}, {} -- Integer player IDs 0..31 positioned both maps.
    -- Cancelled nonces are retired, never reused by a new toggle. Keep at most
    -- six unresolved retired requests per connection; a clear publication by
    -- itself does not prove the receiver's private pending slot is clear.
    local histories = {}
    local revision, cursor, last_now = 0, -1, nil
    -- Product supervision window, not a receiver timeout or proof of rejection.
    local unconfirmed_after_ms = 30000
    local stopped, busy, editing, pruning, resetting = false, false, false, false, false
    local pending_enable, launching = nil, nil
    local api = {}
    local function player_id(pid)
        return type(pid) == "number" and pid == pid and pid % 1 == 0 and pid >= 0 and pid <= 31
    end
    local function valid_time(now)
        return type(now) == "number" and now == now and now >= 0 and now <= 9007199254740991
    end
    local function clock()
        local ok, now = pcall(host.Now)
        if not ok then return nil, "The repeat clock could not be read: " .. tostring(now) end
        if not valid_time(now) then return nil, "The repeat clock returned an invalid time." end
        return now
    end
    local function current(entry)
        return not stopped and entry.enabled and entries[entry.player_id] == entry
    end
    local function retired_count(history)
        local count = 0; for _ in pairs(history.retired) do count = count + 1 end; return count
    end
    local function status(entry, phase, detail, now)
        if not current(entry) then return end
        local tx = entry.history.transactions[entry.kind]
        local dispatch = sender.Snapshot()
        local ours = dispatch.player_id == entry.player_id and dispatch.kind == entry.kind
            and tx ~= nil and dispatch.nonce == tx.nonce
        local since = tx and (tx.admitted_ms or tx.first_dispatch_ms)
        local age = valid_time(now) and valid_time(since) and math.max(0, now - since) or nil
        local boundary = tx and tx.admitted and "recipient_ui" or "launcher"
        entry.snapshot = {
            player_id = entry.player_id,
            kind = entry.kind,
            enabled = true,
            active = ours and dispatch.active == true or false,
            phase = phase,
            detail = detail,
            nonce = tx and tx.nonce,
            selector = sender.Selector(entry.kind),
            admitted = tx and tx.admitted == true or false,
            sent = tx and tx.sent == true or false,
            recipient_confirmed = false,
            first_dispatch_ms = tx and tx.first_dispatch_ms,
            admitted_ms = tx and tx.admitted_ms,
            elapsed_ms = age,
            confirmation_boundary = boundary,
            confirmation_window_ms = unconfirmed_after_ms,
            retry_paused = phase == "unconfirmed",
            next_retry_ms = phase ~= "unconfirmed" and attempts[entry.player_id]
                and attempts[entry.player_id] + 5000 or nil,
            retired_count = retired_count(entry.history),
            readiness_observed = ours and dispatch.readiness_observed == true or false,
            transport = ours and dispatch.transport or nil
        }
        -- Report semantic boundaries once, without logging every observation or
        -- borrowing the global sender's latest result for another player.
        local report_key = phase .. ":" .. tostring(tx and tx.nonce) .. ":" .. boundary
        if type(host.Report) == "function" and entry.report_key ~= report_key then
            entry.report_key = report_key
            local value = {}; for key, item in pairs(entry.snapshot) do value[key] = item end
            pcall(host.Report, value)
        end
    end
    local function notify(entry, reason)
        if entry.notified then return end
        entry.notified = true
        pcall(host.OnDisabled, entry.player_id, entry.kind, tostring(reason or "Scripted screen disabled."))
    end
    local function cancel_matching(entry, reason)
        local snapshot = sender.Snapshot()
        if launching == entry or (snapshot.active and snapshot.player_id == entry.player_id and snapshot.kind == entry.kind) then
            sender.Cancel(reason or "Scripted screen disabled; remaining sends cancelled.")
        end
    end
    local function history_current(history, token)
        return histories[history.anchor.player_id] == history and revision == token
    end
    local function history_fence(history, token)
        return function()
            if not history_current(history, token) then return false end
            local ok, valid = pcall(host.Same, history.anchor)
            return ok and valid == true and history_current(history, token)
        end
    end
    local function remember_sender()
        local snapshot = sender.Snapshot()
        local history = histories[snapshot.player_id]
        local tx = history and history.transactions[snapshot.kind]
        if tx and tx.nonce == snapshot.nonce and snapshot.possibly_dispatched then
            tx.sent = true
            if not tx.first_dispatch_ms and valid_time(snapshot.first_dispatch_ms) then
                tx.first_dispatch_ms = snapshot.first_dispatch_ms
                tx.retry_window_ms = snapshot.first_dispatch_ms
            end
        end
    end
    local function observation(history, token, now)
        local fence = history_fence(history, token)
        if not fence() then return nil end
        local ok, value = pcall(host.Observe, history.anchor)
        if not ok or type(value) ~= "table" or not fence() then return nil end
        if value.active == false then
            -- Only witnessed admission followed by a clear broadcast proves a
            -- launch ended. Silence before admission cannot retire its ID.
            for kind, tx in pairs(history.transactions) do
                if tx.admitted then
                    history.transactions[kind] = nil
                elseif tx.saw_other_publication and valid_time(now) then
                    -- A witnessed occupiedâ†’clear boundary may resume an
                    -- uncancelled retry. It does not retire the pending nonce or
                    -- erase its original dispatch time/cancellation debt.
                    tx.retry_window_ms, tx.pending_timeout = now, false
                    tx.saw_other_publication = nil
                end
            end
            for nonce, tx in pairs(history.retired) do
                if tx.admitted then history.retired[nonce] = nil end
            end
            return value
        end
        if value.active ~= true or type(value.nonce) ~= "number" or value.nonce % 1 ~= 0
            or value.nonce < 1 or value.nonce > 2147483647
            or type(value.selector) ~= "number" or value.selector % 1 ~= 0
            or type(value.instance) ~= "number" or value.instance % 1 ~= 0
            or value.instance < -1 or value.instance > 31 then
            return nil
        end
        local owned
        for _, tx in pairs(history.transactions) do
            if tx.sent and tx.nonce == value.nonce and tx.selector == value.selector
                and (not tx.admitted or tx.instance == value.instance) then
                tx.admitted = true; tx.instance = value.instance; owned = tx
                if not tx.admitted_ms and valid_time(now) then tx.admitted_ms = now end
                tx.pending_timeout = false
                -- The receiver has one launcher slot. A witnessed new launch
                -- means older cancelled requests no longer occupy that slot.
                history.retired = {}
            end
        end
        if not owned then
            local tx = history.retired[value.nonce]
            if tx and tx.sent and tx.selector == value.selector
                and (not tx.admitted or tx.instance == value.instance) then
                tx.admitted = true; tx.instance = value.instance; owned = tx
                if not tx.admitted_ms and valid_time(now) then tx.admitted_ms = now end
            end
        end
        for _, tx in pairs(history.transactions) do
            if tx.sent and not tx.admitted then tx.saw_other_publication = true end
        end
        return value, owned
    end
    local function cleanup_debt(history)
        if history.anchor.player_id ~= history.anchor.local_id then return nil end
        local tx = history.transactions.iaa_hack
        if tx and tx.sent and tx.admitted and tx.selector == 209 then return tx end
        for _, retired in pairs(history.retired) do
            if retired.sent and retired.admitted and retired.selector == 209 then return retired end
        end
    end
    local function cleanup_owned(history, tx, token)
        if not tx or not tx.admitted or tx.selector ~= 209
            or history.anchor.player_id ~= history.anchor.local_id then
            return
        end
        local request = {
            kind = tx.kind,
            selector = tx.selector,
            nonce = tx.nonce,
            instance = tx.instance,
            admitted = true
        }
        pcall(host.Cleanup, history.anchor, request, history_fence(history, token))
    end
    local function service_cleanup(history, now, token, observed, owned)
        if stopped or not history_current(history, token) or not cleanup_debt(history)
            or now < (history.cleanup_due_ms or 0) then
            return
        end
        -- OFF removes repeat intent, but its admitted self launch may finish
        -- later. Consume this bounded cleanup turn before host callbacks.
        history.cleanup_due_ms = now + 250
        if not observed then
            local ok, ready = pcall(host.Ready, history.anchor)
            if stopped or not history_current(history, token) or not ok or ready ~= true then return end
            observed, owned = observation(history, token, now)
        end
        if not stopped and history_current(history, token) and observed and observed.active == true
            and owned ~= nil and owned == cleanup_debt(history) then
            cleanup_owned(history, owned, token)
        end
    end
    local function cancel_pending(history, tx, token, now)
        if not tx or not tx.sent or tx.admitted or not history_current(history, token) then return end
        if not valid_time(now) or now < (history.cancel_due_ms or 0) then return end
        -- This wait is a handoff policy, not a receiver cleanup acknowledgment.
        -- Consume before callback so reentry cannot duplicate cancellation.
        history.handoff_until_ms = math.max(history.handoff_until_ms or 0, now + 250)
        history.cancel_due_ms = now + 5000
        history.cancel_cursor = tx.nonce
        pcall(host.CancelPending, history.anchor, tx.nonce, history_fence(history, token))
    end
    local function service_retired(history, now, token)
        if now < (history.cancel_due_ms or 0) then return end
        local chosen, first
        for nonce, tx in pairs(history.retired) do
            if not tx.admitted then
                if not first or nonce < first.nonce then first = tx end
                if nonce > (history.cancel_cursor or 0) and (not chosen or nonce < chosen.nonce) then chosen = tx end
            end
        end
        cancel_pending(history, chosen or first, token, now)
    end
    local function cancel_entry(entry, token)
        remember_sender()
        local history = entry.history
        if not history or not history_current(history, token) then return end
        local observed, owned = observation(history, token, clock())
        if not history_current(history, token) then return end
        local tx = history.transactions[entry.kind]
        if tx and not tx.admitted then
            history.transactions[entry.kind] = nil
            if tx.sent then
                tx.retired = true; history.retired[tx.nonce] = tx
                local now = clock()
                if valid_time(now) then history.handoff_until_ms = math.max(history.handoff_until_ms or 0, now + 250) end
            end
        end
        if observed and observed.active then
            cleanup_owned(history, owned, token)
        elseif observed and tx and tx.retired then
            cancel_pending(history, tx, token, clock())
        end
    end
    local function remove(entry, reason)
        if entries[entry.player_id] ~= entry then return end
        entries[entry.player_id] = nil; entry.enabled = false; revision = revision + 1
        local token = revision
        cancel_matching(entry, reason)
        cancel_entry(entry, token)
        notify(entry, reason)
    end
    local function same(entry)
        local ok, value = pcall(host.Same, entry.anchor)
        if not current(entry) then return false end
        if not ok then
            status(entry, "unavailable", "Waiting for the captured player connection.")
            return false, "Player identity could not be checked: " .. tostring(value)
        end
        if value == false then
            remove(entry, "Selected player, local connection or session changed.")
            if histories[entry.player_id] == entry.history then histories[entry.player_id] = nil end
            return false
        end
        if value ~= true then status(entry, "unavailable", "Waiting for the captured player connection.") end
        return value == true
    end
    function api.IsEnabled(pid, kind)
        local entry = entries[pid]
        return entry ~= nil and entry.enabled and entry.kind == kind
    end

    function api.SetEnabled(pid, kind, enabled)
        if not player_id(pid) then return false, "Select a valid player (0 through 31)." end
        if not sender.IsKnownKind(kind) then return false, "Choose a scripted screen." end
        if type(enabled) ~= "boolean" then return false, "A scripted screen toggle must be ON or OFF." end
        if not enabled then
            if pending_enable and pending_enable.player_id == pid and pending_enable.kind == kind then
                pending_enable = nil; revision = revision + 1
            end
            local entry = entries[pid]
            if entry and entry.kind == kind then
                local prior = editing; editing = true
                remove(entry, "Scripted screen disabled; remaining sends cancelled.")
                editing = prior
            end
            return true
        end
        if stopped then return false, "Scripted screen repeats are stopped; rearm the player runtime first." end
        local old = entries[pid]
        if old and old.kind == kind then return true end
        if editing or busy or pruning or resetting then
            return false,
                "Scripted screen state is changing; retry the toggle."
        end
        editing = true
        local token = { player_id = pid, kind = kind, revision = revision }
        pending_enable = token
        local function pending()
            return pending_enable == token and revision == token.revision and not stopped and not resetting
        end
        local function finish(ok, detail)
            if pending_enable == token then pending_enable = nil end
            editing = false; return ok, detail
        end
        local began, why = clock()
        if not pending() then return finish(false, "Toggle changed while reading the clock.") end
        if began == nil then return finish(false, why) end
        local ok, anchor, detail = pcall(host.Capture, pid)
        if not pending() then return finish(false, "Toggle changed while capturing the player.") end
        if not ok then return finish(false, "Could not capture the player connection: " .. tostring(anchor)) end
        if type(anchor) ~= "table" or anchor.active ~= true or anchor.player_id ~= pid
            or not player_id(anchor.local_id) then
            return finish(false, tostring(detail or "Select an available player."))
        end
        local checked, unchanged = pcall(host.Same, anchor)
        if not pending() then return finish(false, "Toggle changed during connection validation.") end
        if not checked then return finish(false, "Player identity could not be checked: " .. tostring(unchanged)) end
        if unchanged ~= true then return finish(false, "Selected player, local connection or session changed.") end
        local now, clock_error = clock()
        if not pending() then return finish(false, "Toggle changed during final admission checks.") end
        if now == nil then return finish(false, clock_error) end
        if now < began then return finish(false, "The repeat clock moved backwards; retry the toggle.") end
        local history = histories[pid]
        if history then
            local checked, valid = pcall(host.Same, history.anchor)
            if not pending() then return finish(false, "Toggle changed during transaction validation.") end
            if not checked or valid == nil then return finish(false, "Previous connection identity is unavailable.") end
            if valid ~= true then history = nil end
        end
        if not history then
            history = { anchor = anchor, transactions = {}, retired = {} }; histories[pid] = history
        end
        local entry = { player_id = pid, kind = kind, anchor = history.anchor, history = history, enabled = true }
        entries[pid] = entry; revision = revision + 1; pending_enable = nil
        local admitted_revision = revision
        if old then
            old.enabled = false
            cancel_matching(old, "Another scripted screen replaced this action.")
            cancel_entry(old, admitted_revision)
            notify(old, "Another scripted screen replaced this action.")
            attempts[pid] = nil -- New option gets its own retry budget.
            entry.next_poll_ms = 0
        end
        status(entry, "clear", "Waiting for the player launcher.")
        return finish(current(entry), current(entry) and "Scripted screen enabled." or
            "Toggle changed during replacement.")
    end

    function api.Prune()
        if pruning or resetting then return end
        pruning = true
        for pid = 0, 31 do
            local entry = entries[pid]
            if entry then
                same(entry)
            elseif histories[pid] then
                local history = histories[pid]
                local ok, valid = pcall(host.Same, history.anchor)
                if ok and valid == false and histories[pid] == history then histories[pid] = nil end
            end
        end
        pruning = false
    end

    function api.Tick(now)
        if stopped or busy or editing or pruning or resetting then return end
        busy = true
        local ok, detail = pcall(function()
            api.Prune()
            if stopped then return end
            if now == nil then now = clock() end
            if not valid_time(now) then return end
            if last_now and now < last_now then
                for _, entry in pairs(entries) do
                    status(entry, "unavailable", "The repeat clock moved backwards; waiting for it to recover.", last_now)
                end
                return
            end
            last_now = now
            remember_sender()
            sender.Tick(now)
            remember_sender()
            -- Completion supervision does not depend on another sender's
            -- availability or on the five-second launch-attempt cooldown.
            for pid = 0, 31 do
                local history = histories[pid]
                if history then service_cleanup(history, now, revision) end
                if history and not entries[pid] and retired_count(history) > 0
                    and now >= (history.off_poll_ms or 0) then
                    history.off_poll_ms = now + 250
                    local token = revision
                    local ready_ok, ready = pcall(host.Ready, history.anchor)
                    if not stopped and history_current(history, token) and ready_ok and ready == true then
                        local observed, owned = observation(history, token, now)
                        if observed and history_current(history, token) then
                            if observed.active then
                                cleanup_owned(history, owned, token)
                            elseif not sender.Requested() then
                                service_retired(history, now, token)
                            end
                        end
                    end
                end
            end
            if stopped then return end
            local scan_start = cursor
            for offset = 1, 32 do
                local pid = (scan_start + offset) % 32
                local entry = entries[pid]
                local previous = attempts[pid]
                if entry and now >= (entry.next_poll_ms or 0) and same(entry) then
                    entry.next_poll_ms = now + 250
                    local ready_ok, ready = pcall(host.Ready, entry.anchor)
                    if current(entry) and ready_ok and ready == true then
                        local final = clock()
                        if current(entry) and final and final >= now and final >= last_now then
                            last_now = final
                            local token, history = revision, entry.history
                            local observed, owned = observation(history, token, final)
                            if current(entry) and history_current(history, token) then
                                if not observed then
                                    status(entry, "unavailable", "Waiting for the player launcher state.")
                                elseif observed.active then
                                    if owned and owned.kind == entry.kind then
                                        local expired = owned.admitted_ms and
                                            final >= owned.admitted_ms + unconfirmed_after_ms
                                        status(entry, expired and "unconfirmed" or "admitted", expired and
                                            "Screen visibility unconfirmed after 30s. Waiting for the current launch to close before retrying."
                                            or "Launcher accepted; screen visibility is unconfirmed.", final)
                                    else
                                        status(entry, "occupied",
                                            "Another launch occupies the player launcher; waiting for it to close.",
                                            final)
                                    end
                                    service_cleanup(history, final, token, observed, owned)
                                else
                                    local tx = history.transactions[entry.kind]
                                    if tx and not sender.Requested() and tx.first_dispatch_ms then
                                        local began = tx.retry_window_ms or tx.first_dispatch_ms
                                        if final >= began + unconfirmed_after_ms then tx.pending_timeout = true end
                                    end
                                    local paused = tx and tx.pending_timeout and not sender.Requested()
                                    status(entry, paused and "unconfirmed" or tx and "pending" or "clear", paused and
                                        "No launch confirmed after 30s. Retries paused until the launcher changes; toggle off/on to retry."
                                        or tx and "Request sent; waiting for launcher acceptance." or
                                        "Ready; waiting to retry.", final)
                                    -- Observation is independent of transport pacing. Old cancelled
                                    -- IDs are retried separately, never reused for a new intent.
                                    if not sender.Requested() then service_retired(history, final, token) end
                                    if current(entry) and history_current(history, token) then
                                        if tx and tx.pending_timeout and not sender.Requested() then
                                            -- Preserve the unconfirmed boundary and nonce without
                                            -- sending or emitting a pendingâ†’unconfirmed loop.
                                        elseif retired_count(history) >= 6 then
                                            status(entry, "pending", "Waiting for earlier cancelled launches to settle.")
                                        elseif final < (history.handoff_until_ms or 0) then
                                            status(entry, "pending", "Waiting for the previous launch to clean up.")
                                        elseif not sender.Requested() and (not previous or final >= previous + 5000) then
                                            local available, why = sender.Availability(pid, entry.kind, final)
                                            if current(entry) and history_current(history, token) and available then
                                                launching = entry
                                                local accepted, detail = sender.BeginPinned(pid, entry.kind, entry
                                                    .anchor,
                                                    tx and tx.nonce)
                                                launching = nil
                                                if accepted and current(entry) and history_current(history, token) then
                                                    local snapshot = sender.Snapshot()
                                                    if snapshot.player_id == pid and snapshot.kind == entry.kind then
                                                        attempts[pid] = final; cursor = pid
                                                        history.transactions[entry.kind] = tx or {
                                                            kind = entry.kind,
                                                            selector = sender.Selector(entry.kind),
                                                            nonce = snapshot.nonce
                                                        }
                                                        status(entry, "pending", "Launch request queued.")
                                                    end
                                                elseif current(entry) then
                                                    status(entry, "unavailable",
                                                        detail or "Waiting to send the launch request.")
                                                end
                                                -- One admission per scheduler turn; no catch-up burst.
                                                return
                                            elseif current(entry) and why then
                                                status(entry, tx and "pending" or "clear", why)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    elseif current(entry) then
                        status(entry, "unavailable", "Waiting for gameplay and the player connection.")
                    end
                end
            end
        end)
        launching = nil; busy = false
        if not ok then return false, "Scripted screen scheduling failed: " .. tostring(detail) end
        return true
    end

    function api.Snapshot(pid)
        local entry = entries[pid]
        local value = entry and entry.snapshot or {
            player_id = pid,
            enabled = false,
            active = false,
            phase = "off",
            detail = "",
            recipient_confirmed = false
        }
        local result = {}; for key, item in pairs(value) do result[key] = item end
        return result
    end

    function api.Requested()
        if next(entries) ~= nil or sender.Requested() then return true end
        if not stopped then
            for _, history in pairs(histories) do
                if cleanup_debt(history) or retired_count(history) > 0 then return true end
            end
        end
        return false
    end

    function api.Reset(reason)
        if resetting then return true end
        resetting = true; revision = revision + 1; pending_enable = nil
        local removed = entries; entries = {}
        for _, entry in pairs(removed) do entry.enabled = false end
        local token = revision
        sender.Cancel(reason or "Scripted screen repeats reset; remaining sends cancelled.")
        for _, entry in pairs(removed) do
            cancel_entry(entry, token)
            notify(entry, reason or "Scripted screen repeats reset.")
        end
        resetting = false; return true
    end

    function api.Stop(reason)
        stopped = true; revision = revision + 1; pending_enable = nil
        api.Reset(reason or "Player runtime stopped.")
        sender.Stop(reason or "Player runtime stopped.")
        return true
    end

    function api.Rearm()
        if resetting or editing or pruning or busy then return false, "Scripted screen state is changing; retry rearm." end
        stopped = false
        local token = revision + 1
        api.Reset("Runtime rearmed; previous screen toggles cleared.")
        if stopped or revision ~= token then return false, "Rearm was superseded by a newer state change." end
        sender.Rearm()
        if stopped then return false, "Rearm was superseded by a newer stop." end
        return true
    end

    return api
end

-- END SCRIPTED SCREENS55 CONTROLLER

-- Disable Stumble surface assistance. Each velocity request consumes one fresh
-- asynchronous contact; no old normal is used while its next probe is pending.
function Module.NewSlopeMovement(host)
    local api, owner, pending, revision, busy = {}, nil, nil, 0, false
    local function finite(v) return type(v) == "number" and v == v and math.abs(v) < math.huge end
    local function vector(v)
        return type(v) == "table" and finite(v.x) and finite(v.y) and finite(v.z)
            and math.abs(v.x) < 10000000 and math.abs(v.y) < 10000000 and math.abs(v.z) < 10000000
    end
    local function same(a, b)
        return a and b and a.pid == b.pid and a.ped == b.ped and a.address == b.address and a.token == b.token
    end
    local function distance2(a, b)
        return (a.x - b.x) ^ 2 + (a.y - b.y) ^ 2 + (a.z - b.z) ^ 2
    end
    local function input(v)
        return vector(v) and finite(v.dx) and finite(v.dy) and finite(v.speed)
            and v.dx * v.dx + v.dy * v.dy > 0.0001 and v.dx * v.dx + v.dy * v.dy <= 1.0001 and v.speed > 0
    end
    local function copy(o) return { pid = o.pid, ped = o.ped, address = o.address, token = o.token } end
    function api.HasWork() return owner ~= nil or pending ~= nil end
    function api.Stop()
        revision = revision + 1; owner, pending = nil, nil
        if type(host) == "table" and type(host.Release) == "function" then
            local ok, released = pcall(host.Release); return ok and released ~= false
        end
        return true
    end

    function api.Project(n, dx, dy, speed)
        if not vector(n) or not finite(dx) or not finite(dy) or not finite(speed) or speed <= 0 then return nil end
        local length = math.sqrt(n.x * n.x + n.y * n.y + n.z * n.z)
        if length < 0.5 or length > 1.5 then return nil end
        local nx, ny, nz = n.x / length, n.y / length, n.z / length
        -- Positive up-facing normals only: 40..89 degrees, never walls,
        -- ceilings, or the engine's ordinary walkable ground.
        if nz < 0.0174524064372835 - 0.00000001 or nz > 0.766044443118978 + 0.00000001 then return nil end
        local direction = math.sqrt(dx * dx + dy * dy)
        if direction < 0.01 or direction > 1.0001 then return nil end
        dx, dy = dx / direction, dy / direction
        local dot = dx * nx + dy * ny
        local tx, ty, tz = dx - dot * nx, dy - dot * ny, -dot * nz
        local tangent = math.sqrt(tx * tx + ty * ty + tz * tz)
        if tangent < 0.0001 then return nil end
        -- A small inward component maintains collision contact. The complete
        -- request, including that component, stays at or below 8 metres/sec.
        local run = math.min(speed, math.sqrt(64 - 0.15 * 0.15)) / tangent
        local v = { x = tx * run - nx * 0.15, y = ty * run - ny * 0.15, z = tz * run - nz * 0.15 }
        return vector(v) and v or nil
    end

    local function tick(o)
        if type(host) ~= "table" then return api.Stop() end
        for _, name in ipairs({ "Now", "Current", "Read", "Start", "Poll", "Write", "Release" }) do
            if type(host[name]) ~= "function" then return api.Stop() end
        end
        if not o or not finite(o.pid) or o.pid < 0 or o.pid > 31 or o.pid % 1 ~= 0
            or not finite(o.ped) or o.ped <= 0 or o.ped % 1 ~= 0
            or not finite(o.address) or o.address <= 0 or o.token == nil then
            return api.Stop()
        end
        if owner and not same(owner, o) then return api.Stop() end
        local captured, epoch = copy(o), revision
        local function current()
            return revision == epoch and same(captured, o) and host.Current(captured) == true
                and revision == epoch and same(captured, o)
        end
        if not current() then return api.Stop() end
        local now = host.Now()
        local read = host.Read(captured)
        if not finite(now) or not input(read) or not current() then return api.Stop() end
        -- Steep collision can set GTA's falling flag between frames. An
        -- existing probe may confirm that contact, but freefall cannot begin
        -- a new attachment without an earlier admitted on-foot probe.
        if read.falling == true and not pending then return api.Stop() end
        owner = captured
        if pending then
            local p = pending
            if now < p.at or now - p.at > 80 or distance2(read, p) > 1.5625 then return api.Stop() end
            local status, hit, normal = host.Poll(p.handle, captured)
            if not current() then return api.Stop() end
            if status == 1 then return end
            pending = nil
            if status ~= 2 or not vector(hit) or distance2(hit, read) > 2.7225 then return api.Stop() end
            -- Poll/native callbacks may change input, identity, or control.
            -- Re-read the state and use the present movement intent to project.
            local fresh = host.Read(captured)
            local fresh_now = host.Now()
            if not input(fresh) or not finite(fresh_now) or fresh_now < p.at or fresh_now - p.at > 80
                or distance2(fresh, p) > 1.5625 or distance2(fresh, read) > 0.1225
                or distance2(hit, fresh) > 2.7225 or not current() then
                return api.Stop()
            end
            local velocity = api.Project(normal, fresh.dx, fresh.dy, fresh.speed)
            if not velocity or not current() or host.Write(captured, velocity, fresh, current) ~= true or not current() then
                return
                    api.Stop()
            end
            read, now = fresh, fresh_now
        end
        if not current() then return api.Stop() end
        local handle = host.Start(captured, read)
        if not finite(handle) or handle <= 0 or handle % 1 ~= 0 or not current() then return api.Stop() end
        pending = { handle = handle, at = now, x = read.x, y = read.y, z = read.z }
    end
    function api.Tick(o)
        if busy then return end
        busy = true
        local ok = pcall(tick, o)
        busy = false
        if not ok then api.Stop() end
    end

    return api
end

local function create_player_system(deps)
    local log_info = require_binding("log_info", deps.log_info)
    local toast = require_binding("toast", deps.toast)
    local invoke_void = require_binding("invoke_void", deps.invoke_void)
    local invoke_void_detail = require_binding("invoke_void_detail", deps.invoke_void_detail)
    local invoke_int = require_binding("invoke_int", deps.invoke_int)
    local invoke_int_detail = require_binding("invoke_int_detail", deps.invoke_int_detail)
    local invoke_bool = require_binding("invoke_bool", deps.invoke_bool)
    local invoke_bool_detail = require_binding("invoke_bool_detail", deps.invoke_bool_detail)
    local invoke_float_detail = require_binding("invoke_float_detail", deps.invoke_float_detail)
    local invoke_vec3 = require_binding("invoke_vec3", deps.invoke_vec3)
    local vector_components = require_binding("vector_components", deps.vector_components)
    local now_ms = require_binding("now_ms", deps.now_ms)
    local local_player_id = require_binding("local_player_id", deps.local_player_id)
    local local_ped = require_binding("local_ped", deps.local_ped)
    local entity_exists = require_binding("entity_exists", deps.entity_exists)
    local player_available = require_binding("player_available", deps.player_available)
    local player_name = require_binding("player_name", deps.player_name)
    local player_ped = require_binding("player_ped", deps.player_ped)
    local player_snapshot = require_binding("player_snapshot", deps.player_snapshot)
    local feature_id = require_binding("feature_id", deps.feature_id)
    local H = require_binding("H", deps.H)
    local feature_mgr = require_binding("FeatureMgr", deps.FeatureMgr)
    local feature_type = require_binding("eFeatureType", deps.eFeatureType)
    local utils = require_binding("Utils", deps.Utils)
    local imgui = deps.ImGui
    local memory = deps.Memory
    local gta = deps.GTA
    local pool_mgr = deps.PoolMgr
    local sync_node_type = deps.eSyncDataNode
    local script_global = deps.ScriptGlobal
    local Live = {
        Players = deps.Players,
        owned_player_hashes = {},
        V3 = deps.V3,
        ExplosionArgs = deps.CExplosionArgs,
        ExplosionTag = deps.eExplosionTag,
        REMOTE_GHOST_WINDOW_MS = 5000,
        REMOTE_PASSIVE_WINDOW_MS = 5000,
        GHOST_TIMER_BASE = 1950683,
        GHOST_TIMER_STRIDE = 5,
        GHOST_TIMER_FLAG_OFFSET = 3,
        PASSIVE_BASE = 1893070,
        PASSIVE_STRIDE = 615,
        PASSIVE_OFFSET = 8,
        PROPERTY_BASE = 1845347,
        PROPERTY_STRIDE = 884,
        PROPERTY_OFFSET = 260 + 39,
        PLAYER_BD_BASE = 2658296,
        PLAYER_BD_STRIDE = 468,
        SIMPLE_GROUP_FLAGS_OFFSET = 325 + 3,
        SIMPLE_INDEX_OFFSET = 325 + 8,
        SIMPLE_INSTANCE_OFFSET = 325 + 9,
        SIMPLE_OWNER_OFFSET = 325 + 11,
        SIMPLE_SUBTYPE_OFFSET = 325 + 29,
        PROPERTY_INVITE_EVENT = -1321657966,
        SIMPLE_INTERIOR_EVENT = -1638522928,
        KICK_INTERIOR_EVENT = -1496371358,
        ORG_BASE = 1893070,
        ORG_STRIDE = 615,
        ORG_ROOT_OFFSET = 10,
        ORG_GOONS_OFFSET = 12,
        ORG_GOON_COUNT = 7,     -- active member slots, excluding the boss
        ORG_ROSTER_STORAGE = 8, -- stored array capacity; NOT an eighth member
        ORG_JOIN_REQUESTS_OFFSET = 21,
        ORG_JOINING_BOSS_OFFSET = 27,
        ORG_JOIN_REQUEST_EVENT = -627920584,
        ORG_DISMISS_EVENT = -11681548, -- current three-cell CeoKick; no sender spoof
        SCRIPTED_SCREEN_BEGIN_EVENT = 1541018842,
        SCRIPTED_SCREEN_ACK_EVENT = 1757622014,
        action_generation = 0,
        INVITE_CONTEXT_PROPERTY = 2733326 + 476 + 4,
        ENTRY_CONTEXT_PROPERTY = 1844984 + 19,
    }

    if not fast_respawn_delay then
        fast_respawn_host = new_fast_respawn_delay_host(deps)
        fast_respawn_delay = new_fast_respawn_delay(fast_respawn_host)
    end

    Live.online_version = deps.invoke_string
    Live.source_catalog = module_context and module_context.EnhancedMetadata
    if Live.source_catalog then
        Live.ORG_BASE = Live.source_catalog.organization.base
        Live.ORG_STRIDE = Live.source_catalog.organization.stride
        Live.ORG_ROOT_OFFSET = Live.source_catalog.organization.root
        Live.ORG_GOONS_OFFSET = Live.source_catalog.organization.goons
        Live.ORG_ROSTER_STORAGE = Live.source_catalog.organization.storage_slots
        Live.ORG_GOON_COUNT = Live.source_catalog.organization.active_member_slots
        Live.ORG_JOINING_BOSS_OFFSET = Live.source_catalog.organization.joining_boss
        Live.ORG_DISMISS_EVENT = Live.source_catalog.events.kick_organization.id
        Live.ORG_JOIN_REQUEST_EVENT = Live.source_catalog.events.join_organization.id
        Live.PROPERTY_BASE = Live.source_catalog.property.base
        Live.PROPERTY_STRIDE = Live.source_catalog.property.stride
        Live.PROPERTY_OFFSET = Live.source_catalog.property.index
        Live.PLAYER_BD_BASE = Live.source_catalog.simple_interior.base
        Live.PLAYER_BD_STRIDE = Live.source_catalog.simple_interior.stride
        Live.SIMPLE_GROUP_FLAGS_OFFSET = Live.source_catalog.simple_interior.flags
        Live.SIMPLE_INDEX_OFFSET = Live.source_catalog.simple_interior.index
        Live.SIMPLE_INSTANCE_OFFSET = Live.source_catalog.simple_interior.instance
        Live.SIMPLE_OWNER_OFFSET = Live.source_catalog.simple_interior.owner
        Live.SIMPLE_SUBTYPE_OFFSET = Live.source_catalog.simple_interior.subtype
        Live.PROPERTY_INVITE_EVENT = Live.source_catalog.events.enter_property.id
        Live.SIMPLE_INTERIOR_EVENT = Live.source_catalog.events.enter_simple.id
        Live.KICK_INTERIOR_EVENT = Live.source_catalog.events.kick_interior.id
        Live.SCRIPTED_SCREEN_BEGIN_EVENT = Live.source_catalog.events.scripted_screen_begin.id
        Live.SCRIPTED_SCREEN_ACK_EVENT = Live.source_catalog.events.scripted_screen_ack.id
    end

    function Live.script_globals_ready()
        if not script_global or type(script_global.AreValid) ~= "function"
            or type(script_global.GetInt) ~= "function" then
            return false
        end
        local ok, ready = pcall(script_global.AreValid)
        return ok and ready == true
    end

    function Live.read_global_int(index)
        if not Live.script_globals_ready() then return nil end
        local ok, value = pcall(script_global.GetInt, index)
        return ok and type(value) == "number" and value == value and value % 1 == 0
            and value >= -2147483648 and value <= 4294967295 and value or nil
    end

    function Live.write_global_int(index, value)
        if not Live.script_globals_ready() or type(script_global.SetInt) ~= "function" then return false end
        local ok = pcall(script_global.SetInt, index, math.floor(tonumber(value) or 0))
        return ok and Live.read_global_int(index) == math.floor(tonumber(value) or 0)
    end

    function Live.entity_network_state(entity)
        if not entity_exists(entity) or not gta or type(gta.HandleToPointer) ~= "function" then
            return nil, nil
        end
        local ok, owner, pending = pcall(function()
            local physical = gta.HandleToPointer(entity)
            local net_object = physical and physical.NetObject or nil
            if not net_object then return nil, nil end
            return tonumber(net_object.PlayerId), tonumber(net_object.PendingPlayerId)
        end)
        if not ok then return nil, nil end
        owner, pending = tonumber(owner), tonumber(pending)
        if owner and owner >= 0 and owner <= 31 then owner = math.floor(owner) else owner = nil end
        if pending and pending >= 0 and pending <= 31 then pending = math.floor(pending) else pending = nil end
        return owner, pending
    end

    function Live.entity_network_owner(entity)
        local owner = Live.entity_network_state(entity)
        return owner
    end

    -- Control reads require an actual native BOOL. Owner metadata can lag and
    -- cannot substitute for local authority.
    function Live.control_bool(hash, ...)
        local ok, value, raw, err = pcall(invoke_bool_detail, hash, ...)
        if not ok or err ~= nil or (raw ~= true and raw ~= false and raw ~= 0 and raw ~= 1) then return nil end
        return value == true
    end

    function Live.control_int(hash, ...)
        local ok, value, raw, err = pcall(invoke_int_detail, hash, ...)
        if not ok or err ~= nil or type(value) ~= "number" or value % 1 ~= 0
            or type(raw) ~= "number" or raw % 1 ~= 0 or value ~= raw then
            return nil
        end
        return value
    end

    function Live.give_entity_control(player_id, entity, validity)
        local function current()
            if validity == nil then return true end
            local ok, value = pcall(validity)
            return ok and value == true
        end
        player_id = tonumber(player_id)
        if not player_id or not entity_exists(entity) or not gta
            or type(gta.GiveControl) ~= "function" then
            return false
        end
        if not current() then return false end
        local ok = pcall(gta.GiveControl, math.floor(player_id), entity)
        if not ok or not current() then return false end
        local verified
        if math.floor(player_id) == math.floor(tonumber(local_player_id()) or -1) then
            verified = Live.control_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity) == true
        else
            verified = Live.entity_network_owner(entity) == math.floor(player_id)
        end
        return current() and verified
    end

    -- Cherax's documented GTA.GiveControl path is the only forced migration API
    -- used here. NetworkObjectMgr.ChangeOwner is deliberately excluded because
    -- its migration-type contract is undocumented and a guessed host call can
    -- fail-fast Cherax instead of returning a Lua error.
    function Live.request_entity_control(player_id, entity, validity)
        -- Each migration path retains the caller's physical/connection fence.
        local function current()
            if validity == nil then return true end
            local ok, value = pcall(validity)
            return ok and value == true
        end
        player_id = tonumber(player_id)
        if not player_id or player_id % 1 ~= 0 or player_id < 0 or player_id > 31
            or not entity_exists(entity) or not current() then
            return false, nil, nil
        end
        local local_id = tonumber(local_player_id())
        if not local_id or local_id % 1 ~= 0 or local_id < 0 or local_id > 31 or not current() then
            return false, nil,
                nil
        end
        local local_target = player_id == local_id
        local detail = { entity_request = false, network_id_request = false, give_control = false }
        local function has_local_control()
            return current() and Live.control_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity) == true and current()
        end
        if local_target and has_local_control() then
            local owner, pending = Live.entity_network_state(entity)
            return current(), owner, pending, detail
        end
        if not current() then return false, nil, nil, detail end
        detail.entity_request = true
        detail.entity_request_accepted = Live.control_bool(H.NETWORK_REQUEST_CONTROL_OF_ENTITY, entity)
        if not current() then return false, nil, nil, detail end
        -- NetObject.ObjectID is only an identity token. Ask the native for its
        -- own network-ID representation and reverse-map it before requesting.
        if local_target and not has_local_control() and current()
            and Live.control_bool(0xC7827959479DCC78, entity) == true and current() then
            local netid = Live.control_int(0xA11700682F3AD45C, entity)
            if netid and netid > 0 and current() then
                local mapped = Live.control_int(0xCE4E5D9B0A4FF560, netid)
                if mapped == entity and current() then
                    detail.network_id_request = true
                    detail.network_id_request_accepted = Live.control_bool(0xA670B3662FAFFBD0, netid)
                end
            end
        end
        if not current() then return false, nil, nil, detail end
        if not local_target or not has_local_control() then
            if not current() then return false, nil, nil, detail end
            detail.give_control = true
            Live.give_entity_control(player_id, entity, validity)
        end
        if not current() then return false, nil, nil, detail end
        local owner, pending = Live.entity_network_state(entity)
        if not current() then return false, nil, nil, detail end
        local verified
        if local_target then
            verified = has_local_control()
        else
            verified = owner == player_id
        end
        detail.control_observed = verified == true
        return current() and verified == true, owner, pending, detail
    end

    -- Lester's scene shares the main scheduler; this module owns its controls.
    do
        local scene_module = module_context.Modules.LesterRide
        if type(scene_module) ~= "table" or type(scene_module.New) ~= "function" then
            error("CScript Lester ride module is unavailable")
        end
        local scene_deps = {}
        for key, value in pairs(deps) do scene_deps[key] = value end
        scene_deps.request_entity_control = Live.request_entity_control
        scene_deps.entity_network_owner = Live.entity_network_owner
        Live.lester_ride = scene_module.New(scene_deps)
    end

    local function feature_ref(key)
        if F[key] then return F[key] end
        if type(feature_mgr.GetFeature) == "function" then
            local ok, feature = pcall(feature_mgr.GetFeature, feature_id(key))
            if ok then return feature end
        end
        return nil
    end

    local function is_on(key)
        local feature =
            feature_ref(key)

        if feature
            and type(feature.IsToggled) == "function" then
            local ok, enabled =
                pcall(
                    feature.IsToggled,
                    feature
                )

            if ok then
                if F[key] then
                    ToggleState[key] =
                        enabled == true
                end

                return enabled == true
            end
        end

        return F[key] ~= nil
            and ToggleState[key] == true
    end

    local function set_toggle(key, enabled)
        local feature =
            feature_ref(key)

        if not feature
            or type(feature.IsToggled) ~= "function"
            or type(feature.Toggle) ~= "function" then
            return false
        end

        local wanted =
            enabled == true

        local read_ok, current =
            pcall(
                feature.IsToggled,
                feature
            )

        if not read_ok then
            return false
        end

        if (current == true) ~= wanted then
            local toggle_ok =
                pcall(
                    feature.Toggle,
                    feature,
                    wanted
                )

            if not toggle_ok then
                return false
            end
        end

        local verify_ok, observed =
            pcall(
                feature.IsToggled,
                feature
            )

        if not verify_ok
            or (observed == true) ~= wanted then
            return false
        end

        if F[key] then
            ToggleState[key] =
                wanted
        end

        return true
    end

    local function slider_int(key, fallback)
        local feature = feature_ref(key)
        if not feature then return fallback end
        local ok, value = pcall(function() return feature:GetIntValue() end)
        return ok and type(value) == "number" and value or fallback
    end

    local function slider_float(key, fallback)
        local feature = feature_ref(key)
        if not feature then return fallback end
        local ok, value = pcall(function() return feature:GetFloatValue() end)
        return ok and type(value) == "number" and value or fallback
    end


    local function add_toggle(key, name, description, default, callback)
        ToggleState[key] = default == true
        local function on_toggle(feature)
            local ok, enabled = pcall(function() return feature:IsToggled() end)
            if ok then ToggleState[key] = enabled == true end
            if callback then callback(feature) end
        end
        local feature = feature_mgr.AddFeature(
            feature_id(key), name, feature_type.Toggle, description or "", on_toggle
        )
        if feature and type(feature.SetDefaultValue) == "function" then
            pcall(function()
                feature:SetDefaultValue(default == true)
                if default == true and type(feature.Toggle) == "function" and not feature:IsToggled() then
                    feature:Toggle(true)
                end
            end)
        end
        F[key] = feature

        if feature then
            local ok, enabled =
                pcall(function()
                    return feature:IsToggled()
                end)

            if ok then
                ToggleState[key] =
                    enabled == true
            end

            State.registered_count =
                State.registered_count + 1
        end

        return feature
    end

    local function add_button(key, name, description, callback)
        local feature = feature_mgr.AddFeature(
            feature_id(key), name, feature_type.Button, description or "", callback
        )
        F[key] = feature

        if feature then
            State.registered_count =
                State.registered_count + 1
        end

        return feature
    end

    local function add_slider_int(key, name, description, minimum, maximum, step, default)
        local feature = feature_mgr.AddFeature(
            feature_id(key), name, feature_type.SliderInt, description or ""
        )
        if feature then
            pcall(function()
                local initial = default or minimum
                feature:SetLimitValues(minimum, maximum)
                feature:SetStepSize(step or 1)
                feature:SetDefaultValue(initial)
                if type(feature.SetIntValue) == "function" then feature:SetIntValue(initial) end
            end)
        end
        F[key] = feature

        if feature then
            State.registered_count =
                State.registered_count + 1
        end

        return feature
    end

    local function add_slider_float(key, name, description, minimum, maximum, step, default)
        local feature = feature_mgr.AddFeature(
            feature_id(key), name, feature_type.SliderFloat, description or ""
        )
        if feature then
            pcall(function()
                local initial = default or minimum
                feature:SetLimitValues(minimum, maximum)
                feature:SetStepSize(step or 0.1)
                feature:SetDefaultValue(initial)
                if type(feature.SetFloatValue) == "function" then feature:SetFloatValue(initial) end
            end)
        end
        F[key] = feature
        if feature then
            State.registered_count = State.registered_count + 1
        end
        return feature
    end


    local function player_feature_id(key)
        if not PF_ID[key] then PF_ID[key] = feature_id("selected_player_" .. tostring(key)) end
        return PF_ID[key]
    end

    local function feature_player_id(feature)
        if feature and type(feature.GetPlayerIndex) == "function" then
            local ok, value = pcall(feature.GetPlayerIndex, feature)
            if ok then return tonumber(value) end
        end
        return nil
    end

    local selected_feature_keys = {}
    -- Preserve the exact display text successfully registered with Cherax.
    -- This is the same text the enabled native feature renderer displays.
    local selected_feature_labels = {}
    local function remember_selected_feature(key, hash, features, name)
        if type(name) == "string" and name ~= "" then
            selected_feature_labels[key] = name
        end
        -- The bootstrap accepts both Lua tables and Cherax userdata collections.
        -- Keep the base hash even when the collection has no Lua pairs iterator.
        Live.owned_player_hashes[hash] = true
        pcall(function()
            for _, entry in pairs(features) do
                if type(entry) == "number" then Live.owned_player_hashes[entry] = true end
            end
        end)
        for _, existing in ipairs(selected_feature_keys) do if existing == key then return end end
        if #selected_feature_keys == 0 then
            pcall(log_info, "Selected-player registry accepted " .. type(features) .. " hash collection")
        end
        selected_feature_keys[#selected_feature_keys + 1] = key
    end
    local function add_player_button(key, name, description, callback)
        local hash = player_feature_id(key)

        local ok, features = pcall(
            feature_mgr.AddPlayerFeature,
            hash,
            name,
            feature_type.Button,
            description or "",
            callback,
            true
        )

        if not ok
            or (type(features) ~= "table" and type(features) ~= "userdata")
            or (type(features) == "table" and next(features) == nil) then
            return nil
        end

        State.registered_count =
            State.registered_count + 1

        remember_selected_feature(key, hash, features, name)
        return hash
    end

    local function add_player_toggle(key, name, description, callback)
        local hash = player_feature_id(key)

        local ok, features = pcall(
            feature_mgr.AddPlayerFeature,
            hash,
            name,
            feature_type.Toggle,
            description or "",
            callback,
            true
        )

        if not ok
            or (type(features) ~= "table" and type(features) ~= "userdata")
            or (type(features) == "table" and next(features) == nil) then
            return nil
        end

        State.registered_count =
            State.registered_count + 1

        remember_selected_feature(key, hash, features, name)
        return hash
    end

    local function stop_spectating(quiet)
        if State.spectate_target >= 0 and State.spectate_ped ~= 0 then
            invoke_void(H.NETWORK_SET_IN_SPECTATOR_MODE, false, State.spectate_ped)
        end
        local was_active = State.spectate_target >= 0
        State.spectate_target = -1
        State.spectate_ped = 0
        if was_active and not quiet then toast("Local spectator mode stopped.") end
    end

    -- Local protection ownership. Studio leases and the user toggle share one
    -- snapshot so closing a studio cannot remove a concurrently enabled Godmode.
    Live.protection = { studios = {}, entity = nil, player = nil }
    function Live.local_owner(allow_stopped)
        if not allow_stopped and (not started or not lifecycle_token or not lifecycle_token.alive) then return nil end
        if not (gta and type(gta.GetLocalPed) == "function" and type(gta.HandleToPointer) == "function") then return nil end
        local pid, ped = local_player_id(), local_ped()
        if type(pid) ~= "number" or pid < 0 or pid > 31 or pid % 1 ~= 0 or not entity_exists(ped) then return nil end
        local ok, ptr, address, mapped = pcall(function()
            local p = gta.GetLocalPed()
            return p, p:GetAddress(), gta.HandleToPointer(ped):GetAddress()
        end)
        if not ok or type(address) ~= "number" or address <= 0 or address >= math.huge or address ~= mapped
            or local_ped() ~= ped or local_player_id() ~= pid
            or (not allow_stopped and (not started or not lifecycle_token or not lifecycle_token.alive)) then
            return nil
        end
        return { pid = pid, ped = ped, address = address, ptr = ptr, token = lifecycle_token }
    end

    function Live.same_local_owner(owner, allow_stopped)
        if not owner then return false end
        local fresh = Live.local_owner(allow_stopped)
        return fresh and fresh.pid == owner.pid and fresh.ped == owner.ped and fresh.address == owner.address
            and fresh.token == owner.token
    end

    function Live.protection_bool(hash, ...)
        local _, raw, err = invoke_bool_detail(hash, ...)
        if err ~= nil then return nil end
        if type(raw) == "boolean" then return raw end
        if type(raw) == "number" and raw == raw and math.abs(raw) < math.huge and raw % 1 == 0 then return raw ~= 0 end
        return nil
    end

    function Live.restore_protection(allow_stopped)
        local s = Live.protection
        local o = s.entity
        -- SET_PLAYER_INVINCIBLE belongs to a player slot; never restore it via
        -- a reused ped alias, a new lifecycle token or a different local player.
        local p = s.player
        if p and (local_player_id() ~= p.pid or lifecycle_token ~= p.token) then
            s.player = nil; p = nil
        end
        if p and p.owned and (allow_stopped or (started and lifecycle_token and lifecycle_token.alive)) then
            if invoke_void(H.SET_PLAYER_INVINCIBLE, p.pid, p.original)
                and Live.protection_bool(H.GET_PLAYER_INVINCIBLE, p.pid) == p.original then
                p.owned = false
            end
        end
        if o and Live.same_local_owner(o, allow_stopped) then
            -- Player invincibility can also modify the ped bits. Restore those
            -- snapshots after the player setter, including pre-existing immunity.
            if o.inv_owned and Live.same_local_owner(o, allow_stopped) then
                if invoke_void(H.SET_ENTITY_INVINCIBLE, o.ped, o.invincible) and Live.same_local_owner(o, allow_stopped) then
                    local ok, current = pcall(function() return gta.GetLocalPed():IsInvincible() end)
                    if ok and current == o.invincible then o.inv_owned = false end
                end
            end
            if o.damage_owned and Live.same_local_owner(o, allow_stopped) then
                if invoke_void(H.SET_ENTITY_CAN_BE_DAMAGED, o.ped, o.damageable)
                    and Live.protection_bool(H.GET_ENTITY_CAN_BE_DAMAGED, o.ped) == o.damageable then
                    o.damage_owned = false
                end
            end
            if o.proofs_owned and o.proofs_before and Live.same_local_owner(o,allow_stopped) then
                -- Read current proof bits, restore ONLY the six changes still
                -- matching our applied tuple. Preserve collisionProof (No Ragdoll
                -- owns it independently) and other scripts' later changes.
                local current=Live.read_ragdoll_proofs(o,allow_stopped)
                if current then
                    local next_bits={}
                    for i=1,8 do next_bits[i]=current[i] end
                    local modified=false
                    for _,i in ipairs({1,2,3,5,6,8}) do
                        if current[i]==true and o.proofs_before[i]~=true then
                            next_bits[i]=o.proofs_before[i]
                            modified=true
                        end
                    end
                    if not modified or (Live.same_local_owner(o,allow_stopped)
                        and invoke_void(H.SET_ENTITY_PROOFS,o.ped,table.unpack(next_bits))==true) then
                        o.proofs_owned=nil
                        o.proofs_before=nil
                    end
                end
            end
            if p and p.owned then
                -- A retry of the player setter can touch the ped invincibility
                -- bit again, so retain that baseline until both layers finish.
                o.inv_owned = true
            elseif not o.inv_owned and not o.damage_owned and not o.proofs_owned then
                s.entity = nil
            end
        elseif o then
            local fresh = Live.local_owner(allow_stopped)
            if fresh or lifecycle_token ~= o.token then s.entity = nil end
        end
        if p and not p.owned then s.player = nil end
        if not s.entity and not s.player then State.godmode_ped, State.godmode_last_check = 0, -100000 end
        return not s.entity and not s.player
    end

    function Live.protection_tick()
        local s = Live.protection
        if s.retiring then return Live.restore_protection(true) end
        local godmode = not s.stop_requested and is_on("godmode")
        if not godmode and next(s.studios) == nil then return Live.restore_protection() end
        local o = Live.local_owner()
        if not o then return false end
        local playing = Live.protection_bool(0x5E9564D8246B909A, o.pid)
        local dead = Live.protection_bool(H.IS_PED_DEAD_OR_DYING, o.ped, true)
        if not Live.same_local_owner(o) then return false end
        if playing ~= true or dead ~= false then
            s.studios = {}
            if not godmode then Live.restore_protection() end
            return false
        end
        -- Temporary studio leases cannot migrate onto a replacement character.
        if s.entity and (s.entity.ped ~= o.ped or s.entity.address ~= o.address or s.entity.token ~= o.token) then
            s.studios = {}; s.entity = nil
            if not godmode then
                Live.restore_protection(); return false
            end
        end
        if not s.entity then
            local ok, inv = pcall(function() return o.ptr:IsInvincible() end)
            local damage = Live.protection_bool(H.GET_ENTITY_CAN_BE_DAMAGED, o.ped)
            if not ok or type(inv) ~= "boolean" or damage == nil or not Live.same_local_owner(o) then return false end
            o.invincible, o.damageable = inv, damage
            o.inv_owned, o.damage_owned = false, false
            s.entity = o
        end
        if not s.player then
            local before = Live.protection_bool(H.GET_PLAYER_INVINCIBLE, o.pid)
            if before == nil or not Live.same_local_owner(o) then return false end
            s.player = { pid = o.pid, token = o.token, original = before, owned = false }
        end
        local function wanted()
            return ((not s.stop_requested and is_on("godmode")) or next(s.studios) ~= nil) and Live.same_local_owner(o)
        end
        -- Reassert the entire tuple every eligible frame. GET_PLAYER_INVINCIBLE
        -- alone stays true during some same-handle respawns while ped flags reset.
        local entity, player = s.entity, s.player
        local player_ok, inv_ok, damage_ok = false, false, false
        if wanted() then player_ok = invoke_void(H.SET_PLAYER_INVINCIBLE, o.pid, true) == true end
        if player_ok then player.owned = not player.original end
        if wanted() then inv_ok = invoke_void(H.SET_ENTITY_INVINCIBLE, o.ped, true) == true end
        if inv_ok then entity.inv_owned = true end
        if wanted() then damage_ok = invoke_void(H.SET_ENTITY_CAN_BE_DAMAGED, o.ped, false) == true end
        if damage_ok then entity.damage_owned = true end
        State.godmode_ped, State.godmode_last_check = o.ped, now_ms()
        local read, inv = pcall(function() return gta.GetLocalPed():IsInvincible() end)
        local damage = Live.protection_bool(H.GET_ENTITY_CAN_BE_DAMAGED, o.ped)
        -- Invincibility flags alone can be cleared by exceptional damage
        -- contexts. Use a reversible proof tuple for supported bullet, fire,
        -- explosion, melee, steam and drowning damage. Collision stays as-is,
        -- so movement and No Ragdoll keep their own collision behavior.
        if godmode and wanted() and Live.same_local_owner(o) then
            local proofs=Live.read_ragdoll_proofs(entity)
            if proofs then
                if not entity.proofs_before then
                    entity.proofs_before={}
                    for i=1,8 do entity.proofs_before[i]=proofs[i] end
                end
                local desired={}
                for i=1,8 do desired[i]=proofs[i] end
                local write_needed=false
                for _,i in ipairs({1,2,3,5,6,8})do
                    if proofs[i]~=true then desired[i]=true;write_needed=true end
                end
                if write_needed and Live.same_local_owner(o)
                    and invoke_void(H.SET_ENTITY_PROOFS,o.ped,table.unpack(desired))==true then
                    local verified=Live.read_ragdoll_proofs(entity)
                    local all=true
                    for _,i in ipairs({1,2,3,5,6,8})do
                        if not verified or verified[i]~=true then all=false;break end
                    end
                    if all then entity.proofs_owned=true end
                end
            end
        end
        return player_ok and inv_ok and damage_ok and read and inv == true and damage == false and wanted()
    end

    function Live.acquire_studio_safety(owner)
        if owner ~= "outfit" and owner ~= "vehicle" then return false end
        if Live.protection.retiring or Live.protection.stop_requested then return false end
        if not Live.local_owner() then return false end
        Live.protection.studios[owner] = true
        if Live.protection_tick() then return true end
        Live.protection.studios[owner] = nil
        if (Live.protection.stop_requested or not is_on("godmode")) and next(Live.protection.studios) == nil then
            Live
                .restore_protection()
        end
        return false
    end

    function Live.release_studio_safety(owner, allow_stopped)
        Live.protection.studios[owner] = nil
        if (Live.protection.stop_requested or not is_on("godmode")) and next(Live.protection.studios) == nil then
            return
                Live.restore_protection(allow_stopped)
        end
        return Live.protection_tick()
    end

    function Live.clear_protection(allow_stopped, retire)
        if retire then Live.protection.retiring = true end
        Live.protection.studios = {}
        return Live.restore_protection(allow_stopped)
    end

    local function set_local_godmode(enabled, force)
        -- The feature callback has already updated its toggle state.
        return Live.protection_tick()
    end

