    local SET_CAM_COORD = H.SET_CAM_COORD or 0x4D41783FB745E42E
    local SET_CAM_FOV = H.SET_CAM_FOV or 0xB13C14F66A00D047
    local PREVIEW_FRONT_HEADING = 180.0
    local PREVIEW_ROTATION_RATE = 105.0
    local PREVIEW_ZOOM_RATE = 1.65
    local PREVIEW_DISTANCE_MIN = 1.35
    local PREVIEW_DISTANCE_MAX = 5.50
    local PREVIEW_FOV_MIN = 26.0
    local PREVIEW_FOV_MAX = 42.0
    local PREVIEW_VIEWS = {
        front = 0.0, right = 90.0, back = 180.0, left = 270.0,
    }
    local PREVIEW_FRAMING = {
        face = { distance = 1.48, height = 1.55, look = 1.55, fov = 30.0 },
        upper = { distance = 2.20, height = 1.18, look = 1.15, fov = 31.0 },
        full = { distance = 3.25, height = 0.95, look = 0.85, fov = 32.0 },
        legs = { distance = 2.45, height = 0.62, look = 0.62, fov = 31.0 },
        shoes = { distance = 2.45, height = 0.28, look = 0.30, fov = 31.0 },
    }
    local GET_PED_BONE_COORDS = 0x17C07FC640E86B4E
    local PED_BONES = {
        head = 0x796E,
        neck = 0x9995,
        spine = 0x60F2,
        pelvis = 0x2E28,
        left_foot = 0x3779,
        right_foot = 0xCC4D,
    }
    local CATEGORY_FRAMING = {
        Head = "face",
        Masks = "face",
        Hair = "face",
        Hats = "face",
        Glasses = "face",
        Ears = "face",
        Torso = "upper",
        Accessories = "upper",
        Undershirts = "upper",
        ["Body Armor"] = "upper",
        Decals = "upper",
        Tops = "upper",
        Watches = "upper",
        Bracelets = "upper",
        Legs = "legs",
        Shoes = "shoes",
        ["Bags / Parachutes"] = "upper",
    }

    local function clamp(value, minimum, maximum)
        return math.max(minimum, math.min(maximum, tonumber(value) or minimum))
    end

    local function framing_distance(span, fov, margin)
        span = math.max(0.25, tonumber(span) or 1.0)
        fov = clamp(fov, PREVIEW_FOV_MIN, PREVIEW_FOV_MAX)
        return clamp((span * 0.5) / math.max(0.05, math.tan(math.rad(fov * 0.5)))
            * (tonumber(margin) or 1.18), PREVIEW_DISTANCE_MIN, PREVIEW_DISTANCE_MAX)
    end

    local function outfit_camera_pose(editor)
        local viewport = type(editor.viewport) == "table" and editor.viewport or {}
        local center, center_y, aspect = tonumber(viewport.center_x), tonumber(viewport.center_y),
            tonumber(viewport.aspect)
        if not center or center ~= center or math.abs(center) == math.huge then center = 0.5 end
        if not center_y or center_y ~= center_y or math.abs(center_y) == math.huge then center_y = 0.5 end
        if not aspect or aspect ~= aspect or aspect <= 0 or aspect == math.huge then aspect = 16 / 9 end
        center, center_y, aspect = clamp(center, 0.05, 0.95), clamp(center_y, 0.05, 0.95), clamp(aspect, 0.5, 4)
        local yaw = math.rad(tonumber(editor.current_yaw) or 0)
        local pitch = math.rad(clamp(editor.orbit_pitch or 0, -65, 65))
        local fit = math.max(1 / clamp(viewport.height_fraction or 1, 0.25, 1),
            0.5 / (clamp(viewport.width_fraction or 1, 0.25, 1) * aspect))
        local radius = editor.current_distance * fit
        local distance = radius * math.cos(pitch)
        local vertical = radius * math.sin(pitch)
        local rise = editor.current_height - editor.current_look_height + vertical
        local depth = math.sqrt(distance * distance + rise * rise)
        -- Keep the eye on the selected subject orbit. Pan its look direction
        -- to place the subject in the uncovered region, with pitch corrected
        -- to retain the vertical midpoint. For projected horizontal tangent t,
        -- sin(pan)=t*depth/(distance*sqrt(1+t*t)).
        local half_fov = math.tan(math.rad(editor.current_fov * 0.5))
        local tangent = (0.5 - center) * 2 * half_fov * aspect
        local tangent_y = (0.5 - center_y) * 2 * half_fov
        local pan_sin = clamp(tangent * depth / (distance * math.sqrt(1 + tangent * tangent + tangent_y * tangent_y)),
            -0.9999, 0.9999)
        local pan_cos = math.sqrt(1 - pan_sin * pan_sin)
        local lateral, forward = distance * pan_sin, distance * (pan_cos - 1)
        editor.view_bias = lateral
        local x, y = editor.preview_anchor.x, editor.preview_anchor.y
        local z = editor.preview_anchor.z + editor.current_height + vertical
        local look_pitch = math.atan(-rise, distance * pan_cos) - math.atan(tangent_y)
        return x + math.sin(yaw) * distance, y - math.cos(yaw) * distance, z,
            x + math.cos(yaw) * lateral - math.sin(yaw) * forward,
            y + math.sin(yaw) * lateral + math.cos(yaw) * forward, z + distance * math.tan(look_pitch)
    end

    local function refresh_outfit_framing_metrics(editor, ped)
        ped = tonumber(ped) or tonumber(editor.preview_ped) or 0
        if not entity_exists(ped) then return false end
        local coords = invoke_vec3(H.GET_ENTITY_COORDS, ped, false)
        local _, _, base_z = vector_components(coords)
        base_z = tonumber(base_z)
        if not base_z then return false end
        local function bone_height(bone, fallback)
            local position = invoke_vec3(GET_PED_BONE_COORDS, ped, bone, 0.0, 0.0, 0.0)
            local _, _, z = vector_components(position)
            z = tonumber(z)
            if not z or z ~= z or math.abs(z - base_z) > 4.0 then return fallback end
            return z - base_z
        end
        local head = bone_height(PED_BONES.head, 1.68)
        local neck = bone_height(PED_BONES.neck, head - 0.18)
        local spine = bone_height(PED_BONES.spine, 1.18)
        local pelvis = bone_height(PED_BONES.pelvis, 0.92)
        local left_foot = bone_height(PED_BONES.left_foot, 0.06)
        local right_foot = bone_height(PED_BONES.right_foot, 0.06)
        local feet = math.min(left_foot, right_foot)
        local body_bottom = feet - 0.05
        local body_top = head + math.max(0.10, (head - feet) * 0.07)
        local body_height = clamp(body_top - body_bottom, 1.20, 2.60)
        local function preset(bottom, top, fov, margin)
            bottom, top = tonumber(bottom) or body_bottom, tonumber(top) or body_top
            if top <= bottom then top = bottom + 0.45 end
            local target = (bottom + top) * 0.5
            return {
                distance = framing_distance(top - bottom, fov, margin),
                height = target,
                look = target,
                fov = fov,
            }
        end
        editor.frame_presets = {
            face = preset(neck - body_height * 0.05, body_top, 28.0, 1.28),
            upper = preset(math.min(pelvis, spine) - body_height * 0.03, body_top, 31.0, 1.22),
            full = preset(body_bottom, body_top, 32.0, 1.38),
            legs = preset(body_bottom, body_bottom + body_height * 0.60, 31.0, 1.28),
            shoes = preset(body_bottom, body_bottom + body_height * 0.24, 30.0, 1.25),
        }
        editor.frame_metrics_at_ms = now_ms()
        return true
    end

    local function shortest_angle_delta(from, to)
        return ((tonumber(to) - tonumber(from) + 540.0) % 360.0) - 180.0
    end

    local function ease_in_out(value)
        value = clamp(value, 0.0, 1.0)
        return value * value * (3.0 - 2.0 * value)
    end

    local function motion_duration(editor, degrees)
        local mode = tostring(editor.motion_mode or "smooth")
        if mode == "instant" then return 0 end
        local base = math.abs(tonumber(degrees) or 0) >= 135.0 and 360 or 230
        return mode == "cinematic" and math.floor(base * 1.65) or base
    end

    local function preview_set_view(editor, name)
        local target = PREVIEW_VIEWS[tostring(name)]
        if target == nil then return false end
        target = (target + (tonumber(editor.front_yaw) or 0)) % 360
        local current = tonumber(editor.current_yaw) or 0.0
        local delta = shortest_angle_delta(current, target)
        local duration = motion_duration(editor, delta)
        editor.view_preset = tostring(name)
        editor.target_yaw = (current + delta) % 360.0
        editor.transition = duration > 0 and {
            start_yaw = current,
            delta_yaw = delta,
            start_ms = 0,
            pending = true,
            duration_ms = duration,
        } or nil
        if duration == 0 then editor.current_yaw = editor.target_yaw end
        return true
    end

    local function preview_set_framing(editor, name)
        local preset = type(editor.frame_presets) == "table" and editor.frame_presets[tostring(name)]
            or PREVIEW_FRAMING[tostring(name)]
        if not preset then return false end
        editor.framing_mode = tostring(name)
        editor.target_distance = preset.distance
        editor.target_height = preset.height
        editor.target_look_height = preset.look
        editor.target_fov = preset.fov
        if tostring(editor.motion_mode or "smooth") == "instant" then
            editor.current_distance = preset.distance
            editor.current_height = preset.height
            editor.current_look_height = preset.look
            editor.current_fov = preset.fov
        end
        return true
    end

    local function preview_reset_view(editor)
        editor.auto_rotate = false
        editor.hold_rotate, editor.hold_zoom = 0, 0
        editor.orbit_pitch = 0.0
        editor.mouse_orbit_x, editor.mouse_orbit_y, editor.mouse_zoom_steps = 0, 0, 0
        preview_set_framing(editor, "full")
        preview_set_view(editor, "front")
    end

    local function preview_suggest_category(editor, category)
        if editor.auto_frame_category ~= true or not category then return false end
        editor.auto_rotate = false
        editor.orbit_pitch = 0.0
        editor.mouse_orbit_x, editor.mouse_orbit_y, editor.mouse_zoom_steps = 0, 0, 0
        local framing = CATEGORY_FRAMING[category.label] or "full"
        preview_set_view(editor, category.label == "Bags / Parachutes" and "back" or "front")
        return preview_set_framing(editor, framing)
    end

    -- Outfit Studio owns live field revisions, never the player's model or appearance identity.
    local OutfitLive = {}
    local component_call

    function OutfitLive.safety(enabled)
        local callback = enabled and Live.acquire_studio_safety or Live.release_studio_safety
        if type(callback) ~= "function" then return false end
        local ok, result = pcall(callback, "outfit")
        return ok and result == true
    end

    function OutfitLive.clear_camera_input(editor)
        editor.hold_rotate, editor.hold_zoom = 0, 0
        editor.mouse_orbit_x, editor.mouse_orbit_y, editor.mouse_zoom_steps = 0, 0, 0
    end

    function OutfitLive.camera_delta(value, limit)
        value = tonumber(value)
        if not value or value ~= value or math.abs(value) == math.huge then return 0 end
        return clamp(value, -limit, limit)
    end

    function OutfitLive.input_requested(editor)
        return editor.pending_action ~= nil or next(editor.edits or {}) ~= nil
            or (editor.visible_ping == true and editor.studio_open ~= true)
    end

    function OutfitLive.read_int(hash, ...)
        local value, raw, err = invoke_int_detail(hash, ...)
        if err or type(raw) ~= "number" or value ~= value or value % 1 ~= 0 then return nil end
        return value
    end

    function OutfitLive.read_bool(hash, ...)
        local _, raw, err = invoke_bool_detail(hash, ...)
        if err then return nil end
        if type(raw) == "boolean" then return raw end
        if raw == 0 or raw == 1 then return raw == 1 end
        return nil -- An unknown or malformed result is not a verified false.
    end

    function OutfitLive.copy(value)
        if type(value) ~= "table" then return nil end
        return { drawable = value.drawable, texture = value.texture, palette = value.palette }
    end

    function OutfitLive.equal(a, b)
        return a and b and a.drawable == b.drawable and a.texture == b.texture
            and (a.palette == nil or b.palette == nil or a.palette == b.palette)
    end

    function OutfitLive.character()
        local online = OutfitLive.read_bool(0x9DE624D2FC4B603F)
        if online == nil then return nil end
        if not online then return "story" end
        local economy = module_context and module_context.CScript and module_context.CScript.Economy
        if economy and type(economy.CurrentSlot) == "function" then
            local ok, slot = pcall(economy.CurrentSlot)
            if ok and (slot == 0 or slot == 1) then return "MP" .. slot end
        end
        return nil -- Online edits require a validated active character identity.
    end

    function OutfitLive.identity(ped, camera_only)
        if type(ped) ~= "number" or ped ~= ped or ped % 1 ~= 0 or ped <= 0 or ped >= 0xFFFFFFFF then return nil end
        if ped ~= local_ped() or not entity_exists(ped) then return nil end
        local dead = OutfitLive.read_bool(H.IS_PED_DEAD_OR_DYING, ped, true)
        if dead ~= false then return nil end
        local transitioning = OutfitLive.read_bool(0x68049AEFF83D8F0A)
        if transitioning ~= false then return nil end
        local model = OutfitLive.read_int(H.GET_ENTITY_MODEL, ped)
        if not model or model == 0 or model < -0x80000000 or model > 0xFFFFFFFF
            or not gta or type(gta.HandleToPointer) ~= "function" then
            return nil
        end
        local ok, address, repeated = pcall(function()
            local object = gta.HandleToPointer(ped)
            local address = object and object:GetAddress()
            local fresh = gta.HandleToPointer(ped)
            return address, fresh and fresh:GetAddress()
        end)
        if not ok or type(address) ~= "number" or address ~= address or address % 1 ~= 0
            or address < 0x10000 or address > 0x7FFFFFFFFFFF or repeated ~= address
            or not entity_exists(ped) or OutfitLive.read_int(H.GET_ENTITY_MODEL, ped) ~= model then
            return nil
        end
        local character = camera_only and State.outfit.target and State.outfit.target.character or OutfitLive.character()
        if not character then return nil end
        return {
            ped = ped,
            model = model,
            address = address,
            character = character,
            epoch = tonumber(State.outfit.live_epoch) or 0
        }
    end

    function OutfitLive.same(a, b)
        return a and b and a.ped == b.ped and a.model == b.model and a.address == b.address
            and a.character == b.character and a.epoch == b.epoch
    end

    function OutfitLive.valid(editor, camera_only)
        return OutfitLive.same(editor.target, OutfitLive.identity(editor.target and editor.target.ped or 0, camera_only))
    end

    function OutfitLive.read_field(ped, category)
        local component = category.kind == "component"
        local drawable = OutfitLive.read_int(component and H.GET_PED_DRAWABLE_VARIATION or H.GET_PED_PROP_INDEX,
            ped, category.id, true)
        if drawable == nil or drawable < (component and 0 or -1) then return nil end
        local texture = drawable == -1 and 0 or OutfitLive.read_int(
            component and H.GET_PED_TEXTURE_VARIATION or H.GET_PED_PROP_TEXTURE_INDEX, ped, category.id)
        if texture == nil or texture < 0 then return nil end
        local palette = component and OutfitLive.read_int(0xE3DD5F2A84B42281, ped, category.id) or nil
        if component and (palette == nil or palette < 0 or palette > 3) then return nil end
        return { drawable = drawable, texture = texture, palette = palette }
    end

    function OutfitLive.invalidate(reason)
        local editor = State.outfit
        local ui = module_context and module_context.CScript and module_context.CScript.UI
        local reset = ui and ui.Components and ui.Components.reset_repeat_input
        if type(reset) == "function" then pcall(reset) end
        editor.live_epoch = (tonumber(editor.live_epoch) or 0) + 1
        editor.target, editor.current, editor.baseline, editor.verified = nil, nil, nil, nil
        editor.edits, editor.undo, editor.touched, editor.failures = {}, {}, {}, {}
        editor.confirmation, editor.pending_action = nil, nil
        editor.gta_snapshot, editor.gta_error, editor.gta_name, editor.gta_wear_name = nil, nil, nil, nil
        editor.gta_next_poll = 0
        editor.revision, editor.applied_revision, editor.failed_revision = 0, 0, 0
        editor.limits_model, editor.limits_ready = 0, {}
        editor.dirty_limits = {}
        editor.status = tostring(reason or "Character unavailable")
    end

    function OutfitLive.queue(category, patch, expected, no_undo)
        local editor = State.outfit
        if not editor.target or not editor.current or not category then return false end
        local key = category.kind .. ":" .. category.id
        editor.edits = editor.edits or {}
        local prior = editor.edits[key]
        local fields = prior and prior.patch or {}
        for field, value in pairs(patch or {}) do fields[field] = value end
        editor.revision = (tonumber(editor.revision) or 0) + 1
        editor.edits[key] = {
            category = category,
            patch = fields,
            revision = editor.revision,
            target = editor.target,
            expected = expected,
            no_undo = no_undo == true,
            group = editor.queue_group
        }
        local values = category.kind == "component" and editor.current.components or editor.current.props
        if values[category.id] then
            for field, value in pairs(fields) do values[category.id][field] = value end
        end
        editor.confirmation = nil
        editor.status = "Applying"
        return true
    end

    function OutfitLive.overlay_pending(editor)
        -- Native calls may yield to a later render. Keep a newer queued value
        -- visible when an earlier readback or external wardrobe poll completes.
        for _, request in pairs(editor.edits or {}) do
            if OutfitLive.same(request.target, editor.target) and editor.current then
                local values = request.category.kind == "component" and editor.current.components or editor.current
                    .props
                local value = values[request.category.id]
                if value then
                    for field, next_value in pairs(request.patch) do value[field] = next_value end
                end
            end
        end
    end

    function OutfitLive.write_field(editor, request)
        if not OutfitLive.same(request.target, editor.target) or not OutfitLive.valid(editor) then
            return false, "Character changed; edit cancelled"
        end
        local category, ped = request.category, editor.target.ped
        local before = OutfitLive.read_field(ped, category)
        if not before then return false, "Current category could not be read" end
        for field, value in pairs(request.expected or {}) do
            if before[field] ~= value then return false, "Category changed elsewhere; undo cancelled" end
        end
        local desired = OutfitLive.copy(before)
        for field, value in pairs(request.patch) do desired[field] = value end
        local component = category.kind == "component"
        local count = OutfitLive.read_int(component and H.GET_NUMBER_OF_PED_DRAWABLE_VARIATIONS
            or H.GET_NUMBER_OF_PED_PROP_DRAWABLE_VARIATIONS, ped, category.id)
        if count == nil or desired.drawable < (component and 0 or -1) or desired.drawable >= count then
            return false, "Item is unavailable for this model"
        end
        if desired.drawable == -1 then
            desired.texture = 0
        else
            local textures = OutfitLive.read_int(component and H.GET_NUMBER_OF_PED_TEXTURE_VARIATIONS
                or H.GET_NUMBER_OF_PED_PROP_TEXTURE_VARIATIONS, ped, category.id, desired.drawable)
            if not textures or textures < 1 then return false, "Item texture range is unavailable" end
            -- A changed item has a necessary texture dependency. An explicit texture must remain valid.
            if desired.texture >= textures and request.patch.drawable ~= nil then desired.texture = 0 end
            if desired.texture < 0 or desired.texture >= textures then return false, "Texture is unavailable" end
        end
        if component then
            local valid, raw, err = invoke_bool_detail(0xE825F6B6CEA7671D,
                ped, category.id, desired.drawable, desired.texture)
            if err or (type(raw) ~= "boolean" and type(raw) ~= "number") or not valid then
                return false, "Game rejected this component variation"
            end
        end
        if not OutfitLive.valid(editor) then return false, "Character changed; edit cancelled" end
        if OutfitLive.equal(before, desired) then return true, nil, before, before end
        local ok, raw, err
        if component then
            ok, raw, err = invoke_void_detail(H.SET_PED_COMPONENT_VARIATION,
                ped, category.id, desired.drawable, desired.texture, desired.palette)
        elseif desired.drawable < 0 then
            ok, raw, err = invoke_void_detail(H.CLEAR_PED_PROP, ped, category.id, true)
        else
            ok, raw, err = invoke_void_detail(H.SET_PED_PROP_INDEX,
                ped, category.id, desired.drawable, desired.texture, true, true)
        end
        if not OutfitLive.valid(editor) then return false, "Character changed during application" end
        local after = OutfitLive.read_field(ped, category)
        if not ok or raw == false or err or not OutfitLive.equal(after, desired) then
            return false, "Change was not verified; current appearance refreshed", before, after
        end
        return true, nil, before, after
    end

    function OutfitLive.drain(editor)
        local requests = {}
        for key, value in pairs(editor.edits or {}) do requests[#requests + 1] = { key = key, value = value } end
        table.sort(requests, function(a, b) return a.value.revision < b.value.revision end)
        for _, row in ipairs(requests) do
            local request = row.value
            if editor.edits[row.key] == request then editor.edits[row.key] = nil end
            local ok, reason, before, after = OutfitLive.write_field(editor, request)
            if after and editor.current and editor.verified then
                local collection = request.category.kind == "component" and "components" or "props"
                local previous = editor.verified[collection][request.category.id]
                if not previous or previous.drawable ~= after.drawable then
                    editor.dirty_limits = editor.dirty_limits or {}
                    editor.dirty_limits[row.key] = request.category
                end
                editor.current[collection][request.category.id] = OutfitLive.copy(after)
                editor.verified[collection][request.category.id] = OutfitLive.copy(after)
            end
            if ok then
                editor.failures = editor.failures or {}
                editor.failures[row.key] = nil
                if before and after and not OutfitLive.equal(before, after) then
                    editor.touched = editor.touched or {}
                    local touched = editor.touched[row.key] or { category = request.category, fields = {} }
                    local undo_patch, undo_expected = {}, {}
                    for _, field in ipairs({ "drawable", "texture", "palette" }) do
                        if before[field] ~= after[field] then
                            touched.fields[field] = true; undo_patch[field] = before[field]; undo_expected[field] = after
                                [field]
                        end
                    end
                    editor.touched[row.key] = touched
                    if not request.no_undo then
                        editor.undo = editor.undo or {}
                        local group = editor.undo[#editor.undo]
                        if not request.group or not group or group.group ~= request.group then
                            group = { target = request.target, group = request.group, changes = {} }
                            editor.undo[#editor.undo + 1] = group
                        end
                        group.changes[#group.changes + 1] = {
                            category = request.category,
                            before = undo_patch,
                            after =
                                undo_expected,
                            target = request.target
                        }
                        if #editor.undo > 32 then table.remove(editor.undo, 1) end
                    end
                end
                editor.applied_revision = math.max(tonumber(editor.applied_revision) or 0, request.revision)
            else
                editor.failures = editor.failures or {}
                editor.failures[row.key] = request.revision
                editor.failed_revision = request.revision
                editor.status = reason
                if not after and editor.current and editor.verified then
                    local collection = request.category.kind == "component" and "components" or "props"
                    editor.current[collection][request.category.id] = OutfitLive.copy(editor.verified[collection]
                        [request.category.id])
                end
            end
        end
        if #requests > 0 then
            if next(editor.failures or {}) == nil then editor.failed_revision = 0 end
            if (tonumber(editor.failed_revision) or 0) == 0 then
                editor.status = next(editor.edits or {}) and "Applying" or "Editing current outfit"
            end
            OutfitLive.overlay_pending(editor)
        end
    end

    function OutfitLive.randomize(editor, category)
        -- Count validity does not prove cross-component visual compatibility. Preserve silhouettes,
        -- face and hair; safe whole-outfit variation changes textures only. Manual item freedom remains.
        if category.kind == "component" and (category.id == 0 or category.id == 2) then return end
        local values = category.kind == "component" and editor.current.components or editor.current.props
        local value = values[category.id]
        if not value or value.drawable < 0 then return end
        local counts = category.kind == "component" and editor.component_texture_counts or editor.prop_texture_counts
        local count = tonumber(counts[category.id]) or 0
        if count > 1 then OutfitLive.queue(category, { texture = math.random(0, count - 1) }) end
    end

    local function clone_outfit(outfit)
        if type(outfit) ~= "table" then return nil end
        local result = {
            name = tostring(outfit.name or "Outfit"),
            model = tonumber(outfit.model) or 0,
            created = tostring(outfit.created or ""),
            modified = tostring(outfit.modified or ""),
            favorite = outfit.favorite == true,
            complete = outfit.complete,
            components = {},
            props = {},
        }
        for id, value in pairs(outfit.components or {}) do
            result.components[id] = OutfitLive.copy(value)
        end
        for id, value in pairs(outfit.props or {}) do
            result.props[id] = OutfitLive.copy(value)
        end
        return result
    end

    local function capture_outfit(ped, name)
        if not entity_exists(ped) then return nil end
        local identity = OutfitLive.identity(ped)
        if not identity then return nil end
        local model = OutfitLive.read_int(H.GET_ENTITY_MODEL, ped)
        if not model or model == 0 then return nil end
        local outfit = { name = tostring(name or "Current Outfit"), model = model, components = {}, props = {}, complete = true }
        for _, category in ipairs(OUTFIT_CATEGORIES) do
            local value = OutfitLive.read_field(ped, category)
            if value then
                local values = category.kind == "component" and outfit.components or outfit.props
                values[category.id] = value
            else
                outfit.complete = false
            end
        end
        if not OutfitLive.same(identity, OutfitLive.identity(ped)) then return nil end
        return outfit
    end

    function OutfitLive.snap_equal(a, b)
        if not a or not b or a.model ~= b.model or a.complete ~= b.complete then return false end
        for _, category in ipairs(OUTFIT_CATEGORIES) do
            local key = category.kind == "component" and "components" or "props"
            local x, y = a[key][category.id], b[key][category.id]
            if (x or y) and not OutfitLive.equal(x, y) then return false end
        end
        return true
    end

    local function outfit_storage_path()
        if not (FileMgr and type(FileMgr.GetMenuRootPath) == "function") then return nil end
        local ok, root = pcall(FileMgr.GetMenuRootPath)
        if not ok or type(root) ~= "string" or root == "" then return nil end
        local directory = root .. "\\Lua\\CScript"
        if type(FileMgr.CreateDir) == "function" then pcall(FileMgr.CreateDir, directory) end
        return directory .. "\\outfits.txt"
    end

    local function encode_outfit_values(values, specs)
        local entries = {}
        for _, item in ipairs(specs) do
            local value = values and values[item.id] or nil
            if value then
                entries[#entries + 1] = ("%d:%d:%d"):format(
                    item.id, tonumber(value.drawable) or 0, tonumber(value.texture) or 0)
            end
        end
        return table.concat(entries, ";")
    end

    local function decode_outfit_values(text)
        local result = {}
        for id, drawable, texture in tostring(text or ""):gmatch("(%d+):(-?%d+):(%d+)") do
            result[tonumber(id)] = { drawable = tonumber(drawable), texture = tonumber(texture) }
        end
        return result
    end

    local function empty_outfit_slot(index, suggested_name)
        return {
            name = tostring(suggested_name or ""),
            model = 0,
            created = "",
            modified = "",
            favorite = false,
            components = {},
            props = {}
        }
    end

    local function clone_outfit_slots(slots)
        local result = {}
        for index, slot in ipairs(slots or {}) do result[index] = clone_outfit(slot) end
        if #result == 0 then result[1] = empty_outfit_slot(1) end
        return result
    end

    function OutfitLive.local_slot_occupied(slot)
        return type(slot) == "table" and (next(slot.components or {}) ~= nil or next(slot.props or {}) ~= nil)
    end

    -- Called only by tick-owned preset actions. UI rendering never samples the
    -- host clock, performs persistence, or invokes a native.
    local function outfit_timestamp()
        if not (os and type(os.date) == "function") then return "" end
        local ok, value = pcall(os.date, "!%Y-%m-%dT%H:%M:%SZ")
        return ok and type(value) == "string" and value or ""
    end

    local function load_outfit_slots()
        local editor = State.outfit
        if editor.loaded then return end
        editor.loaded = true
        editor.storage_bytes, editor.storage_error, editor.storage_migrated = nil, nil, false
        editor.slots = { empty_outfit_slot(1) }
        local path = outfit_storage_path()
        if not path or not FileMgr or type(FileMgr.DoesFileExist) ~= "function"
            or type(FileMgr.ReadFileContent) ~= "function" then
            editor.storage_error = "Local file access is unavailable"; return
        end
        local exists_ok, exists = pcall(FileMgr.DoesFileExist, path)
        if not exists_ok then
            editor.storage_error = "Local file existence could not be read"; return
        end
        if not exists then
            editor.selected_slot = 1; editor.rename_buffer = ""; editor.rename_buffer_slot = 1; return
        end
        local read_ok, content = pcall(FileMgr.ReadFileContent, path)
        if not read_ok or type(content) ~= "string" then
            editor.storage_error = "Local presets could not be read"; return
        end
        editor.storage_bytes = content
        local header = content:match("^([^\r\n]+)")
        local legacy = header == "CSCRIPT_OUTFITS_V1"
        if not legacy and header ~= "CSCRIPT_OUTFIT_PRESETS_V1" then
            editor.storage_error = "Local presets use an unsupported format"; return
        end
        local slots, rows, declared = {}, 0, nil
        local malformed = false
        for line in content:gmatch("[^\r\n]+") do
            if line == header then
            elseif line:match("^SLOTS|") and not legacy then
                local count = tonumber(line:match("^SLOTS|(%d+)$"))
                if declared ~= nil or not count or count % 1 ~= 0 or count < 1 then
                    malformed = true; break
                end
                declared = count
            elseif line:match("^PALETTE|") then
                local index, id, palette = line:match("^PALETTE|(%d+)|(%d+)|([0-3])$")
                local slot = index and slots[tonumber(index)]
                local value = slot and slot.components[tonumber(id)]
                if not value then
                    malformed = true; break
                end
                value.palette = tonumber(palette)
            elseif line:match("^META|") then
                local index, created, modified, favorite, model = line:match(
                    "^META|(%d+)|([^|]*)|([^|]*)|([01])|(-?%d+)$")
                local slot = index and slots[tonumber(index)]
                if not slot then
                    malformed = true; break
                end
                slot.created = tostring(created):sub(1, 32); slot.modified = tostring(modified):sub(1, 32)
                slot.favorite = favorite == "1"; slot.model = tonumber(model) or 0
            else
                local index, name, components, props = line:match("^(%d+)|([^|]*)|([^|]*)|([^|]*)$")
                index = tonumber(index)
                if not index or index < 1 or slots[index] or (legacy and index > 5)
                    or (not legacy and index ~= rows + 1) then
                    malformed = true; break
                end
                slots[index] = empty_outfit_slot(index, tostring(name):sub(1, 40))
                slots[index].components = decode_outfit_values(components)
                slots[index].props = decode_outfit_values(props)
                rows = rows + 1
            end
        end
        if not legacy and (declared == nil or rows ~= declared) then malformed = true end
        if malformed then
            editor.storage_error = "Local preset records are incomplete; the original file was preserved"; return
        end
        if legacy then
            local suggested = { "Stealth", "Tryhard", "Casual", "Police", "Military" }
            local migrated = {}
            for index = 1, 5 do
                local slot = slots[index]
                local placeholder = slot and not OutfitLive.local_slot_occupied(slot) and (tonumber(slot.model) or 0) ==
                    0
                    and (slot.name == suggested[index] or slot.name == "Outfit " .. index)
                    and slot.created == "" and slot.modified == "" and slot.favorite ~= true
                if slot and not placeholder then migrated[#migrated + 1] = slot end
            end
            slots = migrated; editor.storage_migrated = true
        end
        if #slots == 0 then slots = { empty_outfit_slot(1) } end
        editor.slots = slots
        editor.selected_slot = math.max(1, math.min(#slots, math.floor(tonumber(editor.selected_slot) or 1)))
        editor.rename_buffer = tostring(slots[editor.selected_slot].name or "")
        editor.rename_buffer_slot = editor.selected_slot; editor.confirmation = nil
    end

    local function save_outfit_slots(slots)
        load_outfit_slots()
        local editor = State.outfit
        if editor.storage_error then return false, editor.storage_error end
        slots = slots or editor.slots
        if #slots < 1 then return false, "The local library must keep one slot" end
        local path = outfit_storage_path()
        if not path or not FileMgr or type(FileMgr.WriteFileContent) ~= "function"
            or type(FileMgr.ReadFileContent) ~= "function" then
            return false, "File persistence is unavailable"
        end
        -- New header prevents a previous five-slot reader from truncating this library.
        local lines = { "CSCRIPT_OUTFIT_PRESETS_V1", "SLOTS|" .. #slots }
        for index, outfit in ipairs(slots) do
            lines[#lines + 1] = table.concat({ tostring(index), tostring(outfit.name or ""):gsub("[|\r\n]", " "):sub(1,
                40),
                encode_outfit_values(outfit.components, OUTFIT_COMPONENTS), encode_outfit_values(outfit.props,
                OUTFIT_PROPS) }, "|")
        end
        for index, outfit in ipairs(slots) do
            lines[#lines + 1] = table.concat(
                { "META", tostring(index), tostring(outfit.created or ""):gsub("[|\r\n]", " "):sub(1, 32),
                    tostring(outfit.modified or ""):gsub("[|\r\n]", " "):sub(1, 32), outfit.favorite == true and "1" or
                "0",
                    tostring(math.floor(tonumber(outfit.model) or 0)) }, "|")
        end
        for index, outfit in ipairs(slots) do
            for _, spec in ipairs(OUTFIT_COMPONENTS) do
                local value = outfit.components and outfit.components[spec.id]
                if value and value.palette ~= nil then
                    lines[#lines + 1] = ("PALETTE|%d|%d|%d"):format(index, spec.id,
                        value.palette)
                end
            end
        end
        local read, before, why = OutfitLive.source_bytes()
        if not read or before ~= editor.storage_bytes then return false, why or "Local file changed before write" end
        local content = table.concat(lines, "\n")
        local ok, result = pcall(FileMgr.WriteFileContent, path, content, false)
        local verified, after = pcall(FileMgr.ReadFileContent, path)
        if not ok or result == false or not verified or after ~= content then
            return false, before ~= nil and "File readback did not match; original presets remain in the verified backup"
                or "File readback did not match"
        end
        editor.storage_bytes = content; editor.storage_migrated = false
        return true
    end

    -- Preview copies are display-only. The live editor retains its own target,
    -- revisions, verified readback and Undo; none of these helpers write to it.
    function OutfitLive.preview_identity(ped)
        if type(ped) ~= "number" or ped <= 0 or ped % 1 ~= 0 or ped == local_ped()
            or ped == (State.outfit.target and State.outfit.target.ped) or not entity_exists(ped) then
            return nil
        end
        local model = OutfitLive.read_int(H.GET_ENTITY_MODEL, ped)
        if not model or model == 0 or not gta or type(gta.HandleToPointer) ~= "function" then return nil end
        -- This handle came from our CLONE_PED call. Compare fresh forward
        -- handle/address samples with the owned lease instead of reverse-scanning
        -- Cherax's pool; a missing reverse-pool entry is not an entity deletion.
        local ok, address, repeated = pcall(function()
            local object = gta.HandleToPointer(ped)
            local address = object and object:GetAddress()
            local fresh = gta.HandleToPointer(ped)
            return address, fresh and fresh:GetAddress()
        end)
        if not ok or type(address) ~= "number" or address ~= address or address % 1 ~= 0
            or address < 0x10000 or address > 0x7FFFFFFFFFFF or repeated ~= address
            or not entity_exists(ped) or OutfitLive.read_int(H.GET_ENTITY_MODEL, ped) ~= model then
            return nil
        end
        return { ped = ped, model = model, address = address }
    end

    function OutfitLive.preview_owned(editor)
        local proof = editor.preview_proof
        local current = proof and OutfitLive.preview_identity(editor.preview_ped)
        return current and current.ped == proof.ped and current.address == proof.address
            and current.model == proof.model and proof.address ~= proof.source_address
            and OutfitLive.read_bool(0xC7827959479DCC78, current.ped) == false
            and OutfitLive.read_bool(H.IS_PED_A_PLAYER, current.ped) == false
    end

    function OutfitLive.preview_write(editor, hash, ...)
        if not hash or not OutfitLive.preview_owned(editor) then return false end
        local ok, raw, err = invoke_void_detail(hash, editor.preview_ped, ...)
        return ok and raw ~= false and not err
    end

    function OutfitLive.preview_delete(editor)
        local ped = tonumber(editor.preview_ped) or 0
        local function forget()
            editor.preview_ped, editor.preview_proof, editor.preview_snapshot = 0, nil, nil
            if memory and type(memory.Free) == "function" and (tonumber(editor.delete_ptr) or 0) ~= 0 then
                pcall(memory.Free, editor.delete_ptr); editor.delete_ptr = 0
            end
            return true
        end
        if ped == 0 then return forget() end
        local exists = OutfitLive.read_bool(H.DOES_ENTITY_EXIST, ped)
        if exists == false then return forget() end
        if exists ~= true then return false end -- Unknown is still our cleanup debt.
        -- Positive evidence of handle reuse means the new entity is NOT ours.
        if ped == local_ped() or ped == (editor.target and editor.target.ped) then return forget() end
        local current = OutfitLive.preview_identity(ped)
        local proof = editor.preview_proof
        if proof and current and (current.address ~= proof.address or current.model ~= proof.model) then return forget() end
        if not OutfitLive.preview_owned(editor) or not memory or not editor.delete_ptr or editor.delete_ptr == 0 then
            return false -- Keep cleanup debt; do not spawn another copy or guess an identity.
        end
        local ok, result = pcall(memory.WriteInt, editor.delete_ptr, ped)
        if not ok or result == false or not OutfitLive.preview_owned(editor) then return false end
        local accepted, raw, err = invoke_void_detail(H.DELETE_ENTITY, editor.delete_ptr)
        if accepted and raw ~= false and not err
            and OutfitLive.read_bool(H.DOES_ENTITY_EXIST, ped) == false then
            return forget()
        end
        return false
    end

    function OutfitLive.preview_create(editor, x, y, z)
        if (tonumber(editor.preview_ped) or 0) ~= 0 or not OutfitLive.valid(editor) then return false end
        -- Reserve correctly typed deletion storage BEFORE creating an entity.
        if not memory or type(memory.AllocInt) ~= "function" or type(memory.WriteInt) ~= "function" then return false end
        if (tonumber(editor.delete_ptr) or 0) == 0 then
            local ok, ptr = pcall(memory.AllocInt)
            if ok and type(ptr) == "number" and ptr > 0 and ptr % 1 == 0 then editor.delete_ptr = ptr end
        end
        if (tonumber(editor.delete_ptr) or 0) == 0 then return false end
        local source = editor.target.ped
        -- Current native signature: ped, isNetwork, scriptHostPed, copyHeadBlend.
        -- Both network flags stay false; the last flag retains the character's face.
        local preview = OutfitLive.read_int(H.CLONE_PED, source, false, false, true)
        if not preview or preview <= 0 or preview == source or preview == local_ped() then return false end
        -- Record the returned allocation before another host read can fail.
        -- An unproven newborn remains debt and blocks further preview creation.
        editor.preview_ped = preview
        editor.preview_proof = nil
        if OutfitLive.read_bool(H.DOES_ENTITY_EXIST, preview) ~= true then return false end
        editor.preview_proof = OutfitLive.preview_identity(preview)
        if editor.preview_proof then editor.preview_proof.source_address = editor.target.address end
        if not editor.preview_proof or editor.preview_proof.model ~= editor.target.model
            or editor.preview_proof.address == editor.target.address or not OutfitLive.valid(editor) then
            return false
        end
        -- The caller supplies the isolated stage above the validated source.
        -- Move only our local copy; no player teleport, weather/timecycle change,
        -- or outfit reset is part of preview creation.
        local anchor = { x = x, y = y, z = z }
        editor.preview_anchor = anchor
        for _, op in ipairs({
            { H.SET_ENTITY_AS_MISSION_ENTITY,         true,     true },
            { H.SET_ENTITY_COLLISION,                 false,    false },
            { H.FREEZE_ENTITY_POSITION,               true },
            { H.SET_ENTITY_COORDS_NO_OFFSET,          anchor.x, anchor.y, anchor.z, false, false, false },
            { H.SET_ENTITY_HEADING,                   180.0 },
            { H.SET_ENTITY_VISIBLE,                   true,     false },
            { H.SET_ENTITY_INVINCIBLE,                true },
            { H.SET_ENTITY_CAN_BE_DAMAGED,            false },
            { H.SET_PED_CAN_RAGDOLL,                  false },
            { H.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, true },
            { H.SET_PED_CAN_BE_TARGETTED,             false },
            { 0xAAA34F8A7CB32098 }, -- CLEAR_PED_TASKS_IMMEDIATELY, copy only
        }) do
            if not OutfitLive.preview_write(editor, op[1], table.unpack(op, 2)) then return false end
        end
        editor.preview_snapshot = nil
        editor.preview_sync_target, editor.preview_sync_attempts, editor.preview_sync_due = nil, 0, 0
        editor.preview_cloned = nil
        return true
    end

    function OutfitLive.preview_sync(editor)
        if (tonumber(editor.preview_ped) or 0) == 0 then return true end
        if not OutfitLive.valid(editor) or not OutfitLive.preview_owned(editor) then return false end
        if OutfitLive.snap_equal(editor.preview_snapshot, editor.verified) then return true end
        local now = now_ms()
        if now < (editor.preview_sync_due or 0) then return true end
        editor.preview_sync_due = now + 50
        local actual = capture_outfit(editor.target.ped, "Current Outfit")
        if not actual or actual.complete ~= true then return true end
        if not OutfitLive.snap_equal(editor.preview_sync_target, actual) then
            editor.preview_sync_target = clone_outfit(actual)
            editor.preview_sync_attempts = 0
        end
        local tries = editor.preview_sync_attempts or 0
        if not editor.preview_cloned then
            local ok, raw, err = invoke_void_detail(0xE952D6431689AD9A, editor.target.ped, editor.preview_ped)
            if not OutfitLive.valid(editor) or not OutfitLive.preview_owned(editor) then return false end
            editor.preview_sync_attempts = math.min(4, tries + 1)
            if not ok or raw == false or err then
                editor.preview_sync_due = now + (tries >= 3 and 1000 or 50)
                return true
            end
            editor.preview_cloned = true
            tries = 0; editor.preview_sync_attempts = 0
        end
        local mismatch = false
        for _, category in ipairs(OUTFIT_CATEGORIES) do
            local group = category.kind == "component" and "components" or "props"
            local desired = actual[group][category.id]
            if not OutfitLive.equal(desired, OutfitLive.read_field(editor.preview_ped, category)) then
                mismatch = true
                -- CLONE_PED_TO_TARGET can settle late or omit a prop. Repair
                -- only our local preview; never write back to the real player.
                if editor.preview_cloned and tries < 4 and desired then
                    if not OutfitLive.valid(editor) or not OutfitLive.preview_owned(editor) then return false end
                    -- The clone can change before its next readback. Do not let
                    -- a quick return to the old outfit reuse that stale proof.
                    editor.preview_snapshot = nil
                    if category.kind == "component" then
                        OutfitLive.preview_write(editor, H.SET_PED_COMPONENT_VARIATION, category.id, desired.drawable,
                            desired.texture, desired.palette or 0)
                    elseif desired.drawable == -1 then
                        OutfitLive.preview_write(editor, H.CLEAR_PED_PROP, category.id)
                    else
                        OutfitLive.preview_write(editor, H.SET_PED_PROP_INDEX, category.id, desired.drawable,
                            desired.texture, true)
                    end
                end
            end
        end
        if not OutfitLive.valid(editor) or not OutfitLive.preview_owned(editor) then return false end
        if not mismatch then
            editor.preview_snapshot = clone_outfit(actual)
            editor.preview_sync_attempts, editor.preview_sync_target = 0, nil
            if editor.preview_sync_warning then
                editor.camera_status = ""; editor.preview_sync_warning = nil
            end
        else
            editor.preview_sync_attempts = math.min(4, tries + 1)
            if tries >= 4 then
                editor.preview_sync_due = now + 1000
                editor.camera_status = "Some preview items are still updating."
                editor.preview_sync_warning = true
            end
        end
        return true
    end

    local function stop_outfit_preview(reason)
        local editor = State.outfit
        OutfitLive.clear_camera_input(editor)
        editor.camera_pose_history = nil
        local ui = module_context and module_context.CScriptUI
        local cam = tonumber(editor.preview_cam) or 0
        if cam ~= 0 then
            local owned = ui and type(ui.owns_studio_camera) == "function"
                and ui.owns_studio_camera("outfit", editor.camera_lease)
            local owner = module_context and module_context.State and module_context.State.UI
            if not ui then owned = owner and owner.PreviewCameraOwner == "outfit" end
            local rendering = OutfitLive.read_int(0x5234F9F10919EABA)
            local alive = OutfitLive.read_bool(0xA7A932170592B50E, cam)
            if editor.preview_stop_logged ~= cam then
                editor.preview_stop_logged = cam
                local safe_reason = tostring(reason or 'unspecified'):gsub('[%c]', ' '):sub(1, 64)
                pcall(log_info, ('OutfitPreviewStop reason=%s leaseOwned=%s ownCameraRendering=%s cameraAlive=%s')
                    :format(safe_reason, tostring(owned == true), tostring(rendering == cam), tostring(alive)))
            end
            -- A different active camera belongs to the game or another feature.
            -- No eased teardown: an outgoing interpolation camera can otherwise
            -- survive a verified destroy and be mistaken for a competing camera
            -- when the next studio acquires its lease on this same native tick.
            if owned and (rendering == cam or rendering == -1 or rendering == 0) then
                invoke_void(H.RENDER_SCRIPT_CAMS, false, false, 0, true, false, 0)
            end
            if owned and alive == true then
                invoke_void(H.SET_CAM_ACTIVE, cam, false)
                invoke_void(H.DESTROY_CAM, cam, false)
            end
            local exists, raw, err = invoke_bool_detail(0xA7A932170592B50E, cam)
            if not owned then exists, raw, err = false, false, nil end
            if err or (raw ~= true and raw ~= false and raw ~= 0 and raw ~= 1) or exists then
                editor.cleanup_pending = true
                editor.cleanup_retry_ms = now_ms() + 250
                editor.hold_rotate, editor.hold_zoom = 0, 0
                editor.camera_status = "Closing view; cleanup will retry"
                return false
            end
            editor.preview_cam = 0
            if ui and type(ui.release_studio_camera) == "function" then
                ui.release_studio_camera("outfit", editor.camera_lease)
            elseif owner and owner.PreviewCameraOwner == "outfit" then
                owner.PreviewCameraOwner = nil
            end
        end
        if not OutfitLive.preview_delete(editor) then
            editor.cleanup_pending = true; editor.cleanup_retry_ms = now_ms() + 250
            editor.hold_rotate, editor.hold_zoom = 0, 0
            editor.camera_status = "Closing preview copy; cleanup will retry"
            return false
        end
        editor.camera_lease, editor.preview_anchor = nil, nil
        editor.camera_ready, editor.camera_start_deadline = false, nil
        editor.cleanup_pending = false
        editor.preview_ped = 0 -- Only our identity-checked local preview was released.
        editor.last_preview_frame_ms = 0
        editor.hold_rotate, editor.hold_zoom = 0, 0
        editor.preview_input_ping, editor.transition = false, nil
        if reason == "camera handoff" or reason == "conflicting camera" or reason == "studio switch"
            or reason == "camera lost" or reason == "camera unavailable" then
            editor.preview_suppressed, editor.preview_requested = true, false
            editor.camera_status = "Camera paused; reopen Outfit Studio to retry"
        end
        if not editor.studio_open or reason == "subject lost" or reason == "subject changed"
            or reason == "session transition" or reason == "panic reset" then
            OutfitLive.safety(false)
        end
        return true
    end

    function OutfitLive.request_close(reason)
        local editor = State.outfit
        editor.close_requested = tostring(reason or "view closed")
        editor.preview_requested, editor.visible_ping, editor.preview_input_ping = false, false, false
        editor.studio_open, editor.auto_rotate = false, false
        OutfitLive.clear_camera_input(editor)
    end

    function OutfitLive.close_tick(now)
        local editor = State.outfit
        if not editor.close_requested then return false end
        if not editor.cleanup_pending or now >= (tonumber(editor.cleanup_retry_ms) or 0) then
            if stop_outfit_preview(editor.close_requested) and OutfitLive.safety(false) then editor.close_requested = nil end
        end
        return true
    end

    local function start_outfit_preview()
        local editor = State.outfit
        if editor.cleanup_pending or not OutfitLive.valid(editor) then return false end
        if (tonumber(editor.preview_cam) or 0) ~= 0 then return true end
        if now_ms() < (tonumber(editor.camera_retry_ms) or 0) then return false end
        local protections = module_context and module_context.CScript and module_context.CScript.Protections
        if protections and type(protections.IsUnderAttack) == "function" then
            local ok, blocked = pcall(protections.IsUnderAttack)
            if not ok or blocked then return false end
        end
        local source = editor.target.ped
        local x, y, z = vector_components(invoke_vec3(H.GET_ENTITY_COORDS, source, false))
        if not x or not y or not z then return false end
        local ui = module_context and module_context.CScriptUI
        local rendering = OutfitLive.read_int(0x5234F9F10919EABA)
        local owner = module_context and module_context.State and module_context.State.UI
        local other_studio = owner and owner.PreviewCameraOwner and owner.PreviewCameraOwner ~= "outfit"
        if rendering == nil or (rendering ~= 0 and rendering ~= -1 and not other_studio) then
            editor.preview_suppressed, editor.preview_requested = true, false
            editor.camera_status = "View paused while another camera is active"
            return false
        end
        if ui and type(ui.claim_studio_camera) == "function" then
            editor.camera_lease = ui.claim_studio_camera("outfit", function(reason)
                editor.preview_suppressed, editor.preview_requested = true, false
                editor.auto_rotate = false
                return stop_outfit_preview(reason or "camera handoff")
            end)
            if not editor.camera_lease then return false end
            rendering = OutfitLive.read_int(0x5234F9F10919EABA)
            if rendering == nil or (rendering ~= 0 and rendering ~= -1) then
                ui.release_studio_camera("outfit", editor.camera_lease); editor.camera_lease = nil
                editor.preview_suppressed, editor.preview_requested = true, false
                editor.camera_status = "View paused while another camera is active"
                return false
            end
        else
            local owner = module_context and module_context.State and module_context.State.UI
            if owner and owner.PreviewCameraOwner and owner.PreviewCameraOwner ~= "outfit" then return false end
            if owner then owner.PreviewCameraOwner = "outfit" end
        end
        -- Restore the isolated pre-rework studio stage: keep the clone within
        -- the same streamed X/Y area but well above the live character so the
        -- real player and ground scene never sit beside the preview subject.
        local preview_z = z + 160.0
        if not OutfitLive.preview_create(editor, x, y, preview_z) or not OutfitLive.preview_sync(editor) then
            stop_outfit_preview("preview copy unavailable")
            if ui and ui.release_studio_camera then ui.release_studio_camera("outfit", editor.camera_lease) end
            if not ui and owner and owner.PreviewCameraOwner == "outfit" then owner.PreviewCameraOwner = nil end
            editor.camera_lease = nil
            editor.preview_suppressed, editor.preview_requested = true, false
            editor.camera_status = "Preview copy unavailable; live editing is still available"
            return false
        end
        x, y, z = editor.preview_anchor.x, editor.preview_anchor.y, editor.preview_anchor.z
        -- The local display copy faces 180 degrees regardless of the real
        -- player's heading. Preserve the selected relative angle when moving
        -- from the source frame into that fixed preview frame.
        local source_front = tonumber(editor.front_yaw) or 0
        editor.current_yaw = ((tonumber(editor.current_yaw) or source_front) - source_front) % 360
        editor.target_yaw = ((tonumber(editor.target_yaw) or source_front) - source_front) % 360
        if type(editor.transition) == "table" then
            editor.transition.start_yaw = ((tonumber(editor.transition.start_yaw) or source_front) - source_front) % 360
        end
        editor.front_yaw = 0
        refresh_outfit_framing_metrics(editor, editor.preview_ped)
        preview_set_framing(editor, editor.framing_mode or "full")
        editor.current_distance, editor.current_height = editor.target_distance, editor.target_height
        editor.current_look_height, editor.current_fov = editor.target_look_height, editor.target_fov
        local cam_x, cam_y, cam_z, look_x, look_y, look_z = outfit_camera_pose(editor)
        local cam = invoke_int(H.CREATE_CAM_WITH_PARAMS, "DEFAULT_SCRIPTED_CAMERA",
            cam_x, cam_y, cam_z, 0.0, 0.0, 0.0, editor.current_fov, false, 2)
        if not cam or cam <= 0 or cam % 1 ~= 0 then
            if ui and ui.release_studio_camera then ui.release_studio_camera("outfit", editor.camera_lease) end
            if not ui and owner and owner.PreviewCameraOwner == "outfit" then owner.PreviewCameraOwner = nil end
            stop_outfit_preview("camera creation failed")
            editor.camera_lease = nil
            editor.camera_retry_ms = now_ms() + 1000
            editor.camera_status = "View unavailable; live editing is available"
            return false
        end
        editor.preview_cam = cam
        editor.preview_stop_logged = nil
        -- Configure the same world-space look point used by subsequent frames
        -- before activation. Switching entity-pointing to coordinate-pointing
        -- after rendering starts creates a visible first-frame framing jump.
        invoke_void(0xF75497BB865F0803, cam, look_x, look_y, look_z)
        invoke_void(H.SET_CAM_ACTIVE, cam, true)
        invoke_void(H.RENDER_SCRIPT_CAMS, true, false, 0, true, false, 0)
        editor.camera_ready = false
        editor.camera_start_deadline = now_ms() + 500
        editor.camera_verify_ms, editor.camera_mismatch_count = now_ms() + 750, 0
        editor.camera_pose_history = { { x = cam_x, y = cam_y, z = cam_z, time = now_ms() } }
        editor.last_preview_frame_ms = now_ms()
        editor.camera_status = "Opening view"
        return true
    end

    -- Cheap render-cadence controller. This performs only owned clone-heading
    -- and camera transforms; outfit discovery, persistence, model
    -- queries, and component application remain on the throttled fast tick.
    local function outfit_preview_frame(now)
        local editor = State.outfit
        local visibility, visible = component_call("studio_workspace_visible", "outfit")
        if editor.studio_open and visibility and visible == false then OutfitLive.request_close("studio hidden") end
        if editor.studio_open and GUI and type(GUI.IsOpen) == "function" then
            local ok, open = pcall(GUI.IsOpen)
            if ok and open == false then OutfitLive.request_close("menu closed") end
        end
        if OutfitLive.close_tick(tonumber(now) or now_ms()) then return end
        if editor.cleanup_pending then
            if (tonumber(now) or now_ms()) >= (tonumber(editor.cleanup_retry_ms) or 0) then
                stop_outfit_preview(
                    "cleanup retry")
            end
            return
        end
        if not tonumber(editor.preview_cam) or editor.preview_cam == 0 or not editor.target then
            editor.last_preview_frame_ms = tonumber(now) or 0
            return
        end
        if not OutfitLive.valid(editor, true) then
            stop_outfit_preview("subject lost"); return
        end
        if not OutfitLive.preview_owned(editor) then
            editor.preview_suppressed, editor.preview_requested = true, false
            stop_outfit_preview("preview copy lost")
            editor.camera_status = "Preview copy lost; reopen Outfit Studio to retry"
            return
        end
        local ui = module_context and module_context.CScriptUI
        if ui and ui.owns_studio_camera and not ui.owns_studio_camera("outfit", editor.camera_lease) then
            stop_outfit_preview("camera handoff"); return
        end
        now = tonumber(now) or now_ms()
        local alive = OutfitLive.read_bool(0xA7A932170592B50E, editor.preview_cam)
        if alive == false then
            stop_outfit_preview("camera lost")
            editor.camera_status = "Camera closed; reopen Outfit Studio to retry"
            return
        end
        local rendering = OutfitLive.read_int(0x5234F9F10919EABA)
        if rendering and rendering ~= -1 and rendering ~= 0 and rendering ~= editor.preview_cam then
            stop_outfit_preview("conflicting camera"); return
        end
        local active = OutfitLive.read_bool(0xDFB2B516207D3534, editor.preview_cam)
        if alive ~= true or active ~= true or rendering ~= editor.preview_cam then
            if not editor.camera_ready and now < (tonumber(editor.camera_start_deadline) or 0) then return end
            stop_outfit_preview("camera unavailable")
            editor.camera_status = "Camera paused; reopen Outfit Studio to retry"
            return
        end
        editor.camera_ready, editor.camera_status = true, ""
        if type(editor.preview_anchor) ~= "table" then
            stop_outfit_preview("position unavailable"); return
        end
        now = tonumber(now) or now_ms()
        local last = tonumber(editor.last_preview_frame_ms) or 0
        editor.last_preview_frame_ms = now
        if last <= 0 or now <= last then return end
        local delta = math.min(0.05, math.max(0.001, (now - last) / 1000.0))

        -- UI deltas are accumulated once, then consumed on this verified native
        -- frame. A held mouse or a stalled UI cannot replay an old drag/wheel.
        local orbit_x = OutfitLive.camera_delta(editor.mouse_orbit_x, 320)
        local orbit_y = OutfitLive.camera_delta(editor.mouse_orbit_y, 320)
        local zoom_steps = OutfitLive.camera_delta(editor.mouse_zoom_steps, 8)
        if editor.auto_frame_category ~= true then
            local motion_ok, motion_x, motion_y = component_call("studio_camera_motion", "outfit")
            if motion_ok then
                orbit_x = OutfitLive.camera_delta(orbit_x + OutfitLive.camera_delta(motion_x, 80), 320)
                orbit_y = OutfitLive.camera_delta(orbit_y + OutfitLive.camera_delta(motion_y, 80), 320)
            end
            -- The optional helper reads PAD wheel edges on this native frame;
            -- its hover/focus/ownership gate comes from the cached UI snapshot.
            local ok, wheel = component_call("studio_camera_wheel", "outfit")
            if ok and type(wheel) == "number" then
                zoom_steps = OutfitLive.camera_delta(zoom_steps + OutfitLive.camera_delta(wheel, 8), 8)
            end
        end
        editor.mouse_orbit_x, editor.mouse_orbit_y, editor.mouse_zoom_steps = 0, 0, 0
        if editor.auto_frame_category ~= true and (orbit_x ~= 0 or orbit_y ~= 0 or zoom_steps ~= 0) then
            editor.transition, editor.auto_rotate = nil, false
            editor.view_preset = "free"
            editor.current_yaw = ((tonumber(editor.current_yaw) or 0) - orbit_x * 0.24) % 360
            editor.target_yaw = editor.current_yaw
            editor.orbit_pitch = clamp((tonumber(editor.orbit_pitch) or 0) + orbit_y * 0.18, -65, 65)
            editor.target_distance = clamp((tonumber(editor.target_distance) or 3.25)
                * math.exp(-zoom_steps * 0.12), PREVIEW_DISTANCE_MIN, PREVIEW_DISTANCE_MAX)
        end

        if tonumber(editor.hold_rotate) and editor.hold_rotate ~= 0 then
            editor.transition = nil
            editor.view_preset = "free"
            editor.current_yaw = ((tonumber(editor.current_yaw) or 0.0)
                + editor.hold_rotate * PREVIEW_ROTATION_RATE * delta) % 360.0
            editor.target_yaw = editor.current_yaw
        elseif editor.auto_rotate then
            editor.transition = nil
            editor.view_preset = "free"
            editor.current_yaw = ((tonumber(editor.current_yaw) or 0.0)
                + PREVIEW_ROTATION_RATE * 0.32 * delta) % 360.0
            editor.target_yaw = editor.current_yaw
        elseif type(editor.transition) == "table" then
            if editor.transition.pending then
                editor.transition.start_ms = now
                editor.transition.pending = false
            end
            local elapsed = now - (tonumber(editor.transition.start_ms) or now)
            local duration = math.max(1, tonumber(editor.transition.duration_ms) or 1)
            local progress = clamp(elapsed / duration, 0.0, 1.0)
            editor.current_yaw = ((tonumber(editor.transition.start_yaw) or 0.0)
                + (tonumber(editor.transition.delta_yaw) or 0.0) * ease_in_out(progress)) % 360.0
            if progress >= 1.0 then
                editor.current_yaw = (tonumber(editor.target_yaw) or editor.current_yaw) % 360.0
                editor.transition = nil
            end
        else
            editor.current_yaw = (tonumber(editor.target_yaw) or editor.current_yaw or 0.0) % 360.0
        end

        if tonumber(editor.hold_zoom) and editor.hold_zoom ~= 0 then
            editor.target_distance = clamp((tonumber(editor.target_distance) or 3.25)
                + editor.hold_zoom * PREVIEW_ZOOM_RATE * delta,
                PREVIEW_DISTANCE_MIN, PREVIEW_DISTANCE_MAX)
        end
        local smoothing = tostring(editor.motion_mode or "smooth") == "cinematic" and 6.0 or 11.0
        if tostring(editor.motion_mode or "smooth") == "instant" then smoothing = 1000.0 end
        local alpha = 1.0 - math.exp(-smoothing * delta)
        editor.current_distance = (tonumber(editor.current_distance) or 3.25)
            + ((tonumber(editor.target_distance) or 3.25) - (tonumber(editor.current_distance) or 3.25)) * alpha
        editor.current_height = (tonumber(editor.current_height) or 0.95)
            + ((tonumber(editor.target_height) or 0.95) - (tonumber(editor.current_height) or 0.95)) * alpha
        editor.current_look_height = (tonumber(editor.current_look_height) or 0.85)
            + ((tonumber(editor.target_look_height) or 0.85) - (tonumber(editor.current_look_height) or 0.85)) * alpha
        editor.current_fov = (tonumber(editor.current_fov) or 32.0)
            + ((tonumber(editor.target_fov) or 32.0) - (tonumber(editor.current_fov) or 32.0)) * alpha

        editor.preview_heading = 180.0
        if not OutfitLive.preview_write(editor, H.SET_ENTITY_HEADING, editor.preview_heading) then
            stop_outfit_preview("camera unavailable"); return
        end
        editor.preview_zoom = editor.current_fov
        local cam_x, cam_y, cam_z, look_x, look_y, look_z = outfit_camera_pose(editor)
        local positioned = invoke_void(SET_CAM_COORD, editor.preview_cam, cam_x, cam_y, cam_z)
        local pointed = invoke_void(0xF75497BB865F0803, editor.preview_cam,
            look_x, look_y, look_z)
        local zoomed = invoke_void(SET_CAM_FOV, editor.preview_cam, editor.current_fov)
        if not positioned or not pointed or not zoomed then
            stop_outfit_preview("camera unavailable")
            editor.camera_status = "Camera update failed; reopen Outfit Studio to retry"
            return
        end
        local poses = editor.camera_pose_history or {}
        editor.camera_pose_history = poses
        poses[#poses + 1] = { x = cam_x, y = cam_y, z = cam_z, time = now }
        -- Native readback may acknowledge an earlier rendered transform. Keep
        -- a short bounded window, including the previous submission after a hitch.
        while #poses > 32 or (#poses > 2 and now - poses[1].time > 250) do
            table.remove(poses, 1)
        end
        if now >= (tonumber(editor.camera_verify_ms) or 0) then
            local rx, ry, rz = vector_components(invoke_vec3(0xBAC038F7459AE5AE, editor.preview_cam))
            local matches = false
            if type(rx) == "number" and type(ry) == "number" and type(rz) == "number" then
                for _, pose in ipairs(poses) do
                    if math.abs(rx - pose.x) < 0.15 and math.abs(ry - pose.y) < 0.15
                        and math.abs(rz - pose.z) < 0.15 then
                        matches = true; break
                    end
                end
            end
            editor.camera_mismatch_count = matches and 0 or ((tonumber(editor.camera_mismatch_count) or 0) + 1)
            editor.camera_verify_ms = now + 750
            if editor.camera_mismatch_count >= 2 then
                stop_outfit_preview("camera unavailable")
                editor.camera_status = "Camera stopped responding; reopen Outfit Studio to retry"
            end
        end
    end


    local function refresh_outfit_limits(target_ped, category)
        local editor = State.outfit
        local ped = tonumber(target_ped) or (editor.target and editor.target.ped) or 0
        if not entity_exists(ped) or type(editor.current) ~= "table" then return end
        local model = invoke_int(H.GET_ENTITY_MODEL, ped)
        if model ~= (tonumber(editor.limits_model) or 0) then
            editor.component_counts, editor.component_texture_counts = {}, {}
            editor.prop_counts, editor.prop_texture_counts = {}, {}
            editor.limits_ready = {}
            editor.limits_model = model
        end
        for _, item in ipairs(OUTFIT_COMPONENTS) do
            if not category or (category.kind == "component" and category.id == item.id) then
                local value = editor.current.components and editor.current.components[item.id]
                local drawable_count = math.max(0,
                    OutfitLive.read_int(H.GET_NUMBER_OF_PED_DRAWABLE_VARIATIONS, ped, item.id) or 0)
                editor.component_counts[item.id] = drawable_count
                editor.component_texture_counts[item.id] = value and drawable_count > 0 and math.max(0,
                    OutfitLive.read_int(H.GET_NUMBER_OF_PED_TEXTURE_VARIATIONS, ped, item.id, value.drawable) or 0) or 0
                editor.limits_ready["component:" .. item.id] = true
            end
        end
        for _, item in ipairs(OUTFIT_PROPS) do
            if not category or (category.kind == "prop" and category.id == item.id) then
                local value = editor.current.props and editor.current.props[item.id]
                local drawable_count = math.max(0,
                    OutfitLive.read_int(H.GET_NUMBER_OF_PED_PROP_DRAWABLE_VARIATIONS, ped, item.id) or 0)
                editor.prop_counts[item.id] = drawable_count
                editor.prop_texture_counts[item.id] = value and value.drawable >= 0 and math.max(0,
                        OutfitLive.read_int(H.GET_NUMBER_OF_PED_PROP_TEXTURE_VARIATIONS, ped, item.id, value.drawable) or
                        0) or
                    0
                editor.limits_ready["prop:" .. item.id] = true
            end
        end
        return true
    end


    local function outfit_button(label)
        if not imgui or type(imgui.Button) ~= "function" then return false end
        local ok, value = pcall(imgui.Button, label)
        return ok and value == true
    end

    local function outfit_same_line()
        if imgui and type(imgui.SameLine) == "function" then pcall(imgui.SameLine) end
    end

    local function outfit_text(text, disabled)
        if not imgui then return end
        local method = imgui.TextWrapped or (disabled and imgui.TextDisabled or imgui.Text)
        if type(method) == "function" then pcall(method, tostring(text)) end
    end

    local function outfit_input(label, current, maximum)
        if not imgui or type(imgui.InputText) ~= "function" then return tostring(current or "") end
        -- The third host argument is input flags, not a byte limit. 31 filters letters.
        local ok, first, second = pcall(imgui.InputText, label, tostring(current or ""), 0)
        if not ok then return tostring(current or "") end
        local value = type(first) == "string" and first
            or first == true and type(second) == "string" and second or tostring(current or "")
        local limit = maximum or 40
        if #value > limit then
            -- Do not split a UTF-8 sequence when enforcing the GTA byte limit.
            while limit > 0 do
                local byte = value:byte(limit + 1)
                if not byte or byte < 128 or byte >= 192 then break end
                limit = limit - 1
            end
            value = value:sub(1, limit)
        end
        return value
    end

    local function outfit_ui()
        local api = module_context and module_context.CScript and module_context.CScript.UI
        return api and type(api.Components) == "table" and api.Components or nil
    end

    component_call = function(name, ...)
        local ui = outfit_ui()
        local callback = ui and ui[name]
        if type(callback) ~= "function" then return false, nil end
        local ok, value, second, third = pcall(callback, ...)
        return ok, value, second, third
    end

    local function component_button(kind, label, id, tooltip, width)
        local ok, clicked = component_call(kind, label, id, tooltip, width)
        if ok then return clicked == true end
        if width and imgui and type(imgui.Button) == "function" then
            local ok_button, clicked_button = pcall(imgui.Button,
                tostring(label) .. "##" .. tostring(id), tonumber(width), 32)
            if ok_button then return clicked_button == true end
        end
        return outfit_button(tostring(label) .. "##" .. tostring(id))
    end

    local function component_section(title, subtitle)
        local ok = component_call("section", title, subtitle)
        if ok then return end
        outfit_text(tostring(title or ""):upper())
        if subtitle then outfit_text(subtitle, true) end
        if imgui and type(imgui.Separator) == "function" then pcall(imgui.Separator) end
    end



    local function component_empty(title, guidance)
        local ok = component_call("empty_state", title, guidance)
        if not ok then outfit_text(tostring(title) .. (guidance and ("  " .. tostring(guidance)) or ""), true) end
    end

    local function component_search(id, current, placeholder, maximum)
        local ok, value = component_call("search_box", id, current, placeholder, maximum)
        if ok and type(value) == "string" then return value end
        return outfit_input(tostring(placeholder or "Search") .. "##" .. tostring(id), current, maximum)
    end

    local function component_chip(label, selected, id, tooltip)
        local full_label = tostring(label)
        local max_chars = math.max(12, math.floor(((tonumber(State.outfit.layout_width) or 260) - 44) / 8))
        if #full_label > max_chars then
            local cut = max_chars - 3
            if utf8 and type(utf8.offset) == "function" then
                local ok, offset = pcall(utf8.offset, full_label, cut + 1)
                if ok and offset then cut = offset - 1 end
            end
            label = full_label:sub(1, cut) .. "..."
            tooltip = full_label .. (tooltip and (" â€” " .. tooltip) or "")
        end
        local ok, clicked = component_call("category_chip", label, selected, id, tooltip)
        if ok then return clicked == true end
        return outfit_button((selected and "> " or "") .. tostring(label) .. "##" .. tostring(id))
    end

    local function component_pair_fits(required_width)
        local ui = outfit_ui()
        if ui and type(ui.row_can_pair) == "function" then
            local ok, value = pcall(ui.row_can_pair, required_width or 250)
            if ok then return value == true end
        end
        return false
    end

    local function component_pair_line(required_width)
        -- row_can_pair measures the REMAINING width after the first control.
        -- The old 240-280px thresholds wrongly forced almost every action to stack.
        local next_width = math.min(150, math.max(88, (tonumber(required_width) or 250) * 0.52))
        if component_pair_fits(next_width) then
            outfit_same_line(); return true
        end
        return false
    end

    local function component_stepper(label, value, minimum, maximum, step, id, tooltip, display_value)
        local ok, next_value, changed = component_call("value_stepper",
            label, value, minimum, maximum, step, id, tooltip, display_value)
        if ok then return tonumber(next_value) or value, changed == true end
        outfit_text(tostring(label) .. "  " .. tostring(display_value or value))
        local changed_value = false
        if outfit_button("< Previous##" .. tostring(id) .. "_previous") then
            value = value - step
            if value < minimum then value = maximum end
            changed_value = true
        end
        outfit_same_line()
        if outfit_button("Next >##" .. tostring(id) .. "_next") then
            value = value + step
            if value > maximum then value = minimum end
            changed_value = true
        end
        return value, changed_value
    end


    local function component_selector(id, label, index, items)
        local ok, selected, changed = component_call("compact_selector", id, label, index, items)
        if ok and items[selected] then return selected, changed == true end
        if imgui and type(imgui.Combo) == "function" then
            if type(imgui.SetNextItemWidth) == "function" then pcall(imgui.SetNextItemWidth, -1) end
            ok, selected, changed = pcall(imgui.Combo, label .. "##" .. id, index - 1, items, #items, 12)
            if ok and type(selected) == "number" and items[selected + 1] then return selected + 1, changed == true end
        end
        outfit_text(label .. ": " .. tostring(items[index] or "None"), true)
        return index, false
    end

    local function component_toggle(label, value, id, tooltip)
        local ok, next_value, changed = component_call("toggle_row", label, value, id, tooltip)
        if ok then return next_value == true, changed == true end
        if component_button("secondary_button", (value and "ON  " or "OFF  ") .. label,
                id, tooltip) then
            return not value, true
        end
        return value == true, false
    end

    local function sanitize_outfit_name(value)
        return tostring(value or ""):gsub("[|\r\n]", " "):sub(1, 40)
    end

    local function queue_outfit_action(action, category_index)
        local editor = State.outfit
        if editor.pending_action ~= nil then
            editor.status = "Finishing previous action"; return false
        end
        editor.next_action_serial = (tonumber(editor.next_action_serial) or 0) + 1
        if tostring(action):sub(1, 4) == 'gta_' then
            editor.pending_action = {
                kind = action,
                serial = editor.next_action_serial,
                target = editor.target,
                revision = tonumber(editor.revision) or 0,
                gta_slot = editor.gta_selected or 0,
                gta_snapshot = editor.gta_snapshot,
                name = tostring(editor.gta_name or ''),
                confirmation = editor.confirmation
            }
            return true
        end
        local slot = math.max(1, math.min(math.max(1, #editor.slots), math.floor(tonumber(editor.selected_slot) or 1)))
        editor.pending_action = {
            kind = tostring(action),
            serial = editor.next_action_serial,
            category = tonumber(category_index),
            slot = slot,
            name = sanitize_outfit_name(editor.rename_buffer),
            target = editor.target,
            revision = tonumber(editor.revision) or 0,
            outfit = clone_outfit(editor.slots[slot]),
            confirmation = editor.confirmation
        }
        return true
    end


    local function outfit_slot_has_data(slot)
        return type(slot) == "table" and (next(slot.components or {}) ~= nil or next(slot.props or {}) ~= nil)
    end

    local function render_outfit_value(editor, category)
        local component = category.kind == "component"
        local value = component and editor.current.components[category.id] or editor.current.props[category.id]
        if not value then
            outfit_text("This category could not be read for the current model.", true); return
        end
        local count = tonumber((component and editor.component_counts or editor.prop_counts)[category.id]) or 0
        if count < 1 then
            outfit_text("No items supported for this model.", true); return
        end
        local textures = tonumber((component and editor.component_texture_counts or editor.prop_texture_counts)
            [category.id]) or 1
        local next_item, changed = component_stepper("Item", value.drawable, component and 0 or -1,
            count - 1, 1, "outfit_item_" .. category.kind .. category.id, "Changes the currently worn item immediately.",
            value.drawable < 0 and "None" or ("Item %d of %d"):format(value.drawable + 1, count))
        if changed then
            OutfitLive.queue(category, { drawable = next_item, texture = 0 })
            textures = 1 -- Wait for the new model/item-dependent range on the native tick.
        end
        if next_item >= 0 then
            local texture, texture_changed = component_stepper("Texture", value.texture, 0, math.max(0, textures - 1), 1,
                "outfit_texture_" .. category.kind .. category.id, "Changes this item's texture immediately.",
                ("Variant %d of %d"):format(value.texture + 1, textures))
            if texture_changed then OutfitLive.queue(category, { texture = texture }) end
        end
        if component_button("secondary_button", "Reset Category", "outfit_reset_category",
                "Restore this category to this character's session baseline.") then
            queue_outfit_action("reset_category", editor.selected_category)
        end
        if editor.advanced == true then
            outfit_text(("%s ID %d | item %d | texture %d%s"):format(category.kind, category.id, value.drawable,
                value.texture, value.palette ~= nil and (" | palette " .. value.palette) or ""), true)
            if component and value.palette ~= nil then
                local palette, pc = component_stepper("Palette", value.palette, 0, 3, 1, "outfit_palette",
                    "Change this component's palette.")
                if pc then OutfitLive.queue(category, { palette = palette }) end
            end
            outfit_text("Item names are not exposed by this model's validated component API.", true)
            if component_button("secondary_button", "Randomize Texture", "outfit_random_category") then
                queue_outfit_action("randomize_category", editor.selected_category)
            end
        end
    end

    local function render_outfit_categories(editor)
        local labels = {}
        for index, category in ipairs(OUTFIT_CATEGORIES) do
            labels[index] = (category.kind == "prop" and "Accessories / " or "Clothing / ") .. category.label
        end
        local index, changed = component_selector("outfit_category", "Category", editor.selected_category or 1, labels)
        if changed and labels[index] then
            editor.selected_category = index
            preview_suggest_category(editor, OUTFIT_CATEGORIES[index])
        end
    end

    local function render_outfit_editor(editor)
        if not editor.current or not editor.target then
            component_empty("Character unavailable", "Live editing resumes when your current character is ready."); return
        end
        local selected = OUTFIT_CATEGORIES[editor.selected_category] or OUTFIT_CATEGORIES[1]
        render_outfit_value(editor, selected)
        if component_button("subtle_button", "Undo Last Change", "outfit_undo") then
            queue_outfit_action("undo")
        end
        component_pair_line(150)
        if component_button("secondary_button", "Revert Session Edits", "outfit_revert") then
            queue_outfit_action("revert")
        end
        component_pair_line(135)
        local details, changed = component_toggle("Item details", editor.advanced == true, "outfit_advanced")
        if changed then editor.advanced = details end
        if component_button("secondary_button", "Randomize Textures", "outfit_random_all",
                "Vary textures while retaining equipped items, face, hair and body coverage.") then
            queue_outfit_action("randomize_all")
        end
        component_pair_line(145)
        if component_button("subtle_button", "Randomize Items", "outfit_random_items",
                "Mix clothing and accessories; Undo restores the previous outfit.") then
            queue_outfit_action("randomize_items")
        end
    end

    local function render_outfit_preview_controls(editor)
        local open = (tonumber(editor.preview_cam) or 0) ~= 0 and not editor.cleanup_pending
        local automatic, changed = component_toggle("Auto Camera", editor.auto_frame_category == true,
            "outfit_auto_camera",
            "Automatically frame the selected clothing category. Turn off for mouse orbit and zoom.")
        if changed then
            editor.auto_frame_category = automatic
            component_call("reset_repeat_input")
            preview_reset_view(editor)
            preview_suggest_category(editor, OUTFIT_CATEGORIES[editor.selected_category])
        end
        component_pair_line(115)
        local view_enabled, view_changed=component_toggle("Open view", open, "outfit_view_toggle")
        if view_changed then
            queue_outfit_action(view_enabled and "restore_preview" or "close")
        end
        local manual = open and editor.auto_frame_category ~= true
        local ok, input = component_call("studio_camera_input", "outfit", manual)
        if ok and type(input) == "table" then
            editor.viewport = input.viewport
            if manual then
                editor.mouse_orbit_x = OutfitLive.camera_delta((tonumber(editor.mouse_orbit_x) or 0)
                    + OutfitLive.camera_delta(input.orbit_x, 160), 320)
                editor.mouse_orbit_y = OutfitLive.camera_delta((tonumber(editor.mouse_orbit_y) or 0)
                    + OutfitLive.camera_delta(input.orbit_y, 160), 320)
                editor.mouse_zoom_steps = OutfitLive.camera_delta((tonumber(editor.mouse_zoom_steps) or 0)
                    + OutfitLive.camera_delta(input.zoom_steps or input.wheel, 8), 8)
            end
        end
        if not manual then OutfitLive.clear_camera_input(editor) end
        if editor.auto_frame_category ~= true then
            outfit_text("Hold right mouse over the preview to orbit; scroll to zoom.", true)
        end
        if editor.camera_status and editor.camera_status ~= "" then outfit_text(editor.camera_status, true) end
    end

    local function render_outfit_presets(editor)
        local sources = { "GTA Saved Outfits", "Local Presets" }
        local index, changed = component_selector("outfit_storage_source", "Source", editor.saved_source or 2, sources)
        if changed then
            editor.saved_source = index; editor.confirmation = nil
        end
        if (editor.saved_source or 2) == 1 then
            editor.gta_visible_ping = true
            if component_button("secondary_button", "Refresh", "gta_outfit_refresh") then
                queue_outfit_action(
                    "gta_refresh")
            end
            local snapshot = editor.gta_snapshot
            if not snapshot then
                component_empty("GTA Saved Outfits", editor.gta_error or "Reading current character wardrobe...")
                return
            end
            editor.gta_filter = component_search("gta_outfit_filter", editor.gta_filter or "", "Find saved outfit", 40)
            local slot_labels, slot_values, selected_choice = {}, {}, 1
            for _, row in ipairs(snapshot.entries) do
                local name = row.occupied and row.name or "Empty"
                local selected = (editor.gta_selected or 0) == row.slot
                if selected or editor.gta_filter == "" or name:lower():find(editor.gta_filter:lower(), 1, true) then
                    slot_labels[#slot_labels+1] = ("%d / %s"):format(row.slot + 1, name)
                    slot_values[#slot_values+1] = row.slot
                    if selected then selected_choice = #slot_values end
                end
            end
            if #slot_labels > 0 then
                local choice, picked = component_selector("gta_outfit_slot", "Outfit Slot",
                    selected_choice, slot_labels)
                if picked and slot_values[choice] ~= nil then
                    local chosen_slot = slot_values[choice]
                    local chosen = snapshot.entries[chosen_slot + 1]
                    editor.gta_selected = chosen_slot
                    editor.gta_name = chosen and chosen.occupied and chosen.name or "New Outfit"
                    editor.confirmation = nil
                end
            else
                outfit_text("No matching saved outfits", true)
            end
            local row = snapshot.entries[(editor.gta_selected or 0) + 1]
            if not row then return end
            outfit_text(("GTA slot %d / %s"):format(row.slot + 1, row.occupied and row.name or "Empty"))
            if editor.gta_name == nil then editor.gta_name = row.occupied and row.name or "New Outfit" end
            local previous_name = editor.gta_name
            editor.gta_name = outfit_input("Name##gta_outfit_name", editor.gta_name, 31)
            if previous_name ~= editor.gta_name then editor.confirmation = nil end
            if row.occupied and component_button("primary_button", "Wear", "gta_outfit_wear") then
                queue_outfit_action("gta_wear")
            end
            if row.occupied then component_pair_line(250) end
            if component_button("primary_button", row.occupied and "Overwrite Selected" or "Save Current", "gta_outfit_save") then
                queue_outfit_action("gta_save")
            end
            if row.occupied then
                component_pair_line(230)
                if component_button("secondary_button", "Rename", "gta_outfit_rename") then
                    queue_outfit_action(
                        "gta_rename")
                end
                component_pair_line(225)
                if component_button("danger_button", "Delete", "gta_outfit_delete") then
                    queue_outfit_action(
                        "gta_delete")
                end
            end
            if editor.confirmation and editor.confirmation.gta_slot ~= nil then
                outfit_text(editor.confirmation.label)
                if component_button("danger_button", "Confirm", "gta_outfit_confirm") then
                    queue_outfit_action(
                        "gta_confirm")
                end
                if component_button("secondary_button", "Cancel", "gta_outfit_cancel") then editor.confirmation = nil end
            end
            outfit_text("Changes update GTA's wardrobe. Persistence is pending the game's save.", true)
            return
        end
        editor.slot_filter = component_search("outfit_slot_filter", editor.slot_filter or "", "Find local preset", 40)
        local slot_labels, slot_values, selected_choice = {}, {}, 1
        for index = 1, math.max(1, #editor.slots) do
            local slot = editor.slots[index] or empty_outfit_slot(index)
            local occupied = outfit_slot_has_data(slot)
            local name = tostring(slot.name or "")
            local display = name ~= "" and name or (occupied and "Unnamed preset" or "Empty slot")
            local selected = editor.selected_slot == index
            if selected or editor.slot_filter == "" or display:lower():find(editor.slot_filter:lower(), 1, true) then
                slot_labels[#slot_labels+1] = ("%d / %s"):format(index, display)
                slot_values[#slot_values+1] = index
                if selected then selected_choice = #slot_values end
            end
        end
        if #slot_labels > 0 then
            local choice, picked = component_selector("outfit_saved_slot", "Local Slot",
                selected_choice, slot_labels)
            if picked and slot_values[choice] then
                local index = slot_values[choice]
                editor.selected_slot = index
                editor.rename_buffer = tostring((editor.slots[index] or {}).name or "")
                editor.rename_buffer_slot = index
                editor.confirmation = nil
            end
        else
            outfit_text("No matching presets", true)
        end
        if component_button("secondary_button", "Add Slot", "outfit_add_slot", "Add an empty local preset slot.") then
            queue_outfit_action("add_slot")
        end
        local slot = editor.slots[editor.selected_slot] or empty_outfit_slot(editor.selected_slot)
        local occupied = outfit_slot_has_data(slot)
        local name = tostring(slot.name or "")
        outfit_text(("Destination: Local slot %d  /  %s"):format(editor.selected_slot,
            name ~= "" and name or (occupied and "Unnamed preset" or "Empty slot")))
        if editor.rename_buffer_slot ~= editor.selected_slot or editor.rename_buffer == nil then
            editor.rename_buffer_slot = editor.selected_slot; editor.rename_buffer = name
        end
        local previous_name = editor.rename_buffer
        editor.rename_buffer = outfit_input("Name##outfit_name", editor.rename_buffer, 40)
        if previous_name ~= editor.rename_buffer then editor.confirmation = nil end
        if occupied and component_button("primary_button", "Wear", "outfit_wear") then queue_outfit_action("load_slot") end
        if occupied then component_pair_line(250) end
        if component_button("primary_button", occupied and "Overwrite Selected" or "Save Current",
                "outfit_save_current") then
            queue_outfit_action("prepare_save")
        end
        component_pair_line(250)
        if component_button("secondary_button", "Rename", "outfit_rename") then queue_outfit_action("rename_slot") end
        if occupied then
            component_pair_line(280)
            if component_button("secondary_button", "Duplicate", "outfit_duplicate") then
                queue_outfit_action(
                    "duplicate_slot")
            end
            if component_button("secondary_button", slot.favorite and "Unfavorite" or "Favorite", "outfit_favorite") then
                queue_outfit_action("favorite_slot")
            end
            component_pair_line(240)
            if component_button("danger_button", "Delete / Clear", "outfit_delete") then
                queue_outfit_action(
                    "prepare_delete")
            end
        end
        if editor.confirmation then
            outfit_text(editor.confirmation.label)
            if component_button("danger_button", "Confirm", "outfit_confirm") then queue_outfit_action("confirm_persist") end
            component_pair_line(180)
            if component_button("secondary_button", "Cancel", "outfit_cancel") then editor.confirmation = nil end
        end
        if editor.storage_error then outfit_text(editor.storage_error, true) end
    end

    local function render_outfit_manager()
        local editor = State.outfit
        component_call("studio_workspace_touch", "outfit")
        editor.visible_ping, editor.preview_input_ping = true, true
        editor.preview_requested = not editor.preview_suppressed
        outfit_text("Outfit Studio")
        local status = tostring(editor.status or "")
        if status:lower():find("fail", 1, true) or status:lower():find("error", 1, true)
            or status:lower():find("unavailable", 1, true) then
            outfit_text(status, true)
        end
        local ui = outfit_ui()
        if ui and ui.studio_layout then
            local ok, w, h, mode = pcall(ui.studio_layout)
            if ok then editor.layout_width, editor.layout_height, editor.layout_breakpoint = w, h, mode end
        end
        if component_chip("Customize", editor.workspace_tab ~= "presets", "outfit_workspace_editor") then
            if editor.workspace_tab == "presets" then component_call("reset_repeat_input") end
            editor.workspace_tab = "editor"
        end
        component_pair_line(190)
        if component_chip("Saved", editor.workspace_tab == "presets", "outfit_workspace_presets") then
            if editor.workspace_tab ~= "presets" then component_call("reset_repeat_input") end
            editor.workspace_tab = "presets"
        end
        local saved = editor.workspace_tab == "presets"
        if not saved then
            render_outfit_preview_controls(editor)
            render_outfit_categories(editor)
        else
            -- Saved does not sample camera input. Drop queued deltas at the
            -- workspace boundary instead of keeping its render heartbeat alive.
            component_call("studio_camera_input", "outfit", false)
            OutfitLive.clear_camera_input(editor)
        end
        local workspace = saved and ("presets:source:" .. tostring(editor.saved_source or 2))
            or ("editor:category:" .. tostring(editor.selected_category))
        local subject = editor.target and tostring(editor.target.address) .. ":" .. tostring(editor.target.epoch) or
            "none"
        local function body()
            if saved then
                render_outfit_presets(editor)
            else
                render_outfit_editor(editor)
            end
        end
        local body_helper = ui and ui.studio_workspace_body
        if type(body_helper) == "function" then
            -- An installed helper owns BeginChild/EndChild and propagates a
            -- renderer error to page recovery. Replaying a failed body here
            -- would duplicate queued actions and escape the bounded region.
            body_helper("outfit", workspace, subject, body)
        else
            body()
        end
    end

    -- Frame-wide awareness suppression is paired with identity-tracked blocking
    -- for rendered NPCs, including scripted/mission actors. Only NPC-to-player
    -- relationships are muted; owned flags restore on disable/session cleanup.
    local IGNORE_FRAME_FLAGS = { 62, 124 } -- SuppressGunfireEvents / CannotBeTargeted
    -- Target exclusion and gunfire suppression do not prevent witnesses from
    -- reacting to melee, injured victims, bodies or propagated agitation.
    -- These documented EVENT gates expire next frame; they do not alter NPC
    -- AI, relationships or mission tasks. Their ambient scope is local-world,
    -- including shocks from other actors while this option is enabled.
    local IGNORE_AMBIENT_FRAME_NATIVES = {
        { key = "shocking_accepted",  hash = 0x2F9A292AD0A3BD89, label = "shocking events" },
        { key = "agitation_accepted", hash = 0x5F3B7749C112D552, label = "agitation events" },
        { key = "witness_accepted",   hash = 0x36F1B38855F2A8DF, label = "witness calls",   player = true },
        -- Frame-local only: do not leave a persistent per-ped blocking flag behind.
        -- This closes the ambient road-block/bump/explosion/panic path that the
        -- player-wide ignore flags do not fully suppress by themselves.
        {
            key = "ambient_block_accepted",
            hash = 0x9911F4A24485F653,
            label = "ambient non-temporary events",
            toggle = true
        },
    }
    -- Frame-wide gates alone do not suppress every NPC reaction. Apply these
    -- persistent gates to validated NPC identities in the bounded scan, including
    -- mission/scripted actors; restore only still-current identities CScript owns.
    local IGNORE_PED_BLOCK_NATIVE = 0x9F8AA94D6D97DBF4      -- SET_BLOCKING_OF_NON_TEMPORARY_EVENTS
    local IGNORE_PED_TASK_BLOCK_NATIVE = 0x90D2156198831D69 -- TASK_SET_BLOCKING_OF_NON_TEMPORARY_EVENTS
    local IGNORE_LOW_PRIORITY_NATIVE = 0x596976B02B6B5700   -- SET_IGNORE_LOW_PRIORITY_SHOCKING_EVENTS
    local IGNORE_CLEAR_TASKS_NATIVE = 0xAAA34F8A7CB32098    -- CLEAR_PED_TASKS_IMMEDIATELY
    -- Pace NPC work across frames; persistent gates have independent refreshes.
    local IGNORE_LOOK_BUDGET = 4
    local IGNORE_POOL_SCAN_INTERVAL_MS = 90
    local IGNORE_POOL_LIMIT = 128
    local IGNORE_SCAN_RATE = 32 / 75
    local IGNORE_WORK_SECONDS = 0.0005
    local IGNORE_TIMING = { persist = 600, law = 250, relationship = 1200, reaction = 150, vehicle = 300 }
    -- Snapshot persistent gates before writing; restore only values still owned by CScript.
    local IGNORE_PED_CONFIG = {
        [17] = true,   -- BlockNonTemporaryEvents
        [24] = true,   -- IgnoreSeenMelee
        [49] = true,   -- BlockGroupPedAimedAtResponse
        [118] = false, -- RunFromFiresAndExplosions
        [128] = false, -- CanBeAgitated
        [134] = true,  -- PreventPedFromReactingToBeingJacked
        [208] = true,  -- DisableExplosionReactions
        [213] = false, -- ListensToSoundEvents (gunshots/impacts can bypass shocks)
        [229] = true,  -- DisablePanicInVehicle
        [285] = true,  -- DisableWeirdPedEvents
        [294] = true,  -- DisableShockingEvents
        [317] = false, -- CanSayFollowedByPlayerAudio
        [350] = true,  -- PreventDraggedOutOfCarThreatResponse
        [395] = true,  -- DontRespondToRandomPedsDamage
        [397] = false, -- KeepTargetLossResponseOnCleanup
        [437] = true,  -- DontShoutTargetPosition
    }
    local IGNORE_LAW_CONFIG = {
        [42] = true,                                                  -- DontInfluenceWantedLevel
        [152] = false,                                                -- AlwaysRespondToCriesForHelp
        [155] = false,                                                -- CanPerformArrest
        [183] = false,                                                -- IsAgitated
        [249] = false,                                                -- CanAttackNonWantedPlayerAsLaw
        [294] = true,                                                 -- DisableShockingEvents
        [324] = true,                                                 -- DontBehaveLikeLaw
        [326] = true,                                                 -- DisablePoliceInvestigatingBody
        [365] = true,                                                 -- OnlyUpdateTargetWantedIfSeen
        [396] = false,                                                -- AllowContinuousThreatResponseWantedLevelUpdates
        [399] = false,                                                -- BroadcastRespondedToThreatWhenGoingToPointShooting
        [412] = false,                                                -- ForceBlipSecurityPedsIfPlayerIsWanted
        [437] = true,                                                 -- DontShoutTargetPosition
    }
    local IGNORE_LAW_TYPES = { [6] = true, [27] = true, [29] = true } -- Cop/SWAT/Army

    local function behavior_debug_enabled()
        local diagnostics = module_context and module_context.CScript and module_context.CScript.Diagnostics
        return diagnostics and diagnostics.DebugMode == true
    end

    local function count_entries(values)
        local count = 0
        for _ in pairs(values or {}) do count = count + 1 end
        return count
    end

    local function pointer_handle(pointer)
        if pointer == nil or not (gta and type(gta.PointerToHandle) == "function") then return 0 end
        local ok, handle = pcall(gta.PointerToHandle, pointer)
        return ok and type(handle) == "number" and handle == handle and handle > 0
            and handle < 2147483647 and handle % 1 == 0 and handle or 0
    end

    local Ignore = {}

    -- Peds Ignore scan pacing begin
    function Ignore.scan_allowance(state, now, force)
        local previous = state.last_work_ms
        local elapsed = previous and math.max(0, now - previous) or 0
        local population = math.max(1, tonumber(state.scan_count) or 32)
        local cap = math.min(IGNORE_LOOK_BUDGET, population)
        local credit = (previous and now >= previous) and (state.scan_credit or 0) or cap
        state.last_work_ms = now
        state.scan_credit = math.min(cap, credit + elapsed * IGNORE_SCAN_RATE * math.min(32, population) / 32)
        if force then state.scan_credit = math.max(1, state.scan_credit) end
        return math.floor(state.scan_credit)
    end

    function Ignore.scan_peds(state, count, allowance, visit)
        state.scan_count = count
        state.scan_credit = math.min(math.max(1, count), state.scan_credit or 0)
        if count <= 0 then
            state.scan_credit = 0; return true
        end
        if allowance <= 0 then return true end
        local first = (tonumber(state.scan_cursor) or 0) % count
        local began = os.clock()
        for offset = 0, math.min(count, allowance, IGNORE_LOOK_BUDGET) - 1 do
            state.scan_cursor = (first + offset + 1) % count
            state.scan_credit = math.max(0, (state.scan_credit or 0) - 1)
            if visit((first + offset) % count + 1) == false then return false end
            if os.clock() - began >= IGNORE_WORK_SECONDS then break end
        end
        return true
    end

    -- Peds Ignore scan pacing end

    function Ignore.read(callback)
        local ok, value = pcall(callback)
        if ok then return value end
    end

    function Ignore.number(value)
        return type(value) == "number" and value == value and value > 0
            and value < 2147483647 and value % 1 == 0
    end

    function Ignore.address(pointer)
        local address = Ignore.read(function() return pointer:GetAddress() end)
        return type(address) == "number" and address == address and address > 0
            and address < math.huge and address % 1 == 0 and address or nil
    end

    function Ignore.network(pointer)
        local ok, object = pcall(function() return pointer.NetObject end)
        if not ok then return nil, false end
        if object == nil then return nil, true end
        local id = Ignore.read(function() return object.ObjectID end)
        if type(id) ~= "number" or id ~= id or id < 0 or id >= 2147483647 or id % 1 ~= 0 then return nil, false end
        return id, true
    end

    function Ignore.released(handle)
        local entity_state = State.messiah
        return entity_state and entity_state.released_script_guids
            and entity_state.released_script_guids[handle] == true
    end

    function Ignore.owner_current(address, network_id)
        local pointer = Ignore.read(function() return gta.GetLocalPed() end)
        if not pointer or Ignore.address(pointer) ~= address then return false end
        local network, known = Ignore.network(pointer)
        return known == true and network == network_id
    end

    function Ignore.valid(proof)
        if not proof or proof.closed or Ignore.released(proof.handle) then return false end
        if proof.controller and (not started or State.peds_ignore ~= proof.controller) then return false end
        -- Fence the complete identity after its read-only observations.
        -- Every native query and write still requires a fresh proof.
        local address = Ignore.address(proof.pointer)
        if address ~= proof.address then return false end
        local net, known = Ignore.network(proof.pointer)
        if not known or net ~= proof.network_id then return false end
        local pointer = Ignore.read(function() return gta.HandleToPointer(proof.handle) end)
        if pointer == nil then return false end
        local mapped = Ignore.address(pointer)
        return mapped == proof.address and proof.current() and not proof.closed
            and not Ignore.released(proof.handle)
    end

    function Ignore.proof(pointer, current, owned_handle, controller)
        if not current() or not (gta and type(gta.HandleToPointer) == "function") then return nil end
        local address = Ignore.address(pointer)
        if not current() or not address then return nil end
        local network_id, known = Ignore.network(pointer)
        if not current() or not known then return nil end
        local handle
        if owned_handle then
            handle = owned_handle -- freshly returned local-player owner, never a target alias
        else
            -- ObjectID identifies CNetObject; the documented contract does not
            -- establish that it is a native network ID. Convert the fresh
            -- CPhysical itself, then prove the address roundtrip below.
            handle = pointer_handle(pointer)
        end
        if not current() or not Ignore.number(handle) or Ignore.released(handle) then return nil end
        local proof = {
            pointer = pointer,
            address = address,
            network_id = network_id,
            handle = handle,
            current = current,
            controller =
                controller
        }
        return Ignore.valid(proof) and proof or nil
    end

    function Ignore.query(proof, kind, hash, ...)
        if not Ignore.valid(proof) then return nil end
        local value, raw, err
        if kind == "bool" then
            value, raw, err = invoke_bool_detail(hash, ...)
        elseif kind == "float" then
            value, raw, err = invoke_float_detail(hash, ...)
        else
            value, raw, err = invoke_int_detail(hash, ...)
        end
        if err or not Ignore.valid(proof) then return nil end
        if kind == "bool" and raw ~= true and raw ~= false and raw ~= 0 and raw ~= 1 then return nil end
        if kind == "int" and (type(raw) ~= "number" or raw ~= raw or raw % 1 ~= 0) then return nil end
        if kind == "float" and (type(raw) ~= "number" or raw ~= raw or math.abs(raw) == math.huge) then return nil end
        return value
    end

    -- Authored scenes own their exact actor while it is alive or pending cleanup.
    function Ignore.scene_actor(proof)
        local actor = proof and Live.friendly_owned and Live.friendly_owned[proof.handle]
        if actor and actor.proof and actor.proof.address == proof.address and actor.proof.network_id == proof.network_id
            and Ignore.valid(proof) then
            return true
        end
        for _, key in ipairs({ "lester_ride", "selected_effects", "player_setpieces" }) do
            if not Ignore.valid(proof) then return false end
            local scene = Live[key]
            if scene and type(scene.OwnsActor) == "function" then
                local ok, owned = pcall(scene.OwnsActor, proof.handle, proof.address, proof.network_id)
                if ok and owned == true then return Ignore.valid(proof) end
            end
            if scene and type(scene.OwnsNPCState) == "function" then
                local ok, owned = pcall(scene.OwnsNPCState, proof.handle, proof.address, proof.network_id)
                if ok and owned == true then return Ignore.valid(proof) end
            end
        end
        return false
    end

    function Ignore.scene_local_interaction(pid)
        local ride = Live.lester_ride
        if not ride or type(ride.LocalInteractionActive) ~= "function" then return false end
        local ok, active = pcall(ride.LocalInteractionActive, pid)
        return ok and active == true
    end

    -- Peds Ignore entry handoff begin
    function Ignore.entry_context(state, owner, pid, now)
        if state.entry_owner ~= owner.address then
            state.entry_owner = owner.address; state.entry_until = 0
            state.recent_entry_vehicle = nil
        end
        local enabled = Ignore.query(owner, "bool", 0x1CEA6BFDF248E5D9, 0, 23)
        local pressed = enabled == true and Ignore.query(owner, "bool", 0xF3A21BCD95725A4A, 0, 23) == true
        -- The on-foot result matters only to a pressed key or live entry window.
        -- Keep each performed query's complete identity fences; do not cache it.
        local on_foot, on_foot_read
        if pressed or now < (tonumber(state.entry_until) or 0) then
            on_foot = Ignore.query(owner, "bool", 0x01FEE67DB37F59B2, owner.handle)
            on_foot_read = true
        end
        if pressed and on_foot == true then state.entry_until = now + 1000 end
        local trying = Ignore.query(owner, "int", 0x814FA8BE5449445D, owner.handle)
        local entering = Ignore.query(owner, "bool", 0xBB062B2B5722478E, owner.handle) == true
        local jacking = Ignore.query(owner, "bool", 0x4AE4FF911DFB61DA, owner.handle) == true
        local vehicle
        if Ignore.number(trying) then
            local pointer = Ignore.read(function() return gta.HandleToPointer(trying) end)
            vehicle = pointer and Ignore.proof(pointer, owner.current, nil, owner.controller) or nil
            if vehicle and vehicle.handle ~= trying then vehicle = nil end
            if vehicle and Ignore.valid(vehicle) then
                state.recent_entry_vehicle = {
                    handle = vehicle.handle,
                    address = vehicle.address,
                    network_id = vehicle.network_id,
                    expires = now + 15000
                }
            end
        end
        -- Evaluate the retained scene callback before deciding the entry-window
        -- route: the callback can open that window reentrantly.
        local active = Ignore.valid(owner)
        if active then
            local scene_active = Ignore.scene_local_interaction(pid)
            if scene_active or vehicle ~= nil or entering or jacking then
                active = true
            elseif now < (tonumber(state.entry_until) or 0) then
                if not on_foot_read then
                    on_foot = Ignore.query(owner, "bool", 0x01FEE67DB37F59B2, owner.handle)
                end
                active = on_foot == true and now < (tonumber(state.entry_until) or 0)
            else
                active = false
            end
        end
        return { active = active == true, vehicle = vehicle, ped = owner.handle, owner = owner }
    end

    function Ignore.entry_global_gates(state, pid, entry, current, now)
        now = tonumber(now) or 0
        local refresh = now - (tonumber(state.global_gates_ms) or -100000) >= 250
        local changed = false
        for _, gate in ipairs({
            { "everyone_accepted",     H.SET_EVERYONE_IGNORE_PLAYER },
            { "police_accepted",       H.SET_POLICE_IGNORE_PLAYER },
            { "low_priority_accepted", IGNORE_LOW_PRIORITY_NATIVE },
        }) do
            if not current() then return false end
            -- Only relinquish a gate which this feature successfully set. Once
            -- yielded, do not keep writing false over unrelated code each frame.
            if (not entry.active and (refresh or state[gate[1]] ~= true))
                or (entry.active and state[gate[1]] == true) then
                local accepted, _, err = invoke_void_detail(gate[2], pid, not entry.active)
                if accepted == true and err == nil then
                    state[gate[1]] = not entry.active; changed = true
                end
            end
        end
        if not entry.active and changed then state.global_gates_ms = now end
        return current()
    end

    function Ignore.entry_interaction(entry, proof)
        if not Ignore.valid(proof) then return false end
        if Ignore.scene_actor(proof) then return true end
        if not entry or not entry.active then return false end
        local vehicle = entry.vehicle
        if vehicle and Ignore.valid(vehicle) then
            local in_vehicle = Ignore.query(proof, "bool", H.IS_PED_IN_ANY_VEHICLE, proof.handle, false)
            if in_vehicle == true and Ignore.query(proof, "int", H.GET_VEHICLE_PED_IS_IN, proof.handle, false) == vehicle.handle then
                return true
            end
        end
        -- After the driver leaves its seat, the actual jacker relationship keeps
        -- that interaction free of ignore-task clearing until the animation ends.
        return Ignore.query(proof, "bool", 0x9A497FE2DF198913, proof.handle) == true
            and Ignore.query(proof, "int", 0x9B128DC36C1E04CF, proof.handle) == entry.ped
    end

    function Ignore.release_entry_ped(state, proof, keep_calm)
        if not Ignore.valid(proof) then return false end
        local managed = state.managed and state.managed[proof.address]
        if not managed then return true end
        if managed.handle ~= proof.handle or managed.network_id ~= proof.network_id then return false end
        -- Reuse the existing compare-before-restore path, scoped to this exact
        -- occupant. A failed restore keeps its debt; other NPCs remain managed.
        local borrowed = managed
        if keep_calm then
            borrowed = {
                handle = managed.handle,
                address = managed.address,
                network_id = managed.network_id,
                config_flags = { [17] = managed.config_flags[17] }
            }
        end
        local scope = { managed = { [proof.address] = borrowed } }
        Ignore.restore_managed(scope)
        if scope.managed[proof.address] then return false end
        if keep_calm then
            managed.entry_released = true
        else
            state.managed[proof.address] = nil
        end
        state.entry_restores = (tonumber(state.entry_restores) or 0) + 1
        return true
    end

    function Ignore.release_entry_driver(state, entry)
        local vehicle = entry and entry.vehicle
        if not vehicle or not Ignore.valid(vehicle) then return end
        local driver = Ignore.query(vehicle, "int", H.GET_PED_IN_VEHICLE_SEAT, vehicle.handle, -1, false)
        if not Ignore.number(driver) or driver == entry.ped then return end
        local pointer = Ignore.read(function() return gta.HandleToPointer(driver) end)
        local proof = pointer and Ignore.proof(pointer, entry.owner.current, nil, entry.owner.controller) or nil
        if proof and proof.handle == driver and Ignore.query(proof, "bool", H.IS_PED_A_PLAYER, driver) == false
            and Ignore.entry_interaction(entry, proof) then
            Ignore.remember_driver(state, entry, proof, state.current_ms or 0)
            Ignore.release_entry_ped(state, proof, not Ignore.scene_actor(proof))
        end
        if proof then proof.closed = true end
    end

    -- Peds Ignore entry handoff end

    -- Peds Ignore response recovery begin
    function Ignore.held_by_gravity(proof)
        local weapons = module_context and module_context.CScript and module_context.CScript.Weapons
        if not weapons or type(weapons.GravitySnapshot) ~= "function" then return false end
        local ok, snapshot = pcall(weapons.GravitySnapshot)
        return ok and type(snapshot) == "table" and snapshot.held == proof.handle
    end

    function Ignore.can_task(proof)
        if not Ignore.valid(proof) or Ignore.held_by_gravity(proof) or Ignore.scene_actor(proof)
            or Ignore.query(proof, "bool", H.IS_PED_A_PLAYER, proof.handle) ~= false
            or Ignore.query(proof, "bool", 0x3317DEDB88C95038, proof.handle, true) ~= false
            or Ignore.query(proof, "bool", 0x47E4E977581C5B55, proof.handle) ~= false
            or Ignore.query(proof, "bool", 0x9A497FE2DF198913, proof.handle) ~= false
            or Ignore.query(proof, "bool", 0xBB062B2B5722478E, proof.handle) ~= false then
            return false
        end
        local networked = Ignore.query(proof, "bool", 0xC7827959479DCC78, proof.handle)
        return networked ~= nil and (not networked
                or Ignore.query(proof, "bool", 0x01BF60A500E28887, proof.handle) == true)
            and not Ignore.scene_actor(proof) and Ignore.valid(proof)
    end

    function Ignore.task(proof, hash, ...)
        if not Ignore.can_task(proof) then return false end
        local accepted, _, err = invoke_void_detail(hash, proof.handle, ...)
        return accepted == true and err == nil and Ignore.valid(proof)
    end

    function Ignore.request_task_control(state, proof, entry, now)
        if not entry or now - (entry.last_control_ms or -100000) < 300
            or not Ignore.valid(proof) or Ignore.scene_actor(proof) or Ignore.held_by_gravity(proof)
            or Ignore.query(proof, "bool", H.IS_PED_A_PLAYER, proof.handle) ~= false
            or Ignore.query(proof, "bool", 0x3317DEDB88C95038, proof.handle, true) ~= false
            or Ignore.query(proof, "bool", 0x47E4E977581C5B55, proof.handle) ~= false
            or Ignore.query(proof, "bool", 0xC7827959479DCC78, proof.handle) ~= true
            or Ignore.query(proof, "bool", 0x01BF60A500E28887, proof.handle) ~= false then
            return false
        end
        if now - (state.control_window_ms or -100000) >= 100 then
            state.control_window_ms, state.control_requests_in_window = now, 0
        end
        if (state.control_requests_in_window or 0) >= 4 or not Ignore.valid(proof)
            or Ignore.scene_actor(proof) or not Ignore.valid(proof) then
            return false
        end
        entry.last_control_ms = now
        state.control_requests_in_window = (state.control_requests_in_window or 0) + 1
        local accepted, _, err = invoke_void_detail(0xB69317BF5E782347, proof.handle)
        state.last_reason = "waiting for NPC control"
        return accepted == true and err == nil
    end

    function Ignore.vehicle_task(proof, vehicle, hash, ...)
        if not Ignore.can_task(proof) or not Ignore.valid(vehicle) then return false end
        local networked = Ignore.query(vehicle, "bool", 0xC7827959479DCC78, vehicle.handle)
        if networked == nil or (networked and Ignore.query(vehicle, "bool", 0x01BF60A500E28887, vehicle.handle) ~= true)
            or not Ignore.valid(proof) or not Ignore.valid(vehicle) then
            return false
        end
        local args = { ... }
        if hash == 0xC20E50AA46D09CA8 then
            if Ignore.query(vehicle, "int", H.GET_PED_IN_VEHICLE_SEAT, vehicle.handle, args[2], false) ~= 0 then return false end
        elseif hash == 0x7AA80209BDA643EB then
            if Ignore.query(proof, "int", H.GET_VEHICLE_PED_IS_IN, proof.handle, false) ~= vehicle.handle
                or Ignore.query(vehicle, "int", H.GET_PED_IN_VEHICLE_SEAT, vehicle.handle, -1, false) ~= 0 then
                return false
            end
        elseif hash == 0x480142959D337D00 then
            if Ignore.query(vehicle, "int", H.GET_PED_IN_VEHICLE_SEAT, vehicle.handle, -1, false) ~= proof.handle then return false end
        end
        if not Ignore.valid(proof) or not Ignore.valid(vehicle) or Ignore.held_by_gravity(proof)
            or Ignore.scene_actor(proof) or not Ignore.valid(proof) or not Ignore.valid(vehicle) then
            return false
        end
        local accepted, _, err = invoke_void_detail(hash, proof.handle, vehicle.handle, table.unpack(args))
        return accepted == true and err == nil and Ignore.valid(proof) and Ignore.valid(vehicle)
    end

    function Ignore.recover_fear(state, proof, entry, now, fleeing, looking)
        if not entry or now - (entry.last_fear_ms or -100000) < 1000
            or not Ignore.valid(proof) then
            return false
        end
        if not fleeing and now - (entry.last_fear_probe_ms or -100000) < 600 then return false end
        entry.last_fear_probe_ms = now
        local fear = fleeing == true
        if not fear then
            -- Scripted shopkeepers can cower without reporting IS_PED_FLEEING.
            -- Task IDs: hands up, cower scenario, cower, react to gun aimed at.
            for _, task in ipairs({ 0, 106, 126, 144 }) do
                if Ignore.query(proof, "bool", 0xB0760331C7AA4155, proof.handle, task) == true then
                    fear = true; break
                end
            end
        end
        if not fear then return false end
        if not Ignore.can_task(proof) then
            Ignore.request_task_control(state, proof, entry, now); return false
        end
        entry.last_fear_ms = now
        local seated = Ignore.query(proof, "bool", H.IS_PED_IN_ANY_VEHICLE, proof.handle, false)
        if seated == nil then return false end
        local vehicle_handle = seated and Ignore.query(proof, "int", H.GET_VEHICLE_PED_IS_IN, proof.handle, false) or nil
        local pointer = Ignore.number(vehicle_handle) and
            Ignore.read(function() return gta.HandleToPointer(vehicle_handle) end)
        local vehicle = pointer and Ignore.proof(pointer, proof.current, nil, proof.controller) or nil
        if seated and (not vehicle or vehicle.handle ~= vehicle_handle
                or Ignore.query(vehicle, "int", H.GET_PED_IN_VEHICLE_SEAT, vehicle.handle, -1, false) ~= proof.handle) then
            return false
        end
        if not Ignore.task(proof, 0xE1EF3C1216AFF2CD) then return false end -- CLEAR_PED_TASKS
        local resumed
        if seated then
            resumed = Ignore.vehicle_task(proof, vehicle, 0x480142959D337D00, 12.0, 786603)
        else
            resumed = Ignore.task(proof, 0xBB9CE077274F6A1B, 10.0, 10)
        end
        if resumed then state.cleared_responses = math.min(999999, (state.cleared_responses or 0) + 1) end
        return resumed == true
    end

    function Ignore.remember_driver(state, entry, proof, now)
        local vehicle = entry and entry.vehicle
        if not vehicle or not Ignore.valid(vehicle) or not Ignore.valid(proof) then return false end
        local model = Ignore.query(vehicle, "int", H.GET_ENTITY_MODEL, vehicle.handle)
        if not model or Ignore.query(vehicle, "bool", 0x7F6DB52EEFC96DF8, model) ~= true
            or not Ignore.valid(proof) then
            return false
        end
        state.displaced = state.displaced or {}
        for address, record in pairs(state.displaced) do
            if now >= record.expires then state.displaced[address] = nil end
        end
        local count = 0; for _ in pairs(state.displaced) do count = count + 1 end
        if count >= 8 and not state.displaced[proof.address] then return false end
        state.displaced[proof.address] = {
            handle = proof.handle,
            address = proof.address,
            network_id = proof.network_id,
            vehicle = vehicle.handle,
            vehicle_address = vehicle.address,
            vehicle_network = vehicle.network_id,
            expires = now + 120000,
            last_task = -100000
        }
        return true
    end

    function Ignore.observe_entry_victim(state, entry, proof, now)
        if not Ignore.valid(proof) or Ignore.scene_actor(proof) then return false end
        if state.displaced and state.displaced[proof.address] then return true end
        local vehicle = entry and entry.vehicle
        local recent = state.recent_entry_vehicle
        if not vehicle and recent and now < recent.expires then
            local pointer = Ignore.read(function() return gta.HandleToPointer(recent.handle) end)
            vehicle = pointer and Ignore.proof(pointer, proof.current, nil, proof.controller) or nil
            if not vehicle or vehicle.handle ~= recent.handle or vehicle.address ~= recent.address
                or vehicle.network_id ~= recent.network_id then
                vehicle = nil
            end
        end
        if not vehicle or not Ignore.valid(vehicle) then return false end
        local jacker = Ignore.query(proof, "int", 0x9B128DC36C1E04CF, proof.handle)
        local local_handle = entry and entry.ped or local_ped()
        local displaced = jacker == local_handle
        if not displaced and recent and now < recent.expires then
            displaced = Ignore.query(proof, "bool", H.GET_PED_CONFIG_FLAG, proof.handle, 334, true) == true
                and Ignore.query(vehicle, "int", H.GET_PED_IN_VEHICLE_SEAT, vehicle.handle, -1, false) == local_handle
        end
        if not displaced or Ignore.query(proof, "int", H.GET_VEHICLE_PED_IS_IN, proof.handle, true) ~= vehicle.handle
            or not Ignore.valid(vehicle) then
            return false
        end
        return Ignore.remember_driver(state, { vehicle = vehicle }, proof, now)
    end

    function Ignore.resume_driver(state, proof, now)
        local record = state.displaced and state.displaced[proof.address]
        if not record then return false end
        if record.handle ~= proof.handle or record.network_id ~= proof.network_id or now >= record.expires then
            state.displaced[proof.address] = nil; return false
        end
        if not Ignore.can_task(proof) then
            Ignore.request_task_control(state, proof, record, now); return true
        end
        local pointer = Ignore.read(function() return gta.HandleToPointer(record.vehicle) end)
        local vehicle = pointer and Ignore.proof(pointer, proof.current, nil, proof.controller) or nil
        if not vehicle or vehicle.handle ~= record.vehicle or vehicle.address ~= record.vehicle_address
            or vehicle.network_id ~= record.vehicle_network then
            state.displaced[proof.address] = nil; return false
        end
        local function current() return Ignore.can_task(proof) and Ignore.valid(vehicle) end
        local driver = Ignore.query(vehicle, "int", H.GET_PED_IN_VEHICLE_SEAT, vehicle.handle, -1, false)
        local in_vehicle = Ignore.query(proof, "bool", H.IS_PED_IN_ANY_VEHICLE, proof.handle, false)
        local seated = in_vehicle == true and
            Ignore.query(proof, "int", H.GET_VEHICLE_PED_IS_IN, proof.handle, false) == vehicle.handle
        if seated and driver == proof.handle and current() then
            if Ignore.vehicle_task(proof, vehicle, 0x480142959D337D00, 12.0, 786603) then state.displaced[proof.address] = nil end
            return true
        end
        if now - record.last_task < 11000 then return true end
        if seated then
            if driver == 0 and Ignore.query(vehicle, "int", H.GET_PED_IN_VEHICLE_SEAT, vehicle.handle, 0, false) == proof.handle
                and current() and Ignore.vehicle_task(proof, vehicle, 0x7AA80209BDA643EB, 0) then
                record.last_task = now
            end
            return true
        end
        if in_vehicle ~= false or driver == nil or (driver ~= 0 and driver ~= local_ped()) then return false end
        local seat = driver == local_ped() and 0 or -1
        if Ignore.query(vehicle, "int", H.GET_PED_IN_VEHICLE_SEAT, vehicle.handle, seat, false) ~= 0
            or Ignore.query(proof, "bool", 0x751B70C3D034E187, proof.handle, vehicle.handle, 30.0, 30.0, 10.0, false, true, 0) ~= true then
            return false
        end
        local speed = Ignore.query(vehicle, "float", 0xD5037BA82E12416F, vehicle.handle)
        if speed == nil or speed > 2.0 or not current() then return false end
        -- Normal walking entry only; occupied seats are never jacked or warped.
        if Ignore.vehicle_task(proof, vehicle, 0xC20E50AA46D09CA8, 10000, seat, 1.0, 1, 0) then
            record.last_task = now; return true
        end
        return false
    end

    -- Peds Ignore response recovery end

    function Ignore.suppress_ambient_frame(state, owner, pid)
        local complete = true
        for _, request in ipairs(IGNORE_AMBIENT_FRAME_NATIVES) do
            if not Ignore.valid(owner) then return false end
            local accepted, _, err
            if request.player then
                accepted, _, err = invoke_void_detail(request.hash, pid)
            elseif request.toggle ~= nil then
                accepted, _, err = invoke_void_detail(request.hash, request.toggle)
            else
                accepted, _, err = invoke_void_detail(request.hash)
            end
            state[request.key] = accepted == true and err == nil
            if not state[request.key] then
                complete = false
                state.last_reason = "partial: " .. request.label .. " unavailable"
            end
        end
        if not Ignore.valid(owner) then return false end
        if complete then state.last_reason = "frame suppression submitted" end
        local signature = tostring(state.shocking_accepted) .. ":" .. tostring(state.agitation_accepted)
            .. ":" .. tostring(state.witness_accepted) .. ":" .. tostring(state.ambient_block_accepted)
        if signature ~= state.last_log_signature then
            state.last_log_signature = signature
            log_info(("Peds Ignore frame gates: shocking=%s agitation=%s witnessCalls=%s ambientBlock=%s; invocation only, behavior requires live test.")
                :format(tostring(state.shocking_accepted), tostring(state.agitation_accepted),
                    tostring(state.witness_accepted), tostring(state.ambient_block_accepted)))
        end
        return true
    end

    function Ignore.rendered_pointers(entries)
        if type(entries) ~= "table" and type(entries) ~= "userdata" then return nil end
        local pointers = {}
        local ok = pcall(function()
            -- Cherax can expose its public iterable as userdata, not a Lua
            -- table. Protect iteration itself and discard partial snapshots.
            for _, item in pairs(entries) do
                if #pointers >= IGNORE_POOL_LIMIT then break end
                pointers[#pointers + 1] = item
            end
        end)
        return ok and pointers or nil
    end

    function Ignore.managed_current(entry)
        if type(entry) ~= "table" or not Ignore.number(entry.handle) then return false end
        if not (gta and type(gta.HandleToPointer) == "function") then return false end
        local ok, pointer = pcall(gta.HandleToPointer, entry.handle)
        if not ok or pointer == nil or Ignore.address(pointer) ~= entry.address then return false end
        local network_id, known = Ignore.network(pointer)
        return known and network_id == entry.network_id
    end

    function Ignore.read_config_flag(proof, flag)
        return Ignore.query(proof, "bool", H.GET_PED_CONFIG_FLAG, proof.handle, flag, true)
    end

    function Ignore.apply_config_flag(state, proof, entry, flag, desired)
        if not Ignore.valid(proof) then return false end
        if entry.config_flags[flag] == nil then
            local original = Ignore.read_config_flag(proof, flag)
            if original == nil or not Ignore.valid(proof) then return false end
            entry.config_flags[flag] = { original = original == true, applied = desired == true }
        end
        local accepted, _, err = invoke_void_detail(H.SET_PED_CONFIG_FLAG, proof.handle, flag, desired == true)
        return accepted == true and err == nil and Ignore.valid(proof)
    end

    function Ignore.remember_blocked(state, proof, now)
        if not Ignore.valid(proof) then return false, nil, false end
        local existing = state.managed and state.managed[proof.address]
        -- proof itself has already round-tripped handle/address/NetObject. Avoid a
        -- second HandleToPointer/NetObject proof for every managed ped visit.
        if existing and (existing.handle ~= proof.handle or existing.network_id ~= proof.network_id) then
            state.managed[proof.address] = nil; existing = nil
        end
        local fresh = existing == nil
        local entry = existing or {
            handle = proof.handle,
            address = proof.address,
            network_id = proof.network_id,
            config_flags = {},
            last_persist_ms = -100000,
            last_relationship_ms = -100000,
            last_reaction_ms = -100000,
            last_vehicle_ms = -100000
        }
        if fresh then
            local ped_type = Ignore.query(proof, "int", H.GET_PED_TYPE, proof.handle)
            entry.ped_type = ped_type
            entry.law = IGNORE_LAW_TYPES[tonumber(ped_type)] == true
            -- Snapshot every flag before the first write. If any read is unavailable,
            -- make zero persistent changes to this identity.
            for flag, desired in pairs(IGNORE_PED_CONFIG) do
                local original = Ignore.read_config_flag(proof, flag)
                if original == nil or not Ignore.valid(proof) then return false, nil, false end
                entry.config_flags[flag] = { original = original == true, applied = desired == true }
            end
            if entry.law then
                for flag, desired in pairs(IGNORE_LAW_CONFIG) do
                    local original = Ignore.read_config_flag(proof, flag)
                    if original == nil or not Ignore.valid(proof) then return false, nil, false end
                    entry.config_flags[flag] = { original = original == true, applied = desired == true }
                end
            end
            -- Retain ownership before mutation so even a partially rejected native
            -- sequence has a reversible cleanup record.
            state.managed[proof.address] = entry
        end
        local refresh_ms = entry.law and IGNORE_TIMING.law or IGNORE_TIMING.persist
        local refresh = fresh or entry.entry_released or
            (tonumber(now) or 0) - (tonumber(entry.last_persist_ms) or -100000) >= refresh_ms
        if not refresh then return true, entry, false end
        local all_ok = true
        for flag, desired in pairs(IGNORE_PED_CONFIG) do
            if not Ignore.apply_config_flag(state, proof, entry, flag, desired) then all_ok = false end
        end
        if entry.law then
            for flag, desired in pairs(IGNORE_LAW_CONFIG) do
                if not Ignore.apply_config_flag(state, proof, entry, flag, desired) then all_ok = false end
            end
        end
        if not Ignore.valid(proof) then return false, entry, fresh end
        local accepted_a, _, error_a = invoke_void_detail(IGNORE_PED_BLOCK_NATIVE, proof.handle, true)
        -- Own the persistent flag directly. Enqueuing a blocking task here can
        -- reapply it after OFF and requires a native script context to undo.
        all_ok = all_ok and accepted_a == true and error_a == nil
        if all_ok and Ignore.valid(proof) then
            entry.entry_released = nil
            entry.last_persist_ms = tonumber(now) or 0
            if fresh then
                state.blocked_peds = math.min(999999, (state.blocked_peds or 0) + 1)
                if entry.law then state.law_managed = math.min(999999, (state.law_managed or 0) + 1) end
            else
                state.reasserted_peds = math.min(999999, (state.reasserted_peds or 0) + 1)
            end
            return true, entry, fresh
        end
        state.block_failures = math.min(999999, (state.block_failures or 0) + 1)
        return false, entry, fresh
    end

    function Ignore.restore_managed(state)
        local restored = 0
        for address, entry in pairs(state.managed or {}) do
            local pending = false
            if Ignore.managed_current(entry) then
                local handle = entry.handle
                for flag, snapshot in pairs(entry.config_flags or {}) do
                    local current, raw, err = invoke_bool_detail(H.GET_PED_CONFIG_FLAG, handle, flag, true)
                    local readable = err == nil and (raw == true or raw == false or raw == 0 or raw == 1)
                    if readable and current == (snapshot.applied == true) then
                        if flag == 17 then invoke_void_detail(IGNORE_PED_BLOCK_NATIVE, handle, snapshot.original == true) end
                        if Ignore.managed_current(entry) then
                            invoke_void_detail(H.SET_PED_CONFIG_FLAG, handle, flag, snapshot.original == true)
                            current, raw, err = invoke_bool_detail(H.GET_PED_CONFIG_FLAG, handle, flag, true)
                            readable = err == nil and (raw == true or raw == false or raw == 0 or raw == 1)
                        end
                        if not readable or current ~= (snapshot.original == true) then pending = true end
                    elseif not readable then
                        pending = true
                    end
                    -- A different current value belongs to another writer; yield.
                end
                if not pending then restored = restored + 1 end
            end
            if not pending then state.managed[address] = nil end
        end
        state.restored_peds = (state.restored_peds or 0) + restored
        return restored
    end

    -- Relationship changes are directional. NPC de-escalation must not turn
    -- the local player's targets into friends or change mission damage rules.
    function Ignore.relationship_value(value)
        return type(value) == "number" and value == value and value % 1 == 0
            and ((value >= 0 and value <= 5) or value == 255)
    end

    function Ignore.relationship_read(from, to)
        local ok, value, raw, err = pcall(invoke_int_detail, H.GET_RELATIONSHIP_BETWEEN_GROUPS, from, to)
        if ok and err == nil and value == raw and Ignore.relationship_value(raw) then return raw end
    end

    function Ignore.restore_relationship_direction(entry, field, from, to)
        local original = entry[field]
        if original == nil then return true end
        if not Ignore.relationship_value(original) then return false end
        local generation = entry.generation or 0
        local function current_owner()
            return generation == (entry.generation or 0) and entry[field] == original
        end
        local current = Ignore.relationship_read(from, to)
        if current == nil or not current_owner() then return false end
        -- A distinct newer value belongs to the game/another owner. Never
        -- replace it with an older snapshot, and never treat failed reads as 0.
        if current == original or current ~= 0 then
            entry[field] = nil; return true
        end
        if Ignore.relationship_read(from, to) ~= current or not current_owner() then return false end
        local ok, accepted, raw, err = pcall(invoke_void_detail, H.SET_RELATIONSHIP_BETWEEN_GROUPS, original, from, to)
        if not ok or accepted ~= true or raw == false or err ~= nil or not current_owner() then return false end
        if Ignore.relationship_read(from, to) ~= original or not current_owner() then return false end
        entry[field] = nil
        return true
    end

    function Ignore.restore_relationships(state, reverse_only, only_key)
        local restored = 0
        for key, entry in pairs(state.relationships or {}) do
            if only_key == nil or only_key == key then
                if entry.busy then
                    -- A host callback may request OFF before its pending native
                    -- effect becomes visible. Retain the record until that call exits.
                    entry.generation = (entry.generation or 0) + 1
                    entry.release_pending = true
                else
                    entry.busy = true
                    local generation = entry.generation or 0
                    local ok, complete = pcall(function()
                        local done = true
                        if entry.reverse ~= nil then
                            local released = Ignore.restore_relationship_direction(entry, "reverse", entry.player_group,
                                entry.ped_group)
                            if released then restored = restored + 1 else done = false end
                        end
                        if not reverse_only and entry.forward ~= nil then
                            local released = Ignore.restore_relationship_direction(entry, "forward", entry.ped_group,
                                entry.player_group)
                            if released then restored = restored + 1 else done = false end
                        end
                        return done
                    end)
                    entry.busy = nil
                    if ok and complete and generation == (entry.generation or 0)
                        and entry.forward == nil and entry.reverse == nil
                        and state.relationships[key] == entry then
                        state.relationships[key] = nil
                    end
                end
            end
        end -- optional single-record drain for a rapid re-enable
        state.relationship_restores = (state.relationship_restores or 0) + restored
        return restored
    end

    function Ignore.apply_relationship(state, proof, player_group, now, urgent)
        if not Ignore.valid(proof) or type(player_group) ~= "number" or player_group == 0 then return false end
        local ped_group = Ignore.query(proof, "int", H.GET_PED_RELATIONSHIP_GROUP_HASH, proof.handle)
        if not Ignore.valid(proof) or type(ped_group) ~= "number" or ped_group == 0 or ped_group == player_group then return false end
        local key = tostring(ped_group) .. ":" .. tostring(player_group)
        state.relationships = state.relationships or {}
        local entry = state.relationships[key]
        if entry and entry.busy then return false end
        if entry and entry.release_pending then
            Ignore.restore_relationships(state, false, key)
            if not Ignore.valid(proof) then return false end
            entry = state.relationships[key]
            if entry then return false end
        end
        if not entry then
            local forward = Ignore.relationship_read(ped_group, player_group)
            if forward == nil or not Ignore.valid(proof)
                or state.relationships[key] ~= nil then
                return false
            end
            -- A reentrant baseline read may have installed a newer owner.
            -- No reverse baseline: fresh records never own PLAYER -> NPC state.
            entry = {
                ped_group = ped_group,
                player_group = player_group,
                forward = forward,
                applied = 0,
                last_apply_ms = -100000,
                generation = 0
            }
            state.relationships[key] = entry
        end
        entry.busy = true
        local generation = entry.generation or 0
        local function current()
            return state.relationships[key] == entry and not entry.release_pending
                and generation == (entry.generation or 0) and Ignore.valid(proof)
        end
        local ok, applied = pcall(function()
            -- Older builds owned both directions. Release their outgoing half
            -- first instead of perpetuating accidental friendly-target behavior.
            if entry.reverse ~= nil and not Ignore.restore_relationship_direction(
                    entry, "reverse", entry.player_group, entry.ped_group) then
                return false
            end
            if not current() then return false end
            local age = (tonumber(now) or 0) - (tonumber(entry.last_apply_ms) or -100000)
            local threshold = urgent and 250 or IGNORE_TIMING.relationship
            if (entry.applied or 0) > 0 and age < threshold then return true end
            local value = Ignore.relationship_read(ped_group, player_group)
            if value == nil or not current() then return false end
            if value ~= 0 then
                -- Capture a distinct fresh game value before reasserting our
                -- inbound-only intent; this is the baseline a later OFF restores.
                entry.forward = value
                local accepted, raw, err = invoke_void_detail(H.SET_RELATIONSHIP_BETWEEN_GROUPS, 0, ped_group,
                    player_group)
                if accepted ~= true or raw == false or err ~= nil or not current() then return false end
                if Ignore.relationship_read(ped_group, player_group) ~= 0 or not current() then return false end
            end
            entry.applied = (entry.applied or 0) + 1
            entry.last_apply_ms = tonumber(now) or 0
            state.relationship_overrides = math.min(999999, (state.relationship_overrides or 0) + 1)
            return true
        end)
        entry.busy = nil
        if ok and applied == true and current() then return true end
        state.relationship_failures = math.min(999999, (state.relationship_failures or 0) + 1)
        return false
    end

    function Ignore.law_context(state, owner, pid, now)
        local cached = state.law_context
        if cached and cached.player == pid and cached.ped == owner.handle and now - cached.time < 250 then return cached end
        local context = { player = pid, ped = owner.handle, time = now, isolated = false }
        state.law_context = context
        context.wanted = Ignore.query(owner, "int", 0xE28E54788CE8F12D, pid) -- GET_PLAYER_WANTED_LEVEL
        if not context.wanted or context.wanted <= 0 then return context end
        -- Search tasks don't expose a target. Admit them only when no other
        -- player is near the local search area; unknown reads exclude the route.
        for slot = 0, 31 do
            if slot ~= pid then
                local active = Ignore.query(owner, "bool", 0xB8DFD30D6973E135, slot)
                if active == nil then return context end
                if active then
                    local remote = Ignore.query(owner, "int", 0x43A66C31C68491C0, slot)
                    if not Ignore.number(remote) then return context end
                    local near = Ignore.query(owner, "bool", 0x751B70C3D034E187, remote, owner.handle, 100.0, 100.0,
                        100.0, false, true, 0)
                    if near ~= false then return context end
                end
            end
        end
        context.isolated = Ignore.valid(owner)
        return context
    end

    function Ignore.law_response(state, proof, entry, context, now, local_target, looking)
        if not entry or not entry.law or not Ignore.valid(proof)
            or now - (tonumber(entry.last_law_clear_ms) or -100000) < 750 then
            return false
        end
        local handle = proof.handle
        -- A cop may keep an aim task without entering combat or gaining stars.
        -- Headtracking proves the local subject; aiming alone does not. Search
        -- tasks still require the isolated wanted context because they expose no
        -- target. Never clear a task merely because a cop is nearby or alert.
        local direct = looking == true and Ignore.number(local_target)
            and Ignore.read_config_flag(proof, 78) == true -- IsAimingGun
        if not direct and (not context or not context.isolated
                or (tonumber(context.wanted) or 0) <= 0) then
            return false
        end
        local target = direct and local_target or context.ped
        if Ignore.query(proof, "bool", H.IS_ENTITY_A_MISSION_ENTITY, handle) ~= false
            or Ignore.query(proof, "bool", H.IS_PED_IN_COMBAT, handle, 0) ~= false
            or Ignore.query(proof, "bool", 0x751B70C3D034E187, handle, target, 60.0, 60.0, 60.0, false, true, 0) ~= true then
            return false
        end
        -- Documented task indices: PoliceWantedResponse / SwatWantedResponse.
        if not direct then
            if Ignore.query(proof, "int", 0x7196842CB375CDB3, handle) ~= context.player then return false end
            local responding = Ignore.query(proof, "bool", 0xB0760331C7AA4155, handle, 69)
            if responding ~= true then responding = Ignore.query(proof, "bool", 0xB0760331C7AA4155, handle, 72) end
            if responding ~= true then return false end
        end
        local networked = Ignore.query(proof, "bool", 0xC7827959479DCC78, handle)
        if networked == nil or (networked and Ignore.query(proof, "bool", 0x01BF60A500E28887, handle) ~= true)
            or not Ignore.valid(proof) then
            return false
        end
        local accepted, _, err = invoke_void_detail(0xE1EF3C1216AFF2CD, handle) -- CLEAR_PED_TASKS
        if accepted ~= true or err ~= nil or not Ignore.valid(proof) then return false end
        entry.last_law_clear_ms = now
        state.law_responses_cleared = (tonumber(state.law_responses_cleared) or 0) + 1
        return true
    end

    local function restore_peds_ignore(reason)
        local state = State.peds_ignore
        -- Restore owned blocking flags on still-current NPCs before dropping the controller.
        Ignore.restore_managed(state)
        if State.peds_ignore ~= state then return false end
        Ignore.restore_relationships(state)
        if State.peds_ignore ~= state then return false end
        if state.enabled and state.player_id == local_player_id() then
            invoke_void(H.SET_EVERYONE_IGNORE_PLAYER, state.player_id, false)
            if State.peds_ignore ~= state then return false end
            if State.peds_ignore == state and state.player_id == local_player_id() then
                invoke_void(H.SET_POLICE_IGNORE_PLAYER, state.player_id, false)
                if State.peds_ignore ~= state then return false end
                invoke_void(IGNORE_LOW_PRIORITY_NATIVE, state.player_id, false)
                if State.peds_ignore ~= state then return false end
            end
        end
        if next(state.managed or {}) or next(state.relationships or {}) then
            state.enabled = true -- Keep OFF cleanup eligible for a later gameplay retry.
            state.restore_pending = true
            state.last_reason = reason
            return false
        end
        -- A nested cleanup/re-enable may install a newer controller. Only the
        -- still-current owner may reset state after native host callbacks.
        if State.peds_ignore ~= state then return false end
        State.peds_ignore = {
            enabled = false,
            local_ped = 0,
            player_id = nil,
            relationships = {},
            managed = {},
            scan_cursor = 0,
            last_scan_ms = -100000,
            scan_source = "idle",
            rendered = 0,
            law_managed = 0,
            helicopter_managed = 0,
            mission_managed = 0,
            reasserted_peds = 0,
            relationship_overrides = 0,
            relationship_failures = 0,
            relationship_restores = 0,
            vehicle_passthrough = 0,
            hard_clears = 0,
            last_firing_amnesty_ms = -100000,
            last_reason = reason
        }
    end

    local function apply_peds_ignore(now, ped, force_scan)
        local state = State.peds_ignore
        local pid = local_player_id()
        if not started or not is_on("peds_ignore") then return false end
        state.source_applied = false
        state.current_ms = now
        state.shocking_accepted, state.agitation_accepted, state.witness_accepted = false, false, false
        local owner_address, owner_network
        local function current()
            if not started or State.peds_ignore ~= state or not is_on("peds_ignore")
                or local_player_id() ~= pid then
                return false
            end
            local matched
            if owner_address then
                matched = Ignore.owner_current(owner_address, owner_network)
            else
                matched = local_ped() == ped
            end
            return matched and local_player_id() == pid and is_on("peds_ignore")
                and started and State.peds_ignore == state
        end
        if not current() or not invoke_bool(0x5E9564D8246B909A, pid) or not current() then
            if State.peds_ignore == state then restore_peds_ignore("owner unavailable") end
            return false
        end
        state.enabled, state.local_ped, state.player_id = true, ped, pid
        local pointer = Ignore.read(function() return gta.GetLocalPed() end)
        local address = pointer and Ignore.address(pointer)
        local network, known = Ignore.network(pointer)
        if not address or not known then
            state.last_reason = "owner-proof-unavailable"; return false
        end
        -- Local ownership is checked through a fresh pointer on every guard.
        -- Avoid repeating a native script-ped lookup around every NPC flag.
        owner_address, owner_network = address, network
        local owner = Ignore.proof(pointer, current, ped, state)
        if not owner or owner.handle ~= ped then
            state.last_reason = "owner-proof-unavailable"; return false
        end
        local entry_handoff = Ignore.entry_context(state, owner, pid, now)
        if not Ignore.entry_global_gates(state, pid, entry_handoff, current, now) then return false end
        if entry_handoff.active then
            state.last_reason = "vehicle entry handoff"
            Ignore.release_entry_driver(state, entry_handoff)
        end
        -- GTA's own firing-amnesty path suppresses the periodic shots-fired crime
        -- report that can wake wanted/searching law peds even after their local
        -- relationship/task response was muted. It expires naturally when the
        -- toggle stops, so no persistent wanted-state write needs restoration.
        if now - (tonumber(state.last_firing_amnesty_ms) or -100000) >= 400 then
            local amnesty, _, amnesty_err = invoke_void_detail(0xBF9BD71691857E48, 900) -- START_FIRING_AMNESTY
            if amnesty == true and amnesty_err == nil then state.last_firing_amnesty_ms = now end
        end
        local scan_allowance = Ignore.scan_allowance(state, now, force_scan == true)
        -- Reset/ambient gates continue every game frame; expensive
        -- rendered-pool enumeration and per-NPC proof runs at most every
        -- 90 ms, except during a live vehicle-entry handoff.
        local scan_due = scan_allowance > 0 and (force_scan == true
            or entry_handoff.active or now >= (state.next_pool_scan_ms or 0))
        if scan_due then state.next_pool_scan_ms = now + IGNORE_POOL_SCAN_INTERVAL_MS end
        -- One-time legacy reverse-direction cleanup, including groups whose
        -- peds have left the rendered pool. Unknown reads remain retryable.
        if scan_due and state.relationship_schema ~= 2
            and now - (state.last_relationship_migration_ms or -100000) >= 250 then
            state.last_relationship_migration_ms = now
            Ignore.restore_relationships(state, true)
            local pending = false
            for _, relationship in pairs(state.relationships or {}) do
                if relationship.reverse ~= nil or relationship.busy then
                    pending = true; break
                end
            end
            if not pending then state.relationship_schema = 2 end
            if not current() then return false end
        end
        local player_group = state.player_group
        if scan_due then
            player_group = invoke_int(H.GET_PED_RELATIONSHIP_GROUP_HASH, ped); state.player_group = player_group
        end
        local law_context = scan_due and not entry_handoff.active and Ignore.law_context(state, owner, pid, now) or nil
        -- A current owned-player lookup proves the ped; no cached owner handle
        -- can carry across death, replacement, disable or a session transition.
        if not entry_handoff.active then
            if not Ignore.suppress_ambient_frame(state, owner, pid) then return false end
            for _, flag in ipairs(IGNORE_FRAME_FLAGS) do
                if not Ignore.valid(owner) then return false end
                local accepted, _, err = invoke_void_detail(H.SET_PED_RESET_FLAG, ped, flag, true)
                if err or accepted ~= true or not current() then return false end
            end
        end
        state.source_applied = not entry_handoff.active
        -- Retire only the temporary proof. Reset flags naturally expire on the
        -- next game frame; there is no RELEASE_SCRIPT_GUID_FROM_ENTITY call.
        owner.closed = true
        if not scan_due then
            state.scan_source = "frame-gates-only"; return current()
        end
        state.last_scan_ms = now
        local entries = Ignore.read(function() return pool_mgr.GetRenderedPeds() end)
        if not current() then return false end
        local pointers = Ignore.rendered_pointers(entries)
        if not current() then return false end
        if not pointers then
            state.scan_source = "rendered-pool-unavailable"; state.rendered = 0
            state.scan_count = 0; state.scan_credit = 0; return true
        end
        local count = #pointers
        state.rendered, state.scan_source = count, "current-rendered"
        local scanned = Ignore.scan_peds(state, count, scan_allowance, function(index)
            if not current() then return false end
            local proof = Ignore.proof(pointers[index], current, nil, state)
            if not proof then state.proof_rejected = (state.proof_rejected or 0) + 1 end
            if proof and proof.handle ~= ped then
                local handle = proof.handle
                local player = Ignore.query(proof, "bool", H.IS_PED_A_PLAYER, handle)
                if player == false and Ignore.valid(proof) then
                    Ignore.observe_entry_victim(state, entry_handoff, proof, now)
                    if Ignore.entry_interaction(entry_handoff, proof) then
                        Ignore.release_entry_ped(state, proof, entry_handoff.active and not Ignore.scene_actor(proof))
                    else
                        -- Complete-ignore mode intentionally includes mission/scripted
                        -- actors while enabled. This can temporarily interfere with their
                        -- authored behavior; both blocker flags are restored on disable.
                        local managed, entry, fresh = Ignore.remember_blocked(state, proof, now)
                        if fresh and Ignore.query(proof, "bool", H.IS_ENTITY_A_MISSION_ENTITY, handle) == true then
                            state.mission_managed = math.min(999999, (state.mission_managed or 0) + 1)
                        end
                        if managed and Ignore.valid(proof) and entry
                            and (fresh or now - (tonumber(entry.last_relationship_ms) or -100000) >= IGNORE_TIMING.relationship) then
                            -- Relationship pairs are persistent group state: write once on
                            -- admission, then only refresh slowly (or urgently after a real
                            -- local-player reaction) instead of twice for every ped visit.
                            if Ignore.apply_relationship(state, proof, player_group, now, false) then
                                entry.last_relationship_ms =
                                    now
                            end
                        end
                        if managed and Ignore.valid(proof) and entry
                            and not Ignore.held_by_gravity(proof)
                            and (fresh or now - (tonumber(entry.last_reaction_ms) or -100000) >= IGNORE_TIMING.reaction) then
                            entry.last_reaction_ms = now
                            local combat = Ignore.query(proof, "int", H.GET_PED_TARGET_FROM_COMBAT_PED, handle, 0)
                            local in_combat = Ignore.query(proof, "bool", H.IS_PED_IN_COMBAT, handle, ped)
                            local fleeing = Ignore.query(proof, "bool", H.IS_PED_FLEEING, handle)
                            local looking = Ignore.query(proof, "bool", 0x5CD3CB88A7F8850D, handle, ped)
                            local hostile = combat == ped or in_combat == true
                            local resumed = Ignore.resume_driver(state, proof, now)
                            local recovered = not resumed and not hostile and
                                Ignore.recover_fear(state, proof, entry, now, fleeing, looking)
                            local ambient_reaction = not resumed and not recovered and
                                (fleeing == true or looking == true)
                            if hostile then Ignore.request_task_control(state, proof, entry, now) end
                            if entry.law and not hostile and not resumed and not recovered
                                and (looking == true or law_context and law_context.isolated)
                                and Ignore.can_task(proof) then
                                Ignore.law_response(state, proof, entry, law_context, now, ped, looking)
                            end
                            if not resumed and not recovered and (hostile or ambient_reaction) and Ignore.can_task(proof) then
                                local cleared = false
                                if hostile then
                                    -- Existing local-player combat must disappear immediately.
                                    local hard = Ignore.task(proof, IGNORE_CLEAR_TASKS_NATIVE)
                                    if hard and Ignore.can_task(proof) then
                                        invoke_void_detail(IGNORE_PED_BLOCK_NATIVE, handle, true)
                                        state.hard_clears = math.min(999999, (state.hard_clears or 0) + 1)
                                        cleared = true
                                    end
                                else
                                    -- Cowering/fleeing/look-at reactions are usually threat
                                    -- response tasks. Clear only that task family rather than
                                    -- hard-resetting all authored tasks for an ambient event.
                                    cleared = Ignore.task(proof,
                                        H.CLEAR_PED_SCRIPT_TASK_IF_RUNNING_THREAT_RESPONSE_NON_TEMP_TASK)
                                end
                                if Ignore.valid(proof) and looking == true then
                                    local accepted = Ignore.task(proof, 0x0F804F1DB19B9689) -- TASK_CLEAR_LOOK_AT
                                    cleared = cleared or accepted
                                end
                                if hostile and Ignore.can_task(proof) then
                                    Ignore.apply_relationship(state, proof, player_group, now, true)
                                end
                                if cleared then
                                    state.cleared_responses = math.min(999999,
                                        (state.cleared_responses or 0) + 1)
                                end
                            end
                        end
                    end -- normal suppression resumes after the entry interaction
                    proof.closed = true
                end
            end
            return current()
        end)
        return scanned and current()
    end

    local function log_behavior_diagnostics()
        local ignore = State.peds_ignore
        local action = State.action_mode
        log_info(("Player behavior diagnostics: pedsIgnore={enabled=%s everyone=%s police=%s "
                .. "managed=%d mission=%d reasserted=%d relationships=%d law=%d helicopter=%d scan=%s/%d frameSourceApplied=%s "
                .. "shocking=%s agitation=%s witnessCalls=%s ambientBlock=%s} "
                .. "actionMode={phase=%s using=%s melee=%s shooting=%s aiming=%s combat=%s lastReason=%s ped=%s}.")
            :format(
                tostring(ignore.enabled),
                tostring(ignore.everyone_accepted == true),
                tostring(ignore.police_accepted == true),
                count_entries(ignore.managed),
                tonumber(ignore.mission_managed) or 0,
                tonumber(ignore.reasserted_peds) or 0,
                count_entries(ignore.relationships),
                tonumber(ignore.law_managed) or 0,
                tonumber(ignore.helicopter_managed) or 0,
                tostring(ignore.scan_source),
                tonumber(ignore.rendered) or 0,
                tostring(ignore.source_applied == true),
                tostring(ignore.shocking_accepted == true),
                tostring(ignore.agitation_accepted == true),
                tostring(ignore.witness_accepted == true),
                tostring(ignore.ambient_block_accepted == true),
                tostring(action.phase),
                tostring(action.using),
                tostring(action.melee),
                tostring(action.shooting),
                tostring(action.aiming),
                tostring(action.combat),
                tostring(action.last_reason),
                tostring(State.action_mode_ped)
            ))
        return true
    end

    local function restore_player()
        if Live.headgear then Live.headgear.Tick(now_ms(), false) end
        local pid = local_player_id()
        local ped = local_ped()
        invoke_void(H.SET_MAX_WANTED_LEVEL, 5)
        restore_peds_ignore("player restore")
        Live.restore_movement_boosts(true)
        Live.bst46_pause("player restore", false)
        Live.clear_protection(true)
        Live.restore_ragdoll_suppression(true)
        if entity_exists(ped) then
            invoke_void(H.SET_PED_SUFFERS_CRITICAL_HITS, ped, true)
            invoke_void(H.SET_PED_USING_ACTION_MODE, ped, false, -1, "DEFAULT_ACTION")
            invoke_void(H.RESET_PED_STRAFE_CLIPSET, ped)
            invoke_void(H.RESET_PED_MOVEMENT_CLIPSET, ped, 0.15)
        end
        local weapons = module_context and module_context.CScript and module_context.CScript.Weapons
        if weapons and type(weapons.RestorePlayer) == "function" then weapons.RestorePlayer(ped) end
        State.godmode_ped = 0
        State.godmode_last_check = -100000
        State.action_mode_ped = 0
        State.action_mode_recovery_until = 0
        State.action_mode = {
            phase = "idle",
            last_reason = "none",
            using = false,
            melee = false,
            shooting = false,
            aiming = false,
            combat = false,
            last_reset_ms = -100000,
            last_log_signature = nil,
        }
    end

    local function suppress_action_mode(now, ped, force_cleanup)
        -- This controller only touches the freshly read local ped. No cached
        -- ped is reused after replacement, and no other feature owns this flag.
        local function current()
            return is_on("disable_action_mode") and ped == local_ped()
        end
        if not current() or not entity_exists(ped)
            or invoke_bool(H.IS_ENTITY_DEAD, ped, false)
            or invoke_bool(H.IS_PED_DEAD_OR_DYING, ped, true) or not current() then
            return
        end
        now = tonumber(now) or now_ms()
        local action = State.action_mode
        local was_action_mode = invoke_bool(H.IS_PED_USING_ACTION_MODE, ped)
        if not current() then return end
        -- Combat tasks can queue forced action mode before the visible-state
        -- readback turns true. Clear both documented force flags and the action
        -- request now, including while aiming; do not wait for a target release.
        invoke_void(H.SET_PED_RESET_FLAG, ped, 298, false)
        if not current() then return end
        invoke_void(H.SET_PED_RESET_FLAG, ped, 299, false)
        if not current() then return end
        invoke_void(H.SET_PED_RESET_FLAG, ped, 200, true)
        if not current() then return end
        -- Keep PRF_DisableActionMode (200) active EACH game frame. Only exit
        -- an already-entered action state: continuously calling the setter
        -- when the ped is already out of action mode can restart transition
        -- blending and create the visible "twitch" around melee actions.
        if was_action_mode then
            invoke_void(H.SET_PED_USING_ACTION_MODE, ped, false, -1, 0)
            if not current() then return end
        end
        local melee = invoke_bool(H.IS_PED_PERFORMING_MELEE_ACTION, ped)
        if not current() then return end
        if not melee then melee = invoke_bool(H.IS_PED_IN_MELEE_COMBAT, ped) end
        if not current() then return end
        local shooting = invoke_bool(H.IS_PED_SHOOTING, ped)
        if not current() then return end
        local aiming = invoke_bool(H.IS_PLAYER_FREE_AIMING, local_player_id())
        if not current() then return end
        -- PRF_DisableActionMode=200: Enhanced freemode.c and the documented
        -- PedResetFlagToggles enum. Prevent re-entry by the game's combat task
        -- later in this frame; clearing the current state alone was insufficient.
        -- Block only this frame's melee targeting input. Do not change the
        -- player's targeting mode, attack tasks, clipsets or stealth controls.
        local seated, seated_raw, seated_error = invoke_bool_detail(H.IS_PED_IN_ANY_VEHICLE, ped, false)
        if current() and seated_error == nil and seated == false and (seated_raw == false or seated_raw == 0) then
            local weapon, weapon_raw, weapon_error = invoke_int_detail(H.GET_SELECTED_PED_WEAPON, ped)
            if current() and weapon_error == nil and type(weapon) == "number" and type(weapon_raw) == "number" then
                local group, group_raw, group_error = invoke_int_detail(0xC3287EE3050FB74C, weapon)
                if current() and group_error == nil and type(group) == "number" and type(group_raw) == "number" then
                    group = group % 4294967296
                    if group == 2685387236 or group == 3566412244 then
                        local fresh, _, fresh_error = invoke_int_detail(H.GET_SELECTED_PED_WEAPON, ped)
                        if current() and fresh_error == nil and fresh == weapon then
                            invoke_void_detail(0xFE99B66D079CF6BC, 0, 25, true)
                            -- DisablePlayerLockOn and ClearLockOnTarget expire each frame.
                            for _, flag in ipairs({ 43, 72 }) do
                                local selected, _, selected_error = invoke_int_detail(H.GET_SELECTED_PED_WEAPON, ped)
                                if not current() or selected_error ~= nil or selected ~= weapon then break end
                                invoke_void_detail(H.SET_PED_RESET_FLAG, ped, flag, true)
                            end
                        end
                    end
                end
            end
        end
        local using = invoke_bool(H.IS_PED_USING_ACTION_MODE, ped)
        if not current() then return end
        State.action_mode_ped, State.action_mode_recovery_until = ped, 0
        action.phase, action.using = using and "pending" or "suppressed", using
        action.last_reason = was_action_mode and "action-state-exit" or "frame-reentry-block"
        action.melee, action.shooting, action.aiming, action.combat = melee, shooting, aiming, melee or shooting
        local signature = table.concat({ tostring(ped), tostring(using) }, ":")
        if behavior_debug_enabled() and signature ~= action.last_log_signature then
            action.last_log_signature = signature
            log_info(("Action Mode state: ped=%s usingAfter=%s resetFlag=200 stealthUntouched=true clipsetsUntouched=true liveRetestRequired=true.")
                :format(tostring(ped), tostring(using)))
        end
    end

    -- Messiah runtime: one table keeps the large player factory below Lua's
    -- local-variable limit while isolating every temporary entity/FX owner.
    -- Tick is the sole activation/movement owner. Model validation, streaming,
    -- creation and cleanup are explicit bounded transitions rather than work
    -- replayed by a toggle callback or every held-attack frame.
    local Messiah = {
        PHASES = {
            OFF = "OFF",
            ASCENDING = "ASCENDING",
            IDLE_HOVER = "IDLE_HOVER",
            GLIDING = "GLIDING",
            ORB_WINDUP = "ORB_WINDUP",
            ORB_RELEASE = "ORB_RELEASE",
            ORB_RECOVER = "ORB_RECOVER",
            LANCE_WINDUP = "LANCE_WINDUP",
            LANCE_CHANNEL = "LANCE_CHANNEL",
