    function Messiah.State()
        if type(State.messiah) ~= "table" then State.messiah = {} end
        local state = State.messiah
        -- Runtime fields are owned by this module after initialization. Repeating
        -- every conversion from projection/lease helpers cost work per primitive.
        -- A replacement state table or a new module owner still initializes fully.
        if state._normalization_owner == Messiah then return state end
        state.active = state.active == true
        state.ped = tonumber(state.ped) or 0
        state.phase = tostring(state.phase or Messiah.PHASES.OFF)
        state.phase_started_ms = tonumber(state.phase_started_ms) or 0
        state.resume_phase = tostring(state.resume_phase or Messiah.PHASES.IDLE_HOVER)
        state.anchor_z = tonumber(state.anchor_z) or 0.0
        state.target_z = tonumber(state.target_z) or state.anchor_z
        state.ascent_start_z = tonumber(state.ascent_start_z) or state.anchor_z
        state.last_hover_height = tonumber(state.last_hover_height)
        state.last_tick_ms = tonumber(state.last_tick_ms) or 0
        state.move_vx = tonumber(state.move_vx) or 0.0
        state.move_vy = tonumber(state.move_vy) or 0.0
        state.move_vz = tonumber(state.move_vz) or 0.0
        state.motion_requested = state.motion_requested == true
        state.activation_id = tonumber(state.activation_id) or 0
        state.activation_epoch = tonumber(state.activation_epoch) or state.activation_id
        state.entity_frame = tonumber(state.entity_frame) or 0
        state.activation_owner = tostring(state.activation_owner or "none")
        state.right_hand = state.right_hand ~= false
        state.aura = type(state.aura) == "table" and state.aura or {}
        state.aura_attempted = type(state.aura_attempted) == "table" and state.aura_attempted or {}
        state.aura_alpha = tonumber(state.aura_alpha)
        state.next_fx_update_ms = tonumber(state.next_fx_update_ms) or 0
        state.projectiles = type(state.projectiles) == "table" and state.projectiles or {}
        state.delete_ptr = tonumber(state.delete_ptr) or 0
        state.shape_hit_ptr = tonumber(state.shape_hit_ptr) or 0
        state.shape_end_ptr = tonumber(state.shape_end_ptr) or 0
        state.shape_normal_ptr = tonumber(state.shape_normal_ptr) or 0
        state.shape_entity_ptr = tonumber(state.shape_entity_ptr) or 0
        state.asset_request_initialized = state.asset_request_initialized == true
        state.asset_deadline_ms = tonumber(state.asset_deadline_ms) or 0
        state.anim_requested = type(state.anim_requested) == "table" and state.anim_requested or {}
        state.ptfx_requested = type(state.ptfx_requested) == "table" and state.ptfx_requested or {}
        state.model_requested = state.model_requested == true
        state.model_owned = state.model_owned == true
        state.model_requested_ms = tonumber(state.model_requested_ms) or 0
        state.model_deadline_ms = tonumber(state.model_deadline_ms) or 0
        state.model_next_poll_ms = tonumber(state.model_next_poll_ms) or 0
