        state.destructive_accent_order = type(state.destructive_accent_order) == "table"
            and state.destructive_accent_order or {}
        state.respawn_blocked_ped = tonumber(state.respawn_blocked_ped) or 0
        state.no_ground_until_ms = tonumber(state.no_ground_until_ms) or 0
        state.no_ground_ability = tostring(state.no_ground_ability or "none")
        state.hud_snapshot = type(state.hud_snapshot) == "table" and state.hud_snapshot or nil
        state.last_target = type(state.last_target) == "table" and state.last_target or nil
        state.last_target_source = tostring(state.last_target_source or "none")
        state.aim_snapshot = type(state.aim_snapshot) == "table" and state.aim_snapshot or nil
        state.reticle_mode = tostring(state.reticle_mode or "DIRECT_MISS")
        state.reticle_mode_until_ms = tonumber(state.reticle_mode_until_ms) or 0
        state.reticle_pulse_until_ms = tonumber(state.reticle_pulse_until_ms) or 0
        state.heading = tonumber(state.heading)
        state.failure_seen = type(state.failure_seen) == "table" and state.failure_seen or {}
        state.diagnostic_seen = type(state.diagnostic_seen) == "table" and state.diagnostic_seen or {}
        state.cleanup_seen = type(state.cleanup_seen) == "table" and state.cleanup_seen or {}
        state.spawn_attempts = tonumber(state.spawn_attempts) or 0
        state.spawn_successes = tonumber(state.spawn_successes) or 0
        state.first_orb_logged = state.first_orb_logged == true
        state.last_cast_logged_speed = tonumber(state.last_cast_logged_speed)
        state.ragdoll_owned = state.ragdoll_owned == true
        state.ragdoll_before = state.ragdoll_before == true
        state.anim_variant = tostring(state.anim_variant or "unknown")
        state.idle_candidate_index = math.max(1,
            math.floor(tonumber(state.idle_candidate_index) or 1))
        state.animation_current = tostring(state.animation_current or "none")
        state.animation_started = type(state.animation_started) == "table" and state.animation_started or {}
        state.animation_next_check_ms = tonumber(state.animation_next_check_ms) or 0
        state.animation_repairs = tonumber(state.animation_repairs) or 0
        state.animation_last_reason = tostring(state.animation_last_reason or "none")
        state.idle_task_pending = state.idle_task_pending == true
        state.idle_task_started_ms = tonumber(state.idle_task_started_ms) or 0
        state.idle_candidates_exhausted = state.idle_candidates_exhausted == true
        state.stance_started = state.stance_started == true
        state.restore_started = state.restore_started == true
        state.restore_reason = tostring(state.restore_reason or "unspecified")
        state.restore_cleanup_summary = type(state.restore_cleanup_summary) == "table"
            and state.restore_cleanup_summary or nil
        state.restoring = state.restoring == true
        state._normalization_owner = Messiah
        return state
    end

    function Messiah.NormalizeHash(value)
        local number = tonumber(value) or 0
        local u32 = math.floor(number % 4294967296)
        if u32 < 0 then u32 = u32 + 4294967296 end
        local s32 = u32 >= 2147483648 and (u32 - 4294967296) or u32
        return u32, s32
    end

    function Messiah.RawValue(value)
        return ("%s:%s"):format(type(value), tostring(value))
    end

    function Messiah.FiniteNumber(value)
        value = tonumber(value)
        if value == nil or value ~= value or value == math.huge or value == -math.huge then
            return nil
        end
        return value
    end

    -- Native Vector3 output pointers use Cherax/GTA's 24-byte scrVector ABI:
    -- float components are written at byte offsets 0, 8 and 16 with padding in
    -- between. Memory.ReadV3 is still sampled for a bounded diagnostic, but its
    -- packed 0/4/8 interpretation must never feed targeting.
    function Messiah.ReadNativeOutV3(address, label)
        address = tonumber(address) or 0
        label = tostring(label or "native-vector")
        if address == 0 or not (memory and type(memory.ReadFloat) == "function") then
            return nil, nil, nil, "read-float-unavailable"
        end
        local packed_ok, packed = false, nil
        if type(memory.ReadV3) == "function" then packed_ok, packed = pcall(memory.ReadV3, address) end
        local packed_x, packed_y, packed_z
        if packed_ok then packed_x, packed_y, packed_z = vector_components(packed) end
        local ok_x, raw_x = pcall(memory.ReadFloat, address)
        local ok_y, raw_y = pcall(memory.ReadFloat, address + 8)
        local ok_z, raw_z = pcall(memory.ReadFloat, address + 16)
        local x = ok_x and Messiah.FiniteNumber(raw_x) or nil
        local y = ok_y and Messiah.FiniteNumber(raw_y) or nil
        local z = ok_z and Messiah.FiniteNumber(raw_z) or nil
        local function number_text(value)
            value = Messiah.FiniteNumber(value)
            return value and ("%.4f"):format(value) or "nil"
        end
        Messiah.LogOnce("native-vector-layout:" .. label,
            ("Messiah native Vector3 read: activation=%d label=%s layout=scrVector24 "
                .. "offsets=0/8/16 rawVectorType=%s rawVector=%s packed=(%s,%s,%s) "
                .. "extractedX=%s extractedY=%s extractedZ=%s.")
            :format(Messiah.State().activation_id, label, type(packed), tostring(packed),
                number_text(packed_x), number_text(packed_y), number_text(packed_z),
                number_text(x), number_text(y), number_text(z)))
        if not x or not y or not z then return nil, nil, nil, "non-finite-native-slots" end
        return x, y, z, "scrVector24"
    end

    function Messiah.LogOnce(key, message)
        local state = Messiah.State()
        key = tostring(key or message)
        if state.diagnostic_seen[key] then return false end
        state.diagnostic_seen[key] = true
        log_info(tostring(message))
        return true
    end

    function Messiah.Trace(message)
        if behavior_debug_enabled() then log_info(message) end
    end

    function Messiah.SetPhase(next_phase, now, detail)
        local state = Messiah.State()
        next_phase = tostring(next_phase or Messiah.PHASES.OFF)
        local previous = state.phase
        if previous == next_phase then return false end
        state.phase = next_phase
        state.phase_started_ms = tonumber(now) or now_ms()
        Messiah.Trace(("Messiah phase transition: activation=%d %s -> %s%s.")
            :format(state.activation_id, tostring(previous), next_phase,
                detail and (" detail=" .. tostring(detail)) or ""))
        return true
    end

    function Messiah.SetReticleMode(next_mode, until_ms, detail)
        local state = Messiah.State()
        next_mode = tostring(next_mode or "DIRECT_MISS")
        local previous = state.reticle_mode
        state.reticle_mode = next_mode
        state.reticle_mode_until_ms = tonumber(until_ms) or state.reticle_mode_until_ms
        if previous == next_mode then return false end
        Messiah.LogOnce("reticle-mode:" .. next_mode,
            ("Messiah reticle transition: activation=%d %s -> %s backend=ImGui.ON_PRESENT "
                .. "visualOnly=true detail=%s.")
            :format(state.activation_id, tostring(previous), next_mode,
                tostring(detail or "none")))
        return true
    end

    function Messiah.Approach(current, target, maximum_delta)
        current, target = tonumber(current) or 0.0, tonumber(target) or 0.0
        maximum_delta = math.max(0.0, tonumber(maximum_delta) or 0.0)
        local difference = target - current
        if math.abs(difference) <= maximum_delta then return target end
        return current + (difference > 0.0 and maximum_delta or -maximum_delta)
    end

    function Messiah.SetModelState(next_state, detail)
        local state = Messiah.State()
        next_state = tostring(next_state or "UNAVAILABLE")
        local previous = state.model_state
        if (next_state == "UNAVAILABLE" or next_state == "INVALID")
            and (state.queued_cast or state.cast_edge_pending) then
            state.queued_cast = false
            state.cast_edge_pending = false
            Messiah.LogOnce("queued-cast-cancelled",
                ("Messiah Fire Orb queued cast cancelled: activation=%d model_state=%s detail=%s.")
                :format(state.activation_id, next_state, tostring(detail or "none")))
        end
        if previous == next_state then return false end
        state.model_state = next_state
        log_info(("Messiah model transition: activation=%d %s -> %s%s.")
            :format(state.activation_id, tostring(previous), next_state,
                detail and (" detail=" .. tostring(detail)) or ""))
        return true
    end

    function Messiah.SetCreationState(next_state, detail)
        local state = Messiah.State()
        next_state = tostring(next_state or "UNAVAILABLE")
        local previous = state.creation_state
        if previous == next_state then return false end
        state.creation_state = next_state
        log_info(("Messiah creation transition: activation=%d %s -> %s%s.")
            :format(state.activation_id, tostring(previous), next_state,
                detail and (" detail=" .. tostring(detail)) or ""))
        return true
    end

    function Messiah.ModelUsable()
        return Messiah.State().model_state == "READY"
    end

    function Messiah.ModelIdentity()
        local u32, s32 = Messiah.NormalizeHash(Messiah.ORB_MODEL)
        return u32, s32,
            ("name=%s model_u32=%s model_s32=%s model_hex=0x%08X")
            :format(Messiah.ORB_MODEL_NAME, tostring(u32), tostring(s32), u32)
    end

    function Messiah.LogBoolNative(name, hash_text, hash, argument)
        local normalized, raw, err = invoke_bool_detail(hash, argument)
        local u32, s32, identity = Messiah.ModelIdentity()
        Messiah.LogOnce("native-bool:" .. tostring(name),
            ("Messiah model native: name=%s hash=%s %s arg_s32=%s "
                .. "normalized=%s raw=%s error=%s backend=%s.")
            :format(tostring(name), tostring(hash_text), identity, tostring(s32),
                tostring(normalized), Messiah.RawValue(raw), tostring(err),
                "Natives.InvokeBool"))
        return normalized, raw, err, u32, s32
    end

    function Messiah.ReportFailure(stage, detail)
        local state = Messiah.State()
        local signature = tostring(stage or "failure") .. ":" .. tostring(detail or "unknown")
        state.last_error = signature
        -- One diagnostic per unique failure per activation. The old three-second
        -- retry logging could slowly bloat Cherax.log while Attack was held.
        if state.failure_seen[signature] then return false end
        state.failure_seen[signature] = true
        log_info(("Messiah failure: activation=%d stage=%s detail=%s.")
            :format(state.activation_id, tostring(stage or "failure"),
                tostring(detail or "unknown")))
        toast("Messiah " .. tostring(stage or "failure") .. ": "
            .. tostring(detail or "unknown"), 4500, "warning")
        return false
    end

    function Messiah.MenuOpen()
        local gui = deps.GUI
        if not (gui and type(gui.IsOpen) == "function") then return false end
        local ok, value = pcall(gui.IsOpen)
        return ok and value == true
    end

    function Messiah.CameraDirection()
        local rot = invoke_vec3(H.GET_GAMEPLAY_CAM_ROT, 2)
        local rx, _, rz = vector_components(rot)
        rx, rz = tonumber(rx) or 0.0, tonumber(rz) or 0.0
        local pitch, yaw = math.rad(rx), math.rad(rz)
        local cp = math.abs(math.cos(pitch))
        local x, y, z = -math.sin(yaw) * cp, math.cos(yaw) * cp, math.sin(pitch)
        local length = math.sqrt(x * x + y * y + z * z)
        if length < 0.0001 then return 0.0, 1.0, 0.0, rz end
        return x / length, y / length, z / length, rz
    end

    function Messiah.EnsureShapePointers()
        local state = Messiah.State()
        if state.shape_hit_ptr ~= 0 and state.shape_end_ptr ~= 0
            and state.shape_normal_ptr ~= 0 and state.shape_entity_ptr ~= 0 then
            return true
        end
        if not (memory and type(memory.Alloc) == "function" and type(memory.AllocInt) == "function"
                and type(memory.WriteInt) == "function" and type(memory.ReadInt) == "function"
                and type(memory.ReadV3) == "function" and type(memory.ReadFloat) == "function") then
            Messiah.LogOnce("target-pointers-unavailable",
                "Messiah target resolver unavailable: Cherax Memory buffers are missing.")
            return false
        end
        local allocated = {}
        local function allocate_int(key)
            local ok, value = pcall(memory.AllocInt)
            value = ok and tonumber(value) or 0
            if value == 0 then error("could not allocate " .. key) end
            state[key] = value
            allocated[#allocated + 1] = key
        end
        local function allocate_v3(key)
            local ok, value = pcall(memory.Alloc, 24)
            value = ok and tonumber(value) or 0
            if value == 0 then error("could not allocate " .. key) end
            state[key] = value
            allocated[#allocated + 1] = key
        end
        local ok, err = pcall(function()
            allocate_int("shape_hit_ptr")
            allocate_v3("shape_end_ptr")
            allocate_v3("shape_normal_ptr")
            allocate_int("shape_entity_ptr")
        end)
        if ok then return true end
        if type(memory.Free) == "function" then
            for index = #allocated, 1, -1 do
                local key = allocated[index]
                if state[key] ~= 0 then pcall(memory.Free, state[key]) end
                state[key] = 0
            end
        end
        Messiah.LogOnce("target-pointer-allocation-failed",
            "Messiah target resolver buffer allocation failed: " .. tostring(err))
        return false
    end

    function Messiah.NormalizeEntityHandle(value)
        if value == nil then return 0, "none" end
        if type(value) ~= "number" then return 0, "non-number" end
        local numeric = value
        if not numeric or numeric ~= numeric or numeric == math.huge or numeric == -math.huge then
            return 0, "non-finite"
        end
        if numeric % 1 ~= 0 then return 0, "non-integer" end
        numeric = math.floor(numeric)
        if numeric == 0 then return 0, "none" end
        -- Entity is a signed script GUID. Cherax/native output buffers can expose
        -- the no-entity sentinel as either -1 or its uint32 representation.
        -- Neither form, nor any other non-positive/high-bit value, may cross an
        -- entity-native boundary.
        if numeric == -1 then return 0, "sentinel-s32-minus-one" end
        if numeric == 4294967295 then return 0, "sentinel-u32-max" end
        if numeric < 0 then return 0, "negative-out-of-range" end
        if numeric >= 2147483648 then return 0, "unsigned-out-of-range" end
        return numeric, "valid"
    end

    function Messiah.ReportRejectedEntityHandle(boundary, raw_handle, classification,
                                                next_native, detail)
        classification = tostring(classification or "unknown")
        if classification == "valid" or classification == "none" then return false end
        local state = Messiah.State()
        return Messiah.LogOnce("entity-handle-rejected:" .. tostring(boundary)
            .. ":" .. classification,
            ("Messiah entity handle rejected: activation=%d boundary=%s rawHandle=%s "
                .. "normalizedHandle=0 classification=%s nextNative=%s invoked=false detail=%s.")
            :format(state.activation_id, tostring(boundary),
                Messiah.RawValue(raw_handle), classification,
                tostring(next_native or "none"), tostring(detail or "none")))
    end

    -- Script GUIDs are disposable aliases. Only this boundary may consume a
    -- retained Messiah target. CPhysical:GetAddress is an opaque comparison key:
    -- no address is dereferenced, reconstructed, or converted back into a GUID.
    -- The documented bridge is not an atomic engine lifetime pin. Failed or
    -- unavailable mapping fails closed; live host safety still requires a retest.
    function Messiah.EntityState()
        local state = Messiah.State()
        state.activation_epoch = tonumber(state.activation_epoch) or state.activation_id
        state.entity_frame = tonumber(state.entity_frame) or 0
        state.entity_identities = state.entity_identities or {}
        state.entity_identity_count = tonumber(state.entity_identity_count) or 0
        state.entity_breadcrumbs = state.entity_breadcrumbs or {}
        state.released_script_guids = state.released_script_guids or {}
        state.released_script_guid_count = tonumber(state.released_script_guid_count) or 0
        state.script_guid_release_serial = tonumber(state.script_guid_release_serial) or 0
        return state
    end

    Messiah.MAX_RELEASED_SCRIPT_GUIDS = 4096

    function Messiah.IsReleasedScriptGuid(handle, state)
        state = state or (type(State.messiah) == "table" and State.messiah or nil)
        return state and state.released_script_guids and state.released_script_guids[handle] == true or false
    end

    function Messiah.RecordReleasedScriptGuid(handle, state)
        state = state or Messiah.EntityState()
        if State.messiah ~= state then return false end
        state.released_script_guids = state.released_script_guids or {}
        state.released_script_guid_count = tonumber(state.released_script_guid_count) or 0
        state.script_guid_release_serial = tonumber(state.script_guid_release_serial) or 0
        if Messiah.IsReleasedScriptGuid(handle, state) then return true end
        if state.released_script_guid_count >= Messiah.MAX_RELEASED_SCRIPT_GUIDS then
            state.script_guid_capacity_blocked = true
            return false
        end
        state.released_script_guids[handle] = true
        state.released_script_guid_count = state.released_script_guid_count + 1
        state.script_guid_release_serial = state.script_guid_release_serial + 1
        return true
    end

    function Messiah.ScriptGuidContextCurrent(lease, state, release_serial)
        if type(lease) ~= "table" or State.messiah ~= state
            or Messiah.IsReleasedScriptGuid(lease.handle, state)
            or release_serial ~= state.script_guid_release_serial
            or not Messiah.EntityOwner(lease) then
            return false
        end
        if lease.identity and (lease.identity.terminal == true or (lease.owned ~= true
                and (tonumber(lease.identity_revision) or 0) ~= (tonumber(lease.identity.borrowed_revision) or 0))) then
            return false
        end
        return lease.state == "live" or lease.state == "candidate"
    end

    function Messiah.EntityOwner(lease)
        local state = Messiah.EntityState()
        if state.disposed == true or state.cleanup_failed == true then return false end
        if state.cleanup_owner == true then
            return state.gameplay_owner == true and lease and lease.epoch == state.cleanup_epoch
        end
        if state.active ~= true and state.bootstrap_owner == true then
            return state.gameplay_owner == true and state.restoring ~= true and state.ending ~= true
                and (not lease or (lease.source == "player-bootstrap"
                    and lease.handle == state.bootstrap_handle and lease.epoch == state.activation_epoch))
        end
        return state.gameplay_owner == true and state.active == true
            and state.restoring ~= true and state.disposed ~= true
            and (not lease or lease.epoch == state.activation_epoch)
    end

    function Messiah.EntityBreadcrumb(lease, operation, hash)
        if not behavior_debug_enabled() then return true end
        local state = Messiah.EntityState()
        lease = type(lease) == "table" and lease or {}
        local hash_text = type(hash) == "number" and ("0x%016X"):format(hash) or tostring(hash or "documented-api")
        local text = ("epoch=%s action=%s ability=%s source=%s raw=%s normalized=%s "
                .. "identity=%s kind=%s operation=%s hash=%s lease=%s frame=%s acquiredMs=%s")
            :format(tostring(lease.epoch or state.activation_epoch),
                tostring(lease.action_serial or 0), tostring(lease.ability or "none"),
                tostring(lease.source or "none"), Messiah.RawValue(lease.raw),
                tostring(lease.handle or 0), tostring(lease.identity_key or "unresolved"),
                tostring(lease.kind or "unknown"), tostring(operation), hash_text,
                tostring(lease.state or "candidate"), tostring(lease.frame or state.entity_frame),
                tostring(lease.acquired_ms or 0))
        local ring = state.entity_breadcrumbs
        ring[#ring + 1] = text
        if #ring > 32 then table.remove(ring, 1) end
        return true
    end

    function Messiah.EntityIdentity(lease)
        local state = Messiah.EntityState()
        local release_serial = state.script_guid_release_serial
        local function current() return Messiah.ScriptGuidContextCurrent(lease, state, release_serial) end
        if not current() then return nil end
        if not Messiah.EntityOwner(lease) or lease.handle == 0 then return nil end
        if not gta or type(gta.HandleToPointer) ~= "function" then return nil end
        if not Messiah.EntityBreadcrumb(lease, "GTA.HandleToPointer", "documented-api") then return nil end
        if not current() then return nil end
        local ok, object = pcall(gta.HandleToPointer, lease.handle)
        if not current() then return nil end
        if not ok or object == nil then return nil end
        if not Messiah.EntityBreadcrumb(lease, "CPhysical:GetAddress", "documented-api") then return nil end
        if not current() then return nil end
        local address_ok, address = pcall(function() return object:GetAddress() end)
        if not current() then return nil end
        if not address_ok or type(address) ~= "number" or address ~= address
            or address <= 0 or address >= math.huge or address % 1 ~= 0 then
            return nil
        end
        return ("physical:%s"):format(tostring(address))
    end

    function Messiah.RetireEntityLease(lease, reason, terminal)
        if type(lease) ~= "table" then return false end
        lease.state = terminal == true and "terminal" or "retired"
        lease.reason = tostring(reason or "retired")
        if terminal == true and lease.identity then
            lease.identity.terminal = true
            lease.identity.terminal_reason = lease.reason
        end
        return true
    end

    function Messiah.EntityExistsBoundary(lease)
        local state = Messiah.EntityState()
        local release_serial = state.script_guid_release_serial
        if not Messiah.ScriptGuidContextCurrent(lease, state, release_serial) then return false end
        if not H.DOES_ENTITY_EXIST or not Messiah.EntityBreadcrumb(lease,
                "DOES_ENTITY_EXIST", "0x7239B21A38F536BA") then
            return false
        end
        if not Messiah.ScriptGuidContextCurrent(lease, state, release_serial) then return false end
        local value, raw, err = invoke_bool_detail(H.DOES_ENTITY_EXIST, lease.handle)
        if not Messiah.ScriptGuidContextCurrent(lease, state, release_serial) then return false end
        lease.local_presence = nil
        if err == nil and (type(raw) == "boolean" or type(raw) == "number") then
            lease.local_presence = value == true
        end
        return lease.local_presence == true
    end

    function Messiah.ValidateEntityLease(lease, operation, hash, include_dead)
        local state = Messiah.EntityState()
        local release_serial = state.script_guid_release_serial
        local function current() return Messiah.ScriptGuidContextCurrent(lease, state, release_serial) end
        if not current() then return false end
        if type(lease) ~= "table" or lease.state ~= "live" or not Messiah.EntityOwner(lease)
            or (state.cleanup_owner ~= true and lease.owned ~= true and lease.frame ~= state.entity_frame)
            or (lease.owned ~= true and (tonumber(lease.blast_generation) or 0) ~= (tonumber(state.blast_generation) or 0))
            or not lease.identity or lease.identity.terminal == true
            or (lease.owned ~= true and (tonumber(lease.identity_revision) or 0)
                ~= (tonumber(lease.identity.borrowed_revision) or 0)) then
            return false
        end
        local identity = Messiah.EntityIdentity(lease)
        if identity ~= lease.identity_key then
            lease.identity_replaced = identity ~= nil
            Messiah.RetireEntityLease(lease, "identity-changed", false); return false
        end
        -- Repeat existence immediately before classification. This covers the
        -- observed true->false between consecutive host calls; it is not a lock.
        if not Messiah.EntityExistsBoundary(lease) or not Messiah.EntityExistsBoundary(lease) then
            Messiah.RetireEntityLease(lease, "entity-disappeared", false); return false
        end
        if not H.GET_ENTITY_TYPE or not Messiah.EntityBreadcrumb(lease,
                "GET_ENTITY_TYPE", "0x8ACD366038D14505") then
            return false
        end
        if not current() then return false end
        local kind_id, kind_raw, kind_error = invoke_int_detail(H.GET_ENTITY_TYPE, lease.handle)
        if not current() then return false end
        local actual_kind = ({ [1] = "ped", [2] = "vehicle", [3] = "object" })[kind_id]
        if kind_error or type(kind_raw) ~= "number" or not actual_kind
            or (lease.kind ~= "unknown" and lease.kind ~= actual_kind) then
            Messiah.RetireEntityLease(lease, "entity-type-changed", false); return false
        end
        lease.kind = actual_kind
        if include_dead ~= true and lease.owned ~= true then
            if not Messiah.EntityExistsBoundary(lease) then
                Messiah.RetireEntityLease(lease, "entity-disappeared", false); return false
            end
            if not H.IS_ENTITY_DEAD or not Messiah.EntityBreadcrumb(lease,
                    "IS_ENTITY_DEAD", "0x5F9532F3B5CC2551") then
                return false
            end
            if not current() then return false end
            local dead, raw, err = invoke_bool_detail(H.IS_ENTITY_DEAD, lease.handle, false)
            if not current() then return false end
            if err or (type(raw) ~= "boolean" and type(raw) ~= "number") then
                Messiah.RetireEntityLease(lease, "dead-status-unknown", false); return false
            end
            if dead == true then
                Messiah.RetireEntityLease(lease, "observed-destroyed", true); return false
            end
            if actual_kind == "vehicle" then
                if not Messiah.EntityExistsBoundary(lease) then
                    Messiah.RetireEntityLease(lease, "entity-disappeared", false); return false
                end
                if not H.IS_VEHICLE_DRIVEABLE or not Messiah.EntityBreadcrumb(lease,
                        "IS_VEHICLE_DRIVEABLE", "0x4C241E39B23DF959") then
                    return false
                end
                if not current() then return false end
                local driveable, raw_driveable, drive_error = invoke_bool_detail(
                    H.IS_VEHICLE_DRIVEABLE, lease.handle, false)
                if not current() then return false end
                if drive_error or (type(raw_driveable) ~= "boolean" and type(raw_driveable) ~= "number") then
                    Messiah.RetireEntityLease(lease, "driveable-status-unknown", false); return false
                end
                if driveable ~= true then
                    Messiah.RetireEntityLease(lease, "observed-non-driveable", true); return false
                end
            end
        end
        if Messiah.EntityIdentity(lease) ~= lease.identity_key or not Messiah.EntityExistsBoundary(lease) then
            Messiah.RetireEntityLease(lease, "changed-before-boundary", false); return false
        end
        local breadcrumb = Messiah.EntityBreadcrumb(lease, operation, hash)
        return breadcrumb and current()
    end

    function Messiah.AcquireEntityLease(raw, expected_kind, context)
        context = type(context) == "table" and context or {}
        local state = Messiah.EntityState()
        local handle, classification = Messiah.NormalizeEntityHandle(raw)
        local cleanup_release = context.release_only == true and context.source == "aim-retirement-proof"
            and context.release_guid == true and state.cleanup_owner == true
            and context.epoch == state.cleanup_epoch
        if handle == 0 or (not Messiah.EntityOwner() and not (cleanup_release
                and Messiah.EntityOwner({ epoch = context.epoch }))) then
            return nil, classification
        end
        if Messiah.IsReleasedScriptGuid(handle, state) then return nil, "released-script-guid" end
        if state.script_guid_capacity_blocked and context.owned ~= true then return nil, "script-guid-capacity" end
        local release_serial = state.script_guid_release_serial
        local lease = {
            raw = raw,
            handle = handle,
            state = "candidate",
            epoch = tonumber(context.epoch) or state.activation_epoch,
            action_serial = tonumber(context.action_serial) or (state.action and state.action.serial) or 0,
            ability = tostring(context.action or (state.action and state.action.ability) or "none"),
            source = tostring(context.source or "pool"),
            frame = state.entity_frame,
            acquired_ms = now_ms(),
            creation_serial = tonumber(context.creation_serial) or 0,
            blast_generation = tonumber(state.blast_generation) or 0,
            kind = tostring(expected_kind or "unknown"),
            owned = context.owned == true,
            release_guid = context.release_guid == true,
            release_only = context.release_only == true
        }
        if not Messiah.ScriptGuidContextCurrent(lease, state, release_serial) then return nil, "guid-context-changed" end
        local key = Messiah.EntityIdentity(lease)
        if not Messiah.ScriptGuidContextCurrent(lease, state, release_serial) then return nil, "guid-context-changed" end
        if not key then return nil, "identity-unavailable" end
        -- A caller with an independently sampled physical identity must not
        -- validate a replacement alias between its proof and lease admission.
        if context.expected_identity_key ~= nil and key ~= context.expected_identity_key then
            return nil, "identity-mismatch-before-validation"
        end
        lease.identity_key = key
        -- A successful new object creation is a new owned generation even if
        -- GTA reuses a deleted carrier's allocation address. Its record stays
        -- private; target tombstones and every old lease remain invalid.
        local fresh = context.owned == true and context.fresh_creation == true
            and expected_kind == "object" and context.source == "carrier"
            and type(context.creation_serial) == "number" and context.creation_serial > 0
        local record = fresh and {
            key = key,
            epoch = state.activation_epoch,
            creation_serial = context.creation_serial,
            terminal = false
        } or state.entity_identities[key]
        if record and record.terminal == true then return nil, "identity-terminal" end
        if not record then
            -- Never evict a tombstone while its activation can still produce
            -- aliases. Capacity exhaustion disables new mutations until re-enable.
            if state.entity_identity_count >= 1024 then return nil, "identity-capacity" end
            record = { key = key, epoch = state.activation_epoch, terminal = false }
            state.entity_identities[key] = record
            state.entity_identity_count = state.entity_identity_count + 1
        end
        lease.identity, lease.state = record, "live"
        lease.identity_revision = tonumber(record.borrowed_revision) or 0
        lease.action_key = table.concat({ tostring(lease.epoch), tostring(lease.action_serial), key }, ":")
        if not Messiah.ValidateEntityLease(lease, "acquire-complete", "none") then return nil, lease.reason end
        return lease, "live"
    end

    function Messiah.LeaseInvoke(lease, return_kind, name, hash, ...)
        local state = Messiah.EntityState()
        local release_serial = state.script_guid_release_serial
        if lease and lease.release_only == true then return false, nil, "guid-release-only" end
        if state.cleanup_owner == true and (not lease or lease.owned ~= true) then
            return false, nil, "cleanup-mutation-not-owned"
        end
        if not hash or not Messiah.ValidateEntityLease(lease, name, hash) then
            return return_kind == "vec3" and nil or false, nil, "lease-rejected"
        end
        local value, raw, err
        if not Messiah.ScriptGuidContextCurrent(lease, state, release_serial) then
            return false, nil,
                "guid-context-changed"
        end
        if return_kind == "bool" then
            value, raw, err = invoke_bool_detail(hash, ...)
        elseif return_kind == "int" then
            value, raw, err = invoke_int_detail(hash, ...)
        elseif return_kind == "float" then
            value, raw, err = invoke_float_detail(hash, ...)
        elseif return_kind == "vec3" then
            value = invoke_vec3(hash, ...)
            if not value then err = "vector-unavailable" end
            raw = value
        else
            value, raw, err = invoke_void_detail(hash, ...)
        end
        if err then
            Messiah.RetireEntityLease(lease, "native-error:" .. tostring(name), false)
            if state.cleanup_owner == true then
                state.cleanup_failed = true
                error("Messiah cleanup aborted at " .. tostring(name) .. ": " .. tostring(err), 0)
            end
        end
        return value, raw, err
    end

    function Messiah.EntityContextMatches(lease, context)
        if type(lease) ~= "table" then return false end
        context = type(context) == "table" and context or {}
        return (context.action_serial == nil or tonumber(context.action_serial) == lease.action_serial)
            and (context.epoch == nil or tonumber(context.epoch) == lease.epoch)
            and (context.action == nil or tostring(context.action) == lease.ability)
    end

    function Messiah.ReleaseEntityLease(lease, reason)
        if type(lease) ~= "table" or lease.state ~= "live" then return true end
        if lease.release_guid ~= true then
            lease.state = "released"; return true
        end
        local state = Messiah.EntityState()
        local hold = state.aim_guid_hold
        if Messiah.AimGuidProtectionCurrent(hold, state, lease.identity) and hold.epoch == lease.epoch then
            lease.state, lease.reason = "retired", "aim-guid-retained:" .. tostring(reason or "consumed")
            if hold.handle ~= lease.handle then
                -- A freshly proved alias already owns this physical entity.
                -- Releasing the older fwScriptGuid could invalidate that owner.
                Messiah.RecordReleasedScriptGuid(lease.handle, state)
            end
            return true
        end
        if not Messiah.ValidateEntityLease(lease, "RELEASE_SCRIPT_GUID_FROM_ENTITY",
                "0x2B3334BCA57CD799") then
            Messiah.RetireEntityLease(lease, "release-skipped-invalid", false); return true
        end
        if state.aim_guid_hold ~= hold then
            -- A validation callback can publish a fresh aim ticket without
            -- changing activation or release history. Never release beneath
            -- that new owner; retire only this superseded alias.
            local replacement = state.aim_guid_hold
            lease.state, lease.reason = "retired", "aim-owner-changed-during-release-proof"
            if not replacement or replacement.handle ~= lease.handle then
                Messiah.RecordReleasedScriptGuid(lease.handle, state)
            end
            return true
        end
        if hold and hold.state == "held" and hold.identity == lease.identity then
            -- A sibling release may invalidate the held fwScriptGuid too.
            -- Quarantine its exact alias before the host call; a stale ticket
            -- cannot protect a fresh sibling or authorize a later mapping.
            if state.aim_guid_hold == hold then state.aim_guid_hold = nil end
            Messiah.AbandonAimGuid(hold, state, "sibling-guid-release")
        end
        if not Messiah.RecordReleasedScriptGuid(lease.handle, state) then
            Messiah.RetireEntityLease(lease, "guid-capacity-release-refused", false)
            return true
        end
        -- The contract invalidates this alias. Claim release BEFORE entering host;
        -- neither a failure nor a second owner may retry this possibly-dead GUID.
        -- The frame aim and a completed beam sweep can share the same GUID.
        -- Revoke their sibling leases before any mapping/existence call, even
        -- when this frame's blast is deferred and has not revoked generations.
        lease.identity.borrowed_revision = (tonumber(lease.identity.borrowed_revision) or 0) + 1
        lease.state, lease.release_reason = "released", tostring(reason or "consumed")
        invoke_void_detail(H.RELEASE_SCRIPT_GUID_FROM_ENTITY, lease.handle)
        return true
    end

    function Messiah.HoldAimGuid(lease)
        local state = Messiah.EntityState()
        if not lease or lease.owned == true or lease.release_guid ~= true or lease.frame ~= state.entity_frame
            or not Messiah.ValidateEntityLease(lease, "aim-guid-hold", "none") then
            return nil
        end
        -- This ticket owns only the decision not to release this exact GUID.
        -- It is not an entity lease, has no native mutation permission, and a
        -- later frame must obtain a fresh shape result/current pointer proof.
        return {
            state = "held",
            handle = lease.handle,
            identity_key = lease.identity_key,
            identity = lease.identity,
            revision = lease.identity_revision,
            kind = lease.kind,
            epoch = lease.epoch,
            proof_frame = state.entity_frame
        }
    end

    function Messiah.AimGuidProtectionCurrent(hold, state, identity)
        return State.messiah == state and type(hold) == "table" and hold.state == "held"
            and hold.proof_frame == state.entity_frame and hold.epoch == state.activation_epoch
            and hold.identity == identity and identity ~= nil and identity.terminal ~= true
            and state.entity_identities[hold.identity_key] == identity
            and hold.revision == (tonumber(identity.borrowed_revision) or 0)
            and not Messiah.IsReleasedScriptGuid(hold.handle, state)
    end

    function Messiah.AbandonAimGuid(hold, state, reason)
        if type(hold) ~= "table" then return false end
        hold.state, hold.reason = "abandoned", tostring(reason or "proof-unavailable")
        -- The exact alias becomes unusable even when no release native was
        -- attempted. Do not tombstone its physical identity or a new GUID.
        if State.messiah == state then Messiah.RecordReleasedScriptGuid(hold.handle, state) end
        return false
    end

    function Messiah.RetireAimGuidHold(hold, reason)
        local state = Messiah.EntityState()
        if type(hold) ~= "table" or hold.state ~= "held" then return true end
        if state.aim_guid_hold == hold then state.aim_guid_hold = nil end
        local protected = state.aim_guid_hold
        if Messiah.AimGuidProtectionCurrent(protected, state, hold.identity) and protected.epoch == hold.epoch then
            if protected.handle == hold.handle then
                -- The new actual query, not the older ticket revision, proves
                -- ownership of this unchanged and never-released alias.
                hold.state = "transferred"
                return true
            end
            -- Preserve the fresh alias on the same physical entity. Revoke
            -- only the superseded numeric alias, with no host release.
            return Messiah.AbandonAimGuid(hold, state, "fresh-alias-protected")
        end
        local epoch, release_serial = state.activation_epoch, state.script_guid_release_serial
        local function current()
            return State.messiah == state and state.activation_epoch == epoch
                and state.aim_guid_hold == protected and release_serial == state.script_guid_release_serial
                and not Messiah.IsReleasedScriptGuid(hold.handle, state)
                and Messiah.EntityOwner({ epoch = hold.epoch }) and hold.identity ~= nil
                and state.entity_identities[hold.identity_key] == hold.identity
                and hold.identity.terminal ~= true
                and (tonumber(hold.identity.borrowed_revision) or 0) == hold.revision
        end
        if not current() or not gta or type(gta.HandleToPointer) ~= "function"
            or type(gta.PointerToHandle) ~= "function" then
            return Messiah.AbandonAimGuid(hold, state, reason)
        end
        -- Mapping a known-unreleased held alias is read-only proof collection.
        -- No entity native runs until a new current-frame child is acquired.
        local ok, pointer = pcall(gta.HandleToPointer, hold.handle)
        if not current() or not ok or pointer == nil then return Messiah.AbandonAimGuid(hold, state, reason) end
        local address_ok, address = pcall(function() return pointer:GetAddress() end)
        if not current() or not address_ok or "physical:" .. tostring(address) ~= hold.identity_key then
            return Messiah.AbandonAimGuid(hold, state, reason)
        end
        local converted_ok, raw = pcall(gta.PointerToHandle, pointer)
        if not current() or not converted_ok or Messiah.NormalizeEntityHandle(raw) ~= hold.handle then
            return Messiah.AbandonAimGuid(hold, state, reason)
        end
        local lease = Messiah.AcquireEntityLease(raw, hold.kind, {
            source = "aim-retirement-proof",
            epoch = hold.epoch,
            action = "none",
            action_serial = 0,
            release_guid = true,
            release_only = true
        })
        if not current() or not lease or lease.identity_key ~= hold.identity_key then
            return Messiah.AbandonAimGuid(hold, state, reason)
        end
        hold.state = "closing"
        local released = Messiah.ReleaseEntityLease(lease, reason or "aim-replaced")
        hold.state = lease.state == "released" and "released" or "abandoned"
        return released
    end

    function Messiah.ReleaseShapeEntity(point, reason)
        if type(point) ~= "table" then return true end
        if point.entity_lease then Messiah.ReleaseEntityLease(point.entity_lease, reason) end
        point.entity_retained, point.entity_released, point.entity = false, true, 0
        return true
    end

    function Messiah.ReleaseAimEntity(reason)
        local state = Messiah.State()
        local aim = state.cleanup_owner == true and state.cleanup_aim_snapshot or state.aim_snapshot
        local point = aim and type(aim.target) == "table" and aim.target or nil
        if reason ~= "frame-consumed" and state.aim_guid_hold then
            Messiah.RetireAimGuidHold(state.aim_guid_hold, reason)
            if State.messiah ~= state then return false end
        end
        local released = Messiah.ReleaseShapeEntity(point, reason)
        if state.cleanup_owner == true then state.cleanup_aim_snapshot = nil end
        return released
    end

    function Messiah.ShapeRay(from_x, from_y, from_z, to_x, to_y, to_z, flags, ignore)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local function current() return Messiah.ActivationContextCurrent(state, epoch) end
        if not current() then return nil, "shape-context-revoked" end
        if not H.START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE
            or not H.GET_SHAPE_TEST_RESULT or not Messiah.EnsureShapePointers() then
            return nil, "native-unavailable"
        end
        if not current() then return nil, "shape-context-revoked" end
        local handle, start_raw, start_error = invoke_int_detail(
            H.START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE,
            from_x, from_y, from_z, to_x, to_y, to_z,
            tonumber(flags) or 511, tonumber(ignore) or 0, 4)
        if not current() then return nil, "shape-context-revoked" end
        if start_error or handle <= 0 then
            Messiah.LogOnce("shape-start-failed",
                ("Messiah target native failed: name=START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE "
                    .. "hash=0x377906D8A31E5586 raw=%s error=%s.")
                :format(Messiah.RawValue(start_raw), tostring(start_error)))
            return nil, "shape-start-failed"
        end
        pcall(memory.WriteInt, state.shape_hit_ptr, 0)
        if not current() then return nil, "shape-context-revoked" end
        pcall(memory.WriteInt, state.shape_entity_ptr, 0)
        if not current() then return nil, "shape-context-revoked" end
        local status, result_raw, result_error = invoke_int_detail(H.GET_SHAPE_TEST_RESULT, handle,
            state.shape_hit_ptr, state.shape_end_ptr, state.shape_normal_ptr, state.shape_entity_ptr)
        if not current() then return nil, "shape-context-revoked" end
        if result_error or status ~= 2 then
            Messiah.LogOnce("shape-result-failed",
                ("Messiah target native failed: name=GET_SHAPE_TEST_RESULT hash=0x3D87450E15D98694 "
                    .. "status=%s raw=%s error=%s.")
                :format(tostring(status), Messiah.RawValue(result_raw), tostring(result_error)))
            return nil, "shape-result-failed"
        end
        local hit_ok, hit = pcall(memory.ReadInt, state.shape_hit_ptr)
        if not current() then return nil, "shape-context-revoked" end
        local hit_value = hit_ok and tonumber(hit) or 0
        local hit_present = hit_value ~= 0
        local x, y, z, layout
        if hit_present then
            x, y, z, layout = Messiah.ReadNativeOutV3(state.shape_end_ptr, "shape-end")
            if not current() then return nil, "shape-context-revoked" end
        end
        local entity_ok, entity_value = pcall(memory.ReadInt, state.shape_entity_ptr)
        if not current() then return nil, "shape-context-revoked" end
        local entity_raw = entity_ok and entity_value or nil
        local entity, entity_classification = Messiah.NormalizeEntityHandle(entity_raw)
        Messiah.ReportRejectedEntityHandle("ShapeRay.GET_SHAPE_TEST_RESULT", entity_raw,
            entity_classification, "none",
            "GET_SHAPE_TEST_RESULT/0x3D87450E15D98694 output normalized before consumers")
        if not current() then return nil, "shape-context-revoked" end
        local owned_orb = entity ~= 0 and state.projectiles[entity] ~= nil
        local release_eligible = entity ~= 0 and entity ~= tonumber(state.ped) and not owned_orb
        local reference = release_eligible and Messiah.AcquireEntityLease(entity, nil,
            { source = "raycast", release_guid = true }) or nil
        if not current() then return nil, "shape-context-revoked" end
        local lease = reference and {
            entity = entity,
            entity_raw = entity_raw,
            entity_classification = entity_classification,
            entity_retained = true,
            entity_lease = reference
        } or nil
        if not hit_present then return nil, "miss", lease end
        if not x then return nil, "point-read-failed:" .. tostring(layout), lease end
        return {
            x = x,
            y = y,
            z = z,
            entity = entity,
            entity_raw = entity_raw,
            entity_classification = entity_classification,
            entity_released = false,
            entity_retained = reference ~= nil,
            entity_lease = reference,
            vector_layout = layout,
        }, "hit"
    end

    function Messiah.ResolveAimTarget(mode, diagnostic_key)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local function current() return Messiah.ActivationContextCurrent(state, epoch) end
        if not current() then return nil, "aim-context-revoked" end
        mode = tostring(mode or "DIRECT"):upper()
        if mode == "SELF" then
            local coords = invoke_vec3(H.GET_ENTITY_COORDS, state.ped, false)
            if not current() then return nil, "aim-context-revoked" end
            local x, y, z = vector_components(coords)
            x, y, z = Messiah.FiniteNumber(x), Messiah.FiniteNumber(y), Messiah.FiniteNumber(z)
            if not x or not y or not z then return nil, "local-ped-unavailable" end
            local point = {
                x = x,
                y = y,
                z = z,
                mode = "SELF",
                source = "local-ped-snapshot"
            }
            Messiah.LogOnce("resolver-final:SELF",
                ("Messiah target resolved: activation=%d mode=SELF final=(%.2f,%.2f,%.2f) "
                    .. "source=local-ped-snapshot immutableOnAccept=true.")
                :format(state.activation_id, x, y, z))
            return point, point.source
        end
        local camera = invoke_vec3(H.GET_GAMEPLAY_CAM_COORD)
        if not current() then return nil, "aim-context-revoked" end
        local cx, cy, cz = vector_components(camera)
        local dx, dy, dz = Messiah.CameraDirection()
        if not current() then return nil, "aim-context-revoked" end
        cx, cy, cz = tonumber(cx), tonumber(cy), tonumber(cz)
        if not cx or not dx then return nil, "camera-unavailable" end
        local distance = mode == "GROUND" and Messiah.GROUND_AIM_DISTANCE
            or Messiah.DIRECT_AIM_DISTANCE
        local ex, ey, ez = cx + dx * distance, cy + dy * distance, cz + dz * distance
        local ray, ray_status, discarded_lease = Messiah.ShapeRay(
            cx, cy, cz, ex, ey, ez, 511, state.ped)
        if not current() then return nil, "aim-context-revoked" end
        if discarded_lease then
            Messiah.ReleaseShapeEntity(discarded_lease, "discarded-ray-result")
            if not current() then return nil, "aim-context-revoked" end
        end
        local retries = 0
        while ray and state.projectiles[tonumber(ray.entity) or 0] and retries < 3 do
            retries = retries + 1
            local advance = 1.25
            local retry_ray, retry_status, retry_lease = Messiah.ShapeRay(
                ray.x + dx * advance, ray.y + dy * advance,
                ray.z + dz * advance, ex, ey, ez, 511, state.ped)
            if not current() then return nil, "aim-context-revoked" end
            if retry_lease then Messiah.ReleaseShapeEntity(retry_lease, "discarded-ray-retry") end
            if not current() then return nil, "aim-context-revoked" end
            ray, ray_status = retry_ray, retry_status
            ray_status = ray and "raycast-retry" or "miss"
        end
        if mode == "DIRECT" then
            local point = ray or { x = ex, y = ey, z = ez, entity = 0 }
            point.mode = "DIRECT"
            point.source = ray and (retries > 0 and "raycast-retry" or "raycast")
                or "camera-forward-endpoint"
            Messiah.LogOnce("resolver-final:DIRECT:" .. point.source,
                ("Messiah target resolved: activation=%d mode=DIRECT final=(%.2f,%.2f,%.2f) "
                    .. "source=%s entity=%s.")
                :format(state.activation_id, point.x, point.y, point.z, point.source,
                    tostring(point.entity or 0)))
            return point, point.source
        end

        local seed_source = ray and "raycast" or "forward-projection"
        local seed
        if ray then
            seed = { x = ray.x, y = ray.y, z = ray.z }
            Messiah.ReleaseShapeEntity(ray, "ground-seed-copied")
            if not current() then return nil, "aim-context-revoked" end
        else
            local flat = math.sqrt(dx * dx + dy * dy)
            if flat < 0.001 then return nil, "no-horizontal-seed" end
            seed = {
                x = cx + (dx / flat) * Messiah.GROUND_FORWARD_FALLBACK,
                y = cy + (dy / flat) * Messiah.GROUND_FORWARD_FALLBACK,
                z = cz,
            }
        end
        -- Start just above the aimed surface, not above the whole map. A ray
        -- from the sky selects an unrelated overpass/roof above a road target.
        -- A roof deliberately aimed at still remains the first surface below.
        local top_z = seed.z + 0.25
        local ground, ground_status, ground_lease = Messiah.ShapeRay(seed.x, seed.y, top_z,
            seed.x, seed.y, -1000.0, 1, state.ped)
        if not current() then return nil, "aim-context-revoked" end
        if ground_lease then Messiah.ReleaseShapeEntity(ground_lease, "discarded-ground-result") end
        if not current() then return nil, "aim-context-revoked" end
        if ground then
            local point = {
                x = ground.x,
                y = ground.y,
                z = ground.z,
                mode = "GROUND",
                source = seed_source .. "+downward-probe"
            }
            Messiah.ReleaseShapeEntity(ground, "ground-target-copied")
            if not current() then return nil, "aim-context-revoked" end
            state.last_target, state.last_target_source = point, point.source
            Messiah.LogOnce("resolver-final:GROUND:" .. point.source,
                ("Messiah target resolved: activation=%d mode=GROUND final=(%.2f,%.2f,%.2f) "
                    .. "source=%s immutableOnAccept=true.")
                :format(state.activation_id, point.x, point.y, point.z, point.source))
            return point, point.source
        end
        if gta and type(gta.GetGroundZ) == "function" then
            local ok, found, ground_z = pcall(gta.GetGroundZ, seed.x, seed.y)
            if not current() then return nil, "aim-context-revoked" end
            ground_z = Messiah.FiniteNumber(ground_z)
            -- A terrain fallback must not reintroduce an upper storey after
            -- the bounded downward probe failed or missed streamed geometry.
            if ok and found == true and ground_z and ground_z <= top_z
                and ground_z >= -1000.0 then
                local point = {
                    x = seed.x,
                    y = seed.y,
                    z = ground_z,
                    mode = "GROUND",
                    source = seed_source .. "+ground-z-fallback"
                }
                state.last_target, state.last_target_source = point, point.source
                Messiah.LogOnce("resolver-final:GROUND:" .. point.source,
                    ("Messiah target resolved: activation=%d mode=GROUND final=(%.2f,%.2f,%.2f) "
                        .. "source=%s immutableOnAccept=true.")
                    :format(state.activation_id, point.x, point.y, point.z, point.source))
                return point, point.source
            end
        end
        Messiah.LogOnce("ground-target-failed:" .. tostring(diagnostic_key or "ability"),
            ("Messiah ground target failed: activation=%d ability=%s seed=%s "
                .. "ray_status=%s downward_status=%s no_ped_fallback=true.")
            :format(state.activation_id, tostring(diagnostic_key or "unknown"), seed_source,
                tostring(ray_status), tostring(ground_status)))
        return nil, "no-ground-target"
    end

    function Messiah.UpdateAimSnapshot(now, menu_open)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        if not Messiah.ActivationContextCurrent(state, epoch) then return nil end
        if menu_open then
            Messiah.ReleaseAimEntity("menu-open")
            return State.messiah == state and state.aim_snapshot or nil
        end
        local old_aim, old_hold = state.aim_snapshot, state.aim_guid_hold
        local resolved, source = Messiah.ResolveAimTarget("DIRECT", "RETICLE")
        if not Messiah.ActivationContextCurrent(state, epoch) or state.aim_snapshot ~= old_aim
            or state.aim_guid_hold ~= old_hold then
            return nil
        end
        local lease = type(resolved) == "table" and resolved.entity_lease or nil
        local next_hold = lease and Messiah.HoldAimGuid(lease) or nil
        if not Messiah.ActivationContextCurrent(state, epoch) or state.aim_snapshot ~= old_aim
            or state.aim_guid_hold ~= old_hold then
            return nil
        end
        local same = old_hold and next_hold and old_hold.state == "held"
            and old_hold.handle == next_hold.handle and old_hold.identity == next_hold.identity
            and old_hold.epoch == next_hold.epoch and not Messiah.IsReleasedScriptGuid(old_hold.handle, state)
        state.aim_guid_hold = next_hold
        if old_hold then
            if same then
                old_hold.state = "transferred"
            else
                Messiah.RetireAimGuidHold(old_hold, "aim-snapshot-replaced")
            end
        end
        if not Messiah.ActivationContextCurrent(state, epoch) or state.aim_snapshot ~= old_aim
            or state.aim_guid_hold ~= next_hold then
            return nil
        end
        if old_aim then Messiah.ReleaseShapeEntity(old_aim.target, "aim-snapshot-child-consumed") end
        if not Messiah.ActivationContextCurrent(state, epoch) or state.aim_snapshot ~= old_aim
            or state.aim_guid_hold ~= next_hold then
            return nil
        end
        local retained = type(resolved) == "table" and resolved.entity_retained == true
        local released = type(resolved) == "table" and resolved.entity_released == true
        local target = Messiah.CopyPoint(resolved)
        if target then
            target.entity_retained, target.entity_released = retained, released
        end
        local direct_hit = target ~= nil and (source == "raycast" or source == "raycast-retry")
        state.aim_snapshot = {
            now_ms = tonumber(now) or now_ms(),
            target = target,
            source = tostring(source or "camera-unavailable"),
            direct_hit = direct_hit,
        }
        if state.phase == Messiah.PHASES.LANCE_CHANNEL then
            Messiah.SetReticleMode("CHANNEL", (tonumber(now) or 0) + 100, "lance channel")
        elseif (tonumber(state.reticle_mode_until_ms) or 0) <= (tonumber(now) or 0) then
            Messiah.SetReticleMode(direct_hit and "DIRECT_HIT" or "DIRECT_MISS", 0,
                "source=" .. tostring(source))
        end
        return state.aim_snapshot
    end

    function Messiah.Axis(control)
        local value = 0.0
        if H.GET_DISABLED_CONTROL_NORMAL and type(deps.invoke_float) == "function" then
            value = tonumber(deps.invoke_float(H.GET_DISABLED_CONTROL_NORMAL, 0, control)) or 0.0
        end
        if value ~= value or value == math.huge or value == -math.huge then value = 0.0 end
        if math.abs(value) < 0.08 then return 0.0 end
        return math.max(-1.0, math.min(1.0, value))
    end

    function Messiah.ControlHeld(control)
        -- Messiah disables these controls before sampling them. The disabled
        -- control state is therefore authoritative; mixing in the normal state
        -- can retain a stale RMB level after the physical button is released.
        if H.IS_DISABLED_CONTROL_PRESSED then
            return invoke_bool(H.IS_DISABLED_CONTROL_PRESSED, 0, control)
        end
        return H.IS_CONTROL_PRESSED and invoke_bool(H.IS_CONTROL_PRESSED, 0, control) or false
    end

    function Messiah.SampleAttackSources()
        local native_down = Messiah.ControlHeld(24) or Messiah.ControlHeld(257)
        local mouse_down, mouse_available = false, false
        if utils and type(utils.IsKeyDown) == "function" then
            local ok, down = pcall(utils.IsKeyDown, 0x01)
            if ok then
                mouse_available = true
                mouse_down = down == true
            end
        end
        return mouse_down, native_down, mouse_available
    end

    function Messiah.NativeInputSample(binding, previous_down)
        local held, just_pressed, just_released = false, false, false
        for _, control in ipairs(binding.controls or {}) do
            held = held or Messiah.ControlHeld(control)
            if H.IS_DISABLED_CONTROL_JUST_PRESSED then
                just_pressed = just_pressed
                    or invoke_bool(H.IS_DISABLED_CONTROL_JUST_PRESSED, 0, control)
            end
            if H.IS_DISABLED_CONTROL_JUST_RELEASED then
                just_released = just_released
                    or invoke_bool(H.IS_DISABLED_CONTROL_JUST_RELEASED, 0, control)
            end
        end
        just_pressed = just_pressed or (held and not previous_down)
        just_released = just_released or (not held and previous_down)
        return held, just_pressed, just_released, "disabled-control-edge"
    end

    function Messiah.KeyboardInputSample(binding, previous_down)
        if utils and type(utils.IsKeyDown) == "function" then
            local ok, held = pcall(utils.IsKeyDown, binding.key)
            if ok then
                held = held == true
                return held, held and not previous_down, not held and previous_down,
                    "keyboard-level-edge"
            end
        end
        local held, pressed, released = Messiah.NativeInputSample(binding, previous_down)
        return held, pressed, released, "disabled-control-edge-fallback"
    end

    function Messiah.InputBackendIdentity()
        local native = H.IS_DISABLED_CONTROL_JUST_PRESSED and H.IS_DISABLED_CONTROL_JUST_RELEASED
            and "disabled-control-edges" or "disabled-control-level"
        local keyboard = utils and type(utils.IsKeyDown) == "function"
            and "keyboard-level-edges" or "native-key-fallback"
        return native .. "+" .. keyboard
    end

    function Messiah.InitializeInputState(menu_open)
        local state = Messiah.State()
        state.inputs = {}
        state.input_backend = Messiah.InputBackendIdentity()
        for ability, binding in pairs(Messiah.INPUT_BINDINGS) do
            local held
            if binding.backend == "keyboard" then
                held = select(1, Messiah.KeyboardInputSample(binding, false))
            else
                held = select(1, Messiah.NativeInputSample(binding, false))
            end
            state.inputs[ability] = { down = held == true, armed = held ~= true, source = "baseline" }
        end
        local mouse_down, native_down, mouse_available = Messiah.SampleAttackSources()
        state.attack_mouse_down, state.attack_native_down = mouse_down, native_down
        state.attack_mouse_available = mouse_available
        state.attack_down = native_down
        state.attack_armed = state.inputs.ORB and state.inputs.ORB.armed == true
        state.attack_backend = "disabled-control-edge"
        state.attack_source = native_down and "disabled-control-edge" or "none"
        state.menu_was_open = menu_open == true
        state.menu_close_baseline = menu_open == true
        Messiah.Trace(("Messiah input backend selected: activation=%d authority=%s "
                .. "raw_mouse=diagnostic-only menu_open=%s native_attack=%s raw_mouse_down=%s.")
            :format(state.activation_id, state.input_backend, tostring(menu_open == true),
                tostring(native_down), tostring(mouse_down)))
    end

    function Messiah.UpdateMouseHealth(now, mouse_down, native_down, mouse_available)
        local state = Messiah.State()
        state.attack_mouse_down = mouse_down
        state.attack_native_down = native_down
        state.attack_mouse_available = mouse_available
        if not mouse_available then
            state.mouse_disagree_since_ms, state.mouse_disagree_samples = 0, 0
            return
        end
        if state.mouse_stale and not mouse_down then
            state.mouse_stale = false
            state.mouse_disagree_since_ms, state.mouse_disagree_samples = 0, 0
            Messiah.LogOnce("input-mouse-recovered",
                ("Messiah raw mouse recovered: activation=%d raw_mouse=false native_attack=%s "
                    .. "authority=disabled-control-edge.")
                :format(state.activation_id, tostring(native_down)))
            return
        end
        if mouse_down and not native_down then
            if state.mouse_disagree_since_ms == 0 then state.mouse_disagree_since_ms = now end
            state.mouse_disagree_samples = state.mouse_disagree_samples + 1
            if not state.mouse_stale
                and (now - state.mouse_disagree_since_ms >= Messiah.INPUT_MOUSE_STALE_MS
                    or state.mouse_disagree_samples >= Messiah.INPUT_MOUSE_STALE_SAMPLES) then
                state.mouse_stale = true
                Messiah.LogOnce("input-mouse-stale",
                    ("Messiah raw mouse declared STALE: activation=%d raw_mouse=true "
                        .. "native_attack=false samples=%d elapsed_ms=%d action=diagnostic-only.")
                    :format(state.activation_id, state.mouse_disagree_samples,
                        now - state.mouse_disagree_since_ms))
            end
        else
            state.mouse_disagree_since_ms, state.mouse_disagree_samples = 0, 0
        end
    end

    -- Menu frames and the first frame after close only refresh baselines.
    -- Raw VK_LBUTTON is diagnostic-only: it can remain high while gameplay Attack is low.
    function Messiah.ProcessAbilityInputs(now, menu_open)
        local state = Messiah.State()
        now = tonumber(now) or now_ms()
        local mouse_down, native_down, mouse_available = Messiah.SampleAttackSources()
        if not menu_open then Messiah.UpdateMouseHealth(now, mouse_down, native_down, mouse_available) end
        local backend = Messiah.InputBackendIdentity()
        local backend_changed = state.input_backend ~= backend
        local samples = {}
        for ability, binding in pairs(Messiah.INPUT_BINDINGS) do
            local previous = state.inputs[ability] and state.inputs[ability].down == true or false
            local held, pressed, released, source
            if binding.backend == "keyboard" then
                held, pressed, released, source = Messiah.KeyboardInputSample(binding, previous)
            else
                held, pressed, released, source = Messiah.NativeInputSample(binding, previous)
            end
            samples[ability] = { held = held, pressed = pressed, released = released, source = source }
        end

        if menu_open then
            if state.action and state.action.ability == "LANCE"
                and state.phase ~= Messiah.PHASES.LANCE_RELEASE
                and state.phase ~= Messiah.PHASES.LANCE_RECOVER then
                Messiah.EndVoidLance(now, "menu-open")
            end
            if not state.menu_was_open then
                state.menu_was_open, state.menu_close_baseline = true, true
                if not state.pending_allow_menu then
                    state.pending_ability, state.pending_target = nil, nil
                    state.pending_source, state.pending_allow_menu = "none", false
                    state.queued_cast, state.cast_edge_pending = false, false
                end
                Messiah.LogOnce("input-menu-open",
                    ("Messiah input gated: activation=%d menu=open gameplayPendingCancelled=%s "
                        .. "menuButtonPending=%s.")
                    :format(state.activation_id, tostring(not state.pending_allow_menu),
                        tostring(state.pending_allow_menu)))
            end
            for ability, sample in pairs(samples) do
                local input = state.inputs[ability] or {}
                input.down, input.armed, input.source = sample.held, false, "menu-baseline"
                state.inputs[ability] = input
                if sample.pressed then
                    Messiah.LogOnce("input-menu-edge:" .. ability,
                        ("Messiah input edge ignored: activation=%d ability=%s reason=menu-open.")
                        :format(state.activation_id, ability))
                end
            end
            return false
        end

        if state.menu_was_open or state.menu_close_baseline or backend_changed then
            state.menu_was_open, state.menu_close_baseline = false, false
            state.input_backend = backend
            for ability, sample in pairs(samples) do
                state.inputs[ability] = {
                    down = sample.held, armed = not sample.held, source = "baseline",
                }
            end
            state.attack_down = samples.ORB and samples.ORB.held == true
            state.attack_armed = state.inputs.ORB and state.inputs.ORB.armed == true
            state.attack_source = state.attack_down and "disabled-control-edge" or "none"
            Messiah.Trace(("Messiah input baseline: activation=%d menu=closed authority=%s "
                    .. "native_attack=%s raw_mouse=%s raw_stale=%s armed=%s synthetic=false.")
                :format(state.activation_id, backend, tostring(native_down), tostring(mouse_down),
                    tostring(state.mouse_stale), tostring(state.attack_armed)))
            return false
        end

        local accepted = false
        for _, ability in ipairs(Messiah.INPUT_PRIORITY) do
            local sample = samples[ability]
            local input = state.inputs[ability] or { down = false, armed = true }
            if sample.released or (not sample.held and input.down) then
                if not input.armed then
                    input.armed = true
                    Messiah.Trace(("Messiah input UP rearmed: activation=%d ability=%s source=%s.")
                        :format(state.activation_id, ability, sample.source))
                end
            end
            if sample.pressed then
                state.input_edge_serial = state.input_edge_serial + 1
                if input.armed then
                    input.armed = false
                    input.source = sample.source
                    if (ability == "RUPTURE" or ability == "SHOCKWAVE" or ability == "SUPER")
                        and state.action and state.action.ability == "LANCE"
                        and state.phase ~= Messiah.PHASES.LANCE_RELEASE
                        and state.phase ~= Messiah.PHASES.LANCE_RECOVER then
                        Messiah.EndVoidLance(now, "cancelled-by-" .. ability)
                    end
                    local did_accept = Messiah.RequestAbility(ability, now,
                        "key:" .. Messiah.INPUT_BINDINGS[ability].label)
                    accepted = did_accept or accepted
                    Messiah.Trace(("Messiah input DOWN edge %s: activation=%d serial=%d ability=%s "
                            .. "source=%s raw_mouse=%s raw_stale=%s.")
                        :format(did_accept and "accepted" or "rejected", state.activation_id,
                            state.input_edge_serial, ability, sample.source, tostring(mouse_down),
                            tostring(state.mouse_stale)))
                else
                    Messiah.Trace(("Messiah input edge ignored: activation=%d ability=%s source=%s reason=not-armed.")
                        :format(state.activation_id, ability, sample.source))
                end
            end
            input.down = sample.held
            state.inputs[ability] = input
        end
        state.attack_down = samples.ORB and samples.ORB.held == true
        state.attack_armed = state.inputs.ORB and state.inputs.ORB.armed == true
        state.attack_source = state.attack_down and "disabled-control-edge" or "none"
        return accepted
    end

    function Messiah.ProcessAttackInput(menu_open)
        return Messiah.ProcessAbilityInputs(now_ms(), menu_open)
    end

    function Messiah.EnsureDeletePtr()
        local state = Messiah.State()
        if state.delete_ptr ~= 0 then return state.delete_ptr end
        if not (memory and type(memory.AllocInt) == "function" and type(memory.WriteInt) == "function") then
            return 0
        end
        local ok, ptr = pcall(memory.AllocInt)
        ptr = ok and tonumber(ptr) or 0
        if ptr ~= 0 then state.delete_ptr = ptr end
        return ptr
    end

    function Messiah.CleanupSnapshot()
        local evidence = messiah_cleanup_evidence
        local result = {
            unresolved = evidence.unresolved,
            overflow = evidence.overflow,
            confirmed_deleted = 0,
            records = {},
            evidence_scope = "local requests only"
        }
        for _, record in ipairs(evidence.records) do
            local copy = {}; for key, value in pairs(record) do copy[key] = value end
            result.records[#result.records + 1] = copy
        end
        return result
    end

    function Messiah.RecordCleanupEvidence(lease, detail, requested)
        if type(lease) ~= "table" then return end
        if lease.cleanup_evidence_recorded then return lease.cleanup_evidence end
        lease.cleanup_evidence_recorded = true
        local evidence = messiah_cleanup_evidence
        evidence.serial = evidence.serial + 1
        evidence.unresolved = evidence.unresolved + 1
        local outcome = "unknown"
        if lease.identity_replaced == true then
            outcome = "identity-replaced"
        elseif lease.local_presence == false then
            outcome = "locally-absent"
        elseif requested == true then
            outcome = "requested"
        end
        local record = {
            serial = evidence.serial,
            activation = tonumber(lease.epoch) or 0,
            action = tonumber(lease.action_serial) or 0,
            creation = tonumber(lease.creation_serial) or 0,
            kind = tostring(lease.kind or "unknown"),
            source = tostring(lease.source or "unknown"),
            outcome = outcome,
            detail = tostring(detail or "unavailable"),
            requested = requested == true,
            network = "unavailable",
            scope = messiah_cleanup_evidence.scope_ending and "ended" or "current",
            invocation = requested and "pending" or "not-requested",
            confirmed_deleted = false
        }
        if #evidence.records < MESSIAH_EVIDENCE_LIMIT then
            evidence.records[#evidence.records + 1] = record
            lease.cleanup_evidence = record
        else
            -- Do not evict an unresolved lifetime or silently lose its count.
            evidence.overflow = evidence.overflow + 1
        end
        return record
    end

    function Messiah.LogCleanupEvidence(reason)
        local evidence = messiah_cleanup_evidence
        if evidence.unresolved == 0 then return end
        log_info(("Messiah cleanup evidence: reason=%s unresolved=%d retained=%d overflow=%d outcome=unverified; no destruction proof.")
            :format(tostring(reason), evidence.unresolved, #evidence.records, evidence.overflow))
        for _, record in ipairs(evidence.records) do
            log_info(("Messiah cleanup record: serial=%d activation=%d action=%d creation=%d kind=%s outcome=%s detail=%s scope=%s network=%s invocation=%s.")
                :format(record.serial, record.activation, record.action, record.creation, record.kind,
                    record.outcome, record.detail, record.scope, record.network, record.invocation))
        end
        -- Logger is best-effort host diagnostics, not verified durable storage.
    end

    function Messiah.DeleteEntity(entity, lease)
        entity = Messiah.NormalizeEntityHandle(entity)
        lease = lease or (Messiah.State().projectiles[entity] or {}).lease
        if not lease or lease.handle ~= entity or lease.owned ~= true then
            return false, "owned-lease-unavailable", true
        end
        if entity == 0 or not Messiah.ValidateEntityLease(lease, "delete-start", "none") then
            Messiah.RecordCleanupEvidence(lease, "abandoned-invalid-lease", false)
            Messiah.RetireEntityLease(lease, "delete-access-ended", false)
            return false, "abandoned-invalid-lease", true
        end
        local ptr = Messiah.EnsureDeletePtr()
        if ptr == 0 then return false, "pointer-unavailable", false end
        Messiah.LeaseInvoke(lease, "void", "SET_ENTITY_AS_MISSION_ENTITY",
            H.SET_ENTITY_AS_MISSION_ENTITY, entity, true, true)
        local written = pcall(memory.WriteInt, ptr, entity)
        if not written then return false, "pointer-write-failed", false end
        if not Messiah.ValidateEntityLease(lease, "DELETE_ENTITY", H.DELETE_ENTITY) then
            Messiah.RecordCleanupEvidence(lease, "delete-lease-retired", false)
            return false, "delete-lease-retired", true
        end
        -- Archive before the fallible boundary, revoke access before DELETE,
        -- and never probe the retired alias to turn a void return into proof.
        local evidence = Messiah.RecordCleanupEvidence(lease, "DELETE_ENTITY-outcome-unverified", true)
        Messiah.RetireEntityLease(lease, "delete-invocation", true)
        local accepted = invoke_void_detail(H.DELETE_ENTITY, ptr)
        if evidence then evidence.invocation = accepted == true and "accepted-unverified" or "error-or-unavailable" end
        return false, accepted == true and "DELETE_ENTITY-accepted-unverified"
            or "DELETE_ENTITY-error-unverified", true
    end

    function Messiah.FxHandle(value)
        if type(value) == "table" then return tonumber(value.handle) or 0 end
        return tonumber(value) or 0
    end

    function Messiah.StopFx(value)
        local state = Messiah.State()
        if type(value) == "table" and value.local_fx_cleanup_uncertain then
            error("Messiah local FX cleanup outcome is uncertain; native retry forbidden", 0)
        end
        local handle = Messiah.FxHandle(value)
        if type(value) == "table" then value.handle = 0 end
        if state.gameplay_owner ~= true or state.disposed then return false end
        if handle ~= 0 and H.STOP_PARTICLE_FX_LOOPED then
            local accepted = invoke_void_detail(H.STOP_PARTICLE_FX_LOOPED, handle, false)
            if accepted ~= true then error("Messiah STOP_PARTICLE_FX_LOOPED failed; cleanup aborted", 0) end
        end
        return true
    end

    function Messiah.SetFxAlpha(value, alpha)
        local handle = Messiah.FxHandle(value)
        alpha = clamp(tonumber(alpha) or 1.0, 0.0, 1.0)
        if handle ~= 0 and H.SET_PARTICLE_FX_LOOPED_ALPHA then
            invoke_void(H.SET_PARTICLE_FX_LOOPED_ALPHA, handle, alpha)
        end
    end

    function Messiah.SoundId()
        if not H.GET_SOUND_ID then return -1 end
        return tonumber(invoke_int(H.GET_SOUND_ID)) or -1
    end

    function Messiah.ReleaseOwnedSound(record, reason)
        local state = Messiah.State()
        if state.gameplay_owner ~= true or state.disposed then
            error("Messiah sound cleanup requires the gameplay owner; no native issued", 0)
        end
        if type(record) ~= "table" or type(record.id) ~= "number" or record.id < 0 then return false end
        -- Each host operation is attempted at most once. Retain the record when
        -- the host may have partially performed it; later cleanup cannot safely
        -- repeat an uncertain STOP/RELEASE against a possibly reused sound ID.
        if not record.stop_attempted then
            record.stop_attempted = true
            local accepted = invoke_void_detail(H.STOP_SOUND, record.id)
            record.stop_completed = accepted == true
        end
        if record.stop_completed ~= true then
            record.cleanup_failure = "STOP_SOUND uncertain: " .. tostring(reason)
            error("Messiah sound cleanup aborted; STOP_SOUND uncertain; ownership retained", 0)
        end
        if not record.release_attempted then
            record.release_attempted = true
            local accepted = invoke_void_detail(H.RELEASE_SOUND_ID, record.id)
            record.release_completed = accepted == true
        end
        if record.release_completed ~= true then
            record.cleanup_failure = "RELEASE_SOUND_ID uncertain: " .. tostring(reason)
            error("Messiah sound cleanup aborted; RELEASE_SOUND_ID uncertain; ownership retained", 0)
        end
        return true
    end

    function Messiah.ForgetReleasedSound(record)
        if type(record) ~= "table" or record.release_completed ~= true then return false end
        local sounds = Messiah.State().sounds
        for index = #sounds, 1, -1 do
            if sounds[index] == record then
                table.remove(sounds, index); return true
            end
        end
        return false
    end

    function Messiah.PollAudioBanks(now, preferred)
        local state = Messiah.State()
        if state.gameplay_owner ~= true or state.disposed or state.ending or state.restoring
            or type(state.audio_bank_pending) ~= "table" then
            return 0
        end
        now = tonumber(now) or now_ms()
        if state.audio_bank_poll_frame ~= state.entity_frame then
            state.audio_bank_poll_frame, state.audio_bank_poll_count = state.entity_frame, 0
        end
        local order = preferred and { preferred } or {
            "DLC_CHRISTMAS2017/XM_ION_CANNON", "DLC_CHRISTMAS2017/XM_Silo_Laser_Hack",
            "BARRY_01_ALIEN_A", "BARRY_01_ALIEN_B", "BARRY_01_ALIEN_C", "DLC_VINEWOOD/DLC_VW_AM_IP" }
        local polled = 0
        for _, bank in ipairs(order) do
            if state.audio_bank_poll_count >= 2 then break end
            local pending = state.audio_bank_pending[bank]
            if pending and pending.epoch == state.activation_epoch and pending.attempts < 20
                and now <= pending.deadline_ms and now >= pending.next_ms then
                pending.attempts = pending.attempts + 1; pending.next_ms = now + 250
                state.audio_bank_poll_count = state.audio_bank_poll_count + 1; polled = polled + 1
                local loaded, _, err = invoke_bool_detail(H.REQUEST_SCRIPT_AUDIO_BANK, bank, false, -1)
                if err == nil and loaded == true then
                    state.audio_banks_owned[bank], state.audio_bank_owned = true, true
                    state.audio_bank_pending[bank] = nil
                    Messiah.LogOnce("audio-bank-ready:" .. bank,
                        ("Messiah audio bank ready: activation=%d bank=%s attempts=%d acceptedReference=1.")
                        :format(state.activation_id, bank, pending.attempts))
                elseif err ~= nil then
                    pending.attempts = 20
                end
            end
        end
        return polled
    end

    function Messiah.SoundBankReady(sound_set)
        local bank = sound_set == "dlc_xm_orbital_cannon_sounds"
            and "DLC_CHRISTMAS2017/XM_ION_CANNON"
            or sound_set == "dlc_xm_silo_laser_hack_sounds"
            and "DLC_CHRISTMAS2017/XM_Silo_Laser_Hack" or nil
        if not bank then return true end
        local state = Messiah.State()
        if state.audio_banks_owned[bank] == true then return true end
        Messiah.PollAudioBanks(now_ms(), bank)
        if state.audio_banks_owned[bank] == true then return true end
        Messiah.LogOnce("audio-bank-unavailable:" .. bank,
            ("Messiah audio unavailable: activation=%d bank=%s requestAccepted=false; cue skipped before allocation.")
            :format(state.activation_id, bank))
        return false
    end

    function Messiah.SoundPriority(role)
        role = tostring(role or "ability")
        if role:find("core", 1, true) then return 50 end
        if role == "lance-loop" or role == "judgment-descent" then return 40 end
        if role:find("charge", 1, true) then return 30 end
        if role:find("satellite", 1, true) or role:find("support", 1, true) then return 10 end
        return 20
    end

    function Messiah.ReserveSoundSlot(role, context)
        local state = Messiah.State()
        context = type(context) == "table" and context or {}
        if state.gameplay_owner ~= true or state.disposed or state.ending or state.restoring
            or (context.epoch ~= nil and context.epoch ~= state.activation_epoch)
            or context.no_audio == true or context.host_retry == true then
            return false
        end
        local priority = Messiah.SoundPriority(role)
        local serial = tonumber(context.action_serial)
            or (state.action and state.action.serial) or state.action_serial
        if #state.sounds < Messiah.MAX_SOUND_HANDLES then return true end
        local victim_index, victim_priority
        for index, record in ipairs(state.sounds) do
            local record_priority = tonumber(record.priority) or Messiah.SoundPriority(record.role)
            -- A core may reclaim optional satellites, but never its own descent
            -- bed or an active held channel. Equal-priority support cannot churn
            -- IDs; a new critical core may supersede an older action's core.
            local bed = record.role == "judgment-descent" or record.role == "lance-loop"
            local eligible = not bed and (record_priority < priority
                or (priority == 50 and record_priority == 50 and record.action_serial ~= serial))
            if eligible and (not victim_index or record_priority < victim_priority) then
                victim_index, victim_priority = index, record_priority
            end
        end
        if not victim_index then
            Messiah.LogOnce("sound-budget:" .. tostring(role),
                ("Messiah audio budget: activation=%d role=%s priority=%d admitted=false maxHandles=%d.")
                :format(state.activation_id, tostring(role), priority, Messiah.MAX_SOUND_HANDLES))
            return false
        end
        local victim = state.sounds[victim_index]
        Messiah.ReleaseOwnedSound(victim, "priority-preemption")
        table.remove(state.sounds, victim_index)
        return true
    end

    function Messiah.TrackSound(role, sound_id, expires_ms, looped, context)
        local state = Messiah.State()
        context = type(context) == "table" and context or {}
        sound_id = tonumber(sound_id) or -1
        if sound_id < 0 then return false end
        -- PLAY helpers reserve BEFORE allocating. Fail closed if a caller ever
        -- bypasses admission; never silently forget a possibly audible new ID.
        if #state.sounds >= Messiah.MAX_SOUND_HANDLES then
            invoke_void(H.STOP_SOUND, sound_id)
            invoke_void(H.RELEASE_SOUND_ID, sound_id)
            return false
        end
        state.sounds[#state.sounds + 1] = {
            id = sound_id,
            role = tostring(role or "ability"),
            priority = Messiah.SoundPriority(role),
            epoch = state.activation_epoch,
            action_serial = tonumber(context.action_serial)
                or (state.action and state.action.serial) or state.action_serial,
            expires_ms = tonumber(expires_ms) or (now_ms() + 1500),
            looped = looped == true,
        }
        return true
    end

    function Messiah.PlayFrontendSound(role, sound_name, sound_set, duration_ms, looped, context)
        if not H.PLAY_SOUND_FRONTEND or not Messiah.SoundBankReady(sound_set)
            or not Messiah.ReserveSoundSlot(role, context) then
            return false
        end
        local id = Messiah.SoundId()
        if id < 0 then return false end
        if not Messiah.TrackSound(role, id, now_ms() + (tonumber(duration_ms) or 1600), looped, context) then return false end
        local record = Messiah.State().sounds[#Messiah.State().sounds]
        if invoke_void(H.PLAY_SOUND_FRONTEND, id, sound_name, sound_set, true) ~= true then
            Messiah.ReleaseOwnedSound(record, "failed-play")
            Messiah.ForgetReleasedSound(record)
            return false
        end
        Messiah.LogOnce("sound-contract:" .. tostring(role),
            ("Messiah ability audio: activation=%d role=%s name=%s set=%s backend=PLAY_SOUND_FRONTEND tracked=true.")
            :format(Messiah.State().activation_id, tostring(role), tostring(sound_name),
                tostring(sound_set)))
        return true
    end

    function Messiah.PlayEntitySound(role, entity, sound_name, sound_set, duration_ms, looped, context)
        entity = Messiah.NormalizeEntityHandle(entity)
        if entity == 0 then return false end
        local state = Messiah.State()
        local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame and state.action == action
        end
        local online = Messiah.FxOnline()
        if online == nil or not current() then return false end
        local lease = Messiah.AcquireEntityLease(entity, nil, {
            source = "sound",
            owned = entity == state.ped,
            action = state.action and state.action.ability
        })
        if not lease or not current() then return false end
        if not H.PLAY_SOUND_FROM_ENTITY or not Messiah.SoundBankReady(sound_set)
            or not Messiah.ValidateEntityLease(lease, "entity-sound", "none")
            or not current()
            or not Messiah.ReserveSoundSlot(role, context) then
            return false
        end
        local id = Messiah.SoundId()
        if id < 0 then return false end
        if not Messiah.TrackSound(role, id, now_ms() + (tonumber(duration_ms) or 1600), looped, context) then return false end
        local record = Messiah.State().sounds[#Messiah.State().sounds]
        if Messiah.LeaseInvoke(lease, "void", "PLAY_SOUND_FROM_ENTITY", H.PLAY_SOUND_FROM_ENTITY, id, sound_name, entity,
                sound_set, online, 0) ~= true then
            Messiah.ReleaseOwnedSound(record, "failed-play")
            Messiah.ForgetReleasedSound(record)
            return false
        end
        Messiah.LogOnce("sound-contract:" .. tostring(role),
            ("Messiah ability audio: activation=%d role=%s name=%s set=%s backend=PLAY_SOUND_FROM_ENTITY tracked=true.")
            :format(Messiah.State().activation_id, tostring(role), tostring(sound_name),
                tostring(sound_set)))
        return true
    end

    function Messiah.PlayCoordSound(role, position, sound_name, sound_set, duration_ms, context)
        local state = Messiah.State()
        local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame and state.action == action
        end
        local online = Messiah.FxOnline()
        if online == nil or not current() then return false end
        position = Messiah.CopyPoint(position)
        if not position or not H.PLAY_SOUND_FROM_COORD or not Messiah.SoundBankReady(sound_set)
            or not current()
            or not Messiah.ReserveSoundSlot(role, context) then
            return false
        end
        local id = Messiah.SoundId()
        if id < 0 then return false end
        if not Messiah.TrackSound(role, id, now_ms() + (tonumber(duration_ms) or 2600), false, context) then return false end
        local record = Messiah.State().sounds[#Messiah.State().sounds]
        if invoke_void(H.PLAY_SOUND_FROM_COORD, id, sound_name,
                position.x, position.y, position.z, sound_set, online, 80, false) ~= true then
            Messiah.ReleaseOwnedSound(record, "failed-play")
            Messiah.ForgetReleasedSound(record)
            return false
        end
        Messiah.LogOnce("sound-contract:" .. tostring(role),
            ("Messiah ability audio: activation=%d role=%s name=%s set=%s backend=PLAY_SOUND_FROM_COORD tracked=true.")
            :format(Messiah.State().activation_id, tostring(role), tostring(sound_name),
                tostring(sound_set)))
        return true
    end

    function Messiah.StopSoundRole(role)
        local state = Messiah.State()
        if state.gameplay_owner ~= true or state.disposed then return 0 end
        local stopped = 0
        for index = #state.sounds, 1, -1 do
            local record = state.sounds[index]
            if role == nil or tostring(record.role) == tostring(role) then
                Messiah.ReleaseOwnedSound(record, "role-stop:" .. tostring(role))
                table.remove(state.sounds, index)
                stopped = stopped + 1
            end
        end
        return stopped
    end

    function Messiah.UpdateSounds(now)
        local state = Messiah.State()
        if state.gameplay_owner ~= true or state.disposed then return end
        -- Prewarm pending banks through the existing gameplay audio tick. This
        -- remains bounded even if the first Judgment is cast long after enable.
        Messiah.PollAudioBanks(now)
        for index = #state.sounds, 1, -1 do
            local record = state.sounds[index]
            if record.cleanup_failure then
                -- Even HAS_SOUND_FINISHED is forbidden after an uncertain
                -- release: that numeric ID may already belong to another sound.
                Messiah.ReleaseOwnedSound(record, "prior-cleanup-fault")
            end
            local expired = now >= (tonumber(record.expires_ms) or 0)
            local finished = record.looped ~= true and H.HAS_SOUND_FINISHED
                and invoke_bool(H.HAS_SOUND_FINISHED, record.id)
            if expired or finished or (record.epoch ~= nil and record.epoch ~= state.activation_epoch) then
                Messiah.ReleaseOwnedSound(record, "expiry-or-epoch")
                table.remove(state.sounds, index)
            end
        end
    end

    function Messiah.InitializeModelStreaming(now)
        local state = Messiah.State()
        if state.model_state ~= "UNAVAILABLE" then return Messiah.ModelUsable() end
        now = tonumber(now) or now_ms()
        local u32, s32, identity = Messiah.ModelIdentity()
        Messiah.LogOnce("model-identity",
            ("Messiah model identity: activation=%d %s primary=%s fallback=%s.")
            :format(state.activation_id, identity, "GTA.CreateObject(string)",
                "CREATE_OBJECT_NO_OFFSET"))

        if not (H.REQUEST_MODEL and H.HAS_MODEL_LOADED
                and H.IS_MODEL_IN_CDIMAGE and H.IS_MODEL_VALID) then
            Messiah.LogOnce("model-native-unavailable",
                ("Messiah model unavailable: activation=%d %s missing streaming native binding.")
                :format(state.activation_id, identity))
            return false
        end

        local in_cdimage, _, cd_error = Messiah.LogBoolNative(
            "IS_MODEL_IN_CDIMAGE", Messiah.MODEL_NATIVE_NAMES.IS_MODEL_IN_CDIMAGE,
            H.IS_MODEL_IN_CDIMAGE, s32)
        local valid, _, valid_error = Messiah.LogBoolNative(
            "IS_MODEL_VALID", Messiah.MODEL_NATIVE_NAMES.IS_MODEL_VALID,
            H.IS_MODEL_VALID, s32)
        if cd_error or valid_error then
            Messiah.LogOnce("model-validation-bridge-error",
                ("Messiah model unavailable: activation=%d %s validation_bridge_error=%s|%s.")
                :format(state.activation_id, identity, tostring(cd_error), tostring(valid_error)))
            return false
        end
        if not in_cdimage or not valid then
            Messiah.SetModelState("INVALID",
                ("in_cdimage=%s valid=%s model_u32=%s")
                :format(tostring(in_cdimage), tostring(valid), tostring(u32)))
            return false
        end

        local loaded, raw_loaded, loaded_error = invoke_bool_detail(H.HAS_MODEL_LOADED, s32)
        Messiah.LogOnce("native-bool:HAS_MODEL_LOADED:first",
            ("Messiah model native: name=HAS_MODEL_LOADED hash=%s %s arg_s32=%s "
                .. "normalized=%s raw=%s error=%s backend=%s.")
            :format(Messiah.MODEL_NATIVE_NAMES.HAS_MODEL_LOADED, identity, tostring(s32),
                tostring(loaded), Messiah.RawValue(raw_loaded), tostring(loaded_error),
                "Natives.InvokeBool"))
        if loaded_error then
            Messiah.LogOnce("model-loaded-bridge-error",
                ("Messiah model unavailable: activation=%d HAS_MODEL_LOADED error=%s.")
                :format(state.activation_id, tostring(loaded_error)))
            return false
        end
        if loaded then
            Messiah.SetModelState("READY", "already_loaded=true model_owned=false")
            return true
        end

        local requested, raw_request, request_error = invoke_void_detail(H.REQUEST_MODEL, s32)
        Messiah.LogOnce("native-void:REQUEST_MODEL",
            ("Messiah model native: name=REQUEST_MODEL hash=%s %s arg_s32=%s "
                .. "accepted=%s raw=%s error=%s backend=%s.")
            :format(Messiah.MODEL_NATIVE_NAMES.REQUEST_MODEL, identity, tostring(s32),
                tostring(requested), Messiah.RawValue(raw_request), tostring(request_error),
                "Natives.InvokeVoid"))
        if not requested then
            Messiah.LogOnce("model-request-failed",
                ("Messiah model unavailable: activation=%d REQUEST_MODEL failed model_u32=%s raw=%s error=%s.")
                :format(state.activation_id, tostring(u32), Messiah.RawValue(raw_request),
                    tostring(request_error)))
            return false
        end

        state.model_requested = true
        state.model_owned = true
        state.model_requested_ms = now
        state.model_deadline_ms = now + Messiah.MODEL_TIMEOUT_MS
        state.model_next_poll_ms = now + Messiah.MODEL_POLL_INTERVAL_MS
        state.model_poll_count = 0
        Messiah.SetModelState("REQUESTED", "request_once=true model_owned=true")
        return false
    end

    function Messiah.AnimationProfile(ped)
        local state = Messiah.State()
        if state.anim_variant == "female" then return Messiah.ANIMATIONS.female end
        if state.anim_variant == "male" then return Messiah.ANIMATIONS.male end
        local female_hash = Messiah.NormalizeHash(utils.Joaat("mp_f_freemode_01"))
        local model_hash = entity_exists(ped)
            and Messiah.NormalizeHash(invoke_int(H.GET_ENTITY_MODEL, ped)) or 0
        state.anim_variant = model_hash == female_hash and "female" or "male"
        return Messiah.ANIMATIONS[state.anim_variant]
    end

    function Messiah.InitializeAssets(now)
        local state = Messiah.State()
        if state.asset_request_initialized then return end
        now = tonumber(now) or now_ms()
        state.asset_request_initialized = true
        state.asset_deadline_ms = now + Messiah.ASSET_TIMEOUT_MS
        local profile = Messiah.AnimationProfile(state.ped)
        local animation_dicts = {}
        for _, spec in ipairs(profile.idle_candidates or {}) do
            animation_dicts[#animation_dicts + 1] = spec.dict
        end
        for _, kind in ipairs({ "orb", "lance", "rupture", "shockwave", "super" }) do
            if profile[kind] then animation_dicts[#animation_dicts + 1] = profile[kind].dict end
        end
        local unique_dicts = {}
        for _, dict in ipairs(animation_dicts) do
            if not unique_dicts[dict] then
                unique_dicts[dict] = true
                -- Own a streaming reference even if another script loaded the dictionary,
                -- so its release cannot evict this activation's animation.
                state.anim_requested[dict] = invoke_void(H.REQUEST_ANIM_DICT, dict) == true
            end
        end
        for _, asset in ipairs(Messiah.PTFX_ASSETS) do
            state.ptfx_requested[asset] = invoke_void(H.REQUEST_NAMED_PTFX_ASSET, asset) == true
        end
        local audio_results = {}
        state.audio_bank_pending = {}
        state.audio_bank_poll_frame, state.audio_bank_poll_count = nil, 0
        for _, bank in ipairs(Messiah.AUDIO_BANKS) do
            local loaded, raw, err = invoke_bool_detail(H.REQUEST_SCRIPT_AUDIO_BANK,
                bank, false, -1)
            if err == nil and loaded == true then
                state.audio_banks_owned[bank] = true
                state.audio_bank_owned = true
            elseif err == nil then
                state.audio_bank_pending[bank] = {
                    epoch = state.activation_epoch,
                    attempts = 1,
                    next_ms = now + 250,
                    deadline_ms = now + Messiah.ASSET_TIMEOUT_MS
                }
            end
            audio_results[#audio_results + 1] = ("%s=%s/raw:%s/error:%s")
                :format(bank, tostring(loaded == true), Messiah.RawValue(raw), tostring(err or "none"))
        end
        Messiah.LogOnce("asset-ownership",
            ("Messiah asset requests initialized: activation=%d animation_dicts=%d "
                .. "ptfx_assets=%d audioBanks=%d ownership=one-accepted-audio-reference-per-asset boundedFalsePolls=true.")
            :format(state.activation_id, count_entries(unique_dicts), #Messiah.PTFX_ASSETS,
                count_entries(state.audio_banks_owned)))
        Messiah.LogOnce("audio-bank-selection",
            ("Messiah audio bank requests: activation=%d authority=scriptAudioBankNames.json "
                .. "results={%s} liveAcceptance=pending.")
            :format(state.activation_id, table.concat(audio_results, ";")))
        local idle_labels = {}
        for _, candidate in ipairs(profile.idle_candidates or {}) do
            idle_labels[#idle_labels + 1] = candidate.dict .. "/" .. candidate.name
        end
        Messiah.LogOnce("animation-selection",
            ("Messiah animation shortlist: activation=%d variant=%s "
                .. "idleCandidates={%s} "
                .. "casts={orb=%s lance=%s rupture=%s shockwave=%s super=%s} "
                .. "authority=gta-v-data-dumps-v3717 liveAcceptance=pending.")
            :format(state.activation_id, state.anim_variant,
                table.concat(idle_labels, ";"),
                profile.orb.name, profile.lance.name, profile.rupture.name,
                profile.shockwave.name, profile.super.name))
        Messiah.LogOnce("fx-selection",
            ("Messiah FX selection: activation=%d torso=%s/%s limbs=%s/%s "
                .. "orb=%s/%s shockwaveSupport=%s/%s impact=%s/{%s,%s,%s} maxAuraHandles=%d "
                .. "palette=indigo+cyan+cold-white material=compact-focal-candidate liveAppearance=unverified.")
            :format(state.activation_id, Messiah.AURA_BODY_ASSET, Messiah.AURA_BODY_EFFECT,
                Messiah.AURA_WISP_ASSET, Messiah.AURA_HAND_EFFECT,
                Messiah.ORB_FX_ASSET, Messiah.ORB_FX_EFFECT,
                Messiah.ENERGY_FX_ASSET, Messiah.ENERGY_FX_EFFECT,
                Messiah.ALIEN_FX_ASSET, Messiah.ALIEN_BULLET_IMPACT_EFFECT,
                Messiah.ALIEN_IMPACT_EFFECT, Messiah.ALIEN_DISINTEGRATE_EFFECT,
                Messiah.MAX_AURA_HANDLES))
        Messiah.InitializeModelStreaming(now)
    end

    function Messiah.TickModelStreaming(now)
        local state = Messiah.State()
        local phase = state.model_state
        if phase ~= "REQUESTED" and phase ~= "LOADING" then return Messiah.ModelUsable() end
        now = tonumber(now) or now_ms()
        if now < state.model_next_poll_ms then return false end
        if state.model_poll_count >= Messiah.MODEL_MAX_POLLS
            or now >= state.model_deadline_ms then
            Messiah.SetModelState("UNAVAILABLE",
                ("timeout_ms=%d polls=%d")
                :format(now - state.model_requested_ms, state.model_poll_count))
            return false
        end

        state.model_poll_count = state.model_poll_count + 1
        state.model_next_poll_ms = now + Messiah.MODEL_POLL_INTERVAL_MS
        local _, s32 = Messiah.NormalizeHash(Messiah.ORB_MODEL)
        local loaded, raw, err = invoke_bool_detail(H.HAS_MODEL_LOADED, s32)
        if err then
            Messiah.LogOnce("native-bool:HAS_MODEL_LOADED:error",
                ("Messiah model native failed: name=HAS_MODEL_LOADED hash=%s model_u32=%s "
                    .. "model_s32=%s raw=%s error=%s backend=%s.")
                :format(Messiah.MODEL_NATIVE_NAMES.HAS_MODEL_LOADED,
                    tostring((Messiah.NormalizeHash(Messiah.ORB_MODEL))), tostring(s32),
                    Messiah.RawValue(raw), tostring(err), "Natives.InvokeBool"))
            Messiah.SetModelState("UNAVAILABLE", "HAS_MODEL_LOADED bridge failure")
            return false
        end
        if loaded then
            Messiah.LogOnce("native-bool:HAS_MODEL_LOADED:ready",
                ("Messiah model native ready: name=HAS_MODEL_LOADED hash=%s model_s32=%s "
                    .. "raw=%s polls=%d.")
                :format(Messiah.MODEL_NATIVE_NAMES.HAS_MODEL_LOADED, tostring(s32),
                    Messiah.RawValue(raw), state.model_poll_count))
            Messiah.SetModelState("READY", ("polls=%d"):format(state.model_poll_count))
            return true
        end
        Messiah.SetModelState("LOADING", ("poll=%d raw=%s")
            :format(state.model_poll_count, Messiah.RawValue(raw)))
        return false
    end

    -- Native BOOL bridges can expose either a Lua boolean or the integer ABI.
    -- Unknown results are never evidence of an offline session or acceptance.
    function Messiah.TransportBoolean(raw, err)
        if err ~= nil then return nil end
        if raw == true or raw == 1 then return true end
        if raw == false or raw == 0 then return false end
        return nil
    end

    -- Cache once per owned frame. These detached diagnostic fields contain no
    -- entity or arbitrary host object: fx_session_{epoch,frame,known,status,
    -- raw_type,raw,error}. A created emitter never proves observer delivery.
    function Messiah.FxOnline()
        local state = Messiah.State()
        local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame and state.action == action
        end
        if not current() then return nil end
        if state.fx_session_frame == frame and state.fx_session_epoch == epoch then return state.fx_online end
        -- A reentrant caller sees pending/unknown and cannot start a duplicate
        -- query or silently allocate an offline substitute.
        state.fx_session_frame, state.fx_session_epoch = frame, epoch
        state.fx_online, state.fx_session_known, state.fx_session_status = nil, false, "pending"
        state.fx_session_raw_type, state.fx_session_raw, state.fx_session_error = "nil", "pending", nil
        local _, raw, err = invoke_bool_detail(H.NETWORK_IS_SESSION_ACTIVE)
        if not current() then return nil end
        local online = Messiah.TransportBoolean(raw, err)
        local kind = type(raw)
        state.fx_session_raw_type = kind
        state.fx_session_raw = (kind == "boolean" or kind == "number") and tostring(raw)
            or (kind == "nil" and "nil" or ("<" .. kind .. ">"))
        state.fx_session_error = type(err) == "string" and err:sub(1, 160)
            or (err ~= nil and "invalid-error" or nil)
        state.fx_online, state.fx_session_known = online, online ~= nil
        state.fx_session_status = online == true and "online" or (online == false and "offline" or "unknown")
        return online
    end

    function Messiah.ClaimFxStart(burst)
        local state, now = Messiah.State(), now_ms()
        if not Messiah.EntityOwner() or state.ending then return false end
        if state.fx_start_frame ~= state.entity_frame then
            state.fx_start_frame, state.fx_starts_this_frame = state.entity_frame, 0
        end
        if (state.fx_starts_this_frame or 0) >= Messiah.MAX_FX_STARTS_PER_FRAME then return false end
        if burst then
            local elapsed = math.max(0, now - (state.fx_token_ms or now))
            state.fx_tokens = math.min(4, (state.fx_tokens or 4) + elapsed * 0.020)
            state.fx_token_ms = now
            if state.fx_tokens < 1 then return false end
            state.fx_tokens = state.fx_tokens - 1
        end
        state.fx_starts_this_frame = (state.fx_starts_this_frame or 0) + 1
        return true
    end

    function Messiah.RecordFxTransport(role, backend, accepted)
        local state = Messiah.State()
        state.fx_transport_attempts = (state.fx_transport_attempts or 0) + 1
        state.fx_transport_accepted = (state.fx_transport_accepted or 0) + (accepted and 1 or 0)
        if accepted == false then
            state.fx_transport_failed = (state.fx_transport_failed or 0) + 1
        elseif accepted == nil then
            state.fx_transport_uncertain = (state.fx_transport_uncertain or 0) + 1
        end
        local scope = backend:match("^START_NETWORKED_") and "networked"
            or (backend:match("^START_PARTICLE_") and "local" or "transport-support")
        Messiah.LogOnce("fx-transport:" .. tostring(role) .. ":" .. tostring(accepted),
            ("Messiah shared FX: revision=17.75 activation=%d role=%s backend=%s accepted=%s "
                .. "scope=%s session=%s sessionRawType=%s sessionRaw=%s "
                .. "localFallback=false observerAcceptance=unverified.")
            :format(state.activation_id, tostring(role), backend, accepted == nil and "unknown" or tostring(accepted),
                scope,
                tostring(state.fx_session_status or "unknown"), tostring(state.fx_session_raw_type or "nil"),
                tostring(state.fx_session_raw or "unread")))
        if accepted == false and not state.fx_transport_warned then
            state.fx_transport_warned = true
            Messiah.ReportFailure("shared effects",
                "GTA rejected " .. scope .. " effect creation; observer visibility is unverified")
        end
    end

    function Messiah.FxEntityReady(lease)
        if not lease or not Messiah.EntityOwner(lease) then return false end
        local state = Messiah.State()
        local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame and state.action == action
        end
        local online = Messiah.FxOnline()
        if online == nil or not current() then return false end
        if online == false then
            local valid = Messiah.ValidateEntityLease(lease, "offline-fx", "none")
            return current() and valid == true
        end
        local networked = Messiah.LeaseInvoke(lease, "bool", "NETWORK_GET_ENTITY_IS_NETWORKED",
            H.NETWORK_GET_ENTITY_IS_NETWORKED, lease.handle)
        if not current() then return false end
        if networked ~= true then
            Messiah.RecordFxTransport("entity-registration", "NETWORK_GET_ENTITY_IS_NETWORKED", false)
        end
        return networked == true
    end

    function Messiah.ForgetProvisionalLocalFx(state, record)
        for index = #state.temp_fx, 1, -1 do
            if state.temp_fx[index] == record then
                table.remove(state.temp_fx, index); return true
            end
        end
        return false
    end

    function Messiah.CancelProvisionalLocalFx(state, record, reason)
        -- A reentrant callback may already have drained the zero-handle
        -- placeholder. Keep the returned handle with its captured owner only.
        local owned = false
        for _, item in ipairs(state.temp_fx) do if item == record then owned = true end end
        if not owned then state.temp_fx[#state.temp_fx + 1] = record end
        record.pending_host_cleanup, record.local_fx_failure = true, tostring(reason)
        -- START has returned. The reservation is no longer in-flight; an
        -- existing owned gameplay/cleanup tick can drain it without replaying
        -- START or tint. A stale callback itself must issue no cleanup native.
        record.provisional_local_fx = false
        if State.messiah ~= state or state.gameplay_owner ~= true or state.disposed
            or state.active ~= true or state.ending or state.restoring or state.cleanup_failed
            or state.activation_epoch ~= record.owner_epoch
            or (record.start_frame ~= nil and (state.entity_frame ~= record.start_frame
                or state.action ~= record.start_action)) then
            log_info(("Messiah local FX pending cleanup: activation=%d role=%s handle=%s reason=%s "
                    .. "capturedOwner=true replacementOwnerUntouched=true liveCleanupRequired=true.")
                :format(state.activation_id, record.role, tostring(record.handle), tostring(reason)))
            return nil
        end
        local ok, accepted = pcall(Messiah.StopFx, record)
        if not ok or accepted ~= true then
            record.local_fx_cleanup_uncertain = true
            error("Messiah local FX cleanup uncertain; ownership retained and native retry forbidden", 0)
        end
        Messiah.ForgetProvisionalLocalFx(state, record)
        return nil
    end

    function Messiah.FinishLocalFxStart(state, epoch, lease, record, handle, creation_error, frame, action)
        record.handle = type(handle) == "number" and handle > 0 and handle <= 0x7FFFFFFF
            and handle % 1 == 0 and handle or 0
        record.created_handle = record.handle
        if creation_error == "lease-rejected" or creation_error == "cleanup-mutation-not-owned" then
            Messiah.ForgetProvisionalLocalFx(state, record)
            return nil
        end
        if creation_error ~= nil then
            local owned = false
            for _, item in ipairs(state.temp_fx) do if item == record then owned = true end end
            if not owned then state.temp_fx[#state.temp_fx + 1] = record end
            record.pending_host_cleanup, record.local_fx_cleanup_uncertain = true, true
            error("Messiah local FX creation outcome uncertain; ownership retained without retry", 0)
        end
        if record.handle == 0 then
            Messiah.ForgetProvisionalLocalFx(state, record); return nil
        end
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame and state.action == action
                and lease.state == "live" and lease.epoch == epoch and record.handle ~= 0
        end
        if not current() then return Messiah.CancelProvisionalLocalFx(state, record, "creation-context-cancelled") end
        -- The legacy provisional flag now reserves every in-flight loop. Only
        -- the local native needs a post-creation tint; network creation already
        -- received its documented RGBA arguments.
        if record.networked ~= true then
            record.tint_attempted = true
            local accepted, raw = invoke_void_detail(H.SET_PARTICLE_FX_LOOPED_COLOUR, record.handle,
                record.colour[1], record.colour[2], record.colour[3], false)
            if accepted ~= true or raw == false then
                return Messiah.CancelProvisionalLocalFx(state, record,
                    "local-tint-failed")
            end
            if not current() then return Messiah.CancelProvisionalLocalFx(state, record, "tint-context-cancelled") end
            record.tint_applied = true
        end
        record.provisional_local_fx = false
        Messiah.ForgetProvisionalLocalFx(state, record)
        return record
    end

    function Messiah.StartLoopedFxOnBone(ped, asset, effect, bone_id, scale, colour, role, ox, oy, oz)
        local state = Messiah.State()
        local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame and state.action == action
        end
        local online = Messiah.FxOnline()
        if online == nil or not current() then return nil end
        local lease = state.ped_lease
        if not current() or not lease or lease.handle ~= Messiah.NormalizeEntityHandle(ped)
            or not invoke_bool(H.HAS_NAMED_PTFX_ASSET_LOADED, asset)
            or not current() or not Messiah.FxEntityReady(lease) or not current() then
            return nil
        end
        local bone_index = Messiah.LeaseInvoke(lease, "int", "GET_PED_BONE_INDEX", H.GET_PED_BONE_INDEX, ped, bone_id)
        if not current() or type(bone_index) ~= "number" or bone_index < 0 then return nil end
        colour = type(colour) == "table" and colour or { 0.10, 0.45, 0.70 }
        colour = { colour[1], colour[2], colour[3] }
        ox, oy, oz = tonumber(ox) or 0.0, tonumber(oy) or 0.0, tonumber(oz) or 0.0
        if not current() or (not online and not H.SET_PARTICLE_FX_LOOPED_COLOUR)
            or #state.temp_fx >= Messiah.MAX_TEMP_FX_HANDLES or not Messiah.ClaimFxStart(false) then
            return nil
        end
        local name = online and "START_NETWORKED_PARTICLE_FX_LOOPED_ON_ENTITY_BONE"
            or "START_PARTICLE_FX_LOOPED_ON_ENTITY_BONE"
        invoke_void(H.USE_PARTICLE_FX_ASSET, asset)
        if not current() then return nil end
        local record = {
            handle = 0,
            asset = asset,
            effect = effect,
            base_scale = scale,
            colour = colour,
            role = tostring(role or "bone"),
            networked = online,
            bone = bone_id,
            offset = { x = ox, y = oy, z = oz },
            owner_epoch = epoch,
            start_frame = frame,
            start_action = action
        }
        local handle, _, creation_error
        record.provisional_local_fx, record.expires_ms = true, now_ms()
        state.temp_fx[#state.temp_fx + 1] = record
        if online then
            handle, _, creation_error = Messiah.LeaseInvoke(lease, "int", name, H[name],
                effect, ped, ox, oy, oz, 0.0, 0.0, 0.0, bone_index, scale, false, false, false,
                colour[1], colour[2], colour[3], 1.0)
        else
            handle, _, creation_error = Messiah.LeaseInvoke(lease, "int", name, H[name],
                effect, ped, ox, oy, oz, 0.0, 0.0, 0.0, bone_index, scale, false, false, false)
        end
        record = Messiah.FinishLocalFxStart(state, epoch, lease, record, handle, creation_error, frame, action)
        if not current() then return nil end
        local accepted = type(handle) == "number" and handle > 0 and handle <= 0x7FFFFFFF and handle % 1 == 0
            and record ~= nil
        Messiah.RecordFxTransport(role, name, accepted)
        if not accepted then return nil end
        record.handle = handle
        return record
    end

    function Messiah.StartLoopedFxOnEntity(entity, asset, effect, scale, colour, role, ox, oy, oz, supplied_lease, rx, ry,
                                           rz)
        local state = Messiah.State()
        local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame and state.action == action
        end
        local online = Messiah.FxOnline()
        if online == nil or not current() then return nil end
        entity = Messiah.NormalizeEntityHandle(entity)
        local lease = supplied_lease or (state.projectiles[entity] or {}).lease
            or (entity == state.ped and state.ped_lease)
        if not current() or not lease or lease.handle ~= entity
            or not invoke_bool(H.HAS_NAMED_PTFX_ASSET_LOADED, asset)
            or not current() or not Messiah.FxEntityReady(lease) or not current() then
            return nil
        end
        colour = type(colour) == "table" and colour or { 0.16, 0.08, 0.48 }
        colour = { colour[1], colour[2], colour[3] }
        if not current() or (not online and not H.SET_PARTICLE_FX_LOOPED_COLOUR)
            or #state.temp_fx >= Messiah.MAX_TEMP_FX_HANDLES or not Messiah.ClaimFxStart(false) then
            return nil
        end
        local name = online and "START_NETWORKED_PARTICLE_FX_LOOPED_ON_ENTITY" or "START_PARTICLE_FX_LOOPED_ON_ENTITY"
        invoke_void(H.USE_PARTICLE_FX_ASSET, asset)
        if not current() then return nil end
        local record = {
            handle = 0,
            asset = asset,
            effect = effect,
            base_scale = scale,
            colour = colour,
            role = tostring(role or "entity"),
            networked = online,
            owner_epoch = epoch,
            start_frame = frame,
            start_action = action
        }
        local handle, _, creation_error
        record.provisional_local_fx, record.expires_ms = true, now_ms()
        state.temp_fx[#state.temp_fx + 1] = record
        if online then
            handle, _, creation_error = Messiah.LeaseInvoke(lease, "int", name, H[name], effect, entity,
                tonumber(ox) or 0.0, tonumber(oy) or 0.0, tonumber(oz) or 0.0,
                tonumber(rx) or 0.0, tonumber(ry) or 0.0, tonumber(rz) or 0.0,
                scale, false, false, false, colour[1], colour[2], colour[3], 1.0)
        else
            handle, _, creation_error = Messiah.LeaseInvoke(lease, "int", name, H[name], effect, entity,
                tonumber(ox) or 0.0, tonumber(oy) or 0.0, tonumber(oz) or 0.0,
                tonumber(rx) or 0.0, tonumber(ry) or 0.0, tonumber(rz) or 0.0,
                scale, false, false, false)
        end
        record = Messiah.FinishLocalFxStart(state, epoch, lease, record, handle, creation_error, frame, action)
        if not current() then return nil end
        local accepted = type(handle) == "number" and handle > 0 and handle <= 0x7FFFFFFF and handle % 1 == 0
            and record ~= nil
        Messiah.RecordFxTransport(role, name, accepted)
        if not accepted then return nil end
        record.handle = handle
        return record
    end

    function Messiah.StartTimedFxAtCoord(asset, effect, x, y, z, scale, duration_ms, diagnostic_key)
        -- These are verified one-shot effects. Let GTA finish them; there is no
        -- loop handle to stop, and no local substitute for a failed network start.
        local state = Messiah.State()
        local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame and state.action == action
        end
        local online = Messiah.FxOnline()
        if online == nil or not current() then return false end
        local point = Messiah.VisualPoint({ x = x, y = y, z = z })
        if not point or not invoke_bool(H.HAS_NAMED_PTFX_ASSET_LOADED, asset)
            or not current() or not Messiah.ClaimFxStart(true) then
            return false
        end
        local name = online and "START_NETWORKED_PARTICLE_FX_NON_LOOPED_AT_COORD"
            or "START_PARTICLE_FX_NON_LOOPED_AT_COORD"
        invoke_void(H.USE_PARTICLE_FX_ASSET, asset)
        if not current() then return false end
        local _, raw, err = invoke_bool_detail(H[name], effect, x, y, z, 0.0, 0.0, 0.0,
            clamp(tonumber(scale) or 1.0, 0.1, 3.0), false, false, false, false)
        if not current() then return false, true end
        local accepted = Messiah.TransportBoolean(raw, err)
        Messiah.RecordFxTransport(diagnostic_key or effect, name, accepted)
        -- A one-shot may already exist after an uncertain host result. Return
        -- acceptance separately from consumption so callers never replay an
        -- uncertain event or count that event as confirmed creation.
        return accepted == true, accepted ~= false
    end

    function Messiah.TryAuraLayer(ped, descriptor, now)
        local state = Messiah.State()
        if state.aura_attempted[descriptor.role] then return end
        local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
        local online = Messiah.FxOnline()
        if online == nil or not Messiah.ActivationContextCurrent(state, epoch)
            or state.entity_frame ~= frame or state.action ~= action then
            return
        end
        if #state.aura >= Messiah.MAX_AURA_HANDLES then
            state.aura_attempted[descriptor.role] = true
            return
        end
        if not invoke_bool(H.HAS_NAMED_PTFX_ASSET_LOADED, descriptor.asset) then
            if now >= state.asset_deadline_ms then
                state.aura_attempted[descriptor.role] = true
                Messiah.LogOnce("aura-timeout:" .. descriptor.role,
                    ("Messiah aura layer unavailable: activation=%d role=%s asset=%s effect=%s timeout=true.")
                    :format(state.activation_id, descriptor.role, descriptor.asset, descriptor.effect))
            end
            return
        end
        if not Messiah.ActivationContextCurrent(state, epoch)
            or state.entity_frame ~= frame or state.action ~= action then
            return
        end
        if state.fx_start_frame == state.entity_frame
            and (state.fx_starts_this_frame or 0) >= Messiah.MAX_FX_STARTS_PER_FRAME then
            return
        end
        state.aura_attempted[descriptor.role] = true
        local record
        if descriptor.bone then
            record = Messiah.StartLoopedFxOnBone(ped, descriptor.asset, descriptor.effect,
                descriptor.bone, descriptor.scale, descriptor.colour, descriptor.role,
                descriptor.ox, descriptor.oy, descriptor.oz)
        else
            record = Messiah.StartLoopedFxOnEntity(ped, descriptor.asset, descriptor.effect,
                descriptor.scale, descriptor.colour, descriptor.role,
                descriptor.ox, descriptor.oy, descriptor.oz)
        end
        if record then
            state.aura[#state.aura + 1] = record
            log_info(("Messiah aura layer created: activation=%d role=%s handle=%s asset=%s effect=%s "
                    .. "bone=%s offset=(%.2f,%.2f,%.2f) scale=%.2f.")
                :format(state.activation_id, descriptor.role, tostring(record.handle),
                    descriptor.asset, descriptor.effect, tostring(descriptor.bone or "entity"),
                    tonumber(descriptor.ox) or 0.0, tonumber(descriptor.oy) or 0.0,
                    tonumber(descriptor.oz) or 0.0, tonumber(descriptor.scale) or 0.0))
        else
            Messiah.LogOnce("aura-create:" .. descriptor.role,
                ("Messiah aura layer creation failed: activation=%d role=%s asset=%s effect=%s.")
                :format(state.activation_id, descriptor.role, descriptor.asset, descriptor.effect))
        end
    end

    function Messiah.StartAura(ped, now)
        local state = Messiah.State()
        if state._aura_attempted_owner ~= state.aura_attempted then
            state._aura_attempted_owner = state.aura_attempted
            state.aura_start_cursor, state.aura_start_remaining = 1, nil
        end
        if state.aura_start_remaining == 0 then
            if #state.aura == 0 and now >= state.asset_deadline_ms
                and not state.aura_failure_notified then
                state.aura_failure_notified=true
                toast("Messiah effects unavailable: GTA rejected the bone particle effects.",4500)
            end
            return
        end
        local descriptors = Messiah.AURA_DESCRIPTORS or {
            {role="spine-void", asset="scr_rcbarry1", effect="scr_alien_charging",
                bone=24818, oz=0.06, scale=0.13, colour={0.22,0.05,0.63}},
            {role="pelvis-void", asset="scr_rcbarry1", effect="scr_alien_charging",
                bone=11816, scale=0.09, colour={0.12,0.04,0.45}},
            {role="left-hand-storm", asset="core", effect="ent_amb_elec_crackle",
                bone=18905, scale=0.28, colour={0.08,0.85,0.86}},
            {role="right-hand-storm", asset="core", effect="ent_amb_elec_crackle",
                bone=57005, scale=0.28, colour={0.08,0.85,0.86}},
            {role="left-ankle", asset="scr_rcbarry1", effect="scr_alien_charging",
                bone=14201, scale=0.055, colour={0.28,0.08,0.66}},
            {role="right-ankle", asset="scr_rcbarry1", effect="scr_alien_charging",
                bone=52301, scale=0.055, colour={0.28,0.08,0.66}}
        }
        Messiah.AURA_DESCRIPTORS = descriptors
        if state.aura_start_remaining == nil then
            state.aura_start_remaining = 0
            for _, descriptor in ipairs(descriptors) do
                if not state.aura_attempted[descriptor.role] then
                    state.aura_start_remaining = state.aura_start_remaining + 1
                end
            end
        end
        -- Three startup attempts per gameplay tick spread the initial FX/native
        -- burst; the rotating cursor also lets ready assets pass unloaded ones.
        local attempts, visited = 0, 0
        while attempts < 3 and visited < #descriptors and state.aura_start_remaining > 0 do
            local index = state.aura_start_cursor
            local descriptor = descriptors[index]
            state.aura_start_cursor = index % #descriptors + 1
            visited = visited + 1
            if not state.aura_attempted[descriptor.role] then
                attempts = attempts + 1
                Messiah.TryAuraLayer(ped, descriptor, now)
                if state.aura_attempted[descriptor.role] then
                    state.aura_start_remaining = state.aura_start_remaining - 1
                end
            end
        end
    end

    function Messiah.UpdateAura(now)
        -- Fixed network creation tint/scale is shared. Camera-dependent alpha
        -- and twenty-per-second scale edits produced a different local aura.
        -- The separately owned cast cue supplies the hand charge instead.
        return #Messiah.State().aura > 0
    end

    function Messiah.AddTempFx(record, expires_ms)
        local state = Messiah.State()
        if not record then return false end
        while #state.temp_fx >= Messiah.MAX_TEMP_FX_HANDLES do
            local victim
            for index, item in ipairs(state.temp_fx) do
                if item.provisional_local_fx ~= true then
                    victim = index; break
                end
            end
            -- An in-flight local START owns its reserved slot even while a
            -- reentrant callback adds another temporary accent.
            if not victim then
                Messiah.StopFx(record); return false
            end
            Messiah.StopFx(state.temp_fx[victim])
            table.remove(state.temp_fx, victim)
        end
        record.expires_ms = tonumber(expires_ms) or now_ms()
        state.temp_fx[#state.temp_fx + 1] = record
        return true
    end

    function Messiah.UpdateLanceAudio(now, action)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local function current() return Messiah.ActionContextCurrent(state, epoch, action, "LANCE") end
        if not current() or action.minimum_pulse
            or not action.channel_started_ms or now - action.channel_started_ms < 800
            or action.channel_audio_escalation_attempted then
            return false
        end
        -- One extra verified sustained layer after a real held channel matures.
        -- It shares the channel role, priority and stop/release ownership without
        -- replacing the spatial hum. A failed bank/start is attempted only once.
        action.channel_audio_escalation_attempted = true
        local accepted = Messiah.PlayFrontendSound("lance-loop", "cannon_charge_fire_loop",
            "dlc_xm_orbital_cannon_sounds", 600000, true,
            { action_serial = action.serial, epoch = epoch })
        if not current() then return false end
        action.channel_audio_escalation_started = accepted == true
        Messiah.LogOnce("lance-audio-escalation:" .. tostring(action.serial),
            ("Messiah Lance audio escalation: activation=%d action=%d heldMs=%d accepted=%s attempt=1; base hum retained.")
            :format(state.activation_id, action.serial, now - action.channel_started_ms, tostring(accepted == true)))
        return accepted == true
    end

    function Messiah.PlayChargeAudio(ability, target, duration_ms)
        local state = Messiah.State()
        if ability == "ORB" then
            return Messiah.PlayFrontendSound("orb-charge", "Blue_Target_Charge",
                "dlc_xm_silo_laser_hack_sounds", 240, false)
        elseif ability == "LANCE" then
            return Messiah.PlayFrontendSound("lance-charge", "Red_Target_Charge",
                "dlc_xm_silo_laser_hack_sounds", 200, false)
        elseif ability == "RUPTURE" then
            return Messiah.PlayFrontendSound("rupture-charge", "Explosion_Shake",
                "dlc_xm_avngr_sounds", duration_ms, false)
        elseif ability == "SHOCKWAVE" then
            return Messiah.PlayFrontendSound("shockwave-charge", "Blue_Target_Charge",
                "dlc_xm_silo_laser_hack_sounds", duration_ms, false)
        elseif ability == "SUPER" then
            return Messiah.PlayFrontendSound("judgment-charge", "cannon_charge_fire_loop",
                "dlc_xm_orbital_cannon_sounds", duration_ms, true)
        end
        return false
    end

    function Messiah.StartChargeCue(now, ped, ability)
        local state = Messiah.State()
        local right = state.cast_hand_right ~= false
        local bone = right and 57005 or 18905
        -- Barry's looped impact provides a compact charge cue at the casting hand.
        local scale = ability == "SUPER" and 0.24 or ability == "ORB" and 0.16
            or ability == "RUPTURE" and 0.16 or 0.14
        local record = Messiah.StartLoopedFxOnBone(ped, Messiah.ALIEN_FX_ASSET,
            Messiah.ALIEN_IMPACT_EFFECT, bone, scale, { 0.60, 0.88, 1.00 },
            "charge-" .. tostring(ability):lower())
        if record then
            record.owner_epoch = state.activation_epoch
            record.owner_action_serial = state.action and state.action.serial
            Messiah.AddTempFx(record, now + ((Messiah.ABILITIES[ability] or {}).windup or 200) + 80)
        end
        return record ~= nil
    end

    function Messiah.UpdateTempFx(now)
        local state = Messiah.State()
        for index = #state.temp_fx, 1, -1 do
            local record = state.temp_fx[index]
            local channel_owned = record.channel_action_serial ~= nil
                and state.action ~= nil
                and tonumber(record.channel_action_serial) == tonumber(state.action.serial)
                and state.action.ending ~= true
            if record.provisional_local_fx ~= true and
                ((record.owner_epoch ~= nil and record.owner_epoch ~= state.activation_epoch)
                    or (not channel_owned and now >= (tonumber(record.expires_ms) or 0))) then
                Messiah.StopFx(record)
                table.remove(state.temp_fx, index)
            end
        end
    end

    function Messiah.CleanupActionTempFx(ability)
        local state = Messiah.State()
        local role = "charge-" .. tostring(ability or ""):lower()
        local stopped = 0
        for index = #state.temp_fx, 1, -1 do
            local record = state.temp_fx[index]
            if tostring(record.role or "") == role then
                Messiah.StopFx(record)
                table.remove(state.temp_fx, index)
                stopped = stopped + 1
            end
        end
        return stopped
    end

    function Messiah.OwnActionTempFx(ability, action_serial)
        local state = Messiah.State()
        local role = "charge-" .. tostring(ability or ""):lower()
        local extended = 0
        for _, record in ipairs(state.temp_fx) do
            if tostring(record.role or "") == role then
                record.channel_action_serial = tonumber(action_serial)
                extended = extended + 1
            end
        end
        return extended
    end

    function Messiah.VisualCount()
        local state = Messiah.State()
        local visuals = state.visuals
        return #(visuals.beams or {}) + #(visuals.markers or {}) + #(visuals.lights or {})
            + (state.channel_beam and 1 or 0)
    end

    function Messiah.AdmitPresentation(priority, count)
        local state = Messiah.State()
        if not Messiah.EntityOwner() or state.ending or state.restoring or state.disposed then return false end
        count = tonumber(count) or 1
        if not Messiah.VisualFinite(priority) or not Messiah.VisualFinite(count)
            or count < 1 or count % 1 ~= 0 or count > Messiah.MAX_VISUALS then
            return false
        end
        local total = Messiah.VisualCount() + count
        if priority < 75 and total > Messiah.MAX_VISUALS - 8 then return false end
        local required = math.max(0, total - Messiah.MAX_VISUALS)
        if required == 0 then return true end
        local candidates = {}
        for _, records in ipairs({ state.visuals.markers, state.visuals.lights }) do
            for _, record in ipairs(records) do
                local rank = tonumber(record.presentation_priority) or 0
                if rank < priority and (priority >= 100 or rank < 75) then
                    candidates[#candidates + 1] = { record = record, rank = rank, order = #candidates + 1 }
                end
            end
        end
        -- Reserve a complete group before removing anything. E cannot take one
        -- or two slots and silently publish a partial three-front release.
        if #candidates < required then return false end
        table.sort(candidates, function(a, b)
            if a.rank == b.rank then return a.order < b.order end
            return a.rank < b.rank
        end)
        local selected = {}
        for index = 1, required do selected[candidates[index].record] = true end
        for _, records in ipairs({ state.visuals.markers, state.visuals.lights }) do
            for index = #records, 1, -1 do
                if selected[records[index]] then table.remove(records, index) end
            end
        end
        return Messiah.VisualCount() + count <= Messiah.MAX_VISUALS
    end

    function Messiah.AddBeam(now, from, target, duration_ms, style, layers)
        local state = Messiah.State()
        from, target = Messiah.VisualPoint(from), Messiah.VisualPoint(target)
        local priority = style == 'judgment' and 90 or style == 'judgment-inward' and 20 or 10
        if not from or not target or not Messiah.AdmitPresentation(priority) then return false end
        state.visuals.beams[#state.visuals.beams + 1] = {
            started_ms = now,
            expires_ms = now + (tonumber(duration_ms) or 110),
            from = from,
            target = target,
            style = tostring(style or 'standard'),
            layers = math.max(1, math.min(Messiah.MAX_BEAM_LAYERS, tonumber(layers) or 3)),
            owner_epoch = state.activation_epoch,
            owner_action_serial = state.action_serial,
            presentation_priority = priority,
            local_only = style == 'judgment-inward',
        }
        return true
    end

    function Messiah.AddMarker(now, position, radius_from, radius_to, duration_ms, colour, alpha)
        local state = Messiah.State()
        if Messiah.VisualCount() >= Messiah.MAX_VISUALS then return false end
        state.visuals.markers[#state.visuals.markers + 1] = {
            started_ms = now,
            expires_ms = now + (tonumber(duration_ms) or 400),
            position = { x = position.x, y = position.y, z = position.z },
            radius_from = tonumber(radius_from) or 1.0,
            radius_to = tonumber(radius_to) or tonumber(radius_from) or 1.0,
            colour = colour or { 92, 48, 210 },
            alpha = tonumber(alpha) or 185,
            kind = "ground-ring",
        }
        return true
    end

    function Messiah.AddPressureWave(now, position, profile_name, options)
        local state = Messiah.State()
        position = Messiah.VisualPoint(position)
        options = type(options) == 'table' and options or {}
        local final = profile_name == 'SUPER_IMPACT' and options.final_core == true
        if not position or not Messiah.VisualFinite(now) or not Messiah.EntityOwner()
            or state.ending or state.restoring or state.disposed or options.no_visual_records
            or options.host_retry or (options.epoch and options.epoch ~= state.activation_epoch)
            or (profile_name ~= 'ORB_IMPACT' and not final) then
            return false
        end
        local serial = tonumber(options.action_serial) or (state.action and state.action.serial) or state.action_serial
        if not Messiah.VisualFinite(serial) or serial <= 0 or serial % 1 ~= 0 then return false end
        for _, record in ipairs(state.visuals.markers) do
            if record.kind == 'pressure-wave' and record.owner_epoch == state.activation_epoch
                and record.owner_action_serial == serial and record.wave_profile == profile_name
                and now < record.expires_ms then
                return false
            end
        end
        -- Orb spam owns at most two compact contact composites. Never evict an
        -- E front, Q fissure, or Judgment final to admit another Orb accent.
        if not final then
            local count = 0
            for index = #state.visuals.markers, 1, -1 do
                local record = state.visuals.markers[index]
                if record.wave_profile == 'ORB_IMPACT' then
                    count = count + 1; if count >= 2 then table.remove(state.visuals.markers, index) end
                end
            end
        end
        if not Messiah.AdmitPresentation(final and 100 or 35) then return false end
        state.visuals.markers[#state.visuals.markers + 1] = {
            kind = 'pressure-wave',
            local_only = true,
            position = position,
            started_ms = now,
            expires_ms = now + (final and 780 or 500),
            radius_from = final and 1.4 or 0.45,
            radius_to = final and 5.4 or 2.2,
            alpha = final and 255 or 240,
            wave_profile = profile_name,
            owner_epoch = state.activation_epoch,
            owner_action_serial = serial,
            owner_ability = final and 'SUPER' or 'ORB',
            presentation_priority = final and 100 or 35
        }
        return true
    end

    function Messiah.AddCracks(now, position, radius, duration_ms, colour, branches)
        local state = Messiah.State()
        position = Messiah.VisualPoint(position)
        if not position or not Messiah.AdmitPresentation(80) then return false end
        local record = {
            started_ms = now,
            expires_ms = now + (tonumber(duration_ms) or 1000),
            position = position,
            radius_from = 0.18,
            radius_to = tonumber(radius) or 4.8,
            colour = colour or { 116, 70, 255 },
            alpha = 238,
            kind = 'ground-cracks',
            local_only = true,
            presentation_priority = 80,
            owner_epoch = state.activation_epoch,
            owner_action_serial = state.action_serial,
            owner_ability = 'RUPTURE',
            branches = math.max(4, math.min(10, math.floor(tonumber(branches) or 8)))
        }
        state.visuals.markers[#state.visuals.markers + 1] = record
        return record
    end

    function Messiah.AddLight(now, position, range, intensity, duration_ms, colour)
        local state = Messiah.State()
        position = Messiah.VisualPoint(position)
        if not position or not Messiah.AdmitPresentation(20) then return false end
        state.visuals.lights[#state.visuals.lights + 1] = {
            started_ms = now,
            expires_ms = now + (tonumber(duration_ms) or 180),
            position = position,
            range = tonumber(range) or 8,
            intensity = tonumber(intensity) or 3,
            colour = colour or { 104, 80, 255 },
            local_only = true,
            presentation_priority = 20,
            owner_epoch = state.activation_epoch,
            owner_action_serial = state.action_serial
        }
        return true
    end

    function Messiah.BeamBasis(from, target)
        if type(from) ~= "table" or type(target) ~= "table" then return nil end
        local dx, dy, dz = target.x - from.x, target.y - from.y, target.z - from.z
        local length = math.sqrt(dx * dx + dy * dy + dz * dz)
        if length < 0.001 then return nil end
        dx, dy, dz = dx / length, dy / length, dz / length
        local flat = math.sqrt(dx * dx + dy * dy)
        local rx, ry, rz = 1.0, 0.0, 0.0
        if flat >= 0.001 then rx, ry = dy / flat, -dx / flat end
        local ux, uy, uz = -dz * ry, dz * rx, dx * ry - dy * rx
        local up_length = math.sqrt(ux * ux + uy * uy + uz * uz)
        if up_length >= 0.001 then
            ux, uy, uz = ux / up_length, uy / up_length, uz / up_length
        end
        return {
            dx = dx,
            dy = dy,
            dz = dz,
            length = length,
            rx = rx,
            ry = ry,
            rz = rz,
            ux = ux,
            uy = uy,
            uz = uz,
        }
    end

    -- A bounded wire-volume renderer replaces the former crossed polygon slabs.
    -- One cold core plus at most four longitudinal strands and a few circular
    -- cross-sections remain visible from any camera angle without opaque faces.










    function Messiah.VisualFinite(value)
        return type(value) == "number" and value == value
            and value > -math.huge and value < math.huge
    end

    function Messiah.VisualPoint(point)
        if type(point) ~= "table" then return nil end
        if not Messiah.VisualFinite(point.x) or not Messiah.VisualFinite(point.y)
            or not Messiah.VisualFinite(point.z) or math.abs(point.x) > 100000.0
            or math.abs(point.y) > 100000.0 or math.abs(point.z) > 100000.0 then
            return nil
        end
        return { x = point.x, y = point.y, z = point.z }
    end

    function Messiah.ClearVisualSnapshot()
        local state = type(State.messiah) == "table" and State.messiah or nil
        if not state then return end
        state.visual_snapshot, state.visual_build = nil, nil
        state.visual_generation = (tonumber(state.visual_generation) or 0) + 1
    end

    function Messiah.ClearLanceVisuals(action_serial)
        -- Release/cancel removes this action's contact mini-beams as well as
        -- its channel. Independent Orb/Rupture/Judgment records retain ownership.
        local state = type(State.messiah) == "table" and State.messiah or nil
        if not state or type(state.visuals) ~= "table" then return end
        for _, name in ipairs({ "beams", "markers", "lights" }) do
            local records = state.visuals[name] or {}
            for index = #records, 1, -1 do
                local record = records[index]
                if record.owner_ability == "LANCE" and record.owner_action_serial == action_serial
                    and record.owner_epoch == state.activation_epoch then
                    table.remove(records, index)
                end
            end
        end
    end

    function Messiah.RecordVisualCameraCheck(now, check, omitted)
        local state = State.messiah
        if type(state) ~= "table" then return end
        local stats = state.visual_camera_diagnostics
        if not stats or stats.epoch ~= state.activation_epoch then
            stats = {
                epoch = state.activation_epoch,
                checks = 0,
                failures = 0,
                recoveries = 0,
                omitted_frames = 0,
                consecutive_omitted = 0,
                next_log_ms = 0,
                status = 'uninitialized'
            }
            state.visual_camera_diagnostics = stats
        end
        if check and stats.last_check ~= check then
            stats.last_check = check; stats.checks = stats.checks + 1
            if check.ok then
                if stats.status == 'suppressed' then
                    stats.recoveries = stats.recoveries + 1; stats.dirty = true
                end
                stats.status = 'ready'; stats.last_ok_ms = now
            else
                stats.failures = stats.failures + 1; stats.status = 'suppressed'; stats.dirty = true
                stats.last_failure_ms = now; stats.last_failure = check
            end
        end
        if omitted then
            stats.omitted_frames = stats.omitted_frames + 1
            stats.consecutive_omitted = stats.consecutive_omitted + 1
        else
            stats.consecutive_omitted = 0
        end
        if stats.dirty and now >= stats.next_log_ms then
            stats.next_log_ms = now + 1000; stats.dirty = false
            local failed = check or {}
            log_info(("Messiah visual camera: epoch=%d status=%s reason=%s checks=%d failures=%d "
                    .. "recoveries=%d omittedRenderSamples=%d residualX=%s residualY=%s failedProbe=%s "
                    .. "fov=%s aspect=%s near=%s retryMs=%s lastFailure=%s phase=render projectionAcceptedOnly=true.")
                :format(state.activation_epoch, stats.status, tostring(failed.reason or 'none'),
                    stats.checks, stats.failures, stats.recoveries, stats.omitted_frames,
                    tostring(failed.residual_x), tostring(failed.residual_y), tostring(failed.failed_probe),
                    tostring(failed.fov), tostring(failed.aspect), tostring(failed.near_clip),
                    tostring(math.max(0, (check and check.retry_ms or now) - now)),
                    tostring(stats.last_failure and stats.last_failure.reason or 'none')))
        end
    end

    function Messiah.ValidatedVisualCamera(now, render_phase, generation)
        local state = render_phase and State.messiah or Messiah.State()
        if type(state) ~= "table" then return nil end
        local epoch, frame = state.activation_epoch, state.entity_frame
        local serial, action, phase, beam = state.action_serial, state.action, state.phase, state.channel_beam
        local function current()
            if render_phase then
                return State.messiah == state and state.active and not state.restoring
                    and not state.ending and not state.disposed and state.activation_epoch == epoch
                    and state.entity_frame == frame and state.visual_generation == generation
                    and state.action_serial == serial and state.action == action
                    and state.phase == phase and state.channel_beam == beam
            end
            return Messiah.ActivationContextCurrent(state, epoch) and state.entity_frame == frame
        end
        if not current() or not Messiah.VisualFinite(now) then return nil end
        if not render_phase and state.visual_camera_sampled_epoch == epoch and state.visual_camera_sampled_frame == frame
            and state.visual_camera_sampled_ms == now then
            return state.visual_camera_frame
        end
        if not render_phase then
            state.visual_camera_sampled_epoch, state.visual_camera_sampled_frame, state.visual_camera_sampled_ms = epoch,
                frame, now
            state.visual_camera_frame = nil
        end
        -- Gameplay publishes detached world geometry. Only the render adapter
        -- compares WorldToScreen against a camera sampled in that same phase.
        local cx, cy, cz = vector_components(invoke_vec3(H.GET_FINAL_RENDERED_CAM_COORD))
        if not current() then return nil end
        local camera = Messiah.VisualPoint({ x = cx, y = cy, z = cz })
        local rx, ry, rz = vector_components(invoke_vec3(H.GET_FINAL_RENDERED_CAM_ROT, 2))
        if not current() then return nil end
        local rotation = Messiah.VisualPoint({ x = rx, y = ry, z = rz })
        local fov = invoke_float_detail(H.GET_FINAL_RENDERED_CAM_FOV)
        if not current() then return nil end
        local aspect = invoke_float_detail(H.GET_ASPECT_RATIO, false)
        if not current() then return nil end
        local near_clip = invoke_float_detail(H.GET_FINAL_RENDERED_CAM_NEAR_CLIP)
        if not current() then return nil end
        if not camera or not rotation or not Messiah.VisualFinite(fov) or fov < 5 or fov > 150
            or not Messiah.VisualFinite(aspect) or aspect < 0.5 or aspect > 4.0
            or not Messiah.VisualFinite(near_clip) or near_clip <= 0 or near_clip > 10 then
            local failed = {
                epoch = epoch,
                ok = false,
                reason = 'invalid-camera-sample',
                checked_ms = now,
                retry_ms = now + 100,
                fov = fov,
                aspect = aspect,
                near_clip = near_clip,
                probes = {}
            }
            if render_phase then
                state.visual_camera_check = failed
                Messiah.RecordVisualCameraCheck(now, failed, true)
            end
            if not render_phase and current() and state.channel_beam then
                Messiah.RecordLanceVisualFrame(now, state.channel_beam, 'camera-suppressed',
                    { reason = failed.reason, core_lines = 0 })
            end
            return nil
        end
        -- Rotation order 2 is ZXY. GTA's forward axis is +Y and up is +Z.
        local sx, cxr = math.sin(math.rad(rx)), math.cos(math.rad(rx))
        local sy, cyr = math.sin(math.rad(ry)), math.cos(math.rad(ry))
        local sz, czr = math.sin(math.rad(rz)), math.cos(math.rad(rz))
        local direction = { x = -sz * cxr, y = czr * cxr, z = sx }
        local right = { x = czr * cyr - sz * sx * sy, y = sz * cyr + czr * sx * sy, z = -cxr * sy }
        local up = { x = czr * sy + sz * sx * cyr, y = sz * sy - czr * sx * cyr, z = cxr * cyr }
        local scale_y = 1.0 / math.tan(math.rad(fov) * 0.5)
        local scale_x = scale_y / aspect
        local calls = 0
        -- Revalidate each actual draw. A previous render's transient mismatch
        -- cannot suppress 100 ms of newly coherent render-camera samples.
        local check = { ok = true, reason = 'world-geometry-published', retry_ms = now }
        if render_phase then
            check = {
                epoch = epoch,
                fov = fov,
                aspect = aspect,
                near_clip = near_clip,
                checked_ms = now,
                ok = gta and type(gta.WorldToScreen) == 'function',
                retry_ms = now,
                probes = {},
                residual_x = 0,
                residual_y = 0,
                reason = 'host-unavailable'
            }
            local probes = { { 0, 0 }, { 0.20, 0.13 }, { -0.16, -0.18 } }
            local host_available = check.ok
            for index, probe in ipairs(probes) do
                if not host_available then break end
                local depth = math.max(10, near_clip * 2)
                local horizontal, vertical = probe[1] * depth / scale_x,
                    probe[2] * depth / scale_y
                local ok, x, y = pcall(gta.WorldToScreen,
                    camera.x + direction.x * depth + right.x * horizontal + up.x * vertical,
                    camera.y + direction.y * depth + right.y * horizontal + up.y * vertical,
                    camera.z + direction.z * depth + right.z * horizontal + up.z * vertical)
                if not current() then return nil end
                calls = calls + 1
                local valid = ok and Messiah.VisualFinite(x) and Messiah.VisualFinite(y)
                local expected_x, expected_y = 0.5 + probe[1] * 0.5, 0.5 - probe[2] * 0.5
                local dx, dy = valid and x - expected_x or nil, valid and y - expected_y or nil
                check.probes[index] = {
                    expected_x = expected_x,
                    expected_y = expected_y,
                    actual_x = valid and x or nil,
                    actual_y = valid and y or nil,
                    dx = dx,
                    dy = dy,
                    status = not ok and 'host-error' or not valid and 'non-finite' or 'sampled'
                }
                if valid then
                    check.residual_x = math.max(check.residual_x, math.abs(dx))
                    check.residual_y = math.max(check.residual_y, math.abs(dy))
                end
                if not valid or math.abs(dx) > 0.015 or math.abs(dy) > 0.015 then
                    check.ok = false
                    if not check.failed_probe then
                        check.failed_probe = index
                        check.reason = not ok and 'host-error' or not valid and 'non-finite' or 'calibration-residual'
                    end
                end
            end
            if check.ok then check.reason = 'same-render-phase-calibrated' end
            state.visual_camera_check = check
        end
        if render_phase then Messiah.RecordVisualCameraCheck(now, check, not check.ok) end
        if not current() then return nil end
        if not check.ok then
            return nil
        end
        local result = {
            epoch = epoch,
            frame = frame,
            now_ms = now,
            camera = camera,
            rotation = rotation,
            direction = direction,
            right = right,
            up = up,
            scale_x = scale_x,
            scale_y = scale_y,
            near_clip = math.max(0.10, near_clip),
            fov = fov,
            aspect = aspect,
            calibration_calls = calls
        }
        if not render_phase then state.visual_camera_frame = result end
        return result
    end

    function Messiah.ProjectValidatedCameraPoint(point, camera)
        point = Messiah.VisualPoint(point)
        if not point or type(camera) ~= 'table' then return nil end
        local p, d, r, u = Messiah.VisualPoint(camera.camera), Messiah.VisualPoint(camera.direction),
            Messiah.VisualPoint(camera.right), Messiah.VisualPoint(camera.up)
        if not p or not d or not r or not u or not Messiah.VisualFinite(camera.scale_x)
            or not Messiah.VisualFinite(camera.scale_y) or not Messiah.VisualFinite(camera.near_clip)
            or camera.scale_x <= 0 or camera.scale_y <= 0 or camera.near_clip <= 0 then
            return nil
        end
        local dx, dy, dz = point.x - p.x, point.y - p.y, point.z - p.z
        local z = dx * d.x + dy * d.y + dz * d.z
        local x = (dx * r.x + dy * r.y + dz * r.z) * camera.scale_x
        local y = (dx * u.x + dy * u.y + dz * u.z) * camera.scale_y
        if not Messiah.VisualFinite(z) or not Messiah.VisualFinite(x) or not Messiah.VisualFinite(y)
            or z < camera.near_clip or math.abs(x) > z or math.abs(y) > z then
            return nil
        end
        return { x = 0.5 + x / (2 * z), y = 0.5 - y / (2 * z) }
    end

    function Messiah.BeginVisualSnapshot(now)
        local state = Messiah.State()
        state.visual_snapshot, state.visual_build = nil, nil
        local camera = Messiah.ValidatedVisualCamera(now)
        if not camera then return nil end
        state.visual_generation = (tonumber(state.visual_generation) or 0) + 1
        local snapshot = {
            active = true,
            epoch = state.activation_epoch,
            action_serial = state.action_serial,
            generation = state.visual_generation,
            now_ms = now,
            world_geometry = true,
            debug = behavior_debug_enabled() == true,
            lines = {},
            discs = {}
        }
        state.visual_build = {
            snapshot = snapshot,
            camera = camera.camera,
            direction = camera.direction,
            right = camera.right,
            up = camera.up,
            scale_x = camera.scale_x,
            scale_y = camera.scale_y,
            near_clip = camera.near_clip,
            projections = 0,
            accepted = 0,
            rejected = 0,
            calibration_calls = camera.calibration_calls
        }
        return state.visual_build
    end

    function Messiah.VisualCameraPoint(point)
        local build = State.messiah and State.messiah.visual_build
        if not build or build.projections >= 192 then return nil end
        build.projections = build.projections + 1
        point = Messiah.VisualPoint(point)
        if not point then
            build.rejected = build.rejected + 1
            return nil
        end
        local dx, dy, dz = point.x - build.camera.x, point.y - build.camera.y, point.z - build.camera.z
        return {
            x = (dx * build.right.x + dy * build.right.y + dz * build.right.z) * build.scale_x,
            y = (dx * build.up.x + dy * build.up.y + dz * build.up.z) * build.scale_y,
            z = dx * build.direction.x + dy * build.direction.y + dz * build.direction.z
        }
    end

    function Messiah.ProjectVisualPoint(point)
        local build = State.messiah and State.messiah.visual_build
        local camera_point = Messiah.VisualCameraPoint(point)
        if not camera_point then return nil end
        if camera_point.z < build.near_clip or math.abs(camera_point.x) > camera_point.z * 15
            or math.abs(camera_point.y) > camera_point.z * 15 then
            build.rejected = build.rejected + 1
            return nil
        end
        build.accepted = build.accepted + 1
        return {
            x = 0.5 + camera_point.x / (camera_point.z * 2),
            y = 0.5 - camera_point.y / (camera_point.z * 2),
            wx = point.x,
            wy = point.y,
            wz = point.z
        }
    end

    function Messiah.ProjectClippedSegment(a, b)
        local build = State.messiah and State.messiah.visual_build
        if not build then return nil end
        local world_a, world_b = Messiah.VisualPoint(a), Messiah.VisualPoint(b)
        if not world_a or not world_b then return nil end
        a, b = Messiah.VisualCameraPoint(a), Messiah.VisualCameraPoint(b)
        if not a or not b then return nil end
        -- Clip the one straight segment in camera space BEFORE division. No
        -- failed/off-screen sample can bend it or connect through the camera.
        local low, high = 0, 1
        local function clip(first, last)
            if first < 0 and last < 0 then return false end
            if first < 0 then
                low = math.max(low, first / (first - last))
            elseif last < 0 then
                high = math.min(high, first / (first - last))
            end
            return low <= high
        end
        if not clip(a.z - build.near_clip, b.z - build.near_clip)
            or not clip(a.z + a.x, b.z + b.x) or not clip(a.z - a.x, b.z - b.x)
            or not clip(a.z + a.y, b.z + b.y) or not clip(a.z - a.y, b.z - b.y) then
            build.rejected = build.rejected + 2
            return nil
        end
        local dx, dy, dz = b.x - a.x, b.y - a.y, b.z - a.z
        local za, zb = a.z + dz * low, a.z + dz * high
        build.accepted = build.accepted + 2
        return {
                x = clamp(0.5 + (a.x + dx * low) / (za * 2), 0, 1),
                y = clamp(0.5 - (a.y + dy * low) / (za * 2), 0, 1),
                wx = world_a.x,
                wy = world_a.y,
                wz = world_a.z
            },
            {
                x = clamp(0.5 + (a.x + dx * high) / (zb * 2), 0, 1),
                y = clamp(0.5 - (a.y + dy * high) / (zb * 2), 0, 1),
                wx = world_b.x,
                wy = world_b.y,
                wz = world_b.z
            }
    end

    function Messiah.ClipVisualLine(a, b)
        if type(a) ~= "table" or type(b) ~= "table" then return nil end
        if not Messiah.VisualFinite(a.x) or not Messiah.VisualFinite(a.y)
            or not Messiah.VisualFinite(b.x) or not Messiah.VisualFinite(b.y)
            or math.abs(a.x) > 8 or math.abs(a.y) > 8 or math.abs(b.x) > 8 or math.abs(b.y) > 8 then
            return nil
        end
        -- Production segments already passed camera-space clipping. Avoid
        -- allocating three temporary arrays again for each colour layer.
        if a.x >= 0 and a.x <= 1 and a.y >= 0 and a.y <= 1
            and b.x >= 0 and b.x <= 1 and b.y >= 0 and b.y <= 1 then
            return a.x, a.y, b.x, b.y
        end
        local dx, dy, low, high = b.x - a.x, b.y - a.y, 0.0, 1.0
        local ps, qs = { -dx, dx, -dy, dy }, { a.x, 1.0 - a.x, a.y, 1.0 - a.y }
        for index = 1, 4 do
            local p, q = ps[index], qs[index]
            if math.abs(p) < 0.00000001 then
                if q < 0 then return nil end
            else
                local t = q / p
                if p < 0 then low = math.max(low, t) else high = math.min(high, t) end
                if low > high then return nil end
            end
        end
        return clamp(a.x + dx * low, 0, 1), clamp(a.y + dy * low, 0, 1),
            clamp(a.x + dx * high, 0, 1), clamp(a.y + dy * high, 0, 1)
    end

    function Messiah.AddProjectedLine(a, b, colour, thickness, alpha)
        local build = State.messiah and State.messiah.visual_build
        if not build or #build.snapshot.lines >= 128 then return false end
        local x1, y1, x2, y2 = Messiah.ClipVisualLine(a, b)
        if not x1 or not Messiah.VisualFinite(thickness) or not Messiah.VisualFinite(alpha) then return false end
        local c = type(colour) == "table" and colour or { 88, 218, 255 }
        for index = 1, 3 do if not Messiah.VisualFinite(c[index]) then return false end end
        build.snapshot.lines[#build.snapshot.lines + 1] = {
            x1 = x1,
            y1 = y1,
            x2 = x2,
            y2 = y2,
            thickness = clamp(thickness, 0.5, 96),
            r = clamp(c[1], 0, 255),
            g = clamp(c[2], 0, 255),
            b = clamp(c[3], 0, 255),
            a = math.floor(clamp(alpha, 0, 255)),
            role = build.role,
            wx1 = a.wx,
            wy1 = a.wy,
            wz1 = a.wz,
            wx2 = b.wx,
            wy2 = b.wy,
            wz2 = b.wz,
            max_span = build.max_span,
        }
        return true
    end

    function Messiah.ProjectEnergySegment(a, b, width, alpha, sampled, fade_tail)
        if not Messiah.VisualFinite(width) or not Messiah.VisualFinite(alpha) then return false end
        local first, last = Messiah.ProjectClippedSegment(a, b)
        if not first then return false end
        -- Each comet segment uses four translucent collinear colour layers.
        -- The active Lance/Judgment body instead uses ProjectVolumetricBeam.
        local previous, steps = first, fade_tail and 3 or 1
        for index = 1, steps do
            local t = index / steps
            local current = steps == 1 and last or {
                x = first.x + (last.x - first.x) * t,
                y = first.y + (last.y - first.y) * t,
                wx = first.wx + (last.wx - first.wx) * t,
                wy = first.wy + (last.wy - first.wy) * t,
                wz = first.wz + (last.wz - first.wz) * t
            }
            local strength = alpha * (fade_tail and (0.12 + 0.88 * t) or 1)
            Messiah.AddProjectedLine(previous, current, { 112, 52, 248 }, width * 1.5, strength * 0.10)
            Messiah.AddProjectedLine(previous, current, { 48, 160, 255 }, width * 0.85, strength * 0.28)
            Messiah.AddProjectedLine(previous, current, { 90, 228, 255 }, width * 0.42, strength * 0.72)
            Messiah.AddProjectedLine(previous, current, { 246, 254, 255 }, width * 0.18, strength)
            previous = current
        end
        return true
    end

    function Messiah.ProjectBloom(point, radius, alpha, ring)
        local build = State.messiah and State.messiah.visual_build
        if not build or #build.snapshot.discs + 4 > 48 then return false end
        local projected = Messiah.ProjectVisualPoint(point)
        if not projected or projected.x < 0 or projected.x > 1 or projected.y < 0 or projected.y > 1
            or not Messiah.VisualFinite(radius) or not Messiah.VisualFinite(alpha) then
            return false
        end
        -- Soft filled falloff replaces the old targeting-like endpoint rings.
        local specs = { { 1.0, 108, 62, 248, 0.06 }, { 0.73, 68, 176, 255, 0.16 },
            { 0.44, 100, 226, 255, 0.38 }, { 0.17, 246, 254, 255, 0.96 } }
        for index, spec in ipairs(specs) do
            build.snapshot.discs[#build.snapshot.discs + 1] = {
                x = projected.x,
                y = projected.y,
                wx = point.x,
                wy = point.y,
                wz = point.z,
                radius = clamp(radius * spec[1], 1.0, 64.0),
                r = spec[2],
                g = spec[3],
                b = spec[4],
                a = math.floor(clamp(alpha * spec[5], 0, 255)),
                filled = true,
                thickness = 2.0,
                role = build.role
            }
        end
        return true
    end

    function Messiah.VisualBeamStart(from, target, style)
        from, target = Messiah.VisualPoint(from), Messiah.VisualPoint(target)
        local basis = from and target and Messiah.BeamBasis(from, target)
        if not basis then return from end
        if style ~= 'channel' then return from end
        local state = Messiah.State()
        local owner = state.visual_owner_position
        local distance = math.min(0.22, basis.length * 0.20)
        if owner and owner.epoch == state.activation_epoch and owner.frame == state.entity_frame then
            local dx, dy, dz = from.x - owner.x, from.y - owner.y, from.z - (owner.z + 0.35)
            local along = dx * basis.dx + dy * basis.dy + dz * basis.dz
            local discriminant = along * along - (dx * dx + dy * dy + dz * dz - 0.95 * 0.95)
            if discriminant >= 0 then
                distance = math.max(distance, -along + math.sqrt(discriminant) + 0.12)
                if distance >= basis.length then return nil end
            end
        end
        distance = clamp(distance, 0, math.max(0, basis.length - 0.08))
        return { x = from.x + basis.dx * distance, y = from.y + basis.dy * distance, z = from.z + basis.dz * distance }
    end

    function Messiah.ProjectBoundedStroke(a, b, width, alpha, colour, span)
        local build = State.messiah and State.messiah.visual_build
        a, b = Messiah.VisualPoint(a), Messiah.VisualPoint(b)
        if not a or not b or not Messiah.VisualFinite(width) or not Messiah.VisualFinite(alpha) then return false end
        if not build or build.projections + 2 > 192 or #build.snapshot.lines + 2 > 128 then return false end
        -- Never clip a near-camera arc into a horizon-spanning chord.
        local function depth(p)
            return (p.x - build.camera.x) * build.direction.x + (p.y - build.camera.y) * build.direction.y
                + (p.z - build.camera.z) * build.direction.z
        end
        if depth(a) < math.max(0.8, build.near_clip * 2) or depth(b) < math.max(0.8, build.near_clip * 2) then return false end
        local first, last = Messiah.ProjectClippedSegment(a, b)
        if not first then return false end
        local dx, dy = last.x - first.x, last.y - first.y
        if dx * dx + dy * dy > (span or 0.24) ^ 2 then return false end
        build.max_span = span or 0.24
        Messiah.AddProjectedLine(first, last, colour or { 84, 180, 255 }, width, alpha * 0.28)
        Messiah.AddProjectedLine(first, last, { 218, 248, 255 }, math.max(1, width * 0.28), alpha)
        build.max_span = nil
        return true
    end

    function Messiah.ProjectVolumetricBeam(record, now, a, b)
        local state = Messiah.State()
        local build = state.visual_build
        local basis = Messiah.BeamBasis(a, b)
        if not basis or not build then return false, 'invalid-world-segment' end
        local judgment = record.style == 'judgment'
        local started = tonumber(record.started_ms) or (state.action and state.action.channel_started_ms) or now
        local held = clamp((now - started) / 3000, 0, 1)
        local radius = (judgment and 1.5 or clamp(basis.length * 0.005, 0.26, 0.58) + 0.10 * held)
            * (0.94 + 0.06 * math.sin(now * 0.007))
        local steps = 4
        local colours = { { 246, 254, 255 }, { 78, 222, 255 }, { 42, 138, 255 }, { 144, 70, 255 }, { 74, 174, 255 } }
        local decay = record.expires_ms and clamp((record.expires_ms - now) / 180, 0, 1) or 1
        local owner = state.visual_owner_position
        local function hidden(first, last)
            if not judgment or not owner or owner.epoch ~= state.activation_epoch or owner.frame ~= state.entity_frame then return false end
            local vx, vy, vz = last.x - first.x, last.y - first.y, last.z - first.z
            local length2 = vx * vx + vy * vy + vz * vz
            local u = length2 > 0 and clamp(((owner.x - first.x) * vx + (owner.y - first.y) * vy
                + (owner.z + 0.4 - first.z) * vz) / length2, 0, 1) or 0
            return (first.x + vx * u - owner.x) ^ 2 + (first.y + vy * u - owner.y) ^ 2
                + (first.z + vz * u - owner.z - 0.4) ^ 2 < 2.0 ^ 2
        end
        local core_lines, core_span = 0, 0
        local core_steps = judgment and steps or 1
        build.role = judgment and 'judgment-strand:1' or 'lance-strand:1'
        -- The continuous core has independent admission before ornament. A
        -- held channel is not a set of disconnected rods. Judgment gets a
        -- broad translucent column around the same locked centerline.
        for index = 1, core_steps do
            local t0, t1 = (index - 1) / core_steps, index / core_steps
            local first = { x = a.x + (b.x - a.x) * t0, y = a.y + (b.y - a.y) * t0, z = a.z + (b.z - a.z) * t0 }
            local last = { x = a.x + (b.x - a.x) * t1, y = a.y + (b.y - a.y) * t1, z = a.z + (b.z - a.z) * t1 }
            if not hidden(first, last) and build.projections + 2 <= 192 and #build.snapshot.lines + 4 <= 128 then
                local p, q = Messiah.ProjectClippedSegment(first, last)
                if p then
                    core_span = core_span + math.sqrt((p.x - q.x) ^ 2 + (p.y - q.y) ^ 2)
                    local width = judgment and 58 or 22 + held * 5
                    local before = #build.snapshot.lines
                    Messiah.AddProjectedLine(p, q, { 112, 60, 246 }, width, 24 * decay)
                    Messiah.AddProjectedLine(p, q, { 56, 166, 255 }, width * 0.58, 68 * decay)
                    Messiah.AddProjectedLine(p, q, { 102, 231, 255 }, width * 0.25, 165 * decay)
                    Messiah.AddProjectedLine(p, q, { 246, 254, 255 }, judgment and 7 or 3.8 + held, 250 * decay)
                    core_lines = core_lines + #build.snapshot.lines - before
                end
            end
        end
        for strand = 1, 5 do
            if strand > 1 and build.projections + steps * 2 <= 192 and #build.snapshot.lines + steps * 2 <= 128 then
                local previous
                build.role = (judgment and 'judgment-strand:' or 'lance-strand:') .. strand
                for index = 0, steps do
                    local t = index / steps
                    local angle = (strand - 2) * math.pi / 2 + t * math.pi * 1.1 + now * 0.0018
                    local r = strand == 1 and 0 or radius * (0.76 + 0.24 * math.sin(math.pi * t))
                    local point = {
                        x = a.x + (b.x - a.x) * t + (basis.rx * math.cos(angle) + basis.ux * math.sin(angle)) * r,
                        y = a.y + (b.y - a.y) * t + (basis.ry * math.cos(angle) + basis.uy * math.sin(angle)) * r,
                        z = a.z + (b.z - a.z) * t + (basis.rz * math.cos(angle) + basis.uz * math.sin(angle)) * r
                    }
                    if previous then
                        if not hidden(previous, point) then
                            local first, last = Messiah.ProjectClippedSegment(previous, point)
                            if first then
                                local width = judgment and 10 or 6 + held * 2
                                Messiah.AddProjectedLine(first, last, colours[strand], width, decay * 60)
                                Messiah.AddProjectedLine(first, last, colours[strand], width * 0.28, decay * 200)
                            end
                        end
                    end
                    previous = point
                end
            end
        end
        build.role = judgment and 'judgment-contact' or 'lance-contact'
        Messiah.ProjectBloom(b, judgment and 42 or 23 + held * 4, 240 * decay, false)
        if not judgment then Messiah.ProjectBloom(a, 18 + held * 3, 205 * decay, false) end
        local end_on = not judgment and core_lines > 0 and basis.length > 6 and core_span < 0.035
        if end_on then
            -- End-on perspective really collapses the connecting segment.
            -- Two compact depth accents stay ON that segment; never shift the
            -- endpoint or invent a sideways beam to make a count look better.
            build.role = 'lance-end-on-depth'
            for _, fraction in ipairs({ 0.12, 0.42 }) do
                local point = {
                    x = a.x + (b.x - a.x) * fraction,
                    y = a.y + (b.y - a.y) * fraction,
                    z = a.z +
                        (b.z - a.z) * fraction
                }
                Messiah.ProjectBloom(point, 8 + (1 - fraction) * 5, 150 + 50 * math.sin(now * .009 + fraction * 4), false)
            end
        end
        build.role = nil
        return core_lines > 0, core_lines > 0 and (end_on and 'end-on' or 'connected') or 'clipped-or-budget',
            { core_lines = core_lines, core_span = core_span, end_on = end_on, world_length = basis.length }
    end

    function Messiah.ProjectShockwaveFront(record, now)
        local state = Messiah.State()
        local build = state.visual_build
        local p = type(record) == 'table' and Messiah.VisualPoint(record.position)
        if not build or not p or record.owner_epoch ~= state.activation_epoch
            or not Messiah.VisualFinite(now) or not Messiah.VisualFinite(record.started_ms)
            or not Messiah.VisualFinite(record.expires_ms)
            or now < record.started_ms or now >= record.expires_ms
            or not Messiah.VisualFinite(record.crosses_ms) or record.crosses_ms <= record.started_ms
            or not Messiah.VisualFinite(record.radius_to) or record.radius_to > 24 then
            return false
        end
        local progress = clamp((now - record.started_ms) / (record.crosses_ms - record.started_ms), 0, 1)
        local radius = record.radius_to * progress
        local fade = clamp((record.expires_ms - now) / 180, 0, 1)
        local dx, dy, dz = build.camera.x - p.x, build.camera.y - p.y, build.camera.z - p.z
        local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
        -- One connected spherical silhouette replaces isolated meridian rods.
        -- Every point remains radius metres from the frozen physics center.
        -- The view-oriented section stays curved from above as well as ground
        -- level. Fade inside the front instead of surrounding the camera.
        local inside = clamp((distance - radius * 0.55) / math.max(1.0, radius * 0.45), 0, 1)
        local alpha = 240 * fade * inside
        if alpha < 8 or radius < 0.15 then return false end
        if build.projections + 20 > 192 or #build.snapshot.lines + 20 > 128 then return false end
        build.role = 'shockwave-front:' .. tostring(record.shell_index)
        local previous
        for sample = 0, 10 do
            local elevation = sample * math.pi / 10
            local side, up = math.cos(elevation) * radius, math.sin(elevation) * radius
            local point = {
                x = p.x + build.right.x * side + build.up.x * up,
                y = p.y + build.right.y * side + build.up.y * up,
                z = p.z + build.right.z * side + build.up.z * up
            }
            if previous then
                Messiah.ProjectBoundedStroke(previous, point,
                    clamp(950 / math.max(16, distance), 10, 28), alpha,
                    record.shell_index == 2 and { 130, 72, 255 } or { 54, 212, 255 }, 0.20)
            end
            previous = point
        end
        build.role = nil
        return true
    end

    function Messiah.ProjectOrbVisual(tip, tail, now, charge)
        local build = State.messiah and State.messiah.visual_build
        if not build or not Messiah.VisualPoint(tip) then return false end
        local dx, dy, dz = tip.x - build.camera.x, tip.y - build.camera.y, tip.z - build.camera.z
        local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
        local radius = clamp((charge and 48 or 110) / math.max(1.6, distance), charge and 6 or 5, charge and 13 or 17)
        if tail then
            local basis = Messiah.BeamBasis(tail, tip)
            if basis and build.projections + 8 <= 192 and #build.snapshot.lines + 16 <= 128 then
                build.role = 'orb-tail'
                local previous = tail
                for index = 1, 4 do
                    local t = index / 4
                    local curve = math.sin(t * math.pi) * 0.13
                    local point = {
                        x = tail.x + (tip.x - tail.x) * t + basis.rx * curve,
                        y = tail.y + (tip.y - tail.y) * t + basis.ry * curve,
                        z = tail.z + (tip.z - tail.z) * t + basis.rz * curve
                    }
                    local strength = 60 + index * 42
                    Messiah.ProjectEnergySegment(previous, point, radius * (0.3 + t), strength, false)
                    previous = point
                end
            end
        end
        build.role = charge and 'orb-charge-core' or 'orb-flight-core'
        Messiah.ProjectBloom(tip, radius * 1.5, 250, false)
        -- Explicit luminous body, independently owned by the production Orb
        -- record. A bloom with a tiny center alone was visually just smoke.
        local projected = Messiah.ProjectVisualPoint(tip)
        if projected and projected.x >= 0 and projected.x <= 1 and projected.y >= 0 and projected.y <= 1
            and #build.snapshot.discs + 2 <= 48 then
            for _, spec in ipairs({ { 0.48, 78, 221, 255, 245 }, { 0.30, 245, 255, 255, 255 } }) do
                build.snapshot.discs[#build.snapshot.discs + 1] = {
                    x = projected.x,
                    y = projected.y,
                    wx = tip.x,
                    wy = tip.y,
                    wz = tip.z,
                    radius = math.max(1.5, radius * spec[1]),
                    r = spec[2],
                    g = spec[3],
                    b = spec[4],
                    a = spec[5],
                    filled = true,
                    thickness = 1,
                    role = build.role
                }
            end
        end
        build.role = nil
        return true
    end

    function Messiah.RecordLanceVisualFrame(now, record, status, details)
        local state = Messiah.State()
        if not record or record.style ~= 'channel' then return end
        local serial = record.action_serial or state.action_serial
        local stats = state.lance_visual_diagnostics
        if not stats or stats.epoch ~= state.activation_epoch or stats.action_serial ~= serial then
            stats = {
                epoch = state.activation_epoch,
                action_serial = serial,
                frames = 0,
                core_frames = 0,
                end_on_frames = 0,
                omitted_frames = 0,
                published_frames = 0,
                next_log_ms = 0
            }
            state.lance_visual_diagnostics = stats
        end
        if stats.frame ~= state.entity_frame or stats.now_ms ~= now then
            stats.frames = stats.frames + 1; stats.frame = state.entity_frame; stats.now_ms = now
            if (details.core_lines or 0) > 0 then
                stats.core_frames = stats.core_frames + 1
            else
                stats.omitted_frames = stats.omitted_frames + 1
            end
            if details.end_on then stats.end_on_frames = stats.end_on_frames + 1 end
        end
        stats.status, stats.latest = status, details
        stats.hand, stats.endpoint = Messiah.VisualPoint(record.from), Messiah.VisualPoint(record.target)
    end

    function Messiah.FlushLanceVisualDiagnostics(now, reason)
        local state = Messiah.State()
        local stats = state.lance_visual_diagnostics
        if not stats or stats.epoch ~= state.activation_epoch then return end
        if state.action and (state.action.ability ~= 'LANCE'
                or state.action.serial ~= stats.action_serial) then
            return
        end
        if reason == 'frame' and now < stats.next_log_ms then return end
        stats.next_log_ms = now + 1000
        local latest = stats.latest or {}
        local hand, endpoint = stats.hand or {}, stats.endpoint or {}
        log_info(("Messiah Lance visual: epoch=%d actionSerial=%d status=%s reason=%s frames=%d "
                .. "coreFrames=%d endOnFrames=%d omittedFrames=%d publishedFrames=%d worldLength=%s "
                .. "clearance=%s depthStart=%s depthEnd=%s coreSpan=%s coreLines=%s "
                .. "hand=(%s,%s,%s) endpoint=(%s,%s,%s) geometryOnly=true.")
            :format(stats.epoch, stats.action_serial, tostring(stats.status), tostring(reason), stats.frames,
                stats.core_frames, stats.end_on_frames, stats.omitted_frames, stats.published_frames,
                tostring(latest.world_length), tostring(latest.clearance), tostring(latest.depth_start),
                tostring(latest.depth_end), tostring(latest.core_span), tostring(latest.core_lines),
                tostring(hand.x), tostring(hand.y), tostring(hand.z), tostring(endpoint.x), tostring(endpoint.y),
                tostring(endpoint.z)))
    end

    function Messiah.ProjectBeamVisual(record, now)
        if type(record) ~= 'table' then return false end
        local a, b = Messiah.VisualPoint(record.from), Messiah.VisualPoint(record.target)
        if not a or not b then return false end
        if record.style == 'channel' or record.style == 'judgment' then
            local original = a
            a = Messiah.VisualBeamStart(a, b, record.style)
            local accepted, status, details = Messiah.ProjectVolumetricBeam(record, now, a, b)
            if record.style == 'channel' then
                details = details or {}
                local build = Messiah.State().visual_build
                details.world_length = (Messiah.BeamBasis(original, b) or {}).length
                if a then
                    details.clearance = math.sqrt((a.x - original.x) ^ 2 + (a.y - original.y) ^ 2 + (a.z - original.z) ^
                        2)
                    if build then
                        local function depth(p)
                            return (p.x - build.camera.x) * build.direction.x
                                + (p.y - build.camera.y) * build.direction.y + (p.z - build.camera.z) * build.direction
                                .z
                        end
                        details.depth_start, details.depth_end = depth(a), depth(b)
                    end
                else
                    status = 'owner-occluded'
                end
                Messiah.RecordLanceVisualFrame(now, record, status, details)
            end
            return accepted
        end
        if record.style == 'judgment-inward' then
            local build = Messiah.State().visual_build
            local progress = clamp((now - record.started_ms) / (record.expires_ms - record.started_ms), 0, 1)
            local head = {
                x = a.x + (b.x - a.x) * progress,
                y = a.y + (b.y - a.y) * progress,
                z = a.z + (b.z - a.z) * progress + math.sin(progress * math.pi) * 1.4
            }
            local tail = {
                x = a.x + (b.x - a.x) * math.max(0, progress - 0.24),
                y = a.y + (b.y - a.y) * math.max(0, progress - 0.24),
                z = head.z + 0.2
            }
            build.role = 'judgment-inward'
            Messiah.ProjectBoundedStroke(tail, head, 12, 200, { 126, 90, 255 }, 0.25)
            Messiah.ProjectBloom(head, 13, 215, false)
            build.role = nil
            return true
        end
        return Messiah.ProjectEnergySegment(a, b, 10, 160, false)
    end

    function Messiah.ProjectVisualRing(position, radius, alpha, plane)
        position = Messiah.VisualPoint(position)
        if not position or not Messiah.VisualFinite(radius) or radius < 0 or radius > 64 then return end
        local previous
        for index = 0, 16 do
            local angle = index * math.pi * 2.0 / 16
            local c, s = math.cos(angle) * radius, math.sin(angle) * radius
            local point = {
                x = position.x + (plane == 3 and 0 or c),
                y = position.y + (plane == 2 and 0 or (plane == 3 and c or s)),
                z = position.z + ((plane == 2 or plane == 3) and s or 0.06)
            }
            if previous then Messiah.ProjectBoundedStroke(previous, point, 5, alpha, { 112, 64, 250 }, 0.16) end
            previous = point
        end
    end

    function Messiah.ProjectPressureWave(record, now)
        local state = Messiah.State()
        local build = state.visual_build
        local p = type(record) == 'table' and Messiah.VisualPoint(record.position)
        if not build or not p or record.owner_epoch ~= state.activation_epoch
            or not Messiah.VisualFinite(now) or not Messiah.VisualFinite(record.started_ms)
            or not Messiah.VisualFinite(record.expires_ms) or record.expires_ms <= record.started_ms
            or not Messiah.VisualFinite(record.radius_from) or record.radius_from <= 0
            or not Messiah.VisualFinite(record.radius_to) or record.radius_to <= record.radius_from
            or record.radius_to > 6 or not Messiah.VisualFinite(record.alpha)
            or now < record.started_ms or now >= record.expires_ms then
            return false
        end
        local final = record.wave_profile == 'SUPER_IMPACT'
        local duration = record.expires_ms - record.started_ms
        local t = clamp((now - record.started_ms) / math.max(1, duration), 0, 1)
        local compress = t < 0.20
        local radius = compress and record.radius_from * (1 - t / 0.20 * 0.8)
            or record.radius_from + (record.radius_to - record.radius_from) * clamp((t - 0.20) / 0.80, 0, 1)
        local alpha = (1 - t) * record.alpha
        build.role = final and 'judgment-final-core' or 'orb-contact'
        Messiah.ProjectBloom(p, (final and 64 or 30) * (compress and 0.6 or 1),
            (compress and 170 or 255) * clamp((1 - t) * 2, 0, 1), false)
        -- Disconnected distortion arcs never become a full camera-sized annulus.
        for index = 0, 5 do
            local angle = index * math.pi / 3 + 0.12
            local a = { x = p.x + math.cos(angle) * radius, y = p.y + math.sin(angle) * radius, z = p.z + 0.15 }
            local b = {
                x = p.x + math.cos(angle + 0.40) * radius,
                y = p.y + math.sin(angle + 0.40) * radius,
                z = p.z +
                    0.30
            }
            Messiah.ProjectBoundedStroke(a, b, final and 13 or 8, alpha, { 132, 92, 255 }, 0.16)
        end
        build.role = nil
        return true
    end

    function Messiah.ProjectMarkerVisual(record, radius, alpha)
        local state = Messiah.State()
        local build = state.visual_build
        local p = Messiah.VisualPoint(record.position)
        if not p or not build then return false end
        if record.kind == 'ground-cracks' then
            build.role = 'rupture-cracks'
            -- Same serial rotation and five 4.8 m endpoints as the actual
            -- scheduled eruptions. Only the middle of each fissure bends.
            local rotation = ((record.owner_action_serial or 0) % 8) * math.pi / 8
            local reach = 4.8 * clamp(radius / math.max(0.18, record.radius_to), 0, 1)
            for index = 0, 4 do
                local angle = rotation + index * math.pi * 2 / 5
                local bend = ((index % 3) - 1) * 0.16
                local middle = {
                    x = p.x + math.cos(angle + bend) * reach * 0.52,
                    y = p.y + math.sin(angle + bend) * reach * 0.52,
                    z = p.z + 0.06
                }
                local tip = {
                    x = p.x + math.cos(angle) * reach,
                    y = p.y + math.sin(angle) * reach,
                    z = p.z + 0.06
                }
                Messiah.ProjectBoundedStroke({ x = p.x, y = p.y, z = p.z + 0.04 }, middle, 16, alpha, { 80, 34, 185 },
                    0.24)
                Messiah.ProjectBoundedStroke(middle, tip, 12, alpha, { 70, 154, 255 }, 0.24)
            end
        elseif record.kind == 'eruption' then
            build.role = record.final_core and 'rupture-core' or 'rupture-eruption'
            local progress = clamp((build.snapshot.now_ms - record.started_ms) / (record.expires_ms - record.started_ms),
                0, 1)
            for index = 0, 4 do
                local angle = index * math.pi * 2 / 5 + (record.owner_action_serial or 1) * 0.4
                local height = (record.final_core and 4.2 or 2.8) * math.sin(progress * math.pi * 0.8)
                local spread = (record.final_core and 2.8 or 1.8) * progress
                local tip = { x = p.x + math.cos(angle) * spread, y = p.y + math.sin(angle) * spread, z = p.z + height }
                local tail = {
                    x = p.x + math.cos(angle) * spread * 0.18,
                    y = p.y + math.sin(angle) * spread * 0.18,
                    z =
                        p.z + 0.06
                }
                Messiah.ProjectBoundedStroke(tail, tip, record.final_core and 28 or 20, alpha, { 112, 60, 238 }, 0.22)
            end
            build.role = 'rupture-debris'
            for index = 0, 2 do
                local angle = index * math.pi * 2 / 3 + 0.7
                local spread = (record.final_core and 3.8 or 2.5) * progress
                local height = (record.final_core and 3.2 or 2.2) * 4 * progress * (1 - progress)
                local center = {
                    x = p.x + math.cos(angle) * spread,
                    y = p.y + math.sin(angle) * spread,
                    z = p.z + height +
                        0.2
                }
                local size = (record.final_core and 0.26 or 0.18) * (1 - progress * 0.45)
                local a = { x = center.x - size, y = center.y, z = center.z - size * 0.35 }
                local b = { x = center.x + size * 0.6, y = center.y + size * 0.5, z = center.z }
                local c = { x = center.x, y = center.y - size * 0.6, z = center.z + size }
                Messiah.ProjectBoundedStroke(a, b, 5, alpha * 0.75, { 132, 114, 101 }, 0.08)
                Messiah.ProjectBoundedStroke(b, c, 5, alpha * 0.75, { 132, 114, 101 }, 0.08)
                Messiah.ProjectBoundedStroke(c, a, 5, alpha * 0.75, { 132, 114, 101 }, 0.08)
            end
            Messiah.ProjectBloom(p, record.final_core and 32 or 20, alpha, false)
        elseif record.kind == 'judgment-compression' then
            build.role = 'judgment-compression'
            local progress = clamp((build.snapshot.now_ms - record.started_ms) / (record.expires_ms - record.started_ms),
                0, 1)
            local r = 3.8 * (1 - progress) + 0.35
            for index = 0, 5 do
                local angle = index * math.pi / 3 + progress * 0.9
                local a = { x = p.x + math.cos(angle) * r, y = p.y + math.sin(angle) * r, z = p.z + 0.15 + progress }
                local b = {
                    x = p.x + math.cos(angle + 0.14) * r * 0.65,
                    y = p.y + math.sin(angle + 0.14) * r * 0.65,
                    z =
                        p.z + 0.25
                }
                Messiah.ProjectBoundedStroke(a, b, 10, alpha, { 123, 65, 248 }, 0.20)
            end
            Messiah.ProjectBloom(p, 20 + progress * 18, alpha, false)
            Messiah.ProjectVisualRing(p, 0.45 + 0.2 * (1 - progress), alpha * 0.6, 1)
        else
            Messiah.ProjectVisualRing(p, math.min(radius, 3), math.min(alpha, 140), 1)
        end
        build.role = nil
        return true
    end

    function Messiah.PublishVisualSnapshot(now)
        local state = Messiah.State()
        local build = state.visual_build
        if not build then return end
        local snapshot = build.snapshot
        state.visual_build = nil
        if not state.active or not state.gameplay_owner or state.restoring or state.disposed
            or state.ending or snapshot.epoch ~= state.activation_epoch
            or snapshot.action_serial ~= state.action_serial then
            return
        end
        snapshot.projection_accepted, snapshot.projection_rejected = build.accepted, build.rejected
        snapshot.projection_attempts, snapshot.camera_calibration_calls = build.projections, build.calibration_calls
        state.visual_snapshot = snapshot
        local lance = state.lance_visual_diagnostics
        if lance and lance.epoch == snapshot.epoch and lance.action_serial == snapshot.action_serial
            and lance.frame == state.entity_frame and lance.now_ms == now then
            lance.published_frames = lance.published_frames + 1
            lance.published_generation = snapshot.generation
            Messiah.FlushLanceVisualDiagnostics(now, 'frame')
        end
        if snapshot.debug and now >= (tonumber(state.next_visual_log_ms) or 0) then
            state.next_visual_log_ms = now + 1000
            log_info(("Messiah visual snapshot published: epoch=%d actionSerial=%d generation=%d "
                    .. "projectionAccepted=%d projectionRejected=%d lines=%d discs=%d "
                    .. "primary=immutable-world-geometry/render-camera fallback=%s visibility=live-unverified.")
                :format(snapshot.epoch, snapshot.action_serial, snapshot.generation,
                    build.accepted, build.rejected, #snapshot.lines, #snapshot.discs,
                    "native-impact-effects"))
        end
    end

    function Messiah.VisualSnapshot(known_generation)
        -- Pure detached copy. UI can retain its own copy while this generation
        -- remains valid; ordinary callers still receive independent tables.
        -- No shared proxy: even rawset cannot alter the publisher's geometry.
        local state = type(State.messiah) == "table" and State.messiah or nil
        local snapshot = state and state.visual_snapshot
        if not state or not state.active or state.restoring or state.disposed or state.ending
            or not snapshot or snapshot.epoch ~= state.activation_epoch
            or snapshot.action_serial ~= state.action_serial
            or snapshot.generation ~= state.visual_generation then
            return nil, false
        end
        if known_generation == snapshot.generation then return nil, true end
        local copy = {
            active = true,
            epoch = snapshot.epoch,
            action_serial = snapshot.action_serial,
            generation = snapshot.generation,
            now_ms = snapshot.now_ms,
            debug = snapshot.debug,
            world_geometry = snapshot.world_geometry,
            projection_attempts = snapshot.projection_attempts,
            projection_accepted = snapshot.projection_accepted,
            projection_rejected = snapshot.projection_rejected,
            camera_calibration_calls = snapshot.camera_calibration_calls,
            lines = {},
            discs = {}
        }
        for _, name in ipairs({ "lines", "discs" }) do
            for index = 1, math.min(name == "lines" and 128 or 48, #snapshot[name]) do
                local row = {}
                for key, value in pairs(snapshot[name][index]) do row[key] = value end
                copy[name][index] = row
            end
        end
        return copy, false
    end

    function Messiah.ProjectRenderSnapshot(snapshot)
        -- The UI retains only a detached world snapshot. This adapter samples
        -- read-only render-camera data and performs arithmetic; no entity,
        -- control, task, particle or gameplay mutation enters this path.
        local state = State.messiah
        local now = now_ms()
        local function current()
            return state and State.messiah == state and state.active and not state.ending
                and not state.restoring and not state.disposed and type(snapshot) == "table"
                and snapshot.world_geometry == true and snapshot.epoch == state.activation_epoch
                and snapshot.action_serial == state.action_serial and snapshot.generation == state.visual_generation
                and Messiah.VisualFinite(snapshot.now_ms) and now >= snapshot.now_ms and now - snapshot.now_ms <= 150
        end
        if not current() then return nil end
        local camera = Messiah.ValidatedVisualCamera(now, true, snapshot.generation)
        if not camera or not current() then return nil end
        local function camera_point(x, y, z)
            local point = Messiah.VisualPoint({ x = x, y = y, z = z })
            if not point then return nil end
            local dx, dy, dz = point.x - camera.camera.x, point.y - camera.camera.y, point.z - camera.camera.z
            return {
                x = (dx * camera.right.x + dy * camera.right.y + dz * camera.right.z) * camera.scale_x,
                y = (dx * camera.up.x + dy * camera.up.y + dz * camera.up.z) * camera.scale_y,
                z = dx * camera.direction.x + dy * camera.direction.y + dz * camera.direction.z
            }
        end
        local function segment(row)
            local a, b = camera_point(row.wx1, row.wy1, row.wz1), camera_point(row.wx2, row.wy2, row.wz2)
            if not a or not b then return nil end
            local low, high = 0, 1
            local function clip(first, last)
                if first < 0 and last < 0 then return false end
                if first < 0 then
                    low = math.max(low, first / (first - last))
                elseif last < 0 then
                    high = math.min(high, first / (first - last))
                end
                return low <= high
            end
            if not clip(a.z - camera.near_clip, b.z - camera.near_clip)
                or not clip(a.z + a.x, b.z + b.x) or not clip(a.z - a.x, b.z - b.x)
                or not clip(a.z + a.y, b.z + b.y) or not clip(a.z - a.y, b.z - b.y) then
                return nil
            end
            local dx, dy, dz = b.x - a.x, b.y - a.y, b.z - a.z
            local za, zb = a.z + dz * low, a.z + dz * high
            return clamp(.5 + (a.x + dx * low) / (2 * za), 0, 1), clamp(.5 - (a.y + dy * low) / (2 * za), 0, 1),
                clamp(.5 + (a.x + dx * high) / (2 * zb), 0, 1), clamp(.5 - (a.y + dy * high) / (2 * zb), 0, 1)
        end
        local result = {
            active = true,
            epoch = snapshot.epoch,
            action_serial = snapshot.action_serial,
            generation = snapshot.generation,
            now_ms = snapshot.now_ms,
            debug = snapshot.debug,
            world_geometry = false,
            projection_phase = "render",
            lines = {},
            discs = {},
            projection_attempts = 0,
            projection_accepted = 0,
            projection_rejected = 0,
            camera_calibration_calls = camera.calibration_calls
        }
        for _, name in ipairs({ "lines", "discs" }) do
            local rows = type(snapshot[name]) == "table" and snapshot[name] or {}
            for index = 1, math.min(#rows, name == "lines" and 128 or 48) do
                local row = rows[index]
                result.projection_attempts = result.projection_attempts + 1
                if type(row) == "table" then
                    local projected = {}
                    for key, value in pairs(row) do if type(value) ~= "table" then projected[key] = value end end
                    local accepted = false
                    if name == "lines" then
                        projected.x1, projected.y1, projected.x2, projected.y2 = segment(row)
                        accepted = projected.x1 ~= nil
                        -- Compact pressure arcs must stay compact after a
                        -- render-camera move as well as during publication.
                        if accepted and row.max_span ~= nil then
                            accepted = Messiah.VisualFinite(row.max_span) and row.max_span > 0
                                and (projected.x2 - projected.x1) ^ 2 + (projected.y2 - projected.y1) ^ 2 <=
                                row.max_span ^ 2
                        end
                    else
                        local point = Messiah.ProjectValidatedCameraPoint({ x = row.wx, y = row.wy, z = row.wz }, camera)
                        if point then
                            projected.x, projected.y = point.x, point.y; accepted = true
                        end
                    end
                    if accepted then
                        result[name][#result[name] + 1] = projected
                        result.projection_accepted = result.projection_accepted + 1
                    end
                end
            end
        end
        result.projection_rejected = result.projection_attempts - result.projection_accepted
        return current() and result or nil
    end

    function Messiah.ProjectRenderHudSnapshot(snapshot)
        local state = State.messiah
        if type(snapshot) ~= "table" or not state or not state.active or state.restoring or state.ending
            or state.disposed or snapshot.epoch ~= state.activation_epoch
            or snapshot.action_serial ~= state.action_serial then
            return nil
        end
        local epoch, frame = state.activation_epoch, state.entity_frame
        local action, phase, beam = state.action, state.phase, state.channel_beam
        local generation = state.visual_generation
        if snapshot.phase ~= nil and snapshot.phase ~= phase then return nil end
        local function current()
            return State.messiah == state and state.active and not state.ending
                and not state.restoring and not state.disposed and state.activation_epoch == epoch
                and state.entity_frame == frame and state.visual_generation == generation
                and snapshot.action_serial == state.action_serial and state.action == action
                and state.phase == phase and state.channel_beam == beam
        end
        local copy = {}
        for key, value in pairs(snapshot) do copy[key] = value end
        copy.reticle = {}
        for key, value in pairs(snapshot.reticle or {}) do copy.reticle[key] = value end
        local r = copy.reticle
        if r.locked_ground or r.projected_contact then
            r.screen_x, r.screen_y = nil, nil
            local rendered = Messiah.ProjectRenderSnapshot({
                active = true,
                world_geometry = true,
                epoch = snapshot.epoch,
                action_serial = snapshot.action_serial,
                generation = state.visual_generation,
                now_ms = snapshot.now_ms,
                lines = {},
                discs = { { wx = r.world_x, wy = r.world_y, wz = r.world_z } }
            })
            if rendered and rendered.discs[1] then
                r.screen_x, r.screen_y = rendered.discs[1].x, rendered.discs[1].y
            end
        end
        return current() and copy or nil
    end

    function Messiah.SharedBeamModelReady(now)
        local state = Messiah.State()
        if state.shared_model_ready then return true end
        if state.shared_model_failed or not Messiah.EntityOwner() then return false end
        if now < (state.shared_model_poll_ms or 0) then return false end
        state.shared_model_poll_ms = now + 100
        local _, model = Messiah.NormalizeHash(Messiah.SHARED_BEAM_MODEL)
        if not state.shared_model_requested then
            if not invoke_bool(H.IS_MODEL_VALID, model) or not invoke_bool(H.IS_MODEL_IN_CDIMAGE, model) then
                state.shared_model_failed = true
                Messiah.RecordFxTransport("beam-model", "prop_dummy_01-validation", false)
                return false
            end
            state.shared_model_requested, state.shared_model_deadline = true, now + 5000
            invoke_void(H.REQUEST_MODEL, model)
        end
        state.shared_model_ready = invoke_bool(H.HAS_MODEL_LOADED, model) == true
        if not state.shared_model_ready and now >= state.shared_model_deadline then
            state.shared_model_failed = true
            Messiah.RecordFxTransport("beam-model", "prop_dummy_01-streaming", false)
        end
        return state.shared_model_ready
    end

    function Messiah.StopSharedBeam(key)
        local state = Messiah.State()
        local record = state.shared_beams[key]
        if not record or not Messiah.EntityOwner(record.lease) then return false end
        -- Consume the emitter first. The existing entity deleter revokes its
        -- identity before entering DELETE_ENTITY and never dereferences it again.
        if record.fx then
            local fx = record.fx; record.fx = nil
            Messiah.StopFx(fx)
        end
        local deleted, detail, access_ended = Messiah.DeleteEntity(record.handle, record.lease)
        record.delete_attempts = (record.delete_attempts or 0) + 1
        if access_ended or record.delete_attempts >= 3 then
            Messiah.RecordCleanupEvidence(record.lease, detail or "cleanup-retry-cap", false)
            state.shared_beams[key] = nil
            Messiah.RetireEntityLease(record.lease, "shared-beam-cleanup", false)
        end
        return deleted == true
    end

    function Messiah.CreateSharedBeam(key, point, now)
        local state = Messiah.State()
        local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame and state.action == action
        end
        local online = Messiah.FxOnline()
        -- No permanent reason on a deferred probe: UpdateSharedBeam owns its
        -- existing bounded retry window and must not latch shared_unavailable.
        if online == nil or not current() then return nil end
        if state.shared_create_frame == state.entity_frame then return nil end
        local count = 0
        for _ in pairs(state.shared_beams) do count = count + 1 end
        if count >= Messiah.MAX_SHARED_BEAMS or not Messiah.SharedBeamModelReady(now) or not current() then return nil end
        state.shared_create_frame = state.entity_frame
        local _, model = Messiah.NormalizeHash(Messiah.SHARED_BEAM_MODEL)
        state.shared_beam_serial = state.shared_beam_serial + 1
        local creation = {
            epoch = epoch,
            action_serial = state.action_serial,
            creation_serial = state.shared_beam_serial,
            kind = "object",
            source = "beam-creation"
        }
        local value, raw, err = invoke_int_detail(H.CREATE_OBJECT_NO_OFFSET, model,
            point.x, point.y, point.z, online, true, false, 0)
        local handle = Messiah.NormalizeEntityHandle(value)
        if not current() or (handle == 0 and (err ~= nil or raw ~= 0)) then
            local evidence = Messiah.RecordCleanupEvidence(creation, "creation-context-or-result-unknown", false)
            if evidence and not current() then evidence.scope = "ended" end
            return nil, "creation-unverified"
        end
        if handle == 0 then
            Messiah.RecordFxTransport("beam-anchor", "CREATE_OBJECT_NO_OFFSET", false)
            return nil, "create-rejected"
        end
        local lease = Messiah.AcquireEntityLease(handle, "object", {
            source = "carrier",
            owned = true,
            fresh_creation = true,
            creation_serial = state.shared_beam_serial,
            action = "SHARED_FX",
            action_serial = state.action_serial
        })
        if not lease then
            local evidence = Messiah.RecordCleanupEvidence(creation, "positive-create-without-safe-identity", false)
            if evidence and not current() then evidence.scope = "ended" end
            Messiah.RecordFxTransport("beam-anchor", "owned-identity-readback", false)
            return nil, "identity-rejected"
        end
        local record = {
            handle = handle,
            lease = lease,
            epoch = state.activation_epoch,
            expires_ms = now + 1200,
            ready_deadline = now + 1200,
            last_update_ms = now - 1000
        }
        state.shared_beams[key] = record
        local observed = Messiah.LeaseInvoke(lease, "int", "GET_ENTITY_MODEL", H.GET_ENTITY_MODEL, handle)
        if Messiah.NormalizeHash(observed) ~= Messiah.NormalizeHash(Messiah.SHARED_BEAM_MODEL) then
            Messiah.StopSharedBeam(key); return nil, "model-mismatch"
        end
        local function set(name, ...)
            return Messiah.LeaseInvoke(lease, "void", name, H[name], handle, ...) == true
        end
        if not set("SET_ENTITY_VISIBLE", false, false)
            or not set("SET_ENTITY_AS_MISSION_ENTITY", true, true)
            or not set("SET_ENTITY_COLLISION", false, false)
            or not set("SET_ENTITY_HAS_GRAVITY", false)
            or not set("SET_ENTITY_DYNAMIC", false)
            or not set("SET_ENTITY_CAN_BE_DAMAGED", false) then
            Messiah.StopSharedBeam(key); return nil, "configuration-rejected"
        end
        -- The model is a visible dummy, not an intrinsically invisible anchor.
        -- Barry's own beam carriers are hidden before attaching this particle.
        local visible, raw, err = Messiah.LeaseInvoke(lease, "bool", "IS_ENTITY_VISIBLE",
            H.IS_ENTITY_VISIBLE, handle)
        if err or (type(raw) ~= "boolean" and type(raw) ~= "number") or visible ~= false then
            Messiah.StopSharedBeam(key); return nil, "visibility-not-confirmed"
        end
        return record
    end

    function Messiah.UpdateSharedBeam(key, visual, now)
        local state = Messiah.State()
        if not Messiah.EntityOwner() or state.ending then return false end
        if visual.shared_unavailable then return false end
        local from, target = Messiah.VisualPoint(visual.from), Messiah.VisualPoint(visual.target)
        if from and target and Messiah.VisualBeamStart then
            from = Messiah.VisualBeamStart(from, target, visual.style)
        end
        local basis = from and target and Messiah.BeamBasis(from, target)
        if not basis then
            if state.shared_beams[key] then Messiah.StopSharedBeam(key) end
            return false
        end
        local record, reason = state.shared_beams[key], nil
        if not record then record, reason = Messiah.CreateSharedBeam(key, from, now) end
        if reason then visual.shared_unavailable = true end
        if not record or record.epoch ~= state.activation_epoch then return false end
        record.expires_ms = tonumber(visual.expires_ms) or now + 180
        if now < record.last_update_ms + Messiah.SHARED_BEAM_UPDATE_MS then return record.fx ~= nil end
        record.last_update_ms = now
        if not Messiah.ValidateEntityLease(record.lease, "shared-beam-frame", "none") then
            visual.shared_unavailable = true
            Messiah.StopSharedBeam(key); return false
        end
        -- GTA's Barry beam is authored along +Z and attached at -90 pitch to
        -- point along an entity's +Y (forward) axis. No guessed evolution names.
        local flat = math.sqrt(basis.dx * basis.dx + basis.dy * basis.dy)
        local pitch = math.deg(math.atan(basis.dz, flat))
        local heading = math.deg(math.atan(-basis.dx, basis.dy))
        local previous = record.transform
        local changed = not previous or math.abs(from.x - previous.x) > 0.01
            or math.abs(from.y - previous.y) > 0.01 or math.abs(from.z - previous.z) > 0.01
            or math.abs(pitch - previous.pitch) > 0.1 or math.abs(heading - previous.heading) > 0.1
        if changed then
            local moved = Messiah.LeaseInvoke(record.lease, "void", "SET_ENTITY_COORDS_NO_OFFSET",
                H.SET_ENTITY_COORDS_NO_OFFSET, record.handle, from.x, from.y, from.z, true, true, false)
            local turned = moved == true and Messiah.LeaseInvoke(record.lease, "void", "SET_ENTITY_ROTATION",
                H.SET_ENTITY_ROTATION, record.handle, pitch, 0.0, heading, 2, true)
            if turned ~= true then
                visual.shared_unavailable = true
                Messiah.StopSharedBeam(key); return false
            end
            record.transform = { x = from.x, y = from.y, z = from.z, pitch = pitch, heading = heading }
        end
        if not record.fx then
            if now >= record.ready_deadline then
                visual.shared_unavailable = true
                Messiah.StopSharedBeam(key); return false
            end
            record.fx = Messiah.StartLoopedFxOnEntity(record.handle, Messiah.ALIEN_FX_ASSET,
                "scr_alien_beam", visual.style == "judgment" and 2.20 or 0.95,
                { 0.14, 0.58, 1.0 }, "beam-" .. tostring(visual.style), 0, 0, 0, record.lease, -90.0, 0, 0)
        end
        if record.fx and visual.style == "judgment" then
            local owner = state.visual_owner_position
            local near_column = owner and owner.epoch == state.activation_epoch
                and owner.frame == state.entity_frame
                and (owner.x - target.x) ^ 2 + (owner.y - target.y) ^ 2 < 2.25
                and owner.z >= target.z - 2 and owner.z <= from.z + 2
            local alpha = near_column and 0.08 or 1.0
            if record.local_alpha ~= alpha then
                Messiah.SetFxAlpha(record.fx, alpha)
                record.local_alpha = alpha
            end
        end
        local clip = clamp(basis.length, 0.25, Messiah.DIRECT_AIM_DISTANCE)
        if record.fx and H.SET_PARTICLE_FX_LOOPED_FAR_CLIP_DIST
            and (not record.clip_distance or math.abs(clip - record.clip_distance) > 0.05) then
            if invoke_void(H.SET_PARTICLE_FX_LOOPED_FAR_CLIP_DIST, record.fx.handle, clip) == true then
                record.clip_distance = clip
            end
        end
        return record.fx ~= nil
    end

    function Messiah.TickVisuals(now)
        local state = Messiah.State()
        -- Shared world particles and caster guidance have separate render paths.
        -- A failed local projection never suppresses world FX or owns their cleanup.
        if not Messiah.EntityOwner() or state.ending then
            if state.visual_snapshot or state.visual_build then Messiah.ClearVisualSnapshot() end
            return
        end
        if state.channel_beam then
            Messiah.UpdateSharedBeam("lance", state.channel_beam, now)
        elseif state.shared_beams.lance then
            Messiah.StopSharedBeam("lance")
        end
        local beams = state.visuals.beams
        for index = #beams, 1, -1 do
            local visual = beams[index]
            if now >= visual.expires_ms or (visual.owner_epoch and visual.owner_epoch ~= state.activation_epoch) then
                table.remove(beams, index)
            else
                if not visual.shared_key then
                    state.shared_visual_serial = (state.shared_visual_serial or 0) + 1
                    visual.shared_key = "strike:" .. tostring(state.shared_visual_serial)
                end
                if not visual.local_only then Messiah.UpdateSharedBeam(visual.shared_key, visual, now) end
            end
        end
        for index = #state.visuals.markers, 1, -1 do
            local visual = state.visuals.markers[index]
            if now >= visual.expires_ms or (visual.owner_epoch and visual.owner_epoch ~= state.activation_epoch) then
                table.remove(state.visuals.markers, index)
            elseif now >= visual.started_ms and not visual.local_only and not visual.shared_emitted and not visual.shared_consumed then
                local p = visual.position
                local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
                local accepted, consumed = Messiah.StartTimedFxAtCoord(Messiah.ALIEN_FX_ASSET,
                    "scr_alien_teleport", p.x, p.y, p.z + 0.1, 0.45, 0, "ground-charge")
                -- This is captured-record consumption bookkeeping, never new
                -- action publication. A frame/action change cannot authorize
                -- reissuing an event whose host call may already have run.
                if consumed == true then visual.shared_consumed = true end
                if not Messiah.ActivationContextCurrent(state, epoch)
                    or state.entity_frame ~= frame or state.action ~= action then
                    return
                end
                visual.shared_emitted = accepted == true or consumed == true
                visual.shared_accepted = accepted == true
            end
        end
        for index = #state.visuals.lights, 1, -1 do
            local light = state.visuals.lights[index]
            if now >= light.expires_ms or light.owner_epoch ~= state.activation_epoch then
                table.remove(
                    state.visuals.lights, index)
            end
        end
        local expired = {}
        for key, record in pairs(state.shared_beams) do
            if now >= record.expires_ms or record.epoch ~= state.activation_epoch then expired[#expired + 1] = key end
        end
        for _, key in ipairs(expired) do Messiah.StopSharedBeam(key) end
        Messiah.TickLocalVisuals(now)
    end

    -- Caster-only guidance uses the existing detached, bounded projection backend.

    function Messiah.TickLocalVisuals(now)
        local state = Messiah.State()
        local visuals = state.visuals
        local action = state.action
        local charging = action and action.ability == 'ORB' and not action.ending
            and state.phase == Messiah.PHASES.ORB_WINDUP and action.visual_charge_position
        if not state.channel_beam and #visuals.beams == 0 and #visuals.markers == 0
            and #visuals.lights == 0 and next(state.projectiles) == nil and not charging then
            if state.visual_snapshot or state.visual_build then Messiah.ClearVisualSnapshot() end
            return
        end
        if not Messiah.BeginVisualSnapshot(now) then return end
        local function live(record)
            return (not record.owner_epoch or record.owner_epoch == state.activation_epoch)
                and now >= (tonumber(record.started_ms) or -math.huge) and now < record.expires_ms
        end
        -- Critical compact final flash is admitted before any optional accents.
        for index = #visuals.markers, 1, -1 do
            local record = visuals.markers[index]
            if record.kind == 'pressure-wave' and record.wave_profile == 'SUPER_IMPACT' and live(record) then
                Messiah.ProjectPressureWave(record, now); break
            end
        end
        if state.channel_beam then Messiah.ProjectBeamVisual(state.channel_beam, now) end
        -- All three E fronts reserve tiny independent patches; Q fissures own
        -- the next priority, ahead of Orb spam and satellite decoration.
        for _, record in ipairs(visuals.markers) do
            if record.kind == 'shockwave-front' and live(record) then Messiah.ProjectShockwaveFront(record, now) end
        end
        local cracks = 0
        for index = #visuals.markers, 1, -1 do
            local record = visuals.markers[index]
            if record.kind == 'ground-cracks' and live(record) and cracks < 1 then
                local t = clamp(
                    (now - record.started_ms) / math.max(1, (record.release_ms or record.expires_ms) - record.started_ms),
                    0,
                    1)
                Messiah.ProjectMarkerVisual(record, record.radius_from + (record.radius_to - record.radius_from) * t, 225)
                cracks = cracks + 1
            end
        end
        for index = #visuals.beams, 1, -1 do
            local record = visuals.beams[index]
            if record.style == 'judgment' and live(record) then
                Messiah.ProjectBeamVisual(record, now); break
            end
        end
        if charging then Messiah.ProjectOrbVisual(action.visual_charge_position, nil, now, true) end
        local orb_count = 0
        for _, info in pairs(state.projectiles) do
            if orb_count >= Messiah.MAX_ORBS then break end
            if not info.cleanup_reason and info.visual_position and info.visual_tail
                and info.visual_frame_ms == state.last_tick_ms then
                Messiah.ProjectOrbVisual(info.visual_position, info.visual_tail, now, false)
                orb_count = orb_count + 1
            end
        end
        local marker_count = 0
        for index = #visuals.markers, 1, -1 do
            local record = visuals.markers[index]
            if live(record) and record.kind ~= 'ground-cracks' and record.kind ~= 'shockwave-front'
                and not (record.kind == 'pressure-wave' and record.wave_profile == 'SUPER_IMPACT') and marker_count < 4 then
                marker_count = marker_count + 1
                local t = clamp((now - record.started_ms) / math.max(1, record.expires_ms - record.started_ms), 0, 1)
                if record.kind == 'pressure-wave' then
                    Messiah.ProjectPressureWave(record, now)
                else
                    Messiah.ProjectMarkerVisual(record, record.radius_from + (record.radius_to - record.radius_from) * t,
                        math.floor(record.alpha * (1 - t * 0.7)))
                end
                if record.local_bloom then Messiah.ProjectBloom(record.position, record.local_bloom, 160, false) end
            end
        end
        local accent_count = 0
        for index = #visuals.beams, 1, -1 do
            local record = visuals.beams[index]
            if record.style ~= 'judgment' and live(record) and accent_count < 3 then
                Messiah.ProjectBeamVisual(record, now); accent_count = accent_count + 1
            end
        end
        for index = #visuals.lights, math.max(1, #visuals.lights - 1), -1 do
            local record = visuals.lights[index]
            if record and live(record) then
                local t = (now - record.started_ms) / (record.expires_ms - record.started_ms)
                state.visual_build.role = 'owned-light'
                Messiah.ProjectBloom(record.position, clamp(record.range * 1.4, 8, 32), 120 * (1 - t), false)
            end
        end
        state.visual_build.role = nil
        Messiah.PublishVisualSnapshot(now)
    end

    function Messiah.AnimationSpec(kind)
        local profile = Messiah.AnimationProfile(Messiah.State().ped)
        if profile and kind == "idle" then
            local candidates = profile.idle_candidates or {}
            local index = math.max(1, math.min(#candidates,
                math.floor(tonumber(Messiah.State().idle_candidate_index) or 1)))
            return candidates[index]
        end
        return profile and profile[kind] or nil
    end

    function Messiah.AdvanceIdleCandidate(reason)
        local state = Messiah.State()
        local profile = Messiah.AnimationProfile(state.ped)
        local candidates = profile and profile.idle_candidates or {}
        local index = math.max(1, math.floor(tonumber(state.idle_candidate_index) or 1))
        local current = candidates[index]
        if current then
            Messiah.StopAnimation(state.ped, current)
            state.animation_started[current.dict .. "\0" .. current.name] = nil
        end
        state.stance_started = false
        state.idle_task_pending = false
        state.idle_task_started_ms = 0
        state.animation_repairs = 0
        state.animation_next_check_ms = 0
        if index >= #candidates then
            state.idle_candidates_exhausted = true
            if not state.pose_failure_notified then
                state.pose_failure_notified=true
                toast("Messiah pose unavailable: GTA rejected the tested idle animations.",4500)
            end
            state.idle_retry_ms = now_ms() + 1500
            Messiah.LogOnce("idle-animation-candidates-exhausted",
                ("Messiah idle animation unavailable: activation=%d reason=%s "
                    .. "candidate=%d/%d allCandidatesExhausted=true.")
                :format(state.activation_id, tostring(reason or "unknown"), index, #candidates))
            return false
        end
        state.idle_candidate_index = index + 1
        state.idle_candidates_exhausted = false
        if index==1 and not state.ghost_fallback_notified then
            state.ghost_fallback_notified=true
            toast("Messiah ghost float was rejected; using a fallback pose.",3500)
        end
        local replacement = candidates[state.idle_candidate_index]
        Messiah.Trace(("Messiah idle animation fallback: activation=%d reason=%s from=%s/%s "
                .. "to=%s/%s candidate=%d/%d source=%s liveAcceptance=pending.")
            :format(state.activation_id, tostring(reason or "unknown"),
                current and current.dict or "none", current and current.name or "none",
                replacement and replacement.dict or "none", replacement and replacement.name or "none",
                state.idle_candidate_index, #candidates,
                replacement and replacement.source or "none"))
        return true
    end

    function Messiah.PlayAnimation(ped, kind, spec)
        local state = Messiah.State()
        local epoch, lease = state.activation_epoch, state.ped_lease
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch) and lease == state.ped_lease
                and lease ~= nil and lease.handle == Messiah.NormalizeEntityHandle(ped)
        end
        if not current() then return false end
        if not spec then
            state.animation_last_reason = "spec-unavailable"
            return false
        end
        if not invoke_bool(H.HAS_ANIM_DICT_LOADED, spec.dict) then
            state.animation_last_reason = "dict-not-ready"
            return false
        end
        if not current() then return false end
        local key = spec.dict .. "\0" .. spec.name
        local previous = state.animation_started[key]
        -- Claim the exact task before entering the host. A callback that
        -- quiesces the owner must still have this task available for its drain.
        state.animation_started[key] = { dict = spec.dict, name = spec.name, kind = kind }
        local accepted, _, err = Messiah.LeaseInvoke(lease, "void", "TASK_PLAY_ANIM",
            H.TASK_PLAY_ANIM, ped, spec.dict, spec.name,
            kind == "idle" and 2.0 or 3.0, -2.0, spec.duration, spec.flags,
            tonumber(spec.playback) or 1.0, false, false, false)
        if not current() then return false end
        local started = accepted == true
        if started then
            if kind == "idle" then
                state.stance_started = false
                state.idle_task_pending = true
                state.idle_task_started_ms = now_ms()
                state.animation_last_reason = "task-accepted-awaiting-readback"
            else
                state.animation_last_reason = "started"
            end
        else
            if err == "lease-rejected" then state.animation_started[key] = previous end
            state.animation_last_reason = "task-start-failed"
        end
        return started
    end

    function Messiah.StopAnimation(ped, spec)
        local state = Messiah.State()
        local lease = state.ped_lease
        if spec and Messiah.ActivationContextCurrent(state, state.activation_epoch)
            and lease and lease.handle == Messiah.NormalizeEntityHandle(ped) then
            return Messiah.LeaseInvoke(lease, "void", "STOP_ANIM_TASK",
                H.STOP_ANIM_TASK, ped, spec.dict, spec.name, -4.0) == true
        end
        return false
    end

    function Messiah.ClearOwnedActionAnimation(ped, kind, reason)
        local state = Messiah.State()
        kind = tostring(kind or state.animation_current or "none")
        if kind == "none" or kind == "idle" then return true end
        local spec = Messiah.AnimationSpec(kind)
        if not spec then return true end
        local key = spec.dict .. "\0" .. spec.name
        local owned = state.animation_started[key] ~= nil or state.animation_current == kind
        if not owned then return true end
        local exact_stop = Messiah.StopAnimation(ped, spec)
        local playing_after_exact = entity_exists(ped) and H.IS_ENTITY_PLAYING_ANIM
            and invoke_bool(H.IS_ENTITY_PLAYING_ANIM, ped, spec.dict, spec.name, 3) or false
        local secondary_clear = false
        if playing_after_exact and H.CLEAR_PED_SECONDARY_TASK and entity_exists(ped) then
            -- All Messiah action clips are confined to the secondary slot. This
            -- fallback is therefore owned and cannot clear the primary stance.
            secondary_clear = invoke_void(H.CLEAR_PED_SECONDARY_TASK, ped) == true
        end
        local playing_after = entity_exists(ped) and H.IS_ENTITY_PLAYING_ANIM
            and invoke_bool(H.IS_ENTITY_PLAYING_ANIM, ped, spec.dict, spec.name, 3) or false
        local cleared = not playing_after
        if cleared then
            state.animation_started[key] = nil
            if state.animation_current == kind then state.animation_current = "none" end
        end
        state.animation_next_check_ms = 0
        Messiah.LogOnce("action-animation-cleanup:" .. kind .. ":" .. tostring(reason),
            ("Messiah action animation cleanup: activation=%d kind=%s reason=%s "
                .. "exactStopAccepted=%s playingAfterExact=%s secondaryClearAccepted=%s "
                .. "playingAfter=%s ownershipRetained=%s.")
            :format(state.activation_id, kind, tostring(reason or "unspecified"),
                tostring(exact_stop), tostring(playing_after_exact),
                tostring(secondary_clear), tostring(playing_after), tostring(not cleared)))
        return cleared
    end

    function Messiah.ReassertIdleStance(now, reason)
        local state = Messiah.State()
        local idle = Messiah.AnimationSpec("idle")
        local lease = state.ped_lease
        if state.gameplay_owner == true and not state.ending and not state.restoring
            and idle and lease and lease.handle == state.ped
            and Messiah.ValidateEntityLease(lease, "idle-reassert-readback", "none") then
            local playing = Messiah.LeaseInvoke(lease, "bool", "IS_ENTITY_PLAYING_ANIM",
                H.IS_ENTITY_PLAYING_ANIM, state.ped, idle.dict, idle.name, 3)
            if playing == true then
                state.stance_started, state.idle_task_pending = true, false
                state.idle_task_started_ms = 0
                state.animation_next_check_ms = (tonumber(now) or now_ms()) + Messiah.ANIM_REPAIR_INTERVAL_MS
                return true
            end
        end
        state.stance_started = false
        state.idle_task_pending = false
        state.idle_task_started_ms = 0
        state.animation_next_check_ms = tonumber(now) or now_ms()
        state.animation_repairs = 0
        Messiah.LogOnce("idle-reassert:" .. tostring(state.action_serial) .. ":" .. tostring(reason),
            ("Messiah idle stance reassert queued: activation=%d reason=%s owner=gameplay-tick.")
            :format(state.activation_id, tostring(reason or "action-complete")))
        return false
    end

    function Messiah.UpdateAnimation(ped, now)
        local state = Messiah.State()
        if not Messiah.ActivationContextCurrent(state, state.activation_epoch) then return false end
        if state.idle_candidates_exhausted and state.action == nil
            and (state.phase == Messiah.PHASES.IDLE_HOVER or state.phase == Messiah.PHASES.GLIDING)
            and now >= (state.idle_retry_ms or math.huge) and (state.idle_retry_passes or 0) < 2 then
            state.idle_retry_passes = (state.idle_retry_passes or 0) + 1
            state.idle_candidate_index, state.idle_candidates_exhausted = 1, false
            Messiah.ReassertIdleStance(now, "delayed-idle-retry")
        end
        local idle = Messiah.AnimationSpec("idle")
        -- The held Lance owns one looping upper-body secondary clip. Monitor
        -- the upright primary underneath it without restarting either each frame.
        local monitor_idle = state.action == nil
            or state.phase == Messiah.PHASES.LANCE_CHANNEL
        if not monitor_idle then
            -- Short upper-body action clips own their secondary slot; defer the
            -- idle watchdog until recovery so it never fights a cast task.
            state.animation_next_check_ms = now + Messiah.ANIM_REPAIR_INTERVAL_MS
        elseif not state.idle_candidates_exhausted and idle
            and invoke_bool(H.HAS_ANIM_DICT_LOADED, idle.dict) then
            if not state.stance_started then
                local playing = H.IS_ENTITY_PLAYING_ANIM
                    and invoke_bool(H.IS_ENTITY_PLAYING_ANIM, ped, idle.dict, idle.name, 3) or false
                if playing then
                    state.stance_started = true
                    state.idle_task_pending = false
                    state.idle_task_started_ms = 0
                    state.animation_last_reason = "playback-confirmed"
                    Messiah.Trace(("Messiah idle animation confirmed: activation=%d reason=playback-readback "
                            .. "slot=primary-loop flags=%d dict=%s clip=%s candidate=%d source=%s.")
                        :format(state.activation_id, idle.flags, idle.dict, idle.name,
                            state.idle_candidate_index, tostring(idle.source or "unspecified")))
                elseif state.idle_task_pending
                    and now - state.idle_task_started_ms < Messiah.ANIM_CONFIRM_TIMEOUT_MS then
                    -- TASK_PLAY_ANIM is asynchronous; allow one bounded readback window.
                elseif state.idle_task_pending then
                    Messiah.LogOnce("idle-animation-readback-failed:" .. tostring(state.idle_candidate_index),
                        ("Messiah idle animation unavailable: activation=%d reason=playback-not-confirmed "
                            .. "timeoutMs=%d dict=%s clip=%s candidate=%d.")
                        :format(state.activation_id, Messiah.ANIM_CONFIRM_TIMEOUT_MS,
                            idle.dict, idle.name, state.idle_candidate_index))
                    Messiah.AdvanceIdleCandidate("playback-not-confirmed")
                elseif Messiah.PlayAnimation(ped, "idle", idle) then
                    Messiah.Trace(("Messiah idle animation requested: activation=%d reason=initial-start "
                            .. "slot=primary-loop flags=%d dict=%s clip=%s candidate=%d source=%s "
                            .. "playbackReadback=pending.")
                        :format(state.activation_id, idle.flags, idle.dict, idle.name,
                            state.idle_candidate_index, tostring(idle.source or "unspecified")))
                else
                    Messiah.LogOnce("idle-animation-start-failed",
                        ("Messiah idle animation unavailable: activation=%d reason=%s "
                            .. "dict_ready=true dict=%s clip=%s.")
                        :format(state.activation_id, state.animation_last_reason,
                            idle.dict, idle.name))
                    Messiah.AdvanceIdleCandidate("task-start-failed")
                end
                state.animation_next_check_ms = now + Messiah.ANIM_REPAIR_INTERVAL_MS
            elseif now >= state.animation_next_check_ms then
                state.animation_next_check_ms = now + Messiah.ANIM_REPAIR_INTERVAL_MS
                if not invoke_bool(H.IS_ENTITY_PLAYING_ANIM, ped, idle.dict, idle.name, 3) then
                    state.animation_last_reason = "clip-stopped"
                    state.stance_started = false
                    state.idle_task_pending = false
                    if state.animation_repairs < Messiah.ANIM_MAX_REPAIRS then
                        state.animation_repairs = state.animation_repairs + 1
                        if Messiah.PlayAnimation(ped, "idle", idle) then
                            Messiah.Trace(("Messiah idle animation recovered: activation=%d reason=clip-stopped "
                                    .. "phase=%s repair=%d/%d slot=primary-loop dict=%s clip=%s.")
                                :format(state.activation_id, state.phase, state.animation_repairs,
                                    Messiah.ANIM_MAX_REPAIRS, idle.dict, idle.name))
                        else
                            Messiah.LogOnce("idle-animation-repair-failed:"
                                .. tostring(state.animation_repairs),
                                ("Messiah idle animation repair failed: activation=%d reason=%s "
                                    .. "attempt=%d/%d dict_ready=true dict=%s clip=%s.")
                                :format(state.activation_id, state.animation_last_reason,
                                    state.animation_repairs, Messiah.ANIM_MAX_REPAIRS,
                                    idle.dict, idle.name))
                        end
                    else
                        Messiah.AdvanceIdleCandidate("clip-stopped-repairs-exhausted")
                    end
                end
            end
        elseif monitor_idle and not state.idle_candidates_exhausted
            and now >= state.asset_deadline_ms then
            Messiah.LogOnce("idle-animation-timeout",
                ("Messiah idle animation unavailable: activation=%d reason=dict-not-ready "
                    .. "dict=%s clip=%s timeout=true requested=%s.")
                :format(state.activation_id, idle and idle.dict or "none",
                    idle and idle.name or "none",
                    tostring(idle and state.anim_requested[idle.dict] == true)))
            Messiah.AdvanceIdleCandidate("dict-not-ready-timeout")
        end

        local desired = "none"
        if state.action and not (state.action.ability == "LANCE" and state.action.ending == true)
            and (string.find(state.phase, "_WINDUP", 1, true)
                or string.find(state.phase, "_RELEASE", 1, true)
                or state.phase == Messiah.PHASES.LANCE_CHANNEL) then
            desired = (Messiah.ABILITIES[state.action.ability] or {}).animation or "orb"
        end
        if desired == state.animation_current then return end
        if state.animation_current ~= "none" then
            if not Messiah.ClearOwnedActionAnimation(
                    ped, state.animation_current, "animation-owner-transition") then
                return
            end
        end
        if desired == "none" then
            state.animation_current = "none"
        else
            local spec = Messiah.AnimationSpec(desired)
            if Messiah.PlayAnimation(ped, desired, spec) then
                state.animation_current = desired
            else
                state.animation_current = "none"
                Messiah.LogOnce("action-animation:" .. desired,
                    ("Messiah action animation unavailable: activation=%d kind=%s reason=%s "
                        .. "dict=%s clip=%s.")
                    :format(state.activation_id, desired, state.animation_last_reason,
                        spec and spec.dict or "none", spec and spec.name or "none"))
            end
        end
    end

    -- Host callbacks may synchronously cancel or replace an activation. These
    -- checks are native-free and never normalize/create a new State while an
    -- old call stack is unwinding.
    function Messiah.ActivationContextCurrent(state, epoch)
        return type(state) == "table" and State.messiah == state
            and state.activation_epoch == epoch and state.active == true
            and state.gameplay_owner == true and state.ending ~= true
            and state.restoring ~= true and state.disposed ~= true
            and state.cleanup_owner ~= true and state.cleanup_failed ~= true
    end

    function Messiah.ActionContextCurrent(state, epoch, action, ability, allow_ending)
        return Messiah.ActivationContextCurrent(state, epoch)
            and type(action) == "table" and state.action == action
            and action.epoch == epoch and action.ability == ability
            and (allow_ending == true or action.ending ~= true)
    end

    function Messiah.Explode(x, y, z, size_scale, no_damage, no_fx, profile_name, make_sound)
        local state = Messiah.State()
        local epoch, frame, action = state.activation_epoch, state.entity_frame, state.action
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame and state.action == action
        end
        if not current() then return false, "not-gameplay-owner" end
        if not Messiah.EntityOwner() or state.ending or state.restoring then return false, "not-gameplay-owner" end
        local online = Messiah.FxOnline()
        if not current() then return false, "activation-context-changed" end
        if online == nil then return false, "session-status-unknown" end
        local position = Messiah.CopyPoint({ x = x, y = y, z = z })
        if not position or math.abs(position.x) > 20000 or math.abs(position.y) > 20000
            or position.z < -2000 or position.z > 10000 then
            return false, "invalid-position"
        end
        if not (Live.ExplosionArgs and type(Live.ExplosionArgs.New) == "function"
                and Live.V3 and type(Live.V3.New) == "function" and Live.ExplosionTag
                and gta and type(gta.AddExplosion) == "function") then
            return false, "backend-unavailable"
        end
        local profile = Messiah.IMPACT_PROFILES[tostring(profile_name)]
        local tag_name = profile and profile.blast_tag
        local tag = tag_name and Live.ExplosionTag[tag_name]
        if tag == nil then return false, "explosion-tag-unavailable" end
        local lease = state.ped_lease
        if not lease or lease.handle ~= state.ped
            or not Messiah.ValidateEntityLease(lease, "blast-owner", "GTA.AddExplosion") then
            return false, "owner-lease-unavailable"
        end
        local pointer_ok, owner = pcall(gta.HandleToPointer, lease.handle)
        if not current() then return false, "activation-context-changed" end
        if not pointer_ok or owner == nil then return false, "owner-pointer-unavailable" end
        local address_ok, address = pcall(function() return owner:GetAddress() end)
        if not current() then return false, "activation-context-changed" end
        if not address_ok or ("physical:%s"):format(tostring(address)) ~= lease.identity_key then
            return false, "owner-identity-changed"
        end
        local scale = Messiah.FiniteNumber(size_scale)
        if not scale then return false, "invalid-size" end
        local ok, args = pcall(function()
            local value = Live.ExplosionArgs.New(tag, Live.V3.New(position.x, position.y, position.z))
            value.WeaponHash = utils.Joaat(profile.blast_weapon or "WEAPON_RPG")
            value.IsLocalOnly = online == false
            value.NoDamage = no_damage == true
            -- Damage/impulse is independent of the shared energy presentation.
            value.NoFx = true
            value.MakeSound = false
            value.DisableDamagingOwner = true
            value.EntExplosionOwner, value.EntIgnoreDamage = owner, owner
            value.SizeScale = clamp(scale, 0.5, 6.0)
            value.CamShake = 0.0
            return value
        end)
        if not current() then return false, "activation-context-changed" end
        if not ok or not args then return false, "argument-construction-failed" end
        -- Revalidate the owner immediately before entering the host. A blast
        -- can destroy arbitrary nearby victims: revoke every borrowed lease
        -- generation BEFORE it runs, including any outstanding shape GUID.
        if not Messiah.ValidateEntityLease(lease, "GTA.AddExplosion", "documented-api") then
            return false, "owner-changed-before-blast"
        end
        if not current() then return false, "activation-context-changed" end
        state.blast_generation = (tonumber(state.blast_generation) or 0) + 1
        local added_ok, added = pcall(gta.AddExplosion, args)
        if not current() then return false, "activation-context-changed" end
        if not added_ok then return false, "host-error" end
        if added == true then return true, "accepted" end
        if added == false then return false, "host-rejected" end
        -- nil, numbers, strings and any other unexpected return are uncertain:
        -- the host may already have applied damage, so they never authorize a retry.
        return false, "host-uncertain"
    end

    function Messiah.CopyPoint(point)
        if type(point) ~= "table" then return nil end
        local x, y, z = tonumber(point.x), tonumber(point.y), tonumber(point.z)
        if not x or not y or not z or x ~= x or y ~= y or z ~= z
            or x == math.huge or x == -math.huge
            or y == math.huge or y == -math.huge
            or z == math.huge or z == -math.huge then
            return nil
        end
        local entity, entity_classification = Messiah.NormalizeEntityHandle(point.entity)
        if entity == 0 and point.entity_classification ~= nil
            and tostring(point.entity_classification) ~= "none" then
            entity_classification = tostring(point.entity_classification)
        end
        return {
            x = x,
            y = y,
            z = z,
            entity = entity,
            entity_raw = point.entity_raw ~= nil and point.entity_raw or point.entity,
            entity_classification = entity_classification,
            entity_lease = point.entity_lease,
            mode = point.mode,
            source = point.source
        }
    end

    function Messiah.VehicleHasPlayer(vehicle, lease)
        if lease and lease.handle ~= Messiah.NormalizeEntityHandle(vehicle) then return false, false end
        lease = lease or Messiah.AcquireEntityLease(vehicle, "vehicle", { source = "player-filter" })
        if not lease then return false, false end
        local seat_value, seat_raw, seat_error = Messiah.LeaseInvoke(lease, "int",
            "GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS", H.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS, lease.handle)
        if seat_error or type(seat_raw) ~= "number" then return false, false end
        local seats = math.max(0, math.min(15, tonumber(seat_value) or 0))
        for seat = -1, seats - 1 do
            local occupant, raw, err = Messiah.LeaseInvoke(lease, "int", "GET_PED_IN_VEHICLE_SEAT",
                H.GET_PED_IN_VEHICLE_SEAT, lease.handle, seat, false)
            if err or type(raw) ~= "number" then return false, false end
            occupant = Messiah.NormalizeEntityHandle(occupant)
            if occupant ~= 0 then
                local is_player, known = Messiah.PedPlayerStatus(occupant)
                if not known then return false, false end
                if is_player then return true, true end
            end
        end
        return false, true
    end

    function Messiah.PedPlayerStatus(ped, lease)
        if lease and lease.handle ~= Messiah.NormalizeEntityHandle(ped) then return false, false end
        lease = lease or Messiah.AcquireEntityLease(ped, "ped", { source = "player-filter", owned = true })
        if not lease then return false, false end
        local value, raw, err = Messiah.LeaseInvoke(lease, "bool", "IS_PED_A_PLAYER", H.IS_PED_A_PLAYER, lease.handle)
        if err or (type(raw) ~= "boolean" and type(raw) ~= "number") then return false, false end
        return value == true, true
    end

    function Messiah.EntityDamageKind(handle, fallback, lease)
        if lease and lease.handle ~= Messiah.NormalizeEntityHandle(handle) then return "unknown" end
        lease = lease or Messiah.AcquireEntityLease(handle, fallback, { source = "classification" })
        if not lease or not Messiah.ValidateEntityLease(lease, "kind-consumer", "none") then
            return "unknown"
        end
        return lease.kind
    end

    function Messiah.ReadDamageState(handle, kind, lease)
        lease = lease or Messiah.AcquireEntityLease(handle, kind, { source = "damage-readback" })
        local snapshot = {
            handle = Messiah.NormalizeEntityHandle(handle),
            kind = tostring(kind or "unknown"),
            exists = false,
            exists_known = false,
            destroyed_known = false,
            driveable_known = false,
            errors = {}
        }
        if not lease or lease.handle ~= snapshot.handle
            or not Messiah.ValidateEntityLease(lease, "readback-start", "none") then
            snapshot.errors[1] = "lease-rejected"
            if lease and (lease.reason == "observed-destroyed"
                    or lease.reason == "observed-non-driveable") then
                -- The guard itself safely observed this transition. A terminal
                -- invocation alone never counts as an observed destruction.
                snapshot.destroyed, snapshot.destroyed_known = true, true
                if lease.kind == "vehicle" then
                    snapshot.driveable, snapshot.driveable_known = false, true
                end
            end
            return snapshot
        end
        snapshot.kind, snapshot.exists, snapshot.exists_known = lease.kind, true, true
        snapshot.destroyed, snapshot.destroyed_known = false, true
        if lease.kind == "vehicle" then snapshot.driveable, snapshot.driveable_known = true, true end
        local function read(field, return_kind, name, hash, ...)
            if lease.state ~= "live" then return end
            local value, raw, err = Messiah.LeaseInvoke(lease, return_kind, name, hash, lease.handle, ...)
            if err or (type(raw) ~= "number" and type(raw) ~= "boolean") then
                snapshot.errors[#snapshot.errors + 1] = name .. ":" .. tostring(err or "invalid-return")
            else
                snapshot[field] = value
            end
        end
        read("damageable", "bool", "GET_ENTITY_CAN_BE_DAMAGED", H.GET_ENTITY_CAN_BE_DAMAGED)
        read("health", "int", "GET_ENTITY_HEALTH", H.GET_ENTITY_HEALTH)
        if lease.kind == "ped" then
            read("armour", "int", "GET_PED_ARMOUR", H.GET_PED_ARMOUR)
        elseif lease.kind == "vehicle" then
            read("body", "float", "GET_VEHICLE_BODY_HEALTH", H.GET_VEHICLE_BODY_HEALTH)
            read("engine", "float", "GET_VEHICLE_ENGINE_HEALTH", H.GET_VEHICLE_ENGINE_HEALTH)
            read("tank", "float", "GET_VEHICLE_PETROL_TANK_HEALTH", H.GET_VEHICLE_PETROL_TANK_HEALTH)
        end
        if lease.state ~= "live" then
            snapshot.exists, snapshot.exists_known = nil, false
            if lease.identity and lease.identity.terminal then
                snapshot.destroyed, snapshot.destroyed_known = true, true
                if lease.kind == "vehicle" then snapshot.driveable, snapshot.driveable_known = false, true end
            end
        end
        return snapshot
    end

    function Messiah.DamageStateText(snapshot)
        snapshot = type(snapshot) == "table" and snapshot or {}
        local function number(value)
            return value == nil and "n/a" or ("%.2f"):format(tonumber(value) or 0.0)
        end
        return ("exists=%s/%s damageable=%s health=%s armour=%s body=%s engine=%s tank=%s "
                .. "driveable=%s/%s destroyed=%s/%s errors=%d")
            :format(tostring(snapshot.exists), tostring(snapshot.exists_known == true),
                tostring(snapshot.damageable),
                number(snapshot.health), number(snapshot.armour), number(snapshot.body),
                number(snapshot.engine), number(snapshot.tank), tostring(snapshot.driveable),
                tostring(snapshot.driveable_known == true), tostring(snapshot.destroyed),
                tostring(snapshot.destroyed_known == true), #(snapshot.errors or {}))
    end

    function Messiah.AcquireDamageControl(handle, lease, request_interval_ms)
        local state = Messiah.EntityState()
        local epoch = state.activation_epoch
        local function current()
            return State.messiah == state and state.activation_epoch == epoch and Messiah.EntityOwner(lease)
        end
        local normalized = Messiah.NormalizeEntityHandle(handle)
        if lease and lease.handle ~= normalized then
            return { before = false, after = false, requested = false, control_known = false }
        end
        lease = lease or Messiah.AcquireEntityLease(handle, nil, { source = "control" })
        local result = {
            session_active = false,
            session_known = false,
            control_known = false,
            before = false,
            requested = false,
            after = false,
            rate_limited = false
        }
        if not current() or not lease or not Messiah.ValidateEntityLease(lease, "NETWORK_IS_SESSION_ACTIVE", H.NETWORK_IS_SESSION_ACTIVE)
            or not current() then
            return result
        end
        local active, raw, err = invoke_bool_detail(H.NETWORK_IS_SESSION_ACTIVE)
        if not current() then return result end
        result.session_known = err == nil and (type(raw) == "boolean" or type(raw) == "number")
        result.session_active = active == true
        if not result.session_known then return result end
        if active ~= true then
            result.after = Messiah.ValidateEntityLease(lease, "offline-control", "none")
            result.before, result.control_known = result.after, result.after
            return result
        end
        local value, control_raw, control_err = Messiah.LeaseInvoke(lease, "bool",
            "NETWORK_HAS_CONTROL_OF_ENTITY", H.NETWORK_HAS_CONTROL_OF_ENTITY, lease.handle)
        if not current() then return result end
        result.control_known = control_err == nil and (type(control_raw) == "boolean" or type(control_raw) == "number")
        result.before, result.after = result.control_known and value == true, result.control_known and value == true
        if result.after or lease.state ~= "live" then return result end
        local key, now = lease.action_key, now_ms()
        local previous = state.impact_control_attempt_ms[key]
        -- Ordinary attacks keep their existing backoff. E explicitly supplies a
        -- bounded shorter interval so a denied request can retry inside its
        -- 180 ms crossing grace. Ownership readback still runs every frame.
        local interval = Messiah.IMPACT_CONTROL_RETRY_MS
        if request_interval_ms == Messiah.SHOCKWAVE_CONTROL_REQUEST_MS
            and lease.ability == "SHOCKWAVE" then
            interval = request_interval_ms
        end
        if previous and now - previous < interval then
            result.rate_limited = true; return result
        end
        if not previous then
            state.impact_control_attempt_order[#state.impact_control_attempt_order + 1] = key
            if #state.impact_control_attempt_order > Messiah.MAX_IMPACT_CONTROL_RECORDS then
                state.impact_control_attempt_ms[table.remove(state.impact_control_attempt_order, 1)] = nil
            end
        end
        state.impact_control_attempt_ms[key] = now
        result.requested = true
        local _, request_raw, request_err = Messiah.LeaseInvoke(lease, "bool",
            "NETWORK_REQUEST_CONTROL_OF_ENTITY", H.NETWORK_REQUEST_CONTROL_OF_ENTITY, lease.handle)
        if not current() then return result end
        if lease.ability == "SHOCKWAVE" and (request_err ~= nil
                or (type(request_raw) ~= "boolean" and type(request_raw) ~= "number")) then
            result.control_known = false; result.request_uncertain = true; return result
        end
        local after, after_raw, after_err = Messiah.LeaseInvoke(lease, "bool",
            "NETWORK_HAS_CONTROL_OF_ENTITY", H.NETWORK_HAS_CONTROL_OF_ENTITY, lease.handle)
        if not current() then return result end
        result.after = after_err == nil and (type(after_raw) == "boolean" or type(after_raw) == "number") and
            after == true
        return result
    end

    function Messiah.ObservedDamage(before, after, requested)
        before = type(before) == "table" and before or {}
        after = type(after) == "table" and after or {}
        requested = math.max(0.0, tonumber(requested) or 0.0)
        if before.exists_known == true and after.exists_known == true
            and before.exists == true and after.exists == false then
            return requested
        end
        if before.destroyed_known == true and after.destroyed_known == true
            and before.destroyed == false and after.destroyed == true then
            return requested
        end
        if before.driveable_known == true and after.driveable_known == true
            and before.driveable == true and after.driveable == false then
            return requested
        end
        local function drop(field)
            local before_value, after_value = tonumber(before[field]), tonumber(after[field])
            if before_value == nil or after_value == nil then return 0.0 end
            return math.max(0.0, before_value - after_value)
        end
        local kind = tostring(before.kind or after.kind or "unknown")
        if kind == "ped" then
            return drop("health") + drop("armour")
        elseif kind == "vehicle" then
            return math.max(drop("health"), drop("body"), drop("engine"), drop("tank"))
        end
        return drop("health")
    end

    function Messiah.RecordDamageEvidence(result, context)
        local state = Messiah.State()
        result = type(result) == "table" and result or {}
        context = type(context) == "table" and context or {}
        local action_serial = tonumber(context.action_serial) or 0
        local profile_name = tostring(context.profile_name or "UNKNOWN")
        local kind = tostring(result.kind or "unknown")
        local key = table.concat({ tostring(state.activation_epoch), tostring(action_serial),
            tostring(result.identity_key or "unresolved"), profile_name, kind }, ":")
        local bucket = state.damage_evidence[key]
        if not bucket then
            bucket = {
                key = key,
                action_serial = action_serial,
                profile_name = profile_name,
                kind = kind,
                attempts = 0,
                verified = 0,
                requested = 0.0,
                observed = 0.0,
                control_denied = 0,
                terminal_attempts = 0,
                terminal_accepted = 0,
                terminal_verified = 0,
                backends = {},
                first = result,
                last = result,
            }
            state.damage_evidence[key] = bucket
            state.damage_evidence_order[#state.damage_evidence_order + 1] = key
        end
        bucket.attempts = bucket.attempts + 1
        bucket.requested = bucket.requested + (tonumber(result.requested) or 0.0)
        bucket.observed = bucket.observed + (tonumber(result.observed) or 0.0)
        if result.verified == true then bucket.verified = bucket.verified + 1 end
        if result.control_after ~= true then bucket.control_denied = bucket.control_denied + 1 end
        if result.terminal_attempted == true then bucket.terminal_attempts = bucket.terminal_attempts + 1 end
        if result.terminal_accepted == true then bucket.terminal_accepted = bucket.terminal_accepted + 1 end
        if result.terminal_verified == true then bucket.terminal_verified = bucket.terminal_verified + 1 end
        bucket.backends[tostring(result.backend or "none")] = true
        bucket.last = result
        if bucket.attempts == 1 then
            local call_parts = {}
            for _, call in ipairs(result.native_calls or {}) do
                call_parts[#call_parts + 1] = ("%s[%s]=%s raw=%s error=%s")
                    :format(tostring(call.name), tostring(call.hash), tostring(call.ok == true),
                        Messiah.RawValue(call.raw), tostring(call.error or "none"))
            end
            log_info(("Messiah damage evidence: activation=%d actionSerial=%d action=%s "
                    .. "profile=%s handle=%s kind=%s requested=%.2f observed=%.2f verified=%s "
                    .. "control={before=%s requested=%s after=%s owner=%s pending=%s} "
                    .. "backend=%s nativeCalls={%s} before={%s} after={%s}.")
                :format(state.activation_id, action_serial, tostring(context.action or "unspecified"),
                    profile_name, tostring(result.handle), kind,
                    tonumber(result.requested) or 0.0, tonumber(result.observed) or 0.0,
                    tostring(result.verified == true), tostring(result.control_before == true),
                    tostring(result.control_requested == true), tostring(result.control_after == true),
                    tostring(result.control_owner), tostring(result.control_pending),
                    tostring(result.backend or "none"),
                    #call_parts > 0 and table.concat(call_parts, ";") or "none",
                    Messiah.DamageStateText(result.before), Messiah.DamageStateText(result.after)))
        end
        return bucket
    end

    function Messiah.FlushDamageEvidence(action_serial, reason)
        local state = Messiah.State()
        action_serial = tonumber(action_serial)
        local flushed = 0
        for index = #state.damage_evidence_order, 1, -1 do
            local key = state.damage_evidence_order[index]
            local bucket = state.damage_evidence[key]
            if bucket and (action_serial == nil or bucket.action_serial == action_serial) then
                local backend_names = {}
                for backend in pairs(bucket.backends) do backend_names[#backend_names + 1] = backend end
                table.sort(backend_names)
                log_info(("Messiah damage summary: activation=%d actionSerial=%d profile=%s kind=%s "
                        .. "attempts=%d verified=%d requested=%.2f observed=%.2f controlDenied=%d "
                        .. "terminal={attempted=%d accepted=%d verified=%d} "
                        .. "backends=%s reason=%s lastAfter={%s}.")
                    :format(state.activation_id, bucket.action_serial, bucket.profile_name, bucket.kind,
                        bucket.attempts, bucket.verified, bucket.requested, bucket.observed,
                        bucket.control_denied, bucket.terminal_attempts, bucket.terminal_accepted,
                        bucket.terminal_verified,
                        #backend_names > 0 and table.concat(backend_names, "+") or "none",
                        tostring(reason or "impact-complete"), Messiah.DamageStateText(bucket.last.after)))
                state.damage_evidence[key] = nil
                table.remove(state.damage_evidence_order, index)
                flushed = flushed + 1
            end
        end
        return flushed
    end

    function Messiah.ClaimTerminalVehicle(action_serial, lease, maximum)
        local state = Messiah.State()
        maximum = math.max(0, math.floor(tonumber(maximum) or 0))
        if type(lease) ~= "table" or lease.state ~= "live" or lease.identity.terminal
            or tonumber(action_serial) ~= lease.action_serial or maximum == 0 then
            return false, "invalid-lease"
        end
        local key = lease.action_key
        if state.terminal_vehicle_registry[key] then return false, "deduped" end
        local used = tonumber(state.terminal_vehicle_counts[action_serial]) or 0
        if lease.ability ~= "LANCE" and used >= maximum then return false, "action-cap" end
        if #state.terminal_vehicle_order >= Messiah.MAX_TERMINAL_VEHICLE_CLAIMS then return false, "registry-capacity" end
        state.terminal_vehicle_registry[key] = true
        state.terminal_vehicle_counts[action_serial] = used + 1
        state.terminal_vehicle_order[#state.terminal_vehicle_order + 1] = { key = key, action_serial = action_serial }
        return true, "claimed"
    end

    function Messiah.MaybeTerminalVehicle(result, profile, context)
        result = type(result) == "table" and result or {}
        profile = type(profile) == "table" and profile or {}
        context = type(context) == "table" and context or {}
        result.terminal_attempted, result.terminal_accepted, result.terminal_verified = false, false, false
        if not result.lease or result.lease.handle ~= Messiah.NormalizeEntityHandle(result.handle)
            or not Messiah.EntityContextMatches(result.lease, context) then
            return false
        end
        if result.kind ~= "vehicle" or profile.terminal_vehicle ~= true
            or context.allow_terminal == false or result.control_after ~= true
            or not H.EXPLODE_VEHICLE then
            return false
        end
        local after = type(result.after) == "table" and result.after or {}
        if after.exists ~= true or after.destroyed == true then return false end
        local thresholds = {
            { field = "health", limit = tonumber(profile.terminal_health) },
            { field = "body",   limit = tonumber(profile.terminal_body) },
            { field = "engine", limit = tonumber(profile.terminal_engine) },
            { field = "tank",   limit = tonumber(profile.terminal_tank) },
        }
        local reason = nil
        for _, threshold in ipairs(thresholds) do
            local value = tonumber(after[threshold.field])
            if value ~= nil and threshold.limit ~= nil and value <= threshold.limit then
                reason = ("%s=%.2f<=%.2f"):format(threshold.field, value, threshold.limit)
                break
            end
        end
        if not reason then return false end
        local claimed, claim_reason = Messiah.ClaimTerminalVehicle(
            context.action_serial, result.lease, profile.max_terminal_vehicles)
        if not claimed then
            result.terminal_claim = claim_reason
            return false
        end
        result.terminal_attempted = true
        result.terminal_claim = claim_reason
        local terminal_before = result.after
        result.terminal_before = terminal_before
        local lease = result.lease
        if not Messiah.ValidateEntityLease(lease, "EXPLODE_VEHICLE", "0xBA71116ADF5B514C") then return false end
        -- Retire before entering the terminal call: even a host-side failure can
        -- have invalidated the target. Outcome is pending, never read on this GUID.
        Messiah.RetireEntityLease(lease, "terminal-invocation", true)
        local accepted, raw, err = invoke_void_detail(H.EXPLODE_VEHICLE, result.handle, false, true)
        result.terminal_accepted = accepted == true
        result.native_calls[#result.native_calls + 1] = {
            name = "EXPLODE_VEHICLE",
            hash = "0xBA71116ADF5B514C",
            ok = accepted == true,
            raw = raw,
            error = err,
        }
        result.invoked = result.invoked == true or accepted == true
        result.backend = tostring(result.backend or "none") .. "+EXPLODE_VEHICLE(hidden):"
            .. (accepted == true and "call-ok" or "call-error")
        result.terminal_verified = false
        result.terminal_outcome = "pending-unverified-no-post-terminal-readback"
        log_info(("Messiah terminal vehicle pulse: activation=%d actionSerial=%d action=%s "
                .. "profile=%s handle=%s identity=%s reason=%s native=EXPLODE_VEHICLE/0xBA71116ADF5B514C "
                .. "args={isAudible=false,isInvisible=true} accepted=%s raw=%s error=%s "
                .. "outcomeVerified=%s preDirect={%s} preTerminal={%s} after={%s}.")
            :format(Messiah.State().activation_id, tonumber(context.action_serial) or 0,
                tostring(context.action or "unspecified"),
                tostring(context.profile_name or "UNKNOWN"), tostring(result.handle), tostring(lease.identity_key),
                reason,
                tostring(accepted == true), Messiah.RawValue(raw), tostring(err or "none"),
                tostring(result.terminal_verified == true),
                Messiah.DamageStateText(result.before), Messiah.DamageStateText(terminal_before),
                Messiah.DamageStateText(result.after)))
        return accepted == true
    end

    function Messiah.ApplyDirectDamage(handle, kind, amount, context)
        local raw_handle = handle
        local classification
        handle, classification = Messiah.NormalizeEntityHandle(handle)
        amount = math.max(0, math.floor(tonumber(amount) or 0))
        context = type(context) == "table" and context or {}
        if context.lease and (context.lease.handle ~= handle
                or not Messiah.EntityContextMatches(context.lease, context)) then
            return {
                handle = handle,
                kind = tostring(kind or "unknown"),
                requested = amount,
                observed = 0.0,
                invoked = false,
                verified = false,
                backend = "rejected-action-epoch",
                native_calls = {}
            }
        end
        Messiah.ReportRejectedEntityHandle("ApplyDirectDamage", raw_handle,
            classification, "DOES_ENTITY_EXIST/0x7239B21A38F536BA",
            "direct damage rejected before classification/readback")
        local lease = context.lease or Messiah.AcquireEntityLease(handle, kind, context)
        kind = lease and lease.kind or "unknown"
        local control = type(context.control) == "table"
            and context.control or Messiah.AcquireDamageControl(handle, lease)
        local result = {
            handle = handle,
            kind = kind,
            lease = lease,
            identity_key = lease and lease.identity_key,
            requested = amount,
            observed = 0.0,
            verified = false,
            invoked = false,
            backend = "none",
            native_calls = {},
            control_before = control.before == true,
            control_requested = control.requested == true,
            control_after = control.after == true,
            control_owner = control.owner,
            control_pending = control.pending,
        }
        result.before = Messiah.ReadDamageState(handle, kind, lease)
        result.after = result.before
        local function mirror_readbacks()
            local before = type(result.before) == "table" and result.before or {}
            local after = type(result.after) == "table" and result.after or {}
            result.before_health, result.after_health = before.health, after.health
            result.before_armour, result.after_armour = before.armour, after.armour
            result.before_body, result.after_body = before.body, after.body
            result.before_engine, result.after_engine = before.engine, after.engine
            result.before_tank, result.after_tank = before.tank, after.tank
            result.driveable_before, result.driveable_after = before.driveable, after.driveable
            result.exists_before, result.exists_after = before.exists == true, after.exists == true
            result.destroyed_before = before.destroyed == true
            result.destroyed_after = after.destroyed == true
        end
        mirror_readbacks()
        if not lease or handle == 0 or amount <= 0 or result.before.exists ~= true then
            result.backend = "rejected-invalid-target"
            mirror_readbacks()
            Messiah.RecordDamageEvidence(result, context)
            return result
        end
        if result.before.damageable == false then
            result.backend = "rejected-not-damageable"
            mirror_readbacks()
            Messiah.RecordDamageEvidence(result, context)
            return result
        end
        if result.control_after ~= true then
            result.backend = "rejected-no-control"
            mirror_readbacks()
            Messiah.RecordDamageEvidence(result, context)
            return result
        end

        local profile = type(context.profile) == "table" and context.profile or {}
        -- Attribute direct energy damage to the railgun family. The former
        -- impulse-weapon hash could leak its stock identity into custom hits.
        local weapon = utils.Joaat("WEAPON_RAILGUNXM3")
        -- Damage may execute from a scheduled impact while the local player is
        -- changing peds.  Capture one normalized attribution owner so a fresh
        -- GET_PLAYER_PED_SCRIPT_INDEX no-entity sentinel can never reach
        -- SET_ENTITY_HEALTH's instigator argument.
        -- Null attribution is supported by SET_ENTITY_HEALTH and avoids a
        -- second unrelated ped GUID changing during this victim transaction.
        local damage_owner = 0
        local function attempt(name, hash_text, hash, ...)
            local ok, raw, err = Messiah.LeaseInvoke(lease, "void", name, hash, ...)
            result.native_calls[#result.native_calls + 1] = {
                name = name, hash = hash_text, ok = ok == true, raw = raw, error = err,
            }
            return ok == true
        end
        if kind == "ped" and H.APPLY_DAMAGE_TO_PED then
            result.invoked = attempt("APPLY_DAMAGE_TO_PED", "0x697157CED63F18D4",
                H.APPLY_DAMAGE_TO_PED, handle, amount, false, 0, weapon)
            result.backend = "APPLY_DAMAGE_TO_PED:" .. (result.invoked and "call-ok" or "call-error")
            result.after = Messiah.ReadDamageState(handle, kind, lease)
            result.observed = Messiah.ObservedDamage(result.before, result.after, amount)
            if result.observed <= 0.0 and H.SET_ENTITY_HEALTH
                and tonumber(result.before.health) ~= nil then
                local target_health = math.max(0, math.floor(result.before.health - amount))
                local fallback = attempt("SET_ENTITY_HEALTH", "0x6B76DC1F3AE6E6A3",
                    H.SET_ENTITY_HEALTH, handle, target_health, damage_owner, weapon)
                result.invoked = result.invoked or fallback
                result.backend = result.backend .. "+SET_ENTITY_HEALTH:"
                    .. (fallback and "call-ok" or "call-error")
                result.after = Messiah.ReadDamageState(handle, kind, lease)
                result.observed = Messiah.ObservedDamage(result.before, result.after, amount)
            end
        elseif kind == "vehicle" then
            local body_scale = math.max(1.0, tonumber(profile.vehicle_body_scale) or 4.0)
            local engine_scale = math.max(1.0, tonumber(profile.vehicle_engine_scale) or 6.0)
            local tank_scale = math.max(1.0, tonumber(profile.vehicle_tank_scale) or 4.0)
            local invoked, backends = false, {}
            local function record_backend(name, ok)
                backends[#backends + 1] = tostring(name) .. ":" .. (ok and "call-ok" or "call-error")
                invoked = ok or invoked
            end
            if H.SET_VEHICLE_DAMAGE then
                record_backend("SET_VEHICLE_DAMAGE", attempt("SET_VEHICLE_DAMAGE",
                    "0xA1DD317EA8FD4F29", H.SET_VEHICLE_DAMAGE, handle,
                    0.0, 0.0, 0.25, amount * 4.0, 1.15, true))
            end
            if H.SET_VEHICLE_BODY_HEALTH and tonumber(result.before.body) ~= nil then
                record_backend("SET_VEHICLE_BODY_HEALTH", attempt("SET_VEHICLE_BODY_HEALTH",
                    "0xB77D05AC8C78AADB", H.SET_VEHICLE_BODY_HEALTH, handle,
                    math.max(-1000.0, result.before.body - amount * body_scale)))
            end
            if H.SET_VEHICLE_ENGINE_HEALTH and tonumber(result.before.engine) ~= nil then
                record_backend("SET_VEHICLE_ENGINE_HEALTH", attempt("SET_VEHICLE_ENGINE_HEALTH",
                    "0x45F6D8EEF34ABEF1", H.SET_VEHICLE_ENGINE_HEALTH, handle,
                    math.max(-4000.0, result.before.engine - amount * engine_scale)))
            end
            if H.SET_VEHICLE_PETROL_TANK_HEALTH and tonumber(result.before.tank) ~= nil then
                record_backend("SET_VEHICLE_PETROL_TANK_HEALTH", attempt(
                    "SET_VEHICLE_PETROL_TANK_HEALTH", "0x70DB57649FA8D0D8",
                    H.SET_VEHICLE_PETROL_TANK_HEALTH, handle,
                    math.max(-999.9, result.before.tank - amount * tank_scale)))
            end
            result.invoked = invoked
            result.backend = #backends > 0 and table.concat(backends, "+")
                or "vehicle-backend-unavailable"
            result.after = Messiah.ReadDamageState(handle, kind, lease)
            result.observed = Messiah.ObservedDamage(result.before, result.after, amount)
        elseif kind == "object" and H.SET_ENTITY_HEALTH and tonumber(result.before.health) ~= nil then
            local object_scale = math.max(1.0, tonumber(profile.object_scale) or 10.0)
            local target_health = math.max(0, math.floor(result.before.health - amount * object_scale))
            result.invoked = attempt("SET_ENTITY_HEALTH", "0x6B76DC1F3AE6E6A3",
                H.SET_ENTITY_HEALTH, handle, target_health, damage_owner, weapon)
            result.backend = "SET_ENTITY_HEALTH(object):"
                .. (result.invoked and "call-ok" or "call-error")
            result.after = Messiah.ReadDamageState(handle, kind, lease)
            result.observed = Messiah.ObservedDamage(result.before, result.after, amount)
        else
            result.backend = "unsupported-kind"
        end
        Messiah.MaybeTerminalVehicle(result, profile, context)
        result.verified = result.invoked == true and (result.observed > 0.0
            or (result.before.exists_known == true and result.after.exists_known == true
                and result.before.exists == true and result.after.exists == false)
            or (result.before.destroyed_known == true and result.after.destroyed_known == true
                and result.before.destroyed == false and result.after.destroyed == true)
            or (result.before.driveable_known == true and result.after.driveable_known == true
                and result.before.driveable == true and result.after.driveable == false))
        mirror_readbacks()
        Messiah.RecordDamageEvidence(result, context)
        return result
    end

    function Messiah.NewImpactStats()
        return {
            player_slots = 0,
            player_candidates = 0,
            ped_candidates = 0,
            vehicle_candidates = 0,
            object_candidates = 0,
            visited_peds = 0,
            visited_vehicles = 0,
            visited_objects = 0,
            eligible = 0,
            affected = 0,
            affected_peds = 0,
            affected_vehicles = 0,
            affected_objects = 0,
            skipped_players = 0,
            skipped_no_control = 0,
            skipped_out_of_range = 0,
            skipped_duplicate = 0,
            skipped_invalid = 0,
            skipped_seated = 0,
            control_requests = 0,
            control_owned = 0,
            ragdolls = 0,
            force_calls = 0,
            damage_calls = 0,
            damage_targets = 0,
            damage_attempts = 0,
            damage_verified = 0,
            damage_failures = 0,
            damage_requested = 0.0,
            damage_observed = 0.0,
            damage_deduped = 0,
            terminal_attempts = 0,
            terminal_accepted = 0,
            terminal_verified = 0,
            velocity_calls = 0,
            velocity_accepted = 0,
            selected_players = 0,
            selected_vehicles = 0,
            selected_peds = 0,
            selected_objects = 0,
            object_responses = 0,
            visit_cap = 0,
            target_cap = 0,
            damage_backends = {},
            force_backends = {},
        }
    end

    function Messiah.AccumulateDamageStats(stats, result)
        if type(stats) ~= "table" or type(result) ~= "table" then return end
        stats.damage_calls = (tonumber(stats.damage_calls) or 0) + 1
        stats.damage_attempts = (tonumber(stats.damage_attempts) or 0) + 1
        stats.damage_requested = (tonumber(stats.damage_requested) or 0)
            + (tonumber(result.requested) or 0.0)
        stats.damage_observed = (tonumber(stats.damage_observed) or 0)
            + (tonumber(result.observed) or 0.0)
        if result.verified == true then
            stats.damage_targets = (tonumber(stats.damage_targets) or 0) + 1
            stats.damage_verified = (tonumber(stats.damage_verified) or 0) + 1
            if result.kind == "object" then
                stats.object_responses = (tonumber(stats.object_responses) or 0) + 1
            end
        else
            stats.damage_failures = (tonumber(stats.damage_failures) or 0) + 1
        end
        if result.control_requested == true then
            stats.control_requests = (tonumber(stats.control_requests) or 0) + 1
        end
        if result.control_after == true then
            stats.control_owned = (tonumber(stats.control_owned) or 0) + 1
        end
        if result.terminal_attempted == true then
            stats.terminal_attempts = (tonumber(stats.terminal_attempts) or 0) + 1
        end
        if result.terminal_accepted == true then
            stats.terminal_accepted = (tonumber(stats.terminal_accepted) or 0) + 1
        end
        if result.terminal_verified == true then
            stats.terminal_verified = (tonumber(stats.terminal_verified) or 0) + 1
        end
        local backend = tostring(result.backend or "none")
        stats.damage_backends = type(stats.damage_backends) == "table"
            and stats.damage_backends or {}
        stats.damage_backends[backend] = true
    end

    function Messiah.AccumulatePhysicalSummary(action_serial, action, profile_name,
                                               stats, pool_backend)
        action_serial = math.max(0, math.floor(tonumber(action_serial) or 0))
        if action_serial == 0 or type(stats) ~= "table" then return nil end
        local state = Messiah.State()
        local bucket = state.physical_summaries[action_serial]
        if type(bucket) ~= "table" then
            bucket = {
                action = tostring(action or "unspecified"),
                profile = tostring(profile_name or "UNKNOWN"),
                ticks = 0,
                pool_backends = {},
                force_backends = {},
                damage_backends = {},
            }
            state.physical_summaries[action_serial] = bucket
        end
        bucket.ticks = (tonumber(bucket.ticks) or 0) + 1
        local numeric_fields = {
            "visited_peds", "visited_vehicles", "visited_objects", "eligible", "affected",
            "affected_peds", "affected_vehicles", "affected_objects", "skipped_players",
            "skipped_no_control", "skipped_out_of_range", "skipped_duplicate",
            "skipped_invalid", "skipped_seated", "control_requests", "control_owned",
            "ragdolls", "force_calls", "velocity_calls", "velocity_accepted",
            "damage_attempts", "damage_verified", "damage_requested", "damage_observed",
            "terminal_attempts", "terminal_accepted", "terminal_verified", "object_responses",
        }
        for _, field in ipairs(numeric_fields) do
            bucket[field] = (tonumber(bucket[field]) or 0) + (tonumber(stats[field]) or 0)
        end
        bucket.visit_cap = math.max(tonumber(bucket.visit_cap) or 0,
            tonumber(stats.visit_cap) or 0)
        bucket.target_cap = math.max(tonumber(bucket.target_cap) or 0,
            tonumber(stats.target_cap) or 0)
        bucket.pool_backends[tostring(pool_backend or "unknown")] = true
        for backend in pairs(type(stats.force_backends) == "table" and stats.force_backends or {}) do
            bucket.force_backends[tostring(backend)] = true
        end
        for backend in pairs(type(stats.damage_backends) == "table" and stats.damage_backends or {}) do
            bucket.damage_backends[tostring(backend)] = true
        end
        return bucket
    end

    function Messiah.FlushPhysicalSummary(action_serial, reason)
        action_serial = math.max(0, math.floor(tonumber(action_serial) or 0))
        local state = Messiah.State()
        local bucket = state.physical_summaries[action_serial]
        if type(bucket) ~= "table" then return false end
        local function names(values)
            local result = {}
            for value in pairs(type(values) == "table" and values or {}) do
                result[#result + 1] = tostring(value)
            end
            table.sort(result)
            return #result > 0 and table.concat(result, "+") or "none"
        end
        log_info(("Messiah physical impact: activation=%d actionSerial=%d ability=%s profile=%s "
                .. "ticks=%d visited=%d visitedVehicles=%d visitedPeds=%d visitedObjects=%d "
                .. "eligible=%d affected=%d vehicles=%d peds=%d objects=%d "
                .. "skippedReason={players=%d,noControl=%d,outOfRange=%d,duplicate=%d,invalid=%d,seated=%d} "
                .. "control={requested=%d,owned=%d,retryMs=%d} force={calls=%d,backend=%s} "
                .. "velocity={calls=%d,accepted=%d} ragdolls=%d "
                .. "damage={attempted=%d,verified=%d,requested=%.2f,observed=%.2f,backend=%s} "
                .. "terminal={attempted=%d,accepted=%d,verified=%d} objectResponses=%d "
                .. "poolBackend=%s visitCap=%d affectedCap=%d reason=%s.")
            :format(state.activation_id, action_serial, tostring(bucket.action),
                tostring(bucket.profile), tonumber(bucket.ticks) or 0,
                (tonumber(bucket.visited_vehicles) or 0) + (tonumber(bucket.visited_peds) or 0)
                + (tonumber(bucket.visited_objects) or 0),
                tonumber(bucket.visited_vehicles) or 0, tonumber(bucket.visited_peds) or 0,
                tonumber(bucket.visited_objects) or 0, tonumber(bucket.eligible) or 0,
                tonumber(bucket.affected) or 0, tonumber(bucket.affected_vehicles) or 0,
                tonumber(bucket.affected_peds) or 0, tonumber(bucket.affected_objects) or 0,
                tonumber(bucket.skipped_players) or 0, tonumber(bucket.skipped_no_control) or 0,
                tonumber(bucket.skipped_out_of_range) or 0,
                tonumber(bucket.skipped_duplicate) or 0, tonumber(bucket.skipped_invalid) or 0,
                tonumber(bucket.skipped_seated) or 0, tonumber(bucket.control_requests) or 0,
                tonumber(bucket.control_owned) or 0, Messiah.IMPACT_CONTROL_RETRY_MS,
                tonumber(bucket.force_calls) or 0, names(bucket.force_backends),
                tonumber(bucket.velocity_calls) or 0, tonumber(bucket.velocity_accepted) or 0,
                tonumber(bucket.ragdolls) or 0, tonumber(bucket.damage_attempts) or 0,
                tonumber(bucket.damage_verified) or 0, tonumber(bucket.damage_requested) or 0.0,
                tonumber(bucket.damage_observed) or 0.0, names(bucket.damage_backends),
                tonumber(bucket.terminal_attempts) or 0, tonumber(bucket.terminal_accepted) or 0,
                tonumber(bucket.terminal_verified) or 0, tonumber(bucket.object_responses) or 0,
                names(bucket.pool_backends), tonumber(bucket.visit_cap) or 0,
                tonumber(bucket.target_cap) or 0, tostring(reason or "impact-complete")))
        state.physical_summaries[action_serial] = nil
        return true
    end

    function Messiah.ImpactFx(profile_name, position, maximum, diagnostic_key, options)
        if (tonumber(maximum) or 0) <= 0 then return 0, "" end
        local state, now = Messiah.State(), now_ms()
        options = type(options) == "table" and options or {}
        if profile_name == "ORB_IMPACT" or (profile_name == "SUPER_IMPACT" and options.final_core == true) then
            -- Rockstar uses this asset for arena sci-fi impact FX. It is a
            -- supplemental shared pulse; the caster's compression, focal flash
            -- and clipped distortion arcs carry the authored local geometry.
            -- Network appearance needs live review.
            local started = Messiah.StartTimedFxAtCoord("scr_xs_props", "scr_xs_exp_mine_sf",
                position.x, position.y, position.z + 0.12,
                profile_name == "ORB_IMPACT" and 0.45 or 1.50, 0,
                profile_name == "ORB_IMPACT" and "orb-pressure-pulse" or "judgment-pressure-pulse")
            return started and 1 or 0, started and "scr_xs_props/scr_xs_exp_mine_sf" or ""
        end
        if profile_name == "RUPTURE_IMPACT" then
            -- Rockstar's survival corpse-emergence path selects this dirt
            -- effect and starts it at ground, not a descending alien shaft.
            local started = Messiah.StartTimedFxAtCoord("scr_sb_hal", "scr_sb_hal_zom_spawn_dirt",
                position.x, position.y, position.z + 0.02, options.final_core and 0.85 or 0.45, 0,
                options.final_core and "rupture-ground-core" or "rupture-ground-eruption")
            return started and 1 or 0, started and "scr_sb_hal/scr_sb_hal_zom_spawn_dirt" or ""
        end
        if profile_name == "LANCE_IMPACT" then
            if now < (state.next_lance_energy_ms or 0) then return 0, "cadence" end
            state.next_lance_energy_ms = now + 220
        end
        -- Barry's game script uses teleport/disintegrate as non-looped effects;
        -- charging and beam are looped. Effect names alone do not prove the mode.
        local effect = profile_name == "SUPER_IMPACT" and Messiah.ALIEN_DISINTEGRATE_EFFECT
            or "scr_alien_teleport"
        local scales = {
            ORB_IMPACT = 0.80,
            LANCE_IMPACT = 0.14,
            RUPTURE_IMPACT = 0.65,
            SUPER_IMPACT = 1.10
        }
        local started = Messiah.StartTimedFxAtCoord(Messiah.ALIEN_FX_ASSET, effect,
            position.x, position.y, position.z + 0.1, scales[profile_name] or 0.65, 0,
            diagnostic_key or profile_name)
        return started and 1 or 0, started and (Messiah.ALIEN_FX_ASSET .. "/" .. effect) or ""
    end

    function Messiah.AddImpactVisualComposite(profile_name, position, direction, now, options)
        position = Messiah.VisualPoint(position)
        options = type(options) == 'table' and options or {}
        local state = Messiah.State()
        if not position or options.no_visual_records or options.host_retry
            or (options.epoch and options.epoch ~= state.activation_epoch) then
            return 0
        end
        local before = Messiah.VisualCount()
        if profile_name == 'ORB_IMPACT' then
            Messiah.AddPressureWave(now, position, profile_name, options)
        elseif profile_name == 'SUPER_IMPACT' and options.final_core then
            Messiah.AddPressureWave(now, position, profile_name, options)
        elseif profile_name == 'SUPER_IMPACT' then
            local target = Messiah.VisualPoint({
                x = options.visual_center_x,
                y = options.visual_center_y,
                z = options
                    .visual_center_z
            })
            if target and Messiah.AddBeam(now, position, target, 380, 'judgment-inward', 3) then
                local beam = state.visuals.beams[#state.visuals.beams]
                beam.owner_action_serial = tonumber(options.action_serial) or state.action_serial
                beam.owner_ability = 'SUPER'
            end
        elseif profile_name == 'RUPTURE_IMPACT' and Messiah.AdmitPresentation(options.final_core and 90 or 55) then
            state.visuals.markers[#state.visuals.markers + 1] = {
                kind = 'eruption',
                local_only = true,
                position = position,
                started_ms = now,
                expires_ms = now + (options.final_core and 780 or 600),
                radius_from = 0.2,
                radius_to = options.final_core and 3 or 1.8,
                alpha = 235,
                final_core = options.final_core == true,
                presentation_priority = options.final_core and 90 or 55,
                owner_epoch = state.activation_epoch,
                owner_action_serial = options.action_serial or state.action_serial,
                owner_ability = 'RUPTURE'
            }
        end
        return Messiah.VisualCount() - before
    end

    function Messiah.PlayShockwavePulse(shell_index, position, context)
        shell_index = tonumber(shell_index)
        if not shell_index or shell_index < 1 or shell_index > 3 or shell_index % 1 ~= 0 then return 0 end
        local state = Messiah.State()
        context = type(context) == "table" and context or {}
        if state.gameplay_owner ~= true or state.ending or state.restoring or state.disposed
            or context.host_retry or context.no_audio
            or (context.epoch ~= nil and context.epoch ~= state.activation_epoch) then
            return 0
        end
        local started = 0
        -- Supplemental peer-visible contact accent, one bounded network burst
        -- per physical front. This is not claimed to reproduce the caster's
        -- authored three-dimensional shell on another client's renderer.
        local point = Messiah.VisualPoint(position)
        -- The old mine burst throws ground debris even when E is airborne.
        -- Barry starts this teleport-energy effect NON_LOOPED_AT_COORD
        -- (barry1.c:2769). Keep that proven creation mode and a compact scale;
        -- the three local fronts carry the shape, not a ground-debris burst.
        if point then
            Messiah.StartTimedFxAtCoord(Messiah.ALIEN_FX_ASSET, "scr_alien_teleport",
                point.x, point.y, point.z, 0.16 + shell_index * 0.025, 0, "shockwave-front-" .. shell_index)
        end
        -- Each physical front owns one brief spatial impulse and one local low
        -- accent. No EMP identity; all three pairs are admitted independently.
        if Messiah.PlayCoordSound("shockwave-pulse", position, "magnetic_explosion",
                "dlc_h4_heist_finale_sounds_soundset", 360, context) then
            started = started + 1
        end
        if Messiah.PlayFrontendSound("shockwave-impact", "Explosion_Shake",
                "dlc_xm_avngr_sounds", 220, false, context) then
            started = started + 1
        end
        return started
    end

    function Messiah.PlayImpactAudio(profile_name, position, options)
        options = type(options) == "table" and options or {}
        if options.no_audio == true or options.host_retry == true then return 0 end
        local state = Messiah.State()
        if options.epoch ~= nil and options.epoch ~= state.activation_epoch then return 0 end
        local started = 0
        if profile_name == "ORB_IMPACT" then
            local owned_role = "orb-impact:" .. tostring(state.activation_epoch)
                .. ":" .. tostring(options.action_serial or 0)
            if Messiah.PlayCoordSound(owned_role, position, "magnetic_explosion",
                    "dlc_h4_heist_finale_sounds_soundset", 700, options) then
                started = started + 1
            end
            if Messiah.PlayFrontendSound("orb-impact-tail", "Blue_Target_Charge",
                    "dlc_xm_silo_laser_hack_sounds", 180, false, options) then
                started = started + 1
            end
        elseif profile_name == "LANCE_IMPACT" then
            -- Sustained channel bed is never recreated at contact cadence. One
            -- short accent per 440 ms can identify contact without 110 ms spam.
            if now_ms() >= (state.next_lance_audio_ms or 0) then
                state.next_lance_audio_ms = now_ms() + 440
                if Messiah.PlayFrontendSound("lance-contact", "Red_Target_Charge",
                        "dlc_xm_silo_laser_hack_sounds", 140, false, options) then
                    started = started + 1
                end
            end
        elseif profile_name == "RUPTURE_IMPACT" then
            local role = options.final_core and "rupture-core" or "rupture-impact"
            if Messiah.PlayCoordSound(role, position, "magnetic_explosion",
                    "dlc_h4_heist_finale_sounds_soundset", options.final_core and 1200 or 330, options)
            then
                started = started + 1
            end
            if options.final_core and Messiah.PlayFrontendSound("rupture-core-tail", "Explosion_Shake",
                    "dlc_xm_avngr_sounds", 650, false, options) then
                started = started + 1
            end
        elseif profile_name == "SHOCKWAVE_IMPACT" then
            -- Physical front completion calls PlayShockwavePulse exactly once
            -- for each band. Individual covered targets never emit more cues.
        elseif profile_name == "SUPER_IMPACT" then
            if options.audio_final == true then
                -- Three different source vocabularies, with core admission
                -- priority. Orbital is a layer, not the complete super identity.
                if Messiah.PlayCoordSound("judgment-core-spatial", position, "DLC_XM_Explosions_Orbital_Cannon",
                        0, 2600, options) then
                    started = started + 1
                end
                if Messiah.PlayCoordSound("judgment-core-bass", position, "magnetic_explosion",
                        "dlc_h4_heist_finale_sounds_soundset", 1500, options) then
                    started = started + 1
                end
                if Messiah.PlayFrontendSound("judgment-core", "Explosion_Shake",
                        "dlc_xm_avngr_sounds", 1000, false, options) then
                    started = started + 1
                end
            elseif Messiah.PlayFrontendSound("judgment-satellite", "Red_Target_Charge",
                    "dlc_xm_silo_laser_hack_sounds", 190, false, options) then
                started = started + 1
            end
        end
        return started
    end

    function Messiah.ClaimDestructiveAccent(action_serial, profile_name)
        local state = Messiah.State()
        action_serial = math.max(0, math.floor(tonumber(action_serial) or 0))
        profile_name = tostring(profile_name or "UNKNOWN")
        if action_serial == 0 then return false, "missing-action-owner" end
        local key = tostring(action_serial) .. ":" .. profile_name
        if state.destructive_accent_registry[key] == true then return false, "deduped" end
        state.destructive_accent_registry[key] = true
        state.destructive_accent_order[#state.destructive_accent_order + 1] = key
        while #state.destructive_accent_order > Messiah.MAX_DESTRUCTIVE_ACCENT_CLAIMS do
            local oldest = table.remove(state.destructive_accent_order, 1)
            state.destructive_accent_registry[oldest] = nil
        end
        return true, "claimed"
    end

    function Messiah.LanceBlastSlot(position, action_serial, now)
        local state = Messiah.State()
        if state.lance_contacts_serial ~= action_serial then
            state.lance_contacts_serial, state.lance_contacts = action_serial, {}
        end
        local contacts = state.lance_contacts
        for _, record in ipairs(contacts) do
            local dx, dy, dz = position.x - record.x, position.y - record.y, position.z - record.z
            if dx * dx + dy * dy + dz * dz <= 6.25 then
                return record, now >= record.next_ms
            end
        end
        if #contacts >= 12 then table.remove(contacts, 1) end
        local record = { x = position.x, y = position.y, z = position.z, next_ms = 0, failures = 0 }
        contacts[#contacts + 1] = record
        return record, true
    end

    function Messiah.RecordEssentialStage(serial, event, now)
        local state = Messiah.State()
        local book = state.essential_stages
        if not book or book.epoch ~= state.activation_epoch then
            book = { epoch = state.activation_epoch, actions = {}, order = {} }
            state.essential_stages = book
        end
        local entry = book.actions[serial]
        if not entry then
            if #book.order >= 16 then
                local oldest = table.remove(book.order, 1)
                Messiah.FlushEssentialStage(book.actions[oldest], "summary-capacity")
                book.actions[oldest] = nil
            end
            entry = { serial = serial, epoch = state.activation_epoch, accepted = 0, rejected = 0, retried = 0, dropped = 0 }
            book.actions[serial] = entry; book.order[#book.order + 1] = serial
        end
        if entry[event] ~= nil then entry[event] = entry[event] + 1 end
        entry.updated_ms = tonumber(now) or now_ms()
    end

    function Messiah.FlushEssentialStage(entry, reason)
        if not entry then return end
        log_info(("Messiah essential stages: epoch=%d actionSerial=%d accepted=%d rejected=%d "
                .. "retried=%d dropped=%d reason=%s hostAcceptanceOnly=true.")
            :format(entry.epoch, entry.serial, entry.accepted, entry.rejected,
                entry.retried, entry.dropped, tostring(reason)))
    end

    function Messiah.RecordEssentialDrop(record, now)
        if not record or not (record.critical or (record.options and
                (record.options.essential or record.options.final_core))) then
            return
        end
        local state = Messiah.State()
        local book = state.essential_stages
        local entry = book and book.epoch == record.epoch and book.actions[record.action_serial]
        if entry then
            entry.dropped = entry.dropped + 1; entry.updated_ms = now or entry.updated_ms
        elseif record.epoch == state.activation_epoch then
            Messiah.RecordEssentialStage(record.action_serial, "dropped", now)
        end
    end

    function Messiah.FlushEssentialStages(now)
        local state = Messiah.State()
        local book = state.essential_stages
        if not book then return end
        for index = #book.order, 1, -1 do
            local serial = book.order[index]
            local entry = book.actions[serial]
            local pending = state.action and state.action.serial == serial
            for _, record in ipairs(state.scheduled_impacts) do
                if record.action_serial == serial then
                    pending = true; break
                end
            end
            local stale = book.epoch ~= state.activation_epoch or not Messiah.EntityOwner()
            if stale or (not pending and now - entry.updated_ms >= 500) then
                Messiah.FlushEssentialStage(entry, stale and "cancelled-or-epoch-ended" or "complete")
                book.actions[serial] = nil; table.remove(book.order, index)
            end
        end
        if #book.order == 0 then state.essential_stages = nil end
    end

    function Messiah.ApplyImpactProfile(profile_name, position, direction, options)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        if not Messiah.ActivationContextCurrent(state, epoch) then return false end
        local profile = Messiah.IMPACT_PROFILES[profile_name]
        position = Messiah.CopyPoint(position)
        options = type(options) == "table" and options or {}
        if not profile or not position or not Messiah.EntityOwner()
            or state.ending or state.restoring or state.cleanup_owner then
            return false
        end
        position = { x = position.x, y = position.y, z = position.z }
        local now = now_ms()
        if not Messiah.ActivationContextCurrent(state, epoch) then return false, nil, 0, "activation-context-changed" end
        local action_serial = tonumber(options.action_serial)
            or (state.action and tonumber(state.action.serial)) or 0
        if action_serial <= 0 or (options.epoch and options.epoch ~= epoch) then return false end
        local damaging = options.no_damage ~= true
        local essential = options.final_core == true or options.essential == true
            or (profile_name == "ORB_IMPACT" and options.no_visual_records ~= true)
            or profile_name == "LANCE_IMPACT"
        if essential then options.essential = true end
        local lance_slot
        if damaging and profile_name == "LANCE_IMPACT" and options.host_retry ~= true then
            local ready
            lance_slot, ready = Messiah.LanceBlastSlot(position, action_serial, now)
            if not ready then return false, nil, 0, "same-contact-cooldown" end
        end
        -- A delayed frame may contain many due stages or simultaneous Orb hits.
        -- Queue detached coordinates, never victim or projectile references.
        if state.blast_frame ~= state.entity_frame then
            state.blast_frame, state.blasts_this_frame = state.entity_frame, 0
        end
        if damaging and (state.blasts_this_frame or 0) >= Messiah.MAX_BLASTS_PER_FRAME then
            if options.budget_retry then return false, nil, 0, "budget" end
            local deferred = {}
            for _, key in ipairs({ "action", "action_serial", "epoch", "blast_scale", "no_vanilla_fx",
                "native_sound", "no_visual_records", "max_fx", "no_audio", "audio_index", "audio_final",
                "final_core", "essential", "visual_center_x", "visual_center_y", "visual_center_z",
                "flush_damage", "flush_reason", "diagnostic_key", "fx_profile", "host_retry" }) do
                deferred[key] = options[key]
            end
            deferred.budget_retry, deferred.epoch = true, epoch
            local queued = Messiah.ScheduleImpact(now, 0,
                {
                    owner_state = state,
                    profile = profile_name,
                    position = position,
                    direction = direction,
                    action_serial = action_serial,
                    options = deferred,
                    critical = essential
                })
            if not Messiah.ActivationContextCurrent(state, epoch) then return false, nil, 0, "activation-context-changed" end
            return queued, nil, 0, queued and "queued" or "queue-full"
        end
        local presented = false
        if options.no_visual_records ~= true then
            Messiah.AddImpactVisualComposite(profile_name, position, direction, now, options)
            if not Messiah.ActivationContextCurrent(state, epoch) then return false, nil, 0, "activation-context-changed" end
            presented = true
        end
        local fx_limit = options.no_visual_records ~= true and 1
            or math.min(1, math.max(0, tonumber(options.max_fx) or 0))
        if fx_limit > 0 then
            Messiah.ImpactFx(tostring(options.fx_profile or profile_name), position, fx_limit,
                tostring(options.diagnostic_key or profile_name), options)
            if not Messiah.ActivationContextCurrent(state, epoch) then return false, nil, 0, "activation-context-changed" end
        end
        if options.no_audio ~= true then Messiah.PlayImpactAudio(profile_name, position, options) end
        if not Messiah.ActivationContextCurrent(state, epoch) then return false, nil, 0, "activation-context-changed" end
        local accepted, result = false, "presentation-only"
        if damaging then
            state.blasts_this_frame = (state.blasts_this_frame or 0) + 1
            accepted, result = Messiah.Explode(position.x, position.y, position.z,
                tonumber(options.blast_scale) or profile.blast_scale,
                false, options.no_vanilla_fx == true, profile_name, options.native_sound ~= false)
            if not Messiah.ActivationContextCurrent(state, epoch) then return false, nil, 0, "activation-context-changed" end
            if lance_slot then
                lance_slot.failures = accepted and 0 or math.min(2, lance_slot.failures + 1)
                lance_slot.next_ms = now + 330 * (2 ^ lance_slot.failures)
            end
            -- Only an explicit false result is safe to retry. A throwing host
            -- may already have applied damage. Final cores get one detached,
            -- silent retry under the same frame/queue/activation limits.
            if essential then
                Messiah.RecordEssentialStage(action_serial, accepted and "accepted" or "rejected", now)
                if not Messiah.ActivationContextCurrent(state, epoch) then
                    return false, nil, 0,
                        "activation-context-changed"
                end
            end
            if result == "host-rejected" and essential and not options.host_retry then
                local queued = Messiah.ScheduleImpact(now, 330,
                    {
                        owner_state = state,
                        profile = profile_name,
                        position = position,
                        action_serial = action_serial,
                        critical = true,
                        options = {
                            action = options.action,
                            action_serial = action_serial,
                            epoch = epoch,
                            blast_scale = tonumber(options.blast_scale) or profile.blast_scale,
                            final_core = options.final_core == true,
                            essential = true,
                            host_retry = true,
                            no_visual_records = true,
                            max_fx = 0,
                            no_audio = true,
                            native_sound = false
                        }
                    })
                if not Messiah.ActivationContextCurrent(state, epoch) then
                    return false, nil, 0,
                        "activation-context-changed"
                end
                if queued then Messiah.RecordEssentialStage(action_serial, "retried", now) end
                if not Messiah.ActivationContextCurrent(state, epoch) then
                    return false, nil, 0,
                        "activation-context-changed"
                end
            end
            state.blast_attempts = (state.blast_attempts or 0) + 1
            state.blast_accepted = (state.blast_accepted or 0) + (accepted and 1 or 0)
            if not accepted then Messiah.ReportFailure("engine blast", tostring(profile_name) .. ": " .. tostring(result)) end
            if not Messiah.ActivationContextCurrent(state, epoch) then return false, nil, 0, "activation-context-changed" end
            if behavior_debug_enabled() or now >= (state.next_blast_log_ms or 0) then
                state.next_blast_log_ms = now + 1000
                log_info(("Messiah engine blast: revision=17.75 epoch=%d actionSerial=%d profile=%s "
                        .. "position=(%.2f,%.2f,%.2f) tag=%s accepted=%s result=%s "
                        .. "attempts=%d acceptedTotal=%d noDamage=false ownerIgnored=true "
                        .. "targetNatives=0 poolScans=0 outcome=live-unverified.")
                    :format(state.activation_epoch, action_serial, profile_name,
                        position.x, position.y, position.z, profile.blast_tag, tostring(accepted), tostring(result),
                        state.blast_attempts, state.blast_accepted))
            end
        end
        return accepted or presented, {
            engine_blast = accepted,
            result = result,
            target_native_calls = 0,
            pool_visits = 0
        }, 0, result
    end

    function Messiah.ScheduleImpact(now, delay_ms, record)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        if not Messiah.ActivationContextCurrent(state, epoch) then return false end
        if type(record) ~= "table" then return false end
        if record.owner_state ~= nil and record.owner_state ~= state then return false end
        local point = Messiah.CopyPoint(record.position)
        if not point then return false end
        point = { x = point.x, y = point.y, z = point.z }
        local input_options = type(record.options) == "table" and record.options or {}
        if (record.epoch ~= nil and record.epoch ~= epoch)
            or (input_options.epoch ~= nil and input_options.epoch ~= epoch) then
            return false
        end
        local critical = record.critical == true or input_options.final_core == true
            or input_options.essential == true
        if #state.scheduled_impacts >= Messiah.MAX_SCHEDULED_IMPACTS and critical then
            -- Preserve an actual projectile/beam contact under overload before
            -- secondary blast coverage, including the final Judgment/Rupture
            -- core. Never grow the bounded queue or evict another primary.
            local replace_index
            for index = #state.scheduled_impacts, 1, -1 do
                local pending = state.scheduled_impacts[index]
                if not pending.critical and not pending.options.final_core then
                    replace_index = index; break
                end
            end
            if replace_index then
                table.remove(state.scheduled_impacts, replace_index)
                Messiah.LogOnce("impact-support-preempted",
                    "Messiah impact load limit: secondary blast replaced to retain primary impact; coverage reduced.")
                if not Messiah.ActivationContextCurrent(state, epoch) then return false end
            end
        end
        if #state.scheduled_impacts >= Messiah.MAX_SCHEDULED_IMPACTS then
            if critical then Messiah.RecordEssentialStage(tonumber(record.action_serial) or 0, "dropped", now) end
            if not Messiah.ActivationContextCurrent(state, epoch) then return false end
            Messiah.LogOnce("scheduled-impact-cap",
                ("Messiah scheduled impact rejected: activation=%d cap=%d.")
                :format(state.activation_id, Messiah.MAX_SCHEDULED_IMPACTS))
            return false
        end
        local record_options = {}
        for _, key in ipairs({ "action", "action_serial", "epoch", "blast_scale", "no_damage", "no_vanilla_fx",
            "native_sound", "no_visual_records", "max_fx", "no_audio", "audio_index", "audio_final",
            "final_core", "essential", "visual_center_x", "visual_center_y", "visual_center_z",
            "flush_damage", "flush_reason", "diagnostic_key", "fx_profile", "budget_retry", "host_retry" }) do
            local value = input_options[key]
            local value_type = type(value)
            if value_type == "boolean" or value_type == "number" or value_type == "string" then
                record_options[key] = value
            end
        end
        if record_options.action_serial == nil then
            record_options.action_serial = tonumber(record.action_serial) or 0
        end
        record_options.epoch = epoch
        local due_ms = (tonumber(now) or now_ms()) + math.max(0, tonumber(delay_ms) or 0)
        if not Messiah.ActivationContextCurrent(state, epoch) then return false end
        state.schedule_serial = state.schedule_serial + 1
        state.scheduled_impacts[#state.scheduled_impacts + 1] = {
            due_ms = due_ms,
            order = state.schedule_serial,
            critical = critical,
            epoch = epoch,
            profile = tostring(record.profile),
            position = point,
            direction = type(record.direction) == "table" and {
                x = tonumber(record.direction.x) or 0.0,
                y = tonumber(record.direction.y) or 0.0,
                z = tonumber(record.direction.z) or 0.0,
            } or nil,
            options = record_options,
            stage = record.stage and tostring(record.stage) or nil,
            action_serial = tonumber(record.action_serial) or 0,
        }
        return true
    end

    function Messiah.TickScheduledImpacts(now)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        if not Messiah.ActivationContextCurrent(state, epoch) then return 0 end
        if not Messiah.EntityOwner() or state.ending or state.restoring then return 0 end
        Messiah.TickShockwaveFronts(now)
        if not Messiah.ActivationContextCurrent(state, epoch) then return 0 end
        local queue = state.scheduled_impacts
        if #queue == 0 then
            Messiah.FlushEssentialStages(now); return 0
        end
        table.sort(queue, function(left, right)
            if left.due_ms == right.due_ms then return left.order < right.order end
            return left.due_ms < right.due_ms
        end)
        local completed = 0
        while completed < Messiah.MAX_BLASTS_PER_FRAME and #queue > 0 do
            local record = queue[1]
            if now < record.due_ms then break end
            if state.blast_frame == state.entity_frame
                and (state.blasts_this_frame or 0) >= Messiah.MAX_BLASTS_PER_FRAME then
                break
            end
            table.remove(queue, 1)
            completed = completed + 1
            if record.epoch == state.activation_epoch then
                Messiah.ApplyImpactProfile(record.profile, record.position, record.direction, record.options)
            else
                Messiah.RecordEssentialDrop(record, now)
            end
            if not Messiah.ActivationContextCurrent(state, epoch) then return completed end
        end
        Messiah.FlushEssentialStages(now)
        return completed
    end

    function Messiah.CleanupProjectile(handle, reason, explode, force)
        local state = Messiah.State()
        local epoch, cleanup_epoch = state.activation_epoch, state.cleanup_epoch
        local cleanup_owner = state.cleanup_owner == true
        local info = state.projectiles[handle]
        if not info or info.cleanup_terminal == true then return false end
        local lease = info.lease
        local function current()
            local valid
            if State.messiah ~= state or state.activation_epoch ~= epoch
                or state.projectiles[handle] ~= info then
                valid = false
            elseif cleanup_owner then
                -- The ordinary gameplay teardown retains its captured cleanup
                -- lease epoch while activation_epoch has already been revoked.
                valid = state.cleanup_owner == true and state.cleanup_epoch == cleanup_epoch
                    and state.gameplay_owner == true and state.restoring == true
                    and state.disposed ~= true and state.cleanup_failed ~= true
                    and lease ~= nil and lease.epoch == cleanup_epoch
            else
                valid = Messiah.ActivationContextCurrent(state, epoch)
            end
            -- A same-table Quiesce transfers cleanup to the existing gameplay
            -- drain. Release only this captured Lua latch so that drain can
            -- finish the still-owned carrier without replaying consumed stages.
            if not valid then info.cleanup_active = false end
            return valid
        end
        if not current() then return false end
        if not Messiah.EntityOwner(lease) then return false end
        reason = tostring(reason or "unspecified")
        info.cleanup_reason = info.cleanup_reason or reason
        info.cleanup_explode = info.cleanup_explode == true or explode == true
        -- Freeze and claim the impact transaction before any FX/audio/damage.
        -- Victim processing never reads or depends on the carrier after this.
        if info.cleanup_explode and info.exploded ~= true and state.cleanup_owner ~= true then
            info.exploded = true
            local position = Messiah.CopyPoint(info.impact_position or info.last_position)
            local direction = {
                x = tonumber(info.impact_direction_x or info.direction_x) or 0.0,
                y = tonumber(info.impact_direction_y or info.direction_y) or 1.0,
                z = tonumber(info.impact_direction_z or info.direction_z) or 0.0
            }
            -- Claim once, then detach all impact work from the carrier before
            -- the engine blast can destroy it. Ground hits need no victim.
            if position then
                local center = { x = position.x, y = position.y, z = position.z + 0.10 }
                Messiah.ApplyImpactProfile("ORB_IMPACT", center, direction, {
                    action = "ORB",
                    action_serial = info.action_serial,
                    epoch = epoch,
                    blast_scale = 3.0,
                    max_fx = 1,
                    native_sound = true
                })
                if not current() then return false end
                for index = 0, 3 do
                    local angle = index * math.pi * 0.5
                    local support_now = now_ms()
                    if not current() then return false end
                    Messiah.ScheduleImpact(support_now, 45 + index * 25, {
                        owner_state = state,
                        epoch = epoch,
                        profile = "ORB_IMPACT",
                        action_serial = info.action_serial,
                        position = {
                            x = center.x + math.cos(angle) * 5.0,
                            y = center.y + math.sin(angle) * 5.0,
                            z = center.z
                        },
                        options = {
                            action = "ORB",
                            action_serial = info.action_serial,
                            epoch = epoch,
                            blast_scale = 2.0,
                            no_visual_records = true,
                            max_fx = 0,
                            no_audio = true,
                            native_sound = false,
                            no_vanilla_fx = true
                        }
                    })
                    if not current() then return false end
                end
            end
            -- A borrowed collision target must never be released/read after a
            -- destructive blast. No target reference is needed by this backend.
            Messiah.RetireEntityLease(info.impact_lease, "coordinate-blast-consumed", false)
            if not current() then return false end
            info.impact_lease, info.impact_handle, info.impact_handle_raw = nil, nil, nil
        end
        if info.cleanup_active == true then return false end
        info.cleanup_active = true
        local fx = type(info.fx) == "table" and info.fx or { info.fx }
        info.fx = fx
        while #fx > 0 do
            local owned_fx = table.remove(fx, 1)
            Messiah.StopFx(owned_fx)
            if not current() then return false end
        end
        if lease and Messiah.ValidateEntityLease(lease, "carrier-quarantine", "none") then
            if not current() then return false end
            info.quarantine_attempted = info.quarantine_attempted or {}
            for _, operation in ipairs({
                { "SET_ENTITY_VELOCITY",  H.SET_ENTITY_VELOCITY,  0.0,   0.0,  0.0 },
                { "SET_ENTITY_COLLISION", H.SET_ENTITY_COLLISION, false, false },
                { "SET_ENTITY_ALPHA",     H.SET_ENTITY_ALPHA,     0,     false },
            }) do
                if not info.quarantine_attempted[operation[1]] then
                    info.quarantine_attempted[operation[1]] = true
                    Messiah.LeaseInvoke(lease, "void", operation[1], operation[2], handle, table.unpack(operation, 3))
                    if not current() then return false end
                end
            end
        end
        if not current() then return false end
        local deleted, backend, access_ended = Messiah.DeleteEntity(handle, lease)
        if not current() then return false end
        info.delete_attempts = (tonumber(info.delete_attempts) or 0) + 1
        if access_ended or info.delete_attempts >= Messiah.ORB_DELETE_MAX_ATTEMPTS then
            Messiah.RecordCleanupEvidence(lease, backend or "cleanup-retry-cap", false)
            info.cleanup_terminal = true
            state.projectiles[handle] = nil
            Messiah.RetireEntityLease(lease, "orb-cleanup-access-ended", false)
            Messiah.Trace(("Messiah Fire Orb cleanup: activation=%d reason=%s delete_backend=%s outcome=unverified owned=true.")
                :format(state.activation_id, reason, tostring(backend)))
        end
        info.cleanup_active = false
        return deleted
    end

    function Messiah.ProjectileCount()
        local total = 0
        for _ in pairs(Messiah.State().projectiles) do total = total + 1 end
        return total
    end

    function Messiah.OldestProjectile()
        local oldest_handle, oldest_ms
        for handle, info in pairs(Messiah.State().projectiles) do
            local born = tonumber(info.born_ms) or 0
            if oldest_ms == nil or born < oldest_ms then oldest_handle, oldest_ms = handle, born end
        end
        return oldest_handle
    end

    function Messiah.TryCreateOrb(x, y, z)
        local state = Messiah.State()
        local epoch, action, frame = state.activation_epoch, state.action, state.entity_frame
        local creation = {
            epoch = epoch,
            action_serial = state.action_serial,
            creation_serial = state.spawn_attempts,
            kind = "object",
            source = "orb-creation"
        }
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.action == action and state.entity_frame == frame
        end
        local function uncertain(detail)
            local evidence = Messiah.RecordCleanupEvidence(creation, detail, false)
            if evidence and not current() then evidence.scope = "ended" end
            return 0, detail
        end
        if not current() then return 0, "creation-context-unavailable" end
        local u32, s32 = Messiah.NormalizeHash(Messiah.ORB_MODEL)
        local primary_ok, primary_raw = false, nil
        if gta and type(gta.CreateObject) == "function" then
            primary_ok, primary_raw = pcall(gta.CreateObject,
                Messiah.ORB_MODEL_NAME, x, y, z, true, true)
            if not current() then return uncertain("helper-returned-after-context-ended") end
            local primary_handle_raw = primary_ok and primary_raw or nil
            local handle, classification = Messiah.NormalizeEntityHandle(primary_handle_raw)
            Messiah.ReportRejectedEntityHandle("TryCreateOrb.GTA.CreateObject",
                primary_handle_raw, classification,
                "DOES_ENTITY_EXIST/0x7239B21A38F536BA",
                "primary creation result rejected before readback")
            local exists = handle ~= 0 and entity_exists(handle)
            if not current() then return uncertain("helper-readback-after-context-ended") end
            if exists then return handle, "GTA.CreateObject(string)" end
            if handle ~= 0 or not primary_ok or primary_raw ~= 0 then
                -- A positive/unknown result may already have allocated. Do not
                -- stack another backend when the first lifetime is uncertain.
                return uncertain("GTA.CreateObject outcome unknown; fallback withheld")
            end
            Messiah.LogOnce("create-primary-failure",
                ("Messiah creation failure: activation=%d native=GTA.CreateObject hash=n/a "
                    .. "backend=GTA.CreateObject(string) model_u32=%s model_s32=%s "
                    .. "pcall=%s raw=%s handle=%s entity_exists=%s.")
                :format(state.activation_id, tostring(u32), tostring(s32),
                    tostring(primary_ok), Messiah.RawValue(primary_raw), tostring(handle),
                    tostring(exists)))
        else
            primary_raw = "GTA.CreateObject unavailable"
            Messiah.LogOnce("create-primary-failure",
                ("Messiah creation failure: activation=%d native=GTA.CreateObject hash=n/a "
                    .. "backend=GTA.CreateObject(string) model_u32=%s model_s32=%s "
                    .. "pcall=false raw=%s handle=0 entity_exists=false.")
                :format(state.activation_id, tostring(u32), tostring(s32),
                    Messiah.RawValue(primary_raw)))
        end

        if H.CREATE_OBJECT_NO_OFFSET then
            local handle_value, fallback_raw, fallback_error = invoke_int_detail(
                H.CREATE_OBJECT_NO_OFFSET, s32, x, y, z, true, true, true, 0)
            if not current() then return uncertain("native-returned-after-context-ended") end
            local handle, classification = Messiah.NormalizeEntityHandle(handle_value)
            Messiah.ReportRejectedEntityHandle("TryCreateOrb.CREATE_OBJECT_NO_OFFSET",
                handle_value, classification,
                "DOES_ENTITY_EXIST/0x7239B21A38F536BA",
                "fallback creation result rejected before readback")
            local exists = handle ~= 0 and entity_exists(handle)
            if exists and current() then return handle, "CREATE_OBJECT_NO_OFFSET" end
            if handle ~= 0 or fallback_error ~= nil or fallback_raw ~= 0 then
                return uncertain("native-allocation-outcome-unknown")
            end
            Messiah.LogOnce("create-fallback-failure",
                ("Messiah creation failure: activation=%d native=CREATE_OBJECT_NO_OFFSET hash=%s "
                    .. "backend=Natives.InvokeInt model_u32=%s model_s32=%s raw=%s "
                    .. "error=%s handle=%s entity_exists=%s.")
                :format(state.activation_id, Messiah.MODEL_NATIVE_NAMES.CREATE_OBJECT_NO_OFFSET,
                    tostring(u32), tostring(s32), Messiah.RawValue(fallback_raw),
                    tostring(fallback_error), tostring(handle),
                    tostring(exists)))
            return 0, ("primary_raw=%s fallback_raw=%s fallback_error=%s fallback_handle=%s")
                :format(Messiah.RawValue(primary_raw), Messiah.RawValue(fallback_raw),
                    tostring(fallback_error), tostring(handle))
        end
        return 0, ("primary_raw=%s fallback=CREATE_OBJECT_NO_OFFSET unavailable")
            :format(Messiah.RawValue(primary_raw))
    end

    function Messiah.AttachOrbFx(handle, info, now)
        local state = Messiah.State()
        info.fx = type(info.fx) == "table" and info.fx or {}
        if info.fx_attempted then return #info.fx > 0 end
        if now >= (tonumber(info.fx_deadline_ms) or now)
            or (info.fx_failures or 0) >= 3 or not info.lease or info.lease.state ~= "live" then
            info.fx_attempted = true
            Messiah.RecordFxTransport("orb-completion", "networked-particles", #info.fx == 2)
            return #info.fx > 0
        end
        if now < (info.fx_next_attempt_ms or 0)
            or (state.fx_start_frame == state.entity_frame
                and (state.fx_starts_this_frame or 0) >= Messiah.MAX_FX_STARTS_PER_FRAME) then
            return #info.fx > 0
        end
        info.fx_next_attempt_ms = now + 100
        -- Newly created objects can take a few ticks to receive their network
        -- identity. Keep this pending instead of permanently hiding the Orb.
        if not Messiah.FxEntityReady(info.lease) then return #info.fx > 0 end
        local core = #info.fx == 0
        local asset = core and Messiah.ORB_FX_ASSET or Messiah.ENERGY_FX_ASSET
        if not invoke_bool(H.HAS_NAMED_PTFX_ASSET_LOADED, asset) then return #info.fx > 0 end
        local fx = Messiah.StartLoopedFxOnEntity(handle, asset,
            core and Messiah.ORB_FX_EFFECT or Messiah.ENERGY_FX_EFFECT,
            core and 0.32 or 0.22, core and { 0.65, 0.90, 1.00 } or { 0.10, 0.45, 1.00 },
            core and "orb-energy-core" or "orb-energy-trail", 0, 0, 0, info.lease)
        if fx then
            info.fx[#info.fx + 1] = fx
        else
            info.fx_failures = (info.fx_failures or 0) + 1
        end
        info.fx_attempted = #info.fx >= 2
        return #info.fx > 0
    end

    function Messiah.ConfigureOrb(handle, info, ped)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        info.configured, info.collision_armed = false, false
        handle = Messiah.NormalizeEntityHandle(handle)
        if handle == 0 then return false end
        if info.fresh_creation == true then
            info.cleanup_identity = info.cleanup_identity or {
                epoch = epoch,
                action_serial = info.action_serial,
                creation_serial = info.creation_serial,
                kind = "object",
                source = "orb-creation"
            }
        end
        local lease, acquire_reason = info.lease, nil
        if not lease then
            lease, acquire_reason = Messiah.AcquireEntityLease(handle, "object", {
                source = "carrier",
                owned = true,
                fresh_creation = info.fresh_creation == true,
                creation_serial = info.creation_serial,
                action = "ORB",
                action_serial = info.action_serial
            })
        end
        if not Messiah.ActivationContextCurrent(state, epoch) then
            local evidence = Messiah.RecordCleanupEvidence(info.cleanup_identity, "orb-admission-scope-ended", false)
            if evidence then evidence.scope = "ended" end
            Messiah.RetireEntityLease(lease, "orb-admission-scope-ended", false)
            return false
        end
        info.lease = lease
        if not lease or not Messiah.ValidateEntityLease(lease, "configure-orb", "none") then
            if not lease and info.fresh_creation == true then
                Messiah.RecordCleanupEvidence(info.cleanup_identity, "positive-create-without-safe-lease", false)
            end
            info.configure_failure = tostring(acquire_reason or (lease and lease.reason) or "lease-invalid")
            Messiah.ReportFailure("Orb configuration", info.configure_failure)
            return false
        end
        local expected_u32 = Messiah.NormalizeHash(Messiah.ORB_MODEL)
        local observed, observed_raw, observed_error = Messiah.LeaseInvoke(lease, "int", "GET_ENTITY_MODEL",
            H.GET_ENTITY_MODEL, handle)
        local observed_u32 = Messiah.NormalizeHash(observed)
        if observed_error or observed_u32 ~= expected_u32 then
            Messiah.LogOnce("entity-readback-failure",
                ("Messiah Fire Orb readback failed: activation=%d handle=%s backend=%s "
                    .. "native=GET_ENTITY_MODEL hash=%s expected_u32=%s observed_raw=%s "
                    .. "observed_u32=%s error=%s.")
                :format(Messiah.State().activation_id, tostring(handle), tostring(info.backend),
                    Messiah.MODEL_NATIVE_NAMES.GET_ENTITY_MODEL, tostring(expected_u32), Messiah.RawValue(observed_raw),
                    tostring(observed_u32), tostring(observed_error)))
            return false
        end
        local function configure(name, hash, ...)
            local accepted, _, err = Messiah.LeaseInvoke(lease, "void", name, hash, ...)
            if accepted ~= true or err then
                info.configure_failure = name .. ": " .. tostring(err or "native-rejected")
                Messiah.ReportFailure("Orb configuration", info.configure_failure)
                return false
            end
            return true
        end
        if not configure("SET_ENTITY_AS_MISSION_ENTITY", H.SET_ENTITY_AS_MISSION_ENTITY, handle, true, true)
            or not configure("SET_ENTITY_DYNAMIC", H.SET_ENTITY_DYNAMIC, handle, true)
            or not configure("SET_ENTITY_HAS_GRAVITY", H.SET_ENTITY_HAS_GRAVITY, handle, false)
            or not configure("SET_ENTITY_MAX_SPEED", H.SET_ENTITY_MAX_SPEED, handle,
                math.max(200.0, (tonumber(info.speed) or 72.0) * 1.25)) then
            return false
        end
        -- Exclude the caster, initialize velocity, then arm immediately.
        if not configure("SET_ENTITY_COLLISION", H.SET_ENTITY_COLLISION, handle, false, false)
            or not configure("SET_ENTITY_RECORDS_COLLISIONS", H.SET_ENTITY_RECORDS_COLLISIONS, handle, true)
            or not configure("SET_ENTITY_NO_COLLISION_ENTITY", H.SET_ENTITY_NO_COLLISION_ENTITY,
                handle, ped, false) then
            return false
        end
        local speed = tonumber(info.speed) or 72.0
        if not configure("SET_ENTITY_VELOCITY", H.SET_ENTITY_VELOCITY, handle,
                (tonumber(info.direction_x) or 0.0) * speed,
                (tonumber(info.direction_y) or 1.0) * speed,
                (tonumber(info.direction_z) or 0.0) * speed) then
            return false
        end
        Messiah.AttachOrbFx(handle, info, now_ms())
        -- prop_bskball_01 is now only the verified physics/collision carrier.
        -- Hiding occurs strictly after entity/model readback so a bad handle can
        -- never be disguised as a successful creation.
        if not configure("SET_ENTITY_ALPHA", H.SET_ENTITY_ALPHA, handle, 0, false)
            or not configure("SET_ENTITY_COLLISION", H.SET_ENTITY_COLLISION, handle, true, true) then
            return false
        end
        info.configured, info.collision_armed, info.configure_failure = true, true, nil
        info.last_velocity_ms = tonumber(info.born_ms) or now_ms()
        if info.readback_logged ~= true then
            info.readback_logged = true
            Messiah.LogOnce("created-entity-readback",
                ("Messiah Fire Orb created: activation=%d handle=%s exists=true backend=%s "
                    .. "expected_model_u32=%s observed_model_raw=%s observed_model_u32=%s carrier_alpha=0.")
                :format(Messiah.State().activation_id, tostring(handle), tostring(info.backend),
                    tostring(expected_u32), Messiah.RawValue(observed_raw), tostring(observed_u32)))
        end
        return true
    end

    function Messiah.FireOrb(now, ped)
        local state = Messiah.State()
        local epoch, action = state.activation_epoch, state.action
        local function current() return Messiah.ActionContextCurrent(state, epoch, action, "ORB") end
        if not current() then return false end
        now = tonumber(now) or now_ms()
        if not current() then return false end
        if not entity_exists(ped) then return Messiah.ReportFailure("Fire Orb", "local ped is unavailable") end
        if not current() then return false end
        if not Messiah.ModelUsable() then return false end
        if not current() then return false end
        if Messiah.ProjectileCount() >= Messiah.MAX_ORBS then
            local oldest = Messiah.OldestProjectile()
            if oldest then Messiah.CleanupProjectile(oldest, "max-count", false) end
            if not current() then return false end
            if Messiah.ProjectileCount() >= Messiah.MAX_ORBS then
                return Messiah.ReportFailure("Fire Orb capacity",
                    "oldest orb cleanup is pending; cast deferred at max count")
            end
        end

        state.spawn_attempts = state.spawn_attempts + 1
        local dx, dy, dz = Messiah.CameraDirection()
        if not current() then return false end
        local release_right = state.action and state.action.ability == "ORB"
            and state.cast_hand_right or state.right_hand
        local bone = release_right and 57005 or 18905
        state.right_hand = not release_right
        local hand = invoke_vec3(GET_PED_BONE_COORDS, ped, bone, 0.0, 0.0, 0.0)
        if not current() then return false end
        local x, y, z = vector_components(hand)
        if not x then
            local coords = invoke_vec3(H.GET_ENTITY_COORDS, ped, false)
            if not current() then return false end
            x, y, z = vector_components(coords)
            if not x then return Messiah.ReportFailure("Fire Orb", "spawn coordinates are unavailable") end
            z = z + 1.0
        end
        local locked = state.action and Messiah.CopyPoint(state.action.target) or nil
        if locked then
            local tx, ty, tz = locked.x - x, locked.y - y, locked.z - z
            local length = math.sqrt(tx * tx + ty * ty + tz * tz)
            if length > 0.001 then dx, dy, dz = tx / length, ty / length, tz / length end
        end
        x, y, z = x + dx * 1.15, y + dy * 1.15, z + dz * 1.15
        local orb, backend = Messiah.TryCreateOrb(x, y, z)
        if not current() then return false end
        if orb == 0 then
            Messiah.SetCreationState("CREATE_FAILED", tostring(backend))
            return Messiah.ReportFailure("Fire Orb spawn", backend)
        end

        local speed = math.max(25.0, math.min(160.0, slider_float("messiah_orb_speed", 72.0)))
        if not current() then return false end
        local info = {
            fx = {},
            fresh_creation = true,
            creation_serial = state.spawn_attempts,
            fx_attempted = false,
            fx_deadline_ms = now + Messiah.ASSET_TIMEOUT_MS,
            born_ms = now,
            ped = ped,
            direction_x = dx,
            direction_y = dy,
            direction_z = dz,
            speed = speed,
            backend = backend,
            configured = false,
            collision_armed = false,
            last_velocity_ms = now,
            readback_logged = false,
            delete_attempts = 0,
            delete_next_ms = 0,
            action_serial = state.action and state.action.serial or state.action_serial,
        }
        state.projectiles[orb] = info
        local configured = Messiah.ConfigureOrb(orb, info, ped)
        if not current() then return false end
        if not configured then
            Messiah.SetCreationState("CREATE_FAILED",
                "handle failed entity/configuration readback backend=" .. tostring(backend))
            Messiah.CleanupProjectile(orb, "configuration-failed", false, true)
            return Messiah.ReportFailure("Fire Orb spawn",
                "creation returned no configurable entity (backend=" .. tostring(backend)
                .. " reason=" .. tostring(info.configure_failure or "model-readback") .. ")")
        end
        Messiah.SetCreationState("CREATED", "backend=" .. tostring(backend))
        if not current() then return false end
        state.queued_cast = false
        state.reticle_pulse_until_ms = now + 120
        state.spawn_successes = state.spawn_successes + 1
        state.last_error = nil
        Messiah.PlayEntitySound("orb-launch", orb, "DESPAWN",
            "BARRY_01_SOUNDSET", 220, false)
        if not current() then return false end
        if not state.first_orb_logged
            or state.last_cast_logged_speed ~= speed
            or behavior_debug_enabled() then
            state.first_orb_logged = true
            state.last_cast_logged_speed = speed
            log_info(("Messiah Fire Orb cast: activation=%d handle=%s speed=%.1f "
                    .. "direction=(%.4f,%.4f,%.4f) backend=%s attempts=%d successes=%d configured=%s.")
                :format(state.activation_id, tostring(orb), speed, dx, dy, dz, tostring(backend),
                    state.spawn_attempts, state.spawn_successes, tostring(info.configured)))
        end
        return true
    end

    function Messiah.DrawAuroraOrbTrail(info, x, y, z)
        if type(info) ~= "table" then return false end
        local dx, dy, dz = tonumber(info.direction_x) or 0.0,
            tonumber(info.direction_y) or 1.0, tonumber(info.direction_z) or 0.0
        local magnitude = math.sqrt(dx * dx + dy * dy + dz * dz)
        if magnitude < 0.001 then return false end
        dx, dy, dz = dx / magnitude, dy / magnitude, dz / magnitude
        local length = clamp((tonumber(info.speed) or 72.0) * 0.055, 2.4, 6.5)
        local tip = { x = x, y = y, z = z }
        local tail = { x = x - dx * length, y = y - dy * length, z = z - dz * length }
        info.visual_position, info.visual_tail = Messiah.VisualPoint(tip), Messiah.VisualPoint(tail)
        info.visual_frame_ms = Messiah.State().last_tick_ms
        return true
    end

    function Messiah.UpdateProjectiles(now, ped)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local function current() return Messiah.ActivationContextCurrent(state, epoch) end
        if not current() then return false end
        local cleanup = {}
        local live_speed = math.max(25.0, math.min(160.0,
            slider_float("messiah_orb_speed", 72.0)))
        if not current() then return false end
        for handle, info in pairs(state.projectiles) do
            if not current() then return false end
            local lease = info.lease or Messiah.AcquireEntityLease(handle, "object", {
                source = "carrier", owned = true, action = "ORB", action_serial = info.action_serial })
            if not current() then return false end
            info.lease = lease
            local age = now - (tonumber(info.born_ms) or now)
            local normalized_handle, handle_classification =
                Messiah.NormalizeEntityHandle(handle)
            local lease_valid
            if normalized_handle ~= 0 and not info.cleanup_reason then
                lease_valid = lease and Messiah.ValidateEntityLease(lease, "projectile-frame", "none")
                if not current() then return false end
            end
            if normalized_handle == 0 then
                Messiah.ReportRejectedEntityHandle("UpdateProjectiles.carrier", handle,
                    handle_classification, "DOES_ENTITY_EXIST/0x7239B21A38F536BA",
                    "invalid tracked carrier queued for cleanup")
                if not current() then return false end
                cleanup[#cleanup + 1] = {
                    handle = handle, reason = "invalid-carrier", explode = false,
                }
            elseif info.cleanup_reason then
                cleanup[#cleanup + 1] = {
                    handle = handle,
                    reason = info.cleanup_reason,
                    explode = info.cleanup_explode == true,
                }
            elseif not lease_valid then
                if age > Messiah.ORB_SPAWN_GRACE_MS then
                    cleanup[#cleanup + 1] = { handle = handle, reason = "entity-missing", explode = false }
                    Messiah.ReportFailure("Fire Orb entity",
                        "creation returned a handle but no live entity appeared (backend="
                        .. tostring(info.backend) .. ")")
                    if not current() then return false end
                end
            else
                if not current() then return false end
                if info.configured ~= true then Messiah.ConfigureOrb(handle, info, ped) end
                if not current() then return false end
                if info.configured == true then
                    if not info.fx_attempted then Messiah.AttachOrbFx(handle, info, now) end
                    if not current() then return false end
                    Messiah.LeaseInvoke(lease, "void", "SET_ENTITY_NO_COLLISION_ENTITY", H
                        .SET_ENTITY_NO_COLLISION_ENTITY, handle, ped, true)
                    if not current() then return false end
                    local orb_coords = Messiah.LeaseInvoke(lease, "vec3", "GET_ENTITY_COORDS", H.GET_ENTITY_COORDS,
                        handle, false)
                    if not current() then return false end
                    local ox, oy, oz = vector_components(orb_coords)
                    if ox then
                        info.last_position = Messiah.CopyPoint({ x = ox, y = oy, z = oz })
                        Messiah.DrawAuroraOrbTrail(info, ox, oy, oz)
                    end
                    if not info.collision_armed and age >= Messiah.ORB_COLLISION_ARM_MS then
                        if H.SET_ENTITY_COLLISION then
                            Messiah.LeaseInvoke(lease, "void", "SET_ENTITY_COLLISION",
                                H.SET_ENTITY_COLLISION, handle, true, true)
                        end
                        if not current() then return false end
                        info.collision_armed = true
                    end
                    -- The speed slider is live: existing orbs adopt the new value,
                    -- which also prevents basketball drag/network correction from
                    -- silently reducing the requested travel speed.
                    info.speed = live_speed
                    if now - (tonumber(info.last_velocity_ms) or -100000)
                        >= Messiah.ORB_VELOCITY_REFRESH_MS then
                        info.last_velocity_ms = now
                        Messiah.LeaseInvoke(lease, "void", "SET_ENTITY_VELOCITY", H.SET_ENTITY_VELOCITY, handle,
                            (tonumber(info.direction_x) or 0.0) * live_speed,
                            (tonumber(info.direction_y) or 1.0) * live_speed,
                            (tonumber(info.direction_z) or 0.0) * live_speed)
                        if not current() then return false end
                    end
                    local collided = info.collision_armed == true
                        and Messiah.LeaseInvoke(lease, "bool", "HAS_ENTITY_COLLIDED_WITH_ANYTHING",
                            H.HAS_ENTITY_COLLIDED_WITH_ANYTHING, handle)
                    if not current() then return false end
                    if collided then
                        info.impact_position = Messiah.CopyPoint(info.last_position)
                        info.impact_direction_x, info.impact_direction_y, info.impact_direction_z =
                            info.direction_x, info.direction_y, info.direction_z
                        -- HAS_ENTITY_COLLIDED_WITH_ANYTHING includes world geometry.
                        -- Do not call GET_LAST_ENTITY_HIT_BY_ENTITY or acquire a victim.
                        cleanup[#cleanup + 1] = { handle = handle, reason = "impact", explode = true }
                    elseif age >= Messiah.ORB_LIFETIME_MS then
                        cleanup[#cleanup + 1] = { handle = handle, reason = "lifetime", explode = false }
                    end
                end
            end
        end
        for _, item in ipairs(cleanup) do
            Messiah.CleanupProjectile(item.handle, item.reason, item.explode)
            if not current() then return false end
        end
    end

    function Messiah.HasOwnership(state)
        state = state or Messiah.State()
        return state.active == true
            or state.phase ~= Messiah.PHASES.OFF
            or #state.aura > 0
            or #state.temp_fx > 0
            or #state.sounds > 0
            or #state.scheduled_impacts > 0
            or #(state.visuals.beams or {}) > 0
            or #(state.visuals.markers or {}) > 0
            or #(state.visuals.lights or {}) > 0
            or state.channel_beam ~= nil
            or state.aim_guid_hold ~= nil
            or state.shockwave_fronts ~= nil
            or next(state.projectiles) ~= nil
            or next(state.shared_beams) ~= nil
            or state.shared_model_requested == true
            or state.delete_ptr ~= 0
            or state.shape_hit_ptr ~= 0
            or state.shape_end_ptr ~= 0
            or state.shape_normal_ptr ~= 0
            or state.shape_entity_ptr ~= 0
            or next(state.anim_requested) ~= nil
            or next(state.ptfx_requested) ~= nil
            or next(state.animation_started) ~= nil
            or state.model_owned == true
            or state.audio_bank_owned == true
            or next(state.audio_banks_owned) ~= nil
            or state.ragdoll_owned == true
            or state.stance_started == true
            or state.action ~= nil
            or state.pending_ability ~= nil
            or next(state.physical_summaries) ~= nil
            or state.restore_started == true
    end

    function Messiah.WithPedBootstrap(ped, callback)
        local state = Messiah.EntityState()
        ped = Messiah.NormalizeEntityHandle(ped)
        if ped == 0 or state.gameplay_owner ~= true or state.disposed or state.restoring
            or state.ending or state.cleanup_failed or state.bootstrap_owner == true then
            return false, "bootstrap-owner-unavailable"
        end
        state.bootstrap_owner, state.bootstrap_handle = true, ped
        local ok, first, second, third = pcall(callback)
        state.bootstrap_owner, state.bootstrap_handle = false, nil
        return ok, first, second, third
    end

    function Messiah.PedReady(ped)
        local state = Messiah.EntityState()
        ped = Messiah.NormalizeEntityHandle(ped)
        if ped == 0 then return false, "entity-unavailable" end
        local ok, ready, reason, lease = Messiah.WithPedBootstrap(ped, function()
            local candidate = state.active and state.ped == ped and state.ped_lease
                or state.bootstrap_ped_lease
            if not candidate or candidate.handle ~= ped or candidate.epoch ~= state.activation_epoch then
                candidate = Messiah.AcquireEntityLease(ped, "ped",
                    { source = "player-bootstrap", owned = true, action_serial = 0 })
            end
            if not candidate or not Messiah.ValidateEntityLease(candidate, "ped-ready", "none") then
                return false, "entity-unavailable"
            end
            local checked = false
            for _, query in ipairs({ { "IS_ENTITY_DEAD", H.IS_ENTITY_DEAD, false },
                { "IS_PED_DEAD_OR_DYING", H.IS_PED_DEAD_OR_DYING, true } }) do
                if query[2] then
                    local dead, raw, err = Messiah.LeaseInvoke(candidate, "bool", query[1], query[2], ped, query[3])
                    if err or (type(raw) ~= "boolean" and type(raw) ~= "number") then
                        return false, "ped-life-unknown"
                    end
                    if dead == true then
                        -- Death revokes this activation's ped lease. Other owned
                        -- effects still drain; a later respawn acquires a fresh
                        -- lease without tombstoning the physical address.
                        Messiah.RetireEntityLease(candidate, "observed-local-ped-death", false)
                        return false, "ped-dead-or-dying"
                    end
                    checked = true
                end
            end
            if not checked then return false, "ped-life-unknown" end
            return true, "alive", candidate
        end)
        if not ok or ready ~= true then
            state.bootstrap_ped_lease = nil
            return false, tostring(reason or ready or "ped-life-unknown")
        end
        state.bootstrap_ped_lease = lease
        return true, "alive", lease
    end

    -- Unload has no documented gameplay-thread drain hook. Quiesce and disposal
    -- stay Lua-only; FrameTick owns gameplay cleanup. pcall cannot catch a host access violation.
    function Messiah.Quiesce(reason, permanent)
        local state = Messiah.State()
        if state.disposed then return false end
        if not state.restoring then
            state.cleanup_epoch = state.activation_epoch or state.activation_id or 0
            state.activation_epoch = state.cleanup_epoch + 1
            state.restoring, state.ending = true, true
            state.restore_started = true
            state.restore_reason = tostring(reason or "quiesce")
        end
        state.active = false
        if state.action then state.action.ending = true end
        state.cleanup_aim_snapshot = state.cleanup_aim_snapshot or state.aim_snapshot
        state.aim_snapshot = nil
        state.hud_snapshot, state.visual_snapshot, state.visual_build = nil, nil, nil
        state.visual_camera_frame, state.visual_camera_sampled_epoch, state.visual_camera_sampled_frame, state.visual_camera_sampled_ms =
            nil, nil, nil, nil
        state.lance_visual_diagnostics, state.visual_camera_diagnostics = nil, nil
        state.visual_generation = (tonumber(state.visual_generation) or 0) + 1
        state.channel_beam, state.action = nil, nil
        local cancelled_fronts = state.shockwave_fronts
        state.shockwave_fronts = nil
        state.visual_owner_position = nil
        state.audio_bank_pending, state.audio_bank_poll_frame, state.audio_bank_poll_count = nil, nil, nil
        for _, record in ipairs(state.scheduled_impacts) do Messiah.RecordEssentialDrop(record, 0) end
        Messiah.FlushEssentialStages(0)
        if state.lance_sweep_pending then
            -- The engine owns its asynchronous query; the start call receives
            -- no Lua buffers. Revoke this plain token without polling a native
            -- from stop/unload, and never carry it into another activation.
            state.lance_sweep_pending.cancelled = true
            state.lance_sweep_pending.handle = 0
            state.lance_sweep_pending = nil
        end
        state.pending_ability, state.pending_target = nil, nil
        state.pending_source, state.pending_allow_menu = "none", false
        state.queued_cast, state.cast_edge_pending = false, false
        state.scheduled_impacts = {}
        state.visuals = { beams = {}, markers = {}, lights = {} }
        state.attack_down, state.attack_armed = false, false
        state.inputs = {}
        state.shockwave_requested, state.shockwave_released = false, false
        state.phase = Messiah.PHASES.RESTORING
        state.disposed = permanent == true
        if permanent == true then
            state.gameplay_owner, state.cleanup_owner = false, false
        end
        -- Finish captured detached accounting only after cleanup has revoked
        -- every live owner. A logging callback cannot adopt a replacement state.
        Messiah.FinishShockwaveDiagnostics(cancelled_fronts, tostring(reason or "quiesce"))
        return true
    end

    function Messiah.FinalDisposal(reason, permanent)
        -- Revoke the old table as well: an already captured callback must not
        -- retain a live action/snapshot merely because State now points elsewhere.
        Messiah.Quiesce(reason or "disposal", permanent)
        local state = type(State.messiah) == "table" and State.messiah or {}
        if state.aim_guid_hold then
            Messiah.AbandonAimGuid(state.aim_guid_hold, state, "final-disposal")
            state.aim_guid_hold = nil
        end
        -- Capture every outstanding owned allocation before clearing live tables.
        -- These records contain no handles, addresses, userdata or callbacks.
        for _, record in pairs(state.shared_beams or {}) do
            Messiah.RecordCleanupEvidence(record.lease or record.cleanup_identity,
                "disposal-before-removal:" .. tostring(reason), false)
            Messiah.RetireEntityLease(record.lease, "final-disposal", false)
        end
        for _, record in pairs(state.projectiles or {}) do
            Messiah.RecordCleanupEvidence(record.lease or record.cleanup_identity,
                "disposal-before-removal:" .. tostring(reason), false)
            Messiah.RetireEntityLease(record.lease, "final-disposal", false)
        end
        Messiah.LogCleanupEvidence(reason)
        -- Never free native buffers or chase game objects from an unload worker.
        -- The host owns script teardown. A stopped gameplay owner may abandon
        -- transient GTA effects rather than risking a second fault.
        State.messiah = {
            activation_id = tonumber(state.activation_id) or 0,
            activation_epoch = tonumber(state.activation_epoch) or 0,
            entity_frame = tonumber(state.entity_frame) or 0,
            gameplay_owner = permanent ~= true and state.gameplay_owner == true,
            disposed = permanent == true,
            active = false,
            ending = false,
            restoring = false,
            phase = Messiah.PHASES.OFF,
            respawn_blocked_ped = tonumber(state.respawn_blocked_ped) or 0,
            visual_generation = (tonumber(state.visual_generation) or 0) + 1,
            last_disposal_reason = tostring(reason or "disposal"),
            cleanup_failed = state.cleanup_failed == true,
            entity_breadcrumbs = state.entity_breadcrumbs,
            released_script_guids = state.released_script_guids,
            released_script_guid_count = state.released_script_guid_count,
            script_guid_release_serial = state.script_guid_release_serial,
            script_guid_capacity_blocked = state.script_guid_capacity_blocked,
        }
        state.gameplay_owner, state.cleanup_owner = false, false
        state.active, state.disposed = false, true
        state.action, state.channel_beam = nil, nil
        state.lance_sweep_pending = nil
        state.shockwave_fronts, state.essential_stages = nil, nil
        state.visual_owner_position = nil
        state.audio_bank_pending, state.audio_bank_poll_frame, state.audio_bank_poll_count = nil, nil, nil
        state.hud_snapshot, state.visual_snapshot, state.visual_build = nil, nil, nil
        state.aim_snapshot, state.cleanup_aim_snapshot = nil, nil
        state.scheduled_impacts, state.sounds, state.projectiles = {}, {}, {}
        state.aura, state.temp_fx, state.audio_banks_owned = {}, {}, {}
        state.shared_beams, state.shared_model_requested = {}, false
        return true
    end

    function Messiah.CleanupInvoke(name, hash, ...)
        local state = Messiah.State()
        if state.gameplay_owner ~= true or state.cleanup_owner ~= true
            or state.cleanup_failed == true or state.disposed == true then
            error("Messiah cleanup owner unavailable: " .. tostring(name), 0)
        end
        if not hash then return false end
        local accepted, _, detail = invoke_void_detail(hash, ...)
        if accepted ~= true then
            state.cleanup_failed = true
            error("Messiah cleanup stopped at " .. tostring(name) .. ": " .. tostring(detail), 0)
        end
        return true
    end

    function Messiah.DrainGameplayCleanup()
        local state = Messiah.State()
        if state.gameplay_owner ~= true or state.disposed == true
            or state.restoring ~= true or state.cleanup_owner == true then
            return false
        end
        state.cleanup_owner = true
        local reason = state.restore_reason
        local function drain()
            -- Consume each owned record BEFORE a fallible stop. Never retry a
            -- possibly completed stop/release when the host returned an error.
            local function stop_fx(record)
                local handle = Messiah.FxHandle(record)
                if type(record) == "table" then record.handle = 0 end
                if handle ~= 0 then
                    Messiah.CleanupInvoke("STOP_PARTICLE_FX_LOOPED", H.STOP_PARTICLE_FX_LOOPED, handle, false)
                end
            end
            for index = #state.sounds, 1, -1 do
                Messiah.ReleaseOwnedSound(state.sounds[index], "gameplay-cleanup")
                table.remove(state.sounds, index)
            end
            local beam_keys = {}
            for key in pairs(state.shared_beams) do beam_keys[#beam_keys + 1] = key end
            for _, key in ipairs(beam_keys) do
                for _ = 1, 3 do
                    if not state.shared_beams[key] then break end
                    Messiah.StopSharedBeam(key)
                end
            end
            local aura, temp_fx = state.aura, state.temp_fx
            state.aura, state.temp_fx = {}, {}
            for _, record in ipairs(aura) do stop_fx(record) end
            for _, record in ipairs(temp_fx) do stop_fx(record) end
            -- Carrier effects are detached before bounded carrier deletion. No
            -- collision victim is retained by a shutdown transaction.
            local handles = {}
            for handle, info in pairs(state.projectiles) do
                handles[#handles + 1] = handle
                for _, record in ipairs(info.fx or {}) do stop_fx(record) end
                info.fx = {}
            end
            for _, handle in ipairs(handles) do
                for _ = 1, Messiah.ORB_DELETE_MAX_ATTEMPTS do
                    if not state.projectiles[handle] then break end
                    Messiah.CleanupProjectile(handle, "restore", false, true)
                    if state.cleanup_failed then error("projectile cleanup aborted", 0) end
                end
            end
            -- Revalidate the owned local ped lease at every setter. A death,
            -- ped change or retired identity skips ped restoration safely.
            local ped_lease = state.ped_lease
            if ped_lease and Messiah.NormalizeEntityHandle(local_ped()) == state.ped then
                Messiah.ObserveMotionRelease(state.ped, now_ms())
                for key, animation in pairs(state.animation_started) do
                    state.animation_started[key] = nil
                    local accepted = Messiah.LeaseInvoke(ped_lease, "void", "STOP_ANIM_TASK",
                        H.STOP_ANIM_TASK, state.ped, animation.dict, animation.name, -4.0)
                    if accepted ~= true then break end
                end
                if state.ragdoll_owned then
                    state.ragdoll_owned = false
                    local restore_ragdoll = state.ragdoll_before
                    if is_on("no_ragdoll") then restore_ragdoll = false end
                    Messiah.LeaseInvoke(ped_lease, "void", "SET_PED_CAN_RAGDOLL",
                        H.SET_PED_CAN_RAGDOLL, state.ped, restore_ragdoll)
                end
            end
            Messiah.ReleaseAimEntity("gameplay-cleanup")
            local banks = state.audio_banks_owned
            state.audio_banks_owned = {}
            for bank, owned in pairs(banks) do
                if owned then
                    Messiah.CleanupInvoke("RELEASE_NAMED_SCRIPT_AUDIO_BANK",
                        H.RELEASE_NAMED_SCRIPT_AUDIO_BANK, bank)
                end
            end
            for dict, owned in pairs(state.anim_requested) do
                state.anim_requested[dict] = nil
                if owned then Messiah.CleanupInvoke("REMOVE_ANIM_DICT", H.REMOVE_ANIM_DICT, dict) end
            end
            for asset, owned in pairs(state.ptfx_requested) do
                state.ptfx_requested[asset] = nil
                if owned then Messiah.CleanupInvoke("REMOVE_NAMED_PTFX_ASSET", H.REMOVE_NAMED_PTFX_ASSET, asset) end
            end
            if state.shared_model_requested then
                state.shared_model_requested = false
                local _, model = Messiah.NormalizeHash(Messiah.SHARED_BEAM_MODEL)
                Messiah.CleanupInvoke("SET_MODEL_AS_NO_LONGER_NEEDED", H.SET_MODEL_AS_NO_LONGER_NEEDED, model)
            end
            if state.model_owned then
                state.model_owned = false
                local _, model = Messiah.NormalizeHash(Messiah.ORB_MODEL)
                Messiah.CleanupInvoke("SET_MODEL_AS_NO_LONGER_NEEDED", H.SET_MODEL_AS_NO_LONGER_NEEDED, model)
            end
            if memory and type(memory.Free) == "function" then
                for _, key in ipairs({ "delete_ptr", "shape_hit_ptr", "shape_end_ptr",
                    "shape_normal_ptr", "shape_entity_ptr" }) do
                    local ptr = state[key]
                    state[key] = 0
                    if ptr and ptr ~= 0 then
                        local freed = pcall(memory.Free, ptr)
                        if not freed then error("native-buffer free failed", 0) end
                    end
                end
            end
        end
        local ok, err = pcall(drain)
        state.cleanup_owner = false
        if not ok then state.cleanup_failed = true end
        Messiah.FinalDisposal(ok and reason or "cleanup-aborted:" .. tostring(err), false)
        local complete = ok and messiah_cleanup_evidence.unresolved == 0
        log_info(("Messiah gameplay cleanup: reason=%s complete=%s calls_completed=%s aborted=%s unresolved=%d epoch=%d.")
            :format(tostring(reason), tostring(complete), tostring(ok), tostring(not ok),
                messiah_cleanup_evidence.unresolved, Messiah.State().activation_epoch))
        return complete
    end

    function Messiah.EndSession()
        -- No old-session mutation or fresh handle lookup is valid after this hook.
        messiah_cleanup_evidence.scope_ending = true
        for _, record in ipairs(messiah_cleanup_evidence.records) do record.scope = "ended" end
        Messiah.FinalDisposal("session transition: evidence scope ended", false)
        messiah_cleanup_evidence.scope_ending = nil
    end

    function Messiah.Restore(reason, force)
        local state = Messiah.State()
        if state.disposed then return false end
        if not state.restoring and not Messiah.HasOwnership(state) then return true end
        Messiah.Quiesce(reason, false)
        if state.gameplay_owner == true then return Messiah.DrainGameplayCleanup() end
        -- Feature/session callbacks may request cleanup; only the next actual
        -- gameplay callback can drain. Module.Restore never calls this path.
        return false
    end

    function Messiah.GameplayTick(now, ped)
        local state = Messiah.State()
        if state.disposed or state.gameplay_owner then return false end
        state.gameplay_owner = true
        state.entity_frame = (tonumber(state.entity_frame) or 0) + 1
        local function tick()
            if state.restoring then
                if not Messiah.DrainGameplayCleanup() then return end
                state = Messiah.State()
            end
            if state.cleanup_failed then
                if not is_on("messiah_state") then state.cleanup_failed = false end
                return
            end
            Messiah.Tick(now, ped)
        end
        local ok, err = pcall(tick)
        if not ok then
            Messiah.Quiesce("gameplay-error", false)
            Messiah.State().cleanup_failed = true
            Messiah.FinalDisposal("gameplay-error:" .. tostring(err), false)
            -- No native cleanup follows a fatal/unknown lifecycle condition.
            log_info("Messiah gameplay aborted; visual state quiesced; " .. tostring(err))
        end
        state.gameplay_owner = false
        if type(State.messiah) == "table" then State.messiah.gameplay_owner = false end
        return ok
    end

    function Messiah.Activate(now, ped, caller)
        local state = Messiah.State()
        if state.gameplay_owner ~= true or state.disposed or state.cleanup_failed then return false end
        now = tonumber(now) or now_ms()
        ped = tonumber(ped) or 0
        caller = tostring(caller or "frame-tick")
        if state.active and state.ped == ped then return true end
        if Messiah.HasOwnership(state) then
            if not Messiah.Restore(
                    state.ped ~= ped and "local ped changed" or "stale ownership before activation",
                    true) then
                return false
            end
            state = Messiah.State()
        end
        local ready, _, bootstrap_lease = Messiah.PedReady(ped)
        if not ready then return false end
        local bootstrap_ok, coords = Messiah.WithPedBootstrap(ped, function()
            local seated, raw, err = Messiah.LeaseInvoke(bootstrap_lease, "bool",
                "IS_PED_IN_ANY_VEHICLE", H.IS_PED_IN_ANY_VEHICLE, ped, false)
            if err or (type(raw) ~= "boolean" and type(raw) ~= "number") or seated == true then return nil end
            return Messiah.LeaseInvoke(bootstrap_lease, "vec3", "GET_ENTITY_COORDS", H.GET_ENTITY_COORDS, ped, false)
        end)
        if not bootstrap_ok or not coords then return false end
        local _, _, z = vector_components(coords)
        if not z then return false end
        local hover = math.max(0.5, math.min(8.0, slider_float("messiah_hover_height", 2.2)))
        state.activation_id = state.activation_id + 1
        state.activation_epoch = state.activation_epoch + 1
        state.restoring, state.ending, state.disposed = false, false, false
        state.entity_identities, state.entity_identity_count, state.entity_leases = {}, 0, {}
        state.activation_owner = caller
        state.active, state.ped, state.anchor_z = true, ped, z
        state.ped_lease = Messiah.AcquireEntityLease(ped, "ped",
            { source = "player", owned = true, action_serial = 0, allow_player = true })
        state.bootstrap_ped_lease = nil
        if not state.ped_lease then
            state.active = false; return false
        end
        state.ascent_start_z = z
        state.target_z = z + hover
        state.last_hover_height = hover
        state.last_tick_ms = now
        state.right_hand = true
        state.cast_hand_right = true
        state.move_vx, state.move_vy, state.move_vz = 0.0, 0.0, 0.0
        state.last_floor_z, state.last_floor_ms = nil, nil
        state.motion_requested = false
        state.resume_phase = Messiah.PHASES.IDLE_HOVER
        state.asset_request_initialized, state.asset_deadline_ms = false, 0
        state.anim_requested, state.ptfx_requested = {}, {}
        state.aura, state.aura_attempted, state.aura_alpha, state.next_fx_update_ms = {}, {}, nil, 0
        local ped_model = Messiah.LeaseInvoke(state.ped_lease, "int", "GET_ENTITY_MODEL", H.GET_ENTITY_MODEL, ped)
        if state.ped_lease.state ~= "live" then
            state.active = false; return false
        end
        local ped_model_u32 = Messiah.NormalizeHash(ped_model)
        local female_model_u32 = Messiah.NormalizeHash(utils.Joaat("mp_f_freemode_01"))
        state.anim_variant = ped_model_u32 == female_model_u32 and "female"
            or H.IS_PED_MALE and not Messiah.LeaseInvoke(state.ped_lease, "bool", "IS_PED_MALE", H.IS_PED_MALE, ped)
            and "female" or "male"
        if state.ped_lease.state ~= "live" then
            state.active = false; return false
        end
        state.idle_candidate_index = 1
        state.animation_current, state.animation_started = "none", {}
        state.animation_next_check_ms, state.animation_repairs = 0, 0
        state.animation_last_reason = "none"
        state.idle_task_pending, state.idle_task_started_ms = false, 0
        state.idle_candidates_exhausted = false
        state.idle_retry_passes, state.idle_retry_ms = 0, nil
        state.lance_contacts_serial, state.lance_contacts = nil, {}
        state.stance_started = false
        state.model_state = "UNAVAILABLE"
        state.creation_state = "UNAVAILABLE"
        state.model_requested, state.model_owned = false, false
        state.model_requested_ms, state.model_deadline_ms = 0, 0
        state.model_next_poll_ms, state.model_poll_count = 0, 0
        state.queued_cast, state.cast_edge_pending = false, false
        state.pending_ability, state.pending_target = nil, nil
        state.pending_source, state.pending_allow_menu = "none", false
        state.action, state.action_serial, state.impact_serial = nil, 0, 0
        state.damage_evidence, state.damage_evidence_order = {}, {}
        state.impact_pool_cursor = { vehicle = 0, ped = 0, object = 0 }
        state.impact_control_attempt_ms, state.impact_control_attempt_order = {}, {}
        state.physical_summaries = {}
        state.terminal_vehicle_registry, state.terminal_vehicle_counts = {}, {}
        state.terminal_vehicle_order = {}
        state.destructive_accent_registry, state.destructive_accent_order = {}, {}
        state.schedule_serial = 0
        state.scheduled_impacts = {}
        state.visuals = { beams = {}, markers = {}, lights = {} }
        state.channel_beam = nil
        state.temp_fx = {}
        state.shared_beams, state.shared_beam_serial = {}, 0
        state.shared_model_requested, state.shared_model_ready, state.shared_model_failed = false, false, false
        state.shared_model_poll_ms, state.shared_create_frame = 0, nil
        state.fx_session_frame, state.fx_start_frame, state.fx_tokens, state.fx_token_ms = nil, nil, 4, now
        state.fx_transport_attempts, state.fx_transport_accepted, state.fx_transport_failed = 0, 0, 0
        state.fx_transport_uncertain = 0
        state.fx_transport_warned, state.next_lance_energy_ms = false, 0
        state.sounds, state.audio_banks_owned, state.audio_bank_owned = {}, {}, false
        state.no_ground_until_ms, state.no_ground_ability = 0, "none"
        state.hud_snapshot, state.last_target, state.last_target_source = nil, nil, "none"
        state.aim_snapshot, state.reticle_mode = nil, "UNINITIALIZED"
        state.reticle_mode_until_ms, state.reticle_pulse_until_ms = 0, 0
        state.mouse_stale, state.mouse_disagree_since_ms, state.mouse_disagree_samples = false, 0, 0
        state.input_edge_serial = 0
        state.cast_released = false
        state.shockwave_requested, state.shockwave_released = false, false
        local heading = H.GET_ENTITY_HEADING and Messiah.LeaseInvoke(state.ped_lease,
            "float", "GET_ENTITY_HEADING", H.GET_ENTITY_HEADING, ped)
        state.heading = tonumber(heading)
        state.last_error = nil
        state.failure_seen = {}
        state.diagnostic_seen = {}
        state.cleanup_seen = {}
        state.first_orb_logged = false
        state.last_cast_logged_speed = nil
        state.spawn_attempts = 0
        state.spawn_successes = 0
        state.restore_started, state.restore_reason, state.restore_cleanup_summary, state.restoring =
            false, "unspecified", nil, false
        Messiah.InitializeInputState(Messiah.MenuOpen())
        state.ragdoll_before = Messiah.LeaseInvoke(state.ped_lease, "bool", "CAN_PED_RAGDOLL", H.CAN_PED_RAGDOLL, ped)
        if state.ped_lease.state ~= "live" then
            state.active = false; return false
        end
        state.ragdoll_before = Live.ragdoll_baseline_for_messiah(ped, state.ragdoll_before)
        Messiah.SetPhase(Messiah.PHASES.ASCENDING, now, "smooth ascent")
        Messiah.InitializeAssets(now)
        state.ragdoll_owned = type(state.ragdoll_before) == "boolean" and
            Messiah.LeaseInvoke(state.ped_lease, "void", "SET_PED_CAN_RAGDOLL", H.SET_PED_CAN_RAGDOLL, ped, false) ==
            true
        if state.ped_lease.state ~= "live" then
            state.active = false; return false
        end
        if state.attack_down then
            Messiah.Trace(("Messiah input activation safety: activation=%d source=%s down=true armed=false; release required.")
                :format(state.activation_id, state.attack_source))
        end
        toast("Messiah awakened: LMB Orb, hold RMB Lance, Q Rupture, E Shockwave, R Judgment.",
            7000, "success")
        log_info(("Messiah state activated: activation=%d owner=%s ped=%s baseZ=%.2f targetZ=%.2f "
                .. "hover=%.2f phase=%s attackDown=%s attackArmed=%s revision=17.75 enginePhysics=true.")
            :format(state.activation_id, caller, tostring(ped), z, state.target_z, hover,
                state.phase, tostring(state.attack_down), tostring(state.attack_armed)))
        return true
    end

    function Messiah.BaseMotionPhase(state)
        state = state or Messiah.State()
        local speed = math.sqrt(state.move_vx * state.move_vx + state.move_vy * state.move_vy)
        return (state.motion_requested or speed > 0.18)
            and Messiah.PHASES.GLIDING or Messiah.PHASES.IDLE_HOVER
    end

    function Messiah.AbilityPhase(ability, stage)
        return Messiah.PHASES[tostring(ability) .. "_" .. tostring(stage)]
    end

    function Messiah.RequestAbility(ability, now, caller, allow_menu)
        local state = Messiah.State()
        now = tonumber(now) or now_ms()
        ability = tostring(ability or ""):upper()
        caller = tostring(caller or "unknown")
        local config = Messiah.ABILITIES[ability]
        if not config then return false end
        if not is_on("messiah_state") or not state.active or not Messiah.PedReady(state.ped) then
            if allow_menu then toast("Enable Messiah State on foot first.", 4500, "warning") end
            return false
        end
        local lance_override = state.action and state.action.ability == "LANCE"
            and state.action.ending == true and state.pending_ability == nil
            and (ability == "RUPTURE" or ability == "SHOCKWAVE" or ability == "SUPER")
        if (state.action or state.pending_ability) and not lance_override then
            Messiah.Trace(("Messiah ability rejected: activation=%d ability=%s caller=%s "
                    .. "reason=action-busy active=%s pending=%s.")
                :format(state.activation_id, ability, caller,
                    state.action and state.action.ability or "none",
                    tostring(state.pending_ability or "none")))
            return false
        end
        if not lance_override and state.phase ~= Messiah.PHASES.IDLE_HOVER
            and state.phase ~= Messiah.PHASES.GLIDING then
            Messiah.Trace(("Messiah ability rejected: activation=%d ability=%s caller=%s "
                    .. "reason=phase-busy phase=%s.")
                :format(state.activation_id, ability, caller, state.phase))
            return false
        end
        local target, source, resolved_lease
        if config.target == "DIRECT" and type(state.aim_snapshot) == "table"
            and now - (tonumber(state.aim_snapshot.now_ms) or -100000) <= 100 then
            target = Messiah.CopyPoint(state.aim_snapshot.target)
            source = state.aim_snapshot.source
        else
            target, source = Messiah.ResolveAimTarget(config.target, ability)
            if config.target == "DIRECT" and type(target) == "table"
                and target.entity_retained == true then
                resolved_lease = target
            end
        end
        target = Messiah.CopyPoint(target)
        if resolved_lease then
            -- A copied point does not own the borrowed shape-test GUID.  The
            -- ordinary frame path keeps the aim lease alive through the
            -- consumer; this defensive resolver fallback is coordinate-only.
            if target then target.entity = 0 end
            for _ = 1, 3 do
                if Messiah.ReleaseShapeEntity(resolved_lease,
                        "ability-target-coordinate-fallback") then
                    break
                end
            end
        end
        if not target then
            if config.target == "GROUND" then
                state.no_ground_until_ms = now + 1800
                state.no_ground_ability = ability
                Messiah.SetReticleMode("GROUND_INVALID", state.no_ground_until_ms,
                    "ability=" .. ability .. " source=" .. tostring(source))
                toast("NO GROUND TARGET", 2200, "warning")
            end
            Messiah.Trace(("Messiah ability rejected: activation=%d ability=%s caller=%s "
                    .. "reason=%s targetMode=%s source=%s noPedFallback=true.")
                :format(state.activation_id, ability, caller,
                    config.target == "GROUND" and "NO_GROUND_TARGET" or "NO_AIM_TARGET",
                    config.target, tostring(source)))
            return false
        end

        state.last_target = Messiah.CopyPoint(target)
        state.last_target_source = tostring(source or target.source or "unknown")
        if config.target == "GROUND" then
            state.no_ground_until_ms, state.no_ground_ability = 0, "none"
            Messiah.SetReticleMode("GROUND_VALID",
                now + math.max(900, config.windup + config.release),
                ("ability=%s target=(%.2f,%.2f,%.2f)")
                :format(ability, target.x, target.y, target.z))
        end
        state.pending_ability = ability
        state.pending_target = Messiah.CopyPoint(target)
        state.pending_source = caller
        state.pending_allow_menu = allow_menu == true
        if ability == "ORB" and not Messiah.ModelUsable() then
            if state.model_state == "REQUESTED" or state.model_state == "LOADING" then
                state.queued_cast = true
                Messiah.Trace(("Messiah ability accepted: activation=%d ability=ORB caller=%s "
                        .. "queued=true queueDepth=1 modelState=%s locked=(%.2f,%.2f,%.2f) source=%s.")
                    :format(state.activation_id, caller, state.model_state,
                        target.x, target.y, target.z, state.last_target_source))
                return true
            end
            state.pending_ability, state.pending_target = nil, nil
            state.pending_source, state.pending_allow_menu = "none", false
            return Messiah.ReportFailure("Fire Orb",
                ("model_state=%s model_u32=%s backend=%s")
                :format(state.model_state, tostring((Messiah.NormalizeHash(Messiah.ORB_MODEL))),
                    "GTA.CreateObject(string)"))
        end
        Messiah.Trace(("Messiah ability accepted: activation=%d ability=%s caller=%s targetMode=%s "
                .. "locked=(%.2f,%.2f,%.2f) source=%s gate=action-lifecycle-only.")
            :format(state.activation_id, ability, caller, config.target,
                target.x, target.y, target.z, state.last_target_source))
        return true
    end

    function Messiah.BeginAbility(now, ability, target, caller)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        if not Messiah.ActivationContextCurrent(state, epoch) then return false end
        local config = Messiah.ABILITIES[ability]
        target = Messiah.CopyPoint(target)
        if not config or not target then return false end
        state.action_serial = state.action_serial + 1
        state.resume_phase = Messiah.BaseMotionPhase(state)
        state.cast_hand_right = state.right_hand
        state.action = {
            serial = state.action_serial,
            ability = ability,
            target = target,
            caller = tostring(caller or "unknown"),
            released = false,
            accepted_ms = now,
            epoch = state.activation_epoch,
            press_target = { x = target.x, y = target.y, z = target.z },
            legitimate_lance_press = ability == "LANCE" and caller == "key:RMB",
            press_direct_hit = target.direct_hit == true
                or (state.aim_snapshot and state.aim_snapshot.direct_hit == true),
            ending = false,
            cleanup_done = false,
            next_impact_ms = now,
            impact_ticks = 0,
            damage_registry = {},
        }
        local action = state.action
        local function current() return Messiah.ActionContextCurrent(state, epoch, action, ability) end
        state.cast_released, state.shockwave_released = false, false
        Messiah.SetPhase(Messiah.AbilityPhase(ability, "WINDUP"), now,
            "ability=" .. ability .. " caller=" .. tostring(caller or "unknown"))
        if not current() then return false end
        Messiah.StartChargeCue(now, state.ped, ability)
        if not current() then return false end
        if ability == 'ORB' and Messiah.EntityOwner(state.ped_lease) then
            local hand = Messiah.LanceHandPoint(state.ped, state.cast_hand_right)
            if not current() then return false end
            state.action.visual_charge_position = Messiah.VisualPoint(hand)
        end
        Messiah.PlayChargeAudio(ability, target, config.windup + 100)
        if not current() then return false end
        if ability == "RUPTURE" then
            Messiah.SetReticleMode("GROUND_VALID", now + config.windup + config.release,
                "ability=RUPTURE action-begun fixed-target")
            if not current() then return false end
            state.action.crack_record = Messiah.AddCracks(now, target, 5.8, config.windup + 1050, { 112, 58, 244 }, 8)
            if not current() then return false end
            if state.action.crack_record then state.action.crack_record.release_ms = now + config.windup end
            state.action.ground_marker = true
        elseif ability == "SUPER" then
            Messiah.SetReticleMode("GROUND_VALID", now + config.windup + config.release,
                "ability=SUPER action-begun fixed-target")
            if not current() then return false end
            local marked = Messiah.AddMarker(now, target, 0.65, 3.8, config.windup, { 92, 58, 228 }, 220)
            if not current() then return false end
            if marked then
                local mark = state.visuals.markers[#state.visuals.markers]
                mark.kind, mark.local_only, mark.presentation_priority = 'judgment-compression', true, 75
                mark.owner_epoch, mark.owner_action_serial = state.activation_epoch, state.action_serial
            end
            state.action.ground_marker = true
            Messiah.AddLight(now, target, 18.0, 4.8, config.windup,
                { 88, 176, 255 })
            if not current() then return false end
            log_info(("Messiah Judgment stage: activation=%d actionSerial=%d stage=MARK "
                    .. "locked=(%.2f,%.2f,%.2f) duration_ms=%d.")
                :format(state.activation_id, state.action_serial,
                    target.x, target.y, target.z, config.windup))
            if not current() then return false end
        end
        if state.action.ground_marker then
            log_info(("Messiah ground marker accepted: activation=%d actionSerial=%d ability=%s "
                    .. "fixed=(%.2f,%.2f,%.2f) lifetimeMs=%d owner=action-target.")
                :format(state.activation_id, state.action_serial, ability,
                    target.x, target.y, target.z, config.windup))
            if not current() then return false end
        end
        log_info(("Messiah action begun: activation=%d serial=%d ability=%s phase=%s "
                .. "hand=%s locked=(%.2f,%.2f,%.2f).")
            :format(state.activation_id, state.action_serial, ability, state.phase,
                state.cast_hand_right and "right" or "left", target.x, target.y, target.z))
        return true
    end

    function Messiah.Shockwave()
        return Messiah.RequestAbility("SHOCKWAVE", now_ms(), "menu-button", true)
    end

    function Messiah.LanceHandPoint(ped, right_hand)
        local bone = right_hand and 57005 or 18905
        local hand = invoke_vec3(GET_PED_BONE_COORDS, ped, bone, 0.0, 0.0, 0.0)
        local x, y, z = vector_components(hand)
        if not x then
            local coords = invoke_vec3(H.GET_ENTITY_COORDS, ped, false)
            x, y, z = vector_components(coords)
            if not x then return nil end
            z = z + 1.0
        end
        return { x = x, y = y, z = z }, bone
    end

    function Messiah.LanceContactPoint(now, hand, target, action)
        local state = Messiah.State()
        if not Messiah.EntityOwner() or state.ending or state.restoring or state.cleanup_owner then
            return nil, "not-gameplay-owner"
        end
        local active = action and action == state.action and action.ability == "LANCE"
            and not action.ending and state.phase == Messiah.PHASES.LANCE_CHANNEL
        hand, target = Messiah.CopyPoint(hand), Messiah.CopyPoint(target)
        hand = hand and { x = hand.x, y = hand.y, z = hand.z }
        target = target and { x = target.x, y = target.y, z = target.z }
        active = active and hand ~= nil and target ~= nil
        local pending = state.lance_sweep_pending
        if pending and (not active or pending.epoch ~= state.activation_epoch
                or pending.action_serial ~= action.serial) then
            pending.cancelled = true
        end
        if not H.START_SHAPE_TEST_CAPSULE or not H.GET_SHAPE_TEST_RESULT
            or not Messiah.EnsureShapePointers() then
            return nil, "sweep-unavailable"
        end
        if not pending then
            if not active then return nil, "no-live-channel" end
            if now < (tonumber(action.next_sweep_ms) or 0) then return nil, "cadence" end
            local dx, dy, dz = target.x - hand.x, target.y - hand.y, target.z - hand.z
            local length = math.sqrt(dx * dx + dy * dy + dz * dz)
            if length < 0.05 or length > Messiah.DIRECT_AIM_DISTANCE + 10 then return nil, "invalid-segment" end
            if not state.ped_lease or not Messiah.ValidateEntityLease(state.ped_lease,
                    "lance-capsule-ignore-owner", "START_SHAPE_TEST_CAPSULE") then
                return nil, "owner-unavailable"
            end
            -- Documented asynchronous capsule, not an invented synchronous cast.
            -- One 0.65 m radius sweep follows the actual hand-to-aim beam, at
            -- most once per damage interval; no pool/entity-damage traversal.
            action.next_sweep_ms = now + Messiah.LANCE_IMPACT_INTERVAL_MS
            local handle, raw, err = invoke_int_detail(H.START_SHAPE_TEST_CAPSULE,
                hand.x, hand.y, hand.z, target.x, target.y, target.z, 0.65, 511, state.ped, 7)
            if err or not Messiah.FiniteNumber(handle) or handle <= 0 or handle % 1 ~= 0 then
                return nil, "sweep-start-failed"
            end
            pending = {
                handle = handle,
                epoch = state.activation_epoch,
                action_serial = action.serial,
                started_ms = now,
                from = hand,
                target = target,
                cancelled = false
            }
            state.lance_sweep_pending = pending
        end
        local frame = tonumber(state.entity_frame) or now
        if pending.polled_frame == frame then return nil, "pending" end
        pending.polled_frame = frame
        local hit_clear, hit_written = pcall(memory.WriteInt, state.shape_hit_ptr, 0)
        local entity_clear, entity_written = pcall(memory.WriteInt, state.shape_entity_ptr, 0)
        if not hit_clear or hit_written == false or not entity_clear or entity_written == false then
            pending.cancelled = true
            return nil, "buffer-write-failed"
        end
        local status, raw, err = invoke_int_detail(H.GET_SHAPE_TEST_RESULT, pending.handle,
            state.shape_hit_ptr, state.shape_end_ptr, state.shape_normal_ptr, state.shape_entity_ptr)
        if err then
            -- The result call may have consumed the native handle before an
            -- exception crossed the bridge. Never retry that uncertain token.
            state.lance_sweep_pending = nil
            return nil, "sweep-result-failed"
        end
        if status == 1 then return nil, "pending" end
        if status ~= 0 and status ~= 2 then return nil, "pending-status-unknown" end
        -- GET_SHAPE_TEST_RESULT invalidates the native handle on 0/2. Claim it
        -- before reading the result, including cancellation and stale aim paths.
        state.lance_sweep_pending = nil
        if status == 0 then return nil, "sweep-invalid" end
        local entity_ok, raw_entity = pcall(memory.ReadInt, state.shape_entity_ptr)
        local entity, classification = Messiah.NormalizeEntityHandle(entity_ok and raw_entity or nil)
        Messiah.ReportRejectedEntityHandle("LanceContactPoint.GET_SHAPE_TEST_RESULT", raw_entity,
            classification, "none", "capsule result normalized before coordinate-only consumers")
        if entity ~= 0 and entity ~= state.ped and not state.projectiles[entity] then
            local lease = Messiah.AcquireEntityLease(entity, nil, {
                source = "raycast",
                release_guid = true,
                action = "LANCE",
                action_serial = pending.action_serial
            })
            if lease then
                -- Only coordinates survive this result. Release a valid borrowed
                -- GUID before any blast, never inspect a victim after destruction.
                Messiah.ReleaseShapeEntity({ entity = entity, entity_lease = lease, entity_retained = true },
                    "lance-sweep-coordinate-consumed")
            end
        end
        if pending.cancelled or not active or pending.epoch ~= state.activation_epoch
            or pending.action_serial ~= action.serial or now - pending.started_ms > 250 then
            return nil, "cancelled-or-stale"
        end
        local hit_ok, hit = pcall(memory.ReadInt, state.shape_hit_ptr)
        local hit_value = hit_ok and Messiah.FiniteNumber(hit) or nil
        if not hit_value or hit_value == 0 or hit_value % 1 ~= 0 then return nil, "miss" end
        local x, y, z = Messiah.ReadNativeOutV3(state.shape_end_ptr, "lance-sweep-end")
        local point = Messiah.CopyPoint({ x = x, y = y, z = z })
        if not point then return nil, "invalid-hit-point" end
        -- The camera may have swung while this async query ran. Accept only a
        -- point still touching the current beam; old beam locations never fire.
        local dx, dy, dz = target.x - hand.x, target.y - hand.y, target.z - hand.z
        local length_sq = dx * dx + dy * dy + dz * dz
        if length_sq < 0.0025 then return nil, "invalid-current-segment" end
        local t = clamp(((point.x - hand.x) * dx + (point.y - hand.y) * dy + (point.z - hand.z) * dz) / length_sq, 0, 1)
        local px, py, pz = point.x - (hand.x + dx * t), point.y - (hand.y + dy * t), point.z - (hand.z + dz * t)
        if px * px + py * py + pz * pz > 0.85 * 0.85 then return nil, "aim-moved" end
        return { x = point.x, y = point.y, z = point.z }, "capsule-contact"
    end

    function Messiah.UpdateVoidLanceChannel(now, ped, action)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local function current() return Messiah.ActionContextCurrent(state, epoch, action, "LANCE") end
        if not current()
            or state.phase ~= Messiah.PHASES.LANCE_CHANNEL then
            return false
        end
        local hand, bone = Messiah.LanceHandPoint(ped, state.cast_hand_right)
        if not current() then return false end
        local aim = action.minimum_pulse ~= true
            and type(state.aim_snapshot) == "table" and state.aim_snapshot or nil
        local target = action.minimum_pulse == true and Messiah.CopyPoint(action.press_target)
            or (aim and Messiah.CopyPoint(aim.target) or Messiah.CopyPoint(action.target))
        if not hand or not target then return false end
        action.target = Messiah.CopyPoint(target)
        action.target_source = tostring((aim and aim.source) or target.source or "unknown")
        local dx, dy, dz = target.x - hand.x, target.y - hand.y, target.z - hand.z
        local length = math.sqrt(dx * dx + dy * dy + dz * dz)
        if length < 0.001 then dx, dy, dz, length = 0.0, 1.0, 0.0, 1.0 end
        dx, dy, dz = dx / length, dy / length, dz / length
        -- Keep the action's presentation record so a failed creation remains
        -- latched until release instead of allocating a new entity every frame.
        state.channel_beam = state.channel_beam or { style = "channel", layers = Messiah.MAX_BEAM_LAYERS }
        state.channel_beam.started_ms = action.channel_started_ms or now
        state.channel_beam.action_serial = action.serial
        state.channel_beam.owner_epoch = state.activation_epoch
        state.channel_beam.from = hand
        state.channel_beam.target = Messiah.CopyPoint(target)
        Messiah.SetReticleMode("CHANNEL", now + 100,
            "beam endpoint source=" .. action.target_source)
        if not current() then return false end
        if action.channel_started_ms == nil then
            action.channel_started_ms = now
            action.next_impact_ms = now
            action.next_contact_sound_ms = now
            action.charge_handles = Messiah.OwnActionTempFx("LANCE", action.serial)
            if not current() then return false end
            Messiah.StopSoundRole("lance-charge")
            if not current() then return false end
            -- Barry's tracked psychic channel replaces the vehicle EMP hum.
            -- The separate charge loop joins once after 800 ms; both retain
            -- the same channel priority and end/cleanup ownership.
            Messiah.PlayEntitySound("lance-loop", ped, "MIND_CONTROL",
                "BARRY_01_SOUNDSET", 600000, true,
                { action_serial = action.serial, epoch = epoch })
            if not current() then return false end
            log_info(("Messiah Void Lance channel started: activation=%d serial=%d handBone=%d "
                    .. "visualRequested=networked-alien-beam+caster-guidance beamLayers=%d localOverlay=true "
                    .. "palette=electric-blue+cyan+cold-white impactIntervalMs=%d "
                    .. "impactMode=engine-explosion nativePhysics=true sweepRadius=0.65 "
                    .. "sweepGuidRelease=validated targetDamageNatives=0 poolScan=false "
                    .. "source=%s chargeHandles=%d.")
                :format(state.activation_id, action.serial, bone, Messiah.MAX_BEAM_LAYERS,
                    Messiah.LANCE_IMPACT_INTERVAL_MS,
                    action.target_source,
                    action.charge_handles))
            if not current() then return false end
        end
        Messiah.UpdateLanceAudio(now, action)
        if not current() then return false end
        Messiah.LogOnce("lance-source:" .. action.target_source,
            ("Messiah Void Lance target source: activation=%d serial=%d source=%s "
                .. "target=(%.2f,%.2f,%.2f).")
            :format(state.activation_id, action.serial, action.target_source,
                target.x, target.y, target.z))
        if not current() then return false end
        local contact, contact_source = Messiah.LanceContactPoint(now, hand, target, action)
        if not current() then return false end
        -- Pending sweeps own contact priority: firing at a farther camera hit
        -- every start would consume the cooldown before the near hit completes.
        local camera_fallback = contact_source == "sweep-unavailable"
            or contact_source == "sweep-start-failed" or contact_source == "sweep-invalid"
            or contact_source == "miss"
        if not contact and camera_fallback and ((aim and aim.direct_hit == true)
                or (action.minimum_pulse == true and action.press_direct_hit == true)) then
            contact, contact_source = { x = target.x, y = target.y, z = target.z }, "camera-contact-fallback"
        end
        if contact then
            action.visual_contact = { x = contact.x, y = contact.y, z = contact.z, now_ms = now }
        end
        local visual_contact = action.visual_contact
        if visual_contact and now - visual_contact.now_ms <= 250 then
            local hx, hy, hz = visual_contact.x - hand.x, visual_contact.y - hand.y, visual_contact.z - hand.z
            local along = hx * dx + hy * dy + hz * dz
            local off_x, off_y, off_z = hx - dx * along, hy - dy * along, hz - dz * along
            if along >= 0 and along <= length and off_x * off_x + off_y * off_y + off_z * off_z <= 0.85 * 0.85 then
                -- The guide and world beam end at the nearest validated contact,
                -- even between capsule results. Never retain the victim handle.
                state.channel_beam.target = { x = visual_contact.x, y = visual_contact.y, z = visual_contact.z }
            else
                action.visual_contact = nil
            end
        else
            action.visual_contact = nil
        end
        if contact and now >= (tonumber(action.next_impact_ms) or now) then
            action.last_contact_source = contact_source
            action.next_impact_ms = now + Messiah.LANCE_IMPACT_INTERVAL_MS
            action.next_sweep_ms = math.max(tonumber(action.next_sweep_ms) or 0, action.next_impact_ms)
            action.impact_ticks = (tonumber(action.impact_ticks) or 0) + 1
            state.reticle_pulse_until_ms = now + 90
            local audible = now >= (tonumber(action.next_contact_sound_ms) or 0)
            if audible then action.next_contact_sound_ms = now + 440 end
            Messiah.ApplyImpactProfile("LANCE_IMPACT", contact,
                { x = dx, y = dy, z = dz }, {
                    action = "LANCE",
                    action_serial = action.serial,
                    epoch = state.activation_epoch,
                    blast_scale = 2.5,
                    max_fx = 0,
                    no_audio = not audible,
                    native_sound = false,
                    no_vanilla_fx = true,
                    solid_hit = true
                })
        end
        return true
    end

    function Messiah.EndVoidLance(now, reason)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local action = state.action
        local function current() return Messiah.ActionContextCurrent(state, epoch, action, "LANCE", true) end
        if not current() then return false end
        if action.ending == true then return true end
        Messiah.FlushLanceVisualDiagnostics(now, 'end:' .. tostring(reason or 'input-up'))
        if not current() then return false end
        action.ending = true
        if state.lance_sweep_pending and state.lance_sweep_pending.action_serial == action.serial then
            state.lance_sweep_pending.cancelled = true
        end
        for index = #state.scheduled_impacts, 1, -1 do
            local pending = state.scheduled_impacts[index]
            if pending.profile == "LANCE_IMPACT" and pending.action_serial == action.serial then
                Messiah.RecordEssentialDrop(pending, now)
                if not current() then return false end
                table.remove(state.scheduled_impacts, index)
            end
        end
        Messiah.ClearLanceVisuals(action.serial)
        state.channel_beam, state.hud_snapshot = nil, nil
        state.visual_snapshot, state.visual_build = nil, nil
        state.visual_generation = (tonumber(state.visual_generation) or 0) + 1
        if state.gameplay_owner ~= true or state.restoring or state.disposed then return true end
        Messiah.StopSharedBeam("lance")
        if not current() then return false end
        action.end_reason = tostring(reason or "input-up")
        state.channel_beam = nil
        Messiah.StopSoundRole("lance-loop")
        if not current() then return false end
        Messiah.StopSoundRole("lance-charge")
        if not current() then return false end
        local charge_stopped = Messiah.CleanupActionTempFx("LANCE")
        if not current() then return false end
        action.animation_cleaned = Messiah.ClearOwnedActionAnimation(
            state.ped, "lance", "lance-end:" .. action.end_reason)
        if not current() then return false end
        Messiah.ReassertIdleStance(now, "lance-end:" .. action.end_reason)
        if not current() then return false end
        Messiah.SetPhase(Messiah.PHASES.LANCE_RELEASE, now,
            "reason=" .. action.end_reason .. " impactTicks=" .. tostring(action.impact_ticks or 0))
        if not current() then return false end
        if action.channel_started_ms ~= nil then
            Messiah.PlayEntitySound("lance-release", state.ped, "DESPAWN",
                "BARRY_01_SOUNDSET", 240, false)
            if not current() then return false end
        end
        Messiah.FlushDamageEvidence(action.serial, "lance-channel-" .. action.end_reason)
        if not current() then return false end
        Messiah.FlushPhysicalSummary(action.serial, "lance-channel-" .. action.end_reason)
        if not current() then return false end
        log_info(("Messiah Void Lance channel ending: activation=%d serial=%d reason=%s "
                .. "heldMs=%d impactTicks=%d minimumPulse=%s "
                .. "cleanup=beam+charge+animation animationConfirmed=%s chargeHandles=%d.")
            :format(state.activation_id, action.serial, action.end_reason,
                math.max(0, now - (tonumber(action.channel_started_ms) or now)),
                tonumber(action.impact_ticks) or 0, tostring(action.minimum_pulse == true),
                tostring(action.animation_cleaned == true), charge_stopped))
        return true
    end

    function Messiah.ReleaseVoidLance(now, ped, action)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        if not Messiah.ActionContextCurrent(state, epoch, action, "LANCE", true) then return false end
        if state.restoring or state.disposed or state.gameplay_owner ~= true then return false end
        if action.cleanup_done then return true end
        action.cleanup_done = true
        state.channel_beam = nil
        state.right_hand = not state.cast_hand_right
        if state.pending_ability ~= "RUPTURE" and state.pending_ability ~= "SUPER" then
            state.reticle_mode_until_ms = now
        end
        log_info(("Messiah Void Lance released: activation=%d serial=%d reason=%s "
                .. "impactTicks=%d cleanupOnce=true.")
            :format(state.activation_id, action.serial, tostring(action.end_reason or "input-up"),
                tonumber(action.impact_ticks) or 0))
        return true
    end

    function Messiah.ReleaseGroundRupture(now, action)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local function current() return Messiah.ActionContextCurrent(state, epoch, action, "RUPTURE") end
        if not current() then return false end
        local target = Messiah.CopyPoint(action.target)
        if not target then return false end
        local cracks = action.crack_record
        if cracks and cracks.owner_epoch == state.activation_epoch and cracks.owner_action_serial == action.serial then
            cracks.expires_ms = math.max(cracks.expires_ms, now + 1000)
            cracks.release_ms = now
        else
            action.crack_record = Messiah.AddCracks(now, target, 5.8, 1000, { 112, 58, 244 }, 8)
        end
        if not current() then return false end
        local rotation = (action.serial % 8) * math.pi / 8.0
        for index = 0, 4 do
            local angle = rotation + index * math.pi * 2.0 / 5.0
            local point = {
                x = target.x + math.cos(angle) * 4.8,
                y = target.y + math.sin(angle) * 4.8,
                z = target.z,
            }
            Messiah.ScheduleImpact(now, index * 70, {
                owner_state = state,
                profile = "RUPTURE_IMPACT",
                position = point,
                action_serial = action.serial,
                options = {
                    action = "RUPTURE",
                    epoch = epoch,
                    diagnostic_key = "rupture-satellite",
                    blast_scale = 3.0,
                    max_fx = 1,
                    audio_index = index + 1,
                    final_core = false
                },
            })
            if not current() then return false end
        end
        Messiah.ScheduleImpact(now, 360, {
            owner_state = state,
            profile = "RUPTURE_IMPACT",
            position = target,
            action_serial = action.serial,
            options = {
                action = "RUPTURE",
                epoch = epoch,
                diagnostic_key = "rupture-core",
                blast_scale = 5.0,
                max_fx = 1,
                audio_index = 6,
                final_core = true,
                flush_damage = true,
                flush_reason = "rupture-final-core"
            },
        })
        if not current() then return false end
        log_info(("Messiah Ground Rupture released: activation=%d serial=%d "
                .. "locked=(%.2f,%.2f,%.2f) eruptions=5 finalCore=1 "
                .. "staggerMs=70 impactTimeOwned=true "
                .. "eruptionPhysics=engine-blast immutable=true "
                .. "blastSizeScale=3.0 coreSizeScale=5.0 "
                .. "engineBlasts=6 targetNatives=0 poolScans=0 nativePhysics=true.")
            :format(state.activation_id, action.serial, target.x, target.y, target.z))
        return true
    end

    -- E owns one bounded release snapshot of opaque identities and coordinates.
    -- It never retains pool pointers or script GUIDs across a frame. Fresh
    -- rendered pointers must re-prove identity before any current-frame lease.
    -- The documented bridge is not an atomic lifetime pin; host safety and
    -- resulting displacement still require a live controlled-distance retest.
    function Messiah.ShockwavePressure(value)
        value = type(value) == "table" and value or Messiah.SHOCKWAVE_PRESSURE
        if type(value) ~= "table" then return nil end
        for name, maximum in pairs({ radius = 24, force = 92, lift = 26, max_targets = 32,
            max_capture_visits = 96, max_lease_admissions = 8 }) do
            local number = value[name]
            if not Messiah.FiniteNumber(number) or number <= 0 or number > maximum then return nil end
            if name:find("max_", 1, true) == 1 and number % 1 ~= 0 then return nil end
        end
        -- Three fixed radii are the ability contract. A malformed descriptor
        -- cannot silently expand the wave or re-enable the old blast carpet.
        if value.radius ~= 24 then return nil end
        return value
    end

    function Messiah.ShockwaveBand(distance, pressure)
        pressure = Messiah.ShockwavePressure(pressure)
        if not pressure or not Messiah.FiniteNumber(distance) or distance < 0
            or distance > pressure.radius then
            return nil
        end
        if distance <= 8 then return 1, 8, 320 end
        if distance <= 16 then return 2, 16, 520 end
        return 3, 24, 760
    end

    function Messiah.ShockwaveDiagnostic(fronts, stage, target, reason, terminal, kind)
        if type(fronts) ~= "table" then return false end
        if type(target) ~= "table" then target = nil end
        local diagnostic = fronts.diagnostic
        if not diagnostic then
            diagnostic = { counts = {}, reasons = {}, reason_count = 0, kinds = {} }
            fronts.diagnostic = diagnostic
        end
        if diagnostic.closed then return false end
        kind = kind or (target and target.kind)
        local kind_counts
        if kind == "vehicle" or kind == "ped" or kind == "object" then
            diagnostic.kinds = diagnostic.kinds or {}
            kind_counts = diagnostic.kinds[kind]
            if not kind_counts then
                kind_counts = { counts = {}, reasons = {}, reason_count = 0 }
                diagnostic.kinds[kind] = kind_counts
            end
        end
        if stage then
            local count = true
            if target then
                target.stages = target.stages or {}
                count = not target.stages[stage]; target.stages[stage] = true
            end
            if count then
                diagnostic.counts[stage] = math.min(999999, (diagnostic.counts[stage] or 0) + 1)
                if kind_counts then
                    kind_counts.counts[stage] = math.min(999999, (kind_counts.counts[stage] or 0) + 1)
                end
            end
        end
        if reason then
            reason = tostring(reason):sub(1, 64)
            if target then target.last_reason = reason end
            local counts = diagnostic.reasons
            if counts[reason] or diagnostic.reason_count < 32 then
                if not counts[reason] then diagnostic.reason_count = diagnostic.reason_count + 1 end
                counts[reason] = math.min(999999, (counts[reason] or 0) + 1)
            else
                counts.other = math.min(999999, (counts.other or 0) + 1)
            end
            if kind_counts then
                local counts = kind_counts.reasons
                if counts[reason] or kind_counts.reason_count < 32 then
                    if not counts[reason] then kind_counts.reason_count = kind_counts.reason_count + 1 end
                    counts[reason] = math.min(999999, (counts[reason] or 0) + 1)
                else
                    counts.other = math.min(999999, (counts.other or 0) + 1)
                end
            end
            if terminal and target then target.done, target.final_reason = true, reason end
        end
        return false
    end

    function Messiah.FinishShockwaveDiagnostics(fronts, reason)
        if type(fronts) ~= "table" then return false end
        Messiah.ShockwaveDiagnostic(fronts)
        local diagnostic = fronts.diagnostic
        if diagnostic.closed then return false end
        local details = {}
        for index, target in ipairs(fronts.targets or {}) do
            if index > 32 then break end
            if not target.final_reason then
                local final = target.done and (target.damage_status or target.last_reason or "response-ended")
                    or (reason == "expired" and "expired:" .. tostring(not (target.stages and target.stages.reResolved)
                            and "not-re-resolved" or target.last_reason or "not-re-resolved")
                        or "cancelled:" .. tostring(reason or "unknown"))
                Messiah.ShockwaveDiagnostic(fronts, nil, target, final, true)
            end
            local current_distance = Messiah.FiniteNumber(target.current_distance)
            details[#details + 1] = ("%d:%s:b%d:%.2f>%s:%s:lease=%s:front=%d:proof=%s:resolver=%s/%s/%s:control=%dreq/%dchecks")
                :format(index, tostring(target.kind),
                    target.band or 0, target.distance or -1,
                    current_distance and ("%.2f"):format(current_distance) or "?",
                    tostring(target.final_reason), tostring(target.lease_reason or "none"),
                    target.response_front or 0, tostring(target.selection_source or "unknown"),
                    tostring(target.conversion_source or "unattempted"), tostring(target.conversion_status or "none"),
                    tostring(target.conversion_raw or "unobserved"), target.control_polls or 0,
                    target.control_checks or 0)
        end
        diagnostic.closed = true
        local counts = diagnostic.counts
        local stages = {}
        for _, name in ipairs({ "discovered", "inRange", "selected", "reResolved", "leaseAdmitted",
            "eligible", "crossed", "controlAcquired", "forceAttempted", "damageAttempted" }) do
            stages[#stages + 1] = name .. "=" .. tostring(counts[name] or 0)
        end
        local rejected = {}
        for name, count in pairs(diagnostic.reasons) do rejected[#rejected + 1] = name .. ":" .. count end
        table.sort(rejected)
        local by_kind = {}
        for _, kind in ipairs({ "vehicle", "ped", "object" }) do
            local row = diagnostic.kinds and diagnostic.kinds[kind] or { counts = {}, reasons = {} }
            local stages, reasons = {}, {}
            for _, name in ipairs({ "discovered", "inRange", "selected", "reResolved", "leaseAdmitted",
                "eligible", "crossed", "controlAcquired", "forceAttempted", "damageAttempted" }) do
                stages[#stages + 1] = name .. ":" .. tostring(row.counts[name] or 0)
            end
            for name, count in pairs(row.reasons) do reasons[#reasons + 1] = name .. ":" .. count end
            table.sort(reasons)
            by_kind[#by_kind + 1] = kind .. "{" .. table.concat(stages, ",") ..
                ";reasons=" .. table.concat(reasons, ",") .. "}"
        end
        log_info(("Messiah Shockwave disposition: epoch=%d actionSerial=%d reason=%s %s "
            .. "captureVisits=%d frameVisitPeak=%d leaseAdmissionPeak=%d "
            .. "reasons=[%s] targets=[%s] counters=discovery-observations/unique-selected-stages "
            .. "byKind=[%s] outcome=LIVE_RETEST_REQUIRED."):format(fronts.epoch, fronts.action_serial, tostring(reason),
            table.concat(stages, " "), fronts.capture_visits or 0, fronts.visit_peak or 0, fronts.lease_peak or 0,
            table.concat(rejected, ","), table.concat(details, ";"), table.concat(by_kind, "|")))
        return true
    end

    function Messiah.ShockwaveFrontAt(fronts, index, now)
        local pressure = type(fronts) == "table" and Messiah.ShockwavePressure(fronts.pressure)
        if not pressure or not Messiah.FiniteNumber(now) or index ~= math.floor(tonumber(index) or -1)
            or index < 1 or index > 3 then
            return nil
        end
        local finish = fronts.started_ms + ({ 320, 520, 760 })[index]
        local start = finish - 320
        local radius = pressure.radius * index / 3
        return radius * clamp((now - start) / 320, 0, 1), radius, start, finish
    end

    -- Detached observations select a response front; they never authorize an
    -- entity native. A fresh current-frame lease is still required at response.
    function Messiah.ObserveShockwaveTarget(fronts, target, point, now)
        if type(fronts) ~= "table" or type(target) ~= "table" or target.done
            or not Messiah.FiniteNumber(now) then
            return false
        end
        local x, y, z = vector_components(point)
        if not Messiah.FiniteNumber(x) or not Messiah.FiniteNumber(y) or not Messiah.FiniteNumber(z) then return false end
        local dx, dy, dz = x - fronts.position.x, y - fronts.position.y, z - fronts.position.z
        local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
        local old_ms, old_distance = target.observed_ms, target.observed_distance
        target.current_distance = distance
        if not Messiah.ShockwaveBand(distance, fronts.pressure) then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "moved-outside-3d-range", true)
        end
        if target.crossing then return true end
        if old_ms and now > old_ms then
            local selected_time, selected_front
            for index = 1, 3 do
                local _, radius, start, finish = Messiah.ShockwaveFrontAt(fronts, index, now)
                local first, last = math.max(old_ms, start), math.min(now, finish)
                if first <= last then
                    local function gap(at)
                        local d = old_distance + (distance - old_distance) * (at - old_ms) / (now - old_ms)
                        return d - radius * clamp((at - start) / 320, 0, 1)
                    end
                    local before, after = gap(first), gap(last)
                    -- No admission from a point first observed inside an
                    -- already-passed front. A sampled outside-to-inside bracket
                    -- must overlap the actual 320 ms travel interval.
                    if before >= 0 and after <= 0 and (before > 0 or first == start) then
                        local at = before == after and first or first + (last - first) * before / (before - after)
                        if now - at <= Messiah.SHOCKWAVE_CONTROL_GRACE_MS
                            and (not selected_time or at < selected_time) then
                            selected_time, selected_front = at, index
                        end
                    end
                end
            end
            if selected_front then
                target.crossing = {
                    front = selected_front,
                    at_ms = selected_time,
                    previous_ms = old_ms,
                    observed_ms = now,
                    previous_distance = old_distance,
                    distance = distance
                }
                target.response_front, target.cross_ms = selected_front, selected_time
            end
        end
        target.observed_ms, target.observed_distance = now, distance
        if not target.crossing then
            local next_time
            for index = 1, 3 do
                local _, radius, start, finish = Messiah.ShockwaveFrontAt(fronts, index, now)
                local at = start + 320 * distance / radius
                if distance <= radius and at >= now and now <= finish and (not next_time or at < next_time) then
                    next_time =
                        at
                end
            end
            target.cross_ms = next_time or math.huge
        end
        return target.crossing ~= nil
    end

    function Messiah.ShockwaveConversion(pointer)
        if pointer == nil or not (gta and type(gta.PointerToHandle) == "function") then return 0, "unavailable" end
        local ok, raw = pcall(gta.PointerToHandle, pointer)
        if not ok then return 0, "uncertain-throw" end
        if raw == nil or (type(raw) == "number" and raw == 0) then return 0, "empty" end
        if type(raw) ~= "number" then return 0, "malformed" end
        local handle = Messiah.NormalizeEntityHandle(raw)
        if handle == 0 then return 0, "malformed" end
        return handle, "accepted"
    end

    -- Read only the current candidate's documented network identity. Every
    -- property/method boundary can revoke the captured frame/identity proof.
    -- No host object or network ID survives this resolver visit.
    function Messiah.ShockwaveNetworkId(pointer, current)
        local function read(callback)
            if not current() then return false, nil, "context-revoked" end
            local ok, value = pcall(callback)
            if not current() then return false, nil, "context-revoked" end
            if not ok then return false, nil, "network-proof-uncertain-throw" end
            return true, value
        end
        local ok, object, reason = read(function() return pointer.NetObject end)
        if not ok then return nil, reason end
        if object == nil then return nil, "unavailable" end
        local id_ok, id, id_reason = read(function() return object.ObjectID end)
        if not id_ok then return nil, id_reason end
        if type(id) ~= "number" or not Messiah.FiniteNumber(id) or id < 0 or id > 0x7FFFFFFF or id % 1 ~= 0 then
            return nil, "network-id-malformed"
        end
        -- Do not call CNetObject:GetEntity: the host explicitly excludes door
        -- objects from that API. The independently validated HandleToPointer
        -- roundtrip below proves the exact original physical identity instead.
        return id, "accepted"
    end

    -- Cherax documents PointerToHandle(CPhysical) as the conversion contract.
    -- CNetObject.ObjectID is only an identity fingerprint here, never passed to
    -- NETWORK_GET_ENTITY_FROM_NETWORK_ID. A typed pool lookup is a bounded
    -- alternative only after an explicitly empty/unavailable direct conversion;
    -- throwing or malformed conversions remain closed for this candidate.
    function Messiah.ResolveShockwaveHandle(pointer, pool_index, getter, key, current, state)
        local indexed = pool_index ~= nil and type(getter) == "function"
        local source = "pointer"
        local raw_kind = "unobserved"
        if not current() then return 0, "context-revoked", source, raw_kind end
        local handle, conversion
        local net_id, network_status = Messiah.ShockwaveNetworkId(pointer, current)
        if network_status ~= "accepted" and network_status ~= "unavailable" then
            return 0, network_status, source, raw_kind
        end
        handle, conversion = Messiah.ShockwaveConversion(pointer)
        raw_kind = conversion
        if not current() then return 0, "context-revoked", source, raw_kind end
        if (conversion == "empty" or conversion == "unavailable") and indexed then
            source = "indexed-after-empty-pointer"
            local ok, raw = pcall(getter, pool_index)
            raw_kind = not ok and "throw" or raw == nil and "nil" or raw == 0 and "zero" or type(raw)
            if not current() then return 0, "context-revoked", source, raw_kind end
            if not ok then return 0, "uncertain-throw", source, raw_kind end
            if raw == nil or (type(raw) == "number" and raw == 0) then return 0, "empty", source, raw_kind end
            if type(raw) ~= "number" then return 0, "malformed", source, raw_kind end
            handle = Messiah.NormalizeEntityHandle(raw)
            if handle == 0 then return 0, "malformed", source, raw_kind end
            conversion = "accepted"
        end
        if conversion ~= "accepted" then return 0, conversion, source, raw_kind end
        local again, after = Messiah.ShockwaveNetworkId(pointer, current)
        if again ~= net_id or after ~= network_status then
            return 0, "network-identity-changed", source, raw_kind
        end
        -- A positive alias is not identity proof. Reject released GUIDs before
        -- even mapping them, then match the current pointer before entity natives.
        if Messiah.IsReleasedScriptGuid(handle, state) then return 0, "released-guid", source, raw_kind end
        if not (gta and type(gta.HandleToPointer) == "function") then return 0, "mapping-unavailable", source, raw_kind end
        local ok, mapped = pcall(gta.HandleToPointer, handle)
        if not current() then return 0, "context-revoked", source, raw_kind end
        if not ok then return 0, "mapping-uncertain-throw", source, raw_kind end
        if mapped == nil then return 0, "mapping-empty", source, raw_kind end
        local address_ok, address = pcall(function() return mapped:GetAddress() end)
        if not current() then return 0, "context-revoked", source, raw_kind end
        if not address_ok then return 0, "mapping-address-uncertain-throw", source, raw_kind end
        if not Messiah.FiniteNumber(address) or address <= 0 or address % 1 ~= 0 then
            return 0, "mapping-invalid", source,
                raw_kind
        end
        if "physical:" .. tostring(address) ~= key then return 0, "mapping-mismatch", source, raw_kind end
        return handle, "accepted", source, raw_kind
    end

    function Messiah.ShockwaveResponsePosition(fronts, target, point, now)
        local x, y, z = vector_components(point)
        if not Messiah.FiniteNumber(x) or not Messiah.FiniteNumber(y) or not Messiah.FiniteNumber(z) then
            return false,
                nil, "position-unavailable"
        end
        local dx, dy, dz = x - fronts.position.x, y - fronts.position.y, z - fronts.position.z
        local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
        if not Messiah.ShockwaveBand(distance, fronts.pressure) then return false, distance, "outside-3d-range" end
        local crossing = target.crossing
        if type(crossing) ~= "table" or crossing.front ~= target.response_front
            or not Messiah.FiniteNumber(crossing.at_ms) or not Messiah.FiniteNumber(crossing.observed_ms)
            or now < crossing.observed_ms then
            return false, distance, "crossing-unproven"
        end
        local radius, _, start, finish = Messiah.ShockwaveFrontAt(fronts, crossing.front, now)
        if not radius or crossing.at_ms < start or crossing.at_ms > finish then
            return false, distance,
                "crossing-unproven"
        end
        if distance > radius then return false, distance, "ahead-of-front" end
        return true, distance
    end

    function Messiah.VisitShockwaveCandidates(consumer, visit_limit, wanted, capture)
        local state = Messiah.EntityState()
        if not Messiah.EntityOwner() or state.ending or state.cleanup_owner then return 0 end
        local fronts = state.shockwave_fronts
        local epoch = state.activation_epoch
        local frame = state.entity_frame
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch)
                and state.entity_frame == frame
                and type(fronts) == "table" and state.shockwave_fronts == fronts and fronts.epoch == epoch
                and fronts.proof_revoked_frame ~= state.entity_frame
        end
        if not current() then return 0 end
        local function identity_current(key, expected, revision, release_serial)
            if not current() then return false end
            local identity = state.entity_identities[key]
            local valid = state.script_guid_release_serial == release_serial
                and (expected == nil or identity == expected)
                and (not identity or (identity.terminal ~= true
                    and (tonumber(identity.borrowed_revision) or 0) == revision))
            if not valid then fronts.proof_revoked_frame = state.entity_frame end
            return valid
        end
        local pressure = Messiah.ShockwavePressure(fronts and fronts.pressure)
        if not pressure then return 0 end
        if fronts.visit_frame ~= state.entity_frame then
            fronts.visit_frame, fronts.frame_visits, fronts.frame_leases = state.entity_frame, 0, 0
            fronts.frame_late_leases = 0
            fronts.frame_kind_leases = {}
        end
        local visited, acquired, seen, pool_visits = 0, fronts.frame_leases or 0, {}, {}
        local specs = {
            { "vehicle", "GetRenderedVehicles", "GetCVehicle", "GetMaxVehicleCount", "GetCurrentVehicleCount", "GetVehicle" },
            { "ped",     "GetRenderedPeds",     "GetCPed",     "GetMaxPedCount",     "GetCurrentPedCount",     "GetPed" },
            { "object",  "GetRenderedObjects",  "GetCObject",  "GetMaxObjectCount",  "GetCurrentObjectCount",  "GetObject" },
        }
        -- Rotate the first pool each frame and reserve conversion opportunities
        -- for each kind. A large vehicle/object pool cannot consume every slot
        -- before nearby peds receive their crossing proof.
        local rotate = state.entity_frame % 3
        for _ = 1, rotate do
            local first = table.remove(specs, 1); specs[#specs + 1] = first
        end
        visit_limit = math.min(pressure.max_capture_visits - (fronts.frame_visits or 0),
            math.max(0, tonumber(visit_limit) or 96))
        if visit_limit <= 0 then return 0 end
        local per_kind = math.min(32, math.max(1, math.floor(visit_limit / 3)))
        fronts.index_cursors = fronts.index_cursors or {}
        fronts.render_cursors = fronts.render_cursors or {}
        local function visit(pointer, spec, pool_index, expected_key)
            if not current() then return end
            if visited >= visit_limit or (pool_visits[spec[1]] or 0) >= per_kind then return end
            visited = visited + 1; pool_visits[spec[1]] = (pool_visits[spec[1]] or 0) + 1
            fronts.frame_visits = (fronts.frame_visits or 0) + 1
            fronts.visit_peak = math.max(fronts.visit_peak or 0, fronts.frame_visits)
            local release_serial = state.script_guid_release_serial
            local address_ok, address = pcall(function() return pointer:GetAddress() end)
            if not current() or state.script_guid_release_serial ~= release_serial then
                fronts.proof_revoked_frame = state.entity_frame
                Messiah.ShockwaveDiagnostic(fronts, nil, wanted and wanted[expected_key], "pointer-context-revoked",
                    false, spec[1]); return
            end
            if not address_ok or not Messiah.FiniteNumber(address) or address <= 0 or address % 1 ~= 0 then
                Messiah.ShockwaveDiagnostic(fronts, nil, wanted and wanted[expected_key], "invalid-pointer",
                    expected_key ~= nil, spec[1])
                return
            end
            local key = "physical:" .. tostring(address)
            if expected_key and key ~= expected_key then
                Messiah.ShockwaveDiagnostic(fronts, nil, wanted[expected_key], "recycled-slot", true, spec[1]); return
            end
            if seen[key] then
                -- The indexed lookup can add an independently re-resolvable
                -- slot to a pointer already sampled from the rendered list.
                if capture and pool_index ~= nil and type(seen[key]) == "table" then
                    seen[key].pool_index = pool_index; return
                end
                if not (capture and pool_index ~= nil and seen[key] == true) then return end
                -- A rendered rejection is not an indexed admission decision.
                -- Re-prove properties and identity on this fresh indexed pointer
                -- before reconsidering the newly available slot evidence.
                seen[key] = nil
            end
            Messiah.ShockwaveDiagnostic(fronts, "discovered", nil, nil, false, spec[1])
            if wanted and not wanted[key] then return end
            local target = wanted and wanted[key]
            if target then Messiah.ShockwaveDiagnostic(fronts, "reResolved", target, nil, false, spec[1]) end
            local identity = state.entity_identities[key]
            local revision = identity and (tonumber(identity.borrowed_revision) or 0) or 0
            -- Destruction still tombstones the physical identity. A previous
            -- GUID release only revokes that exact alias and its old leases;
            -- a distinct current GUID may safely identify this living entity.
            if identity and identity.terminal == true then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "terminal-identity", true, spec[1])
                return
            end
            local position_ok, position = pcall(function() return pointer.Position end)
            if not identity_current(key, identity, revision, release_serial) then return end
            local x, y, z = vector_components(position_ok and position or nil)
            local movable = true
            if spec[1] == "object" then
                local ok, dynamic = pcall(function() return pointer.IsDynamic end)
                if not identity_current(key, identity, revision, release_serial) then return end
                local fixed_ok, fixed = pcall(function() return pointer.IsFixed end)
                if not identity_current(key, identity, revision, release_serial) then return end
                movable = ok and fixed_ok and dynamic == true and fixed == false
            end
            if not movable then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "object-not-movable", false, spec[1]); return
            end
            if not Messiah.FiniteNumber(x) or not Messiah.FiniteNumber(y)
                or not Messiah.FiniteNumber(z) then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "invalid-pointer-position", false, spec[1]); return
            end
            -- Property getters and pointer conversion are fallible host calls.
            -- Re-read identity history after each boundary; a release during a
            -- getter must not authorize a fresh conversion of its positive alias.
            if not identity_current(key, identity, revision, release_serial) then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "identity-history-changed", false, spec[1]); return
            end
            seen[key] = true
            local candidate
            if capture then
                candidate = { sample_position = { x = x, y = y, z = z }, pool_index = pool_index }
                local result = consumer(candidate, key, spec[1])
                if result ~= "current-proof-needed" then
                    seen[key] = result or true; return
                end
                -- Late rendered admissions share the eight-conversion budget,
                -- reserving at least four slots for selected response targets.
                if (fronts.frame_late_leases or 0) >= math.min(4, Messiah.SHOCKWAVE_LATE_PROOF_BUDGET) then
                    Messiah.ShockwaveDiagnostic(fronts, nil, nil, "late-proof-budget", false, spec[1]); return
                end
            end
            if acquired >= pressure.max_lease_admissions then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "lease-budget", false, spec[1]); return
            end
            local kind_leases = fronts.frame_kind_leases or {}
            if (kind_leases[spec[1]] or 0) >= math.ceil(pressure.max_lease_admissions / 3) then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "kind-lease-budget", false, spec[1]); return
            end
            local retry = target
            if not retry then
                fronts.discovery_conversions = fronts.discovery_conversions or {}
                fronts.discovery_conversion_counts = fronts.discovery_conversion_counts or {}
                local ledger = fronts.discovery_conversions[spec[1]]
                if not ledger then
                    ledger = {}; fronts.discovery_conversions[spec[1]] = ledger
                end
                retry = ledger[key]
                if not retry then
                    if (fronts.discovery_conversion_counts[spec[1]] or 0) >= math.min(32, Messiah.SHOCKWAVE_DISCOVERY_PROOF_CAP) then
                        Messiah.ShockwaveDiagnostic(fronts, nil, nil, "late-proof-record-cap", false, spec[1]); return
                    end
                    retry = {}; ledger[key] = retry
                    fronts.discovery_conversion_counts[spec[1]] = (fronts.discovery_conversion_counts[spec[1]] or 0) + 1
                end
            end
            if retry.conversion_failed or retry.conversion_frame == state.entity_frame then return end
            if not identity_current(key, identity, revision, release_serial) then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "conversion-context-revoked", false, spec[1]); return
            end
            retry.conversion_frame = state.entity_frame
            acquired = acquired + 1
            kind_leases[spec[1]] = (kind_leases[spec[1]] or 0) + 1
            fronts.frame_kind_leases = kind_leases
            if capture then fronts.frame_late_leases = (fronts.frame_late_leases or 0) + 1 end
            fronts.frame_leases = acquired; fronts.lease_peak = math.max(fronts.lease_peak or 0, acquired)
            local handle, conversion, source, raw_kind = Messiah.ResolveShockwaveHandle(pointer, pool_index,
                pool_mgr and pool_mgr[spec[6]], key, function()
                    return identity_current(key, identity, revision, release_serial)
                end, state)
            if not identity_current(key, identity, revision, release_serial) then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "conversion-context-revoked", false, spec[1]); return
            end
            retry.conversion_source, retry.conversion_status, retry.conversion_raw = source, conversion, raw_kind
            if conversion == "released-guid" or Messiah.IsReleasedScriptGuid(handle, state) then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "released-guid", false, spec[1]); return
            end
            if conversion ~= "accepted" then
                if conversion == "empty" then
                    retry.conversion_empty_count = (retry.conversion_empty_count or 0) + 1
                    retry.conversion_failed = retry.conversion_empty_count >=
                        math.min(3, Messiah.SHOCKWAVE_CONVERSION_EMPTY_LIMIT)
                    retry.conversion_reason = retry.conversion_failed and "conversion-empty-exhausted" or
                        "conversion-empty-pending"
                    Messiah.ShockwaveDiagnostic(fronts, nil, target, retry.conversion_reason, retry.conversion_failed,
                        spec[1])
                else
                    retry.conversion_failed = true
                    retry.conversion_reason = "conversion-" .. conversion
                    Messiah.ShockwaveDiagnostic(fronts, nil, target, retry.conversion_reason, true, spec[1])
                end
                return
            end
            retry.conversion_empty_count = 0
            if handle == state.ped or state.projectiles[handle] then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "owner-excluded", true, spec[1]); return
            end
            local lease, lease_reason = Messiah.AcquireEntityLease(handle, spec[1], {
                source = "shockwave-fresh-pool",
                action = "SHOCKWAVE",
                expected_identity_key = key,
                action_serial = fronts and fronts.action_serial or 0,
                epoch = state.activation_epoch
            })
            if lease and lease.identity_key == key and identity_current(key, identity, revision, release_serial) then
                if capture then
                    candidate.current_proof = true
                    seen[key] = consumer(candidate, key, spec[1]) or true
                    candidate.current_proof = nil
                else
                    Messiah.ShockwaveDiagnostic(fronts, "leaseAdmitted", target, nil, false, spec[1])
                    consumer(lease, key, spec[1])
                end
                Messiah.RetireEntityLease(lease, "shockwave-frame-consumed", false)
            else
                if target then target.lease_reason = tostring(lease_reason or "none"):sub(1, 64) end
                Messiah.ShockwaveDiagnostic(fronts, nil, target, lease and "identity-mismatch" or "lease-rejected", true,
                    spec[1])
                if lease then Messiah.RetireEntityLease(lease, "shockwave-identity-mismatch", false) end
            end
        end
        local function read_indexed(getter, index, spec, expected_key)
            if not current() then return end
            local release_serial = state.script_guid_release_serial
            local identity = expected_key and state.entity_identities[expected_key]
            local revision = identity and (tonumber(identity.borrowed_revision) or 0) or 0
            local ok, pointer = pcall(getter, index)
            if not current() then return end
            if state.script_guid_release_serial ~= release_serial
                or (expected_key and not identity_current(expected_key, identity, revision, release_serial)) then
                fronts.proof_revoked_frame = state.entity_frame
                Messiah.ShockwaveDiagnostic(fronts, nil, wanted and wanted[expected_key], "pointer-context-revoked",
                    false, spec[1]); return
            end
            visit(ok and pointer or nil, spec, index, expected_key)
        end
        for _, spec in ipairs(specs) do
            if not current() then return visited end
            local indexed = pool_mgr and pool_mgr[spec[3]]
            -- A captured slot is only an index, never a saved pointer or GUID.
            -- Re-read the documented CPhysical getter on this gameplay frame;
            -- a recycled slot must match the captured opaque address again.
            if wanted and type(indexed) == "function" then
                for _, target in ipairs(fronts.targets or {}) do
                    local key = target.identity_key
                    if not current() then return visited end
                    if acquired >= pressure.max_lease_admissions or visited >= visit_limit then break end
                    if wanted[key] == target and target.kind == spec[1] and target.pool_index ~= nil then
                        read_indexed(indexed, target.pool_index, spec, key)
                    end
                end
            end
            local maximum = 0
            if type(indexed) == "function" then
                for _, name in ipairs({ spec[4], spec[5] }) do
                    if not current() then return visited end
                    local get = pool_mgr and pool_mgr[name]
                    if type(get) == "function" then
                        local ok, value = pcall(get)
                        if not current() then return visited end
                        if ok and Messiah.FiniteNumber(value) and value > 0 and value % 1 == 0 then
                            maximum = math.min(value, 65536); break
                        end
                    end
                end
            end
            local rendered = pool_mgr and pool_mgr[spec[2]]
            if not current() then return visited end
            if type(rendered) == "function" and (capture or acquired < pressure.max_lease_admissions) then
                local ok, pointers = pcall(rendered)
                if not current() then return visited end
                if ok and type(pointers) == "table" then
                    -- Reserve half the capture window for off-camera indexed
                    -- objects. Rendering cannot define a circular wave's reach.
                    local cap = maximum > 0 and math.ceil(per_kind / 2) or per_kind
                    local cursor_key = (capture and "capture:" or "resolve:") .. spec[1]
                    local cursor = fronts.render_cursors[cursor_key]
                    if cursor ~= nil and rawget(pointers, cursor) == nil then cursor = nil end
                    while visited < visit_limit and (pool_visits[spec[1]] or 0) < cap do
                        local key, pointer = next(pointers, cursor)
                        if key == nil then
                            cursor = nil; break
                        end
                        if type(key) ~= "number" or not Messiah.FiniteNumber(key) or key % 1 ~= 0 then
                            Messiah.ShockwaveDiagnostic(fronts, nil, nil, "invalid-rendered-key", false, spec[1]); cursor = nil; break
                        end
                        cursor = key; visit(pointer, spec, nil, nil)
                    end
                    fronts.render_cursors[cursor_key] = cursor
                end
            end
            if maximum > 0 then
                local remaining = math.min(maximum, per_kind - (pool_visits[spec[1]] or 0), visit_limit - visited)
                local cursor_key = (capture and "capture:" or "resolve:") .. spec[1]
                local start = (fronts.index_cursors[cursor_key] or ((fronts.action_serial or 1) - 1) * 16) % maximum
                for offset = 0, remaining - 1 do
                    if not current() then return visited end
                    local index = (start + offset) % maximum
                    read_indexed(indexed, index, spec, nil)
                end
                fronts.index_cursors[cursor_key] = (start + remaining) % maximum
            end
        end
        return visited
    end

    function Messiah.CaptureShockwaveTargets(fronts, now, visit_limit)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        now = tonumber(now) or fronts.started_ms
        local targets = fronts.targets or {}
        local by_key = {}
        for _, target in ipairs(targets) do by_key[target.identity_key] = target end
        local visited = Messiah.VisitShockwaveCandidates(function(lease, key, kind)
            local existing = by_key[key]
            if existing then
                if lease.pool_index ~= nil then existing.pool_index = lease.pool_index end
                Messiah.ObserveShockwaveTarget(fronts, existing, lease.sample_position, now)
                return existing
            end
            local point = lease.sample_position
            local x, y, z = vector_components(point)
            if not Messiah.FiniteNumber(x) or not Messiah.FiniteNumber(y)
                or not Messiah.FiniteNumber(z) then
                return
            end
            local dx, dy, dz = x - fronts.position.x, y - fronts.position.y, z - fronts.position.z
            local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
            local band, radius, delay = Messiah.ShockwaveBand(distance, fronts.pressure)
            if not band then
                Messiah.ShockwaveDiagnostic(fronts, nil, nil, "outside-3d-range", false, kind); return
            end
            Messiah.ShockwaveDiagnostic(fronts, "inRange", nil, nil, false, kind)
            if state.ped_lease and state.ped_lease.identity_key == key then
                Messiah.ShockwaveDiagnostic(fronts, nil, nil, "owner-excluded", false, kind); return
            end
            if lease.pool_index ~= nil then
                for _, owned in ipairs(targets) do
                    if owned.kind == kind and owned.pool_index == lease.pool_index and owned.identity_key ~= key then
                        Messiah.ShockwaveDiagnostic(fronts, nil, owned, "recycled-slot", true, kind)
                        return
                    end
                end
            end
            local cross_ms
            -- A bounded scan may first observe this target after an inner
            -- front passed but before a later front reaches it. Admit only a
            -- still-future crossing; ObserveShockwaveTarget must subsequently
            -- prove the outside-to-inside bracket from this fresh observation.
            for index = 1, 3 do
                local _, front_radius, start, finish = Messiah.ShockwaveFrontAt(fronts, index, now)
                local at = start + 320 * distance / front_radius
                if distance <= front_radius and at >= now and now <= finish
                    and (not cross_ms or at < cross_ms) then
                    cross_ms = at
                end
            end
            if not cross_ms then
                Messiah.ShockwaveDiagnostic(fronts, nil, nil, "discovered-after-crossing", false, kind); return
            end
            local pressure = Messiah.ShockwavePressure(fronts.pressure)
            if kind == "object" then
                local object_count = 0
                for _, target in ipairs(targets) do if target.kind == "object" then object_count = object_count + 1 end end
                if object_count >= math.max(1, math.floor((pressure and pressure.max_targets or 0) / 3)) then
                    Messiah.ShockwaveDiagnostic(fronts, nil, nil, "object-target-reservation", false, kind); return
                end
            end
            if #targets >= (pressure and pressure.max_targets or 0) then
                Messiah.ShockwaveDiagnostic(fronts, nil, nil, "target-capacity", false, kind); return
            end
            if now > fronts.started_ms and lease.pool_index == nil and lease.current_proof ~= true then
                return "current-proof-needed"
            end
            -- Changing discovery routes does not erase this identity's prior
            -- conversion result. In particular, a later indexed admission may
            -- not retry a throwing/malformed or exhausted rendered proof.
            local ledger = fronts.discovery_conversions and fronts.discovery_conversions[kind]
            local previous = ledger and ledger[key]
            if previous and previous.conversion_failed then
                Messiah.ShockwaveDiagnostic(fronts, nil, nil, previous.conversion_reason or "conversion-history-closed",
                    false, kind)
                return
            end
            local record = {
                identity_key = key,
                kind = kind,
                distance = distance,
                pool_index = lease.pool_index,
                band = band,
                initial_band = band,
                cross_ms = cross_ms,
                selected_ms = now,
                last_reason = "awaiting-front",
                observed_ms = now,
                observed_distance = distance,
                conversion_frame = previous and previous.conversion_frame,
                conversion_empty_count = previous and previous.conversion_empty_count,
                selection_source = lease.current_proof and "fresh-rendered-lease" or lease.pool_index ~= nil and
                    "indexed" or "release-rendered",
                position = { x = x, y = y, z = z },
                done = false
            }
            targets[#targets + 1] = record
            by_key[key] = record
            Messiah.ShockwaveDiagnostic(fronts, "selected", record, nil, false, kind)
            return record
        end, visit_limit or 96, nil, true)
        if not Messiah.ActivationContextCurrent(state, epoch) or state.shockwave_fronts ~= fronts then return 0 end
        table.sort(targets, function(left, right)
            if left.distance == right.distance then return left.identity_key < right.identity_key end
            return left.distance < right.distance
        end)
        local pressure = Messiah.ShockwavePressure(fronts.pressure)
        while #targets > (pressure and pressure.max_targets or 0) do table.remove(targets) end
        fronts.targets, fronts.capture_visits = targets, (fronts.capture_visits or 0) + visited
        return #targets
    end

    function Messiah.ApplyShockwaveDamage(fronts, target, lease)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch) and state.shockwave_fronts == fronts
        end
        if not current() or type(target) ~= "table" or type(lease) ~= "table"
            or not target.response_claimed or target.damage_attempted
            or fronts.epoch ~= epoch or lease.identity_key ~= target.identity_key
            or lease.kind ~= target.kind or lease.handle == state.ped or state.projectiles[lease.handle]
            or not Messiah.EntityContextMatches(lease, { action = "SHOCKWAVE",
                action_serial = fronts.action_serial, epoch = epoch }) then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-context-rejected")
        end
        local ped = lease.kind == "ped"
        if not ped and lease.kind ~= "vehicle" and lease.kind ~= "object" then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-kind-rejected")
        end
        local vehicle = lease.kind == "vehicle"
        local name = ped and "APPLY_DAMAGE_TO_PED" or vehicle and "SET_VEHICLE_ENGINE_HEALTH" or "SET_ENTITY_HEALTH"
        local hash = ped and H.APPLY_DAMAGE_TO_PED or vehicle and H.SET_VEHICLE_ENGINE_HEALTH or H.SET_ENTITY_HEALTH
        local point = Messiah.LeaseInvoke(lease, "vec3", "GET_ENTITY_COORDS", H.GET_ENTITY_COORDS, lease.handle, false)
        if not current() then return false end
        local x, y, z = vector_components(point)
        if not Messiah.FiniteNumber(x) or not Messiah.FiniteNumber(y) or not Messiah.FiniteNumber(z) then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-position-unavailable")
        end
        local dx, dy, dz = x - fronts.position.x, y - fronts.position.y, z - fronts.position.z
        local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
        target.current_distance = distance
        local covered, _, reason = Messiah.ShockwaveResponsePosition(fronts, target, { x = x, y = y, z = z }, now_ms())
        if not covered then return Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-" .. reason) end
        local amount = 0
        if ped then
            local health, raw, err = Messiah.LeaseInvoke(lease, "int", "GET_ENTITY_HEALTH", H.GET_ENTITY_HEALTH,
                lease.handle)
            if not current() then return false end
            if err or not Messiah.FiniteNumber(raw) or not Messiah.FiniteNumber(health) then
                return Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-health-unavailable")
            end
            -- The wave injures a healthy ped without executing it before its
            -- ragdoll flight. Never heal an already injured ped to this floor.
            amount = math.floor(math.min(Messiah.SHOCKWAVE_PED_DAMAGE,
                math.max(0, health - Messiah.SHOCKWAVE_PED_HEALTH_FLOOR)))
            if amount <= 0 then
                return Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-low-health-physics-only",
                    true)
            end
        elseif vehicle then
            local health, raw, err = Messiah.LeaseInvoke(lease, "float", "GET_VEHICLE_ENGINE_HEALTH",
                H.GET_VEHICLE_ENGINE_HEALTH, lease.handle)
            if not current() then return false end
            if err or not Messiah.FiniteNumber(raw) or not Messiah.FiniteNumber(health) then
                return Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-engine-unavailable")
            end
            amount = math.max(-4000.0, health - Messiah.SHOCKWAVE_ENGINE_DAMAGE)
        end
        if not hash or not Messiah.ValidateEntityLease(lease, name, hash) or not current() then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-lease-rejected")
        end
        -- Health/identity reads are host boundaries too. Recheck spatial
        -- eligibility after them, immediately before the final damage fence.
        -- No further target native follows this coordinate read before damage.
        local final_frame = state.entity_frame
        local final_release_serial = state.script_guid_release_serial
        local final = Messiah.LeaseInvoke(lease, "vec3", "GET_ENTITY_COORDS", H.GET_ENTITY_COORDS, lease.handle, false)
        if not current() then return false end
        local final_covered, _, final_reason = Messiah.ShockwaveResponsePosition(fronts, target, final, now_ms())
        -- The coordinate/timer callbacks may revoke a sibling GUID or advance
        -- ownership without replacing this activation. Recheck metadata only;
        -- another entity read here would reopen the final native boundary.
        local final_current = current() and state.entity_frame == final_frame
            and lease.frame == final_frame
            and (tonumber(lease.blast_generation) or 0) == (tonumber(state.blast_generation) or 0)
            and Messiah.ScriptGuidContextCurrent(lease, state, final_release_serial)
        if not final_current then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-final-lease-rejected", true)
        end
        if not final_covered then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-final-" .. final_reason, true)
        end
        if not ped and not Messiah.RecordReleasedScriptGuid(lease.handle, state) then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "guid-registry-capacity")
        end
        -- Revoke sibling leases before damage and never read the entity after
        -- it. A bounded nonlethal ped hit does not destroy the physical identity
        -- or release its GUID; a later cast must prove it afresh. Vehicle fire
        -- and object destruction retain the terminal fence before their call.
        target.damage_attempted = true
        target.damage_amount = amount
        fronts.damage_attempted = fronts.damage_attempted + 1
        Messiah.ShockwaveDiagnostic(fronts, "damageAttempted", target)
        if ped then
            lease.identity.borrowed_revision = (tonumber(lease.identity.borrowed_revision) or 0) + 1
            Messiah.RetireEntityLease(lease, "shockwave-nonlethal-damage", false)
        else
            Messiah.RetireEntityLease(lease, "shockwave-terminal-damage", true)
        end
        local accepted, raw, err
        if ped then
            accepted, raw, err = invoke_void_detail(hash, lease.handle, amount, true, 0, 0)
        elseif vehicle then
            accepted, raw, err = invoke_void_detail(hash, lease.handle, amount)
        else
            accepted, raw, err = invoke_void_detail(hash, lease.handle, 0, 0, 0)
        end
        if not current() then return false end
        if ped and (err or accepted ~= true) then
            -- Uncertain/rejected host outcomes are consumed without retry.
            -- Do not admit this alias again after an unproven damage boundary.
            Messiah.RecordReleasedScriptGuid(lease.handle, state)
            Messiah.RetireEntityLease(lease, "shockwave-damage-unproven", true)
        end
        target.damage_status = err and "uncertain" or (accepted == true and "accepted" or "rejected")
        Messiah.ShockwaveDiagnostic(fronts, nil, target, "damage-" .. target.damage_status, true)
        if err then
            fronts.damage_uncertain = fronts.damage_uncertain + 1
        elseif accepted == true then
            fronts.damage_accepted = fronts.damage_accepted + 1
        else
            fronts.damage_rejected = fronts.damage_rejected + 1
        end
        return accepted == true
    end

    function Messiah.ApplyShockwaveTarget(fronts, target, lease, point)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch) and state.shockwave_fronts == fronts
        end
        if not current() then return false end
        if type(fronts) ~= "table" or type(target) ~= "table" or type(lease) ~= "table"
            or not Messiah.EntityOwner() or fronts ~= state.shockwave_fronts
            or not Messiah.EntityContextMatches(lease, { action = "SHOCKWAVE",
                action_serial = fronts.action_serial, epoch = fronts.epoch })
            or lease.handle == state.ped or state.projectiles[lease.handle]
            or fronts.epoch ~= state.activation_epoch or lease.epoch ~= fronts.epoch
            or lease.identity_key ~= target.identity_key or target.done
            or target.kind ~= lease.kind then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "response-context-rejected")
        end
        local pressure = Messiah.ShockwavePressure(fronts.pressure)
        if not pressure then return Messiah.ShockwaveDiagnostic(fronts, nil, target, "pressure-invalid") end
        local px, py, pz = vector_components(point)
        if not Messiah.FiniteNumber(px) or not Messiah.FiniteNumber(py)
            or not Messiah.FiniteNumber(pz) then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "response-position-unavailable")
        end
        local covered, _, reason = Messiah.ShockwaveResponsePosition(fronts, target, point, now_ms())
        if not covered then return Messiah.ShockwaveDiagnostic(fronts, nil, target, "response-" .. reason) end
        if lease.kind == "ped" then
            local seated, raw, err = Messiah.LeaseInvoke(lease, "bool", "IS_PED_IN_ANY_VEHICLE",
                H.IS_PED_IN_ANY_VEHICLE, lease.handle, false)
            if not current() then return false end
            if err or (raw ~= false and raw ~= 0) or seated then
                return Messiah.ShockwaveDiagnostic(fronts, nil, target, seated and "seated-ped" or "seat-state-unknown",
                    true)
            end
        end
        Messiah.ShockwaveDiagnostic(fronts, "eligible", target)
        local control = Messiah.AcquireDamageControl(lease.handle, lease,
            Messiah.SHOCKWAVE_CONTROL_REQUEST_MS)
        if not current() then return false end
        -- A rate-limited check is not another acquisition attempt. Counting
        -- each high-FPS frame used to exhaust all 12 slots before control
        -- could arrive. Keep readbacks responsive and requests bounded.
        target.control_checks = (target.control_checks or 0) + 1
        target.control_polls = (target.control_polls or 0) + (control.requested and 1 or 0)
        if control.after ~= true then
            -- A request can complete on a later gameplay frame. Save only the
            -- opaque target identity; the next poll must acquire a fresh lease.
            if control.session_known and control.control_known and lease.state == "live" then
                target.control_pending = true
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "control-pending")
                target.control_deadline_ms = target.control_deadline_ms
                    or math.min(fronts.expires_ms, now_ms() + Messiah.SHOCKWAVE_CONTROL_GRACE_MS)
                if target.control_polls >= Messiah.SHOCKWAVE_CONTROL_POLL_CAP then
                    Messiah.ShockwaveDiagnostic(fronts, nil, target, "control-poll-limit", true)
                    fronts.control_timeouts = fronts.control_timeouts + 1
                end
            else
                target.control_status = "invalid-or-unknown"
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "control-invalid-or-unknown", true)
            end
            return false
        end
        target.control_pending = false
        target.control_status = "acquired"
        Messiah.ShockwaveDiagnostic(fronts, "controlAcquired", target)
        -- Control callbacks can move the entity or complete a later frame.
        -- Re-sample before any response, not only before terminal damage.
        local moved = Messiah.LeaseInvoke(lease, "vec3", "GET_ENTITY_COORDS", H.GET_ENTITY_COORDS, lease.handle, false)
        if not current() then return false end
        local mx, my, mz = vector_components(moved)
        if not Messiah.FiniteNumber(mx) or not Messiah.FiniteNumber(my) or not Messiah.FiniteNumber(mz) then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "post-control-position-unavailable", true)
        end
        local qx, qy, qz = mx - fronts.position.x, my - fronts.position.y, mz - fronts.position.z
        local distance = math.sqrt(qx * qx + qy * qy + qz * qz)
        target.current_distance = distance
        local covered, _, reason = Messiah.ShockwaveResponsePosition(fronts, target, { x = mx, y = my, z = mz }, now_ms())
        if not covered then
            return Messiah.ShockwaveDiagnostic(fronts, nil, target, "post-control-" .. reason,
                reason == "outside-3d-range")
        end
        point = { x = mx, y = my, z = mz }
        local dx, dy = point.x - fronts.position.x, point.y - fronts.position.y
        local flat = math.sqrt(dx * dx + dy * dy)
        if flat < 0.01 then dx, dy, flat = 0, 1, 1 end
        -- Claim before the first possible mutation. No uncertain force call is
        -- retried, and each identity consumes exactly one proven front crossing.
        target.done, target.response_claimed = true, true
        if lease.kind == "ped" then
            Messiah.LeaseInvoke(lease, "bool", "SET_PED_TO_RAGDOLL", H.SET_PED_TO_RAGDOLL,
                lease.handle, 1400, 1800, 0, true, true, false)
            if not current() then return false end
        end
        Messiah.ShockwaveDiagnostic(fronts, "forceAttempted", target)
        local ux, uy = dx / flat, dy / flat
        local ped = lease.kind == "ped"
        local outward = pressure.force * (ped and 0.45 or 1.0)
        local lift = pressure.lift * (ped and 0.35 or 0.45)
        local offset = ped and 0.12 or 0.35
        -- One world-space off-center impulse creates outward translation AND
        -- a tipping moment. COM-only impulses kept cars rigidly upright. Type1
        -- is internal impulse; no fragment-destroying external force is added
        -- before the final damage fence. Visual shell geometry is unchanged.
        local accepted, force_raw, force_error = Messiah.LeaseInvoke(lease, "void", "APPLY_FORCE_TO_ENTITY",
            H.APPLY_FORCE_TO_ENTITY, lease.handle, 1,
            ux * outward, uy * outward, lift, -uy * offset, ux * offset, ped and 0.15 or 0.45,
            0, false, false, true, false, true)
        if not current() then return false end
        if accepted == true then
            fronts.force_accepted = fronts.force_accepted + 1
        else
            fronts.force_rejected = fronts.force_rejected + 1
        end
        target.force_status = accepted == true and "accepted" or tostring(force_error or "rejected"):sub(1, 64)
        local damaged = Messiah.ApplyShockwaveDamage(fronts, target, lease)
        if current() and not target.final_reason then
            Messiah.ShockwaveDiagnostic(fronts, nil, target,
                "force-only:" .. tostring(target.last_reason or target.force_status), true)
        end
        return accepted == true or damaged == true
    end

    function Messiah.TickShockwaveFronts(now)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local fronts = state.shockwave_fronts
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch) and state.shockwave_fronts == fronts
        end
        if not fronts then return 0 end
        if not Messiah.EntityOwner() or state.ending or state.cleanup_owner
            or fronts.epoch ~= state.activation_epoch then
            state.shockwave_fronts = nil
            Messiah.FinishShockwaveDiagnostics(fronts, "owner-revoked")
            return 0
        end
        if fronts.polled_frame == state.entity_frame then return 0 end
        fronts.polled_frame = state.entity_frame
        for index, delay in ipairs({ 320, 520, 760 }) do
            if now >= fronts.started_ms + delay and not fronts.pulsed[index] then
                fronts.pulsed[index] = true
                if now <= fronts.started_ms + delay + 180
                    and type(Messiah.PlayShockwavePulse) == "function" then
                    Messiah.PlayShockwavePulse(index, fronts.position,
                        { action_serial = fronts.action_serial, epoch = fronts.epoch })
                    if not current() then return 0 end
                end
            end
        end
        if now > fronts.expires_ms then
            log_info(("Messiah Shockwave fronts: epoch=%d actionSerial=%d fronts=3 "
                .. "radii=8/16/24 startMs=0/200/440 finishMs=320/520/760 selected=%d captureVisits=%d "
                .. "forceAccepted=%d forceRejected=%d damageAttempted=%d damageAccepted=%d "
                .. "damageRejected=%d damageUncertain=%d controlTimeouts=%d "
                .. "outcome=LIVE_RETEST_REQUIRED."):format(fronts.epoch, fronts.action_serial,
                #fronts.targets, fronts.capture_visits, fronts.force_accepted, fronts.force_rejected,
                fronts.damage_attempted, fronts.damage_accepted, fronts.damage_rejected,
                fronts.damage_uncertain, fronts.control_timeouts))
            if not current() then return 0 end
            state.shockwave_fronts = nil
            Messiah.FinishShockwaveDiagnostics(fronts, "expired")
            return 0
        end
        -- Discovery and re-resolution share the same 96 pointer visits and
        -- eight lease admissions per gameplay frame. Rotation is bounded;
        -- large pools can still leave undiscovered targets behind a passed front.
        if now <= fronts.started_ms + 760 then
            Messiah.CaptureShockwaveTargets(fronts, now, 48)
        end
        if not current() or fronts.proof_revoked_frame == state.entity_frame then return 0 end
        local due, pending = {}, false
        for _, target in ipairs(fronts.targets) do
            if not target.done and target.control_pending and
                (now > target.control_deadline_ms or target.control_polls >= Messiah.SHOCKWAVE_CONTROL_POLL_CAP) then
                target.control_status = "timeout"
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "control-timeout", true)
                fronts.control_timeouts = fronts.control_timeouts + 1
            end
            if not target.done and now >= target.cross_ms then
                due[target.identity_key], pending = target, true
            end
        end
        if not pending then return 0 end
        local responses = 0
        local visits = Messiah.VisitShockwaveCandidates(function(lease, key)
            local target = due[key]
            if not target then return end
            local coords = Messiah.LeaseInvoke(lease, "vec3", "GET_ENTITY_COORDS",
                H.GET_ENTITY_COORDS, lease.handle, false)
            if not current() then return end
            local x, y, z = vector_components(coords)
            if not Messiah.FiniteNumber(x) or not Messiah.FiniteNumber(y)
                or not Messiah.FiniteNumber(z) then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, "invalid-current-position"); return
            end
            local dx, dy, dz = x - fronts.position.x, y - fronts.position.y, z - fronts.position.z
            local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
            target.current_distance = distance
            Messiah.ObserveShockwaveTarget(fronts, target, { x = x, y = y, z = z }, now)
            local covered, _, reason = Messiah.ShockwaveResponsePosition(fronts, target, { x = x, y = y, z = z }, now)
            if not covered then
                Messiah.ShockwaveDiagnostic(fronts, nil, target, reason, reason == "outside-3d-range"); return
            end
            Messiah.ShockwaveDiagnostic(fronts, "crossed", target)
            if Messiah.ApplyShockwaveTarget(fronts, target, lease, { x = x, y = y, z = z }) then
                responses = responses +
                    1
            end
        end, 96, due, false)
        if not current() then return responses end
        fronts.visits = (fronts.visits or 0) + visits
        return responses
    end

    function Messiah.ReleaseShockwave(now, ped, action)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local function current() return Messiah.ActionContextCurrent(state, epoch, action, "SHOCKWAVE") end
        if not current() then return false end
        local pressure = Messiah.ShockwavePressure()
        if not pressure then return false end
        local owner_lease = state.ped_lease
        if ped ~= state.ped or type(owner_lease) ~= "table" or not owner_lease.owned
            or owner_lease.handle ~= ped then
            return false
        end
        local coords = Messiah.LeaseInvoke(owner_lease, "vec3", "GET_ENTITY_COORDS", H.GET_ENTITY_COORDS, ped, false)
        if not current() or state.ped ~= ped or state.ped_lease ~= owner_lease then return false end
        local x, y, z = vector_components(coords)
        if not Messiah.FiniteNumber(x) or not Messiah.FiniteNumber(y) or not Messiah.FiniteNumber(z) then return false end
        -- The 360 ms windup can contain movement. Freeze one owned-ped release
        -- sample for all shells, target bands and pulses; never follow it later.
        local center = { x = x, y = y, z = z }
        local previous = state.shockwave_fronts
        if previous and now <= previous.expires_ms then return false end
        if previous then
            state.shockwave_fronts = nil
            Messiah.FinishShockwaveDiagnostics(previous, "expired")
            if not current() then return false end
        end
        local fronts = {
            epoch = state.activation_epoch,
            action_serial = action.serial,
            started_ms = now,
            expires_ms = now + 940,
            position = center,
            pulsed = {},
            targets = {},
            force_accepted = 0,
            force_rejected = 0,
            pressure = {},
            center_source = "release-owned-ped",
            damage_attempted = 0,
            damage_accepted = 0,
            damage_rejected = 0,
            damage_uncertain = 0,
            control_timeouts = 0
        }
        for key, value in pairs(pressure) do fronts.pressure[key] = value end
        state.shockwave_fronts = fronts
        Messiah.CaptureShockwaveTargets(fronts)
        if not current() then return false end
        local markers = state.visuals.markers
        fronts.presentation_admitted = Messiah.AdmitPresentation(85, 3) == true
        if not current() then return false end
        if not fronts.presentation_admitted then
            log_info(("Messiah Shockwave presentation refused: epoch=%d actionSerial=%d "
                .. "requiredFronts=3 publishedFronts=0 reason=protected-visual-capacity "
                .. "physicalOwnershipPreserved=true."):format(fronts.epoch, fronts.action_serial))
            return true
        end
        for index, radius in ipairs({ 8, 16, 24 }) do
            local delay = ({ 320, 520, 760 })[index]
            markers[#markers + 1] = {
                kind = "shockwave-front",
                local_only = true,
                presentation_priority = 85,
                epoch = fronts.epoch,
                owner_epoch = fronts.epoch,
                action_serial = action.serial,
                shell_index = index,
                started_ms = now + delay - 320,
                crosses_ms = now + delay,
                expires_ms = now + delay + 180,
                radius_from = 0,
                radius_to = radius,
                position = { x = center.x, y = center.y, z = center.z },
                alpha = 225
            }
        end
        return true
    end

    function Messiah.ReleaseSuper(now, action)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local function current() return Messiah.ActionContextCurrent(state, epoch, action, "SUPER") end
        if not current() then return false end
        local target = Messiah.CopyPoint(action.target)
        if not target then return false end
        Messiah.StopSoundRole("judgment-charge")
        if not current() then return false end
        Messiah.PlayFrontendSound("judgment-descent", "background_loop",
            "dlc_xm_orbital_cannon_sounds", Messiah.SUPER_RELEASE_MS + 500, true,
            { action_serial = action.serial, epoch = epoch })
        if not current() then return false end
        Messiah.AddBeam(now, { x = target.x, y = target.y, z = target.z + 52.0 },
            target, Messiah.SUPER_RELEASE_MS, "judgment", Messiah.MAX_BEAM_LAYERS)
        if not current() then return false end
        Messiah.AddLight(now, { x = target.x, y = target.y, z = target.z + 4.0 },
            24.0, 7.0, Messiah.SUPER_RELEASE_MS, { 132, 214, 255 })
        if not current() then return false end
        log_info(("Messiah Judgment stage: activation=%d actionSerial=%d stage=DESCENT "
                .. "locked=(%.2f,%.2f,%.2f) beamHeight=52.0.")
            :format(state.activation_id, action.serial, target.x, target.y, target.z))
        if not current() then return false end
        Messiah.ScheduleImpact(now, 40, {
            owner_state = state,
            profile = "SUPER_IMPACT",
            position = target,
            action_serial = action.serial,
            stage = "DESCENT_CORE",
            options = {
                action = "SUPER",
                epoch = epoch,
                diagnostic_key = "super-descent-core",
                blast_scale = 4.0,
                max_fx = 0,
                no_visual_records = true,
                final_core = false,
                essential = true
            },
        })
        if not current() then return false end
        local audio_index = 0
        for ring = 1, 2 do
            local radius = ring == 1 and 5.5 or 11.0
            for index = 0, 3 do
                local angle = index * math.pi * 0.5 + (ring == 2 and math.pi * 0.25 or 0.0)
                local point = {
                    x = target.x + math.cos(angle) * radius,
                    y = target.y + math.sin(angle) * radius,
                    z = target.z,
                }
                audio_index = audio_index + 1
                Messiah.ScheduleImpact(now, (ring - 1) * 240 + 80 + index * 35, {
                    owner_state = state,
                    profile = "SUPER_IMPACT",
                    position = point,
                    action_serial = action.serial,
                    stage = index == 0 and ("RING_" .. tostring(ring)) or nil,
                    options = {
                        action = "SUPER",
                        epoch = epoch,
                        diagnostic_key = "super-ring",
                        blast_scale = 3.0,
                        max_fx = 0,
                        fx_profile = "LANCE_IMPACT",
                        audio_index = audio_index,
                        visual_center_x = target.x,
                        visual_center_y = target.y,
                        visual_center_z = target.z,
                        final_core = false
                    },
                })
                if not current() then return false end
            end
        end
        Messiah.ScheduleImpact(now, 650, {
            owner_state = state,
            profile = "SUPER_IMPACT",
            position = target,
            action_serial = action.serial,
            stage = "FINAL_CORE",
            options = {
                action = "SUPER",
                epoch = epoch,
                diagnostic_key = "super-core",
                blast_scale = 6.0,
                max_fx = 1,
                no_vanilla_fx = false,
                native_sound = true,
                final_core = true,
                audio_final = true,
                flush_damage = true,
                flush_reason = "judgment-final-core"
            },
        })
        if not current() then return false end
        log_info(("Messiah Judgment released: activation=%d serial=%d "
                .. "locked=(%.2f,%.2f,%.2f) descentCore=1 rings=2 ringImpacts=8 finalCore=1 "
                .. "scheduledImpacts=10 descentLayers=%d immutable=true "
                .. "descentSizeScale=4.0 satelliteSizeScale=3.0 coreSizeScale=6.0 "
                .. "engineBlasts=10 targetNatives=0 poolScans=0 nativePhysics=true.")
            :format(state.activation_id, action.serial, target.x, target.y, target.z,
                Messiah.MAX_BEAM_LAYERS))
        return true
    end

    function Messiah.BeginRequestedAction(now, menu_open)
        local state = Messiah.State()
        local ability = state.pending_ability
        if not ability or state.action then return false end
        if menu_open and not state.pending_allow_menu then return false end
        if state.phase ~= Messiah.PHASES.IDLE_HOVER and state.phase ~= Messiah.PHASES.GLIDING then
            return false
        end
        if ability == "ORB" and not Messiah.ModelUsable() then
            if state.model_state == "REQUESTED" or state.model_state == "LOADING" then return false end
            state.pending_ability, state.pending_target = nil, nil
            state.pending_source, state.pending_allow_menu = "none", false
            state.queued_cast = false
            return false
        end
        local target = Messiah.CopyPoint(state.pending_target)
        local source = state.pending_source
        local deferred = state.queued_cast == true
        state.pending_ability, state.pending_target = nil, nil
        state.pending_source, state.pending_allow_menu = "none", false
        state.queued_cast, state.cast_edge_pending = false, false
        local begun = Messiah.BeginAbility(now, ability, target, source)
        if begun and ability == "ORB" then
            log_info(("Messiah Orb edge consumed: activation=%d inputSerial=%d deferred=%s queueDepth=0.")
                :format(state.activation_id, state.input_edge_serial, tostring(deferred)))
        end
        return begun
    end

    function Messiah.TickActionState(now, ped)
        local state = Messiah.State()
        local epoch = state.activation_epoch
        local action = state.action
        if not action then return false end
        local ability = action.ability
        local function current() return Messiah.ActionContextCurrent(state, epoch, action, ability, true) end
        if not current() then
            -- A stale action must not run release/cleanup natives under a new
            -- activation. Revoke only detached state; lifecycle owns old handles.
            action.ending = true
            if State.messiah == state and state.action == action then
                state.action = nil
                if state.channel_beam and state.channel_beam.owner_epoch == action.epoch then
                    state.channel_beam = nil
                end
                state.hud_snapshot, state.visual_snapshot, state.visual_build = nil, nil, nil
            end
            return false
        end
        local config = Messiah.ABILITIES[ability]
        if not config then
            state.action = nil
            return false
        end
        local elapsed = now - state.phase_started_ms
        if ability == "LANCE" and (not state.ped_lease or not Messiah.ValidateEntityLease(state.ped_lease,
                "lance-action-owner", "none")) then
            if not current() then return false end
            Messiah.EndVoidLance(now, "invalid-owner-or-epoch")
            return false
        end
        if not current() then return false end
        local menu_open = ability == "LANCE" and Messiah.MenuOpen() or false
        if not current() then return false end
        if state.phase == Messiah.AbilityPhase(ability, "WINDUP") then
            if elapsed >= config.windup then
                if ability == "LANCE" then
                    local input = state.inputs.LANCE or {}
                    if input.down == true and not menu_open then
                        Messiah.SetPhase(Messiah.PHASES.LANCE_CHANNEL, now,
                            "ability=LANCE windup complete input=held")
                        if not current() then return false end
                        Messiah.UpdateVoidLanceChannel(now, ped, action)
                    elseif not menu_open and action.legitimate_lance_press == true
                        and action.ending ~= true and input.source ~= "baseline"
                        and input.source ~= "menu-baseline" then
                        -- A genuine gameplay edge owns one copied coordinate pulse.
                        -- A new press during it cannot extend it into an automatic channel.
                        action.minimum_pulse, action.pulse_until_ms = true, now + 150
                        Messiah.SetPhase(Messiah.PHASES.LANCE_CHANNEL, now,
                            "ability=LANCE windup complete input=short-press minimumPulseMs=150")
                        if not current() then return false end
                        Messiah.UpdateVoidLanceChannel(now, ped, action)
                    else
                        Messiah.EndVoidLance(now, "cancelled-input-before-channel")
                    end
                else
                    if action.ground_marker == true and action.ground_marker_removed ~= true then
                        action.ground_marker_removed = true
                        log_info(("Messiah ground marker removed: activation=%d actionSerial=%d "
                                .. "ability=%s reason=release-start fixedTarget=true.")
                            :format(state.activation_id, action.serial, ability))
                        if not current() then return false end
                    end
                    Messiah.SetPhase(Messiah.AbilityPhase(ability, "RELEASE"), now,
                        "ability=" .. ability .. " windup complete")
                end
            end
            return true
        end
        if ability == "LANCE" and state.phase == Messiah.PHASES.LANCE_CHANNEL then
            local input = state.inputs.LANCE or {}
            if menu_open or (action.minimum_pulse == true
                    and now >= action.pulse_until_ms)
                or (action.minimum_pulse ~= true and input.down ~= true) then
                Messiah.EndVoidLance(now, menu_open and "menu-open"
                    or action.minimum_pulse == true and "minimum-pulse-complete" or "input-up")
            else
                Messiah.UpdateVoidLanceChannel(now, ped, action)
            end
            return true
        end
        if state.phase == Messiah.AbilityPhase(ability, "RELEASE") then
            if not action.released then
                action.released = true
                if ability == "ORB" then
                    Messiah.FireOrb(now, ped)
                elseif ability == "LANCE" then
                    Messiah.ReleaseVoidLance(now, ped, action)
                elseif ability == "RUPTURE" then
                    Messiah.ReleaseGroundRupture(now, action)
                elseif ability == "SHOCKWAVE" then
                    Messiah.ReleaseShockwave(now, ped, action)
                elseif ability == "SUPER" then
                    Messiah.ReleaseSuper(now, action)
                end
                if not current() then return false end
            end
            if elapsed >= config.release then
                Messiah.SetPhase(Messiah.AbilityPhase(ability, "RECOVER"), now,
                    "ability=" .. ability .. " release complete")
            end
            return true
        end
        if state.phase == Messiah.AbilityPhase(ability, "RECOVER") then
            if elapsed >= config.recover then
                local serial = action.serial
                if state.animation_current ~= "none" then
                    Messiah.ClearOwnedActionAnimation(
                        ped, state.animation_current, "action-recovery:" .. ability)
                    if not current() then return false end
                end
                state.action = nil
                Messiah.ReassertIdleStance(now, "action-recovery:" .. ability)
                if not Messiah.ActivationContextCurrent(state, epoch) or state.action ~= nil then return false end
                Messiah.SetPhase(Messiah.BaseMotionPhase(state), now,
                    "ability=" .. ability .. " recovery complete")
                if not Messiah.ActivationContextCurrent(state, epoch) or state.action ~= nil then return false end
                log_info(("Messiah action complete: activation=%d serial=%d ability=%s "
                        .. "resume=%s scheduledRemaining=%d.")
                    :format(state.activation_id, serial, ability, state.phase,
                        #state.scheduled_impacts))
            end
            return true
        end
        return false
    end

    function Messiah.ApproachVelocity2D(state, target_x, target_y, maximum_delta)
        local dx, dy = target_x - state.move_vx, target_y - state.move_vy
        local length = math.sqrt(dx * dx + dy * dy)
        if length <= maximum_delta or length < 0.0001 then
            state.move_vx, state.move_vy = target_x, target_y
        else
            local scale = maximum_delta / length
            state.move_vx = state.move_vx + dx * scale
            state.move_vy = state.move_vy + dy * scale
        end
    end

    -- Diagnostic only: an equal vector does not prove exclusive motion ownership.
    function Messiah.RecordMotionWrite(accepted, lease, now, x, y, z)
        local state = type(State.messiah) == "table" and State.messiah or nil
        if not state then return false end
        if accepted ~= true or not state.gameplay_owner or not state.active
            or state.restoring or state.disposed or state.cleanup_failed
            or lease ~= state.ped_lease or not lease or lease.state ~= "live"
            or not Messiah.VisualFinite(now) or not Messiah.VisualFinite(x)
            or not Messiah.VisualFinite(y) or not Messiah.VisualFinite(z) then
            state.last_motion_write = nil
            return false
        end
        local record = state.last_motion_write or {}
        record.lease, record.ped, record.epoch = lease, lease.handle, lease.epoch
        record.identity_key = lease.identity_key
        record.frame, record.now_ms = state.entity_frame, now
        record.x, record.y, record.z = x, y, z
        state.last_motion_write = record
        return true
    end

    function Messiah.ObserveMotionRelease(ped, now)
        local state = type(State.messiah) == "table" and State.messiah or nil
        if not state or not state.gameplay_owner or not state.cleanup_owner
            or not state.restoring or state.disposed or state.cleanup_failed
            or state.restore_reason ~= "feature disabled" then
            return false, "context"
        end
        local record, lease = state.last_motion_write, state.ped_lease
        state.last_motion_write = nil -- Consume once, before any fallible read.
        if not record or not lease or record.lease ~= lease or lease.state ~= "live"
            or ped ~= state.ped or ped ~= lease.handle or ped ~= record.ped
            or record.epoch ~= state.cleanup_epoch or lease.epoch ~= record.epoch
            or record.identity_key ~= lease.identity_key then
            return false, "ownership"
        end
        if not Messiah.VisualFinite(now) or not Messiah.VisualFinite(record.now_ms)
            or now < record.now_ms or now - record.now_ms > 100
            or type(state.entity_frame) ~= "number" or type(record.frame) ~= "number"
            or state.entity_frame < record.frame or state.entity_frame - record.frame > 1 then
            return false, "stale"
        end
        if not Messiah.ValidateEntityLease(lease, "motion-release-observation", "none") then
            return false, "lease"
        end
        for _, query in ipairs({ { "IS_ENTITY_DEAD", false },
            { "IS_PED_DEAD_OR_DYING", true }, { "IS_PED_IN_ANY_VEHICLE", false } }) do
            if not H[query[1]] then return false, "query-unavailable" end
            local value, raw, err = Messiah.LeaseInvoke(lease, "bool", query[1], H[query[1]], ped, query[2])
            if err or (raw ~= true and raw ~= false and raw ~= 0 and raw ~= 1) then
                return false, "query-unknown"
            end
            if value ~= false then return false, query[1] end
        end
        if not H.GET_ENTITY_VELOCITY then return false, "query-unavailable" end
        local observed, _, err = Messiah.LeaseInvoke(lease, "vec3", "GET_ENTITY_VELOCITY",
            H.GET_ENTITY_VELOCITY, ped)
        local x, y, z = vector_components(observed)
        if err or not Messiah.VisualFinite(x) or not Messiah.VisualFinite(y)
            or not Messiah.VisualFinite(z) then
            return false, "velocity-unknown"
        end
        log_info(("Messiah motion release observation: ageMs=%d "
                .. "last=(%.3f,%.3f,%.3f) current=(%.3f,%.3f,%.3f) "
                .. "delta=(%.3f,%.3f,%.3f) resetApplied=false ownershipFromVelocity=false.")
            :format(now - record.now_ms, record.x, record.y, record.z, x, y, z,
                x - record.x, y - record.y, z - record.z))
        return true, "observed-only"
    end

    -- Self-only observation. LeaseInvoke's shared owned-lease validation does
    -- not guard a reentrant frame change between its internal host reads. This
    -- bounded diagnostic therefore proves this exact owned ped identity and
    -- checks the captured context before AND after every read-only boundary.
    -- It neither repairs networking nor proves that another client received it.
    function Messiah.PeerSelfDiagnostic(now, ped)
        local state = type(State.messiah) == "table" and State.messiah or nil
        if not state or not Messiah.VisualFinite(now) then return false end
        local epoch, frame, lease = state.activation_epoch, state.entity_frame, state.ped_lease
        local identity, key = lease and lease.identity, lease and lease.identity_key
        local release_serial = state.script_guid_release_serial
        local function current()
            return Messiah.ActivationContextCurrent(state, epoch) and state.entity_frame == frame
                and state.ped_lease == lease and state.ped == ped and lease ~= nil
                and lease.handle == ped and lease.owned == true and lease.kind == "ped"
                and lease.state == "live" and lease.epoch == epoch
                and identity ~= nil and lease.identity == identity and identity.terminal ~= true
                and identity.key == key and lease.identity_key == key
                and state.script_guid_release_serial == release_serial
                and not Messiah.IsReleasedScriptGuid(ped, state)
        end
        if not current() then return false end
        if state.peer_diagnostic_epoch == epoch and type(state.peer_diagnostic_ms) == "number"
            and now < state.peer_diagnostic_ms + 5000 then
            return false
        end
        -- Consume the same five-second opportunity before any fallible read.
        state.peer_diagnostic_epoch, state.peer_diagnostic_ms = epoch, now
        local function text(value)
            local kind = type(value)
            if kind == "nil" then return "nil" end
            if kind == "boolean" or kind == "number" then return tostring(value) end
            if kind == "string" then return value:gsub("[%c]", " "):sub(1, 96) end
            return "unsupported-" .. kind
        end
        local function boundary(callback, ...)
            if not current() then return false end
            local ok, a, b, c = pcall(callback, ...)
            if not current() then return false end
            return ok, a, b, c
        end
        -- Hashes below are read-only signatures from the supplied natives.json;
        -- keep them Messiah-local rather than extending another module's H map.
        local hashes = {
            DOES_ENTITY_EXIST = 0x7239B21A38F536BA,
            GET_ENTITY_TYPE = 0x8ACD366038D14505,
            IS_ENTITY_DEAD = 0x5F9532F3B5CC2551,
            IS_PED_DEAD_OR_DYING = 0x3317DEDB88C95038,
            NETWORK_GET_ENTITY_IS_NETWORKED = 0xC7827959479DCC78,
            NETWORK_GET_NETWORK_ID_FROM_ENTITY = 0xA11700682F3AD45C,
            NETWORK_HAS_CONTROL_OF_ENTITY = 0x01BF60A500E28887,
            IS_ENTITY_VISIBLE = 0x47D6F43D77935C75,
            GET_ENTITY_ALPHA = 0x5A47B3B5E63E94C6,
            GET_ENTITY_COORDS = 0x3FEF770D40960D5A,
            GET_ENTITY_VELOCITY = 0x4805D2B1D8CF94A9,
            IS_ENTITY_PLAYING_ANIM = 0x1F0B79228E461EC9,
            NETWORK_GET_NUM_CONNECTED_PLAYERS = 0xA4A79DD2D9600654,
        }
        local function read(kind, name, ...)
            local callback = kind == "bool" and invoke_bool_detail or invoke_int_detail
            local ok, value, raw, err = boundary(callback, hashes[name], ...)
            if not current() then return nil end
            if not ok then err, value, raw = text(value), nil, nil end
            local known = err == nil and (kind == "bool"
                and (raw == true or raw == false or raw == 0 or raw == 1)
                or kind == "int" and Messiah.VisualFinite(raw) and raw % 1 == 0)
            local normalized = "unknown"
            if known then normalized = kind == "bool" and tostring(raw == true or raw == 1) or tostring(raw) end
            if not known then value = nil end
            return {
                known = known,
                value = value,
                label = ("%s/raw=%s/type=%s/error=%s"):format(normalized, text(raw), type(raw), text(err))
            }
        end
        local function alive()
            local dead = read("bool", "IS_ENTITY_DEAD", ped, false)
            if not dead or not dead.known or dead.value ~= false then return false end
            local dying = read("bool", "IS_PED_DEAD_OR_DYING", ped, true)
            return dying ~= nil and dying.known and dying.value == false and current()
        end
        if not (gta and type(gta.HandleToPointer) == "function") then return false end
        local ok, pointer = boundary(gta.HandleToPointer, ped)
        if not ok or pointer == nil then return false end
        local address_ok, address = boundary(function() return pointer:GetAddress() end)
        if not address_ok or not Messiah.VisualFinite(address) or address <= 0 or address % 1 ~= 0
            or ("physical:%s"):format(tostring(address)) ~= key then
            return false
        end
        -- Compare native reads against the documented Cherax-owned wrapper.
        -- This is local transport evidence only: ObjectID 0 by itself proves
        -- neither missing replication nor invisibility on another machine.
        local host_fields = {}
        local function host_field(object, name, kind)
            local read_ok, value = boundary(function() return object[name] end)
            if not current() then return false end
            local known = read_ok and (kind == "bool" and type(value) == "boolean"
                or kind == "int" and Messiah.VisualFinite(value) and value % 1 == 0)
            host_fields[#host_fields + 1] = name .. "=" .. (known and text(value) or "unknown")
            return true
        end
        for _, name in ipairs({ "IsDynamic", "IsFixed", "IsFixedByNetwork" }) do
            if not host_field(pointer, name, "bool") then return false end
        end
        local net_ok, net_object = boundary(function() return pointer.NetObject end)
        if not current() then return false end
        if net_ok and net_object ~= nil then
            for _, name in ipairs({ "ObjectID", "ObjectType", "PlayerId", "PendingPlayerId" }) do
                if not host_field(net_object, name, "int") then return false end
            end
            if not host_field(net_object, "IsRemote", "bool") then return false end
        else
            host_fields[#host_fields + 1] = "NetObject=unavailable"
        end
        local host_transport = table.concat(host_fields, ",")
        pointer, net_object = nil, nil -- Never retain wrappers in state.
        local exists = read("bool", "DOES_ENTITY_EXIST", ped)
        if not exists or not exists.known or exists.value ~= true then return false end
        local kind = read("int", "GET_ENTITY_TYPE", ped)
        if not kind or not kind.known or kind.value ~= 1 or not alive() then return false end
        local function query(return_kind, name, ...)
            if not alive() then return nil end
            return read(return_kind, name, ...)
        end
        local networked = query("bool", "NETWORK_GET_ENTITY_IS_NETWORKED", ped)
        if not networked then return false end
        local net_id = { label = networked.known and "not-networked" or "unknown" }
        if networked.known and networked.value == true then
            net_id = query("int", "NETWORK_GET_NETWORK_ID_FROM_ENTITY", ped)
            if not net_id then return false end
        end
        local controlled = query("bool", "NETWORK_HAS_CONTROL_OF_ENTITY", ped)
        if not controlled then return false end
        local visible = query("bool", "IS_ENTITY_VISIBLE", ped)
        if not visible then return false end
        local alpha = query("int", "GET_ENTITY_ALPHA", ped)
        if not alpha then return false end
        local connected = query("int", "NETWORK_GET_NUM_CONNECTED_PLAYERS")
        if not connected then return false end
        local function vector(name)
            if not alive() then return nil end
            local vector_ok, value
            if name == "GET_ENTITY_COORDS" then
                vector_ok, value = boundary(invoke_vec3, hashes[name], ped, false)
            else
                vector_ok, value = boundary(invoke_vec3, hashes[name], ped)
            end
            if not current() then return nil end
            if not vector_ok or value == nil then return "unknown" end
            local numbers = {}
            for _, axis in ipairs({ "x", "y", "z" }) do
                local axis_ok, number = boundary(function() return value[axis] end)
                if not current() then return nil end
                if not axis_ok or not Messiah.VisualFinite(number) then return "unknown" end
                numbers[#numbers + 1] = number
            end
            return ("%.3f,%.3f,%.3f"):format(numbers[1], numbers[2], numbers[3])
        end
        local position = vector("GET_ENTITY_COORDS")
        if not position then return false end
        local velocity = vector("GET_ENTITY_VELOCITY")
        if not velocity then return false end
        local profile = Messiah.ANIMATIONS[state.anim_variant or "male"]
        local idle = profile and profile.idle_candidates[tonumber(state.idle_candidate_index) or 1]
        local idle_readback = { label = "unavailable" }
        if idle then
            idle_readback = query("bool", "IS_ENTITY_PLAYING_ANIM", ped, idle.dict, idle.name, 3)
            if not idle_readback then return false end
        end
        if not alive() or not current() then return false end
        local cache_current = state.fx_session_frame == frame and state.fx_session_epoch == epoch
        local session = cache_current and ("%s/raw=%s/type=%s/error=%s"):format(
            text(state.fx_session_status), text(state.fx_session_raw), text(state.fx_session_raw_type),
            text(state.fx_session_error)) or "unknown/cache-stale"
        log_info(("Messiah peer self diagnostic: epoch=%s frame=%s session={%s} connected={%s} "
                .. "ped=%s networked={%s} netId={%s} control={%s} visible={%s} alpha={%s} "
                .. "position=(%s) velocity=(%s) idle={%s} host={%s} localEvidenceOnly=true peerCloneDelivery=not-proven.")
            :format(tostring(epoch), tostring(frame), session, connected.label, tostring(ped),
                networked.label, net_id.label, controlled.label, visible.label, alpha.label,
                position, velocity, idle_readback.label, host_transport))
        return current()
    end

    function Messiah.TickMovement(now, ped, menu_open)
        local state = Messiah.State()
        local peer_diagnostic_due = false
        if not state.ped_lease or state.ped_lease.handle ~= Messiah.NormalizeEntityHandle(ped)
            or not Messiah.ValidateEntityLease(state.ped_lease, "movement-frame", "none") then
            return 0
        end
        local last = state.last_tick_ms ~= 0 and state.last_tick_ms or now
        local dt = math.max(0.005, math.min(0.05, (now - last) / 1000.0))
        state.last_tick_ms = now
        local cam_x, cam_y, _, camera_heading = Messiah.CameraDirection()
        local flat_len = math.sqrt(cam_x * cam_x + cam_y * cam_y)
        if flat_len < 0.001 then cam_x, cam_y, flat_len = 0.0, 1.0, 1.0 end
        local forward_x, forward_y = cam_x / flat_len, cam_y / flat_len
        local right_x, right_y = forward_y, -forward_x

        local allow_input = not menu_open and state.phase ~= Messiah.PHASES.ASCENDING
            and state.phase ~= Messiah.PHASES.RESTORING
        local axis_lr = allow_input and Messiah.Axis(30) or 0.0
        local axis_ud = allow_input and Messiah.Axis(31) or 0.0
        if math.abs(axis_lr) < 0.001 and math.abs(axis_ud) < 0.001 and allow_input then
            if Messiah.ControlHeld(32) then axis_ud = axis_ud - 1.0 end
            if Messiah.ControlHeld(33) then axis_ud = axis_ud + 1.0 end
            if Messiah.ControlHeld(34) then axis_lr = axis_lr - 1.0 end
            if Messiah.ControlHeld(35) then axis_lr = axis_lr + 1.0 end
        end
        local forward_amount = -axis_ud
        local strafe_amount = axis_lr
        local move_x = right_x * strafe_amount + forward_x * forward_amount
        local move_y = right_y * strafe_amount + forward_y * forward_amount
        local input_length = math.sqrt(move_x * move_x + move_y * move_y)
        if input_length > 1.0 then
            move_x, move_y, input_length = move_x / input_length, move_y / input_length, 1.0
        end
        state.motion_requested = input_length > 0.01
        local speed_factor = forward_amount < -0.01 and Messiah.REVERSE_SPEED_FACTOR or 1.0
        if math.abs(strafe_amount) > math.abs(forward_amount) then
            speed_factor = speed_factor * Messiah.STRAFE_SPEED_FACTOR
        end
        local glide_speed = Messiah.MOVE_SPEED * speed_factor
        if allow_input and Messiah.ControlHeld(21) then
            glide_speed = glide_speed * Messiah.SPRINT_MULTIPLIER
        end
        local target_vx, target_vy = move_x * glide_speed, move_y * glide_speed
        local acceleration = state.motion_requested and Messiah.MOVE_ACCELERATION
            or Messiah.MOVE_DECELERATION
        Messiah.ApproachVelocity2D(state, target_vx, target_vy, acceleration * dt)

        local vertical_input = 0.0
        if allow_input then
            if Messiah.ControlHeld(22) then vertical_input = vertical_input + 1.0 end
            if Messiah.ControlHeld(36) then vertical_input = vertical_input - 1.0 end
        end
        local target_vz = vertical_input * Messiah.VERTICAL_ADJUST_SPEED
        local vertical_rate = vertical_input == 0.0 and Messiah.VERTICAL_DECELERATION
            or Messiah.VERTICAL_ACCELERATION
        state.move_vz = Messiah.Approach(state.move_vz, target_vz, vertical_rate * dt)
        if state.phase ~= Messiah.PHASES.ASCENDING then
            state.anchor_z = state.anchor_z + state.move_vz * dt
        end

        local hover = clamp(slider_float("messiah_hover_height", 2.2), 0.5, 8.0)
        state.last_hover_height = hover
        state.target_z = state.anchor_z + hover
        local coords = Messiah.LeaseInvoke(state.ped_lease, "vec3", "GET_ENTITY_COORDS", H.GET_ENTITY_COORDS, ped, false)
        local px, py, pz = vector_components(coords)
        px, py, pz = tonumber(px), tonumber(py), tonumber(pz)
        if px and py and pz then
            state.visual_owner_position = {
                x = px,
                y = py,
                z = pz,
                epoch = state.activation_epoch,
                frame = state
                    .entity_frame
            }
            if state.phase ~= Messiah.PHASES.ASCENDING and math.abs(state.target_z - pz) > 30.0 then
                state.anchor_z = pz - hover
                state.target_z = pz
                Messiah.LogOnce("hover-discontinuity",
                    ("Messiah hover rebased after external discontinuity: activation=%d ped=%s z=%.2f.")
                    :format(state.activation_id, tostring(ped), pz))
            end

            local height_above_ground = Messiah.LeaseInvoke(state.ped_lease, "float",
                "GET_ENTITY_HEIGHT_ABOVE_GROUND", 0x1DD55701034110E5, ped)
            if state.phase ~= Messiah.PHASES.ASCENDING then
                -- Sensor is valid near land/terrain; moving out over open water
                -- cannot endlessly integrate negative target altitude.
                local valid = type(height_above_ground)=="number"
                    and height_above_ground==height_above_ground
                    and height_above_ground>0.02 and height_above_ground<200.0
                if valid then
                    state.last_floor_z=pz-height_above_ground
                    state.last_floor_ms=now
                end
                local recent=state.last_floor_z and state.last_floor_ms
                    and now >= state.last_floor_ms and now-state.last_floor_ms<750
                local floor=valid and (pz-height_above_ground)
                    or recent and state.last_floor_z or nil
                if floor then
                    local minimum_target=floor+Messiah.HOVER_FLOOR_CLEARANCE
                    if state.target_z<minimum_target then
                        state.target_z=minimum_target
                        state.anchor_z=minimum_target-hover
                        if state.move_vz<0.0 then state.move_vz=0.0 end
                    end
                elseif vertical_input < 0 then
                    -- Missing terrain is not a license to force downward speed.
                    state.target_z=math.max(state.target_z,pz)
                    state.anchor_z=state.target_z-hover
                    state.move_vz=0.0
                end
            end
            local desired_z, feed_forward = state.target_z, 0.0
            if state.phase == Messiah.PHASES.ASCENDING then
                local progress = clamp((now - state.phase_started_ms) / Messiah.ASCENT_DURATION_MS, 0.0, 1.0)
                local distance = state.target_z - state.ascent_start_z
                desired_z = state.ascent_start_z + distance * (1.0 - (1.0 - progress) ^ 3)
                feed_forward = distance * 3.0 * (1.0 - progress) ^ 2 / (Messiah.ASCENT_DURATION_MS / 1000.0)
                if progress >= 1.0 then Messiah.SetPhase(Messiah.PHASES.IDLE_HOVER, now, "ascent complete") end
            else
                local phase = (now % Messiah.HOVER_BOB_PERIOD_MS) / Messiah.HOVER_BOB_PERIOD_MS * math.pi * 2.0
                desired_z = state.target_z + math.sin(phase) * Messiah.HOVER_BOB_AMPLITUDE
                feed_forward = state.move_vz + math.cos(phase) * Messiah.HOVER_BOB_AMPLITUDE
                    * (math.pi * 2.0 / (Messiah.HOVER_BOB_PERIOD_MS / 1000.0))
            end
            local measured=Messiah.LeaseInvoke(state.ped_lease,"vec3",
                "GET_ENTITY_VELOCITY",H.GET_ENTITY_VELOCITY,ped)
            local _,_,actual_vz=vector_components(measured)
            local drag=type(actual_vz)=="number" and actual_vz==actual_vz
                and math.abs(actual_vz)<100.0 and actual_vz*0.24 or 0.0
            local controller_vz=clamp((desired_z-pz)*Messiah.HOVER_RESPONSE
                +feed_forward-drag,-Messiah.MAX_VERTICAL_STEP_SPEED,
                Messiah.MAX_VERTICAL_STEP_SPEED)
            -- This updates local physical velocity. Local readback does not
            -- establish whether another client received the ped's movement.
            -- Small gravity compensation avoids accumulating a hover sag while
            -- leaving the ped's gravity/collision flags owned by the game.
            local velocity_z = controller_vz + 9.81 * dt * 0.5
            local motion_accepted = Messiah.LeaseInvoke(state.ped_lease, "void", "SET_ENTITY_VELOCITY",
                H.SET_ENTITY_VELOCITY,
                ped, state.move_vx, state.move_vy, velocity_z)
            Messiah.RecordMotionWrite(motion_accepted, state.ped_lease, now,
                state.move_vx, state.move_vy, velocity_z)
            if state.peer_diagnostic_epoch ~= state.activation_epoch
                or now >= (state.next_motion_network_log_ms or 0) then
                state.next_motion_network_log_ms = now + 5000
                local observed = Messiah.LeaseInvoke(state.ped_lease, "vec3", "GET_ENTITY_VELOCITY",
                    H.GET_ENTITY_VELOCITY, ped)
                local vx, vy, vz = vector_components(observed)
                log_info(("Messiah movement: backend=physical-velocity requested=(%.2f,%.2f,%.2f) "
                        .. "readback=(%s,%s,%s) observerAcceptance=unverified.")
                    :format(state.move_vx, state.move_vy, velocity_z, tostring(vx), tostring(vy), tostring(vz)))
                peer_diagnostic_due = true
            end
        end

        local base_phase = Messiah.BaseMotionPhase(state)
        if state.phase == Messiah.PHASES.IDLE_HOVER or state.phase == Messiah.PHASES.GLIDING then
            Messiah.SetPhase(base_phase, now, state.motion_requested and "movement input" or "decelerated")
        end
        local horizontal_speed = math.sqrt(state.move_vx * state.move_vx + state.move_vy * state.move_vy)
        local action_facing = state.action ~= nil
            and (string.find(state.phase, "_WINDUP", 1, true) ~= nil
                or string.find(state.phase, "_RELEASE", 1, true) ~= nil
                or state.phase == Messiah.PHASES.LANCE_CHANNEL)
        if horizontal_speed > 0.15 or action_facing then
            local current = state.heading
            if current == nil and type(deps.invoke_float) == "function" then
                local heading_value = Messiah.LeaseInvoke(state.ped_lease, "float", "GET_ENTITY_HEADING",
                    H.GET_ENTITY_HEADING, ped)
                current = tonumber(heading_value)
            end
            current = tonumber(current) or camera_heading
            local delta = ((camera_heading - current + 540.0) % 360.0) - 180.0
            current = (current + delta * math.min(1.0, dt * Messiah.HEADING_RESPONSE)) % 360.0
            state.heading = current
            Messiah.LeaseInvoke(state.ped_lease, "void", "SET_ENTITY_HEADING", H.SET_ENTITY_HEADING, ped, current)
        end
        -- Observe last so a reentrant cancellation cannot leave this movement
        -- stack with another native write after the diagnostic returns.
        if peer_diagnostic_due then Messiah.PeerSelfDiagnostic(now, ped) end
        return dt
    end

    function Messiah.UpdateHudSnapshot(now, menu_open)
        local state = Messiah.State()
        if not state.active then
            state.hud_snapshot = nil
            return nil
        end
        local epoch, frame = state.activation_epoch, state.entity_frame
        local action, phase, channel_beam = state.action, state.phase, state.channel_beam
        local function hud_context_current()
            return Messiah.ActivationContextCurrent(state, epoch) and state.entity_frame == frame
                and state.action == action and state.phase == phase and state.channel_beam == channel_beam
        end
        if not hud_context_current() then return nil end
        local abilities = {}
        for _, ability in ipairs({ "ORB", "LANCE", "RUPTURE", "SHOCKWAVE", "SUPER" }) do
            local config = Messiah.ABILITIES[ability]
            local binding = Messiah.INPUT_BINDINGS[ability]
            local status = "READY"
            if state.action and state.action.ability == ability then
                status = string.match(state.phase, "_([A-Z]+)$") or "ACTIVE"
                if status == "CHANNEL" then
                    status = state.action.minimum_pulse == true and "PULSE" or "CHANNELING"
                end
            elseif state.pending_ability == ability then
                status = state.queued_cast and "QUEUED" or "PENDING"
            elseif state.action or state.pending_ability then
                status = "BUSY"
            elseif (ability == "RUPTURE" or ability == "SUPER")
                and now < state.no_ground_until_ms then
                status = "NO GROUND TARGET"
            end
            abilities[ability] = {
                key = binding.label,
                label = config.title,
                status = status,
                ready = status == "READY",
            }
        end
        local aim = type(state.aim_snapshot) == "table" and state.aim_snapshot or {}
        local reticle_mode = tostring(state.reticle_mode or "DIRECT_MISS")
        if state.phase == Messiah.PHASES.LANCE_CHANNEL then
            reticle_mode = "CHANNEL"
        elseif now >= (tonumber(state.reticle_mode_until_ms) or 0) then
            reticle_mode = aim.direct_hit == true and "DIRECT_HIT" or "DIRECT_MISS"
        end
        local locked_screen_x, locked_screen_y, locked_ground = nil, nil, false
        local projected_contact = false
        local locked_point
        if action and (action.ability == "RUPTURE" or action.ability == "SUPER")
            and type(action.target) == "table" then
            locked_ground = true
            locked_point = Messiah.VisualPoint({ x = action.target.x, y = action.target.y, z = action.target.z + 0.08 })
        elseif action and action.ability == "LANCE" and state.phase == Messiah.PHASES.LANCE_CHANNEL then
            projected_contact = true
            local beam = channel_beam
            if beam and beam.owner_epoch == state.activation_epoch and beam.action_serial == action.serial then
                locked_point = Messiah.VisualPoint(beam.target)
            end
        end
        -- Only immutable world contact is published here. The render adapter
        -- projects it using the same current camera contract as the beam.
        if not hud_context_current() then return nil end
        state.hud_snapshot = {
            active = true,
            epoch = state.activation_epoch,
            action_serial = state.action_serial,
            title = "MESSIAH",
            now_ms = now,
            menu_open = menu_open == true,
            no_ground_target = now < state.no_ground_until_ms,
            no_ground_until_ms = state.no_ground_until_ms,
            no_ground_ability = state.no_ground_ability,
            phase = state.phase,
            abilities = abilities,
            movement = { key = "SPACE / CTRL", label = "ASCEND / DESCEND" },
            reticle = {
                visible = true,
                mode = reticle_mode,
                direct_hit = aim.direct_hit == true,
                ground_valid = reticle_mode == "GROUND_VALID",
                ground_invalid = reticle_mode == "GROUND_INVALID",
                channeling = reticle_mode == "CHANNEL",
                pulse = now < (tonumber(state.reticle_pulse_until_ms) or 0),
                source = tostring(aim.source or "none"),
                locked_ground = locked_ground,
                projected_contact = projected_contact,
                screen_x = locked_screen_x,
                screen_y = locked_screen_y,
                world_x = locked_point and locked_point.x,
                world_y = locked_point and locked_point.y,
                world_z = locked_point and locked_point.z,
            },
        }
        return state.hud_snapshot
    end

    function Messiah.HudSnapshot()
        -- This getter runs from UI/Renderer::Present. It must only copy the
        -- immutable snapshot published by the gameplay tick: no State()
        -- normalization, entity native, lifecycle transition, or cleanup is
        -- allowed on the renderer thread.
        local state = type(State.messiah) == "table" and State.messiah or nil
        local snapshot = state and state.hud_snapshot or nil
        if not state or state.active ~= true or state.restoring or state.disposed
            or type(snapshot) ~= "table" or snapshot.active ~= true
            or snapshot.epoch ~= state.activation_epoch then
            return nil
        end
        local movement = type(snapshot.movement) == "table" and snapshot.movement
            or { key = "SPACE / CTRL", label = "ASCEND / DESCEND" }
        local copy = {
            active = true,
            epoch = snapshot.epoch,
            action_serial = snapshot.action_serial,
            title = snapshot.title,
            now_ms = snapshot.now_ms,
            menu_open = snapshot.menu_open == true,
            no_ground_target = snapshot.no_ground_target == true,
            no_ground_until_ms = snapshot.no_ground_until_ms,
            no_ground_ability = snapshot.no_ground_ability,
            phase = snapshot.phase,
            movement = { key = movement.key, label = movement.label },
            abilities = {},
            reticle = {},
        }
        for ability, row in pairs(snapshot.abilities or {}) do
            copy.abilities[ability] = {
                key = row.key,
                label = row.label,
                status = row.status,
                ready = row.ready == true,
            }
        end
        local reticle = type(snapshot.reticle) == "table" and snapshot.reticle or {}
        copy.reticle = {
            visible = reticle.visible == true,
            mode = tostring(reticle.mode or "DIRECT_MISS"),
            direct_hit = reticle.direct_hit == true,
            ground_valid = reticle.ground_valid == true,
            ground_invalid = reticle.ground_invalid == true,
            channeling = reticle.channeling == true,
            pulse = reticle.pulse == true,
            source = tostring(reticle.source or "none"),
            locked_ground = reticle.locked_ground == true,
            projected_contact = reticle.projected_contact == true,
            screen_x = tonumber(reticle.screen_x),
            screen_y = tonumber(reticle.screen_y),
            world_x = reticle.world_x,
            world_y = reticle.world_y,
            world_z = reticle.world_z,
        }
        return copy
    end

    function Messiah.Tick(now, ped)
        local state = Messiah.State()
        if state.gameplay_owner ~= true or state.disposed or state.restoring or state.ending then return end
        if not is_on("messiah_state") then
            Messiah.Restore("feature disabled", true)
            state.respawn_blocked_ped = 0
            return
        end
        local ready, ready_reason, ready_lease = Messiah.PedReady(ped)
        if not ready then
            local blocked_ped = state.active and state.ped or tonumber(ped) or 0
            if blocked_ped ~= 0 then state.respawn_blocked_ped = blocked_ped end
            state.hud_snapshot = nil
            Messiah.Restore("local ped " .. tostring(ready_reason), true)
            return
        end
        if state.respawn_blocked_ped ~= 0 then
            -- Enhanced can recycle the same numeric handle for the newly alive
            -- local ped. PedReady is the generation boundary: dead frames return
            -- above; the first valid/alive frame rebuilds ownership exactly once.
            log_info(("Messiah respawn accepted: oldPed=%s newPed=%s "
                    .. "handleReused=%s newEntityValid=true aliveTransition=true.")
                :format(tostring(state.respawn_blocked_ped), tostring(ped),
                    tostring(tonumber(ped) == state.respawn_blocked_ped)))
            state.respawn_blocked_ped = 0
        end
        local seat_query_ok, seated = Messiah.WithPedBootstrap(ped, function()
            local value, raw, err = Messiah.LeaseInvoke(ready_lease, "bool",
                "IS_PED_IN_ANY_VEHICLE", H.IS_PED_IN_ANY_VEHICLE, ped, false)
            if err or (type(raw) ~= "boolean" and type(raw) ~= "number") then return nil end
            return value == true
        end)
        if seat_query_ok ~= true or seated == nil then
            Messiah.Restore("local ped vehicle state unavailable", true)
            return
        end
        if seated then
            Messiah.Restore("local ped entered a vehicle", true)
            return
        end
        if not state.active or state.ped ~= ped then
            if not Messiah.Activate(now, ped,
                    state.active and "frame-tick:ped-change" or "frame-tick:toggle-on") then
                return
            end
        end

        for _, control in ipairs(Messiah.CONTROL_IDS) do
            invoke_void(H.DISABLE_CONTROL_ACTION, 0, control, true)
        end
        local menu_open = Messiah.MenuOpen()
        Messiah.TickModelStreaming(now)
        Messiah.SharedBeamModelReady(now)
        Messiah.TickMovement(now, ped, menu_open)
        Messiah.UpdateAimSnapshot(now, menu_open)
        Messiah.ProcessAbilityInputs(now, menu_open)
        Messiah.BeginRequestedAction(now, menu_open)
        Messiah.TickActionState(now, ped)
        if state.lance_sweep_pending and (not state.action or state.action.ending
                or state.phase ~= Messiah.PHASES.LANCE_CHANNEL) then
            Messiah.LanceContactPoint(now, nil, nil, nil)
        end
        Messiah.TickScheduledImpacts(now)
        Messiah.StartAura(ped, now)
        Messiah.UpdateAura(now)
        Messiah.UpdateTempFx(now)
        Messiah.UpdateSounds(now)
        Messiah.UpdateAnimation(ped, now)
        if state.ragdoll_owned then invoke_void(H.SET_PED_CAN_RAGDOLL, ped, false) end
        Messiah.UpdateProjectiles(now, ped)
        Messiah.TickVisuals(now)
        Messiah.UpdateHudSnapshot(now, menu_open)
        Messiah.ReleaseAimEntity("frame-consumed")
    end

    local OWNED_TOGGLES = {
        "fast_respawn", "bst_mode", "godmode", "unlimited_sprint", "no_ragdoll", "disable_stumble", "no_wanted",
        "auto_armour", "messiah_state",
        "auto_clean", "auto_dry", "player_keep_headgear", "peds_ignore", "no_critical_hits", "disable_action_mode",
        "movement_refinement",
        "super_jump", "run_boost", "swim_boost",
        "better_escape", "wheel_snacks", "wheel_armour", "auto_snack_inventory", "auto_armour_inventory",
    }

    local function reset_owned_toggles()
        for _, key in ipairs(OWNED_TOGGLES) do set_toggle(key, false) end
    end

    local suppression_generation = 0
    -- Config flags are persistent and shared by the two independently enabled
    -- controls. Reset flags are frame-only and need no destructive "off" write.
    function Live.ragdoll_baseline_for_messiah(ped, current)
        local o = Live.ragdoll_suppression
        if o and o.ped == ped and o.can_before ~= nil and Live.same_local_owner(o) then return o.can_before end
        return current
    end

    function Live.ragdoll_baseline(o, current)
        local m = Messiah.State()
        if m.ragdoll_owned and m.ped == o.ped and type(m.ragdoll_before) == "boolean"
            and m.ped_lease and Messiah.ValidateEntityLease(m.ped_lease, "ragdoll-baseline", "none")
            and Live.same_local_owner(o) then
            return m.ragdoll_before
        end
        return current
    end

    function Live.free_ragdoll_buffer()
        if Live.ragdoll_proofs_ptr and memory and type(memory.Free) == "function" then
            if pcall(memory.Free, Live.ragdoll_proofs_ptr) then Live.ragdoll_proofs_ptr = nil end
        end
    end

    function Live.read_ragdoll_proofs(o, allow_stopped)
        if not Live.same_local_owner(o, allow_stopped) or not memory or type(memory.Alloc) ~= "function"
            or type(memory.Free) ~= "function" or type(memory.WriteInt) ~= "function" or type(memory.ReadInt) ~= "function" then
            return nil
        end
        if not Live.ragdoll_proofs_ptr then
            local ok, ptr = pcall(memory.Alloc, 64)
            if not ok or type(ptr) ~= "number" or ptr <= 0 then return nil end
            Live.ragdoll_proofs_ptr = ptr
        end
        local ptr = Live.ragdoll_proofs_ptr
        local ok, result = pcall(function()
            for i = 0, 7 do memory.WriteInt(ptr + i * 8, -1) end
            if not Live.same_local_owner(o, allow_stopped) or Live.protection_bool(0xBE8CD9BE829BBEBF, o.ped,
                    ptr, ptr + 8, ptr + 16, ptr + 24, ptr + 32, ptr + 40, ptr + 48, ptr + 56) ~= true
                or not Live.same_local_owner(o, allow_stopped) then
                return nil
            end
            local flags = {}
            for i = 1, 8 do
                -- Native BOOL out parameters can be byte-sized or 32-bit in
                -- host bridges. Inspect the low byte; untouched -1 stays 255.
                local value = memory.ReadInt(ptr + (i - 1) * 8) % 256
                if value ~= 0 and value ~= 1 then return nil end
                flags[i] = value == 1
            end
            return flags
        end)
        if ok and Live.same_local_owner(o, allow_stopped) then return result end
    end

    function Live.write_collision_proof(o, flags, value, allow_stopped)
        if not Live.same_local_owner(o, allow_stopped) then return false end
        -- Preserve all seven other live proof bits; collision is output slot 4.
        if not invoke_void(H.SET_ENTITY_PROOFS, o.ped, flags[1], flags[2], flags[3], value,
                flags[5], flags[6], flags[7], flags[8]) then
            return false
        end
        local after = Live.read_ragdoll_proofs(o, allow_stopped)
        return after ~= nil and after[4] == value
    end

    function Live.restore_collision_proof(o, allow_stopped)
        if o.collision_before == nil then return true end
        local flags = Live.read_ragdoll_proofs(o, allow_stopped)
        if not flags then return false end
        if flags[4] == o.collision_before or flags[4] ~= o.collision_last
            or Live.write_collision_proof(o, flags, o.collision_before, allow_stopped) then
            o.collision_before = nil; return true
        end
        return false
    end

    function Live.restore_ragdoll_flag(o, flag, snapshot, allow_stopped)
        local current = Live.protection_bool(H.GET_PED_CONFIG_FLAG, o.ped, flag, true)
        if current == nil or not Live.same_local_owner(o, allow_stopped) then return false end
        if current == snapshot.before or current ~= snapshot.last then return true end
        return invoke_void(H.SET_PED_CONFIG_FLAG, o.ped, flag, snapshot.before)
            and Live.same_local_owner(o, allow_stopped)
            and Live.protection_bool(H.GET_PED_CONFIG_FLAG, o.ped, flag, true) == snapshot.before
            and Live.same_local_owner(o, allow_stopped)
    end

    function Live.restore_ragdoll_permission(o, allow_stopped)
        if o.can_before == nil then return true end
        if not allow_stopped and is_on("messiah_state") then return false end
        if not Live.same_local_owner(o, allow_stopped) then return false end
        local current = Live.protection_bool(0x128F79EDCECE4FD5, o.ped)
        if current == nil or not Live.same_local_owner(o, allow_stopped) then return false end
        if current ~= o.can_last or current == o.can_before then
            o.can_before = nil; return true
        end
        if invoke_void(H.SET_PED_CAN_RAGDOLL, o.ped, o.can_before)
            and Live.same_local_owner(o, allow_stopped)
            and Live.protection_bool(0x128F79EDCECE4FD5, o.ped) == o.can_before
            and Live.same_local_owner(o, allow_stopped) then
            o.can_before = nil; return true
        end
        return false
    end

    function Live.release_high_fall(o, allow_stopped)
        if not o.high_fall_owned then return true end
        if not Live.same_local_owner(o, allow_stopped) then return false end
        if not invoke_void(0x711794453CFD692B, o.ped, false) then return false end
        o.high_fall_owned = nil
        return true
    end

    function Live.recover_fall_task(o)
        local ped = o.ped
        local function current() return is_on("no_ragdoll") and Live.same_local_owner(o) end
        if not current() or Live.protection_bool(0x01FEE67DB37F59B2, ped) ~= true
            or Live.protection_bool(0x9DE327631295B4C2, ped) ~= false
            or Live.protection_bool(0x53E8CB4F48BFE623, ped) ~= false or not current() then
            return
        end
        local falling=Live.protection_bool(0xFB92A102F1C4DFA3,ped)
        local airborne=Live.protection_bool(0x886E37EC497200B6,ped)
        local ragdoll=Live.protection_bool(0x47E4E977581C5B55,ped)
        -- Never clear ordinary gravity/falling/parachute tasks. Only recover
        -- an actual grounded ragdoll after the prevention failed.
        if ragdoll~=true or falling==true or airborne==true or not current()then return end
        local now = now_ms()
        if o.fall_recover_at and now < o.fall_recover_at and o.fall_recover_at - now <= 250 then return end
        o.fall_recover_at = now + 250
        -- Reset only an observed fall/ragdoll task. Never clear normal aiming,
        -- locomotion, swimming, climbing or vehicle tasks every frame.
        if invoke_void(0xAAA34F8A7CB32098, ped) and current() then
            Live.protection_bool(0xF28965D04F570DCA, ped, 0x9072A713, false, 0, false)
        end
    end

    -- Disable Stumble never clears slope/wall-hit locomotion tasks.
    -- Those tasks are shared with GTA's walking recovery and forcing
    -- CLEAR_PED_TASKS_IMMEDIATELY can strand the player upright on steep ground.

    -- Slope movement host begin
    Live.slope_buffers = {}
    Live.slope_buffer_epoch = 0
    Live.slope_guards = {
        { 0x997ABD671D25CA0B, 2, false },                                                -- vehicle
        { 0x3317DEDB88C95038, 2, true },                                                 -- dead/dying
        { 0xCEDABC5900A0BF97, 1 },                                                       -- jumping
        { 0x47E4E977581C5B55, 1 }, { 0x2A74E1D5F2F00EEC, 1 },                            -- ragdoll/getting up
        { 0x53E8CB4F48BFE623, 1 }, { 0x117C70D1F5730B5E, 1 },                            -- climbing/vaulting
        { 0x5527B8246FEF9B11, 1 }, { 0x7DCE8BDA0F1C1200, 1 },                            -- diving/parachuting
        { 0x9DE327631295B4C2, 1 }, { 0xC024869A53992F34, 1 },                            -- swimming
        { 0x4E209B2C1EAD5159, 1 }, { 0xBB062B2B5722478E, 1 },                            -- melee/entering vehicle
        { 0x57AB4A3080F85143, 1 },                                                       -- scenario
        { 0xB0034A223497FFCB, 0 }, { 0x991251AFC3981F84, 0 },                            -- pause/cutscene
        { 0xD9D2CFFF49FAB35F, 0 },                                                       -- player switch
        { 0xB16FCE9DDC7BA182, 0 }, { 0x797AC7CB535BA28F, 0 }, { 0x5C544BC6C57AC575, 0 }, -- camera fades
    }
    function Live.slope_number(v) return type(v) == "number" and v == v and math.abs(v) < math.huge end

    function Live.slope_current(o)
        return is_on("disable_stumble") and not is_on("messiah_state")
            and not Live.protection.stop_requested and Live.same_local_owner(o)
    end

    function Live.slope_vector(value)
        local x, y, z = vector_components(value)
        if Live.slope_number(x) and Live.slope_number(y) and Live.slope_number(z) then return { x = x, y = y, z = z } end
    end

    function Live.slope_float(hash, ...)
        local value, raw, err = invoke_float_detail(hash, ...)
        if err == nil and Live.slope_number(raw) and Live.slope_number(value) then return value end
    end

    function Live.slope_read(o)
        if not Live.slope_current(o)
            or Live.protection_bool(0x5E9564D8246B909A, o.pid) ~= true
            or Live.protection_bool(0x49C32D60007AFA47, o.pid) ~= true
            or Live.protection_bool(0x01FEE67DB37F59B2, o.ped) ~= true
            or Live.protection_bool(0x39B5D1B10383F0C8) ~= true then
            return nil
        end
        for _, spec in ipairs(Live.slope_guards) do
            local value
            if spec[2] == 0 then
                value = Live.protection_bool(spec[1])
            elseif spec[2] == 1 then
                value = Live.protection_bool(spec[1], o.ped)
            else
                value = Live.protection_bool(spec[1], o.ped, spec[3])
            end
            if value ~= false then return nil end
        end
        for _, control in ipairs({ 30, 31, 22, 21 }) do
            if Live.protection_bool(0x1CEA6BFDF248E5D9, 0, control) ~= true then return nil end
        end
        -- Read controls only; never inject or disable a user's input. Checking
        -- jump before the next game task starts gives manual jumps priority.
        if Live.protection_bool(0xF3A21BCD95725A4A, 0, 22) ~= false then return nil end
        local sprint = Live.protection_bool(0xF3A21BCD95725A4A, 0, 21)
        local falling = Live.protection_bool(0xFB92A102F1C4DFA3, o.ped)
        local ix, iy = Live.slope_float(0xEC3C9B8D5327B563, 0, 30), Live.slope_float(0xEC3C9B8D5327B563, 0, 31)
        if sprint == nil or falling == nil or not ix or not iy or math.abs(ix) > 1 or math.abs(iy) > 1 then return nil end
        local strength = math.sqrt(ix * ix + iy * iy)
        if strength <= 0.01 then return nil end
        local position = Live.slope_vector(invoke_vec3(H.GET_ENTITY_COORDS, o.ped, false))
        local camera = Live.slope_vector(invoke_vec3(H.GET_GAMEPLAY_CAM_ROT, 2))
        local velocity = Live.slope_vector(invoke_vec3(H.GET_ENTITY_VELOCITY, o.ped))
        if not position or not camera or not velocity or velocity.x ^ 2 + velocity.y ^ 2 + velocity.z ^ 2 > 400
            or not Live.slope_current(o) then
            return nil
        end
        local yaw = math.rad(camera.z)
        position.dx = (math.cos(yaw) * ix + math.sin(yaw) * iy) / strength
        position.dy = (math.sin(yaw) * ix - math.cos(yaw) * iy) / strength
        position.speed = (sprint and 7.0 or 4.5) * math.min(strength, 1)
        position.falling = falling
        return position
    end

    function Live.slope_release()
        Live.slope_buffer_epoch = Live.slope_buffer_epoch + 1
        local b = Live.slope_buffers
        if not memory or type(memory.Free) ~= "function" then return next(b) == nil end
        for key, ptr in pairs(b) do if pcall(memory.Free, ptr) then b[key] = nil end end
        return next(b) == nil
    end

    function Live.slope_ensure_buffers()
        local b = Live.slope_buffers
        if b.hit and b.point and b.normal and b.entity then return true end
        if not (memory and type(memory.Alloc) == "function" and type(memory.Free) == "function"
                and type(memory.WriteInt) == "function" and type(memory.ReadInt) == "function"
                and type(memory.WriteFloat) == "function" and type(memory.ReadFloat) == "function") then
            return false
        end
        if not Live.slope_release() then return false end
        local ok = pcall(function()
            for _, spec in ipairs({ { "hit", 8 }, { "point", 24 }, { "normal", 24 }, { "entity", 8 } }) do
                local ptr = memory.Alloc(spec[2])
                if not Live.slope_number(ptr) or ptr <= 0 or ptr % 1 ~= 0 then error("slope buffer unavailable") end
                b[spec[1]] = ptr
            end
        end)
        if not ok then Live.slope_release() end
        return ok
    end

    function Live.slope_start(o, read)
        if not H.START_SHAPE_TEST_LOS_PROBE or not H.GET_SHAPE_TEST_RESULT
            or not Live.slope_current(o) or not Live.slope_ensure_buffers() or not Live.slope_current(o) then
            return nil
        end
        -- Short ankle-height ray catches steep ground and near-vertical faces.
        -- World + object collision only (17); ignore peds, vehicles and water.
        -- Option 7 ignores glass, see-through and no-collision surfaces.
        local handle, raw, err = invoke_int_detail(H.START_SHAPE_TEST_LOS_PROBE,
            read.x, read.y, read.z - 0.35, read.x + read.dx * 1.1, read.y + read.dy * 1.1, read.z - 1.1, 17, o.ped, 7)
        if err == nil and Live.slope_number(raw) and Live.slope_number(handle) and handle == raw
            and handle > 0 and handle % 1 == 0 and Live.slope_current(o) then
            return handle
        end
    end

    function Live.slope_poll(handle, o)
        local b = Live.slope_buffers
        local epoch = Live.slope_buffer_epoch
        if not Live.slope_current(o) or not b.hit or not b.point or not b.normal or not b.entity then return 0 end
        memory.WriteInt(b.hit, -1); memory.WriteInt(b.entity, 0)
        for _, ptr in ipairs({ b.point, b.normal }) do
            for _, offset in ipairs({ 0, 8, 16 }) do memory.WriteFloat(ptr + offset, 0) end
        end
        if not Live.slope_current(o) then return 0 end
        local status, raw, err = invoke_int_detail(H.GET_SHAPE_TEST_RESULT, handle, b.hit, b.point, b.normal, b.entity)
        if err ~= nil or status ~= raw or epoch ~= Live.slope_buffer_epoch or not Live.slope_current(o) then return 0 end
        if status ~= 2 then return status end
        if memory.ReadInt(b.hit) ~= 1 then return 2 end
        -- Native output vectors use 24-byte scrVector slots, not packed V3s.
        local point = {
            x = memory.ReadFloat(b.point),
            y = memory.ReadFloat(b.point + 8),
            z = memory.ReadFloat(b.point +
                16)
        }
        local normal = {
            x = memory.ReadFloat(b.normal),
            y = memory.ReadFloat(b.normal + 8),
            z = memory.ReadFloat(b
                .normal + 16)
        }
        if not Live.slope_current(o) then return 0 end
        return 2, point, normal
    end

    function Live.slope_write(o, velocity, observed, current)
        local fresh = Live.slope_read(o)
        if not fresh or (fresh.x - observed.x) ^ 2 + (fresh.y - observed.y) ^ 2 + (fresh.z - observed.z) ^ 2 > 0.1225
            or fresh.dx * observed.dx + fresh.dy * observed.dy < 0.99 or math.abs(fresh.speed - observed.speed) > 0.01
            or type(current) ~= "function" or not current() or not Live.slope_current(o) then
            return false
        end
        local ok, _, err = invoke_void_detail(H.SET_ENTITY_VELOCITY, o.ped, velocity.x, velocity.y, velocity.z)
        return ok == true and err == nil and Live.slope_current(o)
    end

    Live.slope_movement = Module.NewSlopeMovement({
        Now = now_ms,
        Current = Live.slope_current,
        Read = Live.slope_read,
        Start = Live.slope_start,
        Poll = Live.slope_poll,
        Write = Live.slope_write,
        Release = Live.slope_release
    })
    -- Slope movement host end
    function Live.restore_ragdoll_suppression(allow_stopped)
        local slope_clean = (not Live.slope_movement.HasWork() and next(Live.slope_buffers) == nil)
            or Live.slope_movement.Stop()
        local o = Live.ragdoll_suppression
        if not o then
            Live.free_ragdoll_buffer(); return slope_clean
        end
        if not Live.same_local_owner(o, allow_stopped) then
            local fresh = Live.local_owner(allow_stopped)
            if fresh or lifecycle_token ~= o.token then
                Live.ragdoll_suppression = nil; Live.free_ragdoll_buffer(); return slope_clean
            end
            return false
        end
        for flag, snapshot in pairs(o.flags) do
            if Live.restore_ragdoll_flag(o, flag, snapshot, allow_stopped) then o.flags[flag] = nil end
        end
        Live.restore_ragdoll_permission(o, allow_stopped)
        Live.restore_collision_proof(o, allow_stopped)
        Live.release_high_fall(o, allow_stopped)
        if next(o.flags) == nil and o.can_before == nil and o.collision_before == nil and not o.high_fall_owned then
            Live.ragdoll_suppression = nil; Live.free_ragdoll_buffer()
        end
        return Live.ragdoll_suppression == nil and slope_clean
    end

    -- Local slope observer begin
    -- Debug only: record the local movement path before any correction guard.
    -- Raw.ApartmentLogger is the original host logger; Raw.Logger is muted.
    Live.slope_observer={active=false,latched=false,samples=0,period=100,limit=450}
    Live.slope_observer_tasks={5,6,16,17,18,19,39,45,46,50,51,125,133,134,135,
        264,268,270,280,281,282,283,396,397,406,408,418,422,423}
    Live.slope_observer_bools={
        {'control',0x49C32D60007AFA47,'pid'}, {'onfoot',0x01FEE67DB37F59B2},
        {'ragdoll',0x47E4E977581C5B55}, {'getup',0x2A74E1D5F2F00EEC},
        {'fall',0xFB92A102F1C4DFA3}, {'air',0x886E37EC497200B6},
        {'jump',0xCEDABC5900A0BF97}, {'climb',0x53E8CB4F48BFE623},
        {'vault',0x117C70D1F5730B5E}, {'swim',0x9DE327631295B4C2},
        {'parachute',0x7DCE8BDA0F1C1200}, {'dive',0x5527B8246FEF9B11},
        {'cutscene',0x991251AFC3981F84,'none'}, {'pause',0xB0034A223497FFCB,'none'},
    }
    function Live.slope_observer_emit(text)
        local raw=module_context and module_context.Raw
        local sink=raw and raw.ApartmentLogger
        if not sink or type(sink.LogInfo)~='function' then return false end
        local ok=pcall(sink.LogInfo,'[CScript SlopeProbe v3] '..tostring(text):sub(1,1900))
        return ok
    end
    function Live.slope_observer_stop(reason)
        local s=Live.slope_observer
        if s.active then
            s.active=false
            Live.slope_observer_emit('STOP reason='..tostring(reason)..' samples='..tostring(s.samples)
                ..' rearm=Disable_Stumble_OFF_then_ON')
        end
    end
    function Live.slope_observer_bool(hash,...)
        local ok,value=pcall(Live.protection_bool,hash,...)
        if ok and type(value)=='boolean'then return tostring(value)end
        return 'unknown'
    end
    function Live.slope_observer_float(hash,...)
        local ok,value,raw,err=pcall(invoke_float_detail,hash,...)
        if ok and err==nil and type(value)=='number' and type(raw)=='number'
            and value==value and raw==raw and math.abs(value)<math.huge and math.abs(raw)<math.huge then
            return string.format('%.3f',value)
        end
        return 'unknown'
    end
    function Live.slope_observer_tick(ped,now)
        local s=Live.slope_observer
        if not is_on('disable_stumble')then
            Live.slope_observer_stop('toggle_off');s.latched=false;return
        end
        if type(now)~='number' or now~=now or math.abs(now)==math.huge then
            Live.slope_observer_stop('clock_unavailable');return
        end
        if not s.latched then
            s.latched=true;s.active=true;s.samples=0;s.started=now;s.deadline=now+45000;s.next_sample=now;s.identity=nil
            Live.slope_observer_emit('START duration_ms=45000 interval_ms=100 local_only=true read_only=true')
        end
        if not s.active then return end
        if now<s.started then Live.slope_observer_stop('clock_reversed');return end
        if now>=s.deadline or s.samples>=s.limit then Live.slope_observer_stop('capture_complete');return end
        if now<s.next_sample then return end
        s.next_sample=now+s.period;s.samples=s.samples+1
        local ok,o=pcall(Live.local_owner)
        if not ok or not o or o.ped~=ped or local_ped()~=ped or not entity_exists(ped)then
            Live.slope_observer_emit('SAMPLE n='..s.samples..' t='..(now-s.started)..' reason=LOCAL_OWNER_UNAVAILABLE')
            return
        end
        local id=s.identity
        if id and (id.ped~=o.ped or id.pid~=o.pid or id.address~=o.address or id.token~=o.token)then
            Live.slope_observer_stop('IDENTITY_CHANGED');return
        end
        if not id then s.identity={ped=o.ped,pid=o.pid,address=o.address,token=o.token}end
        local row={'SAMPLE n='..s.samples,'t='..(now-s.started),'owner=true'}
        row[#row+1]='slope148='..Live.slope_observer_bool(H.GET_PED_CONFIG_FLAG,ped,148,true)
        row[#row+1]='stairs253='..Live.slope_observer_bool(H.GET_PED_CONFIG_FLAG,ped,253,true)
        row[#row+1]='steep203='..Live.slope_observer_bool(0xAF9E59B1B1FBF2A0,ped,203)
        row[#row+1]='task46='..Live.slope_observer_bool(0xB0760331C7AA4155,ped,46)
        row[#row+1]='height='..Live.slope_observer_float(0x1DD55701034110E5,ped)
        row[#row+1]='speed='..Live.slope_observer_float(0xD5037BA82E12416F,ped)
        row[#row+1]='ix='..Live.slope_observer_float(0xEC3C9B8D5327B563,0,30)
        row[#row+1]='iy='..Live.slope_observer_float(0xEC3C9B8D5327B563,0,31)
        for _,item in ipairs(Live.slope_observer_bools)do
            local value
            if item[3]=='none'then value=Live.slope_observer_bool(item[2])
            else value=Live.slope_observer_bool(item[2],item[3]=='pid'and o.pid or ped)end
            row[#row+1]=item[1]..'='..value
        end
        local active,unknown={},{}
        for _,index in ipairs(Live.slope_observer_tasks)do
            local value=Live.slope_observer_bool(0xB0760331C7AA4155,ped,index)
            if value=='true'then active[#active+1]=tostring(index)
            elseif value=='unknown'then unknown[#unknown+1]=tostring(index)end
        end
        row[#row+1]='active_indices='..(#active>0 and table.concat(active,',')or 'none')
        row[#row+1]='unknown_indices='..(#unknown>0 and table.concat(unknown,',')or 'none')
        local held=Live.ragdoll_suppression
        local last=held and held.slope_animation
        row[#row+1]='prior_request='..tostring(last and last.last_result or 'none')
        row[#row+1]='prevent_writes='..tostring(last and last.writes or 0)
        row[#row+1]='prevent_before='..tostring(last and last.stairs_before)
        row[#row+1]='prevent_after='..tostring(last and last.stairs_after)
        row[#row+1]='owns253='..tostring(held and held.flags and held.flags[253]~=nil or false)
        row[#row+1]='pace_request='..tostring(last and last.pace_request or 'none')
        row[#row+1]='descent_guard='..tostring(held and held.slope_descent_active==true or false)
        row[#row+1]='surface_grace='..tostring(held and held.slope_surface and held.slope_surface.grace==true or false)
        if not Live.same_local_owner(o)or local_ped()~=ped then
            Live.slope_observer_stop('IDENTITY_CHANGED_DURING_SAMPLE');return
        end
        Live.slope_observer_emit(table.concat(row,' '))
    end
    Live.slope_observer_emit('READY build=TerrainPace_v3 path=OnStairs253_root148 descent=bounded_support live_result=UNVERIFIED')
    -- Local slope observer end

    -- Slope animation candidate begin
    -- Captured Enhanced ground predicate excludes config253 (OnStairs), before
    -- the parent transitions into the scramble task. This is a per-ped native
    -- experiment, not a claim that all terrain becomes physically traversable.
    -- Unlike the failed recovery path, no motion state or task tree is replaced.
    Live.slope_prevention_guards={
        {0x997ABD671D25CA0B,2,false,'vehicle'}, {0x3317DEDB88C95038,2,true,'dead'},
        {0x47E4E977581C5B55,1,nil,'ragdoll'}, {0x2A74E1D5F2F00EEC,1,nil,'getting_up'},
        {0xCEDABC5900A0BF97,1,nil,'jumping'}, {0xFB92A102F1C4DFA3,1,nil,'falling'},
        {0x886E37EC497200B6,1,nil,'airborne'}, {0x53E8CB4F48BFE623,1,nil,'climbing'},
        {0x117C70D1F5730B5E,1,nil,'vaulting'}, {0x5527B8246FEF9B11,1,nil,'diving'},
        {0x7DCE8BDA0F1C1200,1,nil,'parachuting'}, {0x9DE327631295B4C2,1,nil,'swimming'},
        {0xC024869A53992F34,1,nil,'underwater'}, {0xBB062B2B5722478E,1,nil,'vehicle_entry'},
        {0x4E209B2C1EAD5159,1,nil,'melee'}, {0x57AB4A3080F85143,1,nil,'scenario'},
        {0xB0034A223497FFCB,0,nil,'pause'}, {0x991251AFC3981F84,0,nil,'cutscene'},
        {0xD9D2CFFF49FAB35F,0,nil,'player_switch'},
    }
    function Live.slope_animation_current(o)
        return o and is_on('disable_stumble') and not is_on('messiah_state')
            and not Live.protection.stop_requested and Live.same_local_owner(o)
    end
    function Live.slope_prevention_note(o,result)
        if not o then return end
        local s=o.slope_animation or {writes=0};o.slope_animation=s
        local changed=s.last_result~=result;s.last_result=result
        local now=now_ms()
        if type(now)~='number' or now~=now or math.abs(now)==math.huge then return end
        if changed and (not s.next_log or now>=s.next_log or now<s.next_log-1000) then
            s.next_log=now+1000
            if type(Live.slope_observer_emit)=='function'then
                Live.slope_observer_emit('PREVENTION result='..tostring(result)
                    ..' own253='..tostring(o.flags and o.flags[253]~=nil)
                    ..' writes='..tostring(s.writes)..' visual_result=UNVERIFIED')
            end
        end
    end
    function Live.slope_prevention_release(o,reason,allow_stopped)
        if not o then return true end
        o.slope_descent_active=false;o.slope_last_ground=nil
        local saved=o.flags and o.flags[253]
        if saved then
            if not Live.same_local_owner(o,allow_stopped)then return false end
            if not Live.restore_ragdoll_flag(o,253,saved,allow_stopped)then
                Live.slope_prevention_note(o,'RESTORE_PENDING');return false
            end
            o.flags[253]=nil
        end
        Live.slope_prevention_note(o,reason or 'RELEASED')
        return true
    end
    -- Local surface sample: no velocity, position or move-speed writes.
    -- A grounded contact is evidence for at most 180ms of a small downhill step.
    function Live.slope_surface_sample(o)
        local now=now_ms()
        if not Live.slope_animation_current(o) or type(now)~='number' or now~=now then return nil end
        local function number(hash,...)
            local ok,v,raw,err=pcall(invoke_float_detail,hash,...)
            if ok and err==nil and type(v)=='number' and type(raw)=='number'
                and v==v and raw==raw and math.abs(v)<math.huge and math.abs(raw)<math.huge then return v end
        end
        local slope=Live.protection_bool(H.GET_PED_CONFIG_FLAG,o.ped,148,true)
        local air=Live.protection_bool(0x886E37EC497200B6,o.ped)
        local fall=Live.protection_bool(0xFB92A102F1C4DFA3,o.ped)
        local jump=Live.protection_bool(0xCEDABC5900A0BF97,o.ped)
        local jump_key=Live.protection_bool(0xF3A21BCD95725A4A,0,22)
        local height=number(0x1DD55701034110E5,o.ped)
        local ix=number(0xEC3C9B8D5327B563,0,30)
        local iy=number(0xEC3C9B8D5327B563,0,31)
        local ok,v=pcall(invoke_vec3,0x4805D2B1D8CF94A9,o.ped)
        local parsed,x,y,z=false,nil,nil,nil
        if ok then parsed,x,y,z=pcall(vector_components,v)end
        if slope==nil or air==nil or fall==nil or jump==nil or jump_key==nil
            or not height or not ix or not iy or not parsed or type(z)~='number' or z~=z
            or math.abs(z)==math.huge or math.abs(ix)>1 or math.abs(iy)>1 then return nil end
        if jump or jump_key or height<0 or height>1.6 or not Live.slope_animation_current(o)then
            o.slope_last_ground=nil;return nil
        end
        local moving=ix*ix+iy*iy>0.0001
        local grounded=not air and not fall
        if grounded and slope and moving then o.slope_last_ground=now end
        local last=o.slope_last_ground
        local grace=moving and last~=nil and now>=last and now-last<=180
            and z>=-4.0 and z<=0.5 and (air or fall)
        return {moving=moving,slope=slope,height=height,vz=z,grounded=grounded,grace=grace,
            descent=moving and z<-0.05 and ((grounded and slope)or grace)}
    end
    function Live.slope_animation_tick(o)
        if not o then return end
        o.slope_descent_active=false
        if not Live.slope_animation_current(o) then
            Live.slope_prevention_release(o,'INACTIVE');return
        end
        if Live.protection_bool(0x49C32D60007AFA47,o.pid)~=true
            or Live.protection_bool(0x01FEE67DB37F59B2,o.ped)~=true then
            Live.slope_prevention_release(o,'CONTROL_OR_ONFOOT_UNAVAILABLE');return
        end
        local surface=Live.slope_surface_sample(o)
        o.slope_surface=surface
        -- The native sample can be unavailable even on ordinary flat ground.
        -- Never synthesize OnStairs (config 253) without positive slope evidence:
        -- it changes pedestrian locomotion and can persist until the next release.
        if not surface then
            Live.slope_prevention_release(o,'SURFACE_UNAVAILABLE');return
        end
        if surface.slope~=true and surface.grace~=true then
            Live.slope_prevention_release(o,'NOT_SLOPE');return
        end
        for _,g in ipairs(Live.slope_prevention_guards)do
            local value
            if g[2]==0 then value=Live.protection_bool(g[1])
            elseif g[2]==1 then value=Live.protection_bool(g[1],o.ped)
            else value=Live.protection_bool(g[1],o.ped,g[3])end
            local small_step=value==true and surface and surface.grace
                and (g[4]=='falling' or g[4]=='airborne')
            if value~=false and not small_step then
                Live.slope_prevention_release(o,(value==nil and 'UNKNOWN_'or'YIELD_')..g[4]);return
            end
        end
        for _,index in ipairs({133,134,135})do
            if Live.protection_bool(0xB0760331C7AA4155,o.ped,index)~=false then
                Live.slope_prevention_release(o,'SCRIPTED_ANIMATION');return
            end
        end
        -- Do not wait for task46 or a transient SlopeDetected signal. Prevent
        -- admission while normal local ground movement is eligible, including idle.
        local before=Live.protection_bool(H.GET_PED_CONFIG_FLAG,o.ped,253,true)
        local steep=Live.protection_bool(0xAF9E59B1B1FBF2A0,o.ped,203)
        if before==nil or steep==nil then
            Live.slope_prevention_release(o,'TERRAIN_FLAG_UNAVAILABLE');return
        end
        if steep~=true then
            Live.slope_prevention_release(o,'MILD_SLOPE_NO_STAIRS');return
        end
        if not Live.slope_animation_current(o)then
            Live.slope_prevention_release(o,'OWNER_OR_TOGGLE_CHANGED');return
        end
        local s=o.slope_animation or {writes=0};o.slope_animation=s
        s.stairs_before=before;s.steep_before=steep;s.stairs_after=nil
        if steep then
            local ok,_,err=invoke_void_detail(H.SET_PED_RESET_FLAG,o.ped,203,false)
            if not ok or err~=nil or not Live.slope_animation_current(o)then
                Live.slope_prevention_release(o,'STEEP_RESET_REJECTED');return
            end
            if Live.protection_bool(0xAF9E59B1B1FBF2A0,o.ped,203)~=false then
                Live.slope_prevention_release(o,'STEEP_RESET_UNCONFIRMED');return
            end
        end
        if before==false then
            if not Live.slope_animation_current(o)then
                Live.slope_prevention_release(o,'OWNER_OR_TOGGLE_CHANGED');return
            end
            o.flags=o.flags or {}
            -- Ownership precedes an attempt because a native can partially act
            -- before reporting failure. Leave preexisting real stairs unowned.
            if not o.flags[253]then o.flags[253]={before=false,last=true}end
            local ok,_,err=invoke_void_detail(H.SET_PED_CONFIG_FLAG,o.ped,253,true)
            s.writes=math.min((s.writes or 0)+1,1000000)
            if not ok or err~=nil then
                Live.slope_prevention_release(o,'STAIRS_WRITE_REJECTED');return
            end
        end
        if not Live.slope_animation_current(o)then
            Live.slope_prevention_release(o,'OWNER_OR_TOGGLE_CHANGED');return
        end
        local after=Live.protection_bool(H.GET_PED_CONFIG_FLAG,o.ped,253,true)
        if not Live.slope_animation_current(o)then
            Live.slope_prevention_release(o,'OWNER_OR_TOGGLE_CHANGED');return
        end
        s.stairs_after=after
        if after~=true then
            Live.slope_prevention_release(o,'STAIRS_READBACK_UNCONFIRMED');return
        end
        local owned=o.flags and o.flags[253]~=nil
        o.slope_descent_active=owned and surface and surface.descent==true or false
        s.pace_request='NOT_REQUESTED'
        if owned and surface and surface.moving and (surface.slope or surface.grace)
            and (surface.grounded or surface.grace) and Live.slope_animation_current(o)then
            -- Captured root-slope solver explicitly checks PRF148. Apply only
            -- to our synthetic stairs, never genuine preexisting stairs.
            local ok,_,err=invoke_void_detail(H.SET_PED_RESET_FLAG,o.ped,148,true)
            s.pace_request=ok==true and err==nil and 'ROOT_SLOPE_REQUEST_ACCEPTED_UNVERIFIED'
                or 'ROOT_SLOPE_REQUEST_REJECTED'
        end
        Live.slope_prevention_note(o,owned
            and 'PREVENTION_NATIVE_VERIFIED' or 'PREEXISTING_STAIRS_UNOWNED')
        -- Readback proves this native state only. GTA may recalculate OnStairs
        -- later in its frame; live animation absence must be checked separately.
    end
    -- Slope animation candidate end

    function Live.apply_ragdoll_suppression(ped)
        local ragdoll, stumble = is_on("no_ragdoll"), is_on("disable_stumble")
        if not stumble then Live.slope_prevention_release(Live.ragdoll_suppression,'TOGGLE_OFF') end
        if not stumble and (Live.slope_movement.HasWork() or next(Live.slope_buffers) ~= nil) then
            Live.slope_movement.Stop()
        end
        if not ragdoll and not stumble then
            Live.restore_ragdoll_suppression(); return
        end
        local owner = Live.local_owner()
        if not owner or owner.ped ~= ped or Live.protection_bool(0x5E9564D8246B909A, owner.pid) ~= true
            or Live.protection_bool(H.IS_PED_DEAD_OR_DYING, ped, true) ~= false or not Live.same_local_owner(owner) then
            Live.slope_prevention_release(Live.ragdoll_suppression,'OWNER_NOT_PLAYABLE')
            Live.slope_movement.Stop(); return
        end
        local o = Live.ragdoll_suppression
        if o and (o.pid ~= owner.pid or o.ped ~= owner.ped or o.address ~= owner.address or o.token ~= owner.token) then
            Live.ragdoll_suppression = nil; o = nil
        end
        if not o then
            o = owner; o.flags = {}; Live.ragdoll_suppression = o
        end
        -- Sample terrain before the shared config-flag ownership pass.
        if stumble then Live.slope_animation_tick(o) end
        -- No Ragdoll keeps its broad scope. Disable Stumble shares flag164
        -- only during a verified near-ground downward step, not ordinary falls.
        -- Stumble separately covers object impacts and ped/ragdoll contacts;
        -- 318 is the inverse gate that enables ragdoll on minor contact.
        local config_flags = { { 106, true, "no_ragdoll" }, { 164, true, "no_ragdoll" }, { 221, true, "no_ragdoll" },
            { 89,  true, "disable_stumble" }, { 160, true, "disable_stumble" }, { 306, true, "disable_stumble" },
            { 307, true, "disable_stumble" }, { 308, true, "disable_stumble" }, { 318, false, "disable_stumble" } }
        -- Persistent stumble flags need periodic validation, not nine checks
        -- every rendered frame. Restore remains immediate on toggle-off.
        local now = now_ms()
        local stumble_refresh_due = stumble and (not o.stumble_flags_next_ms
            or now < o.stumble_flags_next_ms - 300 or now >= o.stumble_flags_next_ms)
        if stumble_refresh_due then o.stumble_flags_next_ms = now + 300 end
        if not stumble then o.stumble_flags_next_ms = nil end
        for _, spec in ipairs(config_flags) do
            local flag, value, key = spec[1], spec[2], spec[3]
            local saved = o.flags[flag]
            local enabled = is_on(key) or (flag == 164 and stumble and o.slope_descent_active == true)
            if enabled and (key ~= "disable_stumble" or stumble_refresh_due) then
                local before = Live.protection_bool(H.GET_PED_CONFIG_FLAG, ped, flag, true)
                if before ~= nil and Live.same_local_owner(o) then
                    if not saved or before ~= saved.last then
                        -- Preserve a later owner's preference before reapplying
                        -- this enabled control, including inverse flag 318.
                        saved = { before = before, last = before }; o.flags[flag] = saved
                    end
                    local still_enabled = is_on(key) or (flag == 164
                        and is_on("disable_stumble") and o.slope_descent_active == true)
                    if still_enabled and Live.same_local_owner(o) then
                        saved.last = value
                        if before ~= value then invoke_void(H.SET_PED_CONFIG_FLAG, ped, flag, value) end
                    end
                end
            elseif not enabled and saved then
                if Live.restore_ragdoll_flag(o, flag, saved) then o.flags[flag] = nil end
            end
        end
        if ragdoll then
            o.can_verified, o.collision_verified = false, false
            -- Reset flags also require SET_PED_CAN_RAGDOLL to revoke ragdoll permission.
            local current = Live.protection_bool(0x128F79EDCECE4FD5, ped)
            if current ~= nil and is_on("no_ragdoll") and Live.same_local_owner(o) then
                if o.can_before == nil then
                    o.can_before = Live.ragdoll_baseline(o, current); o.can_last = current
                end
                if Live.same_local_owner(o) then
                    o.can_last = false; if current ~= false then invoke_void(H.SET_PED_CAN_RAGDOLL, ped, false) end
                end
                o.can_verified = Live.same_local_owner(o) and Live.protection_bool(0x128F79EDCECE4FD5, ped) == false
            end
            local proofs = Live.read_ragdoll_proofs(o)
            if proofs and is_on("no_ragdoll") and Live.same_local_owner(o) then
                if o.collision_before == nil then o.collision_before = proofs[4] end
                o.collision_last = true
                o.collision_verified = proofs[4] == true or Live.write_collision_proof(o, proofs, true)
            end
            -- Collision proof does not cover GTA's separate high-fall death path.
            if is_on("no_ragdoll") and Live.same_local_owner(o) then
                o.high_fall_owned = true
                o.high_fall_accepted = invoke_void(0x711794453CFD692B, ped, true) == true
            end
            -- Suppress the in-air event and explosion fall task as well as NM ragdoll.
            for _, flag in ipairs({ 370, 210, 274, 150, 458 }) do
                if is_on("no_ragdoll") and Live.same_local_owner(o) then
                    invoke_void(H.SET_PED_RESET_FLAG, ped, flag,
                        true)
                end
            end
            Live.recover_fall_task(o)
            if not (o.can_verified and o.collision_verified and o.high_fall_accepted) then
                local now = now_ms()
                if not o.last_failure_log or now - o.last_failure_log >= 5000 then
                    o.last_failure_log = now
                    log_info(("NoRagdoll pending native verification: permission=%s collision=%s high_fall_accepted=%s")
                        :format(tostring(o.can_verified), tostring(o.collision_verified), tostring(o.high_fall_accepted)))
                end
            end
        else
            Live.restore_ragdoll_permission(o)
            Live.restore_collision_proof(o)
            Live.release_high_fall(o)
        end
        if stumble then
            -- The frame-scoped reset flags are the only per-frame stumble
            -- writes. Never clear locomotion tasks or override ped velocity.
            -- GTA retains normal steep-slope walking and natural fall recovery.
            -- Normal falling and CAN_PED_RAGDOLL remain unaffected here.
            -- Per-frame reset channels cover animated ped bumps and ragdoll
            -- contacts immediately, including between persistent flag refreshes.
            -- No NeverRagdoll, collision-proof, task-clear or velocity override.
            for _, flag in ipairs({ 21, 293, 294, 295, 319, 371, 210 }) do
                if is_on("disable_stumble") and Live.same_local_owner(o) then
                    invoke_void(H.SET_PED_RESET_FLAG, ped, flag, true)
                end
            end
            -- Separate slope response: no task clearing or velocity override.
            -- Terrain prevention already ran before the shared flag ownership pass.
        end
    end

    local function apply_local_suppression(ped)
        Live.slope_observer_tick(ped, now_ms())
        Live.apply_ragdoll_suppression(ped)
        if not started or not (is_on("no_ragdoll") or is_on("no_critical_hits") or is_on("no_wanted")) then return end
        local pid = local_player_id()
        local generation, token = suppression_generation, lifecycle_token
        local function current()
            return started and suppression_generation == generation and token == lifecycle_token
                and token and token.alive and local_player_id() == pid and local_ped() == ped
        end
        if type(pid) ~= "number" or pid < 0 or pid > 31 or pid % 1 ~= 0 or not current()
            or not invoke_bool(0x5E9564D8246B909A, pid) or not current() then
            return
        end
        -- Only a current local-owner lookup and matching pointer roundtrip can
        -- authorize each entity write. No ped alias is retained between frames.
        local function owned()
            if not current() or not (gta and type(gta.GetLocalPed) == "function" and type(gta.HandleToPointer) == "function") then return false end
            if type(ped) ~= "number" or ped <= 0 or ped >= 2147483647 or ped % 1 ~= 0 then return false end
            local ok, address = pcall(function() return gta.GetLocalPed():GetAddress() end)
            if not ok or type(address) ~= "number" or address <= 0 or address >= math.huge or not current() then return false end
            local mapped, value = pcall(function() return gta.HandleToPointer(ped):GetAddress() end)
            return mapped and value == address and current()
        end
        if is_on("no_critical_hits") and owned() and is_on("no_critical_hits") and current() then
            invoke_void(
                H.SET_PED_SUFFERS_CRITICAL_HITS, ped, false)
        end
        if is_on("no_wanted") and owned() then
            local wanted = invoke_int(H.GET_PLAYER_WANTED_LEVEL, pid)
            if not current() or not is_on("no_wanted") then return end
            if wanted > 0 then invoke_void(H.CLEAR_PLAYER_WANTED_LEVEL, pid) end
            if current() and is_on("no_wanted") and current() then invoke_void(H.SET_MAX_WANTED_LEVEL, 0) end
        end
    end

    -- Local input assistance and explicitly bounded, read-back-checked supplies.
    -- This is a custom consumption path, not the game's snack animation script.
    do
        local Q = {
            generation = 0,
            stopped = false,
            last_now = nil,
            next_refill = 0,
            manual_snacks = false,
            manual_armour = false,
            status = "Idle",
            detail = "",
            inputs = {},
            enabled = {},
            escape_pending = nil,
            auto_fault = {},
            refill_messages = {},
            weapon_wheel_forced = false,
            rearm_pending = true,
            rearm_ready = false,
            rearm_reason = "cold-start",
            rearm_attempts = 0,
            rearm_next_ms = 0,
            rearm_ped = 0,
            rearm_pid = -1
        }
        Live.qol = Q
        local N = {
            playing = 0x5E9564D8246B909A,
            dead = 0x5F9532F3B5CC2551,
            pause = 0xB0034A223497FFCB,
            warning = 0xE18B138FABC53103,
            chat = 0xB118AF58B5F332A1,
            keyboard = 0x0CF2B696BBF945AE,
            pressed = 0xF3A21BCD95725A4A,
            disabled_pressed = 0xE2587F8CBBD87B1D,
            just_pressed = 0x580417101DDB492F,
            disabled_just_pressed = 0x91AEF906BCA88877,
            set_control = 0xE8A25867FBA3B05E,
            disable_control = 0xFE99B66D079CF6BC,
            exclusive = 0xEDE476E5EE29EDB1,
            set_pause = 0xDF47FC56C71569CF,
            set_frontend_active = 0x745711A75AB09277,
            pause_state = 0x272ACD84970869C5,
            activate_frontend = 0xEF01D36B9C9D0C7B,
            max_armour = 0x92659B4CE1863CB3,
            enable_control = H.ENABLE_CONTROL_ACTION,
            force_weapon_wheel = H.HUD_FORCE_WEAPON_WHEEL,
            can_switch_weapon = H.SET_PED_CAN_SWITCH_WEAPON,
        }
        local SNACKS = {
            { name = "NO_BOUGHT_YUM_SNACKS",    target = 30 },
            { name = "NO_BOUGHT_HEALTH_SNACKS", target = 15 },
            { name = "NO_BOUGHT_EPIC_SNACKS",   target = 5 },
            { name = "NUMBER_OF_ORANGE_BOUGHT", target = 10 },
            { name = "NUMBER_OF_SPRUNK_BOUGHT", target = 10 },
        }
        local FLAGS = { "better_escape", "wheel_snacks", "wheel_armour",
            "auto_snack_inventory", "auto_armour_inventory" }
        local function integer(v, lo, hi)
            return type(v) == "number" and v % 1 == 0 and v >= lo and v <= hi
        end
        local function int(hash, ...)
            local _, raw, err = invoke_int_detail(hash, ...)
            return not err and integer(raw, -2147483648, 4294967295) and raw or nil
        end
        local function boolean(hash, ...)
            local value, raw, err = invoke_bool_detail(hash, ...)
            if err or (type(raw) ~= "boolean" and not integer(raw, 0, 1)) then return nil end
            return value == true
        end
        local function key(vk)
            if not (utils and type(utils.IsKeyDown) == "function") then return false end
            local ok, value = pcall(utils.IsKeyDown, vk)
            return ok and value == true
        end
        local function live()
            return started and not Q.stopped and lifecycle_token and lifecycle_token.alive == true
        end
        local function note(status, detail)
            detail = tostring(detail or "")
            if Q.status ~= status or Q.detail ~= detail then
                Q.status, Q.detail = status, detail
                log_info("Supplies status=" .. status .. " detail=" .. detail)
            end
        end
        local function clear_inputs()
            Q.inputs = {}; Q.escape_pending = nil
            if Q.weapon_wheel_forced then
                invoke_void_detail(N.force_weapon_wheel, false)
                Q.weapon_wheel_forced = false
            end
        end
        function Q.reset(reason, stopped)
            Q.generation = Q.generation + 1; Q.stopped = stopped == true
            Q.manual_snacks = false; Q.manual_armour = false
            Q.last_now = nil; Q.next_refill = 0; Q.enabled = {}; Q.auto_fault = {}; Q.refill_messages = {}
            Q.rearm_pending = not Q.stopped; Q.rearm_ready = false
            Q.rearm_reason = tostring(reason or "reset"); Q.rearm_attempts = 0; Q.rearm_next_ms = 0
            Q.rearm_ped = 0; Q.rearm_pid = -1
            clear_inputs(); Q.status = "Idle"; Q.detail = tostring(reason or "reset")
        end

        function Q.changed(flag)
            Q.generation = Q.generation + 1
            clear_inputs(); Q.enabled[flag] = nil; Q.last_now = nil
            if flag == "better_escape" then Q.escape_pending = nil end
            if flag == "auto_snack_inventory" then Q.auto_fault.snacks = nil end
            if flag == "auto_armour_inventory" then Q.auto_fault.armour = nil end
        end

        function Q.requested()
            if Q.stopped then return false end
            -- Keep the existing single player frame owner alive after a cold
            -- load/session reset until the local ped + raw keyboard bridge have
            -- both been positively observed. This removes the manual reload as
            -- an accidental "rearm" step without adding another scheduler.
            if Q.rearm_pending then return true end
            if Q.manual_snacks or Q.manual_armour then return true end
            for _, flag in ipairs(FLAGS) do if is_on(flag) then return true end end
            return false
        end

        function Q.snapshot()
            return {
                status = Q.status,
                detail = Q.detail,
                pending_snacks = Q.manual_snacks,
                pending_armour = Q.manual_armour,
                custom_snack_health = 25,
                consumption_interval_ms = 50,
                inventory_interval_ms = 2000,
                cold_start_rearm = Q.rearm_pending and "WAITING" or (Q.rearm_ready and "READY" or "IDLE"),
                rearm_reason = Q.rearm_reason,
                rearm_attempts = Q.rearm_attempts,
                rearm_ped = Q.rearm_ped,
                rearm_pid = Q.rearm_pid
            }
        end

        local function owner(ped)
            if not live() or not integer(ped, 1, 2147483646) or not entity_exists(ped) then return nil end
            local pid = local_player_id()
            if not integer(pid, 0, 31) or local_ped() ~= ped or boolean(N.playing, pid) ~= true
                or boolean(N.dead, ped, false) ~= false then
                return nil
            end
            if not (gta and type(gta.GetLocalPed) == "function" and type(gta.HandleToPointer) == "function") then return nil end
            local ok, address, mapped = pcall(function()
                return gta.GetLocalPed():GetAddress(), gta.HandleToPointer(ped):GetAddress()
            end)
            local model = int(H.GET_ENTITY_MODEL, ped)
            if not ok or not integer(address, 1, 0x7FFFFFFFFFFF) or mapped ~= address
                or not model or model == 0 or local_ped() ~= ped or not live() then
                return nil
            end
            return {
                ped = ped,
                pid = pid,
                address = address,
                model = model,
                token = lifecycle_token,
                generation = Q
                    .generation
            }
        end
        local function same(c)
            if not c or not live() or c.token ~= lifecycle_token or c.generation ~= Q.generation then return false end
            local current = owner(c.ped)
            return current and current.pid == c.pid and current.address == c.address and current.model == c.model
                and c.token == lifecycle_token and c.generation == Q.generation
        end
        local function cold_start_rearm(now, ped)
            if not Q.rearm_pending then return true end
            if now < (tonumber(Q.rearm_next_ms) or 0) then return false end
            Q.rearm_next_ms = now + 100
            Q.rearm_attempts = (tonumber(Q.rearm_attempts) or 0) + 1
            local c = owner(ped)
            if not c then return false end
            if not (utils and type(utils.IsKeyDown) == "function") then return false end
            -- Probe only the three raw keys this owner needs. Their current
            -- pressed values are irrelevant; successful boolean reads establish
            -- that Cherax's keyboard bridge is callable in this generation.
            local tab_ok, tab = pcall(utils.IsKeyDown, 0x09)
            local c_ok, ckey = pcall(utils.IsKeyDown, 0x43)
            local v_ok, vkey = pcall(utils.IsKeyDown, 0x56)
            if not tab_ok or not c_ok or not v_ok or type(tab) ~= "boolean"
                or type(ckey) ~= "boolean" or type(vkey) ~= "boolean" then
                return false
            end
            clear_inputs()
            Q.enabled = {}
            for _, flag in ipairs(FLAGS) do Q.enabled[flag] = is_on(flag) end
            Q.auto_fault = {}; Q.refill_messages = {}; Q.escape_pending = nil
            Q.last_now = now; Q.next_refill = now + 250
            Q.rearm_pending = false; Q.rearm_ready = true
            Q.rearm_ped = c.ped; Q.rearm_pid = c.pid
            suppression_generation = (tonumber(suppression_generation) or 0) + 1
            if type(State) == "table" then
                if type(State.peds_ignore) == "table" then
                    State.peds_ignore.last_scan_ms = -100000; State.peds_ignore.scan_cursor = 0
                end
                if type(State.super_melee) == "table" then
                    State.super_melee.last_scan_ms = -100000; State.super_melee.rendered_cache = nil
                    if State.super_melee.swing then
                        State.super_melee.swing.armed = true
                        State.super_melee.swing.action_was_performing = false
                        State.super_melee.swing.observations = {}
                    end
                end
            end
            local detail = ("reason=%s attempts=%d ped=%d pid=%d tab=%s c=%s v=%s")
                :format(tostring(Q.rearm_reason), Q.rearm_attempts, c.ped, c.pid,
                    tostring(tab), tostring(ckey), tostring(vkey))
            Q.status = "ColdStartRearm=READY"; Q.detail = detail
            log_info("ColdStartRearm=READY " .. detail)
            return true
        end

        local function input_safe(allow_pause)
            -- Only observed blockers stop this input path; unavailable reads do not cancel a hold.
            local paused = boolean(N.pause)
            if paused == true and not allow_pause then return false, "pause" end
            local warning = boolean(N.warning)
            if warning == true then return false, "warning" end
            local chat = boolean(N.chat)
            if chat == true then return false, "chat" end
            local keyboard = int(N.keyboard)
            if keyboard == 0 then return false, "onscreen-keyboard" end
            local gui = deps.GUI
            if gui and type(gui.IsOpen) == "function" then
                local ok, open = pcall(gui.IsOpen)
                if ok and open == true then return false, "cherax-menu" end
            end
            if key(0x12) or key(0x11) or key(0x5B) or key(0x5C) then
                return false, "modifier"
            end
            return true, "ok"
        end
        local function pressed(control)
            return boolean(N.pressed, 0, control) == true or boolean(N.disabled_pressed, 0, control) == true
                or boolean(N.pressed, 2, control) == true or boolean(N.disabled_pressed, 2, control) == true
        end
        local function control_just_pressed(control)
            for _, group in ipairs({ 0, 2 }) do
                if boolean(N.just_pressed, group, control) == true
                    or boolean(N.disabled_just_pressed, group, control) == true then
                    return true
                end
            end
            return false
        end
        local function tab_down()
            -- Read the physical chord independently of GTA's weapon-wheel,
            -- pause/chat/modifier gates, ragdoll, and task state.
            return key(0x09)
        end
        local function chord_down(kind)
            return tab_down() and key(kind == "snacks" and 0x43 or 0x56)
        end
        local function pause_frontend_state()
            local paused = boolean(N.pause)
            local state = int(N.pause_state)
            if paused == nil or state == nil then return nil, nil end
            return paused == true and state > 0, state
        end
        local function pulse_pause_control()
            local accepted = false
            for _, group in ipairs({ 0, 2 }) do
                invoke_void_detail(N.exclusive, group, 199)
                -- NativeDB specifies a BOOL result for SET_CONTROL_VALUE_NEXT_FRAME;
                -- retain it to distinguish accepted input from a failed call.
                local value, raw, err = invoke_bool_detail(N.set_control, group, 199, 1.0)
                if err == nil and (value == true or raw == true or raw == 1) then accepted = true end
            end
            return accepted
        end
        local function activate_pause_frontend()
            -- FE_MENU_VERSION_MP_PAUSE = joaat("FE_MENU_VERSION_MP_PAUSE").
            -- Component -1 is the game's documented map/default pause component.
            local accepted, _, err = invoke_void_detail(N.activate_frontend, 0xBA33ADB3, true, -1)
            return accepted == true and err == nil
        end
        local function deactivate_pause_frontend()
            -- Rockstar scripts close an active pause frontend with
            -- SET_FRONTEND_ACTIVE(false). Pair it with SET_PAUSE_MENU_ACTIVE(false)
            -- so both the frontend and pause flag are released.
            local a, _, ea = invoke_void_detail(N.set_frontend_active, false)
            local b, _, eb = invoke_void_detail(N.set_pause, false)
            return (a == true and ea == nil) or (b == true and eb == nil)
        end
        local function economy(c)
            local cs = module_context and module_context.CScript
            local e = cs and cs.Economy
            if not (e and type(e.CurrentSlot) == "function" and type(e.ReadStat) == "function" and type(e.WriteStat) == "function") then return nil end
            local ok, slot = pcall(e.CurrentSlot)
            if not ok or not integer(slot, 0, 1) or not same(c) then return nil end
            return { api = e, slot = slot, prefix = "MP" .. tostring(slot) .. "_", owner = c }
        end
        local function stock_valid(s)
            local cs = module_context and module_context.CScript
            if not s or not cs or cs.Economy ~= s.api or not same(s.owner) then return false end
            local ok, slot = pcall(s.api.CurrentSlot)
            return ok and slot == s.slot and same(s.owner)
        end
        local function stock_read(s, name)
            local ok, value = pcall(s.api.ReadStat, s.prefix .. name)
            if not ok or not integer(value, 0, 100000) then return nil end
            return value
        end
        local function stock_write(s, name, before, after, admitted)
            if not stock_valid(s) or not admitted() or stock_read(s, name) ~= before
                or not stock_valid(s) or not admitted() then
                return false, "stock/context changed"
            end
            local ok, accepted = pcall(s.api.WriteStat, s.prefix .. name, after)
            if not ok or accepted ~= true then return false, "inventory write rejected" end
            if not stock_valid(s) or stock_read(s, name) ~= after then return false, "inventory write not verified" end
            return true
        end
        local function vitals(c, kind)
            local value = int(kind == "snacks" and H.GET_ENTITY_HEALTH or H.GET_PED_ARMOUR, c.ped)
            local maximum = kind == "snacks" and int(H.GET_ENTITY_MAX_HEALTH, c.ped) or int(N.max_armour, c.pid)
            if not integer(value, 0, 100000) or not integer(maximum, 1, 100000) then return nil end
            if kind == "snacks" and value <= 0 then return nil end
            return value, maximum
        end
        local SUPPLY_REPEAT_MS = 50
        local SUPPLY_APPLY_RETRY_MS = 220
        local function apply_supply_bar(now, c, kind, input)
            local pending = input.pending_apply
            if not pending then return true end
            local flag = kind == "snacks" and "wheel_snacks" or "wheel_armour"
            if not same(c) or not is_on(flag) or now > (pending.deadline or now) then
                input.pending_apply = nil; input.done = true
                note("Unverified", kind .. ": item debited; bounded bar apply expired")
                return false
            end
            local observed = select(1, vitals(c, kind))
            if observed and observed >= pending.target then
                input.pending_apply = nil; input.next = now + SUPPLY_REPEAT_MS
                input.done = observed >= pending.maximum
                note(input.done and "Full" or "Consumed", kind .. ": bar update verified")
                return true
            end
            if kind == "snacks" then
                invoke_void_detail(H.SET_ENTITY_HEALTH, c.ped, pending.target, 0)
            else
                invoke_void_detail(H.SET_PED_ARMOUR, c.ped, pending.target)
            end
            pending.attempts = (pending.attempts or 0) + 1
            return false
        end

        local function consume(now, c, kind, input)
            local flag = kind == "snacks" and "wheel_snacks" or "wheel_armour"
            local function admitted()
                -- Held supplies require the enabled chord and current local character.
                -- input_safe(), weapon-wheel admission, and task state do not gate this path.
                return is_on(flag) and same(c) and chord_down(kind)
            end
            local value, maximum = vitals(c, kind)
            if not value then
                input.done = true; note("Blocked", kind .. ": vitals unreadable"); return
            end
            if value >= maximum then
                input.done = true; note("Full", kind); return
            end
            if not admitted() then
                input.next = now + SUPPLY_REPEAT_MS; return
            end
            local s = input.stock
            if not s or not stock_valid(s) then
                input.done = true; note("Blocked", kind .. ": held inventory context unavailable/changed"); return
            end
            local selected, count, amount
            if kind == "snacks" then
                for _, row in ipairs(SNACKS) do
                    local n = stock_read(s, row.name)
                    if n == nil then
                        input.done = true; note("Blocked", "snack inventory unreadable"); return
                    end
                    if n > 0 then
                        selected, count, amount = row.name, n, 25; break
                    end
                end
            else
                for tier = 5, 1, -1 do
                    local name = "MP_CHAR_ARMOUR_" .. tier .. "_COUNT"
                    local n = stock_read(s, name)
                    if n == nil then
                        input.done = true; note("Blocked", "armor inventory unreadable"); return
                    end
                    if n > 0 then
                        selected, count, amount = name, n, 20 * tier; break
                    end
                end
            end
            if not selected then
                input.done = true; note("Empty", kind); return
            end
            -- Read the bar again after inventory reads. Never spend at full health.
            value, maximum = vitals(c, kind)
            if not value or value >= maximum then
                input.done = true; return
            end
            if not admitted() then
                input.next = now + SUPPLY_REPEAT_MS; return
            end
            local ok, reason = stock_write(s, selected, count, count - 1, admitted)
            if not ok then
                input.done = true; note("Blocked", kind .. ": " .. reason); return
            end
            -- No guessing/refunding after ambiguous host failure: that can duplicate
            -- inventory or heal a replaced character. Stop this hold and report it.
            if not stock_valid(s) or not admitted() then
                input.done = true; note("Stopped", kind .. ": context changed after debit"); return
            end
            value, maximum = vitals(c, kind)
            if not value or value >= maximum or not stock_valid(s) or not admitted() then
                input.done = true; note("Stopped", kind .. ": bar/context changed after debit"); return
            end
            local target = math.min(maximum, value + amount)
            input.pending_apply = { target = target, maximum = maximum, deadline = now + SUPPLY_APPLY_RETRY_MS, attempts = 0 }
            apply_supply_bar(now, c, kind, input)
            if input.pending_apply then
                -- Do not debit a second item until this exact target is observed.
                input.next = now
                note("Applying", kind .. ": item debited; retrying bar during uncontrollable state")
            else
                input.next = now + SUPPLY_REPEAT_MS; input.done = target >= maximum
                note(input.done and "Full" or "Consumed", kind .. ": " .. selected .. " remaining=" .. (count - 1))
            end
        end
        local function refill(c, kind, manual)
            local flag = kind == "snacks" and "auto_snack_inventory" or "auto_armour_inventory"
            local armour_baseline
            local s
            local function admitted()
                if not same(c) or not (manual or is_on(flag)) then return false end
                if armour_baseline then
                    for tier = 1, 4 do
                        if stock_read(s, "MP_CHAR_ARMOUR_" .. tier .. "_COUNT") ~= armour_baseline[tier] then return false end
                    end
                end
                return same(c) and (manual or is_on(flag))
            end
            s = economy(c)
            if not s then return false, "active inventory unavailable" end
            local rows = {}
            if kind == "snacks" then
                for _, row in ipairs(SNACKS) do rows[#rows + 1] = { name = row.name, target = row.target } end
            else
                local total, heavy = 0, nil
                armour_baseline = {}
                for tier = 1, 5 do
                    local n = stock_read(s, "MP_CHAR_ARMOUR_" .. tier .. "_COUNT")
                    if n == nil then return false, "armor inventory unreadable" end
                    total = total + n; armour_baseline[tier] = n; if tier == 5 then heavy = n end
                end
                -- Conservative combined target, not ten of every tier. Never reduce
                -- existing quantities, override rank, or claim this is a live carry cap.
                rows[1] = { name = "MP_CHAR_ARMOUR_5_COUNT", target = heavy + math.max(0, 10 - total) }
            end
            -- Snapshot every row before the first write; absent stats never become 0.
            for _, row in ipairs(rows) do
                row.before = stock_read(s, row.name)
                if row.before == nil then return false, "inventory unreadable: " .. row.name end
            end
            local changed = 0
            for _, row in ipairs(rows) do
                if row.before < row.target then
                    local ok, reason = stock_write(s, row.name, row.before, row.target, admitted)
                    if not ok then return false, reason .. "; verified rows=" .. changed end
                    changed = changed + 1
                end
            end
            if not stock_valid(s) or not admitted() then return false, "context changed" end
            return true, "verified rows=" .. changed
        end
        local function refill_tick(now, c)
            local auto_due = now >= Q.next_refill
            if auto_due then Q.next_refill = now + 2000 end
            for _, kind in ipairs({ "snacks", "armour" }) do
                local manual = Q["manual_" .. kind] == true
                Q["manual_" .. kind] = false
                local flag = kind == "snacks" and "auto_snack_inventory" or "auto_armour_inventory"
                if manual or (auto_due and is_on(flag) and not Q.auto_fault[kind]) then
                    local ok, reason = refill(c, kind, manual)
                    Q.auto_fault[kind] = not ok
                    local signature = tostring(ok) .. ":" .. reason
                    if manual or Q.refill_messages[kind] ~= signature then
                        Q.refill_messages[kind] = signature
                        note(ok and "Inventory ready" or "Refill stopped", kind .. ": " .. reason)
                    end
                    if manual then
                        toast((ok and "Inventory ready: " or "Refill stopped: ") .. kind .. "; " .. reason,
                            4000, ok and "info" or "warning")
                    end
                    if not same(c) then return end
                end
            end
        end
        function Q.tick(now, ped)
            if not live() or not Q.requested() then return end
            if not integer(now, 0, 9007199254740991) then
                Q.reset("invalid clock"); return
            end
            if Q.rearm_pending and not cold_start_rearm(now, ped) then return end
            if Q.last_now and (now < Q.last_now or now - Q.last_now > 1000) then
                Q.reset("frame gap"); Q.last_now = now; Q.next_refill = now + 2000; return
            end
            Q.last_now = now
            for _, flag in ipairs(FLAGS) do
                local enabled = is_on(flag)
                if Q.enabled[flag] ~= enabled then
                    Q.inputs[flag] = nil; Q.enabled[flag] = enabled
                    if flag == "auto_snack_inventory" then Q.auto_fault.snacks = nil end
                    if flag == "auto_armour_inventory" then Q.auto_fault.armour = nil end
                end
            end
            local wants_input = is_on("better_escape") or is_on("wheel_snacks") or is_on("wheel_armour")
            local refill_due = Q.manual_snacks or Q.manual_armour
                or (now >= Q.next_refill and ((is_on("auto_snack_inventory") and not Q.auto_fault.snacks)
                    or (is_on("auto_armour_inventory") and not Q.auto_fault.armour)))
            -- Auto-refill waiting/faulted states perform no native or stat work.
            if not wants_input and not refill_due then return end
            -- Keep input edges on the frame cadence, but do not prove a gameplay
            -- owner or inspect inventory while no input/refill needs that owner.
            -- Pending actions and the first release frame still drain normally.
            local raw_escape = is_on("better_escape") and key(0x1B)
            local native_escape_edge = is_on("better_escape") and control_just_pressed(200)
            local native_escape_held = is_on("better_escape") and pressed(200)
            local escape = Q.inputs.better_escape
            local input_due = raw_escape or native_escape_edge or native_escape_held
                or Q.escape_pending or (escape and (escape.held or escape.owned))
            for _, kind in ipairs({ "snacks", "armour" }) do
                local flag = kind == "snacks" and "wheel_snacks" or "wheel_armour"
                local input = Q.inputs[flag]
                if is_on(flag) and (chord_down(kind) or (input and (input.held or input.pending_apply))) then
                    input_due = true
                end
            end
            if not input_due and not refill_due and not Q.weapon_wheel_forced then
                -- Establish the released baseline so the next Esc press is an edge.
                if is_on("better_escape") and not escape then Q.inputs.better_escape = { held = false, owned = false } end
                return
            end
            local c = owner(ped)
            if not c then
                if Q.manual_snacks or Q.manual_armour then
                    note("Refill stopped", "current local character unavailable")
                    toast("Refill stopped: current local character unavailable.", 4000, "warning")
                end
                Q.manual_snacks = false; Q.manual_armour = false
                Q.next_refill = now + 2000; clear_inputs(); return
            end
            if Q.escape_pending then
                local frontend, frontend_state = pause_frontend_state()
                local observed = boolean(N.pause)
                local reached = Q.escape_pending.target == true and frontend == true
                    or Q.escape_pending.target == false and observed == false
                if reached then
                    note("Pause observed", Q.escape_pending.target and
                        ("frontend opened state=" .. tostring(frontend_state)) or "pause frontend closed")
                    Q.escape_pending = nil
                elseif not Q.escape_pending.fallback and now - Q.escape_pending.at >= 180 then
                    Q.escape_pending.fallback = true
                    local accepted = Q.escape_pending.target and activate_pause_frontend()
                        or deactivate_pause_frontend()
                    Q.escape_pending.fallback_accepted = accepted
                    note("Pause fallback", accepted and
                        (Q.escape_pending.target and "direct MP pause frontend submitted"
                            or "direct frontend close submitted")
                        or "direct frontend fallback rejected")
                elseif now - Q.escape_pending.at >= 600 then
                    Q.escape_pending = nil
                    note("Pause unverified", "direct frontend route and fallback did not reach the requested state")
                end
            end
            local paused = boolean(N.pause)
            local frontend = select(1, pause_frontend_state())
            -- Tab+C / Tab+V use raw chords. Release a previously forced weapon
            -- wheel once so GTA retains normal slot-selection input.
            if Q.weapon_wheel_forced then
                invoke_void_detail(N.force_weapon_wheel, false)
                Q.weapon_wheel_forced = false
            end
            local escape_held = raw_escape or native_escape_held
            if is_on("better_escape") then
                local state = Q.inputs.better_escape
                if not state then
                    state = { held = escape_held, owned = false }; Q.inputs.better_escape = state
                end
                local escape_edge = (raw_escape and not state.held) or native_escape_edge
                if escape_edge and not key(0x50) and same(c) then
                    -- Accept VK_ESCAPE or INPUT_FRONTEND_PAUSE_ALTERNATE (200).
                    -- Exclude INPUT_FRONTEND_CANCEL (202) so Backspace remains Back.
                    local active = frontend == true or paused == true
                    local target = not active
                    log_info(("BetterEscape edge=down source=%s rawEsc=%s native200=%s active=%s target=%s pause=%s frontend=%s")
                        :format(raw_escape and "raw" or "frontend-200", tostring(raw_escape),
                            tostring(native_escape_edge), tostring(active), tostring(target),
                            tostring(paused), tostring(frontend)))
                    -- Route Esc through one P/frontend-199 pulse, with direct
                    -- frontend state as a fallback if GTA does not respond.
                    local accepted = pulse_pause_control()
                    if not accepted then
                        accepted = target and activate_pause_frontend() or deactivate_pause_frontend()
                    end
                    if accepted and same(c) then
                        state.owned = true
                        Q.escape_pending = { at = now, target = target, fallback = false }
                        note("Pause requested",
                            accepted and "Esc routed through P/frontend-199" or "pause request rejected")
                    else
                        state.owned = false
                        note("Pause unavailable", "Esc/P route rejected by native backend")
                    end
                end
                if state.owned and (escape_held or escape_edge) and same(c) then
                    for _, group in ipairs({ 0, 2 }) do
                        invoke_void_detail(N.disable_control, group, 200, true)
                        invoke_void_detail(N.disable_control, group, 202, true)
                    end
                end
                state.held = escape_held
                if not escape_held and not escape_edge then state.owned = false end
            end

            -- Repeat supplies while Tab+C / Tab+V is held, including ragdoll,
            -- fall/get-up, and restricted weapon-wheel states; bypass input_safe().
            for _, kind in ipairs({ "snacks", "armour" }) do
                local flag = kind == "snacks" and "wheel_snacks" or "wheel_armour"
                if is_on(flag) then
                    local held = chord_down(kind)
                    local state = Q.inputs[flag]
                    if not state then
                        state = { held = false, done = false, next = nil, stock = nil, pending_apply = nil }
                        Q.inputs[flag] = state
                    end
                    if not held then
                        state.held = false; state.done = false; state.next = nil; state.stock = nil; state.pending_apply = nil; state.edge_logged = false
                    elseif not state.held then
                        state.held = true; state.done = false; state.next = now; state.stock = nil
                        if not state.edge_logged then
                            state.edge_logged = true
                            log_info(("Supplies input=%s edge=down rawTab=%s key=%s rawChord=%s paused=%s gate=bypassed")
                                :format(kind, tostring(key(0x09)),
                                    tostring(key(kind == "snacks" and 0x43 or 0x56)),
                                    tostring(chord_down(kind)), tostring(paused)))
                        end
                    end
                    if held and not state.done and same(c) then
                        if state.pending_apply then apply_supply_bar(now, c, kind, state) end
                        if not state.pending_apply then
                            if not state.stock or not stock_valid(state.stock) then state.stock = economy(c) end
                            if state.stock then
                                if not state.next or now >= state.next then consume(now, c, kind, state) end
                            else
                                state.next = now + SUPPLY_REPEAT_MS
                                note("Blocked", kind .. ": inventory context unavailable; retrying while held")
                            end
                        end
                    end
                end
            end

            -- Menus must not consume items. An explicitly queued refill may run
            -- while Cherax is open, but never during pause/chat/warnings/loading.
            if not refill_due then
                -- Refill admission runs on its own two-second/manual cadence.
            elseif boolean(N.pause) == false and boolean(N.warning) == false and boolean(N.chat) == false and same(c) then
                refill_tick(now, c)
            else
                if Q.manual_snacks or Q.manual_armour then
                    note("Refill stopped", "pause/chat/warning or local context changed")
                    toast("Refill stopped: return to gameplay and press refill again.", 4000, "warning")
                end
                Q.manual_snacks = false; Q.manual_armour = false; Q.next_refill = now + 2000
            end
        end
    end

    -- Mansion Yoga boost: current Enhanced net_mansion_yoga.c sets bit 10
    -- in Global_2673276.f_3768 on completion, or bit 11 to refresh an already
    -- active bonus. Freemode owns the actual run/swim move-rate override and
    -- expiry. CScript therefore touches only this source-backed request word and
    -- never overwrites a user's persistent Run/Swim multiplier controls.
    Live.YOGA_BOOST_GLOBAL = 2673276 + 3768
    Live.speed_preset = { pending = false, status = "Idle", detail = "" }

    -- The player natives clamp/reject values above 1.49. Cherax's documented
    -- CPlayerInfo properties provide an owned/readable scalar, but bypassing the
    -- run native's positioned outruns normal locomotion and can produce sliding.
    Live.movement_boosts = {}
    Live.movement_boost_fields = {
        run_boost = { "RunSprintSpeedMultiplier", "run_multiplier" },
        swim_boost = { "SwimSpeedMultiplier", "swim_multiplier" }
    }
    function Live.movement_info(owner, allow_stopped)
        if not Live.same_local_owner(owner, allow_stopped) then return nil end
        local ok, info = pcall(function()
            local current = gta.GetLocalPed().PlayerInfo
            if current and current.PlayerPed and current.PlayerPed:GetAddress() == owner.address then return current end
        end)
        if ok and info and Live.same_local_owner(owner, allow_stopped) then return info end
    end

    function Live.restore_movement_boost(key, allow_stopped)
        local o = Live.movement_boosts[key]
        if not o then return true end
        local info = Live.movement_info(o, allow_stopped)
        local released = false
        if info then
            local ok, result = pcall(function()
                -- A different writer has taken over this property: leave its
                -- value intact instead of applying our stale baseline.
                if info[o.field] ~= o.last then return true end
                if Live.same_local_owner(o, allow_stopped) then
                    info[o.field] = o.before; return info[o.field] == o.before
                end
                return false
            end)
            released = ok and result == true
        elseif not Live.same_local_owner(o, allow_stopped) then
            local fresh = Live.local_owner(allow_stopped)
            released = fresh ~= nil or lifecycle_token ~= o.token
        end
        if released then Live.movement_boosts[key] = nil end
        return released
    end

    function Live.restore_movement_boosts(allow_stopped)
        for key in pairs(Live.movement_boosts) do Live.restore_movement_boost(key, allow_stopped) end
        return next(Live.movement_boosts) == nil
    end

    function Live.apply_movement_boosts(pid)
        for key, fields in pairs(Live.movement_boost_fields) do
            if not is_on(key) then
                Live.restore_movement_boost(key)
            else
                local owner = Live.local_owner()
                if owner and Live.protection_bool(0x5E9564D8246B909A, owner.pid) == true
                    and Live.protection_bool(H.IS_PED_DEAD_OR_DYING, owner.ped, true) == false then
                    local info = Live.movement_info(owner)
                    local owned = Live.movement_boosts[key]
                    if owned and not Live.same_local_owner(owned) then
                        Live.movement_boosts[key] = nil; owned = nil
                    end
                    if info then
                        local ok, before = pcall(function() return info[fields[1]] end)
                        if ok and type(before) == "number" and before == before and math.abs(before) < math.huge then
                            local wanted = tonumber(slider_float(fields[2], 1.25)) or 1.25
                            if wanted ~= wanted or math.abs(wanted) == math.huge then wanted = 1.25 end
                            wanted = math.max(1.0, math.min(key == "run_boost" and 1.49 or 20.0, wanted))
                            if not owned then
                                owned = owner; owned.field = fields[1]; owned.before = before
                                Live.movement_boosts[key] = owned
                            end
                            if is_on(key) and Live.same_local_owner(owner) then
                                local wrote, after = pcall(function()
                                    info[fields[1]] = wanted; return info[fields[1]]
                                end)
                                if wrote and after == wanted then owned.last = wanted end
                            end
                        end
                    end
                end
            end
        end
    end

    function Live.queue_speed_preset()
        Live.speed_preset.pending = true
        Live.speed_preset.status, Live.speed_preset.detail = "Queued", "Mansion Yoga boost request"
    end

    function Live.apply_speed_preset(ped)
        local state = Live.speed_preset
        if not state.pending then return end
        state.pending = false
        if not entity_exists(ped) or not invoke_bool(0x9DE624D2FC4B603F) then
            state.status, state.detail = "Unavailable",
                "GTA Online/local character is unavailable; no movement settings changed."
            toast(state.detail, 4500, "warning"); return
        end
        local index = Live.YOGA_BOOST_GLOBAL
        local before = Live.read_global_int(index)
        if before == nil then
            state.status, state.detail = "Unavailable", "Script globals are not ready; no movement settings changed."
            toast(state.detail, 4500, "warning"); return
        end
        local active = (before & (1 << 10)) ~= 0
        local bit = active and 11 or 10
        local expected = before | (1 << bit)
        if expected == before then
            state.status, state.detail = "Already active", "Mansion Yoga boost request is already present."
            toast(state.detail, 3500); return
        end
        local wrote = Live.write_global_int(index, expected)
        local after = Live.read_global_int(index)
        if not wrote or after ~= expected then
            state.status, state.detail = "Failed",
                "Yoga bonus request was not read-back verified; multiplier controls were untouched."
            toast(state.detail, 5000, "warning"); return
        end
        state.status = "Requested"
        state.detail = active and "Requested a source-backed Yoga bonus refresh (bit 11)."
            or "Requested the source-backed Yoga movement bonus (bit 10)."
        toast(state.detail, 4200, "success")
    end

    -- Aim selection is an explicit local request. All target/identity reads and
    -- the Entity* buffer belong to the existing native gameplay frame.
    -- Hashes below are verified against the copied natives_gen9.json database.
    Live.aim = {
        pending = false,
        phase = "idle",
        detail = "Aim at a player, then Select Aimed Player.",
        serial = 0,
        closed = false,
        held = {},
        ptr = 0,
        busy = false,
        hashes = {
            aim = 0x2975C866E6713290,
            kind = 0x8ACD366038D14505,
            player = 0x12534C348C6CB68B,
            index = 0x6C0E2E0125610278,
            driver = 0xBB40DD2270B65366,
            vehicle = 0x9A9112A0FE9A4713,
            seat_free = 0x22AC59A870E6A669,
            chat = 0xB118AF58B5F332A1
        }
    }

    function Live.aim_integer(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge and value % 1 == 0
    end

    function Live.aim_session()
        return module_context and module_context.CScript and module_context.CScript.Session
    end

    function Live.aim_snapshot()
        local s = Live.aim
        return { pending = s.pending, phase = s.phase, detail = s.detail, selected_id = s.selected_id }
    end

    function Live.aim_cancel(reason, close)
        local s = Live.aim
        s.serial = s.serial + 1
        s.pending, s.selected_id = false, nil
        s.phase, s.detail = "cancelled", reason or "Aim selection cancelled."
        if close then s.closed = true end
        -- A yielding host call still owns its buffer until it returns to Tick.
        -- Cooperative DrainUnload services a failed release on gameplay too.
    end

    function Live.aim_request()
        local s = Live.aim
        if not started or s.closed then return false, "Player module is stopped." end
        if s.pending or s.busy or s.ptr ~= 0 then return false, "Aim selection is already pending or cleaning up." end
        local session = Live.aim_session()
        if type(session) ~= "table" or type(session.SelectPlayerIdentity) ~= "function" then
            s.phase, s.detail = "unavailable", "Session identity selection is unavailable."
            s.selected_id = nil
            return false, s.detail
        end
        if not memory or type(memory.AllocInt) ~= "function" or type(memory.WriteInt) ~= "function"
            or type(memory.ReadInt) ~= "function" or type(memory.Free) ~= "function"
            or not Live.Players or type(Live.Players.GetById) ~= "function"
            or not gta or type(gta.HandleToPointer) ~= "function" then
            s.phase, s.detail = "unavailable", "Aim selection memory or identity services are unavailable."
            s.selected_id = nil
            return false, s.detail
        end
        s.serial = s.serial + 1
        s.pending, s.phase, s.detail, s.selected_id = true, "queued", "Aim selection queued for the gameplay frame.", nil
        s.session = session
        s.from_hotkey = false
        return true, s.detail
    end

    function Live.aim_button(feature)
        local s = Live.aim
        if not started or s.closed then return false, "Player module is stopped." end
        -- Host key callbacks may repeat. Latch only this feature's user bindings,
        -- and service release in FrameTick without scanning aimed entities.
        local down = {}
        if feature and type(feature.GetHotkeys) == "function" then
            local ok, keys = pcall(function() return feature:GetHotkeys() end)
            if not ok or type(keys) ~= "table" then return false, "Feature hotkeys are unavailable." end
            if next(keys) ~= nil and type(utils.IsKeyDown) ~= "function" then return false, "Key state is unavailable." end
            for _, key in pairs(keys) do
                if not Live.aim_integer(key) or key <= 0 or key > 255 then return false, "Feature hotkey is invalid." end
                local read, value = pcall(utils.IsKeyDown, key)
                if not read or type(value) ~= "boolean" then return false, "Key state is unavailable." end
                if value then down[key] = true end
            end
        end
        local repeated = false
        for key in pairs(down) do
            if s.held[key] then repeated = true end; s.held[key] = true
        end
        if repeated then return false, "Release the selection hotkey before using it again." end
        if next(down) ~= nil then
            -- GUI.IsOpen is documented and safe outside render. Suppressing the
            -- binding whenever the host menu is open also protects text inputs.
            local gui = deps.GUI
            local ok, open = false, nil
            if gui and type(gui.IsOpen) == "function" then ok, open = pcall(gui.IsOpen) end
            if not ok or open ~= false then return false, "Selection hotkey is suspended while the menu is open." end
        end
        local accepted, detail = Live.aim_request()
        if accepted then s.from_hotkey = next(down) ~= nil end
        return accepted, detail
    end

    function Live.aim_alive(serial)
        local s = Live.aim
        return started and not s.closed and s.pending and s.serial == serial and s.session == Live.aim_session()
    end

    function Live.aim_bool(serial, hash, ...)
        if not Live.aim_alive(serial) then return nil end
        local _, raw, err = invoke_bool_detail(hash, ...)
        if not Live.aim_alive(serial) or err ~= nil then return nil end
        if type(raw) == "boolean" then return raw end
        if raw == 0 or raw == 1 then return raw == 1 end
        return nil
    end

    function Live.aim_int(serial, hash, ...)
        if not Live.aim_alive(serial) then return nil end
        local value, raw, err = invoke_int_detail(hash, ...)
        if not Live.aim_alive(serial) or err ~= nil or not Live.aim_integer(raw)
            or not Live.aim_integer(value) then
            return nil
        end
        return value
    end

    function Live.aim_address(handle)
        local object = gta.HandleToPointer(handle)
        local address = object and object:GetAddress()
        return Live.aim_integer(address) and address > 0 and address or nil
    end

    function Live.aim_capture(serial, target)
        local hashes = Live.aim.hashes
        if not Live.aim_alive(serial) or not Live.aim_integer(target) or target <= 0 or not entity_exists(target) then
            return nil, "No current entity is under your aim."
        end
        local kind = Live.aim_int(serial, hashes.kind, target)
        local ped = target
        if kind == 2 then
            if Live.aim_bool(serial, hashes.seat_free, target, -1, false) ~= false then
                return nil, "The aimed vehicle has no verified seated driver."
            end
            ped = Live.aim_int(serial, hashes.driver, target, -1, false)
        elseif kind ~= 1 then
            return nil, "Aim at a player or an occupied player's vehicle."
        end
        if not Live.aim_integer(ped) or ped <= 0 or not entity_exists(ped)
            or Live.aim_int(serial, hashes.kind, ped) ~= 1 or Live.aim_bool(serial, hashes.player, ped) ~= true then
            return nil, "The aimed target is not a verified player ped."
        end
        local id = Live.aim_int(serial, hashes.index, ped)
        if not Live.aim_integer(id) or id < 0 or id > 31 or id == local_player_id()
            or not player_available(id) or player_ped(id) ~= ped then
            return nil, "The aimed player is unavailable or their ped changed."
        end
        if kind == 2 and Live.aim_int(serial, hashes.vehicle, ped, false) ~= target then
            return nil, "The aimed vehicle's driver changed."
        end
        local player = Live.Players.GetById(id)
        local info = player and player:GetGamerInfo()
        local rid, key = info and info.RockstarId, info and info.HostKey
        local address, cxn = player and player:GetAddress(), player and player.CxnId
        if not Live.aim_integer(rid) or rid <= 0 or not Live.aim_integer(key) or key == 0
            or not Live.aim_integer(address) or address <= 0 or not Live.aim_integer(cxn) then
            return nil, "The aimed player's fresh connection identity is unavailable."
        end
        local target_address, ped_address = Live.aim_address(target), Live.aim_address(ped)
        local target_model = Live.aim_int(serial, H.GET_ENTITY_MODEL, target)
        local ped_model = Live.aim_int(serial, H.GET_ENTITY_MODEL, ped)
        if not target_address or not ped_address or not target_model or target_model == 0
            or not ped_model or ped_model == 0 or not Live.aim_alive(serial) then
            return nil, "The aimed entity's current instance could not be verified."
        end
        return {
            id = id,
            rid = rid,
            host_key = key,
            cxn = cxn,
            address = address,
            ped = ped,
            kind = kind,
            target_address = target_address,
            ped_address = ped_address,
            target_model = target_model,
            ped_model = ped_model
        }
    end

    function Live.aim_release()
        local s = Live.aim
        if s.ptr == 0 then return true end
        local ok, result = pcall(memory.Free, s.ptr)
        if ok and result ~= false then
            s.ptr = 0; return true
        end
        s.detail = "Aim selection buffer release failed; gameplay cleanup is pending."
        return false
    end

    function Live.aim_resolve(serial)
        local s = Live.aim
        if not Live.aim_alive(serial) then return false, "Aim selection cancelled: Session changed." end
        if s.from_hotkey then
            local gui = deps.GUI
            local read, open = false, nil
            if gui and type(gui.IsOpen) == "function" then read, open = pcall(gui.IsOpen) end
            if not read or open ~= false then return false, "Selection hotkey is suspended while the menu is open." end
            if Live.aim_bool(serial, s.hashes.chat) ~= false then
                return false, "Selection hotkey is suspended while game chat is active or unreadable."
            end
        end
        local ptr = memory.AllocInt()
        if not Live.aim_integer(ptr) or ptr <= 0 then return false, "Aim output buffer allocation failed." end
        s.ptr = ptr
        if not Live.aim_alive(serial) then return false, "Aim selection cancelled." end
        if memory.WriteInt(ptr, 0) == false then return false, "Aim output buffer could not be initialized." end
        local found = Live.aim_bool(serial, s.hashes.aim, local_player_id(), ptr)
        if found ~= true then
            return false, found == false and "No entity is under your aim within weapon range."
                or "Aim lookup failed or returned an unreadable BOOL."
        end
        local target = memory.ReadInt(ptr)
        local first, why = Live.aim_capture(serial, target)
        if not first then return false, why end
        local fresh, detail = Live.aim_capture(serial, target)
        if not fresh then return false, detail end
        for key, value in pairs(first) do
            if fresh[key] ~= value then
                return false,
                    "Aim selection cancelled: player connection or entity instance changed."
            end
        end
        if not Live.aim_alive(serial) then return false, "Aim selection cancelled." end
        local ok, result = s.session.SelectPlayerIdentity({ id = fresh.id, rid = fresh.rid, host_key = fresh.host_key })
        if ok ~= true then
            return false,
                type(result) == "string" and result or "Session refused the current player identity."
        end
        return true, type(result) == "string" and result or "Aimed player selected.", fresh.id
    end

    function Live.aim_tick()
        local s = Live.aim
        if s.busy then return end
        for key in pairs(s.held) do
            local ok, down = pcall(utils.IsKeyDown, key)
            if ok and down == false then s.held[key] = nil end
        end
        if s.ptr ~= 0 and not Live.aim_release() then return end
        if not s.pending then return end
        local serial = s.serial
        s.busy, s.phase = true, "resolving"
        local ran, ok, detail, id = pcall(Live.aim_resolve, serial)
        s.busy = false
        if s.serial == serial then
            s.pending = false
            s.phase = ran and ok == true and "selected" or "failed"
            s.detail = ran and detail or "Aim selection failed: native, buffer or identity service error."
            s.selected_id = ran and ok == true and id or nil
        end
        Live.aim_release()
    end

