                or is_on("player_keep_headgear") or not Live.headgear.Clean()
                or is_on("movement_refinement") or is_on("disable_action_mode") or is_on("peds_ignore") or
                State.peds_ignore.enabled
                or is_on("godmode") or next(Live.protection.studios) ~= nil or Live.protection.entity ~= nil or
                Live.protection.player ~= nil
                or is_on("run_boost") or is_on("swim_boost") or next(Live.movement_boosts) ~= nil
                or is_on("no_ragdoll") or is_on("disable_stumble") or Live.slope_observer.active or next(Live.slope_buffers) ~= nil or
                Live.ragdoll_suppression ~= nil or is_on("no_critical_hits") or is_on("no_wanted")
