        RearmRuntimeState = function(reason)
            Live.stop_auto_tp("Runtime rearm")
            if not Live.cancel_tear_gas_toggle("Runtime rearm", true) then
                return false, "Gas chamber trap cleanup request failed."
            end
            local tear_gas_rearm_revision = Live.tear_gas_revision
            Live.cancel_baller_toggle("Runtime rearm", true)
            local screen_ok, screen_why = Live.rearm_scripted_screens()
            if not screen_ok then return false, screen_why end
            Live.local_exit_stopped = false
            Live.ghost_cancel("Runtime rearm", false)
            Live.ghost_retiring = false
            Live.property_exit_stopped = false
            Live.property_exit_guard.Reset()
            Live.aim_cancel("Aim selection cancelled by runtime rearm.")
            local why = reason or "explicit runtime rearm"
            Live.lester_ride.Cancel(nil, why)
            if Live.player_setpieces then Live.player_setpieces.Cancel(nil, why) end
                if Live.vehicle_chaos then Live.vehicle_chaos.Cancel() end
            Live.qol.reset(why, false)
            Live.cleanup_super_melee("runtime rearm:" .. tostring(why))
            State.super_melee.last_scan_ms = -100000
            State.super_melee.prestrike, State.super_melee.prestrike_ms = nil, nil
            local baller_ok, baller_why = Live.rearm_baller_toggle()
            if not baller_ok then return false, baller_why end
            if Live.tear_gas_revision ~= tear_gas_rearm_revision then
                return false, "Runtime rearm was superseded by a newer Gas chamber trap stop."
            end
            return Live.rearm_tear_gas_toggle()
        end,
