-- Host callback objects are not guaranteed to be ordinary Lua arrays. These
-- states deliberately separate proven malformed data from an ABI shape that
-- CScript cannot safely enumerate through the documented Cherax surface.
local SYNC_INSPECTABLE_VALID = "INSPECTABLE_VALID"
