local module_context, started, __public_binding
local __public_stopped, __public_teardown = true, false

-- Public Free has no active Protections feature license. Read-only status
-- and cleanup continue working to avoid leaving stale local state behind.
local function __public_bind(context)
    if __public_binding and __public_binding.context == context and module_context == context then return end
    local cs = context and context.CScript
    local auth = type(cs) == "table" and cs.Entitlements
    local allowed = type(auth) == "table" and auth.IsAllowed
    assert(type(cs) == "table" and cs.DistributionMode == "public"
        and type(allowed) == "function", "Public protection authorization is required")
    __public_binding = {context=context, allowed=allowed}
    __public_stopped = false
end
local function __public_live(binding, require_started)
    return binding ~= nil and binding == __public_binding
        and module_context == binding.context and not __public_stopped and not __public_teardown
        and (not require_started or started == true)
end
local function public_protections_allowed(binding, require_started)
    if not __public_live(binding, require_started) then return false end
    local ok, allowed = pcall(binding.allowed, "modules.protections", "feature")
    return ok and allowed == true and __public_live(binding, require_started)
end
local function __public_denied_handler(name)
    if name == "CAN_APPLY_NODE_DATA" or name == "SHOULD_COLLIDE" then return true end
    if name == "SCRIPTED_GAME_EVENT" then return false end
    return nil
end

local PREMIUM_API_METHODS = {
    SelfIsolationEnabled = true,
    QueueCameraRecovery = true, BlockSource = true,
    IgnoreSourceAlerts = true, QueueLeaveSession = true,
    QueueHostRemoval = true, ExportEvidence = true,
    ClearSuspicion = true, SetSpawnRadius = true,
    FastTick = true, ClearIsolation = true,
    LogStatus = true, LogDetectionReport = true,
}
local function protect_public_methods(api)
    local binding = __public_binding
    for name in pairs(PREMIUM_API_METHODS) do
        local original = api[name]
        if type(original) == "function" then
            api[name] = function(...)
                if not public_protections_allowed(binding, false) then
                    return false, "Donator-only Protections action."
                end
                return original(...)
            end
        end
    end
end

