        State.last_incident_ms = -100000
        State.orbital = {
            available = false, active = {}, local_active = false, research_only = true,
            last_scan_ms = -100000,
            last_error = "Orbital mapping unavailable: runtime validation did not confirm the operator/target relationship.",
