        if needed and identifier == nil then
            local event = eLuaEvent[name]
            if event == nil then
                success = false
            else
                local binding = __public_binding
                local guarded = function(...)
                    if not public_protections_allowed(binding, true) then return __public_denied_handler(name) end
                    local frame = public_api and public_api.BeginIngress(name, (select(1, ...)))
                    local ok, result = pcall(callback, ...)
                    if public_api then pcall(public_api.EndIngress, frame, name, ok, result) end
                    if ok then return result end
                    if public_api and type(public_api.HandlerFailure) == "function" then
                        pcall(public_api.HandlerFailure, name, result)
                    end
                    if name == "SCRIPTED_GAME_EVENT" then return false end
                    if name == "CAN_APPLY_NODE_DATA" or name == "SHOULD_COLLIDE" then return true end
                end
                local registered, id = pcall(EventMgr.RegisterHandler, event, guarded)
                if registered and type(id) == "number" then handler_ids[name] = id else success = false end
            end
        end
    end
    handlers_registered = next(handler_ids) ~= nil
    return success
end
reconcile_event_handlers = register_event_handlers

local function remove_event_handlers()
    if EventMgr and type(EventMgr.RemoveHandler) == "function" then
        for name, identifier in pairs(handler_ids) do
            local ok, result = pcall(EventMgr.RemoveHandler, identifier)
            if ok and result ~= false then handler_ids[name] = nil end
        end
    end
    handlers_registered = next(handler_ids) ~= nil
    return not handlers_registered
end

local function publish_state(context)
    local root = context.State.Protections
    if type(root) ~= "table" then
        root = {}
        context.State.Protections = root
    end
    root.MigrationPhase = Module.MigrationPhase
    root.Runtime = State
    root.Started = started
    root.Bound = bound
    root.RegisteredCount = State.registered_count
end

function Module.BindCompatibility(bindings)
    assert(not __public_teardown, "Public protection teardown is in progress")
    if not module_context then error("protections module must initialize before compatibility binding", 2) end
    if bound then return public_api end
        dependencies = bindings or {}
        public_api = create_protection_system(dependencies)
        protect_public_methods(public_api)

        if not register_event_handlers() then
            public_api = nil
            dependencies = nil

            error(
                "protections module could not register required event handlers",
                2
            )
        end

        bound = true
