end

function Module.Init(context)
    assert(not __public_teardown, "Public protection teardown is in progress")
    if type(context) ~= "table" or type(context.State) ~= "table"
        or type(context.CScript) ~= "table" or type(context.Modules) ~= "table" then
        error("modules.protections received an invalid context")
    end
    if module_context and module_context ~= context then
        error("modules.protections is already initialized by another context")
    end
    __public_bind(context)
    module_context = context
    context.Modules.Protections = Module
    publish_state(context)
end

function Module.Start()
    assert(not __public_teardown, "Public protection teardown is in progress")
    if not module_context then error("modules.protections started before initialization") end
    __public_stopped = false
    State.shutdown_complete = false
    started = true
    if bound and not register_event_handlers() then
        error("protections module could not register active event dependencies", 2)
    end
