local function __public_stop_implementation()
    -- Quiesce callback entry before any diagnostics or state cleanup so an
    -- in-flight unload cannot call into destroyed CScript state.
    started = false
    local restored, detail = true, nil
    if public_api and type(public_api.Shutdown) == "function" then
        local ok, result, err = pcall(public_api.Shutdown)
        restored, detail = ok and result == true, ok and err or result
    end
