-- Tracks one explicitly requested sale using local observations only.
-- CREDIT_CORRELATED is not a server transaction receipt or persistence claim.
local Module={Name="modules.sale_settlement",MigrationPhase="17.75"}
local function integer(v,lo,hi)
    return type(v)=="number" and v==v and v%1==0 and v>=lo and v<=hi
end
local function total(s)
    if not integer(s.bank,-2147483648,2147483647) or not integer(s.wallet,-2147483648,2147483647) then return nil end
    return s.bank+s.wallet
end
local done={CREDIT_CORRELATED=true,AMBIGUOUS=true,CANCELLED=true,TIMED_OUT=true}
function Module.New(options)
    options=options or {}
    local settle_ms=integer(options.settle_ms,250,30000) and options.settle_ms or 2000
    local timeout_ms=integer(options.timeout_ms,1000,1800000) and options.timeout_ms or 1800000
    local state="IDLE"
    local request,scope,baseline,started,last_time,sale,units,variant,success_at,credit_at,stable_since
    local result={payment_verified=false,transaction_receipt=false,receipts=0}
    local api={}
    local function finish(status,why)
        state=status;result.reason=why;result.completed_ms=last_time
    end
    function api.Start(wanted,before,now)
        if state~="IDLE" and not done[state] then return false,"A sale is already being tracked." end
        if type(wanted)~="table" or type(before)~="table" or not integer(now,0,9007199254740991) then
            return false,"Invalid sale request."
        end
        if type(wanted.operation_id)~="string" or #wanted.operation_id<1 or #wanted.operation_id>128
            or not integer(wanted.expected_amount,1,2147483647) then return false,"A quoted payout and operation ID are required." end
        if before.context_valid~=true or before.online~=true or not integer(before.context_epoch,1,2147483647)
            or (before.character_slot~=0 and before.character_slot~=1) or total(before)==nil then
            return false,"Character or balance unavailable."
        end
        if before.thread_count~=0 or before.bunker_mission~=0 or not integer(before.bunker_stock,1,1000) then
            return false,"Begin before the sale starts, with saleable stock."
        end
        request={operation_id=wanted.operation_id,expected_amount=wanted.expected_amount}
        scope={epoch=before.context_epoch,slot=before.character_slot}
        baseline=total(before);started=now;last_time=now
        sale,units,variant,success_at,credit_at,stable_since=nil,nil,nil,nil,nil,nil
        result={operation_id=request.operation_id,expected_amount=request.expected_amount,
            payment_verified=false,transaction_receipt=false,receipts=0,amount=0}
        state="WAIT_SALE";return true
    end
    function api.StartActive(wanted,current,now)
        if state~="IDLE" and not done[state] then return false,"A sale is already being tracked." end
        if type(wanted)~="table" or type(current)~="table" or not integer(now,0,9007199254740991) then
            return false,"Invalid active-sale request."
        end
        if type(wanted.operation_id)~="string" or #wanted.operation_id<1 or #wanted.operation_id>128
            or not integer(wanted.expected_amount,1,2147483647) then
            return false,"A quoted payout and operation ID are required."
        end
        if current.context_valid~=true or current.online~=true or not integer(current.context_epoch,1,2147483647)
            or (current.character_slot~=0 and current.character_slot~=1) or total(current)==nil then
            return false,"Character or balance unavailable."
        end
        if current.local_status~="shape_valid" or current.thread_count~=1
            or not integer(current.bunker_mission,1,2147483647)
            or not integer(current.sale_epoch,1,2147483647)
            or not integer(current.sale_variant,14,19)
            or not integer(current.delivery_units,1,8)
            or current.network_state~=1 or not integer(current.phase,10,12) or current.outcome~=0
            or not integer(current.destroyed_units,0,current.delivery_units) or current.destroyed_units~=0 then
            return false,"Current Bunker sale is not an undamaged active delivery controller."
        end
        request={operation_id=wanted.operation_id,expected_amount=wanted.expected_amount}
        scope={epoch=current.context_epoch,slot=current.character_slot}
        baseline=total(current);started=now;last_time=now
        sale=current.sale_epoch;variant=current.sale_variant;units=current.delivery_units
        success_at,credit_at,stable_since=nil,nil,nil
        result={operation_id=request.operation_id,expected_amount=request.expected_amount,
            sale_epoch=sale,variant=variant,units=units,
            payment_verified=false,transaction_receipt=false,receipts=0,amount=0}
        state="DELIVERING";return true
    end
    function api.Stop(reason)
        if state~="IDLE" and not done[state] then finish("CANCELLED",reason or "Stopped by user.") end
    end
    function api.Observe(s,now)
        if state=="IDLE" or done[state] then return end
        if not integer(now,0,9007199254740991) or now<last_time then finish("CANCELLED","Clock moved backwards.");return end
        last_time=now
