            if not integer(s.sale_epoch,1,2147483647) then finish("AMBIGUOUS","Sale identity is missing.");return end
            if sale and sale~=s.sale_epoch then finish("AMBIGUOUS","A different sale controller appeared.");return end
            if not sale then
                if not integer(s.sale_variant,14,19) or not integer(s.delivery_units,1,8) then
                    finish("AMBIGUOUS","Unsupported sale shape.");return
                end
                sale=s.sale_epoch;variant=s.sale_variant;units=s.delivery_units
                result.sale_epoch=sale;result.variant=variant;result.units=units;state="DELIVERING"
            end
            if s.sale_variant~=variant or s.delivery_units~=units then finish("AMBIGUOUS","Sale identity or unit count changed.");return end
            if not integer(s.destroyed_units,0,units) or s.destroyed_units>0 then
                finish("AMBIGUOUS","Full-cargo payment cannot be inferred after cargo loss.");return
            end
            if s.phase==14 and s.outcome==3 then
                local per_unit=(variant==14 or variant==16 or variant==19) and 5 or 1
                if s.delivered_units~=units or s.delivery_total~=units*per_unit then
                    finish("AMBIGUOUS","Terminal result does not describe every delivery.");return
                end
                if not success_at then success_at=now;result.success_ms=now end
