                finish("AMBIGUOUS","The controller did not report the expected success result.");return
            end
        elseif sale and not success_at and s.thread_count==0 then
            finish("AMBIGUOUS","Controller exited without an observed full-delivery success.");return
        end
        if not success_at then
            if delta and delta~=0 then finish("AMBIGUOUS","Balance changed before this sale's successful result.") end
