        end
        if delta==nil then stable_since=nil;state="WAIT_CREDIT";return end
        if delta~=0 and delta~=request.expected_amount then
            finish("AMBIGUOUS","Balance change differs from the captured quote.");return
        end
        if delta==0 then stable_since=nil;state="WAIT_CREDIT";return end
        credit_at=credit_at or now
        if s.store_session_valid~=true or s.store_refresh_pending~=false or s.bunker_mission~=0
            or s.bunker_stock~=0 or s.thread_count~=0 then
