  menu.SetApplyAllowed(false);guard.SetApplyAllowed(false)
  menu.SetEnabled(false)
  if drain then menu.Restore() else menu.Tick(now)end
  if menu.Snapshot().cleanup_debt==0 then
   guard.SetEnabled(false)
   if drain then guard.Restore() else guard.Tick(now)end
  end
  return menu.Snapshot().cleanup_debt==0 and guard.Snapshot().cleanup_debt==0
 end
 function obj.SetEnabled(a,b)
  local value=b;if value==nil then value=a end
  if type(value)~='boolean'then return false,'Expected boolean request'end
  if value==requested and not failed then return true end
  epoch=epoch+1;requested=value;failed=nil
