   -- If its allocation disappears, withdraw admission while retaining the
   -- uncertain old lease; a script-local token is never proof of deallocation.
   menu.SetApplyAllowed(g.applied)
   if g.cleanup_debt>0 and not g.available then
    failed='Freemode instance unavailable; menu admission withdrawn'
    cleanup(now,true);return false
   end
   menu.Tick(now)
   if serial~=epoch then return false end
   local m=menu.Snapshot()
   if failed_view(m)then failed=m.reason;cleanup(now,true);return false end
   if m.available and g.available then
