  return requested and not failed or menu.Snapshot().cleanup_debt>0 or guard.Snapshot().cleanup_debt>0
 end
 function obj.Snapshot()
  local m,g=menu.Snapshot(),guard.Snapshot()
  local applied=requested and not failed and m.applied and g.applied or false
  local debt=m.cleanup_debt+g.cleanup_debt
  local phase,reason
  if failed then phase=debt>0 and 'Restoring' or 'Failed';reason=failed
  elseif not requested then phase=debt>0 and 'Restoring' or 'Disabled';reason=debt>0 and 'Owned script restoration pending' or 'Disabled'
  elseif applied then phase='Applied locally';reason='Local menu availability and extra organization admission active'
  elseif not m.available then phase=m.phase;reason='Interaction menu: '..tostring(m.reason)
  elseif not g.available then phase=g.phase;reason='Freemode: '..tostring(g.reason)
  elseif not g.applied then phase=g.phase;reason='Freemode: '..tostring(g.reason)
  else phase=m.phase;reason='Interaction menu: '..tostring(m.reason)end
  return {enabled=requested,requested=requested,armed=requested,pending=requested and not applied and not failed or not requested and debt>0,
   available=m.available and g.available,applied=applied,menu_gates_applied=applied,
   admission_applied=applied,suspension_guard_applied=g.applied,cleanup_debt=debt,
   backend='enhanced-interaction',scope='local-menu-and-extra-organization',phase=phase,reason=reason,menu_reason=reason,
   registration_verified=false,execution_verified=false,access_only=false,faulted=failed~=nil,
   scans=m.scans+g.scans,resources={am_pi_menu=m,freemode=g},
