end

-- Supplied files are unwrapped RSC resource images (0x50000000 system pointers),
-- not compressed RSC7 containers. Reject containers rather than guessing a header.
function M.DecodeResource(blob)
 assert(type(blob)=='string' and #blob>=128,'invalid resource image')
 local function u32(o) assert(o+4<=#blob,'truncated u32');return string.unpack('<I4',blob,o+1)end
