        local owner, debt, next_tick, last_tick = nil, false, -math.huge, nil
        local reason = 'Off.'
        local api={}
        local function token() return host.ScriptLocal.GetPtr(HASH,0) end
        local function read_bytes(address,count)
            local parts,offset={},0
            while offset<count do
                local width=math.min(4,count-offset)
                if not owner or token()~=owner.token then return table.concat(parts),false end
                local ok,value=false,nil
                if width==4 and type(host.Memory.ReadUInt)=='function' then
                    ok,value=pcall(host.Memory.ReadUInt,address+offset)
                    ok=ok and integer(value)and value>=0 and value<=0xffffffff
                    if token()~=owner.token then return table.concat(parts),false end
                end
