local function require_binding(name, value)
    if value == nil then error("session compatibility binding missing " .. name, 3) end
    return value
end

local function reset_roster_state()
    selection_revision = selection_revision + 1
    spoof_generation = spoof_generation + 1
    State.rows = {}
