    local function read_global(index)
        if not (script_global and type(script_global.GetInt) == "function") then return nil end
        if type(script_global.AreValid) == "function" then
            local ok, valid = pcall(script_global.AreValid)
            if not ok or valid ~= true then return nil end
        end
        local ok, value = pcall(script_global.GetInt, index)
        return ok and tonumber(value) or nil
    end

    local function write_global(index, value, current)
        if not (script_global and type(script_global.SetInt) == "function") then
            return false, "Cherax ScriptGlobal.SetInt is unavailable."
        end
        if type(script_global.AreValid) == "function" then
            local ok, valid = pcall(script_global.AreValid)
            if not ok or valid ~= true then return false, "Script globals are not ready." end
        end
        if current and not current() then return false, "Operation no longer current." end
        local ok, result = pcall(script_global.SetInt, index, math.floor(tonumber(value) or 0))
        if not ok or result == false then return false, tostring(result or "write rejected") end
        local observed = read_global(index)
        if observed ~= math.floor(tonumber(value) or 0) then
            return false, ("read-back mismatch (%s)"):format(tostring(observed))
        end
        return true
    end

    local warning_hashes
    local function session_warning_hash()
        if not warning_hashes then
            warning_hashes = {}
            for _, label in ipairs(SESSION_WARNING_LABELS) do
                local ok, hash = pcall(utils.Joaat, label)
                if ok and type(hash)=="number" and hash==hash and hash%1==0
                    and hash>=-2147483648 and hash<=4294967295 then
                    warning_hashes[hash & 0xFFFFFFFF] = label
                end
            end
        end
        local ok, hash = pcall(invoke_int, SESSION_WARNING_HASH_NATIVE)
        if not ok or type(hash)~="number" or hash~=hash or hash%1~=0
            or hash< -2147483648 or hash>4294967295 then return nil end
        hash = hash & 0xFFFFFFFF
        if hash==0 or EXIT_WARNING_HASHES[hash] then return nil end
        return hash
    end

    -- Track input admission separately from warning closure. Use the BOOL ABI,
    -- normalize integer BOOLs, and preserve unavailable reads.
    local function confirmation_bool(hash, ...)
        if type(hash) ~= "number" then return nil end
        if type(deps.invoke_bool_detail) == "function" then
            local ok, value, raw, err = pcall(deps.invoke_bool_detail, hash, ...)
            if not ok or err ~= nil then return nil end
            if type(raw) == "boolean" then return raw end
            if type(raw) == "number" and raw == raw then return raw ~= 0 end
            return nil
        end
        local ok, value = pcall(invoke_bool, hash, ...)
        if not ok then return nil end
        if type(value) == "boolean" then return value end
        if type(value) == "number" and value == value then return value ~= 0 end
        return nil
    end

    local function maintain_auto_accept_confirmation(now)
        local state = State.confirmation
        if not is_on("auto_accept_confirmation") then
            if state.active then State.confirmation = new_confirmation_state() end
            return
        end
        now = tonumber(now) or now_ms()
        local warning_active = confirmation_bool(H.IS_WARNING_MESSAGE_ACTIVE)
        local hash = warning_active == true and session_warning_hash() or nil
        if not hash then
            if state.active then
                -- Disappearance may also be a manual dismissal. Do not label it
                -- an auto-accepted transition solely from an input call.
                log_info(("AutoAccept outcome=%s hash=%08X elapsedMs=%d presses=%d releases=%d queued=%d rejected=%d")
                    :format(warning_active == false and "warning-closed-observed" or "warning-changed-or-unreadable",
                        state.message_hash, math.max(0, now-state.detected_at), state.presses,
                        state.releases, state.queued_calls, state.rejected_calls))
                State.confirmation = new_confirmation_state()
            end
            return
        end
        -- maintransition.c func_1046 reason 5: JOAAT("BAIL_BLACKLIST")=0x2A0FA76F.
        -- Record the displayed reason before Auto Accept can close it. This is
        -- an observed warning, not proof of a core rejoin attempt or its outcome.
        if hash == 0x2A0FA76F and (not state.active or state.message_hash ~= hash) then
            State.last_external_failure = {hash=hash,observed_ms=now,label="BAIL_BLACKLIST",
                message="GTA reported a vote kick from this session."}
        end
        if not state.active or state.message_hash ~= hash then
            state = new_confirmation_state()
            State.confirmation = state
            state.active, state.message_hash, state.detected_at = true, hash, now
        end
        local function current()
            return started and State.confirmation == state and state.active
                and is_on("auto_accept_confirmation")
                and confirmation_bool(H.IS_WARNING_MESSAGE_ACTIVE) == true
                and session_warning_hash() == hash
        end
        if not current() then return end
        state.frame_count = state.frame_count + 1
        -- Close Cherax so GTA's warning receives keyboard input. Leave it closed afterward.
        local gui = deps.GUI
        if not state.menu_attempted and gui and type(gui.IsOpen) == "function"
            and type(gui.Toggle) == "function" then
            state.menu_attempted = true
            local ok, opened = pcall(gui.IsOpen)
            if ok and opened == true and current() then
                pcall(gui.Toggle)
                local read_ok, after = pcall(gui.IsOpen)
                state.menu_closed = read_ok and after == false
            end
        end
        if not current() then return end
        local ready = confirmation_bool(H.IS_WARNING_MESSAGE_READY_FOR_CONTROL)
        if not current() then return end
        state.ready_seen = state.ready_seen or ready == true
        if state.frame_count == 1 then
            log_info(("AutoAccept detected=%s ready=%s menuClosed=%s backend=PAD-0+2-explicit-edges")
                :format(warning_hashes[hash] or ("%08X"):format(hash), tostring(ready), tostring(state.menu_closed)))
        end
        if now-state.detected_at >= WARNING_STUCK_MS and not state.stall_logged then
            state.stall_logged = true
            log_warn(("AutoAccept warning still open hash=%08X readySeen=%s queued=%d rejected=%d; continuing rate-limited retries, not reporting success.")
                :format(hash, tostring(state.ready_seen), state.queued_calls, state.rejected_calls))
        end
        -- Respect GTA's admission gate. A not-ready frame consumes no attempt.
        -- If it becomes unready after a submitted press, finish only its release.
        if state.phase == "press" and (ready ~= true or now < state.next_cycle_ms) then return end
        local value = state.phase == "press" and 1.0 or 0.0
        local admitted = false
        -- PAD0 covers the game input path; PAD2 covers the frontend path. Only
        -- Accept is enabled, and only while this exact non-exit warning exists.
        for _, group in ipairs({0, FRONTEND_CONTROL_GROUP}) do
            if not current() then return end
            if type(H.ENABLE_CONTROL_ACTION) == "number" then
                pcall(invoke_void, H.ENABLE_CONTROL_ACTION, group, INPUT_FRONTEND_ACCEPT, true)
            end
            if not current() then return end
            local accepted = confirmation_bool(H.SET_CONTROL_VALUE_NEXT_FRAME,
                group, INPUT_FRONTEND_ACCEPT, value)
            if State.confirmation ~= state then return end
            if accepted == true then state.queued_calls = state.queued_calls + 1; admitted = true
            else state.rejected_calls = state.rejected_calls + 1 end
        end
        if not current() then return end
        if not admitted then
            -- A rejected call must not spend a press or advance the edge state.
            if now-state.detected_at >= WARNING_STUCK_MS then state.next_cycle_ms = now+WARNING_STUCK_RETRY_MS end
            return
        end
        state.phase_frames = state.phase_frames + 1
        -- Start with the fastest down/up pair. A stubborn warning gets a
        -- two-frame hold/up pair after four cycles, accommodating input sampling
        -- order without inserting a delay into the normal successful case.
        local frames = state.presses >= 4 and 2 or 1
        if state.phase_frames < frames then return end
        state.phase_frames = 0
        if state.phase == "press" then
            state.presses = state.presses + 1
            state.phase = "release"
        else
            state.releases = state.releases + 1
            state.phase = "press"
            state.next_cycle_ms = now-state.detected_at >= WARNING_STUCK_MS
                and now+WARNING_STUCK_RETRY_MS or now
        end
    end

    local function phone_string(index)
        if not script_global or type(script_global.GetString) ~= "function" then return nil end
        local ok, value = pcall(script_global.GetString, index)
        return ok and type(value) == "string" and value or nil
    end

    local function phone_classification(kind)
        local counts = State.invite_filter.classifications
        counts[kind] = math.min(1000000, (counts[kind] or 0) + 1)
    end

    local function phone_filter_layout()
        -- TU1.73 Enhanced corpus: VM array headers independently identify the
        -- SMS and both invite queues. Never write an adjacent build's globals.
        if type(deps.invoke_string) ~= "function"
            or deps.invoke_string(0xFCA9373EF340AC0A) ~= "1.73"
            or read_global(114990 + 14150) ~= PHONE_SMS_COUNT
            or read_global(2622518) ~= 12 or read_global(2624668) ~= 12
            or read_global(1845347) ~= 32 then return false end
        return invoke_bool(H.NETWORK_IS_SESSION_STARTED) == true
    end

    local function sms_classification(base)
        local sender, label = read_global(base + 17), phone_string(base)
        if not sender or not label then return "OTHER" end
        -- freemode func_22062/24603: real incoming gamer-handle texts use the
        -- null character145 and the TMLR<session player> label, not NPC senders.
        local player = sender == 145 and tonumber(label:match("^TMLR(%d+)$")) or nil
        if player and player >= 0 and player <= 31 and player ~= local_player_id() then
            return "PLAYER_DIRECT_TEXT"
        end
        if sender < 0 or sender > 223 or sender % 1 ~= 0 then return "OTHER" end
        local texture = phone_string(2349 + 1 + sender * 29 + 7)
        if texture == "CHAR_SOCIAL_CLUB" then return "SYSTEM_CRITICAL" end
        if sender == 145 then return "OTHER" end
        return "NPC_TEXT"
    end

    -- Queue admission flags cannot retract a feed item already posted by GTA.
    -- Remove only the row-owned handle, with a fresh row identity check; never
    -- flush the shared feed (which also contains direct player messages).
    -- Source: cellphone_controller func80 / freemode func11194 (+16),
    -- freemode func13731 (+26), and func16387 (+54).
    local function remove_phone_feed(index, current)
        local handle = read_global(index)
        if type(handle) ~= "number" or handle % 1 ~= 0 or handle < 0
            or type(deps.invoke_void_detail) ~= "function" or not current() then return false end
        local ok, accepted, _, err = pcall(deps.invoke_void_detail, 0xBE4390CB40B3E627, handle)
        if not ok or accepted ~= true or err ~= nil then return false end
        -- Invalidate the retired handle only if the same row still owns it;
        -- this prevents a later filter pass removing a recycled feed ID.
        return write_global(index, -1, function() return current() and read_global(index) == handle end)
    end

    local function reject_npc_sms(index, character, pending)
        if index < 0 or index >= PHONE_SMS_COUNT or index % 1 ~= 0 then return end
        local base = 114990 + 14150 + 1 + index * 104
        if read_global(base + 24) == 0 then return end
        local kind = sms_classification(base)
        phone_classification(kind)
        if kind ~= "NPC_TEXT" then return end
        local sender, label = read_global(base + 17), phone_string(base)
        local function current()
            return started and is_on("block_automated_job_invites")
                and read_global(base + 17) == sender and phone_string(base) == label
                and read_global(21666) == character
        end
        if pending then
            local flags = read_global(9502)
            if type(flags) ~= "number" or flags % 1 ~= 0 then return end
            -- cellphone_controller func_77 consumes bits7/1 BEFORE vibration,
            -- sound and feed construction. Clear only this queued NPC message.
            if not write_global(9502, flags & (~((1 << 7) | (1 << 1))), function()
                return current() and read_global(24108) == index and read_global(9502) == flags
            end) then return end
        end
        remove_phone_feed(base + 16, current)
        if write_global(base + 24, 0, current) then
            write_global(base + 99 + 1 + character, 0, current)
            State.invite_filter.removed = State.invite_filter.removed + 1
        end
    end

    local function retire_filtered_invite_indicator(base,field,current,normal)
        -- Same retired marker and counter branch used by freemode's own
        -- Decrement_New_Invites_Indicator. Marking first prevents a second
        -- decrement when GTA later compacts the expired row.
        if not current() then return false end
        local active,retired=read_global(base),read_global(base+field)
        if active==0 or retired==1 then return true end
        if active~=1 or retired~=0 then return false end
        if normal then
            local admitted=read_global(base+2)
            if admitted==0 then return true end
            if admitted~=1 then return false end
        end
        local count=read_global(24103)
        if type(count)~="number" or count%1~=0 or count<0 or count>1000 then return false end
        if not write_global(base+field,1,function()return current()and read_global(base)==1 and read_global(base+field)==0 end)then return false end
        local wanted=math.max(0,count-1)
        write_global(24103,wanted,function()return current()and read_global(24103)==count end)
        local after=read_global(24103)
        if after~=wanted then
            -- A rejected counter write must not leave a retired marker that
            -- makes both this filter and GTA skip the decrement on retry.
            if after==count then
                write_global(base+field,0,function()return current()and read_global(base+field)==1 and read_global(24103)==count end)
            end
            return false
        end
        local flags=read_global(9503)
        if type(flags)=="number" and flags%1==0 then
            write_global(9503,flags|(1<<11),function()return current()and read_global(9503)==flags end)
        end
        return true
    end

    local function refresh_filtered_phone_badges(character)
        if character~=3 then return end
        local unread=0
        for index=0,PHONE_SMS_COUNT-1 do
            local base=114990+14150+1+index*104
            if read_global(base+24)~=0 and read_global(base+28)==0
                and read_global(base+99+1+character)==1 then unread=unread+1 end
        end
        local changed=false
        if read_global(24109)~=unread then
            changed=write_global(24109,unread,function()return started and is_on("block_automated_job_invites")end)==true
        end
        -- Bit 11 is cellphone_controller's home-screen rebuild request.
        -- Let GTA reconstruct real app icons from the filtered queues, rather
        -- than forging a scaleform row or hiding legitimate player texts.
        if changed then
            local flags=read_global(9503)
            if type(flags)=="number" and flags%1==0 then
                write_global(9503,flags|(1<<11),function()return started and is_on("block_automated_job_invites")and read_global(9503)==flags end)
            end
        end
    end

    local function own_heist_invite(base, player_origin, family, serial)
        -- Current fmmc_launcher func14398/14413 -> func14086/14087:
        -- Doomsday is generated by NPC12; Apartment is NPC12 or NPC20.
        -- The constructor publishes an integer identity and expiry flag0.
        -- func19724 never presents expiry-marked rows, even before their deadline.
        if player_origin ~= 0 or type(serial) ~= "number" or serial % 1 ~= 0
            or read_global(base + 37) ~= 0 then return false end
        local sender = read_global(base + 6)
        return family == 234 and sender == 12
            or family == 123 and (sender == 12 or sender == 20)
    end

    local function maintain_invite_filter(now)
        local state = State.invite_filter
        if not is_on("block_automated_job_invites") then return end
        now = tonumber(now) or now_ms()
        if not state.layout_checked_ms or now - state.layout_checked_ms >= 1000 or now < state.layout_checked_ms then
            state.layout_checked_ms = now
            state.layout = phone_filter_layout() and "VERIFIED_SOURCE_LAYOUT" or "UNAVAILABLE"
        end
        if state.layout ~= "VERIFIED_SOURCE_LAYOUT" then return end
        local character, pending, flags = read_global(21666), read_global(24108), read_global(9502)
        if character == 3 and type(pending) == "number" and type(flags) == "number"
            and (flags & ((1 << 7) | (1 << 1))) ~= 0 then reject_npc_sms(pending, character, true) end
        refresh_filtered_phone_badges(character)
        if now - (tonumber(state.last_scan_ms) or -100000) < 120 then return end
        state.last_scan_ms = now
        if character == 3 then
            local budget = state.initial_clear_done and 4 or PHONE_SMS_COUNT
            state.initial_clear_done = true
            for _ = 1, budget do
                reject_npc_sms(state.sms_cursor, character, false)
                state.sms_cursor = (state.sms_cursor + 1) % PHONE_SMS_COUNT
            end
        end
        -- Presence content is a JOB invite, never a direct player text. Friends
        -- receive no exemption. Own NPC heist continuations use the local44-cell
        -- job queue, and are not removed through the presence API.
        -- Presence invites also have a separate 99-cell presentation queue.
        -- NETWORK_REMOVE_PRESENCE_INVITE alone does not retract its existing
        -- feed item. freemode func19710/19711 own f_92; f_94 is row identity.
        local presence_rows = read_global(1689071)
        if read_global(2623479) == 12 and type(presence_rows) == "number"
            and presence_rows % 1 == 0 and presence_rows >= 0 and presence_rows <= 12 then
            for index = 0, presence_rows - 1 do
                local base = 2623479 + 1 + index * 99
                local serial, presence_id = read_global(base + 94), read_global(base + 91)
                if type(serial) == "number" and serial >= 0 and type(presence_id) == "number" and presence_id >= 0 then
                    local function current()
                        return started and State.invite_filter == state and is_on("block_automated_job_invites")
                            and read_global(1689071) == presence_rows and read_global(base + 94) == serial
                            and read_global(base + 91) == presence_id
                    end
                    if retire_filtered_invite_indicator(base,5,current,false) then
                        remove_phone_feed(base + 92,current)
                    end
                end
            end
        end
        local count = math.max(0, math.min(64, math.floor(tonumber(invoke_int(H.NETWORK_GET_NUM_PRESENCE_INVITES)) or 0)))
        for index = count - 1, 0, -1 do
            local content = tostring(deps.invoke_string(H.NETWORK_GET_PRESENCE_INVITE_CONTENT_ID, index) or "")
            if content ~= "" and invoke_bool(H.NETWORK_REMOVE_PRESENCE_INVITE, index) then
                phone_classification("NPC_JOB_INVITE");state.removed = state.removed + 1
            end
        end
        local network_time = tonumber(invoke_int(0x7A5487FE9FAA6B48))
        local jobs = read_global(1689073)
        if network_time and jobs and jobs >= 0 and jobs <= 12 and jobs % 1 == 0 then
            for index = 0, jobs - 1 do
                local base = 2624668 + 1 + index * 44
                local player_origin, family, serial = read_global(base+7), read_global(base+8), read_global(base+40)
                -- Match the source generator's sender, family, live identity and
                -- non-expired record. A friend's invite is still player_origin1.
                -- These fields identify a local continuation domain; they do not
                -- independently prove the chain remains active after enqueueing.
                if own_heist_invite(base, player_origin, family, serial) then
                    phone_classification("OWN_HEIST_INVITE")
                elseif (player_origin == 0 or player_origin == 1) and serial ~= nil
                    and state.processed_jobs[index] ~= serial then
                    local function current()
                        return started and State.invite_filter == state and is_on("block_automated_job_invites")
                            and read_global(1689073) == jobs and read_global(base+40) == serial
                            and read_global(base+7) == player_origin and read_global(base+8) == family
                            and not own_heist_invite(base, player_origin, family, serial)
                    end
                    local retired=retire_filtered_invite_indicator(base,4,current,false)
                    if retired then remove_phone_feed(base + 26, current) end
                    -- Expiry is the game's own pre-presentation reject path
                    -- func_19724 -> func_13731; it owns queue compaction/feed cleanup.
                    if retired and write_global(base+38, network_time - 1, current) then
                        if write_global(base+37, 1, current) then
                            state.processed_jobs[index] = serial
                            phone_classification("NPC_JOB_INVITE")
                        end
                    end
                end
            end
        end
        local normal = read_global(1689043)
        if normal and normal >= 0 and normal <= 12 and normal % 1 == 0 then
            for index = 0, normal - 1 do
                local base = 2622518 + 1 + index * 80
                local serial = read_global(base+73)
                local function current()
                    return started and State.invite_filter == state and is_on("block_automated_job_invites")
                        and read_global(1689043) == normal and read_global(base+73) == serial
                end
                -- PC func_19728 returns before feed/audio when content_ready67
                -- is false. Keep the bounded slot intact: no forged job or copy.
                local retired=false
                if serial ~= nil and state.processed_normal[index] ~= serial then
                    retired=retire_filtered_invite_indicator(base,4,current,true)
                    if retired then remove_phone_feed(base + 54, current) end
                end
                if retired and serial ~= nil and state.processed_normal[index] ~= serial
                    and write_global(base+67, 0, current) then
                    if write_global(base, 0, current) and write_global(base+77, 0, current) then
                        state.processed_normal[index] = serial
                        phone_classification("NPC_JOB_INVITE")
                    end
                end
            end
        end
        refresh_filtered_phone_badges(character)
        if state.removed > (state.last_logged_removed or 0) and now - state.last_log_ms >= 30000 then
            state.last_log_ms = now
            state.last_logged_removed=state.removed
            log_info("Phone Filter queued spam removed=" .. tostring(state.removed)
                .. "; player direct texts and local Apartment/Doomsday invite domains preserved; live presentation ordering requires retest.")
        end
    end

    restore_phone_suppression = function()
        local owner = phone_gate_owner
        if not owner then return true end
        local version_ok, version = pcall(function()
            return type(deps.invoke_string) == "function" and deps.invoke_string(0xFCA9373EF340AC0A) or nil
        end)
        if not version_ok or version ~= "1.73" then return false end
        -- Restore only our still-present value. The phone profile is persistent
        -- player configuration, not a freemode/roster global or retained entity.
        local observed = read_global(owner.index)
        if observed == nil then return false end
        if observed ~= 1 then phone_gate_owner=nil; return true end
        local restored = write_global(owner.index,owner.baseline,function()
            return read_global(owner.index)==1 and phone_gate_owner==owner
        end)
        -- A host may write the baseline then throw. A same-profile readback
        -- settles that debt immediately without resubmitting the write.
        if phone_gate_owner==owner and read_global(owner.index)==owner.baseline then
            phone_gate_owner=nil
            return true
        end
        return restored
    end

    maintain_disabled_phone_calls = function(now)
        local state = State.phone_calls
        if not is_on("block_automated_job_invites") then
            restore_phone_suppression()
            if state.active then State.phone_calls = new_phone_call_state() end
            return
        end
        -- Calls are independent of SMS/job-queue startup. A missing invite queue
        -- must not disable the incoming-call admission/cancellation controller.
        local layout_ok, layout = pcall(function()
            if type(deps.invoke_string) ~= "function" or deps.invoke_string(0xFCA9373EF340AC0A) ~= "1.73"
                or invoke_bool(H.NETWORK_IS_SESSION_STARTED) ~= true then return false end
            local phase, phone, incoming = read_global(INCOMING_PHONE.phase),
                read_global(INCOMING_PHONE.is_phone), read_global(INCOMING_PHONE.incoming)
            return type(phase)=="number" and phase%1==0 and phase>=0 and phase<=6
                and (phone==0 or phone==1) and (incoming==0 or incoming==1)
        end)
        state.layout = layout_ok and layout and "VERIFIED_CALL_CONTROLLER" or "UNAVAILABLE"
        if state.layout ~= "VERIFIED_CALL_CONTROLLER" then
            -- Do not restore through unvalidated/unavailable globals during a
            -- transition. Existing admission ownership remains available for OFF.
            return
        end
        now = tonumber(now) or now_ms()
        -- The admission profile is persistent character configuration. Keep
        -- it blocked while the player ID/ped is unavailable during loading or
        -- death; only the incoming action needs a current living player.
        local function current()
            return started and State.phone_calls==state and is_on("block_automated_job_invites")
        end
        local character = read_global(INCOMING_PHONE.character)
        if not character or character%1~=0 or character<0 or character>3 then return end
        local profile = INCOMING_PHONE.profile_base+1+character*INCOMING_PHONE.profile_stride
            +1+INCOMING_PHONE.profile_field
        if phone_gate_owner and phone_gate_owner.index~=profile then
            if not restore_phone_suppression() then return end
        end
        local mode = read_global(profile)
        if mode~=0 and mode~=1 and mode~=2 then return end
        if mode~=1 and current() then
            local owner={index=profile,baseline=mode}
            -- Capture before the host write so a toggle-off callback at that
            -- boundary can restore it; never claim an unverified admission gate.
            phone_gate_owner=owner
            local applied=write_global(profile,1,function()
                return read_global(INCOMING_PHONE.character)==character and read_global(profile)==mode
                    and phone_gate_owner==owner and current()
            end)
            if not current() then
                -- A session reset invalidates this action, not the enabled
                -- persistent admission owner. Do not reopen calls here.
                if not started or not is_on("block_automated_job_invites") then restore_phone_suppression() end
                return
            end
            if not applied then return end
        end
        if not current() then return end
        if not state.active then
            log_info("Phone Filter silent profile active; incoming handlers cancelled, outgoing calls preserved; live outcome unverified.")
        end
        state.active=true
        local pid=tonumber(local_player_id())
        if not current() or not pid or pid%1~=0 or pid<0 or pid>31 then return end
        local life_ok,dead=pcall(invoke_bool,PHONE_IS_PLAYER_DEAD_NATIVE,pid)
        if not life_ok or dead~=false or not current() then return end

        -- A pending priority-13/forced call may already have passed admission.
        -- Require the handler's phone AND incoming flags and an exact current
        -- caller/phase. Ordinary dialogue, outgoing calls and answered calls
        -- are never stopped. The game remains responsible for audio/UI cleanup.
        local phase=read_global(INCOMING_PHONE.phase)
        local caller=read_global(INCOMING_PHONE.caller)
        local selector=read_global(INCOMING_PHONE.selector)
        if (phase~=1 and phase~=2) or not caller or caller%1~=0 or caller<0 or caller>223
            or (selector~=0 and selector~=1 and selector~=3) then return end
        local function incoming(expected_phase, expected_selector)
            return read_global(INCOMING_PHONE.is_phone)==1
                and read_global(INCOMING_PHONE.incoming)==1
                and read_global(INCOMING_PHONE.phase)==expected_phase
                and read_global(INCOMING_PHONE.selector)==expected_selector
                and read_global(INCOMING_PHONE.caller)==caller and current()
        end
        if not incoming(phase,selector) then return end
        local forced=read_global(INCOMING_PHONE.forced)
        local rejected=read_global(INCOMING_PHONE.rejected)
        if (forced~=0 and forced~=1) or (rejected~=0 and rejected~=1) then return end
        -- State-based coalescing: a new call from the same caller can be
        -- cancelled on the very next frame; a completed reject is not rewritten.
        if phase==2 and selector==3 and forced==0 and rejected==1 then return end
        state.last_block_ms,state.last_caller,state.last_phase=now,caller,phase
        if phase==1 then
            -- Phase 1 is the preloaded/preparing handler. Its wait loops consume
            -- closing=1; phase=6 prevents resumed preload from admitting it.
            local closing=read_global(INCOMING_PHONE.closing)
            if closing~=0 and closing~=1 then return end
            if not write_global(INCOMING_PHONE.closing,1,function() return incoming(1,selector) end) then return end
            if not write_global(INCOMING_PHONE.phase,6,function() return incoming(1,selector) end) then return end
        else
            if selector==0 then return end
            if forced==1 then
                if not write_global(INCOMING_PHONE.forced,0,function() return incoming(2,selector) end) then return end
            end
            if not write_global(INCOMING_PHONE.selector,3,function() return incoming(2,selector) end) then return end
            if not write_global(INCOMING_PHONE.rejected,1,function() return incoming(2,3) end) then return end
        end
        if not current() then return end
        state.blocks=state.blocks+1
        phone_classification("CONTACT_CALL")
        if not state.cancel_logged then
            state.cancel_logged=true
            log_info("Phone Filter cancelled a pending incoming handler; phase="..tostring(phase).." caller="..tostring(caller).."; live outcome unverified.")
        end
    end

    local function freemode_host_id()
        local value = invoke_int(H.NETWORK_GET_HOST_OF_SCRIPT, ORGANIZATION_SOURCE.freemode_script, -1, 0)
        value = tonumber(value)
        return value and value >= 0 and value <= 31 and math.floor(value) or -1
    end

    local function organization_integer(value, low, high)
        return type(value) == "number" and value == value and value % 1 == 0
            and value >= low and value <= high
    end

    local function organization_layout()
        -- These are VM arrays: the cell at the base is the array header.
        -- Require the actual tunable pointer to match the source-derived index
        -- before allowing writes on this installed game build.
        if read_global(ORGANIZATION_SOURCE.boss_owner_base) ~= 32
            or read_global(ORGANIZATION_SOURCE.ceo_state_base) ~= 32
            or read_global(ORGANIZATION_SOURCE.roster_header) ~= ORGANIZATION_SOURCE.roster_capacity then
            return false, "Organization array layout does not match the verified Enhanced source."
        end
        if type(script_global.GetTunableByHash) ~= "function" or type(script_global.GetPtr) ~= "function" then
            return false, "Cherax tunable identity checks are unavailable."
        end
        local ok_hash, hash = pcall(utils.Joaat, "GB_NUMBER_OF_BOSSES_IN_SESSION")
        if not ok_hash or type(hash) ~= "number" then return false, "Organization tunable hash is unavailable." end
        local ok_tunable, tunable = pcall(script_global.GetTunableByHash, hash)
        local ok_global, address = pcall(script_global.GetPtr, ORGANIZATION_SOURCE.max_bosses_global)
        if not ok_tunable or not ok_global or not organization_integer(tunable, 1, math.maxinteger)
            or tunable ~= address then
            return false, "Organization tunable mapping does not match this game build."
        end
        return true
    end

    local function read_organization_identity()
        local pid = local_player_id()
        if not organization_integer(pid, 0, 31) then return nil, nil, nil, nil, "Local player ID is unavailable." end
        local layout, layout_error = organization_layout()
        if not layout then return nil, nil, nil, nil, layout_error end
        local owner_index = function(id)
            return ORGANIZATION_SOURCE.boss_owner_base + 1 + id * ORGANIZATION_SOURCE.boss_owner_stride
                + ORGANIZATION_SOURCE.boss_owner_field
        end
        local owner = read_global(owner_index(pid))
        if not organization_integer(owner, -1, 31) then return nil, nil, nil, nil, "Organization owner is invalid." end
        local registered = 0
        for id = 0, 31 do
            local ok, active = pcall(invoke_bool, ORGANIZATION_SOURCE.player_active_native, id)
            if not ok or type(active) ~= "boolean" then return nil, nil, nil, nil, "Player activity readback is unavailable." end
            if id == pid and not active then return nil, nil, nil, nil, "Local player is not active." end
            if active then
                local candidate = read_global(owner_index(id))
                if not organization_integer(candidate, -1, 31) then return nil, nil, nil, nil, "Organization roster identity is invalid." end
                if candidate == id then registered = registered + 1 end
            end
        end
        local role = "Independent"
        if owner >= 0 then
            local boss_type = read_global(ORGANIZATION_SOURCE.boss_owner_base + 1
                + owner * ORGANIZATION_SOURCE.boss_owner_stride + ORGANIZATION_SOURCE.boss_type_field)
            if not organization_integer(boss_type, 0, 1) then return nil, nil, nil, nil, "Organization type is unavailable." end
            if owner == pid then
                local ceo = read_global(ORGANIZATION_SOURCE.ceo_state_base + 1
                    + pid * ORGANIZATION_SOURCE.ceo_state_stride + ORGANIZATION_SOURCE.ceo_state_field)
                if not organization_integer(ceo, -2147483648, 4294967295) then return nil, nil, nil, nil, "CEO state is unavailable." end
                role = boss_type == ORGANIZATION_SOURCE.mc_boss_type and "MC President"
                    or (ceo & (1 << ORGANIZATION_SOURCE.ceo_bit)) ~= 0 and "CEO" or "VIP"
            else
                role = boss_type == ORGANIZATION_SOURCE.mc_boss_type and "MC Member" or "Organization Member"
            end
        end
        return pid, owner, registered, role
    end

    local function organization_log(event, detail)
        local state = State.organization
        local signature = tostring(event) .. "|" .. tostring(detail)
        if state.last_log_signature == signature then return end
        state.last_log_signature = signature
        log_info(("OrganizationLimit event=%s host=%s enabled=%s override=%s registered=%s normal=%s effective=%s detail=%s")
            :format(tostring(event), tostring(state.script_host), tostring(state.bypass_enabled),
                tostring(state.override_applied), tostring(state.registered), tostring(state.normal_limit),
                tostring(state.effective_limit), tostring(detail or "")))
    end

    -- Unknown observations are not session boundaries. Retain restoration debt
    -- while globals/player identity are temporarily unavailable during loading.
    local function organization_lifecycle(state)
        if State.organization ~= state
            or state.activation_session_started_ms ~= State.session_started_ms then return false end
        local pid = local_player_id()
        if State.organization ~= state
            or state.activation_session_started_ms ~= State.session_started_ms then return false end
        if not State.online or not organization_integer(pid, 0, 31) then return nil end
        return pid == state.activation_player_id
    end

    local function organization_current(state, require_host)
        if State.organization ~= state or not State.online
            or state.activation_session_started_ms ~= State.session_started_ms
            or local_player_id() ~= state.activation_player_id then return false end
        if require_host and freemode_host_id() ~= state.activation_player_id then return false end
        if organization_layout() ~= true then return false end
        -- Native/API readbacks can re-enter lifecycle callbacks. Revalidate
        -- the owner after all of them, including the final player lookup.
        local pid = local_player_id()
        return State.organization == state and State.online
            and state.activation_session_started_ms == State.session_started_ms
            and pid == state.activation_player_id
    end

    local function capture_organization_baselines(state, normal_limit)
        if not organization_integer(normal_limit, 1, ORGANIZATION_SOURCE.roster_capacity) then
            return false, "Organization tunable is outside the verified 1..10 slot range."
        end
        local pid, _, _, _, err = read_organization_identity()
        if pid == nil then return false, err end
        if state.last_limit_applied ~= nil and state.activation_session_started_ms == State.session_started_ms
            and state.activation_player_id == pid then
            return true -- Preserve the original baseline until pending restoration is settled.
        end
        state.original_limit = normal_limit
        state.activation_session_started_ms = State.session_started_ms
        state.activation_player_id = pid
        state.last_limit_applied = nil
        state.ownership_conflict = false
        return true
    end

    local function request_freemode_script_host(state, reason)
        if state.script_host then return true, "Already Freemode Script Host." end
        state.auto_acquire_host_id = state.freemode_host_id
        if type(gta.ForceScriptHost) ~= "function" then return false, "Cherax GTA.ForceScriptHost is unavailable." end
        local ok_hash, hash = pcall(utils.Joaat, ORGANIZATION_SOURCE.freemode_script)
        if not ok_hash or type(hash) ~= "number" then return false, "Could not hash freemode." end
        local ok, result = pcall(gta.ForceScriptHost, hash)
        if State.organization ~= state then return false, "Session changed during host acquisition." end
        if not ok or result == false then return false, "Freemode Script Host request failed: " .. tostring(result) end
        state.acquire_pending, state.acquire_requested_at = true, now_ms()
        state.last_error, state.last_result = nil, reason or "Freemode Script Host requested once."
        organization_log("HOST_REQUESTED", state.last_result)
        return true, state.last_result
    end

    local function disable_organization_bypass(reason, host_lost)
        local state = State.organization
        state.bypass_enabled, state.bypass_active, state.acquire_pending = false, false, false
        state.auto_acquire_host_id = nil
        if state.last_limit_applied ~= nil then
            local lifecycle = organization_lifecycle(state)
            if lifecycle == false then
                state.last_limit_applied, state.override_applied = nil, false
                state.original_limit, state.activation_player_id, state.activation_session_started_ms = nil, nil, nil
                state.last_result = "Organization override dropped at a session/identity boundary; no stale globals restored."
                return true, state.last_result
            end
            if lifecycle ~= true or not organization_current(state, false) then
                state.status = "RESTORING"
                state.last_error = "Organization restoration is waiting for verified globals and player identity."
                return false, state.last_error
            end
            local current = read_global(ORGANIZATION_SOURCE.max_bosses_global)
            if current == state.last_limit_applied then
                local expected = current
                local ok, err = write_global(ORGANIZATION_SOURCE.max_bosses_global, state.original_limit, function()
                    local observed = read_global(ORGANIZATION_SOURCE.max_bosses_global)
                    return observed == expected and organization_current(state, false)
                end)
                if not ok then state.last_error = err; return false, err end
                if not organization_current(state, false) then return false, "Organization restore crossed a lifecycle boundary." end
            elseif current == nil then
                state.last_error = "Organization limit is unavailable during restoration."
                return false, state.last_error
            end
            -- A value changed by Rockstar or another owner is never overwritten.
        end
        state.last_limit_applied, state.override_applied, state.accepted_extra = nil, false, false
        state.original_limit, state.activation_player_id, state.activation_session_started_ms = nil, nil, nil
        state.last_error = nil
        state.last_result = "Organization limit override disabled: " .. tostring(reason or "requested")
        organization_log("DISABLED", state.last_result)
        return true, state.last_result
    end

    local function organization_slots(limit)
        local free, occupied, seen = 0, 0, {}
        for slot = 0, ORGANIZATION_SOURCE.roster_capacity - 1 do
            local owner = read_global(ORGANIZATION_SOURCE.roster_header + 1 + slot)
            if not organization_integer(owner, -1, 31) or (owner ~= -1 and seen[owner]) then
                return nil, "Organization slot roster is unavailable or inconsistent."
            end
            if owner ~= -1 then seen[owner] = true end
            if slot < limit then
                if owner == -1 then free = free + 1 else occupied = occupied + 1 end
            end
        end
        return free, occupied, seen
    end

    local function refresh_organization(now, force)
        local state = State.organization
        now = tonumber(now) or now_ms()
        if force ~= true and now - state.refreshed_at < 1000 then return state end
        state.refreshed_at = now
        if not State.online then
            state.current_role, state.status, state.script_host = "Offline", "OFFLINE", false
            state.bypass_active, state.eligible = false, false
            state.accepted_extra, state.registration_observed, state.revocation_suppressed = false, false, false
            state.in_host_roster = false
            return state
        end
        local pid, owner, count, role, err = read_organization_identity()
        local limit = read_global(ORGANIZATION_SOURCE.max_bosses_global)
        local free, slot_error, roster = organization_slots(organization_integer(limit, 1, 10) and limit or 10)
        if pid == nil or not organization_integer(limit, 1, 10) or free == nil then
            state.current_role, state.status = "Unavailable", "UNAVAILABLE"
            state.bypass_active, state.eligible = false, false
            state.accepted_extra, state.registration_observed, state.revocation_suppressed = false, false, false
            state.in_host_roster = false
            state.last_error = err or (free == nil and slot_error) or "Organization tunable is outside the verified range."
            return state
        end
        state.freemode_host_id = freemode_host_id()
        state.freemode_host_name = state.freemode_host_id >= 0 and player_name(state.freemode_host_id) or "Unknown"
        state.script_host = state.freemode_host_id == pid
        state.current_role, state.registered, state.session_limit = role, count, limit
        state.normal_limit = state.last_limit_applied and state.original_limit or limit
        state.effective_limit = limit
        local menu = online_interaction_backend and online_interaction_backend.Snapshot() or {}
        local local_admission = state.interaction_requested == true and menu.admission_applied == true
            and menu.suspension_guard_applied == true
        state.registration_observed = owner == pid
        state.in_host_roster = roster and roster[pid] == true or false
        state.accepted_extra = state.registration_observed and not state.in_host_roster and count > ORGANIZATION_SOURCE.roster_capacity
        state.revocation_suppressed = state.interaction_requested == true and menu.suspension_guard_applied == true
        state.eligible, state.local_suspension = role == "Independent" and (free > 0 or local_admission), false
        state.bypass_active = state.bypass_enabled and state.override_applied or local_admission
        state.authority = local_admission and "Local registration and local excess-role retention; host roster remains 10 entries"
            or "Local verified admission tunable; host roster remains 10 entries"
        state.status = state.ownership_conflict and "OWNERSHIP_CONFLICT"
            or free == 0 and limit == 10 and "CAPACITY_BLOCKED"
            or not state.bypass_enabled and state.last_limit_applied ~= nil and "RESTORING"
            or state.override_applied and "LIMIT_APPLIED_LIVE_RETEST_REQUIRED" or "READY_LIVE_RETEST_REQUIRED"
        if state.bypass_enabled and limit == 10 and not state.override_applied
            and not state.ownership_conflict and free > 0 then state.status = "ARMED_UNNECESSARY" end
        if local_admission then
            state.status = state.registration_observed and "REGISTRATION_OBSERVED" or "LOCAL_ADMISSION_READY"
            state.last_error = nil
            state.last_result = state.accepted_extra
                and ("Extra local registration observed: %s; %d organizations; host roster unchanged."):format(role, count)
                or state.registration_observed and ("Local registration observed: %s."):format(role)
                or "Local menu admission is ready, including a full roster; register through GTA's Interaction Menu."
        elseif state.interaction_requested then
            state.status = "LOCAL_ADMISSION_PENDING"
            state.last_error = nil
            state.last_result = menu.reason or "Waiting for the verified menu and Freemode resource gates."
        elseif state.status == "CAPACITY_BLOCKED" then
            state.bypass_active = false
            state.last_error = "All 10 host roster entries are occupied; the bounded tunable request has no free entry."
        elseif state.status ~= "OWNERSHIP_CONFLICT" then
            state.last_error = nil
        end
        return state
    end

    local function maintain_organization_bypass(now, force)
        local state = refresh_organization(now, true)
        now = tonumber(now) or now_ms()
        if not state.bypass_enabled then return true end
        if not State.online then state.last_result = "Organization override armed; waiting for GTA Online."; return true end
        if state.status == "UNAVAILABLE" then return false, state.last_error end
        -- The local registration path needs no tunable change. Preserve a
        -- separate manual request without letting its bounded-roster result
        -- replace the observed local admission/role status while this is active.
        if state.interaction_requested and state.revocation_suppressed
            and (state.status == "LOCAL_ADMISSION_READY" or state.status == "REGISTRATION_OBSERVED") then return true end
        if state.activation_session_started_ms ~= State.session_started_ms
            or state.activation_player_id ~= local_player_id() then
            local captured, err = capture_organization_baselines(state, state.session_limit)
            if not captured then return false, err end
        end
        -- This local registration tunable does not require Freemode Script Host
        -- ownership. Host acquisition remains an explicit diagnostic action.
        state.acquire_pending=false
        local limit = state.session_limit
        if state.last_limit_applied and limit ~= state.last_limit_applied then
            state.last_limit_applied, state.override_applied = nil, false
            state.ownership_conflict = true
        end
        if state.ownership_conflict then
            state.bypass_active, state.status = false, "OWNERSHIP_CONFLICT"
            state.last_result = "Rockstar or another owner changed the organization limit; toggle off/on to capture a new baseline."
            organization_log("OWNERSHIP_CONFLICT", state.last_result)
            return false, state.last_result
        end
        -- A lower admission tunable does not imply a spare physical slot.
        -- Avoid changing it at all when every verified roster slot is occupied.
        local physical_free = organization_slots(ORGANIZATION_SOURCE.roster_capacity)
        if physical_free == nil then
            state.bypass_active, state.eligible = false, false
            return false, "Organization roster changed during admission."
        end
        if physical_free == 0 then
            state.status, state.bypass_active, state.eligible = "CAPACITY_BLOCKED", false, false
            state.last_result = "All 10 host roster entries are occupied; enable local Interaction Menu availability for separate local admission."
            state.last_error = state.last_result
            return false, state.last_result
        end
        if limit < ORGANIZATION_SOURCE.roster_capacity then
            local before = limit
            state.original_limit = before
            state.last_limit_applied = ORGANIZATION_SOURCE.roster_capacity
            local ok, err = write_global(ORGANIZATION_SOURCE.max_bosses_global, ORGANIZATION_SOURCE.roster_capacity, function()
                local observed = read_global(ORGANIZATION_SOURCE.max_bosses_global)
                local current = observed == before and organization_current(state, false)
                return current and started and state.bypass_enabled and state.pending_request ~= false
            end)
            if not ok then
                if read_global(ORGANIZATION_SOURCE.max_bosses_global) ~= state.last_limit_applied then state.last_limit_applied = nil end
                state.last_error, state.bypass_active = err, false
                return false, err
            end
            if not organization_current(state, false) or not state.bypass_enabled or state.pending_request == false then return false, "Organization action was cancelled." end
            state.override_applied, state.bypass_active = true, true
            state.session_limit, state.effective_limit, state.last_apply_ms = 10, 10, now
            organization_log("LIMIT_APPLIED", "Raised the verified admission tunable to the existing 10-slot capacity; register through GTA's Interaction Menu.")
        end
        local free = organization_slots(10)
        if free == nil then state.bypass_active = false; return false, "Organization roster changed during admission." end
        if not organization_current(state, false) then return false, "Organization admission crossed a lifecycle boundary." end
        state.eligible = state.current_role == "Independent" and free > 0
        state.accepted_extra = (state.current_role == "CEO" or state.current_role == "VIP" or state.current_role == "MC President")
            and state.original_limit ~= nil and state.registered > state.original_limit
        if state.accepted_extra then
            state.last_result = ("Registration observed: %s; %d organizations within 10 physical slots."):format(state.current_role, state.registered)
            organization_log("REGISTRATION_OBSERVED", state.last_result)
        elseif free == 0 then
            state.status = "CAPACITY_BLOCKED"
            state.bypass_active, state.eligible = false, false
            state.last_result = "All 10 host roster entries are occupied; the bounded tunable request cannot add a host entry. Local menu admission is separate."
            state.last_error = state.last_result
            organization_log("CAPACITY_BLOCKED", state.last_result)
            return false, state.last_result
        else
            state.last_result = state.override_applied
                and "Lower organization limit raised and read back to 10; registration still requires a live outcome."
                or "Armed but unnecessary: the current limit is already 10 and a roster slot is free. No limit was changed."
        end
        return true
    end

    local apply_organization_request
    local acquire_organization_host
    -- Declare before the tick closures: later local declarations bind globals
    -- in Lua, even though the callbacks execute after module initialization.
    if not online_interaction_backend then
        -- Resolve through the current binding, not a stale optional host table.
        -- This also keeps pending cleanup usable after a compatibility rebind.
        local function host_call(group,method,...)
            local object=dependencies and dependencies[group]
            local fn=object and object[method]
            if type(fn)~="function" then error(group.."."..method.." unavailable",0) end
            return fn(...)
        end
        local host={Memory={},ScriptGlobal={},ScriptLocal={},LocalPlayerId=function()
            local fn=dependencies and dependencies.local_player_id
            if type(fn)~="function" then error("local_player_id unavailable",0) end
            return fn()
        end}
        local function read_uint(...)return host_call("Memory","ReadUInt",...)end
        setmetatable(host.Memory,{__index=function(_,key)
            if key~="ReadUInt"then return nil end
            local memory=dependencies and dependencies.Memory
            return type(memory)=="table"and type(memory.ReadUInt)=="function"and read_uint or nil
        end})
        host.Memory.ScanScript=function(...)return host_call("Memory","ScanScript",...)end
        host.Memory.ReadUByte=function(...)
            local memory=dependencies and dependencies.Memory
            if memory and type(memory.ReadUByte)=="function" then return memory.ReadUByte(...) end
            local value=host_call("Memory","ReadByte",...)
            if type(value)=="number" and value>=-128 and value<0 then return value+256 end
            return value
        end
        host.WholeWriteReady=function(width)
            local memory=dependencies and dependencies.Memory
            if width==2 then return memory~=nil and type(memory.WriteUShort or memory.WriteShort)=="function" end
            return memory~=nil and type(memory.WriteUInt or memory.WriteInt)=="function"
        end
        host.Memory.WriteUShort=function(...)
            local memory=dependencies and dependencies.Memory
            local fn=memory and (memory.WriteUShort or memory.WriteShort)
            if type(fn)~="function" then error("Memory short-instruction writer unavailable",0) end
            return fn(...)
        end
        host.Memory.WriteUInt=function(...)
            local memory=dependencies and dependencies.Memory
            local fn=memory and (memory.WriteUInt or memory.WriteInt)
            if type(fn)~="function" then error("Memory whole-instruction writer unavailable",0) end
            return fn(...)
        end
        host.ScriptLocal.GetPtr=function(...)return host_call("ScriptLocal","GetPtr",...)end
        for _,name in ipairs({"AreValid","GetPtr","GetInt"}) do
            host.ScriptGlobal[name]=function(...)return host_call("ScriptGlobal",name,...)end
        end
        online_interaction_backend=InteractionBackend.New(host)
    end
    local interaction=online_interaction_backend
    if not online_bst_collection_backend then
        local function current(group, method, ...)
            local object=dependencies and dependencies[group]
            local fn=object and object[method]
            if type(fn)~="function" then error(group.."."..method.." unavailable",0) end
            return fn(...)
        end
        local host={Memory={},ScriptLocal={}}
        local function read_uint(...)return current("Memory","ReadUInt",...)end
        setmetatable(host.Memory,{__index=function(_,key)
            if key~="ReadUInt"then return nil end
            local memory=dependencies and dependencies.Memory
            return type(memory)=="table"and type(memory.ReadUInt)=="function"and read_uint or nil
        end})
        for _,name in ipairs({"ScanScript","ReadUByte","WriteUInt"}) do
            host.Memory[name]=function(...) return current("Memory",name,...) end
        end
        host.ScriptLocal.GetPtr=function(...) return current("ScriptLocal","GetPtr",...) end
        host.Context=function()
            assert(current("ScriptGlobal","AreValid")==true,"Session globals unavailable.")
            assert(current("Natives","InvokeBool",0xD83C2B94E7508980)==true,"Session unavailable.")
            local pid=current("Natives","InvokeInt",0x4F8644AF03D0E0D6)
            assert(type(pid)=="number" and pid%1==0 and pid>=0 and pid<32,"Local player unavailable.")
            local player=assert(current("Players","GetById",pid))
            assert(player.PlayerId==pid,"Local player changed.")
            local c={pid=pid,cxn=player.CxnId,origin=current("ScriptGlobal","GetInt",2645103)}
            assert(current("Natives","InvokeInt",0x4F8644AF03D0E0D6)==pid,"Local player changed.")
            local after=assert(current("Players","GetById",pid))
            assert(after.PlayerId==pid and after.CxnId==c.cxn,"Local connection changed.")
            return c
        end
        online_bst_collection_backend=BSTCollectionBackend.New(host)
    end
    local bst_collection=online_bst_collection_backend
    if not online_restart_backend then
        local gethost=function()return assert(dependencies,"Session adapters unavailable")end
        local probe=RestartProbe(gethost)
        local recovery_probe,gentle=RecoveryProbe(gethost,probe)
        local restart=NativeRestart.New({
            Resolve=function()return gethost().FeatureMgr.GetFeature(NativeRestart.FeatureHash)end,
            ButtonType=feature_type.Button,Probe=probe,
        })
        local unstuck=CoreUnstuck.New({
            Probe=recovery_probe,Gentle=gentle,Route=OnlineRecoveryRouter.New(gethost),
        })
        online_restart_backend=RecoveryPair(restart,unstuck)
    end
    if not online_rejoin_backend then
        local ok,controller,host,available=pcall(Module.NewExactSessionReturn,module_context,now_ms)
        if ok then online_rejoin_backend,online_rejoin_host,online_rejoin_available=controller,host,available end
    end
    local native_restart=online_restart_backend
    local native_request
    local native_last_tick=-1
    local stopped_interaction_ms=-math.huge
    local interaction_last_status,interaction_last_log=nil,-math.huge
    -- Recovery owns its native restart path and loading-resource lifecycle.
    local INTERACTION_SCOPE = "Local menu entry, row navigation and selection gates, plus normal local organization registration."
    local INTERACTION_EXECUTION = "Constructed rows use the normal game callbacks. Assets, ownership and network action results still come from GTA. BST collection timing cleanup is retained."
    local exact_rejoin,exact_rejoin_host=online_rejoin_backend,online_rejoin_host
    local rejoin_queued,rejoin_cancel,rejoin_visible=false,false,false
    local rejoin_draining=false
    local rejoin_last_phase
    local interaction_reason = INTERACTION_SCOPE
    local rejoin_reason = "One-click Seamless Rejoin with verification of the original session and freemode readiness."
    local restart_reason = "Restart freemode and verify its initialization, player list readiness and player control."
    local recovery={request=nil,phase="idle",last_error=nil,generation=0}
    local online_capabilities = {
        interaction={available=false,reason=interaction_reason},
        rejoin={available=online_rejoin_available==true,reason=rejoin_reason},
        restart={available=native_restart.Available(),reason=restart_reason},
        unstuck={available=native_restart.Available("unstuck"),
            reason="Recover loading, continue through the landing page and verify playable GTA Online."},
    }
    local provider_specs = {}

    local providers={}
    local function provider_method(feature,method,...)
        if type(feature[method])~="function" then error(method.." unavailable",0) end
        return feature[method](feature,...)
    end
    local function validate_provider(kind,feature,spec)
        for _,own in pairs(F) do if own==feature then return nil,"CScript feature rejected." end end
        -- Type precedes all value access; userdata method presence is not a type.
        local valid,why=pcall(function()
            local actual=provider_method(feature,"GetType")
            if feature_type[spec.kind]==nil or actual~=feature_type[spec.kind] then error("Host feature type mismatch.",0) end
            if provider_method(feature,"GetHash")~=spec.hash then error("Host feature hash mismatch.",0) end
            if provider_method(feature,"GetName",false)~=spec.name then error("Host feature name mismatch.",0) end
            if provider_method(feature,"IsPlayerFeature")~=false then error("Player feature rejected.",0) end
            if provider_method(feature,"IsToggleFeature")~=(kind=="interaction") then error("Host toggle type mismatch.",0) end
            if kind=="interaction" then
                if type(provider_method(feature,"GetBoolValue"))~="boolean" then error("Host BOOL unavailable.",0) end
                if type(feature.SetBoolValue)~="function" then error("Host BOOL setter unavailable.",0) end
            end
            if type(feature.TriggerCallback)~="function" then error("Host callback unavailable.",0) end
            if feature_mgr.GetFeature(spec.hash)~=feature then error("Host provider unloaded or replaced.",0) end
        end)
        if not valid then return nil,tostring(why) end
        return feature
    end
    local function resolve_provider(kind)
        local spec=provider_specs[kind]
        if kind=="rejoin" then return nil,rejoin_reason end
        local ok,feature=pcall(function() return feature_mgr.GetFeature(spec.hash) end)
        if not ok then return nil,tostring(feature) end
        if not feature then return nil,kind=="restart" and restart_reason or "Exact host feature is not loaded." end
        return validate_provider(kind,feature,spec)
    end
    local last_provider_probe = -math.huge
    local function probe_providers()
        local now=now_ms()
        if now>=last_provider_probe and now-last_provider_probe<500 then return end
        last_provider_probe=now
        online_capabilities.restart={available=native_restart.Available(),reason=restart_reason}
        online_capabilities.unstuck={available=native_restart.Available("unstuck"),
            reason="Recover loading, continue through the landing page and verify playable GTA Online."}
    end

    local function recovery_now()
        local time=module_context and module_context.Raw and module_context.Raw.Time
        assert(time and type(time.GetEpocheMs)=="function","Recovery wall clock unavailable")
        local value=time.GetEpocheMs()
        assert(type(value)=="number" and value==value and value>=0,"Recovery wall clock invalid")
        return value
    end
    local function maintain_exact_rejoin(now)
        if not exact_rejoin then return end
        if rejoin_cancel or (not started and exact_rejoin:HasWork()) then
            rejoin_cancel,rejoin_queued=false,false
            exact_rejoin:Cancel("Session return cancelled")
        elseif rejoin_queued and started then
            rejoin_queued=false
            exact_rejoin:Request(recovery_now())
        end
        exact_rejoin:Tick(recovery_now())
        local view=exact_rejoin:Snapshot()
        if view.phase~=rejoin_last_phase then
            rejoin_last_phase=view.phase
            pcall(log_info,"Session return phase="..tostring(view.phase).." detail="..tostring(view.last_error or view.detail).." backend="..tostring(exact_rejoin_host.LastError()or "none"))
            if view.phase=="succeeded"then pcall(toast,"Rejoined the same session.")end
        end
    end

    local function finish_recovery(phase, detail)
        recovery.request=nil
        recovery.phase=phase
        recovery.last_error=(phase=="failed" or phase=="cancelled") and detail or nil
        recovery.detail=detail
        -- Dispatch evidence is emitted on gameplay ticks/lifecycle cleanup only.
        -- Render-side queueing and detached getters never call the logger.
        pcall(log_info,"Session recovery action="..tostring(recovery.action)
            .." phase="..phase.." detail="..tostring(detail))
    end

    local function cancel_recovery(reason)
        if native_restart.Snapshot().pending then
            native_restart.Cancel(reason)
            if native_request then native_request.cancelled=true end
        end
        recovery.generation=recovery.generation+1
        if recovery.request or recovery.phase=="dispatching" then finish_recovery("cancelled",reason) end
    end

    local function recovery_bool(hash,...)
        if type(hash)~="number" or hash%1~=0 or hash==0 then return nil,"Native BOOL hash unavailable." end
        if type(deps.invoke_bool_detail)~="function" then return nil,"Detailed native BOOL dispatch unavailable." end
        local ok, _, raw, err=pcall(deps.invoke_bool_detail,hash,...)
        if not ok then return nil,tostring(_) end
        if err~=nil then return nil,tostring(err) end
        if type(raw)=="boolean" then return raw end
        if type(raw)=="number" and raw==raw and raw%1==0
            and raw>=-2147483648 and raw<=4294967295 then return raw~=0 end
        return nil,"Native BOOL readback unavailable."
    end

    local function transition_active()
        local active,unknown=false,nil
        for _,name in ipairs({"NETWORK_IS_IN_TRANSITION","NETWORK_IS_TRANSITION_STARTED","NETWORK_IS_TRANSITION_BUSY"}) do
            local value,why=recovery_bool(H[name])
            if value==true then active=true elseif value==nil then unknown=why end
        end
        -- Require all three reads: an unreadable flag is not evidence of exit.
        if unknown then return nil,unknown end
        return active
    end

    -- Native contracts from the installed natives DB. Pending invite cancellation
    -- is also used by GTA's Transition_Saving.sch when an invite cannot proceed.
    -- It cancels only the invite, never selects a replacement session.
    local RECOVERY_NATIVE = {
        awaiting_invite=0xD313DE83394AF134, cancel_invite=0xA29177F7703B5644,
        player_control=0x49C32D60007AFA47, screen_faded_in=0x5A859503B0C08678,
    }
    local function recovery_playable()
        if recovery_bool(H.IS_WARNING_MESSAGE_ACTIVE)~=false then return false,"Rockstar warning remains active or unreadable." end
        if recovery_bool(H.NETWORK_IS_SESSION_STARTED)~=true then return false,"Online session is not ready." end
        local id=local_player_id()
        if type(id)~="number" or id<0 or id>31 or not player_available(id) then return false,"Local player is not available." end
        if recovery_bool(RECOVERY_NATIVE.player_control,id)~=true then return false,"GTA has not returned player control." end
        if recovery_bool(RECOVERY_NATIVE.screen_faded_in)~=true then return false,"Loading/fade screen has not cleared." end
        return true
    end

    local function request_current(request)
        -- These operations own no ped/roster/global snapshot. Online and player
        -- availability naturally change while recovering a transition. Explicit
        -- lifecycle cancellation and the dispatched resource identity are fences.
        return started and recovery.request==request and recovery.generation==request.generation
    end

    local function maintain_native_restart(now)
        local view=native_restart.Snapshot()
        local stamp=recovery_now()
        if not view.pending or native_last_tick==stamp then return end
        native_last_tick=stamp
        native_restart.Tick(stamp)
        view=native_restart.Snapshot()
        if native_request and view.dispatch_started then native_request.dispatch_started=true end
        if view.pending then
            recovery.phase=view.cancellation_deferred and "completing_after_cancel" or view.phase
            recovery.last_error=view.cleanup_error or view.error
            recovery.detail=view.cleanup_error and "Owned loading-resource release pending: "..view.cleanup_error
                or view.cancellation_deferred and "Finishing an already-started freemode restart before cleanup."
                or "Session recovery: "..tostring(view.phase)
            return
        end
        local previous=native_request;native_request=nil
        if previous and recovery.request~=previous and recovery.request~=nil then return end
        if previous and recovery.request==previous and started and not previous.cancelled
            and view.gameplay_recovery_verified then
            finish_recovery("done",view.detail or "Freemode restarted and reached a stable playable state.")
            return
        end
        local phase=(view.phase=="cancelled" or previous and previous.cancelled) and "cancelled" or "failed"
        finish_recovery(phase,view.detail or view.error or "Freemode restart ended without a verified replacement.")
    end

    local function maintain_recovery(now)
        local request=recovery.request
        if not request then return end
        if request.phase=="native_restart" then return end -- serviced independently, including cancellation cleanup
        if not request_current(request) then return end
        -- now_ms is native-backed in compat. Establish the bounded dispatch/
        -- observation budget on the first gameplay frame, never in the UI.
        request.deadline=request.deadline or now+8000
        if now>request.deadline then
            finish_recovery("failed","Recovery deadline expired; completion was not verified."
                ..(request.waiting_reason and " Last waiting cause: "..request.waiting_reason or "")); return
        end
        if request.phase=="dispatching" or request.phase=="cleaning" then return end -- Reentrant host tick.
        if request.phase=="queued" then
            if request.retry_at and now<request.retry_at then return end
            request.attempts=(request.attempts or 0)+1
            recovery.attempts=request.attempts
            local function wait_for(reason)
                request.waiting_reason=tostring(reason)
                request.retry_at=now+500
                recovery.phase,recovery.detail="waiting","Manual "..request.kind.." waiting: "..request.waiting_reason
                recovery.waiting_reason=request.waiting_reason
                if recovery.logged_wait~=request.waiting_reason then
                    recovery.logged_wait=request.waiting_reason
                    pcall(log_info,"Session recovery action="..request.kind.." phase=waiting detail="..request.waiting_reason)
                end
            end
            if request.kind=="restart" or request.kind=="unstuck" then
                if not native_restart.Available(request.kind) then wait_for(request.kind=="unstuck" and "Supported Online recovery adapters are unavailable." or "Core Restart Freemode action is unavailable."); return end
                local accepted,detail=native_restart.Request(recovery_now(),request.kind)
                if not request_current(request) then
                    if accepted then native_restart.Cancel("Lifecycle changed during restart request") end
                    return
                end
                if accepted~=true then finish_recovery("failed",detail or "Standalone restart refused."); return end
                request.phase="native_restart";native_request=request
                recovery.phase,recovery.detail="queued",request.kind=="unstuck" and "Loading recovery queued." or "Freemode restart queued; waiting for fresh initialization and player control."
                return
            end
            -- UI acceptance never resolves a provider or invokes a native. A
            -- provider loaded after the request is usable on this gameplay frame.
            local feature,provider_error=resolve_provider(request.kind)
            if not request_current(request) then return end
            online_capabilities[request.kind]={available=feature~=nil,reason=provider_error or "Exact host action; gameplay completion unverified."}
            if feature then
                if request.provider and request.provider~=feature then
                    finish_recovery("cancelled","Captured host provider was replaced before dispatch."); return
                end
                local live,why=resolve_provider(request.kind)
                if not request_current(request) then return end
                if live~=feature then finish_recovery("failed",why or "Host provider changed before dispatch."); return end
                -- Keep the active request during callbacks to reject duplicates;
                -- phase prevents double dispatch if a callback re-enters a tick.
                request.phase,request.dispatch_started="dispatching",true
                recovery.phase,recovery.detail="dispatching","Exact host action dispatching; completion unverified."
                local ok,result=pcall(provider_method,feature,"TriggerCallback")
                if not request_current(request) then return end
                if not ok or result==false then
                    finish_recovery("failed",not ok and "Host callback failed: "..tostring(result) or "Host callback refused."); return
                end
                if request.kind~="unstuck" then
                    finish_recovery("submitted","Exact host "..request.kind.." request submitted; completion unverified."); return
                end
                request.phase="observing"
                recovery.phase,recovery.detail="observing","Unstuck host action submitted; observing transition exit."
                return
            end
            if request.kind~="unstuck" then wait_for(provider_error); return end
            -- Cancellation is void; leave is BOOL (natives_gen9.json). Do not
            -- require an active transition to submit cancellation. Unknown flags
            -- or an unloaded native can never establish successful exit/no-op.
            if type(H.NETWORK_CANCEL_TRANSITION_MATCHMAKING)~="number" or H.NETWORK_CANCEL_TRANSITION_MATCHMAKING==0
                or type(H.NETWORK_LEAVE_TRANSITION)~="number" or H.NETWORK_LEAVE_TRANSITION==0
                or type(deps.invoke_void_detail)~="function" then
                wait_for("Transition cancellation/leave native contract unavailable."); return
            end
            if type(deps.invoke_bool_detail)~="function" then
                wait_for("Detailed native BOOL dispatch unavailable."); return
            end
            if type(deps.transition_dispatch_status)=="function" then
                local ok,available,why=pcall(deps.transition_dispatch_status)
                if not ok or available~=true then
                    wait_for(not ok and tostring(available) or why or "Transition native adapters unavailable."); return
                end
            end
            request.phase,request.dispatch_started="dispatching",true
            recovery.phase,recovery.detail="dispatching","Submitting native transition cancellation; completion unverified."
            local invite=recovery_bool(RECOVERY_NATIVE.awaiting_invite)
            if not request_current(request) then return end
            if invite==true then
                local invoked,accepted,raw,err=pcall(deps.invoke_void_detail,RECOVERY_NATIVE.cancel_invite)
                if not request_current(request) then return end
                if not invoked or accepted~=true or raw==false or err~=nil then
                    finish_recovery("failed","Pending invite cancellation failed: "..tostring(not invoked and accepted or err or raw or accepted)); return
                end
                request.invite_cancelled=true
            end
            local invoked,accepted,raw,err=pcall(deps.invoke_void_detail,H.NETWORK_CANCEL_TRANSITION_MATCHMAKING)
            if not request_current(request) then return end
            if not invoked or accepted~=true or raw==false or err~=nil then
                finish_recovery("failed","Transition matchmaking cancellation failed: "..tostring(not invoked and accepted or err or raw or accepted)); return
            end
            local active,why=transition_active()
            if not request_current(request) then return end
            if active==nil then finish_recovery("failed","Cannot read transition after cancellation: "..tostring(why)); return end
            request.no_active_transition=request.no_active_transition~=false and not active
            if active then
                local left,leave_error=recovery_bool(H.NETWORK_LEAVE_TRANSITION)
                if not request_current(request) then return end
                if left~=true then
                    if leave_error then finish_recovery("failed","NETWORK_LEAVE_TRANSITION failed: "..tostring(leave_error)); return end
                    request.phase="queued"
                    wait_for("GTA has not accepted transition leave yet."); return
                end
            end
            online_capabilities.unstuck={available=true,reason="Native cancellation submitted; transition exit requires observation."}
            request.phase,request.native_fallback,request.retry_at="observing",true,now+500
            recovery.phase,recovery.detail="observing","Native cancellation/leave submitted; observing transition exit."
            return
        end
        local active,why=transition_active()
        if not request_current(request) then return end
        if active==nil then finish_recovery("failed","Cannot verify transition exit: "..tostring(why)); return end
        local playable,waiting=false,"Transition is still active."
        if not active then playable,waiting=recovery_playable() end
        if not request_current(request) then return end
        if active or not playable then
            request.waiting_reason=waiting
            recovery.waiting_reason,recovery.detail=waiting,"Recovery pending: "..waiting
            -- Reissue only the native fallback, at most twice a second. A host
            -- callback is never repeated after it has accepted a request.
            if request.native_fallback and now>=(request.retry_at or now+500) then request.phase="queued" end
            return
        end
        -- Retain the active request through cleanup. The phase prevents a
        -- reentrant frame from cleaning twice and lifecycle cancellation wins.
        request.phase="cleaning"
        if type(deps.on_session_change)=="function" then
            local ok,result,detail=pcall(deps.on_session_change)
            if not request_current(request) then return end
            if not ok or result==false then
                finish_recovery("failed","Transition exit observed, but session cleanup failed: "..tostring(detail or result)); return
            end
        else
            finish_recovery("failed","Transition exit observed, but session cleanup callback is unavailable."); return
        end
        finish_recovery(request.no_active_transition and "no_transition" or "observed",request.kind=="restart"
            and "Freemode replacement and visible, controllable Online gameplay observed; same-session identity and backend health remain unverified." or request.no_active_transition
            and "No active transition detected; Online player control and a visible screen observed without an active warning."
            or "Transition flags cleared; Online player control and a visible screen observed without an active warning.")
    end
    local api = {
        State = State,
        RegisterReadoutFeatures = register_readouts,
    }

    function api.RegisterFeatures()
        return register_readouts()
    end

    function api.RegisteredCount() return State.registered_count end

    function api.IsOn(key) return is_on(key) end

    function api.GetFeature(key) return F[key] end

    function api.StopLobbyVehicleSpawner()
        pcall(request_lobby_spawner,false)
        lobby_retry_at=0
        ToggleState.session_vehicle_spawner=false
        local feature=F.session_vehicle_spawner
        if feature then pcall(function()if feature:IsToggled()then feature:Toggle(false)end end)end
    end

    function api.FastTick(now)
        if not started then return end
        orbital.Tick(now)
        respawn_map.Tick(now)
        railgun_filter.Tick(now)
        probe_providers()
        phone_text.Tick(now)
        local phone_requested,phone_status,phone_detail=phone_text.Status()
        if phone_status~=phone_text_last_status then
            phone_text_last_status=phone_status
            log_info("Phone Text Punctuation status="..phone_status.." "..phone_detail)
        end
        -- Preserve the visible/user-requested toggle across phone resource
        -- lifetimes. Status may move through WAITING/UNAVAILABLE, but CScript no
        -- longer silently flips the option off after a text-box reload.
        if phone_status=="UNAVAILABLE" and phone_status~=phone_text_last_warned then
            phone_text_last_warned=phone_status
            log_warn("Phone Text Punctuation: "..phone_detail)
            toast(phone_detail)
        elseif phone_status~="UNAVAILABLE" then
            phone_text_last_warned=nil
        end
        sync_spoofing(now, false)
        refresh(now, false)
        local organization = State.organization
        local organization_active = organization.bypass_enabled == true
            or organization.interaction_requested == true
            or organization.acquire_pending == true
            or (tonumber(now) or now_ms()) - (tonumber(organization.last_visible_ms) or -100000) <= 5000
        if organization_active then
            refresh_organization(now, false)
            maintain_organization_bypass(now, false)
        end
    end

    function api.HandleRespawnCandidate(sender,args)
        if not started or not is_on("session_respawn_prediction") then return false end
        -- Cheap event filter before inspecting sender identity or coordinates.
        if type(args)~="table" or math.type(args[1])~="integer"
            or (args[1]&0xFFFFFFFF)~=((-1013606569)&0xFFFFFFFF) then return false end
        local ok,id,key,request=pcall(respawn_host.candidate,sender,args)
        if ok and id~=nil then respawn_map.Candidate(id,key,request,now_ms())end
        return false
    end
    function api.ResetRespawnMap() respawn_map.Reset() end
    function api.RespawnMapSnapshot() return respawn_map.Snapshot() end
    function api.IsScriptedScreenObserverRegistered() return scripted_screen_observer_registered end

    function api.GetForceScriptHostStatus() return force_scripthost.Snapshot() end
    function api.ResetForceScriptHost() force_scripthost.Reset() end

    function api.OrbitalSnapshot()return orbital.Snapshot()end
    function api.OrbitalCanHandoff()return orbital.CanHandoff()end
    function api.StopOrbital()
        orbital.Reset("Orbital features stopped.")
        for _,key in ipairs({"session_block_orbital_room","session_detect_orbital"})do
            ToggleState[key]=false
            if F[key]then pcall(function()F[key]:Toggle(false)end)end
        end
    end

    local perf = module_context and module_context.Performance
    if perf and type(perf.Wrap) == "function" then
        orbital.Tick = perf.Wrap("session.orbital", orbital.Tick, 127)
        force_scripthost.Tick = perf.Wrap("session.force_host", force_scripthost.Tick, 127)
        probe_providers = perf.Wrap("session.providers", probe_providers, 127)
        maintain_auto_accept_confirmation = perf.Wrap("session.confirmation", maintain_auto_accept_confirmation, 127)
        maintain_invite_filter = perf.Wrap("session.invite_filter", maintain_invite_filter, 127)
    end
    function api.FrameRequested()
        if not orbital.CanHandoff()then return true end
        if started and orbital.Requested()then return true end
        if started and not force_scripthost.IsCanceled() and is_on("session_force_scripthost") then return true end
        if exact_rejoin and (rejoin_queued or rejoin_cancel or exact_rejoin:HasWork())then return true end
        if local_nat.HasWork() then return true end
        if phone_text.HasWork() then return true end
        if started and is_on("session_respawn_prediction") and respawn_map.HasPending() then return true end
        if respawn_map.HasCleanup() and (not started or not is_on("session_respawn_prediction")) then return true end
        if not started then
            return native_restart.Snapshot().pending == true or interaction.Snapshot().cleanup_debt>0 or bst_collection.HasWork()
                or State.organization.last_limit_applied ~= nil
        end
        return phone_gate_owner ~= nil or State.phone_calls.active == true or State.confirmation.active == true
            or State.organization.pending_request ~= nil or State.organization.pending_host_request == true
            or recovery.request ~= nil or native_restart.Snapshot().pending == true
            or interaction.HasWork() or bst_collection.HasWork()
            or (not State.organization.bypass_enabled and State.organization.last_limit_applied ~= nil)
            or is_on("block_automated_job_invites")
            or is_on("auto_accept_confirmation")
    end

    function api.FrameTick(now)
        now = tonumber(now) or now_ms()
        orbital.Tick(now)
        force_scripthost.Tick(now)
        maintain_exact_rejoin(now)
        service_nat(now) -- submits a native job; also drains restoration after Stop
        bst_collection.Tick(now)
        phone_text.Tick(now) -- also drains a loading lease after Stop on this native thread
        if started and is_on("session_respawn_prediction") and respawn_map.HasPending() then respawn_map.Tick(now,true) end
        if respawn_map.HasCleanup() and (not started or not is_on("session_respawn_prediction")) then respawn_map.Tick(now) end
        if not started then
            maintain_native_restart(now)
            local menu=interaction.Snapshot()
            if menu.requested then interaction.SetEnabled(false) end
            if menu.cleanup_debt>0 and (now<stopped_interaction_ms or now-stopped_interaction_ms>=100) then
                stopped_interaction_ms=now
                interaction.Tick(now)
            end
            if State.organization.last_limit_applied ~= nil then
                disable_organization_bypass("retry stopped restoration", false)
            end
            return
        end
        probe_providers()
        interaction.Tick(now)
        local menu_status=interaction.Snapshot()
        local menu_detail=tostring(menu_status.phase)..": "..tostring(menu_status.reason)
        if menu_status.requested and menu_detail~=interaction_last_status and now-interaction_last_log>=2000 then
            interaction_last_status,interaction_last_log=menu_detail,now
            log_info("Interaction menu "..menu_detail.."; applied="..tostring(menu_status.menu_gates_applied)
                .."; pending cleanup="..tostring(menu_status.cleanup_debt))
        elseif not menu_status.requested then interaction_last_status=nil end
        if not started then return end
        maintain_native_restart(now)
        if not started then return end
        maintain_recovery(now)
        if not started then return end
        -- Input first: phone queue work must not delay warning detection.
        maintain_auto_accept_confirmation(now)
        if not started then return end
        maintain_disabled_phone_calls(now)
        if not started then return end
        maintain_invite_filter(now)
        if not started then return end
        local organization = State.organization
        local request = organization.pending_request
        if request ~= nil then
            organization.pending_request = nil
            local applied, detail = apply_organization_request(request)
            if State.organization == organization and applied ~= true then organization.last_error = detail end
            -- One bounded compensation if a callback queued Off inside SetInt.
            -- Do not expose an enabled override until another frame catches up.
            if State.organization == organization and organization.pending_request == false then
                organization.pending_request, organization.pending_host_request = nil, nil
                disable_organization_bypass("cancelled during activation", false)
            end
        end
        if started and State.organization == organization and organization.pending_host_request then
            organization.pending_host_request = nil
            acquire_organization_host()
        end
        if started and State.organization==organization and not organization.bypass_enabled
            and organization.last_limit_applied~=nil and organization.pending_request==nil then
            disable_organization_bypass("retry pending restoration",false)
        end
    end

    function api.GetPlayersSnapshot()
        State.last_visible_ms = now_ms()
        if State.render_snapshot == nil then publish_snapshot() end
        return State.render_snapshot
    end

    function api.GetOrganizationStatus(force)
        local now = now_ms()
        State.last_visible_ms = now
        State.organization.last_visible_ms = now
        -- ON_PRESENT receives detached state only. Explicit true is reserved
        -- for gameplay-thread diagnostics and the internal request service.
        if force == true then refresh(now, true); refresh_organization(now, true) end
        local state = State.organization
        return {
            current_role = state.current_role,
            registered = state.registered,
            session_limit = state.session_limit,
            normal_limit = state.normal_limit,
            effective_limit = state.effective_limit,
            eligible = state.eligible,
            local_suspension = state.local_suspension,
            authority = state.authority,
            status = state.status,
            bypass_supported = state.normal_limit > 0 and state.normal_limit <= ORGANIZATION_SOURCE.roster_capacity
                and state.status ~= "CAPACITY_BLOCKED" and state.status ~= "UNAVAILABLE",
            physical_capacity = ORGANIZATION_SOURCE.roster_capacity,
            unlimited_supported = false,
            bypass_enabled = state.bypass_enabled,
            bypass_active = state.bypass_active,
            override_applied = state.override_applied,
            published_count = state.published_count,
            script_host = state.script_host,
            freemode_host_id = state.freemode_host_id,
            freemode_host_name = state.freemode_host_name,
            requires_script_host = false,
            original_limit = state.original_limit,
            accepted_extra = state.accepted_extra,
            revocation_suppressed = state.revocation_suppressed,
            registration_observed = state.registration_observed,
            in_host_roster = state.in_host_roster,
            last_result = state.last_result,
            last_error = state.last_error,
            acquire_pending = state.acquire_pending,
            pending_request = state.pending_request,
            reason = state.last_result or "Local registration is observed separately from the bounded host roster.",
            source = ORGANIZATION_SOURCE.source,
        }
    end

    function api.SetInteractionMenuAvailability(enabled)
        if enabled==true and not started then return false,"Session controller is stopped." end
        local ok,reason=interaction.SetEnabled(enabled)
        if ok~=true then return false,reason end
        bst_collection.SetEnabled(enabled)
        local organization = State.organization
        organization.interaction_requested = enabled
        -- Local full-roster admission is owned by the paired script controller.
        -- Keep the older bounded tunable feature independent of this request.
        organization.pending_request = organization.manual_requested == true
        if organization.pending_request == false then organization.pending_host_request = nil end
        return true,enabled and "Local menu availability, BST collection and extra organization admission queued."
            or "Owned menu restoration queued; independent organization requests are preserved."
    end

    function api.GetInteractionMenuAvailability()
        local view=interaction.Snapshot()
        view.quarantined=false
        view.bst_collection=bst_collection.Snapshot()
        local admission = api.GetOrganizationStatus()
        admission.requested = State.organization.interaction_requested == true
        view.admission = admission
        view.capabilities = {
            registration = {supported = view.admission_applied == true and view.suspension_guard_applied == true,
                verified = admission.registration_observed == true, extra_observed = admission.accepted_extra == true,
                physical_capacity = ORGANIZATION_SOURCE.roster_capacity,
                detail = admission.registration_observed and "Self-owned organization observed in GTA's player state."
                    or "Normal registration callbacks retained; success requires an observed self-owned role."},
            bst_collection = {supported=true, verified=true,
                active=view.bst_collection.applied, detail="Collection timing guard; stock request cleanup retained."},
            bst_delivery = {supported = false, verified = false, detail = "Stock delivery and uncollected-drop limits remain unchanged."},
            passive_with_organization = {supported = false, verified = false,
                detail = "No verified Passive Mode controller compatible with CEO/MC membership."},
        }
        view.registration_verified = admission.registration_observed == true
        view.detail=view.applied and "Local menu availability and extra organization admission active." or view.reason
        view.collection_detail=view.bst_collection.reason
        view.execution_detail = INTERACTION_EXECUTION
        return view
    end

    function api.GetOnlineCapabilities()
        -- Cached descriptors only; detached copies protect the cache from UI edits.
        local snapshot={}
        for key,value in pairs(online_capabilities) do
            snapshot[key]={available=value.available,reason=value.reason}
            snapshot[key].requestable=started
        end
        local menu=interaction.Snapshot()
        snapshot.interaction={available=menu.available,requestable=started,reason=menu.reason,backend=menu.backend,scope=menu.scope}
        snapshot.restart.quarantined=false
        return snapshot
    end

    local function queue_recovery(kind)
        if not started then return false,"Session controller is stopped." end
        if recovery.request or native_restart.Snapshot().pending or rejoin_queued
            or (exact_rejoin and exact_rejoin:HasWork())then return false,"Online recovery already pending."end
        rejoin_visible=false
        -- Capture the request before a provider can leave/rejoin. These markers
        -- are for request diagnostics, not a guessed Rockstar session identity.
        recovery.request={kind=kind,phase="queued",generation=recovery.generation,
            origin_session=State.organization,origin_stamp=State.session_started_ms,provider=providers[kind]}
        recovery.phase,recovery.last_error,recovery.detail="queued",nil,"Manual "..kind.." request queued for the gameplay frame; completion unverified."
        recovery.action,recovery.attempts,recovery.waiting_reason,recovery.logged_wait=kind,0,nil,nil
        return true,recovery.detail
    end

    function api.UnstuckFromTransition()
        if recovery.request and recovery.request.kind=="unstuck" then return false,"Recovery already pending." end
        if recovery.request or native_restart.Snapshot().pending then
            cancel_recovery("User requested transition recovery.")
        end
        rejoin_queued,rejoin_visible=false,false
        if exact_rejoin and exact_rejoin:HasWork() then
            exact_rejoin:Cancel("User requested transition recovery.")
        end
        if exact_rejoin and exact_rejoin:HasWork() then return false,"Finishing previous session-resource cleanup." end
        return queue_recovery("unstuck")
    end

    function api.RejoinSession()
        if rejoin_draining then return false,"CScript is unloading."end
        if not started then return false,"Session controller is stopped."end
        if not exact_rejoin or online_rejoin_available~=true then return false,"Exact-session backend APIs are unavailable."end
        if recovery.request or native_restart.Snapshot().pending or rejoin_queued or exact_rejoin:HasWork()then
            return false,"Online recovery already pending."
        end
        -- UI queues only; the native frame captures, prepares and dispatches.
        rejoin_queued,rejoin_visible=true,true
        return true,"Session return queued; verifying the current session."
    end

    function api.RestartFreemodeScript()
        return queue_recovery("restart")
    end

    function api.GetRecoveryStatus()
        local observed=State.last_external_failure
        local external_failure=observed and {hash=observed.hash,observed_ms=observed.observed_ms,
            label=observed.label,message=observed.message} or nil
        if exact_rejoin and rejoin_visible then
            local view=exact_rejoin:Snapshot()
            return{freemode_restart=online_capabilities.restart.available,pending=rejoin_queued or view.pending,
                action="rejoin",phase=rejoin_queued and "queued"or view.phase,attempts=view.attempts,
                last_error=view.last_error and(exact_rejoin_host.LastError()or view.last_error)or nil,
                detail=exact_rejoin_host.LastError()or view.detail,native_rejoin=view,
                last_external_failure=external_failure}
        end
        local request=recovery.request
        local native=native_restart.Snapshot()
        return {freemode_restart=online_capabilities.restart.available,pending=request~=nil or native.pending,
            action=request and request.kind or native.pending and "restart" or recovery.action,
            phase=recovery.phase,last_error=recovery.last_error,detail=recovery.detail,native_restart=native,
            attempts=recovery.attempts or 0,waiting_reason=recovery.waiting_reason,
            deadline_ms=request and request.deadline or nil,next_attempt_ms=request and request.retry_at or nil,
            last_external_failure=external_failure}
    end

    function api.CancelOnlineRecovery(reason)
        rejoin_queued=false
        if exact_rejoin and exact_rejoin:HasWork()then rejoin_cancel=true end
        cancel_recovery(reason or "Online recovery cancelled.")
        api.SetInteractionMenuAvailability(false)
        local menu_ok,detail=interaction.Restore()
        local bst_ok=bst_collection.Stop()
        return menu_ok and bst_ok,not bst_ok and "BST collection restoration pending." or detail
    end

    function api.SetOrganizationLimitBypass(enabled)
        if not started then return false, "Organization controller is stopped." end
        local organization = State.organization
        organization.manual_requested = enabled == true
        organization.pending_request = organization.manual_requested
        if organization.pending_request == false then organization.pending_host_request = nil end
        return true, enabled == true and "Bounded organization tunable request queued; local extra admission is controlled by Interaction Menu availability."
            or "Organization limit disable queued for the gameplay frame."
    end

    function api.CancelOrganizationLimit()
        State.organization.manual_requested, State.organization.interaction_requested = false, false
        State.organization.pending_request, State.organization.pending_host_request = nil, nil
        return disable_organization_bypass("runtime stopped", false)
    end

    apply_organization_request = function(enabled)
        enabled = enabled == true
        if not enabled then return disable_organization_bypass("user disabled", false) end
        refresh(now_ms(), true)
        local state =
            refresh_organization(
                now_ms(),
                true
            )

        if state.status == "UNAVAILABLE" then
            state.bypass_enabled = true -- Keep intent armed; FastTick retries read-only validation.
            return false,
                state.last_error
                or "Organization state is unavailable."
        end
        if not State.online then
            state.bypass_enabled = true
            state.last_result = "Organization override armed; waiting for GTA Online."
            return true, state.last_result
        end
        if state.bypass_enabled then
            return true, state.last_result or "Limit bypass is active."
        end

        local captured,
        capture_error =
            capture_organization_baselines(
                state,
                state.normal_limit
            )

        if not captured then
            return false,
                tostring(capture_error)
                .. " No bypass state was changed."
        end
        state.bypass_enabled = true
        state.bypass_active = false
        state.accepted_extra = false
        state.last_error = nil
        state.last_result = "Organization override armed; checking the local admission tunable and current 10-slot roster."
        organization_log("ENABLED", state.last_result)
        local maintained, maintain_error = maintain_organization_bypass(now_ms(), true)
        if not maintained then
            -- This independent tunable feature remains bounded by the host roster.
            -- The local menu/retention controller does not use this scalar path.
            if state.status == "CAPACITY_BLOCKED" then return false, state.last_result end
            state.last_result = "Organization bypass is armed, but its initial local admission write was not verified: "
                .. tostring(maintain_error or state.last_error or "unknown error")
            return false, state.last_result
        end
        return true, state.last_result
    end

    function api.AcquireFreemodeScriptHost()
        if not started then return false, "Organization controller is stopped." end
        State.organization.pending_host_request = true
        return true, "Freemode Script Host request queued for the gameplay frame."
    end

    acquire_organization_host = function()
        local now =
            now_ms()

        refresh(
            now,
            true
        )

        local state =
            refresh_organization(
                now,
                true
            )

        if not State.online then
            return false,
                "Join a GTA Online session first."
        end

        if state.status == "UNAVAILABLE" then
            return false,
                state.last_error
                or "Organization state is unavailable."
        end

        local requested,
        request_detail =
            request_freemode_script_host(
                state,
                "Freemode Script Host requested once."
            )

        if not requested then
            state.last_error =
                request_detail

            return false,
                request_detail
        end

        local maintained,
        maintain_error =
            maintain_organization_bypass(
                now_ms(),
                true
            )

        if not maintained then
            state.last_error =
                maintain_error
                or state.last_error

            return false,
                state.last_error
                or "Organization maintenance could not be verified."
        end

        return true,
            request_detail
    end

    function api.PanicReset(cooperative_unload)
        api.StopOrbital()
        force_scripthost.Cancel()
        if F.session_force_scripthost then pcall(function()F.session_force_scripthost:Toggle(false)end)end
        ToggleState.session_force_scripthost=false
        rejoin_queued=false
        if exact_rejoin and exact_rejoin:HasWork()then rejoin_cancel=true end
        api.StopLobbyVehicleSpawner()
        respawn_map.Reset()
        if F.session_respawn_prediction then pcall(function() F.session_respawn_prediction:Toggle(false) end) end
        ToggleState.session_respawn_prediction=false
        railgun_filter.Reset()
        if F.session_disable_railgun then pcall(function() F.session_disable_railgun:Toggle(false) end) end
        ToggleState.session_disable_railgun=false
        selection_revision = selection_revision + 1
        cancel_recovery("Online recovery cancelled by Panic Reset.")
        local interaction_ok,interaction_detail=interaction.Stop()
        local bst_ok=bst_collection.Stop()
        local phone_ok = restore_phone_suppression()
        local text_ok = phone_text.Stop()
        -- Runtime's native-thread unload drain owns this deferred lease release.
        if cooperative_unload == true and phone_text.HasWork() then text_ok = true end
        State.confirmation = new_confirmation_state()
        State.phone_calls = new_phone_call_state()
        State.invite_filter = new_invite_filter_state()
        State.organization.manual_requested, State.organization.interaction_requested = false, false
        State.organization.pending_request, State.organization.pending_host_request = nil, nil
        local organization_ok, organization_detail = disable_organization_bypass("Panic Reset", false)
        local region_ok, region_detail = restore_spoof_owner("region")
        local nat_ok, nat_detail = restore_spoof_owner("nat")
        -- The cooperative unload drain waits for the queued native restoration.
        if cooperative_unload == true and local_nat.HasWork() then nat_ok = true end
        local native=native_restart.Snapshot()
        local native_clean=not native.pending and not native.resource_owned
            and not rejoin_queued and not rejoin_cancel and not(exact_rejoin and exact_rejoin:HasWork())
        return native_clean and interaction_ok and bst_ok and organization_ok and region_ok and nat_ok and phone_ok and text_ok,
            (not native_clean and "Freemode completion or loading-resource cleanup is still pending." or nil) or (not interaction_ok and interaction_detail or nil) or (not bst_ok and "BST collection restoration pending." or nil) or (not organization_ok and organization_detail or nil)
                or (not region_ok and region_detail or nil) or (not nat_ok and nat_detail or nil) or (not phone_ok and "Phone admission restoration is pending." or nil)
                or (not text_ok and "Phone text restoration is pending." or nil)
    end

    function api.RailgunFilterSnapshot() return railgun_filter.Snapshot() end

    function api.PhoneTextSnapshot() return phone_text.Snapshot() end
    function api.RestorePhoneText() return phone_text.Stop() end
    function api.DrainUnload(now)
        api.StopOrbital()
        orbital.Tick(tonumber(now)or now_ms())
        rejoin_draining,rejoin_queued=true,false
        if exact_rejoin and exact_rejoin:HasWork()then
            rejoin_cancel=true
            maintain_exact_rejoin(tonumber(now)or now_ms())
        end
        if rejoin_cancel or(exact_rejoin and exact_rejoin:HasWork())then
            return false,"Exact-session return restoration remains pending."
        end
        maintain_native_restart(tonumber(now) or now_ms())
        if native_restart.Snapshot().pending then return false,"Freemode restart or loading-resource cleanup remains pending." end
        api.StopLobbyVehicleSpawner()
        respawn_map.Reset()
        local interaction_ok,interaction_detail=interaction.Stop()
        bst_collection.Stop()
        phone_text.Stop()
        phone_text.Tick(tonumber(now) or now_ms())
        local_nat.RequestRestore("CScript unload")
        local nat = service_nat(now)
        if local_nat.HasWork() then return false, nat.detail or "NAT restoration is pending." end
        if respawn_map.HasCleanup() then return false,"Respawn marker removal is still unconfirmed." end
        if not interaction_ok then return false,interaction_detail or "Interaction instruction restoration is pending." end
        if not orbital.CanHandoff()then return false,"Orbital markers or room-door restoration remain pending." end
        return not phone_text.HasWork() and bst_collection.Snapshot().cleanup_debt==0
    end

    function api.PhoneFilterSnapshot()
        local result = { layout = State.invite_filter.layout, call_layout=State.phone_calls.layout or "NOT_PROBED",
            calls_blocked=State.phone_calls.blocks or 0, call_admission_active=State.phone_calls.active==true,
            call_restore_pending=phone_gate_owner~=nil and not is_on("block_automated_job_invites"),
            removed = State.invite_filter.removed,
            pre_presentation_live_verified = false, classifications = {} }
        for kind, count in pairs(State.invite_filter.classifications) do result.classifications[kind] = count end
        return result
    end

    function api.RestorePhoneSuppression()
        return restore_phone_suppression()
    end

    function api.NatSnapshot() return local_nat.Snapshot() end
    function api.HasNatWork() return local_nat.HasWork() end
    function api.CloseNatForForcedUnload()
        return local_nat.ForceClose("CScript forced teardown")
    end

    function api.ProbeNatBackend(force)
        if force ~= true and not is_on("network_spoof_nat") then
            return {available=false, deferred=true, scope="local-reported", authoritative_verified=false,
                remote_verified=false, detail="Not probed while Spoof NAT is off"}
        end
        local observed = local_nat.Probe()
        local view = local_nat.Snapshot()
        return {available=observed.ready == true, scope="local-reported", authoritative_verified=false,
            remote_verified=false, detail=observed.detail, value=observed.cache_value,
            persistent_value=observed.persistent_value, source_value=observed.source_value,
            observed=observed, labels=NAT_TYPES, status=view.status,
            local_report_verified=view.active == true and observed.ready == true
                and observed.cache_value == view.requested_value and observed.source_value == view.requested_value,
            local_propagation_verified=false, detector_state=observed.detector_state,
            branch_value=observed.branch_value,
            cleanup_pending=view.cleanup_pending == true
                or (view.in_flight == true and view.requested ~= true)}
    end

    function api.GetSpoofingStatus()
        local nat_view = local_nat.Snapshot()
        return {
            region = {
                state = State.spoofing.status.region.state,
                detail = State.spoofing.status.region.detail,
                active = State.spoofing.region.active == true,
            },
            nat = {
                state = nat_view.status,
                detail = nat_view.detail,
                active = nat_view.active == true,
                scope = "local-reported", authoritative_verified = false, remote_verified = false,
                backend = nat_view,
            },
        }
    end

    function api.RestoreSpoofing()
        local region_ok, region_detail = restore_spoof_owner("region")
        local nat_ok, nat_detail = restore_spoof_owner("nat")
        return region_ok and nat_ok, region_detail or nat_detail
    end

    function api.SelectPlayer(player_id)
        if selection_busy then return false end
        player_id = tonumber(player_id)
        if not player_id or not player_available(player_id) then return false end
        local selected_row
        for _, row in ipairs(State.rows) do
            if row.id == player_id then selected_row = row; break end
        end
        if not selected_row then return false end
        if State.selected ~= player_id then
            State.selected = player_id
            State.selected_snapshot = nil
            State.selected_distance_label = "Distance unavailable"
        end
        -- Publish from the roster cache; native detail sampling stays on FastTick.
        set_selected_row_labels(selected_row)
        publish_snapshot()
        State.dirty = true
        State.last_refresh = -100000
        if type(utils.SetSelectedPlayer) == "function" then
            pcall(utils.SetSelectedPlayer, player_id)
        end
        return true
    end

    function api.SelectPlayerIdentity(expected)
        if not started then return false, "Session module is stopped." end
        if selection_busy then return false, "Player selection is already in progress." end
        local function integer(value)
            return type(value) == "number" and value == value
                and value ~= math.huge and value ~= -math.huge and value % 1 == 0
        end
        if type(expected) ~= "table" then return false, "Player identity is unavailable." end
        -- Detached values only: no metatable-backed token or cached verification.
        local id, rid, key = rawget(expected, "id"), rawget(expected, "rid"), rawget(expected, "host_key")
        if not integer(id) or id < 0 or id > 31 or not integer(rid) or rid <= 0
            or not integer(key) or key == 0 then
            return false, "Complete player connection identity is required."
        end
        if not players or type(players.GetById) ~= "function"
            or type(utils.SetSelectedPlayer) ~= "function" then
            return false, "Cherax identity or selection API is unavailable."
        end
        local revision = selection_revision
        local generation = spoof_generation
        local function current()
            return started and revision == selection_revision and generation == spoof_generation
        end
        local function fresh_identity()
            if not current() then return false end
            local available_ok, available = pcall(player_available, id)
            if not available_ok or available ~= true or not current() then return false end
            local ok, fresh_rid, fresh_key = pcall(function()
                local player = players.GetById(id)
                local info = player and player:GetGamerInfo()
                return info and info.RockstarId, info and info.HostKey
            end)
            return ok and current() and fresh_rid == rid and fresh_key == key
        end
        selection_busy = true
        local ran, accepted, detail = pcall(function()
            local sampled_now = now_ms()
            refresh(sampled_now, true)
            if not current() then return false, "Player selection cancelled by a runtime or roster boundary." end
            local row
            for _, item in ipairs(State.rows) do if item.id == id then row = item; break end end
            local identity = State.identity_cache[id]
            if not row or row.rid ~= rid or row.host_key ~= key or not identity or not identity.copy_verified
                or not fresh_identity() then
                return false, "Player left, changed connection, or their fresh identity is unavailable."
            end
            -- Documented return is the previous PID, including zero; it is not
            -- a success boolean. Call exactly once and commit only after recheck.
            local set_ok, previous = pcall(utils.SetSelectedPlayer, id)
            if not set_ok or previous == false then return false, "Cherax player selection failed." end
            if not fresh_identity() then
                return false, "Player identity changed during Cherax selection; script selection was not committed."
            end
            if type(utils.GetSelectedPlayer) == "function" then
                local read_ok, selected = pcall(utils.GetSelectedPlayer)
                if not read_ok or selected ~= id or not current() then
                    return false, "Cherax player selection could not be verified."
                end
            end
            if not fresh_identity() then return false, "Player connection changed before selection publication." end
            State.selected = id
            State.selected_snapshot = nil
            State.selected_distance_label = "Distance unavailable"
            set_selected_row_labels(row)
            publish_snapshot(sampled_now)
            State.dirty = true
            State.last_refresh = -100000
            return true, "Player selected using fresh connection identity."
        end)
        selection_busy = false
        if not ran then return false, "Player identity selection is unavailable: " .. tostring(accepted) end
        return accepted, detail
    end

    local function clipboard(text, label)
        text = tostring(text or "")
        if text == "" then return false, "Nothing is available to copy." end
        if type(utils.SetClipBoardText) ~= "function" then return false, "Cherax clipboard API is unavailable." end
        local ok, err = pcall(utils.SetClipBoardText, text, tostring(label or "CScript"))
        if not ok then return false, tostring(err) end
        toast(tostring(label or "CScript") .. " copied.", 2600)
        return true
    end

    function api.SelectHost(kind)
        refresh(now_ms(), true)
        kind = tostring(kind or "session")
        local id = kind == "script" and tonumber(State.script_host_id) or tonumber(State.session_host_id)
        if not id or id < 0 or not player_available(id) then
            return false, (kind == "script" and "Script" or "Session") .. " host is unavailable."
        end
        return api.SelectPlayer(id)
    end

    function api.CopyRockstarId(kind, expected)
        kind = tostring(kind or "selected")
        local selected_copy = kind ~= "session_host" and kind ~= "script_host"
        if selected_copy then
            -- Legacy callers still capture their selection before refresh. UI
            -- callers supply the detached identity actually displayed on click.
            if expected == nil then
                local identity = State.identity_cache[State.selected]
                expected = identity and { id = State.selected, rid = identity.rid, host_key = identity.host_key }
            end
            if type(expected) ~= "table" or type(expected.id) ~= "number"
                or expected.id % 1 ~= 0 or expected.id < 0 or expected.id > 31
                or type(expected.rid) ~= "number" or expected.rid <= 0 then
                return false, "Selected player identity is unavailable."
            end
            expected = { id = expected.id, rid = expected.rid, host_key = expected.host_key }
        end
        refresh(now_ms(), true)
        local rid, label
        if kind == "session_host" then
            rid, label = State.session_host_rid, "Session host Rockstar ID"
        elseif kind == "script_host" then
            local identity = State.script_host_id and State.identity_cache[State.script_host_id]
            rid, label = identity and identity.rid or nil, "Script host Rockstar ID"
        else
            local identity = State.identity_cache[expected.id]
            local present = false
            for _, row in ipairs(State.rows) do if row.id == expected.id then present = true; break end end
            if not present or not player_available(expected.id) or not identity or not identity.copy_verified
                or identity.rid ~= expected.rid or identity.host_key ~= expected.host_key then
                return false, "Selected player left or their identity changed. Select them again."
            end
            rid, label = identity and identity.rid or nil, "Selected player Rockstar ID"
        end
        if not rid then return false, label .. " is unavailable." end
        return clipboard(tostring(rid), label)
    end

    function api.CopyRoster()
        refresh(now_ms(), true)
        if #(State.rows or {}) == 0 then return false, "Session roster is empty." end
        local lines = { "CScript Session Roster" }
        for _, row in ipairs(State.rows or {}) do
            local flags = {}
            if row.local_player then flags[#flags + 1] = "You" end
            if row.is_friend then flags[#flags + 1] = "Your Social Club Friend" end
            if row.session_host then flags[#flags + 1] = "Session Host" end
            if row.script_host then flags[#flags + 1] = "Script Host" end
            local suffix = #flags > 0 and (" [" .. table.concat(flags, ", ") .. "]") or ""
            lines[#lines + 1] = ("%s | PID %d | RID %s%s"):format(tostring(row.name), tonumber(row.id) or -1,
                tostring(row.rid or "unavailable"), suffix)
        end
        return clipboard(table.concat(lines, "\n"), "CScript session roster")
    end

    function api.CopyRecentHistory()
        refresh(now_ms(), true)
        if #(State.history or {}) == 0 then return false, "No session history has been observed yet." end
        local lines = { "CScript Recent Session History" }
        local first = math.max(1, #State.history - 19)
        for i = first, #State.history do
            local item = State.history[i]
            lines[#lines + 1] = ("%s | %s | PID %s | RID %s%s"):format(tostring(item.kind), tostring(item.name),
                tostring(item.player_id), tostring(item.rid or "unavailable"),
                item.detail and (" | " .. tostring(item.detail)) or "")
        end
        return clipboard(table.concat(lines, "\n"), "CScript session history")
    end

    function api.CopySummary()
        refresh(now_ms(), true)
        local age = State.session_started_ms and duration_label(now_ms() - State.session_started_ms) or "--"
        local lines = {
            "CScript Session Intelligence",
            "Status: " .. tostring(State.session_status or "Unknown"),
            "Players: " .. tostring(#(State.rows or {})),
            "Session host: " .. tostring(State.session_host_name or "Unknown")
            .. " | RID: " .. tostring(State.session_host_rid or "unknown"),
            "Script host: " .. tostring(State.script_host_name or "Unknown"),
            "Observed age: " .. tostring(age),
            "Host migrations: " .. tostring(State.host_migrations or 0),
            "Recent churn: " .. tostring(recent_churn(now_ms())),
            "Your Social Club friends in session: " .. tostring((State.render_snapshot or {}).friend_count or 0),
            "Remote-to-remote friendship: unavailable to the local client",
        }
        return clipboard(table.concat(lines, "\n"), "CScript session summary")
    end

    function api.MarkDirty()
        State.dirty = true
    end

    function api.ResetRoster()
        local restored,
            restore_detail =
                disable_organization_bypass(
                    "roster reset",
                    false
                )

        if not restored then
            return false,
                restore_detail
        end

        reset_roster_state()

        return true
    end

    function api.AppendOverlayLines(lines)
        -- Compatibility entry point; session HUD lines are disabled.
        return type(lines) == "table" and lines or lines
    end

    function api.OverlayRequested() return false end

    function api.LogStatus()
        local online = invoke_bool(H.NETWORK_IS_SESSION_STARTED)
        local count = invoke_int(H.NETWORK_GET_NUM_CONNECTED_PLAYERS)
        return online, count
    end

    function api.HandlePlayerJoin()
        selection_revision = selection_revision + 1
        State.dirty = true
        interaction.InvalidateBoss()
    end

    function api.HandlePlayerLeft()
        selection_revision = selection_revision + 1
        State.dirty = true
        interaction.InvalidateBoss()
        if type(deps.on_player_left) == "function" then
            local ok, err = pcall(deps.on_player_left)
            if not ok then log_error_once("session_player_left", err) end
        end
    end

    function api.HandleSessionChange()
        force_scripthost.Reset()
        api.StopLobbyVehicleSpawner()
        respawn_map.Reset()
        railgun_filter.Reset()
        local request=recovery.request
        -- Before dispatch, a boundary belongs to another operation. After our
        -- mutation starts, allow its one expected boundary; a second boundary
        -- cancels the request. No Online/ped/roster stability is required.
        if request and request.kind=="restart" then
            cancel_recovery("Freemode restart interrupted by a session change.")
        elseif request and request.dispatch_started and not request.boundary_seen then
            request.boundary_seen=true
        else cancel_recovery("Online recovery cancelled by an unrelated session boundary.") end
        interaction.Invalidate("Session resource changed; menu override remains armed.")
        bst_collection.Invalidate()
        State.organization.pending_request,State.organization.pending_host_request=nil,nil
        -- Keep an enabled persistent admission gate across the session boundary.
        -- reset_roster_state invalidates only pending call/action snapshots;
        -- final disable/Stop still restores our exact owned profile value.
        if not is_on("block_automated_job_invites") then restore_phone_suppression() end
        local manual_requested = State.organization.manual_requested == true
        local interaction_requested = interaction.Snapshot().requested == true
        local bypass_requested = manual_requested



        -- Session boundaries invalidate every captured
        -- freemode/global snapshot. Do not restore values
        -- captured from the previous session.
        reset_roster_state()

        -- Preserve the user's requested setting only.
        -- The new session must establish its own authority,
        -- baselines and host state.
        State.organization.manual_requested = manual_requested
        State.organization.interaction_requested = interaction_requested
        if bypass_requested then
            State.organization.bypass_enabled =
                true

            State.organization.last_result =
            "Organization bypass armed for the new session."

            State.organization.last_error =
                nil
        end

        if type(
                deps.on_session_change
            ) == "function" then
            local ok, err =
                pcall(
                    deps.on_session_change
                )

            if not ok then
                log_error_once(
                    "session_change",
                    err
                )
            end
        end
    end

    return api
end

local function unregister_event_handlers()
    if EventMgr
        and type(EventMgr.RemoveHandler)
        == "function" then
        for index =
        #event_handler_ids,
        1,
        -1 do
            pcall(
                EventMgr.RemoveHandler,
                event_handler_ids[index]
            )
        end
    end

    event_handler_ids = {}
    handlers_registered = false
    scripted_screen_observer_registered = false
end

local function register_event_handlers()
    if handlers_registered then
        return true
    end

    if not EventMgr
        or type(EventMgr.RegisterHandler)
        ~= "function"
        or not eLuaEvent then
        return false
    end

    local function register(event, callback)
        if event == nil then
            return true
        end

        local ok, id =
            pcall(
                EventMgr.RegisterHandler,
                event,
                callback
            )

        id =
            ok and tonumber(id) or nil

        if id == nil then
            return false
        end

        event_handler_ids[
        #event_handler_ids + 1
        ] = id

        return true
    end

    local success =
        register(
            eLuaEvent.ON_PLAYER_JOIN,
            function()
                if public_api then
                    public_api.HandlePlayerJoin()
                end
            end
        )
        and register(
            eLuaEvent.ON_PLAYER_LEFT,
            function()
                if public_api then
                    public_api.HandlePlayerLeft()
                end
            end
        )
        and register(
            eLuaEvent.ON_SESSION_CHANGE,
            function()
                if public_api then
                    public_api.HandleSessionChange()
                end
            end
        )

    if not success then
        unregister_event_handlers()
        return false
    end

    -- Optional observer: older hosts can retain the reservation fallback.
    -- Never block a scripted event, including errors in our observer.
    local candidate_registered=register(eLuaEvent.SCRIPTED_GAME_EVENT,function(sender,args)
        if public_api and type(public_api.HandleRespawnCandidate)=="function" then
            pcall(public_api.HandleRespawnCandidate,sender,args)
        end
        local player = module_context and module_context.CScript and module_context.CScript.Player
        if player and type(player.ObserveScriptedScreenReady)=="function" then
            pcall(player.ObserveScriptedScreenReady,sender,args)
        end
        return false
    end)
    scripted_screen_observer_registered = eLuaEvent.SCRIPTED_GAME_EVENT ~= nil and candidate_registered == true
    if not candidate_registered and dependencies and type(dependencies.log_info)=="function" then
        pcall(dependencies.log_info,"Respawn candidate observer unavailable; reservation fallback retained")
    end
    handlers_registered = true

    return true
end

local function publish_state(context)
    local root = context.State.Session
    if type(root) ~= "table" then
        root = {}
        context.State.Session = root
    end
    root.MigrationPhase = Module.MigrationPhase
    root.Runtime = State
    root.Started = started
    root.Bound = bound
    root.RegisteredCount = State.registered_count
end

function Module.BindCompatibility(bindings)
    if not module_context then error("session module must initialize before compatibility binding", 2) end
    if bound then return public_api end
    dependencies =
        bindings or {}

    public_api =
        create_session_system(
            dependencies
        )

    if not register_event_handlers() then
        public_api = nil
        dependencies = nil

        error(
            "session module could not register required event handlers",
            2
        )
    end

    bound = true
    module_context.CScript.Session = public_api
    module_context.Modules.Session = Module
    publish_state(module_context)
    return public_api
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table"
        or type(context.CScript) ~= "table" or type(context.Modules) ~= "table" then
        error("modules.session received an invalid context")
    end
    if module_context and module_context ~= context then
        error("modules.session is already initialized by another context")
    end
    module_context = context
    context.Modules.Session = Module
    publish_state(context)
end

function Module.Start()
    if not module_context then error("modules.session started before initialization") end
    started = true
    if dependencies and type(dependencies.log_info) == "function" then
        dependencies.log_info("Session spoofing/organization runtime initialized; LIVE_RETEST_REQUIRED.")
    end
    publish_state(module_context)
end

function Module.Stop()
    if public_api and public_api.StopOrbital then public_api.StopOrbital() end
    if public_api and public_api.StopLobbyVehicleSpawner then public_api.StopLobbyVehicleSpawner() end
    if public_api and public_api.ResetRespawnMap then public_api.ResetRespawnMap() end
    started = false -- Fence reentrant callbacks before cancellation/restoration.
    if public_api and public_api.ResetForceScriptHost then public_api.ResetForceScriptHost() end
    spoof_generation = spoof_generation + 1
    if public_api and public_api.CancelOnlineRecovery then public_api.CancelOnlineRecovery("Online recovery cancelled by Stop.") end
    -- Stop runtime execution and release the phone admission gate immediately.
    -- RESTORE still owns the other session feature restoration paths.

    if public_api and public_api.CancelOrganizationLimit then public_api.CancelOrganizationLimit() end
    if public_api and public_api.RestoreSpoofing then public_api.RestoreSpoofing() end
    if public_api and public_api.RestorePhoneSuppression then public_api.RestorePhoneSuppression() end
    if public_api and public_api.RestorePhoneText then public_api.RestorePhoneText() end

    if module_context then
        publish_state(
            module_context
        )
    end
end

function Module.CanHandoff()
    if public_api and public_api.OrbitalCanHandoff and not public_api.OrbitalCanHandoff()then return false end
    if online_rejoin_backend and online_rejoin_backend:HasWork()then return false end
    if online_restart_backend and online_restart_backend.Snapshot().pending then return false end
    if online_interaction_backend and online_interaction_backend.Snapshot().cleanup_debt>0 then return false end
    if online_bst_collection_backend and online_bst_collection_backend.Snapshot().cleanup_debt>0 then return false end
    if not public_api then return true end
    if public_api.HasNatWork and public_api.HasNatWork() then return false end
    local view=public_api.RespawnMapSnapshot()
    return view and view.estimated==0 and view.observed==0 and view.incoming==0
        and view.reserved==0 and view.candidates==0
end

function Module.Restore(context)
    if online_rejoin_backend and online_rejoin_backend:HasWork()then
        return false,"Exact-session return restoration remains pending; session ownership retained."
    end
    spoof_generation = spoof_generation + 1
    context = context or module_context
    started = false
    if public_api and type(public_api.PanicReset) == "function" then public_api.PanicReset() end
    if online_interaction_backend and online_interaction_backend.Snapshot().cleanup_debt>0 then
        local detail = "Interaction instruction restoration is pending; session ownership retained."
        if dependencies and type(dependencies.log_warn) == "function" then dependencies.log_warn(detail) end
        return false, detail
    end
    if online_restart_backend and online_restart_backend.Snapshot().pending then
        return false,"Freemode restart or loading-resource cleanup remains pending; session ownership retained."
    end
    if public_api and public_api.CloseNatForForcedUnload then public_api.CloseNatForForcedUnload() end
    if public_api and public_api.HasNatWork and public_api.HasNatWork() then
        local detail = "NAT restoration is pending; session state retained. Use cooperative CScript unload."
        if dependencies and type(dependencies.log_warn) == "function" then dependencies.log_warn(detail) end
        return false, detail
    end
    if public_api and public_api.OrbitalCanHandoff and not public_api.OrbitalCanHandoff()then
        return false,"Orbital markers or room-door restoration remain pending; session ownership retained."
    end
    if not Module.CanHandoff() and dependencies and type(dependencies.log_warn)=="function" then
        dependencies.log_warn("Respawn markers remain unresolved during forced restore; old blip removal is not confirmed.")
    end
    unregister_event_handlers()

    reset_roster_state()
    if context and context.CScript and context.CScript.Session == public_api then context.CScript.Session = nil end
    if context and context.Modules and context.Modules.Session == Module then context.Modules.Session = nil end
    if context and context.State then context.State.Session = {} end
    module_context = nil
    public_api = nil
    dependencies = nil
    bound = false
    handlers_registered = false
    F = {}
    ToggleState = {}
    State = {
        registered_count = 0,
        readouts_registered = false,
        rows = {},
        selected = -1,
        dirty = true,
        last_refresh = -100000,
        last_visible_ms = -100000,
        selected_snapshot = nil,
        selected_name = "None",
        selected_id_label = "No player selected",
        selected_distance_label = "",
        selected_rid_label = "Rockstar ID unavailable",
        selected_friend_label = "Social Club friendship not checked yet.",
        count_label = "Players (0)",
        online = false,
        session_started_ms = nil,
        session_status = "Offline",
        session_host_id = -1,
        session_host_name = "Unknown",
        session_host_rid = nil,
        script_host_id = -1,
        script_host_name = "Unknown",
        host_migrations = 0,
        roster_initialized = false,
        known_players = {},
        identity_cache = {},
        history = {},
        render_snapshot = nil,
        organization = new_organization_state(),
        spoofing = new_spoofing_state(),
        confirmation = new_confirmation_state(),
        phone_calls = new_phone_call_state(),
        invite_filter = new_invite_filter_state(),
    }
end

return Module
]====],
    ["modules/orbital.lua"] = [====[
-- Orbital operator markers and the existing Facility room doors.
local Orbital = { Name = "modules.orbital", MigrationPhase = "17.75" }

function Orbital.Init(context)
    assert(type(context)=="table" and type(context.Modules)=="table","Orbital context unavailable")
    context.Modules.OrbitalCannon=Orbital
end

local function finite(v) return type(v)=="number" and v==v and math.abs(v)<100000 end
local function integer(v) return type(v)=="number" and v==v and v%1==0 end
local function position(v)
    if type(v)~="table" and type(v)~="userdata" then return nil end
    local ok,x,y,z=pcall(function()return v.x,v.y,v.z end)
    if ok and finite(x) and finite(y) and finite(z) then return {x=x,y=y,z=z} end
end
local function distance(a,b)
    return (a.x-b.x)^2+(a.y-b.y)^2+(a.z-b.z)^2
end
local function count(t) local n=0;for _ in pairs(t)do n=n+1 end;return n end
local function read(fn,...)
    if type(fn)~="function" then return nil end
    local ok,a,b,c=pcall(fn,...);if ok then return a,b,c end
end

-- Setters only change intent. The caller runs Tick from its native gameplay loop.
function Orbital.NewController(host)
    local api={}
    local detect,block=false,false
    local scope,next_tick,next_detect=nil,0,0
    local markers,pending,doors,operators={},{},{},{}
    local barrier_pending=false
    local detection_generation,detecting=0,false
    local state={detector="OFF",blocker="OFF",detail="",locked=0,retired_doors=0,
        stale_marker_creations=0,invalid_marker_tokens=0,operator_location_only=true,
        remote_aim_observed=false,marker_move_unconfirmed=0}
    local reset_pending=false
    local function queue_marker(row)
        if row and type(row.marker)=="table" then
            pending[row.marker]=pending[row.marker] or {attempts=0,next_due=0,pid=row.pid}
            row.marker=nil
        end
    end
    local function has_pending_player_marker(pid)
        for _,job in pairs(pending)do
            if job.pid==pid then return true end
        end
        return false
    end
    local function clear_markers()
        for _,row in pairs(markers)do queue_marker(row)end
        markers={};operators={}
    end
    local function clean_markers(now)
        -- Do not hammer REMOVE_BLIP on an unknown/unavailable native result.
        -- A removal lease stays pending until the host proves the blip gone or
        -- the exact saved marker token has been safely retired.
        for token,job in pairs(pending)do
            local due=tonumber(job.next_due) or 0
            if now>=due or due-now>10000 then
                if read(host.marker_remove,token)==true then
                    pending[token]=nil
                else
                    job.attempts=math.min(8,(job.attempts or 0)+1)
                    job.next_due=now+math.min(2000,250*2^math.min(3,job.attempts-1))
                end
            end
        end
    end
    local function restore_door(key,lease)
        if not lease.changed then doors[key]=nil;return end
        local observed=read(host.door_read,lease.door)
        if observed and observed.same==false then doors[key]=nil;return end
        if not observed or observed.same~=true then return end
        local restore_state=observed.state==1 and lease.before_state or nil
        local restore_ratio=finite(observed.ratio) and math.abs(observed.ratio)<0.03
            and lease.before_ratio or nil
        if restore_state==nil and restore_ratio==nil then doors[key]=nil;return end
        if observed.control~=true then read(host.door_request,lease.door);return end
        if read(host.door_write,lease.door,restore_state,restore_ratio)~=true then return end
        local after=read(host.door_read,lease.door)
        if after and after.same==true
            and (restore_state==nil or after.state==restore_state)
            and (restore_ratio==nil or finite(after.ratio) and math.abs(after.ratio-restore_ratio)<0.03) then
            doors[key]=nil
        end
    end
    local function maintain_doors()
        state.locked=0
        if not block then
            local cleanup=read(host.barrier_tick,false)
            barrier_pending=cleanup=="CLEANUP_PENDING" or (barrier_pending and cleanup~="OFF" and cleanup~=nil)
            for key,lease in pairs(doors)do restore_door(key,lease)end
            state.blocker=next(doors) and "RESTORING" or "OFF"
            state.detail=next(doors) and "Waiting to restore the room doors." or ""
            return
        end
        local found=read(host.discover) or {}
        for _,door in ipairs(found)do
            if type(door.key)=="string" and not doors[door.key] and count(doors)<(host.expected_doors or 2)then
                doors[door.key]={door=door}
            end
        end
        local waiting_control=false
        for key,lease in pairs(doors)do
            local observed=read(host.door_read,lease.door)
            if observed and observed.same==false then doors[key]=nil
            elseif observed and observed.same==true and observed.physics==true then
                if observed.state==1 and finite(observed.ratio) and math.abs(observed.ratio)<0.03 then
                    state.locked=state.locked+1
                elseif observed.control~=true then
                    waiting_control=true;read(host.door_request,lease.door)
                elseif integer(observed.state) and observed.state>=0 and observed.state<=6
                    and finite(observed.ratio) and math.abs(observed.ratio)<=1.01 then
                    if not lease.changed then
                        lease.before_state=observed.state;lease.before_ratio=observed.ratio
                        lease.changed=true
                    end
                    read(host.door_write,lease.door,1,0)
                    local after=read(host.door_read,lease.door)
                    if after and after.same==true and after.state==1
                        and finite(after.ratio) and math.abs(after.ratio)<0.03 then
                        state.locked=state.locked+1
                    end
                end
            end
        end
        if state.locked>0 then
            state.blocker=state.locked==(host.expected_doors or 2) and "LOCKED" or "PARTIAL"
            state.detail="Orb Cannon"
        elseif waiting_control then
            state.blocker="WAITING_CONTROL";state.detail="Waiting for control of the orbital room doors."
        else
            state.blocker="WAITING_ROOM";state.detail="Orb Cannon"
        end
        -- The visual barrier has its own lifetime and does not depend on
        -- both sliding panels being found by the door system.
        local barrier_status=read(host.barrier_tick,true)
        if barrier_status=="READY" or barrier_status=="WAITING_CONTROL"
            or barrier_status=="WAITING_MODEL" or barrier_status=="WAITING_ROOM"then barrier_pending=true end
        if barrier_status=="READY" then
            state.blocker=state.locked==(host.expected_doors or 2) and "BARRIER_AND_DOORS" or "BARRIER"
            state.detail="Entrance barrier placed in the loaded Facility. Other clients are not verified."
        elseif state.locked==0 and barrier_status=="WAITING_MODEL" then
            state.blocker="WAITING_MODEL";state.detail="Preparing orbital entrance barrier model."
        elseif state.locked==0 and barrier_status=="WAITING_CONTROL" then
            state.blocker="WAITING_CONTROL";state.detail="Waiting to secure the spawned entrance barrier."
        end
    end
    local function detect_players(now)
        if detecting then return end -- A host callback may synchronously re-enter Tick.
        detecting=true
        local generation=detection_generation
        local function current()
            return detection_generation==generation and detect==true
        end
        if not detect then
            clear_markers();state.detector="OFF";detecting=false;return
        end
        local prepared=read(host.prepare,now)
        if not current() then detecting=false;return end
        if prepared~=true then
            clear_markers();state.detector="WAITING_PROFILE";detecting=false;return
        end
        state.detector="WATCHING";operators={}
        local seen={}
        for pid=0,31 do
            if not current() then detecting=false;return end
            local row=read(host.sample,pid)
