        local list={};for i,row in ipairs(operators)do
            list[i]={id=row.id,name=row.name,position_known=row.position_known,
                position_kind=row.position_kind,position_source=row.position_source,
                aim_known=false,aim_source=row.aim_source or "UNAVAILABLE_REMOTE"}
        end
