            active=#list,operators=list,markers=count(markers),pending_markers=count(pending),
            doors=count(doors),expected_doors=host.expected_doors or 2,
            locked=state.locked,detail=state.detail,retired_doors=state.retired_doors,
            position_basis="Cherax_Players_GetCam_xy_estimate",aim_position_available=false,
            current_reticle_known=false,remote_aim_observed=false,
            stale_marker_creations=state.stale_marker_creations,
            invalid_marker_tokens=state.invalid_marker_tokens,
            marker_move_unconfirmed=state.marker_move_unconfirmed}
    end
    return api
end

local H={
