    PLAYER_ACTIVE=0xB8DFD30D6973E135,PLAYER_PED=0x43A66C31C68491C0,
    EXISTS=0x7239B21A38F536BA,MODEL=0x9F47B058362C84B5,COORDS=0x3FEF770D40960D5A,
    INTERIOR=0x2107BA504071A6BB,ENTITY_BLIP=0xBC8DBDCA2436F7E8,
    BLIP_EXISTS=0xA6DB27D19ECBB7DA,BLIP_COORDS=0x586AFE3FF72D996E,
    ADD_BLIP=0x5A039BB0BCA604B6,BLIP_SPRITE=0xDF735600A4696DAF,
    BLIP_READ_SPRITE=0x1FC877464A04FC4F,BLIP_TYPE=0xBE9B0959FFD0779B,
    BLIP_MOVE=0xAE2AF67E9D9AF65D,BLIP_DISPLAY=0x9029B2F3DA924928,
