    BLIP_NAME_END=0xBC38B49BCB83BC9B,BLIP_REMOVE=0x86A652570E5F25DD,
    FIND_DOOR=0x589F80B325CC82C5,DOOR_REGISTERED=0xC153C43EA202C8C1,
    DOOR_PHYSICS=0xDF97CDD4FC08FD34,DOOR_STATE=0x160AA1B32F6139B8,
    DOOR_RATIO=0x65499865FCA6E5EC,DOOR_SET_STATE=0x6BAB9442830C7F53,
    DOOR_SET_RATIO=0xB6E6FBA95C7324AC,DOOR_CONTROL=0xCB3C68ADB06195DF,
    DOOR_REQUEST=0x870DDFD5A4A796E4,
    CLOSEST_OBJECT=0xE143FA2249364369,
    REQUEST_MODEL=0x963D27A58DF860AC,HAS_MODEL_LOADED=0x98A4EB5D89A0C952,
    FREEZE_ENTITY_POSITION=0x428CA6DBD1094446,
    SET_ENTITY_COLLISION=0x1A9205C1B9EE827F,
    SET_ENTITY_COORDS_NO_OFFSET=0x239A3351AC1DA385,
    SET_ENTITY_HEADING=0x8E2530AA8ADA980E,
    SET_ENTITY_AS_MISSION_ENTITY=0xAD738C3085FE7E11,
    NETWORK_HAS_CONTROL=0x01BF60A500E28887,
    NETWORK_REQUEST_CONTROL=0xB69317BF5E782347,
    DELETE_OBJECT=0x539E0AE3E6634B9F,
