-- Current Enhanced freemode resource 985a416fac7d1106, func_18471.
-- This whole function tests the replicated use bit, not Facility presence.
local USE_SIGNATURE="2D 01 03 00 00 38 00 72 72 5D 17 17 00 56 15 00 38 00 61 F8 8F 28 49 D4 01 47 AD 01 71 82 56 04 00 72 2E 01 01 71 2E 01 01"
local USE_BASE,USE_STRIDE,USE_FIELD=2658296,468,429

function Orbital.New(deps)
    deps=deps or {}
    local N,M,G=deps.Natives or {},deps.Memory or {},deps.ScriptGlobal or {}
    local GTA,Players,Utils=deps.GTA or {},deps.Players or {},deps.Utils or {}
