        local ok,identity,name=pcall(function()
            local info=player:GetGamerInfo()
            if not info or not info.RockstarId or info.RockstarId==0
                or not info.HostKey or info.HostKey==0 or player.CxnId==nil then return nil end
            return tostring(info.RockstarId)..":"..tostring(info.HostKey)..":"..tostring(player.CxnId),player:GetName()
