        -- document that another client's scripted Orbital reticle is always
        -- replicated, so two consistent samples + facility separation are
        -- required. No fabricated coordinates or player-ped fallback.
        local camera=position(read(Players.GetCam,pid))
        local camera_rot=position(read(Players.GetCamRot,pid))
        local ped_pos
        local ped=n("Int",H.PLAYER_PED,pid)
        if integer(ped)and ped>0 and boolean(H.EXISTS,ped)==true then
            ped_pos=vector(H.COORDS,ped,false)
        end
        local plausible=camera and camera_rot
            and math.abs(camera.x)<6500 and math.abs(camera.y)<9000
            and camera.z>10 and camera.z<2500
            and finite(camera_rot.x) and camera_rot.x<=-15 and camera_rot.x>=-91
            and finite(camera_rot.y) and finite(camera_rot.z)
            and (not ped_pos or distance(camera,ped_pos)>90000)
        local time=tonumber(read(deps.time_ms))or 0
        local earlier=camera_candidates[pid]
        if not plausible or player_identity(pid)~=identity then
            camera_candidates[pid]=nil
