        -- Never claim the orbital cannon crosshair is synchronized without
        -- corroboration from the other player's client.
        local map_pos=confirmed and {x=camera.x,y=camera.y,z=0}or nil
        return {identity=identity,name=name,active=true,pos=map_pos,
            position_source=map_pos and "remote_cannon_camera" or "camera_unconfirmed",
