    end
    local issued={}
    local function marker_matches(token)
        if not issued[token] then return false end
        local exists=boolean(H.BLIP_EXISTS,token.handle)
        if exists==false then return false elseif exists~=true then return nil end
        local kind=n("Int",H.BLIP_TYPE,token.handle)
        local sprite=n("Int",H.BLIP_READ_SPRITE,token.handle)
        local pos=vector(H.BLIP_COORDS,token.handle)
        if not integer(kind) or not integer(sprite) or not pos then return nil end
        if kind~=token.kind or sprite~=token.sprite then return false end
        if distance(pos,token.pos)<0.01 then return true end
