    end
    function host.marker_create(row)
        local p=position(row.pos);if not p then return nil end
        if not (M.Alloc and M.Free and M.WriteInt) then return nil end
        local handle=n("Int",H.ADD_BLIP,p.x,p.y,p.z)
        if not integer(handle) or handle<=0 then return nil end
        local token={handle=handle,pos=p,kind=n("Int",H.BLIP_TYPE,handle),sprite=n("Int",H.BLIP_READ_SPRITE,handle)}
        issued[token]=true
        if n("Void",H.BLIP_SPRITE,handle,588) then token.sprite=588 else token.failed=true end
        if not n("Void",H.BLIP_DISPLAY,handle,2) then token.failed=true end
