    end
    local function object_identity(handle)
        if not integer(handle) or handle<=0 or boolean(H.EXISTS,handle)~=true then return nil end
        local model=n("Int",H.MODEL,handle)
        if not integer(model) or not models[model&0xFFFFFFFF] then return nil end
        local object=read(GTA.HandleToPointer,handle)
        local ok,address=pcall(function()return object and object:GetAddress()end)
        if not ok or not integer(address) or address<=0 then return nil end
