            M.WriteInt(p,0)
            if boolean(H.FIND_DOOR,identity.pos.x,identity.pos.y,identity.pos.z,identity.model,p)~=true then return nil end
            local hash=read(M.ReadUInt,p) or read(M.ReadInt,p)
            if integer(hash) and hash~=0 then return hash&0xFFFFFFFF end
