    end
    local room_doors={
        {name="iCannonRoomDoorLeftHash",pos={x=336.5099,y=4832.9575,z=-60.0041}},
        {name="iCannonRoomDoorRightHash",pos={x=335.0931,y=4834.9775,z=-60.0041}},
    }
    for _,door in ipairs(room_doors)do door.hash=read(Utils.Joaat,door.name)end
