        local now=tonumber(read(deps.time_ms)) or 0
        if now<next_nearest then return {}end
        next_nearest=now+500
        local found={}
        for _,profile in ipairs(room_doors)do
          for model in pairs(models)do
            local handle=n("Int",H.CLOSEST_OBJECT,profile.pos.x,profile.pos.y,profile.pos.z,20.0,model,false,false,false)
            local identity=object_identity(handle)
            -- Sliding panels move away from their registered anchors. Identify
            -- the system entry at its source-defined closed position, not at
            -- the current open panel position or an unrelated hangar panel.
            if identity and distance(identity.pos,profile.pos)<=400 and integer(profile.hash)then
                local anchor={pos=profile.pos,model=model}
