        if integer(model) and (model&0xFFFFFFFF)~=door.model then return {same=false}end
        local fresh=object_identity(door.handle)
        if not fresh then return nil end
        if fresh.address~=door.address or fresh.model~=door.model or fresh.interior~=door.interior
            or distance(fresh.pos,door.pos)>100 then return {same=false}end
