    -- The only active room restriction is the actual Facility door-system
    -- lock on verified, controllable sliding panels. Whether that state
    -- replicates into another player's Facility must be live-verified.
    function host.barrier_tick()
        return "OFF"
    end
    return Orbital.NewController(host)
end

return Orbital
