    { key = "apartment_entrance", name = "Owned Apartment", category = "Properties", sprite = 40 },
    { key = "arcade_entrance", name = "Owned Arcade", category = "Heists", sprite = 740 },
    { key = "facility_entrance", name = "Owned Facility", category = "Heists", sprite = 590 },
