local H = {
    DOES_ENTITY_EXIST = 0x7239B21A38F536BA,
    IS_ENTITY_DEAD = 0x5F9532F3B5CC2551,
    IS_PED_IN_ANY_VEHICLE = 0x997ABD671D25CA0B,
    IS_CUTSCENE_ACTIVE = 0x991251AFC3981F84,
    IS_CUTSCENE_PLAYING = 0xD3C2E180A40F031E,
    GET_ENTITY_COORDS = 0x3FEF770D40960D5A,
    GET_ENTITY_HEADING = 0xE83D4F9BA2A38914,
    GET_INTERIOR_FROM_ENTITY = 0x2107BA504071A6BB,
    REQUEST_COLLISION_AT_COORD = 0x07503F7948F491A7,
    SET_ENTITY_COORDS_NO_OFFSET = 0x239A3351AC1DA385,
    SET_ENTITY_HEADING = 0x8E2530AA8ADA980E,
    SET_ENTITY_VELOCITY = 0x1C99BB7B6E96D16F,
    GET_FIRST_BLIP_INFO_ID = 0x1BEDE233E6CD2A1F,
    GET_NEXT_BLIP_INFO_ID = 0x14F96AA50D6FBEA7,
    DOES_BLIP_EXIST = 0xA6DB27D19ECBB7DA,
    GET_BLIP_INFO_ID_COORD = 0xFA7C7F0AADF25D09,
    GET_BLIP_COLOUR = 0xDF729E8D20CF7327,
    IS_PLAYER_CONTROL_ON = 0x49C32D60007AFA47,
    IS_SCREEN_FADED_OUT = 0xB16FCE9DDC7BA182,
    IS_SCREEN_FADING_OUT = 0x797AC7CB535BA28F,
    GET_RENDERING_CAM = 0x5234F9F10919EABA,
    IS_GAMEPLAY_CAM_RENDERING = 0x39B5D1B10383F0C8,
    HAS_COLLISION_LOADED_AROUND_ENTITY = 0xE9676F61BC0B3321,
    IS_ENTITY_WAITING_FOR_WORLD_COLLISION = 0xD05BFF0C0A12C68F,
    GET_INTERIOR_AT_COORDS = 0xB0F7F8663821D9C3,
    IS_INTERIOR_READY = 0x6726BDCCC1932F0E,
}

local function raw_binding(name)
    local raw = module_context and module_context.Raw
    if raw and raw[name] ~= nil then return raw[name] end
    return type(_G) == "table" and _G[name] or nil
end

local function native(method, hash, ...)
    local natives = raw_binding("Natives")
    local callback = natives and natives[method]
    if type(callback) ~= "function" then return false, method .. " is unavailable" end
    local ok, a, b, c = pcall(callback, hash, ...)
    if not ok then return false, tostring(a) end
    return true, a, b, c
end

local function invoke_bool(hash, ...)
    local ok, value = native("InvokeBool", hash, ...)
    return ok and value == true
end

local function invoke_int(hash, ...)
    local ok, value = native("InvokeInt", hash, ...)
    return ok and tonumber(value) or nil
end

local function invoke_float(hash, ...)
    local ok, value = native("InvokeFloat", hash, ...)
    return ok and tonumber(value) or nil
end

local function invoke_vec3(hash, ...)
    local ok, value, y, z = native("InvokeV3", hash, ...)
    if not ok then return nil end
    if type(value) == "number" and type(y) == "number" and type(z) == "number" then
        return { x = value, y = y, z = z }
    end
    return value
end

local function invoke_void(hash, ...)
    local ok, result = native("InvokeVoid", hash, ...)
    return ok and result ~= false, result
end

local function vector_components(value)
    local kind = type(value)
    if kind ~= "table" and kind ~= "userdata" then return nil end
    local ok, x, y, z = pcall(function()
        return tonumber(value.x or value.X or value[1]),
            tonumber(value.y or value.Y or value[2]),
            tonumber(value.z or value.Z or value[3])
    end)
    if not ok or not (x and y and z) then return nil end
    if x ~= x or y ~= y or z ~= z or math.abs(x) > 10000 or math.abs(y) > 10000 or math.abs(z) > 5000 then return nil end
    return x, y, z
end

local function distance_sq(left, right)
    local lx, ly, lz = vector_components(left)
    local rx, ry, rz = vector_components(right)
    if not (lx and rx) then return nil end
    local dx, dy, dz = lx - rx, ly - ry, lz - rz
    return dx * dx + dy * dy + dz * dz
end

local function clean(value, maximum)
    return tostring(value or ""):gsub("[%c|]", " "):gsub("^%s+", ""):gsub("%s+$", ""):sub(1, maximum or 64)
end

local function canonical(content)
    content = tostring(content or "")
    if content:sub(1, 3) == "\239\187\191" then content = content:sub(4) end
    return content:gsub("\r\n", "\n"):gsub("\r", "\n")
end

local function encode(value)
    return tostring(value or ""):gsub("[%%|\r\n]", function(character)
        return ("%%%02X"):format(string.byte(character))
    end)
end

local function decode(value)
    return tostring(value or ""):gsub("%%(%x%x)", function(pair)
        return string.char(tonumber(pair, 16))
    end)
end

local function copy_location(item)
    local category = item.category == "Vehicles" and "Service Vehicles"
        or item.category == "Activities" and "Useful Locations" or item.category
    return {
        id = item.id, name = item.name, category = category, favorite = item.favorite == true,
        x = item.x, y = item.y, z = item.z, heading = item.heading, interior = item.interior,
        created_at = item.created_at,
    }
end

local function copy_locations(items)
    local result = {}
    for index, item in ipairs(items or {}) do result[index] = copy_location(item) end
    return result
end

local function notify(kind, message)
    local service = module_context and module_context.Notifications
    local callback = service and service[kind]
    if type(callback) == "function" then callback(tostring(message), kind == "Error" and 7000 or 4500) end
end

local function resolve_storage()
    if State.path and State.file_api then return true end
    local files = raw_binding("FileMgr")
    if not files or type(files.GetMenuRootPath) ~= "function" or type(files.CreateDir) ~= "function"
        or type(files.DoesFileExist) ~= "function" or type(files.ReadFileContent) ~= "function"
        or type(files.WriteFileContent) ~= "function" then
        return false, "required FileMgr saved-location APIs are unavailable"
    end
    local ok, root = pcall(files.GetMenuRootPath)
    if not ok or type(root) ~= "string" or root == "" then return false, "Cherax menu root is unavailable" end
    root = root:gsub("[\\/]+$", "")
    local data = root .. "\\Lua\\CScriptData"
    local directory = data .. "\\Teleports"
    for _, path in ipairs({ data, directory }) do
        -- Cherax may return false when an existing directory is already usable;
        -- only a thrown binding failure is authoritative here.
        local created = pcall(files.CreateDir, path)
        if not created then return false, "could not create the CScript teleport storage directory" end
    end
    State.file_api = {
        DoesFileExist = files.DoesFileExist,
        ReadFileContent = files.ReadFileContent,
        WriteFileContent = files.WriteFileContent,
    }
    State.path = directory .. "\\locations_v1.txt"
    return true
end

local function serialize(items)
    local lines = { FORMAT_HEADER }
    for _, item in ipairs(items or {}) do
        lines[#lines + 1] = table.concat({
            "location", encode(item.id), encode(item.category), item.favorite and "1" or "0", encode(item.name),
            ("%.6f"):format(item.x), ("%.6f"):format(item.y), ("%.6f"):format(item.z),
            ("%.3f"):format(item.heading or 0), tostring(math.floor(tonumber(item.interior) or 0)),
            tostring(math.floor(tonumber(item.created_at) or 0)),
        }, "|")
    end
    return table.concat(lines, "\n") .. "\n"
end

local function parse(content)
    content = canonical(content)
    local lines = {}; for line in (content .. "\n"):gmatch("(.-)\n") do lines[#lines + 1] = line end
    if lines[1] ~= FORMAT_HEADER then return nil, "saved-location header is invalid" end
    local result, ids = {}, {}
    for index = 2, #lines do
        local line = lines[index]
        if line ~= "" then
            local fields = {}; for value in (line .. "|"):gmatch("(.-)|") do fields[#fields + 1] = value end
            if fields[1] ~= "location" or #fields < 11 then return nil, "saved-location record is invalid" end
            local item = {
                id = clean(decode(fields[2]), 80), category = clean(decode(fields[3]), 24),
                favorite = fields[4] == "1", name = clean(decode(fields[5]), 64),
                x = tonumber(fields[6]), y = tonumber(fields[7]), z = tonumber(fields[8]),
                heading = tonumber(fields[9]), interior = tonumber(fields[10]), created_at = tonumber(fields[11]),
            }
            if item.id == "" or ids[item.id] or item.name == "" or not CATEGORY_SET[item.category]
                or not vector_components(item) then return nil, "saved-location values are invalid" end
            ids[item.id] = true
            result[#result + 1] = item
            if #result > MAX_LOCATIONS then return nil, "saved-location limit was exceeded" end
        end
    end
    return result
end

local function write_locations(candidate)
    local ready, err = resolve_storage(); if not ready then return false, err end
    local content = serialize(candidate)
    local ok, result = pcall(State.file_api.WriteFileContent, State.path, content, false)
    if not ok or result == false then return false, "saved-location write was rejected" end
    local read_ok, observed = pcall(State.file_api.ReadFileContent, State.path)
    if not read_ok or canonical(observed) ~= canonical(content) then return false, "saved-location post-write verification failed" end
    local parsed, parse_err = parse(observed)
    if not parsed then return false, parse_err end
    State.locations = parsed
    State.status, State.last_error = "READY", nil
    return true
end

local function load_locations()
    local ready, err = resolve_storage()
    if not ready then State.status, State.last_error = "UNAVAILABLE", err; return false, err end
    local exists_ok, exists = pcall(State.file_api.DoesFileExist, State.path)
    if not exists_ok then State.status, State.last_error = "READ_ERROR", "saved-location existence check failed"; return false, State.last_error end
    if not exists then State.locations, State.status, State.last_error = {}, "READY", nil; return true end
    local read_ok, content = pcall(State.file_api.ReadFileContent, State.path)
    if not read_ok then State.status, State.last_error = "READ_ERROR", "saved-location file could not be read"; return false, State.last_error end
    local parsed, parse_err = parse(content)
    if not parsed then State.status, State.last_error = "READ_ERROR", parse_err; return false, parse_err end
    State.locations, State.status, State.last_error = parsed, "READY", nil
    return true
end

local function local_ped()
    local gta = raw_binding("GTA")
    if not gta or type(gta.GetLocalPlayerId) ~= "function" then return nil end
    local ok, player = pcall(gta.GetLocalPlayerId)
    if not ok or tonumber(player) == nil then return nil end
    return invoke_int(0x50FAC3A3E030A6E1, tonumber(player))
end

local function safe_local_state(action)
    if not started then return nil, "Teleport Manager is not ready." end
    local ped = local_ped()
    if not ped or ped <= 0 or not invoke_bool(H.DOES_ENTITY_EXIST, ped) or invoke_bool(H.IS_ENTITY_DEAD, ped) then
        return nil, "The local player is not in a teleport-safe state."
    end
    local gta = raw_binding("GTA")
    if not (gta and type(gta.GetLocalPed) == "function" and type(gta.HandleToPointer) == "function") then
        return nil, "The local player's entity identity is unavailable."
    end
    local identity_ok, address = pcall(function()
        local current, resolved = gta.GetLocalPed(), gta.HandleToPointer(ped)
        if current == nil or resolved == nil then return nil end
        local current_address, resolved_address = current:GetAddress(), resolved:GetAddress()
        if type(current_address) ~= "number" or current_address <= 0 or current_address % 1 ~= 0
            or current_address ~= resolved_address then return nil end
        return current_address
    end)
    if not identity_ok or not address then return nil, "The local player handle does not match its current entity allocation." end
    if invoke_bool(H.IS_CUTSCENE_ACTIVE) or invoke_bool(H.IS_CUTSCENE_PLAYING) then
        return nil, "Finish the current cutscene before " .. tostring(action or "continuing") .. "."
    end
    local id_ok, player_id = pcall(gta.GetLocalPlayerId)
    local control_ok, control = native("InvokeBool", H.IS_PLAYER_CONTROL_ON, player_id)
    local camera_ok, gameplay_camera = native("InvokeBool", H.IS_GAMEPLAY_CAM_RENDERING)
    if not id_ok or not control_ok or control ~= true or invoke_bool(H.IS_SCREEN_FADED_OUT)
        or invoke_bool(H.IS_SCREEN_FADING_OUT) or not camera_ok or gameplay_camera ~= true then
        return nil, "GTA owns a camera, fade, or control transition. Finish it before " .. tostring(action or "continuing") .. "."
    end
    if invoke_bool(H.IS_PED_IN_ANY_VEHICLE, ped, false) then
        return nil, "Exit your current vehicle before " .. tostring(action or "continuing") .. "."
    end
    local coords = invoke_vec3(H.GET_ENTITY_COORDS, ped, false)
    local x, y, z = vector_components(coords)
    if not x then return nil, "The local player position is unavailable." end
    return {
        ped = ped, address = address, coords = { x = x, y = y, z = z },
        heading = invoke_float(H.GET_ENTITY_HEADING, ped) or 0,
        interior = invoke_int(H.GET_INTERIOR_FROM_ENTITY, ped) or 0,
    }
end


local function return_record_from_state(current)
    if not current or not current.coords then return nil end
    return {
        x = current.coords.x, y = current.coords.y, z = current.coords.z,
        heading = current.heading or 0, interior = current.interior or 0,
    }
end

local function return_last_teleport()
    local target = State.return_location
    if type(target) ~= "table" then
        return false, "No verified CScript teleport return point is available yet."
    end
    local current, err = safe_local_state("returning to the previous teleport point")
    if not current then notify("Warning", err); return false, err end
    local target_interior = tonumber(target.interior) or 0
    if target_interior ~= 0 and tonumber(current.interior) ~= target_interior then
        local message = "The previous return point belongs to an interior that is not currently loaded."
        notify("Warning", message); return false, message
    end
    local x, y, z = tonumber(target.x), tonumber(target.y), tonumber(target.z)
    if not (x and y and z) then return false, "The stored return point is invalid." end
    invoke_void(H.REQUEST_COLLISION_AT_COORD, x, y, z)
    local moved = invoke_void(H.SET_ENTITY_COORDS_NO_OFFSET, current.ped, x, y, z, false, false, false)
    if not moved then return false, "GTA rejected the local return teleport request." end
    invoke_void(H.SET_ENTITY_VELOCITY, current.ped, 0.0, 0.0, 0.0)
    invoke_void(H.SET_ENTITY_HEADING, current.ped, tonumber(target.heading) or 0)
    local observed = invoke_vec3(H.GET_ENTITY_COORDS, current.ped, false)
    local distance = distance_sq(observed, { x = x, y = y, z = z })
    if distance == nil or distance > 25.0 then
        invoke_void(H.SET_ENTITY_COORDS_NO_OFFSET, current.ped,
            current.coords.x, current.coords.y, current.coords.z, false, false, false)
        invoke_void(H.SET_ENTITY_HEADING, current.ped, current.heading)
        local message = "Return teleport verification failed; the original local position was restored."
        notify("Error", message); return false, message
    end
    State.return_location = return_record_from_state(current)
    State.last_action_error = nil
    notify("Success", "Returned to the previous CScript teleport point.")
    return true, "Returned to the previous CScript teleport point."
end

local function find_location(id)
    id = tostring(id or State.selected_id or "")
    for index, item in ipairs(State.locations or {}) do if item.id == id then return item, index end end
    return nil
end

local function refresh_current()
    local current, err = safe_local_state("capturing a location")
    if not current then State.current, State.last_action_error = nil, err; notify("Warning", err); return false, err end
    State.current, State.last_action_error = current, nil
    return true, current
end

local function save_current(name, category)
    if State.status ~= "READY" then return false, State.last_error or "saved-location storage is unavailable" end
    if #(State.locations or {}) >= MAX_LOCATIONS then return false, "The 24-location limit has been reached." end
    name, category = clean(name, 64), clean(category, 24)
    if name == "" then return false, "Enter a name before saving this location." end
    if not CATEGORY_SET[category] then return false, "Choose a valid location category." end
    local current, err = safe_local_state("saving a location")
    if not current then notify("Warning", err); return false, err end
    State.sequence = (tonumber(State.sequence) or 0) + 1
    local stamp = math.floor((os and os.time and os.time()) or 0)
    local candidate = copy_locations(State.locations)
    candidate[#candidate + 1] = {
        id = ("location-%d-%d"):format(stamp, State.sequence), name = name, category = category, favorite = false,
        x = current.coords.x, y = current.coords.y, z = current.coords.z,
        heading = current.heading, interior = current.interior, created_at = stamp,
    }
    local ok, result = write_locations(candidate)
    if not ok then State.last_action_error = result; notify("Error", result); return false, result end
    State.selected_id = candidate[#candidate].id
    State.current, State.last_action_error = current, nil
    notify("Success", "Saved local location: " .. name)
    return true
end

local function mutate_selected(operation)
    local item, index = find_location()
    if not item then return false, "Select a saved location first." end
    local candidate = copy_locations(State.locations)
    local ok, err = operation(candidate[index])
    if ok == false then return false, err end
    local written, result = write_locations(candidate)
    if not written then State.last_action_error = result; notify("Error", result); return false, result end
    State.last_action_error = nil
    return true
end

local function rename_selected(name)
    name = clean(name, 64)
    if name == "" then return false, "Enter a new name first." end
    local ok, err = mutate_selected(function(item) item.name = name; return true end)
    if ok then notify("Success", "Saved location renamed.") end
    return ok, err
end

local function toggle_favorite()
    local ok, err = mutate_selected(function(item) item.favorite = not item.favorite; return true end)
    if ok then notify("Success", "Favorite updated.") end
    return ok, err
end

local function delete_selected()
    local item, index = find_location()
    if not item then return false, "Select a saved location first." end
    local candidate = copy_locations(State.locations)
    table.remove(candidate, index)
    local ok, err = write_locations(candidate)
    if not ok then State.last_action_error = err; notify("Error", err); return false, err end
    State.selected_id, State.last_action_error = candidate[1] and candidate[1].id or nil, nil
    notify("Success", "Deleted CScript's saved location. GTA state was not changed.")
    return true
end

local function select_location(id)
    local item = find_location(id)
    if not item then return false end
    State.selected_id = item.id
    return true
end

local function teleport_selected()
    local item = find_location()
    if not item then return false, "Select a saved location first." end
    local current, err = safe_local_state("teleporting")
    if not current then notify("Warning", err); return false, err end
    if tonumber(item.interior) ~= 0 and tonumber(current.interior) ~= tonumber(item.interior) then
        local message = "This interior is not currently loaded. Enter the matching property first, then retry."
        notify("Warning", message); return false, message
    end
    local target = { x = item.x, y = item.y, z = item.z }
    invoke_void(H.REQUEST_COLLISION_AT_COORD, item.x, item.y, item.z)
    local moved = invoke_void(H.SET_ENTITY_COORDS_NO_OFFSET, current.ped, item.x, item.y, item.z, false, false, false)
    if not moved then notify("Error", "GTA rejected the local teleport request."); return false, "GTA rejected the local teleport request" end
    invoke_void(H.SET_ENTITY_VELOCITY, current.ped, 0.0, 0.0, 0.0)
    invoke_void(H.SET_ENTITY_HEADING, current.ped, item.heading or 0)
    local observed = invoke_vec3(H.GET_ENTITY_COORDS, current.ped, false)
    local distance = distance_sq(observed, target)
    if distance == nil or distance > 25.0 then
        invoke_void(H.SET_ENTITY_COORDS_NO_OFFSET, current.ped,
            current.coords.x, current.coords.y, current.coords.z, false, false, false)
        invoke_void(H.SET_ENTITY_HEADING, current.ped, current.heading)
        local message = "Teleport verification failed; the original local position was restored."
        notify("Error", message); return false, message
    end
    State.return_location = return_record_from_state(current)
    State.last_action_error = nil
    notify("Success", "Teleported to " .. item.name .. ".")
    return true
end

local KosatkaTravel
local function cancel_pending(reason)
    local kosatka_cancelled=KosatkaTravel and KosatkaTravel.Cancel(reason)
    local event=board_trip and board_trip.Cancel(reason)
    if event and State then State.last_destination_result=event end
    if not State or not State.pending_destination then return event~=nil or kosatka_cancelled==true end
    State.pending_destination = nil
    State.last_destination_result = { status = "CANCELLED", message = tostring(reason or "Teleport cancelled.") }
    return true
end

local function teleport_to_target(name, target, heading, require_interior)
    if State.pending_destination or board_trip and board_trip.Active() then return false, "A destination request is already awaiting placement." end
    local current, err = safe_local_state("teleporting")
    if not current then notify("Warning", err); return false, err end
    local x, y, z = vector_components(target)
    if not x then return false, "The destination coordinates are unavailable." end
    local destination_interior = invoke_int(H.GET_INTERIOR_AT_COORDS, x, y, z)
    if destination_interior == nil then return false, "The destination interior cannot be identified." end
    if require_interior and (current.interior <= 0 or destination_interior ~= current.interior
        or not invoke_bool(H.IS_INTERIOR_READY, current.interior)) then
        return false, "The planning blip must belong to the same loaded interior as the local player."
    end
    if destination_interior > 0 and not invoke_bool(H.IS_INTERIOR_READY, destination_interior) then
        return false, "The destination interior is not loaded; enter the property through its normal entrance first."
    end
    State.pending_destination = { name = name, target = { x = x, y = y, z = z },
        heading = heading, origin = current, interior = destination_interior, phase = "REQUESTED" }
    State.last_destination_result = { status = "REQUESTED", message = "Destination requested; waiting for streaming and placement verification." }
    return true, State.last_destination_result.message
end

-- Called only by the existing Heist Suite scheduler. No additional loop or
-- script job is registered. This controller owns coordinates only; it never
-- fades, freezes, clears tasks, cancels a camera, or takes GTA's control lock.
local function tick_destination(now)
    local pending = started and State and State.pending_destination
    if not pending then return end
    now = tonumber(now) or 0
    if pending.next_tick_ms and now < pending.next_tick_ms then return end
    pending.next_tick_ms = now + 100
    local current, err = safe_local_state("verifying a destination")
    if not current or current.ped ~= pending.origin.ped or current.address ~= pending.origin.address then
        cancel_pending(err or "Local player changed during destination placement.")
        notify("Warning", State.last_destination_result.message)
        return
    end
    local target = pending.target
    if pending.phase == "REQUESTED" then
        local origin_distance = distance_sq(current.coords, pending.origin.coords)
        if not origin_distance or origin_distance > 4 then
            cancel_pending("The player moved before the queued destination could be applied.")
            return
        end
        if not invoke_void(H.REQUEST_COLLISION_AT_COORD, target.x, target.y, target.z) then
            cancel_pending("GTA rejected the destination collision request.")
            return
        end
        pending.phase, pending.started_ms = "STREAMING", now
        return
    end
    if pending.phase == "STREAMING" then
        local origin_distance = distance_sq(current.coords, pending.origin.coords)
        if not origin_distance or origin_distance > 4 then
            cancel_pending("The player moved while destination collision was being requested.")
            return
        end
        if pending.heist_apartment then
            local live=resolve_heist_apartment()
            if not live or (distance_sq(live,target) or math.huge)>0.25 then
                cancel_pending("The owned apartment entrance changed before travel.");return
            end
        end
        if not invoke_void(H.SET_ENTITY_COORDS_NO_OFFSET, current.ped, target.x, target.y, target.z, false, false, false) then
            cancel_pending("GTA rejected the destination coordinates.")
            return
        end
        pending.phase = "VERIFYING"
        pending.applied_ms = now
        State.last_destination_result = { status = "VERIFYING", message = "Coordinates requested; confirming collision and destination placement." }
        return
    end
    local distance = distance_sq(current.coords, target)
    local collision_ok, loaded = native("InvokeBool", H.HAS_COLLISION_LOADED_AROUND_ENTITY, current.ped)
    local waiting_ok, waiting = native("InvokeBool", H.IS_ENTITY_WAITING_FOR_WORLD_COLLISION, current.ped)
    local interior_ready = pending.interior == 0 or invoke_bool(H.IS_INTERIOR_READY, pending.interior)
    if distance and distance <= 1 and collision_ok and loaded == true and waiting_ok and waiting == false
        and current.interior == pending.interior and interior_ready then
        pending.stable_samples = (pending.stable_samples or 0) + 1
        if pending.stable_samples >= 2 then
            if pending.heading then invoke_void(H.SET_ENTITY_HEADING, current.ped, pending.heading) end
            State.return_location = return_record_from_state(pending.origin)
            State.pending_destination, State.last_action_error = nil, nil
            State.last_destination_result = { status = "PLACEMENT_VERIFIED", name = pending.name,
                message = "Local placement and collision verified at " .. tostring(pending.name) .. "." }
            notify("Success", State.last_destination_result.message)
        end
        return
    end
    pending.stable_samples = 0
    if now - pending.applied_ms < 3000 then return end
    -- Roll back only while the same controllable ped remains at CScript's
    -- target. Independent movement or a GTA transition relinquishes ownership.
    local detail = "Destination placement was not verified."
    if distance and distance <= 4 and current.interior == pending.interior then
        local origin = pending.origin
        local accepted = invoke_void(H.SET_ENTITY_COORDS_NO_OFFSET, current.ped,
            origin.coords.x, origin.coords.y, origin.coords.z, false, false, false)
        local observed = accepted and invoke_vec3(H.GET_ENTITY_COORDS, current.ped, false)
        local restored_distance = observed and distance_sq(observed, origin.coords)
        detail = detail .. (restored_distance and restored_distance <= 1
            and " Original coordinates were restored and read back." or " Coordinate restoration could not be verified.")
    else detail = detail .. " GTA changed placement; no rollback was attempted." end
    State.pending_destination, State.last_action_error = nil, detail
    State.last_destination_result = { status = "FAILED", message = detail }
    notify("Warning", detail)
end

resolve_unique_blip=function(sprite, required_colour, area, waypoint_selection)
    local blip = invoke_int(H.GET_FIRST_BLIP_INFO_ID, sprite)
    local candidates, scanned = {}, 0
    while blip and blip > 0 and invoke_bool(H.DOES_BLIP_EXIST, blip) and scanned < 16 do
        scanned = scanned + 1
        local colour = invoke_int(H.GET_BLIP_COLOUR, blip)
        local coords = invoke_vec3(H.GET_BLIP_INFO_ID_COORD, blip)
        local x,y=vector_components(coords)
        local in_area=not area or x and ((x-area.x)^2+(y-area.y)^2)<=area.radius^2
        if colour ~= nil and colour ~= 3 and (not required_colour or colour==required_colour) and x and in_area then
            -- Multiple apartments can share one entrance; that is one destination.
            local duplicate=false
            for _,other in ipairs(candidates) do
                local x,y,z=vector_components(coords);local a,b,c=vector_components(other)
                if math.abs(x-a)<0.5 and math.abs(y-b)<0.5 and math.abs(z-c)<0.5 then duplicate=true;break end
            end
            if not duplicate then candidates[#candidates + 1] = coords end
        end
        blip = invoke_int(H.GET_NEXT_BLIP_INFO_ID, sprite)
    end
    if scanned >= 16 and blip and blip > 0 and invoke_bool(H.DOES_BLIP_EXIST, blip) then
        return nil, "Destination blip scan reached its bound before uniqueness could be proven.", #candidates
    end
    if #candidates == 0 then return nil, "No matching owned/active map destination is available.", 0 end
    if #candidates > 1 and waypoint_selection then
        local waypoint=invoke_int(H.GET_FIRST_BLIP_INFO_ID,8)
        local selected=waypoint and waypoint>0 and invoke_bool(H.DOES_BLIP_EXIST,waypoint)
            and invoke_vec3(H.GET_BLIP_INFO_ID_COORD,waypoint) or nil
        local wx,wy=vector_components(selected)
        local match,matches=nil,0
        if wx then
            for _,candidate in ipairs(candidates) do
                local x,y=vector_components(candidate)
                if (x-wx)^2+(y-wy)^2<=100 then match=candidate;matches=matches+1 end
            end
        end
        if matches==1 then return match,nil,1 end
        if matches>1 then return nil,"The waypoint matches more than one apartment entrance.",#candidates end
        local origin=invoke_vec3(H.GET_ENTITY_COORDS,local_ped(),false)
        local ox,oy=vector_components(origin)
        if not ox then return nil,"The current player position is unavailable.",#candidates end
        local nearest,minimum,tied=nil,math.huge,false
        for _,candidate in ipairs(candidates) do
            local x,y=vector_components(candidate)
            local distance=(x-ox)^2+(y-oy)^2
            if distance<minimum-0.000001 then nearest,minimum,tied=candidate,distance,false
            elseif math.abs(distance-minimum)<=0.000001 then tied=true end
        end
        if not tied then return nearest,nil,1 end
        return nil,"Two apartment entrances are equally close; set a waypoint on your choice.",#candidates
    end
    if #candidates > 1 then return nil, "More than one matching map destination is active; CScript will not guess which one is yours.", #candidates end
    return candidates[1], nil, 1
end

resolve_heist_apartment=function()
    local target,why,count=resolve_unique_blip(40,2,nil,true)
    if target or count~=0 then return target,why,count end
    -- Freemode uses colour 4 for owned apartments without active heist green.
    return resolve_unique_blip(40,4,nil,true)
end

local function refresh_destination_intelligence()
    local rows, ready, ambiguous, absent = {}, 0, 0, 0
    for _, destination in ipairs(DESTINATIONS) do
        local coords,err,count
        if destination.key=="active_heist_board" then
            count=0
            for _,family in ipairs({"apartment","casino","doomsday","cayo"}) do
                local prompt=inspect_heist_board_prompt(family)
                if prompt.available then count=count+1;coords={x=prompt.x,y=prompt.y,z=prompt.z} end
            end
            if count~=1 then coords=nil;err="Enter the selected heist's owned planning interior first." end
        elseif destination.key=="heist_apartment" then coords,err,count=resolve_heist_apartment()
        else coords,err,count=resolve_unique_blip(destination.sprite,destination.colour,destination.area) end
        local x, y, z = vector_components(coords)
        local status
        if x then status = "READY"; ready = ready + 1
        elseif tonumber(count) and tonumber(count) > 1 then status = "AMBIGUOUS"; ambiguous = ambiguous + 1
        else status = "ABSENT"; absent = absent + 1 end
        rows[#rows + 1] = { key=destination.key, name=destination.name, category=destination.category, sprite=destination.sprite,
            status=status, candidate_count=tonumber(count) or 0, x=x, y=y, z=z, error=err,
            requires_interior=destination.requires_interior == true }
    end
    State.destination_intelligence = { status="READY", items=rows, ready=ready, ambiguous=ambiguous, absent=absent,
        total=#DESTINATIONS, refreshed_at=os and type(os.time)=="function" and os.time() or 0,
        note="Explicit live HUD-blip resolution only. Cached coordinates are intelligence; teleport actions re-resolve the live blip and never trust stale cache." }
    return true, State.destination_intelligence
end

local function teleport_destination(key)
    if key=="active_heist_board" then
        local selected
        for _,family in ipairs({"apartment","casino","doomsday","cayo"}) do
            local prompt=inspect_heist_board_prompt(family)
            if prompt.available then
                if selected then return false,"More than one planning interior matched; select the heist first." end
                selected=prompt
            end
        end
        if not selected then return false,"Enter your owned heist planning interior first." end
        return start_board_trip(selected.family,selected.key)
    end
    local destination = DESTINATION_BY_KEY[tostring(key or "")]
    if not destination then return false, "Select a supported live destination." end
    if key=="heist_apartment" and inside_owned_heist_apartment() then
        local message="You are already inside your owned heist apartment."
        State.last_action_error=nil
        State.last_destination_result={status="ALREADY_INSIDE",name=destination.name,message=message}
        notify("Success",message)
        return true,message
    end
    local coords,err
    if key=="heist_apartment" then coords,err=resolve_heist_apartment()
    else coords,err=resolve_unique_blip(destination.sprite,destination.colour,destination.area) end
    if not coords then
        if key=="heist_apartment" and not err then err="No active heist apartment entrance is available." end
        notify("Warning", err); return false, err
    end
    local ok,message=teleport_to_target(destination.name, coords, destination.heading, destination.requires_interior)
    if ok and key=="heist_apartment" then State.pending_destination.heist_apartment=true end
    return ok,message
end

-- Bounded heist-property trip. Completion requires GTA property registration,
-- collision and control; streamed coordinates alone never count as admission.
function Module.NewBoardTrip(host)
    local active, last
    local api={}
    local function finish(status,message,recover)
        local s=active
        if s then
            s.completed=status=="COMPLETE"
            s.cleanup_result={status=status,message=message,recover=recover==true}
            if host.Cleanup(s,recover==true)==false then
                last={status="CLEANUP_PENDING",message="Board trip cleanup is pending; retrying owned streaming cleanup."}
                return last
            end
        end
        active=nil
        last={status=status,message=message}
        return last
    end
    function api.Status() return last or {status="IDLE"} end
    function api.Active() return active~=nil end
    function api.Cancel(reason)
        if active then return finish("CANCELLED",reason or "Board trip cancelled.",host.Valid(active)) end
    end
    function api.Start(family,now)
        if active then return false,"A board trip is already in progress." end
        local s,why=host.Capture();if not s then return false,why end
        local route,err=host.Resolve(family,s);if not route then return false,err end
        s.route,s.family,s.target,s.phase,s.deadline=route,family,route.target,
            route.exit_required and "LEAVING" or route.request and "REQUESTING" or "STREAMING",(now or 0)+(route.exit_required and 75000 or 45000)
        active=s;last={status="PENDING",message=route.exit_required and "Leaving your current interior before the captured board trip."
            or route.request and "Requesting GTA admission to your owned planning property." or route.admission and "Loading the active apartment entrance; waiting for GTA admission." or "Streaming your finale planning room."}
        return true,last.message
    end
    function api.Tick(now)
        local s=active;if not s then return end
        if s.cleanup_result then local r=s.cleanup_result;return finish(r.status,r.message,r.recover) end
        if not host.Valid(s) then return finish("CANCELLED","Board trip cancelled: player, character or session changed.",false) end
        if now>s.deadline then return finish("FAILED","Board trip timed out before GTA confirmed property admission.",true) end
        if s.phase=="LEAVING" then
            if s.exit_dispatching then return end
            if not s.exit_token then
                s.exit_dispatching=true
                local token,why=host.BeginExit(s,function()
                    if active~=s or s.cleanup_result or not host.Valid(s) then return false end
                    return active==s and not s.cleanup_result
                end)
                s.exit_dispatching=false
                if active~=s or s.cleanup_result then
                    if token then s.exit_token=token;host.CancelExit(s,"Board trip cancelled during exit capture.") end
                    return
                end
                if not token then return finish("FAILED",why or "The current interior exit is unavailable.",false) end
                s.exit_token=token
            end
            local exit=host.PollExit(s)
            if active~=s or s.cleanup_result then return end
            if exit.status=="COMPLETE" then
                local ready,why=host.AfterExit(s)
                if active~=s or s.cleanup_result then return end
                if not ready then return finish("CANCELLED",why or "The exit context changed before board admission.",false) end
                s.phase=s.route.request and "REQUESTING" or "STREAMING";s.deadline=now+45000
                last={status="PENDING",message="Current interior exited; continuing the captured board destination."}
                return last
            elseif not exit.active then return finish("FAILED",exit.detail or "The current interior exit did not complete.",false) end
            return
        elseif s.phase=="REQUESTING" then
            local accepted,why=host.Request(s)
            if accepted==false then return finish("FAILED",why or "GTA property admission request failed.",false) end
            if accepted then s.phase="ADMISSION";s.requested_at=now end
        elseif s.phase=="STREAMING" or s.phase=="BOARD_STREAMING" then
            local ready,why,admission=host.Prepare(s)
            if ready==false then
                if admission and not s.route.admission and host.Entrance then
                    local entrance,err=host.Entrance(s)
                    if not entrance then return finish("FAILED",err or why,true) end
                    s.route.admission=true;s.fallback=true;s.target=entrance;s.phase="STREAMING"
                    last={status="PENDING",message="Planning interior is not loaded; entering your owned property through GTA."}
                    return last
                end
                return finish("FAILED",why or "Property streaming failed.",true)
            end
            if not ready then return end
            local moved,err=host.Move(s)
            if moved==false then return finish("FAILED",err or "Property move failed.",true) end
            if not moved then return end
            s.phase=s.route.admission and s.phase=="STREAMING" and "ADMISSION" or "VERIFYING"
            s.moved_at=now
        elseif s.phase=="ADMISSION" then
            if host.Inside(s) then
                local board,why=host.Board(s)
                if not board then return end
                s.target=board;s.phase="BOARD_STREAMING"
            end
        elseif s.phase=="VERIFYING" then
            if host.Inside(s) and host.Arrived(s) then
                return finish("COMPLETE","GTA property admission, board placement and collision verified.",false)
            end
            if not s.route.admission and not host.Inside(s) and now-(s.moved_at or now)>=5000 and host.Entrance then
                local entrance,why=host.Entrance(s)
                if not entrance then return finish("FAILED",why or "GTA property admission was unavailable.",true) end
                s.route.admission=true;s.fallback=true;s.target=entrance;s.phase="STREAMING"
                s.deadline=now+45000
                last={status="PENDING",message="GTA needs normal property admission; entering your owned property before the board handoff."}
                return last
            end
        end
    end
    return api
end

