local function board_global(index)
    local g=raw_binding("ScriptGlobal")
    local ok,v=pcall(function() return g.GetInt(index) end)
    return ok and type(v)=="number" and v%1==0 and v or nil
end
local function property_local(index)
    local ok,v=pcall(function() return raw_binding("ScriptLocal").GetInt(raw_binding("Utils").Joaat("am_mp_property_int"),index) end)
    return ok and type(v)=="number" and v%1==0 and v or nil
end
local function board_scope()
    local core=module_context and module_context.CScript and module_context.CScript.Economy
    local ok,s,slot,pid=pcall(function()return core.Snapshot(),core.CurrentSlot(),raw_binding("GTA").GetLocalPlayerId()end)
    if not ok or type(s)~="table" or not s.online or not s.account_verified or (slot~=0 and slot~=1)
        or type(pid)~="number" or pid<0 or pid>31 then return nil end
    return {key=table.concat({tostring(s.account_id),tostring(s.generation),slot,pid},":"),pid=pid,slot=slot}
end
