-- Exterior property blips may be hidden after GTA admits the player.
-- Recognize that state from ownership/interior readback without moving anyone.
inside_owned_heist_apartment=function()
    if not started or State.pending_destination or State.cargo_request or board_trip and board_trip.Active() then return false end
    local scope=board_scope()
    if not scope then return false end
    local ped=local_ped()
    if not invoke_bool(H.DOES_ENTITY_EXIST,ped) or invoke_bool(H.IS_ENTITY_DEAD,ped) then return false end
    local utils=raw_binding("Utils")
    if not utils or type(utils.Joaat)~="function" then return false end
    local ok,hash=pcall(utils.Joaat,"am_mp_property_int")
    if not ok or invoke_int(0x2C83A9DA6BFFC4F9,hash)~=1 then return false end
    local property=property_local(496)
    if not property or not ((property>=1 and property<=7) or (property>=34 and property<=43)
        or (property>=61 and property<=65) or (property>=73 and property<=85)) then return false end
    local interior=invoke_int(H.GET_INTERIOR_FROM_ENTITY,ped)
    if not interior or interior<=0 or property_local(3856)~=scope.pid
        or property_local(7910)~=interior or property_local(706)~=4 then return false end
    local core=module_context and module_context.CScript and module_context.CScript.Economy
    local ok,leader=pcall(function()return core.ReadStat(("MP%d_HEIST_LEADER_APART_ID"):format(scope.slot))end)
    if not ok or (leader~=property and leader~=-1) then return false end
    local current=board_scope()
    return current and current.key==scope.key and local_ped()==ped and property_local(496)==property
        and property_local(3856)==scope.pid and property_local(7910)==interior and property_local(706)==4
        and invoke_int(H.GET_INTERIOR_FROM_ENTITY,ped)==interior or false
end
inspect_heist_board_prompt=function(family)
    local result={available=false,family=family,label="Teleport to planning screen",reset=false}
    if family~="apartment" and family~="casino" and family~="doomsday" and family~="cayo" then
        result.reason="Select a supported heist.";result.reset=true;return result
    end
    if not started or State.pending_destination or State.cargo_request or board_trip and board_trip.Active() then
        result.reason="Finish the current travel or computer request first.";return result
    end
    local host=board_host()
