end

local function vector_components(value)
    local kind = type(value)
    if kind ~= "table" and kind ~= "userdata" then return nil end
    local ok, x, y, z = pcall(function()
        return tonumber(value.x or value.X or value[1]),
            tonumber(value.y or value.Y or value[2]),
            tonumber(value.z or value.Z or value[3])
    end)
    if not ok or not (x and y and z) then return nil end
    if x ~= x or y ~= y or z ~= z or math.abs(x) > 10000 or math.abs(y) > 10000 or math.abs(z) > 5000 then
        return nil
    end
    return x, y, z
end

local function distance_sq(left, right)
    local lx, ly, lz = vector_components(left)
    local rx, ry, rz = vector_components(right)
    if not (lx and rx) then return nil end
    local dx, dy, dz = lx - rx, ly - ry, lz - rz
    return dx * dx + dy * dy + dz * dz
end

local function entity_exists(handle)
    return type(handle) == "number" and handle > 0 and invoke_bool(H.DOES_ENTITY_EXIST, handle)
end

local function entity_model(handle)
    local value = invoke_int(H.GET_ENTITY_MODEL, handle)
    return value and (value & 0xFFFFFFFF) or 0
end

local function local_player_id()
    local gta = binding("GTA")
    if gta and type(gta.GetLocalPlayerId) == "function" then
        local ok, value = pcall(gta.GetLocalPlayerId)
        value = ok and tonumber(value) or nil
        if value and value >= 0 and value <= 31 then return value end
    end
    return nil
end

