-- Single user action; every phase is bounded and advances only on observation.
-- The host below performs only source-correlated local service requests and
-- normal GTA context entry. An interior coordinate is never an entry mechanism.
function Module.NewKosatkaFlow(host)
    local active
    local api = {}
    local function finish(status, message)
        if status=='FAILED' and host.RecoverDirect then host.RecoverDirect() end
        active = nil
        host.Release()
        return { status = status, message = message }
    end
    function api.Cancel(reason)
        if active then return finish('CANCELLED', reason or 'Kosatka trip cancelled.') end
    end
    function api.Start(generation, now)
        if active then return false, 'A Kosatka trip is already in progress.' end
        local who, why = host.Player()
        if not who then return false, why end
        local ok, err = host.Begin()
        if not ok then host.Release(); return false, err end
        active = { generation=generation, player=who.player_id, ped=who.ped,
            phase='source', deadline=now+10000, total_deadline=now+120000 }
        return true, {status='PENDING',message='Preparing your Kosatka trip.'}
    end
    function api.Tick(now, generation)
        local s=active
        if not s then return end
        if generation~=s.generation then return finish('CANCELLED','Kosatka trip cancelled: session changed.') end
        local who,why=host.Player(true)
        if not who or who.player_id~=s.player or who.ped~=s.ped then
            return finish('CANCELLED',why or 'Kosatka trip cancelled: player changed.')
        end
        if now>s.total_deadline or now>s.deadline then
            return finish('FAILED',s.phase=='spawn' and 'Kosatka delivery or streaming timed out. Try again when GTA Services is available.'
                or s.phase=='entry' and 'GTA did not finish Kosatka entry. You remain at the normal entrance.'
                or 'Kosatka trip timed out before the next step was ready.')
        end
        if s.phase=='source' then
            local ready,err=host.VerifySources()
            if ready==nil then return end
            if not ready then return finish('FAILED',err) end
            local owned,owned_err=host.Owned(s.player)
            if not owned then return finish('FAILED',owned_err) end
            if host.InsideOwn(s.player,s.ped) then
                s.phase='board';s.deadline=now+20000
                return {status='PROGRESS',message='Moving to your Cayo planning board.'}
            end
            local exterior,exterior_err=host.ExteriorReady(s.player,s.ped)
            if not exterior then
                if not host.BeginExit then return finish('FAILED',exterior_err) end
                s.phase='exit_dispatching'
                local token,why=host.BeginExit(function()
                    if active~=s then return false end
                    local current=host.Player(true)
                    return current~=nil and current.player_id==s.player and current.ped==s.ped and active==s
                end)
                if active~=s then host.CancelExit('Kosatka trip changed during exit capture.');return end
                if not token then return finish('FAILED',why or exterior_err) end
                s.phase='leaving';s.deadline=now+30000
                return {status='PROGRESS',message='Leaving your current interior before continuing to your Kosatka.'}
            end
            local entity,err=host.ResolveOwn(s.player)
            if entity==false then return finish('FAILED',err) end
            if not entity then
                local ok,request_err=host.Request(s.player)
                if not ok then return finish('FAILED',request_err) end
            end
            s.phase='spawn';s.deadline=now+60000
            return {status='PROGRESS',message=entity and 'Locating your Kosatka entrance.' or 'Waiting for your Kosatka.'}
        elseif s.phase=='leaving' then
            local exit=host.PollExit()
            if active~=s then return end
            if exit.status=='COMPLETE' then
                s.phase='source';s.deadline=now+10000
                return {status='PROGRESS',message='Current interior exited; continuing your Kosatka trip.'}
            elseif not exit.active then return finish('FAILED',exit.detail or 'The current interior exit did not complete.') end
        elseif s.phase=='spawn' then
            local owned,err=host.Owned(s.player)
            if not owned then return finish('FAILED',err) end
            if host.Stream then host.Stream() end
            local entity,err=host.ResolveOwn(s.player)
            if entity==false then return finish('FAILED',err) end
            if not entity then return end
            local ok,why=host.ExteriorReady(s.player,s.ped)
            if not ok then return finish('FAILED',why) end
            if host.PrepareDirect then
                if not s.direct_deadline then s.direct_deadline=now+10000 end
                if now>s.direct_deadline then
                    return finish('FAILED','Planning-room preload timed out: '..host.DirectStatus())
                end
                local ready,why=host.PrepareDirect(s.player,s.ped,entity)
                if ready==false then return finish('FAILED',why) end
                if not ready then return end
                local moved,err=host.MoveDirect(s.player,s.ped,entity)
                if not moved then return finish('FAILED',err) end
                s.phase='direct_verify';s.deadline=now+10000
                return {status='PROGRESS',message='Moved directly to the planning board; checking interior registration.'}
            end
            local moved,why=host.MoveToEntrance(s.ped,entity)
            if moved==nil then return end
            if not moved then return finish('FAILED',why) end
            s.entity=entity;s.phase='entry';s.deadline=now+35000;s.next_press=now;s.presses=0
            return {status='PROGRESS',message='Entering your Kosatka through its normal entrance.'}
        elseif s.phase=='direct_verify' then
            if host.InsideOwn(s.player,s.ped) and host.RoomReady(s.player,s.ped) and host.AtBoard(s.ped) then
                return finish('COMPLETE','Arrived directly at your Cayo planning board.')
            end
        elseif s.phase=='entry' then
            if host.InsideOwn(s.player,s.ped) then
                s.phase='board';s.deadline=now+20000
                if host.RoomReady(s.player,s.ped) then
                    local moved,err=host.MoveToBoard(s.ped)
                    if not moved then return finish('FAILED',err) end
                    s.phase='verify';s.deadline=now+5000
                    return {status='PROGRESS',message='At the planning board; verifying arrival.'}
                end
                return {status='PROGRESS',message='Waiting for the planning room to finish loading.'}
            end
            if now>=s.next_press and s.presses<20 then
                local ready,why=host.EntranceReady(s.player,s.ped,s.entity)
                if ready==false and why then return finish('FAILED',why) end
                if ready then
                    local ok,why=host.Enter()
                    if not ok then return finish('FAILED',why) end
                    s.presses=s.presses+1;s.next_press=now+150
                end
            end
        elseif s.phase=='board' then
            if not host.InsideOwn(s.player,s.ped) then return end
            if not host.RoomReady(s.player,s.ped) then return end
            local ok,why=host.MoveToBoard(s.ped)
            if not ok then return finish('FAILED',why) end
            s.phase='verify';s.deadline=now+5000
        elseif s.phase=='verify' then
            if not host.InsideOwn(s.player,s.ped) then return finish('FAILED','Kosatka interior ownership changed.') end
            if host.RoomReady(s.player,s.ped) and host.AtBoard(s.ped) then
                return finish('COMPLETE','Arrived in front of your Cayo planning board.')
            end
        end
    end
    return api
end

local K = {
    REQUEST_SCRIPT=0x6EB5F71AA68F2E8E, HAS_SCRIPT_LOADED=0xE6CC9F3BA0FB9EF1,
    SET_SCRIPT_AS_NO_LONGER_NEEDED=0xC90D2DCACD56184C, GET_HASH_KEY=0xD24D37CC275948CC,
    GET_INTERIOR_FROM_ENTITY=0x2107BA504071A6BB, GET_INTERIOR_AT_COORDS=0xB0F7F8663821D9C3,
    IS_INTERIOR_READY=0x6726BDCCC1932F0E, IS_PLAYER_CONTROL_ON=0x49C32D60007AFA47,
    IS_SCREEN_FADED_IN=0x5A859503B0C08678, HAS_COLLISION_LOADED_AROUND_ENTITY=0xE9676F61BC0B3321,
    NETWORK_IS_ACTIVITY_SESSION=0x05095437424397FA, NETWORK_IS_TRANSITION_ACTIVE=0xD0A484CB2F829FBE,
    DECOR_EXIST_ON=0x05661B80A8C9165F, DECOR_GET_INT=0xA06C969B02A97298,
    NETWORK_HASH_FROM_PLAYER_HANDLE=0xBC1D768F2F5D6C05, GET_GAME_TIMER=0x9CD27B0045628463,
    BEGIN_TEXT_COMMAND_IS_THIS_HELP_MESSAGE_BEING_DISPLAYED=0x0A24DA3A41B718F5,
    END_TEXT_COMMAND_IS_THIS_HELP_MESSAGE_BEING_DISPLAYED=0x10BDDBFC529428DD,
    SET_CONTROL_VALUE_NEXT_FRAME=0xE8A25867FBA3B05E,
    SET_FOCUS_POS_AND_VEL=0xBB7454BAFF08FE25, CLEAR_FOCUS=0x31B73D1EA9F01DA2,
    GET_NEXT_BLIP_INFO_ID=0x14F96AA50D6FBEA7,
}
local kosatka_flow
local function kosatka_host()
    local held={}
    local focused=false
    local direct
    local exit_token,exit_service
    local host={}
    local function gint(index)
        local globals=binding('ScriptGlobal')
        if not globals or type(globals.GetInt)~='function' then return nil end
        local ok,v=pcall(globals.GetInt,index)
        if ok and type(v)=='number' and v==v and v%1==0 and v>=-2147483648 and v<=4294967295 then return v end
    end
    function host.Player(transition)
        if not invoke_bool(H.NETWORK_IS_SESSION_STARTED) or invoke_bool(K.NETWORK_IS_TRANSITION_ACTIVE)
            or invoke_bool(K.NETWORK_IS_ACTIVITY_SESSION) then return nil,'Use Go to Kosatka in a stable freemode session.' end
        local id=local_player_id()
        local ped=id and invoke_int(H.GET_PLAYER_PED_SCRIPT_INDEX,id)
        if not entity_exists(ped) or invoke_bool(H.IS_ENTITY_DEAD,ped,false) then return nil,'The local player is not ready.' end
        if not transition and (invoke_bool(H.IS_CUTSCENE_ACTIVE) or invoke_bool(H.IS_CUTSCENE_PLAYING)
            or invoke_bool(H.IS_PED_IN_ANY_VEHICLE,ped,false)) then return nil,'Exit your vehicle and finish the current cutscene first.' end
        return {player_id=id,ped=ped}
    end
    function host.Begin()
        local memory=binding('Memory')
        local ok,version=call_native('InvokeString',0xFCA9373EF340AC0A)
        if not ok or version~='1.73' or not memory or type(memory.GetBaseAddress)~='function'
            or type(memory.ScanScript)~='function' or type(memory.ReadUByte)~='function' then
            return false,'This Kosatka source profile requires GTA Enhanced 1.73 and script verification.'
        end
        local ok,base=pcall(memory.GetBaseAddress,'GTA5_Enhanced.exe')
        if not ok or type(base)~='number' or base<65536 then return false,'This Kosatka source profile requires GTA Enhanced.' end
        local globals=binding('ScriptGlobal')
        if not globals or type(globals.GetInt)~='function' or type(globals.SetInt)~='function' then return false,'Kosatka service access is unavailable.' end
        for name in pairs(KOSATKA_SOURCE) do
            held[#held+1]=name
            if not invoke_void(K.REQUEST_SCRIPT,name) then return false,'Kosatka source loading failed.' end
        end
        return true
    end
    function host.Release()
        host.CancelExit('Kosatka trip finished or cancelled.')
        if direct and direct.scene then invoke_void(0xC197616D221FF4A4) end
        if direct and direct.interior and invoke_int(K.GET_INTERIOR_FROM_ENTITY,direct.ped)~=direct.interior then
            if direct.was_capped then invoke_void(0xD9175F941610DB54,direct.interior,true) end
            if direct.was_disabled then invoke_void(0x6170941419D7D8EC,direct.interior,true) end
        end
        if direct and direct.interior then invoke_void(0x261CCE7EED010641,direct.interior) end
        direct=nil
        if focused then invoke_void(K.CLEAR_FOCUS);focused=false end
        for _,name in ipairs(held) do invoke_void(K.SET_SCRIPT_AS_NO_LONGER_NEEDED,name) end
        held={}
    end
    function host.VerifySources()
        for name in pairs(KOSATKA_SOURCE) do if not invoke_bool(K.HAS_SCRIPT_LOADED,name) then return nil end end
        local memory=binding('Memory')
        for name,patterns in pairs(KOSATKA_SOURCE) do
            local hash=invoke_int(K.GET_HASH_KEY,name)
            if not hash then return false,'Kosatka script identity is unavailable.' end
            for index,pattern in ipairs(patterns) do
                -- Collected planning func_193 starts at PC 65518: its first
                -- 18 bytes end code page 3; the remaining 61 start page 4.
                -- VM code pages need not be adjacent in process memory.
                local segments={pattern}
                if name=='heist_island_planning' and index==1 then
                    local bytes={};for hex in pattern:gmatch('%x%x') do bytes[#bytes+1]=hex end
                    segments={table.concat(bytes,' ',1,18),table.concat(bytes,' ',19)}
                end
                for segment,part in ipairs(segments) do
                    local ok,ptr=pcall(memory.ScanScript,hash,part)
                    if not ok or type(ptr)~='number' or ptr<65536 then
                        return false,('Kosatka source changed (%s, signature %d, page segment %d).'):format(name,index,segment)
                    end
                    local offset=0
                    for hex in part:gmatch('%x%x') do
                        local ok,byte=pcall(memory.ReadUByte,ptr+offset)
                        if not ok or byte~=tonumber(hex,16) then
                            return false,('Kosatka source verification failed (%s, signature %d, segment %d, byte %d).'):format(name,index,segment,offset)
                        end
                        offset=offset+1
                    end
                end
            end
        end
        return true
    end
    function host.Owned(id)
        -- am_pi_menu func_1775, array header +1.
        local flags=gint(1845347+1+id*884+260+489)
        return flags~=nil and (flags&1)==1,'You need to own a Kosatka before using this trip.'
    end
    function host.InsideOwn(id,ped)
        local interior=invoke_int(K.GET_INTERIOR_FROM_ENTITY,ped)
        local sub=invoke_int(K.GET_INTERIOR_AT_COORDS,1560.0,400.0,-50.0)
        return interior and sub and sub>0 and interior==sub
            and gint(2658296+1+id*468+325+11)==id
    end
    function host.RoomReady(id,ped)
        local interior=invoke_int(K.GET_INTERIOR_FROM_ENTITY,ped)
        return interior and interior>0 and invoke_bool(K.IS_INTERIOR_READY,interior)
            and invoke_bool(K.IS_PLAYER_CONTROL_ON,id) and invoke_bool(K.IS_SCREEN_FADED_IN)
            and not invoke_bool(H.IS_CUTSCENE_ACTIVE) and not invoke_bool(H.IS_CUTSCENE_PLAYING)
            and invoke_bool(K.HAS_COLLISION_LOADED_AROUND_ENTITY,ped)
    end
    function host.ExteriorReady(id,ped)
        if invoke_int(K.GET_INTERIOR_FROM_ENTITY,ped)~=0 then return false,'Leave the current interior before going to your Kosatka.' end
        if not invoke_bool(K.IS_PLAYER_CONTROL_ON,id) or not invoke_bool(K.IS_SCREEN_FADED_IN)
