    { key = "registry",    label = "FEATURE REGISTRY", progress = 0.24, min_ms = 700 },
    { key = "player",      label = "PLAYER RUNTIME",   progress = 0.42, min_ms = 1100 },
    { key = "session",     label = "SESSION BRIDGE",   progress = 0.60, min_ms = 1100 },
    { key = "persistence", label = "PERSISTENCE",      progress = 0.76, min_ms = 1100 },
    { key = "interface",   label = "INTERFACE ACCESS", progress = 0.92, min_ms = 900 },
}
local UI_STATE_RETRY_BASE_MS = 1000
local UI_STATE_RETRY_MAX_MS = 30000
local PAGE_FADE_OUT_MS = 130
local PAGE_FADE_IN_MS = 190
local SHELL_REVEAL_MS = 420
