-- the game resolution or the host window. Three panels need approximately
-- 150 px of navigation, 340 px of editor, 170 px of context, plus gutters.
local STUDIO_COMPACT_MAX_WIDTH = 679
local STUDIO_MEDIUM_MAX_WIDTH = 879
-- Ordinary feature cards share a row at normal Cherax menu widths.
-- Dedicated editors keep their own thresholds; larger fonts still stack.
local TWO_PANE_MIN_CONTENT_WIDTH = 500

local module_context
local started = false
local registered = false
local main_tab_registered = false
