Presentation.retired = {}
for _, key in ipairs(Presentation.retired_keys) do Presentation.retired[key] = true end
function Presentation.is_retired(key)
    if Presentation.retired[key] then return true end
    local config = module_context and module_context.CScript.Config
    if config and type(config.IsRetiredFeature) == "function" then
        local ok, retired = pcall(config.IsRetiredFeature, key)
