    State.retired_ui_routes = State.retired_ui_routes or {}
    State.retired_ui_routes[tostring(reference)] = true
    State.retirement_notice_pending = State.retirement_notice_shown ~= true
end

function Presentation.build_metadata()
    local cs = module_context and module_context.CScript or {}
    local d = cs.Diagnostics or {}
    local info = cs.BuildInfo or {}
    return {
        build_id = tostring(d.BuildId or info.BuildId or "Build metadata unavailable"),
        controls = tonumber(d.Controls or info.Controls)
    }
end

