-- Only page destinations are retained. Feature discovery, indexing and
-- quick-access routes have been removed; gameplay controls render in-place.
local ROUTE_BY_ID = {}
local PAGE_ROUTE_BY_CONTEXT = {}
local function route_part(value)
    local part = tostring(value or "route"):gsub("[^%w_]", "_"):gsub("_+", "_")
        :gsub("^_+", ""):gsub("_+$", "")
    return part ~= "" and part or "route"
end
local function page_context_id(category_key, page_name)
    return tostring(category_key or "") .. "\0" .. tostring(page_name or "")
end
local function page_route_id(category_key, page_name)
    return "page__" .. route_part(category_key) .. "__" .. route_part(page_name)
end
for _, category in ipairs(UI_SCHEMA) do
    for _, page in ipairs(category.pages or {}) do
        local id = page_route_id(category.key, page.name)
        ROUTE_BY_ID[id] = {
            route_id = id,
            category_key = category.key,
            page = page.name,
            context = category.key .. " > " .. page.name
        }
        PAGE_ROUTE_BY_CONTEXT[page_context_id(category.key, page.name)] = id
    end
end

local function log_error_once(key, message)
    if not module_context then return end
    key, message = tostring(key), tostring(message):sub(1, 4096)
    if State then
        State.render_errors = State.render_errors or {}
        local previous = State.render_errors[key]
        if previous then
            previous.repeats = math.min(1000000, previous.repeats + 1); return
        end
        State.render_error_count = State.render_error_count or 0
        if State.render_error_count >= 24 then return end
        local item = {
            key = key,
            message = message,
            repeats = 0,
            category = State.selected_category_key,
            context = State.render_context,
            selected_player = State.players_selected
        }
        State.render_errors[key] = item; State.render_error_count = State.render_error_count + 1
        State.first_render_error = State.first_render_error or item
        message = ("context=%s category=%s player=%s: %s"):format(
            tostring(item.context), tostring(item.category), tostring(item.selected_player), message)
    end
    local logger = module_context.Logger
    if logger and type(logger.ErrorOnce) == "function" then
        pcall(logger.ErrorOnce, "ui_" .. key, message, "UI")
    end
    local runtime = module_context.CScript and module_context.CScript.Runtime
    if runtime and type(runtime.RecordTestEvent) == "function" then
        pcall(runtime.RecordTestEvent, "FAILED", "UI", key, "render", message)
    end
end

local function compat_ui()
    if type(public_api) == "table" then return public_api end
    return nil
end

local function feature_id(key)
    local api = compat_ui()
    return api and api.FeatureId and api.FeatureId(key) or nil
end

local function player_feature_id(key)
    local api = compat_ui()
    return api and api.PlayerFeatureId and api.PlayerFeatureId(key) or nil
end

local function ui_spacing(count)
    if not (ImGui and type(ImGui.Spacing) == "function") then return end
    for _ = 1, count or 1 do pcall(ImGui.Spacing) end
end

local function imgui_clicked(method, ...)
    if not (ImGui and type(ImGui[method]) == "function") then return false end
    local ok, clicked = pcall(ImGui[method], ...)
    return ok and clicked == true
end

local function input_byte_cap(value, maximum)
    local text=tostring(value or "")
    local limit=tonumber(maximum) or 64
    if limit~=limit or math.abs(limit)==math.huge then limit=64 end
    limit=math.max(0,math.floor(limit))
    if #text<=limit then return text end
    -- Never leave a partial UTF-8 code point at the byte limit.
    while limit>0 do
        local next_byte=text:byte(limit+1)
        if not next_byte or next_byte<128 or next_byte>191 then break end
        limit=limit-1
    end
    return text:sub(1,limit)
end

local function input_text(label, current, maximum)
    local before=input_byte_cap(current,maximum)
    if not (ImGui and type(ImGui.InputText) == "function") then return before end
    -- Cherax's final argument is ImGuiInputTextFlags, not a buffer length.
    local ok, first, second = pcall(ImGui.InputText, label, before, 0)
    if not ok then return before end
    if type(first) == "string" then return input_byte_cap(first,maximum) end
    if first == true and type(second) == "string" then return input_byte_cap(second,maximum) end
    return before
end

local function input_text_with_hint(label, hint, current, maximum)
    if not (ImGui and type(ImGui.InputTextWithHint) == "function") then
        return input_text(label, current, maximum)
    end
    local ok, first, second = pcall(ImGui.InputTextWithHint, label, tostring(hint or ""),
        input_byte_cap(current,maximum), 0)
    if not ok then return input_text(label, current, maximum) end
    if type(first) == "string" then return input_byte_cap(first,maximum) end
    if first == true and type(second) == "string" then return input_byte_cap(second,maximum) end
    return input_byte_cap(current,maximum)
end

local function user_copy(value, kind, fallback)
    local copy = module_context and module_context.Core and module_context.Core.PresentationCopy
    return copy and copy.Message(value, kind, fallback) or tostring(value or "")
end

local function feature_help(label, original)
    local copy = module_context and module_context.Core and module_context.Core.PresentationCopy
    return copy and copy.Description(tostring(label or ""):gsub("%s+>%s*$", ""), original) or original
end

local function ui_text(value, disabled)
    if not ImGui then return end
    value = user_copy(value)
    local method = disabled and ImGui.TextDisabled or ImGui.Text
    if type(method) == "function" then pcall(method, tostring(value or "")) end
end

local function ui_same_line()
    if ImGui and type(ImGui.SameLine) == "function" then pcall(ImGui.SameLine) end
end

