        State.FeatureRegisteredCount or 0
    add_button("about", "About CScript", "Shows CScript version details.", function()
        dependencies.log_info(BUILD_UI_LABEL .. " by c0rpN is running.")
        dependencies.toast(BUILD_UI_LABEL .. " by c0rpN", 6000, "info")
    end)
    -- Home prefix
    if (State.FeatureRegisteredCount or 0) - before ~= 1 then
        return false
    end
    State.HomePrefixRegistered = true
    return true
end

local function register_home_suffix_features()
    if State.HomeSuffixRegistered then return true end
    State.HomeSuffixRegistered = true
    return true
end

local function register_overlay_features()
    local before =
        State.FeatureRegisteredCount or 0
    if State.OverlayFeaturesRegistered then return true end
    add_toggle("speedometer", "Enable Speedometer", "Shows your current vehicle speed.", false)
    add_combo("speed_unit", "Speedometer Unit", "Selects the speedometer display unit.", { "km/h", "mph", "m/s" }, 0)
    add_toggle("cinematic_bars", "Cinematic Bars", "Adds cinematic letterbox bars.", false)
    add_toggle("hide_hud_radar", "Hide HUD & Radar", "Hides the HUD and radar.", false)
    add_toggle("coords_hud", "Coordinates & Heading HUD", "Shows your local position, heading, and interior ID.", false)
    add_toggle("vitals_hud", "Player Vitals HUD", "Shows local health and armour.", false)
    add_toggle("vehicle_health_hud", "Vehicle Health HUD", "Shows current vehicle engine health.", false)
    -- Overlay
    if (State.FeatureRegisteredCount or 0) - before ~= 7 then
        return false
    end
    State.OverlayFeaturesRegistered = true
    return true
end

local function register_settings_features()
    local before =
        State.FeatureRegisteredCount or 0
    if State.SettingsFeaturesRegistered then return true end
    add_button("friendly_preset", "Apply Local Friendly Preset", "Enables the local friendly-player options.", function()
        dependencies.set_toggle("no_wanted", true)
        dependencies.set_toggle("peds_ignore", true)
        dependencies.set_toggle("no_critical_hits", true)
        dependencies.toast("Local friendly preset applied.")
    end)
    add_toggle("notifications_enabled", "Notifications", "Show CScript notifications.", true, function(feature)
        local notices = module_context and module_context.Notifications
        if notices and notices.SetEnabled then notices.SetEnabled(feature:IsToggled()) end
    end)
    add_toggle("protection_notifications", "Protection Notifications", "Show blocked protection events.", true, function(feature)
        local notices = module_context and module_context.Notifications
        if notices and notices.SetProtectionEnabled then notices.SetProtectionEnabled(feature:IsToggled()) end
    end)
    -- Settings
    if (State.FeatureRegisteredCount or 0) - before ~= 3 then
        return false
    end
    State.SettingsFeaturesRegistered = true
    return true
end

local function reset_overlay()
    if not State then return end
    State.overlay = { lines = {}, vip = nil }
end

local function sample_overlay()
    if not bound then return false end
    local overlay = {
        lines = {},
        vip = nil,
        hide_hud_radar = dependencies.is_on("hide_hud_radar"),
        cinematic_bars = dependencies.is_on("cinematic_bars"),
    }
    local lines = overlay.lines

    dependencies.Session.AppendOverlayLines(lines)
    if dependencies.is_on("speedometer") then
        local vehicle = dependencies.local_vehicle()
        if dependencies.entity_exists(vehicle) then
            local metres = dependencies.invoke_float(dependencies.H.GET_ENTITY_SPEED, vehicle)
            local index = dependencies.list_index("speed_unit")
            local value, unit = metres * 3.6, "km/h"
            if index == 1 then
                value, unit = metres * 2.236936, "mph"
            elseif index == 2 then
                value, unit = metres, "m/s"
            end
            lines[#lines + 1] = ("Speed: %.0f %s"):format(value, unit)
        else
            lines[#lines + 1] = "Speed: --"
        end
    end

    local ped = dependencies.local_ped()
    if dependencies.is_on("coords_hud") and dependencies.entity_exists(ped) then
        local coords = dependencies.invoke_vec3(dependencies.H.GET_ENTITY_COORDS, ped, false)
        local x, y, z = dependencies.vector_components(coords)
        if x then
            lines[#lines + 1] = ("XYZ: %.1f, %.1f, %.1f | H: %.0f | Interior: %d"):format(
                x, y, z, dependencies.invoke_float(dependencies.H.GET_ENTITY_HEADING, ped),
                dependencies.invoke_int(dependencies.H.GET_INTERIOR_FROM_ENTITY, ped))
        else
            lines[#lines + 1] = "Position unavailable"
        end
    elseif dependencies.is_on("coords_hud") then
        lines[#lines + 1] = "Position unavailable"
    end
    if dependencies.is_on("vitals_hud") and dependencies.entity_exists(ped) then
        lines[#lines + 1] = ("Health: %d/%d | Armour: %d"):format(
            dependencies.invoke_int(dependencies.H.GET_ENTITY_HEALTH, ped),
            dependencies.invoke_int(dependencies.H.GET_ENTITY_MAX_HEALTH, ped),
            dependencies.invoke_int(dependencies.H.GET_PED_ARMOUR, ped))
    elseif dependencies.is_on("vitals_hud") then
        lines[#lines + 1] = "Vitals unavailable"
    end
    if dependencies.is_on("vehicle_health_hud") then
        local vehicle = dependencies.local_vehicle()
        if dependencies.entity_exists(vehicle) then
            lines[#lines + 1] = ("Engine health: %.0f"):format(
                dependencies.invoke_float(dependencies.H.GET_VEHICLE_ENGINE_HEALTH, vehicle))
        else
            lines[#lines + 1] = "Engine health: --"
        end
    end

    State.overlay = overlay
    return true
end

local function overlay_requested()
    if not bound then return false end
    return dependencies.Session.OverlayRequested()
        or dependencies.is_on("speedometer") or dependencies.is_on("coords_hud")
        or dependencies.is_on("vitals_hud") or dependencies.is_on("vehicle_health_hud")
        or dependencies.is_on("cinematic_bars")
        or dependencies.is_on("hide_hud_radar")
end

local function frame_tick(now)
    if not bound then return end
    OnlinePanel.dispatch()
    Presentation.dispatch()
    load_ui_state()
    update_startup_presentation(now)
    if State.navigation_save_requested then save_ui_state(now) end
    if dependencies.is_on("hide_hud_radar") then
        dependencies.invoke_void(dependencies.H.HIDE_HUD_AND_RADAR_THIS_FRAME)
    end
    if false then
        dependencies.invoke_void(dependencies.H.HIDE_HUD_COMPONENT_THIS_FRAME, 14)
    end
end

function CScriptUI.publish_player_tab()
    if CScriptUI.player_tab_registered then return true end
    if not ClickGUI or type(ClickGUI.AddPlayerTab) ~= "function" then return false end
    local ok, err = pcall(ClickGUI.AddPlayerTab, TAB_NAME, function()
        if not started or not bound or not State or State.tab_render_blocked or State.player_tab_render_active then return end
        if not dependencies or not dependencies.Player or type(dependencies.Player.SelectedFeatureKeys) ~= "function"
            or not Utils or type(Utils.GetSelectedPlayer) ~= "function" then
            return
        end
        local selected_ok, selected = pcall(Utils.GetSelectedPlayer)
        if not selected_ok or type(selected) ~= "number" or selected % 1 ~= 0 or selected < 0 or selected > 31 then return end
        if dependencies.player_available(selected) ~= true then return end
        local state = State
        state.player_tab_render_active = true
        local child_open = false
        local rendered, why = xpcall(function()
            if type(ClickGUI.BeginCustomChildWindow) ~= "function" or type(ClickGUI.EndCustomChildWindow) ~= "function" then
                error("Native player tab child-window binding unavailable")
            end
            child_open = ClickGUI.BeginCustomChildWindow("CScript Player Actions") == true
            if not child_open then return end
            CScriptUI.surface()
            -- The runtime snapshot supplies identity; no presentation-time host
            -- name/roster scan. Match Cherax's selection, not our roster fallback.
            local session = dependencies.Session
            if session and type(session.GetPlayersSnapshot) == "function" then
                local available, snapshot = pcall(session.GetPlayersSnapshot)
                if available and type(snapshot) == "table" and type(snapshot.rows) == "table" then
                    -- Identity decoration is optional. A transient cache or host
                    -- text-measurement error must not strand the action controls.
                    pcall(function()
                        local row
                        for _, candidate in ipairs(snapshot.rows) do
                            if candidate.id == selected then
                                row = candidate; break
                            end
                        end
                        local width = select(1, content_region())
                        ui_text(PlayersPage.fit(row and row.name or "Player identity unavailable", width))
                        ui_text(
                            PlayersPage.fit(
                                "Slot " .. tostring(selected) .. (row and row.local_player and " | You" or ""),
                                width), true)
                    end)
                end
            end
            local drawn, disabled = CScriptUI.render_selected_player_actions(selected, "native")
            if not state.player_tab_content_logged and type(dependencies.log_info) == "function" then
                pcall(dependencies.log_info,
                    "Native player tab submitted " ..
                    tostring(drawn) ..
                    " current controls for slot " .. tostring(selected) .. " other-player-only=" .. tostring(disabled))
                state.player_tab_content_logged = true
            end
        end, page_traceback)
        -- Close the successful host child even when an individual renderer fails.
        if child_open then
            local ended, end_error = pcall(ClickGUI.EndCustomChildWindow)
            if not ended then rendered, why = false, end_error end
        end
        state.player_tab_render_active = false
        if not rendered then log_error_once("native_player_tab", why) end
    end)
    if not ok then
        log_error_once("native_player_tab_register", err); return false
    end
    CScriptUI.player_tab_registered = true
    return true
end

function CScriptUI.remove_player_tab()
    if CScriptUI.player_tab_registered and ClickGUI and type(ClickGUI.RemovePlayerTab) == "function" then
        local ok = pcall(ClickGUI.RemovePlayerTab, TAB_NAME)
        if ok then CScriptUI.player_tab_registered = false end
    end
end

local function publish_main_tab()
    CScriptUI.publish_player_tab()
    if main_tab_registered then return true end
    if not (ClickGUI and type(ClickGUI.AddTab) == "function") then return false, "ClickGUI.AddTab unavailable" end
    local ok, err = pcall(ClickGUI.AddTab, TAB_NAME, function()
        local state = State
        if not state or not bound or state.tab_render_blocked then return end
        if state.tab_render_active then
            log_error_once("tab_reentry", "Nested host tab callback skipped; no coroutine operations attempted.")
            return
        end
        state.tab_render_active = true
        local render_ok, render_err = xpcall(render_main_ui, page_traceback)
        state.tab_render_active = false
        if not render_ok then log_error_once("main", render_err) end
    end)
    if not ok then return false, tostring(err) end
    main_tab_registered = true
    if State then State.main_tab_deferred = false end
    if module_context then publish_state(module_context) end
    return true
end

publish_state = function(context)
    State.MigrationPhase = Module.MigrationPhase
    State.Started = started
    State.Registered = registered
    State.MainTab = TAB_NAME
    State.MainTabPublished = main_tab_registered == true
    State.CategoryCount = #UI_SCHEMA
    State.FeatureRegisteredCount = State.FeatureRegisteredCount or 0
    State.Bound = bound
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table" or type(context.CScript) ~= "table" then
        error("modules.ui received an invalid context")
    end
    module_context = context
    local effect = context.Modules and context.Modules.VehicleChaos
    local effect_text = effect and type(effect.GetPresentation) == "function" and effect.GetPresentation()
        or { name = "Ruiner Pimp", category = "Naughty removals" }
    for _, section in ipairs(CScriptUI.SelectedPlayerSections) do
        if section.key == "vehicle_effect" then
            section.label = effect_text.category
            -- Restore stable key-based entries, including later options.
            -- Repeated Init must neither drop earlier keys nor duplicate variants.
            local old_names = {}
            for _, action in ipairs(section.actions) do
                if type(action) == "table" and type(action[1]) == "string"
                    and type(action[2]) == "string" then
                    old_names[action[1]] = action[2]
                end
            end
            local aliases = {
                penis = effect_text.penis_name or "penis crash",
                ruiner_pimp = effect_text.name or "Ruiner Pimp",
                vehicle_circle = effect_text.circle_name or "Vehicle Circle",
                trevor_michael = effect_text.duo_name or "Trevor + Michael",
                pistol_circle = effect_text.pickup_name or "Monkey Drops",
            }
            local order = {
                "penis", "cargoplane_pile", "tug_pair", "character_baller",
                "ruiner_pimp", "vehicle_circle", "trevor_michael", "pistol_circle",
            }
            local actions, seen = {}, {}
            for _, key in ipairs(order) do
                local label = aliases[key] or old_names[key] or (key == "tug_pair" and "Tug Pair")
                if label and not seen[key] then
                    actions[#actions + 1] = { key, label }
                    seen[key] = true
                end
            end
            local variants = effect and type(effect.GetVariants) == "function" and effect.GetVariants() or {}
            for _, variant in ipairs(variants) do
                if type(variant.key) == "string" and type(variant.name) == "string"
                    and not seen[variant.key] then
                    actions[#actions + 1] = { variant.key, variant.name }
                    seen[variant.key] = true
                end
            end
            section.actions = actions
        end
    end
    State = context.State.UI or {}
    State.online_action_queue, State.online_last_result = nil, nil
    State.navigation_save_requested = nil
    retire_access_state()
    State.online_interaction_intent = nil
    State.presentation_queue, State.presentation_results, State.presentation_pressed = nil, {}, {}
    State.retirement_notice_pending = State.retirement_notice_shown ~= true
    context.State.UI = State
    context.Modules.UI = Module
    public_api = {
        Schema = UI_SCHEMA,
        Components = CScriptUI,
        RenderMain = render_main_ui,
        MigrationPhase = Module.MigrationPhase,
    }
    context.CScript.UI = public_api
    context.CScriptUI = CScriptUI

    public_api.GetHandoffPresentation = function()
        local labels = {}
        for i, item in ipairs(UI_SCHEMA) do labels[i] = item.label end
        local category = CATEGORY_BY_KEY[State.selected_category_key or "Home"] or UI_SCHEMA[1]
        local page = selected_page(category)
        local session = module_context and module_context.State and module_context.State.Session
        local metadata = Presentation.build_metadata()
        return {
            categories = labels,
            category = category.label,
            page = page and page.name or "",
            build_id = metadata.build_id,
            controls = metadata.controls,
            hold_ms = 2000,
            interface_ready = bound == true and registered == true,
            session_ready = session and session.Started == true and session.Bound == true or false
        }
    end
    public_api.GetRenderDiagnostics = function()
        local first = State and State.first_render_error
        local copy = {}; for k, v in pairs(first or {}) do copy[k] = v end
        return {
            first = first and copy or nil,
            count = State and State.render_error_count or 0,
            blocked = State and State.tab_render_blocked == true or false,
            live_host_failure_reproduced = false
        }
    end
    public_api.PublishMainTab = publish_main_tab
    public_api.BeginShellReveal = function(duration_ms)
        if not State then return false end
        State.shell_reveal_duration_ms = math.max(120, math.min(1200, tonumber(duration_ms) or SHELL_REVEAL_MS))
        State.shell_reveal_started_ms = ui_clock_ms()
        return true
    end

    if not registered then
        if EventMgr and type(EventMgr.RegisterHandler) == "function" and eLuaEvent and eLuaEvent.ON_PRESENT then
            EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
                CScriptUI.studio_presentation_frame()
                local ok, err = pcall(render_present)
                if not ok then log_error_once("present", err) end
            end)
        end
        registered = true
    end
    if __CSCRIPT_PREBOOT_HANDOFF == true then
        State.main_tab_deferred = true
    else
        publish_main_tab()
    end
    publish_state(context)
end

function Module.BindCompatibility(bindings)
    if not module_context then error("ui module must initialize before compatibility binding", 2) end
    if bound then return public_api end
    dependencies = bindings or {}
    for _, name in ipairs({
        "feature_id", "list_index", "is_on", "set_toggle",
        "log_info", "toast", "invoke_void", "invoke_int", "invoke_float", "invoke_bool", "invoke_vec3",
        "local_player_id", "local_ped", "local_vehicle", "entity_exists", "vector_components",
        "player_available", "player_name", "H", "FeatureMgr", "Player", "Session", "Vehicle",
    }) do require_binding(name, dependencies[name]) end

    function public_api.FeatureId(key) return dependencies.feature_id(key) end

    function public_api.PlayerFeatureId(key) return dependencies.Player.PlayerFeatureId(key) end

    function public_api.CurrentContext()
        local category = CATEGORY_BY_KEY[State.selected_category_key or ""] or UI_SCHEMA[1]
        local page = selected_page(category)
        return {
            category = tostring(category and (category.label or category.key) or "Unknown"),
            category_key = tostring(category and category.key or "Unknown"),
            page = tostring(page and page.name or State.selected_page_name or "Unknown"),
        }
    end

    function public_api.ControlContext(hash, name)
        hash = tonumber(hash)
        if hash then
            for _, key in ipairs({ "lester_last_ride" }) do
                local ok, value = pcall(dependencies.Player.PlayerFeatureId, key)
                if ok and tonumber(value) == hash then
                    return {
                        category = "Online",
                        page = "Players",
                        section = "Vehicle",
                        key = "selected_player_" .. key
                    }
                end
            end
            -- Diagnostics resolve a control only when asked. No feature index
            -- or search metadata is built or refreshed in the background.
            for _, category in ipairs(UI_SCHEMA) do
                for _, page in ipairs(category.pages or {}) do
                    for _, window in ipairs(page.windows or {}) do
                        for _, key in ipairs(window[2] or {}) do
                            if not Presentation.is_retired(key) then
                                local ok, value = pcall(dependencies.feature_id, key)
                                if ok and tonumber(value) == hash then
                                    return { category = category.label, page = page.name, section = window[1], key = key }
                                end
                            end
                        end
                    end
                end
            end
        end
        if tostring(name or "") == "Rapid Fire Delay" then
            return { category = "Vehicle", page = "Combat", section = "Mounted Weapons" }
        end
        return { category = "Players", page = "Selected Player", section = "Player Actions" }
    end

    function public_api.ListIndex(key) return dependencies.list_index(key) end

    function public_api.PlayerAvailable(player_id) return dependencies.player_available(player_id) end

    function public_api.PlayerName(player_id) return dependencies.player_name(player_id) end

    function public_api.GetSessionPlayersSnapshot() return dependencies.Session.GetPlayersSnapshot() end

    function public_api.SelectSessionPlayer(player_id) return dependencies.Session.SelectPlayer(player_id) end

    function public_api.SelectSessionHost(kind) return dependencies.Session.SelectHost(kind) end

    function public_api.CopySessionRockstarId(kind, expected) return dependencies.Session.CopyRockstarId(kind, expected) end

    function public_api.GetOverlaySnapshot() return State.overlay or { lines = {}, vip = nil } end

    function public_api.GetWelcomeSnapshot()
        return {
            enabled = true,
            preview = State.welcome_preview == true,
            started_seconds = State.welcome_started_seconds or 0,
            title = State.welcome_title or "Welcome back, Player",
            version = State.welcome_version or BUILD_UI_LABEL,
            status = State.welcome_status or "Ready",
            gate = State.welcome_gate == true,
            progress = tonumber(State.welcome_progress) or 0.0,
            phase = State.welcome_phase or "STARTING",
            detail = State.welcome_detail or "",
            ready = State.welcome_ready == true,
            stage_index = tonumber(State.welcome_stage_index) or 1,
            tasks = State.welcome_tasks or {},
            ready_render_elapsed = (function()
                local started = tonumber(State.welcome_ready_render_seconds) or 0
                if started > 0 and ImGui and type(ImGui.GetTime) == "function" then
                    return math.max(0.0, ImGui.GetTime() - started)
                end
                return 0.0
            end)(),
            registered_count = (module_context and module_context.CScript and module_context.CScript.FeatureKeys)
                and (function()
                    local n = 0
                    for _ in pairs(module_context.CScript.FeatureKeys) do n = n + 1 end
                    return n
                end)() or 0,
            hidden_count = (function()
                local n = 0
                for _ in pairs(State.welcome_hidden_features or {}) do n = n + 1 end
                return n
            end)(),
        }
    end

    function public_api.SetWelcomeStartSeconds(value)
        value = tonumber(value)
        if not value then return false end
        State.welcome_started_seconds = value
        return true
    end

    function public_api.SetWelcomeReadyRenderSeconds(value)
        value = tonumber(value)
        if not value then return false end
        State.welcome_ready_render_seconds = value
        return true
    end

    function public_api.StopWelcome() stop_welcome() end

    function public_api.StartWelcome(preview) start_welcome(preview) end

    function public_api.BeginStartupPresentation() return begin_startup_presentation() end

    function public_api.SetWelcomeStage(progress, phase, detail, ready)
        return set_welcome_stage(progress, phase, detail, ready)
    end

    function public_api.RefreshWelcomeGate() return refresh_welcome_gate() end

    function public_api.RegisterHomePrefixFeatures() return register_home_prefix_features() end

    function public_api.RegisterHomeSuffixFeatures() return register_home_suffix_features() end

    function public_api.RegisterOverlayFeatures() return register_overlay_features() end

    function public_api.RegisterSettingsFeatures() return register_settings_features() end

    function public_api.RegisteredCount() return State.FeatureRegisteredCount or 0 end

    function public_api.RequestNavigationSave()
        if not started then return false end
        State.navigation_save_requested = true
        return true
    end

    function public_api.FrameTick(now) return frame_tick(now) end

    function public_api.FrameRequested()
        return (started and State.online_action_queue ~= nil)
            or (started and State.presentation_queue ~= nil)
            or State.navigation_save_requested == true
            or State.welcome_gate == true
            or dependencies.is_on("hide_hud_radar")
    end

    function public_api.SampleOverlay(now) return sample_overlay(now) end

    function public_api.OverlayRequested() return overlay_requested() end

    function public_api.ResetOverlay() return reset_overlay() end

    function public_api.StopCameraEffects() return stop_camera_effects() end

    function public_api.SetCompactNavigation(value)
        State.compact_navigation = value == true
        return State.compact_navigation
    end

    function public_api.GetCompactNavigation()
        return State.compact_navigation == true
    end

    State.overlay = State.overlay or { lines = {}, vip = nil }
    State.welcome_started_seconds = State.welcome_started_seconds or 0
    State.welcome_preview = State.welcome_preview == true
    State.welcome_gate = State.welcome_gate == true
    State.welcome_hidden_features = State.welcome_hidden_features or {}
    State.welcome_progress = tonumber(State.welcome_progress) or 0.0
    State.welcome_phase = State.welcome_phase or "STARTING"
    State.welcome_detail = State.welcome_detail or ""
    State.welcome_ready = State.welcome_ready == true
    State.welcome_boot_active = State.welcome_boot_active == true
    State.welcome_post_boot = State.welcome_post_boot == true
    State.welcome_stage_index = tonumber(State.welcome_stage_index) or 1
    State.welcome_stage_started_ms = tonumber(State.welcome_stage_started_ms) or 0
    State.welcome_sequence_started_ms = tonumber(State.welcome_sequence_started_ms) or 0
    State.welcome_ready_started_ms = tonumber(State.welcome_ready_started_ms) or 0
    State.welcome_ready_render_seconds = tonumber(State.welcome_ready_render_seconds) or 0
    State.welcome_render_compact_logged = State.welcome_render_compact_logged == true
    State.welcome_render_fullscreen_logged = State.welcome_render_fullscreen_logged == true
    State.welcome_tasks = State.welcome_tasks or {}
    State.welcome_greeting_enabled = State.welcome_greeting_enabled ~= false
    retire_access_state()
    State.more_navigation_expanded = false
    State.compact_navigation = State.compact_navigation == true
    State.active_page_context = nil
    State.page_entry_actions = {}
    State.page_transition = type(State.page_transition) == "table" and State.page_transition or { active = false }
    State.shell_reveal_started_ms = tonumber(State.shell_reveal_started_ms) or 0
    State.shell_reveal_duration_ms = tonumber(State.shell_reveal_duration_ms) or SHELL_REVEAL_MS
    State.ui_state_save_failures = tonumber(State.ui_state_save_failures) or 0
    State.ui_state_next_save_ms = tonumber(State.ui_state_next_save_ms) or 0
    State.ui_state_save_reported = State.ui_state_save_reported == true
    local selected_category = tostring(State.selected_category_key or "")
    local selected_legacy = LEGACY_CATEGORY_DEFAULTS[selected_category]
    if selected_legacy then
        selected_category = selected_legacy[1]
        State.selected_page_name = selected_legacy[2]
    end
    State.selected_category_key = CATEGORY_BY_KEY[selected_category]
        and selected_category or "Home"
    State.selected_page_name = State.selected_page_name or "Overview"
    selected_page(CATEGORY_BY_KEY[State.selected_category_key])
    State.DebugMode = false
    if module_context.CScript and module_context.CScript.Diagnostics then
        module_context.CScript.Diagnostics.DebugMode = State.DebugMode
    end
    -- Preloader handoff leaves the idle UI frame predicate false. Restore the
    -- saved route before publishing the menu, so the first queued action cannot
    -- load old preferences over navigation already chosen by the user.
    load_ui_state()
    bound = true
    publish_state(module_context)
    return public_api
end

function Module.Start()
    started = true
    CScriptUI.publish_player_tab()
    if module_context then publish_state(module_context) end
end

function Module.Stop()
    started = false
    if State then
        State.online_action_queue, State.online_last_result, State.online_interaction_intent = nil, nil, nil
        State.navigation_save_requested = nil
        State.presentation_queue, State.presentation_results, State.presentation_pressed = nil, {}, {}
    end
    CScriptUI.remove_player_tab()
    if module_context then publish_state(module_context) end
end

function Module.Restore(context)
    context = context or module_context
    started = false
    CScriptUI.remove_player_tab()
    registered = false
    main_tab_registered = false
    if context and context.CScript and context.CScript.UI == public_api then context.CScript.UI = nil end
    if context and context.CScriptUI == CScriptUI then context.CScriptUI = nil end
    if context and context.Modules and context.Modules.UI == Module then context.Modules.UI = nil end
    if context and context.State then context.State.UI = {} end
    State = nil
    module_context = nil
    public_api = nil
    dependencies = nil
    bound = false
end

return Module
