Module.Hashes=H
local PACK={revision='speedo50-enhanced-1158-4-runtime',name='cscript_roof50_v4',
 group='CSCRIPT_ROOF50_V4_RUNTIME',groupHash=0x49F645C9,listHash=2088582328,loadHash=3992157797}
-- This group belongs only to the reviewed roof pack. Never execute the shared
-- GROUP_STARTUP group across all DLCs, and never revert permanent assets from
-- a vehicle cleanup: another mount may still use them.
Module.AssetPack={revision=PACK.revision,name=PACK.name,group=PACK.group,groupHash=PACK.groupHash}
local function normalized_path(value)
 return type(value)=='string'and value:match('^%s*(.-)%s*$'):gsub('\\','/'):gsub('/+$',''):lower()or''
end
local function normalized_name(value)return type(value)=='string'and value:lower():gsub('%s+','')or''end

local function scoped_activator(runtime,spec,validate,registered)
 local f,file,n,u=runtime.FeatureMgr,runtime.FileMgr,runtime.Natives,runtime.Utils
 local state,detail,loadedAt,groupCalls,nextGroupAt='NEW',nil,nil,0,nil
 local ownedSelection,submitted
 local API={}
 local function observe()
  assert(f and type(f.GetFeature)=='function'and type(f.GetCurrentFeatureListString)=='function','The Cherax DLC loader API is unavailable')
  assert(file and type(file.GetMenuRootPath)=='function'and type(file.DoesFileExist)=='function','The Cherax DLC folder API is unavailable')
  local root=file.GetMenuRootPath()
  assert(type(root)=='string'and root~='','The Cherax DLC folder is unavailable');root=root:gsub('[\\/]+$','')
  local pack=root..'/DLCs/'..spec.name..'/dlc.rpf'
  assert(file.DoesFileExist(pack)==true,'The reviewed '..spec.name..' DLC pack is missing')
  local target={[spec.name]=true,[spec.name..'/dlc.rpf']=true,['dlcs/'..spec.name]=true,
   ['dlcs/'..spec.name..'/dlc.rpf']=true,[normalized_path(root..'/DLCs/'..spec.name)]=true,[normalized_path(pack)]=true}
  local list=f.GetFeature(spec.listHash)
  assert(list and list:GetType()==13 and list:IsPlayerFeature()==false,'Unexpected Cherax DLC list type or scope')
  local values,index=list:GetList(),list:GetListIndex();local kind=type(values)
  assert((kind=='table'or kind=='userdata')and finite(index,1e10)and index%1==0 and index>=0,'The Cherax DLC list or selection is unreadable')
  local selected=f.GetCurrentFeatureListString(spec.listHash)
  assert(type(selected)=='string','The selected Cherax DLC name is unreadable')
  local lengthOK,length=false,nil;if kind=='userdata'then lengthOK,length=pcall(function()return #values end)end
  local keys,snapshot={},{}
  local function add(key,value)
   assert(type(key)=='number'and key%1==0 and type(value)=='string'and #value<=1024,'Unreadable Cherax DLC entry')
   assert(snapshot[key]==nil,'Duplicate Cherax DLC list key');keys[#keys+1]=key
   assert(#keys<=256,'The Cherax DLC list exceeds the supported bound');snapshot[key]=value
  end
  local sawEntry=false
  local enumerated=pcall(function()for key,value in pairs(values)do sawEntry=true;add(key,value)end end)
  if not enumerated then
   assert(kind=='userdata'and not sawEntry,'The Cherax DLC list enumeration failed')
   assert(lengthOK and finite(length,257)and length>=0 and length%1==0,'The Cherax DLC proxy length is unreadable')
   for key=0,length do local readable,value=pcall(function()return values[key]end);if readable and value~=nil then add(key,value)end end
   assert(#keys==length,'The Cherax DLC proxy is incomplete')
  elseif kind=='userdata'and lengthOK then
   assert(finite(length,257)and length>=0 and length%1==0 and #keys==length,'The Cherax DLC proxy length disagrees with its entries')
  end
  table.sort(keys)
  local matches,label,matchingKey,currentMatches,currentKey,signature=0,nil,nil,0,nil,{}
  for _,key in ipairs(keys)do
   local value=snapshot[key];signature[#signature+1]=('%s:%d:%s'):format(key,#value,value)
   if target[normalized_path(value)]then matches=matches+1;label=value;matchingKey=key end
   if value==selected then currentMatches=currentMatches+1;currentKey=key end
  end
  assert(matches==1,'Refresh the Cherax DLC list so it contains one '..spec.name..' entry, then toggle the roof turret off and on')
  -- Infer table-key/index offset only from a unique observed current selection
  -- and a complete contiguous zero- or one-based list. Never guess a target.
  local offset
  if currentMatches==1 and #keys>0 and(keys[1]==0 or keys[1]==1)then
   offset=currentKey-index
   if offset~=keys[1]then offset=nil end
   for i,key in ipairs(keys)do if key~=keys[1]+i-1 then offset=nil end end
  end
  return{list=list,index=index,selected=selected,key=matchingKey,label=label,offset=offset,
   signature=table.concat(signature,'\n'),root=normalized_path(root),name=list:GetName(false)}
 end
 local function same_list(a,b)return a.list==b.list and a.signature==b.signature and a.root==b.root and a.name==b.name and a.key==b.key and a.label==b.label end
 local function restore_selection(confirmed)
  local owned=ownedSelection;if not owned then return end;ownedSelection=nil
  -- OnClick may queue a consumer that reads the list selection later, even if
  -- it throws. Until all exact models register, leave our V4 choice in place
  -- and relinquish ownership rather than feeding that consumer a foreign DLC.
  if submitted and not confirmed then return end
  -- A user or another script changing the selection takes ownership. Never
  -- overwrite that newer choice, nor touch a replaced/reordered list.
  pcall(function()
   local now=observe()
   if same_list(owned.current,now)and now.index==owned.current.index and now.selected==owned.current.selected then
    now.list:SetListIndex(owned.previous.index)
   end
  end)
 end
 local function loader()
  local value=f.GetFeature(spec.loadHash)
  assert(value and value:GetType()==0 and value:IsPlayerFeature()==false and normalized_name(value:GetName(false))=='loaddlc','The expected single Load DLC callback is unavailable')
  return value
 end
 function API.Step(manifest,now)
  assert(finite(now,1e17)and now>=0,'Invalid roof asset clock')
  if not validate(manifest)then return'unsupported','The asset manifest does not match the reviewed pack'end
  if registered(manifest)then restore_selection(true);state='READY';return'ready'end
  if state=='FAILED'then return'unsupported',detail end
  if state=='LOADED'or state=='REQUESTED'then
   if now<=loadedAt then return'pending','Waiting for the queued Cherax DLC load'end
   if groupCalls>=16 then restore_selection();state='FAILED';detail='The reviewed roof assets did not register; refresh the Cherax DLC list and retry';return'unsupported',detail end
   if nextGroupAt and now<nextGroupAt then return'dispatched','Waiting for the scoped roof asset activation'end
   local ok,why=pcall(function()
    assert(n and type(n.InvokeVoid)=='function','The content activation native is unavailable')
    groupCalls=groupCalls+1;nextGroupAt=now+500
    assert(n.InvokeVoid(H.activate_content_group,spec.groupHash)~=false,'The content activation native rejected the roof group')
   end)
   if not ok then restore_selection();state='FAILED';detail=tostring(why);return'unsupported',detail end
   state='REQUESTED';return'dispatched','Waiting for the scoped roof asset activation'
  end
  local ok,why=pcall(function()
   local first=observe();local action=loader()
   if first.selected~=first.label then
    assert(first.offset~=nil and type(first.list.SetListIndex)=='function','Select '..spec.name..' in the Cherax DLC list, then retry')
    local targetIndex=first.key-first.offset
    assert(targetIndex>=0,'The exact roof DLC index is unavailable')
    local expected={};for key,value in pairs(first)do expected[key]=value end
    expected.index=targetIndex;expected.selected=first.label
    ownedSelection={previous=first,current=expected}
    first.list:SetListIndex(targetIndex)
    local selected=observe()
    assert(same_list(first,selected)and selected.index==targetIndex and selected.selected==first.label,'The exact roof DLC selection did not verify')
    first=selected
   end
   local last=observe()
   assert(same_list(first,last)and first.index==last.index and first.selected==last.selected and last.selected==last.label,'The selected Cherax DLC changed before loading')
   assert(action:GetType()==0 and action:IsPlayerFeature()==false and normalized_name(action:GetName(false))=='loaddlc','The single Load DLC callback changed')
   -- All selection/readback and callback work is synchronous, without yielding.
   -- Keep our selection while the queued callback completes; restore only on
   -- confirmed model registration, and only while still ours.
   submitted=true -- Queue submission may occur before OnClick returns or throws.
   assert(action:OnClick()~=false,'The single Load DLC callback rejected the request')
   state='LOADED';loadedAt=now
  end)
  if not ok then restore_selection();state='FAILED';detail=tostring(why);return'unsupported',detail end
  return'pending','Loading '..spec.name..' before activating its object archetypes'
 end
 function API.Snapshot()return{state=state,detail=detail,groupCalls=groupCalls}end
 function API.Stop()
  restore_selection()
  -- A queued single-pack load remains in flight after cancellation. Retain
  -- that bounded activation state so re-enabling cannot dispatch it twice.
  -- An explicit off/on may retry a failure before submission. An uncertain
  -- submitted failure stays latched until the exact models register.
  if state~='LOADED'and state~='REQUESTED'and not(state=='FAILED'and submitted)then
   state='NEW';detail=nil;loadedAt=nil;groupCalls=0;nextGroupAt=nil;submitted=nil
  end
 end
 return API
end

function Module.CreateAssetActivator(runtime)
 local n,u=runtime.Natives,runtime.Utils
 return scoped_activator(runtime,PACK,function(manifest)
  return type(manifest)=='table'and manifest.revision==PACK.revision and type(manifest.models)=='table'
   and manifest.models.base=='cscript4_speedo50_base'and manifest.models.upper=='cscript4_speedo50_upper'and manifest.models.barrel=='cscript4_speedo50_barrel'
 end,
  function(manifest)
  if not(u and type(u.Joaat)=='function'and n and type(n.InvokeBool)=='function')then return false end
  for _,name in ipairs({'base','upper','barrel'})do
   local hash=u.Joaat(manifest.models[name])&0xffffffff
   if n.InvokeBool(H.valid,hash)~=true or n.InvokeBool(H.cdimage,hash)~=true then return false end
  end
  return true
 end)
end
local AUDIO_PACK={revision='speedo50-audio-v1',name='cscript_roof50_audio_v1',group='CSCRIPT_ROOF50_AUDIO_V1_RUNTIME',
 groupHash=3168962240,listHash=2088582328,loadHash=3992157797,soundSet='CSCRIPT_ROOF50_SOUNDSET',event='CSCRIPT_ROOF50_FIRE'}
Module.AudioPack=AUDIO_PACK
function Module.CreateAudioActivator(runtime)
 return scoped_activator(runtime,AUDIO_PACK,function(manifest)return type(manifest)=='table'and manifest.revision==AUDIO_PACK.revision end,
  function()return type(runtime.AudioConfirmed)=='function'and runtime.AudioConfirmed()==true end)
end

local asset_manifest
local function copy_vector(v)
 if type(v)~='table'or not finite(v.x,10)or not finite(v.y,10)or not finite(v.z,10)then return nil end
 return vector(v.x,v.y,v.z)
end
local function validate_manifest(value)
 if type(value)~='table'or type(value.models)~='table'or type(value.revision)~='string'or value.revision==''then return nil end
 if not finite(value.supportRadius,1)or value.supportRadius<.015 then return nil end
 local result={revision=value.revision,supportRadius=value.supportRadius,models={}}
 for _,name in ipairs({'base','upper','barrel'})do
  local model=value.models[name]
  if type(model)~='string'or not model:match('^cscript[0-9]*_speedo50_[a-z0-9_]+$')then return nil end
  result.models[name]=model
 end
 for _,key in ipairs({'upperOffset','barrelOffset','muzzle'})do
  result[key]=copy_vector(value[key]);if not result[key]then return nil end
 end
 if dot(result.muzzle,result.muzzle)<.01 then return nil end
 if result.revision==PACK.revision and math.abs(result.supportRadius-.165)<.000001
  and result.models.base=='cscript4_speedo50_base'and result.models.upper=='cscript4_speedo50_upper'and result.models.barrel=='cscript4_speedo50_barrel'
  and math.abs(result.upperOffset.x)<.000001 and math.abs(result.upperOffset.y-.055046)<.000001 and math.abs(result.upperOffset.z-.321427)<.000001
  and dot(result.barrelOffset,result.barrelOffset)<1e-12 and math.abs(result.muzzle.x-.001788)<.000001
  and math.abs(result.muzzle.y-.818553)<.000001 and math.abs(result.muzzle.z-.009504)<.000001 then result.supportPolicy=PACK.revision end

 return result
end
function Module.SetAssetManifest(value)
 local validated=validate_manifest(value)
 assert(validated,'Exact turret asset manifest is incomplete or invalid')
 asset_manifest=validated
end

function Module.CreateNativeAdapter(runtime)
 assert(type(runtime)=='table'and runtime.Natives and runtime.Memory and runtime.GTA and runtime.Utils,'Roof turret native services are incomplete')
 local n,m,gta=runtime.Natives,runtime.Memory,runtime.GTA
 local speedo=runtime.Utils.Joaat('speedo4')&0xFFFFFFFF
 local weapon=runtime.Utils.Joaat('VEHICLE_WEAPON_SPEEDO4_TURRET_MG')&0xFFFFFFFF
 local API={}
 local audioConfirmed,audioDispatched,ptfxRequested=false,false,false
 local audioActivator=Module.CreateAudioActivator({FeatureMgr=runtime.FeatureMgr,FileMgr=runtime.FileMgr,Natives=n,Utils=runtime.Utils,
  AudioConfirmed=function()return audioConfirmed end})
 local function invoke(kind,hash,...)
  assert(type(n[kind])=='function','Missing native API '..kind)
  local a,b,c=n[kind](hash,...)
  if kind=='InvokeVoid'then assert(a~=false,'Native operation rejected')
  elseif kind=='InvokeBool'then assert(type(a)=='boolean','Native boolean unavailable')
  elseif kind=='InvokeInt'then assert(finite(a,1e17)and a%1==0,'Native integer unavailable')
  elseif kind=='InvokeFloat'then assert(finite(a,1e6),'Native float unavailable')end
  return a,b,c
 end
 local function bool(hash,...)return invoke('InvokeBool',hash,...)end
 local function int(hash,...)return invoke('InvokeInt',hash,...)end
 local function void(hash,...)invoke('InvokeVoid',hash,...)end
 local function effects_report(record,key,detail)
  if record[key]==detail then return end;record[key]=detail
  if type(runtime.Report)=='function'then pcall(runtime.Report,key,detail)end
 end
