 local function seed_candidates(record)
  local c=record.context
  local candidates={}
  local function local_bone(name)
   local index=int(H.bone_index,c.vehicle,name)
   if index<0 then return nil end
   local world=v3(H.bone_world,c.vehicle,index)
   return v3(H.local_coords,c.vehicle,world.x,world.y,world.z)
  end
  local left,right=local_bone('seat_dside_f'),local_bone('seat_pside_f')
  local rearLeft,rearRight=local_bone('seat_dside_r'),local_bone('seat_pside_r')
  local front=left and right and vector((left.x+right.x)*.5,(left.y+right.y)*.5,(left.z+right.z)*.5)or left or right
  local rear=rearLeft and rearRight and vector((rearLeft.x+rearRight.x)*.5,(rearLeft.y+rearRight.y)*.5,(rearLeft.z+rearRight.z)*.5)or rearLeft or rearRight
  local roof=local_bone('roof')or local_bone('roof_2')
  -- Seat-derived cabin locations avoid probing a hood, rear spoiler, or cargo
  -- simply because those happen to be the highest parts of the model bounds.
  if front and rear then
   candidates[#candidates+1]=vector((front.x+rear.x)*.5,(front.y+rear.y)*.5,math.max(front.z,rear.z))
  end
  if front then candidates[#candidates+1]=front end
  if rear then candidates[#candidates+1]=rear end
  if roof and front then candidates[#candidates+1]=vector(roof.x,roof.y,front.z)end
  assert(#candidates>0,'This vehicle has no measurable cabin roof anchor')
  record.candidates=candidates;record.candidateIndex=1
 end
 local function begin_roof_probe(record,now)
  local speed=invoke('InvokeFloat',H.speed,record.context.vehicle)
  if speed>.75 then return'pending','Hold still briefly to fit the roof mount'end
  local center=record.candidates[record.candidateIndex]
  if not center then return'unsupported','No roof patch supports the entire .50-cal mount'end
  local offsets=record.supportOffsets
  local frame=matrix(record,record.context.vehicle)
  local batch={center=center,frame=frame,started=now,handles={}}
  record.roofBatch=batch
  for _,offset in ipairs(offsets)do
   local high=v3(H.offset_world,record.context.vehicle,center.x+offset[1],center.y+offset[2],record.vehicleBounds.max.z+.25)
   local low=v3(H.offset_world,record.context.vehicle,center.x+offset[1],center.y+offset[2],center.z)
   batch.handles[#batch.handles+1]=shape(record,high,low,2,0,4)
  end
  return'pending','Measuring roof contact'
 end
 local function finish_roof_probe(record,now)
  local batch=record.roofBatch;batch.results=batch.results or{}
  local all=true
  for index,handle in ipairs(batch.handles)do
   if batch.results[index]==nil then batch.results[index]=poll(record,handle)end
   if batch.results[index]==nil then all=false end
  end
  if not all then
   assert(now-batch.started<=750,'Roof collision probe timed out')
   return'pending','Measuring roof contact'
  end
  record.roofBatch=nil
  local current=matrix(record,record.context.vehicle)
  if distance2(current.position,batch.frame.position)>.0009 or dot(current.up,batch.frame.up)<.9998
   or dot(current.forward,batch.frame.forward)<.9998 then
   return'pending','Hold still briefly to finish the roof measurement'
  end
  local samples={}
  for index=1,#batch.handles do
   local result=batch.results[index]
   if not result or not result.hit or result.entity~=record.context.vehicle then
    record.candidateIndex=record.candidateIndex+1;return'pending','Checking the next cabin roof patch'
   end
   local p=v3(H.local_coords,record.context.vehicle,result.point.x,result.point.y,result.point.z)
   local normal=local_direction(current,result.normal)
   samples[index]={entity=result.entity,x=p.x,y=p.y,z=p.z,nx=normal.x,ny=normal.y,nz=normal.z}
  end
  local rendered,roofSource=Module.ResolveRenderedRoof(RENDERED_ROOFS[record.context.model],{
   entity=record.context.vehicle,index=record.candidateIndex,center=batch.center,samples=samples,
   supportRadius=record.assets.supportRadius,roofMod=int(H.get_mod,record.context.vehicle,10)})
  if rendered then samples=rendered end
  local fit,why,measurement=Module.FitRoof({entity=record.context.vehicle,center=batch.center,bounds=record.baseBounds,
   supportRadius=record.assets.supportRadius,samples=samples,supportPolicy=record.assets.supportPolicy})
  -- At most one line per cabin candidate. ROOF_FIT is an internal report event;
  -- it does not replace the concise controller/UI status or expose fit metrics there.
  if type(runtime.Report)=='function'then
   local gap=measurement and('%.6f'):format(measurement.maxGap)or'unavailable'
   pcall(runtime.Report,'ROOF_FIT',('model=0x%08X mode=%s candidate=%d/%d gap=%s limit=%.3f reason=%s'):format(
    record.context.model,roofSource and'rendered'or'collision',record.candidateIndex,#record.candidates,gap,
    measurement and measurement.gapLimit or .01,fit and'accepted'or tostring(why)))
  end
  if not fit then record.candidateIndex=record.candidateIndex+1;return'pending',why end
  record.fit=fit;record.roofSource=roofSource;return'fit'
 end
 local function attach(child,parent,position,rotation)
