 local function sync_attachments(record)
  if record.processDisabled then return end
  -- Refresh the owned chain in parent order before reading its matrices.
  -- This is an update request, never a substitute for pose/contact checks.
  local ok=pcall(function()
   void(H.process_attachments,record.context.vehicle)
   for _,part in ipairs(record.parts)do void(H.process_attachments,part.handle)end
  end)
