 local function begin_pose(record,now,yaw,pitch,preserveClearance)
  assert(not record.pendingPose,'An attachment pose is already settling')
  local pose=Module.YawRoofFit(record.fit,yaw)
  local previous=record.pose
  preserveClearance=preserveClearance==true and previous~=nil
  record.pendingPose={base=pose,yaw=yaw,pitch=pitch,started=now,deadline=now+250,continuous=preserveClearance}
  if not preserveClearance then visibility(record,false)end
  -- Initial/external repairs stay hidden until their full pose verifies.
  -- Ordinary aim updates stay visible and get fresh shot-time clearance.
  local base,upper,barrel=record.parts[1].handle,record.parts[2].handle,record.parts[3].handle
  attach(base,record.context.vehicle,pose.position,pose.rotation)
  -- Preserve the original yaw pivot followed by the housing/gun pitch pivot.
  attach(upper,base,record.assets.upperOffset,vector(pitch,0,0))
