 -- Peers have the stock weapon archetype, but not the private three-part pack.
 -- Keep their single stock approximation separate from the exact local assembly.
 local PROXY_MODEL='w_mg_combatmg'
 local PROXY_MUZZLE=vector(.5941771,-.000036335,.05459582)
 local function proxy_control(proxy)
  if not bool(H.networked,proxy.handle)then return true end
  if bool(H.has_control,proxy.handle)then return true end
  bool(H.request_control,proxy.handle)
  return bool(H.has_control,proxy.handle)
 end
 proxy_visible=function(record,visible)
  local proxy=record.networkProxy
  if not proxy or proxy.identityDebt or not part_owned(proxy)then return false end
  if not proxy_control(proxy)or not part_owned(proxy)then return false end
  if proxy.visible~=visible then void(H.visible,proxy.handle,visible,false);proxy.visible=visible end
  return true
 end
 local function prepare_proxy(record)
  if not record.context.online then return true end
  local proxy=record.networkProxy
  if not proxy then
   local model=record.proxyModel
   assert(model and bool(H.loaded,model),'Stock peer gun model is not loaded')
   local p=v3(H.offset_world,record.context.vehicle,record.fit.position.x,record.fit.position.y,record.fit.position.z)
   local handle=gta.CreateObject(model,p.x,p.y,p.z,false,true)
   assert(finite(handle,1e10)and handle>0,'Stock peer gun could not be created')
   proxy={handle=handle,model=model,name='stock peer gun'};record.networkProxy=proxy
   -- Creation ownership is uninterrupted here. Capture before later yields;
   -- an uncaptured handle is never adopted on a later cleanup attempt.
   local ok,why=pcall(function()
    void(H.visible,handle,false,false);proxy.visible=false
    void(H.local_invisible,handle)
    proxy.address=address(handle)
    assert((int(H.model,handle)&0xFFFFFFFF)==model,'Unexpected stock peer gun identity')
   end)
   if not ok then
    if not proxy.address then
     proxy.identityDebt=true
     -- The creation handle is known only in this uninterrupted acquisition.
     -- A failed immediate deletion remains debt; later cleanup never adopts it.
     local cleaned,absent=pcall(function()
      if not bool(H.exists,handle)then return true end
      assert((int(H.model,handle)&0xFFFFFFFF)==model,'Fresh stock peer gun model changed')
      assert(proxy_control(proxy),'Fresh stock peer gun control unavailable')
      local p=buffer(record)+120
      assert(m.WriteInt(p,handle)~=false and m.ReadInt(p)==handle,'Fresh stock peer gun deletion pointer unavailable')
      void(H.delete,p)
      return not bool(H.exists,handle)
     end)
     if cleaned and absent==true then record.networkProxy=nil end
    end
    error(why)
   end
  end
  assert(part_owned(proxy),'Stock peer gun identity changed')
  API.Frame(record)
  if not bool(H.networked,proxy.handle)then return false,'Waiting for stock peer gun networking'end
  local netId=int(H.net_id,proxy.handle)
  if netId<=0 then return false,'Waiting for stock peer gun network registration'end
  if proxy.netId then assert(netId==proxy.netId,'Stock peer gun network identity changed')else proxy.netId=netId end
  if not proxy_control(proxy)then return false,'Waiting for control of the owned stock peer gun'end
  assert(part_owned(proxy),'Stock peer gun identity changed during control read')
  if not proxy.configured then
   void(H.net_all,proxy.netId,true)
   assert(part_owned(proxy),'Stock peer gun identity changed during network setup')
   void(H.net_migrate,proxy.netId,false)
   void(H.mission,proxy.handle,true,true);void(H.collision,proxy.handle,false,false)
   void(H.invincible,proxy.handle,true,false);void(H.no_collision,proxy.handle,record.context.vehicle,false)
   void(H.lod,proxy.handle,200);proxy.configured=true
  end
  return true
 end
 local function sync_proxy(record)
  if not record.context.online then return true end
  local ready,why=prepare_proxy(record)
  if not ready then return false,why end
  if not record.partsVisible or not record.pose or not pose_matches(record,record.pose)then
   proxy_visible(record,false);return false,'Waiting for the verified custom gun pose'
  end
  local proxy=record.networkProxy
  local carrier=matrix(record,record.context.vehicle)
  local barrel=matrix(record,record.parts[3].handle)
  -- Stock Combat MG points along +X; custom Speedo barrel points along +Y.
  -- Match both axes and the actual muzzle in world space, then attach directly
  -- to the networked carrier. A local custom parent cannot replicate to peers.
  local basis={right=barrel.forward,forward=vector(-barrel.right.x,-barrel.right.y,-barrel.right.z),up=barrel.up}
  local muzzle=world_point(barrel,record.assets.muzzle)
  local delta=transform(basis,PROXY_MUZZLE)
  local world=vector(muzzle.x-delta.x,muzzle.y-delta.y,muzzle.z-delta.z)
  local position=v3(H.local_coords,record.context.vehicle,world.x,world.y,world.z)
  local localBasis={right=local_direction(carrier,basis.right),forward=local_direction(carrier,basis.forward),up=local_direction(carrier,basis.up)}
  local rotation=vector(math.deg(math.atan(localBasis.forward.z,localBasis.up.z)),
   math.deg(math.asin(math.max(-1,math.min(1,-localBasis.right.z)))),math.deg(math.atan(localBasis.right.y,localBasis.right.x)))
  local function matches()
   assert(part_owned(proxy),'Stock peer gun identity changed before pose verification')
   if int(H.attached_to,proxy.handle)~=record.context.vehicle then return false end
   local actual=matrix(record,proxy.handle)
   if distance2(actual.position,world)>.005*.005 then return false end
   for _,axis in ipairs({'right','forward','up'})do if dot(norm(actual[axis]),norm(basis[axis]))<math.cos(math.rad(1))then return false end end
   return true
  end
  if not matches()then
   if not proxy_visible(record,false)then return false,'Waiting for owned stock peer gun visibility control'end
   assert(part_owned(proxy),'Stock peer gun identity changed before attachment')
   attach(proxy.handle,record.context.vehicle,position,rotation)
   if not record.processDisabled then pcall(void,H.process_attachments,record.context.vehicle)end
  end
  if not matches()then return false,'Verifying stock peer gun attachment'end
  if not proxy_visible(record,true)then return false,'Waiting for owned stock peer gun visibility control'end
  return true
 end
 local function finish_pose(record,now)
  local pending=assert(record.pendingPose,'No attachment pose is awaiting verification')
  assert(now>=pending.started and now<=pending.deadline,'Turret attachment pose did not settle within 250 ms')
  sync_attachments(record)
  local ready,why=pose_matches(record,pending)
  if not ready then return false,why end
  record.pose=pending;record.pendingPose=nil;record.yaw,record.pitch=pending.yaw,pending.pitch
  visibility(record,true)
  return true
 end
 local function pose_step(record,now)
  local ready,why=finish_pose(record,now)
  if ready then
   local replicated,detail=sync_proxy(record)
   if replicated then return'ready'end
   return'pending',detail
  end
  sync_proxy(record)
  return'pending','Verifying turret attachment: '..why
 end
 local function create_parts(record,now)
  local c=record.context
  local world=v3(H.offset_world,c.vehicle,record.fit.position.x,record.fit.position.y,record.fit.position.z)
  for _,name in ipairs(record.partNames)do
   local model=record.hashes[name]
   local info=gta.GetModelInfoFromHash(model)
   assert(info,'Exact turret model info disappeared')
   local create=gta.CreateObject
   if type(info.IsWorldObject)=='function'and info:IsWorldObject()and type(gta.CreateWorldObject)=='function'then create=gta.CreateWorldObject end
   local handle=create(model,world.x,world.y,world.z,false,false)
   assert(finite(handle,1e10)and handle>0,'Exact turret component could not be created')
   local part={handle=handle,model=model,name=name};record.parts[#record.parts+1]=part
   local captured,captureError=pcall(function()
    -- The just-returned creation handle is ours in this uninterrupted call.
    -- Hide it before an identity read can throw and leave a visible loose prop.
    void(H.visible,handle,false,false)
    part.address=address(handle)
    assert((int(H.model,handle)&0xFFFFFFFF)==model,'Unexpected turret component identity')
   end)
   if not captured then
    if not part.address then
     part.identityDebt=true
     -- This provisional deletion is permitted only here, before create_parts
     -- returns or yields. Release must never adopt this handle by model later.
     local cleaned,absent=pcall(function()
      if not bool(H.exists,handle)then return true end
      assert((int(H.model,handle)&0xFFFFFFFF)==model,'Fresh component model changed during acquisition')
      local p=buffer(record)+120
      assert(m.WriteInt(p,handle)~=false,'Fresh component deletion pointer write failed')
      assert(m.ReadInt(p)==handle,'Fresh component deletion pointer was not written')
      void(H.delete,p)
      return not bool(H.exists,handle)
     end)
     if cleaned and absent==true then table.remove(record.parts,#record.parts)end
    end
    error(captureError)
   end
   void(H.mission,handle,true,true)
   void(H.collision,handle,false,false);void(H.invincible,handle,true,false)
   void(H.no_collision,handle,c.vehicle,false);void(H.lod,handle,200)
  end
  record.partsVisible=false;record.nextShot=0
  record.roofMod=int(H.get_mod,c.vehicle,10)
  prepare_proxy(record)
  begin_pose(record,now,0,0)
  return pose_step(record,now)
 end
 function API.Step(record,now)
  assert(carrier_owned(record),'Vehicle identity changed while preparing the mount')
  if record.context.native then return native_step(record)end
  record.mode='portable'
  if not record.assets then
   local supplied=runtime.Assets or asset_manifest
   if type(supplied)=='function'then supplied=supplied()end
   local manifest=validate_manifest(supplied)
   if not manifest then return'unsupported','The reviewed three-part Speedo turret manifest is unavailable'end
   record.assets=manifest;record.partNames={'base','upper','barrel'};record.weapon=weapon
   record.hashes={}
   for _,name in ipairs(record.partNames)do
    record.hashes[name]=runtime.Utils.Joaat(manifest.models[name])&0xFFFFFFFF
   end
   buffer(record)
  end
  if not record.assetsReady then
   if type(runtime.EnsureAssets)=='function'then
    local ready,why=runtime.EnsureAssets(record.assets)
    if ready~=true then return'pending',why or'Loading the exact Speedo .50-cal assets'end
   end
   local loaded,pending=true,{}
   for _,name in ipairs(record.partNames)do
    local hash=record.hashes[name]
    local why
    if not bool(H.valid,hash)then why='not registered'
    elseif not bool(H.cdimage,hash)then why='not in streaming image'
    else
     if not record.modelRefs[hash]then record.modelRefs[hash]=true;void(H.request,hash)end
     if not bool(H.loaded,hash)then why='waiting for streaming'end
    end
    if why then loaded=false;pending[#pending+1]=name..': '..why end
   end
   if record.context.online then
    record.proxyModel=record.proxyModel or(runtime.Utils.Joaat(PROXY_MODEL)&0xFFFFFFFF)
    local hash=record.proxyModel
    if not bool(H.valid,hash)or not bool(H.cdimage,hash)then
     loaded=false;pending[#pending+1]='stock peer gun: unavailable'
    else
     if not record.modelRefs[hash]then record.modelRefs[hash]=true;void(H.request,hash)end
     if not bool(H.loaded,hash)then loaded=false;pending[#pending+1]='stock peer gun: waiting for streaming'end
    end
   end
   if not loaded then
    local label='Speedo .50-cal'
    record.assetWaitDetail=label..' assets unavailable ('..table.concat(pending,'; ')..')'
    return'pending',record.assetWaitDetail
   end
   record.assetWaitDetail=nil
   record.weaponRequested=true;void(H.weapon_request,record.weapon,31,0)
   record.baseBounds=dimensions(record,record.hashes.base)
   local offsets,why=support_offsets(record.baseBounds,record.assets.supportRadius)
   if not offsets then return'unsupported',why end
   record.supportOffsets=offsets
   record.vehicleBounds=dimensions(record,record.context.model)
   seed_candidates(record);record.assetsReady=true
  end
  -- A pending assembly owns its three objects already. Verify it in place;
  -- entering create_parts again would duplicate objects on every settle tick.
  if record.pendingPose then return pose_step(record,now)end
  if #record.parts>0 then
   local ready,why=sync_proxy(record);return ready and'ready'or'pending',why
  end
  if not bool(H.weapon_loaded,record.weapon)then return'pending','Loading the roof machine gun weapon asset'end
  prepare_effects(record,now)
  if record.fit then return create_parts(record,now)end
  if record.roofBatch then
   local state,why=finish_roof_probe(record,now)
   if state=='fit'then return create_parts(record,now)end
   return state,why
  end
  return begin_roof_probe(record,now)
 end
 local function fire_allowed()
  if not runtime.GUI or type(runtime.GUI.IsOpen)~='function'or runtime.GUI.IsOpen()~=false then return false end
  return not bool(H.paused)and not bool(H.faded)and not bool(H.fading)
   and bool(H.control_on,gta.GetLocalPlayerId())
 end
 local function camera_ray(record,now)
  local position,rotation
  local ok=pcall(function()
   position=v3(H.rendered_coord);rotation=v3(H.rendered_rotation,2)
   assert(finite(position.x,1e6)and finite(position.y,1e6)and finite(position.z,1e6)
    and finite(rotation.x)and finite(rotation.y)and finite(rotation.z),'Invalid rendered camera')
  end)
  if not ok then position=v3(H.cam_coord);rotation=v3(H.cam_rotation,2)end
  local pitch,yaw=math.rad(rotation.x),math.rad(rotation.z)
  local direction=vector(-math.sin(yaw)*math.cos(pitch),math.cos(yaw)*math.cos(pitch),math.sin(pitch))
  local target=vector(position.x+direction.x*500,position.y+direction.y*500,position.z+direction.z*500)
  if record.aimProbe then
   local probe=record.aimProbe
   local result=poll(record,probe.handle)
   if result~=nil then
    if result and now-probe.started<=150 then
     local point=result.hit and result.point or probe.target
     record.aim={distance=math.max(2,math.min(500,math.sqrt(distance2(point,probe.position)))),time=now}
    end
    record.aimProbe=nil
   end
  end
  if not record.aimProbe then
   record.aimProbe={handle=shape(record,position,target,511,record.context.vehicle,4),started=now,target=target,position=position,direction=direction}
  end
  local aim=record.aim
  local wanted=aim and now-aim.time<=150 and aim.distance or 500
  record.aimAt=now;record.aimDistance=wanted
  local distance=record.aimDistance
  -- Apply measured depth to this frame's camera direction. Reusing an old
  -- world hit point otherwise makes tracking trail, then snap on a ray miss.
  return vector(position.x+direction.x*distance,position.y+direction.y*distance,position.z+direction.z*distance),true
 end
 local function gun_muzzle(record,barrel)
  return v3(H.offset_world,barrel,record.assets.muzzle.x,record.assets.muzzle.y,record.assets.muzzle.z)
 end
 local function aim_angles(record,carrier,frame,target)
  -- Solve the yaw/pitch pivots directly: turning moves the muzzle, so aiming
  -- from its previous position (or repeatedly chasing it) fails close up.
  local anchor=world_point(carrier,record.fit.anchor)
  local t=local_direction(frame,vector(target.x-anchor.x,target.y-anchor.y,target.z-anchor.z))
  local u=record.assets.upperOffset;local bottom=record.fit.baseBottom
  local b,muzzle=record.assets.barrelOffset,record.assets.muzzle
  local ux,uy,uz=u.x-bottom.x,u.y-bottom.y,u.z-bottom.z
  local vx,vz=b.x+muzzle.x,b.z+muzzle.z
  local horizontal=math.sqrt(t.x*t.x+t.y*t.y)
  if horizontal<.001 then return end
  local lateral=ux+vx
  local yaw=math.atan(-t.x,t.y)+math.asin(math.max(-1,math.min(1,lateral/horizontal)))
  local forward=-t.x*math.sin(yaw)+t.y*math.cos(yaw)-uy
  local height=t.z-uz;local radius=math.sqrt(forward*forward+height*height)
  if radius<.001 then return end
  local pitch=math.atan(height,forward)-math.asin(math.max(-1,math.min(1,vz/radius)))
  yaw=math.deg(yaw);yaw=(yaw+180)%360-180
  -- A continuous travel range avoids the old front-sector depression cliff.
  -- Actual carrier obstruction is checked along the barrel before each shot.
  return yaw,math.max(-85,math.min(85,math.deg(pitch)))
 end
 local function draw_crosshair(record,point)
  local ok,why=pcall(function()
   local p=buffer(record)+224
   assert(m.WriteFloat(p,1e6)~=false and m.WriteFloat(p+8,1e6)~=false,'Crosshair output initialization failed')
   if not bool(H.project,point.x,point.y,point.z,p,p+8)then return end
   local x,y=m.ReadFloat(p),m.ReadFloat(p+8)
   if not finite(x,2)or not finite(y,2)or x<0 or x>1 or y<0 or y>1 then return end
   -- Quantize subpixel shimmer only. A new screen position applies now;
   -- no moving average or previous-frame reticle position is involved.
   pcall(function()
    local size=buffer(record)+240
    m.WriteInt(size,0);m.WriteInt(size+8,0);void(H.resolution,size,size+8)
    local width,height=m.ReadInt(size),m.ReadInt(size+8)
    if finite(width,32769)and finite(height,32769)and width>=64 and height>=64 then
     x=math.floor(x*width+.5)/width;y=math.floor(y*height+.5)/height
    end
   end)
   local aspect=invoke('InvokeFloat',H.aspect,false);assert(aspect>.2 and aspect<8,'Invalid crosshair aspect ratio')
   local function rect(dx,dy,w,h,r,g,b,a)void(H.draw_rect,x+dx,y+dy*aspect,w,h*aspect,r,g,b,a,false)end
   for _,side in ipairs({-1,1})do
    rect(side*.0042,0,.0044,.0015,0,0,0,220);rect(side*.0042,0,.0034,.00065,245,245,245,245)
    rect(0,side*.0042,.0015,.0044,0,0,0,220);rect(0,side*.0042,.00065,.0034,245,245,245,245)
   end
   rect(0,0,.0015,.0015,0,0,0,220);rect(0,0,.00065,.00065,245,245,245,245)
  end)
  if not ok then effects_report(record,'RETICLE_PENDING',tostring(why))end
 end
 function API.Update(record,now)
  if not carrier_owned(record)then return false,'Vehicle identity changed'end
  if record.mode=='native'then
   if int(H.get_mod,record.context.vehicle,10)~=record.installedMod then return false,'The native roof modification was changed'end
   return true
  end
  prepare_effects(record,now)
  local soundOK,soundError=pcall(drain_sounds,record,now,false)
  if not soundOK then effects_report(record,'EFFECTS_PENDING',tostring(soundError))end
  for _,part in ipairs(record.parts)do if not part_owned(part)then return false,'An owned turret component disappeared'end end
  -- Body-health loss is not evidence that the roof changed. Bumper/door
  -- impacts must not remove a working mount; actual roof modifications do.
  if not record.surfaceCheckedAt or now-record.surfaceCheckedAt>=250 then
   local roofMod=int(H.get_mod,record.context.vehicle,10)
   record.surfaceCheckedAt=now
   if roofMod~=record.roofMod then
    return'rebuild','Roof changed; hold still briefly to refit the mount'
   end
  end
  -- This already-active portable mount owns the stock attack inputs even while
  -- a new pose is hidden and settling. GUI/pause/fade/control gates still leave
  -- those inputs untouched, and a pending pose can never authorize a shot.
  local controlsActive=fire_allowed()
  local trigger=false
  if controlsActive then
   trigger=bool(H.pressed,0,24)or bool(H.disabled_pressed,0,24)
    or bool(H.pressed,0,69)or bool(H.disabled_pressed,0,69)
   for _,control in ipairs({24,68,69,70})do void(H.disable_control,0,control,true)end
  end
  sync_attachments(record)
  if record.pendingPose then
   finish_pose(record,now)
   if record.pendingPose and not record.pendingPose.continuous then return true end
  elseif not pose_matches(record,assert(record.pose,'The turret has no verified pose'))then
   -- An externally disturbed attachment is hidden and reverified before any
   -- firing. The same pending record/deadline survives every subsequent tick.
   begin_pose(record,now,record.yaw,record.pitch)
   if not finish_pose(record,now)then return true end
  end
  if not controlsActive then return true end
  local target,fresh=camera_ray(record,now)
  local barrel=record.parts[3].handle
  local carrierFrame=matrix(record,record.context.vehicle)
  local frame={right=transform(carrierFrame,record.fit.basis.right),
   forward=transform(carrierFrame,record.fit.basis.forward),up=transform(carrierFrame,record.fit.basis.up)}
  local muzzle=gun_muzzle(record,barrel)
  local yaw,pitch=aim_angles(record,carrierFrame,frame,target)
  if not yaw then return true end
  -- Keep the last verified assembly visible while an ordinary aim update
  -- propagates. Collision evidence and the shot use the actual barrel below.
  if not record.pendingPose and(math.abs(yaw-record.yaw)>.02 or math.abs(pitch-record.pitch)>.02)then
   begin_pose(record,now,yaw,pitch,true)
   finish_pose(record,now)
  end
  -- A lagging child may still be rotating, but the mount must remain attached
  -- to its owned hierarchy with its foot on the measured roof before firing.
  for index,part in ipairs(record.parts)do
   local parent=index==1 and record.context.vehicle or record.parts[index-1].handle
   if int(H.attached_to,part.handle)~=parent then return true end
  end
  local foot=v3(H.offset_world,record.parts[1].handle,record.fit.baseBottom.x,record.fit.baseBottom.y,record.fit.baseBottom.z)
  if distance2(foot,world_point(carrierFrame,record.fit.anchor))>.005*.005 then return true end
  muzzle=gun_muzzle(record,barrel)
  local delta=vector(target.x-muzzle.x,target.y-muzzle.y,target.z-muzzle.z)
  local range=math.sqrt(dot(delta,delta));if range<.5 then return true end
  -- Camera intent can be one attachment update ahead. Both the clearance ray
  -- and projectile follow the actual verified barrel, never that future pose.
  local barrelFrame=matrix(record,barrel)
  local travel=norm(barrelFrame.forward)
  local shotRange=math.min(range,500)
  local finish=vector(muzzle.x+travel.x*shotRange,muzzle.y+travel.y*shotRange,muzzle.z+travel.z*shotRange)
  draw_crosshair(record,finish)
  -- Resolve self-clearance at the actual muzzle only when a round is due.
  -- This avoids making fire depend on last frame's camera, vehicle or aim.
  -- Synchronous probes are bounded by shot cadence; blocked retries are 33ms.
  if record.fireProbe then
   if poll(record,record.fireProbe.handle)~=nil then record.fireProbe=nil end
  end
  local clear=false
  if trigger and now>=record.nextShot and now>=(record.nextClearanceAt or 0)and not record.fireProbe then
   record.nextClearanceAt=now+33
   local function carrier_clear(start,endpoint)
    local handle=shape(record,start,endpoint,511,record.context.ped,4,true)
    local result=poll(record,handle)
    if result==nil then record.fireProbe={handle=handle};return false end
    return result and(not result.hit or result.entity~=record.context.vehicle)
   end
   -- A muzzle below/inside the roof must not bypass self-clearance simply
   -- because the outgoing ray begins on the far side of the carrier surface.
   clear=carrier_clear(barrelFrame.position,muzzle)and carrier_clear(muzzle,finish)
  end
  if trigger and fresh and clear and now>=record.nextShot then
   -- Keep the .50-cal damage/range; the requested faster cadence is 10 rps.
   void(H.shoot,muzzle.x,muzzle.y,muzzle.z,finish.x,finish.y,finish.z,175,true,record.weapon,record.context.ped,true,false,2000.0,record.context.vehicle,0)
   record.shotCount=(record.shotCount or 0)+1;shot_effects(record,now,barrel)
   record.nextShot=(record.nextShot>now-SHOT_INTERVAL and record.nextShot or now)+SHOT_INTERVAL
  end
  if trigger and(not record.fireReportedAt or now-record.fireReportedAt>=2000)then
   record.fireReportedAt=now
   if type(runtime.Report)=='function'then pcall(runtime.Report,'FIRE_STATS',('shots=%d flashes=%d sounds=%d clearance=%s pendingAim=%s'):format(
    record.shotCount or 0,record.flashCount or 0,record.soundCount or 0,tostring(clear==true),tostring(record.pendingPose~=nil)))end
  end
  return true
 end
 local update_local=API.Update
 function API.Update(record,now)
  local result,why=update_local(record,now)
  if result==true and record.mode=='portable'then sync_proxy(record)end
  return result,why
 end
 function API.Release(record)
  API.Frame(record)
  local proxy=record.networkProxy
  if proxy then
   if proxy.identityDebt then
    if bool(H.exists,proxy.handle)then return false,'Stock peer gun identity capture is unresolved'end
   elseif proxy.netId and bool(H.exists,proxy.handle)
    and(int(H.model,proxy.handle)&0xFFFFFFFF)==proxy.model and address(proxy.handle)==proxy.address
    and(not bool(H.networked,proxy.handle)or int(H.net_id,proxy.handle)<=0)then
    -- An unknown registration is not evidence that our entity disappeared.
    -- Retain ownership without visibility, attachment or deletion mutations.
    return false,'Waiting to revalidate the owned stock peer gun network identity'
   elseif part_owned(proxy)then
    if not proxy_control(proxy)then return false,'Waiting for control to remove the owned stock peer gun'end
    if not part_owned(proxy)then return false,'Stock peer gun identity changed during cleanup control read'end
    if not proxy_visible(record,false)then return false,'Waiting for owned stock peer gun visibility control'end
    if not part_owned(proxy)then return false,'Stock peer gun identity changed before deletion'end
    local p=buffer(record)+120;m.WriteInt(p,proxy.handle);void(H.delete,p)
    if part_owned(proxy)then return false,'Stock peer gun deletion is pending'end
   end
   record.networkProxy=nil
  end
  drain_sounds(record,0,true)
  if not record.audioReleased then audioActivator.Stop();record.audioReleased=true end
  if not record.assetSelectionReleased then
   if type(runtime.ReleaseAssets)=='function'then runtime.ReleaseAssets()end
   record.assetSelectionReleased=true
  end
  -- Consume every outstanding asynchronous result before releasing our output
  -- buffer. Cleanup is retried by the controller instead of losing the record.
  local waiting=false
  if record.shapes then
   local handles={};for handle in pairs(record.shapes)do handles[#handles+1]=handle end
   for _,handle in ipairs(handles)do if poll(record,handle)==nil then waiting=true end end
  end
  if record.mode=='native'and not record.nativeRestored then
   if carrier_owned(record)then
    local c=record.context
    -- The previous roof weapon may not exist until its mod is restored. Capture
    -- ownership first because changing our mod can select a fallback weapon.
    local restoreWeapon=record.weaponOwned and bool(H.exists,c.ped)and address(c.ped)==c.pedAddress
     and int(H.vehicle,c.ped,false)==c.vehicle
     and get_weapon(record,c.ped)==(record.weaponRestoreExpected or weapon)and record.originalWeapon~=0
    if record.modOwned and int(H.get_mod,c.vehicle,10)==record.installedMod then
     void(H.set_mod,c.vehicle,10,record.originalMod,false)
     assert(int(H.get_mod,c.vehicle,10)==record.originalMod,'Native roof restoration is pending')
    end
    if restoreWeapon then
     -- Retain only the selection observed after our own roof change. A retry
     -- may restore that selection; a later manual selection stays untouched.
     record.weaponRestoreExpected=get_weapon(record,c.ped)
     assert(bool(H.set_weapon,c.ped,record.originalWeapon),'Native vehicle weapon restoration is pending')
     record.weaponRestoreExpected=nil
    end
    if record.modKitOwned and record.originalModKit>=0 and record.originalModKit~=0 and int(H.get_modkit,c.vehicle)==0 then
     void(H.set_modkit,c.vehicle,record.originalModKit)
    end
   end
   record.nativeRestored=true
  end
  local identityDebt=false
  for index=#record.parts,1,-1 do
   local part=record.parts[index]
   if part.identityDebt then
    -- A later matching model or a recovered pointer cannot prove that this is
    -- still the entity returned by the failed acquisition. Keep explicit debt
    -- while the handle exists, including when it has been reused.
    if bool(H.exists,part.handle)then waiting=true;identityDebt=true
    else table.remove(record.parts,index)end
   elseif part_owned(part)then
    local p=buffer(record)+120;m.WriteInt(p,part.handle);void(H.delete,p)
    if part_owned(part)then waiting=true else table.remove(record.parts,index)end
   else table.remove(record.parts,index)end
  end
  if waiting then
   return false,identityDebt and'A turret component identity was not captured; same-call cleanup failed. Waiting for that handle to disappear'
    or'Finishing turret attachment cleanup'
  end
  for hash in pairs(record.modelRefs)do void(H.release,hash);record.modelRefs[hash]=nil end
  if record.weaponRequested then void(H.weapon_release,record.weapon);record.weaponRequested=nil end
  if record.buffer then
   if type(m.Check)=='function'then assert(m.Check(record.buffer)==true,'Turret native output buffer guard failed')end
   assert(m.Free(record.buffer)~=false,'Turret native output release failed');record.buffer=nil
  end
  return true
 end
 function API.Report(status,detail)
  if type(runtime.Report)=='function'then runtime.Report(status,detail)end
 end
 return API
end

local context,instances=nil,{}
function Module.New(runtime)
 local api=Module.NewController(Module.CreateNativeAdapter(runtime))
 instances[#instances+1]=api
 return api
