   if s.guard_offset==#row.bytes then s.guard_row=s.guard_row+1;s.guard_offset=0 end
  end
  base();return false
 end
 local function enter_restore(reason)
  if s.owned and s.key then s.lost_key=s.key end
  if not s.restoring then s.rev=s.rev+1;s.restoring=true;reset_guard()end
  s.active=false;s.reason=reason or s.reason;s.phase=s.owned and 'RESTORING'or(s.lost_key and 'LOST'or 'OFF')
 end
 local function restore_step()
  if not s.owned then s.restoring=false;s.key=nil;return true end
  if not guard_step(IDENTITY)then return false end
  critical(IDENTITY)
  local current=byte(FLAG)
  if current~=1 then
   s.owned=false;s.restoring=false;s.key=nil;s.phase=current==0 and 'OFF'or 'EXTERNAL_VALUE_PRESERVED';return true
  end
  local revision=s.rev
  assert(s.restoring and revision==s.rev,'Cannon restoration superseded')
  -- This fixed store is the sole restoration mutation; ownership predates it.
  host.WriteUByte(s.base+FLAG,0)
  local after=byte(FLAG)
  if after==0 then s.owned=false;s.restoring=false;s.key=nil;s.phase='OFF';return true end
  assert(after==1,'Cannon restore readback conflicted')
  return false
 end
 local function protect(callback)
  if s.busy then return false,'Cannon balance work is in flight'end
  s.busy=true;local ok,value,detail=pcall(callback);s.busy=false
  if not ok then
   s.active=false;s.reason=tostring(value)
   if s.owned then enter_restore(s.reason)else s.phase=s.lost_key and 'LOST'or 'BLOCKED'end
   return false,s.reason
  end
  return value,detail
 end
 function api.Ensure(key)
  return protect(function()
   if s.terminal or host.Cancelled()==true or type(key)~='string'or host.CurrentKey()~=key then
    enter_restore('Cannon activation context ended');return restore_step()and false or false,s.reason
   end
   if s.restoring then restore_step();return false,s.reason end
   if s.key and s.key~=key then enter_restore('Cannon actor or session changed');restore_step();return false,s.reason end
   if s.lost_key==key then s.phase='RETRY_REQUIRED';return false,'Cannon balance activation ended; toggle Pre-Nerf off and on to retry'end
   if s.key~=key then s.key=key;s.rev=s.rev+1;s.phase='PREPARING';reset_guard()end
   local revision=s.rev
   if s.owned then
    local current=byte(FLAG)
    if current~=1 then
     s.lost_key=key;s.owned=false;s.active=false;s.phase='LOST';s.reason='Game configuration changed the cannon balance byte';return false,s.reason
    end
    -- Rotate exact identity guards without a broad per-frame memory scan.
    local row=CRITICAL[(s.maintenance or 0)%#CRITICAL+1]
    local offset=0;while offset<#row.bytes do local width=math.min(8,#row.bytes-offset);compare(row,offset,width);offset=offset+width end
    s.maintenance=(s.maintenance or 0)+1
    assert(host.CurrentKey()==key and host.Cancelled()~=true and s.rev==revision and not s.restoring,'Cannon context changed during maintenance')
    s.active=true;s.phase='ACTIVE';return true
   end
   if not s.guard_complete and not guard_step()then return false,'Checking the supported cannon image'end
   critical();local original=byte(FLAG)
   if original~=0 then s.lost_key=key;s.phase='EXTERNAL_VALUE_PRESERVED';return false,'Cannon balance byte is already in use'end
   assert(host.CurrentKey()==key and host.Cancelled()~=true and s.rev==revision and not s.restoring,'Cannon context changed before activation')
   base()
   assert(byte(FLAG)==0,'Cannon baseline changed before activation')
   assert(host.CurrentKey()==key and host.Cancelled()~=true,'Cannon context changed at final activation fence')
   assert(s.rev==revision and not s.restoring and not s.terminal,'Cannon activation revoked')
   s.attempted=true;s.owned=true;s.active=false
   host.WriteUByte(s.base+FLAG,1)
   assert(byte(FLAG)==1,'Cannon balance activation readback unavailable')
   assert(s.rev==revision and not s.restoring and not s.terminal,'Cannon activation cancelled during publication')
   s.active=true;s.phase='ACTIVE';s.reason=nil;return true
  end)
 end
 function api.Restore(reason)
  enter_restore(reason)
  if s.busy then return false,'Cannon balance publication is in flight'end
  return protect(restore_step)
 end
 function api.Unload()s.terminal=true;return api.Restore('Cannon owner unloading')end
 function api.CleanupTick()
  if not s.restoring then return not s.owned or s.active end
  return protect(restore_step)
 end
 function api.NeedsCleanup()return s.owned and(s.restoring or not s.active)or s.busy and s.restoring end
 function api.HasObligations()return s.owned or s.busy end
 function api.Snapshot()
  return {phase=s.phase,active=s.active,owned=s.owned,attempted=s.attempted,cleanup_pending=api.NeedsCleanup(),
   last_error=s.reason,shared_process_scope=true,flag_rva=FLAG,supported_build='1.0.1158.16',live_verified=false}
 end
 return api
end
return Owner
end)()
function Module.NewCannonBalanceOwner(host)return CannonBalanceOwner.New(host)end

local CannonTimingBinding=(function()
-- Non-yield adapter for the persistent cannon cache service.
local Binding={}
local NORMAL='CannonTimingV3_Request.txt'
local TERMINAL='CannonTimingV3_TerminalRequest.txt'
local READS={['CannonTimingV3_Ack.txt']=true,['CannonTimingV3_TerminalAck.txt']=true,['CannonTimingV3_Status.txt']=true}
function Binding.New(e,owner_module)
 local s={unloaded=false,status='IDLE',retry_at=0};local owner,directory
 local service={}
 local function cancelled()local v=e.Cancelled();assert(type(v)=='boolean','cannon cancellation unavailable');return s.unloaded or v end
 local function snapshot()return owner and owner.Snapshot()or{phase='UNPREPARED',active=false,alive=true,ready=false,cleanup_pending=false,has_obligations=false,byte_obligations=false}end
 local function ensure_owner()
  if owner then return end
  for _,spec in ipairs({{'Memory','GetBaseAddress','ReadUByte','ReadLong','ReadUInt','WriteUByte'},{'Time','GetEpocheMs'},
    {'FileMgr','GetMenuRootPath','CreateDir','ReadFileContent','WriteFileContent'}})do
   local api=e[spec[1]];assert(api~=nil,'missing cannon '..spec[1]);for i=2,#spec do assert(type(api[spec[i]])=='function','missing cannon '..spec[i])end
  end
  assert(type(e.Context)=='function'and type(e.Cancelled)=='function','missing cannon context')
  local root=e.FileMgr.GetMenuRootPath();assert(type(root)=='string'and #root>0,'cannon menu root unavailable')
  directory=root:gsub('\\','/'):gsub('/+$','')..'/Lua/CScriptData/Diagnostics'
  e.FileMgr.CreateDir(directory) -- Existing directories may return false.
  owner=owner_module.New({
   GetBaseAddress=e.Memory.GetBaseAddress,ReadUByte=e.Memory.ReadUByte,ReadLong=e.Memory.ReadLong,ReadUInt=e.Memory.ReadUInt,
   WriteUByte=function(address,value)
    if value==0xEB then
     local current=e.Context()
     assert(current~=nil and current==s.key and not cancelled(),'cannon activation context revoked')
    end
    return e.Memory.WriteUByte(address,value)
   end,
   NowMs=e.Time.GetEpocheMs,ShouldUnload=cancelled,
   WriteFile=function(name,text)
    assert(name==NORMAL or name==TERMINAL,'nonfixed cannon output')
    assert(type(text)=='string'and #text<=4096,'cannon request bound')
    assert(e.FileMgr.WriteFileContent(directory..'/'..name,text,false)==true,'cannon request publication unconfirmed')
    return true
   end,
   ReadFile=function(name)
    assert(READS[name],'nonfixed cannon input')
    local ok,text=pcall(e.FileMgr.ReadFileContent,directory..'/'..name)
    return ok and type(text)=='string'and #text<=4096 and text or nil
   end,
  })
 end
 local function capture_error(why)
  s.error=tostring(why):gsub('[\r\n]',' '):sub(1,500);s.status='WAITING_CLEANUP'
  if owner then pcall(owner.Unload)end
  return false,s.error
 end
 local function protected(fn)
  local ok,result,detail=pcall(fn)
  if not ok then return capture_error(result)end
  return result,detail
 end
 function service.Ensure(key,restore,rapid)
  if s.unloaded then return false,'cannon owner unloaded'end
  if type(key)~='string'or #key==0 or not(restore==true or rapid==true)then return service.Restore('no timing request')end
  s.key=key
  return protected(function()
   if cancelled()then return service.Unload()end
   ensure_owner()
   local before=snapshot()
   if owner.NeedsCleanup()then owner.CleanupTick();s.status='WAITING_CLEANUP';return false end
   local now=e.Time.GetEpocheMs();assert(type(now)=='number'and now==now and now%1==0,'cannon epoch unavailable')
   if s.last_now and now<s.last_now then owner.Unload();s.status='WAITING_CLEANUP';return false,'cannon epoch rollback'end
   s.last_now=now
   if not before.alive then
    if owner.HasObligations()or now<s.retry_at then return false end
    owner=nil;ensure_owner();before=snapshot()
   end
   if not before.ready then
    if before.phase=='HELLO_PENDING'then
     owner.Tick();before=snapshot()
    elseif now>=s.retry_at then
     s.retry_at=now+1000
     local ok,why=owner.Prepare();s.error=why;s.status='WAITING_COMPANION';return false
    else return false end
    if not before.ready then s.status='WAITING_COMPANION';return false end
   end
   local ok,why=owner.Sync(key,restore==true,rapid==true)
   if not ok then s.error=why;s.status='WAITING_CLEANUP';return false,why end
   -- Advance only a pre-existing request; never consume a just-published APPLY
   -- ACK in the same transaction that wrote its candidate bytes.
   if before.phase=='APPLY_PENDING'or before.phase=='RESTORE_PENDING'then owner.Tick()end
   local current=snapshot();s.status=current.active and'ACTIVE'or'WAITING_CACHE';s.error=current.last_error
   return current.active==true,s.error
  end)
 end
 function service.Restore(reason)
  s.key=nil
  if not owner then return true end
  return protected(function()
   local ok,why
   if owner.NeedsCleanup()then ok,why=owner.CleanupTick()
   elseif not snapshot().alive then ok,why=true,nil
   else ok,why=owner.Restore(reason)end
   s.status=owner.NeedsCleanup()and'WAITING_CLEANUP'or'OFF'
   return ok==true and not owner.NeedsCleanup(),why
  end)
 end
 function service.NeedsCleanup()return owner and owner.NeedsCleanup()==true or false end
 function service.HasObligations()return owner and owner.HasObligations()==true or false end
 function service.CleanupTick()
  if not owner or not owner.NeedsCleanup()then return true end
  return protected(function()local ok,why=owner.CleanupTick();return ok==true and not owner.NeedsCleanup(),why end)
 end
 function service.Unload()
  s.unloaded=true;s.key=nil
  if not owner then s.local_teardown_complete=true;return true end
  return protected(function()
   local ok,why=owner.Unload()
   local current=snapshot()
   local local_clean=ok==true and current.busy~=true and current.active==false
    and current.alive==false and current.byte_conflict~=true
    and current.phase~='TERMINAL_DENIED'
    and not(current.terminal_flush_verified==true and current.byte_obligations==true)
   local_clean=local_clean and type(current.sites)=='table'and #current.sites==4
   if local_clean then for _,site in ipairs(current.sites)do
     if site.owned~=false or site.error~=nil then local_clean=false end
   end end
   if local_clean and owner.HasObligations()then local_clean=current.terminal_published==true end
   -- Local originals and confirmed durable publication permit VM teardown.
   -- Cache obligations remain pending until the matching companion ACK.
   s.local_teardown_complete=local_clean==true
   return s.local_teardown_complete,why or(not local_clean and'cannon local teardown pending'or nil)
  end)
 end
 function service.Snapshot()
  local out=snapshot();out.binding_status=s.status;out.binding_error=s.error;out.shared_hash_scope=true
  out.local_teardown_complete=s.local_teardown_complete==true
   and out.phase~='TERMINAL_DENIED'
   and not(out.terminal_flush_verified==true and out.byte_obligations==true)
  out.manifest="cscript-cannon-cache-owner-v3-18451EA-184572A-1845A85-186292A";out.supported_build="1.0.1158.16"
  return out
 end
 return service
end
return Binding
end)()
-- CANNON_TIMING_BINDING_END

