local function integer(x,lo,hi)
    return type(x)=='number' and x==x and x%1==0 and x>=lo and x<=hi
end
local function ptr(x) return integer(x,0x10000,0x00007FFFFFFFEFFF) and x%8==0 end
local function u32(x) return x & 0xFFFFFFFF end
local function invoke(fn,...)
    assert(type(fn)=='function','Required Cherax API unavailable')
    return fn(...)
end
local function registered(manager,wanted)
    local rows=invoke(manager and manager.GetAllFeatures)
    assert(type(rows)=='table' or type(rows)=='userdata','Feature registry unavailable')
    local found,n={},0
    for key,f in pairs(rows) do
        n=n+1;assert(n<=100000,'Feature registry inspection bound exceeded')
        local kh=integer(key,-2147483648,4294967295) and u32(key) or nil
        if type(f)=='table' or type(f)=='userdata' then
            local fh=type(f.GetHash)=='function' and f:GetHash() or kh
            if integer(fh,-2147483648,4294967295) then
                fh=u32(fh)
                assert(not (kh and wanted[kh] and fh~=kh),'Camera feature identity mismatch')
                if wanted[fh] then
                    assert(not found[fh],'Duplicate camera feature identity')
                    found[fh]=true
                end
            elseif kh and wanted[kh] then error('Unreadable camera feature identity') end
        elseif kh and wanted[kh] then error('Invalid camera feature registry entry') end
    end
    return found
end

local CANNON=0x2A00AB1A
local ATTACK={69,70,114}
-- Hunter-specific offset in heli_gun.c, commit 30dd0df8...; not a guessed bone.
local OFFSET={-0.0066,8.9038,-0.5}
local LIMITS={fov_min=10.0,fov_max=60.0,fov_start=28.0,yaw=95.0,pitch_min=-85.0,pitch_max=20.0,cone_max=90.0}
-- Only the initial 28-degree FOV comes from func_227. Other limits and the
-- sensitivity below are conservative adaptation choices, not stock parity claims.
-- The centre ray stays forward-facing across the supported FOV/aspect range.
-- The stock Hunter camera mount is preserved; mesh clearance is not guaranteed.
local function clamp(v,lo,hi) return math.max(lo,math.min(hi,v)) end
local function wrap(v) return (v+180.0)%360.0-180.0 end
local function finite(x) return type(x)=='number' and x==x and math.abs(x)<10000000 end
-- Reserved only while our own Hunter scope is active on keyboard/mouse.
-- 37 (TAB/select weapon), flight, fire, exit and look actions are NOT included.
-- Radio stays playing; its wheel/station/track controls return with Camera Off.
-- Cfx controls reference: 81-85 and 332/333 are vehicle-radio selection actions.
local WHEEL_CONFLICTS={14,15,16,17,99,100,115,116,261,262,81,82,83,84,85,332,333}
local CONTEXT_ACTIONS={51,54,80,86,119}
local CONTROL_CENSUS_MAX=360
local CONTROL_CENSUS_FRAMES=2
local NAV_RELEASE_MS=250
local NAV_FREE_FRAMES=2
local function create(R)
    local N,M,G=R.Natives,R.Memory,R.GTA
    assert(N and M and G and R.Utils,'Required Cherax services unavailable')
    local hunter=u32(invoke(R.Utils.Joaat,'hunter'))
    assert(u32(invoke(R.Utils.Joaat,'VEHICLE_WEAPON_HUNTER_CANNON'))==CANNON,'Cannon hash mismatch')
    local S={status='OFF',detail='Gun camera off',shutdown=false,blocked=false,
        cam=nil,movie=nil,buffer=nil,movie_buffer=nil,bound=nil,candidate=nil,
        ready=false,render_requested=false,render_frames=0,grant_frame=nil,
        cleanup=false,after_cleanup='OFF',last_frame=nil,last_now=nil,
        filter=nil,filter_unknown=false,create_unknown=false,movie_unknown=false,
        fov=LIMITS.fov_start,pitch=0.0,yaw=0.0,last_observe=nil,
        fov_observed=nil,zoom_steps=0,zoom_source='none',relative_yaw=0.0,relative_pitch=0.0,
        limit_hits=0,last_draw_frame=nil,draw_calls=0,skipped_game_frames=0,max_draw_gap=0,
        input_guard_frames=0,input_guard_frame=nil,context_guard_frames=0,context_guard_frame=nil,
        context_last_down={},context_prev_down={},context_last_sample=nil,context_samples=0,context_signature=nil,
        census_remaining=0,census_trigger_frame=nil,census_sequence=0,census_scans=0,
        navigation_active=false,navigation_resume_request=false,navigation_started=nil,navigation_last_down=nil,
        navigation_free_streak=0,navigation_reason=nil,bomb_bay_open=false,bomb_bay_last=nil,
        nose_heading=0.0,nose_marker_x=0.5,nose_delta=0.0,
        perf_frames=0,perf_dt_sum=0.0,perf_last_fps=0.0,perf_last_frame_ms=0.0}
    local API={}
    local function log(status,detail)
        detail=tostring(detail or ''):gsub('[\r\n]',' ')
        if S.status==status and S.detail==detail then return end
        S.status,S.detail=status,detail
        if R.Logger and type(R.Logger.LogInfo)=='function' then
            pcall(R.Logger.LogInfo,'['..ID..'] '..status..' '..detail)
        end
    end
    local function b(h,...)
        local x=invoke(N.InvokeBool,h,...);assert(type(x)=='boolean','Boolean native read unavailable');return x
    end
    local function i(h,...)
        local x=invoke(N.InvokeInt,h,...);assert(integer(x,-2147483648,4294967295),'Integer native read unavailable');return x
    end
    local function f(h,...)
        local x=invoke(N.InvokeFloat,h,...);assert(finite(x),'Float native read unavailable');return x
    end
    local function v(h,...) assert(invoke(N.InvokeVoid,h,...)~=false,'Native request rejected') end
    local function vec(h,...)
        -- Cherax documents InvokeV3 as THREE floats, not a V3 object.
        local x,y,z=invoke(N.InvokeV3,h,...)
        if type(x)=='table' or type(x)=='userdata' then x,y,z=x.x,x.y,x.z end
        assert(finite(x) and finite(y) and finite(z),'Vector native read unavailable');return x,y,z
    end
    local function alloc(key)
        if not S[key] then
            local p=invoke(M.AllocInt);assert(ptr(p),'Private output allocation failed');S[key]=p
        end
        local p=S[key]
        if type(M.Check)=='function' then assert(M.Check(p)==true,'Private buffer guard failed') end
        if type(M.SizeOf)=='function' then assert(integer(M.SizeOf(p),4,1048576),'Private buffer size invalid') end
        return p
    end
    local function write_private(p,x) assert(invoke(M.WriteInt,p,x)~=false,'Private buffer write rejected') end
    local function weapon(ped)
        local p=alloc('buffer');write_private(p,0)
        if not b(H.selected,ped,p) then return nil end
        local x=invoke(M.ReadUInt,p);assert(integer(x,0,4294967295),'Weapon output invalid');return x
    end
    local function physical(handle,method)
        local o=invoke(G.HandleToPointer,handle)
        assert(o and type(o[method])=='function' and o[method](o)==true,'Entity type unavailable')
        local p=invoke(o.GetAddress,o);assert(ptr(p),'Entity address unavailable');return p
    end
    local function context()
        local online=b(H.session)
        if online then
            local player_count=i(H.players)
            assert(integer(player_count,1,32),'Online session player count unavailable')
        end
        local pid=invoke(G.GetLocalPlayerId);assert(integer(pid,0,31),'Local player unavailable')
        local ped=i(H.ped,pid)
        assert(ped~=0 and b(H.exists,ped) and not b(H.dead,ped,false),'Local pilot absent/dead')
        local veh=i(H.vehicle,ped,false)
        assert(veh~=0 and b(H.exists,veh) and not b(H.dead,veh,false),'Hunter absent/dead')
        assert(u32(i(H.model,veh))==hunter,'FH-1 Hunter required')
        assert(i(H.seat,veh,-1,false)==ped,'Real character must remain pilot')
        assert(i(H.seat,veh,0,false)==0,'Gunner seat must remain empty')
        if b(H.networked,veh) then assert(b(H.control,veh),'Local vehicle control lost') end
        assert(b(H.player_control,pid),'Normal player control unavailable')
        return {pid=pid,ped=ped,vehicle=veh,pa=physical(ped,'IsPed'),va=physical(veh,'IsVehicle'),online=online}
    end
    local function same(a,c)
        return a and c and a.pid==c.pid and a.ped==c.ped and a.vehicle==c.vehicle
            and a.pa==c.pa and a.va==c.va
    end
    local function same_session(a,c) return same(a,c) and a.online==c.online end
    local function paused()
        if b(H.pause) then return 'Pause menu' end
        if b(H.warning) then return 'Warning screen' end
        if b(H.chat) then return 'Text chat' end
        if i(H.keyboard)==0 then return 'On-screen keyboard' end
        if b(H.cutscene) then return 'Cutscene' end
        if b(H.switching) then return 'Character switch' end
        local opened=invoke(R.GUI and R.GUI.IsOpen);assert(type(opened)=='boolean','GUI state unavailable')
        if opened then return 'Close the Cherax menu' end
        return nil
    end
    local function held()
        for _,key in ipairs(ATTACK) do if b(H.pressed,0,key) or b(H.disabled_pressed,0,key) then return true end end
        return false
    end
    local function resources()
        return S.cam~=nil or S.movie~=nil or S.filter~=nil or S.filter_unknown
            or S.create_unknown or S.movie_unknown or S.retired_cam~=nil
    end
    local function request_cleanup(reason,after)
        S.ready=false;S.grant_frame=nil;S.candidate=nil;S.render_frames=0
        S.cleanup=resources();S.after_cleanup=after or 'OFF';S.cleanup_reason=reason
        if S.cleanup then log('CAMERA_RELEASING',reason..'; only owned camera/display resources')
        else log(after or 'OFF',reason) end
    end
    local function cleanup_step(frame)
        if not S.cleanup then return true end
        -- No ped/vehicle dereference here: camera cleanup works after death/removal.
        if S.cam then
            local cam=S.cam
            if b(H.cam_exists,cam) then
                local rendering=i(H.rendered_cam)
                if rendering==cam then
                    -- Never globally stop a different script's rendering camera.
                    if not S.render_stop_submitted then
                        S.render_stop_submitted=true;v(H.render_cams,false,false,0,true,false,0)
                    end
                end
                if not S.deactivate_submitted then
                    S.deactivate_submitted=true;v(H.cam_active,cam,false)
                end
                if not S.destroy_submitted then
                    S.destroy_submitted=true;v(H.destroy_cam,cam,false)
                end
                if b(H.cam_exists,cam) then return false end
            end
            S.retired_cam=cam;S.retired_frame=frame;S.cam=nil
        end
        if S.filter~=nil then
            local current=i(H.filter_index)
            if current==S.filter then
                if not S.filter_clear_submitted then
                    S.filter_clear_submitted=true;v(H.filter_clear)
                end
                if i(H.filter_index)==S.filter then return false end
            end
            -- If replaced externally, abandon only our claim; do not clear theirs.
            S.filter=nil
        end
        if S.movie then
            assert(not S.movie_release_uncertain,'Movie release outcome unknown; not repeating a reference release')
            local p=alloc('movie_buffer');write_private(p,S.movie)
            S.movie_release_uncertain=true
            v(H.movie_release,p)
            S.movie_release_uncertain=false;S.movie=nil
        end
        assert(not S.create_unknown and not S.movie_unknown and not S.filter_unknown,
            'An allocation/filter call has unknown ownership; no false clean-state claim')
        if S.retired_cam then
            if frame==S.retired_frame then return false end
            if i(H.rendered_cam)==S.retired_cam then return false end
            S.retired_cam=nil
        end
        S.cleanup=false;S.render_requested=false;S.render_stop_submitted=false
        S.deactivate_submitted=false;S.destroy_submitted=false;S.filter_clear_submitted=false
        S.last_observe=nil;S.last_draw_frame=nil
        log('CAMERA_RELEASED','Owned camera is absent and no longer the rendering handle; movie release submitted; filter claim closed. Driver restoration is separate.')
        return true
    end
    local function method(name,params,kind)
        assert(b(H.movie_begin,S.movie,name),'Stock heli_cam method unavailable: '..name)
        -- End the method even if an argument wrapper fails, so no dangling call.
        local ok,err=pcall(function()
            for _,x in ipairs(params) do v(kind=='int' and H.param_int or H.param_float,x) end
        end)
        local end_ok,end_err=pcall(v,H.movie_end)
        assert(ok,err);assert(end_ok,end_err)
    end
    local function driver_ready(d)
        return type(d)=='table' and d.active==true and d.native_pilot_input==true
            and d.selected_verified==true and d.current_cannon_ready==true and d.selection_pending~=true
            and d.restore_pending~=true and d.blocked~=true
    end
    local function camera_space_free()
        local other=i(H.rendered_cam)
        if other~=0 and other~=-1 then
            assert(b(H.cam_exists,other),'Rendering camera handle is ambiguous')
            return false,'A different scripted camera is present; not taking it over'
        end
        if not b(H.rendering) then return false,'Game camera transition/native view; waiting before creation' end
        return true
    end
    local function dot(a,c) return a[1]*c[1]+a[2]*c[2]+a[3]*c[3] end
    local function unit(a)
        local length=math.sqrt(dot(a,a))
        assert(finite(length) and length>0.000001,'Degenerate view direction')
        return {a[1]/length,a[2]/length,a[3]/length}
    end
    local function hull_basis(c)
        -- Read the vehicle's actual axes: no guessed Euler order, bone, offset or memory.
        local x,y,z=vec(H.coords,c.vehicle,false)
        local function axis(ox,oy,oz)
            local ax,ay,az=vec(H.offset_world,c.vehicle,ox,oy,oz)
            local a={ax-x,ay-y,az-z};local length=math.sqrt(dot(a,a))
            assert(length>0.98 and length<1.02,'Hunter camera basis scale changed')
            return unit(a)
        end
        local right,forward,up=axis(1.0,0.0,0.0),axis(0.0,1.0,0.0),axis(0.0,0.0,1.0)
        assert(math.abs(dot(right,forward))<0.002 and math.abs(dot(right,up))<0.002
            and math.abs(dot(forward,up))<0.002,'Hunter camera basis is not orthogonal')
        return right,forward,up,z
    end
    local function constrain_view(c,pitch,yaw)
        local aspect=f(H.aspect,false)
        assert(aspect>=0.5 and aspect<=4.0,'Unsupported camera aspect ratio')
        local right,forward,up,alt=hull_basis(c)
        local p,y=math.rad(pitch),math.rad(yaw)
        local direction={-math.sin(y)*math.cos(p),math.cos(y)*math.cos(p),math.sin(p)}
        local lx,ly,lz=dot(direction,right),dot(direction,forward),dot(direction,up)
        local local_yaw=math.deg(math.atan(-lx,ly))
        local local_pitch=math.deg(math.asin(clamp(lz,-1.0,1.0)))
        local yp=math.rad(clamp(local_yaw,-LIMITS.yaw,LIMITS.yaw))
        local pp=math.rad(clamp(local_pitch,LIMITS.pitch_min,LIMITS.pitch_max))
        lx,ly,lz=-math.sin(yp)*math.cos(pp),math.cos(yp)*math.cos(pp),math.sin(pp)
        -- Include the entire rectangular FOV, not just its centre. If FOV application
        -- lags, use the wider of request/readback. All rays stay in the forward
        -- hemisphere with a five-degree margin; this is NOT a mesh collision test.
        local fov=math.max(S.fov,S.fov_observed or S.fov)
        local half_diagonal=math.deg(math.atan(math.tan(math.rad(fov*0.5))*math.sqrt(1.0+aspect*aspect)))
        local cone=math.max(1.0,LIMITS.cone_max-half_diagonal)
        local minimum_forward=math.cos(math.rad(cone))
        if ly<minimum_forward then
            local lateral=math.sqrt(lx*lx+lz*lz)
            assert(lateral>0.000001,'Invalid camera-sector projection')
            local scale=math.sin(math.rad(cone))/lateral
            lx,ly,lz=lx*scale,minimum_forward,lz*scale
        end
        S.relative_yaw=math.deg(math.atan(-lx,ly))
        S.relative_pitch=math.deg(math.asin(clamp(lz,-1.0,1.0)))
        S.clearance_cone=cone;S.forward_dot=ly;S.aspect=aspect
        local out=unit({right[1]*lx+forward[1]*ly+up[1]*lz,
            right[2]*lx+forward[2]*ly+up[2]*lz,right[3]*lx+forward[3]*ly+up[3]*lz})
        local changed=dot(out,direction)<0.999999
        if changed then S.limit_hits=S.limit_hits+1 end
        local result_pitch=math.deg(math.asin(clamp(out[3],-1.0,1.0)))
        local result_yaw=wrap(math.deg(math.atan(-out[1],out[2])))
        -- Preserve input bit-for-bit inside the allowed sector (avoid idle drift).
        if not changed then return pitch,wrap(yaw),alt end
        return result_pitch,result_yaw,alt
    end
    local function edge(action)
        return b(H.just_pressed,0,action) or b(H.disabled_just,0,action)
    end
    local function isolate_wheel(mouse,frame)
        if not mouse then return end
        -- Preempt competing consumers even between wheel pulses. Disabled-edge
        -- reads below still observe zoom. Never set a weapon/radio selection here.
        for _,action in ipairs(WHEEL_CONFLICTS) do
            v(H.disable_control,0,action,true)
        end
        if S.input_guard_frame~=frame then
            S.input_guard_frames=S.input_guard_frames+1;S.input_guard_frame=frame
        end
    end
    -- E maps to several contextual controls. Observe Hunter's 51/54/80/86
    -- controls without blocking them; keep 119 and flight/fire/exit available.
    -- A two-frame census records active controls around the rising E edge.
    local function control_census(frame,now)
        local active,unavailable={},0
        for action=0,CONTROL_CENSUS_MAX do
            local ok,p=pcall(b,H.pressed,0,action)
            local dok,dp=pcall(b,H.disabled_pressed,0,action)
            if not ok and not dok then unavailable=unavailable+1
            elseif (ok and p==true) or (dok and dp==true) then active[#active+1]=tostring(action) end
        end
        S.census_sequence=S.census_sequence+1;S.census_scans=S.census_scans+1
        if R.Logger and type(R.Logger.LogInfo)=='function' then
            pcall(R.Logger.LogInfo,('['..ID..'] GUN_CONTROL_CENSUS seq=%d frame=%d triggerFrame=%s ageMs=%d active=[%s] unavailable=%d; read-only controls 0-%d')
                :format(S.census_sequence,frame,tostring(S.census_trigger_frame),
                    S.census_trigger_at and math.max(0,now-S.census_trigger_at) or 0,
                    table.concat(active,','),unavailable,CONTROL_CENSUS_MAX))
        end
    end
    local function observe_context(frame,now)
        local values,trigger,any_down={},false,false
        local mouse=b(H.mouse,0)
        for _,action in ipairs(CONTEXT_ACTIONS) do
            -- Read normal input first; E remains available to GTA's Hunter systems.
            local ok,p=pcall(b,H.pressed,0,action)
            local down=ok and p==true
            local disabled_ok=true
            if not down and action~=119 then
                local dok,dp=pcall(b,H.disabled_pressed,0,action)
                disabled_ok=dok
                down=dok and dp==true
            end
            values[#values+1]=tostring(action)..'='..((ok and disabled_ok) and tostring(down) or 'UNAVAILABLE')
            if down then
                any_down=true;S.context_last_down[action]=now
            end
            if mouse and down and not S.context_prev_down[action] and action~=119 then trigger=true end
            S.context_prev_down[action]=down
        end
        S.context_last_sample=table.concat(values,',');S.context_samples=S.context_samples+1
        if trigger then
            S.census_remaining=CONTROL_CENSUS_FRAMES;S.census_trigger_frame=frame;S.census_trigger_at=now
        end
        if S.census_remaining>0 then
            control_census(frame,now);S.census_remaining=S.census_remaining-1
        end
        if S.context_last_sample~=S.context_signature then
            S.context_signature=S.context_last_sample
            if not S.context_last_log or now-S.context_last_log>=250 then
                S.context_last_log=now
                if R.Logger and type(R.Logger.LogInfo)=='function' then
                    pcall(R.Logger.LogInfo,'['..ID..'] GUN_CONTEXT_INPUT frame='..frame..' '..S.context_last_sample
                        ..'; observations only; E-linked controls are NOT disabled by this camera')
                end
            end
        end
        return trigger,any_down
    end
    local function bomb_bay(c)
        local open=b(H.bomb_bay,c.vehicle)
        if S.bomb_bay_last==nil or open~=S.bomb_bay_last then
            S.bomb_bay_last=open;S.bomb_bay_open=open
            log(open and 'BOMB_BAY_OPEN' or 'BOMB_BAY_CLOSED',
                open and 'Hunter bomb bay is open; owned cannon scope stays yielded until it closes'
                    or 'Hunter bomb bay is closed; navigation return may settle after normal debounce')
        else S.bomb_bay_open=open end
        return open
    end
    local function draw_nose_indicator(c)
        local hdg=f(H.heading,c.vehicle)%360.0
        local delta=clamp(-S.relative_yaw,-LIMITS.yaw,LIMITS.yaw)
        local marker=clamp(0.5+(delta/LIMITS.yaw)*0.17,0.325,0.675)
        S.nose_heading=hdg;S.nose_delta=delta;S.nose_marker_x=marker
        v(H.draw_rect,marker,0.111,0.0032,0.017,255,255,255,220,false)
        v(H.draw_rect,marker,0.1025,0.020,0.0022,255,255,255,190,false)
        local rounded=math.floor(hdg+0.5)%360
        local label
        if delta<=-LIMITS.yaw*0.94 then label=('< NOSE %03d'):format(rounded)
        elseif delta>=LIMITS.yaw*0.94 then label=('NOSE %03d >'):format(rounded)
        else label=('NOSE %03d'):format(rounded) end
        v(H.text_font,0);v(H.text_scale,0.0,0.27);v(H.text_colour,255,255,255,225)
        v(H.text_centre,true);v(H.text_outline);v(H.text_begin,'STRING');v(H.text_add,label)
        v(H.text_end,marker,0.118,0)
    end
    local function begin_navigation(frame,now,reason)
        if S.navigation_active then return end
        S.navigation_active=true;S.navigation_resume_request=false
        S.navigation_started=now;S.navigation_last_down=now;S.navigation_free_streak=0
        S.navigation_reason=tostring(reason or 'Hunter E navigation')
        request_cleanup('Yielding scope to normal Hunter navigation/bomb-bay controls','NAVIGATION_HANDOFF')
        if S.cleanup then cleanup_step(frame) end
        log('NAVIGATION_HANDOFF',S.navigation_reason..'; stock Hunter controls have priority; scope returns only after input/view/bomb-bay state settles')
    end
    local function navigation_step(wanted,driver,frame,now)
        if wanted~=true then
            S.navigation_active=false;S.navigation_resume_request=false;S.navigation_free_streak=0
            log('OFF','Gun camera navigation cancelled; weapon state unchanged')
            return true
        end
        local c=context()
        assert(S.bound and same_session(S.bound,c),'Original pilot/Hunter/session identity changed during navigation')
        local _,any_down=observe_context(frame,now)
        if bomb_bay(c) then
            S.navigation_last_down=now;S.navigation_free_streak=0
            log('NAVIGATION_WAIT_BOMB_BAY','Bomb bay doors remain open; cannon scope stays yielded and no return is requested')
            return false
        end
        if any_down then
            S.navigation_last_down=now;S.navigation_free_streak=0
            log('NAVIGATION_HANDOFF','Hunter E controls active; stock game behavior has priority')
            return false
        end
        local last=S.navigation_last_down or S.navigation_started or now
        if now-last<NAV_RELEASE_MS then
            S.navigation_free_streak=0
            log('NAVIGATION_WAIT_INPUT','Waiting for E-linked input release before returning to cannon')
            return false
        end
        local free,reason=camera_space_free()
        if not free then
            S.navigation_free_streak=0
            log('NAVIGATION_WAIT_STOCK_VIEW',reason)
            return false
        end
        S.navigation_free_streak=S.navigation_free_streak+1
        if S.navigation_free_streak<NAV_FREE_FRAMES then
            log('NAVIGATION_WAIT_STOCK_VIEW','Stock view cleared once; waiting for a second distinct game frame')
            return false
        end
        if not S.navigation_resume_request then
            S.navigation_resume_request=true
            log('NAVIGATION_RETURN_PENDING','Stock view/input settled; requesting bounded pilot-cannon rearm without a part reset')
        end
        if type(driver)=='table' and driver.navigation_active~=true then
            S.navigation_active=false;S.navigation_resume_request=false;S.navigation_free_streak=0
            S.candidate=nil;S.ready=false;S.grant_frame=nil
            if driver.current_cannon_ready==true then
                log('NAVIGATION_RETURN_READY','Pilot cannon is ready again; scope will reopen automatically')
            else
                log('NAVIGATION_WEAPON_PRESERVED','Native weapon choice preserved; scope remains down until cannon is naturally selected/ready again')
            end
            return true
        end
        return false
    end
    local function lost_weapon_detail(current,disabled,now)
        local ages={}
        for _,action in ipairs(CONTEXT_ACTIONS) do
            local at=S.context_last_down[action]
            ages[#ages+1]=tostring(action)..'AgeMs='..(at and tostring(now-at) or 'not-observed')
        end
        log('GUN_CAMERA_WEAPON_LOST',('selected=%s cannonDisabled=%s %s lastInput=[%s]; legacyContextGuardFrames=%d censusScans=%d; arbitrary loss cause unproven; navigation rearm is only permitted after an explicit E handoff')
            :format(current and ('0x%08X'):format(current) or 'UNAVAILABLE',tostring(disabled),
                table.concat(ages,','),tostring(S.context_last_sample),S.context_guard_frames,S.census_scans))
    end
    local function zoom_input(mouse)
        local zin,zout,source=false,false,'none'
        if mouse then
            -- Resolve one pulse, never sum its aliases. Cursor scroll has priority;
            -- generic wheel actions cover contexts where cursor actions are absent.
            local up,down=edge(241),edge(242)
            if up or down then zin,zout,source=up,down,'cursor-wheel'
            else
                up,down=edge(15) or edge(17) or edge(261),edge(14) or edge(16) or edge(262)
                if up or down then zin,zout,source=up,down,'wheel-actions'
                else zin,zout,source=edge(40),edge(41),'sniper-keys' end
            end
        else
            -- Secondary sniper zoom is D-pad based. Do NOT use primary left-stick
            -- zoom on a flying gamepad: that stick is still needed to fly.
            zin,zout,source=edge(42),edge(43),'pad-secondary-zoom'
        end
        S.zoom_source=(zin or zout) and source or 'none'
        if zin==zout then return 0 end
        return zin and -3.0 or 3.0
    end
    local function build(c,now,frame)
        local free,reason=camera_space_free();assert(free,reason)
        assert(same_session(c,context()) and weapon(c.ped)==CANNON
            and not b(H.disabled,CANNON,c.vehicle,c.ped),'Pilot/cannon changed before camera creation')
        local p,_,yaw=vec(H.game_rot,2)
        S.fov=LIMITS.fov_start;S.fov_observed=nil
        -- Input history belongs to this camera session, not a previous vehicle/view.
        S.context_last_down={};S.context_prev_down={};S.context_last_sample=nil;S.context_signature=nil
        S.context_last_log=nil;S.context_samples=0;S.census_remaining=0;S.census_trigger_frame=nil;S.census_trigger_at=nil;S.census_scans=0
        S.navigation_resume_request=false;S.navigation_free_streak=0
        S.perf_frames=0;S.perf_dt_sum=0.0;S.perf_last_fps=0.0;S.perf_last_frame_ms=0.0
        S.pitch,S.yaw=constrain_view(c,p,yaw)
        S.last_draw_frame=nil
        S.create_unknown=true
        local cam=i(H.create_cam,'DEFAULT_SCRIPTED_CAMERA',false)
        S.create_unknown=false;assert(cam>0,'Camera allocation failed');S.cam=cam
        assert(b(H.cam_exists,cam),'Created camera was not found')
        v(H.attach_cam,cam,c.vehicle,OFFSET[1],OFFSET[2],OFFSET[3],true)
        v(H.near_clip,cam,0.1)
        v(H.cam_rot,cam,S.pitch,0.0,S.yaw,2)
        v(H.cam_fov,cam,S.fov)
        v(H.affects_aim,cam,true) -- aim integration, never a firing command
        method('SET_CAM_LOGO',{0},'int')
        local filter=i(H.filter_index)
        if filter==-1 then
            S.filter_unknown=true
            v(H.filter_set,'heliGunCam')
            local after=i(H.filter_index)
            if after>=0 then S.filter=after end
            S.filter_unknown=false
            if after<0 then log('FILTER_NOT_OBSERVED','Gun camera proceeds without a confirmed heliGunCam filter') end
        else
            log('FILTER_PRESERVED','Existing timecycle effect left unchanged; exact scope tint may differ')
        end
        -- Do not steal a camera that appeared during creation/asset setup.
        free,reason=camera_space_free();assert(free,reason)
        v(H.cam_active,cam,true)
        isolate_wheel(b(H.mouse,0),frame) -- cover the first submitted-view frame too
        S.render_requested=true;S.render_since=now;S.render_frame=frame
        v(H.render_cams,true,false,0,true,false,0)
        log('GUN_CAMERA_SUBMITTED','Hunter camera + stock heli_cam submitted; awaiting own renderer. Release fire before shooting; visual alignment/flight remain unverified.')
    end
    local function update_view(c,frame,now)
        local raw_dt=f(H.dt)
        local dt=clamp(raw_dt,0.0,0.05)
        local dx=clamp(f(H.normal,0,1),-1.0,1.0)
        local dy=clamp(f(H.normal,0,2),-1.0,1.0)
        local mouse=b(H.mouse,0)
        isolate_wheel(mouse,frame)
        if raw_dt>0.0 and raw_dt<1.0 then S.perf_frames=S.perf_frames+1;S.perf_dt_sum=S.perf_dt_sum+raw_dt end
        local gain=(mouse and 6.0 or (100.0*dt))*(S.fov/60.0)
        local before=S.fov
        S.fov=clamp(S.fov+zoom_input(mouse),LIMITS.fov_min,LIMITS.fov_max)
        v(H.cam_fov,S.cam,S.fov)
        S.fov_observed=f(H.fov_read,S.cam)
        assert(S.fov_observed>=1.0 and S.fov_observed<=120.0,'Invalid camera FOV readback')
        local alt
        S.pitch,S.yaw,alt=constrain_view(c,clamp(S.pitch-dy*gain,-89.9,89.9),wrap(S.yaw-dx*gain))
        v(H.cam_rot,S.cam,S.pitch,0.0,S.yaw,2)
        local yawbar=(S.relative_yaw+LIMITS.yaw)/(2*LIMITS.yaw)
        method('SET_ALT_FOV_HEADING',{alt,clamp(yawbar,0.0,1.0),S.yaw%360.0},'float')
        draw_nose_indicator(c)
        -- One submission on every distinct native-loop game frame, no sleeps here
        -- or at the host callback tail. Never run game natives in ON_PRESENT.
        v(H.movie_draw,S.movie,255,255,255,255,0)
        v(H.hide_reticle,14)
        if S.last_draw_frame then
            local gap=(frame-S.last_draw_frame)&0xFFFFFFFF
            if gap>0 and gap<0x80000000 then
                S.skipped_game_frames=S.skipped_game_frames+math.max(0,gap-1)
                S.max_draw_gap=math.max(S.max_draw_gap,gap)
            end
        end
        S.last_draw_frame=frame;S.draw_calls=S.draw_calls+1
        if S.fov~=before then
            S.zoom_steps=S.zoom_steps+1
            if not S.last_zoom_log or now-S.last_zoom_log>=200 then
                S.last_zoom_log=now
                log('GUN_CAMERA_ZOOM',('source=%s requested=%.1f observed=%.1f steps=%d; no weapon selection command')
                    :format(S.zoom_source,S.fov,S.fov_observed,S.zoom_steps))
            end
        end
    end
    function API.Tick(wanted,driver)
        if S.shutdown then return end
        if wanted~=true and not resources() and not S.cleanup then
            S.blocked=false;S.bound=nil;S.candidate=nil;S.ready=false;S.grant_frame=nil
            S.last_now=nil -- OFF idle is not an active-camera frame discontinuity
            if S.status~='CAMERA_RELEASED' then log('OFF','Gun camera off; weapon state unchanged') end
            return
        end
        local ok,err=pcall(function()
            local frame,now=i(H.frame),i(H.time)
            if wanted~=true then
                S.blocked=false;S.bound=nil
                if not S.cleanup then request_cleanup('Camera toggle off','OFF') end
            end
            if frame==S.last_frame then return end
            if S.last_now and (now<S.last_now or now-S.last_now>750) then
                S.blocked=true;request_cleanup('Clock discontinuity; camera disarmed','BLOCKED')
            end
            S.last_frame,S.last_now=frame,now;S.grant_frame=nil
            if S.cleanup then
                if not cleanup_step(frame) then log('CAMERA_RESTORE_PENDING','Owned resource release has not completed; keep loaded');end
                return
            end
            if S.navigation_active then
                navigation_step(wanted,driver,frame,now)
                return
            end
            if wanted~=true or S.blocked then return end
            if not driver_ready(driver) then
                if resources() then S.blocked=true;request_cleanup('Weapon runtime not ready/stopping','BLOCKED');cleanup_step(frame)
                else log('WAITING_FOR_CANNON','Enable the Driver Weapons test first and wait for SELECTION_READY') end
                return
            end
            local c=context()
            assert(not S.bound or same_session(S.bound,c),'Original pilot/Hunter/session identity changed')
            local current_weapon=weapon(c.ped)
            local cannon_disabled=b(H.disabled,CANNON,c.vehicle,c.ped)
            local bay_open=bomb_bay(c)
            if S.cam then
                local nav_trigger=observe_context(frame,now)
                if nav_trigger or bay_open then
                    begin_navigation(frame,now,bay_open and 'Bomb bay opened' or 'Hunter E navigation')
                    return
                end
            elseif bay_open then
                begin_navigation(frame,now,'Bomb bay already open')
                return
            end
            if current_weapon~=CANNON then
                if S.cam then
                    request_cleanup('Native Hunter weapon changed; yielding scope until cannon naturally returns','WEAPON_NAVIGATION')
                    cleanup_step(frame)
                else
                    log('WAITING_FOR_CANNON','Native Hunter weapon selected; scope will reopen automatically when cannon is naturally selected/ready')
                end
                return
            end
            if cannon_disabled then
                if S.cam then lost_weapon_detail(current_weapon,cannon_disabled,now) end
                S.blocked=true;request_cleanup('Cannon remained selected but became disabled','BLOCKED');cleanup_step(frame);return
            end
            local why=paused()
            if why then request_cleanup(why,'SUSPENDED');cleanup_step(frame);return end
            if not S.cam then
                if held() then S.candidate=nil;log('RELEASE_FIRE','Release fire before opening the gun camera');return end
                local free,reason=camera_space_free()
                if not free then
                    if resources() then request_cleanup(reason,'SUSPENDED');cleanup_step(frame)
                    else S.candidate=nil;log('CAMERA_WAIT',reason) end
                    return
                end
                if not S.candidate or not same_session(S.candidate,c) then
                    c.frame=frame;S.candidate=c;log('CAMERA_VERIFYING','Awaiting a second distinct pilot/cannon frame');return
                end
                if frame==S.candidate.frame then return end
                if not S.movie then
                    S.bound=c;S.assets_since=now;S.movie_unknown=true
                    local movie=i(H.movie_request,'heli_cam');S.movie_unknown=false
                    assert(movie>0,'Stock heli_cam instance allocation failed');S.movie=movie
                    log('GUN_DISPLAY_LOADING','Requested an owned instance of the stock heli_cam display')
                end
                assert(now-S.assets_since<=2000,'Stock heli_cam asset timeout')
                if not b(H.movie_loaded,S.movie) then return end
                build(c,now,frame);return
            end
            assert(b(H.cam_exists,S.cam),'Owned camera disappeared')
            local rendered=i(H.rendered_cam)
            if rendered~=S.cam then
                if rendered~=0 and rendered~=-1 then error('Different scripted camera took rendering; not reclaiming it') end
                if S.ready then error('Owned camera stopped rendering') end
                assert(now-S.render_since<=500,'Own-camera render transition timed out')
                S.render_frames=0;log('GUN_CAMERA_TRANSITION','Waiting for our rendering handle; not blaming another script');return
            end
            if not b(H.cam_rendering,S.cam) then
                S.render_frames=0;assert(not S.ready and now-S.render_since<=500,'Owned renderer not confirmed');return
            end
            assert(b(H.movie_loaded,S.movie),'Owned stock display became unavailable')
            update_view(c,frame,now)
            if frame~=S.render_frame then S.render_frames=S.render_frames+1 end
            if S.render_frames>=2 and not S.ready then
                S.ready=true
                log('GUN_CAMERA_RENDERING','Own camera rendered on two later frames with stock heli_cam loaded. Release fire; view/zoom/reticle-to-shot alignment and manual flight need live confirmation.')
            end
            if S.ready then
                S.grant_frame=frame
                if not S.last_observe or now-S.last_observe>=2000 then
                    S.last_observe=now
                    if S.perf_frames>0 and S.perf_dt_sum>0 then
                        S.perf_last_fps=S.perf_frames/S.perf_dt_sum
                        S.perf_last_frame_ms=(S.perf_dt_sum/S.perf_frames)*1000.0
                    end
                    log('GUN_CAMERA_OBSERVATION',('frame=%d realSeat=DRIVER camera=%d fov=%.1f fovObserved=%.1f pitch=%.1f yaw=%.1f relativeYaw=%.1f relativePitch=%.1f zoomSteps=%d drawCalls=%d skippedGameFrames=%d maxDrawGap=%d limitHits=%d inputGuardFrames=%d avgFps=%.1f avgFrameMs=%.2f; draw submissions only; shotAlignment=UNVERIFIED flight=UNVERIFIED')
                        :format(frame,S.cam,S.fov,S.fov_observed,S.pitch,S.yaw,S.relative_yaw,S.relative_pitch,S.zoom_steps,S.draw_calls,S.skipped_game_frames,S.max_draw_gap,S.limit_hits,S.input_guard_frames,S.perf_last_fps,S.perf_last_frame_ms))
                    S.perf_frames=0;S.perf_dt_sum=0.0
                end
            end
        end)
        if not ok then
            S.blocked=true;request_cleanup(tostring(err),'BLOCKED')
            local frame_ok,frame=pcall(i,H.frame)
            if frame_ok and S.cleanup then
                local clean_ok,clean_err=pcall(cleanup_step,frame)
                if not clean_ok then log('CAMERA_RESTORE_PENDING',tostring(clean_err));return end
            end
            log('CAMERA_BLOCKED',tostring(err)..'; camera off before retry; working cannon activation not changed')
        end
    end
    function API.AllowsNativeFire(c)
        -- Private in-process capability; never read from a writable menu feature,
        -- another script, a claimed camera type, or the mere existence of a camera.
        if S.shutdown or S.blocked or S.cleanup or not S.ready or not S.cam
            or not same(S.bound,c) then return false end
        local ok,allowed=pcall(function()
            return S.grant_frame==i(H.frame) and same_session(S.bound,context())
                and paused()==nil and b(H.cam_exists,S.cam)
                and i(H.rendered_cam)==S.cam and b(H.cam_rendering,S.cam)
                and weapon(c.ped)==CANNON and not b(H.disabled,CANNON,c.vehicle,c.ped)
        end)
        return ok and allowed==true
    end
    function API.Cancel(reason)
        if S.shutdown then return end
        S.navigation_active=false;S.navigation_resume_request=false;S.navigation_free_streak=0
        S.blocked=true;request_cleanup(tostring(reason or 'Camera cancelled'),'BLOCKED')
        -- Event/UI callback: no native execution. Loop finishes cleanup.
    end
    function API.Unload()
        if S.shutdown then return end
        S.ready=false;S.grant_frame=nil;S.blocked=true;S.shutdown=true
        if resources() or S.cleanup then
            log('CAMERA_UNLOAD_UNRESOLVED','Host unload interrupted owned camera/display cleanup. No gameplay natives in teardown; no clean-state claim.')
        else log('CAMERA_UNLOADED','Owned camera/display already released; weapon cleanup remains separate') end
        for _,key in ipairs({'buffer','movie_buffer'}) do
            if S[key] then
                local ok,r=pcall(invoke,M.Free,S[key]);if ok and r~=false then S[key]=nil end
            end
        end
    end
    function API.Snapshot()
        return {status=S.status,detail=S.detail,ready=S.ready,blocked=S.blocked,
            cam=S.cam,movie=S.movie,cleanup_pending=S.cleanup,shutdown=S.shutdown,
            fov=S.fov,pitch=S.pitch,yaw=S.yaw,grant_frame=S.grant_frame,
            fov_observed=S.fov_observed,zoom_steps=S.zoom_steps,zoom_source=S.zoom_source,
            input_guard_frames=S.input_guard_frames,input_guard_frame=S.input_guard_frame,
            context_guard_frames=S.context_guard_frames,context_guard_frame=S.context_guard_frame,
            context_samples=S.context_samples,context_last_sample=S.context_last_sample,
            census_scans=S.census_scans,census_remaining=S.census_remaining,census_trigger_frame=S.census_trigger_frame,
            navigation_active=S.navigation_active,navigation_resume_request=S.navigation_resume_request,
            navigation_started=S.navigation_started,navigation_last_down=S.navigation_last_down,
            bomb_bay_open=S.bomb_bay_open,nose_heading=S.nose_heading,nose_marker_x=S.nose_marker_x,nose_delta=S.nose_delta,
            perf_last_fps=S.perf_last_fps,perf_last_frame_ms=S.perf_last_frame_ms,
            relative_yaw=S.relative_yaw,relative_pitch=S.relative_pitch,
            clearance_cone=S.clearance_cone,forward_dot=S.forward_dot,aspect=S.aspect,
            draw_calls=S.draw_calls,skipped_game_frames=S.skipped_game_frames,max_draw_gap=S.max_draw_gap,limit_hits=S.limit_hits,
            scope_visual_verified=false,shot_alignment_verified=false,weapon_commands=0,seat_moves=0}
    end
    return API
end
return {Create=create,Hashes=H,Registered=registered,Limits=LIMITS,Offset=OFFSET}

end)()

