    end
    local function read(suffix,addr)
        assert(integer(addr,0x10000,0x00007FFFFFFFEFFF),'Invalid memory address')
        local x=call(M['Read'..suffix],addr)
        if suffix=='Float' then assert(finite(x),'Invalid memory float')
        else assert(integer(x,-9223372036854775807,9223372036854775807),'Invalid memory integer') end
        return x
    end
    local function hash(name) return u32(call(U.Joaat,name)) end
    local PROFILES={
        [hash('chernobog')]={name='Chernobog',model=hash('chernobog'),mass=40000.0,
            hashes={0,0,0,0,hash('VEHICLE_WEAPON_CHERNO_MISSILE'),0},seats={0,0,0,0,1,0},
            slot=4,remap_slots={4},weapon=hash('VEHICLE_WEAPON_CHERNO_MISSILE'),interval=4000,turret_speed=5.0},
        [hash('hunter')]={name='FH-1 Hunter',model=hash('hunter'),mass=6000.0,
            hashes={hash('VEHICLE_WEAPON_HUNTER_MG'),hash('VEHICLE_WEAPON_HUNTER_MISSILE'),
                hash('VEHICLE_WEAPON_HUNTER_CANNON'),0,hash('VEHICLE_WEAPON_HUNTER_BARRAGE'),0},
            seats={1,0,1,0,0,0},slot=2,remap_slots={0,2},weapon=hash('VEHICLE_WEAPON_HUNTER_CANNON'),
            interval=334,turret_speed=15.0,requires_cannon=true,
            automatic_mapping=true,native_pilot_input=true},
    }
    local function image()
        local base=call(M.GetBaseAddress,GAME);assert(pointer(base),'Enhanced executable not found')
        -- Header identification stays within the first page. Compare every typed
        -- field to its little-endian bytes; a bad reader is not a new image profile.
        local function unsigned_field(offset,width)
            assert(integer(offset,0,4096-width),'Header field outside first page')
            local suffix=width==2 and 'UShort' or 'UInt'
            local typed=read(suffix,base+offset)
            assert(integer(typed,0,2^(width*8)-1),'Unsigned header read out of range')
            local bytes=0
            for j=0,width-1 do
                local byte=read('UByte',base+offset+j)
                assert(integer(byte,0,255),'Unsigned header byte out of range')
                bytes=bytes+byte*2^(8*j)
            end
            assert(typed==bytes,'Executable header typed/byte readback mismatch')
            return typed
        end
        assert(unsigned_field(0,2)==0x5A4D,'Bad DOS header')
        local pe=unsigned_field(0x3C,4)
        assert(integer(pe,64,1024),'Bad PE header offset')
        assert(unsigned_field(pe,4)==0x4550 and unsigned_field(pe+4,2)==0x8664,
            'Not expected x64 PE')
        local optional=unsigned_field(pe+20,2)
        assert(integer(optional,112,512) and pe+24+optional<=4096,'Bad optional header size')
        assert(unsigned_field(pe+24,2)==0x20B,'Not expected x64 PE')
        local timestamp=unsigned_field(pe+8,4)
        local size=unsigned_field(pe+80,4)
        local profile
        for _,candidate in ipairs(IMAGE_PROFILES) do
            if timestamp==candidate.timestamp and size==candidate.size then profile=candidate;break end
        end
        assert(profile,('Unsupported Enhanced image: TimeDateStamp=%d SizeOfImage=%d; no seat writes made')
            :format(timestamp,size))
        assert(call(M.GetBaseAddress,GAME)==base,'Executable base changed during header read')
        return {base=base,size=size,timestamp=timestamp,pe=pe,optional=optional,
            tag=profile.tag,requires_mapping=profile.requires_mapping}
    end
    local function same_image(a,b)
        return a and b and a.base==b.base and a.size==b.size and a.timestamp==b.timestamp
            and a.pe==b.pe and a.optional==b.optional and a.tag==b.tag
    end
    local function image_pointer(a,img)
        return pointer(a) and a>=img.base and a<img.base+img.size
    end
    local function physical(h,kind)
        assert(b(H.exists,h),'Entity disappeared')
        local obj=call(G.HandleToPointer,h);assert(obj~=nil,'No physical entity')
        local a=call(obj.GetAddress,obj);assert(pointer(a),'Invalid physical address')
        assert(call(G.PointerToHandle,obj)==h,'Entity handle round trip failed')
        assert(call(obj[kind],obj)==true,'Entity type mismatch')
        return a,obj
    end
    local function check_rapid_fire()
        local now=S.last_now or 0
        if S.rapid_checked and S.rapid_checked_at and now>=S.rapid_checked_at
            and now-S.rapid_checked_at<RAPID_FIRE_RECHECK_MS then return end
        stage('dependency-registry: enumerate existing features')
        local h=hash('JinxRebound_vehicle_rapid_fire')
        local feature=registered_features(R.FeatureMgr,{[h]=true})[h]
        local state='ABSENT'
        if feature then
            assert(type(feature.GetName)=='function' and feature:GetName()=='Vehicle Rapid Fire',
                'Rapid Fire registry name does not match; no state query')
            assert(type(feature.IsToggleFeature)=='function' and feature:IsToggleFeature()==true,
                'Rapid Fire registry entry is not a toggle; no state query')
            assert(type(feature.IsToggled)=='function','Rapid Fire state reader unavailable')
            local enabled=feature:IsToggled()
            assert(type(enabled)=='boolean','Rapid Fire state is unreadable')
            state=enabled and 'ON' or 'OFF'
        end
        if S.rapid_state~=state then
            S.rapid_state=state
            log('DEPENDENCY','CScript Vehicle Rapid Fire='..state..'; enumerated registry only')
        end
        assert(state~='ON','Disable CScript Vehicle Rapid Fire for this isolated firing test')
        S.rapid_checked=true;S.rapid_checked_at=now
    end
    local function session_ok()
        if b(H.session) then
            local player_count=i(H.players)
            assert(integer(player_count,1,32),'Online session player count unavailable')
        end
    end
    local function context()
        stage('session: check local test context')
        session_ok()
        check_rapid_fire()
        stage('driver-context: player and vehicle identity')
        local pid=call(G.GetLocalPlayerId);assert(integer(pid,0,31),'No local player')
        local ped=i(H.ped,pid);assert(ped>0 and not b(H.dead,ped,false),'Local ped unavailable')
        local pa=physical(ped,'IsPed')
        local vehicle=i(H.vehicle,ped,false);assert(vehicle>0,'Enter the Chernobog or Hunter as driver')
        local va=physical(vehicle,'IsVehicle')
        assert(i(H.seat,vehicle,-1,false)==ped,'Local player must stay in driver seat')
        assert(i(H.seat,vehicle,0,false)==0,'Passenger/gunner seat is occupied')
        assert(not b(H.dead,vehicle,false),'Vehicle is destroyed')
        if b(H.networked,vehicle) then assert(b(H.control,vehicle),'Vehicle not locally controlled') end
        local model=u32(i(H.model,vehicle));local p=PROFILES[model]
        assert(p,'Only Chernobog and Hunter are supported')
        if p.requires_cannon then assert(i(H.mod,vehicle,10)==0,'Equip the Hunter explosive-cannon upgrade first') end
        return {pid=pid,ped=ped,pa=pa,vehicle=vehicle,va=va,profile=p,model=model}
    end
    local function same_context(a,c)
        return a.pid==c.pid and a.ped==c.ped and a.pa==c.pa and a.vehicle==c.vehicle
            and a.va==c.va and a.model==c.model
    end
    local function buffer()
        if not S.buffer then
            local p=call(M.AllocInt);assert(pointer(p),'Could not allocate weapon readback buffer')
            S.buffer=p
        end
        if type(M.Check)=='function' then assert(M.Check(S.buffer)==true,'Readback guard failed') end
        if type(M.SizeOf)=='function' then assert(M.SizeOf(S.buffer)>=4,'Readback buffer too short') end
        return S.buffer
    end
    local function selected(ped)
        local p=buffer();call(M.WriteInt,p,0)
        if not b(H.selected,ped,p) then return nil end
        return u32(read('UInt',p))
    end
    local function clip(vehicle)
        local p=buffer();call(M.WriteInt,p,-1)
        if not b(H.clip,vehicle,-1,p) then return nil end
        local value=read('Int',p);return integer(value,0,100000) and value or nil
    end
    local function table_ok(a,expected_seat)
        local img=image();assert(same_image(img,a.img),'Executable changed')
        assert(image_pointer(read('Long',a.handling),img),'Handling vtable is outside game image')
        assert(u32(read('UInt',a.handling+8))==a.model,'Handling name does not match vehicle')
        assert(math.abs(read('Float',a.handling+12)-a.profile.mass)<0.01,'Handling mass differs')
        assert(read('Long',a.handling+0x158)==a.array,'Subhandling array changed')
        assert(read('UShort',a.handling+0x160)==a.count,'Subhandling count changed')
        assert(read('UShort',a.handling+0x162)==a.capacity,'Subhandling capacity changed')
        assert(read('Long',a.array+a.index*8)==a.weapon_data,'Weapon subhandling identity changed')
        assert(read('Long',a.weapon_data)==a.vtable and image_pointer(a.vtable,img),'Weapon vtable changed')
        for j=0,5 do
            assert(u32(read('UInt',a.weapon_data+8+j*4))==a.profile.hashes[j+1],'Weapon hash row changed')
            local row=a.seat_rows and a.seat_rows[j]
            local value=read('Int',a.weapon_data+0x20+j*4)
            if expected_seat=='leased' and row and row.attempted then
                -- A rejected/throwing write might still have reached memory.
                -- Only this exact attempted row may be original OR desired.
                assert(value==row.original or value==row.desired,
                    'Leased weapon seat row has a foreign value: '..j)
            else
                local wanted=a.profile.seats[j+1]
                if row and type(expected_seat)=='number' then wanted=expected_seat end
                assert(value==wanted,'Weapon seat row changed outside this test: '..j)
            end
        end
        assert(math.abs(read('Float',a.weapon_data+0x50)-a.profile.turret_speed)<0.001,'Turret-layout discriminator changed')
        return true
    end
    local function map(c)
        stage('image: validate executable fingerprint')
        local img=image()
        if S.trace then
            log('IMAGE',('profile=%s TimeDateStamp=%d SizeOfImage=%d; metadata only; layout must pass separately')
                :format(img.tag,img.timestamp,img.size))
        end
        stage('mapping: scan Enhanced handling signature')
        local site=call(M.Scan,HANDLING_PATTERN,GAME)
        assert(integer(site,img.base,img.base+img.size-32),
            'Enhanced handling signature not found; no offset fallback')
        -- Re-read every fixed opcode, including the MOV destination/source registers.
        -- Never accept a scan address alone as permission to dereference an entity field.
        for at,wanted in pairs(HANDLING_FIXED) do
            assert(read('UByte',site+at)==wanted,'Enhanced handling instruction bytes changed')
        end
        local offset=read('Int',site+7)
        assert(integer(offset,0x600,0x1800) and offset%8==0,'Handling offset failed bounds')
        stage('mapping: read derived handling pointer')
        local handling=read('Long',c.va+offset);assert(pointer(handling),'No handling pointer')
        assert(image_pointer(read('Long',handling),img),'Invalid handling vtable')
        assert(u32(read('UInt',handling+8))==c.model,'Handling-name fingerprint mismatch')
        assert(math.abs(read('Float',handling+12)-c.profile.mass)<0.01,'Handling-mass fingerprint mismatch')
        local array=read('Long',handling+0x158)
        local count,capacity=read('UShort',handling+0x160),read('UShort',handling+0x162)
        assert(pointer(array) and integer(count,1,12) and integer(capacity,count,32),'Subhandling array layout mismatch')
        local found={}
        for n=0,count-1 do
            stage('mapping: inspect subhandling entry '..n)
            local p=read('Long',array+n*8)
            if pointer(p) then
                local ok,match=pcall(function()
                    local vt=read('Long',p);if not image_pointer(vt,img) then return false end
                    for j=0,5 do
                        if u32(read('UInt',p+8+j*4))~=c.profile.hashes[j+1] then return false end
                        if read('Int',p+0x20+j*4)~=c.profile.seats[j+1] then return false end
                    end
                    return math.abs(read('Float',p+0x50)-c.profile.turret_speed)<0.001
                end)
                if ok and match then found[#found+1]={p=p,index=n} end
            end
        end
        assert(#found==1,'No unique exact weapon/seat table match; no writes made')
        local a=c
        a.img,a.handling,a.offset,a.array,a.count,a.capacity=img,handling,offset,array,count,capacity
        a.weapon_data,a.index=found[1].p,found[1].index
        a.vtable=read('Long',a.weapon_data);a.seat_addr=a.weapon_data+0x20+a.profile.slot*4
        a.seat_rows={};a.seat_order={}
        for _,slot in ipairs(a.profile.remap_slots) do
            assert(a.profile.seats[slot+1]==1,'Remap profile is not an original passenger assignment')
            local row={slot=slot,address=a.weapon_data+0x20+slot*4,original=1,desired=0,attempted=false}
            a.seat_rows[slot]=row;a.seat_order[#a.seat_order+1]=row
        end
        a.owned=false;a.selection_attempted=false;a.mapping_site=site
        a.mapping_bytes={}
        for j=0,14 do a.mapping_bytes[j+1]=read('UByte',site+j) end
        assert(read('Long',a.va+a.offset)==a.handling,'Vehicle handling pointer changed during mapping')
        table_ok(a,1)
        return a
    end
    local function finish_burst(reason)
        local burst=S.burst;if not burst then return end
        S.burst=nil
        local detail=('route=%s commands=%d triggerFrames=%d heldMs=%s pedShootingObserved=%s clipDecrease=%s clipBefore=%s clipLast=%s reloadAtStart=%s reloadRemainingAtStart=%s deadResync=%s deadResyncReturn=%s deadResyncAtMs=%s reason=%s physicalFire=UNVERIFIED manualFlight=UNVERIFIED')
            :format(burst.route or 'native-command',burst.commands,burst.trigger_frames or 0,
                tostring(burst.started_at and S.last_now and math.max(0,S.last_now-burst.started_at) or nil),
                tostring(burst.shooting),tostring(burst.clip_decreased),
                tostring(burst.clip_before),tostring(burst.clip_last),tostring(burst.reload_at_start),
                tostring(burst.reload_remaining_at_start),tostring(burst.dead_resync_submitted==true),
                tostring(burst.dead_resync_result),tostring(burst.dead_resync_at and burst.started_at and burst.dead_resync_at-burst.started_at or nil),
                tostring(reason))
        log('FIRE_OBSERVATION',detail)
    end
    local function same_native_subject(a)
        assert(call(G.GetLocalPlayerId)==a.pid and i(H.ped,a.pid)==a.ped,
            'Original local ped changed; cannon cleanup withheld')
        assert(physical(a.ped,'IsPed')==a.pa and physical(a.vehicle,'IsVehicle')==a.va,
            'Original ped or vehicle address changed; cannon cleanup withheld')
        assert(u32(i(H.model,a.vehicle))==a.model,'Original vehicle model changed')
        if b(H.networked,a.vehicle) then
            assert(b(H.control,a.vehicle),'No normal vehicle control for cannon cleanup')
        end
    end
    local function known_hunter_weapon(a,value)
        if not value or value==0 then return false end
        for _,weapon in ipairs(a.profile.hashes) do
            if weapon~=0 and value==weapon then return true end
        end
        return false
    end
    local function original_pilot_weapon(a,value)
        if not value or value==0 then return false end
        for index,weapon in ipairs(a.profile.hashes) do
            if weapon~=0 and weapon==value and a.profile.seats[index]==0 then return true end
        end
        return false
    end
    local function preferred_restore_target(a,current)
        if original_pilot_weapon(a,current) then return current end
        if original_pilot_weapon(a,a.previous) then return a.previous end
        return nil -- discover an available ORIGINAL driver-row weapon after reset
    end
    local function record_cleanup_policy(a)
        a.cleanup_availability={}
        local recovery=not original_pilot_weapon(a,a.previous)
        for index,weapon in ipairs(a.profile.hashes) do
            if weapon~=0 then
                local value=a.availability_baseline[weapon]
                assert(type(value)=='boolean','Availability baseline missing a weapon')
                a.cleanup_availability[weapon]=value
                if a.profile.seats[index]~=0 and value==false then recovery=true end
            end
        end
        a.baseline_recovery=recovery
        if recovery then
            -- Keep the raw snapshot untouched. After original-row repair we require
            -- passenger weapons disabled, while preserving both pilot-weapon flags.
            -- This is a declared normalization policy, NOT an invented old state.
            for index,weapon in ipairs(a.profile.hashes) do
                if weapon~=0 and a.profile.seats[index]~=0 then a.cleanup_availability[weapon]=true end
            end
            log('BASELINE_RECOVERY_PLANNED',('capturedSelection=0x%08X cannonDisabled=%s mgDisabled=%s; inherited passenger access is not an exact rollback target; Stop will require original pilot-row selection and disabled passenger weapons; no extra repair/enable')
                :format(a.previous,tostring(a.availability_baseline[a.profile.weapon]),
                    tostring(a.availability_baseline[a.profile.hashes[1]])))
        end
    end
    local function recovery_target_after_reset(a,current)
        if original_pilot_weapon(a,current) and not b(H.disabled,current,a.vehicle,a.ped) then return current end
        if original_pilot_weapon(a,a.previous) and not b(H.disabled,a.previous,a.vehicle,a.ped) then return a.previous end
        assert(a.baseline_recovery,'No legitimate saved pilot weapon; exact restoration cannot guess a replacement')
        for index,weapon in ipairs(a.profile.hashes) do
            if weapon~=0 and a.profile.seats[index]==0 and not b(H.disabled,weapon,a.vehicle,a.ped) then
                log('RECOVERY_SELECTION_TARGET',('available original driver-row weapon=0x%08X; recovery selection; original selection unavailable'):format(weapon))
                return weapon
            end
        end
        error('No available original pilot weapon after reset; no enable, guessed hash or extra repair')
    end
    local function refresh_subject(a)
        same_native_subject(a)
        session_ok()
        assert(not b(H.dead,a.ped,false) and not b(H.dead,a.vehicle,false),
            'Original pilot/vehicle is no longer alive; part reset withheld')
        assert(i(H.vehicle,a.ped,false)==a.vehicle and i(H.seat,a.vehicle,-1,false)==a.ped,
            'Stay in the original Hunter pilot seat until part-reset cleanup completes')
        assert(i(H.seat,a.vehicle,0,false)==0,'Gunner now occupied; part reset withheld')
        assert(b(H.player_control,a.pid),'Normal local player control unavailable; part reset withheld')
        assert(i(H.mod,a.vehicle,10)==0,'Hunter cannon upgrade changed; no mod overwrite or part reset')
        assert(read('Long',a.va+a.offset)==a.handling,'Vehicle handling pointer changed; part reset withheld')
        local health=call(N.InvokeFloat,H.engine_health,a.vehicle)
        assert(finite(health) and health>0 and health<=1000,
            'Hunter engine is broken or health unreadable; use a healthy test vehicle')
    end
    local function lifecycle_object_matches(a,obj,id)
        assert(type(obj)=='table' or type(obj)=='userdata','Network object unavailable')
        assert(obj.ObjectID==id,'Network-object ID mismatch')
        local ent=call(obj.GetEntity,obj)
        assert(ent~=nil and call(ent.IsVehicle,ent)==true,'Network object has no vehicle entity')
        assert(call(ent.GetAddress,ent)==a.va and call(G.PointerToHandle,ent)==a.vehicle,
            'Network object does not resolve to the original Hunter')
    end
    local function lifecycle_manager_object(id)
        local mgr=R.NetworkObjectMgr
        assert(mgr and type(mgr.GetNetworkObject)=='function','Network-object lookup unavailable')
        -- includeAll=true deliberately includes unregistering/reassigning objects.
        -- A non-nil result is NOT absence, even if GetEntity() is currently nil.
        local obj=call(mgr.GetNetworkObject,id,true)
        assert(obj==nil or type(obj)=='table' or type(obj)=='userdata','Invalid network-object lookup result')
        return obj
    end
    local function lifecycle_direct_id(a)
        local addr,ent=physical(a.vehicle,'IsVehicle')
        assert(addr==a.va,'Lifecycle vehicle identity changed')
        local net=ent.NetObject
        assert(net~=nil,'Original vehicle has no readable NetObject')
        local id=net.ObjectID
        -- Do not truncate/mask a rejected raw native result. Zero is only a
        -- candidate: it needs the same independent round trips as every other ID.
        assert(integer(id,0,65535),'Network-object ID outside validated candidate range')
        lifecycle_object_matches(a,net,id)
        lifecycle_object_matches(a,lifecycle_manager_object(id),id)
        local addr2,ent2=physical(a.vehicle,'IsVehicle')
        assert(addr2==a.va and ent2.NetObject~=nil and ent2.NetObject.ObjectID==id,
            'Network-object association changed during capture')
        return id
    end
    local function lifecycle_native_id(a,raw)
        assert(integer(raw,0,65535),'Native ID outside validated candidate range')
        assert(b(H.net_exists,raw) and b(H.net_entity_exists,raw),
            'Native network identity not independently present')
        assert(i(H.net_entity,raw)==a.vehicle,'Native ID inverse does not resolve to original Hunter')
        assert(i(H.net_id,a.vehicle)==raw,'Native network identity changed')
        assert(physical(a.vehicle,'IsVehicle')==a.va,'Lifecycle subject changed during capture')
        return raw
    end
    local function capture_lifecycle_identity(a)
        -- Optional read-only capture. No activation delays, network writes or
        -- fabricated metadata after deletion. Failed probes retain exact values.
        local life=a.lifecycle or {captured=false,rebinds=0,attempts=0}
        a.lifecycle=life
        if life.captured or life.session_changed then return end
        life.attempts=life.attempts+1
        local clock_ok,clock=pcall(i,H.time)
        life.last_capture=clock_ok and clock or nil
        local ok,err=pcall(function()
            assert(physical(a.vehicle,'IsVehicle')==a.va,'Lifecycle vehicle identity changed')
            assert(not b(H.dead,a.vehicle,false),'No new identity capture on destroyed Hunter')
            assert(same_context(a,context()),'Lifecycle capture requires original live local pilot')
            local session_active=b(H.session)
            if life.session_active~=nil then
                assert(session_active==life.session_active,'Session changed during capture retries')
            end
            life.session_active=session_active
            local networked=b(H.networked,a.vehicle)
            if life.networked~=nil then
                assert(networked==life.networked,'Network mode changed during capture retries')
            end
            life.networked=networked
            if networked then
                local raw_ok,raw=pcall(i,H.net_id,a.vehicle)
                life.raw_native=raw_ok and raw or ('ERROR: '..tostring(raw))
                local n_ok,nid=false,nil
                if raw_ok then n_ok,nid=pcall(lifecycle_native_id,a,raw) end
                local d_ok,did=pcall(lifecycle_direct_id,a)
                life.direct_result=d_ok and did or ('ERROR: '..tostring(did))
                assert(not (n_ok and d_ok and nid~=did),'Independent network identity sources disagree')
                if d_ok then
                    life.net_id=did;life.source='cherax-object';life.manager_confirmed=true
                elseif n_ok then
                    life.net_id=nid;life.source='native-roundtrip';life.manager_confirmed=false
                else
                    error('No independently verified network identity; native='..tostring(life.raw_native)
                        ..'; nativeCheck='..tostring(nid)..'; objectCheck='..tostring(life.direct_result))
                end
            else
                life.source='non-networked';life.manager_confirmed=false
            end
            assert(physical(a.vehicle,'IsVehicle')==a.va and u32(i(H.model,a.vehicle))==a.model,
                'Lifecycle subject changed during capture')
            assert(b(H.session)==session_active and b(H.networked,a.vehicle)==networked,
                'Lifecycle context changed during capture')
            life.captured=true;life.capture_error=nil
        end)
        if ok then
            log('LIFECYCLE_ID_CAPTURED',('source=%s id=%s nativeRaw=%s objectResult=%s attempt=%d; original vehicle identity cross-checked; read-only')
                :format(tostring(life.source),tostring(life.net_id),tostring(life.raw_native),
                    tostring(life.direct_result),life.attempts))
        else
            life.capture_error=tostring(err)
            log('LIFECYCLE_ID_UNAVAILABLE',('attempt=%d nativeRaw=%s; normal activation unchanged; disappearance retirement withheld: %s')
                :format(life.attempts,tostring(life.raw_native),life.capture_error))
        end
    end
    local function retry_lifecycle_capture(a,now)
        local life=a.lifecycle
        if not life or life.captured or life.session_changed
            or life.attempts>=LIFECYCLE_CAPTURE_MAX_ATTEMPTS then return end
        if life.last_capture and now-life.last_capture<LIFECYCLE_CAPTURE_RETRY_MS then return end
        -- Called only after verify_active in the existing gameplay loop. Never
        -- called from cleanup/unload, and no retargeting to a respawned vehicle.
        capture_lifecycle_identity(a)
    end
    local function clear_absence(life)
        life.absent_since=nil;life.absent_count=0;life.absent_frame=nil;life.absent_time=nil
    end
    local function cleanup_vehicle_state(a)
        local life=a.lifecycle
        assert(life,'No recorded lifecycle identity; native cleanup remains pending')
        -- Every error breaks an absence streak. An exception is never a false
        -- existence result. Nor is a reused handle permission to repair it.
        local ok,result,detail=pcall(function()
            assert(not life.session_changed,
                'Session changed; original lifecycle identity is no longer sufficient for native cleanup')
            if b(H.exists,a.vehicle) then
                clear_absence(life)
                assert(physical(a.vehicle,'IsVehicle')==a.va,
                    'Original vehicle address changed/reused; no replacement-vehicle cleanup')
                assert(u32(i(H.model,a.vehicle))==a.model,
                    'Original vehicle model changed; no replacement-vehicle cleanup')
                if life.captured and life.networked then
                    assert(b(H.networked,a.vehicle),'Original vehicle network mode changed')
                    if life.source=='cherax-object' then
                        assert(lifecycle_direct_id(a)==life.net_id,
                            'Original vehicle network identity changed; no replacement-vehicle cleanup')
                    else
                        assert(lifecycle_native_id(a,i(H.net_id,a.vehicle))==life.net_id,
                            'Original vehicle network identity changed; no replacement-vehicle cleanup')
                    end
                end
                if b(H.dead,a.vehicle,false) then
                    return 'waiting','Original Hunter is destroyed but still exists; no wreck repair; awaiting removal or a usable original instance'
                end
                return 'present'
            end
            assert(life.captured,'Original vehicle absent but lifecycle identity was not captured')
            assert(not life.session_changed and b(H.session)==life.session_active,
                'Session context changed; old network lifetime cannot be inferred here')
            session_ok()
            assert(not b(H.switching),'Player switch in progress; absence is not deletion evidence')
            if life.networked then
                local net_present=b(H.net_exists,life.net_id)
                local entity_present=b(H.net_entity_exists,life.net_id)
                local manager_present=false
                if life.manager_confirmed then manager_present=lifecycle_manager_object(life.net_id)~=nil end
                if net_present or entity_present or manager_present then
                    clear_absence(life)
                    return 'waiting','Original vehicle handle absent but its network identity remains; not treating streaming loss as deletion'
                end
                if not life.manager_confirmed then
                    assert(i(H.net_entity,life.net_id)==0,'Native ID still resolves to an entity; not absence')
                end
            end
            -- Repeat after network reads to reject reappearance within a sample.
            assert(not b(H.exists,a.vehicle),'Vehicle reappeared during absence observation')
            local now,frame=i(H.time),i(H.frame)
            assert(integer(now,0,4294967295) and integer(frame,0,4294967295),
                'Lifecycle observation clock unavailable')
            if life.absent_time and (now<life.absent_time or frame<life.absent_frame
                or now-life.absent_time>LIFECYCLE_MAX_SAMPLE_GAP_MS) then
                clear_absence(life)
            end
            if not life.absent_since then life.absent_since=now end
            local independent_sample=life.absent_frame~=frame
            if independent_sample then
                life.absent_count=math.min(LIFECYCLE_ABSENCE_FRAMES,(life.absent_count or 0)+1)
                life.absent_frame=frame;life.absent_time=now
            end
            if independent_sample and (life.absent_count or 0)>=LIFECYCLE_ABSENCE_FRAMES
                and now-life.absent_since>=LIFECYCLE_ABSENCE_MS then
                -- Shared state is never retired with an entity. It must still
                -- have its original values at the exact validated table.
                table_ok(a,1)
                return 'absent','Original vehicle handle and captured network lifetime are absent on independent samples'
            end
            return 'waiting','Confirming original vehicle absence; no repair, selection, or flag write'
        end)
        if not ok then clear_absence(life);return 'waiting',tostring(result) end
        return result,detail
    end
    local function cleanup_pilot_subject(a)
        local current=a.cleanup_subject or a
        -- Do not relax the original pointer guard when a handle's address changes.
        if call(G.GetLocalPlayerId)==current.pid and i(H.ped,current.pid)==current.ped then
            assert(b(H.exists,current.ped),'Original pilot is absent while the Hunter still exists; awaiting a local cleanup pilot')
            assert(not b(H.dead,current.ped,false),
                'Original local pilot is dead while the Hunter still exists; awaiting respawn or vehicle removal')
            return current
        end
        assert(call(G.GetLocalPlayerId)==a.pid,'Local player identity changed; cleanup rebind withheld')
        local old_present=b(H.exists,current.ped)
        assert(not old_present or b(H.dead,current.ped,false),
            'Original pilot still exists/alive; no cleanup rebind')
        assert(not (a.cannon_enable and a.cannon_enable.restore_required),
            'Original ped-specific cannon flag still pending; never retargeting that lease to a respawned ped')
        assert(a.lifecycle.rebinds<LIFECYCLE_MAX_REBINDS,'Cleanup pilot-rebind limit reached')
        local candidate={}
        for k,value in pairs(a) do candidate[k]=value end
        candidate.ped=i(H.ped,a.pid)
        assert(candidate.ped>0 and candidate.ped~=current.ped,'Respawned local pilot not available')
        candidate.pa=physical(candidate.ped,'IsPed')
        candidate.cannon_enable=nil -- this ped was never the target of the old flag setter
        candidate.selection_attempted=false;candidate.hunter_hash_confirmed=true
        candidate.cleanup_subject=nil
        -- This check includes exact original vehicle/address, local control,
        -- actual pilot seat, empty gunner, healthy engine and unchanged upgrade.
        refresh_subject(candidate);table_ok(a,1)
        local weapon=selected(candidate.ped)
        assert(known_hunter_weapon(candidate,weapon),'Respawned pilot weapon unreadable; cleanup rebind withheld')
        local lease=a.parts_refresh
        if lease.restore_attempted then
            -- Do not repeat the repair. Preserve the new pilot's deliberate
            -- non-cannon weapon; old pending selections belonged to the old ped.
            lease.restore_target=preferred_restore_target(candidate,weapon)
            lease.cancel_unobserved=false;lease.cancel_confirmed=false
            lease.restore_streak=0;lease.restore_read_frame=nil
            -- Existing mutation count and time bounds are deliberately retained.
        end
        a.cleanup_subject=candidate;a.lifecycle.rebinds=a.lifecycle.rebinds+1
        a.selection_retired=true
        log('CLEANUP_PILOT_REBOUND',
            'Respawned local player is pilot of the exact original healthy Hunter; cleanup only; no seat move or automatic activation')
        return candidate
    end
    local function capture_hunter_availability(a)
        local result={}
        for _,weapon in ipairs(a.profile.hashes) do
            if weapon~=0 then result[weapon]=b(H.disabled,weapon,a.vehicle,a.ped) end
        end
        return result
    end
    local function request_hunter_parts(a)
        assert(a.profile.native_pilot_input and a.availability_baseline,
            'Part reset requires a recorded Hunter baseline')
        refresh_subject(a);table_ok(a,0)
        local frame=i(H.frame)
        -- Journal BEFORE the external native call, including throw-after-mutation.
        -- A pending refresh must be unwound even if no selection setter ever runs.
        a.parts_refresh={activation_frame=frame,restore_required=true,
            restore_attempted=false,restore_streak=0,restore_select_writes=0}
        log('WEAPON_PARTS_REFRESH_REQUESTED',
            'Calling SET_VEHICLE_FIXED once after both row writes; repairs damage; real local ped remains DRIVER; engine effect unverified')
        v(H.repair,a.vehicle)
        refresh_subject(a);table_ok(a,0)
        log('WEAPON_PARTS_REFRESH_SUBMITTED',
            'Repair call returned; this does NOT prove controller rebuild or firing; later selection/availability will decide')
    end
    local function restore_cannon(a,allow_natives)
        local lease=a.cannon_enable
        if not lease or not lease.restore_required then return true end
        if not allow_natives then return false,'Cannon state needs gameplay-thread cleanup; keep script loaded' end
        local ok,err=pcall(function()
            same_native_subject(a)
            local state=b(H.disabled,a.profile.weapon,a.vehicle,a.ped)
            same_native_subject(a)
            -- A true baseline restored by GTA/another script is left alone.
            if state==lease.original then
                lease.restore_required=false
                log('CANNON_RESTORED','Original disabled=true observed; no extra native write needed')
                return
            end
            local now=i(H.time)
            assert(integer(now,0,4294967295),'Cleanup timer unavailable')
            if lease.restore_at and now>=lease.restore_at and now-lease.restore_at<CANNON_RESTORE_RETRY_MS then
                error('Cannon cleanup waiting for its bounded retry interval')
            end
            assert((lease.restore_writes or 0)<CANNON_RESTORE_MAX_WRITES,
                'Cannon cleanup write limit reached; observing for baseline recovery, no repeated setter')
            same_native_subject(a)
            lease.restore_at=now;lease.restore_writes=(lease.restore_writes or 0)+1
            v(H.set_disabled,lease.original,a.profile.weapon,a.vehicle,a.ped)
            same_native_subject(a)
            assert(b(H.disabled,a.profile.weapon,a.vehicle,a.ped)==lease.original,
                'Cannon disabled-state restoration not confirmed')
            same_native_subject(a)
            lease.restore_required=false
            log('CANNON_RESTORED','Original disabled=true read back for the same local ped and Hunter')
        end)
        return ok and not lease.restore_required,ok and nil or tostring(err)
    end
    local function restore_hunter_selection(a,allow_natives)
        if not a.profile.native_pilot_input or not a.selection_attempted or a.selection_restored then
            return true
        end
        if not allow_natives then
            return false,'Hunter selection needs gameplay-thread cleanup; no unload-native call made'
        end
        local ok,err=pcall(function()
            same_native_subject(a)
            -- SET_CURRENT_PED_VEHICLE_WEAPON targets the ped's current vehicle.
            -- Never issue it after a vehicle/seat change just to clear a journal.
            if i(H.vehicle,a.ped,false)~=a.vehicle or i(H.seat,a.vehicle,-1,false)~=a.ped then
                a.selection_restored=true
                a.selection_note='; pilot context ended, prior selection not asserted'
                log('SELECTION_SCOPE_ENDED','Original pilot context ended; no selection write to another seat or vehicle')
                return
            end
            local current=selected(a.ped)
            same_native_subject(a)
            assert(current~=nil,'Hunter cleanup selected-weapon readback unavailable')
            -- A still-visible original hash does not cancel an accepted target
            -- request that has not yet been observed. Send the original selection
            -- explicitly, then observe two later frames before releasing that case.
            local cancel_unobserved=current==a.previous and not a.hunter_hash_confirmed
                and a.last_select_result~=false and not a.selection_cancel_frame
            if current==a.previous and not cancel_unobserved then
                if a.selection_cancel_frame then
                    local frame=i(H.frame)
                    assert(frame>a.selection_cancel_frame,'Selection cancellation awaiting a later frame')
                    if a.selection_cancel_read_frame~=frame then
                        a.selection_cancel_streak=(a.selection_cancel_streak or 0)+1
                        a.selection_cancel_read_frame=frame
                    end
                    assert(a.selection_cancel_streak>=2,'Selection cancellation awaiting a second distinct frame')
                end
                a.selection_restored=true
                log('SELECTION_RESTORED','Original Hunter weapon read back; no additional selection request needed')
                return
            end
            if current~=a.profile.weapon and not cancel_unobserved then
                -- A deliberate/external weapon cycle is not ours to overwrite.
                a.selection_restored=true
                a.selection_note='; intervening weapon selection left unchanged'
                log('SELECTION_RELEASED','Different current weapon observed; no overwrite of the intervening selection')
                return
            end
            assert(a.previous and a.previous~=0,'Original Hunter selection unavailable')
            local now=i(H.time)
            assert(integer(now,0,4294967295),'Selection cleanup timer unavailable')
            if a.selection_restore_at and now>=a.selection_restore_at
                and now-a.selection_restore_at<SELECTION_RESTORE_RETRY_MS then
                error('Selection cleanup waiting for its bounded retry interval')
            end
            assert((a.selection_restore_writes or 0)<SELECTION_RESTORE_MAX_WRITES,
                'Selection cleanup write limit reached; observing for original selection, no repeated setter')
            same_native_subject(a)
            assert(i(H.vehicle,a.ped,false)==a.vehicle and i(H.seat,a.vehicle,-1,false)==a.ped,
                'Pilot context changed before selection cleanup')
            a.selection_restore_at=now
            a.selection_restore_writes=(a.selection_restore_writes or 0)+1
            -- Journal remains pending even when the native throws after mutation.
            local accepted=b(H.select,a.ped,a.previous)
            same_native_subject(a)
            assert(i(H.vehicle,a.ped,false)==a.vehicle and i(H.seat,a.vehicle,-1,false)==a.ped,
                'Pilot context changed during selection cleanup')
            local observed=selected(a.ped)
            same_native_subject(a)
            assert(observed==a.previous,
                'Original Hunter selection not confirmed after restore request; return='..tostring(accepted))
            if cancel_unobserved then
                -- With the old hash still visible, a rejected cancel is not
                -- evidence that the outstanding target request has gone away.
                assert(accepted,'Cancellation of unobserved Hunter selection was not accepted')
                a.selection_cancel_frame=i(H.frame);a.selection_cancel_streak=0
                a.selection_cancel_read_frame=nil
                error('Selection cancellation submitted; awaiting two later original-weapon readbacks')
            end
            a.selection_restored=true
            log('SELECTION_RESTORED','Original Hunter weapon read back after restore request; return='..tostring(accepted))
        end)
        return ok and a.selection_restored==true,ok and nil or tostring(err)
    end
    local function restore_hunter_parts_live(a,allow_natives)
        local lease=a.parts_refresh
        if not lease or not lease.restore_required then return true end
        if not allow_natives then
            return false,'Hunter part reset needs gameplay-thread cleanup; unload does not call repair or other gameplay natives'
        end
        local ok,err=pcall(function()
            refresh_subject(a);table_ok(a,1)
            local now,frame=i(H.time),i(H.frame)
            local current=selected(a.ped)
            assert(known_hunter_weapon(a,current),'Cleanup weapon readback unavailable or foreign; no blind part reset')
            if not lease.restore_attempted then
                -- Preserve a deliberate different pilot weapon when possible.
                -- Never overwrite a changed upgrade or a changed vehicle to finish cleanup.
                lease.restore_target=preferred_restore_target(a,current)
                lease.cancel_unobserved=a.selection_attempted and not a.hunter_hash_confirmed
                    and a.last_select_result~=false
                assert(lease.restore_target or a.baseline_recovery,'No valid original pilot selection for cleanup')
                lease.restore_attempted=true;lease.restore_frame=frame
                lease.restore_at=now;lease.last_mutation_frame=frame
                log('WEAPON_PARTS_RESTORE_REQUESTED',
                    'Original weapon-seat rows are back; calling SET_VEHICLE_FIXED once to reapply them to this Hunter; repairs damage')
                -- Even a rejected/throwing call is not blindly repeated.
                v(H.repair,a.vehicle)
                refresh_subject(a);table_ok(a,1)
                error('Awaiting later frames after original-state part-reset request')
            end
            assert(frame>lease.restore_frame,'Part-reset cleanup awaiting a later game frame')
            -- Reset can affect selected weapons too. A valid intervening pilot weapon
            -- captured before reset is restored, otherwise the original baseline is.
            current=selected(a.ped)
            if not lease.restore_target then
                lease.restore_target=recovery_target_after_reset(a,current)
            end
            assert(original_pilot_weapon(a,lease.restore_target),'Cleanup target is not an original pilot-row weapon')
            if current~=lease.restore_target or (lease.cancel_unobserved and not lease.cancel_confirmed) then
                lease.restore_streak=0;lease.restore_read_frame=nil
                assert(now>=lease.restore_at and now-lease.restore_at<PARTS_RESTORE_WINDOW_MS,
                    'Part-reset selection restore request window expired; no new writes')
                if lease.select_at and now-lease.select_at<SELECTION_RESTORE_RETRY_MS then
                    error('Part-reset selection restore waiting for bounded retry interval')
                end
                assert(lease.restore_select_writes<SELECTION_RESTORE_MAX_WRITES,
                    'Part-reset selection restore request limit reached')
                refresh_subject(a);table_ok(a,1)
                lease.select_at=now;lease.last_mutation_frame=frame
                lease.restore_select_writes=lease.restore_select_writes+1
                local accepted=b(H.select,a.ped,lease.restore_target)
                if lease.cancel_unobserved then lease.cancel_confirmed=accepted==true end
                refresh_subject(a);table_ok(a,1)
                log('PARTS_SELECTION_RESTORE_REQUEST',
                    ('return=%s; target=0x%08X; awaiting later readbacks'):format(tostring(accepted),lease.restore_target))
                error('Part-reset selection restore awaiting independent readbacks')
            end
            -- Undo the separately journalled disable-flag trial when one was made.
            -- No other weapon hash is enabled/disabled by cleanup.
            local before=a.cannon_enable and (a.cannon_enable.restore_writes or 0) or 0
            local clean,why=restore_cannon(a,true)
            local after=a.cannon_enable and (a.cannon_enable.restore_writes or 0) or 0
            if after~=before then lease.last_mutation_frame=frame end
            assert(clean,why or 'Cannon flag restore is pending')
            refresh_subject(a);table_ok(a,1)
            local observed=capture_hunter_availability(a)
            for _,weapon in ipairs(a.profile.hashes) do
                if weapon~=0 and observed[weapon]~=(a.cleanup_availability or a.availability_baseline)[weapon] then
                    lease.restore_streak=0;lease.restore_read_frame=nil
                    error(((a.baseline_recovery and 'Recovery availability' or 'Original availability')..' not yet observed for 0x%08X; reset not repeated'):format(weapon))
                end
            end
            assert(selected(a.ped)==lease.restore_target,'Selection changed during part-reset cleanup observation')
            assert(not observed[lease.restore_target],'Restored pilot weapon is disabled; cleanup not complete')
            refresh_subject(a);table_ok(a,1)
            assert(frame>lease.last_mutation_frame,'Part-reset cleanup awaiting a frame after the last native mutation')
            if lease.restore_read_frame~=frame then
                lease.restore_read_frame=frame;lease.restore_streak=lease.restore_streak+1
            end
            assert(lease.restore_streak>=2,'Part-reset cleanup awaiting a second distinct baseline frame')
            lease.restore_required=false;a.selection_restored=true
            if a.cannon_enable then a.cannon_enable.restore_required=false end
            if a.baseline_recovery then
                lease.normalized=true
                log('WEAPON_PARTS_RECOVERY_OBSERVED',
                    'Two later frames confirm original-row pilot selection, disabled passenger weapons and preserved pilot availability; inherited state normalized; original selection unavailable')
            else
                log('WEAPON_PARTS_BASELINE_OBSERVED',
                    'Two later frames match the saved weapon-availability states and cleanup selection; engine internals/physical firing not inspected')
            end
        end)
        return ok and not lease.restore_required,ok and nil or tostring(err)
    end
    local function restore_hunter_parts(a,allow_natives)
        local lease=a.parts_refresh
        if not lease or not lease.restore_required then return true end
        if not allow_natives then
            return false,'Instance cleanup needs the gameplay loop; direct unload does not probe entities or invoke repair'
        end
        local state,why=cleanup_vehicle_state(a)
        if state=='waiting' then return false,why end
        if state=='absent' then
            -- This closes an obsolete instance journal, NOT a successful repair
            -- or a verified selected/disabled-state restoration on a dead entity.
            lease.restore_required=false;lease.retired=true;lease.outcome='retired_vehicle'
            a.selection_retired=true
            if a.cannon_enable then
                a.cannon_enable.restore_required=false;a.cannon_enable.retired=true
            end
            log('INSTANCE_RETIRED',tostring(why)..'; shared rows verified original; no gameplay setter on the vanished instance')
            return true
        end
        local ok,subject=pcall(cleanup_pilot_subject,a)
        if not ok then return false,tostring(subject) end
        if subject~=a then
            -- The first rebind happens after release's original-ped fire guard.
            -- Block only mounted fire for this verified cleanup pilot as well.
            local guarded,err=pcall(function()
                refresh_subject(subject);table_ok(a,1)
                for _,control in ipairs(ATTACK) do v(H.disable_control,0,control,true) end
            end)
            if not guarded then return false,tostring(err) end
        end
        local clean,err=restore_hunter_parts_live(subject,true)
        if clean then
            lease.outcome=lease.normalized and 'normalized_original_rows'
                or (subject==a and 'restored_original_pilot' or 'restored_respawned_pilot')
        end
        return clean,err
    end
    local function release(reason,allow_natives)
        finish_burst(reason)
        local a=S.active
        if not a then S.stopping=nil;return true end
        -- A part reset invalidates cached state; do not finish the old selection-only
        -- cleanup before the original seat rows have been reapplied to this instance.
        local refreshed=a.parts_refresh~=nil
        if refreshed then
            a.fire_armed=false;a.selected_once=false;a.selection_pending=false
            S.select_requested=false
        end
        if refreshed and allow_natives then
            -- Do not let held experimental cannon fire pass during original-state
            -- repair/cancellation. Never suppress flight or a new vehicle's inputs.
            pcall(function()
                local subject=a.cleanup_subject or a
                same_native_subject(subject)
                if i(H.vehicle,subject.ped,false)==a.vehicle and i(H.seat,a.vehicle,-1,false)==subject.ped then
                    for _,control in ipairs(ATTACK) do v(H.disable_control,0,control,true) end
                end
            end)
        end
        local selection_clean,selection_error=true,nil
        if not refreshed then selection_clean,selection_error=restore_hunter_selection(a,allow_natives) end
        -- Keep the inherited Chernobog cleanup separate from the Hunter experiment.
        if not a.profile.native_pilot_input and allow_natives and a.selection_attempted and not a.selection_restored then
            local ok,c=pcall(context)
            if ok and same_context(a,c) then
                local got_ok,got=pcall(selected,a.ped)
                if got_ok and got==a.profile.weapon and a.previous and a.previous~=0
                    and a.previous~=a.profile.weapon then
                    local set_ok,set_result=pcall(b,H.select,a.ped,a.previous)
                    local read_ok,observed=pcall(selected,a.ped)
                    if not set_ok or not set_result or not read_ok or observed~=a.previous then
                        a.selection_note='; prior weapon selection not confirmed: leave/re-enter vehicle'
                        log('SELECTION_RESTORE_UNVERIFIED','Seat restoration continues; leave/re-enter the vehicle before further testing')
                    end
                end
            end
            a.selection_restored=true
            if not a.previous or a.previous==0 then
                a.selection_note='; no previous driver weapon was readable: leave/re-enter if turret stays selected'
            end
        end
        -- Try the ped-specific baseline first, but restore the seat even if
        -- this native cleanup is pending. Neither pending part is forgotten.
        local cannon_clean,cannon_error=true,nil
        if not refreshed then cannon_clean,cannon_error=restore_cannon(a,allow_natives) end
        if a.owned then
            local ok,err=pcall(function()
                -- The model handling identity is independent of the departing driver.
                -- Never write into a changed/replaced table or overwrite another owner's value.
                table_ok(a,'leased')
                for n=#a.seat_order,1,-1 do
                    local row=a.seat_order[n]
                    if row.attempted then
                        table_ok(a,'leased')
                        local current=read('Int',row.address)
                        if current~=row.original then
                            assert(current==row.desired,'Owned seat row changed: '..row.slot)
                            local result=call(M.WriteInt,row.address,row.original)
                            assert(result~=false and read('Int',row.address)==row.original,
                                'Seat restore write not confirmed for row '..row.slot)
                        end
                        -- Clear the row's lease only after its original value is observed.
                        row.attempted=false
                        table_ok(a,'leased')
                    end
                end
                table_ok(a,1);a.owned=false
            end)
            if not ok then
                S.stopping=reason
                log('RESTORE_PENDING',tostring(err)..'; no new mapping or firing; shared-state conflict remains pending, not discarded')
                return false
            end
        end
        if refreshed then
            local clean,why=restore_hunter_parts(a,allow_natives)
            if not clean then
                S.stopping=reason
                log('RESTORE_PENDING','Original seat rows restored; '..tostring(why)..'; keep loaded; no new activation/firing')
                return false
            end
        end
        if not cannon_clean or not selection_clean then
            S.stopping=reason
            local pending={}
            if not selection_clean then pending[#pending+1]=tostring(selection_error) end
            if not cannon_clean then pending[#pending+1]=tostring(cannon_error) end
            log('RESTORE_PENDING','All owned seat rows restored; '..table.concat(pending,'; ')..'; no new activation or firing')
            return false
        end
        S.active=nil;S.stopping=nil;S.last_input=false;S.select_requested=false;S.last_command=-100000
        S.last_cleanup_outcome=refreshed and a.parts_refresh.outcome or 'restored'
        if refreshed and a.parts_refresh.normalized then
            log('NORMALIZED',tostring(reason)..'; original seat rows confirmed; inherited passenger access normalized with available pilot selection on two later frames; original selection unavailable')
            log('CLEANUP_COMPLETE',tostring(reason)..'; normalization verified for THIS journal; no claim about a prior unresolved unload; safe to unload')
        elseif refreshed and a.parts_refresh.retired then
            log('CLEANUP_COMPLETE',tostring(reason)..'; all '..#a.seat_order
                ..' original shared seat row(s)=1 confirmed; vanished vehicle instance leases RETIRED, not repaired or baseline-verified; safe to unload this completed journal')
        else
            log('RESTORED',tostring(reason)..'; all '..#a.seat_order..' original passenger seat row(s)=1 confirmed'
                ..(a.cannon_enable and not a.cannon_enable.retired and '; cannon disabled-state baseline confirmed' or '')
                ..(refreshed and '; original-state part reset requested and baseline observations confirmed; repaired damage is not reapplied' or '')
                ..(a.cleanup_subject and '; verified with the respawned LOCAL pilot of the same original Hunter; old selection scope retired' or '')..(a.selection_note or ''))
        end
        return true
    end
    local function queue_selection(a,now,frame,reason)
        assert(integer(now,0,4294967295) and integer(frame,0,4294967295),'Selection clock unavailable')
        finish_burst('selection queued')
        a.selection_pending=true;a.selected_once=false;a.fire_armed=false
        a.selection_at=now;a.selection_frame=frame
        a.selection_deadline=now+SELECTION_TIMEOUT_MS
        a.next_selection_request=now+SELECTION_SETTLE_MS
        a.selection_requests=0;a.last_request_frame=nil
        a.readback_streak=0;a.readback_frame=nil;a.last_select_result=nil
        a.hunter_phase=a.profile.native_pilot_input and 'select-first' or nil
        a.hunter_hash_confirmed=false
        a.ready_streak=0;a.ready_frame=nil
        S.last_command=-100000;S.last_input=false
        log('SETTLING',('%s; %s; wait %d ms and a later game frame before selection; no firing')
            :format(a.profile.name,reason,SELECTION_SETTLE_MS))
    end
    local function open(now,frame)
        S.pending_messages={};S.pending_order={};S.pending_suppressed=0
        -- A successful read-only check is single-use, not a cached replacement
        -- for scanning/validating again. Consume it even if activation fails.
        local proof=S.mapping_proof;S.mapping_proof=nil
        local c=context();local img=image()
        local explicit_check=img.requires_mapping and not c.profile.automatic_mapping
        if explicit_check then
            stage('activation: require fresh explicit mapping check')
            assert(proof and integer(proof.checked_at,0,4294967295)
                and now>=proof.checked_at and now-proof.checked_at<MAPPING_CHECK_LIFETIME_MS,
                'Run Check Mapping (No Changes) with this vehicle first; mapping check missing or expired')
            assert(same_context(proof,c) and same_image(proof.img,img),
                'Vehicle or executable changed since mapping check; run Check Mapping again')
        end
        local a=map(c)
        assert(same_image(img,a.img),'Executable changed during activation')
        if explicit_check then
            stage('activation: compare fresh mapping to explicit check')
            for _,key in ipairs({'handling','offset','array','count','capacity','weapon_data',
                'index','vtable','seat_addr','mapping_site'}) do
                assert(a[key]==proof[key],'Mapping identity changed since check: '..key)
            end
            for j=1,15 do
                assert(a.mapping_bytes[j]==proof.mapping_bytes[j],
                    'Mapping instruction bytes changed since check')
            end
        end
        if a.profile.automatic_mapping then
            log('AUTO_VALIDATED','Hunter current-process image, identity and exact weapon/seat table passed; no repeated manual mapping test required')
        end
        -- Output-buffer allocation belongs only to activation, never to the read-only check.
        stage('selection: allocate and read current weapon buffer')
        a.previous=selected(a.ped)
        if a.profile.native_pilot_input then
            -- A reversible selection experiment requires a readable starting weapon.
            assert(a.previous and a.previous~=0,'Initial Hunter weapon is unreadable; no mutation made')
            local known=false
            for _,weapon in ipairs(a.profile.hashes) do
                if weapon~=0 and a.previous==weapon then known=true;break end
            end
            assert(known,'Initial Hunter weapon is outside its exact profile; no mutation made')
        end
        a.disabled_before_remap=b(H.disabled,a.profile.weapon,a.vehicle,a.ped)
        if a.profile.native_pilot_input then
            refresh_subject(a)
            capture_lifecycle_identity(a)
            a.availability_baseline=capture_hunter_availability(a)
            assert(a.availability_baseline[a.profile.weapon]==a.disabled_before_remap,
                'Hunter availability changed during baseline capture; no writes made')
            record_cleanup_policy(a)
            refresh_subject(a)
        end
        log('WEAPON_BASELINE',('disabledBeforeSeatRemap=%s; selected=%s; no seat or enable write yet')
            :format(tostring(a.disabled_before_remap),a.previous and ('0x%08X'):format(a.previous) or 'UNAVAILABLE'))
        assert(same_context(a,context()),'Driver context changed before seat write')
        assert(read('Long',a.va+a.offset)==a.handling,'Vehicle handling pointer changed before seat write')
        table_ok(a,1)
        -- Mark ownership before calling out: even a rejected write may have changed memory.
        stage('seat-write: journal and remap the validated mounted-weapon row(s)')
        S.active=a;a.owned=true
        for _,row in ipairs(a.seat_order) do
            assert(same_context(a,context()),'Driver context changed before paired seat write')
            assert(read('Long',a.va+a.offset)==a.handling,'Handling pointer changed before paired seat write')
            table_ok(a,'leased')
            assert(read('Int',row.address)==row.original,'Original seat row changed before write')
            row.attempted=true -- journal BEFORE calling out, including partial-write failure
            local result=call(M.WriteInt,row.address,row.desired)
            assert(result~=false and read('Int',row.address)==row.desired,
                'Driver weapon assignment not confirmed for row '..row.slot)
            table_ok(a,'leased')
        end
        table_ok(a,0)
        log('WEAPON_ROWS_REMAPPED',('%s; rows=%s; assignment 1->0; actual local ped still DRIVER; no ped-seat move')
            :format(a.profile.name,table.concat(a.profile.remap_slots,',')))
        assert(same_context(a,context()),'Driver context changed before weapon selection')
        -- Do not select in the seat-write frame. An invocation result and a
        -- later selected-weapon readback are recorded as different observations.
        if a.profile.native_pilot_input then request_hunter_parts(a) end
        queue_selection(a,i(H.time),i(H.frame),a.profile.native_pilot_input
            and 'paired rows remapped and vehicle-part reset requested; eligibility still unverified'
            or 'weapon-seat assignment read back as driver')
    end
    local function camera_input_permitted(c)
        if b(H.cam_rendering) then return true end
        -- The prior camera gate rejected ALL scripted cameras. Permit only the
        -- private paired Hunter camera, on the verified native-pilot firing path.
        -- All original menu/control/readiness checks below still apply.
        local a=S.active
        if not a or not a.profile.native_pilot_input or not a.selected_once
            or a.selection_pending or S.stopping or S.blocked then return false end
        if type(R.HunterGunCameraPermit)~='function' then return false end
        local ok,allowed=pcall(R.HunterGunCameraPermit,c)
        return ok and allowed==true
    end
    local function blocked_input(c)
        assert(R.GUI and type(R.GUI.IsOpen)=='function','Cherax menu-state API missing')
        local menu=R.GUI.IsOpen();assert(type(menu)=='boolean','Menu state unavailable')
        return menu or b(H.pause) or b(H.warning) or b(H.chat) or b(H.cutscene)
            or b(H.switching) or i(H.keyboard)==0 or not b(H.player_control,c.pid)
            or not camera_input_permitted(c)
    end
    local function attack_down(native_pilot)
        for _,control in ipairs(native_pilot and {70,114} or ATTACK) do
            if b(H.pressed,0,control) or b(H.disabled_pressed,0,control) then return true end
        end
        return false
    end
    local function verify_active(a)
        local c=context()
        assert(same_context(a,c),'Local driver / vehicle identity changed')
        assert(read('Long',a.va+a.offset)==a.handling,'Vehicle handling pointer changed')
        table_ok(a,0)
        return c
    end
    local function weapon_text(value)
        return value and ('0x%08X'):format(value) or 'UNAVAILABLE'
    end
    local function diagnostic_read(kind,hash,...)
        -- Optional diagnostics never grant selection or fire permission. A missing
        -- read is logged as unavailable, never replaced by a success-like value.
        local ok,value=pcall(kind,hash,...)
        return ok and tostring(value) or 'UNAVAILABLE'
    end
    local function cannon_ammo_context(a,label,from_weapon)
        if not a or not a.profile.native_pilot_input then return end
        local restricted=diagnostic_read(i,H.restricted_ammo,a.vehicle,a.profile.slot)
        local clip_now='UNAVAILABLE'
        local ok_clip,value=pcall(clip,a.vehicle)
        if ok_clip and value~=nil then clip_now=tostring(value) end
        local max_clip=diagnostic_read(i,H.max_clip,a.ped,a.profile.weapon,true)
        local reloading=diagnostic_read(b,H.reloading,a.vehicle,-1)
        local remaining=diagnostic_read(i,H.reload_remaining,a.vehicle,-1)
        local reload_time='UNAVAILABLE'
        local ok_rt,rt=pcall(call,N.InvokeFloat,H.reload_time,a.vehicle,-1)
        if ok_rt and finite(rt) then reload_time=('%.3f'):format(rt) end
        local detail=('label=%s from=%s selected=%s restrictedAmmo=%s clip=%s maxClip=%s reloading=%s reloadRemainingMs=%s reloadTime=%s; observationsOnly')
            :format(tostring(label),weapon_text(from_weapon),weapon_text(selected(a.ped)),restricted,clip_now,max_clip,reloading,remaining,reload_time)
        if R.Logger and type(R.Logger.LogInfo)=='function' then
            pcall(R.Logger.LogInfo,('['..ID..'] CANNON_AMMO_CONTEXT %s'):format(detail))
        end
    end
    local function observe_pilot_controller(a,now,label,force)
        if not a.profile.native_pilot_input then return end
        if not force and a.last_controller_at and now-a.last_controller_at<CONTROLLER_OBSERVATION_MS then return end
        a.last_controller_at=now
        -- These BOOLs describe different paths; none counts actual cannon discharges.
        -- In the accepted gunner baseline, turret-seat and ped-shooting flags were false
        -- while the recording showed firing. Do not turn any such flag into a gate.
        local under=diagnostic_read(b,H.mounted_under_driving,a.ped)
        local cannon=diagnostic_read(b,H.disabled,a.profile.weapon,a.vehicle,a.ped)
        local mg=diagnostic_read(b,H.disabled,a.profile.hashes[1],a.vehicle,a.ped)
        local driver_turret=diagnostic_read(b,H.turret_seat,a.vehicle,-1)
        local control=diagnostic_read(b,H.player_control,a.pid)
        local ok,current=pcall(selected,a.ped)
        verify_active(a)
        local detail=('phase=%s tMs=%d actualSeat=DRIVER selected=%s cannonDisabled=%s mgDisabled=%s mountedTaskUnderDriving=%s driverTurret=%s playerControlFlag=%s; observationsOnly; physicalFire=UNVERIFIED manualFlight=UNVERIFIED')
            :format(label,now,ok and weapon_text(current) or 'UNAVAILABLE',cannon,mg,under,driver_turret,control)
        -- Observation events must not replace the usable UI status with a telemetry line.
        if R.Logger and type(R.Logger.LogInfo)=='function' then
            pcall(R.Logger.LogInfo,('['..ID..'] PILOT_CONTROLLER_OBSERVATION %s'):format(detail))
        end
    end
    local function cannon_availability(now,frame,a)
        if a.profile.native_pilot_input then
            assert(a.hunter_hash_confirmed==true and selected(a.ped)==a.profile.weapon,
                'Hunter availability requires independently observed cannon selection first')
            verify_active(a)
        end
        local disabled=b(H.disabled,a.profile.weapon,a.vehicle,a.ped)
        verify_active(a)
        observe_pilot_controller(a,now,'availability',false)
        local lease=a.cannon_enable
        if lease then
            if lease.confirmed then
                assert(not disabled,'Cannon disabled again after scoped enable; no repeated enable attempt')
                return true
            end
            assert(now-lease.at<CANNON_ENABLE_CONFIRM_MS,
                'Scoped cannon enable was not confirmed in time AFTER cannon selection; no firing')
            if frame<=lease.frame then return false end
            if disabled then return false end
            lease.confirmed=true
            log('CANNON_ENABLED','Disabled=false observed after select-first on a later game frame; joint readiness and actual firing still unverified')
            observe_pilot_controller(a,now,'availability-confirmed',true)
            return true
        end
        if not disabled then return true end
        local turret=diagnostic_read(b,H.turret_seat,a.vehicle,-1)
        local ammo=diagnostic_read(i,H.restricted_ammo,a.vehicle,a.profile.slot)
        log('WEAPON_STATE',('weapon=%s disabled=true driverTurret=%s restrictedAmmo=%s; local ped only; cause unknown')
            :format(weapon_text(a.profile.weapon),turret,ammo))
        assert(a.model==hash('hunter') and a.profile.requires_cannon,
            'Mounted weapon is disabled; scoped enable trial is Hunter-only')
        assert(a.disabled_before_remap==true,
            'Cannon became disabled after seat remap; original state differs, so no enable trial')
        verify_active(a)
        -- Snapshot the exact observed BOOL before the one enable attempt.
        -- Ownership is recorded before calling out, since even a failed call
        -- can have changed the game. No other hash/vehicle/ped is enabled.
        assert(b(H.disabled,a.profile.weapon,a.vehicle,a.ped)==true,
            'Cannon disabled state changed before trial; retry with a fresh mapping')
        verify_active(a)
        lease={original=true,restore_required=true,confirmed=false,at=now,frame=frame,restore_writes=0}
        a.cannon_enable=lease
        S.stage='availability: one scoped local Hunter cannon enable AFTER selection'
        v(H.set_disabled,false,a.profile.weapon,a.vehicle,a.ped)
        verify_active(a)
        local after=b(H.disabled,a.profile.weapon,a.vehicle,a.ped)
        verify_active(a)
        log('CANNON_ENABLE_REQUEST',('order=select-first disabledBefore=true immediateAfter=%s; cannon hash already observed; wait for a later frame; no firing')
            :format(tostring(after)))
        return false
    end
    local function hunter_selection_step(now,frame,a)
        assert(now<a.selection_deadline,
            ('Hunter select-first selection timed out; phase=%s requests=%d lastReturn=%s; no firing')
            :format(tostring(a.hunter_phase),a.selection_requests,tostring(a.last_select_result)))
        if frame<=a.selection_frame or now-a.selection_at<SELECTION_SETTLE_MS then return false end
        verify_active(a)
        observe_pilot_controller(a,now,a.hunter_phase or 'select-first',false)
        local current=selected(a.ped)
        verify_active(a)
        if a.hunter_phase=='select-first' then
            S.stage='select-first: observe or request cannon BEFORE availability gate'
            if current==a.profile.weapon and frame~=a.last_request_frame then
                if a.readback_frame~=frame then
                    a.readback_streak=a.readback_streak+1;a.readback_frame=frame
                end
                if a.readback_streak<2 then
                    log('VERIFYING_CANNON_HASH',('selected=%s frame=%d; first independent frame; enable/fire withheld')
                        :format(weapon_text(current),frame))
                    return false
                end
                a.hunter_hash_confirmed=true;a.hunter_phase='availability-after-selection'
                log('CANNON_SELECTED_FIRST',
                    ('selected=%s observed on two distinct game frames; requests=%d lastReturn=%s; disabled-state check follows, no firing')
                    :format(weapon_text(current),a.selection_requests,tostring(a.last_select_result)))
            else
                a.readback_streak=0;a.readback_frame=nil
                if now<a.next_selection_request or a.selection_requests>=SELECTION_MAX_REQUESTS
                    or frame==a.last_request_frame then return false end
                verify_active(a)
                local before_disabled=b(H.disabled,a.profile.weapon,a.vehicle,a.ped)
                verify_active(a)
                -- Experimental ordering, not an enabled-state bypass for firing:
                -- this is only the existing native selection request, held fire
                -- is suppressed by Tick, and no controller/task native is called.
                a.selection_attempted=true;a.selection_restored=false
                a.selection_requests=a.selection_requests+1;a.last_request_frame=frame
                a.next_selection_request=now+SELECTION_RETRY_MS
                local accepted=b(H.select,a.ped,a.profile.weapon)
                a.last_select_result=accepted
                verify_active(a)
                local after=selected(a.ped)
                local after_disabled=b(H.disabled,a.profile.weapon,a.vehicle,a.ped)
                verify_active(a)
                log('SELECT_FIRST_ATTEMPT',
                    ('attempt=%d/%d elapsedMs=%d frame=%d return=%s before=%s after=%s disabledBefore=%s disabledAfter=%s; enableRequests=0-in-this-phase; fire withheld')
                    :format(a.selection_requests,SELECTION_MAX_REQUESTS,now-a.selection_at,frame,
                        tostring(accepted),weapon_text(current),weapon_text(after),
                        tostring(before_disabled),tostring(after_disabled)))
                -- Neither BOOL acceptance nor immediate readback is readiness.
                -- Require two later, distinct frames before any enable request.
                return false
            end
        end
        assert(a.hunter_phase=='availability-after-selection' and a.hunter_hash_confirmed,
            'Unexpected Hunter activation phase')
        assert(selected(a.ped)==a.profile.weapon,
            'Cannon selection was lost before availability completed; no repeated selection/enable')
        verify_active(a)
        S.stage='availability-after-selection: confirm cannon state without task takeover'
        if not cannon_availability(now,frame,a) then
            a.ready_streak=0;a.ready_frame=nil
            return false
        end
        local observed=selected(a.ped)
        local disabled=b(H.disabled,a.profile.weapon,a.vehicle,a.ped)
        verify_active(a)
        assert(observed==a.profile.weapon and disabled==false,
            'Cannon selected/enabled state changed before readiness; no firing')
        -- The frame of an explicit enable/selection write never counts as a
        -- settled joint readback. No new request is made between the two samples.
        if frame==a.last_request_frame or (a.cannon_enable and frame<=a.cannon_enable.frame) then return false end
        if a.ready_frame~=frame then
            a.ready_streak=a.ready_streak+1;a.ready_frame=frame
        end
        if a.ready_streak<2 then
            log('VERIFYING_CANNON_READY','Cannon selected AND disabled=false; awaiting a second distinct game frame; fire withheld')
            return false
        end
        a.selection_pending=false;a.selected_once=true;a.fire_armed=false;a.hunter_phase='ready'
        a.last_selected_weapon=a.profile.weapon;a.current_cannon_ready=true;a.cycle_rearm=nil
        observe_pilot_controller(a,now,'select-first-ready',true)
        -- Final observation after diagnostics; they never grant permission.
        assert(selected(a.ped)==a.profile.weapon and not b(H.disabled,a.profile.weapon,a.vehicle,a.ped),
            'Cannon state changed at final readiness observation')
        verify_active(a)
        log('SELECTION_READY',
            ('%s; order=select-first selected=%s AND disabled=false on two game frames; requests=%d lastReturn=%s elapsedMs=%d; release fire before native-input test')
            :format(a.profile.name,weapon_text(a.profile.weapon),a.selection_requests,
                tostring(a.last_select_result),now-a.selection_at))
        return true
    end
    local function selection_step(now,frame,a)
        if not a.selection_pending then return true end
        if a.profile.native_pilot_input then return hunter_selection_step(now,frame,a) end
        -- Deadline is checked before accepting a late readback or making a request.
        assert(now<a.selection_deadline,('Pilot/driver weapon selection timed out; requests=%d lastReturn=%s; no firing proven')
            :format(a.selection_requests,tostring(a.last_select_result)))
        if frame<=a.selection_frame or now-a.selection_at<SELECTION_SETTLE_MS then return false end
        S.stage='availability: inspect mounted weapon'
        if not cannon_availability(now,frame,a) then return false end
        S.stage='selection: independent weapon readback'
        local current=selected(a.ped)
        verify_active(a)
        if current==a.profile.weapon then
            if a.readback_frame~=frame then
                a.readback_streak=a.readback_streak+1;a.readback_frame=frame
            end
            -- Two distinct frames, without another selection request in between.
            if a.readback_streak>=2 then
                a.selection_pending=false;a.selected_once=true;a.fire_armed=false
                observe_pilot_controller(a,now,'selection-verified',true)
                log('SELECTION_READY',('%s; selected=%s on two game frames; requests=%d lastReturn=%s elapsedMs=%d; release fire before testing')
                    :format(a.profile.name,weapon_text(current),a.selection_requests,
                        tostring(a.last_select_result),now-a.selection_at))
                return true
            end
            log('VERIFYING_SELECTION',('selected=%s frame=%d; waiting for a second game frame; no firing')
                :format(weapon_text(current),frame))
            return false
        end
        a.readback_streak=0;a.readback_frame=nil
        if now<a.next_selection_request or a.selection_requests>=SELECTION_MAX_REQUESTS
            or frame==a.last_request_frame then return false end
        S.stage='selection: validate request context'
        verify_active(a)
        local disabled=b(H.disabled,a.profile.weapon,a.vehicle,a.ped)
        local turret=diagnostic_read(b,H.turret_seat,a.vehicle,-1)
        local ammo=diagnostic_read(i,H.restricted_ammo,a.vehicle,a.profile.slot)
        log('SELECTION_CONTEXT',('disabled=%s driverTurret=%s restrictedAmmo=%s'):format(tostring(disabled),turret,ammo))
        observe_pilot_controller(a,now,'selection-request',true)
        assert(not disabled,'Mounted weapon disabled before request; no repeat enable')
        -- Revalidate after diagnostic calls, before the only selection operation.
        verify_active(a)
        S.stage='selection: request actual passenger weapon from driver'
        a.selection_attempted=true
        a.selection_requests=a.selection_requests+1;a.last_request_frame=frame
        a.next_selection_request=now+SELECTION_RETRY_MS
        local accepted=b(H.select,a.ped,a.profile.weapon)
        a.last_select_result=accepted
        verify_active(a)
        local after=selected(a.ped)
        verify_active(a)
        log('SELECT_ATTEMPT',('attempt=%d/%d elapsedMs=%d frame=%d return=%s before=%s after=%s disabled=%s driverTurret=%s restrictedAmmo=%s; no firing')
            :format(a.selection_requests,SELECTION_MAX_REQUESTS,now-a.selection_at,frame,
                tostring(accepted),weapon_text(current),weapon_text(after),tostring(disabled),turret,ammo))
        -- Even accepted=true with immediate matching output is not readiness.
        -- The next two game frames must independently confirm the selected hash.
        return false
    end
    local function weapon_cycle_input_down()
        for _,action in ipairs(WEAPON_CYCLE_ACTIONS) do
            if b(H.pressed,0,action) or b(H.disabled_pressed,0,action) then return true end
        end
        return false
    end
    local function navigation_step(now,frame,a,c)
        local n=a.navigation
        assert(n and n.active==true,'Navigation state unavailable')
        finish_burst('Hunter navigation handoff');S.last_input=false;a.fire_armed=false
        if weapon_cycle_input_down() then n.last_cycle_input_at=now end
        local current=selected(c.ped)
        if current~=n.last_observed_weapon then
            n.last_observed_weapon=current
            local user_cycle=n.last_cycle_input_at~=nil and now>=n.last_cycle_input_at and now-n.last_cycle_input_at<=400
            if current~=a.profile.weapon and user_cycle then
                n.weapon_changed=true;n.preserved_weapon=current
                log('NAVIGATION_WEAPON_OBSERVED','Native Hunter weapon changed to '..weapon_text(current)..' within 400 ms of weapon-cycle input; navigation will preserve it')
            elseif current~=a.profile.weapon then
                log('NAVIGATION_STOCK_WEAPON_OBSERVED','Hunter mode changed selected weapon without nearby cycle input; bounded cannon return remains eligible')
            end
        end
        a.current_cannon_ready=(current==a.profile.weapon and not b(H.disabled,a.profile.weapon,c.vehicle,c.ped))
        a.last_selected_weapon=current
        if not n.resume_requested then return false end
        assert(now<n.deadline,'Hunter navigation cannon return timed out; Restore & Stop before retry')
        verify_active(a)
        if n.weapon_changed and current~=a.profile.weapon then
            n.active=false;n.resume_requested=false
            a.fire_armed=false;a.current_cannon_ready=false;a.cycle_rearm=nil
            log('NAVIGATION_WEAPON_PRESERVED','Keeping '..weapon_text(current)..' selected; native weapon cycle owns selection. Cycle back to cannon normally to reopen scope.')
            return true
        end
        if current~=a.profile.weapon then
            n.ready_streak=0;n.ready_frame=nil
            if now>=n.next_request and n.select_writes<NAVIGATION_MAX_WRITES and frame~=n.last_write_frame then
                verify_active(a)
                n.select_writes=n.select_writes+1;n.last_write_frame=frame;n.next_request=now+NAVIGATION_RETRY_MS
                local accepted=b(H.select,c.ped,a.profile.weapon)
                verify_active(a)
                log('NAVIGATION_SELECT_REQUEST',('attempt=%d/%d return=%s before=%s after=%s; no part reset')
                    :format(n.select_writes,NAVIGATION_MAX_WRITES,tostring(accepted),weapon_text(current),weapon_text(selected(c.ped))))
            end
            return false
        end
        local disabled=b(H.disabled,a.profile.weapon,c.vehicle,c.ped)
        verify_active(a)
        if disabled then
            n.ready_streak=0;n.ready_frame=nil
            if now>=n.next_request and n.enable_writes<NAVIGATION_MAX_WRITES and frame~=n.last_write_frame then
                verify_active(a)
                n.enable_writes=n.enable_writes+1;n.last_write_frame=frame;n.next_request=now+NAVIGATION_RETRY_MS
                v(H.set_disabled,false,a.profile.weapon,c.vehicle,c.ped)
                verify_active(a)
                log('NAVIGATION_ENABLE_REQUEST',('attempt=%d/%d immediateDisabled=%s; same Hunter/ped/cannon; no part reset')
                    :format(n.enable_writes,NAVIGATION_MAX_WRITES,tostring(b(H.disabled,a.profile.weapon,c.vehicle,c.ped))))
            end
            return false
        end
        -- If the user cycled away and back to cannon WHILE the stock Hunter mode
        -- still owned the view, refresh the already-selected cannon once here too.
        -- A direct NAVIGATION_SELECT_REQUEST already refreshes controller state and
        -- does not need this extra same-hash call.
        if n.weapon_changed and (n.select_writes or 0)==0 and not n.controller_refresh_submitted then
            if frame==n.last_write_frame then return false end
            cannon_ammo_context(a,'navigation-return-before-refresh',n.entry_weapon)
            verify_active(a)
            local accepted=b(H.select,c.ped,a.profile.weapon)
            n.controller_refresh_submitted=true;n.controller_refresh_frame=frame;n.last_write_frame=frame
            verify_active(a)
            assert(selected(c.ped)==a.profile.weapon,'Navigation same-hash cannon refresh changed selection')
            log('NAVIGATION_CONTROLLER_REFRESH',('return=%s; user naturally cycled back to cannon while stock mode owned view; no forced navigation/repair/ammo write')
                :format(tostring(accepted)))
            return false
        end
        if n.controller_refresh_submitted and frame<=n.controller_refresh_frame then return false end
        if frame==n.last_write_frame then return false end
        if n.ready_frame~=frame then n.ready_frame=frame;n.ready_streak=n.ready_streak+1 end
        if n.ready_streak<2 then
            log('NAVIGATION_VERIFYING','Cannon selected and enabled after stock Hunter mode; waiting for second distinct frame')
            return false
        end
        if n.controller_refresh_submitted then cannon_ammo_context(a,'navigation-return-ready',n.entry_weapon) end
        n.active=false;n.resume_requested=false
        a.selected_once=true;a.selection_pending=false;a.fire_armed=false;a.hunter_phase='ready'
        a.last_selected_weapon=a.profile.weapon;a.current_cannon_ready=true;a.cycle_rearm=nil
        log('NAVIGATION_READY','Pilot cannon selected/enabled on two later frames; camera may reopen automatically; no part reset')
        return true
    end
    local function direction_target()
        local cx,cy,cz=call(N.InvokeV3,H.cam_coord)
        local rx,ry,rz=call(N.InvokeV3,H.cam_rot,2)
        assert(finite(cx) and finite(cy) and finite(cz) and finite(rx) and finite(ry) and finite(rz),'Camera vectors unavailable')
        local pitch,yaw=math.rad(rx),math.rad(rz)
        local cp=math.cos(pitch)
        return cx-math.sin(yaw)*cp*2000,cy+math.cos(yaw)*cp*2000,cz+math.sin(pitch)*2000
    end
    local function cycle_rearm_step(now,frame,a,c,from_weapon)
        local r=a.cycle_rearm
        if not r then
            r={started_at=now,deadline=now+CYCLE_REARM_TIMEOUT_MS,next_request=now,
                enable_writes=0,last_write_frame=nil,ready_streak=0,ready_frame=nil,
                from_weapon=from_weapon,refresh_submitted=false,refresh_frame=nil,refresh_result=nil}
            a.cycle_rearm=r;a.current_cannon_ready=false;a.fire_armed=false
            cannon_ammo_context(a,'natural-return-before-refresh',from_weapon)
            log('CANNON_CYCLE_RETURN','Cannon was naturally selected through native weapon cycling; availability will be stabilized, then one same-hash controller refresh will run before readiness; no part reset')
        elseif r.from_weapon==nil and from_weapon~=nil then
            r.from_weapon=from_weapon
        end
        assert(now<r.deadline,'Natural cannon-cycle rearm timed out; cannon remains selected but availability/controller state did not stabilize')
        local current=selected(c.ped)
        if current~=a.profile.weapon then a.cycle_rearm=nil;a.current_cannon_ready=false;return false end
        local disabled=b(H.disabled,a.profile.weapon,c.vehicle,c.ped)
        if disabled then
            r.ready_streak=0;r.ready_frame=nil
            if now>=r.next_request and r.enable_writes<CYCLE_REARM_MAX_WRITES and frame~=r.last_write_frame then
                verify_active(a)
                r.enable_writes=r.enable_writes+1;r.last_write_frame=frame;r.next_request=now+CYCLE_REARM_RETRY_MS
                v(H.set_disabled,false,a.profile.weapon,c.vehicle,c.ped)
                verify_active(a)
                log('CANNON_CYCLE_ENABLE',('attempt=%d/%d immediateDisabled=%s; natural cannon selection retained; controller refresh waits until availability is enabled; no navigation/repair')
                    :format(r.enable_writes,CYCLE_REARM_MAX_WRITES,tostring(b(H.disabled,a.profile.weapon,c.vehicle,c.ped))))
            end
            return false
        end
        -- Cannon selection can precede the driver's clip/reload state, especially
        -- after barrage. Refresh the same hash once after cannon is selected and
        -- enabled; abort if the player cycles away. No repair or ammo write is used.
        if not r.refresh_submitted then
            if frame==r.last_write_frame then return false end
            verify_active(a)
            assert(selected(c.ped)==a.profile.weapon and not b(H.disabled,a.profile.weapon,c.vehicle,c.ped),
                'Natural cannon state changed before controller refresh')
            local accepted=b(H.select,c.ped,a.profile.weapon)
            r.refresh_submitted=true;r.refresh_frame=frame;r.refresh_result=accepted;r.last_write_frame=frame
            verify_active(a)
            local after=selected(c.ped)
            assert(after==a.profile.weapon,'Same-hash cannon refresh changed the selected weapon')
            log('CANNON_CONTROLLER_REFRESH',('from=%s return=%s selected=%s; same-hash refresh after enabled state only; no weapon navigation, part reset, ammo write or firing command')
                :format(weapon_text(r.from_weapon),tostring(accepted),weapon_text(after)))
            return false
        end
        if frame<=r.refresh_frame or frame==r.last_write_frame then return false end
        current=selected(c.ped)
        if current~=a.profile.weapon then a.cycle_rearm=nil;a.current_cannon_ready=false;return false end
        if b(H.disabled,a.profile.weapon,c.vehicle,c.ped) then
            r.ready_streak=0;r.ready_frame=nil
            return false
        end
        if r.ready_frame~=frame then r.ready_frame=frame;r.ready_streak=r.ready_streak+1 end
        if r.ready_streak<2 then
            log('CANNON_CYCLE_VERIFYING','Natural cannon selection/controller refresh enabled; waiting for second distinct frame before firing/scope')
            return false
        end
        cannon_ammo_context(a,'natural-return-ready',r.from_weapon)
        a.cycle_rearm=nil;a.current_cannon_ready=true;a.fire_armed=false
        log('CANNON_CYCLE_READY','Natural weapon cycle returned to cannon; same-hash controller refresh plus enabled state verified on later frames; scope may reopen automatically')
        return true
    end
    local function attack_control_snapshot()
        local parts={}
        for _,control in ipairs(ATTACK) do
            local ok_p,p=pcall(b,H.pressed,0,control)
            local ok_d,d=pcall(b,H.disabled_pressed,0,control)
            parts[#parts+1]=('%d:p=%s,d=%s'):format(control,ok_p and tostring(p) or 'UNAVAILABLE',ok_d and tostring(d) or 'UNAVAILABLE')
        end
        return table.concat(parts,';')
    end
    local function dead_trigger_observation(now,a,c,burst,ammo,reloading,remaining,label)
        if burst.dead_last_log and now-burst.dead_last_log<DEAD_TRIGGER_OBSERVE_MS then return end
        burst.dead_last_log=now
        local under=diagnostic_read(b,H.mounted_under_driving,a.ped)
        local turret=diagnostic_read(b,H.turret_seat,a.vehicle,-1)
        local control=diagnostic_read(b,H.player_control,a.pid)
        local detail=('phase=%s heldMs=%d selected=%s disabled=%s clip=%s clipStart=%s reloading=%s reloadRemainingMs=%s mountedTaskUnderDriving=%s driverTurret=%s playerControlFlag=%s attack=[%s] resyncSubmitted=%s; observationsOnly')
            :format(tostring(label),math.max(0,now-(burst.started_at or now)),weapon_text(selected(c.ped)),
                tostring(b(H.disabled,a.profile.weapon,c.vehicle,c.ped)),tostring(ammo),tostring(burst.clip_before),
                tostring(reloading),tostring(remaining),under,turret,control,attack_control_snapshot(),
                tostring(burst.dead_resync_submitted==true))
        if R.Logger and type(R.Logger.LogInfo)=='function' then
            pcall(R.Logger.LogInfo,('['..ID..'] DEAD_TRIGGER_OBSERVATION %s'):format(detail))
        end
    end
    local function maybe_dead_trigger_resync(now,frame,a,c,burst,ammo,reload_ok,reloading,remaining_ok,remaining)
        if burst.dead_resync_submitted then return false end
        if burst.shooting or burst.clip_decreased then return false end
        if not burst.started_at or now-burst.started_at<DEAD_TRIGGER_RESYNC_MS then return false end
        if burst.clip_before==nil or ammo==nil or ammo~=burst.clip_before then return false end
        if not reload_ok or reloading~=false then return false end
        if not remaining_ok or type(remaining)~='number' or remaining>0 then return false end
        -- The physical trigger must still be held. Re-read selected/disabled state
        -- immediately before the one experimental same-hash refresh.
        if not attack_down(true) then return false end
        verify_active(a)
        assert(selected(c.ped)==a.profile.weapon,'Dead-trigger refresh requires cannon still selected')
        assert(not b(H.disabled,a.profile.weapon,c.vehicle,c.ped),'Dead-trigger refresh requires cannon still enabled')
        local accepted=b(H.select,c.ped,a.profile.weapon)
        burst.dead_resync_submitted=true
        burst.dead_resync_result=accepted
        burst.dead_resync_at=now
        burst.dead_resync_frame=frame
        verify_active(a)
        assert(selected(c.ped)==a.profile.weapon,'Dead-trigger same-hash refresh changed selected weapon')
        assert(not b(H.disabled,a.profile.weapon,c.vehicle,c.ped),'Dead-trigger same-hash refresh disabled cannon')
        log('DEAD_TRIGGER_RESYNC',('heldMs=%d clip=%s reload=false reloadRemainingMs=%s return=%s; ONE same-hash cannon refresh for this trigger hold; no weapon navigation, ammo/fire-rate write, part reset or firing command')
            :format(now-burst.started_at,tostring(ammo),tostring(remaining),tostring(accepted)))
        return true
    end
    local function native_pilot_firing(now,a,c)
        local current=selected(c.ped)
        local frame=i(H.frame)
        observe_pilot_controller(a,now,'pilot-input',false)
        if current~=a.profile.weapon then
            finish_burst('native weapon cycle / cannon no longer selected')
            S.last_input=false;a.fire_armed=false;a.current_cannon_ready=false;a.cycle_rearm=nil
            if a.last_selected_weapon~=current then
                log('OTHER_WEAPON','Normal pilot weapon selected; native controls remain available. Cycle back to cannon normally; no menu action is required.')
            end
            a.last_selected_weapon=current
            return
        end
        assert(a.selected_once and not a.selection_pending,'Cannon selection has not been independently observed')
        if a.last_selected_weapon~=nil and a.last_selected_weapon~=a.profile.weapon then
            local prior_weapon=a.last_selected_weapon
            a.last_selected_weapon=a.profile.weapon
            if not cycle_rearm_step(now,frame,a,c,prior_weapon) then
                for _,control in ipairs(ATTACK) do v(H.disable_control,0,control,true) end
                return
            end
        elseif a.cycle_rearm then
            if not cycle_rearm_step(now,frame,a,c) then
                for _,control in ipairs(ATTACK) do v(H.disable_control,0,control,true) end
                return
            end
        else
            assert(not b(H.disabled,a.profile.weapon,c.vehicle,c.ped),
                'Pilot cannon disabled while continuously selected; no arbitrary re-enable or controller takeover')
            a.current_cannon_ready=true
        end
        if blocked_input(c) then
            finish_burst('menu / gameplay input unavailable');S.last_input=false;a.fire_armed=false
            -- Prevent held fire leaking through activation/menu transitions; no flight controls.
            for _,control in ipairs(ATTACK) do v(H.disable_control,0,control,true) end
            return
        end
        local down=attack_down(true)
        if not a.fire_armed then
            S.last_input=false
            if down then
                for _,control in ipairs(ATTACK) do v(H.disable_control,0,control,true) end
                log('RELEASE_FIRE','Release mounted-fire controls once; native pilot input will then pass through')
            else
                a.fire_armed=true
                log('PILOT_NATIVE_INPUT','Cannon hash observed; native pilot fire controls now pass through. No scripted shot, forced task or gunner-camera takeover. Physical firing/manual flight still require visual confirmation.')
            end
            return
        end
        -- NO DISABLE_CONTROL_ACTION or SET_VEHICLE_SHOOT_AT_TARGET below this point.
        -- Let the real driver's normal game controller process normal fire input.
        if not down then
            finish_burst('native trigger released');S.last_input=false
            return
        end
        if not S.last_input then
            local ok,ammo=pcall(clip,c.vehicle)
            local ok_reload,reload=pcall(b,H.reloading,c.vehicle,-1)
            local ok_remaining,remaining=pcall(i,H.reload_remaining,c.vehicle,-1)
            local reload_start=nil;if ok_reload then reload_start=reload end
            local remaining_start=nil;if ok_remaining then remaining_start=remaining end
            S.burst={route='native-pilot-input',commands=0,trigger_frames=0,shooting=false,
                clip_decreased=false,clip_before=ok and ammo or nil,clip_last=ok and ammo or nil,
                reload_at_start=reload_start,reload_remaining_at_start=remaining_start,
                started_at=now,started_frame=frame,dead_last_log=nil,
                dead_resync_submitted=false,dead_resync_result=nil,dead_resync_at=nil}
            log('PILOT_TRIGGER_HELD','Normal mounted-fire input observed in the actual pilot seat; commands=0; this is not proof of a shot')
        end
        S.last_input=true
        if S.burst then
            local burst=S.burst
            burst.trigger_frames=burst.trigger_frames+1
            local ok_shooting,shooting=pcall(b,H.shooting,c.ped)
            if ok_shooting and shooting then burst.shooting=true end
            local ok_clip,ammo=pcall(clip,c.vehicle)
            if ok_clip and ammo~=nil then
                burst.clip_last=ammo
                if burst.clip_before and ammo<burst.clip_before then burst.clip_decreased=true end
            end
            local ok_reload,reloading=pcall(b,H.reloading,c.vehicle,-1)
            local ok_remaining,remaining=pcall(i,H.reload_remaining,c.vehicle,-1)
            if not burst.shooting and not burst.clip_decreased then
                dead_trigger_observation(now,a,c,burst,ok_clip and ammo or nil,
                    ok_reload and tostring(reloading) or 'UNAVAILABLE',
                    ok_remaining and tostring(remaining) or 'UNAVAILABLE','held-no-fire')
                maybe_dead_trigger_resync(now,frame,a,c,burst,ok_clip and ammo or nil,
                    ok_reload,reloading,ok_remaining,remaining)
            end
        end
    end
    local function firing(now,a,c)
        if a.profile.native_pilot_input then return native_pilot_firing(now,a,c) end
        if a.cannon_enable then
            assert(not b(H.disabled,a.profile.weapon,c.vehicle,c.ped),
                'Cannon disabled again after scoped enable; no repeated enable attempt')
        end
        local current=selected(c.ped)
        if current~=a.profile.weapon then
            finish_burst('different weapon selected');S.last_input=false
            a.fire_armed=false
            if a.selected_once then log('OTHER_WEAPON','Normal driver weapon selected; use Select Passenger Weapon to return') end
            return
        end
        assert(a.selected_once and not a.selection_pending,'Selection has not been independently verified')
        if blocked_input(c) then
            finish_burst('input blocked');S.last_input=false;a.fire_armed=false;return
        end
        if a.profile.name=='Chernobog' and not b(H.deploy,c.vehicle) then
            finish_burst('stabilizers not deployed');S.last_input=false;a.fire_armed=false
            log('DEPLOY_REQUIRED','Stay in driver seat and deploy the Chernobog stabilizers using the normal control')
            return
        end
        if b(H.disabled,a.profile.weapon,c.vehicle,c.ped) then
            assert(not a.cannon_enable,'Cannon disabled again after scoped enable; no repeated enable attempt')
            finish_burst('weapon disabled');S.last_input=false;a.fire_armed=false
            log('WEAPON_DISABLED','Game reports this mounted weapon disabled; no override');return
        end
        local down=attack_down()
        -- Only suppress fire while routing this selected weapon; never driving or flight controls.
        for _,control in ipairs(ATTACK) do v(H.disable_control,0,control,true) end
        if not a.fire_armed then
            S.last_input=false
            if down then
                log('RELEASE_FIRE','Selection verified; release mounted-fire controls before a new test burst')
            else
                a.fire_armed=true
                log('SELECTED','Selection verified and fire released; normal fire aims at the gameplay camera; physical firing UNVERIFIED')
            end
            return
        end
        if S.burst then
            local ok,shooting=pcall(b,H.shooting,c.ped)
            if ok and shooting then S.burst.shooting=true end
            local ok_clip,ammo=pcall(clip,c.vehicle)
            if ok_clip and ammo and S.burst.clip_before and ammo<S.burst.clip_before then S.burst.clip_decreased=true end
        end
        if not down then
            finish_burst('released');S.last_input=false
            log('SELECTED','Passenger weapon selected; normal fire input aims at the gameplay-camera direction; firing not yet visually verified')
            return
        end
        if not S.last_input then
            local ok,ammo=pcall(clip,c.vehicle)
            S.burst={commands=0,shooting=false,clip_decreased=false,clip_before=ok and ammo or nil}
        end
        S.last_input=true
        if now-S.last_command<a.profile.interval then return end
        local x,y,z=direction_target()
        assert(same_context(a,context()),'Driver context changed immediately before firing')
        table_ok(a,0)
        assert(selected(c.ped)==a.profile.weapon,'Selected weapon changed before command')
        if a.profile.name=='Chernobog' then assert(b(H.deploy,c.vehicle),'Chernobog undeployed before command') end
        assert(not b(H.disabled,a.profile.weapon,c.vehicle,c.ped),'Mounted weapon disabled immediately before firing; no override')
        verify_active(a)
        if S.commands==0 then log('FIRE_REQUEST_BEGIN','Calling actual mounted-weapon native; live result unverified') end
        v(H.shoot,c.ped,0,x,y,z)
        S.last_command=now;S.commands=S.commands+1;S.burst.commands=S.burst.commands+1
        -- Accepted void invocation is explicitly NOT reported as a successful shot.
        log('COMMAND_SUBMITTED',a.profile.name..'; real mounted-weapon request; physical firing/aim/homing UNVERIFIED')
    end
    function API.Tick(enabled)
        if S.shutdown then return end
        if S.stopping then
            S.trace=false;S.enabled=false;S.blocked=true
            S.check_requested=false;S.mapping_requested=false;S.select_requested=false
            local clock_ok,clock=pcall(i,H.time)
            local frame_ok,frame=pcall(i,H.frame)
            if clock_ok then S.last_now=clock end
            if frame_ok then S.last_frame=frame end
            local clean=release(S.stopping,clock_ok and frame_ok)
            if clean and not enabled then S.blocked=false end
            -- An ON request during cleanup is never replayed automatically.
            return
        end
        if enabled and not S.enabled and not S.blocked then
            S.rapid_checked=false;S.rapid_checked_at=nil
            S.trace=true;S.epoch=S.epoch+1;stage('enable: timer and preflight')
        end
        if S.check_requested and not enabled and not S.active then
            S.check_requested=false;S.trace=true;S.epoch=S.epoch+1
            stage('check: context only, no raw memory or weapon changes')
            local ok,c=pcall(context)
            S.trace=false
            if ok then
                log('CONTEXT_OK',c.profile.name..'; local driver, empty gunner seat; rapidFire='..
                    tostring(S.rapid_state)..'; no mapping/selection/fire attempted')
            else log('CHECK_BLOCKED',tostring(c)..'; lastStage='..S.stage) end
            return
        end
        S.check_requested=false
        if S.mapping_requested and not enabled and not S.active then
            S.mapping_requested=false;S.mapping_proof=nil;S.trace=true;S.epoch=S.epoch+1
            stage('check-mapping: read only; no allocation, selection or fire')
            local ok,a=pcall(function()
                local mapped=map(context())
                assert(same_context(mapped,context()),'Driver context changed during mapping check')
                assert(read('Long',mapped.va+mapped.offset)==mapped.handling,
                    'Vehicle handling pointer changed during mapping check')
                table_ok(mapped,1)
                if mapped.img.requires_mapping then
                    mapped.checked_at=i(H.time)
                    assert(integer(mapped.checked_at,0,4294967295),'Mapping check clock unavailable')
                end
                return mapped
            end)
            S.trace=false
            if ok then
                S.blocked=false;S.enabled=false -- explicit read-only revalidation completed while OFF
                if a.img.requires_mapping then S.mapping_proof=a end
                local hashes,seats={},{}
                for j=1,6 do hashes[j]=('0x%08X'):format(a.profile.hashes[j]);seats[j]=tostring(a.profile.seats[j]) end
                log('MAPPING_DETAIL',('profile=%s TimeDateStamp=%d SizeOfImage=%d siteRVA=0x%X subhandlingIndex=%d count=%d capacity=%d hashes=[%s] seats=[%s] turretSpeed=%s')
                    :format(a.img.tag,a.img.timestamp,a.img.size,a.mapping_site-a.img.base,a.index,a.count,a.capacity,
                        table.concat(hashes,','),table.concat(seats,','),tostring(a.profile.turret_speed)))
                log('MAPPING_OK',('%s; Enhanced offset=0x%X; weaponSlot=%d; seat=1; no writes/selection/fire; weapon usability UNVERIFIED%s')
                    :format(a.profile.name,a.offset,a.profile.slot,a.img.requires_mapping
                        and (a.profile.automatic_mapping and '; optional for Hunter: activation validates automatically'
                            or '; manual Enable permitted for this same mapping within 60s; fresh validation still required') or ''))
            else log('MAPPING_BLOCKED',tostring(a)..'; lastStage='..S.stage..'; no writes made') end
            return
        end
        S.mapping_requested=false
        local now_ok,now=pcall(i,H.time)
        if not now_ok then S.blocked=true;release('timer unavailable',false);return end
        local frame_ok,frame=pcall(i,H.frame)
        if not frame_ok or not integer(frame,0,4294967295) then
            S.blocked=true;release('frame counter unavailable',true);return
        end
        if (S.active and S.last_frame and frame<S.last_frame)
            or (S.last_now and (now<S.last_now or (S.active and now-S.last_now>750))) then
            S.mapping_proof=nil;S.blocked=true;release('clock discontinuity / long frame gap',true)
        end
        S.last_now=now;S.last_frame=frame
        if not enabled then
            S.enabled=false
            local clean=release('disabled',true)
            if clean then S.blocked=false end
            S.trace=false
            return
        end
        if S.stopping then release(S.stopping,true);return end
        if S.blocked then return end
        S.enabled=true
        local ok,err=pcall(function()
            if not S.active then open(now,frame);S.trace=false end
            local a=S.active;local c=verify_active(a)
            retry_lifecycle_capture(a,now)
            if a.navigation and a.navigation.active then
                navigation_step(now,frame,a,c)
                return
            end
            if S.select_requested then
                S.select_requested=false
                if not a.selection_pending then queue_selection(a,now,frame,'manual reselect') end
                -- Repeated button presses cannot extend a pending deadline.
            end
            local was_pending=a.selection_pending==true
            if a.selection_pending then
                -- Keep activation/held fire out of the selection experiment.
                for _,control in ipairs(ATTACK) do v(H.disable_control,0,control,true) end
            end
            if not selection_step(now,frame,a) then return end
            if was_pending then c=verify_active(a) end
            firing(now,a,c)
        end)
        if not ok then
            S.trace=false
            S.blocked=true
            err=tostring(err)..'; lastStage='..S.stage
            log('BLOCKED',tostring(err))
            local cleaned=release('blocked: '..tostring(err),true)
            if cleaned then log('BLOCKED',tostring(err)..'; toggle off before retry') end
        end
    end
    function API.BeginNavigation(reason)
        local a=S.active
        if not a or S.stopping or S.blocked or not a.profile.native_pilot_input
            or a.selection_pending or not a.selected_once then return false end
        if a.navigation and a.navigation.active then return true end
        finish_burst('Hunter navigation handoff');S.last_input=false;a.fire_armed=false
        local current=selected(a.ped)
        a.navigation={active=true,resume_requested=false,started_at=S.last_now or 0,
            deadline=nil,next_request=nil,last_write_frame=nil,select_writes=0,enable_writes=0,
            ready_streak=0,ready_frame=nil,reason=tostring(reason or 'Hunter E navigation'),
            entry_weapon=current,last_observed_weapon=current,weapon_changed=false,preserved_weapon=nil,last_cycle_input_at=nil}
        a.last_selected_weapon=current;a.current_cannon_ready=(current==a.profile.weapon and not b(H.disabled,a.profile.weapon,a.vehicle,a.ped))
        log('NAVIGATION_HANDOFF','Normal Hunter E controls may run; cannon remap stays leased and firing is withheld')
        return true
    end
    function API.RequestNavigationResume(reason)
        local a=S.active;local n=a and a.navigation
        if not n or n.active~=true then return false end
        if n.resume_requested then return true end
        local now=S.last_now or 0
        n.resume_requested=true;n.deadline=now+NAVIGATION_REARM_TIMEOUT_MS;n.next_request=now
        n.last_write_frame=nil;n.select_writes=0;n.enable_writes=0;n.ready_streak=0;n.ready_frame=nil
        log('NAVIGATION_RETURN_REQUESTED',tostring(reason or 'Stock Hunter mode closed')..'; bounded select/enable verification begins')
        return true
    end
    function API.SelectPassenger() S.select_requested=true end
    function API.RequestCheck() S.mapping_proof=nil;S.mapping_requested=false;S.check_requested=true end
    function API.RequestMappingCheck() S.mapping_proof=nil;S.check_requested=false;S.mapping_requested=true end
    function API.Cancel(reason)
        S.mapping_proof=nil;S.check_requested=false;S.mapping_requested=false
        if reason=='session changed' and S.active and S.active.lifecycle then
            S.active.lifecycle.session_changed=true;clear_absence(S.active.lifecycle)
        end
        S.blocked=true;S.stopping=reason or 'session/vehicle change'
    end
    function API.Close(reason,allow_natives)
        S.mapping_proof=nil;S.check_requested=false;S.mapping_requested=false
        S.enabled=false;S.blocked=true
        return release(reason or 'stop',allow_natives==true)
    end
    function API.Unload()
        S.mapping_proof=nil;S.shutdown=true
        local clean=release('script unload (memory cleanup only)',false)
        if S.buffer then pcall(M.Free,S.buffer);S.buffer=nil end
        if not clean then log('UNLOAD_UNRESOLVED','Cleanup was interrupted before verification/retirement completed. No clean-state claim; direct unload cannot run the deferred cleanup. Keep the log and do not stack prototypes on this unresolved instance.') end
    end
    function API.Snapshot()
        return {status=S.status,detail=S.detail,active=S.active~=nil,blocked=S.blocked,
            last_cleanup_outcome=S.last_cleanup_outcome,pending_logs_suppressed=S.pending_suppressed,
            baseline_recovery=S.active~=nil and S.active.baseline_recovery==true,
            lifecycle_identity_captured=S.active~=nil and S.active.lifecycle~=nil and S.active.lifecycle.captured==true,
            lifecycle_identity_source=S.active and S.active.lifecycle and S.active.lifecycle.source,
            lifecycle_raw_native=S.active and S.active.lifecycle and S.active.lifecycle.raw_native,
            lifecycle_capture_attempts=S.active and S.active.lifecycle and S.active.lifecycle.attempts or 0,
            cleanup_pilot_rebound=S.active~=nil and S.active.cleanup_subject~=nil,
            restore_pending=S.stopping~=nil,commands=S.commands,epoch=S.epoch,
            stage=S.stage,rapid_state=S.rapid_state,mapping_check_ready=S.mapping_proof~=nil,
            selection_pending=S.active~=nil and S.active.selection_pending==true,
            selection_requests=S.active and S.active.selection_requests or 0,
            selected_verified=S.active~=nil and S.active.selected_once==true,
            current_cannon_ready=S.active~=nil and S.active.current_cannon_ready==true,
            natural_cycle_rearm=S.active~=nil and S.active.cycle_rearm~=nil,
            fire_armed=S.active~=nil and S.active.fire_armed==true,
            cannon_enable_attempted=S.active~=nil and S.active.cannon_enable~=nil,
            cannon_enable_confirmed=S.active~=nil and S.active.cannon_enable~=nil and S.active.cannon_enable.confirmed==true,
            cannon_restore_pending=S.active~=nil and S.active.cannon_enable~=nil and S.active.cannon_enable.restore_required==true,
            native_pilot_input=S.active~=nil and S.active.profile.native_pilot_input==true,
            hunter_phase=S.active and S.active.hunter_phase or nil,
            cannon_hash_observed=S.active~=nil and S.active.hunter_hash_confirmed==true,
            selection_restore_pending=S.active~=nil and S.active.profile.native_pilot_input==true
                and S.active.selection_attempted==true and S.active.selection_restored~=true and S.active.selection_retired~=true,
            parts_refresh_attempted=S.active~=nil and S.active.parts_refresh~=nil,
            parts_restore_pending=S.active~=nil and S.active.parts_refresh~=nil
                and S.active.parts_refresh.restore_required==true,
            remapped_row_count=S.active and #S.active.seat_order or 0,
            navigation_active=S.active~=nil and S.active.navigation~=nil and S.active.navigation.active==true,
            navigation_resume_requested=S.active~=nil and S.active.navigation~=nil and S.active.navigation.resume_requested==true}
    end
    return API
end

local function check_conflicts(R)
    local wanted={}
    for version=0,21 do
        local prefix=version==0 and 'v01' or ('v01'..version)
        for _,suffix in ipairs({'Enable','Select','Stop','Check','Mapping'}) do
            wanted[u32(R.Utils.Joaat('CScript_DriverWeapons_Prototype_'..prefix..'_'..suffix))]=true
        end
    end
    for _,version in ipairs({'010','020','021','022','023','024','025','026','027','028','029'}) do
        for _,suffix in ipairs({'Enable','Stop'}) do
            wanted[u32(R.Utils.Joaat('CScript_HunterPilotCamera_v'..version..'_'..suffix))]=true
        end
    end
    assert(next(registered_features(R.FeatureMgr,wanted))==nil,
        'Finish cleanup and unload the standalone Driver Weapons / Hunter Camera prototype first.')
end
return {Create=create,CheckConflicts=check_conflicts,Hashes=H,Pattern=HANDLING_PATTERN}
end)()

-- Driver controller integration. Native work runs on the gameplay tick;
-- the host unload callback uses only the memory cleanup fallback.
local function create_driver_weapons_owner(factory, runtime)
    local controller,camera,failed,cancelled=nil,nil,false,false
    local API={}
    local function camera_pending()
        if not camera then return false end
        local c=camera.Snapshot()
        return c.cam~=nil or c.movie~=nil or c.cleanup_pending~=nil
    end
    function API.NeedsTick() return controller~=nil or camera~=nil or failed or cancelled end
    function API.Pending()
        local s=controller and controller.Snapshot() or {}
        return s.active==true or s.restore_pending==true or camera_pending()
    end
    function API.Tick(wanted,camera_wanted)
        wanted=wanted==true
        camera_wanted=wanted and camera_wanted==true and not cancelled
        if not wanted then failed,cancelled=false,false end
        if not controller then
            if not wanted or failed or cancelled then return end
            local ok,result=pcall(function()
                factory.CheckConflicts(runtime)
                local bound={};for k,v in pairs(runtime) do bound[k]=v end
                bound.HunterGunCameraPermit=function(c)
                    return camera~=nil and camera.AllowsNativeFire(c)==true
                end
                return factory.Create(bound)
            end)
            if not ok then failed=true;runtime.Report(result);return end
            controller=result;controller.RequestMappingCheck();controller.Tick(false)
        end
        if camera_wanted and not camera then
            local ok,result=pcall(HunterGunCamera.Create,runtime)
            if ok then camera=result else camera_wanted=false;runtime.Report(result) end
        end
        if camera then
            local before=controller.Snapshot()
            camera.Tick(camera_wanted,before)
            local cs=camera.Snapshot()
            if cs.navigation_active and not before.navigation_active then
                controller.BeginNavigation("Camera yielded to normal Hunter controls")
            end
            if cs.navigation_resume_request and controller.Snapshot().navigation_active then
                controller.RequestNavigationResume("Stock Hunter input and bomb bay settled")
            end
        end
        controller.Tick(wanted and not cancelled)
        local s=controller.Snapshot()
        if camera and (not s.active or s.blocked or s.restore_pending or s.selection_pending) then
            local cs=camera.Snapshot()
            if cs.cam or cs.movie or cs.ready then camera.Cancel("Driver stopped or selection pending") end
        end
        if s.blocked and wanted and not failed then failed=true;runtime.Report(s.detail) end
        if camera and not camera_wanted and not camera_pending() then camera.Unload();camera=nil end
        if not wanted and not API.Pending() then controller.Unload();controller=nil end
    end
    function API.Cancel(reason)
        if camera then camera.Cancel(reason) end
        if controller then cancelled=true;controller.Cancel(reason) end
    end
    function API.Drain() API.Tick(false,false);return not API.Pending() end
    function API.Unload()
        if camera then camera.Unload();camera=nil end
        if controller then controller.Unload();controller=nil end
    end
    function API.CameraSnapshot() return camera and camera.Snapshot() or {status="OFF",ready=false} end
    return API
end

local driver_weapons
local roof_turret
local roof_turret_session=0
local function cancel_driver_weapons(reason)
    if driver_weapons then driver_weapons.Cancel(reason) end
end
local started = false
local bound = false
local features_registered = false
local runtime_writes_suspended = false
local handlers_registered = false
local vehicle_change_handler_id = nil
local damage_auto_repair
local vehicle_fly
-- BEGIN VEHICLE_FLY
-- Physics velocity keeps the vehicle solid; no coordinate, collision, gravity or freeze writes.
local function new_vehicle_fly(d)
    local api, s = {}, { status="OFF", generation=0 }
    local H = {
        exists=0x7239B21A38F536BA, dead=0x5F9532F3B5CC2551, model=0x9F47B058362C84B5,
        vehicle=0x9A9112A0FE9A4713, networked=0xC7827959479DCC78, control=0x01BF60A500E28887,
        transition=0x68049AEFF83D8F0A, switch=0xD9D2CFFF49FAB35F, cutscene=0x991251AFC3981F84,
        player_control=0x49C32D60007AFA47, collision=0xCCF1E97BEFDAE480, attached=0xB346476EF1A64897,
        pause=0xB0034A223497FFCB, chat=0xB118AF58B5F332A1,
        coords=0x3FEF770D40960D5A, cam=0x5B4E4C817FCC2DFB,
        roof=0x1899F328B0E12848, rotation=0xAFBD61CC738D9EB9, view=0xA4FF579AC0E3AAAE,
        keyboard=0xA571D46727E2B718, disabled_look=0x11E65974A982637C, bonnet=0xD7360051C885628B,
        frame=0x15C40837039FFAF7, disabled=0xE2587F8CBBD87B1D,
        frame_count=0xFC8202EFC642E6F2,
        get_velocity=0x4805D2B1D8CF94A9, velocity=0x1C99BB7B6E96D16F, angular=0x8339643499D1222E,
        rotate=0x8524A8B0171D5E07, disable=0xFE99B66D079CF6BC,
    }
    -- Match the visible camera directly, as in the activation repair.
    -- GTA owns mouse/stick look; no accumulated synthetic attitude offset.
    local controls={21,22,36,59,60,61,62,63,64,71,72,73,76,87,88,89,90,107,108,109,110,111,
        129,130,131,132,133,134,135,136,86,387,388,389,391}
    -- 387 is Enhanced vehicle jump; 388/389/391 and horn 86 are this
    -- module's existing Enhanced boost routes. Flight owns those actions.
    local function finite(v) return type(v)=="number" and v==v and math.abs(v)<math.huge end
    local function read(kind,hash,...)
        local ok,value,y,z=d.Try(kind,hash,...)
        assert(ok,"Flight native unavailable")
        if kind=="bool" then
            assert(type(value)=="boolean" or value==0 or value==1,"Flight boolean unavailable")
            return value==true or value==1
        end
        if kind=="int" then assert(finite(value) and value%1==0,"Flight identity unavailable") end
        return value,y,z
    end
    local function count(key,amount)
        s[key]=math.min(2147483647,(s[key] or 0)+(amount or 1))
    end
    -- Observations cannot authorize or cancel a physics update. The host only
    -- promises looped dispatch, so frame counts describe delivery; they do not
    -- deduplicate ticks or prove a fixed callback-to-render relationship.
    local function observe(kind,hash)
        local generation=s.generation
        local ok,value=pcall(read,kind,hash)
        if generation~=s.generation then return nil,false end
        if ok then return value,true end
        count("diagnostic_read_failures")
        return nil,false
    end
    local function observe_frame()
        local frame,ok=observe("int",H.frame_count)
        if ok and frame<0 then ok=false;count("diagnostic_read_failures")end
        s.frame_observation_available=ok
        if not ok then s.last_observed_frame=nil;return nil end
        local previous=s.last_observed_frame
        if previous~=nil then
            if frame>previous+1 then count("frame_gaps",frame-previous-1)
            elseif frame==previous then count("same_frame_observations")
            elseif frame<previous then count("frame_counter_resets")end
        end
        s.last_observed_frame=frame
        return frame
    end
    local function vector(hash,...)
        local value,y,z=read("vector3",hash,...)
        -- Cherax InvokeV3 returns x, y, z; alternate hosts can return a vector object.
        if type(value)=="number" then
            assert(finite(value) and finite(y) and finite(z),"Flight vector unavailable")
            return {x=value,y=y,z=z}
        end
        assert(type(value)=="table" or type(value)=="userdata","Flight vector unavailable")
        local x=value.x
        y,z=value.y,value.z
        assert(finite(x) and finite(y) and finite(z),"Flight vector unavailable")
        return {x=x,y=y,z=z}
    end
    local function camera_rotation(fallback)
        local snapshot=d.CameraRotation and d.CameraRotation()
        if snapshot and snapshot.active==true then
            local r=snapshot.rotation
            assert(r and finite(r.x) and finite(r.y) and finite(r.z),"Flight camera unavailable")
            return {x=r.x,y=r.y,z=r.z},true
        end
        return fallback and vector(H.cam,2) or nil,false
    end
    local function enabled(token)
        return token==s.generation and d.Enabled()==true
    end
    local function address(handle)
        local value=d.Address(handle)
        assert(finite(value) and value%1==0 and value>=0x10000,"Flight entity address unavailable")
        return value
    end
    local function capture(token)
        assert(enabled(token),"Flight disabled")
        assert(not read("bool",H.transition) and not read("bool",H.switch)
            and not read("bool",H.cutscene),"Gameplay paused")
        local id={ped=d.LocalPed(),vehicle=d.LocalVehicle(),session=d.Session()}
        assert(finite(id.ped) and id.ped>0 and finite(id.vehicle) and id.vehicle>0,
            "Enter a vehicle to fly")
        assert(read("bool",H.exists,id.ped) and read("bool",H.exists,id.vehicle)
            and not read("bool",H.dead,id.ped,false) and not read("bool",H.dead,id.vehicle,false),
            "Current vehicle unavailable")
        assert(read("int",H.vehicle,id.ped,false)==id.vehicle,"Player left vehicle")
        assert(read("bool",H.player_control,d.LocalPlayer()),"Player control unavailable")
        id.address=address(id.vehicle)
        id.model=read("int",H.model,id.vehicle)
        assert(id.model~=0,"Vehicle identity unavailable")
        assert(not read("bool",H.networked,id.vehicle) or read("bool",H.control,id.vehicle),
            "Vehicle control unavailable")
        assert(not read("bool",H.collision,id.vehicle),"Disable collisionless mode to use Vehicle Fly")
        assert(not read("bool",H.attached,id.vehicle),"Detach the vehicle before flying")
        return id
    end
    local function same(a,b)
        return a and b and a.ped==b.ped and a.vehicle==b.vehicle and a.address==b.address
            and a.model==b.model and a.session==b.session
    end
    local function live(token,id)
        return enabled(token) and d.Session()==id.session and d.LocalPed()==id.ped
            and d.LocalVehicle()==id.vehicle and address(id.vehicle)==id.address
            and read("int",H.model,id.vehicle)==id.model
            and (not read("bool",H.networked,id.vehicle) or read("bool",H.control,id.vehicle))
            and not read("bool",H.collision,id.vehicle)
    end
    local function write(token,id,hash,...)
        assert(live(token,id),"Flight ownership changed")
        local ok,result=d.Try("void",hash,...)
        assert(ok and result~=false,"Flight update failed")
    end
    function api.Cancel()
        s.generation=s.generation+1
        s.owner,s.anchor,s.altitude,s.moving=nil,nil,nil,nil
        s.attitude,s.look,s.previous,s.view,s.bonnet,s.custom,s.input,s.control_interval=nil,nil,nil,nil,nil,nil,nil,nil
        s.level,s.requested_speed,s.measured_speed,s.command_speed,s.observed_speed=0,0,0,0,0
        s.previous_level,s.previous_command_speed,s.previous_boosted=0,0,false
        s.boosted,s.look_x,s.look_y=false,0,0
        s.status,s.detail="OFF",nil
        for _,key in ipairs({"attempts","applied","skipped","frame_gaps","same_frame_observations",
            "frame_counter_resets","diagnostic_read_failures"})do s[key]=0 end
        s.last_skip_reason,s.last_skip_frame,s.last_observed_frame=nil,nil,nil
        s.frame_observation_available=false
    end
    function api.Tick()
        local token=s.generation
        if not enabled(token) then api.Cancel();return false end
        count("attempts")
        local observed_frame=observe_frame()
        local ok,err=pcall(function()
            local id=capture(token)
            local pos=vector(H.coords,id.vehicle,false)
            local measured=vector(H.get_velocity,id.vehicle)
            local camera,custom=camera_rotation(true)
            local roof=vector(H.roof,id.vehicle,0.0,0.0,1.0)
            roof.x,roof.y,roof.z=roof.x-pos.x,roof.y-pos.y,roof.z-pos.z
            local roof_length=math.sqrt(roof.x*roof.x+roof.y*roof.y+roof.z*roof.z)
            assert(roof_length>0.0001,"Vehicle roof direction unavailable")
            roof.x,roof.y,roof.z=roof.x/roof_length,roof.y/roof_length,roof.z/roof_length
            -- Camera mode is display metadata. Actual camera direction and all
            -- identity/control reads remain mandatory for movement below.
            local view=observe("int",H.view)
            local bonnet=observe("bool",H.bonnet)
            local speed=d.Speed()
            assert(finite(speed),"Flight speed unavailable")
            local level=math.max(0,math.min(10,speed))
            speed=level*(10.0+level)
            local elapsed=read("float",H.frame)
            assert(finite(elapsed) and elapsed>0,"Flight timing unavailable")
            -- GET_FRAME_TIME is the interval completed before this frame callback.
            -- Hold a recent long interval for the position gain so a sudden next
            -- slow frame cannot turn a fast-frame gain into an unstable correction.
            s.control_interval=math.max(elapsed,(s.control_interval or elapsed)*math.exp(-elapsed/2))
            local gain=math.min(40.0,0.85/s.control_interval)
            local gui=d.GuiOpen()
            assert(type(gui)=="boolean","Menu state unavailable")
            local input=not gui and not read("bool",H.pause) and not read("bool",H.chat)
            if not same(s.owner,id) then
                s.anchor,s.altitude,s.moving,s.previous=nil,nil,nil,nil
                s.control_interval=elapsed
                s.attitude,s.look=nil,nil
            end
            -- Refresh every frame, including activation and menu resume.
            -- Starting on a slope or banked must not retain that angle forever.
            s.look={x=math.max(-89,math.min(89,camera.x)),z=camera.z}
            assert(same(id,capture(token)),"Flight identity changed")
            for _,control in ipairs(controls) do
                assert(enabled(token),"Flight disabled")
                local applied,result=d.Try("void",H.disable,0,control,true)
                assert(applied and result~=false,"Flight input suppression unavailable")
            end
            local function held(vk)
                local value=d.KeyDown(vk)
                assert(type(value)=="boolean","Keyboard unavailable")
                return value
            end
            local function key(vk)
                if not input then return 0 end
                local down=held(vk)
                if vk==0x10 then
                    down=down or held(0xA0) or held(0xA1) or read("bool",H.disabled,0,21)
                elseif vk==0x11 then
                    down=down or held(0xA2) or held(0xA3) or read("bool",H.disabled,0,36)
                end
                return down and 1 or 0
            end
            local forward,right,up=key(0x57)-key(0x53),key(0x44)-key(0x41),key(0x10)-key(0x11)
            s.boosted=key(0x20)>0
            if s.boosted then speed=speed*2 end
            s.level,s.requested_speed=level,speed
            s.previous_command_speed=s.previous and s.previous.command_speed or 0
            s.previous_level=s.previous and s.previous.level or 0
            s.previous_boosted=s.previous and s.previous.boosted==true or false
            s.observed_speed=0
            if s.previous then
                local previous=s.previous
                local dx,dy,dz=pos.x-previous.position.x,pos.y-previous.position.y,pos.z-previous.position.z
                s.observed_speed=math.min(10000,math.sqrt(dx*dx+dy*dy+dz*dz)/elapsed)
            end
            s.measured_speed=math.min(10000,math.sqrt(measured.x*measured.x+measured.y*measured.y+measured.z*measured.z))
            s.look_x,s.look_y=0,0
            -- Do not disable or reinterpret look controls 1/2. Standard GTA
            -- camera sensitivity and independent Camera Freedom remain in charge.
            local pitch=s.look.x
            local yaw=s.look.z%360
            local p,h=math.rad(pitch),math.rad(yaw)
            local x=-math.sin(h)*math.cos(p)*forward+math.cos(h)*right+roof.x*up
            local y=math.cos(h)*math.cos(p)*forward+math.sin(h)*right+roof.y*up
            local z=math.sin(p)*forward+roof.z*up
            local length=math.sqrt(x*x+y*y+z*z)
            local moving=length>0.0001 and speed>0
            local vx,vy,vz=0,0,0
            local bias={x=0,y=0,z=0}
            if s.previous then
                -- The next frame duration is unknown. The recent time-weighted
                -- interval cancels mean force drift during alternating frame rates
                -- without chasing the previous frame's duration in the servo.
                local last=s.previous.elapsed
                local prediction=(elapsed*elapsed+last*last)/(elapsed+last)
                for _,axis in ipairs({"x","y","z"}) do
                    local previous=s.previous
                    local end_error=measured[axis]-previous.command[axis]
                    local travel_error=(pos[axis]-previous.position[axis])/elapsed-previous.command[axis]
                    -- Learn physics' integrated velocity bias. Actual velocity
                    -- bounds the estimate so an outside teleport cannot become force.
                    if travel_error*end_error>0 then
                        local limit=math.abs(end_error)
                        local observed=math.max(-limit,math.min(limit,travel_error))
                        bias[axis]=math.max(-5,math.min(5,observed*prediction/elapsed))
                    end
                end
            end
            if moving then
                vx,vy,vz=x/length*speed,y/length*speed,z/length*speed
                s.anchor=nil
                if math.abs(z)<0.0001 then
                    if not s.altitude or math.abs(s.altitude-pos.z)>50 then s.altitude=pos.z end
                    vz=math.max(-20,math.min(20,(s.altitude-pos.z)*gain-bias.z))
                else s.altitude=nil end
            else
                s.altitude=nil
                if s.moving or not s.anchor then s.anchor=pos end
                local dx,dy,dz=s.anchor.x-pos.x,s.anchor.y-pos.y,s.anchor.z-pos.z
                local distance=math.sqrt(dx*dx+dy*dy+dz*dz)
                -- Rebase only after a large outside displacement, never ordinary hover drift.
                if distance>50 then s.anchor=pos else
                    local scale=distance>0 and math.min(gain,20/distance) or 0
                    vx,vy,vz=dx*scale-bias.x,dy*scale-bias.y,dz*scale-bias.z
                    local correction=math.sqrt(vx*vx+vy*vy+vz*vz)
                    if correction>20 then vx,vy,vz=vx*20/correction,vy*20/correction,vz*20/correction end
                end
            end
            if input then
                write(token,id,H.rotate,id.vehicle,pitch,0.0,yaw,2,true)
            end
            write(token,id,H.angular,id.vehicle,0.0,0.0,0.0)
            write(token,id,H.velocity,id.vehicle,vx,vy,vz)
            s.command_speed=math.sqrt(vx*vx+vy*vy+vz*vz)
            s.previous={position=pos,command={x=vx,y=vy,z=vz},elapsed=elapsed,
                command_speed=s.command_speed,level=level,boosted=s.boosted}
            s.owner,s.moving,s.view,s.bonnet,s.custom,s.input=id,moving,view,bonnet,custom,input
            s.status,s.detail="ACTIVE",input and "WASD | Shift toward roof | Ctrl toward floor | Space 2x" or "Hovering while using menus"
        end)
        if token~=s.generation then return false end
        if not ok then
            -- Retain the hover point during temporary control interruptions.
            -- Resuming still requires a fresh matching entity and control check.
            s.previous,s.input=nil,false
            s.status,s.detail="WAITING",tostring(err):gsub("^.-:%d+: ",""):sub(1,192)
            count("skipped")
            s.last_skip_reason,s.last_skip_frame=s.detail,observed_frame
            return false
        end
        count("applied")
        return true
    end
    function api.Snapshot()
        return {status=s.status,detail=s.detail,vehicle=s.owner and s.owner.vehicle or 0,
            requested_speed=s.requested_speed or 0,measured_speed=s.measured_speed or 0,
            command_speed=s.command_speed or 0,observed_speed=s.observed_speed or 0,
            level=s.level or 0,previous_level=s.previous_level or 0,
            previous_command_speed=s.previous_command_speed or 0,previous_boosted=s.previous_boosted==true,
            boosted=s.boosted==true,view=s.view or -1,cockpit=s.view==4 or s.bonnet==true,
            look_x=s.look_x or 0,look_y=s.look_y or 0,
            attempts=s.attempts or 0,applied=s.applied or 0,skipped=s.skipped or 0,
            last_skip_reason=s.last_skip_reason,last_skip_frame=s.last_skip_frame,
            frame_gaps=s.frame_gaps or 0,same_frame_observations=s.same_frame_observations or 0,
            frame_counter_resets=s.frame_counter_resets or 0,last_frame=s.last_observed_frame,
            frame_observation_available=s.frame_observation_available==true,
            diagnostic_read_failures=s.diagnostic_read_failures or 0}
    end
    return api
end
-- END VEHICLE_FLY

-- BEGIN DAMAGE_AUTO_REPAIR44
-- Damage-only maintenance. This controller never resets a vehicle, starts its
-- engine, changes weapons/ammo/timing, or recreates any entity.
local function new_damage_auto_repair(d)
    local api = {}
    local s = { generation=0, blocked=false, busy=false, status="OFF", detail="Disabled",
        writes=0, health_verified=0, last_vehicle=0 }
    local H = {
        SESSION=0x9DE624D2FC4B603F, TRANSITION=0x68049AEFF83D8F0A,
        SWITCH=0xD9D2CFFF49FAB35F, CUTSCENE=0x991251AFC3981F84,
        EXISTS=0x7239B21A38F536BA, DEAD=0x5F9532F3B5CC2551,
        MODEL=0x9F47B058362C84B5, VEHICLE=0x9A9112A0FE9A4713,
        NETWORKED=0xC7827959479DCC78, CONTROL=0x01BF60A500E28887,
        ENGINE=0xC45D23BAF168AAB8, SET_ENGINE=0x45F6D8EEF34ABEF1,
        BODY=0xF271147EB7B40F12, SET_BODY=0xB77D05AC8C78AADB,
        TANK=0x7D5DABE888D2D074, SET_TANK=0x70DB57649FA8D0D8,
        DAMAGE=0xBCDC5017D3CE1E9E, DEFORMATION=0x953DA1E1B12C0491,
        DECALS=0xE91F1B65F2B48D57, TYRE=0xBA291848A0815CA9,
        FIX_TYRE=0x6E13FC662B882D1D, FIRE=0x28D3FED7190D3A0B,
        STOP_FIRE=0x7F0DD2EBBB651AFF,
    }
    local tyres={0,1,2,3,4,5,45,47}
    local health={{H.ENGINE,H.SET_ENGINE,-4000},{H.BODY,H.SET_BODY,0},{H.TANK,H.SET_TANK,-1000}}
    local function finite(v)return type(v)=="number" and v==v and math.abs(v)<math.huge end
    local function integer(v)return finite(v) and v%1==0 end
    local function status(value,detail,now)
        s.status,s.detail=value,detail
        if value~="WAITING" then s.reported=nil;return end
        if detail==s.reported then return end
        if finite(now) and finite(s.reported_at) and now>=s.reported_at and now-s.reported_at<2000 then return end
        s.reported,s.reported_at=detail,finite(now) and now or nil
        if type(d.Report)=="function" then pcall(d.Report,detail) end
    end
    local function enabled(token)
        if s.blocked or token~=s.generation then return false end
        local ok,value=pcall(d.Enabled)
        return ok and value==true and not s.blocked and token==s.generation
    end
    local function boolean(hash,...)
        assert(d.Natives and type(d.Natives.InvokeBool)=="function","Boolean reader unavailable")
        local value=d.Natives.InvokeBool(hash,...)
        assert(type(value)=="boolean" or value==0 or value==1,
            ("Boolean read unavailable (0x%X)"):format(hash))
        return value==true or value==1
    end
    local function number(kind,hash,...)
        local reader=d.Natives and d.Natives[kind]
        assert(type(reader)=="function","Numeric reader unavailable")
        local value=reader(hash,...)
        assert(finite(value) and (kind~="InvokeInt" or integer(value)),
            ("Numeric read unavailable (0x%X)"):format(hash))
        return kind=="InvokeInt" and math.tointeger(value) or value
    end
    local function address(entity,kind)
        assert(entity and type(entity[kind])=="function" and entity[kind](entity)==true,"Entity kind unavailable")
        local value=entity:GetAddress()
        assert(integer(value) and value>=0x10000 and value<0x800000000000,"Entity identity unavailable")
        return value
    end
    local function capture(token)
        assert(enabled(token),"Maintenance canceled")
        assert(boolean(H.SESSION) and not boolean(H.TRANSITION)
            and not boolean(H.SWITCH) and not boolean(H.CUTSCENE),"Gameplay unavailable")
        local epoch,pid,ped,vehicle=d.Session(),d.LocalPlayer(),d.LocalPed(),d.LocalVehicle()
        assert(integer(epoch) and integer(pid) and pid>=0 and pid<=31
            and integer(ped) and ped>0 and integer(vehicle) and vehicle>0,"Current vehicle unavailable")
        pid,ped,vehicle=math.tointeger(pid),math.tointeger(ped),math.tointeger(vehicle)
        assert(boolean(H.EXISTS,ped) and boolean(H.EXISTS,vehicle)
            and not boolean(H.DEAD,ped,false) and not boolean(H.DEAD,vehicle,false),"Current entities unavailable")
        assert(number("InvokeInt",H.VEHICLE,ped,false)==vehicle,"Player left vehicle")
        local player=d.Players and d.Players.GetById(pid)
        assert(player and player:IsLocalPlayer()==true,"Local connection unavailable")
        local connection,player_address=player.CxnId,player:GetAddress()
        -- Cherax reports -1 for the local connection. It is valid only after
        -- IsLocalPlayer above, and must still match on every identity recheck.
        assert(integer(connection) and connection>=-1 and integer(player_address)
            and player_address>=0x10000,"Local connection identity unavailable")
        local p=d.GTA.HandleToPointer(ped)
        local v=d.GTA.HandleToPointer(vehicle)
        local ped_address,vehicle_address=address(p,"IsPed"),address(v,"IsVehicle")
        local ped_model=number("InvokeInt",H.MODEL,ped)&0xffffffff
        local vehicle_model=number("InvokeInt",H.MODEL,vehicle)&0xffffffff
        assert(ped_model~=0 and vehicle_model~=0,"Model identity unavailable")
        assert(p.ModelInfo and integer(p.ModelInfo.Model) and (p.ModelInfo.Model&0xffffffff)==ped_model
            and v.ModelInfo and integer(v.ModelInfo.Model) and (v.ModelInfo.Model&0xffffffff)==vehicle_model,
            "Model identity changed")
        local networked=boolean(H.NETWORKED,vehicle)
        local network=0
        if networked then
            local net=v.NetObject
            assert(net and integer(net.ObjectID) and net.ObjectID>0 and net.IsRemote==false
                and net.PlayerId==pid,"Local vehicle ownership unavailable")
            network=net.ObjectID
            assert(boolean(H.CONTROL,vehicle),"Local vehicle control unavailable")
        end
        -- Close both handle and connection reads before any damage writes.
        assert(d.Session()==epoch and d.LocalPlayer()==pid and d.LocalPed()==ped
            and d.LocalVehicle()==vehicle and number("InvokeInt",H.VEHICLE,ped,false)==vehicle,
            "Current vehicle changed")
        local final_player=d.Players.GetById(pid)
        local final_ped,final_vehicle=d.GTA.HandleToPointer(ped),d.GTA.HandleToPointer(vehicle)
        assert(final_player and final_player:IsLocalPlayer()==true
            and final_player.CxnId==connection and final_player:GetAddress()==player_address
            and address(final_ped,"IsPed")==ped_address and address(final_vehicle,"IsVehicle")==vehicle_address,
            "Current identity changed")
        assert(final_ped.ModelInfo and integer(final_ped.ModelInfo.Model)
            and (final_ped.ModelInfo.Model&0xffffffff)==ped_model
            and final_vehicle.ModelInfo and integer(final_vehicle.ModelInfo.Model)
            and (final_vehicle.ModelInfo.Model&0xffffffff)==vehicle_model,
            "Current model changed")
        -- A local entity can become networked while the identity adapters run.
        -- Its earlier local-only status cannot authorize a later remote write.
        assert(boolean(H.NETWORKED,vehicle)==networked,"Vehicle networking changed")
        if networked then
            local final_net=final_vehicle.NetObject
            assert(final_net and final_net.ObjectID==network and final_net.IsRemote==false
                and final_net.PlayerId==pid and boolean(H.CONTROL,vehicle),"Vehicle ownership changed")
        end
        assert(boolean(H.SESSION) and not boolean(H.TRANSITION)
            and not boolean(H.SWITCH) and not boolean(H.CUTSCENE),"Gameplay changed")
        assert(d.Session()==epoch,"Session changed")
        assert(enabled(token),"Maintenance canceled")
        return {epoch=epoch,pid=pid,ped=ped,vehicle=vehicle,connection=connection,player=player_address,
            ped_address=ped_address,vehicle_address=vehicle_address,ped_model=ped_model,
            vehicle_model=vehicle_model,network=network,networked=networked}
    end
    local function same(a,b)
        if not a or not b then return false end
        for key,value in pairs(a)do if b[key]~=value then return false end end
        return true
    end
    local function current(record,token)
        assert(same(record,capture(token)),"Current vehicle changed")
    end
    local function write(record,token,hash,...)
        current(record,token)
        assert(type(d.Natives.InvokeVoid)=="function","Damage writer unavailable")
        local result=d.Natives.InvokeVoid(hash,record.vehicle,...)
        assert(result~=false,"Damage write rejected")
        s.writes=s.writes+1
        assert(enabled(token),"Maintenance canceled")
    end
    function api.Invalidate()
        s.generation=s.generation+1;s.cosmetic=nil
    end
    function api.IntentChanged(value)
        api.Invalidate();s.blocked=value~=true
        status(value==true and "READY"or "OFF",value==true and "Awaiting current vehicle"or "Disabled")
    end
    function api.Cancel()
        api.Invalidate();s.blocked=true;status("OFF","Disabled")
    end
    function api.Resume()
        api.Invalidate();s.blocked=false;status("READY","Awaiting current vehicle")
    end
    function api.Snapshot()
        return {status=s.status,detail=s.detail,generation=s.generation,writes=s.writes,blocked=s.blocked,
            health_verified=s.health_verified,last_vehicle=s.last_vehicle,last_attempt_ms=s.last_attempt_ms}
    end
    local function tick(now,token)
        local record=capture(token)
        local handle=record.vehicle
        s.last_vehicle=handle
        local damaged=false
        for _,spec in ipairs(health)do
            local value=number("InvokeFloat",spec[1],handle)
            -- Preserve boosted health; reject unknown/out-of-range reads and a
            -- destroyed engine. A wreck is not silently resurrected.
            assert(value>=spec[3],"Damage health unavailable")
            if spec[1]==H.ENGINE and value<=-4000 then status("DESTROYED","Current vehicle is destroyed");return end
            if value<1000.0 then
                damaged=true
                write(record,token,spec[2],1000.0)
                local observed=number("InvokeFloat",spec[1],handle)
                current(record,token)
                assert(observed>=1000.0,("Health readback did not confirm repair (0x%X)"):format(spec[1]))
                s.health_verified=s.health_verified+1
            end
        end
        local decals=boolean(H.DAMAGE,handle)
        -- Damage decals and health are not a complete deformation inventory.
        -- Keep the dedicated deformation repair on a short cadence, including
        -- when another owner has restored health or removed damage decals.
        local previous=s.cosmetic
        local due=damaged or not previous or not same(previous.identity,record)
            or not finite(now) or now<previous.at or now-previous.at>=100
        if due then
            write(record,token,H.DEFORMATION)
            if decals then write(record,token,H.DECALS)end
            s.cosmetic={identity=record,at=finite(now)and now or 0}
        end
        for _,tyre in ipairs(tyres)do
            if boolean(H.TYRE,handle,tyre,false)then write(record,token,H.FIX_TYRE,tyre)end
        end
        if boolean(H.FIRE,handle)then write(record,token,H.STOP_FIRE)end
        status("ACTIVE","Damage maintenance active")
    end
    function api.Tick(now)
        if s.busy then return end
        local token=s.generation
        if not enabled(token)then status("OFF","Disabled");return end
        s.busy=true
        s.last_attempt_ms=finite(now)and now or nil
        local ok,err=pcall(tick,now,token)
        s.busy=false
        if not ok then
            if enabled(s.generation) then
                local detail=tostring(err):gsub("^.-:%d+:%s*",""):gsub("[\r\n]"," "):sub(1,220)
                status("WAITING",detail,now)
            else status("OFF","Disabled") end
        end
    end
    return api
end
-- END DAMAGE_AUTO_REPAIR44

-- Explicit release evidence is shared across consumers even when Messiah is
-- disabled. Consult it ONLY for retained aliases, never fresh local ped/vehicle
-- handles. A positive GUID can keep mapping after another consumer releases it.
local function cached_entity_handle_released(handle)
    local player = module_context and module_context.CScript and module_context.CScript.Player
    local check = player and player.IsReleasedEntityHandle
    if type(check) ~= "function" then return false end
    local ok, released = pcall(check, handle)
    return not ok or released ~= false
end

-- Live-traced Enhanced 1.0.1158.16 display preference, not profile-setting cache 412.
-- PREF_RETICULE maps to index 31. Its update(mode=2) branch is a no-op, so a
-- temporary change needs only the preference store, with no profile/save call.
local function create_reticle_preference(get_memory)
    local owner
    local function resolve()
        local m = get_memory()
        assert(m and m.GetBaseAddress and m.Check and m.ReadInt and m.ReadUByte and m.WriteInt, "preference APIs unavailable")
        local base = m.GetBaseAddress("GTA5_Enhanced.exe")
        local function valid(p)
            return type(p)=="number" and p%1==0 and p>=0x10000 and p<0x7FFFFFFFF000 and m.Check(p)
        end
        assert(valid(base), "game module unavailable")
        local pe = base + m.ReadInt(base+0x3C)
        assert(valid(pe) and m.ReadInt(pe)==0x4550, "game image unavailable")
        local size = m.ReadInt(pe+0x50)
        assert(size>0x3DFC400 and size<0x40000000, "unsupported game image")
        local function bytes(rva, hex)
            local p = base+rva
            assert(rva>=0 and rva+#hex/2<size and valid(p) and valid(p+#hex/2-1), "preference code unavailable")
            for i=1,#hex,2 do
                assert(m.ReadUByte(p+(i-1)//2)==tonumber(hex:sub(i,i+1),16), "display preference binding changed")
            end
        end
        -- Independently validate index identity, setter base, cache producer,
        -- and the fact that a temporary update has no extra engine side effect.
        bytes(0x5BD2F6, "41B9FD599F17448908C3")
        assert(base+0x5BD840+m.ReadInt(base+0x5BD840+31*4)==base+0x5BD2F6, "reticle index changed")
        bytes(0x5C7040, "41574156565755534883EC2881F9D80000007F3A4489C689D589CF4863D94C8D3D")
        bytes(0x5C7065, "458B349F")
        bytes(0x5C709B, "41892C9F89F989F24589F0")
        local field = base+0x5C7065+m.ReadInt(base+0x5C7061)+31*4
        bytes(0x5C6074, "448B05")
        bytes(0x5C607B, "4889F1BA9C010000")
        assert(base+0x5C607B+m.ReadInt(base+0x5C6077)==field, "preference producer disagrees")
        assert(base+0x5E9328+m.ReadInt(base+0x5E9328+31*4)==base+0x5E90C1, "reticle update changed")
        bytes(0x5E90C1, "4183E4FD4183FC010F853D010000")
        assert(field>=base and field+4<=base+size and valid(field) and valid(field+3), "preference field unavailable")
        local value=m.ReadInt(field)
        assert(value==0 or value==1, "unknown Weapon Target value")
        return m,field,value
    end
    local api={}
    function api.Read()
        local ok,m,p,value=pcall(resolve)
        if not ok then return nil,tostring(m) end
        return value
    end
    function api.Set(target)
        if target~=0 and target~=1 then return false,"invalid Weapon Target value" end
        local ok,err=pcall(function()
            local m,p,current=resolve()
            if owner and owner.address~=p then error("preference owner changed") end
            if owner and current~=owner.applied then owner=nil end -- Respect an outside/user change.
            if current==target then return end
            owner=owner or {address=p,original=current}
            owner.applied=target
            m.WriteInt(p,target)
            assert(m.ReadInt(p)==target,"preference write did not persist")
        end)
        return ok,ok and "applied" or tostring(err)
    end
    function api.Restore()
        if not owner then return true end
        local ok,err=pcall(function()
            local m,p,current=resolve()
            assert(p==owner.address,"preference owner changed")
            if current==owner.applied then
                m.WriteInt(p,owner.original)
                assert(m.ReadInt(p)==owner.original,"preference restoration pending")
            end
            owner=nil
        end)
        return ok,ok and "restored" or tostring(err)
    end
    function api.Owned() return owner~=nil end
    return api
end


local function create_vehicle_reticle_controller(preference, context)
    local active, next_check = false, 0
    local api = {}
    function api.Restore()
        active, next_check = false, 0
        return preference.Restore()
    end
    function api.Tick(now)
        now=tonumber(now) or 0
        if now<next_check and now>=next_check-100 then return end
        next_check=now+100
        local enabled, armed=context()
        if enabled and armed then
            if not active then
                local ok,detail=preference.Set(1)
                active=ok
                return ok,detail
            end
        elseif active or preference.Owned() then
            return api.Restore()
        end
        return true
    end
    return api
end
local reticle_preference, vehicle_reticle
local function restore_vehicle_reticle()
    if vehicle_reticle then return vehicle_reticle.Restore() end
    return true
end

local ShellState = {
    last_vehicle = 0,
    was_in_vehicle = false,
    doors_locked = false,
    registered_count = 0,
    last_rapid_fire_delay_ms = nil,
    fast_enter_exit = {
        active = false, direct_active = false, direct_ped = 0,
        dirty = true, last_attempt_ms = -100000,
    },
}

-- CPED_RESET_FLAG_UseFastEnterExitVehicleRates (237) is GTA's documented
-- one-frame fast-rate selector. Prime it before task creation on EVERY eligible
-- local-player frame: task/input observations can arrive after the engine has
-- already chosen a transition's rate. The engine chooses the faster rates;
-- this flag does not document an exact 2x multiplier.
local FAST_ENTER_EXIT_RESET_FLAG = 237

local function fast_enter_exit_generation()
    local controller=VehicleMods and VehicleMods.state and VehicleMods.state.controller
    return controller and tonumber(controller.session_generation) or 0
end

local function fast_enter_exit_owner(ped)
    local deps = dependencies
    local generation=fast_enter_exit_generation()
    local function current()
        if dependencies~=deps or not deps or not started or not bound or runtime_writes_suspended then return false end
        local observed=deps.local_ped()
        local enabled=deps.is_on("vehicle_fast_enter_exit")
        -- Host reads may reentrantly stop/suspend this module. The last check
        -- must use Lua-owned lifecycle state, not another host read.
        return observed==ped and enabled and dependencies==deps
            and started and bound and not runtime_writes_suspended
            and fast_enter_exit_generation()==generation
    end
    local function confirmed(hash,expected,...)
        if type(deps.invoke_bool_detail)~="function" then return false end
        local value,_,err=deps.invoke_bool_detail(hash,...)
        return err==nil and value==expected
    end
    if not current() or not deps.entity_exists(ped) or not current()
        or not confirmed(0x5E9564D8246B909A,true,deps.local_player_id()) or not current()
        or not confirmed(0x68049AEFF83D8F0A,false) or not current()
        or not confirmed(deps.H.IS_ENTITY_DEAD,false,ped,false) or not current()
        or not confirmed(deps.H.IS_PED_DEAD_OR_DYING,false,ped,true) or not current() then return nil end
    local api = deps.GTA
    if not (api and type(api.GetLocalPed)=="function" and type(api.HandleToPointer)=="function") then return nil end
    local function address(call,...)
        local ok,pointer=pcall(call,...)
        if not ok or not current() or (type(pointer)~="table" and type(pointer)~="userdata") then return nil end
        local read_ok,value=pcall(function() return pointer:GetAddress() end)
        if not read_ok or not current() or type(value)~="number" or value<=0 or value>=math.huge or value%1~=0 then return nil end
        return value
    end
    local owner=address(api.GetLocalPed)
    if not owner or address(api.HandleToPointer,ped)~=owner or not current() then return nil end
    return owner,generation
end

local function reset_fast_enter_exit_animation()
    local state=ShellState.fast_enter_exit
    -- Reset flags expire after one frame. There is no persistent rate to
    -- restore; never clear another script's flag or touch an old ped handle.
    state.direct_active,state.active=false,false
    state.direct_ped,state.direct_address,state.direct_generation=0,nil,nil
    state.transition,state.transition_started_ms=nil,nil
    state.boost_started_ms,state.boost_blocked,state.approach_probe=nil,nil,nil
end

local function fast_enter_exit_animation_tick(now,ped)
    local state=ShellState.fast_enter_exit
    local address,generation=fast_enter_exit_owner(ped)
    -- Unknown owner evidence stops writes, but does not prove that an attempt
    -- ended. Preserve its deadline/latch until clearance or verified replacement.
    if not address then state.direct_active,state.active=false,false;return end
    if state.direct_ped~=ped or state.direct_address~=address
        or state.direct_generation~=generation then reset_fast_enter_exit_animation() end
    local deps=dependencies
    local H=deps.H
    local function same_owner()
        local current,current_generation=fast_enter_exit_owner(ped)
        return current==address and current_generation==generation
    end
    -- These reads are diagnostics only, never a gate on priming the flag.
    -- A read may retire the module; do not dereference its retired bridge or
    -- issue another observation after that callback.
    local function observe(hash,...)
        if dependencies~=deps or not started or not bound or runtime_writes_suspended then return false end
        return deps.invoke_bool(hash,...)
    end
    local entering=observe(H.IS_PED_GETTING_INTO_A_VEHICLE,ped)
        or observe(H.IS_PED_OPENING_DOOR,ped)
    local exiting=observe(H.IS_PED_JUMPING_OUT_OF_VEHICLE,ped)
        or observe(0xB0760331C7AA4155,ped,2)
    -- A host callback may replace the ped, stop the module or turn us off.
    if not same_owner() then state.direct_active,state.active=false,false;return end
    state.direct_ped,state.direct_address,state.direct_generation=ped,address,generation
    local phase=entering and "enter" or (exiting and "exit" or "primed")
    if state.transition~=phase then state.transition,state.transition_started_ms=phase,now end
    -- No task replacement, warp, global animation rate, memory offset, or
    -- animation catalogue scan. Acceptance confirms invocation, not timing.
    local accepted=deps.invoke_void(H.SET_PED_RESET_FLAG,ped,FAST_ENTER_EXIT_RESET_FLAG,true)==true
    state.direct_active,state.active=accepted,accepted
    -- Reset 237 alone selects rates already used in multiplayer. Natural task
    -- acceleration is a separate, bounded candidate; this updates the whole
    -- ped, not a precisely selected clip or an exact 2x rate.
    if type(deps.advance_local_animation)~="function" then return end
    local function confirmed(hash,expected,...)
        if dependencies~=deps or not started or not bound or runtime_writes_suspended then return false end
        local value,_,err=deps.invoke_bool_detail(hash,...)
        return err==nil and value==expected
    end
    -- Raiju's supplied layout has HasClimbUp/HasOnVehicleEntry. Its climb_up
    -- clips can run while the door-approach task still owns movement; a move
    -- rate override cannot advance those clips. Live capture also shows a
    -- normal getting-in stage with neither approach task nor visible clip.
    -- Both paths require the engine's current single-seat entry target.
    local climb_target
    local function climb_context()
        if not same_owner() or not deps.Natives or type(deps.Natives.InvokeInt)~="function" then return nil end
        local ok,target=pcall(function()
            local vehicle=deps.Natives.InvokeInt(H.GET_VEHICLE_PED_IS_TRYING_TO_ENTER,ped)
            if type(vehicle)~="number" or vehicle%1~=0 or not deps.entity_exists(vehicle)
                or not same_owner() then return nil end
            local seat=deps.Natives.InvokeInt(H.GET_SEAT_PED_IS_TRYING_TO_ENTER,ped)
            if seat~=-1 or not same_owner() then return nil end
            local model=deps.Natives.InvokeInt(H.GET_ENTITY_MODEL,vehicle)
            if type(model)~="number" or model%1~=0
                or (model&0xFFFFFFFF)~=(deps.Utils.Joaat("raiju")&0xFFFFFFFF)
                or not same_owner() then return nil end
            local pointer=deps.GTA.HandleToPointer(vehicle)
            local vehicle_address=pointer and pointer:GetAddress()
            if type(vehicle_address)~="number" or vehicle_address<=0
                or vehicle_address>=math.huge or vehicle_address%1~=0 or not same_owner() then return nil end
            return {vehicle=vehicle,address=vehicle_address,seat=seat,model=model}
        end)
        return ok and target or nil
    end
    local function same_climb(left,right)
        return left and right and left.vehicle==right.vehicle and left.address==right.address
            and left.seat==right.seat and left.model==right.model
    end
    local function raiju_climb_active()
        local target=climb_context()
        if not target or climb_target and not same_climb(target,climb_target) then return false end
        local playing=confirmed(H.IS_ENTITY_PLAYING_ANIM,true,ped,
            "anim@veh@plane@raiju@front@ds@enter_exit","climb_up",3)
            or confirmed(H.IS_ENTITY_PLAYING_ANIM,true,ped,
                "anim@veh@plane@raiju@front@ps@enter_exit","climb_up",3)
        if not playing or not same_climb(target,climb_context()) then return false end
        climb_target=target
        return true
    end
    local function raiju_entry_active()
        local target=climb_context()
        if not target or climb_target and not same_climb(target,climb_target) then return false end
        if not confirmed(H.IS_PED_GETTING_INTO_A_VEHICLE,true,ped)
            or not same_climb(target,climb_context()) then return false end
        climb_target=target
        return true
    end
    local function phase_now()
        if not same_owner()
            or not confirmed(H.IS_PED_RAGDOLL,false,ped) then return nil end
        local function task(id)
            if dependencies~=deps or not started or not bound or runtime_writes_suspended then return nil end
            local value,_,err=deps.invoke_bool_detail(0xB0760331C7AA4155,ped,id)
            if err then return nil end
            return value
        end
        local approach,move_to_door=task(195),task(196)
        -- Approach takes priority over overlapping parent/seat tasks. Unknown
        -- approach evidence must never authorize an extra whole-ped AI update.
        if approach==nil or move_to_door==nil then return nil end
        local entry=task(160)
        if entry==nil then return nil end
        if entry and raiju_climb_active() then return "animation" end
        if approach or move_to_door then return "approach" end
        -- Getting-in is normal-entry evidence, not proof of a specific clip.
        -- A bare parent task or unknown/active approach remains insufficient.
        if entry and raiju_entry_active() then return "animation" end
        local unknown=false
        for _,id in ipairs({161,162,163,164,165,166,167,168}) do
            local value=task(id)
            if value==true then return "animation" end
            if value==nil then unknown=true end
        end
        local exit=task(2)
        if unknown or entry==nil or exit==nil then return nil end
        -- Parent-only evidence is not an animation phase and must not rearm
        -- a stalled attempt during a brief gap between its subtasks.
        return (entry or exit) and "pending" or "idle"
    end
    local phase=phase_now()
    if not same_owner() then return end
    if phase=="idle" then
        state.boost_started_ms,state.boost_blocked,state.approach_probe=nil,nil,nil
        return
    end
    if not phase or phase=="pending" then return end
    if type(now)~="number" or now~=now or now<0 or now>=math.huge then return end
    state.boost_started_ms=state.boost_started_ms or now
    if now<state.boost_started_ms or now-state.boost_started_ms>=8000 then state.boost_blocked=true end
    if state.boost_blocked then return end
    if phase=="approach" then
        -- Scale natural movement once per normal game update, not repeated AI
        -- stepping. Unknown coordinates do not authorize a write or reset the
        -- attempt deadline. This is a requested rate, not measured 2x travel.
        local ok,x,y,z=pcall(function()
            local v=deps.invoke_vec3(H.GET_ENTITY_COORDS,ped,false)
            if v then return v.x,v.y,v.z end
        end)
        local function finite(v) return type(v)=="number" and v==v and v>-math.huge and v<math.huge end
        if not ok or not finite(x) or not finite(y) or not finite(z)
            or not same_owner() then return end
        local probe=state.approach_probe
        if not probe then state.approach_probe={x=x,y=y,z=z,at=now}
        elseif now<probe.at then state.boost_blocked=true;return
        elseif now-probe.at>=500 then
            local dx,dy,dz=x-probe.x,y-probe.y,z-probe.z
            if dx*dx+dy*dy+dz*dz<=0.0025 then
                -- Conservative loss-of-progress fallback; this does not prove
                -- engine failure. Resume only after a positively cleared task.
                state.boost_blocked=true;return
            end
            state.approach_probe={x=x,y=y,z=z,at=now}
        end
        if phase_now()=="approach" and same_owner() then
            deps.invoke_void(0x085BF80FA50A39D1,ped,2.0) -- SET_PED_MOVE_RATE_OVERRIDE
        end
        return
    end
    state.approach_probe=nil
    deps.advance_local_animation(ped,function()
        return not state.boost_blocked and phase_now()=="animation"
            and same_owner()
    end)
end

local function restore_fast_enter_exit()
    reset_fast_enter_exit_animation()
    return true
end

local function sync_fast_enter_exit(now, force)
    ShellState.fast_enter_exit.dirty = false
    if not dependencies or not dependencies.is_on("vehicle_fast_enter_exit") then
        reset_fast_enter_exit_animation()
    end
    return true
end

