local RAPID_DELAY_MIN_MS = 0
local RAPID_DELAY_MAX_MS = 500
local RAPID_DELAY_SAFE_FLOOR_SECONDS = 0.005

local function configured_rapid_delay_ms()
    local value = 45
    if dependencies and type(dependencies.slider_int) == "function" then
        value = tonumber(dependencies.slider_int("vehicle_rapid_fire_delay", 45)) or 45
    end
    return math.max(RAPID_DELAY_MIN_MS, math.min(RAPID_DELAY_MAX_MS, math.floor(value)))
end

-- Feature callbacks and the public vehicle-change hook live outside the
-- create_vehicle_system factory, so they cannot see its local now_ms binding.
-- Route those two boundaries through the compatibility dependency explicitly.
local function runtime_now_ms()
    if dependencies and type(dependencies.now_ms) == "function" then
        local ok, value = pcall(dependencies.now_ms)
        value = ok and tonumber(value) or nil
        if value then return value end
    end
    return math.floor(os.clock() * 1000)
end

local function unavailable_collision()
    return nil
end

local function require_binding(name, value)
    if value == nil then error("vehicle compatibility binding missing " .. name, 3) end
    return value
end

-- Shared weapon-field ledger for validated Enhanced layouts. The Memory bridge
-- is the sole writer; logical claims compose by priority, then stable name.
local function create_weapon_backend(d)
    local api, fields, aliases, unsupported = {}, {}, {}, {}
    local rejected_order = {}
    local function reject(id, row)
        if not unsupported[id] then rejected_order[#rejected_order+1]=id end
        unsupported[id]=row
        while #rejected_order>64 do unsupported[table.remove(rejected_order,1)]=nil end
    end
    local physical_owner = 'vehicle.combat_backend'
    local function token(owner, ptr, field) return owner .. ':' .. tostring(ptr) .. ':' .. field end
    local function sorted(t) local r={} for k in pairs(t) do r[#r+1]=k end table.sort(r);return r end
    local function valid(value, spec)
        return type(value)=='number' and value==value and value>=spec.min and value<=spec.max
            and (spec.type=='float' or value%1==0)
    end
    local function matches(value, requested, spec)
        if type(value)~='number' then return false end
        if spec.mask then return value%1==0 and (value & spec.mask)==(requested & spec.mask) end
        if spec.type~='float' then return value==requested end
        return math.abs(value-requested)<=math.max(0.00001,math.abs(requested)*0.000001)
    end
    local function winner(row)
        local best, name
        for id, claim in pairs(row.claims) do
            if not best or claim.priority>best.priority or (claim.priority==best.priority and id<name) then
                best,name=claim,id
            end
        end
        return best,name
    end
    local function apply(row, force)
        local claim, name=winner(row)
        row.winner=name;row.requested=claim and claim.value or row.original
        local now=d.now()
        if not force and row.retry_at and now<row.retry_at and now>=row.retry_at-1000 then return false,row.detail end
        if not claim then
            -- An indeterminate identity during loading is a deferral, not a
            -- rejected write. Keep the original and the real-failure budget.
            local guarded, same, why = pcall(row.guard)
            if guarded and same == nil then
                row.status='RESTORE_PENDING';row.detail=why or 'Context unavailable; restoration retained'
                row.retry_at=now+250
                return false,row.detail
            end
        end
        if not force and (row.failures or 0)>=4 then return false,row.detail end
        local ok, result, status, detail
        local previous_applied=row.applied
        if claim then
            if not d.allowed() then row.status='SUSPENDED';row.detail='Gameplay context unavailable';return false,row.detail end
            ok,result=d.memory.WriteIfChanged(physical_owner,row.key,row.address,claim.value,row.spec.type,row.guard,row.spec.mask)
        else
            ok,result,status,detail=d.memory.Restore(physical_owner,row.key)
        end
        local guarded,same=pcall(row.guard)
        local observed=guarded and same==true and d.memory.Read(row.address,row.spec.type) or nil
        row.applied=observed
        if ok then
            row.failures=0;row.retry_at=nil;row.detail=detail
            row.status=status=='EXTERNALLY_MODIFIED' and 'RELINQUISHED' or (claim and 'APPLIED' or 'RESTORED')
        else
            row.failures=(row.failures or 0)+1;row.retry_at=now+250
            row.status=claim and 'WRITE_PENDING' or 'RESTORE_PENDING'
            row.detail=("%s; field=%s expected=%s observed=%s requested=%s winner=%s")
                :format(tostring(result),tostring(row.spec.field),tostring(previous_applied),
                    tostring(observed),tostring(row.requested),tostring(row.winner or 'baseline'))
        end
        if not ok then return false,row.detail end
        return true,result
    end
    function api.Snapshot(owner,ptr,field,address,value_type)
        local id=token(owner,ptr,field)
        local prior=aliases[id]
        if prior then
            local ok,original=d.memory.Snapshot(physical_owner,prior.key,prior.address,prior.spec.type,prior.guard,prior.spec.mask)
            if not ok then return false,original end
            return true,prior.original
        end
        local spec,why=d.describe(owner,ptr,field,address,value_type)
        if not spec then
            reject(id,{record=ptr,field=field,support='UNAVAILABLE',status='UNSUPPORTED',detail=why,owners={},attempt_owner=owner,address=address,value_type=value_type})
            return false,why
        end
        if unsupported[id] then
            unsupported[id]=nil
            for i=#rejected_order,1,-1 do if rejected_order[i]==id then table.remove(rejected_order,i) end end
        end
        local key=tostring(ptr)..':'..spec.field
        local row=fields[key]
        if row and (row.address~=address or row.spec.type~=value_type or row.spec.mask~=spec.mask) then return false,'Canonical field mismatch' end
        local guard=row and row.guard or spec.guard
        local ok, original=d.memory.Snapshot(physical_owner,key,address,value_type,guard,spec.mask)
        if not ok then return false,original end
        if not valid(original,spec) then
            if not row then d.memory.Restore(physical_owner,key) end
            local why=('Unsupported baseline for %s: value=%s type=%s ptr=%s offset=%s hash=%s class=%s owner=%s bounds=[%s,%s]')
                :format(spec.field,tostring(original),type(original),tostring(ptr),tostring(address-ptr),
                    tostring(spec.hash),tostring(spec.record_type),tostring(owner),tostring(spec.min),tostring(spec.max))
            local owners={}
            if row then for _,claim in pairs(row.claims) do
                owners[#owners+1]={owner=claim.owner,field=claim.field,requested=claim.value,priority=claim.priority}
            end end
            reject(id,{record=ptr,address=address,offset=address-ptr,field=spec.field,hash=spec.hash,
                kind=spec.kind,record_type=spec.record_type,value_type=value_type,
                rejected_value=tostring(original),rejected_type=type(original),min=spec.min,max=spec.max,
                attempt_owner=owner,owners=owners,winner=row and row.winner or nil,
                support=spec.evidence,status='BASELINE_REJECTED',detail=why})
            return false,why
        end
        if not row then
            row={key=key,ptr=ptr,address=address,spec=spec,guard=guard,original=original,
                applied=original,claims={},refs={},status='OBSERVED'}
            fields[key]=row
        end
        aliases[id]=row;row.refs[id]=true
        return true,row.original
    end
    function api.Write(owner,ptr,field,address,value,value_type)
        local ok,why=api.Snapshot(owner,ptr,field,address,value_type)
        if not ok then return false,why end
        local id=token(owner,ptr,field);local row=aliases[id]
        if not valid(value,row.spec) then return false,'Requested value outside supported field bounds' end
        local priority=d.priority(owner,field)
        local old=row.claims[id]
        local changed=not old or old.value~=value or old.priority~=priority
        row.claims[id]={value=value,priority=priority,owner=owner,field=field}
        if changed then row.failures=0;row.retry_at=nil end
        return apply(row,false)
    end
    function api.Release(owner,ptr,field)
        local id=token(owner,ptr,field);local row=aliases[id]
        if not row then return true end
        row.claims[id]=nil;row.refs[id]=nil;aliases[id]=nil
        local ok,why=apply(row,true)
        if not ok then
            -- Keep the alias as release debt, never revive the old request.
            aliases[id]=row;row.refs[id]=true
        elseif next(row.refs)==nil then fields[row.key]=nil end
        return ok,why
    end
    function api.ReleaseOwner(owner)
        local success=true
        for _,id in ipairs(sorted(aliases)) do
            local row=aliases[id]
            local prefix=owner..':'
            if id:sub(1,#prefix)==prefix then
                row.claims[id]=nil;row.refs[id]=nil;aliases[id]=nil
                local ok=apply(row,true)
                if not ok then aliases[id]=row;row.refs[id]=true;success=false
                elseif next(row.refs)==nil then fields[row.key]=nil end
            end
        end
        return success
    end
    function api.RestoreAll()
        -- Drop every request before the first restore. Never reapply another
        -- enabled preference while a session/unload cleanup is running.
        for _,row in pairs(fields) do row.claims={} end
        local success=true
        for _,key in ipairs(sorted(fields)) do
            local row=fields[key]
            if apply(row,true) then
                for id in pairs(row.refs) do aliases[id]=nil end
                fields[key]=nil
            else success=false end
        end
        return success
    end
    function api.Tick()
        local success=true
        for _,key in ipairs(sorted(fields)) do
            local row=fields[key]
            if row.status=='RESTORE_PENDING' then
                if not apply(row,false) then success=false
                elseif next(row.claims)==nil then
                    for id in pairs(row.refs) do aliases[id]=nil end
                    fields[key]=nil
                end
            end
        end
        return success
    end
    function api.Has(owner,ptr,field) return aliases[token(owner,ptr,field)]~=nil end
    function api.Baseline(ptr,field,fallback)
        local row=fields[tostring(ptr)..':'..field]
        return row and row.original or fallback
    end
    function api.Effective(ptr,field,fallback)
        local row=fields[tostring(ptr)..':'..field]
        if not row then return fallback end
        local claim=winner(row)
        return claim and claim.value or row.original
    end
    function api.Diagnostics()
        local rows={}
        for _,key in ipairs(sorted(fields)) do
            local row=fields[key];local owners={}
            for _,id in ipairs(sorted(row.claims)) do
                local claim=row.claims[id]
                owners[#owners+1]={owner=claim.owner,field=claim.field,requested=claim.value,priority=claim.priority}
            end
            rows[#rows+1]={record=row.ptr,hash=row.spec.hash,kind=row.spec.kind,record_type=row.spec.record_type,
                field=row.spec.field,support=row.spec.evidence,original=row.original,requested=row.requested,
                applied=row.applied,owners=owners,winner=row.winner,status=row.status,detail=row.detail}
        end
        for _,id in ipairs(sorted(unsupported)) do rows[#rows+1]=unsupported[id] end
        return rows
    end
    function api.Verify(ptr)
        for _,row in pairs(fields) do
            if row.ptr==ptr and next(row.claims)~=nil then
                local ok,same=pcall(row.guard)
                if not ok or same~=true then return false end
                local observed=d.memory.Read(row.address,row.spec.type)
                local claim=winner(row)
                row.applied=observed
                if not matches(observed,claim.value,row.spec) then
                    row.status='UNVERIFIED';return false
                end
            end
        end
        return true
    end
    function api.Pending() for _,r in pairs(fields) do if r.status=='RESTORE_PENDING' then return true end end return false end
    return api
end

local function create_vehicle_system(deps)
    local log_info = require_binding("log_info", deps.log_info)
    local log_warn = require_binding("log_warn", deps.log_warn)
