    local is_on = require_binding("is_on", deps.is_on)
    local list_index = require_binding("list_index", deps.list_index)
    local slider_int = require_binding("slider_int", deps.slider_int)
    local slider_float = require_binding("slider_float", deps.slider_float)
    local repair_vehicle = require_binding("repair_vehicle", deps.repair_vehicle)
    local H = require_binding("H", deps.H)
    local Utils = require_binding("Utils", deps.Utils)
    local FeatureMgr = require_binding("FeatureMgr", deps.FeatureMgr)
    local Memory = require_binding("Memory", deps.Memory)
    local OwnedMemory = require_binding("OwnedMemory", deps.OwnedMemory)
    local Natives = require_binding("Natives", deps.Natives)
    local GTA = deps.GTA
    local PoolMgr = deps.PoolMgr
    local V3 = deps.V3
    local CExplosionArgs = deps.CExplosionArgs
    local eExplosionTag = deps.eExplosionTag
    local VehicleMods

    local function combat_record(category, action, detail, severity)
        local runtime = module_context and module_context.CScript and module_context.CScript.Runtime
        if runtime and type(runtime.RecordCombatDiagnostic) == "function" then
            pcall(runtime.RecordCombatDiagnostic, category, action, detail, severity)
        end
    end

    local function builtin_effective(key)
        return VehicleMods and VehicleMods.state
            and VehicleMods.state.builtin_effective
            and VehicleMods.state.builtin_effective[key] == true
    end

    -- Integrated vehicle weapon/maintenance lab. It intentionally shares CScript's
    -- scheduler and lifecycle instead of registering another tab, loop, or handler.
    local VehicleLab = {
        model = {
            lazer = Utils.Joaat("lazer"),
            hydra = Utils.Joaat("hydra"),
            oppressor2 = Utils.Joaat("oppressor2"),
            oppressor = Utils.Joaat("oppressor"),
