            oppressor2_missile = Utils.Joaat("AMMO_OPPRESSOR2_MISSILE"),
            deluxo_missile = Utils.Joaat("AMMO_OPPRESSOR_MISSILE"),
            ruiner_missile = Utils.Joaat("AMMO_SPACE_ROCKET"),
            subcar_missile = Utils.Joaat("AMMO_SUBCAR_MISSILE"),
            vigilante_missile = Utils.Joaat("AMMO_VIGILANTE_MISSILE"),
