    local function restricted_ammo_slots(vehicle)
        local model = entity_exists(vehicle) and vehicle_lab_u32(invoke_int(H.GET_ENTITY_MODEL, vehicle)) or 0
        local slots = VEHICLE_RESTRICTED_AMMO_SLOTS_BY_MODEL[model]
        return slots or VEHICLE_RESTRICTED_AMMO_FALLBACK_SLOTS, model,
            slots and "Enhanced freemode func_1006" or "compatibility fallback"
    end

    local function copy_ammo_slots(slots)
        local result = {}
        for index, slot in ipairs(slots or {}) do result[index] = slot end
        return result
    end

    local function format_ammo_readback(slots, readback)
        local parts = {}
        for _, slot in ipairs(slots or {}) do
            parts[#parts + 1] = ("slot%d=%s"):format(slot, tostring(readback and readback[slot]))
        end
        return #parts > 0 and table.concat(parts, " ") or "slots=none"
    end

