            if now-(access.last_tick or -100000)<35 then return end
            access.last_tick=now
            if not is_on("vehicle_bypass_player_restrictions")or not started or not bound or runtime_writes_suspended
                or read("InvokeBool",POWER_NATIVE.transition)~=false or not driving_input_available(local_player_id())then
