            end
            -- GTA can clear "trying to enter" as soon as a lock aborts the
            -- normal task. Keep our explicit entry target during its deadline.
            if a and a.entry_issued and now<(a.entry_deadline or 0)
                and(not power_number(target)or target==a.vehicle.handle)then
                target=a.vehicle.handle
            end
            if a and a.entry_issued and now>=(a.entry_deadline or 0)then
                access.last_outcome="entry timed out (game may still enforce a lock)"
                if not api.RestoreAccess()then access.phase="restoration pending"end
                return
            end
            if a and(target~=a.vehicle.handle or not access_current(a))then
                if not api.RestoreAccess()then access.phase="restoration pending";return end
                a=nil
            end
            if not power_number(target)or not pedpos then return end
            local targetpos=position(target)
            local maxdist=(target==trying or(a and a.entry_issued and target==a.vehicle.handle))
                and 30 or(fallback_distance or 12)
            if not targetpos or distance(pedpos,targetpos)>maxdist then return end
            local driver=read("InvokeInt",POWER_NATIVE.driver,target,-1,false)
            if not finite_number(driver)then return end
            if not a then
                local v,p=binding(target),binding(ped)
                if not v or not p then return end
                local cleanup=module_context and module_context.Cleanup
                if not cleanup or type(cleanup.Register)~="function"then return end
                a={vehicle=v,ped=p,pid=pid};access.lease=a
                if cleanup.Register("modules.vehicle","vehicle_access",function()return api.RestoreAccess()end)~=true then access.lease=nil;return end
            end
            if not access_current(a)then return end
            local locked=read("InvokeBool",0xF6AF6CB341349015,target,a.pid)
            if type(locked)~="boolean"then return end
            if locked then
                if a.lock_original==nil then a.lock_original=locked end
                a.lock_owned=true
