            -- Never use warp/carjack flags or issue tasks to a remote player.
            local doors_before=read("InvokeInt",0x25BC98A59C2EA962,target)
            local blocked=locked==true
                or(finite_number(doors_before)and doors_before%1==0
                    and doors_before>=2 and doors_before<=10)
                or read("InvokeBool",0x44D28D5DDFE5F68C,ped)==true
            if not a.entry_issued and blocked and(pressed or new_press or target==trying)then
                local seat=access_entry_seat(target,ped)
