                if not access_current(a)then return end
                local timeout=maxdist>=20 and 13000 or 6000
                local sent=invoke_void(0xC20E50AA46D09CA8,ped,target,timeout,seat,1.5,8388609,0)
                a.entry_issued=now;a.entry_deadline=now+timeout+1000;a.entry_seat=seat
                access.phase=sent==true and "local entry task requested"or"entry task call rejected"
                if sent~=true then access.last_outcome="entry task call rejected"end
