            -- Mission locks are separate from the network player-lock mask.
            local doors=read("InvokeInt",0x25BC98A59C2EA962,target)
            if finite_number(doors)and doors%1==0 and doors>=2 and doors<=10 then
                if not access_current(a)or not authority(a.vehicle,false,now)then return end
                a.door_original=doors
