            end
            if not a.exclusive_checked or(not a.exclusive and now-(a.exclusive_scan or 0)>=1000)then
                if not a.ptr then local ok,p=pcall(Memory.AllocInt);if not ok or not power_number(p)then return end;a.ptr=p end
                -- At most 32 player observations per second until an owner is found.
                for pid=0,31 do
                    if read("InvokeBool",0xB8DFD30D6973E135,pid)==true then
                        local other=read("InvokeInt",0x43A66C31C68491C0,pid)
                        if power_number(other)and other~=ped and read("InvokeBool",0xB09D25E77C33EB3F,target,other,a.ptr)==true then
                            local ok,index=pcall(Memory.ReadInt,a.ptr)
                            local owner=binding(other)
                            if ok and(index==0 or index==1)and owner then a.exclusive=owner;a.index=index;break end
                        end
                    end
                end
                a.exclusive_checked=true;a.exclusive_scan=now
            end
            if a.exclusive and same_entity(a.exclusive)and read("InvokeBool",0xB09D25E77C33EB3F,target,a.exclusive.handle,a.ptr)==true then
                if not access_current(a)or not authority(a.vehicle,false,now)then return end
                a.exclusive_owned=true
                invoke_void(0xB5C51B5502E85E83,target,0,a.index)
            end
            access.phase="entry flags requested"
        end
        function api.AccessPending()return access.lease~=nil end
        function api.SessionChanged()
            session_generation=session_generation+1
            access.pressed=false
            s.assignment=nil;s.pending=nil;s.active=false;s.unverified=nil;brake_clock=nil
            if s.driver then s.driver.generation=-1 end
            if access.lease then
                access.lease.vehicle.generation=-1
                -- The old session owns these flags now; free only private memory.
                finish_access(access.lease)
            end
            s.phase="cancelled";s.detail="Session changed. Call your active personal vehicle again."
            return api.Cleanup(now_ms())
        end

        function api.Snapshot()
            return{phase=s.phase,detail=s.detail,assigned=s.assignment~=nil,active=s.active or s.pending==true,
                cleanup_pending=(s.driver~=nil or s.registered==true)and not(s.active or s.pending)or s.unverified~=nil,
                access_phase=access.phase,access_last_outcome=access.last_outcome}
        end
        function api.NeedsTick()return s.active or s.pending or s.driver~=nil or s.unverified~=nil or s.registered==true end
        function api.Brake(now)
            local instant,quick=is_on("vehicle_instant_brake"),is_on("vehicle_quick_brake")
            if not instant and not quick then brake_clock=nil;return end
            local vehicle=local_vehicle();local identity=power_context(vehicle)
            if not identity or not driving_input_available(identity.pid)then brake_clock=nil;return end
            local x,y,z,fx,fy,fz=traction_vectors(vehicle)
            if not finite_number(x)or not finite_number(y)or not finite_number(z)or not finite_number(fx)or not finite_number(fy)or not finite_number(fz)
                or math.abs(x)>1000 or math.abs(y)>1000 or math.abs(z)>1000 or math.abs(fx)>1.5 or math.abs(fy)>1.5 or math.abs(fz)>1.5 then brake_clock=nil;return end
            local forward=x*fx+y*fy+z*fz
            local class=read("InvokeInt",0x29439776AAA00A62,vehicle)
            if not finite_number(class)or class%1~=0 or class<0 or class>22 then brake_clock=nil;return end
            -- Cars/boats use brake/reverse (72) while going forward and throttle
            -- (71) while reversing. Aircraft use their physical decelerate action.
            local control=(class==15 or class==16)and 88 or(forward< -0.2 and 71 or 72)
            if class==14 then
                for _,name in ipairs({"submersible","submersible2","avisa","kosatka"})do
                    if (identity.model & 0xFFFFFFFF)==(Utils.Joaat(name) & 0xFFFFFFFF)then control=130;break end
                end
            end
            local input=read("InvokeFloat",0xEC3C9B8D5327B563,0,control)
            local frame=read("InvokeInt",0xFC8202EFC642E6F2)
            now=tonumber(now)or now_ms()
            if not finite_number(input)or input<=0.05 or not finite_number(frame)then brake_clock=nil;return end
            -- At standstill the shared brake/reverse control is reverse, not an
            -- ongoing brake latch; it must be allowed to start reversing.
            if class~=15 and class~=16 and math.abs(forward)<0.2 and x*x+y*y+z*z<0.09 then
                local ax,ay,az=vector_components(invoke_vec3(0x213B91045D09B983,vehicle))
                if not instant or not finite_number(ax)or not finite_number(ay)or not finite_number(az)or ax*ax+ay*ay+az*az<0.01 then brake_clock=nil;return end
            end
            if brake_clock and brake_clock.frame==frame and same_power_context(identity,brake_clock.identity)then return end
            local dt=read("InvokeFloat",0x15C40837039FFAF7)
            if not finite_number(dt)or dt<=0 or dt>0.1 then brake_clock=nil;return end
            brake_clock={frame=frame,identity=identity}
            if not same_power_context(identity,power_context(vehicle))then brake_clock=nil;return end
            if instant then
                if invoke_void(0x1C99BB7B6E96D16F,vehicle,0.0,0.0,0.0)==true
                    and same_power_context(identity,power_context(vehicle))then
                    invoke_void(0x8339643499D1222E,vehicle,0.0,0.0,0.0)
                end
