            end
            local speed=math.sqrt(x*x+y*y+z*z)
            if speed<0.01 then return end
            -- Add 18 m/s^2 at full brake, integrated by elapsed game frame time.
            -- Scale velocity uniformly so grip, heading and steering stay intact.
            local delta=math.min(speed,18.0*math.min(1,input)*dt)
            local scale=math.max(0,(speed-delta)/speed)
            invoke_void(0x1C99BB7B6E96D16F,vehicle,x*scale,y*scale,z*scale)
        end
        return api
    end)()
    -- VEHICLE_BRAKE_DELIVERY81_END

    -- Enhanced b1158g9 input enum 0xCE566A0F: INPUT_VEH_CAR_JUMP=387.
    -- Legacy 350 is INPUT_REPLAY_CYCLEMARKERRIGHT here, so it never observes
    -- the actual jump button. Source excerpt: enhanced_b1158_vehicle_input_enum.json.
    local VEHICLE_JUMP_INPUT=387

    local function jump_note(status,identity,detail)
        local state=VehicleMods.state
        local record=state.jump_diagnostic or {emitted=0}
        state.jump_diagnostic=record
        record.status,record.detail=status,detail
        local signature=table.concat({status,identity and identity.vehicle or 0,identity and identity.address or 0,
            identity and identity.model or 0,identity and identity.generation or 0,detail},":")
        if record.signature==signature then return end
        local clock=power_native("InvokeInt",0x9CD27B0045628463) -- GET_GAME_TIMER
        if not finite_number(clock) or clock<0 then return end
        if not record.window_ms or clock-record.window_ms>=5000 then
            record.window_ms,record.emitted=clock,0
        elseif clock<record.window_ms then record.window_ms=clock end
        -- A single bounded record survives controller/identity changes. A timer
        -- reset does not replenish this two-lines-per-five-seconds log budget.
        if record.emitted>=2 then return end
        record.emitted=record.emitted+1;record.signature=signature
        pcall(log_info,("Unlimited Jump: %s vehicle=%s model=%s input=%d %s")
            :format(status,tostring(identity and identity.vehicle or 0),
                tostring(identity and identity.model or 0),VEHICLE_JUMP_INPUT,detail))
    end

    function VehicleMods.restore_jump()
        VehicleMods.state.jump_controller=nil -- No native jump state is modified.
        return true
    end

    function VehicleMods.jump_frame(vehicle)
        -- No documented jump recharge/state setter exists in this host build.
        -- Preserve the native ability: never suppress its input or synthesize
        -- forces under the name Unlimited Jump. Retain the ID for old profiles.
        VehicleMods.restore_jump()
        if not is_on("vehicle_unlimited_jump") then return end
        jump_note("UNAVAILABLE",nil,"native jump reset is unverified; stock jump preserved")
        if type(deps.set_toggle)=="function" then deps.set_toggle("vehicle_unlimited_jump",false) end
    end

    function VehicleMods.capture_ammo(vehicle)
        local snapshots = VehicleMods.state.ammo_snapshots
        local address = power_address("HandleToPointer", vehicle)
        if not address then return nil end
        if snapshots[vehicle] and snapshots[vehicle].address == address then return snapshots[vehicle] end
        -- Same integer handle can represent a newly streamed vehicle. Never
        -- restore or inherit the previous physical vehicle's ammo snapshot.
        snapshots[vehicle] = nil
        local count = 0
        for _ in pairs(snapshots) do count = count + 1 end
        if count > 0 and not VehicleMods.restore_ammo() then return nil end
        local slots, model, source = restricted_ammo_slots(vehicle)
        local restricted = {}
        for _, slot in ipairs(slots) do
            restricted[slot] = invoke_int(H.GET_VEHICLE_WEAPON_RESTRICTED_AMMO, vehicle, slot)
        end
        local snapshot = {
            address = address,
            slots = copy_ammo_slots(slots),
            model = model,
            slot_source = source,
            restricted = restricted,
            bombs = invoke_int(H.GET_VEHICLE_BOMB_AMMO, vehicle),
            countermeasures = invoke_int(H.GET_VEHICLE_COUNTERMEASURE_AMMO, vehicle),
        }
        snapshots[vehicle] = snapshot
        return snapshot
    end

    function VehicleMods.apply_infinite_ammo(vehicle, now)
        local snapshot = VehicleMods.capture_ammo(vehicle)
        if not snapshot then return false end
        local slots = snapshot and snapshot.slots or VEHICLE_RESTRICTED_AMMO_FALLBACK_SLOTS
        local all_applied = true

        -- Enhanced freemode can replace the documented -1 sentinel with the
        -- vehicle's stock launcher capacity on a later script tick. Reassert a
        -- large finite count every CScript tick so limited launchers such as the
        -- Oppressor Mk II refill even when Rockstar's capacity layer runs too.
        for _, slot in ipairs(slots) do
            if (tonumber(snapshot.restricted[slot]) or -1) >= 0 then
                local current = invoke_int(H.GET_VEHICLE_WEAPON_RESTRICTED_AMMO, vehicle, slot)
                if current ~= VEHICLE_AMMO_REFILL then
                    all_applied = invoke_void(H.SET_VEHICLE_WEAPON_RESTRICTED_AMMO,
                        vehicle, slot, VEHICLE_AMMO_REFILL) == true and all_applied
                    all_applied = invoke_int(H.GET_VEHICLE_WEAPON_RESTRICTED_AMMO,
                        vehicle, slot) == VEHICLE_AMMO_REFILL and all_applied
                end
            end
        end
        if snapshot.bombs >= 0 and invoke_int(H.GET_VEHICLE_BOMB_AMMO, vehicle) ~= 99 then
            all_applied = invoke_void(H.SET_VEHICLE_BOMB_AMMO, vehicle, 99) == true and all_applied
            all_applied = invoke_int(H.GET_VEHICLE_BOMB_AMMO, vehicle) == 99 and all_applied
        end
        if snapshot.countermeasures >= 0 and invoke_int(H.GET_VEHICLE_COUNTERMEASURE_AMMO, vehicle) ~= 99 then
            all_applied = invoke_void(H.SET_VEHICLE_COUNTERMEASURE_AMMO, vehicle, 99) == true and all_applied
            all_applied = invoke_int(H.GET_VEHICLE_COUNTERMEASURE_AMMO, vehicle) == 99 and all_applied
        end

        -- Mounted hashes are not ped-inventory weapons. Restricted vehicle slots,
        -- bomb counts and countermeasure counts are the authoritative counters.

        local state = VehicleMods.state
        state.ammo_active_slots = copy_ammo_slots(slots)
        state.ammo_active_model = snapshot and snapshot.model or 0
        state.ammo_slot_source = snapshot and snapshot.slot_source or "compatibility fallback"
        now = tonumber(now) or now_ms()
        if now - state.last_ammo_verify_ms >= VEHICLE_AMMO_VERIFY_MS then
            state.last_ammo_verify_ms = now
            local readback = {}
            for _, slot in ipairs(slots) do
                readback[slot] = invoke_int(H.GET_VEHICLE_WEAPON_RESTRICTED_AMMO, vehicle, slot)
            end
            state.ammo_last_readback = readback
            local readback_text = format_ammo_readback(slots, readback)
            local signature = table.concat({ tostring(vehicle), tostring(state.ammo_active_model), readback_text }, ":")
            if state.ammo_log_signature ~= signature then
                state.ammo_log_signature = signature
                log_info(("Vehicle Infinite Ammo refill: vehicle=%s model=0x%08X requested=%d %s source=%s refresh=continuous")
                    :format(
                        tostring(vehicle), vehicle_lab_u32(state.ammo_active_model), VEHICLE_AMMO_REFILL,
                        readback_text, tostring(state.ammo_slot_source)))
            end
        end
        state.ammo_verified = all_applied
        return all_applied
    end

    function VehicleMods.restore_ammo()
        local state = VehicleMods.state
        local snapshots = state.ammo_snapshots
        local restored = true
        for vehicle, snapshot in pairs(snapshots) do
            local released = true
            local exists = entity_exists(vehicle)
            local address = exists and power_address("HandleToPointer", vehicle) or nil
            if exists and not address then
                -- Pointer conversion can fail transiently while the same live
                -- vehicle still owns our refill. Preserve the restore debt.
                released = false
            elseif exists and address == snapshot.address then
                for _, slot in ipairs(snapshot.slots or VEHICLE_RESTRICTED_AMMO_FALLBACK_SLOTS) do
                    if snapshot.restricted[slot] >= 0 then
                        released = invoke_void(H.SET_VEHICLE_WEAPON_RESTRICTED_AMMO,
                            vehicle, slot, snapshot.restricted[slot]) == true and released
                        released = invoke_int(H.GET_VEHICLE_WEAPON_RESTRICTED_AMMO, vehicle, slot)
                            == snapshot.restricted[slot] and released
                    end
                end
                if snapshot.bombs >= 0 then
                    released = invoke_void(H.SET_VEHICLE_BOMB_AMMO, vehicle, snapshot.bombs) == true and released
                    released = invoke_int(H.GET_VEHICLE_BOMB_AMMO, vehicle) == snapshot.bombs and released
                end
                if snapshot.countermeasures >= 0 then
                    released = invoke_void(H.SET_VEHICLE_COUNTERMEASURE_AMMO, vehicle, snapshot.countermeasures) == true and released
                    released = invoke_int(H.GET_VEHICLE_COUNTERMEASURE_AMMO, vehicle) == snapshot.countermeasures and released
                end
            end
            if released then snapshots[vehicle] = nil else restored = false end
        end

        state.ammo_weapon_hashes = {}
        state.ammo_last_readback = {}
        state.ammo_active_slots = {}
        state.ammo_active_model = 0
        state.ammo_slot_source = "none"
        state.ammo_log_signature = nil
        state.last_ammo_verify_ms = -100000
        return restored
    end

    function VehicleMods.ensure_projectile_pointers()
        local state = VehicleMods.state
        if state.projectile_coords_ptr ~= 0 and state.projectile_object_ptr ~= 0 then return true end
        if not (Memory and type(Memory.Alloc) == "function" and type(Memory.AllocInt) == "function"
                and type(Memory.WriteInt) == "function" and type(Memory.ReadInt) == "function") then
            log_error_once("vehicle_projectile_pointers", "Projectile pointer APIs are unavailable.")
            return false
        end
        local ok_coords, coords = pcall(Memory.Alloc, 24)
        local ok_object, object = pcall(Memory.AllocInt)
        if not ok_coords or not ok_object or type(coords) ~= "number" or coords == 0
            or type(object) ~= "number" or object == 0 then
            log_error_once("vehicle_projectile_pointers", "Could not allocate projectile buffers.")
            return false
        end
        state.projectile_coords_ptr = coords
        state.projectile_object_ptr = object
        return true
    end

    function VehicleMods.ensure_target_pointer()
        local state = VehicleMods.state
        if state.lock_target_ptr ~= 0 then return true end
        if not (Memory and type(Memory.AllocInt) == "function"
                and type(Memory.WriteInt) == "function" and type(Memory.ReadInt) == "function") then
            log_error_once("vehicle_target_pointer", "Lock-on target pointer APIs are unavailable.")
            return false
        end
        local ok, pointer = pcall(Memory.AllocInt)
        if not ok or type(pointer) ~= "number" or pointer == 0 then
            log_error_once("vehicle_target_pointer", "Could not allocate lock-on target buffer.")
            return false
        end
        state.lock_target_ptr = pointer
        return true
    end

function VehicleMods.projectile_changes_requested()
    return false -- Native Deluxo projectiles need no discovery or scripted steering.
end

    function VehicleMods.network_session_active()
        if not (Natives and H.NETWORK_IS_SESSION_ACTIVE) then return false end
        local ok, active = pcall(Natives.InvokeBool, H.NETWORK_IS_SESSION_ACTIVE)
        return ok and active == true
    end

    function VehicleMods.direct_projectile_allowed()
        if Natives == nil or Memory == nil then return false, "Projectile APIs are unavailable" end
        if not H.NETWORK_IS_SESSION_ACTIVE then return false, "Session state native is unavailable" end
        local ok_active, active = pcall(Natives.InvokeBool, H.NETWORK_IS_SESSION_ACTIVE)
        if not ok_active then return false, "Session state is unavailable" end
        if active ~= true then return true, "Story Mode" end
        return true, "Online session (local-owned projectile gate)"
    end

    local function projectile_speed(handle)
        if not entity_exists(handle) then return 0.0 end
        local velocity = invoke_vec3(H.GET_ENTITY_VELOCITY, handle)
        local x, y, z = vector_components(velocity)
        if not x then return 0.0 end
        return math.sqrt(x * x + y * y + z * z)
    end

    local function projectile_launch_radius()
        local multiplier = math.max(0.25, math.min(8.0,
            slider_float("vehicle_rocket_speed", 1.0)))
        -- This is only an acquisition gate, not missile range. It is deliberately
        -- tight enough to reject unrelated world projectiles while still covering
        -- a delayed object-pool appearance at the full Rocket Speed slider.
        return math.min(1500.0, 600.0 + multiplier * 110.0)
    end

    local function projectile_distance_from_vehicle(handle, vehicle)
        if not entity_exists(handle) or not entity_exists(vehicle) then return nil end
        local px, py, pz = vector_components(invoke_vec3(H.GET_ENTITY_COORDS, handle, false))
        local vx, vy, vz = vector_components(invoke_vec3(H.GET_ENTITY_COORDS, vehicle, false))
        if not (px and vx) then return nil end
        local dx, dy, dz = px - vx, py - vy, pz - vz
        return math.sqrt(dx * dx + dy * dy + dz * dz)
    end

    function VehicleMods.projectile_locality(physical, handle, native_owner_verified,
                                               vehicle, now, model_hash)
        if not VehicleMods.network_session_active() then return true, "offline" end
        if native_owner_verified == true then return true, "native-owner-filter" end

        local pointer = physical
        if pointer == nil and GTA and type(GTA.HandleToPointer) == "function" then
            local ok, value = pcall(GTA.HandleToPointer, handle)
            if ok then pointer = value end
        end
        local pointer_type = type(pointer)
        if pointer ~= nil and (pointer_type == "userdata" or pointer_type == "table") then
            local ok, net = pcall(function() return pointer.NetObject end)
            if ok and net ~= nil then
                local remote_ok, remote = pcall(function() return net.IsRemote end)
                if remote_ok and remote == true then return false, "remote-netobject" end

                local player_ok, player_id = pcall(function() return net.PlayerId end)
                if player_ok and tonumber(player_id) == tonumber(local_player_id()) then
                    return true, "local-player-netobject"
                end
                -- On current Cherax a non-remote CNetObject is local-owned even when
                -- PlayerId is an unset/transition value for a just-created missile.
                if remote_ok and remote == false then return true, "local-netobject" end
                return false, "unverified-netobject"
            end
        end

        -- Some locally created mounted missiles are visible as rendered CObjects
        -- before a CNetObject wrapper exists. Never use that as a general online
        -- ownership bypass: it is valid only during this exact local firing window.
        local state = VehicleMods.state
        now = tonumber(now) or now_ms()
        vehicle = tonumber(vehicle) or 0
        model_hash = vehicle_lab_u32(model_hash ~= nil and model_hash
            or (handle ~= 0 and invoke_int(H.GET_ENTITY_MODEL, handle) or 0))
        if state.projectile_window_active ~= true
            or now < (tonumber(state.projectile_window_start_ms) or 0)
            or now > (tonumber(state.projectile_window_end_ms) or 0)
            or vehicle == 0
            or vehicle ~= (tonumber(state.projectile_window_vehicle) or 0)
            or not VehicleMods.projectile_object_model_set[model_hash] then
            return false, "no-locality-proof"
        end

        local speed = projectile_speed(handle)
        if speed < 20.0 then return false, "unnetworked-not-moving" end
        local distance = projectile_distance_from_vehicle(handle, vehicle)
        if not distance or distance > projectile_launch_radius() then
            return false, "unnetworked-outside-launch-window"
        end
        return true, "unnetworked-local-launch-window"
    end


    -- Non-writing evidence is separate from active projectile ownership. It holds
    -- only scalar identities, never physical wrappers, timers or a paused writer.
    function VehicleMods.projectile_safety_history()
        local state=VehicleMods.state
        local generation=state.controller.session_generation or 0
        local history=state.projectile_safety
        if not history or history.generation~=generation then
            history={generation=generation,slots={},by_handle={},count=0,cursor=0}
            state.projectile_safety=history
        end
        return history
    end

    function VehicleMods.clear_projectile_safety()
        VehicleMods.state.projectile_safety=nil
    end

    function VehicleMods.projectile_history_filter(history,handle,address,insert)
        -- Fixed-size negative-only overflow evidence. Hash collisions can only
        -- deny extra steering, never grant a target. No live identity is evicted
        -- into a later arbitrary admission when the exact 128-row ledger is full.
        local words=history.overflow or {}
        if insert then history.overflow=words end
        local a=math.floor(tonumber(address) or 0)
        local h=math.floor(tonumber(handle) or 0)
        local first=((a >> 4) ~ (h*17)) & 4095
        local second=((a >> 17) ~ (h*131) ~ (a >> 7)) & 4095
        local hit=true
        for _,bit in ipairs({first,second}) do
            local index=(bit//64)+1;local mask=1 << (bit%64)
            if insert then words[index]=(words[index] or 0) | mask
            elseif ((words[index] or 0) & mask)==0 then hit=false end
        end
        return hit
    end

    function VehicleMods.reject_pending_projectile(handle,info)
        local p=info and (info.pending_resolution or info.resolution_evidence)
        if not p then return end
        local state=VehicleMods.state
        local history=VehicleMods.projectile_safety_history()
        VehicleMods.projectile_history_filter(history,handle,0,true)
        local index=history.by_handle[handle]
        if index and history.slots[index] then
            history.slots[index].target=0;history.slots[index].target_address=nil
        end
        if state.projectile_pending and state.projectile_pending.slots[p.slot]==handle then
            state.projectile_pending.slots[p.slot]=nil
            state.projectile_pending.count=math.max(0,state.projectile_pending.count-1)
        end
        info.pending_resolution,info.resolution_evidence=nil,nil
        info.fire_window_target,info.fire_window_target_address=0,nil
        info.buff_target,info.buff_target_address=0,nil
        if info.first_loss_reason==nil then info.first_loss_reason="pending-rejected" end
        info.buff_target_lost=true
    end

    function VehicleMods.pending_projectile_context(p,handle,now,ped,vehicle)
        local s=VehicleMods.state
        if not VehicleMods.projectile_changes_requested() or runtime_writes_suspended
            or now<p.first_ms or now>p.deadline or now-p.last_ms>200
            or cached_entity_handle_released(handle)
            or power_native("InvokeBool",H.DOES_ENTITY_EXIST,handle)~=true
            or power_native("InvokeInt",H.GET_ENTITY_TYPE,handle)~=3
            or power_native("InvokeInt",H.GET_ENTITY_MODEL,handle)~=p.model
            or s.projectile_window_id~=p.window_id or not s.projectile_window_active
            or s.projectile_window_ambiguous or s.projectile_window_source_key~=p.source_key
            or s.projectile_window_target~=p.target or s.projectile_window_target_address~=p.target_address
            or ped~=p.ped or vehicle~=p.vehicle
            or power_native("InvokeBool",H.DOES_ENTITY_EXIST,p.target)~=true
            or power_native("InvokeBool",H.IS_ENTITY_DEAD,p.target,false)~=false then return false end
        local recent=VehicleMods.projectile_safety_history().recent
        if not recent or recent.ambiguous or recent.source_key~=p.source_key
            or recent.target_key~=p.target_key then return false end
        local sample=VehicleMods.projectile_launch_sample(ped,vehicle,p.target,true)
        return sample and sample.source_key==p.source_key and sample.target_key==p.target_key
            and power_native("InvokeBool",POWER_NATIVE.networked,handle)==p.networked
            and (not p.networked or power_native("InvokeBool",POWER_NATIVE.control,handle)==true)
    end

    function VehicleMods.pending_projectile_owner(info,handle)
        local p=info.resolution_evidence
        if not p then return true end
        local ok,owned=pcall(function()
            local physical=GTA.HandleToPointer(handle)
            if physical:GetAddress()~=info.address then return false end
            if not p.networked then return true end
            local net=physical.NetObject
            return net~=nil and net.IsRemote==false and net.PlayerId==local_player_id()
        end)
        return ok and owned==true
    end

    function VehicleMods.begin_pending_projectile(info,handle,now)
        local s=VehicleMods.state
        local h=VehicleMods.projectile_safety_history()
        -- Only the selected-weapon native's explicit owner-filtered handle can
        -- enter recovery. Pool proximity/locality alone is not launch evidence.
        if info.native_owner_query~=true or info.buff_target_lost or h.by_handle[handle]
            or h.count>=128 or VehicleMods.projectile_history_filter(h,handle,0,false)
            or (info.fire_window_target or 0)==0 or not power_number(info.fire_window_target_address) then return false end
        local pending=s.projectile_pending or {slots={},count=0,cursor=0}
        s.projectile_pending=pending
        if pending.count>=16 then return false end
        local model=power_native("InvokeInt",H.GET_ENTITY_MODEL,handle)
        local networked=power_native("InvokeBool",POWER_NATIVE.networked,handle)
        if type(model)~="number" or model%1~=0 or model==0 or math.abs(model)>4294967295
            or type(networked)~="boolean" then return false end
        local p={first_ms=now,last_ms=now,deadline=math.min(now+320,s.projectile_window_end_ms),
            attempts=0,next_ms=now+25,model=model,networked=networked,
            ped=s.projectile_window_ped,vehicle=s.projectile_window_vehicle,
            source_key=s.projectile_window_source_key,window_id=info.fire_window_id,
            target=info.fire_window_target,target_address=info.fire_window_target_address,
            target_key=table.concat({info.fire_window_target,info.fire_window_target_address},":")}
        if not VehicleMods.pending_projectile_context(p,handle,now,p.ped,p.vehicle) then return false end
        for slot=1,16 do
            if not pending.slots[slot] then
                p.slot=slot;pending.slots[slot]=handle;pending.count=pending.count+1
                info.pending_resolution=p
                -- Do not hold an unreadable borrowed wrapper as future authority.
                if info.physical then s.projectile_entities[info.physical]=nil end
                info.physical,info.address=nil,nil
                return true
            end
        end
        return false
    end

    function VehicleMods.retry_pending_projectiles(now,ped,vehicle)
        local s=VehicleMods.state
        local pending=s.projectile_pending
        if not pending or pending.count==0 or not VehicleMods.projectile_changes_requested() then return end
        local attempted=0
        for _=1,16 do
            pending.cursor=pending.cursor%16+1
            local handle=pending.slots[pending.cursor]
            local info=handle and s.projectiles[handle]
            local p=info and info.pending_resolution
            if p and now>=p.next_ms then
                attempted=attempted+1;p.attempts=p.attempts+1;p.next_ms=now+25
                if p.attempts>8 or not VehicleMods.pending_projectile_context(p,handle,now,ped,vehicle) then
                    VehicleMods.reject_pending_projectile(handle,info)
                else
                    p.last_ms=now
                    local ok,physical=pcall(function()return GTA.HandleToPointer(handle)end)
                    local read,address=pcall(function()return physical:GetAddress()end)
                    if not ok or not read then address=0 end
                    if power_number(address) then
                        local owner=true
                        if p.networked then
                            local read,local_owner=pcall(function()
                                local net=physical.NetObject
                                return net~=nil and net.IsRemote==false and net.PlayerId==local_player_id()
                            end)
                            owner=read and local_owner==true
                        end
                        if not owner or (p.candidate and p.candidate~=address) then
                            VehicleMods.reject_pending_projectile(handle,info)
                        elseif not p.candidate then
                            p.candidate=address
                        elseif not VehicleMods.pending_projectile_context(p,handle,now,ped,vehicle)
                            or power_address("HandleToPointer",handle)~=address then
                            VehicleMods.reject_pending_projectile(handle,info)
                        else
                            -- Two separated readable observations, original command
                            -- and fresh ownership agree. Reconcile all negative and
                            -- known-identity history before capturing any target.
                            info.pending_resolution=nil
                            pending.slots[p.slot]=nil;pending.count=pending.count-1
                            info.address,info.physical=address,physical
                            s.projectile_addresses[address]=handle;s.projectile_entities[physical]=handle
                            VehicleMods.reconcile_projectile_history(info,handle,now)
                            if not info.buff_target_lost then info.resolution_evidence=p end
                        end
                    end
                end
                if attempted>=4 then break end
            end
        end
    end

    function VehicleMods.reconcile_projectile_history(info,handle,now)
        if info.fire_window_id==nil then return end
        local history=VehicleMods.projectile_safety_history()
        local state=VehicleMods.state
        -- Only an actual new discovery performs this bounded maintenance. OFF
        -- has no poll loop or pool walk. Unreadable identities remain quarantined.
        for _=1,8 do
            history.cursor=history.cursor%128+1
            local old=history.slots[history.cursor]
            if old then
                local exists=power_native("InvokeBool",H.DOES_ENTITY_EXIST,old.handle)
                local address=exists~=false and power_address("HandleToPointer",old.handle) or nil
                if exists==false or (address and address~=old.address) then
                    history.by_handle[old.handle]=nil
                    history.slots[history.cursor]=nil
                    history.count=history.count-1
                end
            end
        end
        local index=history.by_handle[handle]
        local old=index and history.slots[index] or nil
        if old and info.address and info.address~=old.address then
            history.slots[index]=nil;history.by_handle[handle]=nil
            history.count=history.count-1;old=nil
        end
        if old then
            -- Seeing the same live object again is not a fresh launch. Permit
            -- re-admission only when both associations agree and current source,
            -- target identity and downstream ownership guards still validate.
            if old.address~=info.address or old.source_key~=state.projectile_window_source_key
                or old.target==0 or old.target~=info.fire_window_target
                or old.target_address~=info.fire_window_target_address then
                info.fire_window_target=0;info.fire_window_target_address=nil
                if info.first_loss_reason==nil then
                    info.first_loss_reason="history-association-mismatch";info.first_loss_ms=now
                end
                info.buff_target_lost=true
            end
            info.rearm_known_identity=true
            return
        end
        local identity=power_number(info.address) and info.address or 0
        local excluded=VehicleMods.projectile_history_filter(history,handle,identity,false)
            or VehicleMods.projectile_history_filter(history,handle,0,false)
        if identity==0 and not excluded and VehicleMods.begin_pending_projectile(info,handle,now) then return end
        if identity==0 or history.count>=128 or excluded then
            VehicleMods.projectile_history_filter(history,handle,identity,true)
            info.fire_window_target=0;info.fire_window_target_address=nil
            if info.first_loss_reason==nil then
                info.first_loss_reason="history-identity-unavailable";info.first_loss_ms=now
                info.first_loss_detail=identity==0 and "identity-unavailable"
                    or history.count>=128 and "history-full" or "history-excluded"
            end
            info.buff_target_lost=true;info.rearm_history_unavailable=true
            return
        end
        for slot=1,128 do
            if not history.slots[slot] then
                history.slots[slot]={handle=handle,address=info.address,
                    source_key=state.projectile_window_source_key,
                    target=info.fire_window_target or 0,target_address=info.fire_window_target_address}
                history.by_handle[handle]=slot;history.count=history.count+1
                break
            end
        end
    end

    function VehicleMods.restore_projectiles()
        local state = VehicleMods.state
        if state.projectile_window_active and type(VehicleMods.finish_projectile_window) == "function" then
            VehicleMods.finish_projectile_window(now_ms(), "restore")
        end
        for handle,info in pairs(state.projectiles) do
            VehicleMods.reject_pending_projectile(handle,info)
            VehicleMods.record_projectile_end(handle,info,now_ms(),"controller-released")
        end
        state.projectile_pending=nil
        state.projectiles = {}
        state.projectile_addresses = {}
        state.projectile_entities = {}
        state.projectile_count = 0
        state.recent_vehicle_weapons = {}
        state.projectile_scan_active_until = 0
        state.last_projectile_scan_ms = -100000
        state.last_projectile_pool_scan_ms=-100000
        state.projectile_last_frame_ms=nil;state.projectile_frame_dt=nil
        state.instant_window_until = 0
        state.instant_shape_test = 0
        state.instant_shape_started_ms = 0
        state.instant_aim = nil
        state.instant_aim_entity = 0
        state.instant_processed = {}
        state.attack_was_pressed = false
        state.projectile_fire_pressed = false
        state.projectile_attribution_recent = nil
        state.buff_guidance_last_target = 0
        state.buff_guidance_log_signature = nil
    end



    function VehicleMods.projectile_debug_enabled()
        local diagnostics = module_context and module_context.CScript
            and module_context.CScript.Diagnostics
        return diagnostics and diagnostics.DebugMode == true
    end

    function VehicleMods.projectile_window_matches(now,ped,vehicle)
        local s=VehicleMods.state
        if not s.projectile_window_active or now<s.projectile_window_start_ms or now>s.projectile_window_end_ms
            or s.projectile_window_ped~=ped or s.projectile_window_vehicle~=vehicle
            or (s.controller.session_generation or 0)~=s.projectile_window_generation
            or power_address("HandleToPointer",ped)~=s.projectile_window_ped_address
            or power_address("HandleToPointer",vehicle)~=s.projectile_window_vehicle_address
            or VehicleMods.mounted_seat(ped,vehicle)~=s.projectile_window_seat then return false end
        local ammo,weapon,ammo_hash=VehicleLab.current_ammo_context(ped,vehicle)
        return ammo==s.projectile_window_ammo_ptr and vehicle_lab_u32(ammo_hash)==s.projectile_window_ammo
            and vehicle_lab_u32(weapon)==s.projectile_window_weapon
            and vehicle_lab_u32(VehicleLab.get_current_vehicle_weapon(ped))==s.projectile_window_weapon
    end

    function VehicleMods.projectile_launch_sample(ped,vehicle,target,acquired)
        local ammo,weapon,ammo_hash=VehicleLab.current_ammo_context(ped,vehicle)
        local pa,va=power_address("HandleToPointer",ped),power_address("HandleToPointer",vehicle)
        local seat=VehicleMods.mounted_seat(ped,vehicle)
        if not pa or not va or seat==nil or not vehicle_lab_plausible_pointer(ammo)
            or vehicle_lab_u32(weapon)==0
            or vehicle_lab_u32(VehicleLab.get_current_vehicle_weapon(ped))~=vehicle_lab_u32(weapon) then return nil end
        local lock_state
        if target==nil then
            target=VehicleMods.get_native_locked_target(vehicle)
            lock_state=power_native("InvokeInt",H.GET_VEHICLE_HOMING_LOCKON_STATE,vehicle)
            acquired=lock_state==2
        end
        local address=target~=0 and power_address("HandleToPointer",target) or nil
        local raw_target,target_address_known=target,address~=nil
        if not acquired or not address then target,address=0,nil end
        local generation=VehicleMods.state.controller.session_generation or 0
        return {ped=ped,vehicle=vehicle,ped_address=pa,vehicle_address=va,seat=seat,
            weapon=vehicle_lab_u32(weapon),ammo=vehicle_lab_u32(ammo_hash),ammo_ptr=ammo,generation=generation,
            target=target,target_address=address,
            lock_state=lock_state,raw_target=raw_target,target_address_known=target_address_known,
            source_key=table.concat({generation,ped,pa,vehicle,va,seat,vehicle_lab_u32(weapon),ammo,vehicle_lab_u32(ammo_hash)},":"),
            target_key=table.concat({target,address or 0},":")}
    end

    function VehicleMods.note_projectile_attribution(now,sample,reason)
        local s=VehicleMods.state
        local history=VehicleMods.projectile_safety_history()
        local old=s.projectile_attribution_recent or history.recent
        local overlap=old and now>=old.sample_ms and now<=old.expires_ms
        local ambiguous=not sample or sample.target==0
            or (overlap and (old.ambiguous or old.source_key~=sample.source_key or old.target_key~=sample.target_key))
        -- One bounded burst record. This is a command/input observation, never
        -- per-projectile launch proof. No scan deadline or native shot is changed.
        local recent={sample_ms=now,expires_ms=now+650,
            source_key=sample and sample.source_key,target_key=sample and sample.target_key,
            ambiguous=ambiguous==true,reason=reason or "input"}
        history.recent=recent
        if VehicleMods.projectile_changes_requested() then s.projectile_attribution_recent=recent end
        if s.projectile_window_active and (ambiguous or not sample
            or s.projectile_window_source_key~=sample.source_key
            or s.projectile_window_target~=sample.target
            or s.projectile_window_target_address~=sample.target_address) then
            s.projectile_window_ambiguous=true
        end
        return ambiguous==true
    end

    function VehicleMods.begin_projectile_window(now, ped, vehicle, reason, command_sample)
        local state = VehicleMods.state
        local sample=command_sample or VehicleMods.projectile_launch_sample(ped,vehicle)
        local ambiguous=VehicleMods.note_projectile_attribution(now,sample,reason)
        if state.projectile_window_active then
            if now <= state.projectile_window_end_ms then return false end
            VehicleMods.finish_projectile_window(now, "replaced")
        end
        if not sample then return false end
        local ammo_ptr,weapon_hash,ammo_hash=sample.ammo_ptr,sample.weapon,sample.ammo
        state.projectile_window_ped,state.projectile_window_ped_address=sample.ped,sample.ped_address
        state.projectile_window_vehicle_address,state.projectile_window_seat=sample.vehicle_address,sample.seat
        state.projectile_window_generation=sample.generation
        state.projectile_window_source_key=sample.source_key
        state.projectile_window_target,state.projectile_window_target_address=sample.target,sample.target_address
        state.projectile_window_lock_state=sample.lock_state
        state.projectile_window_raw_target=sample.raw_target
        state.projectile_window_target_address_known=sample.target_address_known
        local observer=state.instant_lock and state.instant_lock.projectile_observation
        local observer_bound,observer_same_ms,fire_control
        -- Diagnostic equality of the source components available to both paths.
        -- The observer's WeaponInfo pointer is not independently resampled here;
        -- matching milliseconds is sample timing, never a shot acknowledgement.
        if observer then
            if observer.ms~=nil then observer_same_ms=observer.ms==now end
            if type(observer.context_key)=="string" and observer.weapon_ptr~=nil
                and sample.generation~=nil and sample.ped~=nil and sample.ped_address~=nil
                and sample.vehicle~=nil and sample.vehicle_address~=nil and sample.seat~=nil
                and sample.weapon~=nil and sample.ammo_ptr~=nil then
                observer_bound=observer.context_key==table.concat({sample.generation,sample.ped,sample.ped_address,
                    sample.vehicle,sample.vehicle_address,sample.seat,sample.weapon,observer.weapon_ptr,sample.ammo_ptr},":")
            end
        end
        local input_context=state.controller.context
        if input_context and input_context.ped==sample.ped and input_context.vehicle==sample.vehicle
            and input_context.weapon_hash==sample.weapon then fire_control=input_context.fire_control end
        state.projectile_window_pre_input_ms=observer and observer.ms
        state.projectile_window_pre_input_lock_state=observer and observer.lock_state
        state.projectile_window_pre_input_target=observer and observer.target
        state.projectile_window_pre_input_target_address=observer and observer.target_address
        state.projectile_window_pre_input_source_bound=observer_bound
        state.projectile_window_pre_input_same_ms=observer_same_ms
        state.projectile_window_fire_control=fire_control
        state.projectile_window_reason=reason
        state.projectile_window_ambiguous=ambiguous
        state.projectile_window_active = true
        state.projectile_window_id = state.projectile_window_id + 1
        state.projectile_window_start_ms = now
        state.projectile_window_end_ms = now + 650
        state.projectile_scan_active_until = state.projectile_window_end_ms
        state.projectile_window_vehicle = vehicle
        state.projectile_window_weapon = vehicle_lab_u32(weapon_hash)
        state.projectile_window_ammo = vehicle_lab_u32(ammo_hash)
        state.projectile_window_ammo_ptr = ammo_ptr
        state.projectile_window_detection_start = state.projectile_detections
        state.projectile_window_handle_calls_start = state.projectile_handle_calls
        state.projectile_window_handle_hits_start = state.projectile_handle_hits
        state.projectile_window_coords_calls_start = state.projectile_coords_calls
        state.projectile_window_coords_hits_start = state.projectile_coords_hits
        state.projectile_window_pool_scans_start = state.projectile_pool_scans
        state.projectile_window_pool_candidates_start = state.projectile_pool_candidates
        state.projectile_probe_variant = 0
        state.projectile_probe_logged = {}
        if VehicleMods.projectile_debug_enabled() then
            log_info(("Projectile discovery begin id=%d reason=%s startMs=%d endMs=%d vehicle=%s weapon=0x%08X ammo=0x%08X ammoPtr=0x%X")
                :format(
                    state.projectile_window_id, tostring(reason or "manual"), now, state.projectile_window_end_ms,
                    tostring(vehicle), state.projectile_window_weapon, state.projectile_window_ammo,
                    tonumber(ammo_ptr) or 0))
        end
        return true
    end

    function VehicleMods.finish_projectile_window(now, reason)
        local state = VehicleMods.state
        if not state.projectile_window_active then return false end
        if VehicleMods.projectile_debug_enabled() then
            log_info(("Projectile discovery end id=%d reason=%s startMs=%d plannedEndMs=%d actualEndMs=%d detections=%d handleCalls=%d handleHits=%d coordsCalls=%d coordsHits=%d poolScans=%d poolCandidates=%d")
                :format(
                    state.projectile_window_id, tostring(reason or "elapsed"), state.projectile_window_start_ms,
                    state.projectile_window_end_ms, now,
                    state.projectile_detections - state.projectile_window_detection_start,
                    state.projectile_handle_calls - state.projectile_window_handle_calls_start,
                    state.projectile_handle_hits - state.projectile_window_handle_hits_start,
                    state.projectile_coords_calls - state.projectile_window_coords_calls_start,
                    state.projectile_coords_hits - state.projectile_window_coords_hits_start,
                    state.projectile_pool_scans - state.projectile_window_pool_scans_start,
                    state.projectile_pool_candidates - state.projectile_window_pool_candidates_start))
        end
        state.projectile_window_active = false
        return true
    end

    local function projectile_pointer_address(pointer)
        local pointer_type = type(pointer)
        if pointer == nil or (pointer_type ~= "userdata" and pointer_type ~= "table")
            or type(pointer.GetAddress) ~= "function" then
            return 0
        end
        local ok, address = pcall(pointer.GetAddress, pointer)
        return ok and tonumber(address) or 0
    end

    local function projectile_pointer_model(pointer, handle)
        local pointer_type = type(pointer)
        if pointer ~= nil and (pointer_type == "userdata" or pointer_type == "table") then
            local ok, model = pcall(function()
                return pointer.ModelInfo and pointer.ModelInfo.Model or 0
            end)
            if ok and type(model) == "number" and model ~= 0 then return vehicle_lab_u32(model) end
        end
        return handle ~= 0 and vehicle_lab_u32(invoke_int(H.GET_ENTITY_MODEL, handle)) or 0
    end

    function VehicleMods.match_rendered_projectile(x, y, z)
        local state = VehicleMods.state
        local best, best_distance
        local ok, source, _, next_cursor = visit_entity_pool(
            "GetRenderedObjects", "GetCurrentObjectCount", "GetMaxObjectCount",
            "GetCObject", "GetObject", {
                cap = 4096,
                start = state.projectile_indexed_cursor,
                budget = 128,
            }, function(pointer, handle)
                state.projectile_pool_candidates = state.projectile_pool_candidates + 1
                if handle ~= 0 and entity_exists(handle)
                    and state.projectiles[handle] == nil then
                    local model_hash = projectile_pointer_model(pointer, handle)
                    if VehicleMods.projectile_object_model_set[model_hash] then
                        local coords = invoke_vec3(H.GET_ENTITY_COORDS, handle, false)
                        local ox, oy, oz = vector_components(coords)
                        if ox then
                            local dx, dy, dz = ox - x, oy - y, oz - z
                            local distance = dx * dx + dy * dy + dz * dz
                            if distance <= 144.0 and (best_distance == nil or distance < best_distance) then
                                best_distance = distance
                                best = {
                                    handle = handle,
                                    physical = pointer,
                                    address = projectile_pointer_address(pointer),
                                    model = model_hash,
                                    source = "coords-object-pool",
                                }
                            end
                        end
                    end
                end
                return false
            end)
        if ok then
            state.projectile_pool_scans = state.projectile_pool_scans + 1
            state.projectile_pool_source = source
            state.projectile_indexed_cursor = next_cursor or state.projectile_indexed_cursor
        end
        return best
    end

    -- GTA Enhanced can return false for both projectile query natives on mounted
    -- missiles. Current Cherax documents CObject.ModelInfo but not IsProjectile(),
    -- so the pool fallback classifies the seven Rockstar CAmmoRocketInfo projectile
    -- models directly. Candidates are then subjected to the same local-ownership
    -- gate used by native owner=false results.
    function VehicleMods.scan_rendered_projectile(vehicle, now)
        local state = VehicleMods.state
        if not entity_exists(vehicle) then return nil end
        local vehicle_coords = invoke_vec3(H.GET_ENTITY_COORDS, vehicle, false)
        local vx, vy, vz = vector_components(vehicle_coords)
        if not vx then return nil end
        local radius = projectile_launch_radius()
        local radius_sq = radius * radius
        local best, best_score
        local ok, source, _, next_cursor = visit_entity_pool(
            "GetRenderedObjects", "GetCurrentObjectCount", "GetMaxObjectCount",
            "GetCObject", "GetObject", {
                cap = 4096,
                start = state.projectile_indexed_cursor,
                budget = 192,
            }, function(pointer, handle)
                state.projectile_pool_candidates = state.projectile_pool_candidates + 1
                if handle == 0 or not entity_exists(handle)
                    or handle == vehicle
                    or state.instant_processed[handle] ~= nil
                    or state.projectiles[handle] ~= nil then
                    return false
                end

                local model_hash = projectile_pointer_model(pointer, handle)
                if not VehicleMods.projectile_object_model_set[model_hash] then return false end

                local coords = invoke_vec3(H.GET_ENTITY_COORDS, handle, false)
                local x, y, z = vector_components(coords)
                if not x then return false end
                local dx, dy, dz = x - vx, y - vy, z - vz
                local distance_sq = dx * dx + dy * dy + dz * dz
                if distance_sq > radius_sq then return false end

                local local_ok, locality = VehicleMods.projectile_locality(
                    pointer, handle, false, vehicle, now, model_hash)
                if not local_ok then return false end

                local speed = projectile_speed(handle)
                -- Nearest wins, with a tiny moving-object preference for ties.
                local score = distance_sq - math.min(speed, 5000.0) * 0.001
                if best_score == nil or score < best_score then
                    best_score = score
                    best = {
                        handle = handle,
                        physical = pointer,
                        address = projectile_pointer_address(pointer),
                        model = model_hash,
                        source = "object-pool:" .. tostring(locality),
                        locality = locality,
                        owner_verified = locality ~= "unnetworked-local-launch-window",
                    }
                end
                return false
            end)
        if ok then
            state.projectile_pool_scans = state.projectile_pool_scans + 1
            state.projectile_pool_source = source
            state.projectile_indexed_cursor = next_cursor or state.projectile_indexed_cursor
        end
        return best
    end

    function VehicleMods.log_projectile_probe(api, subject_name, source, hash, owner, found, result)
        local state = VehicleMods.state
        result = result or {}
        state.projectile_last_api = api
        state.projectile_last_subject = subject_name
        state.projectile_last_query_source = source
        state.projectile_last_query_hash = vehicle_lab_u32(hash)
        state.projectile_last_owner_filter = owner == true
        state.projectile_last_found = found == true
        state.projectile_last_returned_handle = tonumber(result.handle) or 0
        state.projectile_last_returned_address = tonumber(result.address) or 0
        state.projectile_last_returned_model = vehicle_lab_u32(result.model)
        if not VehicleMods.projectile_debug_enabled() then return end
        local outcome = found ~= true and "miss"
            or ((tonumber(result.handle) or 0) ~= 0 and "handle")
            or ((tonumber(result.address) or 0) ~= 0 and "address")
            or "found-no-entity"
        local key = table.concat({ api, subject_name, source, tostring(vehicle_lab_u32(hash)),
            owner and "1" or "0", outcome }, ":")
        if state.projectile_probe_logged[key] then return end
        state.projectile_probe_logged[key] = true
        log_info(("Projectile lookup id=%d api=%s subject=%s source=%s hash=0x%08X ownerFilter=%s found=%s handle=%s address=0x%X model=0x%08X")
            :format(
                state.projectile_window_id, api, subject_name, source, vehicle_lab_u32(hash),
                tostring(owner == true), tostring(found == true), tostring(result.handle or 0),
                tonumber(result.address) or 0, vehicle_lab_u32(result.model)))
    end

    function VehicleMods.find_current_projectile(ped, vehicle, now)
        if not VehicleMods.ensure_projectile_pointers() then return nil end
        local state = VehicleMods.state
        if not VehicleMods.projectile_window_matches(now,ped,vehicle) then return nil end
        -- Both documented queries take a weaponHash. An AmmoInfo name, model
        -- default or recently selected slot must not stand in for this fire window.
        local candidates={{hash=state.projectile_window_weapon,source="fire-window-weapon"}}
        local pool_due=now-(state.last_projectile_pool_scan_ms or -100000)>=25
        local range_multiplier = math.max(0.5, math.min(30.0, slider_float("vehicle_rocket_range", 1.0)))
        local distance = is_on("vehicle_rocket_range_unlimited") and 50000.0
            or 2500.0 * range_multiplier
        state.projectile_probe_variant = state.projectile_probe_variant % #VehicleMods.projectile_probe_variants + 1
        local variant = VehicleMods.projectile_probe_variants[state.projectile_probe_variant]
        local subject = ped
        local subject_name = variant.subject
        local owner_flag = variant.owner

        local function probe_handle(candidate)
            state.projectile_handle_calls = state.projectile_handle_calls + 1
            local ok, found = pcall(function()
                Memory.WriteInt(state.projectile_object_ptr, 0)
                return Natives.InvokeBool(H.GET_PROJECTILE_OF_PROJECTILE_TYPE_WITHIN_DISTANCE,
                    subject, candidate.hash, distance,
                    state.projectile_coords_ptr, state.projectile_object_ptr, owner_flag)
            end)
            if not ok then
                log_error_once("vehicle_projectile_lookup", found)
                VehicleMods.log_projectile_probe("GET_PROJECTILE_OF_PROJECTILE_TYPE_WITHIN_DISTANCE",
                    subject_name, candidate.source, candidate.hash, owner_flag, false)
                return nil
            end
            local projectile = 0
            if found == true then
                state.projectile_handle_hits = state.projectile_handle_hits + 1
                local read_ok, value = pcall(Memory.ReadInt, state.projectile_object_ptr)
                if read_ok then projectile = tonumber(value) or 0 end
            end
            local result
            if projectile ~= 0 and entity_exists(projectile)
                and state.projectiles[projectile] == nil then
                local physical = nil
                if GTA and type(GTA.HandleToPointer) == "function" then
                    local pointer_ok, pointer = pcall(GTA.HandleToPointer, projectile)
                    if pointer_ok then physical = pointer end
                end
                local model_hash = projectile_pointer_model(physical, projectile)
                local local_ok, locality = VehicleMods.projectile_locality(
                    physical, projectile, owner_flag == true, vehicle, now, model_hash)
                if local_ok then
                    result = {
                        handle = projectile,
                        physical = physical,
                        address = projectile_pointer_address(physical),
                        model = model_hash,
                        native_owner_query = owner_flag == true,
                        owner_verified = owner_flag == true
                            or locality ~= "unnetworked-local-launch-window",
                        locality = locality,
                    }
                end
            end
            VehicleMods.log_projectile_probe("GET_PROJECTILE_OF_PROJECTILE_TYPE_WITHIN_DISTANCE",
                subject_name, candidate.source, candidate.hash, owner_flag, found == true,
                result or { handle = projectile })
            return result
        end

        local function probe_coords(candidate)
            state.projectile_coords_calls = state.projectile_coords_calls + 1
            local ok, found = pcall(Natives.InvokeBool,
                H.GET_COORDS_OF_PROJECTILE_TYPE_WITHIN_DISTANCE,
                subject, candidate.hash, distance, state.projectile_coords_ptr, owner_flag)
            if not ok then
                log_error_once("vehicle_projectile_coords_lookup", found)
                VehicleMods.log_projectile_probe("GET_COORDS_OF_PROJECTILE_TYPE_WITHIN_DISTANCE",
                    subject_name, candidate.source, candidate.hash, owner_flag, false)
                return nil
            end
            local result
            if found == true then
                state.projectile_coords_hits = state.projectile_coords_hits + 1
                if type(Memory.ReadV3) == "function" then
                    local read_ok, coords = pcall(Memory.ReadV3, state.projectile_coords_ptr)
                    if read_ok then
                        local x, y, z = vector_components(coords)
                        if x then
                            if not pool_due then return nil end
                            state.last_projectile_pool_scan_ms=now;pool_due=false
                            result = VehicleMods.match_rendered_projectile(x, y, z)
                            if result then
                                local local_ok, locality = VehicleMods.projectile_locality(
                                    result.physical, result.handle, owner_flag == true,
                                    vehicle, now, result.model)
                                if not local_ok then
                                    result = nil
                                else
                                    result.locality = locality
                                    result.owner_verified = owner_flag == true
                                        or locality ~= "unnetworked-local-launch-window"
                                end
                            end
                        end
                    end
                end
            end
            VehicleMods.log_projectile_probe("GET_COORDS_OF_PROJECTILE_TYPE_WITHIN_DISTANCE",
                subject_name, candidate.source, candidate.hash, owner_flag, found == true, result)
            return result
        end

        -- The native's first parameter is documented as Ped. Ownership forms rotate
        -- across two combat ticks without passing a vehicle through the wrong type.
        for _, candidate in ipairs(candidates) do
            local result = probe_handle(candidate)
            if result then return result end
            result = probe_coords(candidate)
            if result then return result end
        end
        if not pool_due then return nil end
        state.last_projectile_pool_scan_ms=now
        local rendered = VehicleMods.scan_rendered_projectile(vehicle, now)
        if rendered then
            VehicleMods.log_projectile_probe("RENDERED_PROJECTILE_POOL", subject_name,
                rendered.source, state.projectile_window_weapon, false, true, rendered)
            return rendered
        end
        return nil
    end

    function VehicleMods.record_projectile_end(handle,info,now,reason)
        local s=VehicleMods.state
        s.projectile_history=s.projectile_history or {}
        s.projectile_history[#s.projectile_history+1]={handle=handle,address=info.address,model=info.model,
            first_seen_ms=info.first_seen,last_seen_ms=info.last_seen,end_sample_ms=now,
            fire_window_ms=info.fire_window_ms,weapon=info.launch_weapon,template_ammo_ptr=info.template_ammo_ptr,
            target=info.buff_target,guided_steps=info.buff_guided_steps or 0,reason=reason,expiry_cause="unknown",
            terminal_steps=info.buff_terminal_steps or 0,cruise_speed=info.buff_cruise_speed,
            commanded_speed=info.buff_commanded_speed,intercept_time=info.buff_intercept_time,
            last_distance=info.last_distance,last_guidance_ms=info.last_guidance_ms,
            buff_target_lost=info.buff_target_lost,
            first_loss_reason=info.first_loss_reason,first_loss_ms=info.first_loss_ms,first_loss_detail=info.first_loss_detail,
            launch_lock_state=info.launch_lock_state,launch_raw_target=info.launch_raw_target,
            launch_target_address_known=info.launch_target_address_known,
            launch_pre_input_ms=info.launch_pre_input_ms,launch_pre_input_lock_state=info.launch_pre_input_lock_state,
            launch_pre_input_target=info.launch_pre_input_target,launch_pre_input_target_address=info.launch_pre_input_target_address,
            launch_pre_input_source_bound=info.launch_pre_input_source_bound,launch_pre_input_same_ms=info.launch_pre_input_same_ms,
            launch_fire_control=info.launch_fire_control,launch_window_reason=info.launch_window_reason,
            launch_sample_target=info.launch_sample_target,launch_sample_target_address=info.launch_sample_target_address,
            launch_window_ambiguous=info.launch_window_ambiguous,
            fire_window_target=info.fire_window_target,fire_window_target_address=info.fire_window_target_address,
            rearm_known_identity=info.rearm_known_identity,rearm_history_unavailable=info.rearm_history_unavailable,
            native_owner_query=info.native_owner_query,owner_verified=info.owner_verified,
            guidance_authority=info.buff_guidance_authority,missile_profile=info.buff_missile_profile,
            projectile_ammo_record="not exposed by documented CPhysical/CObject contract"}
        if #s.projectile_history>16 then table.remove(s.projectile_history,1) end
    end

    function VehicleMods.prune_projectiles(now)
        local state = VehicleMods.state
        for handle, info in pairs(state.projectiles) do
            local released=cached_entity_handle_released(handle)
            local gone=released or not entity_exists(handle)
            local address=not gone and power_number(info.address) and power_address("HandleToPointer",handle) or nil
            local replaced=address~=nil and address~=info.address
            if gone or replaced then
                local reason=released and "handle-released" or gone and "entity-not-present" or "identity-replaced"
                VehicleMods.record_projectile_end(handle,info,now,reason)
                VehicleMods.reject_pending_projectile(handle,info)
                if info.address then state.projectile_addresses[info.address] = nil end
                if info.physical then state.projectile_entities[info.physical] = nil end
                state.projectiles[handle] = nil
                state.projectile_count = math.max(0, state.projectile_count - 1)
            elseif address~=nil then
                info.last_seen=now
            end
        end
        for handle, processed_at in pairs(state.instant_processed) do
            if now - processed_at > 2500 then state.instant_processed[handle] = nil end
        end
    end

    function VehicleMods.restore_ped_shoot_rate()
        local state = VehicleMods.state
        local ped = tonumber(state.direct_rapid_shoot_rate_ped) or 0
        if ped ~= 0 and entity_exists(ped) and H.SET_PED_SHOOT_RATE then
            local ok, err = pcall(invoke_void, H.SET_PED_SHOOT_RATE, ped, 100)
            if not ok then log_error_once("vehicle_ped_shoot_rate_restore", err) end
        end
        state.direct_rapid_shoot_rate_ped = 0
        state.direct_rapid_shoot_rate_value = 100
        state.direct_rapid_shoot_rate_signature = nil
        state.direct_rapid_shoot_rate_last_ms = -100000
    end


    function VehicleMods.attack_pressed(ped, vehicle, weapon_hash)
        ped, vehicle = ped or local_ped(), vehicle or local_vehicle()
        weapon_hash = weapon_hash or VehicleLab.get_current_vehicle_weapon(ped)
        local control = VehicleMods.fire_control(ped, vehicle, weapon_hash)
        if not control then return false end
        return invoke_bool(H.IS_CONTROL_PRESSED, 0, control)
            or invoke_bool(H.IS_DISABLED_CONTROL_PRESSED, 0, control)
    end


    function VehicleMods.direct_rapid_frame(now, ped, vehicle)
        local state = VehicleMods.state
        if (not is_on("vehicle_rapid_fire") and not is_on("vehicle_rapid_fire_guns"))
            or not entity_exists(ped) or not entity_exists(vehicle) then
            VehicleMods.restore_ped_shoot_rate()
            state.direct_rapid_active = false
            state.direct_rapid_vehicle = 0
            state.direct_rapid_weapon = 0
            state.last_manual_fire_ms = 0
            return false
        end
        local context = VehicleMods.controller_identity(ped, vehicle)
        local hash = context.weapon_hash
        if not VehicleLab.rapid_requested(hash) or not VehicleMods.should_use_direct_rapid(hash)
            or not VehicleMods.fire_control(ped, vehicle, hash) then
            VehicleMods.restore_ped_shoot_rate()
            state.direct_rapid_active = false
            state.direct_rapid_vehicle = 0
            state.direct_rapid_weapon = 0
            state.last_manual_fire_ms = 0
            return false
        end

        -- Preserve GTA's input, reticle, and muzzle path. Change only owned
        -- cadence fields; restore any owned ped shoot-rate state first.
        VehicleMods.restore_ped_shoot_rate()
        VehicleLab.quiesce_rapid_fire_builtin()
        local resolved,ptr=VehicleLab.resolve_weapon_runtime_target(ped)
        local applied=false
        if vehicle_lab_u32(resolved)==hash then
            if VehicleLab.is_native_aircraft_cannon(hash) then
                applied=VehicleLab.apply_native_cannon_profile(ped,vehicle,hash,ptr)==true
            else
                applied=VehicleLab.apply_weapon_runtime(ped,vehicle,hash,ptr)==true
            end
        end
        state.direct_rapid_active=applied
        state.direct_rapid_vehicle=applied and vehicle or 0
        state.direct_rapid_weapon=applied and hash or 0
        state.last_manual_fire_ms=0
        return applied
    end

    function VehicleMods.get_native_locked_target(vehicle)
        local state=VehicleMods.state
        state.last_lock_target,state.last_lock_target_address,state.last_lock_target_ms=0,nil,0
        if not entity_exists(vehicle) or not VehicleMods.ensure_target_pointer() then return 0 end
        local ok, locked = pcall(function()
            Memory.WriteInt(state.lock_target_ptr, 0)
            return Natives.InvokeBool(H.GET_VEHICLE_LOCK_ON_TARGET, vehicle, state.lock_target_ptr)
        end)
        if not ok then
            log_error_once("vehicle_lock_target", locked)
            return 0
        end
        if locked~=true and locked~=1 then return 0 end
        local read_ok, target = pcall(Memory.ReadInt, state.lock_target_ptr)
        if not read_ok or not entity_exists(target) then return 0 end
        state.last_lock_target = target
        state.last_lock_target_address = power_address("HandleToPointer", target)
        state.last_lock_target_ms = now_ms()
        return target
    end

    function VehicleMods.get_locked_target(vehicle)
        return VehicleMods.get_native_locked_target(vehicle)
    end

    function VehicleMods.invalidate_buff_guidance()
        -- A toggle change must invalidate the fast success cache before
        -- the next gameplay maintenance tick.
        VehicleLab.state.global_homing_eval = nil
    end

    function VehicleMods.frame_tick(now)
        now = tonumber(now) or now_ms()
        local projectile_state=VehicleMods.state
        if VehicleMods.projectile_changes_requested() or next(projectile_state.projectiles)~=nil
            or projectile_state.projectile_window_active then
            local previous=projectile_state.projectile_last_frame_ms
            if previous~=now then
                local frame_dt=power_native("InvokeFloat",0x15C40837039FFAF7) -- GET_FRAME_TIME
                if type(frame_dt)~="number" or frame_dt~=frame_dt or frame_dt<=0 or frame_dt==math.huge then
                    frame_dt=previous and now>previous and (now-previous)/1000 or (1/60)
                end
                projectile_state.projectile_frame_dt=math.min(.050,math.max(.001,frame_dt))
                projectile_state.projectile_last_frame_ms=now
                local ped,vehicle=local_ped(),local_vehicle()
                if not entity_exists(ped) or not entity_exists(vehicle)
                    or power_native("InvokeBool",H.IS_ENTITY_DEAD,ped,false)~=false then
                    VehicleMods.restore_projectiles()
                else VehicleMods.process_projectile(now,ped,vehicle) end
            end
        else projectile_state.projectile_last_frame_ms=nil end

        if VehicleMods.mounted_targets_pending() and
            ((not is_on('vehicle_lock_players') and not is_on('vehicle_lock_npcs'))
                or not entity_exists(local_vehicle())) then
            VehicleMods.restore_mounted_targets()
        end

        local state =
            VehicleMods.state

        local rapid_requested =
            VehicleLab.rapid_requested()

        local mobility_requested =
            is_on("vehicle_superdrive") and not is_on("vehicle_fly")

        local driving_requested = is_on("vehicle_drift_mode") or is_on("vehicle_disable_burnout")
            or is_on("vehicle_unlimited_jump") or state.traction_owner~=nil or state.jump_controller~=nil

        local cannon_requested =
            is_on("vehicle_lab_cannons")
            or is_on("vehicle_cannon_range")

        local power_requested =
            is_on("vehicle_engine_power")

        if not rapid_requested
            and not mobility_requested
            and not cannon_requested
            and not power_requested
            and not driving_requested
            and state.power_vehicle == 0
            and not state.power_pending_release
            and not state.direct_rapid_active then
            return
        end

        local vehicle =
            local_vehicle()

        local ped =
            local_ped()
        if driving_requested then
            VehicleMods.traction_frame(vehicle)
            VehicleMods.jump_frame(vehicle)
        end
        if power_requested then
            if entity_exists(vehicle) then
                VehicleMods.apply_power(vehicle, now)
            else
                VehicleMods.restore_power()
            end
        elseif state.power_vehicle ~= 0 or state.power_pending_release then
            VehicleMods.restore_power()
        end

        if rapid_requested then
            if entity_exists(ped) and entity_exists(vehicle) then
                VehicleMods.direct_rapid_frame(now, ped, vehicle)
            else
                VehicleMods.restore_ped_shoot_rate()
                state.direct_rapid_active = false
                state.direct_rapid_vehicle = 0
                state.direct_rapid_weapon = 0
                state.last_manual_fire_ms = 0
            end
        elseif state.direct_rapid_active then
            state.direct_rapid_active = false
            state.direct_rapid_vehicle = 0
            state.direct_rapid_weapon = 0
            state.last_manual_fire_ms = 0
        end

        -- Vehicle Rapid Fire owns cadence changes; cannon restoration does not
        -- change the ped shoot-rate override.
        if not rapid_requested then
            VehicleMods.restore_ped_shoot_rate()
        end

        if not mobility_requested then return end
        if not entity_exists(vehicle) then return end
        if is_on("vehicle_superdrive") and invoke_bool(H.IS_CONTROL_PRESSED, 0, 71) then
            local dx, dy, dz
            if is_on("vehicle_superdrive_camera") then dx, dy, dz = VehicleMods.camera_direction() end
            if not dx then dx, dy, dz = vector_components(invoke_vec3(H.GET_ENTITY_FORWARD_VECTOR, vehicle)) end
            local velocity = invoke_vec3(H.GET_ENTITY_VELOCITY, vehicle)
            local vx, vy, vz = vector_components(velocity)
            if dx and vx then
                local step = slider_float("vehicle_superdrive_multiplier", 0.605) * 0.85
                local nx, ny, nz = vx + dx * step, vy + dy * step, vz + dz * step
                local magnitude = math.sqrt(nx * nx + ny * ny + nz * nz)
                if magnitude > 250.0 then
                    local scale = 250.0 / magnitude
                    nx, ny, nz = nx * scale, ny * scale, nz * scale
                end
                invoke_void(H.SET_ENTITY_VELOCITY, vehicle, nx, ny, nz)
            elseif dx then
                invoke_void(H.SET_VEHICLE_FORWARD_SPEED, vehicle,
                    math.min(250.0, math.max(10.0, slider_float("vehicle_superdrive_multiplier", 0.605) * 40.0)))
            end
        end
    end

    function VehicleMods.combat_tick()end

    function VehicleMods.fast_tick(now, ped, vehicle)
        local state = VehicleMods.state
        if state.buff_release_pending then
            local restored=VehicleLab.restore_global_homing_buff()
            VehicleMods.restore_projectiles()
            if not restored then return end
            state.buff_release_pending=false
        end
        local in_vehicle = entity_exists(ped) and entity_exists(vehicle)
        local rapid_weapon_hash, rapid_weapon_ptr, rapid_fire_ready, native_aircraft_cannon
        if in_vehicle and VehicleLab.rapid_requested() then
            rapid_weapon_hash, rapid_weapon_ptr = VehicleLab.resolve_weapon_runtime_target(ped)
            native_aircraft_cannon = VehicleLab.is_native_aircraft_cannon(rapid_weapon_hash)
            local direct_rapid = VehicleLab.rapid_requested()
                and VehicleMods.should_use_direct_rapid(rapid_weapon_hash)
            if direct_rapid then
                VehicleLab.quiesce_rapid_fire_builtin()
                -- Keep the actual selected mounted weapon's timing profile aligned
                -- with the requested delay, but keep Cherax's built-in helper off.
                if native_aircraft_cannon then
                    VehicleLab.apply_native_cannon_profile(
                        ped, vehicle, rapid_weapon_hash, rapid_weapon_ptr)
                else
                    VehicleLab.prepare_rapid_fire_runtime(
                        ped, vehicle, rapid_weapon_hash, rapid_weapon_ptr)
                end
                rapid_fire_ready = false
            elseif native_aircraft_cannon then
                VehicleLab.quiesce_rapid_fire_builtin()
                VehicleMods.restore_builtin("infinite_weapon_range")
                state.builtin_desired.infinite_weapon_range = false
                VehicleLab.restore_all_weapon_runtime()
                rapid_fire_ready = VehicleLab.apply_native_cannon_profile(
                    ped, vehicle, rapid_weapon_hash, rapid_weapon_ptr)
            elseif VehicleLab.rapid_requested() then
                rapid_fire_ready = VehicleLab.prepare_rapid_fire_runtime(
                    ped, vehicle, rapid_weapon_hash, rapid_weapon_ptr)
            end
        end
        VehicleMods.controller_begin(now, ped, vehicle, rapid_weapon_hash, rapid_weapon_ptr)
        VehicleMods.sync_builtins(now, in_vehicle, rapid_fire_ready, native_aircraft_cannon)
        VehicleMods.instant_lock_observe(now,ped,vehicle)
        if not in_vehicle then
            VehicleMods.restore_power()
            local targets_result=false
            local target_context=(is_on("vehicle_lock_players") or is_on("vehicle_lock_npcs"))
                and VehicleMods.instant_lock_identity(ped,vehicle)~=nil
            if target_context then targets_result=VehicleMods.refresh_lockable_targets(now,vehicle)==true
            elseif next(state.target_entities) ~= nil or next(state.target_ownership or {}) ~= nil
                or VehicleMods.mounted_targets_pending() then
                VehicleMods.restore_lockable_targets()
            end
            if next(state.ammo_snapshots) ~= nil then VehicleMods.restore_ammo() end
            if state.projectile_count > 0 or state.instant_shape_test ~= 0
                or state.projectile_window_active then
                VehicleMods.restore_projectiles()
            end
            VehicleLab.restore_all_weapon_runtime()
            VehicleLab.state.weapon_runtime_signature = nil
            -- The selected Homing Launcher uses the same field owners and
            -- settings as mounted rockets. Invalid selections drain their debt.
            local buff_result = VehicleLab.apply_global_homing_buff(ped, 0) == true
            local ammo_result = VehicleLab.apply_rocket_tuning(ped, 0) == true
            state.last_ammo_refresh_ms = -100000
            state.ammo_active_vehicle = 0
            VehicleMods.instant_ammo_sync(ped,vehicle)
            VehicleMods.controller_finalize({ ammo = ammo_result, buff = buff_result, targets = targets_result })
            return
        end

        local weapon_result = VehicleLab.apply_weapon_runtime(
            ped, vehicle, rapid_weapon_hash, rapid_weapon_ptr) == true
        -- Release any on-foot Homing Launcher owner before composing the exact
        -- native-selected vehicle AmmoInfo. There is no catalog/model fallback.
        local buff_result = VehicleLab.apply_global_homing_buff(ped, vehicle) == true
        local ammo_result = VehicleLab.apply_rocket_tuning(ped, vehicle) == true
        -- Explicit final composition stage. Buff All may refresh its
        -- guidance helpers above; Rapid Fire then reasserts only its cadence fields
        -- from the immutable CWeaponInfo baseline. This is field ownership, not a
        -- whole-profile last-tick winner, and cannot touch projectile launch speed.
        if VehicleLab.rapid_requested() then
            local cadence_hash = rapid_weapon_hash
            local cadence_ptr = tonumber(rapid_weapon_ptr) or 0
            if not cadence_hash or vehicle_lab_u32(cadence_hash) == 0 then
                cadence_hash, cadence_ptr = VehicleLab.resolve_weapon_runtime_target(ped)
            end
            if VehicleLab.is_native_aircraft_cannon(cadence_hash) then
                VehicleLab.apply_native_cannon_profile(ped, vehicle, cadence_hash, cadence_ptr)
            else
                local snap = VehicleLab.state.weapon_runtime_snapshots[cadence_ptr]
                if snap then VehicleLab.write_effective_cadence(cadence_ptr, snap, rapid_delay_seconds()) end
            end
        end
        VehicleMods.instant_ammo_sync(ped,vehicle)
        VehicleLab.log_composition(ped, vehicle, false)
        local targets_result = VehicleMods.refresh_lockable_targets(now, vehicle) == true

        local vehicle_ammo_result = false
        if is_on("vehicle_infinite_ammo") then
            state.ammo_active_vehicle = vehicle
            state.last_ammo_refresh_ms = now
            vehicle_ammo_result = VehicleMods.apply_infinite_ammo(vehicle, now) == true
        else
            if state.ammo_active_vehicle ~= 0 or next(state.ammo_snapshots) ~= nil then
                VehicleMods.restore_ammo()
            end
            state.ammo_active_vehicle = 0
            state.last_ammo_refresh_ms = -100000
        end
        VehicleMods.controller_finalize({
            weapon = weapon_result,
            ammo = ammo_result,
            buff = buff_result,
            targets = targets_result,
            vehicle_ammo = vehicle_ammo_result,
            rapid = rapid_fire_ready == true,
            projectile_armed = in_vehicle and VehicleMods.projectile_changes_requested(),
        })
    end

    -- An on-demand engine sample is independent of registry submissions and of
    -- the provider's checkbox. Missing observations stay unknown, never idle.
    function VehicleMods.restore()
        combat_record("Vehicle Combat", "restore", "Restoring controller-owned runtime state", "INFO")
        VehicleMods.restore_ped_shoot_rate()
        local builtins_restored = VehicleMods.restore_builtins()
        VehicleMods.restore_power()
        local delivery_restored=VehicleMods.driver_assistance.Cancel("Vehicle state restored.")
        local access_restored=VehicleMods.driver_assistance.RestoreAccess()
        local traction_restored=VehicleMods.restore_traction()
        VehicleMods.restore_jump()
        local ammo_restored = VehicleMods.restore_ammo()
        VehicleMods.restore_projectiles()
        local targets_restored = VehicleMods.restore_lockable_targets()
        VehicleMods.state.last_auto_fire_ms = 0
        VehicleMods.state.last_auto_fire_attempt_ms = nil
        VehicleMods.state.last_manual_fire_ms = 0
        VehicleMods.state.manual_muzzle_side = -1.0
        VehicleMods.state.direct_rapid_active = false
        VehicleMods.state.direct_rapid_vehicle = 0
        VehicleMods.state.direct_rapid_weapon = 0
        VehicleMods.state.direct_rapid_shots = 0
        VehicleMods.state.direct_rapid_log_signature = nil
        VehicleMods.state.direct_rapid_ped_rate_log_signature = nil
        VehicleMods.state.direct_rapid_passthrough_log_signature = nil
        VehicleMods.state.buff_guidance_steps = 0
        VehicleMods.state.buff_guidance_projectiles = 0
        VehicleMods.state.buff_guidance_last_target = 0
        VehicleMods.state.buff_guidance_log_signature = nil
        VehicleMods.state.last_combat_tick_ms = 0
        VehicleMods.state.combat_active = false
        VehicleMods.state.noclip_active = false
        VehicleMods.state.builtin_desired = {}
        VehicleMods.state.builtin_last_applied = {}
        VehicleMods.state.builtin_effective = {}
        VehicleMods.state.builtin_last_attempt_ms = {}
        VehicleMods.state.controller.desired = {}
        VehicleMods.state.controller.effective = {}
        VehicleMods.state.controller.backend = {}
        VehicleMods.state.controller.status = {}
        VehicleMods.state.controller.context = {}
        VehicleMods.state.controller.pending_reason = "none"
        VehicleMods.state.controller.force_refresh = true
        VehicleMods.state.last_target_vehicle_scan_ms = -100000
        VehicleMods.state.target_filter_signature = "00"
        VehicleMods.state.target_rendered_peds = 0
        VehicleMods.state.target_rendered_vehicles = 0
        VehicleMods.state.target_eligible_peds = 0
        VehicleMods.state.target_eligible_vehicles = 0
        VehicleMods.state.target_player_diagnostics = {}
        VehicleMods.state.target_scan_error = "restored"
        VehicleMods.state.last_ammo_refresh_ms = -100000
        VehicleMods.state.ammo_active_vehicle = 0
        local restored = access_restored and delivery_restored and builtins_restored and ammo_restored and targets_restored and traction_restored
        combat_record("Vehicle Combat", "restore", restored
            and "Controller-owned runtime state restored" or "Controller restoration remains pending",
            restored and "PASS" or "WARN")
        return restored
    end

    function VehicleMods.shutdown()
        local restored=VehicleMods.restore()
        VehicleMods.clear_projectile_safety()
        local state = VehicleMods.state
        if Memory and type(Memory.Free) == "function" then
            for _, key in ipairs({
                "projectile_coords_ptr", "projectile_object_ptr", "lock_target_ptr",
                "projectile_delete_ptr", "shape_hit_ptr", "shape_end_ptr",
                "shape_normal_ptr", "shape_entity_ptr",
            }) do
                local pointer = state[key]
                state[key] = 0
                if type(pointer) == "number" and pointer ~= 0 then
                    local ok, err = pcall(Memory.Free, pointer)
                    if not ok then log_error_once("vehicle_mod_pointer_free_" .. key, err) end
                end
            end
        end
        return restored
    end

    return VehicleLab, VehicleMods
end

local function personal_vehicle_global_int(index)
    local globals = module_context and module_context.Raw and module_context.Raw.ScriptGlobal
    if globals == nil and type(_G) == "table" then globals = rawget(_G, "ScriptGlobal") end
    if not globals or type(globals.GetInt) ~= "function" then
        return nil, "ScriptGlobal.GetInt is unavailable"
    end
    index = tonumber(index)
    if not index or index % 1 ~= 0 or index < 0 then return nil, "invalid script-global index" end
    local ok, value = pcall(globals.GetInt, math.floor(index))
    value = ok and tonumber(value) or nil
    if value == nil or value % 1 ~= 0 then
        return nil, "script-global read failed at " .. tostring(index)
    end
    return math.floor(value)
end

local function personal_vehicle_tunable(profile)
    if type(profile) ~= "table" then return nil, "tunable profile is unavailable" end
    local globals = module_context and module_context.Raw and module_context.Raw.ScriptGlobal
    local memory = dependencies and dependencies.Memory
        or (module_context and module_context.Raw and module_context.Raw.Memory)
    local utils = dependencies and dependencies.Utils
        or (module_context and module_context.Raw and module_context.Raw.Utils)
    local raw_value
    if globals and type(globals.GetInt) == "function" then
        local ok, value = pcall(globals.GetInt, profile.index)
        value = ok and tonumber(value) or nil
        if value ~= nil and value % 1 == 0 and value >= profile.minimum and value <= profile.maximum then
            raw_value = math.floor(value)
        end
    end
    local semantic_value, semantic_hash, semantic_ptr
    if globals and type(globals.GetTunableByHash) == "function"
        and memory and type(memory.ReadInt) == "function"
        and utils and type(utils.Joaat) == "function" then
        local hash_ok, hash = pcall(utils.Joaat, profile.name)
        semantic_hash = hash_ok and tonumber(hash) or nil
        if semantic_hash then
            local ptr_ok, ptr = pcall(globals.GetTunableByHash, semantic_hash)
            semantic_ptr = ptr_ok and tonumber(ptr) or nil
            if semantic_ptr and semantic_ptr ~= 0 then
                local read_ok, value = pcall(memory.ReadInt, semantic_ptr)
                value = read_ok and tonumber(value) or nil
                if value ~= nil and value % 1 == 0 and value >= profile.minimum and value <= profile.maximum then
                    semantic_value = math.floor(value)
                end
            end
        end
    end
    if semantic_value ~= nil and raw_value ~= nil and semantic_value ~= raw_value then
        return nil, ("%s resolver disagreement (semantic=%s raw=%s)"):format(
            tostring(profile.name), tostring(semantic_value), tostring(raw_value))
    end
    local value = semantic_value or raw_value
    if value == nil then return nil, tostring(profile.name) .. " could not be resolved" end
    return value, nil, {
        semantic_hash = semantic_hash,
        semantic_pointer = semantic_ptr,
        resolver = semantic_value ~= nil and raw_value ~= nil and "semantic+raw agreement"
            or semantic_value ~= nil and "semantic hash" or "verified raw global",
    }
end

local function personal_vehicle_slot_index(slot, offset)
    slot, offset = tonumber(slot), tonumber(offset)
    if not slot or slot % 1 ~= 0 or slot < 0 or slot >= PERSONAL_VEHICLE_PROFILE.slot_count then return nil end
    return PERSONAL_VEHICLE_PROFILE.data_base + 1 + (slot * PERSONAL_VEHICLE_PROFILE.stride) + offset
end

local function personal_vehicle_bit(flags, bit)
    flags, bit = math.floor(tonumber(flags) or 0), math.floor(tonumber(bit) or 0)
    return (flags & (1 << bit)) ~= 0
end

local function personal_vehicle_model_name(model)
    model = tonumber(model) or 0
    if model == 0 then return "Empty" end
    if bound and dependencies and type(dependencies.invoke_string) == "function" then
        local label = dependencies.invoke_string(VEHICLE_LABEL_HASHES.display_name, model)
        if type(label) == "string" and label ~= "" and label ~= "NULL" then
            local localized = dependencies.invoke_string(VEHICLE_LABEL_HASHES.localized_name, label)
            if type(localized) == "string" and localized ~= "" and localized ~= "NULL" then return localized end
            return label:gsub("_", " ")
        end
    end
    return ("Model 0x%08X"):format((math.floor(model) & 0xFFFFFFFF))
end

local function read_personal_vehicle_slot(slot)
    local model_index = personal_vehicle_slot_index(slot, PERSONAL_VEHICLE_PROFILE.model_offset)
    local flags_index = personal_vehicle_slot_index(slot, PERSONAL_VEHICLE_PROFILE.flags_offset)
    if not model_index or not flags_index then return nil, "personal-vehicle slot is outside 0..606" end
    local model, model_err = personal_vehicle_global_int(model_index)
    if model == nil then return nil, model_err end
    local flags, flags_err = personal_vehicle_global_int(flags_index)
    if flags == nil then return nil, flags_err end
    local occupied = model ~= 0
    return {
        slot = slot,
        occupied = occupied,
        model_hash = model,
        model_name = occupied and personal_vehicle_model_name(model) or "Empty",
        flags = flags,
        destroyed = occupied and personal_vehicle_bit(flags, PERSONAL_VEHICLE_PROFILE.flag_destroyed) or false,
        insured = occupied and personal_vehicle_bit(flags, PERSONAL_VEHICLE_PROFILE.flag_insured) or false,
        impounded = occupied and personal_vehicle_bit(flags, PERSONAL_VEHICLE_PROFILE.flag_impounded) or false,
        model_global_index = model_index,
        flags_global_index = flags_index,
    }
end

local function refresh_active_personal_vehicle()
    local slot, slot_err = personal_vehicle_global_int(PERSONAL_VEHICLE_PROFILE.active_slot_index)
    local fee, fee_err, fee_meta = personal_vehicle_tunable(PERSONAL_VEHICLE_PROFILE.impound_fee)
    if slot == nil or slot < -1 or slot >= PERSONAL_VEHICLE_PROFILE.slot_count then
        PersonalVehicleState.status = "UNAVAILABLE"
        PersonalVehicleState.active_slot = -1
        PersonalVehicleState.active = nil
        PersonalVehicleState.impound_fee = fee
        PersonalVehicleState.impound_fee_resolver = fee_meta
        PersonalVehicleState.last_error = tostring(slot_err or "active personal-vehicle slot was outside -1..606")
        PersonalVehicleState.refreshed_at = os and os.time and os.time() or 0
        return false, PersonalVehicleState.last_error
    end
    local active, active_err
    if slot >= 0 then active, active_err = read_personal_vehicle_slot(slot) end
    if slot >= 0 and not active then
        PersonalVehicleState.status = "UNAVAILABLE"
        PersonalVehicleState.active_slot = slot
        PersonalVehicleState.active = nil
        PersonalVehicleState.last_error = tostring(active_err)
        PersonalVehicleState.refreshed_at = os and os.time and os.time() or 0
        return false, PersonalVehicleState.last_error
    end
    PersonalVehicleState.status = slot == -1 and "NO_ACTIVE_SLOT" or "READY"
    PersonalVehicleState.active_slot = slot
    PersonalVehicleState.active = active
    PersonalVehicleState.impound_fee = fee
    PersonalVehicleState.impound_fee_resolver = fee_meta
    PersonalVehicleState.impound_fee_error = fee == nil and tostring(fee_err) or nil
    PersonalVehicleState.last_error = nil
    PersonalVehicleState.refreshed_at = os and os.time and os.time() or 0
    return true,
        slot == -1 and "No active personal-vehicle slot is currently assigned." or "Active personal vehicle refreshed."
end


local function queue_personal_vehicle_action(action)
    action = tostring(action or "")
    if action ~= "refresh" and action ~= "audit" then return false, "Unknown garage scan action." end
    if PersonalVehicleState.scanning and action == "audit" then
        return false, "Garage audit is already running."
    end
    PersonalVehicleState.pending_action = action
    return true, action == "audit" and "Garage audit queued on the runtime tick."
        or "Active personal-vehicle refresh queued on the runtime tick."
end

local function process_personal_vehicle_work(now)
    local action = PersonalVehicleState.pending_action
    PersonalVehicleState.pending_action = nil
    if action == "refresh" then refresh_active_personal_vehicle() end
    if action == "audit" then
        PersonalVehicleState.scanning = true
        PersonalVehicleState.scan_slot = 0
        PersonalVehicleState.scan_entries = {}
        PersonalVehicleState.scan_counts = {
            occupied = 0, empty = 0, insured = 0, uninsured = 0, destroyed = 0, impounded = 0,
        }
        PersonalVehicleState.scan_status = "SCANNING"
        PersonalVehicleState.scan_started_ms = tonumber(now) or 0
        PersonalVehicleState.last_error = nil
    end
    if not PersonalVehicleState.scanning then return end

    local entries = PersonalVehicleState.scan_entries or {}
    local counts = PersonalVehicleState.scan_counts or {
        occupied = 0, empty = 0, insured = 0, uninsured = 0, destroyed = 0, impounded = 0,
    }
    local first = math.max(0, math.floor(tonumber(PersonalVehicleState.scan_slot) or 0))
    local last = math.min(PERSONAL_VEHICLE_PROFILE.slot_count - 1, first + 23)
    for slot = first, last do
        local item, err = read_personal_vehicle_slot(slot)
        if not item then
            PersonalVehicleState.scanning = false
            PersonalVehicleState.scan_status = "FAILED"
            PersonalVehicleState.scan_entries, PersonalVehicleState.scan_counts = nil, nil
            PersonalVehicleState.last_error = ("Garage audit stopped at slot %d: %s. The previous completed audit was preserved.")
                :format(slot, tostring(err))
            return
        end
        if item.occupied then
            counts.occupied = counts.occupied + 1
            if item.insured then counts.insured = counts.insured + 1 else counts.uninsured = counts.uninsured + 1 end
            if item.destroyed then counts.destroyed = counts.destroyed + 1 end
            if item.impounded then counts.impounded = counts.impounded + 1 end
            entries[#entries + 1] = item
        else
            counts.empty = counts.empty + 1
        end
        PersonalVehicleState.scan_slot = slot + 1
    end
    PersonalVehicleState.scan_entries, PersonalVehicleState.scan_counts = entries, counts
    if PersonalVehicleState.scan_slot >= PERSONAL_VEHICLE_PROFILE.slot_count then
        PersonalVehicleState.audit = {
            counts = counts,
            entries = entries,
            total_slots = PERSONAL_VEHICLE_PROFILE.slot_count,
            source = PERSONAL_VEHICLE_PROFILE.source,
        }
        PersonalVehicleState.audit_refreshed_at = os and os.time and os.time() or 0
        PersonalVehicleState.scanning = false
        PersonalVehicleState.scan_status = "COMPLETE"
        PersonalVehicleState.scan_entries, PersonalVehicleState.scan_counts = nil, nil
        PersonalVehicleState.last_error = nil
    end
end

local function personal_vehicle_snapshot()
    local active, audit = PersonalVehicleState.active, PersonalVehicleState.audit
    return {
        status = PersonalVehicleState.status,
        active_slot = PersonalVehicleState.active_slot,
        active = active and {
            slot = active.slot,
            occupied = active.occupied,
            model_hash = active.model_hash,
            model_name = active.model_name,
            flags = active.flags,
            destroyed = active.destroyed,
            insured = active.insured,
            impounded = active.impounded,
            model_global_index = active.model_global_index,
            flags_global_index = active.flags_global_index,
        } or nil,
        audit = audit and
            { counts = audit.counts, entries = audit.entries, total_slots = audit.total_slots, source = audit.source } or
            nil,
        impound_fee = PersonalVehicleState.impound_fee,
        impound_fee_resolver = PersonalVehicleState.impound_fee_resolver,
        impound_fee_error = PersonalVehicleState.impound_fee_error,
        refreshed_at = PersonalVehicleState.refreshed_at,
        audit_refreshed_at = PersonalVehicleState.audit_refreshed_at,
        last_error = PersonalVehicleState.last_error,
        scanning = PersonalVehicleState.scanning == true,
        scan_slot = tonumber(PersonalVehicleState.scan_slot) or 0,
        scan_total = PERSONAL_VEHICLE_PROFILE.slot_count,
        scan_progress = math.min(1.0, math.max(0.0,
            (tonumber(PersonalVehicleState.scan_slot) or 0) / PERSONAL_VEHICLE_PROFILE.slot_count)),
        scan_status = PersonalVehicleState.scan_status,
        source = PERSONAL_VEHICLE_PROFILE.source,
        mutation_support = "READ_ONLY_ROCKSTAR_OWNED",
        reason =
        "CScript reads current Enhanced ownership state only; insurance claims, impound release and garage persistence remain Rockstar-owned flows.",
    }
end

local function publish_state(context)
    local root = context.State.Vehicle
    for key in pairs(root) do root[key] = nil end

    -- These are reference-only views over the two preserved baseline state
    -- tables. No values are copied and compat.lua owns no vehicle state.
    root.Runtime = { Lab = VehicleLab.state, Mods = VehicleMods.state }
    root.VehicleCombatController = VehicleMods.state.controller
    root.Memory = {
        WeaponProfiles = VehicleLab.state.weapon_runtime_snapshots,
        AmmoProfiles = VehicleLab.state.runtime_ammo_snapshots,
        AmmoRanges = VehicleLab.state.ammo_range_snapshots,
    }
    root.Targeting = {
        Vehicles = VehicleMods.state.target_vehicles,
        Peds = VehicleMods.state.target_peds,
        Entities = VehicleMods.state.target_entities,
    }
    root.Projectiles = setmetatable({}, {
        __index = function(_, key)
            if key == "Tracked" then return VehicleMods.state.projectiles end
            if key == "Addresses" then return VehicleMods.state.projectile_addresses end
            if key == "Entities" then return VehicleMods.state.projectile_entities end
            if key == "Count" then return VehicleMods.state.projectile_count end
            if key == "RecentWeapons" then return VehicleMods.state.recent_vehicle_weapons end
            return nil
        end,
    })
    root.Cannon = VehicleLab.state
    root.Current = VehicleMods.state
    root.Ownership = PersonalVehicleState
end

local function reapply_rocket_tuning()
    if not bound then return false, "vehicle module is not compatibility-bound" end
    VehicleLab.state.weapon_runtime_signature = nil
    VehicleLab.state.ammo_runtime_signature = nil
    local ped, vehicle = dependencies.local_ped(), dependencies.local_vehicle()
    if dependencies.entity_exists(ped) then
        if dependencies.entity_exists(vehicle) then VehicleLab.apply_weapon_runtime(ped, vehicle) end
        VehicleLab.apply_rocket_tuning(ped, vehicle)
    end
    return true
end

local function reapply_rapid_fire()
    if not bound then return false, "vehicle module is not compatibility-bound" end
    VehicleLab.state.weapon_runtime_signature = nil
    local ped, vehicle = dependencies.local_ped(), dependencies.local_vehicle()
    local restored = true
    if not VehicleLab.rapid_requested() then
        restored = VehicleLab.quiesce_rapid_fire_builtin()
    end
    if dependencies.entity_exists(ped) and dependencies.entity_exists(vehicle) then
        local weapon_hash, ptr
        local native_aircraft_cannon = false
        local direct_rapid = false
        if VehicleLab.rapid_requested() then
            weapon_hash, ptr = VehicleLab.resolve_weapon_runtime_target(ped)
            native_aircraft_cannon = VehicleLab.is_native_aircraft_cannon(weapon_hash)
            direct_rapid = VehicleMods.should_use_direct_rapid(weapon_hash)
            if direct_rapid then
                VehicleLab.quiesce_rapid_fire_builtin()
                if native_aircraft_cannon then
                    if not VehicleLab.apply_native_cannon_profile(
                            ped, vehicle, weapon_hash, ptr) then
                        restored = false
                    end
                elseif not VehicleLab.prepare_rapid_fire_runtime(
                        ped, vehicle, weapon_hash, ptr) then
                    restored = false
                end
                VehicleMods.state.direct_rapid_log_signature = nil
            elseif native_aircraft_cannon then
                VehicleLab.quiesce_rapid_fire_builtin()
                VehicleLab.restore_all_weapon_runtime()
                if not VehicleLab.apply_native_cannon_profile(ped, vehicle, weapon_hash, ptr) then
                    restored = false
                end
            elseif not VehicleLab.prepare_rapid_fire_runtime(ped, vehicle, weapon_hash, ptr) then
                restored = false
            end
        end
        if not VehicleLab.apply_weapon_runtime(ped, vehicle, weapon_hash, ptr)
            and VehicleLab.rapid_requested()
            and not native_aircraft_cannon and not direct_rapid then
            restored = false
        end
    elseif not VehicleLab.restore_all_weapon_runtime() then
        restored = false
    end
    return restored
end


local VEHICLE_TOGGLE_KEYS = {
    "vehicle_fly",
    "vehicle_damage_auto_repair",
    "vehicle_fast_enter_exit",
    "vehicle_quick_brake", "vehicle_instant_brake", "vehicle_bypass_player_restrictions",
    "vehicle_roof_turret",
    "vehicle_lab_cannons",
    "vehicle_superdrive", "vehicle_superdrive_camera", "vehicle_engine_power",
    "vehicle_drift_mode", "vehicle_disable_burnout", "vehicle_unlimited_jump", "vehicle_unlimited_rocket_boost",
    "vehicle_rapid_fire", "vehicle_rapid_fire_guns", "vehicle_hunter_camera", "vehicle_infinite_ammo",
    "vehicle_instant_lockon",
    "vehicle_lock_players", "vehicle_lock_npcs",
    "vehicle_infinite_lock_range", "vehicle_chernobog_driver",
    "vehicle_buff_all_rockets",
    "vehicle_cannon_range",
}

local function presentation_vehicle()
    if not bound or not dependencies then return 0 end
    local vehicle = dependencies.local_vehicle()
    if not dependencies.entity_exists(vehicle) then vehicle = ShellState.last_vehicle end
    return vehicle
end


local function restore_local_vehicle_presentation()
    if not dependencies then return true end
    local vehicle = presentation_vehicle()
    if dependencies.entity_exists(vehicle) then
        dependencies.invoke_void(dependencies.H.SET_VEHICLE_INDICATOR_LIGHTS, vehicle, 0, false)
        dependencies.invoke_void(dependencies.H.SET_VEHICLE_INDICATOR_LIGHTS, vehicle, 1, false)
        dependencies.invoke_void(dependencies.H.SET_VEHICLE_RADIO_ENABLED, vehicle, true)
        dependencies.invoke_void(dependencies.H.SET_VEHICLE_LIGHT_MULTIPLIER, vehicle, 1.0)
        dependencies.invoke_void(dependencies.H.SET_VEHICLE_FULLBEAM, vehicle, false)
    end
    ShellState.doors_locked = false
    return true
end

local suppression_generation = 0 -- retained lifecycle generation; no retired active dispatcher

-- Named control values, independent of current vehicle/model. Kept inline in the
-- vehicle owner and serviced only by its existing gameplay scheduler.
local function create_combat_setups(context, deps)
    local fields = {
        {"vehicle_driver_weapons","bool"}, {"vehicle_chernobog_driver","bool"}, {"vehicle_roof_turret","bool"},
        {"vehicle_complex_reticle","bool"}, {"vehicle_rapid_fire","bool"},
        {"vehicle_rapid_fire_guns","bool"}, {"vehicle_infinite_ammo","bool"},
        {"vehicle_instant_lockon","bool"},
        {"vehicle_lock_players","bool"}, {"vehicle_lock_npcs","bool"},
        {"vehicle_infinite_lock_range","bool"}, {"vehicle_buff_all_rockets","bool"},
        {"vehicle_cannon_range","bool"}, {"vehicle_lab_cannons","bool"},
        {"vehicle_rapid_fire_delay","int",0,500},
        {"vehicle_rocket_speed","float",0.25,8.0},
        {"vehicle_rocket_lifetime","float",0.0,120.0},
        {"vehicle_cannon_distance","float",500.0,5000.0},
        }
    local by_key = {}; for _,field in ipairs(fields) do by_key[field[1]]=field end
    -- Old saved setups may contain retired controls. Validate and discard only
    -- these known values, preserving every live field without recreating features.
    local retired_fields = {
        vehicle_auto_lock_fire={"vehicle_auto_lock_fire","bool"},
        vehicle_rocket_range_unlimited={"vehicle_rocket_range_unlimited","bool"},
        vehicle_rocket_range={"vehicle_rocket_range","float",0.5,30.0},
        vehicle_missile_profile={"vehicle_missile_profile","combo",0,3},
        vehicle_missile_turn_rate={"vehicle_missile_turn_rate","float",0.1,8.0},
        vehicle_missile_turn_limit={"vehicle_missile_turn_limit","float",0.5,15.0},

        vehicle_oppressor_rockets={"vehicle_oppressor_rockets","bool"},
        vehicle_lab_mk2_tracking={"vehicle_lab_mk2_tracking","bool"},
        vehicle_lab_mk2_profile={"vehicle_lab_mk2_profile","combo",0,2},
        vehicle_cannon_profile={"vehicle_cannon_profile","combo",0,2},
    }
    local epoch,busy=0,false
    local function current(token)
        assert(token==epoch,"Combat setup cancelled by newer lifecycle intent")
    end
    local S={rows={},pending=nil,phase="loading",detail="Combat setups awaiting gameplay tick",
        loaded=false,debt={},active_name=nil}
    local api={}
    local function valid_name(name)
        return type(name)=="string" and #name>0 and #name<=64 and name:find("%S")~=nil
            and not name:find("[%z\1-\31\127]") and utf8.len(name)~=nil
    end
    local function valid(field,value)
        if field[2]=="bool" then return type(value)=="boolean" end
        return type(value)=="number" and value==value and value>=field[3] and value<=field[4]
            and (field[2]=="float" or value%1==0)
    end
    local function equal(field,a,b)
        if field[2]=="float" and type(a)=="number" and type(b)=="number" then
            return math.abs(a-b)<=1e-6*math.max(1,math.abs(a),math.abs(b))
        end
        return a==b
    end
    local function hex(s) return (s:gsub(".",function(c)return ("%02X"):format(c:byte())end)) end
    local function unhex(s)
        assert(#s>0 and #s<=128 and #s%2==0 and not s:find("[^0-9A-F]"),"Invalid encoded name")
        local name=s:gsub("..",function(pair)return string.char(tonumber(pair,16))end)
        assert(valid_name(name),"Invalid UTF-8 setup name");return name
    end
    local function sorted(rows)
        local names={};for name in pairs(rows) do names[#names+1]=name end
        table.sort(names);assert(#names<=32,"Combat setup count exceeds 32");return names
    end
    local function encode(rows)
        local lines={"CSCRIPT_COMBAT_SETUPS_V1"}
        for _,name in ipairs(sorted(rows)) do
            assert(valid_name(name),"Invalid setup name");lines[#lines+1]="S|"..hex(name)
            for _,field in ipairs(fields) do
                local value=rows[name][field[1]];assert(valid(field,value),"Invalid field: "..field[1])
                lines[#lines+1]=field[1].."|"..field[2].."|"..(type(value)=="number" and ("%.17g"):format(value) or tostring(value))
            end
            lines[#lines+1]="E"
        end
        local bytes=table.concat(lines,"\n").."\n";assert(#bytes<=65536,"Combat store exceeds 64 KiB");return bytes
    end
    local function decode(bytes)
        assert(type(bytes)=="string" and #bytes<=65536,"Invalid combat store size")
        assert(bytes:sub(-1)=="\n","Incomplete combat store")
        local rows,current,count={},nil,0;local first=true
        for line in bytes:gmatch("([^\n]*)\n") do
            if first then assert(line=="CSCRIPT_COMBAT_SETUPS_V1","Unknown combat store format");first=false
            elseif line:sub(1,2)=="S|" then
                assert(not current,"Unfinished setup");local name=unhex(line:sub(3))
                assert(not rows[name],"Duplicate setup");count=count+1;assert(count<=32,"Too many setups")
                current={name=name,values={},seen={},count=0};rows[name]=current.values
            elseif line=="E" then
                assert(current and current.count==#fields,"Incomplete setup");current=nil
            else
                assert(current,"Unexpected combat store line")
                local key,kind,raw=line:match("^([^|]+)|([^|]+)|([^|]+)$")
                local field=by_key[key] or retired_fields[key];assert(field and kind==field[2],"Unknown combat field/type")
                assert(not current.seen[key],"Duplicate combat field");current.seen[key]=true
                local value
                if kind=="bool" then assert(raw=="true" or raw=="false","Invalid boolean");value=raw=="true"
                else value=tonumber(raw) end
                assert(valid(field,value),"Invalid combat value")
                if by_key[key] then current.values[key]=value;current.count=current.count+1 end
            end
        end
        assert(not first and not current,"Truncated combat store");return rows
    end
    local config=context.CScript.Config
    local available=type(config)=="table" and type(config.RegisterStore)=="function"
        and type(config.Load)=="function" and type(config.Save)=="function" and type(context.Root)=="string"
    if available then
        local ok,result,why=pcall(config.RegisterStore,"modules.vehicle","combat_setups",{
            path=context.Root.."\\combat_setups.txt",encode=encode,decode=decode})
        available=ok and result==true
        if not available then S.detail=tostring(why or result) end
    end
    local getters={bool="IsToggled",float="GetFloatValue",int="GetIntValue",combo="GetListIndex"}
    local setters={bool="Toggle",float="SetFloatValue",int="SetIntValue",combo="SetListIndex"}
    local function feature(field,expected)
        local key=field[1];local f=deps.feature_ref(key)
        assert(f and (not expected or f==expected),"Feature replaced/unavailable: "..key)
        -- compat's single documented virtual integer has no host metadata.
        if key~="vehicle_rapid_fire_delay" then
            assert(type(f.GetHash)=="function","Feature identity unavailable: "..key)
            local hash,id=f:GetHash(),deps.feature_id(key)
            assert(type(hash)=="number" and hash%1==0 and type(id)=="number"
                and (hash & 0xFFFFFFFF)==(id & 0xFFFFFFFF),"Feature identity mismatch: "..key)
        else assert(type(f)=="table","Virtual integer identity unavailable") end
        assert(type(f[getters[field[2]]])=="function" and type(f[setters[field[2]]])=="function","Typed feature unavailable: "..key)
        if key~="vehicle_rapid_fire_delay" then assert(type(f.TriggerCallback)=="function","Feature callback unavailable: "..key) end
        return f
    end
    local function read(field,expected,token)
        if token~=nil then current(token) end
        local f=feature(field,expected)
        if token~=nil then current(token) end
        local value=f[getters[field[2]]](f)
        if token~=nil then current(token) end
        assert(valid(field,value),"Invalid typed readback: "..field[1]);assert(feature(field,f)==f)
        if token~=nil then current(token) end
        return value,f
    end
    local function write(field,value,f,token)
        current(token);assert(valid(field,value));f=feature(field,f);current(token)
        local owned=S.debt[field[1]]
        local function remember(entry,description)
            if not entry or S.debt[description[1]]~=entry or token~=epoch or not entry.unknown then return end
            local ok,observed=pcall(read,description,entry.feature,token)
            if ok and token==epoch and S.debt[description[1]]==entry then
                -- This is an observation AFTER a failed attempt, not ownership
                -- proof. An unchanged third value remains uncertain; a later
                -- distinct change can be preserved as newer external intent.
                entry.failure_value=observed;entry.failure_known=true
            end
        end
        local ok,why=pcall(function()
            if owned and owned.feature==f then owned.unknown=true;owned.failure_known=false end
            local result=f[setters[field[2]]](f,value)
            current(token);assert(result~=false,"Setter rejected: "..field[1])
            if field[1]~="vehicle_rapid_fire_delay" then
                current(token);result=f:TriggerCallback();current(token)
                assert(result~=false,"Callback rejected: "..field[1])
            end
            local observed=read(field,f,token);assert(equal(field,observed,value),"Setter readback mismatch: "..field[1])
            if owned and S.debt[field[1]]==owned then owned.unknown=false;owned.failure_known=false end
        end)
        if not ok then
            remember(owned,field)
            error(why,0)
        end
    end
    local function capture(token)
        local values,refs={},{}
        for _,field in ipairs(fields) do values[field[1]],refs[field[1]]=read(field,nil,token) end
        return values,refs
    end
    local function restore(token)
        token=token or epoch;current(token)
        if next(S.debt)==nil then S.active_name=nil;return true,"" end
        local failures={}
        -- Re-evaluate EACH obligation just before its write. An earlier callback
        -- may have changed a later scalar; it is not an instruction to replay a
        -- stale whole-settings snapshot over the user's newer value.
        for _,field in ipairs(fields) do
            if token~=epoch then return false,"Combat restore cancelled by newer intent" end
            local key=field[1];local entry=S.debt[key]
            if entry then
                local ok,why=pcall(function()
                    local value=read(field,entry.feature,token);current(token)
                    if S.debt[key]~=entry then return end
                    if not equal(field,value,entry.applied) and not equal(field,value,entry.before) then
                        if entry.unknown and (not entry.failure_known or equal(field,value,entry.failure_value)) then
                            error("Unconfirmed write ownership: "..key,0)
                        end
                        S.debt[key]=nil -- distinct post-success or post-failure external intent wins
                        return
                    end
                    entry.unknown=false
                    if not equal(field,value,entry.before) or entry.callback_pending then
                        -- Publish debt before invoking a possibly reentrant host.
                        entry.callback_pending=true
                        write(field,entry.before,entry.feature,token)
                        current(token)
                        if S.debt[key]==entry then entry.callback_pending=false end
                    end
                    current(token)
                    if S.debt[key]==entry then S.debt[key]=nil end
                end)
                if not ok then failures[#failures+1]=tostring(why) end
            end
        end
        if token~=epoch then return false,"Combat restore cancelled by newer intent" end
        if next(S.debt)==nil then S.active_name=nil end
        return #failures==0 and next(S.debt)==nil,table.concat(failures,"; ")
    end
    local function apply(name,values,token)
        current(token);assert(next(S.debt)==nil,"Restore previous setup before applying another")
        local before,refs=capture(token);current(token)
        local ok,why=pcall(function()
            for _,field in ipairs(fields) do
                current(token)
                local key=field[1];local value=read(field,refs[key],token)
                if not equal(field,value,values[key]) then
                    local entry=S.debt[key] or {before=before[key],feature=refs[key]}
                    entry.applied=values[key];entry.callback_pending=true;S.debt[key]=entry
                    write(field,values[key],refs[key],token)
                    current(token)
                    if S.debt[key]==entry then entry.callback_pending=false end
                end
            end
            for _,field in ipairs(fields) do
                assert(equal(field,read(field,refs[field[1]],token),values[field[1]]),"Final setup readback mismatch: "..field[1])
            end
        end)
        -- Panic may have cleared some debts deliberately. Never rebuild them
        -- from an old batch snapshot after that newer intent has taken effect.
        if token~=epoch then error("Combat setup cancelled by newer lifecycle intent",0) end
        S.active_name=next(S.debt)~=nil and name or nil
        if not ok then
            local rollback,detail=restore(token)
            error(tostring(why)..(rollback and "; partial writes restored" or "; restoration pending: "..detail),0)
        end
    end
    local function persist(rows,token)
        current(token);local wanted=encode(rows)
        local ok,why=config.Save("combat_setups",rows);current(token);assert(ok==true,tostring(why or "Combat store write rejected"))
        local loaded,observed=config.Load("combat_setups",{})
        current(token);assert(loaded==true and encode(observed)==wanted,"Combat store readback failed")
        S.rows=rows
    end
    function api.Request(action,name)
        if not available then return false,"Config combat store service unavailable" end
        if action~="save" and action~="apply" and action~="restore" and action~="delete" then return false,"Unknown combat setup action" end
        if action~="restore" and not valid_name(name) then return false,"Use a nonempty UTF-8 name up to 64 bytes without control characters" end
        if S.pending or busy then return false,"Combat setup request already pending" end
        S.pending={action=action,name=name};S.phase="queued";S.detail="Combat setup "..action.." queued on gameplay tick"
        return true,S.detail
    end
    function api.Snapshot()
        local rows={};for _,name in ipairs(sorted(S.rows)) do rows[#rows+1]={name=name,field_count=#fields} end
        return {rows=rows,pending=S.pending~=nil or busy,phase=S.phase,detail=S.detail,active_name=S.active_name,restore_available=next(S.debt)~=nil}
    end
    function api.Tick()
        if not available or busy then return end
        busy=true;local token=epoch;local request
        local ok,why=pcall(function()
            if not S.loaded then
                S.loaded=true;local invoked,loaded,rows=pcall(config.Load,"combat_setups",{})
                current(token)
                if invoked and loaded==true and type(rows)=="table" then S.rows=rows;S.phase="ready";S.detail="Combat setups loaded"
                else S.load_error=tostring(invoked and rows or loaded);S.phase="failed";S.detail=S.load_error end
            end
            current(token);request=S.pending;if not request then return end;S.pending=nil
            if request.action=="restore" then local restored,detail=restore(token);assert(restored,detail);return end
            assert(not S.load_error,"Malformed/unavailable combat store: "..tostring(S.load_error))
            if request.action=="apply" then local values=S.rows[request.name];assert(values,"Combat setup does not exist");apply(request.name,values,token);return end
            local rows={};for name,values in pairs(S.rows) do rows[name]=values end
            if request.action=="save" then rows[request.name]=capture(token)
            else assert(rows[request.name],"Combat setup does not exist");rows[request.name]=nil end
            persist(rows,token)
        end)
        busy=false
        if token~=epoch then S.phase="cancelled";S.detail="Combat setup cancelled by newer lifecycle intent";return end
        if not request and ok then return end
        local phases={save="saved",apply="applied",restore="restored",delete="deleted"}
        S.phase=ok and phases[request.action] or "failed"
        S.detail=ok and ("Combat setup "..S.phase.."; control readbacks only, game effects unverified") or tostring(why)
    end
    function api.Cancel(reason)
        epoch=epoch+1;S.pending=nil;S.phase="cancelled";S.detail=reason or "Combat setup cancelled"
    end
    function api.Drain()
        api.Cancel("Combat setup drain requested")
        if busy then return false,"Combat setup operation cancelling; restoration pending" end
        busy=true
        local called,ok,why=pcall(restore,epoch)
        busy=false
        if not called then why,ok=ok,false end
        if not ok then S.phase="failed";S.detail=why end
        return ok==true,why
    end
    function api.ResetIntent()
        api.Cancel("Combat setup cancelled by Panic/Reset")
        -- Existing Panic/Reset deliberately turns these controls OFF and selects
        -- Vanilla. Even an equal-value reset is newer intent than this Apply.
        S.pending=nil
        for _,field in ipairs(fields) do
            if field[2]=="bool" or field[1]=="vehicle_missile_profile" then S.debt[field[1]]=nil end
        end
        if next(S.debt)==nil then S.active_name=nil end
    end
    return api
end

local function retirement_identity(key, handle)
    assert(type(handle)=="number" and handle%1==0 and handle>0, "Previous retired target unavailable")
    assert(dependencies.entity_exists(handle), "Previous retired target is not streamed")
    local host=dependencies.GTA
    assert(host and type(host.HandleToPointer)=="function", "Retired target identity adapter unavailable")
    local entity=host.HandleToPointer(handle)
    local kind=key=="prevent_shuffle" and "IsPed" or "IsVehicle"
    assert(entity and type(entity[kind])=="function" and entity[kind](entity)==true, "Retired target kind unavailable")
    assert(type(entity.GetAddress)=="function", "Retired target address unavailable")
    local address=entity:GetAddress()
    assert(type(address)=="number" and address%1==0 and address>=65536 and address<9007199254740991, "Retired target identity unreadable")
    return {handle=handle,address=address}
end

local function process_retired_cleanup()
    if not bound then return true end
    local ok=true
    for key in pairs(retired_cleanup) do
        local restored,result=pcall(function()
            local f=dependencies.feature_ref(key)
            if f and f:IsToggled() then
                -- A raw or late ON value never proves an effect was applied.
                -- Suppress it without manufacturing physical release ownership.
                assert(dependencies.set_toggle(key,false)~=false,"Retired toggle OFF rejected")
            end
            local lease=retired_release[key]
            if (key=="prevent_shuffle" or key=="radio_silence") and lease then
                if type(lease)~="table" then
                    -- This migration token existed at bind, before the retired
                    -- dispatcher ran. Pin its first verifiable handoff target;
                    -- failed/missing evidence remains pending, never 'restored'.
                    local handle=key=="prevent_shuffle" and dependencies.local_ped() or presentation_vehicle()
                    lease=retirement_identity(key,handle)
                    retired_release[key]=lease
                end
                local current=retirement_identity(key,lease.handle)
                assert(retired_release[key]==lease,"Retired cleanup ownership changed")
                if current.address~=lease.address then
                    -- Proven handle reuse: relinquish the old instance without
                    -- writing its baseline into the new occupant.
                    return true
                end
                if key=="prevent_shuffle" then
                    assert(dependencies.invoke_void(dependencies.H.SET_PED_CONFIG_FLAG,lease.handle,184,false)~=false)
                else
                    assert(dependencies.invoke_void(dependencies.H.SET_VEHICLE_RADIO_ENABLED,lease.handle,true)~=false)
                end
            elseif key=="vehicle_lab_continuous_repair" then VehicleLab.state.last_maintenance_ms=0 end
        end)
        if restored and result~=false then retired_cleanup[key]=nil;retired_release[key]=nil else ok=false end
    end
    return ok
end

local function register_features()
    if features_registered then return true end
    if not bound then return false end
    local feature_id = require_binding("feature_id", dependencies.feature_id)
    local feature_ref = require_binding("feature_ref", dependencies.feature_ref)
    local function add_toggle(key, name, description, default, callback)
        assert(not RETIRED_GENERAL_KEYS[key], "Retired maintenance controls cannot be registered")
        local feature = FeatureMgr.AddFeature(
            feature_id(key), name, eFeatureType.Toggle, description or "", callback
        )
        if not feature then
            return nil
        end
        if feature and type(feature.SetDefaultValue) == "function" then
            pcall(function()
                feature:SetDefaultValue(default == true)
                if default == true and type(feature.Toggle) == "function" and not feature:IsToggled() then
                    feature:Toggle(true)
                end
            end)
        end
        ShellState.registered_count = ShellState.registered_count + 1
        return feature
    end
    local function add_button(key, name, description, callback)
        local feature = FeatureMgr.AddFeature(feature_id(key), name, eFeatureType.Button, description or "", callback)
        if not feature then
            return nil
        end
        ShellState.registered_count = ShellState.registered_count + 1
        return feature
    end
    local function add_combo(key, name, description, values, default, callback)
        local feature = FeatureMgr.AddFeature(feature_id(key), name, eFeatureType.Combo, description or "", callback)
        if not feature then
            return nil
        end
        if feature then pcall(function() feature:SetList(values):SetListIndex(default or 0) end) end
        ShellState.registered_count = ShellState.registered_count + 1
        return feature
    end
    local function add_slider_float(key, name, description, minimum, maximum, step, default)
        local feature = FeatureMgr.AddFeature(feature_id(key), name, eFeatureType.SliderFloat, description or "")
        if not feature then
            return nil
        end
        if feature then
            pcall(function()
                local initial = default or minimum
                feature:SetLimitValues(minimum, maximum)
                feature:SetStepSize(step or 0.1)
                feature:SetDefaultValue(initial)
                if type(feature.SetFloatValue) == "function" then feature:SetFloatValue(initial) end
            end)
        end
        ShellState.registered_count = ShellState.registered_count + 1
        return feature
    end
