local function frame_tick(now)
    if not started or not bound then return end
    if runtime_writes_suspended then
        VehicleMods.restore_mounted_targets()
        VehicleMods.driver_assistance.Cancel("Delivery suspended.")
        VehicleMods.driver_assistance.RestoreAccess()
        if roof_turret and roof_turret.Pending() then roof_turret.Drain(tonumber(now)or runtime_now_ms())end
        return
    end
    if vehicle_fly then vehicle_fly.Tick() end
    if damage_auto_repair then damage_auto_repair.Tick(tonumber(now)or runtime_now_ms()) end
    if roof_turret then roof_turret.Tick(dependencies.is_on("vehicle_roof_turret"),tonumber(now)or runtime_now_ms())end
    if driver_weapons then
        local vehicle=dependencies.local_vehicle()
        local model=dependencies.entity_exists(vehicle) and dependencies.invoke_int(dependencies.H.GET_ENTITY_MODEL,vehicle) or 0
        local hunter=(model & 0xFFFFFFFF)==(Utils.Joaat("hunter") & 0xFFFFFFFF)
        local cherno=(model & 0xFFFFFFFF)==(Utils.Joaat("chernobog") & 0xFFFFFFFF)
        local hunter_cannon=hunter and dependencies.is_on("vehicle_driver_weapons")
        driver_weapons.Tick(hunter_cannon
            or (cherno and dependencies.is_on("vehicle_chernobog_driver")),
            hunter_cannon)
    end
    fast_enter_exit_animation_tick(
        tonumber(now) or runtime_now_ms(),
        dependencies.local_ped()
    )
    VehicleMods.driver_assistance.AccessTick(now)
    VehicleMods.driver_assistance.Tick(now)
    -- FrameRequested can tick independently of FastTick. Both must supply
    -- a CURRENT, fully resolved local shooter/vehicle rather than nil handles
    -- (which were overwriting the true acquisition readback as unavailable).
    VehicleMods.instant_lock_observe(now,dependencies.local_ped(),dependencies.local_vehicle())
    VehicleMods.frame_tick(now)
    VehicleLab.frame_tick(now)
    if not dependencies.is_on("vehicle_fly") then VehicleMods.driver_assistance.Brake(now) end
    local manager = module_context and module_context.CScript and module_context.CScript.VehicleManager
    if manager and type(manager.FrameTick) == "function" then manager.FrameTick(now) end
end

local function fast_tick(now, ped)
    if not bound then
        return
    end

    if runtime_writes_suspended then
        return
    end

    if VehicleLab.state.backend then VehicleLab.state.backend.Tick() end
    local life_ped=dependencies.local_ped()
    if not dependencies.entity_exists(life_ped)
        or dependencies.invoke_bool(dependencies.H.IS_ENTITY_DEAD,life_ped,false) then
        VehicleLab.restore()
        VehicleMods.restore()
        return
    end
    local current_rapid_delay_ms =
        configured_rapid_delay_ms()
    if ShellState.last_rapid_fire_delay_ms == nil then
        ShellState.last_rapid_fire_delay_ms = current_rapid_delay_ms
    elseif current_rapid_delay_ms ~= ShellState.last_rapid_fire_delay_ms then
        ShellState.last_rapid_fire_delay_ms = current_rapid_delay_ms
        reapply_rapid_fire()
    end
    if vehicle_reticle then
        local ok,detail=vehicle_reticle.Tick(now)
        if ok==false then dependencies.log_error_once("vehicle_reticle",detail) end
    end
    sync_fast_enter_exit(now, false)
    ped = tonumber(ped) or dependencies.local_ped()
    if not dependencies.entity_exists(ped) then
        VehicleMods.fast_tick(now, 0, 0)
        return
    end

    local vehicle = dependencies.local_vehicle()
    local in_vehicle = dependencies.entity_exists(vehicle)
    if in_vehicle then
        ShellState.last_vehicle = vehicle
    end
    ShellState.was_in_vehicle = in_vehicle
    VehicleMods.fast_tick(now, ped, vehicle)
end


local function suspend_runtime_writes()
    if vehicle_fly then vehicle_fly.Cancel() end
    if damage_auto_repair then damage_auto_repair.Invalidate() end
    if runtime_writes_suspended then
        if not bound then return true end
        local timing_ok=VehicleLab.restore_cannon_timing("Vehicle remains suspended")
        local balance_ok=VehicleLab.restore_cannon_balance('Vehicle remains suspended')
        return timing_ok and balance_ok
    end

    runtime_writes_suspended = true

    if not bound then
        return true
    end

    local lab_ok, lab_result =
        pcall(
            VehicleLab.restore
        )

    local mods_ok, mods_result =
        pcall(
            VehicleMods.restore
        )

    local presentation_ok, presentation_result =
        pcall(
            restore_local_vehicle_presentation
        )

    local fast_ok, fast_result =
        pcall(
            restore_fast_enter_exit
        )

    if not lab_ok
        or lab_result == false then
        return false,
            tostring(
                lab_result
                or "Vehicle Lab restore failed"
            )
    end

    if not mods_ok
        or mods_result == false then
        return false,
            tostring(
                mods_result
                or "Vehicle runtime restore failed"
            )
    end

    if not presentation_ok
        or presentation_result == false then
        return false,
            tostring(
                presentation_result
                or "Vehicle presentation restore failed"
            )
    end

    if not fast_ok
        or fast_result == false then
        return false,
            tostring(
                fast_result
                or "Fast Enter/Exit restore failed"
            )
    end

    return true
end

local function revalidate_runtime_state()
    if not bound then
        return false,
            "vehicle module is not compatibility-bound"
    end

    if VehicleLab.cannon_timing_needs_cleanup()and not VehicleLab.cannon_timing_cleanup_tick()then
        return false,"Cannon cleanup pending"
    end
    runtime_writes_suspended = false

    VehicleMods.state.controller.force_refresh = true

    VehicleLab.state.weapon_runtime_signature = nil
    VehicleLab.state.ammo_runtime_signature = nil

    ShellState.last_rapid_fire_delay_ms = nil
    ShellState.fast_enter_exit.dirty = true

    return true
end

local function panic_reset()
    if vehicle_fly then vehicle_fly.Cancel() end
    if damage_auto_repair then damage_auto_repair.Cancel() end
    if not bound then return true end
    if combat_setups then combat_setups.ResetIntent() end
    for _, key in ipairs(VEHICLE_TOGGLE_KEYS) do dependencies.set_toggle(key, false) end
    local lab_ok=VehicleLab.restore()
    local mods_ok=VehicleMods.restore()
    local fast_ok=restore_fast_enter_exit()
    local presentation_ok=restore_local_vehicle_presentation()
    ShellState.last_vehicle = 0
    ShellState.was_in_vehicle = false
    return lab_ok~=false and mods_ok~=false and fast_ok~=false and presentation_ok~=false
end

local function register_vehicle_change_handler()
    if handlers_registered then return true end
    if not (EventMgr and type(EventMgr.RegisterHandler) == "function"
            and eLuaEvent and eLuaEvent.ON_VEHICLE_CHANGE ~= nil) then
        return false
    end
    local ok, handler_id = pcall(EventMgr.RegisterHandler, eLuaEvent.ON_VEHICLE_CHANGE, function()
        if not (started and bound and public_api and dependencies
                and type(dependencies.local_vehicle) == "function") then
            return
        end
        local previous = ShellState.last_vehicle
        local current = dependencies.local_vehicle()
        local call_ok, result =
            pcall(
                public_api.OnVehicleChange,
                previous,
                current
            )

        if (not call_ok or result == false)
            and type(
                dependencies.log_error_once
            ) == "function" then
            dependencies.log_error_once(
                "vehicle_change_ammo",
                call_ok
                and "vehicle-change restoration/reapply returned false"
                or result
            )
        end
    end)
    if not ok
        or type(handler_id) ~= "number" then
        return false
    end

    vehicle_change_handler_id =
        handler_id

    handlers_registered =
        true
    return true
end


function Module.BindCompatibility(bindings)
    if not module_context then error("vehicle module must initialize before compatibility binding", 2) end
    if bound then return VehicleLab, VehicleMods end
    if type(bindings) ~= "table" then error("vehicle compatibility bindings must be a table", 2) end

    dependencies = bindings
    local repair_dependencies=dependencies
    local fly_dependencies=dependencies
    vehicle_fly=new_vehicle_fly({
        Try=function(kind,hash,...)return module_context.Natives.Try(kind,hash,...)end,
        Enabled=function()return started and bound and not runtime_writes_suspended
            and dependencies==fly_dependencies and dependencies.is_on("vehicle_fly")==true end,
        Speed=function()return dependencies.slider_float("vehicle_fly_speed",2.0)end,
        CameraRotation=function()
            local world=module_context.CScript and module_context.CScript.World
            if world and type(world.CameraFreedomSnapshot)=="function" then
                return world.CameraFreedomSnapshot()
            end
        end,
        LocalPlayer=dependencies.local_player_id,LocalPed=dependencies.local_ped,
        LocalVehicle=dependencies.local_vehicle,Session=function()return roof_turret_session end,
        Address=function(handle)
            local entity=dependencies.GTA.HandleToPointer(handle)
            assert(entity and entity:IsVehicle()==true,"Vehicle identity unavailable")
            return entity:GetAddress()
        end,
        KeyDown=function(vk)
            assert(Utils and type(Utils.IsKeyDown)=="function","Keyboard unavailable")
            return Utils.IsKeyDown(vk)
        end,
        GuiOpen=function()
            assert(GUI and type(GUI.IsOpen)=="function","Menu state unavailable")
            return GUI.IsOpen()
        end,
    })
    damage_auto_repair=new_damage_auto_repair({
        Natives=dependencies.Natives,GTA=dependencies.GTA,Players=Players,
        LocalPlayer=dependencies.local_player_id,LocalPed=dependencies.local_ped,LocalVehicle=dependencies.local_vehicle,
        Session=function()return roof_turret_session end,
        Report=function(detail)
            if type(repair_dependencies.log_info)=="function" then
                repair_dependencies.log_info("Auto repair: "..tostring(detail))
            end
        end,
        Enabled=function()return started and bound and not runtime_writes_suspended
            and dependencies==repair_dependencies and dependencies.is_on("vehicle_damage_auto_repair")==true end,
    })
    driver_weapons=create_driver_weapons_owner(DriverWeapons,{
        Memory=dependencies.Memory,Natives=Natives,GTA=GTA,Utils=Utils,GUI=GUI,
        Logger=Logger,FeatureMgr=FeatureMgr,NetworkObjectMgr=NetworkObjectMgr,
        Report=function(detail) dependencies.toast("Driver Weapons: "..tostring(detail),6500,"warning") end,
    })
    local roof_factory=module_context.Modules and module_context.Modules.RoofTurret
    assert(roof_factory and type(roof_factory.New)=="function","Roof turret module is unavailable")
    local roof_assets=roof_factory.CreateAssetActivator({
        Natives=Natives,Utils=Utils,
        FeatureMgr=module_context.Raw and module_context.Raw.FeatureMgr or FeatureMgr,
        FileMgr=module_context.Raw and module_context.Raw.FileMgr or FileMgr,
    })
    roof_turret=roof_factory.New({
        Memory=dependencies.Memory,Natives=Natives,GTA=GTA,Utils=Utils,GUI=GUI,
        FeatureMgr=module_context.Raw and module_context.Raw.FeatureMgr or FeatureMgr,
        FileMgr=module_context.Raw and module_context.Raw.FileMgr or FileMgr,
        Assets={
            revision="speedo50-enhanced-1158-4-runtime",
            models={base="cscript4_speedo50_base",upper="cscript4_speedo50_upper",barrel="cscript4_speedo50_barrel"},
            supportRadius=.165,
            upperOffset={x=0,y=.055046,z=.321427},barrelOffset={x=0,y=0,z=0},
            muzzle={x=.001788,y=.818553,z=.009504},
        },
        EnsureAssets=function(manifest)
            local state,detail=roof_assets.Step(manifest,runtime_now_ms())
            if state=="unsupported"then error(detail,2)end
            return state=="ready",detail
        end,
        ReleaseAssets=function()roof_assets.Stop()end,
        SessionKey=function()return roof_turret_session end,
        Report=function(status,detail)
            if status=="UNAVAILABLE" then dependencies.toast("Roof .50 Cal: "..tostring(detail),6500,"warning")
            elseif status=="ACTIVE" then dependencies.toast("Roof .50 Cal ready. Use normal vehicle attack.",5000,"info")end
            if Logger and type(Logger.LogInfo)=="function"then Logger.LogInfo("[RoofTurret] "..status..": "..tostring(detail))end
        end,
    })
    dependencies.OwnedMemory = module_context.Memory
    VehicleLab, VehicleMods = create_vehicle_system(dependencies)
    reticle_preference=create_reticle_preference(function()return dependencies.Memory end)
    vehicle_reticle=create_vehicle_reticle_controller(reticle_preference,function()
        if not dependencies.is_on("vehicle_complex_reticle") then return false,false end
        local vehicle=dependencies.local_vehicle()
        if not dependencies.entity_exists(vehicle) then return true,false end
        return true,dependencies.invoke_bool(0x25ECB9F8017D98E0,vehicle) -- DOES_VEHICLE_HAVE_WEAPONS
    end)
    if type(VehicleLab) ~= "table" or type(VehicleMods) ~= "table" then
        error("vehicle runtime factory did not return both systems", 2)
    end
    if not register_vehicle_change_handler() then
        error(
            "vehicle module could not register ON_VEHICLE_CHANGE handler",
            2
        )
    end

    bound = true
    combat_setups = create_combat_setups(module_context, dependencies)
    for key in pairs(RETIRED_GENERAL_KEYS) do
        local ok,on=pcall(dependencies.is_on,key)
        if ok and on then retired_cleanup[key]=true;retired_release[key]=true end
    end

    publish_state(
        module_context
    )

    -- SHOULD_COLLIDE stays on this direct function boundary. The preserved
    -- implementation is O(1) until a known local projectile is tracked.
    public_api.ShouldCollide = VehicleMods.should_projectile_collide
    return VehicleLab, VehicleMods
end

function Module.ReapplyRocketTuning()
    return reapply_rocket_tuning()
end

function Module.ReapplyRapidFire()
    return reapply_rapid_fire()
end

function Module.Shutdown()
    if vehicle_fly then vehicle_fly.Cancel() end
    if damage_auto_repair then damage_auto_repair.Cancel() end
    if VehicleMods and not (VehicleMods.driver_assistance.Cancel("Vehicle module unloading.")and VehicleMods.driver_assistance.RestoreAccess())then return false,"Delivery or vehicle access cleanup pending"end
    if roof_turret and roof_turret.Pending()then return false,"Roof turret cleanup is still pending"end
    local reticle_ok,reticle_error=restore_vehicle_reticle()
    if not bound then return reticle_ok,reticle_error end
    local mods_ok, mods_err = pcall(VehicleMods.shutdown)
    local lab_ok, lab_err = pcall(VehicleLab.shutdown)
    local fast_ok, fast_err = pcall(restore_fast_enter_exit)
    local memory_ok = true
    for _, owner in ipairs(MEMORY_OWNER_RESTORE_ORDER) do
        if not module_context.Memory.RestoreOwner(owner) then memory_ok = false end
    end
    if not reticle_ok then return false,tostring(reticle_error) end
    if not lab_ok or lab_err==false then return false, tostring(lab_err or "Vehicle Lab cleanup pending") end
    if not mods_ok or mods_err==false then return false, tostring(mods_err or "Vehicle state restoration pending") end
    if not fast_ok then return false, tostring(fast_err) end
    return memory_ok
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table"
        or type(context.Memory) ~= "table" or type(context.CScript) ~= "table" then
        error("modules.vehicle requires injected State, Memory, and CScript services")
    end
    if module_context and module_context ~= context then
        error("modules.vehicle is already initialized by another context")
    end
    module_context = context
    public_api = {
        ShouldCollide = unavailable_collision,
    }

    function public_api.RequestCombatSetup(action,name)
        if not bound or not combat_setups then return false,"Vehicle combat setup service unavailable" end
        if not started or runtime_writes_suspended then return false,"Vehicle gameplay scheduler unavailable" end
        return combat_setups.Request(action,name)
    end

    function public_api.CombatSetupSnapshot()
        if combat_setups then return combat_setups.Snapshot() end
        return {rows={},pending=false,phase="unavailable",detail="Vehicle combat setup service unavailable",restore_available=false}
    end

    function public_api.RetireGeneralFeatures()
        if not bound then return false,"Vehicle module is not compatibility-bound" end
        if not started or runtime_writes_suspended then return false,"Vehicle gameplay scheduler unavailable" end
        for key in pairs(RETIRED_GENERAL_KEYS) do retired_cleanup[key]=true end
        return true,"Retired general feature OFF/cleanup queued on gameplay tick"
    end

    function public_api.AssignDeliveryVehicle()if not bound then return false,"Vehicle controls unavailable."end;return VehicleMods.driver_assistance.Assign()end
    function public_api.CallDeliveryVehicle()if not bound then return false,"Vehicle controls unavailable."end;return VehicleMods.driver_assistance.Call()end
    function public_api.CancelDelivery()if not bound then return true end;return VehicleMods.driver_assistance.Cancel("Delivery cancelled.")end
    function public_api.DeliverySnapshot()if not bound then return {phase="unavailable",detail="Vehicle controls unavailable.",assigned=false,active=false,cleanup_pending=false}end;return VehicleMods.driver_assistance.Snapshot()end

    function public_api.GetCurrentVehicle()
        if not bound then return 0 end
        return dependencies.local_vehicle()
    end

    function public_api.RefreshPersonalVehicle()
        return queue_personal_vehicle_action("refresh")
    end

    function public_api.AuditPersonalVehicles()
        return queue_personal_vehicle_action("audit")
    end

    function public_api.PersonalVehicleSnapshot()
        return personal_vehicle_snapshot()
    end

    function public_api.SetRocketSpeed(value)
        if not bound then return false, "vehicle module is not compatibility-bound" end
        if runtime_writes_suspended then return false, "vehicle runtime writes are suspended" end
        local numeric = tonumber(value)
        if not numeric or numeric ~= numeric or numeric == math.huge or numeric == -math.huge then
            return false, "rocket speed must be finite"
        end
        numeric = math.max(0.25, math.min(8.0, numeric))
        dependencies.set_slider_float("vehicle_rocket_speed", numeric)
        return reapply_rocket_tuning()
    end

    function public_api.ResetRocketSpeed()
        return public_api.SetRocketSpeed(1.0)
    end

    function public_api.ResetRocketTuning()
        if not bound then return false, "vehicle module is not compatibility-bound" end
        dependencies.set_slider_float("vehicle_rocket_speed", 1.0)
        dependencies.set_slider_float("vehicle_rocket_lifetime", 0.0)
        return reapply_rocket_tuning()
    end

    function public_api.SetRapidFireDelay(value)
        if not bound then return false, "vehicle module is not compatibility-bound" end
        if runtime_writes_suspended then return false, "vehicle runtime writes are suspended" end
        local numeric = math.floor(tonumber(value) or -1)
        if numeric < RAPID_DELAY_MIN_MS or numeric > RAPID_DELAY_MAX_MS then
            return false, ("rapid fire delay must be between %d and %d milliseconds")
                :format(RAPID_DELAY_MIN_MS, RAPID_DELAY_MAX_MS)
        end
        dependencies.set_slider_int("vehicle_rapid_fire_delay", numeric)
        ShellState.last_rapid_fire_delay_ms = numeric
        return reapply_rapid_fire()
    end

    function public_api.GetRapidFireDelay()
        if not bound then return 45 end
        return configured_rapid_delay_ms()
    end

    function public_api.CompositionSnapshot()
        if not bound then return nil end
        local result=VehicleLab.composition_snapshot(dependencies.local_ped(), dependencies.local_vehicle())
        if result then result.cannon_timing=VehicleLab.cannon_timing_snapshot()end
        return result
    end

    function public_api.ProjectileDiagnosticsSnapshot()
        -- Export existing observations only. Never resolve handles, sample the
        -- host, or expose retained physical wrappers/pending-resolution tables.
        local state = VehicleMods and VehicleMods.state or {}
        local function scalar(value)
            local kind = type(value)
            if kind == "string" or kind == "boolean" then return value end
            if kind == "number" and value == value and math.abs(value) < math.huge then return value end
        end
        local function copy(row, fields)
            local result = {}
            for _, key in ipairs(fields) do result[key] = scalar(rawget(row, key)) end
            return result
        end
        local active_fields = {
            "address", "model", "first_seen", "last_seen", "last_guidance_ms", "last_distance",
            "buff_guided_steps", "buff_target", "buff_target_address", "buff_target_lost",
            "fire_window_id", "fire_window_ms", "fire_window_target", "fire_window_target_address",
            "launch_generation", "launch_weapon", "launch_ammo", "template_ammo_ptr",
            "buff_missile_profile", "buff_guidance_authority", "owner_verified", "native_owner_query",
            "first_loss_reason", "first_loss_ms", "first_loss_detail", "launch_sample_target", "launch_sample_target_address",
            "launch_lock_state", "launch_raw_target", "launch_target_address_known",
            "launch_pre_input_ms", "launch_pre_input_lock_state", "launch_pre_input_target", "launch_pre_input_target_address",
            "launch_pre_input_source_bound", "launch_pre_input_same_ms", "launch_fire_control", "launch_window_reason",
            "launch_window_ambiguous", "rearm_known_identity", "rearm_history_unavailable",
        }
        local history_fields = {
            "handle", "address", "model", "first_seen_ms", "last_seen_ms", "end_sample_ms",
            "fire_window_ms", "weapon", "template_ammo_ptr", "target", "guided_steps", "reason",
            "expiry_cause", "guidance_authority", "missile_profile", "projectile_ammo_record",
            "last_distance", "last_guidance_ms", "buff_target_lost",
            "first_loss_reason", "first_loss_ms", "first_loss_detail", "launch_sample_target", "launch_sample_target_address",
            "launch_lock_state", "launch_raw_target", "launch_target_address_known",
            "launch_pre_input_ms", "launch_pre_input_lock_state", "launch_pre_input_target", "launch_pre_input_target_address",
            "launch_pre_input_source_bound", "launch_pre_input_same_ms", "launch_fire_control", "launch_window_reason",
            "launch_window_ambiguous", "fire_window_target", "fire_window_target_address",
            "rearm_known_identity", "rearm_history_unavailable", "native_owner_query", "owner_verified",
        }
        local snapshot = {
            source = "cached-flight-state", live_sampled = false,
            tracked_count = scalar(state.projectile_count),
            active = {}, active_total = 0, active_limit = 16,
            history = {}, history_total = 0, history_limit = 16,
        }
        local selected = {}
        for handle, info in pairs(state.projectiles or {}) do
            snapshot.active_total = snapshot.active_total + 1
            if type(handle) == "number" and scalar(handle) and handle > 0 and handle % 1 == 0
                and type(info) == "table" then
                local at = 1
                while selected[at] and selected[at].handle < handle do at = at + 1 end
                if at <= 16 then
                    table.insert(selected, at, { handle = handle, info = info })
                    if #selected > 16 then table.remove(selected) end
                end
            end
        end
        for _, item in ipairs(selected) do
            local row = copy(item.info, active_fields)
            row.handle = item.handle
            row.pending_resolution = type(rawget(item.info, "pending_resolution")) == "table"
            row.resolution_evidence = type(rawget(item.info, "resolution_evidence")) == "table"
            snapshot.active[#snapshot.active + 1] = row
        end
        local history = state.projectile_history or {}
        snapshot.history_total = #history
        for index = math.max(1, #history - 15), #history do
            if type(history[index]) == "table" then
                snapshot.history[#snapshot.history + 1] = copy(history[index], history_fields)
            end
        end
        snapshot.active_count, snapshot.history_count = #snapshot.active, #snapshot.history
        snapshot.active_truncated = snapshot.active_total - snapshot.active_count
        snapshot.history_truncated = snapshot.history_total - snapshot.history_count
        return snapshot
    end

    function public_api.PowerSnapshot()
        local state = VehicleMods and VehicleMods.state or {}
        return { requested = bound and dependencies.is_on("vehicle_engine_power") or false,
            backend = state.power_backend or "frame-torque-native", status = state.power_status or "IDLE",
            detail = state.power_detail or "No frame request", value = state.power_requested_value,
            invocation_accepted = state.power_accepted == true, readback_verified = false,
            gameplay_verified = false, pending_release = state.power_pending_release == true }
    end

