    end

    function public_api.DrainUnload()
        if damage_auto_repair then damage_auto_repair.Cancel() end
        local targets_ok=not VehicleMods or VehicleMods.restore_mounted_targets()
        if VehicleMods then VehicleMods.instant_lock_state().pending_rearm=nil end
        local timing_ok,timing_detail=true,nil
        if VehicleLab then timing_ok,timing_detail=VehicleLab.unload_cannon_timing()end
        local setups_ok,setups_detail=true,nil
        if combat_setups then setups_ok,setups_detail=combat_setups.Drain() end
        local delivery_ok=VehicleMods.driver_assistance.Cancel("Vehicle cleanup.")and VehicleMods.driver_assistance.RestoreAccess()
        local retired_ok=process_retired_cleanup()
        local driver_ok,driver_detail=true,nil
        if driver_weapons then driver_ok,driver_detail=driver_weapons.Drain() end
        local roof_ok=true
        if roof_turret then roof_ok=roof_turret.Drain(runtime_now_ms())end
        -- Boost release has no native restoration work, even if identity reads
        -- are unavailable or the host worker is stopped. Other owners still drain.
        if VehicleLab then VehicleLab.restore_unlimited_boost("unload") end
        return delivery_ok==true and timing_ok==true and driver_ok==true and roof_ok==true and setups_ok==true and retired_ok==true and targets_ok==true,timing_detail or setups_detail or driver_detail or(not roof_ok and"Roof turret cleanup pending"or not targets_ok and 'Mounted targeting cleanup pending' or nil)
    end

    function public_api.CannonTimingRestoreRequested()
        return bound and VehicleLab.cannon_timing_needs_cleanup()or false
    end

    function public_api.CannonTimingRestoreTick()
        return not bound or VehicleLab.cannon_timing_cleanup_tick()
    end

    function public_api.VehicleFlySnapshot()
        return vehicle_fly and vehicle_fly.Snapshot() or {status="OFF"}
    end

    function public_api.FrameTick(now)
        return frame_tick(now)
    end

    function public_api.FrameRequested()
        if not started or not bound then return false end
        if runtime_writes_suspended then return (roof_turret and roof_turret.NeedsTick())or VehicleMods.mounted_targets_pending() or VehicleMods.driver_assistance.NeedsTick() or VehicleMods.driver_assistance.AccessPending() end
        local manager = module_context and module_context.CScript and module_context.CScript.VehicleManager
        local manager_requested = manager and type(manager.FrameRequested) == "function"
            and manager.FrameRequested() == true
        return manager_requested
            or VehicleMods.projectile_changes_requested()
            or next(VehicleMods.state.projectiles)~=nil or VehicleMods.state.projectile_window_active
            or dependencies.is_on("vehicle_damage_auto_repair")
            or VehicleMods.mounted_targets_pending()
            or VehicleLab.cannon_timing_tick_requested()
            or next(retired_cleanup)~=nil
            or dependencies.is_on("vehicle_driver_weapons")
            or dependencies.is_on("vehicle_chernobog_driver")
            or dependencies.is_on("vehicle_roof_turret")
            or(roof_turret and roof_turret.NeedsTick())
            or (driver_weapons and driver_weapons.NeedsTick())
            or dependencies.is_on("vehicle_rapid_fire")
            or dependencies.is_on("vehicle_rapid_fire_guns")
            or dependencies.is_on("vehicle_instant_lockon")
            or (VehicleMods.state.instant_lock and VehicleMods.state.instant_lock.owned == true)
            or dependencies.is_on("vehicle_fly")
            or dependencies.is_on("vehicle_superdrive")
            or dependencies.is_on("vehicle_drift_mode")
            or dependencies.is_on("vehicle_disable_burnout")
            or dependencies.is_on("vehicle_quick_brake") or dependencies.is_on("vehicle_instant_brake")
            or VehicleMods.driver_assistance.NeedsTick() or VehicleMods.driver_assistance.AccessPending()
            or dependencies.is_on("vehicle_bypass_player_restrictions")
            or dependencies.is_on("vehicle_unlimited_jump")
            or VehicleMods.state.traction_owner~=nil or VehicleMods.state.jump_controller~=nil
            or dependencies.is_on("vehicle_engine_power")
            or VehicleMods.state.power_vehicle ~= 0 or VehicleMods.state.power_pending_release == true
            or dependencies.is_on("vehicle_lab_cannons")
            or dependencies.is_on("vehicle_cannon_range")
            or VehicleMods.state.direct_rapid_active == true
            or (tonumber(VehicleLab.state.native_cannon_profile_ptr) or 0) ~= 0
            or dependencies.is_on("vehicle_fast_enter_exit")
            or ShellState.fast_enter_exit.direct_active == true
            or ShellState.fast_enter_exit.restore_pending == true
            or dependencies.is_on("vehicle_unlimited_rocket_boost")
            or VehicleLab.state.rocket_boost_applied == true
    end

    function public_api.FastTick(now, ped)
        if bound and started and not runtime_writes_suspended then
            process_retired_cleanup()
            if combat_setups then combat_setups.Tick() end
        end
        local result = fast_tick(now, ped)
        process_personal_vehicle_work(now)
        local manager = module_context and module_context.CScript and module_context.CScript.VehicleManager
        if manager and type(manager.FastTick) == "function" then manager.FastTick(now) end
        return result
    end

