    end

    function public_api.CombatTick(now)
        if not bound or runtime_writes_suspended then return end
        now = tonumber(now) or 0
        if now - VehicleMods.state.last_combat_tick_ms >= 25 then
            VehicleMods.state.last_combat_tick_ms = now
            VehicleMods.combat_tick(now)
        end
    end

