    end

    function public_api.PanicReset()
        if roof_turret then roof_turret.Cancel("Panic reset")end
        cancel_driver_weapons("panic reset")
        restore_vehicle_reticle()
        local result = panic_reset()
        local manager = module_context and module_context.CScript and module_context.CScript.VehicleManager
        if manager and type(manager.PanicReset) == "function" then manager.PanicReset() end
