    function public_api.OnSessionChange()
        if vehicle_fly then vehicle_fly.Cancel() end
        if damage_auto_repair then damage_auto_repair.Invalidate() end
        roof_turret_session=roof_turret_session+1
        if roof_turret then roof_turret.Invalidate("Session changed")end
        cancel_driver_weapons("session changed")
        suppression_generation=suppression_generation+1
        if not bound then return true end
        local timing_ok=VehicleLab.restore_cannon_timing("session changed")
        -- This event is observed after the connection boundary. Old tyre debt
        -- cannot authorize a write even if a new session recycles every alias.
        VehicleMods.driver_assistance.SessionChanged()
        VehicleMods.state.traction_owner=nil
        restore_fast_enter_exit()
        local mods_ok=VehicleMods.restore()
        VehicleMods.clear_projectile_safety()
        local lab_ok=VehicleLab.restore()
        restore_local_vehicle_presentation()
        local manager = module_context and module_context.CScript and module_context.CScript.VehicleManager
        if manager and type(manager.OnSessionChange) == "function" then manager.OnSessionChange() end
        ShellState.last_vehicle = 0
        ShellState.was_in_vehicle = false
        ShellState.doors_locked = false
        PersonalVehicleState.status = "PENDING"
        PersonalVehicleState.active_slot = -1
        PersonalVehicleState.active = nil
        PersonalVehicleState.audit = nil
        PersonalVehicleState.impound_fee = nil
        PersonalVehicleState.impound_fee_resolver = nil
        PersonalVehicleState.impound_fee_error = nil
        PersonalVehicleState.refreshed_at = 0
        PersonalVehicleState.audit_refreshed_at = 0
        PersonalVehicleState.last_error = nil
        PersonalVehicleState.pending_action = nil
        PersonalVehicleState.scanning = false
        PersonalVehicleState.scan_slot = 0
        PersonalVehicleState.scan_entries = nil
        PersonalVehicleState.scan_counts = nil
        PersonalVehicleState.scan_status = "IDLE"
        PersonalVehicleState.scan_started_ms = 0
        VehicleMods.state.controller.session_generation =
            (tonumber(VehicleMods.state.controller.session_generation) or 0) + 1
        VehicleMods.state.controller.force_refresh = true
        return timing_ok and lab_ok~=false and mods_ok~=false
    end

    function public_api.OnVehicleChange(old_vehicle, new_vehicle)
        if vehicle_fly then vehicle_fly.Cancel() end
        if damage_auto_repair then damage_auto_repair.Invalidate() end
        if roof_turret and old_vehicle~=new_vehicle then roof_turret.Invalidate("Vehicle changed")end
        cancel_driver_weapons("vehicle changed")
        if not bound then
            return true
        end

        if old_vehicle ~= nil
            and new_vehicle ~= nil
            and old_vehicle == new_vehicle then
            return true
        end
        local targets_ok=VehicleMods.restore_mounted_targets()
        local timing_ok=VehicleLab.restore_cannon_timing("vehicle changed")
        local balance_ok=VehicleLab.restore_cannon_balance('Vehicle changed')
        timing_ok=timing_ok and balance_ok
        if runtime_writes_suspended then return timing_ok and targets_ok end
        VehicleMods.restore_power("vehicle changed")
        VehicleMods.restore_jump()
        local traction_ok=VehicleMods.restore_traction()
        local builtin_ok = VehicleLab.quiesce_rapid_fire_builtin()
        local cannon_ok = VehicleLab.restore_native_cannon_profile()
        local weapon_ok = VehicleLab.restore_all_weapon_runtime()
        local ammo_ok = pcall(function()
            VehicleLab.restore_global_homing_buff()
            VehicleLab.restore_runtime_ammo_profiles()
            VehicleLab.restore_all_ammo_ranges()
        end)
        VehicleLab.state.ammo_runtime_signature = nil
        VehicleLab.state.native_cannon_profile_last_ms = -100000
        local refill_ok, refill_error =
            pcall(function()
                VehicleMods.restore_ammo()

                local vehicle =
                    tonumber(new_vehicle)

                if vehicle == nil then
                    vehicle =
                        dependencies.local_vehicle()
                end

                if dependencies.is_on(
                        "vehicle_infinite_ammo"
                    )
                    and dependencies.entity_exists(
                        vehicle
                    ) then
                    VehicleMods.state.ammo_active_vehicle =
                        vehicle

                    VehicleMods.state.last_ammo_refresh_ms =
                        runtime_now_ms()

                    VehicleMods.apply_infinite_ammo(
                        vehicle,
                        VehicleMods.state.last_ammo_refresh_ms
                    )
                end
            end)

        if not refill_ok
            and type(
                dependencies.log_error_once
            ) == "function" then
            dependencies.log_error_once(
                "vehicle_change_refill",
                refill_error
            )
        end
