local function require_binding(name, value)
    if value == nil then error("vehicle manager binding missing " .. name, 3) end
    return value
end

-- Never fill absent native fields with defaults: nil means unavailable/unknown.
local function clone_profile(value)
    if type(value) ~= "table" then return value end
    local result = {}
    for key, item in pairs(value) do result[key] = clone_profile(item) end
    return result
end
local function equal(a,b)
    if type(a) ~= type(b) then return false end
    if type(a) ~= "table" then
        if type(a)=="number" then return math.abs(a-b)<0.001 end
        return a==b
    end
    for k,v in pairs(a) do if not equal(v,b[k]) then return false end end
    for k in pairs(b) do if a[k]==nil then return false end end
    return true
end
local function finite_number(value)
    return type(value)=="number" and value==value and value~=math.huge and value~=-math.huge
end

local function create_manager(deps)
    local H = require_binding("H", deps.H)
    local invoke_void = require_binding("invoke_void", deps.invoke_void)
    local invoke_int = require_binding("invoke_int", deps.invoke_int)
