    local function alloc_int(index)
        if State.out_ptrs[index] and State.out_ptrs[index] ~= 0 then return State.out_ptrs[index] end
        if type(memory.AllocInt) ~= "function" then return 0 end
        local ok, value = pcall(memory.AllocInt)
        if not ok then return 0 end
        State.out_ptrs[index] = tonumber(value) or 0
        return State.out_ptrs[index]
    end

    -- Documented int* outputs only; sentinel catches unavailable/no-write returns.
    local function read_outputs(hash, vehicle, count)
        if not hash then return nil end
        local args, pointers = {vehicle}, {}
        for i=1,count do
            local ptr=alloc_int(i)
            if ptr==0 then return nil end
            local ok,result=pcall(memory.WriteInt,ptr,-2147483001)
            if not ok or result==false then return nil end
            args[#args+1]=ptr; pointers[i]=ptr
        end
        local ok,result=pcall(natives.InvokeVoid,hash,table.unpack(args))
        if not ok or result==false then return nil end
        local values={}
        for i,ptr in ipairs(pointers) do
            local read_ok,value=pcall(memory.ReadInt,ptr)
            if not read_ok or type(value)~="number" or value==-2147483001 then return nil end
            values[i]=value
        end
        return values
    end
    local function read_native(kind,hash,...)
        local method=natives["Invoke"..kind]
        if type(method)~="function" or not hash then return nil end
        local ok,value=pcall(method,hash,...)
        if not ok then return nil end
        if kind=="Bool" and type(value)~="boolean" then return nil end
        if (kind=="Int" or kind=="Float") and not finite_number(value) then return nil end
        if kind=="String" and type(value)~="string" then return nil end
        return value
    end
