        wheel_type={"Int","GET_VEHICLE_WHEEL_TYPE","SET_VEHICLE_WHEEL_TYPE",0,12},
        tint={"Int","GET_VEHICLE_WINDOW_TINT","SET_VEHICLE_WINDOW_TINT",-1,6},
