    local SIMPLE_KEYS={"primary","secondary","pearl","wheel_color","primary_custom","secondary_custom",
        "primary_rgb","secondary_rgb","neon_rgb","tyre_smoke_rgb","interior_color","dashboard_color","drift_tyres",
        "primary_finish","secondary_finish","roof_livery"}
    local MAP_KEYS={"mods","mod_variations","toggles","extras","neon_enabled"}
    local function validate_property(key,value,live_mod_count)
        local function integer(minimum,maximum)
            return finite_number(value) and value%1==0 and value>=minimum and value<=maximum
        end
        local spec=SCALARS[key]
        if spec then
            if spec[1]=="Bool" then return type(value)=="boolean" end
            if spec[1]=="String" then return type(value)=="string" and #value<=8 and not value:find("[%c]") end
            if not finite_number(value) or (spec[1]=="Int" and value%1~=0) then return false end
            if spec[4] and (value<spec[4] or value>spec[5]) then return false end
            if key=="livery" and ((State.livery_count or 0)<=0 or value>=State.livery_count) then return false end
            if key=="plate_index" and value>=(State.plate_count or 6) then return false end
            return true
        end
        if key=="primary" or key=="secondary" or key=="pearl" or key=="wheel_color"
            or key=="interior_color" or key=="dashboard_color" then return integer(0,PAINT_INDEX_MAX) end
        if key=="primary_custom" or key=="secondary_custom" or key=="drift_tyres" then return type(value)=="boolean" end
        if key=="primary_finish" or key=="secondary_finish" then return integer(0,6) end
        if key=="roof_livery" then return (State.roof_livery_count or 0)>0 and integer(-1,State.roof_livery_count-1) end
        if key=="primary_rgb" or key=="secondary_rgb" or key=="neon_rgb" or key=="tyre_smoke_rgb" then
            if type(value)~="table" then return false end
            local count=0
            for index,channel in pairs(value) do
                if type(index)~="number" or index%1~=0 or index<1 or index>3
                    or not finite_number(channel) or channel%1~=0 or channel<0 or channel>255 then return false end
                count=count+1
            end
            return count==3
        end
        local group,index=tostring(key):match("^([%w_]+):(%d+)$"); index=tonumber(index)
        if group=="mods" then
            return index<=49 and not TOGGLE_MODS[index] and integer(-1,(live_mod_count or State.mod_counts[index] or 0)-1)
        end
        if group=="mod_variations" then return (index==23 or index==24) and type(value)=="boolean" end
        if group=="toggles" then return TOGGLE_MODS[index]==true and type(value)=="boolean" end
        if group=="extras" then return index<=20 and type(value)=="boolean" end
        if group=="neon_enabled" then return index<=3 and type(value)=="boolean" end
        return false
    end
    local function native_property_value(key,value)
        local spec=SCALARS[key]
        if spec and spec[1]=="Float" then return value+0.0 end
        if type(value)=="number" then return math.floor(value) end
        if key=="primary_rgb" or key=="secondary_rgb" or key=="neon_rgb" or key=="tyre_smoke_rgb" then
            return {math.floor(value[1]),math.floor(value[2]),math.floor(value[3])}
        end
        return value
    end

    local function fields(profile)
        local result={}
        for key in pairs(SCALARS) do if profile and profile[key]~=nil then result[key]=clone_profile(profile[key]) end end
        for _,key in ipairs(SIMPLE_KEYS) do if profile and profile[key]~=nil then result[key]=clone_profile(profile[key]) end end
        for _,key in ipairs(MAP_KEYS) do
            for index,value in pairs(profile and profile[key] or {}) do result[key..":"..index]=clone_profile(value) end
        end
        return result
    end
    local function put_field(profile,key,value)
        local group,index=key:match("^([%w_]+):(%d+)$")
        if group then profile[group]=profile[group] or {}; profile[group][tonumber(index)]=clone_profile(value)
        else profile[key]=clone_profile(value) end
    end

    local function clean_field(value, maximum)
        return tostring(value or ""):gsub("[|\r\n]", " "):sub(1, maximum or 64)
    end

    local function timestamp_now()
        local ok_time, value = pcall(function() return os and os.time and os.time() or 0 end)
        value = ok_time and tonumber(value) or 0
        if value and value > 0 and os and type(os.date) == "function" then
            local ok_date, label = pcall(os.date, "%Y-%m-%d %H:%M", value)
            if ok_date and type(label) == "string" then return label end
        end
        return value and value > 0 and tostring(value) or "Unknown"
    end

    local function vehicle_model_name(model)
        model = tonumber(model) or 0
        if model == 0 then return "Vehicle" end
        local label = invoke_string(VEHICLE_INFO_HASHES.GET_DISPLAY_NAME_FROM_VEHICLE_MODEL, model)
        if label ~= "" and label ~= "NULL" then
            local localized = invoke_string(VEHICLE_INFO_HASHES.GET_FILENAME_FOR_AUDIO_CONVERSATION, label)
            if localized ~= "" and localized ~= "NULL" then return localized end
            return label:gsub("_", " ")
        end
        return "Vehicle"
    end


    -- IMANI46: supplied carmod_shop uses slot 44 only when its actual slot
    -- name is TOP_IMANI_TECH. GET_VEHICLE_MOD is zero based: 0 is Remote
    -- Control Unit, 1 is Missile Lock-On Jammer, and -1 removes the upgrade.
    -- This remains mods[44] in every captured/saved profile, never a new stat.
    local IMANI_CHOICES46={[-1]="None",[0]="Remote Control Unit",[1]="Missile Lock-On Jammer"}
    local function read_imani46(vehicle)
        if not entity_exists(vehicle)
            or read_native("String",N.imani_slot_name46,vehicle,44)~="TOP_IMANI_TECH" then return nil end
        local count=read_native("Int",H.GET_NUM_VEHICLE_MODS,vehicle,44)
        local installed=read_native("Int",H.GET_VEHICLE_MOD,vehicle,44)
        local allowed=read_native("Bool",N.imani_lockon46,vehicle)
        local supported=count==2 and installed~=nil and installed%1==0 and installed>=-1 and installed<=1
        return {supported=supported,count=count,installed=installed,allow_lockon=allowed,
            confirmed=supported and allowed~=nil and allowed==(installed~=1)}
    end
    local function imani_needs_sync46(vehicle,key,value)
        if key~="mods:44" or (value~=-1 and value~=0 and value~=1) then return false end
        local info=read_imani46(vehicle)
        return info~=nil and (not info.supported or info.allow_lockon~=(value~=1))
    end

