    local function studio_safety(active)
        -- Keep protection until every camera/preview cleanup attempt finishes.
        -- A hidden page must not expose the real ped behind a stuck studio cam.
        if not active and (State.preview_cam~=0 or State.preview_cleanup_pending) then
