            and ((State.mod_counts[23] or 0)>0 or (State.mod_counts[24] or 0)>0) then
            local families={0,1,2,3,4,5,7,8,9,10,11,12}
            State.current.wheel_type=families[math.random(1,#families)]
            refresh_preview();family_ok=apply_pending(true)
        end
        if not target_valid(State.target) then return false end
        for index=0,49 do
            if TOGGLE_MODS[index] then
                if State.toggle_presence[index] then State.current.toggles[index]=random_bool() end
            elseif State.current.mods[index]~=nil and (State.mod_counts[index] or 0)>0 then
                State.current.mods[index]=math.random(-1,State.mod_counts[index]-1)
            end
        end
        for _,group in ipairs({"mod_variations","extras","neon_enabled"}) do
            for index in pairs(State.current[group] or {}) do State.current[group][index]=random_bool() end
        end
        for _,key in ipairs({"primary","secondary","pearl","wheel_color","interior_color","dashboard_color"}) do
            set_number(key,0,PAINT_INDEX_MAX)
        end
        for _,side in ipairs({"primary","secondary"}) do
            set_number(side.."_finish",0,6)
            if State.current[side.."_custom"]~=nil then State.current[side.."_custom"]=random_bool() end
            -- An RGB setter also enables custom mode; never run it after a
            -- random indexed color unless that side chose custom RGB mode.
            if State.current[side.."_custom"] and State.current[side.."_rgb"] then
                State.current[side.."_rgb"]={math.random(0,255),math.random(0,255),math.random(0,255)}
            end
        end
        for _,key in ipairs({"neon_rgb","tyre_smoke_rgb"}) do
            if State.current[key] then State.current[key]={math.random(0,255),math.random(0,255),math.random(0,255)} end
        end
        if State.current.tyre_smoke_rgb and State.toggle_presence[20] and math.random(1,8)==1 then
