        if (State.roof_livery_count or 0)>0 then set_number("roof_livery",-1,State.roof_livery_count-1) end
        set_number("tint",0,6);set_number("plate_index",0,(State.plate_count or 6)-1);set_number("xenon_color",-1,12)
        set_number("dirt_level",0,15)
