                State.status="Confirmation expired: destination or vehicle changed"; return
            end
            persist_local(confirmation.action,confirmation.context,true); return
        end
        if action=="add_slot" or action=="save_slot" or action=="delete_slot" or action=="rename_slot" or action=="duplicate_slot" or action=="favorite_slot" then
            if action=="save_slot" and (context.generation~=State.generation or context.target_key~=(State.target and State.target.key)) then
                State.status="Save cancelled: vehicle changed"; return
            end
