    local function drain_camera_actions()
        -- Camera buttons are frame input, like orbit/zoom motion. Do not make
        -- each click wait for a separate maintenance tick. Keep saved actions
        -- on that lane and preserve FIFO order across both kinds of actions.
        while State.pending_actions[1] do
            local name=State.pending_actions[1].name
            local camera=name=="close" or name=="auto_on" or name=="auto_off"
                or name=="preview_reset" or name=="rotate_left" or name=="rotate_right"
                or name=="turn_around" or name=="zoom_in" or name=="zoom_out"
                or name:sub(1,5)=="view:"
