            attempt = tonumber(State.preview_attempt) or 0,
            last_stage = tostring(State.preview_last_stage or "idle"),
            frame_source = tostring(State.preview_frame_source or "class-safe-default"),
            viewport_width = tonumber(State.preview_viewport_width) or 1,
            viewport_fit_scale = tonumber(State.preview_viewport_fit_scale) or 1,
            effective_distance = tonumber(State.preview_effective_distance) or 0,
            vehicle = tonumber(State.preview_vehicle) or 0,
