end

function Module.BindCompatibility(bindings)
    if not module_context then error("vehicle manager must initialize before binding", 2) end
    if bound then return public_api end
    dependencies = bindings or {}
    public_api = create_manager(dependencies)
    module_context.CScript.VehicleManager = public_api
    if module_context.CScript.Vehicle then
        module_context.CScript.Vehicle.RenderManager = public_api.RenderManager
        module_context.CScript.Vehicle.StopManagerPreview = public_api.StopPreview
    end
    bound = true
    return public_api
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.CScript) ~= "table" or type(context.Modules) ~= "table" then
        error("modules.vehicle_manager received an invalid context")
    end
    module_context = context
    context.Modules.VehicleManager = Module
end

function Module.Start() started = true end
function Module.Stop() started = false end
function Module.Restore(context)
    if public_api and type(public_api.Release) == "function" then public_api.Release() end
    context = context or module_context
    if context and context.CScript then context.CScript.VehicleManager = nil end
    if context and context.Modules then context.Modules.VehicleManager = nil end
    module_context, public_api, dependencies = nil, nil, nil
    bound, started = false, false
end

return Module
