for _, metadata in pairs(WeaponMetadata) do
    for _, component in ipairs(metadata.components or {}) do
        local suffix = "##wc_" .. tostring(component.hash)
        component.ui_label_on = "[x] " .. component.name .. suffix
        component.ui_label_off = "[ ] " .. component.name .. suffix
    end
end

local function variant_counterpart_hash(weapon_hash)
    local key = weapon_hash_key(weapon_hash)
    return key and WEAPON_VARIANT_COUNTERPART[key] or nil
end

local function variant_family_key(weapon_hash)
    local key = weapon_hash_key(weapon_hash)
    local counterpart = variant_counterpart_hash(weapon_hash)
    local counterpart_key = weapon_hash_key(counterpart)
    if not key or not counterpart_key then return nil end
    if tonumber(key) < tonumber(counterpart_key) then return key .. ":" .. counterpart_key end
    return counterpart_key .. ":" .. key
end

local function capture_weapon_snapshot(ped, weapon_hash)
    weapon_hash = (tonumber(weapon_hash) or 0) & 0xFFFFFFFF
    if weapon_hash == 0 or not entity_exists(ped)
        or not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, weapon_hash, false) then
        return false
    end
    local ammo=Ammo.Total(ped,weapon_hash)
    if ammo==nil then return false end
    local snapshot = {
        hash = weapon_hash,
        ammo = ammo,
        tint = math.max(0, invoke_int(H.GET_PED_WEAPON_TINT_INDEX, ped, weapon_hash)),
        components = {},
    }
    for _, component in ipairs((WeaponMetadata[weapon_hash] or {}).components or {}) do
        if not component.default and invoke_bool(H.HAS_PED_GOT_WEAPON_COMPONENT, ped, weapon_hash, component.hash) then
            snapshot.components[#snapshot.components + 1] = component.hash
        end
    end
    return snapshot
end

local function restore_weapon_snapshot(ped, snapshot)
    if not entity_exists(ped) or type(snapshot) ~= "table" or not snapshot.hash then return false end
    invoke_void(H.GIVE_WEAPON_TO_PED, ped, snapshot.hash, math.max(1, snapshot.ammo or 250), false, false)
    invoke_void(H.SET_PED_WEAPON_TINT_INDEX, ped, snapshot.hash, math.max(0, snapshot.tint or 0))
    for _, component_hash in ipairs(snapshot.components or {}) do
        invoke_void(H.GIVE_WEAPON_COMPONENT_TO_PED, ped, snapshot.hash, component_hash)
    end
    set_weapon_ammo(ped,snapshot.hash,math.max(0,snapshot.ammo or 250))
    return invoke_bool(H.HAS_PED_GOT_WEAPON, ped, snapshot.hash, false)
end

local function ensure_variant_family_snapshot(ped, weapon_hash)
    local family_key = variant_family_key(weapon_hash)
    local counterpart = variant_counterpart_hash(weapon_hash)
    if not family_key or not counterpart or not entity_exists(ped) then return nil end
    local existing =
        State.variant_family_snapshots[
            family_key
        ]

    if existing
        and tonumber(existing.ped) == tonumber(ped) then

        return existing
    end

    -- Never reuse an inventory baseline captured from a previous ped.
    -- Respawns can replace the local CPed while staying in the same session.
    if existing then
        State.variant_family_snapshots[
            family_key
        ] = nil
    end
    local weapon_u32 = (tonumber(weapon_hash) or 0) & 0xFFFFFFFF
    local counterpart_u32 = counterpart & 0xFFFFFFFF
    local snapshot = {
        hashes = { weapon_u32, counterpart_u32 },
        snapshots = {},
        ped = ped,
        mutated = false,
        mutation_count = 0,
        mutation_reason = nil,
    }
    snapshot.snapshots[weapon_hash_key(weapon_u32)] = capture_weapon_snapshot(ped, weapon_u32)
    snapshot.snapshots[weapon_hash_key(counterpart_u32)] = capture_weapon_snapshot(ped, counterpart_u32)
    State.variant_family_snapshots[family_key] = snapshot
    return snapshot
end

local function mark_variant_family_mutated(family, ped, reason)
    if type(family) ~= "table" or tonumber(ped) == nil or tonumber(ped) == 0 then return end
    family.ped = ped
    family.mutated = true
    family.mutation_count = (tonumber(family.mutation_count) or 0) + 1
    family.mutation_reason = tostring(reason or "CScript variant operation")
end

local function enforce_variant_target(ped, weapon_hash, reason)
    local counterpart = variant_counterpart_hash(weapon_hash)
    if not counterpart or not entity_exists(ped) then return false, false end
    local family = ensure_variant_family_snapshot(ped, weapon_hash)
    local selected = invoke_int(H.GET_SELECTED_PED_WEAPON, ped) & 0xFFFFFFFF
    local selected_was_counterpart = weapon_hash_key(selected) == weapon_hash_key(counterpart)
    local changed = false

    if invoke_bool(H.HAS_PED_GOT_WEAPON, ped, counterpart, false) then
        mark_variant_family_mutated(family, ped, reason or "variant counterpart removal")
        invoke_void(REMOVE_WEAPON_FROM_PED_NATIVE, ped, counterpart)
        changed = true
    end

    local target_u32 = (tonumber(weapon_hash) or 0) & 0xFFFFFFFF
    if not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target_u32, false) and family then
        local original = family.snapshots[weapon_hash_key(target_u32)]
        if type(original) == "table" then
            mark_variant_family_mutated(family, ped, reason or "variant target restoration")
            changed = restore_weapon_snapshot(ped, original) or changed
        end
    end
    return changed, selected_was_counterpart
end

local function capture_variant_for_owned_change(ped, weapon_hash, reason)
    local family = ensure_variant_family_snapshot(ped, weapon_hash)
    if family then mark_variant_family_mutated(family, ped, reason or "CScript weapon mutation") end
    return family
end

local function restore_variant_families(ped)
    local restored = 0
    if tonumber(ped) and ped ~= 0 and entity_exists(ped) then
        for _, family in pairs(State.variant_family_snapshots or {}) do
            if family.mutated == true and tonumber(family.ped) == tonumber(ped) then
                local hashes_valid = true
                for _, hash in ipairs(family.hashes or {}) do
                    hash = tonumber(hash)
                    if not hash or hash == 0 then hashes_valid = false; break end
                end
                if hashes_valid then
            for _, hash in ipairs(family.hashes or {}) do
                if invoke_bool(H.HAS_PED_GOT_WEAPON, ped, hash, false) then
                    invoke_void(REMOVE_WEAPON_FROM_PED_NATIVE, ped, hash)
                end
            end
            for _, original in pairs(family.snapshots or {}) do
                if type(original) == "table" then restore_weapon_snapshot(ped, original) end
            end
                    restored = restored + 1
                end
            end
        end
    end
    State.variant_family_snapshots = {}
    State.session_variant_overrides = {}
    return restored
end

local function variant_override_suppresses(weapon_hash)
    local family_key = variant_family_key(weapon_hash)
    if not family_key then return false end
    local wanted = State.session_variant_overrides[family_key]
    return wanted ~= nil and weapon_hash_key(wanted) ~= weapon_hash_key(weapon_hash)
end

local function session_removed_suppresses(weapon_hash)
    local key = weapon_hash_key(weapon_hash)
    return key ~= nil and State.session_weapon_removed[key] == true
end

local LoadoutStore = { path = nil, legacy_path = nil, slots = {} }
for index = 1, 5 do
    LoadoutStore.slots[index] = { name = "Custom " .. tostring(index), hashes = {}, snapshots = {} }
end

local function sanitize_slot_name(value)
    value = tostring(value or ""):gsub("[|\r\n]", " "):gsub("^%s+", ""):gsub("%s+$", "")
    if value == "" then value = "Unnamed" end
    return value:sub(1, 40)
end

local function normalize_weapon_hashes(values)
    local result, seen = {}, {}
    local function add(value)
        local key = weapon_hash_key(value)
        if not key or not WEAPON_BY_HASH[key] or seen[key] then return end
        local counterpart = WEAPON_VARIANT_COUNTERPART[key]
        local counterpart_key = weapon_hash_key(counterpart)
        if counterpart_key and seen[counterpart_key] then
            for index = #result, 1, -1 do
                if weapon_hash_key(result[index]) == counterpart_key then
                    table.remove(result, index)
                    break
                end
            end
            seen[counterpart_key] = nil
        end
        result[#result + 1] = tonumber(key)
        seen[key] = true
    end
    if type(values) == "table" then
        for _, value in ipairs(values) do add(value) end
    else
        for token in tostring(values or ""):gmatch("[^,;\r\n]+") do
            local normalized = token:gsub("^%s+", ""):gsub("%s+$", ""):lower()
            if normalized:match("^weapon_[%w_]+$") or normalized:match("^gadget_[%w_]+$") then
                add(Utils.Joaat(normalized))
            else
                add(tonumber(normalized))
            end
        end
    end
    return result
end

local function hashes_to_csv(hashes)
    local values = {}
    for _, hash in ipairs(normalize_weapon_hashes(hashes)) do values[#values + 1] = tostring(hash) end
    return table.concat(values, ",")
end

-- V4 adds only known, validated, weapon-specific snapshots. Existing V3
-- hashes remain the authoritative weapon selection and load without changes.
-- On the first Save in V4, currently equipped weapons contribute tint, total
-- ammunition and installed attachment/special-ammo component hashes.
local LOADOUT_FORMAT = "CSCRIPT_LOADOUT_V4"
local function loadout_profile_copy(snapshot,weapon_hash)
    if type(snapshot)~="table" then return nil end
    local key=weapon_hash_key(weapon_hash)
    if not key or not WEAPON_BY_HASH[key] then return nil end
    local ammo=tonumber(snapshot.ammo)
    local tint=tonumber(snapshot.tint)
    if not ammo or ammo~=ammo or ammo<0 or ammo>99999 or ammo%1~=0
        or not tint or tint~=tint or tint<0 or tint>127 or tint%1~=0 then return nil end
    local allowed={}
    for _,entry in ipairs((WeaponMetadata[tonumber(key)] or {}).components or {}) do
        if not entry.default and type(entry.hash)=="number" then allowed[entry.hash]=true end
    end
    local components,seen={},{}
    for _,component in ipairs(snapshot.components or {}) do
        local n=tonumber(component)
        if n and n%1==0 and n>=0 and n<=4294967295 and allowed[n] and not seen[n] then
            seen[n]=true
            if #components<64 then components[#components+1]=n end
        end
    end
    table.sort(components)
    return {hash=tonumber(key),ammo=ammo,tint=tint,components=components}
end
local function encode_loadout_profiles(hashes,snapshots)
    local rows={}
    for _,hash in ipairs(normalize_weapon_hashes(hashes)) do
        local profile=loadout_profile_copy(type(snapshots)=="table" and
            snapshots[weapon_hash_key(hash)],hash)
        if profile then
            local component_tokens={}
            for _,component in ipairs(profile.components)do
                component_tokens[#component_tokens+1]=tostring(component)
            end
            rows[#rows+1]=table.concat({tostring(hash),tostring(profile.ammo),
                tostring(profile.tint),table.concat(component_tokens,",")},":")
        end
    end
    return table.concat(rows,";")
end
local function decode_loadout_profiles(serialized,hashes)
    local saved,allowed={},{}
    for _,hash in ipairs(normalize_weapon_hashes(hashes))do allowed[weapon_hash_key(hash)]=true end
    if type(serialized)~="string" or #serialized>32768 then return saved end
    for segment in serialized:gmatch("[^;]+")do
        local hash,ammo,tint,components=segment:match("^(%d+):(%d+):(%d+):([%d,]*)$")
        local key=weapon_hash_key(hash)
        if key and allowed[key] and not saved[key] then
            local parsed={}
            for token in (components or ""):gmatch("%d+")do parsed[#parsed+1]=tonumber(token) end
            local normalized=loadout_profile_copy({ammo=tonumber(ammo),tint=tonumber(tint),
                components=parsed},tonumber(key))
            if normalized then saved[key]=normalized end
        end
    end
    return saved
end

local function resolve_loadout_path()
    if LoadoutStore.path then return LoadoutStore.path end
    if not (FileMgr and type(FileMgr.GetMenuRootPath) == "function") then return nil end
    local ok, root = pcall(FileMgr.GetMenuRootPath)
    if not ok or type(root) ~= "string" or root == "" then return nil end
    local directory = root .. "\\Lua\\CScript"
    if type(FileMgr.CreateDir) == "function" then pcall(FileMgr.CreateDir, directory) end
    LoadoutStore.path = directory .. "\\loadouts.txt"
    -- Read-only source for one-time migration from pre-rebrand installations.
    LoadoutStore.legacy_path = root .. "\\Lua\\JinxScriptRebound\\loadouts.txt"
    return LoadoutStore.path
end

local function migrate_legacy_loadout_storage()
    local path = LoadoutStore.path
    local legacy_path = LoadoutStore.legacy_path
    if not path or not legacy_path or not (FileMgr
        and type(FileMgr.DoesFileExist) == "function"
        and type(FileMgr.ReadFileContent) == "function"
        and type(FileMgr.WriteFileContent) == "function") then return false end
    local new_ok, new_exists = pcall(FileMgr.DoesFileExist, path)
    if new_ok and new_exists then return false end
    local old_ok, old_exists = pcall(FileMgr.DoesFileExist, legacy_path)
    if not old_ok or not old_exists then return false end
    local read_ok, content = pcall(FileMgr.ReadFileContent, legacy_path)
    if not read_ok or type(content) ~= "string" or content == "" then return false end
    local write_ok, result = pcall(FileMgr.WriteFileContent, path, content, false)
    if write_ok and result ~= false then
        log_info("Migrated retired legacy loadout storage to CScript.")
        return true
    end
    return false
end

local function save_loadout_store()
    local path = resolve_loadout_path()
    if not path or not (FileMgr and type(FileMgr.WriteFileContent) == "function") then
        return false, "File persistence is unavailable"
    end
    local lines = { LOADOUT_FORMAT }
    for index = 1, 5 do
        local slot = LoadoutStore.slots[index]
        lines[#lines + 1] = table.concat({
            tostring(index), sanitize_slot_name(slot.name), hashes_to_csv(slot.hashes),
            encode_loadout_profiles(slot.hashes,slot.snapshots),
        }, "|")
    end
    local ok, result = pcall(FileMgr.WriteFileContent, path, table.concat(lines, "\n"), false)
    return ok and result ~= false, ok and nil or tostring(result)
end

local function load_loadout_store()
    local path = resolve_loadout_path()
    if not path or not (FileMgr and type(FileMgr.DoesFileExist) == "function") then return false end
    migrate_legacy_loadout_storage()
    local exists_ok, exists = pcall(FileMgr.DoesFileExist, path)
    if not exists_ok or not exists or type(FileMgr.ReadFileContent) ~= "function" then return false end
    local read_ok, content = pcall(FileMgr.ReadFileContent, path)
    if not read_ok or type(content) ~= "string" then return false end
    local is_v4 = content:find(LOADOUT_FORMAT, 1, true) ~= nil
    local is_v3 = content:find("CSCRIPT_LOADOUT_V3", 1, true) ~= nil
    local is_v2 = content:find("JINX_LOADOUT_V2", 1, true) ~= nil
    local is_v1 = content:find("JINX_LOADOUT_V1", 1, true) ~= nil
    if not is_v4 and not is_v3 and not is_v2 and not is_v1 then return false end
    for line in content:gmatch("[^\r\n]+") do
        local index, name, weapons, profiles
        if is_v4 then index, name, weapons, profiles = line:match("^(%d+)|([^|]*)|([^|]*)|(.*)$")
        elseif is_v3 or is_v2 then index, name, weapons = line:match("^(%d+)|([^|]*)|([^|]*)$")
        else index, name, weapons = line:match("^(%d+)|([^|]*)|([^|]*)|%d+$") end
        index = tonumber(index)
        if index and index >= 1 and index <= 5 then
            local hashes=normalize_weapon_hashes(weapons)
            LoadoutStore.slots[index] = {
                name = sanitize_slot_name(name),
                hashes = hashes,
                snapshots = is_v4 and decode_loadout_profiles(profiles,hashes) or {},
            }
        end
    end
    return true
end

load_loadout_store()

local function selected_loadout_slot()
    return math.max(1, math.min(5, list_index("loadout_slot") + 1))
end

local function sync_loadout_picker()
    local selected_index = selected_loadout_slot()
    local slot = LoadoutStore.slots[selected_index]
    if not slot then return end
    if F.loadout_slot and type(F.loadout_slot.SetList) == "function" then
        local labels = {}
        for index=1,5 do
            local entry=LoadoutStore.slots[index]
            labels[index]=("%d. %s"):format(index, sanitize_slot_name(entry and entry.name or ("Custom "..index)))
        end
        pcall(function() F.loadout_slot:SetList(labels):SetListIndex(selected_index-1) end)
    end
    if F.loadout_name then pcall(function() F.loadout_name:SetStringValue(slot.name) end) end
    local selected = {}
    for _, hash in ipairs(slot.hashes or {}) do selected[weapon_hash_key(hash)] = true end
    for _, category in ipairs(WEAPON_CATEGORIES) do
        for _, weapon in ipairs(category.weapons) do
            if F[weapon.key] then
                set_toggle(weapon.key, selected[weapon_hash_key(weapon.hash)] == true)
            end
        end
    end
end

local function selected_picker_hashes()
    local hashes = {}
    for _, category in ipairs(WEAPON_CATEGORIES) do
        for _, weapon in ipairs(category.weapons) do
            if is_on(weapon.key) then hashes[#hashes + 1] = weapon.hash end
        end
    end
    return normalize_weapon_hashes(hashes)
end

local function give_or_refresh_weapon(ped, hash, ammo)
    local _, select_target = enforce_variant_target(ped, hash)
    if invoke_bool(H.HAS_PED_GOT_WEAPON, ped, hash, false) then
        set_weapon_ammo(ped, hash, ammo)
        if select_target then invoke_void(H.SET_CURRENT_PED_WEAPON, ped, hash, true) end
        return false
    end
    capture_variant_for_owned_change(ped, hash, "weapon added by CScript")
    invoke_void(H.GIVE_WEAPON_TO_PED, ped, hash, ammo, false, false)
    set_weapon_ammo(ped, hash, ammo)
    if select_target then invoke_void(H.SET_CURRENT_PED_WEAPON, ped, hash, true) end
    return true
end

local function missing_weapon_hashes(ped, hashes)
    local missing = {}
    if not entity_exists(ped) then return missing end
    for _, hash in ipairs(hashes or {}) do
        if not session_removed_suppresses(hash)
            and not variant_override_suppresses(hash)
            and not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, hash, false) then
            missing[#missing + 1] = hash
        end
    end
    return missing
end

local function schedule_loadout_verification(now, delay)
    State.loadout_verify_due = math.max(State.loadout_verify_due or 0, now + (delay or 350))
    State.loadout_verify_attempts = 0
end

local function capture_loadout_profiles(ped,hashes,previous)
    local result={}
    for _,hash in ipairs(normalize_weapon_hashes(hashes)) do
        local key=weapon_hash_key(hash)
        -- An unequipped/unowned weapon must not erase an earlier saved
        -- customization when the user updates only the loadout selection.
        local captured=entity_exists(ped) and capture_weapon_snapshot(ped,hash)
        local profile=loadout_profile_copy(captured or (previous and previous[key]),hash)
        if profile then result[key]=profile end
    end
    return result
end

-- Restore only known compatible weapon components. The ammo-slot components
-- include Mk II special rounds, and are installed BEFORE final total ammo.
-- State's existing component/tint maintenance handles GTA post-respawn rebuild.
local function apply_loadout_profile(ped,hash,snapshot)
    local profile=loadout_profile_copy(snapshot,hash)
    if not profile or not invoke_bool(H.HAS_PED_GOT_WEAPON,ped,hash,false) then return false end
    local key=weapon_hash_key(hash)
    local wanted={}
    for _,component in ipairs(profile.components)do wanted[component]=true end
    local groups={}
    for _,component in ipairs((WeaponMetadata[hash] or {}).components or {})do
        if type(component.slot)=="string" and component.slot~="" then
            local group=groups[component.slot]
            if not group then group={items={}};groups[component.slot]=group end
            group.items[#group.items+1]=component
            if not component.default and wanted[component.hash] then group.wanted=component end
        end
    end
    for slot,group in pairs(groups)do
        local selected=group.wanted
        if selected and not invoke_bool(H.DOES_WEAPON_TAKE_WEAPON_COMPONENT,hash,selected.hash) then
            selected=nil -- Unsupported build: don't keep reasserting it forever.
        end
        State.session_component_targets[key..":"..slot]={
            weapon_hash=hash,slot=slot,component=selected,
            source_component=selected or group.items[1],desired=selected~=nil,
        }
        for _,component in ipairs(group.items)do
            if not component.default and (not selected or selected.hash~=component.hash)
                and invoke_bool(H.HAS_PED_GOT_WEAPON_COMPONENT,ped,hash,component.hash)then
                invoke_void(H.REMOVE_WEAPON_COMPONENT_FROM_PED,ped,hash,component.hash)
            end
        end
        if selected and not invoke_bool(H.HAS_PED_GOT_WEAPON_COMPONENT,ped,hash,selected.hash)then
            invoke_void(H.GIVE_WEAPON_COMPONENT_TO_PED,ped,hash,selected.hash)
        end
    end
    local tint_count=math.max(0,invoke_int(H.GET_WEAPON_TINT_COUNT,hash))
    if tint_count>0 then
        local desired=profile.tint%tint_count
        State.session_tint_targets[key]={weapon_hash=hash,tint=desired}
        if invoke_int(H.GET_PED_WEAPON_TINT_INDEX,ped,hash)~=desired then
            invoke_void(H.SET_PED_WEAPON_TINT_INDEX,ped,hash,desired)
        end
    end
    return true
end

local function apply_custom_loadout(slot_index, silent, options)
    options = options or {}
    local ped = local_ped()
    local index = slot_index or selected_loadout_slot()
    local slot = LoadoutStore.slots[index]
    if not entity_exists(ped) or not slot then
        if not silent then toast("Loadout or local ped is unavailable.") end
        return false
    end

    local hashes = normalize_weapon_hashes(slot.hashes)
    if options.maintenance ~= true then
        -- A newly applied loadout becomes the weapon-set authority. Old picker
        -- additions must not keep an incompatible Mk counterpart alive forever.
        State.session_weapon_keep = {}
        State.session_weapon_removed = {}
        State.session_variant_overrides = {}
        for _, hash in ipairs(hashes) do ensure_variant_family_snapshot(ped, hash) end
    end

    -- REMOVE_ALL_PED_WEAPONS is only appropriate for the explicit Apply button.
    -- Respawn/verification maintenance is additive so GTA's inventory rebuild
    -- cannot be repeatedly torn down while the new ped is settling.
    if is_on("replace_weapons") and options.maintenance ~= true then
        invoke_void(H.REMOVE_ALL_PED_WEAPONS, ped, true)
    end

    local max_ammo=is_on("max_custom_loadout_ammo")
    local given, refreshed = 0, 0
    -- Old per-slot targets must not revive a different selected loadout.
    local included={}
    for _,hash in ipairs(hashes)do included[weapon_hash_key(hash)]=true end
    for key,target in pairs(State.session_component_targets or {})do
        if included[weapon_hash_key(target.weapon_hash)] then State.session_component_targets[key]=nil end
    end
    for key in pairs(included)do State.session_tint_targets[key]=nil end
    for _, hash in ipairs(hashes) do
        if options.maintenance ~= true or not session_removed_suppresses(hash) then
            local profile=loadout_profile_copy(slot.snapshots and slot.snapshots[weapon_hash_key(hash)],hash)
            local ammo=max_ammo and 9999 or (profile and profile.ammo or 250)
            if give_or_refresh_weapon(ped, hash, ammo) then given = given + 1
            else refreshed = refreshed + 1 end
            if profile and invoke_bool(H.HAS_PED_GOT_WEAPON,ped,hash,false) then
                apply_loadout_profile(ped,hash,profile)
                -- Special ammo/clip component changes may reset reserve ammo.
                -- Set the exact stored total AFTER restoring components.
                set_weapon_ammo(ped, hash, ammo)
            end
        end
    end

    State.custom_loadout_ped = ped
    if options.maintenance ~= true then
        State.active_custom_loadout_slot = index
        end
    schedule_loadout_verification(now_ms(), options.maintenance and 450 or 300)

    if not silent then
        toast(("Applied '%s': %d added, %d refreshed."):format(slot.name, given, refreshed), 5000)
    end
    log_info(("Applied custom loadout slot %d '%s' (%d selected, %d added%s)."):format(
        index, slot.name, #hashes, given, options.maintenance and ", maintenance" or ""
    ))
    return true
end

local WeaponCustomizer = {
    selected_hash = WEAPON_CATEGORIES[1].weapons[1].hash,
    valid_components = {},
    installed = {},
    has_weapon = false,
    is_equipped = false,
    tint_count = 0,
    tint_index = 0,
    dirty = true,
    last_sample_ms = -100000,
    last_visible_ms = -100000,
    pending_components = {},
    last_component_click_ms = {},
}

local function queue_native_job(subsystem, callback)
    -- Do not enqueue native mutations while the Weapons domain is suspended.
    -- Desired UI/session state may still be preserved and reconciled later.
    if State.runtime_writes_suspended == true then
        return false
    end

    local generation =
        tonumber(State.job_generation) or 0

    local function run_callback()
        if not started
            or not bound
            or State.runtime_writes_suspended == true
            or generation ~= (tonumber(State.job_generation) or 0) then

            return
        end

        local ok, err =
            pcall(callback)

        if not ok then
            log_error_once(
                "job_run_" .. tostring(subsystem),
                err
            )
        end
    end

    if Script
        and type(Script.QueueJob) == "function" then

        local ok, err =
            pcall(
                Script.QueueJob,
                function()
                    run_callback()
                end
            )

        if not ok then
            log_error_once(
                "job_queue_" .. tostring(subsystem),
                err
            )
        end

        return ok
    end

    run_callback()
    return true
end

local function native_yield(ms)
    if Script and type(Script.Yield) == "function" then
        pcall(Script.Yield, math.max(0, math.floor(tonumber(ms) or 0)))
    end
end

local function select_weapon_for_customization(hash)
    hash = tonumber(hash) and (tonumber(hash) & 0xFFFFFFFF) or 0
    if hash == 0 or WeaponCustomizer.selected_hash == hash then return end
    WeaponCustomizer.selected_hash = hash
    WeaponCustomizer.valid_components = {}
    WeaponCustomizer.installed = {}
    WeaponCustomizer.has_weapon = false
    WeaponCustomizer.is_equipped = false
    WeaponCustomizer.dirty = true
end

local function component_request_key(weapon_hash, component_hash)
    return tostring(weapon_hash_key(weapon_hash) or 0) .. ":" .. tostring(tonumber(component_hash) or 0)
end

local function component_target_key(weapon_hash, slot)
    return tostring(weapon_hash_key(weapon_hash) or 0) .. ":" .. tostring(slot or "unknown")
end

local function weapon_display_name(weapon_hash)
    local weapon = WEAPON_BY_HASH[weapon_hash_key(weapon_hash)]
    return weapon and weapon[1] or ("0x%08X"):format((tonumber(weapon_hash) or 0) & 0xFFFFFFFF)
end

local function component_slot_items(weapon_hash, slot)
    local metadata = WeaponMetadata[weapon_hash] or {}
    local result = {}
    for _, item in ipairs(metadata.components or {}) do
        if item.slot == slot then result[#result + 1] = item end
    end
    return result
end

local function component_actual_state(ped, weapon_hash, component)
    if not entity_exists(ped) or not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, weapon_hash, false) then
        return false
    end
    if component.default then
        for _, other in ipairs(component_slot_items(weapon_hash, component.slot)) do
            if not other.default and invoke_bool(H.HAS_PED_GOT_WEAPON_COMPONENT, ped, weapon_hash, other.hash) then
                return false
            end
        end
        return true
    end
    return invoke_bool(H.HAS_PED_GOT_WEAPON_COMPONENT, ped, weapon_hash, component.hash)
end

local function remember_session_weapon(weapon_hash)
    local key = weapon_hash_key(weapon_hash)
    if not key then return end
    weapon_hash = weapon_hash & 0xFFFFFFFF
    State.session_weapon_removed[key] = nil
    local counterpart = variant_counterpart_hash(weapon_hash)
    local counterpart_key = weapon_hash_key(counterpart)
    if counterpart_key then
        State.session_weapon_keep[counterpart_key] = nil
        local family_key = variant_family_key(weapon_hash)
        if family_key then State.session_variant_overrides[family_key] = weapon_hash end
    end
    State.session_weapon_keep[key] = weapon_hash
end

local function remember_tint_target(weapon_hash, tint_index)
    local key = weapon_hash_key(weapon_hash)
    if not key then return end
    State.session_tint_targets[key] = {
        weapon_hash = weapon_hash & 0xFFFFFFFF,
        tint = math.max(0, math.floor(tonumber(tint_index) or 0)),
    }
end


local function remember_component_target(weapon_hash, component, desired)
    if not component or not component.slot then return end
    local key = component_target_key(weapon_hash, component.slot)
    State.session_component_targets[key] = {
        weapon_hash = weapon_hash & 0xFFFFFFFF,
        slot = component.slot,
        component = desired and component or nil,
        source_component = component,
        desired = desired == true,
    }
end

local function apply_component_request_once(ped, request, settle_ms)
    local weapon_hash, component = request.weapon_hash, request.component
    if not entity_exists(ped) or not weapon_hash or weapon_hash == 0 or not component then
        return false, "invalid-request"
    end
    if not invoke_bool(H.DOES_WEAPON_TAKE_WEAPON_COMPONENT, weapon_hash, component.hash) then
        return false, "unsupported"
    end

    capture_variant_for_owned_change(ped, weapon_hash, "weapon component")
    local _, select_target = enforce_variant_target(ped, weapon_hash)
    if not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, weapon_hash, false) then
        invoke_void(H.GIVE_WEAPON_TO_PED, ped, weapon_hash, 250, false, false)
        set_weapon_ammo(ped, weapon_hash, 250)
        native_yield(0)
    end
    if select_target then invoke_void(H.SET_CURRENT_PED_WEAPON, ped, weapon_hash, true) end

    if request.desired then
        for _, other in ipairs(component_slot_items(weapon_hash, component.slot)) do
            if other.hash ~= component.hash and not other.default then
                invoke_void(H.REMOVE_WEAPON_COMPONENT_FROM_PED, ped, weapon_hash, other.hash)
            end
        end
        if not component.default then
            invoke_void(H.GIVE_WEAPON_COMPONENT_TO_PED, ped, weapon_hash, component.hash)
        end
    elseif not component.default then
        invoke_void(H.REMOVE_WEAPON_COMPONENT_FROM_PED, ped, weapon_hash, component.hash)
    end

    settle_ms = math.max(0, math.floor(tonumber(settle_ms) or 0))
    if settle_ms > 0 then native_yield(settle_ms) end
    local verified=component_actual_state(ped,weapon_hash,component)==request.desired
    if verified and component.slot=="ammo" then
        local requested=(is_on("max_ammo") or is_on("max_custom_loadout_ammo")) and 9999 or 250
        set_weapon_ammo(ped,weapon_hash,requested)
    end
    return verified,"verified"
end

local function apply_component_request(ped, request, max_attempts, settle_ms)
    max_attempts = math.max(1, math.min(4, tonumber(max_attempts) or 1))
    local last_reason = "not-attempted"
    for attempt = 1, max_attempts do
        local success, reason = apply_component_request_once(ped, request, settle_ms)
        request.attempts = (request.attempts or 0) + 1
        last_reason = reason or last_reason
        if success then return true, last_reason end
        if reason == "unsupported" or reason == "invalid-request" then break end
        if attempt < max_attempts then native_yield(50) end
    end
    return false, last_reason
end

local function component_target_is_satisfied(ped, target)
    if not entity_exists(ped) or not target or not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target.weapon_hash, false) then
        return false
    end
    if target.component then
        return component_actual_state(ped, target.weapon_hash, target.component)
    end
    for _, other in ipairs(component_slot_items(target.weapon_hash, target.slot)) do
        if not other.default and invoke_bool(H.HAS_PED_GOT_WEAPON_COMPONENT, ped, target.weapon_hash, other.hash) then
            return false
        end
    end
    return true
end

local function apply_component_target_once(ped, target)
    if not target then return false end
    if target.component then
        local request = {
            weapon_hash = target.weapon_hash,
            component = target.component,
            desired = true,
            attempts = 0,
        }
        return apply_component_request(ped, request, 1, 0)
    end

    if not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target.weapon_hash, false) then
        return false
    end
    for _, other in ipairs(component_slot_items(target.weapon_hash, target.slot)) do
        if not other.default then
            invoke_void(H.REMOVE_WEAPON_COMPONENT_FROM_PED, ped, target.weapon_hash, other.hash)
        end
    end
    return component_target_is_satisfied(ped, target)
end

local function process_pending_weapon_components(now, ped)
    local state = WeaponCustomizer
    for key, request in pairs(state.pending_components) do
        if now >= (request.next_retry_ms or 0) then
            -- fast_tick already runs in Cherax's native script loop. Keep this
            -- path bounded; the click path does the longer Script.QueueJob retry.
            local success, reason = apply_component_request(ped, request, 1, 0)
            if success then
                state.pending_components[key] = nil
                if state.selected_hash == request.weapon_hash then
                    state.installed[request.component.hash] = request.desired
                    state.dirty = true
                end
            elseif request.attempts >= 4 or now >= (request.expires_ms or now) or reason == "unsupported" then
                state.pending_components[key] = nil
                state.dirty = true
                log_warn(("Weapon component failed: weapon=%s (0x%08X) component='%s' 0x%08X desired=%s reason=%s attempts=%d."):format(
                    weapon_display_name(request.weapon_hash),
                    request.weapon_hash & 0xFFFFFFFF,
                    tostring(request.component.name or "Unknown"),
                    (tonumber(request.component.hash) or 0) & 0xFFFFFFFF,
                    tostring(request.desired),
                    tostring(reason),
                    request.attempts or 0
                ))
            else
                request.next_retry_ms = now + 200
            end
        end
    end
end

local function refresh_weapon_customizer(now, force)
    local state = WeaponCustomizer
    if force ~= true and now - state.last_visible_ms > 650 then return end
    if force ~= true and not state.dirty and now - state.last_sample_ms < 250 then return end
    state.last_sample_ms = now
    state.dirty = false
    local ped, weapon_hash = local_ped(), state.selected_hash
    if not entity_exists(ped) or not weapon_hash or weapon_hash == 0 then return end

    local metadata = WeaponMetadata[weapon_hash] or { components = {}, tints = true }
    if #state.valid_components == 0 then
        local valid = {}
        for _, component in ipairs(metadata.components or {}) do
            if invoke_bool(H.DOES_WEAPON_TAKE_WEAPON_COMPONENT, weapon_hash, component.hash) then
                valid[#valid + 1] = component
            end
        end
        local order = { attachment = 1, finish = 2, ammo = 3 }
        table.sort(valid, function(a, b)
            local ga, gb = order[a.group] or 9, order[b.group] or 9
            if ga ~= gb then return ga < gb end
            return tostring(a.name) < tostring(b.name)
        end)
        state.valid_components = valid
    end

    state.has_weapon = invoke_bool(H.HAS_PED_GOT_WEAPON, ped, weapon_hash, false)
    state.is_equipped = weapon_hash_key(invoke_int(H.GET_SELECTED_PED_WEAPON, ped)) == weapon_hash_key(weapon_hash)
    local installed, slot_has_alternative = {}, {}
    if state.has_weapon then
        for _, component in ipairs(state.valid_components) do
            if not component.default then
                local active = invoke_bool(H.HAS_PED_GOT_WEAPON_COMPONENT, ped, weapon_hash, component.hash)
                installed[component.hash] = active
                if active then slot_has_alternative[component.slot] = true end
            end
        end
        for _, component in ipairs(state.valid_components) do
            if component.default then
                installed[component.hash] = slot_has_alternative[component.slot] ~= true
            end
        end
        state.tint_count = math.max(0, invoke_int(H.GET_WEAPON_TINT_COUNT, weapon_hash))
        state.tint_index = math.max(0, invoke_int(H.GET_PED_WEAPON_TINT_INDEX, ped, weapon_hash))
    else
        state.tint_count, state.tint_index = 0, 0
    end

    -- Keep the control stable while the script-thread request is settling.
    for _, request in pairs(state.pending_components) do
        if request.weapon_hash == weapon_hash then
            installed[request.component.hash] = request.desired
            if request.desired then
                for _, other in ipairs(state.valid_components) do
                    if other.slot == request.component.slot and other.hash ~= request.component.hash then
                        installed[other.hash] = false
                    end
                end
            end
        end
    end

    -- The chosen virtual configuration is the UI authority. GTA Online can
    -- transiently rebuild the ped inventory; that should not flip the button
    -- back while the maintenance layer is about to restore the selection.
    for _, target in pairs(State.session_component_targets or {}) do
        if target.weapon_hash == weapon_hash then
            for _, other in ipairs(state.valid_components) do
                if other.slot == target.slot then
                    if target.component then
                        installed[other.hash] = other.hash == target.component.hash
                    else
                        installed[other.hash] = other.default == true
                    end
                end
            end
        end
    end
    local tint_target = State.session_tint_targets[weapon_hash_key(weapon_hash)]
    if tint_target and state.tint_count > 0 then
        state.tint_index = tint_target.tint % state.tint_count
    end
    state.installed = installed
end

local function set_weapon_component(component)
    local weapon_hash = WeaponCustomizer.selected_hash
    if not component or not weapon_hash or weapon_hash == 0 then return end

    local now = now_ms()
    local slot_click_key = component_target_key(weapon_hash, component.slot)
    if now - (WeaponCustomizer.last_component_click_ms[slot_click_key] or -100000) < 350 then
        return
    end
    WeaponCustomizer.last_component_click_ms[slot_click_key] = now

    local exact_key = component_request_key(weapon_hash, component.hash)
    local exact_pending = WeaponCustomizer.pending_components[exact_key]
    if exact_pending and now < (exact_pending.expires_ms or now) then return end
    for pending_key, pending in pairs(WeaponCustomizer.pending_components) do
        if pending.weapon_hash == weapon_hash and pending.component
            and pending.component.slot == component.slot then
            WeaponCustomizer.pending_components[pending_key] = nil
        end
    end

    local currently_active = WeaponCustomizer.installed[component.hash] == true
    if component.default and currently_active then return end
    local desired = not currently_active
    local key = exact_key
    local request = {
        weapon_hash = weapon_hash & 0xFFFFFFFF,
        component = component,
        desired = desired,
        attempts = 0,
        next_retry_ms = now + 350,
        expires_ms = now + 3500,
    }

    remember_session_weapon(weapon_hash)
    remember_component_target(weapon_hash, component, desired)
    WeaponCustomizer.pending_components[key] = request
    WeaponCustomizer.installed[component.hash] = desired
    WeaponCustomizer.dirty = true
    log_info(("Weapon component click: weapon=%s component='%s' desired=%s."):format(
        weapon_display_name(weapon_hash), tostring(component.name or "Unknown"), tostring(desired)))

    queue_native_job("weapon_component", function()
        local ped = local_ped()
        if not entity_exists(ped) then
            request.next_retry_ms = now_ms() + 250
            return
        end
        local current = WeaponCustomizer.pending_components[key]
        if current ~= request then return end

        local success, reason = apply_component_request(ped, request, 3, 25)
        if success then
            WeaponCustomizer.pending_components[key] = nil
            WeaponCustomizer.installed[component.hash] = desired
            log_info(("Weapon component applied: weapon=%s component='%s' desired=%s attempts=%d."):format(
                weapon_display_name(weapon_hash), tostring(component.name or "Unknown"),
                tostring(desired), request.attempts or 0))
        else
            request.next_retry_ms = now_ms() + 250
            log_warn(("Weapon component queued for retry: weapon=%s component='%s' desired=%s reason=%s attempts=%d."):format(
                weapon_display_name(weapon_hash), tostring(component.name or "Unknown"),
                tostring(desired), tostring(reason), request.attempts or 0))
        end
        WeaponCustomizer.dirty = true
    end)
end

local function set_weapon_tint(delta)
    local weapon_hash = WeaponCustomizer.selected_hash
    if not weapon_hash or weapon_hash == 0 then return end
    local ped = local_ped()
    if not entity_exists(ped) then return end
    remember_session_weapon(weapon_hash)
    capture_variant_for_owned_change(ped, weapon_hash, "weapon tint")

    local count = math.max(0, invoke_int(H.GET_WEAPON_TINT_COUNT, weapon_hash))
    if count <= 0 then return end
    local key = weapon_hash_key(weapon_hash)
    local existing = State.session_tint_targets[key]
    local base = existing and existing.tint or math.max(0, invoke_int(H.GET_PED_WEAPON_TINT_INDEX, ped, weapon_hash))
    local desired = (base + (tonumber(delta) or 0)) % count
    remember_tint_target(weapon_hash, desired)
    WeaponCustomizer.tint_index = desired
    WeaponCustomizer.dirty = true

    queue_native_job("weapon_tint", function()
        local live_ped = local_ped()
        if not entity_exists(live_ped) then return end
        local _, select_target = enforce_variant_target(live_ped, weapon_hash)
        if not invoke_bool(H.HAS_PED_GOT_WEAPON, live_ped, weapon_hash, false) then
            invoke_void(H.GIVE_WEAPON_TO_PED, live_ped, weapon_hash, 250, false, false)
            set_weapon_ammo(live_ped, weapon_hash, 250)
        end
        if select_target then invoke_void(H.SET_CURRENT_PED_WEAPON, live_ped, weapon_hash, true) end
        local applied = false
        for attempt = 1, 3 do
            invoke_void(H.SET_PED_WEAPON_TINT_INDEX, live_ped, weapon_hash, desired)
            native_yield(25)
            if invoke_int(H.GET_PED_WEAPON_TINT_INDEX, live_ped, weapon_hash) == desired then
                applied = true
                break
            end
            if attempt < 3 then native_yield(50) end
        end
        if applied then
            log_info(("Weapon tint applied: weapon=%s tint=%d."):format(weapon_display_name(weapon_hash), desired))
        else
            log_warn(("Weapon tint drifted after apply: weapon=%s tint=%d; maintenance will retry."):format(
                weapon_display_name(weapon_hash), desired))
        end
        WeaponCustomizer.dirty = true
    end)
end

local function arm_picker_equip(ped, weapon_hash, force_ms)
    if not entity_exists(ped) or not weapon_hash or weapon_hash == 0 then return end
    local now = now_ms()
    State.picker_equip_hash = weapon_hash & 0xFFFFFFFF
    State.picker_equip_ped = ped
    State.picker_equip_started_ms = now
    State.picker_equip_force_until = now + math.max(0, math.floor(tonumber(force_ms) or 0))
end

local function clear_picker_equip()
    State.picker_equip_hash = 0
    State.picker_equip_ped = 0
    State.picker_equip_started_ms = 0
    State.picker_equip_force_until = 0
end

local function equip_picker_weapon(weapon_hash, refresh_ammo)
    if not weapon_hash or weapon_hash == 0 then return end
    remember_session_weapon(weapon_hash)
    queue_native_job("weapon_equip", function()
        local ped = local_ped()
        if not entity_exists(ped) then return end
        capture_variant_for_owned_change(ped, weapon_hash, "weapon picker equip")
        local _, swapped_from_counterpart = enforce_variant_target(ped, weapon_hash)
        if not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, weapon_hash, false) then
            invoke_void(H.GIVE_WEAPON_TO_PED, ped, weapon_hash, 250, false, false)
        end
        if refresh_ammo == true then set_weapon_ammo(ped, weapon_hash, 250) end
        native_yield(0)
        invoke_void(H.SET_CURRENT_PED_WEAPON, ped, weapon_hash, true)
        local force_ms = swapped_from_counterpart and 6000 or (variant_counterpart_hash(weapon_hash) and 3500 or 0)
        arm_picker_equip(ped, weapon_hash, force_ms)
        WeaponCustomizer.has_weapon = true
        WeaponCustomizer.is_equipped = true
        WeaponCustomizer.dirty = true
        log_info(("Session weapon equipped: %s (0x%08X)."):format(
            weapon_display_name(weapon_hash), weapon_hash & 0xFFFFFFFF))
    end)
end

local function equip_selected_weapon()
    equip_picker_weapon(WeaponCustomizer.selected_hash, false)
end

local function give_selected_weapon()
    local weapon_hash = WeaponCustomizer.selected_hash
    if not weapon_hash or weapon_hash == 0 then return end
    equip_picker_weapon(weapon_hash, true)
end

local function remove_selected_weapon()
    local weapon_hash = WeaponCustomizer.selected_hash
    local key = weapon_hash_key(weapon_hash)
    if not key or not weapon_hash or weapon_hash == 0 then return end

    -- An explicit picker removal wins over active loadout/session maintenance
    -- until the user gives the weapon again or explicitly reapplies a loadout.
    State.session_weapon_keep[key] = nil
    State.session_weapon_removed[key] = true
    State.session_tint_targets[key] = nil
    State.session_weapon_drop_stats[key] = nil
    for target_key, target in pairs(State.session_component_targets or {}) do
        if target and weapon_hash_key(target.weapon_hash) == key then
            State.session_component_targets[target_key] = nil
        end
    end
    local family_key = variant_family_key(weapon_hash)
    if family_key then State.session_variant_overrides[family_key] = nil end
    if weapon_hash_key(State.picker_equip_hash) == key then clear_picker_equip() end

    queue_native_job("weapon_remove", function()
        local ped = local_ped()
        if not entity_exists(ped) then return end
        local selected = invoke_int(H.GET_SELECTED_PED_WEAPON, ped) & 0xFFFFFFFF
        if weapon_hash_key(selected) == key then
            invoke_void(H.SET_CURRENT_PED_WEAPON, ped, Utils.Joaat("weapon_unarmed"), true)
            native_yield(0)
        end
        if invoke_bool(H.HAS_PED_GOT_WEAPON, ped, weapon_hash, false) then
            invoke_void(REMOVE_WEAPON_FROM_PED_NATIVE, ped, weapon_hash)
        end
        WeaponCustomizer.has_weapon = false
        WeaponCustomizer.is_equipped = false
        WeaponCustomizer.installed = {}
        WeaponCustomizer.pending_components = {}
        WeaponCustomizer.dirty = true
        log_info(("Session weapon removed: %s (0x%08X)."):format(
            weapon_display_name(weapon_hash), weapon_hash & 0xFFFFFFFF))
    end)
end

local function verify_active_loadouts(now, ped)
    if not entity_exists(ped) or (State.loadout_verify_due or 0) <= 0 or now < State.loadout_verify_due then
        return
    end

    local missing_total = 0
    local custom_slot = nil
    if is_on("auto_custom_loadout") then
        custom_slot = selected_loadout_slot()
    elseif (State.active_custom_loadout_slot or 0) > 0 then
        custom_slot = State.active_custom_loadout_slot
    end

    if custom_slot then
        local slot = LoadoutStore.slots[custom_slot]
        local hashes = slot and normalize_weapon_hashes(slot.hashes) or {}
        local missing = missing_weapon_hashes(ped, hashes)
        missing_total = missing_total + #missing
        if #missing > 0 then
            for _, hash in ipairs(missing) do
                local saved = loadout_profile_copy(
                    slot.snapshots and slot.snapshots[weapon_hash_key(hash)], hash)
                local ammo = is_on("max_custom_loadout_ammo") and 9999 or (saved and saved.ammo or 250)
                give_or_refresh_weapon(ped, hash, ammo)
                if saved and invoke_bool(H.HAS_PED_GOT_WEAPON, ped, hash, false) then
                    apply_loadout_profile(ped, hash, saved)
                    set_weapon_ammo(ped, hash, ammo)
                end
            end
        end
    end

    if missing_total == 0 then
        State.loadout_verify_due = 0
        State.loadout_verify_attempts = 0
        return
    end

    State.loadout_verify_attempts = (State.loadout_verify_attempts or 0) + 1
    if State.loadout_verify_attempts >= 4 then
        log_warn(("Loadout verification stopped with %d weapon(s) still missing after respawn."):format(missing_total))
        State.loadout_verify_due = 0
        State.loadout_verify_attempts = 0
    else
        State.loadout_verify_due = now + 450
    end
end

local function collect_session_weapon_targets()
    local targets = {}

    local function add(hash, ammo, source, priority)
        local key = weapon_hash_key(hash)
        if not key or session_removed_suppresses(hash) or variant_override_suppresses(hash) then return end
        priority = tonumber(priority) or 0
        local counterpart = variant_counterpart_hash(hash)
        local counterpart_key = weapon_hash_key(counterpart)
        if counterpart_key and targets[counterpart_key] then
            if (targets[counterpart_key].priority or 0) > priority then return end
            targets[counterpart_key] = nil
        end
        local existing = targets[key]
        if not existing or priority >= (existing.priority or 0) then
            targets[key] = {
                hash = hash & 0xFFFFFFFF,
                ammo = math.max(ammo or 250, existing and existing.ammo or 0),
                source = source or "session",
                priority = priority,
            }
        end
    end

    -- A picker action after applying a loadout is an explicit per-family override.
    for _, hash in pairs(State.session_weapon_keep or {}) do
        add(hash, 250, "picker", 70)
    end

    local custom_slot = nil
    if is_on("auto_custom_loadout") then
        custom_slot = selected_loadout_slot()
    elseif (State.active_custom_loadout_slot or 0) > 0 then
        custom_slot = State.active_custom_loadout_slot
    end
    if custom_slot then
        local slot = LoadoutStore.slots[custom_slot]
        for _, hash in ipairs(slot and normalize_weapon_hashes(slot.hashes) or {}) do
            local saved=loadout_profile_copy(
                slot.snapshots and slot.snapshots[weapon_hash_key(hash)], hash)
            local ammo=is_on("max_custom_loadout_ammo") and 9999 or (saved and saved.ammo or 250)
            add(hash, ammo, "custom-loadout", 60)
        end
    end


    return targets
end

local function apply_saved_weapon_customization(ped, weapon_hash)
    if not entity_exists(ped) or not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, weapon_hash, false) then return 0, 0 end
    local component_repairs, tint_repairs = 0, 0
    for _, target in pairs(State.session_component_targets or {}) do
        if target.weapon_hash == weapon_hash and not component_target_is_satisfied(ped, target) then
            if apply_component_target_once(ped, target) then component_repairs = component_repairs + 1 end
        end
    end
    local tint_target = State.session_tint_targets[weapon_hash_key(weapon_hash)]
    if tint_target then
        local count = math.max(0, invoke_int(H.GET_WEAPON_TINT_COUNT, weapon_hash))
        local desired = count > 0 and (tint_target.tint % count) or tint_target.tint
        if count > 0 and invoke_int(H.GET_PED_WEAPON_TINT_INDEX, ped, weapon_hash) ~= desired then
            invoke_void(H.SET_PED_WEAPON_TINT_INDEX, ped, weapon_hash, desired)
            if invoke_int(H.GET_PED_WEAPON_TINT_INDEX, ped, weapon_hash) == desired then tint_repairs = 1 end
        end
    end
    if WeaponCustomizer.selected_hash == weapon_hash and (component_repairs > 0 or tint_repairs > 0) then
        WeaponCustomizer.dirty = true
    end
    return component_repairs, tint_repairs
end

local function note_session_weapon_drop(now, weapon_hash)
    local key = weapon_hash_key(weapon_hash)
    if not key then return end
    local stat = State.session_weapon_drop_stats[key]
    if not stat or now - (stat.window_start or 0) > 30000 then
        stat = { window_start = now, count = 0, last_log = -100000 }
        State.session_weapon_drop_stats[key] = stat
    end
    stat.count = stat.count + 1
    if stat.count >= 3 and now - (stat.last_log or -100000) >= 30000 then
        stat.last_log = now
        log_info(("Inventory drift detected: %s disappeared %d times in 30s; virtual residency is active."):format(
            weapon_display_name(weapon_hash), stat.count))
    end
end

local function maintain_session_weapons(now, ped)
    if now - (State.last_session_weapon_maintenance_ms or -100000) < 200 then return end
    State.last_session_weapon_maintenance_ms = now

    local repaired, names = 0, {}
    for _, target in pairs(collect_session_weapon_targets()) do
        local added=false
        local _, select_target = enforce_variant_target(ped, target.hash)
        if not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target.hash, false) then
            note_session_weapon_drop(now, target.hash)
            added=true
            invoke_void(H.GIVE_WEAPON_TO_PED, ped, target.hash, target.ammo or 250, false, false)
            set_weapon_ammo(ped, target.hash, target.ammo or 250)
            if invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target.hash, false) then
                repaired = repaired + 1
                names[#names + 1] = weapon_display_name(target.hash)
            end
        end
        if select_target and invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target.hash, false) then
            invoke_void(H.SET_CURRENT_PED_WEAPON, ped, target.hash, true)
        end
        if invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target.hash, false) then
            local components=apply_saved_weapon_customization(ped, target.hash)
            if added or components>0 then set_weapon_ammo(ped,target.hash,target.ammo or 250) end
        end
    end

    if repaired > 0 and now - (State.last_session_weapon_repair_log_ms or -100000) >= 1500 then
        State.last_session_weapon_repair_log_ms = now
        log_info(("Session weapon maintenance restored %d weapon(s): %s."):format(
            repaired, table.concat(names, ", ")))
    end
end

local function maintain_session_components(now, ped)
    if now - (State.last_session_component_maintenance_ms or -100000) < 350 then return end
    State.last_session_component_maintenance_ms = now

    local component_repairs, tint_repairs = 0, 0
    for _, target in pairs(State.session_component_targets or {}) do
        if invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target.weapon_hash, false)
            and not component_target_is_satisfied(ped, target) then
            local success = apply_component_target_once(ped, target)
            if success then
                component_repairs = component_repairs + 1
                if WeaponCustomizer.selected_hash == target.weapon_hash then WeaponCustomizer.dirty = true end
            end
        end
    end

    for _, target in pairs(State.session_tint_targets or {}) do
        if invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target.weapon_hash, false) then
            local count = math.max(0, invoke_int(H.GET_WEAPON_TINT_COUNT, target.weapon_hash))
            if count > 0 then
                local desired = target.tint % count
                if invoke_int(H.GET_PED_WEAPON_TINT_INDEX, ped, target.weapon_hash) ~= desired then
                    invoke_void(H.SET_PED_WEAPON_TINT_INDEX, ped, target.weapon_hash, desired)
                    if invoke_int(H.GET_PED_WEAPON_TINT_INDEX, ped, target.weapon_hash) == desired then
                        tint_repairs = tint_repairs + 1
                        if WeaponCustomizer.selected_hash == target.weapon_hash then WeaponCustomizer.dirty = true end
                    end
                end
            end
        end
    end

    if (component_repairs > 0 or tint_repairs > 0)
        and now - (State.last_session_customization_log_ms or -100000) >= 1500 then
        State.last_session_customization_log_ms = now
        log_info(("Weapon customization maintenance restored components=%d tints=%d."):format(
            component_repairs, tint_repairs))
    end
end

local function adopt_live_variant_selection(now, ped, selected)
    selected = (tonumber(selected) or 0) & 0xFFFFFFFF
    local previous = (tonumber(State.last_weapon) or 0) & 0xFFFFFFFF
    if selected == 0 or previous == 0 or selected == previous then return end
    local counterpart = variant_counterpart_hash(selected)
    local family_key = variant_family_key(selected)
    if not counterpart or not family_key then return end
    if not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, selected, false) then return end

    local selected_key = weapon_hash_key(selected)
    local wanted = State.session_variant_overrides[family_key]
    if wanted ~= nil and weapon_hash_key(wanted) == selected_key then
        arm_picker_equip(ped, selected, 3500)
        return
    end

    -- A live Mk I/Mk II selection is explicit user intent. Adopt the weapon that
    -- actually reached the player's hands before loadout residency gets a chance
    -- to reassert the opposite family member.
    local observed_family = State.variant_family_snapshots[family_key]
    if observed_family then
        -- User intent supersedes any earlier observation. If CScript had changed
        -- this family and the player then selected a different live variant, it
        -- relinquishes restoration ownership instead of undoing that choice on
        -- unload.
        observed_family.mutated = false
        observed_family.mutation_reason = "live variant adopted"
    end
    remember_session_weapon(selected)
    arm_picker_equip(ped, selected, 3500)
    if now - (State.last_variant_adopt_log_ms or -100000) >= 500 then
        State.last_variant_adopt_log_ms = now
        log_info(("Live weapon variant adopted: %s now overrides %s for this session."):format(
            weapon_display_name(selected), weapon_display_name(counterpart)))
    end
end

local function maintain_picker_equip(now, ped)
    local target = (tonumber(State.picker_equip_hash) or 0) & 0xFFFFFFFF
    if target == 0 then return end
    if State.picker_equip_ped ~= ped then
        clear_picker_equip()
        return
    end

    local selected = invoke_int(H.GET_SELECTED_PED_WEAPON, ped) & 0xFFFFFFFF
    local target_key = weapon_hash_key(target)
    local selected_key = weapon_hash_key(selected)
    if selected_key == target_key then return end

    local target_owned = invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target, false)
    local counterpart = variant_counterpart_hash(target)
    local counterpart_key = weapon_hash_key(counterpart)
    local counterpart_owned = counterpart and invoke_bool(H.HAS_PED_GOT_WEAPON, ped, counterpart, false) or false

    -- The stabilization pin is only allowed to arbitrate inside the Mk I/Mk II
    -- family it was armed for. A different selected weapon (Grenade Launcher,
    -- Minigun, etc.) is a real wheel/quick-swap choice and must win immediately.
    -- Otherwise a recently equipped Heavy Sniper Mk II can hijack the Heavy
    -- weapon group for several seconds.
    if selected ~= 0 and selected_key ~= counterpart_key then
        clear_picker_equip()
        return
    end

    -- If the target is still cleanly present after the stabilization window, the
    -- player deliberately moved to the counterpart; stop pinning instead of
    -- fighting the new selection.
    if target_owned and not counterpart_owned and now > (State.picker_equip_force_until or 0) then
        clear_picker_equip()
        return
    end

    remember_session_weapon(target)
    enforce_variant_target(ped, target)
    if not invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target, false) then
        invoke_void(H.GIVE_WEAPON_TO_PED, ped, target, 250, false, false)
    end
    if invoke_bool(H.HAS_PED_GOT_WEAPON, ped, target, false) then
        invoke_void(H.SET_CURRENT_PED_WEAPON, ped, target, true)
        State.last_weapon = target
        WeaponCustomizer.dirty = true
        if now - (State.last_picker_equip_repair_log_ms or -100000) >= 1000 then
            State.last_picker_equip_repair_log_ms = now
            log_info(("Picker equip drift repaired: restored %s after GTA inventory fallback."):format(
                weapon_display_name(target)))
        end
    end
end

local function maintain_loadout_persistence(now, ped)
    if not entity_exists(ped) then return end

    local alive = invoke_int(H.GET_ENTITY_HEALTH, ped) > 0
    local ped_changed = ped ~= State.weapon_ped_seen
    local respawned = alive and (ped_changed or State.weapon_ped_alive ~= true)

    if ped_changed then
        State.weapon_ped_seen = ped
        State.custom_loadout_ped = 0
    end

    if respawned then
        -- GTA Online may rebuild the inventory for several frames after the
        -- new ped becomes valid. Delaying the first repair prevents a loadout
        -- from being immediately overwritten by that rebuild.
        State.loadout_respawn_due = now + 750
        State.loadout_verify_due = 0
        State.loadout_verify_attempts = 0
    end
    State.weapon_ped_alive = alive

    if not alive then return end
    if (State.loadout_respawn_due or 0) > 0 and now >= State.loadout_respawn_due then
        State.loadout_respawn_due = 0

        local slot_index = nil
        if is_on("auto_custom_loadout") then
            slot_index = selected_loadout_slot()
        elseif (State.active_custom_loadout_slot or 0) > 0 then
            slot_index = State.active_custom_loadout_slot
        end
        if slot_index then
            apply_custom_loadout(slot_index, true, { maintenance = true })
        end
    end

    verify_active_loadouts(now, ped)
    maintain_session_weapons(now, ped)
    maintain_session_components(now, ped)
end

-- Engine reset flags below belong exclusively to Instant Weapon Switch.
-- They skip/blend animation states; they are NOT a playback-rate multiplier.
local WEAPON_FLAG_INSTANT_BLEND_TO_AIM = 74
local WEAPON_FLAG_INSTANT_BLEND_NO_SETTLE = 401
local WEAPON_FLAG_SKIP_FPS_UNHOLSTER = 426

local function apply_weapon_transition_readiness(ped, transition, write)
    if not write(0xA52D5247A4227E14,ped) then return end -- SET_PED_NO_TIME_DELAY_BEFORE_SHOT
    if transition then
        if not write(H.SET_PED_RESET_FLAG,ped,WEAPON_FLAG_INSTANT_BLEND_TO_AIM,true) then return end
        if not write(H.SET_PED_RESET_FLAG,ped,WEAPON_FLAG_INSTANT_BLEND_NO_SETTLE,true) then return end
        if not write(H.SET_PED_RESET_FLAG,ped,WEAPON_FLAG_SKIP_FPS_UNHOLSTER,true) then return end
    end
end

local function reset_fast_hands(ped)
    -- Extra natural-task updates own no persistent native state.
    State.fast_hands_ped=0
    State.fast_hands_address=nil
    State.fast_hands_weapon=0
    State.fast_hands_until_ms=0
    State.fast_hands_started=nil
    State.fast_hands_was_switching=false
    State.fast_hands_reset_pending=false
    State.fast_hands_anim_active=false
    State.fast_hands_status="IDLE"
end

-- Fast Melee begin
-- Never use FORCE_PED_AI_AND_ANIMATION_UPDATE here: it advances locomotion,
-- AI and hit processing together. Only a positively identified attack clip
-- may receive a modest playback multiplier; GTA still owns the attack task,
-- animation events, damage, targeting, combo transitions and recovery.
local FastMelee = {
    PLAYING = 0x1F0B79228E461EC9, SPEED = 0x28D1A16553C51776,
    PHASE = 0x346D81500D088F42, FRAME_TIME = 0x15C40837039FFAF7,
    RATE = 1.6, RECOVERY_RATE = 1.75, SCAN_BUDGET = 48,
    -- Explicit attacking clips from supplied animDictsCompact.json. Exclude
    -- locomotion, stances, dodges, hit reactions and paired takedowns.
    families = {
        unarmed = { "short_0_punch", "short_90_punch", "short_-90_punch",
            "short_180_punch", "short_-180_punch", "long_0_punch",
            "long_90_punch", "long_-90_punch", "long_180_punch", "long_-180_punch",
            "heavy_punch_a", "heavy_punch_b", "heavy_punch_c",
            "walking_punch", "walking_punch_no_target", "running_punch",
            "running_punch_no_target", "running_punch_long_range", "ground_attack_0",
            "ground_attack_0_long", "ground_attack_90", "ground_attack_-90",
            "ground_attack_180", "ground_attack_-180", "low_attack_0",
            "low_attack_90", "low_attack_-90", "low_attack_180", "low_attack_-180",
            "heavy_punch_a_var_1", "heavy_punch_b_var_1", "heavy_punch_b_var_2", "heavy_punch_c_var_1",
            "kick_close_a", "kick_close_b", "kick_far_a", "vehicle_kick" },
        knife = { "knife_short_range_0", "knife_short_range_90", "knife_short_range_-90",
            "knife_short_range_180", "knife_short_range_-180", "knife_long_range_0",
            "knife_long_range_90", "knife_long_range_-90", "knife_long_range_180",
            "knife_long_range_-180", "kick_close_a", "kick_close_b", "kick_far_a", "vehicle_kick" },
        large_wpn = { "short_0_attack", "short_90_attack", "short_-90_attack",
            "short_180_attack", "short_-180_attack", "long_0_attack", "long_90_attack",
            "long_-90_attack", "long_180_attack", "long_-180_attack",
            "car_side_attack_a", "car_down_attack", "kick_close_a", "kick_close_b", "kick_far_a" },
        small_wpn = { "small_melee_wpn_short_range_0", "small_melee_wpn_short_range_+90",
            "small_melee_wpn_short_range_-90", "small_melee_wpn_short_range_+180",
            "small_melee_wpn_short_range_-180", "small_melee_wpn_long_range_0",
            "small_melee_wpn_long_range_+90", "small_melee_wpn_long_range_-90",
            "small_melee_wpn_long_range_+180", "small_melee_wpn_long_range_-180",
            "car_side_attack_a", "car_down_attack", "kick_close_a", "kick_close_b", "kick_far_a" },
    },
