local function register_features()
    if features_registered then return true end
    add_toggle("gravity_gun","Gravity Gun",
        "RMB: grab. Scroll: move closer/farther. Fire: throw. E: upright. Q: tumble.",false,
        function()Gravity.Reset("READY")end)
    add_slider_float("gravity_power","Gravity Power","Increases pull, push, scroll and throw strength.",1.0,20.0,1.0)
    add_button("remove_all_weapons", "Remove All Weapons", "Removes your weapons and stops automatic loadout restoration.", function()
        remove_all_local_weapons()
    end)
    add_button(
        "refill_owned_weapons",
        "Refill All Owned Weapons",
        "Refills ammunition for every supported weapon currently owned by the local ped.",
        function()
            local ped = local_ped()

            if not entity_exists(ped) then
                toast("Local ped is unavailable.")
                return
            end

            local refilled,unconfirmed = 0,0
        for _, category in ipairs(WEAPON_CATEGORIES) do
            for _, weapon in ipairs(category.weapons) do
                if invoke_bool(H.HAS_PED_GOT_WEAPON, ped, weapon.hash, false) then
                    if set_weapon_ammo(ped,weapon.hash,9999) then refilled=refilled+1
                    else unconfirmed=unconfirmed+1 end
                end
            end
        end
        toast(("Ammo confirmed for %d owned weapon(s); %d unconfirmed."):format(refilled,unconfirmed))
    end)
    add_toggle("shoot_friendlies", "Shoot friendlies",
        "Disables restrictions on shooting friendlies.", false,
        function()
            if ToggleState.shoot_friendlies~=true then State.friendlies_panic_blocked=false end
            Friendlies.IntentChanged(ToggleState.shoot_friendlies==true)
        end)
    Friendlies.IntentChanged(ToggleState.shoot_friendlies==true)
    -- Retain the stored toggle key so existing presets still find this feature.
    add_toggle("near_miss_assist", "Aimbot",
        "Hold aim near a visible player to track them. You fire normally.", false,
        function() SoftAimCamera.Reset() end)
    local aim_strength = add_slider_float("aim_strength", "Aim Strength",
        "Low values gently track. 100% applies full camera correction.", 1.0, 100.0, 35.0, 1.0)
    if aim_strength then aim_strength:SetFloatValue(35.0) end
    local aim_radius = add_slider_float("aim_radius", "Aim Radius",
        "How close a player must be to the crosshair. The area shrinks with zoom.", 1.0, 30.0, 10.0, 1.0)
    if aim_radius then aim_radius:SetFloatValue(10.0) end
    add_toggle("max_ammo", "Max Ammo On Weapon Change", "Refills when you equip or change ammo type, and replenishes an emptied weapon.", false)
    add_toggle("infinite_clip", "Infinite Ammo Clip", "Prevents equipped weapons from needing reloads.", false,
        function(f) if not f:IsToggled() and entity_exists(local_ped()) then invoke_void(H.SET_PED_INFINITE_AMMO_CLIP, local_ped(), false) end end)
    add_toggle("instant_weapon_switch", "Instant Weapon Switch", "Switches weapons instantly when on foot.", false)
    add_toggle("fast_melee", "Fast Melee", "Speeds up melee windup and recovery while keeping normal contact timing and damage.", false,
        function(feature) set_fast_melee_requested(feature:IsToggled()) end)
    add_toggle("fast_hands", "Fast Hands", "Speeds up weapon swaps. Pauses while Instant Weapon Switch is on.", false,
        function(feature)
            State.fast_hands_notice_shown=false
            State.fast_hands_reset_pending=true
        end)

    -- Five persistent visual custom-loadout slots.
    add_combo("loadout_slot", "Custom Loadout Slot", "Selects one of five persistent loadout slots.", {
        "Slot 1", "Slot 2", "Slot 3", "Slot 4", "Slot 5",
    }, 0, function()
        State.custom_loadout_ped = 0
        sync_loadout_picker()
        if is_on("auto_custom_loadout") and entity_exists(local_ped()) then
            State.loadout_respawn_due = now_ms() + 100
        end
    end)
    add_input_text("loadout_name", "Custom Slot Name", "Persistent name for the selected custom loadout slot.", LoadoutStore.slots[1].name)
    for _, category in ipairs(WEAPON_CATEGORIES) do
        for _, weapon in ipairs(category.weapons) do
            add_toggle(weapon.key, weapon[1], "Include " .. weapon[1] .. " in the selected custom slot.", false)
        end
    end
    add_toggle("replace_weapons", "Replace Existing Weapons", "Removes current weapons before applying a loadout.", false)
    add_toggle("max_custom_loadout_ammo", "Max Ammo When Applied", "Gives maximum ammo with the selected loadout.", false)
    add_toggle("auto_custom_loadout", "Auto Apply Selected Loadout", "Re-equips your selected loadout after respawning.", false,
        function(feature)
            State.custom_loadout_ped = 0
            if feature:IsToggled() and entity_exists(local_ped()) then
                State.loadout_respawn_due = now_ms() + 100
            end
        end)
    add_button("save_custom_loadout", "Save Selected Slot", "Saves checked weapons to the selected slot.", function()
        local index = selected_loadout_slot()
        local slot = LoadoutStore.slots[index]
        slot.name = sanitize_slot_name(input_text("loadout_name", slot.name))
        slot.hashes = selected_picker_hashes()
        slot.snapshots=capture_loadout_profiles(local_ped(),slot.hashes,slot.snapshots)
        State.custom_loadout_ped = 0
        local ok, err = save_loadout_store()
        sync_loadout_picker()
        if ok then toast(("Saved '%s' with %d weapons."):format(slot.name, #slot.hashes))
        else toast("Loadout kept in memory; save failed: " .. tostring(err), 6000) end
    end)
    add_button("apply_custom_loadout", "Apply Selected Slot", "Equips the selected loadout.", function()
        apply_custom_loadout(selected_loadout_slot(), false)
    end)
    add_button("clear_custom_loadout", "Clear Selected Slot", "Clears the selected editor and saves the empty slot.", function()
        local index = selected_loadout_slot()
        LoadoutStore.slots[index] = { name = "Custom " .. tostring(index), hashes = {}, snapshots = {} }
        State.custom_loadout_ped = 0
        local ok, err = save_loadout_store()
        sync_loadout_picker()
        if ok then toast("Cleared custom loadout slot " .. tostring(index) .. ".")
        else toast("Slot cleared in memory; save failed: " .. tostring(err), 6000) end
    end)
    sync_loadout_picker()
    features_registered = true
    return true
end

local function render_component_group(title, group)
    ui_spacing(1)
    if ImGui and type(ImGui.Separator) == "function" then pcall(ImGui.Separator) end
    if ImGui and type(ImGui.Text) == "function" then pcall(ImGui.Text, title) end
    ui_spacing(1)
    local count = 0
    for _, component in ipairs(WeaponCustomizer.valid_components) do
        if component.group == group then
            count = count + 1
            local active = WeaponCustomizer.installed[component.hash] == true
            local label = active and component.ui_label_on or component.ui_label_off
            if imgui_clicked("Button", label) then set_weapon_component(component) end
        end
    end
    if count == 0 and ImGui and type(ImGui.TextDisabled) == "function" then
        pcall(ImGui.TextDisabled, "No compatible options.")
    end
end

-- Cherax BeginChild enters a scope but does not return an "opened" boolean.
-- These counters cover only scopes owned by the picker and stay silent when balanced.
local WeaponPickerStack = { tables = 0, children = 0, ids = 0 }

local function check_weapon_picker_stack(where)
    if WeaponPickerStack.tables == 0 and WeaponPickerStack.children == 0 and WeaponPickerStack.ids == 0 then return end
    log_error_once("ui_weapon_picker_stack_" .. tostring(where),
        ("ImGui imbalance after %s: tables=%d children=%d ids=%d"):format(
            tostring(where), WeaponPickerStack.tables, WeaponPickerStack.children, WeaponPickerStack.ids))
end

local function render_weapon_list()
    local begin_ok, begin_err = pcall(ImGui.BeginChild, "##CScriptWeaponList", 0, 420, true, 0)
    if not begin_ok then return false, begin_err end
    WeaponPickerStack.children = WeaponPickerStack.children + 1

    local render_ok, render_err = pcall(function()
        local ui = module_context and module_context.CScriptUI
        if ui and type(ui.surface) == "function" then ui.surface() end
        for category_index, category in ipairs(WEAPON_CATEGORIES) do
            if category_index > 1 then ui_spacing(1) end
            if type(ImGui.TextDisabled) == "function" then ImGui.TextDisabled(category.name) else ImGui.Text(category.name) end
            if type(ImGui.Separator) == "function" then ImGui.Separator() end
            for _, weapon in ipairs(category.weapons) do
                local selected = WeaponCustomizer.selected_hash == weapon.hash
                local label = selected and weapon.ui_label_selected or weapon.ui_label
                if imgui_clicked("Selectable", label, selected) then
                    select_weapon_for_customization(weapon.hash)
                end
            end
        end
    end)

    local end_ok, end_err = pcall(ImGui.EndChild)
    WeaponPickerStack.children = WeaponPickerStack.children - 1
    if not render_ok then return false, render_err end
    if not end_ok then return false, end_err end
    return true
end

local function render_weapon_details()
    local begin_ok, begin_err = pcall(ImGui.BeginChild, "##CScriptWeaponDetails", 0, 420, true, 0)
    if not begin_ok then return false, begin_err end
    WeaponPickerStack.children = WeaponPickerStack.children + 1

    local render_ok, render_err = pcall(function()
        local ui = module_context and module_context.CScriptUI
        if ui and type(ui.surface) == "function" then ui.surface() end
        local weapon = WEAPON_BY_HASH[weapon_hash_key(WeaponCustomizer.selected_hash)]
        if type(ImGui.TextDisabled) == "function" then ImGui.TextDisabled("Selected Weapon")
        else ImGui.Text("Selected Weapon") end
        ImGui.Text(weapon and weapon[1] or "Unknown")
        if type(ImGui.Separator) == "function" then ImGui.Separator() end
        ui_spacing(1)
        if WeaponCustomizer.has_weapon then
            if type(ImGui.TextDisabled) == "function" then
                ImGui.TextDisabled(WeaponCustomizer.is_equipped and "Owned and equipped" or "Owned")
            end
            if not WeaponCustomizer.is_equipped then
                if imgui_clicked("Button", "Equip Weapon##weapon_equip") then equip_selected_weapon() end
                if type(ImGui.SameLine) == "function" then ImGui.SameLine() end
            end
            if imgui_clicked("Button", "Remove Weapon##weapon_remove") then remove_selected_weapon() end
        elseif imgui_clicked("Button", "Give & Equip##weapon_give") then
            give_selected_weapon()
        end
        if weapon then
            local included = is_on(weapon.key)
            if imgui_clicked("Button", (included and "Remove From Loadout" or "Add To Loadout") .. "##weapon_loadout") then
                set_toggle(weapon.key, not included)
            end
        end

        render_component_group("Attachments", "attachment")
        render_component_group("Finish / Skin", "finish")
        if WeaponCustomizer.tint_count > 0 then
            ImGui.Text(("Tint: %d / %d"):format(WeaponCustomizer.tint_index + 1, WeaponCustomizer.tint_count))
            if imgui_clicked("Button", "Previous Tint##weapon_tint_prev") then set_weapon_tint(-1) end
            if type(ImGui.SameLine) == "function" then ImGui.SameLine() end
            if imgui_clicked("Button", "Next Tint##weapon_tint_next") then set_weapon_tint(1) end
        end
        render_component_group("Ammo / Bullet Type", "ammo")
    end)

    local end_ok, end_err = pcall(ImGui.EndChild)
    WeaponPickerStack.children = WeaponPickerStack.children - 1
    if not render_ok then return false, render_err end
    if not end_ok then return false, end_err end
    return true
end

local function render_weapon_picker()
    WeaponCustomizer.last_visible_ms = now_ms()
    check_weapon_picker_stack("entry")

    local flags = ImGuiTableFlags and ImGuiTableFlags.SizingStretchProp or 0
    local begin_ok, opened = pcall(ImGui.BeginTable, "##CScriptWeaponPicker", 2, flags)
    if not begin_ok or opened ~= true then return end
    WeaponPickerStack.tables = WeaponPickerStack.tables + 1

    local scope_err = nil
    local render_ok, render_err = pcall(function()
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0)
        local list_ok, list_err = render_weapon_list()
        if list_ok then
            ImGui.TableSetColumnIndex(1)
            local details_ok, details_err = render_weapon_details()
            if not details_ok then scope_err = details_err end
        else
            scope_err = list_err
        end
    end)

    local end_ok, end_err = pcall(ImGui.EndTable)
    WeaponPickerStack.tables = WeaponPickerStack.tables - 1
    if not render_ok then log_error_once("ui_weapon_picker", render_err) end
    if scope_err ~= nil then log_error_once("ui_weapon_picker_scope", scope_err) end
    if not end_ok then log_error_once("ui_weapon_picker_end_table", end_err) end
    check_weapon_picker_stack("exit")
end

local function frame_tick(now)
    -- Lease restoration must continue when weapon writes are suspended.
    is_on("shoot_friendlies")
    Friendlies.Tick(now)
    Gravity.Tick(now)
    fast_melee_tick(now)
    if State.runtime_writes_suspended then return end
    if Gravity.Requested() then
        SoftAimCamera.Reset()
    else
        SoftAimCamera.Tick(now)
    end
    fast_hands_tick(now)
    instant_weapon_switch_tick(now)
end

local function fast_tick(now, ped)
    if State.runtime_writes_suspended then return end
    refresh_weapon_customizer(now, false)
    ped = tonumber(ped) or local_ped()
    if not entity_exists(ped) then
        State.weapon_ped_alive = false
        return
    end

    local weapon = invoke_int(H.GET_SELECTED_PED_WEAPON, ped) & 0xFFFFFFFF
    if weapon ~= 0 and weapon ~= State.last_weapon then
        adopt_live_variant_selection(now, ped, weapon)
        State.last_weapon = weapon
    end

    process_pending_weapon_components(now, ped)
    maintain_picker_equip(now, ped)
    maintain_loadout_persistence(now, ped)

    Ammo.MaxTick(ped,weapon,is_on("max_ammo"),now)
    if is_on("infinite_clip") then invoke_void(H.SET_PED_INFINITE_AMMO_CLIP, ped, true) end
end

local function slow_tick(now, ped)
    if State.runtime_writes_suspended then return end
    ped = tonumber(ped) or local_ped()
    if not entity_exists(ped) then return end
end

local function restore_player_weapon_state(ped)
    Ammo.target=nil
    Friendlies.Reset("OFF")
    reset_fast_melee()
    Gravity.Reset("OFF")
    SoftAimCamera.Reset()
    ped = tonumber(ped) or local_ped()
    if entity_exists(ped) then
        invoke_void(H.SET_PED_INFINITE_AMMO_CLIP, ped, false)
        invoke_void(H.SET_PED_CAN_SWITCH_WEAPON, ped, true)
    end
    reset_fast_hands(0)
    reset_instant_switch()
    State.last_weapon = 0
end

local function clear_weapon_bookkeeping()
    Ammo.target=nil
    Friendlies.Reset("OFF")
    reset_fast_melee()
    Gravity.Reset("OFF")
    reset_instant_switch()
    SoftAimCamera.Reset()
    State.job_generation =
        (tonumber(State.job_generation) or 0) + 1
    State.custom_loadout_ped = 0
    State.active_custom_loadout_slot = 0
    State.weapon_ped_seen = 0
    State.weapon_ped_alive = false
    State.loadout_respawn_due = 0
    State.loadout_verify_due = 0
    State.loadout_verify_attempts = 0
    State.session_weapon_keep = {}
    State.session_weapon_removed = {}
    State.session_component_targets = {}
    State.session_tint_targets = {}
    State.session_variant_overrides = {}
    State.session_weapon_drop_stats = {}
    clear_picker_equip()
    State.last_variant_adopt_log_ms = -100000
    State.last_picker_equip_repair_log_ms = -100000
    State.last_session_weapon_maintenance_ms = -100000
    State.last_session_component_maintenance_ms = -100000
    State.last_session_weapon_repair_log_ms = -100000
    State.last_session_customization_log_ms = -100000
    WeaponCustomizer.valid_components = {}
    WeaponCustomizer.installed = {}
    WeaponCustomizer.pending_components = {}
    WeaponCustomizer.last_component_click_ms = {}
    WeaponCustomizer.dirty = true
    WeaponCustomizer.last_sample_ms = -100000
    WeaponCustomizer.last_visible_ms = -100000
end

local function clear_runtime_state(ped)
    local friendlies_disabled=set_toggle("shoot_friendlies",false)
    State.friendlies_panic_blocked=not friendlies_disabled
    Friendlies.IntentChanged(false)
    reset_fast_melee()
    -- Explicit Panic Reset remains user-directed and may restore owned state.
    ped = tonumber(ped) or local_ped()
    restore_variant_families(ped)
    restore_player_weapon_state(ped)
    clear_weapon_bookkeeping()
end

local function suspend_runtime_writes()
    reset_fast_melee()
    if State.runtime_writes_suspended then
        return true
    end

    -- Block scheduler and queued-job writes first. Suspension must pause
    -- runtime behavior without destroying the user's desired feature state.
    State.runtime_writes_suspended = true
    Friendlies.Reset("PAUSED")
    Gravity.Reset("PAUSED")
    SoftAimCamera.Reset()

    State.job_generation =
        (tonumber(State.job_generation) or 0) + 1

    local ped =
        local_ped()

    if entity_exists(ped) then
        if is_on("infinite_clip") then
            invoke_void(
                H.SET_PED_INFINITE_AMMO_CLIP,
                ped,
                false
            )
        end

    end

    reset_fast_hands(0)
    reset_instant_switch()
    State.last_weapon = 0

    return true
end

local function revalidate_runtime_state()
    if not bound then
        return false,
            "weapons module is not compatibility-bound"
    end

    State.runtime_writes_suspended = false
    Friendlies.Reset("READY")
    Gravity.Reset("READY")
    SoftAimCamera.Reset()

    reset_fast_hands(0)
    reset_instant_switch()
    State.last_weapon = 0

    -- Force the preserved desired inventory/customization state to be
    -- checked immediately after the suspension is released.
    State.last_session_weapon_maintenance_ms = -100000
    State.last_session_component_maintenance_ms = -100000

    WeaponCustomizer.dirty = true
    WeaponCustomizer.last_sample_ms = -100000

    set_fast_melee_requested(ToggleState.fast_melee==true)
    return true
end

local function session_change_cleanup()
    Friendlies.OnSessionChange()
    -- Session transitions invalidate all captured entity/inventory ownership.
    -- Never chase stale handles with inventory natives during the transition.
    State.variant_family_snapshots = {}
    State.session_variant_overrides = {}
    clear_weapon_bookkeeping()
    set_fast_melee_requested(ToggleState.fast_melee==true)
end

local function safe_host_unload()
    local melee_restored=reset_fast_melee()
    local gravity_restored=Gravity.Reset("OFF")
    local friendlies_restored=Friendlies.Reset("OFF")
    if State.host_cleanup_done == true then return melee_restored and gravity_restored and friendlies_restored, 0 end
    State.host_cleanup_done = true
    -- Discard any transition bookkeeping before the unload fast path.
    reset_fast_hands(0)
    local restored = 0
    local has_owned_change = is_on("infinite_clip")
    if not has_owned_change then
        for _, family in pairs(State.variant_family_snapshots or {}) do
            if family.mutated == true then has_owned_change = true; break end
        end
    end
    if not has_owned_change then
        -- The common live-adoption path is bookkeeping-only. Avoid even benign
        -- session/entity probes when there is nothing CScript owns to restore.
        State.variant_family_snapshots = {}
        State.session_variant_overrides = {}
        clear_weapon_bookkeeping()
        return melee_restored and gravity_restored and friendlies_restored, 0
    end
    local ped = tonumber(State.weapon_ped_seen) or 0
    local session_valid = H.NETWORK_IS_SESSION_STARTED ~= nil
        and invoke_bool(H.NETWORK_IS_SESSION_STARTED) == true
    local ped_valid = ped ~= 0 and State.weapon_ped_alive == true
        and tonumber(local_ped()) == ped and entity_exists(ped)
    if session_valid and ped_valid then
        restored = restore_variant_families(ped)
        if is_on("infinite_clip") then invoke_void(H.SET_PED_INFINITE_AMMO_CLIP, ped, false) end
    else
        -- Ownership is no longer safe to exercise. Drop bookkeeping without
        -- touching weapon inventory; a cosmetic restore is never worth a host
        -- access violation during teardown.
        State.variant_family_snapshots = {}
        State.session_variant_overrides = {}
    end
    clear_weapon_bookkeeping()
    return melee_restored and gravity_restored and friendlies_restored, restored
end

local api = {
    AmmoSnapshot = Ammo.Snapshot,
    RegisterFeatures = register_features,
    RenderPicker = render_weapon_picker,
    FrameTick = frame_tick,
    FrameRequested = function()
        return State.fast_melee_clip~=nil or Gravity.Requested() or Friendlies.Requested() or State.runtime_writes_suspended ~= true
            and (State.fast_melee_requested==true or is_on("shoot_friendlies") or is_on("near_miss_assist") or is_on("instant_weapon_switch") or is_on("fast_hands")
                or State.fast_hands_reset_pending == true or State.fast_hands_anim_active == true)
    end,
    FastTick = fast_tick,
    SlowTick = slow_tick,
    RestorePlayer = restore_player_weapon_state,
    PanicReset = clear_runtime_state,
    SuspendRuntimeWrites = suspend_runtime_writes,
    RevalidateRuntimeState = revalidate_runtime_state,
    RuntimeWritesSuspended = function() return State.runtime_writes_suspended == true end,
    HostUnload = safe_host_unload,
    OnSessionChange = session_change_cleanup,
    SyncLoadoutPicker = sync_loadout_picker,
    WeaponCount = WEAPON_COUNT,
    State = State,
    GravitySnapshot = Gravity.Snapshot,
    AimSnapshot = SoftAimCamera.Snapshot,
    -- Keep the existing cleanup scheduler entrypoints, draining both leases.
    GravityRestoreTick = function(now)
        local gravity=Gravity.RestoreTick(now)
        local friendlies=Friendlies.RestoreTick(now)
        return gravity and friendlies
    end,
    GravityRestoreRequested = function()return Gravity.RestoreRequested()or Friendlies.RestoreRequested()end,
    FriendliesSnapshot = Friendlies.Snapshot,
    FriendliesRestoreRequested = Friendlies.RestoreRequested,
    CanHandoff = function()return State.fast_melee_clip==nil and not Gravity.Requested()and not Friendlies.Requested()end,
}
function api.RegisteredCount() return State.registered_count end
function api.IsOn(key) return is_on(key) end
function api.GetFeature(key) return F[key] end
if module_context and module_context.Raw and module_context.Raw.TestMode == true then
    function api.TestEnforceVariant(ped, weapon_hash)
        capture_variant_for_owned_change(ped, weapon_hash, "debug regression mutation")
        return enforce_variant_target(ped, weapon_hash, "debug regression mutation")
    end
end
return api
end

local function publish_state(context)
    local root = context.State.Weapons
    if type(root) ~= "table" then
        root = {}
        context.State.Weapons = root
    end
    root.MigrationPhase = Module.MigrationPhase
    root.Runtime = State
    root.Started = started
    root.Bound = bound
end

function Module.BindCompatibility(bindings)
    if not module_context then error("weapons module must initialize before compatibility binding", 2) end
    if bound then return public_api end
    dependencies = bindings or {}
    public_api = create_weapon_system(dependencies)
    bound = true
    module_context.CScript.Weapons = public_api
    module_context.Modules.Weapons = Module
    publish_state(module_context)
    return public_api
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table"
        or type(context.CScript) ~= "table" or type(context.Modules) ~= "table" then
        error("modules.weapons received an invalid context")
    end
    if module_context and module_context ~= context then
        error("modules.weapons is already initialized by another context")
    end
    module_context = context
    context.State.Weapons = context.State.Weapons or {}
    context.Modules.Weapons = Module
    publish_state(context)
end

function Module.Start()
    if not module_context then error("modules.weapons started before initialization") end
    started = true
    State.host_cleanup_done = false
    State.runtime_writes_suspended = false
    publish_state(module_context)
end

function Module.Stop()
    -- Stop while bindings are still valid, then make Restore bookkeeping-only.
    -- Host cleanup is ownership-scoped and idempotent.
    if public_api and type(public_api.HostUnload) == "function" then public_api.HostUnload() end
    started = false
    if module_context then publish_state(module_context) end
end

function Module.CanHandoff()
    -- Preflight only: never release a hold or restore a host toggle here.
    return public_api==nil or public_api.CanHandoff()==true
end

function Module.Restore(context)
    context = context or module_context
    started = false
    if public_api and type(public_api.HostUnload) == "function" and public_api.HostUnload()==false then
        -- Retain bindings and ownership debt for the caller's next cleanup pass.
        if module_context then publish_state(module_context) end
        return false,"Weapon state restoration remains pending"
    end
    if context and context.CScript and context.CScript.Weapons == public_api then
        context.CScript.Weapons = nil
    end
    if context and context.Modules and context.Modules.Weapons == Module then
        context.Modules.Weapons = nil
    end
    if context and context.State then context.State.Weapons = {} end
    public_api = nil
    dependencies = nil
    module_context = nil
    bound = false
    started = false
    features_registered = false
    F = {}
    ToggleState = {}
end
return Module
]====],
    ["modules/world.lua"] = [====[
-- Local world and rendering controls, exposed through the UI and config bridges.
local Module = { Name = "modules.world", MigrationPhase = "17.75" }

local module_context
local public_api
local started = false
local syncing_fps_toggle = false
local lifecycle
local lifecycle_epoch = 0
local cutscene_request_epoch = 0

local function current_callback(token)
    return token ~= nil and token == lifecycle and token.revoked ~= true
end

-- Feature/UI/session callbacks may run outside the existing native-script loop.
-- They only coalesce requests; FrameTick/FastTick perform the game operations.
local function queue_command(key, value)
    if not current_callback(lifecycle) or lifecycle.failed == true then return false end
    lifecycle.pending[key] = value
    return true
end

local FEATURE_ID_NAMESPACE = "JinxRebound_"
local ID = {}
local F = {}

local function new_cutscene_skip_state()
    return {
        initialized = false, last_interior = 0, phase = "idle",
        signal_started_ms = -100000, origin_interior = 0, destination_interior = 0,
        entry_started_ms = -100000, entry_deadline_ms = -100000,
        destination_ready_ms = -100000, fade_owned = false, camera_suppressed = false,
        release_until_ms = -100000, last_action_ms = -100000,
        last_kind = "None", last_detail = "No cutscene or entry transition has been skipped.", count = 0,
        native_pending = nil, native_status = "IDLE", native_blocked = false,
        native_requests = 0, playback_ended = false, property_completed = false,
        mp_status = "NOT_SAMPLED", presentation_kind = "NONE", mp_detail = "",
    }
end

