end

local function entry_poll_completion(pending,subject)
    if not pending.fast_path then return end
    if entry_threads(ENTRY_INT)~=1 then return end
    local ptr=entry_pointer(ENTRY_INT,263)
    if not ptr then return end
    local property=entry_read(ENTRY_INT,265);local family=entry_read(ENTRY_INT,266)
    local phase=entry_read(ENTRY_INT,267);local interior=entry_read(ENTRY_INT,271)
    if entry_pointer(ENTRY_INT,263)~=ptr or entry_threads(ENTRY_INT)~=1 then return end
    -- The interior script can briefly expose an older/default target while the
    -- exterior handoff is being consumed. Do not tear down a successful direct
    -- lease on that first transient sample. Bind only once the same property and
    -- family arrive; after binding, any identity replacement remains fail-closed.
    if property~=pending.before.property or family~=pending.before.family then
        if pending.int_bound then entry_cancel("Interior target changed after bind",false) end
        return
    end
    if pending.int_ptr and pending.int_ptr~=ptr then
        if pending.int_bound then entry_cancel("Interior controller storage changed after bind",false) end
        return
    end
    pending.int_ptr=ptr
    pending.int_bound=true
    entry_suppress_arrival_presentation(pending,subject,phase,interior)
    if phase==2 then pending.saw_transfer=true end
    if phase==3 and pending.saw_transfer then pending.saw_owner_wait=true end
    if phase>=4 and phase<=7 and pending.saw_owner_wait and entry_global(ENTRY_ROOT+761)==1 then
        pending.saw_owner_complete=true
    end
    local final_ready = phase==7 and interior>0 and entry_global(ENTRY_ROOT+761)==1
        and invoke_int(H.GET_INTERIOR_FROM_ENTITY,subject.ped)==interior
        and invoke_bool(H.IS_INTERIOR_READY,interior) and invoke_bool(H.IS_PLAYER_CONTROL_ON,invoke_int(H.PLAYER_ID))
    if not final_ready then pending.final_ready_at=nil; pending.final_ready_samples=0 end
    if final_ready then
        local now=now_ms()
        if not pending.final_ready_at or now<pending.final_ready_at then
            pending.final_ready_at=now;pending.final_ready_samples=0
        end
        pending.final_ready_samples=(pending.final_ready_samples or 0)+1
        -- Phase transitions can occur within one Rockstar tick. Require stable
        -- final owner, controller, physical interior and control evidence instead
        -- of demanding that Lua sampled every intermediate phase.
        if not pending.saw_owner_complete and (pending.final_ready_samples<2 or now-pending.final_ready_at<120) then return end
        local current=entry_context()
        if EntrySkip.pending~=pending or not current or current.ped~=pending.ped or current.model~=pending.model
            or pending.epoch~=cutscene_request_epoch or not is_on("skip_entry_cutscenes")
            or entry_pointer(ENTRY_INT,263)~=ptr or entry_threads(ENTRY_INT)~=1 then
            entry_cancel("Completion subject changed",false);return
        end
        local direct_restored=entry_release_direct(pending,"completion")
        EntrySkip.pending=nil;EntrySkip.completed=EntrySkip.completed+1;EntrySkip.status="COMPLETED"
        EntrySkip.detail=pending.arrival_only
            and "Loaded facility arrival camera shortened; GTA completed its own interior placement and cleanup."
            or pending.direct_armed
            and "Simple-interior entry completed through Rockstar's seamless no-fade/no-loading branch."
            or "Simple-interior entry completed through the presentation-bypass fallback; GTA retained its normal loading path."
        log_entry("InteriorEntry status=COMPLETED property="..property.." family="..family.." interior="..interior
            .." direct="..tostring(pending.direct_armed).." direct_restored="..tostring(direct_restored).." requests="..EntrySkip.requests)
    end
end
-- A facility may already be in its interior camera sequence when the toggle is
-- enabled, or exterior phase 2 may pass between samples. The source-backed
-- func_8312 camera bank is independent of the optional seamless loading lease.
-- Attach only to the registered ready destination and its live camera, never by forcing
-- the exterior handoff, scene phase, collision, player control or coordinates.
local function entry_attach_facility_arrival(subject,base)
    if not subject or entry_threads(ENTRY_INT)~=1 then return false end
    local ptr=entry_pointer(ENTRY_INT,263)
    if not ptr then return false end
    local property=entry_read(ENTRY_INT,265)
    local family=entry_read(ENTRY_INT,266)
    local phase=entry_read(ENTRY_INT,267)
    local interior=entry_read(ENTRY_INT,271)
    if family~=9 and family~=17 then return false end
    local function waiting(reason)
        -- Existing Arcade misses had no interior-controller evidence. Log a
        -- changed admission denial only; this observer never changes admission.
        if family==17 then
            local key=property..":"..phase..":"..interior..":"..reason
            if EntrySkip.arrival_observation_key~=key then
                EntrySkip.arrival_observation_key=key
                log_entry("InteriorEntry status=ARRIVAL_WAITING property="..property.." family=17 phase="..phase
                    .." interior="..interior.." reason="..reason)
            end
        end
        return false
    end
    if not entry_integer(property,1,4095) or not (entry_integer(phase,2,7) or family==9 and phase==24)
        or not entry_integer(interior,1,0x7FFFFFFF) then return waiting("unsupported_controller_state") end
    if not entry_arrival_target(property,interior) then
        if entry_global(ENTRY_ROOT+759)~=property then return waiting("destination_target_changed") end
        local pid=invoke_int(H.PLAYER_ID)
        if not entry_integer(pid,0,31) or entry_global(2658296+1+pid*468+325+11)~=pid then
            return waiting("destination_not_owned")
        end
        return waiting("destination_not_ready")
    end
    local active=false
    for _,camera_index in ipairs(ARRIVAL_CAMERA_BANKS) do
        local bank=camera_index-387
        local cam=entry_global(camera_index)
        if entry_global(bank+386)==1 and entry_integer(cam,1,0x7FFFFFFF)
            and invoke_bool(H.DOES_CAM_EXIST,cam) then active=true end
    end
    if not active then return waiting("arrival_camera_inactive") end
    local now=now_ms()
    local pending={before={property=property,family=family},base=base,ped=subject.ped,model=subject.model,
        epoch=cutscene_request_epoch,lifecycle=lifecycle_epoch,at=now,sample_at=now,
        int_ptr=ptr,int_bound=true,fast_path=true,arrival_only=true}
    if not entry_arrival_guard(pending) then return waiting("arrival_bytecode_mismatch") end
    local fresh=entry_context()
    if not fresh or fresh.ped~=subject.ped or fresh.model~=subject.model
        or not is_on("skip_entry_cutscenes") or pending.epoch~=cutscene_request_epoch
        or entry_threads(ENTRY_INT)~=1 or entry_pointer(ENTRY_INT,263)~=ptr
        or entry_read(ENTRY_INT,265)~=property or entry_read(ENTRY_INT,266)~=family
        or entry_read(ENTRY_INT,267)~=phase or entry_read(ENTRY_INT,271)~=interior then return false end
    EntrySkip.pending=pending;EntrySkip.requests=EntrySkip.requests+1
    EntrySkip.status="ARRIVAL_OBSERVING"
    EntrySkip.detail="Property destination is loaded; shortening only its verified arrival camera."
    entry_suppress_arrival_presentation(pending,fresh,phase,interior)
    return true
end
local function entry_tick_impl()
    local cleanup=EntrySkip.cleanup
    if cleanup then
        local now=now_ms()
        if cleanup.lifecycle~=lifecycle_epoch then
            EntrySkip.cleanup=nil
            EntrySkip.cleanup_status="ABANDONED_SESSION_CHANGED"
            log_entry("InteriorEntry restore abandoned: original lifecycle ended; no old baseline written.")
        elseif not cleanup.cleanup_retry_at or now<cleanup.cleanup_retry_at-250 or now>=cleanup.cleanup_retry_at then
            cleanup.cleanup_retry_at=now+250
            local subject=entry_context()
            local image,base=false,nil
            if entry_api_ready() then image,base=entry_image() end
            if image and base==cleanup.base and subject and subject.ped==cleanup.ped and subject.model==cleanup.model then
                if entry_release_direct(cleanup,"pending cleanup retry") then
                    EntrySkip.cleanup=nil;EntrySkip.cleanup_status="RESTORED"
                end
            end
        end
        if EntrySkip.cleanup then EntrySkip.cleanup_status="RESTORE_PENDING";return end
    end
    if not entry_api_ready() then
        if EntrySkip.pending then entry_cancel("Entry API unavailable",false) end
        EntrySkip.status="UNSUPPORTED";EntrySkip.detail="Simple-interior entry skipping requires documented local/global/image APIs including safe global readback.";return
    end
    local image,base=entry_image()
    if not image then
        if EntrySkip.pending then entry_cancel("Game build changed",false) end
        EntrySkip.status="UNSUPPORTED";EntrySkip.detail="Simple-interior executable/controller guards are unavailable on this Enhanced build.";return
    end
    local subject=entry_context()
    local pending=EntrySkip.pending
    if pending then
        if not is_on("skip_entry_cutscenes") or pending.epoch~=cutscene_request_epoch then
            entry_cancel("Entry skipping disabled or reset",true);return
        end
        if base~=pending.base or not subject or subject.ped~=pending.ped or subject.model~=pending.model or pending.lifecycle~=lifecycle_epoch then
            entry_cancel("Character or session changed",false);return
        end
        local now=now_ms()
        if now<pending.at or now-pending.at>20000 then entry_cancel("Entry observation timed out",true);return end
        if now<pending.sample_at or now-pending.sample_at>500 then
            entry_cancel("Entry observation gap",false);return
        end
        pending.sample_at=now
        if pending.arrival_only then entry_poll_completion(pending,subject);return end
        local s=entry_ext_snapshot()
        if s then
            if not entry_identity(s,pending.before) then entry_cancel("Exterior target changed",false);return end
            if (s.phase>=14 and s.phase<=18 or s.camera~=0 or s.shots~=0)
                and not (pending.direct_armed and pending.fast_path) then
                entry_cancel("GTA selected a presentation path",false);return
            end
            if s.phase==10 or s.phase==11 or s.phase==19 then
                pending.fast_path=true;EntrySkip.status="TRANSFERRING"
                EntrySkip.detail=pending.direct_armed
                    and "Rockstar seamless simple-interior handoff active; CScript is waiting for GTA's interior owner."
                    or "Presentation bypass active; GTA is using its normal transfer."
            elseif s.phase==0 or s.phase==1 then entry_cancel("Entry returned to selection",false);return end
        elseif not pending.fast_path then entry_cancel("Exterior controller changed before handoff",false);return end
        entry_poll_completion(pending,subject);return
    end
    if not is_on("skip_entry_cutscenes") or not subject then return end
    if entry_attach_facility_arrival(subject,base) then return end
    local s=entry_ext_snapshot()
    if not s then return end
    if EntrySkip.blocked and (not entry_identity(s,EntrySkip.blocked) or s.phase~=2) then EntrySkip.blocked=nil end
    if not entry_before_presentation(s) or EntrySkip.blocked then return end
    local epoch=cutscene_request_epoch
    local current=entry_context();local fresh=entry_ext_snapshot()
    if not entry_identity(fresh,s) or not entry_before_presentation(fresh) or not current
        or current.ped~=subject.ped or current.model~=subject.model or not is_on("skip_entry_cutscenes")
        or epoch~=cutscene_request_epoch or not started or not current_callback(lifecycle) then return end
    EntrySkip.blocked=s
    pending={before=s,applied=s.flags & (~64),base=base,ped=subject.ped,model=subject.model,
        lifecycle=lifecycle_epoch,epoch=epoch,at=now_ms(),direct_armed=false,direct_released=false,
        descriptor_changed=(s.flags & 64)~=0}
    pending.sample_at=pending.at
    EntrySkip.pending=pending

    local direct_ok,direct_reason=entry_arm_direct(pending)
    if not direct_ok then
        if pending.direct_rollback_failed then
            entry_cancel("Direct simple-interior arm rollback failed: "..tostring(direct_reason),true)
            EntrySkip.status="FAILED"
            return
        end
        pending.direct_fallback=tostring(direct_reason)
        log_entry("InteriorEntry status=DIRECT_FALLBACK property="..s.property.." reason="..tostring(direct_reason))
    end

    if pending.descriptor_changed then
        local accepted,result=pcall(ScriptLocal.SetInt,ENTRY_EXT,732,pending.applied)
        if not accepted or result==false then entry_cancel("Entry presentation-bit write failed",true);EntrySkip.status="FAILED";return end
    end
    local verified=entry_ext_snapshot()
    local verified_subject=entry_context()
    if not entry_identity(verified,s) or verified.phase~=2 or verified.flags~=pending.applied
        or not verified_subject or verified_subject.ped~=subject.ped or verified_subject.model~=subject.model
        or not started or not current_callback(lifecycle) or epoch~=cutscene_request_epoch then
        entry_cancel("Entry pre-presentation readback did not match",true);EntrySkip.status="FAILED";return
    end
    EntrySkip.requests=EntrySkip.requests+1;EntrySkip.status=direct_ok and "DIRECT_REQUESTED" or "REQUESTED"
    EntrySkip.detail=direct_ok
        and "Rockstar seamless simple-interior branch armed before presentation; waiting for GTA's matching interior owner."
        or "Direct branch unavailable ("..tostring(direct_reason).."); presentation-only bypass requested."
    log_entry("InteriorEntry status="..EntrySkip.status.." property="..s.property.." family="..s.family.." entrance="..s.entrance
        .." flags_before="..s.flags.." flags_after="..pending.applied.." descriptor_changed="..tostring(pending.descriptor_changed)
        .." seamless_marker="..tostring(pending.direct_armed).." no_loading="..tostring(pending.no_loading_owned)
        .." shared_controller=true source_branch_verified=true live_result=pending")
end
local function entry_tick()
    local ok,reason=pcall(entry_tick_impl)
    if not ok then
        entry_cancel("Entry adapter read failed",false)
        EntrySkip.status="FAILED";EntrySkip.detail="Simple-interior entry read failed: "..tostring(reason)
    end
end

-- Apartment entry is owned by am_mp_property_int, not the exterior menu.
-- Enhanced source: func_9899, main phase 3, animation kinds 3/4, stage 5.
-- Advance only the controller's running local scene to its own f_242 threshold.
-- GTA still executes its threshold side effects, stage 20 cleanup and phase 4.
local function property_entry_cancel(reason)
    local pending=PropertyEntry.pending
    PropertyEntry.pending=nil
    if pending then
        PropertyEntry.status="CANCELLED"
        PropertyEntry.detail=tostring(reason).."; GTA retains entry cleanup and placement."
        log_entry("PropertyEntry status=CANCELLED property="..tostring(pending.property).." reason="..tostring(reason))
    end
end

local function property_is_apartment(property)
    -- func_13160 returns apartment families 4/5/6 for precisely these ranges.
    return entry_integer(property,1,23) or entry_integer(property,34,43) or entry_integer(property,61,85)
end

local function property_has_local_arrival(property)
    -- func_13160 families7/8/9/10 use the same kind3 scene threshold and cleanup.
    -- Garage/exit/elevator kinds remain excluded by the separate kind3/phase3 guards.
    return property_is_apartment(property) or entry_integer(property,86,114)
end

local function property_arrival_kind(s)
    if s.kind==3 then return property_has_local_arrival(s.property) end
    -- func_13160 families 4/5, func_9987 case 4: the alternate interior
    -- doorway animation. func_9899 stage 5 routes both kinds 3 and 4 through
    -- the same f_242 threshold and stage 20 cleanup. Other families/kinds
    -- (garage, elevator, visitors and exits) do not borrow that authorization.
    return s.kind==4 and (entry_integer(s.property,8,23) or entry_integer(s.property,66,72))
end

local function property_int_snapshot()
    if entry_threads(PROPERTY_INT)~=1 or type(ScriptLocal.GetFloat)~="function" then return nil end
    local ptr=entry_pointer(PROPERTY_INT,706)
    if not ptr then return nil end
    local s={ptr=ptr,phase=entry_read(PROPERTY_INT,706),property=entry_read(PROPERTY_INT,496),
        local_scene=entry_read(PROPERTY_INT,387),owner=entry_read(PROPERTY_INT,3845+11),
        interior=entry_read(PROPERTY_INT,7910),stage=entry_read(PROPERTY_INT,10224),
        kind=entry_read(PROPERTY_INT,10224+229),scene=entry_read(PROPERTY_INT,10224+33),
        scene_ped=entry_read(PROPERTY_INT,10224+20+1),scene_player=entry_read(PROPERTY_INT,10224+37+1),flags=entry_read(PROPERTY_INT,10224+255),
        threshold=ScriptLocal.GetFloat(PROPERTY_INT,10224+242)}
    if entry_pointer(PROPERTY_INT,706)~=ptr or entry_threads(PROPERTY_INT)~=1 then return nil end
    return s
end

local function property_identity(a,b)
    return a and b and a.ptr==b.ptr and a.property==b.property and a.owner==b.owner and a.kind==b.kind
        and a.interior==b.interior and a.scene==b.scene and a.scene_ped==b.scene_ped and a.scene_player==b.scene_player
end

local function property_actor_matches(s,subject)
    -- func_9987 case3/4 creates this client's clone via func_10010. However
    -- func_9899 stage0 then resets f_37[] to INVALID_PLAYER_INDEX (584831),
    -- so that array is NOT a usable player-identity guard during stages3/5.
    -- Bind the actual local presentation actor, model and script allocation.
    return s and subject and s.local_scene==1
        and (s.scene_player==-1 or s.scene_player==invoke_int(H.PLAYER_ID))
        and entry_integer(s.scene_ped,1,2147483647) and s.scene_ped~=subject.ped
        and invoke_bool(H.DOES_ENTITY_EXIST,s.scene_ped) and not invoke_bool(H.IS_ENTITY_DEAD,s.scene_ped,false)
        and invoke_int(H.GET_ENTITY_MODEL,s.scene_ped)==subject.model
end

local function property_scene_ready(s,subject)
    if not (s and subject and property_arrival_kind(s) and s.phase==3 and s.stage==5
        -- func_9899 stage5 advances this client's local clone scene even when
        -- the apartment belongs to another player. Owner remains bound to the
        -- transaction; f_37 was reset at stage0 and cannot authorize this scene.
        and s.local_scene==1 and entry_integer(s.owner,0,31)
        and property_actor_matches(s,subject) and entry_integer(s.scene,0,2147483647)
        and entry_integer(s.interior,1,2147483647) and invoke_bool(H.IS_INTERIOR_READY,s.interior)
        and (s.flags & (1<<7))~=0 and (s.flags & (1<<13))==0
        and type(s.threshold)=="number" and s.threshold==s.threshold
        and s.threshold>=0.24 and s.threshold<1.0
        and invoke_bool(0x25D39B935A038A26,s.scene)) then return false end
    -- func_9899 stage5 acknowledges a running kind3/4 scene only after phase
    -- exceeds 0.01. Exterior phase5 consumes f_27 immediately (f_28/f_25),
    -- so it cannot be a durable readiness latch. Recheck that same initialized
    -- local scene directly; property_seek_scene also rebinds allocation, owner,
    -- property and clone before requesting only GTA's existing threshold.
    local phase=invoke_native("float",0xE4A310B1D7FA73CC,s.scene)
    return type(phase)=="number" and phase==phase and phase>0.01 and phase<s.threshold
end

local function property_ext_handoff_snapshot(s,subject)
    if not s or s.phase~=3 or s.stage~=3 or s.kind~=3 or s.local_scene~=1
        or not property_is_apartment(s.property) or s.owner~=invoke_int(H.PLAYER_ID)
        or not property_actor_matches(s,subject) or s.interior<=0 or not invoke_bool(H.IS_INTERIOR_READY,s.interior)
        or entry_threads(PROPERTY_EXT)~=1 or entry_global(1844984+28)~=0
        or entry_global(1844984+27)~=0 or entry_global(1844984+19)~=s.property
        or entry_global(1844984+3)~=s.owner then return nil end
    local ptr=entry_pointer(PROPERTY_EXT,257)
    if not ptr then return nil end
    local e={ptr=ptr,phase=entry_read(PROPERTY_EXT,257),stage=entry_read(PROPERTY_EXT,246),
        property=entry_read(PROPERTY_EXT,278),entrance=entry_read(PROPERTY_EXT,280)}
    if e.phase~=5 or e.stage~=3 or e.property~=s.property or not entry_integer(e.entrance,0,2)
        or entry_pointer(PROPERTY_EXT,257)~=ptr or entry_threads(PROPERTY_EXT)~=1 then return nil end
    return e
end

local function property_seek_scene(pending,s,subject)
    if pending.scene_seek or not property_scene_ready(s,subject) then return false end
    local phase=invoke_native("float",0xE4A310B1D7FA73CC,s.scene)
    if type(phase)~="number" or phase~=phase or phase<0.01 or phase>=s.threshold then return false end
