    if ok and type(value)=="number" and value==value and value~=math.huge and value~=-math.huge then return value end
    Audio.failure("float:"..tostring(hash),value)
end
function Audio.tv_tick(enabled)
    local owned=Audio.tv
    if not enabled and not owned then return end
    if owned and owned.token~=lifecycle then Audio.tv=nil;owned=nil end
    local current=Audio.number(AH.tv_read)
    if current==nil then Audio.diag.tv_state="Volume unreadable";return end
    Audio.diag.tv_volume=current
    if enabled then
        if current>-100.0 then
            -- Keep the first baseline for this ownership period. Game fades
            -- can derive a new gain from our -100; it is not a new baseline.
            if not owned then Audio.tv={baseline=current,token=lifecycle} end
            local accepted=Audio.write(AH.tv_set,-100.0)
            local after=Audio.number(AH.tv_read)
            if after~=nil then Audio.diag.tv_volume=after end
            Audio.diag.tv_state=not accepted and "Volume write failed"
                or after==-100.0 and "Volume set to -100" or "Volume not confirmed at -100"
        elseif current<-100.0 then
            -- A quieter external setting is not raised to our mute level.
            Audio.tv=nil;Audio.diag.tv_state="Quieter volume preserved"
        else
            Audio.diag.tv_state=owned and "Owned volume at -100" or "Existing volume at -100"
        end
    elseif owned then
        if current~=-100.0 then
            Audio.tv=nil;Audio.diag.tv_state="External volume preserved"
        elseif Audio.write(AH.tv_set,owned.baseline) then
            local after=Audio.number(AH.tv_read)
            if after~=nil then Audio.diag.tv_volume=after end
            if after==owned.baseline then Audio.tv=nil;Audio.diag.tv_state="Volume restored"
            else Audio.diag.tv_state="Volume restoration pending" end
        else Audio.diag.tv_state="Volume restoration pending" end
    end
end
function Audio.local_ped()
    local ok,value=pcall(invoke_int,H.PLAYER_PED_ID)
    if ok and value>0 then return value end
    Audio.failure("local-ped",value)
end
-- Each extra mixer scene is acquired only from a readable inactive baseline.
-- Existing game/other-script scenes are neither borrowed nor reconfigured.
function Audio.named_scene_tick(name,enabled,status_key,apply)
    local owned=Audio.scenes[name]==true
    if not enabled and not owned then return end
    local active=Audio.read(AH.active,name)
    Audio.diag[status_key]=active==true and (owned and "Owned active locally" or "Preexisting active; not owned")
        or active==false and "Inactive" or "Unreadable"
    if enabled then
        if active==false then
            Audio.scenes[name]=true -- Release debt precedes a potentially partial start.
            local accepted=Audio.read(AH.start,name)
            active=Audio.read(AH.active,name)
            Audio.diag[status_key]=active==true and "Local active; owned start requested"
                or accepted==false and "Start rejected; cleanup retained" or "Start unconfirmed"
        end
        if active==true and Audio.scenes[name] and apply~=nil then
            -- Only a scene acquired by CScript can receive its apply variable.
            -- Acceptance is NOT proof that audio is inaudible on the client.
            local accepted=Audio.write(AH.scene_variable,name,"apply",apply)
            Audio.diag[status_key.."_variable"]=accepted and "NATIVE_ACCEPTED_EFFECT_UNVERIFIED"
                or "REQUEST_REJECTED"
        end
    elseif owned then
        if active==false then Audio.scenes[name]=nil
        elseif active==true and Audio.write(AH.stop,name) and Audio.read(AH.active,name)==false then
            Audio.scenes[name]=nil;Audio.diag[status_key]="Released"
        end
    end
end
function Audio.groups_tick(environment,music)
    Audio.named_scene_tick("FBI_HEIST_H5_MUTE_AMBIENCE_SCENE",environment,"environment_state")
    Audio.named_scene_tick("MUTES_RADIO_SCENE",music,"radio_state")
    Audio.named_scene_tick("MP_POSITIONED_RADIO_MUTE_SCENE",music,"positioned_radio_state",1.0)
    if not music then
        Audio.diag.music_state="Not requested"
        Audio.diag.music_general_playing=nil
        Audio.diag.music_scripted_playing=nil
        return
    end
    -- General and scripted music have DISTINCT native status reads. Relying on
    -- AUDIO_IS_MUSIC_PLAYING alone misses scripted music in some game states.
    local playing=Audio.read(AH.music_playing)
    local scripted=Audio.read(AH.scripted_music_playing)
    Audio.diag.music_general_playing=playing
    Audio.diag.music_scripted_playing=scripted
    if playing~=true and scripted~=true then
        Audio.diag.music_state=playing==false and scripted==false
            and "Not playing (both native flags clear)" or "Status partly unreadable"
        return
    end
    -- GLOBAL_KILL_MUSIC is a one-shot score request. It is not a blanket
    -- mute for vehicle engines, weather/wind sounds or player dialogue.
    Audio.diag.music_stop_requests=math.min(100000,(Audio.diag.music_stop_requests or 0)+1)
    local accepted=Audio.read(AH.music_event,"GLOBAL_KILL_MUSIC")
    local after_general=Audio.read(AH.music_playing)
    local after_scripted=Audio.read(AH.scripted_music_playing)
    Audio.diag.music_general_playing=after_general
    Audio.diag.music_scripted_playing=after_scripted
    if after_general==false and after_scripted==false then
        Audio.diag.music_state="Stopped (both native flags clear locally)"
    elseif accepted==true then
        Audio.diag.music_state="Stop requested; playback unverified"
    else
        Audio.diag.music_state="Stop request unconfirmed"
    end
end
function Audio.global_tick(voices,sirens,environment,music)
    -- SET_AUDIO_FLAG has no getter. It cannot verify actual audible silence.
    -- Keep release debt if a native reports rejection after partial mutation.
    -- FrontendRadioDisabled is a documented audio flag, extending Music's
    -- frontend radio coverage without mutating weather/wind or vehicle radios.
    local wanted={DisableBarks=voices,PoliceScannerDisabled=sirens,
        WantedMusicDisabled=music,DisableFlightMusic=music,
        FrontendRadioDisabled=music}
    for flag,enabled in pairs(wanted)do
        local owned=Audio.global_flags[flag]==true
        if enabled or owned then
            if enabled then Audio.global_flags[flag]=true end
            local accepted=Audio.write(AH.flag,flag,enabled==true)
            Audio.diag.audio_flag_requests=math.min(100000,(Audio.diag.audio_flag_requests or 0)+1)
            if not accepted then
                Audio.diag.audio_flag_rejections=math.min(100000,
                    (Audio.diag.audio_flag_rejections or 0)+1)
            else
                Audio.global_flags[flag]=enabled and true or nil
            end
            Audio.diag.audio_flag_status[flag]=accepted
                and (enabled and "NATIVE_ACCEPTED_EFFECT_UNVERIFIED" or "RELEASE_ACCEPTED")
                or (enabled and "REQUEST_REJECTED_RESTORE_PENDING" or "RELEASE_REJECTED")
        end
    end
end
function Audio.int(hash,...)
    local ok,value=pcall(invoke_int,hash,...)
    if ok and type(value)=="number" and value==value and math.abs(value)<math.huge and value%1==0 then return value end
    Audio.failure("int:"..tostring(hash),value)
end
function Audio.player_vehicle_snapshot()
    -- Sample players once per audio frame, not once per vehicle. This uses only
    -- player/current-vehicle reads; seat lookups can materialize ambient occupants.
    local vehicles,seen,complete={},{},true
    local function include(handle)
        if type(handle)~="number" or handle~=handle or math.abs(handle)==math.huge or handle<0 or handle%1~=0 then return false end
        if handle==0 then return false end -- An active slot without a ready ped has unknown occupancy.
        if seen[handle] then return true end
        if Audio.read(AH.player,handle)~=true then return false end
        local vehicle=Audio.int(AH.ped_vehicle,handle,false)
        if vehicle==nil or vehicle<0 then
            Audio.failure("player-vehicle",vehicle);return false
        end
        seen[handle]=true
        if vehicle>0 then vehicles[vehicle]=true end
        return true
    end
    if not include(Audio.int(H.PLAYER_PED_ID)) then complete=false end
    for slot=0,31 do
        local active=Audio.read(AH.player_active,slot)
        if active==nil then complete=false end
        if active then
            local ped=Audio.int(AH.player_ped,slot)
            if not include(ped) then Audio.failure("player-ped",ped);complete=false end
        end
    end
    -- A later unknown slot must not discard a positive player-vehicle exclusion.
    return vehicles,complete
end
function Audio.occupant_snapshot()
    -- This is a bounded candidate set, never a claim to have enumerated the world.
    -- Complete per-vehicle counts and fresh members are required at each mute.
    local pool=module_context and module_context.Raw and module_context.Raw.PoolMgr or PoolMgr
    local result={available=false,vehicles={}}
    local retained=Audio.occupant_candidates or {}
    local candidates,seen,addresses={},{},{}
    Audio.occupant_candidates=candidates
    Audio.diag.occupant_pool_reads=0;Audio.diag.occupant_candidates=0
    if not pool or type(pool.GetMaxPedCount)~="function" or type(pool.GetPed)~="function" then return result end
    local ok,capacity=pcall(pool.GetMaxPedCount)
    if not ok or type(capacity)~="number" or capacity~=capacity or capacity<1 or capacity>65536 or capacity%1~=0 then return result end
    result.available=true
    local function group(vehicle)
        local row=result.vehicles[vehicle]
        if not row then row={members={}};result.vehicles[vehicle]=row end
        return row
    end
    local function visit(handle)
        if type(handle)~="number" or handle<=0 or handle%1~=0 or seen[handle] or #candidates>=128 then return end
        seen[handle]=true
        local p=Audio.identity(handle,1)
        if not p then return end
        local vehicle=Audio.int(AH.ped_vehicle,handle,false)
        if vehicle==nil or vehicle<=0 then return end
        local row=group(vehicle)
        local prior=addresses[p.address]
        if prior then
            -- Distinct handles resolving to one address cannot count twice.
            group(prior.vehicle).unknown=true;row.unknown=true;return
        end
        p.vehicle=vehicle;addresses[p.address]=p
        local player=Audio.read(AH.player,handle)
        if player==true then row.player=true;return end
        if player~=false or Audio.same(p)~=true then row.unknown=true;return end
        row.members[#row.members+1]=p;candidates[#candidates+1]=p
    end
    -- Keep only candidates for existing leases, and re-read their current birth
    -- and vehicle. This prevents a rotating pool slice from dropping live proofs.
    for _,p in ipairs(retained) do
        if Audio.vehicles[p.vehicle] then visit(p.handle) end
    end
    local first=(Audio.occupant_cursor or 0)%capacity
    for i=0,math.min(32,capacity)-1 do
        Audio.diag.occupant_pool_reads=Audio.diag.occupant_pool_reads+1
        local got,handle=pcall(pool.GetPed,(first+i)%capacity)
        if got then visit(handle) end
    end
    Audio.occupant_cursor=(first+math.min(32,capacity))%capacity
    Audio.diag.occupant_candidates=#candidates
    return result
end
function Audio.npc_from_occupants(vehicle)
    local census=Audio.occupancy_census
    if not census or not census.available or Audio.same(vehicle)~=true then return nil end
    local row=census.vehicles[vehicle.handle]
    if row and row.player then return false end
    if row and row.unknown then return nil end
    local members=row and row.members or {}
    local before=Audio.int(AH.vehicle_occupants,vehicle.handle,true,true)
    if before==nil or before<0 or before>128 or before~=#members then return nil end
    local function current_members()
        for _,p in ipairs(members) do
            if Audio.same(p)~=true or Audio.read(AH.player,p.handle)~=false
                or Audio.int(AH.ped_vehicle,p.handle,false)~=vehicle.handle then return false end
        end
        return true
    end
    if not current_members() then return nil end
    local after=Audio.int(AH.vehicle_occupants,vehicle.handle,true,true)
    -- A stable total alone is insufficient: an NPC can leave as a player enters.
    if after~=before or not current_members() or Audio.same(vehicle)~=true then return nil end
    return true
end
function Audio.npc_vehicle(p)
    if Audio.stopping or Audio.reset or not Audio.enabled("mute_active_sirens") then return nil end
    if Audio.player_vehicles and Audio.player_vehicles[p.handle] then return false end
    if Audio.players_complete then return true end
    return Audio.npc_from_occupants(p)
end

function Audio.ringtone_tick()
    local handle=Audio.local_ped()
    local p=handle and Audio.identity(handle,1)
    if not p or Audio.read(AH.player,handle)~=true then return end
    local ringing=Audio.read(AH.ringtone_read,handle)
    Audio.diag.ringtone_state=ringing==true and "Playing" or ringing==false and "Not playing" or "Unreadable"
    -- Recheck both identity and current local-player handle. Never enumerate or
    -- target another player's or an ambient ped's ringtone, and never end a call.
    if ringing==true and Audio.same(p)==true and Audio.local_ped()==handle then
        local accepted=Audio.write(AH.ringtone_stop,handle)
        -- STOP_PED_RINGTONE is a void request. Only a fresh native read from
        -- the SAME local ped can confirm the ringtone actually stopped.
        if Audio.same(p)~=true or Audio.local_ped()~=handle then
            Audio.diag.ringtone_state="Local ped changed; stop result unverified"
            return
        end
        local after=Audio.read(AH.ringtone_read,handle)
        Audio.diag.ringtone_state=after==false and "Stopped (local native readback)"
            or accepted and "Stop requested; ringtone still active or unknown"
            or "Stop request rejected or unavailable"
    end
end
function Audio.identity(handle,kind)
    local g=module_context and module_context.Raw and module_context.Raw.GTA or GTA
    if not g or type(g.HandleToPointer)~="function" then Audio.failure("identity","GTA.HandleToPointer unavailable");return nil end
    if type(handle)~="number" or handle<=0 or handle%1~=0 then return false end
    local ok,value=pcall(function()
        if not invoke_bool(H.DOES_ENTITY_EXIST,handle) or invoke_int(AH.entity_type,handle)~=kind then return false end
        local ptr=g.HandleToPointer(handle)
        local address=ptr:GetAddress()
        if type(address)~="number" or address<=65535 or address>=0x800000000000 or address%1~=0 then return nil end
        local model=invoke_int(H.GET_ENTITY_MODEL,handle)
        if model==0 then return nil end
        -- Pool entries already originate as handles. Re-read the handle mapping;
        -- PointerToHandle can reverse-scan the entire pool on each identity check.
        if g.HandleToPointer(handle):GetAddress()~=address
            or invoke_int(H.GET_ENTITY_MODEL,handle)~=model then return nil end
        return {handle=handle,address=address,model=model,kind=kind,token=lifecycle}
    end)
    if ok then
        if value==nil then Audio.failure("identity","Address/model unavailable or changed during read") end
        return value
    end
    Audio.failure("identity",value)
    return nil
end
function Audio.same(p)
    if p.token~=lifecycle then return false end
