            local current=Audio.read(AH.speech_read,handle)
            if current==false then entries[handle]=nil
            elseif current==true and Audio.same(p) and Audio.write(AH.speech_set,handle,false)
                and Audio.same(p) and Audio.read(AH.speech_read,handle)==false then entries[handle]=nil end
        elseif same==true then
            -- Only originally audible sirens are owned. No inactive-mute inference.
            -- Setter has no flag getter: accepted reset is the available release contract.
            if Audio.same(p) and Audio.write(AH.siren_set,handle,false) then entries[handle]=nil end
