    local traffic=enabled and Audio.enabled("mute_traffic_ambience")
    local voices=enabled and Audio.enabled("mute_npc_voices")
    local sirens=enabled and Audio.enabled("mute_active_sirens")
    local tv=enabled and Audio.enabled("mute_tv_audio")
    local ringtone=enabled and Audio.enabled("mute_phone_ringtone")
    local environment=enabled and Audio.enabled("mute_environment_ambience")
    local music=enabled and Audio.enabled("mute_music")
    Audio.global_tick(voices,sirens,environment,music)
    Audio.player_vehicles=nil;Audio.players_complete=false;Audio.occupancy_census=nil
    if not traffic and not voices and not sirens and not tv and not ringtone and not environment and not music
        and Audio.clean() then Audio.occupant_candidates={};Audio.reset=false;return end
    local now=now_ms()
    local discovery_due=force or now>=Audio.next_scan
    -- A fresh player census is needed only before possible vehicle work.
    -- Owned sirens still get a new census every frame; an empty ledger waits
    -- for the next discovery slice instead of enumerating 32 slots per frame.
    if sirens and (discovery_due or next(Audio.vehicles)~=nil) then
        Audio.player_vehicles,Audio.players_complete=Audio.player_vehicle_snapshot()
        if not Audio.players_complete then Audio.occupancy_census=Audio.occupant_snapshot()
        else Audio.occupant_candidates={} end
    else Audio.occupant_candidates={} end
