    Audio.tv_tick(tv)
    if ringtone then Audio.ringtone_tick() end
    if not discovery_due then return end
    Audio.frame_handles=nil
    Audio.next_scan=now+125
    Audio.diag.scans=Audio.diag.scans+1;Audio.diag.last_scan_ms=now
    Audio.groups_tick(environment,music)
