        local active=Audio.read(AH.active,Audio.scene)
        Audio.diag.scene_state=active==true and "Active" or active==false and "Inactive" or "Unreadable"
        if traffic then
            if active==false then
                Audio.scene_owned=true -- Keep release debt even if the setter partially fails.
                local accepted=Audio.read(AH.start,Audio.scene)
                local after=Audio.read(AH.active,Audio.scene)
                Audio.diag.scene_start=accepted==true and "Accepted" or accepted==false and "Rejected" or "Unreadable"
                Audio.diag.scene_state=after==true and "Active" or after==false and "Inactive" or "Unreadable"
