function Audio.frame_requested()
    return not Audio.clean() or Audio.diag.probe_pending
        or Audio.enabled("mute_traffic_ambience") or Audio.enabled("mute_npc_voices")
        or Audio.enabled("mute_active_sirens") or Audio.enabled("mute_tv_audio")
        or Audio.enabled("mute_phone_ringtone") or Audio.enabled("mute_environment_ambience")
        or Audio.enabled("mute_music")
end
function Audio.frame_tick()
    local serviced=Audio.tick(false)
    if serviced or Audio.stopping or Audio.reset then return end
    -- Reassert a bounded rotating slice between discovery scans. Recreated
    -- handles are checked again, and only acquired flags get persistent writes.
    Audio.frame_cursor=Audio.frame_cursor or {Ped=0,Vehicle=0}
    for _,spec in ipairs({{Audio.peds,"Ped","mute_npc_voices"},
                          {Audio.vehicles,"Vehicle","mute_active_sirens"}}) do
        if Audio.enabled(spec[3]) then
            -- Ledger membership changes during discovery or a siren release.
            -- Retain one stable rotation between those events, without sorting
            -- and allocating both handle arrays on every rendered frame.
            Audio.frame_handles=Audio.frame_handles or {}
            local cached=Audio.frame_handles[spec[2]]
            if not cached or cached.entries~=spec[1] then
                cached={entries=spec[1],handles={}}
                for handle in pairs(spec[1]) do cached.handles[#cached.handles+1]=handle end
                Audio.frame_handles[spec[2]]=cached
            end
            local handles=cached.handles
            local count=#handles
            if count>0 then
                local first=Audio.frame_cursor[spec[2]]%count
                local visited=math.min(16,count)
                for i=0,visited-1 do
                    local handle=handles[(first+i)%count+1]
                    local p=spec[1][handle]
                    if p and Audio.same(p)==true and Audio.near(p) then
                        if spec[2]=="Ped" then Audio.stop_speech(p)
                        else Audio.service_siren(p) end
                    end
