        and r("ReadUShort",base+pe+4)==0x8664 and r("ReadUShort",base+pe+24)==0x20B,"Camera PE identity mismatch")
    assert(r("ReadUInt",base+pe+8)==1789157136 and r("ReadUInt",base+pe+24+56)==0x5B45200,
        "Camera backend does not support this Enhanced executable build")
