        local a,b=r("ReadLong",vft),r("ReadLong",vft+16)
        assert(p.matches(a,"48 8D 05 ? ? ? ? C3")and p.matches(b,"8B 05 ? ? ? ? C3"),"Camera RTTI getter shape mismatch")
        local descriptor=a+7+r("ReadInt",a+3);local key=b+6+r("ReadInt",b+2)
        assert(key==descriptor+8 and p.data(descriptor,16),"Camera RTTI descriptor mismatch")
        return r("ReadUInt",key)
    end
    local parserHit=m.Scan("48 8B 05 ? ? ? ? 44 0F B6 B8 ? ? ? ? 4C 8B 72","GTA5_Enhanced.exe")
    assert(p.matches(parserHit,"48 8B 05 ? ? ? ? 44 0F B6 B8 ? ? ? ? 4C 8B 72"),"Gen9 camera parser locator unavailable")
    local slot=parserHit+7+r("ReadInt",parserHit+3)
