        if node==0 then break end
        assert(p.pointer(node)and not seen[node],"Camera parser map identity invalid");seen[node]=true
        if r("ReadUInt",node)==0xE4BE8CA5 then p.parser=r("ReadLong",node+8);break end
        node=r("ReadLong",node+16)
    end
    assert(p.pointer(p.parser)and r("ReadUInt",p.parser+8)==0xE4BE8CA5 and r("ReadLong",p.parser+32)==1664,
        "Current shooter metadata parser identity mismatch")
    local fields={};local parent=p.parser
    for _,key in ipairs({0xE4BE8CA5,0xA8972556,0x140F27A2,0xA387B8D5,0x680CB468})do
        assert(p.pointer(parent)and r("ReadUInt",parent+8)==key,"Camera parser inheritance mismatch")
        local size=r("ReadLong",parent+32);local arr,num,cap=r("ReadLong",parent+48),r("ReadUShort",parent+56),r("ReadUShort",parent+58)
        assert(size>=16 and size<=0x10000 and num<=256 and num<=cap and cap<=512 and(num==0 or p.pointer(arr)),"Camera parser fields invalid")
        for i=0,num-1 do
            local member=r("ReadLong",arr+i*8);assert(p.pointer(member),"Camera member pointer invalid")
            local d=r("ReadLong",member+8);assert(p.data(d,40),"Camera member descriptor outside module")
            local name=r("ReadUInt",d)
            if name==0x1E5CB5D3 or name==0xFDFC7009 or name==0xACEC22BE then
                fields[name]={offset=r("ReadLong",d+8),kind=r("ReadUByte",d+16),descriptor=d}
            end
        end
        parent=r("ReadLong",parent+16)
    end
    local low,high,name=fields[0x1E5CB5D3],fields[0xFDFC7009],fields[0xACEC22BE]
    assert(low and low.kind==7 and low.offset==84 and high and high.kind==7 and high.offset==88
        and name and name.kind==11 and name.offset==8,"Current camera Min/Max/Name schema mismatch")
    assert(r("ReadFloat",low.descriptor+32)==-85 and r("ReadFloat",high.descriptor+32)==60,"Camera schema defaults mismatch")
    p.min_offset,p.max_offset,p.name_offset=low.offset,high.offset,name.offset
    local ctor=r("ReadLong",p.parser+0x60);seen={}
    for _=1,4 do
        assert(p.inside(ctor,16,".text")and not seen[ctor],"Camera constructor code unavailable");seen[ctor]=true
        if r("ReadUByte",ctor)~=0xE9 then break end
        ctor=ctor+5+r("ReadInt",ctor+1)
    end
    assert(p.inside(ctor,1024,".text"),"Camera constructor exceeds code bounds")
    for i=0,1014 do
        local at=ctor+i
        if r("ReadUByte",at)==0x48 and r("ReadUByte",at+1)==0x8D then
            local a,b=r("ReadUByte",at+2),r("ReadUByte",at+9)
            if a&0xC7==5 and r("ReadUByte",at+7)==0x48 and r("ReadUByte",at+8)==0x89 and b&0xC0==0 and a&0x38==b&0x38 then
                local vft=at+7+r("ReadInt",at+3)
                if p.inside(vft,0x40,".rdata")then
                    local getter=r("ReadLong",vft+0x38)
                    if p.matches(getter,"48 8B 05 ? ? ? ? C3")then
                        local cache=getter+7+r("ReadInt",getter+3)
                        if p.data(cache,8)and r("ReadLong",cache)==p.parser then
                            assert(not p.metadata_vft or p.metadata_vft==vft,"Camera constructor type is ambiguous")
                            p.metadata_vft,p.parser_cache=vft,cache
                        end
                    end
                end
            end
        end
    end
    assert(p.metadata_vft,"Current shooter metadata vtable not proved")
    local hit=m.Scan("88 05 ? ? ? ? E8 ? ? ? ? 88 05 ? ? ? ? E8","GTA5_Enhanced.exe")
    assert(p.matches(hit+17,"E8 ? ? ? ?"),"Enhanced gameplay-director locator unavailable")
    local getter=hit+22+r("ReadInt",hit+18)
    assert(p.matches(getter,"48 8B 05 ? ? ? ? C3"),"Enhanced gameplay-director getter mismatch")
    p.director_slot=getter+7+r("ReadInt",getter+3);assert(p.data(p.director_slot,8),"Director slot outside module data")
    local director=r("ReadLong",p.director_slot);assert(p.pointer(director),"Gameplay director unavailable")
    local vft=r("ReadLong",director);assert(p.rtti(vft)==0x3E9ED27F,"Gameplay director RTTI mismatch")
    local selected=r("ReadLong",vft+9*8)
    assert(p.matches(selected,"41 57 41 56 41 55 41 54 56 57 55 53 48 83 EC 58 0F 29 74 24 40 4C 89 C7 49 89 D4 49 89 CD 4C 8B 72 40 41 0F B6 40 28 3C 03 75 ? 48 89 F9 E8 ? ? ? ? 84 C0 74 ? 49 8B 8D ? ? ? ? 48 85"),
        "Current selected-camera instruction identity mismatch")
    p.selected_offset=r("ReadInt",selected+58)
    assert(p.selected_offset>=8 and p.selected_offset<=0x1000 and p.selected_offset%8==0,"Selected-camera field invalid")
    function p.resource(address,nameHash)
        return p.pointer(address)and r("ReadLong",address)==p.metadata_vft
            and r("ReadLong",p.parser_cache)==p.parser and r("ReadUInt",p.parser+8)==0xE4BE8CA5
            and(nameHash==nil or r("ReadUInt",address+p.name_offset)==nameHash)
    end
    function p.target()
        local d=r("ReadLong",p.director_slot)
        if not p.pointer(d)or p.rtti(r("ReadLong",d))~=0x3E9ED27F then return nil end
        local cam=r("ReadLong",d+p.selected_offset)
        if not p.pointer(cam)then return nil end
        local cv=r("ReadLong",cam)
        if p.rtti(cv)~=0x5D1804BC then return nil end
        local fn=r("ReadLong",cv+33*8)
        if not p.matches(fn,"48 8B 81 ? ? ? ? 0F B6 40 50 C3")then return nil end
        local offset=r("ReadInt",fn+3)
        if offset<8 or offset>0x1000 or offset%8~=0 then return nil end
        local address=r("ReadLong",cam+offset)
        if not p.resource(address)then return nil end
        return address,r("ReadUInt",address+p.name_offset)
    end
    return p
end
function FirstPersonPitch.release_now()
    local l=FirstPersonPitch.lease
    if not l then FirstPersonPitch.restore_pending=false;return true end
    local ok,same=pcall(l.profile.resource,l.address,l.name)
    if not ok then FirstPersonPitch.restore_pending=true;FirstPersonPitch.status("RESTORE_PENDING","Camera resource identity is temporarily unreadable.");return false end
    if not same then
        FirstPersonPitch.lease=nil;FirstPersonPitch.restore_pending=false
        FirstPersonPitch.status("IDENTITY_CHANGED","Camera resource was replaced; stale restoration was skipped.");return true
    end
    local pending=false
    for _,f in ipairs(l.fields)do
        if f.touched then
            local read_ok,value=pcall(l.profile.read,"ReadFloat",f.address)
            if not read_ok then pending=true
            elseif value==f.original then f.touched=false
            elseif value~=f.wanted then f.touched=false;l.external=true
            else
                -- A writer may mutate and then throw. Readback of the captured
                -- original, rather than its return value, settles this debt.
                pcall(l.profile.memory.WriteFloat,f.address,f.original)
                local verified,current=pcall(l.profile.read,"ReadFloat",f.address)
                local identity_ok,identity=pcall(l.profile.resource,l.address,l.name)
                if verified and current==f.original and identity_ok and identity then f.touched=false else pending=true end
            end
        end
    end
    FirstPersonPitch.restore_pending=pending
    if not pending then FirstPersonPitch.lease=nil end
    FirstPersonPitch.status(pending and "RESTORE_PENDING"or "OFF",pending and "Camera range restoration remains pending."
        or(l.external and "Owned limits restored; external camera changes were preserved."or "Captured camera limits restored."))
    return not pending
end
function FirstPersonPitch.Release()
    FirstPersonPitch.release_requested=true
    if FirstPersonPitch.busy then return false end
    FirstPersonPitch.busy=true
    local ok,result=pcall(FirstPersonPitch.release_now)
    FirstPersonPitch.busy=false;FirstPersonPitch.release_requested=false
    if not ok then
        FirstPersonPitch.restore_pending=FirstPersonPitch.lease~=nil
        FirstPersonPitch.status("RESTORE_PENDING",tostring(result));return false
    end
    State.first_person_pitch=FirstPersonPitch.Snapshot()
    return result
end
function FirstPersonPitch.Tick(wanted,eligible,permit)
    if FirstPersonPitch.busy then return false end
    if not wanted then
        local clean=FirstPersonPitch.Release();FirstPersonPitch.blocked=false;FirstPersonPitch.attempted=false;FirstPersonPitch.profile=nil
        return clean
    end
    local function allowed()
        return eligible==true and(not permit or permit()==true)and FirstPersonPitch.domain_allowed()
    end
    if not allowed()then return FirstPersonPitch.Release()end
    if FirstPersonPitch.blocked then return false end
    FirstPersonPitch.busy=true
    local ok,why=pcall(function()
        if not FirstPersonPitch.profile then
            assert(not FirstPersonPitch.attempted,"Camera backend could not be validated; switch off and on to retry")
            FirstPersonPitch.attempted=true;FirstPersonPitch.profile=FirstPersonPitch.discover()
        end
        local p=FirstPersonPitch.profile
        local address,name=p.target()
        local l=FirstPersonPitch.lease
        if l and(address~=l.address or name~=l.name)then
            assert(FirstPersonPitch.release_now(),"Old camera range restoration remains pending");l=nil
        end
        if not address then FirstPersonPitch.status("WAITING","No supported first-person shooter camera is active.");return end
        if l then
            for _,f in ipairs(l.fields)do
                if p.read("ReadFloat",f.address)~=f.wanted then
                    FirstPersonPitch.blocked=true;FirstPersonPitch.release_now()
                    FirstPersonPitch.status("EXTERNAL_CHANGE","Camera limits changed externally; switch this feature off and on to retry.");return
                end
            end
            return
        end
        assert(allowed(),"Camera request was revoked before acquisition")
        local low,high=p.read("ReadFloat",address+p.min_offset),p.read("ReadFloat",address+p.max_offset)
        assert(low>=-180 and high<=180 and low<high,"Loaded camera pitch range is invalid")
        l={profile=p,address=address,name=name,fields={
            {address=address+p.min_offset,original=low,wanted=math.min(low,-90.0)},
            {address=address+p.max_offset,original=high,wanted=math.max(high,90.0)}}}
        FirstPersonPitch.lease=l
        for _,f in ipairs(l.fields)do
            assert(allowed()and p.target()==address and p.resource(address,name),"Camera request or selected resource changed")
            if f.original~=f.wanted then
                local service=module_context and module_context.Memory
                if service and type(service.OwnerOf)=="function"then assert(service.OwnerOf(f.address)==nil,"Camera field is owned by another CScript writer")end
                f.touched=true
                local wrote,result=pcall(p.memory.WriteFloat,f.address,f.wanted)
                assert(wrote and result~=false,"Camera pitch write was rejected")
                assert(p.resource(address,name)and p.read("ReadFloat",f.address)==f.wanted,"Camera pitch write readback mismatch")
                assert(allowed(),"Camera request was revoked during acquisition")
            end
        end
        FirstPersonPitch.status("ACTIVE","Normal first-person metadata pitch limits permit straight up and down.")
    end)
    if not ok then
        FirstPersonPitch.blocked=true
        local restored=FirstPersonPitch.release_now()
        if restored then FirstPersonPitch.status("UNAVAILABLE",tostring(why))end
    end
    FirstPersonPitch.busy=false
    if FirstPersonPitch.release_requested then FirstPersonPitch.Release()end
    State.first_person_pitch=FirstPersonPitch.Snapshot()
    return ok
end

local function restore_world_now()
    ClearArea.Cancel("World reset")
    FirstPersonPitch.Release()
    Audio.reset=true;Audio.tick(true)
    entry_cancel("World reset",true)
    property_entry_cancel("World reset")
    if State.cutscene_skip.native_pending then
        cutscene_cancel(State.cutscene_skip, "World reset")
    end
    cancel_entry_suppression("world restore")
    release_clock()
    release_weather()
    local player=module_context.CScript.Player
    if player and player.SetWorldAggression then player.SetWorldAggression(false) end
    set_toggle("aggressive_world",false)
    -- World never owns global radar, wind, artificial lights or camera shake.
    -- A normal reset must not change another script's settings/effects.
end

local function restore_world()
    cutscene_request_epoch = cutscene_request_epoch + 1
    -- This bridge performs OS memory cleanup, not GTA natives, so restoration
    -- also remains possible when the gameplay domain has been stopped.
    restore_fps_unlock()
    if not current_callback(lifecycle) or lifecycle.failed == true then return false end
    -- Revoke all earlier requests before accepting a new cleanup request.
    lifecycle.pending = { restore_world = true }
    State.weather_override = nil
    set_toggle("freeze_clock", false)
    set_toggle("first_person_pitch", false)
    set_toggle("disable_tips_notifications", false)
    set_toggle("mute_traffic_ambience",false)
    set_toggle("mute_npc_voices",false)
    set_toggle("mute_active_sirens",false)
    set_toggle("mute_tv_audio",false)
    set_toggle("mute_phone_ringtone",false)
    set_toggle("mute_environment_ambience",false)
    set_toggle("mute_music",false)
    return true
end

-- Unlike RestoreWorld/PanicReset, a session change is not a user reset.
-- Invalidate old presentation work while preserving current desired settings
-- and the latest queued FPS command, including an explicit OFF not yet drained.
-- No native or patch write is performed by this notification callback.
local function on_session_change()
    ClearArea.Cancel("Online session changed")
    cutscene_request_epoch = cutscene_request_epoch + 1
    if not current_callback(lifecycle) or lifecycle.failed == true then return false end
    local fps_command = lifecycle.pending.unlock_fps
    lifecycle.pending = {
        restore_world = true,
        reset_cutscene_skip = true,
        unlock_fps = fps_command,
    }
    -- Clock input is re-read after cleanup on the next gameplay frame. Weather
    -- is re-applied by FastTick from State.weather_override, not a stale copy.
    return true
end

local function drain_commands()
    local commands = lifecycle.pending
    lifecycle.pending = {}
    if commands.audio_probe then Audio.diag.probe_pending=true end
    if commands.unlock_fps ~= nil then
        local service = module_context and module_context.FPSLimiter
        if service and type(service.Request) == "function" then
            service.Request(commands.unlock_fps == true)
        else
            sync_fps_toggle(false)
        end
    end
    if commands.aggressive_world~=nil then
        local player=module_context.CScript.Player
        if not player or not player.SetWorldAggression or not player.SetWorldAggression(commands.aggressive_world) then
            set_toggle("aggressive_world",false)
        end
    end
    if commands.restore_world then restore_world_now() end
    if commands.reset_cutscene_skip then
        cancel_entry_suppression("feature changed")
        property_entry_cancel("feature changed")
        reset_cutscene_skip_tracking()
    end
    if commands.clock ~= nil then
        if commands.clock == false then release_clock()
        else freeze_clock(wanted_clock_hour()) end
    end
    if commands.clock_time ~= nil then
        invoke_void(H.SET_CLOCK_TIME, commands.clock_time, 0, 0)
        if is_on("freeze_clock") then freeze_clock(commands.clock_time) end
    end
    if commands.weather ~= nil then
        if commands.weather == false then
            release_weather()
        else
            lifecycle.owned.weather = true
            invoke_void(H.SET_OVERRIDE_WEATHER, commands.weather)
        end
    end
    if commands.stop_visual_effects then stop_visual_effects_now() end
    if commands.clear_area then
        -- A new press replaces the current pass, including deferred checks.
        -- The single gameplay owner cancels before resetting pool cursors;
        -- no two cleanup passes can mutate entities simultaneously.
        if ClearArea.Requested() then ClearArea.Cancel("restarted") end
        local ok, why = ClearArea.Start()
        if not ok then
            log_entry("Clear Area unavailable: " .. tostring(why))
        end
    end
end

local function register_features()
    add_toggle("mute_traffic_ambience", "Mute Traffic Ambience", "Mutes background traffic ambience; nearby engines may remain audible.", false)
    add_toggle("mute_npc_voices", "Mute NPC Voices", "Blocks new ambient NPC barks and mutes current nearby NPC speech.", false)
    add_toggle("mute_active_sirens", "Mute Active NPC Sirens", "Mutes nearby sirens while preserving player-occupied vehicles and emergency lights.", false)
    add_toggle("mute_tv_audio", "Mute TV Audio", "Mutes in-game TV audio.", false)
    add_toggle("mute_phone_ringtone", "Silence Phone Ringtone", "Silences ringing from your phone.", false)
    add_toggle("mute_environment_ambience", "Mute Environment Ambience", "Reduces background environmental ambience without changing weather or player sound settings.", false)
    add_toggle("mute_music", "Mute Music", "Mutes radio and stops scripted music locally. Player speech and sound effects are preserved.", false)
    add_toggle("disable_tips_notifications", "Disable Tips Notifications",
        "Hides standard and floating help/tutorial tips. Keeps kill feed, player notifications, subtitles and radar visible.", false)
    add_toggle("first_person_pitch", "First Person Camera Limits",
        "Expands first-person pitch and heading limits, including aiming and scopes.", false)
    add_toggle("unlock_fps", "Unlock FPS",
        "Disables three Enhanced audio limits. The engine ceiling, VSync and driver limits still apply.",
        false, function(feature)
            if started and not syncing_fps_toggle then queue_command("unlock_fps", feature:IsToggled() == true) end
        end)
    add_toggle("low_traffic", "Suppress Traffic Spawns", "Stops new traffic and parked vehicles from spawning nearby.", false)
    add_toggle("aggressive_world", "Aggressive NPCs", "Makes nearby NPCs fight. Turn off selected-player aggression first.", false,
        function() queue_command("aggressive_world",is_on("aggressive_world")) end)
    add_toggle("low_peds", "Suppress Ambient Spawns", "Stops new ambient pedestrians from spawning nearby.", false)
    add_button("world_clear_area", "Clear Area",
        "Clears eligible streamed vehicles, objects and NPCs with bounded retries. Preserves players and vehicles carrying players; reports remaining entities.", function()
            queue_command("clear_area", true)
        end)
    add_toggle("freeze_clock", "Freeze Local Clock", "Freezes the local world clock.", false,
        function(feature)
            if feature:IsToggled() then
                local hour = math.max(0, math.min(23, slider_int("clock_hour", 22)))
                queue_command("clock", hour)
            else
                queue_command("clock", false)
            end
        end)
    add_slider_int("clock_hour", "Frozen Clock Hour", "Hour used by Freeze Local Clock.", 0, 23, 1, 22)
    add_button("world_noon", "Set Local Noon", "Sets the local world clock to noon.", function()
        if F.clock_hour and type(F.clock_hour.SetIntValue) == "function" then pcall(function() F.clock_hour:SetIntValue(12) end) end
        queue_command("clock_time", 12)
        toast("Local time set to noon.")
    end)
    add_button("world_midnight", "Set Local Midnight", "Sets the local world clock to midnight.", function()
        if F.clock_hour and type(F.clock_hour.SetIntValue) == "function" then pcall(function() F.clock_hour:SetIntValue(0) end) end
        queue_command("clock_time", 0)
        toast("Local time set to midnight.")
    end)
    add_toggle("skip_entry_cutscenes", "Skip Cutscenes / Entry Sequences",
        "Skips cutscenes and supported property-entry sequences.",
        false, function(feature)
            cutscene_request_epoch = cutscene_request_epoch + 1
            queue_command("reset_cutscene_skip", true)
            if feature:IsToggled() then
                toast("Cutscene and supported entry skipping enabled.", 2500)
            end
        end)

    add_toggle("disable_decals", "Disable Decal Rendering", "Hides decals.", false)
    add_toggle("suppress_postfx", "Suppress Scripted Post-FX", "Removes screen filters, blur and camera shake.", false,
        function(feature) if feature:IsToggled() then stop_visual_effects() end end)
    add_button("performance_preset", "Apply Performance Preset", "Reduces demanding world and overlay effects.", function()
        set_toggle("low_traffic", true)
        set_toggle("low_peds", true)
        set_toggle("disable_decals", true)
        set_toggle("suppress_postfx", true)
        for _, key in ipairs({ "coords_hud", "vitals_hud", "vehicle_health_hud" }) do
            set_toggle(key, false)
        end
        toast("Local performance preset applied.")
    end)
end

local function first_person_pitch_tick()
    local wanted=not Audio.stopping and is_on("first_person_pitch")
    local function eligible()
        if not invoke_bool(H.IS_GAMEPLAY_CAM_RENDERING)
            or invoke_bool(H.IS_CINEMATIC_CAM_RENDERING)
            or invoke_bool(H.IS_CUTSCENE_ACTIVE) then return false end
        -- Aim may temporarily enter first person while the saved context remains
        -- third person. Otherwise sample the ACTIVE context, not the on-foot
        -- preference, which may differ from the current vehicle camera.
        if not invoke_bool(H.IS_FIRST_PERSON_AIM_CAM_ACTIVE) then
            local context = invoke_int(H.GET_CAM_ACTIVE_VIEW_MODE_CONTEXT)
            if context < 0 or context > 7
                or invoke_int(H.GET_CAM_VIEW_MODE_FOR_CONTEXT, context) ~= 4 then return false end
        end
        return true
    end
    local active=wanted and eligible()
    FirstPersonPitch.Tick(wanted,active,function()
        return not Audio.stopping and is_on("first_person_pitch") and eligible()
    end)
    if not active or Audio.stopping or not is_on("first_person_pitch") then return end
    -- This-update limits expire when disabled, stopped or leaving first person.
    -- Never set a pitch/rotation, consume look input, or alter third-person limits.
    invoke_void(H.SET_FIRST_PERSON_AIM_CAM_RELATIVE_PITCH_LIMITS_THIS_UPDATE, -90.0, 90.0)
    invoke_void(H.SET_FIRST_PERSON_AIM_CAM_RELATIVE_HEADING_LIMITS_THIS_UPDATE, -180.0, 180.0)
    invoke_void(H.BLOCK_FIRST_PERSON_ORIENTATION_RESET_THIS_UPDATE)
end

local Tips={}
function Tips.enabled()
    if Audio.stopping then return false end
    local feature=F["disable_tips_notifications"]
    if not feature or type(feature.IsToggled)~="function" then return false end
    local ok,enabled=pcall(feature.IsToggled,feature)
    if not ok or type(enabled)~="boolean" then return false end
    -- Config restores/native controls can change before their callback arrives.
    -- Read silently: never call Toggle(), show a toast, or flip another control.
    ToggleState.disable_tips_notifications=enabled
    return enabled
end
local function tips_notifications_tick()
    if not Tips.enabled() then return end
    -- Retain GTA's help identity; clearing it can cause scripts to repost tips.
    -- Individual native failure must not disable unrelated world/audio controls.
    pcall(invoke_void,0xD46923FC481CA285) -- HIDE_HELP_TEXT_THIS_FRAME
    for _,component in ipairs({10,11,12}) do
        if Audio.stopping then return end
        pcall(invoke_void,0x6806C51AD12B83B8,component)
    end
    -- HELP_TEXT + two floating-help channels only. No feed/subtitle/radar calls.
end

local function frame_tick()
    if not started then return end
    drain_commands()
    if ClearArea.Requested() then
        ClearArea.Tick()
    end
    -- Audio lives on the existing native frame owner. Discovery stays bounded;
    -- active lines, sirens, phone rings and TV fades get prompt local upkeep.
    Audio.frame_tick()
    tips_notifications_tick()
    -- Slider state is read on the existing native frame, independent of whether
    -- the Cherax widget delays its callback until release. Stable clock upkeep
    -- remains on FastTick; only a changed hour takes this immediate path.
    apply_clock_input()
    first_person_pitch_tick()
    if is_on("skip_entry_cutscenes") or EntrySkip.pending or EntrySkip.cleanup then entry_tick() end
    if is_on("skip_entry_cutscenes") or PropertyEntry.pending then property_entry_tick() end
    local fps = module_context and module_context.FPSLimiter
    if fps and fps_snapshot().busy == true then fps.Tick() end
    if is_on("skip_entry_cutscenes") then cutscene_skip_tick() end
    if is_on("low_peds") then
        invoke_void(H.SET_PED_DENSITY_MULTIPLIER_THIS_FRAME, 0.0)
        invoke_void(H.SET_SCENARIO_PED_DENSITY_MULTIPLIER_THIS_FRAME, 0.0, 0.0)
        invoke_void(H.SET_AMBIENT_PED_RANGE_MULTIPLIER_THIS_FRAME, 0.0)
    end
    if is_on("low_traffic") then
        invoke_void(H.SET_VEHICLE_DENSITY_MULTIPLIER_THIS_FRAME, 0.0)
        invoke_void(H.SET_RANDOM_VEHICLE_DENSITY_MULTIPLIER_THIS_FRAME, 0.0)
        invoke_void(H.SET_PARKED_VEHICLE_DENSITY_MULTIPLIER_THIS_FRAME, 0.0)
    end
    if is_on("disable_decals") then invoke_void(H.SET_DISABLE_DECAL_RENDERING_THIS_FRAME) end
    -- Job/transition presentation can reapply both timecycle slots and blur.
    -- This frame path is already independent of local ped/session availability.
    if is_on("suppress_postfx") then stop_visual_effects_now() end
end

local function fast_tick()
    if not started then return end
    drain_commands()
    Audio.tick(Audio.stopping)
    -- Help suppression belongs exclusively to FrameTick, not this slower tick.
    local fps = module_context and module_context.FPSLimiter
    if fps then
        fps.Tick()
        local snapshot = fps_snapshot()
        if not snapshot.active and not snapshot.busy and is_on("unlock_fps") then
            -- Checked does not mean applied: rejected/unsupported requests
            -- return the control to off; the status card keeps the reason.
