            control_wait = source.authority_wait ~= nil,
            explosion_attempted = source.explosion_attempted == true,
            explosion_verified = source.explosion_verified == true,
            explosion_accepted = source.explosion_accepted,
            explosion_error = source.explosion_error,
            blast_attempted = source.blast_attempted == true,
            blast_backend = source.blast_backend, blast_accepted = source.blast_accepted,
            blast_error = source.blast_error, blast_size = source.blast_size,
            blast_view_distance = source.blast_view_distance,
            preflight_distance = source.preflight_distance,
            flight_ascent = source.flight_ascent,
            flight_verified = source.flight_verified == true,
            flight_task_handoff = source.flight_task_handoff == true,
            remote_hold_state = source.remote_hold_state,
            seat_fallback_attempted = source.seat_fallback_attempted==true,
            seat_fallback_accepted = source.seat_fallback_accepted,
            seat_fallback_attempts = source.seat_fallback_attempts or 0,
            direct_entry_attempts = source.direct_entry_attempts or 0,
            actor_protection_accepted = actor.protection_accepted,
            actor_protection_readback = actor.protection_readback,
            actor_migration_requested = actor.migration_locked==true,
            access_restore_incomplete = source.access_restore_incomplete == true,
            cleanup_pending = #deferred > 0 or (run ~= nil and (source.cancel_reason ~= nil or source.phase == "cleanup" or source.phase == "debt")),
            ped = type(source.ped) == "table" and source.ped.handle or source.ped_handle,
            vehicle = type(source.vehicle) == "table" and source.vehicle.handle or source.vehicle_handle,
            lester = type(source.lester) == "table" and source.lester.handle or 0,
            retired = source.retired or 0, cleanup_debt = debts(),
        }
        return result
    end
    local function finish()
        local state = snapshot()
        state.active, state.cleanup_pending, state.phase, state.paused = false, false, "idle", quiesced
        state.ped_handle, state.vehicle_handle = state.ped, state.vehicle
        state.ped, state.vehicle = nil, nil
        last = state
        local message = run.reason or "cancelled"
        if run.explosion_verified and (run.retired or 0) == 0 and not run.access_restore_incomplete then
            message = "Lester's ride finished; temporary state restored."
        end
        if (run.retired or 0) > 0 then
            message = message .. " Original entity references were lost; replacement entities were not modified."
        end
        if run.access_restore_incomplete then
            message = message .. " A changed player/seat identity prevented restoring an original access permission."
        end
        run = nil
        notify(message, state.explosion_verified and state.retired == 0 and not state.access_restore_incomplete and "success" or "warning")
    end
    local function begin_cleanup(reason, now)
        if not run then return end
        run.reason = run.cancel_reason or reason or run.reason or "cancelled"
        run.cancel_reason = run.reason
        run.authority_wait = nil
        if run.phase ~= "cleanup" then
            set_phase("cleanup", now, LIMIT.cleanup)
            run.cleanup_reported = false
        end
    end
    local function retire(record, reason)
        if not record.retired then
            record.retired = reason
            run.retired = (run.retired or 0) + 1
            log("Retired original entity " .. tostring(record.handle) .. ": " .. tostring(reason))
        end
        record.freeze_owned, record.lock_owned, record.owner_owed = false, false, false
        record.invincible_owned, record.ragdoll_owned = false, false
        record.hold_owned, record.pose_owned, record.damage_flags_owned = false, false, false
        for _, entry in pairs(record.player_locks or {}) do entry.owned = false end
        if record.exclusive then record.exclusive.owned = false end
    end
    local function has_control(record)
        local value
        if matches(record) ~= nil then value = read_bool(H.CONTROL, record.handle) end
        record.observed_control = value
        return value == true
    end
    local function request_control(record, now)
        if not matches(record) then return false end
        if read_bool(H.CONTROL, record.handle) == true then
            if record.original_owner and record.original_owner ~= run.local_id then record.owner_owed = true end
            return true
        end
        if now < (record.next_request_ms or -math.huge) then return false end
        if not resource_cleanup_allowed() then return false end
        if run.phase ~= "cleanup" and run.phase ~= "debt" and not scene_allowed() then return false end
        record.next_request_ms = now + LIMIT.request_interval
        if record.original_owner and record.original_owner ~= run.local_id then record.owner_owed = true end
        if type(deps.request_entity_control) == "function" then
            pcall(deps.request_entity_control, run.local_id, record.handle)
        else
            read_bool(H.REQUEST_CONTROL, record.handle)
        end
        -- The wrapper's return is not sufficient evidence of authority.
        return matches(record) ~= nil and read_bool(H.CONTROL, record.handle) == true
    end
    local function slot_matches(entry)
        if entry.identity then return player_match_state(entry.identity) end
        local current, reason = player_identity(entry.pid)
        if current then return false end
        if entry.empty and reason == "gone" then return true end
        return nil
    end
    local function exclusive_state(ped_record)
        -- Enhanced freemode func_21607 proves (vehicle, ped, outIndex).
        -- The supplied NativeDB parameter labels incorrectly reverse the first two.
        if not run.access_buffer or not matches(run.vehicle) or not matches(ped_record) then return nil end
        local value = read_bool(H.EXCLUSIVE_GET, run.vehicle.handle, ped_record.handle, run.access_buffer)
        if value ~= true then return value end
        local ok, index = pcall(deps.Memory.ReadInt, run.access_buffer)
        if not ok or (index ~= 0 and index ~= 1) then return nil end
        return true, index
    end
    local function capture_access()
        local record = run.vehicle
        record.player_locks = {}
        for pid = 0, 31 do
            if not scene_allowed() or not matches(record) then return false, "car identity changed during access capture" end
            local value = read_bool(H.PLAYER_LOCK_GET, record.handle, pid)
            if value == nil then return false, "personal-vehicle access is unreadable" end
            local entry = { pid = pid, original = value, owned = false }
            if value then
                local identity, reason = player_identity(pid)
                if not identity and reason ~= "gone" then return false, "player-slot identity is unreadable for vehicle access" end
                entry.identity, entry.empty = identity, not identity
            end
            record.player_locks[pid] = entry
        end
        if not scene_allowed() then return false, "scene stopped during access capture" end
        local ok, buffer = pcall(deps.Memory.AllocInt)
        if not ok or not integer(buffer) or buffer == 0 then return false, "exclusive-seat query buffer is unavailable" end
        run.access_buffer = buffer
        if not scene_allowed() then return false, "scene stopped during access capture" end
        if not pcall(deps.Memory.WriteInt, buffer, -1) then return false, "exclusive-seat query buffer could not be initialized" end
        if not scene_allowed() then return false, "scene stopped during access capture" end
        local exclusive, index = exclusive_state(run.ped)
        if exclusive == nil then return false, "exclusive driver seat is unreadable" end
        if exclusive then record.exclusive = { index = index, original = run.ped, owned = false } end
        return true
    end
    local function borrow_access(now)
        local record = run.vehicle
        for pid = 0, 31 do
            local entry = record.player_locks[pid]
            if entry.original then
                if slot_matches(entry) ~= true or read_bool(H.PLAYER_LOCK_GET, record.handle, pid) ~= true then
                    return false, "personal-vehicle access changed before the hijack"
                end
                if not scene_allowed() or not has_control(record) then return false, "car authority changed before opening access" end
                entry.owned = true
                local accepted = scene_write(H.PLAYER_LOCK_SET, record.handle, pid, false)
                local observed
                if matches(record) then observed = read_bool(H.PLAYER_LOCK_GET, record.handle, pid) end
                -- A reentrant persistent restore may have run before this setter committed.
                if observed ~= true then entry.owned = true end
                if not accepted or observed ~= false then return false, "personal-vehicle access did not open for Lester" end
            end
        end
        local exclusive = record.exclusive
        if exclusive then
            local current, index = exclusive_state(exclusive.original)
            if current ~= true or index ~= exclusive.index then return false, "exclusive driver changed before the hijack" end
            if not scene_allowed() or not has_control(record) or not matches(run.lester) then
                return false, "car/Lester identity changed before exclusive-seat access"
            end
            exclusive.applied, exclusive.owned = run.lester, true
            local accepted = scene_write(H.EXCLUSIVE_SET, record.handle, run.lester.handle, exclusive.index)
            local observed, observed_index = exclusive_state(exclusive.applied)
            if observed == nil or (observed and observed_index == exclusive.index) then exclusive.owned = true end
            if not accepted or observed ~= true or observed_index ~= exclusive.index then
                return false, "exclusive driver access did not transfer to Lester"
            end
        end
        record.access_borrowed, record.next_access_check = true, now + LIMIT.request_interval
        return true
    end
    local function access_unchanged(now)
        local record = run.vehicle
        if not record.access_borrowed or now < record.next_access_check then return true end
        record.next_access_check = now + LIMIT.request_interval
        -- Freemode may reapply the captured global restriction after our first
        -- unlock. Retry only that original value; preserve a different later
        -- change for cleanup instead of silently waiting for the entry timeout.
        local door_lock = read_int(H.LOCK_GET, record.handle)
        if door_lock ~= 1 then
            if door_lock ~= record.original_lock or not has_control(record) or not scene_allowed() then return false end
            record.lock_owned, record.applied_lock = true, 1
            local accepted = scene_write(H.LOCK_SET, record.handle, 1)
            if not accepted or not matches(record) or read_int(H.LOCK_GET, record.handle) ~= 1 then return false end
        end
        for _, entry in pairs(record.player_locks) do
            if entry.owned then
                if slot_matches(entry) ~= true then return false end
                local value = read_bool(H.PLAYER_LOCK_GET, record.handle, entry.pid)
                if value == true and has_control(record) and scene_allowed() then
                    scene_write(H.PLAYER_LOCK_SET, record.handle, entry.pid, false)
                    value = matches(record) and read_bool(H.PLAYER_LOCK_GET, record.handle, entry.pid)
                end
                if value ~= false then return false end
            elseif read_bool(H.PLAYER_LOCK_GET, record.handle, entry.pid) ~= false then
                -- A restriction first introduced after capture belongs to its
                -- caller. Detect it promptly without borrowing or restoring it.
                return false
            end
        end
        local exclusive = record.exclusive
        if exclusive and exclusive.owned then
            local value, index = exclusive_state(exclusive.applied)
            if value ~= true or index ~= exclusive.index then return false end
        end
        return true
    end
    local function retire_access(entry, reason)
        entry.owned = false
        run.access_restore_incomplete = true
        log("Original access permission was not restored: " .. reason)
    end
    local function restore_access(now, allow_request, target_scope)
        local record = run.vehicle
        if not access_owed(record) then return true end
        local current, reason = matches(record)
        if not current then
            if reason == "gone" or reason == "replaced" then retire(record, reason); return true end
            return false
        end
        local function control()
            return has_control(record) or (allow_request and request_control(record, now))
        end
        for _, entry in pairs(record.player_locks or {}) do
            if entry.owned then
                local observed = read_bool(H.PLAYER_LOCK_GET, record.handle, entry.pid)
                if observed == entry.original then entry.owned = false
                elseif observed ~= nil then
                    local same_slot = slot_matches(entry)
                    if same_slot == false then retire_access(entry, "player slot " .. tostring(entry.pid) .. " changed")
                    elseif same_slot == true and control() then
                        -- Ownership acquisition can yield across a connection or permission change.
                        if cleanup_scope() ~= true or not matches(record) then return false end
                        local current_lock = read_bool(H.PLAYER_LOCK_GET, record.handle, entry.pid)
                        local current_slot = slot_matches(entry)
                        if current_lock == entry.original then entry.owned = false
                        elseif current_slot == false then retire_access(entry, "player slot " .. tostring(entry.pid) .. " changed during control acquisition")
                        elseif current_lock == false and current_slot == true and has_control(record) then
                            write(H.PLAYER_LOCK_SET, record.handle, entry.pid, entry.original)
                            if read_bool(H.PLAYER_LOCK_GET, record.handle, entry.pid) == entry.original then entry.owned = false end
                        end
                    end
                end
            end
        end
        local exclusive = record.exclusive
        if exclusive and exclusive.owned then
            local applied, applied_reason = matches(exclusive.applied)
            if not applied then
                if applied_reason == "gone" or applied_reason == "replaced" then
                    retire_access(exclusive, "Lester's exclusive-seat identity was lost")
                end
            else
                local value, index = exclusive_state(exclusive.applied)
                if value == false or (value == true and index ~= exclusive.index) then
                    exclusive.owned = false
                    log("Preserved a later exclusive-driver change.")
                elseif value == true and index == exclusive.index and target_scope ~= nil then
                    if control() then
                        local current_local, current_target = cleanup_scope()
                        if current_local ~= true or not matches(record) then return false end
                        local current_applied, current_index = exclusive_state(exclusive.applied)
                        if current_applied == false or (current_applied == true and current_index ~= exclusive.index) then
                            exclusive.owned = false
                            log("Preserved an exclusive-driver change during control acquisition.")
                        elseif current_applied == true and current_index == exclusive.index then
                            local original, original_reason = matches(exclusive.original)
                            local replacement
                            if current_target == true and original then replacement = original.handle
                            elseif current_target == false or original_reason == "gone" or original_reason == "replaced" then replacement = 0 end
                            if replacement ~= nil and has_control(record) then
                                write(H.EXCLUSIVE_SET, record.handle, replacement, exclusive.index)
                                local still_applied, after_index = exclusive_state(exclusive.applied)
                                if still_applied == false or (still_applied == true and after_index ~= exclusive.index) then
                                    exclusive.owned = false
                                end
                            end
                        end
                    end
                end
            end
        end
        return not access_owed(record)
    end
    local function freeze_record(record)
        local current = matches(record)
        if not readable_freeze(current) or frozen(current) or not has_control(record) then return false end
        record.freeze_owned = true -- retain debt even if a bridge throws after the setter
        local accepted = scene_write(H.FREEZE, record.handle, true)
        local after = matches(record)
        -- A reentrant Stop may have restored the old value before the pending
        -- host setter commits; retain the resulting freeze for the final fallback.
        if not readable_freeze(after) or frozen(after) then record.freeze_owned = true end
        return accepted and readable_freeze(after) and frozen(after)
    end
    local function restore_flags(record, now, allow_request)
        if not record or (not record.freeze_owned and not record.lock_owned
            and not record.hold_owned and not record.damage_flags_owned) then return true end
        local current, reason = matches(record)
        if not current then
            if reason == "gone" or reason == "replaced" then retire(record, reason); return true end
            return false
        end
        local function control()
            return has_control(record) or (allow_request and request_control(record, now))
        end
        if record.hold_owned and control() then
            if cleanup_scope() ~= true or not matches(record) then return false end
            local restored = true
            -- Stop only our named pose, not unrelated gameplay tasks.
            if record.pose_owned then
                if read_bool(H.PLAYING_ANIM, record.handle, HOLD_DICT, HOLD_CLIP, 3) == true then
                    restored = write(H.STOP_ANIM, record.handle, HOLD_DICT, HOLD_CLIP, -8.0) and restored
                end
                record.pose_owned = not restored
            end
            for _, flag in ipairs({48, 120}) do
                if not matches(record) or not has_control(record) then return false end
                local original = record.hold_flags and record.hold_flags[flag]
                if original ~= nil and read_bool(H.PED_FLAG_GET, record.handle, flag, true) ~= original then
                    local setter = flag == 120 and H.HANDCUFFS or H.PED_FLAG
                    if flag == 120 then write(setter, record.handle, original)
                    else write(setter, record.handle, flag, original) end
                end
                restored = original ~= nil and read_bool(H.PED_FLAG_GET, record.handle, flag, true) == original and restored
            end
            if not matches(record) or not has_control(record) then return false end
            if record.hold_ragdoll ~= nil and read_bool(H.CAN_RAGDOLL, record.handle) ~= record.hold_ragdoll then
                write(H.RAGDOLL, record.handle, record.hold_ragdoll)
            end
            restored = read_bool(H.CAN_RAGDOLL, record.handle) == record.hold_ragdoll and restored
            record.hold_owned = not restored
        end
        if record.damage_flags_owned and control() then
            if cleanup_scope() ~= true or not matches(record) then return false end
            local old, restored = record.damage_flags, true
            if old.invincible ~= nil then restored = write(H.INVINCIBLE, record.handle, old.invincible, false) and restored end
            if not matches(record) or not has_control(record) then return false end
            if old.damageable ~= nil then restored = write(H.SET_DAMAGEABLE, record.handle, old.damageable) and restored end
            if old.proofs then
                if not matches(record) or not has_control(record) then return false end
                local q=old.proofs
                restored = write(H.SET_PROOFS, record.handle,q.bullet,q.fire,q.explosion,q.collision,q.melee,q.steam,q.p7,q.drown) and restored
            end
            record.damage_flags_owned = not restored
        end
        if record.freeze_owned then
            if not readable_freeze(current) then return false end
            if not frozen(current) then record.freeze_owned = false
            elseif control() then
                write(H.FREEZE, record.handle, false)
                local after = matches(record)
                if readable_freeze(after) and not frozen(after) then record.freeze_owned = false end
            end
        end
        if record.lock_owned then
            local current_lock = read_int(H.LOCK_GET, record.handle)
            if current_lock == record.original_lock then record.lock_owned = false
            elseif current_lock ~= nil and current_lock ~= record.applied_lock then
                record.lock_owned = false
                log("Preserved a later car door-lock change.")
            elseif current_lock == record.applied_lock and control() then
                write(H.LOCK_SET, record.handle, record.original_lock)
                if read_int(H.LOCK_GET, record.handle) == record.original_lock then record.lock_owned = false end
            end
        end
        return not record.freeze_owned and not record.lock_owned and not record.hold_owned and not record.damage_flags_owned
    end
    local function restore_owner(record, now)
        if not record or not record.owner_owed then return true end
        if record.freeze_owned or record.lock_owned or record.hold_owned or record.damage_flags_owned or access_owed(record) then return false end
        local current, reason = matches(record)
        if not current then
            if reason == "gone" or reason == "replaced" then retire(record, reason); return true end
            return false
        end
        local owner_identity_state = player_match_state(record.owner_identity)
        if owner_identity_state == nil then return false end
        if owner_identity_state == false then
            record.owner_owed = false
            log("Original ownership recipient left; no transfer to a reused player slot.")
            return true
        end
        if current.owner == record.original_owner and current.pending_owner ~= run.local_id then
            record.owner_owed = false
            return true
        end
        if current.owner ~= run.local_id and current.pending_owner ~= run.local_id then
            record.owner_owed = false
            log("Preserved a later ownership transfer.")
            return true
        end
        if now < (record.next_owner_restore_ms or -math.huge) then return false end
        if not resource_cleanup_allowed() then return false end
        record.next_owner_restore_ms = now + LIMIT.request_interval
        if type(deps.GTA.GiveControl) ~= "function" then return false end
        pcall(deps.GTA.GiveControl, record.original_owner, record.handle)
        local after = matches(record)
        if after and after.owner == record.original_owner and after.pending_owner ~= run.local_id then
            record.owner_owed = false
        end
        return not record.owner_owed
    end
    local function maintain_actor_protection(now, force)
        local scene,record=run,run and run.lester
        if not record then return true end
        local function current()
            return run==scene and run.lester==record and resource_cleanup_allowed()
                and matches(record)~=nil and run==scene and run.lester==record
        end
        if not current() then return false end
        -- These reset flags expire every frame, independently of the slower
        -- protection cadence. Keep the created actor walking at entry altitude.
        if has_control(record) then
            local on_foot=read_bool(H.ON_FOOT,record.handle)==true
            local entry=scene_allowed() and (run.phase=="spawn" or run.phase=="actor_control"
                or run.phase=="jack" or run.phase=="ped_control" or run.phase=="ped_hold")
            if current() then write(H.GRAVITY,record.handle,not (on_foot and entry)) end
            if on_foot and entry and current() then
                local velocity=vector(H.GET_VELOCITY,record.handle)
                if velocity and velocity.z<0 and current() and has_control(record) then
                    write(H.VELOCITY,record.handle,velocity.x,velocity.y,0.0)
                end
            end
            for _,flag in ipairs({150,370,210,458}) do
                if current() then write(H.RESET_FLAG,record.handle,flag,true) end
            end
            if entry and on_foot and current() and read_bool(H.FALLING,record.handle)==true
                and now>=(record.next_fall_recovery or -math.huge) then
                record.next_fall_recovery=now+500
                if current() and write(H.CLEAR_TASKS,record.handle) and current()
                    and run.task_issued and run.jack_deadline_ms and now<run.jack_deadline_ms
                    and has_control(run.vehicle) then
                    -- Resume the original entry task within its existing deadline.
                    scene_write(H.ENTER,record.handle,run.vehicle.handle,run.jack_deadline_ms-now,-1,1.0,8,0)
                end
            end
        end
        if not force and now<(record.next_protection_ms or -math.huge) then return true end
        record.next_protection_ms=now+100
        -- This is exclusively our verified newly created actor. Local protection
        -- must remain active while network authority is being reacquired, and
        -- must not be removed from a surviving actor when deletion is rejected.
        local function protect(hash,...)
            if not current() then return false end
            return write(hash,record.handle,...)
        end
        record.invincible_owned,record.ragdoll_owned=true,true
        local accepted=protect(H.INVINCIBLE,true,false)
        accepted=protect(H.SET_DAMAGEABLE,false) and accepted
        accepted=protect(H.SET_PROOFS,true,true,true,true,true,true,true,true) and accepted
        accepted=protect(H.RAGDOLL,false) and accepted
        accepted=protect(H.TARGETTABLE,false) and accepted
        accepted=protect(H.DRAGGABLE,false) and accepted
        record.protection_accepted=accepted
        record.protection_readback=current() and read_bool(H.DAMAGEABLE,record.handle)==false
            and read_bool(H.CAN_RAGDOLL,record.handle)==false
        if current() and has_control(record) and record.network_id~=nil then
            local network_id=read_int(H.NETWORK_ID,record.handle)
            -- Native script network IDs and wrapper ObjectID are distinct representations.
            -- The wrapper still guards identity; compare native values only with native values.
            if integer(network_id) and network_id>0 and record.native_network_id==nil then
                record.native_network_id=network_id
                log("Lester network identity: wrapper="..tostring(record.network_id).." native="..tostring(network_id))
            end
            if integer(network_id) and network_id>0 and network_id==record.native_network_id and current() and has_control(record) then
                -- The migration lease belongs only to this script-created actor.
                -- It remains locked until confirmed deletion; no borrowed entity
                -- gets a migration setter or an assumed restoration value.
                if write(H.MIGRATE,network_id,false) and current() then record.migration_locked=true end
            end
        end
        return accepted and current()
    end
    local function remove_lester(now)
        local record = run.lester
        if not record then return true end
        -- Deleting our actor does not require authority over the borrowed car.
        -- Car freeze/lock/access restoration remains tracked independently. In
        -- particular, a denied car permission must not strand an immortal actor.
        local current, reason = matches(record)
        if not current then
            if reason == "gone" or reason == "replaced" then
                retire(record, reason); run.lester = nil; return true
            end
            return false
        end
        if not request_control(record, now) then return false end
        maintain_actor_protection(now,true)
        if not resource_cleanup_allowed() then return false end
        local memory = deps.Memory
        if not memory or type(memory.AllocInt) ~= "function" or type(memory.WriteInt) ~= "function"
            or type(memory.Free) ~= "function" then return false end
        local allocated, buffer = pcall(memory.AllocInt)
        if not allocated or not integer(buffer) or buffer == 0 then return false end
        -- Cherax owns any guarded allocation left during final teardown. Do not
        -- start another buffer operation if Stop reentered the allocation call.
        if not resource_cleanup_allowed() then return false end
        local stored = pcall(memory.WriteInt, buffer, record.handle)
        if stored and matches(record) and has_control(record) and resource_cleanup_allowed() then
            -- This is our created actor, never the selected player. Adopt the
            -- script mission reference before deleting and verify disappearance.
            write(H.MISSION, record.handle, true, true)
            if matches(record) and has_control(record) and resource_cleanup_allowed() then
                write(H.DELETE_PED, buffer)
            end
            if matches(record) and has_control(record) and resource_cleanup_allowed() then
                -- DELETE_PED may zero the buffer even when the entity survives.
                local restored = pcall(memory.WriteInt, buffer, record.handle)
                if restored and matches(record) then write(H.DELETE_ENTITY, buffer) end
            end
        end
        if resource_cleanup_allowed() then pcall(memory.Free, buffer) end
        local after, after_reason = matches(record)
        if not after and (after_reason == "gone" or after_reason == "replaced") then run.lester = nil end
        return run.lester == nil
    end
    cleanup_scope = function()
        if not run.local_identity then return true, true end
        local current_local_id, session = local_id(), read_bool(H.SESSION)
        local local_state = player_match_state(run.local_identity)
        if current_local_id == nil or session == nil or local_state == nil then return nil, nil end
        if current_local_id ~= run.local_id or session ~= run.session or local_state == false then return false, false end
        return true, player_match_state(run.target_identity)
    end
    local function restore_persistent(now, allow_request)
        local local_scope, target_scope = cleanup_scope()
        -- A different local connection/session cannot supply proof for an old
        -- network object, even if a recycled handle/address happens to match.
        if local_scope == false then
            for _, record in pairs({ ped = run.ped, vehicle = run.vehicle, lester = run.lester }) do
                retire(record, "local session identity changed")
            end
            run.lester = nil
            return true, true, false
        end
        if local_scope == nil then return false, false, nil end
        local ped_ok = true
        if target_scope == false and run.ped then retire(run.ped, "selected player connection changed")
        elseif target_scope == nil and run.ped then ped_ok = not run.ped.freeze_owned and not run.ped.hold_owned
        else ped_ok = restore_flags(run.ped, now, allow_request) end
        local car_ok = restore_flags(run.vehicle, now, allow_request)
        local current_local, current_target = cleanup_scope()
        if current_local ~= true then return false, false, current_local end
        car_ok = restore_access(now, allow_request, current_target) and car_ok
        current_local = cleanup_scope()
        if current_local ~= true then return false, false, current_local end
        -- Actor protection/migration are removed by confirmed deletion, never
        -- by making a still-live actor vulnerable before a fallible delete.
        return ped_ok, car_ok, true
    end
    local function cleanup(now, allow_request)
        if not run then return true end
        if allow_request and not resource_cleanup_allowed() then return false end
        local _, _, local_scope = restore_persistent(now, allow_request)
        if allow_request and resource_cleanup_allowed() and local_scope == true then
            maintain_actor_protection(now)
            remove_lester(now)
            restore_owner(run.ped, now)
            if not run.lester then restore_owner(run.vehicle, now) end
        end
        if allow_request and resource_cleanup_allowed() and run.model_requested
            and write(H.RELEASE_MODEL, LIMIT.lester_model) then run.model_requested = false end
        if allow_request and resource_cleanup_allowed() and run.anim_requested and not (run.ped and run.ped.hold_owned)
            and write(H.RELEASE_ANIM, HOLD_DICT) then run.anim_requested = false end
        if allow_request and resource_cleanup_allowed() and run.access_buffer and not access_owed(run.vehicle) then
            local ok = pcall(deps.Memory.Free, run.access_buffer)
            if ok then run.access_buffer = nil end
        end
        local pending = debts()
        if #pending == 0 then finish(); return true end
        if allow_request and run.deadline and now >= run.deadline then
            run.phase = "debt"
            run.next_debt_retry_ms = now + 1000
            if not run.cleanup_reported then
                run.cleanup_reported = true
                notify("Cleanup pending: " .. table.concat(pending, ", ") .. "; retrying at most once per second.")
            end
        end
        return false
    end

    local function retry_deferred(now, force, persistent_only)
        if #deferred == 0 then return true end
        if deferred_cursor > #deferred then deferred_cursor = 1 end
        local index = deferred_cursor
        local pending = deferred[index]
        deferred_cursor = index % #deferred + 1
        if not force and now < (pending.next_debt_retry_ms or 0) then return false end
        -- All routines below resolve identity again through the temporarily
        -- selected record. No actor or active scene is ever placed in this queue.
        local active, saved_last = run, last
        run = pending
        local ok, finished
        if persistent_only then
            local ped_ok, car_ok
            ok, ped_ok, car_ok = pcall(restore_persistent, now, false)
            finished = ok and ped_ok and car_ok
        else
            ok, finished = pcall(cleanup, now, true)
        end
        local remaining = run
        run, last = active, saved_last
        if not ok then log("deferred cleanup retry: " .. tostring(finished)) end
        if not persistent_only and ok and remaining == nil then table.remove(deferred, index)
        else pending.next_debt_retry_ms = now + 1000 end
        return #deferred == 0
    end

    local function validate_current()
        if read_bool(H.SESSION) ~= run.session or local_id() ~= run.local_id
            or not same_player(run.local_identity) or ped_for(run.local_id) ~= run.local_ped.handle
            or not matches(run.local_ped) then return false, "local player/session identity changed or became unreadable" end
        if not same_player(run.target_identity) or ped_for(run.pid) ~= run.ped.handle then
            return false, "selected player identity changed or became unreadable"
        end
        if not matches(run.ped) or not matches(run.vehicle) then return false, "original player or car no longer exists" end
        if read_bool(H.DEAD, run.ped.handle, false) ~= false then return false, "selected player is no longer alive" end
        if run.phase ~= "explosion" and read_bool(H.DEAD, run.vehicle.handle, false) ~= false then
            return false, "car was destroyed before the finale"
        end
        if run.lester then
            if not matches(run.lester) then run.lester.live = false; return false, "Lester actor no longer exists" end
            run.lester.live = read_bool(H.DEAD, run.lester.handle, false) == false
            if run.phase ~= "explosion" and not run.lester.live then return false, "Lester did not survive the hijack" end
        end
        -- Bound scene displacement, not the spectator's distance. Streamed
        -- physical identities above remain mandatory throughout the scene.
        local origin = run.scene_origin
        for _, record in ipairs({ run.ped, run.vehicle }) do
            local position = vector(H.COORDS, record.handle, false)
            if not origin or not position then return false, "scene coordinates are no longer streamed" end
            local dx, dy, dz = position.x - origin.x, position.y - origin.y, position.z - origin.z
            if dx * dx + dy * dy + dz * dz > LIMIT.scene_distance * LIMIT.scene_distance then
                return false, "scene moved outside its captured origin bounds"
            end
        end
        local observation = {
            current_vehicle = read_int(H.CURRENT_VEHICLE, run.ped.handle, false),
            in_any = read_bool(H.IN_ANY, run.ped.handle, false),
            on_foot = read_bool(H.ON_FOOT, run.ped.handle),
            being_jacked = read_bool(H.BEING_JACKED, run.ped.handle),
        }
        run.observation = observation
        if observation.in_any == nil then return false, "selected player occupancy is unreadable" end
        -- The association handle can remain nonzero during/after a drag-out.
        -- Match compat.player_snapshot: only occupancy makes it a current car.
        if observation.in_any == true then
            if observation.current_vehicle == nil or observation.current_vehicle ~= run.vehicle.handle then
                return false, "selected player changed vehicles"
            end
            if run.ejected_verified or run.ped.freeze_owned then return false, "selected player re-entered a vehicle" end
        end
        return true
    end
    local function driver()
        local value = read_int(H.DRIVER, run.vehicle.handle, -1, false)
        if run.observation then run.observation.driver = value end
        return value
    end
    local function seated()
        local value = run.lester and driver() == run.lester.handle
            and read_bool(H.IN_VEHICLE, run.lester.handle, run.vehicle.handle, false) == true
        if run.observation then run.observation.lester_seated = value == true end
        return value
    end
    local function recover_entry_task(now)
        if run.phase ~= "jack" or not run.task_issued or seated()
            or now - run.jack_started_ms < 2000 or now >= run.jack_deadline_ms
            or now < (run.next_direct_entry_ms or 0) or (run.direct_entry_attempts or 0) >= 3 then return end
        -- TASK_ENTER_VEHICLE flag 16 is the documented direct-entry path. It
        -- acts on our actor, so it can finish the carjack even while authority
        -- over the occupied car is migrating. Never replace an unrelated driver.
        local occupant = driver()
        if (occupant ~= 0 and occupant ~= run.ped.handle) or not scene_allowed()
            or not matches(run.vehicle) or not matches(run.ped)
            or not matches(run.lester) or not has_control(run.lester) then return end
        run.direct_entry_attempts = (run.direct_entry_attempts or 0) + 1
        run.next_direct_entry_ms = now + 1000
        scene_write(H.ENTER, run.lester.handle, run.vehicle.handle,
            math.max(1, run.jack_deadline_ms - now), -1, 2.0, 16, 0)
        -- Acceptance is not proof of seating/ejection; the existing observations
        -- and original scene deadline remain mandatory before flight.
        if scene_allowed() then diagnostic("direct-entry-fallback", now) end
    end
    local function recover_authority(now)
        local phase = run.phase
        local before_task = phase == "hold" or phase == "spawn" or phase == "actor_control"
        local during_entry = phase == "jack" or phase == "ped_control" or phase == "ped_hold"
        if not before_task and not during_entry and phase ~= "flight" then return true end
        local required = { { "car", run.vehicle } }
        if during_entry or phase == "flight" then required[#required + 1] = { "Lester", run.lester } end
        if run.pid==run.local_id and (phase == "ped_hold" or phase == "flight") then
            required[#required + 1] = { "player", run.ped }
        end
        local waiting = run.authority_wait
        if waiting and now >= waiting.deadline then
            begin_cleanup("could not recover " .. waiting.entities .. " control during " .. phase, now)
            return false
        end
        local missing = {}
        for _, item in ipairs(required) do
            if not has_control(item[2]) then missing[#missing + 1] = item end
        end
        if #missing == 0 then
            if waiting then
                run.authority_wait = nil
                run.vehicle.next_access_check = now
                diagnostic("control-recovered", now)
            end
            return true
        end
        -- Ownership can migrate during the engine's carjack task. Keep that
        -- single task and its original deadline while control is reacquired.
        if not waiting then
            local deadline = during_entry and math.min(run.jack_deadline_ms, run.started_ms + LIMIT.total)
                or math.min(now + LIMIT.control, run.deadline or math.huge, run.started_ms + LIMIT.total)
            local names = {}
            for _, item in ipairs(missing) do names[#names + 1] = item[1] end
            waiting = { deadline = deadline, entities = table.concat(names, "/") }
            run.authority_wait = waiting
            diagnostic("control-wait", now)
        end
        run.ejection_since_ms = nil
        if now >= waiting.deadline then
            begin_cleanup("could not recover " .. waiting.entities .. " control during " .. phase, now)
            return false
        end
        local function current_driver_valid()
            local occupant = driver()
            return before_task and occupant == run.ped.handle or not before_task and occupant ~= nil
                and (occupant == 0 or occupant == run.ped.handle or occupant == run.lester.handle)
        end
        if not current_driver_valid() then begin_cleanup("driver changed during control recovery", now); return false end
        for _, item in ipairs(missing) do
            request_control(item[2], now)
            if not scene_allowed() then return false end
            local returned_at = clock()
            if returned_at < now or returned_at >= waiting.deadline then
                begin_cleanup("control recovery returned after its deadline", returned_at)
                return false, returned_at
            end
            now = returned_at
            -- The host request may yield or reenter the script. Refresh every
            -- identity before another request or any resumed scene operation.
            local valid, reason = validate_current()
            if not valid then begin_cleanup(reason, now); return false, now end
            if not current_driver_valid() then begin_cleanup("driver changed during control recovery", now); return false, now end
        end
        for _, item in ipairs(required) do if not has_control(item[2]) then return false, now end end
        run.authority_wait = nil
        run.vehicle.next_access_check = now
        diagnostic("control-recovered", now)
        return true, now
    end
    local function begin_player_hold(now)
        local record = run.ped
        local f48 = read_bool(H.PED_FLAG_GET, record.handle, 48, true)
        local f120 = read_bool(H.PED_FLAG_GET, record.handle, 120, true)
        local ragdoll = read_bool(H.CAN_RAGDOLL, record.handle)
        if f48 == nil or f120 == nil or ragdoll == nil then return false end
        if not matches(record) or not has_control(record) or not scene_allowed() then return false end
        record.hold_flags, record.hold_ragdoll = {[48]=f48,[120]=f120}, ragdoll
        record.hold_owned, record.pose_owned = true, true
        run.pose_started_ms, run.next_pose_ms, run.pose_attempts = now, now, 0
        return true
    end
    local function maintain_player_hold(now)
        local record = run.ped
        if not record or not record.hold_owned then return true end
        if not matches(record) or not has_control(record) or not scene_allowed() then return false end
        local function hold_write(hash,...)
            record.hold_owned=true
            local ok=scene_write(hash,...)
            record.hold_owned=true -- a reentrant restore may precede host commit
            return ok
        end
        -- PAD suppression applies only to the local player's input.
        if run.pid == run.local_id then
            scene_write(H.DISABLE_FIRE, run.local_id, true)
            for _, group in ipairs({0,2}) do
                for _, id in ipairs({21,22,23,24,25,30,31,37,45,58,140,141,142,143,257,263,264}) do
                    if not scene_allowed() then return false end
                    scene_write(H.DISABLE_INPUT, group, id, true)
                end
            end
        end
        if read_bool(H.PED_FLAG_GET, record.handle, 48, true) ~= true then hold_write(H.PED_FLAG,record.handle,48,true) end
        if not scene_allowed() or not matches(record) then return false end
        if read_bool(H.PED_FLAG_GET, record.handle, 120, true) ~= true then hold_write(H.HANDCUFFS,record.handle,true) end
        if not scene_allowed() or not matches(record) then return false end
        if read_bool(H.CAN_RAGDOLL, record.handle) ~= false then hold_write(H.RAGDOLL,record.handle,false) end
        if not scene_allowed() or not matches(record) then return false end
        local playing = read_bool(H.PLAYING_ANIM,record.handle,HOLD_DICT,HOLD_CLIP,3)
        if playing ~= true and now >= run.next_pose_ms and run.pose_attempts < 3 then
            run.pose_attempts, run.next_pose_ms = run.pose_attempts+1, now+250
            record.pose_owned = true
            scene_write(H.PLAY_ANIM,record.handle,HOLD_DICT,HOLD_CLIP,8.0,-8.0,LIMIT.total,2,1.0,false,false,false)
            -- A reentrant unload may occur in the host task setter.
            record.hold_owned, record.pose_owned = true, true
        end
        return scene_allowed()
    end
    local function held_player()
        if not run.ped.freeze_owned or not has_control(run.ped) or not frozen(matches(run.ped)) then return false end
        if not run.ped.hold_owned or read_bool(H.PLAYING_ANIM,run.ped.handle,HOLD_DICT,HOLD_CLIP,3) ~= true
            or read_bool(H.PED_FLAG_GET,run.ped.handle,48,true) ~= true
            or read_bool(H.PED_FLAG_GET,run.ped.handle,120,true) ~= true
            or read_bool(H.CAN_RAGDOLL,run.ped.handle) ~= false then return false end
        if read_bool(H.ON_FOOT, run.ped.handle) ~= true or read_bool(H.IN_ANY, run.ped.handle, false) ~= false then return false end
        local position = vector(H.COORDS, run.ped.handle, false)
        local origin = run.held_position
        if not position or not origin then return false end
        local dx, dy, dz = position.x - origin.x, position.y - origin.y, position.z - origin.z
        return dx * dx + dy * dy + dz * dz <= 0.25
    end
    local function player_departure_ready()
        if run.pid==run.local_id then return held_player() end
        -- Another peer owns its input. Departure is based on observed ejection,
        -- never on a claim that our local PAD/freeze call disabled that peer.
        return run.ejected_verified==true and matches(run.ped)~=nil
            and read_bool(H.ON_FOOT,run.ped.handle)==true
            and read_bool(H.IN_ANY,run.ped.handle,false)==false
            and read_bool(H.BEING_JACKED,run.ped.handle)==false
    end
    local function vacant_seat_fallback(now)
        if (run.seat_fallback_attempts or 0) >= 3 or now < (run.next_seat_fallback_ms or 0)
            or seated() or not run.ejected_verified
            or now-(run.ejected_verified_at or run.ejection_since_ms or now)<100 then return end
        local scene=run
        local function current()
            return run==scene and scene_allowed() and matches(run.ped) and matches(run.lester)
                and matches(run.vehicle) and has_control(run.lester) and has_control(run.vehicle)
                and frozen(matches(run.vehicle)) and read_bool(H.ON_FOOT,run.ped.handle)==true
                and read_bool(H.IN_ANY,run.ped.handle,false)==false
                and read_bool(H.BEING_JACKED,run.ped.handle)==false and driver()==0
                and run==scene and scene_allowed()
        end
        if not current() then return end
        run.seat_fallback_attempted=true
        run.seat_fallback_attempts=(run.seat_fallback_attempts or 0)+1
        run.next_seat_fallback_ms=now+250
        run.seat_fallback_accepted=scene_write(H.SEAT,run.lester.handle,run.vehicle.handle,-1)
        -- A void setter is only an attempted fallback. Flight below still needs
        -- the real driver-seat and IN_VEHICLE observations, including aircraft.
        if run==scene and scene_allowed() then diagnostic("vacant-seat-fallback",now) end
    end
    local function proof_observation(record)
        local memory = deps.Memory
        if not scene_allowed() or not memory or type(memory.Alloc) ~= "function"
            or type(memory.WriteInt) ~= "function" or type(memory.ReadInt) ~= "function"
            or type(memory.Free) ~= "function" then return nil end
        local allocated, pointer = pcall(memory.Alloc, 32)
        if not allocated or not integer(pointer) or pointer <= 0 then return nil end
        if not resource_cleanup_allowed() then return nil end
        local ok, result = pcall(function()
            local addresses = {}
            for index = 1, 8 do
                if not scene_allowed() then return nil end
                addresses[index] = pointer + (index - 1) * 4
                memory.WriteInt(addresses[index], -1)
            end
            if not matches(record) or not scene_allowed() then return nil end
            if read_bool(H.PROOFS, record.handle, table.unpack(addresses)) ~= true then return nil end
            local values = {}
            for index, name in ipairs({ "bullet", "fire", "explosion", "collision", "melee", "steam", "p7", "drown" }) do
                if not scene_allowed() then return nil end
                local value = memory.ReadInt(addresses[index])
                if value ~= 0 and value ~= 1 then return nil end
                values[name] = value == 1
            end
            if not matches(record) then return nil end
            return values
        end)
        -- Free our output buffer on normal success/error. If Stop reentered,
        -- Cherax owns guarded-allocation teardown; do not call buffer APIs again.
        if not resource_cleanup_allowed() then return nil end
        local freed = pcall(memory.Free, pointer)
        if not ok or not freed then return nil end
        return result
    end
    local function damage_observation(record)
        local current = matches(record)
        if not current then return { identity = false } end
        local result = {
            identity = true, dead = read_bool(H.DEAD, record.handle, false),
            damageable = read_bool(H.DAMAGEABLE, record.handle),
            health = read_int(H.HEALTH, record.handle),
            engine = read_float(H.ENGINE_HEALTH, record.handle),
            body = read_float(H.BODY_HEALTH, record.handle),
            driveable = read_bool(H.DRIVEABLE, record.handle, false),
            proofs = proof_observation(record),
        }
        local ok, invincible = pcall(function()
            local object = deps.GTA.HandleToPointer(record.handle)
            if object and object:GetAddress() == record.address and type(object.IsInvincible) == "function" then
                return object:IsInvincible()
            end
        end)
        if ok and type(invincible) == "boolean" then result.invincible = invincible end
        current = matches(record)
        if not current then return { identity = false } end
        result.control = read_bool(H.CONTROL, record.handle)
        result.owner, result.pending = current.owner, current.pending_owner
        return result
    end
    local function damage_text(value)
        if not value then return "not-sampled" end
        local proofs = value.proofs
        local function proof(name) return proofs and tostring(proofs[name]) or "unknown" end
        return ("identity=%s dead=%s damageable=%s invincible=%s health=%s engine=%s body=%s driveable=%s control=%s owner=%s pending=%s proofs_explosion=%s proofs(bullet/fire/collision/melee/steam/p7/drown)=%s/%s/%s/%s/%s/%s/%s")
            :format(tostring(value.identity), tostring(value.dead), tostring(value.damageable),
                tostring(value.invincible), tostring(value.health), tostring(value.engine),
                tostring(value.body), tostring(value.driveable), tostring(value.control), tostring(value.owner),
                tostring(value.pending), proof("explosion"), proof("bullet"), proof("fire"), proof("collision"),
                proof("melee"), proof("steam"), proof("p7"), proof("drown"))
    end
    diagnostic = function(event, now)
        if not run then return end
        -- Reserve two of the bounded trace slots for the finale and cleanup.
        local cap = (run.phase == "explosion" or run.phase == "cleanup") and 24 or 22
        if (run.diagnostic_count or 0) >= cap then return end
        run.diagnostic_count = (run.diagnostic_count or 0) + 1
        local o, ped, car = run.observation or {}, run.ped or {}, run.vehicle or {}
        local actor=run.lester or {}
        local finale = run.explosion_before and (" backend=EXPLODE_VEHICLE accepted=%s raw_type=%s error=%s before={%s} immediate={%s} after={%s}")
            :format(tostring(run.explosion_accepted), tostring(run.explosion_raw_type), tostring(run.explosion_error),
                damage_text(run.explosion_before), damage_text(run.explosion_immediate), damage_text(run.explosion_after)) or ""
        log(("trace run=%s phase=%s event=%s task_ms=%s vehicle=%s in_any=%s on_foot=%s being_jacked=%s driver=%s seated=%s control(ped/car)=%s/%s owner(ped/car)=%s/%s pending(ped/car)=%s/%s frozen(ped/car)=%s:%s/%s:%s actor(control/owner/pending/protected/migration-requested)=%s/%s/%s/%s/%s remote_hold=%s seat_fallback=%s reason=%s%s")
            :format(tostring(run.run_id), tostring(run.phase), tostring(event),
                tostring(run.jack_started_ms and now - run.jack_started_ms or 0),
                tostring(o.current_vehicle), tostring(o.in_any), tostring(o.on_foot), tostring(o.being_jacked),
                tostring(o.driver), tostring(o.lester_seated), tostring(ped.observed_control), tostring(car.observed_control),
                tostring(ped.observed_owner), tostring(car.observed_owner),
                tostring(ped.observed_pending_owner), tostring(car.observed_pending_owner),
                tostring(ped.observed_fixed), tostring(ped.observed_network_fixed),
                tostring(car.observed_fixed), tostring(car.observed_network_fixed),
                tostring(actor.observed_control),tostring(actor.observed_owner),tostring(actor.observed_pending_owner),
                tostring(actor.protection_readback),tostring(actor.migration_locked),tostring(run.remote_hold_state),
                tostring(run.seat_fallback_accepted),tostring(run.reason), finale))
    end
    local function model_observation(handle, wrapper_model)
        local function u32(value) return integer(value) and value & 0xFFFFFFFF or nil end
        local function hex(value) return value and ("0x%08X"):format(value) or "unknown" end
        local function classify(model)
            if model == nil then return nil, "unknown", "model-unreadable" end
            local ok, value, raw, err = pcall(deps.invoke_bool_detail, H.CAR_MODEL, model)
            if not ok then return nil, "call-error", tostring(value) end
            if err ~= nil or not (type(raw) == "boolean" or raw == 0 or raw == 1) then
                return nil, tostring(raw), tostring(err)
            end
            return value == true, tostring(raw), tostring(err)
        end
        local native_model = read_int(H.MODEL, handle)
        local native_u32, wrapper_u32 = u32(native_model), u32(wrapper_model)
        local native_car, native_raw, native_error = classify(native_u32)
        local wrapper_car, wrapper_raw, wrapper_error = classify(wrapper_model)
        log(("model run=%s target=%s local=%s vehicle=%s model_native_raw=%s model_native_u32=%s model_wrapper_raw=%s model_wrapper_u32=%s car_native=%s raw=%s error=%s car_wrapper=%s raw=%s error=%s")
            :format(tostring(run.run_id), tostring(run.pid), tostring(run.local_id), tostring(handle),
                tostring(native_model), hex(native_u32), tostring(wrapper_model), hex(wrapper_u32),
                tostring(native_car), native_raw, native_error, tostring(wrapper_car), wrapper_raw, wrapper_error))
        return wrapper_car
    end
    local function prepare(now)
        local memory = deps.Memory
        if type(deps.GTA.CreatePed) ~= "function" or not memory or type(memory.AllocInt) ~= "function"
            or type(memory.WriteInt) ~= "function" or type(memory.ReadInt) ~= "function" or type(memory.Free) ~= "function" then
            begin_cleanup("documented actor creation/deletion support is unavailable", now); return
        end
        local available_ok, available = pcall(deps.player_available, run.pid)
        local snap_ok, snap = pcall(deps.player_snapshot, run.pid)
        if not available_ok or not available then begin_cleanup("selected player is unavailable", now); return end
        if not snap_ok then begin_cleanup("selected player snapshot is unreadable", now); return end
        if snap == nil then begin_cleanup("selected player is not streamed", now); return end
        if type(snap) ~= "table" then begin_cleanup("selected player snapshot is unreadable", now); return end
        run.local_id, run.session = local_id(), read_bool(H.SESSION)
        if run.local_id == nil or run.session == nil or (run.pid ~= run.local_id and not run.session) then
            begin_cleanup("player/session identity is unavailable", now); return
        end
        run.target_identity, run.local_identity = player_identity(run.pid, snap), player_identity(run.local_id)
        if not run.target_identity or not run.local_identity then begin_cleanup("player connection identity is unreadable", now); return end
        local ped = ped_for(run.pid)
        local ped_identity, ped_identity_error = physical(ped)
        if not ped_identity then
            begin_cleanup(ped_identity_error == "gone" and "selected player is not streamed"
                or "selected player physical identity is unreadable", now); return
        end
        local current_vehicle = read_int(H.CURRENT_VEHICLE, ped, false)
        if current_vehicle == nil then begin_cleanup("selected player vehicle identity is unreadable", now); return end
        if current_vehicle == 0 then
            begin_cleanup("selected player must be driving a vehicle", now); return
        end
        if (snap.ped and snap.ped ~= ped) or (snap.vehicle and snap.vehicle ~= current_vehicle) then
            begin_cleanup("selected player snapshot identity does not match", now); return
        end
        local vehicle_identity, vehicle_identity_error = physical(current_vehicle)
        if not vehicle_identity then
            begin_cleanup(vehicle_identity_error == "gone" and "selected vehicle is not streamed"
                or "selected vehicle physical identity is unreadable", now); return
        end
        for _, pending in ipairs(deferred) do
            local borrowed = pending.vehicle
            if borrowed and borrowed.address == vehicle_identity.address
                and borrowed.model == vehicle_identity.model and borrowed.network_id == vehicle_identity.network_id then
                begin_cleanup("this vehicle still has retained cleanup from an earlier Lester ride", now); return
            end
        end
        local occupant = read_int(H.DRIVER, current_vehicle, -1, false)
        if occupant == nil then begin_cleanup("selected vehicle driver is unreadable", now); return end
        if occupant ~= ped then begin_cleanup("selected player is not the driver", now); return end
        local ped_record, ped_error = baseline(ped)
        local vehicle_record, vehicle_error = baseline(current_vehicle)
        if not ped_record or not vehicle_record then
            begin_cleanup("cannot borrow frozen/unreadable entities: " .. tostring(ped_error or vehicle_error), now); return
        end
        run.ped, run.vehicle = ped_record, vehicle_record
        run.local_ped = physical(ped_for(run.local_id))
        if not run.local_ped then begin_cleanup("local player is not streamed", now); return end
        local target_position = vector(H.COORDS, ped, false)
        local car_position = vector(H.COORDS, current_vehicle, false)
        local local_position = vector(H.COORDS, run.local_ped.handle, false)
        if not target_position then begin_cleanup("selected player position is unreadable", now); return end
        if not car_position then begin_cleanup("selected vehicle position is unreadable", now); return end
        if not local_position then begin_cleanup("local player position is unreadable", now); return end
        local dx, dy, dz = target_position.x - local_position.x, target_position.y - local_position.y,
            target_position.z - local_position.z
        run.preflight_distance = math.sqrt(dx * dx + dy * dy + dz * dz)
        if not finite(run.preflight_distance) then begin_cleanup("measured player distance is unreadable", now); return end
        -- Capture before ownership requests or scene mutation. The 350m leash
        -- still bounds both entities during loading, hijack and flight.
        run.scene_origin = car_position
        log(("preflight run=%s native_distance=%.2fm snapshot_distance=%s"):format(
            tostring(run.run_id), run.preflight_distance, tostring(snap.distance)))
        local car_model = model_observation(current_vehicle, run.vehicle.model)
        if car_model == nil then begin_cleanup("vehicle model classification is unreadable", now); return end
        if car_model ~= true then
            local model=run.vehicle.model & 0xFFFFFFFF
            local vehicle_model,train,seats=read_bool(H.VEHICLE_MODEL,model),read_bool(H.TRAIN_MODEL,model),read_int(H.MODEL_SEATS,model)
            if vehicle_model~=true or train~=false or not seats or seats<1 or seats>32 then
                begin_cleanup("vehicle has no supported driver seat (trains and trailers excluded)",now);return
            end
            log("non-car driver-seat route admitted; seating and ejection must still be observed")
        end
        if read_bool(H.DEAD, ped, false) ~= false or read_bool(H.DEAD, current_vehicle, false) ~= false then
            begin_cleanup("player and car must be alive", now); return
        end
        local forward = vector(H.FORWARD, current_vehicle)
        run.heading = read_float(H.HEADING, current_vehicle)
        if not forward or run.heading == nil then begin_cleanup("car direction is unreadable", now); return end
        local length = math.sqrt(forward.x * forward.x + forward.y * forward.y)
        if length < 0.01 then begin_cleanup("car must be upright enough to determine forward direction", now); return end
        run.forward = { x = forward.x / length, y = forward.y / length }
        local original_lock = read_int(H.LOCK_GET, current_vehicle)
        if original_lock == nil or original_lock < 0 or original_lock > 10 then begin_cleanup("door-lock state is unreadable", now); return end
        run.vehicle.original_lock = original_lock
        local access_ok, access_error = capture_access()
        if not access_ok then begin_cleanup(access_error, now); return end
        for _, hash in ipairs({ H.MODEL_VALID, H.MODEL_IN_IMAGE, H.MODEL_PED }) do
            if read_bool(hash, LIMIT.lester_model) ~= true then begin_cleanup("Lester model is unavailable", now); return end
        end
        run.anim_requested = true
        if not scene_write(H.REQUEST_ANIM, HOLD_DICT) then begin_cleanup("hold animation request rejected",now);return end
        run.model_requested = true
        if not scene_write(H.REQUEST_MODEL, LIMIT.lester_model) then begin_cleanup("Lester model request was rejected", now); return end
        set_phase("model", now, LIMIT.model)
    end
    local function vehicle_blast(now)
        local scene = run
        if not scene or scene.blast_attempted or not scene_allowed() then return end
        local record = scene.vehicle
        local function current()
            local valid = run == scene and scene_allowed() and matches(record) ~= nil and has_control(record)
            return valid and run == scene and scene_allowed()
        end
        local function current_position()
            if not current() then return nil end
            local point
            local bone = read_int(H.BONE, record.handle, "seat_dside_f")
            if bone and bone >= 0 then point = vector(H.BONE_COORDS, record.handle, bone) end
            point = point or vector(H.COORDS, record.handle, false)
            return current() and point or nil
        end
        local point = current_position()
        if not point then return end
        -- Own a single effect attempt before entering constructors or host code.
        -- Host false/nil/errors are not a reason to stack another explosion.
        scene.blast_attempted = true
        scene.blast_size = VEHICLE_BLAST_SIZE
        local args
        local tag = deps.eExplosionTag and deps.eExplosionTag.EXP_TAG_CAR
        if tag ~= nil and deps.CExplosionArgs and type(deps.CExplosionArgs.New) == "function"
            and deps.V3 and type(deps.V3.New) == "function"
            and deps.GTA and type(deps.GTA.AddExplosion) == "function" then
            local built, value = pcall(function()
                local value = deps.CExplosionArgs.New(tag, deps.V3.New(point.x, point.y, point.z))
                value.NoFx = false
                value.MakeSound = true
                value.NoDamage = false
                value.IsLocalOnly = scene.session ~= true
                value.SizeScale = VEHICLE_BLAST_SIZE
                value.CamShake = 0.2
                value.ActivationDelay = 0
                return value
            end)
            if built and value then args = value
            else scene.blast_preparation_error = tostring(value) end
        end
        if not current() then return end
        point = current_position() -- do not use the car's original launch position
        if not point then return end
        scene.blast_position = point
        if scene.local_ped and matches(scene.local_ped) then
            local observer = vector(H.COORDS, scene.local_ped.handle, false)
            if observer then
                local dx, dy, dz = point.x-observer.x, point.y-observer.y, point.z-observer.z
                scene.blast_view_distance = math.sqrt(dx*dx+dy*dy+dz*dz)
            end
        end
        if args then
            local positioned, why = pcall(function()
                args.ExplosionPosition = deps.V3.New(point.x, point.y, point.z)
            end)
            if not positioned then scene.blast_preparation_error=tostring(why); args=nil end
        end
        if not current() then return end
        if args then
            scene.blast_backend = "GTA.AddExplosion/CAR"
            local sent, accepted = pcall(deps.GTA.AddExplosion, args)
            scene.blast_accepted = sent and accepted == true
            scene.blast_error = not sent and tostring(accepted)
                or accepted == false and "host-rejected"
                or accepted ~= true and "host-result-uncertain" or nil
        else
            -- Capability/construction fallback only, before any host blast call.
            -- Native damageScale is NOT a visual scale; keep it at normal damage.
            scene.blast_backend, scene.blast_size = "ADD_EXPLOSION/CAR", 1.0
            scene.blast_accepted = scene_write(H.EXPLOSION, point.x, point.y, point.z,
                VEHICLE_BLAST_TAG, 1.0, true, false, 0.2, false)
            scene.blast_error = not scene.blast_accepted and "native-blast-rejected" or nil
        end
        log(("blast run=%s backend=%s accepted=%s size=%s networked=%s view_distance=%s error=%s; destroyed state checked separately")
            :format(tostring(scene.run_id), tostring(scene.blast_backend), tostring(scene.blast_accepted),
                tostring(scene.blast_size), tostring(scene.session == true),
                tostring(scene.blast_view_distance), tostring(scene.blast_error)))
    end
    local function explode(now)
        if run.explosion_attempted then return end
        if not seated() or not player_departure_ready() or not has_control(run.vehicle) then
            begin_cleanup("finale cancelled: driver, ejected player, or vehicle authority changed", now); return
        end
        local position
        local bone = read_int(H.BONE, run.vehicle.handle, "seat_dside_f")
        if bone and bone >= 0 then position = vector(H.BONE_COORDS, run.vehicle.handle, bone) end
        position = position or vector(H.COORDS, run.vehicle.handle, false)
        if not position then begin_cleanup("current car position is unreadable", now); return end
        -- Mark before invoking: even an uncertain bridge result must not cause a retry.
        -- Lester remains invincible through the finale; cleanup deletes our actor.
        -- Optional evidence never becomes a new prerequisite for the finale.
        run.explosion_before = damage_observation(run.vehicle)
        if not scene_allowed() then return end
        local valid, reason = validate_current()
        if not valid then begin_cleanup(reason, now); return end
        if not seated() or not player_departure_ready() or not has_control(run.vehicle) then
            begin_cleanup("finale cancelled: driver, ejected player, or vehicle authority changed", now); return
        end
        if not scene_allowed() then return end
        run.explosion_attempted = true
        run.explosion_position = position
        local ok, accepted, raw, err = pcall(deps.invoke_void_detail, H.EXPLODE, run.vehicle.handle, true, false)
        run.explosion_accepted = ok and accepted == true and err == nil
        run.explosion_raw_type = ok and type(raw) or "call-error"
        run.explosion_error = not ok and tostring(accepted) or err ~= nil and tostring(err) or nil
        if scene_allowed() then run.explosion_immediate = damage_observation(run.vehicle) end
        -- One visible vehicle-type blast, with real explosion damage. A host
        -- acceptance is still not proof that this vehicle entered its wreck state.
        vehicle_blast(now)
        if not scene_allowed() then return end
        set_phase("explosion", now, LIMIT.explosion)
    end
    local function finish_damage(now)
        if run.damage_fallback_attempted or not scene_allowed() then return end
        if not matches(run.vehicle) or not has_control(run.vehicle) or not player_departure_ready() then return end
        if read_bool(H.DEAD,run.vehicle.handle,false) ~= false then return end
        run.damage_fallback_attempted = true
        local record, old = run.vehicle, run.explosion_before or {}
        record.damage_flags = {}
        local function damage(hash,...)
            if not scene_allowed() or not matches(record) or not has_control(record) then return false end
            return scene_write(hash,record.handle,...)
        end
        if old.invincible == true then
            record.damage_flags.invincible, record.damage_flags_owned = true, true
            if not damage(H.INVINCIBLE,false,false) then return end
        end
        if old.damageable == false then
            record.damage_flags.damageable, record.damage_flags_owned = false, true
            if not damage(H.SET_DAMAGEABLE,true) then return end
        end
        if old.proofs and old.proofs.explosion then
            record.damage_flags.proofs, record.damage_flags_owned = old.proofs, true
            local q=old.proofs
            if not damage(H.SET_PROOFS,q.bullet,q.fire,false,q.collision,q.melee,q.steam,q.p7,q.drown) then return end
        end
        if not damage(H.SET_ENGINE,-4000.0) or not damage(H.SET_BODY,0.0) or not damage(H.SET_TANK,-1000.0) then return end
        damage(H.EXPLODE,true,false)
        if scene_allowed() and matches(record) and read_bool(H.DEAD,record.handle,false) == false then
            damage(H.SET_HEALTH,0,0,0)
        end
        log("finale fallback submitted; destruction still requires death readback")
    end
    local function apply_flight(now)
        if run.last_flight_ms == now then return true end
        run.last_flight_ms = now
        return scene_write(H.ROTATION, run.vehicle.handle, LIMIT.pitch, 0.0, run.heading, 2, true)
            and scene_write(H.ANGULAR, run.vehicle.handle, 0.0, 0.0, 0.0)
            and scene_write(H.VELOCITY, run.vehicle.handle, run.forward.x * LIMIT.speed,
                run.forward.y * LIMIT.speed, flight_vertical_speed)
    end
    local function step(now)
        if run.cancel_reason then begin_cleanup(run.cancel_reason, now); cleanup(now, true); return end
        if run.phase == "queued" then
            run.started_ms = now
            prepare(now)
            if run and run.phase == "cleanup" then cleanup(now, true) end
            return
        end
        if run.phase == "cleanup" then cleanup(now, true); return end
        if run.phase == "debt" then return end
        local valid, reason = validate_current()
        if not valid then begin_cleanup(reason, now); cleanup(now, true); return end
        if now < run.started_ms or now - run.started_ms > LIMIT.total then
            begin_cleanup("scene timed out", now); cleanup(now, true); return
        end
        -- Authority recovery can return for many ticks; actor protection has an
        -- independent cadence and is serviced before that early return.
        if run.lester and not maintain_actor_protection(now) then
            begin_cleanup("Lester protection could not be maintained",now);cleanup(now,true);return
        end
        recover_entry_task(now)
        if not scene_allowed() then return end
        local authority_ok, recovery_now = recover_authority(now)
        now = recovery_now or now
        if not authority_ok then
            if run and run.phase == "cleanup" then cleanup(now, true) end
            return
        end
        -- Frame-only pairs expire without restoration. Do not disable the car's
        -- collision or the original carjack contact while the target is seated.
        if run.lester and matches(run.lester) and has_control(run.lester) then
            if run.ejected_verified and matches(run.ped) then
                scene_write(H.NO_COLLISION_PAIR,run.lester.handle,run.ped.handle,true)
            end
            if not scene_allowed() then return end
            if run.local_ped and run.local_ped.handle~=run.ped.handle and matches(run.local_ped) then
                scene_write(H.NO_COLLISION_PAIR,run.lester.handle,run.local_ped.handle,true)
            end
        end
        if not scene_allowed() then return end
        if run.phase ~= "explosion" and not access_unchanged(now) then
            begin_cleanup("personal-vehicle access changed during the scene", now); cleanup(now, true); return
        end
        if run.phase == "model" then
            if read_bool(H.MODEL_LOADED, LIMIT.lester_model) == true and read_bool(H.ANIM_LOADED,HOLD_DICT) == true then set_phase("control", now, LIMIT.control)
            elseif now >= run.deadline then begin_cleanup("Lester/hold animation loading timed out", now) end
        elseif run.phase == "control" then
            if driver() ~= run.ped.handle then begin_cleanup("driver changed before the scene began", now)
            elseif request_control(run.vehicle, now) then set_phase("hold", now, LIMIT.control)
            elseif now >= run.deadline then begin_cleanup("could not acquire control of the selected car", now) end
        elseif run.phase == "hold" then
            if driver() ~= run.ped.handle or not has_control(run.vehicle) then begin_cleanup("car control or driver changed", now); return end
            if not scene_write(H.VELOCITY, run.vehicle.handle, 0.0, 0.0, 0.0)
                or not scene_write(H.ANGULAR, run.vehicle.handle, 0.0, 0.0, 0.0) or not freeze_record(run.vehicle) then
                begin_cleanup("car freeze did not verify", now); return
            end
            if run.vehicle.original_lock ~= 1 then
                run.vehicle.lock_owned, run.vehicle.applied_lock = true, 1
                local accepted = scene_write(H.LOCK_SET, run.vehicle.handle, 1)
                local observed = read_int(H.LOCK_GET, run.vehicle.handle)
                if observed == 1 or observed == nil then run.vehicle.lock_owned = true end
                if not accepted or observed ~= 1 then
                    begin_cleanup("could not unlock the car for Lester", now); return
                end
            end
            set_phase("spawn", now, LIMIT.control)
        elseif run.phase == "spawn" then
            if not has_control(run.vehicle) or not frozen(matches(run.vehicle)) or driver() ~= run.ped.handle then
                begin_cleanup("car changed before Lester spawned", now); return
            end
            local position = vector(H.COORDS, run.vehicle.handle, false)
            if not position or type(deps.GTA.CreatePed) ~= "function" then begin_cleanup("Lester spawning is unavailable", now); return end
            if not scene_allowed() then return end
            local ok, handle = pcall(deps.GTA.CreatePed, LIMIT.lester_model, 4,
                position.x - run.forward.y * 2.5, position.y + run.forward.x * 2.5,
                position.z, run.heading, true, true)
            if not ok or not integer(handle) or handle == 0 then begin_cleanup("Lester creation failed", now); return end
            local candidate = physical(handle)
            local alias = false
            for _, record in ipairs({ run.ped, run.vehicle, run.local_ped }) do
                if handle == record.handle or (candidate and candidate.address == record.address) then alias = true end
            end
            if not candidate or candidate.model ~= LIMIT.lester_model or alias then
                -- A model/address identity is required before any delete can be safe.
                run.unresolved_spawn = handle
                run.retired = (run.retired or 0) + 1
                begin_cleanup("spawned Lester identity could not be verified; engine auto-cleanup retained", now); return
            end
            run.lester = candidate
            run.lester.live = true
            if not scene_allowed() then return end
            if not maintain_actor_protection(now,true) then begin_cleanup("Lester initial protection was rejected",now);return end
            set_phase("actor_control", now, LIMIT.control)
        elseif run.phase == "actor_control" then
            if not has_control(run.vehicle) or not frozen(matches(run.vehicle)) then begin_cleanup("car hold was lost", now); return end
            if request_control(run.lester, now) then
                local access_ok, access_error = borrow_access(now)
                if not access_ok then begin_cleanup(access_error, now); return end
                if not maintain_actor_protection(now,true) then begin_cleanup("Lester protection was rejected",now);return end
                if not scene_write(H.TARGETTABLE, run.lester.handle, false)
                    or not scene_write(H.DRAGGABLE, run.lester.handle, false)
                    or not scene_write(H.PED_FLAG, run.lester.handle, 398, true)
                    or not scene_write(H.PED_FLAG, run.lester.handle, 141, true)
                    or not scene_write(H.BLOCK_EVENTS, run.lester.handle, true)
                    or not scene_write(H.KEEP_TASK, run.lester.handle, true)
                    or not scene_write(H.ENTER, run.lester.handle, run.vehicle.handle, LIMIT.jack, -1, 1.0, 8, 0) then
                    begin_cleanup("Lester entry task was rejected", now); return
                end
                run.task_issued = true
                run.jack_started_ms, run.jack_deadline_ms = now, now + LIMIT.jack
                set_phase("jack", now, LIMIT.jack)
            elseif now >= run.deadline then begin_cleanup("could not control the spawned Lester", now) end
        elseif run.phase == "jack" then
            if not has_control(run.vehicle) or not frozen(matches(run.vehicle)) or not has_control(run.lester) then
                begin_cleanup("ownership or car hold was lost during the hijack", now); return
            end
            local occupant = driver()
            if occupant == nil or (occupant ~= 0 and occupant ~= run.ped.handle and occupant ~= run.lester.handle) then
                begin_cleanup("another driver took the car", now); return
            end
            local o = run.observation or {}
            local fully_out = o.on_foot == true and o.in_any == false and o.being_jacked == false
                and occupant ~= run.ped.handle
            if fully_out then run.ejection_since_ms = run.ejection_since_ms or now
            else run.ejection_since_ms = nil end
            if fully_out and now - run.ejection_since_ms >= LIMIT.ejection then
                run.ejected_verified = true
                run.ejected_verified_at = run.ejected_verified_at or now
                set_phase("ped_control", now, math.min(LIMIT.control, math.max(1, run.deadline - now)))
            elseif now >= run.deadline then begin_cleanup("Lester could not complete the hijack before timeout", now) end
        elseif run.phase == "ped_control" then
            if now >= run.jack_deadline_ms then begin_cleanup("Lester could not complete the hijack before timeout", now); return end
            if not has_control(run.vehicle) or not frozen(matches(run.vehicle)) or not has_control(run.lester) then
                begin_cleanup("car/Lester control was lost", now); return
            end
            if read_bool(H.ON_FOOT, run.ped.handle) ~= true or read_bool(H.IN_ANY, run.ped.handle, false) ~= false
                or read_bool(H.BEING_JACKED, run.ped.handle) ~= false then
                begin_cleanup("player did not remain fully out of the car", now); return
            end
            if run.pid~=run.local_id then
                -- One best-effort remote hold attempt. Remote ped authority is
                -- not a condition for operating our actor in the controlled car.
                run.remote_hold_state="unavailable"
                if request_control(run.ped,now) and scene_allowed() and has_control(run.ped) then
                    if scene_write(H.VELOCITY,run.ped.handle,0.0,0.0,0.0) and freeze_record(run.ped) then
                        run.held_position=vector(H.COORDS,run.ped.handle,false)
                        if begin_player_hold(now) then
                            maintain_player_hold(now);run.remote_hold_state="requested"
                        else run.remote_hold_state="partial; cleanup retained" end
                    end
                end
                if scene_allowed() then
                    log("Remote action hold "..run.remote_hold_state.."; ejection and Lester seating remain required")
                    set_phase("ped_hold",now,math.max(1,run.jack_deadline_ms-now))
                end
            elseif request_control(run.ped, now) then
                if not scene_write(H.VELOCITY, run.ped.handle, 0.0, 0.0, 0.0) or not freeze_record(run.ped) then
                    begin_cleanup("player immobility did not verify", now); return
                end
                run.held_position = vector(H.COORDS, run.ped.handle, false)
                if not begin_player_hold(now) then begin_cleanup("player action state unreadable",now);return end
                maintain_player_hold(now)
                set_phase("ped_hold", now, math.max(1, run.jack_deadline_ms - now))
            elseif now >= run.deadline then begin_cleanup("remote player control was unavailable; launch cancelled", now) end
        elseif run.phase == "ped_hold" then
            maintain_player_hold(now)
            vacant_seat_fallback(now)
            if run.pid==run.local_id and not held_player() and now - run.pose_started_ms < 1000 then return end
            if now >= run.jack_deadline_ms then begin_cleanup("Lester never reached the driver seat before timeout", now); return end
            if not player_departure_ready() or not has_control(run.vehicle) or not frozen(matches(run.vehicle)) or not has_control(run.lester) then
                begin_cleanup("player departure or vehicle control did not hold", now); return
            end
            if now - run.phase_started_ms >= LIMIT.hold and seated() then
                -- The live failure log shows CLEAR_PED_TASKS_IMMEDIATELY
                -- removing Lester from his already verified driver seat. Keep
                -- the seated task intact: scripted vehicle velocity needs no
                -- task clear. Verify occupancy and authority before release.
                local scene = run
                local valid = validate_current()
                if run ~= scene or not scene_allowed() then return end
                if not valid or not has_control(run.lester) or not has_control(run.vehicle)
                    or not seated() or not player_departure_ready() or not frozen(matches(run.vehicle)) then
                    begin_cleanup("Lester departure lost seating or authority", now); return
                end
                run.flight_task_handoff = true
                diagnostic("flight-task-handoff", now)
                run.flight_origin = vector(H.COORDS, run.vehicle.handle, false)
                if not run.flight_origin then begin_cleanup("launch position is unreadable", now); return end
                -- Release only our car freeze; retain the borrowed door lock until cleanup.
                if not scene_write(H.FREEZE, run.vehicle.handle, false) then begin_cleanup("car release failed", now); return end
                local current = matches(run.vehicle)
                if not readable_freeze(current) or frozen(current) then begin_cleanup("car release did not verify", now); return end
                run.vehicle.freeze_owned = false
                run.flight_started_ms, run.last_flight_ms = now, nil
                set_phase("flight", now, LIMIT.flight)
                -- Do not leave a released car running the entry task until the
                -- next scheduler tick before its first physics command.
                if not apply_flight(now) then begin_cleanup("flight physics command was rejected", now) end
            elseif now >= run.deadline then begin_cleanup("Lester never reached the driver seat", now) end
        elseif run.phase == "flight" then
            maintain_player_hold(now)
            if not seated() or not player_departure_ready() or not has_control(run.vehicle) or not has_control(run.lester) then
                begin_cleanup("flight authority, Lester seating, or player departure changed", now); return
            end
            local vehicle_now = matches(run.vehicle)
            if not readable_freeze(vehicle_now) or frozen(vehicle_now) then begin_cleanup("car was externally frozen during flight", now); return end
            local position = vector(H.COORDS, run.vehicle.handle, false)
            if not position then begin_cleanup("flight position is unreadable", now); return end
            run.flight_ascent = position.z - run.flight_origin.z
            if run.flight_ascent >= 2.0 and not run.flight_verified then
                run.flight_verified = true
                log(("flight ascent observed: %.2fm after %sms"):format(run.flight_ascent, tostring(now - run.flight_started_ms)))
                diagnostic("flight-ascent-observed", now)
            end
            -- A void physics setter being accepted does not establish flight.
            -- Require observed height gain before permitting the finale.
            if not run.flight_verified and now - run.flight_started_ms >= LIMIT.ascent then
                begin_cleanup("vehicle ascent was not observed; launch cancelled", now); return
            end
            if now >= run.deadline then explode(now); return end
            if not apply_flight(now) then begin_cleanup("flight physics command was rejected", now) end
        elseif run.phase == "explosion" then
            maintain_player_hold(now)
            if now-run.phase_started_ms >= 200 then finish_damage(now) end
            if not scene_allowed() then return end
            if read_bool(H.DEAD, run.vehicle.handle, false) == true then
                run.explosion_verified = true
                run.explosion_after = damage_observation(run.vehicle)
                begin_cleanup("vehicle explosion observed", now)
            elseif now >= run.deadline then
                run.explosion_after = damage_observation(run.vehicle)
                begin_cleanup("vehicle destruction was not observed after the bounded finale", now)
            end
        end
        if run and run.phase == "cleanup" then cleanup(now, true) end
    end

    function api.Start(pid)
        pid = tonumber(pid)
        if not integer(pid) or pid < 0 or pid > 31 then return false, "invalid player" end
        if busy then return false, "Lester is finishing the current tick; try again" end
        local missing = unavailable()
        if missing then return false, missing end
        if quiesced then return false, "Lester Ride is stopping" end
        if run then
            local ped = run.ped or {}
            local car_only = run.phase == "debt" and run.lester == nil
                and not ped.freeze_owned and not ped.hold_owned and not ped.damage_flags_owned and not ped.owner_owed
            if not car_only then return false, "a Lester Ride or its cleanup is already active" end
            if run.pid == pid then return false, "this player's previous vehicle cleanup is still pending" end
            if #deferred >= DEFERRED_LIMIT then return false, "Lester cleanup backlog is full; retained vehicles are still being restored" end
            deferred[#deferred + 1], run = run, nil
        end
        for _, pending in ipairs(deferred) do
            if pending.pid == pid then return false, "this player's previous vehicle cleanup is still pending" end
        end
        serial = serial + 1
        run = { run_id = serial, pid = pid, phase = "queued", reason = "queued", retired = 0 }
        return true, "queued"
    end
    function api.Cancel(pid, reason)
        if not run then return true end
        if pid ~= nil and tonumber(pid) ~= run.pid then return false, "different player" end
        run.cancel_reason = tostring(reason or "cancelled")
        if run.phase == "debt" then run.phase = "cancel_requested" end
        return true
    end
    function api.Tick(now)
        if busy or quiesced then return end
        now = clock(now)
        busy = true
        retry_deferred(now, false, false)
        busy = false
        if not run then return end
        if run.phase == "debt" then
            now=clock(now)
            busy=true
            -- Protection is independent of the throttled ownership/delete retry.
            -- Validate session provenance before touching a retained actor.
            if cleanup_scope()==true then pcall(maintain_actor_protection,now) end
            if now < (run.next_debt_retry_ms or 0) then busy=false;return end
            local ok,err=pcall(cleanup,now,true)
            if run then run.next_debt_retry_ms=now+1000 end
            if not ok then log("cleanup retry: "..tostring(err)) end
            busy=false
            return
        end
        busy = true
        now = clock(now)
        last_now = now
        local ok, err = pcall(step, now)
        if not ok and run then
            begin_cleanup("runtime error: " .. tostring(err), now)
            log(run.reason)
        end
        if quiesced and run then pcall(api.RestorePersistentState) end
        busy = false
    end
    function api.IsActive() return run ~= nil or #deferred > 0 end
    function api.Snapshot() return snapshot() end
    function api.OwnsActor(handle, address, network_id)
        local actor = run and run.lester
        return actor ~= nil and not actor.retired and handle == actor.handle
            and address == actor.address and network_id == actor.network_id
    end
    function api.LocalInteractionActive(pid)
        return scene_allowed() and run.pid == pid and run.local_id == pid and run.lester ~= nil
            and run.lester.live ~= false and not run.lester.retired
            and run.phase ~= "cleanup" and run.phase ~= "debt" and run.phase ~= "cancel_requested"
    end
    function api.DrainUnload(now)
        if not run and #deferred == 0 then return true end
        if busy then
            api.Cancel(nil, "unload requested")
            return false, "cleanup queued behind the current native operation"
        end
        busy = true
        now = clock(now)
        last_now = now
        drain_epoch = epoch
        for _ = 1, #deferred do retry_deferred(now, true, false) end
        local ok, result = true, true
        if run then
            begin_cleanup("unload requested", now)
            ok, result = pcall(cleanup, now, true)
        end
        drain_epoch = nil
        if not ok then log("Unload cleanup error: " .. tostring(result)) end
        busy = false
        return ok and result == true and #deferred == 0,
            run and table.concat(debts(), ", ") or (#deferred > 0 and tostring(#deferred) .. " retained vehicle cleanup records" or nil)
    end
    function api.Quiesce(reason)
        epoch = epoch + 1
        quiesced = true
        if run then run.cancel_reason = tostring(reason or "module stopping") end
    end
    function api.RestorePersistentState()
        if not run and #deferred == 0 then return true end
        if restoring_flags then return false, "persistent restoration already running" end
        restoring_flags = true
        -- Unload-worker fallback: owned freeze/lock setters only;
        -- no ownership requests, resources, tasks, streaming, allocation, freeing,
        -- deletion, or new scene progression.
        for _ = 1, #deferred do retry_deferred(last_now, true, true) end
        local ok, ped_ok, car_ok = true, true, true
        if run then ok, ped_ok, car_ok = pcall(restore_persistent, last_now, false) end
        restoring_flags = false
        if not ok then return false, tostring(ped_ok) end
        return ped_ok and car_ok and (not run or run.lester==nil) and #deferred == 0,
            table.concat(debts(), ", ") .. (#deferred > 0 and ("; " .. tostring(#deferred) .. " retained vehicle cleanup records") or "")
    end
    instances[#instances + 1] = api
    return api
end

function Module.Init(context)
    assert(type(context) == "table" and type(context.Modules) == "table", "lester_ride requires a module context")
    assert(not module_context or module_context == context, "lester_ride already initialized")
    module_context = context
    context.Modules.LesterRide = Module
end
function Module.Start()
    assert(module_context, "lester_ride started before initialization")
    module_started = true
end
function Module.Stop()
    module_started = false
    for _, api in ipairs(instances) do
        api.Quiesce("module stopping")
        pcall(api.RestorePersistentState)
    end
end
function Module.Restore(context)
    context = context or module_context
    for _, api in ipairs(instances) do api.Quiesce("module restored") end
    if context and context.Modules and context.Modules.LesterRide == Module then context.Modules.LesterRide = nil end
    module_context, module_started = nil, false
    instances = {}
end

return Module
]====],
