-- Selected-player vehicle effects with CScript-owned lifecycle and cleanup.
local Module = { Name = "modules.vehicle_chaos", MigrationPhase = "17.75" }
-- Shared creation path: create at the requested pose, then let the caller
-- retain the returned handle before identity capture and type-specific setup.
local function create_scene_entity(gta, is_ped, model, pose, ped_type)
    if is_ped then
        return gta.CreatePed(model, ped_type,
            pose.x + 0.0, pose.y + 0.0, pose.z + 0.0, pose.heading + 0.0, true, true)
    end
    return gta.SpawnVehicle(model, pose.x, pose.y, pose.z, pose.heading, true, true)
end

-- Legacy eight-slot support remains for older shared spawn helpers, but the
-- selected-player Baller toggle below now owns its own 96-ped LOCAL visual.
-- Keep legacy bounds conservative even if a bypass calls the old helper.
local BALLER_WAVES = 1
local BALLER_PED_LIMIT = 8
local BALLER_SLOT_COUNT = 8
local BALLER_FIRST_WAVE = BALLER_SLOT_COUNT
local BALLER_WAVE_PAUSE_MS = 250
local BALLER_RING_RADIUS = 0.60 -- Fixed eight-position platform ring.
-- Reassert physical hold without hammering 512 peds every frame.
-- Each stationary tick inspects only a slice for drift/falls, while a moving
-- target still updates all eight overlapping slots from one shared pose.
local BALLER_HARDEN_EVERY_MS = 1200
local BALLER_AI_REFRESH_EVERY_MS = 2500
local BALLER_DRIFT_BATCH = 64
local BALLER_DRIFT_TOLERANCE_SQ = 0.05 * 0.05
-- Some networked peds can migrate out of local control after creation.
-- Recover only originally tracked peds and never flood network-control requests.
local BALLER_CONTROL_RETRY_MS = 1800
local BALLER_CONTROL_REQUESTS_PER_PASS = 2
local BALLER_OWNERSHIP_LOG_MS = 3000
local function baller_requested_count() return math.min(8, BALLER_PED_LIMIT) end
local BALLER_HOVER_HEIGHT = 4.0
local BALLER_HOLD_EVERY_MS = 50

-- Identical slot inputs give identical XYZ and heading, regardless of wave.
-- The ring's heading is captured once at activation and never changes when
-- the target turns; only the center follows the target's position.
local function baller_slot_pose(slot, center, ring_heading)
    local angle = math.rad(ring_heading or 0.0) +
        (((slot - 1) % BALLER_SLOT_COUNT) * (2.0 * math.pi / BALLER_SLOT_COUNT))
    return {
        x = center.x + BALLER_RING_RADIUS * math.cos(angle),
        y = center.y + BALLER_RING_RADIUS * math.sin(angle),
        z = center.z + BALLER_HOVER_HEIGHT,
        heading = (math.deg(angle) + 90.0) % 360.0,
    }
end

-- Tug Pair uses the same reference vehicle spawn/placement/cleanup path as Penis.
-- The cap controls total birth attempts AND concurrently tracked Tug vehicles.
local LIMIT = 250 -- Fixed cap: two networked Tug boats per selected-player activation.

local module_context, __public_binding
local __public_stopped, __public_teardown, __public_faulted = true, false, false
-- Public-only action admission. Both this direct API and Cherax feature
-- callbacks must deny new producers without the live Donator entitlement.
-- Read/cleanup/cancel paths deliberately remain available to all tiers.
local function __public_bind(context)
    assert(not __public_teardown and not __public_faulted, "Public API cleanup is incomplete")
    assert(module_context == nil or module_context == context, "Public API already has a context")
    if __public_binding and __public_binding.context == context then return end
    local cs = context and context.CScript
    local auth = type(cs) == "table" and cs.Entitlements
    local allowed = type(auth) == "table" and auth.IsAllowed
    assert(type(cs) == "table" and cs.DistributionMode == "public"
        and type(allowed) == "function", "Public API authorization is required")
    __public_binding = {context=context, allowed=allowed}
    __public_stopped = false
end
local function __public_live(binding)
    return binding ~= nil and binding == __public_binding
        and module_context == binding.context and not __public_stopped
        and not __public_teardown and not __public_faulted
end
local function __public_vehicle_allowed(binding, effect_key)
    if not __public_live(binding) then return false end
    local ok, allowed = pcall(binding.allowed, "modules.vehicle_chaos", effect_key)
    return ok and allowed == true and __public_live(binding)
end

local instances = {}
