    character_baller = "character_baller",
    penis = "evilage",
    tug_pair = "tug",
    cargoplane_pile = "cargoplane",
    ruiner_pimp =
    "ruiner pimp",
    vehicle_circle = "evilage",
    trevor_michael = "avisa",
    pistol_circle = "submersible2"
}
-- Keep the registered IDs and editable duo_/pickup_ fields stable while
-- replacing the former ped actions with the circle and original vehicle paths.
local REPLACEMENT_MODELS = {
    tug_pair = "tug",
    trevor_michael = "avisa",
    pistol_circle = "submersible2",
    cargoplane_pile =
    "cargoplane"
}
local DEFAULT_PRESENTATION = {
    pickup_name = "anti-banana weapon",
    pickup_description = "Spawns Kraken submarines around this player.",
    circle_name = "Exorcism shyt fine shyte kurwa",
    circle_description = "Dense inward-facing vehicle circle around this player.",
    duo_name = "steroid crash",
    duo_description = "Avisa submarines spawn in a dense circle around this player.",
    name = "HIV crash",
    description = "Spawns vehicles around the selected player.",
    category = "Naughty removals",
    penis_name = "penis crash",
    penis_description = "Spawns vehicles around the selected player.",
}
local presentation = DEFAULT_PRESENTATION

local function copy_presentation(values)
    local out = {}
    for key in pairs(DEFAULT_PRESENTATION) do out[key] = values[key] end
    return out
end

local function load_presentation(host)
    local result = copy_presentation(DEFAULT_PRESENTATION)
    local files = host and host.FileMgr
    if not files or type(files.GetMenuRootPath) ~= "function" or
        type(files.DoesFileExist) ~= "function" or type(files.ReadFileContent) ~= "function" then
        return result
    end
    local ok, content = pcall(function()
        local root = files.GetMenuRootPath()
        if type(root) ~= "string" or root == "" then return nil end
        local path = root:gsub("[/\\]+$", "") .. "\\Lua\\CScript\\vehicle_effect.txt"
        if not files.DoesFileExist(path) then return nil end
        return files.ReadFileContent(path)
    end)
    if not ok or type(content) ~= "string" or #content > 8192 then return result end
    -- Read plain text once per load. Names are never executed as Lua, and
    -- changing display text does not change the registered feature ID.
    content = content:gsub("^\239\187\191", "")
    for line in content:gmatch("[^\r\n]+") do
        local key, value = line:match("^%s*([%a_]+)%s*=%s*(.-)%s*$")
        if key and DEFAULT_PRESENTATION[key] and value ~= "" and not value:find("%c") then
            local limit = key:match("description$") and 1024 or 160
            if key == "pickup_name" and (value == "Monkey Drops" or value == "Mixed Crowd") then
                value = DEFAULT_PRESENTATION.pickup_name
            elseif key == "duo_name" and value == "Trevor + Michael" then
                value = DEFAULT_PRESENTATION.duo_name
            elseif key == "pickup_description" and (value == "Loose pistol pickups placed on the ground using the original spawn pattern."
                    or value == "Pistols spawn above this player's head and fall under gravity."
                    or value == "Monkey peds fall from above this player, with active AI and physics."
                    or value == "Monkey peds spawn in the same tight ring as Vehicle Circle, with active physics."
                    or value == "Frozen monkey peds spawn rapidly in the same tight ring as Vehicle Circle."
                    or value == "Frozen chimps, dogs, boars, coyotes, Franklin and Lamar spawn in a dense circle."
                    or value == "Kraken submarines spawn in a dense circle around this player.") then
                value = DEFAULT_PRESENTATION.pickup_description
            elseif key == "duo_description" and (value == "Rapid overlapping pairs, frozen at the starting position."
                    or value == "Trevor and Michael spawn separately with active AI and physics; automatic cleanup follows the run."
                    or value == "Trevor and Michael spawn in the same tight ring as Vehicle Circle, with active AI and physics."
                    or value == "Frozen Trevor and Michael pairs spawn rapidly in the same tight ring as Vehicle Circle.") then
                value = DEFAULT_PRESENTATION.duo_description
            end
            if #value <= limit then result[key] = value end
        end
    end
    return result
end

function Module.GetPresentation()
    return copy_presentation(presentation)
end

local DEFAULT_VARIANTS = {
    { key = "vehicle_variant_1", name = "Femboy crash",                 model = "deluxo",     view = "hover" },
    { key = "vehicle_variant_2", name = "Al-Qaida demonstration",       model = "hunter",     view = "shuttle" },
    { key = "vehicle_variant_3", name = "Cryhard crash ong",            model = "toreador",   view = "shuttle" },
    { key = "vehicle_variant_4", name = "Degen splash cash dashcam",     model = "dominator7", view = "shuttle" },
}
local function copy_variant(value)
    return {
        key = value.key,
        name = value.name,
        description = value.description,
        model = value.model,
        preset = value.preset,
        view = value.view,
        camera_height = value.camera_height
    }
end
local function default_variants()
    local out = {}
    for i, value in ipairs(DEFAULT_VARIANTS) do
        out[i] = copy_variant(value)
        out[i].preset = ""
        out[i].camera_height = 10000.0
        out[i].description = value.view == "shuttle" and
            "Vehicle stream with repeated teleports between above the target and your original position; ends at origin."
            or "erectile dysfunction ahh"
    end
    return out
end
local variants = default_variants()
local function load_variants(host)
    local out = default_variants()
    local files = host and host.FileMgr
    if not files or type(files.GetMenuRootPath) ~= "function" or type(files.DoesFileExist) ~= "function"
        or type(files.ReadFileContent) ~= "function" then
        return out
    end
    local ok, content = pcall(function()
        local root = files.GetMenuRootPath()
        if type(root) ~= "string" or root == "" then return nil end
        local path = root:gsub("[/\\]+$", "") .. "\\Lua\\CScript\\vehicle_variants.txt"
        return files.DoesFileExist(path) and files.ReadFileContent(path) or nil
    end)
    if not ok or type(content) ~= "string" or #content > 16384 then return out end
    content = content:gsub("^\239\187\191", "")
    local descriptions = {}
    for line in content:gmatch("[^\r\n]+") do
        local index, field, value = line:match("^%s*variant_([1-4])_([%a_]+)%s*=%s*(.-)%s*$")
        local entry = index and out[tonumber(index)]
        if entry and not value:find("%c") then
            if field == "name" and #value > 0 and #value <= 160 then
                entry.name = value
            elseif field == "description" and #value > 0 and #value <= 1024 then
                entry.description = value; descriptions[tonumber(index)] = true
            elseif field == "model" and #value > 0 and #value <= 64 and value:match("^[%w_%-]+$") then
                entry.model = value
            elseif field == "preset" and #value <= 160 and not value:find('[/\\:*?"<>|]') and not value:find("..", 1, true) then
                entry.preset = value:gsub("%.[jJ][sS][oO][nN]$", "")
            elseif field == "view" and (value == "hover" or value == "shuttle" or value == "sky") then
                entry.view = value == "sky" and "shuttle" or value
            elseif field == "camera_height" then
                local n = tonumber(value)
                if n and n == n and n >= 1000 and n <= 20000 then entry.camera_height = n end
            end
        end
    end
    for i, entry in ipairs(out) do
        if not descriptions[i] then
            entry.description = entry.view == "shuttle" and
                "Vehicle stream with repeated teleports between above the target and your original position; ends at origin."
                or "erectile dysfunction ahh"
        end
    end
    return out
end
function Module.GetVariants()
    local out = {}
    for i, value in ipairs(variants) do out[i] = copy_variant(value) end
    return out
end

-- Shared lobby allocation backend. Poll on native-thread
-- scheduler turns; this adapter never loops or yields while a model is loading.
function Module.NewSpawnBackend(host, options)
    error("Standalone backend is unavailable in the Public build", 2)
    options = options or {}
    local model = options.model
    assert(type(model) == "number" and model == model and model % 1 == 0 and model ~= 0
        and model >= -2147483648 and model <= 4294967295, "invalid vehicle model")
    model = model % 4294967296
    local mode = options.backend or "native"
    assert(mode == "native" or mode == "helper", "unknown spawn backend")
    local natives, gta = assert(host.Natives), host.GTA or {}
    local clock = assert(host.Time and host.Time.GetEpocheMs)
    local closed, requested, release_due = false, false, false
    local next_request, waiting_since = 0, nil
    local stats = {
        backend = mode,
        calls = 0,
        returned = 0,
        zero_returns = 0,
        errors = 0,
        total_ms = 0,
        max_ms = 0,
        last_ms = 0,
        model_wait_ms = 0,
        model_requests = 0,
        inflight = 0
    }
    local api = {}
    local function release()
        if release_due and stats.inflight == 0 and requested then
            local ok, value = pcall(natives.InvokeVoid, 0xE532F5D78798DAAB, model)
            if ok and value ~= false then
                requested = false; release_due = false
            end
        end
    end
    function api.Poll()
        if closed then return false, "closed" end
        local now = clock()
        if not requested then
            local ok, value = pcall(natives.InvokeVoid, 0x963D27A58DF860AC, model)
            if not ok or value == false then return false, "model request rejected" end
            requested = true; next_request = now + 250; stats.model_requests = stats.model_requests + 1
        end
        local ok, loaded = pcall(natives.InvokeBool, 0x98A4EB5D89A0C952, model)
        if closed then return false, "closed" end
        if ok and (loaded == true or loaded == 1) then
            if waiting_since then
                stats.model_wait_ms = stats.model_wait_ms + math.max(0, now - waiting_since); waiting_since = nil
            end
            return true
        end
        if not waiting_since then waiting_since = now end
        if now >= next_request then
            next_request = now + 250
            local called, value = pcall(natives.InvokeVoid, 0x963D27A58DF860AC, model)
            if called and value ~= false then stats.model_requests = stats.model_requests + 1 end
        end
        return false, "model pending"
    end

    function api.Create(pose, networked)
        if closed then return false, nil, "closed" end
        if type(pose) ~= "table" or type(networked) ~= "boolean" then return false, nil, "invalid allocation arguments" end
        for _, key in ipairs({ "x", "y", "z", "heading" }) do
            local v = pose[key]
            if type(v) ~= "number" or v ~= v or math.abs(v) == math.huge then return false, nil, "invalid spawn pose" end
        end
        local ready, why = api.Poll()
        if not ready then return false, nil, why end
        local allocate
        if mode == "native" then allocate = natives.InvokeInt else allocate = gta.SpawnVehicle end
        if type(allocate) ~= "function" then return false, nil, mode .. " allocator unavailable" end
        if closed then return false, nil, "closed" end
        stats.calls = stats.calls + 1; stats.inflight = stats.inflight + 1
        local started = clock()
        local ok, result
        if mode == "native" then
            -- Full Gen9 signature. Last flag is NOT Cherax's autoCleanup flag.
            ok, result = pcall(allocate, 0xAF35D0D2583051B0, model,
                pose.x + 0.0, pose.y + 0.0, pose.z + 0.0, pose.heading + 0.0,
                networked, networked, pose.z < -100.0)
        else
            ok, result = pcall(allocate, model, pose.x + 0.0, pose.y + 0.0, pose.z + 0.0,
                pose.heading + 0.0, networked, true)
        end
        local elapsed = math.max(0, clock() - started)
        stats.inflight = stats.inflight - 1; stats.last_ms = elapsed
        stats.total_ms = stats.total_ms + elapsed; stats.max_ms = math.max(stats.max_ms, elapsed)
        release()
        if not ok then
            stats.errors = stats.errors + 1; stats.last_error = tostring(result); return false, nil, stats.last_error
        end
        if type(result) ~= "number" or result ~= result or result % 1 ~= 0 or result == 0 then
            stats.zero_returns = stats.zero_returns + 1; return false, nil, "no entity handle"
        end
        stats.returned = stats.returned + 1
        -- Even after cancellation, return a late handle so the caller records
        -- its cleanup obligation. Never silently create a fallback duplicate.
        return true, result
    end

    function api.Close()
        if waiting_since then
            stats.model_wait_ms = stats.model_wait_ms + math.max(0, clock() - waiting_since)
            waiting_since = nil
        end
        closed = true; release_due = true; release()
    end

    function api.Snapshot()
        local copy = {}; for k, v in pairs(stats) do copy[k] = v end
        copy.closed = closed; copy.model = model
        copy.model_wait_ms = copy.model_wait_ms + (waiting_since and math.max(0, clock() - waiting_since) or 0)
        copy.average_ms = stats.calls > 0 and stats.total_ms / stats.calls or 0
        return copy
    end

    return api
end

-- CNetObject:GetEntity is invalid for doors. Registry keys can be reused,
-- so even read-only diagnostics must check a supported physical type first.
local NETWORK_PHYSICAL_TYPES = {
    [0] = true,
    [1] = true,
    [2] = true,
    [4] = true,
    [5] = true,
    [6] = true,
    [7] = true,
    [9] = true,
    [10] = true,
    [11] = true,
    [12] = true,
    [13] = true
}
local NETWORK_VEHICLE_TYPES = {
    [0] = true,
    [1] = true,
    [2] = true,
    [4] = true,
    [9] = true,
    [10] = true,
    [12] = true,
    [13] = true
}
local function registry_entity(object, anchor)
    local ok, kind = pcall(function() return object.ObjectType end)
    if not ok or type(kind) ~= "number" or kind ~= kind or kind % 1 ~= 0 then return nil, "object_type_unknown" end
    if not NETWORK_PHYSICAL_TYPES[kind] then return nil, "unsupported_object_type" end
    if anchor then
        if anchor.entity_kind == "ped" and kind ~= 6 then return nil, "ped_type_disagrees" end
        if anchor.entity_kind == "vehicle" and not NETWORK_VEHICLE_TYPES[kind] then return nil, "vehicle_type_disagrees" end
        if anchor.object_type ~= nil and kind ~= anchor.object_type then return nil, "object_type_changed" end
    end
    local entity = object:GetEntity()
    return entity, entity and "matched" or "entity_unknown"
end

-- BEGIN BALLER_PLATFORM_8
-- Dense Kaylee circle and timed supercar drops. All scene entities are LOCAL.
-- Ring NPCs have no collision; dropped cars use normal local world physics.
-- Keep the stable exported name/feature ID for existing CScript UI bindings.
local BallerPlatform8 = (function()
    local M = { Version = 'kaylee-circle-cars-local-3' }
    -- One dense horizontal band, not four full-height storeys.
    -- Reuse the existing 96-actor budget; reference population is not known.
    local SLOTS, ROWS, MIN_COUNT = 1, 1, 1
    local COUNT = SLOTS * ROWS
    -- Retain these working dimensions; they are not measurements of the clip.
    local RADIUS, BOTTOM = 2.45, 3.5
    local IDLE_DICT, IDLE_CLIP = 'move_f@multiplayer', 'idle'
    -- LOOPING | NOT_INTERRUPTABLE | OVERRIDE_PHYSICS | IGNORE_GRAVITY.
    -- Applied only to this scene's verified, non-networked actors.
    local IDLE_FLAGS = 1 | 8 | 1024 | 2048
    local LOAD_TIMEOUT_MS, SPAWN_INTERVAL_MS, SPAWN_STALL_MS = 5000, 55, 8000
    local BIRTH_BATCH, DELETE_BATCH = 3, 32
    local DROP_INTERVAL_MS, CAR_LIFETIME_MS, MAX_DROPPED_CARS = 1000, 12000, 12
    local CAR_DELETE_BATCH, DROP_CENTER_OFFSET = 4, 0.75
    -- All eight are SUPER/ClassId 7 in the supplied vehicle data; validate in-game too.
    local SUPER_MODELS = { 'adder', 'zentorno', 't20', 'osiris',
        'entityxf', 'turismor', 'cheetah', 'reaper' }
    local FOLLOW_THRESHOLD_SQ = 0.12 * 0.12
    local CLEANUP_WAIT_MS, RETRY_PAUSE_MS = 4500, 2000

    local H = {
        exists = 0x7239B21A38F536BA,
        model = 0x9F47B058362C84B5,
        is_networked = 0xC7827959479DCC78,
        valid_model = 0xC0296A2EDF545E92,
        is_ped = 0x75816577FEA6DAD5,
        request_model = 0x963D27A58DF860AC,
        has_model = 0x98A4EB5D89A0C952,
        release_model = 0xE532F5D78798DAAB,
        create_ped = 0xD49F9B0955C367DE,
        create_car = 0xAF35D0D2583051B0,
        is_vehicle = 0x19AAC8F07BFEC53E,
        vehicle_class = 0xDEDF1C8BD47C2200,
        car_gravity = 0x89F149B6131E57DA,
        dynamic = 0x1718DE8E3F2823CA,
        physics = 0x710311ADF0E20730,
        velocity = 0x1C99BB7B6E96D16F,
        invincible = 0x3882114BDE571AD4,
        engine_on = 0x2497C4717C8B881E,
        set_mission = 0xAD738C3085FE7E11,
        set_collision = 0x1A9205C1B9EE827F,
        set_gravity = 0x4A4722448F18EEF5,
        set_ped_gravity = 0x9FF447B6B6AD960A,
        freeze = 0x428CA6DBD1094446,
        block_events = 0x9F8AA94D6D97DBF4,
        can_ragdoll = 0xB128377056A54E2A,
        request_anim = 0xD3BD40951412FEF6,
        has_anim = 0xD031A9162D01088C,
        release_anim = 0xF66A602F829E2A06,
        clear_tasks = 0xAAA34F8A7CB32098,
        play_anim = 0xEA47FE3719165B94,
        move = 0x239A3351AC1DA385,
        delete = 0xAE3CBE5BF394C9C9,
    }

    local function finite(v)
        return type(v) == 'number' and v == v and math.abs(v) < math.huge
    end

    local function layout(index, origin, start_heading, admitted_count)
        local slots = admitted_count or COUNT
        local slot = (index - 1) % slots
        local a = math.rad(start_heading) + slot * (2 * math.pi / slots)
        return {
            x = origin.x + RADIUS * math.cos(a),
            y = origin.y + RADIUS * math.sin(a),
            z = origin.z + BOTTOM,
            -- Parallel actors approximate the reference's uniform front/back band.
            -- This is a visual choice, not a claim about the reference's internals.
            heading = start_heading % 360.0
        }
    end

    -- All calls below are reached only from the existing native-thread tick.
    function M.NewCheraxAdapter(raw)
        local G, N, U, T, Players, Pool, Memory =
            assert(raw.GTA), assert(raw.Natives), assert(raw.Utils), assert(raw.Time),
            assert(raw.Players), assert(raw.PoolMgr), assert(raw.Memory)
        local model = U.Joaat('ig_kaylee')
        local initial_session = assert(raw.session_key and raw.session_key(), 'Session identity unavailable')
        local h = {}
        local car_models, car_requests = {}, {}

        local function same_session()
            local ok, current = pcall(raw.session_key)
            return ok and current == initial_session
        end

        local function boolean(hash, ...)
            local v = N.InvokeBool(hash, ...)
            if v == true or v == 1 then return true end
            if v == false or v == 0 then return false end
            error('Native boolean read unavailable')
        end

        local function void(hash, ...)
            assert(N.InvokeVoid(hash, ...) ~= false, 'Native rejected the operation')
        end

        function h.clock() return T.GetEpocheMs() end

        function h.log(text)
            if raw.Logger and raw.Logger.LogInfo then
                pcall(raw.Logger.LogInfo, '[Kaylee Band] ' .. tostring(text))
            end
        end

        function h.target(pid)
            if not same_session() then return nil end
            local ok, value = pcall(function()
                local p = Players.GetById(pid)
                local ped = Players.GetCPed(pid)
                if not p or not ped then return nil end
                local info = p:GetGamerInfo()
                if not info or info.RockstarId == nil or p.CxnId == nil then return nil end
                local origin = ped.Position
                if not origin or not finite(origin.x) or not finite(origin.y) or not finite(origin.z) then
                    return nil
                end
                local addr = ped:GetAddress()
                if not finite(addr) or addr <= 0 then return nil end
                return {
                    x = origin.x,
                    y = origin.y,
                    z = origin.z,
                    key = tostring(pid) .. ':' .. tostring(info.RockstarId) .. ':' ..
                        tostring(p.CxnId)
                }
            end)
            return ok and value or nil
        end

        function h.capacity()
            local ok, available = pcall(function()
                local used, maximum = Pool.GetCurrentPedCount(), Pool.GetMaxPedCount()
                if not finite(used) or not finite(maximum) then return 0 end
                return math.max(0, math.floor(maximum - used - 24))
            end)
            return ok and math.min(COUNT, available) or 0
        end

        function h.requestModel()
            assert(boolean(H.valid_model, model) and boolean(H.is_ped, model),
                'ig_kaylee model unavailable')
            void(H.request_model, model)
            void(H.request_anim, IDLE_DICT)
        end

        function h.modelReady()
            return boolean(H.has_model, model) and boolean(H.has_anim, IDLE_DICT)
        end

        function h.releaseModel()
            void(H.release_model, model)
            void(H.release_anim, IDLE_DICT)
        end

        -- A handle alone is not ownership: check model, physical address AND
        -- non-network status before moving or deleting a scene actor.
        function h.valid(r)
            if not same_session() then return false end
            local ok, outcome = pcall(function()
                if not boolean(H.exists, r.handle) then return false end
                if not r.address then return nil end
                local ent = G.HandleToPointer(r.handle)
                if not ent then return nil end
                local addr = ent:GetAddress()
                if not finite(addr) or addr ~= r.address then return false end
                local current_model = N.InvokeInt(H.model, r.handle)
                if not finite(current_model) or (current_model % 4294967296) ~= (r.model or model) % 4294967296 then
                    return false
                end
                return boolean(H.is_networked, r.handle)
            end)
            if not ok then return nil end
            return outcome -- preserve explicit false: absence is not an unknown read
        end

        function h.create(pose)
            assert(same_session(), 'Session changed during creation')
            -- Both network flags TRUE: this is deliberately a network flood.
            local handle = N.InvokeInt(H.create_ped, 5, model,
                pose.x + 0.0, pose.y + 0.0, pose.z + 0.0, pose.heading + 0.0, true, true)
            if not finite(handle) or handle <= 0 or handle % 1 ~= 0 then
                local probe_ok, can_register = pcall(N.InvokeBool, 0xBCBF4FEF9FA5D781, 1)
                return nil, 'CREATE_PED returned ' .. tostring(handle)
                    .. '; NETWORK_CAN_REGISTER_MISSION_PEDS(1)='
                    .. (probe_ok and tostring(can_register) or 'unavailable')
            end
            local r = { handle = handle, model = model, kind = 'ped' }
            local ok, address = pcall(function()
                local ent = G.HandleToPointer(handle)
                return ent and ent:GetAddress() or nil
            end)
            if ok and finite(address) and address > 0 then r.address = address end
            return r
        end

        function h.carCapacity()
            local ok, room = pcall(function()
                local used, maximum = Pool.GetCurrentVehicleCount(), Pool.GetMaxVehicleCount()
                if not finite(used) or not finite(maximum) or used < 0 or maximum < 0 then return 0 end
                return math.max(0, math.floor(maximum - used - 16))
            end)
            return ok and math.min(MAX_DROPPED_CARS, room) or 0
        end

        function h.requestCars()
            car_models = {}
            for _, name in ipairs(SUPER_MODELS) do
                local ok, hash = pcall(function()
                    local value = U.Joaat(name)
                    if not boolean(H.valid_model, value) or not boolean(H.is_vehicle, value)
                        or N.InvokeInt(H.vehicle_class, value) ~= 7 then
                        return nil
                    end
                    car_requests[value] = true -- preserve release obligation even if request fails
                    void(H.request_model, value)
                    return value
                end)
                if ok and hash then car_models[#car_models + 1] = hash end
            end
            return #car_models
        end

        function h.chooseCar(last_model)
            if not same_session() then return nil, 'Session changed' end
            local ready, previous = {}, nil
            for _, hash in ipairs(car_models) do
                local ok, loaded = pcall(boolean, H.has_model, hash)
                if ok and loaded then
                    if hash == last_model then previous = hash else ready[#ready + 1] = hash end
                else
                    pcall(void, H.request_model, hash) -- at most once per drop interval
                end
            end
            if #ready > 0 then return ready[math.random(1, #ready)] end
            if previous then return previous end -- only one usable model is loaded
            return nil, 'Supercar models are not loaded'
        end

        function h.releaseCars()
            for hash in pairs(car_requests) do
                local ok = pcall(void, H.release_model, hash)
                if ok then car_requests[hash] = nil end
            end
            car_models = {}
        end

        function h.createCar(hash, pose)
            assert(same_session(), 'Session changed during local car creation')
            assert(car_requests[hash] and boolean(H.has_model, hash), 'Supercar model is not ready')
            -- Full signature from supplied Gen9 natives.json; never network the drop.
            local handle = N.InvokeInt(H.create_car, hash, pose.x + 0.0, pose.y + 0.0,
                pose.z + 0.0, pose.heading + 0.0, true, true, pose.z < -100.0)
            if not finite(handle) or handle <= 0 or handle % 1 ~= 0 then
                return nil, 'Local supercar allocation returned no handle'
            end
            local r = { handle = handle, model = hash, kind = 'vehicle' }
            local ok, address = pcall(function()
                local ent = G.HandleToPointer(handle)
                return ent and ent:GetAddress() or nil
            end)
            if ok and finite(address) and address > 0 then r.address = address end
            return r
        end

        function h.configureCar(r)
            assert(h.valid(r) == true and r.kind == 'vehicle', 'Local supercar identity could not be verified')
            void(H.set_mission, r.handle, true, true)
            void(H.set_collision, r.handle, true, true)
            void(H.freeze, r.handle, false)
            void(H.dynamic, r.handle, true)
            void(H.set_gravity, r.handle, true)
            void(H.car_gravity, r.handle, true)
            void(H.invincible, r.handle, true) -- visual drops do not need exploding wrecks
            void(H.engine_on, r.handle, false, true, true)
            void(H.physics, r.handle)
            void(H.velocity, r.handle, 0.0, 0.0, -1.0)
        end

        function h.configure(r)
            h.log("CONFIGURE handle=" .. tostring(r.handle)
                .. " address=" .. tostring(r.address)
                .. " valid=" .. tostring(h.valid(r)))
            assert(h.valid(r) == true, 'Created Kaylee identity could not be verified')
            void(H.set_mission, r.handle, true, true)
            void(H.set_collision, r.handle, false, true)
            void(H.set_gravity, r.handle, false)
            void(H.set_ped_gravity, r.handle, false)
            void(H.block_events, r.handle, true)
            void(H.can_ragdoll, r.handle, false)
            void(H.freeze, r.handle, true)
            void(H.clear_tasks, r.handle)
            -- Freezing coordinates alone does not select an upright skeletal pose.
            void(H.play_anim, r.handle, IDLE_DICT, IDLE_CLIP,
                8.0, -8.0, -1, IDLE_FLAGS, 1.0, true, true, true)
        end

        function h.move(r, pose)
            if h.valid(r) ~= true then return false end
            void(H.move, r.handle, pose.x + 0.0, pose.y + 0.0, pose.z + 0.0, true, true, true)
            return true
        end

        function h.delete(r)
            local valid = h.valid(r)
            if valid == false then return true end
            if valid ~= true then return false end
            local ptr = Memory.AllocInt()
            if not finite(ptr) or ptr <= 0 then return false end
            local ok = pcall(function()
                assert(h.valid(r) == true, 'Local scene ownership changed')
                void(H.set_mission, r.handle, true, true)
                Memory.WriteInt(ptr, r.handle)
                void(H.delete, ptr)
            end)
            pcall(Memory.Free, ptr)
            return ok and h.valid(r) == false
        end

        return h
    end

    function M.New(h)
        local s = {
            phase = 'idle',
            reason = 'Off',
            peds = {},
            cars = {},
            created = 0,
            configured = 0,
            dropped = 0,
            count = COUNT,
            follow = true,
            paused = false,
            revision = 0
        }
        local api, ticking = {}, false

        local function cleanup(reason)
            if s.phase == 'idle' or s.phase == 'cleaning' or s.phase == 'cleanup_pending' then return end
            s.revision = s.revision + 1
            s.phase, s.reason = 'cleaning', reason or 'Stopped'
            s.next_drop = nil -- stop the producer before touching its records
            s.cleanup_index, s.car_cleanup_index = #s.peds, #s.cars
            s.cleanup_deadline = h.clock() + CLEANUP_WAIT_MS
        end

        local function anchor()
            local a = h.target(s.pid)
            if not a then return nil end -- temporary streaming absence: hold, do not dismantle
            assert(a.key == s.key, 'Selected player disconnected or changed identity')
            assert(finite(a.x) and finite(a.y) and finite(a.z), 'Invalid selected-player position')
            return a
        end

        function api.Start(pid)
            if s.phase ~= 'idle' then return false, 'Previous Kaylee scene is still cleaning up' end
            if type(pid) ~= 'number' or pid % 1 ~= 0 or pid < 0 or pid > 31 then
                return false, 'Invalid selected player'
            end
            local ok, why = pcall(function()
                local a = assert(h.target(pid), 'Selected player is not streamed')
                local room = h.capacity()
                assert(finite(room) and room >= MIN_COUNT, 'Insufficient local ped pool headroom')
                s.revision = s.revision + 1
                local revision = s.revision
                s.pid, s.key, s.center, s.heading = pid, a.key, a, 0
                s.count = math.min(COUNT, math.floor(room))
                s.peds, s.cars, s.created, s.configured = {}, {}, 0, 0
                s.dropped, s.last_car_model, s.spawn_failures = 0, nil, 0
                s.paused, s.car_cursor, s.car_reap_due = false, 0, 0
                s.phase, s.reason = 'loading', 'Loading local Kaylee model and standing pose'
                s.started, s.next_spawn = h.clock(), 0
                s.last_progress, s.drop_status = s.started, 'Waiting for the complete circle'
                s.model_requested = true
                h.requestModel()
                if s.revision ~= revision then return end
                s.cars_requested = true
                local loaded, problem = pcall(h.requestCars)
                if not loaded then s.drop_status = 'Car model request: ' .. tostring(problem) end
            end)
            if not ok then
                s.reason = tostring(why)
                if s.model_requested then cleanup(s.reason) end
                return false, s.reason
            end
            return true
        end

        function api.Stop(reason) cleanup(reason or 'Disabled') end

        function api.SetPaused(enabled)
            s.paused = enabled == true
            if s.paused and s.phase == 'active' then s.next_drop = h.clock() + DROP_INTERVAL_MS end
        end

        function api.RetryCleanup()
            if s.phase == 'cleanup_pending' then
                s.phase, s.cleanup_index, s.car_cleanup_index = 'cleaning', #s.peds, #s.cars
                s.cleanup_deadline = h.clock() + CLEANUP_WAIT_MS
            end
        end

        function api.Status()
            return {
                phase = s.phase,
                reason = s.reason,
                peds = #s.peds,
                cars = #s.cars,
                maximum = COUNT,
                target = s.count,
                created = s.created,
                configured = s.configured,
                anchor = s.pid,
                layers = ROWS,
                slots = s.count,
                follow = s.follow,
                platform = 0,
                local_only = true,
                paused = s.paused,
                dropped_total = s.dropped,
                car_limit = MAX_DROPPED_CARS,
                drop_interval_ms = DROP_INTERVAL_MS,
                drop_status = s.drop_status,
                next_drop = s.next_drop,
                complete = s.phase == 'active'
            }
        end

        -- Reverse, round-robin deletion. Unknown/failed deletions remain tracked
        -- and keep their allocation slots. Never scan or delete unrelated entities.
        local function retire(records, cursor, budget, expired_only, now)
            local total, scanned, attempted = #records, 0, 0
            local i = math.min(cursor and cursor > 0 and cursor or total, total)
            while scanned < total and #records > 0 and attempted < budget do
                if i < 1 or i > #records then i = #records end
                local r = records[i]
                scanned = scanned + 1
                if not expired_only or now >= (r.expires or 0) then
                    attempted = attempted + 1
                    local ok, deleted = pcall(h.delete, r)
                    if ok and deleted == true then table.remove(records, i) end
                end
                i = i - 1
            end
            return i
        end

        local function perform_cleanup(now)
            local before = #s.peds + #s.cars
            s.cleanup_index = retire(s.peds, s.cleanup_index, DELETE_BATCH, false, now)
            s.car_cleanup_index = retire(s.cars, s.car_cleanup_index, CAR_DELETE_BATCH, false, now)
            if #s.peds + #s.cars < before then
                s.cleanup_deadline = now + CLEANUP_WAIT_MS -- slow, productive cleanup is not a stall
            end
            if #s.peds == 0 and #s.cars == 0 then
                if s.model_requested then
                    pcall(h.releaseModel); s.model_requested = false
                end
                if s.cars_requested then
                    pcall(h.releaseCars); s.cars_requested = false
                end
                s.phase = 'idle'
                s.pid, s.key = nil, nil
                h.log(s.reason .. '; local circle and car cleanup complete')
            elseif now >= s.cleanup_deadline then
                s.phase = 'cleanup_pending'
                s.reason = ('Local cleanup incomplete (%d peds, %d cars); retrying safely')
                    :format(#s.peds, #s.cars)
                h.log(s.reason)
            end
        end

        -- Only the NPCs belong to the held/following ring. Cars are independent
        -- physical drops and MUST NOT be translated after their initial creation.
        local function follow(a, force)
            local dx, dy, dz = a.x - s.center.x, a.y - s.center.y, a.z - s.center.z
            if not force and dx * dx + dy * dy + dz * dz < FOLLOW_THRESHOLD_SQ then return true end
            local revision = s.revision
            for i, r in ipairs(s.peds) do
                if s.revision ~= revision then return false end
                if not h.move(r, layout(i, a, s.heading, s.count)) then
                    error('One local Kaylee disappeared; cleaning scene')
                end
            end
            if s.revision ~= revision then return false end
            s.center = { x = a.x, y = a.y, z = a.z }
            return true
        end

        local function finish_ring(a, now)
            if not follow(a, true) then return end
            s.phase, s.reason = 'active', 'Complete local Kaylee circle held until disabled'
            s.next_drop, s.drop_status = now + DROP_INTERVAL_MS, 'One supercar per second'
            h.log(s.reason .. ' (' .. s.created .. ' actors)')
        end

        local function drop_car(a, now)
            if now < (s.next_drop or now + DROP_INTERVAL_MS) then return end
            -- No catch-up loop: a long frame may delay a drop, never multiply it.
            s.next_drop = now + DROP_INTERVAL_MS
            local revision = s.revision
            -- Reap at the drop boundary too: the 200ms maintenance cadence may
            -- otherwise miss an expiry and unnecessarily skip this second's drop.
            s.car_cursor = retire(s.cars, s.car_cursor, CAR_DELETE_BATCH, true, now)
            if s.revision ~= revision then return end
            if #s.cars >= MAX_DROPPED_CARS then
                s.drop_status = 'Waiting for old local car cleanup'; return
            end
            local room_ok, room = pcall(h.carCapacity)
            if s.revision ~= revision then return end
            if not room_ok or not finite(room) or room < 1 then
                s.drop_status = 'Waiting for local vehicle pool headroom'; return
            end
            local chosen, model, why = pcall(h.chooseCar, s.last_car_model)
            if s.revision ~= revision then return end
            if not chosen or not model then
                s.drop_status = 'Waiting for a supercar model: ' .. tostring(why or model or 'streaming'); return
            end
            local pose = {
                x = a.x,
                y = a.y,
                z = a.z + BOTTOM + DROP_CENTER_OFFSET,
                heading = math.random(0, 359) + 0.0
            }
            local allocated, rec, failure = pcall(h.createCar, model, pose)
            if allocated and rec then
                rec.expires = now + CAR_LIFETIME_MS
                s.cars[#s.cars + 1] = rec -- retain even a late allocation after cancellation
            end
            if s.revision ~= revision then return end
            if not allocated or not rec then
                s.drop_status = 'Local car allocation deferred: ' .. tostring(failure or rec); return
            end
            local configured, problem = pcall(h.configureCar, rec)
            if s.revision ~= revision then return end
            if not configured then
                rec.expires = now -- keep the handle and clean this failed drop, not the ring
                s.car_reap_due = 0
                s.drop_status = 'Removing incomplete car: ' .. tostring(problem); return
            end
            s.last_car_model, s.dropped = model, s.dropped + 1
            s.drop_status = 'One supercar per second'
        end

        local function tick()
            local now = h.clock()
            if s.phase == 'idle' or s.phase == 'cleanup_pending' then return end
            if s.phase == 'cleaning' then
                perform_cleanup(now); return
            end
            if s.last_clock and now < s.last_clock then
                s.next_spawn, s.last_progress, s.started = now, now, now
                if s.phase == 'active' then s.next_drop = now + DROP_INTERVAL_MS end
                for _, r in ipairs(s.cars) do r.expires = now + CAR_LIFETIME_MS end
                s.car_reap_due = 0
            end
            s.last_clock = now
            if now >= s.car_reap_due then
                s.car_cursor = retire(s.cars, s.car_cursor, CAR_DELETE_BATCH, true, now)
                s.car_reap_due = now + 200
            end
            local a = anchor()
            if not a or s.paused then
                -- Keep the finished/partially built ring where it is. The binding
                -- still cancels on an actual connection/session change or unload.
                s.next_drop = now + DROP_INTERVAL_MS
                s.started, s.last_progress = now, now
                s.drop_status = s.paused and 'Paused; circle retained' or 'Anchor not streamed; circle retained'
                return
            end
            if s.phase == 'loading' then
                assert(now - s.started <= LOAD_TIMEOUT_MS, 'Kaylee model or standing pose load timed out')
                if h.modelReady() then
                    s.phase, s.reason = 'spawning', 'Building the full local Kaylee circle'
                    s.last_progress = now
                end
            elseif s.phase == 'spawning' then
                -- No total build deadline. Low FPS must not erase a progressing arc.
                if not follow(a) or now < s.next_spawn then return end
                local revision = s.revision
                for _ = 1, BIRTH_BATCH do
                    if s.revision ~= revision then return end
                    if s.created >= s.count then break end
                    if h.capacity() <= 0 then
                        assert(s.created >= MIN_COUNT, 'Local ped pool filled before minimum circle completed')
                        s.count = s.created; break
                    end
                    if s.revision ~= revision then return end
                    local i = s.created + 1
                    local allocated, rec, problem = pcall(h.create, layout(i, s.center, s.heading, s.count))
                    if allocated and rec then
                        s.peds[#s.peds + 1] = rec -- track before configuration or a cancel boundary
                        s.created = i
                    end
                    if s.revision ~= revision then return end
                    if not allocated or not rec then
                        s.spawn_failures = s.spawn_failures + 1
                        s.reason = 'Retrying local ped allocation: ' .. tostring(problem or rec)
                        if s.spawn_failures >= 4 and now - s.last_progress >= SPAWN_STALL_MS then
                            assert(s.created >= MIN_COUNT,
                                'Networked ped allocation stalled before minimum circle completed; last error: ' ..
                                tostring(problem or rec))
                            s.count = s.created -- close the ring with the successfully admitted actors
                        end
                        break
                    end
                    h.configure(rec)
                    if s.revision ~= revision then return end
                    s.configured = s.configured + 1
                    s.last_progress, s.spawn_failures = h.clock(), 0
                end
                s.next_spawn = h.clock() + SPAWN_INTERVAL_MS
                if s.created >= s.count then finish_ring(a, h.clock()) end
            elseif s.phase == 'active' then
                if follow(a) then drop_car(a, now) end
            end
        end

        function api.Tick()
            if ticking then return false end
            ticking = true
            local ok, err = pcall(tick)
            ticking = false
            if not ok then
                cleanup(tostring(err)); h.log('Stopped local circle: ' .. tostring(err))
            end
            return ok
        end

        return api
    end

    function M.Bind(api, raw, __public_instance)
        __public_instance = __public_instance or __public_binding
        assert(__public_live(__public_instance), "Public API context is not active")
        local function public_vehicle_action_allowed(effect_key)
            return __public_vehicle_allowed(__public_instance, effect_key)
        end
        local base = {}; for k, v in pairs(api) do base[k] = v end
        local owner = {}
        local scene, intent, last = nil, nil, { phase = 'idle', reason = 'Off', peds = 0 }
        local closed, due, retry_due, busy_tick = false, 0, 0, false
        local processing_paused = false

        local function get_status() return scene and scene.Status() or last end
        local function occupied() return intent ~= nil or get_status().phase ~= 'idle' end
        local function session()
            local ok, key = pcall(raw.session_key or function() end)
            return ok and key or nil
        end
        local function connection(pid)
            local ok, key = pcall(function()
                local p = raw.Players.GetById(pid)
                if not p or p:IsLocalPlayer() then return nil end
                local info = p:GetGamerInfo()
                if not info or not info.RockstarId or p.CxnId == nil then return nil end
                return tostring(info.RockstarId) .. ':' .. tostring(p.CxnId)
            end)
            return ok and key or nil
        end
        local function notify(reason)
            local old = intent; intent = nil
            if old and type(raw.OnBallerDisabled) == 'function' then
                pcall(raw.OnBallerDisabled, old.pid, reason)
            end
        end
        local function stop(reason)
            if scene then scene.Stop(reason) end
            notify(reason or 'Disabled')
            if not occupied() and M.lease == owner then M.lease = nil end
        end

        function api.SetBallerEnabled(pid, enabled)
            if enabled == true and not public_vehicle_action_allowed("character_baller") then
                return false, "Supporter-only vehicle action."
            end
            pid = tonumber(pid)
            if enabled ~= true then
                if (intent and intent.pid == pid) or (scene and get_status().anchor == pid) then
                    stop('Disabled by user')
                    if scene then scene.RetryCleanup() end
                end
                return true
            end
            if closed then return false, 'Vehicle effects are stopped' end
            if not pid or pid % 1 ~= 0 or pid < 0 or pid > 31 then
                return false, 'Select a valid player'
            end
            if intent then
                if intent.pid == pid then return true end
                return false, 'Turn off the current Kaylee scene first'
            end
            if occupied() or (M.lease and M.lease ~= owner) then
                return false, 'Previous Kaylee scene is still cleaning up'
            end
            local base_status = base.Status('character_baller')
            if base_status.blocked or (base_status.pending or 0) > 0 then
                return false, 'Finish another vehicle effect or its cleanup first'
            end
            local key, scope = connection(pid), session()
            if not key or scope == nil then return false, 'Selected player/session identity unavailable' end
            M.lease = owner
            intent = { pid = pid, key = key, session = scope }
            scene, due = nil, 0
            last = { phase = 'queued', reason = 'Preparing one dense local Kaylee band', anchor = pid, peds = 0 }
            return true
        end

        function api.BallerEnabled(pid)
            return intent ~= nil and intent.pid == tonumber(pid)
        end

        function api.PruneBaller()
            if intent and (session() ~= intent.session or connection(intent.pid) ~= intent.key) then
                stop('Player/session changed')
            end
            return intent ~= nil
        end

        function api.Start(pid, key)
            if key == 'character_baller' then return api.SetBallerEnabled(pid, true) end
            return base.Start(pid, key)
        end

        function api.Status(key)
            local result = base.Status(key)
            local s = get_status()
            local pending = (s.phase == 'cleaning' or s.phase == 'cleanup_pending')
                and ((s.peds or 0) + (s.cars or 0)) or 0
            result.blocked = result.blocked or occupied() or (M.lease and M.lease ~= owner) or false
            result.baller_enabled = intent ~= nil
            result.baller_waiting = intent ~= nil and s.phase ~= 'active'
            result.baller_phase = intent and s.phase or 'off'
            result.baller_player_id = intent and intent.pid or nil
            result.pending = (result.pending or 0) + pending
            if occupied() then
                result.name = 'Kaylee Circle + Supercars (local visual)'
                result.phase = pending > 0 and 'cleanup' or 'executing'
                result.background_cleanup = intent == nil and pending > 0
            end
            return result
        end

        function api.BallerDiagnostics()
            local s = get_status()
            local pending = (s.phase == 'cleaning' or s.phase == 'cleanup_pending')
                and ((s.peds or 0) + (s.cars or 0)) or 0
            return {
                active = intent ~= nil,
                player_id = intent and intent.pid or s.anchor,
                phase = s.phase,
                maximum = COUNT,
                overall_limit = COUNT,
                target = s.target or COUNT,
                waves = ROWS,
                held = s.peds or 0,
                present = s.peds or 0,
                positioned = s.configured or 0,
                missing = math.max(0, (s.peds or 0) - (s.configured or 0)),
                waiting = pending,
                pending = pending,
                pending_cleanup = pending,
                created = s.created or 0,
                configured = s.configured or 0,
                platform_count = 0,
                local_only = true,
                cars = s.cars or 0,
                dropped_total = s.dropped_total or 0,
                car_limit = MAX_DROPPED_CARS,
                drop_interval_ms = DROP_INTERVAL_MS,
                drop_status = s.drop_status,
                complete = s.complete == true,
                reason = s.reason,
                flicker_moves = 0,
                swaps = 0
            }
        end

        function api.Cancel(reason)
            stop(reason or 'Cancelled')
            return base.Cancel(reason)
        end

        function api.IsActive() return occupied() or base.IsActive() end

        function api.TickHeadFollow(now, allow_scene)
            processing_paused = allow_scene == false
            if scene then scene.SetPaused(processing_paused) end
            return base.TickHeadFollow(now, allow_scene)
        end

        function api.TickCleanup(now)
            if busy_tick then return end
            busy_tick = true
            local ok, err = pcall(function()
                if not public_vehicle_action_allowed("character_baller") then
                    local phase=scene and scene.Status().phase or "idle"
                    if intent or (scene and phase~="idle" and phase~="cleaning" and phase~="cleanup_pending") then
                        stop("Supporter authorization ended")
                    end
                end
                base.TickCleanup(now)
                api.PruneBaller()
                local clock = tonumber(now) or raw.Time.GetEpocheMs()
                if clock < due and due - clock <= 40 then return end
                due = clock + 40
                if intent and not scene then
                    local adapter = M.NewCheraxAdapter(raw)
                    scene = M.New(adapter)
                    local accepted, why = scene.Start(intent.pid)
                    if not accepted then stop(why) else scene.SetPaused(processing_paused) end
                end
                if scene then
                    if scene.Status().phase == 'cleanup_pending' and clock >= retry_due then
                        scene.RetryCleanup(); retry_due = clock + RETRY_PAUSE_MS
                    end
                    scene.Tick()
                    last = scene.Status()
                    if last.phase == 'cleaning' or last.phase == 'cleanup_pending' then
                        notify(last.reason)
                    end
                    if last.phase == 'idle' then
                        notify(last.reason)
                        scene = nil
                        if M.lease == owner then M.lease = nil end
                    end
                elseif not intent then
                    last.phase = 'idle'
                    if M.lease == owner then M.lease = nil end
                end
            end)
            busy_tick = false
            if not ok then
                stop('Local Kaylee scene error: ' .. tostring(err))
                if raw.Logger and raw.Logger.LogError then
                    pcall(raw.Logger.LogError, '[Kaylee Band] ' .. tostring(err))
                end
            end
        end

        function api.DrainUnload()
            stop('Script unloading')
            local ready, why = base.DrainUnload()
            api.TickCleanup(raw.Time.GetEpocheMs())
            return ready and not occupied(),
                occupied() and 'Kaylee circle/cars await local cleanup' or why
        end

        function api.CanHandoff() return not occupied() and base.CanHandoff() end

        function api.RestorePersistentState()
            stop('Restoring state')
            return base.RestorePersistentState()
        end

        function api.Stop()
            closed = true
            stop('Module unloaded')
            if occupied() and raw.Logger and raw.Logger.LogError then
                pcall(raw.Logger.LogError,
                    '[Kaylee Band] Unload before cleanup confirmation; records still pending')
            end
            return base.Stop()
        end

        return api
    end

    return M
end)()
Module.PlatformBaller8 = BallerPlatform8
-- END BALLER_PLATFORM_8

function Module.New(host)
    local __public_instance = __public_binding
    assert(__public_live(__public_instance), "Public API context is not active")
    local function public_vehicle_action_allowed(effect_key)
        return __public_vehicle_allowed(__public_instance, effect_key)
    end
    host = host or (module_context and module_context.Raw) or {}
    local GTA, Natives, Utils = host.GTA, host.Natives, host.Utils
    local Time, Players, Memory = host.Time, host.Players, host.Memory
    local FileMgr, Logger = host.FileMgr, host.Logger
    local raw_script = host.Script
    local Script = { QueueJob = raw_script.QueueJob, Yield = raw_script.Yield }
    local generation, job_running, disposed = 0, false, false
    local owner_token, job_progress = nil, nil
    local orphan_model_leases = {}
    local function session_key()
        if type(host.session_key) ~= "function" then return nil end
        local ok, key = pcall(host.session_key)
        if ok and (type(key) == "string" or (type(key) == "number" and key == key)) then return key end
    end
    local active_vehicle_backend, last_spawn_timing = nil, {}
    local lobby_backend = host.lobby_spawn_backend or "helper"
    local active_session_key
    local function session_state(expected)
        if expected == nil then return "same" end
        local current = session_key()
        if current == nil then return "unavailable" end
        return current == expected and "same" or "changed"
    end
    local cancel_signal = {}
    local function touch_job(token, phase)
        if owner_token == token and job_progress and job_progress.token == token then
            job_progress.time = Time.GetEpocheMs()
            job_progress.phase = phase
        end
    end

    local TAG = "CScript.Penis"
    local DURATION_MS = 15000
    local LOBBY_BURST_LIMIT, LOBBY_BURST_MS = 20, 5000
    local LOBBY_POOL_HEADROOM, LOBBY_MAX_WORK, LOBBY_WORK_MS = 32, 4, 4
    local LOBBY_MIN_Z, LOBBY_MAX_Z = 1000.0, 4500.0
    local LOBBY_MAX_INFLIGHT, LOBBY_ALLOCATION_TIMEOUT_MS = 4, 5000
    -- Probe at most four owned entities per 40-ms pass, and never the complete
    -- network pool. The runtime's tick does not do these reads.
    local LOBBY_RETENTION_MS = 40
    local LOBBY_PLAYER_FAILURE_LIMIT, LOBBY_EMPTY_FAILURE_LIMIT = 3, 8
    local FOREGROUND_CLEANUP_MS = 4000
    local LOCAL_RETURN_WAIT_MS = 5000 -- Report a stalled return; retain the restoration obligation.
    local BACKGROUND_CLEANUP_BATCH, BACKGROUND_CLEANUP_MS = 32, 500
    local HOVER_HEIGHT = 160.0
    local FOLLOW_EVERY_MS = 40
    local SPAWN_EVERY_MS = 40 -- 1 ms floods the network; actual 40-ms scheduler remains bounded.
    local MAX_VEHICLES = 640  -- global script ceiling; actual network/pool budget can be lower.
    -- Only ordinary vehicle spawners opt in to the higher cap / tighter cadence.
    -- Do not tune Baller, Tug, Cargo, or crash-oriented target-stack presets.
    local REGULAR_VEHICLE_TUNING = {
        limit = 640,
        legacy_tracked_limit = 512,
        reference_ms = 40,
        variant_ms = 20,
        circle_ms = 18,
        is_regular = function(effect_key)
            return effect_key == "vehicle_circle" or effect_key == "ruiner_pimp"
                or effect_key == "trevor_michael" or effect_key == "pistol_circle"
                or (type(effect_key) == "string" and effect_key:match("^vehicle_variant_[1-4]$") ~= nil)
        end
    }
    local REFERENCE_PRESET = "evilage" -- original button's default; each run captures its own preset
    -- One new car every scheduler tick throughout the active period. Recycle the
    -- oldest confirmed-owned car when full; never exceed the live-entity budget.
    -- Native/model loading costs can reduce the actual in-game rate.
    local REFERENCE_ACTIVE_LIMIT = 512
    local PED_ACTIVE_LIMIT = 512 -- ordinary ped effects; retained cleanup records still count.
    -- p_franklin_02 is the Agency/Contract Franklin already present in the old set.
    local PED_POOL_HEADROOM = 16
    local active_ped_models = nil
    local REFERENCE_BATCH_SIZE = 1 -- SPAWN_EVERY_MS above is Deluxo only
    local REFERENCE_SPAWN_EVERY_MS = 40
    -- Small bounded batches: preserve serial birth/ownership checks, avoid
    -- a burst of unverified network entities or an unbounded single frame.
    local CIRCLE_BATCH_SIZE = 3
    local CIRCLE_SPAWN_EVERY_MS = 18
    local CIRCLE_BATCH_BUDGET_MS = 90
    local PED_SPAWN_EVERY_MS = 20
    local PED_MODELS = {
        -- Chimp is classified as civmale in the supplied game data, not Animal.
        { name = "a_c_chimp", kind = 4 }, { name = "a_c_rottweiler", kind = 28 },
        { name = "a_c_boar",  kind = 28 }, { name = "a_c_coyote", kind = 28 },
        { name = "player_one", kind = 4 }, { name = "ig_lamardavis", kind = 4 },
    }
    local VARIANT_SPAWN_EVERY_MS = 20 -- denser new variants; the same live entity budget
    local REFERENCE_SPACE_RETRY_MS = 200
    local REFERENCE_OPENING_LOOSE = 2
    local REFERENCE_LOOSE_EVERY = 40
    local REFERENCE_COLUMN_LEVELS = 12
    local REFERENCE_LAYER_STEP = 0.04        -- only 0.44 m across a full stack
    local REFERENCE_REANCHOR_DISTANCE = 0.18 -- follow small steps without chasing tiny position jitter
    local REFERENCE_REANCHOR_TURN = 8.0
    local REFERENCE_SETUP_ATTEMPTS = 4
    local REFERENCE_FAILED_CAR_LIMIT = 3
    -- Native networked xenons support 13 coloured indices, not arbitrary RGB.
    local REFERENCE_XENON_PALETTE = { 0, 11, 3, 10, 4, 2, 5, 12, 1, 9, 7, 8, 6 }
    -- Walk the whole saturated RGB hue wheel at full intensity, plus white.
    -- 37 is coprime to 1530, so all 1530 bright hue steps are reachable.
    -- Assign once per car; do not generate per-frame colour/network updates.
    local function reference_neon_colour(sequence)
        local n = sequence - 1
        if n % 14 == 13 then return 255, 255, 255 end
        local hue = ((n - math.floor(n / 14)) * 37) % 1530
        local sector, offset = math.floor(hue / 255), hue % 255
        if sector == 0 then return 255, offset, 0 end
        if sector == 1 then return 255 - offset, 255, 0 end
        if sector == 2 then return 0, 255, offset end
        if sector == 3 then return 0, 255 - offset, 255 end
        if sector == 4 then return offset, 0, 255 end
        return 255, 0, 255 - offset
    end
    local CLEANUP_PASSES = 3
    local CLEANUP_RETRY_MS = 400
    -- 640 ordinary vehicles + 64 tracker slots for unresolved cleanup records.
