        local q,why=physical(p.handle)
        if not q and why=="gone" and p.owned and p.native_network_id and same_player(p.local_identity)then
            local key=type(deps.session_key)=="function" and deps.session_key()or nil
            if p.session_key==nil or key==p.session_key then
                local h=int(H.NET_ENTITY,p.native_network_id);local fresh=h and physical(h)
                if fresh and fresh.address==p.address and fresh.model==p.model and fresh.network_id==p.network_id then
                    p.handle=h;q=fresh
                end
            end
        end
        if not q then return nil,why end
        if p.network_pending and q.network_id~=nil then p.network_id=q.network_id;p.network_pending=nil end
        if q.address~=p.address or q.model~=p.model or q.network_id~=p.network_id then return nil,"replaced" end
        return q
    end
    local function ped(pid)
        local ok,h=pcall(deps.player_ped,pid);return ok and physical(h) or nil
    end
    local function session_key()
        if type(deps.session_key)~="function" then return nil end
        local ok,key=pcall(deps.session_key)
        if ok and (finite(key) or type(key)=="string") then return key end
    end
    local function epoch_changed(r)
        local key=session_key()
        return r.session_key~=nil and key~=nil and key~=r.session_key
    end
    local function in_scope(r)
        return (r.session_key==nil or session_key()==r.session_key)
            and bool(H.SESSION)==true and same_player(r.local_identity)
    end
    local function active(r)
        return not stopped and not r.cancelled and runs[r.kind]==r
    end
    local function apply(r,h,...)
        return active(r) and write(h,...) and active(r)
    end
    local function inform(r,reason)
        if r.informed then return end
        r.informed=true
        if type(deps.on_effect_stopped)=="function" then pcall(deps.on_effect_stopped,r.kind,r.pid,reason) end
    end
    local function cancel(r,reason)
        if not r or r.cancelled then return end
        r.cancelled=true;r.reason=reason or "disabled";r.phase="cleanup"
        inform(r,r.reason)
    end
    local function control(p,t,validity)
        local function allowed()return validity==nil or validity()==true end
        if not allowed() or not matches(p) then return false end
        if bool(H.CONTROL,p.handle)==true then p.control_since=nil;return allowed() end
        p.control_since=p.control_since or t
        if t>=(p.next_control or 0) then
            p.next_control=t+100
            if not allowed()then return false end
            if type(deps.request_entity_control)=="function"then
                pcall(deps.request_entity_control,deps.local_player_id(),p.handle,validity)
            elseif allowed()then bool(H.REQUEST_CONTROL,p.handle)end
        end
        return matches(p)~=nil and bool(H.CONTROL,p.handle)==true and allowed()
    end
    local function finish(r)
        last[r.kind]={pid=r.pid,phase="idle",reason=r.reason,active=false,cleanup_pending=false,
            detached=r.detached or 0,wheels_damaged=r.wheels_damaged or 0,
            rotors_damaged=r.rotors_damaged or 0,wings_damaged=r.wings_damaged or 0,
            wheel_detach_supported=false,unresolved_spawn=r.unresolved_spawn}
        if runs[r.kind]==r then runs[r.kind]=nil end
        inform(r,r.reason)
    end
    local function release_model(r)
        if stopped and not draining then return end
        if r.model_requested and write(H.RELEASE_MODEL,r.model) then r.model_requested=false end
    end
    local function ensure_hostility(r,target)
        if not r.hostile_group then
            local t=now()
            if t<(r.next_group_attempt or 0) then return false end
            r.next_group_attempt=t+1000
            local m=deps.Memory
            if not m or type(m.AllocInt)~="function" or type(m.ReadInt)~="function"
                or type(m.WriteInt)~="function" or type(m.Free)~="function" then return false end
            local ok,ptr=pcall(m.AllocInt)
            if not ok or not integer(ptr) or ptr==0 then return false end
            local success,group=pcall(function()
                m.WriteInt(ptr,0)
                group_serial=group_serial+1
                if not apply(r,H.GROUP_ADD,"CSFX_"..tostring(r.started).."_"..group_serial,ptr) then return nil end
                return m.ReadInt(ptr)
            end)
            pcall(m.Free,ptr)
            if not success or not integer(group) or group==0 then return false end
            r.hostile_group=group%0x100000000;r.hostile_targets={}
        end
        local target_group=int(H.GROUP_GET,target.handle)
        if not target_group then return false end
        target_group=target_group%0x100000000
        -- Network players commonly share a relationship group. Hate toward
        -- that group also authorizes attacks on the local player. Selected
        -- attacks use the explicit combat task and CanAttackFriendly instead.
        local relation=r.kind=="aggressive_world" and 5 or 3
        if not r.hostile_targets[target_group]
            or int(H.REL_GET,r.hostile_group,target_group)~=relation then
            -- Only pairs involving our private group are changed. Never turn
            -- an existing ambient/player relationship pair hostile globally.
            if not apply(r,H.REL_SET,relation,r.hostile_group,target_group)
                or not apply(r,H.REL_SET,relation,target_group,r.hostile_group) then return false end
            if int(H.REL_GET,r.hostile_group,target_group)~=relation then return false end
            r.hostile_targets[target_group]=true
        end
        return true
    end
    local function release_hostility(r)
        if not r.hostile_group then return true end
        if write(H.GROUP_REMOVE,r.hostile_group) then r.hostile_group=nil;r.hostile_targets=nil;return true end
        return false
    end
    -- These config bits have getters and are restored exactly for borrowed NPCs:
    -- block ambient events, permit friendly attacks, remove police wanted gates,
    -- and suppress shocking-event panic. The actor's original group is retained.
    local combat_config={{17,true},{140,true},{182,false},{249,true},{294,true}}
    local function snapshot_combat(a)
        if a.original_group then return true end
        local group=int(H.GROUP_GET,a.handle);if group==nil then return false end
        local flags={}
        for _,entry in ipairs(combat_config) do
            local v=bool(H.CONFIG_GET,a.handle,entry[1],true)
            if v==nil then return false end
            flags[entry[1]]=v
        end
        a.original_group=group%0x100000000;a.original_config=flags
        return true
    end
    local function configure_combat(r,a)
        a.forced_combat=true
        if not apply(r,H.GROUP_SET,a.handle,r.hostile_group) then return false end
        local group=int(H.GROUP_GET,a.handle)
        if not group or group%0x100000000~=r.hostile_group then return false end
        for _,entry in ipairs(combat_config) do
            if not apply(r,H.CONFIG_SET,a.handle,entry[1],entry[2])
                or bool(H.CONFIG_GET,a.handle,entry[1],true)~=entry[2] then return false end
        end
        -- AlwaysFight does not clear contradictory civilian AlwaysFlee or
        -- FleesFromInvincibleOpponents flags. Disable those explicitly.
        for _,entry in ipairs({{5,true},{17,false},{46,true},{58,true},{63,false}}) do
            if not apply(r,H.COMBAT_ATTR,a.handle,entry[1],entry[2]) then return false end
        end
        return true
    end
    local function cleanup(r,t)
        if stopped and not draining then return end
        if r.kind=="break_vehicle" and r.grip_vehicle then
            local v=r.grip_vehicle
            local found,why=matches(v)
            if epoch_changed(r) or not found and (why=="gone" or why=="replaced") then r.grip_vehicle=nil
            elseif in_scope(r) and found and control(v,t) then
                if write(H.GRIP,v.handle,false) and write(H.GRIP_LEVEL,v.handle,0) then r.grip_vehicle=nil end
            end
            if r.grip_vehicle then return end
        end
        if r.kind=="aggressive_npcs" or r.kind=="aggressive_world" then
            if t<(r.next_cleanup or 0) then return end
            r.next_cleanup=t+100
            local keys={};for h in pairs(r.actors or {}) do keys[#keys+1]=h end;table.sort(keys)
            local start=r.cleanup_cursor or 1
            for i=0,math.min(8,#keys)-1 do
                local index=(start+i-1)%#keys+1
                local h=keys[index];local a=r.actors[h]
                local found,why=matches(a)
                local done=epoch_changed(r) or not found and (why=="gone" or why=="replaced")
                if not done and in_scope(r) and found and control(a,t) then
                    done=true
                    if matches(a.target) and bool(H.COMBAT_ACTIVE,h,a.target.handle)==true then
                        done=write(H.CLEAR_TASK,h) and done
                    end
                    if a.forced_combat then
                        -- No combat-attribute getter exists: release the force
                        -- flags to off, rather than claim an exact snapshot.
                        for _,flag in ipairs({5,46,58}) do done=write(H.COMBAT_ATTR,h,flag,false) and done end
                    end
                    if a.original_config then
                        for _,entry in ipairs(combat_config) do
                            local current=bool(H.CONFIG_GET,h,entry[1],true)
                            if current==nil then done=false
                            elseif current==entry[2] and current~=a.original_config[entry[1]] then
                                done=write(H.CONFIG_SET,h,entry[1],a.original_config[entry[1]]) and done
                                done=bool(H.CONFIG_GET,h,entry[1],true)==a.original_config[entry[1]] and done
                            end
                        end
                    end
                    if a.original_group then
                        local current=int(H.GROUP_GET,h)
                        if current==nil then done=false
                        elseif current%0x100000000==r.hostile_group then
                            done=write(H.GROUP_SET,h,a.original_group) and done
                            local restored=int(H.GROUP_GET,h)
                            done=restored~=nil and restored%0x100000000==a.original_group and done
                        end
                    end
                end
                if done then r.actors[h]=nil end
            end
            r.cleanup_cursor=#keys>0 and (start+8-1)%#keys+1 or 1
            if next(r.actors or {}) then return end
            if not release_hostility(r) then return end
        end
        if r.kind~="angry_monke" then finish(r);return end
        if epoch_changed(r) then
            -- CreatePed(autoCleanup=true) owns old-session disposal. Never look
            -- up or delete an old handle after the host session epoch changes.
            r.actor=nil;r.unresolved_spawn=nil
            r.reason="session changed; previous actor left to host auto-cleanup"
            release_model(r)
            if not r.model_requested and release_hostility(r) then finish(r) end
            return
        end
        -- Cleanup is session-bound, but does not require the departed target.
        -- Unknown session/local identity pauses deletion, never touches stale pointers.
        if not in_scope(r) then
            if bool(H.SESSION)==false then
                r.actor=nil;r.unresolved_spawn=nil;release_model(r)
                if not r.model_requested and release_hostility(r) then finish(r) end
            end
            return
        end
        release_model(r)
        if r.actor then
            local found,why=matches(r.actor)
            if not found and (why=="gone" or why=="replaced") then r.actor=nil
            elseif found and t>=(r.next_cleanup or 0) then
                r.next_cleanup=t+500
                if control(r.actor,t) then
                    local m=deps.Memory
                    if m and type(m.AllocInt)=="function" and type(m.WriteInt)=="function" and type(m.Free)=="function" then
                        local ok,ptr=pcall(m.AllocInt)
                        if ok and integer(ptr) and ptr~=0 then
                            local stored=pcall(m.WriteInt,ptr,r.actor.handle)
                            if stored and (not stopped or draining) and in_scope(r) and matches(r.actor)
                                and bool(H.CONTROL,r.actor.handle)==true then
                                write(H.SET_MISSION,r.actor.handle,true,true)
                                if matches(r.actor) and in_scope(r) and bool(H.CONTROL,r.actor.handle)==true then
                                    m.WriteInt(ptr,r.actor.handle);write(H.DELETE,ptr)
                                    if matches(r.actor) and in_scope(r) and bool(H.CONTROL,r.actor.handle)==true then
                                        m.WriteInt(ptr,r.actor.handle);write(H.DELETE_ENTITY,ptr)
                                    end
                                end
                            end
                            pcall(m.Free,ptr)
                        end
                    end
                    local current,reason=matches(r.actor)
                    if not current and (reason=="gone" or reason=="replaced") then r.actor=nil end
                end
            end
        end
        if not r.actor and not r.model_requested and not r.unresolved_spawn and release_hostility(r) then finish(r) end
    end
    local function begin(kind,pid)
        pid=tonumber(pid)
        if stopped then return nil,"effects are stopping" end
        if not integer(pid) or pid<0 or pid>31 then return nil,"invalid player" end
        if runs[kind] then return nil,"this effect or its cleanup is already active" end
        if bool(H.SESSION)~=true then return nil,"an online session is required" end
        local ok,lid=pcall(deps.local_player_id)
        local local_identity=ok and player(lid)
        local target=player(pid)
        if not target or not local_identity then return nil,"player connection identity unavailable" end
        local key=session_key()
        if type(deps.session_key)=="function" and key==nil then return nil,"session epoch unavailable" end
        local r={kind=kind,pid=pid,target=target,local_identity=local_identity,session_key=key,phase="queued",started=now(),reason="queued"}
        runs[kind]=r;return r
    end
    local function target_state(r)
        if not in_scope(r) or not same_player(r.target) then return nil,"player or session changed" end
        local p,l=ped(r.pid),ped(r.local_identity.pid)
        if not p or not l then return nil,"player ped is not streamed" end
        local dead=bool(H.DEAD,p.handle,false)
        if dead==true then return nil,"target is dead" end
        if dead~=false then return nil,"target state unreadable" end
        return p,nil,l
    end
    local function nearby(p,l)
        local a=vec(H.COORDS,p.handle,false)
        if not a then return nil end
        local interior=int(H.INTERIOR,p.handle)
        if interior==nil then return nil end
        if interior~=0 and bool(H.INTERIOR_READY,interior)~=true then return nil end
        -- Spectating streams the target while the local body stays elsewhere.
        if bool(H.COLLISION_LOADED,p.handle)~=true then return nil end
        return a,interior
    end
    local function car(r,p,t)
        local h=int(H.VEHICLE,p.handle,false)
        if r.grip_vehicle and (h~=r.grip_vehicle.handle or not matches(r.grip_vehicle)) then
            local old,why=matches(r.grip_vehicle)
            if not old and (why=="gone" or why=="replaced") then r.grip_vehicle=nil
            elseif old and control(r.grip_vehicle,t) and write(H.GRIP,old.handle,false) and write(H.GRIP_LEVEL,old.handle,0) then r.grip_vehicle=nil
            else r.phase="restoring previous vehicle grip";return nil end
        end
        if not h or h==0 then r.vehicle=nil;return nil end
        if not r.vehicle or r.vehicle.handle~=h or not matches(r.vehicle) then r.vehicle=physical(h) end
        local v=r.vehicle
        local supported = v and (r.kind=="dismember_vehicle"
            and bool(H.MODEL_VEHICLE,v.model)==true or bool(H.CAR,v.model)==true)
        if not supported or bool(H.DEAD,h,false)~=false then return nil end
        if not control(v,t) then
            if v.control_since and t-v.control_since>2500 then
                if r.kind=="break_vehicle"then r.phase="waiting for vehicle control"
                else cancel(r,"vehicle authority unavailable")end
            end
            return nil
        end
        return v
    end
    local function break_context(r,p,v)
        -- Every impulse belongs to this exact driver, connection, session and
        -- physical vehicle. Destination/control reads are not write authority.
        if not active(r) or not in_scope(r) or not same_player(r.target)
            or not matches(p) or not matches(v) then return false end
        local current_ped=ped(r.pid)
        if not current_ped or current_ped.address~=p.address or current_ped.handle~=p.handle
            or current_ped.model~=p.model or current_ped.network_id~=p.network_id then return false end
        return int(H.VEHICLE,p.handle,false)==v.handle and int(H.DRIVER,v.handle,-1,false)==p.handle
            and bool(H.DEAD,p.handle,false)==false and bool(H.DEAD,v.handle,false)==false and active(r)
    end
    local function break_fence(r,p,v)
        return break_context(r,p,v) and bool(H.CONTROL,v.handle)==true and break_context(r,p,v)
    end
    local function break_step(r,p,t)
        if t<(r.next_jolt or 0) then return end
        local h=int(H.VEHICLE,p.handle,false)
        if not h or h==0 then r.vehicle=nil;r.phase="waiting for driver vehicle";return end
        local v=physical(h)
        if not v or bool(H.MODEL_VEHICLE,v.model)~=true or int(H.DRIVER,h,-1,false)~=p.handle
            or bool(H.DEAD,h,false)~=false then r.phase="waiting for driver vehicle";return end
        r.vehicle=v
        if not control(v,t,function()return break_context(r,p,v)end) then r.phase="waiting for vehicle control";return end
        local plane,heli=bool(H.PLANE,v.model),bool(H.HELI,v.model)
        local airborne=bool(H.AIR,h)
        local speed=number(deps.invoke_float_detail,H.SPEED,h)
        if plane==nil or heli==nil or airborne==nil or speed==nil then return end
        if speed<1.0 and not ((plane or heli) and airborne) then r.phase="waiting for movement";return end
        local downward=(plane or heli) and airborne
        local magnitude=downward and -math.random(25,65)/100 or math.random(35,85)/100
        local ox,oy=math.random(-30,30)/100,math.random(-50,50)/100
        -- Internal impulse, world vertical force, local offset below the body,
        -- mass relative. Ground lift is well below the existing 4.5 Vehicle Hop.
        -- Aircraft receive a world-downward pulse, independent of their attitude.
        if not break_fence(r,p,v) then return end
        r.next_jolt=t+math.random(180,650)
        if not apply(r,H.FORCE,h,1,0.0,0.0,magnitude,ox,oy,-0.45,0,false,true,true,false,true) then
            cancel(r,"physical jolt rejected");return
        end
        r.phase=downward and "irregular downward jolts" or "irregular underside jolts"
    end
    -- Type-specific native damage. Damaged model fragments are not necessarily
    -- physically separate entities on every vehicle model.
    local function dismember_step(r,p,t)
        local v=car(r,p,t)
        if not v then
            if t-r.started>=3000 then cancel(r,"no streamed controlled vehicle") end
            return
        end
        local h=v.handle
        local plane,heli=bool(H.PLANE,v.model),bool(H.HELI,v.model)
        if plane==nil or heli==nil then cancel(r,"vehicle type unreadable");return end
        local function current()
            return active(r) and in_scope(r) and same_player(r.target)
                and matches(v)~=nil and int(H.VEHICLE,p.handle,false)==h
                and bool(H.CONTROL,h)==true and bool(H.DEAD,h,false)==false
        end
        if not current() then cancel(r,"vehicle identity changed");return end
        r.detached,r.wheels_damaged,r.rotors_damaged,r.wings_damaged=0,0,0,0
        -- Detachable doors, glass and supported roofs remain available.
        for i=0,7 do
            if not current() then cancel(r,"vehicle changed");return end
            if bool(H.DOOR_VALID,h,i)==true
                and apply(r,H.DOOR_BROKEN,h,i,false) then r.detached=r.detached+1 end
        end
        for i=0,7 do
            if not current() then cancel(r,"vehicle changed");return end
            if bool(H.WINDOW_INTACT,h,i)==true then apply(r,H.WINDOW,h,i)end
        end
        if not plane and not heli then
            -- A wheel's internal mesh detachment is model/fragment-dependent.
            -- No spawned collision wheel or invented BREAK_OFF native.
            if current() then apply(r,H.WHEEL_BREAKABLE,h,true) end
            local wheel_points={{id=0,x=-0.9,y=1.2,z=-0.42},
                {id=1,x=0.9,y=1.2,z=-0.42},
                {id=4,x=-0.9,y=-1.25,z=-0.42},
                {id=5,x=0.9,y=-1.25,z=-0.42}}
            for _,wheel in ipairs(wheel_points)do
                if not current()then cancel(r,"vehicle changed");return end
                local burst=bool(H.IS_TYRE_BURST,h,wheel.id,false)
                if burst==false and apply(r,H.TYRE_BURST,h,wheel.id,true,950.0)then
                    r.wheels_damaged=r.wheels_damaged+1
                end
                if current()then apply(r,H.VEHICLE_DAMAGE,h,
                    wheel.x,wheel.y,wheel.z,115.0,0.9,true)end
            end
            local roof=int(H.BONE,h,"roof")
            if roof and roof>=0 and current()then apply(r,H.ROOF,h,0.0,0.0,2.0)end
        elseif heli then
            -- Rotor health/fragment damage, without setting engine health to 0
            -- or using any EXPLODE_VEHICLE call.
            local main=number(deps.invoke_float_detail,H.ROTOR_MAIN,h)
            local tail=number(deps.invoke_float_detail,H.ROTOR_TAIL,h)
            if main and main>0 and current()
                and apply(r,H.ROTOR_MAIN_SET,h,math.min(main,225.0))then
                r.rotors_damaged=r.rotors_damaged+1
            end
            if tail and tail>0 and current()
                and apply(r,H.ROTOR_TAIL_SET,h,math.min(tail,225.0))then
                r.rotors_damaged=r.rotors_damaged+1
            end
            if current()then apply(r,H.VEHICLE_DAMAGE,h,0.0,0.0,2.25,120.0,0.9,true)end
        else
            -- Aircraft have no generic detachable-wing native. Aim native
            -- fragment damage at wing sections; no forced explosion.
            for _,x in ipairs({-2.2,2.2})do
                if not current()then cancel(r,"vehicle changed");return end
                if apply(r,H.VEHICLE_DAMAGE,h,x,0.1,0.45,140.0,1.2,true)then
                    r.wings_damaged=r.wings_damaged+1
                end
            end
        end
        cancel(r,("Native structural damage: doors=%d wheels=%d rotors=%d wings=%d; visible detachment model-dependent")
            :format(r.detached,r.wheels_damaged,r.rotors_damaged,r.wings_damaged))
    end
    local function monke_step(r,p,l,t)
        if r.model_requested and not r.actor and r.load_started and t-r.load_started>=4000
            and bool(H.MODEL_LOADED,r.model)~=true then cancel(r,"chimp model load timed out");return end
        local position,interior=nearby(p,l)
        if not position then
            -- Keep one actor; never teleport to a remote/unstreamed interior.
            r.phase="waiting for streamed target"
            return
        end
        if not r.model then
            r.model=int(H.HASH,"a_c_chimp");r.weapon=int(H.HASH,"WEAPON_BAT")
            if r.model then r.model=r.model%0x100000000 end
            if r.weapon then r.weapon=r.weapon%0x100000000 end
            if not r.model or not r.weapon or bool(H.MODEL_VALID,r.model)~=true or bool(H.MODEL_PED,r.model)~=true then
                cancel(r,"chimp model unavailable");return
            end
            r.model_requested=true;r.load_started=t
            if not apply(r,H.REQUEST_MODEL,r.model) then cancel(r,"model request rejected") end
            return
        end
        if not r.actor then
            if bool(H.MODEL_LOADED,r.model)~=true then
                if t-r.load_started>=4000 then cancel(r,"chimp model load timed out") end
                return
            end
            if not deps.GTA or type(deps.GTA.CreatePed)~="function" then cancel(r,"ped spawning unavailable");return end
            if t<(r.next_spawn or 0) then return end
            r.spawn_attempts=(r.spawn_attempts or 0)+1;r.next_spawn=t+750
            local ok,h=pcall(deps.GTA.CreatePed,r.model,4,position.x+1.5,position.y,position.z,0.0,true,true)
            if not ok then cancel(r,"chimp creation error: "..tostring(h));return end
            if not integer(h) or h==0 then
                if r.spawn_attempts>=3 then cancel(r,"chimp creation failed after 3 attempts") end
                return
            end
            local a=physical(h)
            if not a or a.model~=r.model or a.address==p.address or a.address==l.address then
                r.unresolved_spawn=h;cancel(r,"spawn identity unavailable; host auto-cleanup retained");return
            end
