]====],
    ["modules/player_bounty.lua"] = [====[
-- Freemode bounty renewal, scoped to one session and connection identity.
-- Enhanced 1158 source: freemode func_16641 (23-word event), func_25589/25590
-- (validation + assignment), func_16644 (host-synchronized active flag),
-- func_3899/25052 (rotating event tokens). No globals or account stats are written.
local Module = { Name = "modules.player_bounty", MigrationPhase = "17.75" }
local context, instances = nil, {}
local PROFILE = {
    event = 1517551547, words = 23,
    active_base = 1835603 + 4 + 1, header = 1835603 + 4, stride = 3,
    maximum = 262145 + 2337,
    token_a = 1923118 + 9, token_b = 1923118 + 10,
