  local v=a.observed_position;local wanted=a.command_position
  local function xyz(q)return q and string.format("%.2f,%.2f,%.2f",q.x,q.y,q.z)or"unreadable"end
  pcall(deps.log_info,string.format("Hammer trace run=%s player=%s stage=%s handle=%s model=%s net=%s nativeNet=%s visible=%s pos={%s} requested={%s} fall=%.2f elapsed=%sms reason=%s",
   tostring(r.serial),tostring(r.pid),stage,tostring(a.handle),tostring(a.model),tostring(a.network_id),tostring(a.native_network_id),
   tostring(a.visible),xyz(v),xyz(wanted),tonumber(a.observed_fall)or 0,tostring(t-a.born),tostring(reason or r.reason)))
