   or not apply(r,a,H.FREEZE,a.handle,true)
   or not apply(r,a,H.GRAVITY,a.handle,false)
   or not apply(r,a,H.COLLISION,a.handle,true,true)
   or not apply(r,a,H.VISIBLE,a.handle,true,false)
