  if not control(a,t)then
   if a.control_since and t-a.control_since>2500 then
    if r.spec.sustained then r.reason="waiting for actor control" else cancel(r,"created entity authority unavailable")end
   end
   return false
  end
  if r.kind=="hammer_of_god"then return configure_hammer(r,a,t)end
  if not a.physics_ready and (not apply(r,a,H.MISSION,a.handle,true,false)
    or not apply(r,a,H.FREEZE,a.handle,false) or not apply(r,a,H.COLLISION,a.handle,true,true)
    or not apply(r,a,H.DYNAMIC,a.handle,true) or not apply(r,a,H.GRAVITY,a.handle,true)
    or not apply(r,a,H.LOAD_COLLISION,a.handle,true,0)
