   local speed=r.kind=="hammer_of_god" and 170.0 or 55.0
   apply(r,a,H.MAX_SPEED,a.handle,speed+20)
   if not apply(r,a,H.VELOCITY,a.handle,0.0,0.0,-speed)then cancel(r,"drop velocity rejected");return false end
  elseif r.kind=="kamikaze_jet"then
