 -- Occupant-preserving goal pursuit. No ped task/seat takeover is attempted:
 -- authority over a borrowed vehicle is not authority over its player driver.
 local function possession_context(r,p,a)
  if not current(r)or not scope(r)or not same_player(r.target)or not matches(p)or not matches(a)then return false end
  local ok,h=pcall(deps.player_ped,r.pid)
  return ok and h==p.handle and int(H.CAR,p.handle,false)==a.handle
   and int(H.DRIVER,a.handle,-1,false)==p.handle and bool(H.DEAD,p.handle,false)==false
   and bool(H.DEAD,a.handle,false)==false and current(r)
 end
 local function possession_fence(r,p,a)
  return possession_context(r,p,a)and bool(H.CONTROL,a.handle)==true and possession_context(r,p,a)
 end
 local function possession_write(r,p,a,h,...)
  return possession_fence(r,p,a)and write(h,...)and current(r)
 end
 local function output_buffer(bytes,fn)
  local m=deps.Memory
  if not m or type(m.Alloc)~="function"or type(m.Free)~="function"or type(m.ReadFloat)~="function"
   or type(m.WriteFloat)~="function"or type(m.ReadInt)~="function"or type(m.WriteInt)~="function"then return end
  local ok,ptr=pcall(m.Alloc,bytes)
  if not ok or not integer(ptr)or ptr<=0 then return end
  local ran,a,b,c=pcall(fn,m,ptr)
  pcall(m.Free,ptr)
  if ran then return a,b,c end
