 local function output_vector(m,ptr)
  -- Cherax native scrVector ABI: float slots 0/8/16, not packed 0/4/8.
  local x,y,z=m.ReadFloat(ptr),m.ReadFloat(ptr+8),m.ReadFloat(ptr+16)
  if finite(x)and finite(y)and finite(z)and math.abs(x)<100000 and math.abs(y)<100000 and math.abs(z)<100000 then
   return{x=x,y=y,z=z}
  end
 end
 -- Panels and smoke handles are owned here. Native gas fields expire in the
 -- engine; they are paced separately and cannot be cancelled by an FX handle.
