 function tear.Headroom(amount)
  local pool=deps.PoolMgr
  if not pool or type(pool.GetCurrentObjectCount)~="function"or type(pool.GetMaxObjectCount)~="function"then return false end
  local ok,used,maximum=pcall(function()return pool.GetCurrentObjectCount(),pool.GetMaxObjectCount()end)
  return ok and integer(used)and integer(maximum)and used>=0 and maximum>0
   and maximum-used>=amount and bool(H.CAN_OBJECTS,amount)==true
