 drain_probe_jobs=function()
  -- Native probe jobs own no borrowed entity mutations, but their exact tokens
  -- must reach status0/2 before unload can release this Lua context.
  for _=1,math.min(4,#probe_debt)do
   local probe=table.remove(probe_debt,1)
