 local function road_node(r,p,a,at,goal,water)
  return output_buffer(32,function(m,ptr)
   for _,off in ipairs({0,8,16,24})do m.WriteFloat(ptr+off,1000000)end
   if not possession_fence(r,p,a)then return end
