   m.WriteInt(ptr+24,-1);m.WriteInt(ptr+28,-1)
   if bool(H.NODE_PROPERTIES,point.x,point.y,point.z,ptr+24,ptr+28)~=true then return end
   local density,flags=m.ReadInt(ptr+24),m.ReadInt(ptr+28)
