     local heading=math.atan(forward.y,forward.x)+math.rad(math.random(-110,110))
     local radius=math.random(180,450)
     to={x=at.x+math.cos(heading)*radius,y=at.y+math.sin(heading)*radius,z=at.z-math.random(15,70)}
    else
     -- Probe a little beyond the measured facade so the same surface can be
     -- observed again instead of relying on an indefinitely cached ray result.
     local dx,dy,dz=unit(to.x-at.x,to.y-at.y,to.z-at.z)
     to={x=to.x+dx*3,y=to.y+dy*3,z=to.z+dz*3}
    end
    start_route_probe(r,p,a,s,at,to,t)
   end
   if not s.goal or not s.proof_at or t-s.proof_at>500 or distance(at,s.proof_origin)>50 then
    r.phase="waiting";r.reason="searching streamed structure collision";return
   end
  else
   if s.goal and (t>=s.goal_until or distance(at,s.goal)<15)then s.goal=nil;s.waypoint=nil;s.clear=nil end
   if not s.goal and t>=(s.next_goal or 0)then
    s.next_goal=t+500
    local angle=math.rad(math.random(0,359));local radius=math.random(120,300)
    local sample={x=at.x+math.cos(angle)*radius,y=at.y+math.sin(angle)*radius,z=at.z}
    local goal=road_node(r,p,a,sample,nil,boat)
    if goal and distance(at,goal)>=50 and distance(at,goal)<=600 and math.abs(goal.z-at.z)<=30 then
     s.goal=goal;s.goal_until=t+math.random(12000,25000);s.speed=math.random(10,16);s.clear=nil
    end
   end
   if not s.goal then r.phase="waiting";r.reason="searching streamed road/water nodes";return end
   if t>=(s.next_waypoint or 0)then
    s.next_waypoint=t+250
    local dx,dy=unit(s.goal.x-at.x,s.goal.y-at.y,0)
    local sample={x=at.x+dx*22,y=at.y+dy*22,z=at.z}
    local waypoint=road_node(r,p,a,sample,s.goal,boat)
    if waypoint and distance(at,waypoint)>=5 and distance(at,waypoint)<=65 and math.abs(waypoint.z-at.z)<=12 then
     s.waypoint=waypoint
