   end
   if not s.waypoint then r.phase="waiting";r.reason="local node pursuit unavailable";return end
   start_route_probe(r,p,a,s,{x=at.x,y=at.y,z=at.z+0.8},
    {x=s.waypoint.x,y=s.waypoint.y,z=s.waypoint.z+0.8},t)
