  if flying then
   local rotation=vec(H.ROTATION_GET,h,2)
   if not rotation then return end
   local pitch=clamp(math.deg(math.atan(dz,flat)),-25,15)
   local roll=clamp(-math.deg(error)*0.6,-35,35)
   local rightx,righty=fy,-fx
