   local roll_rate=clamp(math.rad(roll-rotation.y)*1.4-(angular.x*fx+angular.y*fy)*0.4,-0.8,0.8)
   local yaw_rate=clamp(error*0.7-angular.z*0.25,-0.6,0.6)
   if not possession_write(r,p,a,H.ANGULAR,h,rightx*pitch_rate+fx*roll_rate,righty*pitch_rate+fy*roll_rate,yaw_rate)then return end
   local speed=category=="plane"and 45 or 20
   local along=velocity.x*fx+velocity.y*fy
   local thrust=clamp((speed-along)*0.03,0,category=="plane"and 0.35 or 0.25)
   local vx,vy=fx*thrust,fy*thrust
