 -- Closest point on an observed movement segment, never an intended path.
 local function sweep(a,b,p)
  local dx,dy,dz=b.x-a.x,b.y-a.y,b.z-a.z
  local n=dx*dx+dy*dy+dz*dz
  local u=n>0.0001 and clamp(((p.x-a.x)*dx+(p.y-a.y)*dy+(p.z-a.z)*dz)/n,0,1)or 0
  local q={x=a.x+dx*u,y=a.y+dy*u,z=a.z+dz*u}
  return q,distance(q,p)
 end
 local function motion(r,a,origin,vx,vy,vz,t)
  local dt=clamp((t-(a.last_guidance or t))/1000,0,0.1)
  a.last_guidance=t
  if not a.probe_origin then a.probe_origin=origin;a.probe_at=t end
  if not a.kinematic and t-a.probe_at>=200 then
   local expected=math.sqrt(vx*vx+vy*vy+vz*vz)*(t-a.probe_at)/1000
   if expected>2 and distance(origin,a.probe_origin)<expected*0.15
     and (a.phased or bool(H.CONTACT,a.handle)~=true or r.kind=="ghost_vehicle" or r.kind=="kamikaze_jet")then
    -- Certain static map props accept velocity but never start simulating.
    -- Recover only our verified owned actor with a time-scaled transform step.
    a.kinematic=true
    if type(deps.log_info)=="function"then pcall(deps.log_info,r.spec.name..": stalled physics; guided transform recovery")end
   end
   a.probe_at=t;a.probe_origin=origin
  end
  if a.kinematic and dt>0 then
   apply(r,a,H.POSITION,a.handle,origin.x+vx*dt,origin.y+vy*dt,origin.z+vz*dt,false,false,false)
  end
