   end
   local dx,dy,dz=unit(aim_x-origin.x,aim_y-origin.y,aim_z-origin.z)
   apply(r,a,H.ROTATION,a.handle,math.deg(math.asin(clamp(dz,-1,1))),0.0,
    math.deg(math.atan(-dx,dy)),2,true)
   motion(r,a,origin,dx*speed,dy*speed,dz*speed,t)
   r.reason="ghost pursuit; target speed="..string.format("%.1f",measured)..
    " m/s, requested speed="..string.format("%.1f",speed).." m/s"
   return
  end
  if r.kind~="kamikaze_jet" and r.kind~="hammer_of_god" and r.kind~="cargo_guillotine"then return end
  if a.impact then return end
  if r.kind=="kamikaze_jet"then
   if not ensure_jet_pilot(r,a,p,pos,t)then r.reason="waiting for pilot/aircraft control";return end
   retain_hammer(r,a,t)
   if a.launch_origin and distance(a.launch_origin,origin)>=12.0 and not a.flight_verified then
    a.flight_verified=true
    if type(deps.log_info)=="function"then pcall(deps.log_info,"Jet flight observed run="..r.serial.." travel="..string.format("%.2f",distance(a.launch_origin,origin)))end
   end
  end
  local clear=bool(H.LOS,a.handle,p.handle,17)==true
  local phased=not clear or (r.kind=="kamikaze_jet" and (distance(origin,pos)>3.0 or bool(H.CONTACT,a.handle)==true))
  local collision_changed=a.phased~=phased
  if collision_changed then
   -- Avoid catching the container/aircraft on a distant roof or wall. Only
   -- this script-created body phases, and it is solid again for the impact.
   if apply(r,a,H.COLLISION,a.handle,not phased,true)then a.phased=phased end
  end
  local closest,near=sweep(a.last_position or origin,origin,pos)
  local contact=t-a.born>=120 and not a.phased and not collision_changed and bool(H.CONTACT,a.handle)==true
  local swept=t-a.born>=120 and near<=4.0 and clear
  if (contact or swept)and (r.kind~="kamikaze_jet"or a.flight_verified)then
   local at=contact and origin or closest
   a.impact=true;r.impact_at=t;r.reason=contact and "collision observed"or "target crossing observed"
   if current(r)and matches(a)and bool(H.CONTROL,a.handle)==true then
    if not impact_blast(r,a,at,t)then cancel(r,"impact effect rejected")end
   end
   return
  end
  a.last_position=origin
  if r.kind=="kamikaze_jet"then
   local speed=110.0;local lead=clamp(distance(origin,pos)/speed,0,1.2)
   local dx,dy,dz=unit(pos.x+clamp(tv.x,-90,90)*lead-origin.x,pos.y+clamp(tv.y,-90,90)*lead-origin.y,pos.z+clamp(tv.z,-30,30)*lead-origin.z)
   if not a.flight_ready then
    apply(r,a,H.GRAVITY,a.handle,false)
    apply(r,a,H.LANDING_GEAR,a.handle,3);a.flight_ready=true
   end
   apply(r,a,H.ENGINE,a.handle,true,true,false)
   apply(r,a,H.ROTATION,a.handle,math.deg(math.asin(clamp(dz,-1,1))),0.0,math.deg(math.atan(-dx,dy)),2,true)
   apply(r,a,H.ANGULAR,a.handle,0.0,0.0,0.0)
   apply(r,a,H.FORWARD_SPEED,a.handle,speed)
   motion(r,a,origin,dx*speed,dy*speed,dz*speed,t)
  else
   local speed=r.kind=="hammer_of_god"and 170.0 or 55.0
   local lead=clamp((origin.z-pos.z)/speed,0.08,1.5)
   local vx=clamp((pos.x+clamp(tv.x,-80,80)*lead-origin.x)/math.max(lead,0.12),-90,90)
   local vy=clamp((pos.y+clamp(tv.y,-80,80)*lead-origin.y)/math.max(lead,0.12),-90,90)
   motion(r,a,origin,vx,vy,-speed,t)
   if origin.z<pos.z-12 then cancel(r,"drop passed target without impact")end
  end
 end
 -- The damaging phase is already over. Settle only its exact owned boulder;
 -- a dead/despawned target or a new respawn location is irrelevant here.
 local function hammer_aftermath(r,t)
  if not scope(r)then cancel(r,"session changed during Hammer aftermath");return end
  local a=r.actors[1];local found,why=matches(a)
  if not found then cancel(r,"Hammer aftermath entity "..tostring(why));return end
  local landing=r.landing
  if not landing then
   landing={started=t,last_step=t};r.landing=landing
   r.phase="settling";r.reason="finishing boulder descent"
  end
  if not control(a,t)then
   landing.last_step=t
   if t-landing.started>=15000 then cancel(r,"Hammer ground settling control timed out")end
   return
  end
  local at=vec(H.COORDS,a.handle,false)
  if not at then
   if t-landing.started>=15000 then cancel(r,"Hammer aftermath coordinates unavailable")end
   return
  end
  a.observed_position=at
  if landing.placed then
   if distance(at,landing.placed)<=0.15 then
    if not landing.grounded_at then
     landing.grounded_at=t;r.phase="grounded";r.reason="boulder resting on ground"
     hammer_trace(r,a,"ground-rest",t,"object placement accepted; position stable")
    end
    if t-landing.grounded_at>=3000 then cancel(r,"Hammer ground rest completed")end
    return
   end
   landing.placed=nil;landing.grounded_at=nil;landing.ground=nil
  end
  if t-landing.started>=15000 then cancel(r,"Hammer ground settling timed out");return end
  local dt=clamp((t-landing.last_step)/1000,0,0.1);landing.last_step=t
  if t>=(landing.next_collision or 0)then
   landing.next_collision=t+250
   apply(r,a,H.LOAD_COLLISION,a.handle,true,0)
  end
  if not landing.ground and t>=(landing.next_ground or 0)then
   landing.next_ground=t+250
   local get=deps.GTA and deps.GTA.GetGroundZ
   if type(get)=="function"then
    local ok,known,z=pcall(get,at.x,at.y)
    -- Ground helpers can yield. Never continue a cancelled/retriggered run,
    -- a recycled entity, or a previous-session request after returning.
    if not current(r)or not scope(r)or not matches(a)
      or bool(H.CONTROL,a.handle)~=true then return end
    if ok and known==true and finite(z)and z<=at.z+0.25 then landing.ground=z end
   end
  end
  if landing.ground==nil then r.reason="waiting for streamed ground";return end
  if not landing.collision_ready then
   if not apply(r,a,H.COLLISION,a.handle,true,true)
