     or bool(H.CONTROL,a.handle)~=true then return end
   local actual=vec(H.COORDS,a.handle,false)
   if placed==true and actual and math.abs(actual.x-at.x)<=1.0 and math.abs(actual.y-at.y)<=1.0
     and actual.z>=landing.ground-0.25 and actual.z<=landing.ground+12.0 then
    landing.placed=actual -- Require another stable observation before resting.
   end
   return
  end
