   end
  end
 end
 local function fling(r,p,pos,t)
  local vehicle=int(H.CAR,p.handle,false)
  local body=vehicle and vehicle~=0 and physical(vehicle)or p
  if not body then cancel(r,"Fling body unavailable");return end
  if r.fling_body and (r.fling_body.handle~=body.handle or not matches(r.fling_body))then cancel(r,"Fling body changed");return end
  r.fling_body=r.fling_body or body
  local function fence()return current(r)and scope(r)and same_player(r.target)and matches(p)~=nil and matches(body)~=nil end
  if r.fling_sent then
   local v=vec(H.VELOCITY_GET,body.handle)
   if v and v.z>30 then cancel(r,"launch motion observed locally; recipient visibility unverified")
   elseif t-r.fling_sent>=750 then cancel(r,"Fling command had no observed launch")end
   return
  end
  -- Local, on-foot physics test only. Never use this ragdoll path on a
  -- remote ped: the target's client owns its ragdoll simulation.
  local local_ok,local_id=pcall(deps.local_player_id)
  if local_ok and integer(local_id) and r.pid==local_id and vehicle==0 then
   if not fence()or bool(H.CONTROL,p.handle)~=true then
    cancel(r,"self fling control unavailable");return
   end
   if not r.self_ragdoll_requested_at then
    if bool(H.PED_RAGDOLL,p.handle,3500,3500,0,true,true,false)~=true then
     cancel(r,"self fling ragdoll request rejected");return
    end
    r.self_ragdoll_requested_at=t;r.reason="waiting for local ragdoll confirmation";return
   end
   if bool(H.IS_PED_RAGDOLL,p.handle)~=true then
    if t-r.self_ragdoll_requested_at>=750 then
     cancel(r,"self fling ragdoll not observed; check no-ragdoll settings")
    end
    return
   end
   local forward=vec(H.FORWARD,p.handle)
   local flat=forward and math.sqrt(forward.x*forward.x+forward.y*forward.y)
   if not finite(flat)or flat<0.0001 then
    cancel(r,"self fling facing unavailable");return
   end
   local speed,tilt=260.0,math.rad(10.0)
   local horizontal=speed*math.sin(tilt)
   local vx,vy=forward.x/flat*horizontal,forward.y/flat*horizontal
   local vz=speed*math.cos(tilt)
   if not fence()or not apply(r,p,H.VELOCITY,p.handle,vx,vy,vz)then
    cancel(r,"self fling physics launch rejected");return
