-- Fatal bootstrap errors must be visible when the outer preloader fails.
-- The previous no-op hid the true reason while the UI only said BOOT FAILED.
local function bootstrap_log(level, message)
    if level == "LogError" and Logger and type(Logger.LogError) == "function" then
        return pcall(Logger.LogError, "[CScript bootstrap] " .. tostring(message))
    end
    return true
end

local function bootstrap_toast(message, duration)
    if GUI and type(GUI.AddToast) == "function" and eToastPos and eToastPos.TOP_RIGHT then
        pcall(GUI.AddToast, LOADER_NAME, tostring(message), duration or 6500, eToastPos.TOP_RIGHT)
    end
end

local function traceback(message)
    if debug and type(debug.traceback) == "function" then
        return debug.traceback(tostring(message), 2)
    end
    return tostring(message)
end

local required = Utils and type(Utils.Joaat) == "function"
    and FeatureMgr and type(FeatureMgr.AddFeature) == "function"
    and ClickGUI and type(ClickGUI.AddTab) == "function"
    and Script and type(Script.RegisterLooped) == "function"
    and EventMgr and type(EventMgr.RegisterHandler) == "function"
    and eLuaEvent and eLuaEvent.ON_UNLOAD ~= nil

if not required then
    bootstrap_log("LogError", "phase=preflight module=loader error=required Cherax Enhanced APIs unavailable")
    bootstrap_toast("CScript needs a compatible Cherax version.", 7000)
    return
end

-- An active runtime must finish its own stop and restore before replacement.
if rawget(_G, "CScript") ~= nil then
    local message = "CScript is already running. Unload it before loading this version."
    bootstrap_log("LogError", message)
    bootstrap_toast(message, 7000)
    return
end

