-- runtime table. Do not remove controls owned by an unrelated script.
if type(FeatureMgr.GetFeature) == "function" then
    local existing_hash = Utils.Joaat("JinxRebound_about")
    local ok, existing = pcall(FeatureMgr.GetFeature, existing_hash)
    if ok and existing then
        bootstrap_log("LogError",
            "phase=preflight module=loader error=existing JinxRebound_about feature detected; another Lua owns this namespace")
        bootstrap_toast(
            "CScript controls are already registered by another script. Unload it before loading CScript.",
            7000)
        return
    end
end

-- A previously crashed script can leave custom tab callbacks visible briefly
-- after its Lua state is gone. Remove only CScript-owned tab names before any
-- new feature or render callback is registered.
if type(ClickGUI.RemoveTab) == "function" then pcall(ClickGUI.RemoveTab, "CScript") end
if type(ClickGUI.RemovePlayerTab) == "function" then pcall(ClickGUI.RemovePlayerTab, "CScript") end

