    public.Diagnostics.Module = runtime.module
    public.Diagnostics.Failed = runtime.failed
    public.Diagnostics.Failure = runtime.failure
    public.Diagnostics.Controls = runtime.compat_controls
end

local function lifecycle_log(module_name, phase, status, detail)
    runtime.lifecycle_sequence = runtime.lifecycle_sequence + 1
    local message = ("[CScript Lifecycle] %03d module=%s phase=%s %s"):format(
        runtime.lifecycle_sequence, tostring(module_name), tostring(phase), tostring(status))
    if detail ~= nil and detail ~= "" then message = message .. " " .. tostring(detail) end
    if RAW_LOGGER and type(RAW_LOGGER.LogInfo) == "function" then pcall(RAW_LOGGER.LogInfo, message) end
end

local function script_directory()
    if debug and type(debug.getinfo) == "function" then
        local ok, info = pcall(debug.getinfo, 1, "S")
        local source = ok and info and tostring(info.source or "") or ""
        if source:sub(1, 1) == "@" then source = source:sub(2) end
        source = source:gsub("/", "\\")
        local directory = source:match("^(.*)\\[^\\]+$")
        if directory and directory ~= "" then
            if runtime.mode == "bundled" and directory:lower():sub(-5) == "\\dist" then
                directory = directory:sub(1, -6)
            elseif runtime.mode == "direct" and directory:lower():sub(-4) == "\\lua" then
                directory = directory .. "\\CScript"
            end
            return directory
        end
    end
    if FileMgr and type(FileMgr.GetMenuRootPath) == "function" then
        local ok, root = pcall(FileMgr.GetMenuRootPath)
        if ok and type(root) == "string" and root ~= "" then
            return root .. "\\Lua\\CScript"
        end
    end
    return nil
end

local ROOT = script_directory()
if not ROOT and runtime.mode == "direct" then
    bootstrap_log("LogError", "phase=preflight module=loader error=unable to resolve CScript module directory")
    bootstrap_toast("CScript could not start. Check its files and try again.", 7000)
    rawset(_G, "CScript", nil)
    return
end

local stop_all
local sample_test_features = NOOP

-- This is the one real Script.RegisterLooped registration for the host state.
-- Replacement runtimes reuse its dispatcher without accumulating idle loops.
local __public_dispatching, __public_pending_stop, __public_auth_closed = false, nil, false
local __public_close_state = { active = false, failed = false, unload = false }
local __public_request_stop
local function __public_revoke()
    if __public_auth_closed then return end
    __public_auth_closed = true
    __public_close_state.active = true
    pcall(__public_close)
    __public_close_state.active = false
end
local function __public_dispatch_work()
    if runtime.stopping then return end
    local ok, err = xpcall(runtime.tick, traceback)
    if not ok then
        runtime.tick = NOOP
        runtime.failed = true
        runtime.failure = {
            phase = "tick",
            module = runtime.module or "runtime",
            error = tostring(err),
        }
        local failed_module, failed_error = runtime.failure.module, runtime.failure.error
        __public_request_stop("Public runtime tick failed")
        update_diagnostics()
        bootstrap_log("LogError", ("phase=tick module=%s error=%s"):format(
            tostring(failed_module), tostring(failed_error)))
        return
    end
    if runtime.stopping or __public_pending_stop then return end
    sample_test_features()
end

__public_request_stop = function(reason)
    __public_pending_stop = __public_pending_stop or reason
    runtime.stopping = true
    if type(stop_all) == "function" then
        stop_all(__public_pending_stop, true)
    else
        -- Host callbacks can run before the cleanup function is assigned.
        -- Revoke now; defer module cleanup to the existing pending-stop check.
        __public_revoke()
    end
end
local function dispatch_runtime_tick()
    if runtime.stopping or __public_pending_stop or __public_dispatching then return end
    __public_dispatching = true
    local checked, admitted = pcall(__public_tick)
    if not checked or admitted ~= true then
        __public_dispatching = false
        __public_request_stop("Public authorization expired or rejected")
        return
    end
    if runtime.stopping or __public_pending_stop then
        __public_dispatching = false
        return
    end
    local worked = pcall(__public_dispatch_work)
    __public_dispatching = false
    if not worked then __public_request_stop("Public runtime dispatch failed") end
end

local loop_ok, loop_result = true, true
if loop_dispatcher.Registered ~= true then
    loop_ok, loop_result = pcall(RAW_SCRIPT.RegisterLooped, function()
        local callback = loop_dispatcher.Callback
        if type(callback) == "function" then return callback() end
    end)
    if loop_ok then loop_dispatcher.Registered = true end
end

if not loop_ok then
    bootstrap_log("LogError",
        "phase=lifecycle module=loader error=Script.RegisterLooped failed: " .. tostring(loop_result))
    rawset(_G, "CScript", nil)
    return
end
loop_dispatcher.Generation = (tonumber(loop_dispatcher.Generation) or 0) + 1
loop_dispatcher.Callback = dispatch_runtime_tick

local unload_ok, unload_handler = pcall(RAW_EVENT_MGR.RegisterHandler, eLuaEvent.ON_UNLOAD, function()
    if stop_all then stop_all("Cherax unload", false) end
end)
if not unload_ok then
    runtime.stopping = true
    runtime.tick = NOOP
    bootstrap_log("LogError",
        "phase=lifecycle module=loader error=ON_UNLOAD registration failed: " .. tostring(unload_handler))
    rawset(_G, "CScript", nil)
    return
end

local context = {
    CScript = public,
    Runtime = runtime,
    Root = ROOT,
    LoaderVersion = LOADER_VERSION,
    MigrationPhase = MIGRATION_PHASE,
    Core = public.Core,
    Bridges = public.Bridges,
    Modules = public.Modules,
    Raw = {
        Logger = RAW_LOGGER,
        ApartmentLogger = RAW_APARTMENT_LOGGER,
        Script = RAW_SCRIPT,
        Time = Time,
        EventMgr = RAW_EVENT_MGR,
        FeatureMgr = RAW_FEATURE_MGR,
        FileMgr = FileMgr,
        Natives = Natives,
        Memory = Memory,
        Players = Players,
        -- Resolve through the inherited Cherax environment, as for Players.
        -- rawget(_G, ...) misses host APIs in the single-file bundle.
        -- UI annotations are explicitly unverified and never evidence themselves.
        ModderDB = ModderDB,
        PoolMgr = PoolMgr,
        GTA = GTA,
        CVehicle = CVehicle,
        NetworkObjectMgr = NetworkObjectMgr,
        ScriptGlobal = ScriptGlobal,
        GUI = RAW_GUI,
        ClickGUI = RAW_CLICK_GUI,
        Utils = Utils,
        eLuaEvent = eLuaEvent,
        eToastPos = eToastPos,
        eFeatureType = eFeatureType,
        TestMode = rawget(_G, "__CSCRIPT_TEST_MODE") == true,
    },
}

-- Keep context copies and module globals on the same private permission view.
assert(rawget(context, "CScript") == public and getmetatable(context) == nil,
    "Public module context shape changed")
rawset(context, "CScript", nil)
local __public_context_fields = { CScript = __public_cscript }
setmetatable(context, {
    __index = __public_context_fields,
    __newindex = function(target, key, value)
        if key == "CScript" then
            assert(value == __public_cscript, "Public module context cannot replace authorization")
            return
        end
        rawset(target, key, value)
    end,
    __pairs = function() return __public_iter(context, __public_context_fields) end,
    __metatable = false,
})

local function rebuild_runtime_tick()
    if runtime.stopping or not runtime.callbacks_enabled then
        runtime.tick = NOOP
        return
    end
    local base = runtime.base_tick
    local framework = runtime.framework_tick
    if framework == nil then
        runtime.tick = base
    elseif base == NOOP then
        runtime.tick = framework
    else
        runtime.tick = function()
            base()
            framework()
        end
    end
end

context.SetFrameworkTick = function(callback)
    if callback ~= nil and type(callback) ~= "function" then
        error("framework tick must be a function or nil", 2)
    end
    runtime.framework_tick = callback
    rebuild_runtime_tick()
end

local function direct_path(relative_path)
    return ROOT .. "\\" .. relative_path:gsub("/", "\\")
end

local arm_record_handlers

local function inactive_event_result(event)
    if event == eLuaEvent.CAN_APPLY_NODE_DATA or event == eLuaEvent.SHOULD_COLLIDE then return true end
    if event == eLuaEvent.SCRIPTED_GAME_EVENT then return false end
    return nil
end

local function detach_handler(record, fake, info)
    -- Neutralize entry before calling the host, which can reenter cleanup.
    info.quiesced = true
    if info.registering or info.removing then
        info.removal_pending = true
        return false, "Event registration or removal is still in progress"
    end
    if info.real_id ~= nil then
        if record.event_ids[info.real_id] ~= fake then
            info.removal_pending = true
            return false, "Event handler ownership is unresolved"
        end
        if not (RAW_EVENT_MGR and type(RAW_EVENT_MGR.RemoveHandler) == "function") then
            info.removal_pending = true
            return false, "EventMgr.RemoveHandler is unavailable"
        end
        local real_id = info.real_id
        info.removing = true
        info.removal_pending = true
        local ok, result = pcall(RAW_EVENT_MGR.RemoveHandler, real_id)
        info.removing = false
        if not ok or result == false then
            info.removal_pending = true
            return false, result
        end
        -- The documented host removal returns void; nil is a successful result.
        if record.event_ids[real_id] == fake then record.event_ids[real_id] = nil end
        if info.real_id == real_id then info.real_id = nil end
    end
    info.removal_pending = false
    return true
end

local function remove_handler(record, handler_id)
    local fake = record.fake_handlers[handler_id] and handler_id or record.event_ids[handler_id]
    local info = fake and record.fake_handlers[fake]
    if not info then return false end
    local removed, detail = detach_handler(record, fake, info)
    if not removed then return false, detail end
    info.removed = true
    record.fake_handlers[fake] = nil
    for index = #record.pending_handlers, 1, -1 do
        if record.pending_handlers[index] == fake then table.remove(record.pending_handlers, index) end
    end
    return true
end

local function packed(...)
    return { n = select("#", ...), ... }
end

local function feature_type_label(value)
    if type(eFeatureType) == "table" then
        for key, candidate in pairs(eFeatureType) do
            if candidate == value then return tostring(key) end
        end
    end
    return tostring(value)
end

local function feature_callback_result(record, hash, name, ok, ...)
    if ok then return ... end
    bootstrap_log("LogError", ("phase=feature-callback module=%s name=%s hash=0x%08X error=%s")
        :format(tostring(record.name), tostring(name), tonumber(hash) or 0, tostring((...))))
    return nil
end

-- Public-only execution guard. The authenticated runtime still has to
-- install the private entitlement adapter after UID authorization. A visible
-- UI lock alone is never permission to execute a feature.
-- Feature identity is captured before registration can run a callback.
-- Public FeatureKeys remains a UI registry, never a live authorization source.
local __public_feature_keys = setmetatable({}, { __mode = "k" })
local __public_module_names = setmetatable({}, { __mode = "k" })
local function __public_capture_module(record)
    assert(type(record) == "table" and type(record.name) == "string",
        "Public module identity is invalid")
    local name = record.name:gsub("%.lua$", ""):gsub("/", ".")
    assert(name ~= "", "Public module identity is empty")
    assert(__public_module_names[record] == nil or __public_module_names[record] == name,
        "Public module identity cannot be reassigned")
    __public_module_names[record] = name
end
local function __public_capture_feature(record, hash)
    assert(__public_module_names[record] ~= nil, "Public module identity is missing")
    assert(type(hash) == "number" and hash == hash and hash % 1 == 0,
        "Public feature identity requires an integer hash")
    local registry, key = public.FeatureKeys, nil
    assert(type(registry) == "table", "Public feature identity registry is missing")
    -- Read actual entries; a public __pairs metamethod cannot synthesize identity.
    for registered, feature_hash in next, registry do
        if feature_hash == hash then
            assert(type(registered) == "string", "Public feature identity key is invalid")
            local candidate = registered:gsub("^selected_player_", "")
            assert(candidate ~= "", "Public feature identity key is empty")
            assert(key == nil or key == candidate, "Public feature identity is ambiguous")
            key = candidate
        end
    end
    assert(key ~= nil, "Public feature identity must precede registration")
    local owned = __public_feature_keys[record]
    if not owned then owned = {}; __public_feature_keys[record] = owned end
    assert(owned[hash] == nil or owned[hash] == key, "Public feature identity cannot be reassigned")
    owned[hash] = key
end
local function public_action_allowed(record, hash, kind)
    -- Public mode and this admission function are captured privately.
    local key
    if kind == "feature" then
        local owned = __public_feature_keys[record]
        key = owned and owned[hash]
        if not key then return false end
    else
        key = kind or "event"
    end
    local module_name = __public_module_names[record]
    if not module_name then return false end
    local ok, allowed = pcall(__public_allowed, module_name, key)
    return ok and allowed == true
end

local function trace_feature_callback(record, hash, name, feature_type, callback, ...)
    if not public_action_allowed(record, hash, "feature") then
        return false, "Supporter-only feature or CScript authorization unavailable."
    end
    local trace_state = public and public.Runtime and public.Runtime.State
    if not (trace_state and trace_state.test_session and trace_state.test_session.enabled == true) then
        return feature_callback_result(record, hash, name, xpcall(callback, traceback, ...))
    end
    local args = packed(...)
    local trace_api = public and public.Runtime
    local token
    if trace_api and type(trace_api.BeginTestAction) == "function" then
        token = trace_api.BeginTestAction(record.name, name, "feature callback",
            ("hash=0x%08X type=%s"):format(tonumber(hash) or 0, feature_type_label(feature_type)), hash)
    end
    local results
    local ok, err = xpcall(function()
        results = packed(callback(table.unpack(args, 1, args.n)))
    end, traceback)
    if not ok then
        if token and trace_api and type(trace_api.EndTestAction) == "function" then
            trace_api.EndTestAction(token, "FAILED", tostring(err), "lua-exception")
        end
        bootstrap_log("LogError", ("phase=feature-callback module=%s name=%s hash=0x%08X error=%s")
            :format(tostring(record.name), tostring(name), tonumber(hash) or 0, tostring(err)))
        return nil
    end
    local status, detail = "SUCCESS_UNVERIFIED", "callback returned without Lua error"
    local first = results and results[1]
    if type(first) == "table" and first.TestStatus then
        status = tostring(first.TestStatus)
        detail = tostring(first.TestDetail or detail)
    elseif first == false then
        status, detail = "NO_OP", "callback returned false"
    end
    if token and trace_api and type(trace_api.EndTestAction) == "function" then
        trace_api.EndTestAction(token, status, detail, tostring(first))
    end
    return table.unpack(results, 1, results.n)
end

local function register_test_control_spec(spec)
    local trace_api = public and public.Runtime
    if spec.registered == true or not trace_api or type(trace_api.RegisterControlAudit) ~= "function" then
        return spec.registered == true
    end
    local ok, err = trace_api.RegisterControlAudit(spec)
    if ok == true then
        spec.registered = true
        return true
    end
    if ok == false then
        bootstrap_log("LogError", ("phase=control-audit module=%s hash=0x%08X error=%s")
            :format(tostring(spec.module), tonumber(spec.hash) or 0, tostring(err)))
    end
    return false
end

local function flush_test_control_audit()
    local registered = 0
    for _, spec in ipairs(runtime.test_control_specs) do
        if register_test_control_spec(spec) then registered = registered + 1 end
    end
    return registered
end

local function register_test_feature(record, feature, hash, name, feature_type, description, callback, player)
    local spec = {
        hash = hash,
        name = name,
        module = record.name,
        feature_type = feature_type_label(feature_type),
        description = description,
        callback = type(callback) == "function",
        player = player == true,
    }
    runtime.test_control_specs[#runtime.test_control_specs + 1] = spec
    register_test_control_spec(spec)
    if player == true then return end
    runtime.test_feature_records[#runtime.test_feature_records + 1] = {
        feature = feature,
        hash = hash,
        name = tostring(name),
        module = tostring(record.name),
        feature_type = feature_type,
        value = nil,
        initialized_session = -1,
    }
end

local function sampled_feature_value(item)
    local feature, kind = item.feature, item.feature_type
    local method
    if eFeatureType and kind == eFeatureType.Toggle then
        method = "IsToggled"
    elseif eFeatureType and kind == eFeatureType.SliderInt then
        method = "GetIntValue"
    elseif eFeatureType and kind == eFeatureType.SliderFloat then
        method = "GetFloatValue"
    elseif eFeatureType and kind == eFeatureType.List then
        method = "GetListIndex"
    elseif eFeatureType and kind == eFeatureType.InputText then
        method = "GetStringValue"
    else
        return nil, false
    end
    local member_ok, member = pcall(function() return feature[method] end)
    if not member_ok or type(member) ~= "function" then return nil, false end
    local ok, value = pcall(member, feature)
    if not ok then return nil, false end
    if method == "GetStringValue" then return "length=" .. tostring(#tostring(value or "")), true end
    if type(value) == "number" then return ("%.9g"):format(value), true end
    return tostring(value), true
end

sample_test_features = function()
    local trace_api = public and public.Runtime
    if not trace_api or type(trace_api.TestSessionSnapshot) ~= "function" then return end
    local state = trace_api.State
    if state and state.test_session and state.test_session.enabled ~= true then return end
    local ok, snapshot = pcall(trace_api.TestSessionSnapshot)
    if not ok or type(snapshot) ~= "table" or snapshot.enabled ~= true then return end
    local session = tonumber(snapshot.session_id) or 0
    local records = runtime.test_feature_records
    if #records == 0 then return end
    local budget = math.min(24, #records)
    for _ = 1, budget do
        local index = math.max(1, math.min(#records, tonumber(runtime.test_feature_cursor) or 1))
        local item = records[index]
        runtime.test_feature_cursor = (index % #records) + 1
        local value, readable = sampled_feature_value(item)
        if readable then
            if item.initialized_session ~= session then
                item.initialized_session, item.value = session, value
            elseif item.value ~= value then
                local before = item.value
                item.value = value
                if type(trace_api.RecordTestEvent) == "function" then
                    trace_api.RecordTestEvent("SUCCESS_UNVERIFIED", item.module, item.name,
                        "feature value change", "before=" .. tostring(before) .. " after=" .. tostring(value))
                end
            end
        end
    end
end

-- Cherax can invoke feature callbacks while a feature is being constructed,
-- and current Enhanced builds can fail-fast when a new feature userdata is
-- queried or mutated before the registry is complete. Modules retain their
-- historical initialization choreography, but stateful feature methods are
-- queued here and replayed only after every control, handler, and tab exists.
local DEFERRED_FEATURE_METHODS = {
    Toggle = true,
    SetLimitValues = true,
    SetStepSize = true,
    SetIntValue = true,
    SetFloatValue = true,
    SetList = true,
    SetListItems = true,
    SetListIndex = true,
    SetStringValue = true,
}

local FEATURE_READ_DEFAULTS = {
    IsToggled = false,
    GetIntValue = 0,
    GetFloatValue = 0.0,
    GetListIndex = 0,
    GetStringValue = "",
}

local function make_feature_facade(record, feature, hash, name)
    local resolved_feature, resolved_epoch
    local function resolve_feature()
        -- Owned registry objects remain stable between epoch checks; state is
        -- ALWAYS read from the live object. Recheck once per second to observe
        -- an external replacement without a registry call on every IsToggled.
        local epoch = context.FeatureCacheEpoch or 0
        if resolved_epoch == epoch then return resolved_feature end
        resolved_epoch = epoch
        resolved_feature = nil
        if runtime.owned_feature_hashes[hash]
            and RAW_FEATURE_MGR and type(RAW_FEATURE_MGR.GetFeature) == "function" then
            local ok, current = pcall(RAW_FEATURE_MGR.GetFeature, hash)
            local current_type = type(current)
            if ok and (current_type == "table" or current_type == "userdata") then
                resolved_feature = current
                return current
            end
        end
        -- An absent/replaced owned entry must not fall back to stale userdata.
        -- Hosts without a registry getter retain the original registration object.
        if runtime.owned_feature_hashes[hash]
            and not (RAW_FEATURE_MGR and type(RAW_FEATURE_MGR.GetFeature) == "function") then
            resolved_feature = feature
        end
        return resolved_feature
    end

    local facade
    facade = setmetatable({}, {
        __index = function(_, key)
            local method
            if key == "SetDefaultValue" then
                method = function(_, ...)
                    record.feature_defaults[hash] = packed(...)
                    return facade
                end
            elseif DEFERRED_FEATURE_METHODS[key] then
                method = function(_, ...)
                    if not runtime.feature_methods_enabled then
                        record.pending_feature_methods[#record.pending_feature_methods + 1] = {
                            name = tostring(key), hash = hash, args = packed(...),
                        }
                        return facade
                    end
                    local current = resolve_feature()
                    local member = current and current[key]
                    if type(member) ~= "function" then
                        error(("feature method missing for %s.%s (0x%08X)"):format(
                            tostring(name), tostring(key), tonumber(hash) or 0), 2)
                    end
                    return member(current, ...)
                end
            elseif FEATURE_READ_DEFAULTS[key] ~= nil then
                method = function(_, ...)
                    if not runtime.feature_methods_enabled then return FEATURE_READ_DEFAULTS[key] end
                    local current = resolve_feature()
                    local member = current and current[key]
                    if type(member) ~= "function" then return FEATURE_READ_DEFAULTS[key] end
                    return member(current, ...)
                end
            else
                local current = resolve_feature()
                local member_ok, member = pcall(function() return current[key] end)
                if not member_ok then
                    error(("feature member lookup failed for %s.%s (0x%08X): %s"):format(
                        tostring(name), tostring(key), tonumber(hash) or 0, tostring(member)), 2)
                end
                if type(member) ~= "function" then return member end
                method = function(_, ...)
                    local object = resolve_feature()
                    return object[key](object, ...)
                end
            end
            -- Cache the method closure, never its returned feature value.
            rawset(facade, key, method)
            return method
        end,
        __newindex = function(_, key, value)
            resolve_feature()[key] = value
        end,
    })
    return facade
end

-- BEGIN OWNED NATIVE LOOP GROUPS
-- Loader-owned groups; opaque callbacks retain Cherax's real native Yield.
local function new_owned_native_loop_manager(dispatcher, raw_script, options)
    options = options or {}
    local registry = dispatcher.OwnedNativeLoopGroups
    if registry == nil then
        registry = { protocol = "CScript-native-loop-groups-v1", slots = {} }
        dispatcher.OwnedNativeLoopGroups = registry
    end
    assert(type(registry) == "table" and registry.protocol == "CScript-native-loop-groups-v1",
        "incompatible owned native-loop registry")
    local api, groups, order = {}, {}, {}
    local active, closing, failed, hard_unload = false, false, false, false
    local in_flight, pending_stop, error_reported = 0, nil, false
    local pack, unpack_values = table.pack, table.unpack
    local function traceback(value)
        if debug and type(debug.traceback) == "function" then return debug.traceback(tostring(value), 2) end
        return tostring(value)
    end
    local function entry_allowed(slot, group)
        return active and not closing and not failed and slot.owner == api
            and slot.generation == group.generation
            and (not options.is_ready or options.is_ready() == true)
            and (not options.is_failed or options.is_failed() ~= true)
    end
    local function release_slots()
        for _, group in ipairs(order) do
            local slot = group.slot
            if slot and slot.owner == api and not slot.in_flight then slot.owner = nil end
        end
    end
    local function finish_stop()
        if not closing or in_flight ~= 0 then return end
        release_slots()
        local callback = pending_stop
        pending_stop = nil
        if callback and not hard_unload then
            local ok, err = xpcall(callback, traceback)
            if not ok then api.Fail("deferred native-loop stop: " .. tostring(err)) end
        end
    end
    function api.Fail(reason)
        failed, active, closing = true, false, true
        if not error_reported then
            error_reported = true
            if type(options.on_error) == "function" then options.on_error(tostring(reason)) end
        end
        finish_stop()
    end
    function api._Run(slot)
        local group = groups[slot.key]
        if not group or slot.in_flight or not entry_allowed(slot, group) then return end
        slot.in_flight = true
        in_flight = in_flight + 1
        local ok, err = xpcall(function()
            local count = #group.callbacks
            for index = 1, count do
                if not entry_allowed(slot, group) then break end
                local item = group.callbacks[index]
                item.callback(unpack_values(item.args, 1, item.args.n))
            end
        end, traceback)
        in_flight = in_flight - 1
        slot.in_flight = false
        if not ok then api.Fail("native loop " .. slot.key .. ": " .. tostring(err)) end
        finish_stop()
    end
    local function bind_group(group)
        local slot = registry.slots[group.key]
        if slot == nil then
            slot = { key = group.key, generation = 0, registered = false, in_flight = false }
            registry.slots[group.key] = slot
        end
        if slot.in_flight or (slot.owner ~= nil and slot.owner ~= api) then
            return false, "owned native loop is still in use: " .. group.key
        end
        slot.generation = slot.generation + 1
        group.slot, group.generation = slot, slot.generation
        slot.owner = api
        if not slot.registered then
            local ok, handle = pcall(raw_script.RegisterLooped, function()
                local owner = slot.owner
                if owner then return owner._Run(slot) end
            end)
            if not ok or type(handle) ~= "number" or handle ~= handle
                or math.abs(handle) == math.huge or handle % 1 ~= 0 then
                slot.owner = nil
                return false, "owned native-loop registration failed: " .. tostring(handle)
            end
            slot.native_handle, slot.registered = handle, true
        end
        return true
    end
    function api.Register(key, callback, ...)
        assert(not closing and not failed, "owned native-loop registration is closed")
        assert(type(key) == "string" and key ~= "", "owned native-loop group needs a key")
        assert(type(callback) == "function", "Script.RegisterLooped callback must be a function")
        local group = groups[key]
        if not group then
            group = { key = key, callbacks = {} }
            groups[key] = group
            order[#order + 1] = group
        end
        local wrapped = type(options.wrap) == "function" and options.wrap(key, callback) or callback
        local handle = #group.callbacks + 1
        group.callbacks[handle] = { callback = wrapped, args = pack(...) }
        if active and not group.slot then
            local ok, why = bind_group(group)
            if not ok then api.Fail(why); error(why, 2) end
        end
        -- Preserve the collector's logical integer handle. The raw worker's
        -- private handle is not a per-callback registration handle.
        return handle
    end
    function api.Activate()
        if closing or failed then return false, "owned native-loop manager is stopped" end
        if active then return true end
        for _, group in ipairs(order) do
            local ok, why = bind_group(group)
            if not ok then
                failed, closing = true, true
                release_slots()
                return false, why
            end
        end
        active = true
        return true
    end
    function api.IsIdle() return in_flight == 0 end
    function api.BeginHandoff()
        if closing or failed or in_flight ~= 0 then return false end
        -- Close admission before teardown. Never restore underneath an old
        -- callback's suspended continuation or replace its worker owner.
        closing, active = true, false
        return true
    end
    function api.Stop(on_idle, host_unload)
        closing, active = true, false
        if host_unload == true then
            -- ON_UNLOAD ends with host destruction of the Lua state's native
            -- workers; there is no documented native-thread drain here.
            hard_unload, pending_stop = true, nil
        elseif type(on_idle) == "function" and in_flight ~= 0 then
            pending_stop = pending_stop or on_idle
        end
        if in_flight ~= 0 then return false end
        pending_stop = nil
        release_slots()
        return true
    end
    function api.Snapshot()
        local result = { active = active, closing = closing, failed = failed,
            in_flight = in_flight, hard_unload = hard_unload, groups = {} }
        for _, group in ipairs(order) do
            local slot = group.slot
            result.groups[#result.groups + 1] = { key = group.key, callbacks = #group.callbacks,
                registered = slot and slot.registered == true or false,
                generation = group.generation, native_handle = slot and slot.native_handle or nil,
                in_flight = slot and slot.owner == api and slot.in_flight == true or false }
        end
        return result
    end
    return api
end
-- END OWNED NATIVE LOOP GROUPS

local function measured_callback(label, callback, stride)
    local wrapped
    return function(...)
        if wrapped then return wrapped(...) end
        local performance = context.Performance
        if performance and type(performance.Wrap) == "function" then
            wrapped = performance.Wrap(label, callback, stride)
            return wrapped(...)
        end
        return callback(...)
    end
end

local native_loop_owner
native_loop_owner = new_owned_native_loop_manager(loop_dispatcher, RAW_SCRIPT, {
    is_ready = function()
        return runtime.phase == "ready" and runtime.callbacks_enabled
            and not runtime.stopping and not runtime.stopped
    end,
    is_failed = function() return runtime.failed == true end,
    wrap = function(key, callback)
        return measured_callback("scheduler." .. (key:match("^(.-)::") or key), callback, 61)
    end,
    on_error = function(err)
        runtime.failed = true
        runtime.failure = { phase = "native-loop", module = "owned-native-loop", error = tostring(err) }
        update_diagnostics()
        bootstrap_log("LogError", "phase=native-loop module=owned-native-loop error=" .. tostring(err))
        if stop_all then stop_all("native loop failure", true) end
    end,
})

-- Observe host delivery before admission checks. These bounded counters touch
-- no payloads, clocks, natives, or logs inside a network callback.
local function bump_event_observation(info, key)
    local observation = info.observation
    if observation[key] < 1000000000 then observation[key] = observation[key] + 1 end
end

local function module_environment(record)
    __public_capture_module(record)
    local script_proxy = setmetatable({}, { __index = RAW_SCRIPT })
    script_proxy.RegisterLooped = function(callback, ...)
        if type(callback) ~= "function" then error("Script.RegisterLooped callback must be a function", 2) end
        record.tick_callbacks[#record.tick_callbacks + 1] = {
            callback = measured_callback("scheduler." .. record.name, callback, 61), args = { ... },
        }
        return #record.tick_callbacks
    end

    local native_loop_facades = {}
    script_proxy.NativeLoopGroup = function(scope)
        assert(type(scope) == "string" and scope ~= "", "native-loop scope is required")
        local facade = native_loop_facades[scope]
        if not facade then
            facade = setmetatable({ RegisterLooped = function(callback, ...)
                return native_loop_owner.Register(record.name .. "::" .. scope, callback, ...)
            end }, { __index = script_proxy })
            native_loop_facades[scope] = facade
        end
        return facade
    end

    local event_proxy = setmetatable({}, { __index = RAW_EVENT_MGR })
    event_proxy.RegisterHandler = function(event, callback)
        if type(callback) ~= "function" then error("EventMgr.RegisterHandler callback must be a function", 2) end
        if runtime.stopping or runtime.stopped or record.stopped or record.released then
            error("EventMgr.RegisterHandler called during runtime cleanup", 2)
        end
        local fake = runtime.next_fake_handler
        runtime.next_fake_handler = runtime.next_fake_handler - 1
        local label = event == eLuaEvent.ON_PRESENT and "render." .. record.name
            or "event." .. record.name .. "." .. tostring(event)
        local info = { event = event, callback = measured_callback(label, callback, 127), real_id = nil, removed = false,
            observation = { host_entries = 0, disabled_entries = 0, authorization_denied = 0,
                lifecycle_denied = 0, forwarded = 0 } }
        record.fake_handlers[fake] = info
        if event == eLuaEvent.ON_UNLOAD then
            info.unload = true
            record.unload_callbacks[#record.unload_callbacks + 1] = fake
            return fake
        end
        record.pending_handlers[#record.pending_handlers + 1] = fake
        -- Feature/default replay and saved settings run after the initial arm
        -- pass, while phase is still 'activate'. Those registrations, and
        -- later toggle changes, must reach the native event manager now.
        if record.handlers_armed then
            local armed, detail = arm_record_handlers(record)
            if not armed then
                remove_handler(record, fake)
                error("EventMgr.RegisterHandler failed: " .. tostring(detail), 2)
            end
        end
        return fake
    end
    event_proxy.RemoveHandler = function(handler_id)
        return remove_handler(record, handler_id)
    end
    event_proxy.GetHandlerState = function(handler_id)
        local fake = record.fake_handlers[handler_id] and handler_id or record.event_ids[handler_id]
        local info = fake and record.fake_handlers[fake]
        if not info then return nil end
        local registered = info.real_id ~= nil
        local observation = info.observation
        return {
            registered = registered,
            armed = registered and not info.registering and not info.quiesced and not info.removed
                and not record.stopped and not record.released and not runtime.stopping and not runtime.stopped,
            removal_pending = info.removal_pending == true,
            queued = not registered and not info.removed and not info.quiesced,
            host_entries = observation.host_entries,
            disabled_entries = observation.disabled_entries,
            authorization_denied = observation.authorization_denied,
            lifecycle_denied = observation.lifecycle_denied,
            forwarded = observation.forwarded,
            native_id = info.real_id,
            event = info.event,
            callbacks_enabled = runtime.callbacks_enabled == true,
        }
    end

    local feature_proxy = setmetatable({}, { __index = RAW_FEATURE_MGR })
    feature_proxy.AddFeature = function(hash, name, feature_type, description, callback, ...)
        __public_capture_feature(record, hash)
        local copy = public.Core.PresentationCopy
        if copy then description = copy.Description(name, description) end
        if record.feature_lookup[hash] then error("duplicate feature registration: " .. tostring(hash), 2) end
        -- CScript owns collision detection for features registered during this
        -- runtime. Do not probe Cherax with GetFeature(hash) before AddFeature:
        -- the current Enhanced host can fail-fast on an absent or invalid
        -- registry entry instead of returning a Lua error. The historical
        -- JinxRebound namespace remains stable and authored hashes are validated
        -- unique before packaging.
        if runtime.owned_feature_hashes[hash] then
            error(("feature hash already owned by CScript module %s: %s (0x%08X)"):format(
                tostring(runtime.owned_feature_hashes[hash]), tostring(name), tonumber(hash) or 0), 2)
        end
        if type(callback) == "function" then
            callback = measured_callback("feature." .. record.name, callback, 1)
        end
        local guarded = callback
        if type(callback) == "function" then
            guarded = function(...)
                if runtime.stopping then return end
                if not runtime.callbacks_enabled then
                    record.pending_feature_calls[#record.pending_feature_calls + 1] = {
                        callback = callback,
                        args = packed(...),
                        hash = hash,
                    }
                    return
                end
                return trace_feature_callback(record, hash, name, feature_type, callback, ...)
            end
        end
        local callback_options = { ... }
        local native_thread_execution = callback_options[1]
        if native_thread_execution == nil then native_thread_execution = true end
        -- Callback-backed feature mutation can synchronously re-enter Cherax
        -- while its registry is still being finalized. Always force callbacks
        -- through the host queue; preserve the caller's native-thread choice.
        local feature = RAW_FEATURE_MGR.AddFeature(
            hash, name, feature_type, description, guarded, native_thread_execution, true)
        local value_type = type(feature)
        if value_type ~= "table" and value_type ~= "userdata" then
            error(("FeatureMgr.AddFeature returned invalid %s for %s (0x%08X)"):format(
                value_type, tostring(name), tonumber(hash) or 0), 2)
        end
        record.feature_lookup[hash] = true
        record.feature_hashes[#record.feature_hashes + 1] = hash
        runtime.owned_feature_hashes[hash] = record.name
        register_test_feature(record, feature, hash, name, feature_type, description, callback, false)
        return make_feature_facade(record, feature, hash, name)
    end
    feature_proxy.RemoveFeature = function(hash)
        if not record.feature_lookup[hash] or runtime.owned_feature_hashes[hash] ~= record.name then
            return false
        end
        record.feature_lookup[hash] = nil
        runtime.owned_feature_hashes[hash] = nil
        return RAW_FEATURE_MGR.RemoveFeature(hash)
    end
    feature_proxy.AddPlayerFeature = function(hash, name, feature_type, description, callback, ...)
        __public_capture_feature(record, hash)
        local copy = public.Core.PresentationCopy
        if copy then description = copy.Description(name, description) end
        if record.player_feature_lookup[hash] then error("duplicate player feature registration: " .. tostring(hash), 2) end
        if runtime.owned_player_feature_hashes[hash] then
            error(("player feature hash already owned by CScript module %s: %s (0x%08X)"):format(
                tostring(runtime.owned_player_feature_hashes[hash]), tostring(name), tonumber(hash) or 0), 2)
        end
        -- As with ordinary features, avoid object-returning GetFeature probes.
        -- CScript never removes player features that it did not record as owned.
        if type(callback) == "function" then
            callback = measured_callback("feature." .. record.name, callback, 1)
        end
        local guarded = callback
        if type(callback) == "function" then
            guarded = function(...)
                if runtime.stopping then return end
                if not runtime.callbacks_enabled then
                    record.pending_feature_calls[#record.pending_feature_calls + 1] = {
                        callback = callback,
                        args = packed(...),
                        hash = hash,
                    }
                    return
                end
                return trace_feature_callback(record, hash, name, feature_type, callback, ...)
            end
        end
        local features = RAW_FEATURE_MGR.AddPlayerFeature(
            hash, name, feature_type, description, guarded, ...)
        local value_type = type(features)
        -- Cherax exposes its 32-hash collection as userdata. Mocks and
        -- some older builds expose an ordinary Lua table; both are valid.
        if value_type ~= "table" and value_type ~= "userdata" then
            error(("FeatureMgr.AddPlayerFeature returned invalid %s for %s (0x%08X)"):format(
                value_type, tostring(name), tonumber(hash) or 0), 2)
        end
        record.player_feature_lookup[hash] = true
        record.player_feature_hashes[#record.player_feature_hashes + 1] = hash
        runtime.owned_player_feature_hashes[hash] = record.name
        register_test_feature(record, features, hash, name, feature_type, description, callback, true)
        return features
    end
    feature_proxy.RemovePlayerFeature = function(hash)
        if not record.player_feature_lookup[hash] or runtime.owned_player_feature_hashes[hash] ~= record.name then
            return false
        end
        record.player_feature_lookup[hash] = nil
        runtime.owned_player_feature_hashes[hash] = nil
        return RAW_FEATURE_MGR.RemovePlayerFeature(hash)
    end

    local click_gui_proxy = setmetatable({}, { __index = RAW_CLICK_GUI })
    local function publish_late_tab(item, add_method)
        if not runtime.callbacks_enabled then return end
        if runtime.stopping then error("CScript is stopping", 2) end
        local guarded = function(...)
            if not runtime.callbacks_enabled or runtime.stopping or item.removed then return end
            if not public_action_allowed(record, nil, "event") then return end
            if not runtime.callbacks_enabled or runtime.stopping or item.removed then return end
            return item.callback(...)
        end
        local ok, result = pcall(add_method, item.name, guarded)
        if not ok or result == false then
            item.removed = true
            error("late tab publication failed: " .. tostring(result), 2)
        end
        item.active = true
    end
    click_gui_proxy.AddTab = function(name, callback)
        if type(callback) ~= "function" then error("ClickGUI.AddTab callback must be a function", 2) end
        local item = {
            name = name,
            callback = measured_callback("ui." .. record.name, callback, 61),
            active = false,
            removed = false
        }
        record.tabs[#record.tabs + 1] = item
        publish_late_tab(item, RAW_CLICK_GUI.AddTab)
    end
    click_gui_proxy.AddPlayerTab = function(name, callback)
        if type(callback) ~= "function" then error("ClickGUI.AddPlayerTab callback must be a function", 2) end
        local item = {
            name = name, callback = measured_callback("ui.player." .. record.name, callback, 61), active = false, removed = false,
        }
        record.player_tabs[#record.player_tabs + 1] = item
        publish_late_tab(item, RAW_CLICK_GUI.AddPlayerTab)
    end
    local function remove_deferred_tab(items, name, remover)
        for index = #items, 1, -1 do
            local item = items[index]
            if not item.removed and item.name == name then
                if item.active and type(remover) == "function" then pcall(remover, name) end
                item.active = false
                item.removed = true
                return true
            end
        end
        return false
    end
    click_gui_proxy.RemoveTab = function(name)
        return remove_deferred_tab(record.tabs, name, RAW_CLICK_GUI.RemoveTab)
    end
    click_gui_proxy.RemovePlayerTab = function(name)
        return remove_deferred_tab(record.player_tabs, name, RAW_CLICK_GUI.RemovePlayerTab)
    end

    local environment = {}
    rawset(environment, "_G", environment)
    rawset(environment, "CScript", __public_cscript)
    rawset(environment, "Script", script_proxy)
    rawset(environment, "EventMgr", event_proxy)
    rawset(environment, "FeatureMgr", feature_proxy)
    rawset(environment, "ClickGUI", click_gui_proxy)
    if RAW_LOGGER then
        local logger_proxy = {}
        logger_proxy.LogInfo = function(message)
            local text = tostring(message)
            if text:find("[CScript] v", 1, true)
                and text:find("loaded successfully. Registered", 1, true) then
                runtime.compat_controls = tonumber(text:match("Registered (%d+) controls"))
                    or EXPECTED_LOGICAL_CONTROLS
                update_diagnostics()
                return
            end
            if type(RAW_LOGGER.LogInfo) == "function" then return RAW_LOGGER.LogInfo(message) end
        end
        if type(RAW_LOGGER.LogWarn) == "function" then logger_proxy.LogWarn = RAW_LOGGER.LogWarn end
        if type(RAW_LOGGER.LogError) == "function" then logger_proxy.LogError = RAW_LOGGER.LogError end
        if type(RAW_LOGGER.Log) == "function" then logger_proxy.Log = RAW_LOGGER.Log end
        rawset(environment, "Logger", logger_proxy)
    end
    if RAW_GUI then
        local gui_proxy = setmetatable({}, { __index = RAW_GUI })
        gui_proxy.AddToast = function(title, message, duration, position)
            if tostring(message):find("Loaded successfully", 1, true) then return true end
            local copy = public.Core.PresentationCopy
            if copy then message = copy.Message(message) end
            return RAW_GUI.AddToast("CScript", message, duration, position)
        end
        rawset(environment, "GUI", gui_proxy)
    end
    setmetatable(environment, {
        __index = _G,
        __newindex = function(_, key)
            error(("module %s attempted undeclared global write: %s"):format(record.name, tostring(key)), 2)
        end,
    })
    return environment
end

local function compile_module(relative_path, environment)
    local source = BUNDLED_SOURCES[relative_path]
    if source then
        if type(load) ~= "function" then return nil, "Lua load() is unavailable for bundled source" end
        return load(source, "@CScript/" .. relative_path, "t", environment)
    end
    if type(loadfile) ~= "function" then
        return nil, "loadfile() is unavailable; use the deterministic dist/loader.lua bundle"
    end
    return loadfile(direct_path(relative_path), "t", environment)
end

arm_record_handlers = function(record)
    if not (RAW_EVENT_MGR and type(RAW_EVENT_MGR.RegisterHandler) == "function") then
        return false, "EventMgr.RegisterHandler is unavailable"
    end
    for _, fake in ipairs(record.pending_handlers) do
        local info = record.fake_handlers[fake]
        if info and not info.removed and not info.real_id
            and not info.registering and not info.quiesced and not info.removal_pending then
            local allow_when_inactive = info.event == eLuaEvent.SHOULD_COLLIDE
                or info.event == eLuaEvent.CAN_APPLY_NODE_DATA
            info.generation = (info.generation or 0) + 1
            local generation = info.generation
            local callback = function(...)
                -- This second guard runs after the public authorization hook.
                -- A callback retained by a failed removal cannot revive later.
                if record.fake_handlers[fake] ~= info or info.generation ~= generation
                    or info.real_id == nil or info.registering or info.removed or info.quiesced
                    or record.stopped or record.released or runtime.stopping or runtime.stopped
                    or not runtime.callbacks_enabled then
                    bump_event_observation(info, "lifecycle_denied")
                    return inactive_event_result(info.event)
                end
                bump_event_observation(info, "forwarded")
                return info.callback(...)
            end
            local guarded = function(...)
                bump_event_observation(info, "host_entries")
                if not runtime.callbacks_enabled then
                    bump_event_observation(info, "disabled_entries")
                    if allow_when_inactive then return true end
                    if info.event == eLuaEvent.SCRIPTED_GAME_EVENT then return false end
                    return
                end
                if not public_action_allowed(record, nil, "event") then
                    local observation = info.observation
                    if observation and observation.authorization_denied < 1000000000 then
                        observation.authorization_denied = observation.authorization_denied + 1
                    end
                    if info.event == eLuaEvent.CAN_APPLY_NODE_DATA
                        or info.event == eLuaEvent.SHOULD_COLLIDE then return true end
                    if info.event == eLuaEvent.SCRIPTED_GAME_EVENT then return false end
                    return
                end
                return callback(...)
            end
            info.registering = true
            local ok, handler_id = pcall(RAW_EVENT_MGR.RegisterHandler, info.event, guarded)
            info.registering = false
            if not ok then return false, handler_id end
            if type(handler_id) ~= "number" or handler_id ~= handler_id
                or handler_id == math.huge or handler_id == -math.huge
                or handler_id ~= math.floor(handler_id) then
                info.quiesced = true
                return false, "Native event registration did not return an integer handler ID"
            end
            info.real_id = handler_id
            record.event_ids[handler_id] = fake
            if record.fake_handlers[fake] ~= info or info.removed or info.quiesced
                or info.removal_pending or record.stopped or record.released
                or runtime.stopping or runtime.stopped then
                -- Keep any returned native ID owned until removal succeeds.
                record.fake_handlers[fake] = info
                detach_handler(record, fake, info)
                return false, "Runtime stopped while registering an event handler"
            end
        end
    end
    record.pending_handlers = {}
    record.handlers_armed = true
    return true
end

local function arm_record_tabs(record)
    local function arm(items, add_method, label)
        if #items > 0 and type(add_method) ~= "function" then
            return false, label .. " is unavailable"
        end
        for _, item in ipairs(items) do
            if not item.removed and not item.active then
                local guarded = function(...)
                    if not runtime.callbacks_enabled or runtime.stopping or item.removed then return end
                    if not public_action_allowed(record, nil, "event") then return end
                    if not runtime.callbacks_enabled or runtime.stopping or item.removed then return end
                    return item.callback(...)
                end
                local ok, err = pcall(add_method, item.name, guarded)
                if not ok then return false, err end
                item.active = true
            end
        end
        return true
    end
    local ok, err = arm(record.tabs, RAW_CLICK_GUI.AddTab, "ClickGUI.AddTab")
    if not ok then return false, err end
    return arm(record.player_tabs, RAW_CLICK_GUI.AddPlayerTab, "ClickGUI.AddPlayerTab")
end

local function replay_feature_callbacks(record)
    local queue = record.pending_feature_calls
    record.pending_feature_calls = {}
    local index = 1
    while index <= #queue do
        if index > 4096 then return false, "startup feature callback queue exceeded 4096 entries" end
        local item = queue[index]
        if public_action_allowed(record, item.hash, "feature") then
            local ok, err = xpcall(function()
                return item.callback(table.unpack(item.args, 1, item.args.n))
            end, traceback)
            if not ok then return false, err end
        end
        index = index + 1
    end
    return true
end

local function replay_feature_methods(record)
    local queue = record.pending_feature_methods
    record.pending_feature_methods = {}
    local index = 1
    while index <= #queue do
        if index > 4096 then return false, "startup feature method queue exceeded 4096 entries" end
        local item = queue[index]
        bootstrap_log("LogInfo", ("Feature state replay module=%s call=%d/%d method=%s hash=0x%08X")
            :format(tostring(record.name), index, #queue, tostring(item.name), tonumber(item.hash) or 0))
        local ok, err = xpcall(function()
            if not (RAW_FEATURE_MGR and type(RAW_FEATURE_MGR.GetFeature) == "function") then
                error("FeatureMgr.GetFeature unavailable for registered feature replay")
            end
            local current = RAW_FEATURE_MGR.GetFeature(item.hash)
            local current_type = type(current)
            if current_type ~= "table" and current_type ~= "userdata" then
                error("registered feature could not be re-resolved")
            end
            local method = current[item.name]
            if type(method) ~= "function" then error("registered feature method is unavailable") end
            return method(current, table.unpack(item.args, 1, item.args.n))
        end, traceback)
        if not ok then
            return false, ("deferred feature method %s failed for 0x%08X: %s"):format(
                tostring(item.name), tonumber(item.hash) or 0, tostring(err))
        end
        index = index + 1
    end
    return true, #queue
end

local function quiesce_record(record)
    local pending = {}
    for fake, info in pairs(record.fake_handlers) do
        if not info.unload then pending[#pending + 1] = { fake = fake, info = info } end
    end
    for _, item in ipairs(pending) do
        if record.fake_handlers[item.fake] == item.info then
            -- Keep the virtual record for its module's subsequent Stop/Restore.
            detach_handler(record, item.fake, item.info)
        end
    end
    local function remove_tabs(items, remover)
        for index = #items, 1, -1 do
            local item = items[index]
            if item.active and type(remover) == "function" then pcall(remover, item.name) end
            item.active = false
        end
    end
    remove_tabs(record.player_tabs, RAW_CLICK_GUI.RemovePlayerTab)
    remove_tabs(record.tabs, RAW_CLICK_GUI.RemoveTab)
end

local function release_record(record)
    if record.released then return true end
    for _, info in pairs(record.fake_handlers) do
        if info.real_id ~= nil or info.registering or info.removal_pending then return false end
    end
    record.released = true
    if RAW_FEATURE_MGR then
        -- Startup rollback only releases features that this loader registered.
        -- Do not call Toggle(false) on arbitrary feature objects. The host rejects
        -- boolean parameters for Button/Slider features and can
        -- fail-fast before RemoveFeature is reached. Module Stop/Restore has
        -- already restored runtime state, so direct removal is the safe path.
        if type(RAW_FEATURE_MGR.RemovePlayerFeature) == "function" then
            for index = #record.player_feature_hashes, 1, -1 do
                local hash = record.player_feature_hashes[index]
                if record.player_feature_lookup[hash] and runtime.owned_player_feature_hashes[hash] == record.name then
                    pcall(RAW_FEATURE_MGR.RemovePlayerFeature, hash)
                end
                record.player_feature_lookup[hash] = nil
                if runtime.owned_player_feature_hashes[hash] == record.name then runtime.owned_player_feature_hashes[hash] = nil end
            end
        end
        if type(RAW_FEATURE_MGR.RemoveFeature) == "function" then
            for index = #record.feature_hashes, 1, -1 do
                local hash = record.feature_hashes[index]
                if record.feature_lookup[hash] and runtime.owned_feature_hashes[hash] == record.name then
                    pcall(RAW_FEATURE_MGR.RemoveFeature, hash)
                end
                record.feature_lookup[hash] = nil
                if runtime.owned_feature_hashes[hash] == record.name then runtime.owned_feature_hashes[hash] = nil end
            end
        end
    end
    record.pending_feature_methods = {}
    record.pending_feature_calls = {}
    record.feature_defaults = {}
    record.pending_handlers = {}
    record.fake_handlers = {}
    return true
end

local function stop_record(record, reason)
    if record.stopped then return end
    record.stopped = true
    lifecycle_log(record.name, "STOP", "begin", "reason=" .. tostring(reason))
    local module = record.module
    if record.initialized then
        runtime.cleanup_trace[#runtime.cleanup_trace + 1] = "stop:" .. record.name
    end
    if record.initialized and module and type(module.Stop) == "function" then
        local ok, err = xpcall(function() module.Stop(context, reason) end, traceback)
        if not ok then
            bootstrap_log("LogError", ("phase=stop module=%s error=%s"):format(record.name, tostring(err)))
        end
    end
    for index = #record.unload_callbacks, 1, -1 do
        local fake = record.unload_callbacks[index]
        local info = record.fake_handlers[fake]
        if info and not info.removed then
            info.removed = true
            record.fake_handlers[fake] = nil
            local ok, err = xpcall(info.callback, traceback)
            if not ok then
                bootstrap_log("LogError", ("phase=compat-unload module=%s error=%s"):format(record.name, tostring(err)))
            end
        end
    end
    lifecycle_log(record.name, "STOP", "ok")
end

local function restore_record(record, reason)
    if record.restored then return end
    lifecycle_log(record.name, "RESTORE", "begin", "reason=" .. tostring(reason))
    local module = record.module
    if record.initialized then
        runtime.cleanup_trace[#runtime.cleanup_trace + 1] = "restore:" .. record.name
    end
    if record.initialized and module and type(module.Restore) == "function" then
        local ok, result, detail = xpcall(function() return module.Restore(context, reason) end, traceback)
        if not ok or result==false then
            local err=detail or result
            bootstrap_log("LogError", ("phase=restore module=%s error=%s"):format(record.name, tostring(err)))
            lifecycle_log(record.name, "RESTORE", "failed", tostring(err))
            return false
        end
    end
    record.restored = true
    lifecycle_log(record.name, "RESTORE", "ok")
    return true
end

local function pre_stop_record(record, reason)
    if record.pre_stopped then return end
    record.pre_stopped = true
    local module = record.module
    if record.initialized and module and type(module.PreStop) == "function" then
        lifecycle_log(record.name, "PRE_STOP", "begin", "reason=" .. tostring(reason))
        local ok, err = xpcall(function() module.PreStop(context, reason) end, traceback)
        if not ok then
            bootstrap_log("LogError", ("phase=pre-stop module=%s error=%s"):format(record.name, tostring(err)))
            lifecycle_log(record.name, "PRE_STOP", "failed", tostring(err))
            return
        end
        lifecycle_log(record.name, "PRE_STOP", "ok")
    end
end

stop_all = function(reason, failed)
    runtime.stopping = true
    if __public_close_state.active then
        __public_close_state.failed = __public_close_state.failed or failed == true
        __public_close_state.unload = __public_close_state.unload or reason == "Cherax unload"
        return
    end
    __public_revoke()
    failed = failed == true or __public_close_state.failed
    if __public_close_state.unload then reason = "Cherax unload" end
    if runtime.stopped then
        if reason == "Cherax unload" and rawget(_G, "CScript") == public then rawset(_G, "CScript", nil) end
        return true
    end
    lifecycle_log("loader", "UNLOAD", "begin", "reason=" .. tostring(reason))
    runtime.stopping = true
    runtime.feature_methods_enabled = false
    runtime.callbacks_enabled = false
    runtime.tick = NOOP
    if loop_dispatcher and loop_dispatcher.Callback == dispatch_runtime_tick then
        loop_dispatcher.Callback = NOOP
    end
    runtime.base_tick = NOOP
    runtime.framework_tick = nil
    runtime.failed = failed == true or runtime.failed
    update_diagnostics()
    -- Never restore module state while a dedicated imported worker remains
    -- suspended mid-yield. Cherax owns destruction on host unload.
    local native_idle = native_loop_owner.Stop(function() stop_all(reason, failed) end,
        reason == "Cherax unload")
    if not native_idle and reason ~= "Cherax unload" then return false end
    -- Disable entry points before any module state or owned memory is restored.
    for index = #runtime.loaded, 1, -1 do quiesce_record(runtime.loaded[index]) end
    -- Durability hooks run before ordinary module teardown. Economy uses this
    -- to flush through its cached absolute paths and captured FileMgr methods.
    for index = #runtime.loaded, 1, -1 do pre_stop_record(runtime.loaded[index], reason) end
    for index = #runtime.loaded, 1, -1 do stop_record(runtime.loaded[index], reason) end
    if context.Cleanup and type(context.Cleanup.RunAll) == "function" then
        local ok, err = xpcall(function() context.Cleanup.RunAll(reason) end, traceback)
        if not ok then bootstrap_log("LogError", "phase=cleanup module=core/cleanup.lua error=" .. tostring(err)) end
    end
    local restoration_pending = false
    for index = #runtime.loaded, 1, -1 do
        if restore_record(runtime.loaded[index], reason) == false then
            runtime.failed = true
            restoration_pending = true
        end
    end
    local handlers_pending = false
    for _, record in ipairs(runtime.loaded) do
        for _, info in pairs(record.fake_handlers) do
            if info.real_id ~= nil or info.registering or info.removal_pending then handlers_pending = true end
        end
    end
    update_diagnostics()
    if reason ~= "Cherax unload" and (restoration_pending or handlers_pending) then
        lifecycle_log("loader", "UNLOAD", "pending", "owned cleanup remains retryable")
        return false
    end
    -- During a host-initiated unload Cherax owns destruction of this Lua
    -- state's features. Calling RemoveFeature/RemovePlayerFeature from inside
    -- ON_UNLOAD re-enters that teardown and the host can fail-fast after all
    -- module restores have completed. Explicit release remains necessary for
    -- startup rollback, where the Lua state itself is still alive.
    if reason ~= "Cherax unload" then
        for index = #runtime.loaded, 1, -1 do release_record(runtime.loaded[index]) end
    end
    runtime.stopped = true
    if failed == true and RAW_EVENT_MGR and type(RAW_EVENT_MGR.RemoveHandler) == "function" then
        pcall(RAW_EVENT_MGR.RemoveHandler, unload_handler)
    end
    if (reason == "Cherax unload" or failed == true) and rawget(_G, "CScript") == public then
        rawset(_G, "CScript", nil)
    end
    lifecycle_log("loader", "UNLOAD", "complete", "failed=" .. tostring(runtime.failed))
    return true
end

-- An early host dispatch can reject admission before stop_all is assigned.
if __public_pending_stop then
    stop_all(__public_pending_stop, true)
    return
end
