                and loop_dispatcher.Protocol == "CScript-loop-dispatcher-v1"
                and loop_dispatcher.Registered == true
        end
        local chaos=context.Modules and context.Modules.VehicleChaos
        if chaos then
            local ok,clean=pcall(function()return chaos.CanHandoff()end)
            if not ok or clean~=true then
                bootstrap_log("LogError", "Loader replacement deferred: vehicle cleanup is unresolved. Stop the effect and allow cleanup before retrying.")
                return false
            end
        end
        local player=context.Modules and context.Modules.Player
        if player then
            local ok,clean=pcall(function()return player.CanHandoff()end)
            if not ok or clean~=true then
