-- Explicitly armed business operations. No account writes from rendering.
-- Source: Enhanced freemode and tuneables_processing.c (TU 1.73).
local Module={Name="modules.business_automation",MigrationPhase="17.75"}
local SUPPLY={bunker=true,acid_lab=true,mc_cocaine=true,mc_meth=true,mc_cash=true,mc_weed=true,mc_documents=true}
local PRODUCTION={nightclub=true,special_cargo=true,hangar=true}
-- freemode 1191100..1191107 normalizes manufacturing supply state with 100
-- and 200 thresholds. 100 is the refill target, not an absolute read limit.
-- Keep a conservative 0..200 controller envelope; never clamp or write stock.
local SUPPLY_READ_MAX=200
local function integer(v,lo,hi) return type(v)=="number" and v==v and v%1==0 and v>=lo and v<=hi end
local function clone(t)local o={};for k,v in pairs(t or {})do o[k]=v end;return o end
local function new_single(host,emit)
    local modes,queue,lease={}, {},nil
    local last=-1000
    local results={}
    local function supply_mode(mode)return mode=="supplies" or mode=="fast_supplies" or mode=="supply_once" end
    local api={}
