            local row=lease.rows[i]
            local good,current=pcall(host.ReadCell,row)
            if not good or not integer(current,-2147483648,2147483647) then
                retained[#retained+1]=row
            elseif current==row.after then
                local wrote,result=pcall(host.WriteCell,row,row.value)
                local checked,value=pcall(host.ReadCell,row)
                if not wrote or result==false or not checked or value~=row.value then retained[#retained+1]=row end
            end -- Already original or externally changed: never overwrite either.
        end
        local timer_ok=true
        if lease.timer and lease.timer_applied and not lease.timer_restored then
            local called,result=pcall(host.RestoreProductionTimer,lease.timer)
            timer_ok=called and result==true
            if timer_ok then lease.timer_restored=true end
        end
        if #retained==0 and timer_ok then lease=nil;return true end
        lease.rows=retained;lease.active=false;return false
    end
    function api.Request(mode,business,enabled)
        if not supply_mode(mode) and mode~="production" then return false,"Unknown business operation." end
        if not SUPPLY[business] and not (mode=="production" and PRODUCTION[business]) then return false,"Operation not implemented for this business." end
        if type(enabled)~="boolean" then return false,"Choose On or Off." end
        local id=(supply_mode(mode) and "supplies" or mode)..":"..business
        if not enabled then
            queue[id]=nil
            if supply_mode(mode) then
                if modes[business] and modes[business].pending then modes[business].disabled=true
                else modes[business]=nil end
            elseif lease and lease.scope.business==business then lease.active=false end
            return true
        end
        if mode=="production" and lease then
            if not lease.active or lease.scope.business~=business then return false,"Production restoration is still pending." end
            local checked,valid=pcall(host.Valid,lease.scope)
            if not checked or valid~=true then return false,"The existing production scope changed." end
            for _,row in ipairs(lease.rows)do
                local read,value=pcall(host.ReadCell,row)
