        if not ok or type(scope)~="table" then return false,tostring(ok and why or scope or "Business context unavailable.")end
        if scope.account==nil or (scope.slot~=0 and scope.slot~=1) or scope.generation==nil then return false,"Unverified character."end
        if mode=="supply_once" and queue[id] and queue[id].mode~="supply_once" then
            queue[id].force_request=true
        else
