    end
    local function apply_production(item)
        if lease then return false,"Another production override is active or awaiting cleanup." end
        local rows,why=host.ResolveProduction(item.scope)
        if type(rows)~="table" or #rows<1 then return false,why or "Production tunables unavailable."end
        for _,row in ipairs(rows)do
            if not integer(row.value,-2147483648,2147483647) or not integer(row.after,-2147483648,2147483647) or row.pointer==nil then return false,"Invalid production tunable."end
            if host.ReadCell(row)~=row.value then return false,"Production settings changed before applying."end
        end
