        for _,row in ipairs(rows)do
            if not host.Valid(item.scope)then restore();return false,"Character changed."end
            if host.ReadCell(row)~=row.value then restore();return false,"Production settings changed."end
            -- Capture before invoking, including a failed write that partially applied.
            lease.rows[#lease.rows+1]=row
            if host.WriteCell(row,row.after)==false or host.ReadCell(row)~=row.after then restore();return false,"Production override was rejected."end
        end
