        -- Retain the timer restoration obligation before entering that host.
        lease.timer_applied=true
        local timer_applied,timer_apply_err=host.ApplyProductionTimer(timer)
        if timer_applied~=true then restore();return false,timer_apply_err or "Production timer bootstrap was rejected." end
        lease.active=true
        if (item.business=="special_cargo" or item.business=="hangar") and type(host.ExpediteSource)=="function" then
            local ok,detail=host.ExpediteSource(item.scope)
            lease.source_next=last+5000
            results[item.business]=tostring(detail or (ok and "Staff sourcing accelerated." or "Existing sourcing order could not be accelerated."))
            notice(results[item.business])
        end
        return true
    end
    local function tick(now)
        if lease and not lease.active then restore()end
        local requests=queue;queue={}
        for _,item in pairs(requests)do
            if host.Valid(item.scope)then
                if supply_mode(item.mode) then
                    local previous=modes[item.business]
                    if previous and host.Valid(previous.scope) then
                        -- A one-shot accelerates an existing mode; it must not
                        -- silently disable Auto/Quick Supplies after delivery.
                        if item.mode=="supply_once" then
                            if not previous.pending then previous.force_request=true end
                        else
                            previous.quick=item.mode=="fast_supplies";previous.once=false
                            previous.force_request=item.force_request==true
                            previous.disabled=false
