                            once=item.mode=="supply_once",force_request=item.force_request==true}
                    end
                else
                    local ok,why=apply_production(item)
                    if not ok then notice(why)end
                end
            else notice("Business request cancelled: character or session changed.")end
        end
        if lease and lease.active then
            local valid,invalid_reason=host.Valid(lease.scope)
            for _,row in ipairs(lease.rows)do
                if host.ReadCell(row)~=row.after then valid=false;invalid_reason="Production tunable changed (hash "..tostring(row.hash)..")." end
            end
            -- Normal production advances the timer start/init pair. Cleanup restores
            -- only unchanged override cells; tunable identity remains guarded.
            if not valid then lease.active=false;restore();notice("Fast Production stopped: "..tostring(invalid_reason or "context or tunable settings changed."))end
        end
        if lease and lease.active and lease.source_next and now>=lease.source_next then
            local key=lease.scope.business
            local ok,detail=host.ExpediteSource(lease.scope)
            lease.source_next=now+5000
            local message=tostring(detail or (ok and "Paid staff orders checked." or "Staff sourcing stopped."))
            if not ok then lease.active=false;restore();notice(message) end
            results[key]=message
        end
        for key,mode in pairs(modes)do
            local valid,invalid_reason=host.Valid(mode.scope)
            if not valid then modes[key]=nil;notice("Auto Supplies stopped: "..tostring(invalid_reason or "context changed."))
            else
                local read,state,why=pcall(host.Read,mode.scope)
                if not read then state=nil;why="Supply inventory read failed." end
                if not state or not integer(state.supplies,0,1000)then
                    if mode.pending and now<mode.pending.deadline then
                        -- Unreadable inventory is not a delivery acknowledgment.
                        -- Disarm requests but keep the same-scope in-flight fence.
                        if not mode.disabled then notice(why or "Auto Supplies stopped: supply state unreadable.") end
                        mode.disabled=true
