                    else
                        modes[key]=nil;notice(why or "Auto Supplies stopped: supply state unreadable.")
                    end
                elseif mode.pending then
                    if state.supplies>mode.pending.before and (not host.TransactionsIdle or host.TransactionsIdle()==true) then
                        results[key]="Supplies increased after the request."
                        mode.pending=nil;mode.next_ms=now+(mode.quick and 1000 or 5000)
                        if host.SupplySettled then host.SupplySettled(now) end
                        if mode.once or mode.disabled then modes[key]=nil end
                    elseif now>=mode.pending.deadline then
                        modes[key]=nil;results[key]="Supplies did not increase within two minutes; requests stopped.";notice(results[key])
                    end
                elseif mode.once and state.supplies>=100 then
                    modes[key]=nil;results[key]="Supplies are already full."
                elseif now>=mode.next_ms and state.supplies<=((mode.once or mode.force_request) and 99 or mode.quick and 99 or 20)
                    and (mode.once or mode.force_request or not state.capacity or state.stock<state.capacity)then
