    end
    function api.ReadBusiness(business)
        local ok,scope,why=pcall(host.Scope,business)
        if not ok or not scope then return nil,tostring(ok and why or scope) end
        local row={owned=true,property=scope.property,factory=scope.factory,slot=scope.slot}
