        return true
    end
    function api.Request(mode,key,enabled)
        if farms[key] and farms[key].running then
            if enabled then return false,"Stop Stock Farm before changing its production or supply controls." end
            stop_farm(key,"STOPPED","Stopped by manual control.")
        end
        return engine(key).Request(mode,key,enabled)
    end
    function api.ReadBusiness(key)return engine(key).ReadBusiness(key) end
    function api.StartStockFarm(key,keep_full)
        if not supported(key) then return false,"Stock Farm requires a verified production controller; paid staff orders remain separate." end
        if type(keep_full)~="boolean" then return false,"Choose whether to keep stock full." end
        if type(host.StockFarmBlocked)=="function" then
            local ok,blocked,why=pcall(host.StockFarmBlocked,key)
            if not ok or blocked then return false,tostring(ok and why or blocked) end
        end
        local previous=farms[key];if previous and previous.running then return false,"Stock Farm is already running." end
        local e=engine(key);local s=e.Snapshot(key)
        if s.cleanup_pending or s.production_queued or s.supply_queued then return false,"Wait for the queued operation or restoration to finish first." end
