        local farm={running=true,phase="STARTING",reason=nil,stock=state.stock,target=state.capacity,
            cycles=0,keep_full=keep_full,scope=scope,progress_ms=clock,since=clock}
        farms[key]=farm
        if state.stock==state.capacity then
            e.Request("production",key,false)
            if SUPPLY[key] then e.Request("fast_supplies",key,false) end
            farm.phase="FULL";farm.running=keep_full;return true
        end
        local ok,err=arm(key,farm);if not ok then stop_farm(key,"FAILED",err);return false,err end
        return true
    end
    function api.StopStockFarm(key)
        if not farms[key] then return false,"Stock Farm has not been started." end
        stop_farm(key,"STOPPED","Stopped by user.");return true
    end
    function api.StartAllStockFarms(keep_full)
        local report={started={},skipped={}}
        for _,key in ipairs(keys) do
            local ok,why=api.StartStockFarm(key,keep_full)
            if ok then report.started[#report.started+1]=key else report.skipped[key]=why end
        end
        return #report.started>0,report
    end
    function api.StopAllStockFarms()
        for key,farm in pairs(farms) do if farm.running then stop_farm(key,"STOPPED","Stopped by user.") end end
        return true
    end
    function api.StopStaffOrders(key)
        if key~="hangar" and key~="special_cargo" then return false,"Choose a staff-order business." end
        local e=engines[key]
        if not e then return true end
        local clean=e.Release()
        if clean then release_reservations(key) end
        return clean,clean and nil or "Staff-order settings are still restoring."
    end
    function api.Tick(now)
        if not integer(now,0,9007199254740991) or now<clock then return end
        clock=now
        for key,e in pairs(engines) do
            e.Tick(now)
            local s=e.Snapshot(key)
            if not s.fast_production and not s.cleanup_pending then release_reservations(key) end
        end
        for key,farm in pairs(farms) do
            if farm.running then
                local ok,why=pcall(function()
                    local valid,invalid_reason=host.Valid(farm.scope)
                    if not valid then return stop_farm(key,"FAILED",invalid_reason or "Character, session or ownership changed.") end
                    local state,err=inventory(key)
                    if not state then return stop_farm(key,"FAILED",err) end
                    if state.stock>farm.stock then farm.progress_ms=now end
                    farm.stock=state.stock;farm.target=state.capacity
                    local s=engine(key).Snapshot(key)
                    if state.stock==state.capacity then
                        if farm.phase~="FULL" then
                            engine(key).Request("production",key,false)
                            if SUPPLY[key] then engine(key).Request("fast_supplies",key,false) end
                            farm.phase="FULL";farm.cycles=farm.cycles+1
                            farm.running=farm.keep_full
                        end
                    elseif farm.phase=="FULL" then
                        if not s.cleanup_pending and not s.fast_production then
                            local armed,detail=arm(key,farm);if not armed then stop_farm(key,"FAILED",detail) end
                        end
                    elseif farm.phase=="STARTING" and s.fast_production then farm.phase="PRODUCING"
                    elseif farm.phase=="STARTING" and now-farm.since>=3000 then
                        stop_farm(key,"FAILED","Production override did not start; check the business notification.")
                    elseif farm.phase=="PRODUCING" then
                        if not s.fast_production or SUPPLY[key] and not s.auto_supplies then
                            return stop_farm(key,"FAILED","Production or supplies stopped; Stock Farm stopped with it.")
                        end
                        if now-farm.progress_ms>=180000 then
                            stop_farm(key,"FAILED",key=="nightclub" and "No stock increase for three minutes. Check technicians and linked businesses."
                                or "No stock increase for three minutes. Check business setup and supplies.")
                        end
                    end
                end)
                if not ok then stop_farm(key,"FAILED",tostring(why)) end
            end
        end
    end
    function api.Snapshot(key)
        local s=engine(key).Snapshot(key);local farm=farms[key]
        s.stock_farm_supported=supported(key)==true
        s.stock_farm=farm and {running=farm.running,phase=farm.phase,reason=farm.reason,stock=farm.stock,
            target=farm.target,cycles=farm.cycles,keep_full=farm.keep_full}
            or {running=false,phase="IDLE",cycles=0}
        return s
    end
    function api.Stop()
        api.StopAllStockFarms()
        for _,e in pairs(engines) do e.Stop() end
    end
    function api.Release()
        api.Stop();local complete=true
        for key,e in pairs(engines) do if e.Release() then release_reservations(key) else complete=false end end
        return complete
    end
    function api.CanHandoff()
        for _,farm in pairs(farms) do if farm.running then return false end end
        for _,e in pairs(engines) do if not e.CanHandoff() then return false end end
        return true
    end
    return api
end

-- Host binding is deliberately narrow: documented stat reads and named tunables.
-- No direct persistent product/supply writes are made by this module.
local function make_host(context)
    local raw=context.Raw or {};local core=context.CScript.Economy
    local g,n,m,u,gta=raw.ScriptGlobal,raw.Natives,raw.Memory,raw.Utils,raw.GTA
    local host={}
    function host.StockFarmBlocked(key)
        local businesses=context.CScript.Businesses
        if not businesses then return false end
        local row
        if key=="bunker" and type(businesses.BunkerFarmSnapshot)=="function" then row=businesses.BunkerFarmSnapshot()
        elseif SUPPLY[key] and type(businesses.MCFarmSnapshot)=="function" then row=businesses.MCFarmSnapshot(key) end
        if row and row.active then return true,"Sale farm owns this business until its cycle stops." end
        return false
    end
    local factory_ids={mc_cocaine={3,8,13,18},mc_meth={1,6,11,16},mc_cash={4,9,14,19},mc_weed={2,7,12,17},mc_documents={5,10,15,20}}
    local function get(index)return g.GetInt(index)end
    local function stat(slot,name)return core.ReadStat(core.QualifyStat(slot,name))end
    local function basic()
        return g and type(g.AreValid)=="function" and g.AreValid()==true and n and u
            and n.InvokeString(0xFCA9373EF340AC0A)=="1.73"
            and n.InvokeInt(0x2C83A9DA6BFFC4F9,u.Joaat("freemode"))==1
    end
    function host.TransactionsIdle()
        if not basic() or type(n.InvokeBool)~="function" then return false,"Native transaction context is unavailable." end
        local manager=context.CScript.Businesses
        if not manager or type(manager.NativeTransactionsIdle)~="function" then return false,"Native transaction validation is unavailable." end
        return manager.NativeTransactionsIdle()
    end
    function host.SupplyReady()
        local manager=context.CScript.Businesses
        if not manager then return false,"Business sale state is unavailable." end
        for _,key in ipairs({"bunker","mc_cocaine","mc_meth","mc_cash","mc_weed","mc_documents"}) do
            local state=key=="bunker" and manager.BunkerFarmSnapshot and manager.BunkerFarmSnapshot()
                or key~="bunker" and manager.MCFarmSnapshot and manager.MCFarmSnapshot(key)
            if state and state.active and (state.phase=="WAIT_SALE_CONTROLLER" or state.phase=="WAIT_COMPLETION_READY"
                or state.phase=="WAIT_SETTLEMENT") then return false,"Waiting for sale settlement before requesting supplies." end
        end
        return true
    end
    local GET_NETWORK_TIME=0x7A5487FE9FAA6B48
    local GET_PACKED_STAT_INT_CODE=0x0BC900A6FE73770C
    local TIMER_START_INDEX=2709047
    local TIMER_INIT_INDEX=2709048
    local PLAYER_FACTORY5_BASE=1845879
    local PLAYER_STRIDE=884
    local FACTORY_SUPPLIES_OFFSET=2
    local FACTORY_INTERVAL_OFFSET=9
    local function signed32(value)
        value=math.floor(tonumber(value) or 0)%4294967296
        if value>=2147483648 then value=value-4294967296 end
        return value
    end
    local function read_global(index,lo,hi)
        if not g or type(g.GetInt)~="function" then return nil,"ScriptGlobal.GetInt unavailable" end
        local ok,raw_value=pcall(g.GetInt,index)
        if not ok then return nil,"global "..tostring(index).." read failed: "..tostring(raw_value) end
        local value=tonumber(raw_value)
        if not integer(value,lo,hi) then return nil,"global "..tostring(index).."="..tostring(raw_value).." is outside integer range "..tostring(lo)..".."..tostring(hi) end
        return math.floor(value)
    end
    local function write_global(index,value)
        if not g or type(g.SetInt)~="function" or type(g.GetInt)~="function" then return false,"ScriptGlobal read/write unavailable" end
        local ok,result=pcall(g.SetInt,index,value)
        if not ok or result==false then return false,"global write rejected at "..tostring(index) end
        local rok,observed=pcall(g.GetInt,index)
        if not rok or observed~=value then return false,"global readback mismatch at "..tostring(index) end
        return true
    end
    function host.Scope(business)
        if business=="hangar" then
            local pocket=context.CScript.HangarPocket
            local p=pocket and pocket.Snapshot and pocket.Snapshot()
            if p and (p.running or p.cleanup_pending) then return nil,"Pocket Dimension owns Hangar sourcing until its native transaction settles." end
        end
        if not basic()then return nil,"Enter a supported Enhanced freemode session."end
        local snap=core.Snapshot();local slot=core.CurrentSlot()
        if not snap.account_verified or not snap.online or (slot~=0 and slot~=1)then return nil,"Account context unavailable."end
        if PRODUCTION[business] then
            local property
            if business=="special_cargo" then
                local properties={};local owned=0
                for i=0,4 do
                    local id=stat(slot,"PROP_WHOUSE_SLOT"..i)
                    if not integer(id,0,1000) then return nil,"Warehouse ownership is unreadable." end
                    properties[#properties+1]=id;if id>0 then owned=owned+1 end
                end
                if owned==0 then return nil,"No cargo warehouse is owned." end
                property=table.concat(properties,",")
            else
                property=stat(slot,business=="nightclub" and "BUSINESSHUB_OWNED" or "HANGAR_OWNED")
                if not integer(property,1,1000) then return nil,"This property is not owned." end
            end
            return {account=snap.account_id,slot=slot,generation=snap.generation,business=business,property=property}
        end
        local factory=business=="bunker" and 5 or business=="acid_lab" and 6 or nil
        if factory==nil then
            local ids=factory_ids[business];if not ids then return nil,"Unsupported business."end
            for i=0,4 do
                local v=stat(slot,"FACTORYSLOT"..i)
                if not integer(v,0,1000) then return nil,"MC factory ownership is unreadable." end
                for _,id in ipairs(ids)do if v==id then
                    if factory~=nil then return nil,"MC factory ownership is ambiguous." end
                    factory=i
                end end
            end
        end
        if factory==nil then return nil,"This business is not owned."end
        local owned
        if factory==6 then
            local player=gta and gta.GetLocalPlayerId and gta.GetLocalPlayerId()
            if not integer(player,0,31) then return nil,"Acid Lab player ownership is unavailable." end
            -- freemode func_26824 owns these two mirrored signals together;
            -- XM22_LAB_OWNED is not the owning-script contract.
            local flags=read_global(1846097+player*884,-2147483648,2147483647)
            local property=read_global(1845892+player*884,0,32)
            if flags==nil or property~=32 or math.floor(flags/16384)%2~=1 then
                return nil,"Acid Lab ownership is not active in the current player factory state."
            end
            owned=32
        else owned=stat(slot,"FACTORYSLOT"..factory) end
        local setup=stat(slot,"FACTORYSETUP"..factory)
        if not integer(owned,1,1000) then return nil,"The business must be owned."end
        -- Setup stats are not a positive ownership/setup flag: the operational
        -- Bunker has been observed at zero. Delivery func_21960 validates the
        -- slot, not FACTORYSETUP. Validate owned property and actual inventory.
        local supplies=stat(slot,"MATTOTALFORFACTORY"..factory)
        local stock=stat(slot,"PRODTOTALFORFACTORY"..factory)
        if not integer(supplies,0,SUPPLY_READ_MAX) then return nil,"MATTOTALFORFACTORY"..factory.."="..tostring(supplies).." is outside integer range 0.."..SUPPLY_READ_MAX.."." end
        if not integer(stock,0,1000) then return nil,"PRODTOTALFORFACTORY"..factory.."="..tostring(stock).." is outside integer range 0..1000." end
        return {account=snap.account_id,slot=slot,generation=snap.generation,business=business,factory=factory,property=owned,setup=setup}
    end
    function host.Valid(c)
        local next_scope,why=host.Scope(c.business)
        if not next_scope then return false,why end
        for _,field in ipairs({"account","slot","generation","factory","property"}) do
            if next_scope[field]~=c[field] then
                return false,"Business scope "..field.." changed"..(field=="account" and "." or
                    " from "..tostring(c[field]).." to "..tostring(next_scope[field])..".")
            end
        end
        return true
    end
    function host.Read(c)
        if c.business=="nightclub" then
            if type(g.GetTunableByHash)~="function" or type(g.GetPtr)~="function" then return nil,"Nightclub capacity APIs unavailable." end
            local specs={{"CARGO",286213},{"WEAPONS",286207},{"COKE",286208},{"METH",286209},
                {"WEED",286210},{"FORGED_DOCUMENTS",286211},{"COUNTERFEIT_CASH",286212}}
            local total,capacity=0,0
            for i,spec in ipairs(specs) do
                local pointer=g.GetTunableByHash(u.Joaat("BB_BUSINESS_TOTAL_MAX_UNITS_"..spec[1]))
                if not pointer or pointer==0 or pointer~=g.GetPtr(spec[2]) then return nil,"Nightclub capacity does not match current source." end
                local cap=get(spec[2]);local stock=stat(c.slot,"HUB_PROD_TOTAL_"..(i-1))
                if not integer(cap,1,1000) or not integer(stock,0,cap) then return nil,"Nightclub inventory is unavailable or exceeds verified capacity." end
                total=total+stock;capacity=capacity+cap
            end
            return {stock=total,capacity=capacity}
        end
        local supplies=stat(c.slot,"MATTOTALFORFACTORY"..c.factory)
        local stock=stat(c.slot,"PRODTOTALFORFACTORY"..c.factory)
        if not integer(supplies,0,SUPPLY_READ_MAX) or not integer(stock,0,1000)then return nil,"Business inventory unavailable."end
        local capacities={
            bunker={"GR_MANU_CAPACITY",283486},acid_lab={"ACID_LAB_PRODUCT_CAPACITY",280998},
            mc_weed={"BIKER_WEED_CAPACITY",280958},mc_meth={"BIKER_METH_CAPACITY",280966},
            mc_cocaine={"BIKER_COCAINE_CAPACITY",280974},mc_documents={"BIKER_FAKEIDS_CAPACITY",280982},
            mc_cash={"BIKER_COUNTERCASH_CAPACITY",280990},
        }
        local inventory={supplies=supplies,stock=stock}
        local spec=capacities[c.business]
        if not spec or type(g.GetTunableByHash)~="function" or type(g.GetPtr)~="function" then
            return inventory
        end
        local pointer=g.GetTunableByHash(u.Joaat(spec[1]))
        if pointer~=g.GetPtr(spec[2]) then return inventory end
        local capacity=get(spec[2])
        if not integer(capacity,1,1000) then return inventory end
        return {supplies=supplies,stock=stock,capacity=capacity}
    end
    function host.Supply(c)
        if not host.Valid(c) or get(1673820)~=7 then return false,"Resupply array does not match the source contract."end
        local index=1673820+1+c.factory;local previous=get(index)
        if not integer(previous,0,2147483647)then return false,"Resupply timer unreadable."end
        if previous==1 then return true end
        local wrote=g.SetInt(index,1)
        local after=get(index)
        if wrote==false or (after~=1 and after~=0) then return false,"Resupply request did not verify." end
        return true,"Delivery requested; supplies have not yet been observed."
    end
    -- Paid staff orders store future cloud timestamps, not cargo quantities.
    -- am_mp_warehouse func_178/190/191 and am_mp_hangar func_8493/8495/8522.
    function host.ExpediteSource(scope)
        if not host.Valid(scope) then return false,"Staff sourcing context changed." end
        if not n or type(n.InvokeBool)~="function" or not m or type(m.AllocInt)~="function" or type(m.Free)~="function" then
            return false,"New orders are fast; existing-order stat APIs are unavailable."
        end
        local now=n.InvokeInt(0x9A73240B49945C76)
        if not integer(now,1,2147483647) then return false,"Cloud time is unavailable; existing orders were not changed." end
        local orders={}
        if scope.business=="hangar" then orders={{index=11904,pending=36828}}
        elseif scope.business=="special_cargo" then
            for i=0,4 do
                local owned=stat(scope.slot,"PROP_WHOUSE_SLOT"..i)
                if integer(owned,1,1000) then orders[#orders+1]={index=10400+i,pending=32359+i} end
            end
        else return false,"This property has no staff sourcing deadline." end
        local pointer=m.AllocInt()
        if not integer(pointer,1,9007199254740991) then return false,"Stat read buffer unavailable." end
        local changed,failed=0,nil
        local ok,why=pcall(function()
            for _,order in ipairs(orders) do
                if not host.Valid(scope) then error("Character changed during sourcing request.") end
                if n.InvokeBool(0xDA7EBFC49AE3F1B0,order.pending,scope.slot)==true then
                    local hash=n.InvokeInt(0xD69CE161FE614531,0,order.index,scope.slot)
                    if not integer(hash,-2147483648,4294967295) or hash==0 then error("Sourcing deadline hash is unavailable.") end
                    m.WriteInt(pointer,0)
                    if n.InvokeBool(0x767FBC2AC802EF3D,hash,pointer,-1)~=true then error("Sourcing deadline could not be read.") end
                    local before=m.ReadInt(pointer)
                    -- A pending flag with no future deadline is already ready.
                    if integer(before,now+1,math.min(2147483647,now+604800)) then
                        if n.InvokeBool(0xDA7EBFC49AE3F1B0,order.pending,scope.slot)~=true then error("Sourcing order changed before write.") end
                        if n.InvokeBool(0x767FBC2AC802EF3D,hash,pointer,-1)~=true or m.ReadInt(pointer)~=before then error("Sourcing deadline changed before write.") end
                        local target=now-1
                        if n.InvokeBool(0xB3271D7AB655B441,hash,target,true)~=true then error("Sourcing deadline write was rejected.") end
                        if n.InvokeBool(0x767FBC2AC802EF3D,hash,pointer,-1)~=true or m.ReadInt(pointer)~=target then
                            error("Sourcing deadline readback did not verify; stock is not confirmed.")
                        end
                        changed=changed+1
                    elseif not integer(before,0,now) then
                        error("Sourcing deadline is outside the supported clock range.")
                    end
                end
            end
        end)
        pcall(m.Free,pointer)
        if not ok then return false,tostring(why).." Verified deadlines changed: "..changed end
        return true,("Accelerated %d active staff order(s). New orders use the fast duration; cargo still requires GTA delivery."):format(changed)
    end
    -- This five-tunable profile and timer bootstrap filled Bunker stock from
    -- 25 to 100 in Enhanced 1.73 testing. Require source and pointer validation.
    local SPECS={
        {hash=215868155,after=1000},
        {hash=631477612,after=0},
        {hash=818645907,after=0},
        {hash=-1652502760,after=1},
        {hash=1647327744,after=1},
    }
    local function resolve(spec)
        if not g or type(g.GetTunableByHash)~="function" or not m
            or type(m.ReadInt)~="function" or not g.AreValid() then return nil end
        local ok,pointer=pcall(g.GetTunableByHash,spec.hash);pointer=ok and tonumber(pointer) or 0
        if not integer(pointer,1,9007199254740991) then return nil end
        local rok,value=pcall(m.ReadInt,pointer)
        if not rok or not integer(value,-2147483648,2147483647) then return nil end
        return {pointer=pointer,value=math.floor(value),after=spec.after,hash=spec.hash}
    end
    -- freemode func_21933 subtracts upgrade reductions from these base times.
    -- Zero both reductions while applying a 1000ms base, avoiding negatives.
    local FACTORY_PRODUCTION={
        mc_weed={name="BIKER_WEED_PRODUCTION_TIME",offset=17383,upgrades={{-1694873660,17393},{1575359233,17399}}},
        mc_meth={name="BIKER_METH_PRODUCTION_TIME",offset=17384,upgrades={{1944848251,17392},{1577999189,17398}}},
        mc_cocaine={name="BIKER_CRACK_PRODUCTION_TIME",offset=17385,upgrades={{2070857577,17391},{-1539796661,17397}}},
        mc_documents={name="BIKER_FAKEIDS_PRODUCTION_TIME",offset=17386,upgrades={{1672482518,17389},{-518264160,17395}}},
        mc_cash={name="BIKER_COUNTERCASH_PRODUCTION_TIME",offset=17387,upgrades={{1690071006,17390},{-1454958662,17396}}},
        acid_lab={name="BIKER_ACID_PRODUCTION_TIME",offset=17388,upgrades={{494316332,17394}}},
    }
    function host.ResolveProduction(scope)
        if not basic()then return nil,"Production context unavailable."end
        local specs=SPECS
        if scope and scope.business=="nightclub" then
            specs={}
            for i,hash in ipairs({-147565853,-1390027611,-1292210552,1007184806,18969287,-863328938,1607981264}) do
                specs[#specs+1]={hash=hash,index=262145+24039+i,after=1000}
            end
        elseif scope and scope.business=="special_cargo" then
            specs={{hash=u.Joaat("WAREHOUSE_CARGO_SOURCING_TIME"),index=262145+32129,after=0}}
        elseif scope and scope.business=="hangar" then
            specs={{hash=418213689,index=262145+32114,after=0}}
        elseif scope and scope.business~="bunker" then
            local profile=FACTORY_PRODUCTION[scope.business]
            if not profile or type(g.GetPtr)~="function" then return nil,"Production profile unavailable." end
            specs={{hash=u.Joaat(profile.name),index=262145+profile.offset,after=1000}}
            for _,upgrade in ipairs(profile.upgrades) do specs[#specs+1]={hash=upgrade[1],index=262145+upgrade[2],after=0} end
        end
        local rows,seen={},{}
        for _,spec in ipairs(specs)do
            local row=resolve(spec);if not row then return nil,"Production tunable does not match this build."end
            if spec.index and g.GetPtr(spec.index)~=row.pointer then return nil,"Production tunable pointer does not match current source." end
            if seen[row.pointer] then return nil,"Duplicate production tunable pointer." end
            seen[row.pointer]=true;rows[#rows+1]=row
        end
        return rows
    end
    function host.ReadCell(row)
        if not g or not m or not g.AreValid() or type(g.GetTunableByHash)~="function" or type(m.ReadInt)~="function" then return nil end
        local ok,pointer=pcall(g.GetTunableByHash,row.hash)
        if not ok or pointer~=row.pointer then return nil end
        local rok,value=pcall(m.ReadInt,row.pointer)
        return rok and integer(value,-2147483648,2147483647) and math.floor(value) or nil
    end
    function host.WriteCell(row,value)
        if host.ReadCell(row)==nil or not m or type(m.WriteInt)~="function" then return false end
        local ok,result=pcall(m.WriteInt,row.pointer,value)
        if not ok or result==false then return false end
        return host.ReadCell(row)==value
    end
    function host.CaptureProductionTimer(scope)
        if not basic() or not gta or type(gta.GetLocalPlayerId)~="function" or type(n.InvokeInt)~="function" then
            return nil,"Production timer APIs unavailable."
        end
        local pok,player=pcall(gta.GetLocalPlayerId);player=pok and tonumber(player) or nil
        if not integer(player,0,31) then return nil,"Local player id unavailable." end
        if scope.business=="special_cargo" or scope.business=="hangar" then
            -- The paid order controller creates sourcing deadlines. Duration
            -- overrides affect future orders; captured deadlines stay unchanged.
            return {scope=clone(scope),rows={}}
        end
        if scope.business=="nightclub" then
            if get(2709178)~=5 or get(2709197)~=8 then return nil,"Nightclub timer arrays do not match this build." end
            local now=n.InvokeInt(GET_NETWORK_TIME)
            if not integer(now,-2147483648,2147483647) then return nil,"Network time unavailable." end
            local rows={}
            local function capture(index,after,lo,hi)
                local value,why=read_global(index,lo,hi)
                if value==nil then return false,why end
                rows[#rows+1]={index=index,value=value,after=after};return true
            end
            -- Seven goods occupy 0..6 of the source's eight-entry cache.
            -- freemode func_20727 stores base minus elapsed network time;
            -- func_20752 also applies pause compensation. This is a signed
            -- remaining timer, with no source-defined 24-hour bound.
            for good=0,6 do
                local ok,why=capture(2709198+good,1000,-2147483648,2147483647)
                if not ok then return nil,"Nightclub production cache: "..tostring(why) end
            end
            for tech=0,4 do
