function Module.NewHangarGroundFinish(host)
    local api={}
    function api.Request()
        local ok,result,detail=pcall(function()
            local token=host.Capture();if not token or not host.Valid(token)then return false,'Ground-sale controller is unavailable.'end
            local function get(i,lo,hi)
                local v=host.Read(i)
                if type(v)~='number' or v%1~=0 or v<lo or v>hi then error('Ground sale is not ready (field '..i..').',0)end
                return v
            end
            get(4063,1,1);get(4065,token.pid,token.pid);get(4879,8,8);get(4083,4,4)
            local participant=get(4069,0,7);local phase=4879+1+participant*189+112
            get(phase,1,1);get(4727,1,1);get(4728,0,0)
            local required=get(213,1,50);local delivered=get(214,0,required)
            local flags=get(4084,-2147483648,2147483647)
            local rows={{214,delivered,required},{4084,flags,flags|2048},{4728,0,3},{phase,1,2},{4727,1,2}}
            for _,r in ipairs(rows)do
                if not host.Valid(token)or host.Read(r[1])~=r[2]then return false,'Ground-sale controller changed; remaining writes cancelled.'end
                if r[2]~=r[3] and (host.Write(r[1],r[3])==false or host.Read(r[1])~=r[3])then
                    return false,'Ground completion write did not verify; no automatic retry.'
                end
            end
            return true,'Ground-sale completion requested. GTA still owns cargo removal and payment.'
        end)
        if not ok then return false,tostring(result)end
        return result,detail
    end
    return api
end

local function complete_hangar_ground_sale(ctx)
    local reserve=module_context and module_context.CScript and module_context.CScript.HangarPocket
    local rs=reserve and reserve.Snapshot and reserve.Snapshot()
    if rs and (rs.running or rs.cleanup_pending or rs.action and rs.action.busy)then return false,'Stop Hangar cargo actions before finishing a sale.'end
    local memory=binding('Memory');local globals=binding('ScriptGlobal');local core=economy()
    if not memory or not memory.ScanScript or not memory.ReadUByte or not globals or not globals.AreValid or not ctx.locals.GetPtr or not core then
        return false,'Ground-sale verification APIs are unavailable.'
    end
    for _,pattern in ipairs(GROUND_PROFILE)do
        local at=memory.ScanScript(ctx.hash,pattern)
        if type(at)~='number' or at<=0 then return false,'Ground-sale script does not match the collected build.'end
        local offset=0
        for byte in pattern:gmatch('%x%x')do if memory.ReadUByte(at+offset)~=tonumber(byte,16)then return false,'Ground-sale code changed.'end;offset=offset+1 end
    end
    local function capture()
        if not globals.AreValid()or script_thread_count(ctx.hash)~=1 then return nil end
        local check=active_sale_context(ctx.profile,ctx.hash);if not check then return nil end
        local scope=core.Snapshot();local slot=core.CurrentSlot();local ptr=ctx.locals.GetPtr(ctx.hash,4232)
        if not scope or not scope.account_verified or not scope.online or (slot~=0 and slot~=1)or type(ptr)~='number' or ptr<=0 then return nil end
        return {pid=ctx.player,account=scope.account_id,generation=scope.generation,slot=slot,pointer=ptr}
    end
    return Module.NewHangarGroundFinish({Capture=capture,Valid=function(t)
        local s=capture();return s and s.pid==t.pid and s.account==t.account and s.generation==t.generation and s.slot==t.slot and s.pointer==t.pointer
    end,Read=function(i)return ctx.locals.GetInt(ctx.hash,i)end,Write=function(i,v)return ctx.locals.SetInt(ctx.hash,i,v)end}).Request()
end

local ACTIVE_SALE_HANDLERS = {
    hangar_ground=complete_hangar_ground_sale,
    mc = complete_mc_sale,
    bunker = complete_bunker_sale,
    hangar = complete_hangar_sale,
}

local function complete_active_sale()
    local active, query_error = {}
    for _, profile in ipairs(ACTIVE_SALE_PROFILES) do
        local hash, hash_err = script_hash(profile.script)
        if hash then
            local threads, thread_err = script_thread_count(hash)
            if threads and threads > 0 then active[#active + 1] = { profile = profile, hash = hash }
            elseif threads == nil and not query_error then query_error = thread_err end
        elseif not query_error then query_error = hash_err end
    end
    local ground=false
    for _,row in ipairs(active)do if row.profile.key=='hangar_ground'then ground=true end end
    if ground then for i=#active,1,-1 do if active[i].profile.key=='hangar'then table.remove(active,i)end end end
    if #active == 0 then
        return false, query_error or "Start an MC, Bunker, or Hangar sell mission first."
    end
    if #active > 1 then
        return false, "Multiple supported sale scripts are active; no completion write was attempted."
    end
    local selected = active[1]
    local ctx, ctx_err = active_sale_context(selected.profile, selected.hash)
    if not ctx then
        local logger=module_context and module_context.Logger
        if logger and logger.Info then logger.Info("active-sale detection failed: "..tostring(ctx_err),"Businesses")end
        return false,ctx_err
    end
    local handler = ACTIVE_SALE_HANDLERS[selected.profile.key]
    local ok, detail = handler(ctx)
    if module_context and module_context.Logger and type(module_context.Logger.Info) == "function" then
        module_context.Logger.Info(("active-sale profile=%s ok=%s evidence=%s detail=%s")
            :format(selected.profile.key, tostring(ok == true), selected.profile.evidence, tostring(detail)), "Businesses")
    end
    return ok == true, detail
end

local sale_finish_pending
local function finish_thread_identity(hash)
    local scripts,natives,locals=binding("Script"),binding("Natives"),binding("ScriptLocal")
    if not scripts or not natives or not locals or not locals.GetPtr or script_thread_count(hash)~=1 then return nil end
    local tid
    local ok=pcall(scripts.ExecuteAsScript,hash,function()tid=natives.InvokeInt(0xC30338E8088E2E21)end)
    local ptr=locals.GetPtr(hash,738)
    if not ok or type(tid)~="number" or tid<=0 or not ptr or ptr<=0 then return nil end
    return tostring(tid)..":"..tostring(ptr)
end
local function request_sale_finish()
    if sale_finish_pending then return false,"Sale completion is already waiting for the start announcement."end
    local ok,why=complete_active_sale()
    if not ok and (tostring(why):find("Waiting for the sale-start announcement",1,true)
        or tostring(why):find("Waiting for the MC sale to settle",1,true)) then
        local locals=binding("ScriptLocal");local hash=script_hash("gb_biker_contraband_sell")
        local pointer=locals and locals.GetPtr and locals.GetPtr(hash,738)
        if not pointer or pointer<=0 then return false,why end
        local identity=finish_thread_identity(hash);if not identity then return false,"Sale instance identity unavailable."end
        sale_finish_pending={hash=hash,pointer=pointer,identity=identity,started=State.clock_ms or 0,generation=State.generation}
        return true,"Finish queued; waiting for the MC start announcement to clear."
    end
    return ok,why
end
local function tick_sale_finish(now)
    local p=sale_finish_pending;if not p then return end
    local locals=binding("ScriptLocal")
    local ok,why
    if p.generation~=State.generation or script_thread_count(p.hash)~=1 or not locals or locals.GetPtr(p.hash,738)~=p.pointer or finish_thread_identity(p.hash)~=p.identity then
        ok,why=false,"Sale controller changed; queued finish cancelled."
    elseif now-p.started>30000 then ok,why=false,"Sale-start announcement did not clear; queued finish stopped."
    else
        ok,why=complete_active_sale()
        if not ok and (tostring(why):find("Waiting for the sale-start announcement",1,true)
            or tostring(why):find("Waiting for the MC sale to settle",1,true)) then return end
    end
    sale_finish_pending=nil
    State.last_action={ok=ok==true,key="complete_active_sale",detail=tostring(why)}
    local logger=module_context and module_context.Logger
    if logger and logger.Info then logger.Info("queued-finish ok="..tostring(ok).." detail="..tostring(why),"Businesses")end
end

-- Source-backed direct Bunker sale launch. The Disruption Logistics app
-- registers IG_SELL_0_t0_v0, writes mission request 226 plus route 0/1 into
-- Global_1893070[player], then dispatches event 1613825825 to freemode.
-- Route 0 is Los Santos; freemode's Bunker delivery selector maps that route
-- to the city/airport/port destination tables. Route 1 is Blaine County.
function Module.NewBunkerSaleStart(host)
    local active
    local api={}
    local function fail(reason)
        if active and type(host.Cleanup)=="function" then pcall(host.Cleanup,active.token,active.route,reason) end
        if active then
            active.phase="FAILED";active.ok=false;active.reason=tostring(reason or "Bunker sale start failed.")
        end
        return false,active and active.reason or tostring(reason)
    end
    function api.Start(route,now)
        if active and active.phase~="FAILED" and active.phase~="STARTED" then
            return false,"A Bunker sale start is already pending."
        end
        route=tonumber(route);now=tonumber(now) or 0
        if route~=0 and route~=1 then return false,"Bunker sale route must be 0 or 1." end
        local token,why=host.Capture(route)
        if not token then return false,tostring(why or "Bunker launch context unavailable.") end
        local ok,tx=host.BeginRegistration(token)
        if ok~=true then return false,tostring(tx or "Bunker sale registration was rejected.") end
        active={phase="WAIT_REGISTRATION",ok=nil,route=route,token=token,transaction_id=tx,
            started_ms=now,updated_ms=now,dispatched=false}
        return true,active
    end
    function api.Tick(now)
        if not active or active.phase=="FAILED" or active.phase=="STARTED" then return active end
        now=tonumber(now) or 0;active.updated_ms=now
        if host.Valid(active.token)~=true then fail("Bunker launch context changed.");return active end
        if active.phase=="WAIT_REGISTRATION" then
            local state,detail=host.RegistrationState(active.token,active.transaction_id)
            if state=="success" then
                local armed,arm_err=host.ArmRequest(active.token,active.route)
                if armed~=true then fail(arm_err or "Bunker mission request could not be armed.");return active end
                local sent,send_err=host.Dispatch(active.token,active.route)
                if sent~=true then fail(send_err or "Bunker mission request event was rejected.");return active end
                active.phase="WAIT_CONTROLLER";active.dispatched=true;active.dispatched_ms=now
            elseif state=="failed" then
                fail(detail or "Bunker sale registration failed.");return active
            elseif now-(tonumber(active.started_ms) or now)>15000 then
                fail("Bunker sale registration timed out.");return active
            end
        elseif active.phase=="WAIT_CONTROLLER" then
            if host.ControllerReady(active.token)==true then
                active.phase="STARTED";active.ok=true;active.started_controller_ms=now
            elseif now-(tonumber(active.dispatched_ms) or now)>20000 then
                fail("Bunker controller did not start after the freemode request.")
            end
        end
        return active
    end
    function api.Snapshot()
        if not active then return {phase="IDLE",ok=nil} end
        return {phase=active.phase,ok=active.ok,route=active.route,reason=active.reason,
            transaction_id=active.transaction_id,dispatched=active.dispatched==true}
    end
    function api.Cancel(reason)
        if not active or active.phase=="FAILED" or active.phase=="STARTED" then return false end
        return fail(reason or "Bunker sale start cancelled.")
    end
    return api
end

-- Uses Rockstar's own Disruption Logistics app for sale registration. This avoids
-- recreating the cash-transaction manager: the app performs
-- PROCESS_TRANSACTION_FOR_CONTRABAND_MISSION, then launches mission 226 normally.
-- The driver only opens the app, selects PAGE_SELL / Los Santos, confirms the
-- app's own overlays, and waits for gb_gunrunning.
function Module.NewBunkerAppSale(host)
    local active
    local api={}
    local function cleanup(reason)
        active.cleanup_request=reason or active.cleanup_request
        if type(host.Cleanup)=="function" then
            local ok,result,why=pcall(host.Cleanup,active.token,active.cleanup_request)
            active.cleaned=ok and result==true
            if active.cleaned then active.cleanup_reason=nil
            else active.cleanup_reason=tostring(why or result or "Bunker owned-app cleanup is unconfirmed.") end
        else active.cleaned=true;active.cleanup_reason=nil end
    end
    local function fail(reason)
        if active then
            active.phase="FAILED";active.ok=false;active.reason=tostring(reason or "Bunker app sale failed.")
            cleanup(active.reason)
        end
        return false,active and active.reason or tostring(reason)
    end
    local function started(now)
        active.phase="STARTED";active.ok=true;active.controller_ms=now
        cleanup("Bunker sale registered.")
        return active
    end
    function api.Start(now)
        if active and active.cleaned==false then
            return false,"Bunker app cleanup is pending: "..tostring(active.cleanup_reason)
        end
        if active and active.phase~="FAILED" and active.phase~="STARTED" then
            return false,"A Bunker app sale is already pending."
        end
        now=tonumber(now) or 0
        local token,why=host.Capture()
        if not token then return false,tostring(why or "Bunker app launch context unavailable.") end
        -- Capture ownership before EnsureApp: even a rejected launch can leave
        -- an owned thread or temporary patches that must be cleaned up.
        active={phase="WAIT_APP",ok=nil,token=token,started_ms=now,phase_ms=now,
            selection_handle=nil,moves=0,reason=nil}
        local ok,detail=host.EnsureApp(token)
        if ok~=true then return fail(detail or "Bunker app could not start.") end
        return true,active
    end
    function api.Tick(now)
        if active and type(host.Maintain)=="function" then pcall(host.Maintain,active.token) end
        if not active then return active end
        if active.phase=="FAILED" or active.phase=="STARTED" then
            -- Terminal launch status does not release the cleanup obligation.
            if active.cleaned==false then cleanup() end
            return active
        end
        if type(host.PumpQuiet)=="function" then
            local ok,why=host.PumpQuiet(active.token);if not ok then fail(why);return active end
        end
        now=tonumber(now) or 0
        if host.Valid(active.token)~=true then fail("Bunker app sale context changed.");return active end
        if host.ControllerReady(active.token)==true then return started(now) end
        local state,read_err=host.Read(active.token)
        if type(state)~="table" then fail(read_err or "Bunker app state is unreadable.");return active end

        if active.phase=="WAIT_APP" then
            if state.threads==1 and state.scaleform and state.scaleform>0 then
                -- The app is fully initialized before its login splash. Jumping to
                -- PAGE_SELL through the app's own SHOW_SCREEN method avoids a fake
                -- mouse/keyboard login click while leaving transaction ownership in
                -- appBunkerBusiness.
                local ok,why=host.ShowSellPage(active.token,state)
                if not ok then fail(why);return active end
                active.phase="WAIT_SELL";active.phase_ms=now
            else
                local ok,why=host.EnsureApp(active.token)
                if not ok then fail(why);return active end
                if now-(active.phase_ms or now)>10000 then fail("Bunker app did not become ready.");return active end
            end
        elseif active.phase=="WAIT_HOME" then
            if state.page==1 or state.page==7 then
                local ok,why=host.ShowSellPage(active.token,state)
                if not ok then fail(why);return active end
                active.phase="WAIT_SELL";active.phase_ms=now
            elseif now-(active.phase_ms or now)>7000 then
                fail("Bunker app login did not reach the home page.");return active
            end
        elseif active.phase=="WAIT_SELL" then
            if state.page==7 then
                local handle,why=host.QuerySelection(active.token,state)
                if not handle then fail(why);return active end
                active.selection_handle=handle;active.phase="WAIT_SELECTION";active.phase_ms=now
            elseif now-(active.phase_ms or now)>5000 then
                fail("Bunker app did not enter the Sell page.");return active
            end
        elseif active.phase=="WAIT_SELECTION" or active.phase=="WAIT_CITY_SELECTION" then
            local selection,ready,why=host.ReadSelection(active.token,active.selection_handle)
            if why then fail(why);return active end
            if ready then
                active.last_selection=selection
                if selection==10 then
                    local ok,press_err=host.PulseAccept(active.token,state)
                    if not ok then fail(press_err);return active end
                    active.phase="WAIT_OVERLAY";active.phase_ms=now
                elseif (selection==-1 or selection==9) and (active.moves or 0)<3 then
                    local ok,move_err=host.SelectCity(active.token,state)
                    if not ok then fail(move_err);return active end
                    active.moves=(active.moves or 0)+1
                    local handle,query_err=host.QuerySelection(active.token,state)
                    if not handle then fail(query_err);return active end
                    active.selection_handle=handle;active.phase="WAIT_CITY_SELECTION";active.phase_ms=now
                else
                    fail("Unexpected Bunker Sell-page selection "..tostring(selection)..".");return active
                end
            elseif now-(active.phase_ms or now)>5000 then
                fail("Bunker Sell-page selection query timed out.");return active
            end
        elseif active.phase=="WAIT_WARNING_SELECTION" or active.phase=="WAIT_FINAL_SELECTION" then
            local selection,ready,why=host.ReadSelection(active.token,active.selection_handle)
            if why then fail(why);return active end
            if ready then
                active.last_selection=selection
                if selection~=1 then fail("Unexpected Bunker confirmation selection "..tostring(selection).." at stage "..tostring(state.stage)..".");return active end
                local ok,press_err=host.PulseAccept(active.token,state)
                if not ok then fail(press_err);return active end
                active.phase=active.phase=="WAIT_WARNING_SELECTION" and "WAIT_CONFIRM_OVERLAY" or "WAIT_CONTROLLER"
                active.phase_ms=now
            elseif now-(active.phase_ms or now)>5000 then
                fail("Bunker confirmation selection query timed out.");return active
            end
        elseif active.phase=="WAIT_OVERLAY" then
            if state.stage==5 then
                local ok,why=host.SelectConfirm(active.token,state)
                if not ok then fail(why);return active end
                local handle,query_err=host.QuerySelection(active.token,state)
                if not handle then fail(query_err);return active end
                active.selection_handle=handle;active.phase="WAIT_WARNING_SELECTION";active.phase_ms=now
            elseif state.stage==2 then
                local ok,why=host.SelectConfirm(active.token,state)
                if not ok then fail(why);return active end
                local handle,query_err=host.QuerySelection(active.token,state)
                if not handle then fail(query_err);return active end
                active.selection_handle=handle;active.phase="WAIT_FINAL_SELECTION";active.phase_ms=now
            elseif state.overlay and state.stage==0 then
                fail("Bunker app rejected the sale before confirmation.");return active
            elseif now-(active.phase_ms or now)>7000 then
                fail("Bunker sale confirmation overlay did not appear.");return active
            end
        elseif active.phase=="WAIT_CONFIRM_OVERLAY" then
            if state.stage==2 then
                local ok,why=host.SelectConfirm(active.token,state)
                if not ok then fail(why);return active end
                local handle,query_err=host.QuerySelection(active.token,state)
                if not handle then fail(query_err);return active end
                active.selection_handle=handle;active.phase="WAIT_FINAL_SELECTION";active.phase_ms=now
            elseif state.overlay and state.stage==0 then
                fail("Bunker app rejected the sale after the gang-size warning.");return active
            elseif now-(active.phase_ms or now)>7000 then
                fail("Bunker final confirmation overlay did not appear.");return active
            end
        elseif active.phase=="WAIT_CONTROLLER" then
            if host.ControllerReady(active.token)==true then return started(now) end
            if state.threads==0 and now-(active.phase_ms or now)>2000 then
                fail("Bunker app exited before gb_gunrunning started.");return active
            elseif now-(active.phase_ms or now)>20000 then
                fail("gb_gunrunning did not start after the Bunker app confirmed the sale.");return active
            end
        end
        return active
    end
    function api.Snapshot()
        if not active then return {phase="IDLE",ok=nil} end
        return {phase=active.phase,ok=active.ok,reason=active.reason,last_selection=active.last_selection,
            moves=active.moves or 0,cleanup_pending=active.cleaned==false,cleanup_reason=active.cleanup_reason}
    end
    function api.Cancel(reason)
        if not active or active.phase=="FAILED" or active.phase=="STARTED" then return false end
        return fail(reason or "Bunker app sale cancelled.")
    end
    function api.Shutdown()
        if type(host.Shutdown)=="function" then return host.Shutdown(active and active.token) end
        if active and type(host.Cleanup)=="function" then return host.Cleanup(active.token) end
    end
    return api
end

-- Temporary edits to this owned app's presentation functions only. Verify every
-- signature before any write. Never retain a code pointer between calls/frames.
function Module.NewBunkerQuietApp(host,profile)
    local lease
    local api={}
    local function bytes(text)
        local out={} for h in tostring(text):gmatch('%x%x') do out[#out+1]=tonumber(h,16) end return out
    end
    local function pattern(row)
        local out={} for i,v in ipairs(row.current) do out[i]=string.format('%02X',v) end return table.concat(out,' ')
    end
    local function resolve(row)
        local ok,address=pcall(host.Scan,pattern(row));address=ok and tonumber(address) or nil
        if not address or address<=0 then return nil end
        for i,v in ipairs(row.current) do
            local read,b=pcall(host.Read,address+i-1)
            if not read or b~=v then return nil end
        end
        return address
    end
    local function write(row,address,index,value)
        local ok,result=pcall(host.Write,address+index-1,value)
        local read,b=pcall(host.Read,address+index-1)
        if read and type(b)=='number' then row.current[index]=b end
        return ok and result~=false and read and b==value
    end
    function api.Restore()
        if not lease then return true,'clean' end
        local loaded=host.Loaded()
        if loaded==false then lease=nil;return true,'unloaded' end
        if loaded~=true then return false,'Bunker quiet app load state is unavailable.' end
        if host.Threads()~=0 then return false,'Bunker quiet app cleanup is pending.' end
        local addresses={}
        for i,row in ipairs(lease) do
            addresses[i]=resolve(row)
            if not addresses[i] then return false,'Bunker quiet app restore signature changed: '..row.name end
        end
        for i,row in ipairs(lease) do
            for j,v in ipairs(row.original) do
                if row.current[j]~=v and not write(row,addresses[i],j,v) then
                    return false,'Bunker quiet app restore write failed: '..row.name
                end
            end
        end
        lease=nil;return true,'restored'
    end
    function api.Apply()
        if lease then
            local ok,why=api.Restore();if not ok then return false,why end
        end
        if host.Loaded()~=true or host.Threads()~=0 then return false,'Bunker app must be loaded with no existing thread.' end
        local rows,addresses={},{}
        for i,spec in ipairs(profile or {}) do
            local original=bytes(spec.original)
            local current={} for j,v in ipairs(original) do current[j]=v end
            local row={name=spec.name,original=original,current=current,offset=spec.offset,replacement=bytes(spec.replacement)}
            rows[i]=row;addresses[i]=resolve(row)
            if not addresses[i] then return false,'Bunker quiet app signature does not match this build: '..row.name end
        end
        if #rows==0 then return false,'Bunker quiet app profile is empty.' end
        lease=rows
        for i,row in ipairs(rows) do
            for j,v in ipairs(row.replacement) do
                if not write(row,addresses[i],row.offset+j,v) then
                    local restored,why=api.Restore()
                    return false,'Bunker quiet app patch write failed: '..row.name..(restored and '' or '; '..tostring(why))
                end
            end
        end
        return true,'quiet'
    end
    function api.Pending()return lease~=nil end
    return api
end

-- The owned MC app executes its original eligibility, quote and sale-registration
-- functions. Commands use an otherwise inert rollover local; no player input.
function Module.NewMCAppSale(host)
    local active
    local api={}
    local function fail(why)
        if active then
            if active.phase~='FAILED' then active.failure_phase=active.phase end
            active.phase='FAILED';active.reason=tostring(why);active.ok=false
            local ok,result=pcall(host.Cleanup,active.token)
            active.cleaned=ok and result==true
        end
        return false,tostring(why)
    end
    local function rejected(why,state)
        return fail(("%s [phase=%s stage=%s property=%s command=%s overlay=%s quote=%s]")
            :format(why,tostring(active.phase),tostring(state.stage),tostring(state.property),
                tostring(state.command),tostring(state.overlay),tostring(state.quote)))
    end
    function api.Start(now)
        if active and (not active.cleaned or active.phase~='FAILED' and active.phase~='STARTED') then
            return false,'An MC background app is still pending.'
        end
        local token,why=host.Capture();if not token then return false,why end
        active={token=token,phase='WAIT_APP',phase_ms=now,started_ms=now,cleaned=false}
        local ok,err=host.EnsureApp(token);if not ok then return fail(err) end
        return true
    end
    local function tick(now)
        if not active then return end
        host.Maintain(active.token)
        if active.phase=='FAILED' or active.phase=='STARTED' then
            if not active.cleaned then local ok,result=pcall(host.Cleanup,active.token);active.cleaned=ok and result==true end
            return active
        end
        if not host.Valid(active.token) then fail('MC sale context changed.');return active end
        local ok,why=host.PumpQuiet(active.token);if not ok then fail(why);return active end
        if host.ControllerReady(active.token) then
            active.phase='STARTED';active.ok=true
            local called,result=pcall(host.Cleanup,active.token);active.cleaned=called and result==true
            return active
        end
        local s,err=host.Read(active.token);if not s then fail(err);return active end
        active.app_stage=s.stage;active.app_property=s.property;active.app_command=s.command
        if s.quote and s.quote>0 then active.quote=s.quote end
        if active.phase=='WAIT_APP' then
            if s.threads==1 and s.scaleform and s.scaleform>0 then
                local bound,detail=host.BindBusiness(active.token);if not bound then fail(detail);return active end
                active.phase='WAIT_BUSINESS';active.phase_ms=now
                -- Binding can be synchronous; use verified readback immediately.
                s,err=host.Read(active.token);if not s then fail(err);return active end
                active.app_stage=s.stage;active.app_property=s.property;active.app_command=s.command
            else local ready,detail=host.EnsureApp(active.token);if not ready then fail(detail);return active end end
        end
        if active.phase=='WAIT_BUSINESS' then
            if s.property==active.token.property then
                local sent,detail=host.Dispatch(active.token,1);if not sent then fail(detail);return active end
                active.phase='WAIT_OVERLAY';active.phase_ms=now
            end
        elseif active.phase=='WAIT_OVERLAY' or active.phase=='WAIT_FINAL' then
            if s.command==-1 and s.overlay then
                if s.stage~=1003 and s.stage~=3012 then rejected('MC business rejected the sale.',s);return active end
                if active.phase=='WAIT_FINAL' and s.stage~=3012 then rejected('MC sale confirmation did not advance.',s);return active end
                local sent,detail=host.Dispatch(active.token,2);if not sent then fail(detail);return active end
                active.phase=s.stage==1003 and 'WAIT_FINAL' or 'WAIT_CONTROLLER';active.phase_ms=now
            end
        elseif active.phase=='WAIT_CONTROLLER' then
            if s.overlay and s.stage==0 and s.command==-1 then rejected('MC business rejected the confirmed sale.',s);return active end
            if s.threads==0 and now-active.phase_ms>2000 then fail('MC app exited before the sale started.');return active end
        end
        if now-active.phase_ms>(active.phase=='WAIT_CONTROLLER' and 25000 or 10000) then rejected('MC background sale timed out.',s) end
        return active
    end
    function api.Tick(now)
        local before=active and active.phase
        local ok,result=pcall(tick,now)
        if not ok then fail('MC app stopped: '..tostring(result));return active end
        if active and active.phase~=before and type(host.Report)=='function' then
            pcall(host.Report,active.phase,active.app_stage,active.app_property,active.app_command,active.quote)
        end
        return result
    end
    function api.Snapshot()
        if not active then return {phase='IDLE'} end
        return {phase=active.phase,ok=active.ok,reason=active.reason,quote=active.quote,cleanup_pending=not active.cleaned,
            failure_phase=active.failure_phase,app_stage=active.app_stage,app_property=active.app_property,app_command=active.app_command}
    end
    function api.Cancel(why)if active then return fail(why or 'MC sale stopped.') end end
    function api.Shutdown()if active then return host.Shutdown(active.token) end;return true end
    return api
end

function Module.BusinessTransactionsIdle(host)
    local header=host.Read(4515492)
    if header~=16 then return false,"Native transaction header is unreadable or changed: "..tostring(header) end
    local basket,checkout=host.Basket(),host.Checkout()
    if basket~=false or checkout~=false then
        return false,("Native transactions busy: basket=%s checkout=%s."):format(tostring(basket),tostring(checkout))
    end
    -- VM arrays carry a header before the first 84-cell transaction record.
    for slot=0,14 do
        local value=host.Read(4515492+1+slot*84+67)
        if value~=0 then return false,("Native transaction pending: slot=%d state=%s."):format(slot,tostring(value)) end
    end
    return true
end

-- Separate production leases may run together. GTA's sale controller, laptop
-- and payment settlement belong to one farm at a time, in request order.
function Module.NewSaleQueue(idle)
    local owner,queue=nil,{}
    local api={}
    function api.Acquire(key)
        if owner==key then return true end
        local queued=false;for _,item in ipairs(queue)do if item==key then queued=true end end
        if not queued then queue[#queue+1]=key end
        if owner then return false,"Waiting for "..tostring(owner).." sale settlement." end
        if queue[1]~=key then return false,"Waiting behind "..tostring(queue[1]).." in the sale queue." end
        local ready,why=idle()
        if ready~=true then return false,why or "Another mission or business laptop is active." end
        owner=table.remove(queue,1);return true
    end
    function api.Release(key)if owner==key then owner=nil end end
    function api.Cancel(key)
        api.Release(key)
        for i=#queue,1,-1 do if queue[i]==key then table.remove(queue,i)end end
    end
    return api
end

function Module.NewMCFarm(host)
    local farm
    local api={}
    local function stop(phase,reason)
        pcall(host.Supplies,false)
        if host.Production then pcall(host.Production,false) end
        if host.CancelSale then pcall(host.CancelSale,reason) end
        if host.ReleaseSale then pcall(host.ReleaseSale) end
        if farm then farm.active=false;farm.phase=phase;farm.reason=reason end
        if type(host.Report)=='function'then pcall(host.Report,phase,reason)end
        return false,reason
    end
    function api.Start(repeat_mode,now)
        if farm and farm.active then return false,'MC Auto Farm is already running.' end
        local row,why=host.Read();if not row then return false,why end
        local ok,detail=host.Supplies(true);if not ok then return false,detail end
        if host.Production then
            local applied,err=host.Production(true)
            if not applied then host.Supplies(false);return false,err end
        end
        farm={active=true,phase='PRODUCING',repeat_mode=repeat_mode~=false,cycles=0,
            account=row.account,generation=row.generation,slot=row.slot,factory=row.factory,property=row.property,
            phase_ms=now,last_stock=row.stock,last_supplies=row.supplies}
        return true
    end
    local function tick(now)
        if not farm or not farm.active then return end
        local row,why=host.Read()
        if not row or row.account~=farm.account or row.generation~=farm.generation or row.slot~=farm.slot
            or row.factory~=farm.factory or row.property~=farm.property then
            return stop('FAILED',why or 'MC business context changed.')
        end
        farm.last_stock,farm.last_supplies,farm.capacity=row.stock,row.supplies,row.capacity
        if farm.phase=='PRODUCING' then
            if row.stock>=row.capacity then
                host.Supplies(false)
                if host.Production then host.Production(false) end
                farm.phase='WAIT_PRODUCTION_SETTLEMENT';farm.phase_ms=now
                farm.settle_stock=nil;farm.production_idle_since=nil
            elseif now-farm.phase_ms>=3000 and not host.SupplyActive() then return stop('FAILED','MC supplies stopped before stock was full.')
            elseif now-farm.phase_ms>=3000 and host.ProductionActive and not host.ProductionActive() then return stop('FAILED','MC production stopped before stock was full.') end
        elseif farm.phase=='WAIT_PRODUCTION_SETTLEMENT' then
            local idle,wait_reason=false,"Transaction state is unavailable."
            if host.TransactionsIdle then idle,wait_reason=host.TransactionsIdle() end
            if idle~=true then
                farm.wait_reason=wait_reason or "Production transaction is still pending."
                farm.production_idle_since=nil;farm.settle_stock=nil
            else
                farm.wait_reason=nil
                if farm.settle_stock~=row.stock then
                    farm.settle_stock=row.stock;farm.production_idle_since=now
                end
                if idle==true and now-(farm.production_idle_since or now)>=1000 then
                    if row.stock<row.capacity then
                        local ok,why=host.Supplies(true);if not ok then return stop('FAILED',why) end
                        if host.Production then
                            local ready,err=host.Production(true);if not ready then return stop('FAILED',err) end
                        end
                        farm.phase='PRODUCING';farm.phase_ms=now
                    else
                        farm.phase='WAIT_SALE_TURN';farm.phase_ms=now
                    end
                end
            end
            if farm.phase=='WAIT_PRODUCTION_SETTLEMENT' and now-farm.phase_ms>60000 then
                return stop('FAILED','Production transaction is still pending. Sale was not started; wait for GTA to finish saving.')
            end
        end
        if farm.phase=='WAIT_SALE_TURN' then
            -- Queue readiness can become stale while another farm owns settlement.
            local idle,why=host.TransactionsIdle and host.TransactionsIdle()
            if idle~=true then
                farm.production_idle_since=nil;farm.wait_reason=why or 'Waiting for native transaction settlement.';return
            end
            farm.production_idle_since=farm.production_idle_since or now
            if now-farm.production_idle_since<1000 then return end
            local acquired=true
            if host.AcquireSale then acquired,why=host.AcquireSale() end
            if acquired==true then farm.wait_reason=nil else farm.wait_reason=why or "Waiting for the current sale to settle." end
            if acquired==true then
                farm.balance_before=row.balance;farm.stock_before=row.stock;farm.anchor=host.BeginAttribution()
                local ok,err=host.StartSale(now);if not ok then return stop('FAILED',err) end
                farm.phase='WAIT_SALE_CONTROLLER';farm.phase_ms=now
            end
        elseif farm.phase=='WAIT_SALE_CONTROLLER' then
            local sale=host.SaleSnapshot()
            if sale.phase=='FAILED' then return stop('FAILED',sale.reason) end
            if sale.quote and sale.quote>0 then farm.expected_payout=sale.quote end
            if sale.phase=='STARTED' then
                if not farm.expected_payout then return stop('FAILED','MC sale quote was unavailable.') end
                farm.phase='WAIT_COMPLETION_READY';farm.phase_ms=now
            elseif now-farm.phase_ms>40000 then return stop('FAILED','MC sale did not start.') end
        elseif farm.phase=='WAIT_COMPLETION_READY' then
            -- Controller presence alone precedes its asynchronous start/reward work.
            -- Keep manual completion on its existing path; pace automatic farms.
            if now-farm.phase_ms<1500 then return end
            if not host.TransactionsIdle or host.TransactionsIdle()~=true then
                farm.wait_reason='Waiting for sale-start transaction settlement.'
                if now-farm.phase_ms>20000 then return stop('FAILED',farm.wait_reason) end
                return
            end
            farm.wait_reason=nil
            local ok,err=host.CompleteSale(farm)
            if ok then farm.phase='WAIT_SETTLEMENT';farm.phase_ms=now;farm.settle_good=0
            elseif now-farm.phase_ms>20000 then return stop('FAILED',err or 'MC sale completion did not become ready.') end
        elseif farm.phase=='WAIT_SETTLEMENT' then
            local delta=row.balance-farm.balance_before
            farm.last_balance_delta=delta
            -- Normal production can add stock while the paid controller closes.
            -- Require inventory reduction, the full quote, ended controller and
            -- idle native transactions together, rather than an exact zero.
            local ended=host.SaleEnded()
            local idle=host.TransactionsIdle and host.TransactionsIdle()==true
            if row.stock<farm.stock_before and delta>=farm.expected_payout and ended and idle then
                if farm.settle_delta~=delta or farm.settle_stock~=row.stock or not farm.settle_since or now<farm.settle_since then
                    farm.settle_delta,farm.settle_stock,farm.settle_since,farm.settle_last=delta,row.stock,now,now
                    farm.settle_good=1
                elseif now>farm.settle_last then
                    farm.settle_good=(farm.settle_good or 0)+1;farm.settle_last=now
                end
                if farm.settle_good>=3 and now-farm.settle_since>=1000 then
                    farm.cycles=farm.cycles+1;farm.observed_balance_delta=delta;farm.payment_verified=false
                    local called,attributed=pcall(host.Attribute,farm.anchor,delta)
                    farm.earning_attributed=called and attributed==true;farm.anchor=nil
                    farm.attributed_balance_delta=farm.earning_attributed and delta or nil
                    farm.last_cycle_payout=farm.attributed_balance_delta
                    if host.ReleaseSale then host.ReleaseSale() end
                    farm.phase=farm.repeat_mode and 'COOLDOWN' or 'COMPLETED';farm.active=farm.repeat_mode
                    farm.phase_ms=now
                    if type(host.Report)=='function' then
                        pcall(host.Report,farm.phase,('Sale cycle %d observed; balance +%d (%s), stock=%d/%d. Payment persistence unverified.')
                            :format(farm.cycles,delta,farm.earning_attributed and 'correlated' or 'attribution unavailable',row.stock,farm.stock_before))
                    end
                end
            else farm.settle_good=0;farm.settle_since,farm.settle_last,farm.settle_delta,farm.settle_stock=nil,nil,nil,nil end
            if farm.active and farm.phase=='WAIT_SETTLEMENT' and now-farm.phase_ms>45000 then
                return stop('FAILED',('MC settlement not confirmed: payout=%d/%d stock=%d/%d controllerEnded=%s transactionsIdle=%s.')
                    :format(delta,farm.expected_payout,row.stock,farm.stock_before,tostring(ended),tostring(idle)))
            end
        elseif farm.phase=='COOLDOWN' then
            local ok,err=host.Supplies(true);if not ok then return stop('FAILED',err) end
            if host.Production then
                local applied,why=host.Production(true);if not applied then return stop('FAILED',why) end
            end
            farm.phase='PRODUCING';farm.phase_ms=now
        end
    end
    function api.Tick(now)
        -- Advance ready phases within this frame. Re-read scope/inventory at
        -- every boundary, and never observe settlement twice in one timestamp.
        local ok,result=pcall(function()
            for _=1,8 do
                local before=farm and farm.phase
                local cycles=farm and farm.cycles
                tick(now)
                if not farm or not farm.active or farm.phase==before then break end
                if farm.cycles~=cycles and farm.phase~='COOLDOWN' then break end
            end
        end)
        if not ok then return stop('FAILED','MC Auto Farm stopped: '..tostring(result)) end
        if farm and farm.active and type(host.Report)=='function' then
            local reason=farm.wait_reason or ('stock=%s/%s supplies=%s'):format(tostring(farm.last_stock),
                tostring(farm.capacity or 'full'),tostring(farm.last_supplies))
            local report_reason=farm.wait_reason or ''
            if farm.report_phase~=farm.phase or farm.report_reason~=report_reason or now-(farm.report_ms or now)>=5000 then
                farm.report_phase,farm.report_reason,farm.report_ms=farm.phase,report_reason,now
                pcall(host.Report,farm.phase,reason)
            end
        end
        return result
    end
    function api.Stop(why)return stop('STOPPED',why or 'Stopped by user.') end
    -- Internal manager handshake: never resolve a deferred request to a new cycle.
    function api.CaptureFinishCycle()return farm and farm.active and farm or nil end
    function api.FinishCycle(expected)
        if not farm or farm~=expected or not farm.active then return false end
        farm.repeat_mode=false
        if farm.phase=='COOLDOWN' then farm.active=false;farm.phase='COMPLETED' end
        return true
    end
    function api.Snapshot()
        if not farm then return {active=false,phase='IDLE',cycles=0} end
        local out={};for k,v in pairs(farm) do if type(v)~='table' then out[k]=v end end;return out
    end
    return api
end

