        {name="physical_accept",original="2D 00 02 00 00 5D 11 38 02 56 35 00 3B 93 71 82 06 56 2D 00 50 54 01 43 B6 15 66 2C 09 00 41 2B",offset=5,replacement="2E 00 00"},
        {name="phone_close",original="2D 01 03 00 00 5D 49 41 02 56 03 00 2E 01 00 53 8B 55 56 16 00 5D E4 40 02 56 09 00 72 72 5D 70",offset=5,replacement="2E 01 00"},
        {name="phone_state",original="2D 01 03 00 00 38 00 56 3C 00 5D FE 54 02 52 A2 54 41 01 25 0A 08 2A 06 56 09 00 52 A2 54 41 01",offset=5,replacement="2E 01 00"},
