local BUNKER_APP_NATIVE={
    REQUEST_SCRIPT=0x6EB5F71AA68F2E8E,HAS_SCRIPT_LOADED=0xE6CC9F3BA0FB9EF1,
    START_NEW_SCRIPT=0xE81651AD79516E48,SET_SCRIPT_NO_LONGER_NEEDED=0xC90D2DCACD56184C,
    BEGIN_SF=0xF6E48914C7A8694E,ADD_INT=0xC3D0841A0CC546A6,ADD_FLOAT=0xD69736AAE04DB51A,
    END_SF=0xC6796A8FFA375E53,END_SF_RETURN=0xC50AA39A577AF886,
    SF_READY=0x768FF8961BA904D6,SF_GET_INT=0x2DE7EFA66B906036,
    DRAW_HIDDEN_SF=0x54972ADAF0294A93,TERMINATE_THREAD=0xC8B189ED9138BCD4,
    THREAD_ACTIVE=0x46E9AE36D8FA6417,RELEASE_SF=0x1D132D614DD86811,
}

local function bunker_app_sale_host(profile,business)
    local BUNKER_APP_SOURCE=profile or BUNKER_APP_SOURCE
    local raw=module_context and module_context.Raw or {}
    local natives,utils,locals,globals,gta=raw.Natives,raw.Utils,binding("ScriptLocal"),raw.ScriptGlobal,raw.GTA
    local core=economy()
    if not natives or type(natives.InvokeInt)~="function" or type(natives.InvokeBool)~="function"
        or type(natives.InvokeVoid)~="function" or not utils or type(utils.Joaat)~="function"
        or not locals or type(locals.GetInt)~="function" or type(locals.SetInt)~="function"
        or not globals or type(globals.GetInt)~="function" or type(globals.SetInt)~="function"
        or not gta or type(gta.GetLocalPlayerId)~="function" or not core then
        return nil,"Bunker app driver APIs are unavailable."
    end
    local memory=raw.Memory
    if not memory or type(memory.ScanScript)~="function" or type(memory.ReadUByte)~="function"
        or type(memory.WriteUByte)~="function" then return nil,"Bunker background app memory APIs are unavailable." end
    local app_hash=utils.Joaat(BUNKER_APP_SOURCE.script)
    local gun_hash=utils.Joaat(BUNKER_APP_SOURCE.mc and "gb_biker_contraband_sell" or "gb_gunrunning")
    local host={}
    local function current_scope()
        local scope=type(core.Snapshot)=="function" and core.Snapshot() or nil
        local slot=type(core.CurrentSlot)=="function" and core.CurrentSlot() or nil
        local pok,pid=pcall(gta.GetLocalPlayerId);pid=pok and tonumber(pid) or nil
        if type(scope)~="table" or scope.account_verified~=true or scope.online~=true
            or (slot~=0 and slot~=1) or not pid or pid<0 or pid>31 then return nil end
        return {account=scope.account_id,generation=scope.generation,slot=slot,pid=math.floor(pid)}
    end
    local function same_scope(token)
        local scope=current_scope()
        return scope and token and scope.account==token.account and scope.generation==token.generation
            and scope.slot==token.slot and scope.pid==token.pid or false
    end
    local function threads(hash)
        local ok,v=pcall(natives.InvokeInt,THREAD_COUNT_HASH,hash);v=ok and tonumber(v) or nil
        return v and math.max(0,math.floor(v)) or nil
    end
    local function app_loaded()
        local ok,value=pcall(natives.InvokeBool,BUNKER_APP_NATIVE.HAS_SCRIPT_LOADED,BUNKER_APP_SOURCE.script)
        return ok and value or (ok and false or nil)
    end
    local terminated_owned_thread=false
    local quiet=Module.NewBunkerQuietApp({
        Loaded=app_loaded,Threads=function()
            local count=threads(app_hash)
            return terminated_owned_thread and count==1 and 0 or count
        end,
        Scan=function(pattern)return memory.ScanScript(app_hash,pattern) end,
        Read=memory.ReadUByte,Write=memory.WriteUByte,
    },BUNKER_APP_SOURCE.quiet_patches)
    local function release_quiet()
        if not quiet.Pending() then return true end
        local ok,why=quiet.Restore()
        if ok then pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.SET_SCRIPT_NO_LONGER_NEEDED,BUNKER_APP_SOURCE.script) end
        return ok,why
    end
    local function app_local(index)
        local ok,v=pcall(locals.GetInt,app_hash,index);v=ok and tonumber(v) or nil
        return v and math.floor(v) or nil
    end
    local function set_app_local(index,value)
        local ok,result=pcall(locals.SetInt,app_hash,index,value)
        if not ok or result==false then return false end
        return app_local(index)==value
    end
    local function sf_begin(handle,name)
        local ok,v=pcall(natives.InvokeBool,BUNKER_APP_NATIVE.BEGIN_SF,handle,name)
        return ok and v==true
    end
    local function sf_end()
        return pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.END_SF)
    end
    function host.Capture()
        local scope=current_scope();if not scope then return nil,"Verified GTA Online character context is unavailable." end
        local factory=5
        if BUNKER_APP_SOURCE.mc then
            local item=BUSINESS_BY_KEY[business]
            if not item or not item.factory_ids then return nil,"Unsupported MC business." end
            factory=nil
            for i=0,4 do
                local property=core.ReadStat(core.QualifyStat(scope.slot,"FACTORYSLOT"..i))
                for _,id in ipairs(item.factory_ids) do
                    if property==id then
                        if factory~=nil then return nil,"Duplicate MC factory assignment." end
                        factory=i
                    end
                end
            end
            if factory==nil then return nil,"MC business is not owned." end
        end
        local owned=type(core.ReadStat)=="function" and type(core.QualifyStat)=="function"
            and core.ReadStat(core.QualifyStat(scope.slot,"FACTORYSLOT"..factory)) or nil
        local stock=type(core.ReadStat)=="function" and type(core.QualifyStat)=="function"
            and core.ReadStat(core.QualifyStat(scope.slot,"PRODTOTALFORFACTORY"..factory)) or nil
        if not tonumber(owned) or tonumber(owned)<=0 then return nil,"Bunker ownership is not verified." end
        if not tonumber(stock) or tonumber(stock)<=0 then return nil,"Bunker has no stock to sell." end
        if threads(gun_hash) and threads(gun_hash)>0 then return nil,"A Bunker sell mission is already active." end
        local roster_ok,header=pcall(globals.GetInt,1893070)
        local boss_ok,boss=pcall(globals.GetInt,1893070+1+scope.pid*615+10)
        if not roster_ok or tonumber(header)~=32 or not boss_ok or tonumber(boss)~=scope.pid then
            return nil,"Register as a CEO/MC boss before starting Bunker Auto Farm."
        end
        if BUNKER_APP_SOURCE.mc then
            -- Collected appBikerBusiness bytecode: sale eligibility 0xD01 ->
            -- 0xA41A -> 0x3785 -> 0x3794(player,1). Requires local ownership
            -- AND roster.f_10.f_433==1, matching Session's MC type contract.
            local type_index=1893070+1+scope.pid*615+10+433
            local type_ok,boss_type=pcall(globals.GetInt,type_index)
            if not type_ok or boss_type~=1 then
                return nil,"Register as an MC President before starting an MC sale (organization type "..tostring(type_ok and boss_type or "unreadable")..")."
            end
        end
        local browser_ok,browser=pcall(globals.GetInt,BUNKER_APP_SOURCE.browser_global)
        if not browser_ok or tonumber(browser)~=0 then return nil,"Close the existing in-game computer before background farming." end
        local other_app=utils.Joaat(BUNKER_APP_SOURCE.mc and "appBunkerBusiness" or "appBikerBusiness")
        if threads(other_app)~=0 then return nil,"Close the other business laptop first." end
        if BUNKER_APP_SOURCE.mc then
            for _,name in ipairs({"gb_gunrunning","gb_smuggler"}) do
                if threads(utils.Joaat(name))~=0 then return nil,"Finish the current business sale first." end
            end
        end
        local app_threads=threads(app_hash)
        if app_threads~=0 then return nil,"Close the existing Bunker laptop before starting background farming." end
        local released,why=release_quiet();if not released then return nil,why end
        return {account=scope.account,generation=scope.generation,slot=scope.slot,pid=scope.pid,
            factory=factory,property=owned,app_preexisting=app_threads>0,app_started=false}
    end
    function host.Valid(token)return same_scope(token) end
    function host.EnsureApp(token)
        if not same_scope(token) then return false,"Character context changed before Bunker app start." end
        local count=threads(app_hash)
        if count==1 then
            return token.app_started==true and quiet.Pending(),"Existing Bunker app is not owned by this background launch."
        end
        if count and count>1 then return false,"Multiple Bunker app threads are active." end
        pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.REQUEST_SCRIPT,BUNKER_APP_SOURCE.script)
        local loaded_ok,loaded=pcall(natives.InvokeBool,BUNKER_APP_NATIVE.HAS_SCRIPT_LOADED,BUNKER_APP_SOURCE.script)
        if not loaded_ok then return false,"Bunker app load-state query failed." end
        if loaded~=true then return true,"loading" end
        local patched,patch_err=quiet.Apply()
        if not patched then return false,patch_err end
        local start_ok,thread=pcall(natives.InvokeInt,BUNKER_APP_NATIVE.START_NEW_SCRIPT,BUNKER_APP_SOURCE.script,BUNKER_APP_SOURCE.stack_size)
        thread=start_ok and tonumber(thread) or 0
        if not thread or thread<=0 then release_quiet();return false,"Bunker app script start was rejected." end
        token.app_started=true;token.app_thread=math.floor(thread)
        -- Hold this script resource until its owned thread exits and edits restore.
        return true,"started"
    end
    function host.Read(token)
        if not same_scope(token) then return nil,"Character context changed." end
        local count=threads(app_hash);if count==nil then return nil,"Bunker app thread state unavailable." end
        local controller=threads(gun_hash) or 0
        if count==0 then return {threads=0,controller_threads=controller,page=nil,stage=nil,scaleform=nil,overlay=false} end
        if count~=1 then return nil,"Multiple Bunker app threads are active." end
        if BUNKER_APP_SOURCE.mc then
            local handle,command,property,stage,overlay,quote=app_local(728),app_local(551),app_local(557),app_local(552),app_local(547),app_local(553)
            if handle==nil or command==nil or property==nil or stage==nil or overlay==nil or quote==nil then
                return nil,"MC app state is unreadable."
            end
            if command < -1 or command>2 or property<0 or property>32 or (overlay~=0 and overlay~=1) then
                return nil,"MC app layout does not match this build."
            end
            if handle>0 then
                local ok,loaded=pcall(natives.InvokeBool,0x85F01B8D5B90570E,handle)
                if not ok or not loaded then handle=0 end
            end
            return {threads=count,scaleform=handle,command=command,property=property,stage=stage,overlay=overlay==1,quote=quote}
        end
        local flags,page,stage,scaleform=app_local(BUNKER_APP_SOURCE.flags_local),app_local(BUNKER_APP_SOURCE.page_local),
            app_local(BUNKER_APP_SOURCE.stage_local),app_local(BUNKER_APP_SOURCE.scaleform_local)
        if flags==nil or page==nil or stage==nil or scaleform==nil then return nil,"Bunker app locals are unavailable." end
        if page<0 or page>7 or stage<0 or stage>15 then return nil,"Bunker app local layout does not match this build." end
        return {threads=count,controller_threads=controller,flags=flags,page=page,stage=stage,scaleform=scaleform,
            overlay=(flags & 2)~=0}
    end
    function host.BindBusiness(token)
        if not same_scope(token) or not BUNKER_APP_SOURCE.mc then return false,"MC context changed." end
        if not set_app_local(557,token.property) or not set_app_local(555,-1) or not set_app_local(553,-1) then
            return false,"MC selected business did not verify."
        end
        return true
    end
    function host.Dispatch(token,command)
        if not same_scope(token) or not BUNKER_APP_SOURCE.mc or (command~=1 and command~=2)
            or app_local(557)~=token.property or app_local(551)~=-1 then return false,"MC app command is not ready." end
        return set_app_local(551,command),"MC app command did not verify."
    end
    function host.ShowSellPage(token,state)
        state=state or host.Read(token)
        if type(state)~="table" or state.threads~=1 or not state.scaleform or state.scaleform<=0 then
            return false,"Bunker app is not ready for Sell-page navigation."
        end
        if not set_app_local(BUNKER_APP_SOURCE.page_local,BUNKER_APP_SOURCE.page_sell) then
            return false,"Bunker app Sell-page local write did not verify."
        end
        if not sf_begin(state.scaleform,"SHOW_SCREEN") then return false,"Bunker Sell-page scaleform call was rejected." end
        pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.ADD_INT,BUNKER_APP_SOURCE.page_sell)
        sf_end()
        return true
    end
    function host.QuerySelection(token,state)
        state=state or host.Read(token)
        if type(state)~="table" or not state.scaleform or state.scaleform<=0 then return nil,"Bunker scaleform unavailable." end
        if not sf_begin(state.scaleform,"GET_CURRENT_SELECTION") then return nil,"Bunker selection query was rejected." end
        local ok,handle=pcall(natives.InvokeInt,BUNKER_APP_NATIVE.END_SF_RETURN)
        handle=ok and tonumber(handle) or nil
        if not handle or handle<0 then return nil,"Bunker selection return handle is invalid." end
        return math.floor(handle)
    end
    function host.ReadSelection(token,handle)
        if not same_scope(token) then return nil,false,"Character context changed." end
        local ok,ready=pcall(natives.InvokeBool,BUNKER_APP_NATIVE.SF_READY,handle)
        if not ok then return nil,false,"Bunker selection readiness query failed." end
        if ready~=true then return nil,false,nil end
        local rok,value=pcall(natives.InvokeInt,BUNKER_APP_NATIVE.SF_GET_INT,handle)
        value=rok and tonumber(value) or nil
        if not value or value%1~=0 then return nil,false,"Bunker selection result is invalid." end
        return math.floor(value),true,nil
    end
    function host.SelectCity(token,state)
        state=state or host.Read(token)
        if type(state)~="table" or not state.scaleform or state.scaleform<=0 then return false,"Bunker scaleform unavailable." end
        if state.page~=7 or state.overlay then return false,"Bunker Sell page is not ready for selection." end
        -- GET_CURRENT_SELECTION latches an activated Scaleform button, not hover.
        -- Coordinates belong only to the hidden movie; the player's cursor is untouched.
        if not sf_begin(state.scaleform,"SET_MOUSE_INPUT") then return false,"Bunker cursor input was rejected." end
        pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.ADD_FLOAT,0.48)
        pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.ADD_FLOAT,0.72)
        sf_end()
        if not sf_begin(state.scaleform,"SET_INPUT_EVENT") then return false,"Bunker selection input was rejected." end
        pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.ADD_FLOAT,201.0)
        sf_end()
        return true
    end
    function host.SelectConfirm(token,state)
        state=state or host.Read(token)
        if type(state)~="table" or not state.overlay or (state.stage~=5 and state.stage~=2) then
            return false,"Bunker confirmation overlay is not ready."
        end
        local x,y=state.stage==5 and 0.50 or 0.57,0.57
        if not sf_begin(state.scaleform,"SET_MOUSE_INPUT") then return false,"Bunker confirmation cursor input was rejected." end
        pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.ADD_FLOAT,x)
        pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.ADD_FLOAT,y)
        sf_end()
        if not sf_begin(state.scaleform,"SET_INPUT_EVENT") then return false,"Bunker confirmation selection was rejected." end
        pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.ADD_FLOAT,201.0)
        sf_end()
        return true
    end
    function host.PulseAccept(token,state)
        if not same_scope(token) then return false,"Character context changed." end
        state=state or host.Read(token)
        if type(state)~="table" or state.threads~=1 or (state.flags & 1)~=0 then
            return false,"Bunker app selection dispatch is already pending."
        end
        -- Reproduce func_574's result handles, rather than synthesizing a PAD edge.
        -- func_11 waits for both responses and owns all validation/transactions.
        local selection,why=host.QuerySelection(token,state)
        if not selection then return false,why end
        if not sf_begin(state.scaleform,"GET_CURRENT_SCREEN_ID") then return false,"Bunker screen query was rejected." end
        local ok,screen=pcall(natives.InvokeInt,BUNKER_APP_NATIVE.END_SF_RETURN)
        screen=ok and tonumber(screen) or nil
        if not screen or screen<0 or screen%1~=0 then return false,"Bunker screen return handle is invalid." end
        if not set_app_local(BUNKER_APP_SOURCE.selection_local,selection)
            or not set_app_local(BUNKER_APP_SOURCE.screen_local,screen)
            or not set_app_local(BUNKER_APP_SOURCE.flags_local,state.flags | 1) then
            return false,"Bunker app selection dispatch did not verify."
        end
        return true
    end
    function host.Maintain(token)
        if quiet.Pending() and threads(app_hash)==0 then return release_quiet() end
        return true
    end
    function host.PumpQuiet(token)
        if not token or not token.app_started or token.app_closed or threads(app_hash)~=1 then return true end
        local handle=app_local(BUNKER_APP_SOURCE.scaleform_local)
        if handle and handle>0 then
            -- Keep the movie timeline/return queue advancing outside the viewport.
            local ok=pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.DRAW_HIDDEN_SF,handle,-10.0,-10.0,0.001,0.001,0,0,0,0,0)
            if not ok then return false,"Bunker hidden movie update failed." end
        end
        return true
    end
    function host.ControllerReady(token)
        return same_scope(token) and threads(gun_hash)==1 or false
    end
    function host.Cleanup(token)
        if not token or not token.app_started then return host.Maintain(token) end
        if token.app_preexisting or token.app_closed then return host.Maintain(token) end
        local count=threads(app_hash)
        if count==0 then token.app_closed=true;return host.Maintain(token) end
        if count~=1 or not token.app_thread then return false,"Bunker owned-app cleanup could not verify its thread." end
        local ok,live=pcall(natives.InvokeBool,BUNKER_APP_NATIVE.THREAD_ACTIVE,token.app_thread)
        if not ok or live~=true then return false,"Bunker owned-app cleanup lost thread ownership." end
        local handle=app_local(BUNKER_APP_SOURCE.scaleform_local)
        -- The app has registered the sale before ControllerReady. Close only the
        -- launcher now, keeping gb_gunrunning and the player's live controls intact.
        if not BUNKER_APP_SOURCE.mc then pcall(globals.SetInt,BUNKER_APP_SOURCE.browser_global,0) end
        pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.TERMINATE_THREAD,token.app_thread)
        local check,still_live=pcall(natives.InvokeBool,BUNKER_APP_NATIVE.THREAD_ACTIVE,token.app_thread)
        if not check or still_live~=false then return false,"Bunker owned-app termination did not verify." end
        token.app_closed=true;terminated_owned_thread=true
        if handle and handle>0 and type(memory.AllocInt)=="function"
            and type(memory.WriteInt)=="function" and type(memory.Free)=="function" then
            local allocated,ptr=pcall(memory.AllocInt)
            if allocated and ptr and ptr>0 then
                pcall(memory.WriteInt,ptr,handle)
                pcall(natives.InvokeVoid,BUNKER_APP_NATIVE.RELEASE_SF,ptr)
                pcall(memory.Free,ptr)
            end
        end
        local restored,why=release_quiet()
        terminated_owned_thread=false
        return restored,why
    end
    function host.Shutdown(token)return host.Cleanup(token) end
    return host
end

local function get_bunker_app_engine()
    if bunker_app_engine then return bunker_app_engine end
    local host,why=bunker_app_sale_host()
    if not host then return nil,why end
    bunker_app_engine=Module.NewBunkerAppSale(host)
    return bunker_app_engine
end

local function start_bunker_app_sale()
    local engine,why=get_bunker_app_engine();if not engine then return false,why end
    local now=State and tonumber(State.clock_ms) or 0
    if not now or now<=0 then
        local time=binding("Time")
        if time and type(time.GetEpocheMs)=="function" then
            local called,value=pcall(time.GetEpocheMs);if called then now=tonumber(value) or 0 end
        end
    end
    local ok,row=engine.Start(now or 0)
    if not ok then return false,row end
    return true,"Bunker Disruption Logistics sale start armed for Los Santos."
end

local function bunker_app_sale_snapshot()
    return bunker_app_engine and bunker_app_engine.Snapshot() or {phase="IDLE",ok=nil}
end

local function tick_bunker_app_sale(now)
    if not bunker_app_engine then return end
    local before=bunker_app_engine.Snapshot()
    local row=bunker_app_engine.Tick(now)
    if type(row)~="table" or row.phase==before.phase then return end
    if row.phase=="STARTED" then
        State.last_action={ok=true,key="start_bunker_app_sale",detail="Bunker sale controller started through Disruption Logistics."}
    elseif row.phase=="FAILED" then
        State.last_action={ok=false,key="start_bunker_app_sale",detail=tostring(row.reason or "Bunker app sale failed.")}
    end
end

local BUNKER_START_SOURCE = {
    mission = 226, event = 1613825825, los_santos = 0, blaine_county = 1,
    roster_base = 1893070, roster_stride = 615, roster_root = 10,
    request_field = 33, active_field = 34, route_field = 216,
    bunker_busy_base = 1673828, bunker_slot = 5,
    context348 = 2733326 + 3989 + 348,
    context349 = 2733326 + 3989 + 349,
    context350 = 2733326 + 3989 + 350,
    mission_hash_global = 4516967,
    sell_name = "IG_SELL_0_t0_v0",
    mission_stat_name = "MP_STAT_MISSIONFORFACTORY5_v0",
    category_name = "CATEGORY_INVENTORY_CONTRABAND_MISSION",
    basket_action = -1018905335, basket_flags = 4,
}

local BUNKER_NETSHOP = {
    USE=0x7D2708796355B20B, VALID=0xB24F0944DA203D9E, REFRESH=0x810E8431C0614BF9,
    CATALOG=0x2B949A1E6AEC8F6A, BASKET_ACTIVE=0xA65568121DF2EA26,
    TX_PROGRESS=0x613F125BA3BD2EB9, BASKET_START=0x279F08B1A4B29B7E,
    BASKET_END=0xFA336E7F40C0A0D0, ADD=0xF30980718C8ED876,
    APPLY=0xE1A0450ED46A7812, CHECKOUT=0x39BE7CEA8D9CC8E6,
    PENDING=0x4B64CD6D18474126,
}
local NETWORK_IS_PLAYER_ACTIVE=0xB8DFD30D6973E135

local function bunker_sale_source_host()
    local globals,natives,gta,memory,utils=binding("ScriptGlobal"),binding("Natives"),binding("GTA"),binding("Memory"),binding("Utils")
    local core=economy()
    if not globals or type(globals.GetInt)~="function" or type(globals.SetInt)~="function"
        or type(globals.AreValid)~="function" or not natives or type(natives.InvokeBool)~="function"
        or type(natives.InvokeInt)~="function" or not gta or type(gta.GetLocalPlayerId)~="function"
        or type(gta.TriggerScriptEvent)~="function" or not memory or type(memory.AllocInt)~="function"
        or type(memory.Alloc)~="function" or type(memory.WriteInt)~="function" or type(memory.ReadInt)~="function"
        or type(memory.Free)~="function" or not utils or type(utils.Joaat)~="function" or not core then
        return nil,"Direct Bunker sale APIs are unavailable."
    end
    local host={}
    local function integer(v,lo,hi)return type(v)=="number" and v==v and v%1==0 and v>=lo and v<=hi end
    local function hash(name)
        local ok,v=pcall(utils.Joaat,name);v=ok and tonumber(v) or nil
        if not integer(v,-2147483648,4294967295) then return nil end
        v=math.floor(v)%4294967296
        if v>=2147483648 then v=v-4294967296 end
        return v
    end
    local function get(index)
        local ok,v=pcall(globals.GetInt,index);v=ok and tonumber(v) or nil
        return integer(v,-2147483648,2147483647) and math.floor(v) or nil
    end
    local function set(index,value)
        local ok,result=pcall(globals.SetInt,index,value)
        if not ok or result==false then return false end
        return get(index)==value
    end
    local function native_bool(id,...)
        local ok,v=pcall(natives.InvokeBool,id,...);return ok and v==true
    end
    local function stat(slot,key)
        if type(core.ReadStat)~="function" or type(core.QualifyStat)~="function" then return nil end
        local ok,name=pcall(core.QualifyStat,slot,key);if not ok then return nil end
        local rok,value=pcall(core.ReadStat,name)
        return rok and tonumber(value) or nil
    end
    local function current_scope()
        local scope=type(core.Snapshot)=="function" and core.Snapshot() or nil
        local slot=type(core.CurrentSlot)=="function" and core.CurrentSlot() or nil
        local pid_ok,pid=pcall(gta.GetLocalPlayerId);pid=pid_ok and tonumber(pid) or nil
        if type(scope)~="table" or scope.account_verified~=true or scope.online~=true
            or (slot~=0 and slot~=1) or not integer(pid,0,31) then return nil end
        return {account=scope.account_id,generation=scope.generation,slot=slot,pid=math.floor(pid)}
    end
    local function same_scope(token)
        local scope=current_scope()
        return scope and token and scope.account==token.account and scope.generation==token.generation
            and scope.slot==token.slot and scope.pid==token.pid or false
    end
    local function roster_index(pid,field)
        return BUNKER_START_SOURCE.roster_base+1+pid*BUNKER_START_SOURCE.roster_stride
            +BUNKER_START_SOURCE.roster_root+field
    end
    function host.Capture(route)
        if globals.AreValid()~=true then return nil,"Script globals are unavailable." end
        local scope=current_scope();if not scope then return nil,"Verified GTA Online character context is unavailable." end
        if get(BUNKER_START_SOURCE.roster_base)~=32 then return nil,"Freemode player-state layout does not match this build." end
        local boss_index=roster_index(scope.pid,0)
        if get(boss_index)~=scope.pid then return nil,"Register as a CEO/MC boss before starting a Bunker sale." end
        local request_index=roster_index(scope.pid,BUNKER_START_SOURCE.request_field)
        local active_index=roster_index(scope.pid,BUNKER_START_SOURCE.active_field)
        local route_index=roster_index(scope.pid,BUNKER_START_SOURCE.route_field)
        local request_before,active_before,route_before=get(request_index),get(active_index),get(route_index)
        if request_before~=-1 or active_before~=-1 then return nil,"Another freemode mission request is already active." end
        local busy_index=BUNKER_START_SOURCE.bunker_busy_base+1+BUNKER_START_SOURCE.bunker_slot
        if get(busy_index)~=0 then return nil,"Bunker resupply/production delivery state is busy." end
        for _,profile in ipairs(ACTIVE_SALE_PROFILES) do
            local h,hash_err=script_hash(profile.script)
            if not h then return nil,hash_err or "Supported sale script hash is unavailable." end
            local threads,thread_err=script_thread_count(h)
            if threads==nil then return nil,thread_err or "Supported sale script state is unavailable." end
            if threads>0 then return nil,"A supported sell mission is already active." end
        end
        local owned,stock=stat(scope.slot,"FACTORYSLOT5"),stat(scope.slot,"PRODTOTALFORFACTORY5")
        if not integer(owned,1,1000) then return nil,"Bunker ownership is not verified." end
        if not integer(stock,1,1000) then return nil,"Bunker has no verified stock to sell." end
        local ok,freemode_host=pcall(natives.InvokeInt,NETWORK_GET_HOST_OF_SCRIPT,"freemode",-1,0)
        freemode_host=ok and tonumber(freemode_host) or nil
        if not integer(freemode_host,0,31) then return nil,"Freemode script host is unavailable." end
        local mission_hash,mission_stat_hash=hash(BUNKER_START_SOURCE.sell_name),hash(BUNKER_START_SOURCE.mission_stat_name)
        local category_hash=hash(BUNKER_START_SOURCE.category_name)
        if not mission_hash or not mission_stat_hash or not category_hash then return nil,"Bunker sale transaction hashes are unavailable." end
        return {
            account=scope.account,generation=scope.generation,slot=scope.slot,pid=scope.pid,route=route,
            request_index=request_index,active_index=active_index,route_index=route_index,busy_index=busy_index,
            request_before=request_before,active_before=active_before,route_before=route_before,
            mission_hash=mission_hash,mission_stat_hash=mission_stat_hash,category_hash=category_hash,
            mission_hash_before=get(BUNKER_START_SOURCE.mission_hash_global),stock_before=stock,
        }
    end
    function host.Valid(token)
        if not same_scope(token) or globals.AreValid()~=true then return false end
        if token.request_armed then return true end
        return get(token.request_index)==token.request_before and get(token.active_index)==token.active_before
            and get(token.busy_index)==0
    end
    local function free(pointer)
        if pointer and pointer~=0 then pcall(memory.Free,pointer) end
    end
    local function end_basket()
        if native_bool(BUNKER_NETSHOP.BASKET_ACTIVE) then pcall(natives.InvokeBool,BUNKER_NETSHOP.BASKET_END) end
    end
    -- Current Enhanced decomp exposes Global_4515492[i /*84*/], while
    -- Rockstar source declares g_cashTransactionData[SHOPPING_TRANSACTION_MAX_NUMBER+1].
    -- The VM array header therefore contains 16, although usable script slots are 0..14.
    local CASH_TX_BASE,CASH_TX_HEADER_COUNT,CASH_TX_SLOTS,CASH_TX_STRIDE=4515492,16,15,84
    local CASH_TX_DATA=65
    local CASH_TX_STATUS=CASH_TX_DATA+2
    local CASH_TX_IS_BASKET=CASH_TX_DATA+5
    local CASH_TX_TRIGGER=4516963
    local GET_FRAME_COUNT=0xFC8202EFC642E6F2
    local function tx_base(slot)return CASH_TX_BASE+1+slot*CASH_TX_STRIDE end
    local function tx_index(slot,field)return tx_base(slot)+field end
    local function tx_snapshot(slot)
        local row={}
        for off=0,CASH_TX_STRIDE-1 do
            local value=get(tx_base(slot)+off)
            if value==nil then return nil end
            row[off]=value
        end
        return row
    end
    local function tx_restore(token)
        local slot=token and token.transaction_slot
        local row=token and token.transaction_baseline
        if not integer(slot,0,CASH_TX_SLOTS-1) or type(row)~="table" then return end
        local txid=get(tx_index(slot,CASH_TX_DATA))
        local status=get(tx_index(slot,CASH_TX_STATUS))
        if txid~=token.transaction_id and status~=0 then return end
        for off=0,CASH_TX_STRIDE-1 do
            local value=row[off]
            if value~=nil then pcall(globals.SetInt,tx_base(slot)+off,value) end
        end
        if token.tx_trigger_before~=nil and get(CASH_TX_TRIGGER)==1 then
            pcall(globals.SetInt,CASH_TX_TRIGGER,token.tx_trigger_before)
        end
        token.transaction_restored=true
    end
    local function tx_finish(token)
        if not token or token.transaction_finished then return end
        token.transaction_finished=true
        if native_bool(BUNKER_NETSHOP.BASKET_ACTIVE) then end_basket() end
        tx_restore(token)
    end
    function host.BeginRegistration(token)
        if not same_scope(token) then return false,"Character context changed before sale registration." end
        if native_bool(BUNKER_NETSHOP.USE)~=true then return false,"Rockstar transaction system is unavailable." end
        if native_bool(BUNKER_NETSHOP.VALID,token.slot)~=true then return false,"Rockstar transaction session is invalid." end
        if native_bool(BUNKER_NETSHOP.REFRESH)==true then return false,"Rockstar transaction refresh is pending." end
        if native_bool(BUNKER_NETSHOP.CATALOG)~=true then return false,"Rockstar transaction catalog is unavailable." end
        if native_bool(BUNKER_NETSHOP.TX_PROGRESS)==true then return false,"Another Rockstar transaction is active." end
        if get(CASH_TX_BASE)~=CASH_TX_HEADER_COUNT then return false,"Rockstar cash-transaction array layout does not match this build." end

        local slot
        for i=0,CASH_TX_SLOTS-1 do
            local status=get(tx_index(i,CASH_TX_STATUS))
            local basket=get(tx_index(i,CASH_TX_IS_BASKET))
            if status==nil or basket==nil then return false,"Rockstar cash-transaction state is unavailable." end
            if status~=0 and basket==1 then return false,"Another Rockstar basket transaction is active." end
            if slot==nil and status==0 then slot=i end
        end
        if slot==nil then return false,"No Rockstar cash-transaction slot is free." end
        if native_bool(BUNKER_NETSHOP.BASKET_ACTIVE)==true then
            return false,"Rockstar reports an active basket outside the tracked transaction array."
        end

        local baseline=tx_snapshot(slot)
        if not baseline then return false,"Could not snapshot the Rockstar cash-transaction slot." end
        local tok_ok,tx_ptr=pcall(memory.AllocInt);tx_ptr=tok_ok and tonumber(tx_ptr) or 0
        local item_ok,item_ptr=pcall(memory.Alloc,16);item_ptr=item_ok and tonumber(item_ptr) or 0
        if tx_ptr==0 or item_ptr==0 then free(tx_ptr);free(item_ptr);return false,"Bunker sale transaction allocation failed." end
        pcall(memory.WriteInt,tx_ptr,0)
        local started=native_bool(BUNKER_NETSHOP.BASKET_START,tx_ptr,token.category_hash,
            BUNKER_START_SOURCE.basket_action,BUNKER_START_SOURCE.basket_flags)
        if not started then free(tx_ptr);free(item_ptr);return false,"Bunker sale basket start was rejected." end
        local rid,txid=pcall(memory.ReadInt,tx_ptr);txid=rid and tonumber(txid) or nil
        if not integer(txid,0,2147483647) then end_basket();free(tx_ptr);free(item_ptr);return false,"Bunker sale transaction id is invalid." end

        token.transaction_id=txid
        token.transaction_slot=slot
        token.transaction_baseline=baseline
        token.tx_trigger_before=get(CASH_TX_TRIGGER)

        local service_invalid=hash("SERVICE_INVALID")
        if not service_invalid then end_basket();free(tx_ptr);free(item_ptr);tx_restore(token);return false,"SERVICE_INVALID hash unavailable." end
        local frame_ok,frame=pcall(natives.InvokeInt,GET_FRAME_COUNT);frame=frame_ok and tonumber(frame) or 0
        local writes={
            [CASH_TX_DATA]=txid,
            [CASH_TX_DATA+1]=0,
            [CASH_TX_STATUS]=1,
            [CASH_TX_DATA+3]=78225582,
            [CASH_TX_DATA+4]=service_invalid,
            [CASH_TX_IS_BASKET]=1,
            [CASH_TX_DATA+6]=token.category_hash,
            [CASH_TX_DATA+7]=BUNKER_START_SOURCE.basket_action,
            [CASH_TX_DATA+10]=BUNKER_START_SOURCE.basket_flags,
            [CASH_TX_DATA+11]=3,
            [CASH_TX_DATA+12]=0,
            [CASH_TX_DATA+13]=0,
            [CASH_TX_DATA+14]=math.floor(frame or 0),
            [CASH_TX_DATA+18]=0,
        }
        for field,value in pairs(writes) do
            if not set(tx_index(slot,field),value) then
                end_basket();free(tx_ptr);free(item_ptr);tx_restore(token)
                return false,"Rockstar cash-transaction slot write did not verify."
            end
        end
        pcall(globals.SetInt,CASH_TX_TRIGGER,0)

        local values={token.mission_stat_hash,token.mission_hash,0,1}
        for i=1,4 do
            local wrote=pcall(memory.WriteInt,item_ptr+(i-1)*4,values[i])
            if not wrote then end_basket();free(tx_ptr);free(item_ptr);tx_restore(token);return false,"Bunker sale item-data write failed." end
        end
        -- Match current Enhanced's func_408 cache. For an inventory category,
        -- f_15 is the inventory/stat key and f_16 is the catalogue mission key.
        pcall(globals.SetInt,tx_index(slot,CASH_TX_DATA+15),token.mission_stat_hash)
        pcall(globals.SetInt,tx_index(slot,CASH_TX_DATA+16),token.mission_hash)
        if native_bool(BUNKER_NETSHOP.ADD,item_ptr,1)~=true then
            end_basket();free(tx_ptr);free(item_ptr);tx_restore(token);return false,"Bunker sale mission item was rejected."
        end
        free(tx_ptr);free(item_ptr)

        -- Enhanced 1.73's cash manager does not directly call CHECKOUT_START here.
        -- It marks the tracked slot ready and sends SCRIPT_EVENT_REQUEST_CASH_TRANSACTION
        -- (-710178565) to the local player. The normal transaction event handler then
        -- performs checkout, applies server data, and updates f_65.f_2 to SUCCESS/FAIL.
        pcall(globals.SetInt,tx_index(slot,CASH_TX_DATA+13),1)
        pcall(globals.SetInt,tx_index(slot,CASH_TX_DATA+12),0)
        pcall(globals.SetInt,tx_index(slot,CASH_TX_DATA+14),math.floor(frame or 0))
        pcall(globals.SetInt,tx_index(slot,CASH_TX_DATA+18),0)
        local cash_event={-710178565,token.pid,0}
        for field=0,18 do
            cash_event[#cash_event+1]=get(tx_index(slot,CASH_TX_DATA+field)) or 0
        end
        while #cash_event<35 do cash_event[#cash_event+1]=0 end
        cash_event[36]=slot
        local event_ok,event_result=pcall(gta.TriggerScriptEvent,1<<token.pid,cash_event)
        if not event_ok or event_result==false then
            end_basket();tx_restore(token)
            return false,tostring(event_result or "Rockstar cash-transaction script event was rejected.")
        end
        token.cash_event=cash_event
        pcall(globals.SetInt,CASH_TX_TRIGGER,1)
        return true,txid
    end
    function host.RegistrationState(token,txid)
        if not same_scope(token) then return "failed","Character context changed during sale registration." end
        local mission=stat(token.slot,"MISSIONFORFACTORY5")
        local status=get(tx_index(token.transaction_slot,CASH_TX_STATUS))
        if mission==token.mission_hash and status==2 then
            tx_finish(token)
            return "success","Rockstar sale mission registration verified by the native cash-transaction manager."
        end
        if status==1 then return "pending","Rockstar Bunker mission registration is pending." end
        if status==2 then
            return "pending","Rockstar transaction succeeded; waiting for MISSIONFORFACTORY5 inventory readback."
        end
        if status==0 and mission==token.mission_hash then
            tx_finish(token)
            return "success","Rockstar sale mission registration verified."
        end
        if status~=nil and status~=0 then
            local event_code=get(tx_index(token.transaction_slot,CASH_TX_DATA+17))
            token.transaction_status=status
            token.transaction_event_code=event_code
            tx_finish(token)
            return "failed",("Rockstar Bunker mission registration failed with transaction status %s, result code %s.")
                :format(tostring(status),tostring(event_code))
        end
        return "pending","Waiting for Rockstar Bunker mission registration reply."
    end
    function host.ArmRequest(token,route)
        if not same_scope(token) then return false,"Character context changed before freemode request." end
        if get(token.request_index)~=token.request_before or get(token.active_index)~=token.active_before
            or get(token.route_index)~=token.route_before or get(token.busy_index)~=0 then
            return false,"Freemode Bunker request fields changed before dispatch."
        end
        if not set(token.route_index,route) then return false,"Bunker destination route write did not verify." end
        if not set(BUNKER_START_SOURCE.mission_hash_global,token.mission_hash) then
            if get(token.route_index)==route then set(token.route_index,token.route_before) end
            return false,"Bunker sale mission hash write did not verify."
        end
        if not set(token.request_index,BUNKER_START_SOURCE.mission) then
            if get(BUNKER_START_SOURCE.mission_hash_global)==token.mission_hash then
                set(BUNKER_START_SOURCE.mission_hash_global,token.mission_hash_before or 0)
            end
            if get(token.route_index)==route then set(token.route_index,token.route_before) end
            return false,"Bunker freemode mission request write did not verify."
        end
        token.request_armed=true
        return true
    end
    function host.Dispatch(token,route)
        if not same_scope(token) or get(token.request_index)~=BUNKER_START_SOURCE.mission
            or get(token.route_index)~=route then return false,"Bunker request changed before event dispatch." end
        local c348,c349,c350=get(BUNKER_START_SOURCE.context348),get(BUNKER_START_SOURCE.context349),get(BUNKER_START_SOURCE.context350)
        if c348==nil or c349==nil or c350==nil then return false,"Freemode mission context globals are unavailable." end
        -- Current Enhanced app scripts broadcast SCRIPT_EVENT_GB_BOSS_WORK_REQUEST_SERVER
        -- to every valid player, not only the freemode host. Keep the event shape exact:
        -- {type, from, reserved, mission, variation1, variation2, variation3, warehouse}.
        local player_mask=0
        for pid=0,31 do
            local ok,active=pcall(natives.InvokeBool,NETWORK_IS_PLAYER_ACTIVE,pid)
            if ok and active==true then player_mask=player_mask | (1<<pid) end
        end
        if player_mask==0 then return false,"No active GTA Online players were available for Bunker dispatch." end
        local payload={BUNKER_START_SOURCE.event,token.pid,0,BUNKER_START_SOURCE.mission,c348,c349,c350,-1}
        local sent,result=pcall(gta.TriggerScriptEvent,player_mask,payload)
        if not sent or result==false then return false,tostring(result or "Cherax script-event dispatch failed.") end
        token.player_mask=player_mask;token.payload=payload
        return true
    end
    function host.ControllerReady(token)
        if not same_scope(token) then return false end
        local h=script_hash("gb_gunrunning");if not h then return false end
        return script_thread_count(h)==1
    end
    function host.Cleanup(token,route)
        if not token then return end
        if token.transaction_id then tx_finish(token) end
        if same_scope(token) then
            if get(token.request_index)==BUNKER_START_SOURCE.mission then set(token.request_index,token.request_before) end
            if get(token.route_index)==route then set(token.route_index,token.route_before) end
            if get(BUNKER_START_SOURCE.mission_hash_global)==token.mission_hash then
                set(BUNKER_START_SOURCE.mission_hash_global,token.mission_hash_before or 0)
            end
        end
    end
    return host
end

local function get_bunker_sale_engine()
    if bunker_sale_engine then return bunker_sale_engine end
    local host,why=bunker_sale_source_host()
    if not host then return nil,why end
    bunker_sale_engine=Module.NewBunkerSaleStart(host)
    return bunker_sale_engine
end

local function start_bunker_sale(destination)
    destination=tostring(destination or "los_santos")
    local route
    if destination=="los_santos" or destination=="los santos" or destination=="0" then
        route=BUNKER_START_SOURCE.los_santos;destination="los_santos"
    elseif destination=="blaine_county" or destination=="blaine county" or destination=="1" then
        route=BUNKER_START_SOURCE.blaine_county;destination="blaine_county"
    else
        return false,"Choose Los Santos or Blaine County."
    end
    local engine,why=get_bunker_sale_engine();if not engine then return false,why end
    local now=State and tonumber(State.clock_ms) or 0
    if not now or now<=0 then
        local time=binding("Time")
        if time and type(time.GetEpocheMs)=="function" then
            local called,value=pcall(time.GetEpocheMs);if called then now=tonumber(value) or 0 end
        end
    end
    local ok,row=engine.Start(route,now or 0)
    if not ok then return false,row end
    if State then State.bunker_sale_destination=destination end
    return true,("Direct Bunker sale registration started for %s."):format(
        destination=="los_santos" and "Los Santos" or "Blaine County")
end

local function bunker_sale_start_snapshot()
    local row=bunker_sale_engine and bunker_sale_engine.Snapshot() or {phase="IDLE",ok=nil}
    row.destination=State and State.bunker_sale_destination or nil
    return row
end

local function tick_bunker_sale_start(now)
    if not bunker_sale_engine then return end
    local before=bunker_sale_engine.Snapshot()
    local row=bunker_sale_engine.Tick(now)
    if type(row)~="table" or row.phase==before.phase then return end
    if row.phase=="STARTED" then
        State.last_action={ok=true,key="start_bunker_sale",detail="Bunker sale controller started from the direct freemode request."}
        if module_context and module_context.Notifications and type(module_context.Notifications.Success)=="function" then
            module_context.Notifications.Success("Bunker sale started.",4500)
        end
    elseif row.phase=="FAILED" then
        State.last_action={ok=false,key="start_bunker_sale",detail=tostring(row.reason or "Bunker sale start failed.")}
        if module_context and module_context.Notifications and type(module_context.Notifications.Warning)=="function" then
            module_context.Notifications.Warning(State.last_action.detail,6500)
        end
    end
end

local function mc_farm_read(business)
    local item=BUSINESS_BY_KEY[business]
    local core=economy();local raw=module_context and module_context.Raw or {}
    local g,m,u,n=raw.ScriptGlobal,raw.Memory,raw.Utils,raw.Natives
    if not item or not item.factory_ids or not core or not g or not m or not u or not n then
        return nil,'MC business APIs are unavailable.'
    end
    local scope,slot=core.Snapshot(),core.CurrentSlot()
    if not scope.account_verified or not scope.online or (slot~=0 and slot~=1) then return nil,'Enter GTA Online.' end
    local function stat(name)return tonumber(core.ReadStat(core.QualifyStat(slot,name))) end
    local factory,property
    for i=0,4 do
        local owned=stat('FACTORYSLOT'..i)
        for _,id in ipairs(item.factory_ids) do
            if owned==id then
                if factory~=nil then return nil,'Duplicate MC factory assignment.' end
                factory,property=i,owned
            end
        end
    end
    if factory==nil then return nil,'This MC business is not owned.' end
    -- Ownership + readable bounded inventory are the operational gate;
    -- FACTORYSETUP is not a positive readiness flag on this build.
    local specs={mc_cocaine={'BIKER_COCAINE_CAPACITY',280974},mc_meth={'BIKER_METH_CAPACITY',280966},
        mc_cash={'BIKER_COUNTERCASH_CAPACITY',280990},mc_weed={'BIKER_WEED_CAPACITY',280958},mc_documents={'BIKER_FAKEIDS_CAPACITY',280982}}
    local spec=specs[business];local pointer=g.GetTunableByHash(u.Joaat(spec[1]))
    if not pointer or pointer==0 or pointer~=g.GetPtr(spec[2]) then return nil,'MC stock capacity does not match this build.' end
    local capacity=tonumber(m.ReadInt(pointer))
    local stock,supplies=stat('PRODTOTALFORFACTORY'..factory),stat('MATTOTALFORFACTORY'..factory)
    local bank,wallet=tonumber(n.InvokeInt(0x76EF28DA05EA395A)),tonumber(n.InvokeInt(0xA40F9C2623F6A8B5,slot))
    if not capacity or capacity%1~=0 or capacity<1 or capacity>1000 or not stock or stock%1~=0 or stock<0 or stock>capacity
        or not supplies or supplies%1~=0 or supplies<0 or supplies>200 or not bank or not wallet then
        return nil,'MC inventory or balance is unreadable.'
    end
    return {account=scope.account_id,generation=scope.generation,slot=slot,factory=factory,property=property,
        stock=stock,supplies=supplies,capacity=capacity,balance=bank+wallet}
end

-- Read-only sale arbitration. fmmc_launcher also waits in freemode; its
-- existence is not evidence of a running sale. Source: Enhanced fmmc_launcher
-- main f_96 state switch, _IS_FMMC_ACTIVE f_185, and func_13667 launch request.
function Module.FarmSaleIdle(host)
    for _,name in ipairs({'gb_gunrunning','gb_biker_contraband_sell','gb_smuggler',
        'fm_content_smuggler_sell','fm_mission_controller','fm_mission_controller_2020',
        'appBunkerBusiness','appBikerBusiness','appsecuroserv'}) do
        if host.Count(name)~=0 then return false,'Active or unreadable sale controller/laptop: '..name end
    end
    local launcher=host.Count('fmmc_launcher')
    if launcher~=0 and launcher~=1 then return false,'Launcher thread count is unreadable or ambiguous.' end
    if host.Count('freemode')~=1 then return false,'Waiting for the freemode controller.' end
    local c,why=host.Context()
    if type(c)~='table' then return false,why or 'Sale context is unreadable.' end
    if c.online~=true or c.activity~=false or c.transition~=false or c.player_switch~=false then
        return false,'A session/activity transition is active or unreadable.'
    end
    if c.header~=32 or type(c.pid)~='number' or c.pid%1~=0 or c.pid<0 or c.pid>31 then return false,'Player roster is unreadable.' end
    -- f_96 is the launcher control-flow state, not the mission-active flag.
    -- Exact supplied Enhanced bytecode: func_9966 (0x2E3020) enters 3;
    -- func_13629 (0x452E94) services it; _IS_FMMC_ACTIVE (0x4CED) reads f_185.
    -- 3 alone must not veto an otherwise idle freemode sale. All independent
    -- mission/request/activity/transition/computer checks below remain mandatory.
    local nonblocking_phase=c.launcher_phase==2 or c.launcher_phase==3
    if c.mission~=0 or c.launch_requested~=0 or (launcher==1 and not nonblocking_phase) then
        return false,('Job launcher is busy or unreadable: mission=%s phase=%s request=%s.'):format(tostring(c.mission),tostring(c.launcher_phase),tostring(c.launch_requested))
    end
    if c.gb_request~=-1 or c.gb_current~=-1 then return false,'Another organization mission is pending or active.' end
    if c.browser~=0 or c.app~=0 or c.remote_computer~=-1 then return false,'Close the active business computer first.' end
    return true,'Freemode sale launch is ready; idle launcher retained.'
end
local function farm_sale_context()
    local raw=module_context and module_context.Raw or {}
    local g,n,gta=raw.ScriptGlobal,raw.Natives,raw.GTA
    if not g or not n or not gta then return nil,'Sale readiness APIs unavailable.' end
    local function global(i)local ok,v=pcall(g.GetInt,i);return ok and type(v)=='number' and v%1==0 and v or nil end
    local function bool(h)local ok,v=pcall(n.InvokeBool,h);if ok and type(v)=='boolean' then return v end;if ok and (v==0 or v==1) then return v==1 end end
    local ok,version=pcall(n.InvokeString,0xFCA9373EF340AC0A)
    local valid,ready=pcall(g.AreValid)
    local pok,pid=pcall(gta.GetLocalPlayerId)
    if not ok or version~='1.73' or not valid or ready~=true or not pok or type(pid)~='number' or pid%1~=0 or pid<0 or pid>31 then
        return nil,'Validated Enhanced freemode context unavailable.'
    end
    local roster=1845347+1+pid*884;local org=1893070+1+pid*615+10
    if global(1893070)~=32 then return nil,'Organization roster is unreadable.' end
    return {online=bool(0x10FAB35428CCC9D7),activity=bool(0x05095437424397FA),transition=bool(0x68049AEFF83D8F0A),
        player_switch=bool(0xD9D2CFFF49FAB35F),header=global(1845347),pid=pid,mission=global(roster+185),
        launcher_phase=global(roster+96),launch_requested=global(1574613),gb_request=global(org+33),gb_current=global(org+34),
        browser=global(77414),app=global(1574757),remote_computer=global(1971195)}
end
local farm_transactions_idle
local function farm_sales_idle()
    local idle,why=farm_transactions_idle()
    if idle~=true then return false,why end
    local automation=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
    if automation and automation.Snapshot then
        for _,key in ipairs({'bunker','acid_lab','mc_cocaine','mc_meth','mc_cash','mc_weed','mc_documents'}) do
            if automation.Snapshot(key).supply_pending then return false,'Waiting for pending business supply delivery.' end
        end
    end
    for key,engine in pairs(mc_apps) do
        if engine.Snapshot().cleanup_pending then return false,'Waiting for '..key..' laptop cleanup.' end
    end
    if bunker_app_engine and bunker_app_engine.Snapshot().cleanup_pending then return false,'Waiting for Bunker laptop cleanup.' end
    return Module.FarmSaleIdle({Count=function(name)
        local hash=script_hash(name);if not hash then return nil end;return script_thread_count(hash)
    end,Context=farm_sale_context})
end

local function farm_sale_queue()
    if not sale_queue then sale_queue=Module.NewSaleQueue(farm_sales_idle) end
    return sale_queue
end

local function stop_all_mc_farms(reason)
    for _,farm in pairs(mc_farms) do farm.Stop(reason) end
end

farm_transactions_idle=function()
    local raw=module_context and module_context.Raw or {}
    local g,n=raw.ScriptGlobal,raw.Natives
    if not g or not n or type(g.AreValid)~='function' or type(g.GetInt)~='function'
        or type(n.InvokeString)~='function' or type(n.InvokeBool)~='function' then
        return false,'Native transaction status is unavailable.'
    end
    local ok,idle,why=pcall(function()
        if g.AreValid()~=true or n.InvokeString(0xFCA9373EF340AC0A)~='1.73' then
            return false,'Native transaction context is unverified.'
        end
        return Module.BusinessTransactionsIdle({Read=g.GetInt,
            Basket=function()return n.InvokeBool(0xA65568121DF2EA26)end,
            Checkout=function()return n.InvokeBool(0x613F125BA3BD2EB9)end})
    end)
    if not ok then return false,'Native transaction read failed.' end
    return idle==true,why
end

local function start_mc_farm(business,repeat_mode)
    local cargo=module_context and module_context.CScript and module_context.CScript.CargoFarm
    if cargo and cargo.Snapshot().running then return false,"Stop Cargo Auto Farm before starting another sale farm."end
    local stock_automation=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
    local stock_state=stock_automation and stock_automation.Snapshot and stock_automation.Snapshot(business)
    if stock_state and stock_state.stock_farm and stock_state.stock_farm.running then return false,'Stop Stock Farm for this business before starting its sale farm.' end
    if mc_farms[business] and mc_farms[business].Snapshot().active then return false,'Auto Farm is already running for this business.' end
    if mc_apps[business] and mc_apps[business].Snapshot().cleanup_pending then return false,'This business laptop is still closing.' end
    local row,why=mc_farm_read(business);if not row then return false,why end
    local a=module_context.CScript.BusinessAutomation;local core=economy()
    if not a then return false,'MC supplies are unavailable.' end
    local hash=script_hash('gb_biker_contraband_sell')
    if not hash then return false,'MC sale profile is unavailable.' end
    local app,err=bunker_app_sale_host(MC_APP_SOURCE,business);if not app then return false,err end
    app.Report=function(phase,stage,property,command,quote)
        if module_context.Logger and module_context.Logger.Info then
            module_context.Logger.Info(('phase=%s stage=%s property=%s command=%s quote=%s')
                :format(tostring(phase),tostring(stage),tostring(property),tostring(command),tostring(quote)),'MCAppSale')
        end
    end
    local engine=Module.NewMCAppSale(app)
    mc_apps[business]=engine
    local queue=farm_sale_queue()
    local farm=Module.NewMCFarm({
        Report=function(phase,reason)
            if module_context.Logger and module_context.Logger.Info then
                module_context.Logger.Info('business='..business..' phase='..tostring(phase)..' reason='..tostring(reason),'MCFarm')
            end
        end,
        Read=function()return mc_farm_read(business) end,
        Supplies=function(enabled)return a.Request('fast_supplies',business,enabled) end,
        Production=function(enabled)return a.Request('production',business,enabled) end,
        ProductionActive=function()return a.Snapshot(business).fast_production end,
        SupplyActive=function()return a.Snapshot(business).auto_supplies end,
        TransactionsIdle=function()
            local s=a.Snapshot(business)
            if s.cleanup_pending or s.production_queued or s.supply_queued or s.supply_pending or s.fast_production or s.auto_supplies then
                return false,("Production restore pending: cleanup=%s productionQueued=%s supplyQueued=%s supplyPending=%s production=%s supplies=%s.")
                    :format(tostring(s.cleanup_pending),tostring(s.production_queued),tostring(s.supply_queued),
                        tostring(s.supply_pending),tostring(s.fast_production),tostring(s.auto_supplies))
            end
            return farm_transactions_idle()
        end,
        BeginAttribution=function()return core.BeginEarningAttribution() end,
        AcquireSale=function()return queue.Acquire(business) end,
        ReleaseSale=function()queue.Release(business) end,
        StartSale=function(now)mc_app_engine=engine;return engine.Start(now) end,
        SaleSnapshot=function()return engine.Snapshot() end,
        CancelSale=function(reason)queue.Cancel(business);return engine.Cancel(reason) end,
        CompleteSale=function()
            local ctx,detail=active_sale_context(active_sale_profile("mc"),hash)
            if not ctx then return false,detail end
            return complete_mc_sale(ctx)
        end,
        SaleEnded=function()return script_thread_count(hash)==0 end,
        Attribute=function(anchor,delta)
            core.Refresh()
            return core.AttributeEarning(anchor,'Businesses',delta,
                BUSINESS_BY_KEY[business].name..' sale (ended controller, reduced stock and correlated balance; payment persistence unverified)')==true
        end,
    })
    mc_farms[business]=farm
    return farm.Start(repeat_mode,State.clock_ms or 0)
end

local function mc_farm_snapshot(business)
    business=business or (State and State.selected_business)
    local farm=mc_farms[business]
    if not farm then return {active=false,phase='IDLE',cycles=0} end
    local row=farm.Snapshot();row.business=business;return row
end

local function stop_mc_farm(reason,business)
    business=business or (State and State.selected_business)
    local farm=mc_farms[business]
    if not farm then return false,'Auto Farm is not running for this business.' end
    farm.Stop(reason)
    return true
end

local function bunker_farm_read()
    local core=economy();local raw=module_context and module_context.Raw or {}
    local globals,natives,memory,utils=raw.ScriptGlobal,raw.Natives,raw.Memory,raw.Utils
    if not core or type(core.Snapshot)~="function" or type(core.CurrentSlot)~="function"
        or type(core.ReadStat)~="function" or type(core.QualifyStat)~="function"
        or not globals or type(globals.GetTunableByHash)~="function" or not memory or type(memory.ReadInt)~="function"
        or not utils or type(utils.Joaat)~="function" or not natives or type(natives.InvokeInt)~="function" then
        return nil,"Bunker farm read APIs are unavailable."
    end
    local scope=core.Snapshot();local slot=core.CurrentSlot()
    if type(scope)~="table" or scope.account_verified~=true or scope.online~=true or (slot~=0 and slot~=1) then
        return nil,"Verified GTA Online character context is unavailable."
    end
    local function stat(key)
        local name=core.QualifyStat(slot,key);local v=core.ReadStat(name)
        v=tonumber(v);return v and math.floor(v) or nil
    end
    local stock,supplies=stat("PRODTOTALFORFACTORY5"),stat("MATTOTALFORFACTORY5")
    if stock==nil or supplies==nil then return nil,"Bunker inventory readback is unavailable." end
    local h=utils.Joaat("GR_MANU_CAPACITY")
    local ptr=globals.GetTunableByHash(h)
    local cap=ptr and ptr~=0 and memory.ReadInt(ptr) or nil
    cap=tonumber(cap);if not cap or cap<1 or cap>1000 then return nil,"Bunker capacity is unavailable." end

    -- Recreate the app's Los Santos quote from current named tunables when possible.
    -- This gives the farm a lower-bound settlement check: high-demand / first-sale
    -- bonuses may legitimately pay more, but a Blaine County-sized underpayment
    -- must never be accepted as a successful Los Santos cycle.
    local function tunable(name,kind)
        local ok,hash=pcall(utils.Joaat,name);if not ok then return nil end
        local pok,p=pcall(globals.GetTunableByHash,hash);p=pok and tonumber(p) or 0
        if p==0 then return nil end
        local reader=kind=="float" and memory.ReadFloat or memory.ReadInt
        if type(reader)~="function" then return nil end
        local rok,value=pcall(reader,p)
        return rok and tonumber(value) or nil
    end
    local minimum_los_santos_payout
    local base=tunable("GR_MANU_PRODUCT_VALUE","int")
    local equipment_value=tunable("GR_MANU_PRODUCT_VALUE_EQUIPMENT_UPGRADE","int")
    local staff_value=tunable("GR_MANU_PRODUCT_VALUE_STAFF_UPGRADE","int")
    local far=tunable("GR_SELL_PRODUCT_FAR_MODIFIER","float")
    local equipment,staff=stat("BUNKER_EQUIPMENT"),stat("BUNKER_STAFF")
    if base and equipment_value and staff_value and far and far>0 and far<100
        and (equipment==0 or equipment==1) and (staff==0 or staff==1) then
        local unit=base+(equipment==1 and equipment_value or 0)+(staff==1 and staff_value or 0)
        minimum_los_santos_payout=math.floor(unit*stock*far+0.5)
        if minimum_los_santos_payout<=0 then minimum_los_santos_payout=nil end
    end
    local bank=natives.InvokeInt(0x76EF28DA05EA395A)
    local wallet=natives.InvokeInt(0xA40F9C2623F6A8B5,slot)
    bank,wallet=tonumber(bank),tonumber(wallet)
    if not bank or not wallet then return nil,"Bunker farm balance snapshot is unavailable." end
    return {account=scope.account_id,generation=scope.generation,slot=slot,stock=stock,supplies=supplies,
        capacity=math.floor(cap),bank=bank,wallet=wallet,balance=bank+wallet,
        minimum_los_santos_payout=minimum_los_santos_payout}
end

local function bunker_farm_scope_valid(token)
    -- Inventory may be temporarily unreadable; a known identity change is not
    -- an inventory delay and must cancel without waiting for the read grace.
    local core=economy()
    if not core or type(core.Snapshot)~="function" or type(core.CurrentSlot)~="function" then
        return nil,nil,"Bunker context status is unavailable."
    end
    local checked,scope=pcall(core.Snapshot)
    local read_slot,slot=pcall(core.CurrentSlot)
    if not checked or type(scope)~="table" or not read_slot then return nil,nil,"Bunker context status is unavailable." end
    if scope.account_verified~=true or scope.online~=true or scope.account_id~=token.account
        or scope.generation~=token.generation or slot~=token.slot then return false end
    local read,row,why=pcall(bunker_farm_read)
    if not read then return nil,nil,tostring(row) end
    if not row then return nil,nil,why end
    return row.account==token.account and row.generation==token.generation and row.slot==token.slot,row
end

local function bunker_farm_stop_automation()
    local a=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
    if a and type(a.Request)=="function" then
        pcall(a.Request,"production","bunker",false)
        pcall(a.Request,"supplies","bunker",false)
    end
end

local function bunker_farm_fail(reason)
    bunker_farm_stop_automation()
    if sale_queue then sale_queue.Cancel("bunker") end
    if bunker_app_engine then pcall(bunker_app_engine.Cancel,"Bunker farm stopped.") end
    if bunker_farm then
        bunker_farm.active=false;bunker_farm.phase="FAILED";bunker_farm.reason=tostring(reason or "Bunker Auto Farm failed.")
    end
    return false,bunker_farm and bunker_farm.reason or tostring(reason)
end

local function bunker_farm_begin_production(row,now)
    -- Request only queues work. Every cycle needs its own applied confirmation
    -- and stock high-water mark; native timer/supply delays are not progress.
    bunker_farm.phase="STARTING";bunker_farm.phase_ms=now
    bunker_farm.progress_ms=now;bunker_farm.progress_stock=row.stock
    bunker_farm.status_missing_ms=nil;bunker_farm.controls_stopped_ms=nil
    bunker_farm.read_missing_ms=nil;bunker_farm.balance_before=nil
    bunker_farm.wait_reason="Waiting for queued Production and auto supplies to apply."
end

local function start_bunker_farm(repeat_mode)
    local cargo=module_context and module_context.CScript and module_context.CScript.CargoFarm
    if cargo and cargo.Snapshot().running then return false,"Stop Cargo Auto Farm before starting another sale farm."end
    local stock_automation=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
    local stock_state=stock_automation and stock_automation.Snapshot and stock_automation.Snapshot('bunker')
    if stock_state and stock_state.stock_farm and stock_state.stock_farm.running then return false,'Stop Stock Farm for Bunker before starting its sale farm.' end
    if bunker_farm and bunker_farm.active then return false,"Bunker Auto Farm is already running." end
    local row,why=bunker_farm_read();if not row then return false,why end
    local a=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
    if not a or type(a.Request)~="function" then return false,"Business automation is unavailable." end
    local ok,err=a.Request("supplies","bunker",true);if not ok then return false,err end
    ok,err=a.Request("production","bunker",true);if not ok then
        pcall(a.Request,"supplies","bunker",false);return false,err
    end
    bunker_farm={active=true,repeat_mode=repeat_mode~=false,cycles=0,
        account=row.account,generation=row.generation,slot=row.slot,started_ms=State and State.clock_ms or 0,
        expected_payout=row.minimum_los_santos_payout or 1050000,
        payout_floor_source=row.minimum_los_santos_payout and "current tunables" or "normal full-stock fallback",
        last_stock=row.stock,last_supplies=row.supplies,settle_good=0}
    bunker_farm_begin_production(row,bunker_farm.started_ms)
    return true,"Bunker Auto Farm starting; waiting for applied Production and auto supplies."
end

local function stop_bunker_farm(reason)
    if not bunker_farm or not bunker_farm.active then return false,"Bunker Auto Farm is not running." end
    bunker_farm_stop_automation()
    if sale_queue then sale_queue.Cancel("bunker") end
    if bunker_app_engine then pcall(bunker_app_engine.Cancel,"Bunker Auto Farm stopped.") end
    if bunker_sale_engine then pcall(bunker_sale_engine.Cancel,"Bunker Auto Farm stopped.") end
    bunker_farm.active=false;bunker_farm.phase="STOPPED";bunker_farm.reason=tostring(reason or "Stopped by user.")
    return true,bunker_farm.reason
end

local function bunker_farm_snapshot()
    if not bunker_farm then return {active=false,phase="IDLE",cycles=0} end
    local out={};for k,v in pairs(bunker_farm) do
        if type(v)=="string" or type(v)=="number" or type(v)=="boolean" then out[k]=v end
    end
    return out
end

local function request_finish_farm_cycle(key, expected_token)
    local item=type(key)=='string' and BUSINESS_BY_KEY[key] or nil
    if not item or (key~='bunker' and not item.factory_ids) then
        return false,'Choose Bunker or an MC sale farm.'
    end
    if not started then return false,'Business Manager is not running.' end
    local engine=key~='bunker' and mc_farms[key] or nil
    local farm=key=='bunker' and bunker_farm or engine and engine.CaptureFinishCycle()
    if not farm or not farm.active then return false,'This sale farm is not running.' end
    if expected_token~=nil and (type(expected_token)~='number' or expected_token%1~=0
        or expected_token~=farm_row_token(farm)) then
        return false,'The displayed farm cycle changed; refresh the row before requesting finish.'
    end
    if farm.finish_requested then return true,'Finish current cycle is already requested.' end
    if farm.account==nil or farm.generation==nil or (farm.slot~=0 and farm.slot~=1) then
        return false,'The active farm identity is unavailable.'
    end
    -- Capture BEFORE deferring; request and snapshot do no game reads or writes.
    farm_finish_requests[key]={farm=farm,engine=engine,account=farm.account,
        slot=farm.slot,generation=farm.generation}
    farm.finish_requested=true
    return true,'Finish requested; the current cycle will follow its existing guarded path.'
end

local function tick_farm_finish_requests()
    local requests=farm_finish_requests
    farm_finish_requests={}
    for key,request in pairs(requests) do
        local farm=request.farm
        local same=key=='bunker' and bunker_farm==farm
            or key~='bunker' and mc_farms[key]==request.engine
                and request.engine.CaptureFinishCycle()==farm
        local core=economy()
        local checked,scope=false,nil
        local read_slot,slot=false,nil
        if same and farm.active and core and type(core.Snapshot)=='function' and type(core.CurrentSlot)=='function' then
            checked,scope=pcall(core.Snapshot)
            read_slot,slot=pcall(core.CurrentSlot)
        end
        if same and farm.active and checked and type(scope)=='table' and read_slot
            and scope.account_verified==true and scope.online==true and scope.account_id==request.account
            and scope.generation==request.generation and slot==request.slot then
            if key=='bunker' then
                farm.repeat_mode=false
                if farm.phase=='COOLDOWN' then farm.active=false;farm.phase='COMPLETED' end
            else request.engine.FinishCycle(farm) end
            farm_finish_detail='Finish current cycle applied to '..BUSINESS_BY_KEY[key].name..'.'
        else
            farm.finish_requested=nil
            farm_finish_detail='Finish request discarded: the captured farm or account/session/character changed or became unavailable.'
        end
    end
end

local function farm_activity_snapshot()
    local rows={}
    for _,item in ipairs(BUSINESS_CATALOG) do
        if item.key=='bunker' or item.factory_ids then
            local farm=item.key=='bunker' and bunker_farm_snapshot() or mc_farm_snapshot(item.key)
            local engine=item.key~='bunker' and mc_farms[item.key] or nil
            local instance=item.key=='bunker' and bunker_farm or engine and engine.CaptureFinishCycle()
            rows[#rows+1]={key=item.key,label=item.name,active=farm.active==true,
                request_token=farm_row_token(instance),
                phase=farm.phase or 'IDLE',finish_requested=farm.finish_requested==true,
                detail=farm.reason or farm.wait_reason or (farm.finish_requested
                    and 'Finish requested; no payment is claimed by this request.' or 'No finish request.')}
        end
    end
    return {rows=rows,detail=farm_finish_detail}
end

local function tick_bunker_farm_once(now)
    if not bunker_farm or not bunker_farm.active then return end
    bunker_farm.clock_ms=now
    local valid,row,why=bunker_farm_scope_valid(bunker_farm)
    if valid==false then bunker_farm_fail("Bunker Auto Farm stopped: account/session/character context changed.");return end
    if not row then
        bunker_farm.read_missing_ms=bunker_farm.read_missing_ms or now
        bunker_farm.wait_reason=tostring(why or "Bunker inventory status is unavailable.")
        if now-bunker_farm.read_missing_ms>=15000 then
            bunker_farm_fail("Bunker read status did not recover: "..bunker_farm.wait_reason)
        end
        return
    end
    if bunker_farm.read_missing_ms then bunker_farm.wait_reason=nil end
    bunker_farm.read_missing_ms=nil
    bunker_farm.last_stock,bunker_farm.last_supplies,bunker_farm.capacity=row.stock,row.supplies,row.capacity
    local automation=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
    if bunker_farm.phase=="STARTING" or bunker_farm.phase=="PRODUCING" then
        -- Full stock needs no production confirmation: restore and use the
        -- existing sale ownership path even if a queued override failed.
        if row.stock>=row.capacity then
            if row.minimum_los_santos_payout then
                bunker_farm.expected_payout=row.minimum_los_santos_payout
                bunker_farm.payout_floor_source="current tunables"
            end
            bunker_farm.wait_reason=nil
            bunker_farm_stop_automation();bunker_farm.phase="WAIT_PRODUCTION_RESTORE";bunker_farm.phase_ms=now
            return
        end
        local read,a=false,nil
        if automation and type(automation.Snapshot)=="function" then read,a=pcall(automation.Snapshot,"bunker") end
        local known=read and type(a)=="table"
        local applied=known and a.fast_production==true and a.auto_supplies==true
            and a.supply_queued==false and a.cleanup_pending==false
        if not applied then
            bunker_farm.status_missing_ms=bunker_farm.status_missing_ms or now
            local stopped=known and (a.fast_production==false and a.production_queued==false
                or a.auto_supplies==false and a.supply_queued==false)
            if stopped then
                bunker_farm.controls_stopped_ms=bunker_farm.controls_stopped_ms or now
            else bunker_farm.controls_stopped_ms=nil end
            local evidence=known and (a.production_result or a.supply_result) or nil
            bunker_farm.wait_reason=stopped and "Production or auto supplies are not applied; waiting for confirmation."
                or "Waiting for Production and auto supplies status/application."
            -- Result strings are shared/advisory; applied flags and queue state
            -- decide liveness. Never re-arm controls against a user's Off choice.
            if evidence then bunker_farm.wait_reason=bunker_farm.wait_reason.." Automation: "..tostring(evidence) end
            if bunker_farm.controls_stopped_ms and now-bunker_farm.controls_stopped_ms>=5000 then
                bunker_farm_fail("Production or auto supplies stopped/failed to apply. "..bunker_farm.wait_reason)
            elseif now-bunker_farm.status_missing_ms>=15000
                or bunker_farm.phase=="STARTING" and now-bunker_farm.phase_ms>=15000 then
                bunker_farm_fail("Production startup/status confirmation timed out. "..bunker_farm.wait_reason)
            end
            return
        end
        bunker_farm.status_missing_ms=nil;bunker_farm.controls_stopped_ms=nil;bunker_farm.wait_reason=nil
        if bunker_farm.phase=="STARTING" then
            bunker_farm.phase="PRODUCING";bunker_farm.phase_ms=now
            bunker_farm.progress_ms=now;bunker_farm.progress_stock=row.stock
        elseif row.stock>(bunker_farm.progress_stock or row.stock) then
            bunker_farm.progress_stock=row.stock;bunker_farm.progress_ms=now
        end
        -- Fifteen minutes tolerates slow native units plus a two-minute supply
        -- delivery. A single unchanged tick or consumed supply is not failure.
        if now-bunker_farm.progress_ms>=900000 then
            bunker_farm_fail("No Bunker stock increase for fifteen minutes; check setup, manufacturing and supplies.")
        end
    elseif bunker_farm.phase=="WAIT_PRODUCTION_RESTORE" then
        local a=automation and automation.Snapshot and automation.Snapshot("bunker") or {}
        local idle,why=farm_transactions_idle()
        if a.fast_production~=true and a.cleanup_pending~=true and a.auto_supplies~=true
            and a.production_queued~=true and a.supply_queued~=true and a.supply_pending~=true and idle==true then
            if bunker_farm.restore_stock~=row.stock then
                bunker_farm.restore_stock=row.stock;bunker_farm.restore_idle_since=now
            end
            if now-(bunker_farm.restore_idle_since or now)>=1000 then
                bunker_farm.phase="WAIT_SALE_TURN";bunker_farm.phase_ms=now
            end
        else
            bunker_farm.restore_idle_since=nil;bunker_farm.restore_stock=nil
            bunker_farm.wait_reason=why or "Waiting for production restoration or pending supplies."
        end
        if bunker_farm.phase=="WAIT_PRODUCTION_RESTORE" and now-(bunker_farm.phase_ms or now)>60000 then
            bunker_farm_fail("Production or supplies have not settled before the sale start.");return
        end
    elseif bunker_farm.phase=="WAIT_SALE_TURN" then
        local idle,why=farm_transactions_idle()
        if idle~=true then bunker_farm.restore_idle_since=nil;bunker_farm.wait_reason=why;return end
        bunker_farm.restore_idle_since=bunker_farm.restore_idle_since or now
        if now-bunker_farm.restore_idle_since<1000 then return end
        local acquired,why=farm_sale_queue().Acquire("bunker")
        if acquired then bunker_farm.wait_reason=nil else bunker_farm.wait_reason=why end
        if acquired then
            local economy=module_context and module_context.CScript and module_context.CScript.Economy
            if economy and type(economy.Refresh)=="function" then economy.Refresh() end
            bunker_farm.balance_before=row.balance;bunker_farm.stock_before=row.stock
            bunker_farm.earning_anchor=economy and type(economy.BeginEarningAttribution)=="function"
                and economy.BeginEarningAttribution() or nil
            local ok,why=start_bunker_app_sale()
            if not ok then bunker_farm_fail(why);return end
            bunker_farm.phase="WAIT_SALE_CONTROLLER";bunker_farm.phase_ms=now
        end
    elseif bunker_farm.phase=="WAIT_SALE_CONTROLLER" then
        local s=bunker_app_sale_snapshot()
        if s.phase=="FAILED" then bunker_farm_fail(s.reason or "Bunker app sale start failed.");return end
        if s.phase=="STARTED" then
            bunker_farm.phase="WAIT_COMPLETION_READY";bunker_farm.phase_ms=now;bunker_farm.completion_attempts=0
        elseif now-(bunker_farm.phase_ms or now)>25000 then
            bunker_farm_fail("Direct Bunker sale controller did not start.");return
        end
    elseif bunker_farm.phase=="WAIT_COMPLETION_READY" then
        if now-(bunker_farm.phase_ms or now)<1500 then return end
        if farm_transactions_idle()~=true then
            bunker_farm.wait_reason="Waiting for sale-start transaction settlement."
            if now-(bunker_farm.phase_ms or now)>15000 then bunker_farm_fail(bunker_farm.wait_reason) end
            return
        end
        bunker_farm.wait_reason=nil
        bunker_farm.completion_attempts=(bunker_farm.completion_attempts or 0)+1
        local ok,why=complete_active_sale()
        if ok then
            bunker_farm.phase="WAIT_SETTLEMENT";bunker_farm.phase_ms=now;bunker_farm.settle_good=0;bunker_farm.settle_last=nil
        elseif now-(bunker_farm.phase_ms or now)>15000 then
            bunker_farm_fail("Bunker completion never became ready: "..tostring(why));return
        end
    elseif bunker_farm.phase=="WAIT_SETTLEMENT" then
        local delta=row.balance-(bunker_farm.balance_before or row.balance)
        bunker_farm.last_balance_delta=delta
        local hash=script_hash('gb_gunrunning')
        local ended=hash~=nil and script_thread_count(hash)==0
        local idle,why=farm_transactions_idle()
        local cleanup=bunker_app_engine and bunker_app_engine.Snapshot().cleanup_pending==true
        bunker_farm.wait_reason=not ended and 'Waiting for the Bunker sale controller to close.'
            or cleanup and 'Waiting for Bunker laptop cleanup.' or not idle and why or nil
        if row.stock==0 and delta>=(bunker_farm.expected_payout or 1) and ended and idle and not cleanup then
            if bunker_farm.settle_delta~=delta or not bunker_farm.settle_since then
                bunker_farm.settle_delta=delta;bunker_farm.settle_since=now;bunker_farm.settle_good=0;bunker_farm.settle_last=nil
            end
            if not bunker_farm.settle_last or now>bunker_farm.settle_last then
                bunker_farm.settle_good=(bunker_farm.settle_good or 0)+1;bunker_farm.settle_last=now
            end
            if bunker_farm.settle_good>=3 and now-bunker_farm.settle_since>=1000 then
                bunker_farm.cycles=(bunker_farm.cycles or 0)+1
                bunker_farm.last_cycle_payout=delta
                local economy=module_context and module_context.CScript and module_context.CScript.Economy
                if economy and type(economy.Refresh)=="function" then economy.Refresh() end
                if economy and type(economy.AttributeEarning)=="function" then
                    bunker_farm.earning_attributed=economy.AttributeEarning(bunker_farm.earning_anchor,
                        "Businesses",delta,"Bunker sale (correlated with completed delivery and empty stock)") == true
                end
                bunker_farm.earning_anchor=nil
                if sale_queue then sale_queue.Release("bunker") end
                if bunker_farm.repeat_mode then
                    bunker_farm.phase="COOLDOWN";bunker_farm.phase_ms=now
                else
                    bunker_farm.active=false;bunker_farm.phase="COMPLETED"
                end
            end
        else bunker_farm.settle_good=0;bunker_farm.settle_last=nil;bunker_farm.settle_since=nil;bunker_farm.settle_delta=nil end
        if bunker_farm.active and now-(bunker_farm.phase_ms or now)>30000 then
            bunker_farm_fail(("Bunker settlement mismatch: stock=%s delta=%s expected-at-least=%s")
                :format(tostring(row.stock),tostring(delta),tostring(bunker_farm.expected_payout)));return
        end
    elseif bunker_farm.phase=="COOLDOWN" then
        local ok,why=automation.Request("supplies","bunker",true)
        if not ok then bunker_farm_fail(why);return end
        ok,why=automation.Request("production","bunker",true)
        if not ok then bunker_farm_fail(why);return end
        bunker_farm_begin_production(row,now)
    end
end

local function tick_bunker_farm(now)
    -- Continue across ready phase boundaries without adding an idle frame.
    -- Each step repeats account/inventory validation; settlement counts only
    -- distinct timestamps and never releases its transaction/cleanup fences.
    for _=1,8 do
        local before=bunker_farm and bunker_farm.phase
        tick_bunker_farm_once(now)
        if not bunker_farm or not bunker_farm.active or bunker_farm.phase==before then break end
    end
end

local function solo_mc_routes_status()
    local tools = module_context and module_context.CScript and module_context.CScript.MissionTools
    local snapshot = tools and type(tools.TunableOverrideSnapshot) == "function"
        and tools.TunableOverrideSnapshot() or nil
    for _, profile in ipairs(snapshot and snapshot.profiles or {}) do
        if profile.key == "mc_solo_sales" then
            return {
                available = true, active = profile.total > 0 and profile.active == profile.total,
                partial = profile.active > 0 and profile.active < profile.total,
                active_count = profile.active, total = profile.total, reason = profile.reason,
            }
        end
    end
    return { available = false, active = false, partial = false,
        reason = "Solo MC Sale Routes tunable profile is unavailable." }
end

local function set_solo_mc_routes(enabled)
    local tools = module_context and module_context.CScript and module_context.CScript.MissionTools
    if not tools then return false, "Mission Tools tunable service is unavailable." end
    if enabled then return tools.ApplyTunableProfile("mc_solo_sales") end
    return tools.RestoreTunableProfile("mc_solo_sales")
end

-- Get Supplies arms the freemode resupply timer. Global_1673820 slots 0..4
-- are MC factories, 5 is Bunker and 6 is Acid Lab. The raw ScriptGlobal index
-- is base + 1 + slot. Once cloud_time - timestamp exceeds the cooldown,
-- freemode clears the entry and handles delivery. Silent Night 1.11.4
-- provides a corroborating reference; current source revision is below.
local RESUPPLY_PROFILE = {
    base_index = 1673820,
    trigger_value = 1,
    source_revision = "Tessio/v-decompiled-scripts@a6e73168a5480d29cec6a04759a2bef231c7c7fe",
    evidence = "Enhanced freemode Global_1673820[i], func_21961 and delivery loop; Silent Night 1.11.4 Business.Supplies semantic workflow",
}

local function resupply_slot(status)
    if not status then return nil end
    if status.key == "bunker" then return 5 end
    if status.key == "acid_lab" then return 6 end
    if tostring(status.key or ""):match("^mc_") then
        local slot = tonumber(status.factory_slot)
        if slot and slot % 1 == 0 and slot >= 0 and slot <= 4 then return slot end
    end
    return nil
end

local function rockstar_resupply(status)
    local slot = resupply_slot(status)
    if slot == nil then
        return false, "Rockstar resupply is available only for a validated MC factory slot, Bunker, or Acid Lab."
    end
    local globals = binding("ScriptGlobal")
    if not (globals and type(globals.GetInt) == "function" and type(globals.SetInt) == "function") then
        return false, "Cherax ScriptGlobal read/write access is unavailable; the resupply request was not armed."
    end
    local header_ok, header = pcall(globals.GetInt, RESUPPLY_PROFILE.base_index)
    if not header_ok or header ~= 7 then return false, "Resupply array does not match this build." end
    local index = RESUPPLY_PROFILE.base_index + 1 + slot
    local read_ok, before = pcall(globals.GetInt, index)
    before = read_ok and tonumber(before) or nil
    if before == nil or before % 1 ~= 0 or before < 0 or before > 2147483647 then
        return false, ("Current Rockstar resupply timestamp for slot %d could not be validated; zero writes were performed."):format(slot)
    end
    if before == RESUPPLY_PROFILE.trigger_value then
        return true, "Rockstar resupply is already armed for this business."
    end
    local write_ok, write_result = pcall(globals.SetInt, index, RESUPPLY_PROFILE.trigger_value)
    if not write_ok or write_result == false then
        return false, "Cherax rejected the Rockstar resupply trigger; no persistent business stock stat was changed."
    end
    local verify_ok, observed = pcall(globals.GetInt, index)
    observed = verify_ok and tonumber(observed) or nil
    -- 1 = armed and waiting for freemode. 0 = freemode already consumed the
    -- trigger. Both are valid post-write states. Anything else is treated as
    -- an unverified transition and the previous timestamp is restored when
    -- possible, keeping the same snapshot/verify/rollback posture as CScript's
    -- persistent business transactions.
    if observed ~= RESUPPLY_PROFILE.trigger_value and observed ~= 0 then
        local rollback_ok = pcall(globals.SetInt, index, before)
        local reread_ok, restored = pcall(globals.GetInt, index)
        restored = reread_ok and tonumber(restored) or nil
        local rollback_state = rollback_ok and restored == before and "previous timestamp restored"
            or "rollback could not be verified"
        return false, ("Rockstar resupply trigger could not be verified (observed %s; %s). No direct supplies/product stat was written.")
            :format(tostring(observed), rollback_state)
    end
    local state = observed == 0 and "accepted/consumed by freemode" or "armed"
    return true, ("Rockstar resupply %s for %s. GTA now owns the delivery flow."):format(state, tostring(status.name or "business"))
end

