-- GTA Online Enhanced 1.73 / build 1158.13 Hangar inventory. Current
-- appsmuggler.c resolves physical cargo slots through packed character stats
-- 16011..16060 and STATS::GET_PACKED_STAT_INT_CODE(index, characterSlot).
-- The 1..16 values encode two crate variants for each of eight Air Freight
-- families. The replicated global mirror remains useful diagnostically, but
-- packed storage is the local slot read path used here, not authority proof.
-- This writer edits the 50 local slots. It does not provide reserve storage,
-- an accepted cargo grant or a sale lifecycle.
local GET_PACKED_STAT_INT_CODE = 0x0BC900A6FE73770C
local SET_PACKED_STAT_INT_CODE = 0x1581503AE529CD2E
local HANGAR_PACKED_PROFILE = {
    first = 16011, count = 50, capacity = 50,
    source_revision = "GTA Online Enhanced 1.73 / 1158.13 validated logical source corpus",
    evidence = "appsmuggler.c _STAT_GET_PACKED_INT + func_321 and CATEGORY_CONTRABAND_QNTY transaction path",
    types = {
        [1] = "Medical Supplies", [2] = "Medical Supplies",
        [3] = "Tobacco & Alcohol", [4] = "Tobacco & Alcohol",
        [5] = "Art & Antiques", [6] = "Art & Antiques",
        [7] = "Narcotics", [8] = "Narcotics",
        [9] = "Jewelry & Gemstones", [10] = "Jewelry & Gemstones",
        [11] = "Animal Materials", [12] = "Animal Materials",
        [13] = "Counterfeit Goods", [14] = "Counterfeit Goods",
        [15] = "Chemicals", [16] = "Chemicals",
    },
}
local HANGAR_TYPE_ORDER = {
    "Animal Materials", "Art & Antiques", "Chemicals", "Counterfeit Goods",
    "Jewelry & Gemstones", "Medical Supplies", "Narcotics", "Tobacco & Alcohol",
}
-- Silent Night 1.13.1 Enhanced Supporter tracing (2026-08-18) confirmed
-- this packed-slot layer and Animal Materials values 11/12. Preserve the
-- eight Rockstar cargo-family pairs.
local HANGAR_TYPE_VARIANTS = {
    [1] = { 11, 12 }, -- Animal Materials
    [2] = { 5, 6 },   -- Art & Antiques
    [3] = { 15, 16 }, -- Chemicals
    [4] = { 13, 14 }, -- Counterfeit Goods
    [5] = { 9, 10 },  -- Jewelry & Gemstones
    [6] = { 1, 2 },   -- Medical Supplies
    [7] = { 7, 8 },   -- Narcotics
    [8] = { 3, 4 },   -- Tobacco & Alcohol
}
local HANGAR_POCKET_DEFAULTS = {
    -- The local slot editor is bounded by the physical 50-slot inventory.
    delay_ms = 50,
    step = 50,
    limit = 0, -- Zero selects the full local 50-slot capacity.
    type_index = 1,
    fast_mode = true,
    verify_poll_ms = 10,
    verify_timeout_ms = 350,
    normal_verify_ms = 75,
    normal_intra_step_ms = 50,
}

local function read_packed_int(index, character_slot)
    local natives = module_context and module_context.Natives
    if not natives or type(natives.Try) ~= "function" then
        return nil, "typed native service is unavailable"
    end
    index = tonumber(index)
    if not index or index % 1 ~= 0 or index < 0 then return nil, "packed stat index is invalid" end
    local ok, value = natives.Try("int", GET_PACKED_STAT_INT_CODE, index, character_slot == nil and -1 or character_slot)
    value = ok and tonumber(value) or nil
    if value == nil or value % 1 ~= 0 then
        return nil, "GET_PACKED_STAT_INT_CODE failed for index " .. tostring(index)
    end
    return math.floor(value)
end

local function request_packed_int_write(index, value, character_slot)
    local natives = module_context and module_context.Natives
    if not natives or type(natives.Try) ~= "function" then
        return false, "typed native service is unavailable"
    end
    index, value = tonumber(index), tonumber(value)
    if not index or index % 1 ~= 0 or index < HANGAR_PACKED_PROFILE.first
        or index >= HANGAR_PACKED_PROFILE.first + HANGAR_PACKED_PROFILE.count then
        return false, "packed Hangar slot index is outside 16011..16060"
    end
    if not value or value % 1 ~= 0 or value < 0 or value > 16 then
        return false, "packed Hangar cargo value must be an integer from 0 through 16"
    end
    local ok, err = natives.Try("void", SET_PACKED_STAT_INT_CODE, math.floor(index), math.floor(value), character_slot == nil and -1 or character_slot)
    if not ok then return false, "SET_PACKED_STAT_INT_CODE failed: " .. tostring(err) end
    return true
end

