        { key = "set_product", label = "Set Product to Target", style = "secondary",
            reason = "Converts the selected percentage through the live Acid Lab product capacity." },
    }, {
        complete_setup = function(_, _, status) return business_transaction(status,
            { FACTORYSETUP6 = 1 }, "Acid Lab - Complete Setup", "complete_setup") end,
        resupply = function(_, _, status) return rockstar_resupply(status) end,
        clear_supplies = function(_, _, status) return business_transaction(status,
            { MATTOTALFORFACTORY6 = 0 }, "Acid Lab - Clear Supplies", "clear_supplies") end,
        clear_product = function(_, _, status) return business_transaction(status,
            { PRODTOTALFORFACTORY6 = 0 }, "Acid Lab - Clear Product", "clear_product") end,
        fill_supplies = function(_, _, status)
            local value, err = current_capacity("supplies"); if not value then return false, err end
            return business_transaction(status, { MATTOTALFORFACTORY6 = value }, "Acid Lab - Fill Supplies", "fill_supplies")
        end,
        fill_product = function(_, _, status)
            local value, err = current_capacity("acid_product"); if not value then return false, err end
            return business_transaction(status, { PRODTOTALFORFACTORY6 = value }, "Acid Lab - Fill Product", "fill_product")
        end,
        set_supplies = function(_, _, status, request)
            local value, err = capacity_target("supplies", request and request.target_percent); if value == nil then return false, err end
            return business_transaction(status, { MATTOTALFORFACTORY6 = value }, "Acid Lab - Set Supplies", "set_supplies")
        end,
        set_product = function(_, _, status, request)
            local value, err = capacity_target("acid_product", request and request.target_percent); if value == nil then return false, err end
            return business_transaction(status, { PRODTOTALFORFACTORY6 = value }, "Acid Lab - Set Product", "set_product")
        end,
    }, { "FACTORYSETUP6", "MATTOTALFORFACTORY6", "PRODTOTALFORFACTORY6" },
        "Current Enhanced factory 6 named stats and live supply/product capacity tunables are readable. Changes remain live-test required.")

    local function ceo_standard_target(status, index, percent)
        local capacity = status.warehouse_capacities and status.warehouse_capacities[index]
        local detail = status.warehouse_details and status.warehouse_details[index]
        if not capacity or not detail then return nil, "Owned warehouse accounting is unavailable; zero writes were performed." end
        local special = math.max(0, tonumber(detail.special) or 0)
        local standard_capacity = math.max(0, capacity - special)
        if percent == nil then return standard_capacity end
        percent = tonumber(percent)
        if percent == nil or percent % 1 ~= 0 or percent < 0 or percent > 100 then
            return nil, "Warehouse target percentage must be a whole value from 0 to 100; zero writes were performed."
        end
        local desired_total = math.floor((capacity * percent / 100) + 0.5)
        return math.max(0, math.min(standard_capacity, desired_total - special))
    end

    ADAPTERS.special_cargo = named_stat_adapter("special-cargo-named-stats-v1", {
        { key = "fill_all", label = "Fill All Owned Warehouses", style = "primary",
            reason = "Fills standard crates only up to each owned warehouse's remaining capacity after current special-cargo crates; unused slots are untouched." },
        { key = "clear_all", label = "Clear Standard Crates", style = "danger",
            reason = "Clears only standard Special Cargo crate totals for owned warehouses. Special-item cargo counts are preserved and never written." },
        { key = "fill_selected", label = "Fill Selected Warehouse", style = "secondary",
            reason = "Fills standard crates only to the selected slot's remaining capacity after current special-cargo crates." },
        { key = "clear_selected", label = "Clear Selected Standard Crates", style = "danger",
            reason = "Clears only standard crates in the selected owned warehouse. Special-item cargo is preserved and never written." },
        { key = "set_selected", label = "Set Selected Warehouse to Target", style = "secondary",
            reason = "Targets total warehouse occupancy while preserving special-cargo crates; only the standard-crate stat is written and verified." },
        { key = "set_all_target", label = "Set All Owned Warehouses to Target", style = "secondary",
            reason = "Targets total occupancy independently for each owned warehouse while preserving special-cargo crates; unused slots remain untouched." },
    }, {
        fill_all = function(_, _, status)
            local values = {}
            for index in pairs(status.warehouse_capacities or {}) do
                local target, err = ceo_standard_target(status, index, nil)
                if target == nil then return false, err end
                values["CONTOTALFORWHOUSE" .. tostring(index)] = target
            end
            if next(values) == nil then return false, "No owned warehouse capacity was resolved; zero writes were performed." end
            return business_transaction(status, values, "CEO Special Cargo - Fill Owned Warehouses", "fill_all")
        end,
        clear_all = function(_, _, status)
            local values = {}
            for index in pairs(status.warehouse_capacities or {}) do
                values["CONTOTALFORWHOUSE" .. tostring(index)] = 0
            end
            if next(values) == nil then return false, "No owned warehouse capacity was resolved; zero writes were performed." end
            return business_transaction(status, values, "CEO Special Cargo - Clear Standard Crates", "clear_all")
        end,
        fill_selected = function(_, _, status, request)
            local index = tonumber(request and request.target_index)
            if not index or index % 1 ~= 0 or index < 1 or index > 5 then return false, "Select a valid warehouse slot; zero writes were performed." end
            local target, err = ceo_standard_target(status, index - 1, nil)
            if target == nil then return false, err end
            local key = "CONTOTALFORWHOUSE" .. tostring(index - 1)
            return business_transaction(status, { [key] = target }, "CEO Special Cargo - Fill Warehouse " .. tostring(index), "fill_selected")
        end,
        clear_selected = function(_, _, status, request)
            local index = tonumber(request and request.target_index)
            if not index or index % 1 ~= 0 or index < 1 or index > 5 then return false, "Select a valid warehouse slot; zero writes were performed." end
            if not (status.warehouse_capacities and status.warehouse_capacities[index - 1]) then
                return false, "The selected warehouse slot is not currently owned; zero writes were performed."
            end
            local key = "CONTOTALFORWHOUSE" .. tostring(index - 1)
            return business_transaction(status, { [key] = 0 }, "CEO Special Cargo - Clear Standard Crates Warehouse " .. tostring(index), "clear_selected")
        end,
        set_selected = function(_, _, status, request)
            local index = tonumber(request and request.target_index)
            if not index or index % 1 ~= 0 or index < 1 or index > 5 then return false, "Select a valid warehouse slot; zero writes were performed." end
            local value, err = ceo_standard_target(status, index - 1, request and request.target_percent)
            if value == nil then return false, err end
            local key = "CONTOTALFORWHOUSE" .. tostring(index - 1)
            return business_transaction(status, { [key] = value }, "CEO Special Cargo - Set Warehouse " .. tostring(index), "set_selected")
        end,
        set_all_target = function(_, _, status, request)
            local values = {}
            for index in pairs(status.warehouse_capacities or {}) do
                local target, err = ceo_standard_target(status, index, request and request.target_percent)
                if target == nil then return false, err end
                values["CONTOTALFORWHOUSE" .. tostring(index)] = target
            end
            if next(values) == nil then return false, "No owned warehouse capacity was resolved; zero writes were performed." end
            return business_transaction(status, values, "CEO Special Cargo - Set Owned Warehouses Target", "set_all_target")
        end,
    }, function(status)
        local required = {}
        for index in pairs(status and status.warehouse_capacities or {}) do
            required[#required + 1] = "CONTOTALFORWHOUSE" .. tostring(index)
            required[#required + 1] = "SPCONTOTALFORWHOUSE" .. tostring(index)
        end
        if #required == 0 then return { "OWNED_WAREHOUSE_SLOT_UNAVAILABLE" } end
        return required
    end,
        "Owned warehouse slots and their current Enhanced 16/42/111 capacities are resolved independently. Changes remain live-test required.")

    for _, key in ipairs({ "mc_cocaine", "mc_meth", "mc_cash", "mc_weed", "mc_documents" }) do
        ADAPTERS[key] = named_stat_adapter("mc-factory-slot-named-stats-v1", {
            { key = "complete_setup", label = "Complete Business Setup", style = "primary",
                reason = "Sets only FACTORYSETUP for the detected owned factory slot to 1." },
            { key = "resupply", label = "Get Supplies (Rockstar Flow)", style = "primary",
                    reason = "Requests supplies for this MC business through GTA's delivery system." },
            { key = "clear_supplies", label = "Clear Supplies", style = "danger",
                reason = "Clears only the material total for the detected owned factory slot." },
            { key = "clear_product", label = "Clear Product", style = "danger",
                reason = "Clears only the product total for the detected owned factory slot." },
            { key = "fill_supplies", label = "Direct Fill Supplies", style = "secondary",
                reason = "Direct stat editor using the live supply capacity. Use Get Supplies for Rockstar's normal resupply-delivery flow." },
            { key = "fill_product", label = "Fill Product", style = "primary",
                reason = "Uses the live current Enhanced business-specific product-capacity tunable." },
            { key = "set_supplies", label = "Set Supplies to Target", style = "secondary",
                reason = "Converts the selected percentage through the live supply capacity for the detected factory slot." },
            { key = "set_product", label = "Set Product to Target", style = "secondary",
                reason = "Converts the selected percentage through this business's live product capacity." },
        }, {
            complete_setup = function(_, _, status)
                local stat = "FACTORYSETUP" .. tostring(status.factory_slot)
                return business_transaction(status, { [stat] = 1 }, status.name .. " - Complete Setup", "complete_setup")
            end,
            resupply = function(_, _, status)
                return rockstar_resupply(status)
            end,
            clear_supplies = function(_, _, status)
                local stat = "MATTOTALFORFACTORY" .. tostring(status.factory_slot)
                return business_transaction(status, { [stat] = 0 }, status.name .. " - Clear Supplies", "clear_supplies")
            end,
            clear_product = function(_, _, status)
                local stat = "PRODTOTALFORFACTORY" .. tostring(status.factory_slot)
                return business_transaction(status, { [stat] = 0 }, status.name .. " - Clear Product", "clear_product")
            end,
            fill_supplies = function(_, _, status)
                local value, err = current_capacity("supplies"); if not value then return false, err end
                local stat = "MATTOTALFORFACTORY" .. tostring(status.factory_slot)
                return business_transaction(status, { [stat] = value }, status.name .. " - Fill Supplies", "fill_supplies")
            end,
            fill_product = function(_, _, status)
                local value, err = current_capacity(status.key .. "_product"); if not value then return false, err end
                local stat = "PRODTOTALFORFACTORY" .. tostring(status.factory_slot)
                return business_transaction(status, { [stat] = value }, status.name .. " - Fill Product", "fill_product")
            end,
            set_supplies = function(_, _, status, request)
                local value, err = capacity_target("supplies", request and request.target_percent); if value == nil then return false, err end
                local stat = "MATTOTALFORFACTORY" .. tostring(status.factory_slot)
                return business_transaction(status, { [stat] = value }, status.name .. " - Set Supplies", "set_supplies")
            end,
            set_product = function(_, _, status, request)
                local value, err = capacity_target(status.key .. "_product", request and request.target_percent); if value == nil then return false, err end
                local stat = "PRODTOTALFORFACTORY" .. tostring(status.factory_slot)
                return business_transaction(status, { [stat] = value }, status.name .. " - Set Product", "set_product")
            end,
        }, function(status)
            if tonumber(status and status.factory_slot) == nil then return { "FACTORY_SLOT_UNAVAILABLE" } end
            return {
                "FACTORYSETUP" .. tostring(status.factory_slot),
                "MATTOTALFORFACTORY" .. tostring(status.factory_slot),
                "PRODTOTALFORFACTORY" .. tostring(status.factory_slot),
            }
        end, "The detected factory slot's named stats and business-specific live capacity tunables are readable. Changes remain live-test required.")
    end
end

-- Disable direct stock/setup writes rejected or reconciled by Rockstar
-- before readback in live testing. Nightclub popularity and freemode
-- resupply use separate validated paths.
local LIVE_REJECTED_DIRECT_ACTIONS = {
    nightclub = {
        fill_warehouse=true, clear_warehouse=true, fill_selected_good=true,
        clear_selected_good=true, set_selected_good=true, set_warehouse_target=true,
    },
    bunker = {
        complete_setup=true, clear_supplies=true, clear_product=true,
        fill_supplies=true, fill_product=true, set_supplies=true, set_product=true,
    },
    acid_lab = {
        complete_setup=true, clear_supplies=true, clear_product=true,
        fill_supplies=true, fill_product=true, set_supplies=true, set_product=true,
    },
    special_cargo = {
        fill_all=true, clear_all=true, fill_selected=true, clear_selected=true,
        set_selected=true, set_all_target=true,
    },
    mc_cocaine = { complete_setup=true, clear_supplies=true, clear_product=true, fill_supplies=true, fill_product=true, set_supplies=true, set_product=true },
    mc_meth = { complete_setup=true, clear_supplies=true, clear_product=true, fill_supplies=true, fill_product=true, set_supplies=true, set_product=true },
    mc_cash = { complete_setup=true, clear_supplies=true, clear_product=true, fill_supplies=true, fill_product=true, set_supplies=true, set_product=true },
    mc_weed = { complete_setup=true, clear_supplies=true, clear_product=true, fill_supplies=true, fill_product=true, set_supplies=true, set_product=true },
    mc_documents = { complete_setup=true, clear_supplies=true, clear_product=true, fill_supplies=true, fill_product=true, set_supplies=true, set_product=true },
}

local function apply_live_action_policy(key, adapter)
    if type(adapter) ~= "table" then return end
    local rejected = LIVE_REJECTED_DIRECT_ACTIONS[key]
    if not rejected then return end

    local filtered = {}
    for _, action in ipairs(adapter.action_info or {}) do
        if not rejected[tostring(action.key)] then filtered[#filtered + 1] = action end
    end
    adapter.action_info = filtered
    for action_key in pairs(rejected) do
        if adapter.actions then adapter.actions[action_key] = nil end
    end

    local previous_refresh = adapter.refresh
    adapter.refresh = function(slot, core, status)
        local result = type(previous_refresh) == "function" and previous_refresh(slot, core, status) or {}
        if type(result) ~= "table" then result = {} end
        if key == "special_cargo" then
            result.can_mutate = false
            result.management_support = "Live read-only"
            result.reason = "Direct CEO warehouse crate writes are parked after repeated live read-back rejection. Warehouse ownership/capacity/cargo remain readable."
        elseif key == "nightclub" then
            result.management_support = "Partial - popularity live verified"
            if result.can_mutate == true then
                result.reason = "Nightclub popularity remains available. Direct warehouse-stock writes are parked after repeated live read-back rejection."
            end
        else
            result.management_support = "Rockstar resupply only"
            if result.can_mutate == true then
                result.reason = "Direct setup/supplies/product stat writes are parked after repeated live read-back rejection. Only the Rockstar freemode resupply flow remains promoted."
            end
        end
        return result
    end
end

for business_key, adapter in pairs(ADAPTERS) do apply_live_action_policy(business_key, adapter) end

economy = function()
    return module_context and module_context.CScript and module_context.CScript.Economy
end

local function current_business()
    return BUSINESS_BY_KEY[State.selected_business or "nightclub"] or BUSINESS_CATALOG[1]
end

local function unavailable_reason(item)
    return ("%s management is unavailable on the current Enhanced build because no safe read-and-verify contract has been validated."):format(item.name)
end

local function build_status(item)
    local adapter = ADAPTERS[item.key]
    local factory = item.factory_ids ~= nil or item.key == "bunker" or item.key == "acid_lab"
    local stock = factory or item.key == "nightclub" or item.key == "hangar"
        or item.key == "special_cargo" or item.key == "vehicle_cargo"
    return {
        key = item.key, name = item.name, group = item.group, class = item.class, fields = item.fields,
        owned = nil, ownership = "Unknown", status = "Unknown",
        stock = nil, supplies = nil, value = nil, capacity = nil,
        production = nil, time_remaining = nil, income_summary = nil,
        adapter = adapter and adapter.version or nil,
        actions = adapter and adapter.action_info or {},
        can_mutate = false,
        applicable_fields = { stock=stock, supplies=factory,
            production=factory or item.key == "nightclub", income=item.passive_income ~= nil,
            time_remaining=factory or item.passive_income ~= nil and item.passive_income.timer ~= nil },
        ownership_state = "UNKNOWN", read_state = "NOT_REFRESHED", mutation_state = "READ_ONLY",
        read_support = (item.signal or item.ownership_fields or item.read_fields or item.factory_ids) and "Read Only" or "Unavailable",
        management_support = "Unavailable",
        readouts = {}, read_values = {},
        recommended_action = (item.signal or item.ownership_fields or item.read_fields or item.factory_ids)
            and "Loading business state."
            or "Manage this business in GTA. CScript will not guess unsupported stock or sale state.",
        reason = "Loading business state.",
    }
end

local function refresh_business(key)
    local item = BUSINESS_BY_KEY[tostring(key)] or current_business()
    local status = build_status(item)
    local core = economy()
    if not core then status.reason = "Economy core is unavailable"; State.statuses[item.key] = status; return false, status.reason end
    local slot, slot_err = core.CurrentSlot()
    if slot ~= 0 and slot ~= 1 then
        status.reason = slot_err or "Character unavailable"
        State.statuses[item.key] = status
        return false, status.reason, "CONTEXT_CHANGED"
    end
    local statuses = State.statuses
    status.character_slot = slot

    -- These two named ownership signals are present in independently inspected
    -- stat catalogs. Zero remains "not detected", never a definitive unowned
    -- claim, because absent and zero-valued stats are not distinguishable here.
    if item.signal then
        local value, err = core.ReadStat(core.QualifyStat(slot, item.signal))
        status.raw_ownership_signal = value
        if value and value > 0 then
            status.owned, status.ownership, status.status = true, "Detected", "Owned signal detected"
            status.reason = "Ownership was detected. Stock and management actions are not yet validated on this Enhanced build."
        elseif value ~= nil then
            status.owned, status.ownership, status.status = nil, "Not detected", "Ownership signal is zero"
            status.reason = "A zero signal is not treated as proof that the property is unowned."
        else
            status.status = "Unavailable"
            status.raw_error = tostring(err)
            status.reason = "Ownership status is unavailable on the current Enhanced build."
        end
    end

    if item.ownership_fields then
        local ownership_reads, ownership_positive = 0, 0
        for _, ownership_key in ipairs(item.ownership_fields) do
            local value, err = core.ReadStat(core.QualifyStat(slot, ownership_key))
            if value ~= nil then
                ownership_reads = ownership_reads + 1
                status.read_values[ownership_key] = value
                if tonumber(value) and tonumber(value) > 0 then ownership_positive = ownership_positive + 1 end
            elseif not status.raw_error then status.raw_error = tostring(err) end
        end
        if ownership_positive > 0 then
            status.owned, status.ownership, status.status = true, "Detected", "Owned signal detected"
        elseif ownership_reads > 0 and status.owned ~= true then
            status.owned, status.ownership = nil, "Not detected"
        end
    end

    if item.factory_ids then
        local expected = {}; for _, id in ipairs(item.factory_ids) do expected[id] = true end
        local read_count, matched_slot = 0, nil
        for index = 0, 4 do
            local value = core.ReadStat(core.QualifyStat(slot, "FACTORYSLOT" .. tostring(index)))
            if type(value) == "number" and value == value and value % 1 == 0 and value >= 0 then
                read_count = read_count + 1
                if expected[tonumber(value)] then matched_slot = index; status.raw_ownership_signal = value; break end
            end
        end
        if matched_slot ~= nil then
            status.owned, status.ownership, status.status = true, "Detected", "Owned factory detected"
            status.read_support = "Read Only"
            status.factory_slot = matched_slot
            status.reason = "Ownership was detected from the current factory-slot assignment. Product and supply writes remain unavailable."
            for _, descriptor in ipairs({
                { prefix = "FACTORYSETUP", label = "Setup State" },
                { prefix = "MATTOTALFORFACTORY", label = "Supplies" },
                { prefix = "PRODTOTALFORFACTORY", label = "Product" },
                { prefix = "FACTORYUPGRADES", label = "Equipment Upgrade" },
                { prefix = "FACTORYUPGRADES", suffix = "_1", label = "Staff Upgrade" },
                { prefix = "FACTORYUPGRADES", suffix = "_2", label = "Security Upgrade" },
            }) do
                local stat = descriptor.prefix .. tostring(matched_slot) .. tostring(descriptor.suffix or "")
                local value, err = core.ReadStat(core.QualifyStat(slot, stat))
                if value ~= nil then
                    status.read_values[stat] = value
                    status.readouts[#status.readouts + 1] = { key = stat, label = descriptor.label,
                        value = value, display_value = value, confidence = "CURRENT_SOURCE_CORROBORATED" }
                else
                    status.readouts[#status.readouts + 1] = { key = stat, label = descriptor.label,
                        error = tostring(err), confidence = "UNAVAILABLE" }
                end
            end
        elseif read_count == 5 then
            status.owned, status.ownership, status.status = false, "Not owned", "No matching factory in all five verified slots"
            status.read_support = "Read Only"
            status.reason = "No matching MC factory is assigned in the five current factory slots."
        elseif read_count > 0 then
            status.owned, status.ownership, status.status = nil, "Unknown", "Factory ownership read incomplete"
            status.reason = "Some factory slots could not be read; ownership cannot be determined."
        end
    end

    -- The operation host validates the same live factory ownership used by
    -- production. Acid Lab is player bit14 + factory6 property32, not a named
    -- XM22_LAB_OWNED stat. Read-only inventory does not depend on edit support.
    local automation=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
    if (item.factory_ids or item.key=="bunker" or item.key=="acid_lab")
        and automation and type(automation.ReadBusiness)=="function" then
        local ok,row,why=pcall(automation.ReadBusiness,item.key)
        if ok and row and row.slot==slot then
            status.owned,status.ownership,status.status=true,"Detected","Owned factory detected"
            status.factory_slot=row.factory;status.raw_ownership_signal=row.property
            status.stock,status.capacity,status.supplies=row.stock,row.capacity,row.supplies
            status.ownership_source=item.key=="acid_lab" and "Player ownership bit14 + factory6 property32" or "Current factory assignment"
            status.read_error=row.read_error
        elseif item.key=="acid_lab" then
            status.owned,status.ownership=nil,"Not detected"
            status.ownership_error=tostring(ok and why or row)
        end
    end

    local readable, rejected = 0, 0
    for _, field in ipairs(item.read_fields or {}) do
        local value, err = core.ReadStat(core.QualifyStat(slot, field.key))
        if value ~= nil then
            readable = readable + 1
            status.read_values[field.key] = value
            status.readouts[#status.readouts + 1] = {
                key = field.key, label = field.label, value = value,
                display_value = value * (tonumber(field.scale) or 1),
                suffix = field.suffix, money = field.money == true,
                source08 = field.source08,
                confidence = field.confidence or "CURRENT_ENHANCED_SOURCE",
            }
        else
            rejected = rejected + 1
            status.readouts[#status.readouts + 1] = {
                key = field.key, label = field.label, error = tostring(err),
                confidence = "UNAVAILABLE",
            }
        end
    end
    if readable > 0 then
        status.read_support = "Read Only"
        status.status = status.owned == true and "Read-only state available" or status.status
        status.reason = ("Read-only state: %d field%s available; %d unavailable. Management support is evaluated separately.")
            :format(readable, readable == 1 and "" or "s", rejected)
    end

    if item.passive_income then
        status.passive_income = {
            safe_cash = item.passive_income.safe and tonumber(read_value(status, item.passive_income.safe)) or nil,
            payout_timer_raw = item.passive_income.timer and tonumber(read_value(status, item.passive_income.timer)) or nil,
            lifetime_earnings = item.passive_income.lifetime and tonumber(read_value(status, item.passive_income.lifetime)) or nil,
            safe_stat = item.passive_income.safe,
            timer_stat = item.passive_income.timer,
            lifetime_stat = item.passive_income.lifetime,
            server_authoritative = true,
            read_only = true,
            source = "Source 08 / current Enhanced mpstatssetup + owning scripts",
        }
    end

    if item.key == "special_cargo" then
        status.warehouse_capacities, status.warehouse_details = {}, {}
        local owned_count, total_capacity, standard_crates, special_crates = 0, 0, 0, 0
        for index = 0, 4 do
            local property = read_value(status, "PROP_WHOUSE_SLOT" .. tostring(index))
            local capacity = warehouse_capacity(property)
            if capacity then
                local standard = tonumber(read_value(status, "CONTOTALFORWHOUSE" .. tostring(index))) or 0
                local special = tonumber(read_value(status, "SPCONTOTALFORWHOUSE" .. tostring(index))) or 0
                status.warehouse_capacities[index] = capacity
                status.warehouse_details[index] = { property = tonumber(property), capacity = capacity,
                    standard = standard, special = special, total = standard + special }
                owned_count, total_capacity = owned_count + 1, total_capacity + capacity
                standard_crates, special_crates = standard_crates + standard, special_crates + special
            end
        end
        if owned_count > 0 then
            status.owned, status.ownership, status.status = true, "Detected", "Owned warehouse slots detected"
            status.capacity, status.stock = total_capacity, standard_crates + special_crates
            status.standard_crates, status.special_crates = standard_crates, special_crates
            status.reason = ("Detected %d owned warehouse slot%s: %d standard + %d special = %d / %d cargo.")
                :format(owned_count, owned_count == 1 and "" or "s", standard_crates, special_crates,
                    standard_crates + special_crates, total_capacity)
        end
    end

    if item.key == "vehicle_cargo" then
        local owned_signal = tonumber(status.raw_ownership_signal)
        local property_id = tonumber(read_value(status, "PROP_IE_WAREHOUSE"))
        local verification = tonumber(read_value(status, "PROP_IE_WAREHOUSE_VER"))
        local exported = tonumber(read_value(status, "VEHEXPORTED"))
        if (owned_signal and owned_signal > 0) or (property_id and property_id > 0) then
            status.owned, status.ownership, status.status = true, "Detected", "Vehicle Warehouse detected"
        end
        status.vehicle_cargo = {
            owned_signal = owned_signal, property_id = property_id,
            interior_variant = tonumber(read_value(status, "PROP_IE_WAREHOUSE_VAR")),
            ownership_verification = verification, vehicles_exported = exported,
            property_value = tonumber(read_value(status, "PROP_IE_WAREHOUSE_VALUE")),
            source_missions_started = tonumber(read_value(status, "LFETIME_IE_STEAL_STARTED")),
            export_missions_started = tonumber(read_value(status, "LFETIME_IE_EXPORT_STARTED")),
            export_missions_completed = tonumber(read_value(status, "LFETIME_IE_EXPORT_COMPLETED")),
            lifetime_earnings = tonumber(read_value(status, "LFETIME_IE_MISSION_EARNINGS")),
            sell_cooldown_raw = tonumber(read_value(status, "IMP_EXP_SELL_MISSION_CD")),
            server_authoritative = true,
        }
        status.management_support = "Read Only"
        status.can_mutate = false
        status.reason = status.owned == true
            and ("Vehicle Warehouse detected (property=%s, verification=%s, exported=%s). Inventory, sourcing and sales are read-only; their server-authoritative state has no validated edit adapter.")
                :format(tostring(property_id or "unknown"), tostring(verification or "unknown"), tostring(exported or "unknown"))
            or "Vehicle Cargo ownership/property diagnostics are readable. No warehouse inventory write is exposed."
    end

    if item.key == "bunker" then
        local supply_cap = add_capacity_contract(status, "supplies", "Supplies launch threshold")
        local product_cap = add_capacity_contract(status, "bunker_product", "Bunker product capacity")
        local supplies, product = tonumber(read_value(status, "MATTOTALFORFACTORY5")), tonumber(read_value(status, "PRODTOTALFORFACTORY5"))
        if supplies and supplies%1==0 and supplies>=0 and supplies<=200 then status.supplies=supplies end
        if product and product%1==0 and product>=0 and product<=1000 then status.stock=product end
        if product_cap then status.capacity=product_cap end
    elseif item.key == "acid_lab" then
        local supply_cap = add_capacity_contract(status, "supplies", "Supplies launch threshold")
        local product_cap = add_capacity_contract(status, "acid_product", "Acid Lab product capacity")
        local supplies, product = tonumber(read_value(status, "MATTOTALFORFACTORY6")), tonumber(read_value(status, "PRODTOTALFORFACTORY6"))
        if supplies and supplies%1==0 and supplies>=0 and supplies<=200 then status.supplies=supplies end
        if product and product%1==0 and product>=0 and product<=1000 then status.stock=product end
        if product_cap then status.capacity=product_cap end
    elseif item.factory_ids and status.factory_slot ~= nil then
        local supply_cap = add_capacity_contract(status, "supplies", "Supplies launch threshold")
        local product_cap = add_capacity_contract(status, item.key .. "_product", status.name .. " product capacity")
        local supplies = tonumber(read_value(status, "MATTOTALFORFACTORY" .. tostring(status.factory_slot)))
        local product = tonumber(read_value(status, "PRODTOTALFORFACTORY" .. tostring(status.factory_slot)))
        if supplies and supplies%1==0 and supplies>=0 and supplies<=200 then status.supplies=supplies end
        if product and product%1==0 and product>=0 and product<=1000 then status.stock=product end
        if product_cap then status.capacity=product_cap end
    elseif item.key == "nightclub" then
        local total, capacity, complete, capacity_complete = 0, 0, true, true
        for index = 0, 6 do
            local product = tonumber(read_value(status, "HUB_PROD_TOTAL_" .. tostring(index)))
            local cap = add_capacity_contract(status, "nightclub_" .. tostring(index), NIGHTCLUB_PRODUCT_NAMES[index + 1] .. " capacity")
            if product == nil then complete=false else total=total+product end
            if cap==nil then capacity_complete=false else capacity=capacity+cap end
        end
        if complete then status.stock=total end
        if capacity_complete then status.capacity=capacity end
    elseif item.key == "hangar" then
        local aggregate = tonumber(read_value(status, "HANGAR_CONTRABAND_TOTAL"))
        local inventory, inventory_err = read_hangar_inventory(status.character_slot)
        if inventory then
            status.stock, status.capacity = aggregate, inventory.capacity
            status.local_packed_stock=inventory.occupied
            status.stock_source="HANGAR_CONTRABAND_TOTAL"
            status.local_slots_are_accepted_stock=false
            status.readouts[#status.readouts+1]={key="HANGAR_LOCAL_PACKED_SLOTS",label="Local Packed Slots (not accepted cargo)",
                value=inventory.occupied,display_value=inventory.occupied,confidence="LOCAL_PROJECTION"}
            status.hangar_inventory = inventory
            status.hangar_profile = HANGAR_PACKED_PROFILE
            status.read_support = "Current Enhanced packed inventory"
            for _, name in ipairs(HANGAR_TYPE_ORDER) do
                status.readouts[#status.readouts + 1] = {
                    key = "HANGAR_TYPE_" .. name:gsub("[^%w]", "_"):upper(), label = name,
                    value = inventory.by_type[name] or 0, display_value = inventory.by_type[name] or 0,
                    confidence = "CURRENT_ENHANCED_SOURCE",
                }
            end
            local consistent = aggregate == nil or aggregate == inventory.occupied
            status.cargo_contract = {
                aggregate_read = aggregate ~= nil, packed_slots_read = true, type_breakdown = true,
                aggregate_matches_slots = consistent, mutation = false, local_mutation = true, occupied = inventory.occupied,
                aggregate = aggregate, source_revision = HANGAR_PACKED_PROFILE.source_revision,
                evidence = HANGAR_PACKED_PROFILE.evidence,
                persistent_slot_write = "STATS::SET_PACKED_STAT_INT_CODE(16011..16060)",
                aggregate_stat = "HANGAR_CONTRABAND_TOTAL", aggregate_server_authoritative = true,
                transaction_category = "CATEGORY_CONTRABAND_QNTY",
                transaction_item = "MP_STAT_HANGAR_CONTRABAND_TOTAL_v0",
                transaction_type = 78225582,
                transaction_action = -886368739,
                transaction_basket_flags = 4,
                transaction_item_data = "{ item=MP_STAT_HANGAR_CONTRABAND_TOTAL_v0, aux=0, value0=0, value1=1 }",
                transaction_transport = "NET_GAMESERVER_BASKET_START / NET_GAMESERVER_BASKET_ADD_ITEM",
                transaction_manager = "Global_4515492[15 /*84*/] + self-directed TU transaction event -710178565",
                transaction_result = "manager state 1=pending; 2=success; non-2 terminal=failure; func_265 cleanup",
                comparable_flows = "Bunker, Acid Lab and CEO warehouse flows reuse NETSHOPPING primitives but carry different category/item/service payloads and lifecycle owners; they are evidence for the transport pattern, not interchangeable Hangar transactions.",
                transaction_readiness = {
                    readable = false, bypassed = true,
                    reason = "The local slot editor uses packed Hangar stats with per-slot readback. It does not reserve the shared transaction manager.",
                },
                live_trace = {
                    reference = "Silent Night 1.13.1 Enhanced Supporter / 2026-08-18",
                    supplier = "Observed 0 -> 14 -> 27 occupied slots via 16011..16060",
                    remove = "Observed 27 -> 0 after Silent Night Remove + session reconciliation",
                    cadence_ms = 809,
                },
                payout_reconciliation = {
                    packed_stock = inventory.occupied,
                    server_aggregate = aggregate,
                    reconciled = aggregate ~= nil and aggregate == inventory.occupied,
                    payout_ready = false, -- A matching count is not a verified sale or accepted grant.
                    note = "GTA reconciles packed slots to the accepted aggregate. Matching counts do not verify sale readiness or a new cargo grant.",
                },
                reconciliation = { direction="accepted_total_to_local_slots",
                    source="appsmuggler.c func_415 lines 28160..28237",
                    rule="Delete excess packed slots; populate missing packed slots from the accepted total. Never promote local slots into accepted cargo." },
                missing = { "An accepted cargo grant requires the owning sourcing transaction; local slot writes do not provide it." },
            }
            status.status = "Cargo inventory mapped"
            if inventory.invalid > 0 then
                status.reason = ("Hangar inventory contains %d unrecognized slot value(s); local editing is unavailable."):format(inventory.invalid)
            elseif not consistent then
                status.reason = ("Local Hangar slots=%d while aggregate=%s. Current controls edit local slots only; authoritative storage and reconciliation remain unverified.")
                    :format(inventory.occupied, tostring(aggregate))
            else
                status.reason = ("Local Hangar inventory: %d / %d slots across eight Air Freight families. The local editor does not provide reserve storage or cargo sales.")
                    :format(inventory.occupied, inventory.capacity)
            end
        else
            status.stock, status.capacity = aggregate, HANGAR_PACKED_PROFILE.capacity
            status.cargo_contract = { aggregate_read = aggregate ~= nil, packed_slots_read = false,
                type_breakdown = false, mutation = false, error = tostring(inventory_err),
                source_revision = HANGAR_PACKED_PROFILE.source_revision, evidence = HANGAR_PACKED_PROFILE.evidence,
                missing = { "GET_PACKED_STAT_INT_CODE current-character read availability" } }
            status.reason = "Hangar aggregate cargo is readable, but packed-slot inventory could not be resolved: " .. tostring(inventory_err)
        end
    end

    local adapter = ADAPTERS[item.key]
    local refresh_ok = true
    if adapter and type(adapter.refresh) == "function" then
        local ok, result = pcall(adapter.refresh, slot, core, status)
        if ok and type(result) == "table" then
            for key_name, value in pairs(result) do status[key_name] = value end
        else
            status.status, status.reason = "Error", "Adapter refresh failed: " .. tostring(result)
            status.raw_error = tostring(result)
            refresh_ok = false
        end
    end
    local final_slot = core.CurrentSlot()
    if State.statuses ~= statuses or final_slot ~= slot then
        return false, "Character/session changed during business refresh; stale results discarded.", "CONTEXT_CHANGED"
    end
    status.ownership_state = status.owned == true and "OWNED" or status.owned == false and "NOT_OWNED"
        or status.ownership == "Not detected" and "NOT_DETECTED" or "UNKNOWN"
    local readable_row = false
    for _, row in ipairs(status.readouts or {}) do if row.value ~= nil then readable_row = true; break end end
    status.read_state = (next(status.read_values or {}) ~= nil or status.raw_ownership_signal ~= nil
        or readable_row) and "READ_ONLY" or "UNAVAILABLE"
    status.can_mutate = status.can_mutate == true and status.owned == true
    status.mutation_state = status.can_mutate == true and "READY_TO_APPLY" or "READ_ONLY"
    if item.passive_income and item.passive_income.safe then
        local cash = tonumber(status.read_values[item.passive_income.safe])
        if cash and cash == cash and cash >= 0 and cash < math.huge then
            status.income_summary = "Safe $" .. tostring(math.floor(cash))
        end
    end
    status.field_states = {}
    for field, applicable in pairs(status.applicable_fields) do
        local value = status[field == "income" and "income_summary" or field]
        status.field_states[field] = not applicable and "NOT_APPLICABLE"
            or value ~= nil and "READ" or "UNAVAILABLE"
    end
    status.refreshed_at = os and os.time and os.time() or 0
    State.statuses[item.key] = status
    if State.selected_business == item.key then
        State.next_visible_refresh_ms = (State.clock_ms or 0) + 5000
    end
    return refresh_ok, status.reason
end

local function source_coverage_summary()
    local fields, properties = 0, 0
    for _, item in ipairs(BUSINESS_CATALOG) do
        properties = properties + 1
        fields = fields + #(item.read_fields or {}) + #(item.ownership_fields or {}) + (item.signal and 1 or 0)
    end
    return {
        properties = properties,
        named_stat_fields = fields,
        source_revision = "GTA Online Enhanced 1.73 / 1158.13 consolidated source + Source05/06 semantics",
        mutation_policy = "Read everything source-backed; mutate only through validated owner/lifecycle adapters.",
    }
end

local function refresh_all()
    State.machine_state = "CHECK_STATUS"
    local detected, failures = 0, 0
    for _, item in ipairs(BUSINESS_CATALOG) do
        local ok = refresh_business(item.key)
        if ok then detected = detected + 1 else failures = failures + 1 end
    end
    State.last_refresh_ms = State.clock_ms or 0
    State.last_refresh_epoch = os and os.time and os.time() or 0
    State.machine_state = failures == 0 and "READY" or "WAIT"
    return true, { detected = detected, unavailable = failures }
end

-- Render requests only flag work. Readiness retries use 250/500/1000/2000ms
-- backoff (capped), with at most one live cursor and one property per slice.
local function request_main_refresh(force)
    if State.main_scan then return true end
    if State.main_refresh_requested then
        if force then State.main_wait = nil end -- next tick bypasses readiness backoff
        return true
    end
    if not force and State.main_requested_generation == State.generation then return true end
    State.main_requested_generation = State.generation
    State.main_refresh_requested = true
    State.main_refresh_completed = 0
    State.main_refresh_error, State.main_wait = nil, nil
    return true
end

local function clear_action_intent()
    State.target_percent,State.target_index_by_business,State.last_action=50,{},nil
end

local function cancel_main_context()
    clear_action_intent()
    State.main_scan, State.main_refresh_requested, State.main_wait = nil, false, nil
    State.main_requested_generation = nil
    State.statuses = {}
    State.generation = State.generation + 1
    State.main_refresh_completed = 0
    State.main_refresh_error = "Updating for the current session."
end

local function wait_main_character(now)
    -- Losing a bound character invalidates partial results and queued action
    -- generations. A new ready character must start from an empty cursor.
    if State.main_scan then cancel_main_context() end
    local delay = math.min(2000, (State.main_wait and State.main_wait.delay_ms or 125) * 2)
    State.main_wait = { next_ms=now+delay, delay_ms=delay }
    State.main_refresh_requested = true
    State.main_requested_generation = State.generation
    State.main_refresh_error = nil
end

local function tick_main_refresh(now)
    if not State.main_scan and not State.main_refresh_requested then return false end
    if State.main_wait and now<State.main_wait.next_ms then return true end
    local core = economy()
    local generation = State.generation
    local ok, slot = false, nil
    if core and type(core.CurrentSlot)=="function" then ok,slot=pcall(core.CurrentSlot) end
    if generation~=State.generation or not started then return true end
    if not ok or (slot~=0 and slot~=1) then
        wait_main_character(now)
        return true
    end
    State.main_wait = nil
    if State.main_refresh_requested then
        State.main_refresh_requested = false
        State.main_scan = { index=1, next_ms=now, generation=State.generation, slot=slot }
    end
    local scan = State.main_scan
    if scan.generation~=State.generation or scan.slot~=slot then
        cancel_main_context()
        return true
    end
    if now<scan.next_ms then return true end
    local item = MAIN_CATALOG[scan.index]
    local read_ok, result, detail, disposition = pcall(refresh_business,item.key)
    if State.main_scan ~= scan or State.generation ~= scan.generation then return true end
    if disposition=="CONTEXT_CHANGED" then
        cancel_main_context()
        return true
    end
    if not read_ok then
        State.main_refresh_error = tostring(result)
        State.main_scan = nil
        return true
    end
    State.main_refresh_completed = scan.index
    scan.index,scan.next_ms = scan.index+1,now+250
    if scan.index>#MAIN_CATALOG then
        State.main_scan=nil
        State.last_refresh_ms=now
        State.last_refresh_epoch=os and os.time and os.time() or 0
    end
    return true
end

local function select_business(key)
    if not BUSINESS_BY_KEY[tostring(key)] then return false end
    if State.selected_business ~= tostring(key) then
        State.selection_generation = (State.selection_generation or 0) + 1
    end
    State.selected_business = tostring(key)
    State.next_visible_refresh_ms = 0
    return true
end

local function run_action(action)
    local request = type(action) == "table" and action or { key = action }
    action = request.key
    local item = current_business()
    local adapter = ADAPTERS[item.key]
    if not adapter or adapter.mutation_validated ~= true then return false, unavailable_reason(item) end
    local refreshed, refresh_error = refresh_business(item.key)
    if not refreshed then return false, refresh_error end
    local status = State.statuses[item.key]
    if not status or status.owned ~= true then return false, "business ownership is not validated" end
    if request.expected_slot ~= nil and status.character_slot ~= request.expected_slot then
        return false, "Character changed after the action was queued."
    end
    if status.can_mutate ~= true then return false, status.reason or "this business action is not mutation-ready" end
    local handler = adapter.actions and adapter.actions[tostring(action)]
    if type(handler) ~= "function" then return false, "this action is not available for " .. item.name end
    return handler(status.character_slot, economy(), status, request)
end

local function pocket_state()
    State.hangar_pocket = State.hangar_pocket or {
        delay_ms = HANGAR_POCKET_DEFAULTS.delay_ms,
        step = HANGAR_POCKET_DEFAULTS.step,
        limit = HANGAR_POCKET_DEFAULTS.limit,
        type_index = HANGAR_POCKET_DEFAULTS.type_index,
        fast_mode = HANGAR_POCKET_DEFAULTS.fast_mode,
        running = false, mode = "idle", next_ms = 0, pending = nil,
        cycle_remaining = 0, writes = 0, last_result = "Idle", last_ok = true,
    }
    return State.hangar_pocket
end

local function pocket_log(message)
    local logger = module_context and module_context.Logger
    if logger and type(logger.Info) == "function" then
        logger.Info("Pocket Dimension: " .. tostring(message), "Businesses")
    end
end

local function stop_hangar_pocket(ok, detail)
    local pocket = pocket_state()
    if ok ~= false and type(pocket.pending) == "table" then
        local observed, err = read_packed_int(pocket.pending.index, pocket.scope and pocket.scope.slot)
        if observed ~= pocket.pending.value then
            ok = false
            detail = ("Stop verification failed at packed slot %d: requested %s, observed %s (%s).")
                :format(pocket.pending.index, tostring(pocket.pending.value), tostring(observed), tostring(err or "mismatch"))
        end
    end
    pocket.running = false
    pocket.mode = "idle"
    pocket.pending = nil
    pocket.cycle_remaining = 0
    pocket.last_ok = ok ~= false -- Local operation result only, never a cargo grant.
    pocket.result_kind = ok == false and "ERROR" or "LOCAL_ONLY"
    pocket.accepted_stock_verified = false
    local status=State.statuses and State.statuses.hangar
    pocket.accepted_stock=status and status.stock or nil
    pocket.local_slots=status and status.local_packed_stock or nil
    pocket.last_result = tostring(detail or (ok == false and "Stopped with an error" or "Stopped"))
    pocket_log(pocket.last_result)
    return pocket.last_ok, pocket.last_result
end

local function set_hangar_pocket_delay(value)
    local pocket = pocket_state()
    value = math.floor(tonumber(value) or HANGAR_POCKET_DEFAULTS.delay_ms)
    pocket.delay_ms = math.max(10, math.min(5000, value))
    return pocket.delay_ms
end

local function set_hangar_pocket_step(value)
    local pocket = pocket_state()
    value = math.floor(tonumber(value) or HANGAR_POCKET_DEFAULTS.step)
    pocket.step = math.max(1, math.min(50, value))
    return pocket.step
end

local function set_hangar_pocket_limit(value)
    local pocket = pocket_state()
    value = math.floor(tonumber(value) or HANGAR_POCKET_DEFAULTS.limit)
    -- Keep local writes within the physical slot capacity.
    pocket.limit = math.max(0, math.min(50, value))
    return pocket.limit
end

local function set_hangar_pocket_fast(value)
    local pocket = pocket_state()
    pocket.fast_mode = value == true
    return pocket.fast_mode
end

local function effective_hangar_limit(pocket)
    local limit = math.floor(tonumber(pocket and pocket.limit) or 0)
    if limit <= 0 then return HANGAR_PACKED_PROFILE.capacity end
    return math.max(1, math.min(HANGAR_PACKED_PROFILE.capacity, limit))
end

local function set_hangar_pocket_type(value)
    local pocket = pocket_state()
    value = math.floor(tonumber(value) or HANGAR_POCKET_DEFAULTS.type_index)
    pocket.type_index = math.max(1, math.min(#HANGAR_TYPE_ORDER, value))
    return pocket.type_index
end

local function hangar_pocket_ready()
    refresh_business("hangar")
    local status = State.statuses and State.statuses.hangar
    if not status or status.owned ~= true then return nil, "Owned Hangar could not be validated." end
    if status.can_mutate ~= true then return nil, status.reason or "Hangar packed mutation is not ready." end
    local inventory = status.hangar_inventory
    if type(inventory) ~= "table" then return nil, "Hangar packed inventory is unavailable." end
    if (tonumber(inventory.invalid) or 0) > 0 then return nil, "Hangar contains an unrecognized packed cargo value." end
    return status
end

local function hangar_operation_scope(status)
    local core = economy()
    local scope = core and core.Snapshot and core.Snapshot()
    local slot = core and core.CurrentSlot and core.CurrentSlot()
    if not scope or scope.account_verified ~= true or scope.online ~= true
        or scope.account_id == nil or scope.generation == nil
        or (slot ~= 0 and slot ~= 1) or slot ~= status.character_slot then
        return nil, "Hangar character or session is unavailable."
    end
    return { account=scope.account_id, generation=scope.generation, slot=slot }
end

local function start_hangar_pocket()
    local reserve=module_context and module_context.CScript and module_context.CScript.HangarPocket
    local reserve_state=reserve and reserve.Snapshot and reserve.Snapshot()
    if reserve_state and (reserve_state.running or reserve_state.cleanup_pending or reserve_state.action and reserve_state.action.busy) then return false,"The aggregate cargo supplier owns this Hangar; stop it before editing local slots." end
    local status, err = hangar_pocket_ready()
    if not status then return false, err end
    local pocket = pocket_state()
    if pocket.running then return false, "Pocket Dimension is already running." end
    local occupied = tonumber(status.hangar_inventory and status.hangar_inventory.occupied) or 0
    local target_limit = effective_hangar_limit(pocket)
    if occupied >= target_limit then
        return false, ("Local slots already contain %d entries (target %d). This does not mean accepted cargo is full; use Fast Staff Sourcing for cargo from paid orders."):format(occupied, target_limit)
    end
    local scope, why = hangar_operation_scope(status)
    if not scope then return false, why end
    pocket.scope = scope
    pocket.accepted_stock=status.stock; pocket.local_slots=occupied
    pocket.accepted_stock_verified=false; pocket.result_kind="LOCAL_ONLY"
    pocket.running = true
    pocket.mode = "supplier"
    pocket.next_ms = tonumber(State.clock_ms) or 0
    pocket.pending = nil
    pocket.cycle_remaining = 0
    pocket.writes = 0
    pocket.start_occupied = occupied
    pocket.last_ok = true
    pocket.result_kind = "LOCAL_ONLY"
    pocket.accepted_stock_verified = false
    pocket.last_result = ("Local slot editing running: %s, step=%d, target=%s, delay=%dms, mode=%s. This operation does not add accepted cargo.")
        :format(HANGAR_TYPE_ORDER[pocket.type_index], pocket.step,
            pocket.limit <= 0 and "local capacity 50" or tostring(target_limit), pocket.delay_ms,
            pocket.fast_mode and "FAST" or "Local readback")
    pocket_log(pocket.last_result)
    return true, pocket.last_result
end

local function remove_hangar_stock()
    local status, err = hangar_pocket_ready()
    if not status then return false, err end
    local pocket = pocket_state()
    if pocket.running then return false, "Stop the active Pocket Dimension supplier before removing stock." end
    if (tonumber(status.hangar_inventory and status.hangar_inventory.occupied) or 0) <= 0 then
        return false, "Hangar packed inventory is already empty."
    end
    local scope, why = hangar_operation_scope(status)
    if not scope then return false, why end
    pocket.scope = scope
    pocket.accepted_stock=status.stock; pocket.local_slots=status.hangar_inventory.occupied
    pocket.accepted_stock_verified=false; pocket.result_kind="LOCAL_ONLY"
    pocket.running = true
    pocket.mode = "remove"
    pocket.next_ms = tonumber(State.clock_ms) or 0
    pocket.pending = nil
    pocket.cycle_remaining = 0
    pocket.writes = 0
    pocket.last_ok = true
    pocket.last_result = "Clearing local slots only. Accepted cargo is not removed by this operation; GTA may restore its local representation."
    pocket_log(pocket.last_result)
    return true, pocket.last_result
end

local function next_hangar_slot(inventory, want_empty)
    if type(inventory) ~= "table" then return nil end
    for offset = 0, HANGAR_PACKED_PROFILE.count - 1 do
        local value = tonumber(inventory.slots and inventory.slots[offset + 1]) or 0
        if (want_empty and value == 0) or ((not want_empty) and value ~= 0) then
            return HANGAR_PACKED_PROFILE.first + offset, value, offset + 1
        end
    end
    return nil
end

local function next_hangar_type_value(pocket, slot_offset)
    local variants = HANGAR_TYPE_VARIANTS[pocket.type_index] or HANGAR_TYPE_VARIANTS[1]
    -- Alternate the two Rockstar variants within the selected cargo family.
    local selector = ((tonumber(pocket.writes) or 0) % #variants) + 1
    return variants[selector]
end

local function tick_hangar_pocket(now)
    local pocket = pocket_state()
    if pocket.running ~= true then return end
    now = math.max(0, tonumber(now) or 0)
    local current = pocket.scope and hangar_operation_scope({character_slot=pocket.scope.slot})
    if not current or current.account ~= pocket.scope.account or current.generation ~= pocket.scope.generation then
        return stop_hangar_pocket(false, "Hangar fill stopped because the account, character or session changed.")
    end

    -- FAST mode polls the outstanding write and advances immediately after
    -- exact readback. It never permits a second write while one is pending.
    if type(pocket.pending) == "table" then
        if now < (tonumber(pocket.pending.next_verify_ms) or 0) then return end
        local observed, err = read_packed_int(pocket.pending.index, pocket.scope.slot)
        if observed ~= pocket.pending.value then
            if now < (tonumber(pocket.pending.deadline_ms) or 0) then
                pocket.pending.next_verify_ms = now + (pocket.fast_mode
                    and HANGAR_POCKET_DEFAULTS.verify_poll_ms or HANGAR_POCKET_DEFAULTS.normal_verify_ms)
                return
            end
            return stop_hangar_pocket(false, ("Readback timed out at packed slot %d: requested %s, observed %s (%s). Supplier stopped before another write.")
                :format(pocket.pending.index, tostring(pocket.pending.value), tostring(observed), tostring(err or "mismatch")))
        end
        pocket.writes = (tonumber(pocket.writes) or 0) + 1
        pocket.pending = nil
        if pocket.mode == "supplier" then
            local target_limit = effective_hangar_limit(pocket)
            -- Count the entire inventory after the final write. Earlier slots may
            -- have been reverted by GTA; write-count arithmetic is not stock.
            pocket.cycle_remaining = math.max(0, (tonumber(pocket.cycle_remaining) or 0) - 1)
            if pocket.fast_mode then
                pocket.next_ms = now + (pocket.cycle_remaining > 0 and 0 or pocket.delay_ms)
            else
                pocket.next_ms = now + (pocket.cycle_remaining > 0
                    and HANGAR_POCKET_DEFAULTS.normal_intra_step_ms or pocket.delay_ms)
            end
        else
            pocket.next_ms = pocket.fast_mode and now or (now + HANGAR_POCKET_DEFAULTS.normal_intra_step_ms)
        end
        return
    end
    if now < (tonumber(pocket.next_ms) or 0) then return end

    local inventory, inventory_err = read_hangar_inventory(pocket.scope.slot)
    if not inventory then return stop_hangar_pocket(false, "Hangar inventory read failed: " .. tostring(inventory_err)) end
    if (tonumber(inventory.invalid) or 0) > 0 then
        return stop_hangar_pocket(false, "Unknown packed cargo value appeared; Pocket Dimension stopped before another write.")
    end

    if pocket.mode == "remove" then
        local index = next_hangar_slot(inventory, false)
        if not index then
            refresh_business("hangar")
            return stop_hangar_pocket(true, ("Local slot clearing finished after %d verified writes. This does not confirm removal of accepted cargo; GTA may restore the slots.")
                :format(tonumber(pocket.writes) or 0))
        end
        if (tonumber(pocket.writes) or 0) >= HANGAR_PACKED_PROFILE.capacity * 2 then
            return stop_hangar_pocket(false, "GTA restored cargo while removing; stopped after 100 verified writes.")
        end
        local ok, err = request_packed_int_write(index, 0, pocket.scope.slot)
        if not ok then return stop_hangar_pocket(false, err) end
        pocket.pending = {
            index = index, value = 0,
            next_verify_ms = now + (pocket.fast_mode and HANGAR_POCKET_DEFAULTS.verify_poll_ms or HANGAR_POCKET_DEFAULTS.normal_verify_ms),
            deadline_ms = now + HANGAR_POCKET_DEFAULTS.verify_timeout_ms,
        }
        return
    end

    if pocket.mode ~= "supplier" then return stop_hangar_pocket(false, "Unknown Pocket Dimension mode.") end
    local occupied = tonumber(inventory.occupied) or 0
    local target_limit = effective_hangar_limit(pocket)
    if occupied >= target_limit or occupied >= HANGAR_PACKED_PROFILE.capacity then
        refresh_business("hangar")
        return stop_hangar_pocket(true, ("Local slot editing finished: %d slots (target %d), %d verified writes. Accepted cargo was not granted by this operation. Use Fast Staff Sourcing for paid cargo orders.")
            :format(occupied, target_limit, tonumber(pocket.writes) or 0))
    end
    if (tonumber(pocket.cycle_remaining) or 0) <= 0 then
        pocket.cycle_remaining = math.min(pocket.step, target_limit - occupied, HANGAR_PACKED_PROFILE.capacity - occupied)
    end
    if (tonumber(pocket.writes) or 0) >= HANGAR_PACKED_PROFILE.capacity * 2 then
        return stop_hangar_pocket(false, "GTA reverted cargo while filling; stopped after 100 verified writes. Accepted cargo remains unverified.")
    end
    local index, _, slot_offset = next_hangar_slot(inventory, true)
    if not index then return stop_hangar_pocket(true, "All local slots are occupied. This is not confirmation that accepted cargo is full.") end
    local cargo_value = next_hangar_type_value(pocket, slot_offset)
    local ok, err = request_packed_int_write(index, cargo_value, pocket.scope.slot)
    if not ok then return stop_hangar_pocket(false, err) end
    pocket.pending = {
        index = index, value = cargo_value,
        next_verify_ms = now + (pocket.fast_mode and HANGAR_POCKET_DEFAULTS.verify_poll_ms or HANGAR_POCKET_DEFAULTS.normal_verify_ms),
        deadline_ms = now + HANGAR_POCKET_DEFAULTS.verify_timeout_ms,
    }
end

local function resupply_all_supported()
    local targets, skipped = {}, 0
    for _, item in ipairs(BUSINESS_CATALOG) do
        local adapter = ADAPTERS[item.key]
        if adapter and adapter.mutation_validated == true and adapter.actions
            and type(adapter.actions.resupply) == "function" then
            -- Refresh the candidate first so the bulk action never relies on
            -- a stale ownership/factory-slot snapshot.
            refresh_business(item.key)
            local status = State.statuses and State.statuses[item.key]
            if status and status.owned == true and status.can_mutate == true then
                targets[#targets + 1] = item.key
            else
                skipped = skipped + 1
            end
        end
    end
    if #targets == 0 then
        return false, "No owned, mutation-ready MC/Bunker/Acid business was available for Rockstar resupply."
    end
    -- The Business scheduler advances one resupply target every three seconds.
    State.bulk_resupply = {
        targets = targets,
        index = 1,
        next_ms = tonumber(State.clock_ms) or 0,
        armed = 0,
        failed = {},
        skipped = skipped,
    }
    return true, ("Queued Rockstar resupply for %d business(es); one request will be armed every 3 seconds."):format(#targets)
end

local function tick_bulk_resupply(now)
    local bulk = State.bulk_resupply
    if type(bulk) ~= "table" then return end
    if now < (tonumber(bulk.next_ms) or 0) then return end
    local key = bulk.targets and bulk.targets[bulk.index]
    if not key then
        State.last_action = {
            ok = #(bulk.failed or {}) == 0,
            key = "resupply_all",
            detail = #(bulk.failed or {}) == 0
                and ("Rockstar resupply armed for %d business(es); %d unavailable business(es) skipped."):format(bulk.armed or 0, bulk.skipped or 0)
                or ("Rockstar resupply armed for %d business(es); failures: %s"):format(bulk.armed or 0, table.concat(bulk.failed, " | ")),
        }
        State.bulk_resupply = nil
        return
    end
    refresh_business(key)
    local status = State.statuses and State.statuses[key]
    local adapter = ADAPTERS[key]
    local ok, detail = false, "business is no longer mutation-ready"
    if status and status.owned == true and status.can_mutate == true and adapter and adapter.actions
        and type(adapter.actions.resupply) == "function" then
        ok, detail = adapter.actions.resupply(status.character_slot, economy(), status, { key = "resupply" })
    end
    if ok then
        bulk.armed = (bulk.armed or 0) + 1
    else
        bulk.failed[#bulk.failed + 1] = tostring(status and status.name or key) .. ": " .. tostring(detail)
    end
    bulk.index = bulk.index + 1
    bulk.next_ms = now + 3000
end

local function needs_attention()
    local result = {}
    for _, item in ipairs(BUSINESS_CATALOG) do
        local status = State.statuses[item.key]
        if status and (status.status == "Error"
            or (tonumber(status.supplies) and tonumber(status.supplies) < 25)
            or (tonumber(status.stock) and tonumber(status.capacity)
                and tonumber(status.stock) >= tonumber(status.capacity))) then
            result[#result + 1] = status
        end
    end
    return result
end

local function set_auto_refresh(value)
    State.auto_refresh = value == true
    if State.auto_refresh then
        State.machine_state = "WAIT"
        State.next_refresh_ms = 0
    elseif State.automation_running ~= true then State.machine_state = "IDLE" end
    return true
end

local function start_automation()
    State.automation_running = true
    State.auto_refresh = true
    State.machine_state, State.next_refresh_ms = "CHECK_STATUS", 0
    return true
end

local function stop_automation()
    State.automation_running, State.auto_refresh = false, false
    State.machine_state, State.next_refresh_ms = "IDLE", 0
    return true
end

local function tick_runtime(now)
    if not started then return end
    local farm_now=tonumber(now)
    if bunker_farm and bunker_farm.active and (not farm_now or farm_now~=farm_now or farm_now<0
        or farm_now==math.huge or farm_now<(bunker_farm.clock_ms or bunker_farm.started_ms or 0)) then
        bunker_farm_fail("Bunker Auto Farm stopped: runtime clock boundary changed.")
        return
    end
    if bunker_farm and bunker_farm.active then bunker_farm.clock_ms=farm_now end
    now = math.max(0, tonumber(now) or 0)
    State.clock_ms = now
    tick_farm_finish_requests()
    tick_sale_finish(now)
    local reserve=module_context and module_context.CScript and module_context.CScript.HangarPocket
    if reserve and type(reserve.Tick)=="function" then reserve.Tick(now) end
    if State.app_runtime_ms ~= now then
        State.app_runtime_ms = now
        tick_bunker_app_sale(now)
        if mc_app_engine then mc_app_engine.Tick(now) end
        tick_hangar_pocket(now)
    end
    -- Farm controllers must run while account storage is retrying. Their own
    -- readers verify account/session/character identity before acting. Keep the
    -- same frame deduplication with the slower refresh Tick. Readiness is
    -- checked every runtime frame rather than at a fixed one-second poll.
    if State.farm_runtime_ms~=now then
        State.farm_runtime_ms=now
        tick_bunker_farm(now)
        if bunker_farm and (bunker_farm.active or bunker_farm.report_phase~=bunker_farm.phase) then
            local reason=bunker_farm.reason or bunker_farm.wait_reason
                or ("stock=%s/%s supplies=%s"):format(tostring(bunker_farm.last_stock),
                    tostring(bunker_farm.capacity or "full"),tostring(bunker_farm.last_supplies))
            local report_reason=bunker_farm.reason or bunker_farm.wait_reason or ""
            if bunker_farm.report_phase~=bunker_farm.phase or bunker_farm.report_reason~=report_reason
                or now-(bunker_farm.report_ms or now)>=5000 then
                bunker_farm.report_phase,bunker_farm.report_reason,bunker_farm.report_ms=bunker_farm.phase,report_reason,now
                local logger=module_context and module_context.Logger
                if logger and type(logger.Info)=="function" then
                    logger.Info("phase="..bunker_farm.phase.." reason="..tostring(reason),"BunkerFarm")
                end
            end
        end
        for _,farm in pairs(mc_farms) do farm.Tick(now) end
    end
end

local function tick(now)
    if not started then return end
    now = math.max(0, tonumber(now) or 0)
    State.clock_ms = now
    tick_bunker_sale_start(now)
    tick_runtime(now)
    local action = table.remove(State.action_queue, 1)
    if action then
        if action.key == "refresh_selected" then refresh_business(State.selected_business)
        elseif action.key == "refresh_main" then request_main_refresh(true)
        elseif action.key == "refresh_all" then refresh_all()
        elseif action.key == "resupply_all" then
            local ok, result = resupply_all_supported()
            State.last_action = { ok = ok == true, key = "resupply_all", detail = tostring(result or "") }
            if not ok and module_context.Notifications and type(module_context.Notifications.Warning) == "function" then
                module_context.Notifications.Warning(tostring(result or "Bulk resupply could not start."), 6500)
            end
        elseif action.key == "complete_active_sale" then
            local ok, result = request_sale_finish()
            State.last_action = { ok = ok == true, key = "complete_active_sale", detail = tostring(result or "") }
            local notifications = module_context.Notifications
            if notifications then
                local callback = ok and notifications.Success or notifications.Warning
                if type(callback) == "function" then callback(tostring(result or "Active sale action finished."), 6500) end
            end
        elseif action.key == "solo_mc_routes" then
            local ok, result = set_solo_mc_routes(action.value == true)
            State.last_action = { ok = ok == true, key = "solo_mc_routes", detail = tostring(result or "") }
            local notifications = module_context.Notifications
            if notifications then
                local callback = ok and notifications.Success or notifications.Warning
                if type(callback) == "function" then callback(tostring(result or "Solo MC route action finished."), 6500) end
            end
        elseif action.key == "run" then
            local captured = action.context
            local ok, result = false, "Business selection/context changed; apply again."
            if captured and captured.generation == State.generation
                and captured.selection == (State.selection_generation or 0)
                and captured.business == State.selected_business then
                local core = economy()
                local read_ok, slot = pcall(core.CurrentSlot)
                if read_ok and slot == captured.slot then ok, result = run_action(action.value) end
            end
            State.last_action = { ok = ok == true, key = tostring(action.value or ""), detail = tostring(result or "") }
            if ok then refresh_business(State.selected_business) end
            if not ok and module_context.Notifications and type(module_context.Notifications.Warning) == "function" then
                module_context.Notifications.Warning(tostring(result or "Business action failed."), 6500)
            end
        elseif action.key == "hangar_pocket_start" then
            local ok, result = start_hangar_pocket()
            State.last_action = { ok = ok == true, key = "hangar_pocket_start", detail = tostring(result or "") }
            if not ok and module_context.Notifications and type(module_context.Notifications.Warning) == "function" then
                module_context.Notifications.Warning(tostring(result or "Pocket Dimension could not start."), 6500)
            end
        elseif action.key == "hangar_pocket_stop" then
            local ok, result = stop_hangar_pocket(true, "Pocket Dimension stopped by user.")
            State.last_action = { ok = ok == true, key = "hangar_pocket_stop", detail = tostring(result or "") }
            refresh_business("hangar")
        elseif action.key == "hangar_pocket_remove" then
            local ok, result = remove_hangar_stock()
            State.last_action = { ok = ok == true, key = "hangar_pocket_remove", detail = tostring(result or "") }
            if not ok and module_context.Notifications and type(module_context.Notifications.Warning) == "function" then
                module_context.Notifications.Warning(tostring(result or "Hangar stock removal could not start."), 6500)
            end
        elseif module_context.Logger then
            module_context.Logger.Error("Unknown queued Business action: " .. tostring(action.key), "Businesses")
        end
    end
    tick_bulk_resupply(now)
    local main_refresh_busy = (action ~= nil and action.key ~= "refresh_main") or tick_main_refresh(now)
    -- The visible card requests refresh through a cached flag, never native
    -- reads in rendering. One selected property at most every five seconds.
    if not main_refresh_busy and MAIN_BUSINESSES[State.selected_business]
        and now <= (State.visible_until_ms or -1) and now >= (State.next_visible_refresh_ms or 0) then
        State.next_visible_refresh_ms = now + 5000
        refresh_business(State.selected_business)
    end
    if not State.auto_refresh then
        if State.automation_running ~= true and State.bulk_resupply == nil then State.machine_state = "IDLE" end
        return
    end
    if main_refresh_busy then return end
    if now < (tonumber(State.next_refresh_ms) or 0) then return end
    if State.machine_state == "ERROR" then return end
    State.machine_state = "CHECK_STATUS"
    -- Automatic refresh reads only the selected property to avoid bursts of
    -- 200+ stat probes. Manual Refresh All reads the full inventory.
    local ok, result = pcall(refresh_business, State.selected_business)
    if not ok then
        State.machine_state, State.last_error = "ERROR", tostring(result)
        State.auto_refresh, State.automation_running = false, false
        return
    end
    State.machine_state = "WAIT"
    State.next_refresh_ms = now + 30000
end

local function invalidate(reason)
    farm_finish_requests={};farm_finish_detail=nil
    sale_finish_pending=nil
    stop_all_mc_farms("Business context invalidated.")
    for _,engine in pairs(mc_apps) do engine.Cancel("Business context invalidated.") end
    if bunker_farm and bunker_farm.active then bunker_farm_fail("Business context invalidated.") end
    bunker_farm=nil
    if bunker_app_engine then
        local cancelled=pcall(bunker_app_engine.Cancel,"Business context invalidated.")
        local read,status=pcall(bunker_app_engine.Snapshot)
        -- The terminal status still owns its token until cleanup reads back.
        -- tick_bunker_app_sale continues retrying it after invalidation.
        if cancelled and read and type(status)=="table" and status.cleanup_pending==false then bunker_app_engine=nil end
    end
    if bunker_sale_engine then pcall(bunker_sale_engine.Cancel,"Business context invalidated.") end
    bunker_sale_engine=nil
    clear_action_intent()
    State.generation = (State.generation or 0) + 1
    State.main_scan, State.main_refresh_requested, State.main_requested_generation = nil, false, nil
    State.main_refresh_completed, State.main_refresh_error, State.main_wait = 0, nil, nil
    State.visible_until_ms, State.next_visible_refresh_ms = -1, 0
    State.statuses = {}
    State.action_queue = {}
    State.bulk_resupply = nil
    State.hangar_pocket = {
        delay_ms = HANGAR_POCKET_DEFAULTS.delay_ms, step = HANGAR_POCKET_DEFAULTS.step,
        limit = HANGAR_POCKET_DEFAULTS.limit, type_index = HANGAR_POCKET_DEFAULTS.type_index,
        fast_mode = HANGAR_POCKET_DEFAULTS.fast_mode,
        running = false, mode = "idle", next_ms = 0, pending = nil, cycle_remaining = 0,
        writes = 0, last_result = "Idle", last_ok = true,
    }
    State.auto_refresh, State.automation_running = false, false
    State.machine_state, State.next_refresh_ms = "IDLE", 0
    State.invalidated = tostring(reason or "Session changed")
end

local function queue_action(key, value)
    key = tostring(key or "")
    if key == "" then return false, "Business action key is required" end
    for _, pending in ipairs(State.action_queue) do
        if pending.key == key then return false, "this Business action is already queued" end
    end
    if #State.action_queue >= MAX_ACTION_QUEUE then return false, "Business action queue is full" end
    local captured
    if key == "run" then
        local status = State.statuses[State.selected_business]
        local slot = status and status.character_slot
        if slot ~= 0 and slot ~= 1 then return false, "Waiting for the current business settings." end
        local request = type(value)=="table" and value or {key=value}
        if type(request.key)~="string" then return false,"Choose a business action." end
        -- Freeze scalar action input and identity; caller/UI edits cannot retarget it.
        value = {key=request.key, expected_slot=slot,
            target_percent=request.target_percent or State.target_percent,
            target_index=request.target_index or State.target_index_by_business[State.selected_business] or 1}
        captured = {business=State.selected_business,slot=slot,generation=State.generation,
            selection=State.selection_generation or 0}
    end
    State.action_queue[#State.action_queue + 1] = { key = key, value = value, context=captured }
    return true
end

local function set_target_percent(value)
    value = tonumber(value)
    if value == nil then return false end
    State.target_percent = math.max(0, math.min(100, math.floor(value + 0.5)))
    return true
end

local function set_target_index(value)
    value = tonumber(value)
    if value == nil then return false end
    State.target_index_by_business[State.selected_business] = math.max(1, math.min(7, math.floor(value + 0.5)))
    return true
end

local function passive_income_summary()
    local result = {
        entries = {}, known_safe_cash = 0, safe_cash_total = 0,
        known_timers = 0, known_lifetime = 0, properties_with_data = 0,
        server_authoritative = true, read_only = true,
        note = "Safe cash and passive-income stats are script-owned, server-authoritative and read-only.",
    }
    for _, item in ipairs(BUSINESS_CATALOG) do
        if item.passive_income then
            local status = State.statuses and State.statuses[item.key]
            local passive = status and status.passive_income
            if passive then
                local entry = {
                    key = item.key, name = item.name, owned = status.owned,
                    safe_cash = passive.safe_cash, payout_timer_raw = passive.payout_timer_raw,
                    lifetime_earnings = passive.lifetime_earnings,
                    server_authoritative = true, read_only = true,
                }
                if entry.safe_cash ~= nil then
                    result.known_safe_cash = result.known_safe_cash + 1
                    result.safe_cash_total = result.safe_cash_total + math.max(0, tonumber(entry.safe_cash) or 0)
                end
                if entry.payout_timer_raw ~= nil then result.known_timers = result.known_timers + 1 end
                if entry.lifetime_earnings ~= nil then result.known_lifetime = result.known_lifetime + 1 end
                if entry.safe_cash ~= nil or entry.payout_timer_raw ~= nil or entry.lifetime_earnings ~= nil then
                    result.properties_with_data = result.properties_with_data + 1
                    result.entries[#result.entries + 1] = entry
                end
            end
        end
    end
    return result
end

local function snapshot()
    local selected = current_business()
    local read_adapter_count, validated_adapter_count = 0, 0
    local ownership_summary = { detected = 0, not_detected = 0, unknown = 0, names = {} }
    local main_catalog={}
    for _,item in ipairs(MAIN_CATALOG) do main_catalog[#main_catalog+1]=item end
    for _, item in ipairs(BUSINESS_CATALOG) do
        if item.signal or item.ownership_fields or item.read_fields or item.factory_ids then read_adapter_count = read_adapter_count + 1 end
        local adapter = ADAPTERS[item.key]
        if adapter and adapter.mutation_validated == true then
            validated_adapter_count = validated_adapter_count + 1
        end
        local status = State.statuses and State.statuses[item.key]
        if status and status.owned == true then
            ownership_summary.detected = ownership_summary.detected + 1
            ownership_summary.names[#ownership_summary.names + 1] = item.name
        elseif status and status.owned == false then
            ownership_summary.not_detected = ownership_summary.not_detected + 1
        else
            ownership_summary.unknown = ownership_summary.unknown + 1
        end
    end
    return {
        catalog = BUSINESS_CATALOG, main_catalog=main_catalog, statuses = State.statuses,
        main_refresh = { active=State.main_scan~=nil or State.main_refresh_requested==true,
            state=State.main_wait and "WAITING" or State.main_scan and "SCANNING"
                or State.main_refresh_requested and "QUEUED" or State.main_refresh_error and "FAILED"
                or State.main_refresh_completed==#MAIN_CATALOG and "COMPLETE" or "IDLE",
            completed=State.main_refresh_completed or 0,total=#MAIN_CATALOG,error=State.main_refresh_error },
        selected_business = selected.key, selected = State.statuses[selected.key] or build_status(selected),
        needs_attention = needs_attention(), auto_refresh = State.auto_refresh == true,
