-- Retained native manifest entries; these references do not register a runtime path.
local REMOVED_AIRCRAFT_CANNON_NATIVE_IDS = {
    H.DISABLE_CONTROL_ACTION,
    H.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS,
    H.SHOOT_SINGLE_BULLET_BETWEEN_COORDS,
}

local ID = {}
-- Stable namespace for existing Cherax feature settings.
local FEATURE_ID_NAMESPACE = "JinxRebound_"
local LEGACY_FEATURE_IDS = {
    -- Preserve the saved Disable Phone Calls feature identity.
    disable_phone_calls = 3173828533,
}
local function feature_id(key)
    if not ID[key] then
        ID[key] = LEGACY_FEATURE_IDS[key]
            or Utils.Joaat(FEATURE_ID_NAMESPACE .. tostring(key))
    end
    -- Keep one authoritative registry of every CScript-owned Cherax feature.
    -- The welcome gate uses only these hashes, so it never hides unrelated
    -- Cherax controls while CScript's startup presentation is active.
    CScript.FeatureKeys = CScript.FeatureKeys or {}
    CScript.FeatureKeys[tostring(key)] = ID[key]
    return ID[key]
end
local State = {
    unloading = false,
    panicking = false,
    last_tick = 0,
    last_slow_tick = 0,
    last_vehicle = 0,
    last_ped = 0,
    was_in_vehicle = false,
    doors_locked = false,
    registered_count = 0,
    errors = {},
    event_handlers = {},
    last_overlay_sample = 0,
    welcome_started_seconds = 0,
    welcome_username = "Player",
    welcome_title = "Welcome back, Player",
    welcome_version = "CScript 17.76",
    welcome_status = "Ready",
    welcome_preview = false,
    overlay = { lines = {}, pinned = nil, vip = nil },
}

local function log_info(message)
    if Logger and type(Logger.LogInfo) == "function" then
        pcall(Logger.LogInfo, "[" .. SCRIPT_NAME .. "] " .. tostring(message))
    end
end

local function log_warn(message)
    if Logger and type(Logger.LogWarn) == "function" then
        pcall(Logger.LogWarn, "[" .. SCRIPT_NAME .. "] " .. tostring(message))
    else
        log_info("WARN: " .. tostring(message))
    end
end

local function log_error_once(key, message)
    message = tostring(message)
    if State.errors[key] == message then return end
    State.errors[key] = message
    if Logger and type(Logger.LogError) == "function" then
        pcall(Logger.LogError, "[" .. SCRIPT_NAME .. "] " .. message)
    else
        log_warn(message)
    end
end

local function toast(message, duration, notification_type, priority, domain)
    local text = tostring(message)
    local kind = tostring(notification_type or ""):lower()
    if kind == "" then
        local lower = text:lower()
        if lower:find("failed", 1, true) or lower:find("error", 1, true) then kind = "error"
        elseif lower:find("unavailable", 1, true) or lower:find("could not", 1, true)
            or lower:find("skipped", 1, true) then kind = "warning"
        elseif lower:find("saved", 1, true) or lower:find("applied", 1, true)
            or lower:find("restored", 1, true) or lower:find("ready", 1, true) then kind = "success"
        else kind = "info" end
    end
    local notifications =
    CScript
    and CScript.Notifications
    if notifications and type(notifications.Push) == "function" then
        local ok = pcall(notifications.Push, text, duration or 4000, kind, priority, nil, nil, domain)
        if ok then return end
    end
    if GUI and type(GUI.AddToast) == "function" and eToastPos then
        pcall(GUI.AddToast, SCRIPT_NAME, text, duration or 4000, eToastPos.TOP_RIGHT)
    end
end

local RuntimeApi

local function trace_api(label)
    if RuntimeApi and type(RuntimeApi.RecordApiCall) == "function" then RuntimeApi.RecordApiCall(label) end
end

local function invoke_void(hash, ...)
    trace_api("Native.InvokeVoid")
    if not (Natives and type(Natives.InvokeVoid) == "function") then return false end
    local ok, err = pcall(Natives.InvokeVoid, hash, ...)
    if not ok then log_error_once("void_" .. tostring(hash), err) end
    return ok
end

-- Messiah's detail variants retain native results and errors for diagnostics.
-- The other helpers keep their established return contracts.
local function invoke_void_detail(hash, ...)
    trace_api("Native.InvokeVoid")
    if not (Natives and type(Natives.InvokeVoid) == "function") then
        return false, nil, "Natives.InvokeVoid unavailable"
    end
    local ok, value = pcall(Natives.InvokeVoid, hash, ...)
    if not ok then
        log_error_once("void_" .. tostring(hash), value)
        return false, nil, tostring(value)
    end
    return true, value, nil
end

local function invoke_int(hash, ...)
    trace_api("Native.InvokeInt")
    if not (Natives and type(Natives.InvokeInt) == "function") then return 0 end
    local ok, value = pcall(Natives.InvokeInt, hash, ...)
    if not ok then
        log_error_once("int_" .. tostring(hash), value)
        return 0
    end
    return type(value) == "number" and value or 0
end

local function invoke_int_detail(hash, ...)
    trace_api("Native.InvokeInt")
    if not (Natives and type(Natives.InvokeInt) == "function") then
        return 0, nil, "Natives.InvokeInt unavailable"
    end
    local ok, value = pcall(Natives.InvokeInt, hash, ...)
    if not ok then
        log_error_once("int_" .. tostring(hash), value)
        return 0, nil, tostring(value)
    end
    return type(value) == "number" and value or 0, value, nil
end

local function invoke_float(hash, ...)
    trace_api("Native.InvokeFloat")
    if not (Natives and type(Natives.InvokeFloat) == "function") then return 0.0 end
    local ok, value = pcall(Natives.InvokeFloat, hash, ...)
    if not ok then
        log_error_once("float_" .. tostring(hash), value)
        return 0.0
    end
    return type(value) == "number" and value or 0.0
end

local function invoke_float_detail(hash, ...)
    trace_api("Native.InvokeFloat")
    if not (Natives and type(Natives.InvokeFloat) == "function") then
        return 0.0, nil, "Natives.InvokeFloat unavailable"
    end
    local ok, value = pcall(Natives.InvokeFloat, hash, ...)
    if not ok then
        log_error_once("float_" .. tostring(hash), value)
        return 0.0, nil, tostring(value)
    end
    return type(value) == "number" and value or 0.0, value, nil
end

local function invoke_string(hash, ...)
    trace_api("Native.InvokeString")
    if not (Natives and type(Natives.InvokeString) == "function") then return "" end
    local ok, value = pcall(Natives.InvokeString, hash, ...)
    return ok and type(value) == "string" and value or ""
end

local function invoke_bool(hash, ...)
    trace_api("Native.InvokeBool")
    if not (Natives and type(Natives.InvokeBool) == "function") then return false end
    local ok, value = pcall(Natives.InvokeBool, hash, ...)
    if not ok then
        log_error_once("bool_" .. tostring(hash), value)
        return false
    end
    return value == true or (type(value) == "number" and value == value
        and value ~= math.huge and value ~= -math.huge and value % 1 == 0 and value ~= 0)
end

local function invoke_bool_detail(hash, ...)
    trace_api("Native.InvokeBool")
    if not (Natives and type(Natives.InvokeBool) == "function") then
        return false, nil, "Natives.InvokeBool unavailable"
    end
    local ok, value = pcall(Natives.InvokeBool, hash, ...)
    if not ok then
        log_error_once("bool_" .. tostring(hash), value)
        return false, nil, tostring(value)
    end
    local valid = type(value)=="boolean" or (type(value)=="number" and value==value
        and value~=math.huge and value~=-math.huge and value%1==0)
    if not valid then return false,value,"Invalid native BOOL return" end
    return value==true or (type(value)=="number" and value~=0), value, nil
end

local function invoke_vec3(hash, ...)
    trace_api("Native.InvokeV3")
    local fn = Natives and (Natives.InvokeVector3 or Natives.InvokeV3)
    if type(fn) ~= "function" then return nil end
    local ok, value, y, z = pcall(fn, hash, ...)
    if not ok then
        log_error_once("vec3_" .. tostring(hash), value)
        return nil
    end
    if type(value) == "number" and type(y) == "number" and type(z) == "number" then
        return { x = value, y = y, z = z }
    end
    return value
end

-- Shared budget for natural weapon/vehicle transitions. This native updates
-- the whole ped, so never stack calls from two features in the same frame.
-- No retained ped pointer/handle and no claim about measured playback speed.
local animation_update_frame
local function advance_local_animation(ped, still_owner)
    if type(still_owner)~="function" or not still_owner() then return false end
    local _,frame,err=invoke_int_detail(0xFC8202EFC642E6F2) -- GET_FRAME_COUNT
    if err or type(frame)~="number" or frame~=frame or frame<0
        or frame>=math.huge or frame%1~=0 or not still_owner() then return false end
    if animation_update_frame==frame then return false end
    -- Reserve BEFORE dispatch, including failures and reentrant callbacks.
    animation_update_frame=frame
    return invoke_void(0x2208438012482A1A,ped,false,false)
end

local function now_ms()
    local value = invoke_int(H.GET_GAME_TIMER)
    if value > 0 then return value end
    return math.floor(os.clock() * 1000)
end

local function local_player_id()
    if GTA and type(GTA.GetLocalPlayerId) == "function" then
        local ok, value = pcall(GTA.GetLocalPlayerId)
        if ok and type(value) == "number" then return value end
    end
    return 0
end

local function local_ped()
    return invoke_int(H.GET_PLAYER_PED_SCRIPT_INDEX, local_player_id())
end

local function entity_exists(handle)
    return type(handle) == "number" and handle ~= 0 and invoke_bool(H.DOES_ENTITY_EXIST, handle)
end

local function local_vehicle()
    local ped = local_ped()
    if not entity_exists(ped) or not invoke_bool(H.IS_PED_IN_ANY_VEHICLE, ped, false) then return 0 end
    return invoke_int(H.GET_VEHICLE_PED_IS_IN, ped, false)
end

local function vector_components(value)
    if value == nil then return nil end
    local value_type = type(value)
    if value_type ~= "table" and value_type ~= "userdata" then return nil end
    local ok, x, y, z = pcall(function()
        return tonumber(value.x or value.X or value[1]),
            tonumber(value.y or value.Y or value[2]),
            tonumber(value.z or value.Z or value[3])
    end)
    if not ok then return nil end
    if not (x and y and z) then return nil end
    return x, y, z
end

local function player_available(player_id)
    player_id = tonumber(player_id)
    if not player_id or player_id < 0 or player_id > 31 then return false end
    if not (Players and type(Players.GetById) == "function") then return false end
    local ok, player = pcall(Players.GetById, player_id)
    return ok and (type(player) == "table" or type(player) == "userdata")
end

local function player_name(player_id)
    if Players and type(Players.GetName) == "function" then
        local ok, name = pcall(Players.GetName, player_id)
        if ok and type(name) == "string" and name ~= "" then return name end
    end
    local name = invoke_string(0x6D0DE6A7B5DA71F8, player_id)
    if name ~= "" and name ~= "**Invalid**" then return name end
    return "Player " .. tostring(player_id)
end

local function player_ped(player_id)
    if not player_available(player_id) then return 0 end
    local ped = invoke_int(H.GET_PLAYER_PED_SCRIPT_INDEX, player_id)
    return entity_exists(ped) and ped or 0
end

local function player_flags(player_id)
    local passive, ghost, tags = false, false, ""
    local known = { passive = false, ghost = false }
    player_id = tonumber(player_id)
    if not player_id or not player_available(player_id) then return passive, ghost, tags, known end

    -- f_8 includes forced protection; f_9 distinguishes forced passive states.
    -- Keep the full protection flag for action guards, and classify the UI separately.
    if ScriptGlobal and type(ScriptGlobal.AreValid) == "function"
        and type(ScriptGlobal.GetInt) == "function" then
        local ready_ok, ready = pcall(ScriptGlobal.AreValid)
        if ready_ok and ready == true then
            local header_ok, header = pcall(ScriptGlobal.GetInt, 1893070)
            if header_ok and header == 32 then
                local passive_ok, value = pcall(ScriptGlobal.GetInt,
                    1893070 + 1 + math.floor(player_id) * 615 + 8)
                if passive_ok and (value == 0 or value == 1) then
                    passive, known.passive = value == 1, true
                    if value == 0 then
                        known.passive_mode = false
                    else
                        local forced_ok, forced = pcall(ScriptGlobal.GetInt,
                            1893070 + 1 + math.floor(player_id) * 615 + 9)
                        if forced_ok and (forced == 0 or forced == 1) then
                            known.passive_mode = forced == 0
                        end
                    end
                end
            end
        end
    end

    -- IS_ENTITY_A_GHOST is the supported local-view readback. Pair-specific
    -- freemode ownership is checked separately by the Remove Ghost runtime.
    local ped = player_ped(player_id)
    if ped ~= 0 then
        local value, raw, err = invoke_bool_detail(H.IS_ENTITY_A_GHOST, ped)
        if err == nil and (type(raw) == "boolean" or raw == 0 or raw == 1) then
            ghost, known.ghost = value, true
        end
    end
    if Players
    and type(Players.GetTags) == "function" then
        local tags_ok, value = pcall(Players.GetTags, player_id)
        if tags_ok and type(value) == "string" then tags = value end
    end
    return passive, ghost, tags, known
end

local function player_snapshot(player_id)
    local ped = player_ped(player_id)
    if ped == 0 then return nil end
    local passive, ghost, tags = player_flags(player_id)
    local vehicle = 0
    if invoke_bool(H.IS_PED_IN_ANY_VEHICLE, ped, false) then
        vehicle = invoke_int(H.GET_VEHICLE_PED_IS_IN, ped, false)
    end
    local local_coords = invoke_vec3(H.GET_ENTITY_COORDS, local_ped(), false)
    local target_coords = invoke_vec3(H.GET_ENTITY_COORDS, ped, false)
    local lx, ly, lz = vector_components(local_coords)
    local tx, ty, tz = vector_components(target_coords)
    local distance = nil
    if lx and tx then
        local dx, dy, dz = tx - lx, ty - ly, tz - lz
        distance = math.sqrt(dx * dx + dy * dy + dz * dz)
    end
    return {
        id = player_id,
        name = player_name(player_id),
        ped = ped,
        vehicle = vehicle,
        passive = passive,
        ghost = ghost,
        tags = tags,
        speed = invoke_float(H.GET_ENTITY_SPEED, vehicle ~= 0 and vehicle or ped),
        model = invoke_int(H.GET_ENTITY_MODEL, vehicle ~= 0 and vehicle or ped),
        interior = invoke_int(H.GET_INTERIOR_FROM_ENTITY, ped),
        distance = distance,
        x = tx, y = ty, z = tz,
    }
end

-- Cherax v5.48.1 fail-fasts GTA while applying the 0..500 limit metadata to
-- the Rapid Fire Delay SliderInt. Keep this one value in Lua so config,
-- vehicle logic, and the custom CScript UI retain the same integer contract
-- without creating or touching fatal Feature userdata.
-- Spawn radius is also owned in Lua and rendered by the custom UI. Its config
-- adapter delegates directly to Protections instead of creating a second state.
local VIRTUAL_INT_SPECS = {
    vehicle_rapid_fire_delay = { default = 45, minimum = 0, maximum = 500 },
    protect_spawn_radius = { default = 25, minimum = 5, maximum = 5000,
        service = "Protections", getter = "GetSpawnRadius", setter = "SetSpawnRadius" },
}
local VirtualIntState = {
    vehicle_rapid_fire_delay = VIRTUAL_INT_SPECS.vehicle_rapid_fire_delay.default,
}
local VirtualIntFeatures = {}

local function virtual_int_feature(key)
    local spec = VIRTUAL_INT_SPECS[key]
    if not spec then return nil end
    if VirtualIntFeatures[key] then return VirtualIntFeatures[key] end

    local feature = {}
    function feature:GetIntValue()
        if spec.service then
            local owner = CScript and CScript[spec.service]
            local getter = owner and owner[spec.getter]
            if type(getter) == "function" then return getter() end
            return nil
        end
        return VirtualIntState[key]
    end
    function feature:SetIntValue(value)
        if spec.service then
            local owner = CScript and CScript[spec.service]
            local setter = owner and owner[spec.setter]
            if type(setter) ~= "function" then return false end
            if setter(value) ~= true then return false end
            return self
        end
        local numeric = math.floor(tonumber(value) or spec.default)
        VirtualIntState[key] = math.max(spec.minimum, math.min(spec.maximum, numeric))
        return self
    end
    VirtualIntFeatures[key] = feature
    return feature
end

local FeatureReferenceCache = {}
local function feature_ref(key)
    local virtual =
        virtual_int_feature(key)

    if virtual then
        return virtual
    end

    local epoch = RuntimeApi and RuntimeApi.State and RuntimeApi.State.health
        and math.floor((RuntimeApi.State.health.last_tick_ms or 0) / 1000) or 0
    local cached = FeatureReferenceCache[key]
    if cached and cached.epoch == epoch then return cached.feature end
    if FeatureMgr
        and type(FeatureMgr.GetFeature) == "function" then

        local ok, feature =
            pcall(
                FeatureMgr.GetFeature,
                feature_id(key)
            )

        if ok and feature ~= nil then
            FeatureReferenceCache[key] = { feature = feature, epoch = epoch }
            return feature
        end
    end

    return nil
end

local function is_on(key)
    local feature =
        feature_ref(key)

    if not feature
        or type(feature.IsToggled) ~= "function" then
        return false
    end

    local ok, enabled =
        pcall(
            feature.IsToggled,
            feature
        )

    return ok
        and enabled == true
end

local function list_index(key)
    local feature = feature_ref(key)
    if not feature then return 0 end
    local ok, value = pcall(function() return feature:GetListIndex() end)
    return ok and type(value) == "number" and value or 0
end

local function set_toggle(key, enabled)
    local feature =
        feature_ref(key)

    if not feature then
        return false,
            "feature unavailable: "
            .. tostring(key)
    end

    if type(feature.IsToggled) ~= "function"
        or type(feature.Toggle) ~= "function" then

        return false,
            "feature is not toggle-compatible: "
            .. tostring(key)
    end

    local wanted =
        enabled == true

    local read_ok, current =
        pcall(
            feature.IsToggled,
            feature
        )

    if not read_ok then
        log_error_once(
            "toggle_read_" .. tostring(key),
            "Could not read toggle "
            .. tostring(key)
            .. ": "
            .. tostring(current)
        )

        return false,
            tostring(current)
    end

    if current == wanted then
        return true, false
    end

    local toggle_ok, toggle_error =
        pcall(
            feature.Toggle,
            feature,
            wanted
        )

    if not toggle_ok or toggle_error == false then
        log_error_once(
            "toggle_write_" .. tostring(key),
            "Could not toggle "
            .. tostring(key)
            .. ": "
            .. tostring(toggle_error)
        )

        return false,
            tostring(toggle_error)
    end

    local verify_ok, observed =
        pcall(
            feature.IsToggled,
            feature
        )

    if not verify_ok
        or observed ~= wanted then

        local detail =
            "Toggle "
            .. tostring(key)
            .. " did not reach requested state "
            .. tostring(wanted)

        log_error_once(
            "toggle_verify_" .. tostring(key),
            detail
        )

        return false, detail
    end

    return true, true
end

local function set_slider_int(key, value)
    local feature = feature_ref(key)
    if not feature or type(feature.SetIntValue) ~= "function" then return false end
    return pcall(function() feature:SetIntValue(math.floor(tonumber(value) or 0)) end)
end

local function slider_int(key, fallback)
    local feature = feature_ref(key)
    if not feature then return fallback end
    local ok, value = pcall(function() return feature:GetIntValue() end)
    return ok and type(value) == "number" and value or fallback
end

local function slider_float(key, fallback)
    local feature = feature_ref(key)
    if not feature then return fallback end
    local ok, value = pcall(function() return feature:GetFloatValue() end)
    return ok and type(value) == "number" and value or fallback
end

local function set_slider_float(key, value)
    local feature = feature_ref(key)
    if not feature then return false end
    local ok = pcall(function() feature:SetFloatValue(value) end)
    return ok
end

local function repair_vehicle(vehicle)
    if not entity_exists(vehicle) then return false end
    invoke_void(H.SET_VEHICLE_ENGINE_HEALTH, vehicle, 1000.0)
    invoke_void(H.SET_VEHICLE_FIXED, vehicle)
    invoke_void(H.SET_VEHICLE_DEFORMATION_FIXED, vehicle)
    invoke_void(H.SET_VEHICLE_DIRT_LEVEL, vehicle, 0.0)
    invoke_void(H.SET_VEHICLE_PETROL_TANK_HEALTH, vehicle, 1000.0)
    return true
end

