log_info("Startup stage: session compatibility bind begin.")
local SessionRuntime = CScript and CScript.Modules and CScript.Modules.Session
if type(SessionRuntime) ~= "table" or type(SessionRuntime.BindCompatibility) ~= "function" then
    error("CScript session module is unavailable")
end
local SessionApi = SessionRuntime.BindCompatibility({
    invoke_int_detail = invoke_int_detail,
    log_info = log_info,
    log_warn = log_warn,
    log_error_once = log_error_once,
    toast = toast,
    invoke_void = invoke_void,
    invoke_void_detail = invoke_void_detail,
    invoke_int = invoke_int,
    invoke_bool = invoke_bool,
    invoke_bool_detail = invoke_bool_detail,
    -- Wrapper functions exist even when the host native bridge is absent.
    transition_dispatch_available = Natives and type(Natives.InvokeBool) == "function"
        and type(Natives.InvokeVoid) == "function",
    -- Evaluate on gameplay probing, so late bridge load/unload is not hidden by
    -- the startup snapshot. The detailed wrappers still preserve actual errors.
    transition_dispatch_status = function()
        if not (Natives and type(Natives.InvokeBool) == "function") then
            return false, "Natives.InvokeBool unavailable"
        end
        if type(Natives.InvokeVoid) ~= "function" then return false, "Natives.InvokeVoid unavailable" end
        return true
    end,
    invoke_string = invoke_string,
    now_ms = now_ms,
    local_player_id = local_player_id,
    player_available = player_available,
    player_name = player_name,
    player_snapshot = player_snapshot,
    player_flags = player_flags,
    feature_id = feature_id,
    H = H,
    FeatureMgr = FeatureMgr,
    eFeatureType = eFeatureType,
    Script = setmetatable({}, {__index=function(_, key)
        local current=Script
        return current and current[key] or nil
    end}),
    Natives = setmetatable({}, {__index=function(_, key)
        local current=Natives
        return current and current[key] or nil
    end}),
    Utils = Utils,
    GTA = GTA,
    GUI = GUI,
    Players = Players,
    ePlayerListSort = ePlayerListSort,
    ScriptGlobal = setmetatable({}, {__index=function(_, key)
        local current=ScriptGlobal
        return current and current[key] or nil
    end}),
    ScriptLocal = setmetatable({}, {__index=function(_, key)
        local current=ScriptLocal
        return current and current[key] or nil
    end}),
