local function stat_hash(name)
    if not module_context or not module_context.Cherax then return nil, "hash service unavailable" end
    return module_context.Cherax.Hash(tostring(name))
end

local function read_stat(name)
    local memory = module_context and module_context.Raw and module_context.Raw.Memory
    if not memory or type(memory.AllocInt) ~= "function" or type(memory.WriteInt) ~= "function"
        or type(memory.ReadInt) ~= "function" or type(memory.Free) ~= "function" then
        return nil, "required stat pointer APIs are unavailable"
    end
    local hash, hash_err = stat_hash(name)
    if hash == nil then return nil, hash_err end
    local allocated, pointer = pcall(memory.AllocInt)
    pointer = allocated and tonumber(pointer) or 0
    if pointer == 0 then return nil, "Memory.AllocInt failed" end
    local value
    local ok, failure = xpcall(function()
        if not pcall(memory.WriteInt, pointer, 0) then error("Memory.WriteInt failed") end
        local invoked, result = native_try("bool", STAT_GET_INT, hash, pointer, -1)
        if not invoked then error("STAT_GET_INT invocation failed: " .. tostring(result)) end
        if result ~= true then error("STAT_GET_INT rejected " .. tostring(name)) end
        local read_ok, read_value = pcall(memory.ReadInt, pointer)
        if not read_ok or type(read_value) ~= "number" then error("Memory.ReadInt failed") end
        value = math.floor(read_value)
    end, function(err) return tostring(err) end)
    pcall(memory.Free, pointer)
    return ok and value or nil, ok and nil or failure
end

function Module.ReadBoolStat(name)
    local memory=module_context and module_context.Raw and module_context.Raw.Memory
    if not memory or type(memory.AllocInt)~="function" or type(memory.WriteInt)~="function"
        or type(memory.ReadInt)~="function" or type(memory.Free)~="function" then return nil,"Boolean stat APIs unavailable." end
    local hash,why=stat_hash(name);if hash==nil then return nil,why end
    local allocated,pointer=pcall(memory.AllocInt)
    if not allocated or not tonumber(pointer) or tonumber(pointer)==0 then return nil,"Stat allocation failed." end
    local ok,value=pcall(function()
        memory.WriteInt(pointer,0)
        local invoked,accepted=native_try("bool",0x11B5E6D2AE73F48E,hash,pointer,-1)
        if not invoked or accepted~=true then error("Boolean stat read rejected: "..tostring(name)) end
        local observed=memory.ReadInt(pointer)
        if observed~=0 and observed~=1 then error("Invalid boolean stat value.") end
        return observed==1
    end)
    pcall(memory.Free,pointer)
    if not ok then return nil,tostring(value) end
    return value
end

local function write_stat(name, value)
    value = tonumber(value)
    if not value or value ~= math.floor(value) or value < -2147483648 or value > 2147483647 then
        return false, "stat value is outside signed 32-bit integer range"
    end
    local hash, hash_err = stat_hash(name)
    if hash == nil then return false, hash_err end
    local invoked, result = native_try("bool", STAT_SET_INT, hash, value, true)
    if not invoked then return false, "STAT_SET_INT invocation failed: " .. tostring(result) end
    if result ~= true then return false, "STAT_SET_INT rejected " .. tostring(name) end
    return true
end

function Module.Profile.read_hash_float(hash)
    local memory = module_context and module_context.Raw and module_context.Raw.Memory
    if not memory or type(memory.Alloc) ~= "function" or type(memory.WriteFloat) ~= "function"
        or type(memory.ReadFloat) ~= "function" or type(memory.Free) ~= "function" then
        return nil, "required float-stat pointer APIs are unavailable"
    end
    hash = tonumber(hash)
    if hash == nil then return nil, "stat hash is unavailable" end
    local allocated, pointer = pcall(memory.Alloc, 4)
    pointer = allocated and tonumber(pointer) or 0
    if pointer == 0 then return nil, "Memory.Alloc(4) failed" end
    local value
    local ok, failure = xpcall(function()
        if not pcall(memory.WriteFloat, pointer, 0.0) then error("Memory.WriteFloat failed") end
        local invoked, result = native_try("bool", Module.ProfileNative.GET_FLOAT, hash, pointer, -1)
        if not invoked or result ~= true then error("Module.ProfileNative.GET_FLOAT rejected stat") end
        local read_ok, read_value = pcall(memory.ReadFloat, pointer)
        if not read_ok or type(read_value) ~= "number" or read_value ~= read_value then
            error("Memory.ReadFloat failed")
        end
        value = read_value
    end, function(err) return tostring(err) end)
    pcall(memory.Free, pointer)
    return ok and value or nil, ok and nil or failure
end

function Module.Profile.read_float(name)
    local hash, hash_err = stat_hash(name)
    if hash == nil then return nil, hash_err end
    return Module.Profile.read_hash_float(hash)
end

function Module.Profile.write_float_verified(name, value, expected_before)
    value = tonumber(value)
    if not value or value ~= value or value == math.huge or value == -math.huge then
        return false, "float stat value is invalid"
    end
    local hash, hash_err = stat_hash(name)
    if hash == nil then return false, hash_err end
    local before, before_err = Module.Profile.read_hash_float(hash)
    if before == nil then return false, before_err end
    if expected_before ~= nil and math.abs(before - expected_before) > 0.0005 then
        return false, "float stat changed before write"
    end
    if math.abs(before - value) <= 0.0005 then
        return true, { changed=false, before=before, after=before, hash=hash }
    end
    local invoked, result = native_try("bool", Module.ProfileNative.SET_FLOAT, hash, value, true)
    if not invoked or result ~= true then return false, "Module.ProfileNative.SET_FLOAT rejected " .. tostring(name) end
    local after, after_err = Module.Profile.read_hash_float(hash)
    if after == nil or math.abs(after - value) > 0.005 then
        native_try("bool", Module.ProfileNative.SET_FLOAT, hash, before, true)
        return false, after_err or "float stat read-back verification failed"
    end
    return true, { changed=true, before=before, after=after, hash=hash }
end

local function read_stat_hash_int(hash)
    local memory = module_context and module_context.Raw and module_context.Raw.Memory
    if not memory or type(memory.AllocInt) ~= "function" or type(memory.WriteInt) ~= "function"
        or type(memory.ReadInt) ~= "function" or type(memory.Free) ~= "function" then
        return nil, "required stat pointer APIs are unavailable"
    end
    hash = tonumber(hash)
    if hash == nil then return nil, "stat hash is unavailable" end
    local allocated, pointer = pcall(memory.AllocInt)
    pointer = allocated and tonumber(pointer) or 0
    if pointer == 0 then return nil, "Memory.AllocInt failed" end
    local value
    local ok, failure = xpcall(function()
        if not pcall(memory.WriteInt, pointer, 0) then error("Memory.WriteInt failed") end
        local invoked, result = native_try("bool", STAT_GET_INT, hash, pointer, -1)
        if not invoked or result ~= true then error("STAT_GET_INT rejected resolved character stat") end
        local read_ok, read_value = pcall(memory.ReadInt, pointer)
        if not read_ok or type(read_value) ~= "number" then error("Memory.ReadInt failed") end
        value = math.floor(read_value)
    end, function(err) return tostring(err) end)
    pcall(memory.Free, pointer)
    return ok and value or nil, ok and nil or failure
end

local function read_character_stat_index(slot, stat_index, data_type)
    slot, stat_index, data_type = tonumber(slot), tonumber(stat_index), tonumber(data_type) or 0
    if (slot ~= 0 and slot ~= 1) or not stat_index or stat_index % 1 ~= 0 then
        return nil, "character/stat index is invalid"
    end
    local hash_ok, hash = native_try("int", GET_STAT_HASH_FOR_CHARACTER_STAT,
        math.floor(data_type), math.floor(stat_index), math.floor(slot))
    if not hash_ok or type(hash) ~= "number" or hash == 0 then
        return nil, "_GET_STAT_HASH_FOR_CHARACTER_STAT failed for index " .. tostring(stat_index)
    end
    return read_stat_hash_int(hash)
end

function Module.Profile.read_character_float(slot, stat_index, data_type)
    slot, stat_index, data_type = tonumber(slot), tonumber(stat_index), tonumber(data_type) or 1
    if (slot ~= 0 and slot ~= 1) or not stat_index or stat_index % 1 ~= 0 then
        return nil, "character/float stat index is invalid"
    end
    local hash_ok, hash = native_try("int", GET_STAT_HASH_FOR_CHARACTER_STAT,
        math.floor(data_type), math.floor(stat_index), math.floor(slot))
    if not hash_ok or type(hash) ~= "number" or hash == 0 then
        return nil, "_GET_STAT_HASH_FOR_CHARACTER_STAT failed for float index " .. tostring(stat_index)
    end
    return Module.Profile.read_hash_float(hash)
end

function Module.Profile.write_character_float_verified(slot, stat_index, value, expected_before, data_type)
    slot, stat_index, value, data_type = tonumber(slot), tonumber(stat_index), tonumber(value), tonumber(data_type) or 1
    if (slot ~= 0 and slot ~= 1) or not stat_index or stat_index % 1 ~= 0 or not value or value ~= value then
        return false, "character float-stat write is invalid"
    end
    local hash_ok, hash = native_try("int", GET_STAT_HASH_FOR_CHARACTER_STAT,
        math.floor(data_type), math.floor(stat_index), math.floor(slot))
    if not hash_ok or type(hash) ~= "number" or hash == 0 then
        return false, "_GET_STAT_HASH_FOR_CHARACTER_STAT failed for float index " .. tostring(stat_index)
    end
    local before, before_err = Module.Profile.read_hash_float(hash)
    if before == nil then return false, before_err end
    if expected_before ~= nil and math.abs(before - expected_before) > 0.0005 then
        return false, "character float stat changed before write"
    end
    local invoked, result = native_try("bool", Module.ProfileNative.SET_FLOAT, hash, value, true)
    if not invoked or result ~= true then return false, "Module.ProfileNative.SET_FLOAT rejected character stat index " .. tostring(stat_index) end
    local after, after_err = Module.Profile.read_hash_float(hash)
    if after == nil or math.abs(after - value) > 0.005 then
        native_try("bool", Module.ProfileNative.SET_FLOAT, hash, before, true)
        return false, after_err or "character float stat read-back verification failed"
    end
    return true, { changed=math.abs(before-value)>0.0005, before=before, after=after, hash=hash }
end

local function write_character_stat_index_verified(slot, stat_index, value, expected_before)
    slot, stat_index, value = tonumber(slot), tonumber(stat_index), tonumber(value)
    if (slot ~= 0 and slot ~= 1) or not stat_index or stat_index % 1 ~= 0
        or not value or value % 1 ~= 0 then return false, "character/stat index write is invalid" end
    local hash_ok, hash = native_try("int", GET_STAT_HASH_FOR_CHARACTER_STAT,
        0, math.floor(stat_index), math.floor(slot))
    if not hash_ok or type(hash) ~= "number" or hash == 0 then
        return false, "_GET_STAT_HASH_FOR_CHARACTER_STAT failed for index " .. tostring(stat_index)
    end
    local before, before_err = read_stat_hash_int(hash)
    if before == nil then return false, before_err end
    if expected_before ~= nil and before ~= expected_before then
        return false, ("stat index %d changed before write (expected %s, read %s)")
            :format(stat_index, tostring(expected_before), tostring(before))
    end
    if before == value then return true, { changed=false, before=before, after=before, hash=hash } end
    local invoked, result = native_try("bool", STAT_SET_INT, hash, math.floor(value), true)
    if not invoked or result ~= true then
        return false, "STAT_SET_INT rejected character stat index " .. tostring(stat_index)
    end
    local after, after_err = read_stat_hash_int(hash)
    if after ~= value then
        return false, after_err or ("character stat index %d read-back was %s, expected %s")
            :format(stat_index, tostring(after), tostring(value))
    end
    return true, { changed=true, before=before, after=after, hash=hash }
end

local function read_packed_bool(index, slot)
    index, slot = tonumber(index), tonumber(slot)
    if not index or index % 1 ~= 0 or (slot ~= 0 and slot ~= 1) then
        return nil, "packed bool index/character slot is invalid"
    end
    local ok, value = native_try("bool", GET_PACKED_STAT_BOOL_CODE, math.floor(index), math.floor(slot))
    if not ok or type(value) ~= "boolean" then
        return nil, "GET_PACKED_STAT_BOOL_CODE failed for " .. tostring(index)
    end
    return value
end


local function read_packed_int(index, slot)
    index, slot = tonumber(index), tonumber(slot)
    if not index or index % 1 ~= 0 or (slot ~= 0 and slot ~= 1) then
        return nil, "packed int index/character slot is invalid"
    end
    local ok, value = native_try("int", GET_PACKED_STAT_INT_CODE, math.floor(index), math.floor(slot))
    if not ok or type(value) ~= "number" then
        return nil, "GET_PACKED_STAT_INT_CODE failed for " .. tostring(index)
    end
    return math.floor(value)
end

local function unsigned32(value)
    value = tonumber(value)
    if not value then return nil end
    value = math.floor(value)
    if value < 0 then value = value + 4294967296 end
    return value % 4294967296
end

local function integer_bit_is_set(value, bit)
    value, bit = unsigned32(value), tonumber(bit)
    if value == nil or bit == nil or bit % 1 ~= 0 or bit < 0 or bit > 31 then return false end
    return math.floor(value / (2 ^ math.floor(bit))) % 2 == 1
end

local function write_packed_bool_verified(index, value, slot)
    local before, before_err = read_packed_bool(index, slot)
    if before == nil then return false, before_err end
    value = value == true
    if before == value then return true, { before=before, after=before, changed=false } end
    local invoked, failure = native_try("void", SET_PACKED_STAT_BOOL_CODE,
        math.floor(tonumber(index)), value, math.floor(tonumber(slot)))
    if not invoked then return false, "SET_PACKED_STAT_BOOL_CODE failed: " .. tostring(failure) end
    local after, read_err = read_packed_bool(index, slot)
    if after ~= value then
        -- This is a character-scoped packed flag, so a best-effort rollback to
        -- the independently captured value is valid when verification fails.
        native_try("void", SET_PACKED_STAT_BOOL_CODE,
            math.floor(tonumber(index)), before == true, math.floor(tonumber(slot)))
        return false, "packed bool read-back verification failed: " .. tostring(read_err or after)
    end
    return true, { before=before, after=after, changed=true }
end

local function is_online()
    local invoked, value = native_try("bool", NETWORK_IS_SESSION_STARTED)
    return invoked and value == true
end

local function detect_character_slot()
    if not is_online() then return nil, "GTA Online session is not active" end
    local value, err = read_stat("MPPLY_LAST_MP_CHAR")
    if value ~= 0 and value ~= 1 then
        return nil, "current character slot could not be validated: " .. tostring(err or value)
    end
    return value
end

local function qualify_stat(slot, key)
    key = tostring(key or "")
    if key:match("^MPPLY_") or key:match("^MP[01]_") or key == "BANK_BALANCE" then return key end
    return ("MP%d_%s"):format(tonumber(slot) or 0, key)
end

local function profile_progression_refresh()
    local slot, slot_err = detect_character_slot()
    local cache = {
        status = "PENDING", slot = slot, character = slot ~= nil and ("Character " .. tostring(slot + 1)) or "Unavailable",
        items = {}, available_count = 0, total_count = #RECOVERY_PROFILE_FIELDS, refreshed_at = epoch(),
    }
    if slot == nil then
        cache.status, cache.error = "UNAVAILABLE", slot_err
        State.profile_progression_cache = cache
        return false, slot_err
    end
    for _, descriptor in ipairs(RECOVERY_PROFILE_FIELDS) do
        local stat_name = descriptor.scope == "account" and descriptor.key or qualify_stat(slot, descriptor.key)
        local value, err = read_stat(stat_name)
        local available = type(value) == "number"
        if available then cache.available_count = cache.available_count + 1 end
        cache.items[#cache.items + 1] = {
            key = descriptor.key, label = descriptor.label, scope = descriptor.scope,
            value = value, available = available, error = available and nil or clean(err or "stat unavailable", 160),
            money = descriptor.money == true, suffix = descriptor.suffix,
        }
    end
    cache.status = cache.available_count == cache.total_count and "READY"
        or cache.available_count > 0 and "PARTIAL" or "UNAVAILABLE"
    if cache.available_count == 0 then cache.error = "no curated account/progression stats could be read" end
    State.profile_progression_cache = cache
    return cache.available_count > 0, cache.error
end

local function profile_progression_snapshot()
    local cache = State.profile_progression_cache
    if type(cache) ~= "table" then
        return { status="REFRESH_REQUIRED", items={}, available_count=0, total_count=#RECOVERY_PROFILE_FIELDS }
    end
    local copy = {
        status=cache.status, slot=cache.slot, character=cache.character, available_count=cache.available_count,
        total_count=cache.total_count, refreshed_at=cache.refreshed_at, error=cache.error, items={}
    }
    for i,item in ipairs(cache.items or {}) do
        copy.items[i] = { key=item.key,label=item.label,scope=item.scope,value=item.value,available=item.available,
            error=item.error,money=item.money,suffix=item.suffix }
    end
    return copy
end

local function serialize_snapshot(snapshot)
    local lines = {
        "CSCRIPT_HEIST_SNAPSHOT_V1",
        "version|" .. encode(snapshot.version), "time|" .. encode(snapshot.time),
        "slot|" .. encode(snapshot.slot), "family|" .. encode(snapshot.family),
        "action|" .. encode(snapshot.action),
    }
    for _, item in ipairs(snapshot.stats or {}) do
        lines[#lines + 1] = table.concat({
            "stat", encode(item.key), encode(item.before), encode(item.after), encode(item.label), encode(item.kind or "int")
        }, "|")
    end
    return table.concat(lines, "\n")
end

local function parse_snapshot(content, path)
    content = canonical_text(content)
    if type(content) ~= "string" or content:match("^([^\n]+)") ~= "CSCRIPT_HEIST_SNAPSHOT_V1" then
        return nil, "snapshot header is invalid"
    end
    local snapshot, first = { stats = {}, path = path }, true
    for line in content:gmatch("[^\n]+") do
        if first then first = false else
            local item = fields(line)
            if item[1] == "version" then snapshot.version = item[2]
            elseif item[1] == "time" then snapshot.time = tonumber(item[2])
            elseif item[1] == "slot" then snapshot.slot = tonumber(item[2])
            elseif item[1] == "family" then snapshot.family = item[2]
            elseif item[1] == "action" then snapshot.action = item[2]
            elseif item[1] == "stat" then
                snapshot.stats[#snapshot.stats + 1] = {
                    key = item[2], before = tonumber(item[3]), after = tonumber(item[4]), label = item[5], kind = item[6] or "int",
                }
            end
        end
    end
    if snapshot.slot ~= 0 and snapshot.slot ~= 1 then return nil, "snapshot character slot is invalid" end
    if #snapshot.stats == 0 then return nil, "snapshot contains no stat records" end
    return snapshot
end

local function create_snapshot(spec, slot, captured)
    if not State.paths then return nil, "snapshot storage is unavailable" end
    local snapshot = {
        version = module_context and module_context.LoaderVersion or "unknown", time = epoch(),
        slot = slot, family = clean(spec.family or "Heist", 48),
        action = clean(spec.label or spec.action_key, 80), stats = {},
    }
    for _, item in ipairs(captured) do
        snapshot.stats[#snapshot.stats + 1] = {
            key = item.key, before = item.before, after = item.after, label = item.label or item.key, kind = item.kind or "int",
        }
    end
    local path = State.paths.snapshots .. "\\" .. timestamp_id() .. "-"
        .. snapshot.family:gsub("[^%w_-]", "_") .. ".snapshot"
    local ok, err = write_file(path, serialize_snapshot(snapshot))
    if not ok then return nil, "snapshot write failed: " .. tostring(err) end
    local reread, read_err = read_file(path)
    local verified, parse_err = parse_snapshot(reread, path)
    if not verified then return nil, "snapshot verification failed: " .. tostring(read_err or parse_err) end
    return verified
end

-- Snapshot values stay numeric; the optional type selects the native stat ABI.
function Module.TransactionRead(key, kind)
    if kind ~= "bool" then return read_stat(key) end
    local value, why = Module.ReadBoolStat(key)
    if value == nil then return nil, why end
    return value and 1 or 0
end
function Module.TransactionWrite(key, value, kind)
    if kind ~= "bool" then return write_stat(key, value) end
    if value ~= 0 and value ~= 1 then return false, "Invalid boolean stat target." end
    local hash, why = stat_hash(key); if hash == nil then return false, why end
    local called, accepted = native_try("bool", 0x4B33C4243DE0C432, hash, value == 1, true)
    return called and accepted == true, "Boolean stat write rejected: " .. tostring(key)
end

local function rollback_stats(captured, applied_count)
    local failures = {}
    for index = math.min(applied_count or #captured, #captured), 1, -1 do
        local item = captured[index]
        local ok, err = Module.TransactionWrite(item.key, item.before, item.kind)
        if ok then
            local observed = Module.TransactionRead(item.key, item.kind)
            if observed ~= item.before then ok, err = false, "rollback verification mismatch" end
        end
        if not ok then failures[#failures + 1] = item.key .. ": " .. tostring(err) end
    end
    return #failures == 0, table.concat(failures, "; ")
end

local function run_transaction(spec)
    spec = type(spec) == "table" and spec or {}
    local action_key = clean(spec.action_key, 80)
    if action_key == "" then return false, "transaction action key is required" end
    if State.in_flight then return false, "another Economy transaction is already in progress" end
    if type(spec.values) ~= "table" or next(spec.values) == nil then return false, "transaction has no values to apply" end
    State.in_flight, State.transaction_status = action_key, "VALIDATE"

    local success, result, detail = xpcall(function()
        local slot, slot_err = detect_character_slot()
        if slot == nil then error(slot_err) end
        if spec.expected_slot ~= nil and tonumber(spec.expected_slot) ~= slot then
            error(("character slot changed (expected %s, current %s)"):format(tostring(spec.expected_slot), tostring(slot)))
        end
        if type(spec.validate) == "function" then
            local valid, reason = spec.validate(slot)
            if valid ~= true then error(reason or "transaction validation failed") end
        end

        State.transaction_status = "CAPTURE"
        local captured, ordered = {}, spec.order or {}
        if #ordered == 0 then for key in pairs(spec.values) do ordered[#ordered + 1] = key end; table.sort(ordered) end
        for _, raw_key in ipairs(ordered) do
            local key = qualify_stat(slot, raw_key)
            local kind = spec.types and spec.types[raw_key] or "int"
            if kind ~= "int" and kind ~= "bool" then error("Unknown stat type") end
            local before, read_err = Module.TransactionRead(key, kind)
            if before == nil then error("cannot read " .. key .. ": " .. tostring(read_err)) end
            local after = tonumber(spec.values[raw_key])
            if not after or after ~= math.floor(after) or (kind == "bool" and after ~= 0 and after ~= 1) then error("invalid target value for " .. key) end
            captured[#captured + 1] = {
                key = key, before = before, after = after, kind = kind,
                label = type(spec.labels) == "table" and spec.labels[raw_key] or raw_key,
            }
        end

        local changed = {}
        for _, item in ipairs(captured) do
            if item.before ~= item.after then changed[#changed + 1] = item end
        end

        local snapshot
        if #changed > 0 then
            State.transaction_status = "SNAPSHOT"
            local snapshot_err
            snapshot, snapshot_err = create_snapshot(spec, slot, changed)
            if not snapshot then error(snapshot_err) end
        end

        -- Primary heist Apply opts into a second scope check after snapshot
        -- I/O, before the first write or no-op verification. Other callers keep
        -- the existing transaction contract.
        if spec.revalidate_before_apply == true then
            local current_slot, slot_err = detect_character_slot()
            if current_slot == nil or current_slot ~= slot then
                error(slot_err or "character slot changed before apply")
            end
            local expected_account = tonumber(spec.expected_account)
            local current_account = resolve_local_account_identity()
            if not expected_account or expected_account <= 0 or expected_account >= math.huge
                or expected_account ~= math.floor(expected_account) or current_account ~= expected_account
                or State.account_id ~= expected_account or State.account_verified ~= true then
                error("Rockstar account changed before apply")
            end
            if type(spec.validate) == "function" then
                local valid, reason = spec.validate(current_slot)
                if valid ~= true then error(reason or "transaction validation failed before apply") end
            end
        end

        State.transaction_status = "APPLY"
        local applied = 0
        for _, item in ipairs(changed) do
            local wrote, write_err = Module.TransactionWrite(item.key, item.after, item.kind)
            if not wrote then
                -- A backend may mutate then report failure; include the attempted field.
                local rollback_ok, rollback_err = rollback_stats(changed, applied + 1)
                error(("apply failed at %s: %s; rollback=%s%s"):format(item.key, tostring(write_err),
                    rollback_ok and "complete" or "incomplete",
                    rollback_err ~= "" and (" (" .. rollback_err .. ")") or ""))
            end
            applied = applied + 1
        end

        State.transaction_status = "VERIFY"
        local verified = 0
        for _, item in ipairs(captured) do
            local observed, read_err = Module.TransactionRead(item.key, item.kind)
            if observed ~= item.after then
                local rollback_ok, rollback_err = rollback_stats(changed, applied)
                error(("verification failed at %s (wanted %s, got %s: %s); rollback=%s%s"):format(
                    item.key, tostring(item.after), tostring(observed), tostring(read_err or "mismatch"),
                    rollback_ok and "complete" or "incomplete",
                    rollback_err ~= "" and (" (" .. rollback_err .. ")") or ""))
            end
            verified = verified + 1
        end

        State.last_changes = changed
        if snapshot then State.last_snapshot = snapshot end
        local summary = {
            target_count = #captured, changed_count = #changed, verified_count = verified,
            snapshot = snapshot,
        }
        if #changed == 0 then
            State.transaction_status = "ALREADY_APPLIED"
            add_history("info", spec.label or action_key,
                ("Already in requested state; targets=%d changed=0 verified=%d"):format(#captured, verified))
        else
            State.transaction_status = "SUCCESS"
            add_history("success", spec.label or action_key,
                ("targets=%d changed=%d verified=%d snapshot=%s"):format(
                    #captured, #changed, verified, tostring(snapshot.path)))
        end
        save_histories()
        return snapshot, summary
    end, function(err) return tostring(err) end)

    State.in_flight = nil
    if not success then
        State.transaction_status, State.last_error = "ERROR", clean(result, 240)
        add_history("error", spec.label or action_key, State.last_error)
        save_histories()
        notify("Error", (spec.label or "Economy action") .. " failed: " .. State.last_error, 7500)
        log_error((spec.label or action_key) .. " failed: " .. State.last_error)
        return false, State.last_error
    end
    State.last_error = nil
    if State.transaction_status == "ALREADY_APPLIED" then
        notify("Info", "Already in the requested state. No GTA values changed.", 5000)
    else
        notify("Success", (spec.label or "Economy action") .. " completed and verified.", 5000)
    end
    return true, result, detail
end

local function restore_last_snapshot()
    local snapshot = State.last_snapshot
    if not snapshot then return false, "no Economy snapshot is available in this session" end
    local values, order, labels, types = {}, {}, {}, {}
    for _, item in ipairs(snapshot.stats or {}) do
        values[item.key], order[#order + 1], labels[item.key] = item.before, item.key, item.label
        types[item.key] = item.kind or "int"
    end
    return run_transaction({
        action_key = "restore:" .. tostring(snapshot.path or snapshot.time),
        label = "Restore Economy Snapshot", family = snapshot.family or "Restore",
        expected_slot = snapshot.slot, values = values, order = order, labels = labels, types = types,
    })
end

local function career_refresh()
    local slot, slot_err = detect_character_slot()
    local result = { status = "UNAVAILABLE", slot = slot, character = slot ~= nil and ("Character " .. tostring(slot + 1)) or "Unavailable" }
    if slot == nil then result.error = slot_err; State.career_cache = result; return false, result end
    local final_ok, finalized = native_try("bool", HAS_FINALIZED_CHOSEN_CRIMINAL_CAREER)
    local id_ok, career_id = native_try("int", GET_CHOSEN_CRIMINAL_CAREER)
    career_id = id_ok and tonumber(career_id) or nil
    if not final_ok or career_id == nil or career_id % 1 ~= 0 or career_id < 0 or career_id > 16 then
        result.error = "current Enhanced Criminal Career state could not be validated"
        State.career_cache = result
        return false, result
    end
    result.status = "READY"
    result.finalized = finalized == true
    result.career_id = math.floor(career_id)
    result.source = "mp_unlocks.c / fm_maintain_cloud_header_data.c current Enhanced native path"
    result.note = "Raw career ID is shown without guessed labels; CScript does not mutate Criminal Career selection."
    State.career_cache = result
    return true, result
end

local function career_snapshot()
    local c = State.career_cache
    if type(c) ~= "table" then return { status = "REFRESH_REQUIRED" } end
    return { status=c.status, slot=c.slot, character=c.character, finalized=c.finalized, career_id=c.career_id, source=c.source, note=c.note, error=c.error }
end

local function career_progress_completion(pack, tier, completion_values)
    local order = CAREER_PROGRESS_ORDER[pack]
    if order == nil then return nil, "career pack order is unavailable" end
    local group = math.floor(order / 8)
    local value = completion_values[group + 1]
    if value == nil then return nil, "career completion bitset is unavailable" end
    local base_bit = (order % 8) * 4
    local completed = 0
    for offset = 0, 3 do
        if not integer_bit_is_set(value, base_bit + offset) then break end
        completed = completed + 1
    end
    return completed > tier
end

local function career_supplemental_claim(pack, claim_values, kind)
    local order = CAREER_PROGRESS_ORDER[pack]
    if order == nil then return nil, "career reward order is unavailable" end
    local first = kind == 4 and 16798 or 16799
    local second = kind == 4 and 18533 or 18534
    local stat_index = math.floor(order / 32) == 0 and first or second
    local value = claim_values[stat_index]
    if value == nil then return nil, "career reward claim bitset is unavailable" end
    local bit = order % 32
    return integer_bit_is_set(value, bit), nil, { kind="reward_bit", stat_index=stat_index, bit=bit }
end

local function career_progress_claimed(slot, pack, tier, claim_values)
    local claim_type = career_claim_type(pack, tier)
    local claimed, claim_err, claim_meta
    if claim_type == 2 then
        local index = CAREER_CLAIM_PACKED[pack] and CAREER_CLAIM_PACKED[pack][tier]
        if not index then return nil, "packed claim marker is not mapped" end
        claimed, claim_err = read_packed_bool(index, slot)
        claim_meta = { kind="packed_bool", index=index }
    elseif claim_type == 1 then
        local bit = CAREER_TYPE1_BITS[pack]
        if bit == nil or claim_values[16805] == nil then return nil, "type-1 claim bit is unavailable" end
        claimed, claim_meta = integer_bit_is_set(claim_values[16805], bit), { kind="character_bit", stat_index=16805, bit=bit }
    elseif claim_type == 3 then
        local bit = CAREER_TYPE3_BITS[pack]
        if bit == nil or claim_values[16806] == nil then return nil, "type-3 claim bit is unavailable" end
        claimed, claim_meta = integer_bit_is_set(claim_values[16806], bit), { kind="character_bit", stat_index=16806, bit=bit }
    elseif claim_type == 0 then
        local bit = CAREER_TYPE0_BITS[pack]
        if bit == nil or claim_values[16800] == nil then return nil, "vehicle-reward claim bit is unavailable" end
        claimed, claim_meta = integer_bit_is_set(claim_values[16800], bit), { kind="vehicle_reward_bit", stat_index=16800, bit=bit, vehicle=CAREER_REWARD_VEHICLES[pack] }
    elseif claim_type == 4 or claim_type == 5 then
        claimed, claim_err, claim_meta = career_supplemental_claim(pack, claim_values, claim_type)
    else
        return nil, "unknown claim representation"
    end
    if claimed == nil then return nil, claim_err or "career reward claim marker is unavailable" end

    -- Current freemode.c func_16070 defines tier 4 as fully claimed only when
    -- the primary func_16053 marker AND both supplemental pack-order bits
    -- (func_16068 / func_16067) are present. Treating only the primary marker
    -- as claimed would hide a partially delivered tier-4 reward.
    if tier == 3 then
        local supplemental4, err4, meta4 = career_supplemental_claim(pack, claim_values, 4)
        local supplemental5, err5, meta5 = career_supplemental_claim(pack, claim_values, 5)
        if supplemental4 == nil or supplemental5 == nil then
            return nil, err4 or err5 or "tier-4 supplemental claim state is unavailable"
        end
        claim_meta.supplemental = { meta4, meta5 }
        claim_meta.primary_claimed = claimed == true
        claim_meta.supplemental_claimed = supplemental4 == true and supplemental5 == true
        claimed = claimed == true and supplemental4 == true and supplemental5 == true
    end
    return claimed, claim_err, claim_meta
end

local function career_progress_refresh()
    local slot, slot_err = detect_character_slot()
    local cache = { status="UNAVAILABLE", slot=slot, character=slot ~= nil and ("Character "..tostring(slot+1)) or "Unavailable",
        packs={}, completed_tiers=0, claimed_rewards=0, unclaimed_rewards=0, readable_packs=0, total_packs=#CAREER_PROGRESS_PACKS, refreshed_at=epoch() }
    if slot == nil then cache.error=slot_err; State.career_progress_cache=cache; return false,slot_err end
    local completion_values = {}
    for i,stat_index in ipairs(CAREER_COMPLETION_STATS) do completion_values[i]=select(1,read_character_stat_index(slot,stat_index,0)) end
    local claim_values = {}
    for _,stat_index in ipairs({16800,16805,16806,16798,18533,16799,18534}) do claim_values[stat_index]=select(1,read_character_stat_index(slot,stat_index,0)) end
    for _,descriptor in ipairs(CAREER_PROGRESS_PACKS) do
        local pack={ id=descriptor.id,token=descriptor.token,label=descriptor.label,tiers={},completed=0,claimed=0,unclaimed=0,readable=true }
        for tier=0,3 do
            local complete, complete_err=career_progress_completion(descriptor.id,tier,completion_values)
            local claimed, claim_err, claim_meta=career_progress_claimed(slot,descriptor.id,tier,claim_values)
            local readable=complete~=nil and claimed~=nil
            if not readable then pack.readable=false end
            if complete==true then pack.completed=pack.completed+1; cache.completed_tiers=cache.completed_tiers+1 end
            if claimed==true then pack.claimed=pack.claimed+1; cache.claimed_rewards=cache.claimed_rewards+1 end
            local unclaimed=complete==true and claimed==false
            if unclaimed then pack.unclaimed=pack.unclaimed+1; cache.unclaimed_rewards=cache.unclaimed_rewards+1 end
            pack.tiers[#pack.tiers+1]={ tier=tier+1, complete=complete, claimed=claimed, unclaimed=unclaimed,
                readable=readable, completion_error=complete_err, claim_error=claim_err, claim=claim_meta }
        end
        if pack.readable then cache.readable_packs=cache.readable_packs+1 end
        cache.packs[#cache.packs+1]=pack
    end
    cache.status=cache.readable_packs==cache.total_packs and "READY" or cache.readable_packs>0 and "PARTIAL" or "UNAVAILABLE"
    cache.note="Read-only Career Progress checks. Tier 4 requires the primary marker and both supplemental reward bits. Claim markers remain unchanged to preserve unclaimed rewards."
    State.career_progress_cache=cache
    return cache.readable_packs>0, cache.error
end

local function career_progress_snapshot()
    local c=State.career_progress_cache
    if type(c)~="table" then return {status="REFRESH_REQUIRED",packs={},completed_tiers=0,claimed_rewards=0,unclaimed_rewards=0,readable_packs=0,total_packs=#CAREER_PROGRESS_PACKS} end
    local out={status=c.status,slot=c.slot,character=c.character,completed_tiers=c.completed_tiers,claimed_rewards=c.claimed_rewards,
        unclaimed_rewards=c.unclaimed_rewards,readable_packs=c.readable_packs,total_packs=c.total_packs,refreshed_at=c.refreshed_at,error=c.error,note=c.note,packs={}}
    for i,p in ipairs(c.packs or {}) do
        local cp={id=p.id,token=p.token,label=p.label,completed=p.completed,claimed=p.claimed,unclaimed=p.unclaimed,readable=p.readable,tiers={}}
        for j,t in ipairs(p.tiers or {}) do cp.tiers[j]={tier=t.tier,complete=t.complete,claimed=t.claimed,unclaimed=t.unclaimed,readable=t.readable,completion_error=t.completion_error,claim_error=t.claim_error,claim=t.claim} end
        out.packs[i]=cp
    end
    return out
end

local function recovery_refresh()
    local slot, slot_err = detect_character_slot()
    local cache = {
        status = slot ~= nil and "READY" or "UNAVAILABLE",
        slot = slot,
        character = slot ~= nil and ("Character " .. tostring(slot + 1)) or "Unavailable",
        error = slot_err,
        skills = {},
        available_count = 0,
        total_count = #RECOVERY_SKILLS,
        refreshed_at = epoch(),
    }
    if slot == nil then
        State.recovery_cache = cache
        return false, slot_err
    end
    for _, descriptor in ipairs(RECOVERY_SKILLS) do
        local qualified = qualify_stat(slot, descriptor.key)
        local value, err = read_stat(qualified)
        local available = type(value) == "number"
            and value >= descriptor.minimum and value <= descriptor.maximum
        cache.skills[#cache.skills + 1] = {
            key = descriptor.key, label = descriptor.label, stat = qualified,
            value = value, minimum = descriptor.minimum, maximum = descriptor.maximum,
            available = available, error = available and nil or tostring(err or "value outside expected 0..100 range"),
        }
        if available then cache.available_count = cache.available_count + 1 end
    end
    if cache.available_count == 0 then
        cache.status = "UNAVAILABLE"
        cache.error = "none of the curated skill stats passed live read/range validation"
    elseif cache.available_count < cache.total_count then
        cache.status = "PARTIAL"
    end
    State.recovery_cache = cache
    career_refresh()
    return cache.available_count > 0, cache
end

local function recovery_apply(values, label, action_key)
    local slot, slot_err = detect_character_slot()
    if slot == nil then return false, slot_err end
    local normalized, order, labels = {}, {}, {}
    for raw_key, raw_value in pairs(values or {}) do
        local descriptor = RECOVERY_SKILL_BY_KEY[tostring(raw_key)]
        if not descriptor then return false, "unsupported curated recovery key: " .. tostring(raw_key) end
        local value = tonumber(raw_value)
        if not value or value ~= math.floor(value) or value < descriptor.minimum or value > descriptor.maximum then
            return false, descriptor.label .. " must be an integer from 0 to 100"
        end
        local current, read_err = read_stat(qualify_stat(slot, descriptor.key))
        if type(current) ~= "number" or current < descriptor.minimum or current > descriptor.maximum then
            return false, descriptor.label .. " live validation failed: " .. tostring(read_err or current)
        end
        normalized[descriptor.key] = value
        order[#order + 1] = descriptor.key
        labels[descriptor.key] = descriptor.label
    end
    table.sort(order)
    local ok, snapshot, detail = run_transaction({
        action_key = action_key or "recovery:skills",
        label = label or "Recovery Skills",
        family = "Recovery Skills",
        expected_slot = slot,
        values = normalized,
        order = order,
        labels = labels,
        validate = function(current_slot)
            if current_slot ~= slot then return false, "character slot changed before recovery write" end
            for _, key in ipairs(order) do
                local descriptor = RECOVERY_SKILL_BY_KEY[key]
                local current, err = read_stat(qualify_stat(current_slot, key))
                if type(current) ~= "number" or current < descriptor.minimum or current > descriptor.maximum then
                    return false, descriptor.label .. " failed pre-write validation: " .. tostring(err or current)
                end
            end
            return true
        end,
    })
    if ok then
        State.recovery_last_snapshot = snapshot
        recovery_refresh()
    end
    return ok, snapshot, detail
end

local function recovery_set_skill(key, value)
    local descriptor = RECOVERY_SKILL_BY_KEY[tostring(key)]
    if not descriptor then return false, "unknown curated recovery skill" end
    return recovery_apply({ [descriptor.key] = value }, "Set " .. descriptor.label,
        "recovery:skill:" .. descriptor.key)
end

local function recovery_max_skills()
    local values = {}
    for _, descriptor in ipairs(RECOVERY_SKILLS) do values[descriptor.key] = descriptor.maximum end
    return recovery_apply(values, "Max Character Skills", "recovery:max_skills")
end

local function recovery_restore_last()
    local snapshot = State.recovery_last_snapshot
    if not snapshot or snapshot.family ~= "Recovery Skills" then
        return false, "no Recovery Skills snapshot is available in this session"
    end
    local values = {}
    for _, item in ipairs(snapshot.stats or {}) do
        local raw = tostring(item.key):gsub("^MP[01]_", "")
        if RECOVERY_SKILL_BY_KEY[raw] then values[raw] = item.before end
    end
    if next(values) == nil then return false, "Recovery snapshot contains no supported skill records" end
    return recovery_apply(values, "Restore Character Skills", "recovery:restore_skills")
end

local recovery_snapshot
local read_money

local function achievement_refresh()
    local slot, slot_err = detect_character_slot()
    local cache = {
        status = slot ~= nil and "READY" or "UNAVAILABLE",
        slot = slot, character = slot ~= nil and ("Character " .. tostring(slot + 1)) or "Unavailable",
        error = slot_err, items = {}, available_count = 0, passed_count = 0,
        total_count = #RECOVERY_ACHIEVEMENTS, refreshed_at = epoch(),
    }
    if slot == nil then State.achievement_cache = cache; return false, slot_err end
    for _, descriptor in ipairs(RECOVERY_ACHIEVEMENTS) do
        local invoked, passed_or_err = native_try("bool", HAS_ACHIEVEMENT_BEEN_PASSED, descriptor.id)
        local available = invoked == true and type(passed_or_err) == "boolean"
        local progress, progress_available
        if available then
            local progress_ok, raw_progress = native_try("int", GET_ACHIEVEMENT_PROGRESS, descriptor.id)
            if progress_ok and type(raw_progress) == "number" and raw_progress >= 0 and raw_progress <= 100 then
                progress, progress_available = math.floor(raw_progress), true
            end
        end
        local item = {
            id = descriptor.id, label = descriptor.label, group = descriptor.group,
            available = available, passed = available and passed_or_err == true or false,
            grant_supported = descriptor.grant_supported ~= false,
            catalog_status = descriptor.grant_supported == false and "UNVERIFIED" or "SOURCE_ID",
            unsupported_reason = descriptor.unsupported_reason,
            progress = progress, progress_available = progress_available == true,
            error = available and nil or clean(passed_or_err or "achievement native unavailable", 160),
        }
        cache.items[#cache.items + 1] = item
        if available then
            cache.available_count = cache.available_count + 1
            if item.passed then cache.passed_count = cache.passed_count + 1 end
        end
    end
    if cache.available_count == 0 then
        cache.status, cache.error = "UNAVAILABLE", "achievement state could not be read on this runtime"
    elseif cache.available_count < cache.total_count then cache.status = "PARTIAL" end
    State.achievement_cache = cache
    return cache.available_count > 0, cache
end

local function achievement_grant(id, options)
    options = type(options) == "table" and options or {}
    local refresh_after = options.refresh ~= false
    local silent = options.silent == true
    id = tonumber(id)
    if not id or id % 1 ~= 0 then return false, "achievement id is invalid" end
    id = math.floor(id)
    local descriptor = RECOVERY_ACHIEVEMENT_BY_ID[id]
    if not descriptor then return false, "achievement is outside CScript's curated Recovery catalog" end
    local generation = State.generation
    local slot, slot_err = detect_character_slot()
    if slot == nil then return false, slot_err end

    local read_ok, before = native_try("bool", HAS_ACHIEVEMENT_BEEN_PASSED, id)
    if not read_ok then return false, "achievement pre-read failed: " .. tostring(before) end
    if before == true then
        if refresh_after then achievement_refresh() end
        return true, descriptor.label .. " is already passed; zero writes were performed."
    end
    if type(before) ~= "boolean" then return false, "achievement pre-read returned an invalid value", "UNAVAILABLE" end
    if descriptor.grant_supported == false then return false, descriptor.unsupported_reason, "UNSUPPORTED" end

    -- achievement_controller.c func_104 refuses grants while Global_44938 == 14
    -- except the exact source-backed exemption set 60..69 (func_105). Mirror
    -- that prerequisite before invoking the irreversible platform grant.
    local script_global = module_context and module_context.Raw and module_context.Raw.ScriptGlobal
    if script_global == nil and type(_G) == "table" then script_global = rawget(_G, "ScriptGlobal") end
    if not (script_global and type(script_global.GetInt) == "function") then
        return false, "achievement state prerequisite could not be validated because ScriptGlobal.GetInt is unavailable"
    end
    local state_ok, controller_state = pcall(script_global.GetInt, 44938)
    controller_state = state_ok and tonumber(controller_state) or nil
    if controller_state == nil or controller_state % 1 ~= 0 then
        return false, "achievement controller prerequisite Global_44938 could not be validated"
    end
    local state14_exempt = id >= 60 and id <= 69
    if controller_state == 14 and not state14_exempt then
        return false, "current Enhanced achievement controller blocks this achievement in state 14; zero writes were performed", "CONTEXT_BLOCKED"
    end

    -- Current Enhanced achievement_controller.c uses GIVE_ACHIEVEMENT_TO_PLAYER
    -- and immediately verifies HAS_ACHIEVEMENT_BEEN_PASSED. Achievements are
    -- platform/account state and are inherently irreversible; unlike stat
    -- transactions there is no valid rollback primitive. CScript therefore
    -- services explicit single/bulk requests one item at a time with read-back.
    local final_slot = detect_character_slot()
    local still_requested = not options.current or options.current()
    if final_slot ~= slot or not still_requested or State.generation ~= generation then
        return false, "achievement request cancelled before grant; zero writes were performed", "CANCELLED"
    end
    local invoked, result = native_try("bool", GIVE_ACHIEVEMENT_TO_PLAYER, id)
    if not invoked then return false, "achievement grant native failed: " .. tostring(result) end
    if result ~= true then
        return false, "achievement grant explicitly rejected (native_result=" .. tostring(result) .. ")", "REJECTED"
    end
    local verify_ok, passed = native_try("bool", HAS_ACHIEVEMENT_BEEN_PASSED, id)
    if not verify_ok or passed ~= true then
        return false, ("achievement grant was not verified (native_result=%s readback=%s)")
            :format(tostring(result), tostring(passed))
    end

    if refresh_after then achievement_refresh() end
    if not silent then
        add_history("success", "Achievement Recovery",
            ("Granted and verified achievement %d (%s) for Character %d. This platform change is irreversible.")
                :format(id, descriptor.label, slot + 1))
        save_histories()
        notify("Success", "Achievement granted and verified: " .. descriptor.label, 6000)
    end
    return true, descriptor.label .. " granted and verified."
end

local function achievement_snapshot()
    local cache = State.achievement_cache
    if type(cache) ~= "table" then
        return { status="REFRESH_REQUIRED", slot=State.character_slot, character=State.character_label or "Unavailable",
            items={}, available_count=0, passed_count=0, total_count=#RECOVERY_ACHIEVEMENTS,
            bulk=State.achievement_bulk }
    end
    local copy = {
        status=cache.status, slot=cache.slot, character=cache.character, error=cache.error,
        available_count=cache.available_count, passed_count=cache.passed_count,
        total_count=cache.total_count, refreshed_at=cache.refreshed_at, items={},
        bulk=nil,
    }
    for i,item in ipairs(cache.items or {}) do
        copy.items[i] = { id=item.id,label=item.label,group=item.group,available=item.available,passed=item.passed,
            progress=item.progress,progress_available=item.progress_available,error=item.error,
            grant_supported=item.grant_supported,catalog_status=item.catalog_status,unsupported_reason=item.unsupported_reason }
    end
    local bulk = State.achievement_bulk
    if type(bulk) == "table" then
        copy.bulk = {
            active=bulk.active==true,status=bulk.status,index=bulk.index,total=bulk.total,
            granted=bulk.granted,skipped=bulk.skipped,failed=bulk.failed,
            slot=bulk.slot,error=bulk.error,current_label=bulk.current_label,
            current_id=bulk.current_id,failed_id=bulk.failed_id,failed_label=bulk.failed_label,
            unsupported=bulk.unsupported,rejected=bulk.rejected,context_blocked=bulk.context_blocked,
            pending=0,completed=bulk.granted,already_passed=bulk.skipped,
        }
    end
    return copy
end

local function achievement_bulk_start()
    if type(State.achievement_bulk) == "table" and State.achievement_bulk.active then
        return false, "Grant All Missing Achievements is already running."
    end
    local slot, slot_err = detect_character_slot()
    if slot == nil then return false, slot_err end
    State.achievement_bulk = {
        active=true, status="RUNNING", index=1, total=#RECOVERY_ACHIEVEMENTS,
        granted=0, skipped=0, failed=0, unsupported=0, rejected=0, context_blocked=0, slot=slot,
        generation=tonumber(State.generation) or 0, error=nil, current_label=nil,
    }
    return true, "Grant All Missing Achievements started. Each irreversible grant is read back before the next one."
end

local function achievement_bulk_cancel()
    local bulk = State.achievement_bulk
    if type(bulk) ~= "table" or not bulk.active then return false, "No bulk achievement grant is running." end
    bulk.active, bulk.status, bulk.current_label = false, "CANCELLED", nil
    achievement_refresh()
    return true, "Bulk achievement grant cancelled; already verified grants remain passed."
end

local function achievement_bulk_tick()
    local bulk = State.achievement_bulk
    if type(bulk) ~= "table" or not bulk.active then return end
    local slot = detect_character_slot()
    if slot ~= bulk.slot or (tonumber(State.generation) or 0) ~= bulk.generation then
        bulk.active, bulk.status = false, "FAILED"
        bulk.failed = (tonumber(bulk.failed) or 0) + 1
        bulk.error = "character/session identity changed during the bulk grant"
        achievement_refresh()
        return
    end
    local descriptor = RECOVERY_ACHIEVEMENTS[tonumber(bulk.index) or 1]
    if not descriptor then
        bulk.active, bulk.status, bulk.current_label = false,
            (bulk.unsupported or 0) > 0 and "COMPLETE_WITH_SKIPS" or "COMPLETE", nil
        achievement_refresh()
        add_history("success", "Achievement Recovery",
            ("Bulk grant completed for Character %d: %d verified, %d already passed, %d unsupported skipped.")
                :format(slot + 1, tonumber(bulk.granted) or 0, tonumber(bulk.skipped) or 0, bulk.unsupported or 0))
        save_histories()
        notify((bulk.unsupported or 0) > 0 and "Warning" or "Success",
            ("Achievement review complete: %d verified, %d already passed, %d unsupported skipped.")
            :format(tonumber(bulk.granted) or 0, tonumber(bulk.skipped) or 0, bulk.unsupported or 0), 7000)
        return
    end
    bulk.current_label, bulk.current_id = descriptor.label, descriptor.id
    local read_ok, passed = native_try("bool", HAS_ACHIEVEMENT_BEEN_PASSED, descriptor.id)
    if not read_ok or type(passed) ~= "boolean" then
        bulk.active, bulk.status = false, "FAILED"
        bulk.failed = (tonumber(bulk.failed) or 0) + 1
        bulk.failed_id, bulk.failed_label = descriptor.id, descriptor.label
        bulk.error = "pre-read failed for " .. tostring(descriptor.label)
        achievement_refresh()
        return
    end
    if passed then
        bulk.skipped = (tonumber(bulk.skipped) or 0) + 1
    elseif descriptor.grant_supported == false then
        bulk.unsupported = (bulk.unsupported or 0) + 1
    else
        local granted, detail, disposition = achievement_grant(descriptor.id, { refresh=false, silent=true,
            current=function() return State.achievement_bulk == bulk and bulk.active and bulk.generation == State.generation end })
        if not granted then
            bulk.active, bulk.status = false, "FAILED"
            bulk.failed = (tonumber(bulk.failed) or 0) + 1
            bulk.failed_id, bulk.failed_label = descriptor.id, descriptor.label
            bulk.rejected = (bulk.rejected or 0) + (disposition == "REJECTED" and 1 or 0)
            bulk.context_blocked = (bulk.context_blocked or 0) + (disposition == "CONTEXT_BLOCKED" and 1 or 0)
            bulk.error = ("ID %d (%s): %s"):format(descriptor.id, descriptor.label, tostring(detail))
            achievement_refresh()
            notify("Warning", "Bulk achievement grant stopped: " .. tostring(detail), 7000)
            return
        end
        bulk.granted = (tonumber(bulk.granted) or 0) + 1
    end
    bulk.index = (tonumber(bulk.index) or 1) + 1
end

local function award_reward_refresh()
    local slot, slot_err = detect_character_slot()
    local cache = {
        status = slot ~= nil and "READY" or "UNAVAILABLE",
        slot = slot, character = slot ~= nil and ("Character " .. tostring(slot + 1)) or "Unavailable",
        error = slot_err, completed_sets = 0, source_values = {}, items = {},
        readable_sources = 0, total_sources = #AWARD_SET_STAT_INDEXES,
        refreshed_at = epoch(),
    }
    if slot == nil then State.award_reward_cache = cache; return false, slot_err end

    local completed = 0
    for _, stat_index in ipairs(AWARD_SET_STAT_INDEXES) do
        local value, err = read_character_stat_index(slot, stat_index, 0)
        local readable = type(value) == "number" and value >= -2147483648 and value <= 2147483647
        cache.source_values[#cache.source_values + 1] = {
            stat_index=stat_index, value=value, readable=readable, error=readable and nil or err,
        }
        if not readable then
            cache.status = "UNAVAILABLE"
            cache.error = "Rockstar award-set prerequisite stat " .. tostring(stat_index) .. " could not be read"
            State.award_reward_cache = cache
            return false, cache.error
        end
        cache.readable_sources = cache.readable_sources + 1
        -- mp_awards.c func_54: 8 groups * 4 bits in each of five bitsets.
        local unsigned = value
        if unsigned < 0 then unsigned = unsigned + 4294967296 end
        for group = 0, 7 do
            local group_complete = true
            for bit = 0, 3 do
                local offset = (group * 4) + bit
                if math.floor(unsigned / (2 ^ offset)) % 2 ~= 1 then
                    group_complete = false
                    break
                end
            end
            if group_complete then completed = completed + 1 end
        end
    end
    cache.completed_sets = completed

    for _, descriptor in ipairs(RECOVERY_AWARD_REWARDS) do
        local unlocked, err = read_packed_bool(descriptor.packed_bool, slot)
        local readable = type(unlocked) == "boolean"
        cache.items[#cache.items + 1] = {
            threshold=descriptor.threshold, packed_bool=descriptor.packed_bool,
            text_key=descriptor.text_key, label=descriptor.label,
            eligible=completed >= descriptor.threshold, unlocked=unlocked == true,
            available=readable, error=readable and nil or err,
        }
        if not readable then
            cache.status = "PARTIAL"
            cache.error = cache.error or "one or more derived packed reward flags could not be read"
        end
    end
    State.award_reward_cache = cache
    return true, cache
end

local function award_reward_repair(flag_index)
    flag_index = tonumber(flag_index)
    if not flag_index or flag_index % 1 ~= 0 then return false, "award reward flag is invalid" end
    flag_index = math.floor(flag_index)
    local descriptor = RECOVERY_AWARD_REWARD_BY_FLAG[flag_index]
    if not descriptor then return false, "award reward is outside CScript's curated repair catalog" end
    local slot, slot_err = detect_character_slot()
    if slot == nil then return false, slot_err end

    local ok, cache_or_err = award_reward_refresh()
    local cache = State.award_reward_cache
    if not ok or type(cache) ~= "table" then return false, tostring(cache_or_err or "award prerequisites unavailable") end
    if cache.slot ~= slot then return false, "character slot changed during award prerequisite validation" end
    if (tonumber(cache.completed_sets) or 0) < descriptor.threshold then
        return false, ("Rockstar prerequisite is not met: %d / %d completed award sets")
            :format(tonumber(cache.completed_sets) or 0, descriptor.threshold)
    end

    local before, before_err = read_packed_bool(flag_index, slot)
    if before == nil then return false, before_err end
    if before == true then
        return true, descriptor.label .. " reward flag is already present; zero writes were performed."
    end

    -- mp_awards.c func_52 performs exactly this derived write after recomputing
    -- the same completed-set count. CScript mirrors only that one missing flag.
    local wrote, detail = write_packed_bool_verified(flag_index, true, slot)
    if not wrote then
        award_reward_refresh()
        return false, tostring(detail)
    end
    local verify = read_packed_bool(flag_index, slot)
    if verify ~= true then
        if detail and detail.changed then
            native_try("void", SET_PACKED_STAT_BOOL_CODE, flag_index, detail.before == true, slot)
        end
        award_reward_refresh()
        return false, "derived reward flag did not remain set after independent verification"
    end

    award_reward_refresh()
    add_history("success", "Award Reward Recovery",
        ("Repaired earned reward %s (%s / packed %d) after verifying %d completed award sets for Character %d.")
            :format(descriptor.label, descriptor.text_key, flag_index, descriptor.threshold, slot + 1))
    save_histories()
    notify("Success", "Verified earned reward repaired: " .. descriptor.label, 6000)
    return true, descriptor.label .. " repaired and verified."
end

local function award_reward_snapshot()
    local cache = State.award_reward_cache
    if type(cache) ~= "table" then
        return { status="REFRESH_REQUIRED", slot=State.character_slot,
            character=State.character_label or "Unavailable", completed_sets=0,
            source_values={}, items={}, readable_sources=0, total_sources=#AWARD_SET_STAT_INDEXES }
    end
    local copy = {
        status=cache.status, slot=cache.slot, character=cache.character,
        error=cache.error, completed_sets=cache.completed_sets,
        readable_sources=cache.readable_sources, total_sources=cache.total_sources,
        refreshed_at=cache.refreshed_at, source_values={}, items={},
    }
    for i,item in ipairs(cache.source_values or {}) do
        copy.source_values[i] = { stat_index=item.stat_index,value=item.value,readable=item.readable,error=item.error }
    end
    for i,item in ipairs(cache.items or {}) do
        copy.items[i] = { threshold=item.threshold,packed_bool=item.packed_bool,text_key=item.text_key,
            label=item.label,eligible=item.eligible,unlocked=item.unlocked,available=item.available,error=item.error }
    end
    return copy
end


local function award_reward_repair_all_earned()
    local ok, detail = award_reward_refresh()
    local cache = State.award_reward_cache
    if not ok or type(cache) ~= "table" then return false, tostring(detail or "award prerequisites unavailable") end
    local slot = cache.slot
    local repaired = 0
    for _, item in ipairs(cache.items or {}) do
        if item.available and item.eligible and not item.unlocked then
            local wrote, write_detail = write_packed_bool_verified(item.packed_bool, true, slot)
            if not wrote then
                award_reward_refresh()
                return false, ("award reward repair-all stopped at %s: %s"):format(tostring(item.label), tostring(write_detail))
            end
            repaired = repaired + 1
        end
    end
    award_reward_refresh()
    if repaired > 0 then
        add_history("success", "Award Reward Recovery", ("Repaired %d already-earned outfit reward marker(s) for Character %d."):format(repaired, slot + 1))
        save_histories()
        notify("Success", ("Repaired %d earned award reward(s)."):format(repaired), 6000)
    end
    return true, repaired > 0 and ("Repaired " .. tostring(repaired) .. " earned reward marker(s).") or "All earned award reward markers were already present."
end

local function evaluate_derived_award_rule(descriptor, slot, cache)
    local rule = descriptor and descriptor.rule
    if type(rule) ~= "table" then return nil, nil, "derived award rule is unavailable" end
    cache = cache or { packed_bools={}, packed_ints={}, character_stats={} }
    cache.packed_bools, cache.packed_ints, cache.character_stats = cache.packed_bools or {}, cache.packed_ints or {}, cache.character_stats or {}

    local function cached_packed_bool(index)
        if cache.packed_bools[index] ~= nil then return cache.packed_bools[index], nil end
        local value, err = read_packed_bool(index, slot)
        if value ~= nil then cache.packed_bools[index] = value end
        return value, err
    end
    local function cached_packed_int(index)
        if cache.packed_ints[index] ~= nil then return cache.packed_ints[index], nil end
        local value, err = read_packed_int(index, slot)
        if value ~= nil then cache.packed_ints[index] = value end
        return value, err
    end
    local function cached_character_stat(index, data_type)
        local key = tostring(data_type or 0) .. ":" .. tostring(index)
        if cache.character_stats[key] ~= nil then return cache.character_stats[key], nil end
        local value, err = read_character_stat_index(slot, index, data_type or 0)
        if value ~= nil then cache.character_stats[key] = value end
        return value, err
    end

    if rule.kind == "all_packed_bools" or rule.kind == "any_packed_bools" then
        local count = 0
        for _, index in ipairs(rule.indexes or {}) do
            local value, err = cached_packed_bool(index)
            if value == nil then return nil, nil, err end
            if value then count = count + 1 end
        end
        local total = #(rule.indexes or {})
        local eligible
        if rule.kind == "all_packed_bools" then
            eligible = total > 0 and count == total
        else
            eligible = count > 0
        end
        return eligible, ("%d / %d prerequisite marker(s) present"):format(count, total)
    elseif rule.kind == "character_stat_min" then
        local value, err = cached_character_stat(rule.stat_index, rule.data_type or 0)
        if value == nil then return nil, nil, err end
        return value >= (tonumber(rule.minimum) or 0), ("character stat %d = %d (needs %d)"):format(rule.stat_index, value, tonumber(rule.minimum) or 0)
    elseif rule.kind == "packed_int_min" then
        local value, err = cached_packed_int(rule.packed_int)
        if value == nil then return nil, nil, err end
        return value >= (tonumber(rule.minimum) or 0), ("packed int %d = %d (needs %d)"):format(rule.packed_int, value, tonumber(rule.minimum) or 0)
    elseif rule.kind == "character_stat_bit" then
        local value, err = cached_character_stat(rule.stat_index, rule.data_type or 0)
        if value == nil then return nil, nil, err end
        local set = integer_bit_is_set(value, rule.bit)
        return set, ("character stat %d bit %d = %s"):format(rule.stat_index, rule.bit, set and "set" or "clear")
    elseif rule.kind == "character_stat_bit_pairs_all" then
        local value, err = cached_character_stat(rule.stat_index, rule.data_type or 0)
        if value == nil then return nil, nil, err end
        local complete = 0
        for _, pair in ipairs(rule.pairs or {}) do
            if integer_bit_is_set(value, pair[1]) or integer_bit_is_set(value, pair[2]) then complete = complete + 1 end
        end
        local total = #(rule.pairs or {})
        return total > 0 and complete == total, ("%d / %d source bit-pair group(s) satisfied"):format(complete, total)
    end
    return nil, nil, "unsupported derived award rule: " .. tostring(rule.kind)
end

local function derived_award_refresh()
    local slot, slot_err = detect_character_slot()
    local result = { status=slot ~= nil and "READY" or "UNAVAILABLE", slot=slot,
        character=slot ~= nil and ("Character " .. tostring(slot + 1)) or "Unavailable",
        error=slot_err, items={}, available_count=0, repairable_count=0, present_count=0,
        total_count=#RECOVERY_DERIVED_AWARD_MARKERS, refreshed_at=epoch() }
    if slot == nil then State.derived_award_cache = result; return false, slot_err end
    local source_cache = { packed_bools={}, packed_ints={}, character_stats={} }
    for _, descriptor in ipairs(RECOVERY_DERIVED_AWARD_MARKERS) do
        local unlocked, unlock_err = read_packed_bool(descriptor.packed_bool, slot)
        local eligible, detail, rule_err = evaluate_derived_award_rule(descriptor, slot, source_cache)
        local available = type(unlocked) == "boolean" and type(eligible) == "boolean"
        local item = { packed_bool=descriptor.packed_bool, label=descriptor.label, rule_kind=descriptor.rule.kind,
            unlocked=unlocked == true, eligible=eligible == true, available=available, detail=detail,
            error=available and nil or tostring(unlock_err or rule_err or "source prerequisite unavailable") }
        result.items[#result.items+1] = item
        if available then result.available_count=result.available_count+1 else result.status="PARTIAL" end
        if item.unlocked then result.present_count=result.present_count+1 end
        if available and item.eligible and not item.unlocked then result.repairable_count=result.repairable_count+1 end
    end
    if result.status == "PARTIAL" then result.error = "one or more derived marker prerequisites could not be validated" end
    State.derived_award_cache = result
    return true, result
end

local function derived_award_snapshot()
    local c=State.derived_award_cache
    if type(c)~="table" then return { status="REFRESH_REQUIRED",items={},available_count=0,repairable_count=0,present_count=0,total_count=#RECOVERY_DERIVED_AWARD_MARKERS } end
    local r={status=c.status,slot=c.slot,character=c.character,error=c.error,available_count=c.available_count,
        repairable_count=c.repairable_count,present_count=c.present_count,total_count=c.total_count,refreshed_at=c.refreshed_at,items={}}
    for i,item in ipairs(c.items or {}) do
        r.items[i]={packed_bool=item.packed_bool,label=item.label,rule_kind=item.rule_kind,unlocked=item.unlocked,
            eligible=item.eligible,available=item.available,detail=item.detail,error=item.error}
    end
    return r
end

local function derived_award_repair(flag_index)
    flag_index=tonumber(flag_index)
    if not flag_index or flag_index%1~=0 then return false,"derived award flag is invalid" end
    flag_index=math.floor(flag_index)
    local descriptor=RECOVERY_DERIVED_AWARD_BY_FLAG[flag_index]
    if not descriptor then return false,"derived award marker is outside CScript's source-backed repair catalog" end
    local slot,slot_err=detect_character_slot(); if slot==nil then return false,slot_err end
    local eligible, detail, err=evaluate_derived_award_rule(descriptor,slot)
    if type(eligible)~="boolean" then return false,"prerequisite validation failed: "..tostring(err) end
    if not eligible then return false,"Rockstar-derived prerequisite is not met: "..tostring(detail) end
    local before,before_err=read_packed_bool(flag_index,slot); if before==nil then return false,before_err end
    if before then derived_award_refresh(); return true,descriptor.label.." is already present; zero writes were performed." end
    local wrote,write_detail=write_packed_bool_verified(flag_index,true,slot)
    if not wrote then derived_award_refresh(); return false,tostring(write_detail) end
    derived_award_refresh()
    add_history("success","Derived Award Recovery",("Repaired %s (packed %d) after validating %s for Character %d."):format(descriptor.label,flag_index,tostring(detail),slot+1))
    save_histories(); notify("Success","Derived earned marker repaired: "..descriptor.label,6000)
    return true,descriptor.label.." repaired and verified."
end

local function derived_award_repair_all_earned()
    local ok,detail=derived_award_refresh(); local cache=State.derived_award_cache
    if not ok or type(cache)~="table" then return false,tostring(detail or "derived award prerequisites unavailable") end
    local slot=cache.slot; local repaired=0
    for _,item in ipairs(cache.items or {}) do
        if item.available and item.eligible and not item.unlocked then
            local wrote,write_detail=write_packed_bool_verified(item.packed_bool,true,slot)
            if not wrote then derived_award_refresh(); return false,("repair-all stopped at %s: %s"):format(item.label,tostring(write_detail)) end
            repaired=repaired+1
        end
    end
    derived_award_refresh()
    if repaired>0 then add_history("success","Derived Award Recovery",("Repaired %d already-earned derived marker(s) for Character %d."):format(repaired,slot+1)); save_histories(); notify("Success",("Repaired %d derived earned marker(s)."):format(repaired),6000) end
    return true,repaired>0 and ("Repaired "..repaired.." derived marker(s).") or "All earned derived markers were already present."
end

local function collectible_threshold(descriptor)
    if not descriptor.threshold_tunable_offset then
        return tonumber(descriptor.maximum), nil, descriptor.maximum and { kind="fixed", value=descriptor.maximum } or nil
    end
    local script_global = module_context and module_context.Raw and module_context.Raw.ScriptGlobal
    if script_global == nil and type(_G) == "table" then script_global = rawget(_G, "ScriptGlobal") end
    if not (script_global and type(script_global.GetInt) == "function") then
        return nil, "live collectible threshold could not be validated because ScriptGlobal.GetInt is unavailable"
    end
    local index = 262145 + math.floor(tonumber(descriptor.threshold_tunable_offset) or -999999)
    local ok, value = pcall(script_global.GetInt, index)
    value = ok and tonumber(value) or nil
    if value == nil or value % 1 ~= 0 or value < 1 or value > 1000 then
        return nil, "live collectible threshold is outside the expected range"
    end
    return math.floor(value), nil, { kind="tunable", index=index, default=descriptor.threshold_default }
end

local function collectible_reward_flags(descriptor)
    if type(descriptor.reward_flags) == "table" then return descriptor.reward_flags end
    if descriptor.reward_flag then return {descriptor.reward_flag} end
    return {}
end

local function collectible_refresh()
    local slot,slot_err=detect_character_slot()
    local result={status=slot~=nil and "READY" or "UNAVAILABLE",slot=slot,character=slot~=nil and ("Character "..(slot+1)) or "Unavailable",
        error=slot_err,items={},available_count=0,repairable_count=0,total_count=#RECOVERY_COLLECTIBLES,refreshed_at=epoch()}
    if slot==nil then State.collectible_cache=result; return false,slot_err end
    for _,descriptor in ipairs(RECOVERY_COLLECTIBLES) do
        local count,count_err=read_character_stat_index(slot,descriptor.count_stat_index,0)
        local maximum,threshold_err,threshold_meta=collectible_threshold(descriptor)
        local count_available=type(count)=="number" and type(maximum)=="number"
        local flags=collectible_reward_flags(descriptor)
        local reward_states={}
        local reward_available=true
        local reward_present=#flags>0
        local reward_err
        for _,flag in ipairs(flags) do
            local present,err=read_packed_bool(flag,slot)
            reward_states[#reward_states+1]={packed_bool=flag,present=present==true,available=type(present)=="boolean",error=err}
            if type(present)~="boolean" then reward_available=false; reward_err=reward_err or err end
            if present~=true then reward_present=false end
        end
        if #flags==0 then reward_present=false end
        local available=count_available and reward_available
        local complete=count_available and count>=maximum
        local repairable=available and #flags>0 and complete and reward_present~=true
        result.items[#result.items+1]={key=descriptor.key,label=descriptor.label,count=count,maximum=maximum,
            count_stat_index=descriptor.count_stat_index,reward_flag=descriptor.reward_flag,reward_flags=flags,reward_states=reward_states,reward_label=descriptor.reward_label,
            reward_present=reward_present==true,complete=complete==true,repairable=repairable==true,available=available,note=descriptor.note,threshold=threshold_meta,
            error=available and nil or tostring(count_err or threshold_err or reward_err or "collectible state unavailable")}
        if available then result.available_count=result.available_count+1 else result.status="PARTIAL" end
        if repairable then result.repairable_count=result.repairable_count+1 end
    end
    if result.status=="PARTIAL" then result.error="one or more collectible counters, thresholds, or reward flags could not be validated" end
    State.collectible_cache=result; return true,result
end

local function collectible_snapshot()
    local c=State.collectible_cache
    if type(c)~="table" then return {status="REFRESH_REQUIRED",items={},available_count=0,repairable_count=0,total_count=#RECOVERY_COLLECTIBLES} end
    local r={status=c.status,slot=c.slot,character=c.character,error=c.error,available_count=c.available_count,repairable_count=c.repairable_count,total_count=c.total_count,refreshed_at=c.refreshed_at,items={}}
    for i,item in ipairs(c.items or {}) do local x={} for k,v in pairs(item) do x[k]=v end r.items[i]=x end
    return r
end

local function collectible_reward_repair(key)
    local descriptor=RECOVERY_COLLECTIBLE_BY_KEY[tostring(key or "")]
    if not descriptor then return false,"collectible is outside CScript's curated catalog" end
    local flags=collectible_reward_flags(descriptor)
    if #flags==0 then return false,"this collectible has no isolated cosmetic reward marker approved for repair" end
    local slot,slot_err=detect_character_slot(); if slot==nil then return false,slot_err end
    local count,count_err=read_character_stat_index(slot,descriptor.count_stat_index,0)
    if type(count)~="number" then return false,"collectible count could not be validated: "..tostring(count_err) end
    local maximum,threshold_err=collectible_threshold(descriptor)
    if type(maximum)~="number" then return false,"collectible completion threshold could not be validated: "..tostring(threshold_err) end
    if count<maximum then return false,("collection is incomplete: %d / %d"):format(count,maximum) end
    local missing={}
    for _,flag in ipairs(flags) do
        local before,before_err=read_packed_bool(flag,slot); if before==nil then return false,before_err end
        if not before then missing[#missing+1]=flag end
    end
    if #missing==0 then collectible_refresh(); return true,tostring(descriptor.reward_label).." marker already present; zero writes were performed." end
    for _,flag in ipairs(missing) do
        local wrote,write_detail=write_packed_bool_verified(flag,true,slot)
        if not wrote then collectible_refresh(); return false,tostring(write_detail) end
    end
    collectible_refresh()
    add_history("success","Collectible Reward Recovery",("Repaired %s after verifying %s %d/%d for Character %d. %d isolated wardrobe marker(s) restored; no completion-cash transaction was replayed."):format(tostring(descriptor.reward_label),descriptor.label,count,maximum,slot+1,#missing))
    save_histories(); notify("Success","Earned collectible reward repaired: "..tostring(descriptor.reward_label),6000)
    return true,tostring(descriptor.reward_label).." repaired and verified."
end

local function collectible_repair_all_earned()
    local ok,detail=collectible_refresh(); local cache=State.collectible_cache
    if not ok or type(cache)~="table" then return false,tostring(detail or "collectible prerequisites unavailable") end
    local slot=cache.slot; local repaired_rewards=0; local repaired_markers=0
    for _,item in ipairs(cache.items or {}) do
        if item.available and item.repairable and type(item.reward_flags)=="table" then
            local changed=false
            for _,state in ipairs(item.reward_states or {}) do
                if state.available and not state.present then
                    local wrote,write_detail=write_packed_bool_verified(state.packed_bool,true,slot)
                    if not wrote then collectible_refresh(); return false,("collectible repair-all stopped at %s: %s"):format(item.label,tostring(write_detail)) end
                    repaired_markers=repaired_markers+1; changed=true
                end
            end
            if changed then repaired_rewards=repaired_rewards+1 end
        end
    end
    collectible_refresh()
    if repaired_rewards>0 then add_history("success","Collectible Reward Recovery",("Repaired %d earned collectible reward(s) / %d isolated wardrobe marker(s) for Character %d; no completion-cash transactions replayed."):format(repaired_rewards,repaired_markers,slot+1)); save_histories(); notify("Success",("Repaired %d earned collectible reward(s)."):format(repaired_rewards),6000) end
    return true,repaired_rewards>0 and ("Repaired "..repaired_rewards.." collectible reward(s) across "..repaired_markers.." marker(s).") or "All earned collectible reward markers were already present."
end

local function recovery_repair_all_supported_rewards()
    local repaired = {}
    for _, step in ipairs({
        { "Award-set rewards", award_reward_repair_all_earned },
        { "Derived award markers", derived_award_repair_all_earned },
        { "Collectible rewards", collectible_repair_all_earned },
    }) do
        local ok, detail = step[2]()
        if not ok then return false, step[1] .. " failed: " .. tostring(detail) end
        repaired[#repaired + 1] = step[1] .. ": " .. tostring(detail)
    end
    return true, table.concat(repaired, " | ")
end

local function recovery_complete_all_supported_award_sets()
    local slot, slot_err = detect_character_slot()
    if slot == nil then return false, slot_err end
    local generation = tonumber(State.generation) or 0
    local before, changed = {}, {}
    for _, stat_index in ipairs(AWARD_SET_STAT_INDEXES) do
        local value, err = read_character_stat_index(slot, stat_index, 0)
        if value == nil then return false, "award-set pre-read failed: " .. tostring(err) end
        before[stat_index] = value
    end
    local function identity_stable()
        local current_slot = detect_character_slot()
        return current_slot == slot and (tonumber(State.generation) or 0) == generation
    end
    local function rollback(reason)
        local failures = {}
        for index = #changed, 1, -1 do
            local item = changed[index]
            local ok, detail = write_character_stat_index_verified(
                slot, item.stat_index, item.before, -1)
            if not ok then failures[#failures + 1] = tostring(detail) end
        end
        award_reward_refresh(); career_progress_refresh()
        if #failures > 0 then
            return false, tostring(reason) .. "; rollback also failed: " .. table.concat(failures, "; ")
        end
        return false, tostring(reason) .. "; every changed award bitset was rolled back"
    end

    for _, stat_index in ipairs(AWARD_SET_STAT_INDEXES) do
        if before[stat_index] ~= -1 then
            if not identity_stable() then return rollback("character/session identity changed before award write") end
            local ok, detail = write_character_stat_index_verified(slot, stat_index, -1, before[stat_index])
            if not ok then return rollback("award-set write failed at " .. tostring(stat_index) .. ": " .. tostring(detail)) end
            changed[#changed + 1] = { stat_index=stat_index, before=before[stat_index] }
        end
    end
    if not identity_stable() then return rollback("character/session identity changed before final verification") end
    for _, stat_index in ipairs(AWARD_SET_STAT_INDEXES) do
        local verify, verify_err = read_character_stat_index(slot, stat_index, 0)
        if verify ~= -1 then
            return rollback(("award-set final read-back failed at %d: %s")
                :format(stat_index, tostring(verify_err or verify)))
        end
    end
    State.award_completion = {
        status="COMPLETE", slot=slot, changed=#changed, completed_at=epoch(),
        stat_indexes={ table.unpack(AWARD_SET_STAT_INDEXES) },
    }
    award_reward_refresh(); derived_award_refresh(); career_progress_refresh()
    local rewards_ok, rewards_detail = recovery_repair_all_supported_rewards()
    add_history("success", "Award Set Recovery",
        ("Completed and verified all 40 source-backed award sets for Character %d across five bitsets; %d bitsets changed. %s")
            :format(slot + 1, #changed, tostring(rewards_detail)))
    save_histories()
    notify(rewards_ok and "Success" or "Warning",
        rewards_ok and "All supported award sets completed and reward markers repaired."
            or "Award sets completed, but one reward-marker repair needs another pass.", 7500)
    if not rewards_ok then
        return true, "Award sets completed and verified; reward-marker follow-up: " .. tostring(rewards_detail)
    end
    return true, ("Completed all 40 supported award sets; %d source bitset(s) changed. %s")
        :format(#changed, tostring(rewards_detail))
end

local function serialize_account_snapshot(snapshot)
    local lines = {
        ACCOUNT_SNAPSHOT_HEADER,
        "version|" .. encode(snapshot.version), "time|" .. encode(snapshot.time),
        "slot|" .. encode(snapshot.slot), "cash|" .. encode(snapshot.cash or ""),
        "bank|" .. encode(snapshot.bank or ""),
    }
    for _, item in ipairs(snapshot.skills or {}) do
        lines[#lines + 1] = table.concat({ "skill", encode(item.key), encode(item.stat), encode(item.value),
            encode(item.minimum), encode(item.maximum), encode(item.available and 1 or 0) }, "|")
    end
    for _, item in ipairs(snapshot.achievements or {}) do
        lines[#lines + 1] = table.concat({ "achievement", encode(item.id), encode(item.label), encode(item.group),
            encode(item.passed and 1 or 0), encode(item.progress or ""), encode(item.available and 1 or 0) }, "|")
    end
    return table.concat(lines, "\n")
end

local function parse_account_snapshot(content, path)
    content = canonical_text(content)
    if type(content) ~= "string" or content:match("^([^\n]+)") ~= ACCOUNT_SNAPSHOT_HEADER then
        return nil, "account snapshot header is invalid"
    end
    local snapshot, first = { skills={}, achievements={}, path=path }, true
    for line in content:gmatch("[^\n]+") do
        if first then first = false else
            local item = fields(line)
            if item[1] == "version" then snapshot.version = item[2]
            elseif item[1] == "time" then snapshot.time = tonumber(item[2])
            elseif item[1] == "slot" then snapshot.slot = tonumber(item[2])
            elseif item[1] == "cash" then snapshot.cash = tonumber(item[2])
            elseif item[1] == "bank" then snapshot.bank = tonumber(item[2])
            elseif item[1] == "skill" then
                local key, value, minimum, maximum, available = item[2], tonumber(item[4]), tonumber(item[5]), tonumber(item[6]), tonumber(item[7]) == 1
                local descriptor = RECOVERY_SKILL_BY_KEY[key]
                if descriptor and value and minimum == descriptor.minimum and maximum == descriptor.maximum
                    and value >= minimum and value <= maximum then
                    snapshot.skills[#snapshot.skills + 1] = { key=key, stat=item[3], value=value,
                        minimum=minimum, maximum=maximum, available=available }
                end
            elseif item[1] == "achievement" then
                local id = tonumber(item[2])
                if id then snapshot.achievements[#snapshot.achievements + 1] = {
                    id=id,label=item[3],group=item[4],passed=tonumber(item[5])==1,
                    progress=tonumber(item[6]),available=tonumber(item[7])==1,
                } end
            end
        end
    end
    if snapshot.slot ~= 0 and snapshot.slot ~= 1 then return nil, "account snapshot character slot is invalid" end
    if not snapshot.time or #snapshot.skills == 0 then return nil, "account snapshot is incomplete" end
    return snapshot
end

local function account_snapshot_create()
    local slot, slot_err = detect_character_slot()
    if slot == nil then return false, slot_err end
    local skills_ok = recovery_refresh()
    if not skills_ok then return false, "curated skill validation failed; account snapshot was not written" end
    achievement_refresh() -- Read-only and optional; skills remain the restore authority.
    local skills = recovery_snapshot()
    local achievements = achievement_snapshot()
    local cash, bank = read_money(slot)
    local snapshot = {
        version=module_context and module_context.LoaderVersion or "unknown", time=epoch(), slot=slot,
        cash=cash, bank=bank, skills={}, achievements={},
    }
    for _, item in ipairs(skills.skills or {}) do
        if item.available and type(item.value) == "number" then snapshot.skills[#snapshot.skills+1] = item end
    end
    if #snapshot.skills == 0 then return false, "no validated curated skills are available for snapshot" end
    for _, item in ipairs(achievements.items or {}) do snapshot.achievements[#snapshot.achievements+1] = item end
    local paths = State.paths or active_paths()
    local root = paths and (paths.account_snapshots or (paths.root and (paths.root .. "\\AccountSnapshots")))
    if not root then return false, "account snapshot storage is unavailable" end
    local dir_ok, dir_err = ensure_directory(root)
    if not dir_ok then return false, "account snapshot directory failed: " .. tostring(dir_err) end
    local path = root .. "\\" .. timestamp_id() .. "-character-" .. tostring(slot + 1) .. ".snapshot"
    local ok, err = write_file(path, serialize_account_snapshot(snapshot))
    if not ok then return false, "account snapshot write failed: " .. tostring(err) end
    local reread, read_err = read_file(path)
    local verified, parse_err = parse_account_snapshot(reread, path)
    if not verified then return false, "account snapshot verification failed: " .. tostring(read_err or parse_err) end
    State.account_last_snapshot = verified
    add_history("success", "Account Snapshot", ("Saved Character %d snapshot: skills=%d achievements=%d path=%s")
        :format(slot + 1, #verified.skills, #verified.achievements, path))
    save_histories()
    notify("Success", "Account snapshot saved and verified.", 5000)
    return true, verified
end

local function account_snapshot_load_latest()
    local paths = State.paths or active_paths()
    local root = paths and (paths.account_snapshots or (paths.root and (paths.root .. "\\AccountSnapshots")))
    if not root then return false, "account snapshot storage is unavailable" end
    local files = file_mgr()
    if not files or type(files.FindFiles) ~= "function" then return false, "FileMgr.FindFiles is unavailable" end
    local ok, found = pcall(files.FindFiles, root, ".snapshot", false)
    if not ok or type(found) ~= "table" then return false, "account snapshot listing failed" end
    local candidates = {}
    for _, raw in pairs(found) do
        local path = tostring(raw or "")
        if path ~= "" then
            if not path:find("[\\/]", 1) then path = root .. "\\" .. path end
            candidates[#candidates + 1] = path
        end
    end
    table.sort(candidates, function(a,b) return a > b end)
    for _, path in ipairs(candidates) do
        local content = read_file(path)
        local snapshot = parse_account_snapshot(content, path)
        if snapshot then
            State.account_last_snapshot = snapshot
            return true, snapshot
        end
    end
    return false, "no verified account snapshot was found"
end

local function account_snapshot_restore_skills()
    local snapshot = State.account_last_snapshot
    if not snapshot then
        local loaded, loaded_or_err = account_snapshot_load_latest()
        if not loaded then return false, loaded_or_err end
        snapshot = loaded_or_err
    end
    local slot, slot_err = detect_character_slot()
    if slot == nil then return false, slot_err end
    if tonumber(snapshot.slot) ~= slot then
        return false, ("snapshot belongs to Character %d; current character is %d"):format((tonumber(snapshot.slot) or 0)+1, slot+1)
    end
    local values = {}
    for _, item in ipairs(snapshot.skills or {}) do
        local descriptor = RECOVERY_SKILL_BY_KEY[item.key]
        if descriptor and item.available and type(item.value) == "number"
            and item.value >= descriptor.minimum and item.value <= descriptor.maximum then
            values[item.key] = math.floor(item.value)
        end
    end
    if next(values) == nil then return false, "account snapshot contains no restorable curated skill values" end
    return recovery_apply(values, "Restore Account Snapshot Skills", "recovery:account_snapshot_restore_skills")
end

local function account_snapshot_state()
    local snapshot = State.account_last_snapshot
    return {
        available = type(snapshot) == "table", path = snapshot and snapshot.path or nil,
        time = snapshot and snapshot.time or nil, slot = snapshot and snapshot.slot or nil,
        skill_count = snapshot and #(snapshot.skills or {}) or 0,
        achievement_count = snapshot and #(snapshot.achievements or {}) or 0,
        cash = snapshot and snapshot.cash or nil, bank = snapshot and snapshot.bank or nil,
    }
end

recovery_snapshot = function()
    local cache = State.recovery_cache
    if type(cache) ~= "table" then
        return {
            status = "REFRESH_REQUIRED", slot = State.character_slot,
            character = State.character_label or "Unavailable", skills = {},
            available_count = 0, total_count = #RECOVERY_SKILLS,
            last_snapshot = State.recovery_last_snapshot,
        }
    end
    local copy = {
        status = cache.status, slot = cache.slot, character = cache.character, error = cache.error,
        available_count = cache.available_count, total_count = cache.total_count,
        refreshed_at = cache.refreshed_at, skills = {}, last_snapshot = State.recovery_last_snapshot,
    }
    for i, item in ipairs(cache.skills or {}) do
        copy.skills[i] = {
            key=item.key,label=item.label,stat=item.stat,value=item.value,minimum=item.minimum,maximum=item.maximum,
            available=item.available,error=item.error,
        }
    end
    return copy
end

read_money = function(slot)
    local first_cash,first_bank
    for sample=1,2 do
        local cash_ok,cash=native_try("int",NETWORK_GET_VC_WALLET_BALANCE,slot)
        local bank_ok,bank=native_try("int",NETWORK_GET_VC_BANK_BALANCE)
        if not cash_ok or not bank_ok or not Module.Money.ValidBalance(cash) or not Module.Money.ValidBalance(bank) then
            return nil,nil,"Waiting for valid cash and bank balances"
        end
        if sample==1 then first_cash,first_bank=cash,bank
        elseif first_cash~=cash or first_bank~=bank then return nil,nil,"Balances are updating" end
    end
    return first_cash,first_bank
end

local function invalidate_dependents(reason)
    local automation=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
    if automation and type(automation.Stop)=="function"then pcall(automation.Stop,reason)end
    local heists = module_context and module_context.CScript and module_context.CScript.Heists
    local businesses = module_context and module_context.CScript and module_context.CScript.Businesses
    if heists and type(heists.Invalidate) == "function" then pcall(heists.Invalidate, reason) end
    if businesses and type(businesses.Invalidate) == "function" then pcall(businesses.Invalidate, reason) end
end

local function status_for(amount, limit)
    amount, limit = math.max(0, tonumber(amount) or 0), math.max(1, tonumber(limit) or 1)
    local percentage = amount / limit * 100
    if percentage >= 100 then return "Limit Reached", "limit", 4, percentage end
    if percentage >= 85 then return "Caution", "caution", 3, percentage end
    if percentage >= 67 then return "Elevated", "elevated", 2, percentage end
    return "Normal", "normal", 1, percentage
end

local function activity_window(amount, limit, event_count)
    local label, key, rank, percentage = status_for(amount, limit)
    return {
        amount = amount, limit = limit, percentage = percentage,
        status = label, status_key = key, status_rank = rank, event_count = event_count,
    }
end

local function calculate_earnings_summary(current, slot)
    current, slot = tonumber(current) or epoch(), tonumber(slot)
    local last24, last7, count24, count7 = 0, 0, 0, 0
    local sources = { Heists = 0, Businesses = 0, Missions = 0, Safes = 0, ["Other / Unknown"] = 0 }
    for _, item in ipairs(State.earnings or {}) do
        local amount, timestamp = math.max(0, tonumber(item.amount) or 0), tonumber(item.time) or 0
        if item.confidence == "verified" and item.character_slot == slot and timestamp <= current then
            if timestamp > current - DAY_SECONDS then
                last24, count24 = last24 + amount, count24 + 1
            end
            if timestamp > current - WEEK_SECONDS then
                last7, count7 = last7 + amount, count7 + 1
                local bucket = source_bucket(item.source)
                if bucket == "Unknown" then bucket = "Other / Unknown" end
                sources[bucket] = (sources[bucket] or 0) + amount
            end
        end
    end
    local result = {
        last24 = last24, last7 = last7, last24_count = count24, last7_count = count7,
        lifetime = slot ~= nil and math.max(0, tonumber(State.lifetime_by_slot[slot]) or 0) or 0,
        sources = sources, character_slot = slot, calculated_at = current,
    }
    result.daily = activity_window(last24, State.daily_caution, count24)
    result.weekly = activity_window(last7, State.weekly_caution, count7)
    return result
end

local function money_label(value)
    value = math.max(0, math.floor(tonumber(value) or 0))
    local text = tostring(value)
    repeat
        local changed
        text, changed = text:gsub("^(-?%d+)(%d%d%d)", "%1,%2")
    until changed == 0
    return "$" .. text
end

local function sync_threshold_state(summary, allow_notifications)
    local slot = summary and summary.character_slot
    if slot ~= 0 and slot ~= 1 then return end
    State.threshold_levels[slot] = State.threshold_levels[slot] or {}
    local levels = State.threshold_levels[slot]
    for _, spec in ipairs({
        { key = "daily", label = "24-hour" }, { key = "weekly", label = "7-day" },
    }) do
        local activity = summary[spec.key]
        local previous = tonumber(levels[spec.key])
        if previous and allow_notifications and activity.status_rank > previous then
            if activity.status_rank >= 4 then
                notify("Error", ("%s earnings limit reached. %s / %s"):format(
                    spec.label, money_label(activity.amount), money_label(activity.limit)), 7000)
            elseif activity.status_rank >= 3 then
                notify("Warning", ("%s earnings approaching limit. %s / %s"):format(
                    spec.label, money_label(activity.amount), money_label(activity.limit)), 6500)
            end
        end
        levels[spec.key] = activity.status_rank
    end
end

local function update_cached_summary(current, allow_notifications)
    local summary = calculate_earnings_summary(current, State.character_slot)
    sync_threshold_state(summary, allow_notifications == true)
    State.earnings_summary = summary
    local ordered,recent={},{}
    for index,item in ipairs(State.earnings or {}) do
        if item.confidence=="verified" and item.character_slot==State.character_slot
            and type(item.time)=="number" and item.time<=current then
            ordered[#ordered+1]={item=item,index=index}
        end
    end
    table.sort(ordered,function(left,right)
        if left.item.time~=right.item.time then return left.item.time>right.item.time end
        return left.index>right.index
    end)
    for index=1,math.min(20,#ordered) do recent[index]=ordered[index].item end
    State.recent_earnings = recent
    State.hud_snapshot = {
        enabled = State.hud_enabled == true, character_slot = State.character_slot,
        last24 = summary.last24, last7 = summary.last7,
        daily_limit = summary.daily.limit, weekly_limit = summary.weekly.limit,
        daily_percentage = summary.daily.percentage, weekly_percentage = summary.weekly.percentage,
        daily_status = summary.daily.status, weekly_status = summary.weekly.status,
    }
    return summary
end

local function add_earning(source, amount, detail, metadata)
    if State.account_verified ~= true or not State.account_id then
        return false, "earnings tracking is waiting for the active Rockstar account"
    end
    if State.persistence_loaded ~= true or State.persistence_authoritative ~= true then
        return false, "earnings tracking is waiting for persistent history"
    end
    metadata = type(metadata) == "table" and metadata or {}
    amount = math.floor(tonumber(amount) or 0)
    local slot = metadata.character_slot
    if slot == nil then slot = State.character_slot end
    if amount <= 0 then return false, "earning amount must be positive" end
    if slot ~= 0 and slot ~= 1 then return false, "current character slot is unavailable" end
    local timestamp = math.floor(tonumber(metadata.timestamp) or epoch())
    if timestamp <= 0 then return false, "earning timestamp is invalid" end
    local event = {
        time = timestamp, amount = amount, source = clean(source or "Unknown", 80), confidence = "verified",
        cash_delta = math.floor(tonumber(metadata.cash_delta) or 0),
        bank_delta = math.floor(tonumber(metadata.bank_delta) or 0),
        character_slot = slot, session_id = clean(metadata.session_id or State.tracking_session_id, 80),
        detail = clean(detail or "Verified account balance increase", 180),
        balance_before = metadata.balance_before,
    }
    if Module.Journal and type(Module.Journal.StampEvent)=="function" then Module.Journal.StampEvent(event) end
    State.earnings[#State.earnings + 1] = event
    State.lifetime_by_slot[slot] = math.max(0, tonumber(State.lifetime_by_slot[slot]) or 0) + amount
    State.verified_events_since_start = (tonumber(State.verified_events_since_start) or 0) + 1
    State.last_verified_delta, State.last_event_timestamp = amount, timestamp
    Module.Settlement.ResolvePending()
    if Module.Income and Module.Income.Track then Module.Income.Track(event,metadata.observation) end
    prune_earnings(epoch())
    Dirty.Earnings()
    update_cached_summary(epoch(), slot == State.character_slot)
    local committed, commit_err = commit_earnings("verified-earning", event)
    if not committed then
        notify("Error", "Verified earning is in memory, but its local journal commit failed. Check Economy diagnostics.", 7500)
        return false, commit_err
    end
    return true, event
end

-- Correlate one already-recorded balance event; never manufacture another earning.
function Module.BeginEarningAttribution()
    if State.account_verified ~= true or State.persistence_authoritative ~= true
        or State.persistence_loaded ~= true or not State.account_id
        or (State.character_slot ~= 0 and State.character_slot ~= 1) then return nil end
    return {account=State.account_id,generation=State.generation,slot=State.character_slot,
        session=State.tracking_session_id,count=State.verified_events_since_start or 0,started_ms=now_ms()}
end

function Module.AttributeEarning(anchor, source, amount, detail)
    if type(anchor) ~= "table" or anchor.used then return false end
    local current=Module.BeginEarningAttribution()
    if not current or current.account~=anchor.account or current.generation~=anchor.generation
        or current.slot~=anchor.slot or current.session~=anchor.session
        or current.started_ms<anchor.started_ms or current.started_ms-anchor.started_ms>60000
        or current.count~=anchor.count+1 then return false end
    local event=State.earnings[#State.earnings]
    if not event or (event.source~="Unknown" and not (event._income_generic and source_bucket(event.source)==source_bucket(source))) or event.confidence~="verified"
        or event.character_slot~=anchor.slot or event.session_id~=anchor.session
        or event.amount~=amount or amount<=0 then return false end
    event.source=clean(source or "Unknown",80)
    event.detail=clean(detail or "Source correlated with observed balance increase",180)
    anchor.used=true;event._income_generic=nil
    if Module.Income then Module.Income.Claim(event) end
    Dirty.Earnings()
    update_cached_summary(epoch(),false)
    return true
end

-- Result evidence is supplied by a source-specific scheduler observer, never by
-- the renderer or by a payout-size heuristic. Only an existing balance delta is
-- relabelled. This separate lease can survive a normal mission/session exit;
-- the older business attribution API keeps its original strict scope contract.
Module.Settlement = { pending = {} }

function Module.Settlement.Current(anchor)
    return type(anchor)=="table" and not anchor.used and not anchor.rejected
        and State.account_verified==true and State.persistence_authoritative==true
        and State.persistence_loaded==true and State.account_id==anchor.account
        and State.attribution_epoch==anchor.scope
        and (State.character_slot==nil or State.character_slot==anchor.slot)
        and now_ms()>=anchor.started_ms and now_ms()-anchor.started_ms<=180000
end

function Module.Settlement.Begin(source, identity)
    local anchor=Module.BeginEarningAttribution()
    if not anchor or not State.baseline_valid or type(identity)~="string" or identity==""
        or (source~="Heists" and source~="Businesses" and source~="Missions" and source~="Safes") then return nil end
    anchor.source,anchor.identity=source,clean(identity,180)
    anchor.scope,anchor.balance_before=State.attribution_epoch,State.baseline_total
    return anchor
end

function Module.Settlement.Resolve(anchor)
    if not Module.Settlement.Current(anchor) then return false end
    local count=State.verified_events_since_start or 0
    if count==anchor.count then return nil end -- wait for the slower balance poll
    local event=State.earnings[#State.earnings]
    if count~=anchor.count+1 or not event or (event.source~="Unknown" and not (event._income_generic and event.source==anchor.source))
        or event.confidence~="verified" or event.character_slot~=anchor.slot
        or event.amount~=anchor.amount or event.balance_before~=anchor.balance_before then
        anchor.rejected=true;return false
    end
    event.source,event.detail=anchor.source,anchor.detail
    event._income_generic=nil
    if Module.Income then Module.Income.Claim(event) end
    anchor.used=true
    Dirty.Earnings()
    update_cached_summary(epoch(),false)
    return true,event
end

function Module.Settlement.ResolvePending()
    local retained={}
    for _,anchor in ipairs(Module.Settlement.pending) do
        if Module.Settlement.Resolve(anchor)==nil then retained[#retained+1]=anchor end
    end
    Module.Settlement.pending=retained
end

function Module.Settlement.Confirm(anchor, amount, before, after, detail)
    if not Module.Settlement.Current(anchor) or anchor.confirmed then return false end
    if type(amount)~="number" or amount~=amount or amount<=0 or amount%1~=0
        or type(before)~="number" or type(after)~="number" or before~=anchor.balance_before
        or after-before~=amount then return false end
    anchor.amount,anchor.detail=amount,clean(detail or (anchor.identity.." result and balance matched"),180)
    anchor.confirmed=true
    local resolved,event=Module.Settlement.Resolve(anchor)
    if resolved==true then return commit_earnings("source-attribution",event) end
    if resolved==false or #Module.Settlement.pending>=16 then return false end
    Module.Settlement.pending[#Module.Settlement.pending+1]=anchor
    return true -- evidence accepted; no additional earning is created
end

