function Module.Profile.resolve_stat_name(slot,name)
    if type(slot)~="number"or slot%1~=0 or(slot~=0 and slot~=1)
        or type(name)~="string"or #name>80 then return nil,"Invalid character/stat."end
    if name:match("^MPX_[A-Z0-9_]+$")then
        return "MP"..tostring(slot)..name:sub(4)
    elseif name:match("^MPPLY_[A-Z0-9_]+$")then
        return name
    end
    return nil,"Only MPX_ (character) and MPPLY_ (account) stats are supported."
end
function Module.Profile.career_alias(key)
    local aliases={
        career_MPPLY_KILLS_PLAYERS="player_kills",
        career_MPPLY_DEATHS_PLAYER="player_deaths",
        career_MPPLY_DEATHS_PLAYER_SUICIDE="player_suicides",
        ["custom_stat:MPPLY_KILLS_PLAYERS"]="player_kills",
        ["custom_stat:MPPLY_DEATHS_PLAYER"]="player_deaths",
        ["custom_stat:MPPLY_DEATHS_PLAYER_SUICIDE"]="player_suicides"
    }
    return aliases[key]
end

function Module.Profile.finite(value)
    return type(value)=="number" and value==value and value~=math.huge and value~=-math.huge
end
function Module.Profile.float32(value)
    if string.pack and string.unpack then return (string.unpack("f",string.pack("f",value))) end
    return value
end
function Module.Profile.signed32(value)
    return ((value+2147483648)%4294967296)-2147483648
end
function Module.Profile.round(value)
    return value<0 and math.ceil(value-0.5) or math.floor(value+0.5)
end
function Module.Profile.fields()
    return module_context and module_context.CScript and module_context.CScript.AccountFields
end
function Module.Profile.valid_value(value,kind)
    if kind=="date" then
        local fields=Module.Profile.fields()
        return fields and type(fields.ValidDate)=="function" and fields.ValidDate(value)==true or false
    end
    return Module.Profile.finite(value)
end
function Module.Profile.parse(key, raw)
    if key=="creation_date" then
        local fields=Module.Profile.fields()
        if not fields or type(fields.ParseDate)~="function" then return nil,"Date editor unavailable." end
        return fields.ParseDate(raw)
    end
    local range = Module.Profile.RANGES[key]
    if Module.Profile.CAREER_BY_KEY[key]then
        range={0,2147483647,true}
    elseif type(key)=="string"and key:sub(1,12)=="custom_stat:"then
        local stat=key:sub(13)
        if not Module.Profile.resolve_stat_name(0,stat)then
            return nil,"Invalid custom stat name. Use MPX_ or MPPLY_."
        end
        range={-2147483648,2147483647,true}
    end
    if not range then return nil, "This field cannot be edited." end
    local text = tostring(raw or ""):match("^%s*(.-)%s*$")
    if type(raw)~="number" and not text:match("^[+-]?%d+%.?%d*$") and not text:match("^[+-]?%.%d+$")
        and not text:match("^[+-]?%d+%.?%d*[eE][+-]?%d+$") then
        return nil, "Enter a signed number using digits and a decimal point."
    end
    local value = tonumber(text)
    if key=="kd_ratio" then
        -- Typed overflow is still a valid numeric request: saturate it before
        -- planning signed counters. Explicit non-finite API values stay invalid.
        if value==nil or value~=value or type(raw)=="number" and not Module.Profile.finite(value) then
            return nil, "Enter a valid number."
        end
        return math.max(range[1],math.min(range[2],value))
    end
    if not Module.Profile.finite(value) or value < range[1] or value > range[2] then
        return nil, ("Enter a value from %s to %s."):format(range[1], range[2])
    end
    if range[3] and value % 1 ~= 0 then return nil, "Enter a whole number." end
    return value
end
function Module.Profile.time_raw(value, minutes)
    -- Lua's 64-bit number intermediate avoids integer multiplication overflow.
    local raw=minutes and Module.Profile.round(value*60000.0) or value
    if raw<Module.Profile.SIGNED_STAT_MIN or raw>Module.Profile.SIGNED_STAT_MAX then
        return nil,"This minute value cannot fit the game's signed stat transport. Enter a smaller duration or edit Raw Stat."
    end
    return raw
end

function Module.Profile.scope(expected)
    local slot, err = detect_character_slot()
    if slot == nil then return nil, err end
    local account = select(1, resolve_local_account_identity())
    if not account or account ~= State.account_id then return nil, "The active account changed. Refresh the profile." end
    local gta=module_context and module_context.Raw and module_context.Raw.GTA
    local id_ok,id=false,nil
    if gta and type(gta.GetLocalPlayerId)=="function" then id_ok,id=pcall(gta.GetLocalPlayerId) end
    local scope = {slot=slot, account=account, generation=tonumber(State.generation) or 0, player=id_ok and id or nil}
    if expected and (scope.slot ~= expected.slot or scope.account ~= expected.account or scope.generation ~= expected.generation or expected.player~=nil and scope.player~=expected.player) then
        return nil, "The character or session changed. Refresh the profile."
    end
    return scope
end

function Module.Profile.player_globals()
    local raw = module_context and module_context.Raw or {}
    local globals, gta, memory = raw.ScriptGlobal, raw.GTA, raw.Memory
    if not (globals and type(globals.AreValid)=="function" and type(globals.GetInt)=="function"
        and type(globals.GetFloat)=="function" and type(globals.SetFloat)=="function"
        and gta and type(gta.GetLocalPlayerId)=="function" and memory and type(memory.GetBaseAddress)=="function") then
        return nil, "Profile editing is unavailable in this session."
    end
    local version_ok, version = native_try("string", 0xFCA9373EF340AC0A)
    local image_ok, image = pcall(memory.GetBaseAddress, "GTA5_Enhanced.exe")
    local valid_ok, valid = pcall(globals.AreValid)
    local id_ok, id = pcall(gta.GetLocalPlayerId)
    local array_ok, count = pcall(globals.GetInt, 2658296)
    local freemode = stat_hash("freemode")
    local threads_ok, threads = native_try("int", 0x2C83A9DA6BFFC4F9, freemode)
    if not version_ok or version ~= "1.73" or not image_ok or not tonumber(image) or image <= 0
        or not valid_ok or valid ~= true or not id_ok or type(id) ~= "number" or id % 1 ~= 0 or id < 0 or id > 31
        or not array_ok or count ~= 32 or not threads_ok or threads ~= 1 then
        return nil, "This edit needs a supported GTA Online freemode session."
    end
    return {globals=globals, player=id}
end

function Module.Profile.mental_context(before)
    local context,err=Module.Profile.player_globals()
    if not context then return nil,err end
    local globals,id=context.globals,context.player
    local index = 2658296 + 1 + id*468 + 272
    local read_ok, live = pcall(globals.GetFloat, index)
    if not read_ok or not Module.Profile.finite(live) then
        return nil, "The current Mental State could not be read."
    end
    -- Capture the persistent stat and display cache independently so this
    -- transaction can reconcile them. Validate build, array, slot and domain.
    if before~=nil and not Module.Profile.finite(before) then
        return nil,"The saved Mental State could not be read."
    end
    return {globals=globals, index=index, value=live, player=id}
end

function Module.Profile.refresh()
    local slot, slot_err = detect_character_slot()
    local cache={status=slot~=nil and "READY" or "UNAVAILABLE", slot=slot, error=slot_err, items={},
        generation=tonumber(State.generation) or 0, account=State.account_id,
        revision=(State.profile_revision or 0)+1}
    State.profile_revision=cache.revision
    if slot == nil then State.profile_stats=cache; return cache end
    local function add(key,label,value,kind,minimum,maximum,step,note)
        cache.items[#cache.items+1]={key=key,label=label,value=value,available=value~=nil,kind=kind,
            minimum=minimum,maximum=maximum,step=step,note=note}
    end
    local fields=Module.Profile.fields()
    if fields then
        local rank,rank_err=read_stat(qualify_stat(slot,"CHAR_RANK_FM"))
        local xp,xp_err=read_stat(qualify_stat(slot,"CHAR_XP_FM"))
        add("rank","Rank",rank,"int",1,8000,1,rank_err)
        add("rp","RP",xp,"int",0,1787576850,1,xp_err)
        local date,date_err=fields.ReadDate(slot)
        add("creation_date","Created",date and date:sub(1,10) or nil,"date",nil,nil,nil,date_err)
    end
    local mental, mental_err=Module.Profile.read_character_float(slot,133,1)
    local mental_context, context_err=Module.Profile.mental_context(mental)
    add("mental_state","Mental State",mental,"float",-2147483647,2147483647,0.01,mental_err or context_err)
    cache.items[#cache.items].editable=mental_context~=nil
    cache.items[#cache.items].live_value=mental_context and mental_context.value or nil
    local kd,kd_err=Module.Profile.read_float("MPPLY_KILL_DEATH_RATIO")
    add("kd_ratio","K/D Ratio",kd,"float",-2147483647,2147483647,0.01,kd_err)
    local kills,kills_err=read_stat("MPPLY_KILLS_PLAYERS")
    add("player_kills","Player Kills",kills,"int",-2147483647,2147483647,1,kills_err)
    local deaths,deaths_err=read_stat("MPPLY_DEATHS_PLAYER")
    add("player_deaths","Player Deaths",deaths,"int",-2147483647,2147483647,1,deaths_err)
    local suicide,suicide_err=read_stat("MPPLY_DEATHS_PLAYER_SUICIDE")
    add("player_suicides","Player Suicide Deaths",suicide,"int",-2147483647,2147483647,1,suicide_err)
    local total_ms,parts,all_time=0,{},true
    for _,key in ipairs({"freemode","missions","deathmatches","races"}) do
        local name=Module.Profile.TIME_STATS[key]
        local value,err=read_stat(name)
        parts[key]=value
        if value then total_ms=total_ms+value else all_time=false end
        if key=="freemode" then
            add("freemode_minutes","Freemode Time (minutes)",value and value/60000 or nil,"time",-2147483647,2147483647,1,err)
            add("freemode_raw","Freemode Time (raw)",value,"int",-2147483647,2147483647,1,err)
        elseif key=="missions" then
            add("missions_minutes","Missions (minutes)",value and value/60000 or nil,"time",-2147483647,2147483647,1,err)
        elseif key=="deathmatches" then
            add("deathmatches_minutes","Deathmatches (minutes)",value and value/60000 or nil,"time",-2147483647,2147483647,1,err)
        elseif key=="races" then
            add("races_minutes","Races (minutes)",value and value/60000 or nil,"time",-2147483647,2147483647,1,err)
        end
    end
    add("tracked_total_minutes","Tracked Online Total — Minutes",all_time and total_ms/60000 or nil,"total_time",-2147483647,2147483647,1)
    add("tracked_total_raw","Tracked Online Total — Raw Stat",all_time and total_ms or nil,"int",-2147483647,2147483647,1)
    local playing,playing_err=Module.Profile.playing_time_minutes()
    add("mp_playing_time","Total Play Time (minutes)",playing,"read_only",0,0,0,playing_err)
    cache.time_parts=parts
    -- Grouped career data from the original stat editor. The snapshot owns
    -- only readings; no value is automatically written or persisted by CScript.
    cache.career_groups={}
    for _, group in ipairs(Module.Profile.CAREER_GROUPS)do
        local result={key=group.key,title=group.title,col=group.col,items={}}
        for _,spec in ipairs(group)do
            local qualified=Module.Profile.resolve_stat_name(slot,spec[1])
            local number,reason
            if qualified then number,reason=read_stat(qualified)end
            result.items[#result.items+1]={
                key="career_"..spec[1],label=spec[2],stat=spec[1],
                value=number,available=number~=nil,kind="int",
                minimum=0,maximum=2147483647,note=reason
            }
        end
        cache.career_groups[#cache.career_groups+1]=result
    end
    cache.commit_status=State.profile_pending_verify and "Checking" or nil
    State.profile_stats=cache
    return cache
end

-- A custom read is read-only and revalidates identity both before and
-- afterward; the name parser never accepts arbitrary globals or pointers.
function Module.Profile.custom_read(name, expected)
    local scope,why=Module.Profile.scope(expected)
    if not scope then return nil,why end
    local qualified,reason=Module.Profile.resolve_stat_name(scope.slot,name)
    if not qualified then return nil,reason end
    local value,err=read_stat(qualified)
    if not Module.Profile.scope(scope)then return nil,"Character/session changed."end
    return value,err
end

function Module.Profile.entry(name, value, kind, slot)
    local item={name=name, after=(kind=="float" or kind=="mental") and Module.Profile.float32(value) or value, kind=kind or "int"}
    if kind=="date" then
        local fields=Module.Profile.fields()
        if not fields then return nil,"Date editor unavailable." end
        item.read=function()return fields.ReadDate(slot)end
        item.write=function(v)return fields.WriteDate(slot,v)end
        local before,err=item.read()
        item.before=before
        if not Module.Profile.valid_value(before,"date") then return nil,err or "Creation date is unreadable."end
        item.after,err=fields.MergeDate(value,before)
        if not item.after then return nil,err end
        return item
    elseif kind=="mental" then
        item.read=function() return Module.Profile.read_character_float(slot,133,1) end
        local ok,hash=native_try("int",GET_STAT_HASH_FOR_CHARACTER_STAT,1,133,slot)
        local named=stat_hash(qualify_stat(slot,"PLAYER_MENTAL_STATE"))
        if not ok or not tonumber(hash) or not named or hash%4294967296~=named%4294967296 then
            return nil,"Mental State storage could not be validated."
        end
        item.write=function(v) local called,result=native_try("bool",Module.ProfileNative.SET_FLOAT,hash,v,true);return called and result==true end
    elseif kind=="float" then
        item.read=function() return Module.Profile.read_float(name) end
        local hash=stat_hash(name)
        item.write=function(v) local called,result=native_try("bool",Module.ProfileNative.SET_FLOAT,hash,v,true);return called and result==true end
    else
        item.read=function() return read_stat(name) end
        item.write=function(v) return write_stat(name,v) end
    end
    item.before=select(1,item.read())
    if not Module.Profile.valid_value(item.before,item.kind) then return nil,"Could not read "..name.."." end
    return item
end

function Module.Profile.close(a,b,kind)
    if kind=="date" then return a==b and Module.Profile.valid_value(a,kind) end
    if not Module.Profile.finite(a) or not Module.Profile.finite(b) then return false end
    if kind=="int" then return a==b end
    return Module.Profile.float32(a)==Module.Profile.float32(b)
end
function Module.Profile.derived_ratio(kills,deaths,suicides)
    local denominator=Module.Profile.signed32(deaths+suicides+suicides)
    if denominator==0 then return nil,"These counters produce an undefined K/D (zero denominator)." end
    return Module.Profile.float32(Module.Profile.float32(kills)/Module.Profile.float32(denominator))
end
function Module.Profile.plan_ratio(value, deaths, suicides)
    if not Module.Profile.finite(value) or not Module.Profile.finite(deaths) or not Module.Profile.finite(suicides) then
        return nil,"Current K/D operands could not be read."
    end
    local limit=Module.Profile.SIGNED_STAT_MAX
    local wanted=Module.Profile.float32(value)
    local current=Module.Profile.signed32(deaths+2*suicides)
    local function candidate(denominator)
        if denominator==0 or math.abs(denominator)>limit then return nil end
        local kills=Module.Profile.round(wanted*denominator)
        -- The boundary FLOAT rounds to 2147483648; the signed max still maps
        -- to that exact same FLOAT, so test representation before rejecting it.
        kills=math.max(-limit,math.min(limit,kills))
        local next_deaths=Module.Profile.signed32(denominator-2*suicides)
        if next_deaths < -limit then return nil end
        local actual=Module.Profile.derived_ratio(kills,next_deaths,suicides)
        if actual~=wanted then return nil end
        return {kills=kills,deaths=next_deaths,suicides=suicides,ratio=actual}
    end
    local keep=candidate(current)
    if keep then return keep end
    -- Bounded continued fractions find integer operands for the actual stored
    -- FLOAT. No arbitrary decimal-place restriction and no unbounded search.
    local x=math.abs(value); local n0,n1,d0,d1=0,1,1,0
    for _=1,32 do
        local whole=math.floor(x)
        local numerator,denominator=whole*n1+n0,whole*d1+d0
        if denominator>limit or numerator>limit then break end
        if denominator>0 then
            local max_multiple=math.max(1,math.floor(limit/math.max(denominator,numerator,1)))
            local multiple=math.max(1,math.min(max_multiple,math.ceil(math.abs(current)/denominator)))
            local found=candidate(denominator*multiple) or candidate(denominator)
            if found then return found end
        end
        local fractional=x-whole
        if fractional<=0 then break end
        n0,n1,d0,d1=n1,numerator,d1,denominator
        x=1/fractional
    end
    local boundary=candidate(1) or candidate(limit)
    if boundary then return boundary end
    return nil,"This ratio cannot be represented by the signed counters while preserving suicide deaths."
end

function Module.Profile.transaction(entries, scope)
    local applied={}
    local function rollback(reason)
        local active=Module.Profile.scope(scope)
        if not active then return false,reason.." The account/session changed; restoration was not attempted." end
        local restored=true
        for i=#applied,1,-1 do
            local item=applied[i]
            local read_ok,current=pcall(item.read)
            if not read_ok or not Module.Profile.valid_value(current,item.kind) then
                restored=false
            elseif Module.Profile.close(current,item.before,item.kind) then
                -- Already original; a rejected write may never have changed it.
            elseif not Module.Profile.close(current,item.after,item.kind) then
                restored=false -- Another writer owns the current value.
            elseif not Module.Profile.scope(scope) then
                return false,reason.." Context changed; remaining restoration stopped."
            else
                local wrote_ok,wrote=pcall(item.write,item.before)
                local checked,after=pcall(item.read)
                if not wrote_ok or not checked or wrote~=true or not Module.Profile.close(after,item.before,item.kind) then restored=false end
            end
        end
        return false,reason..(restored and " Previous values restored." or " Restoration could not be confirmed.")
    end
    for _,item in ipairs(entries) do
        if not Module.Profile.close(select(1,item.read()),item.before,item.kind) then return false,"Profile changed before applying. Refresh and try again." end
    end
    if not Module.Profile.scope(scope) then return false,"The character or session changed. Refresh the profile." end
    for _,item in ipairs(entries) do
        if not Module.Profile.scope(scope) then return rollback("The account or session changed while applying.") end
        if not Module.Profile.close(item.before,item.after,item.kind) then
            -- Include a rejected write in restoration: a host can mutate and then
            -- report failure. There is no yield inside this guarded transaction.
            applied[#applied+1]=item
            local wrote_ok,wrote=pcall(item.write,item.after)
            if not wrote_ok or wrote~=true then return rollback("Could not apply "..item.name..".") end
        end
    end
    if not Module.Profile.scope(scope) then return rollback("The account or session changed while applying.") end
    for _,item in ipairs(entries) do
        local read_ok,observed=pcall(item.read)
        if not read_ok or not Module.Profile.close(observed,item.after,item.kind) then return rollback("The game did not retain "..item.name..".") end
    end
    return true,{changed=#applied>0,entries=entries,scope=scope}
end

function Module.Profile.set(key,raw,expected)
    local value,parse_err=Module.Profile.parse(key,raw)
    local original_key=key
    -- Player kill/death counters must use the existing K/D consistency
    -- transaction, not a blind direct stat write.
    key=Module.Profile.career_alias(key) or key
    if value==nil then return false,parse_err end
    if State.in_flight or State.profile_pending_verify then return false,"Another profile change is finishing." end
    expected=expected or State.profile_stats
    local scope,scope_err=Module.Profile.scope(expected)
    if not scope then return false,scope_err end
    State.in_flight="profile:"..key
    local ok,result,detail=xpcall(function()
        local entries={}
        local function add(name,target,kind)
            local item,err=Module.Profile.entry(name,target,kind,scope.slot)
            if not item then error(err) end
            entries[#entries+1]=item
            return item
        end
        local mental_context
        if key=="rank" or key=="rp" then
            local fields=Module.Profile.fields()
            if not fields then return false,"Rank editor unavailable."end
            local xp=key=="rank" and fields.RPForRank(value) or value
            local rank=key=="rank" and value or fields.RankForRP(value)
            if xp==nil or rank==nil then return false,"Rank/RP values are outside the supported range."end
            -- freemode func_2301 maintains both stats and its player mirror.
            -- This edit does not issue an XP award or record earned activity.
            add(qualify_stat(scope.slot,"CHAR_XP_FM"),xp,"int")
            add(qualify_stat(scope.slot,"CHAR_RANK_FM"),rank,"int")
            local live,why=Module.Profile.player_globals()
            if not live or live.player~=scope.player then return false,why or "Current rank display context changed."end
            local g=live.globals
            if type(g.SetInt)~="function" or g.GetInt(1845347)~=32 then return false,"Rank display layout does not match the source."end
            for _,field in ipairs({{1,xp,"current rank XP"},{6,rank,"current rank level"}})do
                local index=1845347+1+live.player*884+198+field[1]
                local old=g.GetInt(index)
                if not Module.Profile.finite(old) or old%1~=0 or old<0 or old>1787576850 then
                    return false,"Current rank display could not be read."
                end
                entries[#entries+1]={name=field[3],kind="int",before=old,after=field[2],
                    read=function()return g.GetInt(index)end,
                    write=function(v)return g.SetInt(index,v)~=false end}
            end
        elseif key=="creation_date" then
            add(qualify_stat(scope.slot,"CHAR_DATE_CREATED"),value,"date")
        elseif key=="mental_state" then
            local item=add("Mental State",value,"mental")
            local err
            mental_context,err=Module.Profile.mental_context(item.before)
            if not mental_context then return false,err end
            local ctx=mental_context
            entries[#entries+1]={name="current Mental State",kind="float",before=ctx.value,after=Module.Profile.float32(value),
                read=function() local got,v=pcall(ctx.globals.GetFloat,ctx.index);return got and v or nil end,
                write=function(v) local wrote,out=pcall(ctx.globals.SetFloat,ctx.index,v);return wrote and out~=false end}
        elseif key=="kd_ratio" or Module.Profile.COUNTERS[key] then
            local kills=add("MPPLY_KILLS_PLAYERS",0)
            local deaths=add("MPPLY_DEATHS_PLAYER",0)
            local suicides=add("MPPLY_DEATHS_PLAYER_SUICIDE",0)
            kills.after,deaths.after,suicides.after=kills.before,deaths.before,suicides.before
            local ratio
            if key=="kd_ratio" then
                local plan,err=Module.Profile.plan_ratio(value,deaths.before,suicides.before)
                if not plan then return false,err end
                kills.after,deaths.after,ratio=plan.kills,plan.deaths,plan.ratio
            else
                for _,item in ipairs(entries) do if item.name==Module.Profile.COUNTERS[key] then item.after=value end end
                local reason
                ratio,reason=Module.Profile.derived_ratio(kills.after,deaths.after,suicides.after)
                if ratio==nil then return false,reason end
            end
            local ratio_entry=add("MPPLY_KILL_DEATH_RATIO",ratio,"float")
            local ctx,ctx_err=Module.Profile.player_globals()
            if not ctx then return false,ctx_err end
            local count_ok,count=pcall(ctx.globals.GetInt,1845347)
            if not count_ok or count~=32 then return false,"Current profile display is unavailable. Try again in freemode." end
            local base=1845347+1+ctx.player*884+198
            for _,field in ipairs({
                {26,"float",ratio_entry.before,ratio,"current K/D"},
                {28,"int",kills.before,kills.after,"current kills"},
                {29,"int",Module.Profile.signed32(deaths.before+suicides.before),Module.Profile.signed32(deaths.after+suicides.after),"current deaths"},
            }) do
                local index=base+field[1]
                local getter=field[2]=="float" and ctx.globals.GetFloat or ctx.globals.GetInt
                local setter=field[2]=="float" and ctx.globals.SetFloat or ctx.globals.SetInt
                if type(setter)~="function" then return false,"Current profile display cannot be updated." end
                local got,observed=pcall(getter,index)
                if not got or not Module.Profile.finite(observed) or observed < -2147483648 or observed>2147483648
                    or field[2]=="int" and observed%1~=0 then
                    return false,"Current profile display could not be read. Refresh and try again."
                end
                entries[#entries+1]={name=field[5],kind=field[2],before=observed,after=field[4],
                    read=function()local good,v=pcall(getter,index);return good and v or nil end,
                    write=function(v)local good,out=pcall(setter,index,v);return good and out~=false end}
            end
        elseif Module.Profile.CAREER_BY_KEY[key]or
            type(key)=="string"and key:sub(1,12)=="custom_stat:"then
            local stat=Module.Profile.CAREER_BY_KEY[key]or key:sub(13)
            local qualified,err=Module.Profile.resolve_stat_name(scope.slot,stat)
            if not qualified then return false,err end
            add(qualified,value)
        elseif key=="missions_minutes" or key=="deathmatches_minutes" or key=="races_minutes" then
            local part=key:gsub("_minutes$","")
            local target,convert_err=Module.Profile.time_raw(value,true)
            if target==nil then return false,convert_err end
            local stat=Module.Profile.TIME_STATS[part]
            if not stat then return false,"This playtime field is unsupported." end
            add(stat,target)
        elseif key=="freemode_minutes" or key=="tracked_total_minutes" or key=="freemode_raw" or key=="tracked_total_raw" then
            local target,convert_err=Module.Profile.time_raw(value,key:find("minutes",1,true)~=nil)
            if target==nil then return false,convert_err end
            if key=="tracked_total_minutes" or key=="tracked_total_raw" then
                local other=0
                for part,name in pairs(Module.Profile.TIME_STATS) do
                    if part~="freemode" then local current,err=read_stat(name);if current==nil then return false,err end;other=other+current end
                end
                target=target-other
                if target < -2147483647 or target > 2147483647 then return false,"This total would overflow Freemode Raw Stat while preserving the other time counters." end
            end
            add(Module.Profile.TIME_STATS.freemode,target)
        end
        local applied,change=Module.Profile.transaction(entries,scope)
        if not applied then return false,change end
        if mental_context then
            local band=Module.Profile.round(Module.Profile.float32(Module.Profile.float32(value)*Module.Profile.float32(0.07)))
            -- The supplied caller reaches this native only with bands 0..7.
            -- Raw FLOAT editing must not probe an unproven native parameter:
            -- host fail-fast can escape Lua error handling.
            local band_ok=false
            if band>=0 and band<=7 then band_ok=native_try("void",Module.ProfileNative.SET_MENTAL,band) end
            change.band_applied=band_ok==true
            -- The session field is independently read back; the void native
            -- does not provide independent confirmation of matchmaking state.
            if not band_ok then change.warning="Mental State saved; this value has no confirmed matchmaking update." end
        end
        return true,change
    end,function(err)return tostring(err)end)
    State.in_flight=nil
    if not ok then return false,result end
    if result~=true then return false,detail end
    State.profile_last_change={key=key,detail=detail}
    State.profile_pending_verify={key=key,detail=detail,due=now_ms()+250,deadline=now_ms()+1750}
    Module.Profile.refresh()
    return true,detail
end

function Module.Profile.rollback_owned(detail)
    if not Module.Profile.scope(detail.scope) then return false,"context changed; no restoration attempted",false end
    local complete,conflict,pending=true,false,false
    detail.cleanup=detail.cleanup or {}
    for i=#detail.entries,1,-1 do
        local item=detail.entries[i]
        local ok,current=pcall(item.read)
        if not ok or not Module.Profile.valid_value(current,item.kind) then
            complete=false;pending=true;detail.cleanup[item.name]="UNREADABLE"
        elseif Module.Profile.close(current,item.before,item.kind) then
            detail.cleanup[item.name]="RESTORED"
        elseif not Module.Profile.close(current,item.after,item.kind) then
            complete=false;conflict=true;detail.cleanup[item.name]="EXTERNAL_PRESERVED"
        elseif not Module.Profile.scope(detail.scope) then
            return false,"context changed; remaining restoration stopped",false
        else
            local wrote,value=pcall(item.write,item.before)
            local read,observed=pcall(item.read)
            if wrote and value==true and read and Module.Profile.close(observed,item.before,item.kind) then
                detail.cleanup[item.name]="RESTORED"
            else complete=false;pending=true;detail.cleanup[item.name]="PENDING" end
        end
    end
    return complete,conflict and "External changes preserved; owned fields restored where possible."
        or (pending and "Owned restoration is pending." or "Previous values restored."),pending
end

function Module.Profile.verify_pending(now)
    local pending=State.profile_pending_verify
    if not pending or now<pending.due then return end
    local detail=pending.detail
    local valid,reason=Module.Profile.scope(detail.scope)
    local mismatch,display_lag=false,true
    if not pending.cleanup then detail.observed={} end
    if valid and not pending.cleanup then
        for _,item in ipairs(detail.entries) do
            local ok,observed=pcall(item.read)
            ok=ok and Module.Profile.valid_value(observed,item.kind)
            detail.observed[#detail.observed+1]={field=item.name,kind=item.kind,before=item.before,
                requested=item.after,observed=ok and observed or nil,read_ok=ok}
            if not ok or not Module.Profile.close(observed,item.after,item.kind) then
                mismatch=true
                -- Only an unchanged display mirror gets time to settle. Persistent
                -- stat disagreement or an external new display value is a conflict.
                if not ok or not item.name:match("^current ")
                    or not Module.Profile.close(observed,item.before,item.kind) then display_lag=false end
                reason="The game changed "..item.name.." after applying."
            end
        end
        if mismatch and display_lag and now<(pending.deadline or pending.due) then
            pending.due=now+250
            State.profile_stats.commit_status="Settling"
            return -- read-only waiting; no fight with freemode's display writer
        end
        valid=not mismatch
    end
    if pending.cleanup then valid=false;reason=pending.reason end
    if not valid and Module.Profile.scope(detail.scope) then
        local restored,cleanup,pending_owned=Module.Profile.rollback_owned(detail)
        pending.reason=pending.reason or reason
        pending.cleanup_attempts=(pending.cleanup_attempts or 0)+1
        if pending_owned and pending.cleanup_attempts<3 then
            pending.cleanup=true;pending.due=now+250
            State.profile_stats.commit_status="Restoring"
            State.profile_stats.last_error=reason
            return
        end
        reason=tostring(reason).." "..cleanup
        detail.fully_restored=restored
    end
    State.profile_pending_verify=nil
    Module.Profile.refresh()
    State.profile_stats.commit_status=valid and (detail.warning and "Saved" or "Applied") or "Not applied"
    State.profile_stats.last_error=not valid and reason or detail.warning
    if valid then
        add_history("info","Profile Updated",pending.key)
        log_info("Profile commit "..pending.key.." verified immediate stat/display readbacks (reload persistence untested); rows="..tostring(#detail.entries)
            ..(detail.warning and (" warning="..detail.warning) or ""))
    else
        log_error("Profile commit "..pending.key..": "..tostring(reason))
        for _,row in ipairs(detail.observed or {}) do
            log_info(("Profile evidence %s kind=%s before=%s requested=%s observed=%s cleanup=%s")
                :format(row.field,row.kind,tostring(row.before),tostring(row.requested),
                    tostring(row.observed),tostring(detail.cleanup and detail.cleanup[row.field])))
        end
    end
end

-- User-requested wallet/bank transfers. No stat editing and no blind retries.
function Module.NewBankTransfer(host)
    local pending, stopped, next_poll = nil, false, 0
    local accounting_excluded=false
    local view = {busy=false, pause_tracking=false, message='', success=false}
    local api={}
    local function finish(message,success)
        pending=nil;view={busy=false,pause_tracking=false,message=message,success=success==true}
    end
    local function valid_scope(s)
        return type(s)=='table' and s.ready==true and s.account~=nil and (s.slot==0 or s.slot==1)
    end
    local function same(s,p)
        return valid_scope(s) and s.account==p.scope.account and s.slot==p.scope.slot
            and s.generation==p.scope.generation
    end
    local function amount(text)
        if text=='all' then return 'all' end
        text=tostring(text or ''):match('^%s*(.-)%s*$'):gsub('^%$','')
        if text:find(',',1,true) then
            local first,tail=text:match('^(%d%d?%d?)(,.*)$')
            if not first then return nil end
            local rest=tail:gsub(',%d%d%d','')
            if rest~='' then return nil end
            text=text:gsub(',','')
        end
        if not text:match('^%d+$') then return nil end
        local n=tonumber(text)
        if not n or n<1 or n>2147483647 or n~=math.floor(n) then return nil end
        return n
    end
    function api.Request(direction,text)
        if stopped then return false,'Transfers are stopped.' end
        if pending then return false,'A transfer is already pending.' end
        if direction~='deposit' and direction~='withdraw' then return false,'Choose Deposit or Withdraw.' end
        local n=amount(text)
        if not n then return false,'Enter a whole amount from $1 to $2,147,483,647.' end
        local scope=host.cached_scope()
        if not valid_scope(scope) then return false,'Join GTA Online and wait for your balance.' end
        pending={direction=direction,requested=n,scope={account=scope.account,slot=scope.slot,generation=scope.generation}}
        view={busy=true,pause_tracking=true,message='Queued',success=false};next_poll=0
        return true
    end
    function api.Tick()
        if stopped or not pending then return end
        local now=host.clock()
        if now<next_poll then return end
        next_poll=now+500
        local p=pending
        if p.sent and now-p.started>=30000 and not p.reconciled then
            p.reconciled=true;view.pause_tracking=false;accounting_excluded=true
            if host.reconcile then pcall(host.reconcile) end
        end
        if p.scope_lost or not same(host.scope(),p) then
            if not p.sent then finish('Transfer cancelled: session or character changed.')
            else
                p.scope_lost=true
                view.message='Session changed. Check your balances before another transfer.'
            end
            return
        end
        local cash,bank=host.read(p.scope.slot)
        local function valid_balance(n)
            return type(n)=='number' and n==n and n>=0 and n<=2147483647 and n==math.floor(n)
        end
        if not valid_balance(cash) or not valid_balance(bank) then
            if not p.sent then finish('Balances are unavailable.') end
            return
        end
        if not p.sent then
            local available=p.direction=='deposit' and cash or bank
            local target=p.direction=='deposit' and bank or cash
            local n=p.requested=='all' and available or p.requested
            if n<1 then finish('Nothing to transfer.');return end
            if n>available then finish('Not enough money.');return end
            if n>2147483647 or target+n>2147483647 then finish('This transfer exceeds the supported balance limit.');return end
            if not same(host.scope(),p) then finish('Transfer cancelled: character changed.');return end
            p.cash,p.bank,p.amount,p.started=cash,bank,n,now
            -- Mark before calling out so reentry cannot submit twice.
            p.sent=true;view.message='Transferring...'
            local ok,called,accepted,reason=pcall(host.submit,p.direction,p.scope.slot,n)
            if not ok or called~=true or type(accepted)~='boolean' then
                view.message='Transfer response unavailable. Waiting for confirmation.';return
            end
            if accepted==false then finish(type(reason)=='string' and reason or 'Transfer was not accepted. Try again later.');return end
            return
        end
        local ok,called,status=pcall(host.status,p.direction)
        if not ok then called=false end
        if called and status==1 then p.saw_pending=true end
        if called and status==3 then
            local expected_cash=p.cash+(p.direction=='withdraw' and p.amount or -p.amount)
            local expected_bank=p.bank+(p.direction=='deposit' and p.amount or -p.amount)
            if cash==expected_cash and bank==expected_bank then
                -- Release only after both balances verify; completion must never repeat
                -- if its native bridge or refresh throws after accepting the nonce.
                finish(p.direction=='deposit' and 'Deposited to bank.' or 'Withdrawn to wallet.',true)
                pcall(host.complete)
                return
            end
        elseif called and type(status)=='number' and status~=1 and status~=0 then
            -- A terminal value can belong to a prior transaction. Only release
            -- after observing this request pending and unchanged source/destination.
            if p.saw_pending and cash==p.cash and bank==p.bank then
                finish('Transfer failed. Check your balances before retrying.');return
            end
        end
        if now-p.started>=30000 then view.message='Outcome uncertain. Check your balances; further transfers are locked.' end
    end
    function api.Snapshot()return {busy=view.busy,pause_tracking=view.pause_tracking,message=view.message,success=view.success,
        accounting_excluded=accounting_excluded,accounting_message=accounting_excluded and 'Earnings during an uncertain bank transfer were excluded. Delayed balance updates may affect earnings totals.' or nil}end
    function api.Stop()stopped=true;if pending and not pending.sent then finish('Transfer cancelled.') end end
    return api
end


function Module.EnsureBankTransfer()
    if Module.bank_transfer then return Module.bank_transfer end
    Module.bank_transfer=Module.NewBankTransfer({
        cached_scope=function()
            return {account=State.account_id,slot=State.character_slot,generation=State.generation,
                ready=started and State.online==true and State.account_verified==true and State.persistence_loaded==true}
        end,
        scope=function()
            local slot=detect_character_slot()
            local account=resolve_local_account_identity()
            return {account=account,slot=slot,generation=State.generation,
                ready=started and slot~=nil and account~=nil and account==State.account_id
                    and State.account_verified==true and State.persistence_loaded==true}
        end,
        clock=now_ms,
        read=function(slot)
            local current=detect_character_slot()
            if current~=slot then return nil end
            local a,cash=native_try('int',NETWORK_GET_VC_WALLET_BALANCE,slot)
            local b,bank=native_try('int',NETWORK_GET_VC_BANK_BALANCE)
            if a and b then return cash,bank end
        end,
        submit=function(direction,slot,n)
            local busy_ok,busy=native_try('bool',0x613F125BA3BD2EB9)
            if not busy_ok or type(busy)~='boolean' then return true,false,'Bank service availability could not be checked.' end
            if busy then return true,false,'Another bank transaction is in progress.' end
            local memory=module_context and module_context.Raw and module_context.Raw.Memory
            if not memory or type(memory.AllocInt)~='function' or type(memory.Free)~='function'
                or type(memory.WriteInt)~='function' or type(memory.ReadInt)~='function' then
                return true,false,'Bank service memory APIs are unavailable.'
            end
            local owned={}
            local ready_ok,ready,reason=pcall(function()
                for i=1,2 do
                    local pointer=memory.AllocInt()
                    if not pointer or pointer==0 then error('Manager state allocation failed') end
                    owned[i]=pointer;memory.WriteInt(pointer,-1)
                end
                local called=native_try('bool',0x897433D292B44130,owned[1],owned[2])
                if called~=true then return false,'Bank service state could not be read.' end
                -- Enhanced ATM/banking use output state 8, ignoring the native
                -- BOOL result. Live ready state 8 can legitimately return false.
                local state=memory.ReadInt(owned[1])
                if state==-1 then return false,'Bank service state was not returned.' end
                if state~=8 then return false,'Bank service is not ready (state '..tostring(state)..').' end
                return true
            end)
            for _,pointer in ipairs(owned) do pcall(memory.Free,pointer) end
            if not ready_ok then return true,false,'Bank service state check failed.' end
            if not ready then return true,false,reason end
            local called,accepted=native_try('bool',direction=='deposit' and 0xC2F7FE5309181C7D or 0xD47A2C1BA117471D,slot,n)
            return called,accepted,'The bank service declined this transfer request.'
        end,
        status=function(direction)
            return native_try('int',direction=='deposit' and 0x350AA5EBC03D3BD2 or 0x23789E777D14CE44)
        end,
        reconcile=function()
            -- An uncertain interval cannot safely attribute earnings. Resume from
            -- a fresh baseline without presenting the transfer as successful.
            clear_money_baseline()
        end,
        complete=function()
            native_try('bool',0x498C1E05CE5F7877)
            refresh_money(true)
        end,
    })
    return Module.bank_transfer
end

local function queue_action(key, value)
    key = tostring(key or "")
    if key == "" then return false, "Economy action key is required" end
    local profile_key=key:match("^profile_stat_set:(.+)$")
    local expected
    if profile_key then
        local parsed,err=Module.Profile.parse(profile_key,value)
        if parsed==nil then return false,err end
        value=parsed
        local cache=State.profile_stats
        if not cache or cache.status~="READY" or not cache.account or State.account_verified~=true
            or State.persistence_loaded~=true then return false,"Refresh the profile before applying." end
        if State.profile_pending_verify or State.in_flight then return false,"Another profile change is finishing." end
        expected={slot=cache.slot,account=cache.account,generation=cache.generation}
    end
    for _, pending in ipairs(State.action_queue) do
        if pending.key == key then return false, "This change is already queued." end
        if profile_key and pending.key:match("^profile_stat_set:") then return false,"Another profile change is queued." end
    end
    if #State.action_queue >= MAX_ACTION_QUEUE then return false, "Economy action queue is full" end
    State.action_queue[#State.action_queue + 1] = { key = key, value = value, expected=expected }
    if profile_key then State.profile_stats.commit_status="Applying";State.profile_stats.last_error=nil end
    return true
end

local function process_action(index)
    local action = table.remove(State.action_queue, index or 1)
    if not action then return end
    if action.key == "refresh" then refresh_money(true)
    elseif action.key == "restore" then restore_last_snapshot()
    elseif action.key == "advanced" then State.advanced = action.value == true; save_settings()
    elseif action.key == "recovery_refresh" then recovery_refresh()
    elseif action.key == "profile_progression_refresh" then profile_progression_refresh()
    elseif action.key == "career_progress_refresh" then career_progress_refresh()
    elseif action.key == "recovery_max_skills" then recovery_max_skills()
    elseif action.key == "recovery_restore_skills" then recovery_restore_last()
    elseif action.key == "achievement_refresh" then achievement_refresh()
    elseif action.key == "achievement_grant_all" then achievement_bulk_start()
    elseif action.key == "achievement_grant_all_cancel" then achievement_bulk_cancel()
    elseif action.key:match("^achievement_grant:") then
        achievement_grant(action.key:sub(#"achievement_grant:" + 1))
    elseif action.key == "award_reward_refresh" then award_reward_refresh()
    elseif action.key == "award_complete_all_supported" then recovery_complete_all_supported_award_sets()
    elseif action.key == "reward_repair_all_supported" then recovery_repair_all_supported_rewards()
    elseif action.key == "award_reward_repair_all_earned" then award_reward_repair_all_earned()
    elseif action.key:match("^award_reward_repair:") then
        award_reward_repair(action.key:sub(#"award_reward_repair:" + 1))
    elseif action.key == "derived_award_refresh" then derived_award_refresh()
    elseif action.key == "derived_award_repair_all_earned" then derived_award_repair_all_earned()
    elseif action.key:match("^derived_award_repair:") then
        derived_award_repair(action.key:sub(#"derived_award_repair:" + 1))
    elseif action.key == "collectible_refresh" then collectible_refresh()
    elseif action.key == "collectible_repair_all_earned" then collectible_repair_all_earned()
    elseif action.key:match("^collectible_reward_repair:") then
        collectible_reward_repair(action.key:sub(#"collectible_reward_repair:" + 1))
    elseif action.key == "account_snapshot_create" then account_snapshot_create()
    elseif action.key == "account_snapshot_load_latest" then account_snapshot_load_latest()
    elseif action.key == "account_snapshot_restore_skills" then account_snapshot_restore_skills()
    elseif action.key == "profile_stats_refresh" then Module.Profile.refresh()
    elseif action.key:match("^profile_stat_set:") then
        local ok,detail=Module.Profile.set(action.key:sub(#"profile_stat_set:" + 1),action.value,action.expected)
        if not ok then
            State.profile_stats=State.profile_stats or {};State.profile_stats.last_error=tostring(detail);State.profile_stats.commit_status="Not applied"
            log_error("Profile commit "..action.key.." rejected: "..tostring(detail))
        end
    elseif action.key:match("^recovery_skill:") then
        recovery_set_skill(action.key:sub(#"recovery_skill:" + 1), action.value)
    else log_error("Unknown queued Economy action: " .. tostring(action.key)) end
end

local function tick()
    if not started then return end
    local now = now_ms()
    -- Runtime camera/launcher/teleport work is independent of account storage.
    -- Service it from the existing scheduler even while account reads retry.
    local runtime_heists = module_context and module_context.CScript and module_context.CScript.Heists
    if runtime_heists and type(runtime_heists.TickRuntime) == "function" then runtime_heists.TickRuntime(now) end
    local runtime_businesses = module_context and module_context.CScript and module_context.CScript.Businesses
    if runtime_businesses and type(runtime_businesses.TickRuntime) == "function" then runtime_businesses.TickRuntime(now) end
    local automation=module_context and module_context.CScript and module_context.CScript.BusinessAutomation
    if automation and type(automation.Tick)=="function" then automation.Tick(now) end
    if State.persistence_loaded ~= true then
        if State.persistence_retry_at_ms and now >= State.persistence_retry_at_ms then
            attempt_persistence_bootstrap("START_RETRY")
        end
        return
    end
    Module.Income.Poll(now)
    if not verify_active_account_scope(now) then return end
    if Module.bank_transfer then Module.bank_transfer.Tick() end
    Module.Profile.verify_pending(now)
    -- UI confirms at most one commit. Profile work is responsive without moving
    -- journal/business refresh or disk persistence onto a faster cadence.
    for index,action in ipairs(State.action_queue) do
        if action.key=="profile_stats_refresh" or action.key:match("^profile_stat_set:") then process_action(index);break end
    end
    if now - (State.last_tick_ms or -100000) < 1000 then return end
    State.last_tick_ms = now
    process_action()
    achievement_bulk_tick()
    refresh_money(false)
    if now<=(State.profile_visible_until_ms or -1) and now>=(State.next_profile_visible_ms or 0) then
        State.next_profile_visible_ms=now+5000
        Module.Profile.refresh();recovery_refresh()
    end
    -- Heist commands are serviced solely by TickRuntime before storage/account gates.
    local businesses = module_context and module_context.CScript and module_context.CScript.Businesses
    if businesses and type(businesses.Tick) == "function" then businesses.Tick(now) end
    update_cached_summary(epoch(), false)
    if State.persistence_dirty and now - (State.last_persist_ms or -100000) >= 5000 then
        State.last_persist_ms = now
        save_histories()
    end
end

local function snapshot_state()
    return {
        account_id = State.account_id, account_name = State.account_name,
        account_verified = State.account_verified == true,
        account_label = State.account_id and ((State.account_name or "Rockstar account")
            .. "  |  RID " .. tostring(State.account_id)) or "Rockstar account unavailable",
        online = State.online == true, character_slot = State.character_slot,
        character = State.character_label or "Unavailable",
        session = State.online and "GTA Online" or "Offline / unavailable",
        bank_transfer = Module.bank_transfer and Module.bank_transfer.Snapshot() or {},
        cash = State.cash, bank = State.bank, total = State.total,
        tracking_status = State.money_tracking_status,
        money_status = State.money_status, earnings = State.earnings_summary or update_cached_summary(epoch(), false),
        earnings_history = State.recent_earnings or {},
        daily_caution = State.daily_caution, weekly_caution = State.weekly_caution,
        advanced = State.advanced == true, hud_enabled = State.hud_enabled == true,
        transaction_status = State.transaction_status or "IDLE",
        in_flight = State.in_flight, last_error = State.last_error,
        last_changes = State.last_changes or {}, last_snapshot = State.last_snapshot,
        history = State.history or {}, persistence_status = State.persistence_status,
        persistence_stage = State.persistence_stage, persistence_error = State.persistence_error,
        generation = State.generation or 0,
        queued_actions = #State.action_queue,
        diagnostics = {
            baseline_cash = State.baseline_cash, baseline_bank = State.baseline_bank,
            baseline_total = State.baseline_total, baseline_valid = State.baseline_valid == true,
            last_verified_delta = State.last_verified_delta,
            last_event_timestamp = State.last_event_timestamp,
            last24_event_count = State.earnings_summary and State.earnings_summary.last24_count or 0,
            last7_event_count = State.earnings_summary and State.earnings_summary.last7_count or 0,
            history_file = active_paths() and active_paths().earnings or "Unavailable",
            history_backup = active_paths() and active_paths().earnings_backup or "Unavailable",
            persistence_status = State.persistence_status, persistence_stage = State.persistence_stage,
            persistence_error = State.persistence_error,
            persistence_loaded = State.persistence_loaded == true,
            persistence_authoritative = State.persistence_authoritative == true,
            persistence_attempts = State.persistence_attempts,
            persistence_failure_stage = State.persistence_failure_stage,
            account_id = State.account_id, account_name = State.account_name,
            account_verified = State.account_verified == true, account_error = State.account_error,
            character_slot = State.character_slot, tracking_session = State.tracking_session_id,
        },
    }
end

local function set_caution_thresholds(daily, weekly)
    if tonumber(daily)~=DEFAULT_DAILY_CAUTION or tonumber(weekly)~=DEFAULT_WEEKLY_CAUTION then
        return false,"Earnings limits are fixed at $30M per 24 hours and $150M per 7 days."
    end
    State.daily_caution,State.weekly_caution=DEFAULT_DAILY_CAUTION,DEFAULT_WEEKLY_CAUTION
    update_cached_summary(epoch(), false)
    return save_settings()
end

local function reset_caution_thresholds()
    return set_caution_thresholds(DEFAULT_DAILY_CAUTION, DEFAULT_WEEKLY_CAUTION)
end

local function set_hud_enabled(value)
    State.hud_enabled = value == true
    update_cached_summary(epoch(), false)
    return save_settings()
end

local function reset_earnings_history()
    local paths = active_paths()
    if not State or not paths or type(paths.earnings) ~= "string" or type(paths.earnings_backup) ~= "string"
        or State.account_verified ~= true or not State.account_id
        or tonumber(State.account_id) ~= tonumber(paths.account_id)
        or State.persistence_loaded ~= true or State.persistence_authoritative ~= true
        or State.persistence_write_blocked then
        return false, "history reset is waiting for verified account storage"
    end
    local slot = State.character_slot
    if slot ~= 0 and slot ~= 1 then return false, "current character slot is unavailable" end
    local generation = Module.Journal.Epoch(State.lifetime_by_slot, slot)
    if generation >= Module.Journal.MAX_EPOCH then return false, "local history reset generation is exhausted" end
    local old_events, old_lifetime = State.earnings, State.lifetime_by_slot
    local old_disk_payload = read_file(paths.earnings)
    local old_delta, old_timestamp = State.last_verified_delta, State.last_event_timestamp
    local old_dirty = State.earnings_dirty
    local retained = {}
    for _, item in ipairs(State.earnings or {}) do
        if item.character_slot ~= slot then retained[#retained + 1] = item end
    end
    local lifetime = { [0] = old_lifetime[0], [1] = old_lifetime[1], journal_epochs = {
        [0] = Module.Journal.Epoch(old_lifetime, 0), [1] = Module.Journal.Epoch(old_lifetime, 1) } }
    lifetime[slot], lifetime.journal_epochs[slot] = 0, generation + 1
    State.earnings, State.lifetime_by_slot = retained, lifetime
    Dirty.Earnings()
    local intended_payload = serialize_earnings()
    local ok, err = commit_earnings("reset-history")
    if not ok then
        local actual_payload = read_file(paths.earnings)
        local _, _, actual_valid = parse_earnings(actual_payload, State.account_id)
        if actual_valid and canonical_text(actual_payload) == canonical_text(intended_payload) then
            -- Some hosts can store the bytes and still report a failed write.
            -- An independent exact reread establishes the committed outcome.
            ok = true
            State.earnings_dirty = false
            State.persistence_status = Module.Journal.recovery_ambiguous and "DEGRADED" or "READY"
            State.persistence_stage = "RESET_REREAD"
            State.persistence_error = Module.Journal.recovery_ambiguous and Module.Journal.ambiguity_message or nil
            Dirty.Sync()
        elseif canonical_text(actual_payload) ~= canonical_text(old_disk_payload)
            or (actual_payload == nil and file_exists(paths.earnings) ~= false) then
            set_persistence_failure("DEGRADED_READONLY", "RESET_UNCERTAIN",
                "History reset could not be confirmed. The saved history needs recovery before further writes.", true)
            State.persistence_authoritative = false
            State.attribution_epoch = (State.attribution_epoch or 0) + 1
            Module.Settlement.pending = {}
            clear_money_baseline()
        end
    end
    if not ok then
        State.earnings, State.lifetime_by_slot = old_events, old_lifetime
        State.last_verified_delta, State.last_event_timestamp = old_delta, old_timestamp
        State.earnings_dirty = old_dirty
        Dirty.Sync()
        update_cached_summary(epoch(), false)
        return false, err or "local earnings history could not be saved"
    end
    State.last_verified_delta, State.last_event_timestamp = nil, nil
    State.threshold_levels[slot] = nil
    if Module.Income and Module.Income.ResetSlot then Module.Income.ResetSlot(slot) end
    -- Keep a verified reset fence in the normal fallback journal as well.
    -- The pre-reset bytes remain in the existing pending backup.
    local backup_ok, backup_err = write_file(paths.earnings_backup, serialize_earnings())
    if not backup_ok then
        set_persistence_failure("DEGRADED", "RESET_BACKUP", backup_err, false)
    end
    update_cached_summary(epoch(), false)
    add_history("info", "Reset Earnings History", ("Cleared CScript local history for Rockstar ID %s, Character %d")
        :format(tostring(State.account_id), slot + 1))
    save_histories()
    return true
end

local function log_earnings_snapshot()
    local summary = State.earnings_summary or update_cached_summary(epoch(), false)
    log_info(("Earnings snapshot account=%s slot=%s cash=%s bank=%s combined=%s 24h=%s/%s (%0.1f%% %s) 7d=%s/%s (%0.1f%% %s) events=%d/%d"):format(
        tostring(State.account_id), tostring(State.character_slot), tostring(State.cash), tostring(State.bank), tostring(State.total),
        tostring(summary.last24), tostring(summary.daily.limit), summary.daily.percentage, summary.daily.status,
        tostring(summary.last7), tostring(summary.weekly.limit), summary.weekly.percentage, summary.weekly.status,
        summary.last24_count, summary.last7_count))
    return true
end

local function build_public_api()
    return {
        RequestBankTransfer = function(direction,text)
            if not started or not State then return false,'Economy is not running.' end
            return Module.EnsureBankTransfer().Request(direction,text)
        end,
        Refresh = function() return refresh_money(true) end, QueueAction = queue_action, Snapshot = snapshot_state,
        CurrentSlot = detect_character_slot, QualifyStat = qualify_stat,
        ReadStat = read_stat, ReadBoolStat = Module.ReadBoolStat, WriteStat = write_stat, RunTransaction = run_transaction,
        RestoreLastSnapshot = restore_last_snapshot, RecordHistory = add_history,
        RecordEarning = add_earning, BeginEarningAttribution = Module.BeginEarningAttribution,
        AttributeEarning = Module.AttributeEarning, Save = save_histories, Invalidate = invalidate, Tick = tick,
        BeginEarningSettlement = Module.Settlement.Begin,
        ConfirmEarningSettlement = Module.Settlement.Confirm,
        IsEarningSettlementCurrent = Module.Settlement.Current,
        SummaryAt = function(current) return calculate_earnings_summary(current, State.character_slot) end,
        HudSnapshot = function() return State.hud_snapshot end,
        SetHudEnabled = set_hud_enabled, ResetEarningsHistory = reset_earnings_history,
        LogEarningsSnapshot = log_earnings_snapshot,
        RecoverySnapshot = recovery_snapshot, RecoveryRefresh = recovery_refresh,
        RequestVisibleProfileRefresh=function()
            State.profile_visible_until_ms=now_ms()+1500
        end,
        ProfileStatsRefresh = Module.Profile.refresh, ProfileStatsSnapshot = function()
            local cache=State.profile_stats
            if cache and cache.account==State.account_id and cache.generation==(tonumber(State.generation) or 0) then return cache end
            return {status="Loading",items={},generation=tonumber(State.generation) or 0,account=State.account_id}
        end, ProfileParse=Module.Profile.parse, ProfileRatioPlan=Module.Profile.plan_ratio,
        ProfileStatSet = Module.Profile.set,
        ProfileCustomRead = Module.Profile.custom_read,
        ProfileProgressionRefresh = profile_progression_refresh, ProfileProgressionSnapshot = profile_progression_snapshot,
        RecoverySetSkill = recovery_set_skill, RecoveryMaxSkills = recovery_max_skills,
        RecoveryRestoreLast = recovery_restore_last, RecoveryCatalog = RECOVERY_SKILLS,
        AchievementRefresh = achievement_refresh, AchievementSnapshot = achievement_snapshot,
