function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table" or type(context.CScript) ~= "table"
        or type(context.Natives) ~= "table" or type(context.Events) ~= "table" then
        error("modules.economy_core requires State, CScript, Natives, and Events services")
    end
    module_context = context
    Module.bank_transfer=nil
    cached_file_api = nil
    cached_paths = nil
    final_save_completed = false
    final_save_attempted = false
    emergency_save_attempted = false
    State = context.State.Economy or {}
    context.State.Economy = State
    State.history, State.earnings, State.lifetime_by_slot = {}, {}, { [0] = 0, [1] = 0 }
    State.action_queue = {}
    State.profile_stats,State.profile_last_change,State.profile_pending_verify=nil,nil,nil
    State.achievement_bulk = nil
    State.award_completion = nil
    State.daily_caution = DEFAULT_DAILY_CAUTION
    State.weekly_caution = DEFAULT_WEEKLY_CAUTION
    State.hud_enabled, State.threshold_levels = false, {}
    State.persistence_status, State.persistence_stage = "PENDING", "INIT"
    State.persistence_error, State.persistence_failure_stage = nil, nil
    State.persistence_loaded, State.persistence_authoritative = false, false
    State.persistence_write_blocked = true
    State.history_dirty, State.earnings_dirty, State.persistence_dirty = false, false, false
    State.persistence_attempts, State.persistence_retry_at_ms = 0, nil
    State.account_id, State.account_name, State.account_verified = nil, nil, false
    State.account_error, State.last_account_check_ms = nil, -100000
    State.verified_events_since_start = 0
    State.attribution_epoch,State.attribution_slot=0,nil
    State.money_observation,State.money_identity_epoch,State.money_transfer_excluded=nil,0,false
    State.money_tracking_status="Waiting for a balance baseline"
    Module.Income.observer=nil;Module.Income.next_poll=nil;Module.Income.last_now=nil;Module.Income.Reset()
    Module.Settlement.pending={}
    State.tracking_session_id = timestamp_id() .. "-" .. tostring(tonumber(State.generation) or 0)
    State.transaction_status, State.last_money_refresh_ms = "IDLE", -100000
    State.last_tick_ms, State.generation = -100000, tonumber(State.generation) or 0
    update_cached_summary(epoch(), false)
    public_api = build_public_api()
    context.Modules.EconomyCore = Module
    context.CScript.Economy = public_api
end

-- Loader-owned pre-stop hook. This runs immediately after callback quiescing,
-- before any module Stop/Restore work can invalidate host path services.
function Module.PreStop(_, reason)
    return final_save(reason or "pre-stop")
end

function Module.Start(context)
    started = true
    local events = (context or module_context).Events
    local ok, err = events.RegisterTick("economy", "scheduler", tick)
    if not ok then error("Economy scheduler registration failed: " .. tostring(err)) end
    tick_registered = true
    events.RegisterSessionChange("economy", "session-change", function() invalidate("GTA session changed") end)
    attempt_persistence_bootstrap("START")
    log_info("Economy core started; rolling earnings tracking activates only after persistent history is authoritative.")
end

function Module.Stop()
    if Module.bank_transfer then Module.bank_transfer.Stop() end
    started = false
    if State and not final_save_attempted then final_save("stop-fallback") end
end

function Module.Restore(context)
    if Module.bank_transfer then Module.bank_transfer.Stop();Module.bank_transfer=nil end
    context = context or module_context
    started = false
    if context and context.Events and tick_registered then context.Events.UnregisterOwner("economy") end
    tick_registered = false
    if context and context.CScript and context.CScript.Economy == public_api then context.CScript.Economy = nil end
    if context and context.Modules and context.Modules.EconomyCore == Module then context.Modules.EconomyCore = nil end
    if context and context.State then context.State.Economy = {} end
    module_context, public_api, State = nil, nil, nil
    cached_paths, cached_file_api, final_save_completed = nil, nil, false
    final_save_attempted, emergency_save_attempted = false, false
end

return Module
