-- Enhanced 1158.13 Hangar cargo reserve.
-- Rooster deliveries and inventory-only clears update the aggregate; physical slots follow confirmed inventory.
local Module={Name="modules.hangar_pocket"}
local MAX=2147483647
local MAX_STEP=MAX
