-- physical-slot families (1..16). Both requests and reserve refill use these.
local TYPE_IDS={0,1,2,3,4,5,6,7}
local function integer(x,a,b)return type(x)=="number" and x==x and x%1==0 and x>=a and x<=b end
local function finite(v,lo,hi)return type(v)=='number'and v==v and v>=lo and v<=hi end
