-- gb_smuggler func1065..1069 and func1331 case230, owner/full delivery only.
-- Each conversion and arithmetic float operation follows the VM's binary32.
function Module.CalculateFullPayout(count,price)
 if not integer(count,0,50)or type(price)~='table'
  or not integer(price.unit_price,1,MAX)or not integer(price.bonus_step,1,50)
  or not finite(price.bonus_rate,0,10)or not finite(price.fee_rate,0,1)
  or not integer(price.fee_cap,0,MAX)or type(price.private_session)~='boolean'
  or not integer(price.eligible_rivals,0,32)or not integer(price.demand_cap,0,32)
  or not finite(price.demand_rate,0,100)then
  return nil,'Net payout requires readable current fees, session and rival pricing.'
 end
 local base=price.unit_price*count
 if not integer(base,0,MAX)then return nil,'Cargo base value exceeds the verified integer payout range.'end
 local steps=math.floor(f32(f32(count)/f32(price.bonus_step)))
 local bulk_rate=f32(f32(steps)*f32(price.bonus_rate))
 local bulk=round(f32(f32(base)*bulk_rate));local gross=base+bulk
