 local fee=round(math.min(f32(f32(gross)*f32(price.fee_rate)),f32(price.fee_cap)))
 if not integer(fee,0,gross)then return nil,'Current Ron fee cannot produce a verified net payout.'end
 local net=gross-fee;local percent=0
 if not price.private_session then percent=math.ceil(f32(f32(math.min(price.eligible_rivals,price.demand_cap))*f32(price.demand_rate)))end
 local demand=(net//100)*percent;local final=net+demand
