end
-- Target selected-category full-delivery earnings, retaining every existing crate.
function Module.PlanValueTarget(view,selected,target,price,completion)
 if type(view)~='table'or not integer(view.stock,0,50)or type(view.counts)~='table'
  or not integer(selected,1,8)or not integer(target,1,MAX)or type(price)~='table'then
  return nil,'Value targeting requires known physical cargo types and readable current prices.'
 end
 local total=0
 for i=1,8 do if not integer(view.counts[i],0,50)then return nil,'Cargo category inventory is unreadable.'end;total=total+view.counts[i]end
