  bonus_step=price.bonus_step,bonus_rate=price.bonus_rate,fee_rate=0,fee_cap=0,
  private_session=true,eligible_rivals=0,demand_rate=0,demand_cap=0}
 local current=view.counts[selected];local best,minimum,maximum
 for add=0,50-view.stock do
  local count=current+add;local value,detail=Module.CalculateFullPayout(count,price)
