  end
 end
 if target>maximum then
  -- A high desired payout is NOT invalid cargo. Plan the greatest achievable
  -- real inventory value at the current 50-slot Hangar capacity instead.
  -- Do not manufacture a GTA payout or bypass its physical cargo accounting.
  best.target_exceeds_capacity=true
  best.max_achievable_value=maximum
  return best
