 if target<minimum then
  -- Only the previous plan's independently re-read approximation may finish above target.
  local planned=type(completion)=='table' and completion.limit==view.stock and completion.estimated_value==minimum
  if not planned then
   return nil,('Selected cargo already estimates GTA$%d, above the GTA$%d target. Nothing removed.'):format(minimum,target)
