        local c=controller(s);if not c then return nil,'Rooster state unavailable; waiting for settlement.'end
        local settled=c.active==0 and c.quantity==-1 and c.type_id==-1 and (c.flags & 512)==0
        view.settled=settled
        view.complete=settled and c.stage==2 and view.coherent
        view.failed=settled and c.stage==3
        if settled then
            local restored,detail=patch.RestoreTicker()
            if not restored then return nil,detail end
        end
        return view
    end
    function host.SetRefillType(s,id)
        if not host.Valid(s) or not integer(id,0,7)then return false,'Cargo scope changed.'end
        local c=controller(s)
        if not c or c.active~=0 or c.stage~=2 or c.quantity~=-1 or c.type_id~=-1 or (c.flags & 768)~=0 or count('gb_smuggler')~=0 then
            return false,'A new source/sale operation appeared before refill metadata could be updated.'
        end
        local before=packed(18090,s.slot)
        if before~=0 then return false,'Refill hint changed outside this settled Rooster grant.'end
        local ok=pcall(n.InvokeVoid,0x1581503AE529CD2E,18090,id,s.slot)
        return ok and packed(18090,s.slot)==id,'Local refill hint readback failed.'
    end
    return host
end
local instance
function Module.Init(context)
    instance=Module.New(Module.MakeHost(context));context.CScript.HangarPocket=instance
    local function log(message)
        if context.Logger and context.Logger.Info then context.Logger.Info(message,'HangarPocket')end
    end
    for _,key in ipairs({'Configure','Start','FillToValue','Stop','OpenComputer','ClearCargo','StartSale'})do
        local original=instance[key]
        instance[key]=function(...)
            local ok,why=original(...)
            log(key..' ok='..tostring(ok)..' detail='..tostring(why or ''))
            return ok,why
        end
    end
    local original_tick=instance.Tick
    local last
    instance.Tick=function(now)
        original_tick(now)
        local s=instance.Snapshot();local message=tostring(s.phase)..' '..tostring(s.reason)..' action='..tostring(s.action.phase)..' '..tostring(s.action.reason)
        if message~=last then last=message;log(message..' stock='..tostring(s.stock)..' pending='..tostring(s.cleanup_pending))end
    end
end
function Module.Stop()
    if instance then instance.Stop()end
end
function Module.Restore(context)
    if instance then
        local ok,why=instance.ForceRelease()
        if not ok and context and context.Logger and context.Logger.Info then context.Logger.Info(tostring(why),'HangarPocket')end
    end
    if context and context.CScript then context.CScript.HangarPocket=nil end
    instance=nil
end
return Module
