["CScript/modules/heist_manager.lua"]=[====[
-- Single owner of Heist Tools selection, commands and cached presentation.
-- Prototype controllers own game behavior. Only Doomsday finish uses the preserved runtime.
local Module={Name='modules.heist_manager',MigrationPhase='17.75'}
local context_ref,public_api,router
local FAMILIES={apartment=true,cayo=true,casino=true,doomsday=true}
local ACTIONS={prepare='prepare',instant_finish='finish',solo_launch_toggle='solo',
 payout_auto='payout',payout_max='payout_once',bonus_toggle='bonus',
 board_refresh='board',cuts_apply='cuts',cuts_read='read_cuts',casino_cuts='casino_cuts'}
local function copy(value,seen,depth)
 if type(value)~='table'then return value end
 depth=(depth or 0)+1;assert(depth<=12,'Heist data nesting limit exceeded')
 seen=seen or {};assert(not seen[value],'Cyclic heist input');seen[value]=true
 local out={};for k,v in pairs(value)do
  assert(type(k)=='string'or type(k)=='number','Invalid heist field')
  assert(type(v)~='function'and type(v)~='thread'and type(v)~='userdata','Invalid heist value')
  out[k]=copy(v,seen,depth)
 end
 seen[value]=nil;return out
end
local function error_text(value)
 return tostring(value or 'Controller returned no result'):gsub('^.-:%d+:%s*','')
end
function Module.NewRouter(h)
 assert(type(h)=='table'and h.backend and type(h.backend.Execute)=='function','Heist backend required')
 assert(type(h.now)=='function'and type(h.context)=='function','Heist clock/context required')
 local backend=h.backend
 local active=false
 local family='apartment'
 local generation=1
 local queue,choices,models,results,views={}, {}, {}, {}, {}
 local observed,serial=nil,0
 local r={}
 local function now()
  local n=h.now();assert(type(n)=='number'and n==n and n>=0 and n<math.huge,'Heist clock unavailable')
  return n
 end
 local function describe(f)
  if not models[f]then
   local d=assert(backend.Describe(f),'Heist profile unavailable: '..f)
   models[f]=copy(d);choices[f]={}
   for _,selector in ipairs(d.selectors or {})do
    local option=(selector.options or {})[selector.default or 1]
    if option then choices[f][selector.key]=copy(option.value)end
   end
  end
  return models[f]
 end
 local function result(action,status,message)
  local value={family=action.family,action=action.command,status=status,message=error_text(message),id=action.id}
  results[action.family]=value
  if h.log then pcall(h.log,'route='..action.family..' action='..action.command..' status='..status..' '..value.message)end
  if h.notify and (status=='FAILED'or status=='EXPIRED'or status=='CANCELLED')then pcall(h.notify,value.message)end
  return value
 end
 local function cancel_all(reason)
  for _,a in ipairs(queue)do result(a,'CANCELLED',reason)end
  queue={}
 end
 local function option_valid(f,key,value)
  for _,selector in ipairs(describe(f).selectors or {})do
   if selector.key==key then
    for _,option in ipairs(selector.options or {})do
     if type(value)~='table'and option.value==value then return true end
    end
    return false
   end
  end
  return false
 end
 function r.Start()active=true;describe(family);return true end
 function r.SelectFamily(value)
  if not FAMILIES[value]then return false,'Unknown heist family.'end
  if family~=value then cancel_all('Heist selection changed before execution.');generation=generation+1 end
  family=value;describe(family);return true
 end
 function r.SetOption(key,value)
  if not option_valid(family,key,value)then return false,'Invalid selection for '..tostring(key)end
  choices[family][key]=value;return true
 end
 function r.QueueAction(key,args)
  if not active then return false,'Heist Tools are stopped.'end
  local command=ACTIONS[key]
  if not command then return false,'Unknown Heist Tools action: '..tostring(key)end
  if #queue>=8 then return false,'Heist action queue is full.'end
  local t=now()
  -- Expired entries cannot hold the duplicate-request lock forever.
  for i=#queue,1,-1 do
   if t<queue[i].created or t>queue[i].expires then
    local old=table.remove(queue,i);result(old,'EXPIRED','Request expired before execution. Press the action again.')
   end
  end
  for _,a in ipairs(queue)do
   if a.family==family and a.command==command then return false,'This action is already queued.'end
  end
  local ok,payload=pcall(copy,args or {})
  if not ok or type(payload)~='table'then return false,'Invalid heist action arguments.'end
  if command=='prepare'then
   local selection=payload.selection or choices[family]
   for k,v in pairs(selection)do if not option_valid(family,k,v)then return false,'Invalid prep option: '..tostring(k)end end
   payload.selection=copy(selection)
  elseif command=='solo'or command=='payout'or command=='bonus'then
   if type(payload.enabled)~='boolean'then return false,'Choose on or off.'end
   if command=='bonus'and family~='apartment'then return false,'The 12M Bonus belongs to Apartment heists.'end
  end
  local needs_context=command=='prepare'or command=='finish'or command=='cuts'or command=='board'
   or command=='casino_cuts'or command=='payout_once'
  if needs_context and not(observed and observed.online and type(observed.key)=='string')then
   return false,'Waiting for an observed GTA Online context.'
  end
  serial=serial+1
  queue[#queue+1]={id=serial,family=family,command=command,args=payload,
   generation=generation,created=t,expires=t+3000,context_key=needs_context and observed.key or nil}
  return true,serial
 end
 local function run(action)
  if action.command=='finish'and action.family=='doomsday'then
   assert(h.legacy and type(h.legacy.InstantFinish)=='function','Original Doomsday finish service unavailable')
   if type(h.legacy.TransactionReady)=='function'then
    local ready,why=h.legacy.TransactionReady();if ready~=true then return false,why end
   end
   -- Payout preparation cannot prevent the explicitly preserved finish operation.
   local prep_ok,ready,why=pcall(backend.Execute,'doomsday','before_finish',{})
   if (not prep_ok or ready==false)and h.log then pcall(h.log,'Doomsday payout preparation: '..tostring(prep_ok and why or ready))end
   return h.legacy.InstantFinish('doomsday')
  end
  return backend.Execute(action.family,action.command,action.args)
 end
 function r.TickRuntime()
  if not active then return end
  local t=now()
  if type(h.shared_tick)=='function'then
   local ok,why=pcall(h.shared_tick,t)
   if not ok and h.log then pcall(h.log,'Travel scheduler: '..tostring(why))end
  end
  local sampled,current=pcall(h.context)
  observed=sampled and type(current)=='table'and current or nil
  local action=table.remove(queue,1)
  if action then
   if t<action.created or t>action.expires then
    result(action,'EXPIRED','Request expired before execution. Press the action again.')
   elseif action.generation~=generation or action.family~=family or
    (action.context_key and (not observed or not observed.online or observed.key~=action.context_key))then
    result(action,'CANCELLED','Session, mission or selection changed before execution.')
   else
    -- Pop before calling: an exception never leaves a stuck queue entry.
    local ran,accepted,message=pcall(run,action)
    if not ran then result(action,'FAILED',accepted)
    elseif accepted~=true then result(action,'FAILED',message)
    else result(action,'ACCEPTED',message or 'Request accepted; game result unconfirmed.')end
   end
  end
  if type(backend.Tick)=='function'then
   local ok,why=pcall(backend.Tick)
   if not ok and h.log then pcall(h.log,'Controller tick error: '..tostring(why))end
  end
  if h.legacy and type(h.legacy.TickFinish)=='function'then
   local ok,why=pcall(h.legacy.TickFinish)
   if not ok and h.log then pcall(h.log,'Doomsday result monitor: '..tostring(why))end
  end
  local got,view=pcall(backend.Snapshot,family)
  if got and type(view)=='table'then views[family]=copy(view)end
 end
 function r.Snapshot()
  local d=describe(family)
  local v=copy(views[family] or {})
  v.selected_family=family;v.generation=generation;v.queued_actions=#queue
  v.selectors=copy(d.selectors or {});v.capabilities=copy(d.capabilities or {})
  v.selection=copy(choices[family]);v.last_result=copy(results[family])
  v.sources=copy(d.sources or {});v.controller_revision='RC3_SINGLE_OWNER'
  return v
 end
 function r.Invalidate(reason)
  generation=generation+1;cancel_all(reason or 'Session changed.');observed=nil
  if type(backend.OnSessionChange)=='function'then pcall(backend.OnSessionChange)end
 end
 function r.Stop()active=false;cancel_all('Heist Tools stopped.');observed=nil;return true end
 function r.Tick()return true end -- Account-gated legacy cadence has no command ownership.
 function r.TickApartmentActions()return true end
 function r.RequestVisibleRefresh()return true end
 function r.Refresh()return r.Snapshot()end
 function r.RefreshAll()return r.Snapshot()end
 function r.GetFinishActionResult(f)
  local v=results[f or family];return v and v.action=='finish'and copy(v)or nil
 end
 function r.GetApartmentActionResult()return copy(results.apartment)end
 function r.SelectWorkspace()return true end
 function r.SetAutoDiscovery()return true end
 return r
end
local function host_clock()
 local raw=context_ref and context_ref.Raw or {}
 local time=raw.Time or Time
 if time and type(time.GetEpocheMs)=='function'then return time.GetEpocheMs()end
 return math.floor(os.clock()*1000)
end
function Module.Init(context)
 assert(context and context.CScript and context.Modules and context.State,'Heist Tools context unavailable')
 context_ref=context
 local backend=assert(context.CScript.HeistPrototypes,'Replacement heist controllers were not loaded')
 router=Module.NewRouter{backend=backend,legacy=context.CScript.HeistRuntimeProfiles,
  now=host_clock,context=backend.Context,
  shared_tick=function(t)
   local teleports=context.CScript.Teleports
   if teleports and type(teleports.Tick)=='function'then teleports.Tick(t)end
  end,
  log=function(message)
   local logger=context.Raw and context.Raw.Logger or Logger
   if logger and logger.LogInfo then pcall(logger.LogInfo,'[CScript Heists RC3] '..message)end
  end,
  notify=function(message)
   local notifications=context.Notifications or context.CScript.Notifications
   if notifications and type(notifications.Warning)=='function'then pcall(notifications.Warning,message)end
  end}
 public_api=router
 context.CScript.Heists=public_api;context.Modules.HeistManager=Module
 if EventMgr and type(EventMgr.RegisterHandler)=='function'and eLuaEvent and eLuaEvent.ON_SESSION_CHANGE~=nil then
  EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE,function()
   if router then router.Invalidate('Session changed.')end
  end)
 end
end
function Module.Start()return router.Start()end
function Module.Stop()if router then return router.Stop()end;return true end
function Module.Restore(context)
 Module.Stop();context=context or context_ref
 if context and context.CScript and context.CScript.Heists==public_api then context.CScript.Heists=nil end
 if context and context.Modules and context.Modules.HeistManager==Module then context.Modules.HeistManager=nil end
 context_ref,public_api,router=nil,nil,nil;return true
end
return Module
]====],
["CScript/modules/heist_persistence.lua"]=[====[
-- CScript Heist Suite local preset persistence.
-- User data lives outside the replaceable runtime under CScriptData\Economy.
local Module = { Name = "modules.heist_persistence", MigrationPhase = "17.75" }

local module_context
local public_api
local State
local file_api
local paths

local HEADER = "CSCRIPT_HEIST_PRESETS_V1"
local EXPORT_HEADER = "CSCRIPT_HEIST_PRESET_EXPORT_V1"
local RECOVERY_PENDING = "CSCRIPT_HEIST_RECOVERY_V1\nPENDING"
local RECOVERY_COMPLETE = "CSCRIPT_HEIST_RECOVERY_V1\nCOMPLETE"

local function clean(value, maximum)
    value = tostring(value or ""):gsub("[%c]", " "):gsub("^%s+", ""):gsub("%s+$", "")
    return value:sub(1, maximum or 120)
end

local function current_provenance()
    local diagnostics = module_context and module_context.CScript and module_context.CScript.Diagnostics or {}
    return clean(diagnostics.LoaderVersion or "17.75", 80),
        clean(diagnostics.BuildId or "Unavailable", 120),
        clean(diagnostics.CompatibilityId or "gta-v-enhanced|cherax-v5.48.1-ee-be-b10713", 120)
end

local function now()
    if os and type(os.time) == "function" then
        local ok, value = pcall(os.time); if ok and tonumber(value) then return math.floor(value) end
    end
    return 0
end

local function identifier(prefix)
    State.sequence = (tonumber(State.sequence) or 0) + 1
    local stamp = tostring(now())
    local suffix = tostring(State.sequence)
    return clean((prefix or "preset") .. "-" .. stamp .. "-" .. suffix, 72):gsub("[^%w_-]", "_")
end

local function encode(value)
    return tostring(value or ""):gsub("([^%w%._%- ])", function(char) return ("%%%02X"):format(string.byte(char)) end)
end

local function decode(value)
    return tostring(value or ""):gsub("%%(%x%x)", function(hex) return string.char(tonumber(hex, 16)) end)
end

local function canonical(content)
    if type(content) ~= "string" then return nil end
    if content:sub(1, 3) == "\239\187\191" then content = content:sub(4) end
    local normalized = content:gsub("\r\n", "\n"):gsub("\r", "\n")
    return normalized -- Do not leak gsub's replacement count into a caller's arguments.
end

local function split(line)
    local result = {}
    for item in (tostring(line or "") .. "|"):gmatch("(.-)|") do result[#result + 1] = decode(item) end
    return result
end

local function capture_file_api()
    local files = module_context and module_context.Raw and module_context.Raw.FileMgr
    if not files then return false, "FileMgr is unavailable" end
    file_api = {
        GetMenuRootPath = files.GetMenuRootPath, CreateDir = files.CreateDir,
        DoesFileExist = files.DoesFileExist, ReadFileContent = files.ReadFileContent,
        WriteFileContent = files.WriteFileContent, FindFiles = files.FindFiles,
    }
    if type(file_api.GetMenuRootPath) ~= "function" or type(file_api.CreateDir) ~= "function"
        or type(file_api.DoesFileExist) ~= "function" or type(file_api.ReadFileContent) ~= "function"
        or type(file_api.WriteFileContent) ~= "function" then
        return false, "required FileMgr preset APIs are unavailable"
    end
    return true
end

local function ensure(path)
    local ok, result = pcall(file_api.CreateDir, path)
    -- Cherax returns false when a directory already exists; only a thrown call
    -- is a readiness failure. File operations provide the real verification.
    return ok, ok and nil or tostring(result)
end

local function resolve_paths()
    local ok, err = capture_file_api(); if not ok then return false, err end
    local root_ok, root = pcall(file_api.GetMenuRootPath)
    if not root_ok or type(root) ~= "string" or root == "" then return false, "Cherax menu root is unavailable" end
    root = root:gsub("[\\/]+$", "")
    local data = root .. "\\Lua\\CScriptData"
    local economy = data .. "\\Economy"
    local preset_root = economy .. "\\HeistPresets"
    local exports = preset_root .. "\\Exports"
    local snapshots = economy .. "\\HeistSnapshots"
    local diagnostics = economy .. "\\HeistDiagnostics"
    for _, directory in ipairs({ data, economy, preset_root, exports, snapshots, diagnostics }) do
        local created, create_err = ensure(directory); if not created then return false, create_err end
    end
    paths = {
        root = preset_root, main = preset_root .. "\\presets_v1.txt",
        backup = preset_root .. "\\presets_v1.txt.bak", exports = exports, snapshots = snapshots,
        recovery = preset_root .. "\\presets_v1.txt.recovery",
        diagnostics = diagnostics,
    }
    State.path = paths.main
    return true
end

local function exists(path)
    local ok, result = pcall(file_api.DoesFileExist, path)
    if not ok then return nil, tostring(result) end
    return result == true
end

local function read(path)
    local present, err = exists(path); if present == nil then return nil, err end
    if not present then return nil, "file does not exist" end
    local ok, content = pcall(file_api.ReadFileContent, path)
    if not ok or type(content) ~= "string" then return nil, tostring(content or "read failed") end
    return canonical(content)
end

local function write(path, content)
    local ok, result = pcall(file_api.WriteFileContent, path, tostring(content), false)
    if not ok or result == false then return false, tostring(result or "write rejected") end
    local verify, err = read(path)
    if canonical(verify) ~= canonical(content) then return false, "post-write verification failed: " .. tostring(err or "content mismatch") end
    return true
end

local function copy_values(values)
    local copy = {}
    for key, value in pairs(values or {}) do
        local number = tonumber(value)
        if type(key) == "string" and key:match("^[%w_]+$") and number and number == math.floor(number) then
            copy[key] = number
        end
    end
    return copy
end

local function copy_preset(preset)
    return {
        id = preset.id, name = preset.name, heist = preset.heist, character_slot = preset.character_slot,
        created = preset.created, modified = preset.modified, values = copy_values(preset.values),
        metadata = clean(preset.metadata, 160),
        runtime_version = clean(preset.runtime_version, 80), build_id = clean(preset.build_id, 120),
        compatibility_id = clean(preset.compatibility_id, 120),
    }
end

local function serialize(presets, header)
    local lines = { header or HEADER }
    for _, preset in ipairs(presets or {}) do
        lines[#lines + 1] = table.concat({ "preset", encode(preset.id), encode(preset.heist),
            encode(preset.character_slot), encode(preset.name), encode(preset.created), encode(preset.modified),
            encode(preset.metadata), encode(preset.runtime_version), encode(preset.build_id),
            encode(preset.compatibility_id) }, "|")
        local keys = {}; for key in pairs(preset.values or {}) do keys[#keys + 1] = key end; table.sort(keys)
        for _, key in ipairs(keys) do
            lines[#lines + 1] = table.concat({ "value", encode(preset.id), encode(key), encode(preset.values[key]) }, "|")
        end
    end
    return table.concat(lines, "\n")
end

local function parse(content, expected_header)
    content = canonical(content)
    local first = type(content) == "string" and content:match("^([^\n]+)") or nil
    if first ~= (expected_header or HEADER) then return nil, "preset header is invalid" end
    local records, by_id, first_line = {}, {}, true
    for line in content:gmatch("[^\n]+") do
        if first_line then first_line = false else
            local fields = split(line)
            if fields[1] == "preset" then
                local slot = tonumber(fields[4])
                local preset = {
                    id = clean(fields[2], 72), heist = clean(fields[3], 32), character_slot = slot,
                    name = clean(fields[5], 64), created = tonumber(fields[6]) or 0,
                    modified = tonumber(fields[7]) or 0, metadata = clean(fields[8], 160),
                    runtime_version = clean(fields[9], 80), build_id = clean(fields[10], 120),
                    compatibility_id = clean(fields[11], 120), values = {},
                }
                if preset.id == "" or preset.heist == "" or preset.name == "" or (slot ~= 0 and slot ~= 1) or by_id[preset.id] then
                    return nil, "preset record is invalid"
                end
                by_id[preset.id] = preset; records[#records + 1] = preset
            elseif fields[1] == "value" then
                local preset, key, value = by_id[fields[2]], fields[3], tonumber(fields[4])
                if not preset or not tostring(key):match("^[%w_]+$") or not value or value ~= math.floor(value) then
                    return nil, "preset value record is invalid"
                end
                preset.values[key] = value
            else return nil, "unknown preset record" end
        end
    end
    return records
end

local function parse_snapshot(content, path)
    content = canonical(content)
    if type(content) ~= "string" or content:match("^([^\n]+)") ~= "CSCRIPT_HEIST_SNAPSHOT_V1" then
        return nil, "snapshot header is invalid"
    end
    local snapshot, first_line = { stats = {}, path = path }, true
    for line in content:gmatch("[^\n]+") do
        if first_line then first_line = false else
            local fields = split(line)
            if fields[1] == "version" then snapshot.version = fields[2]
            elseif fields[1] == "time" then snapshot.time = tonumber(fields[2])
            elseif fields[1] == "slot" then snapshot.slot = tonumber(fields[2])
            elseif fields[1] == "family" then snapshot.family = fields[2]
            elseif fields[1] == "action" then snapshot.action = fields[2]
            elseif fields[1] == "stat" then
                local before, after = tonumber(fields[3]), tonumber(fields[4])
                if not before or not after then return nil, "snapshot stat value is invalid" end
                snapshot.stats[#snapshot.stats + 1] = { key = fields[2], before = before, after = after, label = fields[5] }
            end
        end
    end
    if snapshot.slot ~= 0 and snapshot.slot ~= 1 then return nil, "snapshot character slot is invalid" end
    if #snapshot.stats == 0 then return nil, "snapshot contains no stat records" end
    return snapshot
end

local function refresh_snapshots()
    State.snapshots = {}
    if not paths or not file_api or type(file_api.FindFiles) ~= "function" then return false, "FileMgr.FindFiles is unavailable" end
    local ok, found = pcall(file_api.FindFiles, paths.snapshots, ".snapshot", false)
    if not ok or type(found) ~= "table" then return false, tostring(found or "snapshot enumeration failed") end
    for _, item in pairs(found) do
        local path = tostring(item or "")
        if path ~= "" then
            if not path:find("[\\/]", 1) then path = paths.snapshots .. "\\" .. path end
            local parsed = parse_snapshot(read(path), path)
            if parsed then State.snapshots[#State.snapshots + 1] = parsed end
        end
    end
    table.sort(State.snapshots, function(a, b) return (a.time or 0) > (b.time or 0) end)
    return true
end

local function list_snapshots(family, slot)
    local result = {}
    for _, parsed in ipairs(State.snapshots or {}) do
        if (not family or parsed.family == family) and (slot == nil or parsed.slot == slot) then result[#result + 1] = parsed end
    end
    return result
end

local function load_snapshot(path)
    path = clean(path, 320)
    if not paths or path == "" or path:sub(1, #paths.snapshots):lower() ~= paths.snapshots:lower() then
        return nil, "snapshot path is outside CScriptData"
    end
    for _, item in ipairs(State.snapshots or {}) do if item.path == path then return item end end
    return nil, "snapshot is not present in the verified cache; refresh snapshots first"
end

local function recovery_pending()
    local present, err = exists(paths.recovery)
    if present == nil then return nil, "Preset recovery marker access failed: " .. tostring(err) end
    if not present then return false end
    local content, read_err = read(paths.recovery)
    if content == RECOVERY_PENDING then return true end
    if content == RECOVERY_COMPLETE then return false end
    return nil, "Preset recovery marker is unreadable: " .. tostring(read_err or "incomplete marker")
end

local function restore_primary(content)
    -- FileMgr has no atomic replacement in this module's API. Persist the
    -- recovery intent first so a restart cannot trust a partial valid primary.
    local ok, err = write(paths.recovery, RECOVERY_PENDING)
    if not ok then return false, "Could not protect preset recovery: " .. tostring(err) end
    ok, err = write(paths.main, content)
    if not ok then return false, "Primary restoration failed: " .. tostring(err) end
    ok, err = write(paths.recovery, RECOVERY_COMPLETE)
    if not ok then return false, "Primary verified, but recovery completion failed: " .. tostring(err) end
    return true
end

local function save()
    if not paths then return false, "preset storage is unavailable" end
    local pending, marker_err = recovery_pending()
    if pending == nil or pending and not State.backup_recovery_pending then
        State.status, State.error = "DEGRADED", marker_err or "Reload the recovered presets before saving."
        return false, State.error
    end
    local content = serialize(State.presets)
    -- A failed recovery can leave a syntactically valid but partial primary.
    -- Keep the verified backup until the recovered records are durably saved.
    if not State.backup_recovery_pending and exists(paths.main) == true then
        local previous = read(paths.main)
        if type(previous) == "string" and parse(previous) then
            local backup_ok, backup_err = write(paths.backup, previous)
            if not backup_ok then return false, "preset backup failed: " .. tostring(backup_err) end
        end
    end
    local ok, err
    if State.backup_recovery_pending then ok, err = restore_primary(content)
    else ok, err = write(paths.main, content) end
    State.status, State.error = ok and "READY" or "DEGRADED", ok and nil or err
    if ok then State.backup_recovery_pending = false end
    return ok, err
end

local function load()
    local ready, path_err = resolve_paths()
    if not ready then State.status, State.error = "DEGRADED", path_err; return false, path_err end
    local pending, marker_err = recovery_pending()
    if pending == nil then State.status, State.error = "DEGRADED", marker_err; return false, marker_err end
    local main_present, main_err = exists(paths.main)
    local content, read_err = read(paths.main)
    local loaded, parse_err = parse(content)
    if loaded and not pending and not State.backup_recovery_pending then
        State.presets, State.status, State.error = loaded, "READY", nil
        return true
    end
    local backup_present, backup_err = exists(paths.backup)
    if backup_present then
        local backup_content, backup_read_err = read(paths.backup)
        local recovered, backup_parse_err = parse(backup_content)
        if recovered then
            State.presets, State.backup_recovery_pending = recovered, true
            local ok, err = restore_primary(serialize(recovered))
            if not ok then
                State.status, State.error = "DEGRADED", "Recovered presets are available. " .. tostring(err)
                return false, State.error
            end
            State.backup_recovery_pending, State.status, State.error = false, "READY", nil
            return true
        end
        backup_err = backup_read_err or backup_parse_err
    elseif backup_present == false and main_present == false and not pending and not State.backup_recovery_pending then
        State.presets = {}
        local ok, err = write(paths.main, serialize(State.presets))
        State.status, State.error = ok and "READY" or "DEGRADED", ok and nil or err
        return ok, err
    end
    State.status, State.error = "DEGRADED", backup_err or main_err or read_err or parse_err or "Preset recovery is incomplete"
    return false, State.error
end

local function find(id)
    for index, preset in ipairs(State.presets or {}) do if preset.id == id then return preset, index end end
end

local function list(heist, slot)
    local result = {}
    for _, preset in ipairs(State.presets or {}) do
        if (not heist or preset.heist == heist) and (slot == nil or preset.character_slot == slot) then
            result[#result + 1] = copy_preset(preset)
        end
    end
    table.sort(result, function(a, b) return (a.modified or 0) > (b.modified or 0) end)
    return result
end

local function create(spec)
    if State.status ~= "READY" then return false, State.error or "preset storage is not ready" end
    spec = type(spec) == "table" and spec or {}
    local slot, heist, name = tonumber(spec.character_slot), clean(spec.heist, 32), clean(spec.name, 64)
    local values = copy_values(spec.values)
    if slot ~= 0 and slot ~= 1 then return false, "preset character slot is invalid" end
    if heist == "" or name == "" then return false, "preset heist and name are required" end
    if next(values) == nil then return false, "preset has no validated values" end
    local stamp = now()
    local current_runtime, current_build, current_compatibility = current_provenance()
    local preset = { id = identifier(heist), heist = heist, name = name, character_slot = slot,
        created = stamp, modified = stamp, metadata = clean(spec.metadata, 160), values = values,
        runtime_version = spec.runtime_version ~= nil and clean(spec.runtime_version, 80) or current_runtime,
        build_id = spec.build_id ~= nil and clean(spec.build_id, 120) or current_build,
        compatibility_id = spec.compatibility_id ~= nil and clean(spec.compatibility_id, 120) or current_compatibility }
    while find(preset.id) do preset.id = identifier(heist .. "_copy") end
    State.presets[#State.presets + 1] = preset
    local ok, err = save(); if not ok then table.remove(State.presets) return false, err end
    return true, copy_preset(preset)
end

local function rename(id, name)
    local preset = find(id); name = clean(name, 64)
    if not preset then return false, "preset was not found" end
    if name == "" then return false, "preset name is required" end
    local previous, modified = preset.name, preset.modified
    preset.name, preset.modified = name, now()
    local ok, err = save(); if not ok then preset.name, preset.modified = previous, modified end
    return ok, err
end

local function duplicate(id, name)
    local preset = find(id); if not preset then return false, "preset was not found" end
    return create({ heist = preset.heist, character_slot = preset.character_slot,
        name = clean(name, 64) ~= "" and name or (preset.name .. " Copy"), values = preset.values,
        metadata = preset.metadata, runtime_version = preset.runtime_version,
        build_id = preset.build_id, compatibility_id = preset.compatibility_id })
end

local function remove(id)
    local _, index = find(id); if not index then return false, "preset was not found" end
    local removed = table.remove(State.presets, index)
    local ok, err = save(); if not ok then table.insert(State.presets, index, removed) end
    return ok, err
end

local function export(id)
    local preset = find(id); if not preset then return false, "preset was not found" end
    local path = paths.exports .. "\\" .. clean(preset.id, 72):gsub("[^%w_-]", "_") .. ".heistpreset"
    local ok, err = write(path, serialize({ preset }, EXPORT_HEADER))
    return ok, ok and path or err
end

local function import(path)
    path = clean(path, 260)
    if path == "" then return false, "import path is required" end
    local loaded, err = parse(read(path), EXPORT_HEADER)
    if not loaded or #loaded ~= 1 then return false, err or "export must contain exactly one preset" end
    local preset = loaded[1]
    return create({ heist = preset.heist, character_slot = preset.character_slot,
        name = preset.name .. " (Imported)", values = preset.values, metadata = preset.metadata,
        runtime_version = preset.runtime_version, build_id = preset.build_id,
        compatibility_id = preset.compatibility_id })
end

local function write_diagnostic(filename, content)
    if State.status ~= "READY" or not paths or not paths.diagnostics then
        return false, State.error or "Heist diagnostics storage is not ready"
    end
    filename = tostring(filename or "")
    if not filename:match("^heist%-state%-%d+%-%d+%-%w+%.txt$") or filename:find("%.%.", 1, true) then
        return false, "Heist diagnostics filename is invalid"
    end
    local path = paths.diagnostics .. "\\" .. filename
    local ok, err = write(path, tostring(content or ""))
    return ok, ok and path or err
end

local function snapshot()
    return { status = State.status, error = State.error, path = State.path, count = #(State.presets or {}), presets = list(),
        snapshot_path = paths and paths.snapshots or nil,
        diagnostic_path = paths and paths.diagnostics or nil }
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table" or type(context.CScript) ~= "table" then
        error("modules.heist_persistence requires State and CScript services")
    end
    module_context = context
    file_api, paths = nil, nil
    State = context.State.HeistPersistence or {}
    context.State.HeistPersistence = State
    State.presets, State.snapshots, State.status, State.error, State.path = {}, {}, "PENDING", nil, nil
    State.backup_recovery_pending = false
    public_api = { StartLoad = load, Save = save, List = list, Find = function(id) local value = find(id); return value and copy_preset(value) end,
        Create = create, Rename = rename, Duplicate = duplicate, Delete = remove,
        Export = export, Import = import, RefreshSnapshots = refresh_snapshots,
        WriteDiagnostic = write_diagnostic,
        ListSnapshots = list_snapshots, LoadSnapshot = load_snapshot,
        Snapshot = snapshot, MigrationPhase = Module.MigrationPhase }
    context.Modules.HeistPersistence = Module
    context.CScript.HeistPersistence = public_api
end

function Module.Start()
    local ok, err = load()
    if ok then refresh_snapshots() end
    if module_context and module_context.Logger then
        local message = ("Heist preset persistence stage=START path=%s presets=%d status=%s%s"):format(
            tostring(State.path or "Unavailable"), #(State.presets or {}), tostring(State.status),
            err and (" error=" .. tostring(err)) or "")
        if ok then module_context.Logger.Info(message, "Heists") else module_context.Logger.Error(message, "Heists") end
    end
end

function Module.Restore(context)
    context = context or module_context
    if context and context.CScript and context.CScript.HeistPersistence == public_api then context.CScript.HeistPersistence = nil end
    if context and context.Modules and context.Modules.HeistPersistence == Module then context.Modules.HeistPersistence = nil end
    if context and context.State then context.State.HeistPersistence = {} end
    module_context, public_api, State, file_api, paths = nil, nil, nil, nil, nil
end

return Module
