   end
  end
  assert(#roster==s.party and seen[s.pid],'Mission crew is not ready.')
  s.roster=table.concat(roster,',')
 end)
 assert(s.host==true and nb(H.thread_active,s.thread)and ni(H.thread_host,s.thread)==s.pid,
  'Use Instant Finish as the current finale script host.')
 s.pointer=ScriptLocal.GetPtr(hash,p.root)
 assert(type(s.pointer)=='number'and s.pointer>=65536,'Mission locals are unavailable.')
 s.phase=li(hash,p.root);s.flags=li(hash,p.root+1);s.crew_flags=li(hash,p.root+3);s.gate=li(hash,p.root+4)
 s.teams=li(hash,p.teams);assert(s.teams>=1 and s.teams<=4,'Mission team count is unavailable.')
 s.identity=table.concat({epoch,s.pid,s.mission%4294967296,s.script,s.thread,s.pointer,s.roster},':')
 assert(ScriptLocal.GetPtr(hash,p.root)==s.pointer,'Mission allocation changed.')
