 for _,pattern in ipairs(assert(SIGNATURES[s.script]))do
  local ptr=Memory.ScanScript(s.hash,pattern)
  assert(type(ptr)=='number'and ptr>=65536,'This controller does not match the verified Enhanced build.')
  local offset=0
  for byte in pattern:gmatch('%x%x')do
   assert(Memory.ReadUByte(ptr+offset)==tonumber(byte,16),'Script code changed during verification.')
   offset=offset+1
