end
local function no_failure(s)
 for team=0,3 do assert(not has(s.flags,20+team),'GTA recorded a failed team. Restart the finale.')end
 assert(not has(s.crew_flags,31),'GTA recorded an invalid crew result.')
 if s.family=='cayo'then
  assert(not has(s.crew_flags,26),'GTA recorded an invalid crew result.')
  for team=0,s.teams-1 do assert(li(s.hash,s.p.pending_failure+team)==0,'A team failure is already queued.')end
 end
end
local function active(s)
 assert(s.phase==s.p.phase and has(s.flags,17)and has(s.flags,19)and not has(s.flags,16),
  'Wait until the finale has started and the objectives are active.')
 no_failure(s);assert(not has(s.gate,11),'The mission already has an end request.')
end
local function plan(s)
 active(s)
 local fields,guards={},{}
 local function add(index,old,new)
  assert(integer(old)and integer(new),'Mission score is outside the supported range.')
  guards[#guards+1]={index=index,old=old}
  if old~=new then fields[#fields+1]={index=index,old=old,value=new}end
 end
 local flags,occupied=s.flags,0
 for team=0,s.teams-1 do
  if has(s.flags,team)then
   occupied=occupied+1
   local stage=li(s.hash,s.p.stage+team)
   assert(stage>=0 and(stage<=17 or stage==99999),'Mission objective stage is unreadable.')
   guards[#guards+1]={index=s.p.stage+team,old=stage}
   local score=li(s.hash,s.p.score+team);local goal=gi(4722490+team*26988)
   guards[#guards+1]={index=4722490+team*26988,old=goal,global=true}
   assert(score>=0 and goal>=-1,'Mission goal is unreadable.')
   local players=li(s.hash,s.p.players+team)
   assert(players>=0 and players<=32,'Mission team roster is unreadable.')
   guards[#guards+1]={index=s.p.players+team,old=players}
   if goal==-1 then goal=math.max(1,players)elseif goal==0 then goal=1 end
   local delta=math.max(0,goal-score)
   -- Match FMC 767/768 or FMC2020 955/809: total, earned and stage score.
   add(s.p.score+team,score,score+delta)
   local bonus=li(s.hash,s.p.bonus_score+team);assert(bonus>=0,'Earned score is unreadable.')
   add(s.p.bonus_score+team,bonus,bonus+delta)
   if stage<17 then
    local current=li(s.hash,s.p.stage_score+team);assert(current>=0,'Stage score is unreadable.')
    add(s.p.stage_score+team,current,current+delta)
   end
  end
  flags=flags|(1<<(9+team))
 end
 assert(occupied>0,'Mission teams have not become active yet.')
 add(s.p.root+1,s.flags,flags)
 -- Publish the source-defined result gate last; GTA owns result processing.
 add(s.p.root+4,s.gate,s.gate|(1<<11))
 return fields,guards
end
local function new_controller(h)
 local pending,last=nil,'IDLE: No finish request submitted.'
 local c={}
 local function trace(s,reason)
  if not s then log(reason);return end
  log(reason..' heist='..s.name..' script='..s.script..' mission='..s.mission..' pid='..s.pid
   ..' thread='..s.thread..' ptr='..s.pointer..' crew='..s.party..' roster='..s.roster..' teams='..s.teams
   ..' phase='..s.phase..' flags='..s.flags..' gate='..s.gate..' crew_flags='..s.crew_flags)
 end
 local function same(s)
  local ok,fresh=pcall(h.capture)
  if ok and fresh.identity==s.identity and fresh.teams==s.teams then return fresh end
 end
 local function rollback(tx)
  local current=tx and same(tx.context)
  if not current then return 'context changed; old values were not replayed' end
  if current.phase~=current.p.phase or has(current.flags,16)then return 'GTA owns result processing' end
  local restored,conflicts,failed=0,0,0
  for n=#tx.attempted,1,-1 do
   local f=tx.attempted[n]
   local ok=pcall(function()
    local fresh=assert(same(tx.context),'Context changed during cleanup.')
    assert(fresh.phase==fresh.p.phase and not has(fresh.flags,16),'GTA owns result processing.')
    if li(fresh.hash,f.index)==f.value then
     ScriptLocal.SetInt(fresh.hash,f.index,f.old)
     assert(same(tx.context),'Context changed during cleanup write.')
     assert(li(fresh.hash,f.index)==f.old,'Cleanup readback failed.')
     restored=restored+1
    elseif li(fresh.hash,f.index)~=f.old then conflicts=conflicts+1 end
   end)
   if not ok then failed=failed+1 end
  end
  return 'cleanup restored='..restored..' external='..conflicts..' unresolved='..failed
 end
 function c.Request()
  if pending then return false,'A finish request is already being observed.'end
  local s,tx
  local ok,why=pcall(function()
   s=h.capture();active(s);h.verify(s)
   local fresh=assert(same(s),'Mission changed during verification.');active(fresh)
   assert(fresh.flags==s.flags and fresh.gate==s.gate and fresh.crew_flags==s.crew_flags,'Mission state changed during verification.')
   local fields,guards=plan(s)
   tx={context=s,attempted={},started=h.now(),stamp=''}
   local expected={};for _,f in ipairs(guards)do expected[f.index]=f.old end
   trace(s,'submit')
   for _,f in ipairs(fields)do
    local current=assert(same(s),'Mission changed before submission.')
    assert(current.phase==s.p.phase and not has(current.flags,16),'GTA already started result processing.')
    no_failure(current)
    for _,guard in ipairs(guards)do
     local current_value=guard.global and gi(guard.index)or li(s.hash,guard.index)
     assert(current_value==expected[guard.index],'Mission data changed before submission.')
    end
    tx.attempted[#tx.attempted+1]=f
    ScriptLocal.SetInt(s.hash,f.index,f.value)
    assert(same(s),'Mission changed during a result write.')
    assert(li(s.hash,f.index)==f.value,'GTA rejected a result write.')
    expected[f.index]=f.value
    log('write index='..f.index..' before='..f.old..' submitted='..f.value)
   end
   pending=tx
  end)
  if not ok then
   last='UNAVAILABLE: '..clean(why)..(tx and(' ('..rollback(tx)..').')or'')
   trace(s,last);return false,last
  end
  last='SUBMITTED: '..s.name..'. Waiting for GTA result processing.'
  if s.family=='cayo'or s.family=='casino'then
   last=last..' Settlement uses the loot already earned.'
  end
  return true,last
 end
 function c.Tick()
  if not pending then return nil end
  local tx=pending;local s=same(tx.context)
  if not s then
   pending=nil;last='UNCONFIRMED: Mission, host or crew changed before a result was observed.'
   log(last);return false,last
  end
  local stamp=s.phase..':'..s.flags..':'..s.gate..':'..s.crew_flags
  if stamp~=tx.stamp then trace(s,'observe');tx.stamp=stamp end
  local valid=pcall(no_failure,s)
  if not valid then
   pending=nil;last='FAILED: GTA recorded a team or crew failure. Check the result screen.'
   trace(s,last);return false,last
  end
  if s.phase==s.p.result and has(s.flags,16)then
   pending=nil;last='PROCESSING: GTA entered the result stage; heist pass and payment are NOT confirmed.'
   trace(s,last);return true,last
  end
  local now=h.now()
  if now<tx.started or now-tx.started>=20000 then
   pending=nil;last='UNCONFIRMED: No result stage observed after 20 seconds ('..rollback(tx)..').'
   trace(s,last);return false,last
  end
  return nil
 end
 function c.ReportBlocked(message)
  -- Request history only: a preflight refusal must survive Show Status.
  -- Preserve an already pending observation and its eventual result.
  if not pending then last='BLOCKED: '..clean(message)end
  return last
 end
 function c.Status()return last end
 function c.ShowStatus()
  local ok,s=pcall(h.capture)
  if ok then
   trace(s,'status')
   pcall(function()
    for team=0,s.teams-1 do
     assert(same(s),'Mission changed during status capture.')
     log('team='..team..' players='..li(s.hash,s.p.players+team)..' stage='..li(s.hash,s.p.stage+team)
      ..' score='..li(s.hash,s.p.score+team)..' earned='..li(s.hash,s.p.bonus_score+team)
      ..' goal='..gi(4722490+team*26988))
    end
   end)
  else log('status unavailable: '..clean(s))end
  return last
 end
 function c.Stop(changed)
  if changed then epoch=epoch+1 end
  if pending then
   last='UNCONFIRMED: Observation stopped ('..(changed and'context invalidated' or rollback(pending))..').'
   log(last)
  end
  pending=nil
 end
 return c
end
local controller=new_controller(host)
return {Controller=controller,Host=host,NewController=new_controller,
 Profiles=PROFILES,Signatures=SIGNATURES}
end)()

