 for _,row in ipairs(ROWS)do
  local known=gi(row[1])
  if known~=0 and known%4294967296==hash%4294967296 then
   assert(not found or found.name==row[2] and found.family==row[3],'Finale identity is ambiguous.');found={name=row[2],family=row[3]}
  end
