 if not s.session then return s end
 s.activity=nb(0x05095437424397FA) -- NETWORK_IS_ACTIVITY_SESSION
 s.total=ni(0xCF61D4B4702EE9EB) -- NETWORK_GET_TOTAL_NUM_PLAYERS
 assert(s.total>=0 and s.total<=32,'Network player count is unavailable.')
 s.pid=ni(0x4F8644AF03D0E0D6);assert(s.pid>=0 and s.pid<=31,'Player is unavailable.')
 s.mission=gi(4858023)
 s.classic=ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller'))
 s.modern=ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller_2020'))
 s.v3=ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fm_mission_controller_v3'))
 s.launchers=ni(0x2C83A9DA6BFFC4F9,Utils.Joaat('fmmc_launcher'))
 assert(s.classic>=0 and s.classic<=1 and s.modern>=0 and s.modern<=1 and s.launchers>=0 and s.launchers<=1 and s.v3>=0 and s.v3<=1 and s.classic+s.modern+s.v3<=1,'Script instance counts are ambiguous.')
