-- A lobby participant slot / session epoch is not a durable mission identity.
-- Reacquire the CURRENT own-host finale instead of reviving an old lobby pointer.
function host.recovery_current(s)
 local ok,fresh=pcall(function()
  local w=host.world()
  assert(w.session and w.activity and w.total==1 and w.classic==1
   and w.modern==0 and w.v3==0 and w.epoch==s.epoch
   and w.pid==s.pid and w.mission==s.mission,'Doomsday activity changed.')
  local c=InstantFinish.Host.capture()
  assert(c.identity==s.identity and c.host==true and c.party==1 and c.teams==1
   and c.family=='doomsday' and c.script=='fm_mission_controller',
   'Current Doomsday controller changed.')
  assert(c.phase==c.p.phase and bit(c.flags,17) and bit(c.flags,19)
   and not bit(c.flags,16),'Doomsday is not in active gameplay.')
  for team=0,3 do assert(not bit(c.flags,20+team),'Doomsday already has a failed team.')end
  assert(not bit(c.crew_flags,31),'Doomsday has an invalid crew result.')
