function host.recover_mission(expected)
 local w=host.world()
 assert(w.session and w.activity and w.total==1 and w.classic==1
  and w.modern==0 and w.v3==0,'Waiting for the current solo Doomsday activity.')
 local c=InstantFinish.Host.capture()
 assert(c.family=='doomsday' and c.script=='fm_mission_controller'
  and c.host==true and c.party==1 and c.teams==1,'Not an own-host solo Doomsday finale.')
 assert(not expected or expected.identity==c.identity,'Selected finale changed before recovery.')
 c.epoch=w.epoch
 assert(c.pid==w.pid and c.mission==w.mission,'Doomsday mission identity is changing.')
 assert(host.recovery_current(c),'Current Doomsday state could not be revalidated.')
 InstantFinish.Host.verify(c)
 assert(host.recovery_current(c),'Current Doomsday changed during verification.')
