end
local function make_plan(h,s)
 assert(s.solo,'Waiting for exactly one player in your hosted lobby.')
 if s.family=='cayo'then return {}end -- The game already supports solo Cayo; no minimum writes.
 assert(s.family=='casino' or s.family=='doomsday','Unknown finale family.')
 assert(s.role==0,'Select the first role/team for the solo host.')
 assert(s.teams==1,'Waiting for a supported single-team finale; team definitions are preserved.')
 local fields={}
 local function add(kind,index,value,minimum,maximum,catalogue)
  local old=h.read(kind,index,s)
  assert(integer(old) and old>=minimum and old<=maximum,'A player or crew minimum is not ready.')
  fields[#fields+1]={kind=kind,index=index,old=old,value=value,catalogue=catalogue,owned=false}
 end
 add('g',4722361,1,1,4) -- Global_4718592.f_3769, overall minimum.
 add('l',20211,1,1,4) -- iLocal_20196.f_15, invite-lobby copy.
 for team=0,s.teams-1 do
  add('g',4722368+team,team==0 and 1 or 0,0,4)
  local crew=h.read('g',4915256+team,s)
  assert(integer(crew) and (crew==11 or crew>=0 and crew<=4),'Controller crew minimum is not ready.')
  add('g',4915256+team,0,0,11)
 end
 -- trcmn role minima are independent of tcmin. Zero means no absent role
 -- can invalidate admission; role definitions/objectives themselves stay intact.
 if bit(h.read('g',4718606,s),6)then
  for team=0,s.teams-1 do for role=0,3 do add('g',4915262+team*5+role,0,0,4)end end
 end
 add('g',4722364,1,1,4) -- Default active team count.
 add('g',4722366,1,0,4) -- Minimum team count.
 add('g',4722365,1,1,4) -- Defined count: loader otherwise resets the default.
 add('g',s.catalogue.index,1,1,4,s.catalogue)
 if s.metadata then add('g',1048584,1,1,4)end
 return fields
end
local function is_mission(w,t)
 return w.v3==0 and (t.context.family=='cayo' and w.modern==1 and w.classic==0
  or t.context.family~='cayo' and w.classic==1 and w.modern==0)
end
local function new_controller(h)
 local enabled,transaction=false,nil
 local latest='OFF: Enable before opening a heist finale lobby.'
 local c={}
 local function status(text)if latest~=text then latest=text;log(text)end;return text end
 local function world()local ok,w=pcall(h.world);return ok and w or nil end
 local function current(t)
  local ok,s=pcall(h.lobby)
  if ok and s.identity==t.context.identity then return s end
 end
 local function scope(t,w)
  return w and w.session and w.pid==t.context.pid and w.epoch==t.context.epoch
 end
 local function restore(t,catalogue_only)
  local w=world()
  if not scope(t,w)then return true end
  local s=current(t)
  local matching=w.mission==t.context.mission
  local cancelled=w.mission==0 and w.classic==0 and w.modern==0 and w.v3==0 and w.launchers==0
  -- Don't restore the two-player admission contract when the mission thread
  -- disappears but GTA is still in the activity/result transition.
  local no_controller=w.classic==0 and w.modern==0 and w.v3==0
  local in_original_lobby=not t.mission_seen and matching and no_controller
   and (w.launchers==0 or s~=nil)
  local after_activity=t.mission_seen and not w.activity and no_controller
   and w.launchers==0 and (matching or cancelled)
  local ordinary=not catalogue_only and (in_original_lobby or after_activity)
  local all=true
  for n=#t.fields,1,-1 do
   local f=t.fields[n]
   if f.owned then
    local eligible=f.catalogue and (matching or cancelled) and (is_mission(w,t) or w.classic==0 and w.modern==0 and w.v3==0 and (w.launchers==0 or s~=nil))
     or not f.catalogue and ordinary and (f.kind~='l' or s~=nil)
    if eligible then
     local ok=pcall(function()
      local fresh=world();assert(scope(t,fresh),'Restoration context changed.')
      local cancelled_now=fresh.mission==0 and fresh.classic==0 and fresh.modern==0 and fresh.v3==0 and fresh.launchers==0
      assert(fresh.mission==t.context.mission or cancelled_now and f.kind=='g' or f.catalogue and cancelled_now,'Job changed during restoration.')
      if f.catalogue then
       assert(is_mission(fresh,t) or fresh.classic==0 and fresh.modern==0 and fresh.v3==0 and (fresh.launchers==0 or current(t)),
        'Controller changed during catalogue restoration.')
       if not h.catalogue_matches(f.catalogue)then f.owned=false;return end
      else
       assert(fresh.classic==0 and fresh.modern==0 and fresh.v3==0 and (fresh.launchers==0 or current(t)),
        'A new mission started during restoration.')
       if f.kind=='l'then assert(current(t),'Launcher instance changed.')end
      end
      if h.read(f.kind,f.index,t.context)==f.value then
       h.write(f.kind,f.index,f.old,t.context)
       assert(h.read(f.kind,f.index,t.context)==f.old,'Restoration readback failed.')
      end
      f.owned=false
     end)
     all=all and ok
    end
   end
  end
  return all
 end
 -- Recover only on an explicit Instant Finish request. No stale catalogue row,
 -- launcher local, or pre-transition player slot is copied into the new context.
 local function recover_contract(expected)
  if not enabled then return false,'Enable Solo Launch before starting Doomsday.'end
  if type(h.recover_mission)~='function' or type(h.recovery_current)~='function'then
   return false,'Current-mission recovery is unavailable.'
  end
  local t
  local ok,why=pcall(function()
   local s=h.recover_mission(expected)
   assert(s and s.family=='doomsday' and s.host==true and s.party==1 and s.teams==1,
    'Recovery needs your own single-player Doomsday finale.')
   local w=world()
   assert(w and w.session and w.activity and w.total==1 and w.classic==1
    and w.modern==0 and w.v3==0 and w.pid==s.pid and w.epoch==s.epoch
    and w.mission==s.mission,'Recovery activity identity changed.')
   local fields={}
   local function add(index,value,minimum,maximum)
    local before=h.read('g',index,s)
    assert(integer(before) and before>=minimum and before<=maximum,
     'Doomsday admission input is unavailable: '..index)
    fields[#fields+1]={kind='g',index=index,old=before,value=value,owned=false}
   end
   -- Same global admission fields as make_plan(), snapshotted afresh here.
   add(4722361,1,1,4)
   add(4722368,1,0,4)
   local crew=h.read('g',4915256,s)
   assert(integer(crew) and (crew==11 or crew>=0 and crew<=4),'Doomsday crew minimum is invalid.')
   add(4915256,0,0,11)
   if bit(h.read('g',4718606,s),6)then
    for role=0,3 do add(4915262+role,0,0,4)end
   end
   add(4722364,1,1,4)
   add(4722366,1,0,4)
   add(4722365,1,1,4)
   assert(h.recovery_current(s),'Doomsday changed before admission recovery.')
   t={context=s,fields=fields,reapplications=0,started=h.now(),mission_seen=true,
    recovered=true,attempted={}}
   -- All validation and reads have finished before the first write.
   for _,f in ipairs(fields)do
    assert(h.recovery_current(s),'Doomsday changed during admission recovery.')
    assert(h.read('g',f.index,s)==f.old,'Admission value changed before recovery: '..f.index)
    if f.old~=f.value then
     f.owned=true;t.attempted[#t.attempted+1]=f
     h.write('g',f.index,f.value,s)
     assert(h.recovery_current(s),'Doomsday changed after admission recovery write.')
     assert(h.read('g',f.index,s)==f.value,'Doomsday recovery readback failed: '..f.index)
    end
   end
   transaction=t
  end)
  if not ok then
   -- Undo a partial apply only in this exact, freshly captured live context.
   -- When that context is gone, do not replay snapshots into a different job.
   if t then
    for n=#t.attempted,1,-1 do
     local f=t.attempted[n]
     pcall(function()
      assert(h.recovery_current(t.context),'Recovery rollback context ended.')
      if h.read('g',f.index,t.context)==f.value then
       h.write('g',f.index,f.old,t.context)
      end
     end)
    end
   end
   log('DOOMSDAY_REBIND_FAILED '..tostring(why))
   return false,'Current solo Doomsday admission recovery failed: '..reason(why)
  end
  log('DOOMSDAY_CONTRACT_REBOUND current_pid='..t.context.pid
   ..' epoch='..t.context.epoch..' mission='..t.context.mission
   ..' thread='..t.context.thread..' fields='..#t.fields..' old_launcher_locals_replayed=false')
  return true,'Current solo Doomsday contract revalidated.'
 end
 -- fmmc_launcher checks its own minimum again during/after transition. Keep
 -- only the already-owned global values, and never rewrite an unrelated job.
 local function hold_doomsday_minima(t,w)
  if t.context.family~='doomsday' or w.activity~=true or w.total~=1 or w.mission~=t.context.mission then return end
  local ok,why=pcall(function()
   for _,f in ipairs(t.fields)do
    if f.owned and f.kind=='g' and (not f.catalogue or h.catalogue_matches(f.catalogue)) then
     local v=h.read('g',f.index,t.context)
     if v==f.old then
      assert(t.reapplications<32,'Repeated Doomsday minimum resets; refusing to keep writing.')
      h.write('g',f.index,f.value,t.context)
      t.reapplications=t.reapplications+1
      log('DOOMSDAY_MIN_REAPPLIED index='..f.index..' from='..v..' to='..f.value)
     elseif v~=f.value then
      error('Doomsday minimum edited elsewhere index='..f.index..'; refusing overwrite.')
     end
    end
   end
  end)
  if not ok and why~=t.last_hold_error then t.last_hold_error=why;log('DOOMSDAY_MIN_WARNING '..tostring(why))end
 end
 -- The launcher has a separate insufficient-players decision in
 -- fmmc_launcher func_10906: uLocal_17871.f_421 < iLocal_20196.f_15.
 -- This check is independent of fm_mission_controller's f_874 abort bit.
 -- During the EXACT original active finale, observe the current launcher
 -- locals and only reapply the owned minimum if the launcher resets it to 2.
 -- Never write into an unrelated job, another crew, or an unloaded script.
 local function watch_doomsday_launcher(t,w)
  if not t or t.context.family~='doomsday' or not t.mission_seen
   or not w.session or not w.activity or w.total~=1 or w.classic~=1
   or w.launchers~=1 or w.modern~=0 or w.v3~=0
   or w.pid~=t.context.pid or w.epoch~=t.context.epoch
   or w.mission~=t.context.mission then return end
  local ok,why=pcall(function()
   local hash=Utils.Joaat('fmmc_launcher')
   local ptr=ScriptLocal.GetPtr(hash,20211)
   assert(type(ptr)=='number'and ptr>=65536,'Launcher allocation is unavailable.')
   if t.watch_launcher_ptr~=ptr then
    h.verify({hash=hash})
    assert(ScriptLocal.GetPtr(hash,20211)==ptr,'Launcher allocation changed while verifying.')
    t.watch_launcher_ptr=ptr
    t.watch_launcher_writes=0
    t.watch_launcher_stamp=nil
    log('DOOMSDAY_LAUNCHER_NEW allocation='..ptr..' original_lobby_allocation='..tostring(t.context.pointer))
   end
   local minimum=li(hash,20211) -- iLocal_20196.f_15
   local current=li(hash,17871+421) -- uLocal_17871.f_421, current count
   local initial=li(hash,17871+420) -- uLocal_17871.f_420, earlier count
   local mode=gi(4718592)
   local reason=h.read('g',2690054,t.context)
   local stamp=table.concat({minimum,current,initial,mode,reason,w.classic,w.launchers},':')
   if stamp~=t.watch_launcher_stamp then
    log('DOOMSDAY_LAUNCHER_WATCH min_f15='..minimum..' current_f421='..current
     ..' previous_f420='..initial..' mode='..mode..' kick_reason3930='..reason
     ..' finish_requested='..tostring(t.finish_requested~=nil))
    t.watch_launcher_stamp=stamp
   end
   local owned_local=false
   for _,f in ipairs(t.fields)do
    if f.kind=='l' and f.index==20211 and f.owned and f.value==1 then
     owned_local=true;break
    end
   end
   -- The recovered contract intentionally has no old launcher-local field.
   -- It can still use this readout, but must not write an unowned one.
   if t.finish_requested and owned_local and mode==0 and current==1
     and minimum==2 then
    assert((t.watch_launcher_writes or 0)<4,'Repeated launcher resets: refusing further writes.')
    assert(ScriptLocal.GetPtr(hash,20211)==ptr,'Launcher changed before write.')
    ScriptLocal.SetInt(hash,20211,1)
    assert(ScriptLocal.GetPtr(hash,20211)==ptr and li(hash,20211)==1,
     'Launcher ignored minimum readback.')
    t.watch_launcher_writes=(t.watch_launcher_writes or 0)+1
    log('DOOMSDAY_LAUNCHER_MIN_REAPPLIED old=2 new=1 current_crew=1'
     ..' writes='..t.watch_launcher_writes)
   end
  end)
  if not ok and why~=t.watch_launcher_error then
   t.watch_launcher_error=why
   log('DOOMSDAY_LAUNCHER_WARNING '..tostring(why))
  end
 end
 -- Enhanced classic controller cleanup has an independent count<2 branch:
 -- fm_mission_controller func_19111 -> Global_2685155.f_874; on >=2 it calls
 -- func_19110 -> f_875. In fmmc_launcher func_13724, f_874 selects its abort
 -- transition. Guarded prototype mirrors the >=2 handoff *only* after our
 -- own successful Doomsday result request, not during regular mission play.
 local function observe_doomsday_result(t,w)
  if t.context.family~='doomsday' or not t.finish_requested or not t.mission_seen
   or not w.activity or w.total~=1 or h.now()-t.finish_requested>90000 then return end
  local ok,why=pcall(function()
   local abort=h.read('g',2686029,t.context) -- Global_2685155.f_874
   local proceed=h.read('g',2686030,t.context) -- Global_2685155.f_875
   local reason=h.read('g',2690054,t.context) -- Global_2686124.f_3930
   assert((abort==0 or abort==1) and (proceed==0 or proceed==1),'Unknown Doomsday handoff flags.')
   local stamp=abort..':'..proceed..':'..reason..':'..w.classic..':'..w.launchers
   if stamp~=t.last_result_stamp then
    log('DOOMSDAY_RESULT_MONITOR total='..w.total..' activity='..tostring(w.activity)
     ..' abort874='..abort..' proceed875='..proceed..' launcher_reason3930='..reason
     ..' controller='..w.classic..' launcher='..w.launchers)
    t.last_result_stamp=stamp
   end
   if abort==1 then
    if proceed==0 then
     h.write('g',2686030,1,t.context)
    end
    h.write('g',2686029,0,t.context)
    log('DOOMSDAY_SOLO_HANDOFF corrected one-player abort flags after own result request; settlement unverified')
   end
  end)
  if not ok and why~=t.last_result_error then t.last_result_error=why;log('DOOMSDAY_RESULT_WARNING '..tostring(why))end
 end
 local function apply(s)
  local verified,why=pcall(h.verify,s)
  if not verified then enabled=false;return status('FAILED: '..reason(why))end
  local ready,fields=pcall(make_plan,h,s)
  if not ready then return status('WAITING: '..reason(fields))end
  local t={context=s,fields=fields,reapplications=0,started=h.now()}
  local ok,why=pcall(function()
   transaction=t
   for _,f in ipairs(t.fields)do
    local fresh=assert(current(t),'Launcher changed during solo admission.')
    assert(fresh.solo and fresh.role==0 and fresh.metadata==s.metadata and (fresh.family=='cayo' or fresh.teams==1),'The lobby crew, role or metadata changed.')
    assert(h.read(f.kind,f.index,s)==f.old,'A minimum changed before application.')
    if f.old~=f.value then
     f.owned=true -- Include setters that mutate then throw.
     h.write(f.kind,f.index,f.value,s)
     assert(current(t),'Launcher changed after a minimum write.')
     assert(h.read(f.kind,f.index,s)==f.value,'Solo minimum readback failed.')
    end
   end
  end)
  if not ok then
   enabled=false
   local restored=restore(t,false)
   if restored then transaction=nil end
   return status('FAILED: '..reason(why)..(restored and '' or ' Restoration is pending.'))
  end
  if s.family=='cayo'then return status('NATIVE SOLO: Cayo Perico already supports one player. Start normally; no minima changed.')end
  log('applied heist='..s.name..' mission='..s.mission..' thread='..s.thread..' fields='..#t.fields)
  return status('APPLIED: Solo admission settings are active. Start the finale normally.')
 end
 function c.SetEnabled(value)
  value=value==true
  if enabled==value then return true,latest end
  enabled=value
  if enabled then return true,status('ON: Solo Launch enabled for your next hosted finale lobby.')end
  local t=transaction
  if t then
   local w=world()
   if not scope(t,w) or w.mission~=t.context.mission then restore(t,true);transaction=nil
   elseif is_mission(w,t) or t.mission_seen and w.activity then
    t.mission_seen=true
    if not (t.context.family=='doomsday' and w.activity) then restore(t,true) end
    return true,status('MISSION: Solo Launch off; keeping the Doomsday contract through settlement.')
   elseif w.classic>0 or w.modern>0 or w.v3>0 then
    return true,status('WAITING: Unexpected controller; no restoration writes into it.')
   elseif current(t)then
    if restore(t,false)then transaction=nil
    else return false,status('RESTORING: Some owned minima could not be restored yet.')end
   else
    t.handoff=t.handoff or h.now()
    return true,status('HANDOFF: Waiting for the current launch to settle before restoring.')
   end
  end
  return true,status('OFF: Solo Launch disabled.')
 end
 function c.Tick()
  local w=world()
  if not w then return status('WAITING: GTA state is temporarily unreadable.')end
  local t=transaction
  if t then
   -- Observe the launcher while we still own the original Doomsday activity.
   if scope(t,w) and w.mission==t.context.mission then
    watch_doomsday_launcher(t,w)
   end
   if not scope(t,w) or w.mission~=t.context.mission then
    -- GTA can clear the selected mission ID before the result activity ends.
    -- Permit only the empty-job/empty-controller gap. Never touch a new job.
    local final_gap=scope(t,w) and t.finish_requested and t.mission_seen and w.activity
     and w.mission==0 and w.classic==0 and w.modern==0 and w.v3==0 and w.launchers==0
    if final_gap then
     observe_doomsday_result(t,w)
     return status('RESULT HANDOFF: Mission ID cleared; waiting for activity to close.')
    end
    if scope(t,w) and t.finish_requested and t.mission_seen and w.activity
       and w.mission~=t.context.mission and w.classic==0
       and w.modern==0 and w.v3==0 then
     if not t.result_job_shift_logged then
      t.result_job_shift_logged=true
      log('DOOMSDAY_RESULT_JOB_SHIFT old_mission='..t.context.mission
       ..' new_mission='..w.mission..' activity=true launcher='..w.launchers
       ..'; no old-job writes permitted; outcome still unconfirmed')
     end
     return status('RESULT HANDOFF: Activity still open after job ID changed; result unconfirmed.')
    end
    -- On a fully closed activity, safely restore only owned global minima that
    -- still have the exact value we set. Never restore a stale script local.
    if scope(t,w) and t.mission_seen and not w.activity and w.mission==0 and
       w.classic==0 and w.modern==0 and w.v3==0 and w.launchers==0 then
     restore(t,false)
    else
     restore(t,true)
    end
    log('DOOMSDAY_CONTRACT_RELEASE old_pid='..tostring(t.context.pid)..' new_pid='..tostring(w.pid)
     ..' old_epoch='..tostring(t.context.epoch)..' new_epoch='..tostring(w.epoch)
     ..' old_mission='..tostring(t.context.mission)..' new_mission='..tostring(w.mission)
     ..' session='..tostring(w.session)..' activity='..tostring(w.activity))
    transaction=nil
    return status('WAITING: Previous launch context ended; old snapshots released.')
   end
   if is_mission(w,t)then
    t.mission_seen=true
    hold_doomsday_minima(t,w)
    observe_doomsday_result(t,w)
    -- Doomsday's launcher may be alive alongside the finale controller.
    -- Restoring its original catalogue minimum here reintroduces the 2-player
    -- contract before result processing has finished. Other heists unchanged.
    if not (t.context.family=='doomsday' and w.activity) then restore(t,true) end
    return status('MISSION: '..t.context.name..' controller observed. Keep this Lua loaded through the result.')
   end
   if w.classic>0 or w.modern>0 or w.v3>0 then return status('WAITING: Unexpected controller; no writes into it.')end
   if t.mission_seen then
    if w.activity then
     -- The controller can exit before GTA has finished its network result
     -- transition; releasing global minimums here caused a fresh 2-player check.
     hold_doomsday_minima(t,w)
     observe_doomsday_result(t,w)
     return status('RESULT HANDOFF: Retaining finale admission while GTA is still in the activity.')
    end
    if w.launchers~=0 then
     return status('RESTORING: Waiting for the previous launcher/result context to close.')
    end
    if restore(t,false)then transaction=nil
    else return status('RESTORING: Waiting to restore the finished mission minima.')end
    return status(enabled and 'WAITING: Mission ended. Waiting for your next solo lobby.' or 'OFF: Finished mission minima released.')
   end
   if w.launchers==0 then
    t.handoff=t.handoff or h.now()
    if h.now()-t.handoff<30000 then return status('HANDOFF: Waiting for the finale controller.')end
    if restore(t,false)then transaction=nil end
    return status('UNCONFIRMED: No mission controller observed after 30 seconds. Check Show Status.')
   end
   local s=current(t)
   if not s then return status('WAITING: Launcher identity is temporarily unavailable; no writes.')end
   t.handoff=nil
   if not enabled or not s.solo or s.role~=0 or s.metadata~=t.context.metadata or s.family~='cayo' and s.teams~=1 then
    if not restore(t,false)then return status('RESTORING: Waiting to release the previous lobby settings.')end
    transaction=nil
    if not enabled then return status('OFF: Solo Launch disabled.')end
    if not s.solo or s.role~=0 then return status('WAITING: Solo Launch needs one host in the first role.')end
    local ok,fresh=pcall(h.lobby);if ok then return apply(fresh)end
    return status('WAITING: Lobby is changing.')
   end
   local ok,why=pcall(function()
    for _,f in ipairs(t.fields)do
     local fresh=assert(current(t),'Launcher changed during minimum maintenance.')
     assert(fresh.solo and fresh.role==0 and fresh.metadata==t.context.metadata and (fresh.family=='cayo' or fresh.teams==1),'The lobby crew, role or metadata changed during maintenance.')
     local value=h.read(f.kind,f.index,t.context)
     if value~=f.value then
      assert(f.owned and value==f.old,'A minimum was edited independently; stopping Solo Launch.')
      assert(t.reapplications<32,'GTA repeatedly reset the solo settings; check Show Status.')
      if f.catalogue then assert(h.catalogue_matches(f.catalogue),'Catalogue row changed.')end
      h.write(f.kind,f.index,f.value,t.context)
      assert(h.read(f.kind,f.index,t.context)==f.value,'Maintenance readback failed.')
      t.reapplications=t.reapplications+1
     end
    end
   end)
   if not ok then
    enabled=false
    if restore(t,false)then transaction=nil end
    return status('FAILED: '..reason(why))
   end
   return latest
  end
  if not enabled then return latest end
  if w.session and (w.classic>0 or w.modern>0 or w.v3>0)then
   return status('OBSERVED: A mission controller is running. No lobby settings are being applied.')
  end
  if not w.session or w.classic~=0 or w.modern~=0 or w.v3~=0 or w.launchers~=1 then
   return status('WAITING: Open your hosted heist finale lobby before starting the mission.')
  end
  local ok,s=pcall(h.lobby)
  if not ok then return status('WAITING: '..reason(s))end
  if not s.solo or s.role~=0 then return status('WAITING: Solo Launch needs one host in the first role.')end
  return apply(s)
 end
 function c.MarkResultRequested(expected)
  if not enabled then return false,'Enable Solo Launch before starting Doomsday.'end
  local t,w=transaction,world()
  local valid=t and t.context.family=='doomsday' and scope(t,w)
   and w.mission==t.context.mission and is_mission(w,t)
   and w.activity and w.total==1
  if not valid then
   local ok,why=recover_contract(expected)
   if not ok then return false,why end
   t,w=transaction,world()
  end
  if not scope(t,w) or w.mission~=t.context.mission or not is_mission(w,t)
    or not w.activity or w.total~=1 then
   return false,'The own, single-player Doomsday mission is no longer active.'
  end
  hold_doomsday_minima(t,w)
  -- Do not accept a best-effort warning as a valid result contract.
  for _,f in ipairs(t.fields)do
   if f.kind=='g' and not f.catalogue and h.read('g',f.index,t.context)~=f.value then
    return false,'Doomsday admission did not remain applied: '..f.index
   end
  end
  t.mission_seen=true
  t.finish_requested=h.now()
  t.last_result_stamp=nil
  watch_doomsday_launcher(t,w)
  log('DOOMSDAY_RESULT_ARMED before finish submission; current solo contract verified')
  return true,'Doomsday solo handoff armed; completion/payment unconfirmed.'
 end
 function c.CancelResultRequested(why)
  if transaction then transaction.finish_requested=nil;transaction.last_result_stamp=nil end
  log('DOOMSDAY_RESULT_CANCELLED '..tostring(why or 'finish not submitted'))
 end
 function c.IsEnabled()return enabled end
 function c.Status()return latest end
 function c.Reset()transaction=nil;status('WAITING: Session changed; prior snapshots discarded.')end
 function c.Unload()
  enabled=false
  if transaction then
   local t,w=transaction,world()
   -- During the launcher->controller gap, rolling back the minima would
   -- reintroduce a two-player contract while this very launch consumes it.
   local handoff=scope(t,w) and w.mission==t.context.mission and w.launchers==0
    and w.classic==0 and w.modern==0 and w.v3==0 and not t.mission_seen
   local active_result=scope(t,w) and t.mission_seen and w.activity
    and w.mission==t.context.mission
   local complete=restore(t,handoff or active_result)
   if handoff or active_result or w and is_mission(w,t)then
    log('Unload during launch/mission: '..(complete and 'catalogue cleanup checked' or 'catalogue cleanup unconfirmed')..'; this job keeps its admission contract until GTA loads the next content metadata.')
   elseif not complete then log('Unload: some matching owned minima could not be restored; cleanup is unconfirmed.')end
