local function buffer_stat(name,kind)
 local ptr=Memory.AllocInt();assert(ptr and ptr~=0,'Stat buffer unavailable.')
 local ok,value=pcall(function()
  Memory.WriteInt(ptr,0)
  local native=kind=='bool' and 0x11B5E6D2AE73F48E or 0x767FBC2AC802EF3D
  assert(Natives.InvokeBool(native,Utils.Joaat(name),ptr,-1)==true,'Cannot read '..name)
  local v=Memory.ReadInt(ptr);assert(integer(v),'Invalid stat: '..name)
  if kind=='bool'then assert(v==0 or v==1,'Invalid boolean stat.');return v==1 end
