local ApartmentBoard=(function()

-- Standalone Apartment Planning Board test for Cherax.
-- One feature. Does not load CScript or change finale cuts, payout or setups.
local TITLE = "Apartment Board Test"
local G = {
    owner=1941984+58, root=1936441+1787, count=1936441+1707,
    dirty=1936441+1782, status=1936441+1720+1,
    player_base=1877383+1,
}
local H={
    session=0xD83C2B94E7508980, activity=0x05095437424397FA,
    player=0x4F8644AF03D0E0D6, stat_int=0x767FBC2AC802EF3D,
    stat_string=0xE50384ACC2C3DB74,
}
local function number_ok(n)
    return type(n)=="number" and n==n and n%1==0
        and n>=-9007199254740991 and n<=9007199254740991
end
local function valid_time(n) return number_ok(n) and n>=0 end
local function valid_string(v) return type(v)=="string" and v~="" and v~="." end
local function same(a,b)
    return a.player==b.player and a.slot==b.slot and a.saved_root==b.saved_root
        and a.stage==b.stage and a.board_root==b.board_root and a.count==b.count
end
local function log(msg)
    if type(Logger)=="table" and type(Logger.LogInfo)=="function" then
        pcall(Logger.LogInfo,"["..TITLE.."] "..tostring(msg))
    end
end
local function say(msg)
    log(msg)
    if type(GUI)=="table" and type(GUI.AddToast)=="function" then
        pcall(function()GUI.AddToast(TITLE,tostring(msg),5500,eToastPos.TOP_RIGHT)end)
    end
end

-- This controller is unit-testable without GTA. Host actions are isolated.
local function new_controller(host)
    local pending,latest,last_poll=nil,"Ready",0
    local api={}
    local function result(ok,msg)latest=msg;return ok,msg end
    local function inspect()
        local ok,s=pcall(host.inspect)
        if not ok or type(s)~="table" then return nil,"Can't read the heist board." end
        if s.session~=true then return nil,"Enter GTA Online first." end
        if s.activity~=false then return nil,"Leave the current mission first." end
        if not number_ok(s.player) or s.player<0 or s.player>31 or (s.slot~=0 and s.slot~=1) then
            return nil,"Couldn't identify your character."
        end
        if not number_ok(s.saved_root) or not number_ok(s.stage) then
            return nil,"Saved heist isn't available."
        end
        if not s.board_open then return nil,"Open your apartment heist board first." end
        if s.owner~=s.player then return nil,"This isn't your planning board." end
        if not valid_string(s.board_uid) or not number_ok(s.board_root) then
            return nil,"Planning board isn't ready yet."
        end
        if s.board_root%4294967296~=s.saved_root%4294967296 then
            return nil,"The board shows a different heist."
        end
        if not number_ok(s.count) or s.count<1 or s.count>7
            or not number_ok(s.missions) or s.missions~=s.count then
            return nil,"Board entries: "..tostring(s.count).."; saved setups: "..tostring(s.missions)..". Press Log Board Details."
        end
        if not number_ok(s.dirty) then return nil,"Planning board isn't ready yet." end
        return s
    end
    function api.Check()
        local s,why=inspect()
        if not s then return result(false,why) end
        if pending then return result(true,"Waiting for the board to update.")end
        if s.dirty~=0 then return result(false,"The board is busy. Try again shortly.")end
        return result(true,"Planning board is ready.")
    end
    function api.Refresh()
        if pending then return result(false,"The board is already updating.")end
        local before,why=inspect()
        if not before then return result(false,why)end
        if before.dirty~=0 then return result(false,"The board is busy. Try again shortly.")end
        local now=host.now()
        if not valid_time(now) then return result(false,"Game timer isn't available.")end
        local s=inspect()
        if not s or not same(before,s) or s.dirty~=0 then
            return result(false,"Planning board changed. Check it again.")
        end
        local ok,accepted=pcall(host.set_dirty)
        if not ok or accepted~=true then return result(false,"Couldn't refresh the board.")end
        pending={snapshot=before,started=now,deadline=now+5000}
        last_poll=0
        return result(true,"Refreshing the planning board...")
    end
    function api.Tick()
        if not pending then return nil end
        local now=host.now()
        if not valid_time(now) or now<pending.started or now>=pending.deadline then
            pending=nil;return result(false,"The board didn't update. Open it again.")
        end
        if last_poll~=0 and now-last_poll<100 then return nil end
        last_poll=now
        local fresh=inspect()
        if not fresh or not same(fresh,pending.snapshot) then
            pending=nil;return result(false,"Heist or board changed. Try again.")
        end
