function P.build(selection, old)
    local approach = assert(tonumber(selection.approach), "Approach missing")
    local target = assert(tonumber(selection.target), "Target missing")
    assert(approach % 1 == 0 and approach >= 1 and approach <= 3, "Invalid approach")
    assert(target % 1 == 0 and target >= 0 and target <= 3, "Invalid target")
    assert(tonumber(old.ARCADE_OWNED) and old.ARCADE_OWNED > 0, "Own an Arcade first.")
    -- func1279 disallows the immediately previous approach. Preserve history;
    -- changing H3_LAST_APPROACH would hide an incompatible normal board state.
    local last = assert(math.tointeger(old.H3_LAST_APPROACH), "Last approach unreadable")
    assert(last >= 0 and last <= 3, "Unknown Casino last-approach state")
    assert(last ~= approach,
        "That approach was used last. Choose another approach.")
    -- H3_HARD_APPROACH stores an approach id, not a boolean. If it equals the
    -- chosen approach the game uses Hard, otherwise Normal; no reset required.
    local hard = assert(math.tointeger(old.H3_HARD_APPROACH), "Difficulty unreadable")
    assert(hard >= 0 and hard <= 3, "Unknown Casino difficulty state")
    local bits0 = assert(math.tointeger(old.H3OPT_BITSET0), "Prep bitset0 unreadable")
    local bits1 = assert(math.tointeger(old.H3OPT_BITSET1), "Prep bitset1 unreadable")
    local flow = assert(math.tointeger(old.CAS_HEIST_FLOW), "Heist flow unreadable")
    local access = assert(math.tointeger(old.H3OPT_ACCESSPOINTS), "Access scope unreadable")
    local poi = assert(math.tointeger(old.H3OPT_POI), "POI scope unreadable")
    local partial = assert(math.tointeger(old.H3_PARTIALPASS), "Partial prep state unreadable")
    -- Mandatory: scoped contents bit0, common bits1..4; selected approach bits.
    local mandatory = ({[1]=127,[2]=159,[3]=799})[approach]
    -- Common optional bits0/1/2/4, plus game-maintained ever-powerdrills bit22.
    -- Silent adds3/5; Con adds entry pairs8..15 and NOOSE/firefighter16/17;
    -- Aggressive adds19/20. Never force6/7 paid finale services,18 collectible
    -- High Roller,21 thermal/breaching variant, or unrelated higher bits.
    local all_prep = ({[1]=0x40003F,[2]=0x43FF17,[3]=0x580017})[approach]
    local partial_mask = ({[1]=0x01E3,[2]=0x1E23,[3]=0xE023})[approach]
    return {
        H3OPT_APPROACH=approach, H3OPT_TARGET=target,
        H3OPT_CREWWEAP=1, H3OPT_WEAPS=0,
        H3OPT_CREWDRIVER=1, H3OPT_VEHS=0,
        H3OPT_CREWHACKER=1, H3OPT_KEYLEVELS=2,
        H3OPT_BITSET0=bits0 | all_prep, H3OPT_BITSET1=bits1 | mandatory,
        H3OPT_DISRUPTSHIP=3, H3OPT_MASKS=1,
        H3OPT_ACCESSPOINTS=access | 0x7FF, H3OPT_POI=poi | 0x3FF,
        H3_PARTIALPASS=partial & (~partial_mask),
        -- bit0 setup initialized (func628),4 casino scoped (func299),
        --22 security intel acquired (func1108). Other flow/history preserved.
        CAS_HEIST_FLOW=flow | 0x400011,
    }
end

return P

end)()
P.title='Diamond Casino'
-- Shared source used to build three independent, standalone prototypes.
local function int(v)return type(v)=='number' and v%1==0 and v>=-2147483648 and v<=2147483647 end
local function clean(v)return tostring(v):gsub('^.-:%d+:%s*','')end
local function new_controller(h,profile)
 local pending
 local reopen=profile.refresh and profile.refresh.reopen_message
  or (profile.family=='doomsday' and 'Preps applied. Leave the planning room, then return.'
  or 'Preps applied. Reopen the planning screen.')
 local c={}
 local function trace(t,label)if h.trace then pcall(h.trace,t,label)end end
 local function release(t,reason)if t and h.release then pcall(h.release,t,reason)end end
 local function recovery(t)
  if h.recovery then local ok,message=pcall(h.recovery,t);if ok and message then return message end end
  return reopen
 end
 local function owned(t)
  h.check(t.context)
  for _,f in ipairs(t.fields)do
   local observed=h.read(t.context,f.key)
   -- func885 adds its own first-planning-room help latch after publication.
   -- Accept only that observed addition; selected act and every other bit stay exact.
   if profile.family=='doomsday' and f.key=='GANGOPS_HEIST_STATUS'
    and t.doomsday_refresh and t.doomsday_refresh.published and observed==(f.value|64)then
    f.value=observed;t.expected[f.key]=observed
   end
   assert(observed==f.value,'Heist selection changed. Apply again.')
  end
 end
 function c.Apply(selection)
  if pending then return false,'Still applying.' end
  local t={fields={}}
  local ok,err=pcall(function()
   t.context=h.context();h.check(t.context)
   local old,allowed={},{}
   for _,key in ipairs(profile.stat_keys)do
    allowed[key]=true;old[key]=h.read(t.context,key)
    assert(int(old[key]),'Could not read prep data.')
   end
   for _,key in ipairs(profile.context_stat_keys or {})do
    old[key]=h.read(t.context,key);assert(int(old[key]),'Could not read heist context.')
   end
   if profile.context_globals then old._globals=h.read_globals(t.context)end
   local values=profile.build(selection,old)
   for key,v in pairs(values)do assert(allowed[key] and int(v),'Invalid prep value.')end
   for _,key in ipairs(profile.stat_keys)do
    assert(int(values[key]),'Missing prep value.')
    t.fields[#t.fields+1]={key=key,old=old[key],value=values[key]}
   end
   t.expected=values;t.old=old;trace(t,'before')
   -- No yield between related writes. Snapshot all inputs before publication.
   for _,f in ipairs(t.fields)do
    h.check(t.context)
    assert(h.read(t.context,f.key)==f.old,'Prep data changed. Apply again.')
    if f.old~=f.value then
     f.attempted=true;h.write(t.context,f.key,f.value)
     h.check(t.context)
     assert(h.read(t.context,f.key)==f.value,'Prep write was not accepted.')
    end
   end
   owned(t)
   t.deadline=h.now()+3000;t.stage='cache';trace(t,'written')
   pending=t
  end)
  if not ok then
   trace(t,'write failure: '..clean(err))
   local restored=true
   for i=#t.fields,1,-1 do
    local f=t.fields[i]
    if f.attempted then
     local rok=pcall(function()
      h.check(t.context)
      if h.read(t.context,f.key)==f.value then h.write(t.context,f.key,f.old)end
     end)
     restored=restored and rok
    end
   end
   release(t,'write failure')
   return false,clean(err)..(restored and '' or ' Some prep data may already be applied.')
  end
  return true,'Applying...'
 end
 function c.Tick()
  local t=pending;if not t then return nil end
  local ok,message=pcall(function()
   owned(t)
   if h.now()>=t.deadline then trace(t,'refresh timeout');return recovery(t)end
   if not h.mirrors(t)then
    if not t.cache_wait_logged then t.cache_wait_logged=true;trace(t,'waiting for cache')end
    return nil
   end
   if t.stage=='cache'then
    local result=h.refresh(t)
    if t.presentation_started_at and not t.presentation_window_set then
     t.presentation_window_set=true;t.deadline=t.presentation_started_at+3000
    end
    if result=='none'then return 'Preps applied. Open the planning board.' end
    if result=='reopen'then return recovery(t)end
    if result=='wait'then return nil end
    assert(result=='pending','Unknown board refresh state.')
    t.stage='redraw'
   end
   if h.ack(t)then return 'Preps applied.' end
   return nil
  end)
  if not ok then
   local fallback
   if h.recovery then local rok,msg=pcall(h.recovery,t);if rok then fallback=msg end end
   release(t,'error');pending=nil
   return fallback or ('Preps applied. '..clean(message))
  end
  if message then release(t,message);pending=nil end
  return message
 end
 function c.Unload()release(pending,'unload');pending=nil end
 return c
end
if TEST_ONLY then return {NewController=new_controller}end

local function ni(hash,...)local v=Natives.InvokeInt(hash,...);assert(int(v),'GTA integer read failed.');return v end
local function nb(hash,...)local v=Natives.InvokeBool(hash,...);assert(type(v)=='boolean','GTA boolean read failed.');return v end
local function gi(index)local v=ScriptGlobal.GetInt(index);assert(int(v),'Planning data unavailable.');return v end
local function gf(index)
 local v=ScriptGlobal.GetFloat(index)
 assert(type(v)=='number' and v==v and v>-math.huge and v<math.huge,'Planning multiplier unavailable.')
 return v
end
local function li(hash,index)local v=ScriptLocal.GetInt(hash,index);assert(int(v),'Planning script unavailable.');return v end
local function stat(name)
 local ptr=Memory.AllocInt();assert(type(ptr)=='number' and ptr>0,'Stat buffer unavailable.')
 local ok,value=pcall(function()
  Memory.WriteInt(ptr,0)
  assert(nb(0x767FBC2AC802EF3D,Utils.Joaat(name),ptr,-1),'Could not read '..name..'.')
  local v=Memory.ReadInt(ptr);assert(int(v),'Invalid stat value.');return v
 end)
 local released=pcall(Memory.Free,ptr);assert(released,'Stat buffer could not be released.')
 assert(ok,value);return value
end
local function count(name)return ni(0x2C83A9DA6BFFC4F9,Utils.Joaat(name))end
local function log(message)
 if Logger and Logger.LogInfo then pcall(Logger.LogInfo,'[Prep prototype v3 / '..P.family..'] '..tostring(message))end
end
local function say(message)
 log(message)
 if GUI and GUI.AddToast then pcall(GUI.AddToast,P.title,message,4500,eToastPos.TOP_RIGHT)end
end
local host={}
function host.now()return Time.GetEpocheMs()end
function host.context()
 assert(nb(0xD83C2B94E7508980) and not nb(0x68049AEFF83D8F0A)
  and not nb(0x05095437424397FA),'Return to GTA Online freemode first.')
 assert(count('freemode')==1 and count('fm_mission_controller')==0
  and count('fm_mission_controller_2020')==0 and not nb(0xA33CDCCDA663159E),'Finish the current mission first.')
 local pid=ni(0x4F8644AF03D0E0D6);local slot=stat('MPPLY_LAST_MP_CHAR')
 assert(pid>=0 and pid<=31 and (slot==0 or slot==1),'Character unavailable.')
 local prefix='MP'..slot..'_'
 local freemode_ptr=ScriptLocal.GetPtr(Utils.Joaat('freemode'),0)
 assert(type(freemode_ptr)=='number' and freemode_ptr>=65536,'Freemode unavailable.')
 local context={pid=pid,slot=slot,prefix=prefix,freemode_ptr=freemode_ptr}
 context.identity=table.concat({pid,slot,freemode_ptr},':')
 return context
end
function host.read(context,key)return stat(context.prefix..key)end
function host.check(context)
 local fresh=host.context()
 assert(context and fresh.identity==context.identity,'Character or session changed.')
 for _,guard in ipairs(P.required_stat_bits or {})do
  assert((host.read(context,guard.key)&guard.mask)==guard.mask,'Pay the heist setup fee at your planning board first.')
 end
 for _,guard in ipairs(P.required_stat_min or {})do
  assert(host.read(context,guard.key)>=guard.min,guard.message or 'Initialize your own heist first.')
 end
 for _,guard in ipairs(P.stat_guards or {})do
  local value=host.read(context,guard.key)
  assert((not guard.minimum or value>=guard.minimum)
   and (not guard.required_mask or (value&guard.required_mask)==guard.required_mask),guard.reason)
 end
 for _,guard in ipairs(P.prerequisite_stats or {})do
  assert(guard.test=='nonzero' and host.read(context,guard.key)~=0,guard.message)
 end
end
function host.write(context,key,value)
 assert(nb(0xB3271D7AB655B441,Utils.Joaat(context.prefix..key),value,true),'GTA rejected prep data.')
end
function host.read_globals(context)
 host.check(context)
 local out={}
 for key,row in pairs(P.context_globals or {})do
  assert(row.kind=='int' or row.kind=='float','Unsupported default data type.')
  out[key]=row.kind=='float' and gf(row.index) or gi(row.index)
 end
 return out
end
local function mirrors(profile)
 local r=profile.refresh;local rows={}
 if r.mirrors then
  for _,row in ipairs(r.mirrors)do rows[#rows+1]={key=row.key,index=r.mirror_base,offset=row.offset,stride=r.mirror_stride}end
 elseif r.cache then
  for key,offset in pairs(r.cache.fields)do
   rows[#rows+1]={key=key,index=r.cache.base+r.cache.array_header+r.cache.member_offset,offset=offset,stride=r.cache.stride}
  end
 else
  for key,offset in pairs(r.cache_offsets or {})do
   rows[#rows+1]={key=key,index=r.cache_base+(r.cache_array_header or 0),offset=offset,stride=r.cache_stride}
  end
 end
 return rows
end
local mirror_rows=mirrors(P)
function host.mirrors(t)
 for _,row in ipairs(mirror_rows)do
  local expected=t.expected[row.key]
  -- Only compare values actually written by this transaction.
  if expected~=nil and gi(row.index+t.context.pid*row.stride+row.offset)~=expected then return false end
 end
 return true
end
local function capture_board(t)
 local r=P.refresh;local hash=Utils.Joaat(r.script)
 if count(r.script)==0 then return nil end
 assert(count(r.script)==1,'Close extra planning screens first.')
 local ptr=ScriptLocal.GetPtr(hash,0)
 assert(type(ptr)=='number' and ptr>=65536,'Planning screen unavailable.')
 assert(type(P.verification_patterns)=='table' and #P.verification_patterns>=2,'Board refresh is not verified for this build.')
 for _,pattern in ipairs(P.verification_patterns)do
  local found=Memory.ScanScript(hash,pattern)
  assert(type(found)=='number' and found>=65536,'Planning script build changed. Reopen the planning screen.')
 end
 return {hash=hash,ptr=ptr}
end
local function same_board(t)
 host.check(t.context)
 local b=t.board;local r=P.refresh
 assert(count(r.script)==1 and ScriptLocal.GetPtr(b.hash,0)==b.ptr,'Planning screen changed.')
 local owner=r.owner_index or r.owner_global
 assert(owner and gi(owner)==t.context.pid,'Open your own planning board.')
 assert(li(b.hash,r.local_index or r.ready_local)==r.ready_value,'Planning screen is busy.')
 return b,r
end
local function set_global(t,index,value)
 same_board(t);ScriptGlobal.SetInt(index,value);assert(gi(index)==value,'Board update rejected.')
end
local function cayo_idle(t)
 local b,r=same_board(t)
 return gi(r.screen_state_global)==r.idle_state and gi(r.fullscreen_global)==r.idle_fullscreen_value
end
local function casino_panel(t)
 local _,r=same_board(t)
 local id=gi(r.panel_index)
 local panel
 for _,row in ipairs(r.panels)do if row.id==id then panel=row;break end end
 if not panel then return nil,'panel='..id end
 local stage=gi(panel.stage_index)
 for _,check in ipairs(r.busy_checks or {})do
  if (not check.panel or check.panel==id) and (not check.active_only or stage==r.active_stage)
   and gi(check.index)~=check.expected then return nil,'busy global='..check.index..' value='..gi(check.index)end
 end
 for _,check in ipairs(panel.busy_checks or {})do
  if (not check.stage or stage==check.stage) and gi(check.index)~=check.expected then
   return nil,'busy panel='..id..' global='..check.index..' value='..gi(check.index)
  end
 end
 if r.stable_stages[stage] and gi(panel.substate_index)==r.required_substate
  and gi(panel.movie_index)>0 then return panel end
 return nil,'panel='..id..' stage='..stage..' substate='..gi(panel.substate_index)..' movie='..gi(panel.movie_index)
end
local function casino_targets(t)
 local _,r=same_board(t)
 -- func610: all three stage3 panels are the ordinary idle planning room.
 -- Each stage3 handler still calls its semantic dirty consumer.
 local all_idle=true
 for _,panel in ipairs(r.panels)do
  if gi(panel.stage_index)~=3 then all_idle=false;break end
 end
 if all_idle then
  for _,check in ipairs(r.busy_checks or {})do
   if gi(check.index)~=check.expected then return nil,'idle room dialog busy' end
  end
  for _,panel in ipairs(r.panels)do
   if gi(panel.substate_index)~=r.required_substate or gi(panel.movie_index)<=0 then return nil,'idle room boards not loaded' end
  end
  return r.panels
 end
 local panel,why=casino_panel(t)
 return panel and {panel} or nil,why
end
local function same_targets(t,expected)
 local rows=casino_targets(t)
 if not rows or #rows~=#expected then return false end
 for i,row in ipairs(rows)do if row~=expected[i]then return false end end
 return true
end
local presentation
local function presentation_impl()
 if presentation or not P.refresh_factory then return presentation end
 local hash=Utils.Joaat(P.refresh.script)
 local function as_script(fn)
  assert(count(P.refresh.script)==1,'Planning script unavailable.')
  local packed
  Script.ExecuteAsScript(hash,function()packed=table.pack(fn())end)
  assert(packed,'Planning script context unavailable.')
  return table.unpack(packed,1,packed.n)
 end
 local api={gi=gi,li=function(index)return li(hash,index)end,
  si=function(index,value)
   assert(int(value),'Invalid display value.');ScriptGlobal.SetInt(index,value)
   assert(gi(index)==value,'Display write rejected.')
  end,
  sl=function(index,value)
   assert(int(value),'Invalid display local.');ScriptLocal.SetInt(hash,index,value)
   assert(li(hash,index)==value,'Display local write rejected.')
  end,
  count=function()return count(P.refresh.script)end,
  ptr=function()return ScriptLocal.GetPtr(hash,0)end,
  same_context=function(t)host.check(t.context);return true end,
  now=host.now,log=log,notice=say,script_hash=hash,
  ni=function(native,...)local args=table.pack(...);return as_script(function()return ni(native,table.unpack(args,1,args.n))end)end,
  nb=function(native,...)local args=table.pack(...);return as_script(function()return nb(native,table.unpack(args,1,args.n))end)end,
  nv=function(native,...)local args=table.pack(...);return as_script(function()return Natives.InvokeVoid(native,table.unpack(args,1,args.n))end)end,
 }
 function api.verify(patterns)
  patterns=patterns or P.verification_patterns
  assert(type(patterns)=='table' and #patterns>=2,'Missing display layout verification.')
  local all={}
  for _,pattern in ipairs(P.verification_patterns or {})do all[#all+1]=pattern end
  if patterns~=P.verification_patterns then for _,pattern in ipairs(patterns)do all[#all+1]=pattern end end
  for _,pattern in ipairs(all)do
   local found=Memory.ScanScript(hash,pattern)
   assert(type(found)=='number' and found>=65536,'Unsupported planning script build.')
  end
  return true
 end
 function api.release_movie(handle)
  assert(int(handle) and handle>0,'Invalid display movie.')
  local ptr=Memory.AllocInt();assert(type(ptr)=='number' and ptr>0,'Display release buffer unavailable.')
  local ok,err=pcall(function()
   Memory.WriteInt(ptr,handle)
   api.nv(0x1D132D614DD86811,ptr)
  end)
  local freed=pcall(Memory.Free,ptr);assert(freed,'Display release buffer failed.')
  assert(ok,err)
 end
 presentation=assert(P.refresh_factory(api),'Display controller unavailable.')
 return presentation
end
function host.refresh(t)
 local custom=presentation_impl()
 if custom then
  local result,why=custom.request(t)
  if not t.presentation_started_at and ((t._cayo_movie_rebuild and t._cayo_movie_rebuild.old_released)
   or (t.doomsday_refresh and t.doomsday_refresh.published))then t.presentation_started_at=host.now()end
  if why and t.custom_reason~=why then
   t.custom_reason=why;log('display reload: '..why)
   if result=='wait' and why:find('Close the planning screen',1,true)then say('Close the planning screen to refresh.')end
  end
  return result
 end
 if P.family=='doomsday'then return count(P.refresh.script)==0 and 'none' or 'reopen' end
 t.board=t.board or capture_board(t)
 if not t.board then return 'none' end
 local b,r=same_board(t)
 if P.family=='casino'then
  local panels,why=casino_targets(t)
  if not panels then
   if t.refresh_reason~=why then t.refresh_reason=why;log('waiting for board: '..why)end
   return 'wait'
  end
  for _,row in ipairs(r.cache_sync)do
   assert(same_targets(t,panels),'Planning screen changed.')
   set_global(t,row.index,assert(t.expected[row.key]))
  end
  t.panels=panels
  for _,panel in ipairs(panels)do
   assert(same_targets(t,panels),'Planning screen changed.')
   set_global(t,panel.dirty_index,r.dirty_trigger)
  end
  return 'pending'
 elseif P.family=='cayo'then
  if not cayo_idle(t)then return 'reopen' end
  ScriptLocal.SetInt(b.hash,r.render_loaded_local,0)
  assert(li(b.hash,r.render_loaded_local)==0,'Board redraw rejected.')
  assert(cayo_idle(t),'Planning screen changed.')
  set_global(t,r.entry_flags_global,gi(r.entry_flags_global)&(~(1<<r.entry_bit)))
  return 'pending'
 end
