 if P.family=='cayo'then
  return cayo_idle(t) and li(b.hash,r.render_loaded_local)==1 and (gi(r.entry_flags_global)&(1<<r.entry_bit))~=0
 end
 return false
end
function host.recovery(t)
 local s=t and t._cayo_movie_rebuild
 if s and s.old_released and not s.done then return 'Preps applied. Reenter the Kosatka to reload the board.' end
 s=t and t.doomsday_refresh
 if s and s.published then return 'Preps applied. Reenter the Facility to reload the board.' end
end
function host.release(t,reason)
 local fallback=host.recovery(t)
 if presentation and presentation.release then presentation.release(t,reason)end
 if fallback and reason=='unload'then say(fallback)end
end

local controller=new_controller(host,P)
return {Controller=controller,Host=host,Profile=P,NewController=new_controller}
end)()


-- SOURCE rrer.lua; controller body copied without standalone UI registration.
local ApartmentFinish=(function()

-- Apartment Instant Finish, standalone prototype v1, Enhanced 1.73.
-- Submit once; let GTA perform its own bookkeeping/result/transaction work.
-- Live result and payment have NOT been validated for this prototype.
-- Source: fm_mission_controller funcs 767/768, 790, 871, 946, 13215.
-- Uses the existing host result gate, not an objective-17 bytecode patch.
local TITLE='Apartment Instant Finish'
local SCRIPT='fm_mission_controller'
local H={session=0xD83C2B94E7508980,player=0x4F8644AF03D0E0D6,
 threads=0x2C83A9DA6BFFC4F9,script=0x8A1C8B1738FFE87E,
 thread=0xC30338E8088E2E21,host=0x83CD99A1E6061AB5,
 thread_host=0xD3DEBE2991FE8098,thread_active=0x46E9AE36D8FA6417,
 party=0x18D0456E86604654,participant=0x6FF8FF40B6357D45,
 participant_player=0x24FB80D107371267}
local L={phase=20412,flags=20413,result_gate=20416,teams=21405,
 players=21417,score=21645,stage_score=21650,bonus_score=23191,stage=29327}
local ROWS={{9188,'The Fleeca Job'},{9193,'The Prison Break'},
 {9200,'The Humane Labs Raid'},{9206,'Series A Funding'},
 {9212,'The Pacific Standard Job'},{9213,'The Pacific Standard Job'},{9220,'The Pacific Standard Job'}}
-- Exact, unique anchors in the collected 1158.16 bytecode. Read-only scans.
-- func_946: root getter/setter; func_871: f_4 bit11 -> result processing.
local SIGNATURES={
 '2D 01 03 00 00 50 BC 4F 38 00 58 05 00 38 00 51 BC 4F 2E 01 00',
 '2D 00 45 00 00 37 05 75 31 2B 71 39 0C 4F BC 4F 41 04 25 0B 82 56 04 00 72 2E 00 01',
}
local function integer(v)return type(v)=='number' and v%1==0 and v>=-2147483648 and v<=2147483647 end
local function has(v,bit)return integer(v) and (v&(1<<bit))~=0 end
local function hash_equal(a,b)
 return integer(a) and type(b)=='number' and b%1==0
  and b>=-2147483648 and b<=4294967295 and a%4294967296==b%4294967296
end
local function clean(err)return tostring(err):gsub('^.-:%d+:%s*','')end
local function ni(hash,...)
 local ok,v=pcall(Natives.InvokeInt,hash,...);if ok and integer(v)then return v end
 error('Native integer state is unavailable.')
end
local function nb(hash,...)
 local ok,v=pcall(Natives.InvokeBool,hash,...);if ok and type(v)=='boolean'then return v end
 error('Native boolean state is unavailable.')
end
local function gi(index)
 local v=ScriptGlobal.GetInt(index);assert(integer(v),'Global state is unavailable.');return v
end
local function li(hash,index)
 local v=ScriptLocal.GetInt(hash,index);assert(integer(v),'Mission local is unavailable.');return v
end
local function log(text)
 if Logger and Logger.LogInfo then pcall(Logger.LogInfo,'['..TITLE..' v1] '..tostring(text))end
end
local function say(text)
 log(text)
 if GUI and GUI.AddToast then pcall(GUI.AddToast,TITLE,tostring(text),6500,eToastPos.TOP_RIGHT)end
end
local function identify(mission)
 local found
 for _,row in ipairs(ROWS)do
  local value=gi(262145+row[1])
  if value~=0 and hash_equal(mission,value)then
   assert(not found or found==row[2],'Apartment finale identity is ambiguous.');found=row[2]
  end
 end
 return found
end
local host={}
function host.now()
 local v=Time.GetEpocheMs();assert(type(v)=='number' and v==v,'Clock is unavailable.');return v
end
function host.capture()
 assert(nb(H.session),'Enter GTA Online first.')
 local hash=Utils.Joaat(SCRIPT)
 assert(ni(H.threads,hash)==1 and ni(H.threads,Utils.Joaat('fm_mission_controller_2020'))==0,
  'Start an apartment finale first; the planning board is not an active mission.')
 local mission=gi(4858023)
 local name=identify(mission);assert(name,'The active job is not an apartment finale.')
 local s={hash=hash,mission=mission,name=name,pid=ni(H.player)}
 assert(s.pid>=0 and s.pid<=31,'Player is unavailable.')
 Script.ExecuteAsScript(hash,function()
  s.actual=ni(H.script);s.thread=ni(H.thread);s.host=nb(H.host);s.party=ni(H.party)
  assert(hash_equal(s.actual,hash) and s.thread>0,'Mission script context is unavailable.')
  assert(s.party>=1 and s.party<=4,'Mission crew is still loading.')
  local roster,seen={},{}
  for part=0,31 do
   if nb(H.participant,part)then
    local pid=ni(H.participant_player,part)
    assert(pid>=0 and pid<=31 and not seen[pid],'Mission crew changed.')
    seen[pid]=true;roster[#roster+1]=part..'='..pid
   end
  end
  assert(#roster==s.party and seen[s.pid],'Mission crew is not ready.')
  s.roster=table.concat(roster,',')
 end)
 assert(s.host==true and nb(H.thread_active,s.thread) and ni(H.thread_host,s.thread)==s.pid,
  'Use Instant Finish as the current finale script host.')
 s.pointer=ScriptLocal.GetPtr(hash,L.phase)
 assert(type(s.pointer)=='number' and s.pointer>=65536,'Mission locals are not loaded.')
 s.phase=li(hash,L.phase);s.flags=li(hash,L.flags);s.gate=li(hash,L.result_gate)
 s.crew_flags=li(hash,20415)
 s.teams=li(hash,L.teams)
 assert(s.teams>=1 and s.teams<=4,'Mission teams are unavailable.')
 s.identity=table.concat({s.pid,s.mission%4294967296,s.thread,s.pointer,s.roster},':')
 assert(ScriptLocal.GetPtr(hash,L.phase)==s.pointer,'Mission allocation changed.')
 return s
end
function host.verify(s)
 assert(Memory and type(Memory.ScanScript)=='function','Script version verification is unavailable.')
 for _,pattern in ipairs(SIGNATURES)do
  local ptr=Memory.ScanScript(s.hash,pattern)
  assert(type(ptr)=='number' and ptr>=65536,'This mission script does not match the tested Enhanced layout.')
 end
end
local function active(s)
 assert(s.phase==9 and has(s.flags,17) and has(s.flags,19) and not has(s.flags,16),
  'Wait until the finale has started and mission objectives are active.')
 for team=0,3 do assert(not has(s.flags,20+team),'The game already recorded a failed team. Restart this finale.')end
 assert(not has(s.gate,11),'The mission already has an end request.')
end
local function plan(s)
 active(s)
 local fields={}
 local function add(index,old,new)
  assert(integer(old) and integer(new),'Mission score is outside the supported integer range.')
  if old~=new then fields[#fields+1]={index=index,old=old,value=new}end
 end
 local flags=s.flags
 local occupied=0
 for team=0,s.teams-1 do
  if has(s.flags,team)then
   occupied=occupied+1
   local stage=li(s.hash,L.stage+team)
   assert(stage>=0 and (stage<=17 or stage==99999),'Mission objective stage is unreadable.')
   local score=li(s.hash,L.score+team)
   local goal=gi(4718592+3838+1+team*26988+59)
   assert(score>=0 and goal>=-1,'Mission goal is unreadable.')
   if goal==-1 then goal=math.max(1,li(s.hash,L.players+team))
   elseif goal==0 then goal=1 end
   local delta=math.max(0,goal-score)
   if delta>0 then
    -- Match func_767/768: increase total, earned score and active-stage score.
    add(L.score+team,score,score+delta)
    local bonus=li(s.hash,L.bonus_score+team)
    add(L.bonus_score+team,bonus,bonus+delta)
    if stage<17 then
     local current=li(s.hash,L.stage_score+team)
     add(L.stage_score+team,current,current+delta)
    end
   end
  end
  flags=flags|(1<<(9+team))
 end
 assert(occupied>0,'Mission teams have not become active yet.')
 add(L.flags,s.flags,flags)
 -- Publish only after all score/end-state data has been written and read back.
 add(L.result_gate,s.gate,s.gate|(1<<11))
 return fields
end
local function new_controller(h)
 local pending,last=nil,'IDLE: Start an apartment finale, then click Instant Finish.'
 local c={}
 local function trace(s,reason)
  if not s then log(reason);return end
  log(reason..' heist='..s.name..' mission='..s.mission..' pid='..s.pid
   ..' thread='..s.thread..' ptr='..s.pointer..' crew='..s.party..' teams='..s.teams
   ..' phase='..s.phase..' flags='..s.flags..' result_gate='..s.gate
   ..' crew_flags='..tostring(s.crew_flags))
 end
 local function same(s)
  local ok,fresh=pcall(h.capture)
  if ok and fresh.identity==s.identity and fresh.teams==s.teams then return fresh end
 end
 function c.Request()
  if pending then return false,'A finish request is already being observed.'end
  local s,fields,attempted
  local ok,why=pcall(function()
   s=h.capture();active(s);h.verify(s)
   local fresh=assert(same(s),'Mission changed during verification.');active(fresh)
   assert(fresh.flags==s.flags and fresh.gate==s.gate,'Mission state changed during verification.')
   fields=plan(s);attempted={}
   trace(s,'submit')
   for _,f in ipairs(fields)do
    local current=assert(same(s),'Mission changed before result submission.')
    assert(current.phase==9 and not has(current.flags,16),'GTA already started result processing.')
    for team=0,3 do assert(not has(current.flags,20+team),'A team failed before submission.')end
    assert(li(s.hash,f.index)==f.old,'Mission data changed before submission.')
    attempted[#attempted+1]=f
    ScriptLocal.SetInt(s.hash,f.index,f.value)
    assert(same(s),'Mission changed during a result write.')
    assert(li(s.hash,f.index)==f.value,'GTA rejected a result write.')
   end
   pending={context=s,started=h.now(),stamp=''}
  end)
  if not ok then
   -- Roll back only this exact still-active VM and values we still own.
   -- Once GTA begins result processing these fields belong to GTA.
   local current=s and same(s)
   local restore_ok=true
   if attempted and current and current.phase==9 and not has(current.flags,16)then
    for n=#attempted,1,-1 do
     local f=attempted[n]
     local restored=pcall(function()
      local fresh=assert(same(s));assert(fresh.phase==9 and not has(fresh.flags,16))
      if li(s.hash,f.index)==f.value then
       ScriptLocal.SetInt(s.hash,f.index,f.old)
       assert(li(s.hash,f.index)==f.old)
      end
     end)
     restore_ok=restore_ok and restored
    end
   end
   last='UNAVAILABLE: '..clean(why)
   if not restore_ok then last=last..' Some submitted values could not be restored.'end
   trace(current,last);return false,last
  end
  last='SUBMITTED: '..s.name..'. Waiting for GTA result processing.'
  return true,last
 end
 function c.Tick()
  if not pending then return nil end
  local p=pending
  local s=same(p.context)
  if not s then
   pending=nil;last='UNCONFIRMED: The mission context ended or changed before a result was observed.'
   log(last);return false,last
  end
  local stamp=s.phase..':'..s.flags..':'..s.gate
  if stamp~=p.stamp then trace(s,'observe');p.stamp=stamp end
  for team=0,3 do
   if has(s.flags,20+team)then
    pending=nil;last='FAILED: GTA recorded a failed team. Check the game result.'
    trace(s,last);return false,last
   end
  end
  if s.phase==12 and has(s.flags,16)then
   pending=nil;last='RESULT: GTA reached result processing. Check the result screen and payment.'
   trace(s,last);return true,last
  end
  if h.now()-p.started>=20000 then
   pending=nil;last='UNCONFIRMED: No result stage observed after 20 seconds. Check Show Status.'
   trace(s,last);return false,last
  end
  return nil
 end
 function c.Status()return last end
 function c.ShowStatus()
  local ok,s=pcall(h.capture)
  if ok then
   trace(s,'status')
   pcall(function()
    for team=0,s.teams-1 do
     assert(same(s),'Mission changed during status capture.')
     log('team='..team..' players='..li(s.hash,L.players+team)
      ..' stage='..li(s.hash,L.stage+team)..' score='..li(s.hash,L.score+team)
      ..' goal='..gi(4718592+3838+1+team*26988+59)
      ..' minimum='..gi(4718592+196663+1+team))
    end
   end)
  else log('status unavailable: '..clean(s))end
  return last
 end
 function c.Stop()
  if pending then last='UNCONFIRMED: Observation stopped before confirming a result.'end
  pending=nil
 end
 return c
end
local controller=new_controller(host)
return {Controller=controller,Host=host,NewController=new_controller,Active=active}
end)()


