 local function status(text)if latest~=text then latest=text;log(text)end;return text end
 local function world()local ok,w=pcall(h.world);return ok and w or nil end
 local function current(t)
  local ok,s=pcall(h.lobby)
  if ok and s.identity==t.context.identity then return s end
 end
 local function scope(t,w)
  return w and w.session and w.pid==t.context.pid and w.epoch==t.context.epoch
 end
 local function restore(t,catalogue_only)
  local w=world()
  if not scope(t,w)then return true end
  local s=current(t)
  local matching=w.mission==t.context.mission
  local cancelled=w.mission==0 and w.classic==0 and w.modern==0 and w.launchers==0
  local ordinary=not catalogue_only and matching and w.classic==0 and w.modern==0
   and (w.launchers==0 or s~=nil)
  local all=true
  for n=#t.fields,1,-1 do
   local f=t.fields[n]
   if f.owned then
    local eligible=f.catalogue and (matching or cancelled) and (w.classic==1 or w.launchers==0 or s~=nil)
     or not f.catalogue and ordinary and (f.kind~='l' or s~=nil)
    if eligible then
     local ok=pcall(function()
      local fresh=world();assert(scope(t,fresh),'Restoration context changed.')
      local cancelled_now=fresh.mission==0 and fresh.classic==0 and fresh.modern==0 and fresh.launchers==0
      assert(fresh.mission==t.context.mission or f.catalogue and cancelled_now,'Job changed during restoration.')
      if f.catalogue then
       if not h.catalogue_matches(f.catalogue)then f.owned=false;return end
      else
       assert(fresh.classic==0 and fresh.modern==0 and (fresh.launchers==0 or current(t)),
        'A new mission started during restoration.')
       if f.kind=='l'then assert(current(t),'Launcher instance changed.')end
      end
      if h.read(f.kind,f.index,t.context)==f.value then
       h.write(f.kind,f.index,f.old,t.context)
       assert(h.read(f.kind,f.index,t.context)==f.old,'Restoration readback failed.')
      end
