   local f=t.fields[n]
   if f.attempted then
    local restored=pcall(function()
     same(t.context,true)
     if h.read(f.index,f.field)==f.value then
      h.write(f.index,f.field,f.old)
      assert(h.read(f.index,f.field)==f.old,'Restore readback failed.')
