-- SOURCE MaxPayout.lua; controller body copied without standalone UI registration.
local ApartmentMax=(function()
-- Apartment Crew Cuts | standalone Cherax test
-- Applies only lobby board percentages; no mission, reward or bonus writes.
local TITLE="Apartment Max Payout Test"
local H={
 session=0xD83C2B94E7508980,activity=0x05095437424397FA,
 player=0x4F8644AF03D0E0D6,threads=0x2C83A9DA6BFFC4F9
}
local missions={
 {9188,"Fleeca"}, {9193,"Prison Break"}, {9200,"Humane Labs"},
 {9206,"Series A"}, {9212,"Pacific Standard"}, {9213,"Pacific Standard"},
 {9220,"Pacific Standard"}
}
local function integer(n)return type(n)=="number" and n==n and n%1==0 end
local function native_bool(h,...)
 local ok,v=pcall(Natives.InvokeBool,h,...)
 if ok and type(v)=="boolean" then return v end
 return nil
end
local function native_int(h,...)
 local ok,v=pcall(Natives.InvokeInt,h,...)
 return ok and integer(v) and v or nil
end
local function glob(i)
 local ok,v=pcall(ScriptGlobal.GetInt,i)
 return ok and integer(v) and v or nil
end
local function log(message)
 if type(Logger)=="table" and type(Logger.LogInfo)=="function" then
  pcall(Logger.LogInfo,"["..TITLE.."] "..tostring(message))
 end
end
local function say(message)
 log(message)
 if type(GUI)=="table" and type(GUI.AddToast)=="function" then
  pcall(function()GUI.AddToast(TITLE,tostring(message),5500,eToastPos.TOP_RIGHT)end)
 end
end
local function detect_heist(mission,read)
 if not integer(mission) or mission==0 then return nil end
 local found
 for _,row in ipairs(missions)do
  local root=read(262145+row[1])
  if integer(root) and root~=0 and root%4294967296==mission%4294967296 then
   if found and found~=row[2]then return nil end
   found=row[2]
  end
 end
 return found
end
local function cut_text(values)
 local parts={}
 for n=1,4 do parts[n]=tostring(type(values)=="table" and values[n] or "?")end
 return table.concat(parts," / ")
end
local function new_controller(host)
 local previous,latest,last_watch,last_board="",nil,0,nil
 local api={}
 function api.Check()
  local ok,raw=pcall(host.read)
  if not ok or type(raw)~="table"then
   latest={ok=false,message="Can't read the heist lobby."}
   return latest
  end
  local result={ok=false,script=raw.script,member_mask=raw.member_mask,
   cuts=raw.cuts,matches=raw.matches,consumed=raw.consumed,heist=raw.heist,
   raw=raw}
  local lobby_present=raw.launcher==1 and integer(raw.owner) and raw.owner>=0 and raw.owner<=31
   and integer(raw.member_mask) and raw.member_mask>0
  if raw.session~=true then result.message="Enter GTA Online first."
  elseif raw.classic==1 and raw.modern==0 and not lobby_present then
   result.route="mission"
   if raw.heist==nil or not integer(raw.pid) or raw.pid<0 or raw.pid>31 then
    result.message="Couldn't identify this apartment finale."
   elseif not integer(raw.consumed) or raw.consumed<0 or raw.consumed>9999 then
    result.message="Mission payout field isn't available."
   else
    result.ok=true
    result.message=raw.heist.." | After lobby, payout field: "..tostring(raw.consumed).."%"
    if last_board and last_board.mission==raw.mission and last_board.pid==raw.pid then
     result.last_board={table.unpack(last_board.cuts)}
     result.message=result.message.." | Last lobby: "..cut_text(result.last_board).."%"
    end
   end
  elseif (raw.classic or 0)>0 and (raw.modern or 0)>0 and not lobby_present then
   result.message="Mission controller is changing."
  -- GTA marks heist preparation as an activity too. Read the launcher first.
  elseif raw.launcher~=1 then
   result.message=raw.activity==true and "No finale lobby is active."
    or "Open an apartment finale lobby to see crew cuts."
  elseif raw.heist==nil then result.message="This lobby isn't showing an apartment heist."
  elseif not integer(raw.pid) or raw.pid<0 or raw.pid>31 then result.message="Couldn't read your player."
  elseif raw.member_mask==0 or raw.owner==-1 then result.message="Lobby data has cleared. Waiting for the mission."
  elseif raw.owner~=raw.pid then result.message="Only the finale host can confirm crew cuts."
  elseif type(raw.cuts)~="table" or #raw.cuts~=4 then result.message="Crew cuts are unavailable."
  else
   local sum=0
   for i=1,4 do
    local val=raw.cuts[i]
    if not integer(val) or val<0 or val>9999 then
     result.message="Board cuts: "..cut_text(raw.cuts).." | Other set: "..cut_text(raw.mirror_cuts)
      .." | Board has an invalid percentage."
     latest=result;return result
    end
    sum=sum+val
   end
   result.ok=true;result.total=sum
   result.route="lobby"
   if integer(raw.mission) and integer(raw.member_mask) and raw.member_mask>0 then
    last_board={mission=raw.mission,pid=raw.pid,cuts={table.unpack(raw.cuts)}}
   end
   result.message=raw.heist..": "..table.concat(raw.cuts," / ").."%"
   if raw.member_mask~=nil then result.message=result.message
      .." | crew mask "..tostring(raw.member_mask) end
   -- The other set is diagnostic only; differing legacy values do not invalidate B.
  end
  latest=result
  return result
 end
 function api.Snapshot()return latest end
 function api.Apply(requested)
  if type(requested)~="table" or #requested~=4 then return false,"Enter four crew cuts." end
  local wanted={}
  for n=1,4 do
   local v=requested[n]
   if not integer(v) or v<0 or v>9999 then return false,"Use whole percentages from 0 to 9999." end
   wanted[n]=v
  end
  local start=api.Check()
  if not start.ok or start.route~="lobby" then return false,"Open your own finale lobby before applying cuts." end
  local captured=start.raw
  if not integer(captured.mission) or not integer(captured.member_mask)
   or captured.member_mask<1 or captured.member_mask>15 then return false,"Crew slots aren't ready." end
  for n=1,4 do
   if (captured.member_mask & (1<<(n-1)))==0 and wanted[n]~=0 then
    return false,"Player "..n.." isn't in the crew. Set that cut to 0."
   end
  end
  local before={table.unpack(captured.cuts)}
  local expected={table.unpack(before)}
  local function inspect()
   local ok,r=pcall(host.read)
   if not ok or type(r)~="table" or r.session~=true or r.launcher~=1
    or r.pid~=captured.pid or r.owner~=captured.owner or r.mission~=captured.mission
    or r.heist~=captured.heist or r.member_mask~=captured.member_mask
    or type(r.cuts)~="table" or #r.cuts~=4 then return nil end
   return r
  end
  local attempted={}
  local function fail(reason)
   local restored=true
   for j=#attempted,1,-1 do
    local n=attempted[j];local r=inspect()
    if not r then restored=false
    elseif r.cuts[n]==wanted[n] then
     pcall(host.write_cut,n,before[n])
     local fresh=inspect()
     if not fresh or fresh.cuts[n]~=before[n] then restored=false end
    elseif r.cuts[n]~=before[n] then restored=false end
   end
   return false,reason..(restored and " Previous values preserved." or " Some values changed; check the board.")
  end
  for n=1,4 do
   local r=inspect()
   if not r then return fail("Lobby changed.")end
   for slot=1,4 do if r.cuts[slot]~=expected[slot] then return fail("Crew cuts changed during apply.")end end
   if before[n]~=wanted[n] then
    attempted[#attempted+1]=n
    local ok,accepted=pcall(host.write_cut,n,wanted[n])
    if not ok or accepted~=true then return fail("Couldn't set player "..n.."'s cut.")end
    expected[n]=wanted[n]
   end
  end
  local final=inspect()
  if not final then return fail("Lobby changed before confirmation.")end
  for n=1,4 do if final.cuts[n]~=wanted[n] then return fail("GTA didn't retain the selected cuts.")end end
  api.Check()
  return true,"Board cuts set: "..cut_text(wanted).."%."
 end
 function api.Watch()
  local now=host.now()
  if not integer(now) or now<last_watch or now-last_watch<650 then return nil end
  last_watch=now
  local r=api.Check()
  local signature=(r.message or "")..tostring(r.total)..tostring(r.consumed)
  if previous==signature then return nil end
  previous=signature
  return r
 end
 return api
end
local host={}
function host.now()
 local ok,v=pcall(function()return Time.GetEpocheMs()end)
 return ok and integer(v) and v or math.floor((os.clock()or 0)*1000)
end
function host.read()
 local session=native_bool(H.session)
 local activity=native_bool(H.activity)
 local pid=native_int(H.player)
 local launcher=native_int(H.threads,Utils.Joaat("fmmc_launcher"))
 local mission=glob(4858023)
 local cuts={}
 -- Verified against the visible Prison Break board at 55%, 26% and 0%.
 for i=1,4 do cuts[i]=glob(1941382+i) end
 local mirrors,match={},true
 for i=1,4 do
  mirrors[i]=glob(1936407+i)
  if mirrors[i]~=cuts[i] then match=false end
 end
 return {
  session=session,activity=activity,pid=pid,owner=glob(1942042),
  launcher=launcher,mission=mission,
  classic=native_int(H.threads,Utils.Joaat("fm_mission_controller")),
  modern=native_int(H.threads,Utils.Joaat("fm_mission_controller_2020")),
  heist=detect_heist(mission,glob),cuts=cuts,mirror_cuts=mirrors,
  matches=match,member_mask=glob(1941375),consumed=glob(2692687),
  remainder=glob(1936412),host_remainder=glob(1941387),
 }
end
function host.write_cut(slot,value)
 -- B is the board source verified in live tests. No legacy/mission writes.
 if not integer(slot) or slot<1 or slot>4 or not integer(value) then return false end
 local ok,accepted=pcall(ScriptGlobal.SetInt,1941382+slot,value)
 return ok and accepted~=false and glob(1941382+slot)==value
end
-- Reward projection extracted from the existing apartment payout model.
-- The configured $3m target is not represented as a verified server cap.
local function finite(v)return type(v)=='number' and v==v and v~=math.huge and v~=-math.huge end
local function f32(v)return (string.unpack('f',string.pack('f',v)))end
local function rounded(v)return math.floor(f32(v)+0.5)end
local function estimate(reward,cut)
 local amount=rounded(f32(f32(reward.pool)*f32(f32(cut)/f32(100)))*f32(reward.cut_multiplier))
 for _,factor in ipairs(reward.settlement)do amount=rounded(f32(amount)*f32(factor))end
 return rounded(f32(f32(amount)/f32(10)))*10
end
local function calculate(snapshot,reward,target)
 if type(snapshot)~='table' or snapshot.ok~=true or snapshot.route~='lobby' then return nil,'Open your apartment finale lobby.' end
 local r=snapshot.raw
 if type(r)~='table' or r.session~=true or r.launcher~=1 or r.owner~=r.pid
  or not integer(r.pid) or r.pid<0 or r.pid>31 or not integer(r.mission)
  or not integer(r.member_mask) or r.member_mask<1 or r.member_mask>15 then return nil,'Lobby or crew is not ready.'end
 if not integer(target) or target<1 or target>3000000 then return nil,'Choose a target from $1 to $3,000,000.'end
 if type(reward)~='table' or not finite(reward.pool) or reward.pool<=0 or reward.pool>2147483647
  or not finite(reward.cut_multiplier) or reward.cut_multiplier<=0 or reward.cut_multiplier>100
  or type(reward.settlement)~='table' or #reward.settlement~=3 then return nil,'Reward inputs are not ready.'end
 for _,v in ipairs(reward.settlement)do if not finite(v) or v<=0 or v>100 then return nil,'Reward multiplier is not ready.'end end
 local p={cuts={0,0,0,0},amounts={0,0,0,0},target=target,reward=reward,raw=r}
 local key={r.mission,r.pid,r.owner,r.member_mask,target,reward.pool,reward.cut_multiplier}
 for _,v in ipairs(reward.settlement)do key[#key+1]=v end
 for _,o in ipairs(reward.observations or {})do key[#key+1]=o.index..':'..o.kind..':'..o.value end
 for n=1,4 do if (r.member_mask & (1<<(n-1)))~=0 then
  local lo,hi=0,9999
  while lo<hi do local mid=(lo+hi+1)//2;if estimate(reward,mid)<=target then lo=mid else hi=mid-1 end end
  p.cuts[n]=lo;p.amounts[n]=estimate(reward,lo)
 end end
 p.key=table.concat(key,':');return p
end
local function summary(p)
 return 'Cuts: '..cut_text(p.cuts)..'% | Estimated per player: $'..cut_text(p.amounts)
end
local function new_automatic(h)
 local previous,blocked,last_time=nil,nil,nil
 local api={}
 function api.Reset()previous=nil;blocked=nil;last_time=nil end
 function api.Tick(target,force)
  local now=h.now()
  if not integer(now) or now<0 then return {ok=false,message='Clock is not ready.'}end
  if not force and last_time and now>=last_time and now-last_time<700 then return nil end
  last_time=now
  local ok,s=pcall(h.snapshot)
  if not ok or type(s)~='table' then return {ok=false,message='Cannot read the heist.'}end
  if s.route=='mission' then
   return {ok=s.ok,route='mission',message='Mission started. No board changes. Payout field: '..tostring(s.consumed)..'%'}
  end
  if blocked then return {ok=false,message=blocked}end
  local got,rewards,why=pcall(h.rewards,s)
  if not got or type(rewards)~='table' then return {ok=false,message=got and (why or 'Waiting for reward data.') or tostring(rewards)}end
  local p,reason=calculate(s,rewards,target)
  if not p then return {ok=false,message=reason}end
  if previous and previous.key==p.key then
   for n=1,4 do if s.raw.cuts[n]~=previous.cuts[n]then
    blocked='Cuts changed elsewhere. Switch Auto off and on to resume.'
    return {ok=false,message=blocked}
   end end
   return {ok=true,message=summary(p),plan=p}
  end
  local applied,accepted,message=pcall(h.apply,p)
  if not applied or accepted~=true then
   blocked='Apply stopped: '..tostring(applied and message or accepted)..'. Switch Auto off and on to retry.'
   return {ok=false,message=blocked}
  end
  previous=p
  return {ok=true,message=summary(p),plan=p}
 end
 return api
end
local reward_rows={
 ['Fleeca']={25,9258,38200},['Prison Break']={22,9259,38201},['Humane Labs']={23,9260,38202},
 ['Series A']={24,9261,38203},['Pacific Standard']={21,9262,38204},
}
local function read_rewards(snapshot)
 if not snapshot or snapshot.ok~=true or snapshot.route~='lobby' then return nil,'Waiting for your finale lobby.'end
 local ok,result=pcall(function()
  local observations={}
  local function read(index,kind)
   local v=kind=='float' and ScriptGlobal.GetFloat(index) or ScriptGlobal.GetInt(index)
   assert(finite(v) and (kind=='float' or integer(v)),'Reward field unavailable: '..index)
   observations[#observations+1]={index=index,kind=kind or 'int',value=v};return v
  end
  local function ti(n)return read(262145+n)end
  local function tf(n)return read(262145+n,'float')end
  local row=assert(reward_rows[snapshot.raw.heist],'Unknown apartment heist.')
  assert(read(4718592+139900)==row[1],'Waiting for the finale reward selector.')
  local difficulty=read(4718592+3771);assert(difficulty>=0 and difficulty<=2,'Difficulty is unavailable.')
  local base,dm=ti(row[2]),tf(9328+difficulty)
  assert(base>0 and dm>0 and dm<=100,'Base reward is unavailable.')
  local low,high=ti(8425),ti(8426)
  assert(low>=0 and high>=low and high<=2147483647,'Reward bounds are unavailable.')
  local pool=math.max(low,math.min(high,rounded(f32(base)*f32(dm))))
  local first,repeat_factor=tf(8423),tf(8424)
  assert(first>0 and first<=100 and repeat_factor>0 and repeat_factor<=100,'Replay reward factors are unavailable.')
  local local_switch,host_switch=ti(8571),ti(8572)
  assert((local_switch==0 or local_switch==1)and(host_switch==0 or host_switch==1),'Membership switches are unavailable.')
  local member=tf(8574);assert(member>=0 and member<=100,'Membership factor is unavailable.')
  local membership=(local_switch==1 or host_switch==1)and math.max(1,member)or 1
  local global_factor,event_factor=tf(0),tf(row[3])
  assert(event_factor>=0 and event_factor<=100,'Event factor is unavailable.')
  assert(tf(2403)==0 and tf(2407)==0,'Additional reward floor or ceiling is active.')
  return {pool=pool,cut_multiplier=math.max(first,repeat_factor),
   settlement={membership,global_factor,math.max(1,event_factor)},observations=observations,
   base=base,difficulty=difficulty,difficulty_factor=dm}
 end)
 return ok and result or nil,not ok and tostring(result) or nil
end
local function rewards_match(p)
 for _,o in ipairs(p.reward.observations)do
  local ok,v=pcall(o.kind=='float' and ScriptGlobal.GetFloat or ScriptGlobal.GetInt,o.index)
  if not ok or v~=o.value then return false end
 end
 return true
end
local cuts=new_controller(host)
local applying=nil
local original_write=host.write_cut
host.write_cut=function(slot,value)
 if applying and not rewards_match(applying)then return false end
 return original_write(slot,value)
end
local automatic_host={now=host.now,snapshot=function()return cuts.Check()end,rewards=read_rewards}
function automatic_host.apply(p)
 if not rewards_match(p)then return false,'Reward inputs changed' end
 local current=cuts.Check()
 local fresh,why=read_rewards(current)
 local fresh_plan=fresh and calculate(current,fresh,p.target)
 if not fresh_plan or fresh_plan.key~=p.key then return false,why or 'Lobby or reward changed' end
 applying=p
 local ran,ok,message=pcall(cuts.Apply,p.cuts)
 applying=nil
 if not ran then return false,tostring(ok)end
 if ok and not rewards_match(p)then return false,'Reward changed after the board write; check current cuts' end
 return ok,message
end
local automatic=new_automatic(automatic_host)
return {Controller=automatic,Cuts=cuts,Host=host,Calculate=calculate,ReadRewards=read_rewards,NewAutomatic=new_automatic}
end)()


