  local sound=b.base+b.sound
  if api.gi(sound)~=0 and api.gi(sound+1)>=0 then s.sounds[#s.sounds+1]={active=sound,index=sound+1,id=api.gi(sound+1)} end
  if b.base==F and api.gi(sound+2)~=0 and api.gi(sound+3)>=0 then s.sounds[#s.sounds+1]={active=sound+2,index=sound+3,id=api.gi(sound+3)} end
  local function add(i,v) s.writes[#s.writes+1]={index=i,old=api.gi(i),value=v} end
  for i=0,6 do add(F+718+i,0) end -- exact func_960 STORE_N 7
  for i=0,9 do add(F+794+i,0) end -- exact func_958 STORE_N 10
  add(F+700,0);add(F+701,1);add(F+702,1);add(F+703,0)
  add(F+717,render) -- existing named RT skips func_885 registration assignment
  add(F+812+415,0);add(F+812+416,0);add(F+812+417,0)
  local header=api.gi(F+812+110)
  if header~=19 and header~=0 then return "reopen","Unknown finale plan array layout" end
  add(F+812+110,19) -- source header; v3 incorrectly zeroed this cell
  for i=0,18 do add(F+812+110+1+i*16,0) end -- correct payload cells
  add(F+1247,api.gi(F+1247) & ~1) -- preserve ownership bit5, clear init0
  t.doomsday_refresh=s
  local ok,err=pcall(function()
   assert(context(t,s),"Context changed before publication")
   for _,w in ipairs(s.writes) do assert(api.gi(w.index)==w.old,"Presentation changed before publication") end
   for _,w in ipairs(s.writes) do
    s.count=s.count+1;api.si(w.index,w.value)
    assert(api.gi(w.index)==w.value,"Presentation prefix write failed")
   end
  end)
  if not ok then
   local restored=context(t,s) and rollback(s);t.doomsday_refresh=nil
   return "reopen",tostring(err)..(restored and "; prefix restored" or "; prefix conflict")
  end
  -- Publication starts before any resource release. Never restore the old
  -- image after this boundary, including when acknowledgement times out.
  s.published=true;s.started=api.now()
  local published,why=pcall(function()
   for _,v in ipairs(s.sounds) do
    api.nv(0xA3B0C41BA5CC0BB5,v.id);api.nv(0x353FC880830B88FA,v.id)
    api.si(v.index,-1);api.si(v.active,0)
   end
   for _,v in ipairs(s.movies) do api.release_movie(v.handle);api.si(v.index,0) end
   api.sl(218,0) -- existing main -> func_885 -> ordinary finale boot states
   assert(api.li(218)==0,"Presentation state was not published")
   s.committed=true
  end)
  if not published then s.error=tostring(why);return "reopen","Published rebuild failed; stale globals were not restored" end
  return "pending"
 end
 local function rebuild_ack(t)
  local s=t.doomsday_refresh
  if not s or not s.committed or not context(t,s) then return false end
  if api.li(218)~=3 or api.gi(F+853)~=s.pid or api.gi(F+889)~=s.act then return false end
  -- Enteredstate3, previousstate2, consumed exitbit2 proves source
  -- func_448->func_449 SHOW_FINALE ran after this presentation reset.
  if api.gi(F+718)~=3 or api.gi(F+719)~=2 or not bit(api.gi(F+721),3) or bit(api.gi(F+722),2) then return false end
  return api.gi(F+717)==s.render and api.nb(0x85F01B8D5B90570E,api.gi(F+714))==true
 end
 -- v4 in-place repair; UPDATE_FINALE_PLAN removes old ActionScript list items.
 local H,REWARD=F+812+110,F+812+43
 local BEGIN,END_METHOD,ADD_INT=0xF6E48914C7A8694E,0xC6796A8FFA375E53,0xC3D0841A0CC546A6
 local FRAME=0xFC8202EFC642E6F2
 local prefixes={"HP_IAA_STEP_","HP_SUB_STEP_A","HP_MSI_STEP_"}
 local tunable_names={"GANGOPS_THE_IAA_JOB_CASH_REWARD","GANGOPS_THE_SUBMARINE_JOB_CASH_REWARD","GANGOPS_THE_MISSILE_SILO_JOB_CASH_REWARD"}
 local function act_of(t)return ({[1]=0,[2]=1,[4]=2})[t.expected.GANGOPS_HEIST_STATUS & 7]end
 local function float32(v)return string.unpack("<f",string.pack("<f",v))end
 local function read_float(index)
  if api.gf then return api.gf(index) end
  return string.unpack("<f",string.pack("<I4",api.gi(index)&0xFFFFFFFF))
 end
 local function reward_for(t,act)
  -- func909 selected types26/27/28, func901's non-activity multiplier/cap.
  assert(api.nb(0x05095437424397FA)~=true,"Activity reward outside Facility display repair")
  local index=262145+9263+act
  local base=api.tunable_int and api.tunable_int(tunable_names[act+1],index) or api.gi(index)
  assert(type(base)=="number" and base%1==0 and base>0 and base<=2147483647,"Selected reward tunable unavailable")
  local flag=5+act
  local disabled=api.gi(262145+38231)~=0 or api.gi(262145+38232+1+flag)~=0
  local completed=bit(api.gi(1912812+1+t.context.pid*322+320),flag)
  local multiplier=1
  if not disabled and not completed then multiplier=read_float(262145+38205+act) end
  assert(type(multiplier)=="number" and multiplier==multiplier and multiplier>0 and multiplier<100,"Selected reward multiplier unavailable")
  local reward=api.ni(0xF2DB717A73826179,float32(float32(base)*float32(multiplier)))
  local cap=api.gi(262145+23030)
  assert(type(cap)=="number" and cap%1==0 and cap>0,"Normal reward display cap unavailable")
  reward=math.min(reward,cap)
  assert(reward>0 and reward<=2147483647 and reward%1==0,"Invalid normal reward display")
  return reward
 end
 local function plan_labels(act)
  local prefix=prefixes[act+1]
  if act==1 then
   local role=api.gi(F+812+415)
   assert(role==0 or role==1,"Bogdan plan role not initialized")
   if role==1 then prefix="HP_SUB_STEP_B" end
  end
  local labels,valid={},{}
  for i=0,18 do
   local label=prefix..i
   if api.nb(0xAC09CA973C564252,label)==true then labels[i+1]=label;valid[#valid+1]=label
   else labels[i+1]="" end
  end
  assert(#valid>0,"Selected briefing labels unavailable")
  return labels,valid
 end
 local function surface_context(t,s)
  if not context(t,s) then return false end
  local act=act_of(t)
  if act==nil or api.li(218)~=3 or api.gi(F+853)~=t.context.pid or api.gi(F+889)~=act then return false end
  if api.gi(F+718)~=3 or api.gi(F+723)~=0 then return false end
  local flags=api.gi(F+1247)
  if not bit(flags,0) then return false end
  for _,n in ipairs({1,2,16,17})do if bit(flags,n)then return false end end
  local player=1882797+1+t.context.pid*321+43
  if bit(api.gi(player+27),3) or bit(api.gi(player+27),6) or api.gi(1970544)~=0 then return false end
  for key,off in pairs({GANGOPS_HEIST_STATUS=26,GANGOPS_FLOW_MISSION_PROG=23,GANGOPS_FM_MISSION_PROG=24})do
   local observed=api.gi(player+off)
   if key=="GANGOPS_HEIST_STATUS"then
    if (observed|64)~=(t.expected[key]|64)then return false end
   elseif observed~=t.expected[key]then return false end
  end
  local header=api.gi(H)
  if header~=0 and header~=19 then return false end
  local movie=api.gi(F+714)
  if movie<=0 or api.nb(0x85F01B8D5B90570E,movie)~=true then return false end
  local name="Prop_x17DLC_Monitor_Wall_01a"
  if api.nb(0x78DCDC15C9F116B4,name)~=true then return false end
  local render=api.ni(0x1A6478B61C6BDC3B,name)
  return render>0 and api.gi(F+717)==render and (not s or not s.movie or s.movie==movie)
 end
 local function call_method(movie,name,body)
  assert(api.nb(BEGIN,movie,name)==true,"Scaleform method rejected: "..name)
  local ok,err=pcall(body)
  local ended,enderr=pcall(api.nv,END_METHOD)
  assert(ok,err);assert(ended,enderr)
 end
 local function repair_surface(t,s)
  assert(surface_context(t,s),"Owned finale display changed before repair")
  assert(api.gs and api.ss,"Doomsday repair needs global string read/write")
  local act=assert(act_of(t));local reward=reward_for(t,act)
  local labels,valid=plan_labels(act)
  assert(api.gi(F+812+50)==5,"Finale distribution array header changed")
  local shares,total={},0
  for i=0,4 do
   local v=api.gi(F+812+50+1+i)
   assert(v%1==0 and v>=0 and v<=100,"Invalid existing distribution")
   shares[i+1]=v;total=total+v
  end
  assert(total==100,"Existing reward distribution not initialized")
  local writes={{index=H,old=api.gi(H),value=19},{index=REWARD,old=api.gi(REWARD),value=reward}}
  for i=0,18 do
   local index=H+1+i*16
   writes[#writes+1]={index=index,old=api.gs(index),value=labels[i+1],text=true}
  end
  local count=0
  local function read(w)return w.text and api.gs(w.index) or api.gi(w.index)end
  local function write(w,v)if w.text then api.ss(w.index,v)else api.si(w.index,v)end end
  local ok,err=pcall(function()
   for _,w in ipairs(writes)do assert(read(w)==w.old,"Display changed before repair")end
   for _,w in ipairs(writes)do count=count+1;write(w,w.value);assert(read(w)==w.value,"Display repair rejected")end
  end)
  if not ok then
   local restore=surface_context(t,s)
   if restore then
    for i=1,count do local w=writes[i];local v=read(w);if v~=w.old and v~=w.value then restore=false;break end end
   end
   if restore then for i=count,1,-1 do local w=writes[i];if read(w)==w.value then write(w,w.old)end end end
   error(tostring(err)..(restore and "; display prefix restored" or "; display prefix conflict"))
  end
  -- Only display caches. No cuts, payout/global mission type or tunable writes.
  s.published=true;s.surface_published=true;s.movie=api.gi(F+714);s.act=act
  call_method(s.movie,"UPDATE_FINALE_PLAN",function()
   for _,label in ipairs(valid)do
    api.nv(0x80338406F3475E55,label)
    api.nv(0x362E2D3FE93A9959)
   end
  end)
  call_method(s.movie,"UPDATE_CASH_DISTRIBUTION",function()
   for _,share in ipairs(shares)do api.nv(ADD_INT,(reward//100)*share)end
  end)
  s.display_reward=reward;s.labels=labels;s.plan_count=#valid
  s.surface_frame=api.ni(FRAME);s.surface_done=true
  if api.log then api.log("Doomsday display repaired act="..(act+1).." planItems="..#valid.." reward="..reward.." header="..api.gi(H))end
 end
 local function surface_ack(t,s)
  if not s or not s.surface_done or not surface_context(t,s) then return false end
  if api.ni(FRAME)==s.surface_frame or api.gi(H)~=19 or api.gi(REWARD)~=s.display_reward then return false end
  for i=0,18 do if api.gs(H+1+i*16)~=s.labels[i+1]then return false end end
  t.presentation_token={version=4,ptr=s.ptr,movie=s.movie,act=s.act,reward=s.display_reward,labels=s.labels}
  return true
 end
 local function request(t)
  local s=t.doomsday_refresh
  if s and s.surface_done then return "pending" end
  -- Already-selected finale, including v3's header0: fix it in place without
  -- resetting crew/cuts, replaying SHOW_FINALE or releasing/requesting a movie.
  if not s and surface_context(t) then
   s={ptr=api.ptr(),pid=t.context.pid,inplace=true,published=false,started=api.now()}
   t.doomsday_refresh=s;repair_surface(t,s)
   return "pending"
  end
  return rebuild_request(t)
 end
 local function ack(t)
  local s=t.doomsday_refresh
  if s and s.surface_done then return surface_ack(t,s) end
  if not rebuild_ack(t)then return false end
  repair_surface(t,s)
  return false -- require a later game frame after the explicit clear/update
 end
 local function reuse(previous,current)
  local token=previous and previous.presentation_token
  if not token or token.version~=4 or not api.gs then return false end
  -- Reuse performs NO mutations, so a healthy screen may stay interactive.
  if not context(current,{ptr=token.ptr}) or act_of(current)~=token.act then return false end
  if api.li(218)~=3 or api.gi(F+853)~=current.context.pid or api.gi(F+889)~=token.act then return false end
  local state=api.gi(F+718)
  if state~=3 and state~=4 then return false end
  if api.gi(F+714)~=token.movie or api.nb(0x85F01B8D5B90570E,token.movie)~=true then return false end
  local flags=api.gi(F+1247)
  if not bit(flags,0) or bit(flags,17) then return false end
  if api.gi(H)~=19 or api.gi(REWARD)~=reward_for(current,token.act)then return false end
  local labels=plan_labels(token.act)
  for i=0,18 do if api.gs(H+1+i*16)~=labels[i+1]then return false end end
  current.presentation_token=token
  return true
 end
 local function recovery(t)
  local s=t and t.doomsday_refresh
  if s and s.inplace then return "Preps applied. Close the planning screen, then Apply again to repair its display." end
  if s and s.published then return "Preps applied. Reenter the Facility planning room to recover the display." end
 end

 return {
  request=request,ack=ack,reuse=reuse,recovery=recovery,
  release=function(t,reason)
   local s=t.doomsday_refresh
   if s and not s.published and context(t,s) then rollback(s) end
   if s then s.release_reason=reason end -- keep audit; no post-publication restore
  end,
  metadata={version=4,experimental=true,live_tested=false,patterns=patterns,
   pattern_pcs={0xCA,0x31780,0x342DE,0x6AAC,0x1CD5E},
   acknowledgement="Correct plan header/labels, selected-act reward and clear/update method; visual check pending"},
 }
end

end)()
P.refresh_factory=function(api)return refresh_factory(api,P)end
-- Shared source used to build three independent, standalone prototypes.
local function int(v)return type(v)=='number' and v%1==0 and v>=-2147483648 and v<=2147483647 end
local function clean(v)return tostring(v):gsub('^.-:%d+:%s*','')end
local function new_controller(h,profile)
 local pending,last_completed,last_choice,last_seed
 local reopen=profile.refresh and profile.refresh.reopen_message
  or (profile.family=='doomsday' and 'Preps applied. Leave the planning room, then return.'
  or 'Preps applied. Reopen the planning screen.')
 local c={}
 local function trace(t,label)if h.trace then pcall(h.trace,t,label)end end
 local function release(t,reason)if t and h.release then pcall(h.release,t,reason)end end
 local function recovery(t)
  if h.recovery then local ok,message=pcall(h.recovery,t);if ok and message then return message end end
  return reopen
 end
 local function equivalent(key,expected,observed)
  if expected==observed then return true end
  local mask=profile.runtime_stat_additions and profile.runtime_stat_additions[key]
  return mask and int(expected) and int(observed) and (expected|observed)==observed
   and ((expected~observed)&~mask)==0
 end
 local function owned(t)
  h.check(t.context)
  for _,f in ipairs(t.fields)do
   local observed=h.read(t.context,f.key)
   if observed~=f.value and equivalent(f.key,f.value,observed)then f.value=observed;t.expected[f.key]=observed end
   -- func885 adds its own first-planning-room help latch after publication.
   -- Accept only that observed addition; selected act and every other bit stay exact.
   if profile.family=='doomsday' and f.key=='GANGOPS_HEIST_STATUS'
    and t.doomsday_refresh and t.doomsday_refresh.published and observed==(f.value|64)then
    f.value=observed;t.expected[f.key]=observed
   end
   assert(observed==f.value,'Heist selection changed. Apply again.')
  end
 end
 function c.Apply(selection)
  if pending then return false,'Still applying.' end
  local t={fields={}}
  local ok,err=pcall(function()
   t.context=h.context();h.check(t.context)
   local old,allowed={},{}
   for _,key in ipairs(profile.stat_keys)do
    allowed[key]=true;old[key]=h.read(t.context,key)
    assert(int(old[key]),'Could not read prep data.')
   end
   for _,key in ipairs(profile.context_stat_keys or {})do
    old[key]=h.read(t.context,key);assert(int(old[key]),'Could not read heist context.')
   end
   if profile.stable_repeats then
    local parts={t.context.identity or ''}
    for _,selector in ipairs(profile.selectors or {})do parts[#parts+1]=selector.key..'='..tostring(selection[selector.key])end
    t.choice_key=table.concat(parts,'|')
    local normalized={};for key,value in pairs(selection)do normalized[key]=value end
    if last_choice==t.choice_key then normalized.seed=last_seed
    else last_choice=t.choice_key;last_seed=normalized.seed or h.now();normalized.seed=last_seed end
    selection=normalized
   end
   if profile.context_globals then old._globals=h.read_globals(t.context)end
   local values=profile.build(selection,old)
   for key,v in pairs(values)do assert(allowed[key] and int(v),'Invalid prep value.')end
   for _,key in ipairs(profile.stat_keys)do
    assert(int(values[key]),'Missing prep value.')
    t.fields[#t.fields+1]={key=key,old=old[key],value=values[key]}
   end
   t.expected=values;t.old=old;trace(t,'before')
   if profile.stable_repeats and last_completed and last_completed.choice_key==t.choice_key
    and last_completed.context.identity==t.context.identity and h.reuse_display then
    local unchanged=true
    for _,f in ipairs(t.fields)do
     if f.old~=f.value or not equivalent(f.key,last_completed.expected[f.key],f.value)then unchanged=false;break end
    end
    if unchanged then
     local rok,current=pcall(h.reuse_display,last_completed,t)
     if rok and current then t.unchanged=true;return end
    end
   end
   -- No yield between related writes. Snapshot all inputs before publication.
   for _,f in ipairs(t.fields)do
    h.check(t.context)
    assert(h.read(t.context,f.key)==f.old,'Prep data changed. Apply again.')
    if f.old~=f.value then
     f.attempted=true;h.write(t.context,f.key,f.value)
     h.check(t.context)
     assert(h.read(t.context,f.key)==f.value,'Prep write was not accepted.')
    end
   end
   owned(t)
   t.deadline=h.now()+3000;t.stage='cache';trace(t,'written')
   pending=t
  end)
  if not ok then
   trace(t,'write failure: '..clean(err))
   local restored=true
   for i=#t.fields,1,-1 do
    local f=t.fields[i]
    if f.attempted then
     local rok=pcall(function()
      h.check(t.context)
      if h.read(t.context,f.key)==f.value then h.write(t.context,f.key,f.old)end
     end)
     restored=restored and rok
    end
   end
   release(t,'write failure')
   return false,clean(err)..(restored and '' or ' Some prep data may already be applied.')
  end
  return true,t.unchanged and 'Already applied.' or 'Applying...'
 end
 function c.Tick()
  local t=pending;if not t then return nil end
  local ok,message=pcall(function()
   owned(t)
   if h.now()>=t.deadline then trace(t,'refresh timeout');return recovery(t)end
   if not h.mirrors(t)then
    if not t.cache_wait_logged then t.cache_wait_logged=true;trace(t,'waiting for cache')end
    return nil
   end
   if not t.cache_confirmed then t.cache_confirmed=true;trace(t,'cache matched')end
   if t.stage=='cache'then
    local result=h.refresh(t)
    if t.presentation_started_at and not t.presentation_window_set then
     t.presentation_window_set=true;t.deadline=t.presentation_started_at+3000
    end
    if result=='none'then return 'Preps applied. Open the planning board.' end
    if result=='reopen'then return recovery(t)end
    if result=='wait'then return nil end
    assert(result=='pending','Unknown board refresh state.')
    t.stage='redraw'
   end
   if h.ack(t)then last_completed=t;return 'Preps applied.' end
   return nil
  end)
  if not ok then
   local fallback
   if h.recovery then local rok,msg=pcall(h.recovery,t);if rok then fallback=msg end end
   release(t,'error');pending=nil
   return fallback or ('Preps applied. '..clean(message))
  end
  if message then release(t,message);pending=nil end
  return message
 end
 function c.Unload()release(pending,'unload');pending=nil end
 return c
end
if TEST_ONLY then return {NewController=new_controller}end

local function ni(hash,...)local v=Natives.InvokeInt(hash,...);assert(int(v),'GTA integer read failed.');return v end
local function nb(hash,...)local v=Natives.InvokeBool(hash,...);assert(type(v)=='boolean','GTA boolean read failed.');return v end
local function gi(index)local v=ScriptGlobal.GetInt(index);assert(int(v),'Planning data unavailable.');return v end
local function gf(index)
 local v=ScriptGlobal.GetFloat(index)
 assert(type(v)=='number' and v==v and v>-math.huge and v<math.huge,'Planning multiplier unavailable.')
 return v
end
local function li(hash,index)local v=ScriptLocal.GetInt(hash,index);assert(int(v),'Planning script unavailable.');return v end
local function stat(name)
 local ptr=Memory.AllocInt();assert(type(ptr)=='number' and ptr>0,'Stat buffer unavailable.')
 local ok,value=pcall(function()
  Memory.WriteInt(ptr,0)
  assert(nb(0x767FBC2AC802EF3D,Utils.Joaat(name),ptr,-1),'Could not read '..name..'.')
  local v=Memory.ReadInt(ptr);assert(int(v),'Invalid stat value.');return v
 end)
 local released=pcall(Memory.Free,ptr);assert(released,'Stat buffer could not be released.')
 assert(ok,value);return value
end
local function count(name)return ni(0x2C83A9DA6BFFC4F9,Utils.Joaat(name))end
local function log(message)
 if Logger and Logger.LogInfo then pcall(Logger.LogInfo,'[Prep prototype v5 / '..P.family..'] '..tostring(message))end
end
local function say(message)
 log(message)
 if GUI and GUI.AddToast then pcall(GUI.AddToast,P.title,message,4500,eToastPos.TOP_RIGHT)end
end
local host={}
function host.now()return Time.GetEpocheMs()end
function host.context()
 assert(nb(0xD83C2B94E7508980) and not nb(0x68049AEFF83D8F0A)
  and not nb(0x05095437424397FA),'Return to GTA Online freemode first.')
 assert(count('freemode')==1 and count('fm_mission_controller')==0
  and count('fm_mission_controller_2020')==0 and not nb(0xA33CDCCDA663159E),'Finish the current mission first.')
 local pid=ni(0x4F8644AF03D0E0D6);local slot=stat('MPPLY_LAST_MP_CHAR')
 assert(pid>=0 and pid<=31 and (slot==0 or slot==1),'Character unavailable.')
 local prefix='MP'..slot..'_'
 local freemode_ptr=ScriptLocal.GetPtr(Utils.Joaat('freemode'),0)
 assert(type(freemode_ptr)=='number' and freemode_ptr>=65536,'Freemode unavailable.')
 local context={pid=pid,slot=slot,prefix=prefix,freemode_ptr=freemode_ptr}
 context.identity=table.concat({pid,slot,freemode_ptr},':')
 return context
end
function host.read(context,key)return stat(context.prefix..key)end
function host.check(context)
 local fresh=host.context()
 assert(context and fresh.identity==context.identity,'Character or session changed.')
 for _,guard in ipairs(P.required_stat_bits or {})do
  assert((host.read(context,guard.key)&guard.mask)==guard.mask,'Pay the heist setup fee at your planning board first.')
 end
 for _,guard in ipairs(P.required_stat_min or {})do
  assert(host.read(context,guard.key)>=guard.min,guard.message or 'Initialize your own heist first.')
 end
 for _,guard in ipairs(P.stat_guards or {})do
  local value=host.read(context,guard.key)
  assert((not guard.minimum or value>=guard.minimum)
   and (not guard.required_mask or (value&guard.required_mask)==guard.required_mask),guard.reason)
 end
 for _,guard in ipairs(P.prerequisite_stats or {})do
  assert(guard.test=='nonzero' and host.read(context,guard.key)~=0,guard.message)
 end
end
function host.write(context,key,value)
 assert(nb(0xB3271D7AB655B441,Utils.Joaat(context.prefix..key),value,true),'GTA rejected prep data.')
end
function host.read_globals(context)
 host.check(context)
 local out={}
 for key,row in pairs(P.context_globals or {})do
  assert(row.kind=='int' or row.kind=='float','Unsupported default data type.')
  out[key]=row.kind=='float' and gf(row.index) or gi(row.index)
 end
 return out
end
local function mirrors(profile)
 local r=profile.refresh;local rows={}
 if r.mirrors then
  for _,row in ipairs(r.mirrors)do rows[#rows+1]={key=row.key,index=r.mirror_base,offset=row.offset,stride=r.mirror_stride}end
 elseif r.cache then
  for key,offset in pairs(r.cache.fields)do
   rows[#rows+1]={key=key,index=r.cache.base+r.cache.array_header+r.cache.member_offset,offset=offset,stride=r.cache.stride}
  end
 else
  for key,offset in pairs(r.cache_offsets or {})do
   rows[#rows+1]={key=key,index=r.cache_base+(r.cache_array_header or 0),offset=offset,stride=r.cache_stride}
  end
 end
 return rows
end
local mirror_rows=mirrors(P)
function host.mirrors(t)
 for _,row in ipairs(mirror_rows)do
  local expected=t.expected[row.key]
  -- Only compare values actually written by this transaction.
  if expected~=nil and gi(row.index+t.context.pid*row.stride+row.offset)~=expected then return false end
 end
 return true
end
local function capture_board(t)
 local r=P.refresh;local hash=Utils.Joaat(r.script)
 if count(r.script)==0 then return nil end
 assert(count(r.script)==1,'Close extra planning screens first.')
 local ptr=ScriptLocal.GetPtr(hash,0)
 assert(type(ptr)=='number' and ptr>=65536,'Planning screen unavailable.')
 assert(type(P.verification_patterns)=='table' and #P.verification_patterns>=2,'Board refresh is not verified for this build.')
 for _,pattern in ipairs(P.verification_patterns)do
  local found=Memory.ScanScript(hash,pattern)
  assert(type(found)=='number' and found>=65536,'Planning script build changed. Reopen the planning screen.')
 end
 return {hash=hash,ptr=ptr}
end
local function same_board(t)
 host.check(t.context)
 local b=t.board;local r=P.refresh
 assert(count(r.script)==1 and ScriptLocal.GetPtr(b.hash,0)==b.ptr,'Planning screen changed.')
 local owner=r.owner_index or r.owner_global
 assert(owner and gi(owner)==t.context.pid,'Open your own planning board.')
 assert(li(b.hash,r.local_index or r.ready_local)==r.ready_value,'Planning screen is busy.')
 return b,r
end
local function set_global(t,index,value)
 same_board(t);ScriptGlobal.SetInt(index,value);assert(gi(index)==value,'Board update rejected.')
end
local function cayo_idle(t)
 local b,r=same_board(t)
 return gi(r.screen_state_global)==r.idle_state and gi(r.fullscreen_global)==r.idle_fullscreen_value
end
local function casino_panel(t)
 local _,r=same_board(t)
 local id=gi(r.panel_index)
 local panel
 for _,row in ipairs(r.panels)do if row.id==id then panel=row;break end end
 if not panel then return nil,'panel='..id end
 local stage=gi(panel.stage_index)
 for _,check in ipairs(r.busy_checks or {})do
  if (not check.panel or check.panel==id) and (not check.active_only or stage==r.active_stage)
   and gi(check.index)~=check.expected then return nil,'busy global='..check.index..' value='..gi(check.index)end
 end
 for _,check in ipairs(panel.busy_checks or {})do
  if (not check.stage or stage==check.stage) and gi(check.index)~=check.expected then
   return nil,'busy panel='..id..' global='..check.index..' value='..gi(check.index)
  end
 end
 if r.stable_stages[stage] and gi(panel.substate_index)==r.required_substate
  and gi(panel.movie_index)>0 then return panel end
 return nil,'panel='..id..' stage='..stage..' substate='..gi(panel.substate_index)..' movie='..gi(panel.movie_index)
end
local function casino_targets(t)
 local _,r=same_board(t)
 -- func610: all three stage3 panels are the ordinary idle planning room.
 -- Each stage3 handler still calls its semantic dirty consumer.
 local all_idle=true
 for _,panel in ipairs(r.panels)do
  if gi(panel.stage_index)~=3 then all_idle=false;break end
 end
 if all_idle then
  for _,check in ipairs(r.busy_checks or {})do
   if gi(check.index)~=check.expected then return nil,'idle room dialog busy' end
  end
  for _,panel in ipairs(r.panels)do
   if gi(panel.substate_index)~=r.required_substate or gi(panel.movie_index)<=0 then return nil,'idle room boards not loaded' end
  end
  return r.panels
 end
 local panel,why=casino_panel(t)
 return panel and {panel} or nil,why
end
local function same_targets(t,expected)
 local rows=casino_targets(t)
 if not rows or #rows~=#expected then return false end
 for i,row in ipairs(rows)do if row~=expected[i]then return false end end
 return true
end
local presentation
local function presentation_impl()
 if presentation or not P.refresh_factory then return presentation end
 local hash=Utils.Joaat(P.refresh.script)
 local function as_script(fn)
  assert(count(P.refresh.script)==1,'Planning script unavailable.')
  local packed
  Script.ExecuteAsScript(hash,function()packed=table.pack(fn())end)
  assert(packed,'Planning script context unavailable.')
  return table.unpack(packed,1,packed.n)
 end
 local api={gi=gi,gf=gf,
  gs=function(index)
   local value=ScriptGlobal.GetString(index)
   assert(type(value)=='string','Planning text unavailable.');return value
  end,
  ss=function(index,value)
   assert(type(value)=='string' and #value<64,'Invalid planning text.')
   ScriptGlobal.SetString(index,value)
   assert(ScriptGlobal.GetString(index)==value,'Planning text write rejected.')
  end,
  li=function(index)return li(hash,index)end,
  si=function(index,value)
   assert(int(value),'Invalid display value.');ScriptGlobal.SetInt(index,value)
   assert(gi(index)==value,'Display write rejected.')
  end,
  sl=function(index,value)
   assert(int(value),'Invalid display local.');ScriptLocal.SetInt(hash,index,value)
   assert(li(hash,index)==value,'Display local write rejected.')
  end,
  count=function()return count(P.refresh.script)end,
  ptr=function()return ScriptLocal.GetPtr(hash,0)end,
  same_context=function(t)host.check(t.context);return true end,
  now=host.now,log=log,notice=say,script_hash=hash,
  ni=function(native,...)local args=table.pack(...);return as_script(function()return ni(native,table.unpack(args,1,args.n))end)end,
  nb=function(native,...)local args=table.pack(...);return as_script(function()return nb(native,table.unpack(args,1,args.n))end)end,
  nv=function(native,...)local args=table.pack(...);return as_script(function()return Natives.InvokeVoid(native,table.unpack(args,1,args.n))end)end,
 }
 function api.tunable_int(name,fallback_index)
  local ptr=Memory.AllocInt();assert(type(ptr)=='number' and ptr>0,'Reward buffer unavailable.')
  local ok,value=pcall(function()
   Memory.WriteInt(ptr,0)
   if api.nb(0x40FCE03E50E8DBE8,Utils.Joaat('MP_Global'),Utils.Joaat(name),ptr)then
    local current=Memory.ReadInt(ptr);assert(int(current),'Reward tunable is invalid.');return current
   end
   return gi(fallback_index)
  end)
  local freed=pcall(Memory.Free,ptr);assert(freed,'Reward buffer could not be released.')
  assert(ok,value);return value
 end
 function api.verify(patterns)
  patterns=patterns or P.verification_patterns
  assert(type(patterns)=='table' and #patterns>=2,'Missing display layout verification.')
  local all={}
  for _,pattern in ipairs(P.verification_patterns or {})do all[#all+1]=pattern end
  if patterns~=P.verification_patterns then for _,pattern in ipairs(patterns)do all[#all+1]=pattern end end
  for _,pattern in ipairs(all)do
   local found=Memory.ScanScript(hash,pattern)
   assert(type(found)=='number' and found>=65536,'Unsupported planning script build.')
  end
  return true
 end
 function api.release_movie(handle)
  assert(int(handle) and handle>0,'Invalid display movie.')
  local ptr=Memory.AllocInt();assert(type(ptr)=='number' and ptr>0,'Display release buffer unavailable.')
  local ok,err=pcall(function()
   Memory.WriteInt(ptr,handle)
   api.nv(0x1D132D614DD86811,ptr)
  end)
  local freed=pcall(Memory.Free,ptr);assert(freed,'Display release buffer failed.')
  assert(ok,err)
 end
 presentation=assert(P.refresh_factory(api),'Display controller unavailable.')
 return presentation
end
function host.refresh(t)
 local custom=presentation_impl()
 if custom then
  local result,why=custom.request(t)
  if not t.presentation_started_at and ((t._cayo_movie_rebuild and t._cayo_movie_rebuild.old_released)
   or (t.doomsday_refresh and t.doomsday_refresh.published))then t.presentation_started_at=host.now()end
  if why and t.custom_reason~=why then
   t.custom_reason=why;log('display reload: '..why)
   if result=='wait' and why:find('Close the planning screen',1,true)then say('Close the planning screen to refresh.')end
  end
  return result
 end
 if P.family=='doomsday'then return count(P.refresh.script)==0 and 'none' or 'reopen' end
 t.board=t.board or capture_board(t)
 if not t.board then return 'none' end
 local b,r=same_board(t)
 if P.family=='casino'then
  local panels,why=casino_targets(t)
  if not panels then
   if t.refresh_reason~=why then t.refresh_reason=why;log('waiting for board: '..why)end
   return 'wait'
  end
  for _,row in ipairs(r.cache_sync)do
   assert(same_targets(t,panels),'Planning screen changed.')
   set_global(t,row.index,assert(t.expected[row.key]))
  end
  t.panels=panels
  for _,panel in ipairs(panels)do
   assert(same_targets(t,panels),'Planning screen changed.')
   set_global(t,panel.dirty_index,r.dirty_trigger)
  end
  return 'pending'
 elseif P.family=='cayo'then
  if not cayo_idle(t)then return 'reopen' end
  ScriptLocal.SetInt(b.hash,r.render_loaded_local,0)
  assert(li(b.hash,r.render_loaded_local)==0,'Board redraw rejected.')
  assert(cayo_idle(t),'Planning screen changed.')
  set_global(t,r.entry_flags_global,gi(r.entry_flags_global)&(~(1<<r.entry_bit)))
  return 'pending'
 end
 return 'reopen'
end
function host.trace(t,label)
 local fields={label,'pid='..tostring(t.context and t.context.pid),'slot='..tostring(t.context and t.context.slot)}
 if label=='before' or label=='written'then
  for _,f in ipairs(t.fields)do fields[#fields+1]=f.key..'='..f.old..'->'..f.value end
 end
 local r=P.refresh
 if count(r.script)==1 then
  fields[#fields+1]='board_local='..li(Utils.Joaat(r.script),r.local_index or r.ready_local or 218)
  if r.owner_index or r.owner_global then fields[#fields+1]='owner='..gi(r.owner_index or r.owner_global)end
  if r.panel_index then fields[#fields+1]='panel='..gi(r.panel_index)end
  for _,panel in ipairs(r.panels or {})do
   fields[#fields+1]=panel.key..'='..gi(panel.stage_index)..'/'..gi(panel.substate_index)..'/'..gi(panel.dirty_index)
  end
 end
 for _,row in ipairs(P.diagnostic_values or {})do
  fields[#fields+1]=row.label..'='..(row.kind=='float' and gf(row.index) or gi(row.index))
 end
 if P.diagnose_primary and t.context and t.expected then
  local base=1982548+1+t.context.pid*53
  local diagnostic=P.diagnose_primary({H4CNF_TARGET=gi(base+14),H4_PROGRESS=gi(base+1),_globals=host.read_globals(t.context)})
  fields[#fields+1]='payout_status='..diagnostic.status
  if diagnostic.status=='AVAILABLE'then
   fields[#fields+1]='mirror_target='..diagnostic.target
   fields[#fields+1]='primary_base='..diagnostic.base
   fields[#fields+1]='normal_factor='..diagnostic.normal_factor
   fields[#fields+1]='hard_factor='..diagnostic.hard_factor
   fields[#fields+1]='hard='..tostring(diagnostic.hard)
   fields[#fields+1]='source_primary='..diagnostic.expected
  end
 end
 log(table.concat(fields,' | '))
end
function host.ack(t)
 local custom=presentation_impl();if custom then return custom.ack(t)end
 local b,r=same_board(t)
 if P.family=='casino'then
  if not same_targets(t,t.panels)then return false end
  for _,panel in ipairs(t.panels)do if gi(panel.dirty_index)~=r.dirty_ack then return false end end
  return true
 end
 if P.family=='cayo'then
  return cayo_idle(t) and li(b.hash,r.render_loaded_local)==1 and (gi(r.entry_flags_global)&(1<<r.entry_bit))~=0
 end
 return false
end
function host.reuse_display(previous,current)
 local custom=presentation_impl()
 return custom and custom.reuse and host.mirrors(current) and custom.reuse(previous,current)==true
end
function host.recovery(t)
 if presentation and presentation.recovery then
  local message=presentation.recovery(t)
  if message then return message end
 end
 local s=t and t._cayo_movie_rebuild
 if s and s.old_released and not s.done then return 'Preps applied. Reenter the Kosatka to reload the board.' end
 s=t and t.doomsday_refresh
 if s and s.published then return 'Preps applied. Reenter the Facility to reload the board.' end
end
function host.release(t,reason)
 local fallback=host.recovery(t)
 if presentation and presentation.release then presentation.release(t,reason)end
 if fallback and reason=='unload'then say(fallback)end
end

local controller=new_controller(host,P)
return {Controller=controller,Host=host,Profile=P,NewController=new_controller}
end)()


-- RC3 family backend. These are the recovered controllers, not legacy adapter fallbacks.
local FLAGS={solo=false,payout=false}
local VIEW={apartment={},cayo={},casino={},doomsday={}}
local SOURCES={
 apartment={'Prototype_Apartment_Selector.lua','Prototype_Apartment_Board.lua','rrer.lua','f.lua','MaxPayout.lua','CMM.lua'},
 cayo={'Prototype_Cayo_Preps.lua','CScript_Heist_Prototype_v2_8_EarlyHandoff.lua'},
 casino={'Prototype_Casino_Preps.lua','CScript_Heist_Prototype_v2_8_EarlyHandoff.lua'},
 doomsday={'CayoPerico.lua','CScript_Heist_Prototype_v2_8_EarlyHandoff.lua','Original CScript Doomsday Instant Finish'}
}
local PREPS={cayo=CayoPreps,casino=CasinoPreps,doomsday=DoomsdayPreps}
local epoch,last_tick,last_read,finish_family=0,-1,-1,nil
local function detach(v)
 if type(v)~='table'then return v end
 local t={};for k,x in pairs(v)do if type(x)~='function'then t[k]=detach(x)end end;return t
end
local function message(family,kind,text)
 if text==nil then return end
 text=tostring(text)
 local v=VIEW[family]
 if v and v[kind]==text then return end
 if v then v[kind]=text end
 if Logger and type(Logger.LogInfo)=='function'then
  pcall(Logger.LogInfo,'[CScript Heist Backend RC3] family='..tostring(family)..' '..kind..' '..text)
 end
end
local function describe(family)
 assert(VIEW[family],'Unsupported heist family')
 local selectors
 if family=='apartment'then
  local options={}
  for i,row in ipairs(ApartmentSelector.Rows)do options[i]={label=row.name,value=i}end
  selectors={{key='heist',label='Heist',default=1,options=options}}
 else selectors=PREPS[family].Profile.selectors end
 return {family=family,selectors=detach(selectors),sources=detach(SOURCES[family]),
  capabilities={finish=true,bonus=family=='apartment',board=family=='apartment',
   manual_cuts=family=='apartment',casino_cuts=family=='casino',prepare=true}}
end
local function game_context()
 local ok,w=pcall(SoloLaunch.Host.world)
 if not ok or type(w)~='table'or w.session~=true then return {online=false}end
 return {online=true,key=table.concat({epoch,w.epoch or 0,w.pid or -1,w.mission or 0},':'),
  mission=w.mission,activity=w.activity,player=w.pid}
end
local function snapshot(family)
 local v=detach(VIEW[family]or{})
 v.family=family
 v.toggles={solo=FLAGS.solo,payout=FLAGS.payout,bonus=ApartmentBonus.Controller.IsEnabled()}
 return v
end
local function set_solo(enabled)
 local called,ok,why=pcall(ApartmentSolo.Controller.SetEnabled,enabled)
 if not called or ok==false then return false,tostring(called and why or ok)end
 local ran,accepted,detail=pcall(SoloLaunch.Controller.SetEnabled,enabled)
 if not ran or accepted==false then
  pcall(ApartmentSolo.Controller.SetEnabled,FLAGS.solo)
  return false,tostring(ran and detail or accepted)
 end
 FLAGS.solo=enabled
 return true,enabled and 'Solo Launch armed.'or'Solo Launch disabled.'
end
local function set_payout(enabled)
 local ok,accepted=pcall(MaxPayout.SetEnabled,enabled)
 if not ok or accepted==false then return false,tostring(accepted)end
 ApartmentMax.Controller.Reset();FLAGS.payout=enabled
 return true,enabled and 'Max Payout armed.'or'Max Payout disabled.'
end
local function prepare_finish(family)
 if family=='apartment'then
  if ApartmentBonus.Controller.IsEnabled()then
   local ok,note=pcall(ApartmentBonus.Controller.Tick)
   if not ok then return false,tostring(note)end
   if note then message('apartment','bonus_status',note)end
  end
  return true,'Apartment result will use the configured lobby cuts.'
 end
 if not FLAGS.payout then return true,'Max Payout is off.'end
 local ran,ready,why=pcall(MaxPayout.BeforeFinish)
 return ran and ready==true,tostring(ran and why or ready)
end
local function apply_preps(family,selection)
 if type(selection)~='table'then return false,'Select the preparation options first.'end
 if family=='apartment'then
  local index=selection.heist
  if type(index)~='number'or index%1~=0 or index<1 or index>5 then return false,'Choose an Apartment heist.'end
  return ApartmentSelector.Controller.Select(index)
 end
 local engine=PREPS[family];if not engine then return false,'Prep controller unavailable.'end
 local payload={seed=engine.Host.now()}
 for _,selector in ipairs(engine.Profile.selectors or{})do
  local value=selection[selector.key]
  if value==nil then value=selector.options[selector.default or 1].value end
  local valid=false
  for _,option in ipairs(selector.options or{})do if option.value==value then valid=true;break end end
  if not valid then return false,'Invalid '..tostring(selector.label)..' selection.'end
  payload[selector.key]=value
 end
 return engine.Controller.Apply(payload)
end
local function execute(family,command,args)
 if not started then return false,'Heist controllers are stopped.'end
 if not VIEW[family]then return false,'Unknown heist family.'end
 args=args or{}
 if command=='prepare'then return apply_preps(family,args.selection)
 elseif command=='finish'then
  if family=='doomsday'then return false,'Doomsday must use the original CScript finish implementation.'end
  local prepared,warning=prepare_finish(family)
  if not prepared then message(family,'preparation_warning',warning)end
  local controller=family=='apartment'and ApartmentFinish.Controller or InstantFinish.Controller
  if family~='apartment'then
   local ok,ctx=pcall(InstantFinish.Host.capture)
   if not ok then return false,tostring(ctx)end
   if ctx.family~=family then return false,'Active finale does not match the selected heist.'end
  end
  local accepted,why=controller.Request()
  if accepted then finish_family=family end
  message(family,'finish_status',why)
  return accepted,why
 elseif command=='before_finish'then return prepare_finish(family)
 elseif command=='solo'then return set_solo(args.enabled==true)
 elseif command=='payout'then return set_payout(args.enabled==true)
 elseif command=='bonus'then
  if family~='apartment'then return false,'12M Bonus is an Apartment option.'end
  return ApartmentBonus.Controller.SetEnabled(args.enabled==true)
 elseif command=='payout_once'then
  if family=='apartment'then
   ApartmentMax.Controller.Reset()
   local result=ApartmentMax.Controller.Tick(3000000,true)
   return result and result.ok==true,result and result.message or'Payout context unavailable.'
  end
  local ok,why=set_payout(true);if not ok then return false,why end
  local result=MaxPayout.Tick(true)
  return result and result.ok==true,result and result.message or'Payout context unavailable.'
 elseif command=='board'and family=='apartment'then return ApartmentBoard.Controller.Refresh()
 elseif command=='cuts'and family=='apartment'then
  if type(args.values)~='table'then return false,'Enter the four board percentages.'end
  -- One manual/automatic board writer, both from the recovered MaxPayout.lua.
  local result,why=ApartmentMax.Cuts.Apply(args.values)
  if result then ApartmentMax.Controller.Reset()end
  return result,why
 elseif command=='read_cuts'and family=='apartment'then
  local s=ApartmentMax.Cuts.Check();return s.ok==true,s.message
 elseif command=='casino_cuts'and family=='casino'then
  local ok,why=CasinoBoardCuts.SetMode(args.mode or'host');if not ok then return false,why end
  local called,text=pcall(CasinoBoardCuts.Apply);return called,tostring(text)
 end
 return false,'This action is not provided by the recovered '..family..' controller.'
end
local function poll(family,kind,fn)
 local ok,a,b=pcall(fn)
 if not ok then message(family,kind,'Controller error: '..tostring(a))
 elseif b~=nil then message(family,kind,b)
 elseif type(a)=='string'then message(family,kind,a)end
end
local function tick()
 if not started then return end
 local now=Time and Time.GetEpocheMs and Time.GetEpocheMs()or 0
 if type(now)~='number'then return end
 if now>=last_tick and now-last_tick<50 then return end
 last_tick=now
 poll('apartment','finish_status',ApartmentFinish.Controller.Tick)
 poll(finish_family or'cayo','finish_status',InstantFinish.Controller.Tick)
 if FLAGS.solo then
  poll('apartment','solo_status',ApartmentSolo.Controller.Tick)
  local ok,text=pcall(SoloLaunch.Controller.Tick)
  if not ok then text='Controller error: '..tostring(text)end
  for _,f in ipairs({'cayo','casino','doomsday'})do message(f,'solo_status',text)end
 end
 poll('apartment','prep_status',ApartmentSelector.Controller.Tick)
 poll('apartment','board_status',ApartmentBoard.Controller.Tick)
 for family,engine in pairs(PREPS)do poll(family,'prep_status',engine.Controller.Tick)end
 if ApartmentBonus.Controller.IsEnabled()then poll('apartment','bonus_status',ApartmentBonus.Controller.Tick)end
 if FLAGS.payout then
  local ok,r=pcall(ApartmentMax.Controller.Tick,3000000)
  if ok and r then message('apartment','payout_status',r.message);VIEW.apartment.payout_plan=detach(r.plan)end
  local ran,result=pcall(MaxPayout.Tick)
  if ran and result then
   local f=result.plan and result.plan.family
   if f and VIEW[f]then
    message(f,'payout_status',result.message);VIEW[f].payout_plan=detach(result.plan)
   else
    for _,name in ipairs({'cayo','casino','doomsday'})do message(name,'payout_status',result.message)end
   end
  end
 end
 if now<last_read or now-last_read>=500 then
  last_read=now
  local ok,s=pcall(ApartmentMax.Cuts.Check)
  if ok and s and s.ok and type(s.cuts)=='table'then
   VIEW.apartment.cuts=detach(s.cuts);VIEW.apartment.cuts_message=s.message
  else
   VIEW.apartment.cuts=nil;VIEW.apartment.cuts_message=ok and s and s.message or'Board cuts unavailable.'
  end
 end
end
local function stop()
 started=false
 local clean=true
 for _,fn in ipairs({
  function()ApartmentFinish.Controller.Stop()end,
  function()InstantFinish.Controller.Stop(false)end,
  function()ApartmentSolo.Controller.Unload()end,
  function()SoloLaunch.Controller.Unload()end,
  function()return MaxPayout.SetEnabled(false)end,
  function()ApartmentMax.Controller.Reset()end,
  function()ApartmentBonus.Controller.Unload()end,
  function()ApartmentSelector.Controller.Stop()end,
  function()if ApartmentBoard.Controller.Stop then ApartmentBoard.Controller.Stop()end end,
  function()CayoPreps.Controller.Unload()end,
  function()CasinoPreps.Controller.Unload()end,
  function()DoomsdayPreps.Controller.Unload()end
 })do
  local ok,result=pcall(fn)
  if not ok or result==false then clean=false;message('apartment','cleanup',tostring(result))end
 end
 FLAGS.solo,FLAGS.payout=false,false
 return clean
end
local function session_changed()
 epoch=epoch+1;last_tick,last_read=-1,-1;finish_family=nil
 ApartmentFinish.Controller.Stop();InstantFinish.Controller.Stop(true)
 ApartmentSolo.SessionChanged();SoloLaunch.Controller.Reset()
 MaxPayout.OnSessionChanged();ApartmentMax.Controller.Reset()
 ApartmentSelector.Controller.Stop();CasinoBoardCuts.Reset()
 for _,engine in pairs(PREPS)do pcall(engine.Controller.Unload)end
 for family in pairs(VIEW)do VIEW[family]={}end
end
function Module.Init(ctx)
 context_ref=ctx;MaxPayout.BindLifecycle()
 public_api={Describe=describe,Context=game_context,Snapshot=snapshot,Execute=execute,
  Tick=tick,OnSessionChange=session_changed,Quiesce=stop,
  ControllerRevision='RC3_SINGLE_OWNER',LiveVerified=false}
 ctx.CScript.HeistPrototypes=public_api;ctx.Modules.HeistPrototypeBridge=Module
end
function Module.Start()started=true;return true end
function Module.Stop()return stop()end
function Module.Restore(ctx)
 if Module.Stop()~=true then return false,'Prototype cleanup remains pending.'end
 ctx=ctx or context_ref
 if ctx and ctx.CScript and ctx.CScript.HeistPrototypes==public_api then ctx.CScript.HeistPrototypes=nil end
 if ctx and ctx.Modules and ctx.Modules.HeistPrototypeBridge==Module then ctx.Modules.HeistPrototypeBridge=nil end
 context_ref,public_api=nil,nil;return true
end
return Module
