-- Heist runtime profiles derived from GTA V Enhanced scripts. Cut arrays are
-- build-specific launcher/planning state. Validate each slot independently
-- and keep board refresh separate. Apartment's live cut board requires 100%.
local Module = { Name = "modules.heist_runtime_profiles", MigrationPhase = "17.75" }

-- BEGIN ENDING CUTSCENE WATCHER70
-- A submitted finale owns one bounded request to its normal skip consumer.
-- Requesting a skip is not an outcome, a payment receipt or a zero-frame promise.
function Module.NewEndingCutsceneWatcher(host)
 for _,name in ipairs({'Now','Validate','Read','Request'})do
  assert(type(host[name])=='function','Ending cutscene watcher requires '..name)
 end
 local active,busy,arming,stopped,revision=nil,false,false,false,0
 local latest={state='IDLE',active=false,requested=false,payment_verified=false}
 local api={}
 local function time(value)return type(value)=='number'and value==value and value>=0 and value<=9007199254740991 end
 local function current(s)return active==s and not stopped and s.revision==revision end
 local function finish(s,state,reason)
  if not current(s)then return end
  active=nil;revision=revision+1
  latest={state=state,active=false,requested=state=='REQUESTED',family=s.ctx.family,
   controller_identity=s.ctx.controller_identity,phase=s.phase,observation=s.ctx.ending_observation,payment_verified=false,reason=reason or s.wait_reason or state}
  if type(host.Report)=='function'then pcall(host.Report,latest)end
 end
 local function check(s)
  if not current(s)then return false end
  local now=host.Now()
  if not current(s)then return false end
  if not time(now)or now<s.started or now<s.last then finish(s,'CLOCK_UNAVAILABLE');return false end
  if now>=s.deadline then finish(s,'EXPIRED');return false end
  s.last=now
  local valid=host.Validate(s.ctx)
  if not current(s)then return false end
  if valid==false then finish(s,'CONTEXT_CHANGED','controller_or_owner_changed');return false end
  if valid~=true then s.wait_reason='identity_unavailable'end
  return valid==true
 end
 function api.Arm(ctx)
  if busy or arming or stopped or type(ctx)~='table'or type(ctx.controller_identity)~='string'then return false end
  local token=revision;arming=true
  local ok,now=pcall(host.Now);arming=false
  if not ok or not time(now)or stopped or token~=revision then return false end
  revision=revision+1
  active={ctx=ctx,started=now,last=now,deadline=now+120000,revision=revision}
  latest={state='WAITING',active=true,requested=false,family=ctx.family,
   controller_identity=ctx.controller_identity,payment_verified=false}
  return true
 end
 function api.Tick()
  if busy or not active or stopped then return end
  busy=true;local s=active
  local ok=pcall(function()
   if not check(s)then return end
   local phase=host.Read(s.ctx)
   if not current(s)then return end
   s.phase=phase
   if phase=='done'then finish(s,'COMPLETE','ending_completed');return end
   if phase~='playing'and phase~='prepared'then s.wait_reason='ending_not_active';return end
   local fenced=false
   local function fence(expected_phase)
    if not check(s)then return false end
    local phase=host.Read(s.ctx)
    if not current(s)or (phase~='playing'and phase~='prepared')then return false end
    if expected_phase and phase~=expected_phase then return false end
    -- Read may invoke host/native services. Recheck identity and deadline last.
    if not check(s)then return false end
    local now=host.Now()
    if not current(s)or not time(now)or now<s.last or now>=s.deadline then
     if current(s)then finish(s,'EXPIRED')end;return false
    end
    fenced=true;return true
   end
   -- The host owns the only write and must cross this final fence. Even an
   -- ambiguous host exception is terminal; never duplicate a possible request.
   local accepted,reason=host.Request(s.ctx,fence)
   if current(s)then finish(s,accepted==true and fenced and 'REQUESTED'or 'UNAVAILABLE',reason)end
  end)
  if not ok and current(s)then finish(s,'UNAVAILABLE','request_or_observation_error')end
  busy=false
 end
 function api.Cancel()
  if active then finish(active,'CANCELLED','cancelled')end
  revision=revision+1;active=nil
  latest={state='CANCELLED',active=false,requested=false,payment_verified=false}
 end
 function api.Stop()api.Cancel();stopped=true end
 function api.Rearm()
  if busy or arming then return false end
  revision=revision+1;active=nil;stopped=false
  latest={state='IDLE',active=false,requested=false,payment_verified=false};return true
 end
 function api.Requested()return active~=nil and not stopped end
 function api.Snapshot()local copy={};for k,v in pairs(latest)do copy[k]=v end;return copy end
 return api
end
-- END ENDING CUTSCENE WATCHER70

