    { key="social", script="social_controller", label="Social Controller", family="Social" },
    { key="garage", script="am_mp_garage_control", label="Garage Controller", family="Vehicle / Property" },
}

local function refresh_app_status()
    begin_explicit_thread_refresh()
    local result={status="IDLE",active={},items={},readable_count=0,total_profiles=#ROCKSTAR_APP_SCRIPTS,source_revision=SOURCE_REVISION}
    for _,item in ipairs(ROCKSTAR_APP_SCRIPTS) do
        local row={key=item.key,script=item.script,label=item.label,family=item.family}
        local hash,hash_err=script_hash(item.script)
        if hash then
            local threads,thread_err=thread_count(hash)
            if threads~=nil then
                row.available=true; row.threads=threads; row.active=threads>0; row.hash=hash; result.readable_count=result.readable_count+1
                if row.active then result.active[#result.active+1]=row end
            else row.error=thread_err end
        else row.error=hash_err end
        result.items[#result.items+1]=row
    end
    if #result.active>0 then result.status="ACTIVE" elseif result.readable_count==0 then result.status="UNAVAILABLE" end
    result.note="Explicit read-only script-thread inventory for current Enhanced Rockstar app/controllers; app presence does not authorize app-state mutation."
    app_cache=result
    return result.readable_count>0,result
end

local function app_status()
    if type(app_cache)~="table" then return {status="REFRESH_REQUIRED",active={},items={},readable_count=0,total_profiles=#ROCKSTAR_APP_SCRIPTS} end
    return app_cache
end

local function refresh_activity_status()
    begin_explicit_thread_refresh()
    local result = { status = "IDLE", active = {}, source_revision = SOURCE_REVISION, total_profiles = #ACTIVITY_SCRIPTS }
    local readable = 0
    for _, item in ipairs(ACTIVITY_SCRIPTS) do
        local hash, hash_err = script_hash(item.script)
        if hash then
            local threads, thread_err = thread_count(hash)
            if threads ~= nil then
                readable = readable + 1
                if threads > 0 then
                    result.active[#result.active + 1] = {
                        key = item.key, script = item.script, label = item.label,
                        family = item.family, threads = threads, hash = hash,
                    }
                end
            elseif not result.error then result.error = thread_err end
        elseif not result.error then result.error = hash_err end
    end
    if #result.active > 0 then result.status = "ACTIVE"
    elseif readable == 0 then result.status = "UNAVAILABLE"
    else result.status = "IDLE" end
    result.readable_count = readable
    result.reason = #result.active > 0
        and "Current Enhanced activity script identity is readable. This is runtime intelligence only; no completion/write path is inferred from script presence."
        or "No source-catalogued business/freemode activity script is currently active."
    activity_cache = result
    return readable > 0, result
end

local function activity_status()
    return activity_cache or {
        status = "REFRESH_REQUIRED", active = {}, readable_count = 0,
        total_profiles = #ACTIVITY_SCRIPTS, source_revision = SOURCE_REVISION,
        reason = "Choose Refresh Runtime Intelligence to query activity scripts once. Rendering uses this cached snapshot.",
    }
end

local function refresh_controller_status()
    begin_explicit_thread_refresh()
    local result = { status = "IDLE", active = {}, instant_finish = false, source_revision = SOURCE_REVISION }
    local readable = 0
    for _, item in ipairs(CONTROLLER_SCRIPTS) do
        local hash, hash_err = script_hash(item.script)
        if hash then
            local threads, thread_err = thread_count(hash)
            if threads ~= nil then
                readable = readable + 1
                if threads > 0 then
                    result.active[#result.active + 1] = { key=item.key, script=item.script, label=item.label, threads=threads, hash=hash }
                end
            elseif not result.error then result.error = thread_err end
        elseif not result.error then result.error = hash_err end
    end
    if #result.active > 0 then result.status = "ACTIVE"
    elseif readable == 0 then result.status = "UNAVAILABLE"
    else result.status = "IDLE" end
    result.readable_count = readable
    result.reason = #result.active > 0
        and "Active mission identity is readable. Instant Finish requires a validated completion transition for this activity."
        or "No supported finale/controller script is active."
    controller_cache = result
    return readable > 0, result
end

local function controller_status()
    return controller_cache or {
        status = "REFRESH_REQUIRED", active = {}, readable_count = 0,
        total_profiles = #CONTROLLER_SCRIPTS, instant_finish = false,
        source_revision = SOURCE_REVISION,
        reason = "Choose Refresh Runtime Intelligence to query controller scripts once. Rendering uses this cached snapshot.",
    }
end

refresh_launch_status = function(family)
    begin_explicit_thread_refresh()
    local ready = force_ready_status()
    local solo = solo_launch_status(family)
    log_detection("SoloLaunch", family, solo.ready, solo.reason)
    local support = (ready.support == "EXPERIMENTAL" or solo.support == "EXPERIMENTAL") and "EXPERIMENTAL" or "BLOCKED"
    launch_cache = {
        support = support, script = FMMC_PROFILE.script, family = tostring(family or ""),
        state = solo_override and (solo_override.failed and "FAILED" or "APPLYING")
            or ready.state or solo.state or "INSTANCE_UNAVAILABLE",
        instance_id = ready.instance_id or solo.instance_id,
        host = ready.host == true and "Local player" or ready.state == "NOT_HOST" and "Other player" or "Unknown",
        players = ready.players or "Unknown",
        ready = ready.ready == true or solo.ready == true,
        reason = ready.ready and ready.reason or solo.ready and solo.reason
            or (ready.reason or solo.reason or "Launcher state is unavailable."),
        force_ready = ready, solo_launch = solo, ready_snapshot_available = ready_snapshot ~= nil,
        evidence = FMMC_PROFILE.evidence, source_revision = SOURCE_REVISION,
        confidence = "B", live_status = "LIVE_TEST_REQUIRED", refreshed = true,
        refreshed_at_ms = runtime_time_ms(), last_action = launch_event,
    }
    if ready_snapshot then
        local ctx, _, context_state = launch_context()
        if (not ctx and (context_state == "NOT_IN_LOBBY" or context_state == "NOT_HOST"))
            or (ctx and (not same_launcher(ctx.identity, ready_snapshot.identity) or ctx.mission ~= ready_snapshot.mission)) then
            ready_snapshot = nil
            launch_cache.ready_snapshot_available = false
            ready.ready_snapshot_available = false
        end
    end
    return launch_cache.ready == true, launch_cache
end

local function launch_status(family)
    if launch_cache and (family == nil or launch_cache.family == tostring(family)) then
        launch_cache.ready_snapshot_available = ready_snapshot ~= nil
        if launch_cache.force_ready then launch_cache.force_ready.ready_snapshot_available = ready_snapshot ~= nil end
        if launch_cache.solo_launch then launch_cache.solo_launch.override_active = solo_override ~= nil end
        return launch_cache
    end
    local reason = "Launcher status is queued for the existing gameplay scheduler."
    local pending = { support = "REFRESH_REQUIRED", state = "PENDING", ready = false, script = FMMC_PROFILE.script,
        reason = reason, confidence = "B", evidence = FMMC_PROFILE.evidence }
    return {
        support = "REFRESH_REQUIRED", state = "PENDING", family = family, script = FMMC_PROFILE.script,
        host = "Unknown", players = "Unknown", ready = false, reason = reason,
        force_ready = pending, solo_launch = pending, ready_snapshot_available = ready_snapshot ~= nil,
        evidence = FMMC_PROFILE.evidence, source_revision = SOURCE_REVISION,
        confidence = "B", live_status = "LIVE_TEST_REQUIRED", refreshed = false,
    }
end

local function cached_force_ready_status(family)
    local status = launch_status(family)
    return status.force_ready or { support = "REFRESH_REQUIRED", ready = false, reason = status.reason }
end

local function cached_solo_launch_status(family)
    local status = launch_status(family)
    return status.solo_launch or { support = "REFRESH_REQUIRED", ready = false, reason = status.reason }
end

local function validate_cut_request(profile, values)
    if type(profile) ~= "table" or not CUT_PROFILES[profile.family] then
        return false, "The active-finale cut profile is unavailable."
    end
    local slots = tonumber(profile.slot_count)
    local max_cut = tonumber(profile.max_cut) or 999
    if not slots or slots < 1 or slots > 4 then return false, "Validated cut slot count is invalid." end
    if type(values) ~= "table" or #values ~= slots then return false, "Cut values do not match the validated participant count." end
    local total = 0
    for index = 1, slots do
        local value = tonumber(values[index])
        if not value or value % 1 ~= 0 or value < 0 or value > max_cut then
            return false, ("Cut slot %d is outside the validated 0-%d range."):format(index, max_cut)
        end
        total = total + value
    end
    -- Validate each participant slot independently: 0..999 for
    -- Cayo/Casino/Doomsday, 0..9999 for Apartment. GTA determines payouts.
    return true, nil, total
end

global_service = function()
    local globals = binding("ScriptGlobal")
    if not (globals and type(globals.GetInt) == "function" and type(globals.SetInt) == "function") then
        return nil, "This Cherax build does not expose safe ScriptGlobal read/write access."
    end
    return globals
end

local copy_array
local function read_cuts(family)
    if not started then return nil, "Heist runtime profiles are not ready." end
    local profile = CUT_PROFILES[tostring(family or "")]
    if not profile then return nil, "No current Enhanced cut profile is available for this heist." end
    local globals, globals_err = global_service()
    if not globals then return nil, globals_err end
    local max_cut = tonumber(profile.max_cut) or 999
    local values = {}
    for slot = 1, profile.slot_count do
        local index = profile.base_index + slot
        local ok, raw = pcall(globals.GetInt, index)
        raw = ok and tonumber(raw) or nil
        if raw == nil or raw % 1 ~= 0 or raw < 0 or raw > max_cut then
            return nil, ("Player %d cut could not be read safely in the 0-%d range. No write was attempted."):format(slot, max_cut)
        end
        values[slot] = raw
    end
    cut_cache[profile.family] = { values = copy_array(values), refreshed = true }
    return values
end

copy_array = function(values)
    local result = {}
    for index = 1, #(values or {}) do result[index] = values[index] end
    return result
end

-- A transaction binds to session generation, character, local player and the
-- actual local storage of active scripts. Script names/counts alone are not an
-- instance identity. Missing GetPtr blocks mutation while a script is active.
cut_identity = function(family)
    local core = context_ref and context_ref.CScript and context_ref.CScript.Economy
    local natives, locals = binding("Natives"), binding("ScriptLocal")
    local ok, identity = pcall(function()
        assert(started and core and type(core.CurrentSlot)=="function", "character service unavailable")
        local slot = core.CurrentSlot()
        assert(slot==0 or slot==1, "character slot unavailable")
        assert(natives.InvokeBool(0xD83C2B94E7508980)==true, "online session unavailable")
        assert(natives.InvokeBool(0x520F3282A53D26B7)==false, "session transition")
        local pid = assert(local_player_id())
        local parts = {cut_generation, slot, pid}
        local board = BOARD_PROFILES[family]
        local scripts = {{"fmmc_launcher",FMMC_PROFILE.minimum_players_local}}
        if board then scripts[#scripts+1]={board.script,board.local_index} end
        for _, item in ipairs(scripts) do
            local hash = assert(script_hash(item[1]))
            local count = natives.InvokeInt(THREAD_COUNT_HASH, hash)
            assert(type(count)=="number" and count>=0 and count<=1, "script instance ambiguous")
            parts[#parts+1]=count
            if count==1 then
                assert(locals and type(locals.GetPtr)=="function", "script storage identity unavailable")
                local address=locals.GetPtr(hash,item[2])
                assert(type(address)=="number" and address>=65536, "script storage identity unavailable")
                parts[#parts+1]=address
                local exact,why=HeistOps.script_identity(hash,item[2],item[1]);assert(exact,why)
                assert(exact.pointer==address,"script storage changed during identity read")
                parts[#parts+1]=exact.thread_id
                if board and item[1]==board.script and board.local_presentation==true then
                    assert(exact.networked~=true,"Planning script unexpectedly registered a network host: "..exact.host_diagnostic)
                    parts[#parts+1]="local-presentation"
                else
                    assert(exact.networked==true and exact.host~=nil,
                        "Exact network-script host unavailable ("..exact.host_diagnostic..").")
                    parts[#parts+1]=exact.host
                end
                local layout=PAYOUT_ROSTERS[family]
                if board and item[1]==board.script and layout then
                    local globals=assert(global_service())
                    for _,index in ipairs({layout.owner,layout.count,layout.participants,
                        layout.participants+1,layout.participants+2,layout.participants+3}) do
                        local v=globals.GetInt(index)
                        assert(type(v)=="number" and v%1==0,"planning identity unavailable")
                        parts[#parts+1]=v
                    end
                end
            end
        end
        return {key=table.concat(parts,":"), slot=slot, pid=pid, generation=cut_generation}
    end)
    if not ok then return nil, "Cut context unavailable: "..tostring(identity) end
    return identity
end

local function same_cut_context(family, identity)
    local current, err = cut_identity(family)
    if not current then return nil, err end
    return current.key==identity.key, "Cut context changed; old values will not be replayed."
end

-- Payout calculators must use an observed roster rather than treating all four
-- cut-array cells as participating players. These reads are action-owned, never
-- performed during UI rendering. They deliberately do not invent a gross pot.
local function read_payout_context(family,finish_party)
    family = tostring(family or "")
    if not CUT_PROFILES[family] then return nil, "This heist has no cut profile." end
    local supported, why = launch_build_status()
    if not supported then return nil, why end
    local identity, err = cut_identity(family)
    if not identity then return nil, err end
    local globals, globals_err = global_service()
    if not globals then return nil, globals_err end
    local result = { family=family, identity=identity.key, active_slots={}, participants={},
        character_slot=identity.slot, owner_pid=identity.pid, source_revision=SOURCE_REVISION, live_status="LIVE_RETEST_REQUIRED" }
    local ok, reason = pcall(function()
        local function read(index)
            local value=globals.GetInt(index)
            assert(type(value)=="number" and value%1==0,"Participant field is unreadable.")
            return value
        end
        local layout, board = NORMAL_CUTS[family], BOARD_PROFILES[family]
        local launcher_hash=script_hash(FMMC_PROFILE.script)
        local launcher_active=launcher_hash and thread_count(launcher_hash)==1
        local classic_hash=assert(script_hash("fm_mission_controller"))
        local classic_count=thread_count(classic_hash)
        local modern_count=thread_count(assert(script_hash("fm_mission_controller_2020")))
        assert((classic_count==0 or classic_count==1) and (modern_count==0 or modern_count==1),
            'Controller instance is ambiguous or unreadable.')
        assert(classic_count+modern_count<=1,'Multiple mission controllers are active.')
        local active_controller=modern_count==1 or classic_count==1
        -- FMC exists during the Apartment cut board in initialization state 0.
        -- Only that exact state may defer to the current board owner. Loading
        -- state 9 and result state 12 cannot reuse old board publication data.
        if active_controller and family=='apartment' and launcher_active and classic_count==1 and modern_count==0 then
            local p=HeistOps.controllers.fm_mission_controller
            local exact,why=HeistOps.script_identity(classic_hash,p.root,'fm_mission_controller');assert(exact,why)
            local state=binding('ScriptLocal').GetInt(classic_hash,p.root)
            assert(type(state)=='number' and state%1==0,'The Apartment controller phase is unreadable.')
            if state==0 then
                result.preparing_controller={hash=classic_hash,thread_id=exact.thread_id,pointer=exact.pointer,root=p.root}
                active_controller=false
            end
        end
        if active_controller then
            assert(family=="cayo" or family=="apartment" or family=="casino" or family=="doomsday","Party cuts are copied at launch. Active all-player payout recalculation is unavailable for this heist; enable in the lobby.")
            local ctx,controller_error=HeistOps.controller(family);assert(ctx,controller_error)
            -- Cache only successful bytecode verification for this exact VM
            -- allocation, thread, host, roster, and lifecycle generation.
            if HeistOps.payout_guard_identity~=ctx.controller_identity then
                HeistOps.guard(ctx.script_hash,ctx.script)
                HeistOps.payout_guard_identity=ctx.controller_identity
            end
            local party_finish=finish_party==true and family=='casino'
            assert(party_finish or #ctx.participants==1 and ctx.participants[1].player==identity.pid,"Active payout adjustment requires one exact local-host participant.")
            result.finish_party=party_finish or nil
            if family=="apartment" or family=="doomsday" then
                assert(binding("ScriptLocal").GetInt(ctx.script_hash,ctx.profile.teams)==1,"Active classic payout requires exactly one active team.")
            end
            result.route="controller";result.heist=ctx.heist;result.mission=ctx.mission
            result.script=ctx.script;result.script_hash=ctx.script_hash;result.controller_identity=ctx.controller_identity
            result.host_player=ctx.host_player;result.host_participant_index=ctx.host_participant_index
            result.active_slots={1};result.participants=ctx.participants
            if party_finish then
                result.active_slots={}
                for i=1,#ctx.participants do result.active_slots[i]=i end
            end
            local original_host_rows=0
            result.original_crew={}
            if family=="cayo" then for i=0,3 do
                local crew=read(1981687+ctx.host_player*27+i)
                local share=read(1981697+ctx.host_player*27+i)
                result.original_crew[#result.original_crew+1]=crew..":"..share
                if crew==ctx.host_player then original_host_rows=original_host_rows+1
                else assert(share==0,"Original party shares could redistribute; active solo adjustment unavailable.") end
            end
            assert(original_host_rows==1,"Original Cayo crew roster is ambiguous.") end
        elseif layout and board and not launcher_active then
            local hash=assert(script_hash(board.script))
            assert(thread_count(hash)==1,"Open this heist's planning board first.")
            assert(binding("ScriptLocal").GetInt(hash,board.local_index)==board.ready_value,"Wait for the planning board to finish loading.")
            assert(read(layout.owner)==identity.pid,"Only the planning owner can apply payout cuts.")
            local count=read(layout.count)
            assert(count>=1 and count<=4,"The planning roster is unavailable.")
            local seen={}
            for slot=1,4 do
                local pid=read(layout.participants+slot-1)
                if slot<=count then
                    assert(pid>=0 and pid<=31 and not seen[pid],"The planning roster is ambiguous.")
                    assert(read(layout.readiness+slot-1)==0 or pid==identity.pid,"A crew member is already ready; reopen cut selection.")
                    seen[pid]=true
                    result.active_slots[#result.active_slots+1]=slot
                    result.participants[#result.participants+1]={slot=slot,player=pid}
                else assert(pid==-1,"The planning roster is still changing.") end
            end
            assert(seen[identity.pid],"The planning owner is missing from the crew.")
            result.route="planning"
            result.heist=family
        else
            local ctx, context_err=launch_context(true)
            assert(ctx,context_err)
            local detected,heist=HeistOps.identify(globals,ctx.mission)
            assert(detected==family,"The launcher does not identify this family's finale.")
            result.heist=heist
            -- The shared launcher VM can include unrelated session players.
            -- Invitation authority was proved by launch_context; cut authority
            -- and slots come from the current family's own publication state.
            local payout_layout=PAYOUT_ROSTERS[family]
            local participant_base=FMMC_PROFILE.participant_base
            local bits
            if payout_layout then
                local board_hash=assert(script_hash(board.script))
                assert(thread_count(board_hash)==1,"Wait for this heist's planning cut screen to initialize.")
                assert(read(payout_layout.owner)==identity.pid,"Only the current planning owner can publish this heist's cuts.")
                if payout_layout.phase then
                    assert(read(payout_layout.phase)==payout_layout.ready_phase,"The finale planning cut screen is still loading.")
                else
                    assert(binding("ScriptLocal").GetInt(board_hash,board.local_index)==board.ready_value,
                        "The planning cut screen is still loading.")
                end
                local count=read(payout_layout.count)
                assert(count>=1 and count<=4,"Wait for this heist's planning crew to finish loading.")
                participant_base=payout_layout.participants
                bits=(1<<count)-1
                for slot=0,3 do
                    local pid=read(participant_base+slot)
                    if slot<count then
                        assert(pid>=0 and pid<=31,"The planning cut roster is incomplete.")
                        assert(read(payout_layout.readiness+slot)==0 or pid==identity.pid,
                            "A crew member is already ready; reopen cut selection.")
                    else
                        assert(pid==-1,"The planning cut roster is still changing.")
                    end
                end
                result.cut_authority="board:"..tostring(read(payout_layout.owner))
            else
                -- Apartment func_8399 publishes these slots; f_3001 is its
                -- board mask and is not reused for any other heist family.
                assert(read(1941142)==5 and read(1845348+identity.pid*884+185)==27,
                    "Open the Apartment finale cut board before publishing cuts.")
                bits=read(FMMC_PROFILE.active_slots_index)
                result.cut_authority=ctx.host_role..":"..tostring(ctx.leader)
            end
            assert(bits>=1 and bits<=15,"The launcher participant mask is invalid.")
            local seen={}
            for slot=1,4 do
                local pid=read(participant_base+slot-1)
                if active_slot(bits,slot-1) then
                    assert(pid>=0 and pid<=31 and not seen[pid],"The launcher roster is ambiguous.")
                    assert(binding("Natives").InvokeBool(0xB8DFD30D6973E135,pid)==true,"A heist crew member is no longer active.")
                    seen[pid]=true
                    result.active_slots[#result.active_slots+1]=slot
                    result.participants[#result.participants+1]={slot=slot,player=pid}
                else
                    assert(pid==-1,"The heist cut roster and occupied slots disagree.")
                end
            end
            assert(seen[identity.pid],"The host is missing from the launcher roster.")
            result.route="launcher"
            result.mission=ctx.mission
            result.launcher=ctx.identity.thread_id..":"..ctx.identity.pointer..":"..ctx.host_role..":"..result.cut_authority
        end
    end)
    if not ok then return nil,tostring(reason) end
    local rids,members=HeistOps.member_rids(result.participants)
    if not rids then return nil,members end
    result.member_map=members
    local natives=binding('Natives')
    if natives and type(natives.InvokeString)=='function' then
        for _,row in ipairs(result.participants) do
            local readable,name=pcall(natives.InvokeString,0x6D0DE6A7B5DA71F8,row.player)
            if readable and type(name)=='string' and #name>0 and #name<=128 then row.name=name:gsub('[%c]','') end
        end
    end
    local parts={family,result.identity,result.route,tostring(result.mission or ""),tostring(result.launcher or ""),tostring(result.controller_identity or "")}
    if result.preparing_controller then
        local p=result.preparing_controller
        local exact,why=HeistOps.script_identity(p.hash,p.root,'fm_mission_controller')
        if not exact or exact.thread_id~=p.thread_id or exact.pointer~=p.pointer
            or binding('ScriptLocal').GetInt(p.hash,p.root)~=0 then
            return nil,why or 'The Apartment controller left its planning phase.'
        end
        parts[#parts+1]='preparing='..p.thread_id..':'..p.pointer..':0'
    end
    for _,item in ipairs(result.participants) do parts[#parts+1]=item.slot.."="..item.player.."@"..members[item.player] end
    for _,row in ipairs(result.original_crew or {}) do parts[#parts+1]="original="..row end
    result.key=table.concat(parts,"|")
    if same_cut_context(family,identity)~=true then return nil,"The heist context changed while reading the crew." end
    return result
end

local function validate_payout_context(family, expected)
    if type(expected)~="table" or expected.family~=family or type(expected.key)~="string" then
        return false,"Refresh the heist payout context first."
    end
    local current,reason=read_payout_context(family,expected.finish_party)
    if not current then return false,reason end
    if current.key~=expected.key then return false,"The crew or heist changed; recalculate the cuts." end
    local ok,why=pcall(function()
        local g=assert(global_service())
        for _,row in ipairs(expected.payout_observations or {}) do
            local value
            if row.kind=="local_int" then
                assert(row.script_hash==current.script_hash,"Payout observation script changed.")
                value=binding("ScriptLocal").GetInt(row.script_hash,row.index)
            elseif row.kind=="native_bool" or row.kind=="native_string" then
                local invoke=row.kind=='native_bool' and binding('Natives').InvokeBool or binding('Natives').InvokeString
                if row.argument==nil then value=invoke(row.index) else value=invoke(row.index,row.argument) end
            elseif row.kind=="float" then value=g.GetFloat(row.index)
            else value=g.GetInt(row.index) end
            assert(value==row.value,"Take, fee, or difficulty changed; recalculate the payout.")
        end
    end)
    if not ok then return false,tostring(why) end
    return true
end

local function normal_cut_guard(family, values)
    local layout, board = NORMAL_CUTS[family], BOARD_PROFILES[family]
    if not layout then return false, "Normal board workflow is unavailable for this family; raw mode remains separate." end
    local globals, err = global_service(); if not globals then return false, err end
    local ok, result = pcall(function()
        local function read(index)
            local v=globals.GetInt(index);assert(type(v)=="number" and v%1==0,"planning field unreadable");return v
        end
        local hash=assert(script_hash(board.script))
        assert(binding("Natives").InvokeInt(THREAD_COUNT_HASH,hash)==1,"open the planning board")
        assert(binding("ScriptLocal").GetInt(hash,board.local_index)==board.ready_value,"board is not ready")
        assert(read(layout.owner)==local_player_id(),"local player is not planning owner")
        local n=read(layout.count);assert(n>=1 and n<=4,"participant count is unknown")
        local tunable,flags=read(262145+33926),read(1989970)
        assert(tunable==-1 or ((flags & (1<<4))==0 and (flags & (1<<layout.lock_bit))==0),"crew cuts are locked")
        local ids,total={},0
        for i=1,4 do
            local pid=read(layout.participants+i-1)
            if i<=n then
                assert(pid>=0 and pid<=31 and not ids[pid],"participant identity is invalid")
                ids[pid]=true
                assert(read(layout.readiness+i-1)==0 or pid==local_player_id(),"participant is already ready")
                assert(values[i]%5==0 and values[i]>=15 and values[i]<=(n==1 and 100 or 85),"normal cuts require five-point steps and board bounds")
            else
                assert(pid==-1 and values[i]==0,"inactive slots must have zero cuts")
            end
            total=total+values[i]
        end
        assert(total==100,"normal split must total 100; remainder is not a fifth participant")
        return true
    end)
    return ok and result==true, ok and nil or tostring(result)
end

-- Conflicts are sticky per field. They block new transactions, but never
-- suppress recovery of other attempted fields. At most five fields are checked
-- per existing 250 ms tick; every retry uses the original context guards.
local function cut_cleanup_counts(tx)
    local pending, conflicts = 0, 0
    for _,slot in ipairs(tx.attempted) do
        local disposition=tx.disposition[slot]
        if disposition=="EXTERNAL_CONFLICT" then conflicts=conflicts+1
        elseif not tx.resolved[slot] then pending=pending+1 end
    end
    tx.pending_fields,tx.conflict_fields=pending,conflicts
    return pending,conflicts
end

local function rollback_cuts(tx)
    local family, profile = tx.family, CUT_PROFILES[tx.family]
    cut_outcomes[family]=tx
    cut_cleanup_counts(tx)
    local same, reason = same_cut_context(family,tx.identity)
    if same==true and tx.payout_context then
        same,reason=validate_payout_context(family,tx.payout_context)
    end
    if same~=true then
        tx.state = same==false and "CONTEXT_CHANGED" or "RESTORE_PENDING"
        tx.reason=reason
        cut_cache[family]=nil
        return false
    end
    local globals=global_service(); if not globals then return false end
    for i=#tx.attempted,1,-1 do
        local slot=tx.attempted[i]
        if not tx.resolved[slot] and tx.disposition[slot]~="EXTERNAL_CONFLICT" then
            local still=same_cut_context(family,tx.identity)
            if still==true and tx.payout_context then still=validate_payout_context(family,tx.payout_context) end
            if still~=true then break end
            local index=tx.indices and tx.indices[slot] or profile.base_index+slot
            local ok,current=pcall(globals.GetInt,index)
            if ok and current==tx.before[slot] then
                tx.resolved[slot],tx.disposition[slot]=true,"RESTORED"
            elseif ok and current==tx.requested[slot] then
                tx.disposition[slot]="OWNED_PENDING"
                -- A throwing/rejecting writer can still have mutated memory.
                -- Readback, not its return value, determines restoration.
                pcall(globals.SetInt,index,tx.before[slot])
                local read_ok,observed=pcall(globals.GetInt,index)
                if read_ok and observed==tx.before[slot] then
                    tx.resolved[slot],tx.disposition[slot]=true,"RESTORED"
                elseif read_ok and type(observed)=="number" and observed~=tx.requested[slot] then
                    tx.disposition[slot]="EXTERNAL_CONFLICT"
                end
            elseif ok and type(current)=="number" then
                tx.disposition[slot]="EXTERNAL_CONFLICT" -- relinquish permanently; no later overwrite
            else tx.disposition[slot]="UNREADABLE_PENDING" end
        end
    end
    local pending,conflicts=cut_cleanup_counts(tx)
    local complete=pending==0 and conflicts==0
    if complete then
        cut_pending[family]=nil
        local observed=read_cuts(family)
        tx.state,tx.reason="ROLLED_BACK","Attempted fields restored by readback; no payout claim."
        if not observed then cut_cache[family]=nil end
    else
        tx.state=conflicts>0 and "EXTERNAL_CONFLICT" or "RESTORE_PENDING"
        tx.reason=conflicts>0 and ("External fields preserved: %d; pending owned/unreadable cleanup: %d. New transactions blocked."):format(conflicts,pending)
            or "Rollback incomplete; still-owned fields will be retried in this context."
        cut_cache[family]=nil
    end
    cut_outcomes[family]=tx
    return complete
end

local function cut_transaction(family, requested, restoring, mode, restore_remainder, expected_payout_context)
    family=tostring(family or "")
    local profile = CUT_PROFILES[family]
    if not profile then return false, "No current Enhanced cut profile is available for this heist." end
    if mode~=nil and mode~="raw" and mode~="normal" then return false,"Unknown cut workflow; no write attempted." end
    if cut_pending[family] then
        rollback_cuts(cut_pending[family])
        if cut_pending[family] then return false, "Earlier cut cleanup remains unresolved; no new write was attempted." end
    end
    local valid,validation_err=validate_cut_request(profile,requested)
    if not valid then return false,validation_err end
    local identity,identity_err=cut_identity(family)
    if not identity then return false,identity_err end
    if family=="apartment" and not expected_payout_context then
        local err;expected_payout_context,err=read_payout_context(family)
        if not expected_payout_context then return false,err end
    end
    if expected_payout_context then
        local valid,why=validate_payout_context(family,expected_payout_context)
        if not valid then return false,why end
    end
    if family=='apartment' and not restoring then
        if not expected_payout_context or expected_payout_context.route~='launcher' then
            return false,'Apartment board cuts require the current finale cut screen.'
        end
        local total,occupied=0,{}
        for _,row in ipairs(expected_payout_context.participants)do occupied[row.slot]=true end
        for slot=1,4 do
            if not occupied[slot] and requested[slot]~=0 then return false,'An absent Apartment crew member must have a zero board cut.' end
            total=total+requested[slot]
        end
        if total~=100 then
            return false,'Apartment finale board cuts must total 100%. The game resets larger board totals; active solo payout percentages are calculated after launch.'
        end
    end
    if family=='apartment' then
        local checked,why=pcall(HeistOps.guard,assert(script_hash(FMMC_PROFILE.script)),'apartment_planning_board')
        if not checked then return false,tostring(why) end
    end
    if mode=="normal" then
        local normal,why=normal_cut_guard(family,requested);if not normal then return false,why end
    end
    local before,read_err=read_cuts(family);if not before then return false,read_err end
    if mode=="normal" then
        local ok,remainder=pcall(global_service().GetInt,profile.base_index+5)
        local total=0;for _,v in ipairs(before) do total=total+v end
        if not ok or type(remainder)~="number" or remainder<0 or remainder>100 or remainder%1~=0
            or total+remainder~=100 then return false,"Board cuts/remainder are inconsistent; use raw mode only deliberately." end
        before[5]=remainder;requested[5]=0
    end
    if restore_remainder~=nil then
        local ok,value=pcall(global_service().GetInt,profile.base_index+5)
        if not ok or value~=0 then return false,"Board remainder changed; restoration not attempted." end
        before[5]=value;requested[5]=restore_remainder
    end
    local indices,extra_before,extra_requested={},{},{}
    if family=="apartment" then
        local host_slot
        for _,row in ipairs(expected_payout_context.participants) do if row.player==identity.pid then host_slot=row.slot end end
        if not host_slot then return false,"Apartment host cut slot is unavailable." end
        for i=1,4 do indices[i]=profile.base_index+i;indices[4+i]=1941382+i end
        indices[9]=2692687 -- Global_2686124.f_6563, consumed by FMC func_2512
        -- func8593 resets these remainders when a larger board total is seen;
        -- func8414 blocks Continue until the host remainder is zero.
        indices[10],indices[11]=1936412,1941387
        local saved=restoring and previous_cuts[family]
        for i=5,11 do
            local ok,value=pcall(global_service().GetInt,indices[i])
            if not ok or type(value)~="number" or value%1~=0 or value<0 or value>(i>=10 and 100 or 9999) then return false,"Apartment cut consumer is unreadable." end
            if saved and value~=saved.extra_applied[i-4] then return false,"Apartment cut consumer changed; external value preserved." end
            extra_before[i-4]=value
            extra_requested[i-4]=saved and saved.extra_values[i-4] or (i>=10 and 0 or requested[i==9 and host_slot or i-4])
        end
    end
    local original_before,original_requested=copy_array(before),copy_array(requested)
    for i=1,#extra_before do before[4+i]=extra_before[i];requested[4+i]=extra_requested[i] end
    local tx={family=family,identity=identity,payout_context=expected_payout_context,before=before,requested=copy_array(requested),indices=next(indices) and indices or nil,
        attempted={},resolved={},disposition={},mode=mode or "raw",state="PENDING",time=runtime_time_ms()}
    local globals=global_service()
    local function fail(message)
        cut_pending[family]=tx
        local restored=rollback_cuts(tx)
        return false,message..(restored and " Attempted fields restored by readback." or " Cleanup remains unresolved."),tx.state
    end
    for slot=1,#requested do
        local index=tx.indices and tx.indices[slot] or profile.base_index+slot
        if before[slot]~=requested[slot] then
            if same_cut_context(family,identity)~=true then return fail("Context changed before write.") end
            if expected_payout_context then
                local valid,why=validate_payout_context(family,expected_payout_context)
                if not valid then return fail(why) end
            end
            if mode=="normal" then
                local normal,why=normal_cut_guard(family,requested);if not normal then return fail(why) end
            end
            local readable,current=pcall(globals.GetInt,index)
            if not readable or current~=before[slot] then return fail("Cuts changed before write.") end
            tx.attempted[#tx.attempted+1]=slot -- BEFORE any mutating host call
            tx.disposition[slot]="ATTEMPTED"
            local ok,result=pcall(globals.SetInt,index,requested[slot])
            if not ok or result==false then return fail(("Player %d cut write rejected."):format(slot)) end
        end
    end
    if same_cut_context(family,identity)~=true then return fail("Context changed during write.") end
    if expected_payout_context then
        local valid,why=validate_payout_context(family,expected_payout_context)
        if not valid then return fail(why) end
    end
    local observed,verify_err=read_cuts(family)
    if not observed then return fail(verify_err) end
    if requested[5]~=nil and family~="apartment" then
        local ok,remainder=pcall(globals.GetInt,profile.base_index+5)
        if not ok or remainder~=requested[5] then return fail("Board remainder did not verify.") end
    end
    for slot=1,profile.slot_count do
        if observed[slot]~=requested[slot] then return fail("Cut readback differs from the request.") end
    end
    for i=5,#requested do if tx.indices then
        local ok,value=pcall(globals.GetInt,tx.indices[i])
        if not ok or value~=requested[i] then return fail("Apartment cut consumer did not verify.") end
    end end
    if #tx.attempted==0 then return true,"Cuts already match by readback; payout not verified.","ALREADY_APPLIED" end
    previous_cuts[family]={values=original_before,applied=original_requested,extra_values=extra_before,extra_applied=extra_requested,identity=identity,payout_context=expected_payout_context}
    tx.state,tx.reason="READBACK_MATCH","Cut globals match; board progression and payout are not verified."
    cut_outcomes[family]=tx
    return true,tx.reason,"VERIFIED"
end

tick_cut_transactions = function()
    if not started or runtime_time_ms()<next_cut_tick then return end
    next_cut_tick=runtime_time_ms()+250
    observe_boards()
    for _,family in ipairs({"cayo","casino","doomsday","apartment"}) do
        local tx=cut_pending[family]
        if tx and tx.state~="CONTEXT_CHANGED" and (tx.pending_fields or 0)>0 then rollback_cuts(tx) end
        local outcome=cut_outcomes[family]
        if not tx and outcome and outcome.state=="READBACK_MATCH" and runtime_time_ms()-outcome.time<=5000 then
            local same=same_cut_context(family,outcome.identity)
            if same==false then outcome.state,outcome.reason="CONTEXT_CHANGED","Observed context changed after readback."
            elseif same==true then
                local values=read_cuts(family)
                if values then
                    for slot=1,4 do
                        if values[slot]~=outcome.requested[slot] then
                            outcome.state,outcome.reason="CHANGED_AFTER_READBACK","Game/other owner changed cuts after successful readback; no automatic reapply."
                            break
                        end
                    end
                end
            end
        end
    end
end

local function cuts_status(family)
    family = tostring(family or "")
    local profile = CUT_PROFILES[family]
    if not profile then
        return { support = "UNSUPPORTED", ready = false, detected_participants = 0,
            reason = "No current Enhanced active-finale cut profile is available." }
    end
    local outcome=cut_outcomes[family]
    local dispositions={}
    for slot,value in pairs(outcome and outcome.disposition or {}) do dispositions[slot]=value end
    local cache = cut_cache[family]
    local values = cache and copy_array(cache.values) or nil
    local total = 0
    for _, value in ipairs(values or {}) do total = total + value end
    return {
        support = values and "EXPERIMENTAL" or "BLOCKED", ready = values ~= nil,
        detected_participants = values and profile.slot_count or 0,
        values = values or {}, total = total, presets = CUT_PRESETS,
        max_cut = tonumber(profile.max_cut) or 999,
        standard_total = total == 100,
        restore_ready = previous_cuts[family] ~= nil and cut_pending[family] == nil,
        pending_cleanup = cut_pending[family] ~= nil,
        pending_cleanup_fields = outcome and outcome.pending_fields or 0,
        external_conflict_fields = outcome and outcome.conflict_fields or 0,
        field_dispositions = dispositions,
        new_writes_blocked = cut_pending[family] ~= nil,
        outcome = cut_outcomes[family] and cut_outcomes[family].state or "NOT_APPLIED",
        outcome_reason = cut_outcomes[family] and cut_outcomes[family].reason,
        normal_supported = NORMAL_CUTS[family] ~= nil,
        reason = cut_pending[family] and cut_pending[family].reason
            or values and (family=='apartment' and 'The Apartment cut board requires a 100% total. Active solo payout percentages are calculated after launch.'
                or "Current cut globals are cached. Apply rereads all four slots before any write; the combined total is not restricted.")
            or "Current cuts load automatically.",
        confidence = "CURRENT_SOURCE_CORROBORATED", live_status = "LIVE_TEST_REQUIRED",
        evidence = profile.evidence, source_revision = SOURCE_REVISION,
        framework = "CSCRIPT_HEIST_CUT_PROFILE_V3_NO_AUTO_REFRESH",
    }
end

local function apply_cuts(family, values, mode, expected_payout_context)
    if family=='apartment' and not expected_payout_context then
        local why;expected_payout_context,why=read_payout_context(family)
        if not expected_payout_context then return false,why end
    end
    if expected_payout_context and expected_payout_context.route=="controller" then return HeistOps.apply_active_cut(family,values,expected_payout_context) end
    return cut_transaction(tostring(family or ""), copy_array(values), false, mode, nil, expected_payout_context)
end

local function restore_cuts(family)
    if HeistOps.active_cut and HeistOps.active_cut.family==family then return HeistOps.restore_active_cut() end
    family = tostring(family or "")
    local values = previous_cuts[family]
    if not values then return false, "No CScript cut snapshot is available for this heist." end
    if same_cut_context(family,values.identity)~=true then return false,"Previous cut context changed; restoration was not attempted." end
    local current=read_cuts(family)
    if not current then return false,"Current cuts unreadable; restoration was not attempted." end
    for slot=1,4 do
        if current[slot]~=values.applied[slot] then return false,"Cuts changed after CScript readback; external values preserved." end
    end
    local desired=copy_array(values.values);local remainder=desired[5];desired[5]=nil
    return cut_transaction(family, desired, true, nil, remainder, values.payout_context)
end

local function invalidate_cuts()
    if HeistOps.ending_skip then HeistOps.ending_skip.Cancel() end
    cut_generation=cut_generation+1
    for _,observation in pairs(board_observations) do
        if observation.state=="SUBMITTED" then observation.state="CONTEXT_CHANGED" end
    end
    previous_cuts, cut_cache = {}, {}
    for family,tx in pairs(cut_pending) do
        tx.state,tx.reason="CONTEXT_CHANGED","Session/character lifecycle changed; pending debt retained without stale writes."
        cut_outcomes[family]=tx
    end
end

