function HeistOps.identify(g, mission)
 if type(mission)~="number" or mission%1~=0 or mission==0 then return nil,"Mission hash is unavailable ("..tostring(mission)..")." end
 local found={}
 local function test(index,family,key)
  local v=g.GetInt(index)
  if type(v)=="number" and v~=0 and v%4294967296==mission%4294967296 then found[family..":"..key]={family,key} end
 end
 for _,x in ipairs({{9188,"fleeca"},{9193,"prison"},{9200,"humane"},{9206,"series_a"},{9212,"pacific"},{9213,"pacific"},{9220,"pacific"}}) do test(262145+x[1],"apartment",x[2]) end
 for _,x in ipairs({{3,"act1"},{8,"act2"},{14,"act3"},{15,"act3"}}) do test(266854+x[1],"doomsday",x[2]) end
 for i=0,20 do test(268205+i,"casino","casino") end
 for i=0,10 do test(291682+i,"cayo","cayo") end
 local only;for _,v in pairs(found) do if only then return nil,"Mission hash matches more than one heist family/finale." end;only=v end
 if only then return only[1],only[2] end
 return nil,("Mission hash %s (0x%08X) does not match the current heist tunables."):format(tostring(mission),mission%4294967296)
end
function HeistOps.bytes(text)
 local result={};for value in text:gmatch("%x%x") do result[#result+1]=tonumber(value,16) end;return result
end
function HeistOps.matches(memory,address,bytes,patch)
 for i,v in ipairs(bytes) do
  local expected=patch and patch[i] or v
  if memory.ReadUByte(address+i-1)~=expected then return false end
 end
 return true
end
function HeistOps.signature_segments(signature,override)
 local bytes=override or signature.decoded or HeistOps.bytes(signature.bytes)
 if not override then signature.decoded=bytes;if signature.segments then return signature.segments end end
 assert(type(signature.pc)=="number" and signature.pc%1==0 and signature.pc>=0,"Source signature PC is unavailable.")
 local segments,offset={},0
 while offset<#bytes do
  local length=math.min(#bytes-offset,16384-(signature.pc+offset)%16384)
  local part,text={},{}
  for i=1,length do part[i]=bytes[offset+i];text[i]=("%02X"):format(part[i]) end
  segments[#segments+1]={offset=offset,bytes=part,pattern=table.concat(text," ")}
  offset=offset+length
 end
 if not override then signature.segments=segments end
 return segments
end
function HeistOps.guard(hash,name)
 local memory=binding("Memory");assert(memory and memory.ScanScript and memory.ReadUByte,"Script bytecode verification unavailable.")
 local addresses={}
 for _,signature in ipairs(assert(HeistOps.signatures[name])) do
  local first
  -- VM code pages are 16 KiB and need not be adjacent in process memory.
  -- Preserve/check every byte of the captured function, scanning each exact
  -- page fragment separately. All current split fragments are corpus-unique.
  for segment,part in ipairs(HeistOps.signature_segments(signature)) do
   local scanned,ptr=pcall(memory.ScanScript,hash,part.pattern)
   assert(scanned and type(ptr)=="number" and ptr%1==0 and ptr>=65536,
    ("Script bytecode scan failed (script=%s signature=%s pc=%d segment=%d offset=%d observed=%s).")
     :format(name,signature.name,signature.pc,segment,part.offset,tostring(ptr)))
   for i,expected in ipairs(part.bytes) do
    local readable,observed=pcall(memory.ReadUByte,ptr+i-1)
    if not readable or observed~=expected then
     error(("Script code changed during verification (script=%s signature=%s pc=%d segment=%d offset=%d expected=0x%02X observed=%s type=%s).")
      :format(name,signature.name,signature.pc,segment,part.offset+i-1,expected,tostring(observed),type(observed)))
    end
   end
   if not first then first=ptr end
  end
  addresses[#addresses+1]=assert(first,"Source signature is empty.")
 end
 return addresses
end
-- Read-only observations reuse completed verification for one exact controller
-- identity. Mutating submissions retain the full guard immediately before writes.
function HeistOps.read_guard(ctx,name)
 local identity=ctx and ctx.controller_identity
 if type(identity)~="string" or identity=="" then return HeistOps.guard(ctx.script_hash,name) end
 local memory=binding("Memory")
 local key=tostring(cut_generation)..":"..tostring(ctx.script_hash)..":"..identity
 local cache=HeistOps.read_guard_cache
 if not cache or cache.key~=key or cache.memory~=memory then
  cache={key=key,memory=memory,groups={}};HeistOps.read_guard_cache=cache
 end
 local addresses=cache.groups[name]
 if not addresses then
  addresses=HeistOps.guard(ctx.script_hash,name)
  cache.groups[name]=addresses
 end
 local result={};for i,address in ipairs(addresses)do result[i]=address end
 return result
end

