function HeistOps.can_handoff()
    if HeistOps.pending or HeistOps.active_cut or solo_override
        or HeistOps.catalogue_cleanup or HeistOps.late_admission or ready_snapshot or next(cut_pending) then return false end
    local apartment=context_ref and context_ref.Modules and context_ref.Modules.HeistAdapterApartment
    if apartment then
        if type(apartment.CanHandoff)=="function" then
            local called,clean,why=pcall(apartment.CanHandoff)
            if not called then return false,tostring(clean) end
            if clean~=true then return false,why or "Apartment planner cleanup remains pending." end
            return true
        end
        local ok,status=pcall(function()return apartment.ChallengeStatus()end)
        return ok and type(status)=="table" and status.enabled==false
