   local state=g.GetInt(4515492+1+slot*84+67)
   assert(type(state)=='number' and state%1==0 and state>=0 and state<=3,'Transaction state is unavailable.')
   if state~=0 then return false,"Wait for GTA's current transaction to finish." end
  end
  return true
 end)
 if not ok then return false,'Game transaction status is unavailable. Try again shortly.' end
