    if clean~=true then return false,why end
    if context and context.CScript and context.CScript.HeistRuntimeProfiles == public_api then
        context.CScript.HeistRuntimeProfiles = nil
    end
    if context and context.Modules and context.Modules.HeistRuntimeProfiles == Module then
        context.Modules.HeistRuntimeProfiles = nil
    end
    context_ref, public_api = nil, nil
end

return Module
