local function economy()
    return context_ref and context_ref.CScript and context_ref.CScript.Economy
end

local function raw_binding(name)
    local raw = context_ref and context_ref.Raw
    if raw and raw[name] ~= nil then return raw[name] end
    return type(_G) == "table" and rawget(_G, name) or nil
end

local function semantic_tunable_int(profile)
    profile = profile or {}
    local globals = raw_binding("ScriptGlobal")
    local memory = raw_binding("Memory")
    local utils = raw_binding("Utils")
    local index = 262145 + math.floor(tonumber(profile.offset) or -999999)
    local minimum = tonumber(profile.minimum) or 0
    local maximum = tonumber(profile.maximum) or 2147483647
    local raw_value
    if globals and type(globals.GetInt) == "function" and index >= 0 then
        local ok, value = pcall(globals.GetInt, index)
        value = ok and tonumber(value) or nil
        if value ~= nil and value % 1 == 0 and value >= minimum and value <= maximum then raw_value = math.floor(value) end
    end
    local semantic_value, semantic_hash, semantic_ptr
    if globals and type(globals.GetTunableByHash) == "function"
        and memory and type(memory.ReadInt) == "function"
        and utils and type(utils.Joaat) == "function" then
        local ok_hash, hash = pcall(utils.Joaat, tostring(profile.name or ""))
        semantic_hash = ok_hash and tonumber(hash) or nil
        if semantic_hash then
            local ok_ptr, ptr = pcall(globals.GetTunableByHash, semantic_hash)
            semantic_ptr = ok_ptr and tonumber(ptr) or nil
            if semantic_ptr and semantic_ptr ~= 0 then
                local ok_value, value = pcall(memory.ReadInt, semantic_ptr)
                value = ok_value and tonumber(value) or nil
                if value ~= nil and value % 1 == 0 and value >= minimum and value <= maximum then
                    semantic_value = math.floor(value)
                end
            end
        end
    end
    if semantic_value ~= nil and raw_value ~= nil and semantic_value ~= raw_value then
        return nil, ("%s semantic/raw disagreement (%s vs %s)"):format(
            tostring(profile.name), tostring(semantic_value), tostring(raw_value))
    end
    local value = semantic_value or raw_value
    if value == nil then return nil, tostring(profile.name or "tunable") .. " is unavailable" end
    return value, nil, {
        name = profile.name, index = index, semantic_hash = semantic_hash, semantic_pointer = semantic_ptr,
        resolver = semantic_value ~= nil and raw_value ~= nil and "semantic+raw agreement"
            or semantic_value ~= nil and "semantic hash" or "verified raw global",
    }
end


local function tunable_descriptor(key)
    local descriptor = TUNABLE_OVERRIDE_CATALOG[tostring(key or "")]
    if not descriptor then return nil, "Unknown tunable override: " .. tostring(key) end
    return descriptor
end

local function validate_tunable_write_target(descriptor)
    local globals = raw_binding("ScriptGlobal")
    local memory = raw_binding("Memory")
    local utils = raw_binding("Utils")
    if not (globals and type(globals.GetInt)=="function" and type(globals.SetInt)=="function"
        and type(globals.GetTunableByHash)=="function") then
        return nil, "Cherax ScriptGlobal semantic/read/write access is unavailable."
    end
    if not (memory and type(memory.ReadInt)=="function" and utils and type(utils.Joaat)=="function") then
        return nil, "Cherax Memory/Utils semantic tunable validation is unavailable."
    end
    local value, err, meta = semantic_tunable_int({ name=descriptor.name, offset=descriptor.offset, minimum=0, maximum=2147483647 })
    if value == nil then return nil, err end
    if not meta or meta.resolver ~= "semantic+raw agreement" or not meta.semantic_pointer or meta.semantic_pointer == 0 then
        return nil, tostring(descriptor.name) .. " did not resolve through both semantic and raw current-build paths."
    end
    return { globals=globals, value=value, meta=meta }
end

local function active_override_count()
    local count=0
    for _ in pairs(State and State.tunable_overrides or {}) do count=count+1 end
    return count
end

local function restore_tunable_key(key, quiet)
    local owned = State and State.tunable_overrides and State.tunable_overrides[key]
    if not owned then return true, false, "not owned" end
    local descriptor = TUNABLE_OVERRIDE_CATALOG[key]
    if not descriptor then
        State.tunable_overrides[key]=nil
        return true, false, "descriptor missing"
    end
    local resolved, err = validate_tunable_write_target(descriptor)
    if not resolved then return false, false, err end
    local current=tonumber(resolved.value)
    if current == tonumber(owned.original) then
        State.tunable_overrides[key]=nil
        return true, false, "already restored"
    end
    if current ~= tonumber(owned.target) then
        -- Rockstar/cloud/another script changed the tunable after CScript. Never
        -- overwrite that newer state during cleanup.
        State.tunable_overrides[key]=nil
        local message=("%s changed outside CScript (%s -> %s); restore ownership released without writing.")
            :format(descriptor.label,tostring(owned.target),tostring(current))
        State.last_override_warning=message
        return true, false, message
    end
    local ok,result=pcall(resolved.globals.SetInt, resolved.meta.index, owned.original)
    if not ok or result==false then return false,false,"Cherax rejected restore for "..descriptor.label end
    local verify,verify_err=validate_tunable_write_target(descriptor)
    if not verify or tonumber(verify.value) ~= tonumber(owned.original) then
        return false,false,"Restore read-back failed for "..descriptor.label..": "..tostring(verify_err or (verify and verify.value))
    end
    State.tunable_overrides[key]=nil
    if not quiet then State.last_override_action="Restored "..descriptor.label end
    return true,true,"restored"
end

local function apply_tunable_key(key, target)
    local descriptor, descriptor_err = tunable_descriptor(key)
    if not descriptor then return false,false,descriptor_err end
    target=math.max(0,math.floor(tonumber(target) or 0))
    local resolved, err = validate_tunable_write_target(descriptor)
    if not resolved then return false,false,err end
    State.tunable_overrides = State.tunable_overrides or {}
    local owned=State.tunable_overrides[key]
    if owned then
        if tonumber(resolved.value)==target then return true,false,"already active" end
        return false,false,descriptor.label.." changed while CScript owns it; restore before reapplying."
    end
    local original=tonumber(resolved.value)
    if original==target then
        -- Snapshot matching targets too, so the profile can be tracked and
        -- restored without overwriting a later external change.
        State.tunable_overrides[key]={original=original,target=target,index=resolved.meta.index,
            name=descriptor.name,label=descriptor.label,group=descriptor.group,no_write=true}
        return true,false,"already at target"
    end
    local ok,result=pcall(resolved.globals.SetInt,resolved.meta.index,target)
    if not ok or result==false then return false,false,"Cherax rejected override for "..descriptor.label end
    local verify,verify_err=validate_tunable_write_target(descriptor)
    if not verify or tonumber(verify.value)~=target then
        pcall(resolved.globals.SetInt,resolved.meta.index,original)
        return false,false,"Override read-back failed for "..descriptor.label..": "..tostring(verify_err or (verify and verify.value))
    end
    State.tunable_overrides[key]={original=original,target=target,index=resolved.meta.index,name=descriptor.name,label=descriptor.label,group=descriptor.group}
    return true,true,"applied"
end

local function profile_keys(profile_key)
    profile_key=tostring(profile_key or "")
    if profile_key=="all" then
        local result,targets={},{}
        -- "All QoL Tunables" covers cooldowns and fees. MC route changes
        -- require the separate profile toggle.
        local order={"service_requests","business_work","freemode_work","vehicle_equipment","fee_relief"}
        for _,name in ipairs(order) do
            local profile=TUNABLE_OVERRIDE_PROFILES[name]
            for _,key in ipairs(profile.keys) do
                result[#result+1]=key
                targets[key]=profile.targets and profile.targets[key] or 0
            end
        end
        return result,"All QoL Tunables",targets
    end
    local profile=TUNABLE_OVERRIDE_PROFILES[profile_key]
    if not profile then return nil,"Unknown override profile: "..profile_key end
    local result={}; for _,key in ipairs(profile.keys) do result[#result+1]=key end
    return result,profile.label,profile.targets or {}
end

local function apply_override_profile(profile_key)
    if not State then return false,"Mission Tools is unavailable." end
    local keys,label,targets=profile_keys(profile_key)
    if not keys then return false,label end
    local newly_owned,changed,unchanged={},0,0
    for _,key in ipairs(keys) do
        local was_owned=State.tunable_overrides and State.tunable_overrides[key]~=nil
        local target=targets and targets[key] or 0
        local ok,did_change,err=apply_tunable_key(key,target)
        if not ok then
            for i=#newly_owned,1,-1 do restore_tunable_key(newly_owned[i],true) end
            State.last_override_error=tostring(err)
            return false,("%s override aborted at %s; this action's new writes were rolled back."):format(label,tostring(err))
        end
        if not was_owned and State.tunable_overrides and State.tunable_overrides[key] then
            newly_owned[#newly_owned+1]=key
        end
        if did_change then changed=changed+1 else unchanged=unchanged+1 end
    end
    State.last_override_error=nil
    State.last_override_action=("%s: %d changed, %d already at target/owned."):format(label,changed,unchanged)
    return true,State.last_override_action
end

local function restore_override_profile(profile_key, quiet)
    if not State then return false,"Mission Tools is unavailable." end
    local keys,label=profile_keys(profile_key)
    if not keys then return false,label end
    local restored,released,failures=0,0,{}
    for _,key in ipairs(keys) do
        if State.tunable_overrides and State.tunable_overrides[key] then
            local ok,did_restore,detail=restore_tunable_key(key,true)
            if not ok then failures[#failures+1]=tostring(detail)
            elseif did_restore then restored=restored+1 else released=released+1 end
        end
    end
    if #failures>0 then
        State.last_override_error=table.concat(failures," | ")
        return false,("%s restore incomplete: %s"):format(label,State.last_override_error)
    end
    State.last_override_error=nil
    local message=("%s: %d restored, %d already restored/external ownership released."):format(label,restored,released)
    if not quiet then State.last_override_action=message end
    return true,message
end

local function override_snapshot()
    local profiles={}
    for key,profile in pairs(TUNABLE_OVERRIDE_PROFILES) do
        local active=0
        for _,item_key in ipairs(profile.keys) do if State.tunable_overrides and State.tunable_overrides[item_key] then active=active+1 end end
        profiles[#profiles+1]={key=key,label=profile.label,total=#profile.keys,active=active,reason=profile.reason}
    end
    table.sort(profiles,function(a,b) return a.label<b.label end)
    return {active_count=active_override_count(), profiles=profiles, last_action=State.last_override_action,
        last_error=State.last_override_error, last_warning=State.last_override_warning}
end

local function read_work_cooldowns(core, slot)
    local now = os and type(os.time) == "function" and os.time() or 0
    local items, available = {}, 0
    for _, descriptor in ipairs(WORK_REQUEST_COOLDOWNS) do
        local qualified = core.QualifyStat(slot, descriptor.stat)
        local value, err = core.ReadStat(qualified)
        value = tonumber(value)
        if value ~= nil and value % 1 == 0 and value >= 0 then
            available = available + 1
            value = math.floor(value)
            local remaining = now > 0 and math.max(0, value - now) or nil
            items[#items + 1] = {
                key=descriptor.key, label=descriptor.label, stat=descriptor.stat, qualified_stat=qualified,
                cooldown_end=value, remaining_seconds=remaining,
                ready=remaining ~= nil and remaining <= 0 or value == 0,
                source=descriptor.source, available=true,
            }
        else
            items[#items + 1] = { key=descriptor.key, label=descriptor.label, stat=descriptor.stat,
                qualified_stat=qualified, available=false, error=tostring(err or "invalid cooldown timestamp") }
        end
    end
    return items, available
end

local function read_service_tunables()
    local items, available = {}, 0
    for _, descriptor in ipairs(SERVICE_TUNABLES) do
        local value, err, meta = semantic_tunable_int(descriptor)
        if value ~= nil then available = available + 1 end
        items[#items + 1] = {
            key=descriptor.key, label=descriptor.label, name=descriptor.name, kind=descriptor.kind,
            value=value, available=value ~= nil, error=value == nil and tostring(err) or nil,
            resolver=meta and meta.resolver or nil, global_index=meta and meta.index or (262145 + descriptor.offset),
            source="current Enhanced tuneables_processing.c + freemode request cooldown semantics",
        }
    end
    return items, available
end

local function read_daily_objective_rewards()
    local items, available = {}, 0
    for _, descriptor in ipairs(DAILY_OBJECTIVE_REWARDS) do
        local cash, cash_err, cash_meta = semantic_tunable_int({ name=descriptor.cash.name, offset=descriptor.cash.offset,
            minimum=0, maximum=100000000 })
        local rp, rp_err, rp_meta = semantic_tunable_int({ name=descriptor.rp.name, offset=descriptor.rp.offset,
            minimum=0, maximum=100000000 })
        local ok = cash ~= nil and rp ~= nil
        if ok then available = available + 1 end
        items[#items + 1] = {
            key=descriptor.key, label=descriptor.label, cash=cash, rp=rp, available=ok,
            cash_name=descriptor.cash.name, rp_name=descriptor.rp.name,
            cash_resolver=cash_meta and cash_meta.resolver or nil, rp_resolver=rp_meta and rp_meta.resolver or nil,
            error=not ok and tostring(cash_err or rp_err) or nil,
            source="current Enhanced freemode daily-objective reward path + tuneables_processing.c",
        }
    end
    return items, available
end

local function read_daily_objective_milestones()
    local items,available={},0
    for _,descriptor in ipairs(DAILY_OBJECTIVE_MILESTONES) do
        local cash,cash_err,cash_meta=semantic_tunable_int({name=descriptor.cash.name,offset=descriptor.cash.offset,minimum=0,maximum=100000000})
        local rp,rp_err,rp_meta=semantic_tunable_int({name=descriptor.rp.name,offset=descriptor.rp.offset,minimum=0,maximum=100000000})
        local ok=cash~=nil and rp~=nil; if ok then available=available+1 end
        items[#items+1]={key=descriptor.key,label=descriptor.label,transaction_label=descriptor.transaction_label,cash=cash,rp=rp,available=ok,
            cash_name=descriptor.cash.name,rp_name=descriptor.rp.name,source_discrepancy=descriptor.source_discrepancy==true,note=descriptor.note,
            cash_resolver=cash_meta and cash_meta.resolver or nil,rp_resolver=rp_meta and rp_meta.resolver or nil,
            error=not ok and tostring(cash_err or rp_err) or nil,source="current Enhanced freemode.c func_21327 + tuneables_processing.c"}
    end
    return items,available
end

local function refresh()
    local core = economy()
    if not core then return false, "Economy stat service is unavailable." end
    local slot, slot_err = core.CurrentSlot()
    if slot == nil then return false, slot_err end
    local items, available = {}, 0
    for _, family in ipairs(FAMILIES) do
        local value, err = core.ReadStat(core.QualifyStat(slot, family.stat))
        local index = value ~= nil and (math.floor(value) - family.base + 1) or nil
        local mission = index and family.missions[index] or nil
        if value ~= nil then available = available + 1 end
        items[#items + 1] = {
            key = family.key, label = family.label, stat = family.stat, raw = value,
            current = mission or (value ~= nil and "No mapped mission" or "Unavailable"),
            progress = index and math.max(0, math.min(#family.missions, index)) or 0,
            total = #family.missions, available = value ~= nil, error = value == nil and tostring(err) or nil,
            confidence = "REFERENCE_CORROBORATED_READ_ONLY",
        }
    end
    local signals, signal_available = {}, 0
    for _, descriptor in ipairs(SOURCE_SIGNALS) do
        local value, err = core.ReadStat(core.QualifyStat(slot, descriptor.stat))
        if value ~= nil then signal_available = signal_available + 1 end
        signals[#signals + 1] = {
            key = descriptor.key, label = descriptor.label, stat = descriptor.stat,
            raw = value, available = value ~= nil, error = value == nil and tostring(err) or nil,
            confidence = "CURRENT_ENHANCED_SOURCE_READ_ONLY",
        }
    end
