    local services, service_available = read_service_tunables()
    local rewards, reward_available = read_daily_objective_rewards()
    local milestones, milestone_available = read_daily_objective_milestones()
    State.signals, State.signal_available = signals, signal_available
    State.work_cooldowns, State.work_cooldown_available = work, work_available
    State.service_tunables, State.service_tunable_available = services, service_available
    State.daily_rewards, State.daily_reward_available = rewards, reward_available
    State.daily_milestones, State.daily_milestone_available = milestones, milestone_available
    State.items, State.character_slot, State.refreshed_at = items, slot, os and os.time and os.time() or 0
    local total_available = available + signal_available + work_available + service_available + reward_available + milestone_available
    State.status = total_available > 0 and "READ_ONLY" or "UNAVAILABLE"
    return total_available > 0, total_available > 0 and "Mission, service and challenge intelligence refreshed."
        or "Mission/service intelligence is unavailable on this build."
end

local function snapshot()
    return {
        status = State.status or "PENDING", items = State.items or {}, signals = State.signals or {},
        signal_available = State.signal_available or 0,
        work_cooldowns = State.work_cooldowns or {}, work_cooldown_available = State.work_cooldown_available or 0,
        service_tunables = State.service_tunables or {}, service_tunable_available = State.service_tunable_available or 0,
        daily_rewards = State.daily_rewards or {}, daily_reward_available = State.daily_reward_available or 0,
        daily_milestones = State.daily_milestones or {}, daily_milestone_available = State.daily_milestone_available or 0,
        character_slot = State.character_slot, refreshed_at = State.refreshed_at,
        source_revision = "GTA Online Enhanced 1.73 / 1158.13 consolidated source corpus + Source 08",
        mutation_support = "TEMPORARY_TUNABLE_OVERRIDES",
        tunable_overrides = override_snapshot(),
        reason = "Mission and progression stats remain read-only. Temporary tunable overrides require matching source mappings, verified writes and conflict-aware restoration on unload.",
        milestone_note = "The second milestone is named for 20 objectives but uses the payment label 25 Complete. Milestone and payout state remain read-only.",
    }
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table" or type(context.CScript) ~= "table"
        or type(context.CScript.Economy) ~= "table" then
