        TunableOverrideCatalog = TUNABLE_OVERRIDE_CATALOG, TunableOverrideProfiles = TUNABLE_OVERRIDE_PROFILES,
        ApplyTunableProfile = apply_override_profile, RestoreTunableProfile = restore_override_profile,
        RestoreAllTunableOverrides = function() return restore_override_profile("all", false) end,
