        -- An allocator can recycle the same address for the same model.
        -- Require the original handle too; resolve only tracked candidates.
        if d.PointerToHandle(entity)~=record.handle then return false end
        local object = entity.NetObject
        if object==nil then return record.networked==false end
        return object.IsRemote==false and object.PlayerId==player_id
    end
    local function decide(entity_a, entity_b)
        if not active or d.Running()~=true or d.Enabled()~=true then return true end
        local player_id = d.GetLocalPlayerId()
        if type(player_id)~="number" or player_id%1~=0 or player_id<0 or player_id>31 then return true end
        local address_a, model_a = identity(entity_a)
        local address_b, model_b = identity(entity_b)
        if not address_a or not address_b or address_a==address_b then return true end
        local a = actor(entity_a,address_a,model_a,player_id)
        local b = actor(entity_b,address_b,model_b,player_id)
        if not a and not b then return true end
        if a and b then return false end
        local address, model = a and address_b or address_a, a and model_b or model_a
        if same_local(d.GetLocalPed(),address,model) then return false end
        return not same_local(d.GetLocalVehicle(),address,model)
    end
    function api.Track(record)
        if type(record)~="table" or not integer(record.address) or not integer(record.handle)
            or type(record.model)~="number" or record.model~=record.model
            or math.abs(record.model)==math.huge or record.model%1~=0
            or type(record.networked)~="boolean" then return false end
