            return wait_for("Waiting for a matching interior after respawn")
        end
        if interior~=0 and not read("bool",H.ready,interior) then
            return wait_for("Waiting for interior to load")
        end
        local proof={ped=lp,target=target,mover=mover,vehicle=vehicle,car=car,passenger=passenger,interior=interior,
            shared=vehicle>0 and read("int",H.vehicle,target.handle,false)==vehicle}
        if s.proof then
            if not same(proof.target,s.proof.target) then
                return wait_for("Selected player's character changed during teleport")
            end
            assert(same(proof.ped,s.proof.ped)
                and same(proof.mover,s.proof.mover) and proof.vehicle==s.proof.vehicle
                and proof.interior==s.proof.interior and proof.passenger==s.proof.passenger
                and (not proof.car or same(proof.car,s.proof.car)),"Local vehicle or interior changed")
        else s.proof=proof end
        return proof
    end
    local function write_current(token,proof)
        local pid,identity,session,owner=s.pid,s.identity,s.session,s.owner
        assert(s.active and s.generation==token and d.Running()==true and d.Session()==session,"Teleport owner changed")
        -- Connection getters can call host code. Complete them before the final
        -- native ownership and allocation observations, not after those proofs.
        local connection=d.Identity(pid)
        assert(s.generation==token and same_connection(identity,connection),"Connection changed before teleport")
        if read("int",H.player_ped,pid)~=proof.target.handle then
            return wait_for("Selected player respawned during teleport")
        end
        assert(d.LocalPed()==proof.ped.handle,"Local player changed")
        if proof.vehicle>0 and read("int",H.vehicle,proof.target.handle,false)==proof.vehicle then
            s.status,s.detail="ACTIVE","Already travelling in the same vehicle";return false
        end
        for _,record in ipairs({proof.ped,proof.target,proof.mover})do
            if record==proof.target and (not read("bool",H.exists,record.handle)
                or read("bool",H.dead,record.handle,false)) then
                return wait_for("Selected player died or is respawning")
            end
            assert(read("bool",H.exists,record.handle) and not read("bool",H.dead,record.handle,false)
                and read("int",H.model,record.handle)==record.model,"Entity changed before teleport")
        end
        if proof.vehicle>0 then
            local driver=read("int",H.driver,proof.vehicle,-1,false)
            assert((proof.passenger and driver~=proof.ped.handle) or
                (not proof.passenger and driver==proof.ped.handle),"Seat changed before local action")
            assert(same(proof.car,entity(proof.vehicle,H.vehicle_kind)),"Occupied vehicle allocation changed")
        end
        assert(not read("bool",H.networked,proof.mover.handle) or read("bool",H.control,proof.mover.handle),
            "Local entity control changed before teleport")
        if d.Available then
            local ready,reason=d.Available()
            assert(s.generation==token and s.active,"Teleport owner changed during availability check")
            if ready~=true then s.status,s.detail="WAITING",reason or "Waiting for the current local trip";return false end
        end
        -- Availability may call host code. Recheck occupancy after it, then
        -- keep allocation evidence after every native observation.
        local vehicle=current_vehicle(proof.ped.handle)
        if vehicle==nil then return false end
        if vehicle~=proof.vehicle then return wait_for("Waiting for local vehicle transition") end
        if vehicle>0 and (read("int",H.driver,vehicle,-1,false)~=proof.ped.handle)~=proof.passenger then
            return wait_for("Waiting for local seat transition")
        end
        for _,record in ipairs({proof.ped,proof.target,proof.mover,proof.car})do
            assert(d.Address(record.handle)==record.address,"Entity allocation changed before teleport")
        end
        -- Only cached Lua scope comparisons follow the final host observations.
        assert(s.active and s.generation==token and s.pid==pid and s.identity==identity
            and s.owner==owner and s.session==session and d.Session()==session and d.Running()==true,
            "Teleport owner changed at write fence")
        return true
    end
    function api.Tick(now)
        if ticking or not api.Prune() then return false end
        ticking=true
        local token=s.generation
        local ok,err=pcall(function()
            assert(finite(now) and now>=0,"Teleport clock unavailable")
            if d.Available then
                local ready,reason=d.Available()
                if ready~=true then s.status,s.detail="WAITING",reason or "Waiting for the current local trip";return end
            end
            if now<s.due then return end
            if s.pid==d.LocalPlayer() then
                s.status,s.detail="ACTIVE","Following yourself"
                s.due=now+250 -- no self-teleport or negative Z offset
                return
            end
            local frame=read("int",H.frame)
            if frame==s.last_frame then return end
            s.last_frame,s.due=frame,now+10
            -- Proofs fence ONE native turn, not the entire enabled lifetime.
            -- Legitimate vehicle/seat changes between frames get fresh evidence.
            s.proof=nil
            local proof=capture(token)
            if not proof then return end
            if proof.shared then s.exit=nil;s.status,s.detail="ACTIVE","Already travelling in the same vehicle";return end
            if proof.passenger then
                local exit=s.exit
                if not exit or exit.vehicle~=proof.vehicle or exit.car_address~=proof.car.address
                    or exit.ped_address~=proof.ped.address then
                    exit={vehicle=proof.vehicle,car_address=proof.car.address,ped_address=proof.ped.address,
                        attempts=0,due=now}
                    s.exit=exit
                end
                s.status="WAITING"
                s.detail=exit.failed and "Passenger exit request failed; waiting before retry"
                    or "Leaving passenger seat, then teleporting on foot"
                if now<exit.due then return end
                if exit.attempts>=3 then
                    s.detail=exit.failed and "Passenger exit request failed; leave the vehicle to resume Auto-tp"
                        or "Waiting for passenger exit; leave the vehicle to resume Auto-tp"
                    return
                end
                if not write_current(token,proof) then return end
                -- Keep the fast local warp, then allow a normal exit fallback
                -- to complete before one last warp. Accepted is not completed.
                local flags=exit.attempts==1 and 0 or 16
                -- Count every attempted submission, including rejected/throwing
                -- natives, before entering host code. A retired run stays retired.
                exit.attempts=exit.attempts+1
                exit.due=now+(flags==0 and 4000 or 1500)
                local called,accepted,result=pcall(d.Try,"void",H.leave,proof.ped.handle,proof.vehicle,flags)
                if s.generation~=token or s.exit~=exit or not s.active then return end
                exit.failed=not called or accepted~=true or result==false
                s.detail=exit.failed and "Passenger exit request failed; waiting before retry"
                    or "Leaving passenger seat, then teleporting on foot"
                -- Never teleport in the exit turn; confirm an empty seat next frame.
                return
            end
            s.exit=nil
            local destination=vector(H.offset,proof.target.handle,0.0,0.0,-0.5)
            -- Request destination collision without requiring it to have loaded before movement.
            local accepted,result=d.Try("void",H.request,destination.x,destination.y,destination.z)
            assert(accepted and result~=false,"Destination collision request failed")
            if d.Available then
                local ready,reason=d.Available()
                if ready~=true then s.status,s.detail="WAITING",reason or "Waiting for the current local trip";return end
            end
            proof=capture(token)
            if not proof then return end
            if d.Available then
                local ready,reason=d.Available()
                if ready~=true then s.status,s.detail="WAITING",reason or "Waiting for the current local trip";return end
            end
            if proof.shared then s.status,s.detail="ACTIVE","Already travelling in the same vehicle";return end
            if not write_current(token,proof)then return end
            accepted,result=d.Try("void",H.move,proof.mover.handle,destination.x,destination.y,destination.z,false,false,false)
            assert(accepted and result~=false,"GTA rejected the local teleport request")
            s.requests=s.requests+1;s.status,s.detail="ACTIVE","Local teleport requests every 10 ms, limited to one per frame"
        end)
        ticking=false
        if not ok then
            if s.generation==token then api.Cancel(tostring(err):gsub("^.-:%d+: ",""))end
            return false
        end
        return true
    end
    function api.Snapshot()
        return {active=s.active==true,status=s.status,detail=s.detail,player_id=s.pid or s.last_pid}
    end
    return api
end
-- END LOCAL_AUTO_TP

-- Only reversible ped flags are borrowed. Prop snapshots belong to one ped.
function Module.NewHeadgearController(host)
    local api, lease, due, last_wanted = {}, nil, 0, false
    local desired = { [36] = true, [228] = false, [258] = false, [380] = true }
    local function restore()
        if not lease then return true end
        local state = host.Current(lease.proof)
        if state == 'retired' then
            lease = nil; return true
        end
        if state ~= 'current' then return false end
        for flag, entry in pairs(lease.flags) do
            local value = host.ReadFlag(lease.proof, flag)
            if type(value) == 'boolean' then
                if value == entry.before or value ~= entry.last then
                    lease.flags[flag] = nil
                else
                    host.WriteFlag(lease.proof, flag, entry.before)
                    local after = host.ReadFlag(lease.proof, flag)
                    if after == entry.before or type(after) == 'boolean' and after ~= entry.last then lease.flags[flag] = nil end
                end
            end
        end
        if next(lease.flags) == nil then
            lease = nil; return true
        end
        return false
    end
    function api.Tick(now, wanted)
        if not wanted then
            if last_wanted then due = 0 end
            last_wanted = false
            if not lease then return true end
            if now < due then return false end
            due = now + 250
            return restore()
        end
        last_wanted = true
        if now < due then return false end; due = now + 200
        local proof = host.Capture()
        if not proof then return false end
        if lease and (lease.proof.handle ~= proof.handle or host.Current(lease.proof) ~= 'current') then
            if not restore() then return false end
        end
        if not lease then
            lease = { proof = proof, flags = {}, props = host.ReadProps(proof), model = proof.headgear_model }
        elseif proof.headgear_model ~= lease.model then
            lease.props = host.ReadProps(proof); lease.model = proof.headgear_model
        end
        if host.Current(lease.proof) ~= 'current' then return false end
        for flag, value in pairs(desired) do
            local before = host.ReadFlag(lease.proof, flag)
            if type(before) == 'boolean' and before ~= value then
                lease.flags[flag] = lease.flags[flag] or { before = before, last = value }
                if flag == 228 then host.LoseProps(lease.proof, false) else host.WriteFlag(lease.proof, flag, value) end
            end
        end
        local props = host.ReadProps(lease.proof)
        local event = host.Event(lease.proof, now)
        if props then
            for index, prop in ipairs(props) do
                local before = lease.props and lease.props[index]
                if before and before.drawable >= 0 and prop.drawable == -1 and event then
                    host.WriteProp(lease.proof, index, before)
                else
                    -- Nonempty replacements and deliberate removals become the
                    -- new outfit. Never reapply a prior costume every frame.
                    lease.props = lease.props or {}; lease.props[index] = prop
                end
            end
        end
        return true
    end

    function api.Clean() return lease == nil end

    return api
end

