-- Friendly effects keep connection-scoped intent separate from gameplay work.
function Module.NewFriendlyController(host)
    local api, rows, interest, debt, retiring = {}, {}, {}, {}, {}
    local halted, next_identity = false, 0
    local keys = { off_the_radar = true, remote_auto_repair = true, remote_horn_boost = true, remote_speed = true, remote_top_speed = true, bodyguards = true, vehicle_gun = true }
    local defaults = {
        model = "s_m_y_blackops_01",
        count = 2,
        weapon = "WEAPON_CARBINERIFLE",
        godmode = false,
        targeting =
        "defend_both",
        speed = 1.5,
        top_speed = 1.5
    }
    local function copy(t)
        local r = {}; for k, v in pairs(t or {}) do r[k] = v end; return r
    end
    local function queue_owned(r, kind)
        local keep = {}
        for _, a in ipairs(r.actors) do if not kind or a.kind == kind then debt[#debt + 1] = a else keep[#keep + 1] = a end end
        r.actors = keep
    end
    local function off(r, key, keep_toggle)
        r.flags[key] = nil
        if key == 'bodyguards' then
            queue_owned(r, 'guard'); r.guard_births = 0; r.guard_phase_done = nil; r.guard_phase_started = nil
        elseif key == 'vehicle_gun' then
            queue_owned(r, 'gun')
        end
        if not keep_toggle then host.Reset(key, r.pid) end
    end
    local function retire(r, keep_toggle)
        for key in pairs(copy(r.flags)) do off(r, key, keep_toggle) end
        queue_owned(r)
        r.retired = true; r.pending = nil
    end
    function api.Settings(pid)
        if type(pid) ~= 'number' or pid % 1 ~= 0 or pid < 0 or pid > 31 then return { status = 'Select a player', flags = {} } end
        interest[pid] = true
        local r = rows[pid]
        local result = copy(r and not r.retired and r.settings or defaults)
        result.key = r and not r.retired and r.key or nil
        result.status = r and r.status or 'Waiting for player'
        result.flags = copy(r and r.flags)
        result.bodyguards_enabled = result.flags.bodyguards == true
        result.config_result = r and r.config_result and copy(r.config_result) or nil
        result.owned = r and #r.actors or 0; result.cleanup_pending = #debt
        return result
    end

    function api.Configure(pid, patch, expected)
        local r = rows[pid]
        if halted or not r or r.retired or expected ~= r.key then return false, 'The selected player connection changed.' end
        if type(patch) ~= 'table' then return false, 'Invalid friendly settings.' end
        local candidate = copy(r.settings)
        for key, value in pairs(patch) do
            if defaults[key] == nil then return false, 'Unknown friendly setting.' end
            if key == 'model' or key == 'weapon' then
                if type(value) ~= 'string' or #value < 1 or #value > 64 or not value:match('^[%w_]+$') then
                    return false,
                        'Enter a model or weapon name.'
                end
            elseif key == 'count' then
                if type(value) ~= 'number' or value % 1 ~= 0 or value < 1 or value > 20 then
                    return false,
                        'Bodyguard count must be 1 to 20.'
                end
            elseif key == 'godmode' then
                if type(value) ~= 'boolean' then return false, 'Invalid bodyguard godmode setting.' end
            elseif key == 'targeting' then
                if value ~= 'defend_players' and value ~= 'defend_npcs' and value ~= 'defend_both' and value ~= 'attack_all' then
                    return
                        false, 'Invalid bodyguard targeting.'
                end
            elseif type(value) ~= 'number' or value ~= value or value < 1 or value > 5 then
                return false, 'Multiplier must be between 1 and 5.'
            end
            candidate[key] = value
        end
        r.pending = { key = expected, settings = candidate }; r.status = 'Settings queued'
        return true
    end

    function api.Set(pid, key, wanted)
        if not keys[key] or type(wanted) ~= 'boolean' then return false, 'Invalid friendly action.' end
        local r = rows[pid]
        if halted then return false, 'Friendly actions are stopped.' end
        if type(pid) ~= 'number' or pid % 1 ~= 0 or pid < 0 or pid > 31 then return false, 'Select a player.' end
        interest[pid] = true
        if not wanted and (not r or r.retired) then return true end
        if not r or r.retired then
            local pin, identity = host.Pin(pid)
            if not pin or not identity then return false, 'Wait for the selected player connection.' end
            if r then retiring[#retiring + 1] = r end
            r = {
                pid = pid,
                pin = pin,
                key = identity,
                settings = copy(defaults),
                flags = {},
                actors = {},
                status =
                'Ready'
            }
            rows[pid] = r
        elseif wanted and host.Current(r.pin) ~= true then
            return false, 'The selected player connection changed.'
        end
        if not wanted then
            off(r, key); return true
        end
        if key == 'bodyguards' and not r.flags[key] then
            r.guard_births = 0; r.guard_phase_done = nil; r.guard_phase_started = nil
        end
        r.flags[key] = true; r.status = 'Enabled; gameplay verification pending'
        return true
    end

    function api.Tick(now)
        local created, owned_total = false, #debt
        for _, r in pairs(rows) do owned_total = owned_total + #r.actors end
        if now >= next_identity then
            next_identity = now + 250
            for pid in pairs(interest) do
                local pin, key = host.Pin(pid)
                local old = rows[pid]
                if pin and key and (not old or old.retired or old.key ~= key) then
                    local same_connection = old and not old.retired
                        and old.pin.identity.rid == pin.identity.rid
                        and old.pin.identity.cxn == pin.identity.cxn
                        and old.pin.local_identity.rid == pin.local_identity.rid
                        and old.pin.local_identity.cxn == pin.local_identity.cxn
                    local retained_flags = same_connection and copy(old.flags) or {}
                    local retained_settings = same_connection and copy(old.settings) or copy(defaults)
                    if old then
                        -- Dispose the old ped's actors/leases, but keep menu
                        -- intent ON for this exact same selected connection.
                        if not old.retired then retire(old, same_connection == true) end
                        retiring[#retiring + 1] = old
                    end
                    rows[pid] = {
                        pid = pid, pin = pin, key = key,
                        settings = retained_settings,
                        flags = retained_flags,
                        actors = {},
                        status = same_connection and 'Recovered after character change' or 'Ready'
                    }
                elseif old and not old.retired and host.Current(old.pin) == false then
                    if host.ConnectionSame and host.ConnectionSame(old.pin) == true then
                        old.status = 'Waiting for character to stream in'
                    else
                        retire(old)
                    end
                end
            end
        end
        local work = {}
        for _, r in pairs(rows) do work[#work + 1] = r end
        for _, r in ipairs(retiring) do work[#work + 1] = r end
        for _, r in ipairs(work) do
            if host.ReleaseModels then host.ReleaseModels(r, r.retired or halted) end
            local current = not r.retired and host.Current(r.pin)
            if current == false and not r.retired
                and (not host.ConnectionSame or host.ConnectionSame(r.pin) ~= true) then
                retire(r)
            end
            if r.radar and (r.retired or not r.flags.off_the_radar) then
                if host.RadarRelease(r.pin, r.radar) then r.radar = nil end
            end
            if r.top and (r.retired or not r.flags.remote_top_speed or current ~= true) then
                if host.TopRestore(r.top) then r.top = nil end
            end
            if current == true and not halted then
                if r.flags.off_the_radar and not r.radar then
                    local provider, why = host.RadarBorrow(r.pin)
                    if provider then
                        r.radar = provider
                        if provider.applied == false then
                            off(r, 'off_the_radar'); r.status = 'Off The Radar provider failed'; if host.Notice then
                                host
                                    .Notice(r.pid, 'Off The Radar could not be enabled.')
                            end
                        else
                            r.status = 'Off The Radar requested; peer visibility unverified'
                        end
                    else
                        off(r, 'off_the_radar'); r.status = why or 'Remote Off The Radar unavailable'; if host.Notice then
                            host.Notice(r.pid, 'Off The Radar unavailable.')
                        end
                    end
                end
                if r.pending then
                    if r.pending.key == r.key then
                        local ok, why = host.Validate(r.pending.settings)
                        if ok then
                            local before = r.settings; r.settings = r.pending.settings
                            if before.model ~= r.settings.model or before.count ~= r.settings.count then
                                queue_owned(r, 'guard'); r.guard_births = 0; r.guard_phase_done = nil; r.guard_phase_started = nil
                            elseif before.weapon ~= r.settings.weapon or before.godmode ~= r.settings.godmode or before.targeting ~= r.settings.targeting then
                                r.guard_settings_revision = (r.guard_settings_revision or 0) + 1
                                r.next_threat = 0; r.enemy = nil
                                for _, actor in ipairs(r.actors) do if actor.kind == 'guard' then actor.next_task = 0 end end
                            end
                            r.status = 'Settings accepted; bodyguard refresh queued'
                        else
                            r.status = why or 'Settings unavailable'
                        end
                        r.config_result = {
                            ok = ok == true,
                            message = ok and 'Settings applied.' or why or
                                'Settings unavailable.'
                        }
                        if not ok and host.Notice then host.Notice(r.pid, r.config_result.message) end
                    end
                    r.pending = nil
                end
                if (r.flags.remote_auto_repair or r.flags.remote_horn_boost
                    or r.flags.remote_speed or r.flags.remote_top_speed)
                    and now>=(r.next_vehicle_probe or 0)then
                    r.status=host.Vehicle(r,now)or r.status
                    -- No authority is not a toggle failure. Poll at 350 ms
                    -- until conditions change, then resume normal 125 ms.
                    r.next_vehicle_probe=now+((r.status or ""):find("Waiting",1,true)
                        and 350 or 125)
                end
                if r.flags.bodyguards and not created then
                    r.guard_phase_started = r.guard_phase_started or now
                    if not r.guard_phase_done and now - r.guard_phase_started >= 15000 then
                        r.guard_phase_done = true; r.status = 'Some bodyguards could not be created'
                        if host.Notice then host.Notice(r.pid, 'Some bodyguards could not be created.') end
                    end
                    local count = 0; for _, a in ipairs(r.actors) do if a.kind == 'guard' then count = count + 1 end end
                    if not r.guard_phase_done and count < r.settings.count and (r.guard_births or 0) < r.settings.count and owned_total < 64 and now >= (r.next_birth or 0) then
                        r.next_birth = now + 75
                        local actor, why, terminal = host.Spawn(r, 'guard', count + 1, now)
                        if actor then
                            actor.kind = 'guard'; r.guard_births = (r.guard_births or 0) + 1; if r.guard_births >= r.settings.count then r.guard_phase_done = true end; r.actors[#r.actors + 1] =
                                actor; created = true; owned_total = owned_total + 1
                        elseif why then
                            r.status = why; if terminal then
                                off(r, 'bodyguards'); if host.Notice then host.Notice(r.pid, why) end
                            end
                        end
                    end
                end
                local gun_pending = false; for _, a in ipairs(r.actors) do
                    if a.kind == 'gun' and a.initializing then
                        gun_pending = true; break
                    end
                end
                if r.flags.vehicle_gun and not gun_pending and not created and now >= (r.next_shot or 0) and owned_total < 64 then
                    if host.Firing(r.pin) then
                        r.next_shot = now + 250
                        local actor, why, terminal = host.Spawn(r, 'gun', 1, now)
                        if actor then
                            actor.kind = 'gun'; actor.expires = actor.expires or now + 10000; r.actors[#r.actors + 1] =
                                actor; created = true; owned_total = owned_total + 1
                        elseif why then
                            r.status = why; if terminal then
                                off(r, 'vehicle_gun'); if host.Notice then host.Notice(r.pid, why) end
                            end
                        end
                    end
                end
                if host.Advance then
                    for _, a in ipairs(r.actors) do host.Advance(r, a, now) end
                end
                local has_guards = false
                if r.flags.bodyguards then
                    for _, a in ipairs(r.actors) do
                        if a.kind == 'guard' and not a.expires then
                            has_guards = true; break
                        end
                    end
                end
                if has_guards and now >= (r.next_guard or 0) then
                    r.next_guard = now + 500; host.Guards(r, now)
                end
            end
            local keep = {}
            for _, actor in ipairs(r.actors) do
                local birth_pending = actor.kind == 'guard' and r.flags.bodyguards and not r.guard_phase_done
                if actor.expires and now >= actor.expires and not birth_pending then
                    debt[#debt + 1] = actor
                else
                    keep[#keep + 1] =
                        actor
                end
            end
            r.actors = keep
        end
        local pending = {}
        for _, r in ipairs(retiring) do
            if r.radar or r.top or r.model_requests and next(r.model_requests) then pending[#pending + 1] = r end
        end
        retiring = pending
        for _ = 1, math.min(2, #debt) do
            local a = table.remove(debt, 1)
            if host.Delete(a, now) ~= true then debt[#debt + 1] = a end
        end
    end

    function api.Stop()
        halted = true
        for _, r in pairs(rows) do if not r.retired then retire(r) end end
    end

    function api.Requested()
        if #debt > 0 or #retiring > 0 then return true end
        for pid in pairs(interest) do if not rows[pid] or rows[pid].retired then return true end end
        for _, r in pairs(rows) do
            if r.pending or r.radar or r.top or #r.actors > 0 or next(r.flags) or r.model_requests and next(r.model_requests) then return true end
        end
        return false
    end

    function api.Clean()
        if #debt > 0 or #retiring > 0 then return false end
        for _, r in pairs(rows) do if r.radar or r.top or #r.actors > 0 or r.model_requests and next(r.model_requests) then return false end end
        return true
    end

    return api
end

-- BEGIN REMOTE GUARD44 CONTROLLER
-- One explicitly selected connection/current character at a time. Requests are
-- intent only; the gameplay tick owns native mutation and restoration.
local function new_remote_guard44(host)
    local api, intent, lease = {}, nil, nil
    local revision, busy, stopped, due = 0, false, false, -100000
    local phase, message, authority = "IDLE", "Off", nil
    local authority_detail, authority_wait_ms = {}, 0
    local function copied_control_detail(value)
        local copy = {}
        for _, key in ipairs({ "requests", "owner", "pending_owner", "checked_ms", "observed",
            "entity_request", "entity_request_accepted", "network_id_request", "network_id_request_accepted", "give_control" }) do
            local item
            if type(value) == "table" then item = value[key] end
            if type(item) == "number" or type(item) == "boolean" then copy[key] = item end
        end
        return copy
    end
    local scalar_order = { "invincible", "damageable", "critical" }
    local desired = { invincible = true, damageable = false, critical = true }
    local function call(name, ...)
        local fn = host[name]
        if type(fn) ~= "function" then return nil end
        local ok, value = pcall(fn, ...)
        if ok then return value end
    end
    local function status(next_phase, detail)
        local changed = phase ~= next_phase or message ~= detail
        phase, message = next_phase, detail
        if changed then call("Report", phase, message, intent and intent.pid) end
    end
    local function count_owned()
        if not lease then return 0 end
        local count = 0
        for _ in pairs(lease.scalars) do count = count + 1 end
        for _ in pairs(lease.proofs) do count = count + 1 end
        return count
    end
    local function flags(value)
        if type(value) ~= "table" then return nil end
        local copy = {}
        for index = 1, 8 do
            if type(value[index]) ~= "boolean" then return nil end
            copy[index] = value[index]
        end
        return copy
    end
    local function enabled(row, token)
        return intent == row and row and row.enabled == true
            and revision == token and not stopped
    end
    local function cancel(reason, latch)
        revision = revision + 1
        if intent then
            intent.enabled = false
            intent.latched = latch == true
            intent.reason = reason
            intent.terminal_phase = nil
        end
        authority = nil
        status(count_owned() > 0 and "RESTORE_PENDING" or "STOPPED", reason or "Off")
    end
    local function lease_current(owned)
        return lease == owned and owned and call("EntityState", owned.entity) == "current"
    end
    local function control(owned, request, fence)
        if not lease_current(owned) or fence and not fence() then return false end
        local value = call("Control", owned.entity, request == true, fence)
        authority_detail = copied_control_detail(call("ControlState", owned.entity))
        return value == true and lease_current(owned) and (not fence or fence())
    end
    local function write(owned, field, value, expected, fence)
        if owned.inflight or not lease_current(owned) or fence and not fence() then return false end
        owned.inflight = true
        -- Ownership is armed by the caller before this host boundary. A failed
        -- setter may already have mutated; only fresh reads settle its debt.
        local result = call("Write", owned.entity, field, value, expected, fence)
        owned.inflight = false
        return result == true
    end
    local function settle_scalars(owned)
        for _, field in ipairs(scalar_order) do
            local entry = owned.scalars[field]
            if entry then
                local value = call("Read", owned.entity, field)
                if type(value) == "boolean" and (value == entry.before or value ~= entry.last) then
                    owned.scalars[field] = nil
                end
            end
        end
    end
    local function settle_proofs(owned, values)
        values = flags(values)
        if not values then return end
        for index, entry in pairs(owned.proofs) do
            if values[index] == entry.before or values[index] ~= entry.last then
                owned.proofs[index] = nil
            end
        end
    end
    local function restore()
        local owned = lease
        if not owned then return true end
        if owned.inflight then return false end
        local state = call("EntityState", owned.entity)
        if state == "retired" then
            lease = nil; return true
        end
        if state ~= "current" then return false end
        -- Read/compare even without authority, but never interpret an unknown
        -- read or a failed identity probe as a completed restore.
        settle_scalars(owned)
        settle_proofs(owned, call("Read", owned.entity, "proofs"))
        if count_owned() == 0 then
            lease = nil; return true
        end
        local token = revision
        local function fence() return lease == owned and revision == token end
        if not control(owned, true, fence) then return false end
        for _, field in ipairs(scalar_order) do
            if not fence() then return false end
            local entry = owned.scalars[field]
            if entry then
                local current = call("Read", owned.entity, field)
                if type(current) == "boolean" and fence() then
                    if current == entry.before or current ~= entry.last then
                        owned.scalars[field] = nil
                    elseif control(owned, false, fence) then
                        write(owned, field, entry.before, current, fence)
                        if not fence() then return false end
                        local after = call("Read", owned.entity, field)
                        if type(after) == "boolean" and fence() and (after == entry.before or after ~= entry.last) then
                            owned.scalars[field] = nil
                        end
                    end
                end
            end
        end
        if not fence() then return false end
        local current = flags(call("Read", owned.entity, "proofs"))
        if current and fence() then
            settle_proofs(owned, current)
            local wanted, changed = flags(current), false
            for index, entry in pairs(owned.proofs) do
                wanted[index] = entry.before; changed = true
            end
            if changed and control(owned, false, fence) then
                write(owned, "proofs", wanted, current, fence)
                if not fence() then return false end
                settle_proofs(owned, call("Read", owned.entity, "proofs"))
            end
        end
        if not fence() then return false end
        if count_owned() == 0 then
            lease = nil; return true
        end
        return false
    end
    local function wait_for_authority(row, now)
        authority = false
        row.authority_since = row.authority_since or now
        authority_wait_ms = math.max(0, now - row.authority_since)
        if now < row.authority_since or authority_wait_ms >= 4000 then
            local pending = count_owned() > 0
            local reason = pending
                and "No network control for 4 seconds; protection stopped. Restoration pending."
                or "Network control was not granted within 4 seconds; remote protection was not enabled."
            cancel(reason, false)
            if not pending then
                lease = nil
                row.terminal_phase = "NO_AUTHORITY"
                status("NO_AUTHORITY", reason)
            else
                status("RESTORE_PENDING", reason)
            end
            return false
        end
        status("PENDING_AUTHORITY",
            ("Requesting control (%d / 4 s)."):format(math.min(3, math.floor(authority_wait_ms / 1000))))
        return false
    end
    local function wait_for_readback(row, now)
        row.readback_since = row.readback_since or now
        if now < row.readback_since or now - row.readback_since >= 4000 then
            local pending = count_owned() > 0
            local reason = pending
                and "Protection could not be verified within 4 seconds; stopped. Restoration pending."
                or "Protection could not be verified within 4 seconds; stopped."
            cancel(reason, false)
            row.terminal_phase = "PROTECTION_UNVERIFIED"
            if not pending then lease = nil end
            status(pending and "RESTORE_PENDING" or "PROTECTION_UNVERIFIED", reason)
            return false
        end
        status("READBACK_PENDING", "Protection has not been fully verified.")
        return false
    end
    local function step(now, allow)
        if not intent or not intent.enabled or stopped or allow == false then
            if allow == false and intent and intent.enabled then cancel("Protection stopped; restoration pending.", true) end
            local clean = restore()
            if clean then
                status(intent and intent.terminal_phase or "IDLE", intent and intent.reason or "Off")
            else
                status("RESTORE_PENDING", "Restoration pending.")
            end
            return clean
        end
        local row, token = intent, revision
        local function fence() return enabled(row, token) end
        local function interrupted()
            authority = nil
            if fence() then status("IDENTITY_PENDING", "Waiting for the same player and character.") end
            return false
        end
        local state = call("TargetState", row.pin, lease and lease.entity)
        if not fence() then return interrupted() end
        if state == "retired" then
            cancel("Player or character changed; enable again.", true)
            return restore()
        end
        if state ~= "current" then
            authority = nil; status("IDENTITY_PENDING", "Waiting for the same player and character."); return false
        end
        if not lease then
            local entity = call("Capture", row.pin, fence)
            if not fence() then return interrupted() end
            if not entity then
                status("READBACK_PENDING", "Protection state is unavailable."); return false
            end
            lease = { entity = entity, scalars = {}, proofs = {} }
        end
        local owned = lease
        local function apply_fence()
            return fence() and lease == owned
                and call("TargetState", row.pin, owned.entity) == "current" and fence()
        end
        authority = control(owned, true, apply_fence)
        if not apply_fence() then return interrupted() end
        if not authority then return wait_for_authority(row, now) end
        local verified = true
        for _, field in ipairs(scalar_order) do
            if not apply_fence() then return interrupted() end
            local current = call("Read", owned.entity, field)
            if not apply_fence() then return interrupted() end
            if type(current) ~= "boolean" then
                verified = false
            else
                local entry = owned.scalars[field]
                if entry and current ~= entry.last then owned.scalars[field] = nil end
                if current ~= desired[field] then
                    if not control(owned, false, apply_fence) then
                        if not apply_fence() then return interrupted() end
                        return wait_for_authority(row, now)
                    end
                    owned.scalars[field] = owned.scalars[field] or { before = current, last = desired[field] }
                    write(owned, field, desired[field], current, apply_fence)
                end
                if not apply_fence() then return interrupted() end
                if call("Read", owned.entity, field) ~= desired[field] then verified = false end
            end
        end
        if not apply_fence() then return interrupted() end
        local current = flags(call("Read", owned.entity, "proofs"))
        if not current or not apply_fence() then
            verified = false
        else
            local wanted, changed = flags(current), false
            for index = 1, 8 do
                -- Slot 7 is dontResetOnCleanup, not damage immunity. Preserve it.
                if index ~= 7 then
                    local entry = owned.proofs[index]
                    if entry and current[index] ~= entry.last then owned.proofs[index] = nil end
                    wanted[index] = true
                    if current[index] ~= true then changed = true end
                end
            end
            if changed then
                if not control(owned, false, apply_fence) then
                    if not apply_fence() then return interrupted() end
                    return wait_for_authority(row, now)
                end
                for index = 1, 8 do
                    if index ~= 7 and current[index] ~= wanted[index] then
                        owned.proofs[index] = owned.proofs[index] or { before = current[index], last = wanted[index] }
                    end
                end
                write(owned, "proofs", wanted, current, apply_fence)
            end
            if not apply_fence() then return interrupted() end
            local after = flags(call("Read", owned.entity, "proofs"))
            if not after then
                verified = false
            else
                for index = 1, 8 do if index ~= 7 and after[index] ~= true then verified = false end end
            end
        end
        if not apply_fence() then return interrupted() end
        -- A later setter or owner update may clear a scalar that was already
        -- checked above. Close every application with fresh scalar/proof reads;
        -- these observations still do not establish immunity on another client.
        for _, field in ipairs(scalar_order) do
            if call("Read", owned.entity, field) ~= desired[field] then verified = false end
            if not apply_fence() then return interrupted() end
        end
        local final_proofs = flags(call("Read", owned.entity, "proofs"))
        if not apply_fence() then return interrupted() end
        if not final_proofs then
            verified = false
        else
            for index = 1, 8 do if index ~= 7 and final_proofs[index] ~= true then verified = false end end
        end
        authority = control(owned, false, apply_fence)
        if not apply_fence() then return interrupted() end
        if not authority then return wait_for_authority(row, now) end
        row.authority_since, authority_wait_ms = nil, 0
        if not verified then return wait_for_readback(row, now) end
        row.readback_since = nil
        status("LOCAL_PROTECTION_OBSERVED", "Protection observed on this client; remote immunity is unverified.")
        return true
    end
    function api.Request(pid, wanted)
        if wanted ~= true then
            if intent and (pid == nil or pid == intent.pid) and (intent.enabled or intent.latched) then
                cancel("Off",
                    false)
            end
            return true
        end
        if stopped then return false, "Remote protection is stopped." end
        if intent and intent.enabled then
            if pid == intent.pid then return true end
            return false, "Disable Remote Godmode on the current player first."
        end
        if intent and intent.latched then return false, "Turn Remote Godmode off before selecting a new character." end
        if busy or lease then return false, "Remote protection restoration is pending." end
        revision = revision + 1
        local row, token = { pid = pid, enabled = true }, revision
        intent = row
        local pin = call("Pin", pid)
        if not enabled(row, token) then return false, "Remote protection request changed." end
        if not pin then
            cancel("Player connection or character is unavailable.", true)
            return false, "Player connection or character is unavailable."
        end
        row.pin = pin
        due = -100000
        authority, authority_detail, authority_wait_ms = nil, {}, 0
        status("PENDING_AUTHORITY", "Requesting control (0 / 4 s).")
        return true
    end

    function api.Cancel(reason, halt, pid)
        if pid ~= nil and (not intent or pid ~= intent.pid) then return true end
        -- An automatic checkbox reset must preserve the terminal outcome.
        if intent and not intent.enabled and halt ~= true and reason == intent.reason then
            return not lease and not busy
        end
        cancel(reason or "Off", halt == true)
        if halt then stopped = true end
        return not lease and not busy
    end

    function api.Tick(now, allow)
        if busy then return false end
        now = tonumber(now) or 0
        if now < due then return api.CanHandoff() end
        due = now + 50
        busy = true
        local ok, result = pcall(step, now, allow)
        busy = false
        if not ok then
            status("READBACK_PENDING", "Protection state is unavailable."); return false
        end
        return result == true
    end

    function api.Drain(now)
        api.Cancel("Restoration pending.", true)
        due = -100000
        api.Tick(now, false)
        return api.CanHandoff()
    end

    function api.CanHandoff() return not busy and (not lease or count_owned() == 0 and not lease.inflight) end

    function api.Requested() return intent and intent.enabled == true or lease ~= nil or busy end

    function api.Snapshot()
        return {
            player_id = intent and intent.pid or -1,
            enabled = intent and intent.enabled == true or false,
            phase = phase,
            message = message,
            authority = authority,
            owned = count_owned(),
            pending = not api.CanHandoff(),
            local_view_only = true,
            peer_effects_verified = false,
            local_protection_observed = phase == "LOCAL_PROTECTION_OBSERVED" and authority == true,
            control = copied_control_detail(authority_detail),
            control_wait_ms = authority_wait_ms,
            control_deadline_ms = 4000
        }
    end

    return api
end
-- END REMOTE GUARD44 CONTROLLER

-- Normal-location respawn: advance only the game's active Wasted countdown.
-- Freemode still chooses the spawn and owns fades, search and streaming.
local function new_fast_respawn_delay(host)
    local api, enabled, lease, last, pending = {}, false, nil, nil, nil
    local request_revision = 0 -- Cancellation only; never an engine-program generation.
    local function signed(value) return ((value + 0x80000000) & 0xffffffff) - 0x80000000 end
    local function integer(value) return math.type(value) == "integer" end
    local function read(fresh, intent)
        local ok, row = pcall(host.Read, fresh == true, intent)
        if not ok or type(row) ~= "table" then return nil end
        local copy = {}; for key, value in pairs(row) do copy[key] = value end
        return copy
    end
    local function same(a, b)
        return a and b and a.pid == b.pid and a.ped == b.ped and a.identity == b.identity
            and (a.freemode_thread == nil or b.freemode_thread == nil or a.freemode_thread == b.freemode_thread)
    end
    local function eligible(row)
        return row and row.online == true and row.transition == false and row.activity == false and row.mission == false
            and row.dead == true and integer(row.pid) and row.pid >= 0 and row.pid <= 31
            and integer(row.ped) and row.ped > 0 and type(row.identity) == "string" and row.identity ~= ""
    end
    local function ready(row)
        if not eligible(row) or row.stage ~= -1 or row.strip ~= 2 or row.mode ~= 2 or row.delay ~= -1
            or not integer(row.flags) or not integer(row.stamp) or not integer(row.network)
            or not integer(row.acceleration) then
            return false
        end
        if (row.flags & ((1 << 1)|(1 << 7)|(1 << 20)|(1 << 21))) ~= 0 then return false end
        local elapsed = signed(row.network - row.stamp)
        return elapsed >= 0 and elapsed <= 12000 and row.acceleration >= 0 and row.acceleration <= 9550
    end
    local function prove()
        local revision = request_revision; local ok, value = pcall(host.Prove,
            function() return request_revision == revision end); return ok and value == true
    end
    local function write(value, expected)
        local revision = request_revision; local ok, result = pcall(host.Write, value, expected,
            function() return request_revision == revision end); return ok and result ~= false
    end
    local function retired(row, owned)
        return row and (not same(row, owned) or row.dead == false
            or integer(row.stage) and row.stage ~= -1 or integer(row.strip) and row.strip ~= 2
            or integer(row.flags) and (row.flags & (1 << 1)) ~= 0
            or integer(row.stamp) and row.stamp ~= owned.written)
    end
    function api.Request(wanted)
        if (wanted == true) ~= enabled then request_revision = request_revision + 1 end
        if wanted == true and not enabled then last = nil end
        enabled = wanted == true
        if not enabled then pending = nil end
    end

    function api.Tick()
        if not enabled and not lease then
            pending = nil; return true
        end
        if lease then
            local row = read(false, enabled and "observe" or nil)
            if enabled and row and row.observation_due == true and not retired(row, lease) then row = read() end
            if retired(row, lease) then
                lease = nil
            elseif not enabled then
                if not row or row.online ~= true or row.transition ~= false or row.activity ~= false or row.mission ~= false
                    or row.stamp ~= lease.written or not prove() then
                    return false
                end
                local fresh = read(true)
                if retired(fresh, lease) then
                    lease = nil; return true
                end
                if not fresh or not same(fresh, lease) or fresh.stamp ~= lease.written
                    or fresh.stage ~= -1 or fresh.strip ~= 2 or fresh.flags ~= row.flags then
                    return false
                end
                if not write(lease.original, fresh) then return false end
                local after = read()
                if after and same(after, lease) and after.stamp == lease.original then
                    lease = nil
                elseif retired(after, lease) then
                    lease = nil
                else
                    return false
                end
            end
            return lease == nil or enabled
        end
        if pending then
            local before = pending; pending = nil
            local observed = read(false, "observe")
            if not observed or observed.dead ~= true or not same(observed, before) then return true end
            -- Second fresh proof stays BETWEEN the original and final snapshots.
            if not prove() or not enabled then return true end
            local fresh = read(true)
            if not enabled or not ready(fresh) or not same(before, fresh)
                or fresh.freemode_thread ~= before.freemode_thread
                or fresh.stamp ~= before.stamp or fresh.flags ~= before.flags then
                return true
            end
            local key = fresh.identity .. ":" .. fresh.pid .. ":" .. fresh.ped .. ":" .. fresh.stamp
            if key == last then return true end
            local owned = {
                pid = fresh.pid,
                ped = fresh.ped,
                identity = fresh.identity,
                freemode_thread = fresh.freemode_thread,
                original = fresh.stamp,
                written = signed(fresh.network - 11000)
            }
            lease, last = owned, key
            if not write(owned.written, fresh) then return false end
            local after = read()
            if after and same(after, owned) and after.stamp == owned.original then
                lease = nil; return false
            end
            if retired(after, owned) then
                lease = nil; return true
            end
            return after ~= nil and after.stamp == owned.written
        end
        local row = read(false, "admission")
        if not eligible(row) or row.proof_backoff == true then return true end
        if row.stage ~= nil then
            if not ready(row) then return true end
            if row.identity .. ":" .. row.pid .. ":" .. row.ped .. ":" .. row.stamp == last then return true end
        end
        -- First proof precedes every versioned admission snapshot. Publishing a
        -- pending transaction owns no mutation or restore debt until next Tick.
        if not prove() or not enabled then return true end
        local first = read(true)
        if not enabled or not ready(first) or not same(row, first)
            or row.freemode_thread ~= first.freemode_thread then
            return true
        end
        if first.identity .. ":" .. first.pid .. ":" .. first.ped .. ":" .. first.stamp == last then return true end
        pending = first
        return true
    end

    function api.Drain()
        request_revision = request_revision + 1; enabled = false; pending = nil; return api.Tick() and lease == nil
    end

    function api.CanHandoff() return lease == nil end

    function api.Requested() return enabled or lease ~= nil end

    return api
end


local fast_respawn_delay
local fast_respawn_host

-- BEGIN FAST RESPAWN CURRENT SOURCE READER
-- Fresh engine-registry coherence, not an allocation-generation/lock claim.
-- No retained slot/page authority, ScanScript fallback or writes.
local function new_fast_respawn_source_reader(mem, fence)
    local spec = {
        hash = 3363132797,
        size = 8180501,
        natives = 2839,
        locator_rva = 9551938,
        registry_rva = 65867776,
        locator =
        "8b565883e21f488d05d94e5b030fb64c02014885c974614839b4c8d8000000",
        anchors = { { pc = 5866565, hex = "2d 00 02 00 00 61 7c ca 28 47 5c 04 2e 00 01" }, { pc = 6086696, hex = "2d 00 02 00 00 61 7c ca 28 47 5d 04 2e 00 01" }, { pc = 6087044, hex = "2d 00 02 00 00 61 2a 37 28 47 5b 02 2e 00 01" }, { pc = 6087168, hex = "2d 01 04 00 00 2c 01 04 08 61 f8 8f 28 49 d4 01 41 ec 39 03 38 00 2c 01 04 08 61 f8 8f 28 49 d4 01 42 ec 2c 01 00 88 61 2a 37 28 48 7d 0b 2e 01 00" }, { pc = 5925103, hex = "2a 37 28 48 7a 0b 55 00 00 55 68 01 2c 01 06 d4 61 2a 37 28 47 7b 0b 2c 09 01 7a 56 03 00 55 53 01 2c 01 06 d4 61 2a 37 28 47 7b 0b 5d 84 e1 5c 2c 09 01 cc 2c 09 01" }, { pc = 5925748, hex = "0b 00 00 00 be 01 55 fb 01 55 f8 01 2c 01 06 d4 61 2a 37 28 47 7c 0b 2c 09 04 2a 5d 28 e0 5c 59 05 00 72 5d 32 6f 72 55 da 01 61 2a 37 28 47 6d 0b 71 57 08 00 72 61" }, { pc = 6098733, hex = "43 ed 10 2c 01 06 d4 61 7c ca 28 46 e2 06 47 f1 02 2c 09 04 2a 2c 05 06 0f 02 38 00 30 55 53 00 43 5d 28 2c 01 06 d4 61 7c ca 28 46 e2 06 47 f1 02 2c 09 04 2a 2c 05 06 0f 61 7c ca 28 46 e2 06 47 f3 02 01 02 38 00 30 61 7c ca 28 46 e2 06 46 bf 02 41 10 5d 39 8c 5a 56 18 00 38 00 2f 3d 05 38 00 30 61 7c ca 28 46 e2 06 46 f4 02 25 0b 2c 08 0a ef 38 00 2f 71 5c bf 00 71 38 00 30 72 2c" } }
    }
    local function integer(v) return type(v) == 'number' and v == v and math.abs(v) < math.huge and v % 1 == 0 end
    local function ptr(v) return integer(v) and v >= 0x10000 and v <= 0x7fffffffffff and v % 8 == 0 end
    local function need(v, s) if not v then error(s, 0) end end
    local function decode(hex)
        local b = {}; for v in hex:gmatch('%x%x') do b[#b + 1] = string.char(tonumber(v, 16)) end; return table.concat(b)
    end
    local locator = decode(spec.locator)
    for _, a in ipairs(spec.anchors) do
        a.bytes = decode(a.hex); a.page = a.pc // 16384; a.offset = a.pc % 16384
        need(a.pc >= 0 and a.pc + #a.bytes <= spec.size and a.offset + #a.bytes <= 16384, 'source_spec_invalid')
    end
    local stats = { long = 0, uint = 0, byte = 0 }
    local function guard() need(not fence or fence() == true, 'scope_changed') end
    -- Every memory/base host boundary has a fresh scope precheck. Adjacent
    -- scalar postcheck/precheck duplicates are coalesced: only Lua arithmetic and
    -- validation intervene. Public proof/current/address returns close scope.
    local function q(a)
        guard(); need(ptr(a) and a <= 0x7ffffffffff7, 'pointer_extent_invalid'); stats.long = stats.long + 1
        local v = mem.ReadLong(a); need(integer(v), 'pointer_value_invalid'); return v
    end
    local function u(a)
        guard(); need(integer(a) and a >= 0x10000 and a <= 0x7ffffffffffc, 'uint_extent_invalid'); stats.uint = stats
            .uint + 1
        local v = mem.ReadUInt(a); need(integer(v) and v >= 0 and v <= 0xffffffff, 'uint_value_invalid'); return v
    end
    local function b(a)
        guard(); need(integer(a) and a >= 0x10000 and a <= 0x7fffffffffff, 'byte_extent_invalid'); stats.byte = stats
            .byte + 1
        local v = mem.ReadUByte(a); need(integer(v) and v >= 0 and v <= 255, 'byte_value_invalid'); return v
    end
    -- ReadLong is the documented64-bit scalar reader. Raw source reads may be
    -- unaligned; exact signed integer storage is required for all64 source bits.
    local function l(a)
        guard(); need(integer(a) and a >= 0x10000 and a <= 0x7ffffffffff8, 'long_extent_invalid'); stats.long = stats
            .long + 1
        local v = mem.ReadLong(a); need(integer(v) and math.type(v) == 'integer', 'long_bits_unknown'); return v
    end
    local function exact(at, bytes, check)
        local offset = 0
        while offset < #bytes do
            -- A preceding read's mapping change is observed here before any next data
            -- read. Only local offset arithmetic occurs between adjacent mapping gates.
            if check then check() end
            local remaining = #bytes - offset
            if check and remaining >= 8 then
                need(l(at + offset) == string.unpack('<i8', bytes, offset + 1), 'source_bytes_changed'); offset = offset +
                    8
            elseif remaining >= 4 then
                need(u(at + offset) == string.unpack('<I4', bytes, offset + 1), 'source_bytes_changed'); offset = offset +
                    4
            else
                need(b(at + offset) == bytes:byte(offset + 1), 'source_bytes_changed'); offset = offset + 1
            end
        end
        -- This closes the final data read; it is never omitted by adjacency reuse.
        if check then check() end
    end

    local function image()
        guard(); local base = mem.GetBaseAddress('GTA5_Enhanced.exe'); need(ptr(base), 'image_base_unknown')
        need(b(base) == 0x4d and b(base + 1) == 0x5a, 'image_unknown')
        local pe = u(base + 0x3c); need(pe >= 0x40 and pe < 4096 and pe % 4 == 0, 'image_unknown')
        need(u(base + pe) == 0x4550 and u(base + pe + 8) == 1789157136 and u(base + pe + 80) == 95703552, 'image_changed')
        exact(base + spec.locator_rva, locator)
        local disp = u(base + spec.locator_rva + 9); if disp >= 0x80000000 then disp = disp - 0x100000000 end
        local table = base + spec.locator_rva + 13 + disp + 0xd8
        need(table == base + spec.registry_rva and table + 176 * 8 <= base + 95703552, 'registry_locator_changed')
        guard(); need(mem.GetBaseAddress('GTA5_Enhanced.exe') == base, 'image_base_changed'); return base, table
    end
    local function slot(p) need(q(p.table + p.index * 8) == p.program, 'program_entry_changed') end
    local function pu(p, offset)
        slot(p); local v = u(p.program + offset); slot(p); return v
    end
    local function pq(p, offset)
        slot(p); local v = q(p.program + offset); slot(p); return v
    end
    local function metadata(p)
        slot(p); need(pu(p, 0x58) == spec.hash and pu(p, 0x1c) == spec.size and pu(p, 0x2c) == spec.natives,
            'program_header_changed')
        need(pq(p, 0x10) == p.pages and pq(p, 0x40) == p.cache, 'program_tables_changed')
    end
    local function page_current(p, index)
        slot(p); need(pq(p, 0x10) == p.pages, 'code_table_changed')
        local page = q(p.pages + index * 8); slot(p)
        need(page == p.page[index] and ptr(page) and page <= 0x7fffffffc000, 'code_page_changed')
    end
    local function current(p)
        need(type(p) == 'table', 'proof_unknown'); local base, table = image()
        need(base == p.base and table == p.table, 'image_changed'); metadata(p)
        for index in pairs(p.page) do page_current(p, index) end
        metadata(p); guard(); return true
    end
    local api = {}
    function api.Prove()
        stats = { long = 0, uint = 0, byte = 0 }
        local ok, value = pcall(function()
            local base, table = image(); local result
            for index = 0, 175 do
                local program = q(table + index * 8)
                if program ~= 0 then
                    need(ptr(program) and program <= 0x7fffffffff80, 'program_pointer_invalid')
                    local p = { base = base, table = table, index = index, program = program }
                    if pu(p, 0x58) == spec.hash then
                        need(not result, 'duplicate_program'); result = p
                    end
                end
            end
            need(result, 'program_missing'); local p = result
            need(pu(p, 0x1c) == spec.size and pu(p, 0x2c) == spec.natives, 'program_header_changed')
            p.pages = pq(p, 0x10); p.cache = pq(p, 0x40); p.page = {}
            need(ptr(p.pages) and p.pages <= 0x7ffffffff060 and ptr(p.cache), 'program_tables_invalid')
            for _, a in ipairs(spec.anchors) do
                if not p.page[a.page] then
                    metadata(p); local page = q(p.pages + a.page * 8); slot(p)
                    need(ptr(page) and page <= 0x7fffffffc000, 'code_page_invalid'); p.page[a.page] = page
                end
            end
            current(p)
            for _, a in ipairs(spec.anchors) do
                metadata(p); page_current(p, a.page)
                exact(p.page[a.page] + a.offset, a.bytes, function() page_current(p, a.page) end)
                metadata(p); page_current(p, a.page)
            end
            current(p); return p
        end)
        if ok then return value end
        return nil, type(value) == 'string' and value:match('^[a-z_]+$') and value or 'reader_api_error'
    end

    function api.Current(p)
        local ok, value = pcall(current, p); return ok and value == true
    end

    function api.Address(p, index)
        local ok, value = pcall(function()
            current(p); local a = assert(spec.anchors[index]); page_current(p, a.page); guard(); return p.page[a.page] +
                a.offset
        end)
        if ok then return value end
    end

    function api.Verify(p)
        local ok, value = pcall(function()
            current(p)
            for _, a in ipairs(spec.anchors) do
                metadata(p); page_current(p, a.page)
                exact(p.page[a.page] + a.offset, a.bytes, function() page_current(p, a.page) end)
                metadata(p); page_current(p, a.page)
            end
            current(p); return true
        end)
        return ok and value == true
    end

    function api.Stats() return { long = stats.long, uint = stats.uint, byte = stats.byte } end

    return api
end
-- END FAST RESPAWN CURRENT SOURCE READER

local function new_fast_respawn_delay_host(deps)
    local api, proof_at, proof_tried_at, epoch = {}, nil, nil, 0
    local proof_thread, proof_epoch, proof_generation = nil, nil, 0
    local source_reader, proof_resource, active_action
    local threads_at, threads_ok, threads_identity, last_snapshot_at
    local N, G, M, P = deps.Natives, deps.ScriptGlobal, deps.Memory, deps.Players
    local hash = deps.Utils.Joaat("freemode")
    local function normal_threads(now, fresh)
        if not fresh and threads_at and now >= threads_at and now - threads_at <= 100 then return threads_ok end
        threads_at, threads_ok, threads_identity = now, false, nil
        local ok, normal, identity = pcall(function()
            if N.InvokeVoid(0xDADFADA5A20143A8) == false then return false end
            local seen, freemode, mission, owner = {}, 0, 0, nil
            for _ = 1, 1024 do
                local id = N.InvokeInt(0x30B4FA1C82DD4B9F)
                if math.type(id) ~= "integer" or id < 0 or id > 0x7fffffff then return false end
                if id == 0 then return freemode == 1 and mission == 0, owner end
                if seen[id] then return false end; seen[id] = true
                local name = N.InvokeString(0x05A42BA9FC8DA96B, id)
                local active = N.InvokeBool(0x46E9AE36D8FA6417, id)
                if type(name) ~= "string" or type(active) ~= "boolean" or active and name == "" then return false end
                if active then
                    name = name:lower()
                    if name == "freemode" then
                        freemode = freemode + 1; owner = id
                    elseif name == "fm_mission_controller" or name == "fm_mission_controller_2020" then
                        mission = mission + 1
                    end
                end
            end
            return false
        end)
        threads_ok = ok and normal == true and math.type(identity) == "integer" and identity > 0
        threads_identity = threads_ok and identity or nil
        return threads_ok
    end
    local function thread_still(id)
        return math.type(id) == "integer" and id > 0
            and N.InvokeString(0x05A42BA9FC8DA96B, id) == "freemode"
            and N.InvokeBool(0x46E9AE36D8FA6417, id) == true
    end
    local function local_identity(pid, ped, final_pid, final_ped)
        if pid == nil then
            pid, ped = deps.local_player_id(), deps.local_ped()
            final_pid, final_ped = deps.local_player_id(), deps.local_ped()
        end
        if final_pid ~= pid or final_ped ~= ped then return end
        if math.type(pid) ~= "integer" or pid < 0 or pid > 31 or math.type(ped) ~= "integer" or ped <= 0 then return end
        local function capture()
            local p = P and P.GetById(pid); if not p or type(p.GetAddress) ~= "function" then return end
            local cxn, address = p.CxnId, p:GetAddress(); local info = p:GetGamerInfo()
            local rid = info and info.RockstarId ~= nil and tostring(info.RockstarId) or nil
            if math.type(cxn) ~= "integer" or type(address) ~= "number" or address % 1 ~= 0
                or address < 0x10000 or address > 0x7fffffffffff or not rid or rid == "" or rid == "0" then
                return
            end
            return cxn, address, rid
        end
        local c, a, r = capture(); local c2, a2, r2 = capture()
        if c ~= nil and c == c2 and a == a2 and r == r2 then
            return { pid = pid, ped = ped, cxn = c, address = a, rid = r }
        end
    end
    local function same_identity(a, b)
        return a and b and a.pid == b.pid and a.ped == b.ped and a.cxn == b.cxn and a.address == b.address and
            a.rid == b.rid
    end
    local function resource_current()
        return source_reader and proof_resource and source_reader.Current(proof_resource) == true
    end
    function api.Prove(allowed)
        proof_at, proof_thread, proof_epoch, proof_resource, source_reader = nil, nil, nil, nil, nil
        proof_generation = proof_generation + 1
        proof_tried_at = deps.now_ms()
        local generation, owner_epoch = proof_generation, epoch
        local previous_action = active_action; active_action = allowed
        local ok, matched = pcall(function()
            if not N or not G or not M or G.AreValid() ~= true or N.InvokeBool(0x68049AEFF83D8F0A) ~= false
                or N.InvokeBool(0x9DE624D2FC4B603F) ~= true then
                return false
            end
            if not threads_ok or not threads_identity then
                if not normal_threads(deps.now_ms(), true) then return false end
            end
            local owner, identity, began = threads_identity, local_identity(), deps.now_ms()
            if not identity then return false end
            local function scope()
                if epoch ~= owner_epoch or proof_generation ~= generation
                    or active_action and active_action() ~= true then
                    return false
                end
                if not thread_still(owner) then return false end
                -- Native ID/ped observations precede readiness and the final
                -- primitive connection snapshot; none follows that snapshot.
                local pid, ped = deps.local_player_id(), deps.local_ped()
                local final_pid, final_ped = deps.local_player_id(), deps.local_ped()
                local now = deps.now_ms()
                if type(now) ~= "number" or now < began or now - began > 500
                    or N.InvokeBool(0x9DE624D2FC4B603F) ~= true
                    or N.InvokeBool(0x68049AEFF83D8F0A) ~= false or N.InvokeBool(0x05095437424397FA) ~= false then
                    return false
                end
                return same_identity(identity, local_identity(pid, ped, final_pid, final_ped)) and epoch == owner_epoch and
                    proof_generation == generation
                    and (not active_action or active_action() == true)
            end
            local reader = new_fast_respawn_source_reader(M, scope)
            local resource = reader.Prove()
            if not resource or not scope() or G.GetInt(2658296) ~= 32 or not scope()
                or not thread_still(owner) or not scope() then
                return false
            end
            local verified_at = deps.now_ms()
            if not reader.Current(resource) then return false end
            source_reader, proof_resource = reader, resource
            proof_at, proof_thread, proof_epoch = verified_at, owner, owner_epoch
            return true
        end)
        active_action = previous_action
        return ok and matched == true
    end

    function api.Read(fresh, intent)
        local pid, ped = deps.local_player_id(), deps.local_ped()
        if math.type(pid) ~= "integer" or pid < 0 or pid > 31 or math.type(ped) ~= "integer" or ped <= 0 then return nil end
        local dead = N.InvokeBool(0x5F9532F3B5CC2551, ped, false)
        if type(dead) ~= "boolean" then return nil end
        if dead ~= true then return { pid = pid, ped = ped, dead = dead } end
        local p = P and P.GetById(pid)
        local info = p and p:GetGamerInfo()
        local rid, cxn = info and info.RockstarId, p and p.CxnId
        if rid == nil or tostring(rid) == "0" or math.type(cxn) ~= "integer" then return nil end
        local identity = tostring(rid) .. ":" .. cxn .. ":" .. epoch
        -- Cheap lease frames do not touch globals. A bounded full observation
        -- still notices a new death when a low-FPS sample missed the alive edge.
        if intent == "observe" and fresh ~= true then
            local at = deps.now_ms()
            return {
                pid = pid,
                ped = ped,
                identity = identity,
                dead = dead,
                observation_due = not last_snapshot_at or at < last_snapshot_at or at - last_snapshot_at > 500
            }
        end
        local row = {
            pid = pid,
            ped = ped,
            identity = identity,
            online = N.InvokeBool(0x9DE624D2FC4B603F),
            transition = N.InvokeBool(0x68049AEFF83D8F0A),
            activity = N.InvokeBool(0x05095437424397FA),
            dead = dead
        }
        if row.online ~= true or row.transition ~= false or row.activity ~= false then return row end
        local now = deps.now_ms()
        row.mission = not normal_threads(now, fresh == true)
        if row.mission then return row end
        row.freemode_thread = threads_identity
        local cached = proof_at and now >= proof_at and now - proof_at <= 500 and proof_epoch == epoch and
            proof_thread == threads_identity
        if intent == "admission" and fresh ~= true and not cached then
            row.proof_backoff = not proof_at and proof_tried_at and now >= proof_tried_at and now - proof_tried_at <= 500 or
                false
            return row
        end
        if not proof_at or now < proof_at or now - proof_at > 500 then
            if proof_tried_at and now >= proof_tried_at and now - proof_tried_at <= 500 then return row end
            if not api.Prove() then return row end
        end
        local generation, owner_epoch, owner = proof_generation, proof_epoch, proof_thread
        local function current()
            return proof_at ~= nil and epoch == owner_epoch and proof_epoch == owner_epoch
                and proof_generation == generation and proof_thread == owner
                and threads_ok and threads_identity == owner
        end
        if not current() or G.AreValid() ~= true or not current() or not resource_current() then
            proof_at = nil; return row
        end
        local function get(index)
            assert(current(), "Fast Respawn source generation changed")
            local value = G.GetInt(index)
            assert(current(), "Fast Respawn source generation changed")
            return value
        end
        local player = 2658296 + 1 + pid * 468
        row.stage = get(player + 236)
        row.strip = get(2673276 + 1762 + 701)
        row.flags = get(2673276 + 1762 + 756)
        row.stamp = get(2673276 + 1762 + 753)
        row.acceleration = get(2673276 + 1762 + 755)
        row.mode = get(2673276 + 1116)
        row.delay = get(2673276 + 1117)
        row.network = N.InvokeInt(0x7A5487FE9FAA6B48)
        if not current() or not thread_still(owner) or not current() or not resource_current() then
            proof_at = nil; return nil
        end
        row.source_generation = generation
        last_snapshot_at = deps.now_ms()
        return row
    end

    function api.Write(value, expected, allowed)
        local previous_action = active_action; active_action = allowed
        local ok, result = pcall(function()
            local function current()
                return type(expected) == "table" and proof_at ~= nil and proof_epoch == epoch
                    and expected.source_generation == proof_generation and expected.freemode_thread == proof_thread
                    and threads_ok and threads_identity == proof_thread
                    and (not active_action or active_action() == true)
            end
            if math.type(value) ~= "integer" or not current() or G.AreValid() ~= true
                or not current() or not thread_still(proof_thread) or not current()
                or not source_reader or not proof_resource or not source_reader.Verify(proof_resource) or not current() then
                return false
            end
            G.SetInt(2673276 + 1762 + 753, value)
            return current() and resource_current() and G.GetInt(2673276 + 1762 + 753) == value and current()
        end)
        active_action = previous_action
        return ok and result == true
    end

    function api.Invalidate()
        proof_at, proof_tried_at, proof_thread, proof_epoch, threads_at, threads_identity, last_snapshot_at = nil, nil,
            nil, nil, nil, nil, nil
        source_reader, proof_resource = nil, nil
        threads_ok = false; epoch = epoch + 1; proof_generation = proof_generation + 1
    end

    return api
end


