    function Messiah.State()
        if type(State.messiah) ~= "table" then State.messiah = {} end
        local state = State.messiah
        -- Runtime fields are owned by this module after initialization. Repeating
        -- every conversion from projection/lease helpers cost work per primitive.
        -- A replacement state table or a new module owner still initializes fully.
        if state._normalization_owner == Messiah then return state end
        state.active = state.active == true
        state.ped = tonumber(state.ped) or 0
        state.phase = tostring(state.phase or Messiah.PHASES.OFF)
        state.phase_started_ms = tonumber(state.phase_started_ms) or 0
        state.resume_phase = tostring(state.resume_phase or Messiah.PHASES.IDLE_HOVER)
        state.anchor_z = tonumber(state.anchor_z) or 0.0
        state.target_z = tonumber(state.target_z) or state.anchor_z
        state.ascent_start_z = tonumber(state.ascent_start_z) or state.anchor_z
        state.last_hover_height = tonumber(state.last_hover_height)
        state.last_tick_ms = tonumber(state.last_tick_ms) or 0
        state.move_vx = tonumber(state.move_vx) or 0.0
        state.move_vy = tonumber(state.move_vy) or 0.0
        state.move_vz = tonumber(state.move_vz) or 0.0
        state.motion_requested = state.motion_requested == true
        state.activation_id = tonumber(state.activation_id) or 0
        state.activation_epoch = tonumber(state.activation_epoch) or state.activation_id
