    -- BEGIN REMOTE GUARD44 HOST
    function Live.remote_bool(hash, ...)
        local ok, value, raw, err = pcall(invoke_bool_detail, hash, ...)
        if not ok or err ~= nil or (raw ~= true and raw ~= false and raw ~= 0 and raw ~= 1) then return nil end
        return value == true
    end

    function Live.remote_release_buffer()
        local io = remote_proof_io44
        if io.busy then return false end
        if io.ptr == nil then return true end
        if not memory or type(memory.Free) ~= "function" then return false end
        io.busy = true
        local ok, result = pcall(memory.Free, io.ptr)
        if ok and result ~= false then io.ptr = nil end
        io.busy = false
        return io.ptr == nil
    end

    function Live.remote_entity_state(proof)
        if not proof or not Ignore.number(proof.handle) then return "unknown" end
        if proof.remote_context and module_context ~= proof.remote_context then return "unknown" end
        if Ignore.released(proof.handle) then return "retired" end
        local exists = Live.remote_bool(H.DOES_ENTITY_EXIST, proof.handle)
        if exists == false then return "retired" end
        if exists ~= true then return "unknown" end
        local pointer = Ignore.read(function() return gta.HandleToPointer(proof.handle) end)
        if not pointer then return "unknown" end
        local address = Ignore.address(pointer)
        if not address then return "unknown" end
        if address ~= proof.address then return "retired" end
        local network, known = Ignore.network(pointer)
        if not known then return "unknown" end
        if network ~= proof.network_id then return "retired" end
        -- Recheck the handle mapping after the NetObject observation. Unknown
        -- mappings keep the obligation; a positive new mapping retires it.
        local after = Ignore.read(function() return gta.HandleToPointer(proof.handle) end)
        local mapped = after and Ignore.address(after)
        if not mapped then return "unknown" end
        if mapped ~= proof.address then return "retired" end
        return "current"
    end

    function Live.read_remote_proofs(proof, extra)
        local io = remote_proof_io44
        local function current()
            return (not extra or extra() == true) and Live.remote_entity_state(proof) == "current"
                and (not extra or extra() == true)
        end
        if io.busy or not memory or type(memory.Alloc) ~= "function" or type(memory.Free) ~= "function"
            or type(memory.WriteInt) ~= "function" or type(memory.ReadInt) ~= "function" or not current() then
            return nil
        end
        io.busy = true
        local ok, result = pcall(function()
            if io.ptr == nil then
                local ptr = memory.Alloc(64)
                if type(ptr) ~= "number" or ptr <= 0 or ptr % 1 ~= 0 then return nil end
                io.ptr = ptr
            end
            local ptr = io.ptr
            if not current() then return nil end
            for index = 0, 7 do memory.WriteInt(ptr + index * 8, -1) end
            if not current() or Live.remote_bool(0xBE8CD9BE829BBEBF, proof.handle,
                    ptr, ptr + 8, ptr + 16, ptr + 24, ptr + 32, ptr + 40, ptr + 48, ptr + 56) ~= true or not current() then
                return nil
            end
            local values = {}
            for index = 1, 8 do
                local raw = memory.ReadInt(ptr + (index - 1) * 8)
                if type(raw) ~= "number" or raw % 1 ~= 0 then return nil end
                local value = raw % 256
                if value ~= 0 and value ~= 1 then return nil end
                values[index] = value == 1
            end
            if current() then return values end
        end)
        -- Allocation ownership is kept if Free fails. Only gameplay callbacks
        -- call this function/retry; CanHandoff and terminal disposal are pure.
        if io.ptr ~= nil then
            local freed, value = pcall(memory.Free, io.ptr)
            if freed and value ~= false then io.ptr = nil end
        end
        io.busy = false
        if ok and current() then return result end
    end

    function Live.remote_read_field(proof, field)
        if Live.remote_entity_state(proof) ~= "current" then return nil end
        if field == "proofs" then return Live.read_remote_proofs(proof) end
        local value
        if field == "invincible" then
            value = Ignore.read(function() return proof.pointer:IsInvincible() end)
        elseif field == "damageable" then
            value = Live.remote_bool(H.GET_ENTITY_CAN_BE_DAMAGED, proof.handle)
        elseif field == "critical" then
            value = Live.remote_bool(H.GET_PED_CONFIG_FLAG, proof.handle, 2, true)
        end
        if type(value) == "boolean" and Live.remote_entity_state(proof) == "current" then return value end
    end

    function Live.remote_control(proof, request, fence)
        local function valid()
            return (not fence or fence() == true) and Live.remote_entity_state(proof) == "current"
                and (not fence or fence() == true)
        end
        if not valid() then return false end
        local controlled = Live.remote_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, proof.handle)
        if not valid() then return false end
        if controlled ~= true and request and now_ms() >= (proof.remote_control_due or -100000) then
            proof.remote_control_due = now_ms() + 100
            if not valid() then return false end
            proof.remote_control_requests = (proof.remote_control_requests or 0) + 1
            local _, owner, pending, detail = Live.request_entity_control(local_player_id(), proof.handle, valid)
            proof.remote_control_owner, proof.remote_control_pending, proof.remote_control_detail = owner, pending,
                detail
            if not valid() then return false end
            controlled = Live.remote_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, proof.handle)
        end
        proof.remote_control_observed, proof.remote_control_checked_ms = controlled == true, now_ms()
        return controlled == true and valid()
    end

    function Live.remote_control_state(proof)
        -- Cached diagnostics only: UI snapshots must never probe natives or
        -- turn owner metadata into mutation authority.
        local detail = proof.remote_control_detail or {}
        return {
            requests = proof.remote_control_requests or 0,
            owner = proof.remote_control_owner,
            pending_owner = proof.remote_control_pending,
            checked_ms = proof.remote_control_checked_ms,
            observed = proof.remote_control_observed,
            entity_request = detail.entity_request,
            entity_request_accepted = detail.entity_request_accepted,
            network_id_request = detail.network_id_request,
            network_id_request_accepted = detail.network_id_request_accepted,
            give_control = detail.give_control
        }
    end

    function Live.remote_write_field(proof, field, value, expected, fence)
        local function valid()
            return (not fence or fence() == true) and Live.remote_entity_state(proof) == "current"
                and (not fence or fence() == true)
        end
        local function equal(a, b)
            if type(a) ~= type(b) then return false end
            if type(a) ~= "table" then return type(a) == "boolean" and a == b end
            for index = 1, 8 do if type(a[index]) ~= "boolean" or a[index] ~= b[index] then return false end end
            return true
        end
        if not valid() or not Live.remote_control(proof, false, valid) then return false end
        local current = Live.remote_read_field(proof, field)
        if not valid() or not equal(current, expected) or not Live.remote_control(proof, false, valid) or not valid() then return false end
        local ok, result
        if field == "invincible" then
            -- The setter also accepts dontResetOnCleanup. Preserve the live
            -- corresponding proof slot instead of blindly clearing it.
            local proofs = Live.read_remote_proofs(proof, valid)
            if not proofs or not valid() or Live.remote_read_field(proof, field) ~= expected
                or not Live.remote_control(proof, false, valid) or not valid() then
                return false
            end
            ok, result = pcall(invoke_void, H.SET_ENTITY_INVINCIBLE, proof.handle, value, proofs[7])
        elseif field == "damageable" then
            ok, result = pcall(invoke_void, H.SET_ENTITY_CAN_BE_DAMAGED, proof.handle, value)
        elseif field == "critical" then
            ok, result = pcall(invoke_void, H.SET_PED_CONFIG_FLAG, proof.handle, 2, value)
        elseif field == "proofs" and type(value) == "table" then
            ok, result = pcall(invoke_void, H.SET_ENTITY_PROOFS, proof.handle,
                value[1], value[2], value[3], value[4], value[5], value[6], value[7], value[8])
        end
        return ok == true and result == true and valid()
    end

    function Live.remote_guard_pin(pid)
        pid = Live.remote_player_index(pid)
        local local_id = local_player_id()
        if not started or not pid or pid == local_id then return nil end
        local identity, local_identity = Live.remote_identity(pid), Live.remote_identity(local_id)
        local snapshot = player_snapshot(pid)
        if not identity or not local_identity or not snapshot or not Ignore.number(snapshot.ped) then return nil end
        local pin = {
            pid = pid,
            local_id = local_id,
            identity = identity,
            local_identity = local_identity,
            ped = snapshot.ped,
            context = module_context,
            generation = Live.action_generation
        }
        -- Pin the physical identity during ON, before the first gameplay tick.
        -- A recycled numeric ped handle must never adopt a new character.
        local pointer = Ignore.read(function() return gta.HandleToPointer(pin.ped) end)
        if not pointer then return nil end
        local context = module_context
        local proof = Ignore.proof(pointer, function() return module_context ~= nil and module_context == context end,
            pin.ped)
        if not proof then return nil end
        proof.remote_context = context
        pin.entity = proof
        if Live.remote_guard_target(pin, proof) == "current" then return pin end
    end

    function Live.remote_guard_target(pin, proof)
        if not pin then return "unknown" end
        proof = proof or pin.entity
        if not proof or not pin.entity then return "unknown" end
        if proof.handle ~= pin.entity.handle or proof.address ~= pin.entity.address or proof.network_id ~= pin.entity.network_id then
            return
            "retired"
        end
        if pin.context ~= module_context or pin.generation ~= Live.action_generation or pin.local_id ~= local_player_id() then
            return
            "retired"
        end
        if not started then return "unknown" end
        local identity, local_identity = Live.remote_identity(pin.pid), Live.remote_identity(pin.local_id)
        if not identity or not local_identity then return "unknown" end
        if identity.rid ~= pin.identity.rid or identity.cxn ~= pin.identity.cxn or identity.local_id ~= pin.identity.local_id
            or local_identity.rid ~= pin.local_identity.rid or local_identity.cxn ~= pin.local_identity.cxn
            or local_identity.local_id ~= pin.local_identity.local_id then
            return "retired"
        end
        local snapshot = player_snapshot(pin.pid)
        if not snapshot then return "unknown" end
        if Ignore.number(snapshot.ped) and snapshot.ped ~= pin.ped then return "retired" end
        if snapshot.ped ~= pin.ped then return "unknown" end
        local dead = Live.remote_bool(0x5F9532F3B5CC2551, pin.ped, false)
        if dead == true then return "retired" end
        if dead == nil or snapshot.passive or snapshot.ghost then return "unknown" end
        local entity_state = proof and Live.remote_entity_state(proof) or "current"
        -- Close the entity/native observations with the pinned connections.
        local after, local_after = Live.remote_identity(pin.pid), Live.remote_identity(pin.local_id)
        if not after or not local_after then return "unknown" end
        if pin.context ~= module_context or pin.generation ~= Live.action_generation or pin.local_id ~= local_player_id()
            or after.rid ~= pin.identity.rid or after.cxn ~= pin.identity.cxn or after.local_id ~= pin.identity.local_id
            or local_after.rid ~= pin.local_identity.rid or local_after.cxn ~= pin.local_identity.cxn
            or local_after.local_id ~= pin.local_identity.local_id then
            return "retired"
        end
        return entity_state
    end

    function Live.remote_guard_capture(pin, fence)
        if fence() and Live.remote_guard_target(pin, pin.entity) == "current" and fence() then return pin.entity end
    end

    remote_guard44 = new_remote_guard44({
        Pin = Live.remote_guard_pin,
        TargetState = Live.remote_guard_target,
        Capture = Live.remote_guard_capture,
        EntityState = Live.remote_entity_state,
        Control = Live.remote_control,
        Read = Live.remote_read_field,
        Write = Live.remote_write_field,
        ControlState = Live.remote_control_state,
        Report = function(phase, detail, pid)
            local snapshot = remote_guard44 and remote_guard44.Snapshot() or {}
            local control = snapshot.control or {}
            log_info(("RemoteGodmode pid=%s state=%s detail=%s attempts=%s owner=%s pending_owner=%s entity_request=%s network_id_request=%s give_control=%s")
                :format(
                    tostring(pid), tostring(phase), tostring(detail), tostring(control.requests or 0),
                    tostring(control.owner),
                    tostring(control.pending_owner), tostring(control.entity_request),
                    tostring(control.network_id_request),
                    tostring(control.give_control)))
            if phase == "NO_AUTHORITY" or phase == "PROTECTION_UNVERIFIED" or (phase == "RESTORE_PENDING" and tostring(detail):find("4 seconds", 1, true)) then
                toast(tostring(detail), 6500, "warning")
            end
        end
    })
    function Live.remote_guard_cancel(reason, halt, pid)
        if remote_guard44 then remote_guard44.Cancel(reason, halt, pid) end
        local ref = Live.remote_guard_feature
        if ref and (pid == nil or ref.pid == pid) then
            Live.remote_guard_feature = nil
            pcall(function() if ref.feature:IsToggled() then ref.feature:Toggle(false) end end)
        end
    end

    function Live.remote_guard_tick(now, allow)
        if remote_guard44 then
            remote_guard44.Tick(now, allow)
            local snapshot = remote_guard44.Snapshot()
            if not snapshot.enabled and Live.remote_guard_feature then
                Live.remote_guard_cancel(snapshot.message, false, snapshot.player_id)
            end
        end
        Live.remote_release_buffer()
    end

    function Live.remote_protection_can_handoff()
        return (not remote_guard44 or remote_guard44.CanHandoff()) and remote_proof_io44.ptr == nil
            and not remote_proof_io44.busy and not Live.remote_write_inflight and not Live.remote_vehicle_restore_busy
            and next(State.remote_vehicle_protection or {}) == nil
    end

    -- Public exports are disabled by Module.Stop. This pure raw predicate must
    -- remain callable by final disposal after its public wrapper is retired.
    remote_protection_handoff44 = Live.remote_protection_can_handoff
    -- END REMOTE GUARD44 HOST

    local function remote_godmode_label(state)
        return state.kind == "kill" and "Godmode kill"
            or state.kind == "vehicle_grant" and "Vehicle Godmode"
            or state.kind == "vehicle" and "Remove Vehicle Godmode"
            or state.kind == "glitched" and "Remove Godmode" or "Remove Player Godmode"
    end
    local function remote_protection_identity_valid(state)
        return state and module_context ~= nil and module_context == state.context
            and state.generation == Live.action_generation and state.local_id == local_player_id()
            and Live.remote_same(state.local_id, state.local_identity)
            and Live.remote_same(state.player_id, state.identity)
    end
    local function remote_protection_blocked(snapshot, kind, target_is_local)
        if not snapshot then return true, "The selected player's character is unavailable." end
        if not target_is_local then
            if snapshot.passive then return true, "The selected player is in passive mode." end
            if snapshot.ghost and kind ~= "glitched" and kind ~= "kill" then
                return true, "The selected player is ghosted."
            end
        end
        return false
    end
    local function finish_remote_godmode_clear(reason, expected)
        local s = expected or State.remote_godmode
        if not s or State.remote_godmode ~= s or not s.active then return end
        s.active = false
        local detail, observed
        if reason ~= "completed" then
            s.status = "STOPPED"; detail = tostring(reason)
        elseif s.control ~= true then
            s.status = "NO_AUTHORITY"
            detail = s.control_acquired and "network control was lost before the request completed"
                or "network control was not granted; no damage-state or health request could be applied"
        elseif s.commands_ok ~= true then
            s.status = "COMMAND_FAILED"; detail = "one or more native commands failed"
        elseif s.readback ~= true then
            s.status = "READBACK_UNVERIFIED"; detail = "local damage flags did not match the request"
        elseif s.kind == "kill" then
            if s.death_observed == true then
                observed = true
                s.status = s.target_is_local and "LOCAL_DEATH_OBSERVED" or "REMOTE_LOCAL_DEATH_OBSERVED"
                detail = s.target_is_local and "Death was observed locally" or
                    "Death was observed in your local view; peer-side confirmation is unavailable"
            elseif s.health_attempted then
                s.status = "DEATH_UNVERIFIED"; detail = "The health request was sent; death was not observed"
            else
                s.status = "HEALTH_NOT_SENT"; detail = "No health request was sent before the action ended"
            end
        elseif s.target_is_local then
            s.status = "LOCAL_DAMAGE_FLAGS_OBSERVED"; observed = true
            detail = "Local damage flags matched the request; physical behavior is unverified"
        else
            s.status = "REMOTE_LOCAL_VIEW_ONLY"; observed = true
            detail = "Damage flags matched in your local view; target-side immunity remains unverified"
        end
        toast(remote_godmode_label(s) .. ": " .. detail .. ".", 6500, observed and "info" or "warning")
        log_info(("RemoteProtection kind=%s pid=%s status=%s control=%s commands=%s readback=%s controlRequests=%s healthAttempts=%s healthAccepted=%s deathObserved=%s reason=%s")
            :format(
                tostring(s.kind), tostring(s.player_id), s.status, tostring(s.control), tostring(s.commands_ok),
                tostring(s.readback), tostring(s.control_requests or 0), tostring(s.health_attempts or 0),
                tostring(s.health_command_ok == true), tostring(s.death_observed == true), tostring(reason)))
    end
    local function request_remote_entity_control(state, entity, now)
        if not remote_protection_identity_valid(state) or not Ignore.valid(state.proof) or not entity_exists(entity) then return false end
        if Live.remote_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity) == true then return true end
        if now - (state.control_request_ms[entity] or -100000) >= 100 then
            if not Ignore.valid(state.proof) then return false end
            state.control_request_ms[entity] = now
            state.control_requests = (state.control_requests or 0) + 1
            local _, owner, pending, detail = Live.request_entity_control(local_player_id(), entity,
                function() return Ignore.valid(state.proof) end)
            state.control_owner, state.control_pending, state.control_detail = owner, pending, detail
        end
        return Ignore.valid(state.proof) and Live.remote_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity) == true
    end
    function Live.restore_remote_vehicle_protection(request_control, player_id, only_requested)
        local leases = State.remote_vehicle_protection or {}
        -- OFF targets just this player's CScript-owned leases. Runtime unload
        -- requests all leases; ordinary retry ticks process only marked debts.
        if player_id ~= nil then
            for _, o in pairs(leases) do
                if o.player_id == player_id then o.restore_requested = true end
            end
        elseif only_requested ~= true then
            for _, o in pairs(leases) do o.restore_requested = true end
        end
        if Live.remote_vehicle_restore_busy then
            Live.remote_vehicle_restore_requested = true
            return false
        end
        Live.remote_vehicle_restore_busy = true
        local pending = {}
        for key, o in pairs(leases) do
            if o.restore_requested ~= true then
                pending[key] = o -- keep unrelated active vehicle protection
            elseif o.inflight then
                -- A reentrant reset may run before the native has finished
                -- changing its field. Baseline reads cannot settle that attempt.
                pending[key] = o
            elseif Live.remote_entity_state(o.proof) == "current" and Ignore.valid(o.proof) then
                local entity = o.proof.handle
                local function control()
                    return Ignore.valid(o.proof) and invoke_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity)
                        and Ignore.valid(o.proof)
                end
                if request_control and not control() then
                    Live.request_entity_control(local_player_id(), entity, function() return Ignore.valid(o.proof) end)
                end
                if o.inv_owned and Ignore.valid(o.proof) then
                    local inv = Ignore.read(function() return o.proof.pointer:IsInvincible() end)
                    if inv == true and control() then
                        o.inflight = true
                        pcall(Live.remote_write_field, o.proof, "invincible", o.invincible, true,
                            function() return Ignore.valid(o.proof) end)
                        o.inflight = false
                        if Ignore.valid(o.proof) then inv = Ignore.read(function() return o.proof.pointer:IsInvincible() end) else inv = nil end
                    end
                    if inv ~= nil and inv ~= true then o.inv_owned = false end
                end
                if o.damage_owned and Ignore.valid(o.proof) then
                    local value = Ignore.query(o.proof, "bool", H.GET_ENTITY_CAN_BE_DAMAGED, entity)
                    if value == false and control() then
                        o.inflight = true
                        pcall(Live.remote_write_field, o.proof, "damageable", o.damageable, false,
                            function() return Ignore.valid(o.proof) end)
                        o.inflight = false
                        value = Ignore.query(o.proof, "bool", H.GET_ENTITY_CAN_BE_DAMAGED, entity)
                    end
                    if value ~= nil and value ~= false then o.damage_owned = false end
                end
                if o.inv_owned or o.damage_owned then pending[key] = o end
            elseif Live.remote_entity_state(o.proof) ~= "retired" then
                pending[key] = o -- unknown identity/readback is still an obligation
            end
        end
        State.remote_vehicle_protection = pending
        -- Other players may legitimately retain active CScript grants.
        -- Only unfinished restoration requests are retry debt.
        local requested_pending = false
        for _, o in pairs(pending) do
            if o.restore_requested == true then requested_pending = true; break end
        end
        Live.remote_vehicle_restore_requested = requested_pending
        Live.remote_vehicle_restore_busy = false
        return not requested_pending
    end

    local function tick_remote_godmode_clear(now)
        local s = State.remote_godmode
        if not s or not s.active then return end
        now = tonumber(now) or now_ms()
        if now - (s.last_apply_ms or -100000) < 50 then return end
        s.last_apply_ms = now
        if not remote_protection_identity_valid(s) then
            s.control, s.commands_ok, s.readback = false, false, false
            finish_remote_godmode_clear("player or session connection changed", s); return
        end
        for _, key in ipairs(s.local_clear_keys or {}) do
            if is_on(key) then
                finish_remote_godmode_clear("a local protection was re-enabled", s); return
            end
        end
        local snapshot = player_snapshot(s.player_id)
        if not player_available(s.player_id) or not snapshot or snapshot.ped ~= s.ped
            or (s.target_is_local and snapshot.ped ~= local_ped())
            or remote_protection_blocked(snapshot, s.kind, s.target_is_local) or not Ignore.valid(s.proof)
            or (s.vehicle ~= 0 and snapshot.vehicle ~= s.vehicle) then
            finish_remote_godmode_clear("target changed", s); return
        end
        local entity = s.proof.handle
        if not s.control_acquired and now >= s.until_ms then
            finish_remote_godmode_clear("completed", s); return
        end
        s.control = request_remote_entity_control(s, entity, now)
        if s.control and not s.control_acquired then
            s.control_acquired = true
            s.until_ms = math.min(tonumber(s.overall_until_ms) or s.until_ms, now + 1800)
        end
        s.commands_ok, s.readback = false, false
        if s.control and Ignore.valid(s.proof) then
            local grant = s.kind == "vehicle_grant"
            local grant_owner
            local function write(hash, ...)
                if Live.remote_write_inflight or not Ignore.valid(s.proof) or Live.remote_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity) ~= true then return false end
                if not Ignore.valid(s.proof) then return false end
                local arguments = table.pack(...)
                if grant_owner and hash == H.SET_ENTITY_INVINCIBLE then
                    local flags = Live.read_remote_proofs(s.proof, function() return Ignore.valid(s.proof) end)
                    if not flags or not Ignore.valid(s.proof) or Live.remote_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity) ~= true
                        or not Ignore.valid(s.proof) then
                        return false
                    end
                    arguments[3] = flags[7] -- preserve dontResetOnCleanup
                end
                -- A native can change the field before returning failure.
                -- Arm ownership before entering the host, including callbacks
                -- which request restoration before its mutation has finished.
                if grant_owner then
                    if grant_owner.inflight then return false end
                    if hash == H.SET_ENTITY_INVINCIBLE and not grant_owner.invincible then grant_owner.inv_owned = true end
                    if hash == H.SET_ENTITY_CAN_BE_DAMAGED and grant_owner.damageable then grant_owner.damage_owned = true end
                    grant_owner.inflight = true
                end
                Live.remote_write_inflight = true
                local invoked, result = pcall(invoke_void, hash, table.unpack(arguments, 1, arguments.n))
                Live.remote_write_inflight = false
                if grant_owner then grant_owner.inflight = false end
                return invoked and result, true
            end
            local existing = State.remote_vehicle_protection and State.remote_vehicle_protection[s.proof.address]
            if s.vehicle ~= 0 and existing and existing.inflight then
                if now >= s.until_ms then finish_remote_godmode_clear("vehicle protection mutation is pending", s) end
                return
            end
            if grant then
                State.remote_vehicle_protection = State.remote_vehicle_protection or {}
                local key = s.proof.address
                if State.remote_vehicle_protection[key] then
                    local old = State.remote_vehicle_protection[key]
                    local old_state = Live.remote_entity_state(old.proof)
                    if old_state == "retired" then
                        State.remote_vehicle_protection[key] = nil
                    elseif old_state ~= "current" or not Ignore.valid(old.proof) then
                        if now >= s.until_ms then
                            finish_remote_godmode_clear(
                                "vehicle protection restoration is pending", s)
                        end
                        return -- Unknown proof cannot erase the earlier baseline.
                    end
                end
                if not State.remote_vehicle_protection[key] then
                    if not Ignore.valid(s.proof) then
                        finish_remote_godmode_clear("target changed", s); return
                    end
                    local ok, inv = pcall(function() return s.proof.pointer:IsInvincible() end)
                    local damageable = Ignore.query(s.proof, "bool", H.GET_ENTITY_CAN_BE_DAMAGED, entity)
                    if not Ignore.valid(s.proof) or not ok or type(inv) ~= "boolean" or damageable == nil then
                        finish_remote_godmode_clear("baseline unavailable", s); return
                    end
                    -- Cleanup belongs to the entity we protected, even if its
                    -- occupant disconnects or a new connection cancels this action.
                    local context = module_context
                    local restore_proof = Ignore.proof(s.proof.pointer,
                        function() return module_context ~= nil and module_context == context end, entity)
                    if not restore_proof or not Ignore.valid(s.proof) then
                        finish_remote_godmode_clear("baseline unavailable", s); return
                    end
                    restore_proof.remote_context = context
                    State.remote_vehicle_protection[key] = {
                        proof = restore_proof,
                        player_id = s.player_id,
                        identity = s.identity,
                        vehicle = s.vehicle,
                        invincible = inv,
                        damageable = damageable
                    }
                end
            end
            grant_owner = grant and State.remote_vehicle_protection[s.proof.address]
            local ok = write(H.SET_ENTITY_INVINCIBLE, entity, grant, false)
            local damage_ok = write(H.SET_ENTITY_CAN_BE_DAMAGED, entity, not grant)
            ok = damage_ok and ok
            if not grant then
                ok = write(H.SET_ENTITY_PROOFS, entity, false, false, false, false, false, false, false, false) and ok
                if s.vehicle == 0 then
                    ok = write(H.SET_PLAYER_INVINCIBLE, s.player_id, false) and ok
                    ok = write(0x6BC97F4F4BB3C04B, s.player_id, false) and ok -- reaction invincibility
                    ok = write(H.SET_PED_CAN_BE_TARGETTED, entity, true) and ok
                end
                if s.kind == "glitched" or s.kind == "kill" then
                    ok = write(H.SET_PED_CAN_RAGDOLL, entity, true) and ok
                    ok = write(0x1A9205C1B9EE827F, entity, true, true) and ok -- SET_ENTITY_COLLISION
                    ok = write(H.SET_PED_SUFFERS_CRITICAL_HITS, entity, true) and ok
                end
            end
            s.commands_ok = ok
            local inv_ok, inv = false, nil
            if Ignore.valid(s.proof) then inv_ok, inv = pcall(function() return s.proof.pointer:IsInvincible() end) end
            local damageable = Ignore.query(s.proof, "bool", H.GET_ENTITY_CAN_BE_DAMAGED, entity)
            local proof_bits = not grant and
                Live.read_remote_proofs(s.proof, function() return Ignore.valid(s.proof) end) or
                nil
            local proofs_clear = grant
            if not grant and proof_bits then
                proofs_clear = true
                for index = 1, 8 do if proof_bits[index] ~= false then proofs_clear = false end end
            end
            local physical_clear = true
            if s.kind == "glitched" or s.kind == "kill" then
                physical_clear = Ignore.query(s.proof, "bool", H.GET_PED_CONFIG_FLAG, entity, 2, true) == false
                    and Ignore.query(s.proof, "bool", 0x128F79EDCECE4FD5, entity) == true
                    and Ignore.query(s.proof, "bool", 0xCCF1E97BEFDAE480, entity) == false
            end
            s.control = Ignore.valid(s.proof) and Live.remote_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity) == true
            s.readback = s.control and Ignore.valid(s.proof) and inv_ok and inv == grant and damageable == not grant
                and proofs_clear and physical_clear
            if s.kind == "kill" then
                local function observe_death()
                    local dead = Ignore.query(s.proof, "bool", 0x5F9532F3B5CC2551, entity, false)
                    local health = Ignore.query(s.proof, "int", 0xEEF059FAD016D209, entity)
                    s.control = Ignore.valid(s.proof) and Live.remote_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity) ==
                        true
                    s.death_observed = s.control and Ignore.valid(s.proof) and dead == true and type(health) == "number" and
                        health <= 0
                end
                if s.health_attempted then observe_death() end
                if s.readback and s.commands_ok and not s.health_command_ok and not s.death_observed
                    and not s.health_inflight and (s.health_attempts or 0) < 3
                    and now < s.until_ms and now < (s.overall_until_ms or s.until_ms)
                    and now - (s.health_request_ms or -100000) >= 250 then
                    s.health_request_ms = now; s.health_inflight = true
                    -- A skipped guard consumes cadence, not a native attempt.
                    -- Preserve the documented entity, health, instigator, weapon ABI.
                    local accepted, entered = write(0x6B76DC1F3AE6E6A3, entity, 0, 0, 0)
                    s.health_inflight = false
                    s.health_command_ok = accepted == true
                    if entered then
                        s.health_attempted = true; s.health_attempts = (s.health_attempts or 0) + 1
                        observe_death()
                    end
                    s.commands_ok = s.commands_ok and s.health_command_ok
                end
                if s.health_attempted then s.commands_ok = s.commands_ok and s.health_command_ok end
            end
            -- Explicit removal releases an owned grant only after every damage
            -- fields are observed clear. Cancelled or partial attempts keep debt.
            if s.kind == "vehicle" and existing and s.readback and not existing.inflight
                and Ignore.valid(existing.proof) and Ignore.valid(s.proof)
                and State.remote_vehicle_protection and State.remote_vehicle_protection[s.proof.address] == existing then
                State.remote_vehicle_protection[s.proof.address] = nil
            end
        end
        if s.kind == "kill" and s.death_observed or now >= s.until_ms then finish_remote_godmode_clear("completed", s) end
    end
    local function start_remote_godmode_clear(player_id, kind)
        local startup = {}
        Live.remote_protection_startup = startup
        local previous = State.remote_godmode
        player_id = Live.remote_player_index(player_id)
        if not player_id or not player_available(player_id) then
            toast("Select an available player."); return false
        end
        local target_is_local = player_id == local_player_id()
        if kind == "vehicle_grant" and Live.remote_vehicle_restore_requested then
            toast("Vehicle protection restoration is pending."); return false
        end
        if remote_guard44 and remote_guard44.Snapshot().player_id == player_id and kind ~= "vehicle_grant" and kind ~= "vehicle" then
            Live.remote_guard_cancel("Protection removal requested.", false, player_id)
            Live.remote_guard_tick(now_ms(), false)
            if not remote_guard44.CanHandoff() then
                toast("Remote protection restoration is pending."); return false
            end
        end
        local snapshot = player_snapshot(player_id)
        if kind == "kill" then
            local dead = snapshot and Live.remote_bool(0x5F9532F3B5CC2551, snapshot.ped, false)
            if dead ~= false then
                toast(dead == true and "The selected character is already dead." or
                    "The selected character could not be verified."); return false
            end
        end
        local blocked, blocked_reason = remote_protection_blocked(snapshot, kind, target_is_local)
        if blocked then
            toast(blocked_reason); return false
        end
        if target_is_local and snapshot.ped ~= local_ped() then
            toast("Your character changed before the action."); return false
        end
        local vehicle = (kind == "vehicle" or kind == "vehicle_grant") and snapshot.vehicle or 0
        local entity = vehicle ~= 0 and vehicle or snapshot.ped
        if (kind == "vehicle" or kind == "vehicle_grant") and not entity_exists(vehicle) then
            toast("Selected player has no streamed vehicle."); return false
        end
        local local_id = local_player_id()
        local identity, local_identity = Live.remote_identity(player_id), Live.remote_identity(local_id)
        if not identity or not local_identity then
            toast("Player connection identity is unavailable; nothing was applied."); return false
        end
        local request = {
            player_id = player_id,
            local_id = local_id,
            identity = identity,
            local_identity = local_identity,
            generation = Live.action_generation,
            context = module_context,
            local_clear_keys = {},
            initializing = true,
            active = false
        }
        local function owns_request()
            if request.initializing then
                return Live.remote_protection_startup == startup and State.remote_godmode == previous
            end
            return request.active and State.remote_godmode == request
        end
        local pointer = Ignore.read(function() return gta.HandleToPointer(entity) end)
        local proof = pointer and Ignore.proof(pointer, function()
            if not owns_request() or not remote_protection_identity_valid(request) then return false end
            for _, key in ipairs(request.local_clear_keys) do if is_on(key) then return false end end
            return owns_request()
        end, entity)
        if not proof then
            toast("The target entity could not be verified."); return false
        end
        local local_clear_keys = {}
        if target_is_local and (kind == "glitched" or kind == "player" or kind == "kill") then
            local_clear_keys = (kind == "glitched" or kind == "kill") and { "godmode", "no_ragdoll", "no_critical_hits" } or
                { "godmode" }
            local changed = {}
            for _, key in ipairs(local_clear_keys) do
                if not Ignore.valid(proof) then return false end
                if is_on(key) then
                    if not set_toggle(key, false) then
                        for _, prior in ipairs(changed) do if not is_on(prior) then set_toggle(prior, true) end end
                        toast("Could not release CScript's local protection; nothing was applied."); return false
                    end
                    changed[#changed + 1] = key
                end
            end
        end
        -- Self removal is explicit intent, but a later toggle must win over it.
        -- Remote targets and vehicle actions never change local survival options.
        local now = now_ms()
        if not Ignore.valid(proof) then return false end
        request.active, request.kind, request.ped, request.vehicle = true, kind, snapshot.ped, vehicle
        request.target_is_local, request.local_clear_keys = target_is_local, local_clear_keys
        request.proof, request.until_ms, request.last_apply_ms = proof, now + 4000, -100000
        request.overall_until_ms, request.control_acquired = now + 5800, false
        request.control_request_ms, request.control_requests = {}, 0
        request.initializing = false
        if previous then previous.active = false end
        State.remote_godmode = request
        tick_remote_godmode_clear(now)
        return true
    end

    -- Shared with the later interior-exit decoder; preserve its original ABI.
    local function u32(value)
        return (tonumber(value) or 0) & 0xFFFFFFFF
    end

    -- General remote state actions use exact player-bound providers.
    -- The separate Ghosted-to-You controller owns only our broadcast slot;
    -- a local remote-player ghost native cannot clear peer-owned state.
    function Live.remote_player_index(player_id)
        player_id = tonumber(player_id)
        if not player_id or player_id ~= player_id or player_id < 0 or player_id > 31
            or player_id % 1 ~= 0 then
            return nil
        end
        return player_id
    end

    Live.setpiece_keys = {
        fling_player = true,
        hammer_of_god = true,
        demonic_possession = true,
        cargo_guillotine = true,
        kamikaze_jet = true,
        ghost_vehicle = true,
    }
    -- BEGIN BALLER57 PLAYER ADAPTER
    Live.baller_toggle_refs = {}
    Live.baller_toggle_syncing = {}
    Live.baller_toggle_epoch = 0
    Live.baller_armed = false

    function Live.clear_baller_toggle(feature)
        if feature == nil or Live.baller_toggle_syncing[feature] then return false end
        Live.baller_toggle_syncing[feature] = true
        local ok = pcall(function()
            if feature:IsToggled() then feature:Toggle(false) end
        end)
        Live.baller_toggle_syncing[feature] = nil
        return ok
    end

    function Live.report_baller_failure(kind, reason)
        local message='Baller '..tostring(kind)..': '..tostring(reason or 'Unknown failure')
        -- Retain the full reason before presentation shortening; no player data.
        local raw=module_context and module_context.Raw
        local files=raw and raw.FileMgr
        if files and type(files.GetMenuRootPath)=='function' and type(files.WriteFileContent)=='function' then
            pcall(function()
                local root=tostring(files.GetMenuRootPath()):gsub('[/\\]+$','')
                files.WriteFileContent(root..'\\Lua\\CScript_Baller_LastError.txt',message,false)
            end)
        end
        pcall(toast,message,9000,'info')
    end

    function Live.on_baller_disabled(pid, reason)
        if reason and reason~='disabled' and reason~='unloading' and reason~='cleanup requested' then
            Live.report_baller_failure('stopped',reason)
        end
        local feature = Live.baller_toggle_refs[pid]
        local effect = Live.vehicle_chaos
        if feature and (not effect or not effect.BallerEnabled(pid)) then
            Live.baller_toggle_refs[pid] = nil
            Live.clear_baller_toggle(feature)
        end
    end

    function Live.cancel_baller_toggle(reason, disarm)
        local was_armed = Live.baller_armed
        Live.baller_armed = false
        Live.baller_toggle_epoch = Live.baller_toggle_epoch + 1
        local epoch = Live.baller_toggle_epoch
        local refs = Live.baller_toggle_refs
        Live.baller_toggle_refs = {}
        local effect = Live.vehicle_chaos
        for pid, feature in pairs(refs) do
            if effect and type(effect.SetBallerEnabled) == "function" then
                pcall(effect.SetBallerEnabled, pid, false)
            end
            Live.clear_baller_toggle(feature)
        end
        if not disarm and epoch == Live.baller_toggle_epoch then
            Live.baller_armed = was_armed
        end
    end

    function Live.rearm_baller_toggle()
        Live.baller_armed = false
        if not started or not lifecycle_token or lifecycle_token.alive ~= true then
            return false, "Player runtime is not ready."
        end
        Live.baller_armed = true
        return true
    end

    function Live.set_baller_toggle(feature)
        if feature == nil or Live.baller_toggle_syncing[feature] then return false end
        local ok, pid, enabled = pcall(function()
            return feature:GetPlayerIndex(), feature:IsToggled()
        end)
        if not ok or type(pid) ~= "number" or pid % 1 ~= 0 or pid < 0 or pid > 31
            or type(enabled) ~= "boolean" then
            Live.clear_baller_toggle(feature)
            return false
        end
        local effect = Live.vehicle_chaos
        if not enabled then
            -- A callback retained by a replaced feature instance cannot disable
            -- the current instance's intent for this same player slot.
            local current = Live.baller_toggle_refs[pid]
            if current and current ~= feature then return true end
            Live.baller_toggle_epoch = Live.baller_toggle_epoch + 1
            Live.baller_toggle_refs[pid] = nil
            if effect and type(effect.SetBallerEnabled) == "function" then
                local called, accepted, why = pcall(effect.SetBallerEnabled, pid, false)
                if not called or not accepted then return false, why end
            end
            return true
        end
        if not Live.baller_armed or not started or not lifecycle_token or lifecycle_token.alive ~= true then
            Live.clear_baller_toggle(feature)
            return false
        end
        local available, reason = Live.selected_action_availability("character_baller", pid)
        if not available then
            Live.clear_baller_toggle(feature)
            Live.report_baller_failure('blocked',reason or 'Selected player unavailable')
            return false, reason
        end
        local why
        effect, why = Live.ensure_vehicle_chaos()
        if not effect or type(effect.SetBallerEnabled) ~= "function" or type(effect.BallerEnabled) ~= "function" then
            Live.clear_baller_toggle(feature)
            Live.report_baller_failure('blocked',why or 'Baller toggle is unavailable.')
            return false, why or "Baller toggle is unavailable."
        end
        Live.baller_toggle_epoch = Live.baller_toggle_epoch + 1
        local epoch = Live.baller_toggle_epoch
        local called, accepted, detail = pcall(effect.SetBallerEnabled, pid, true)
        if not called or not accepted or epoch ~= Live.baller_toggle_epoch or not effect.BallerEnabled(pid) then
            Live.clear_baller_toggle(feature)
            local failure=not called and accepted or detail or 'Scene setup was interrupted'
            Live.report_baller_failure('blocked',failure)
            return false, failure
        end
        local previous = Live.baller_toggle_refs[pid]
        Live.baller_toggle_refs[pid] = feature
        if previous and previous ~= feature then Live.clear_baller_toggle(previous) end
        return true
    end

    -- END BALLER57 PLAYER ADAPTER

    function Live.ensure_vehicle_chaos()
        if Live.vehicle_chaos then return Live.vehicle_chaos end
        local effect = module_context and module_context.Modules and module_context.Modules.VehicleChaos
        if type(effect) ~= "table" or type(effect.New) ~= "function" then
            return nil,
                "Vehicle effect module is unavailable."
        end
        local effect_host = {}
        for key, value in pairs(module_context.Raw) do effect_host[key] = value end
        effect_host.session_key = function() return Live.action_generation end
        effect_host.OnBallerDisabled = Live.on_baller_disabled
        -- Read-only intent, not a movement native: Auto-tp owns local positioning.
        effect_host.auto_tp_requested = function()
            return Live.auto_tp ~= nil and Live.auto_tp.Requested() == true
        end
        effect_host.auto_tp_handoff_ready = function()
            local controller = Live.auto_tp
            if not controller or not controller.Requested() then return false end
            local pid = controller.Target()
            local ok, ready = pcall(function()
                local remote = Live.Players.GetCPed(pid)
                if not remote then return false end
                local handle = gta.PointerToHandle(remote)
                if type(handle) ~= "number" or handle<=0 then return false end
                local valid, dead = module_context.Natives.Try("bool",0x5F9532F3B5CC2551,handle,false)
                return valid and (dead==false or dead==0)
            end)
            return ok and ready == true
        end
        Live.vehicle_chaos = effect.New(effect_host)
        return Live.vehicle_chaos
    end

    function Live.spawn_action_status(effect_key)
        local status=Live.vehicle_chaos and Live.vehicle_chaos.Status(effect_key) or {phase="idle",blocked=false}
        local key=({["Tug Pair"]="tug_pair",["Avisa"]="trevor_michael",["Kraken"]="pistol_circle",
            ["Ruiner Pimp"]="ruiner_pimp",["Baller"]="character_baller",["Vehicle Circle"]="vehicle_circle"})[status.name]
        local label=key and selected_feature_labels[key]
        if label then
            local copy={};for k,v in pairs(status)do copy[k]=v end
            copy.name=label;return copy
        end
        return status
    end

    function Live.selected_action_availability(key, player_id)
        if key=="auto_tp" and Live.auto_tp and Live.auto_tp.Target()==player_id then return true end
        if key == "tear_gas_trap" and Live.player_setpieces
            and Live.player_setpieces.IsEnabled("tear_gas_trap", player_id) then
            return true
        end
        if key == "character_baller" and Live.vehicle_chaos
            and Live.vehicle_chaos.BallerEnabled(player_id) then
            return true
        end
        local screen_kind = Live.scripted_screen_kinds and Live.scripted_screen_kinds[key]
        if screen_kind and Live.scripted_screen_repeats
            and Live.scripted_screen_repeats.IsEnabled(player_id, screen_kind) then
            return true
        end
        player_id = Live.remote_player_index(player_id)
        if player_id == nil or not player_available(player_id) then return false, "Select an available player." end
        if key == "tear_gas_trap" then
            if not Live.tear_gas_armed or not started or not lifecycle_token
                or lifecycle_token.alive ~= true or State.runtime_writes_suspended == true then
                return false, "Gas chamber trap is waiting for the player runtime."
            end
            if Live.player_setpieces and type(Live.player_setpieces.Available) == "function" then
                return Live.player_setpieces.Available("tear_gas_trap", player_id)
            end
            return true
        end
        if key == "character_baller" then
            if player_id == local_player_id() then return false, "Select another player for this effect." end
            return true
        end
        if screen_kind then
            if not Live.scripted_screen_repeats then return false, "Scripted screens are unavailable." end
            return true
        end
        local effect_key = key == "penis" or key == "tug_pair" or key == "cargoplane_pile" or key == "ruiner_pimp" or key == "vehicle_circle" or
            key == "trevor_michael" or
            key == "pistol_circle" or key == "character_baller"
            or tostring(key):match("^vehicle_variant_[1-4]$")
        if effect_key then
            if effect_key and player_id == local_player_id() then return false, "Select another player for this effect." end
            local status = Live.spawn_action_status(key)
            -- Button admission is handled by the vehicle module. Its single-worker
            -- queue can replace the current effect while preserving cleanup debt;
            -- UI must not hide the replacement action during another run.
        end
        if player_id ~= local_player_id() then return true end
        local remote_only = {
            penis = "Select another player for this vehicle effect.",
            ruiner_pimp = "Select another player for this vehicle effect.",
            join_organization = "You cannot join yourself. Select another CEO / MC.",
            kick_from_organization = "This is a remote dismissal action. Use Leave or Retire for your own organization.",
            enter_interior = "This action joins another player's interior. Select its occupant.",
            kick_from_interior = "This is a remote interior-exit action. Use the normal exit for your own interior.",
        }
        if remote_only[key] then return false, remote_only[key] end
        return true
    end

    function Live.remote_ghost_readback(ped)
        if not entity_exists(ped) then return nil end
        local value, raw, err = invoke_bool_detail(H.IS_ENTITY_A_GHOST, ped)
        if err ~= nil or (type(raw) ~= "boolean" and type(raw) ~= "number") then return nil end
        return value
    end

    function Live.remote_identity(player_id)
        if not player_available(player_id) then return nil end
        local ok, identity = pcall(function()
            local p = Live.Players and Live.Players.GetById(player_id)
            if not p then return nil end
            local info = p:GetGamerInfo()
            local rid = info and info.RockstarId
            local cxn = p.CxnId
            if rid == nil or tostring(rid) == "0" or tostring(rid) == ""
                or type(cxn) ~= "number" or cxn ~= cxn or cxn % 1 ~= 0 then
                return nil
            end
            return { rid = tostring(rid), cxn = cxn, local_id = local_player_id() }
        end)
        return ok and identity or nil
    end

    function Live.remote_same(player_id, identity)
        if not started or not identity then return false end
        local now = Live.remote_identity(player_id)
        return now ~= nil and now.rid == identity.rid and now.cxn == identity.cxn
            and now.local_id == identity.local_id
    end

    function Live.stop_auto_tp(reason)
        if Live.auto_tp then Live.auto_tp.Cancel(reason or "Auto-tp stopped")end
    end
    function Live.get_auto_tp()
        if Live.auto_tp then return Live.auto_tp end
        Live.auto_tp=Module.NewAutoTeleportController({
            Try=function(kind,hash,...)return module_context.Natives.Try(kind,hash,...)end,
            Running=function()return started and bound and lifecycle_token and lifecycle_token.alive==true
                and State.runtime_writes_suspended~=true end,
            LocalPlayer=local_player_id,LocalPed=local_ped,Identity=Live.remote_identity,
            Session=function()return Live.action_generation end,
            Address=function(handle)local e=gta.HandleToPointer(handle);return e and e:GetAddress()end,
            Available=function()
                local status=Live.vehicle_chaos and Live.vehicle_chaos.Status()
                if status and status.returning then return false,"Waiting for local vehicle-effect return"end
                if Live.local_exit.Requested() or State.enter_interior and State.enter_interior.active then
                    return false,"Waiting for the current local interior trip"
                end
                local teleports=module_context.State and module_context.State.Teleports
                local result=teleports and teleports.last_destination_result
                if teleports and (teleports.pending_destination or teleports.cargo_request)
                    or result and (result.status=="PENDING" or result.status=="CLEANUP_PENDING")then
                    return false,"Waiting for the current CScript teleport"
                end
                local vehicle=module_context.CScript and module_context.CScript.Vehicle
                local fly=vehicle and vehicle.VehicleFlySnapshot and vehicle.VehicleFlySnapshot()
                if fly and fly.status=="ACTIVE" and (fly.vehicle or 0)>0 then
                    return false,"Waiting while Vehicle Fly owns the local vehicle"
                end
                return true
            end,
            Stopped=function(pid,owner,reason)
                if Live.auto_tp_feature==owner then
                    Live.auto_tp_feature=nil;Live.auto_tp_syncing=true
                    pcall(function()if owner:IsToggled()then owner:Toggle(false)end end)
                    Live.auto_tp_syncing=false
                end
                if reason and reason~="Off" and reason~="Disabled" then
                    log_info("Auto-tp: "..tostring(reason))
                end
            end,
        })
        return Live.auto_tp
    end

    Live.REMOTE_ACTION_NAMES = {
        -- Blocking future admission does not exit an already passive player.
        passive = { ["remove passive"] = true, ["remove passive mode"] = true },
        ghost = {
            ["remove ghost"] = true,
            ["remove ghost mode"] = true,
            ["remove ghosted state"] = true,
            ["remove ghost state"] = true,
            ["remove ghosting"] = true
        },
        interior_enter = { ["enter interior"] = true, ["enter player interior"] = true },
        interior_kick = { ["kick from interior"] = true, ["kick from apartment"] = true },
    }

    function Live.remote_action_info(feature, player_id, kind)
        -- Feature userdata exposes invalid typed methods; inspect type FIRST.
        local ok, info = pcall(function()
            if not feature or feature:GetType() ~= feature_type.Button then return nil end
            if feature:IsPlayerFeature() ~= true or feature:GetPlayerIndex() ~= player_id then return nil end
            local hash, serial = feature:GetHash(), feature:GetId()
            if type(hash) ~= "number" or type(serial) ~= "number" then return nil end
            if Live.owned_player_hashes and Live.owned_player_hashes[hash] then return nil end
            for _, own in pairs(PF_ID) do if own == hash then return nil end end
            local name = feature:GetName(false)
            if type(name) ~= "string" then return nil end
            local clean = name:lower():gsub("~[^~]*~", ""):gsub("[^%w]+", " ")
                :gsub("^%s+", ""):gsub("%s+$", "")
            clean = clean:gsub("^vibescript ", ""):gsub("^vibe script ", "")
            if not Live.REMOTE_ACTION_NAMES[kind][clean] then return nil end
            if type(feature.OnClick) ~= "function" then return nil end
            return { feature = feature, hash = hash, serial = serial, name = name, action_name = clean }
        end)
        return ok and info or nil
    end

    function Live.remote_resolve(hash, player_id, kind)
        if Live.owned_player_hashes and Live.owned_player_hashes[hash] then return nil end
        local ok, feature = pcall(feature_mgr.GetFeature, hash, player_id)
        local info = ok and Live.remote_action_info(feature, player_id, kind) or nil
        if info then
            info.lookup_hash = hash; info.lookup_index = player_id; return info
        end
        -- Some registries enumerate instance hashes instead of base array hashes.
        -- A direct lookup is accepted ONLY after its player index matches too.
        ok, feature = pcall(feature_mgr.GetFeature, hash)
        info = ok and Live.remote_action_info(feature, player_id, kind) or nil
        if info then
            info.lookup_hash = hash; return info
        end
        return nil
    end

    function Live.remote_find_provider(player_id, kind)
        if type(feature_mgr.GetFeature) ~= "function" then
            return nil, "Cherax player-feature registry is unavailable"
        end
        local registries = {}
        for _, name in ipairs({ "GetAllPlayerFeatureHashes", "GetAllFeatureHashes" }) do
            if type(feature_mgr[name]) == "function" then
                local ok, hashes
                if name == "GetAllPlayerFeatureHashes" then
                    ok, hashes = pcall(feature_mgr[name], player_id)
                else
                    ok, hashes = pcall(feature_mgr[name])
                end
                if not ok or (type(hashes) ~= "table" and type(hashes) ~= "userdata") then
                    return nil, "feature registry could not be read"
                end
                registries[#registries + 1] = hashes
            end
        end
        if #registries == 0 then return nil, "Cherax feature registry is unavailable" end
        local count, candidates, seen = 0, {}, {}
        -- On-click only. No per-frame feature search, fuzzy name match, global
        -- selection mutation, guessed hash or subscription/source extraction.
        local complete, iteration_error = pcall(function()
            for _, hashes in ipairs(registries) do
                for _, hash in pairs(hashes) do
                    count = count + 1
                    if count > 32768 then error("feature registry exceeded its bounded scan") end
                    if type(hash) == "number" and hash == hash and hash % 1 == 0 then
                        local info = Live.remote_resolve(hash, player_id, kind)
                        if info and not seen[info.serial] then
                            seen[info.serial] = true
                            candidates[#candidates + 1] = info
                        end
                    end
                end
            end
        end)
        if not complete then return nil, "player-feature iteration failed: " .. tostring(iteration_error) end
        if #candidates == 0 then
            return nil, "no matching player-bound " .. tostring(kind) .. " button is exposed by the loaded scripts"
        end
        if #candidates ~= 1 then return nil, "multiple matching external actions; no ambiguous callback was run" end
        return candidates[1]
    end

    function Live.remote_state(kind)
        return kind == "passive" and State.remote_passive or State.remote_ghost
    end

    function Live.remote_finish(kind, reason, quiet)
        local state = Live.remote_state(kind)
        if not state or not state.active then return end
        state.active = false
        state.status = reason == "completed" and "DISPATCHED_UNVERIFIED" or "STOPPED"
        -- Explicit nil/false handling: a false observation is NOT a failed read.
        local observed
        if kind == "passive" then observed = state.passive_after else observed = state.ghost_after end
        log_info(("RemoteState kind=%s target=%s pid=%d status=%s provider=%s hash=%s incomingUpdates=%d observed=%s globalGhost=%s pairGhost=%s pairMask=%s scope=external-player-action localWrites=0")
            :format(kind, state.player_name, state.player_id, state.status, state.provider_name,
                tostring(state.provider_hash), state.node_updates, tostring(observed),
                tostring(state.ghost_global_after), tostring(state.ghost_pair_after), tostring(state.ghost_pair_mask)))
        if quiet ~= true then
            local detail = " No matching incoming state update was received."
            if state.node_updates > 0 then
                if kind == "passive" then
                    detail = " Latest incoming passive flag: " .. tostring(observed) .. "."
                else
                    local function flag_text(value)
                        if value == nil then return "unknown" end
                        return value and "active" or "clear"
                    end
                    detail = " Incoming ghost state: general " .. flag_text(state.ghost_global_after)
                        .. ", with you " .. flag_text(state.ghost_pair_after) .. "."
                end
            end
            toast(("%s was dispatched for %s.%s Target-side removal is not verified.")
                :format(state.provider_name, state.player_name, detail), 6500, "info")
        end
    end

    function Live.remote_tick(kind, now)
        local state = Live.remote_state(kind)
        if not state or not state.active then return end
        now = tonumber(now) or now_ms()
        if not Live.remote_same(state.player_id, state.identity) then
            Live.remote_finish(kind, "target/session identity changed", true); return
        end
        if now >= state.until_ms then
            Live.remote_finish(kind, "completed"); return
        end
        -- Observe only; never repeat the external command or overwrite its data.
    end

    function Live.remote_dispatch(kind, player_id)
        -- Hold the guard across host metadata reads as well as OnClick: those
        -- reads can reenter Lua before a request has been published to State.
        if Live.remote_dispatching then return false end
        local token, pending = {}, nil
        Live.remote_dispatching = token
        local completed, result = pcall(function()
            local previous = Live.remote_state(kind)
            player_id = Live.remote_player_index(player_id)
            if not started or not player_id or not player_available(player_id) then
                toast("Select an available player; no state action was sent.", 5000, "warning"); return false
            end
            -- A self-selected action still requires the exact external provider
            -- positioned to that index. Do not change selection or invent a state clear.
            if previous and previous.active then
                toast("The previous state action is still awaiting observation; no duplicate action was sent.", 4500,
                    "info")
                return false
            end
            local identity = Live.remote_identity(player_id)
            if not identity then
                toast("Selected-player connection identity is unavailable; no action was sent.", 6000, "warning"); return false
            end
            local provider, why = Live.remote_find_provider(player_id, kind)
            if not provider then
                log_info("RemoteState status=UNAVAILABLE kind=" ..
                    kind .. " pid=" .. player_id .. " reason=" .. tostring(why) .. " localWrites=0")
                toast(
                    "Remove " ..
                    (kind == "passive" and "Passive" or "Ghost") ..
                    ": " .. tostring(why) .. ". No local-only substitute was applied.", 8500, "warning")
                return false
            end
            if not Live.remote_same(player_id, identity) then return false end
            -- Resolve display/timing metadata before the final provider and
            -- connection checks; no metadata getter may follow those checks.
            local now, target_name = now_ms(), player_name(player_id)
            -- Re-resolve by exactly the same lookup, then recheck type, creation
            -- identity and player index immediately before the dispatch boundary.
            local ok, fresh
            if provider.lookup_index == nil then
                ok, fresh = pcall(feature_mgr.GetFeature, provider.lookup_hash)
            else
                ok, fresh = pcall(feature_mgr.GetFeature, provider.lookup_hash, provider.lookup_index)
            end
            local checked = ok and Live.remote_action_info(fresh, player_id, kind) or nil
            if not checked or checked.serial ~= provider.serial or checked.hash ~= provider.hash
                or checked.action_name ~= provider.action_name
                or not Live.remote_same(player_id, identity)
                or not started or Live.remote_dispatching ~= token
                or Live.remote_state(kind) ~= previous then
                log_info("RemoteState status=CONTEXT_REJECTED kind=" .. kind .. " pid=" .. player_id
                    .. " lookup=" .. tostring(ok) .. " provider=" .. tostring(checked ~= nil))
                toast("The target or action changed before dispatch; nothing was sent.", 5500, "warning"); return false
            end
            local state = {
                active = true,
                kind = kind,
                player_id = player_id,
                player_name = target_name,
                identity = identity,
                started_ms = now,
                until_ms = now + 5000,
                node_updates = 0,
                provider_name = checked.name,
                provider_hash = checked.hash,
                status = "DISPATCHING",
                passive_after = nil,
                ghost_after = nil,
                ghost_global_after = nil,
                ghost_pair_after = nil,
                ghost_pair_mask = nil,
                global_writes = 0,
                attempts = 1
            }
            if kind == "passive" then State.remote_passive = state else State.remote_ghost = state end
            pending = state
            -- OnClick is the documented GUI-equivalent invocation; it preserves
            -- the provider's configured native-thread queuing. Do not bypass that
            -- contract by calling a raw Lua function or changing selected player.
            local sent, result = pcall(fresh.OnClick, fresh)
            if Live.remote_state(kind) ~= state or not state.active then return false end
            if not sent or result == false then
                state.active, state.status = false, "REJECTED"
                log_info("RemoteState status=REJECTED kind=" .. kind .. " pid=" .. player_id ..
                    " provider=" .. checked.name)
                toast("External state action was rejected; no local override was applied.", 6000, "warning"); return false
            end
            state.status = "DISPATCHED_UNVERIFIED"
            log_info(("RemoteState dispatched kind=%s pid=%d provider=%s hash=%s scope=external-player-action localWrites=0")
                :format(kind, player_id, checked.name, tostring(checked.hash)))
            toast(("%s sent through the loaded player action for %s. Waiting for incoming state; result unverified.")
                :format(checked.name, state.player_name), 4500, "info")
            return true
        end)
        if Live.remote_dispatching == token then Live.remote_dispatching = nil end
        if not completed then
            if pending and Live.remote_state(kind) == pending and pending.status == "DISPATCHING" then
                pending.active, pending.status = false, "REJECTED"
            end
            pcall(log_info, "RemoteState status=DISPATCH_ERROR kind=" .. tostring(kind) .. " localWrites=0")
            return false
        end
        return result == true
    end

    -- BEGIN GHOST_RELATIONSHIP44
    -- TU1.73 freemode func_24257 -> func_24261 -> func_24259 clears a
    -- receiver's Ghosted-to-You timer when OUR GPBD_FM_3 f_8 is true and
    -- f_9 is false. This one owned broadcast affects every listening peer.
    -- It is not another player's passive/global-ghost removal primitive.
    Live.ghost_retiring = false
    Live.ghost_busy = false
    function Live.ghost_pending()
        local s = State.remote_ghost
        return Live.ghost_busy or
            (s and (s.active or s.owned or s.restore_pending or s.write_inflight or s.report_pending)) == true
    end

    -- Module terminal guards retain this pure closure directly. Public API
    -- wrappers intentionally return nil after Stop invalidates their token.
    ghost_relationship_pending_raw = Live.ghost_pending
    function Live.ghost_request(pid)
        -- Render callback: queue only. No globals, natives or provider calls.
        if not started or Live.ghost_retiring or Live.ghost_pending()
            or type(pid) ~= "number" or pid ~= pid or pid % 1 ~= 0 or pid < 0 or pid > 31 then
            return false
        end
        State.remote_ghost = {
            active = true,
            queued = true,
            kind = "ghost",
            player_id = math.tointeger(pid),
            status = "QUEUED",
            until_ms = math.huge,
            node_updates = 0,
            ghost_pair_revision = 0,
            writes = 0,
            restore_pending = false,
            owned = false
        }
        return true
    end

    function Live.ghost_cancel(reason, terminal)
        if terminal then Live.ghost_retiring = true end
        local s = State.remote_ghost
        if not s then return end
        s.active = false; s.queued = false; s.result = reason or "Canceled"; s.status = "STOPPED"; s.report_pending = false
        if s.owned or s.write_inflight then s.restore_pending = true end
    end

    function Live.ghost_session_changed()
        -- The session generation changed before this call. Never restore the
        -- previous VM's slot into a new session, even when addresses recycle.
        Live.ghost_cancel("Session changed", false)
        local s = State.remote_ghost
        if s and s.generation ~= Live.action_generation then
            s.owned = false; s.restore_pending = false; s.cleanup_status = "OLD_SESSION_ABANDONED"
        end
    end

    function Live.ghost_bool(hash, ...)
        local _, raw, err = invoke_bool_detail(hash, ...)
        if err ~= nil then return nil end
        if type(raw) == "boolean" then return raw end
        if raw == 0 then return false elseif raw == 1 then return true end
        return nil
    end

    function Live.ghost_source()
        return Live.action_source_ready() and Live.ORG_BASE == 1893070 and Live.ORG_STRIDE == 615
            and Live.PASSIVE_BASE == 1893070 and Live.PASSIVE_STRIDE == 615 and Live.PASSIVE_OFFSET == 8
            and Live.read_global_int(1893070) == 32
    end

    function Live.ghost_owner_same(s)
        return s.generation == Live.action_generation and local_player_id() == s.local_id
            and Live.action_local_same(s)
    end

    function Live.ghost_fence(s, restoring)
        -- This last fence is Lua-only. No host getter may follow it before the
        -- write: a getter can deliver cancellation or a new session reentrantly.
        if State.remote_ghost ~= s or s.generation ~= Live.action_generation then return false end
        if restoring then return s.owned == true and s.write_inflight ~= true end
        return started and not Live.ghost_retiring and s.active == true
            and State.runtime_writes_suspended ~= true
    end

    function Live.ghost_safe(s)
        if not started then return false, "CScript player processing is stopped" end
        if Live.ghost_retiring then return false, "CScript is stopping; retry after loading" end
        if State.runtime_writes_suspended == true then return false, "Player processing is suspended" end
        if not s.active or State.remote_ghost ~= s then
            return false,
                "The Ghosted-to-You request was canceled or replaced"
        end
        if not Live.ghost_source() then return false, "Validated TU1.73 player-state layout unavailable" end
        if not Live.ghost_owner_same(s) then return false, "Your connection changed or could not be verified" end
        if not Live.remote_same(s.player_id, s.identity) then
            return false,
                "Selected player's connection changed or is unavailable"
        end
        local value = Live.ghost_bool(0x10FAB35428CCC9D7) -- NETWORK_IS_GAME_IN_PROGRESS
        if value ~= true then
            return false,
                value == nil and "Cannot read the Online session state" or "Join an active GTA Online session first"
        end
        value = Live.ghost_bool(H.NETWORK_IS_IN_TRANSITION)
        if value ~= false then
            return false,
                value == nil and "Cannot read the session transition state" or
                "Wait for the session transition to finish"
        end
        value = Live.ghost_bool(H.NETWORK_IS_TRANSITION_STARTED)
        if value ~= false then
            return false,
                value == nil and "Cannot read the pending session transition" or
                "A session transition has started; wait for it to finish"
        end
        value = Live.read_global_int(1574582) -- The actual passive controller is never changed.
        if value ~= 0 and value ~= 1 then return false, "Cannot read your passive-mode controller" end
        if value == 1 and Live.read_global_int(s.index) ~= 1 then
            return false, "Your passive-status publication is not ready; retry when it settles"
        end
        value = Live.read_global_int(s.index + 1)
        if value ~= 0 then
            return false,
                value == 1 and "The current special ghost mode does not provide the Ghosted-to-You clear signal" or
                "Cannot read your special passive/ghost-mode state"
        end
        if State.remote_ghost ~= s or not s.active or Live.ghost_retiring then
            return false,
                "The Ghosted-to-You request changed during the checks"
        end
        if not Live.ghost_owner_same(s) then return false, "Your connection changed during the checks" end
        if not Live.remote_same(s.player_id, s.identity) then
            return false,
                "Selected player's connection changed during the checks"
        end
        -- Keep the existing final Lua-only fence: no new host read follows it.
        if not Live.ghost_fence(s, false) then return false, "Player processing changed during the checks" end
        return true
    end

    function Live.ghost_write(s, value, restoring)
        -- AreValid may reenter Lua and replace the session. Fence after it,
        -- immediately before the setter; do not perform another host read.
        if not Live.script_globals_ready() or type(script_global.SetInt) ~= "function"
            or not Live.ghost_fence(s, restoring) then
            return false
        end
        s.write_inflight = true
        if not restoring then
            s.owned = true; s.restore_pending = true
        end
        local ok, accepted = pcall(script_global.SetInt, s.index, value)
        s.write_inflight = false
        return ok and accepted ~= false
    end

    function Live.ghost_result(s, result)
        s.active = false; s.queued = false; s.result = result; s.status = "RESTORING"
        s.restore_pending = s.owned or s.write_inflight or false; s.report_pending = true
    end

    function Live.ghost_release(s, status)
        if s.generation ~= Live.action_generation then status = "OLD_SESSION_ABANDONED" end
        s.owned = false; s.restore_pending = false; s.cleanup_status = status
        return true
    end

    function Live.ghost_restore(s)
        if not s or not s.owned then
            if s then s.restore_pending = s.write_inflight == true end
            return not s or not s.write_inflight
        end
        s.restore_pending = true
        if s.generation ~= Live.action_generation then return Live.ghost_release(s, "OLD_SESSION_ABANDONED") end
        if s.write_inflight then return false end
        if not Live.ghost_source() or not Live.ghost_owner_same(s) then return false end
        local ptr = Live.global_ptr(s.index)
        if not ptr then return false end
        if ptr ~= s.pointer then return Live.ghost_release(s, "STORAGE_REPLACED") end
        local current = Live.read_global_int(s.index)
        if current == nil then return false end
        if current == s.original then return Live.ghost_release(s, "RESTORED") end
        if current ~= 1 then return Live.ghost_release(s, "EXTERNAL_VALUE_PRESERVED") end
        local passive, special = Live.read_global_int(1574582), Live.read_global_int(s.index + 1)
        if passive == nil or special == nil then return false end
        -- If the game or another feature entered real passive/special mode,
        -- its current publication owns the value now; do not clear it.
        if passive ~= 0 or special ~= 0 then return Live.ghost_release(s, "EXTERNAL_PASSIVE_PRESERVED") end
        if not Live.ghost_owner_same(s) or not Live.ghost_source()
            or Live.global_ptr(s.index) ~= s.pointer or Live.read_global_int(s.index) ~= 1
            or Live.read_global_int(1574582) ~= 0 or Live.read_global_int(s.index + 1) ~= 0 then
            return false
        end
        if not Live.ghost_fence(s, true) then
            if s.generation ~= Live.action_generation then return Live.ghost_release(s, "OLD_SESSION_ABANDONED") end
            return false
        end
        Live.ghost_write(s, s.original, true)
        if s.generation ~= Live.action_generation then return Live.ghost_release(s, "OLD_SESSION_ABANDONED") end
        if not Live.ghost_owner_same(s) or Live.global_ptr(s.index) ~= s.pointer then return false end
        local after = Live.read_global_int(s.index)
        if not Live.ghost_fence(s, true) then
            if s.generation ~= Live.action_generation then return Live.ghost_release(s, "OLD_SESSION_ABANDONED") end
            return false
        end
        if after == s.original then return Live.ghost_release(s, "RESTORED") end
        if after ~= nil and after ~= 1 then return Live.ghost_release(s, "EXTERNAL_VALUE_PRESERVED") end
        return false
    end

    function Live.ghost_setup(s, now)
        if not Live.ghost_source() then
            Live.ghost_result(s, "Validated TU1.73 player-state layout unavailable"); return
        end
        local own = Live.remote_player_index(local_player_id())
        if not own or own == s.player_id then
            Live.ghost_result(s, "Select another player"); return
        end
        local target, actor = Live.remote_identity(s.player_id), Live.remote_identity(own)
        if not target or not actor then
            Live.ghost_result(s, "Connection identity unavailable"); return
        end
        s.local_id = math.tointeger(own); s.identity = target; s.local_identity = actor; s.generation = Live
            .action_generation
        s.index = 1893070 + 1 + s.local_id * 615 + 8
        local admitted, reason = Live.ghost_safe(s)
        if not admitted then
            Live.ghost_result(s, reason or "Local eligibility could not be verified"); return
        end
        s.pointer = Live.global_ptr(s.index); s.original = Live.read_global_int(s.index)
        if not s.pointer then
            Live.ghost_result(s, "Local passive-status storage is unavailable"); return
        end
        if s.original == nil then
            Live.ghost_result(s, "Cannot read your passive-status publication"); return
        end
        if s.original ~= 0 and s.original ~= 1 then
            Live.ghost_result(s, "Your passive-status publication is invalid"); return
        end
        admitted, reason = Live.ghost_safe(s)
        if not admitted then
            Live.ghost_result(s, reason or "Local eligibility changed before admission"); return
        end
        if Live.global_ptr(s.index) ~= s.pointer or Live.read_global_int(s.index) ~= s.original then
            Live.ghost_result(s, "Local passive-status storage changed before admission"); return
        end
        s.queued = false; s.status = "READY_TO_SIGNAL"; s.until_ms = now + 6500
        s.ghost_pair_revision = 0; s.ghost_pair_after = nil; s.ghost_pair_mask = nil
    end

    function Live.ghost_publish(s, now)
        if not Live.ghost_safe(s) or Live.global_ptr(s.index) ~= s.pointer
            or Live.read_global_int(s.index) ~= s.original or not Live.ghost_safe(s) then
            Live.ghost_result(s, "Local context changed before the signal"); return
        end
        if not Live.ghost_fence(s, false) then return end
        -- Ownership precedes the setter, including a setter that commits and
        -- then throws or reenters cancellation. Only the local slot is writable.
        if s.original == 0 then
            if not Live.ghost_write(s, 1, false) then
                Live.ghost_result(s, "Ghosted-to-You signal could not be written"); return
            end
        end
        if State.remote_ghost ~= s or not s.active or Live.ghost_retiring
            or not Live.ghost_safe(s) or Live.global_ptr(s.index) ~= s.pointer
            or Live.read_global_int(s.index) ~= 1 or not Live.ghost_fence(s, false) then
            Live.ghost_cancel("Signal interrupted", false); Live.ghost_restore(s); return
        end
        if s.original == 0 then s.writes = s.writes + 1 end
        s.published = true; s.status = "SIGNAL_PUBLISHED"
        -- The source receiver visits one of 32 participant slots per call.
        -- A 1.5s pulse can end before one full sweep on a slower peer. Keep
        -- this single owned signal bounded, with a later acknowledgment window.
        s.published_at = now; s.release_at = now + 4000; s.until_ms = now + 6500
        s.after_revision = s.ghost_pair_revision or 0; s.restore_pending = false
    end

    function Live.ghost_report(s)
        if not s.report_pending or s.owned or s.write_inflight or s.restore_pending then return end
        s.report_pending = false; s.status = s.result or "STOPPED"
        local detail
        if s.result == "PAIR_CLEAR_OBSERVED" then
            detail = "Fresh incoming state reports Ghosted to You cleared."
        elseif s.result == "PAIR_ALREADY_CLEAR" then
            detail = "The incoming Ghosted to You flag is already clear."
        elseif s.result == "NO_INCOMING_STATE" then
            detail = "No fresh Ghosted to You state arrived; no signal was published."
        elseif s.result == "NO_CLEAR_OBSERVED" then
            detail = "The clear request finished; the selected player's Ghosted to You clear was not confirmed."
        else
            detail = tostring(s.result or "Canceled") .. "."
        end
        log_info("GhostedToYou result=" .. tostring(s.result) .. " cleanup=" .. tostring(s.cleanup_status)
            .. " target=" .. tostring(s.player_id) .. " writes=" .. tostring(s.writes or 0)
            .. " scope=own-broadcast-all-peer-observation")
        toast(detail, 6500, "info")
    end

    function Live.ghost_service(now, allow, force)
        if Live.ghost_busy then return not Live.ghost_pending() end
        local s = State.remote_ghost
        if not s or not Live.ghost_pending() then return true end
        if type(now) ~= "number" or now ~= now or math.abs(now) == math.huge then
            Live.ghost_cancel("Clock unavailable", false); return false
        end
        if allow ~= true then Live.ghost_cancel("Player processing suspended", false) end
        if s.last_tick and now < s.last_tick then Live.ghost_cancel("Clock moved backwards", false) end
        if not force and s.last_tick and now >= s.last_tick and now - s.last_tick < 100 then return false end
        s.last_tick = now; Live.ghost_busy = true
        local ok = pcall(function()
            if s.owned and not s.active then s.restore_pending = true end
            if s.restore_pending then Live.ghost_restore(s) end
            if s.active then
                if s.queued then
                    Live.ghost_setup(s, now)
                elseif not Live.ghost_safe(s) then
                    Live.ghost_result(s, "Player or local context changed")
                elseif s.published then
                    if (s.ghost_pair_revision or 0) > (s.after_revision or 0) and s.ghost_pair_after == false then
                        Live.ghost_result(s, "PAIR_CLEAR_OBSERVED")
                    elseif now >= s.until_ms then
                        Live.ghost_result(s, "NO_CLEAR_OBSERVED")
                    end
                    if s.owned and now >= s.release_at then s.restore_pending = true end
                else
                    -- A stable relationship need not send a fresh sync node.
                    -- Readback acknowledges the request, never gates dispatch.
                    Live.ghost_publish(s, now)
                end
            end
            if s.restore_pending then Live.ghost_restore(s) end
            Live.ghost_report(s)
        end)
        Live.ghost_busy = false
        if not ok then
            -- The protected turn has unwound: no setter from it is still in
            -- flight, but any already-owned slot remains restoration debt.
            s.write_inflight = false
            Live.ghost_cancel("Host state unavailable", false)
        end
        return not Live.ghost_pending()
    end

    -- END GHOST_RELATIONSHIP44

    local function start_remote_ghost_clear(player_id) return Live.ghost_request(player_id) end
    local function start_remote_passive_clear(player_id) return Live.remote_dispatch("passive", player_id) end
    local function tick_remote_ghost_clear(now) Live.ghost_service(now, true) end
    local function tick_remote_passive_clear(now) Live.remote_tick("passive", now) end
    local function finish_remote_ghost_clear(reason, quiet) Live.ghost_cancel(reason, false) end
    local function finish_remote_passive_clear(reason, quiet) Live.remote_finish("passive", reason, quiet) end

    local function remote_relationship_filter_active()
        return (State.remote_ghost and State.remote_ghost.active == true)
            or (State.remote_passive and State.remote_passive.active == true)
    end

    local function filter_remote_relationship_nodes(player_id, updated_nodes)
        -- Compatibility entry point is retained, but this is now READ-ONLY.
        -- Network update callbacks cannot run a removal, execute a native, or
        -- modify a flag. No cached userdata escapes this callback.
        if not started or (type(updated_nodes) ~= "table" and type(updated_nodes) ~= "userdata")
            or not sync_node_type then
            return false
        end
        player_id = Live.remote_player_index(player_id)
        if not player_id then return false end
        local now = now_ms()
        pcall(function()
            for index, node in ipairs(updated_nodes) do
                if index > 192 then break end
                local ok_type, node_type = pcall(function() return node:GetNodeType() end)
                for _, kind in ipairs({ "passive", "ghost" }) do
                    local state = Live.remote_state(kind)
                    if state and state.active and state.player_id == player_id and now < state.until_ms
                        and ok_type then
                        local field, flag, mask
                        if node_type == sync_node_type.CPlayerGameStateDataNode then
                            local ok, value = pcall(function()
                                local data = node:As("CPlayerGameStateDataNode")
                                if kind == "passive" then return data.bIsPassiveMode else return data.bGhost end
                            end)
                            if ok and type(value) == "boolean" then
                                field = kind == "passive" and "passive_after" or "ghost_global_after"
                                flag = value
                            end
                        elseif kind == "ghost" and sync_node_type.CPlayerExtendedGameStateNode ~= nil
                            and node_type == sync_node_type.CPlayerExtendedGameStateNode then
                            local ok, value = pcall(function()
                                return node:As("CPlayerExtendedGameStateNode").ghostPlayers
                            end)
                            local local_id = Live.remote_player_index(state.identity and state.identity.local_id)
                            -- The host exposes an int mask; accept either signed or
                            -- unsigned 32-bit representation, never a coerced flag.
                            if ok and local_id and type(value) == "number" and value == value
                                and value % 1 == 0 and value >= -2147483648 and value <= 4294967295 then
                                field, mask = "ghost_pair_after", value & 0xFFFFFFFF
                                flag = (mask & (1 << local_id)) ~= 0
                            end
                        end
                        -- A reused player slot or reentrant callback cannot supply
                        -- observations for the request's previous connection.
                        if field and Live.remote_same(player_id, state.identity)
                            and (kind ~= "ghost" or not state.index or Live.ghost_owner_same(state))
                            and Live.remote_state(kind) == state and state.active then
                            state.node_updates = state.node_updates + 1
                            state[field] = flag
                            if mask ~= nil then
                                state.ghost_pair_mask = mask
                                state.ghost_pair_revision = (state.ghost_pair_revision or 0) + 1
                            end
                            if kind == "ghost" then
                                -- False in just one channel cannot establish that
                                -- the other channel is clear. These are received
                                -- publications, not proof of owner-side restoration.
                                if state.ghost_global_after == true or state.ghost_pair_after == true then
                                    state.ghost_after = true
                                elseif state.ghost_global_after == false and state.ghost_pair_after == false then
                                    state.ghost_after = false
                                else
                                    state.ghost_after = nil
                                end
                            end
                        end
                    end
                end
            end
        end)
        return false
    end

    -- Enhanced uses two authoritative interior paths. Property instances use
    -- func_25184/event -1321657966 (11 fields); simple interiors use
    -- func_25008/event -1638522928 (16 fields). GlobalPlayerBD f_325 carries
    -- each player's simple-interior index, instance, owner and subtype.

    -- VM layout validation does not establish target-side acceptance. Dispatch
    -- through one verified player-bound interior action; no remote-global writes
    -- or coordinate teleport fallback.
    function Live.action_source_ready()
        if not Live.script_globals_ready() then return false end
        -- Online version alone is not address proof; row/nested headers and field
        -- ranges below remain mandatory. Never auto-upgrade to an unknown TU.
        if type(Live.online_version) ~= "function" then return false end
        local ok, version = pcall(Live.online_version, 0xFCA9373EF340AC0A)
        return ok and version == "1.73"
    end

    function Live.action_identity(player_id)
        if not Live.action_source_ready() then
            toast("Selected-player script actions require the validated TU1.73 source layout.", 6500, "warning")
            return nil
        end
        player_id = Live.remote_player_index(player_id)
        local local_id = Live.remote_player_index(local_player_id())
        if not player_id or not local_id or player_id == local_id then return nil end
        local target, actor = Live.remote_identity(player_id), Live.remote_identity(local_id)
        if not target or not actor then return nil end
        return {
            player_id = player_id,
            identity = target,
            local_id = local_id,
            local_identity = actor,
            generation = Live.action_generation,
            active = true,
            last_poll_ms = -100000
        }
    end

    function Live.action_local_same(state)
        if not state or state.generation ~= Live.action_generation
            or local_player_id() ~= state.local_id then
            return false
        end
        local current = Live.remote_identity(state.local_id)
        local original = state.local_identity
        return current ~= nil and original ~= nil
            and current.rid == original.rid and current.cxn == original.cxn
    end

    function Live.action_valid(state)
        return state ~= nil and state.active == true and Live.action_source_ready() and Live.action_local_same(state)
            and Live.remote_same(state.player_id, state.identity)
            and (state.owner_id == nil or Live.remote_same(state.owner_id, state.owner_identity))
    end

    function Live.action_poll_due(state, now)
        if now < (state.until_ms or 0) and now >= (state.last_poll_ms or -100000)
            and now - (state.last_poll_ms or -100000) < 100 then
            return false
        end
        state.last_poll_ms = now
        return true
    end

    function Live.event_float32(value)
        if type(value) ~= "number" or value ~= value or math.abs(value) > 1000000
            or type(string.pack) ~= "function" or type(string.unpack) ~= "function" then
            return nil
        end
        local ok, bits = pcall(function() return string.unpack("<i4", string.pack("<f", value)) end)
        return ok and bits or nil
    end

    function Live.action_send(player_id, args, fence)
        if not Live.action_source_ready() then return false, "source build/globals became unavailable" end
        -- A codec contract, not a universal arbitrary-event sender. Dense exact
        -- payload lengths keep adjacent fields or dropped nil cells off the wire.
        local words = ({ [Live.ORG_JOIN_REQUEST_EVENT] = 3, [Live.ORG_DISMISS_EVENT] = 3,
            [Live.SIMPLE_INTERIOR_EVENT] = 16, [Live.PROPERTY_INVITE_EVENT] = 11, [Live.KICK_INTERIOR_EVENT] = 9,
            [Live.SCRIPTED_SCREEN_BEGIN_EVENT] = 25, [Live.SCRIPTED_SCREEN_ACK_EVENT] = 24 })[args and args[1]]
        if Live.source_catalog then
            words = nil
            for _, definition in pairs(Live.source_catalog.events) do
                if args and args[1] == definition.id then
                    words = definition.words; break
                end
            end
        end
        if not words or type(args) ~= "table" then return false, "unknown source event" end
        local count = 0
        for key in pairs(args) do
            if type(key) ~= "number" or key % 1 ~= 0 or key < 1 or key > words then
                return false, "invalid script-event cell index"
            end
            count = count + 1
        end
        if count ~= words or #args ~= words then return false, "source event payload length mismatch" end
        if args[2] ~= local_player_id() then return false, "event sender must be the local actor" end
        player_id = Live.remote_player_index(player_id)
        if not player_id or not gta or type(gta.TriggerScriptEvent) ~= "function" then
            return false, "script event API unavailable"
        end
        for _, value in ipairs(args) do
            if type(value) ~= "number" or value ~= value or value % 1 ~= 0 then
                return false, "script event payload must contain integer cells"
            end
        end
        if fence ~= nil and (type(fence) ~= "function" or fence() ~= true) then return false, "script event cancelled" end
        local ok, result = pcall(gta.TriggerScriptEvent, 1 << player_id, args)
        if not ok or result == false then return false, tostring(result) end
        -- API return is dispatch information, never a target-side acknowledgement.
        return true, result
    end

    -- One captured connection and a bounded three-event launch batch.
    -- The companion below observes admission and owns completed self cleanup.
    Live.scripted_screens = Module.NewScriptedScreens({
        Now = now_ms,
        Capture = function(pid) return Live.scripted_screen_identity(pid) end,
        Valid = function(request)
            return Live.scripted_screen_valid(request)
        end,
        CanObserveReady = function(request) return Live.scripted_screen_can_observe_ready(request) end,
        Send = function(pid, args, fence) return Live.action_send(pid, args, fence) end,
        Report = function(status)
            log_info(("Scripted screen %s: %s; target=%s; recipientConfirmed=false")
                :format(tostring(status.kind or "screen"), tostring(status.phase), tostring(status.player_id)))
            local errors = Live.scripted_screen_errors
            if status.phase == "dispatched" then
                errors[status.player_id] = nil
            elseif status.active == false and (status.phase == "failed" or status.phase == "expired")
                and status.detail and errors[status.player_id] ~= status.detail then
                errors[status.player_id] = status.detail
                toast(status.detail, 4500, "warning")
            end
        end,
    })
    function Live.start_scripted_screen(pid, kind)
        if not started or not lifecycle_token or lifecycle_token.alive ~= true then return false end
        local accepted, why = Live.scripted_screens.Begin(pid, kind)
        if not accepted and why then toast(why, 6500, "warning") end
        return accepted
    end

    Live.scripted_screen_kinds = {
        send_online_intro = "online_intro",
        send_doomsday_hack = "iaa_hack",
        send_wizards_ruin =
        "wizard_arcade",
        send_space_monkey = "space_monkey",
        send_badlands_revenge = "badlands",
        send_camhedz = "camhedz"
    }
    Live.scripted_screen_toggle_refs = {}
    Live.scripted_screen_errors = {}
    Live.scripted_screen_syncing = {}
    Live.scripted_screen_armed = false

    function Live.clear_scripted_screen_toggle(feature)
        if feature == nil or Live.scripted_screen_syncing[feature] then return false end
        Live.scripted_screen_syncing[feature] = true
        local ok = pcall(function()
            if feature:IsToggled() then feature:Toggle(false) end
        end)
        Live.scripted_screen_syncing[feature] = nil
        return ok
    end

    function Live.scripted_screen_identity(pid)
        pid = Live.remote_player_index(pid)
        local actor = Live.remote_player_index(local_player_id())
        if not pid or not actor then return nil, "Select an available player." end
        local target_identity, local_identity = Live.remote_identity(pid), Live.remote_identity(actor)
        if not target_identity or not local_identity then return nil, "Player connection is unavailable." end
        return {
            player_id = pid,
            identity = target_identity,
            local_id = actor,
            local_identity = local_identity,
            generation = Live.action_generation,
            active = true,
            last_poll_ms = -100000
        }
    end

    function Live.scripted_screen_same(pin)
        if type(pin) ~= "table" or pin.active ~= true or not started
            or pin.generation ~= Live.action_generation then
            return false
        end
        local ok, actor = pcall(local_player_id)
        if not ok or type(actor) ~= "number" or actor % 1 ~= 0 or actor < 0 or actor > 31 then return nil end
        if actor ~= pin.local_id then return false end
        local function matches(pid, expected)
            if type(expected) ~= "table" then return false end
            if not Live.Players or type(Live.Players.GetById) ~= "function" then return nil end
            local read, player = pcall(Live.Players.GetById, pid)
            if not read then return nil end
            if player == nil then return false end
            local checked, rid, cxn = pcall(function()
                local info = player:GetGamerInfo()
                return info and info.RockstarId, player.CxnId
            end)
            if not checked or rid == nil or tostring(rid) == "" or tostring(rid) == "0"
                or type(cxn) ~= "number" or cxn ~= cxn or cxn % 1 ~= 0 then
                return nil
            end
            return tostring(rid) == expected.rid and cxn == expected.cxn and actor == expected.local_id
        end
        local local_same, target_same = matches(actor, pin.local_identity), matches(pin.player_id, pin.identity)
        if local_same == false or target_same == false then return false end
        if local_same == nil or target_same == nil then return nil end
        return true
    end

    function Live.scripted_screen_valid(pin)
        if not started or not lifecycle_token or lifecycle_token.alive ~= true then return false end
        local same = Live.scripted_screen_same(pin)
        if same ~= true then return same end
        if State.runtime_writes_suspended == true or not Live.action_source_ready() then return nil end
        return true
    end

    function Live.scripted_screen_can_observe_ready(pin)
        local session = module_context and module_context.CScript and module_context.CScript.Session
        if not session or type(session.IsScriptedScreenObserverRegistered) ~= "function"
            or session.IsScriptedScreenObserverRegistered() ~= true or not Live.scripted_screen_pin_ready(pin) then
            return false
        end
        local token = lifecycle_token
        local ok, _, raw, err = pcall(invoke_int_detail, H.NETWORK_GET_HOST_OF_SCRIPT, "freemode", -1, 0)
        return ok and err == nil and type(raw) == "number" and raw % 1 == 0 and raw == pin.local_id
            and Live.scripted_screen_pin_current(pin, token)
    end

    function Live.scripted_screen_pin_ready(pin)
        return Live.scripted_screen_valid(pin) == true
    end

    function Live.scripted_screen_pin_current(pin, token)
        -- Getter-free final check after the controller's potentially reentrant
        -- identity fence and immediately before a transport/write boundary.
        return started and token ~= nil and lifecycle_token == token and token.alive == true
            and State.runtime_writes_suspended ~= true and pin.active == true
            and pin.generation == Live.action_generation
    end

    -- The normal freemode player broadcast publishes the 21-cell launch data
    -- only after a script starts. A clear row is not proof that an unobserved
    -- pending request was cancelled; retired requests retain their cleanup IDs.
    function Live.record_scripted_screen_observation(pin, value)
        -- Cache on the captured connection; no extra native/global reads and no
        -- UI notification. This is accepted-launch publication, not remote UI
        -- completion or access to the recipient's private pending state.
        local signature = value == nil and "unreadable" or value.active == false and "clear"
            or ("active:" .. tostring(value.selector) .. ":" .. tostring(value.instance) .. ":" .. tostring(value.nonce))
        if pin.observation60 == signature then return end
        pin.observation60 = signature
        local snapshot = Live.scripted_screens.Snapshot()
        local sender_here = snapshot.player_id == pin.player_id
        local intent = Live.scripted_screen_toggle_refs[pin.player_id]
        pcall(log_info,
            ("Scripted-screen observation: target=%s; source=player-broadcast; observed=%s; requested=%s; senderKind=%s; senderNonce=%s")
            :format(tostring(pin.player_id), signature, tostring(intent and intent.kind or "none"),
                tostring(sender_here and snapshot.kind or "none"), tostring(sender_here and snapshot.nonce or "none")))
    end

    function Live.observe_scripted_screen(pin)
        local token = lifecycle_token
        if not Live.scripted_screen_pin_ready(pin) then return nil end
        local function finish(value)
            if not Live.scripted_screen_pin_current(pin, token) then return nil end
            Live.record_scripted_screen_observation(pin, value)
            -- Logging is callback-capable; never publish a stale sample after
            -- a reentrant cancellation or runtime/session replacement.
            if not Live.scripted_screen_pin_current(pin, token) then return nil end
            return value
        end
        if Live.read_global_int(2658296) ~= 32 then return finish(nil) end
        local base = 2658296 + 1 + pin.player_id * 468 + 1
        local selector, instance, nonce = Live.read_global_int(base),
            Live.read_global_int(base + 16), Live.read_global_int(base + 17)
        if selector == nil or instance == nil or nonce == nil or selector < 0 or selector > 4096
            or instance < -1 or instance > 31 then
            return finish(nil)
        end
        if Live.read_global_int(base) ~= selector or Live.read_global_int(base + 16) ~= instance
            or Live.read_global_int(base + 17) ~= nonce or Live.read_global_int(2658296) ~= 32
            or not Live.scripted_screen_pin_ready(pin) then
            return finish(nil)
        end
        if selector == 0 and instance == -1 and nonce == 0 then return finish({ active = false }) end
        if nonce < 1 or nonce > 2147483647 then return finish(nil) end
        return finish({ active = true, selector = selector, instance = instance, nonce = nonce })
    end

    function Live.cancel_pending_scripted_screen(pin, nonce, fence)
        local token = lifecycle_token
        if type(fence) ~= "function" or not fence() or not Live.scripted_screen_pin_ready(pin)
            or type(nonce) ~= "number" or nonce % 1 ~= 0 or nonce < 1 or nonce > 2147483647 then
            return false
        end
        local observed = Live.observe_scripted_screen(pin)
        if not observed or observed.active ~= false then return false end
        -- This event aborts only matching pre-launch states 6/7/8. It cannot
        -- terminate a script that is already running in state10.
        return Live.action_send(pin.player_id, { 1625721778, pin.local_id, 0, nonce }, function()
            return Live.scripted_screen_pin_ready(pin) and fence() and Live.scripted_screen_pin_current(pin, token)
        end)
    end

    function Live.cleanup_completed_self_screen(pin, transaction, fence)
        local token = lifecycle_token
        if type(fence) ~= "function" or not fence() or not Live.scripted_screen_pin_ready(pin)
            or pin.player_id ~= pin.local_id or type(transaction) ~= "table"
            or transaction.admitted ~= true or transaction.kind ~= "iaa_hack" or transaction.selector ~= 209
            or type(transaction.nonce) ~= "number" or transaction.nonce % 1 ~= 0
            or transaction.nonce < 1 or transaction.nonce > 2147483647 then
            return false
        end
        local function owned_launch()
            local observed = Live.observe_scripted_screen(pin)
            return observed and observed.active == true and observed.selector == 209
                and observed.nonce == transaction.nonce and observed.instance == transaction.instance
                and Live.read_global_int(2621568) == 10 and Live.read_global_int(2621568 + 4) == 209
                and Live.read_global_int(2621568 + 20) == transaction.instance
                and Live.read_global_int(2621568 + 21) == transaction.nonce
        end
        if not owned_launch() then return false end
        local result, flags = Live.read_global_int(1965228 + 1), Live.read_global_int(1965228)
        if (result ~= 1 and result ~= 2 and result ~= 3) or flags == nil then return false end
        local ok, _, threads, err = pcall(invoke_int_detail, 0x2C83A9DA6BFFC4F9, 0x9C0D52BB)
        if not ok or err ~= nil or threads ~= 1 or not owned_launch()
            or Live.read_global_int(1965228 + 1) ~= result or Live.read_global_int(1965228) ~= flags
            or not script_global or type(script_global.SetInt) ~= "function"
            or not Live.scripted_screen_pin_ready(pin) or not fence()
            or not Live.scripted_screen_pin_current(pin, token) then
            return false
        end
        if (flags & 1) ~= 0 then return true end
        -- The normal mission supervisor sets this bit after result1/2/3.
        -- Hotwire performs its own UI/result cleanup and thread termination;
        -- freemode then clears its launch slot. Never reset that slot ourselves.
        local next_flags = (flags | 1) & 0xFFFFFFFF
        if next_flags >= 2147483648 then next_flags = next_flags - 4294967296 end
        local wrote = pcall(script_global.SetInt, 1965228, next_flags)
        return wrote and Live.read_global_int(1965228) == next_flags
    end

    Live.scripted_screen_repeats = Module.NewScriptedScreenRepeater({
        Now = now_ms,
        Capture = Live.scripted_screen_identity,
        Same = Live.scripted_screen_same,
        Ready = function()
            return Live.scripted_screen_armed and started and lifecycle_token and lifecycle_token.alive == true
                and State.runtime_writes_suspended ~= true and Live.action_source_ready()
        end,
        Observe = Live.observe_scripted_screen,
        CancelPending = Live.cancel_pending_scripted_screen,
        Cleanup = Live.cleanup_completed_self_screen,
        Report = function(value)
            -- Debug nonce updates do not belong in the normal release log.
        end,
        OnDisabled = function(pid, kind, reason)
            local entry = Live.scripted_screen_toggle_refs[pid]
            if entry and entry.kind == kind and not Live.scripted_screen_repeats.IsEnabled(pid, kind) then
                Live.scripted_screen_toggle_refs[pid] = nil
                Live.scripted_screen_errors[pid] = nil
                Live.clear_scripted_screen_toggle(entry.feature)
            end
            if reason and not tostring(reason):find("replaced this action",1,true) then
                log_info("Scripted screen stopped: " .. tostring(reason))
            end
        end,
    }, Live.scripted_screens)

    function Live.rearm_scripted_screens()
        Live.scripted_screen_armed = false
        local ok, why = Live.scripted_screen_repeats.Rearm()
        if not ok then return false, why end
        Live.scripted_screen_armed = true
        return true
    end

    function Live.set_scripted_screen_toggle(feature, kind)
        if feature == nil or Live.scripted_screen_syncing[feature] then return false end
        local ok, pid, enabled = pcall(function() return feature:GetPlayerIndex(), feature:IsToggled() end)
        if not ok or type(pid) ~= "number" or pid % 1 ~= 0 or pid < 0 or pid > 31 then
            Live.clear_scripted_screen_toggle(feature)
            return false
        end
        if not enabled then
            local entry = Live.scripted_screen_toggle_refs[pid]
            -- A delayed OFF callback from an older feature object must not
            -- remove the same kind's replacement intent.
            if entry and (entry.kind ~= kind or entry.feature ~= feature) then return true end
            Live.scripted_screen_repeats.SetEnabled(pid, kind, false)
            if entry and entry.kind == kind and entry.feature == feature then
                Live.scripted_screen_toggle_refs[pid] = nil
                Live.scripted_screen_errors[pid] = nil
            end
            return true
        end
        if not Live.scripted_screen_armed or not started or not lifecycle_token or lifecycle_token.alive ~= true then
            Live.clear_scripted_screen_toggle(feature)
            return false
        end
        local accepted, why = Live.scripted_screen_repeats.SetEnabled(pid, kind, true)
        if not accepted or not Live.scripted_screen_repeats.IsEnabled(pid, kind) then
            Live.clear_scripted_screen_toggle(feature)
            if why then toast(why, 4500, "warning") end
            return false
        end
        Live.scripted_screen_toggle_refs[pid] = { kind = kind, feature = feature }
        return true
    end

    function Live.physical_interior(player_id)
        local ped = player_ped(player_id)
        if not entity_exists(ped) then return nil end
        local _, value, err = invoke_int_detail(H.GET_INTERIOR_FROM_ENTITY, ped)
        if err ~= nil or type(value) ~= "number" or value ~= value
            or value % 1 ~= 0 or value < 0 then
            return nil
        end
        return value
    end

    function Live.global_ptr(index)
        if not script_global or type(script_global.GetPtr) ~= "function" then return nil end
        local ok, ptr = pcall(script_global.GetPtr, index)
        return ok and type(ptr) == "number" and ptr > 0 and ptr % 1 == 0 and ptr or nil
    end

    function Live.restore_join_request(state)
        if not state or not state.joining_index then return true end
        local function finish(status)
            state.join_restore_pending = false
            state.join_request_owned = false
            state.join_cleanup_status = status
            if Live.join_cleanup == state then Live.join_cleanup = nil end
            State.join_cleanup_pending = Live.join_cleanup ~= nil
            return true
        end
        Live.join_cleanup = state
        state.join_restore_pending = true
        State.join_cleanup_pending = true
        state.join_cleanup_status = "RESTORE_PENDING"
        -- A new VM/session must never receive the previous session's baseline.
        if state.generation ~= Live.action_generation then
            return finish("ABANDONED_SESSION_CHANGED")
        end
        -- An off callback can run before SetInt commits. Seeing the baseline
        -- during that call cannot settle a write which has not returned yet.
        if state.join_write_inflight then return false end
        if not Live.action_source_ready() or not Live.action_local_same(state) then return false end
        if Live.org_index(state.local_id, Live.ORG_JOINING_BOSS_OFFSET) ~= state.joining_index then return false end
        local ptr = Live.global_ptr(state.joining_index)
        if not ptr then return false end
        if ptr ~= state.joining_ptr then return finish("ABANDONED_STORAGE_CHANGED") end
        local current = Live.read_global_int(state.joining_index)
        if current == nil then return false end
        if current == state.original_joining_boss then return finish("RESTORED") end
        if current ~= state.boss_id then return finish("EXTERNALLY_CHANGED") end
        Live.write_global_int(state.joining_index, state.original_joining_boss)
        -- This also settles a write-then-throw host result without a second write.
        if Live.global_ptr(state.joining_index) == state.joining_ptr
            and Live.action_local_same(state)
            and Live.read_global_int(state.joining_index) == state.original_joining_boss then
            return finish("RESTORED")
        end
        return false
    end

    function Live.retry_join_cleanup(now, force)
        local state = Live.join_cleanup
        if not state or not state.join_restore_pending then return true end
        now = tonumber(now) or now_ms()
        if not force and state.join_cleanup_retry_at and now >= state.join_cleanup_retry_at - 250
            and now < state.join_cleanup_retry_at then
            return false
        end
        state.join_cleanup_retry_at = now + 250
        return Live.restore_join_request(state)
    end

    function Live.property_instance(player_id)
        player_id = Live.remote_player_index(player_id)
        if not player_id or Live.read_global_int(Live.PROPERTY_BASE) ~= 32 then return nil end
        return Live.read_global_int(Live.PROPERTY_BASE + 1
            + player_id * Live.PROPERTY_STRIDE + Live.PROPERTY_OFFSET + 1)
    end

    local function player_property(player_id)
        player_id = tonumber(player_id)
        if not Live.remote_player_index(player_id)
            or Live.read_global_int(Live.PROPERTY_BASE) ~= 32 then
            return nil
        end
        return Live.read_global_int(Live.PROPERTY_BASE + 1
            + math.floor(player_id) * Live.PROPERTY_STRIDE + Live.PROPERTY_OFFSET)
    end

    function Live.property_owner(player_id)
        player_id = Live.remote_player_index(player_id)
        if not player_id or Live.read_global_int(Live.PROPERTY_BASE) ~= 32 then return nil end
        -- am_mp_property_int func_13227 publishes the actual owner's handle
        -- at f_260.f_76 even when this player is only visiting the property.
        local index = Live.PROPERTY_BASE + 1 + player_id * Live.PROPERTY_STRIDE + 260 + 76
        local ptr = Live.global_ptr(index)
        if not ptr then return nil end
        local valid, raw, err = invoke_bool_detail(0x6F79B93B0A8E4133, ptr, 13)
        if err ~= nil or valid ~= true or (raw ~= true and raw ~= 1) then return nil end
        local owner, owner_raw, owner_error = invoke_int_detail(0xCE5F689CF5A0A49D, ptr)
        if owner_error ~= nil or type(owner_raw) ~= "number" or owner ~= owner_raw
            or not Live.remote_player_index(owner) or not player_available(owner) then
            return nil
        end
        return owner
    end

    function Live.player_simple_interior(player_id)
        player_id = tonumber(player_id)
        if not Live.remote_player_index(player_id)
            or Live.read_global_int(Live.PLAYER_BD_BASE) ~= 32 then
            return nil
        end
        local base = Live.PLAYER_BD_BASE + 1 + math.floor(player_id) * Live.PLAYER_BD_STRIDE
        local group_flags = Live.read_global_int(base + Live.SIMPLE_GROUP_FLAGS_OFFSET)
        local index = Live.read_global_int(base + Live.SIMPLE_INDEX_OFFSET)
        local owner = Live.read_global_int(base + Live.SIMPLE_OWNER_OFFSET)
        local active = type(index) == "number" and index >= 0 and index <= 255
            and type(owner) == "number" and owner >= 0 and owner <= 31
        return {
            group_flags = group_flags,
            -- func_2385: GET_BITS_IN_RANGE(f_325.f_3, 28, 31). This is
            -- freemode's authoritative exit-group argument for event -1496371358.
            exit_type = group_flags and ((u32(group_flags) >> 28) & 0xF) or nil,
            index = index,
            instance = Live.read_global_int(base + Live.SIMPLE_INSTANCE_OFFSET),
            owner = owner,
            subtype = Live.read_global_int(base + Live.SIMPLE_SUBTYPE_OFFSET),
            active = active,
        }
    end

    -- Current Enhanced freemode organization handshake:
    --   GPBD_FM_3.BossGoon.JoiningBoss = selected organization owner
    --   CEventNetworkRequestToJoinBoss (-627920584) -> that owner
    -- The owner's freemode instance validates JoiningBoss, adds the requester
    -- to its synchronized Goons roster, and returns event 1360435217. CScript
    -- never writes Boss or the roster; those remain freemode-authoritative.
    function Live.org_index(player_id, offset)
        player_id = tonumber(player_id)
        if not Live.remote_player_index(player_id)
            or Live.read_global_int(Live.ORG_BASE) ~= 32 then
            return nil
        end
        return Live.ORG_BASE + 1 + math.floor(player_id) * Live.ORG_STRIDE
            + Live.ORG_ROOT_OFFSET + math.floor(tonumber(offset) or 0)
    end

    function Live.org_owner(player_id)
        local index = Live.org_index(player_id, 0)
        local owner = index and Live.read_global_int(index)
        return type(owner) == "number" and owner >= -1 and owner <= 31 and owner or nil
    end

    function Live.boss_has_goon(boss_id, player_id)
        boss_id, player_id = tonumber(boss_id), tonumber(player_id)
        if not Live.remote_player_index(boss_id) or not Live.remote_player_index(player_id) then return nil end
        local header = Live.org_index(boss_id, Live.ORG_GOONS_OFFSET)
        local observed_header = header and Live.read_global_int(header)
        -- Current Yim layout reserves eight cells; Rockstar's own member loops
        -- use seven. The prior hardcoded header==7 rejected header==8 outright.
        -- A seven-capacity row can still be read without touching the reserved
        -- cell; no other capacity is accepted and no roster write is performed.
        if not header or (observed_header ~= Live.ORG_ROSTER_STORAGE and observed_header ~= Live.ORG_GOON_COUNT) then
            local signature = tostring(header) .. ":" .. tostring(observed_header)
            if Live.org_header_warning ~= signature then
                Live.org_header_warning = signature
                log_info("Organization roster UNAVAILABLE headerIndex=" .. tostring(header)
                    .. " expectedStorage=7-or-8 activeSlots=" ..
                    Live.ORG_GOON_COUNT .. " observed=" .. tostring(observed_header)
                    .. "; no layout guessing or roster writes")
            end
            return nil
        end
        local found = false
        for slot = 0, Live.ORG_GOON_COUNT - 1 do
            local index = Live.org_index(boss_id, Live.ORG_GOONS_OFFSET + 1 + slot)
            local member = index and Live.read_global_int(index)
            if member == nil or member < -1 or member > 31 then return nil end
            if member == player_id then found = true end
        end
        return found
    end

    function Live.org_has_capacity(boss_id)
        -- freemode func_10608/10606: CEO includes boss + 3 members; MC + 7.
        local mc_index = Live.org_index(boss_id, 433)
        local mc = mc_index and Live.read_global_int(mc_index)
        if mc ~= 0 and mc ~= 1 then return nil end
        local header = Live.org_index(boss_id, Live.ORG_GOONS_OFFSET)
        local size = header and Live.read_global_int(header)
        if size ~= Live.ORG_ROSTER_STORAGE and size ~= Live.ORG_GOON_COUNT then return nil end
        local limit, free = mc == 1 and 7 or 3, false
        for slot = 0, limit - 1 do
            local index = Live.org_index(boss_id, Live.ORG_GOONS_OFFSET + 1 + slot)
            local member = index and Live.read_global_int(index)
            if type(member) ~= "number" or member % 1 ~= 0 or member < -1 or member > 31 then return nil end
            if member == -1 then free = true end
        end
        return free
    end

    -- BEGIN ORGANIZATION_JOIN47_READINESS
    -- func_12140 refuses a request while the boss is its own f_36 activity
    -- owner (func_11268). Visible empty slots can also be reserved by saved
    -- account IDs inside the boss's script; those reservations are not readable
    -- from this client. An explicit rejection never becomes local acceptance.
    function Live.org_join_readiness(boss)
        local capacity = Live.org_has_capacity(boss)
        local busy_index = Live.org_index(boss, 36)
        local activity = busy_index and Live.read_global_int(busy_index)
        if capacity == nil or type(activity) ~= "number" or activity % 1 ~= 0
            or activity < -1 or activity > 31 then
            return { known = false, detail = "Waiting for organization availability data." }
        end
        local type_index = Live.org_index(boss, 433)
        local kind = type_index and Live.read_global_int(type_index)
        if kind ~= 0 and kind ~= 1 then return { known = false, detail = "Waiting for organization type data." } end
        local signature = { tostring(kind), tostring(activity) }
        for slot = 0, Live.ORG_GOON_COUNT - 1 do
            local index = Live.org_index(boss, Live.ORG_GOONS_OFFSET + 1 + slot)
            local member = index and Live.read_global_int(index)
            if type(member) ~= "number" or member % 1 ~= 0 or member < -1 or member > 31 then
                return { known = false, detail = "Waiting for the organization roster." }
            end
            signature[#signature + 1] = tostring(member)
        end
        return {
            known = true,
            capacity = capacity,
            busy = activity == boss,
            activity_owner = activity,
            organization_type = kind,
            signature = table.concat(signature, ":"),
            detail = activity == boss and "Waiting for the organization activity to allow members."
                or capacity == false and "Waiting for a free organization slot." or "Organization appears available."
        }
    end

    function Live.join_status(state, phase, detail)
        if State.join_organization ~= state then return end
        if state.phase ~= phase or state.detail ~= detail then
            state.phase, state.detail = phase, detail
            log_info(("Join Their CEO / MC phase=%s selected=%s boss=%s attempts=%s leaveAttempts=%s detail=%s")
                :format(tostring(phase), tostring(state.selected_id), tostring(state.boss_id),
                    tostring(state.attempts or 0), tostring(state.leave_attempts or 0), tostring(detail)))
        end
    end

    function Live.join_cache_readiness(state, readiness)
        state.readiness = readiness
        if state.denied_signature and readiness.known and readiness.signature ~= state.denied_signature then
            state.denial_context_changed = true
        end
    end

    function Live.join_departure_step(state, now)
        if state.leave_done or state.leave_owner == nil then return true end
        if not Live.join_intent_valid(state) then return false end
        local owner = Live.org_owner(state.local_id)
        state.owner_readback = owner
        if owner == state.boss_id then return false end -- observe target convergence; never leave it
        if owner == -1 then
            local removed
            if state.leave_owner == state.local_id then
                removed = Live.boss_roster_empty(state.local_id)
            else
                local previous = Live.remote_identity(state.leave_owner)
                if previous and (previous.rid ~= state.leave_identity.rid or previous.cxn ~= state.leave_identity.cxn) then
                    removed = true
                elseif previous then
                    removed = Live.boss_has_goon(state.leave_owner, state.local_id) == false
                elseif type(invoke_bool_detail) == "function" then
                    local active, raw, err = invoke_bool_detail(0xB8DFD30D6973E135, state.leave_owner)
                    removed = err == nil and active == false and (raw == false or raw == 0)
                end
            end
            if not Live.join_intent_valid(state) then return false end
            if removed == true then
                state.leave_done = true
                state.next_attempt_ms = 0
                Live.join_status(state, "READY",
                    "Previous organization departure confirmed; joining the selected organization.")
                return true
            end
            Live.join_status(state, "LEAVING", "Waiting for the previous organization roster to clear.")
            return false
        end
        if owner ~= nil and owner ~= state.leave_owner then
            Live.finish_join_organization("your organization changed while departure was pending", false, false, state)
            return false
        end
        if owner == nil or not Live.remote_same(state.leave_owner, state.leave_identity) then
            Live.join_status(state, "WAITING_DEPARTURE", "Waiting for the original organization identity.")
            return false
        end
        if Live.join_cleanup ~= nil or State.join_cleanup_pending == true then
            Live.join_status(state, "WAITING_CLEANUP", "Waiting for the previous organization request to be restored.")
            return false
        end
        if state.leave_inflight or now < (state.leave_next_ms or 0) then return false end
        -- This event requests the LOCAL freemode instance to run its complete
        -- boss/member departure path (func_25133 -> func_9195(5) -> func_11313).
        -- It does not assign Boss, edit a roster, or impersonate another sender.
        state.leave_inflight = true
        state.leave_attempts = (state.leave_attempts or 0) + 1
        state.leave_next_ms = now + 30000
        Live.join_status(state, "LEAVING", "Leaving your current organization automatically.")
        local ok, result = Live.action_send(state.local_id, { Live.ORG_DISMISS_EVENT, state.local_id, 0 }, function()
            if not Live.join_intent_valid(state) or not state.leave_inflight or state.leave_done
                or not Live.remote_same(state.leave_owner, state.leave_identity)
                or not Live.join_intent_valid(state) then
                return false
            end
            -- The identity observations above can re-enter callbacks. Check
            -- local membership last, then inspect only captured Lua state.
            local current_owner = Live.org_owner(state.local_id)
            return current_owner == state.leave_owner and State.join_organization == state
                and state.active == true and state.generation == Live.action_generation
                and not Live.join_stopped and state.leave_inflight and not state.leave_done
                and Live.join_cleanup == nil and State.join_cleanup_pending ~= true
        end)
        state.leave_inflight = false
        if not Live.join_intent_valid(state) then return false end
        state.leave_result = result
        if not ok then
            Live.join_status(state, "WAITING_DEPARTURE",
                "Departure dispatch was not confirmed; waiting before another attempt.")
        end
        return false
    end

    -- END ORGANIZATION_JOIN47_READINESS

    function Live.org_join_response(player_id)
        -- Supplied Enhanced func_25147 -> func_9197, read by func_12046:
        -- BossGoon.f_4 bit 7 = accepted; bit 8 = cannot accept now.
        -- Read only: freemode owns clearing these transient response bits.
        local index = Live.org_index(player_id, 4)
        local flags = index and Live.read_global_int(index)
        if type(flags) ~= "number" or flags % 1 ~= 0 then return nil end
        return (flags & (1 << 7)) ~= 0, (flags & (1 << 8)) ~= 0
    end

    function Live.join_intent_valid(state)
        if Live.join_stopped or State.join_organization ~= state or not Live.action_valid(state) then return false end
        if Live.org_owner(state.selected_id) ~= state.boss_id
            or Live.org_owner(state.boss_id) ~= state.boss_id then
            return false
        end
        -- Global/identity getters may re-enter callbacks. The captured intent
        -- must still own this action after every callback-capable observation.
        return Live.action_valid(state) and State.join_organization == state and state.active == true
            and not Live.join_stopped
    end

    function Live.clear_join_toggle(state)
        local feature = state and state.feature
        if state then state.feature = nil end
        if feature then
            pcall(function()
                local enabled = feature:IsToggled()
                local current = State.join_organization
                if enabled and not (current ~= state and current and current.active and current.feature == feature) then
                    feature:Toggle(false)
                end
            end)
        end
    end

    function Live.finish_join_organization(reason, success, quiet, expected)
        local state = expected or State.join_organization
        if type(state) ~= "table" or State.join_organization ~= state or state.active ~= true then return end
        state.active, state.attempt_active = false, false
        state.phase, state.detail = success == true and "JOINED" or "STOPPED", tostring(reason)
        state.next_attempt_ms, state.next_check_ms = nil, nil
        local joining_now
        if success ~= true then
            if state.join_request_owned then Live.restore_join_request(state) end
            if state.join_restore_pending then
                reason = tostring(reason) ..
                    "; local join prerequisite restoration pending"
            end
        elseif state.join_write_inflight and state.join_request_owned then
            -- Membership may converge in a reentrant callback before a late
            -- prerequisite write commits. That write still needs settlement.
            Live.restore_join_request(state)
        elseif not state.join_restore_pending then
            -- Actual owner + roster acceptance transfers this handshake to GTA.
            -- A previously queued restoration debt still drains independently.
            state.join_request_owned = false
            state.join_cleanup_status = "CONSUMED_BY_FREEMODE"
        end
        if Live.action_local_same(state) then
            state.owner_readback = Live.org_owner(state.local_id) or -1
            state.roster_readback = Live.boss_has_goon(state.boss_id, state.local_id)
            if state.joining_index then joining_now = Live.read_global_int(state.joining_index) end
        end
        Live.clear_join_toggle(state)
        log_info(("Join Their CEO / MC finished: selected=%s boss=%s bossId=%s attempts=%s localOwnerBefore=%s localOwnerAfter=%s roster=%s joiningBefore=%s joiningAfter=%s event=%s eventResult=%s reason=%s success=%s source=supplied-enhanced-freemode-handshake.")
            :format(tostring(state.selected_id), tostring(state.boss_name), tostring(state.boss_id),
                tostring(state.attempts or 0),
                tostring(state.local_owner_before), tostring(state.owner_readback),
                tostring(state.roster_readback), tostring(state.original_joining_boss),
                tostring(joining_now), tostring(Live.ORG_JOIN_REQUEST_EVENT),
                tostring(state.event_result), tostring(reason), tostring(success)))
        if quiet ~= true then
            local message = success
                and ("Joined %s's CEO / MC; the join toggle is now off."):format(state.boss_name)
                or ("Join Their CEO / MC stopped: %s."):format(tostring(reason))
            toast(message, 7500, success and "success" or "info")
        end
    end

    function Live.quiesce_join_organization(reason)
        -- Terminal disposal is Lua-only. The gameplay drain owns restoration.
        Live.join_stopped = true
        local state = State.join_organization
        if type(state) ~= "table" then return end
        state.active, state.attempt_active = false, false
        state.next_attempt_ms, state.next_check_ms = nil, nil
        state.stop_reason = reason
        state.phase, state.detail = "STOPPED", tostring(reason)
        if state.join_request_owned then
            Live.join_cleanup = state
            state.join_restore_pending = true
            state.join_cleanup_status = "RESTORE_PENDING"
            State.join_cleanup_pending = true
        end
    end

    function Live.stop_join_organization(player_id, feature)
        local state = State.join_organization
        if type(state) ~= "table" or not state.active or state.selected_id ~= Live.remote_player_index(player_id) then return false end
        Live.finish_join_organization("disabled for the selected player", false, false, state)
        return true
    end

    function Live.settle_join_attempt(state, reason, now)
        if State.join_organization ~= state or state.active ~= true or not state.attempt_active then return end
        state.attempt_active = false
        local delay = math.min(30000, 1000 * (2 ^ math.min(5, math.max(0, (state.attempts or 1) - 1))))
        state.next_attempt_ms, state.next_check_ms = now + delay, now + 100
        state.retry_reason = reason
        Live.join_status(state, state.denied_signature and "WAITING_REMOTE_ADMISSION" or "WAITING_RETRY", reason)
        if state.join_request_owned then Live.restore_join_request(state) end
        log_info(("Join Their CEO / MC waiting: selected=%s boss=%s attempt=%s reason=%s restorationPending=%s")
            :format(tostring(state.selected_id), tostring(state.boss_id), tostring(state.attempts),
                tostring(reason), tostring(state.join_restore_pending == true)))
    end

    function Live.try_join_organization(state, now)
        if not Live.join_intent_valid(state) or state.attempt_active or state.join_request_owned
            or Live.join_cleanup ~= nil or State.join_cleanup_pending == true
            or now < (state.next_attempt_ms or 0) then
            return
        end
        -- Wait for a free local handshake and fully settled membership/response
        -- state. We never clear freemode response bits or alter a boss roster.
        if Live.org_owner(state.local_id) ~= -1 or Live.boss_has_goon(state.boss_id, state.local_id) ~= false then return end
        local readiness = Live.org_join_readiness(state.boss_id)
        if not Live.join_intent_valid(state) then return end
        Live.join_cache_readiness(state, readiness)
        if not readiness.known or readiness.busy or readiness.capacity ~= true then
            Live.join_status(state,
                readiness.busy and "WAITING_ACTIVITY" or readiness.capacity == false and "WAITING_CAPACITY" or
                "WAITING_DATA", readiness.detail)
            return
        end
        -- A denial with the same advertised roster/activity is not progress.
        -- Rearm immediately after a meaningful change; otherwise only a bounded
        -- 30-second probe can notice a remote reservation which is not published.
        if state.denied_signature == readiness.signature and not state.denial_context_changed
            and now < (state.denied_probe_ms or 0) then
            Live.join_status(state, "WAITING_REMOTE_ADMISSION",
                "The organization rejected the join; waiting for its admission state to change.")
            return
        end
        local accepted, refused = Live.org_join_response(state.local_id)
        if accepted ~= false or refused ~= false then
            Live.join_status(state, "WAITING_RESPONSE", "Waiting for freemode to finish its previous join response.")
            return
        end
        local index = Live.org_index(state.local_id, Live.ORG_JOINING_BOSS_OFFSET)
        local original = index and Live.read_global_int(index)
        local ptr = index and Live.global_ptr(index)
        if original ~= -1 or not ptr or not Live.join_intent_valid(state) then
            Live.join_status(state, "WAITING_HANDSHAKE", "Waiting for the existing local organization request to finish.")
            return
        end
        if Live.global_ptr(index) ~= ptr or Live.read_global_int(index) ~= -1
            or not Live.join_intent_valid(state) then
            return
        end
        state.joining_index, state.joining_ptr, state.original_joining_boss = index, ptr, original
        state.attempt_active, state.join_request_owned = true, true
        state.attempts = (state.attempts or 0) + 1
        state.started_ms, state.until_ms, state.last_poll_ms = now, now + 10000, -100000
        state.response_accepted, state.response_refused = false, false
        state.handshake_consumed, state.consumed_ms = false, nil
        state.join_cleanup_status, state.join_cleanup_retry_at = nil, nil
        state.event_result = nil
        state.request_signature = readiness.signature
        state.denied_signature, state.denied_probe_ms, state.denial_context_changed = nil, nil, false
        -- Ownership is recorded before the write, including write-then-throw or
        -- an off/session callback inside the host setter.
        state.join_write_inflight = true
        Live.join_status(state, "JOINING",
            "Joining the selected organization; waiting for its owner and roster to confirm.")
        if not Live.join_intent_valid(state) or not state.attempt_active then
            state.join_write_inflight = false
            if state.join_request_owned then Live.restore_join_request(state) end
            return
        end
        local written = Live.write_global_int(index, state.boss_id)
        state.join_write_inflight = false
        if State.join_organization ~= state or state.active ~= true or not state.attempt_active then
            if state.join_request_owned then Live.restore_join_request(state) end
            return
        end
        if not written then
            Live.settle_join_attempt(state, "JoiningBoss prerequisite write was not confirmed", now)
            return
        end
        local function dispatch_ready()
            if not Live.join_intent_valid(state) or not state.attempt_active or not state.join_request_owned
                or state.join_restore_pending or Live.join_cleanup ~= nil then
                return false
            end
            local yes, no = Live.org_join_response(state.local_id)
            local ready = Live.org_join_readiness(state.boss_id)
            if yes ~= false or no ~= false or Live.org_owner(state.local_id) ~= -1
                or Live.boss_has_goon(state.boss_id, state.local_id) ~= false
                or not ready.known or ready.busy or ready.capacity ~= true then
                return false
            end
            return Live.global_ptr(index) == ptr and Live.read_global_int(index) == state.boss_id
                and Live.join_intent_valid(state) and state.attempt_active and state.join_request_owned
        end
        local ok, result = Live.action_send(state.boss_id,
            { Live.ORG_JOIN_REQUEST_EVENT, state.local_id, 0 }, dispatch_ready)
        if State.join_organization ~= state or state.active ~= true or not state.attempt_active then return end
        state.event_result = result
        local owner, roster = Live.org_owner(state.local_id), Live.boss_has_goon(state.boss_id, state.local_id)
        if not Live.join_intent_valid(state) then
            Live.finish_join_organization("the captured player or organization changed", false, false, state)
        elseif owner == state.boss_id and roster == true then
            state.owner_readback, state.roster_readback = owner, roster
            Live.finish_join_organization("freemode accepted the request", true, false, state)
        elseif not ok then
            Live.settle_join_attempt(state, "organization request dispatch was not confirmed: " .. tostring(result), now)
        end
    end

    function Live.tick_join_organization(now)
        now = tonumber(now) or now_ms()
        Live.retry_join_cleanup(now)
        local state = State.join_organization
        if type(state) ~= "table" or state.active ~= true then return end
        if not Live.join_intent_valid(state) then
            Live.finish_join_organization("the captured player or organization is no longer available", false, false,
                state)
            return
        end
        if state.attempt_active then
            -- Freemode can consume transient response bits between membership
            -- polls. Remember responses every runtime tick while one is in flight.
            local accepted, refused = Live.org_join_response(state.local_id)
            if accepted then state.response_accepted = true end
            if refused and not accepted then state.response_refused = true end
            if not state.response_refused and not Live.action_poll_due(state, now) then return end
        elseif state.next_check_ms and now >= state.next_check_ms - 100 and now < state.next_check_ms then
            return
        else
            state.next_check_ms = now + 100
        end
        local owner = Live.org_owner(state.local_id)
        local roster = Live.boss_has_goon(state.boss_id, state.local_id)
        if not Live.join_intent_valid(state) then
            Live.finish_join_organization("the captured player or organization changed", false, false, state)
            return
        end
        state.owner_readback, state.roster_readback = owner or -1, roster
        if owner == state.boss_id and roster == true then
            Live.finish_join_organization("freemode accepted the request", true, false, state)
            return
        end
        if state.leave_owner ~= nil and not state.leave_done then
            -- Do not abandon a current organization while the destination is
            -- already known to be full/busy. Keep the user's one-click intent.
            local readiness = Live.org_join_readiness(state.boss_id)
            if not Live.join_intent_valid(state) then return end
            Live.join_cache_readiness(state, readiness)
            if owner == state.leave_owner and (not readiness.known or readiness.busy or readiness.capacity ~= true) then
                Live.join_status(state,
                    readiness.busy and "WAITING_ACTIVITY" or readiness.capacity == false and "WAITING_CAPACITY" or
                    "WAITING_DATA", readiness.detail)
                return
            end
            if not Live.join_departure_step(state, now) then return end
            owner = Live.org_owner(state.local_id)
        end
        if owner ~= nil and owner >= 0 and owner ~= state.boss_id then
            Live.finish_join_organization("you joined another organization", false, false, state)
            return
        end
        if not state.attempt_active then
            Live.try_join_organization(state, now); return
        end
        if state.response_refused then
            state.denied_signature = state.request_signature
            state.denied_probe_ms = now + 30000
            state.denial_context_changed = false
            Live.settle_join_attempt(state,
                "The organization refused admission; a free visible slot can still be reserved or unavailable.", now)
            return
        end
        if owner ~= state.boss_id and roster == false and not state.response_accepted
            and Live.org_has_capacity(state.boss_id) == false then
            Live.settle_join_attempt(state, "the organization is full", now)
            return
        end
        local joining_now = Live.read_global_int(state.joining_index)
        if joining_now ~= nil and joining_now ~= -1 and joining_now ~= state.boss_id then
            Live.settle_join_attempt(state, "another local handshake replaced this request", now)
            return
        end
        if joining_now == -1 then
            state.handshake_consumed = true
            state.consumed_ms = state.consumed_ms or now
            if not state.response_accepted and owner == -1 and roster == false
                and now - state.consumed_ms >= 1000 then
                Live.settle_join_attempt(state, "freemode ended the request without membership", now)
                return
            end
        end
        if now >= (tonumber(state.until_ms) or 0) then
            Live.settle_join_attempt(state, owner == state.boss_id
                and "waiting for the boss roster to confirm membership" or "freemode did not confirm membership", now)
        end
    end

    function Live.start_join_organization(player_id, feature)
        if Live.join_stopped then return false end
        player_id = Live.remote_player_index(player_id)
        local pending = State.join_organization
        if pending and pending.active == true then
            -- Repeated enabled callbacks are idempotent: do not recapture an
            -- identity, reset a timer or send another request.
            if pending.selected_id == player_id then return true end
            toast("Disable the current organization join toggle before selecting another player.", 5500, "info")
            return false
        end
        local available, why = Live.selected_action_availability("join_organization", player_id)
        if not available then
            toast(why, 5500, "warning"); return false
        end
        local request = Live.action_identity(player_id)
        if not request then
            toast("Selected player or local connection identity is unavailable.", 6500, "warning")
            return false
        end
        if not Live.script_globals_ready() or not gta or type(gta.TriggerScriptEvent) ~= "function" then
            toast("Join Their CEO / MC requires valid freemode globals and script events.", 7000, "warning")
            return false
        end
        local local_id, boss_id = request.local_id, Live.org_owner(player_id)
        if not boss_id or boss_id < 0 or boss_id > 31 or not player_available(boss_id)
            or Live.org_owner(boss_id) ~= boss_id then
            toast("The selected player is not in an active CEO / MC organization.", 7000, "warning")
            return false
        end
        if boss_id == local_id or (Live.org_owner(local_id) == boss_id and Live.boss_has_goon(boss_id, local_id) == true) then
            toast("You are already in that CEO / MC organization.", 5500, "info")
            return true
        end
        local local_owner = Live.org_owner(local_id)
        if local_owner == nil then
            toast("Your current organization state is unavailable; nothing was changed.", 6500, "warning")
            return false
        end
        if local_owner >= 0 and local_owner ~= boss_id then
            request.leave_owner, request.leave_identity = local_owner, Live.remote_identity(local_owner)
            if not request.leave_identity then
                toast("Your current organization identity is unavailable; nothing was changed.", 6500, "warning")
                return false
            end
        end
        request.owner_id, request.owner_identity = boss_id, Live.remote_identity(boss_id)
        request.selected_id, request.boss_id, request.boss_name = player_id, boss_id, player_name(boss_id)
        if not request.owner_identity or not Live.action_valid(request)
            or Live.org_owner(player_id) ~= boss_id or Live.org_owner(boss_id) ~= boss_id
            or not Live.action_valid(request) or Live.join_stopped then
            toast("Organization request identity changed; no state was changed.", 6500, "warning")
            return false
        end
        if feature then
            local ok, enabled = pcall(function() return feature:IsToggled() end)
            if not ok or enabled ~= true then return false end
        end
        -- A callback may have committed another intent or disabled this feature
        -- while identity/global reads were in progress. Never overwrite it.
        if State.join_organization ~= pending or (pending and pending.active == true) or Live.join_stopped then return false end
        request.feature, request.attempt_active, request.join_request_owned = feature, false, false
        request.attempts, request.next_attempt_ms, request.next_check_ms = 0, 0, 0
        request.owner_readback, request.roster_readback, request.local_owner_before = local_owner, false, local_owner
        request.phase, request.detail = "PREPARING", "Preparing the selected organization join."
        request.leave_attempts, request.leave_next_ms = 0, 0
        State.join_organization = request
        toast(
            ("Joining %s's CEO / MC; your current organization will be left automatically when the destination is available.")
            :format(request.boss_name), 6500, "info")
        Live.tick_join_organization(now_ms())
        return true
    end

    function Live.interior_provider_dispatch(kind, request)
        if Live.interior_dispatching then return false, "interior action is already dispatching" end
        if type(Live.remote_find_provider) ~= "function" then return nil, "no interior provider" end
        local provider, why = Live.remote_find_provider(request.player_id, kind)
        if not provider then return nil, why end
        if not Live.action_valid(request) then return false, "player identity changed" end
        local ok, fresh = pcall(feature_mgr.GetFeature, provider.lookup_hash, provider.lookup_index)
        local checked = ok and Live.remote_action_info(fresh, request.player_id, kind) or nil
        if not checked or checked.serial ~= provider.serial or checked.hash ~= provider.hash
            or not Live.action_valid(request) then
            return false, "interior action changed before dispatch"
        end
        if request.interior_mode == "simple" and kind == "interior_kick"
            and checked.action_name ~= "kick from interior" then
            return nil, "apartment-only provider does not cover this simple interior"
        end
        -- Use the provider's GUI-equivalent queue; never alter selected player.
        Live.interior_dispatching = true
        local sent, result = pcall(fresh.OnClick, fresh)
        Live.interior_dispatching = false
        if not sent or result == false or not Live.action_valid(request) then
            return false, "interior provider rejected or identity changed"
        end
        return true, checked.name
    end

    function Live.entry_control_ready(player_id)
        -- IS_PLAYER_CONTROL_ON(Player) is a read-only documented native.
        -- A matching network instance can precede the end of the entry task;
        -- never force control ON to manufacture a completed admission.
        local value, raw, err = invoke_bool_detail(0x49C32D60007AFA47, player_id)
        return err == nil and (raw == true or raw == 1) and value == true
    end

    -- One local exit owner serves selected-player entry and the board trips.
    -- Classic properties use an exact local-player provider when available;
    -- simple interiors use the source-verified ordinary exit request input.
    function Live.local_exit_observe(s)
        local property = player_property(s.local_id)
        local simple = Live.player_simple_interior(s.local_id)
        local physical = Live.physical_interior(s.local_id)
        if property == nil or not simple or simple.index == nil or simple.owner == nil or physical == nil then
            return nil, "Waiting for synchronized interior data."
        end
        local outside = property == -1 and simple.index == -1 and simple.owner == -1 and physical == 0
        local control = Live.entry_control_ready(s.local_id)
        if outside and control then
            local ped = local_ped()
            local loaded, loaded_raw, loaded_err = invoke_bool_detail(0xE9676F61BC0B3321, ped)
            local waiting, waiting_raw, waiting_err = invoke_bool_detail(0xD05BFF0C0A12C68F, ped)
            control = loaded_err == nil and (loaded_raw == true or loaded_raw == 1) and loaded == true
                and waiting_err == nil and (waiting_raw == false or waiting_raw == 0) and waiting == false
        end
        local mode = simple.active and "simple" or property > 0 and "property" or outside and "outside" or "unknown"
        local key = mode == "simple" and
            table.concat({ simple.index, simple.owner, simple.instance or -1, simple.subtype or -1 }, ":")
            or mode == "property" and table.concat({ property, Live.property_instance(s.local_id) or -1 }, ":") or mode
        return {
            outside = outside,
            control = control,
            mode = mode,
            key = key,
            simple = simple,
            property = property,
            physical = physical,
            changed = s.origin_key ~= nil and mode ~= "outside" and mode ~= "unknown" and key ~= s.origin_key
        }
    end

    function Live.local_exit_valid(s)
        return started and not Live.local_exit_stopped and State.runtime_writes_suspended ~= true
            and Live.action_source_ready() and Live.action_local_same(s)
            and local_ped() == s.ped and entity_exists(s.ped)
            and invoke_int(H.GET_ENTITY_MODEL, s.ped) == s.model
    end

    function Live.local_exit_source()
        local raw = module_context and module_context.Raw or {}
        local memory, locals, utils = raw.Memory, raw.ScriptLocal, raw.Utils
        if not memory or type(memory.ScanScript) ~= "function" or type(memory.ReadUByte) ~= "function"
            or not locals or type(locals.GetPtr) ~= "function" or not utils or type(utils.Joaat) ~= "function" then
            return false
        end
        local patterns = {
            { "freemode",                "2D 01 03 00 00 5D 2C 93 08 06 56 11 00 72 61 F2 C5 1D 48 B4 0F 38 00 61 F2 C5 1D 48 B5 0F 2E 01 00" },
            { "am_mp_smpl_interior_int", "61 F2 C5 1D 47 B4 0F 56 DD 02 62 B9 27 1C 5D C8 35 20 58 77 00 4F 07 01 41 03 76 57 6E 00" },
            { "am_mp_smpl_interior_int", "71 61 F2 C5 1D 48 B4 0F 71 61 F2 C5 1D 48 B5 0F 72 4F 07 01 41 02 71 5D 2F 36 20 2E 00 00" },
        }
        for _, row in ipairs(patterns) do
            local hash = utils.Joaat(row[1])
            local ok, thread = pcall(locals.GetPtr, hash, 0)
            if not ok or type(thread) ~= "number" or thread < 65536 or thread % 8 ~= 0
                or invoke_int(0x2C83A9DA6BFFC4F9, hash) ~= 1 then
                return false
            end
            local good, ptr = pcall(memory.ScanScript, hash, row[2])
            if not good or type(ptr) ~= "number" or ptr < 65536 then return false end
            local offset = 0
            for byte in row[2]:gmatch("%x%x") do
                local read, value = pcall(memory.ReadUByte, ptr + offset)
                if not read or value ~= tonumber(byte, 16) then return false end
                offset = offset + 1
            end
            local same, current = pcall(locals.GetPtr, hash, 0)
            if not same or current ~= thread or invoke_int(0x2C83A9DA6BFFC4F9, hash) ~= 1 then return false end
        end
        return true
    end

    Live.local_exit = Module.NewLocalInteriorExit({
        Capture = function()
            if not started or Live.local_exit_stopped or State.runtime_writes_suspended == true
                or not Live.action_source_ready() then
                return nil, "Interior exit requires the validated freemode source and an active player module."
            end
            local pid = Live.remote_player_index(local_player_id())
            local identity = pid and Live.remote_identity(pid)
            local ped = local_ped()
            if not identity or not entity_exists(ped) then return nil, "Your character identity is unavailable." end
            local s = {
                local_id = pid,
                player_id = pid,
                identity = identity,
                local_identity = identity,
                generation = Live.action_generation,
                ped = ped,
                model = invoke_int(H.GET_ENTITY_MODEL, ped),
                active = true
            }
            local o, why = Live.local_exit_observe(s)
            if not o then return nil, why end
            s.origin_key, s.origin_mode = o.key, o.mode
            return s
        end,
        Valid = Live.local_exit_valid,
        Observe = Live.local_exit_observe,
        Request = function(s, current)
            if not current() then return false, "The interior trip changed." end
            local o = Live.local_exit_observe(s)
            if not o or o.changed then return false, "The current interior changed before its exit request." end
            if o.outside then return nil, "Confirming that the previous interior has closed." end
            if not o.control then return nil, "Waiting for the current transition to finish." end
            if o.mode == "simple" then
                if not Live.local_exit_source() or not current() then
                    return false,
                        "The simple-interior exit controller could not be verified."
                end
                local index = 1951218 + 4020
                local pending = Live.read_global_int(index)
                if pending == 1 then return true, "Observing GTA's existing interior exit request." end
                if pending ~= 0 or Live.read_global_int(1951218 + 773) ~= 0 then
                    return nil,
                        "Waiting for GTA's current interior operation."
                end
                local fresh = Live.local_exit_observe(s)
                if not fresh or fresh.key ~= s.origin_key or not fresh.control or not current()
                    or Live.read_global_int(index) ~= 0 then
                    return false, "The interior exit context changed before commit."
                end
                -- func_2505(0)'s only needed input. f4021 already defaults to 0;
                -- it selects exit text, not the destination or admission state.
                if Live.read_global_int(index + 1) ~= 0 then
                    return nil,
                        "Waiting for another interior exit request to settle."
                end
                s.commit_attempted = true
                pcall(script_global.SetInt, index, 1)
                -- A setter may commit then throw, or GTA may consume the input
                -- before readback. Never replay it; observe the actual exit.
                return true, "Normal GTA exit requested; waiting for exterior registration."
            elseif o.mode == "property" then
                s.interior_mode = "property"
                if not current() then return false, "The interior trip changed." end
                s.commit_attempted = true
                local ok, why = Live.interior_provider_dispatch("interior_kick", s)
                if ok ~= true then
                    return false,
                        "This property's normal exit is unavailable: " ..
                        tostring(why or "no matching local-player exit action")
                end
                return true, "Local property exit submitted; waiting for exterior registration."
            end
            return false, "The current interior has no verified GTA exit controller."
        end,
    })

    function Live.enter_intent_valid(state)
        if State.enter_interior ~= state or not state.active or not Live.action_valid(state) then return false end
        if state.mode == "simple" then
            local current = Live.player_simple_interior(state.player_id)
            if not current or not current.active or current.index ~= state.simple_index or current.owner ~= state.simple_owner
                or current.instance ~= state.instance_id or current.subtype ~= state.subtype then
                return false
            end
        elseif player_property(state.player_id) ~= state.property
            or Live.property_instance(state.player_id) ~= state.property_instance
            or Live.property_owner(state.player_id) ~= state.owner_id then
            return false
        end
        return State.enter_interior == state and state.active == true and state.generation == Live.action_generation
    end

    function Live.quiesce_enter_interior(reason)
        -- Worker/terminal paths revoke intent in Lua only. The gameplay
        -- finisher owns game observations and user-facing result logging.
        local state = State.enter_interior
        if type(state) ~= "table" or state.active ~= true then return end
        state.active = false; state.phase = "cancelled"; state.detail = tostring(reason)
        if state.exit_token then Live.local_exit.Cancel(state.exit_token, reason) end
    end

    local function finish_enter_interior(reason, success, quiet)
        local state = State.enter_interior
        if type(state) ~= "table" or state.active ~= true then return end
        state.active = false
        state.phase = success and "complete" or "failed"; state.detail = tostring(reason)
        if state.exit_token then Live.local_exit.Cancel(state.exit_token, reason) end
        local message = success
            and ("Entered %s's current %s interior through freemode.")
            :format(state.player_name, state.mode)
            or ("Enter Interior failed for %s: %s."):format(state.player_name, tostring(reason))
        local local_simple = Live.player_simple_interior(local_player_id())
        log_info(("Enter Interior finished: target=%s id=%s mode=%s property=%s simple=%s owner=%s instance=%s subtype=%s reason=%s success=%s eventResult=%s contextSeen=%s localProperty=%s localSimple=%s localOwner=%s physicalInterior=%s backend=%s deadlineMs=%s source=supplied-enhanced-freemode-events.")
            :format(tostring(state.player_name), tostring(state.player_id), tostring(state.mode),
                tostring(state.property), tostring(state.simple_index), tostring(state.simple_owner),
                tostring(state.instance_id), tostring(state.subtype),
                tostring(reason), tostring(success), tostring(state.event_result),
                tostring(state.context_seen), tostring(player_property(local_player_id())),
                tostring(local_simple and local_simple.index), tostring(local_simple and local_simple.owner),
                tostring(entity_exists(local_ped()) and invoke_int(H.GET_INTERIOR_FROM_ENTITY, local_ped()) or 0),
                tostring(state.backend), tostring(state.until_ms)))
        if quiet ~= true then toast(message, 7500, success and "success" or "warning") end
    end

    local function tick_enter_interior(now)
        local state = State.enter_interior
        if type(state) ~= "table" or state.active ~= true then return end
        now = tonumber(now) or now_ms()
        if not Live.action_valid(state) then
            finish_enter_interior("player or session identity changed", false); return
        end
        if not Live.action_poll_due(state, now) then return end
        local target_simple = Live.player_simple_interior(state.player_id)
        if state.mode == "simple" and (not target_simple or not target_simple.active
                or target_simple.index ~= state.simple_index or target_simple.owner ~= state.simple_owner
                or target_simple.instance ~= state.instance_id or target_simple.subtype ~= state.subtype) then
            finish_enter_interior("target interior context changed or became unavailable", false); return
        end
        if state.mode == "property" and (player_property(state.player_id) ~= state.property
                or Live.property_instance(state.player_id) ~= state.property_instance
                or Live.property_owner(state.player_id) ~= state.owner_id) then
            finish_enter_interior("target property/instance changed or became unavailable", false); return
        end
        if state.phase == "leaving_current" then
            local exit = Live.local_exit.Poll(state.exit_token, now)
            state.detail = exit.detail
            if exit.status == "COMPLETE" then
                state.phase = "dispatch_pending"
            elseif not exit.active then
                finish_enter_interior(exit.detail, false); return
            else
                return
            end
        end
        if state.phase == "dispatch_pending" then
            -- Retain the captured target; changing selection never redirects a
            -- queued trip. Commit once, including callback re-entry.
            state.phase = "dispatching"; state.detail = "Requesting the selected interior after the exit."
            local ok, result = Live.action_send(state.local_id, state.entry_args, function()
                if not Live.enter_intent_valid(state) then return false end
                local current = Live.local_exit_observe(state)
                return current ~= nil and current.outside and current.control and Live.enter_intent_valid(state)
            end)
            if State.enter_interior ~= state or not state.active then return end
            if not ok then
                finish_enter_interior("invitation dispatch failed: " .. tostring(result), false); return
            end
            state.event_result = result; state.phase = "entering"; state.backend = "cscript-freemode-event"
            state.until_ms = now + 30000; state.detail = "Waiting for GTA interior admission and player control."
            return
        elseif state.phase == "dispatching" then
            return
        end
        local local_property = player_property(state.local_id)
        local local_simple = Live.player_simple_interior(state.local_id)
        local ped = local_ped()
        local physical_interior = Live.physical_interior(state.local_id) or 0
        if state.mode == "simple" then
            if local_simple and local_simple.active == true
                and local_simple.index == state.simple_index
                and local_simple.owner == state.simple_owner
                and local_simple.instance == state.instance_id and local_simple.subtype == state.subtype then
                state.context_seen = true
                if physical_interior > 0 and Live.entry_control_ready(state.local_id) then
                    finish_enter_interior("owner/instance and physical interior matched; control restored", true)
                    return
                end
            end
        else
            local invite_property = Live.read_global_int(Live.INVITE_CONTEXT_PROPERTY)
            local entry_property = Live.read_global_int(Live.ENTRY_CONTEXT_PROPERTY)
            if invite_property == state.property or entry_property == state.property then
                state.context_seen = true
            end
            if local_property == state.property
                and Live.property_instance(state.local_id) == state.property_instance
                and Live.property_owner(state.local_id) == state.owner_id
                and physical_interior > 0 and Live.entry_control_ready(state.local_id) then
                finish_enter_interior("property/instance and physical interior matched; control restored", true)
                return
            end
        end
        if now >= (tonumber(state.until_ms) or 0) then
            local detail = state.context_seen
                and "freemode accepted the context but the transition/control did not finish in time"
                or "freemode did not expose an accepted invitation context"
            finish_enter_interior(detail, false)
        end
    end

    local function start_enter_interior(player_id)
        player_id = Live.remote_player_index(player_id)
        local available, why = Live.selected_action_availability("enter_interior", player_id)
        if not available then
            toast(why, 5500, "warning")
            return false
        end
        local request = Live.action_identity(player_id)
        if not request then
            toast("Selected player or local connection identity is unavailable.", 6500, "warning")
            return false
        end
        if not Live.script_globals_ready() then
            toast("Enter Interior requires valid freemode script globals.", 6500, "warning")
            return false
        end
        -- The exact player-bound provider does not require our event API.
        -- Only the independent fallback validates TriggerScriptEvent at dispatch.
        if State.enter_interior.active then
            toast("An interior entry is already pending.", 5000, "info"); return false
        end
        local snapshot = player_snapshot(player_id)
        local property = player_property(player_id)
        local property_instance = Live.property_instance(player_id)
        local simple = Live.player_simple_interior(player_id)
        local simple_index = simple and tonumber(simple.index) or -1
        local local_id = tonumber(local_player_id())
        if not local_id or local_id < 0 or local_id > 31 then
            toast("Enter Interior could not resolve the local network player.", 6500, "warning")
            return false
        end
        local args, mode, instance_id, subtype, simple_owner
        local observing_existing = false
        if simple and simple.active == true then
            mode = "simple"
            instance_id = tonumber(simple.instance) or 0
            simple_owner = tonumber(simple.owner)
            subtype = tonumber(simple.subtype) or -1
            local current = Live.player_simple_interior(local_id)
            if current and current.active == true and current.index == simple_index
                and current.owner == simple_owner and current.instance == instance_id and current.subtype == subtype
                and (Live.physical_interior(local_id) or 0) > 0 then
                if Live.entry_control_ready(local_id) then
                    toast("You are already in that interior.", 5000, "info"); return true
                end
                observing_existing = true
            end
            if not player_available(simple_owner) then
                toast("The synchronized owner of that simple interior is no longer in the session.", 7000, "warning")
                return false
            end
            request.owner_id, request.owner_identity = simple_owner, Live.remote_identity(simple_owner)
            if not request.owner_identity or simple.instance == nil or simple.subtype == nil then return false end
            -- func_203 maps 81/88 to mobile interiors (types 5/8), which
            -- require explicit coordinates. Other types let func_25008 select
            -- the real entrance via func_9860 instead of inside/MLO coordinates.
            local x, y, z = 0, 0, 0
            if simple_index == 81 or simple_index == 88 then
                x, y, z = Live.event_float32(snapshot and snapshot.x),
                    Live.event_float32(snapshot and snapshot.y), Live.event_float32(snapshot and snapshot.z)
                if x == nil or y == nil or z == nil then
                    toast("The selected mobile interior's coordinates are unavailable.", 7000, "warning")
                    return false
                end
            end
            local exit_type = tonumber(simple.exit_type)
            if not exit_type or exit_type % 1 ~= 0 or exit_type < 0 or exit_type > 15 then return false end
            -- f_12 selects the interior component; f_15 selects the variant
            -- encoded in the target's f_325.f_3 bits 28..31.
            args = {
                Live.SIMPLE_INTERIOR_EVENT, local_id, 0,
                simple_index, simple_owner, 0, 1,
                x, y, z, 0, instance_id,
                subtype,
                99999, 0, exit_type,
            }
        elseif property and property >= 1 and property <= 131 then
            mode = "property"
            instance_id, subtype = -1, -1
            if property_instance == nil then
                toast("The selected property's instance is unavailable.", 6500, "warning"); return false
            end
            if player_property(local_id) == property and Live.property_instance(local_id) == property_instance
                and Live.property_owner(local_id) ~= nil
                and Live.property_owner(local_id) == Live.property_owner(player_id)
                and invoke_int(H.GET_INTERIOR_FROM_ENTITY, local_ped()) > 0 then
                if Live.entry_control_ready(local_id) then
                    toast("You are already in that property.", 5000, "info"); return true
                end
                observing_existing = true
            end
            local property_owner = Live.property_owner(player_id)
            if property_owner == nil then
                toast("The property's owner is unavailable.", 6500, "warning"); return false
            end
            request.owner_id, request.owner_identity = property_owner, Live.remote_identity(property_owner)
            if not request.owner_identity then return false end
            -- freemode func_17810 uses entrance 0 for an ordinary invitation.
            -- func_25184/17811 consume the synchronized property variant.
            local variant = Live.read_global_int(Live.PROPERTY_BASE + 1 + player_id * Live.PROPERTY_STRIDE + 260 + 126)
            if type(variant) ~= "number" or variant % 1 ~= 0 or variant < -1 or variant > 2147483647 then variant = -1 end
            local owner_token = Live.read_global_int(2652584) == 32
                and Live.read_global_int(2652584 + 1 + property_owner * 3) or -1
            if type(owner_token) ~= "number" or owner_token % 1 ~= 0 or owner_token < -1 or owner_token > 2147483647 then
                toast("The property's owner context is unavailable.", 6500, "warning"); return false
            end
            args = {
                Live.PROPERTY_INVITE_EVENT, local_id, 0, property_owner, owner_token, variant,
                property, 0, 0, 0, 2,
            }
        else
            toast("The selected player's current freemode interior state is unavailable.", 7000, "warning")
            return false
        end
        if not Live.action_valid(request) then return false end
        -- Accept the trip now; its invitation waits for any local exit.
        -- The request always retains this player/owner/instance identity.
        request.interior_mode = mode
        local now = now_ms()
        State.enter_interior = {
            identity = request.identity,
            local_identity = request.local_identity,
            local_id = request.local_id,
            generation = request.generation,
            owner_id = request.owner_id,
            owner_identity = request.owner_identity,
            property_instance = property_instance,
            active = true,
            player_id = player_id,
            player_name = snapshot and snapshot.name or player_name(player_id),
            mode = mode,
            property = property or -1,
            simple_index = simple_index or -1,
            simple_owner = simple_owner or -1,
            instance_id = instance_id or -1,
            subtype = subtype or -1,
            started_ms = now,
            until_ms = now + 60000,
            backend = observing_existing and "existing-transition" or "cscript-freemode-event",
            phase = observing_existing and "entering" or "dispatch_pending",
            detail = observing_existing and "Waiting for the current entry to restore control." or
                "Preparing the selected interior trip.",
            entry_args = args,
            context_seen = false,
        }
        local state = State.enter_interior
        if not observing_existing then
            local local_context = Live.local_exit_observe(state)
            if not local_context then
                finish_enter_interior("local interior state is unavailable", false); return false
            end
            if not local_context.outside then
                local token, reason = Live.local_exit.Begin("Enter " .. state.player_name .. "'s interior", now,
                    function()
                        return Live.enter_intent_valid(state)
                    end)
                if not token then
                    finish_enter_interior(reason, false); return false
                end
                state.exit_token = token; state.phase = "leaving_current"
                state.detail = "Leaving your current interior before joining the selected player."
            end
        end
        toast(state.detail, 6000, "info")
        tick_enter_interior(now)
        return true
    end

    local function finish_kick_from_interior(reason, success, quiet)
        local state = State.kick_interior
        if type(state) ~= "table" or state.active ~= true then return end
        state.active = false
        local current = Live.player_simple_interior(state.player_id)
        local snapshot = player_available(state.player_id) and player_snapshot(state.player_id) or nil
        log_info(("Kick From Interior finished: target=%s id=%s simple=%s owner=%s instance=%s exitType=%s physicalBefore=%s currentSimple=%s currentOwner=%s currentInstance=%s physicalAfter=%s reason=%s success=%s command=%s eventResult=%s mode=%s property=%s source=interior-dispatch.")
            :format(tostring(state.player_name), tostring(state.player_id), tostring(state.simple_index),
                tostring(state.simple_owner), tostring(state.instance_id), tostring(state.exit_type),
                tostring(state.physical_before), tostring(current and current.index),
                tostring(current and current.owner), tostring(current and current.instance),
                tostring(snapshot and snapshot.interior),
                tostring(reason), tostring(success), tostring(state.command_ok), tostring(state.event_result),
                tostring(state.mode or "simple"), tostring(state.property)))
        if quiet ~= true then
            local message = success
                and ("Kick From Interior: observed %s outside."):format(state.player_name)
                or ("Kick From Interior failed for %s: %s."):format(state.player_name, tostring(reason))
            toast(message, 7000, success and "success" or "warning")
        end
    end

    local function tick_kick_from_interior(now)
        local state = State.kick_interior
        if type(state) ~= "table" or state.active ~= true then return end
        now = tonumber(now) or now_ms()
        if not Live.action_valid(state) then
            finish_kick_from_interior("selected player or session identity changed", false)
            return
        end
        if not Live.action_poll_due(state, now) then return end
        local current = Live.player_simple_interior(state.player_id)
        local snapshot = player_snapshot(state.player_id)
        local property = player_property(state.player_id)
        local outside = current and current.index == -1 and current.owner ~= nil
            and (state.mode ~= "property" or property == -1)
            and Live.physical_interior(state.player_id) == 0
        if outside then
            state.outside_since = state.outside_since or now
            if now - state.outside_since >= 250 then
                finish_kick_from_interior("outside state observed across multiple samples", true); return
            end
        else
            state.outside_since = nil
        end
        if now >= (tonumber(state.until_ms) or 0) then
            finish_kick_from_interior("freemode kept the target in the same interior instance", false)
        end
    end

    local function start_kick_from_interior(player_id)
        player_id = Live.remote_player_index(player_id)
        local available, why = Live.selected_action_availability("kick_from_interior", player_id)
        if not available then
            toast(why, 5500, "warning")
            return false
        end
        local request = Live.action_identity(player_id)
        if not request then
            toast("Selected player or local connection identity is unavailable.", 6500, "warning")
            return false
        end
        if not Live.script_globals_ready() then
            toast("Kick From Interior requires valid freemode globals.", 7000, "warning")
            return false
        end
        if State.kick_interior.active then
            toast("An interior kick is already pending.", 5000, "info"); return false
        end
        local snapshot = player_snapshot(player_id)
        local simple = Live.player_simple_interior(player_id)
        local simple_index = simple and tonumber(simple.index) or -1
        local property = player_property(player_id)
        local mode = simple and simple.active == true and "simple" or "property"
        if mode == "simple" and (simple.instance == nil or simple.exit_type == nil) then return false end
        if mode == "property" and (not property or property < 1 or property > 131) then
            toast("The selected player's current interior data is unavailable.", 7500, "warning")
            return false
        end
        local local_id = tonumber(local_player_id())
        if not local_id or local_id < 0 or local_id > 31 then
            toast("Kick From Interior could not resolve the local network player.", 6500, "warning")
            return false
        end
        local instance_id = tonumber(simple and simple.instance) or 0
        local simple_owner = tonumber(simple and simple.owner) or -1
        local exit_type = math.max(0, math.min(15, tonumber(simple and simple.exit_type) or 0))
        local args = {
            Live.KICK_INTERIOR_EVENT, local_id, 0,
            simple_index, instance_id, exit_type, 0, 0, -1,
        }
        if not Live.action_valid(request) then return false end
        request.interior_mode = mode
        local ok, result
        if mode == "property" then
            -- Classic apartments use a different host-owned exit controller.
            ok, result = Live.interior_provider_dispatch("interior_kick", request)
            if ok == nil then
                log_info("Kick From Interior unsupported property=" ..
                    tostring(property) .. " pid=" .. player_id .. " reason=" .. tostring(result))
                toast("This property needs a matching loaded Kick From Interior / Apartment action; none is available.",
                    8000, "warning")
                return false
            end
        else
            ok, result = Live.action_send(player_id, args)
        end
        if not ok then
            toast("Kick From Interior event dispatch failed: " .. tostring(result), 7000, "warning")
            return false
        end
        local now = now_ms()
        State.kick_interior = {
            identity = request.identity,
            local_identity = request.local_identity,
            local_id = request.local_id,
            generation = request.generation,
            active = true,
            mode = mode,
            property = property,
            player_id = player_id,
            player_name = snapshot and snapshot.name or player_name(player_id),
            simple_index = simple_index,
            simple_owner = simple_owner,
            instance_id = instance_id,
            exit_type = exit_type,
            physical_before = snapshot and tonumber(snapshot.interior) or nil,
            started_ms = now,
            until_ms = now + (mode == "property" and 15000 or 6000),
            event_result = result,
            command_ok = true,
        }
        toast(("Kick From Interior request sent; waiting for an observed exit for %s...")
            :format(State.kick_interior.player_name), 5500, "info")
        tick_kick_from_interior(now)
        return true
    end


    -- Session property exits begin
    function Live.property_exit_observation(pid)
        if not Live.action_source_ready() or not Live.script_globals_ready() then return nil end
        local simple = Live.player_simple_interior(pid)
        if not simple then return nil end
        local outside = simple.index == -1 and simple.owner == -1
        if not outside and (not simple.active or not Live.property_exit_guard.Supports(simple.index)) then return nil end
        local request = Live.action_identity(pid)
        if not request then return nil end
        if outside then return { outside = true, request = request } end
        if type(simple.instance) ~= "number" or simple.instance % 1 ~= 0 or simple.instance < 0 or simple.instance >= 32
            or type(simple.exit_type) ~= "number" then
            return nil
        end
        request.owner_id = simple.owner
        request.owner_identity = Live.remote_identity(simple.owner)
        if not request.owner_identity then return nil end
        local base = Live.PLAYER_BD_BASE + 1 + pid * Live.PLAYER_BD_STRIDE + 325
        local transition = Live.read_global_int(base)
        local activity = Live.read_global_int(base + 4)
        if type(transition) ~= "number" or transition % 1 ~= 0 or type(activity) ~= "number" or activity % 1 ~= 0 then return nil end
        return {
            request = request,
            index = simple.index,
            instance = simple.instance,
            owner = simple.owner,
            exit_type = simple.exit_type,
            ready = (u32(transition) & 8) == 0 and (u32(activity) & 12) == 0
        }
    end

    function Live.property_exits_enabled()
        return started and not Live.property_exit_stopped and State.runtime_writes_suspended ~= true
            and is_on("session_keep_players_outside")
    end

    Live.property_exit_guard = new_property_exit_guard({
        enabled = Live.property_exits_enabled,
        local_id = local_player_id,
        event = Live.KICK_INTERIOR_EVENT,
        observe = Live.property_exit_observation,
        valid = function(o) return Live.action_valid(o.request) end,
        send = function(observation, args, current)
            local fresh = Live.property_exit_observation(observation.request.player_id)
            if not Live.property_exit_guard.Same(observation, fresh) or fresh.ready ~= true
                or not Live.action_valid(fresh.request) or not current() then
                return false
            end
            return Live.action_send(fresh.request.player_id, args, function()
                local latest = Live.property_exit_observation(fresh.request.player_id)
                return Live.property_exit_guard.Same(fresh, latest) and latest.ready == true
                    and Live.action_valid(latest.request) and current()
            end)
        end,
    })
    -- Session property exits end

    function Live.finish_kick_organization(reason, observed, quiet)
        local state = State.kick_organization
        if not state or not state.active then return end
        state.active = false
        state.status = observed and "OBSERVED" or "NOT_CONFIRMED"
        log_info(("Kick From Organization status=%s pid=%s boss=%s detail=%s dispatch=%s")
            :format(state.status, tostring(state.player_id), tostring(state.boss_id),
                tostring(reason), tostring(state.event_result)))
        if not quiet then
            toast(observed and "Selected player observed outside the organization."
                or ("Kick From Organization not confirmed: " .. tostring(reason)),
                6500, observed and "info" or "warning")
        end
    end

    function Live.boss_roster_empty(boss)
        local base = Live.org_index(boss, Live.ORG_GOONS_OFFSET)
        if not base then return nil end
        local count = Live.read_global_int(base)
        if count ~= Live.ORG_GOON_COUNT and count ~= Live.ORG_ROSTER_STORAGE then return nil end
        for slot = 0, Live.ORG_GOON_COUNT - 1 do
            local value = Live.read_global_int(base + 1 + slot)
            if value == nil or value < -1 or value > 31 then return nil end
            if value ~= -1 then return false end
        end
        return true
    end

    function Live.tick_kick_organization(now)
        local state = State.kick_organization
        if not state or not state.active then return end
        now = tonumber(now) or now_ms()
        if not Live.action_valid(state) then
            Live.finish_kick_organization("player, boss, or session changed", false); return
        end
        if not Live.action_poll_due(state, now) then return end
        local owner = Live.org_owner(state.player_id)
        local roster
        if state.player_id == state.boss_id then
            -- A leaving boss is no longer its own owner: do not cancel before
            -- reading the very transition this action is supposed to observe.
            roster = Live.boss_roster_empty(state.boss_id)
            if roster ~= nil then roster = not roster end
        else
            if Live.org_owner(state.boss_id) ~= state.boss_id then
                Live.finish_kick_organization("organization owner changed", false); return
            end
            roster = Live.boss_has_goon(state.boss_id, state.player_id)
        end
        if owner == -1 and roster == false then
            state.clear_since = state.clear_since or now
            if now - state.clear_since >= 250 then
                Live.finish_kick_organization("owner and boss roster both cleared", true); return
            end
        else
            state.clear_since = nil
        end
        if now >= state.until_ms then
            Live.finish_kick_organization("the owner/roster did not confirm dismissal", false)
        end
    end

    function Live.start_kick_organization(player_id)
        local available, why = Live.selected_action_availability("kick_from_organization", player_id)
        if not available then
            toast(why, 5500, "warning"); return false
        end
        local request = Live.action_identity(player_id)
        if not request then
            toast("Select another player with an available connection identity.", 6500, "warning"); return false
        end
        if State.kick_organization.active then
            toast("An organization kick is already pending.", 5000, "info"); return false
        end
        local boss = Live.org_owner(request.player_id)
        if not Live.remote_player_index(boss) or Live.org_owner(boss) ~= boss then
            toast("No active CEO / MC organization was found for that player.", 6500, "warning"); return false
        end
        if boss ~= request.player_id and Live.boss_has_goon(boss, request.player_id) ~= true then
            toast("The selected player is not confirmed in the boss's roster.", 6500, "warning"); return false
        end
        request.owner_id, request.owner_identity = boss, Live.remote_identity(boss)
        if not request.owner_identity or not Live.action_valid(request) then return false end
        -- Enhanced freemode.c func_25133 consumes exactly three cells.
        -- Unlike the old five-cell member-dismissal event, this does not impersonate
        -- the boss in f_1. The receiver/protections may still decline it.
        local ok, result = Live.action_send(request.player_id, { Live.ORG_DISMISS_EVENT, request.local_id, 0 })
        if not ok then
            toast("Organization dismissal dispatch failed: " .. tostring(result), 6500, "warning"); return false
        end
        request.boss_id, request.event_result = boss, result
        request.started_ms, request.until_ms = now_ms(), now_ms() + 7000
        request.status = "DISPATCHED_UNVERIFIED"
        State.kick_organization = request
        log_info(("Kick From Organization dispatched pid=%d boss=%d event=%d targetResult=UNVERIFIED")
            :format(request.player_id, boss, Live.ORG_DISMISS_EVENT))
        toast("Organization dismissal sent; waiting for owner and roster read-back.", 5000, "info")
        return true
    end

    local function restore_cripple_target(player_id, reason, quiet)
        local target = State.cripple.targets[player_id]
        if type(target) ~= "table" then return end
        if entity_exists(target.ped) then
            if target.control_seen == true and not invoke_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, target.ped) then
                Live.request_entity_control(local_player_id(), target.ped)
            end
            invoke_void(H.SET_ENABLE_HANDCUFFS, target.ped, false)
            invoke_void(H.SET_ENABLE_BOUND_ANKLES, target.ped, false)
            local restore_owner = tonumber(target.original_owner)
            local restore_needed = target.control_seen == true and restore_owner
                and restore_owner >= 0 and restore_owner <= 31
                and restore_owner ~= tonumber(local_player_id())
            if restore_needed then
                target.owner_restored = Live.request_entity_control(restore_owner, target.ped)
            else
                target.owner_restored = Live.entity_network_owner(target.ped) == restore_owner
                    or target.control_seen ~= true
            end
        end
        State.cripple.targets[player_id] = nil
        log_info(("Cripple released: target=%s id=%s ped=%s reason=%s originalOwner=%s lastOwner=%s pendingOwner=%s controlSeen=%s ownerRestored=%s commandsSeen=%s applied=%s.")
            :format(tostring(target.player_name), tostring(player_id), tostring(target.ped),
                tostring(reason), tostring(target.original_owner), tostring(target.last_owner),
                tostring(target.pending_owner), tostring(target.control_seen),
                tostring(target.owner_restored), tostring(target.commands_seen), tostring(target.applied)))
        if quiet ~= true then
            local message = target.applied == true
                and ("Cripple released for " .. tostring(target.player_name) .. ".")
                or ("Cripple request cancelled for " .. tostring(target.player_name) .. ".")
            toast(message, 5000, "info")
        end
    end

    local function set_cripple_target(player_id, enabled, feature)
        player_id = tonumber(player_id)
        if enabled ~= true then
            if player_id then restore_cripple_target(player_id, "feature disabled", false) end
            return true
        end
        if not player_id or not player_available(player_id) or player_id == local_player_id() then
            toast("Select another available player.", 5500, "warning")
            return false
        end
        local snapshot = player_snapshot(player_id)
        if not snapshot or not entity_exists(snapshot.ped) then
            toast("The selected player's streamed ped is unavailable.", 6000, "warning")
            return false
        end
        State.cripple.targets[player_id] = {
            player_id = player_id,
            player_name = snapshot.name,
            ped = snapshot.ped,
            last_apply_ms = -100000,
            last_control_request_ms = -100000,
            last_ragdoll_ms = -100000,
            applied = false,
            ragdoll_sent = false,
            control_seen = false,
            original_owner = Live.entity_network_owner(snapshot.ped),
            owner_restored = false,
            activation_logged = false,
            commands_seen = false,
            started_ms = now_ms(),
            feature = feature,
            last_owner = nil,
            pending_owner = nil,
        }
        State.cripple.last_failure = nil
        toast(("Cripple is acquiring verified network control of %s; leave it enabled while this completes.")
            :format(snapshot.name), 6500, "info")
        return true
    end

    local function tick_cripple(now)
        now = tonumber(now) or now_ms()
        if now - (tonumber(State.cripple.last_tick_ms) or -100000) < 200 then return end
        State.cripple.last_tick_ms = now
        for player_id, target in pairs(State.cripple.targets) do
            if not player_available(player_id) then
                restore_cripple_target(player_id, "selected player left the session", true)
            else
                local ped = player_ped(player_id)
                if not entity_exists(ped) then
                    restore_cripple_target(player_id, "streamed ped became unavailable", true)
                else
                    if ped ~= target.ped then
                        local old_ped = target.ped
                        if entity_exists(old_ped) then
                            if not invoke_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, old_ped) then
                                Live.give_entity_control(local_player_id(), old_ped)
                            end
                            invoke_void(H.SET_ENABLE_HANDCUFFS, old_ped, false)
                            invoke_void(H.SET_ENABLE_BOUND_ANKLES, old_ped, false)
                            if tonumber(target.original_owner) and target.original_owner ~= local_player_id() then
                                Live.give_entity_control(target.original_owner, old_ped)
                            end
                        end
                        target.ped = ped
                        target.original_owner = Live.entity_network_owner(ped)
                        target.applied = false
                        target.ragdoll_sent = false
                        target.control_seen = false
                        target.activation_logged = false
                        target.commands_seen = false
                        target.started_ms = now
                    end
                    if not invoke_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, ped)
                        and now - (tonumber(target.last_control_request_ms) or -100000) >= 250 then
                        target.last_control_request_ms = now
                        local controlled, owner, pending = Live.request_entity_control(local_player_id(), ped)
                        target.last_owner, target.pending_owner = owner, pending
                        target.control_seen = target.control_seen == true or controlled == true
                    end
                    target.control_seen = target.control_seen == true
                        or invoke_bool(H.NETWORK_HAS_CONTROL_OF_ENTITY, ped)
                    local cuffs = invoke_void(H.SET_ENABLE_HANDCUFFS, ped, true)
                    local ankles = invoke_void(H.SET_ENABLE_BOUND_ANKLES, ped, true)
                    target.commands_seen = target.commands_seen == true or (cuffs == true and ankles == true)
                    target.applied = target.applied == true
                        or (target.control_seen == true and cuffs == true and ankles == true)
                    if target.control_seen and now - (tonumber(target.last_ragdoll_ms) or -100000) >= 1500 then
                        target.last_ragdoll_ms = now
                        target.ragdoll_sent = invoke_void(H.SET_PED_TO_RAGDOLL,
                            ped, 1800, 1800, 0, false, false, false) == true
                    end
                    if target.activation_logged ~= true and target.control_seen and target.applied then
                        target.activation_logged = true
                        log_info(("Cripple applied: target=%s id=%s ped=%s originalOwner=%s currentOwner=%s control=true cuffs=true ankles=true.")
                            :format(tostring(target.player_name), tostring(player_id), tostring(ped),
                                tostring(target.original_owner), tostring(Live.entity_network_owner(ped))))
                        toast(("Cripple applied to %s with verified control; disable it once you are finished.")
                            :format(tostring(target.player_name)), 6500, "success")
                    elseif target.control_seen ~= true
                        and now >= (tonumber(target.started_ms) or now) + 4000 then
                        State.cripple.last_failure = {
                            player_id = player_id,
                            player_name = target.player_name,
                            owner = target.last_owner,
                            pending_owner = target.pending_owner,
                            commands_seen = target.commands_seen == true,
                            at_ms = now,
                        }
                        if target.feature and type(target.feature.IsToggled) == "function"
                            and type(target.feature.Toggle) == "function" then
                            pcall(function()
                                if target.feature:IsToggled() then target.feature:Toggle(false) end
                            end)
                        end
                        restore_cripple_target(player_id,
                            "network owner did not grant control within four seconds", true)
                        toast(
                            ("Cripple failed for %s: player %s retained control of the ped. Toggle disabled.")
                            :format(tostring(target.player_name), tostring(target.last_owner)), 8000, "warning")
                    end
                end
            end
        end
    end

    Live.SUPER_MELEE_SCAN_INTERVAL_MS = 20
    Live.SUPER_MELEE_POINTER_SHORTLIST_PER_KIND = 128
    Live.SUPER_MELEE_IMPACT_WINDOW_MS = 700
    Live.SUPER_MELEE_MIN_CONTACT_AGE_MS = 30
    -- Natural authority transfer can take more than the old 200 ms. Keep a
    -- short, non-yielding lease with at most eight requests; never force an owner.
    Live.SUPER_MELEE_CONTROL_TIMEOUT_MS = 350
    Live.SUPER_MELEE_HIT_EVIDENCE_LIFETIME_MS = 180
    Live.SUPER_MELEE_CONTROL_INTERVAL_MS = 35
    Live.SUPER_MELEE_OWNER_RETURN_DELAY_MS = 320
    Live.SUPER_MELEE_OWNER_RETURN_TIMEOUT_MS = 1200
    Live.SUPER_MELEE_RAGDOLL_TIME_MS = 2600
    Live.SUPER_MELEE_PHYSICS_DELAY_MS = 48
    Live.SUPER_MELEE_RAGDOLL_READY_MS = 150
    Live.SUPER_MELEE_MOTION_TIMEOUT_MS = 150
    -- A stalled frame must not replay an old fallback or attribute unrelated
    -- later travel to the punch. This is an observation lifetime, not a sleep.
    Live.SUPER_MELEE_OBSERVATION_LIFETIME_MS = 260
    Live.SUPER_MELEE_REPEAT_IMPACT_MS = 220
    -- Idle evidence stays within the 250 ms freshness limit while avoiding
    -- fourteen complete neighbourhood snapshots per second at rest.
    Live.SUPER_MELEE_PRESTRIKE_INTERVAL_MS = 150
    Live.SUPER_MELEE_PRESTRIKE_MAX_AGE_MS = 250

    function Live.super_melee_gate(reason)
        State.super_melee.last_gate = tostring(reason)
        return nil
    end

    function Live.super_melee_trace(status, action, detail)
        local runtime = module_context and module_context.CScript and module_context.CScript.Runtime
        if runtime and type(runtime.RecordTestEvent) == "function" then
            pcall(runtime.RecordTestEvent, status, "Player", "Super Melee", action, detail)
        end
        if runtime and type(runtime.RecordCombatDiagnostic) == "function" then
            local severity = status == "FAILED" and "FAIL"
                or (status == "CANCELLED" and "WARN"
                    or (status == "SUCCESS_VERIFIED" and "PASS" or "INFO"))
            pcall(runtime.RecordCombatDiagnostic, "Super Melee", action,
                tostring(status) .. " " .. tostring(detail or ""), severity)
        end
    end

    function Live.super_melee_finite_clamp(value, minimum, maximum)
        value = tonumber(value)
        if not value or value ~= value or value == math.huge or value == -math.huge then value = 0.0 end
        return math.max(minimum, math.min(maximum, value))
    end

    function Live.super_melee_modifier_multiplier(strength)
        strength = math.max(1, math.min(20, tonumber(strength) or 1))
        if strength <= 5 then
            return 2.5 + (9.0 - 2.5) * ((strength - 1.0) / 4.0)
        end
        return 9.0 + (28.0 - 9.0) * ((strength - 5.0) / 5.0)
    end

    function Live.super_melee_object_identity(value)
        if value == nil then return nil end
        local ok, address = pcall(function()
            if type(value.GetAddress) == "function" then return value:GetAddress() end
            return nil
        end)
        if ok and tonumber(address) then return tostring(math.floor(tonumber(address))) end
        local text_ok, text = pcall(tostring, value)
        return text_ok and tostring(text):gsub("[\r\n]", " ") or nil
    end

    function Live.super_melee_player_info()
        local players = dependencies and dependencies.Players
        if not (players and type(players.GetById) == "function") then
            return nil, nil, "Players.GetById unavailable"
        end
        local player_ok, player = pcall(players.GetById, local_player_id())
        if not player_ok or player == nil then return nil, nil, "local CNetGamePlayer unavailable" end
        local info_ok, info = pcall(function() return player.PlayerInfo end)
        if not info_ok or info == nil then return nil, nil, "local CPlayerInfo unavailable" end
        local identity = Live.super_melee_object_identity(info)
        if not identity then return nil, nil, "CPlayerInfo identity unavailable" end
        return info, identity
    end

    function Live.super_melee_read_modifier(info)
        if info == nil then return nil end
        local ok, value = pcall(function() return info.MeleeWeaponForceModifier end)
        value = ok and tonumber(value) or nil
        if not value or value ~= value or value == math.huge or value == -math.huge then return nil end
        return value
    end

    function Live.super_melee_write_modifier(info, value)
        value = tonumber(value)
        if info == nil or not value or value ~= value or value < 0.0 or value > 64.0 then
            return false, "modifier write rejected by finite range guard"
        end
        local ok, err = pcall(function() info.MeleeWeaponForceModifier = value end)
        if not ok then return false, tostring(err) end
        local observed = Live.super_melee_read_modifier(info)
        local tolerance = math.max(0.0001, math.abs(value) * 0.00001)
        if observed == nil or math.abs(observed - value) > tolerance then
            return false, "modifier read-back mismatch observed=" .. tostring(observed)
        end
        return true, observed
    end

    function Live.super_melee_modifier_state()
        local state = State.super_melee
        if type(state.modifier) ~= "table" then
            state.modifier = {
                owned = false,
                info = nil,
                identity = nil,
                ped = 0,
                baseline = nil,
                applied = nil,
                strength = 0,
                multiplier = 1.0,
                status = "IDLE",
                backend = "physical-assist",
                last_error = nil,
                yielded_identity = nil,
            }
        end
        return state.modifier
    end

    function Live.restore_super_melee_modifier(reason)
        local modifier = Live.super_melee_modifier_state()
        if not modifier or modifier.owned ~= true then
            if modifier then
                modifier.status = "IDLE"
                modifier.backend = "physical-assist"
                modifier.strength = 0
            end
            return true, "not-owned"
        end
        local current = Live.super_melee_read_modifier(modifier.info)
        local tolerance = math.max(0.0001, math.abs(tonumber(modifier.applied) or 0.0) * 0.00001)
        if current == nil then
            modifier.last_error = "CPlayerInfo unavailable during restore"
            modifier.status = "FAILED"
            Live.super_melee_trace("FAILED", "modifier restore",
                "reason=" .. tostring(reason) .. " result=readback-unavailable")
            modifier.owned, modifier.info = false, nil
            return false, modifier.last_error
        end
        if math.abs(current - (tonumber(modifier.applied) or current)) > tolerance then
            modifier.yielded_identity = modifier.identity
            modifier.last_error = "external mutation observed; restore yielded"
            modifier.status = "UNAVAILABLE"
            Live.super_melee_trace("SUCCESS_UNVERIFIED", "modifier restore",
                "reason=" .. tostring(reason) .. " result=yielded-to-external-change current="
                .. tostring(current) .. " lastApplied=" .. tostring(modifier.applied))
            modifier.owned, modifier.info, modifier.baseline, modifier.applied = false, nil, nil, nil
            modifier.backend, modifier.strength = "physical-assist", 0
            return true, "yielded"
        end
        local restored, observed = Live.super_melee_write_modifier(modifier.info, modifier.baseline)
        if not restored then
            modifier.last_error = tostring(observed)
            modifier.status = "FAILED"
            Live.super_melee_trace("FAILED", "modifier restore",
                "reason=" .. tostring(reason) .. " result=" .. tostring(observed))
            modifier.owned, modifier.info = false, nil
            return false, modifier.last_error
        end
        Live.super_melee_trace("SUCCESS_VERIFIED", "modifier restore",
            "reason=" .. tostring(reason) .. " baseline=" .. tostring(observed))
        modifier.info, modifier.identity, modifier.baseline, modifier.applied = nil, nil, nil, nil
        modifier.ped, modifier.strength, modifier.multiplier = 0, 0, 1.0
        modifier.owned, modifier.status, modifier.backend, modifier.last_error =
            false, "IDLE", "physical-assist", nil
        return true, "restored"
    end

    function Live.update_super_melee_modifier(ped, strength)
        local modifier = Live.super_melee_modifier_state()
        if modifier.owned then
            Live.restore_super_melee_modifier("physical-impact backend")
        end
        modifier.status = strength > 0 and "DISABLED_CURRENT_BUILD" or "IDLE"
        modifier.backend = "physical-impact"
        modifier.strength = math.max(0, math.min(20, tonumber(strength) or 0))
        modifier.multiplier = 1.0
        modifier.applied = nil
        modifier.last_error = strength > 0
            and "CPlayerInfo.MeleeWeaponForceModifier disabled after live v5.49.0 regression"
            or nil
        return strength <= 0
    end

    -- Observed Super Melee damage field: settings 4/5/6/10 read 400/500/600/1000.
    -- CScript applies 100*strength across the 1..20 slider; the force field stays disabled.
    function Live.super_melee_damage_state()
        local state = State.super_melee
        if not state.damage_modifier then
            state.damage_modifier = { owned = false, status = "IDLE", last_strength = 0 }
        end
        return state.damage_modifier
    end

    function Live.super_melee_damage_target()
        -- Host lookups only: also safe to use during Quiesce/Dispose without
        -- running a game native or dereferencing a cached CPlayerInfo wrapper.
        local players, gta = dependencies and dependencies.Players, dependencies and dependencies.GTA
        if not players or not gta then return nil end
        local ok, info, key, health, incarnation = pcall(function()
            local pid = gta.GetLocalPlayerId()
            if type(pid) ~= "number" or pid % 1 ~= 0 or pid < 0 or pid > 31 then return nil end
            local player, ped = players.GetById(pid), gta.GetLocalPed()
            if not player or not ped then return nil end
            local i = player.PlayerInfo
            if not i or not i.PlayerPed then return nil end
            local pa, na, ia, cxn = ped:GetAddress(), player:GetAddress(), i.PlayerPed:GetAddress(), player.CxnId
            local function pointer(v)
                return type(v) == "number" and v % 1 == 0 and v >= 0x10000 and v <= 0x00007FFFFFFFFFFF
            end
            if not pointer(pa) or not pointer(na) or ia ~= pa or type(cxn) ~= "number" or cxn % 1 ~= 0 then return nil end
            -- The damage field belongs to the local player connection, not its
            -- current ped incarnation. Revalidate the current PlayerPed above but
            -- keep restore debt across respawn/model changes of the same owner.
            -- Never cache or dereference the old PlayerInfo/ped wrapper.
            return i, table.concat({ pid, na, cxn }, ":"), tonumber(ped.Health), pa
        end)
        if not ok then return nil end
        return info, key, health, incarnation
    end

    function Live.super_melee_damage_read(info)
        if not info then return nil end
        local ok, value = pcall(function() return info.MeleeWeaponDamageModifier end)
        if not ok or type(value) ~= "number" or value ~= value or value < 0 or value > 100000 then return nil end
        return value
    end

    function Live.restore_super_melee_damage(reason)
        local d = Live.super_melee_damage_state()
        if not d.owned then return true end
        if d.inflight then return false end
        local info, key = Live.super_melee_damage_target()
        if not info then
            d.status = "RESTORE_PENDING"; return false
        end
        if key ~= d.identity then
            d.owned = false; d.status = "RETIRED_IDENTITY"; d.baseline = nil; d.last_write = nil
            return true -- old player/ped is not a writable target anymore
        end
        local current = Live.super_melee_damage_read(info)
        if current == nil then
            d.status = "RESTORE_PENDING"; return false
        end
        local tolerance = math.max(0.0001, math.abs(d.last_write or 0) * 0.00001)
        if math.abs(current - d.baseline) <= 0.0001 then
            d.owned = false; d.status = "RESTORED"; return true
        end
        if math.abs(current - (d.last_write or current)) > tolerance then
            d.owned = false; d.yielded_identity = key; d.status = "EXTERNAL_CHANGE_PRESERVED"
            return true
        end
        if d.bst_seen and Live.bst46.source_valid and Live.bst46_equal(current, d.bst_target)
        then
            local flags = Live.bst46_flags()
            if flags == nil then
                d.status = "RESTORE_PENDING"; return false
            end
            if (flags & 1) ~= 0 then
                d.owned = false; d.status = "NATIVE_BST_PRESERVED"; return true
            end
        end
        local fresh, fresh_key = Live.super_melee_damage_target()
        if not fresh or fresh_key ~= key then
            d.status = "RESTORE_PENDING"; return false
        end
        if Live.super_melee_damage_read(fresh) ~= current then
            d.status = "RESTORE_PENDING"; return false
        end
        local checked, checked_key = Live.super_melee_damage_target()
        if not checked or checked_key ~= key or not d.owned then
            d.status = "RESTORE_PENDING"; return false
        end
        d.inflight = true
        local wrote = pcall(function() checked.MeleeWeaponDamageModifier = d.baseline end)
        d.inflight = false
        local after_info, after_key = Live.super_melee_damage_target()
        if after_info and after_key ~= key then
            d.owned = false; d.status = "RETIRED_IDENTITY"; return true
        end
        local after = Live.super_melee_damage_read(after_info)
        if not wrote or after == nil or math.abs(after - d.baseline) > 0.0001 then
            d.status = "RESTORE_PENDING"; return false
        end
        d.owned = false; d.status = "RESTORED"; d.last_write = nil
        Live.super_melee_trace("SUCCESS_VERIFIED", "damage field restore",
            "reason=" .. tostring(reason) .. " baseline=" .. tostring(d.baseline) .. " field-only")
        return true
    end

    function Live.update_super_melee_damage(ped, strength)
        local d = Live.super_melee_damage_state()
        strength = tonumber(strength)
        if not strength or strength ~= strength or strength == math.huge or strength == -math.huge then
            return Live.restore_super_melee_damage("invalid strength")
        end
        strength = math.max(0, math.min(20, math.floor(strength)))
        local bst, bst_identity, bst_incarnation = Live.bst46_melee(ped)
        local bst_revision = Live.bst46.revision
        if strength == 0 and not bst then
            local restored = Live.restore_super_melee_damage("slider disabled")
            if restored then
                d.yielded_identity = nil; d.last_strength = 0
            end
            return restored
        end
        if Live.bst46.retiring or not started or ped ~= local_ped() or not entity_exists(ped)
            or invoke_bool(H.IS_ENTITY_DEAD, ped, false) then
            return Live.restore_super_melee_damage("local gameplay unavailable")
        end
        local info, key, health, incarnation = Live.super_melee_damage_target()
        if bst and (bst_identity ~= key or bst_incarnation ~= incarnation) then
            return Live.restore_super_melee_damage("BST context changed")
        end
        if not info or not health or health <= 0 then
            if d.owned then
                Live.restore_super_melee_damage("local target unavailable")
            else
                d.status = "UNAVAILABLE"
            end
            return false
        end
        if d.owned and key ~= d.identity then
            if not Live.restore_super_melee_damage("local identity changed") then return false end
        end
        if bst and d.yielded_incarnation and d.yielded_incarnation ~= incarnation then d.yielded_identity = nil end
        if d.yielded_identity == key then return false end
        local current = Live.super_melee_damage_read(info)
        if current == nil then
            d.status = "UNAVAILABLE"; return false
        end
        if d.owned and math.abs(current - (d.last_write or current)) > 0.0001 then
            local normal = Live.bst46.profile and (Live.bst46.profile.gym and 1.25 or 1.0)
            if bst and ((d.incarnation and d.incarnation ~= incarnation)
                    or (Live.bst46.source_reset and Live.bst46_equal(current, normal))) then
                d.owned = false; d.baseline = nil
            else
                d.owned = false; d.yielded_identity = key; d.yielded_incarnation = incarnation; d.status =
                "EXTERNAL_CHANGE_PRESERVED"
                return false
            end
        end
        local wanted = strength > 0 and 100.0 * strength or math.max(d.owned and d.baseline or current, bst)
        if not d.owned then
            d.identity = key; d.baseline = current
        end
        d.incarnation = incarnation
        if bst then
            d.bst_seen = true; d.bst_target = bst
        end
        if math.abs(current - wanted) <= 0.0001 then
            -- An externally supplied matching baseline is not our write lease.
            d.status = d.owned and "FIELD_MATCH" or "PREEXISTING_VALUE"
            d.last_strength = strength
            return true
        end
        local fresh, fresh_key = Live.super_melee_damage_target()
        if not fresh or fresh_key ~= key or ped ~= local_ped() or not started or Live.bst46.retiring
            or (strength == 0 and (bst_revision ~= Live.bst46.revision or not Live.bst46_melee(ped))) then
            return false
        end
        if Live.super_melee_damage_read(fresh) ~= current then
            d.status = "VALUE_CHANGED_BEFORE_WRITE"; return false
        end
        local checked, checked_key, _, checked_incarnation = Live.super_melee_damage_target()
        if not checked or checked_key ~= key or checked_incarnation ~= incarnation or not started or Live.bst46.retiring
            or (bst and bst_revision ~= Live.bst46.revision) then
            return false
        end
        -- Establish debt before setter: host setters can fail after mutating.
        d.owned = true; d.last_write = wanted; d.inflight = true
        local wrote = pcall(function() checked.MeleeWeaponDamageModifier = wanted end)
        d.inflight = false
        local after_info, after_key = Live.super_melee_damage_target()
        if after_info and after_key ~= key then
            d.owned = false; d.status = "RETIRED_IDENTITY"; return false
        end
        local readback = Live.super_melee_damage_read(after_info)
        if not wrote or readback == nil or math.abs(readback - wanted) > 0.0001 then
            d.status = "WRITE_UNVERIFIED"
            Live.restore_super_melee_damage("write or readback failed")
            return false
        end
        if strength == 0 and (bst_revision ~= Live.bst46.revision or not Live.bst46_melee(ped)) then
            Live.restore_super_melee_damage("BST request changed"); return false
        end
        d.status = "FIELD_MATCH"; d.last_strength = strength
        Live.super_melee_trace("SUCCESS_VERIFIED", "damage field",
            "strength=" .. strength .. " observed=" .. readback .. " forceField=untouched; impact outcome unverified")
        return true
    end

    -- BEGIN BST MODE46
    -- freemode func_15931/15934: weapon 0.72*2, melee 2 (gym 2.5),
    -- defense 1/melee. Only documented, readable combat properties are owned.
    -- The existing Super Melee owner remains the sole melee-damage writer.
    Live.bst46 = {
        intent = false,
        canceled = false,
        retiring = false,
        revision = 0,
        fields = {},
        yielded = {},
        status =
        "OFF"
    }
    Live.bst46_fields = { "WeaponDamageModifier", "WeaponDefenseModifier", "MeleeWeaponDefenseModifier" }
    function Live.bst46_read(info, field)
        local ok, value = pcall(function() return info[field] end)
        if not ok or type(value) ~= "number" or value ~= value or value < 0 or value > 100000 then return nil end
        return value
    end

    function Live.bst46_equal(a, b)
        return type(a) == "number" and type(b) == "number" and math.abs(a - b) <= math.max(0.0001, math.abs(b) * 0.00001)
    end

    function Live.bst46_wanted()
        local s = Live.bst46
        return started and not s.retiring and not s.canceled and s.intent
            and State.runtime_writes_suspended ~= true and is_on("bst_mode")
    end

    function Live.bst46_request(enabled)
        local s = Live.bst46
        s.revision = s.revision + 1; s.intent = enabled == true; s.profile = nil
        if enabled then
            s.canceled = false; s.yielded = {}
            local d = Live.super_melee_damage_state()
            if not d.owned then d.yielded_identity = nil end
        end
    end

    function Live.bst46_flags()
        local ok, flags = pcall(Live.read_global_int, 2673276 + 3768)
        if not ok or type(flags) ~= "number" or flags % 1 ~= 0 or flags < -2147483648 or flags > 4294967295 then return nil end
        return flags & 0xFFFFFFFF
    end

    function Live.bst46_profile(ped)
        if not Live.bst46_wanted() or not Live.action_source_ready()
            or Live.remote_bool(0x9DE624D2FC4B603F) ~= true
            or Live.remote_bool(H.NETWORK_IS_IN_TRANSITION) ~= false
            or ped ~= local_ped() or Live.remote_bool(H.IS_ENTITY_DEAD, ped, false) ~= false then
            return nil
        end
        local flags = Live.bst46_flags()
        local special = Live.read_global_int(1836784)
        local pid = local_player_id()
        if flags == nil or type(special) ~= "number" or special % 1 ~= 0 or special < -1 or special > 31 then return nil end
        local factor = (flags & (1 << 6)) ~= 0 and 2.5 or 2.0
        local defense = pid == special and 1.0 or 1.0 / factor
        return {
            weapon = 1.44,
            melee = factor,
            defense = defense,
            ped = ped,
            gym = (flags & (1 << 6)) ~= 0,
            native = (flags & 1) ~=
                0
        }
    end

    function Live.bst46_restore()
        local s = Live.bst46
        for _, field in ipairs(Live.bst46_fields) do
            local o = s.fields[field]
            if o and not o.inflight then
                local info, key = Live.super_melee_damage_target()
                if info and key ~= o.identity then
                    s.fields[field] = nil
                elseif info then
                    local current = Live.bst46_read(info, field)
                    if current ~= nil then
                        if Live.bst46_equal(current, o.before) or not Live.bst46_equal(current, o.last) then
                            s.fields[field] = nil -- another owner wins; no stale baseline write
                        else
                            local flags = 0
                            if s.source_valid then flags = Live.bst46_flags() end
                            if flags == nil then
                                s.status = "RESTORE_PENDING"; return false
                            end
                            if (flags & 1) ~= 0 then
                                -- The game's own requested/active BST will run its source teardown.
                                s.fields[field] = nil; s.status = "NATIVE_BST_PRESERVED"
                                goto next_bst_field
                            end
                            local fresh, fresh_key = Live.super_melee_damage_target()
                            if fresh and fresh_key == key and Live.bst46_equal(Live.bst46_read(fresh, field), current) then
                                local checked, checked_key = Live.super_melee_damage_target()
                                if not checked or checked_key ~= key or s.fields[field] ~= o then return false end
                                fresh = checked
                                o.inflight = true
                                pcall(function() fresh[field] = o.before end)
                                o.inflight = false
                                local after, after_key = Live.super_melee_damage_target()
                                if after and after_key ~= key then
                                    s.fields[field] = nil
                                elseif after and Live.bst46_equal(Live.bst46_read(after, field), o.before) then
                                    s.fields[field] = nil
                                end
                            end
                        end
                    end
                end
            end
            ::next_bst_field::
        end
        return next(s.fields) == nil
    end

    function Live.bst46_pause(reason, halt)
        local s = Live.bst46
        s.revision = s.revision + 1; s.profile = nil; s.status = tostring(reason or "RESTORING")
        if halt then
            s.retiring = true; s.intent = false
        end
        local clean = Live.bst46_restore()
        local melee = Live.restore_super_melee_damage(reason or "BST pause")
        return clean and melee
    end

    function Live.bst46_cancel()
        local s = Live.bst46
        s.canceled = true; s.intent = false; s.revision = s.revision + 1; s.profile = nil
        return Live.bst46_pause("PANIC", false)
    end

    function Live.bst46_melee(ped)
        local s = Live.bst46
        if Live.bst46_wanted() and s.profile and s.profile.ped == ped then
            return s.profile.melee, s.profile.identity, s.profile.incarnation
        end
    end

    function Live.bst46_tick(ped)
        local s = Live.bst46
        if not Live.bst46_wanted() then
            s.profile = nil
            local clean = Live.bst46_restore()
            s.status = clean and "OFF" or "RESTORE_PENDING"
            return clean
        end
        local revision = s.revision
        local profile = Live.bst46_profile(ped)
        local info, key, health, incarnation = Live.super_melee_damage_target()
        if not profile or not info or not health or health <= 0 or not incarnation or not Live.bst46_wanted() or revision ~= s.revision then
            s.profile = nil; Live.bst46_restore(); s.status = "WAITING_FOR_LOCAL_FREEMODE"; return false
        end
        -- Preflight the complete readable profile before acquiring any field.
        for _, field in ipairs({ "WeaponDamageModifier", "WeaponDefenseModifier", "MeleeWeaponDefenseModifier", "MeleeWeaponDamageModifier" }) do
            if Live.bst46_read(info, field) == nil then
                s.profile = nil; Live.bst46_restore(); s.status = "COMBAT_FIELD_UNAVAILABLE"; return false
            end
        end
        local previous = s.profile
        s.source_reset = previous and ((previous.native and not profile.native) or previous.gym ~= profile.gym) or false
        profile.identity = key; profile.incarnation = incarnation
        s.source_valid = true; s.profile = profile
        local function current()
            if revision ~= s.revision or s.profile ~= profile or not Live.bst46_wanted() or ped ~= local_ped() then return false end
            return revision == s.revision and s.profile == profile and not s.retiring
        end
        local complete = true
        for _, field in ipairs(Live.bst46_fields) do
            if not current() then
                Live.bst46_restore(); return false
            end
            local fresh, fresh_key, _, fresh_incarnation = Live.super_melee_damage_target()
            if not fresh or fresh_key ~= key or fresh_incarnation ~= incarnation or not current() then return false end
            local value = Live.bst46_read(fresh, field)
            if value == nil then
                complete = false
            else
                local o = s.fields[field]
                if o and o.identity ~= key then
                    s.fields[field] = nil; o = nil
                end
                local identity = key .. ":" .. incarnation
                if o and not Live.bst46_equal(value, o.last) then
                    local source_reset = previous and
                        ((previous.native and not profile.native) or previous.gym ~= profile.gym)
                    local normal = field == "WeaponDamageModifier" and 0.72 or (profile.gym and 0.8 or 1.0)
                    if o.incarnation ~= incarnation or (source_reset and Live.bst46_equal(value, normal)) then
                        s.fields[field] = nil; o = nil -- proven respawn/source reset; capture the fresh baseline
                    else
                        s.fields[field] = nil; o = nil; s.yielded[field] = identity
                    end
                end
                if s.yielded[field] == identity then
                    complete = false
                else
                    local before = o and o.before or value
                    local wanted = field == "WeaponDamageModifier" and math.max(before, profile.weapon) or
                        math.min(before, profile.defense)
                    if o then o.incarnation = incarnation end
                    if not Live.bst46_equal(value, wanted) then
                        local final, final_key, _, final_incarnation = Live.super_melee_damage_target()
                        if not final or final_key ~= key or final_incarnation ~= incarnation or not current()
                            or not Live.bst46_equal(Live.bst46_read(final, field), value) then
                            return false
                        end
                        -- Metadata/property getters can reenter. Refresh identity after
                        -- the final value read, then finish with a Lua-only intent fence.
                        local checked, checked_key, _, checked_incarnation = Live.super_melee_damage_target()
                        if not checked or checked_key ~= key or checked_incarnation ~= incarnation
                            or revision ~= s.revision or s.profile ~= profile or s.retiring then
                            return false
                        end
                        final = checked
                        o = o or { identity = key, incarnation = incarnation, before = before }
                        s.fields[field] = o; o.last = wanted; o.inflight = true
                        local wrote = pcall(function() final[field] = wanted end)
                        o.inflight = false
                        local after, after_key = Live.super_melee_damage_target()
                        if not wrote or not after or after_key ~= key or not Live.bst46_equal(Live.bst46_read(after, field), wanted) then complete = false end
                        if not current() then
                            Live.bst46_restore(); return false
                        end
                    end
                end
            end
        end
        s.status = complete and "COMBAT_FIELDS_OBSERVED" or "PARTIAL_OR_EXTERNAL_OWNER"
        return complete
    end

    function Live.bst46_snapshot()
        local s, d = Live.bst46, Live.super_melee_damage_state()
        local owned = 0; for _ in pairs(s.fields) do owned = owned + 1 end
        local phase = s.status
        if phase == "COMBAT_FIELDS_OBSERVED" and d.status ~= "FIELD_MATCH" and d.status ~= "PREEXISTING_VALUE" then
            phase =
            "PARTIAL_OR_EXTERNAL_OWNER"
        end
        return {
            enabled = Live.bst46_wanted(),
            status = phase,
            owned_fields = owned,
            melee_status = d.status,
            melee_shared_with_super_melee = true,
            source_profile = s.profile and {
                weapon = s.profile.weapon,
                melee = s.profile.melee,
                defense = s.profile
                    .defense
            } or nil,
            native_unarmed_side_effect_verified = false,
            live_verified = false
        }
    end

    bst_pending46 = function()
        local d = Live.super_melee_damage_state()
        return next(Live.bst46.fields) ~= nil or (d.bst_seen == true and d.owned == true)
    end
    -- END BST MODE46

    -- Melee owns this small identity proof independently of Messiah. We never
    -- release script GUIDs, keep a pool wrapper between frames, or infer lifetime
    -- from a positive integer. A pending impact must resolve the current pool
    -- slot/physical identity again before any target native can run.
    function Live.super_melee_address(pointer)
        if pointer == nil then return nil end
        local ok, address = pcall(function() return pointer:GetAddress() end)
        if not ok or type(address) ~= "number" or address ~= address
            or address <= 0 or address == math.huge or address % 1 ~= 0 then
            return nil
        end
        return address
    end

    function Live.super_melee_rendered(spec)
        local state, now = State.super_melee, now_ms()
        if not state.rendered_cache or state.rendered_cache_ms ~= now then
            state.rendered_cache, state.rendered_cache_ms = {}, now
        end
        local key = spec and spec[2]
        if not key then return {} end
        if state.rendered_cache[key] then return state.rendered_cache[key] end
        local cache, generation = state.rendered_cache, tonumber(state.generation) or 0
        local rows = {}
        if pool_mgr and type(pool_mgr[key]) == "function" then
            local ok, current = pcall(pool_mgr[key])
            if ok and (type(current) == "table" or type(current) == "userdata") then
                -- Cherax may expose STL collections as iterable userdata.
                -- A partial/throwing iterator is not a complete fresh snapshot.
                local iterated = pcall(function()
                    for _, pointer in pairs(current) do
                        rows[#rows + 1] = pointer; if #rows >= 64 then break end
                    end
                end)
                if not iterated then rows = {} end
            end
        end
        -- This cache lasts one native tick only. Each use still converts and
        -- round-trips the current physical identity before a target native.
        if state.rendered_cache ~= cache or (tonumber(state.generation) or 0) ~= generation then return {} end
        cache[key] = rows
        return rows
    end

    function Live.super_melee_owner_current(ped)
        if not started then
            Live.super_melee_gate("player module stopped"); return false
        end
        if ped ~= local_ped() then
            Live.super_melee_gate("local player changed"); return false
        end
        if slider_int("super_melee", 0) <= 0 then
            Live.super_melee_gate("slider disabled"); return false
        end
        if invoke_bool(H.IS_ENTITY_DEAD, ped, false) or invoke_bool(H.IS_PED_DEAD_OR_DYING, ped, true) then
            Live.super_melee_gate("local player dead"); return false
        end
        return ped == local_ped()
    end

    function Live.super_melee_local_vehicle(ped)
        if invoke_bool(H.IS_PED_IN_ANY_VEHICLE, ped, false) ~= true then return 0 end
        local vehicle = invoke_int(H.GET_VEHICLE_PED_IS_IN, ped, false)
        return type(vehicle) == "number" and vehicle > 0 and entity_exists(vehicle) and vehicle or 0
    end

    function Live.super_melee_target_excluded(entity, ped)
        if type(entity) ~= "number" or entity <= 0 or entity == ped then return true end
        local local_vehicle = Live.super_melee_local_vehicle(ped)
        if local_vehicle > 0 then
            if entity == local_vehicle then
                Live.super_melee_gate("local current vehicle excluded")
                return true
            end
            -- Shape outputs can use a different script GUID for the same
            -- physical vehicle. Never let that alias bypass own-vehicle fencing.
            if entity_exists(entity) and gta and type(gta.HandleToPointer) == "function" then
                local a_ok, a = pcall(gta.HandleToPointer, entity)
                local b_ok, b = pcall(gta.HandleToPointer, local_vehicle)
                local a_address = a_ok and Live.super_melee_address(a) or nil
                local b_address = b_ok and Live.super_melee_address(b) or nil
                if a_address and a_address == b_address then
                    Live.super_melee_gate("local current vehicle alias excluded")
                    return true
                end
            end
        end
        return Live.super_melee_preview_entity(entity)
    end

    function Live.super_melee_native_kind(handle)
        if type(handle) ~= "number" or handle <= 0 or handle % 1 ~= 0 or handle >= 2147483648
            or not entity_exists(handle) then
            return "invalid", 0
        end
        local entity_type = invoke_int(H.GET_ENTITY_TYPE, handle)
        if entity_type == 1 then return "ped", 1 end
        if entity_type == 2 then return "vehicle", 2 end
        if entity_type == 3 then return "object", 3 end
        -- GET_ENTITY_TYPE should be authoritative, but keep typed native readback
        -- as a compatibility fallback for host builds that transiently return 0.
        if invoke_bool(H.IS_ENTITY_A_PED, handle) == true then return "ped", 1 end
        if invoke_bool(H.IS_ENTITY_A_VEHICLE, handle) == true then return "vehicle", 2 end
        if invoke_bool(H.IS_ENTITY_AN_OBJECT, handle) == true then return "object", 3 end
        return "invalid", tonumber(entity_type) or 0
    end

    function Live.super_melee_native_proof(handle, ped, route, frame)
        if not Live.super_melee_owner_current(ped) then return nil end
        handle = tonumber(handle)
        if not handle or handle <= 0 or handle % 1 ~= 0 or handle >= 2147483648
            or Live.super_melee_target_excluded(handle, ped) or not entity_exists(handle) then
            return Live.super_melee_gate("native direct target unavailable")
        end
        local kind, entity_type = Live.super_melee_native_kind(handle)
        if kind == "invalid" or not Live.super_melee_owner_current(ped) then
            return Live.super_melee_gate("native direct target type unavailable")
        end
        local target_model, raw_model, model_error = invoke_int_detail(H.GET_ENTITY_MODEL, handle)
        if model_error or type(raw_model) ~= "number" or raw_model == 0 or raw_model ~= raw_model
            or math.abs(raw_model) == math.huge or raw_model % 1 ~= 0 then
            return Live.super_melee_gate("native direct target model unavailable")
        end
        frame = frame or Live.super_melee_attack_frame(ped)
        local coords = invoke_vec3(H.GET_ENTITY_COORDS, handle, false)
        local ex, ey, ez = vector_components(coords)
        local distance, alignment = Live.super_melee_spatial_from_frame(frame, ex, ey, ez)
        local maximum = kind == "vehicle" and 8.5 or (kind == "object" and 5.0 or 4.0)
        if not distance or alignment == nil or distance > maximum
            or (kind ~= "vehicle" and alignment < -.20 and distance > 1.5) then
            return Live.super_melee_gate("native direct target outside bounded melee envelope")
        end
        local networked = invoke_bool(H.NETWORK_GET_ENTITY_IS_NETWORKED, handle) == true
        local network_id = nil
        if networked then
            network_id = invoke_int(H.NETWORK_GET_NETWORK_ID_FROM_ENTITY, handle)
            if type(network_id) ~= "number" or network_id <= 0 or network_id % 1 ~= 0 then
                -- A just-created/freshly-hit networked entity can exist before GTA
                -- publishes a usable network ID to this script. Keep the native
                -- identity, but NEVER use a missing ID as permission to skip the
                -- natural NETWORK_HAS_CONTROL_OF_ENTITY gate before physics writes.
                network_id = nil
            end
        end
        local owner_model = invoke_int(H.GET_ENTITY_MODEL, ped)
        local generation = tonumber(State.super_melee.generation) or 0
        local instance_address, owner_instance_address
        if gta and type(gta.HandleToPointer) == "function" then
            local ok, pointer = pcall(gta.HandleToPointer, handle)
            instance_address = ok and Live.super_melee_address(pointer) or nil
            ok, pointer = pcall(gta.HandleToPointer, ped)
            owner_instance_address = ok and Live.super_melee_address(pointer) or nil
        end
        route = tostring(route or "native-direct")
        return {
            handle = handle,
            address = ("native:%d:%d:%d"):format(handle, target_model, generation),
            instance_address = instance_address,
            owner_instance_address = owner_instance_address,
            identity_ms = now_ms(),
            slot = nil,
            spec = nil,
            ped = ped,
            target_model = target_model,
            entity_type = entity_type,
            network_id = network_id,
            networked = networked,
            captured_ms = now_ms(),
            retired = false,
            route = route,
            native_identity = true,
            direct_authorized = route == "native-direct",
            owner_address = ("native-owner:%d:%d:%d"):format(ped, tonumber(owner_model) or 0, generation),
            owner_network = nil,
            owner_model = owner_model,
            generation = generation,
            distance = distance,
            alignment = alignment,
        }
    end

    function Live.super_melee_release_shape_proof(proof, reason)
        if type(proof) ~= "table" or proof.shape_borrowed ~= true or proof.shape_released == true then return true end
        local state, handle = State.super_melee, proof.handle
        local pending = state.pending and state.pending[handle]
        -- A duplicate strike may point at the very proof awaiting physics.
        -- Neither retire nor release that live pending owner's lease.
        if pending and pending.proof == proof then return true end
        local returning = state.owner_restores and state.owner_restores[handle]
        if returning and returning.proof == proof then return true end
        proof.shape_released = true
        proof.retired = true
        proof.reason = tostring(reason or "shape GUID consumed")
        -- A shape output is not necessarily a newly allocated GUID. Before ALL
        -- release paths (including rejected results), protect current/local and
        -- independently retained users of this exact numeric GUID.
        local ped = local_ped()
        local current_vehicle = type(ped) == "number" and ped > 0 and entity_exists(ped)
            and Live.super_melee_local_vehicle(ped) or 0
        if handle == ped or handle == proof.ped or handle == current_vehicle then return true end
        local retained = state.proofs and state.proofs[handle]
        local strike = state.nonped_strike
        local inflight = state.shape_inflight and state.shape_inflight[handle]
        if (pending and pending.proof ~= proof)
            or (retained and retained ~= proof and retained.retired ~= true)
            or (strike and strike.target == handle and strike.proof ~= proof)
            or (inflight and inflight ~= proof) then
            return true
        end
        if not entity_exists(handle) then return true end
        -- A deleted target can leave a reused positive GUID. Never release the
        -- replacement entity using the old target's captured identity.
        if proof.target_model and invoke_int(H.GET_ENTITY_MODEL, handle) ~= proof.target_model then return true end
        if proof.network_id and invoke_int(H.NETWORK_GET_NETWORK_ID_FROM_ENTITY, handle) ~= proof.network_id then return true end
        if proof.shape_address then
            local ok, pointer = pcall(gta.HandleToPointer, handle)
            if not ok or Live.super_melee_address(pointer) ~= proof.shape_address then return true end
        end
        if H.RELEASE_SCRIPT_GUID_FROM_ENTITY then
            pcall(invoke_void_detail, H.RELEASE_SCRIPT_GUID_FROM_ENTITY, handle)
        end
        return true
    end

    function Live.super_melee_free_shape_buffers()
        local state = State.super_melee
        local buffers = state.shape_buffers
        state.shape_buffers = nil
        if buffers and memory and type(memory.Free) == "function" then
            for _, ptr in pairs(buffers) do pcall(memory.Free, ptr) end
        end
    end

    function Live.super_melee_ensure_shape_buffers()
        local state = State.super_melee
        if state.shape_buffers then return true end
        if not memory or type(memory.Alloc) ~= "function" or type(memory.Free) ~= "function"
            or type(memory.WriteInt) ~= "function" or type(memory.ReadInt) ~= "function" then
            return false
        end
        local buffers = {}
        for _, spec in ipairs({ { "shape_hit_ptr", 4 }, { "shape_end_ptr", 24 },
            { "shape_normal_ptr", 24 }, { "shape_entity_ptr", 4 } }) do
            local ok, ptr = pcall(memory.Alloc, spec[2])
            if not ok or type(ptr) ~= "number" or ptr <= 0 or ptr >= math.huge or ptr % 1 ~= 0 then
                for _, allocated in pairs(buffers) do pcall(memory.Free, allocated) end
                return false
            end
            buffers[spec[1]] = ptr
        end
        state.shape_buffers = buffers
        return true
    end

    function Live.super_melee_shape_target(ped, frame, segment)
        local swing = State.super_melee.swing
        if swing.active ~= true or not Live.super_melee_owner_current(ped) then return nil, nil, "no-active-swing" end
        if not H.START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE or not H.GET_SHAPE_TEST_RESULT
            or not H.RELEASE_SCRIPT_GUID_FROM_ENTITY or not Live.super_melee_ensure_shape_buffers() then
            return nil, nil, "shape-native-unavailable"
        end
        frame = frame or Live.super_melee_attack_frame(ped)
        if not frame then return nil, nil, "attack-frame-unavailable" end
        local fx, fy = tonumber(frame.fx), tonumber(frame.fy)
        if not fx or not fy then return nil, nil, "attack-forward-unavailable" end
        local state = State.super_melee.shape_buffers
        local from_x, from_y, from_z = frame.x + fx * 0.12, frame.y + fy * 0.12, frame.z + 0.72
        local to_x, to_y, to_z = frame.x + fx * 4.0, frame.y + fy * 4.0, frame.z + 0.72
        if segment then
            from_x, from_y, from_z = segment.x1, segment.y1, segment.z1
            to_x, to_y, to_z = segment.x2, segment.y2, segment.z2
        end
        local shape, raw, err = invoke_int_detail(H.START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE,
            from_x, from_y, from_z, to_x, to_y, to_z, 511, ped, 4)
        if err or type(shape) ~= "number" or shape <= 0 then return nil, nil, "shape-start-failed" end
        local hit_ok, hit_written = pcall(memory.WriteInt, state.shape_hit_ptr, 0)
        local entity_ok, entity_written = pcall(memory.WriteInt, state.shape_entity_ptr, 0)
        if not hit_ok or hit_written == false or not entity_ok or entity_written == false then
            return nil, nil, "shape-buffer-clear-failed"
        end
        local status, result_raw, result_err = invoke_int_detail(H.GET_SHAPE_TEST_RESULT, shape,
            state.shape_hit_ptr, state.shape_end_ptr, state.shape_normal_ptr, state.shape_entity_ptr)
        if result_err or status ~= 2 then return nil, nil, "shape-result-unavailable" end
        local read_hit_ok, hit = pcall(memory.ReadInt, state.shape_hit_ptr)
        if not read_hit_ok or tonumber(hit) == 0 then return nil, nil, "shape-miss" end
        local read_entity_ok, raw_entity = pcall(memory.ReadInt, state.shape_entity_ptr)
        local handle, classification = Messiah.NormalizeEntityHandle(read_entity_ok and raw_entity or nil)
        Messiah.ReportRejectedEntityHandle("SuperMelee.GET_SHAPE_TEST_RESULT", raw_entity,
            classification, "none", "active-swing shape target normalized before native proof")
        if handle == 0 or handle == ped or Live.super_melee_target_excluded(handle, ped) or not entity_exists(handle) then
            if handle and handle > 0 then
                Live.super_melee_release_shape_proof(
                    { handle = handle, ped = ped, shape_borrowed = true }, "excluded shape result")
            end
            return nil, nil, "shape-target-unavailable"
        end
        local proof = Live.super_melee_native_proof(handle, ped, "native-shape", frame)
        if not proof then
            Live.super_melee_release_shape_proof({ handle = handle, ped = ped, shape_borrowed = true },
                "rejected shape proof")
            return nil, nil, "shape-proof-rejected"
        end
        proof.shape_borrowed = true
        proof.shape_released = false
        local address_ok, address_pointer = pcall(gta.HandleToPointer, handle)
        proof.shape_address = address_ok and Live.super_melee_address(address_pointer) or nil
        proof.direct_authorized = true
        proof.discovery_route = "native-shape"
        return handle, proof, nil
    end

    function Live.super_melee_resolve(pointer, slot, spec, ped)
        if not Live.super_melee_owner_current(ped) then return nil end
        local generation = tonumber(State.super_melee.generation) or 0
        local address = Live.super_melee_address(pointer)
        if not address then return Live.super_melee_gate("physical pointer unavailable") end
        local network_id, known = Ignore.network(pointer)
        if not known then return Live.super_melee_gate("NetObject fingerprint unavailable") end
        if not Live.super_melee_owner_current(ped) then return nil end
        local converted, handle = false, nil
        if gta and type(gta.PointerToHandle) == "function" then converted, handle = pcall(gta.PointerToHandle, pointer) end
        if not Live.super_melee_owner_current(ped) then return nil end
        local route = "rendered-pointer"
        -- Indexed C++ pool wrappers can fault outside Lua pcall. Use rendered
        -- entities only, with a fresh PointerToHandle round-trip for each target.
        if not converted or type(handle) ~= "number" or handle <= 0 or handle % 1 ~= 0 or handle > 2147483647
            or Ignore.released(handle) or Live.super_melee_target_excluded(handle, ped)
            or not Live.super_melee_owner_current(ped) then
            return Live.super_melee_gate("no verified rendered pointer handle")
        end
        local after, after_known = Ignore.network(pointer)
        if not after_known or after ~= network_id or not Live.super_melee_owner_current(ped) then return nil end
        if not (gta and type(gta.HandleToPointer) == "function") then return nil end
        local mapped_ok, mapped = pcall(gta.HandleToPointer, handle)
        local mapped_net, mapped_known = Ignore.network(mapped)
        if not mapped_ok or Live.super_melee_address(mapped) ~= address
            or not mapped_known or mapped_net ~= network_id
            or not Live.super_melee_owner_current(ped) then
            return nil
        end
        local owner_ok, owner = pcall(gta.HandleToPointer, ped)
        local owner_address = Live.super_melee_address(owner)
        local owner_network, owner_known = Ignore.network(owner)
        if not owner_ok or not owner_address or not owner_known
            or not Live.super_melee_owner_current(ped) then
            return nil
        end
        local owner_model = invoke_int(H.GET_ENTITY_MODEL, ped)
        if generation ~= (tonumber(State.super_melee.generation) or 0)
            or not Live.super_melee_owner_current(ped) then
            return nil
        end
        local target_model, raw_model, model_error = invoke_int_detail(H.GET_ENTITY_MODEL, handle)
        if model_error or type(raw_model) ~= "number" or raw_model == 0
            or raw_model ~= raw_model or math.abs(raw_model) == math.huge or raw_model % 1 ~= 0
            or generation ~= (tonumber(State.super_melee.generation) or 0)
            or not Live.super_melee_owner_current(ped) then
            return nil
        end
        return {
            handle = handle,
            address = address,
            slot = slot,
            spec = spec,
            ped = ped,
            target_model = target_model,
            network_id = network_id,
            captured_ms = now_ms(),
            retired = false,
            route = route,
            owner_address = owner_address,
            owner_network = owner_network,
            owner_model = owner_model,
            generation = generation
        }
    end

    function Live.super_melee_target_identity_current(proof)
        -- true: same instance; false: confirmed replacement/deletion; nil:
        -- temporarily unreadable. Ownership return does not depend on gameplay
        -- strength, local ped, death, retirement or the current swing generation.
        if not proof or type(proof.handle) ~= "number" then return false end
        local exists, raw, err = invoke_bool_detail(H.DOES_ENTITY_EXIST, proof.handle)
        if err or raw == nil then return nil end
        if exists ~= true then return false end
        local model, model_raw, model_err = invoke_int_detail(H.GET_ENTITY_MODEL, proof.handle)
        if model_err or type(model_raw) ~= "number" or model_raw == 0 then return nil end
        if model ~= proof.target_model then return false end
        if proof.entity_type then
            local entity_type, type_raw, type_err = invoke_int_detail(H.GET_ENTITY_TYPE, proof.handle)
            if type_err or type(type_raw) ~= "number" or type_raw == 0 then return nil end
            if entity_type ~= proof.entity_type then return false end
        end
        local address = proof.instance_address or proof.strike_address or proof.shape_address
            or (type(proof.address) == "number" and proof.address or nil)
        local pointer
        if address then
            if not gta or type(gta.HandleToPointer) ~= "function" then return nil end
            local ok, current = pcall(gta.HandleToPointer, proof.handle)
            if not ok then return nil end
            pointer = current
            local current_address = Live.super_melee_address(pointer)
            if current_address == nil then return nil end
            if current_address ~= address then return false end
        end
        if proof.native_identity == true then
            local networked, network_raw, network_err = invoke_bool_detail(H.NETWORK_GET_ENTITY_IS_NETWORKED,
                proof.handle)
            if network_err or network_raw == nil then return nil end
            if networked ~= (proof.networked == true) then return false end
            if proof.network_id then
                local id, id_raw, id_err = invoke_int_detail(H.NETWORK_GET_NETWORK_ID_FROM_ENTITY, proof.handle)
                if id_err or type(id_raw) ~= "number" or id_raw <= 0 then return nil end
                if id ~= proof.network_id then return false end
            elseif not address and now_ms() ~= proof.identity_ms then
                -- Discovery without an instance fingerprint remains same-tick
                -- only. Never retain damage authorization on a bare handle.
                return false
            end
        elseif pointer then
            local id, known = Ignore.network(pointer)
            if not known then return nil end
            if id ~= proof.network_id then return false end
        else
            return nil
        end
        return true
    end

    function Live.super_melee_proof_current(proof)
        if not proof or proof.retired or not Live.super_melee_owner_current(proof.ped) then return false end
        local identity = Live.super_melee_target_identity_current(proof)
        if identity ~= true then
            if identity == false then
                proof.retired = true; proof.reason = "target instance changed"
            end
            return false
        end
        if proof.generation ~= (tonumber(State.super_melee.generation) or 0) then
            proof.retired = true; proof.reason = "player lifecycle changed"; return false
        end
        if proof.native_identity == true then
            local captured_address = proof.instance_address or proof.strike_address or proof.shape_address
            if captured_address then
                local ok, ptr = pcall(gta.HandleToPointer, proof.handle)
                if not ok or Live.super_melee_address(ptr) ~= captured_address then
                    proof.retired = true; proof.reason = "strike target pointer changed"; return false
                end
            end
            -- GET_MELEE_TARGET_FOR_PED / GET_LAST_ENTITY_HIT_BY_ENTITY already return
            -- current engine script handles. Do not make those fresh hit sources
            -- depend on Cherax CPhysical wrapper conversion or Messiah's historic
            -- released-GUID registry: numeric script handles can be reused later.
            if not entity_exists(proof.handle) or Live.super_melee_target_excluded(proof.handle, proof.ped) then
                proof.retired = true; proof.reason = "native target no longer exists"; return false
            end
            local kind, entity_type = Live.super_melee_native_kind(proof.handle)
            local target_model = invoke_int(H.GET_ENTITY_MODEL, proof.handle)
            if kind == "invalid" or entity_type ~= proof.entity_type or target_model ~= proof.target_model then
                proof.retired = true; proof.reason = "native target type/model identity changed"; return false
            end
            if proof.owner_model ~= 0 and invoke_int(H.GET_ENTITY_MODEL, proof.ped) ~= proof.owner_model then
                proof.retired = true; proof.reason = "local player model identity changed"; return false
            end
            if proof.owner_instance_address then
                local ok, pointer = pcall(gta.HandleToPointer, proof.ped)
                if not ok or Live.super_melee_address(pointer) ~= proof.owner_instance_address then return false end
            end
            local current_networked = invoke_bool(H.NETWORK_GET_ENTITY_IS_NETWORKED, proof.handle) == true
            if current_networked ~= (proof.networked == true) then
                proof.retired = true; proof.reason = "native target networked state changed"; return false
            end
            if proof.networked == true and proof.network_id ~= nil then
                local current_network = invoke_int(H.NETWORK_GET_NETWORK_ID_FROM_ENTITY, proof.handle)
                if tonumber(current_network) ~= tonumber(proof.network_id) then
                    proof.retired = true; proof.reason = "native target network identity changed"; return false
                end
            end
            proof.captured_ms = now_ms()
            return Live.super_melee_owner_current(proof.ped)
        end
        if Ignore.released(proof.handle) then return false end
        local owner_ok, owner = pcall(gta.HandleToPointer, proof.ped)
        local owner_net, owner_known = Ignore.network(owner)
        if not owner_ok or Live.super_melee_address(owner) ~= proof.owner_address
            or not owner_known or owner_net ~= proof.owner_network
            or invoke_int(H.GET_ENTITY_MODEL, proof.ped) ~= proof.owner_model then
            proof.retired = true; proof.reason = "local player identity changed"; return false
        end
        local ok, pointer
        if proof.slot ~= nil and proof.spec and type(pool_mgr[proof.spec[3]]) == "function" then
            ok, pointer = pcall(pool_mgr[proof.spec[3]], proof.slot)
            if not ok or Live.super_melee_address(pointer) ~= proof.address then
                proof.retired = true; proof.reason = "indexed target disappeared or changed"; return false
            end
        elseif proof.spec and pool_mgr and type(pool_mgr[proof.spec[2]]) == "function" then
            -- Rendered map keys are not pool indices. Obtain a NEW wrapper from
            -- the current map on every validation; never retain a frame alias.
            for _, current in ipairs(Live.super_melee_rendered(proof.spec)) do
                if Live.super_melee_address(current) == proof.address then
                    pointer = current; break
                end
            end
            if pointer == nil then
                proof.retired = true; proof.reason = "target unavailable in current rendered list"; return false
            end
        elseif not proof.spec and proof.direct_authorized == true then
            -- A confirmed punch can release GTA's melee lock as the victim
            -- falls. The lock is a discovery source, not its physical lifetime.
            -- Reacquire the same handle/address/NetObject/model below instead.
            ok, pointer = pcall(gta.HandleToPointer, proof.handle)
            if not ok then pointer = nil end
        end
        local current_handle
        if pointer ~= nil then
            local refreshed = Live.super_melee_resolve(pointer, proof.slot, proof.spec, proof.ped)
            if not refreshed or refreshed.address ~= proof.address or refreshed.network_id ~= proof.network_id
                or refreshed.owner_address ~= proof.owner_address or refreshed.owner_network ~= proof.owner_network
                or refreshed.target_model ~= proof.target_model
                or refreshed.generation ~= proof.generation then
                proof.retired = true; proof.reason = "target address, NetObject or model identity changed"; return false
            end
            current_handle = refreshed.handle
        end
        if current_handle ~= proof.handle then
            proof.retired = true; proof.reason = "target handle no longer freshly resolved"; return false
        end
        ok, pointer = pcall(gta.HandleToPointer, proof.handle)
        local net, known = Ignore.network(pointer)
        if not ok or Live.super_melee_address(pointer) ~= proof.address
            or not known or net ~= proof.network_id
            or not Live.super_melee_owner_current(proof.ped)
            or proof.generation ~= (tonumber(State.super_melee.generation) or 0) then
            proof.retired = true; proof.reason = "target roundtrip changed"; return false
        end
        proof.captured_ms = now_ms()
        return true
    end

    function Live.super_melee_native(kind, hash, entity, ...)
        local proof = State.super_melee.proofs and State.super_melee.proofs[entity]
        if not Live.super_melee_proof_current(proof) then return kind == "bool" and false or nil end
        local fn = kind == "bool" and invoke_bool_detail or kind == "int" and invoke_int_detail
            or kind == "vec3" and invoke_vec3 or invoke_void_detail
        if type(fn) ~= "function" then return nil end
        local ok, value, raw, err = pcall(fn, hash, entity, ...)
        if not ok or err then
            proof.retired = true; return nil
        end
        return value
    end

    function Live.super_melee_kind(entity)
        local entity_type = Live.super_melee_native("int", H.GET_ENTITY_TYPE, entity)
        if entity_type == 1 or Live.super_melee_native("bool", H.IS_ENTITY_A_PED, entity) then return "ped" end
        if entity_type == 2 or Live.super_melee_native("bool", H.IS_ENTITY_A_VEHICLE, entity) then return "vehicle" end
        if entity_type == 3 or Live.super_melee_native("bool", H.IS_ENTITY_AN_OBJECT, entity) then return "object" end
        return "invalid"
    end

    function Live.super_melee_preview_entity(entity)
        if tonumber(State.outfit and State.outfit.preview_ped) == tonumber(entity) then return true end
        local manager = module_context and module_context.CScript and module_context.CScript.VehicleManager
        if manager and type(manager.PreviewDiagnostics) == "function" then
            local ok, diagnostics = pcall(manager.PreviewDiagnostics)
            if ok and type(diagnostics) == "table"
                and tonumber(diagnostics.vehicle) == tonumber(entity) then
                return true
            end
        end
        return false
    end

    function Live.super_melee_key_down(vk)
        if not (utils and type(utils.IsKeyDown) == "function") then return false end
        local ok, value = pcall(utils.IsKeyDown, vk)
        return ok and value == true
    end

    function Live.super_melee_vehicle_attack(ped)
        if invoke_bool(H.IS_PED_IN_ANY_VEHICLE, ped, false) ~= true then return nil end
        local vehicle = invoke_int(H.GET_VEHICLE_PED_IS_IN, ped, false)
        if not vehicle or vehicle <= 0 or not entity_exists(vehicle) then return nil end
        local model = invoke_int(H.GET_ENTITY_MODEL, vehicle)
        if model == 0 or (not invoke_bool(H.IS_THIS_MODEL_A_BIKE, model)
                and not invoke_bool(H.IS_THIS_MODEL_A_BICYCLE, model)) then
            return nil
        end
        if not Live.super_melee_key_down(0x58) then return nil end -- X / vehicle melee modifier
        local left, right = Live.super_melee_key_down(0x01), Live.super_melee_key_down(0x02)
        if not left and not right then return nil end
        local forward = invoke_vec3(H.GET_ENTITY_FORWARD_VECTOR, vehicle)
        local fx, fy = vector_components(forward); fx, fy = tonumber(fx), tonumber(fy)
        local magnitude = fx and fy and math.sqrt(fx * fx + fy * fy) or 0.0
        if magnitude < 0.001 then return nil end
        fx, fy = fx / magnitude, fy / magnitude
        -- Mouse side selects the lateral strike envelope while X is held.
        local side = left and 1.0 or -1.0
        return {
            vehicle = vehicle,
            fx = -fy * side,
            fy = fx * side,
            mode = left and "bike-left" or "bike-right",
            driveby = invoke_bool(H.IS_PED_DOING_DRIVEBY, ped) == true
        }
    end

    function Live.super_melee_attack_frame(ped)
        local ped_coords = invoke_vec3(H.GET_ENTITY_COORDS, ped, false)
        local px, py, pz = vector_components(ped_coords)
        local swing = State.super_melee.swing
        local fx, fy = tonumber(swing.attack_fx), tonumber(swing.attack_fy)
        if not fx or not fy then
            local forward = invoke_vec3(H.GET_ENTITY_FORWARD_VECTOR, ped)
            fx, fy = vector_components(forward); fx, fy = tonumber(fx), tonumber(fy)
        end
        px, py, pz = tonumber(px), tonumber(py), tonumber(pz)
        local magnitude = fx and fy and math.sqrt(fx * fx + fy * fy) or 0.0
        if not px or not py or not pz or magnitude < 0.001 then return nil end
        return { x = px, y = py, z = pz, fx = fx / magnitude, fy = fy / magnitude }
    end

    function Live.super_melee_spatial_from_frame(frame, ex, ey, ez)
        ex, ey, ez = tonumber(ex), tonumber(ey), tonumber(ez)
        if not frame or not ex or not ey or not ez then return nil, nil end
        local px, py, pz, fx, fy = frame.x, frame.y, frame.z, frame.fx, frame.fy
        local dx, dy, dz = ex - px, ey - py, ez - pz
        local horizontal = math.sqrt(dx * dx + dy * dy)
        local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
        local alignment = horizontal < 0.001 and 1.0 or ((dx / horizontal) * fx + (dy / horizontal) * fy)
        return distance, Live.super_melee_finite_clamp(alignment, -1.0, 1.0)
    end

    function Live.super_melee_spatial(ped, entity, frame)
        frame = frame or Live.super_melee_attack_frame(ped)
        local entity_coords = Live.super_melee_native("vec3", H.GET_ENTITY_COORDS, entity, false)
        local ex, ey, ez = vector_components(entity_coords)
        return Live.super_melee_spatial_from_frame(frame, ex, ey, ez)
    end

    function Live.super_melee_pointer_position(pointer)
        if pointer == nil then return nil, nil, nil end
        local ok, value = pcall(function() return pointer.Position end)
        if not ok then return nil, nil, nil end
        local x, y, z = vector_components(value)
        x, y, z = tonumber(x), tonumber(y), tonumber(z)
        if not x or not y or not z or x ~= x or y ~= y or z ~= z then return nil, nil, nil end
        return x, y, z
    end

    function Live.super_melee_ranked_handles(ped, direct, idle, supplemental)
        local frame = Live.super_melee_attack_frame(ped)
        if not frame or not Live.super_melee_owner_current(ped) then return {}, nil, 0 end
        local state = State.super_melee
        state.proofs = state.proofs or {}
        local ranked, seen = {}, {}
        -- Preserve the 32-candidate bound, but do not let the first visited
        -- pool starve the others. Keep the nearest within each kind, not the
        -- first wrappers returned by its iterator. Direct targeting remains
        -- one additional discovery slot and still needs fresh hit evidence.
        local budgets = { ped = 16, vehicle = 12, object = 4 }
        local counts = { ped = 0, vehicle = 0, object = 0 }
        local specs = {
            { "ped",     "GetRenderedPeds",     "GetCPed",     "GetPed",     "GetMaxPedCount",     4.5 },
            { "vehicle", "GetRenderedVehicles", "GetCVehicle", "GetVehicle", "GetMaxVehicleCount", 12.0 },
            { "object",  "GetRenderedObjects",  "GetCObject",  "GetObject",  "GetMaxObjectCount",  5.5 },
        }
        local function add(pointer, slot, spec)
            local ex, ey, ez = Live.super_melee_pointer_position(pointer)
            local distance, alignment = Live.super_melee_spatial_from_frame(frame, ex, ey, ez)
            -- A vehicle's origin can be to the side/behind an actual door or
            -- bumper impact. Keep it in the bounded shortlist; only fresh
            -- attributed damage + touching can relax its final centre-angle gate.
            if not distance or distance > spec[6]
                or (spec[1] ~= "vehicle" and alignment < -.10 and distance > 1.25) then
                return
            end
            local proof = Live.super_melee_resolve(pointer, slot, spec, ped)
            if not proof or Live.super_melee_target_excluded(proof.handle, ped) then return end
            local existing = seen[proof.address]
            if existing then
                if slot ~= nil and existing.proof.slot == nil
                    and existing.proof.handle == proof.handle and existing.proof.network_id == proof.network_id then
                    existing.proof.slot, existing.proof.spec, existing.proof.route = slot, spec, proof.route
                    local pending = state.pending[proof.handle]
                    if pending and pending.proof.address == proof.address and pending.proof.network_id == proof.network_id then
                        pending.proof.slot, pending.proof.spec, pending.proof.route = slot, spec, proof.route
                    end
                end
                return
            end
            local kind = spec[1]
            local replace_index = nil
            if counts[kind] >= budgets[kind] then
                local farthest = nil
                for index, row in ipairs(ranked) do
                    if row.kind == kind and (not farthest or row.distance > farthest.distance
                            or (row.distance == farthest.distance and row.handle > farthest.handle)) then
                        replace_index, farthest = index, row
                    end
                end
                if not farthest or distance > farthest.distance
                    or (distance == farthest.distance and proof.handle >= farthest.handle) then
                    return
                end
                seen[farthest.proof.address] = nil
                -- Pending physics owns its own identity, independent of which
                -- discovery rows are closest in this later frame.
                local pending = state.pending[farthest.handle]
                state.proofs[farthest.handle] = pending and pending.proof or nil
            end
            local row = { handle = proof.handle, distance = distance, alignment = alignment, proof = proof, kind = kind }
            seen[proof.address] = row; state.proofs[proof.handle] = proof
            if replace_index then
                ranked[replace_index] = row
            else
                ranked[#ranked + 1] = row; counts[kind] = counts[kind] + 1
            end
        end
        -- Use rendered maps for nearby entities. Their keys are not pool indices;
        -- indexed C++ pool scans are excluded because their wrappers can become stale.
        state.scan_cursors = state.scan_cursors or {}
        for _, spec in ipairs(specs) do
            local visits = 0
            if pool_mgr and type(pool_mgr[spec[2]]) == "function" then
                for _, pointer in ipairs(Live.super_melee_rendered(spec)) do
                    visits = visits + 1
                    add(pointer, nil, spec)
                end
            end
        end
        -- Native direct-hit sources are authoritative discovery handles from GTA.
        -- Prefer an already-proved rendered identity if one exists for this exact
        -- handle; otherwise use a bounded pure-native proof. This prevents a
        -- transient Cherax PointerToHandle/HandleToPointer failure from disabling
        -- Super Melee while keeping proximity alone insufficient as hit evidence.
        local function add_native_source(handle, route)
            handle = tonumber(handle)
            if not handle or handle <= 0 or Live.super_melee_target_excluded(handle, ped) then return end
            local proof = Live.super_melee_native_proof(handle, ped, route, frame)
            if not proof then return end
            for _, row in ipairs(ranked) do
                if tonumber(row.handle) == handle then
                    row.proof, row.distance, row.alignment = proof, proof.distance, proof.alignment
                    state.proofs[handle] = proof
                    return
                end
            end
            state.proofs[handle] = proof
            ranked[#ranked + 1] = {
                handle = handle,
                distance = proof.distance,
                alignment = proof.alignment,
                proof = proof,
                kind = Live.super_melee_native_kind(handle)
            }
        end
        if type(player_available) == "function" and type(player_ped) == "function" then
            for pid = 0, 31 do
                if pid ~= local_player_id() and player_available(pid) then
                    local other = player_ped(pid)
                    if other and other > 0 and entity_exists(other) then
                        local occupied = invoke_int(H.GET_VEHICLE_PED_IS_IN, other, false)
                        if occupied and occupied > 0 then add_native_source(occupied, "native-player-vehicle") end
                    end
                end
            end
        end
        if tonumber(direct) and direct > 0 then add_native_source(direct, "native-direct") end
        -- A fresh GET_LAST_ENTITY_HIT_BY_ENTITY edge is an independent hit source.
        -- It is supplemental only; stale values are filtered by the caller.
        if tonumber(supplemental) and supplemental > 0 and supplemental ~= direct then
            add_native_source(supplemental, "native-last-hit")
        end
        -- One synchronous forward probe is allowed only while a real melee swing
        -- is active. It discovers what the fist/bike strike is actually facing,
        -- but it still cannot authorize force by proximity: super_melee_candidate
        -- below still requires a fresh GTA damage/last-hit edge for this entity.
        if idle ~= true and State.super_melee.swing.active == true then
            local shape_handle, shape_proof, shape_error = Live.super_melee_shape_target(ped, frame)
            local outcome = shape_error or ("target:" .. tostring(shape_handle))
            if state.swing.shape_outcome ~= outcome then
                state.swing.shape_outcome = outcome
                Live.super_melee_trace("SUCCESS_UNVERIFIED", "discovery",
                    ("swing=%s shape=%s"):format(tostring(state.swing.id), outcome))
            end
            if shape_handle and shape_proof then
                local duplicate = false
                for _, row in ipairs(ranked) do
                    if tonumber(row.handle) == tonumber(shape_handle) then
                        duplicate = true; break
                    end
                end
                if duplicate then
                    -- Do not release a duplicate numeric alias here: GTA may have
                    -- returned the same live script GUID already owned by another
                    -- discovery route. Let the owning proof/script lifetime keep it.
                    shape_proof.shape_borrowed = false
                    shape_proof.shape_released = true
                    shape_proof.retired = true
                else
                    state.proofs[shape_handle] = shape_proof
                    ranked[#ranked + 1] = {
                        handle = shape_handle,
                        distance = shape_proof.distance,
                        alignment = shape_proof.alignment,
                        proof = shape_proof,
                        kind = Live.super_melee_native_kind(shape_handle)
                    }
                end
            end
        end
        table.sort(ranked, function(l, r) return (l.distance or math.huge) < (r.distance or math.huge) end)
        return ranked, frame, #ranked
    end

    function Live.super_melee_observation_key(proof)
        -- A rendered pointer and a native hit handle can describe the same entity.
        -- Key damage history by the checked engine identity, not discovery route.
        return table.concat({ tostring(proof.handle), tostring(proof.target_model),
            tostring(proof.network_id or 0), tostring(proof.generation),
            tostring(proof.instance_address or proof.strike_address or proof.shape_address
                or (type(proof.address) == "number" and proof.address)
                or (proof.network_id and "network" or proof.identity_ms)) }, ":")
    end

    function Live.super_melee_observation_current(observation, proof)
        return observation.handle == proof.handle and observation.network_id == proof.network_id
            and observation.target_model == proof.target_model
            and observation.identity == Live.super_melee_observation_key(proof)
    end

    function Live.super_melee_observe(entity, ped, now, touching, distance, alignment)
        local swing = State.super_melee.swing
        local damaged_by_entity = Live.super_melee_native("bool", H.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY, entity, ped, true)
        local damaged_by_melee = Live.super_melee_native("bool", H.HAS_ENTITY_BEEN_DAMAGED_BY_WEAPON, entity, 0, 1)
        local proof = State.super_melee.proofs and State.super_melee.proofs[entity]
        if not Live.super_melee_proof_current(proof) then return false, false, false, false, false, false, false end
        local identity = Live.super_melee_observation_key(proof)
        local observation = swing.observations[identity]
        local identity_replaced = observation ~= nil and not Live.super_melee_observation_current(observation, proof)
        if identity_replaced then observation = nil end
        local first_seen_late = observation == nil and now > (tonumber(swing.started_ms) or now)
        local health = Live.super_melee_native("int", H.GET_ENTITY_HEALTH, entity)
        local health_fell = observation and type(health) == "number" and type(observation.health) == "number"
            and health < observation.health
        local fatal_melee = false
        local previous_age = observation and now - (observation.last_seen_ms or observation.first_seen_ms or now)
        if health_fell and observation.health > 0 and health <= 0 and previous_age >= 0
            and previous_age <= Live.SUPER_MELEE_PRESTRIKE_MAX_AGE_MS
            and Live.super_melee_kind(entity) == "ped"
            and Live.super_melee_native("int", H.GET_PED_SOURCE_OF_DEATH, entity) == ped then
            local cause = Live.super_melee_native("int", 0x16FFE42AB2D2DC59, entity)
            local group = cause and invoke_int(0xC3287EE3050FB74C, cause) or 0
            -- Weapon hash/group values are joaat values, not memory offsets.
            fatal_melee = type(cause) == "number" and (cause % 4294967296 == 0xA2719263
                or (type(group) == "number" and group % 4294967296 == 0xD49321D4))
        end
        -- Health loss cannot refresh sticky attacker/melee histories. It may
        -- supplement only an independently fresh strike positioned to this target;
        -- ordinary fresh attacker transitions remain valid without that route.
        local bound_strike = health_fell and Live.super_melee_nonped_contact(entity, ped,
            Live.super_melee_kind(entity), touching, alignment or -1, now, false)
        local damaged_by_entity_fresh = damaged_by_entity
            and ((observation and observation.damage_entity ~= true)
                or bound_strike)
        local damaged_by_melee_fresh = damaged_by_melee
            and ((observation and observation.damage_melee ~= true) or bound_strike)
        -- A pre-strike edge must also be melee-attributed. A gunshot immediately
        -- before starting a punch must not inherit the punch's physics response.
        if observation and observation.from_prestrike and damaged_by_melee ~= true then
            damaged_by_entity_fresh = false
        end
        if observation and observation.from_prestrike and observation.damage_entity == true then
            -- Another attacker may lower health while old attribution stays set.
            damaged_by_entity_fresh = false
        end
        local contact_edge = touching == true and observation ~= nil and observation.touching == false
        if not observation then
            observation = {
                first_seen_ms = now,
                handle = proof.handle,
                network_id = proof.network_id,
                target_model = proof.target_model,
                identity = identity
            }
            swing.observations[identity] = observation
        end
        if fatal_melee then observation.fatal_melee_ms = now end
        if damaged_by_entity_fresh then observation.attacker_edge_ms = now end
        if damaged_by_melee_fresh then observation.melee_edge_ms = now end
        local function recent(at)
            return at ~= nil and now >= at and now - at <= Live.SUPER_MELEE_HIT_EVIDENCE_LIFETIME_MS
        end
        damaged_by_entity_fresh = recent(observation.attacker_edge_ms)
        damaged_by_melee_fresh = recent(observation.melee_edge_ms)
        if contact_edge then observation.contact_edge_ms = now end
        if touching ~= true then observation.contact_edge_ms = nil end
        -- A real contact edge can arrive before the 90 ms strike gate. Retain
        -- that observed edge briefly instead of swallowing it in the baseline.
        local contact_fresh = touching == true and observation.contact_edge_ms ~= nil
            and now >= observation.contact_edge_ms and now - observation.contact_edge_ms <= 150
        observation.last_seen_ms = now
        observation.from_prestrike = nil
        observation.damage_entity = damaged_by_entity
        observation.damage_melee = damaged_by_melee
        observation.health, observation.touching = health, touching
        return damaged_by_entity, damaged_by_melee,
            damaged_by_entity_fresh, damaged_by_melee_fresh, first_seen_late, contact_fresh, identity_replaced,
            recent(observation.fatal_melee_ms)
    end

    -- Current hand/foot locations come from the documented bone native and
    -- IDs already used by the player effects. Sampling never enumerates pools.
    -- Limb segments bind a fresh engine strike to its exact target. Approach,
    -- wind-up and ordinary limb collisions never authorize force on their own.
    function Live.sample_super_melee_limb_contact(ped, now, check_contact, ped_strike)
        local state, swing = State.super_melee, State.super_melee.swing
        if swing.action_was_performing ~= true then
            state.limb_samples = nil
            return nil
        end
        local previous = state.limb_samples
        local rx, ry, rz = vector_components(invoke_vec3(H.GET_ENTITY_COORDS, ped, false))
        if type(rx) ~= "number" or type(ry) ~= "number" or type(rz) ~= "number" then
            state.limb_samples = nil; return nil
        end
        local root = { x = rx, y = ry, z = rz }
        local sample = {
            ped = ped,
            ms = now,
            generation = state.generation,
            swing_id = swing.id,
            points = {},
            frames = {},
            root =
                root
        }
        state.limb_samples = sample
        local continuous = previous and previous.ped == ped and previous.generation == state.generation
            and previous.swing_id == swing.id and now > previous.ms and now - previous.ms <= 80
        local displaced = 0
        for index, bone in ipairs({ 57005, 18905, 52301, 14201 }) do
            local point = invoke_vec3(0x17C07FC640E86B4E, ped, bone, 0.0, 0.0, 0.0)
            local x, y, z = vector_components(point)
            x, y, z = tonumber(x), tonumber(y), tonumber(z)
            if x and y and z and x == x and y == y and z == z
                and math.abs(x) < math.huge and math.abs(y) < math.huge and math.abs(z) < math.huge then
                sample.points[index] = { x = x, y = y, z = z }
                local old = continuous and previous.points[index]
                if old then
                    local dx, dy, dz = x - old.x, y - old.y, z - old.z
                    if dx * dx + dy * dy + dz * dz > 1.44 then displaced = displaced + 1 end
                end
            end
        end
        -- Scalar frame records do not retain wrappers, handles, or nested history.
        sample.frames[1] = { ms = now, points = sample.points, root = root }
        if continuous and displaced < 2 then
            for _, frame in ipairs(previous.frames or { { ms = previous.ms, points = previous.points } }) do
                if #sample.frames >= 6 then break end
                if now >= frame.ms and now - frame.ms <= 80 then sample.frames[#sample.frames + 1] = frame end
            end
        end
        if not check_contact then return nil end
        local frame = Live.super_melee_attack_frame(ped)
        if not frame then return nil, "attack-frame-unavailable" end
        local selected, ambiguous = nil, false
        local tested = 0
        state.shape_inflight = {}
        -- The engine strike pulse may follow contact/rebound by a frame. Test
        -- only actually sampled adjacent limb segments from the preceding 80ms.
        -- No broad cone/radius or interpolation across missing frames.
        local segments = {}
        for step = 1, #sample.frames - 1 do
            local current, prior = sample.frames[step], sample.frames[step + 1]
            if current.ms > prior.ms and current.ms - prior.ms <= 80 then
                for index = 1, 4 do
                    local point, old = current.points[index], prior.points[index]
                    if point and old then
                        local dx, dy, dz = point.x - old.x, point.y - old.y, point.z - old.z
                        local travel = dx * dx + dy * dy + dz * dz
                        local root_before, root_after = prior.root, current.root
                        local relative = 0
                        if root_before and root_after then
                            local ux = dx - (root_after.x - root_before.x)
                            local uy = dy - (root_after.y - root_before.y)
                            local uz = dz - (root_after.z - root_before.z)
                            relative = ux * ux + uy * uy + uz * uz
                        end
                        if travel >= 0.0004 and travel <= 1.44 and relative >= 0.0001 then
                            segments[#segments + 1] = {
                                old = old,
                                point = point,
                                index = index,
                                score = relative,
                                at = current.ms,
                                dx = dx,
                                dy = dy,
                                dz = dz,
                                travel = travel
                            }
                        end
                    end
                end
            end
        end
        table.sort(segments, function(a, b)
            if a.score ~= b.score then return a.score > b.score end
            if a.at ~= b.at then return a.at > b.at end
            return a.index < b.index
        end)
        for _, segment in ipairs(segments) do
            if tested >= 12 then break end
            tested = tested + 1
            local old, point = segment.old, segment.point
            -- The native hand/foot bone is inside the striking mesh. Cover only
            -- 12 cm beyond its observed travel, and only after a fresh GTA strike.
            -- This is never an input/proximity-only authorization.
            local tip = 0.12 / math.sqrt(segment.travel)
            local entity, proof = Live.super_melee_shape_target(ped, frame,
                {
                    x1 = old.x,
                    y1 = old.y,
                    z1 = old.z,
                    x2 = point.x + segment.dx * tip,
                    y2 = point.y + segment.dy * tip,
                    z2 = point.z + segment.dz * tip
                })
            if entity and proof then
                local kind = Live.super_melee_native_kind(entity)
                if (ped_strike and kind == "ped") or (not ped_strike and (kind == "vehicle" or kind == "object")) then
                    if selected and selected.target ~= entity then ambiguous = true end
                    if not selected then
                        selected = { target = entity, proof = proof, trajectory_age_ms = now - segment.at }
                        state.shape_inflight[entity] = proof
                    end
                end
                if not selected or selected.proof ~= proof then
                    if selected and selected.target == entity then
                        proof.shape_borrowed = false; proof.shape_released = true
                    else
                        Live.super_melee_release_shape_proof(proof, "unselected limb contact")
                    end
                end
            end
        end
        state.shape_inflight = nil
        swing.limb_test_detail = ("trajectoryFrames=%d segments=%d displaced=%d"):format(#sample.frames, tested,
            displaced)
        if selected and ambiguous then
            Live.super_melee_release_shape_proof(selected.proof, "ambiguous simultaneous limb contacts")
            return nil, "ambiguous"
        end
        return selected
    end

    -- Reset flag 316 is a one-frame engine report of an actual melee strike
    -- against non-ped material. It is NOT a target selector. Bind a new edge to
    -- the engine's exact hit entity; never combine a wall hit with a nearby car.
    function Live.super_melee_fresh_direct_ped_contact(ped, now)
        local swing = State.super_melee.swing
        local direct = invoke_int(H.GET_MELEE_TARGET_FOR_PED, ped)
        if not direct or direct <= 0 or direct ~= swing.direct_target then return nil end
        local proof = Live.super_melee_native_proof(direct, ped, "native-direct")
        if not proof or Live.super_melee_native_kind(direct) ~= "ped" then return nil end
        local observation = swing.observations[Live.super_melee_observation_key(proof)]
        local age = observation and now - (observation.last_seen_ms or observation.first_seen_ms or now)
        if not observation or not Live.super_melee_observation_current(observation, proof)
            or age < 0 or age > 80
            or observation.damage_entity ~= false
            or type(observation.health) ~= "number" or observation.health <= 0 then
            return nil
        end
        local health = invoke_int(H.GET_ENTITY_HEALTH, direct)
        local melee = invoke_bool(H.HAS_ENTITY_BEEN_DAMAGED_BY_WEAPON, direct, 0, 1)
        local attacker = invoke_bool(H.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY, direct, ped, true)
        if type(health) ~= "number" or health >= observation.health or melee ~= true
            or attacker ~= true
            or not Live.super_melee_proof_current(proof) then
            return nil
        end
        -- Called only for a fresh LOCAL reset76 pulse with no shooting conflict.
        -- Bind the explicit target to a fresh local-attacker transition and
        -- health loss with current melee attribution; sticky histories cannot bind it.
        return { target = direct, proof = proof, direct_damage = true }
    end

    function Live.super_melee_fresh_nonped_damage_contact(ped, now, last_hit)
        local swing = State.super_melee.swing
        local handles = Live.super_melee_ranked_handles(ped, 0, true)
        local selected = nil
        -- This helper runs only on a fresh local reset316 pulse without firing.
        -- A unique same-target false->true melee damage edge binds that pulse.
        -- Existing/sticky damage and nearest/forward/touching alone cannot bind it.
        for _, row in ipairs(handles) do
            if row.kind == "vehicle" or row.kind == "object" then
                local proof = row.proof
                local observation = swing.observations[Live.super_melee_observation_key(proof)]
                local age = observation and now - (observation.last_seen_ms or observation.first_seen_ms or now)
                if observation and Live.super_melee_observation_current(observation, proof)
                    and age >= 0 and age <= 80 and observation.damage_melee == false
                    and Live.super_melee_proof_current(proof)
                    and Live.super_melee_native("bool", H.HAS_ENTITY_BEEN_DAMAGED_BY_WEAPON, row.handle, 0, 1) == true
                    and Live.super_melee_proof_current(proof) then
                    if selected and selected.target ~= row.handle then return nil, "ambiguous-fresh-damage" end
                    selected = { target = row.handle, proof = proof, damage_binding = true }
                end
            end
        end
        if selected and tonumber(last_hit) and last_hit > 0 and last_hit ~= selected.target then
            return nil, "engine-target-conflicts-with-fresh-damage"
        end
        return selected
    end

    function Live.sample_super_melee_nonped_strike(ped, now)
        local state, swing = State.super_melee, State.super_melee.swing
        local value = invoke_bool(0xAF9E59B1B1FBF2A0, ped, 316) == true
        local ped_value = invoke_bool(0xAF9E59B1B1FBF2A0, ped, 76) == true
        local firing = invoke_bool(H.IS_PED_SHOOTING, ped)
            or invoke_bool(0xAF9E59B1B1FBF2A0, ped, 14)
        if firing then state.last_melee_conflicting_shot_ms = now end
        local shot = state.last_melee_conflicting_shot_ms
        local shooting_conflict = firing or (shot and now >= shot and now - shot <= 180)
        local last = invoke_int(H.GET_LAST_ENTITY_HIT_BY_ENTITY, ped)
        local prior = state.nonped_strike_sample
        local action = swing.action_was_performing == true or (swing.active == true
            and swing.action_ended_ms and now >= swing.action_ended_ms and now - swing.action_ended_ms <= 80)
        local owner_address = nil
        if action then
            local owner_ok, owner_ptr = pcall(gta.HandleToPointer, ped)
            owner_address = owner_ok and Live.super_melee_address(owner_ptr) or nil
        end
        state.nonped_strike_sample = {
            value = value,
            ped_value = ped_value,
            ped = ped,
            owner_address = owner_address,
            last_hit =
                last,
            ms = now,
            generation = state.generation
        }
        local fresh = value and prior and prior.value == false and prior.ped == ped
            and owner_address and (prior.owner_address == owner_address or prior.owner_address == nil)
            and prior.generation == state.generation and now >= prior.ms and now - prior.ms <= 80
        local ped_fresh = ped_value and prior and prior.ped_value == false and prior.ped == ped
            and owner_address and (prior.owner_address == owner_address or prior.owner_address == nil)
            and prior.generation == state.generation and now > prior.ms and now - prior.ms <= 80
        local use_ped = ped_fresh and not fresh
        local limb, limb_error = Live.sample_super_melee_limb_contact(ped, now, (fresh or ped_fresh) and action
            and not shooting_conflict, use_ped)
        if not limb and limb_error ~= "ambiguous" and use_ped and action and not shooting_conflict then
            limb = Live.super_melee_fresh_direct_ped_contact(ped, now)
        end
        if not limb and limb_error ~= "ambiguous" and fresh and action and not shooting_conflict then
            limb, limb_error = Live.super_melee_fresh_nonped_damage_contact(ped, now, last)
        end
        if (value or ped_value) and (not prior or prior.value ~= value or prior.ped_value ~= ped_value) then
            Live.super_melee_trace("SUCCESS_UNVERIFIED", "strike sample",
                ("swing=%s reset76=%s reset316=%s action=%s fresh76=%s fresh316=%s exactLimb=%s shooting=%s lastHit=%s")
                :format(tostring(swing.id), tostring(ped_value), tostring(value), tostring(action == true),
                    tostring(ped_fresh == true), tostring(fresh == true), tostring(limb and limb.target or 0),
                    tostring(shooting_conflict == true), tostring(last)) .. " " .. tostring(swing.limb_test_detail or "")
                .. " binding=" ..
                tostring(limb and (limb.damage_binding and "fresh-melee-edge" or "limb-or-ped") or limb_error or "none"))
        end
        if (fresh or ped_fresh) and action and not shooting_conflict and (not use_ped or limb) then
            local proof = state.proofs and state.proofs[last]
            if not Live.super_melee_target_excluded(last, ped) and not Live.super_melee_proof_current(proof) then
                proof = Live.super_melee_native_proof(last, ped, "native-strike")
                if proof then
                    local ok, ptr = pcall(gta.HandleToPointer, last)
                    proof.strike_address = ok and Live.super_melee_address(ptr) or nil
                end
            end
            local changed = (fresh or ped_fresh) and prior and prior.last_hit ~= nil and prior.last_hit ~= last or false
            -- A freshly changed engine target wins. A stale last-hit field may
            -- be replaced ONLY by an exact limb collision on this strike pulse.
            if limb and (use_ped or not changed or last == limb.target or not proof) then
                if proof and proof.handle == limb.target then
                    limb.proof.shape_borrowed = false; limb.proof.shape_released = true
                else
                    proof = limb.proof
                end
                last = limb.target
            elseif limb then
                Live.super_melee_release_shape_proof(limb.proof, "engine target disagrees with limb contact"); limb = nil
            end
            if (changed or limb ~= nil) and proof and proof.handle == last and Live.super_melee_proof_current(proof) then
                local previous_hit = state.nonped_strike
                state.proofs[last] = proof -- protect shared GUID during transfer
                state.nonped_strike = {
                    target = last,
                    proof = proof,
                    ms = now,
                    generation = state.generation,
                    last_changed = changed,
                    limb_contact = limb ~= nil and limb.direct_damage ~= true and limb.damage_binding ~= true,
                    nonped_damage = limb and limb.damage_binding == true,
                    ped_contact = use_ped == true,
                    ped_direct = limb and limb.direct_damage == true
                }
                if previous_hit and previous_hit.proof ~= proof then
                    local pending = state.pending[previous_hit.target]
                    if not pending or pending.proof ~= previous_hit.proof then
                        Live.super_melee_release_shape_proof(previous_hit.proof, "strike replaced")
                        if state.proofs[previous_hit.target] == previous_hit.proof then state.proofs[previous_hit.target] = nil end
                    end
                end
                Live.super_melee_trace("SUCCESS_UNVERIFIED", "strike",
                    ("swing=%s strikeFlag=%s target=%s limbContact=%s directDamage=%s")
                    :format(tostring(swing.id), use_ped and "76" or "316", tostring(last),
                        tostring(limb ~= nil and limb.direct_damage ~= true and limb.damage_binding ~= true),
                        tostring(limb and limb.direct_damage == true)) ..
                    " damageBinding=" .. tostring(limb and limb.damage_binding == true))
            end
        end
        local hit = state.nonped_strike
        if hit and (now < hit.ms or now - hit.ms > 80 or hit.generation ~= state.generation
                or (not hit.limb_contact and not hit.ped_direct and not hit.nonped_damage and last ~= hit.target) or not Live.super_melee_proof_current(hit.proof)) then
            local pending = state.pending[hit.target]
            if not pending or pending.proof ~= hit.proof then
                Live.super_melee_release_shape_proof(hit.proof, "strike evidence expired")
            end
            state.nonped_strike = nil
        end
    end

    function Live.super_melee_nonped_contact(entity, ped, kind, touching, alignment, now, melee_fresh)
        local hit = State.super_melee.nonped_strike
        if not hit or hit.consumed or hit.target ~= entity
            or (kind == "ped" and (hit.ped_contact ~= true or (hit.limb_contact ~= true and hit.ped_direct ~= true)))
            or (kind ~= "ped" and (hit.ped_contact == true or (kind ~= "vehicle" and kind ~= "object")))
            -- A fresh local ped-strike pulse plus exact limb contact (or a
            -- current melee target with new health loss) needs no second flag.
            -- A door/bumper strike can leave a vehicle centre behind the fist.
            -- Only an independent fresh target edge can relax that centre test.
            or (alignment < 0.1 and hit.last_changed ~= true and melee_fresh ~= true and hit.limb_contact ~= true)
            or (touching ~= true and hit.last_changed ~= true and melee_fresh ~= true and hit.limb_contact ~= true)
            or now < hit.ms or now - hit.ms > 80 or hit.generation ~= State.super_melee.generation
            or invoke_bool(H.IS_PED_SHOOTING, ped)
            or (not hit.limb_contact and not hit.ped_direct and not hit.nonped_damage and invoke_int(H.GET_LAST_ENTITY_HIT_BY_ENTITY, ped) ~= hit.target)
            or (hit.ped_direct and invoke_int(H.GET_MELEE_TARGET_FOR_PED, ped) ~= hit.target)
            or (hit.nonped_damage and (kind == "ped" or melee_fresh ~= true)) then
            return false
        end
        return Live.super_melee_proof_current(hit.proof)
            and Live.super_melee_proof_current(State.super_melee.proofs[entity])
    end

    function Live.super_melee_candidate(entity, ped, direct_ped, now, frame, ranked_distance, ranked_alignment,
                                        last_hit_fresh)
        if not Live.super_melee_proof_current(State.super_melee.proofs and State.super_melee.proofs[entity])
            or Live.super_melee_target_excluded(entity, ped) then
            return nil
        end
        local kind = Live.super_melee_kind(entity)
        if kind == "invalid" then return nil end
        direct_ped = direct_ped == true and kind == "ped"
        local distance, alignment = tonumber(ranked_distance), tonumber(ranked_alignment)
        if not distance or not alignment then distance, alignment = Live.super_melee_spatial(ped, entity, frame) end
        if not distance or alignment == nil then return nil end
        -- Distance is now only a sanity fence. It is never sufficient hit evidence.
        local maximum = kind == "vehicle" and 7.5 or (kind == "object" and 4.0 or 3.25)
        if distance > maximum then return nil end
        local touching = Live.super_melee_native("bool", H.IS_ENTITY_TOUCHING_ENTITY, entity, ped)
        local had_baseline = State.super_melee.swing.observations
            [Live.super_melee_observation_key(State.super_melee.proofs[entity])] ~= nil
        local damaged_by_entity, damaged_by_melee,
        damaged_by_entity_fresh, damaged_by_melee_fresh, first_seen_late, contact_fresh, identity_replaced, fatal_melee =
            Live.super_melee_observe(entity, ped, now, touching, distance, alignment)
        local swing = State.super_melee.swing
        local swing_elapsed = math.max(0, now - (tonumber(swing.started_ms) or now))
        if swing.active ~= true or now > (swing.impact_until_ms or 0) or identity_replaced == true then return nil end
        if swing.action_was_performing ~= true and (not swing.action_ended_ms
                or now - swing.action_ended_ms > 80 or invoke_bool(H.IS_PED_SHOOTING, ped)) then
            return nil
        end
        local shot = State.super_melee.last_melee_conflicting_shot_ms
        if invoke_bool(H.IS_PED_SHOOTING, ped) or (shot and now >= shot and now - shot <= 180) then return nil end
        local direct_contact = touching == true
        local source, score
        -- Amplification requires a fresh GTA hit/damage edge from this local
        -- melee action. Distance, alignment, movement, lock-on, and touching
        -- provide context but cannot establish a hit.
        if Live.super_melee_nonped_contact(entity, ped, kind, touching, alignment, now, damaged_by_melee_fresh) then
            source, score = kind == "ped" and "fresh-ped-strike+bound-target+melee-damage"
                or "fresh-nonped-strike+exact-hit-evidence", 1160.0
        elseif fatal_melee then
            source, score = "fresh-fatal-local-melee", 1170.0
        elseif damaged_by_entity_fresh and damaged_by_melee_fresh then
            source, score = "fresh-attacker+melee-damage", 1140.0
        elseif last_hit_fresh == true and damaged_by_entity_fresh == true then
            -- A fresh last-hit edge plus fresh damage from the local ped is the
            -- strongest generic proof for vehicles/objects where the melee-type
            -- damage flag can be inconsistent across animations.
            source, score = "fresh-last-hit+attacker-damage", 1120.0
        elseif last_hit_fresh == true and damaged_by_entity == true and damaged_by_melee == true
            and direct_ped and touching == true and distance <= 2.4 then
            source, score = "fresh-last-hit+direct-melee-contact", 1110.0
        elseif damaged_by_entity_fresh and damaged_by_melee == true then
            -- The generic melee flag may already be set when this swing starts,
            -- but the attacker-damage edge must still be new in this swing.
            source, score = "fresh-attacker-damage+melee-attribution", 1100.0
        elseif damaged_by_melee_fresh and damaged_by_entity == true and last_hit_fresh == true then
            -- Mirror of the case above: accept only when the fresh melee edge is
            -- paired with GTA's fresh last-hit edge for this exact entity.
            source, score = "fresh-melee-damage+last-hit", 1080.0
        else
            swing.candidate_gates = swing.candidate_gates or {}
            local gate = table.concat({ tostring(damaged_by_entity), tostring(damaged_by_melee),
                tostring(damaged_by_entity_fresh), tostring(damaged_by_melee_fresh), tostring(first_seen_late) }, ":")
            if swing.candidate_gates[entity] ~= gate then
                swing.candidate_gates[entity] = gate
                Live.super_melee_trace("NO_OP", "candidate",
                    ("swing=%s target=%s route=%s baseline=%s attacker=%s melee=%s freshAttacker=%s freshMelee=%s lastHit=%s")
                    :format(tostring(swing.id), tostring(entity), tostring(State.super_melee.proofs[entity].route),
                        tostring(had_baseline), tostring(damaged_by_entity), tostring(damaged_by_melee),
                        tostring(damaged_by_entity_fresh), tostring(damaged_by_melee_fresh), tostring(last_hit_fresh)))
            end
            swing.last_candidate_gate = ("no new GTA melee-hit evidence kind=%s distance=%.2f alignment=%.3f touching=%s contactFresh=%s lastHit=%s attackerDamageFresh=%s meleeFresh=%s elapsedMs=%d (proximity/contact-alone-not-evidence)")
                :format(tostring(kind), distance, alignment, tostring(touching), tostring(contact_fresh == true),
                    tostring(last_hit_fresh == true), tostring(damaged_by_entity_fresh == true),
                    tostring(damaged_by_melee_fresh == true), swing_elapsed)
            Live.super_melee_gate(swing.last_candidate_gate)
            return nil
        end
        if damaged_by_entity_fresh then score = score + 30 end
        if damaged_by_melee_fresh then score = score + 20 end
        if touching then score = score + 10 end
        return {
            target = entity,
            proof = State.super_melee.proofs[entity],
            kind = kind,
            source = source,
            score = score,
            proof_route = tostring(State.super_melee.proofs[entity] and
                (State.super_melee.proofs[entity].discovery_route or State.super_melee.proofs[entity].route) or "unknown"),
            direct = direct_ped or direct_contact,
            direct_ped = direct_ped,
            direct_contact = direct_contact,
            damaged_by_entity = damaged_by_entity,
            damaged_by_melee = damaged_by_melee,
            touching = touching,
            damaged_by_entity_fresh = damaged_by_entity_fresh,
            damaged_by_melee_fresh = damaged_by_melee_fresh,
            first_seen_late = first_seen_late,
            last_hit_fresh = last_hit_fresh == true,
            fatal_melee = fatal_melee == true,
            distance = distance,
            alignment = alignment,
            contact_authorized = true,
        }
    end

    function Live.super_melee_evidence_snapshot(proof, ped, now)
        local entity = proof.handle
        local snapshot = {
            first_seen_ms = now,
            last_seen_ms = now,
            handle = proof.handle,
            network_id = proof.network_id,
            target_model = proof.target_model,
            identity = Live.super_melee_observation_key(proof),
            damage_entity = Live.super_melee_native("bool", H.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY, entity, ped, true),
            damage_melee = Live.super_melee_native("bool", H.HAS_ENTITY_BEEN_DAMAGED_BY_WEAPON, entity, 0, 1),
            health = Live.super_melee_native("int", H.GET_ENTITY_HEALTH, entity),
            touching = Live.super_melee_native("bool", H.IS_ENTITY_TOUCHING_ENTITY, entity, ped)
        }
        if not Live.super_melee_proof_current(proof) then return nil end
        return snapshot
    end

    function Live.prime_super_melee_evidence(ped, now)
        local state = State.super_melee
        if state.prestrike_ms and now >= state.prestrike_ms
            and now - state.prestrike_ms < Live.SUPER_MELEE_PRESTRIKE_INTERVAL_MS then
            return
        end
        state.prestrike_ms = now
        state.prestrike_last_hit = invoke_int(H.GET_LAST_ENTITY_HIT_BY_ENTITY, ped)
        local snapshots = {}
        -- Keep small scalar pre-impact baselines for targets not yet locked on.
        -- No native hit or proximity here authorizes any physics write.
        local direct = invoke_int(H.GET_MELEE_TARGET_FOR_PED, ped)
        local handles = Live.super_melee_ranked_handles(ped, direct, true)
        local remaining = { ped = 8, vehicle = 4, object = 2 }
        for _, item in ipairs(handles) do
            local proof = item.proof
            local kind = item.kind
            local admit = proof.handle == direct or (remaining[kind] or 0) > 0
            if admit and proof.handle ~= ped then
                if proof.handle ~= direct then remaining[kind] = remaining[kind] - 1 end
                local snapshot = Live.super_melee_evidence_snapshot(proof, ped, now)
                if snapshot then
                    snapshots[Live.super_melee_observation_key(proof)] = {
                        snapshot = snapshot,
                        handle = proof.handle,
                        network_id = proof.network_id,
                        target_model = proof.target_model,
                        owner_address = proof.owner_address,
                        owner_network = proof.owner_network,
                        owner_model = proof.owner_model,
                        generation = proof.generation
                    }
                end
            end
        end
        state.prestrike = snapshots
    end

    function Live.capture_super_melee_evidence_baseline(ped, direct)
        local swing = State.super_melee.swing
        swing.observations = {}
        local handles = Live.super_melee_ranked_handles(ped, direct, true)
        swing.prestrike_candidates = 0
        for _, item in ipairs(handles) do
            local entity = item.handle
            if Live.super_melee_proof_current(State.super_melee.proofs[entity]) and entity ~= ped then
                local proof = State.super_melee.proofs[entity]
                local prior = State.super_melee.prestrike and
                    State.super_melee.prestrike[Live.super_melee_observation_key(proof)]
                local age = prior and swing.started_ms - prior.snapshot.last_seen_ms
                if prior and age > 0 and age <= Live.SUPER_MELEE_PRESTRIKE_MAX_AGE_MS
                    and prior.handle == entity and prior.network_id == proof.network_id
                    and prior.target_model == proof.target_model
                    and prior.owner_model == proof.owner_model and prior.generation == proof.generation
                    and not (type(prior.owner_address) == "number" and type(proof.owner_address) == "number"
                        and prior.owner_address ~= proof.owner_address) then
                    -- The first observed melee frame may already contain impact
                    -- damage. Preserve the recent pre-strike reading in that case.
                    swing.observations[Live.super_melee_observation_key(proof)] = prior.snapshot
                    prior.snapshot.from_prestrike = true
                    swing.prestrike_candidates = swing.prestrike_candidates + 1
                else
                    swing.observations[Live.super_melee_observation_key(proof)] = Live.super_melee_evidence_snapshot(
                        proof, ped, swing.started_ms)
                end
            end
        end
        State.super_melee.prestrike = nil
        swing.baseline_candidates = #handles
    end

    function Live.super_melee_better_candidate(candidate, best)
        if not candidate then return best end
        if not best or candidate.score > best.score + 0.001 then return candidate end
        if math.abs(candidate.score - best.score) <= 0.001
            and candidate.distance < best.distance then
            return candidate
        end
        return best
    end

    function Live.super_melee_hit_entity(ped, now)
        local swing = State.super_melee.swing
        local direct = invoke_int(H.GET_MELEE_TARGET_FOR_PED, ped)
        if Live.super_melee_target_excluded(direct, ped) then direct = 0 end
        if tonumber(direct) and direct > 0 then
            swing.direct_target = direct
            swing.direct_target_ms = now
        elseif tonumber(swing.direct_target) and swing.direct_target > 0
            and now - (tonumber(swing.direct_target_ms) or tonumber(swing.started_ms) or now) <= 350 then
            -- GTA can release the melee lock immediately after impact. Retain only
            -- this swing's recently proved direct target for the bounded hit window.
            direct = swing.direct_target
        end
        local last_hit = invoke_int(H.GET_LAST_ENTITY_HIT_BY_ENTITY, ped)
        if Live.super_melee_target_excluded(last_hit, ped) then last_hit = 0 end
        local baseline = tonumber(State.super_melee.swing.last_hit_before) or 0
        local last_hit_fresh = tonumber(last_hit) and last_hit > 0 and last_hit ~= baseline
        if now - (tonumber(State.super_melee.last_scan_ms) or -100000) < Live.SUPER_MELEE_SCAN_INTERVAL_MS then
            return nil
        end
        State.super_melee.last_scan_ms = now
        local strike = State.super_melee.nonped_strike
        local supplemental = (last_hit_fresh or (strike and strike.consumed ~= true)) and last_hit or 0
        -- Evaluate the freshly captured exact hit before rendered enumeration
        -- and the synchronous shape probe. Preserve its proof across frames.
        if strike and strike.consumed ~= true and (strike.target == last_hit or strike.limb_contact or strike.ped_direct or strike.nonped_damage)
            and Live.super_melee_proof_current(strike.proof) then
            State.super_melee.proofs[strike.target] = strike.proof
            local exact = Live.super_melee_candidate(strike.target, ped, false, now, nil, nil, nil, last_hit_fresh)
            if exact then return exact end
        end
        local handles, frame = Live.super_melee_ranked_handles(ped, direct, false, supplemental)
        for identity, observation in pairs(State.super_melee.swing.observations) do
            if now - (observation.last_seen_ms or now) > 2000 then
                State.super_melee.swing.observations[identity] = nil
            end
        end
        local best = nil
        for _, item in ipairs(handles) do
            local is_direct = tonumber(item.handle) == tonumber(direct)
            best = Live.super_melee_better_candidate(
                Live.super_melee_candidate(item.handle, ped, is_direct, now, frame,
                    item.distance, item.alignment, last_hit_fresh and tonumber(item.handle) == tonumber(last_hit)), best)
        end
        for _, item in ipairs(handles) do
            local proof = item.proof
            if proof and proof.shape_borrowed == true and (not best or best.proof ~= proof) then
                Live.super_melee_release_shape_proof(proof, "shape candidate not selected")
                if State.super_melee.proofs[item.handle] == proof then State.super_melee.proofs[item.handle] = nil end
            end
        end
        return best
    end

    function Live.super_melee_owner_identity(pid)
        if type(pid) ~= "number" or pid < 0 or pid > 31 or not Live.Players then return nil end
        local ok, key = pcall(function()
            local p = Live.Players.GetById(pid)
            if not p then return nil end
            local address, cxn = p:GetAddress(), p.CxnId
            if type(address) ~= "number" or type(cxn) ~= "number" then return nil end
            return tostring(address) .. ":" .. tostring(cxn)
        end)
        return ok and key or nil
    end

    function Live.request_super_melee_control(item, ped, now)
        local entity = item.target
        if now >= (item.control_deadline_ms or 0) or not Live.super_melee_proof_current(item.proof)
            or not Live.super_melee_impact_area_current(item, ped) then
            return false
        end
        if not item.control_changed then
            local proof = item.proof
            local address = proof.instance_address or proof.strike_address or proof.shape_address
                or (type(proof.address) == "number" and proof.address)
            if not address and not proof.network_id then return false end
            local owner = Live.entity_network_owner(entity)
            local owner_key = Live.super_melee_owner_identity(owner)
            local acquiring_owner = local_player_id()
            local acquiring_key = Live.super_melee_owner_identity(acquiring_owner)
            if not owner_key or not acquiring_key then return false end
            if owner == acquiring_owner then return Live.super_melee_write_control_current(item) end
            -- Record before either native or forced acquisition: a request can
            -- synchronously succeed or mutate ownership before reporting failure.
            item.original_owner, item.owner_identity = owner, owner_key
            item.acquiring_owner, item.acquiring_identity = acquiring_owner, acquiring_key
            item.control_changed = true
        end
        -- Every acquisition attempt must still belong to both captured player
        -- connections. Unreadable identity retains debt without another request.
        local owner_key = Live.super_melee_owner_identity(item.original_owner)
        local acquiring_key = Live.super_melee_owner_identity(item.acquiring_owner)
        if not owner_key or owner_key ~= item.owner_identity
            or not acquiring_key or acquiring_key ~= item.acquiring_identity then
            return false
        end
        Live.super_melee_native("bool", H.NETWORK_REQUEST_CONTROL_OF_ENTITY, entity)
        if Live.super_melee_write_control_current(item) then return true end
        if item.kind == "vehicle" and not item.force_request_attempted then
            if Live.super_melee_owner_identity(item.original_owner) ~= item.owner_identity
                or Live.super_melee_owner_identity(item.acquiring_owner) ~= item.acquiring_identity then
                return false
            end
            if not Live.super_melee_proof_current(item.proof) then return false end
            item.force_request_attempted = true
            Live.request_entity_control(local_player_id(), entity)
        end
        return Live.super_melee_write_control_current(item)
    end

    function Live.restore_super_melee_owner(entity, item, now, immediate)
        if not item.control_changed then return true end
        if not item.proof or entity ~= item.proof.handle then return false end
        local identity = Live.super_melee_target_identity_current(item.proof)
        if identity == nil then return false end
        if identity == false then
            item.control_changed = false; return true
        end
        local key = Live.super_melee_owner_identity(item.original_owner)
        if not key then return false end
        if key ~= item.owner_identity then
            item.control_changed = false; return true
        end
        local acquiring_owner = item.acquiring_owner
        if acquiring_owner == nil then return false end
        local acquiring_key = Live.super_melee_owner_identity(acquiring_owner)
        if not acquiring_key then return false end
        if acquiring_key ~= item.acquiring_identity then
            item.control_changed = false; return true
        end
        local owner = Live.entity_network_owner(entity)
        if owner == nil then return false end
        if owner ~= acquiring_owner then
            -- A native request can grant on a later tick. Keep its obligation
            -- through the acquisition window while the original owner remains.
            if owner == item.original_owner and now < (item.control_deadline_ms or 0) then return false end
            item.control_changed = false; return true
        end
        -- GiveControl is a one-time transfer, not a persistent migration lock.
        -- Never override a later owner or send restoration to a reused player slot.
        if Live.super_melee_target_identity_current(item.proof) == true
            and Live.super_melee_owner_identity(item.original_owner) == item.owner_identity
            and Live.super_melee_owner_identity(acquiring_owner) == item.acquiring_identity
            and Live.entity_network_owner(entity) == acquiring_owner then
            local returned = Live.give_entity_control(item.original_owner, entity)
            if returned == true then
                item.control_changed = false; return true
            end
            return false
        end
        return false
    end

    function Live.carry_super_melee_control(previous, candidate, impact)
        if not previous or not candidate or not impact or previous.control_changed ~= true then return false end
        local old, new = previous.proof, candidate.proof
        if not old or not new or previous.target ~= candidate.target or old.handle ~= new.handle
            or old.target_model ~= new.target_model or old.network_id ~= new.network_id or old.generation ~= new.generation
            or Live.super_melee_observation_key(old) ~= Live.super_melee_observation_key(new)
            or not Live.super_melee_proof_current(old) or not Live.super_melee_proof_current(new)
            or Live.super_melee_owner_identity(previous.original_owner) ~= previous.owner_identity
            or Live.entity_network_owner(candidate.target) ~= local_player_id() then
            return false
        end
        impact.control_changed = true
        impact.original_owner, impact.owner_identity = previous.original_owner, previous.owner_identity
        impact.acquiring_owner, impact.acquiring_identity = previous.acquiring_owner, previous.acquiring_identity
        impact.force_request_attempted = previous.force_request_attempted
        return true
    end

    function Live.process_super_melee_owner_returns(now)
        local state = State.super_melee
        for entity, item in pairs(state.owner_restores) do
            local due = now < (item.submitted_ms or now) or now >= (item.owner_return_ms or 0)
            if due and now - (item.owner_return_attempt_ms or -100000) >= 100 then
                item.owner_return_attempt_ms = now
                local done = Live.restore_super_melee_owner(entity, item, now, true)
                if done then
                    state.owner_restores[entity] = nil
                    if state.proofs[entity] == item.proof then state.proofs[entity] = nil end
                    Live.super_melee_release_shape_proof(item.proof, "owner return finished")
                end
            end
        end
    end

    function Live.cleanup_super_melee(reason)
        local state = State.super_melee
        local pending_before, returns_before = state.pending, state.owner_restores
        for entity, item in pairs(pending_before or {}) do
            if item.control_changed then
                item.owner_return_ms = 0
                returns_before[entity] = item
            end
        end
        for entity, item in pairs(returns_before) do
            if Live.restore_super_melee_owner(entity, item, now_ms(), true) then returns_before[entity] = nil end
        end
        local borrowed = {}
        local function collect(proof)
            if proof and proof.shape_borrowed == true and proof.shape_released ~= true then
                borrowed[proof.handle] =
                    proof
            end
        end
        for _, proof in pairs(state.proofs or {}) do collect(proof) end
        for _, item in pairs(pending_before or {}) do collect(item.proof) end
        for _, item in pairs(returns_before or {}) do collect(item.proof) end
        if state.nonped_strike then collect(state.nonped_strike.proof) end
        for _, proof in pairs(state.shape_inflight or {}) do collect(proof) end
        -- Detach all local users first; one handle can have several proof objects.
        state.proofs, state.pending, state.nonped_strike, state.shape_inflight = {}, {}, nil, nil
        for _, proof in pairs(borrowed) do Live.super_melee_release_shape_proof(proof, "Super Melee cleanup") end
        Live.super_melee_free_shape_buffers()
        state.generation = (tonumber(state.generation) or 0) + 1
        state.rendered_cache, state.rendered_cache_ms = nil, nil
        state.prestrike, state.prestrike_ms = nil, nil
        state.nonped_strike, state.nonped_strike_sample, state.limb_samples = nil, nil, nil
        state.last_melee_conflicting_shot_ms = nil
        state.scan_cursors = {}
        state.pending = {}
        state.swing.active, state.swing.armed, state.swing.consumed = false, true, false
        state.swing.started_ms, state.swing.impact_until_ms, state.swing.direct_target = 0, 0, 0
        state.swing.action_was_performing = false
        state.swing.attack_fx, state.swing.attack_fy, state.swing.attack_mode, state.swing.action_token = nil, nil, nil,
            nil
        state.swing.observations, state.swing.baseline_candidates = {}, 0
        state.last_strength, state.last_target = 0, 0
        state.last_outcome = "cancelled:" .. tostring(reason or "cleanup")
        Live.restore_super_melee_modifier(reason or "cleanup")
        if reason ~= "slider disabled" or not Live.bst46_melee(local_ped()) then
            Live.restore_super_melee_damage(reason or "cleanup")
        end
        Live.super_melee_trace("CANCELLED", "cleanup", state.last_outcome)
    end

    function Live.quiesce_super_melee(reason)
        Live.restore_super_melee_damage(reason or "stop") -- fresh host lookups, no natives
        -- Stop/Dispose may run outside the native thread. Cancel force work but
        -- retain return obligations for a later safe gameplay-thread tick.
        local state = State.super_melee
        for entity, item in pairs(state.pending or {}) do
            if item.control_changed then
                item.owner_return_ms = 0; state.owner_restores[entity] = item
            end
        end
        Live.super_melee_free_shape_buffers() -- owned heap only, no entity natives
        state.generation = (tonumber(state.generation) or 0) + 1
        state.pending, state.proofs = {}, {}
        state.rendered_cache, state.rendered_cache_ms = nil, nil
        state.prestrike, state.prestrike_ms = nil, nil
        state.nonped_strike, state.nonped_strike_sample, state.limb_samples = nil, nil, nil
        state.last_melee_conflicting_shot_ms = nil
        state.swing.active, state.swing.consumed, state.swing.action_was_performing = false, false, false
        state.swing.observations = {}
        state.last_outcome = "cancelled:" .. tostring(reason or "stop")
    end

    local function super_melee_anchor_curve(strength, at_one, at_five, at_ten)
        strength = math.max(1, math.min(20, tonumber(strength) or 1))
        if strength <= 5 then
            return at_one + (at_five - at_one) * ((strength - 1) / 4.0)
        elseif strength <= 10 then
            return at_five + (at_ten - at_five) * ((strength - 5) / 5.0)
        end
        -- Preserve the proven 5->10 slope instead of inventing a discontinuous tier.
        return at_ten + (at_ten - at_five) * ((strength - 10) / 5.0)
    end

    function Live.super_melee_force_profile(kind, strength)
        strength = tonumber(strength) or 0
        if strength <= 0 or strength ~= strength then return 0.0, 0.0 end
        strength = math.min(20, strength)
        local low = math.min(strength, 10)
        local horizontal, lift, high_speed
        -- Directed speed targets are mass independent. One command per proven
        -- hit; no repeated force after collisions or a retained ownership failure.
        if kind == "ped" then
            horizontal = super_melee_anchor_curve(low, 8.0, 20.0, 40.0)
            lift = super_melee_anchor_curve(low, 3.0, 5.0, 8.0)
            high_speed = 120.0
        elseif kind == "vehicle" then
            horizontal = super_melee_anchor_curve(low, 22.0, 55.0, 90.0)
            lift = super_melee_anchor_curve(low, 5.0, 12.0, 20.0)
            high_speed = 160.0
        else
            horizontal = super_melee_anchor_curve(low, 10.0, 24.0, 45.0)
            lift = super_melee_anchor_curve(low, 2.0, 4.0, 6.0)
            high_speed = 125.0
        end
        local high = math.max(0, (strength - 10) / 10)
        return horizontal + (high_speed - horizontal) * high, lift + (kind == "vehicle" and 12.0 or 8.0) * high
    end

    function Live.capture_super_melee_impact(ped, candidate, now, strength, original_owner)
        if not candidate or Live.super_melee_target_excluded(candidate.target, ped) then
            return nil, "local player/current vehicle cannot be a Super Melee target"
        end
        local swing = State.super_melee.swing
        local fx, fy = tonumber(swing.attack_fx), tonumber(swing.attack_fy)
        if candidate.kind == "vehicle" and not tostring(swing.attack_mode or ""):find("bike-", 1, true) then
            fx, fy = vector_components(invoke_vec3(H.GET_ENTITY_FORWARD_VECTOR, ped)); fx, fy = tonumber(fx),
                tonumber(fy)
        end
        if not fx or not fy then
            local forward = invoke_vec3(H.GET_ENTITY_FORWARD_VECTOR, ped)
            fx, fy = vector_components(forward); fx, fy = tonumber(fx), tonumber(fy)
        end
        local magnitude = fx and fy and math.sqrt(fx * fx + fy * fy) or 0.0
        if magnitude < 0.001 or magnitude ~= magnitude or magnitude == math.huge then
            return nil, "attacker forward unavailable at impact"
        end
        fx, fy = fx / magnitude, fy / magnitude
        local attacker_position = invoke_vec3(H.GET_ENTITY_COORDS, ped, false)
        local target_position = Live.super_melee_native("vec3", H.GET_ENTITY_COORDS, candidate.target, false)
        local ax, ay, az = vector_components(attacker_position)
        local tx, ty, tz = vector_components(target_position)
        local velocity = Live.super_melee_native("vec3", H.GET_ENTITY_VELOCITY, candidate.target)
        local vx, vy, vz = vector_components(velocity)
        for _, value in pairs({ ax, ay, az, tx, ty, tz, vx, vy, vz }) do
            if type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then
                return nil, "finite impact position/velocity unavailable"
            end
        end
        if ax == nil or ay == nil or az == nil or tx == nil or ty == nil or tz == nil
            or vx == nil or vy == nil or vz == nil then
            return nil, "impact position/velocity unavailable"
        end
        -- Animation heading can swivel during a hook/kick. Use the struck
        -- entity's bearing from the attacker for peds/objects. Vehicle launches
        -- retain actual strike direction instead of aiming at the chassis centre.
        local dx, dy = tx - ax, ty - ay
        local separation = math.sqrt(dx * dx + dy * dy)
        local direction_source = candidate.kind == "vehicle" and "actual-strike-direction" or "strike-forward-fallback"
        if candidate.kind ~= "vehicle" and separation >= 0.25 then
            fx, fy = dx / separation, dy / separation
            direction_source = "away-from-attacker-at-impact"
        end
        return {
            impact_direction_source = direction_source,
            target = candidate.target,
            proof = candidate.proof,
            kind = candidate.kind,
            source = candidate.source,
            proof_route = candidate.proof_route or (candidate.proof and candidate.proof.route) or "unknown",
            direct = candidate.direct,
            direct_ped = candidate.direct_ped,
            direct_contact = candidate.direct_contact,
            damaged_by_entity = candidate.damaged_by_entity,
            damaged_by_melee = candidate.damaged_by_melee,
            touching = candidate.touching,
            damaged_by_entity_fresh = candidate.damaged_by_entity_fresh,
            damaged_by_melee_fresh = candidate.damaged_by_melee_fresh,
            first_seen_late = candidate.first_seen_late,
            fatal_melee = candidate.fatal_melee == true,
            last_hit_fresh = candidate.last_hit_fresh == true,
            distance = candidate.distance,
            alignment = candidate.alignment,
            score = candidate.score,
            contact_authorized = candidate.contact_authorized == true,
            swing_id = State.super_melee.swing.id,
            strength = strength,
            original_owner = original_owner,
            started_ms = now,
            impact_ms = now,
            impact_forward_x = fx,
            impact_forward_y = fy,
            impact_forward_z = 0.0,
            impact_attacker_x = tonumber(ax),
            impact_attacker_y = tonumber(ay),
            impact_attacker_z = tonumber(az),
            impact_target_x = tonumber(tx),
            impact_target_y = tonumber(ty),
            impact_target_z = tonumber(tz),
            impact_velocity_x = tonumber(vx) or 0.0,
            impact_velocity_y = tonumber(vy) or 0.0,
            impact_velocity_z = tonumber(vz) or 0.0,
            modifier_primary = false,
            modifier_multiplier = tonumber(State.super_melee.modifier.multiplier) or 1.0,
            modifier_applied = tonumber(State.super_melee.modifier.applied),
            last_request_ms = -100000,
            attempts = 0,
            control_changed = false,
            phase = "control",
            -- Allow the already-proved contact to finish control + ragdoll preparation.
            -- Fresh-hit detection retains its separate 180 ms edge window.
            evidence_expires_ms = now + Live.SUPER_MELEE_CONTROL_TIMEOUT_MS
                + Live.SUPER_MELEE_RAGDOLL_READY_MS + 80,
            control_deadline_ms = now + Live.SUPER_MELEE_CONTROL_TIMEOUT_MS,
        }
    end

    function Live.super_melee_fatal_dynamic(entity, item)
        local health = Live.super_melee_native("int", H.GET_ENTITY_HEALTH, entity)
        return item and item.fatal_melee == true and item.contact_authorized == true
            and type(health) == "number" and health <= 0
            and Live.super_melee_native("bool", 0x1218E6886D3D8327, entity) == false
    end

    function Live.apply_super_melee_ragdoll(entity, kind, item)
        if kind ~= "ped" then return false, "not-applicable", "not a ped" end
        -- The normal hit may already have created a ragdoll (including a
        -- dying victim). Do not reject or restart usable existing physics.
        if Live.super_melee_native("bool", H.IS_PED_RAGDOLL, entity) == true then
            return true, "verified", "existing IS_PED_RAGDOLL=true; no new task"
        end
        if Live.super_melee_fatal_dynamic(entity, item) then
            return true, "verified", "fresh attributed melee corpse has dynamic physics; no new task"
        end
        local can_ragdoll = Live.super_melee_native("bool", H.CAN_PED_RAGDOLL, entity)
        if not can_ragdoll then return false, "blocked", "CAN_PED_RAGDOLL=false" end
        local attempted = Live.super_melee_native("bool", H.SET_PED_TO_RAGDOLL, entity,
            Live.SUPER_MELEE_RAGDOLL_TIME_MS, 3000, 0, false, false, false)
        local verified = Live.super_melee_native("bool", H.IS_PED_RAGDOLL, entity)
        if verified then return true, "verified", "IS_PED_RAGDOLL=true type=0" end
        if attempted then
            Live.super_melee_native("void", 0x01F6594B923B9251, entity) -- SET_PED_RAGDOLL_FORCE_FALL
            return true, "unverified", "request accepted; force-fall submitted; IS_PED_RAGDOLL=false type=0"
        end
        if attempted == false then
            -- A rejected request is not success. The normal punch reaction may
            -- still publish ragdoll next frame; wait only the existing 150 ms
            -- readiness window, without repeating tasks or enabling ragdoll flags.
            return true, "waiting", "request rejected; waiting for natural ragdoll readiness"
        end
        return false, "blocked", "ragdoll native unavailable or target proof retired"
    end

    function Live.super_melee_motion_snapshot(entity)
        local velocity = Live.super_melee_native("vec3", H.GET_ENTITY_VELOCITY, entity)
        local position = Live.super_melee_native("vec3", H.GET_ENTITY_COORDS, entity, false)
        local rotation_velocity = Live.super_melee_native("vec3", 0x213B91045D09B983, entity) -- GET_ENTITY_ROTATION_VELOCITY
        local vx, vy, vz = vector_components(velocity)
        local x, y, z = vector_components(position)
        local rx, ry, rz = vector_components(rotation_velocity)
        if vx == nil or vy == nil or vz == nil or x == nil or y == nil or z == nil then return nil end
        for _, value in ipairs({ vx, vy, vz, x, y, z }) do
            if type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then return nil end
        end
        if rx ~= nil and ry ~= nil and rz ~= nil then
            for _, value in ipairs({ rx, ry, rz }) do
                if type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then
                    rx, ry, rz = nil, nil, nil; break
                end
            end
        end
        return { vx = vx, vy = vy, vz = vz, x = x, y = y, z = z, rx = rx, ry = ry, rz = rz }
    end

    function Live.super_melee_write_control_current(item)
        if not Live.super_melee_proof_current(item.proof) then return false end
        -- A prior request/grant, ragdoll call or motion read is not a lease on
        -- authority. Observe current control again immediately before a write.
        -- Do not request, migrate, or override ownership from this check.
        local networked = item.proof.native_identity == true and item.proof.networked == true
            or (item.proof.native_identity ~= true and item.proof.network_id ~= nil)
        return not networked or
            Live.super_melee_native("bool", H.NETWORK_HAS_CONTROL_OF_ENTITY, item.target) == true
    end

    function Live.apply_super_melee_impulse(entity, item)
        local kind = item.kind
        if kind ~= "ped" and kind ~= "vehicle" and kind ~= "object" then return false, "invalid kind" end
        if item.launch_submitted then return false, "launch already submitted" end
        local horizontal, lift = Live.super_melee_force_profile(kind, item.strength)
        if horizontal <= 0 then return false, "strength disabled" end
        local fx, fy = tonumber(item.impact_forward_x), tonumber(item.impact_forward_y)
        if not fx or not fy or fx ~= fx or fy ~= fy or math.abs(fx) == math.huge or math.abs(fy) == math.huge then
            return false, "impact direction unavailable"
        end
        local magnitude = math.sqrt(fx * fx + fy * fy)
        if magnitude < 0.001 then return false, "impact direction unavailable" end
        local x, y, z = fx / magnitude * horizontal, fy / magnitude * horizontal, lift
        if not Live.super_melee_write_control_current(item) then return false, "control unavailable before physics write" end
        if kind == "vehicle" then
            -- Off-centre force was mostly rotating the chassis in the live trace.
            -- Set the directed launch once, with the same fresh control check used
            -- for peds. Subsequent movement is ordinary GTA collision physics.
            -- Suppress inherited punch-induced spin once, at the actual impact.
            -- No subsequent angular/linear writes fight normal collision physics.
            item.angular_submitted = true
            Live.super_melee_native("void", 0x8339643499D1222E, entity, 0.0, 0.0, 0.0)
            if not Live.super_melee_write_control_current(item) then return false, "control changed before launch" end
            item.request_x, item.request_y, item.request_z = x, y, z
            item.launch_submitted = true
            local accepted = Live.super_melee_native("void", H.SET_ENTITY_VELOCITY, entity, x, y, z) == true
            return accepted,
                accepted and "vehicle directed launch submitted; motion observation pending" or "vehicle launch rejected"
        end
        -- Peds/objects retain their primary world-space launch after proved contact.
        -- Replace animation sideways velocity; never reapply after collision,
        -- add an offset/torque, raise an entity speed cap, or retry a failed launch.
        item.request_x, item.request_y, item.request_z = x, y, z
        item.launch_submitted = true
        local accepted = Live.super_melee_native("void", H.SET_ENTITY_VELOCITY, entity, x, y, z) == true
        return accepted,
            accepted and "directed launch submitted; physics observation pending" or "launch submission failed"
    end

    function Live.super_melee_observed_motion(entity, item, now)
        local current = Live.super_melee_motion_snapshot(entity)
        local baseline = item.motion_before
        if not current or not baseline then return false, "motion read unavailable", false end
        local fx, fy = item.impact_forward_x, item.impact_forward_y
        local delta_velocity = (current.vx - baseline.vx) * fx + (current.vy - baseline.vy) * fy
        local elapsed = math.max(0, now - item.submitted_ms) / 1000.0
        local residual = (current.x - baseline.x - baseline.vx * elapsed) * fx
            + (current.y - baseline.y - baseline.vy * elapsed) * fy
        -- Position must advance too: a write/readback of velocity on a frozen
        -- entity is not an observed launch. Subtract pre-existing travel.
        local observed = residual > 0.02 and (delta_velocity > 0.20 or (residual > 0.08 and delta_velocity >= -0.10))
        local angular_delta = 0.0
        if item.kind == "vehicle" and current.rx ~= nil and baseline.rx ~= nil then
            local drx = current.rx - baseline.rx
            local dry = current.ry - baseline.ry
            local drz = current.rz - baseline.rz
            angular_delta = math.sqrt(drx * drx + dry * dry + drz * drz)
            -- Rotation is secondary evidence; a successful vehicle launch requires translation.
            observed = residual > 0.04 and (delta_velocity > 0.35 or (residual > 0.12 and delta_velocity >= -0.10))
        end
        if item.kind == "ped" then
            -- Require a strength-scaled ped response beyond the ordinary punch/ragdoll reaction.
            local minimum_delta = super_melee_anchor_curve(item.strength, 2.0, 6.0, 12.0)
            local minimum_distance = super_melee_anchor_curve(item.strength, 0.12, 0.45, 0.90)
            observed = residual > 0.04 and (delta_velocity >= minimum_delta
                or (residual >= minimum_distance and delta_velocity >= -0.10))
        end
        return observed, ("forwardMotion=%.3f deltaVelocity=%.3f angularDelta=%.3f elapsedMs=%d"):format(
            residual, delta_velocity, angular_delta, now - item.submitted_ms), true
    end

    local function yes_no(value) return value == true and "yes" or "no" end

    function Live.super_melee_evidence_detail(item, now)
        local impact_age = math.max(0, (tonumber(now) or tonumber(item.impact_ms) or 0)
            - (tonumber(item.impact_ms) or 0))
        return ("swingId=%s target=%s targetKind=%s hitSource=%s proofRoute=%s direct=%s directPed=%s directContact=%s damagedByEntity=%s damagedByEntityFresh=%s damagedByMelee=%s damagedByMeleeFresh=%s touching=%s lateDiscovery=%s lastHitFresh=%s distance=%.2f alignment=%.3f impactAgeMs=%d impactForward=%.3f,%.3f,0.000 originalOwner=%s controlAttempts=%s modifierPrimary=%s modifierMultiplier=%.3f")
            :format(tostring(item.swing_id), tostring(item.target), tostring(item.kind),
                tostring(item.source), tostring(item.proof_route or (item.proof and item.proof.route) or "unknown"),
                yes_no(item.direct), yes_no(item.direct_ped),
                yes_no(item.direct_contact), yes_no(item.damaged_by_entity),
                yes_no(item.damaged_by_entity_fresh), yes_no(item.damaged_by_melee),
                yes_no(item.damaged_by_melee_fresh), yes_no(item.touching),
                yes_no(item.first_seen_late), yes_no(item.last_hit_fresh),
                tonumber(item.distance) or -1.0, tonumber(item.alignment) or -2.0,
                impact_age, tonumber(item.impact_forward_x) or 0.0,
                tonumber(item.impact_forward_y) or 0.0,
                tostring(item.original_owner), tostring(item.attempts or 0),
                yes_no(item.modifier_primary), tonumber(item.modifier_multiplier) or 1.0)
    end

    function Live.super_melee_impact_area_current(item, ped)
        local motion = Live.super_melee_motion_snapshot(item.target)
        local x, y, z = vector_components(invoke_vec3(H.GET_ENTITY_COORDS, ped, false))
        if not motion or x == nil or y == nil or z == nil then return false end
        for _, value in ipairs({ x, y, z }) do
            if type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then return false end
        end
        local ax, ay, az = x - item.impact_attacker_x, y - item.impact_attacker_y, z - item.impact_attacker_z
        local tx, ty, tz = motion.x - item.impact_target_x, motion.y - item.impact_target_y,
            motion.z - item.impact_target_z
        local limit = item.kind == "vehicle" and 12.0 or 6.0
        -- Keep the impact direction, not later aim. Do not replay a retained
        -- network hit after either subject teleports/leaves the local hit area.
        return ax * ax + ay * ay + az * az <= 36.0 and tx * tx + ty * ty + tz * tz <= limit * limit
    end

    function Live.process_super_melee_pending(now, ped, strength)
        local state = State.super_melee
        local function finish(entity, item, status, outcome, detail)
            if state.pending[entity] ~= item then return end
            if item.control_changed and item.launch_submitted and item.submitted_ms then
                item.owner_return_ms = item.submitted_ms + Live.SUPER_MELEE_OWNER_RETURN_DELAY_MS
                item.owner_return_deadline = item.owner_return_ms + Live.SUPER_MELEE_OWNER_RETURN_TIMEOUT_MS
                state.owner_restores[entity] = item
            elseif item.control_changed then
                if not Live.restore_super_melee_owner(entity, item, now, true) then
                    item.owner_return_ms = 0; state.owner_restores[entity] = item
                end
            end
            state.pending[entity] = nil
            state.last_target, state.last_strength = entity, item.strength or strength
            state.last_outcome = outcome
            detail = "hitSource=" .. tostring(item.source or "unknown") .. " " .. tostring(detail or "")
            local summary = ("swing=" .. tostring(item.swing_id) .. " result=%s kind=%s phase=%s target=%s controlRequests=%s strength=%s requestedSpeed=%.1f %s")
                :format(
                    tostring(outcome), tostring(item.kind), tostring(item.phase), tostring(entity),
                    tostring(item.attempts or 0), tostring(item.strength),
                    Live.super_melee_force_profile(item.kind, item.strength), tostring(detail or ""))
            Live.super_melee_trace(status, "impulse", summary .. " " .. Live.super_melee_evidence_detail(item, now))
            pcall(log_info, "SuperMelee status=" .. tostring(status) .. " " .. summary:sub(1, 480))
            if item.proof and item.proof.shape_borrowed == true then
                Live.super_melee_release_shape_proof(item.proof, "pending terminal:" .. tostring(status))
                if not state.owner_restores[entity] and state.proofs[entity] == item.proof then state.proofs[entity] = nil end
            end
        end
        for entity, item in pairs(state.pending) do
            local expired = now >
                (item.evidence_expires_ms or (item.impact_ms + Live.SUPER_MELEE_HIT_EVIDENCE_LIFETIME_MS))
            if Live.super_melee_target_excluded(entity, ped) then
                finish(entity, item, "CANCELLED", "local current vehicle excluded",
                    "self-vehicle cannot receive Super Melee force")
            elseif not Live.super_melee_proof_current(item.proof) then
                finish(entity, item, "CANCELLED", "target unavailable or identity changed",
                    item.proof and item.proof.reason)
            elseif now < (item.submitted_ms or item.prepared_ms or item.impact_ms) then
                finish(entity, item, "CANCELLED", "clock moved backwards", "retained work discarded")
            elseif (item.phase == "control" or item.phase == "prepare") and expired then
                finish(entity, item, "CANCELLED", "hit evidence expired",
                    "authoritative melee contact is too old; no late force")
            elseif item.phase == "prepare" and not Live.super_melee_impact_area_current(item, ped) then
                finish(entity, item, "CANCELLED", "impact area changed", "subjects moved after the real hit")
            elseif item.phase == "observe" and now - item.submitted_ms >= Live.SUPER_MELEE_OBSERVATION_LIFETIME_MS then
                finish(entity, item, "CANCELLED", "physics observation expired", "no delayed fallback")
            elseif item.phase == "observe" then
                if now - item.submitted_ms >= Live.SUPER_MELEE_PHYSICS_DELAY_MS then
                    local observed, detail = Live.super_melee_observed_motion(entity, item, now)
                    if observed then
                        finish(entity, item, "SUCCESS_VERIFIED", "observed forward motion:" .. item.kind, detail)
                    elseif now - item.submitted_ms >= Live.SUPER_MELEE_MOTION_TIMEOUT_MS then
                        finish(entity, item, "FAILED", "contact impulse produced no verified forward motion",
                            tostring(detail) .. "; one-shot launch is never reapplied after a collision")
                    end
                end
            else
                local has_control = Live.super_melee_write_control_current(item)
                if item.phase == "control" then
                    if now >= (item.control_deadline_ms or (item.impact_ms + Live.SUPER_MELEE_CONTROL_TIMEOUT_MS)) then
                        finish(entity, item, "CANCELLED", "control timeout", "real hit expired; no delayed force")
                    else
                        if not has_control and now - (item.last_request_ms or -100000) >= Live.SUPER_MELEE_CONTROL_INTERVAL_MS then
                            item.last_request_ms = now; item.attempts = (item.attempts or 0) + 1
                            has_control = Live.request_super_melee_control(item, ped, now) == true
                        end
                        if has_control and not Live.super_melee_impact_area_current(item, ped) then
                            finish(entity, item, "CANCELLED", "impact area changed", "real hit not replayed elsewhere")
                        elseif has_control then
                            item.phase, item.prepared_ms = "prepare", now
                            if item.kind == "ped" then
                                local attempted, result, detail = Live.apply_super_melee_ragdoll(entity, item.kind, item)
                                item.ragdoll_detail = detail
                                if not attempted or result == "blocked" then
                                    finish(entity, item, "FAILED",
                                        "ragdoll unavailable", detail)
                                end
                            end
                        end
                    end
                end
                if state.pending[entity] == item and item.phase == "prepare" then
                    has_control = Live.super_melee_write_control_current(item)
                    local ready = item.kind ~= "ped" or Live.super_melee_native("bool", H.IS_PED_RAGDOLL, entity) == true
                        or Live.super_melee_fatal_dynamic(entity, item)
                    if not has_control then
                        finish(entity, item, "CANCELLED", "control lost before submission", "no ownership stealing")
                    elseif expired then
                        finish(entity, item, "CANCELLED", "hit evidence expired during preparation", "no late force")
                    elseif not ready and now - item.prepared_ms >= Live.SUPER_MELEE_RAGDOLL_READY_MS then
                        finish(entity, item, "FAILED", "ragdoll readiness timeout", item.ragdoll_detail)
                    elseif not ready then
                        item.dynamic_ready_ms = nil
                    elseif ready then
                        local static = Live.super_melee_native("bool", 0x1218E6886D3D8327, entity)
                        if static == true and item.kind == "ped" and now - item.prepared_ms < Live.SUPER_MELEE_RAGDOLL_READY_MS then
                            item.dynamic_ready_ms = nil
                            -- wait within the same short contact lease only
                        elseif static == true and item.kind ~= "ped"
                            and now - item.prepared_ms < Live.SUPER_MELEE_RAGDOLL_READY_MS then
                            -- Stationary cars may be asleep after a legitimate hit.
                            -- Wake once with fresh identity/control, then observe a
                            -- later dynamic frame. Do not unfreeze a fixed entity.
                            local ok, ptr = pcall(gta.HandleToPointer, entity)
                            local readable, fixed, network_fixed = pcall(function()
                                return ptr.IsFixed, ptr.IsFixedByNetwork
                            end)
                            local can_wake = ok and readable and fixed == false and network_fixed == false
                            if not item.wake_attempted and can_wake and Live.super_melee_write_control_current(item) then
                                item.wake_attempted = true
                                item.wake_ms = now
                                Live.super_melee_native("void", 0x710311ADF0E20730, entity)
                                Live.super_melee_trace("SUCCESS_UNVERIFIED", "physics wake",
                                    ("swing=%s target=%s wakeRequested=true"):format(tostring(item.swing_id),
                                        tostring(entity)))
                            end
                        elseif static ~= false then
                            finish(entity, item, "FAILED", "static or unavailable physics target",
                                "IS_ENTITY_STATIC=" .. tostring(static))
                        elseif item.kind == "ped" and (not item.dynamic_ready_ms or now - item.dynamic_ready_ms < 32) then
                            item.dynamic_ready_ms = item.dynamic_ready_ms or now
                        else
                            local baseline = Live.super_melee_motion_snapshot(entity)
                            if not baseline then
                                finish(entity, item, "FAILED", "motion snapshot unavailable", "impulse not submitted")
                            else
                                local accepted, detail = Live.apply_super_melee_impulse(entity, item)
                                if accepted and state.pending[entity] == item then
                                    item.phase, item.submitted_ms, item.motion_before = "observe", now, baseline
                                    state.last_target, state.last_strength = entity, item.strength or strength
                                    state.last_outcome = "contact force submitted; motion unverified:" .. item.kind
                                    Live.super_melee_trace("SUCCESS_UNVERIFIED", "impulse",
                                        Live.super_melee_evidence_detail(item, now)
                                        .. (" requestedForce=%.2f,%.2f,%.2f %s"):format(item.request_x, item.request_y,
                                            item.request_z, detail))
                                else
                                    finish(entity, item, "FAILED", "physical impulse rejected", detail)
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    function Live.begin_super_melee_swing(now, ped, attack)
        local state, swing = State.super_melee, State.super_melee.swing
        swing.id = (tonumber(swing.id) or 0) + 1
        swing.active, swing.armed, swing.consumed = true, false, false
        swing.started_ms, swing.impact_until_ms = now, now + Live.SUPER_MELEE_IMPACT_WINDOW_MS
        swing.last_impact_ms = nil
        swing.attack_fx, swing.attack_fy = nil, nil
        swing.attack_mode = attack and attack.mode or "on-foot"
        if attack then
            swing.attack_fx, swing.attack_fy = attack.fx, attack.fy
        else
            local fx, fy = vector_components(invoke_vec3(H.GET_ENTITY_FORWARD_VECTOR, ped))
            local length = type(fx) == "number" and type(fy) == "number" and math.sqrt(fx * fx + fy * fy) or 0
            if length > 0.001 then swing.attack_fx, swing.attack_fy = fx / length, fy / length end
        end
        swing.direct_target = invoke_int(H.GET_MELEE_TARGET_FOR_PED, ped)
        if Live.super_melee_target_excluded(swing.direct_target, ped) then swing.direct_target = 0 end
        swing.direct_target_ms = tonumber(swing.direct_target) and swing.direct_target > 0 and now or nil
        local prior_age = state.prestrike_ms and now - state.prestrike_ms
        swing.last_hit_before = prior_age and prior_age > 0 and prior_age <= Live.SUPER_MELEE_PRESTRIKE_MAX_AGE_MS
            and state.prestrike_last_hit or invoke_int(H.GET_LAST_ENTITY_HIT_BY_ENTITY, ped)
        swing.candidate_gates, swing.shape_outcome, swing.last_candidate_gate = {}, nil, nil
        if Live.super_melee_target_excluded(swing.last_hit_before, ped) then swing.last_hit_before = 0 end
        swing.last_resolved_target = 0
        state.last_scan_ms = now - Live.SUPER_MELEE_SCAN_INTERVAL_MS
        Live.capture_super_melee_evidence_baseline(ped, swing.direct_target)
        Live.super_melee_trace("SUCCESS_UNVERIFIED", "swing",
            ("swing=%d state=started impactWindowMs=%d directTarget=%s baselineCandidates=%d prestrikeCandidates=%d")
            :format(
                swing.id, Live.SUPER_MELEE_IMPACT_WINDOW_MS, tostring(swing.direct_target),
                tonumber(swing.baseline_candidates) or 0, tonumber(swing.prestrike_candidates) or 0))
    end

    function Live.super_melee_swing_ready(now, ped)
        local swing = State.super_melee.swing
        local vehicle_attack = Live.super_melee_vehicle_attack(ped)
        local performing = invoke_bool(H.IS_PED_PERFORMING_MELEE_ACTION, ped)
            or invoke_bool(0xD1871251F3B5ACD7, ped) or vehicle_attack ~= nil -- IS_PED_RUNNING_MELEE_TASK
        local action_token = vehicle_attack and vehicle_attack.mode or (performing and "on-foot" or "idle")
        local rising_edge = performing and (swing.action_was_performing ~= true or swing.action_token ~= action_token)
        if performing then
            swing.action_ended_ms = nil
        elseif swing.action_was_performing == true then
            swing.action_ended_ms = now
        end
        swing.action_was_performing = performing
        swing.action_token = action_token
        if rising_edge then Live.begin_super_melee_swing(now, ped, vehicle_attack) end
        if not performing then
            swing.armed = true
            Live.prime_super_melee_evidence(ped, now)
            if not swing.active then Live.super_melee_gate("waiting for confirmed melee action") end
        end
        -- Melee combos can hold the native action flag continuously true for
        -- longer than 850 ms. Continue observing that action, without resetting
        -- its damage/contact baseline or manufacturing a new strike.
        if performing and swing.active and now > (tonumber(swing.impact_until_ms) or 0) then
            swing.impact_until_ms = now + Live.SUPER_MELEE_IMPACT_WINDOW_MS
        end
        if swing.active and now > (tonumber(swing.impact_until_ms) or 0) then
            if not swing.consumed then
                Live.super_melee_trace("NO_OP", "swing",
                    ("swing=%s state=expired result=no-qualified-hit gate=%s"):format(
                        tostring(swing.id),
                        tostring(swing.last_candidate_gate or State.super_melee.last_gate or
                            "no candidate in bounded scan")))
                pcall(log_info, ("SuperMelee status=NO_OP result=no-qualified-hit swing=%s gate=%s"):format(
                    tostring(swing.id),
                    tostring(swing.last_candidate_gate or State.super_melee.last_gate or "no candidate in bounded scan")))
            end
            swing.active = false
        end
        -- A combo may keep the native melee-action flag continuously true. Scan
        -- for NEW damage/contact edges after a bounded separation; sticky flags
        -- and proximity alone cannot authorize another impact.
        return swing.active == true and (swing.consumed ~= true or (performing
            and now - (swing.last_impact_ms or now) >= Live.SUPER_MELEE_REPEAT_IMPACT_MS))
    end

    function Live.apply_super_melee(now, ped)
        local state = State.super_melee
        Live.process_super_melee_owner_returns(now)
        local strength = math.max(0, math.min(20, math.floor(slider_int("super_melee", 0))))
        Live.update_super_melee_modifier(ped, strength)
        Live.update_super_melee_damage(ped, strength)
        if strength <= 0 or not Live.super_melee_owner_current(ped) then
            state.prestrike, state.prestrike_ms = nil, nil
            state.nonped_strike_sample, state.limb_samples = nil, nil
            if next(state.pending) ~= nil or next(state.owner_restores) ~= nil
                or state.swing.active == true or state.shape_buffers ~= nil or state.nonped_strike ~= nil then
                Live.cleanup_super_melee(strength <= 0 and "slider disabled" or "local ped unavailable")
            end
            return
        end
        -- No borrowed shape result may disappear just because this frame builds
        -- a new discovery table. Pending hits retain their proof; every other
        -- borrowed GUID is released before the table is rebuilt.
        for entity, proof in pairs(state.proofs or {}) do
            local pending = state.pending[entity]
            if proof and proof.shape_borrowed == true and (not pending or pending.proof ~= proof)
                and (not state.nonped_strike or state.nonped_strike.proof ~= proof
                    or state.nonped_strike.consumed or now - state.nonped_strike.ms > 80) then
                Live.super_melee_release_shape_proof(proof, "frame proof table rebuild")
            end
        end
        state.proofs = {}
        for entity, item in pairs(state.pending) do state.proofs[entity] = item.proof end
        for entity, item in pairs(state.owner_restores) do state.proofs[entity] = item.proof end
        local retained_strike = state.nonped_strike
        if retained_strike and not retained_strike.consumed and now >= retained_strike.ms
            and now - retained_strike.ms <= 80 and retained_strike.proof.retired ~= true
            and not state.proofs[retained_strike.target] then
            state.proofs[retained_strike.target] = retained_strike.proof
        end
        Live.process_super_melee_pending(now, ped, strength)
        local ready = Live.super_melee_swing_ready(now, ped)
        Live.sample_super_melee_nonped_strike(ped, now)
        if not ready then return end
        local candidate = Live.super_melee_hit_entity(ped, now)
        if not candidate then return end
        if not Live.super_melee_proof_current(candidate.proof) then
            Live.super_melee_release_shape_proof(candidate.proof, "selected proof invalid before impact")
            return
        end
        local target, swing = candidate.target, state.swing
        if Live.super_melee_target_excluded(target, ped) then
            state.last_outcome = "local current vehicle excluded"
            Live.super_melee_trace("NO_OP", "hit evidence", "self-vehicle cannot receive Super Melee force")
            Live.super_melee_release_shape_proof(candidate.proof, "selected target excluded")
            return
        end
        if state.pending[target] then
            swing.consumed = true
            state.last_outcome = "target already awaiting control"
            Live.super_melee_trace("NO_OP", "hit evidence",
                ("swing=%s target=%s result=already-pending"):format(tostring(swing.id), tostring(target)))
            Live.super_melee_release_shape_proof(candidate.proof, "duplicate pending target")
            return
        end
        local prior_restore = state.owner_restores[target]
        local original_owner = local_player_id() -- captured before the first control request
        -- Keep previous ownership debt until the new impact snapshot exists.
        swing.consumed, swing.last_resolved_target, swing.last_impact_ms = true, target, now
        swing.impact_until_ms = now + Live.SUPER_MELEE_IMPACT_WINDOW_MS
        local impact, impact_error = Live.capture_super_melee_impact(
            ped, candidate, now, strength, original_owner)
        if not impact then
            swing.consumed = true
            state.last_outcome = "impact snapshot failed"
            Live.super_melee_trace("CANCELLED", "hit evidence",
                ("swingId=%s target=%s result=%s"):format(
                    tostring(swing.id), tostring(target), tostring(impact_error)))
            Live.super_melee_release_shape_proof(candidate.proof, "impact snapshot failed")
            return
        end
        impact.control_changed = false
        if prior_restore and not Live.carry_super_melee_control(prior_restore, candidate, impact) then
            Live.super_melee_release_shape_proof(candidate.proof, "previous owner return unresolved")
            return
        end
        state.pending[target] = impact
        if prior_restore then
            state.owner_restores[target] = nil
            if prior_restore.proof ~= candidate.proof then
                Live.super_melee_release_shape_proof(prior_restore.proof, "ownership debt transferred to fresh impact")
            end
        end
        local consumed = swing.observations[Live.super_melee_observation_key(candidate.proof)]
        if consumed then consumed.attacker_edge_ms, consumed.melee_edge_ms, consumed.fatal_melee_ms = nil, nil, nil end
        if candidate.last_hit_fresh then swing.last_hit_before = target end
        if state.nonped_strike then state.nonped_strike.consumed = true end
        Live.super_melee_trace("SUCCESS_UNVERIFIED", "hit evidence",
            Live.super_melee_evidence_detail(state.pending[target], now)
            .. (" score=%.2f consumed=yes"):format(tonumber(candidate.score) or 0.0))
        Live.process_super_melee_pending(now, ped, strength)
    end

    Live.friendly_host = {}
    function Live.friendly_host.Notice(pid, message)
        toast(tostring(message), 4500, 'warning')
    end

    function Live.friendly_connection(pin)
        if pin.context ~= module_context or pin.generation ~= Live.action_generation or pin.local_id ~= local_player_id() then return false end
        if not player_available(pin.pid) or not player_available(pin.local_id) then return false end
        local identity, local_identity = Live.remote_identity(pin.pid), Live.remote_identity(pin.local_id)
        if not identity or not local_identity then return nil end
        if pin.context ~= module_context or pin.generation ~= Live.action_generation or pin.local_id ~= local_player_id() then return false end
        return identity.rid == pin.identity.rid and identity.cxn == pin.identity.cxn
            and local_identity.rid == pin.local_identity.rid and local_identity.cxn == pin.local_identity.cxn
    end

    function Live.friendly_local_scope(pin)
        if pin.context ~= module_context or pin.generation ~= Live.action_generation or pin.local_id ~= local_player_id() then return false end
        local identity = Live.remote_identity(pin.local_id)
        if not identity then return nil end
        if pin.context ~= module_context or pin.generation ~= Live.action_generation or pin.local_id ~= local_player_id() then return false end
        return identity.rid == pin.local_identity.rid and identity.cxn == pin.local_identity.cxn
    end

    function Live.friendly_host.ConnectionSame(pin)
        return Live.friendly_connection(pin)
    end
    function Live.friendly_host.Pin(pid)
        pid = Live.remote_player_index(pid)
        local own = local_player_id()
        if not started or pid == nil then return nil end
        local identity, local_identity = Live.remote_identity(pid), Live.remote_identity(own)
        local snapshot = player_snapshot(pid)
        if not identity or not local_identity or not snapshot or not Ignore.number(snapshot.ped) then return nil end
        local proof = Live.friendly_proof(snapshot.ped)
        if not proof then return nil end
        local pin = {
            pid = pid,
            local_id = own,
            identity = identity,
            local_identity = local_identity,
            ped = snapshot.ped,
            entity = proof,
            context = module_context,
            generation = Live.action_generation
        }
        if Live.friendly_host.Current(pin) ~= true then return nil end
        local key = table.concat({ identity.rid, identity.cxn, local_identity.rid, local_identity.cxn,
            pin.generation, proof.address, proof.network_id or -1 }, ':')
        return pin, key
    end

    function Live.friendly_host.Current(pin)
        local connection = Live.friendly_connection(pin)
        if connection ~= true then return connection end
        local snapshot = player_snapshot(pin.pid)
        if not snapshot then return nil end
        if Ignore.number(snapshot.ped) and snapshot.ped ~= pin.ped then return false end
        if snapshot.ped ~= pin.ped then return nil end
        local dead = Live.remote_bool(0x5F9532F3B5CC2551, pin.ped, false)
        if dead == true then return false end
        if dead ~= false then return nil end
        local state = Live.remote_entity_state(pin.entity)
        if Live.friendly_connection(pin) ~= true then return nil end
        if state == 'retired' then return false end
        if state == 'current' then return true end
    end

    function Live.friendly_host.Reset(key, pid)
        local hash = PF_ID[key]
        if type(hash) ~= 'number' then return end
        local ok, f = pcall(feature_mgr.GetFeature, hash, pid)
        if ok and f then pcall(function() if f:IsToggled() then f:Toggle(false) end end) end
    end

    function Live.friendly_float(hash, ...)
        local ok, value, raw, err = pcall(invoke_float_detail, hash, ...)
        if ok and err == nil and type(raw) == 'number' and type(value) == 'number' and value == value and math.abs(value) < math.huge then
            return
                value
        end
    end

    function Live.friendly_vec(hash, ...)
        local ok, v = pcall(invoke_vec3, hash, ...)
        if not ok then return nil end
        local got, x, y, z = pcall(vector_components, v)
        if got and type(x) == 'number' and type(y) == 'number' and type(z) == 'number' and x == x and y == y and z == z and math.abs(x) < 100000 and math.abs(y) < 100000 and math.abs(z) < 100000 then
            return {
                x =
                    x,
                y = y,
                z = z
            }
        end
    end

    function Live.friendly_write(hash, ...)
        local ok, accepted, _, err = pcall(invoke_void_detail, hash, ...)
        return ok and accepted == true and err == nil
    end

    function Live.friendly_proof(handle)
        if not handle or handle <= 0 then return nil end
        local context = module_context
        local pointer = Ignore.read(function() return gta.HandleToPointer(handle) end)
        local proof = pointer and Ignore.proof(pointer, function() return module_context == context end, handle)
        if proof then proof.remote_context = context end
        return proof
    end

    function Live.friendly_host.Validate(settings)
        local model = utils.Joaat(settings.model); local weapon = utils.Joaat(settings.weapon)
        if Live.remote_bool(0xC0296A2EDF545E92, model) ~= true or Live.remote_bool(0x75816577FEA6DAD5, model) ~= true then
            return
                false, 'Bodyguard model is not a valid ped.'
        end
        if Live.remote_bool(0x937C71165CF334B3, weapon) ~= true then return false, 'Bodyguard weapon is unavailable.' end
        return true
    end

    function Live.friendly_radar_provider(pin, lookup_hash)
        local foreign = module_context and module_context.CScript.ForeignFeatures
        if not foreign then return nil end
        local function inspect(f)
            local ok, entry = pcall(function()
                if not f or not foreign.Describe(f) or not foreign.Supports(f, 'toggle') then return nil end
                local hash = f:GetHash()
                if Live.owned_player_hashes and Live.owned_player_hashes[hash] then return nil end
                for _, owned in pairs(PF_ID) do if owned == hash then return nil end end
                if not f:IsPlayerFeature() or f:GetPlayerIndex() ~= pin.pid then return nil end
                local name = f:GetName(false)
                if type(name) ~= 'string' or name:lower():gsub('~[^~]*~', ''):gsub('[^%w]', '') ~= 'offtheradar' then return nil end
                if type(f.TriggerCallback) ~= 'function' then return nil end
                return { feature = f, serial = f:GetId(), hash = hash }
            end)
            return ok and entry or nil
        end
        if lookup_hash then
            local ok, f = pcall(feature_mgr.GetFeature, lookup_hash, pin.pid)
            local entry = ok and inspect(f)
            if entry then return entry end
            ok, f = pcall(feature_mgr.GetFeature, lookup_hash)
            return ok and inspect(f) or nil
        end
        -- Names can collide with our own selected-player control. Enumerate once
        -- at admission and require a unique, foreign, correctly indexed toggle.
        local candidates, seen = {}, {}
        local function offer(f)
            local entry = inspect(f)
            if entry and not seen[entry.serial] then
                seen[entry.serial] = true; candidates[#candidates + 1] = entry
            end
        end
        if type(feature_mgr.GetFeatureByName) == 'function' then
            local ok, f = pcall(feature_mgr.GetFeatureByName, 'Off The Radar', pin.pid)
            if ok then offer(f) end
        end
        if type(feature_mgr.GetAllFeatures) == 'function' then
            local ok, all = pcall(feature_mgr.GetAllFeatures)
            if ok and all then
                local scanned = pcall(function()
                    local count = 0
                    for hash, f in pairs(all) do
                        count = count + 1; if count > 32768 then error('feature registry limit') end
                        offer(f)
                        if type(hash) == 'number' then
                            local got, indexed = pcall(feature_mgr.GetFeature, hash, pin.pid)
                            if got then offer(indexed) end
                        end
                    end
                end)
                if not scanned then return nil end
            end
        end
        if #candidates == 1 then return candidates[1] end
    end

    function Live.friendly_host.RadarBorrow(pin)
        local lease = Live.friendly_radar_provider(pin)
        if not lease or Live.friendly_host.Current(pin) ~= true then
            return nil,
                'Remote Off The Radar provider unavailable.'
        end
        local ok, before = pcall(function() return lease.feature:IsToggled() end)
        if not ok or type(before) ~= 'boolean' then return nil, 'Remote Off The Radar state unavailable.' end
        lease.owned = not before; lease.before = before
        if before then
            lease.applied = true; return lease
        end
        -- Record the lease before returning even if a setter mutates then throws.
        local accepted, result = pcall(function()
            lease.feature:Toggle(true); return lease.feature:TriggerCallback()
        end)
        local read, observed = pcall(function() return lease.feature:IsToggled() end)
        lease.applied = accepted and result ~= false and read and observed == true
        return lease
    end

    function Live.friendly_host.RadarRelease(pin, lease)
        if not lease.owned then return true end
        if Live.friendly_connection(pin) == false then return true end
        if Live.friendly_connection(pin) ~= true then return false end
        local entry = Live.friendly_radar_provider(pin, lease.hash)
        if not entry then return false end
        if entry.serial ~= lease.serial then return true end
        local ok, done = pcall(function()
            local f = entry.feature
            if f:IsToggled() == false then return true end
            if Live.friendly_connection(pin) ~= true then return false end
            f:Toggle(false); f:TriggerCallback()
            return f:IsToggled() == false
        end)
        return ok and done == true
    end

    function Live.friendly_float32(value)
        -- Same guarded representation conversion as Economy Profile.float32.
        if type(value) ~= 'number' or value ~= value or math.abs(value) == math.huge
            or type(string.pack) ~= 'function' or type(string.unpack) ~= 'function' then
            return nil
        end
        local ok, rounded = pcall(function() return string.unpack('f', string.pack('f', value)) end)
        if ok and type(rounded) == 'number' and rounded == rounded and math.abs(rounded) < math.huge then return rounded end
    end

    function Live.friendly_host.TopRestore(lease)
        local scope = Live.friendly_local_scope(lease.pin)
        if scope == false then return true end
        if scope ~= true then return false end
        local state = Live.remote_entity_state(lease.proof)
        if state == 'retired' then return true end
        local function fence()
            return Live.friendly_local_scope(lease.pin) == true and Live.remote_entity_state(lease.proof) == 'current'
        end
        if state ~= 'current' or not Live.remote_control(lease.proof, false, fence) or not fence() then
            return Live.friendly_local_scope(lease.pin) == false
        end
        local ok, done = pcall(function()
            if not fence() then return Live.friendly_local_scope(lease.pin) == false end
            local current = lease.vehicle.VehicleTopSpeedPercent
            if type(current) ~= 'number' or current ~= current or math.abs(current) == math.huge then return false end
            if current ~= lease.value then return true end
            if not Live.remote_control(lease.proof, false, fence) or not fence() then
                return Live.friendly_local_scope(lease.pin) == false
            end
            -- Both stored values came from the same float32 field. An external
            -- update during control acquisition is never ours to restore over.
            if lease.vehicle.VehicleTopSpeedPercent ~= lease.value then return true end
            if not fence() then return Live.friendly_local_scope(lease.pin) == false end
            lease.vehicle.VehicleTopSpeedPercent = lease.before
            return fence() and lease.vehicle.VehicleTopSpeedPercent == lease.before
        end)
        return ok and done == true
    end

    function Live.friendly_host.Vehicle(r, now)
        local pin = r.pin
        local handle = invoke_int(H.GET_VEHICLE_PED_IS_IN, pin.ped, false)
        if not handle or handle <= 0 then
            r.vehicle_authority_since = nil
            if r.top and Live.friendly_host.TopRestore(r.top) then r.top = nil end
            return 'Waiting for the selected player vehicle'
        end
        if invoke_int(H.GET_PED_IN_VEHICLE_SEAT, handle, -1, false) ~= pin.ped then
            r.vehicle_authority_since = nil
            if r.top and Live.friendly_host.TopRestore(r.top) then r.top = nil end
            return r.top and 'Previous vehicle top speed restoration pending' or 'Selected player must be the driver'
        end
        local fresh = Live.friendly_proof(handle)
        local proof = r.vehicle_proof
        if not proof or not fresh or proof.handle ~= fresh.handle or proof.address ~= fresh.address or proof.network_id ~= fresh.network_id then
            proof = fresh; r.vehicle_proof = proof; r.vehicle_authority_since = nil
            r.repair_on_first_control = true -- repair minor damage on vehicle transition
        end
        if not proof or Live.friendly_host.Current(pin) ~= true then return 'Vehicle identity unavailable' end
        local fence = function()
            return Live.friendly_host.Current(pin) == true and
                invoke_int(H.GET_VEHICLE_PED_IS_IN, pin.ped, false) == handle and
                invoke_int(H.GET_PED_IN_VEHICLE_SEAT, handle, -1, false) == pin.ped
        end
        if r.top and (r.top.proof.address ~= proof.address or not r.flags.remote_top_speed) then
            if not Live.friendly_host.TopRestore(r.top) then return 'Previous vehicle top speed restoration pending' end
            r.top = nil
        end
        -- Requesting this occupied vehicle calls GiveControl to our client and
        -- can fight its driver's simulation. Assistance must never migrate it.
        if not Live.remote_control(proof, false, fence) then
            -- The occupied vehicle is normally simulated by its driver.
            -- Never claim that a local setter changed a remote driver's car.
            -- This state is recoverable: menu intent remains enabled.
            return 'Waiting: vehicle is controlled by its driver'
        end
        r.vehicle_authority_since = nil
        local status = 'Vehicle authority observed; remote effect unverified'
        if r.flags.remote_auto_repair and now >= (r.next_repair or 0) then
            r.next_repair = now + 500
            local engine = Live.friendly_float(0xC45D23BAF168AAB8, handle)
            local body = Live.friendly_float(0xF271147EB7B40F12, handle)
            if engine and body and (r.repair_on_first_control or engine < 999 or body < 999)
                and fence() and Live.remote_control(proof, false, fence) then
                r.repair_on_first_control = false
                Live.friendly_write(0x45F6D8EEF34ABEF1, handle, 1000.0)
                if fence() and Live.remote_control(proof, false, fence) then
                    Live.friendly_write(0x115722B1B9C14C1C,
                        handle)
                end
                if fence() and Live.remote_entity_state(proof) == 'current' then
                    engine = Live.friendly_float(0xC45D23BAF168AAB8, handle); body = Live.friendly_float(
                        0xF271147EB7B40F12, handle)
                    status = engine and body and engine >= 990 and body >= 990 and
                        'Repair readback confirmed locally; peer effect unverified' or
                        'Repair requested; readback pending'
                end
            end
        end
        if r.flags.remote_speed and fence() and Live.remote_control(proof, false, fence) then
            Live.friendly_write(0xB59E4BD37AE292DB, handle, r.settings.speed)
            status = 'Speed multiplier requested; no native multiplier readback'
        end
        if r.flags.remote_horn_boost and now >= (r.next_horn or 0) and Live.remote_bool(0x9D6BFC12B05C6121, handle) == true then
            r.next_horn = now + 250
            local v = Live.friendly_vec(0x4805D2B1D8CF94A9, handle); local f = Live.friendly_vec(0x0A794A5A57F8DF91,
                handle)
            if v and f and fence() and Live.remote_control(proof, false, fence) then
                local x, y, z = v.x + f.x * 8, v.y + f.y * 8, v.z + f.z * 8
                local speed = math.sqrt(x * x + y * y + z * z)
                if speed > 120 then x, y, z = x * 120 / speed, y * 120 / speed, z * 120 / speed end
                Live.friendly_write(0x1C99BB7B6E96D16F, handle, x, y, z)
                local seen = fence() and Live.friendly_vec(0x4805D2B1D8CF94A9, handle)
                status = seen and math.abs(seen.x - x) < 2 and math.abs(seen.y - y) < 2 and
                    'Horn boost velocity read back locally; peer effect unverified' or
                    'Horn boost velocity readback pending'
            end
        end
        if r.flags.remote_top_speed and now >= (r.next_top_retry or 0)
            and fence() and Live.remote_control(proof, false, fence) then
            local ok = pcall(function()
                if not r.top then
                    local raw = module_context.Raw and module_context.Raw.CVehicle
                    if not raw or type(raw.FromAddress) ~= 'function' then
                        r.next_top_retry = now + 2000
                        status = 'Top speed unavailable on this Cherax build'
                        return
                    end
                    local vehicle = raw.FromAddress(proof.address)
                    local before = vehicle and vehicle.VehicleTopSpeedPercent
                    if type(before) ~= 'number' or before ~= before or before <= 0 or before > 10000 then return end
                    r.top = {
                        proof = proof,
                        vehicle = vehicle,
                        before = before,
                        local_id = pin.local_id,
                        local_identity =
                            pin.local_identity,
                        generation = pin.generation,
                        pin = pin
                    }
                end
                local lease = r.top; local value = Live.friendly_float32(lease.before * r.settings.top_speed)
                if value == nil then
                    r.next_top_retry = now + 2000
                    status = 'Top speed value temporarily unavailable'
                    return
                end
                local expected = lease.value or lease.before
                if lease.vehicle.VehicleTopSpeedPercent ~= expected then
                    r.top = nil -- a new writer now owns the value; never restore over them
                    r.next_top_retry = now + 1000
                    status = 'Top speed baseline changed; waiting to recapture'
                    return
                end
                if not fence() or not Live.remote_control(proof, false, fence) or not fence() then return end
                if lease.vehicle.VehicleTopSpeedPercent ~= expected then
                    r.top = nil -- a new writer now owns the value; never restore over them
                    r.next_top_retry = now + 1000
                    status = 'Top speed baseline changed; waiting to recapture'
                    return
                end
                -- Store the exact field representation before the fallible setter,
                -- retaining ownership if it applies and then throws.
                lease.value = value
                if expected ~= value then lease.vehicle.VehicleTopSpeedPercent = value end
                local observed = fence() and lease.vehicle.VehicleTopSpeedPercent
                status = observed == value and 'Top speed field read back locally; peer effect unverified' or
                    'Top speed field readback pending'
            end)
            if not ok then status = 'Top speed field unavailable; cleanup retained' end
        end
        return status
    end

    function Live.friendly_host.Firing(pin)
        if Live.friendly_host.Current(pin) ~= true then return false end
        local vehicle=invoke_int(H.GET_VEHICLE_PED_IS_IN,pin.ped,false)
        if not vehicle or vehicle<=0 then return false end
        if invoke_int(H.GET_PED_IN_VEHICLE_SEAT,vehicle,-1,false)~=pin.ped then return false end
        return Live.remote_bool(0x34616828CD07F1A1,pin.ped)==true
    end

    function Live.friendly_host.Spawn(r, kind, index, now)
        local pin = r.pin
        local model = utils.Joaat(kind == 'gun' and 'adder' or r.settings.model)
        if Live.remote_bool(kind == 'guard' and 0xBCBF4FEF9FA5D781 or 0x7277F1F2E085EE74, 1) ~= true then
            return nil,
                'Network entity capacity unavailable.', true
        end
        if Live.remote_bool(0xC0296A2EDF545E92, model) ~= true then return nil, 'Invalid spawn model.', true end
        if kind == 'guard' and Live.remote_bool(0x75816577FEA6DAD5, model) ~= true then
            return nil,
                'Invalid bodyguard model.', true
        end
        if kind == 'guard' and Live.remote_bool(0x937C71165CF334B3, utils.Joaat(r.settings.weapon)) ~= true then
            return
                nil, 'Invalid bodyguard weapon.', true
        end
        if Live.remote_bool(0x98A4EB5D89A0C952, model) ~= true then
            r.model_requests = r.model_requests or {}; r.model_requests[model] = r.model_requests[model] or now
            Live.friendly_model_users = Live.friendly_model_users or {}
            local users = Live.friendly_model_users[model] or {}; Live.friendly_model_users[model] = users; users[r] = true
            if now - r.model_requests[model] > 10000 then return nil, 'Selected model could not load.', true end
            r.model_request_due = r.model_request_due or {}
            if now >= (r.model_request_due[model] or 0) then
                r.model_request_due[model] = now + 250
                if not Live.friendly_write(0x963D27A58DF860AC, model) then
                    return nil, 'Selected model unavailable.',
                        true
                end
            end
            return nil, 'Loading selected model'
        end
        local point = Live.friendly_vec(H.GET_ENTITY_COORDS, pin.ped, false)
        if not point or Live.friendly_host.Current(pin) ~= true then return nil, 'Selected player is not streamed' end
        local direction = kind == 'gun' and Live.friendly_vec(0x0A794A5A57F8DF91, pin.ped)
        local angle = (index - 1) * math.pi * 2 / math.max(1, r.settings.count)
        local x, y, z = point.x + math.cos(angle) * 3, point.y + math.sin(angle) * 3, point.z
        if kind == 'gun' then
            if not direction then return nil, 'Remote firing direction unavailable' end
            local length = math.sqrt(direction.x ^ 2 + direction.y ^ 2 + direction.z ^ 2)
            if length < 0.5 or length > 1.5 then return nil, 'Remote firing direction unavailable' end
            direction = { x = direction.x / length, y = direction.y / length, z = direction.z / length }
            x, y, z = point.x + direction.x * 6, point.y + direction.y * 6, point.z + 1 + direction.z * 6
        end
        local ok, handle
        if kind == 'guard' then
            ok, handle = pcall(gta.CreatePed, model, 4, x, y, z, 0, true, true)
        else
            ok, handle = pcall(gta.SpawnVehicle, model, x, y, z, 0, true, true)
        end
        if not ok or type(handle) ~= 'number' or handle <= 0 then return nil, 'Entity creation failed.', true end
        if handle == pin.ped or handle == local_ped() or handle == invoke_int(H.GET_VEHICLE_PED_IS_IN, pin.ped, false)
            or handle == invoke_int(H.GET_VEHICLE_PED_IS_IN, local_ped(), false) then
            return nil, 'Spawn returned a protected entity.', true
        end
        -- Register ownership immediately, even if the host yields or identity is not readable yet.
        local actor = {
            handle = handle,
            proof = Live.friendly_proof(handle),
            model = model,
            pin = pin,
            born = now,
            owned = true,
            direction =
                direction,
            row = r
        }
        local pointer = Ignore.read(function() return gta.HandleToPointer(handle) end)
        actor.address = pointer and Ignore.address(pointer)
        Live.friendly_owned = Live.friendly_owned or {}; Live.friendly_owned[handle] = actor
        local observed_model = invoke_int(0x9F47B058362C84B5, handle)
        if not observed_model or observed_model % 4294967296 ~= model % 4294967296 then
            actor.proof = nil; actor.unproven = true
        end
        if not actor.proof or Live.friendly_host.Current(pin) ~= true then
            actor.unproven = not actor.proof; actor.expires = now; return actor
        end
        if not Live.remote_control(actor.proof, true) then
            actor.initializing = true; actor.init_deadline = now + 4000; return actor
        end
        if kind == 'guard' then
            actor.initializing = true; actor.init_deadline = now + 4000
            Live.friendly_initialize_guard(r, actor, now)
        else
            if not Live.friendly_actor_write(r, actor, 0x1C99BB7B6E96D16F, handle, direction.x * 65, direction.y * 65, direction.z * 65) then
                actor.expires =
                    now
            end
        end
        if r.model_requests and r.model_requests[model] ~= nil then Live.friendly_release_model(r, model) end
        return actor
    end

    function Live.friendly_initialize_guard(r, actor, now)
        local handle = actor.handle; local pin = r.pin
        if not actor.proof or Live.remote_entity_state(actor.proof) ~= 'current' then return false end
        if not Live.remote_control(actor.proof, true) then
            if now >= (actor.init_deadline or now) then
                actor.expires = now; r.status = 'Bodyguard control unavailable; cleanup pending'
                if not actor.notified then
                    actor.notified = true
                    if now >= (r.guard_notice_due or 0) then
                        r.guard_notice_due = now + 5000; Live.friendly_host.Notice(r.pid,
                            'A bodyguard could not get control.')
                    end
                end
            end
            return false
        end
        local weapon = utils.Joaat(r.settings.weapon)
        if Live.remote_bool(0x937C71165CF334B3, weapon) ~= true then
            actor.expires = now; return false
        end
        if not Live.friendly_actor_write(r, actor, 0xBF0FD6E56C964FCB, handle, weapon, 250, false, true)
            or not Live.friendly_actor_write(r, actor, 0xADF692B254977C0C, handle, weapon, true)
            or not Live.friendly_actor_write(r, actor, 0x3882114BDE571AD4, handle, r.settings.godmode, false)
            or not Live.friendly_actor_write(r, actor, 0x1760FFA8AB074D66, handle, not r.settings.godmode)
            or not Live.friendly_actor_write(r, actor, 0x9F8AA94D6D97DBF4, handle, true)
            or not Live.friendly_actor_write(r, actor, 0x971D38760FBC02EF, handle, true)
            or not Live.friendly_actor_write(r, actor, 0x66B57B72E0836A76, handle, pin.pid, false)
            or not Live.friendly_actor_write(r, actor, 0x66B57B72E0836A76, handle, pin.local_id, false) then
            if now >= (actor.init_deadline or now) then
                actor.expires = now; r.status = 'Bodyguard initialization failed; cleanup pending'
                if not actor.notified then
                    actor.notified = true
                    if now >= (r.guard_notice_due or 0) then
                        r.guard_notice_due = now + 5000; Live.friendly_host.Notice(r.pid,
                            'A bodyguard could not be initialized.')
                    end
                end
            end
            return false
        end
        local equipped = invoke_int(0x0A6DB4965674D243, handle)
        local damageable = Live.remote_bool(0xD95CC5D2AB15A09F, handle)
        if type(equipped) ~= 'number' or equipped % 4294967296 ~= weapon % 4294967296 or damageable ~= not r.settings.godmode then
            if now >= (actor.init_deadline or now) then
                actor.expires = now; r.status = 'Bodyguard settings readback failed; cleanup pending'
            end
            return false
        end
        actor.settings_revision = r.guard_settings_revision or 0
        actor.initializing = nil
        return true
    end

    function Live.friendly_host.Advance(r, a, now)
        if a.kind ~= 'gun' or not a.initializing or a.expires and a.expires <= now then return end
        if a.proof and Live.remote_entity_state(a.proof) == 'current' and Live.remote_control(a.proof, true) then
            local direction = a.direction
            if direction and Live.friendly_actor_write(r, a, 0x1C99BB7B6E96D16F, a.handle, direction.x * 65, direction.y * 65, direction.z * 65) then
                a.initializing = nil
                return
            end
        end
        if now >= (a.init_deadline or now) then
            a.initializing = nil; a.expires = now
            r.flags.vehicle_gun = nil; Live.friendly_host.Reset('vehicle_gun', r.pid)
            r.status = 'Vehicle Gun launch control unavailable; cleanup pending'
            Live.friendly_host.Notice(r.pid, 'Vehicle Gun could not get launch control.')
        end
    end

    function Live.friendly_actor_write(r, a, hash, ...)
        if Live.friendly_host.Current(r.pin) ~= true or not a.proof or Live.remote_entity_state(a.proof) ~= 'current'
            or not Live.remote_control(a.proof, false) or Live.friendly_host.Current(r.pin) ~= true
            or Live.remote_entity_state(a.proof) ~= 'current' then
            return false
        end
        return Live.friendly_write(hash, ...)
    end

    function Live.friendly_host.Guards(r, now)
        local point = Live.friendly_vec(H.GET_ENTITY_COORDS, r.pin.ped, false)
        if not point then return end
        local protected = { [r.pin.ped] = true, [local_ped()] = true }
        for handle, actor in pairs(Live.friendly_owned or {}) do
            if actor.proof and Live.remote_entity_state(actor.proof) == 'current' then protected[handle] = true end
        end
        if now >= (r.next_threat or 0) then
            r.next_threat = now + 1000
            local entries = Ignore.read(function() return pool_mgr.GetRenderedPeds() end)
            local pointers = entries and Ignore.rendered_pointers(entries) or {}
            pointers = pointers or {}
            local enemy, best = nil, math.huge
            local start = r.threat_cursor or 0
            for offset = 1, math.min(48, #pointers) do
                local index = (start + offset - 1) % #pointers + 1
                local proof = Ignore.proof(pointers[index],
                    function() return Live.friendly_host.Current(r.pin) == true end)
                local h = proof and proof.handle
                if h and not protected[h] and Live.remote_bool(H.IS_ENTITY_DEAD, h, false) == false then
                    local isplayer = Live.remote_bool(0x12534C348C6CB68B, h)
                    local mode = r.settings.targeting
                    local relevant = mode == 'attack_all' or mode == 'defend_both' or
                        mode == 'defend_players' and isplayer == true or mode == 'defend_npcs' and isplayer == false
                    local threat = mode == 'attack_all' or Live.remote_bool(0x4859F1FC66A6278E, h, r.pin.ped) == true or
                        Live.remote_bool(0xC86D67D52A707CF8, r.pin.ped, h, true) == true
                    if relevant and threat then
                        local at = Live.friendly_vec(H.GET_ENTITY_COORDS, h, false)
                        local distance = at and ((at.x - point.x) ^ 2 + (at.y - point.y) ^ 2 + (at.z - point.z) ^ 2)
                        if distance and distance < 60 * 60 and distance < best then enemy, best = proof, distance end
                    end
                end
            end
            r.threat_cursor = #pointers > 0 and (start + 48) % #pointers or 0
            r.enemy = enemy
        end
        local enemy = r.enemy
        if enemy and (protected[enemy.handle] or Live.remote_entity_state(enemy) ~= 'current') then
            enemy = nil; r.enemy = nil
        end
        local vehicle = invoke_int(H.GET_VEHICLE_PED_IS_IN, r.pin.ped, false)
        if not vehicle or vehicle <= 0 then vehicle = invoke_int(0x814FA8BE5449445D, r.pin.ped) end
        local vehicle_proof = vehicle and vehicle > 0 and Live.friendly_proof(vehicle) or nil
        if vehicle_proof and (not r.guard_vehicle or r.guard_vehicle.address ~= vehicle_proof.address or r.guard_vehicle.network_id ~= vehicle_proof.network_id) then
            r.guard_vehicle = vehicle_proof
            for _, a in ipairs(r.actors) do
                a.seat = nil; a.enter_until = nil; a.task = nil
            end
        elseif not vehicle_proof then
            if r.guard_vehicle then
                for _, a in ipairs(r.actors) do
                    a.seat = nil; a.enter_until = nil; a.next_task = 0; a.task = nil
                end
            end
            r.guard_vehicle = nil
        end
        local claims = {}
        for _, a in ipairs(r.actors) do
            if a.kind == 'guard' and a.seat and a.enter_until and now < a.enter_until then claims[a.seat] = a end
        end
        local work = 0
        for index, a in ipairs(r.actors) do
            if a.kind == 'guard' and a.proof and not a.expires and Live.friendly_host.Current(r.pin) == true then
                if Live.remote_entity_state(a.proof) == 'retired' or Live.remote_bool(H.IS_ENTITY_DEAD, a.handle, false) == true then
                    a.expires = now
                elseif a.initializing or a.settings_revision ~= (r.guard_settings_revision or 0) then
                    if not a.initializing then
                        a.initializing = true; a.init_deadline = now + 4000
                    end
                    if work < 4 then
                        work = work + 1; Live.friendly_initialize_guard(r, a, now)
                    end
                elseif work < 4 and now >= (a.next_task or 0) and Live.remote_control(a.proof, true) then
                    local seated = invoke_int(H.GET_VEHICLE_PED_IS_IN, a.handle, false)
                    if vehicle_proof and Live.remote_entity_state(vehicle_proof) == 'current' then
                        if seated == vehicle then
                            a.seat = nil; a.enter_until = nil; a.next_task = now + 1000
                        elseif not a.enter_until or now >= a.enter_until then
                            a.seat = nil; a.enter_until = nil
                            local maximum = invoke_int(0xA7C4F2C6E744A550, vehicle)
                            if type(maximum) == 'number' and maximum > 0 and maximum <= 32 then
                                for seat = 0, maximum - 1 do
                                    if not claims[seat] and Live.remote_bool(0x22AC59A870E6A669, vehicle, seat, true) == true then
                                        claims[seat] = a; a.seat = seat; a.enter_until = now + 6500
                                        work = work + 1
                                        -- Flag 1 uses ordinary entry; 3/16 would teleport.
                                        Live.friendly_actor_write(r, a, 0xC20E50AA46D09CA8, a.handle, vehicle, 6000, seat,
                                            2.0, 1, 0)
                                        a.task = 'enter'; a.next_task = now + 6500
                                        break
                                    end
                                end
                            end
                            if not a.seat then
                                work = work + 1; a.next_task = now + 2000
                                Live.friendly_actor_write(r, a, 0x304AE42E357B8C7E, a.handle, r.pin.ped,
                                    (index % 3 - 1) *
                                    2, -3 - math.floor(index / 3) * 2, 0, 4.0, -1, 4.0, true)
                                a.task = 'follow'
                            end
                        end
                    elseif seated and seated > 0 then
                        work = work + 1; a.seat = nil; a.enter_until = nil; a.task = 'leave'; a.next_task = now + 3000
                        Live.friendly_actor_write(r, a, 0xD3DBCE61A490BE02, a.handle, seated, 0)
                    elseif enemy then
                        work = work + 1; a.task = 'combat'; a.next_task = now + 3000
                        Live.friendly_actor_write(r, a, 0xF166E48407BAC484, a.handle, enemy.handle, 0, 16)
                    else
                        work = work + 1; a.task = 'follow'; a.next_task = now + 4000
                        Live.friendly_actor_write(r, a, 0x304AE42E357B8C7E, a.handle, r.pin.ped, (index % 3 - 1) * 2,
                            -2 - math.floor(index / 3) * 2, 0, 3.0, -1, 3.0, true)
                    end
                end
            end
        end
    end

    function Live.friendly_model_pending(model)
        for _, actor in pairs(Live.friendly_owned or {}) do
            local row = actor.row
            if actor.model == model and actor.initializing and not actor.expires and row and not row.retired then
                local enabled
                if actor.kind == 'gun' or type(actor.direction) == 'table' then
                    enabled = row.flags.vehicle_gun
                else
                    enabled = row.flags.bodyguards
                end
                if enabled then return true end
            end
        end
        return false
    end

    function Live.friendly_release_model(r, model)
        if not r.model_requests or r.model_requests[model] == nil then return true end
        if Live.friendly_model_pending(model) then return false end
        local users = Live.friendly_model_users and Live.friendly_model_users[model]
        if users then
            for other in pairs(users) do
                if other ~= r and (not other.model_requests or other.model_requests[model] == nil) then
                    users[other] = nil
                elseif other ~= r then
                    -- The remaining row carries the one streaming obligation.
                    -- Releasing this row must not cancel another pending load.
                    users[r] = nil; r.model_requests[model] = nil
                    return true
                end
            end
        end
        if not Live.friendly_write(0xE532F5D78798DAAB, model) then return false end
        r.model_requests[model] = nil
        if users then
            users[r] = nil
            if next(users) == nil then Live.friendly_model_users[model] = nil end
        end
        return true
    end

    function Live.friendly_host.ReleaseModels(r, all)
        for model in pairs(r.model_requests or {}) do
            local needed = false
            if not all then
                needed = r.flags.bodyguards and not r.guard_phase_done and model == utils.Joaat(r.settings.model)
                    or r.flags.vehicle_gun and model == utils.Joaat('adder')
            end
            if not needed then Live.friendly_release_model(r, model) end
        end
    end

    function Live.friendly_retire_actor(a)
        if Live.friendly_owned and Live.friendly_owned[a.handle] == a then Live.friendly_owned[a.handle] = nil end
        return true
    end

    function Live.friendly_host.Delete(a, now)
        if a.buffer then
            local freed, value = pcall(memory.Free, a.buffer)
            if not freed or value == false then return false end
            a.buffer = nil
        end
        if not a.owned then return false end
        local scope = Live.friendly_local_scope(a.pin)
        if scope == false then return Live.friendly_retire_actor(a) end
        if scope ~= true then return false end
        if not a.proof and a.address then
            local pointer = Ignore.read(function() return gta.HandleToPointer(a.handle) end)
            local model = invoke_int(0x9F47B058362C84B5, a.handle)
            if pointer and Ignore.address(pointer) == a.address and model and model % 4294967296 == a.model % 4294967296 then
                a.proof = Live.friendly_proof(a.handle); a.unproven = not a.proof
            end
        end
        if a.unproven or not a.proof then return false end
        local state = Live.remote_entity_state(a.proof)
        if state == 'retired' then return Live.friendly_retire_actor(a) end
        local function fence()
            return Live.friendly_local_scope(a.pin) == true and Live.remote_entity_state(a.proof) == 'current'
        end
        if state ~= 'current' or not Live.remote_control(a.proof, true, fence) or not fence() then
            if Live.friendly_local_scope(a.pin) == false then return Live.friendly_retire_actor(a) end
            return false
        end
        local ok, ptr = pcall(memory.AllocInt)
        if not ok or type(ptr) ~= 'number' or ptr <= 0 then return false end
        local stored, result = pcall(memory.WriteInt, ptr, a.handle)
        if stored and result ~= false and fence() and Live.remote_control(a.proof, false, fence) and fence() then
            Live.friendly_write(0xAD738C3085FE7E11, a.handle, true, true)
            if fence() and Live.remote_control(a.proof, false, fence) and fence() then
                a.delete_accepted = Live
                    .friendly_write(0xAE3CBE5BF394C9C9, ptr) or a.delete_accepted
            end
        end
        local freed, value = pcall(memory.Free, ptr)
        if not freed or value == false then
            a.buffer = ptr; return false
        end
        local done = Live.friendly_local_scope(a.pin) == false or
            a.delete_accepted and Live.remote_entity_state(a.proof) == 'retired'
        if done then Live.friendly_retire_actor(a) end
        return done
    end

    Live.headgear_host = {}
    function Live.headgear_host.Capture()
        if not started then return nil end
        local ped = local_ped()
        if not entity_exists(ped) or Live.remote_bool(0x5F9532F3B5CC2551, ped, false) ~= false then return nil end
        local proof = Live.friendly_proof(ped)
        if proof then proof.headgear_model = invoke_int(H.GET_ENTITY_MODEL, ped) end
        return proof
    end

    function Live.headgear_host.Current(proof) return Live.remote_entity_state(proof) end

    function Live.headgear_host.ReadFlag(proof, flag)
        if Live.remote_entity_state(proof) ~= 'current' then return nil end
        return Live.remote_bool(H.GET_PED_CONFIG_FLAG, proof.handle, flag, true)
    end

    function Live.headgear_host.WriteFlag(proof, flag, value)
        return Live.remote_entity_state(proof) == 'current' and
            Live.friendly_write(H.SET_PED_CONFIG_FLAG, proof.handle, flag, value)
    end

    function Live.headgear_host.LoseProps(proof, value)
        -- CanLosePropsOnDamage=228, CanLoseHelmetOnDamage=258, and
        -- DontTakeOffHelmet=36: documented ePedConfigFlags (citizenfx/natives).
        return Live.remote_entity_state(proof) == 'current' and
            Live.friendly_write(0xE861D0B05C7662B8, proof.handle, value, 0)
    end

    function Live.headgear_host.ReadProps(proof)
        if Live.remote_entity_state(proof) ~= 'current' then return nil end
        local props = {}
        for index = 0, 2 do
            local drawable, raw, err = invoke_int_detail(0x898CC20EA75BACD8, proof.handle, index, 0)
            local texture, traw, terr = invoke_int_detail(0xE131A28626F81AB2, proof.handle, index)
            if err ~= nil or terr ~= nil or type(raw) ~= 'number' or type(traw) ~= 'number' or drawable < -1 or texture < -1 then return nil end
            props[index + 1] = { drawable = drawable, texture = texture }
        end
        return Live.remote_entity_state(proof) == 'current' and props or nil
    end

    function Live.headgear_host.WriteProp(proof, index, prop)
        return Live.remote_entity_state(proof) == 'current' and Live.friendly_write(0x93376B65A266EB5F,
            proof.handle, index - 1, prop.drawable, math.max(0, prop.texture), true, 0)
    end

    function Live.headgear_host.Event(proof, now)
        local wardrobe = State.outfit
        if wardrobe and (wardrobe.studio_open or wardrobe.visible_ping or wardrobe.pending_action or wardrobe.preview_suppressed
                or now - (wardrobe.last_visible_ms or -100000) < 500) then
            return false
        end
        local health = invoke_int(0xEEF059FAD016D209, proof.handle)
        local vehicle = invoke_int(H.GET_VEHICLE_PED_IS_IN, proof.handle, false)
        local previous = Live.headgear_event
        local event = previous and previous.address == proof.address and
            (health < previous.health or vehicle ~= previous.vehicle or Live.remote_bool(0xBB062B2B5722478E, proof.handle) == true)
        Live.headgear_event = { address = proof.address, health = health, vehicle = vehicle }
        return event == true
    end

    Live.headgear = Module.NewHeadgearController(Live.headgear_host)
    Live.friendly = Module.NewFriendlyController(Live.friendly_host)


    -- Self-Isolation Mode: transient contact filtering for owned actors.
    -- No persistent entity flags, model/cap/wave values,
    -- spawn networking args, remote effects, or original rrer CFG are rewritten.
    --
    -- This cannot protect GTA if the native engine crashes before the Lua
    -- scheduler runs, and peer-visible physics equivalence needs live testing.
    Live.rrer_shield={
        actors={},by_handle={},last_sample=0,
        severe_samples=0,low_pool_samples=0,trip_until=0,
        last_report=0,active_feature=nil,trip_count=0,cleaning=false
    }
    Live.rrer_shield_H={
        entity_exists=0x7239B21A38F536BA,
        entity_model=0x9F47B058362C84B5,
        frame_time=0x15C40837039FFAF7,
    }
    function Live.rrer_shield_now()
        local value=now_ms()
        return type(value)=="number" and value==value and value or 0
    end
    function Live.rrer_shield_other_vehicle_busy()
        local active=Live.vehicle_chaos
        if not active or type(active.Status)~="function"then return false end
        local ok,status=pcall(active.Status)
        return ok and type(status)=="table" and
            (status.phase=="executing" or status.phase=="cleanup" or
                status.phase=="returning" or (status.pending or 0)>0)
    end
    function Live.rrer_shield_work_clock()
        if type(os)=="table" and type(os.clock)=="function" then
            local ok,value=pcall(os.clock)
            if ok and type(value)=="number" and value==value then return value*1000 end
        end
        return Live.rrer_shield_now()
    end
    function Live.rrer_shield_on()
        if not started or not bound or not lifecycle_token or lifecycle_token.alive~=true then return false end
        local current=module_context and module_context.CScript and module_context.CScript.Protections
        if not current or type(current.SelfIsolationEnabled)~="function" then return false end
        local ok,enabled=pcall(current.SelfIsolationEnabled)
        return ok and enabled==true
    end
    Live.rrer_contact=Module.NewSelfIsolationController({
        EventMgr=module_context.Raw and module_context.Raw.EventMgr,
        Event=module_context.Raw and module_context.Raw.eLuaEvent and module_context.Raw.eLuaEvent.SHOULD_COLLIDE,
        Running=function()
            return started and bound and lifecycle_token and lifecycle_token.alive==true
        end,
        Enabled=Live.rrer_shield_on,
        GetLocalPlayerId=gta and gta.GetLocalPlayerId,
        GetLocalPed=gta and gta.GetLocalPed,
        GetLocalVehicle=gta and gta.GetLocalVehicle,
        PointerToHandle=gta and gta.PointerToHandle,
    })
    function Live.rrer_shield_reset()
        Live.rrer_contact.Reset()
        Live.rrer_shield.actors={}
        Live.rrer_shield.by_handle={}
        Live.rrer_shield.active_feature=nil
        Live.rrer_shield.cleaning=false
        Live.rrer_shield.severe_samples,Live.rrer_shield.low_pool_samples=0,0
    end
    function Live.rrer_shield_address(handle)
        local ok,address=pcall(function()
            local physical=GTA.HandleToPointer(handle)
            return physical and physical:GetAddress()
        end)
        if ok and type(address)=="number" and address>0 and address==address
            and address<math.huge and address%1==0 then return address end
    end
    function Live.rrer_shield_present(entry)
        if not entry or type(entry.handle)~="number" or entry.handle<=0 or not entry.address then return false end
        local ok,exists=pcall(Natives.InvokeBool,Live.rrer_shield_H.entity_exists,entry.handle)
        if not ok or (exists~=true and exists~=1) then return false end
        local checked,model=pcall(Natives.InvokeInt,Live.rrer_shield_H.entity_model,entry.handle)
        if not checked or type(model)~="number" or model%4294967296~=entry.model%4294967296 then return false end
        local net_ok,networked=pcall(Natives.InvokeBool,0xC7827959479DCC78,entry.handle)
        if not net_ok then return false end
        if networked==true then
            local controlled,owned=pcall(Natives.InvokeBool,0x01BF60A500E28887,entry.handle)
            if not controlled or owned~=true then return false end
        elseif networked~=false then return false end
        if Live.rrer_shield_address(entry.handle)~=entry.address then return false end
        entry.networked=networked
        return true
    end
    function Live.rrer_shield_track(handle,model)
        if type(handle)~="number" or handle<=0 or handle%1~=0 or
            type(model)~="number" then return end
        local actors=Live.rrer_shield.actors
        if #actors>=384 then return end -- prevent unbounded handle tracking
        for _,entry in ipairs(actors)do
            if entry.handle==handle then return end
        end
        local rec={handle=handle,model=model,address=Live.rrer_shield_address(handle)}
        actors[#actors+1]=rec
        Live.rrer_shield.by_handle[handle]=rec
    end
    function Live.rrer_shield_configured(handle)
        local record=Live.rrer_shield.by_handle[handle]
        -- The setup hook already runs on the native worker. Admit only the
        -- original, owned allocation after setup; the event itself uses no natives.
        if Live.rrer_shield_present(record) then Live.rrer_contact.Track(record) end
    end
    function Live.rrer_shield_tick()
        if not Live.rrer_shield_on() then
            Live.rrer_shield.severe_samples,Live.rrer_shield.low_pool_samples=0,0
            return
        end
        local clock=Live.rrer_shield_now()
        local actors=Live.rrer_shield.actors
        if clock<Live.rrer_shield.last_sample+200 and
            clock>=Live.rrer_shield.last_sample then return end
        Live.rrer_shield.last_sample=clock
        local monitoring=(#actors>0 and Live.rrer_shield.active_feature~=nil)
            or Live.rrer_shield_other_vehicle_busy()
        if not monitoring then
            Live.rrer_shield.severe_samples,Live.rrer_shield.low_pool_samples=0,0
            return
        end
        local frame_ok,frame=pcall(Natives.InvokeFloat,Live.rrer_shield_H.frame_time)
        if frame_ok and type(frame)=="number" and frame==frame and
            frame>=0.10 and frame<10.0 then
            Live.rrer_shield.severe_samples=Live.rrer_shield.severe_samples+1
        else
            Live.rrer_shield.severe_samples=0
        end
        -- Entity pool headroom is a *proxy*. Cherax's crash-log Manifold Pool
        -- has no documented Lua accessor, so this must never be represented
        -- as direct manifold pressure measurement.
        local pool=module_context and module_context.Raw and module_context.Raw.PoolMgr
        local available
        if pool and type(pool.GetCurrentPedCount)=="function" and
            type(pool.GetMaxPedCount)=="function" then
            local ok,used,cap=pcall(function()
                return pool.GetCurrentPedCount(),pool.GetMaxPedCount()
            end)
            if ok and type(used)=="number" and type(cap)=="number" and
                cap>0 and used>=0 and cap>=used then
                available=cap-used
            end
        end
        if available and available<24 then
            Live.rrer_shield.low_pool_samples=Live.rrer_shield.low_pool_samples+1
        else
            Live.rrer_shield.low_pool_samples=0
        end
        if clock>=Live.rrer_shield.last_report+5000 or
            clock<Live.rrer_shield.last_report then
            Live.rrer_shield.last_report=clock
            local contact=Live.rrer_contact.Snapshot()
            log_info(("Self-Isolation: tracked=%d contacts=%d failures=%d fpsSpike=%d pedHeadroom=%s contactFilter=%s")
                :format(#actors,contact.blocked,contact.failures,
                    Live.rrer_shield.severe_samples,tostring(available or "unknown"),contact.detail))
        end
        if clock<Live.rrer_shield.trip_until or
            (Live.rrer_shield.severe_samples<4 and Live.rrer_shield.low_pool_samples<3) then
            return
        end
        Live.rrer_shield.trip_until=clock+15000
        Live.rrer_shield.trip_count=Live.rrer_shield.trip_count+1
        log_info("Self-Isolation: severe client performance/pool condition. Stopping owned Baller/vehicle effects; no unrelated entity deletion.")
        if Live.rrer_shield.active_feature then
            local feature=Live.rrer_shield.active_feature
            pcall(function() if feature:IsToggled() then feature:Toggle(false)end end)
        end
        local chaos=Live.vehicle_chaos
        if chaos and type(chaos.Cancel)=="function"then
            pcall(chaos.Cancel,"Self-Isolation watchdog")
        end
    end

    -- Import the exact candidate source. Stability edits live in gameplay/rrer.lua;
    -- transport encoding preserves those CRLF bytes without runtime rewriting.
    local function install_original_rrer()
        local original = FileMgr.GetMenuRootPath()
        assert(type(original)=="string" and original~="", "Cherax root required for original rrer.lua")
        local path = original:gsub("[/\\]+$","")..
            "\\Lua\\CScript\\assets\\rrer_original.b64.txt"
        local encoded = FileMgr.ReadFileContent(path)
        assert(type(encoded)=="string" and #encoded>0 and #encoded%4==0,
            "Verbatim rrer.lua build asset is unavailable")
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local map = {}
        for i=1,#alphabet do map[alphabet:byte(i)]=i-1 end
        local result={}
        for i=1,#encoded,4 do
            local a,b,c,d=encoded:byte(i,i+3)
            assert(a and b and c and d and map[a] and map[b] and
                (c==61 or map[c]) and (d==61 or map[d]),
                "Verbatim rrer.lua encoded asset is malformed")
            local value=(map[a]<<18)|(map[b]<<12)|((map[c]or 0)<<6)|(map[d]or 0)
            result[#result+1]=string.char((value>>16)&255)
            if c~=61 then result[#result+1]=string.char((value>>8)&255) end
            if d~=61 then result[#result+1]=string.char(value&255) end
        end
        local raw=table.concat(result)
        assert(#raw>=1000 and raw:find("FeatureMgr.AddPlayerFeature(FEATURE",1,true)
            and raw:find("ClickGUI.AddPlayerTab('Nigga Baller'",1,true),
            "Verbatim rrer.lua signature missing")
        -- Keep the EXISTING CScript selected-player toggle and saved hash.
        -- rrer.lua executes byte-for-byte as staged; only its runtime lookup
        -- for its standalone feature ID resolves to that existing hash.
        local identity=player_feature_id("character_baller")
        local original_joaat=Utils.Joaat
        local rrer_utils=setmetatable({
            Joaat=function(value)
                if value=="nigga_baller_kaylee_100_v1"then return identity end
                return original_joaat(value)
            end
        },{__index=Utils})
        -- The original script creates a separate standalone player tab.
        -- Suppress only THAT extra tab at the CScript integration boundary.
        -- Its own player toggle remains registered normally through
        -- CScript's FeatureMgr, with the original callback untouched.
        local rrer_gui=setmetatable({
            AddPlayerTab=function(name,callback)
                if name=="Nigga Baller"then return true end
                return ClickGUI.AddPlayerTab(name,callback)
            end
        },{__index=ClickGUI})
        -- Observe only this imported feature; no source/CFG edits or spawn changes.
        local rrer_logger=setmetatable({
            LogInfo=function(message,...)
                local text=tostring(message or "")
                if text:find("[Nigga Baller] Removing tracked entities",1,true) then
                    Live.rrer_shield.cleaning=true
                elseif text:find("[Nigga Baller] Cleanup complete.",1,true) then
                    Live.rrer_shield_reset()
                end
                return Logger.LogInfo(message,...)
            end
        },{__index=Logger})
        local rrer_featuremgr=setmetatable({
            AddPlayerFeature=function(id,name,kind,desc,callback,...)
                if id~=identity or type(callback)~="function" then
                    return FeatureMgr.AddPlayerFeature(id,name,kind,desc,callback,...)
                end
                local observed=function(feature,...)
                    local ok,on=pcall(function()return feature:IsToggled()end)
                    if ok and on then
                        Live.rrer_shield.active_feature=feature
                        Live.rrer_shield.cleaning=false
                    elseif ok and Live.rrer_shield.active_feature==feature then
                        Live.rrer_shield.cleaning=true
                    end
                    local result=table.pack(callback(feature,...))
                    if ok and on then
                        local read,still_on=pcall(function()return feature:IsToggled()end)
                        if read and still_on==false then Live.rrer_shield_reset() end
                    end
                    return table.unpack(result,1,result.n)
                end
                return FeatureMgr.AddPlayerFeature(id,name,kind,desc,observed,...)
            end
        },{__index=FeatureMgr})
        -- Preserve the repaired, owned native worker and the original callback's
        -- arguments, yields and return values. No explicit Script.Yield/throttling
        -- is added here; the existing emergency cleanup callbacks may yield.
        -- NativeLoopGroup is supplied by CScript's OWN loader, not Cherax.
        -- Never fall back to the shared gameplay dispatcher: the heavy
        -- imported worker previously caused alternate-frame processing and
        -- broke both Gravity Gun and Disable Action / Combat Mode.
        assert(type(Script.NativeLoopGroup)=="function",
            "CScript owned native-loop worker was not registered")
        local rrer_native_script=Script.NativeLoopGroup("original_rrer")
        assert(type(rrer_native_script)=="table"
            and type(rrer_native_script.RegisterLooped)=="function",
            "CScript native-loop facade is unavailable")
        local rrer_script=setmetatable({
            RegisterLooped=function(callback,...)
                return rrer_native_script.RegisterLooped(function(...)
                    pcall(Live.rrer_shield_tick)
                    return callback(...)
                end,...)
            end
        },{__index=rrer_native_script})
        local rrer_gta=setmetatable({
            CreatePed=function(...)
                local ped=GTA.CreatePed(...)
                if type(ped)=="number" and ped>0 and ped%1==0 then
                    Live.rrer_shield_track(ped,select(1,...))
                end
                return ped
            end
        },{__index=GTA})
        Live.rrer_shield_natives=setmetatable({
            InvokeVoid=function(hash,...)
                local result=Natives.InvokeVoid(hash,...)
                -- The final setup call may freeze or unfreeze the imported ped.
                if hash==0x428CA6DBD1094446 and type(select(2,...))=="boolean" and result~=false then
                    pcall(Live.rrer_shield_configured,select(1,...))
                end
                return result
            end
        },{__index=Natives})
        local rrer_env=setmetatable({
            Utils=rrer_utils,ClickGUI=rrer_gui,Logger=rrer_logger,
            FeatureMgr=rrer_featuremgr,Script=rrer_script,GTA=rrer_gta,
            Natives=Live.rrer_shield_natives
        },{__index=_ENV})
        rrer_env._G=rrer_env
        local chunk,why=load(raw,"@rrer.lua","t",rrer_env)
        assert(chunk,why)
        chunk()
        State.registered_count=State.registered_count+1
        remember_selected_feature("character_baller",identity,{},"Nigga baller")
    end

    local function register_selected_features()
        if State.selected_registered then return true end
        Live.effect_toggle_refs = {}
        add_player_toggle("auto_tp", "Auto-tp", "",
            function(feature)
                if Live.auto_tp_syncing then return end
                local pid,enabled=feature_player_id(feature),feature:IsToggled()
                if not enabled then
                    if Live.auto_tp_feature==feature then Live.stop_auto_tp("Disabled")end
                    return
                end
                local ok,why=Live.get_auto_tp().Enable(pid,feature)
                if ok then Live.auto_tp_feature=feature else
                    Live.auto_tp_syncing=true;pcall(function()feature:Toggle(false)end);Live.auto_tp_syncing=false
                    log_info("Auto-tp: "..tostring(why));toast(tostring(why))
                end
            end)
        function Live.selected_effect_stopped(kind, pid, reason)
            if kind == "aggressive_world" then
                local world = module_context.CScript.World
                local feature = world and world.GetFeature("aggressive_world")
                if feature then pcall(function() if feature:IsToggled() then feature:Toggle(false) end end) end
            end
            local entry = Live.effect_toggle_refs[kind]
            if entry and entry.pid == pid then
                Live.effect_toggle_refs[kind] = nil
                pcall(function() if entry.feature:IsToggled() then entry.feature:Toggle(false) end end)
            end
            if reason then log_info("Selected effect: " .. tostring(reason)) end
        end

        function Live.get_selected_effects()
            if not Live.selected_effects then
                local effect_deps = {}
                for key, value in pairs(deps) do effect_deps[key] = value end
                effect_deps.request_entity_control = Live.request_entity_control
                effect_deps.entity_network_owner = Live.entity_network_owner
                effect_deps.on_effect_stopped = Live.selected_effect_stopped
                effect_deps.session_key = function() return Live.action_generation end
                effect_deps.can_claim_npc = function(h, a, n)
                    local state = State.peds_ignore
                    local entry = state and state.managed and state.managed[a]
                    if not entry then return true end
                    if entry.handle ~= h or entry.network_id ~= n then return false end
                    -- Return only this ped's borrowed Ignore state before the
                    -- selected combat controller captures its own originals.
                    -- Local-player ignore gates and other NPCs stay untouched.
                    local scope = { managed = { [a] = entry } }
                    Ignore.restore_managed(scope)
                    if scope.managed[a] then return false end
                    state.managed[a] = nil; return true
                end
                effect_deps.is_scene_actor = function(h, a, n)
                    return (Live.lester_ride and Live.lester_ride.OwnsActor(h, a, n))
                        or (Live.player_setpieces and Live.player_setpieces.OwnsActor(h, a, n)) or false
                end
                Live.selected_effects = module_context.Modules.PlayerEffects.New(effect_deps)
            end
            return Live.selected_effects
        end

        for _, spec in ipairs({
            { "aggressive_npcs", "Aggressive NPCs", "npcs attack the nigga",                                    "SetAggressiveNPCs" },
            { "break_vehicle",   "Break Vehicle",   "Disrupts the player vehicle's physical jolts while driving, downward jolts for aircrafts and helicopters", "SetBreakVehicle" },
            { "angry_monke",     "Angry Monke",     "angry monke no happy",                                    "SetAngryMonke" },
        }) do
            local key, method = spec[1], spec[4]
            add_player_toggle(key, spec[2], spec[3], function(feature)
                local pid, enabled = feature_player_id(feature), feature:IsToggled()
                local previous = Live.effect_toggle_refs[key]
                if enabled and previous and previous.pid ~= pid then
                    pcall(function() feature:Toggle(false) end)
                    log_info("Stop the active " .. key .. " before selecting another player.")
                    return
                end
                if enabled then Live.effect_toggle_refs[key] = { pid = pid, feature = feature } end
                local ok, why = Live.get_selected_effects()[method](pid, enabled)
                if ok and enabled and key == "aggressive_npcs" and pid == local_player_id() then
                    set_toggle("peds_ignore", false)
                end
                if not ok then
                    if enabled then
                        Live.effect_toggle_refs[key] = nil
                        pcall(function() feature:Toggle(false) end)
                    end
                    log_info(tostring(why or "Selected effect could not start."))
                elseif not enabled then
                    local entry = Live.effect_toggle_refs[key]
                    if entry and entry.pid == pid then Live.effect_toggle_refs[key] = nil end
                end
            end)
        end
        add_player_button("dismember_vehicle", "Dismember Vehicle",
            "Detaches doors, hood, trunk and supported roofs; shatters windows. Wheels and fixed panels remain model/API limited.",
            function(feature)
                local ok, why = Live.get_selected_effects().DismemberVehicle(feature_player_id(feature))
                if not ok then log_info(tostring(why or "Vehicle parts could not be detached.")) end
            end)
        Live.bounty_toggle_refs = {}
        function Live.get_player_bounty()
            if not Live.player_bounty then
                Live.player_bounty = module_context.Modules.PlayerBounty.New({
                    now_ms = now_ms,
                    read_global_int = Live.read_global_int,
                    script_globals_ready = Live.script_globals_ready,
                    profile_ready = function()
                        if not Live.action_source_ready() or not invoke_bool(H.NETWORK_IS_SESSION_STARTED) then return false end
                        local _, threads, err = invoke_int_detail(0x2C83A9DA6BFFC4F9, 0xC875557D)
                        return err == nil and type(threads) == "number" and threads > 0
                    end,
                    session_key = function() return Live.action_generation end,
                    player_identity = function(pid)
                        local identity = Live.remote_identity(pid)
                        return identity and
                            (identity.rid .. ":" .. tostring(identity.cxn) .. ":" .. tostring(identity.local_id)) or
                            nil
                    end,
                    player_available = player_available,
                    local_player_id = local_player_id,
                    send_event = function(mask, args)
                        if not gta or type(gta.TriggerScriptEvent) ~= "function" then return false end
                        local ok, result = pcall(gta.TriggerScriptEvent, mask, args)
                        return ok and result ~= false
                    end,
                    on_stopped = function(pid, reason)
                        local feature = Live.bounty_toggle_refs[pid]
                        Live.bounty_toggle_refs[pid] = nil
                        if feature then pcall(function() if feature:IsToggled() then feature:Toggle(false) end end) end
                        log_info("Permanent Bounty: " .. tostring(reason))
                    end,
                })
            end
            return Live.player_bounty
        end

        add_player_toggle("permanent_bounty", "Permanent Bounty",
            "Renews this player's bounty after it is cleared, while in this session. Disable stops renewal; an existing bounty remains.",
            function(feature)
                local pid = feature_player_id(feature)
                if not feature:IsToggled() then
                    if Live.player_bounty then Live.player_bounty.Stop(pid) end
                    Live.bounty_toggle_refs[pid] = nil
                    return
                end
                Live.bounty_toggle_refs[pid] = feature
                local ok, why = Live.get_player_bounty().Start(pid)
                if not ok then
                    Live.bounty_toggle_refs[pid] = nil
                    pcall(function() feature:Toggle(false) end)
                    log_info("Permanent Bounty: " .. tostring(why))
                end
            end)
        Live.never_wanted_toggle_refs = {}
        function Live.get_player_never_wanted()
            if not Live.player_never_wanted then
                Live.player_never_wanted = module_context.Modules.PlayerNeverWanted.New({
                    now_ms = now_ms,
                    read_global_int = Live.read_global_int,
                    script_globals_ready = Live.script_globals_ready,
                    profile_ready = function()
                        if not Live.action_source_ready() or not invoke_bool(H.NETWORK_IS_SESSION_STARTED) then return false end
                        local _, threads, err = invoke_int_detail(0x2C83A9DA6BFFC4F9, 0xC875557D)
                        return err == nil and type(threads) == "number" and threads > 0
                    end,
                    session_key = function() return Live.action_generation end,
                    player_identity = function(pid)
                        local identity = Live.remote_identity(pid)
                        return identity and
                            (identity.rid .. ":" .. tostring(identity.cxn) .. ":" .. tostring(identity.local_id)) or
                            nil
                    end,
                    get_wanted = function(pid)
                        local value, raw, err = invoke_int_detail(H.GET_PLAYER_WANTED_LEVEL, pid)
                        if err == nil and type(raw) == "number" then return value end
                    end,
                    player_available = player_available,
                    local_player_id = local_player_id,
                    send_event = function(mask, args)
                        if not gta or type(gta.TriggerScriptEvent) ~= "function" then return false end
                        local ok, result = pcall(gta.TriggerScriptEvent, mask, args)
                        return ok and result ~= false
                    end,
                    on_stopped = function(pid, reason)
                        local feature = Live.never_wanted_toggle_refs[pid]
                        Live.never_wanted_toggle_refs[pid] = nil
                        if feature then pcall(function() if feature:IsToggled() then feature:Toggle(false) end end) end
                        log_info("Never Wanted: " .. tostring(reason))
                    end,
                })
            end
            return Live.player_never_wanted
        end

        add_player_toggle("never_wanted", "Never Wanted",
            "Continuously clears this player's wanted level while enabled in this session.",
            function(feature)
                local pid = feature_player_id(feature)
                if not feature:IsToggled() then
                    if Live.player_never_wanted then Live.player_never_wanted.Stop(pid) end
                    Live.never_wanted_toggle_refs[pid] = nil
                    return
                end
                Live.never_wanted_toggle_refs[pid] = feature
                local ok, why = Live.get_player_never_wanted().Start(pid)
                if not ok then
                    Live.never_wanted_toggle_refs[pid] = nil
                    pcall(function() feature:Toggle(false) end)
                    log_info("Never Wanted: " .. tostring(why))
                end
            end)
        Live.setpiece_toggle_refs = {}
        function Live.get_player_setpieces()
            if not Live.player_setpieces then
                local scene_deps = {}
                for key, value in pairs(deps) do scene_deps[key] = value end
                scene_deps.session_key = function() return Live.action_generation end
                scene_deps.request_entity_control = Live.request_entity_control
                scene_deps.on_effect_stopped = function(kind, pid, reason)
                    if kind == "fling_player" then toast("Fling Player: " .. tostring(reason), 5000, "info") end
                    local refs = Live.setpiece_toggle_refs[kind]
                    local feature = refs and refs[pid]
                    -- A queued stop from a previous generation must not turn
                    -- off a replacement that was enabled before events flushed.
                    if feature and not Live.player_setpieces.IsEnabled(kind, pid) then
                        refs[pid] = nil
                        pcall(function() if feature:IsToggled() then feature:Toggle(false) end end)
                    end
                end
                Live.player_setpieces = module_context.Modules.PlayerSetpieces.New(scene_deps)
            end
            return Live.player_setpieces
        end

        -- BEGIN TEAR GAS60 ADAPTER
        Live.tear_gas_armed = false
        Live.tear_gas_revision = 0
        Live.tear_gas_syncing = {}
        Live.tear_gas_requests = {}

        function Live.clear_tear_gas_toggle(feature)
            if feature == nil or Live.tear_gas_syncing[feature] then return false end
            Live.tear_gas_syncing[feature] = true
            local ok = pcall(function() if feature:IsToggled() then feature:Toggle(false) end end)
            Live.tear_gas_syncing[feature] = nil
            return ok
        end

        function Live.cancel_tear_gas_toggle(reason, disarm)
            local was_armed = Live.tear_gas_armed
            Live.tear_gas_armed = false
            Live.tear_gas_revision = Live.tear_gas_revision + 1
            local revision = Live.tear_gas_revision
            local refs = Live.setpiece_toggle_refs.tear_gas_trap or {}
            Live.setpiece_toggle_refs.tear_gas_trap = {}
            Live.tear_gas_requests = {}
            local ok = true
            if Live.player_setpieces then
                ok = pcall(Live.player_setpieces.Cancel, nil, reason or "Gas chamber trap stopped", "tear_gas_trap")
            end
            for pid, feature in pairs(refs) do
                local current_refs = Live.setpiece_toggle_refs.tear_gas_trap or {}
                local current_request = Live.tear_gas_requests[pid]
                if current_refs[pid] ~= feature and (not current_request or current_request.feature ~= feature) then
                    Live.clear_tear_gas_toggle(feature)
                end
            end
            if not disarm and revision == Live.tear_gas_revision then
                Live.tear_gas_armed = was_armed
            end
            return ok
        end

        function Live.rearm_tear_gas_toggle()
            Live.tear_gas_armed = false
            Live.tear_gas_revision = Live.tear_gas_revision + 1
            if not started or not lifecycle_token or lifecycle_token.alive ~= true
                or State.runtime_writes_suspended == true then
                Live.tear_gas_armed = false
                return false, "Player runtime is not ready for Gas chamber trap."
            end
            Live.tear_gas_armed = true
            return true
        end

        function Live.set_tear_gas_toggle(feature)
            if feature == nil or Live.tear_gas_syncing[feature] then return false end
            local ok, pid, enabled = pcall(function() return feature:GetPlayerIndex(), feature:IsToggled() end)
            if not ok or type(pid) ~= "number" or pid % 1 ~= 0 or pid < 0 or pid > 31
                or type(enabled) ~= "boolean" then
                Live.clear_tear_gas_toggle(feature)
                return false
            end
            local refs = Live.setpiece_toggle_refs.tear_gas_trap
            if not refs then
                refs = {}; Live.setpiece_toggle_refs.tear_gas_trap = refs
            end
            local requests = Live.tear_gas_requests
            if not enabled then
                local pending = requests[pid]
                if pending and pending.feature ~= feature then return true end
                if not pending and refs[pid] and refs[pid] ~= feature then return true end
                requests[pid] = nil
                refs[pid] = nil
                if not Live.player_setpieces then return true end
                local stopped, accepted = pcall(Live.player_setpieces.SetEnabled, "tear_gas_trap", pid, false)
                return stopped and accepted == true
            end
            if not Live.tear_gas_armed or not started or not lifecycle_token or lifecycle_token.alive ~= true
                or State.runtime_writes_suspended == true then
                Live.clear_tear_gas_toggle(feature)
                return false
            end
            -- Each player admission owns its own marker. A callback for another
            -- player does not revoke it, and an older callback cannot roll back
            -- a newer ON even when the UI reused the same feature object.
            local request = { feature = feature }
            local revision, token = Live.tear_gas_revision, lifecycle_token
            requests[pid] = request
            local function owns_request()
                return Live.tear_gas_requests == requests and requests[pid] == request
                    and Live.setpiece_toggle_refs.tear_gas_trap == refs
            end
            local function current_request()
                return owns_request() and revision == Live.tear_gas_revision
                    and lifecycle_token == token and token.alive == true and started
                    and Live.tear_gas_armed and State.runtime_writes_suspended ~= true
            end
            local function clear_obsolete_visual()
                local current_refs = Live.setpiece_toggle_refs.tear_gas_trap or {}
                local current = Live.tear_gas_requests[pid]
                if current_refs[pid] ~= feature and (not current or current.feature ~= feature) then
                    Live.clear_tear_gas_toggle(feature)
                end
            end
            local available, why = Live.selected_action_availability("tear_gas_trap", pid)
            if available ~= true or not current_request() then
                if owns_request() then requests[pid] = nil end
                clear_obsolete_visual()
                if why then log_info(tostring(why)) end
                return false
            end
            local loaded, engine = pcall(Live.get_player_setpieces)
            if not loaded or type(engine) ~= "table" or type(engine.SetEnabled) ~= "function"
                or type(engine.IsEnabled) ~= "function" then
                if owns_request() then requests[pid] = nil end
                clear_obsolete_visual()
                log_info("Gas chamber trap is unavailable: " .. tostring(engine))
                return false
            end
            if not current_request() then
                if owns_request() then requests[pid] = nil end
                clear_obsolete_visual()
                return false
            end
            local old = refs[pid]
            local called, accepted, detail = pcall(engine.SetEnabled, "tear_gas_trap", pid, true)
            local checked, enabled_now = pcall(engine.IsEnabled, "tear_gas_trap", pid)
            if not called or accepted ~= true or not checked or enabled_now ~= true or not current_request() then
                if owns_request() then
                    requests[pid] = nil
                    refs[pid] = nil
                    pcall(engine.SetEnabled, "tear_gas_trap", pid, false)
                end
                clear_obsolete_visual()
                local current_refs = Live.setpiece_toggle_refs.tear_gas_trap or {}
                if old and old ~= feature and current_refs[pid] ~= old then Live.clear_tear_gas_toggle(old) end
                if not called or (accepted ~= true and detail) then log_info(tostring(called and detail or accepted)) end
                return false
            end
            refs[pid] = feature
            if old and old ~= feature then Live.clear_tear_gas_toggle(old) end
            return true
        end

        -- END TEAR GAS60 ADAPTER

        for _, spec in ipairs({
            { "fling_player",        "Fling Player", "annoy niggas by pushin em up into the sky, vehicles and niggas finna see jesus's buttcrack" },
            { "hammer_of_god",       "The Hammer of God",                   "Drops a huge object from high above, with an impact shockwave and debris. Automatic cleanup follows." },
            { "demonic_possession",  "Vehicle possesion", "Goal-directed autopilot keeps the player in the driver seat, pursues random road or water destinations, and steers aircraft toward streamed structure surfaces. Requires vehicle control." },
            { "cargo_guillotine",    "Cargo Guillotine",                    "Drops a guided shipping container. Retrigger removes the previous container before replacing it." },
            { "kamikaze_jet",        "9/11 pilot in a nutshell", "lazer aiming for hitting the nigga" },
            { "ghost_vehicle",       "Car-rapist", "a car that will rape the nigga continuously lol" },
        }) do
            local key = spec[1]
            local sustained = key == "demonic_possession" or key == "ghost_vehicle"
            local register = sustained and add_player_toggle or add_player_button
            register(key, spec[2], spec[3], function(feature)
                local pid = feature_player_id(feature)
                local effects = Live.get_player_setpieces()
                if sustained and not feature:IsToggled() then
                    local refs = Live.setpiece_toggle_refs[key]
                    if refs then refs[pid] = nil end
                    effects.SetEnabled(key, pid, false)
                    return
                end
                local available, reason = Live.selected_action_availability(key, pid)
                if not available then
                    if sustained then pcall(function() feature:Toggle(false) end) end
                    log_info(tostring(reason)); return
                end
                if sustained then
                    Live.setpiece_toggle_refs[key] = Live.setpiece_toggle_refs[key] or {}
                    Live.setpiece_toggle_refs[key][pid] = feature
                end
                local ok, why
                if sustained then
                    ok, why = effects.SetEnabled(key, pid, true)
                else
                    ok, why = effects.Start(key, pid)
                end
                if not ok then
                    if sustained then
                        Live.setpiece_toggle_refs[key][pid] = nil
