                    for id = 0, 11 do
                        row.components[id] = {
                            drawable = int(1342 + 2 + slot * 13 + id),
                            texture = int(1616 + 2 +
                                slot * 13 + id)
                        }
                    end
                    for id = 0, 8 do
                        row.props[id] = {
                            drawable = int(1890 + 2 + slot * 10 + id),
                            texture = int(2101 + 2 + slot * 10 +
                                id)
