        function M.PrepareWear(api, selected, slot)
            if type(slot) ~= 'number' or slot % 1 ~= 0 or slot < 0 or slot > 19 then return nil, 'Invalid slot' end
            local fresh, err = M.Snapshot(api); if not fresh then return nil, err end
            local row = fresh.entries[slot + 1]
            if not same_context(selected, fresh) or not selected.entries[slot + 1]
                or identity(row) ~= identity(selected.entries[slot + 1]) then
                return nil, 'Saved outfit changed; refresh'
            end
            if not row.occupied then return nil, 'Selected outfit slot is empty' end
            if type(api.validate) ~= 'function' then return nil, 'Ped variation validator required' end
            for kind, values in pairs({ component = row.components, prop = row.props }) do
                for id, v in pairs(values) do
                    if not (kind == 'component' and v.drawable == -1) then
                        local ok, valid = pcall(api.validate, kind, id, v.drawable, v.texture, fresh)
                        if not ok or valid ~= true then return nil, 'Saved outfit is incompatible with the current ped' end
                    end
