            local ok, failure = pcall(function()
                -- Existing occupied record remains valid until both cache fields land.
                owned_write('string', name_address, desired_name)
                assert(api.string(name_address) == desired_name, 'Name readback failed')
                if operation == 'delete' then
                    owned_write('int', occupied_address, 0)
                    assert(api.int(occupied_address) == 0, 'Occupied readback failed')
                end
                local after, e = M.Snapshot(api)
                assert(after and same_context(fresh, after), e or 'Session changed during cache write')
                local actual = after.entries[slot + 1]
                local expected = {
                    slot = row.slot,
                    name = desired_name,
                    occupied = desired_occupied == 1,
                    components = row.components,
                    props = row.props,
                    flags = row.flags,
                    extra = row.extra
