                        texture =
                            native(0xE131A28626F81AB2, ctx.ped, id)
                    }
                end
                if row.props[0].drawable == 1 then row.props[0].drawable = -1 end
                local function restricted(kind, id, tag)
                    local v = (kind == 'component' and row.components or row.props)[id]
                    local hash = native(kind == 'component' and 0x0368B3A838070348 or 0x5D6160275CAEC8DD, ctx.ped, id,
                        v.drawable, v.texture)
                    local value = api.native_bool(0x341DE7ED1D2A1BFD, hash, api.hash(tag), kind == 'component' and 0 or 1)
                    assert(type(value) == 'boolean', 'Restriction native unavailable'); return value
                end
                if restricted('component', 1, 'SCUBA_GEAR') then row.components[1] = { drawable = 0, texture = 0 } end
                if restricted('component', 8, 'SCUBA_GEAR') then
                    row.components[8] = {
                        drawable = ctx.model == 1885233650 and
                            15 or 3,
                        texture = 0
                    }
                end
                if restricted('prop', 1, 'SCUBA_GEAR') then row.props[1].drawable = -1 end
                row.components[0].drawable = -1
                if not restricted('component', 2, 'NIGHT_VISION') then row.components[2].drawable = -1 end
                local extra = stat(1759)
                local item = native(0x10144267DD22866C, ctx.model == 1885233650 and 3 or 4, -1, extra)
                if item ~= -1 and owned(129 + item) then row.extra = extra end
                for i, index in ipairs({ 14, 15, 16, 17, 71, 72 }) do row.flags[FLAGS[i]] = owned(index) and 1 or 0 end
                assert(type(api.validate) == 'function', 'Ped variation validator required')
                for kind, values in pairs({ component = row.components, prop = row.props }) do
                    for id, v in pairs(values) do
                        if not (kind == 'component' and v.drawable == -1) then
                            assert(api.validate(kind, id, v.drawable, v.texture, ctx) == true,
