    end)()
    -- END GTA WARDROBE BACKEND

    function OutfitLive.gta_adapter(editor)
        local api = {}
        -- Player compatibility historically omits FileMgr; the documented host
        -- binding remains available through bootstrap Raw (and the VFS global).
        local files = deps.FileMgr or (module_context and module_context.Raw and module_context.Raw.FileMgr) or FileMgr
        function api.context()
            if OutfitLive.read_bool(0x9DE624D2FC4B603F) ~= true
                or OutfitLive.read_bool(0x68049AEFF83D8F0A) ~= false
                or not OutfitLive.valid(editor) or not script_global or not script_global.AreValid
                or not script_global.AreValid() then
                return nil
            end
            local t = editor.target
            local character = t.character == 'MP0' and 0 or t.character == 'MP1' and 1 or nil
            if character == nil then return nil end
            return {
                online = true,
                transition = false,
                character = character,
                ped = t.ped,
                model = t.model,
                epoch = t
                    .epoch
            }
        end

        function api.int(address) return script_global.GetInt(address) end

        function api.string(address) return script_global.GetString(address) end

        function api.write_int(address, value)
            assert(api.context(), 'Character changed before wardrobe write')
            script_global.SetInt(address, value)
        end

        function api.write_string(address, value)
            assert(api.context(), 'Character changed before wardrobe write')
            script_global.SetString(address, value)
        end

        api.native_int = OutfitLive.read_int
        api.native_bool = OutfitLive.read_bool
        api.hash = function(text) return utils.Joaat(text) end
        function api.stat_int(index, character)
            local hash = OutfitLive.read_int(0xD69CE161FE614531, 0, index, character)
            if not hash or not memory or type(memory.AllocInt) ~= 'function'
                or type(memory.ReadInt) ~= 'function' or type(memory.Free) ~= 'function' then
                return nil
            end
            local allocated, ptr = pcall(memory.AllocInt)
            if not allocated or type(ptr) ~= 'number' or ptr <= 0 then return nil end
            local ok, value = pcall(function()
                if OutfitLive.read_bool(0x767FBC2AC802EF3D, hash, ptr, -1) ~= true then return nil end
                return memory.ReadInt(ptr)
            end)
            pcall(memory.Free, ptr)
            return ok and value or nil
        end

        function api.validate(kind, id, drawable, texture, ctx)
            if not api.context() or type(drawable) ~= 'number' or type(texture) ~= 'number'
                or drawable % 1 ~= 0 or texture % 1 ~= 0 then
                return false
            end
            if kind == 'prop' and drawable == -1 then return texture >= -1 end
            local component = kind == 'component'
            if drawable < 0 or texture < 0 then return false end
            local count = OutfitLive.read_int(component and H.GET_NUMBER_OF_PED_DRAWABLE_VARIATIONS
                or H.GET_NUMBER_OF_PED_PROP_DRAWABLE_VARIATIONS, ctx.ped, id)
            if not count or drawable >= count then return false end
            local textures = OutfitLive.read_int(component and H.GET_NUMBER_OF_PED_TEXTURE_VARIATIONS
                or H.GET_NUMBER_OF_PED_PROP_TEXTURE_VARIATIONS, ctx.ped, id, drawable)
            if not textures or texture >= textures then return false end
            return not component or OutfitLive.read_bool(0xE825F6B6CEA7671D, ctx.ped, id, drawable, texture) == true
        end

        function api.backup(snapshot, slot, operation)
            if not api.context() then return false, 'character context changed' end
            if not files or not files.WriteFileContent or not files.ReadFileContent
                or not files.DoesFileExist then
                return false, 'file access unavailable'
            end
            if type(files.GetMenuRootPath) ~= 'function' then return false, 'menu directory unavailable' end
            local got, root = pcall(files.GetMenuRootPath)
            if not got or type(root) ~= 'string' or root == '' then return false, 'menu directory unavailable' end
            local directory = root .. '\\Lua\\CScript'
            -- Host CreateDir returns false for an already existing directory.
            -- Establish existence independently; backup readback remains mandatory.
            local checked, exists = pcall(files.DoesFileExist, directory)
            if not checked or type(exists) ~= 'boolean' then return false, 'directory check failed' end
            if not exists then
                if type(files.CreateDir) ~= 'function' then return false, 'directory creation unavailable' end
                local created = pcall(files.CreateDir, directory)
                local rechecked, present = pcall(files.DoesFileExist, directory)
                if not created or not rechecked or present ~= true then return false, 'directory could not be created' end
            end
            local source = directory .. '\\outfits.txt'
            local function quote(s) return '"' .. tostring(s):gsub('\\', '\\\\'):gsub('"', '\\"') .. '"' end
            local rows = {}
            for _, row in ipairs(snapshot.entries) do
                local components, props, flags = {}, {}, {}
                for id = 0, 11 do
                    local v = row.components[id]; components[#components + 1] = ('"%d":[%d,%d]'):format(id, v.drawable,
                        v.texture)
                end
                for id = 0, 8 do
                    local v = row.props[id]; props[#props + 1] = ('"%d":[%d,%d]'):format(id, v.drawable, v.texture)
                end
                for _, offset in ipairs({ 2334, 2356, 2378, 2400, 2422, 2444 }) do
                    flags[#flags + 1] = ('"%d":%d')
                        :format(offset, row.flags[offset])
                end
                rows[#rows + 1] = ('{"slot":%d,"name":%s,"occupied":%s,"components":{%s},"props":{%s},"flags":{%s},"extra":%d}')
                    :format(row.slot, quote(row.name), tostring(row.occupied), table.concat(components, ','),
                        table.concat(props, ','), table.concat(flags, ','), row.extra)
            end
            local bytes = ('{"format":"CScript GTA wardrobe backup 1","character":%d,"model":%d,"slot":%d,"operation":%s,"entries":[%s]}')
                :format(snapshot.character, snapshot.model, slot, quote(operation), table.concat(rows, ','))
            editor.gta_backup_serial = (editor.gta_backup_serial or 0) + 1
            local path = source .. ('.gta-MP%d-%d-%d-%d.json'):format(snapshot.character,
                tonumber(os and os.time and os.time()) or 0, now_ms(), editor.gta_backup_serial)
            local ok, existing = pcall(files.DoesFileExist, path)
            if not ok or type(existing) ~= 'boolean' then return false, 'backup filename check failed' end
            if existing then return false, 'backup filename already exists' end
            local wrote, result = pcall(files.WriteFileContent, path, bytes, false)
            local read, actual = pcall(files.ReadFileContent, path)
            if not wrote or result ~= true then return false, 'backup write failed' end
            if not read or actual ~= bytes then return false, 'backup readback did not match' end
            if not api.context() then return false, 'character context changed' end
            editor.gta_last_backup = path
            return true
        end

        return api
    end

    function OutfitLive.gta_refresh(editor)
        local ok, snapshot, err = pcall(OutfitLive.GTA.Snapshot, OutfitLive.gta_adapter(editor))
        editor.gta_snapshot = ok and snapshot or nil
        editor.gta_error = not ok and tostring(snapshot) or err
        editor.gta_next_poll = now_ms() + 3000
        return editor.gta_snapshot
    end

    function OutfitLive.gta_action(editor, request)
        if not request or not OutfitLive.same(request.target, editor.target) or not OutfitLive.valid(editor) then
            editor.status = 'Wardrobe action cancelled: character changed'; return
        end
        if request.kind == 'gta_refresh' then
            OutfitLive.gta_refresh(editor); return
        end
        if not request.gta_snapshot or request.revision ~= editor.revision or next(editor.edits or {}) ~= nil
            or (tonumber(editor.failed_revision) or 0) > 0 then
            editor.status = 'Wardrobe action cancelled: outfit changed or an edit was not verified'; return
        end
        local api = OutfitLive.gta_adapter(editor)
        if request.kind == 'gta_wear' then
            local row, why = OutfitLive.GTA.PrepareWear(api, request.gta_snapshot, request.gta_slot)
            if not row then
                editor.status = tostring(why); return
            end
            -- Apply the complete supported clothing/prop record through the same
            -- validated mutation owner as live editing. Preserve face/hair sentinels.
            for id = 0, 11 do
                local v = row.components[id]
                if v.drawable >= 0 then
                    OutfitLive.queue({ kind = 'component', id = id },
                        { drawable = v.drawable, texture = v.texture })
                end
            end
            for id = 0, 8 do
                local v = row.props[id]
                OutfitLive.queue({ kind = 'prop', id = id },
                    { drawable = v.drawable, texture = v.drawable < 0 and 0 or v.texture })
            end
            editor.gta_wear_name = row.name
            return
        end
        local operation = request.kind == 'gta_rename' and 'rename' or request.kind == 'gta_delete' and 'delete' or
            'save'
        if request.kind == 'gta_confirm' then
            local confirm = request.confirmation
            local current = capture_outfit(editor.target.ped, 'Current Outfit')
            if not confirm or confirm ~= editor.confirmation or confirm.gta_slot ~= editor.gta_selected
                or confirm.revision ~= editor.revision or (confirm.operation == 'save' and confirm.name ~= editor.gta_name)
                or not OutfitLive.snap_equal(current, confirm.snapshot) then
                editor.confirmation = nil; editor.status = 'Confirmation expired: destination or outfit changed'; return
            end
            request = confirm; operation = confirm.operation
        else
            local row = request.gta_snapshot.entries[request.gta_slot + 1]
            if not row then
                editor.status = 'Select a GTA outfit slot'; return
            end
            if operation == 'delete' or (operation == 'save' and row.occupied) then
                request.operation = operation
                request.snapshot = capture_outfit(editor.target.ped, 'Current Outfit')
                if not request.snapshot or request.snapshot.complete == false then
                    editor.status = 'Current outfit could not be verified'; return
                end
                request.label = (operation == 'delete' and 'Delete' or 'Overwrite') ..
                    ' GTA slot ' .. (request.gta_slot + 1) .. ' / ' .. row.name .. '?'
                editor.confirmation = request
                return
            end
        end
        local result, err
        if operation == 'save' then
            result, err = OutfitLive.GTA.SaveCache(api, request.gta_snapshot, request.gta_slot, request.name)
        else
            result, err = OutfitLive.GTA.ChangeCache(api, request.gta_snapshot, request.gta_slot, operation, request
                .name)
        end
        editor.confirmation = nil
        editor.status = result and 'Updated in GTA; pending game save' or tostring(err)
        OutfitLive.gta_refresh(editor)
    end

    function OutfitLive.source_bytes()
        local path = outfit_storage_path()
        if not path or not FileMgr or type(FileMgr.DoesFileExist) ~= "function"
            or type(FileMgr.ReadFileContent) ~= "function" then
            return false, nil, "Local file access unavailable"
        end
        local ok, exists = pcall(FileMgr.DoesFileExist, path)
        if not ok then return false, nil, "Could not check local preset file" end
        if not exists then return true, nil end
        local read, bytes = pcall(FileMgr.ReadFileContent, path)
        if not read or type(bytes) ~= "string" then return false, nil, "Local presets could not be read" end
        return true, bytes
    end

    function OutfitLive.backup(editor)
        if editor.storage_error then return false, editor.storage_error end
        local ok, bytes, err = OutfitLive.source_bytes()
        if not ok or bytes ~= editor.storage_bytes then
            return false,
                err or "Local presets changed elsewhere; reopen Saved"
        end
        if bytes == nil then return true, nil end
        local path = outfit_storage_path() ..
            ".studio-backup-" .. tostring(editor.next_action_serial) .. "-" .. tostring(now_ms()) .. ".txt"
        local wrote, result = pcall(FileMgr.WriteFileContent, path, bytes, false)
        local read, actual = pcall(FileMgr.ReadFileContent, path)
        if not wrote or result == false or not read or actual ~= bytes then
            return false,
                "Recoverable backup could not be verified"
        end
        editor.last_backup_path = path
        return true, path
    end

    function OutfitLive.snapshot_changes(editor, snapshot, no_undo)
        if not snapshot or snapshot.model ~= editor.target.model then return false end
        for _, category in ipairs(OUTFIT_CATEGORIES) do
            local values = category.kind == "component" and snapshot.components or snapshot.props
            local value = values and values[category.id]
            -- Saved wardrobe composition does not carry head-blend, overlays, hair colour or tattoos.
            if value and not (category.kind == "component" and (category.id == 0 or category.id == 2)) then
                OutfitLive.queue(category, OutfitLive.copy(value), nil, no_undo)
            end
        end
        return true
    end

    function OutfitLive.persist(editor, request, kind, snapshot)
        if not OutfitLive.same(request.target, editor.target) or not OutfitLive.valid(editor)
            or request.revision ~= (tonumber(editor.revision) or 0) then
            editor.status = "Save cancelled: character or edit changed"; return false
        end
        local ok, bytes, err = OutfitLive.source_bytes()
        if not ok or bytes ~= editor.storage_bytes then
            editor.status = err or "Save cancelled: local presets changed elsewhere"
            editor.loaded = false; return false
        end
        local slots = clone_outfit_slots(editor.slots)
        local slot = slots[request.slot]
        if not slot then
            editor.status = "Save cancelled: local destination changed"; return false
        end
        local destination = request.slot
        if kind == "add_slot" then
            destination = #slots + 1; slots[destination] = empty_outfit_slot(destination)
        elseif kind == "delete_slot" then
            slots[request.slot] = empty_outfit_slot(request.slot)
        elseif kind == "save_slot" then
            if not snapshot or snapshot.complete == false then
                editor.status = "Save failed: outfit snapshot is incomplete"; return false
            end
            local saved = clone_outfit(snapshot)
            saved.name = sanitize_outfit_name(request.name)
            saved.created = slot.created ~= "" and slot.created or outfit_timestamp()
            saved.modified = outfit_timestamp(); saved.favorite = slot.favorite
            slots[request.slot] = saved
        elseif kind == "rename_slot" then
            slot.name = sanitize_outfit_name(request.name); slot.modified = outfit_timestamp()
        elseif kind == "favorite_slot" then
            slot.favorite = not slot.favorite; slot.modified = outfit_timestamp()
        elseif kind == "duplicate_slot" then
            if not outfit_slot_has_data(slot) then
                editor.status = "Selected local preset is empty"; return false
            end
            local target
            for index, value in ipairs(slots) do
                if index ~= request.slot and not outfit_slot_has_data(value) and (tonumber(value.model) or 0) == 0
                    and tostring(value.name or "") == "" and tostring(value.created or "") == ""
                    and tostring(value.modified or "") == "" and not value.favorite then
                    target = index; break
                end
            end
            destination = target or (#slots + 1)
            slots[destination] = clone_outfit(slot)
            local name = tostring(slot.name or "")
            slots[destination].name = name ~= "" and ("Copy of " .. name):sub(1, 40) or ""
            slots[destination].created = outfit_timestamp(); slots[destination].modified = slots[destination].created
        else
            editor.status = "Unknown local preset action"; return false
        end
        local wrote, why = save_outfit_slots(slots)
        if wrote then
            editor.slots = slots; editor.selected_slot = destination; editor.confirmation = nil
            editor.rename_buffer = tostring(slots[destination].name or ""); editor.rename_buffer_slot = destination
            if kind == "add_slot" or kind == "duplicate_slot" then editor.slot_filter = "" end
            editor.status = kind == "add_slot" and "Empty slot added" or "Saved"
            return true
        end
        editor.status = "Save failed: " .. tostring(why); return false
    end

    local function outfit_editor_tick(now, ped)
        local editor = State.outfit
        if OutfitLive.close_tick(now) then return end
        if editor.last_editor_tick_ms == now and not OutfitLive.input_requested(editor) then return end
        editor.last_editor_tick_ms = now
        if editor.visible_ping then
            editor.visible_ping = false; editor.last_visible_ms = now
            if not editor.studio_open then
                editor.studio_open = true; editor.auto_rotate = false
                editor.reopen_pending = true
                editor.preview_suppressed, editor.preview_requested = false, true
                editor.camera_retry_ms = 0
            end
            load_outfit_slots()
        end
        if not editor.studio_open and not editor.pending_action and next(editor.edits or {}) == nil
            and (tonumber(editor.preview_cam) or 0) == 0 then
            return
        end
        local identity = OutfitLive.identity(ped)
        if not OutfitLive.same(editor.target, identity) then
            stop_outfit_preview("subject changed")
            OutfitLive.invalidate(identity and "Editing current outfit" or "Character unavailable")
            if identity then
                identity.epoch = editor.live_epoch
                local current = capture_outfit(ped, "Current Outfit")
                if current then
                    editor.target = identity; editor.current = current; editor.verified = clone_outfit(current)
                    editor.baseline = clone_outfit(current); editor.selected_category = 1
                    local heading = invoke_float_detail(H.GET_ENTITY_HEADING, ped)
                    editor.front_yaw = ((tonumber(heading) or 0) + 180) % 360
                    editor.current_yaw, editor.target_yaw = editor.front_yaw, editor.front_yaw
                    editor.preview_suppressed = false; editor.next_poll_ms = 0
                    editor.reopen_pending = true
                end
            end
        elseif editor.reopen_pending and editor.target then
            -- Keep previous edits applied while establishing a fresh open-session undo baseline.
            local current = capture_outfit(ped, "Current Outfit")
            if current then
                editor.current = current; editor.verified = clone_outfit(current); editor.baseline = clone_outfit(
                    current)
                editor.undo, editor.touched = {}, {}
            end
        end
        if editor.reopen_pending and editor.target then
            -- Manual mode always opens at the character's front. Automatic mode
            -- frames the current category without requiring a view-button click.
            local heading = invoke_float_detail(H.GET_ENTITY_HEADING, ped)
            editor.front_yaw = ((tonumber(heading) or 0) + 180) % 360
            refresh_outfit_framing_metrics(editor, ped)
            preview_reset_view(editor)
            editor.current_yaw, editor.target_yaw = editor.front_yaw, editor.front_yaw
            editor.transition = nil
            preview_suggest_category(editor, OUTFIT_CATEGORIES[editor.selected_category])
            editor.more_actions = false
        end
        editor.reopen_pending = false
        if not editor.target then return end
        if editor.gta_visible_ping then
            editor.gta_visible_ping = nil
            if not editor.gta_snapshot or now >= (editor.gta_next_poll or 0) then OutfitLive.gta_refresh(editor) end
        end
        OutfitLive.drain(editor)
        local request = editor.pending_action
        editor.pending_action = nil
        local action = request and request.kind
        if request and not OutfitLive.same(request.target, editor.target) then
            editor.status = "Action cancelled: character changed"; action = nil
        end
        if request and (action == "prepare_save" or action == "prepare_delete") and request.revision ~= editor.revision then
            editor.status = "Save cancelled: edit changed after request"; action = nil
        end
        editor.queue_group = request and request.serial or nil
        if action and action:sub(1, 4) == 'gta_' then
            local ok, err = pcall(OutfitLive.gta_action, editor, request)
            if not ok then
                editor.status = 'Wardrobe action stopped: ' .. tostring(err); editor.confirmation = nil
            end
        elseif action == "restore_preview" then
            editor.preview_suppressed, editor.preview_requested = false, true
            editor.preview_sync_attempts, editor.preview_sync_due = 0, 0
            editor.camera_retry_ms = 0; editor.camera_status = ''
        elseif action == "close" then
            editor.preview_suppressed, editor.preview_requested = true, false
            editor.auto_rotate = false; stop_outfit_preview("view closed")
        elseif action == "reset_category" then
            local category = OUTFIT_CATEGORIES[request.category or editor.selected_category]
            local values = category.kind == "component" and editor.baseline.components or editor.baseline.props
            if values[category.id] then OutfitLive.queue(category, OutfitLive.copy(values[category.id])) end
        elseif action == "randomize_all" then
            refresh_outfit_limits(ped)
            for _, category in ipairs(OUTFIT_CATEGORIES) do OutfitLive.randomize(editor, category) end
        elseif action == "randomize_category" then
            refresh_outfit_limits(ped)
            OutfitLive.randomize(editor, OUTFIT_CATEGORIES[request.category or editor.selected_category])
        elseif action == "randomize_items" then
            refresh_outfit_limits(ped)
            for _, category in ipairs(OUTFIT_CATEGORIES) do
                if not (category.kind == "component" and (category.id == 0 or category.id == 2)) then
                    local count = tonumber((category.kind == "component" and editor.component_counts or editor.prop_counts)
                        [category.id]) or 0
                    if count > 0 then
                        OutfitLive.queue(category,
                            { drawable = math.random(category.kind == "component" and 0 or -1, count - 1), texture = 0 })
                    end
                end
            end
        elseif action == "undo" then
            local change = table.remove(editor.undo or {})
            if change and OutfitLive.same(change.target, editor.target) then
                for _, part in ipairs(change.changes or { change }) do
                    OutfitLive.queue(part.category, part.before, part.after, true)
                end
            else
                editor.status = "No verified change to undo"
            end
        elseif action == "revert" then
            for _, touched in pairs(editor.touched or {}) do
                local category = touched.category
                local values = category.kind == "component" and editor.baseline.components or editor.baseline.props
                if values[category.id] then
                    local patch = {}
                    for field in pairs(touched.fields) do patch[field] = values[category.id][field] end
                    OutfitLive.queue(category, patch, nil, true)
                end
            end
        elseif action == "load_slot" then
            if not outfit_slot_has_data(request.outfit) then
                editor.status = "Selected local preset is empty"
            elseif not OutfitLive.snapshot_changes(editor, request.outfit) then
                editor.status = "Preset belongs to another or unknown model; current character preserved"
            end
        elseif action == "prepare_save" or action == "prepare_delete" then
            if next(editor.edits or {}) ~= nil or (tonumber(editor.failed_revision) or 0) > 0 then
                editor.status = "Save stopped: an edit was not verified"
            else
                local snapshot = capture_outfit(ped, "Current Outfit")
                local occupied = outfit_slot_has_data(editor.slots[request.slot])
                local backed, backup = OutfitLive.backup(editor)
                if not backed then
                    editor.status = tostring(backup)
                elseif not snapshot or snapshot.complete == false or not OutfitLive.valid(editor) then
                    editor.status = "Save failed: current outfit could not be captured completely"
                elseif action == "prepare_save" and not occupied then
                    OutfitLive.persist(editor, request, "save_slot", snapshot)
                else
                    editor.confirmation = {
                        kind = action == "prepare_delete" and "delete_slot" or "save_slot",
                        slot = request.slot,
                        name = request.name,
                        target = editor.target,
                        revision = editor.revision,
                        snapshot = snapshot,
                        bytes = editor.storage_bytes,
                        backup = backup,
                        label = (action == "prepare_delete" and "Clear" or "Overwrite") .. " Local slot " .. request
                            .slot
                            .. "  /  " .. tostring(editor.slots[request.slot].name) .. "? A verified backup is saved."
                    }
                end
            end
        elseif action == "confirm_persist" then
            local confirm = request.confirmation
            local current = capture_outfit(ped, "Current Outfit")
            if not confirm or confirm ~= editor.confirmation or confirm.slot ~= editor.selected_slot
                or confirm.revision ~= editor.revision or confirm.bytes ~= editor.storage_bytes
                or not OutfitLive.same(confirm.target, editor.target) or not OutfitLive.snap_equal(current, confirm.snapshot) then
                editor.confirmation = nil; editor.status = "Confirmation expired: destination or outfit changed"
            else
                OutfitLive.persist(editor, confirm, confirm.kind, current)
            end
        elseif action == "add_slot" or action == "rename_slot" or action == "duplicate_slot" or action == "favorite_slot" then
            local backed, why = OutfitLive.backup(editor)
            if backed then
                OutfitLive.persist(editor, request, action)
            else
                editor.status = tostring(why)
            end
        end
        editor.queue_group = nil
        OutfitLive.drain(editor)
        if editor.gta_wear_name then
            if (tonumber(editor.failed_revision) or 0) == 0 and next(editor.edits or {}) == nil then
                editor.status = 'Outfit clothing applied: ' .. editor.gta_wear_name
            end
            editor.gta_wear_name = nil
        end
        -- Only an item's own texture range depends on that changed item.
        -- Full wardrobe discovery remains a modest external-change poll.
        for key, category in pairs(editor.dirty_limits or {}) do
            refresh_outfit_limits(ped, category)
            editor.dirty_limits[key] = nil
        end
        if now >= (tonumber(editor.next_poll_ms) or 0) and OutfitLive.valid(editor) then
            local current = capture_outfit(ped, "Current Outfit")
            if current then
                if editor.confirmation and not OutfitLive.snap_equal(current, editor.confirmation.snapshot) then editor.confirmation = nil end
                editor.current = current; editor.verified = clone_outfit(current)
                OutfitLive.overlay_pending(editor)
                refresh_outfit_limits(ped)
                local heading = invoke_float_detail(H.GET_ENTITY_HEADING, ped)
                if type(heading) == "number" and (tonumber(editor.preview_ped) or 0) == 0 then
                    editor.front_yaw = (heading + 180) %
                        360
                end
            end
            editor.next_poll_ms = now + 750
        end
        if not editor.cleanup_pending and not OutfitLive.preview_sync(editor) then
            editor.preview_suppressed, editor.preview_requested = true, false
            stop_outfit_preview("preview synchronization failed")
            editor.camera_status = "Preview could not match the real outfit; live edits are kept"
        end
        local visibility, visible = component_call("studio_workspace_visible", "outfit")
        local hidden = visibility and type(visible) == "boolean" and not visible
            or (not visibility or type(visible) ~= "boolean") and now - (tonumber(editor.last_visible_ms) or -100000) >
            650
        if editor.cleanup_pending or editor.preview_suppressed then stop_outfit_preview("view closed") end
        if hidden then
            OutfitLive.request_close("studio hidden")
            OutfitLive.close_tick(now)
            editor.confirmation = nil
        elseif editor.studio_open then
            if not OutfitLive.safety(true) then
                stop_outfit_preview("safety unavailable")
                editor.camera_status = "View paused: player protection unavailable"
            elseif editor.preview_requested and not editor.preview_suppressed and editor.current
                and (tonumber(editor.preview_cam) or 0) == 0 then
                start_outfit_preview()
            end
        end
    end

    function OutfitLive.input_tick(now, ped)
        if OutfitLive.input_requested(State.outfit) then outfit_editor_tick(now, ped) end
    end

    local function fast_tick(now, ped)
        if Live.vehicle_chaos then Live.vehicle_chaos.TickCleanup() end
        Live.process_super_melee_owner_returns(tonumber(now) or now_ms())
        local pid = local_player_id()
        ped = tonumber(ped) or local_ped()
        outfit_editor_tick(tonumber(now) or now_ms(), ped)
        if not entity_exists(ped) then return end

        Live.protection_tick()

        if is_on("unlimited_sprint") then invoke_void(H.RESTORE_PLAYER_STAMINA, pid, 1.0) end
        -- No second action-mode re-entry reset on the 250 ms fast tick.
        -- Core runtime owns its single early frame call instead.
        Live.apply_movement_boosts(pid)
    end

    local function slow_tick(_, ped)
        ped = tonumber(ped) or local_ped()
        if not entity_exists(ped) then return end
        if is_on("auto_armour") and invoke_int(H.GET_PED_ARMOUR, ped) < slider_int("armour_threshold", 50) then
            invoke_void(H.SET_PED_ARMOUR, ped, 100)
        end
        if is_on("auto_clean") then invoke_void(H.CLEAR_PED_BLOOD_DAMAGE, ped) end
        if is_on("auto_dry") then invoke_void(H.CLEAR_PED_WETNESS, ped) end
    end

    local function panic_reset()
        Live.stop_auto_tp("Panic reset")
        Live.cancel_tear_gas_toggle("Panic reset", false)
        Live.cancel_baller_toggle("Panic reset", false)
        Live.scripted_screen_repeats.Reset("Panic reset")
        Live.scripted_screens.Cancel("Panic reset")
        Live.local_exit.Cancel(nil, "Panic reset")
        Live.bst46_cancel()
        Live.remote_guard_cancel("Panic reset; restoration pending.", false)
        fast_respawn_delay.Request(false)
        set_toggle("session_keep_players_outside", false)
        Live.property_exit_guard.Reset()
        if Live.selected_effects then Live.selected_effects.Cancel(nil, "panic reset") end
        if Live.player_setpieces then Live.player_setpieces.Cancel(nil, "panic reset") end
        if Live.player_bounty then Live.player_bounty.Reset("panic reset") end
        if Live.player_never_wanted then Live.player_never_wanted.Reset("panic reset") end
        Live.aim_cancel("Aim selection cancelled by panic reset.")
        Live.lester_ride.Cancel(nil, "panic reset")
        if Live.vehicle_chaos then Live.vehicle_chaos.Cancel() end
        Live.restore_remote_vehicle_protection()
        Live.qol.reset("panic reset")
        Live.speed_preset.pending = false
        suppression_generation = suppression_generation + 1
        -- Direct ownership teardown is required during unload because feature
        -- callbacks are already disabled before Module.Restore is invoked.
        Messiah.Restore("panic reset", true)
        if State.remote_godmode then State.remote_godmode.active = false end
        if State.remote_passive and State.remote_passive.active == true then
            finish_remote_passive_clear("panic reset", true)
        end
        if State.remote_ghost and State.remote_ghost.active == true then
            finish_remote_ghost_clear("panic reset", true)
        end
        if State.enter_interior and State.enter_interior.active == true then
            finish_enter_interior("panic reset", false, true)
        end
        if State.join_organization and State.join_organization.active == true then
            Live.finish_join_organization("panic reset", false, true)
        end
        Live.retry_join_cleanup(now_ms(), true)
        if State.kick_interior and State.kick_interior.active == true then
            finish_kick_from_interior("panic reset", false, true)
        end
        Live.finish_kick_organization("panic reset", false, true)
        local crippled = {}
        for player_id in pairs(State.cripple.targets) do crippled[#crippled + 1] = player_id end
        for _, player_id in ipairs(crippled) do
            restore_cripple_target(player_id, "panic reset", true)
            if type(feature_mgr.GetFeature) == "function" then
                local ok, feature = pcall(feature_mgr.GetFeature, player_feature_id("cripple"), player_id)
                if ok and feature and type(feature.IsToggled) == "function"
                    and type(feature.Toggle) == "function" then
                    pcall(function() if feature:IsToggled() then feature:Toggle(false) end end)
                end
            end
        end
        reset_owned_toggles()
        Live.cleanup_super_melee("panic reset")
        local super_melee = feature_ref("super_melee")
        if super_melee and type(super_melee.SetIntValue) == "function" then
            pcall(function() super_melee:SetIntValue(0) end)
        end
        stop_spectating(true)
        stop_outfit_preview("panic reset")
        OutfitLive.invalidate("Studio reset")
        State.outfit.preview_requested = false
        State.outfit.preview_dirty = false
        State.outfit.preview_restart = false
        State.outfit.pending_action = nil
        State.outfit.apply_model_confirmation = nil
        State.outfit.auto_rotate = false
        State.outfit.studio_open = false
        restore_player()
    end

    local function session_change_cleanup()
        Live.rrer_shield_reset()
        Live.stop_auto_tp("Session changed")
        Live.cancel_tear_gas_toggle("Session changed", false)
        Live.cancel_baller_toggle("Session changed", false)
        Live.scripted_screen_repeats.Reset("Session changed")
        Live.scripted_screens.Cancel("Session changed")
        Live.local_exit.Cancel(nil, "Session changed")
        Live.bst46_pause("session transition", false)
        Live.bst46.yielded = {}
        Live.remote_guard_cancel("Session changed; restoration pending.", false)
        Live.remote_guard_tick(now_ms(), false)
        fast_respawn_host.Invalidate()
        fast_respawn_delay.Request(false)
        Live.property_exit_guard.Reset()
        Messiah.EndSession()
        if Live.selected_effects then Live.selected_effects.Cancel(nil, "session changed") end
        if Live.player_setpieces then Live.player_setpieces.Cancel(nil, "session changed") end
        if Live.player_bounty then Live.player_bounty.Reset("session changed") end
        if Live.player_never_wanted then Live.player_never_wanted.Reset("session changed") end
        Live.clear_protection(true)
        Live.restore_movement_boosts(true)
        Live.restore_ragdoll_suppression(true)
        Live.aim_cancel("Aim selection cancelled by session change.")
        Live.lester_ride.Cancel(nil, "session changed")
        if Live.vehicle_chaos then Live.vehicle_chaos.Cancel() end
        Live.restore_super_melee_damage("session transition")
        Live.action_generation = Live.action_generation + 1
        Live.ghost_session_changed()
        -- Abandon, do not restore, a prerequisite belonging to the old VM.
        Live.finish_join_organization("session changed", false, true)
        Live.retry_join_cleanup(now_ms(), true)
        if State.kick_organization then State.kick_organization.active = false end
        Live.qol.reset("session transition")
        Live.speed_preset.pending = false
        OutfitLive.invalidate("Session changed")
        suppression_generation = suppression_generation + 1
        -- A session transition invalidates entity handles and temporary runtime
        -- operations, but it must not erase the user's enabled Player settings.

        if State.remote_godmode then
            State.remote_godmode.active = false
        end

        if State.remote_ghost then
            State.remote_ghost.active = false
        end

        if State.remote_passive then
            State.remote_passive.active = false
        end

        if State.enter_interior then
            State.enter_interior.active = false
        end

        if State.kick_interior then
            State.kick_interior.active = false
        end

        State.cripple.targets = {}

        stop_spectating(true)

        stop_outfit_preview(
            "session transition"
        )

        State.outfit.preview_requested = false
        State.outfit.preview_dirty = false
        State.outfit.preview_restart = false
        State.outfit.pending_action = nil
        State.outfit.apply_model_confirmation = nil
        State.outfit.auto_rotate = false
        State.outfit.studio_open = false

        -- Cancel force work; return debts use independent instance/connection
        -- checks and remain available for gameplay-thread cleanup after rearm.
        Live.quiesce_super_melee("session transition")
        State.super_melee.proofs = {}
        State.super_melee.scan_cursors = {}
        State.super_melee.generation = (tonumber(State.super_melee.generation) or 0) + 1
        State.super_melee.prestrike, State.super_melee.prestrike_ms = nil, nil
        State.super_melee.rendered_cache, State.super_melee.rendered_cache_ms = nil, nil

        State.super_melee.swing.active = false
        State.super_melee.swing.armed = true
        State.super_melee.swing.consumed = false
        State.super_melee.swing.started_ms = 0
        State.super_melee.swing.impact_until_ms = 0
        State.super_melee.swing.direct_target = 0
        State.super_melee.swing.last_resolved_target = 0
        State.super_melee.swing.action_was_performing = false
        State.super_melee.swing.observations = {}
        State.super_melee.swing.baseline_candidates = 0
        State.super_melee.swing.prestrike_candidates = 0

        State.super_melee.last_scan_ms = -100000
        State.super_melee.last_target = 0
        State.super_melee.last_outcome =
        "session transition"

        State.godmode_ped = 0
        State.godmode_last_check = -100000

        State.action_mode_ped = 0
        State.action_mode_recovery_until = 0

        State.action_mode = {
            phase = "idle",
            last_reason = "session transition",
            using = false,
            melee = false,
            shooting = false,
            aiming = false,
            combat = false,
            last_reset_ms = -100000,
            last_log_signature = nil,
        }

        restore_peds_ignore(
            "session transition"
        )

        return true
    end

