    function api.SetWorldAggression(enabled)
        if not Live.get_selected_effects then return false end
        local ok, why = Live.get_selected_effects().SetWorldAggression(enabled)
        if ok and enabled then set_toggle("peds_ignore", false) end
        if not ok then log_info(tostring(why)) end
        return ok
    end

    function api.SelectedEffectsRequested()
        return Live.ghost_pending() or
            (Live.vehicle_chaos and Live.vehicle_chaos.HeadFollowRequested and Live.vehicle_chaos.HeadFollowRequested())
            or Live.selected_effects ~= nil or Live.player_bounty ~= nil or Live.player_never_wanted ~= nil or
            Live.player_setpieces ~= nil
    end

    function api.SelectedEffectsTick(now, allow_scene, allow_vehicle, allow_world)
        if allow_scene ~= true and Live.ghost_pending() then
            Live.ghost_cancel("Player processing suspended", false)
            Live.ghost_service(now, false)
        end
        if Live.vehicle_chaos and Live.vehicle_chaos.TickHeadFollow then
            Live.vehicle_chaos.TickHeadFollow(now, allow_scene)
        end
        -- Update the existing Baller toggle's description without adding
        -- another registered menu control or using the disabled logger.
        -- Read only cached counters; no extra network/pool probes per frame.
        local baller_clock = tonumber(now)
        if baller_clock and baller_clock == baller_clock
            and Live.vehicle_chaos and type(Live.vehicle_chaos.BallerDiagnostics) == "function"
            and (not Live.baller_ui_next or baller_clock >= Live.baller_ui_next
                or baller_clock + 1000 < Live.baller_ui_next) then
            Live.baller_ui_next = baller_clock + 1000
            local metrics = Live.vehicle_chaos.BallerDiagnostics()
            for pid, feature in pairs(Live.baller_toggle_refs or {}) do
                if feature then
                    local help="One networked wave of eight Kaylee peds on an invisible platform. 0.60 m ring; gravity and platform collision on; no local hover."
                    if metrics.player_id==pid then
                        help=string.format("Tracked %d/%d | placed %d | awaiting placement %d | cleanup %d\n%s",metrics.present or 0,
                            metrics.target or 8,metrics.positioned or 0,metrics.missing or 0,metrics.waiting or 0,tostring(metrics.reason or ""))
                    end
                    pcall(function() feature:SetDesc(help) end)
                end
            end
        end
        if Live.player_setpieces then
            if allow_scene ~= true then
                Live.player_setpieces.Cancel(nil, "player processing suspended")
            elseif allow_vehicle ~= true then
                for _, kind in ipairs({ "demonic_possession", "ghost_vehicle", "kamikaze_jet" }) do
                    Live.player_setpieces.Cancel(nil, "vehicle processing suspended", kind)
                end
            end
            Live.player_setpieces.Tick(now)
        end
        if Live.selected_effects then
            if allow_world == false then
                Live.selected_effects.Cancel(nil, "world processing suspended",
                    "aggressive_world")
            end
            if allow_scene ~= true then
                Live.selected_effects.Cancel(nil, "player processing suspended")
            elseif allow_vehicle ~= true then
                Live.selected_effects.Cancel(nil, "vehicle processing suspended", "break_vehicle")
                Live.selected_effects.Cancel(nil, "vehicle processing suspended", "dismember_vehicle")
            end
            Live.selected_effects.Tick(now)
        end
        if Live.player_bounty then
            if allow_scene ~= true then
                Live.player_bounty.Reset("player processing suspended")
            else
                Live.player_bounty.Tick(now)
            end
        end
        if Live.player_never_wanted then
            if allow_scene ~= true then
                Live.player_never_wanted.Reset("player processing suspended")
            else
                Live.player_never_wanted.Tick(now)
            end
        end
    end

    function api.LesterRideSnapshot() return Live.lester_ride.Snapshot() end

    function api.LesterRideTick(now, allow_scene)
        if allow_scene ~= true then
            local snapshot = Live.lester_ride.Snapshot()
            if snapshot.active and snapshot.phase ~= "cleanup" and snapshot.phase ~= "debt" then
                Live.lester_ride.Cancel(nil, "player or vehicle processing suspended")
            end
        end
        -- Cleanup continues after domain suspension; scene progression does not.
        return Live.lester_ride.Tick(now)
    end

    function api.PanicReset()
        panic_reset()
        if bst_pending46 and bst_pending46() then return false, "Combat modifier restoration is pending" end
        if State.join_cleanup_pending == true then return false, "Organization join prerequisite restoration is pending" end
        if Live.ghost_pending() then return false end
        if not Live.remote_protection_can_handoff() then return false end
        local store_clean = not store_ignore or store_ignore.Restore()
        if outfit_resources_pending() then return false, "Outfit preview cleanup remains pending" end
        return store_clean
    end

    function api.StoreIgnoreRestoreRequested() return store_ignore and store_ignore.Requested() or false end

    function api.StoreIgnoreRestoreTick(now, allow)
        if not store_ignore or (allow == true and is_on("peds_ignore")) then return true end
        store_ignore.Tick(now, false)
        return not store_ignore.Requested()
    end

    function api.StoreIgnoreSnapshot() return store_ignore and store_ignore.Snapshot() or {} end

    function api.JoinOrganizationSnapshot()
        local s = State.join_organization or {}
        local r = s.readiness or {}
        return {
            active = s.active == true,
            phase = s.phase or "IDLE",
            detail = s.detail or "Off",
            selected_id = s.selected_id,
            boss_id = s.boss_id,
            attempts = s.attempts or 0,
            leave_attempts = s.leave_attempts or 0,
            owner = s.owner_readback,
            roster = s.roster_readback,
            last_result = s.event_result,
            leave_result = s.leave_result,
            refused = s.denied_signature ~= nil,
            next_probe_ms = s.denied_probe_ms,
            capacity = r.capacity,
            boss_busy = r.busy,
            boss_activity_owner = r.activity_owner,
            organization_type = r.organization_type,
            roster_signature = r.signature,
            previous_owner = s.leave_owner,
            response_accepted = s.response_accepted,
            response_refused = s.response_refused,
            cleanup_pending = State.join_cleanup_pending == true or s.join_restore_pending == true
        }
    end

    function api.GhostRelationshipPending() return Live.ghost_pending() end

    function api.GhostRelationshipSnapshot()
        local s = State.remote_ghost or {}
        return {
            status = s.status,
            result = s.result,
            cleanup = s.cleanup_status,
            active = s.active == true,
            pending = Live.ghost_pending(),
            owned = s.owned == true,
            writes = s.writes or 0,
            incoming_pair = s.ghost_pair_after,
            scope = "Ghosted to You; all-peer broadcast"
        }
    end

    function api.DrainUnload(now)
        Live.stop_auto_tp("Script unload")
        Live.headgear.Tick(tonumber(now) or now_ms(), false)
        Live.friendly.Stop()
        Live.friendly.Tick(tonumber(now) or now_ms())
        Live.cancel_tear_gas_toggle("Script unload", true)
        Live.cancel_baller_toggle("Script unload", true)
        Live.scripted_screen_armed = false
        Live.scripted_screen_repeats.Stop("Script unload")
        Live.scripted_screens.Stop("Script unload")
        Live.local_exit_stopped = true
        Live.local_exit.Cancel(nil, "Script unload")
        finish_enter_interior("Script unload", false, true)
        local bst_clean = Live.bst46_pause("script unload", true)
        Live.ghost_cancel("Script unload", true)
        local ghost_clean = Live.ghost_service(tonumber(now) or now_ms(), false, true)
        local guard_clean = not remote_guard44 or remote_guard44.Drain(tonumber(now) or now_ms())
        Live.remote_release_buffer()
        Live.quiesce_join_organization("script unload")
        Live.clear_join_toggle(State.join_organization)
        local join_clean = Live.retry_join_cleanup(tonumber(now) or now_ms(), true)
        local respawn_clean = fast_respawn_delay.Drain()
        -- Reject new leases while the existing camera owners finish teardown.
        -- Failed camera cleanup retains its protection lease and keeps draining.
        Live.protection.stop_requested = true
        local movement_clean = Live.restore_movement_boosts(true)
        local ragdoll_clean = Live.restore_ragdoll_suppression(true)
        Live.aim_cancel("Aim selection cancelled by unload.")
        local aim_clean = not Live.aim.busy and Live.aim_release()
        -- Called only by the existing runtime gameplay tick, while the VM and
        -- scheduler are alive. GameplayTick owns its own native cleanup gate.
        OutfitLive.close_tick(tonumber(now) or now_ms())
        local protection_clean = false
        if next(Live.protection.studios) == nil then
            protection_clean = Live.clear_protection(true, true)
        else
            Live.protection_tick()
        end
        Messiah.GameplayTick(now, local_ped())
        local scene_clean, scene_detail = Live.lester_ride.DrainUnload(tonumber(now) or now_ms())
        local setpieces_clean, setpieces_detail = true, nil
        if Live.player_setpieces then
            setpieces_clean, setpieces_detail = Live.player_setpieces.DrainUnload(tonumber(now) or
                now_ms())
        end
        local effects_clean, effects_detail = true, nil
        if Live.selected_effects then
            effects_clean, effects_detail = Live.selected_effects.DrainUnload(tonumber(now) or
                now_ms())
        end
        if Live.player_bounty then Live.player_bounty.Reset("script unload") end
        if Live.player_never_wanted then Live.player_never_wanted.Reset("script unload") end
        local chaos_clean, chaos_detail = true, nil
        if Live.vehicle_chaos then chaos_clean, chaos_detail = Live.vehicle_chaos.DrainUnload() end
        local remote = Live.restore_remote_vehicle_protection(true)
        restore_peds_ignore("cooperative unload")
        if store_ignore then store_ignore.Tick(tonumber(now) or now_ms(), false) end
        local state = Messiah.State()
        return
            Live.friendly.Clean() and Live.headgear.Clean() and bst_clean and join_clean and guard_clean and
            Live.remote_protection_can_handoff() and ghost_clean and
            respawn_clean and setpieces_clean == true and effects_clean == true and protection_clean and movement_clean and
            ragdoll_clean and aim_clean and chaos_clean == true and scene_clean == true and remote and
            not State.outfit.close_requested and not State.outfit.cleanup_pending
            and (not store_ignore or not store_ignore.Requested())
            and not State.peds_ignore.restore_pending and not state.cleanup_failed and not Messiah.HasOwnership(state)
            and messiah_cleanup_evidence.unresolved == 0,
            (not Live.friendly.Clean() and "Friendly entity or vehicle cleanup is pending") or
            (not Live.headgear.Clean() and "Headgear restoration is pending") or
            (not bst_clean and "Combat modifier restoration is pending") or
            (not join_clean and "Organization join prerequisite restoration is pending") or
            (not guard_clean and "Remote protection restoration is pending") or
            (not ghost_clean and "Ghosted-to-You signal restoration is pending") or
            (not respawn_clean and "Fast Respawn countdown restoration is pending") or
            (messiah_cleanup_evidence.unresolved > 0 and "Messiah cleanup remains unverified") or scene_detail or
            chaos_detail or effects_detail or setpieces_detail
    end

    function api.RestorePersistentState()
        local contact_clean=Live.rrer_contact.Stop()
        Live.headgear.Tick(now_ms(), false)
        Live.friendly.Stop()
        Live.cancel_tear_gas_toggle("Persistent-state shutdown", true)
        Live.cancel_baller_toggle("Persistent-state shutdown", true)
        Live.scripted_screen_armed = false
        Live.scripted_screen_repeats.Stop("Persistent-state shutdown")
        Live.scripted_screens.Stop("Persistent-state shutdown")
        Live.local_exit_stopped = true
        Live.local_exit.Cancel(nil, "Persistent-state shutdown")
        finish_enter_interior("Persistent-state shutdown", false, true)
        local bst_clean = Live.bst46_pause("persistent-state cleanup", true)
        Live.ghost_cancel("Persistent state shutdown", true)
        if remote_guard44 then remote_guard44.Cancel("Script unload; restoration pending.", true) end
        Live.join_stopped = true
        Live.finish_join_organization("script unload", false, true)
        local join_clean = Live.retry_join_cleanup(now_ms(), true)
        fast_respawn_delay.Request(false)
        local store_clean = not store_ignore or store_ignore.Restore()
        -- Final hard-stop cleanup runs after the cooperative drain: never leave
        -- persistent immunity behind once this module can no longer maintain it.
        Live.clear_protection(true, true)
        Live.restore_movement_boosts(true)
        Live.restore_ragdoll_suppression(true)
        Live.lester_ride.RestorePersistentState()
        if Live.selected_effects then Live.selected_effects.RestorePersistentState() end
        if Live.player_setpieces then Live.player_setpieces.RestorePersistentState() end
        if Live.vehicle_chaos then Live.vehicle_chaos.RestorePersistentState() end
        -- These setters restore already-owned flags; they do not queue tasks,
        -- request/release streaming resources, or resume stopped callbacks.
        restore_peds_ignore("script unload")
        Live.restore_remote_vehicle_protection()
        Live.restore_super_melee_damage("persistent-state cleanup")
        local pid, ped = local_player_id(), local_ped()
        if ToggleState.no_wanted then invoke_void(H.SET_MAX_WANTED_LEVEL, 5) end
        if entity_exists(ped) then
            if ToggleState.no_critical_hits then invoke_void(H.SET_PED_SUFFERS_CRITICAL_HITS, ped, true) end
        end
        return contact_clean and Live.friendly.Clean() and Live.headgear.Clean() and bst_clean and join_clean and
            Live.remote_protection_can_handoff() and not Live.ghost_pending() and
            store_clean and fast_respawn_delay.CanHandoff()
    end

    function api.Quiesce()
        local contact_clean=Live.rrer_contact.Stop()
        Live.slope_observer_stop("module_stop")
        Live.stop_auto_tp("Player module stopped")
        Live.friendly.Stop()
        Live.cancel_tear_gas_toggle("Player module stopped", true)
        Live.cancel_baller_toggle("Player module stopped", true)
        Live.scripted_screen_armed = false
        Live.scripted_screen_repeats.Stop("Player module stopped")
        Live.scripted_screens.Stop("Player module stopped")
        Live.local_exit_stopped = true
        Live.local_exit.Cancel(nil, "Player module stopped")
        Live.quiesce_enter_interior("Player module stopped")
        Live.bst46_pause("module stop", true)
        Live.ghost_cancel("Player module stopped", true)
        if remote_guard44 then remote_guard44.Cancel("Player module stopped.", true) end
        if State.remote_godmode then State.remote_godmode.active = false end
        Live.quiesce_join_organization("player module stopped")
        fast_respawn_delay.Request(false)
        Live.property_exit_stopped = true
        Live.property_exit_guard.Reset()
        if Live.selected_effects then Live.selected_effects.Quiesce("player module stopped") end
        if Live.player_setpieces then Live.player_setpieces.Quiesce("player module stopped") end
        if Live.player_bounty then Live.player_bounty.Reset("player module stopped") end
        if Live.player_never_wanted then Live.player_never_wanted.Reset("player module stopped") end
        Live.protection.retiring = true
        if Live.vehicle_chaos then Live.vehicle_chaos.Stop() end
        Live.aim_cancel("Aim selection cancelled: player module stopped.", true)
        Live.lester_ride.Quiesce("player module stopped")
        OutfitLive.request_close("module stop")
        Live.qol.reset("module stop", true)
        Live.speed_preset.pending = false
        Live.quiesce_super_melee("module stop")
        Messiah.Quiesce("module stop", true)
        return contact_clean
    end

    function api.Dispose()
        local contact_clean=Live.rrer_contact.Stop()
        Live.stop_auto_tp("Player module disposed")
        Live.friendly.Stop()
        Live.cancel_tear_gas_toggle("Player module disposed", true)
        Live.cancel_baller_toggle("Player module disposed", true)
        Live.scripted_screen_armed = false
        Live.scripted_screen_repeats.Stop("Player module disposed")
        Live.scripted_screens.Stop("Player module disposed")
        Live.local_exit_stopped = true
        Live.local_exit.Cancel(nil, "Player module disposed")
        Live.quiesce_enter_interior("Player module disposed")
        Live.bst46_pause("module disposal", true)
        Live.ghost_cancel("Player module stopped", true)
        if remote_guard44 then remote_guard44.Cancel("Player module disposed.", true) end
        Live.quiesce_join_organization("player module disposed")
        fast_respawn_delay.Request(false)
        if Live.selected_effects then Live.selected_effects.Quiesce("player module disposed") end
        if Live.player_setpieces then Live.player_setpieces.Quiesce("player module disposed") end
        if Live.player_bounty then Live.player_bounty.Reset("player module disposed") end
        if Live.player_never_wanted then Live.player_never_wanted.Reset("player module disposed") end
        if Live.vehicle_chaos then Live.vehicle_chaos.Stop() end
        Live.aim_cancel("Aim selection cancelled: player module disposed.", true)
        Live.lester_ride.Quiesce("player module disposed")
        Live.qol.reset("module restore", true)
        Live.quiesce_super_melee("module restore")
        Messiah.Quiesce("module restore", true)
        Messiah.FinalDisposal("module restore", true)
        return contact_clean
    end

    function api.OnSessionChange()
        return session_change_cleanup()
    end

    function api.OnPlayerLeft()
        if Live.auto_tp then Live.auto_tp.Prune()end
        if Live.vehicle_chaos then Live.vehicle_chaos.PruneBaller() end
        Live.scripted_screen_repeats.Prune()
        Live.scripted_screens.Prune()
        local ride = Live.lester_ride.Snapshot()
        if ride.active and ride.pid ~= nil and not player_available(ride.pid) then
            Live.lester_ride.Cancel(nil, "selected player left")
        end
        if State.kick_organization and State.kick_organization.active
            and not Live.action_valid(State.kick_organization) then
            Live.finish_kick_organization("player or boss departed", false)
        end
        if State.remote_godmode and State.remote_godmode.active == true
            and not player_available(State.remote_godmode.player_id) then
            finish_remote_godmode_clear("selected player left the session")
        end
        if State.remote_ghost and State.remote_ghost.active == true
            and not player_available(State.remote_ghost.player_id) then
            finish_remote_ghost_clear("selected player left the session")
        end
        if State.remote_passive and State.remote_passive.active == true
            and not player_available(State.remote_passive.player_id) then
            finish_remote_passive_clear("selected player left the session")
        end
        if State.enter_interior and State.enter_interior.active == true
            and not player_available(State.enter_interior.player_id) then
            finish_enter_interior("selected player left the session", false)
        end
        if State.join_organization and State.join_organization.active == true
            and not Live.join_intent_valid(State.join_organization) then
            Live.finish_join_organization("the captured player or organization left or changed", false)
        end
        if State.kick_interior and State.kick_interior.active == true
            and not player_available(State.kick_interior.player_id) then
            finish_kick_from_interior("selected player left the session", false)
        end
        local crippled = {}
        for player_id in pairs(State.cripple.targets) do
            if not player_available(player_id) then crippled[#crippled + 1] = player_id end
        end
        for _, player_id in ipairs(crippled) do
            restore_cripple_target(player_id, "selected player left the session", true)
        end
    end

    return api
end

local function publish_state(context)
    local root = context.State.Player
    if type(root) ~= "table" then
        root = {}
        context.State.Player = root
    end
    root.MigrationPhase = Module.MigrationPhase
    root.Runtime = State
    root.Started = started
    root.Bound = bound
    root.RegisteredCount = State.registered_count
end

function Module.BindCompatibility(bindings)
    if not module_context then error("player module must initialize before compatibility binding", 2) end
    if bound then return public_api end
    dependencies = bindings or {}
    public_api = create_player_system(dependencies)
    -- Lifecycle cleanup retains this controller's read-only readiness query;
    -- exported gameplay methods still retire when their token closes.
    friendly_cleanup_ready = public_api.FriendlyCanHandoff
    local token = { alive = true, dispose = public_api.Dispose }
    lifecycle_token = token
    -- Retained old exports cannot reach new State after rebind/reload.
    for name, callback in pairs(public_api) do
        if type(callback) == "function" then
            public_api[name] = function(...)
                if not token.alive then
                    if name == "RequestAimSelection" then return false, "Player module is stopped." end
                    -- This getter closes over its own cancelled Lua-only state;
                    -- retained UI consumers may still display the final result.
                    if name == "AimSelectionSnapshot" then return callback(...) end
                    -- Retry only this old controller's handler removal after
                    -- the gameplay token closes; it cannot reach a new runtime.
                    if name == "StopSelfIsolationHandler" or name == "SelfIsolationCanHandoff"
                        or name == "SelfIsolationSnapshot" then return callback(...) end
                    return nil
                end
                return callback(...)
            end
        end
    end
    bound = true
    module_context.CScript.Player = public_api
    module_context.Modules.Player = Module
    public_api.RegisterSelfIsolationHandler()
    publish_state(module_context)
    return public_api
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table"
        or type(context.CScript) ~= "table" or type(context.Modules) ~= "table" then
        error("modules.player received an invalid context")
    end
    if module_context and module_context ~= context then
        error("modules.player is already initialized by another context")
    end
    module_context = context
    if not store_ignore then store_ignore = new_peds_store_guards(function() return module_context end) end
    context.Modules.Player = Module
    publish_state(context)
end

function Module.Start()
    if not module_context then error("modules.player started before initialization") end
    started = true
    if public_api then public_api.RegisterSelfIsolationHandler() end
    publish_state(module_context)
end

function Module.CanHandoff()
    if public_api and public_api.SelfIsolationCanHandoff
        and public_api.SelfIsolationCanHandoff()==false then return false end
    if friendly_cleanup_ready and not friendly_cleanup_ready() then return false end
    if bst_pending46 and bst_pending46() then return false end
    if ghost_relationship_pending_raw and ghost_relationship_pending_raw() then return false end
    if remote_guard44 and not remote_guard44.CanHandoff() then return false end
    if remote_proof_io44.ptr ~= nil or remote_proof_io44.busy then return false end
    if remote_protection_handoff44 and not remote_protection_handoff44() then return false end
    if outfit_resources_pending() then return false end
    if (State.join_organization and State.join_organization.active == true) or State.join_cleanup_pending == true then return false end
    if fast_respawn_delay and not fast_respawn_delay.CanHandoff() then return false end
    if store_ignore and not store_ignore.CanHandoff() then return false end
    if messiah_cleanup_evidence.unresolved ~= 0 then return false end
    if not bound then return true end
    return public_api and public_api.MessiahCanHandoff() == true
end

function Module.Stop()
    if friendly_cleanup_ready and not friendly_cleanup_ready() then
        public_api.Quiesce()
        return false, "Friendly cleanup is pending on the gameplay thread."
    end
    -- Restore persistent flags before the token and its ownership records are
    -- discarded. Resource/task teardown still belongs to the gameplay path.
    local clean = true
    if public_api and type(public_api.RestorePersistentState) == "function" then
        clean = public_api
            .RestorePersistentState() ~= false
    end
    if public_api and type(public_api.Quiesce) == "function" then public_api.Quiesce() end
    if lifecycle_token then lifecycle_token.alive = false end
    started = false
    if module_context then publish_state(module_context) end
    return clean
end

function Module.Restore(context)
    if public_api and public_api.StopSelfIsolationHandler
        and public_api.StopSelfIsolationHandler()==false then
        return false,"Self-isolation contact handler removal is pending."
    end
    if friendly_cleanup_ready and not friendly_cleanup_ready() then
        return false,
            "Friendly cleanup is pending."
    end
    if bst_pending46 and bst_pending46() then return false, "Combat modifier restoration is pending" end
    if ghost_relationship_pending_raw and ghost_relationship_pending_raw() then return false end
    if remote_guard44 and not remote_guard44.CanHandoff() then return false end
    if remote_proof_io44.ptr ~= nil or remote_proof_io44.busy then return false end
    if remote_protection_handoff44 and not remote_protection_handoff44() then return false end
    if outfit_resources_pending() then return false, "Outfit preview cleanup remains pending" end
    if (State.join_organization and State.join_organization.active == true) or State.join_cleanup_pending == true then return false end
    if fast_respawn_delay and not fast_respawn_delay.CanHandoff() then return false end
    if store_ignore and not store_ignore.Restore() then return false end
    store_ignore = nil
    context = context or module_context
    started = false
    if lifecycle_token then
        lifecycle_token.alive = false
        local dispose = lifecycle_token.dispose
        lifecycle_token.dispose = nil
        if type(dispose) == "function" then dispose() end
    end
    -- Final disposal is Lua-only. Do not free host buffers from the unload worker.
    if context and context.CScript and context.CScript.Player == public_api then context.CScript.Player = nil end
    if context and context.Modules and context.Modules.Player == Module then context.Modules.Player = nil end
    if context and context.State then context.State.Player = {} end
    fast_respawn_delay, fast_respawn_host = nil, nil
    remote_guard44, remote_protection_handoff44 = nil, nil
    bst_pending46 = nil
    module_context = nil
    public_api = nil
    friendly_cleanup_ready = nil
    ghost_relationship_pending_raw = nil
    dependencies = nil
    bound = false
    F = {}
    ToggleState = {}
    PF_ID = {}
    State = {
        registered_count = 0,
