["CScript/modules/player_bounty.lua"]=[====[
-- Freemode bounty renewal, scoped to one session and connection identity.
-- Enhanced 1158 source: freemode func_16641 (23-word event), func_25589/25590
-- (validation + assignment), func_16644 (host-synchronized active flag),
-- func_3899/25052 (rotating event tokens). No globals or account stats are written.
local Module = { Name = "modules.player_bounty", MigrationPhase = "17.75" }
local context, instances = nil, {}
local PROFILE = {
    event = 1517551547, words = 23,
    active_base = 1835603 + 4 + 1, header = 1835603 + 4, stride = 3,
    maximum = 262145 + 2337,
    token_a = 1923118 + 9, token_b = 1923118 + 10,
}
local function integer(n)
    return type(n)=="number" and n==n and n%1==0 and math.abs(n)<=4294967295
end
local function key(k)
    return (type(k)=="string" and k~="") or integer(k)
end
function Module.New(deps)
    for _,name in ipairs({"read_global_int","script_globals_ready","profile_ready","session_key",
        "player_identity","player_available","local_player_id","send_event","now_ms"}) do
        assert(type(deps[name])=="function", "player_bounty requires "..name)
    end
    local api, runs, history, next_poll, last_send = {}, {}, {}, 0, -100000
    local function call(fn,...)
        local ok,v=pcall(fn,...); if ok then return v end
    end
    local function read(index)
        local n=call(deps.read_global_int,index); return integer(n) and n or nil
    end
