        local run=runs[pid]; if not run then return false end
        runs[pid]=nil
        history[pid]={active=false, phase="stopped", reason=reason, attempts=run.total}
        if type(deps.on_stopped)=="function" then pcall(deps.on_stopped,pid,reason) end
        return true
    end
    local function ready()
        return call(deps.profile_ready)==true and call(deps.script_globals_ready)==true
            and read(PROFILE.header)==32 -- func_27270 initializes src.f_4 = 32
    end
    local function valid(run)
        return ready() and call(deps.session_key)==run.session
            and call(deps.local_player_id)==run.sender
            and call(deps.player_identity,run.sender)==run.sender_identity
            and call(deps.player_available,run.pid)==true
            and call(deps.player_identity,run.pid)==run.identity
    end
    local function state(pid)
        local flag=read(PROFILE.active_base+pid*PROFILE.stride)
        local amount=read(PROFILE.active_base+pid*PROFILE.stride+1)
        if flag==0 and amount==0 then return false end
        if flag==1 and amount and amount>0 then return true end
        return nil
    end
    function api.Start(pid)
        if not integer(pid) or pid<0 or pid>31 then return false,"Invalid player." end
        if runs[pid] then return true end
        if not ready() then return false,"Current Enhanced freemode profile is unavailable." end
        local sender,session=call(deps.local_player_id),call(deps.session_key)
        if not integer(sender) or sender<0 or sender>31 or pid==sender then return false,"Select another player." end
        local identity, sender_identity=call(deps.player_identity,pid),call(deps.player_identity,sender)
        if not key(session) or not key(identity) or not key(sender_identity)
            or call(deps.player_available,pid)~=true then return false,"Fresh session and player identities are required." end
        if state(pid)==nil then return false,"Bounty state is not readable." end
        local a,b,maximum=read(PROFILE.token_a),read(PROFILE.token_b),read(PROFILE.maximum)
        if not a or not b or (a==0 and b==0) or not maximum or maximum<1 or maximum>100000 then
            return false,"Freemode bounty tokens or tuning are not initialized."
        end
        runs[pid]={pid=pid,sender=sender,session=session,identity=identity,sender_identity=sender_identity,
            phase="observing",attempts=0,total=0,next_send=0}
