end
function Module.Start() assert(context,"player_bounty not initialized") end
function Module.Stop() for _,api in ipairs(instances) do api.Reset("Module stopped.") end end
function Module.Restore(c)
    Module.Stop();c=c or context
    if c and c.Modules and c.Modules.PlayerBounty==Module then c.Modules.PlayerBounty=nil end
    context,instances=nil,{}
end
return Module
