  return runs[r.pid]==r and ready() and call(deps.session_key)==r.session
   and call(deps.local_player_id)==r.sender and call(deps.player_identity,r.sender)==r.sender_identity
   and call(deps.player_available,r.pid)==true and call(deps.player_identity,r.pid)==r.identity
