  if not integer(pid)or pid<0 or pid>31 then return false,'Invalid player.'end
  if runs[pid]then return true end
  if not ready()then return false,'Validated freemode profile is unavailable.'end
  local sender,session=call(deps.local_player_id),call(deps.session_key)
  if not integer(sender)or sender<0 or sender>31 or sender==pid then
   return false,'Select another player; use No Wanted Level for yourself.'
