    local dx,dy,dz=unit(goal.x-at.x,goal.y-at.y,goal.z-at.z)
    found=bool(H.NODE_FAVOUR,at.x,at.y,at.z,dx,dy,dz,1,ptr,ptr+24,node_flags,3.0,0.0)
   else found=bool(H.NODE,at.x,at.y,at.z,ptr,ptr+24,node_flags,3.0,0)end
   if found~=true then return end
