 local function guide(r,a,p,pos,t)
  if r.kind=="hammer_of_god"then return guide_hammer(r,a,p,pos,t)end
  local origin=vec(H.COORDS,a.handle,false)
  if not origin then return end
  local tv=vec(H.VELOCITY_GET,p.handle)or{x=0,y=0,z=0}
  if r.kind=="ghost_vehicle"then
   -- After a temporary ownership gap, recover our own actor state. No control
   -- request or mutation is attempted against the target's vehicle.
   if a.ghost_recover_needed then
    a.phased=nil;a.kinematic=false;a.probe_origin=nil
    a.next_ghost_protection=0
    a.ghost_recover_needed=nil
   end
   if t>=(a.next_ghost_protection or 0)then
    if not apply(r,a,H.INVINCIBLE,a.handle,true,false)
      or not apply(r,a,H.FREEZE,a.handle,false)
      or not apply(r,a,H.ENGINE,a.handle,true,true,false)
      or not apply(r,a,H.LOCK,a.handle,10)then
     r.reason="waiting for ghost vehicle protection";return
    end
    a.next_ghost_protection=t+700
   end
   local car=int(H.CAR,p.handle,false)
   if car and car~=0 and physical(car)then
    local observed=vec(H.VELOCITY_GET,car)
    if observed then tv=observed end
   end
   local separation=distance(origin,pos)
   local measured=math.sqrt(tv.x*tv.x+tv.y*tv.y+tv.z*tv.z)
   if not finite(measured)then measured=0 end
   local elapsed=t-(a.ghost_speed_at or t)
   local speed=ghost_follow_speed(clamp(measured,0,140),separation,a.ghost_chase_speed,elapsed)
   a.ghost_chase_speed,a.ghost_speed_at=speed,t
   local lead=clamp(separation/math.max(speed,24),0.08,0.40)
   local aim_x=pos.x+clamp(tv.x,-140,140)*lead
   local aim_y=pos.y+clamp(tv.y,-140,140)*lead
   local aim_z=pos.z+0.35+clamp(tv.z,-30,30)*lead
   local clear=bool(H.LOS,a.handle,p.handle,17)==true
   -- Only record a changed phase when collision really changed.
   local phased=not clear or separation>3.0 or
    (bool(H.CONTACT,a.handle)==true and bool(H.TOUCHING,a.handle,p.handle)~=true)
   if a.phased~=phased then
    if apply(r,a,H.COLLISION,a.handle,not phased,true)then
     apply(r,a,H.ALPHA,a.handle,phased and 153 or 255,false)
     apply(r,a,H.GRAVITY,a.handle,false)
