  if a.impact then return end
  if r.kind=="kamikaze_jet"then
   if not ensure_jet_pilot(r,a,p,pos,t)then r.reason="waiting for pilot/aircraft control";return end
   retain_hammer(r,a,t)
   if a.launch_origin and distance(a.launch_origin,origin)>=12.0 and not a.flight_verified then
    a.flight_verified=true
    if type(deps.log_info)=="function"then pcall(deps.log_info,"Jet flight observed run="..r.serial.." travel="..string.format("%.2f",distance(a.launch_origin,origin)))end
   end
  end
  local clear=bool(H.LOS,a.handle,p.handle,17)==true
  local phased=not clear or (r.kind=="kamikaze_jet" and (distance(origin,pos)>3.0 or bool(H.CONTACT,a.handle)==true))
  local collision_changed=a.phased~=phased
  if collision_changed then
   -- Avoid catching the container/aircraft on a distant roof or wall. Only
   -- this script-created body phases, and it is solid again for the impact.
   if apply(r,a,H.COLLISION,a.handle,not phased,true)then a.phased=phased end
  end
  local closest,near=sweep(a.last_position or origin,origin,pos)
  local contact=t-a.born>=120 and not a.phased and not collision_changed and bool(H.CONTACT,a.handle)==true
  local swept=t-a.born>=120 and near<=4.0 and clear
  if (contact or swept)and (r.kind~="kamikaze_jet"or a.flight_verified)then
   local at=contact and origin or closest
   a.impact=true;r.impact_at=t;r.reason=contact and "collision observed"or "target crossing observed"
   if current(r)and matches(a)and bool(H.CONTROL,a.handle)==true then
    if not impact_blast(r,a,at,t)then cancel(r,"impact effect rejected")end
   end
   return
  end
  a.last_position=origin
  if r.kind=="kamikaze_jet"then
   local speed=110.0;local lead=clamp(distance(origin,pos)/speed,0,1.2)
   local dx,dy,dz=unit(pos.x+clamp(tv.x,-90,90)*lead-origin.x,pos.y+clamp(tv.y,-90,90)*lead-origin.y,pos.z+clamp(tv.z,-30,30)*lead-origin.z)
