   local tag=deps.eExplosionTag and deps.eExplosionTag.EXP_TAG_MORTAR_KINETIC
   if not (tag~=nil and deps.CExplosionArgs and type(deps.CExplosionArgs.New)=='function'
       and deps.V3 and type(deps.V3.New)=='function' and deps.GTA and type(deps.GTA.AddExplosion)=='function')then
    cancel(r,'Fling kinetic backend unavailable; target control not requested');return
   end
   local at=vec(H.COORDS,body.handle,false)or pos
   local built,args=pcall(function()
    local value=deps.CExplosionArgs.New(tag,deps.V3.New(at.x,at.y,at.z-0.8))
    value.IsLocalOnly=false;value.NoDamage=true;value.NoFx=true;value.MakeSound=false
    -- Test a stronger kinetic fallback while preserving the original pulse count.
    -- SizeScale is not guaranteed to scale remote ped knockback on its own.
    value.SizeScale=4.0;value.CamShake=0.0;value.ActivationDelay=0;value.DisableDamagingOwner=true
    return value
   end)
   if not built or not args or not fence()then cancel(r,'Fling kinetic request could not be prepared');return end
   local invoked,accepted=pcall(deps.GTA.AddExplosion,args)
   if not invoked or accepted~=true then cancel(r,'Fling kinetic request rejected');return end
   r.fling_pulses=(r.fling_pulses or 0)+1;r.next_fling_pulse=t+120;r.active_since=r.active_since or t
