  -- Flatten pitch so a leaning ped or pitched vehicle cannot invert the launch.
  local forward=vec(0x0A794A5A57F8DF91,body.handle) -- GET_ENTITY_FORWARD_VECTOR
  local flat=forward and math.sqrt(forward.x*forward.x+forward.y*forward.y)
  if not finite(flat)or flat<0.0001 then
   cancel(r,"Fling forward direction unavailable");return
  end
  local launch_speed=24000.0 -- User-selected speed; no live stability guarantee.
  local tilt=math.rad(10.0)
