 end
 local function action(r,p,pos,t)
  if r.kind=="tear_gas_trap"then tear.Action(r,p,pos,t);return end
  if r.impact_at then
   if t-r.impact_at>=350 then cancel(r,"impact completed")end
   return
  end
  if own_cleanup_pending(r)then r.phase="waiting";r.reason="cleaning previous actor";return end
  r.acquire_started=r.acquire_started or t
  r.phase="executing";r.reason="active"
  if r.spec.class=="impulse"then fling(r,p,pos,t);return end
  if r.spec.class=="borrowed"then possession(r,p,t);return end
