    if r.kind=="hammer_of_god"then hammer_trace(r,a,"actor-lost",t,why)end
    if r.spec.sustained and (why=="gone"or why=="replaced")then reset_cycle(r,"replacing missing actor",t)
    else cancel(r,"created entity "..tostring(why))end
