   end
   if r.spec.sustained and bool(H.DEAD,a.handle,false)==true then reset_cycle(r,"replacing destroyed actor",t);return end
   if not a.auxiliary and configure(r,a,p,pos,t)then
    local actor_control=control(a,t)
    if not actor_control and r.kind=="ghost_vehicle"then
     a.ghost_recover_needed=true
     r.reason="waiting for ghost vehicle control"
    elseif actor_control then
     guide(r,a,p,pos,t)
    end
   end
  end
