 local function reserved(replacing)
  local count=#debt+inflight
  for kind,r in pairs(runs)do
   local creating=r.inflight or 0
   count=count+(kind==replacing and #r.actors or math.max(#r.actors+creating,r.spec.count+(r.spec.extra_count or 0))-creating)
  end
  return count
 end
 local function flush_events(t)
  local queued=events;events={}
  for _,e in ipairs(queued)do
   if type(deps.log_info)=="function"then
    pcall(deps.log_info,"Selected effect: "..e.name.." [player "..e.pid.."] "..e.phase
     .." ("..tostring(e.reason)..", "..string.format("%.2fs",math.max(0,t-e.started)/1000)..")")
   end
   if e.phase=="stopped" and type(deps.on_effect_stopped)=="function"then
    pcall(deps.on_effect_stopped,e.kind,e.pid,e.reason)
   end
  end
 end
 function api.Available(kind,pid)
  local spec=specs[kind];pid=tonumber(pid)
  if not spec then return false,"unknown selected action"end
  if not integer(pid)or pid<0 or pid>31 then return false,"invalid player"end
  if stopped then return false,"actions are stopping"end
  local key=kind..":"..tostring(pid)
  if runs[key]then return true end
  if spec.class=="borrowed"and pending_probes()>=64 then return false,"collision job cleanup backlog is full"end
  if reserved(key)+spec.count+(spec.extra_count or 0)>MAX_OWNED
   or spec.class~="borrowed"and #model_debt>=MAX_OWNED then return false,"owned entity cleanup backlog is full"end
  if kind=="tear_gas_trap"and tear.Reserved(key)+SMOKE_COUNT>MAX_SMOKE then return false,"owned smoke capacity is full"end
  return true
 end
 function api.Start(kind,pid)
  local spec=specs[kind];pid=tonumber(pid)
  if not spec then return false,"unknown selected action"end
  if stopped then return false,"actions are stopping"end
  local admission
  if kind=="tear_gas_trap"then
   if not integer(pid)or pid<0 or pid>31 then return false,"invalid player"end
   admission={};tear.admissions[pid]=admission
  end
  local function gas_current()return not stopped and tear.admissions[pid]==admission end
  if spec.class=="borrowed"and pending_probes()>=64 then return false,"collision job cleanup backlog is full"end
  local run_key=kind..":"..tostring(pid)
  if kind=="tear_gas_trap"and tear.Reserved(run_key)+SMOKE_COUNT>MAX_SMOKE then return false,"owned smoke capacity is full"end
  if reserved(run_key)+spec.count+(spec.extra_count or 0)>MAX_OWNED or spec.class~="borrowed" and #model_debt>=MAX_OWNED then return false,"owned entity cleanup backlog is full"end
  if not integer(pid) or pid<0 or pid>31 then return false,"invalid player"end
  local ok,lid=pcall(deps.local_player_id);local local_identity=ok and player(lid)
  local target_identity=player(pid);local key=epoch()
  if not local_identity or not target_identity or bool(H.SESSION)~=true then return false,"online player identity unavailable"end
  if type(deps.session_key)=="function" and key==nil then return false,"session epoch unavailable"end
  local started_at
  if admission then
   started_at=now()
   -- Host identity/time calls can reenter OFF, a newer ON or Quiesce. The old
   -- admission must neither cancel the replacement nor install after shutdown.
   if not gas_current()then return false,"Gas chamber trap admission superseded"end
   if reserved(run_key)+spec.count>MAX_OWNED or #model_debt>=MAX_OWNED or tear.Reserved(run_key)+SMOKE_COUNT>MAX_SMOKE then
    return false,"owned entity or smoke cleanup backlog is full"
   end
  end
  if runs[run_key]then runs[run_key].stop_requested=true;cancel(runs[run_key],"retriggered")end
  if admission and not gas_current()then return false,"Gas chamber trap admission superseded"end
  serial=serial+1
  local r={key=run_key,kind=kind,spec=spec,pid=pid,target=target_identity,local_identity=local_identity,epoch=key,
   phase="executing",started=started_at or now(),serial=serial,actors={},reason="queued"}
  runs[run_key]=r;event(r,"started","queued")
  return true
 end
 function api.Cancel(pid,reason,kind)
  if kind==nil or kind=="tear_gas_trap"then
   if pid==nil then tear.admissions={}else tear.admissions[pid]=nil end
  end
  local cancelled={}
  for k,r in pairs(runs)do
   if (pid==nil or r.pid==pid) and (kind==nil or r.kind==kind)then cancelled[#cancelled+1]=r end
  end
  for _,r in ipairs(cancelled)do r.stop_requested=true;cancel(r,reason)end
