 local function tick(t,drain)
  if busy then return end;busy=true;t=now(t)
  -- Clean first: a retrigger must never create its replacement ahead of deletion.
  local clean_ok,clean_error=pcall(cleanup,t,drain)
  if not clean_ok and type(deps.log_info)=="function"then pcall(deps.log_info,"Selected effect cleanup: "..tostring(clean_error))end
  local queued={};for _,r in pairs(runs)do queued[#queued+1]=r end
  table.sort(queued,function(a,b)return a.serial<b.serial end)
  for _,r in ipairs(queued)do
   if current(r) and not drain then
    local ok,err=pcall(function()
     if r.kind=="hammer_of_god"and r.impact_at then
      -- Run BEFORE target-state validation: the impact may already have killed
      -- or despawned the target, but its scenery still needs to reach ground.
      hammer_aftermath(r,t)
      elseif not r.spec.sustained and r.active_since and t-r.active_since>=r.spec.duration then
      cancel(r,r.kind=="hammer_of_god"and"Hammer expired without an observed impact"or"completed")
     elseif not r.spec.sustained and not r.active_since and r.acquire_started and t-r.acquire_started>=6000 then cancel(r,"acquisition timed out")
     else
