       -- Remote ped handles can briefly vanish during a respawn/stream update.
       -- Identity/session changes are terminal; only transient streaming waits.
       if r.kind=="tear_gas_trap"then cancel(r,why)
       elseif r.spec.sustained and why~="player or session changed"then
        if #r.actors>0 then reset_cycle(r,why,t)end
