-- Public Free has no active Protections feature license. Read-only status
-- and cleanup continue working to avoid leaving stale local state behind.
local function __public_bind(context)
    if __public_binding and __public_binding.context == context and module_context == context then return end
    local cs = context and context.CScript
    local auth = type(cs) == "table" and cs.Entitlements
    local allowed = type(auth) == "table" and auth.IsAllowed
    assert(type(cs) == "table" and cs.DistributionMode == "public"
        and type(allowed) == "function", "Public protection authorization is required")
