local function ingress_observation_count(value)
    if type(value) ~= "number" or value ~= value or value < 0 or value > 1000000000 then return 0 end
    return math.floor(value)
end

local function handler_registration_state(identifier)
    local present = identifier ~= nil
    local state = { registered=present, armed=present, queued=false, removal_pending=false,
        ingress={ observed=false } }
    if not present or not EventMgr or type(EventMgr.GetHandlerState) ~= "function" then return state end
    -- Loader-owned identifiers can exist before a host callback is armed, or
    -- remain owned while a failed removal is retried. Neither is live intake.
    local ok, observed = pcall(EventMgr.GetHandlerState, identifier)
    if not ok or type(observed) ~= "table" then
        state.registered, state.armed = false, false
        return state
    end
    state.registered = observed.registered == true
    state.removal_pending = observed.removal_pending == true
    state.queued = observed.queued == true
    state.armed = state.registered and observed.armed == true and not state.removal_pending
    if type(observed.host_entries) == "number" then
        state.ingress = {
            observed = true,
            host_entries = ingress_observation_count(observed.host_entries),
            disabled_entries = ingress_observation_count(observed.disabled_entries),
            authorization_denied = ingress_observation_count(observed.authorization_denied),
            lifecycle_denied = ingress_observation_count(observed.lifecycle_denied),
            forwarded = ingress_observation_count(observed.forwarded),
            native_id = type(observed.native_id) == "number" and observed.native_id or nil,
            event = type(observed.event) == "number" and observed.event or nil,
            callbacks_enabled = observed.callbacks_enabled == true,
        }
    end
    return state
end

