    local function canonical(content)
        if type(content) ~= "string" then return nil end
        if content:sub(1, 3) == "\239\187\191" then content = content:sub(4) end
        return content:gsub("\r\n", "\n"):gsub("\r", "\n")
    end

    local function clean(value, maximum)
        local text = tostring(value == nil and "" or value):gsub("[%c]+", " ")
        text = text:gsub("[Cc]:\\[Uu]sers\\[^\\%s]+", "<user-profile>")
        text = text:gsub("%f[%d]%d%d?%d?%.%d%d?%d?%.%d%d?%d?%.%d%d?%d?%f[%D]", "<ip>")
        for _, key in ipairs({ "token", "secret", "password", "license", "activation", "auth", "rid", "rockstarid", "account" }) do
            local pattern = key:gsub("%a", function(character)
                return "[" .. character:lower() .. character:upper() .. "]"
            end)
            text = text:gsub("(" .. pattern .. "%s*[=:]%s*)[^%s,;|]+", "%1<redacted>")
        end
        maximum = math.max(16, tonumber(maximum) or 240)
        if #text > maximum then text = text:sub(1, maximum - 3) .. "..." end
        return text
    end

    local function finite_number(value)
        return type(value) == "number" and value == value
            and value ~= math.huge and value ~= -math.huge
    end

    local function integer_number(value)
        return finite_number(value) and value == math.floor(value)
    end

    local function set_spawn_radius(value)
        if not finite_number(value) then return false end
        value=math.floor(math.max(SPAWN_RADIUS_MIN,math.min(SPAWN_RADIUS_MAX,value))+0.5)
        State.spawn.radius=value
        return true
    end

    local function timestamp_label()
        if os and type(os.date) == "function" then
            local ok, value = pcall(os.date, "%Y%m%d-%H%M%S")
            if ok and type(value) == "string" then return value end
        end
        return tostring(math.floor(now_ms()))
    end

    local function session_source_label(player_id)
        player_id = tonumber(player_id) or -1
        return player_id >= 0 and ("session player %d"):format(player_id) or "unattributed session source"
    end


    -- Event callbacks can run thousands of times per frame in combat. Toggle
    -- callbacks publish changes immediately; the native scheduler reconciles
    -- external/no-callback changes on a bounded cadence. Disabled handlers now
    -- perform only Lua table reads, without touching host Feature userdata.
    -- Enhanced freemode func_24825 consumes the four-word remote
    -- -901348601 request then calls NETWORK_BAIL(16). Filter only that inbound
    -- cause; never intercept local natives or ordinary quit/session transitions.
    local desync_probe_ms=-100000
    local function probe_desync_backend(now)
        if now>=desync_probe_ms and now-desync_probe_ms<5000 then return end
        desync_probe_ms=now
        local ok,version=pcall(function() return Natives.InvokeString(0xFCA9373EF340AC0A) end)
        State.desync.game_version = ok and type(version)=="string" and version or nil
        State.desync.backend_available=ok and version=="1.73"
            and eLuaEvent and eLuaEvent.SCRIPTED_GAME_EVENT~=nil
            and EventMgr and type(EventMgr.RegisterHandler)=="function"
            and type(EventMgr.RemoveHandler)=="function" or false
        if not State.desync.backend_available then State.desync.applied=false end
    end
    local last_toggle_refresh_ms = -100000
    local function refresh_toggle_states(now)
        now = tonumber(now) or 0
        if now >= last_toggle_refresh_ms and now - last_toggle_refresh_ms < 250 then return end
        last_toggle_refresh_ms = now
        for key in pairs(ToggleState) do
            local feature = F[key]
            if feature and type(feature.IsToggled) == "function" then
                local ok, enabled = pcall(feature.IsToggled, feature)
                if ok then
                    ToggleState[key] = key ~= "desync_protection" and enabled == true
                    if key=="desync_protection" and State.desync.backend_available then ToggleState[key]=enabled==true end
                    if key == "desync_protection" and enabled == true and not State.desync.backend_available then
                        State.desync.requested=true
                        State.desync.result="REJECTED_UNAVAILABLE"
                    end
                end
            end
        end
    end

    local function is_on(key)
        -- Retained feature IDs cannot reactivate retired automatic actions
        -- through an old saved configuration or an external feature toggle.
        if key == "protect_auto_isolate" or key == "protect_collision" then
            return false
        end
        return ToggleState[key] == true
    end

    local function add_toggle(key, name, description, default)
        if F[key] then
            return F[key]
        end

        ToggleState[key] = default == true

        local function on_toggle(feature)
            local ok, enabled = pcall(function()
                return feature:IsToggled()
            end)

            if ok then
                ToggleState[key] = enabled == true
                if key == "op_crash_protection" or key == "protect_ped_spawns"
                    or key == "protect_vehicle_spawns" or key == "protect_object_spawns" then
                    State.spawn.position, State.spawn.sampled_at = nil, -100000
                end
                if key == "desync_protection" and State.desync.backend_available then
                    State.desync.requested=enabled==true
                    State.desync.result=enabled and "REMOTE_BAIL_FILTER" or "OFF"
                    State.desync.request_count=math.min(1000000000,State.desync.request_count+1)
                elseif key == "desync_protection" then
                    local status=State.desync
                    if not status.resetting then
                        status.requested=enabled==true
                        status.applied=false
                        status.result=enabled and "REJECTED_UNAVAILABLE" or "OFF"
                    end
                    if enabled==true then
                        -- No cause-aware NETWORK_BAIL contract exists in the
                        -- supplied host surface. Never intercept intentional exits.
                        ToggleState[key]=false
                        if status.resetting then return end
                        status.request_count=math.min(1000000000,status.request_count+1)
                        status.resetting=true
                        pcall(feature.Toggle,feature,false)
                        status.resetting=false
                        local now=now_ms()
                        if now<status.last_notice_ms or now-status.last_notice_ms>=5000 then
                            status.last_notice_ms=now
                            status.notification_count=math.min(1000000000,status.notification_count+1)
                            log_warn(("Desync Protection unavailable: no verified cause-aware local bail interceptor; no bail was suppressed. Requested ON / applied OFF. Rejected requests=%d, duplicate notices=%d.")
                                :format(status.request_count,status.duplicate_notifications))
                        else
                            status.duplicate_notifications=math.min(1000000000,status.duplicate_notifications+1)
                        end
                    end
                end
                if reconcile_event_handlers then reconcile_event_handlers() end
            end
        end

        local feature = FeatureMgr.AddFeature(
            feature_id(key),
            name,
            eFeatureType.Toggle,
            description or "",
            on_toggle
        )

        if not feature then
            return nil
        end

        if type(feature.SetDefaultValue) == "function" then
            pcall(function()
                feature:SetDefaultValue(default == true)

                if default == true
                    and type(feature.Toggle) == "function"
                    and not feature:IsToggled() then
                    feature:Toggle(true)
                end
            end)
        end

        F[key] = feature

        local ok, enabled = pcall(function()
            return feature:IsToggled()
        end)

        if ok then
            ToggleState[key] = enabled == true
        end

        State.registered_count =
            State.registered_count + 1

        return feature
    end

    local function add_button(key, name, description, callback)
    if F[key] then
        return F[key]
    end

    local feature = FeatureMgr.AddFeature(
        feature_id(key),
        name,
        eFeatureType.Button,
        description or "",
        callback
    )

    if not feature then
        return nil
    end

    F[key] = feature

    State.registered_count =
        State.registered_count + 1

    return feature
end

    local function object_member(object, name)
        if object == nil then return nil end
        local ok, value = pcall(function() return object[name] end)
        if ok then return value end
        return nil
    end

    local function sender_identity(sender)
        if type(sender) == "number" then
            if not integer_number(sender) or sender < 0 or sender > 31 then return -1, "invalid" end
            return math.floor(sender), "trusted"
        end
        if sender == nil then return -1, "unknown" end
        local raw = object_member(sender, "PlayerId")
        if raw == nil then return -1, "unknown" end
        local value = tonumber(raw)
        if not integer_number(value) or value < 0 or value > 31 then return -1, "invalid" end
        return math.floor(value), "trusted"
    end

    local function sender_player_id(sender)
        local player_id = sender_identity(sender)
        return player_id
    end

    local function sender_name(sender)
        local id = sender_player_id(sender)
        local method = object_member(sender, "GetName")
        if type(method) == "function" then
            local ok, value = pcall(method, sender)
            if ok and type(value) == "string" and value ~= "" then return value:sub(1, 64) end
        end
        return id >= 0 and player_name(id) or "unknown"
    end

    local function net_object_identity(net_object)
        if net_object == nil then return -1, "unknown" end
        local raw = object_member(net_object, "PlayerId")
        if raw == nil then return -1, "unknown" end
        local value = tonumber(raw)
        if not integer_number(value) or value < 0 or value > 31 then return -1, "invalid" end
        return math.floor(value), "trusted"
    end

    local function net_object_player_id(net_object)
        local player_id = net_object_identity(net_object)
        return player_id
    end

    local function protection_master(key)
        return is_on("op_crash_protection") and (key == nil or is_on(key))
    end

    local function roster_presence(player_id)
        -- Prefer the documented accessor over compatibility helpers which may
        -- collapse an exception into false. An exception proves no disconnect.
        if players and type(players.GetById) == "function" then
            local ok, value = pcall(players.GetById, player_id)
            if ok then return value ~= nil end
            return nil
        end
        if type(player_available) == "function" then
            local ok, value = pcall(player_available, player_id)
            if ok and type(value) == "boolean" then return value end
        end
        -- If the host build has no roster accessor, absence cannot be proven.
        -- Keep the session-local slot rather than falsely classifying a valid
        -- remote callback as a disconnect.
        return nil
    end

    local function orbital_player_available(player_id)
        return roster_presence(player_id) ~= false
    end


    local function scan_orbital_activity(now)
        local orbital = State.orbital
        if now - (orbital.last_scan_ms or -100000) < ORBITAL_SCAN_INTERVAL_MS then return end
        orbital.last_scan_ms = now
        orbital.scans = (orbital.scans or 0) + 1
        -- Orbital detection is disabled: runtime validation did not confirm
        -- the operator signal or its target/victim relationship.
        orbital.available = false
        orbital.active = {}
        orbital.local_active = false
        orbital.research_only = true
        orbital.last_error = "Orbital detection unavailable: f_429 is not a verified operator signal. Alerts and blocking are disabled."
    end

    local function total_blocked()
        local counters = State.counters
        return (tonumber(counters.events_blocked) or 0)
            + (tonumber(counters.nodes_blocked) or 0)
            + (tonumber(counters.collisions_blocked) or 0)
            + (tonumber(State.desync.blocked) or 0)
    end

    local function source_identity(player_id)
        if not players or type(players.GetById) ~= "function" then return nil end
        local ok, token = pcall(function()
            local current = players.GetById(player_id)
            local getter = object_member(current, "GetGamerInfo")
            if type(getter) ~= "function" then return nil end
            local info = getter(current)
            local value = object_member(info, "RockstarId")
            if type(value) == "string" and value ~= "" then return value end
            if integer_number(value) and value > 0 then return tostring(value) end
        end)
        return ok and token or nil
    end

    local function clear_source_state(player_id)
        State.evidence[player_id], State.detected[player_id] = nil, nil
        State.isolated_until[player_id], State.ignored_until[player_id] = nil, nil
        State.block_leases[player_id], State.mute_leases[player_id] = nil, nil
        State.event_buckets[tostring(player_id)], State.node_buckets[tostring(player_id)] = nil, nil
        State.evidence_aggregates[player_id], State.missing_since[player_id] = nil, nil
        State.source_identities[player_id] = nil
        if State.attack.source_id == player_id then
            State.attack.source_id, State.attack.source_confidence = -1, CONFIDENCE_NONE
            State.attack.last_action = "Session player changed; old traffic block and attribution cleared"
        end
    end

    local function refresh_source_identity(player_id)
        if player_id < 0 or player_id > 31 then return end
        local generation = State.session_generation
        local token = source_identity(player_id)
        if generation ~= State.session_generation then return nil end
        local previous = State.source_identities[player_id]
        if token and previous and token ~= previous then clear_source_state(player_id) end
        -- An unavailable getter proves neither a disconnect nor a new occupant.
        if token then State.source_identities[player_id] = token end
        return token
    end

    local function has_manual_blocks()
        return next(State.isolated_until) ~= nil
    end

    local function manual_lease_active(player_id, now, expiry_key, lease_key)
        player_id = tonumber(player_id)
        if not started or not player_id or player_id < 0 or player_id > 31 then return false end
        now = tonumber(now) or now_ms()
        local expirations, leases = State[expiry_key], State[lease_key]
        local until_ms = tonumber(expirations[player_id]) or 0
        if until_ms <= 0 then return false end
        local lease = leases[player_id]
        local generation = State.session_generation
        if now >= until_ms or not lease or lease.session_generation ~= generation then
            expirations[player_id], leases[player_id] = nil, nil
            return false
        end
        local token = refresh_source_identity(player_id)
        -- Keep a temporarily unreadable lease dormant, with its original expiry.
        -- A readable replacement clears the old slot state in the refresh above.
        return started and generation == State.session_generation and State[lease_key] == leases
            and leases[player_id] == lease and token ~= nil and token == lease.identity
    end

    local function is_ignored(player_id, now)
        return manual_lease_active(player_id, now, "ignored_until", "mute_leases")
    end

    local function is_isolated(player_id, now)
        return manual_lease_active(player_id, now, "isolated_until", "block_leases")
    end

    local function append_evidence(player_id, category, detail, blocked, direct, now)
        now = tonumber(now) or now_ms()
        State.evidence_sequence = (tonumber(State.evidence_sequence) or 0) + 1
        State.evidence_rows[#State.evidence_rows + 1] = {
            sequence = State.evidence_sequence,
            at_ms = now,
            source_id = tonumber(player_id) or -1,
            category = clean(category, 64),
            detail = clean(detail, 240),
            blocked = blocked == true,
            direct = direct == true,
        }
        while #State.evidence_rows > EVIDENCE_LIMIT do
            table.remove(State.evidence_rows, 1)
            State.evidence_dropped = State.evidence_dropped + 1
        end
        State.evidence_dirty = true
    end

    local function aggregate_evidence(player_id, category, detail, blocked, direct, now)
        now = tonumber(now) or now_ms()
        player_id = tonumber(player_id) or -1
        category = clean(category, 64)
        detail = clean(detail, 200)
        local by_source = State.evidence_aggregates[player_id]
        if not by_source then
            by_source = {}
            State.evidence_aggregates[player_id] = by_source
        end
        local incident = by_source[category]
        if not incident then
            incident = {
                count = 0, emitted = 0, first_ms = now, last_ms = now,
                last_emit_ms = now, detail = detail, blocked = blocked == true,
                direct = direct == true,
            }
            by_source[category] = incident
        end
        incident.count = incident.count + 1
        incident.last_ms = now
        incident.detail = detail
        incident.blocked = incident.blocked or blocked == true
        incident.direct = incident.direct or direct == true
        if incident.count == 1 then
            append_evidence(player_id, category, detail, blocked, direct, now)
            incident.emitted = 1
            State.counters.evidence_aggregated = State.counters.evidence_aggregated + 1
        end
        return incident
    end

    local function flush_evidence_aggregates(force, now, only_player_id)
        now = tonumber(now) or now_ms()
        for player_id, by_source in pairs(State.evidence_aggregates) do
            if only_player_id == nil or tonumber(only_player_id) == tonumber(player_id) then
                for category, incident in pairs(by_source) do
                    local pending = (tonumber(incident.count) or 0) - (tonumber(incident.emitted) or 0)
                    if pending > 0 and (force == true
                        or now - (tonumber(incident.last_emit_ms) or now) >= EVIDENCE_AGGREGATE_MS) then
                        local elapsed = math.max(0, now - (tonumber(incident.first_ms) or now))
                        append_evidence(player_id, category,
                            ("%s; aggregate x%d during %dms"):format(
                                clean(incident.detail, 170), tonumber(incident.count) or 0, elapsed),
                            incident.blocked == true, incident.direct == true, now)
                        incident.emitted = incident.count
                        incident.last_emit_ms = now
                        State.counters.evidence_aggregated = State.counters.evidence_aggregated + 1
                    end
                end
            end
        end
    end

    local function evidence_report()
        local attack = State.attack
        local lines = {
            "CSCRIPT_CRASH_SHIELD_EVIDENCE_V2",
            "Privacy=session-local player ids only; no names, Rockstar ids, IPs, account ids, or persistent player records",
            "PayloadPolicy=no raw event payload bytes; bounded shape, hash, count, and validation summaries only",
            "Retaliation=false",
            "SessionGeneration=" .. tostring(State.session_generation),
            "AttackActive=" .. tostring(attack.active == true),
            "AttackReason=" .. clean(attack.reason, 160),
            "SuspectedSource=" .. tostring(tonumber(attack.source_id) or -1),
            "Blocked=" .. tostring(total_blocked()),
            "LastAction=" .. clean(attack.last_action, 160),
            "EvidenceLimit=" .. tostring(EVIDENCE_LIMIT),
            "EvidenceDropped=" .. tostring(State.evidence_dropped),
            "UninspectableNodeCollections=" .. tostring(State.counters.node_collections_uninspectable or 0),
            "ValidatorInternalErrors=" .. tostring(State.counters.validator_internal_errors or 0),
            "AggregatedIncidentRows=" .. tostring(State.counters.evidence_aggregated or 0),
            "",
            "[session_suspicion]",
            "PlayerId|Score|Blocked|Distinct|LastReason",
        }
        local player_ids = {}
        for player_id in pairs(State.evidence) do player_ids[#player_ids + 1] = player_id end
        table.sort(player_ids)
        for _, player_id in ipairs(player_ids) do
            local entry = State.evidence[player_id]
            local distinct = 0
            for _ in pairs(entry.categories or {}) do distinct = distinct + 1 end
            lines[#lines + 1] = table.concat({ tostring(player_id), tostring(entry.score or 0),
                tostring(entry.blocked or 0), tostring(distinct), clean(entry.last_reason, 120) }, "|")
        end
        lines[#lines + 1] = ""
        lines[#lines + 1] = "[bounded_evidence]"
        lines[#lines + 1] = "Sequence|AtMs|PlayerId|Blocked|Direct|Category|Detail"
        for _, row in ipairs(State.evidence_rows) do
            lines[#lines + 1] = table.concat({ tostring(row.sequence), tostring(row.at_ms),
                tostring(row.source_id), tostring(row.blocked), tostring(row.direct),
                row.category, row.detail }, "|")
        end
        return table.concat(lines, "\n")
    end

    local function flush_evidence(force, explicit_export)
        -- Ordinary ticks, resets, transitions and unloads never write files.
        -- Preserve the last explicit export's verified status between ticks.
        if explicit_export ~= true then return false, "Automatic diagnostic file logging is disabled." end
        State.evidence_last_flush_ms = now_ms()
        local function failed(detail)
            State.evidence_verified = false
            State.evidence_last_error = clean(detail, 200)
            State.counters.evidence_write_failures = State.counters.evidence_write_failures + 1
            return false, State.evidence_last_error
        end
        if not file_mgr or type(file_mgr.CreateDir) ~= "function"
            or type(file_mgr.WriteFileContent) ~= "function"
            or type(file_mgr.ReadFileContent) ~= "function" then
            return failed("The documented diagnostic file APIs are unavailable.")
        end
        local root = module_context and module_context.Root
        if type(root) ~= "string" or root == "" then
            local read, menu_root = pcall(function() return file_mgr.GetMenuRootPath() end)
            if not read or type(menu_root) ~= "string" or menu_root == "" then
                return failed("CScript's diagnostic directory is unavailable.")
            end
            root = menu_root .. "\\Lua\\CScript"
        end
        local directory = root .. "\\Diagnostics"
        local made, result = pcall(file_mgr.CreateDir, directory)
        if not made or result == false then return failed("Could not create the diagnostic directory.") end
        local stamp = timestamp_label():gsub("[^%w_-]", "_")
        local path = directory .. "\\Protection_" .. stamp .. "_"
            .. tostring(State.session_generation) .. "_" .. tostring(State.evidence_sequence) .. ".txt"
        local report = evidence_report()
        local written, accepted = pcall(file_mgr.WriteFileContent, path, report, false)
        if not written or accepted ~= true then return failed("Could not write the protection diagnostic report.") end
        local read, content = pcall(file_mgr.ReadFileContent, path)
        if not read or canonical(content) ~= canonical(report) then
            return failed("Protection diagnostic readback did not match the requested report.")
        end
        State.evidence_path, State.evidence_last_error = path, nil
        State.evidence_dirty, State.evidence_verified = false, true
        State.counters.evidence_writes = State.counters.evidence_writes + 1
        return true, path
    end

    local function apply_attack_suppression()
        local attack = State.attack
        if attack.suppression_applied == true then return true end
        local token = { vehicle = false, weapons = false }
        if vehicle and type(vehicle.RuntimeWritesSuspended) == "function" then
            local ok, value = pcall(vehicle.RuntimeWritesSuspended)
            token.vehicle = ok and value == true
        end
        if weapons and type(weapons.RuntimeWritesSuspended) == "function" then
            local ok, value = pcall(weapons.RuntimeWritesSuspended)
            token.weapons = ok and value == true
        end
        if vehicle_manager and type(vehicle_manager.StopPreview) == "function" then
            pcall(vehicle_manager.StopPreview, "Crash Shield Under Attack")
        end
        if player and type(player.StopOutfitPreview) == "function" then
            pcall(player.StopOutfitPreview, "Crash Shield Under Attack")
        end
        if not token.vehicle and vehicle and type(vehicle.SuspendRuntimeWrites) == "function" then
            pcall(vehicle.SuspendRuntimeWrites)
        end
        if not token.weapons and weapons and type(weapons.SuspendRuntimeWrites) == "function" then
            pcall(weapons.SuspendRuntimeWrites)
        end
        if owned_memory and type(owned_memory.RestoreDomain) == "function" then
            pcall(owned_memory.RestoreDomain, "Vehicle")
            pcall(owned_memory.RestoreDomain, "Weapons")
            pcall(owned_memory.RestoreDomain, "OptionalBuiltins")
        end
        attack.suppression_token = token
        attack.suppression_applied = true
        attack.last_action = "Closed previews and suspended nonessential Vehicle/Weapons memory paths"
        State.evidence_dirty = true
        return true
    end

    local function release_attack_suppression(reason)
        local attack =
            State.attack

        if attack.suppression_applied ~= true then
            return true
        end

        local token =
            attack.suppression_token or {}

        local failures = {}

        local function revalidate(
            label,
            callback
        )
            if type(callback) ~= "function" then
                failures[#failures + 1] = label .. ": restoration callback unavailable"
                return false
            end

            local ok, result, detail =
                pcall(callback)

            if not ok
                or result == false then

                failures[#failures + 1] =
                    label
                    .. ": "
                    .. clean(
                        detail
                            or result
                            or "revalidation failed",
                        120
                    )

                return false
            end

            return true
        end

        if not token.vehicle then
            local released = revalidate(
                "Vehicle",
                vehicle and vehicle.RevalidateRuntimeState
            )
            if released then token.vehicle = true end
        end

        if not token.weapons then
            local released = revalidate(
                "Weapons",
                weapons and weapons.RevalidateRuntimeState
            )
            if released then token.weapons = true end
        end

        if #failures > 0 then
            local detail =
                table.concat(
                    failures,
                    " | "
                )

            attack.last_action =
                clean(
                    "Suppression release pending: "
                    .. detail,
                    160
                )

            State.evidence_dirty = true

            return false, detail
        end

        attack.suppression_token = nil
        attack.suppression_applied = false

        attack.last_action =
            clean(
                reason
                    or "Attack quiet period ended; high-risk paths revalidated",
                160
            )

        State.evidence_dirty = true

        return true
    end

    local function release_suppression_or_defer(reason)
        local released, detail = release_attack_suppression(reason)
        State.suppression_release_pending = released ~= true
        State.suppression_release_retry_ms = released and 0 or now_ms() + 1000
        return released, detail
    end

    local function activate_attack(player_id, category, detail, priority, confidence, now)
        now = tonumber(now) or now_ms()
        local attack = State.attack
        local was_active = attack.active == true
        attack.active = true
        attack.until_ms = math.max(tonumber(attack.until_ms) or 0, now + ATTACK_HOLD_MS)
        priority = math.max(0, tonumber(priority) or 0)
        confidence = math.max(CONFIDENCE_NONE, tonumber(confidence) or CONFIDENCE_NONE)
        local source_id = tonumber(player_id) or -1
        local source_known = source_id >= 0 and source_id <= 31 and source_id ~= local_player_id()
        local current_id = tonumber(attack.source_id) or -1
        local current_known = current_id >= 0 and current_id <= 31 and current_id ~= local_player_id()
        -- An unattributed/lower-confidence event can extend the quiet-period,
        -- but it can never replace a trustworthy session-local attribution.
        local replace_source = not was_active
            or (source_known and not current_known)
            or (source_known == current_known and confidence > (tonumber(attack.source_confidence) or 0))
            or (source_known == current_known and confidence == (tonumber(attack.source_confidence) or 0)
                and priority > (tonumber(attack.priority) or 0))
        if replace_source then
            attack.reason = clean(category .. ": " .. tostring(detail or "blocked inbound abuse"), 160)
            attack.source_id = source_id
            attack.source_confidence = confidence
            attack.priority = priority
        end
        if not was_active then
            attack.since_ms = now
            attack.suppression_pending = true
            State.counters.attack_entries = State.counters.attack_entries + 1
            -- An attack score is internal context, not a second block notification.
        end
        attack.last_action = "Blocked " .. clean(category, 96)
        if not was_active or replace_source then State.evidence_dirty = true end
    end

    local function record_evidence(player_id, category, detail, points, direct, blocked,
        confidence, signal, allow_unattributed_attack)
        player_id = tonumber(player_id) or -1
        if player_id == local_player_id() then return end
        refresh_source_identity(player_id)
        local now = now_ms()
        confidence = math.max(CONFIDENCE_NONE, math.min(CONFIDENCE_CONFIRMED,
            tonumber(confidence) or CONFIDENCE_NONE))
        signal = clean(signal or category, 64)
        aggregate_evidence(player_id, category, detail, blocked, direct, now)
        -- Evidence capture is a Crash Shield safety property. The legacy
        -- modder_detection toggle controls only scoring/escalation, not the
        -- bounded, privacy-safe record of traffic CScript actually rejected.
        if not is_on("modder_detection") then return end
        local entry
        if player_id >= 0 and player_id <= 31 then
            entry = State.evidence[player_id]
            if not entry then
                entry = {
                    score = 0, blocked = 0, categories = {}, high_signals = {},
                    events = {}, last_ms = now,
                }
                State.evidence[player_id] = entry
            end
            local category_state = entry.categories[category]
            if not category_state then
                category_state = { count = 0, last_ms = -100000 }
                entry.categories[category] = category_state
            end
            category_state.count = category_state.count + 1
            category_state.max_confidence = math.max(tonumber(category_state.max_confidence) or 0, confidence)
            local fresh = now - category_state.last_ms >= 5000
            category_state.last_ms = now
            entry.last_ms = now
            entry.last_reason = clean(category, 96)
            if blocked == true then entry.blocked = (entry.blocked or 0) + 1 end
            if fresh then entry.score = math.min(1000, entry.score + math.max(0, tonumber(points) or 0)) end
            if confidence >= CONFIDENCE_HIGH then entry.high_signals[signal] = now end
            if fresh or category_state.count == 1 then
                entry.events[#entry.events + 1] = {
                    time = now, category = clean(category, 64), detail = clean(detail, 160),
                    direct = direct == true, confidence = confidence, signal = signal,
                }
                while #entry.events > EVIDENCE_EVENT_LIMIT do table.remove(entry.events, 1) end
            end
        end

        local score = entry and entry.score or 0
        local distinct_high = 0
        if entry then
            for _, at_ms in pairs(entry.high_signals or {}) do
                if now - (tonumber(at_ms) or -100000) <= ATTACK_HOLD_MS then distinct_high = distinct_high + 1 end
            end
        end
        local confirmed = confidence >= CONFIDENCE_CONFIRMED
        local correlated = confidence >= CONFIDENCE_HIGH and distinct_high >= 2
        local attributed = player_id >= 0 and player_id <= 31
        local qualifies = attributed and (confirmed or correlated)
        if qualifies then
            if player_id >= 0 and not State.detected[player_id] then
                local distinct = 0
                for _ in pairs(entry.categories) do distinct = distinct + 1 end
                State.detected[player_id] = {
                    score = score, distinct = distinct, reason = clean(category, 96), first_flag_ms = now,
                    session_local = true,
                }
            end
            activate_attack(player_id, tostring(category), tostring(detail or "blocked inbound abuse"),
                points, confidence, now)
            if protection_master("protect_auto_isolate") and player_id ~= local_player_id() then
                State.isolated_until[player_id] = math.max(State.isolated_until[player_id] or 0,
                    now + AUTO_ISOLATE_MS)
            end
        elseif not attributed and allow_unattributed_attack == true and confirmed then
            activate_attack(-1, tostring(category), tostring(detail or "blocked inbound abuse"),
                points, confidence, now)
        end
    end

    local ingress_frame
    local function emit_blocked_notice(player_id, category, detail)
        local notifications = module_context and module_context.Notifications
        if not notifications or type(notifications.Protection) ~= "function" then return end
        local now = now_ms()
        if is_ignored(player_id, now) then
            State.counters.notices_suppressed = State.counters.notices_suppressed + 1
            return
        end
        local cache = State.block_notices
        local key = clean(category, 72)
        local prior = cache[key]
        if prior and now >= prior.at and now - prior.at < 5000 then
            prior.count = math.min(1000000000, prior.count + 1)
            return
        end
        -- A second category during the global interval is coalesced internally.
        -- No per-player/hash map can grow under a varying attack payload.
        if now >= State.last_notice_ms and now - State.last_notice_ms < 1200 then return end
        cache[key] = { at=now, count=1 }
        State.last_notice_ms = now
        local summary = clean(detail or "Inbound request rejected", 150)
        if prior and prior.count > 1 then summary = summary .. "; " .. tostring(prior.count) .. " earlier blocks" end
        if player_id >= 0 then summary = summary .. " (session player " .. tostring(player_id) .. ")" end
        pcall(notifications.Protection, key, summary)
    end

    local function blocked_notice(player_id, category, detail)
        -- Delivery waits until the guarded host callback has successfully
        -- returned its event-specific DENY result. A later validator exception
        -- therefore cannot produce a notification for traffic allowed through.
        if ingress_frame then ingress_frame.notice = {player_id, category, detail} end
    end

    local function note(player_id, category, detail, _isolate_hint, _collision_shield)
        State.last_incident_ms = now_ms()
        blocked_notice(player_id, category, detail)
    end

    local function bucket(store, player_id, now, window_ms)
        local key = tostring(player_id)
        local value = store[key]
        if not value or now < value.started or now - value.started >= window_ms then
            value = {
                started = now, total = 0, by_hash = {}, creates = 0,
                nearby = 0, nodes = 0, callbacks = 0,
            }
            store[key] = value
        end
        return value
    end

    local function validate_script_event_args(args)
        -- Cherax builds can expose legitimate event argument containers through
        -- userdata/proxy tables. Treat that host-shape uncertainty as
        -- uninspectable/fail-open rather than blocking player interaction.
        if type(args) ~= "table" or getmetatable(args) ~= nil then
            return nil, 0, "payload container is host-opaque"
        end
        local count, maximum = 0, 0
        for key, value in pairs(args) do
            count = count + 1
            if count > EVENT_ARGUMENT_LIMIT then return false, count, "argument count exceeds 64" end
            if not integer_number(key) or key < 1 or key > EVENT_ARGUMENT_LIMIT then
                return false, count, "non-array argument key"
            end
            -- Lua integers hold the full signed 64-bit event word. Only floats
            -- need the exact-integer bound; abs(INT64_MIN) also overflows.
            if not integer_number(value) or (math.type(value) ~= "integer"
                and math.abs(value) > 9007199254740991) then
                return false, count, "non-finite/non-integer argument"
            end
            if key > maximum then maximum = key end
        end
        if count < 1 or maximum ~= count or type(args[1]) ~= "number" then
            return false, count, "missing or sparse event hash/arguments"
        end
        return true, count, nil
    end

    local function script_filters_active()
        if protection_master("protect_script_events") then return true end
        for _, feature in ipairs(EXTRA_FEATURES) do
            local key = feature[1]
            if key ~= "protect_blame_attribution" and key ~= "protect_ped_motion"
                and key ~= "protect_object_physics" and key ~= "protect_vehicle_physics"
                and key ~= "protect_remote_camera_data" and key ~= "protect_ped_spawns"
                and key ~= "protect_vehicle_spawns" and key ~= "protect_object_spawns" and protection_master(key) then return true end
        end
        return false
    end

    local function protect_script_events_handler(sender, args)
        if not started then return false end
        local desync=is_on("desync_protection") and State.desync.backend_available
        if not desync and not script_filters_active() and not has_manual_blocks() then return false end
        local now = now_ms()
        local player_id, source_state = sender_identity(sender)
        if player_id==local_player_id() then return false end
        local trusted_remote = source_state == "trusted" and player_id >= 0
        -- Explicit user blocks own an ingress dependency and precede optional
        -- payload inspection, including host-opaque argument containers.
        if trusted_remote and is_isolated(player_id, now) then
            State.counters.events_blocked = State.counters.events_blocked + 1
            aggregate_evidence(player_id, "session-local quarantine", "script event rejected", true, false, now)
            blocked_notice(player_id, "Blocked player traffic", "Script event rejected")
            return true
        end
        if not desync and not script_filters_active() then return false end
        local valid, argument_count, shape_error = validate_script_event_args(args)
        if valid ~= true then
            if valid == false and protection_master("protect_script_events") then
                State.counters.events_blocked = State.counters.events_blocked + 1
                State.counters.malformed_blocked = State.counters.malformed_blocked + 1
                local detail = ("%s (count=%d)"):format(tostring(shape_error), tonumber(argument_count) or 0)
                note(player_id, "Malformed script event", detail)
                record_evidence(player_id, "malformed script event", detail, 45, false, true,
                    CONFIDENCE_LOW, "script-shape")
                return true
            end
            return false -- Unknown host container/failed inspection is not an attack.
        end
        local signed_hash = args[1] & 0xFFFFFFFF
        if signed_hash >= 0x80000000 then signed_hash = signed_hash - 0x100000000 end
        if desync and trusted_remote and argument_count >= 4 and signed_hash == -901348601 then
            State.desync.blocked=math.min(1000000000,(State.desync.blocked or 0)+1)
            State.desync.last_block_ms=now
            aggregate_evidence(player_id,"remote bail request","TU1.73 remote bail request rejected",true,false,now)
            blocked_notice(player_id,"Remote session bail","Freemode session-bail request rejected")
            return true
        end
        if not script_filters_active() then return false end
        local policy = State.desync.backend_available and SCRIPT_POLICIES[signed_hash] or nil
        if policy and trusted_remote then
            local label, detail
            if protection_master("protect_script_schema") and argument_count < policy.words then
                label, detail = "Truncated freemode request", policy.receiver .. " requires " .. tostring(policy.words) .. " words"
            elseif argument_count >= policy.words then
                if policy.sender and protection_master("protect_event_identity") and args[policy.sender] ~= player_id then
                    label, detail = "Forged event sender", "Bounty request sender differs from the host-resolved sender"
                elseif protection_master(policy.key)
                    and (not policy.forced_activity or args[9] ~= 0 or args[10] ~= 0)
                    and (not policy.local_target or args[policy.local_target] == local_player_id()) then
                    label, detail = policy.label, "Incoming freemode request rejected"
                end
            end
            if label then
                State.counters.events_blocked = State.counters.events_blocked + 1
                note(player_id, label, detail)
                aggregate_evidence(player_id, label, detail, true, false, now)
                return true
            end
        end
        if not protection_master("protect_script_events") then return false end

        local hash = args[1]
        local value = bucket(State.event_buckets, player_id, now, EVENT_WINDOW_MS)
        value.total = value.total + 1
        local hash_count = value.by_hash[hash]
        -- At most EVENT_TOTAL_LIMIT distinct hashes are retained per source
        -- window. Once the total limit is crossed, novel hash values are not
        -- allowed to grow the bucket map.
        if hash_count ~= nil or value.total <= EVENT_TOTAL_LIMIT then
            hash_count = (hash_count or 0) + 1
            value.by_hash[hash] = hash_count
        else
            hash_count = 0
        end

        if not value.rate_reported and (value.total > EVENT_TOTAL_LIMIT or hash_count > EVENT_REPEAT_LIMIT) then
            value.rate_reported = true
            aggregate_evidence(player_id, "script traffic burst",
                ("events=%d repeats=%d args=%d; allowed"):format(value.total, hash_count, argument_count),
                false, false, now)
        end
        return false
    end

    local function inspect_sync_node(node)
        if node == nil then return false, "nil sync node" end
        local get_type = object_member(node, "GetNodeType")
        -- Some valid Cherax callbacks expose only partial node metadata. Its
        -- missing or failing accessors do not establish a malformed payload.
        if get_type == nil then return false, nil end
        if type(get_type) ~= "function" then return false, nil end
        local ok_type, node_type = pcall(get_type, node)
        if not ok_type then return false, nil end
        if not (sync_node_type and sync_node_type.CPedGameStateDataNode ~= nil)
            or node_type ~= sync_node_type.CPedGameStateDataNode then
            return false, nil
        end
        local cast = object_member(node, "As")
        if type(cast) ~= "function" then return false, nil end
        local ok_cast, data = pcall(cast, node, "CPedGameStateDataNode")
        if not ok_cast or data == nil then return false, nil end
        local ok_mount, on_mount = pcall(function() return data.onMount end)
        if not ok_mount then return false, nil end
        return on_mount == true, nil
    end

    local function validate_sync_nodes(updated_nodes)
        local kind = type(updated_nodes)
        if kind ~= "table" and kind ~= "userdata" then
            return SYNC_UNINSPECTABLE, 0,
                "host node collection is opaque (luaType=" .. tostring(type(updated_nodes)) .. ")"
        end
        if kind == "userdata" or getmetatable(updated_nodes) ~= nil then
            -- Cherax documents length/index iteration, not a requirement for
            -- a plain Lua table. Snapshot only bounded, readable host slots.
            local ok, count, nodes = pcall(function()
                local count = #updated_nodes
                if not integer_number(count) or count < 0 or count > NODE_ARRAY_LIMIT then return nil end
                local nodes = {}
                for index=1,count do
                    local node = updated_nodes[index]
                    if node == nil then return nil end
                    nodes[index] = node
                end
                return count, nodes
            end)
            if ok and count ~= nil then return SYNC_INSPECTABLE_VALID, count, nil, nodes end
            return SYNC_UNINSPECTABLE, 0, "host node collection cannot be read within bounds"
        end
        local ok, state, count, detail = pcall(function()
            local observed, maximum = 0, 0
            for key, node in pairs(updated_nodes) do
                observed = observed + 1
                if observed > NODE_ARRAY_LIMIT then
                    return SYNC_INSPECTABLE_INVALID, observed, "node count exceeds 192"
                end
                if not integer_number(key) or key < 1 or key > NODE_ARRAY_LIMIT then
                    return SYNC_INSPECTABLE_INVALID, observed, "non-array sync-node key"
                end
                if node == nil then
                    return SYNC_INSPECTABLE_INVALID, observed, "nil sync node"
                end
                if key > maximum then maximum = key end
            end
            if maximum ~= observed then
                return SYNC_INSPECTABLE_INVALID, observed, "sparse sync-node collection"
            end
            return SYNC_INSPECTABLE_VALID, observed, nil
        end)
        if not ok then
            return SYNC_UNINSPECTABLE, 0,
                "host node collection enumeration is unavailable"
        end
        return state, count, detail, state == SYNC_INSPECTABLE_VALID and updated_nodes or nil
    end

    local function validation_vector_components(value)
        local kind = type(value)
        if kind ~= "table" and kind ~= "userdata" then return nil, nil, nil, false end
        local ok, x, y, z = pcall(vector_components, value)
        if ok and x ~= nil and y ~= nil and z ~= nil then return x, y, z, true end
        -- Compat collapses incomplete reads to nil. Preserve independently
        -- readable axes without treating an unavailable host getter as malformed.
        local readable = true
        local function axis(lower, upper, index)
            local accepted, component = pcall(function()
                return tonumber(value[lower] or value[upper] or value[index])
            end)
            if not accepted then readable = false; return nil end
            return component
        end
        x, y, z = axis("x", "X", 1), axis("y", "Y", 2), axis("z", "Z", 3)
        return x, y, z, readable
    end

    local function safe_position_components(position)
        local x, y, z, readable = validation_vector_components(position)
        if (type(x) == "number" and not finite_number(x))
            or (type(y) == "number" and not finite_number(y))
            or (type(z) == "number" and not finite_number(z)) then
            return nil, nil, nil, "non-finite or partial position"
        end
        if not readable or (x == nil and y == nil and z == nil) then return nil, nil, nil, nil end
        if not (finite_number(x) and finite_number(y) and finite_number(z)) then
            return nil, nil, nil, "non-finite or partial position"
        end
        if math.abs(x) > 1000000 or math.abs(y) > 1000000 or math.abs(z) > 1000000 then
            return nil, nil, nil, "position outside bounded world range"
        end
        return x, y, z, nil
    end

    local NUMERIC_NODES = {
        { key="protect_ped_motion", class="CPedMovementDataNode", scalars={"DesiredMoveBlendRatioX","DesiredMoveBlendRatioY","DesiredPitch","MaxMoveBlendRatio"}, vectors={} },
        { key="protect_ped_motion", class="CPedOrientationDataNode", scalars={"currentHeading","desiredHeading"}, vectors={} },
        { key="protect_object_physics", class="CObjectCreationDataNode", scalars={"ScriptGrabRadius"}, vectors={"ScriptGrabPosition","dummyPosition","objectPosition"} },
        { key="protect_vehicle_physics", class="CVehicleControlDataNode", scalars={"BVTHStoppingDist","StickY","SubCarDive","SubCarPitch","TargetGravityScale","brakePedal","subCarYaw","throttle","topSpeedPercent"}, vectors={} },
        { key="protect_vehicle_physics", class="CVehicleSteeringDataNode", scalars={"SteeringAngle"}, vectors={} },
        { key="protect_vehicle_physics", class="CHeliControlDataNode", scalars={"BVTHStoppingDist","StickY","SubCarDive","SubCarPitch","TargetGravityScale","brakePedal","jetPackStrafeForceScale","jetPackThrusterThrottle","pitchControl","rollControl","subCarYaw","throttle","throttleControl","topSpeedPercent","yawControl"}, vectors={} },
        { key="protect_vehicle_physics", class="CPlaneControlDataNode", scalars={"BVTHStoppingDist","StickY","SubCarDive","SubCarPitch","TargetGravityScale","brake","brakePedal","pitchControl","rollControl","subCarYaw","throttle","throttleControl","topSpeedPercent","verticalFlightMode","yawControl"}, vectors={} },
        { key="protect_vehicle_physics", class="CBoatGameStateDataNode", scalars={"AnchorLodDistance","BuoyancyForceMultiplier"}, vectors={} },
        { key="protect_vehicle_physics", class="CVehicleProximityMigrationDataNode", scalars={"SpeedMultiplier"}, vectors={"position"} },
        { key="protect_remote_camera_data", class="CPlayerCameraDataNode", scalars={"eulersX","eulersZ"}, vectors={"LookAtPosition","Position","lockOnTargetOffset","playerToTargetAimOffset"} },
    }
    local function typed_node(node, class)
        local node_type = sync_node_type and sync_node_type[class]
        if node_type == nil then return nil end
        local get_type, cast = object_member(node, "GetNodeType"), object_member(node, "As")
        if type(get_type) ~= "function" or type(cast) ~= "function" then return nil end
        local ok, actual = pcall(get_type, node)
        if not ok or actual ~= node_type then return nil end
        local accepted, data = pcall(cast, node, class)
        return accepted and data or nil
    end
    local function spawn_filters_active()
        for _, key in pairs(SPAWN_NODES) do if protection_master(key) then return true end end
        return false
    end
    local function refresh_spawn_position(now)
        local spawn = State.spawn
        if not spawn_filters_active() then spawn.position=nil; spawn.sampled_at=-100000; return end
        if now >= spawn.sampled_at and now-spawn.sampled_at < 250 then return end
        spawn.sampled_at=now
        spawn.position=nil
        if not gta or type(gta.GetLocalPed) ~= "function" then return end
        local ok, ped = pcall(gta.GetLocalPed)
        if not ok or ped == nil then return end
        local x,y,z = safe_position_components(object_member(ped, "Position"))
        if x then spawn.position={x=x,y=y,z=z} end
    end
    local function spawn_node_class(node)
        local get_type = object_member(node, "GetNodeType")
        if type(get_type) == "function" then
            local ok, value = pcall(get_type, node)
            if ok and value ~= nil and sync_node_type then
                if sync_node_type.CPlayerCreationDataNode ~= nil
                    and value == sync_node_type.CPlayerCreationDataNode then return "player" end
                for class, key in pairs(SPAWN_NODES) do
                    if sync_node_type[class] ~= nil and value == sync_node_type[class] then return key end
                end
            end
        end
        local get_name = object_member(node, "GetNodeName")
        if type(get_name) == "function" then
            local ok, name = pcall(get_name, node)
            if ok and name == "CPlayerCreationDataNode" then return "player" end
            if ok then return SPAWN_NODES[name] end
        end
    end
    local function spawn_model_class(model_hash)
        if not integer_number(model_hash) or not gta or type(gta.GetModelInfoFromHash) ~= "function" then return nil end
        local ok, info = pcall(gta.GetModelInfoFromHash, model_hash)
        if not ok or info == nil then return nil end
        -- Ped models are also used by real player characters. Only an explicit
        -- NPC creation node can prove that a ped belongs to the NPC filter.
        for _, spec in ipairs({{"IsVehicle","protect_vehicle_spawns"},{"IsObject","protect_object_spawns"}}) do
            local method = object_member(info, spec[1])
            if type(method) == "function" then
                local read, matches = pcall(method, info)
                if read and matches == true then return spec[2] end
            end
        end
    end
    local function blocked_spawn(nodes, model_hash, px, py, pz, now)
        local spawn = State.spawn
        refresh_spawn_position(now)
        local origin = spawn.position
        if not px or not origin or now < spawn.sampled_at or now-spawn.sampled_at > 1000 then
            spawn.unresolved=math.min(1000000000,spawn.unresolved+1)
            return nil
        end
        local dx,dy,dz=px-origin.x,py-origin.y,pz-origin.z
        if dx*dx+dy*dy+dz*dz > spawn.radius*spawn.radius then return nil end
        local kind
        for _, node in ipairs(nodes or {}) do
            local key = spawn_node_class(node)
            if key == "player" then return nil end
            if key and protection_master(key) then kind=kind or key end
        end
        kind = kind or spawn_model_class(model_hash)
        if not kind then
            spawn.unresolved=math.min(1000000000,spawn.unresolved+1)
        elseif protection_master(kind) then
            return kind
        end
    end
    local function node_filters_active()
        if protection_master("protect_sync_nodes") or protection_master("protect_attachments")
            or protection_master("protect_blame_attribution") or spawn_filters_active() then return true end
        for _, spec in ipairs(NUMERIC_NODES) do if protection_master(spec.key) then return true end end
        return false
    end
    -- These getters are conditional in the installed node contract. Stale
    -- values in an omitted field do not describe the current inbound update.
    local CONDITIONAL_NUMERIC_FIELDS = {
        CVehicleProximityMigrationDataNode = {
            position = { "isMoving", true },
        },
        CObjectCreationDataNode = {
            ScriptGrabRadius = { "ScriptGrabbedFromWorld", true },
            ScriptGrabPosition = { "ScriptGrabbedFromWorld", true },
            objectPosition = { "hasGameObject", false },
        },
    }
    local function numeric_field_active(class, data, name)
        local fields = CONDITIONAL_NUMERIC_FIELDS[class]
        local gate = fields and fields[name]
        if not gate then return true end
        -- Preserve false distinctly from missing/unreadable metadata. Do not
        -- even access a dependent getter until its exact activation is proven.
        local ok, active = pcall(function() return data[gate[1]] end)
        return ok and active == gate[2]
    end
    local function inspect_node_values(node, is_create, player_id)
        if is_create and player_id >= 0 and player_id ~= local_player_id()
            and protection_master("protect_blame_attribution") then
            local data = typed_node(node, "CPedCreationDataNode")
            if data and object_member(data,"hasAttDamageToPlayer") == true
                and object_member(data,"attDamageToPlayer") == local_player_id() then
                return "Remote attribution", "Remote ped creation attributes damage to the local player"
            end
        end
        for _, spec in ipairs(NUMERIC_NODES) do
            if protection_master(spec.key) then
                local data = typed_node(node, spec.class)
                if data then
                    for _, name in ipairs(spec.scalars) do
                        local value
                        if numeric_field_active(spec.class, data, name) then value = object_member(data, name) end
                        if type(value) == "number" and not finite_number(value) then
                            return "Non-finite entity data", spec.class .. "." .. name
                        end
                    end
                    for _, name in ipairs(spec.vectors) do
                        local value
                        if numeric_field_active(spec.class, data, name) then value = object_member(data, name) end
                        if value ~= nil then
                            local x,y,z,readable = validation_vector_components(value)
                            if (type(x)=="number" and not finite_number(x))
                                or (type(y)=="number" and not finite_number(y))
                                or (type(z)=="number" and not finite_number(z)) then
                                return "Non-finite entity position", spec.class .. "." .. name
                            elseif readable and (x ~= nil or y ~= nil or z ~= nil)
                                and not (finite_number(x) and finite_number(y) and finite_number(z)) then
                                return "Malformed entity position", spec.class .. "." .. name .. ": partial vector"
                            end
                        end
                    end
                end
            end
        end
    end

    local function protect_sync_nodes_handler(is_create, model_hash, position, net_object, updated_nodes)
        if not started then return true end
        local relationship_filter = filter_remote_ghost_nodes
        local filters_active = node_filters_active()
        if not filters_active and not has_manual_blocks() then
            -- This callback stays registered while disabled. Resolve a sender
            -- only for an active selected-player ghost/passive filter.
            local relationship_active = type(remote_relationship_filter_active) == "function"
                and remote_relationship_filter_active() == true
            if not relationship_active then return true end
            local player_id = select(1, net_object_identity(net_object))
            if player_id >= 0 and (type(updated_nodes) == "table" or type(updated_nodes) == "userdata")
                and type(relationship_filter) == "function" then
                pcall(relationship_filter, player_id, updated_nodes)
            end
            return true
        end
        local player_id, source_state = net_object_identity(net_object)
        local now = now_ms()
        local remote_flag = object_member(net_object, "IsRemote")
        if player_id == local_player_id() or remote_flag == false then return true end

        -- World entities and ownership handoffs can lack a player owner.
        -- Their host identity alone cannot justify rejecting entity sync.
        if player_id >= 0 and is_isolated(player_id, now) then
            State.counters.nodes_blocked = State.counters.nodes_blocked + 1
            if is_create then State.counters.creates_blocked = State.counters.creates_blocked + 1 end
            aggregate_evidence(player_id, "session-local quarantine", "entity sync rejected", true, false, now)
            blocked_notice(player_id, "Blocked player traffic", "Entity sync rejected")
            State.attack.until_ms = math.max(State.attack.until_ms or 0, now + ATTACK_HOLD_MS)
            return false
        end

        if not filters_active then
            if player_id >= 0 and type(remote_relationship_filter_active) == "function"
                and remote_relationship_filter_active() == true
                and (type(updated_nodes) == "table" or type(updated_nodes) == "userdata")
                and type(relationship_filter) == "function" then
                pcall(relationship_filter, player_id, updated_nodes)
            end
            return true
        end

        if protection_master("protect_sync_nodes") and type(is_create) ~= "boolean" then
            State.counters.nodes_blocked = State.counters.nodes_blocked + 1
            State.counters.invalid_nodes_blocked = State.counters.invalid_nodes_blocked + 1
            note(player_id, "malformed entity sync", "create flag is not boolean", false, false)
            record_evidence(player_id, "malformed entity sync", "create flag is not boolean", 70, false, true,
                CONFIDENCE_LOW, "create-flag-shape")
            return false
        end
        if protection_master("protect_sync_nodes") and model_hash ~= nil and model_hash ~= 0
            and (not integer_number(model_hash) or math.abs(model_hash) > 9007199254740991) then
            State.counters.nodes_blocked = State.counters.nodes_blocked + 1
            State.counters.invalid_nodes_blocked = State.counters.invalid_nodes_blocked + 1
            note(player_id, "malformed entity sync", "invalid model hash", false, false)
            record_evidence(player_id, "malformed entity sync", "invalid model hash", 70, false, true,
                CONFIDENCE_LOW, "model-hash-shape")
            return false
        end
        local collection_state, node_count, node_error, nodes = validate_sync_nodes(updated_nodes)
        if protection_master("protect_sync_nodes") and collection_state == SYNC_INSPECTABLE_INVALID then
            State.counters.nodes_blocked = State.counters.nodes_blocked + 1
            State.counters.invalid_nodes_blocked = State.counters.invalid_nodes_blocked + 1
            local detail = ("%s (count=%d)"):format(tostring(node_error), tonumber(node_count) or 0)
            note(player_id, "malformed entity sync", detail, false, false)
            record_evidence(player_id, "malformed entity sync", detail, 70, false, true,
                CONFIDENCE_HIGH, "node-collection-shape")
            return false
        elseif collection_state == SYNC_UNINSPECTABLE then
            -- Opaque userdata/host collections are ABI uncertainty, not attack
            -- evidence. Independently safe callback fields remain validated;
            -- structural node inspection is skipped and traffic proceeds. The
            -- bounded read-only observer below may try documented accessors.
            State.counters.node_collections_uninspectable =
                State.counters.node_collections_uninspectable + 1
        end
        local px, py, pz, position_error = safe_position_components(position)
        if protection_master("protect_sync_nodes") and position_error then
            State.counters.nodes_blocked = State.counters.nodes_blocked + 1
            State.counters.invalid_nodes_blocked = State.counters.invalid_nodes_blocked + 1
            note(player_id, "malformed entity sync", position_error, false, false)
            record_evidence(player_id, "malformed entity sync", position_error, 70, false, true,
                CONFIDENCE_LOW, "position-shape")
            return false
        end

        if is_create == true and (source_state == "trusted" or remote_flag == true)
            and spawn_filters_active() then
            local key=blocked_spawn(nodes, model_hash, px, py, pz, now)
            if key then
                State.counters.nodes_blocked=State.counters.nodes_blocked+1
                State.counters.creates_blocked=State.counters.creates_blocked+1
                local category=key=="protect_ped_spawns" and "Ped spawn" or key=="protect_vehicle_spawns" and "Vehicle spawn" or "Object spawn"
                local kind=key=="protect_ped_spawns" and "ped" or key=="protect_vehicle_spawns" and "vehicle" or "object"
                State.spawn.blocked[kind]=math.min(1000000000,State.spawn.blocked[kind]+1)
                State.spawn.last_block_ms=now
                local detail="Incoming creation rejected within the configured spawn radius"
                note(player_id, category, detail)
                aggregate_evidence(player_id, category, detail, true, false, now)
                return false
            end
        end
        if collection_state == SYNC_INSPECTABLE_VALID then
            for _, node in ipairs(nodes) do
                local category, detail = inspect_node_values(node, is_create, player_id)
                if category then
                    State.counters.nodes_blocked = State.counters.nodes_blocked + 1
                    if is_create then State.counters.creates_blocked = State.counters.creates_blocked + 1 end
                    note(player_id, category, detail)
                    aggregate_evidence(player_id, category, detail, true, false, now)
                    return false
                end
                local invalid_mount, integrity_error = false, nil
                if protection_master("protect_attachments") then invalid_mount, integrity_error = inspect_sync_node(node) end
                if integrity_error then
                    State.counters.nodes_blocked = State.counters.nodes_blocked + 1
                    State.counters.invalid_nodes_blocked = State.counters.invalid_nodes_blocked + 1
                    if is_create then State.counters.creates_blocked = State.counters.creates_blocked + 1 end
                    note(player_id, "invalid sync node", integrity_error, false, true)
                    record_evidence(player_id, "invalid sync node", integrity_error, 85, true, true,
                        CONFIDENCE_HIGH, "node-accessor-integrity")
                    return false
                end
                if invalid_mount then
                    State.counters.nodes_blocked = State.counters.nodes_blocked + 1
                    if is_create then State.counters.creates_blocked = State.counters.creates_blocked + 1 end
                    note(player_id, "invalid mount sync", "CPedGameStateDataNode.onMount", false, true)
                    record_evidence(player_id, "invalid mount sync", "CPedGameStateDataNode.onMount", 90, true, true,
                        CONFIDENCE_CONFIRMED, "verified-invalid-mount")
                    return false
                end
            end
        end

        local value = bucket(State.node_buckets, player_id, now, NODE_WINDOW_MS)
        value.callbacks = value.callbacks + 1
        value.nodes = value.nodes + node_count
        if is_create then
            value.creates = value.creates + 1
        end

        local flooding = value.callbacks > NODE_CALLBACK_LIMIT or value.nodes > NODE_TOTAL_LIMIT
            or value.creates > NODE_CREATE_LIMIT
            or value.nearby > NODE_NEARBY_LIMIT
        if flooding and not value.rate_reported then
            value.rate_reported = true
            aggregate_evidence(player_id, "sync traffic burst",
                ("callbacks=%d nodes=%d creates=%d nearby=%d"):format(
                    value.callbacks, value.nodes, value.creates, value.nearby),
                false, false, now)
        end

        -- Only optional processing that consumes remote node objects runs
        -- after the Crash Shield has validated and rate-limited the callback.
        -- The selected-player observer is bounded, exception-contained and
        -- read-only. It also supports the host's opaque userdata collection;
        -- opaque ABI shape remains distinct from malformed inspected traffic.
        if (type(updated_nodes) == "table" or type(updated_nodes) == "userdata") and player_id >= 0
            and type(filter_remote_ghost_nodes) == "function" then
            local ok_filter, filter_error = pcall(filter_remote_ghost_nodes, player_id, updated_nodes)
            if not ok_filter then
                if State.relationship_filter_error_logged ~= true then
                    State.relationship_filter_error_logged = true
                    log_warn("Selected-player relationship filter rejected unsafe node input: " .. clean(filter_error, 160))
                end
                State.counters.validator_internal_errors = State.counters.validator_internal_errors + 1
                count_spawn_ingress("internal_errors")
                aggregate_evidence(-1, "internal validator error",
                    "optional selected-player relationship processor failed open", false, false, now)
                return true
            end
        end
        return true
    end

    local function protect_collision_handler(entity_a, entity_b, material_a, material_b,
        point_a, world_a, point_b, world_b)
        if not started then return true end
        -- Skip the vehicle collision policy while this protection is idle.
        if not protection_master("protect_collision") then return true end
        local now = now_ms()
        if now >= State.collision_shield_until then return true end
        if (entity_a == nil or entity_b == nil) and State.attack.active == true then
            State.counters.collisions_blocked = State.counters.collisions_blocked + 1
            State.counters.invalid_nodes_blocked = State.counters.invalid_nodes_blocked + 1
            record_evidence(-1, "invalid collision input", "missing entity pointer during active attack",
                80, true, true, CONFIDENCE_LOW, "collision-input")
            return false
        end
        local ok_decision, decision = pcall(vehicle_should_collide, entity_a, entity_b, material_a, material_b,
            point_a, world_a, point_b, world_b)
        if not ok_decision then
            if State.attack.active == true then
                State.counters.collisions_blocked = State.counters.collisions_blocked + 1
                record_evidence(-1, "invalid collision input",
                    "CScript collision policy rejected an unsafe entity pointer", 80, true, true,
                    CONFIDENCE_LOW, "collision-input")
                return false
            end
            return true
        end
        if decision ~= nil then return decision end

        local local_ped_pointer = nil
        local local_vehicle_pointer = nil
        if gta and type(gta.GetLocalPed) == "function" then
            local ok, value = pcall(gta.GetLocalPed)
            if ok then local_ped_pointer = value end
        end
        if gta and type(gta.GetLocalVehicle) == "function" then
            local ok, value = pcall(gta.GetLocalVehicle)
            if ok then local_vehicle_pointer = value end
        end

        local a_local = entity_a ~= nil and (entity_a == local_ped_pointer or entity_a == local_vehicle_pointer)
        local b_local = entity_b ~= nil and (entity_b == local_ped_pointer or entity_b == local_vehicle_pointer)
        if not a_local and not b_local then return true end

        local other = a_local and entity_b or entity_a
        local ok_physical, is_physical = pcall(function() return other and other:IsPhysical() end)
        if ok_physical and is_physical == true then
            State.counters.collisions_blocked = State.counters.collisions_blocked + 1
            return false
        end
        if not ok_physical and State.attack.active == true then
            State.counters.collisions_blocked = State.counters.collisions_blocked + 1
            record_evidence(-1, "invalid collision input", "physical-entity validation failed",
                80, true, true, CONFIDENCE_LOW, "collision-input")
            return false
        end
        return true
    end

    local function reaction_argument_shape(args, reaction)
        local parts = {}
        for index, value in ipairs(args) do
            local kind = type(value)
            local item
            if kind == "number" then
                local number = tonumber(value) or 0
                if value == reaction then
                    item = ("%d=reaction:%s"):format(index, tostring(number))
                elseif number == math.floor(number) and number >= -1 and number <= 255 then
                    item = ("%d=number:%d"):format(index, number)
                else
                    item = ("%d=number"):format(index)
                end
            elseif kind == "string" then
                item = ("%d=string(len=%d)"):format(index, #value)
            else
                item = ("%d=%s"):format(index, kind)
            end
            parts[#parts + 1] = item
        end
        return table.concat(parts, ",")
    end

    local function resolve_reaction_sender(args)
        -- Do not guess the numeric ON_REACTION callback layout. The supplied
        -- Cherax API material does not define that event's argument order, and
        -- a wrong numeric guess could isolate/flag an innocent session player.
        -- Only accept an object-like callback argument when it resolves to one
        -- unique, currently available remote player.
        local unique = {}
        local count = 0
        local resolved = -1
        for _, value in ipairs(args) do
            if type(value) ~= "number" then
                local candidate = sender_player_id(value)
                if candidate >= 0 and candidate ~= local_player_id()
                    and orbital_player_available(candidate) and not unique[candidate] then
                    unique[candidate] = true
                    count = count + 1
                    resolved = candidate
                end
            end
        end
        if count == 1 then return resolved end
        return -1
    end

    local function protection_reaction_handler(...)
        if not started or not protection_master("protect_reactions") or not protection_type then return end
        local args = { ... }
        local reaction = nil
        for _, value in ipairs(args) do
            if value == protection_type.CRASH or value == protection_type.KICK
                or value == protection_type.BAD_SCRIPT_EVENT then
                reaction = value
                break
            end
        end
        if reaction == nil then return end

        local sender_id = resolve_reaction_sender(args)
        State.counters.reactions_seen = State.counters.reactions_seen + 1
        if sender_id >= 0 then
            State.counters.reactions_attributed = State.counters.reactions_attributed + 1
        else
            State.counters.reactions_unknown = State.counters.reactions_unknown + 1
            local now = now_ms()
            local shape = reaction_argument_shape(args, reaction)
            local key = "reaction-shape|" .. tostring(reaction)
            local entry = State.notice_log_cache[key]
            if not entry or now - entry.last_ms >= 30000 then
                log_info(("Cherax reaction attribution diagnostic: sender unresolved; args[%d]={%s}")
                    :format(#args, shape))
                State.notice_log_cache[key] = { last_ms = now, suppressed = 0 }
            end
        end

        local label = reaction == protection_type.CRASH and "Cherax crash reaction"
            or reaction == protection_type.KICK and "Cherax kick reaction"
            or "Cherax bad-script-event reaction"
        -- The host already handled this alert. Its undocumented callback
        -- argument order cannot prove a new attack or a CScript block.
        -- Keep it diagnostic: no quarantine, camera/collision changes,
        -- preview cancellation, suspicion points, or runtime suspension.
        aggregate_evidence(sender_id, "Cherax alert", reaction_argument_shape(args, reaction),
            false, false, now_ms())
    end

    local function register_features()
        if State.features_registered then return true end
        if not add_toggle("desync_protection", "Desync Protection",
            "Blocks inbound session-bail requests. Your own exits stay available.", false) then return false end
        if not add_toggle("op_crash_protection", "Crash Protection",
            "Enables CScript's payload filters. Explicit player traffic blocks stay active until cleared.", true) then
            return false
        end
        if not add_toggle("protect_script_events", "Event Validation",
            "Rejects malformed event payloads. Normal traffic bursts stay allowed.", true) then
            return false
        end
        if not add_toggle("protect_sync_nodes", "Entity Validation",
            "Rejects malformed entity data. Normal streaming stays allowed.", true) then
            return false
        end
        if not add_toggle("protect_attachments", "Invalid Mount Filter",
            "Rejects the invalid remote ped mount flag.", true) then
            return false
        end
        if not add_toggle("protect_auto_isolate", "Auto-Isolate Suspicious Senders",
            "Retired. Use Block Player Traffic for an explicit block.", false) then
            return false
        end
        if not add_toggle("protect_collision", "Emergency Collision Shield",
            "Retired. Normal collisions stay enabled.", false) then
            return false
        end
        if not add_toggle("protect_self_isolation", "Nigga baller self-isolation",
            "Filters local physics contacts for this effect's owned actors while enabled. This cannot prevent every engine crash.", false) then
            return false
        end
        if not add_toggle("protect_camera", "Automatic Camera Recovery",
            "Recovers a persistent invalid rendering-camera handle while gameplay is safe. Valid scripted cameras, missions and previews stay intact.", false) then
            return false
        end
        if not add_toggle("protect_reactions", "Record Cherax Alerts",
            "Records Cherax alerts without changing gameplay.", true) then
            return false
        end
        if not add_toggle("modder_detection", "Payload Incident Tracking",
            "Tracks rejected payloads in this session.", true) then
            return false
        end
        if not add_button("protection_status", "Log Protection Status",
            "Writes filter status and block counts to Cherax.log.", function()
                if public_api then public_api.LogStatus() end
            end) then
            return false
        end
        if not add_button("clear_protection_isolation", "Clear Traffic Blocks",
            "Allows traffic from players you blocked in this session.", function()
                if public_api then public_api.ClearIsolation() end
            end) then
            return false
        end
        if not add_button("modder_detection_report", "Save Protection Diagnostics",
            "Saves recent filter incidents without account details.", function()
                if public_api then public_api.ExportEvidence() end
            end) then
            return false
        end
        if not add_button("clear_modder_evidence", "Clear Incident Tracking", "Clears this session's incident scores.", function()
            if public_api then public_api.ClearSuspicion() end
        end) then
            return false
        end
        for _, feature in ipairs(EXTRA_FEATURES) do
            if not add_toggle(feature[1], feature[2], feature[3], feature[4]) then return false end
        end
        State.features_registered = true
        if reconcile_event_handlers then reconcile_event_handlers() end
        return true
    end

    local api = {
        State = State,
        RegisterFeatures = register_features,
        PlayerId = sender_player_id,
        PlayerName = sender_name,
        NetObjectPlayerId = net_object_player_id,
        IsIsolated = is_isolated,
    }

    function api.BeginIngress(name, is_create)
        local frame = { previous = ingress_frame }
        ingress_frame = frame
        if name == "CAN_APPLY_NODE_DATA" then
            count_spawn_ingress("entries")
            if is_create == true then count_spawn_ingress("creates")
            elseif is_create == false then count_spawn_ingress("updates") end
        end
        return frame
    end

    function api.EndIngress(frame, name, accepted, result)
        if not frame then return end
        ingress_frame = frame.previous
        local denied = (name == "SCRIPTED_GAME_EVENT" and result == true)
            or (name == "CAN_APPLY_NODE_DATA" and result == false)
        if name == "CAN_APPLY_NODE_DATA" then
            if not accepted then count_spawn_ingress("internal_errors")
            elseif denied then count_spawn_ingress("rejected_total") end
        end
        if accepted and denied and frame.notice then
            emit_blocked_notice(table.unpack(frame.notice))
        end
    end

    local function camera_native(kind, key, ...)
        local natives = module_context and module_context.Natives
        if not started or not natives or type(natives.Try) ~= "function" then
            return false, "Camera native adapter unavailable"
        end
        local ok, accepted, value = pcall(natives.Try, kind, CAMERA_H[key], ...)
        if not ok or accepted ~= true then return false, key .. " read/request rejected" end
        if kind == "bool" and type(value) ~= "boolean" then return false, key .. " returned no boolean" end
        if kind == "int" and not integer_number(value) then return false, key .. " returned no integer" end
        return true, value
    end

    local function studio_camera_service()
        local ui = module_context and module_context.CScript and module_context.CScript.UI
        return ui and ui.Components or nil
    end

    local function camera_owner()
        local components = studio_camera_service()
        if components and type(components.studio_camera_snapshot) == "function" then
            local ok, snapshot = pcall(components.studio_camera_snapshot)
            if not ok then return "unavailable studio owner" end
            if snapshot and (snapshot.active or snapshot.handing_off) then return snapshot.owner or "studio" end
        end
        local ui = module_context and module_context.State and module_context.State.UI
        return ui and ui.PreviewCameraOwner or nil
    end

    local function camera_generation()
        return module_context and module_context.Runtime and module_context.Runtime.generation or 0
    end

    local function camera_result(status, detail, now, failure)
        local camera = State.camera
        local was_pending = camera.pending ~= nil
        camera.status, camera.detail, camera.last_result_ms = status, detail, now
        camera.request, camera.pending, camera.samples, camera.verified_samples = nil, nil, 0, 0
        if failure then State.counters.camera_failures = State.counters.camera_failures + 1 end
        if was_pending or failure then
            log_info("Camera recovery " .. status .. ": " .. detail)
        end
    end

    local function cancel_camera_recovery(detail)
        State.camera = new_camera_recovery_state()
        State.camera.status, State.camera.detail = "CANCELLED", detail
    end

    -- Native-thread snapshot. Unknown native readback is not permission to stop
    -- a camera. Legitimate scripted views frequently return gameplay=false.
    local function camera_observation(now, manual)
        if camera_owner() ~= nil then return nil, "Studio camera is open; close its view first", "STUDIO" end
        local snapshot = { generation = State.session_generation, loader_generation = camera_generation(), ms = now }
        for _, field in ipairs({ {"player", "PLAYER_ID"}, {"ped", "PLAYER_PED_ID"} }) do
            local ok, value = camera_native("int", field[2])
            if not ok then return nil, value, "UNAVAILABLE" end
            snapshot[field[1]] = value
        end
        if snapshot.player < 0 or snapshot.player > 31 or snapshot.ped <= 0 then
            return nil, "No current character", "DEFERRED"
        end
        local ok, value = camera_native("bool", "DOES_ENTITY_EXIST", snapshot.ped)
        if not ok then return nil, value, "UNAVAILABLE" end
        if not value then return nil, "Current character is unavailable", "DEFERRED" end
        ok, value = camera_native("int", "GET_ENTITY_MODEL", snapshot.ped)
        if not ok then return nil, value, "UNAVAILABLE" end
        if value == 0 then return nil, "Current character model is unavailable", "UNAVAILABLE" end
        snapshot.model = value
        local guards = {
            {"IS_ENTITY_DEAD", "Character is dead", snapshot.ped, false},
            {"IS_CUTSCENE_ACTIVE", "A cutscene is active"}, {"IS_CUTSCENE_PLAYING", "A cutscene is playing"},
            {"NETWORK_IS_IN_SPECTATOR_MODE", "Spectator view is active"},
            {"NETWORK_IS_IN_TRANSITION", "Session transition is active"},
            {"IS_PLAYER_SWITCH_IN_PROGRESS", "Character switch is active"},
            {"IS_SCREEN_FADED_OUT", "Game screen is faded out"},
            {"IS_SCREEN_FADING_OUT", "Game screen is fading"}, {"IS_SCREEN_FADING_IN", "Game screen is fading"},
            {"IS_CINEMATIC_CAM_RENDERING", "Cinematic view is active"},
            {"IS_PAUSE_MENU_ACTIVE", "Game pause menu is open"},
        }
        for _, guard in ipairs(guards) do
            if guard[3] ~= nil then ok, value = camera_native("bool", guard[1], guard[3], guard[4])
            else ok, value = camera_native("bool", guard[1]) end
            if not ok then return nil, value, "UNAVAILABLE" end
            if value then return nil, guard[2], "DEFERRED" end
        end
        ok, value = camera_native("bool", "IS_PLAYER_CONTROL_ON", snapshot.player)
        if not ok then return nil, value, "UNAVAILABLE" end
        snapshot.controls = value
        -- Disabled controls can be part of the unwanted camera state the user
        -- explicitly asked to recover. Keep this guard for automatic recovery;
        -- a manual reset changes only camera rendering, never player controls.
        if not value and not manual then
            return nil, "GTA has disabled character controls; property/menu camera may be active", "DEFERRED"
        end
        ok, value = camera_native("bool", "IS_GAMEPLAY_CAM_RENDERING")
        if not ok then return nil, value, "UNAVAILABLE" end
        snapshot.gameplay = value
        ok, value = camera_native("int", "GET_RENDERING_CAM")
        if not ok then return nil, value, "UNAVAILABLE" end
        snapshot.camera = value
        if not manual and not snapshot.gameplay then
            for _, key in ipairs({"GET_MISSION_FLAG", "NETWORK_IS_ACTIVITY_SESSION"}) do
                local read, active = camera_native("bool", key)
                if not read then return nil, active, "UNAVAILABLE" end
                if active then return nil, "Mission or activity camera is protected", "DEFERRED" end
            end
            local read, active = camera_native("bool", "NETWORK_IS_SESSION_ACTIVE")
            if not read or not active then return nil, "Session is not ready", "DEFERRED" end
            read, active = camera_native("bool", "DOES_CAM_EXIST", snapshot.camera)
            if not read then return nil, active, "UNAVAILABLE" end
            snapshot.invalid_camera = not active and snapshot.camera > 0
        end
        return snapshot
    end

    local function same_camera_subject(a, b)
        return a and b and a.generation == b.generation and a.loader_generation == b.loader_generation
            and a.player == b.player and a.ped == b.ped and a.model == b.model
    end

    -- Render-safe: this records intent against the last scheduler snapshot.
    -- No native, timer native, persistence or camera callback runs here.
    function api.QueueCameraRecovery()
        if not started then return false, "Camera recovery is unavailable while CScript is stopped" end
        local camera = State.camera
        if camera.request or camera.pending then return false, "Camera recovery is already pending" end
        camera.request = { generation = State.session_generation, loader_generation = camera_generation(),
            subject = camera.observed }
        camera.status, camera.detail = "QUEUED", "Recovery queued"
        return true
    end

    function api.CameraRecoverySnapshot()
        local camera = State.camera
        return {
            status = camera.status, detail = camera.detail, attempts = camera.attempts,
            pending = camera.request ~= nil or camera.pending ~= nil,
            automatic = protection_master("protect_camera"),
            requests = State.counters.camera_requests, recovered = State.counters.camera_resets,
            failures = State.counters.camera_failures,
        }
    end

    local function submit_camera_recovery(pending, now)
        -- Match CheraxDefender's immediate six-argument local reset. There is no
        -- camera deletion, player manipulation, or unrelated post-effect wipe.
        local ok, detail = camera_native("void", "RENDER_SCRIPT_CAMS", false, false, 0, true, true, 0)
        if not ok then camera_result("REJECTED", detail, now, true); return false end
        local camera = State.camera
        pending.attempts, pending.last_attempt_ms = pending.attempts + 1, now
        camera.attempts, camera.status, camera.detail = pending.attempts, "REQUESTED", "Waiting for gameplay camera"
        State.counters.camera_requests = State.counters.camera_requests + 1
        return true
    end

    local function camera_recovery_tick(now)
        local camera = State.camera
        local automatic = protection_master("protect_camera")
        if camera.pending and not camera.pending.manual and not automatic then
            camera_result("CANCELLED", "Automatic camera recovery disabled", now, false)
        end
        if not camera.request and not camera.pending and not automatic then return end
        local interval = (camera.request or camera.pending) and 100 or 500
        if not camera.request and now >= camera.last_scan_ms and now - camera.last_scan_ms < interval then return end
        if camera.pending and now - camera.last_scan_ms > 1000 then
            camera_result("CANCELLED", "Recovery observation paused; request again for the current camera", now, false)
            camera.observed, camera.last_scan_ms = nil, now
            return
        end
        if now - camera.last_scan_ms > 1000 then camera.samples = 0 end
        if now < camera.last_scan_ms then
            camera_result("CANCELLED", "Camera clock changed", now, false)
            camera.observed = nil
        end
        camera.last_scan_ms = now
        if camera.request and camera_owner() ~= nil then
            -- An explicit manual recovery may close the studio through its
            -- owner. A failed cleanup keeps the lease and forbids a global reset.
            local components = studio_camera_service()
            local ok, released = false, false
            if components and type(components.stop_studio_camera) == "function" then
                ok, released = pcall(components.stop_studio_camera, "manual camera recovery")
            end
            if not ok or released ~= true or camera_owner() ~= nil then
                camera_result("STUDIO", "Studio view could not close; camera recovery deferred", now, false)
                return
            end
        end
        local manual = camera.request ~= nil or (camera.pending and camera.pending.manual == true)
        local observed, reason, status = camera_observation(now, manual)
        if not observed then
            camera.observed = nil
            camera_result(status, reason, now, status == "UNAVAILABLE" and camera.pending ~= nil)
            return
        end
        local previous = camera.observed
        camera.observed = observed
        if previous and (not same_camera_subject(previous, observed) or previous.camera ~= observed.camera) then
            camera.samples = 0
        end
        if camera.pending then
            local pending = camera.pending
            if not same_camera_subject(pending.subject, observed)
                or (not observed.gameplay and observed.camera ~= 0 and observed.camera ~= -1
                    and observed.camera ~= pending.subject.camera) then
                camera_result("CANCELLED", "Character or camera changed during recovery", now, false)
                return
            end
            if observed.gameplay then
                camera.verified_samples = camera.verified_samples + 1
                if camera.verified_samples >= 2 then
                    State.counters.camera_resets = State.counters.camera_resets + 1
                    camera_result("RECOVERED", "Gameplay camera restored", now, false)
                end
                return
            end
            if not pending.manual and observed.invalid_camera ~= true then
                camera_result("CANCELLED", "Rendering camera is valid; automatic recovery cancelled", now, false)
                return
            end
            camera.verified_samples = 0
            if now - pending.started_ms >= 1800 then
                camera_result("INEFFECTIVE", "Camera is still controlled elsewhere; recovery was not verified", now, true)
            elseif pending.attempts < 2 and now - pending.last_attempt_ms >= 750
                and observed.camera == pending.subject.camera then
                submit_camera_recovery(pending, now)
            end
            return
        end
        local request = camera.request
        if request then
            camera.request = nil
            if request.generation ~= State.session_generation or request.loader_generation ~= camera_generation()
                or (request.subject and (not same_camera_subject(request.subject, observed)
                    or (not observed.gameplay and request.subject.camera ~= observed.camera)
                    or now - request.subject.ms > 1500)) then
                camera_result("CANCELLED", "Character or camera changed before recovery; request again", now, false)
                return
            end
        end
        if observed.gameplay then
            camera.samples = 0
            if request then camera_result("ALREADY_GAMEPLAY", "Gameplay camera is already active", now, false)
            elseif now - camera.last_result_ms > 3000 then camera.status, camera.detail = "MONITORING", "Gameplay camera active" end
            return
        end
        if not request then
            if not automatic then camera.samples = 0; camera.status, camera.detail = "DISABLED", "Automatic recovery disabled"; return end
            -- A recent traffic block is not proof a scripted camera is hostile.
            -- Only a stable positive handle which DOES_CAM_EXIST rejects can be
            -- automatically recovered. Zero/-1 and valid cameras stay untouched.
            if not observed.invalid_camera then
                camera.samples = 0
                camera.status, camera.detail = "MONITORING", "Scripted camera left intact"
                return
            end
            if camera.last_auto_camera == observed.camera and now - camera.last_auto_incident < ATTACK_HOLD_MS then return end
            camera.samples = camera.samples + 1
            if camera.samples < 5 then camera.status, camera.detail = "CHECKING", "Checking invalid rendering camera"; return end
            camera.last_auto_incident, camera.last_auto_camera = now, observed.camera
        end
        camera.samples, camera.verified_samples = 0, 0
        camera.pending = { subject = observed, manual = request ~= nil, started_ms = now, attempts = 0 }
        camera.attempts = 0
        submit_camera_recovery(camera.pending, now)
    end

    function api.DesyncSnapshot()
        local status=State.desync
        if status.backend_available then
            local applied=is_on("desync_protection")
                and handler_registration_state(handler_ids.SCRIPTED_GAME_EVENT).armed
            return {state="LIMITED",cause="Source-verified remote bail request only",
                requested=is_on("desync_protection"),applied=applied,
                result=applied and "REMOTE_BAIL_FILTER" or "OFF",blocked=status.blocked or 0,
                last_block_ms=status.last_block_ms,request_count=status.request_count,
                local_exit_intercepted=false,transport_desync_prevented=false,
                suppressed=(status.blocked or 0)>0,live_verified=false}
        end
        return { state = "UNAVAILABLE", cause = "No verified cause-aware local bail interceptor",
            requested=status.requested, applied=false, result=status.result,
            request_count=status.request_count, notification_count=status.notification_count,
            duplicate_notifications=status.duplicate_notifications,
            transition_state = "not intercepted", host_migration_state = "not intercepted",
            bail_requested = "unknown", suppressed = false, recovery_result = "NOT_ATTEMPTED" }
    end

    function api.PolicySnapshot()
        local supported = State.desync.backend_available == true
        local unavailable = {}
        if not supported then
            unavailable.protect_event_identity = true
            unavailable.protect_script_schema = true
            unavailable.desync_protection = true
            for _, policy in pairs(SCRIPT_POLICIES) do unavailable[policy.key] = true end
        end
        local version = State.desync.game_version
        local detail
        if supported then detail = "Freemode request mappings verified for game version 1.73."
        elseif version and version ~= "1.73" then detail = "No verified freemode request mapping for game version " .. clean(version, 32) .. "."
        elseif version == "1.73" then detail = "The incoming script-event callback is unavailable."
        else detail = "The running game version has not been verified." end
        local registration=handler_registration_state(handler_ids.SCRIPTED_GAME_EVENT)
        return { supported=supported, version=version, detail=detail,
            active=started and (script_filters_active() or is_on("desync_protection")),
            registered=registration.registered, armed=registration.armed,
            queued=registration.queued, removal_pending=registration.removal_pending,
            unavailable_features=unavailable }
    end

    function api.RegisteredCount() return State.registered_count end
    function api.IsOn(key) return is_on(key) end
    function api.GetFeature(key) return F[key] end

    function api.IsUnderAttack()
        return State.attack.active == true
    end

    function api.HighRiskWritesAllowed(domain)
        -- Reject the offending inbound payload without suspending local features.
        return true
    end

    function api.SuspicionSnapshot()
        local rows = {}
        local now = now_ms()
        for player_id in pairs(State.evidence) do
            refresh_source_identity(player_id)
            local isolated, ignored = is_isolated(player_id, now), is_ignored(player_id, now)
            local entry = State.evidence[player_id]
            if entry then
                local distinct = 0
                for _ in pairs(entry.categories or {}) do distinct = distinct + 1 end
                rows[#rows + 1] = {
                    player_id = player_id,
                    source = session_source_label(player_id),
                    score = tonumber(entry.score) or 0,
                    blocked = tonumber(entry.blocked) or 0,
                    distinct = distinct,
                    reason = clean(entry.last_reason or "inbound anomaly", 96),
                    isolated = isolated,
                    ignored = ignored,
                }
            end
        end
        table.sort(rows, function(a, b)
            if a.score == b.score then return a.player_id < b.player_id end
            return a.score > b.score
        end)
        return rows
    end

    function api.StatusSnapshot()
        local suspicions = api.SuspicionSnapshot()
        local attack = State.attack
        local source_id = tonumber(attack.source_id) or -1
        local observed = State.status_context
        return {
            status = attack.active == true and "UNDER ATTACK"
                or (protection_master(nil) and "MONITORING" or "OFF"),
            active = attack.active == true,
            reason = clean(attack.reason or "Monitoring inbound traffic", 160),
            source_id = source_id,
            source = session_source_label(source_id),
            source_available = source_id >= 0 and observed.source_id == source_id and observed.source_available or false,
            blocked = total_blocked(),
            last_action = clean(attack.last_action or "Crash Shield monitoring", 160),
            since_ms = attack.since_ms,
            until_ms = tonumber(attack.until_ms) or 0,
            host_authority = observed.host_authority == true,
            evidence_path = State.evidence_path,
            evidence_verified = State.evidence_verified == true,
            evidence_error = State.evidence_last_error,
            evidence_rows = #State.evidence_rows,
            evidence_dropped = State.evidence_dropped,
            uninspectable_node_collections = State.counters.node_collections_uninspectable or 0,
            validator_internal_errors = State.counters.validator_internal_errors or 0,
            aggregated_incident_rows = State.counters.evidence_aggregated or 0,
            pending_action = State.pending_action and State.pending_action.kind or nil,
            suspicions = suspicions,
        }
    end

    local function action_source(player_id)
        player_id = tonumber(player_id)
        if not integer_number(player_id) then player_id = tonumber(State.attack.source_id) or -1 end
        player_id = math.floor(tonumber(player_id) or -1)
        if player_id < 0 or player_id > 31 or player_id == local_player_id() then
            return nil, "No trustworthy remote session-local source is selected."
        end
        if not orbital_player_available(player_id) then
            return nil, "The suspected session-local source is no longer connected."
        end
        return player_id
    end

    local function queue_action(kind, player_id, source_token, session_generation, expected_epoch)
        expected_epoch = expected_epoch or action_epoch
        if not started or expected_epoch ~= action_epoch then
            return false, "The action was cancelled by a reset or shutdown."
        end
        if State.pending_action ~= nil then return false, "A Crash Shield action is already queued." end
        local requested_ms = now_ms()
        if not started or expected_epoch ~= action_epoch then
            return false, "The action was cancelled by a reset or shutdown."
        end
        if State.pending_action ~= nil then return false, "A Crash Shield action is already queued." end
        State.pending_action = { kind = kind, player_id = player_id, requested_ms = requested_ms,
            source_identity = source_token, session_generation = session_generation, action_epoch = expected_epoch }
        return true
    end

    local function manual_source(player_id, lease_key)
        if not started then return nil, "Traffic controls are unavailable while CScript is stopped." end
        local generation = State.session_generation
        local leases = State[lease_key]
        local source, err = action_source(player_id)
        if not source then return nil, err end
        local identity = refresh_source_identity(source)
        local now = now_ms()
        -- A reset may replace this policy while a host identity read reenters Lua.
        if not started or generation ~= State.session_generation or State[lease_key] ~= leases or not identity then
            return nil, "The selected source, session, or manual policy changed or is unavailable."
        end
        return source, nil, { identity = identity, session_generation = generation }, now
    end

    function api.BlockSource(player_id)
        local source, err, lease, now = manual_source(player_id, "block_leases")
        if not source then toast(err, 4500, "warning"); return false, err end
        State.block_leases[source] = lease
        State.isolated_until[source] = math.max(State.isolated_until[source] or 0, now + MANUAL_BLOCK_MS)
        State.counters.manual_blocks = State.counters.manual_blocks + 1
        State.attack.last_action = "Local block enabled for " .. session_source_label(source)
        State.attack.until_ms = math.max(State.attack.until_ms or 0, now + ATTACK_HOLD_MS)
        append_evidence(source, "explicit local block", "user enabled session-local inbound quarantine", true, true, now)
        if reconcile_event_handlers and not reconcile_event_handlers() then
            local detail = "Traffic block requested; an incoming handler is unavailable. CScript will retry."
            toast(detail, 4500, "warning")
            return false, detail
        end
        toast("Crash Shield locally blocked " .. session_source_label(source) .. ".", 4500)
        return true
    end

    function api.IgnoreSourceAlerts(player_id)
        local source, err, lease, now = manual_source(player_id, "mute_leases")
        if not source then toast(err, 4500, "warning"); return false, err end
        State.mute_leases[source] = lease
        State.ignored_until[source] = now + IGNORE_ALERT_MS
        State.counters.ignored_alerts = State.counters.ignored_alerts + 1
        State.attack.last_action = "Muted alerts for " .. session_source_label(source)
        append_evidence(source, "alert mute", "alerts muted; defensive filtering remains active", false, false)
        toast("Alerts muted for two minutes; Crash Shield filtering remains active.", 4500)
        return true
    end

    function api.QueueLeaveSession()
        local ok, err = queue_action("leave")
        if ok then toast("Leave Session queued on CScript's scheduler.", 3500) end
        if not ok then toast(err, 4000, "warning") end
        return ok, err
    end

    function api.CanHostRemove(player_id)
        local source, err = action_source(player_id)
        if not source then return false, err end
        if H.NETWORK_IS_HOST == nil or invoke_bool(H.NETWORK_IS_HOST) ~= true then
            return false, "Local player does not currently have session-host authority."
        end
        return true, nil, source
    end

    function api.QueueHostRemoval(player_id)
        local generation, epoch = State.session_generation, action_epoch
        if not started then return false, "Host removal is unavailable while CScript is stopped." end
        local allowed, err, source = api.CanHostRemove(player_id)
        if not started or epoch ~= action_epoch then
            return false, "Host removal was cancelled by a reset or shutdown."
        end
        if not allowed then toast(err, 4500, "warning"); return false, err end
        local identity = source_identity(source)
        if not started or epoch ~= action_epoch then
            return false, "Host removal was cancelled by a reset or shutdown."
        end
        if not identity or generation ~= State.session_generation then
            local detail = "The selected source identity or current session is unavailable."
            toast(detail, 4500, "warning")
            return false, detail
        end
        local ok, queue_error = queue_action("host_remove", source, identity, generation, epoch)
        if ok then toast("Host removal queued; authority and source identity will be rechecked before use.", 4500) end
        if not ok then toast(queue_error, 4000, "warning") end
        return ok, queue_error
    end

    function api.ExportEvidence()
        local ok, err = queue_action("export")
        if ok then toast("Crash Shield evidence export queued.", 3000) end
        if not ok then toast(err, 4000, "warning") end
        return ok, err
    end

    function api.ClearSuspicion()
        local ok, err = queue_action("clear_suspicion")
        if ok then toast("Session incident-score reset queued.", 3500) end
        if not ok then toast(err, 4000, "warning") end
        return ok, err
    end

    local function prune_disconnected_sources(now)
        if now - State.last_roster_prune_ms < 500 then return end
        State.last_roster_prune_ms = now
        local slots = {}
        for player_id in pairs(State.evidence) do slots[player_id] = true end
        for player_id in pairs(State.isolated_until) do slots[player_id] = true end
        for player_id in pairs(State.ignored_until) do slots[player_id] = true end
        for player_id in pairs(slots) do
            if orbital_player_available(player_id) then
                refresh_source_identity(player_id)
                State.missing_since[player_id] = nil
            else
                local missing = State.missing_since[player_id]
                if not missing then
                    State.missing_since[player_id] = now
                elseif now - missing >= ROSTER_GRACE_MS then
                    flush_evidence_aggregates(true, now, player_id)
                    append_evidence(player_id, "source disconnected",
                        "live suspicion and quarantine cleared to prevent player-slot reuse", false, false, now)
                    clear_source_state(player_id)
                end
            end
        end
    end

    local function process_pending_action()
        local action = State.pending_action
        if not action then return end
        State.pending_action = nil
        if not started or action.action_epoch ~= action_epoch then return end
        if action.kind == "leave" then
            State.counters.leave_requests = State.counters.leave_requests + 1
            local submitted = H.NETWORK_BAIL ~= nil and invoke_void(H.NETWORK_BAIL, 16, 0, 0) ~= false
            State.attack.last_action = submitted and "Leave Session requested from GTA networking"
                or "Leave Session request could not be submitted"
            append_evidence(-1, "explicit user action", State.attack.last_action, false, true)
            toast(State.attack.last_action, 4500, submitted and "warning" or "error")
        elseif action.kind == "host_remove" then
            local allowed, err, source = api.CanHostRemove(action.player_id)
            if not started or action.action_epoch ~= action_epoch then return end
            if allowed then
                -- A session slot can be reused between the click and this tick.
                -- Missing identity is not permission to act on its new occupant.
                local identity = source_identity(source)
                if not started or action.action_epoch ~= action_epoch then return end
                if action.session_generation ~= State.session_generation
                    or action.source_identity == nil or identity ~= action.source_identity then
                    allowed, err = false, "The selected source or session changed, or its identity is unavailable."
                end
            end
            if not allowed then
                State.attack.last_action = "Host removal refused: " .. clean(err, 120)
                append_evidence(action.player_id, "host removal refused", State.attack.last_action, false, true)
                toast(State.attack.last_action, 5000, "warning")
            else
                State.counters.host_remove_requests = State.counters.host_remove_requests + 1
                local submitted = H.NETWORK_SESSION_KICK_PLAYER ~= nil
                    and invoke_void(H.NETWORK_SESSION_KICK_PLAYER, source) ~= false
                State.attack.last_action = submitted
                    and ("Host removal submitted for " .. session_source_label(source))
                    or ("Host removal failed for " .. session_source_label(source))
                append_evidence(source, "explicit host action", State.attack.last_action, false, true)
                toast(State.attack.last_action, 5000, submitted and "warning" or "error")
            end
        elseif action.kind == "export" then
            flush_evidence_aggregates(true, now_ms())
            State.evidence_dirty = true
            local ok, path_or_error = flush_evidence(true, true)
            State.attack.last_action = ok and "Crash Shield evidence exported and read-back verified"
                or ("Evidence export failed: " .. clean(path_or_error, 110))
            toast(ok and ("Crash Shield evidence saved: " .. tostring(path_or_error))
                or State.attack.last_action, 6000, ok and "success" or "error")
        elseif action.kind == "clear_suspicion" then
            flush_evidence_aggregates(true, now_ms())
            State.evidence_dirty = true
            State.evidence = {}
            State.detected = {}
            State.event_buckets = {}
            State.node_buckets = {}
            State.evidence_aggregates = {}
            append_evidence(-1, "session suspicion reset",
                "scores cleared; bounded incident history retained for this session", false, true)
            State.attack.last_action = "Current-session suspicion counters cleared"
        end
    end

    function api.SetSpawnRadius(value)
        return set_spawn_radius(value)
    end

    function api.GetSpawnRadius() return State.spawn.radius end

    function api.SpawnSnapshot()
        local spawn=State.spawn
        local now=now_ms()
        local available=eLuaEvent and eLuaEvent.CAN_APPLY_NODE_DATA~=nil and EventMgr
            and type(EventMgr.RegisterHandler)=="function" and type(EventMgr.RemoveHandler)=="function" or false
        local registration=handler_registration_state(handler_ids.CAN_APPLY_NODE_DATA)
        return {radius=spawn.radius,available=available,registered=registration.registered,
            armed=registration.armed,queued=registration.queued,removal_pending=registration.removal_pending,
            position_ready=spawn.position~=nil and now>=spawn.sampled_at and now-spawn.sampled_at<=1000,
            enabled={ped=protection_master("protect_ped_spawns"),vehicle=protection_master("protect_vehicle_spawns"),
                object=protection_master("protect_object_spawns")},
            blocked={ped=spawn.blocked.ped,vehicle=spawn.blocked.vehicle,object=spawn.blocked.object},
            blocked_total=spawn.blocked.ped+spawn.blocked.vehicle+spawn.blocked.object,
            entries=spawn.entries,creates=spawn.creates,updates=spawn.updates,
            rejected_total=spawn.rejected_total,internal_errors=spawn.internal_errors,
            traffic_observed=spawn.entries>0,ingress=registration.ingress,
            unresolved=spawn.unresolved,last_block_ms=spawn.last_block_ms,mode="CREATE_ONLY",
            detail="Incoming creation-data veto; earlier engine/network bookkeeping is outside this Lua callback."}
    end

    function api.FastTick(now)
        if not started then return end
        now = tonumber(now) or now_ms()
        probe_desync_backend(now)
        refresh_toggle_states(now)
        -- Idle monitoring can retain an old subject indefinitely while disabled.
        -- Drop only idle observations; a queued click keeps its original subject
        -- so character/camera changes and delayed requests still cancel safely.
        if not protection_master("protect_camera") and not State.camera.request and not State.camera.pending then
            State.camera.observed, State.camera.samples = nil, 0
        end
        refresh_spawn_position(now)
        if reconcile_event_handlers then reconcile_event_handlers() end
        local runtime_active = protection_master(nil)
            or is_on("modder_detection")
            or State.attack.active == true
            or State.pending_action ~= nil
            or State.evidence_dirty == true
            or next(State.evidence_aggregates) ~= nil
            or next(State.isolated_until) ~= nil
            or State.camera.request ~= nil or State.camera.pending ~= nil
            or State.suppression_release_pending == true
        if not runtime_active then return end
        -- Diagnostics consume gameplay observations; disabled/stopped UI reads
        -- never query native host authority or scan the current roster.
        local source_id = tonumber(State.attack.source_id) or -1
        local observed = State.status_context
        if now < observed.sampled_at or now - observed.sampled_at >= 500 or source_id ~= observed.source_id then
            local host_ok, host = pcall(function()
                return H.NETWORK_IS_HOST ~= nil and invoke_bool(H.NETWORK_IS_HOST) == true
            end)
            State.status_context = {
                host_authority = host_ok and host == true,
                source_id = source_id,
                source_available = source_id >= 0 and roster_presence(source_id) == true or false,
                sampled_at = now,
            }
        end
