        flush_evidence_aggregates(true, now)
        local released, release_error = release_suppression_or_defer("Panic Reset released Crash Shield suppression")
        if #State.evidence_rows > 0 then
            append_evidence(-1, "panic reset",
                released and "temporary attribution, quarantine, and suppression released"
                    or "traffic blocks cleared; local runtime restoration remains pending", false, true, now)
            flush_evidence(true)
        end
        State.event_buckets = {}
        State.node_buckets = {}
        State.isolated_until = {}
        State.ignored_until = {}
        State.block_leases = {}
        State.mute_leases = {}
