        State.evidence = {}
        State.detected = {}
        State.evidence_aggregates = {}
        State.pending_action = nil
        State.collision_shield_until = 0
        State.attack.active = false
        State.attack.reason = "Monitoring inbound traffic"
        State.attack.source_id = -1
        State.attack.source_confidence = CONFIDENCE_NONE
        State.attack.priority = 0
        State.attack.since_ms = nil
        State.attack.until_ms = 0
        State.attack.suppression_pending = false
        State.attack.last_action = released and "Panic Reset released Crash Shield temporary state"
            or "Panic Reset cleared traffic blocks; local runtime restoration is pending"
        if reconcile_event_handlers then reconcile_event_handlers() end
        return released, release_error
    end

    function api.OnSessionChange()
        action_epoch = action_epoch + 1
        State.spawn.position=nil
        State.spawn.sampled_at=-100000
        State.status_context = { host_authority = false, source_id = -1, source_available = false, sampled_at = -100000 }
        cancel_camera_recovery("Session changed; camera recovery cancelled")
