        local had_evidence = #State.evidence_rows > 0
        local released, release_error = release_suppression_or_defer("Session transition released Crash Shield suppression")
        local pending_token = not released and State.attack.suppression_token or nil
        if had_evidence then
            append_evidence(-1, "session transition", "session-local attribution closed", false, true)
            flush_evidence(true)
        end
        State.session_generation = State.session_generation + 1
        State.block_notices = {}
        State.last_notice_ms = -100000
        State.event_buckets = {}
        State.node_buckets = {}
        State.relationship_filter_error_logged = false
        State.isolated_until = {}
        State.ignored_until = {}
