        State.missing_since = {}
        State.evidence = {}
        State.evidence_rows = {}
        State.evidence_sequence = 0
        State.evidence_aggregates = {}
        State.evidence_dropped = 0
        State.evidence_dirty = false
        State.evidence_path = nil
        State.evidence_verified = false
        State.evidence_last_error = nil
