            active = false, reason = "Monitoring inbound traffic", source_id = -1,
            source_confidence = CONFIDENCE_NONE,
            since_ms = nil, until_ms = 0,
            last_action = released and "Session changed; Crash Shield monitoring"
                or "Session changed; previous local runtime restoration is pending",
            suppression_token = pending_token, suppression_applied = not released,
        }
