        return released, release_error
    end

    function api.Shutdown()
        action_epoch = action_epoch + 1
        State.spawn.position=nil
        State.status_context = { host_authority = false, source_id = -1, source_available = false, sampled_at = -100000 }
        if State.shutdown_complete == true then return true end
        cancel_camera_recovery("CScript stopped; camera recovery cancelled")
        flush_evidence_aggregates(true, now_ms())
        local had_evidence = #State.evidence_rows > 0
        local released, release_error = release_suppression_or_defer("CScript unload released Crash Shield suppression")
        if had_evidence then
            append_evidence(-1, "loader shutdown", released and "high-risk suppression released"
                or "local runtime restoration remains pending", false, true)
            flush_evidence(true)
        end
        State.pending_action = nil
        State.attack.active = false
        State.attack.suppression_pending = false
        State.shutdown_complete = released == true
        return released, release_error
    end

    function api.HandlerFailure(kind, detail)
        kind = clean(kind or "unknown callback", 64)
        detail = clean(detail or "internal callback failure", 160)
        local now = now_ms()
        if kind == "CAN_APPLY_NODE_DATA" then
            -- CScript-internal uncertainty must never deny ordinary entity sync
            -- or implicate a remote source. The guarded callback returns ALLOW.
            State.counters.validator_internal_errors = State.counters.validator_internal_errors + 1
            aggregate_evidence(-1, "internal validator error",
                kind .. " failed open: " .. detail, false, false, now)
            local key = "internal-failure|" .. kind
            local prior = State.notice_log_cache[key]
            if not prior or now - (tonumber(prior.last_ms) or -100000) >= 30000 then
                log_warn("Crash Shield validator failed open in " .. kind .. ": " .. detail)
                State.notice_log_cache[key] = { last_ms = now, suppressed = 0 }
            else
                prior.suppressed = (tonumber(prior.suppressed) or 0) + 1
            end
            return true
        end
        State.counters.validator_internal_errors = State.counters.validator_internal_errors + 1
        aggregate_evidence(-1, "internal validator error", kind .. ": " .. detail,
            false, false, now)
        local key = "internal-failure|" .. kind
        local prior = State.notice_log_cache[key]
        if not prior or now - prior.last_ms >= 30000 then
            log_warn("Protection callback failed open in " .. kind .. ": " .. detail)
            State.notice_log_cache[key] = {last_ms=now,suppressed=0}
        end
        return kind ~= "SCRIPTED_GAME_EVENT"
    end

    function api.HandlerDependencies()
        -- Counts are real independent consumers. A selected-player relationship
        -- override keeps node intake alive when Crash Shield itself is disabled.
        local relationships = type(remote_relationship_filter_active) == "function"
            and remote_relationship_filter_active() == true
        return {
            CAN_APPLY_NODE_DATA = (node_filters_active() and 1 or 0)
                + (has_manual_blocks() and 1 or 0)
                + (relationships and 1 or 0),
            SCRIPTED_GAME_EVENT = (script_filters_active() and 1 or 0)
                + (has_manual_blocks() and 1 or 0)
                + (is_on("desync_protection") and State.desync.backend_available and 1 or 0),
            SHOULD_COLLIDE = protection_master("protect_collision")
                and now_ms() < (tonumber(State.collision_shield_until) or 0) and 1 or 0,
            ON_REACTION = protection_master("protect_reactions") and 1 or 0,
