    function api.HandlerSnapshot()
        local result = { dependencies = api.HandlerDependencies(), registered = {}, states = {} }
        for name, identifier in pairs(handler_ids) do
            result.registered[name] = identifier
            result.states[name] = handler_registration_state(identifier)
        end
        return result
    end

    api.Handlers = {
        SCRIPTED_GAME_EVENT = protect_script_events_handler,
        CAN_APPLY_NODE_DATA = protect_sync_nodes_handler,
        SHOULD_COLLIDE = protect_collision_handler,
        ON_REACTION = protection_reaction_handler,
