local function register_event_handlers()
    if not public_api then return false end
    if not (EventMgr and type(EventMgr.RegisterHandler) == "function"
        and type(EventMgr.RemoveHandler) == "function" and eLuaEvent) then return false end
    local wanted = public_api.HandlerDependencies()
    local success = true
    for name, callback in pairs(public_api.Handlers) do
        local needed = started and (tonumber(wanted[name]) or 0) > 0
        local identifier = handler_ids[name]
        local registration = handler_registration_state(identifier)
        if identifier ~= nil and (not needed or registration.removal_pending) then
            local removed, result = pcall(EventMgr.RemoveHandler, identifier)
            if removed and result ~= false then
                handler_ids[name], identifier = nil, nil
            else success = false end
        end
        if needed and identifier == nil then
            local event = eLuaEvent[name]
            if event == nil then
                success = false
            else
                local binding = __public_binding
                local guarded = function(...)
                    if not public_protections_allowed(binding, true) then return __public_denied_handler(name) end
                    local frame = public_api and public_api.BeginIngress(name, (select(1, ...)))
                    local ok, result = pcall(callback, ...)
                    if public_api then pcall(public_api.EndIngress, frame, name, ok, result) end
                    if ok then return result end
                    if public_api and type(public_api.HandlerFailure) == "function" then
                        pcall(public_api.HandlerFailure, name, result)
                    end
                    if name == "SCRIPTED_GAME_EVENT" then return false end
                    if name == "CAN_APPLY_NODE_DATA" or name == "SHOULD_COLLIDE" then return true end
                end
                local registered, id = pcall(EventMgr.RegisterHandler, event, guarded)
                if registered and type(id) == "number" then handler_ids[name] = id else success = false end
            end
        end
