-- END GENERATED RENDERED ROOF PROFILES

-- Collision margins/proxy triangles can sit above the visible roof. Use an
-- installed-model surface only when every live carrier hit matches its shape.
function Module.ResolveRenderedRoof(profile,input)
 if type(profile)~='table'or input.roofMod~=-1 or math.abs(input.supportRadius-.165)>.000001 then return end
 local chosen,provenance,ambiguous
 for _,variant in ipairs(profile.variants or{})do
  for _,candidate in ipairs(variant.candidates or{})do
   local center=candidate.center
   if candidate.index==input.index and math.abs(center.x-input.center.x)<.015 and math.abs(center.y-input.center.y)<.015 then
    for _,collision in ipairs(candidate.collisionVariants or{})do
     local delta,valid={},#candidate.samples==9 and #collision.z==9
     local sum=0
     for index=1,9 do
      local live,render=input.samples[index],candidate.samples[index]
      if not live or not render or live.entity~=input.entity or not finite(live.z)or not finite(live.nx,2)or not finite(live.ny,2)or not finite(live.nz,2)
       or live.nz<math.cos(math.rad(30))or math.abs(live.x-render.x)>.015 or math.abs(live.y-render.y)>.015 then
       valid=false;break
      end
      local normalLength=live.nx*live.nx+live.ny*live.ny+live.nz*live.nz
      if normalLength<.81 or normalLength>1.21 then valid=false;break end
      delta[index]=live.z-collision.z[index];sum=sum+delta[index]
     end
     local mean=sum/9
     if mean<-.008 or mean>(collision.margin or 0)+.008 then valid=false end
     if valid then for index=1,9 do if math.abs(delta[index]-mean)>.008 then valid=false;break end end end
     if valid then
      local samples={}
      for index,render in ipairs(candidate.samples)do
       local live=input.samples[index]
       if not finite(render.z)or not finite(render.nx,2)or not finite(render.ny,2)or not finite(render.nz,2)
        or render.nz<math.cos(math.rad(30))or math.abs(live.z-render.z)>.18 then valid=false;break end
       samples[index]={entity=input.entity,x=live.x,y=live.y,z=render.z,nx=render.nx,ny=render.ny,nz=render.nz}
      end
      if valid then
       if chosen then
        for index,sample in ipairs(samples)do
         if math.abs(sample.z-chosen[index].z)>.008 then ambiguous=true end
        end
       else chosen=samples;provenance=variant.sourceSha256 end
      end
     end
    end
   end
  end
 end
 if not ambiguous then return chosen,provenance end
end

local function support_offsets(bounds,radius)
 if not finite(radius,1)or radius<.015 then return nil,'The turret has no reviewed foot sweep radius'end
 local halfX,halfY=(bounds.max.x-bounds.min.x)*.5,(bounds.max.y-bounds.min.y)*.5
 if halfX<.015 or halfY<.015 then return nil,'Turret footprint is degenerate'end
 -- The manifest radius comes from the lowest mesh vertices, measured about
 -- the bounds' bottom center. Bounds are only a consistency check: their
 -- corners are not assumed to be part of the visible foot.
 if radius<math.max(halfX,halfY)or radius>math.sqrt(halfX*halfX+halfY*halfY)+.001 then
  return nil,'The reviewed foot sweep does not match the loaded base bounds'
 end
 local offsets={{0,0}}
 for index=0,7 do
  local angle=index*math.pi/4
  offsets[#offsets+1]={radius*math.cos(angle),radius*math.sin(angle)}
 end
 return offsets
end

-- Samples are already in carrier-local coordinates and share one stable carrier
-- transform. Required order: center, then eight ring points starting at +X and
-- increasing counterclockwise in 45-degree steps. The reviewed radius covers
-- the foot at every yaw; bounds corners alone do not establish that support.
-- A missing carrier hit, steep surface, or incomplete ring is a failure.
function Module.FitRoof(input)
 if type(input)~='table'or type(input.center)~='table'or type(input.bounds)~='table'
  or type(input.samples)~='table'then return nil,'Roof measurement is incomplete'end
 local center,bounds,samples=input.center,input.bounds,input.samples
 if not finite(input.entity,1e10)or input.entity<=0 or not finite(center.x)or not finite(center.y)
  or type(bounds.min)~='table'or type(bounds.max)~='table'then return nil,'Invalid roof measurement identity'end
 for _,axis in ipairs({'x','y','z'})do
  if not finite(bounds.min[axis])or not finite(bounds.max[axis])or bounds.max[axis]<=bounds.min[axis]then
   return nil,'Invalid turret mesh bounds'
  end
 end
 local offsets,why=support_offsets(bounds,input.supportRadius)
 if not offsets then return nil,why end
 local sampleCount=#offsets
 local meanX,meanY,meanZ=0,0,0
 local normals={}
 for index=1,sampleCount do
  local s=samples[index]
  if type(s)~='table'or s.entity~=input.entity or not finite(s.x)or not finite(s.y)or not finite(s.z)
   or not finite(s.nx)or not finite(s.ny)or not finite(s.nz)then return nil,'The full mount footprint did not hit this roof'end
  if math.abs(s.x-center.x-offsets[index][1])>.04 or math.abs(s.y-center.y-offsets[index][2])>.04 then
   return nil,'The roof moved during measurement'
  end
  local n=vector(s.nx,s.ny,s.nz);local length2=dot(n,n)
  if length2<.81 or length2>1.21 then return nil,'Invalid roof surface normal'end
  n=norm(n);normals[index]=n
  if n.z<math.cos(math.rad(30))then return nil,'The measured surface is too steep'end
  meanX,meanY,meanZ=meanX+s.x,meanY+s.y,meanZ+s.z
 end
 meanX,meanY,meanZ=meanX/sampleCount,meanY/sampleCount,meanZ/sampleCount
 local xx,yy,xy,xz,yz=0,0,0,0,0
 for index=1,sampleCount do
  local s=samples[index];local x,y,z=s.x-meanX,s.y-meanY,s.z-meanZ
  xx,yy,xy,xz,yz=xx+x*x,yy+y*y,xy+x*y,xz+x*z,yz+y*z
 end
 local determinant=xx*yy-xy*xy
 if determinant<=1e-10 then return nil,'Insufficient roof support area'end
 local slopeX,slopeY=(xz*yy-yz*xy)/determinant,(yz*xx-xz*xy)/determinant
 local up=norm(vector(-slopeX,-slopeY,1))
 if up.z<math.cos(math.rad(30))then return nil,'The roof fit is too steep'end
 for _,n in ipairs(normals)do
  if dot(n,up)<math.cos(math.rad(25))then return nil,'Roof normals disagree with the support surface'end
 end
 local intercept=meanZ-slopeX*meanX-slopeY*meanY
 local low,high=math.huge,-math.huge
 for index=1,sampleCount do
  local s=samples[index];local error=s.z-(slopeX*s.x+slopeY*s.y+intercept)
  low,high=math.min(low,error),math.max(high,error)
 end
 -- The reviewed V4 Speedo foot spans the full 165 mm support ring. Its
 -- deliberate 40 mm residual cap covers the measured 37.947 mm Deluxo crown;
 -- the rigid foot seats at the highest measured support point, so a visible
 -- local gap up to this bound remains possible. Generic manifests keep 10 mm.
 -- Missing/foreign hits and steep/disagreeing normals never receive a waiver.
 local gap=high-low
 local gapLimit=input.supportPolicy=='speedo50-enhanced-1158-4-runtime'and .04 or .01
 local measurement={maxGap=gap,gapLimit=gapLimit}
 if gap>gapLimit then return nil,'Roof curvature leaves too much space under the mount',measurement end
 local anchor=vector(center.x,center.y,slopeX*center.x+slopeY*center.y+intercept+high)
 local right=norm(vector(1,0,slopeX))
 local basis={right=right,forward=cross(up,right),up=up}
 local bottomCenter=vector((bounds.min.x+bounds.max.x)*.5,(bounds.min.y+bounds.max.y)*.5,bounds.min.z)
 local originOffset=transform(basis,bottomCenter)
 local position=vector(anchor.x-originOffset.x,anchor.y-originOffset.y,anchor.z-originOffset.z)
 -- GTA rotation order 0 (ZYX). At yaw 0 these angles reproduce the measured
 -- right/forward/up basis exactly, including combined pitch and roll.
 local rotation=vector(math.deg(math.atan(slopeY,math.sqrt(1+slopeX*slopeX))),-math.deg(math.atan(slopeX)),0)
 return{position=position,rotation=rotation,rotationOrder=0,basis=basis,anchor=anchor,
  baseBottom=bottomCenter,supportRadius=input.supportRadius,maxGap=gap,slopes={x=slopeX,y=slopeY}},nil,measurement
end

function Module.YawRoofFit(fit,degrees)
 assert(type(fit)=='table'and finite(degrees,1e6),'Invalid turret roof pose')
 local angle=math.rad(degrees);local c,s=math.cos(angle),math.sin(angle)
 local right,forward,up=fit.basis.right,fit.basis.forward,fit.basis.up
 local basis={right=vector(right.x*c+forward.x*s,right.y*c+forward.y*s,right.z*c+forward.z*s),
  forward=vector(-right.x*s+forward.x*c,-right.y*s+forward.y*c,-right.z*s+forward.z*c),up=up}
 local offset=transform(basis,fit.baseBottom)
 local position=vector(fit.anchor.x-offset.x,fit.anchor.y-offset.y,fit.anchor.z-offset.z)
 local rotation=vector(math.deg(math.atan(basis.forward.z,up.z)),
  math.deg(math.asin(math.max(-1,math.min(1,-basis.right.z)))),math.deg(math.atan(basis.right.y,basis.right.x)))
 return{position=position,rotation=rotation,rotationOrder=0,basis=basis}
end

-- The adapter is the game/native boundary. It adds each acquired resource to
-- the record before another native operation can fail; Release is retryable.
-- Keeping a retiring record until Release confirms completion prevents a quick
-- off/on toggle or a vehicle change from abandoning partially created objects.
function Module.NewController(host)
 assert(type(host)=='table'and type(host.GetContext)=='function'and type(host.Step)=='function'
  and type(host.Update)=='function'and type(host.Release)=='function','Roof turret host is incomplete')
 local record,wanted,cancelled,failedKey=nil,false,false,nil
 local status,detail='OFF','Disabled'
 local API={}
 local function set_status(nextStatus,nextDetail)
  nextDetail=nextDetail or nextStatus
  local changed=nextStatus~=status or nextDetail~=detail
  status,detail=nextStatus,nextDetail
  if changed and type(host.Report)=='function'then pcall(host.Report,status,detail)end
 end
 local function key(context)
  return table.concat({context.vehicle,context.model,context.address,context.ped,context.pedAddress,context.session or 0,tostring(context.online),context.carrierNetId or 0},':')
 end
 local function valid_context(context)
  if type(context)~='table'or context.driver~=true or context.roof~=true or context.usable~=true then return false end
  for _,field in ipairs({'vehicle','model','address','ped','pedAddress'})do
   if not finite(context[field],1e17)or context[field]<=0 then return false end
  end
  return context.session==nil or type(context.session)=='number'or type(context.session)=='string'
 end
 local function retire(reason)
  if record then record.retiring=true;record.reason=reason or'Removing mount';set_status('CLEANUP',record.reason)end
 end
 local function cleanup()
  if not record then return true end
  local ok,complete,why=pcall(host.Release,record,record.reason)
  if ok and complete==true then
   record=nil
   if failedKey then set_status('UNAVAILABLE',detail)
   elseif cancelled then set_status('PAUSED','Toggle off and on to resume')
   elseif wanted then set_status('WAITING','Waiting for an eligible vehicle')
   else set_status('OFF','Disabled')end
   return true
  end
  set_status('CLEANUP',ok and(why or'Finishing mount cleanup')or tostring(complete))
  return false
 end
 local function fail(reason)
  if record then failedKey=record.key end
  retire(reason);cleanup()
  if not record then set_status('UNAVAILABLE',reason)end
 end
 function API.Tick(enabled,now)
  wanted=enabled==true
  assert(finite(now,1e17)and now>=0,'Roof turret tick requires a valid clock')
  -- Frame-local hiding must run even through GUI gates, preparation and cleanup.
  if record and type(host.Frame)=='function'then
   local ok,why=pcall(host.Frame,record)
   if not ok then fail(tostring(why));return end
  end
  if not wanted then
   cancelled,failedKey=false,nil
   retire('Disabled');if record then cleanup()else set_status('OFF','Disabled')end
   return
  end
  if record and record.retiring then cleanup();return end
  if cancelled then set_status('PAUSED','Toggle off and on to resume');return end
  local ok,context,why=pcall(host.GetContext,now)
  if not ok or not valid_context(context)then
   if record then retire('Vehicle, driver, or roof is no longer eligible');cleanup()
   else set_status('WAITING',ok and(why or'Waiting for an eligible vehicle')or tostring(context))end
   return
  end
  local identity=key(context)
  if record and record.key~=identity then retire('Vehicle identity changed');cleanup();return end
  if failedKey and failedKey~=identity then failedKey=nil end
  if failedKey==identity then return end
  if not record then
   local frozen={}
   for name,value in pairs(context)do
    if type(value)~='table'and type(value)~='userdata'and type(value)~='function'then frozen[name]=value end
   end
   record={context=frozen,key=identity,parts={},modelRefs={},createdAt=now,deadline=now+8000}
   set_status('PREPARING','Measuring the roof and preparing the mount')
  end
  if record.ready then
   local good,updated,reason=pcall(host.Update,record,now)
   if good and updated=='rebuild'then retire(reason or'Refitting the roof mount');cleanup()
   elseif not good or updated~=true then fail(good and(reason or'Mount update stopped')or tostring(updated))end
   return
  end
  if now<record.createdAt or now>record.deadline then fail(record.assetWaitDetail or'Roof preparation timed out');return end
  local good,result,reason=pcall(host.Step,record,now)
  if not good then fail(tostring(result));return end
  if result=='ready'then record.ready=true;set_status('ACTIVE','Remote .50 cal mounted')
  elseif result=='pending'then set_status('PREPARING',reason or'Preparing mount')
  else fail(reason or'No supported turret mount is available')end
 end
 function API.Cancel(reason)
  cancelled=true;retire(reason or'Cancelled')
  if not record then set_status('PAUSED',reason or'Cancelled')end
 end
 function API.Invalidate(reason)
  retire(reason or'Vehicle context changed')
 end
 function API.NeedsTick()return record~=nil end
 function API.Pending()return record~=nil end
 function API.Drain(now)API.Tick(false,now);return record==nil end
 function API.Snapshot()
  return{status=status,detail=detail,enabled=wanted,active=record~=nil and record.ready==true and not record.retiring,
   cleanupPending=record~=nil and record.retiring==true,vehicle=record and record.context.vehicle,
   address=record and record.context.address,parts=record and#record.parts or 0}
 end
 return API
end

