  if ped<=0 or not bool(H.exists,ped)or bool(H.dead,ped,false)then return nil,'Waiting for your character'end
  local vehicle=int(H.vehicle,ped,false)
  if vehicle<=0 or not bool(H.exists,vehicle)or bool(H.dead,vehicle,false)then return nil,'Enter a vehicle with a roof'end
  if int(H.driver,vehicle,-1,false)~=ped then return nil,'Use the driver seat'end
  if not bool(H.roof,vehicle)then return nil,'This vehicle has no closed roof'end
  if bool(H.convertible,vehicle,false)and int(H.roof_state,vehicle)~=0 then return nil,'Close the convertible roof first'end
