   if not bool(H.networked,vehicle)then return nil,'Online roof mounts require a networked vehicle'end
   carrierNetId=int(H.net_id,vehicle)
   if carrierNetId<=0 then return nil,'Waiting for the vehicle network registration'end
  end
  return{vehicle=vehicle,model=model,address=address(vehicle),ped=ped,pedAddress=address(ped),session=session(),
   driver=true,roof=true,usable=true,native=model==speedo,online=online,carrierNetId=carrierNetId}
