 local function expected_frames(record,pose,carrier)
  local base={right=transform(carrier,pose.base.basis.right),forward=transform(carrier,pose.base.basis.forward),
   up=transform(carrier,pose.base.basis.up),position=world_point(carrier,pose.base.position)}
  local angle=math.rad(pose.pitch);local c,s=math.cos(angle),math.sin(angle)
  local upper={right=base.right,
   forward=vector(c*base.forward.x+s*base.up.x,c*base.forward.y+s*base.up.y,c*base.forward.z+s*base.up.z),
   up=vector(-s*base.forward.x+c*base.up.x,-s*base.forward.y+c*base.up.y,-s*base.forward.z+c*base.up.z),
   position=world_point(base,record.assets.upperOffset)}
