  local parents={record.context.vehicle,record.parts[1].handle,record.parts[2].handle}
  local minimumDot=math.cos(math.rad(1));local maximumDistance2=.005*.005
  for index,part in ipairs(record.parts)do
   if not part_owned(part)then error('An owned turret component changed during pose verification')end
   if int(H.attached_to,part.handle)~=parents[index]then return false,part.name..' parent has not settled'end
   local actual=matrix(record,part.handle);local target=expected[index]
   if distance2(actual.position,target.position)>maximumDistance2 then return false,part.name..' origin differs from its mount'end
   for _,axis in ipairs({'right','forward','up'})do
