 function API.Step(record,now)
  assert(carrier_owned(record),'Vehicle identity changed while preparing the mount')
  if record.context.native then return native_step(record)end
  record.mode='portable'
  if not record.assets then
   local supplied=runtime.Assets or asset_manifest
   if type(supplied)=='function'then supplied=supplied()end
   local manifest=validate_manifest(supplied)
   if not manifest then return'unsupported','The reviewed three-part Speedo turret manifest is unavailable'end
   record.assets=manifest;record.partNames={'base','upper','barrel'};record.weapon=weapon
   record.hashes={}
   for _,name in ipairs(record.partNames)do
    record.hashes[name]=runtime.Utils.Joaat(manifest.models[name])&0xFFFFFFFF
   end
   buffer(record)
  end
  if not record.assetsReady then
   if type(runtime.EnsureAssets)=='function'then
    local ready,why=runtime.EnsureAssets(record.assets)
    if ready~=true then return'pending',why or'Loading the exact Speedo .50-cal assets'end
   end
   local loaded,pending=true,{}
   for _,name in ipairs(record.partNames)do
    local hash=record.hashes[name]
    local why
    if not bool(H.valid,hash)then why='not registered'
    elseif not bool(H.cdimage,hash)then why='not in streaming image'
    else
     if not record.modelRefs[hash]then record.modelRefs[hash]=true;void(H.request,hash)end
     if not bool(H.loaded,hash)then why='waiting for streaming'end
    end
    if why then loaded=false;pending[#pending+1]=name..': '..why end
   end
   if record.context.online then
    record.proxyModel=record.proxyModel or(runtime.Utils.Joaat(PROXY_MODEL)&0xFFFFFFFF)
    local hash=record.proxyModel
    if not bool(H.valid,hash)or not bool(H.cdimage,hash)then
     loaded=false;pending[#pending+1]='stock peer gun: unavailable'
    else
     if not record.modelRefs[hash]then record.modelRefs[hash]=true;void(H.request,hash)end
     if not bool(H.loaded,hash)then loaded=false;pending[#pending+1]='stock peer gun: waiting for streaming'end
    end
   end
