   backend='enhanced-interaction',scope='local-menu-and-extra-organization',phase=phase,reason=reason,menu_reason=reason,
   registration_verified=false,execution_verified=false,access_only=false,faulted=failed~=nil,
   scans=m.scans+g.scans,resources={am_pi_menu=m,freemode=g},
