 if active~=true then return nil,'No active Online session.'end
 local ok,value=pcall(function()
  assert(pointer(base),'Invalid module base')
  local function q(a)
   assert(pointer(a)and a<=0x7ffffffffff7,'Qword address outside canonical range')
   local v=mem.ReadLong(a);assert(math.type(v)=='integer','Invalid qword');return v
  end
