-- Own one verified keyboard-mode byte; preserve the stock send/cancel paths.
local function create_phone_keyboard_patch(get_context, spec)
    local NAME, HASH = spec.name, spec.hash
    local N = { loaded=0xE6CC9F3BA0FB9EF1, version=0xFCA9373EF340AC0A,
        request=0x6EB5F71AA68F2E8E, release=0xC90D2DCACD56184C }
    local PATTERN = spec.pattern
    local STOCK_PATTERN=PATTERN:gsub("%?","77")
    local OWNED_PATTERN=PATTERN:gsub("%?","72")
    local ANCHOR = spec.anchor
    local SIZE, OFFSET, ORIGINAL, PATCHED = 35, 7, 0x77, 0x72
    local api, owner, memory, native, globals = {}, nil, nil, nil, nil
    local wanted, initialized, next_check = false, false, 0
    local retained, requested_at = false, 0
    local status, detail, generation = "OFF", "", 0
    local phone_state, next_phone_check = nil, 0
    local function address(value)
        return type(value)=="number" and value==value and value%1==0
            and value>=0x10000 and value<0x00007FFFFFFFFFFF-SIZE
    end
    local function invoke(kind,hash,...)
        if not native or type(native.Try)~="function" then return false end
        return native.Try(kind,hash,...)
    end
    local function loaded()
        local ok,value=invoke("bool",N.loaded,NAME)
        if not ok or type(value)~="boolean" then return nil end
        return value
    end
    local function phone_screen()
        if not globals or type(globals.AreValid)~="function" or type(globals.GetInt)~="function" then return nil end
        local ok,valid=pcall(globals.AreValid)
        if not ok or valid~=true then return nil end
        -- Enhanced 1.73 appcontacts: Global_21666.f_1 > 3 is phone-visible.
        local read,value=pcall(globals.GetInt,21667)
        if read and type(value)=="number" and value%1==0 and value>=0 and value<=10 then return value end
    end
    local function scan(pattern)
        local ok,value=pcall(memory.ScanScript,HASH,pattern)
        if ok and address(value) then return value end
    end
    local function bytes(ptr)
        local data={}
        for i=0,SIZE-1 do
            local ok,value=pcall(memory.ReadUByte,ptr+i)
            if not ok or type(value)~="number" or value%1~=0 or value<0 or value>255 then return nil end
            data[i+1]=value
        end
        return data
    end
    local function equal(a,b,mode)
        if not a or not b then return false end
        for i=1,SIZE do
            if a[i]~=(i==OFFSET+1 and mode or b[i]) then return false end
        end
        return true
    end
    local function matches(data,pattern)
        local index=0
        for token in pattern:gmatch("%S+") do
            index=index+1
            if token~="?" and data[index]~=tonumber(token,16) then return false end
        end
        return index==SIZE
    end
    local function find()
        -- ScanScript resolves the currently loaded resource. In particular,
        -- unload cleanup must not enter a script native from Cherax's worker.
        if not memory then return nil end
        local entry=scan("2D")
        if not entry then return nil end
        local ptr,anchor=scan(STOCK_PATTERN) or scan(OWNED_PATTERN),scan(ANCHOR)
        if not ptr or not anchor or ptr-anchor~=spec.distance then return nil end
        local data,control=bytes(ptr),bytes(anchor)
        if not data or not control or not matches(data,PATTERN) or not matches(control,ANCHOR) then return nil end
        -- IS_PC_VERSION and GET_CURRENT_LANGUAGE must be the same native-table
        -- entries in both selectors; never infer native identity from a number.
        for _,i in ipairs({3,4,16,17}) do if data[i]~=control[i] then return nil end end
        if data[3]==data[16] and data[4]==data[17] then return nil end
        if scan("2D")~=entry then return nil end
        return {ptr=ptr,anchor=anchor,data=data,control=control,entry=entry}
    end
    local function restore()
        if owner then
            -- Fresh script resolution precedes every restore; never dereference
            -- a cached address after the script resource unloads or is replaced.
            local current=find()
            if not current then
                -- A temporarily unavailable scanner/read is not proof that the
                -- script was destroyed. Dropping this owner strands our patched
                -- byte: the next retry correctly refuses to adopt a prepatched
                -- resource, so the enabled intent can never recover or restore.
                -- Keep cleanup debt without reading the cached address. Tick
                -- may separately prove unload from the gameplay-thread native.
                status,detail="RESTORE_PENDING","Phone input restoration is waiting for a verified resource."
                return false
            end
            if current.ptr~=owner.ptr or current.anchor~=owner.anchor
                or not equal(current.control,owner.control,ORIGINAL) then
                owner=nil
                return true -- The old resource is gone; never write its address.
            end
            if equal(current.data,owner.data,PATCHED) then
                pcall(memory.WriteUByte,current.ptr+OFFSET,ORIGINAL)
                local observed=find()
                if not observed or observed.ptr~=owner.ptr
                    or not equal(observed.data,owner.data,ORIGINAL) then
                    status,detail="RESTORE_PENDING","Phone input restoration needs another attempt."
                    return false
                end
            elseif not equal(current.data,owner.data,ORIGINAL) then
                owner=nil
                return true -- Preserve another owner's change.
            end
            owner=nil
        end
        return true
    end
    local function defer(reason, unavailable, now)
        -- A resource reload/signature mismatch may be transient. Relinquish any
        -- owned byte safely, preserve the user's requested toggle, and retry.
        restore()
        if owner then owner.recheck=true end
        status,detail=unavailable and "UNAVAILABLE" or "WAITING",tostring(reason or "Phone input not ready.")
        next_check=(tonumber(now) or 0)+(unavailable and 1500 or 350)
    end
    function api.Set(enabled)
        wanted=enabled==true;generation=generation+1;next_check=0
        if wanted then status,detail="QUEUED","Open a new phone text after enabling." end
    end
    function api.Tick(now)
        if not wanted and not owner and not retained then return end
        now=tonumber(now) or 0
        if initialized and wanted and now>=next_phone_check then
            next_phone_check=now+100
            local screen=phone_screen()
            if screen and screen>3 and screen~=phone_state then next_check=0 end
            phone_state=screen
        end
        if now<next_check then return end
        next_check=now+100
        if not wanted then
            -- Tick runs on the gameplay thread; Stop can run on the host worker
            -- and must remain script-native free. Only a successful false load
            -- observation can retire an unresolved old resource here.
            if owner then
                local ok,present=invoke("bool",N.loaded,NAME)
                if ok and present==false then owner=nil end
            end
            if restore() then
                if retained then
                    local ok=invoke("void",N.release,NAME)
                    if ok then retained=false end
                end
                status,detail=retained and "RESTORE_PENDING" or "OFF",
                    retained and "Phone input loading reference release is pending." or ""
            end
            return
        end
        if owner then
            -- Phone closed: avoid two full phone script-discovery probes
            -- per second. Opening the phone forces next_check=0 above.
            next_check=now+((phone_state~=nil and phone_state<=3) and 5000 or 1000)
            local present=loaded()
            if present==nil then
                -- An unavailable native observation is not an unload event.
                status,detail="WAITING","Phone resource status unavailable; retrying."
                next_check=now+100
                return
            elseif present==false then
                owner=nil
                status,detail="WAITING","Open the phone to enable punctuation for new texts."
                next_check=now+100
            else
                -- Both supported resources start with ENTER (2D). This lookup
                -- stops at the first byte instead of searching megabytes of code.
                -- It only signals rediscovery: every write/restore still resolves
                -- full signatures, and this path never reads cached patch addresses.
                local entry=scan("2D")
                if not entry then
                    status,detail="WAITING","Phone resource discovery unavailable; retrying."
                    next_check=now+100
                    return
                elseif entry==owner.entry and not owner.recheck and phone_state~=nil and phone_state<=3 then
                    status,detail="ACTIVE","Phone text input is ready."
                    return
                end
                local current=find()
                if current and current.ptr==owner.ptr and current.anchor==owner.anchor
                    and equal(current.data,owner.data,PATCHED)
                    and equal(current.control,owner.control,ORIGINAL) then
                    owner.entry=current.entry
                    owner.recheck=nil
                    status,detail="ACTIVE","Phone text input is ready."
                elseif current and equal(current.data,owner.data,ORIGINAL) then
                    owner=nil
                    status,detail="WAITING","Phone input resource reloaded."
                    next_check=now
                else
                    defer("Phone input ownership could not be verified; retrying.",false,now)
                end
            end
            if owner then return end
        end
        if not initialized then
            local ctx=get_context()
            local host=ctx and ctx.Cherax
            memory=host and type(host.Get)=="function" and host.Get("Memory") or nil
            globals=host and type(host.Get)=="function" and host.Get("ScriptGlobal") or nil
            native=ctx and ctx.Natives or nil
            if not memory or type(memory.ScanScript)~="function"
                or type(memory.ReadUByte)~="function" or type(memory.WriteUByte)~="function"
                or not native or type(native.Try)~="function" then
                defer("Phone input access is unavailable in this host.",true,now);return
            end
            local ok,version=invoke("string",N.version)
            if not ok or version~="1.73" then
                defer("This phone input layout is not supported by the running game.",true,now);return
            end
            initialized=true
        end
        -- Only the contacts resource needs a retained preload reference.
        if spec.preload and not retained then
            retained,requested_at=true,now -- keep cleanup ownership if host call throws
            local ok=invoke("void",N.request,NAME)
            if not ok then
                status,detail="WAITING","Phone input preload is pending."
                next_check=now+350
                return
            end
        end
        if not loaded() then
            status,detail="WAITING","Preparing punctuation for compose and reply."
            if spec.preload and now-requested_at>=5000 then
                local ok=invoke("void",N.release,NAME)
                if ok then retained=false end
                status,detail="UNAVAILABLE","Phone input preload did not become ready; retrying."
                next_check=now+1500
            end
            return
        end
        local current=find()
        if not current or current.data[OFFSET+1]~=ORIGINAL then
            defer("Phone input resource changed; waiting for a verified text box.",false,now);return
        end
        local token=generation
        if not wanted then
            if restore() then status,detail="OFF","" end
            return
        end
        owner=current -- retain compensation ownership even if a write throws
        pcall(memory.WriteUByte,current.ptr+OFFSET,PATCHED)
        local observed=find()
        if not observed or observed.ptr~=current.ptr or observed.anchor~=current.anchor
            or not equal(observed.data,current.data,PATCHED)
            or not equal(observed.control,current.control,ORIGINAL) then
            defer("Phone input change could not be verified; retrying safely.",false,now);return
        end
        if not wanted or generation~=token then
            if restore() and not wanted then status,detail="OFF","" end
            return
        end
        status,detail="ACTIVE","Phone text input is ready."
        next_check=now+1000
    end
    function api.Stop()
        wanted=false;generation=generation+1;next_check=0
        local ok=restore()
        if ok and not retained then status,detail="OFF",""
        elseif retained then status,detail="RESTORE_PENDING","Phone input loading reference release is queued." end
        return ok and not retained
    end
    function api.HasWork() return wanted or owner~=nil or retained end
    function api.Snapshot()
        return {requested=wanted,status=status,detail=detail,owned=owner~=nil,
            retained=retained,live_verified=false}
    end
    function api.Status() return wanted,status,detail end
    return api
end

-- New texts and Online replies use separate script-owned keyboard selectors.
local function create_phone_text_input(get_context)
    local compose = create_phone_keyboard_patch(get_context, {
        name = "appcontacts", hash = 0xB7387687, preload = true, distance = 0x7E,
        pattern = "2C 01 00 16 56 06 00 ? 39 33 55 11 00 2C 01 00 C1 71 57 06 00 71 39 33 55 03 00 72 39 33 38 04 56 08 01",
        anchor = "2C 01 00 16 56 06 00 77 39 32 55 11 00 2C 01 00 C1 71 57 06 00 71 39 32 55 03 00 72 39 32 38 18 56 14 00",
    })
    local reply = create_phone_keyboard_patch(get_context, {
        name = "freemode", hash = 0xC875557D, preload = false, distance = 0x80,
        pattern = "2C 01 06 D3 56 06 00 ? 39 33 55 11 00 2C 01 08 6F 71 57 06 00 71 39 33 55 03 00 72 39 33 38 04 56 0D 01",
        anchor = "2C 01 06 D3 56 06 00 77 39 32 55 11 00 2C 01 08 6F 71 57 06 00 71 39 32 55 03 00 72 39 32 38 18 56 16 00",
    })
    local api, wanted = {}, false
    function api.Set(enabled)
        wanted = enabled == true
        compose.Set(wanted); reply.Set(wanted)
    end
    function api.Tick(now) compose.Tick(now); reply.Tick(now) end
    function api.HasWork() return compose.HasWork() or reply.HasWork() end
    function api.Status()
        if not wanted then
            return false, api.HasWork() and "RESTORE_PENDING" or "OFF", ""
        end
        local _, first, first_detail = compose.Status()
        local _, second, second_detail = reply.Status()
        if first == "ACTIVE" and second == "ACTIVE" then
            return true, "ACTIVE", "Punctuation enabled for new texts and replies."
        end
        if first == "UNAVAILABLE" then return true, first, first_detail end
        if second == "UNAVAILABLE" then return true, second, second_detail end
        return true, "WAITING", "Preparing punctuation for new texts and replies."
    end
    function api.Stop()
        wanted = false
        local first, second = compose.Stop(), reply.Stop()
        return first and second
    end
    function api.Snapshot()
        local _, status, detail = api.Status()
        local first, second = compose.Snapshot(), reply.Snapshot()
        return { requested = wanted, status = status, detail = detail,
            owned = first.owned or second.owned, retained = first.retained,
            compose_owned = first.owned, reply_owned = second.owned, live_verified = false }
    end
    return api
end

