        active=false,blocked=false,closed=false,epoch=0,serial=0,next_due=0,
        supported=false,readable=false,ready=false,owners={},restore=false}
    local api={}
    local function integer(v) return type(v)=='number' and v==v and v%1==0 end
    local function pointer(v) return integer(v) and v>=0x10000 and v<0x800000000000 and v%8==0 end
    local function enum(v) return integer(v) and v>=0 and v<=3 end
    local function owned() return next(s.owners)~=nil end
    local function outstanding() return owned() or s.flight~=nil end
    local function message(err) return type(err)=='table' and tostring(err.detail) or tostring(err) end
    local function reject(detail) error({unsupported=true,detail=detail},0) end
    local function describe(detail)
        local o=s.observed
        if not o then return tostring(detail) end
        return tostring(detail)..(' [source=%s cache=%s detector=%s branch=%s]'):format(
            tostring(o.source),tostring(o.cache),tostring(o.detector_state),tostring(o.branch))
    end
    local function status(name,detail) s.status=name;s.detail=describe(detail) end
    local function snapshot()
        local o=s.observed or {}; local uncertain=false
        for _,owner in pairs(s.owners) do uncertain=uncertain or owner.pending~=nil end
        return {requested=s.requested,requested_value=s.value,status=s.status,detail=s.detail,
            active=s.active,cache_owned=s.owners.cache~=nil,source_owned=s.owners.source~=nil,
            propagation_pending=false,cleanup_pending=owned() and (s.restore or not s.requested),
            in_flight=s.flight~=nil,cache_value=o.cache,source_value=o.source,
            persistent_value=o.persistent,detector_state=o.detector_state,
            detector_initialized=o.initialized,branch_value=o.branch,
            blocked=s.blocked,supported=s.supported,readable=s.readable,ready=s.ready,
            forced_closed=s.closed,ownership_uncertain=uncertain,
            scope='local-reported',remote_verified=false,local_propagation_verified=false}
    end
    local function context()
        assert(type(host)=='table' and type(host.memory)=='function','memory host unavailable')
        local m=host.memory()
        assert(m and type(m.GetBaseAddress)=='function' and type(m.ReadUByte)=='function'
            and type(m.ReadUShort)=='function' and type(m.ReadUInt)=='function'
            and type(m.ReadLong)=='function','required memory readers unavailable')
        local b=m.GetBaseAddress(MODULE)
        if not pointer(b) or b%0x1000~=0 or b+IMAGE_SIZE>=0x800000000000 then
            reject('Expected Enhanced module is unavailable.')
        end
        local c={m=m, base=b, reads=0}
        function c.read(kind, address, width, unsigned)
            assert(pointer(address-(address%8)) and address+width<0x800000000000,'invalid read address')
            c.reads=c.reads+1; assert(c.reads<=READ_LIMIT,'bounded read budget exceeded')
            local v=m[kind](address)
            assert(integer(v) and (not unsigned or (v>=0 and v<2^(8*width))),'invalid typed read')
            return v
        end
        function c.u8(rva) return c.read('ReadUByte',b+rva,1,true) end
        function c.u16(rva) return c.read('ReadUShort',b+rva,2,true) end
        function c.u32(rva) return c.read('ReadUInt',b+rva,4,true) end
        function c.i64(rva) return c.read('ReadLong',b+rva,8,false) end
        return c
    end
    local function executable(rva, count)
        for _, row in ipairs(sections) do
            if (row[6]&0x20000000)~=0 and rva>=row[2]
                and rva+count<=row[2]+math.max(row[3],row[4]) then return true end
        end
        return false
    end
    local function validate(c)
        if c.m.GetBaseAddress(MODULE)~=c.base then reject('Module base changed during validation.') end
        if c.u16(0)~=0x5A4D then reject('Unsupported MZ header.') end
        local pe=c.u32(0x3C)
        if pe<64 or pe+24+0xF0+#sections*40>HEADER_SIZE then reject('Unsupported PE header bounds.') end
        if c.u32(pe)~=0x4550 or c.u16(pe+4)~=0x8664 or c.u16(pe+6)~=#sections
            or c.u32(pe+8)~=TIMESTAMP or c.u16(pe+20)~=0xF0 or c.u16(pe+24)~=0x20B
            or c.u32(pe+24+56)~=IMAGE_SIZE or c.u32(pe+24+60)~=HEADER_SIZE then
            reject('Unsupported executable identity.')
        end
        for i,row in ipairs(sections) do
            local at=pe+24+0xF0+(i-1)*40
            local name={}; for j=0,7 do name[#name+1]=string.char(c.u8(at+j)) end
            if table.concat(name):gsub('%z+$','')~=row[1] or c.u32(at+8)~=row[3]
                or c.u32(at+12)~=row[2] or c.u32(at+16)~=row[4]
                or c.u32(at+20)~=row[5] or c.u32(at+36)~=row[6] then
                reject('Unsupported section layout at index '..(i-1)..'.')
            end
        end
        if c.u32(pe+24+112+3*8)~=0x4FAC000 or c.u32(pe+24+112+3*8+4)~=868956 then
            reject('Unsupported exception directory.')
        end
        for _,p in ipairs(proofs) do
            if not executable(p.rva,#p.bytes) then reject('Code proof outside an executable section.') end
            local at=1
            while at+3<=#p.bytes do
                local expected=string.unpack('<I4',p.bytes,at)
                if c.u32(p.rva+at-1)~=expected then reject('Live code proof changed: '..p.name..'.') end
                at=at+4
            end
            while at<=#p.bytes do
                if c.u8(p.rva+at-1)~=p.bytes:byte(at) then reject('Live code proof changed: '..p.name..'.') end
                at=at+1
            end
        end
        local function rel32(at, expected)
            local disp=c.u32(at); if disp>=0x80000000 then disp=disp-0x100000000 end
            if at+4+disp~=expected then reject('Captured relative-address relationship changed.') end
        end
        rel32(0x11D1AB6,R.cache); rel32(0x11D7BD1,R.source); rel32(0x11D7BD7,R.cache)
        rel32(0x11B868F,R.cache); rel32(0x11B869E,R.cache); rel32(0x11B8698,0x11D7B20)
        rel32(0x11B839D,R.socket); rel32(0x11B8513,R.branch)
        rel32(0x6EAEA3,0x3E0DA70); rel32(0x6EAEC1,0x11B82D0)
        rel32(0x6EB198,0x11B82D0); rel32(0x6E9770,R.refresh)
        rel32(0x11D1D33,R.detector_state); rel32(0x11D1AE3,R.initialized-1) -- CMP has a trailing immediate byte.
        s.profile_base=c.base; s.supported=true
    end
    -- The source is the detector's coarse result; the cache is its lazy public
    -- getter. This backend owns only those two DWORDs. Peer state and relay
    -- selection are observations, never destinations or success criteria.
    local function observe(c)
        local o={base=c.base,cache=c.u32(R.cache),source=c.u32(R.source),
            persistent=c.u32(R.persistent),flags=c.u32(R.flags),branch=c.u8(R.branch),
            initialized=c.u8(R.initialized),detector_state=c.u32(R.detector_state),
            signin=c.u8(R.signin),socket=c.i64(R.socket),
            detector_iterator=c.i64(R.detector_iterator),presence_iterator=c.i64(R.presence_iterator)}
        if pointer(o.socket) and o.socket+16<0x800000000000 then
            o.socket_value=c.read('ReadLong',o.socket+8,8,false)
        end
        o.valid=enum(o.cache) and enum(o.source) and enum(o.persistent)
        o.idle=o.detector_iterator==0 and o.presence_iterator==0
        if not o.valid then o.reason='A NAT enum is outside 0..3.'
        elseif o.initialized~=1 then o.reason='NAT detector is not initialized.'
        elseif o.detector_state~=9 then o.reason='Waiting for terminal successful NAT detection (state 9).'
        elseif not pointer(o.socket) or o.socket_value==nil or o.socket_value<0 then o.reason='Network socket is not ready.'
        elseif (o.flags&2)==0 then o.reason='Network address detection is not ready.'
        elseif (o.signin&2)==0 then o.reason='Local presence is not signed in.'
        elseif o.branch~=0 and o.branch~=1 then o.reason='Unknown peer-builder branch value.'
        elseif not o.idle then o.reason='An engine delegate iterator is active.' end
        o.ready=o.reason==nil
        s.observed=o;s.readable=true;s.ready=o.ready
        return o
    end
    local function generation(o)
        return {base=o.base,initialized=o.initialized,detector_state=o.detector_state,
            flags=o.flags,socket=o.socket,socket_value=o.socket_value,signin=o.signin&2}
    end
    local function same_generation(g,o)
        return g.base==o.base and g.initialized==o.initialized and g.detector_state==o.detector_state
            and g.flags==o.flags and g.socket==o.socket and g.socket_value==o.socket_value
            and g.signin==(o.signin&2)
    end
    local function blocked(detail)
        s.active=false;s.blocked=true;s.restore=owned()
        status(s.restore and 'RESTORE_PENDING' or 'BLOCKED',detail)
    end
    local function foreign(key)
        s.owners[key]=nil
        if key=='source' and s.owners.cache then s.owners.cache.invalidated=true end
        blocked('Another writer changed the '..key..'; preserving its value and cleaning up only owned values.')
    end
    local function reconcile(o)
        for _,key in ipairs({'source','cache'}) do
            local owner=s.owners[key]
            if owner then
                if owner.generation.base~=o.base then reject('NAT ownership belongs to a different module instance.') end
                if not same_generation(owner.generation,o) then owner.invalidated=true end
                if key=='cache' and not s.owners.source and o.source~=owner.source_baseline then
                    owner.invalidated=true
                end
                local p=owner.pending
                if p then
                    if o[key]==p.wanted then
                        owner.last=p.wanted;owner.pending=nil
                        if p.action=='reset' or (p.action=='restore' and not owner.invalidated) then
                            s.owners[key]=nil
                        end
                    elseif o[key]==p.before then
                        owner.pending=nil;owner.last=p.before
                        if p.created then s.owners[key]=nil end
                    else foreign(key) end
                elseif o[key]~=owner.last then foreign(key) end
            end
        end
        local cache=s.owners.cache
        if cache and not s.owners.source and o.source~=cache.source_baseline then cache.invalidated=true end
        for _,owner in pairs(s.owners) do
            if owner.invalidated then
                blocked('Detector/network generation changed; stale baseline restoration is deferred.')
                break
            end
        end
    end
    local function intent()
        if not s.requested or s.blocked or s.closed then return false end
        if s.intent_fn then
            local ok,wants=pcall(s.intent_fn)
            if not ok or wants~=true then
                s.requested=false;s.epoch=s.epoch+1;s.active=false;s.restore=owned()
                status(s.restore and 'RESTORE_PENDING' or 'OFF',ok and 'Latest feature intent is off.' or 'Feature intent is unavailable.')
                return false
            end
        end
        return s.requested and not s.blocked and not s.closed
    end
    local function allowed()
        if type(host.write_allowed)~='function' then return false end
        local ok,value=pcall(host.write_allowed);return ok and value==true
    end
    local function current(epoch,value)
        return s.requested and not s.closed and not s.blocked and not s.restore
            and s.epoch==epoch and s.value==value
    end
    local function permits_apply(epoch,value)
        if not intent() or not current(epoch,value) then return false end
        if not allowed() then return false end
        -- Both host callbacks may re-enter SetRequested/ForceClose. The last
        -- decision before mutation/confirmation must therefore be pure state.
        return current(epoch,value)
    end
    local function write(c,o,key,value,action,epoch)
        if s.closed then return false end
        local writer=c.m.WriteInt
        assert(type(writer)=='function','NAT enum writer is unavailable')
        if s.closed or (action=='apply' and not current(epoch,value)) then return false end
        local owner=s.owners[key];local created=owner==nil
        if created then
            assert(action=='apply','cleanup cannot acquire an unowned value')
            local source=s.owners.source
            owner={baseline=o[key],last=o[key],generation=generation(o),
                source_baseline=source and source.baseline or o.source,invalidated=false}
            s.owners[key]=owner
        end
        assert(o[key]==owner.last,'NAT value changed before journaled write')
        owner.pending={wanted=value,before=o[key],created=created,action=action}
        -- WriteInt is documented void. nil/false/true return values do not
        -- acknowledge an effect; the typed readback is the acknowledgement.
        local ok,why=pcall(writer,c.base+R[key],value)
        local read_ok,after=pcall(observe,c)
        if not read_ok then
            if not s.closed then blocked('NAT write acknowledgement failed; pending ownership retained: '..message(after)) end
            return false
        end
        reconcile(after)
        if s.closed then return false end
        if after[key]~=value then
            blocked('NAT '..action..' did not read back: '..(ok and 'unchanged or replaced value' or message(why)))
            return false
        end
        local held=s.owners[key]
        if held and held.invalidated then return false end
        return true,after
    end
    local function cleanup(c,o)
        s.active=false
        -- Source is restored before cache so cache invalidation can never
        -- repopulate from our stale source override.
        for _,key in ipairs({'source','cache'}) do
            if s.closed then return end
            local owner=s.owners[key]
            if owner then
                validate(c);o=observe(c);reconcile(o);owner=s.owners[key]
                if owner then
                    if not o.ready then
                        s.restore=true;status('RESTORE_PENDING',o.reason);return
                    end
                    if key=='source' and owner.invalidated then
                        s.restore=true
                        status('RESTORE_PENDING','Waiting for the detector to replace an owned result from an earlier generation.')
                        return
                    end
                    if key=='cache' and s.owners.source then
                        s.restore=true;status('RESTORE_PENDING','Source cleanup is still unresolved.');return
                    end
                    local reset=key=='cache' and owner.invalidated
                    local value=reset and 0 or owner.baseline
                    if o[key]==value then s.owners[key]=nil
                    else
                        local ok,after=write(c,o,key,value,reset and 'reset' or 'restore')
                        if not ok then return end
                        o=after
                    end
                end
            end
        end
        s.restore=owned()
        if not s.restore then
            status(s.blocked and 'BLOCKED' or 'OFF',s.blocked and
                'Owned values released; external values preserved. Toggle off and on to rearm.' or
                'Original local NAT reports restored.')
        end
    end
    local function work()
        local wants=intent()
        if not wants and not owned() then s.active=false;s.restore=false;return end
        local c=context();validate(c)
        local o=observe(c);reconcile(o)
        if s.restore or not wants or s.blocked then cleanup(c,o);return end
        if not allowed() then
            s.active=false
            if owned() then s.restore=true;cleanup(c,o)
            else status('WAITING','New gameplay writes are suspended.') end
            return
        end
        if not o.ready then s.active=false;status('WAITING',o.reason);return end
        local wanted,epoch=s.value,s.epoch
        for _,key in ipairs({'source','cache'}) do
            if s.closed then return end
            if not permits_apply(epoch,wanted) then
                s.active=false;s.restore=owned();return
            end
            if o[key]~=wanted then
                validate(c);o=observe(c);reconcile(o)
                if s.closed then return end
                if s.blocked or s.restore then return end
                if not o.ready then s.active=false;status('WAITING',o.reason);return end
                if not permits_apply(epoch,wanted) then
                    s.active=false;s.restore=owned();return
                end
                if o[key]~=wanted then
                    local ok,after=write(c,o,key,wanted,'apply',epoch)
                    if not ok then return end
                    o=after
                end
            end
        end
        o=observe(c);reconcile(o)
        if s.closed then return end
        if not permits_apply(epoch,wanted)
            or not o.ready or o.source~=wanted or o.cache~=wanted then
            s.active=false;s.restore=owned()
            if not s.blocked then status(s.restore and 'RESTORE_PENDING' or 'WAITING','NAT report pair changed before final confirmation.') end
            return
        end
        s.active=true
        status('LOCAL_REPORTED','Detector source and hardware NAT report match the selection; peer advertisement is unverified.')
    end
    function api.SetRequested(enabled,value,intent_fn)
        if s.closed then return false,'Backend is closed.' end
        enabled=enabled==true
        local changed=enabled~=s.requested or (enabled and value~=s.value)
        if changed then s.epoch=s.epoch+1;s.next_due=0 end
        if not enabled then
            s.requested=false;s.active=false;s.restore=owned()
            if not s.restore then status('OFF','Local NAT report override is off.') end
        else
            if not s.requested and not owned() then s.blocked=false end
            s.requested=true;s.value=value
            if not enum(value) or value==0 then
                blocked('Requested NAT must be Open(1), Moderate(2), or Strict(3).')
                return false,s.detail
            end
            if changed then s.active=false;status('PENDING','Waiting for queued local NAT report work.') end
        end
        s.intent_fn=type(intent_fn)=='function' and intent_fn or nil
        return true
    end
    function api.RequestRestore(reason)
        if s.requested then s.epoch=s.epoch+1 end
        s.requested=false;s.active=false;s.restore=owned();s.next_due=0
        status(s.restore and 'RESTORE_PENDING' or 'OFF',reason or 'Local NAT restoration requested.')
        return not outstanding()
    end
    function api.HasWork() return outstanding() or (s.requested and not s.blocked and not s.closed) end
    function api.Snapshot() return snapshot() end
    function api.Tick(now)
        if s.closed or s.flight or not api.HasWork() then return false end
        if not integer(now) then
            local ok,value=pcall(host.now_ms)
            if not ok or not integer(value) then status('WAITING','Clock is unavailable.');return false end
            now=value
        end
        if now<s.next_due then return false end
        local ok,script=pcall(host.script)
        if not ok or not script or type(script.QueueJob)~='function' then
            status('WAITING','Native job queue is unavailable.');s.next_due=now+RETRY_MS;return false
        end
        s.serial=s.serial+1
        local token={id=s.serial,epoch=s.epoch};s.flight=token
        local submitted,why=pcall(script.QueueJob,function()
            if s.flight~=token or s.closed then return end
            if token.epoch~=s.epoch then
                s.flight=nil;s.next_due=0
                if not owned() then
                    s.restore=false
                    if not s.requested then status('OFF','Queued NAT work canceled before mutation.') end
                end
                return
            end
            local done,err=pcall(work)
            if not done and not s.closed then
                s.active=false
                if type(err)=='table' and err.unsupported then
                    s.supported=false;s.blocked=true;s.restore=owned();status('UNSUPPORTED',message(err))
                else
                    s.readable=false
                    if owned() then s.blocked=true;s.restore=true end
                    status(owned() and 'RESTORE_PENDING' or 'WAITING','Host operation failed; ownership retained: '..message(err))
                end
            end
            if s.flight==token then s.flight=nil end
            s.next_due=now+RETRY_MS
        end)
        -- QueueJob's integer ID has no documented success/failure sentinel.
        if not submitted or why==false then
            if s.flight==token then s.flight=nil end
            s.next_due=now+RETRY_MS;status('WAITING','Native job submission failed: '..tostring(why));return false
        end
        return true
    end
    function api.Probe()
        local ok,why=pcall(function()
            local c=context();validate(c)
            local o=observe(c);reconcile(o)
            if s.active and (not o.ready or o.source~=s.value or o.cache~=s.value or not intent()) then
                s.active=false;s.restore=owned()
                if not s.blocked then
                    status(s.restore and 'RESTORE_PENDING' or 'WAITING',o.reason or 'Local NAT report pair no longer matches the selection.')
                end
            elseif s.active then
                status('LOCAL_REPORTED','Detector source and hardware NAT report match the selection; peer advertisement is unverified.')
            elseif not s.blocked and not o.ready then status(owned() and 'RESTORE_PENDING' or 'WAITING',o.reason)
            elseif not s.blocked then status(s.status,'Local NAT report values are readable; no change made.') end
        end)
        if not ok then
            s.active=false;s.ready=false;s.readable=false;s.observed=nil
            if owned() then s.blocked=true;s.restore=true end
            if type(why)=='table' and why.unsupported then
                s.supported=false;s.blocked=true;status('UNSUPPORTED',message(why))
            else status(owned() and 'RESTORE_PENDING' or 'WAITING','Read-only NAT probe failed; ownership retained: '..message(why)) end
        end
        return snapshot()
    end
    function api.ForceClose(reason)
        s.closed=true;s.requested=false;s.active=false;s.epoch=s.epoch+1;s.flight=nil;s.restore=owned()
        status('CLOSED',reason or (s.restore and 'Forced close retains unresolved NAT ownership.' or 'NAT backend closed.'))
        return not owned()
    end
    return api
end

-- Read-only player observations; only our local map blips are mutated.
local function create_respawn_host(deps)
    local N,M=deps.Natives or {},deps.Memory or {}
    local function call(kind,hash,...)
        local fn=N[kind];if type(fn)~="function" then return nil end
        local ok,a,b,c=pcall(fn,hash,...);if ok then return a,b,c end
    end
    local function boolean(hash,...)
        local v=call("InvokeBool",hash,...)
        if v==true or v==1 then return true elseif v==false or v==0 then return false end
    end
    local host={}
    function host.notify(message) if type(deps.toast)=="function" then deps.toast(message) end end
    function host.report(message) if type(deps.log_info)=="function" then deps.log_info("Respawn map "..message) end end
    function host.online()
        return boolean(0x9DE624D2FC4B603F)==true and boolean(0x68049AEFF83D8F0A)==false
    end
    -- Host-approved reservations, traced in the user's extracted Enhanced
    -- freemode resource 985a416fac7d1106. Match loaded code before any reads.
    local G=deps.ScriptGlobal or {}
    local profile,attempts,next_probe,next_layout=false,0,0,0
    local BASE=2649164
    local signatures={
    '03 32 74 37 03 41 01 61 4C 6C 28 40 83 34 03 33 37 03 41 28 71 58 20 00',
    '36 01 72 37 03 41 01 61 4C 6C 28 46 05 01 36 01 71 37 03 41 01 61 4C 6C 28 46 26 01 36 01 61 4C 6C 28 47 68 01 37 03 41 01 61 4C 6C 28 46 47 01 36 01',
    '2D 04 0C 00 00 28 C3 CB EF 1C 39 06 2C 01 04 08 37 06 42 01 38 01 37 06 42 03 38 02 37 06 42 04 38 03 37 06 42 05'
}
    local function read(fn,...)
        if type(fn)~="function" then return nil end
        local ok,v=pcall(fn,...);if ok then return v end
    end
    function host.reset() profile=false;attempts=0;next_probe=0;next_layout=0 end
    function host.prepare(now)
        if read(G.AreValid)~=true then profile=false;return end
        if profile and now>=next_layout then
            next_layout=now+1000
            for _,off in ipairs({131,228,261,294,327})do
                if read(G.GetInt,BASE+off)~=32 then profile=false;break end
            end
        end
        if profile or now<next_probe or attempts>=3 then return end
        attempts=attempts+1;next_probe=now+5000
        local hash=deps.Utils and read(deps.Utils.Joaat,"freemode")
        if not hash then return end
        for _,pattern in ipairs(signatures)do
            local address=read(M.ScanScript,hash,pattern)
            if type(address)~="number" or address<=0 then return end
        end
        for _,off in ipairs({131,228,261,294,327})do
            if read(G.GetInt,BASE+off)~=32 then return end
        end
        profile=true;next_layout=now+1000
        host.report("reservation profile matched")
    end
    local function reservation(id)
        if not profile then return nil end
        local seq=read(G.GetInt,BASE+328+id)
        local stamp=read(G.GetInt,BASE+229+id)
        local active=read(G.GetInt,BASE+262+id)
        local index=BASE+132+id*3
        local pos={x=read(G.GetFloat,index),y=read(G.GetFloat,index+1),z=read(G.GetFloat,index+2)}
        if type(seq)~="number" or seq%1~=0 or type(stamp)~="number"
            or (active~=0 and active~=1) or seq~=read(G.GetInt,BASE+328+id)
            or stamp~=read(G.GetInt,BASE+229+id) or active~=read(G.GetInt,BASE+262+id) then return nil end
        return {seq=seq,active=active==1,pos=pos}
    end
    -- Validated against the captured 41-word candidate requests. Event hooks
    -- only decode/queue data; map natives run on the gameplay tick.
    function host.candidate(sender,args)
        if not profile or type(args)~="table" or #args~=41 then return nil end
        for i=1,41 do if math.type(args[i])~="integer" then return nil end end
        if (args[1]&0xFFFFFFFF)~=((-1013606569)&0xFFFFFFFF) then return nil end
        local id=sender
        if type(id)~="number" then
            id=nil
            for _,field in ipairs({"PlayerId","PlayerID","Index"})do
                local ok,value=pcall(function()return sender[field]end)
                if ok and type(value)=="number" then id=value;break end
            end
        end
        if type(id)~="number" or id%1~=0 or id<0 or id>31 or id==deps.local_player_id() or args[2]~=id then return nil end
        for _,i in ipairs({4,20,26,32})do if args[i]~=5 then return nil end end
        local points={}
        local function float(word)return string.unpack('<f',string.pack('<I4',word&0xFFFFFFFF))end
        for i=0,4 do
            local j=5+i*3
            local x,y,z=float(args[j]),float(args[j+1]),float(args[j+2])
            if x~=x or y~=y or z~=z or math.abs(x)>=100000 or math.abs(y)>=100000 or math.abs(z)>=100000 then return nil end
            if math.abs(x)+math.abs(y)+math.abs(z)>0.01 then points[#points+1]={x=x,y=y,z=z}end
        end
        if #points==0 then return nil end
        local player=deps.Players and deps.Players.GetById(id)
        local info=player and player:GetGamerInfo()
        if not info or not info.RockstarId or info.RockstarId==0 or not info.HostKey or info.HostKey==0 then return nil end
        return id,tostring(info.RockstarId)..":"..tostring(info.HostKey),{points=points,checksum=args[38]&0xFFFFFFFF}
    end
    function host.sample(id)
        if id==deps.local_player_id() or not deps.player_available(id) then return nil end
        local player=deps.Players and deps.Players.GetById(id)
        local info=player and player:GetGamerInfo()
        if not info or not info.RockstarId or info.RockstarId==0 or not info.HostKey or info.HostKey==0 then return nil end
        local identity=tostring(info.RockstarId)..":"..tostring(info.HostKey)
        local ped=call("InvokeInt",0x50FAC3A3E030A6E1,id)
        if type(ped)~="number" or ped<=0 then return nil end
        local dead=boolean(0x5F9532F3B5CC2551,ped,false)
        local visible=boolean(0x47D6F43D77935C75,ped)
        local interior=call("InvokeInt",0x2107BA504071A6BB,ped)
        local x,y,z=call("InvokeV3",0x3FEF770D40960D5A,ped,false)
        if type(x)=="table" or type(x)=="userdata" then x,y,z=x.x,x.y,x.z end
        local reserved=reservation(id)
        local fresh=deps.Players.GetById(id);fresh=fresh and fresh:GetGamerInfo()
        if not fresh or identity~=tostring(fresh.RockstarId)..":"..tostring(fresh.HostKey) then return nil end
        if dead==nil or visible==nil or interior==nil then return nil end
        -- Installed Cherax Documentation.json: PLAYING=0, HASDIED=1,
        -- RESPAWN=5. This is current replicated state, not future coordinates.
        local player_state
        pcall(function() player_state=player.PlayerInfo.PlayerState end)
        if type(player_state)~="number" or player_state%1~=0 or player_state<0 or player_state>6 then player_state=nil end
        return {identity=identity,name=deps.player_name(id),ped=ped,player_state=player_state,
            dead=dead,visible=visible,interior=interior,pos={x=x,y=y,z=z},reservation=reserved}
    end
    -- Only tokens issued by this adapter carry removal authority. A live
    -- numeric handle alone is not ownership: the game can recycle it.
    local owned={}
    local function finite(v)return type(v)=="number" and v==v and math.abs(v)<100000 end
    local function fingerprint(h)
        local kind=call("InvokeInt",0xBE9B0959FFD0779B,h)
        if type(kind)~="number" or kind%1~=0 then return nil end
        local x,y,z=call("InvokeV3",0x586AFE3FF72D996E,h)
        if type(x)=="table" or type(x)=="userdata" then x,y,z=x.x,x.y,x.z end
        if not (finite(x) and finite(y) and finite(z)) then return nil end
        return {kind=kind,x=x,y=y,z=z}
    end
    local function report_once(h,record,reason)
        if record and not record.reported then
            record.reported=true
            pcall(host.report,"marker="..tostring(h).." cleanup="..reason.."; deletion unconfirmed")
        end
    end
    local function matches(h,record)
        local birth=record and record.birth
        if not birth then return nil end
        local current=fingerprint(h)
        if not current then return nil end
        return current.kind==birth.kind and math.abs(current.x-birth.x)<0.25
            and math.abs(current.y-birth.y)<0.25 and math.abs(current.z-birth.z)<0.25
    end
    function host.remove(handles)
        local records=owned[handles]
        if not records then return true end
        -- REMOVE_BLIP takes Blip*, not the handle value.
        if not (M.Alloc and M.Free and M.WriteInt and N.InvokeVoid) then return false end
        local all=true
        for i=#handles,1,-1 do
            local h=handles[i];local exists=boolean(0xA6DB27D19ECBB7DA,h)
            if exists==false then table.remove(handles,i)
            elseif exists==true then
                local record=records[h]
                local same=record and matches(h,record)
                if same==false then
                    -- Lost/reused handle: relinquish it without touching its new owner.
                    report_once(h,record,"identity-changed")
                    table.remove(handles,i)
                elseif same==nil then all=false;report_once(h,record,"identity-unavailable")
                else
                    local ok,p=pcall(M.Alloc,8)
                    if ok and type(p)=="number" and p>0 then
                        pcall(function() M.WriteInt(p,h);N.InvokeVoid(0x86A652570E5F25DD,p) end)
                        pcall(M.Free,p)
                        if boolean(0xA6DB27D19ECBB7DA,h)==false then table.remove(handles,i)
                        else all=false;report_once(h,record,"removal-unconfirmed") end
                    else all=false end
                end
            else all=false end
        end
        if #handles==0 then owned[handles]=nil end
        return all and #handles==0
    end
    function host.marker(pos,radius,label,confirmed,incoming,reserved,candidate)
        if not (M.Alloc and M.Free and M.WriteInt and N.InvokeVoid and N.InvokeInt and N.InvokeBool) then return nil end
        if type(pos)~="table" or not (finite(pos.x) and finite(pos.y) and finite(pos.z))
            or not finite(radius) or radius<0 then return nil end
        local handles,records={},{}
        owned[handles]=records
        local function add(hash,...)
            local h=call("InvokeInt",hash,...)
            if type(h)=="number" and h%1==0 and h>0 and h<=0x7FFFFFFF then
                handles[#handles+1]=h
                -- Requested coordinates are not an observed identity. Capture
                -- native readback at birth, before any later cleanup/reuse.
                local record={};records[h]=record
                local birth=fingerprint(h)
                local expected_kind=hash==0x46818D79B1F7499A and 7 or 4
                if birth and birth.kind==expected_kind then record.birth=birth
                else report_once(h,record,"birth-unavailable") end
                return h
            end
        end
        local ok=pcall(function()
            local pin=assert(add(0x5A039BB0BCA604B6,pos.x+0.0,pos.y+0.0,pos.z+0.0))
            N.InvokeVoid(0x03D7FB09E75D6B7E,pin,confirmed and 2 or 3)
            N.InvokeVoid(0xD38744167B2FA257,pin,0.7)
            N.InvokeVoid(0xBE8BE4FE60E27B72,pin,false)
            N.InvokeVoid(0xF9113A30DE5C6670,"STRING")
            N.InvokeVoid(0x6C188BE134E074AA,label)
            N.InvokeVoid(0xBC38B49BCB83BC9B,pin)
        end)
        if not ok then host.remove(handles) end
        -- Retain partially-created handles for cleanup even if setup failed.
        if #handles==0 then owned[handles]=nil;return nil end
        return handles
    end
    return host
end

-- One blue reservation/received-position dot per player, then green only after
-- confirmed PLAYING and visible. Candidate lists are validation evidence only.
local function create_respawn_map(deps)
    local api,players,marks={},{},{}
    local next_tick,next_pending,last_time=0,0,0
    local function finite(v)return type(v)=="number" and v==v and math.abs(v)<100000 end
    local function position(p)return type(p)=="table" and finite(p.x) and finite(p.y) and finite(p.z)
        and (math.abs(p.x)+math.abs(p.y)+math.abs(p.z)>0.01) end
    local function copy(p)return {x=p.x,y=p.y,z=p.z}end
    local function distance(a,b)return math.sqrt((a.x-b.x)^2+(a.y-b.y)^2+(a.z-b.z)^2)end
    local function remove(id)
        local m=marks[id];if not m then return true end
        if m.handles then
            for i=#m.handles,1,-1 do
                local ok,v=pcall(deps.remove,m.handles[i])
                if ok and v==true then table.remove(m.handles,i)end
            end
            if #m.handles==0 then marks[id]=nil;return true end
        else
            local ok,v=pcall(deps.remove,m.handle)
            if ok and v==true then marks[id]=nil;return true end
        end
        m.expires=0;return false
    end
    -- Keep only the latest request per observed death. Never render from the
    -- event callback, and never let duplicate traffic refresh the expiry.
    function api.Candidate(id,identity,request,now)
        if type(now)~="number" or now~=now or math.abs(now)==math.huge then return false end
        if not deps.enabled() then return false end
        local state=players[id]
        if not state or state.identity~=identity or not state.death or state.dead~=true
            or now<state.death_time or now-state.death_time>20000 then return false end
        if type(request)~="table" or type(request.points)~="table" or #request.points<1 or #request.points>5
            or math.type(request.checksum)~="integer" then return false end
        local points,signature={},{tostring(request.checksum)}
        for _,p in ipairs(request.points)do
            if not position(p) or distance(state.death,p)>2000 then return false end
            points[#points+1]=copy(p);signature[#signature+1]=('%s,%s,%s'):format(p.x,p.y,p.z)
        end
        signature=table.concat(signature,';')
        if state.request_signature==signature then return false end
        state.request_signature=signature
        state.pending_request={points=points,time=now,expires=now+5000,signature=signature}
        next_pending=0
        return true
    end
    local function closest(request,pos)
        local best
        for _,p in ipairs(request.points)do local d=distance(p,pos);if not best or d<best then best=d end end
        return best
    end
    function api.Reset()
        for id in pairs(marks)do remove(id)end
        players={};next_tick=0;next_pending=0
        if type(deps.reset)=="function" then pcall(deps.reset)end
    end
    function api.HasCleanup()return next(marks)~=nil end
    function api.HasPending()
        for _,p in pairs(players)do if p.death then return true end end
        return false
    end
    local function show(id,row,pos,radius,confirmed,now,incoming,reserved)
        if not remove(id) then return false end
        local count=0;for _ in pairs(marks)do count=count+1 end
        if count>=8 then return false end
        local name=tostring(row.name or id):gsub('[~%c]',''):sub(1,32)
        local label=(confirmed and 'Observed respawn: ' or reserved and 'Reserved respawn: ' or incoming and 'Received respawn location: ' or 'Estimated respawn: ')..name
        local ok,h=pcall(deps.marker,pos,radius,label,confirmed,incoming,reserved)
        if ok and h then
            marks[id]={handle=h,expires=now+(confirmed and 6000 or 20000),estimated=not confirmed and not incoming and not reserved,incoming=incoming,reserved=reserved,pos=copy(pos)}
            return true
        end
        return false
    end
    function api.Tick(now,pending_only)
        if type(now)~="number" or now~=now or math.abs(now)==math.huge then return end
        if now<last_time then api.Reset()end;last_time=now
        if pending_only then
            if now<next_pending then return end;next_pending=now+100
        else
            if now<next_tick then return end;next_tick=now+250
        end
        if not deps.enabled() or not deps.online() then api.Reset();next_tick=now+250;return end
        if type(deps.prepare)=="function" then pcall(deps.prepare,now)end
        for id,m in pairs(marks)do if now>=m.expires then remove(id)end end
        for id=0,31 do
            if not pending_only or (players[id] and players[id].death) then
            local ok,row=pcall(deps.sample,id)
            local old=players[id]
            if not ok or not row or not position(row.pos) or row.interior~=0 or type(row.dead)~="boolean" then
                remove(id);players[id]=nil
            else
                if old and old.identity~=row.identity then remove(id);old=nil end
                local state=old or {identity=row.identity}
                players[id]=state
                state.dead=row.dead
                local r=row.reservation
                local seq=r and type(r.seq)=="number" and r.seq%1==0 and r.seq or nil
                local fresh=seq~=nil and state.reservation_seq~=nil and seq~=state.reservation_seq
                local valid_reservation=r and r.active==true and position(r.pos)
                if row.dead then
                    if not state.death then
                        remove(id);state.death=copy(row.pos);state.death_time=now;state.notified=false;state.incoming=nil;state.incoming_at=nil;state.reserved=nil;state.reservation_reported=false
                        state.request,state.pending_request,state.request_signature=nil,nil,nil
                    end
                    if state.pending_request then
                        state.request=state.pending_request;state.pending_request=nil
                    end
                    local request=state.request
                    -- Retain the latest request as a contradiction fence for this
                    -- death even after its visible candidate pins expire.
                    if state.reserved and request and closest(request,state.reserved.pos)>1 then
                        state.reserved=nil
                    end
                    local elapsed=now-state.death_time
                    if valid_reservation and fresh and (not request or closest(request,r.pos)<=1)
                        and elapsed>=0 and elapsed<=20000
                        and distance(state.death,r.pos)<=2000 then
                        state.reserved={seq=seq,pos=copy(r.pos),time=now}
                    end
                    local reserved=state.reserved
                    if reserved and (not valid_reservation or seq~=reserved.seq or now-reserved.time>=20000) then
                        state.reserved=nil;reserved=nil
                    end
                    if reserved then
                        local mark=marks[id]
                        if not mark or not mark.reserved or distance(mark.pos,reserved.pos)>0.01 then
                            show(id,row,reserved.pos,0,false,now,false,true)
                        end
                        if marks[id] and marks[id].reserved and not state.notified and type(deps.notify)=="function" then
                            state.notified=true
                            local name=tostring(row.name or id):gsub('[~%c]',''):sub(1,32)
                            pcall(deps.notify,"Reserved respawn: "..name.." — blue map marker")
                        end
                    elseif marks[id] and (marks[id].reserved or marks[id].candidate) then remove(id)end
                elseif state.death then
                    -- Measure to first living observation, not visibility after fade-in.
                    if not state.reservation_reported then
                        state.reservation_reported=true
                        local request=state.pending_request or state.request
                        if request and now>=request.time and now-request.time<=20000 and type(deps.report)=="function" then
                            pcall(deps.report,("slot=%d candidate_to_first_alive_ms=%d candidate_count=%d nearest_candidate_error_m=%.3f")
                                :format(id,now-request.time,#request.points,closest(request,row.pos)))
                        end
                        -- An event can be queued after the last dead poll and
                        -- before this living sample: suppress contradicted logs too.
                        if state.reserved and request and closest(request,state.reserved.pos)>1 then
                            state.reserved=nil
                            if marks[id] and marks[id].reserved then remove(id) end
                        end
                        state.request,state.pending_request=nil,nil
                        local c=state.reserved
                        if c and valid_reservation and seq==c.seq and now-c.time<20000 and type(deps.report)=="function" then
                            local dx,dy=row.pos.x-c.pos.x,row.pos.y-c.pos.y
                            pcall(deps.report,("slot=%d reservation_to_first_alive_ms=%d horizontal_error_m=%.3f vertical_error_m=%.3f")
                                :format(id,now-c.time,math.sqrt(dx*dx+dy*dy),row.pos.z-c.pos.z))
                        end
                        state.reserved=nil
                        -- First alive can precede fade-in/PLAYING. Keep the blue
                        -- reservation until green replaces it or its expiry.
                        if marks[id] and marks[id].candidate then remove(id)end
                    end
                    local elapsed=now-state.death_time
                    local delta=distance(state.death,row.pos)
                    local valid=elapsed>=0 and elapsed<=30000 and delta>=20 and delta<=2000
                    -- Invisibility also means streaming, spectator/stealth or a
                    -- hidden PLAYING ped. Only replicated RESPAWN is evidence
                    -- for a blue received-position marker.
                    local pending=row.player_state==5
                    if valid and pending then
                        if not state.incoming or distance(state.incoming,row.pos)>10 or not marks[id] or not marks[id].incoming then
                            show(id,row,copy(row.pos),0,false,now,true)
                            state.incoming=copy(row.pos)
                            state.incoming_at=state.incoming_at or now
                        end
                        if marks[id] and marks[id].incoming and not state.notified and type(deps.notify)=="function" then
                            state.notified=true
                            local name=tostring(row.name or id):gsub('[~%c]',''):sub(1,32)
                            pcall(deps.notify,"Received respawn location: "..name.." — blue map marker")
                        end
                    elseif row.visible==true and row.player_state==0 then
                        local finished=not valid
                        if valid then
                            finished=show(id,row,copy(row.pos),0,true,now)
                            if finished and type(deps.report)=="function" then
                                pcall(deps.report,"slot="..id.." received_position="..tostring(state.incoming_at~=nil)
                                    .." received_to_visible_ms="..tostring(state.incoming_at and now-state.incoming_at or 0))
                            end
                        else remove(id)end
                        -- Failed replacement keeps its transition for a retry;
                        -- the existing 30-second validity bound still applies.
                        if finished then state.death,state.death_time,state.incoming,state.incoming_at=nil,nil,nil,nil end
                    elseif elapsed>30000 then
                        remove(id);state.death,state.death_time,state.incoming=nil,nil,nil
                    end
                end
                state.reservation_seq=seq
            end
            end
        end
    end
    function api.Snapshot()
        local estimates,observed,incoming,reserved,candidates=0,0,0,0,0
        for _,m in pairs(marks)do
            if m.candidate then candidates=candidates+#m.handles elseif m.reserved then reserved=reserved+1 elseif m.incoming then incoming=incoming+1 elseif m.estimated then estimates=estimates+1 else observed=observed+1 end
        end
        return {samples=0,estimated=estimates,observed=observed,incoming=incoming,reserved=reserved,candidates=candidates,
            detail=('Respawn map: %d blue pending, %d green respawned. Blue = reservation or received position (can change); green = visible and PLAYING.'):format(reserved+incoming,observed)}
    end
    return api
end

-- Session Railgun filter: targeted requests are identity-fenced and bounded.
-- Remote readback is a controlled client observation, not proof that
-- another player's authoritative inventory has changed.
local function create_session_railgun_filter(deps)
    local api,state,generation={},{},0
    local N={online=0x9DE624D2FC4B603F,transition=0x68049AEFF83D8F0A,ped=0x50FAC3A3E030A6E1,
        has=0x8DECB02F88F428BC,remove=0x4899CB088EDF59B8}
    local hashes
    local function bool(hash,...)
        if type(deps.invoke_bool_detail)~="function" then return nil end
        local ok,_,raw,err=pcall(deps.invoke_bool_detail,hash,...)
        if not ok or err then return nil end
        if raw==true or raw==1 then return true end
        if raw==false or raw==0 then return false end
    end
    local function write(hash,...)
        if type(deps.invoke_void_detail)~="function" then return false end
        local ok,accepted,raw,err=pcall(deps.invoke_void_detail,hash,...)
        return ok and accepted==true and raw~=false and err==nil
    end
    local function integer(value,minimum)
        return type(value)=="number" and value==value and value%1==0 and value>=(minimum or 0) and math.abs(value)<math.huge
    end
    local function identity(id)
        local ok,result=pcall(function()
            if not deps.player_available(id) then return nil end
            local player=deps.Players and deps.Players.GetById(id)
            local info=player and player:GetGamerInfo()
            if not info or not integer(info.RockstarId,1) or (not integer(info.HostKey,math.mininteger) or info.HostKey==0) then return nil end
            local ped=deps.invoke_int(N.ped,id)
            if not integer(ped,1) or ped>=0xFFFFFFFF then return nil end
            local pointer=deps.GTA.HandleToPointer(ped)
            local address=pointer and pointer:GetAddress()
            if not integer(address,0x10000) or address>0x7FFFFFFFFFFF or deps.GTA.PointerToHandle(pointer)~=ped then return nil end
            return {id=id,ped=ped,address=address,rid=info.RockstarId,key=info.HostKey}
        end)
        return ok and result or nil
    end
    local function same(a,b)
        return a and b and a.id==b.id and a.ped==b.ped and a.address==b.address and a.rid==b.rid and a.key==b.key
    end
    function api.Reset()
        generation=generation+1
        state={cursor=0,next_scan=0,targets={},local_removed=0,remote_submitted=0,remote_observed=0,
            status="OFF",detail="Disabled",cycle={found=0,blocked=0,unknown=0},scanned=0}
    end
    api.Reset()
    function api.Tick(now)
        if not deps.enabled() then state.status,state.detail="OFF","Disabled";return end
        now=tonumber(now)
        if not now or now~=now or math.abs(now)==math.huge then return end
        if now<state.next_scan then return end
        state.next_scan=now+250
        if bool(N.online)~=true or bool(N.transition)~=false then
            state.targets={};state.status,state.detail="WAITING","Waiting for an active session";return
        end
        if not hashes then
            local ok,a,b=pcall(function()return deps.Utils.Joaat("weapon_railgun"),deps.Utils.Joaat("weapon_railgunxm3")end)
            if not ok or not integer(a,-0x80000000) or not integer(b,-0x80000000) or a==0 or b==0 or a==b then
                state.status,state.detail="UNAVAILABLE","Railgun identifiers unavailable";return
            end
            hashes={a & 0xFFFFFFFF,b & 0xFFFFFFFF}
        end
        local token,local_id=generation,deps.local_player_id()
        local function current()return token==generation and deps.enabled() and deps.local_player_id()==local_id end
        for _=1,4 do
            if not current() then return end
            local id=state.cursor;state.cursor=(id+1)%32;state.scanned=state.scanned+1
            local target=identity(id)
            if target then
                local local_target=id==local_id
                local present,unknown={},false
                for _,hash in ipairs(hashes) do
                    local has=bool(N.has,target.ped,hash,false)
                    -- Remote replicas do not expose the recipient's complete
                    -- inventory. Submit just these two targeted removals even
                    -- when the railgun is holstered or absent in our replica.
                    if has or not local_target then present[#present+1]=hash end
                    if has==nil then unknown=true end
                end
                if unknown then state.cycle.unknown=state.cycle.unknown+1 end
                if #present>0 then
                    state.cycle.found=state.cycle.found+#present
                    local entry=state.targets[id]
                    if not entry or not same(entry.identity,target) then
                        entry={identity=target,next_remove={}};state.targets[id]=entry
                    end
                    for _,hash in ipairs(present) do
                        if not current() then return end
                        if now>=(entry.next_remove[hash] or 0) then
                            -- Re-resolve both the connection and ped immediately
                            -- before dispatch. This native has a targeted
                            -- CRemoveWeaponEvent route; requesting ownership of
                            -- another player's ped would incorrectly block it.
                            if not same(target,identity(id)) then break end
                            if not current() then return end
                            entry.next_remove[hash]=now+2000
                            local accepted=write(N.remove,target.ped,hash)
                            if accepted and not local_target then state.remote_submitted=state.remote_submitted+1 end
                            if not current() then return end
                            local verified=accepted and same(target,identity(id)) and bool(N.has,target.ped,hash,false)==false
                            if verified then
                                local key=local_target and "local_removed" or "remote_observed"
                                state[key]=state[key]+1
                            elseif not accepted or local_target then state.cycle.blocked=state.cycle.blocked+1 end
                        end
                    end
                else state.targets[id]=nil end
            else state.targets[id]=nil end
            if state.cursor==0 then
                local cycle=state.cycle
                if cycle.blocked>0 then state.status,state.detail="BLOCKED","A targeted removal could not be submitted or locally verified"
                elseif cycle.unknown>0 then state.status,state.detail="WAITING","Some weapon observations unavailable"
                elseif cycle.found==0 then state.status,state.detail="IDLE","No railguns observed on readable session peds"
                else state.status,state.detail="ACTIVE","Targeted railgun requests submitted; recipient inventories remain unverified" end
                state.cycle={found=0,blocked=0,unknown=0}
            elseif state.status=="OFF" then state.status,state.detail="SCANNING","Checking available session peds" end
        end
    end
    function api.Snapshot()
        return {status=state.status,detail=state.detail,local_removed=state.local_removed,
            remote_submitted=state.remote_submitted,remote_observed=state.remote_observed,
            remote_observation_scope="local_replica",scanned=state.scanned,authoritative_verified=false}
    end
    return api
end

-- BEGIN FORCE SCRIPTHOST45
local function create_force_scripthost45(deps)
    local api,generation={},0
    local state,canceled=nil,false
    local N={online=0x9DE624D2FC4B603F,transition=0x68049AEFF83D8F0A,
        local_id=0x4F8644AF03D0E0D6,active=0xB8DFD30D6973E135,
        host=0x1D6A14F1F9A736FC,threads=0x2C83A9DA6BFFC4F9}
    local function integer(value,low,high)
        return type(value)=="number" and value==value and value%1==0
            and value>=low and value<=high
    end
    local function read(kind,hash,...)
        local fn=deps["invoke_"..kind.."_detail"]
        if type(fn)~="function" then return nil end
        local ok,_,raw,err=pcall(fn,hash,...)
        if not ok or err~=nil then return nil end
        if kind=="bool" then
            if raw==true or raw==1 then return true end
            if raw==false or raw==0 then return false end
        elseif integer(raw,-0x80000000,0xFFFFFFFF) then return raw end
    end
    local function status(phase,detail)
        state.phase,state.detail=phase,detail
    end
    function api.Reset()
        generation=generation+1
        state={phase="OFF",detail="Disabled",requests=0,next_request=0,
            observed_host=-1,local_host=false,requested=false}
    end
    function api.Cancel()
        canceled=true;api.Reset()
    end
    function api.Rearm()
        canceled=false;api.Reset()
    end
    function api.IsCanceled()return canceled end
    api.Reset()
    function api.Snapshot()
        local copy={};for k,v in pairs(state)do copy[k]=v end;return copy
    end
    function api.Tick(now)
        if canceled then return end
        if deps.enabled()~=true then
            if state.requested then api.Reset() end
            return
        end
        if not integer(now,0,0x1FFFFFFFFFFFFF)then return end
        local token=generation
        local stamp=deps.session_stamp()
        local function current()
            return generation==token and deps.enabled()==true and deps.session_stamp()==stamp
                and generation==token
        end
        if state.last_tick and now<state.last_tick then state.next_request=0 end
        state.last_tick=now;state.requested=true;state.local_host=false
        if stamp==nil or read("bool",N.online)~=true or read("bool",N.transition)~=false then
            state.local_host=false;state.observed_host=-1
            status("WAITING","Waiting for an active Freemode session.")
            return
        end
        if not current()then return end
        local pid=read("int",N.local_id)
        if not integer(pid,0,31) or read("bool",N.active,pid)~=true then
            state.local_host=false;status("WAITING","Waiting for your player to become active.");return
        end
        if not current()then return end
        local function local_current()
            return current() and read("int",N.local_id)==pid and read("bool",N.active,pid)==true
                and read("bool",N.online)==true and read("bool",N.transition)==false and current()
        end
        local ok_hash,hash=pcall(deps.Utils.Joaat,"freemode")
        if not ok_hash or not integer(hash,-0x80000000,0xFFFFFFFF)or hash==0 then
            status("UNAVAILABLE","Freemode could not be identified.");return
        end
        local threads=read("int",N.threads,hash)
        if not threads or threads<1 then
            state.local_host=false;status("WAITING","Waiting for Freemode to start.");return
        end
        local host=read("int",N.host,"freemode",-1,0)
        if not current()then return end
        state.observed_host=integer(host,0,31)and host or -1
        state.local_host=host==pid
        if state.local_host then
            if not local_current()then
                state.local_host=false;status("WAITING","Player or session changed; checking again.");return
            end
            state.next_request=0
            status("HELD","You are Freemode script host.")
            return
        end
        if not integer(host,0,31)then
            status("WAITING","Script host is migrating; waiting for its identity.");return
        end
        if type(deps.GTA.ForceScriptHost)~="function"then
            status("UNAVAILABLE","Script-host acquisition is unavailable.");return
        end
        if state.session~=stamp or state.player_id~=pid then
            state.session,state.player_id,state.next_request=stamp,pid,0
        end
        status("RECLAIMING","Reclaiming Freemode script host...")
        if now<state.next_request then return end
        -- Observe each gameplay frame; coalesce unsuccessful requests so
        -- competing migrations cannot produce an unbounded request loop.
        -- The first loss after an observed HELD state is handled next frame.
        if not local_current()then return end
        state.next_request=now+250
        state.requests=state.requests+1;state.last_request=now
        local called,result=pcall(deps.GTA.ForceScriptHost,hash)
        if not current()then return end
        if not called or result==false then
            status("RETRYING","Script-host request was not accepted; retrying.")
            return
        end
        -- A void host call returning normally is a request, not confirmation.
        local observed=read("int",N.host,"freemode",-1,0)
        if not current()then return end
        state.observed_host=integer(observed,0,31)and observed or -1
        state.local_host=observed==pid
        if state.local_host then
            if not local_current()then
                state.local_host=false;status("WAITING","Player or session changed; checking again.");return
            end
            state.next_request=0
            status("HELD","You are Freemode script host.")
        end
    end
    return api
end
-- END FORCE SCRIPTHOST45

local function create_session_system(deps)
    local log_info = require_binding("log_info", deps.log_info)
    local log_warn = require_binding("log_warn", deps.log_warn)
    local log_error_once = require_binding("log_error_once", deps.log_error_once)
    local toast = require_binding("toast", deps.toast)
    local invoke_void = require_binding("invoke_void", deps.invoke_void)
    local invoke_int = require_binding("invoke_int", deps.invoke_int)
    local invoke_bool = require_binding("invoke_bool", deps.invoke_bool)
    local now_ms = require_binding("now_ms", deps.now_ms)
    local local_player_id = require_binding("local_player_id", deps.local_player_id)
    local player_available = require_binding("player_available", deps.player_available)
    local player_name = require_binding("player_name", deps.player_name)
    local player_snapshot = require_binding("player_snapshot", deps.player_snapshot)
    local player_flags = require_binding("player_flags", deps.player_flags)
    local feature_id = require_binding("feature_id", deps.feature_id)
    local feature_mgr = require_binding("FeatureMgr", deps.FeatureMgr)
    local feature_type = require_binding("eFeatureType", deps.eFeatureType)
    local utils = require_binding("Utils", deps.Utils)
    local gta = require_binding("GTA", deps.GTA)
    local H = require_binding("H", deps.H)
    local players = deps.Players
    local script_global = deps.ScriptGlobal
    local gamer_handle = deps.GamerHandle
    local maintain_disabled_phone_calls
    local phone_gate_owner
    local restore_phone_suppression
    local phone_text = create_phone_text_input(function() return module_context end)
    local phone_text_last_status = "OFF"
local phone_text_last_warned
    local local_nat = create_engine_nat({
        memory = function()
            local host = module_context and module_context.Cherax
            return host and host.Get and host.Get("Memory")
        end,
        script = function()
            local host = module_context and module_context.Cherax
            return host and host.Get and host.Get("Script")
        end,
        now_ms = now_ms,
        write_allowed = function()
            local runtime = module_context and module_context.CScript and module_context.CScript.Runtime
            return runtime ~= nil and type(runtime.RuntimeWriteAllowed) == "function"
                and runtime.RuntimeWriteAllowed("Other") == true
        end,
    })

    local function feature_ref(key)
        if F[key] then return F[key] end
        if type(feature_mgr.GetFeature) == "function" then
            local ok, feature = pcall(feature_mgr.GetFeature, feature_id(key))
            local access = module_context and module_context.CScript and module_context.CScript.ForeignFeatures
            if ok and feature and access and access.Supports(feature, "toggle") then return feature end
        end
        return nil
    end

    local function is_on(key)
        local feature =
            feature_ref(key)

        if feature
            and type(feature.IsToggled) == "function" then
            local ok, enabled =
                pcall(
                    feature.IsToggled,
                    feature
                )

            if ok then
                if F[key] then
                    ToggleState[key] =
                        enabled == true
                end

                return enabled == true
            end
        end

        return F[key] ~= nil
            and ToggleState[key] == true
    end

    local railgun_filter=create_session_railgun_filter(setmetatable({
        enabled=function()return started and is_on("session_disable_railgun")end,
    },{__index=deps}))

    local force_scripthost=create_force_scripthost45(setmetatable({
        enabled=function()return started and is_on("session_force_scripthost")end,
        session_stamp=function()return State.session_started_ms end,
    },{__index=deps}))

    local respawn_host=create_respawn_host(deps)
    respawn_host.enabled=function()return started and is_on("session_respawn_prediction")end
    local respawn_map=create_respawn_map(respawn_host)

    local orbital=assert(module_context.Modules.OrbitalCannon,"Orbital module unavailable").New(setmetatable({
        time_ms=now_ms,
        session_key=function()return ReadSessionIdentity(module_context.Raw.Memory,true)end,
    },{__index=module_context.Raw}))

    local function add_toggle(key, name, description, default, callback)
        if F[key] then
            return F[key]
        end

        ToggleState[key] =
            default == true

        local function on_toggle(feature)
            local ok, enabled =
                pcall(
                    feature.IsToggled,
                    feature
                )

            if ok then
                ToggleState[key] =
                    enabled == true
            end

            if type(callback) == "function" then
                local callback_ok, callback_error = pcall(callback, feature, ToggleState[key])
                if not callback_ok then log_error_once("session_toggle_" .. tostring(key), callback_error) end
            end
        end

        local feature =
            feature_mgr.AddFeature(
                feature_id(key),
                name,
                feature_type.Toggle,
                description or "",
                on_toggle
            )

        if feature
            and type(feature.SetDefaultValue) == "function" then
            pcall(function()
                feature:SetDefaultValue(
                    default == true
                )

                if default == true
                    and type(feature.Toggle) == "function"
                    and not feature:IsToggled() then
                    feature:Toggle(true)
                end
            end)
        end

        F[key] = feature

        if feature then
            local ok, enabled =
                pcall(
                    feature.IsToggled,
                    feature
                )

            if ok then
                ToggleState[key] =
                    enabled == true
            end

            State.registered_count =
                State.registered_count + 1
        end

        return feature
    end

    local function list_index(key, default)
        local feature = feature_ref(key)
        if feature then
            local ok, value = pcall(function() return feature:GetListIndex() end)
            value = ok and tonumber(value) or nil
            if value then return math.floor(value) end
        end
        return math.floor(tonumber(default) or 0)
    end

    local function add_combo(key, name, description, values, default, callback)
        if F[key] then return F[key] end
        local function on_change(feature)
            if type(callback) == "function" then
                local callback_ok, callback_error = pcall(callback, feature)
                if not callback_ok then log_error_once("session_combo_" .. tostring(key), callback_error) end
            end
        end
        local feature = feature_mgr.AddFeature(
            feature_id(key), name, feature_type.Combo, description or "", on_change)
        if feature then
            local ok, err = pcall(function()
                feature:SetList(values):SetListIndex(default or 0)
            end)
            if not ok then
                log_error_once("session_combo_setup_" .. tostring(key), err)
                return nil
            end
            F[key] = feature
            State.registered_count = State.registered_count + 1
        end
        return feature
    end

    local function normalize_option(value)
        return tostring(value or ""):lower():gsub("[^%w]", "")
    end

    local function foreign_list_entries(list)
        local entries,seen = {},{}
        if list==nil then return entries end
        local function push(key,value)
            if type(value)~="string" or value=="" then return end
            local k=tonumber(key)
            local sig=tostring(k).."\0"..value
            if seen[sig] then return end
            seen[sig]=true;entries[#entries+1]={key=k,label=value}
        end
        -- Cherax v5.49 may return a userdata proxy for table<int,string>.
        local ok=pcall(function() for key,value in pairs(list) do push(key,value) end end)
        if #entries==0 then
            local ok_len,len=pcall(function() return #list end)
            len=ok_len and tonumber(len) or 0
            if len and len>0 and len<=64 then
                for i=0,len do local q,v=pcall(function() return list[i] end);if q then push(i,v) end end
                for i=1,len do local q,v=pcall(function() return list[i] end);if q then push(i,v) end end
            else
                -- Bounded proxy probing covers zero/one based userdata without trusting __len.
                for i=0,63 do local q,v=pcall(function() return list[i] end);if q then push(i,v) end end
            end
        end
        table.sort(entries,function(a,b)
            if a.key~=nil and b.key~=nil then return a.key<b.key end
            if a.key~=nil then return true end;if b.key~=nil then return false end;return a.label<b.label
        end)
        local zero_based=entries[1] and entries[1].key==0
        for position,entry in ipairs(entries) do
            entry.index=entry.key~=nil and math.floor(entry.key-(zero_based and 0 or 1)) or position-1
        end
        return entries
    end

    local function foreign_option_index(list, wanted, aliases)
        local candidates = aliases and aliases[wanted] or nil
        if type(candidates) ~= "table" then candidates = { normalize_option(wanted) } end
        local wanted_set = {}
        for _, candidate in ipairs(candidates) do wanted_set[normalize_option(candidate)] = true end
        local found
        for _, entry in ipairs(foreign_list_entries(list)) do
            if wanted_set[normalize_option(entry.label)] then
                if found then return nil end -- Ambiguous alias: never guess one.
                found = entry
            end
        end
        if found then return found.index, found.label end
        return nil
    end

    local function spoof_status(kind, status, detail)
        local spoofing = State.spoofing
        spoofing.status[kind] = { state = tostring(status), detail = tostring(detail or "") }
        local signature = tostring(status) .. "\0" .. tostring(detail or "")
        if spoofing.last_log[kind] == signature then return end
        spoofing.last_log[kind] = signature
        log_info(("%s spoof backend: %s%s"):format(
            SPOOF_BACKENDS[kind].label, tostring(status),
            detail and (" (" .. tostring(detail) .. ")") or ""))
    end


    local foreign_method_capabilities = {
        GetName = "metadata", GetHash = "metadata", GetDesc = "metadata",
        GetList = "list", GetListIndex = "list", SetListIndex = "list",
        IsToggled = "toggle", Toggle = "toggle", TriggerCallback = "metadata",
    }

    local function foreign_call(feature, method, ...)
        local access = module_context and module_context.CScript and module_context.CScript.ForeignFeatures
        local capability = foreign_method_capabilities[method]
        if not access or not feature or not capability then error("Typed Feature access unavailable", 0) end
        -- Recheck immediately before EACH host operation. A successful earlier
        -- read is not a lease on a foreign Feature across callbacks/reloads.
        local allowed, reason
        if capability == "metadata" then
            allowed, reason = access.Describe(feature)
        else
            allowed, reason = access.Supports(feature, capability)
        end
        if not allowed then error(reason or "Foreign feature type is unavailable", 0) end
        if type(feature[method]) ~= "function" then error("Foreign feature method unavailable: " .. method, 0) end
        return feature[method](feature, ...)
    end

    local function foreign_feature_name(feature)
        if not feature then return "" end
        local ok, value = pcall(foreign_call, feature, "GetName", false)
        return ok and tostring(value or "") or ""
    end

    local function foreign_feature_hash(feature, fallback)
        if not feature then return tonumber(fallback) end
        local ok, value = pcall(foreign_call, feature, "GetHash")
        value = ok and tonumber(value) or tonumber(fallback)
        if type(value) ~= "number" or value ~= value or value % 1 ~= 0 then return nil end
        return value
    end


    local function foreign_supports(feature, capability)
        local access = module_context and module_context.CScript and module_context.CScript.ForeignFeatures
        if not access or type(access.Supports) ~= "function" then return false, "Typed Feature access unavailable" end
        return access.Supports(feature, capability)
    end


    local function feature_list_info(feature, backend)
        local legal, reason = foreign_supports(feature, "list")
        if not legal then return nil, false, reason end
        for _, method in ipairs({ "GetList", "GetListIndex", "SetListIndex" }) do
            local ok, value = pcall(function() return feature[method] end)
            if not ok or type(value) ~= "function" then
                return nil, false, method .. " method unavailable (" .. (ok and type(value) or "member lookup failed") .. ")"
            end
        end
        local ok, list = pcall(foreign_call, feature, "GetList")
        if not ok then return nil, false, "GetList invocation failed" end
        local entries=foreign_list_entries(list)
        if backend.mode=="search-selector" then
            if #entries==0 then return list,false,"GetList returned an empty/unsupported label proxy ("..type(list)..")" end
            if #entries>64 then return list,false,"GetList exceeds the bounded region catalog" end
            local seen={}
            for _,entry in ipairs(entries) do
                if type(entry.index)~="number" or entry.index<0 or seen[entry.index] then
                    return list,false,"GetList has ambiguous indices"
                end
                seen[entry.index]=true
            end
        end
        local required = backend.required or (backend.selector and backend.selector.required) or {}
        for _, label in ipairs(required) do
            if foreign_option_index(list, label, backend.aliases) == nil then return list, false, "missing option: " .. label end
        end
        local index_ok, index = pcall(foreign_call, feature, "GetListIndex")
        if not index_ok or type(index) ~= "number" or index ~= index or index % 1 ~= 0 then
            return list, false, "GetListIndex read-back is unavailable or non-integral"
        end
        return list, true
    end

    local function is_own_spoof_feature(feature, hash)
        for _, key in ipairs({
            "network_nat_type", "network_spoof_nat",
            "network_region", "network_spoof_region",
        }) do
            if F[key] ~= nil and F[key] == feature then return true end
            local own_hash = feature_id(key)
            if type(hash) == "number" and ((hash & 0xFFFFFFFF) == (own_hash & 0xFFFFFFFF)) then
                return true
            end
        end
        return false
    end







    local function resolve_foreign_feature(spec, role)
        if type(feature_mgr.GetFeature) ~= "function" then
            return nil, "FeatureMgr.GetFeature is unavailable"
        end
        local ok, feature = pcall(feature_mgr.GetFeature, spec.id)
        if not ok or not feature then return nil, "exact " .. tostring(role) .. " feature was not found" end
        local legal, reason = foreign_supports(feature, role == "toggle" and "toggle" or "list")
        if not legal then return nil, reason end
        if spec.name then
            local name = foreign_feature_name(feature)
            if name ~= tostring(spec.name) then
                return nil, "exact " .. tostring(role) .. " name validation failed"
            end
        end
        return feature
    end





    local function read_foreign_index(feature)
        local legal, reason = foreign_supports(feature, "list")
        if not legal then return nil, reason end
        local ok, value = pcall(foreign_call, feature, "GetListIndex")
        if not ok or type(value) ~= "number" or value ~= value or value % 1 ~= 0 or value < 0 then
            return nil, "selector read-back failed or returned an invalid index"
        end
        return value
    end

    local function write_foreign_index(feature, wanted, still_current)
        wanted = math.floor(tonumber(wanted) or -1)
        local current, read_error = read_foreign_index(feature)
        if current == nil then return false, read_error end
        if still_current and not still_current() then return false, "selector action cancelled before write" end
        if current ~= wanted then
            local ok, err = pcall(foreign_call, feature, "SetListIndex", wanted)
            if not ok then return false, "selector write failed: " .. tostring(err) end
        end
        local observed, verify_error = read_foreign_index(feature)
        if observed == nil then return false, verify_error end
        if observed ~= wanted then
            return false, ("selector read-back mismatch (wanted=%d observed=%s)")
                :format(wanted, tostring(observed))
        end
        return true
    end


    local function clear_spoof_owner(owner)
        owner.captured = false
        owner.snapshot_index = nil
        owner.last_index_applied = nil
        owner.snapshot_toggle = nil
        owner.last_toggle_applied = nil
        owner.active = false
        owner.selector = nil
        owner.toggle = nil
        owner.list_signature = nil
        owner.restoring = nil
    end

    local function resolve_region_selector()
        local spec = SPOOF_BACKENDS.region.selector
        local selector, err = resolve_foreign_feature(spec, "search-region selector")
        if not selector then return nil, nil, nil, err end
        local hash = math.tointeger(foreign_feature_hash(selector, spec.id))
        if hash == nil or (hash & 0xFFFFFFFF) ~= spec.id
            or is_own_spoof_feature(selector, spec.id) then
            return nil, nil, nil, "search-region identity mismatch"
        end
        local list, valid, list_error = feature_list_info(selector, SPOOF_BACKENDS.region)
        if not valid then
            return nil, nil, nil, "search-region list: " .. tostring(list_error)
        end
        local callback_ok, callback = pcall(function() return selector.TriggerCallback end)
        if not callback_ok or type(callback) ~= "function" then
            return nil, nil, nil, "search-region callback: TriggerCallback unavailable"
        end
        local rows = {}
        for _, entry in ipairs(foreign_list_entries(list)) do
            rows[#rows + 1] = tostring(entry.index) .. ":" .. entry.label
        end
        if #rows == 0 then return nil, nil, nil, "search-region list is empty" end
        return selector, list, table.concat(rows, "\0")
    end

    local function write_region_index(selector, wanted, current)
        if current and not current() then return false, "search-region action cancelled" end
        local selected, err = write_foreign_index(selector, wanted, current)
        if not selected then return false, err end
        if current and not current() then return false, "search-region action cancelled" end
        -- Setting a Feature's value alone does not dispatch its GUI callback.
        local ok, result = pcall(foreign_call, selector, "TriggerCallback")
        if not ok or result == false then return false, "search-region callback failed" end
        if current and not current() then return false, "search-region action cancelled" end
        local observed, read_error = read_foreign_index(selector)
        if observed ~= wanted then return false, read_error or "search-region callback read-back mismatch" end
        if current and not current() then return false, "search-region action cancelled" end
        return true
    end

    local function restore_region_owner()
        local owner = State.spoofing.region
        if not owner.captured then owner.active = false; return true end
        if owner.restoring then return false, "search-region restoration already in progress" end
        owner.restoring, owner.active = true, false
        local generation, spoofing = spoof_generation, State.spoofing
        local function finish(ok, detail) owner.restoring = nil; return ok, detail end
        local function generation_current()
            return generation == spoof_generation and State.spoofing == spoofing
                and spoofing.region == owner and owner.captured
        end
        local selector, _, signature, err = resolve_region_selector()
        if not generation_current() then return finish(false, "search-region restoration cancelled") end
        if not selector or selector ~= owner.selector or signature ~= owner.list_signature then
            clear_spoof_owner(owner)
            spoof_status("region", "RESTORE SKIPPED", err or "search-region backend identity changed")
            return finish(true)
        end
        local observed, read_error = read_foreign_index(selector)
        if not generation_current() then return finish(false, "search-region restoration cancelled") end
        if observed == nil then return finish(false, read_error) end
        if observed ~= owner.last_index_applied then
            clear_spoof_owner(owner)
            spoof_status("region", "EXTERNAL CHANGE", "search-region changed outside CScript; preserved")
            return finish(true)
        end
        if observed ~= owner.snapshot_index then
            local function current()
                if not generation_current() then return false end
                local live, _, live_signature = resolve_region_selector()
                return generation_current() and live == selector and live_signature == signature
            end
            local ok, restore_error = write_region_index(selector, owner.snapshot_index, current)
            if not ok then return finish(false, restore_error) end
        end
        if not generation_current() then return finish(false, "search-region restoration cancelled") end
        clear_spoof_owner(owner)
        spoof_status("region", "RESTORED", "original session-search region")
        return finish(true)
    end

    local function apply_region_owner(wanted_label)
        local owner = State.spoofing.region
        local generation, spoofing = spoof_generation, State.spoofing
        local selector, list, signature, err = resolve_region_selector()
        if generation ~= spoof_generation or State.spoofing ~= spoofing then
            return false, "search-region action cancelled"
        end
        if not selector then return false, err end
        local wanted_index, backend_label = foreign_option_index(list, wanted_label, SPOOF_BACKENDS.region.aliases)
        if wanted_index == nil then return false, "selected region is absent from the current search-region list" end
        local observed, read_error = read_foreign_index(selector)
        if generation ~= spoof_generation or State.spoofing ~= spoofing or not started then
            return false, "search-region action cancelled"
        end
        if observed == nil then return false, read_error end
        local known_index = false
        for _, entry in ipairs(foreign_list_entries(list)) do
            if entry.index == observed then known_index = true end
        end
        if not known_index then return false, "search-region baseline index is outside the current list" end
        if owner.captured and (owner.selector ~= selector or owner.list_signature ~= signature) then
            return false, "search-region backend changed while owned"
        end
        if owner.captured and observed ~= owner.last_index_applied then
            clear_spoof_owner(owner)
            return false, "search-region changed outside CScript; external selection preserved"
        end
        if not owner.captured then
            owner.captured, owner.selector, owner.list_signature = true, selector, signature
            owner.snapshot_index, owner.last_index_applied = observed, observed
        end
        local function current()
            if not started or generation ~= spoof_generation or State.spoofing ~= spoofing
                or not is_on("network_spoof_region") or spoofing.region ~= owner
                or not owner.captured or owner.selector ~= selector then return false end
            local live, _, live_signature = resolve_region_selector()
            return started and generation == spoof_generation and State.spoofing == spoofing
                and is_on("network_spoof_region") and owner.captured
                and live == selector and live_signature == signature
        end
        if observed ~= wanted_index or not owner.active then
            owner.last_index_applied = wanted_index
            local ok, write_error = write_region_index(selector, wanted_index, current)
            if not ok then return false, write_error end
        end
        if not current() then return false, "search-region action cancelled" end
        owner.active = true
        spoof_status("region", "APPLIED", tostring(backend_label) .. " session-search override; selector read back")
        return true
    end

    local function publish_nat_status()
        local view = local_nat.Snapshot()
        State.spoofing.nat.active = view.active == true
        spoof_status("nat", view.status, view.detail)
        return view
    end

    local function service_nat(now)
        local_nat.Tick(tonumber(now) or now_ms())
        return publish_nat_status()
    end

    local function restore_nat_owner()
        local_nat.RequestRestore("NAT override disabled")
        local view = publish_nat_status()
        return not local_nat.HasWork(), view.detail
    end

    local function apply_nat_owner(wanted_label)
        local wanted = ({Open=1, Moderate=2, Strict=3})[wanted_label]
        local generation, selected = spoof_generation, list_index("network_nat_type", 0)
        local ok, why = local_nat.SetRequested(true, wanted, function()
            return started and generation == spoof_generation and is_on("network_spoof_nat")
                and list_index("network_nat_type", 0) == selected
        end)
        publish_nat_status()
        return ok, why
    end

    local function restore_spoof_owner(kind)
        if kind == "region" then return restore_region_owner() end
        return restore_nat_owner()
    end

    local function apply_spoof_owner(kind, wanted_label)
        if kind == "region" then return apply_region_owner(wanted_label) end
        return apply_nat_owner(wanted_label)
    end

    local function disable_local_spoofer(key, message)
        local feature = F[key]
        if feature then
            pcall(function()
                if feature:IsToggled() then feature:Toggle(false) end
            end)
        end
        ToggleState[key] = false
        toast(tostring(message), 6500)
    end

    local function sync_spoofing(now, force)
        now = tonumber(now) or now_ms()
        -- NAT intent is asynchronous; a pending native job is not an apply failure.
        if started and is_on("network_spoof_nat") then
            apply_nat_owner(NAT_TYPES[list_index("network_nat_type", 0) + 1] or NAT_TYPES[1])
        else
            restore_nat_owner()
        end
        service_nat(now)
        local spoofing = State.spoofing
        local generation = spoof_generation
        if not force and not spoofing.dirty
            and now - (tonumber(spoofing.last_attempt_ms) or -100000) < spoofing.retry_ms then
            return true
        end
        spoofing.dirty = false
        spoofing.last_attempt_ms = now
        local success = true
        for _, item in ipairs({
            { kind = "region", toggle_key = "network_spoof_region", combo_key = "network_region",
                values = MATCHMAKING_REGIONS },
        }) do
            if is_on(item.toggle_key) then
                local selected = item.values[list_index(item.combo_key, 0) + 1] or item.values[1]
                local ok, err = apply_spoof_owner(item.kind, selected)
                if generation ~= spoof_generation or State.spoofing ~= spoofing or not started then return false end
                if not ok then
                    success = false
                    restore_spoof_owner(item.kind)
                    if generation ~= spoof_generation or State.spoofing ~= spoofing or not started then return false end
                    spoof_status(item.kind, "UNAVAILABLE", err)
                    log_warn(SPOOF_BACKENDS[item.kind].label .. " spoofing disabled: " .. tostring(err))
                    disable_local_spoofer(item.toggle_key,
                        SPOOF_BACKENDS[item.kind].label.." spoof backend unavailable; the CScript toggle was disabled.")
                end
            else
                local ok, err = restore_spoof_owner(item.kind)
                if generation ~= spoof_generation or State.spoofing ~= spoofing or not started then return false end
                if not ok then
                    success = false
                    spoof_status(item.kind, "RESTORE FAILED", err)
                    log_warn(SPOOF_BACKENDS[item.kind].label .. " spoof restore failed: " .. tostring(err))
                elseif State.spoofing[item.kind].active ~= true
                    and State.spoofing[item.kind].captured ~= true
                    and State.spoofing.status[item.kind].state ~= "UNAVAILABLE"
                    and State.spoofing.status[item.kind].state ~= "RESTORE SKIPPED"
                    and State.spoofing.status[item.kind].state ~= "EXTERNAL CHANGE"
                    and State.spoofing.status[item.kind].state ~= "RESTORED" then
                    spoof_status(item.kind, "IDLE", "Disabled")
                end
            end
        end
        return success
    end

    local function get_session_player_ids()
        -- Slots, not ipairs(Players.Get()): Cherax may return a sparse/zero-based
        -- map, or a temporarily incomplete list. A streamed ped is not required.
        local ids = {}
        for player_id = 0, 31 do
            local available_ok, available = pcall(player_available, player_id)
            local native_active = false
            if not (available_ok and available) and type(deps.invoke_bool_detail) == "function" then
                native_active = deps.invoke_bool_detail(ORGANIZATION_SOURCE.player_active_native, player_id) == true
            end
            if (available_ok and available) or native_active then ids[#ids + 1] = player_id end
        end
        return ids
    end

    local function roster_global(index)
        if not script_global or type(script_global.GetInt) ~= "function" then return nil end
        local ok, value = pcall(script_global.GetInt, index)
        return ok and type(value) == "number" and value % 1 == 0 and value or nil
    end

    local function roster_hud_colour(index)
        local m = deps.Memory
        if not (m and type(m.Alloc) == "function" and type(m.Free) == "function"
            and type(m.WriteInt) == "function" and type(m.ReadInt) == "function") then return nil end
        local ok, ptr = pcall(m.Alloc, 16)
        if not ok or type(ptr) ~= "number" or ptr <= 0 then return nil end
        local read_ok, colour = pcall(function()
            for offset = 0, 12, 4 do m.WriteInt(ptr + offset, -1) end
            invoke_void(0x7C9C91AB74A0360F, index, ptr, ptr + 4, ptr + 8, ptr + 12)
            local result = {}
            for offset = 0, 12, 4 do
                local value = m.ReadInt(ptr + offset)
                if type(value) ~= "number" or value < 0 or value > 255 then return nil end
                result[#result + 1] = value
            end
            return result
        end)
        pcall(m.Free, ptr)
        return read_ok and colour or nil
    end

    local function roster_organization(player_id, colour_cache)
        -- Read-only TU1.73 source chain: freemode func_60 (Boss), func_1767
        -- (boss -> slot), func_39 (slot -> colour), func_1766 (192 + colour).
        if not (script_global and type(script_global.AreValid) == "function") then return nil end
        local ok, ready = pcall(script_global.AreValid)
        if not ok or ready ~= true or roster_global(1893070) ~= 32 then return nil end
        local boss = roster_global(1893070 + 1 + player_id * 615 + 10)
        if not boss or boss < 0 or boss > 31 or not player_available(boss) then return nil end
        if roster_global(1893070 + 1 + boss * 615 + 10) ~= boss then return nil end
        local kind = roster_global(1893070 + 1 + boss * 615 + 10 + 433)
        if kind ~= 0 and kind ~= 1 then return nil end
        local row = { label = kind == 1 and "MC" or "CEO", boss = boss }
        local base = 2649164 + 818
        if roster_global(base) ~= 10 or roster_global(base + 11) ~= 32
            or roster_global(base + 44) ~= 10 then return row end
        local slot = roster_global(base + 11 + 1 + boss)
        if not slot or slot < 0 or slot > 9 then return row end
        if roster_global(base + 44 + 1 + slot * 2) ~= boss then return row end
        local colour = roster_global(base + 44 + 1 + slot * 2 + 1)
        if not colour or colour < 0 or colour > 14 then return row end
        local hud = 192 + colour
        if colour_cache[hud] == nil then colour_cache[hud] = roster_hud_colour(hud) or false end
        row.colour_id, row.colour = colour, colour_cache[hud] or nil
        return row
    end

    local function safe_identity(player_id, fallback_name)
        local cached = State.identity_cache[player_id]
        if cached and fallback_name and cached.name ~= fallback_name then cached = nil end
        local identity = cached or {
            id = player_id,
            name = fallback_name or player_name(player_id),
            rid = nil,
            host_key = nil,
            friend_status = nil,
            is_friend = false,
            friend_checked_at = -100000,
            friend_source = "PENDING",
            friend_error = nil,
        }
        identity.name = fallback_name or identity.name or player_name(player_id)
        -- Cached labels may survive a failed lookup, but a copy requires fresh
        -- identity evidence from this refresh.
        identity.copy_verified = false
        if players and type(players.GetById) == "function" then
            local ok_player, player = pcall(players.GetById, player_id)
            if ok_player and player then
                do
                    local ok_info, info = pcall(function()
                        if type(player.GetGamerInfo) == "function" then return player:GetGamerInfo() end
                    end)
                    if ok_info and info then
                        local ok_identity, rid, host_key = pcall(function()
                            return tonumber(info.RockstarId), info.HostKey
                        end)
                        if ok_identity and rid and rid > 0 and rid % 1 == 0 then
                            if identity.rid ~= rid then
                                identity.is_friend, identity.friend_checked_at = false, -100000
                            end
                            identity.rid = rid
                            identity.host_key = host_key
                            identity.copy_verified = true
                        end
                    end
                end
                -- Retain Cherax's undocumented FriendStatus only as raw diagnostic
                -- evidence. It is not interpreted as a PID mask or a Social Club
                -- friendship flag.
                pcall(function()
                    local info = player.PlayerInfo
                    local status = info and tonumber(info.FriendStatus)
                    if status ~= nil then identity.friend_status = math.floor(status) end
                end)
            end
        end
        local now = now_ms()
        if player_id == local_player_id() then
            identity.is_friend, identity.friend_source, identity.friend_error = false, "LOCAL_PLAYER", nil
            identity.friend_checked_at = now
        elseif identity.rid and now - (tonumber(identity.friend_checked_at) or -100000) >= 5000 then
            identity.friend_checked_at = now
            if not (gamer_handle and type(gamer_handle.New) == "function") then
                identity.is_friend, identity.friend_source = false, "UNAVAILABLE"
                identity.friend_error = "GamerHandle.New is unavailable"
            else
                local ok_friend, is_friend_or_error = pcall(function()
                    local handle = gamer_handle.New(identity.rid)
                    assert(handle ~= nil and type(handle.ToBuffer) == "function", "GamerHandle creation failed")
                    local buffer = handle:ToBuffer()
                    assert(buffer ~= nil and type(buffer.GetBuffer) == "function", "GamerHandle buffer unavailable")
                    return invoke_bool(H.NETWORK_IS_FRIEND, buffer:GetBuffer())
                end)
                if ok_friend then
                    identity.is_friend = is_friend_or_error == true
                    identity.friend_source, identity.friend_error = "NETWORK_IS_FRIEND", nil
                else
                    identity.is_friend, identity.friend_source = false, "ERROR"
                    identity.friend_error = tostring(is_friend_or_error)
                end
            end
        end
        State.identity_cache[player_id] = identity
        return identity
    end

    local function rebuild_row_labels(rows)
        for _, row in ipairs(rows) do
            local badges = {}
            if row.local_player then badges[#badges + 1] = "You" end
            if row.is_friend then badges[#badges + 1] = "Your Friend" end
            if row.session_host then badges[#badges + 1] = "Host" end
            if row.script_host then badges[#badges + 1] = "Script" end
            local prefix = #badges > 0 and ("[" .. table.concat(badges, "/") .. "] ") or ""
            local status = {}
            if row.organization then
                status[#status + 1] = row.organization.label .. (row.organization.colour_id
                    and (" #" .. tostring(row.organization.colour_id + 1)) or " colour ?")
            end
            if row.passive then status[#status + 1] = "Passive" end
            if row.ghost then status[#status + 1] = "Ghosted to you" end
            if row.passive_known ~= true or row.ghost_known ~= true then status[#status + 1] = "Status ?" end
            row.status_label = #status > 0 and ("  [" .. table.concat(status, "] [") .. "]") or ""
            row.label = "   " .. prefix .. row.name:gsub("##", "# #") .. " (" .. tostring(row.id) .. ")"
                .. row.status_label .. "##session_player_" .. tostring(row.id)
        end
    end

    local function tags_have(tags, needle)
        tags = tostring(tags or ""):lower()
        if tags:find(needle, 1, true) ~= nil then return true end
        -- Current Cherax renders compact host badges (for example [H] and
        -- [SH]) instead of spelling out the older long labels.
        if needle == "session host" then return tags:find("[h]", 1, true) ~= nil end
        if needle == "script host" then return tags:find("[sh]", 1, true) ~= nil end
        return false
    end

    local function append_history(kind, player_id, name, rid, now, detail)
        local history = State.history
        history[#history + 1] = {
            time_ms = now,
            kind = tostring(kind),
            player_id = tonumber(player_id) or -1,
            name = tostring(name or "Unknown"),
            rid = tonumber(rid),
            detail = detail and tostring(detail) or nil,
        }
        while #history > HISTORY_LIMIT do table.remove(history, 1) end
    end

    local function recent_churn(now)
        local count = 0
        for i = #State.history, 1, -1 do
            local item = State.history[i]
            if now - (tonumber(item.time_ms) or 0) > CHURN_WINDOW_MS then break end
            if item.kind == "join" or item.kind == "leave" or item.kind == "host" then count = count + 1 end
        end
        return count
    end

    local function duration_label(ms)
        ms = math.max(0, tonumber(ms) or 0)
        local seconds = math.floor(ms / 1000)
        local hours = math.floor(seconds / 3600)
        local minutes = math.floor((seconds % 3600) / 60)
        seconds = seconds % 60
        if hours > 0 then return ("%dh %02dm"):format(hours, minutes) end
        return ("%dm %02ds"):format(minutes, seconds)
    end

    local function set_selected_row_labels(selected_row)
        if selected_row then
            State.selected_name = selected_row.name
            local flags = {}
            if selected_row.local_player then flags[#flags + 1] = "You" end
            if selected_row.is_friend then flags[#flags + 1] = "Your Social Club Friend" end
            if selected_row.session_host then flags[#flags + 1] = "Session Host" end
            if selected_row.script_host then flags[#flags + 1] = "Script Host" end
            State.selected_id_label = ("Player ID %d%s"):format(selected_row.id,
                #flags > 0 and ("  [" .. table.concat(flags, ", ") .. "]") or "")
            State.selected_rid_label = selected_row.rid and ("Rockstar ID: " .. tostring(selected_row.rid))
                or "Rockstar ID unavailable"
            if selected_row.local_player then
                State.selected_friend_label = "This is your current Rockstar account."
            elseif selected_row.friend_source ~= "NETWORK_IS_FRIEND" then
                State.selected_friend_label = "Social Club friendship unavailable on this refresh."
            elseif selected_row.is_friend then
                State.selected_friend_label = "Social Club friend of your current Rockstar account."
            else
                State.selected_friend_label = "Not a Social Club friend of your current Rockstar account."
            end
        else
            State.selected_name = "None"
            State.selected_id_label = "No player selected"
            State.selected_rid_label = "Rockstar ID unavailable"
            State.selected_friend_label = "Social Club friendship not checked yet."
        end
    end

    local function publish_snapshot(sampled_now)
        local rows, friend_count = {}, 0
        for index, row in ipairs(State.rows) do
            if row.is_friend then friend_count = friend_count + 1 end
            rows[index] = {
                id = row.id,
                name = row.name,
                rid = row.rid,
                host_key = row.host_key,
                friend_status = row.friend_status,
                is_friend = row.is_friend == true,
                friend_source = row.friend_source,
                friend_error = row.friend_error,
                local_player = row.local_player == true,
                session_host = row.session_host == true,
                script_host = row.script_host == true,
                passive = row.passive == true,
                ghost = row.ghost == true,
                passive_known = row.passive_known == true,
                ghost_known = row.ghost_known == true,
                status_label = row.status_label,
                organization = row.organization and {
                    label = row.organization.label, boss = row.organization.boss,
                    colour_id = row.organization.colour_id,
                    colour = row.organization.colour and { table.unpack(row.organization.colour) } or nil,
                } or nil,
                label = row.label,
            }
        end
        local history = {}
        for i = math.max(1, #State.history - 9), #State.history do
            local item = State.history[i]
            if item then
                history[#history + 1] = {
                    time_ms = item.time_ms,
                    kind = item.kind,
                    player_id = item.player_id,
                    name = item.name,
                    rid = item.rid,
                    detail = item.detail,
                }
            end
        end
        local now = sampled_now or now_ms()
        State.render_snapshot = {
            rows = rows,
            selected = State.selected,
            selected_name = State.selected_name,
            selected_id_label = State.selected_id_label,
            selected_distance_label = State.selected_distance_label,
            selected_rid_label = State.selected_rid_label,
            selected_friend_label = State.selected_friend_label,
            count_label = State.count_label,
            online = State.online == true,
            session_status = State.session_status,
            session_age_label = State.session_started_ms and duration_label(now - State.session_started_ms) or "--",
            session_host_id = State.session_host_id,
            session_host_name = State.session_host_name,
            session_host_rid = State.session_host_rid,
            script_host_id = State.script_host_id,
            script_host_name = State.script_host_name,
            host_migrations = State.host_migrations,
            recent_churn = recent_churn(now),
            friend_count = friend_count,
            friend_group_count = 0,
            history = history,
        }
        return State.render_snapshot
    end

    local function refresh(now, force)
        local refresh_revision = selection_revision
        now = tonumber(now) or now_ms()
        local organization =
            State.organization

        local background_required =
            organization
            and (
                organization.bypass_enabled == true
                or organization.acquire_pending == true
            )

        if force ~= true
            and not background_required
            and now - (
                State.last_visible_ms
                or -100000
            ) > 1000 then
            return
        end

        if force ~= true
            and not State.dirty
            and now - State.last_refresh < 1000 then
            return
        end

        local online = invoke_bool(H.NETWORK_IS_SESSION_STARTED) == true
        if online and not State.online then
            State.session_started_ms = now
            State.roster_initialized = false
            State.known_players = {}
            State.identity_cache = {}
            State.history = {}
            State.host_migrations = 0
        elseif not online and State.online then
            State.session_started_ms = nil
            State.roster_initialized = false
            State.known_players = {}
            State.identity_cache = {}
            State.session_host_id = -1
            State.script_host_id = -1
        end
        State.online = online

        local ids = get_session_player_ids()
        local rows, present, colour_cache = {}, {}, {}
        local session_host_id, script_host_id = -1, -1
        for _, value in ipairs(ids) do
            local player_id = tonumber(value)
            if player_id then
                local name = player_name(player_id)
                local identity_ok, identity = pcall(safe_identity, player_id, name)
                if not identity_ok then identity = { name = name } end
                identity.name = name
                local flags_ok, passive, ghost, tags, known = pcall(player_flags, player_id)
                if not flags_ok then passive, ghost, tags, known = false, false, "", nil end
                local org_ok, organization = pcall(roster_organization, player_id, colour_cache)
                local is_local = player_id == local_player_id()
                local is_session_host = tags_have(tags, "session host")
                local is_script_host = tags_have(tags, "script host")
                if is_session_host then session_host_id = player_id end
                if is_script_host then script_host_id = player_id end
                rows[#rows + 1] = {
                    id = player_id,
                    name = name,
                    rid = identity.rid,
                    host_key = identity.host_key,
                    friend_status = identity.friend_status,
                    is_friend = identity.is_friend == true,
                    friend_source = identity.friend_source,
                    friend_error = identity.friend_error,
                    local_player = is_local,
                    session_host = is_session_host,
                    script_host = is_script_host,
                    passive = known and known.passive_mode == true or false,
                    ghost = ghost,
                    passive_known = known and type(known.passive_mode) == "boolean" or false,
                    ghost_known = known and known.ghost == true,
                    organization = org_ok and organization or nil,
                    tags = tags,
                    label = name .. "##session_player_" .. tostring(player_id),
                }
                present[player_id] = true
            end
        end

        rebuild_row_labels(rows)

        if State.roster_initialized then
            for player_id in pairs(present) do
                if not State.known_players[player_id] then
                    local identity = safe_identity(player_id, player_name(player_id))
                    append_history("join", player_id, identity.name, identity.rid, now)
                end
            end
            for player_id, previous in pairs(State.known_players) do
                if not present[player_id] then
                    append_history("leave", player_id, previous.name, previous.rid, now)
                    State.identity_cache[player_id] = nil
                end
            end
        end
        local known = {}
        for _, row in ipairs(rows) do known[row.id] = { name = row.name, rid = row.rid } end
        State.known_players = known
        State.roster_initialized = true

        if session_host_id >= 0 then
            if State.session_host_id >= 0 and State.session_host_id ~= session_host_id then
                local identity = safe_identity(session_host_id, player_name(session_host_id))
                State.host_migrations = State.host_migrations + 1
                append_history("host", session_host_id, identity.name, identity.rid, now,
                    ("from player %d"):format(State.session_host_id))
            end
            State.session_host_id = session_host_id
            local identity = safe_identity(session_host_id, player_name(session_host_id))
            State.session_host_name = identity.name
            State.session_host_rid = identity.rid
        else
            State.session_host_id = -1
            State.session_host_name = "Unknown"
            State.session_host_rid = nil
        end
        State.script_host_id = script_host_id
        State.script_host_name = script_host_id >= 0 and player_name(script_host_id) or "Unknown"

        if not online then
            State.session_status = "Offline"
        else
            local churn = recent_churn(now)
            if churn >= 8 then
                State.session_status = "High churn"
            elseif churn >= 4 then
                State.session_status = "Changing"
            else
                State.session_status = "Stable"
            end
        end

        if refresh_revision ~= selection_revision then return false end
        State.rows = rows
        State.count_label = ("Players (%d)"):format(#rows)
        -- Identity selection publishes only after its fresh read and host setter.
        -- Never let a refresh follow a different roster row during that request.
        if selection_busy then
            State.last_refresh = now
            State.dirty = false
            return true
        end
        if State.selected < 0 or not present[State.selected] then
            State.selected = rows[1] and rows[1].id or -1
        end

        local selected_row
        for _, row in ipairs(rows) do
            if row.id == State.selected then
                selected_row = row; break
            end
        end
        set_selected_row_labels(selected_row)
        if selected_row then
            local snapshot_ok, snapshot = pcall(player_snapshot, selected_row.id)
            if snapshot_ok and snapshot then
                State.selected_snapshot = snapshot
                State.selected_distance_label = ("Distance: %s"):format(
                    snapshot.distance and ("%.0f m"):format(snapshot.distance) or "Unavailable")
            elseif not State.selected_snapshot or State.selected_snapshot.id ~= selected_row.id then
                State.selected_snapshot = nil
                State.selected_distance_label = "Distance unavailable"
            end
        else
            State.selected_snapshot = nil
            State.selected_distance_label = ""
        end

        State.last_refresh = now
        State.dirty = false
        publish_snapshot()
    end

