local function board_admission_thread_matches(hash,ptr)
    if type(ptr)~="number" or ptr<65536 or ptr%8~=0
        or invoke_int(0x2C83A9DA6BFFC4F9,hash)~=1 then return false end
    local ok,current=pcall(function() return raw_binding("ScriptLocal").GetPtr(hash,0) end)
    return ok and current==ptr
end
local function board_verify_admission_source()
    local memory,utils=raw_binding("Memory"),raw_binding("Utils")
    if not memory or type(memory.ScanScript)~="function" or type(memory.ReadUByte)~="function"
        or not utils or type(utils.Joaat)~="function" then return false end
    local hash=utils.Joaat("freemode")
    local ok,thread=pcall(function() return raw_binding("ScriptLocal").GetPtr(hash,0) end)
    if not ok or not board_admission_thread_matches(hash,thread) then return false end
    for _,pattern in ipairs(BOARD_ADMISSION_SIGNATURES) do
        local ok,ptr=pcall(memory.ScanScript,hash,pattern)
        if not ok or type(ptr)~="number" or ptr<65536 then return false end
        local offset=0
        for byte in pattern:gmatch("%x%x") do
            local good,value=pcall(memory.ReadUByte,ptr+offset)
            if not good or value~=tonumber(byte,16) then return false end
            offset=offset+1
        end
    end
    if not board_admission_thread_matches(hash,thread) then return false end
    return true,hash,thread
end

local function board_host()
    local host={}
    function host.Capture()
        if State.pending_destination then return nil,"Finish the current teleport first." end
        local current,why=safe_local_state("going to a heist board");if not current then return nil,why end
        local scope=board_scope();if not scope then return nil,"Online character context is unavailable." end
        local ok,version=native("InvokeString",0xFCA9373EF340AC0A)
        local good,base=pcall(function()return raw_binding("Memory").GetBaseAddress("GTA5_Enhanced.exe")end)
        if not ok or version~="1.73" or not good or type(base)~="number" or base<=0
            or board_global(1845347)~=32 or board_global(2658296)~=32 then
            return nil,"Heist board property data requires the current Enhanced 1.73 profile."
        end
        scope.origin=current;scope.ped=current.ped;scope.address=current.address
        return scope
    end
    function host.Valid(s)
        local scope=board_scope()
        if not scope or scope.key~=s.key or local_ped()~=s.ped or not invoke_bool(H.DOES_ENTITY_EXIST,s.ped)
            or invoke_bool(H.IS_ENTITY_DEAD,s.ped) then return false end
        local ok,address=pcall(function()return raw_binding("GTA").HandleToPointer(s.ped):GetAddress()end)
        if not ok or address~=s.address then return false end
        if s.admission_ptr and not board_admission_thread_matches(s.admission_hash,s.admission_ptr) then return false end
        if s.family=="cayo" and s.cayo_inside and not host.Inside(s) then return false end
        if s.family=="casino" and s.casino_inside and not host.Inside(s) then return false end
        local r=BOARD_ROUTES[s.family]
        if r and board_global(1845347+1+s.pid*884+260+r.ownership)~=s.owned then return false end
        if s.simple_ptr then
            local ok,ptr,property=pcall(function()
                local l=raw_binding("ScriptLocal")
                return l.GetPtr(93794601,263),l.GetInt(93794601,265)
            end)
            if not ok or ptr~=s.simple_ptr or property~=s.property
                or board_global(2658296+1+s.pid*468+325+8)~=s.property
                or board_global(2658296+1+s.pid*468+325+11)~=s.pid
                or invoke_int(0x2C83A9DA6BFFC4F9,93794601)~=1 then return false end
        end
        if s.apartment_ptr then
            local ok,hash,ptr=pcall(function()
                local h=raw_binding("Utils").Joaat("am_mp_property_int")
                return h,raw_binding("ScriptLocal").GetPtr(h,3856)
            end)
            if not ok or ptr~=s.apartment_ptr or invoke_int(0x2C83A9DA6BFFC4F9,hash)~=1
                or property_local(496)~=s.apartment_property or property_local(3856)~=s.pid then return false end
        end
        return true
    end
    local function apartment_inside(s)
        local ok,hash,ptr=pcall(function()
            local h=raw_binding("Utils").Joaat("am_mp_property_int")
            return h,raw_binding("ScriptLocal").GetPtr(h,3856)
        end)
        if not ok or type(ptr)~="number" or ptr<65536 or invoke_int(0x2C83A9DA6BFFC4F9,hash)~=1 then return false end
        local owner,property=property_local(3856),property_local(496)
        local interior=invoke_int(H.GET_INTERIOR_FROM_ENTITY,s.ped)
        if owner~=s.pid or not property or property<1 or property>85 or not interior or interior<=0
            or property_local(7910)~=interior or property_local(706)~=4 then return false end
        if s.apartment_property and s.apartment_property~=property or s.apartment_ptr and s.apartment_ptr~=ptr then return false end
        return true,property,interior,ptr
    end
    function host.Resolve(family,s)
        s.family=family
        if family=="cayo" then
            if not host.Inside(s) then return nil,"Enter your owned Kosatka first, or use Go to Kosatka." end
            s.cayo_inside=true
            return {family=family,target=CAYO_BOARD,heading=180}
        end
        local r=BOARD_ROUTES[family]
        if r then
            local owned=board_global(1845347+1+s.pid*884+260+r.ownership)
            if not owned or owned<1 or owned>r.maximum then return nil,"An owned "..(family=="casino" and "Arcade" or "Facility").." is required." end
            s.owned=owned
            s.family=family
            s.interior=invoke_int(H.GET_INTERIOR_AT_COORDS,r.target.x,r.target.y,r.target.z)
            -- Ownership index -> property mapping is freemode func1545/1553.
            s.property=r.first+owned-1
            local inside,ptr=host.Inside(s)
            local target=r.target
            if inside then
                s.simple_ptr=ptr
                if family=="casino" then s.casino_inside=true end
            end
            return {family=family,target=target,heading=r.heading,admission=not inside,request=not inside,
                exit_required=s.origin.interior~=0 and not inside}
        elseif family=="apartment" then
            if apartment_inside(s) then
                local target,why=host.Board(s)
                if not target then return nil,why end
                return {family=family,target=target}
            end
            local core=module_context.CScript.Economy
            local ok,stage=pcall(function()return core.ReadStat(("MP%d_HEIST_PLANNING_STAGE"):format(s.slot))end)
            if not ok or stage~=-1 then return nil,"The active apartment heist finale is not ready." end
            local coords,why=resolve_unique_blip(40,2,nil,true)
            if not coords then return nil,"Active heist apartment: "..tostring(why) end
            return {family=family,target=coords,admission=true,exit_required=s.origin.interior~=0}
        end
        return nil,"This heist board trip is unavailable."
    end
    function host.Inside(s)
        if s.family=="apartment" then return apartment_inside(s) end
        if s.family=="cayo" then
            -- Same owner/interior/ownership evidence as the existing Kosatka
            -- utility. The interaction target is heist_island_planning func577.
            local interior=invoke_int(H.GET_INTERIOR_FROM_ENTITY,s.ped)
            local sub=invoke_int(H.GET_INTERIOR_AT_COORDS,1560.0,400.0,-50.0)
            local flags=board_global(1845347+1+s.pid*884+260+489)
            return interior and sub and sub>0 and interior==sub and invoke_bool(H.IS_INTERIOR_READY,sub)
                and flags~=nil and (flags&1)==1 and board_global(2658296+1+s.pid*468+325+11)==s.pid
                and invoke_int(0x2C83A9DA6BFFC4F9,raw_binding("Utils").Joaat("heist_island_planning"))==1
        end
        local r=BOARD_ROUTES[s.family]
        if not r then return false end
        local property=board_global(2658296+1+s.pid*468+325+8)
        local owner=board_global(2658296+1+s.pid*468+325+11)
        if not property or property~=(s.property or r.first+s.owned-1) or owner~=s.pid
            or invoke_int(0x2C83A9DA6BFFC4F9,93794601)~=1 then return false end
        local interior
        if s.family=="casino" then
            -- Arcade's controller owns both floors; its Inside check uses this
            -- complete property volume, not equality with the basement interior.
            local x,y,z=vector_components(invoke_vec3(H.GET_ENTITY_COORDS,s.ped,false))
            local low,high=CASINO_BOUNDS.minimum,CASINO_BOUNDS.maximum
            if not x or x<low.x or x>high.x or y<low.y or y>high.y or z<low.z or z>high.z then return false end
        else
            interior=invoke_int(H.GET_INTERIOR_AT_COORDS,r.target.x,r.target.y,r.target.z)
            if not interior or interior<=0 or invoke_int(H.GET_INTERIOR_FROM_ENTITY,s.ped)~=interior
                or not invoke_bool(H.IS_INTERIOR_READY,interior) then return false end
        end
        local ok,ptr,p,f,phase,room=pcall(function()
            local l=raw_binding("ScriptLocal")
            return l.GetPtr(93794601,263),l.GetInt(93794601,265),l.GetInt(93794601,266),
                l.GetInt(93794601,267),l.GetInt(93794601,271)
        end)
        return ok and type(ptr)=="number" and ptr>=65536 and (not s.simple_ptr or s.simple_ptr==ptr)
            and p==property and f==(s.family=="casino" and 17 or 9) and phase==7
            and (s.family=="casino" and type(room)=="number" and room>0
                or s.family~="casino" and room==interior),ptr
    end
    function host.BeginExit(s,intent)
        local player=module_context and module_context.CScript and module_context.CScript.Player
        if not player or type(player.BeginLocalInteriorExit)~="function"
            or type(player.PollLocalInteriorExit)~="function" or type(player.CancelLocalInteriorExit)~="function" then
            return nil,"The local interior-exit service is unavailable."
        end
        s.exit_service=player
        return player.BeginLocalInteriorExit("Go to "..tostring(s.family).." board",intent)
    end
    function host.PollExit(s)
        return s.exit_service.PollLocalInteriorExit(s.exit_token)
    end
    function host.CancelExit(s,reason)
        if s.exit_service and s.exit_token then s.exit_service.CancelLocalInteriorExit(s.exit_token,reason) end
        s.exit_token=nil;s.exit_service=nil
    end
    function host.AfterExit(s)
        local current,why=safe_local_state("continuing the board trip")
        if not current or current.interior~=0 or current.ped~=s.ped or current.address~=s.address or not host.Valid(s) then
            return false,why or "The local character changed after leaving the current interior."
        end
        -- Departure changes the origin. Rollback may return only to this
        -- confirmed exterior, never to coordinates in the departed interior.
        s.origin=current
        return true
    end
    function host.Request(s)
        if not host.Valid(s) or s.request_committed then return false,"Property request context changed." end
        local verified,hash,thread=board_verify_admission_source()
        if not verified then return false,"The GTA property-admission source could not be verified." end
        s.admission_hash,s.admission_ptr=hash,thread
        local current,why=safe_local_state("requesting property admission")
        if not current or current.interior~=0 then return false,why or "Leave the current interior first." end
        if (distance_sq(current.coords,s.origin.coords) or math.huge)>16 then return false,"You moved away during the board request." end
        local root=1951218
        -- An occupied request belongs to GTA. Never replace an invite/transition.
        if board_global(root+4292)~=0 or board_global(root+4293)~=-1
            or board_global(root+3934)~=-1 or board_global(root+4302)~=-1
            or board_global(root+4294)~=0 or board_global(root+4300)~=0
            or board_global(root+4027)~=-1 then return false,"Another GTA property admission is pending." end
        local globals=raw_binding("ScriptGlobal")
        if not globals or type(globals.SetInt)~="function" then return false,"Property request APIs are unavailable." end
        -- func25008 selects the destination owner through func2576. Requesting
        -- our own property lets the normal family callback choose local ownership.
        local writes={{root+3934,-1,s.pid},{root+4293,-1,s.property},
            {root+4294,0,0},{root+4299,board_global(root+4299),1},{root+4292,0,1}}
        local applied={}
        for _,row in ipairs(writes) do
            if row[2]==nil or not host.Valid(s) or board_global(row[1])~=row[2] then
                why="GTA property request changed before commit.";break
            end
            if row[1]==root+4292 then
                -- The setter can apply then throw; GTA may consume the flag
                -- before readback. Once commit is attempted, never replay owner
                -- preparation or restore it. Observe genuine admission instead.
                s.request_committed=true
                local ok,result=pcall(globals.SetInt,row[1],row[3])
                s.request_uncertain=not ok or result==false or board_global(row[1])~=row[3]
                return true
            end
            applied[#applied+1]=row
            local ok,result=pcall(globals.SetInt,row[1],row[3])
            if not ok or result==false or board_global(row[1])~=row[3] then why="GTA rejected the property request.";break end
        end
        if why then
            -- Retain partial preparation for compare-before-restore cleanup.
            -- It has not yielded or handed a successfully committed request to GTA.
            s.request_preparation=applied
            return false,why
        end
        return false,"Property commit was not attempted."
    end
    function host.Entrance(s)
        local sprite=s.family=="doomsday" and 590 or s.family=="casino" and 740
        if not sprite then return nil,"No normal-admission route for this property." end
        local coords,why=resolve_unique_blip(sprite)
        if not coords then return nil,"Owned property entrance: "..tostring(why) end
        return coords
    end
    function host.Board(s)
        local current=safe_local_state("waiting for property admission")
        if not current then return nil,"Waiting for GTA to release property-entry control." end
        if s.family=="cayo" then
            if not host.Inside(s) then return nil,"Waiting for your owned Kosatka interior." end
            return CAYO_BOARD
        end
        if s.family~="apartment" then
            local inside,ptr=host.Inside(s)
            if not inside then return nil,"Waiting for your owned property registration." end
            s.simple_ptr=ptr
            if s.family=="casino" then s.casino_inside=true end
            s.last_target=invoke_vec3(H.GET_ENTITY_COORDS,s.ped,false)
            return BOARD_ROUTES[s.family].target
        end
        local inside,property,interior,ptr=apartment_inside(s)
        if not inside then return nil,"Waiting for your apartment registration." end
        local board,why=resolve_unique_blip(428,2)
        if not board then return nil,why end
        local x,y,z=vector_components(board)
        if invoke_int(H.GET_INTERIOR_AT_COORDS,x,y,z)~=interior then return nil,"Waiting for the apartment's own planning marker." end
        s.apartment_property=property;s.apartment_ptr=ptr
        s.last_target=invoke_vec3(H.GET_ENTITY_COORDS,s.ped,false)
        return {x=x,y=y,z=z}
    end
    local function release_stream(s)
        local clean=true
        if s.scene then if invoke_void(0xC197616D221FF4A4) then s.scene=nil else clean=false end end
        if s.focus then if invoke_void(0x31B73D1EA9F01DA2) then s.focus=nil else clean=false end end
        return clean
    end
    function host.Prepare(s)
        local t=s.target
        if not s.scene then
            local current,why=safe_local_state("loading the planning room")
            if not current then return nil end
            local expected=s.last_target or s.origin.coords
            local distance=distance_sq(current.coords,expected)
            if not distance or distance>16 then return false,"You moved away during the board trip." end
            if invoke_bool(0xA41A05B6CB741B85) then return false,"Another GTA scene is loading." end
            local interior=invoke_int(H.GET_INTERIOR_AT_COORDS,t.x,t.y,t.z)
            if s.family=="casino" and s.casino_inside and interior==0 then
                -- AM_MP_ARCADE loads the secondary floor itself. Wait for its
                -- real interior instead of leaving this already owned property.
                invoke_void(H.REQUEST_COLLISION_AT_COORD,t.x,t.y,t.z)
                return nil
            end
            if interior==nil or (not s.route.admission or s.phase=="BOARD_STREAMING") and interior<=0 then
                return false,"The selected planning interior is unavailable.",true
            end
            s.interior=interior
            if interior>0 and not s.pinned then
                s.presentation_interior=interior
                s.was_disabled=invoke_bool(0xBC5115A5A939DD15,interior)
                s.was_capped=invoke_bool(0x92BAC8ACF88CEC26,interior)
                if s.was_disabled and not invoke_void(0x6170941419D7D8EC,interior,false) then return false,"Interior enable failed." end
                if s.was_capped and not invoke_void(0xD9175F941610DB54,interior,false) then return false,"Interior uncap failed." end
                if not invoke_void(0x2CA429C029CCF247,interior) then return false,"Interior pin failed." end
                s.pinned=interior
                if not invoke_void(0x41F37C3427C75AE0,interior) then return false,"Interior refresh failed." end
            end
            if not invoke_void(0xBB7454BAFF08FE25,t.x,t.y,t.z,0.0,0.0,0.0) then return false,"Streaming focus failed." end
            s.focus=true
            if not invoke_bool(0xACCFB4ACF53551B0,t.x,t.y,t.z,50.0,0) then return false,"Scene streaming was rejected." end
            s.scene=true
        end
        invoke_void(H.REQUEST_COLLISION_AT_COORD,t.x,t.y,t.z)
        if not invoke_bool(0x01B8247A7A8B9AD1) or s.interior>0 and not invoke_bool(H.IS_INTERIOR_READY,s.interior) then return nil end
        return true
    end
    function host.Move(s)
        local current=safe_local_state("moving to the heist board");if not current then return nil end
        local expected=s.last_target or s.origin.coords
        if (distance_sq(current.coords,expected) or math.huge)>16 then return false,"You moved away during the board trip." end
        if s.family=="apartment" and s.phase=="STREAMING" and s.route.admission then
            local live=resolve_unique_blip(40,2,nil,true)
            if not live or (distance_sq(live,s.target) or math.huge)>1 then return false,"The active apartment entrance changed." end
        end
        if s.fallback and s.phase=="STREAMING" then
            local live=host.Entrance(s)
            if not live or (distance_sq(live,s.target) or math.huge)>1 then return false,"The owned property entrance changed." end
        end
        if not release_stream(s) then return false,"Planning stream cleanup is pending." end
        local t=s.target
        if not invoke_void(H.SET_ENTITY_COORDS_NO_OFFSET,s.ped,t.x,t.y,t.z,false,false,false) then return false,"GTA rejected board-trip placement." end
