inspect_heist_board_prompt=function(family)
    local result={available=false,family=family,label="Teleport to planning screen",reset=false}
    if family~="apartment" and family~="casino" and family~="doomsday" and family~="cayo" then
        result.reason="Select a supported heist.";result.reset=true;return result
    end
    if not started or State.pending_destination or State.cargo_request or board_trip and board_trip.Active() then
        result.reason="Finish the current travel or computer request first.";return result
    end
    local host=board_host()
    local scope,why=host.Capture()
    if not scope then result.reason=why;return result end
    if scope.origin.interior<=0 and family~="casino" then result.reason="Enter your owned planning interior first.";result.reset=true;return result end
    scope.family=family
    local r=BOARD_ROUTES[family]
    if r then
        scope.owned=board_global(1845347+1+scope.pid*884+260+r.ownership)
        if not scope.owned or scope.owned<1 or scope.owned>r.maximum then result.reset=true;return result end
        scope.property=r.first+scope.owned-1
        local interior=invoke_int(H.GET_INTERIOR_AT_COORDS,r.target.x,r.target.y,r.target.z)
        result.reset=family~="casino" and interior~=scope.origin.interior
            or board_global(2658296+1+scope.pid*468+325+8)~=scope.property
            or board_global(2658296+1+scope.pid*468+325+11)~=scope.pid
