        result.reset=invoke_int(H.GET_INTERIOR_AT_COORDS,1560.0,400.0,-50.0)~=scope.origin.interior
            or board_global(2658296+1+scope.pid*468+325+11)~=scope.pid
    else
        result.reset=property_local(3856)~=scope.pid
    end
    if not host.Inside(scope) then result.reason="Enter the selected heist's owned planning interior first.";return result end
    local route,why=host.Resolve(family,scope)
    if not route then result.reason=why;return result end
    if route.admission or route.exit_required or not host.Inside(scope) then
        result.reason="Enter the selected heist's owned planning interior first.";return result
    end
    result.available=true;result.reset=false;result.interior=scope.origin.interior;result.property=scope.property or scope.apartment_property
    result.x,result.y,result.z=route.target.x,route.target.y,route.target.z
    result.key=table.concat({scope.key,family,result.interior,tostring(result.property or "kosatka"),
        tostring(scope.simple_ptr or scope.apartment_ptr or 0)},":")
    return result
end
local function heist_board_prompt_snapshot(family)
