            local checked,flags,property=pcall(function()return locals.GetInt(r.hash,592),locals.GetInt(r.hash,768)end)
            if not checked or type(flags)~='number' or flags%1~=0 or (flags & (1<<13))==0 or property~=r.warehouse_property then return end
        end
        if ok and type(handle)=="number" and handle>0 and invoke_bool(0x85F01B8D5B90570E,handle)
            and app_global(77414)==1 and app_global(1574757)==1 and owner and owner%4294967296==r.hash%4294967296
            and frame and frame>r.start_frame then
            if r.frame and frame>r.frame then
                cargo_finish(true,r.warehouse_slot~=nil and ('Warehouse '..tostring(r.warehouse_slot+1)..' laptop is rendering. Close Cherax to use it.') or 'CEO cargo computer is rendering. Close Cherax to use it.');return
            end
            r.frame=frame
        end
        return
    end
    if app_global(77414)~=0 or app_global(1574757)~=0 or invoke_int(0x2C83A9DA6BFFC4F9,r.hash)~=0 then cargo_finish(false,"Another computer opened.");return end
    if not r.requested then
        if not invoke_bool(0xFC04745FBE67C19A,"appsecuroserv") then cargo_finish(false,"CEO computer script is unavailable.");return end
        local ok=native("InvokeVoid",0x6EB5F71AA68F2E8E,"appsecuroserv")
        if not ok then cargo_finish(false,"CEO script request failed.");return end
        r.requested=true
    end
    if not invoke_bool(0xE6CC9F3BA0FB9EF1,"appsecuroserv") then return end
    local current,err=safe_local_state("opening the cargo computer")
    if not current or current.ped~=r.ped then cargo_finish(false,err or "Player changed.");return end
    local free=invoke_int(0xFEAD16FC8F9DFC0F,8344)
    if not free or free<1 then cargo_finish(false,"No GTA app script stack is available.");return end
    r.start_frame=invoke_int(0xFC8202EFC642E6F2)
    if not r.start_frame then cargo_finish(false,"Render clock unavailable.");return end
    local prepared,why=warehouse_bootstrap(r,false)
    if prepared then prepared,why=cargo_bootstrap(r,false) end
    if not prepared then cargo_finish(false,why);return end
    r.thread=invoke_int(0xE81651AD79516E48,"appsecuroserv",8344)
    if not r.thread or r.thread<=0 then cargo_finish(false,"GTA rejected the CEO computer launch.") end
end

local function snapshot()
    local selected = find_location()
    return {
        status = State.status or "PENDING", path = State.path, last_error = State.last_error,
        cargo_result = State.cargo_result, destination_result = State.last_destination_result, destination_pending = State.pending_destination ~= nil,
        last_action_error = State.last_action_error, categories = CATEGORIES,
        locations = copy_locations(State.locations), selected_id = State.selected_id,
        selected = selected and copy_location(selected) or nil,
        destinations = DESTINATIONS, destination_intelligence = State.destination_intelligence or { status="REFRESH_REQUIRED", items={}, ready=0, ambiguous=0, absent=0, total=#DESTINATIONS },
        current = State.current and {
            x = State.current.coords.x, y = State.current.coords.y, z = State.current.coords.z,
            heading = State.current.heading, interior = State.current.interior,
        } or nil,
        maximum = MAX_LOCATIONS,
        can_return = type(State.return_location) == "table",
        return_location = type(State.return_location) == "table" and {
            x = State.return_location.x, y = State.return_location.y, z = State.return_location.z,
            heading = State.return_location.heading, interior = State.return_location.interior,
        } or nil,
    }
end

