local function binding(name)
    local raw = context_ref and context_ref.Raw
    if raw and raw[name] ~= nil then return raw[name] end
    -- Bundled modules use an isolated environment whose __index resolves the
    -- Cherax globals. A raw lookup would bypass that compatibility boundary.
    return type(_G) == "table" and _G[name] or nil
end

local function call_native(method, hash, ...)
    local natives = binding("Natives")
    local callback = natives and natives[method]
    if type(callback) ~= "function" then return false, method .. " is unavailable" end
    local ok, a, b, c = pcall(callback, hash, ...)
    if not ok then return false, tostring(a) end
    return true, a, b, c
end

local function invoke_void(hash, ...)
    local ok, err = call_native("InvokeVoid", hash, ...)
    return ok and err ~= false, err
end

local function invoke_int(hash, ...)
    local ok, value = call_native("InvokeInt", hash, ...)
    return ok and tonumber(value) or nil
end

local function invoke_float(hash, ...)
    local ok, value = call_native("InvokeFloat", hash, ...)
    return ok and tonumber(value) or nil
end

local function invoke_bool(hash, ...)
    local ok, value = call_native("InvokeBool", hash, ...)
    return ok and value == true
end

local function invoke_vec3(hash, ...)
    local ok, value, y, z = call_native("InvokeV3", hash, ...)
    if not ok then return nil end
    if type(value) == "number" and type(y) == "number" and type(z) == "number" then
        return { x = value, y = y, z = z }
    end
    return value
end

local function vector_components(value)
    local kind = type(value)
    if kind ~= "table" and kind ~= "userdata" then return nil end
    local ok, x, y, z = pcall(function()
        return tonumber(value.x or value.X or value[1]),
            tonumber(value.y or value.Y or value[2]),
            tonumber(value.z or value.Z or value[3])
    end)
    if not ok or not (x and y and z) then return nil end
    if x ~= x or y ~= y or z ~= z or math.abs(x) > 10000 or math.abs(y) > 10000 or math.abs(z) > 5000 then
        return nil
    end
    return x, y, z
end

local function distance_sq(left, right)
    local lx, ly, lz = vector_components(left)
    local rx, ry, rz = vector_components(right)
    if not (lx and rx) then return nil end
    local dx, dy, dz = lx - rx, ly - ry, lz - rz
    return dx * dx + dy * dy + dz * dz
end

local function entity_exists(handle)
    return type(handle) == "number" and handle > 0 and invoke_bool(H.DOES_ENTITY_EXIST, handle)
end

local function entity_model(handle)
    local value = invoke_int(H.GET_ENTITY_MODEL, handle)
    return value and (value & 0xFFFFFFFF) or 0
end

local function local_player_id()
    local gta = binding("GTA")
    if gta and type(gta.GetLocalPlayerId) == "function" then
        local ok, value = pcall(gta.GetLocalPlayerId)
        value = ok and tonumber(value) or nil
        if value and value >= 0 and value <= 31 then return value end
    end
    return nil
end

