-- UI requests are queued here; the existing teleport scheduler runs the trip.
local running,pending,busy,generation,last_now,invalidated=false,false,false,0,nil,false
local last={status='IDLE',message=''}
local session_registered=false
local OWNER,EVENT_KEY='modules.teleport_manager','restored_kosatka_session'
local function publish(event)
    if not event then return end
    last={status=tostring(event.status or 'PENDING'),message=tostring(event.message or '')}
    if last.status=='COMPLETE' or last.status=='FAILED' or last.status=='CANCELLED' then busy=false end
    local notices=context_ref and context_ref.Notifications
    local level=last.status=='COMPLETE' and 'Success' or last.status=='FAILED' and 'Warning' or 'Info'
    if notices and type(notices[level])=='function' and last.message~='' then
        pcall(notices[level],last.message)
    end
end
local api={}
function api.Bind(context)
    context_ref=context
    local events=context and context.Events
    if events and type(events.RegisterSessionChange)=='function' then
        session_registered=events.RegisterSessionChange(OWNER,EVENT_KEY,function()
            generation=generation+1
            invalidated=true
        end)==true
    end
end
function api.SetStarted(value) running=value==true end
function api.Active() return pending or busy end
function api.Snapshot()
    return {status=last.status,message=last.message,pending=api.Active()}
end
function api.Request()
    if not running then return false,'Teleport service is stopped.' end
    if not session_registered then return false,'Kosatka session lifecycle is unavailable.' end
    if invalidated then return false,'Wait for the session transition to finish.' end
    if api.Active() then return false,'A Kosatka trip is already in progress.' end
    pending=true
    last={status='QUEUED',message='Kosatka teleport queued.'}
    return true,last.message
end
function api.Cancel(reason)
    local had_work=pending or busy
    pending=false;generation=generation+1
    if kosatka_flow then
        local ok,event=pcall(kosatka_flow.Cancel,reason or 'Kosatka trip cancelled.')
        if ok then publish(event)else publish({status='FAILED',message=tostring(event)})end
    end
    busy=false
    if had_work and last.status~='FAILED' and last.status~='CANCELLED' then
        publish({status='CANCELLED',message=reason or 'Kosatka trip cancelled.'})
    end
    return had_work
end
function api.Tick(now)
    if invalidated then invalidated=false;api.Cancel('Kosatka trip cancelled: session changed.');return end
    if not running or not api.Active() then return end
    now=tonumber(now)
    if not now or now~=now or now<0 or now==math.huge then
        api.Cancel('Kosatka trip stopped: clock unavailable.');return
    end
    if last_now and now<last_now then api.Cancel('Kosatka trip stopped: clock changed.');last_now=now;return end
    last_now=now
    if pending then
        pending=false
        kosatka_flow=kosatka_flow or Module.NewKosatkaFlow(kosatka_host())
        local called,accepted,event=pcall(kosatka_flow.Start,generation,now)
        if not called or not accepted then
            busy=false
            publish({status='FAILED',message=tostring(called and event or accepted)})
        else busy=true;publish(event)end
        return
    end
    local ok,event=pcall(kosatka_flow.Tick,now,generation)
    if not ok then
        api.Cancel('Kosatka trip stopped after a host error.')
        publish({status='FAILED',message=tostring(event)})
    else publish(event)end
end
function api.Unbind()
    api.Cancel('CScript unloaded.')
    running=false
    local events=context_ref and context_ref.Events
    if session_registered and events and type(events.Unregister)=='function' then
        events.Unregister(OWNER,EVENT_KEY)
    end
    session_registered=false;kosatka_flow=nil;context_ref=nil
end
return api
end)()
-- END RESTORED KOSATKA TRAVEL

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table" or type(context.CScript) ~= "table" then
        error("modules.teleport_manager received an invalid context")
    end
    module_context = context
    KosatkaTravel.Bind(context)
    State = context.State.Teleports or {}
    context.State.Teleports = State
    State.locations, State.status, State.sequence, State.return_location, State.destination_intelligence = {}, "PENDING", 0, nil, nil
    State.pending_destination, State.last_destination_result = nil, nil
    board_trip=nil
    State.heist_board_prompt,State.heist_board_prompt_requested,State.heist_board_prompt_next=nil,nil,nil
    public_api = {
        OpenCargoComputer = open_cargo_computer, OpenWarehouseComputer = open_warehouse_computer, DrainUnload = drain_cargo, Snapshot = snapshot, Tick = function(now)
            -- UI only queues this trip. The existing gameplay tick owns travel.
            if KosatkaTravel.Active() and (State.pending_destination or State.cargo_request
                or board_trip and board_trip.Active()) then
                KosatkaTravel.Cancel("Another travel request started.")
            end
            KosatkaTravel.Tick(now)
            tick_destination(now)
            tick_board_trip(now)
            tick_cargo_computer(now)
            tick_heist_board_prompt(now or 0)
            if started and now and now<=(State.visible_until_ms or -1) and now>=(State.next_visible_refresh_ms or 0) then
                State.next_visible_refresh_ms=now+5000
                refresh_destination_intelligence()
            end
        end,
        RequestVisibleRefresh=function()
            local time=module_context and module_context.Raw and module_context.Raw.Utils
            local now=time and type(time.GetTime)=="function" and time.GetTime()*1000 or (os.clock()*1000)
            State.visible_until_ms=now+1500
        end,
        RequestHeistBoardPromptRefresh=function(family)
            if State.heist_board_prompt and State.heist_board_prompt.family~=family then State.heist_board_prompt=nil end
