    return false
end

function Presentation.retired_reference(reference)
    local value = tostring(reference or "")
    if Presentation.is_retired(value) then return value end
    -- Match the complete logical key; greedy underscore matching loses the
    -- double-underscore boundary and can redirect legacy routes incorrectly.
    if value:find("feature__", 1, true) == 1 then
        for candidate in pairs(Presentation.retired) do
            if value:sub(- #candidate - 2) == "__" .. candidate then return candidate end
        end
    end
end

