    CATEGORY_BY_KEY[category.key] = category
    CATEGORY_KEYS[index] = category.key
end

-- Only page destinations are retained. Feature discovery, indexing and
-- quick-access routes have been removed; gameplay controls render in-place.
local ROUTE_BY_ID = {}
local PAGE_ROUTE_BY_CONTEXT = {}
local function route_part(value)
    local part = tostring(value or "route"):gsub("[^%w_]", "_"):gsub("_+", "_")
        :gsub("^_+", ""):gsub("_+$", "")
    return part ~= "" and part or "route"
end
local function page_context_id(category_key, page_name)
    return tostring(category_key or "") .. "\0" .. tostring(page_name or "")
end
local function page_route_id(category_key, page_name)
    return "page__" .. route_part(category_key) .. "__" .. route_part(page_name)
end
for _, category in ipairs(UI_SCHEMA) do
    for _, page in ipairs(category.pages or {}) do
        local id = page_route_id(category.key, page.name)
        ROUTE_BY_ID[id] = {
            route_id = id,
            category_key = category.key,
            page = page.name,
            context = category.key .. " > " .. page.name
        }
        PAGE_ROUTE_BY_CONTEXT[page_context_id(category.key, page.name)] = id
    end
end

local function log_error_once(key, message)
    if not module_context then return end
    key, message = tostring(key), tostring(message):sub(1, 4096)
    if State then
        State.render_errors = State.render_errors or {}
        local previous = State.render_errors[key]
        if previous then
            previous.repeats = math.min(1000000, previous.repeats + 1); return
        end
        State.render_error_count = State.render_error_count or 0
        if State.render_error_count >= 24 then return end
        local item = {
            key = key,
            message = message,
            repeats = 0,
            category = State.selected_category_key,
            context = State.render_context,
            selected_player = State.players_selected
        }
        State.render_errors[key] = item; State.render_error_count = State.render_error_count + 1
        State.first_render_error = State.first_render_error or item
        message = ("context=%s category=%s player=%s: %s"):format(
            tostring(item.context), tostring(item.category), tostring(item.selected_player), message)
    end
    local logger = module_context.Logger
    if logger and type(logger.ErrorOnce) == "function" then
        pcall(logger.ErrorOnce, "ui_" .. key, message, "UI")
    end
    local runtime = module_context.CScript and module_context.CScript.Runtime
    if runtime and type(runtime.RecordTestEvent) == "function" then
        pcall(runtime.RecordTestEvent, "FAILED", "UI", key, "render", message)
    end
end

local function compat_ui()
    if type(public_api) == "table" then return public_api end
    return nil
end

local function feature_id(key)
    local api = compat_ui()
    return api and api.FeatureId and api.FeatureId(key) or nil
end

local function player_feature_id(key)
    local api = compat_ui()
    return api and api.PlayerFeatureId and api.PlayerFeatureId(key) or nil
end

local function ui_spacing(count)
    if not (ImGui and type(ImGui.Spacing) == "function") then return end
    for _ = 1, count or 1 do pcall(ImGui.Spacing) end
end

local function imgui_clicked(method, ...)
    if not (ImGui and type(ImGui[method]) == "function") then return false end
    local ok, clicked = pcall(ImGui[method], ...)
    return ok and clicked == true
end

local function input_byte_cap(value, maximum)
    local text=tostring(value or "")
    local limit=tonumber(maximum) or 64
    if limit~=limit or math.abs(limit)==math.huge then limit=64 end
    limit=math.max(0,math.floor(limit))
    if #text<=limit then return text end
    -- Never leave a partial UTF-8 code point at the byte limit.
    while limit>0 do
        local next_byte=text:byte(limit+1)
        if not next_byte or next_byte<128 or next_byte>191 then break end
        limit=limit-1
    end
    return text:sub(1,limit)
end

local function input_text(label, current, maximum)
    local before=input_byte_cap(current,maximum)
    if not (ImGui and type(ImGui.InputText) == "function") then return before end
    -- Cherax's final argument is ImGuiInputTextFlags, not a buffer length.
    local ok, first, second = pcall(ImGui.InputText, label, before, 0)
    if not ok then return before end
    if type(first) == "string" then return input_byte_cap(first,maximum) end
    if first == true and type(second) == "string" then return input_byte_cap(second,maximum) end
    return before
end

local function input_text_with_hint(label, hint, current, maximum)
    if not (ImGui and type(ImGui.InputTextWithHint) == "function") then
        return input_text(label, current, maximum)
    end
    local ok, first, second = pcall(ImGui.InputTextWithHint, label, tostring(hint or ""),
        input_byte_cap(current,maximum), 0)
    if not ok then return input_text(label, current, maximum) end
    if type(first) == "string" then return input_byte_cap(first,maximum) end
    if first == true and type(second) == "string" then return input_byte_cap(second,maximum) end
    return input_byte_cap(current,maximum)
end

local function user_copy(value, kind, fallback)
    local copy = module_context and module_context.Core and module_context.Core.PresentationCopy
    return copy and copy.Message(value, kind, fallback) or tostring(value or "")
end

local function feature_help(label, original)
    local copy = module_context and module_context.Core and module_context.Core.PresentationCopy
    return copy and copy.Description(tostring(label or ""):gsub("%s+>%s*$", ""), original) or original
end

local function ui_text(value, disabled)
    if not ImGui then return end
    value = user_copy(value)
    local method = disabled and ImGui.TextDisabled or ImGui.Text
    if type(method) == "function" then pcall(method, tostring(value or "")) end
end

local function ui_same_line()
    if ImGui and type(ImGui.SameLine) == "function" then pcall(ImGui.SameLine) end
end

local active_column_layout

local function resolve_layout_capabilities()
    if UI_CAPABILITIES.resolved then return UI_CAPABILITIES end
    UI_CAPABILITIES.tables = ImGui ~= nil
        and type(ImGui.BeginTable) == "function"
        and type(ImGui.TableSetupColumn) == "function"
        and type(ImGui.TableNextRow) == "function"
        and type(ImGui.TableSetColumnIndex) == "function"
        and type(ImGui.EndTable) == "function"
    UI_CAPABILITIES.resolved = true
    return UI_CAPABILITIES
end

local function clean_id(value)
    return tostring(value or "component"):gsub("[^%w_]", "_")
end

local function trace_ui_event(status, label, action, detail)
    local runtime = module_context and module_context.CScript and module_context.CScript.Runtime
    if runtime and type(runtime.RecordTestEvent) == "function" then
        pcall(runtime.RecordTestEvent, status, "UI", tostring(label or "Control"),
            tostring(action or "interaction"), tostring(detail or ""))
    end
end

local function content_region()
    if not (ImGui and type(ImGui.GetContentRegionAvail) == "function") then return 0, 0 end
    local ok, width, height = pcall(ImGui.GetContentRegionAvail)
    if not ok then return 0, 0 end
    return math.max(0, tonumber(width) or 0), math.max(0, tonumber(height) or 0)
end

local function measured_text_width(value)
    value = tostring(value or "")
    if ImGui and type(ImGui.CalcTextSize) == "function" then
        local ok, width = pcall(ImGui.CalcTextSize, value)
        if ok and tonumber(width) then return tonumber(width) end
    end
    return #value * 7
end

local function component_minimum_width(label, kind)
    local available = select(1, content_region())
    local compact = available > 0 and available <= STUDIO_COMPACT_MAX_WIDTH
    local floor = kind == "icon" and (compact and 30 or 34)
        or kind == "chip" and (compact and 44 or 60)
        or (compact and 76 or 92)
    return math.max(floor, measured_text_width(label) + (kind == "chip" and 14 or (compact and 20 or 30)))
end

function CScriptUI.available_content()
    return content_region()
end

function CScriptUI.studio_breakpoint(width)
    width = math.max(0, tonumber(width) or select(1, content_region()))
    if width <= STUDIO_COMPACT_MAX_WIDTH then return "compact" end
    if width <= STUDIO_MEDIUM_MAX_WIDTH then return "medium" end
    return "wide"
end

function CScriptUI.studio_layout()
    local width, height = content_region()
    local breakpoint = CScriptUI.studio_breakpoint(width)
    -- One editor surface with a compact selector. Do not reserve empty sidebar
    -- or preview columns, or force a taller child inside the Cherax page.
    return width, height, breakpoint, { 100 }, math.max(0, math.min(560, math.floor(height)))
end

-- Camera leases are claimed by studio native-thread updates, never by render.
-- A handoff requires the old owner to finish releasing its own resources.
local studio_camera = { generation = 0, lease = nil, handing_off = false }
local studio_scroll = {}
local studio_present_generation, studio_visible = 0, {}
local studio_visibility_diagnostics, studio_host_tab = {}, nil

function CScriptUI.studio_presentation_frame()
    studio_present_generation = studio_present_generation + 1
    if ClickGUI and type(ClickGUI.GetActiveMenuTab)=="function" then
        local ok,value=pcall(ClickGUI.GetActiveMenuTab)
        studio_host_tab=ok and tostring(value) or "unavailable"
    end
end

function CScriptUI.studio_workspace_touch(owner)
    if owner == "outfit" or owner == "vehicle" then studio_visible[owner] = studio_present_generation end
end

-- This bridge consumes cached presentation state; no ImGui calls on gameplay.
-- Wall-clock hitches do not mean the studio disappeared. Two frame tolerance
-- allows either host callback ordering while noticing a different custom tab.
function CScriptUI.studio_workspace_visible(owner)
    local seen=studio_visible[owner]
    local detail={owner=owner,present_generation=studio_present_generation,last_touch_generation=seen,
        gap=seen and studio_present_generation-seen or nil,host_tab=studio_host_tab,
        category=State and State.selected_category_key,page=State and State.selected_page_name}
    local function result(visible,reason)
        detail.visible=visible;detail.reason=reason
        local previous=studio_visibility_diagnostics[owner]
        studio_visibility_diagnostics[owner]=detail
        if visible==false and (not previous or previous.visible~=false)
            and dependencies and type(dependencies.log_info)=="function" then
            pcall(dependencies.log_info,("StudioVisibility owner=%s visible=false reason=%s gap=%s hostTab=%s category=%s page=%s")
                :format(tostring(owner),reason,tostring(detail.gap),tostring(detail.host_tab),tostring(detail.category),tostring(detail.page)))
        end
        return visible
    end
    if GUI and type(GUI.IsOpen) == "function" then
        local ok, open = pcall(GUI.IsOpen)
        detail.menu_open=ok and type(open)=="boolean" and open or nil
        if ok and open == false then detail.menu_open=false;return result(false,"menu_closed") end
    end
    if State then
        local category, page = owner == "outfit" and "Player" or "Vehicle",
            owner == "outfit" and "Outfit Studio" or "Studio"
        if State.selected_category_key ~= category or State.selected_page_name ~= page then return result(false,"page_changed") end
        if State.tab_render_blocked then return result(false,"tab_render_blocked") end
        if State.page_render_failure then return result(false,"page_render_failure") end
    end
    if seen == nil or studio_present_generation == 0 then return result(nil,"not_presented") end
    local visible=studio_present_generation-seen<=2
    return result(visible,visible and "recent_touch" or "presentation_gap")
end

function CScriptUI.studio_visibility_snapshot(owner)
    local copy={};for key,value in pairs(studio_visibility_diagnostics[owner] or {}) do copy[key]=value end
    return copy
end

local function publish_studio_camera_owner(owner)
    CScriptUI.PreviewCameraOwner = owner
    if module_context and module_context.State and module_context.State.UI then
        module_context.State.UI.PreviewCameraOwner = owner
    end
end

function CScriptUI.owns_studio_camera(owner, generation)
    local lease = studio_camera.lease
    return lease ~= nil and lease.owner == owner and lease.generation == generation
end

-- Cached ownership only: protections may inspect this from their native tick
-- without peeking at studio internals or treating every script camera as abuse.
function CScriptUI.studio_camera_snapshot()
    local lease = studio_camera.lease
    return {
        active = lease ~= nil,
        owner = lease and lease.owner or nil,
        generation = lease and lease.generation or studio_camera.generation,
        handing_off = studio_camera.handing_off == true
    }
end

function CScriptUI.release_studio_camera(owner, generation)
    if not CScriptUI.owns_studio_camera(owner, generation) then return false end
    studio_camera.lease = nil
    publish_studio_camera_owner(nil)
    return true
end

function CScriptUI.stop_studio_camera(reason)
    local lease = studio_camera.lease
    if not lease then return true end
    if studio_camera.handing_off then return false end
    studio_camera.handing_off = true
    local ok, released = pcall(lease.release, tostring(reason or "studio closed"))
    studio_camera.handing_off = false
    if not ok or released ~= true then
        -- Retain ownership even when a failed callback prematurely released its
        -- token. Another studio must not take over a camera with cleanup debt.
        if studio_camera.lease == nil then studio_camera.lease = lease end
        publish_studio_camera_owner(lease.owner)
        return false
    end
    if studio_camera.lease == lease then studio_camera.lease = nil end
    publish_studio_camera_owner(studio_camera.lease and studio_camera.lease.owner or nil)
    return true
end

function CScriptUI.claim_studio_camera(owner, release)
    if (owner ~= "outfit" and owner ~= "vehicle" and owner ~= "vehicle_effect") or type(release) ~= "function"
        or studio_camera.handing_off then
        return nil
    end
    local lease = studio_camera.lease
    if lease and lease.owner == owner then return lease.generation end
    if lease and not CScriptUI.stop_studio_camera("studio switch") then return nil end
    studio_camera.generation = studio_camera.generation + 1
    studio_camera.lease = { owner = owner, generation = studio_camera.generation, release = release }
    publish_studio_camera_owner(owner)
    return studio_camera.generation
end

-- Choose the largest usable uncovered rectangle for framing and gesture start.
-- A captured right drag can subsequently cross the menu without losing orbit.
function CScriptUI.studio_viewport()
    local fallback = { center_x = 0.5, center_y = 0.5, width_fraction = 1, height_fraction = 1, pointer_region = false }
    if not ImGui or type(ImGui.GetDisplaySize) ~= "function" then return fallback end
    local ok, result = pcall(function()
        local function finite(value)
            return type(value) == "number" and value == value and math.abs(value) < math.huge
        end
        local screen_width, screen_height = ImGui.GetDisplaySize()
        if not finite(screen_width) or not finite(screen_height)
            or screen_width <= 0 or screen_height <= 0 then
            return fallback
        end
        local function rectangle(api, position, size)
            if not api or type(api[position]) ~= "function" or type(api[size]) ~= "function" then return nil end
            local pos_ok, x, y = pcall(api[position])
            local size_ok, width, height = pcall(api[size])
            if not pos_ok or not size_ok or not finite(x) or not finite(y)
                or not finite(width) or not finite(height) or width <= 0 or height <= 0
                or x >= screen_width or x + width <= 0 or y >= screen_height or y + height <= 0 then
                return nil
            end
            return { x = x, y = y, width = width, height = height }
        end
        -- ClickGUI includes Cherax's navigation rail and border. ImGui's current
        -- window can be the inset Lua child, which shifts the uncovered midpoint.
        -- Both outer geometry getters are documented Cherax screen-coordinate APIs.
        local outer_bounds = rectangle(ClickGUI, "GetPos", "GetSize")
        local bounds = outer_bounds or rectangle(ImGui, "GetWindowPos", "GetWindowSize")
        if not bounds then return fallback end
        local left = math.max(0, math.min(screen_width, bounds.x))
        local right = math.max(0, math.min(screen_width, bounds.x + bounds.width))
        local top = math.max(0, math.min(screen_height, bounds.y))
        local bottom = math.max(0, math.min(screen_height, bounds.y + bounds.height))
        local region, area
        for _, candidate in ipairs({
            { x = 0,   y = 0,    width = left,             height = screen_height },
            { x = right, y = 0,  width = screen_width - right, height = screen_height },
            { x = 0,   y = 0,    width = screen_width,     height = top },
            { x = 0,   y = bottom, width = screen_width,   height = screen_height - bottom },
        }) do
            local size = candidate.width * candidate.height
            if candidate.width / screen_width >= 0.25 and candidate.height / screen_height >= 0.25
                and (not area or size > area) then
                region, area = candidate, size
            end
        end
        if not region then return fallback end
        return {
            center_x = (region.x + region.width * 0.5) / screen_width,
            center_y = (region.y + region.height * 0.5) / screen_height,
            width_fraction = region.width / screen_width,
            height_fraction = region.height / screen_height,
            aspect = screen_width / screen_height,
            screen_width = screen_width,
            screen_height = screen_height,
            x = region.x,
            y = region.y,
            width = region.width,
            height = region.height,
            pointer_region = outer_bounds ~= nil
        }
    end)
    return ok and result or fallback
end

-- Presentation captures pointer eligibility and pixel deltas only. Wheel natives
-- are read separately on the owning studio's verified gameplay frame.
local studio_pointer = {}
local function studio_finite(value)
    return type(value) == "number" and value == value and math.abs(value) < math.huge
end
local function studio_input_clock()
    if Time and type(Time.GetEpocheMs) == "function" then
        local ok, value = pcall(Time.GetEpocheMs)
        if ok and studio_finite(value) then return value end
    end
    return nil -- CPU time cannot prove a wall-clock input freshness deadline.
end
function CScriptUI.studio_camera_input(owner, enabled)
    local viewport = CScriptUI.studio_viewport()
    local input = { orbit_x = 0, orbit_y = 0, zoom_steps = 0, wheel = 0, interacting = false, viewport = viewport }
    local previous = studio_pointer[owner]
    if owner ~= "outfit" and owner ~= "vehicle" then return input end
    local lease = studio_camera.lease
    if enabled ~= true or not lease or lease.owner ~= owner or studio_camera.handing_off
        or not viewport.pointer_region or not ImGui then
        studio_pointer[owner] = nil; return input
    end
    local ok, x, y, down, frame = pcall(function()
        -- Clicking the world preview can unfocus the Lua child. The open host
        -- menu is the authoritative workspace gate when its API is available.
        local host_open
        if GUI and type(GUI.IsOpen) == "function" then host_open = GUI.IsOpen() end
        if (host_open ~= true and not ImGui.IsWindowFocused(ImGuiFocusedFlags and ImGuiFocusedFlags.RootAndChildWindows or 3))
            or host_open == false
            or (type(ImGui.IsAnyItemActive) == "function" and ImGui.IsAnyItemActive())
            or (type(ImGui.IsPopupOpen) == "function" and ImGui.IsPopupOpen("", 384)) then
            return nil
        end
        local mx, my = ImGui.GetMousePos()
        return mx, my, ImGui.IsMouseDown(1), ImGui.GetFrameCount()
    end)
    local now = studio_input_clock()
    if not ok or not studio_finite(x) or not studio_finite(y) or not studio_finite(frame)
        or frame < 0 or frame % 1 ~= 0 or not studio_finite(now)
        or x < 0 or x >= viewport.screen_width or y < 0 or y >= viewport.screen_height then
        studio_pointer[owner] = nil; return input
    end
    -- A repeated render must not duplicate a drag or make wheel polling eligible twice.
    if previous and previous.frame == frame and previous.generation == lease.generation then return input end
    local same_gesture = previous and previous.generation == lease.generation and frame > previous.frame
    local continuous = same_gesture
        and now >= previous.time and now - previous.time <= 150
    local hovered = x >= viewport.x and x < viewport.x + viewport.width and y >= viewport.y and
    y < viewport.y + viewport.height
    local captured = down == true and ((same_gesture and previous.captured == true)
        or (hovered and (not previous or previous.down ~= true)))
    if continuous and captured and previous.captured == true then
        input.orbit_x = math.max(-320, math.min(320, x - previous.x))
        input.orbit_y = math.max(-320, math.min(320, y - previous.y))
        input.interacting = input.orbit_x ~= 0 or input.orbit_y ~= 0
    end
    studio_pointer[owner] = {
        x = x,
        y = y,
        down = down == true,
        captured = captured,
        hovered = hovered,
        frame = frame,
        time = now,
        generation = lease.generation,
        elapsed = continuous and math.min(0.05, (now - previous.time) / 1000) or 0,
        edge_x = captured and input.orbit_x == 0 and (x <= 1 and -1 or x >= viewport.screen_width - 2 and 1 or 0) or 0,
        edge_y = captured and input.orbit_y == 0 and (y <= 1 and -1 or y >= viewport.screen_height - 2 and 1 or 0) or 0
    }
    return input
end

-- A physical cursor cannot move beyond the display. Continue an already-owned
-- drag at that edge, using relative PAD look axes where the host exposes them.
-- The fallback is time-scaled edge orbit, never a replay of the previous delta.
function CScriptUI.studio_camera_motion(owner)
    local pointer, lease = studio_pointer[owner], studio_camera.lease
    local now = studio_input_clock()
    if not pointer or not lease or lease.owner ~= owner or pointer.generation ~= lease.generation
        or not pointer.captured or pointer.motion_read or studio_camera.handing_off
        or not studio_finite(now) or now < pointer.time or now - pointer.time > 150 then
        return 0, 0
    end
    pointer.motion_read = true
    local function axis(edge, control)
        if edge == 0 then return 0 end
        if dependencies and type(dependencies.invoke_float) == "function" then
            local ok, value = pcall(dependencies.invoke_float, 0x4F8A26A890FD62FB, 0, control)
            if ok and studio_finite(value) and math.abs(value) > 0.00001 then
                return math.max(-80, math.min(80, value * 320))
            end
        end
        return edge * 180 * pointer.elapsed
    end
    return axis(pointer.edge_x, 1), axis(pointer.edge_y, 2)
end

function CScriptUI.studio_camera_wheel(owner)
    local pointer, lease = studio_pointer[owner], studio_camera.lease
    local now = studio_input_clock()
    if not pointer or not lease or lease.owner ~= owner or pointer.generation ~= lease.generation
        or (not pointer.hovered and not pointer.captured) or studio_camera.handing_off
        or not studio_finite(now) or now < pointer.time or now - pointer.time > 150
        or pointer.wheel_read == true or not dependencies or type(dependencies.invoke_bool) ~= "function" then
        return 0
    end
    local function pressed(control)
        local normal_ok, normal = pcall(dependencies.invoke_bool, 0x580417101DDB492F, 0, control)
        local disabled_ok, disabled = pcall(dependencies.invoke_bool, 0x91AEF906BCA88877, 0, control)
        return (normal_ok and normal == true) or (disabled_ok and disabled == true)
    end
    local up, down = pressed(241), pressed(242)
    if up or down then pointer.wheel_read = true end
    return (up and 1 or 0) - (down and 1 or 0)
end

function CScriptUI.reset_studio_input()
    studio_pointer = {}
end

function CScriptUI.studio_workspace_scroll(id, workspace, category, subject)
    if not ImGui or type(ImGui.GetScrollY) ~= "function" or type(ImGui.SetScrollY) ~= "function" then return end
    local key = tostring(workspace) .. ":" .. tostring(category) .. ":" .. tostring(subject)
    local state = studio_scroll[id] or { positions = {} }
    studio_scroll[id] = state
    local ok, position = pcall(ImGui.GetScrollY)
    if not ok or type(position) ~= "number" then return end
    if state.key ~= key then
        if state.key then state.positions[state.key] = math.max(0, position) end
        -- Positions are UI-only. Bound the cache when subjects change often.
        if state.count and state.count > 64 then state.positions, state.count = {}, 0 end
        state.count = (state.count or 0) + 1
        state.key = key
        pcall(ImGui.SetScrollY, state.positions[key] or 0)
    else
        state.positions[key] = math.max(0, position)
    end
end

local studio_body_depth = 0
function CScriptUI.studio_workspace_body(id, workspace, subject, renderer)
    if type(renderer) ~= "function" then return false end
    local width, height = content_region()
    -- The header/view/category stay outside this one scrolling region. Reserve
    -- trailing item spacing so the child cannot create a second parent scroll.
    -- Very small/unsupported hosts retain a usable natural-layout fallback.
    if studio_body_depth > 0 or width <= 0 or height < 80 or not ImGui
        or type(ImGui.BeginChild) ~= "function" or type(ImGui.EndChild) ~= "function" then
        renderer()
        return true
    end
    local begun, visible = pcall(ImGui.BeginChild, "##studio_body_" .. clean_id(id),
        0, math.max(1, math.floor(height - 8)), false, 0)
    if not begun then
        State.tab_render_blocked = true
        log_error_once("studio_begin", visible)
        error("Studio BeginChild failed; unload and reload CScript: " .. tostring(visible), 0)
    end
    studio_body_depth = studio_body_depth + 1
    local ok, err = pcall(function()
        if visible ~= false then
            CScriptUI.surface()
            CScriptUI.studio_workspace_scroll("body_" .. clean_id(id), workspace, "body", subject)
            renderer()
        end
    end)
    if State and State.tab_render_blocked then error(err or "Native UI scope uncertain; unload and reload CScript.", 0) end
    local ended, end_error = pcall(ImGui.EndChild)
    studio_body_depth = studio_body_depth - 1
    if not ended then
        State.tab_render_blocked = true
        log_error_once("studio_end", end_error)
        error("Studio EndChild failed; unload and reload CScript: " .. tostring(end_error), 0)
    end
    if not ok then error(err, 0) end
    return true
end

function CScriptUI.button_width(label, kind)
    return component_minimum_width(tostring(label or ""), tostring(kind or "secondary"))
end

function CScriptUI.row_can_pair(required_width)
    local width = select(1, content_region())
    return width >= (tonumber(required_width) or 250)
end

function CScriptUI.tooltip(message)
    message = user_copy(message)
    message = tostring(message or ""):gsub("[\r\n]+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    if message == "" or not ImGui or type(ImGui.IsItemHovered) ~= "function"
        or (type(ImGui.SetTooltip) ~= "function"
            and not (type(ImGui.BeginTooltip) == "function" and type(ImGui.EndTooltip) == "function"
                and type(ImGui.TextWrapped) == "function")) then
        return false
    end
    local ok, hovered = pcall(ImGui.IsItemHovered)
    if ok and hovered == true then
        if type(ImGui.BeginTooltip) == "function" and type(ImGui.EndTooltip) == "function"
            and type(ImGui.TextWrapped) == "function" then
            local began = pcall(ImGui.BeginTooltip)
            if began then
                local wrapped = type(ImGui.PushTextWrapPos) == "function"
                    and pcall(ImGui.PushTextWrapPos, 420) or false
                pcall(ImGui.TextWrapped, message)
                if wrapped and type(ImGui.PopTextWrapPos) == "function" then pcall(ImGui.PopTextWrapPos) end
                pcall(ImGui.EndTooltip)
            end
        else
            pcall(ImGui.SetTooltip, message)
        end
        return true
    end
    return false
end

function CScriptUI.section(title, subtitle)
    ui_spacing(1)
    ui_text(tostring(title or "SECTION"):upper())
    if subtitle and tostring(subtitle) ~= "" then
        CScriptUI.tooltip(subtitle)
        -- Explanations belong in hover help, never as automatic debug text.
    end
    if ImGui and type(ImGui.Separator) == "function" then pcall(ImGui.Separator) end
end

-- Geometry is measured from the content, never from estimated row counts.
-- Cache only the underlay height: the current-frame border always follows the
-- actual group. This keeps cards in one scrolling page, without nested children.
CScriptUI._card_geometry = {}
-- Animated accents are presentation-only. Never alter Cherax's global style
-- stack or host tab colors; those belong to the menu, not to CScript.
local function cscript_gloss_phase()
    if ImGui and type(ImGui.GetTime)=="function" then
        local ok, seconds=pcall(ImGui.GetTime)
        if ok and type(seconds)=="number" and seconds==seconds then
            return (seconds * 0.12) % 1.0
        end
    end
    return 0.5
end
function CScriptUI.card(id, title, subtitle, renderer, height)
    ui_spacing(1)
    local key = clean_id(id)
    local is_dashboard = tostring(id):sub(1,10) == "dashboard_"
    local width = select(1, content_region())
    local x, y
    if ImGui and type(ImGui.GetCursorScreenPos) == "function" then
        local ok, px, py = pcall(ImGui.GetCursorScreenPos)
        if ok then x, y = tonumber(px), tonumber(py) end
    end
    local previous = CScriptUI._card_geometry[key]
    if x and y and width > 0 and type(ImGui.AddRectFilled) == "function" then
        local h = previous and previous.width == width and previous.height or 32
        local r,g,b = is_dashboard and 8 or 12, is_dashboard and 10 or 11, is_dashboard and 13 or 18
        pcall(ImGui.AddRectFilled, x, y, x + width, y + h, r,g,b, 250, 5)
        -- The reference uses precise separators rather than full-panel bloom.
        pcall(ImGui.AddRectFilled, x+2, y+2, x+width-2, y+3,
            95, 51, 142, is_dashboard and 130 or 70, 0)
    end
    local function scope(fn, ...)
        local ok, err = pcall(fn, ...)
        if not ok then
            if State then State.tab_render_blocked = true end
            error("Card scope failed; unload and reload CScript: " .. tostring(err), 0)
        end
    end
    local grouped = ImGui and type(ImGui.BeginGroup) == "function" and type(ImGui.EndGroup) == "function"
    if grouped then scope(ImGui.BeginGroup) end
    local padded = grouped and type(ImGui.Indent) == "function" and type(ImGui.Unindent) == "function"
    if padded then scope(ImGui.Indent, 8) end
    if grouped and type(ImGui.Dummy) == "function" then pcall(ImGui.Dummy, 0, 3) end
    local ok, err = pcall(function()
        if title and tostring(title) ~= "" then
            local label=tostring(title)
            local title_width=select(1, content_region())
            if ImGui and type(ImGui.GetCursorScreenPos)=="function"
                and type(ImGui.AddText)=="function" and type(ImGui.Dummy)=="function"
                and title_width>=measured_text_width(label)+12 then
                local px,py=ImGui.GetCursorScreenPos()
                local tw=measured_text_width(label)
                pcall(ImGui.AddText,px+math.max(4,(title_width-tw)/2),py+3,
                    label,188,121,245,255)
                if type(ImGui.AddRectFilled)=="function" then
                    pcall(ImGui.AddRectFilled,px+4,py+23,px+title_width-4,py+24,
                        81,43,108,167,0)
                end
                ImGui.Dummy(0,28)
            else
                ui_text(label)
                ui_spacing(1)
            end
        end
        if subtitle and tostring(subtitle) ~= "" then CScriptUI.tooltip(subtitle) end
        if type(renderer) == "function" then renderer() end
    end)
    if State and State.tab_render_blocked then error(err or "Native UI scope uncertain; unload and reload CScript.", 0) end
    if padded then scope(ImGui.Unindent, 8) end
    if grouped and type(ImGui.Dummy) == "function" then pcall(ImGui.Dummy, 0, 3) end
    if grouped then scope(ImGui.EndGroup) end
    if grouped and x and y and width > 0 and type(ImGui.GetItemRectSize) == "function" then
        local measured, _, h = pcall(ImGui.GetItemRectSize)
        if measured and tonumber(h) and h > 0 then
            if not CScriptUI._card_geometry[key] then
                local count = 0; for _ in pairs(CScriptUI._card_geometry) do count = count + 1 end
                if count >= 256 then CScriptUI._card_geometry = {} end
            end
            CScriptUI._card_geometry[key] = { width = width, height = h }
            if type(ImGui.AddRect) == "function" then
                pcall(ImGui.AddRect,x,y,x+width,y+h,
                    is_dashboard and 118 or 61, is_dashboard and 64 or 40,
                    is_dashboard and 158 or 85, is_dashboard and 205 or 148,
                    5,0,1)
            end
        end
    end
    if not ok then
        log_error_once("card_" .. key, err); error(err, 0)
    end
    return ok
end

-- Opaque local surface hides the host gradient only inside CScript's content.
-- Cherax's header, sidebar, window dimensions and other Lua tabs stay host-owned.
function CScriptUI.surface()
    if not (ImGui and type(ImGui.GetCursorScreenPos)=="function"
            and type(ImGui.AddRectFilled)=="function") then return end
    local ok,x,y=pcall(ImGui.GetCursorScreenPos)
    local w,h=content_region()
    if not ok or type(x)~="number" or type(y)~="number" or w<=0 or h<=0 then return end
    -- Render behind all widgets. This is actual Cherax ImGui drawing, not a
    -- background screenshot. No custom textures or allocations per frame.
    pcall(ImGui.AddRectFilled,x-3,y-3,x+w+3,y+h+3,7,8,12,255,5)
    local phase=cscript_gloss_phase()
    local glow_x=x+8+math.max(0,w-16)*phase
    pcall(ImGui.AddRectFilled,x+2,y-2,x+w-2,y,78,35,116,125,0)
    pcall(ImGui.AddRectFilled,math.max(x+4,glow_x-24),y-2,
        math.min(x+w-4,glow_x+24),y,181,82,239,155,0)
    local ribbon=math.min(92,math.max(22,h*0.15))
    pcall(ImGui.AddRectFilled,x+4,y+4,x+math.min(w-4,w*0.56),y+5,
        65,29,116,98,0)
    if h>85 and w>170 then
        pcall(ImGui.AddRectFilled,x+w-3,y+8,x+w-2,y+ribbon,121,50,174,42,0)
    end
end

local function component_button(label, id, tooltip, kind, active, requested_width, disabled)
    label, id, kind = tostring(label), clean_id(id or label), tostring(kind or "secondary")
    disabled = disabled == true
    local custom = ImGui and type(ImGui.InvisibleButton) == "function"
        and type(ImGui.GetCursorScreenPos) == "function" and type(ImGui.AddRectFilled) == "function"
        and type(ImGui.AddRect) == "function" and type(ImGui.AddText) == "function"
    local clicked, held, input_active = false, false, false
    if custom then
        local ok = pcall(function()
            local x, y = ImGui.GetCursorScreenPos()
            if not x or not y then error("cursor position unavailable") end
            local text_width, text_height = #label * 7, 15
            if type(ImGui.CalcTextSize) == "function" then
                local width, height = ImGui.CalcTextSize(label)
                text_width, text_height = tonumber(width) or text_width, tonumber(height) or text_height
            end
            local available_width = select(1, content_region())
            local studio = id:find("outfit_", 1, true) or id:find("vm_", 1, true)
                or id:find("studio_", 1, true)
            local compact = available_width > 0 and available_width <= STUDIO_COMPACT_MAX_WIDTH
            local minimum_width = kind == "icon" and (compact and 30 or 34)
                or kind == "chip" and (compact and 44 or 60)
                or (compact and 76 or 92)
            local width, height = math.max(studio and 48 or minimum_width,
                text_width + (kind == "chip" and (studio and 11 or 14) or (studio and 15 or compact and 18 or 24))),
                studio and (kind == "chip" and 23 or 25) or (kind == "chip" and 25 or (compact and 27 or 29))
            if tonumber(requested_width) then width = math.max(34, tonumber(requested_width)) end
            if available_width > 0 then width = math.min(width, available_width) end
            clicked = ImGui.InvisibleButton("##" .. id, width, height) == true and not disabled
            local hovered = type(ImGui.IsItemHovered) == "function" and ImGui.IsItemHovered() == true
            input_active = type(ImGui.IsItemActive) == "function" and ImGui.IsItemActive() == true
            held = not disabled and input_active
            local fill, border = { 18, 14, 28, 245 }, { 69, 40, 92, 208 }
            local text_color = { 239, 238, 246, 255 }
            if disabled then
                fill, border, text_color = { 13, 14, 18, 218 }, { 43, 44, 52, 190 }, { 116, 118, 130, 220 }
            elseif kind == "primary" then
                fill, border = hovered and { 139, 48, 218, 252 } or { 97, 30, 153, 250 }, { 182, 84, 246, 244 }
            elseif kind == "danger" then
                fill, border = hovered and { 91, 28, 39, 248 } or { 43, 20, 26, 245 }, { 218, 63, 84, 242 }
            elseif kind == "subtle" then
                fill, border = hovered and { 44, 25, 56, 244 } or { 21, 16, 31, 240 }, { 87, 51, 116, 210 }
            elseif kind == "chip" and active then
                fill, border = hovered and { 121, 37, 170, 250 } or { 90, 28, 136, 248 }, { 186, 89, 246, 246 }
            elseif active then
                fill, border = hovered and { 63, 37, 82, 248 } or { 42, 29, 58, 246 }, { 156, 73, 222, 238 }
            elseif hovered then
                fill, border = { 28, 27, 34, 246 }, { 104, 71, 131, 235 }
            end
            local rounding = studio and 3 or kind == "chip" and 4 or 4
            ImGui.AddRectFilled(x, y, x + width, y + height, fill[1], fill[2], fill[3], fill[4], rounding)
            ImGui.AddRect(x, y, x + width, y + height, border[1], border[2], border[3], border[4], rounding, 0, 1)
            if kind == "chip" and active then
                ImGui.AddRectFilled(x + 1, y + height - 2, x + width - 1, y + height,
                    174, 72, 255, 255, 0)
            end
            ImGui.AddText(x + math.max(7, (width - text_width) * 0.5),
                y + math.max(4, (height - text_height) * 0.5), label,
                text_color[1], text_color[2], text_color[3], text_color[4])
        end)
        if not ok then custom = false end
    end
    if not custom then
        local fallback_label = label .. "##" .. id
        if tonumber(requested_width) and ImGui and type(ImGui.Button) == "function" then
            local available_width = select(1, content_region())
            local width = math.max(34, tonumber(requested_width))
            if available_width > 0 then width = math.min(width, available_width) end
            local studio = id:find("outfit_", 1, true) or id:find("vm_", 1, true)
                or id:find("studio_", 1, true)
            local ok, value = pcall(ImGui.Button, fallback_label, width, studio and 26 or 32)
            if ok then clicked = value == true else clicked = imgui_clicked("Button", fallback_label) end
        else
            clicked = imgui_clicked("Button", fallback_label)
        end
        if ImGui and type(ImGui.IsItemActive) == "function" then
            local held_ok, held_value = pcall(ImGui.IsItemActive)
            held = held_ok and held_value == true
        end
        input_active = held
        if disabled then clicked, held = false, false end
    end
    CScriptUI.tooltip(feature_help(label, tooltip))
    if clicked and kind ~= "toggle" and not id:find("^step_") then
        trace_ui_event("SUCCESS_UNVERIFIED", label, "button press", "id=" .. tostring(id))
    end
    return clicked, held, input_active
end

function CScriptUI.primary_button(label, id, tooltip, width, disabled)
    return component_button(tostring(label) .. "  >", "primary_" .. clean_id(id or label), tooltip, "primary", false,
        width, disabled)
end

function CScriptUI.secondary_button(label, id, tooltip, width, disabled)
    return component_button(label, "secondary_" .. clean_id(id or label), tooltip, "secondary", false, width, disabled)
end

-- Repeat only reversible option navigation. Ordinary buttons (especially save,
-- delete and confirmation actions) deliberately retain their click semantics.
local repeat_press
local function repeat_clock()
    if ImGui and type(ImGui.GetTime) == "function" then
        local ok, value = pcall(ImGui.GetTime)
        if ok and type(value) == "number" and value == value and value >= 0 and value < math.huge then
            return value * 1000
        end
    end
    if Time and type(Time.GetEpocheMs) == "function" then
        local ok, value = pcall(Time.GetEpocheMs)
        if ok and type(value) == "number" and value == value and value >= 0 and value < math.huge then return value end
    end
end

local function repeated_button(label, id, tooltip, width, disabled)
    local clicked, held, input_active = component_button(label, id, tooltip, "secondary", false, width, disabled)
    local focused = true
    if ImGui and type(ImGui.IsWindowFocused) == "function" then
        local ok, value = pcall(ImGui.IsWindowFocused,
            ImGuiFocusedFlags and ImGuiFocusedFlags.RootAndChildWindows or 0)
        focused = ok and value == true
    end
    local now, frame = repeat_clock(), nil
    if ImGui and type(ImGui.GetFrameCount) == "function" then
        local ok, value = pcall(ImGui.GetFrameCount)
        if ok and type(value) == "number" and value >= 0 and value % 1 == 0 then frame = value end
    end
    local press = repeat_press and repeat_press.id == id and repeat_press or nil
    if disabled or not focused then
        if input_active then
            repeat_press = {
                id = id,
                last_ms = now or 0,
                last_frame = frame,
                next_ms = math.huge,
                cancelled = true
            }
        elseif press then
            repeat_press = nil
        end
        return false
    end
    if not held then
        -- ImGui normally reports Button on release. A press already handled on
        -- mouse-down must not add a final, unintended extra step on release.
        if press then
            repeat_press = nil; return false
        end
        return clicked == true
    end
    if not now then return clicked == true end
    if press then
        if now < press.last_ms or now - press.last_ms > 250
            or (frame and press.last_frame and (frame < press.last_frame or frame > press.last_frame + 1)) then
            press.cancelled = true
        end
        press.last_ms, press.last_frame = now, frame
        if press.cancelled or now < press.next_ms then return false end
        -- One step per rendered frame; never catch up a backlog after a hitch.
        press.next_ms = now + 50
        return true
    end
    repeat_press = { id = id, last_ms = now, last_frame = frame, next_ms = now + 250 }
    return true
end

function CScriptUI.repeat_button(label, id, tooltip, width, disabled)
    return repeated_button(label, "repeat_" .. clean_id(id or label), tooltip, width, disabled)
end

function CScriptUI.reset_repeat_input()
    if repeat_press then repeat_press.cancelled = true end
    CScriptUI.reset_studio_input()
end

