-- A presentation-only press/hold primitive. Cherax builds exposing
-- ImGui.IsItemActive receive continuous hold state; older bindings retain the
-- ordinary click result without synthesizing input or registering another loop.
function CScriptUI.hold_button(label, id, tooltip, width, active)
    local clicked, held = component_button(label, "hold_" .. clean_id(id or label), tooltip,
        "subtle", active == true, width)
    return clicked, held, ImGui and type(ImGui.IsItemActive) == "function" or false
