function CScriptUI.status_badge(label, kind)
    local prefix = ({ success = "+", warning = "!", error = "x", info = "i" })[kind] or "i"
    ui_text("[" .. prefix .. "] " .. tostring(label or "Status"), kind ~= "success")
end

function CScriptUI.progress_bar(fraction, label, kind)
    fraction = math.max(0, math.min(1, tonumber(fraction) or 0))
    label = tostring(label or (math.floor(fraction * 100 + 0.5) .. "%"))
    if ImGui and type(ImGui.ProgressBar) == "function" then
        local ok = pcall(ImGui.ProgressBar, fraction, -1, 18, label)
        if ok then return true end
    end
    local blocks, filled = 16, math.floor(fraction * 16 + 0.5)
    CScriptUI.status_badge(label .. "  [" .. string.rep("=", filled) .. string.rep("-", blocks - filled) .. "]",
        kind or "info")
    return false
end

function CScriptUI.empty_state(title, guidance)
    ui_spacing(1)
    ui_text(title or "Nothing here yet.", true)
    if guidance and tostring(guidance) ~= "" then ui_text(guidance, true) end
    ui_spacing(1)
end

-- Real Cherax ImGui tab bars, matching the host's horizontal tab behavior.
-- These navigate CScript only. Gameplay features still use RenderFeature.
function CScriptUI.tab_bar(id,items,selected,on_change)
    assert(ImGui and type(ImGui.BeginTabBar)=="function"
        and type(ImGui.EndTabBar)=="function"
        and type(ImGui.BeginTabItem)=="function"
        and type(ImGui.EndTabItem)=="function","Cherax horizontal tab API unavailable.")
    local tab_id="##CScriptTabs_"..clean_id(id)
    local flags=ImGuiTabBarFlags and ImGuiTabBarFlags.FittingPolicyScroll or 0
    local ok,opened=pcall(ImGui.BeginTabBar,tab_id,flags)
    if not ok then error("Cherax BeginTabBar failed: "..tostring(opened),0) end
    if opened~=true then return selected,false end
    local changed,selection=false,selected
    local render_ok,render_error=xpcall(function()
        for _,row in ipairs(items or {}) do
            local key=tostring(row.key or row[1])
            local label=tostring(row.label or row[2] or row.key or row[1])
            local tab_open,tab_ok
            -- Request synchronization only on first render or an external
            -- programmatic route change. Never force the old tab selected
            -- every frame, or clicking a new tab would appear not to work.
            local previous=State and State.cherax_native_tab_selection and
                State.cherax_native_tab_selection[tab_id]
            local selection_changed=previous~=nil and previous~=selected
            local first=(previous==nil)
            local request=(first or selection_changed) and key==selected
            local select_flag=ImGuiTabItemFlags and ImGuiTabItemFlags.SetSelected or 0
            if request and select_flag~=0 then
                tab_ok,tab_open=pcall(ImGui.BeginTabItem,label,nil,select_flag)
                if not tab_ok then tab_ok,tab_open=pcall(ImGui.BeginTabItem,label,select_flag) end
            end
            if not tab_ok then tab_ok,tab_open=pcall(ImGui.BeginTabItem,label)end
            if not tab_ok then error("Cherax BeginTabItem failed: "..tostring(tab_open),0)end
            if tab_open==true then
                -- A tab item must be ended before callback/page selection.
                local ended,end_error=pcall(ImGui.EndTabItem)
                if not ended then error("Cherax EndTabItem failed: "..tostring(end_error),0) end
                if not changed and selection~=key then
                    selection,changed=key,true
                    if type(on_change)=="function"then on_change(row,key)end
                end
            end
        end
    end,function(err) return tostring(err) end)
    local ended,end_error=pcall(ImGui.EndTabBar)
    if not ended then
        State.tab_render_blocked=true
        error("Cherax EndTabBar failed; reload CScript: "..tostring(end_error),0)
    end
    if not render_ok then error(render_error,0)end
    State.cherax_native_tab_selection=State.cherax_native_tab_selection or {}
    State.cherax_native_tab_selection[tab_id]=selection
    return selection,changed
end

function CScriptUI.context_tabs(id,items,selected)
    return CScriptUI.tab_bar(id,items,selected)
end

-- A responsive business selector: all supported businesses remain visible
-- within the available menu width, with no offscreen horizontal tab scrolling.
function CScriptUI.business_tabs(items, selected)
    local measured_width = select(1,content_region())
    local width = math.max(150, tonumber(measured_width) or 500)
    local columns = math.max(1, math.min(3, math.floor((width - 10) / 138)))
    local button_width = math.max(90, math.floor((width - (columns - 1) * 6 - 8) / columns))
    for index,item in ipairs(items or {}) do
        local label = item.short_label or item.label or item.key
        if CScriptUI.category_chip(label, item.key==selected,
            "business_" .. tostring(item.key), nil, button_width) and item.key~=selected then
            return item.key, true
        end
        if index % columns ~= 0 and index < #items then ui_same_line() end
    end
    return selected, false
end

function CScriptUI.toggle_row(label, enabled, id, tooltip)
    enabled = enabled == true
    if not ImGui or type(ImGui.Checkbox) ~= "function" then
        ui_text(tostring(label) .. " (control unavailable)", true)
        return enabled, false
    end
    local ok, value = pcall(ImGui.Checkbox, tostring(label) .. "##toggle_" .. clean_id(id or label), enabled)
    CScriptUI.tooltip(feature_help(label, tooltip))
    if ok and type(value) == "boolean" and value ~= enabled then
        trace_ui_event("SUCCESS_UNVERIFIED", label, "toggle change", "value=" .. tostring(value))
        return value, true
    end
    return enabled, false
end

function CScriptUI.slider_row(label, value_text, renderer, tooltip)
    local heading, value = tostring(label), tostring(value_text or "")
    local combined = heading .. "  " .. value
    local width = select(1, content_region())
    if width > 0 and measured_text_width(combined) > width then
        ui_text(heading)
        if value ~= "" then ui_text(value) end
    else
        ui_text(combined)
    end
    CScriptUI.tooltip(tooltip)
    if type(renderer) == "function" then return renderer() end
end

function CScriptUI.value_stepper(label, value, minimum, maximum, step, id, tooltip, display_value)
    minimum, maximum, step = tonumber(minimum) or 0, tonumber(maximum) or 0, tonumber(step) or 1
    value = math.max(minimum, math.min(maximum, tonumber(value) or minimum))
    local display = tostring(display_value or value)
    local available_width = select(1, content_region())
    local previous_width = component_minimum_width("< Previous", "secondary")
    local next_width = component_minimum_width("Next >", "secondary")
    local inline_required = previous_width + next_width + measured_text_width(display) + 30
    local stacked = available_width > 0 and inline_required > available_width
    if stacked then ui_text(tostring(label) .. "  -  " .. display) else ui_text(tostring(label)) end
    local changed = false
    local stacked_button_width = stacked and math.max(72, math.floor((available_width - 8) * 0.5)) or nil
    if repeated_button("< Previous", "step_prev_" .. clean_id(id or label), tooltip,
            stacked_button_width) then
        value = value - step
        if value < minimum then value = maximum end
        changed = true
    end
    ui_same_line()
    if not stacked then
        ui_text(display); ui_same_line()
    end
    if repeated_button("Next >", "step_next_" .. clean_id(id or label), tooltip,
            stacked_button_width) then
        value = value + step
        if value > maximum then value = minimum end
        changed = true
    end
    if changed then
        trace_ui_event("SUCCESS_UNVERIFIED", label, "value change", "value=" .. tostring(value))
    end
    return value, changed
end

function CScriptUI.compact_selector(id, label, index, items, options)
    items = type(items) == "table" and items or {}
    options = type(options) == "table" and options or {}
    if #items == 0 then
        ui_text(tostring(label) .. ": None", true); return 1, false
    end
    index = math.max(1, math.min(#items, math.floor(tonumber(index) or 1)))
    local selected, key = index, clean_id(id)
    local function caption(item)
        if type(item) == "table" then return tostring(item.label or item.name or item[2] or item[1] or "Item") end
        return tostring(item)
    end
    -- Only modification choices opt into the existing Outfit Item/Texture row.
    -- Step catalog indices, leaving each caller's native-value mapping intact.
    if options.stepper == true and type(CScriptUI.value_stepper) == "function" then
        return CScriptUI.value_stepper(label, index, 1, #items, 1, "studio_select_" .. key,
            options.tooltip, caption(items[index]))
    end
    -- Navigation, camera angles, sources and destinations remain ordinary lists.
    if ImGui and type(ImGui.BeginCombo) == "function" and type(ImGui.EndCombo) == "function"
        and type(ImGui.Selectable) == "function" then
        local preview = tostring(label) .. ": " .. caption(items[selected])
        if type(ImGui.SetNextItemWidth) == "function" then pcall(ImGui.SetNextItemWidth, -1) end
        local ok, opened = pcall(ImGui.BeginCombo, "##studio_select_" .. key, preview, 0)
        if ok then
            local content_ok = true
            if opened == true then
                content_ok = pcall(function()
                    for candidate, item in ipairs(items) do
                        local row_label = caption(item) .. (candidate == selected and " (current)" or "")
                        -- false supports both activation-return and selected-state bindings.
                        if ImGui.Selectable(row_label .. "##" .. key .. "_" .. candidate, false) == true then
                            selected = candidate
                        end
                        if candidate == index and type(ImGui.SetItemDefaultFocus) == "function" then
                            ImGui.SetItemDefaultFocus()
                        end
                    end
                end)
                pcall(ImGui.EndCombo)
            end
            if not content_ok then return index, false end
            return selected, selected ~= index
        end
    end
    if ImGui and type(ImGui.Combo) == "function" then
        local captions = {}
        for candidate, item in ipairs(items) do captions[candidate] = caption(item) end
        if type(ImGui.SetNextItemWidth) == "function" then pcall(ImGui.SetNextItemWidth, -1) end
        local ok, next_index, changed = pcall(ImGui.Combo, tostring(label) .. "##studio_select_" .. key,
            index - 1, captions, #captions, 12)
        if ok and type(next_index) == "number" and items[next_index + 1] then
            return next_index + 1, changed == true
        end
    end
    ui_text(tostring(label) .. ": " .. caption(items[index]), true)
    return index, false
end

function CScriptUI.studio_category_selector(id, labels, selected)
    return CScriptUI.compact_selector(id, "Category", selected, labels)
end

function CScriptUI.rgb_channels(id, label, values)
    local result={}
    for index=1,3 do result[index]=math.max(0,math.min(255,math.floor(tonumber(values[index]) or 0))) end
    local wrapped=ImGui and type(ImGui.PushTextWrapPos)=="function" and type(ImGui.PopTextWrapPos)=="function"
    if wrapped then ImGui.PushTextWrapPos(0) end
    ui_text(tostring(label)..("  #%02X%02X%02X"):format(result[1],result[2],result[3]))
    if wrapped then ImGui.PopTextWrapPos() end
    local available=select(1,content_region())
    local sliders=ImGui and type(ImGui.SliderInt)=="function"
    local inline=sliders and available>=240
    local width=inline and math.max(64,math.floor((available-16)/3)) or math.max(64,available)
    local changed=false
    for index,channel in ipairs({"R","G","B"}) do
        if inline and index>1 then ui_same_line() end
        local value,edited=result[index],false
        if sliders then
            if type(ImGui.SetNextItemWidth)=="function" then pcall(ImGui.SetNextItemWidth,width) end
            local ok,a,b=pcall(ImGui.SliderInt,"##rgb_"..clean_id(id).."_"..index,value,0,255,channel.." %d")
            local candidate=ok and (type(a)=="number" and a or type(b)=="number" and b or nil)
            if candidate and candidate==candidate and math.abs(candidate)<100000 then
                candidate=math.max(0,math.min(255,math.floor(candidate+0.5)))
                value,edited=candidate,candidate~=value
            end
        else
            value,edited=CScriptUI.value_stepper(channel,value,0,255,1,"rgb_"..clean_id(id).."_"..index)
        end
        result[index]=math.max(0,math.min(255,math.floor(value)))
        changed=changed or edited
    end
    return result,changed
end

function CScriptUI.studio_camera_toolbar(id, enabled, options)
    local input = {
        rotate = 0,
        zoom = 0,
        turn_around = false,
        reset = false,
        interacting = false,
        viewport = CScriptUI.studio_viewport()
    }
    local focus = true
    if ImGui and type(ImGui.IsWindowFocused) == "function" then
        local ok, value = pcall(ImGui.IsWindowFocused,
            ImGuiFocusedFlags and ImGuiFocusedFlags.RootAndChildWindows or 0)
        focus = ok and value == true
    end
    local disabled = enabled == false or not focus
    local available = select(1, content_region())
    local compact = type(options) == "table" and options.compact == true
    local per_row = available >= 680 and 6 or available >= 350 and 3 or available >= 210 and 2 or 1
    local actions = {
        { "Rotate Left",  "rotate", -1, "rotate_left" }, { "Turn Around", "turn_around", true, "turn_around" },
        { "Rotate Right", "rotate", 1,  "rotate_right" }, { "Zoom -", "zoom", -1, "zoom_out" },
        { "Zoom +", "zoom", 1, "zoom_in" },
    }
    if compact then
        local captions = { "Left", "Turn 180", "Right", "Zoom -", "Zoom +" }
        local total = 0
        for index, action in ipairs(actions) do
            action[5], action[1] = action[1], captions[index]
            action.width = math.max(48, measured_text_width(action[1]) + 16)
            total = total + action.width + (index > 1 and 8 or 0)
        end
        -- Compact labels fit all six controls at ordinary menu widths. At small
        -- widths the same controls wrap predictably instead of clipping labels.
        per_row = available >= total and #actions or available >= 255 and 3 or available >= 160 and 2 or 1
    end
    local used, count = 0, 0
    for _, action in ipairs(actions) do
        local width = action.width or component_minimum_width(action[1], "secondary")
        if count > 0 and count < per_row and used + 8 + width <= available then
            ui_same_line(); used = used + 8
        else
            used, count = 0, 0
        end
        local clicked, held = component_button(action[1], clean_id(id) .. "_" .. action[4],
            (action[5] or action[1]) .. ". Adjust the studio view.", "subtle", false, width, disabled)
        if not disabled then
            if action[2] == "rotate" or action[2] == "zoom" then
                if held or clicked then input[action[2]] = action[3] end
            elseif clicked then
                input[action[2]] = true
            end
            input.interacting = input.interacting or clicked or held
        end
        used, count = used + math.min(width, math.max(0, available)), count + 1
    end
    return input
end

function CScriptUI.confirm_dialog(id, message)
    CScriptUI.status_badge(message or "Confirm this action", "warning")
    if CScriptUI.danger_button("Confirm", "confirm_" .. clean_id(id)) then return "confirm" end
    ui_same_line()
    if CScriptUI.secondary_button("Cancel", "cancel_" .. clean_id(id)) then return "cancel" end
    return nil
end

function CScriptUI.begin_columns(id, count, weights)
    count = math.max(1, tonumber(count) or 2)
    active_column_layout = nil
    if count < 2 or not resolve_layout_capabilities().tables then return false end
    local flags = ImGuiTableFlags and (id == "hangar_panels"
        and ImGuiTableFlags.SizingStretchSame or ImGuiTableFlags.SizingStretchProp) or 0
    local opened = ImGui.BeginTable("##CScriptColumns_" .. clean_id(id), count, flags)
    if opened ~= true then return false end

    active_column_layout = { mode = "table", count = count, open = true }
    local column_flags = ImGuiTableColumnFlags and ImGuiTableColumnFlags.WidthStretch or 0
    local setup_ok, setup_err = pcall(function()
        for index = 1, count do
            -- Cherax v5.48.1 exposes the two-argument TableSetupColumn binding.
            -- WidthStretch keeps columns evenly distributed without calling an
            -- unsupported third-argument weight overload.
            ImGui.TableSetupColumn("##CScriptColumn_" .. tostring(index), column_flags)
        end
    end)
    if not setup_ok then
        local layout = active_column_layout
        active_column_layout = nil
        if layout and layout.open then pcall(ImGui.EndTable) end
        UI_CAPABILITIES.tables = false
        log_error_once("table_layout_disabled",
            "ImGui table column setup was unavailable; CScript will use stacked page layouts. " .. tostring(setup_err))
        return false
    end
    return true
end

function CScriptUI.editor_height(minimum, maximum)
    local fallback = tonumber(maximum) or 520
    if not (ImGui and type(ImGui.GetContentRegionAvail) == "function") then return fallback end
    local ok, _, available_height = pcall(ImGui.GetContentRegionAvail)
    if not ok or not tonumber(available_height) then return fallback end
    local available = math.floor(tonumber(available_height) - 6)
    local wanted_minimum = tonumber(minimum) or 320
    if available < wanted_minimum then return math.max(220, available) end
    return math.min(fallback, available)
end

function CScriptUI.end_columns()
    local layout = active_column_layout
    active_column_layout = nil
    if layout and layout.mode == "table" and layout.open then ImGui.EndTable() end
end

function CScriptUI.abort_columns()
    local layout = active_column_layout
    active_column_layout = nil
    if layout and layout.mode == "table" and layout.open and ImGui
        and type(ImGui.EndTable) == "function" then
        pcall(ImGui.EndTable)
    end
end

function CScriptUI.column(index)
    local layout = active_column_layout
    index = math.max(0, tonumber(index) or 0)
    if layout and layout.mode == "table" then ImGui.TableSetColumnIndex(index) end
end

function CScriptUI.next_row()
    if active_column_layout and active_column_layout.mode == "table" then ImGui.TableNextRow() end
end

