local LEGACY_CATEGORY_DEFAULTS = {
    Weapons = { "Combat", "General" },
    Businesses = { "Progression", "Businesses" },
    Heists = { "Progression", "Heists" },
    Recovery = { "Progression", "Account" },
    Economy = { "Progression", "Economy" },
    Session = { "Online", "Session" },
    Utilities = { "World", "General" },
}

local function resolve_route(reference)
    reference = tostring(reference or "")
    local direct = ROUTE_BY_ID[reference]
    if direct then return direct end
    local alias = LEGACY_PAGE_ROUTE_ALIASES[reference]
    return alias and ROUTE_BY_ID[alias] or nil
end

-- These legacy fields are ignored in memory and retired only on an explicit
-- save. Unknown persisted preferences remain untouched.
local LEGACY_ACCESS_KEYS = {
    favorites = true,
    pins = true,
    recent = true,
    global_search = true,
    quick_mode = true,
    search_cache_query = true,
    search_cache_results = true,
    quick_access_expanded = true,
    focused_feature = true,
    navigation_focus = true,
    hotkey_palette = true,
    palette_open = true,
}
local function retire_access_state()
    for key in pairs(LEGACY_ACCESS_KEYS) do State[key] = nil end
    State.ui_state_dirty = nil
end

local function ui_state_path()
    if not (FileMgr and type(FileMgr.GetMenuRootPath) == "function") then return nil end
    local ok, root = pcall(FileMgr.GetMenuRootPath)
    if not ok or type(root) ~= "string" or root == "" then return nil end
    local directory = root .. "\\Lua\\CScript"
    return directory .. "\\ui_state.txt"
end

local function read_ui_state_source(path)
    if not path or not (FileMgr and type(FileMgr.DoesFileExist) == "function"
            and type(FileMgr.ReadFileContent) == "function") then
        return false
    end
    local exists_ok, exists = pcall(FileMgr.DoesFileExist, path)
    if not exists_ok or type(exists) ~= "boolean" then return false end
    if not exists then return true, nil end
    local read_ok, content = pcall(FileMgr.ReadFileContent, path)
    if not read_ok or type(content) ~= "string" then return false end
    if not content:match("^CSCRIPT_UI_STATE_V[12][\r\n]")
        and content ~= "CSCRIPT_UI_STATE_V1" and content ~= "CSCRIPT_UI_STATE_V2" then
        return false
    end
    return true, content
end

local function load_ui_state()
    if State.ui_state_loaded then return end
    State.ui_state_loaded = true
    local path = ui_state_path()
    local read_ok, content = read_ui_state_source(path)
    if not read_ok or not content then return end
    State.ui_state_source = content
    local fields = {}
    for line in (content .. "\n"):gmatch("([^\n]*)\n") do
        local key, value = line:match("^([%w_]+)=([^\r]*)")
        if key == "category" or key == "page" then fields[key] = value end
    end
    local source_category_key = tostring(fields.category or "")
    local category_key = source_category_key
    local legacy = LEGACY_CATEGORY_DEFAULTS[category_key]
    if legacy then category_key = legacy[1] end
    State.selected_category_key = CATEGORY_BY_KEY[category_key] and category_key or "Home"
    State.selected_page_name = CATEGORY_BY_KEY[State.selected_category_key].pages[1].name
    local page_name = tostring(fields.page or "")
    local legacy_route = resolve_route(page_route_id(source_category_key, page_name))
    if legacy_route then
        State.selected_category_key = legacy_route.category_key
        page_name = legacy_route.page
        State.progression_heist_pending = ({ Apartment = "apartment", ["Cayo Perico"] = "cayo",
            ["Diamond Casino"] = "casino", Doomsday = "doomsday" })[tostring(fields.page or "")]
    elseif legacy then
        page_name = legacy[2]
    end
    local category = CATEGORY_BY_KEY[State.selected_category_key or ""]
    if category and page_name ~= "" then
        for _, page in ipairs(category.pages or {}) do
            if page.name == page_name then
                State.selected_page_name = page_name; break
            end
        end
    end
end

local function defer_ui_state_save(now_ms)
    local failures = math.min(6, (tonumber(State.ui_state_save_failures) or 0) + 1)
    local delay = math.min(UI_STATE_RETRY_MAX_MS, UI_STATE_RETRY_BASE_MS * (2 ^ (failures - 1)))
    State.ui_state_save_failures = failures
    State.ui_state_next_save_ms = math.max(0, tonumber(now_ms) or 0) + delay
    if not State.ui_state_save_reported then
        State.ui_state_save_reported = true
        log_error_once("state_persist",
            "UI page preferences could not be saved. Retrying the explicit save with bounded backoff.")
    end
end

local function save_ui_state(now_ms)
    if not State.navigation_save_requested then return true end
    now_ms = math.max(0, tonumber(now_ms) or 0)
    if now_ms < (tonumber(State.ui_state_next_save_ms) or 0) then return false end
    local path = ui_state_path()
    if not path or not (FileMgr and type(FileMgr.WriteFileContent) == "function") then
        defer_ui_state_save(now_ms)
        return false
    end
    -- Re-read immediately before an explicit write. A read failure or unknown
    -- format must never replace an existing file with partial preferences.
    local read_ok, source = read_ui_state_source(path)
    if not read_ok then
        defer_ui_state_save(now_ms); return false
    end
    State.ui_state_source = source
    local values = { category = State.selected_category_key or "Home", page = State.selected_page_name or "Overview" }
    local seen, lines = {}, {}
    if type(State.ui_state_source) == "string" then
        local source = State.ui_state_source
        if source:sub(-1) ~= "\n" then source = source .. "\n" end
        for line in source:gmatch("([^\n]*)\n") do
            local key = line:match("^([%w_]+)=")
            if values[key] then
                lines[#lines + 1] = key .. "=" .. tostring(values[key]):gsub("[\r\n]", ""); seen[key] = true
            elseif not LEGACY_ACCESS_KEYS[key] then
                lines[#lines + 1] = line
            end
        end
    else
        lines[1] = "CSCRIPT_UI_STATE_V2"
    end
    for _, key in ipairs({ "category", "page" }) do
        if not seen[key] then lines[#lines + 1] = key .. "=" .. tostring(values[key]):gsub("[\r\n]", "") end
    end
    local content = table.concat(lines, "\n")
    local ok, result = pcall(FileMgr.WriteFileContent, path, content, false)
    if ok and result ~= false then
        State.navigation_save_requested = nil
        State.ui_state_save_failures = 0
        State.ui_state_next_save_ms = 0
        State.ui_state_source = content
        return true
    end
    defer_ui_state_save(now_ms)
    return false
end

local function selected_page(category)
    if not category then return nil end
    local wanted = tostring(State.selected_page_name or "")
    for _, page in ipairs(category.pages or {}) do if page.name == wanted then return page end end
    local fallback = category.pages and category.pages[1] or nil
    if fallback then State.selected_page_name = fallback.name end
    return fallback
end

local function ui_clock_ms()
    if ImGui and type(ImGui.GetTime) == "function" then
        local ok, value = pcall(ImGui.GetTime)
        if ok and type(value) == "number" then return math.floor(math.max(0, value) * 1000) end
    end
    return math.floor(((os and os.clock and os.clock()) or 0) * 1000)
end

local function transition_ease(value)
    value = math.max(0.0, math.min(1.0, tonumber(value) or 0.0))
    return value * value * (3.0 - 2.0 * value)
end

local function push_ui_alpha(alpha)
    alpha = math.max(0.02, math.min(1.0, tonumber(alpha) or 1.0))
    if alpha >= 0.999 then return false end
    if not (ImGui and type(ImGui.PushStyleVar) == "function" and type(ImGui.PopStyleVar) == "function"
            and ImGuiStyleVar and ImGuiStyleVar.Alpha ~= nil) then
        return false
    end
    local ok, err = pcall(ImGui.PushStyleVar, ImGuiStyleVar.Alpha, alpha)
    if not ok then
        State.tab_render_blocked = true
        log_error_once("fade_push", err)
        error("Fade PushStyleVar failed; native scope uncertain; unload and reload CScript: " .. tostring(err), 0)
    end
    return true
end

local function pop_ui_alpha(pushed)
    if not pushed then return end
    local ok, err = pcall(ImGui.PopStyleVar, 1)
    if not ok then
        State.tab_render_blocked = true
        log_error_once("fade_pop", err)
        error("Fade PopStyleVar failed; native scope uncertain; unload and reload CScript: " .. tostring(err), 0)
    end
end

local HeistNavigation = {
    stage_by_workspace = {
        setup = "setup",
        loot = "setup",
        board = "setup",
        cuts = "finale",
        launch = "finale",
        utilities = "tools",
        presets = "presets",
        advanced = "setup"
    }
}

function HeistNavigation.Supported(snapshot, key)
    for _, item in ipairs(snapshot.workspaces or {}) do
        if item.key == key then return true end
    end
    return false
end

function HeistNavigation.SetState(family, workspace, stage)
    State.heist_stages = State.heist_stages or {}
    State.heist_seen_workspace = State.heist_seen_workspace or {}
    State.heist_targets_by_family = State.heist_targets_by_family or {}
    State.heist_stages[family] = stage or HeistNavigation.stage_by_workspace[workspace] or "overview"
    State.heist_seen_workspace[family] = workspace == "board" and "loot" or workspace == "presets" and "setup" or
        workspace
    if workspace == "board" or workspace == "loot" then State.heist_targets_by_family[family] = workspace end
    State.heist_nav_error = nil
end

function HeistNavigation.Navigate(heists, family, workspace)
    if not (heists and type(heists.SelectFamily) == "function" and type(heists.Snapshot) == "function") then
        State.heist_nav_error = "Heist navigation unavailable."
        return false
    end
    local before = heists.Snapshot()
    local ok, why = heists.SelectFamily(family)
    if ok and workspace and family ~= "overview" and family ~= "presets" then
        local target = workspace == "board" and "loot" or workspace == "presets" and "setup" or workspace
        if type(heists.SelectWorkspace) == "function" then
            ok, why = heists.SelectWorkspace(target)
        else
            ok, why = false, "Heist navigation unavailable."
        end
    end
    if not ok then
        -- Rejected semantic navigation must not leave a different family selected.
        heists.SelectFamily(before.selected_family)
        if type(heists.SelectWorkspace) == "function" then heists.SelectWorkspace(before.selected_workspace) end
        State.heist_nav_error = why or "This view is unavailable."
        return false
    end
    if workspace then HeistNavigation.SetState(family, workspace) end
    return true
end

local function commit_navigation_entry(entry, source)
    if type(entry) ~= "table" then return false end
    local route_id = PAGE_ROUTE_BY_CONTEXT[page_context_id(entry.category_key, entry.page)]
    if not route_id or entry.route_id ~= route_id then return false end
    -- Canonical page data also discards stale feature/heist action payloads.
    entry = ROUTE_BY_ID[route_id]
    if State.selected_category_key == "Player" and State.selected_page_name == "Outfit Studio"
        and (entry.category_key ~= "Player" or entry.page ~= "Outfit Studio") then
        local player = module_context and module_context.CScript and module_context.CScript.Player
        if player and type(player.RequestOutfitPreviewClose) == "function" then
            player.RequestOutfitPreviewClose("page left") -- flags only; native tick owns teardown
        end
    end
    State.selected_category_key = entry.category_key
    State.selected_page_name = entry.page
    if dependencies and type(dependencies.log_info) == "function" then
        dependencies.log_info(("UI navigation source=%s target=%s transition=fade")
            :format(tostring(source or "direct"), tostring(entry.context or entry.key)))
    end
    return true
end

local function begin_page_transition(entry, source)
    if type(entry) ~= "table" then return false end
    local route_id = PAGE_ROUTE_BY_CONTEXT[page_context_id(entry.category_key, entry.page)]
    if not route_id or entry.route_id ~= route_id then return false end
    entry = ROUTE_BY_ID[route_id]
    local same_page = tostring(State.selected_category_key or "") == tostring(entry.category_key)
        and tostring(State.selected_page_name or "") == tostring(entry.page)
    if same_page then
        State.page_transition = nil -- clicking the current route cancels an outgoing request
        return commit_navigation_entry(entry, source)
    end
    local pending = State.page_transition
    if pending and pending.active and pending.entry
        and pending.entry.category_key == entry.category_key and pending.entry.page == entry.page then
        return true
    end
    if pending and pending.active and not pending.switched then
        pending.entry, pending.source = entry, tostring(source or "direct")
        return true -- latest route wins without restarting the fade clock
    end
    local now = ui_clock_ms()
    State.page_transition = {
        active = true,
        switched = false,
        started_ms = now,
        entry = entry,
        source = tostring(source or "direct"),
        from_category = tostring(State.selected_category_key or ""),
        from_page = tostring(State.selected_page_name or ""),
    }
    return true
end

local function update_page_transition(now)
    local transition = State and State.page_transition
    if type(transition) ~= "table" or transition.active ~= true then return end
    now = tonumber(now) or ui_clock_ms()
    local elapsed = math.max(0, now - (tonumber(transition.started_ms) or now))
    if transition.switched ~= true and elapsed >= PAGE_FADE_OUT_MS then
        if not commit_navigation_entry(transition.entry, transition.source) then
            transition.active = false
            return
        end
        transition.switched = true
    end
    if transition.switched == true and elapsed >= PAGE_FADE_OUT_MS + PAGE_FADE_IN_MS then
        transition.active = false
        transition.entry = nil
    end
end

local function page_transition_alpha(now)
    local transition = State and State.page_transition
    if type(transition) ~= "table" or transition.active ~= true then return 1.0 end
    now = tonumber(now) or ui_clock_ms()
    local elapsed = math.max(0, now - (tonumber(transition.started_ms) or now))
    if elapsed < PAGE_FADE_OUT_MS then
        return 1.0 - transition_ease(elapsed / PAGE_FADE_OUT_MS)
    end
    return transition_ease((elapsed - PAGE_FADE_OUT_MS) / PAGE_FADE_IN_MS)
end

local function shell_reveal_alpha(now)
    local started_ms = tonumber(State and State.shell_reveal_started_ms) or 0
    if started_ms <= 0 then return 1.0 end
    now = tonumber(now) or ui_clock_ms()
    local elapsed = math.max(0, now - started_ms)
    if elapsed >= (tonumber(State.shell_reveal_duration_ms) or SHELL_REVEAL_MS) then
        State.shell_reveal_started_ms = 0
        return 1.0
    end
    return transition_ease(elapsed / math.max(1, tonumber(State.shell_reveal_duration_ms) or SHELL_REVEAL_MS))
end

local function navigate_to_entry(entry, source)
    return begin_page_transition(entry, source)
end

Presentation.services = {
    aim = { owner = "Player", request = "RequestAimSelection", snapshot = "AimSelectionSnapshot" },
    setup = { owner = "Vehicle", request = "RequestCombatSetup", snapshot = "CombatSetupSnapshot" },
    farm = { owner = "Businesses", request = "RequestFinishFarmCycle", snapshot = "FarmActivitySnapshot" },
    delay = { owner = "Vehicle", request = "SetRapidFireDelay" },
}
function Presentation.provider(channel)
    local spec = Presentation.services[channel]
    return spec and module_context and module_context.CScript[spec.owner], spec
end

function Presentation.snapshot(channel)
    local provider, spec = Presentation.provider(channel)
    if not provider or type(provider[spec.request]) ~= "function" then
        return nil, spec.owner .. "." .. spec.request .. " unavailable."
    end
    if not spec.snapshot then return {} end
    if type(provider[spec.snapshot]) ~= "function" then
        return nil, spec.owner .. "." .. spec.snapshot .. " unavailable."
    end
    local ok, snapshot = pcall(provider[spec.snapshot])
    if not ok then return nil, "Snapshot unavailable: " .. tostring(snapshot) end
    if type(snapshot) ~= "table" then return nil, "Snapshot unavailable: invalid response." end
    return snapshot
end

function Presentation.busy(channel, snapshot)
    return (State.presentation_queue and State.presentation_queue[channel] ~= nil)
        or snapshot and snapshot.pending == true or false
end

function Presentation.queue(channel, ...)
    local snapshot, why = Presentation.snapshot(channel)
    if not snapshot then return false, why end
    if Presentation.busy(channel, snapshot) then return false, "Request already pending." end
    local provider = Presentation.provider(channel)
    State.presentation_queue = State.presentation_queue or {}
    State.presentation_results = State.presentation_results or {}
    State.presentation_queue[channel] = { provider = provider, args = table.pack(...) }
    State.presentation_results[channel] = {
        detail = "Queued for gameplay.",
        before = tostring(snapshot.phase) ..
            ":" .. tostring(snapshot.detail)
    }
    return true, "Queued for gameplay."
end

function Presentation.dispatch()
    if not started then return end
    local queue = State.presentation_queue or {}; State.presentation_queue = nil
    for _, channel in ipairs({ "aim", "setup", "farm", "delay" }) do
        local request = queue[channel]
        if request then
            local provider, spec = Presentation.provider(channel)
            local ok, accepted, detail = false, false, "Provider changed or unavailable."
            if provider == request.provider and type(provider[spec.request]) == "function" then
                ok, accepted, detail = pcall(provider[spec.request], table.unpack(request.args, 1, request.args.n))
                if not ok then detail, accepted = accepted, false end
            end
            local result = State.presentation_results[channel]
            result.detail = (ok and accepted == true and "Request accepted: " or "Request failed: ")
                .. tostring(detail or (accepted == true and "awaiting gameplay result." or "No acceptance returned."))
        end
    end
end

function Presentation.one_press(label, id, tooltip, kind, disabled)
    local renderer = kind == "primary" and CScriptUI.primary_button
        or kind == "danger" and CScriptUI.danger_button or CScriptUI.secondary_button
    -- The component clamps dimensions to the actual available Cherax content.
    local clicked, held, input_active = renderer(label, id, tooltip, CScriptUI.button_width(label, kind), disabled)
    State.presentation_pressed = State.presentation_pressed or {}
    local latched = State.presentation_pressed[id]
    if not clicked and not held and not input_active then State.presentation_pressed[id] = nil end
    if clicked then State.presentation_pressed[id] = true end
    return clicked == true and not latched and not disabled
end

function Presentation.result(channel, snapshot, why)
    local result = State.presentation_results and State.presentation_results[channel]
    local signature = snapshot and tostring(snapshot.phase) .. ":" .. tostring(snapshot.detail)
    if result and signature and signature ~= result.before and not Presentation.busy(channel) then
        State.presentation_results[channel] = nil; result = nil
    end
    local detail = why or result and result.detail or snapshot and snapshot.detail
    if detail and detail ~= "" then
        ui_text(tostring(detail):sub(1, 110), true)
        if #tostring(detail) > 110 then CScriptUI.tooltip(detail) end
    end
end

function Presentation.render_setups()
    CScriptUI.section("Combat Setups")
    local snapshot, why = Presentation.snapshot("setup")
    if not snapshot then
        Presentation.result("setup", nil, why); return
    end
    if ImGui and type(ImGui.SetNextItemWidth) == "function" then ImGui.SetNextItemWidth(-1) end
    State.combat_setup_name = input_text_with_hint("##CScriptCombatSetupName", "Name current combat settings...",
        State.combat_setup_name or "", 64)
    local name = State.combat_setup_name
    local selected = false
    for _, row in ipairs(snapshot.rows or {}) do
        if row.name == name then selected = true end
        if CScriptUI.category_chip(tostring(row.name) .. " (" .. tostring(row.field_count or 0) .. ")",
                row.name == name, "combat_setup_row_" .. tostring(row.name), "Select this saved setup; use Apply explicitly.") then
            State.combat_setup_name = row.name; name = row.name; selected = true
        end
    end
    local busy = Presentation.busy("setup", snapshot)
    local typed = ImGui and (type(ImGui.InputText) == "function" or type(ImGui.InputTextWithHint) == "function")
    if not typed then ui_text("Name entry unavailable in this ImGui host.", true) end
    local used = 0; local width = select(1, content_region())
    for _, action in ipairs({
        { "save",  "Save Current", not typed or not name:find("%S") },
        { "apply", "Apply",        not selected }, { "restore", "Restore", snapshot.restore_available ~= true },
        { "delete", "Delete", not selected },
    }) do
        local button_width = CScriptUI.button_width(action[2], "secondary")
        if used > 0 and used + button_width + 8 <= width then ui_same_line() else used = 0 end
        if Presentation.one_press(action[2], "combat_setup_" .. action[1],
                action[1] == "restore" and "Restore prior values while preserving later user edits." or nil,
                action[1] == "delete" and "danger" or "secondary", busy or action[3]) then
            Presentation.queue("setup", action[1], name)
            busy = true
        end
        used = used + button_width + 8
    end
    Presentation.result("setup", snapshot, why)
end

function Presentation.render_farms()
    local snapshot, why = Presentation.snapshot("farm")
    if not snapshot then
        Presentation.result("farm", nil, why); return
    end
    local active = 0
    for _, row in ipairs(snapshot.rows or {}) do
        if row.active == true then
            active = active + 1
            if active == 1 then CScriptUI.section("Active Farm Cycles") end
            ui_text(tostring(row.label or row.key) .. " | " .. tostring(row.phase or "active"), true)
            if Presentation.one_press(row.finish_requested and "Finishing current cycle" or "Finish Current Cycle",
                    "finish_cycle_" .. tostring(row.key), "Finish this running cycle, then stop before the next cycle.",
                    "secondary", row.finish_requested == true or Presentation.busy("farm", snapshot)) then
                Presentation.queue("farm", row.key, row.request_token)
            end
            if row.detail and row.detail ~= "" then CScriptUI.tooltip(row.detail) end
        end
    end
    Presentation.result("farm", snapshot, why)
end

function Presentation.render_retirement()
    if State.retirement_notice_pending then
        ui_text("Eight vehicle maintenance controls retired. Legacy saved routes are ignored.", true)
        CScriptUI.tooltip(table.concat(Presentation.retired_keys, ", ") ..
            ". Page selection is retained. Loading does not rewrite saved files.")
        State.retirement_notice_shown = true; State.retirement_notice_pending = false
    end
end

local function render_virtual_rapid_fire_delay()
    local current = math.max(0, math.min(500,
        math.floor(tonumber(dependencies.Vehicle.GetRapidFireDelay()) or 45)))
    if ImGui and type(ImGui.SliderInt) == "function" then
        local ok, a, b = pcall(ImGui.SliderInt, "Rapid Fire Delay##vehicle_rapid_fire_delay", current, 0, 500, "%d ms")
        local next_value = ok and (type(a) == "number" and a or type(b) == "number" and b) or nil
        if next_value and next_value ~= current then Presentation.queue("delay", next_value) end
    else
        local draft = input_text("Rapid Fire Delay (ms)##vehicle_rapid_fire_delay",
            State.rapid_fire_delay_draft or tostring(current), 4)
        State.rapid_fire_delay_draft = draft
        ui_same_line()
        local value = tonumber(draft)
        if CScriptUI.secondary_button("Apply", "rapid_fire_delay_apply", nil, nil,
                not value or value % 1 ~= 0 or value < 0 or value > 500) then
            Presentation.queue("delay", value)
        end
    end
    CScriptUI.tooltip("Milliseconds between shots. Zero uses the fastest supported cadence.")
end

local function render_feature(key, player_id)
    if player_id == nil and Presentation.is_retired(key) then return end
    if ImGui and type(ImGui.SetNextItemWidth) == "function" then
        pcall(ImGui.SetNextItemWidth, -1)
    end
    if player_id == nil and key == "vehicle_rapid_fire_delay" then
        render_virtual_rapid_fire_delay()
        return
    end
    local hash = player_id == nil and feature_id(key) or player_feature_id(key)
    if not hash then return end
    if player_id == nil then ClickGUI.RenderFeature(hash) else ClickGUI.RenderFeature(hash, player_id) end
end
