function CScriptUI.details_open(id, label)
    State.details_expanded = State.details_expanded or {}
    local open = State.details_expanded[id] == true
    ui_spacing(1)
    if CScriptUI.subtle_button((open and "-  " or "+  ") .. tostring(label or "Details"),
            "details_" .. id, nil, select(1, content_region())) then
        open = not open; State.details_expanded[id] = open
    end
    if open then ui_spacing(1) end
    return open
end

-- Heist status is already a user-facing result. Keep its useful reason without
-- the general copy filter turning every technical word into the same warning.
function CScriptUI.heist_status_message(value, fallback, hide_amounts)
    fallback = fallback or "The current heist status is unavailable."
    if type(value) ~= "string" or #value > 4096 then return fallback end
    local text = value:gsub("^%s+", "")
    for _ = 1, 4 do
        local before = text
        text = text:gsub('^%[string%s+["\'].-["\']%]:%d+:%s*', "")
            :gsub("^@?[^%c]-%.lua:%d+:%s*", "")
        if text == before then break end
    end
    local trace = text:lower():find("stack traceback", 1, true)
    if trace then text = text:sub(1, trace - 1) end
    text = text:gsub("[%c]", " "):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
        :gsub("%$3M Payout", "Apartment payout")
    local lower = text:lower()
    if text == "" or lower:find("0x%x+") or text:find("%a:[/\\]")
        or text:find("[/\\][%w_.%- ]+[/\\]") or lower:find("%.lua:%d+")
        or lower:find("[string", 1, true) or lower:find("[c]:", 1, true) then
        return fallback
    end
    local byte_run = 0
    for token in text:gsub("[,;:%[%]]", " "):gmatch("%S+") do
        if #token >= 16 and token:match("^%x+$") then return fallback end
        byte_run = (token:match("^%x%x$") or token == "?" or token == "??") and byte_run + 1 or 0
        if byte_run >= 4 then return fallback end
    end
    if hide_amounts and (text:find("$", 1, true) or lower:find("predicted", 1, true)
            or lower:find("estimate", 1, true) or lower:find("upper-bound", 1, true)) then
        return fallback
    end
    if #text > 260 then
        local clipped = text:sub(1, 257):match("^(.*)%s")
        return clipped and (clipped .. "...") or fallback
    end
    return text
end

function CScriptUI.heist_inline_status(value, fallback, hide_amounts)
    if not ImGui then return end
    local text = CScriptUI.heist_status_message(value, fallback, hide_amounts)
    if type(ImGui.TextWrapped) == "function" then
        local ok = pcall(ImGui.TextWrapped, text)
        if ok then return end
    end
    if type(ImGui.Text) == "function" then pcall(ImGui.Text, text) end
end

function CScriptUI.heist_automatic_status_text(auto, selected_family)
    if type(auto) ~= "table" then
        return "Automatic payout: status unavailable",
            "The current automatic payout state could not be read."
    end
    local labels = {
        OFF = "Off", WAITING = "Waiting", CONFLICT = "Conflict", UNAVAILABLE = "Unavailable",
        UNSUPPORTED_PARTY = "Crew unsupported", APPLIED = "Crew split applied",
        LOBBY_CUTS_COPIED = "Crew split retained", FINISH_EXISTING_CUTS = "Using existing crew split",
        SUBMITTED = "Completion requested", AWAITING_RESULT = "Waiting for game result",
        AWAITING_LOCAL_RESULT = "Waiting for local result", PAYMENT_OBSERVED = "Local payment observed",
        PAYMENT_UNVERIFIED = "Payment unconfirmed", PAYMENT_MISMATCH = "Payment mismatch",
        LOCAL_FAILURE_OBSERVED = "Local failure observed", LOCAL_SUCCESS_OBSERVED = "Local result observed",
        LOCAL_SUCCESS_BALANCE_OBSERVED = "Local result and balance observed",
        OUTCOME_UNVERIFIED = "Result unconfirmed", REQUEST_TIMEOUT = "Request timed out",
        CLEANUP_PENDING = "Cleanup pending", RESTORE_PENDING = "Restoration pending",
        CONTROLLER_PROCESSED_RESTORE_PENDING = "Restoration pending",
        MISSION_FAILED = "Mission failed", MISSION_FAILED_RESTORE_PENDING = "Mission failed; restoration pending",
        RESTORED = "Temporary changes restored",
    }
    local families = { apartment = "Apartment", cayo = "Cayo Perico", casino = "Diamond Casino", doomsday = "Doomsday" }
    local family = families[auto.family] or "Heist not identified"
    if families[auto.family] and auto.family ~= selected_family then family = family .. " (other heist)" end
    local heading = "Automatic payout: " .. (auto.enabled == true and "Enabled" or "Off")
        .. " | " .. (labels[auto.state] or "Status unavailable") .. " | " .. family
    local fallback = "The current crew payout status could not be confirmed."
    local reason = auto.reason
    if auto.state == "APPLIED" then
        reason = "The crew split was applied. Game payment has not been observed."
    elseif auto.state == "PAYMENT_OBSERVED" then
        reason = "Local payment was observed. Saved payment persistence has not been verified."
    elseif auto.state == "LOCAL_SUCCESS_BALANCE_OBSERVED" then
        reason = "A local passing result and matching balance increase were observed. Saved payment and other players' payments remain unverified."
    elseif auto.state == "LOCAL_SUCCESS_OBSERVED" then
        reason = "A local passing result was observed. A matching balance increase has not been confirmed."
    elseif auto.state == "PAYMENT_MISMATCH" then
        reason = "The observed local payment did not match the expected result. Check the game's result screen."
    end
    return heading, CScriptUI.heist_status_message(reason, fallback, true),
        auto.enabled == true and auto.state ~= "APPLIED" and auto.state ~= "PAYMENT_OBSERVED"
            and auto.state ~= "LOCAL_SUCCESS_BALANCE_OBSERVED"
            and "Enabled alone does not confirm an applied crew split or game payment." or nil
end

function CScriptUI.heist_details(snapshot, selected)
    if not CScriptUI.details_open("heist_state_" .. tostring(snapshot.selected_family), "State & Diagnostics") then return end
    if selected.reason then ui_text(selected.reason, true) end
    for _, field in ipairs(selected.diagnostic_fields or {}) do
        ui_text(
            tostring(field.label or field.key) ..
            ": " .. tostring(field.interpreted_value or field.value or "Unavailable"),
            true)
    end
    for _, control in ipairs(snapshot.setup_controls or {}) do
        if not control.ready then
            ui_text(
                tostring(control.label) .. ": " .. tostring(control.reason or "Unavailable in this context"), true)
        end
    end
    for _, action in ipairs(snapshot.utilities and snapshot.utilities.actions or {}) do
        if action.support ~= "EXPERIMENTAL" and action.support ~= "VERIFIED" then
            ui_text(tostring(action.label) .. ": " .. tostring(action.reason or "Not implemented"), true)
        end
    end
end


function CScriptUI.SyncHeistIntent(snapshot)
    if State.heist_draft_generation ~= snapshot.generation then
        State.heist_drafts, State.heist_batches, State.heist_batch_errors = {}, {}, {}
        State.heist_draft_generation = snapshot.generation
    end
    local identity = tostring(snapshot.generation) .. ":" .. tostring(snapshot.selected_family)
        .. ":" .. tostring(snapshot.selected_user_preset or snapshot.selected_builtin or "")
    if State.heist_confirm_scope ~= identity then
        State.heist_delete_confirm, State.heist_preset_review_confirm = nil, nil
        State.heist_confirm_scope = identity
    end
end

function CScriptUI.heist_grid(id, items, renderer, maximum)
    local width = select(1, content_region())
    local columns = math.min(maximum or 3, width >= 480 and 3 or width >= 320 and 2 or 1)
    local opened = false
    if columns > 1 and resolve_layout_capabilities().tables then
        local ok, result = pcall(ImGui.BeginTable, "##heist_grid_" .. clean_id(id), columns,
            ImGuiTableFlags and ImGuiTableFlags.SizingStretchSame or 0)
        opened = ok and result == true
    end
    local ok, err = pcall(function()
        for index, item in ipairs(items or {}) do
            if opened then
                if (index - 1) % columns == 0 then ImGui.TableNextRow() end
                ImGui.TableSetColumnIndex((index - 1) % columns)
            end
            renderer(item, index)
        end
    end)
    if opened then ImGui.EndTable() end
    if not ok then error(err, 0) end
end

function CScriptUI.heist_board_prompt(family)
    local teleports = module_context and module_context.CScript and module_context.CScript.Teleports
    if not teleports or not teleports.HeistBoardPromptSnapshot then return end
    if teleports.RequestHeistBoardPromptRefresh then teleports.RequestHeistBoardPromptRefresh(family) end
    local prompt = teleports.HeistBoardPromptSnapshot(family) or {}
    if not prompt.available then return end
    if CScriptUI.secondary_button("Teleport to planning screen", "heist_board_prompt_go",
            "Move to the planning screen.") then
        local accepted = teleports.TeleportToHeistBoard(family, prompt.key)
        if not accepted then
            local notices = module_context.Notifications
            if notices then notices.Warning("Planning screen unavailable.") end
        end
    end
end

function CScriptUI.progression_queue(api, key, arguments)
    if type(api) ~= "table" or type(api.QueueAction) ~= "function" then return false end
    local called, ok, reason = pcall(api.QueueAction, key, arguments)
    if called and ok == true then return true, reason end
    local message = tostring((called and reason or ok) or "Action could not be queued.")
    local notifications = module_context and module_context.Notifications
    if notifications and type(notifications.Warning) == "function" then
        pcall(notifications.Warning, message, 4000)
    end
    return false, message
end

function CScriptUI.progression_select(label, id, items, current)
    local index = 1
    for i, item in ipairs(items) do
        if item.key == current then
            index = i; break
        end
    end
    local chosen, changed = CScriptUI.value_stepper(label, index, 1, #items, 1, id, nil, items[index].label)
    return changed and items[chosen] and items[chosen].key or current, changed
end

local function render_heist_manager(page)
    local _,heists=economy_services()
    if not heists then CScriptUI.empty_state('Heist Tools unavailable.');return end
    local model=safe_ui_snapshot(heists,'Snapshot')or{}
    local families={{key='apartment',label='Apartment'},{key='cayo',label='Cayo Perico'},
        {key='casino',label='Diamond Casino'},{key='doomsday',label='Doomsday'}}
    local family=model.selected_family or 'apartment'
    local chosen,changed=CScriptUI.tab_bar('heist_families',families,family)
    if changed and chosen~=family then
        local ok=heists.SelectFamily(chosen)
        if ok then model=heists.Snapshot();family=model.selected_family end
    end
    -- One selection model per family. No legacy setup dropdown or parallel tab selection.
    CScriptUI.section('Setup')
    for _,selector in ipairs(model.selectors or{})do
        local labels,index={},selector.default or 1
        local selected=model.selection and model.selection[selector.key]
        for i,option in ipairs(selector.options or{})do
            labels[i]=tostring(option.label)
            if option.value==selected then index=i end
        end
        if #labels>0 then
            local next_index,edited=CScriptUI.compact_selector('heist_rc3_'..family..'_'..selector.key,
                selector.label,index,labels)
            if edited and selector.options[next_index]then
                local accepted,why=heists.SetOption(selector.key,selector.options[next_index].value)
                if accepted then model=heists.Snapshot()else CScriptUI.heist_inline_status(why)end
            end
        end
    end
    CScriptUI.section('Actions')
    CScriptUI.heist_grid('heist_rc3_actions',{'prepare','finish'},function(action)
        if action=='prepare'then
            if CScriptUI.primary_button('Apply Preps','heist_rc3_prepare',
                'Apply the selected preparation profile using the recovered controller.')then
                CScriptUI.progression_queue(heists,'prepare')
            end
        elseif CScriptUI.primary_button('Instant Finish','heist_rc3_finish',
            family=='doomsday'and 'Use the original CScript Doomsday Instant Finish.'or
            'Submit once through the recovered finale controller. Game completion is not guaranteed.')then
            CScriptUI.progression_queue(heists,'instant_finish')
        end
    end,2)
    if model.capabilities and model.capabilities.board then
        if CScriptUI.secondary_button('Refresh Board','heist_rc3_board',
            'Refresh the existing Apartment board without changing the heist selection.')then
            CScriptUI.progression_queue(heists,'board_refresh')
        end
    end
    local last=model.last_result
    if last and last.message then
        ui_text((last.status=='FAILED'and 'Not applied: 'or last.status=='EXPIRED'and 'Expired: 'or'')..last.message,true)
    end
    if model.prep_status then ui_text(model.prep_status,true)end
    if model.finish_status then ui_text(model.finish_status,true)end
    CScriptUI.section('Options')
    local toggles=model.toggles or{}
    local value,edited=CScriptUI.toggle_row('Solo Launch',toggles.solo==true,'heist_rc3_solo',
        'Arm the recovered standalone launch controllers before opening the finale lobby.')
    if edited then CScriptUI.progression_queue(heists,'solo_launch_toggle',{enabled=value})end
    value,edited=CScriptUI.toggle_row('Max Payout',toggles.payout==true,'heist_rc3_payout',
        'Run the recovered payout controller. An estimate is not confirmed game payment.')
    if edited then CScriptUI.progression_queue(heists,'payout_auto',{enabled=value})end
    if model.capabilities and model.capabilities.bonus then
        value,edited=CScriptUI.toggle_row('12M Bonus',toggles.bonus==true,'heist_rc3_bonus',
            'Use the recovered CMM controller; its current-game eligibility checks still apply.')
        if edited then CScriptUI.progression_queue(heists,'bonus_toggle',{enabled=value})end
        if model.bonus_status then ui_text(model.bonus_status,true)end
    end
    if model.solo_status then ui_text(model.solo_status,true)end
    if model.payout_status then ui_text(model.payout_status,true)end
    if model.capabilities and model.capabilities.manual_cuts then
        CScriptUI.section('Cuts')
        if type(model.cuts)=='table'and #model.cuts==4 then
            State.heist_rc3_cuts=State.heist_rc3_cuts or{}
            local draft=State.heist_rc3_cuts[family]
            if not draft then draft={};for i=1,4 do draft[i]=tostring(model.cuts[i])end;State.heist_rc3_cuts[family]=draft end
            CScriptUI.heist_grid('heist_rc3_cuts',{1,2,3,4},function(slot)
                draft[slot]=input_text('Player '..slot..'##heist_rc3_cut_'..slot,draft[slot],16)
            end,2)
            if CScriptUI.secondary_button('Use Current Cuts','heist_rc3_copy')then
                for i=1,4 do draft[i]=tostring(model.cuts[i])end
            end
            if CScriptUI.primary_button('Apply Cuts','heist_rc3_apply_cuts')then
                local values,valid={},true
                for i=1,4 do
                    local n=tonumber(draft[i])
                    if not n or n%1~=0 or n<0 or n>9999 then valid=false;break end
                    values[i]=n
                end
                if valid then CScriptUI.progression_queue(heists,'cuts_apply',{values=values})
                else CScriptUI.heist_inline_status('Enter four whole percentages from 0 to 9999.')end
            end
        else
            State.heist_rc3_cuts=State.heist_rc3_cuts or{};State.heist_rc3_cuts[family]=nil
            ui_text(model.cuts_message or 'Open your finale board to read the crew cuts.',true)
        end
    end
    CScriptUI.section('Travel')
    if family=='cayo'then
        local teleports=module_context and module_context.CScript and module_context.CScript.Teleports
        if teleports and type(teleports.TeleportToKosatka)=='function'then
            if CScriptUI.secondary_button('Teleport to Kosatka','heist_rc3_kosatka',
                'Travel to your own Kosatka and its Cayo planning board.')then
                local accepted,reason=teleports.TeleportToKosatka()
                if not accepted then CScriptUI.heist_inline_status(reason or 'Kosatka travel is unavailable.')end
            end
        else ui_text('Kosatka teleport service unavailable.',true)end
        CScriptUI.heist_board_prompt(family)
    else CScriptUI.progression_travel('Heists',family)end
end

local function render_business_manager(page)
    Presentation.render_farms()
    local _, _, businesses = economy_services()
    if not businesses then return end
    local automation = module_context and module_context.CScript and module_context.CScript.BusinessAutomation
    local snapshot = safe_ui_snapshot(businesses, "Snapshot") or {}
    -- A real control or service must exist for every entry in this list.
    -- Pure ownership/read-only catalog entries never appear as empty pages.
    local actionable = {
        bunker=true, acid_lab=true, nightclub=true, special_cargo=true,
        hangar=true, mc_cocaine=true, mc_meth=true, mc_cash=true,
        mc_weed=true, mc_documents=true
    }
    local short_labels = {
        bunker="Bunker", acid_lab="Acid Lab", nightclub="Nightclub",
        special_cargo="CEO Cargo", hangar="Hangar",
        mc_cocaine="Cocaine", mc_meth="Meth", mc_cash="Cash",
        mc_weed="Weed", mc_documents="Documents",
    }
    local items = {}
    for _, item in ipairs(snapshot.catalog or businesses.Catalog or {}) do
        if actionable[item.key] then
            items[#items + 1] = { key = item.key, label = tostring(item.name or item.key),
                short_label = short_labels[item.key] }
        end
    end
    if #items == 0 then return end
    local chosen = State.progression_business or "bunker"
    if not actionable[chosen] then chosen = "bunker" end
    if snapshot.selected_business ~= chosen and type(businesses.SelectBusiness) == "function" then
        businesses.SelectBusiness(chosen); snapshot = safe_ui_snapshot(businesses, "Snapshot") or {}
    end
    local next_key,changed=CScriptUI.business_tabs(items,chosen)
    if changed and next_key~=chosen then
        State.progression_business=next_key;State.business_request_error=nil
        businesses.SelectBusiness(next_key)
        return
    end
    State.progression_business = chosen
    if chosen ~= "hangar" then
        CScriptUI.section("Travel")
        CScriptUI.progression_travel("Businesses", chosen)
    end
    if type(businesses.RequestVisibleRefresh) == "function" then businesses.RequestVisibleRefresh() end
    local selected = snapshot.selected or {}
    local modes = automation and type(automation.Snapshot) == "function" and automation.Snapshot(chosen) or {}
    local factory = chosen == "bunker" or chosen == "acid_lab" or chosen:find("mc_", 1, true) == 1
    local sale_farm = chosen == "bunker" or chosen:find("mc_", 1, true) == 1
    local outcome
    local function call(owner, key, ...)
        if not owner or type(owner[key]) ~= "function" then return false end
        local called, ok, why = pcall(owner[key], ...)
        State.business_request_error = not called and tostring(ok)
            or ok == false and tostring(why or "Action could not start.") or nil
        if called and type(why) == "table" and why.skipped then
            local skipped = 0; local first
            for name, reason in pairs(why.skipped) do
                skipped = skipped + 1; first = first or tostring(name) .. ": " .. tostring(reason)
            end
            if skipped > 0 then
                State.business_request_error = ("Started %d; skipped %d. %s"):format(
                    #(why.started or {}), skipped, first or "")
            end
        end
        local logger = module_context and module_context.Logger
        if logger and type(logger.Info) == "function" then
            logger.Info(
                "business=" ..
                chosen ..
                " action=" ..
                key .. " ok=" .. tostring(called and ok ~= false) .. " reason=" ..
                tostring(State.business_request_error or ""), "BusinessAction")
        end
        if State.business_request_error and outcome then outcome(State.business_request_error) end
        return called and ok ~= false
    end
    local function request(key, value) return call(automation, "Request", key, chosen, value) end
    outcome = function(detail)
        if type(detail) ~= "string" or detail == "" then return end
        ui_text(detail:sub(1, 110), true); if #detail > 110 then CScriptUI.tooltip(detail) end
    end
    local pocket = chosen == "hangar" and module_context and module_context.CScript and
        module_context.CScript.HangarPocket
    local pocket_state = pocket and type(pocket.Snapshot) == "function" and pocket.Snapshot() or {}
    local cargo_farm = pocket and module_context.CScript.CargoFarm
    local cargo_state = cargo_farm and cargo_farm.Snapshot() or {}

    local pocket_busy = cargo_state.running == true or pocket_state.running == true or pocket_state.cleanup_pending == true or
        pocket_state.action and pocket_state.action.busy == true
    local stock = pocket_state.stock or selected.stock
    if stock ~= nil and chosen ~= "hangar" then
        local count = "Stock " .. tostring(stock) .. " / " .. tostring(selected.capacity or "--")
        if factory and selected.supplies ~= nil then
            count = count .. "   Supplies " .. tostring(selected.supplies) ..
                "%"
        end
        ui_text(count, true)
    end
    if State.business_request_error then
        outcome(State.business_request_error)
    elseif snapshot.last_action and snapshot.last_action.ok == false then
        outcome(snapshot.last_action.detail)
    end
    local hangar_draft
    if pocket then
        local cfg = pocket_state.config or {}
        State.hangar_pocket_draft = State.hangar_pocket_draft or {
            limit = tostring(cfg.limit or 100),
            target_value = tostring(cfg.target_value or 2550000),
            step = tostring(cfg.step or 1),
            type_index = cfg.type_index or 1,
            delay = tostring((cfg.delay_ms or 1000) / 1000)
        }
        local draft = State.hangar_pocket_draft
        hangar_draft = draft
        CScriptUI.section("Cargo")
        if stock ~= nil then ui_text("In storage: " .. tostring(stock) .. " crates", true) end
        if not pocket_busy then
            local types = pocket_state.type_items or {}
            if #types > 0 then
                draft.type_index = CScriptUI.value_stepper("Cargo Type", draft.type_index, 1, #types,
                    1, "hangar_type", nil, types[draft.type_index] or types[1])
            end
            ui_text("Target payout")
            if ImGui and type(ImGui.SetNextItemWidth) == "function" then
                ImGui.SetNextItemWidth(math.max(80, math.min(245, select(1, content_region()) - 12)))
            end
            draft.target_value = input_text("GTA$##hangar_value", draft.target_value, 11)
        end

        -- The supplier itself owns the toggle state. It becomes OFF on
        -- COMPLETE/STOPPED/REJECTED without any persistent UI fake flag.
        local value_running = pocket_state.running == true and cfg.target_mode == 1
        local value_on, changed_value = CScriptUI.toggle_row("Fill to Value", value_running,
            "hangar_fill_to_value", "Add cargo toward the selected payout. Stops automatically when finished.")
        if changed_value then
            if value_on and not pocket_busy then
                call(pocket, "FillToValue", tonumber(draft.target_value) or false, draft.type_index)
            elseif not value_on and value_running then
                call(pocket, "Stop")
            end
            pocket_state = pocket.Snapshot() or pocket_state
            cfg = pocket_state.config or cfg
            pocket_busy = cargo_state.running == true or pocket_state.running == true or
                pocket_state.cleanup_pending == true or pocket_state.action and pocket_state.action.busy == true
        end

        -- Keep the three controls together immediately below cargo selection.
        if not pocket_busy then
            if CScriptUI.secondary_button("Open Computer", "hangar_open_computer",
                "Open your Hangar computer.") then call(pocket, "OpenComputer") end
            if CScriptUI.row_can_pair(CScriptUI.button_width("Open Computer")+
                CScriptUI.button_width("Clear Cargo")+8) then ui_same_line() end
            if CScriptUI.danger_button("Clear Cargo", "hangar_clear_cargo",
                "Remove all Hangar cargo.") then call(pocket, "ClearCargo") end
        end
        if value_running and pocket_state.quote_valid and pocket_state.estimated_value then
            ui_text(("Estimated payout: GTA$%d"):format(pocket_state.estimated_value),true)
        end
        if pocket_state.running and pocket_state.phase and pocket_state.phase~="IDLE" then
            local phases={ARMED="Preparing",PREPARING="Preparing",
                WAIT_TRANSACTION="Adding cargo",WAIT_DELAY="Adding cargo",DRAINING="Finishing"}
            ui_text(phases[pocket_state.phase] or "Working",true)
        elseif pocket_state.phase=="REJECTED" or pocket_state.phase=="STOPPED" then
            if pocket_state.reason then outcome(tostring(pocket_state.reason)) end
        end
        if pocket_state.action and pocket_state.action.phase=="STOPPED" and pocket_state.action.reason then
            outcome(tostring(pocket_state.action.reason))
        end
    end
    if not pocket then CScriptUI.section("Actions") end


    local sale_running = false
    -- Multiple farms may run in sequence; skip internal scheduling notes.
    if sale_farm then
        local mc = chosen ~= "bunker"
        local farm = (mc and snapshot.mc_farm or snapshot.bunker_farm) or {}
        sale_running = farm.active == true
        if farm.active then
            if CScriptUI.danger_button("Stop Auto Farm", "business_farm_stop") then
                call(businesses, mc and "StopMCFarm" or "StopBunkerFarm", "Stopped from CScript UI.")
            end
        else
            if CScriptUI.primary_button("Start Auto Farm", "business_farm_start", "Produces stock, sells it and repeats after settlement.") then
                if mc then call(businesses, "StartMCFarm", chosen, true) else call(businesses, "StartBunkerFarm", true) end
            end
        end
        if farm.active or farm.reason then
            ui_text(tostring(farm.phase or "IDLE") .. "   Cycles " .. tostring(farm.cycles or 0), true)
            if farm.wait_reason then
                outcome(tostring(farm.wait_reason))
            elseif farm.reason then
                outcome(tostring(farm.reason))
            end
        end
    end
    if sale_farm or chosen == "hangar" then
        if CScriptUI.primary_button("Instant Finish Sale", "business_complete_active_sale", pocket_busy and "Stop cargo fill and let its current delivery settle first." or nil, nil, pocket_busy) then
            CScriptUI.progression_queue(businesses, "complete_active_sale")
        end
    end
    if modes.cleanup_pending then ui_text("Restoring production settings...", true) end
    CScriptUI.section("Automation")
    if modes.stock_farm_supported and automation and not sale_running then
        local farm = modes.stock_farm or {}
        local enabled, toggled = CScriptUI.toggle_row("Keep Stock Full", farm.running == true, "business_stock_farm",
            "Automatically produces to capacity and resumes after stock is sold. Does not launch a sale.")
        if toggled then
            if enabled then
                call(automation, "StartStockFarm", chosen, true)
            else
                call(automation, "StopStockFarm",
                    chosen)
            end
        end
        if farm.running then
            ui_text(tostring(farm.phase or "Producing"), true)
            if farm.reason then CScriptUI.tooltip(tostring(farm.reason)) end
        elseif farm.phase == "FAILED" then
            outcome(farm.reason)
        end
    end
    if not sale_running and not pocket_busy and not (modes.stock_farm or {}).running then
        local label = (chosen == "hangar" or chosen == "special_cargo") and "Fast Staff Orders" or "Fast Production"
        local active, toggled = CScriptUI.toggle_row(label, modes.fast_production == true, "business_fast_production",
            (chosen == "hangar" or chosen == "special_cargo") and
            "Accelerates paid staff orders; GTA delivers the cargo."
            or chosen == "nightclub" and "Requires assigned technicians and linked businesses." or
            "Speeds stock production.")
        if toggled then request("production", active) end
    end
    if factory and not sale_running and not (modes.stock_farm or {}).running then
        local quick, edited = CScriptUI.toggle_row("Keep Supplies Full", modes.fast_supplies == true,
            "business_fast_supplies")
        if edited then request("fast_supplies", quick) end
    end
    if chosen == "hangar" then
        CScriptUI.section("Travel")
        CScriptUI.progression_travel("Businesses", chosen)
    end
    if chosen:find("mc_", 1, true) == 1 then
        local enabled, edited = CScriptUI.toggle_row("Solo Sale Routes", (snapshot.solo_mc_routes or {}).active ==
            true, "business_solo_mc_routes")
        if edited then CScriptUI.progression_queue(businesses, "solo_mc_routes", enabled) end
    end
    if CScriptUI.details_open("business_bulk_actions", "All Businesses") then
        if automation and type(automation.StartAllStockFarms) == "function" then
            if CScriptUI.primary_button("Produce All Businesses", "business_produce_all",
                    "Keeps stock full at owned factories and Nightclub. Staff orders and sales are separate.") then
                call(automation, "StartAllStockFarms", true)
            end
            if CScriptUI.danger_button("Stop All Production Farms", "business_produce_all_stop") then
                call(automation,
                    "StopAllStockFarms")
            end
        end
        if CScriptUI.secondary_button("Resupply All", "business_resupply_all") then
            CScriptUI.progression_queue(
                businesses, "resupply_all")
        end
        if CScriptUI.secondary_button("Refresh", "business_refresh_selected") then
            CScriptUI.progression_queue(
                businesses, "refresh_selected")
        end
        if modes.production_result then outcome(modes.production_result) end
        if modes.supply_result and modes.supply_result ~= modes.production_result then outcome(modes.supply_result) end
    end

end


local function teleport_action(callback, ...)
    local ok, result, detail = pcall(callback, ...)
    if ok and result ~= false then
        State.teleport_action_error = nil; return true
    end
    local message = tostring(ok and detail or result or "Teleport action failed.")
    State.teleport_action_error = message
    local notifications = module_context and module_context.Notifications
    if notifications and type(notifications.Warning) == "function" then notifications.Warning(message, 5500) end
    return false
end


function CScriptUI.progression_travel(scope, selected)
    local teleports = module_context and module_context.CScript and module_context.CScript.Teleports
    if not teleports then return end
    local map = scope == "Heists" and {
            casino = { "arcade_entrance", "Teleport to Arcade" },
            doomsday = { "facility_entrance", "Teleport to Facility" },
            apartment = { "heist_apartment", "Teleport to Heist Apartment" }
        }
        or {
            bunker = { "bunker", "Teleport to Bunker" },
            hangar = { "hangar", "Teleport to Hangar" },
            nightclub = { "nightclub", "Teleport to Nightclub" },
            special_cargo = { "office", "Teleport to CEO Office" },
            acid_lab = { "acid_lab_locator", "Teleport to Acid Lab" },
            mc_cocaine = { "mc_cocaine", "Teleport to Cocaine Lockup" },
            mc_meth = { "mc_meth", "Teleport to Meth Lab" },
            mc_cash = { "mc_cash", "Teleport to Cash Factory" },
            mc_weed = { "mc_weed", "Teleport to Weed Farm" },
            mc_documents = { "mc_documents", "Teleport to Document Office" }
        }
    local item = map[selected]
    if item and CScriptUI.secondary_button(item[2], "travel_selected_" .. scope,
            selected == "apartment" and "Travel to your heist apartment." or "Travel to your property entrance.") then
        teleport_action(teleports.TeleportDestination, item[1])
    end
    if scope == "Heists" and item then CScriptUI.heist_board_prompt(selected) end
    if scope == "Businesses" and selected == "special_cargo" then
        if CScriptUI.secondary_button("Open CEO Cargo Computer", "open_ceo_cargo_computer", "Open the cargo computer anywhere while registered as CEO.") then
            teleport_action(teleports.OpenCargoComputer)
        end
        local businesses = module_context and module_context.CScript and module_context.CScript.Businesses
        local business_snapshot = safe_ui_snapshot(businesses, "Snapshot") or {}
        local status = (business_snapshot.statuses or {}).special_cargo or business_snapshot.selected or {}
        local details = status.warehouse_details or {}
        for slot = 0, 4 do
            local warehouse = details[slot]
            if warehouse and type(warehouse.property) == 'number' and warehouse.property >= 1 and warehouse.property <= 22 then
                local label = ('Open Warehouse %d Laptop'):format(slot + 1)
                if CScriptUI.secondary_button(label, 'open_cargo_warehouse_' .. slot,
                        'Opens this owned warehouse computer (property ' .. tostring(warehouse.property) .. '). Warehouse selection is rechecked before launch.') then
                    teleport_action(teleports.OpenWarehouseComputer, slot, warehouse.property)
                end
            end
        end
    end
    local snapshot = safe_ui_snapshot(teleports, "Snapshot") or {}
    local result = selected == "special_cargo" and snapshot.cargo_result or nil
    if result then ui_text("Travel: " .. tostring(result.message), true) end
    if State.teleport_action_error then ui_text("Travel: " .. State.teleport_action_error, true) end
end

local function render_protections_hardening(page)
    -- Owner/private builds do not install this optional presentation bridge.
    -- Honor an installed access provider, including failure, without making a
    -- missing UI helper prevent an initialized protection module from drawing.
    if type(CScriptUI.public_category_locked) == "function" then
        local checked, locked = pcall(CScriptUI.public_category_locked, "modules.protections")
        if not checked or type(locked) ~= "boolean" then
            CScriptUI.empty_state("Protection access unavailable", "The access provider could not be checked. Try again after it is ready.")
            return
        end
        if locked then
            CScriptUI.empty_state("Supporter access required", "CScript Protections unlocks with an active Supporter entitlement.")
            return
        end
    end
    local protections = module_context and module_context.CScript and module_context.CScript.Protections
    if type(protections) ~= "table" or type(protections.GetSpawnRadius) ~= "function"
        or type(protections.SetSpawnRadius) ~= "function" then
        CScriptUI.empty_state("Protections unavailable", "The protection module has not finished starting. Try this page again after startup.")
        return
    end
    local windows = page and page.windows or {}
    local policy = safe_ui_snapshot(protections, "PolicySnapshot")
    local unsupported = policy and policy.unavailable_features or {}
    local width = select(1, content_region())
    local grouped = #windows >= 2 and width >= compact_card_min_width() and ImGui
        and type(ImGui.BeginTable) == "function" and type(ImGui.EndTable) == "function"
        and type(ImGui.TableNextRow) == "function" and type(ImGui.TableSetColumnIndex) == "function"
    local outer = false
    if grouped then
        local ok, visible = pcall(ImGui.BeginTable, "##CScriptProtectionGroupGrid", 2,
            ImGuiTableFlags and ImGuiTableFlags.SizingStretchSame or 0)
        outer = ok and visible == true
    end
    -- One table row with independent vertical stacks. The previous one-row-
    -- per-pair layout inserted a blank region below every shorter card.
    local weight, split, best, subtotal = 0, 1, math.huge, 0
    for _, window in ipairs(windows) do weight = weight + #(window[2] or {}) + 2 end
    for index = 1, #windows - 1 do
        subtotal = subtotal + #(windows[index][2] or {}) + 2
        local diff = math.abs(weight - 2 * subtotal)
        if diff < best then split, best = index, diff end
    end
    local render_ok, render_err = pcall(function()
        if outer then ImGui.TableNextRow() end
        for index, window in ipairs(windows) do
            local title, keys = window[1], window[2]
            local expanded = true
            if outer and (index == 1 or index == split + 1) then
                ImGui.TableSetColumnIndex(index == 1 and 0 or 1)
            end
            if expanded then
                CScriptUI.card("protection_group_" .. index, title, nil, function()
                    local width = select(1, content_region())
                    -- Each card owns its widget columns; the cards themselves stay full width.
                    local minimum_width = math.max(600, measured_text_width("Automatic Camera Recovery") * 2 + 112)
                    local columns = width >= minimum_width and #keys > 1
                        and ImGui and type(ImGui.BeginTable) == "function" and type(ImGui.EndTable) == "function"
                        and type(ImGui.TableNextRow) == "function" and type(ImGui.TableSetColumnIndex) == "function"
                    local opened = false
                    if columns then
                        local ok, visible = pcall(ImGui.BeginTable, "##CScriptProtectionControls_" .. index, 2,
                            ImGuiTableFlags and ImGuiTableFlags.SizingStretchSame or 0)
                        opened = ok and visible == true
                    end
                    local function draw(key)
                        if key == "protect_spawn_radius" then
                            local read_ok, current = pcall(protections.GetSpawnRadius)
                            if not read_ok or type(current) ~= "number" or current ~= current
                                or math.abs(current) == math.huge then
                                ui_text("Spawn radius unavailable.", true)
                                return
                            end
                            if ImGui and type(ImGui.SliderInt) == "function" then
                                if type(ImGui.SetNextItemWidth)=="function" then pcall(ImGui.SetNextItemWidth,-1) end
                                local ok, a, b = pcall(ImGui.SliderInt, "Spawn Radius##protect_spawn_radius", current, 5, 5000, "%d m")
                                local value = ok and (type(b) == "number" and b or type(a) == "number" and a) or nil
                                if value and value ~= current then protections.SetSpawnRadius(value) end
                            else
                                ui_text("Spawn Radius: " .. tostring(current) .. " m", true)
                            end
                            CScriptUI.tooltip("Rejects incoming creation for enabled entity types within 5 to 5,000 metres before it is applied. This also filters legitimate traffic, mission entities and friends' spawns. Player characters and your own entities remain allowed; existing entities are not removed.")
                            return
                        end
                        render_feature(key)
                        if unsupported[key] == true then
                            ui_text("Unavailable on this game version.", true)
                            CScriptUI.tooltip(policy.detail or "The event mapping has not been verified for this game version.")
                        end
                        if key == "desync_protection" then
                            local status = safe_ui_snapshot(protections, "DesyncSnapshot")
                            if status and status.state == "UNAVAILABLE" then
                                ui_text("Not supported on this game build.", true)
                            end
                        elseif key == "protect_self_isolation" and type(protections.IsOn) == "function" then
                            local ok, enabled = pcall(protections.IsOn, key)
                            if ok and enabled == true then
                                local owner = module_context and module_context.CScript and module_context.CScript.Player
                                local status = safe_ui_snapshot(owner, "SelfIsolationSnapshot")
                                if not status or status.registered ~= true then
                                    ui_text("Local contact filter unavailable.", true)
                                end
                                if status and status.detail then CScriptUI.tooltip(status.detail) end
                            end
                        end
                    end
                    if opened then
                        local ok, err = pcall(function()
                            for key_index, key in ipairs(keys) do
                                if key_index % 2 == 1 then ImGui.TableNextRow() end
                                ImGui.TableSetColumnIndex((key_index - 1) % 2)
                                draw(key)
                            end
                        end)
                        ImGui.EndTable()
                        if not ok then error(err, 0) end
                    else
                        for _, key in ipairs(keys) do draw(key) end
                    end
                    if title == "Script Event Protection" and policy and policy.active == true
                        and (policy.registered ~= true or policy.armed == false) then
                        ui_text("Script-event filter unavailable; registration is pending.", true)
                    elseif title == "Spawn Protection" then
                        local status = safe_ui_snapshot(protections, "SpawnSnapshot")
                        if not status then
                            ui_text("Status unavailable", true)
                        else
                            local enabled = status.enabled or {}
                            local active = enabled.vehicle == true or enabled.ped == true or enabled.object == true
                            local ingress=type(status.ingress)=="table" and status.ingress or {}
                            local label
                            if not active then label=nil
                            elseif status.removal_pending==true then label="Restarting protection..."
                            elseif status.queued==true then label="Starting protection..."
                            elseif status.available~=true or status.registered~=true or status.armed~=true then
                                label="Protection unavailable"
                            elseif status.position_ready~=true then label="Waiting for position..."
                            elseif ingress.observed==true and display_count(ingress.host_entries)>0
                                and display_count(ingress.forwarded)==0 then
                                label=ingress.callbacks_enabled==false and "Protection paused" or "Protection unavailable"
                            elseif ingress.observed==true and display_count(ingress.forwarded)>0
                                and display_count(status.entries)==0 then label="Protection unavailable"
                            elseif display_count(status.entries)==0
                                or (ingress.observed==true and display_count(ingress.host_entries)==0) then
                                label="Waiting for traffic..."
                            end
                            if label then ui_text(label,true) end
                        end
                    end
                end)
            end
        end
    end)
    if outer then ImGui.EndTable() end
    if not render_ok then error(render_err, 0) end
end


function CScriptUI.editor_field(label, id, value, maximum, compact)
    local width = select(1, content_region())
    if compact then
        -- Each account tile has its own label, value and Set control.
        -- This avoids 3 squeezed columns inside a 2-column ImGui table.
        ui_text(PlayersPage.fit(tostring(label), math.max(70,width-8)))
        CScriptUI.tooltip(label)
        if ImGui and type(ImGui.SetNextItemWidth) == "function" then
            pcall(ImGui.SetNextItemWidth, math.max(70,width-70))
        end
        local field=input_text("##"..id,value,maximum)
        if width>=154 then ui_same_line() end
        return field
    end
    local origin
    if ImGui and type(ImGui.GetCursorPosX) == "function" and type(ImGui.SetCursorPosX) == "function" then
        local ok, x = pcall(ImGui.GetCursorPosX)
        if ok then origin = tonumber(x) end
    end
    local columns = origin and width >= 440
    local label_width = math.min(210, math.floor(width * 0.40))
    local action_width = 76
    ui_text(columns and PlayersPage.fit(label, label_width - 8) or label)
    CScriptUI.tooltip(label)
    if columns then
        ui_same_line(); pcall(ImGui.SetCursorPosX, origin + label_width)
    end
    local field_width = math.max(60, width - (columns and label_width or 0) - action_width - 8)
    if ImGui and type(ImGui.SetNextItemWidth) == "function" then pcall(ImGui.SetNextItemWidth, field_width) end
    local result = input_text("##" .. id, value, maximum)
    if width >= 180 then
        ui_same_line()
        if origin then pcall(ImGui.SetCursorPosX, origin + width - action_width) end
    end
    return result
end

function CScriptUI.profile_editor_row(economy, profile, item, compact)
    if item.kind == "read_only" or not item.available or item.editable == false then
        if compact then ui_text(tostring(item.label).."  n/a",true) end
        return
    end
    local key = tostring(item.key)
    State.recovery_profile_drafts = State.recovery_profile_drafts or {}
    local drafts = State.recovery_profile_drafts
    local draft = drafts[key]
    local formatted = (type(item.value) == "number" or type(item.value) == "string") and tostring(item.value) or ""
    -- Show readable minute values, not a wall of floating-point digits.
    if type(item.value) == "number" and key:find("_minutes",1,true) then
        formatted = string.format("%.1f",item.value)
    end
    if not draft then
        draft = { text = formatted, revision = profile.revision }; drafts[key] = draft
    end
    if draft.revision ~= profile.revision and not draft.dirty then
        draft.text = formatted; draft.revision = profile.revision
    end
    local text = CScriptUI.editor_field(tostring(item.label), "profile_input_" .. key, draft.text, 48, compact)
    if text ~= draft.text then
        draft.text = text; draft.dirty = true; draft.error = nil
    end
    local value, reason
    if type(economy.ProfileParse) == "function" then value, reason = economy.ProfileParse(key, draft.text) end
    local busy = profile.commit_status == "Applying" or profile.commit_status == "Checking" or
        profile.commit_status == "Settling" or profile.commit_status == "Restoring"
    if CScriptUI.secondary_button("Set", "profile_apply_" .. key, nil,
            compact and 62 or 76, busy or value == nil) and not busy and value ~= nil then
        if key == "kd_ratio" then
            local deaths, suicides
            for _, other in ipairs(profile.items or {}) do
                if other.key == "player_deaths" then
                    deaths = other.value
                elseif other.key == "player_suicides" then
                    suicides = other.value
                end
            end
            local plan, why
            if type(economy.ProfileRatioPlan) == "function" and deaths ~= nil and suicides ~= nil then
                plan, why = economy.ProfileRatioPlan(value, deaths, suicides)
            end
            if plan then
                State.progression_kd_request = {
                    value = value,
                    text = draft.text,
                    deaths = deaths,
                    suicides = suicides,
                    kills = plan.kills,
                    total_deaths = plan.deaths
                }
                draft.error = nil
            else
                draft.error = why or "Waiting for kills and deaths."
            end
        else
            local ok, why = CScriptUI.progression_queue(economy, "profile_stat_set:" .. key, value)
            if not ok then draft.error = why end
        end
        -- Queue acceptance is not confirmation; keep the edited text until a later refresh.
    end
    local request = key == "kd_ratio" and State.progression_kd_request
    if request and request.text ~= draft.text then
        State.progression_kd_request = nil; request = nil
    end
    if request then
        local text = ("Set KD to %s? This also sets kills to %s and deaths to %s. Suicides stay unchanged.")
            :format(tostring(request.value), tostring(request.kills), tostring(request.total_deaths))
        local answer = CScriptUI.confirm_dialog("account_kd_counters", text)
        if answer == "confirm" then
            local deaths, suicides
            for _, other in ipairs(profile.items or {}) do
                if other.key == "player_deaths" then
                    deaths = other.value
                elseif other.key == "player_suicides" then
                    suicides = other.value
                end
            end
            if deaths == request.deaths and suicides == request.suicides and not busy then
                local ok, why = CScriptUI.progression_queue(economy, "profile_stat_set:kd_ratio", request.value)
                if not ok then draft.error = why end
            else
                draft.error = "Profile changed. Review the KD edit again."
            end
            State.progression_kd_request = nil
        elseif answer == "cancel" then
            State.progression_kd_request = nil
        end
    end
    if draft.dirty and value == nil then ui_text(tostring(reason or "Enter a valid value."), true) end
    if draft.error then ui_text(draft.error, true) end
    if not compact then ui_spacing(1) end
end

function CScriptUI.account_grid(id, items, renderer)
    local width=select(1,content_region())
    if width>=480 then
        return CScriptUI.heist_grid("account_"..id,items,renderer,2)
    end
    for index,item in ipairs(items or {}) do renderer(item,index) end
end

local function render_recovery_manager()
    local economy = economy_services()
    if not economy then return end
    local profile = safe_ui_snapshot(economy, "ProfileStatsSnapshot") or {}
    local scope = tostring(profile.account)..":"..tostring(profile.slot)..":"..tostring(profile.generation)
    if State.recovery_profile_scope ~= scope then
        State.recovery_profile_scope=scope
        State.recovery_profile_drafts={}
        State.progression_skill_drafts={}
        State.account_custom={name="MPX_",value="",message=nil,read_value=nil}
        State.progression_max_skills_confirm=nil
        State.progression_kd_request=nil
    end
    if type(economy.RequestVisibleProfileRefresh)=="function" then
        economy.RequestVisibleProfileRefresh()
    end

    local item_map={}
    for _,item in ipairs(profile.items or {})do item_map[item.key]=item end

    local function group(title,id,keys)
        local rows={}
        for _,key in ipairs(keys)do
            local item=item_map[key]
            if item then rows[#rows+1]=item end
        end
        if #rows==0 then return end
        CScriptUI.section(title)
        CScriptUI.account_grid(id,rows,function(item)
            CScriptUI.profile_editor_row(economy,profile,item,true)
        end)
    end

    if CScriptUI.secondary_button("Refresh Stats","account_refresh_stats")then
        CScriptUI.progression_queue(economy,"profile_stats_refresh")
    end
    local status=profile.commit_status
    if status and status~="READY" then
        ui_text(status..(profile.last_error and " - "..tostring(profile.last_error)or""),true)
    end

    group("Character","character",{"rank","rp","creation_date","mental_state","kd_ratio"})
    group("Playtime","playtime",{
        "freemode_minutes","missions_minutes","deathmatches_minutes",
        "races_minutes","tracked_total_minutes",
        "freemode_raw","tracked_total_raw","mp_playing_time",
    })

    -- Original AISlop groups. Render two visible field tiles per line.
    -- No "click to expand", and no second horizontal scrollbar.
    for _,career in ipairs(profile.career_groups or {})do
        local rows=career.items or{}
        if #rows>0 then
            CScriptUI.section(tostring(career.title))
            CScriptUI.account_grid("career_"..tostring(career.key),rows,function(item)
                CScriptUI.profile_editor_row(economy,profile,item,true)
            end)
        end
    end

    local recovery=safe_ui_snapshot(economy,"RecoverySnapshot")or{}
    local skills=recovery.skills or{}
    local visible={}
    for _,skill in ipairs(skills)do
        if skill.available then visible[#visible+1]=skill end
    end
    if #visible>0 then
        CScriptUI.section("Skills")
        CScriptUI.account_grid("skills",visible,function(item)
            local key=tostring(item.key)
            State.progression_skill_drafts=State.progression_skill_drafts or{}
            local drafts=State.progression_skill_drafts
            local last=drafts[key]or tostring(item.value or 0)
            drafts[key]=CScriptUI.editor_field(tostring(item.label),
                "account_skill_"..key,last,16,true)
            local value=tonumber(drafts[key])
            local valid=value and value==value and value%1==0
                and value>=(tonumber(item.minimum)or 0)
                and value<=(tonumber(item.maximum)or 100)
            if CScriptUI.secondary_button("Set","account_skill_set_"..key,
                nil,62,not valid) and valid then
                CScriptUI.progression_queue(economy,"recovery_skill:"..key,value)
            end
        end)
        if CScriptUI.primary_button("Max Skills","recovery_max_skills")then
            State.progression_max_skills_confirm=true
        end
        if State.progression_max_skills_confirm then
            local answer=CScriptUI.confirm_dialog("account_max_skills",
                "Set your available character skills to maximum?")
            if answer=="confirm" then
                CScriptUI.progression_queue(economy,"recovery_max_skills")
                State.progression_max_skills_confirm=nil
            elseif answer=="cancel" then
                State.progression_max_skills_confirm=nil
            end
        end
    end

    CScriptUI.section("Custom Stat")
    local form=State.account_custom or {name="MPX_",value=""}
    State.account_custom=form
    CScriptUI.account_grid("custom_input",{1,2},function(column)
        local label,id,key=column==1 and "Stat name" or "Value",
            column==1 and "custom_stat_name" or "custom_stat_value",
            column==1 and "name" or "value"
        ui_text(label)
        if ImGui and type(ImGui.SetNextItemWidth)=="function" then
            pcall(ImGui.SetNextItemWidth,math.max(88,select(1,content_region())-10))
        end
        form[key]=input_text("##"..id,tostring(form[key]or""),column==1 and 81 or 22)
    end)
    local name=tostring(form.name or ""):upper():gsub("%s","")
    local key="custom_stat:"..name
    if CScriptUI.secondary_button("Read Stat","account_custom_read")then
        local value,reason
        if type(economy.ProfileCustomRead)=="function"then
            local ok,a,b=pcall(economy.ProfileCustomRead,name,{
                slot=profile.slot,account=profile.account,generation=profile.generation
            })
            if ok then value,reason=a,b else reason=a end
        else reason="Custom stat reader unavailable." end
        if value~=nil then
            form.value=tostring(value)
            form.message="Read "..name
        else form.message=tostring(reason or "Stat not available.") end
    end
    if CScriptUI.row_can_pair(CScriptUI.button_width("Read Stat")+
        CScriptUI.button_width("Set Stat")+8)then ui_same_line()end
    if CScriptUI.primary_button("Set Stat","account_custom_write")then
        local value,reason=economy.ProfileParse(key,tostring(form.value or ""))
        if value==nil then
            form.message=tostring(reason or "Invalid stat or integer.")
        else
            local ok,why=CScriptUI.progression_queue(economy,"profile_stat_set:"..key,value)
            form.message=ok and "Change queued."or tostring(why or "Change rejected.")
        end
    end
    if form.message then ui_text(form.message,true)end
end

local function render_page_heading(category, page)
    -- The selected tabs already name the page and category. Keep descriptions
    -- available without spending two more rows on the same navigation labels.
    if page.description then CScriptUI.tooltip(page.description) end
    ui_spacing(1)
end

local function render_world_weather()
    local world = module_context and module_context.CScript and module_context.CScript.World
    CScriptUI.card("world_weather", "Local Weather",
        "Changes the weather around you.", function()
            if not world or type(world.WeatherSnapshot) ~= "function" then
                CScriptUI.empty_state("Local weather service unavailable.")
                return
            end
            local snapshot = world.WeatherSnapshot() or {}
            if snapshot.active then
                CScriptUI.status_badge(tostring(snapshot.preset),"info")
            end
            local presets = {
                { "Extra Sunny", "EXTRASUNNY" }, { "Clear", "CLEAR" }, { "Clouds", "CLOUDS" },
                { "Overcast",    "OVERCAST" }, { "Rain", "RAIN" }, { "Thunder", "THUNDER" },
                { "Foggy", "FOGGY" }, { "Snow", "SNOW" }, { "Xmas", "XMAS" },
            }
            local available_width = select(1, content_region())
            local row_width, gap = 0, 8
            local function button_width(label)
                local width = math.max(34, measured_text_width(label) + 18)
                if available_width > 0 then width = math.min(width, available_width) end
                if row_width > 0 and row_width + gap + width <= available_width then
                    ui_same_line()
                    row_width = row_width + gap + width
                else
                    row_width = width
                end
                return width
            end
            for _, item in ipairs(presets) do
                local width = button_width(item[1])
                if CScriptUI.secondary_button(item[1], "world_weather_" .. item[2]:lower(), nil, width) then
                    world.ApplyWeather(item[2])
                end
            end
            local reset_width = button_width("Reset Weather  >")
            if CScriptUI.primary_button("Reset Weather", "world_weather_reset",
                    "Clears only CScript's local weather override and returns control to GTA.", reset_width) then
                world.ClearWeather()
            end
        end)
end

local function render_world_local(page)
    local windows = { { "Local Weather", {}, render = render_world_weather } }
    for _, window in ipairs(page and page.windows or {}) do
        windows[#windows + 1] = window
    end
    render_window_grid("World_Local", windows)
end

local function render_page(category, page)
    local context_token = page_context_id(category.key, page.name)
    if State.active_page_context ~= context_token then
        State.active_page_context = context_token
        State.page_entry_actions = {}
        if ImGui and type(ImGui.SetScrollY) == "function" then
            -- Re-enter at the page heading, never at a stale partially clipped
            -- row. Scrolling remains untouched while this page stays selected.
            pcall(ImGui.SetScrollY, 0)
        end
    end
    -- Outfit Studio supplies its own compact title/current-target row.
    if page.kind ~= "outfit_manager" and page.kind ~= "vehicle_manager" then render_page_heading(category, page) end
    if page.kind == "home_dashboard" then
        render_home_dashboard()
        return
    end
    if page.kind == "weapon_picker" then
        local weapons = module_context and module_context.CScript and module_context.CScript.Weapons
        if weapons and type(weapons.RenderPicker) == "function" then weapons.RenderPicker() end
        if #(page.windows or {}) > 0 then
            ui_spacing(1)
            render_window_grid("Combat_Weapons", page.windows)
        end
        return
    end
    if page.kind == "vehicle_combat" then
        Presentation.render_setups()
        for index, window in ipairs(page.windows or {}) do
            render_feature_window(window[1], window[2], "Vehicle_Combat_" .. index)
        end
        return
    end
    if page.kind == "session_overview" then
        render_session_overview(page)
        return
    end
    if page.kind == "session_players" then
        render_session_players()
        return
    end
    if page.kind == "protections_hardening" then
        render_protections_hardening(page)
        return
    end
    if page.kind == "world_local" then
        render_world_local(page)
        return
    end
    if page.kind == "outfit_manager" then
        local player = module_context and module_context.CScript and module_context.CScript.Player
        if player and type(player.RenderOutfitManager) == "function" then player.RenderOutfitManager() end
        return
    end
    if page.kind == "vehicle_manager" then
        local vehicle = module_context and module_context.CScript and module_context.CScript.Vehicle
        if vehicle and type(vehicle.RenderManager) == "function" then vehicle.RenderManager() end
        return
    end
    if page.kind == "recovery_manager" then
        render_recovery_manager(); return
    end
    if page.kind == "heist_manager" then
        render_heist_manager(page); return
    end
    if page.kind == "business_manager" then
        render_business_manager(page); return
    end
    if page.kind == "economy_manager" then
        CScriptUI.render_economy_manager(); return
    end
    if category.key == "Player" then
        CScriptUI.render_player_windows(page)
    else
        render_window_grid(category.key .. "_" .. page.name:gsub("%W", "_"), page.windows or {})
    end
end

local page_error_signatures = {}
local page_error_order = {}
local PAGE_ERROR_HISTORY_LIMIT = 24

local function page_traceback(err)
    local message = tostring(err)
    if debug and type(debug.traceback) == "function" then
        return debug.traceback(message, 2)
    end
    return message
end

local function log_page_error_once(category, page, message)
    local route_id = page_route_id(category.key, page.name)
    local signature = route_id .. "\0" .. tostring(message)
    if page_error_signatures[signature] then return false end
    if #page_error_order >= PAGE_ERROR_HISTORY_LIMIT then
        page_error_signatures[table.remove(page_error_order, 1)] = nil
    end
    page_error_signatures[signature] = true
    page_error_order[#page_error_order + 1] = signature
    log_error_once("page_" .. clean_id(route_id) .. "_" .. tostring(#page_error_order),
        ("Page renderer failed: %s > %s\n%s"):format(
            tostring(category.label), tostring(page.name), tostring(message)))
    return true
end

local function render_page_recovery(category, page)
    local title = "This page could not load."
    CScriptUI.card("page_recovery_" .. page_route_id(category.key, page.name),
        title, nil, function()
            CScriptUI.status_badge("Try again or return Home.", "warning")
            if CScriptUI.primary_button("Home", "page_recovery_home") then
                local home_route = PAGE_ROUTE_BY_CONTEXT[page_context_id("Home", "Overview")]
                navigate_to_entry(ROUTE_BY_ID[home_route], "recovery")
                State.page_render_failure = nil
            end
            ui_same_line()
            if CScriptUI.secondary_button("Retry Page", "page_recovery_retry") then
                State.page_render_failure = nil
            end
        end, 170)
end

local function render_page_safely(category, page)
    local route_id = page_route_id(category.key, page.name)
    local failure = State.page_render_failure
    if failure and failure.route_id == route_id then
        render_page_heading(category, page)
        render_page_recovery(category, page)
        return false
    end

    local ok, err = xpcall(function() render_page(category, page) end, page_traceback)
    if ok then
        State.page_render_failure = nil
        return true
    end

    if not State.tab_render_blocked then CScriptUI.abort_columns() end
    local message = tostring(err)
    log_page_error_once(category, page, message)
    State.page_render_failure = { route_id = route_id, message = message }
    if not State.tab_render_blocked then render_page_recovery(category, page) end
    return false
end




local function render_main_ui()
    if State and State.tab_render_blocked then return end
    CScriptUI.surface()
    if State and State.welcome_gate == true and State.welcome_preview ~= true then
        render_brand_header()
        CScriptUI.status_badge("Loading CScript", "info")
        ui_text(
            "Your features will be ready shortly.",
            true)
        return
    end

    local now = ui_clock_ms()
    update_page_transition(now)
    local shell_alpha = shell_reveal_alpha(now)
    local shell_pushed = false
    local render_ok, render_err = xpcall(function()
        render_brand_header()
        Presentation.render_retirement()
        local category = CATEGORY_BY_KEY[State.selected_category_key or "Home"] or UI_SCHEMA[1]
        State.selected_category_key = category.key

        -- Categories and subcategories use actual horizontal Cherax tab bars.
        -- Only the selected page's controls are rendered below the two rows.
        local function commit_tab(category_key,page_name,source)
            local route_id=PAGE_ROUTE_BY_CONTEXT[page_context_id(category_key,page_name)]
            local entry=route_id and ROUTE_BY_ID[route_id]
            if entry then
                State.page_transition=nil
                return commit_navigation_entry(entry,source)
            end
            return false
        end
        CScriptUI.tab_bar("main_categories",UI_SCHEMA,category.key,function(item)
            local first=item.pages and item.pages[1]
            if first then commit_tab(item.key,first.name,"category_tab")end
        end)
        category=CATEGORY_BY_KEY[State.selected_category_key or "Home"] or UI_SCHEMA[1]
        local page=selected_page(category)
        if not page then
            CScriptUI.empty_state("This workspace has no pages.")
            return
        end
        if #(category.pages or {})>1 then
            ui_spacing(1)
            local pages={}
            for _,item in ipairs(category.pages)do
                pages[#pages+1]={key=item.name,label=item.name,description=item.description}
            end
            CScriptUI.tab_bar("category_pages_"..category.key,pages,page.name,function(item)
                commit_tab(category.key,item.key,"page_tab")
            end)
            page=selected_page(category)
        end
        -- Keep scrolling content clear of the fixed navigation hit boxes.
        ui_spacing(1)
        local _, body_height = content_region()
        local flags = 0
        if page.kind == "session_players" then
            flags = (ImGuiWindowFlags and ImGuiWindowFlags.NoScrollbar or 0)
                | (ImGuiWindowFlags and ImGuiWindowFlags.NoScrollWithMouse or 0)
        end
        local function body()
            CScriptUI.surface()
            if ImGui and type(ImGui.Dummy) == "function" then pcall(ImGui.Dummy, 0, 2) end
            local body_pushed = push_ui_alpha(math.max(0.25, page_transition_alpha(now)) * shell_alpha)
            local body_ok, body_err = xpcall(function()
                render_page_safely(category, page)
            end, page_traceback)
            -- A host Begin/End failure may have changed the current window or
            -- recovered its stack. No Pop/End is safe until the script is reloaded.
            if State.tab_render_blocked then
                error(body_err or "Native UI scope uncertain; unload and reload CScript.", 0)
            end
            -- This push belongs to the body window, including Lua recovery errors.
            pop_ui_alpha(body_pushed)
            if not body_ok then error(body_err, 0) end
        end
        -- Route-specific identity isolates each body. Page entry resets its scroll;
        -- filling the remaining area keeps navigation outside the scrolling region.
        if not PlayersPage.child("##CScriptPageBody_" .. category.key .. "_" .. page.name, 0,
                math.max(1, body_height - 6), flags, body) then
            body()
        end
    end, page_traceback)
    pop_ui_alpha(shell_pushed)
    if not render_ok then error(render_err, 0) end
    -- A successful selected-tab callback still owns its route when the page
    -- child is clipped. Failed callbacks must not refresh this heartbeat.
    if State.selected_category_key == "Player" and State.selected_page_name == "Outfit Studio" then
        CScriptUI.studio_workspace_touch("outfit")
    elseif State.selected_category_key == "Vehicle" and State.selected_page_name == "Studio" then
        CScriptUI.studio_workspace_touch("vehicle")
    end
end

local function smoothstep(value)
    value = math.max(0.0, math.min(1.0, tonumber(value) or 0.0))
    return value * value * (3.0 - 2.0 * value)
end

local NOTIFICATION_COLORS = {
    info = { 109, 128, 255 },
    success = { 91, 218, 158 },
    warning = { 247, 183, 90 },
    error = { 238, 92, 112 },
    protection = { 192, 122, 255 },
}
local NOTIFICATION_ICONS = { info = "i", success = "+", warning = "!", error = "x" }

local function render_notification_stack(items, width, top_y)
    width = math.max(1, tonumber(width) or 1920)
    local panel_width = math.max(1, math.min(420, width - 32))
    local gap = 7
    local x = (width - panel_width) * 0.5
    local y = math.max(18, tonumber(top_y) or 24)
    for _, item in ipairs(items or {}) do
        local progress = tonumber(item.progress) or 0
        local enter = smoothstep(math.min(1, progress / 0.08))
        local exit = smoothstep(math.max(0, (progress - 0.86) / 0.14))
        local opacity = math.max(0, math.min(1, enter * (1 - exit)))
        local alpha = math.floor(238 * opacity)
        local panel_height = 68
        if alpha > 0 then
            local color = NOTIFICATION_COLORS[item.kind] or NOTIFICATION_COLORS.info
            local message = tostring(item.message or ""):gsub("[\r\n]+", " ")
            local repeat_count = math.max(1, math.floor(tonumber(item.repeat_count) or 1))
            local max_message = math.max(42, math.floor(panel_width / 5.2))
            if #message > max_message then message = message:sub(1, max_message - 3) .. "..." end
            local draw_y = math.floor(y + (1 - enter) * -10)
            ImGui.BgAddRectFilled(x - 2, draw_y - 2, x + panel_width + 2, draw_y + panel_height + 2,
                134, 61, 215, math.floor(64 * opacity), 12)
            ImGui.BgAddRectFilled(x + 2, draw_y + 5, x + panel_width + 2, draw_y + panel_height + 5,
                0, 0, 0, math.floor(90 * opacity), 11)
            ImGui.BgAddRectFilled(x, draw_y, x + panel_width, draw_y + panel_height,
                16, 10, 25, alpha, 11)
            ImGui.BgAddRectFilled(x + 13, draw_y + 12, x + 28, draw_y + 27,
                150, 57, 237, math.floor(240 * opacity), 4)
            ImGui.BgAddText(x + 17, draw_y + 12, "C", 255, 245, 255, math.floor(255 * opacity))
            ImGui.BgAddText(x + 37, draw_y + 12, "CSCRIPT", 224, 197, 255, math.floor(255 * opacity))
            ImGui.BgAddText(x + 110, draw_y + 12,
                item.kind == "protection" and "SHIELD" or tostring(item.title or "Info"):upper(),
                color[1], color[2], color[3], math.floor(230 * opacity))
            if repeat_count > 1 then
                ImGui.BgAddText(x + panel_width - 61, draw_y + 12, "x" .. tostring(repeat_count),
                    203, 172, 236, math.floor(245 * opacity))
            end
            ImGui.BgAddText(x + 16, draw_y + 37, message, 239, 232, 248, math.floor(245 * opacity))
            ImGui.BgAddRectFilled(x + 12, draw_y + panel_height - 4,
                x + 12 + (panel_width - 24) * math.max(0, 1 - progress), draw_y + panel_height - 2,
                173, 78, 255, math.floor(225 * opacity), 1)
        end
        y = y + panel_height + gap
    end
end

local function render_cached_overlay(overlay, width, height)
    if overlay.cinematic_bars then
        local bar = math.floor(height * 0.07)
        ImGui.BgAddRectFilled(0, 0, width, bar, 0, 0, 0, 255, 0)
        ImGui.BgAddRectFilled(0, height - bar, width, height, 0, 0, 0, 255, 0)
    end
    local lines = overlay.lines or {}
    if #lines > 0 then
        local x, bottom = 22, math.max(80, height - 44)
        local panel_width = math.max(280, math.min(520, width - 44))
        local panel_height = 18 + #lines * 22
        local top = bottom - panel_height
        ImGui.BgAddRectFilled(x - 10, top, x - 10 + panel_width, bottom, 10, 12, 18, 185, 7)
        ImGui.BgAddRectFilled(x - 10, top, x - 6, bottom, 169, 78, 255, 225, 3)
        for index, line in ipairs(lines) do ImGui.BgAddText(x, top + 8 + (index - 1) * 22, line, 238, 240, 246, 235) end
    end
    if overlay.vip then
        local x, y = width * 0.5 - 230, 26
        ImGui.BgAddRectFilled(x, y, x + 460, y + 38, 45, 20, 64, 220, 7)
        ImGui.BgAddText(x + 16, y + 10, tostring(overlay.vip), 242, 226, 252, 245)
    end
end


local function log_startup_render_once(mode, progress, phase)
    if not State or not dependencies or type(dependencies.log_info) ~= "function" then return end
    local key = mode == "fullscreen" and "welcome_render_fullscreen_logged" or "welcome_render_compact_logged"
    if State[key] == true then return end
    State[key] = true
    dependencies.log_info(("Startup presentation render=VISIBLE mode=%s progress=%d phase=%s")
        :format(mode, math.floor((tonumber(progress) or 0) * 100 + 0.5), tostring(phase or "STARTING")))
end

-- BEGIN SHARED STARTUP PRESENTATION
local function create_startup_presentation()
    -- Staged loading panel and identity finale share the startup lifecycle.
    -- Animation does not advance readiness or publish the interface.
    local function clamp(v, a, b) return math.max(a, math.min(b, v)) end
    local function ease(v)
        v = clamp(v, 0, 1); return v * v * (3 - 2 * v)
    end
    local function hold_ms(v) return clamp(tonumber(v) or 2000, 1500, 3500) end
    local function rgba(v) return math.floor(clamp(v, 0, 255)) end
    local function rect(x, y, xx, yy, r, g, b, a, round)
        if a < 1 or xx <= x or yy <= y then return end
        if ImGui and type(ImGui.BgAddRectFilled) == "function" then
            pcall(ImGui.BgAddRectFilled, x, y, xx, yy, rgba(r), rgba(g), rgba(b), rgba(a), round or 0)
        end
    end
    local function line(x, y, xx, yy, r, g, b, a, thick)
        if a < 1 then return end
        if ImGui and type(ImGui.BgAddLine) == "function" then
            pcall(ImGui.BgAddLine, x, y, xx, yy, rgba(r), rgba(g), rgba(b), rgba(a), thick or 1)
        end
    end
    local function circle(x, y, radius, r, g, b, a, filled, thick)
        if a < 1 then return end
        local fn = ImGui and (filled and ImGui.BgAddCircleFilled or ImGui.BgAddCircle)
        if type(fn) == "function" then
            if filled then
                pcall(fn, x, y, radius, rgba(r), rgba(g), rgba(b), rgba(a), 16)
            else
                pcall(fn, x, y, radius, rgba(r), rgba(g), rgba(b), rgba(a), 64, thick or 1)
            end
        end
    end
    local function text(x, y, s, r, g, b, a)
        if a < 1 then return end
        if ImGui and type(ImGui.BgAddText) == "function" then
            pcall(ImGui.BgAddText, x, y, s, rgba(r), rgba(g), rgba(b), rgba(a))
        end
    end
    local phases = {
        { "Setup",     "Checking your setup",      "Getting things ready.",       ["HOST CONTRACT"] = true },
        { "Sources",   "Preparing CScript",        "Loading your features.",      ["VERIFYING MODULE SOURCES"] = true },
        { "Integrity", "Verifying your files",     "Checking your files.",        ["DEEP SOURCE INTEGRITY"] = true },
        { "Services",  "Connecting to the game",    "Connecting to the game.", ["INDEXING NATIVE CATALOG"] = true },
        { "Game",      "Reading game data",        "Connecting to the current game.",      ["SCANNING GTA IMAGE"] = true },
        { "Runtime",   "Getting ready",   "Checking that everything is ready.",   ["FINGERPRINTING RUNTIME"] = true },
        { "Session",   "Connecting your session",  "Preparing your session context.",      ["BINDING SESSION CONTEXT"] = true, ["ACTIVATION ARMED"] = true },
        { "Workspace", "Restoring your workspace", "Loading your saved preferences.",      ["ACTIVATING MODULE GRAPH"] = true, ["VERIFYING REGISTRY"] = true, ["ARMING PLAYER RUNTIME"] = true, ["CHECKING SESSION"] = true, ["LOADING PERSISTENCE"] = true },
        { "Interface", "Preparing your interface", "Your workspace is almost ready.",      ["FINALIZING INTERFACE"] = true,    ["CSCRIPT READY"] = true },
    }
    -- Build the five-piece C and letter paths once to avoid per-frame geometry allocation.
    local segments = {}
    for i = 0, 4 do
        local points = {}
        for j = 0, 8 do
            local a = math.rad(42 + (276 / 5) * i + 1.2 + (276 / 5 - 2.4) * j / 8)
            points[#points + 1] = { math.cos(a), math.sin(a) }
        end
        segments[#segments + 1] = points
    end
    local ticks = {}
    for i = 0, 11 do
        local a = math.rad(15 + i * 30); ticks[#ticks + 1] = { math.cos(a), math.sin(a) }
    end
    local glyphs = {
        C = { { { 1, 0 }, { .2, 0 }, { 0, .2 }, { 0, .8 }, { .2, 1 }, { 1, 1 } } },
        S = { { { 1, 0 }, { .15, 0 }, { 0, .15 }, { 0, .4 }, { 1, .6 }, { 1, .85 }, { .85, 1 }, { 0, 1 } } },
        R = { { { 0, 1 }, { 0, 0 }, { .8, 0 }, { 1, .2 }, { 1, .35 }, { .8, .5 }, { 0, .5 } }, { { .5, .5 }, { 1, 1 } } },
        I = { { { .5, 0 }, { .5, 1 } } },
        P = { { { 0, 1 }, { 0, 0 }, { .8, 0 }, { 1, .2 }, { 1, .35 }, { .8, .5 }, { 0, .5 } } },
        T = { { { 0, 0 }, { 1, 0 } }, { { .5, 0 }, { .5, 1 } } },
    }
    local visual = {
        start = nil,
        last = nil,
        progress = 0,
        font = 0,
        widths = {},
        fits = {},
        fit_count = 0,
        version = nil,
        identity =
        "CScript",
        phase = 1,
        pending = 1,
        phase_at = 0
    }
    local function font_size()
        local f = 15
        if ImGui and type(ImGui.GetFontSize) == "function" then
            local ok, n = pcall(ImGui.GetFontSize); if ok and type(n) == "number" and n > 0 and n < 256 then f = n end
        end
        if f ~= visual.font then
            visual.font = f; visual.widths = {}; visual.fits = {}; visual.fit_count = 0
        end
        return f
    end
    local function measure(s)
        if visual.widths[s] then return visual.widths[s] end
        local width = #s * visual.font * .6
        if ImGui and type(ImGui.CalcTextSize) == "function" then
            local ok, n = pcall(ImGui.CalcTextSize, s); if ok and type(n) == "number" and n >= 0 and n < 100000 then
                width =
                    n
            end
        end
        visual.widths[s] = width; return width
    end
    local function fit(s, width)
        width = math.floor(width)
        if measure(s) <= width then return s end
        local key = s .. ":" .. tostring(width)
        if visual.fits[key] then return visual.fits[key] end
        local out = s
        while #out > 0 and measure(out .. "...") > width do out = out:sub(1, -2) end
        out = out .. "..."
        if visual.fit_count >= 24 then
            visual.widths = {}; visual.fits = {}; visual.fit_count = 0
        end
        visual.fit_count = visual.fit_count + 1; visual.fits[key] = out; return out
    end
    local function centered(cx, y, s, width, r, g, b, a)
        s = fit(s, width); text(cx - measure(s) * .5, y, s, r, g, b, a)
    end
    local function mark(cx, cy, radius, alpha, assembly, shine)
        for i, points in ipairs(segments) do
            local part = ease(assembly * 1.45 - (i - 1) * .11)
            local offset = (1 - part) * (i % 2 == 0 and -5 or 5)
            for j = 2, #points do
                local a, b = points[j - 1], points[j]
                local bright = part * ease((assembly * 5 - (i - 1)) * .8)
                line(cx + a[1] * radius, cy + a[2] * radius + offset, cx + b[1] * radius, cy + b[2] * radius + offset,
                    147, 100, 229, alpha * 12, math.max(5, radius * .13))
                line(cx + a[1] * radius, cy + a[2] * radius + offset, cx + b[1] * radius, cy + b[2] * radius + offset,
                    183 + shine * 38, 136 + shine * 53, 244 + shine * 10, alpha * (48 + 196 * bright),
                    math.max(1.8, radius * .048))
            end
        end
    end
    local function wordmark(cx, y, size, alpha)
        local width = size * .65; local step = width + size * .38
        local x = cx - (6 * step + width) * .5
        for ch in ("CSCRIPT"):gmatch(".") do
            for _, path in ipairs(glyphs[ch]) do
                for i = 2, #path do
                    local a, b = path[i - 1], path[i]
                    line(x + a[1] * width, y + a[2] * size, x + b[1] * width, y + b[2] * size, 235, 226, 252, alpha, 1.7)
                end
            end
            x = x + step
        end
    end
    local function draw(state, w, h, now, version)
        if state.dismissed and not state.failed then return end
        if type(w) ~= "number" or type(h) ~= "number" or w < 320 or h < 220 then return end
        local font = font_size(); local started = tonumber(state.started_ms) or now
        local age = math.max(0, now - started)
        local ready = not state.failed and (tonumber(state.ready_ms) or 0) > 0
        local ra = ready and math.max(0, now - state.ready_ms) or 0
        local target = ready and 1 or clamp(tonumber(state.progress) or 0, 0, .985)
        local phase = 1
        for i, p in ipairs(phases) do if p[state.failed_stage or state.stage] then phase = i end end
        if visual.start ~= started or not visual.last or now < visual.last then
            visual.start = started; visual.progress = target; visual.phase = phase; visual.pending = phase; visual.phase_at =
                now - 300
        end
        local dt = clamp(now - (visual.last or now), 0, 80); visual.last = now
        if target < visual.progress then
            visual.progress = target
        else
            visual.progress = math.min(target, visual.progress + (target - visual.progress) * (1 - math.exp(-dt / 155)))
        end
        if ready and ra >= 240 then visual.progress = 1 end
        if phase ~= visual.pending then
            visual.pending = phase; visual.phase_at = now
        end
        local pa = math.max(0, now - visual.phase_at); local phase_alpha = 1
        if visual.phase ~= visual.pending and pa < 90 then
            phase_alpha = 1 - ease(pa / 90)
        elseif pa < 230 then
            visual.phase = visual.pending; phase_alpha = ease((pa - 90) / 140)
        else
            visual.phase = visual.pending
        end
        if visual.version ~= version then
            visual.version = version
            visual.identity = tostring(version or "Build metadata unavailable"); visual.widths = {}; visual.fits = {}; visual.fit_count = 0
        end
        local intro = state.quick and 1 or ease(age / 440)
        local exit = ready and ease((ra - hold_ms(state.hold_ms) - 460) / 440) or 0
        local opacity = intro * (1 - exit); if opacity <= 0 then return end
        local finale = ready and (state.quick and 1 or ease((ra - 100) / 500)) or 0
        -- Loading and finale share one translucent background.
        rect(0, 0, w, h, 8, 8, 16, opacity * (66 + 28 * finale), 0)
        local compact = w < 600 or h < 460 or font > 32
        if compact then
            local pw = math.min(w - 32, 520); local ph = math.min(h - 32, font * 3 + 110)
            local x = (w - pw) * .5; local y = (h - ph) * .5; local pad = 18
            rect(x, y, x + pw, y + ph, 18, 17, 30, opacity * 191, 12)
            line(x + 12, y + 1, x + pw - 12, y + 1, 201, 172, 239, opacity * 55, 1)
            mark(x + 34, y + 34, 15, opacity, ease(age / 650), ready and ease(ra / 800) or 0)
            text(x + 64, y + 23, "CScript", 246, 238, 253, opacity * 250)
            local label = state.failed and "Startup stopped" or ready and "Ready" or phases[visual.phase][2]
            text(x + pad, y + ph - 2 * font - 47, fit(label, pw - pad * 2), 224, 215, 240, opacity * 246)
            text(x + pad, y + ph - font - 33, fit(state.failed and "Reload CScript to try again." or visual.identity, pw - pad *
                2), 166, 153, 189, opacity * 222)
            rect(x + pad, y + ph - 19, x + pw - pad, y + ph - 17, 191, 163, 227, opacity * 40, 1)
            rect(x + pad, y + ph - 19, x + pad + (pw - pad * 2) * visual.progress, y + ph - 17, 181, 129, 238,
                opacity * 238, 1)
            return
        end
        local panel_alpha = opacity * (1 - ease(ra / 260) * (ready and 1 or 0))
        if panel_alpha > .003 then
            local pad = 26; local lh = font + 12; local header = math.max(76, 2 * font + 24)
            local pw = math.min(w - 40, math.max(640, math.min(780, font * 35)))
            local ph = header + 2 * font + 3 * lh + 100
            local x = (w - pw) * .5; local y = (h - ph) * .5 + (1 - intro) * 9 - (ready and ease(ra / 260) * 7 or 0)
            local inner = pw - 2 * pad; local aa = panel_alpha
            rect(x + 9, y + ph, x + pw - 9, y + ph + 5, 0, 0, 0, aa * 35, 4)
            rect(x, y, x + pw, y + ph, 18, 17, 30, aa * 187, 14)
            line(x + 16, y + 1, x + pw - 16, y + 1, 202, 173, 241, aa * 66, 1)
            line(x + 1, y + 17, x + 1, y + ph - 17, 184, 158, 221, aa * 24, 1)
            line(x + pw - 1, y + 17, x + pw - 1, y + ph - 17, 184, 158, 221, aa * 24, 1)
            -- Restrained engraved corners and header lights; fixed-size work.
            line(x + pad, y + ph - 12, x + pad + 28, y + ph - 12, 175, 122, 231, aa * 65, 1)
            line(x + pw - pad - 28, y + ph - 12, x + pw - pad, y + ph - 12, 175, 122, 231, aa * 65, 1)
            local cy = y + header * .5
            circle(x + pad + 28, cy, 35, 171, 126, 226, aa * 38, false, 1)
            mark(x + pad + 29, cy, 24, aa, ease(age / 700), 0)
            text(x + pad + 84, cy - font - 5, "C S C R I P T", 242, 233, 252, aa * 255)
            text(x + pad + 84, cy + 7, fit(visual.identity, inner - 150), 177, 159, 202, aa * 235)
            for i = 0, 2 do
                circle(x + pw - pad - 24 + i * 10, cy - 4, 1.6, 190, 150, 235, aa *
                    (i == phase % 3 and 160 or 45), true)
            end
            line(x + pad, y + header, x + pw - pad, y + header, 174, 119, 231, aa * 58, 1)
            -- A quiet header glint is decoration, never a progress signal.
            local sweep = state.failed and 0 or ((age % 6400) / 6400)
            local sx = x + pad + inner * sweep
            line(sx, y + header, math.min(x + pw - pad, sx + 28), y + header, 215, 187, 248,
                aa * (state.failed and 0 or 76) * math.sin(sweep * math.pi), 1)
            local heading = state.failed and "Startup stopped" or phases[visual.phase][2]
            local detail = state.failed and "Reload CScript to try again." or phases[visual.phase][3]
            local content = aa * ease((age - 150) / 260) * (state.failed and 1 or phase_alpha)
            text(x + pad, y + header + 20, fit(heading, inner), 242, 233, 253, content * 253)
            text(x + pad, y + header + font + 29, fit(detail, inner), 182, 169, 204, content * 235)
            local gy = y + header + 2 * font + 55; local colw = inner / 3
            for i, p in ipairs(phases) do
                local col = math.floor((i - 1) / 3); local row = (i - 1) % 3; local xx = x + pad + colw * col; local yy =
                    gy + row * lh
                local active = i == phase; local done = i < phase
                if active then rect(xx - 7, yy - 4, xx + colw - 16, yy + font + 5, 139, 86, 202, aa * 26, 5) end
                if row < 2 then
                    line(xx + 3, yy + font * .5 + 6, xx + 3, yy + lh + font * .5 - 6, 177, 137, 216,
                        aa * (done and 59 or 22), 1)
                end
                circle(xx + 3, yy + font * .5, active and 3 or 2, done and 188 or 174, done and 162 or 120, 231,
                    aa * (active and 245 or done and 170 or 58), not active, 1.2)
                text(xx + 15, yy, fit(p[1], colw - 38), active and 210 or done and 205 or 142,
                    active and 169 or done and 192 or 132, active and 249 or done and 225 or 161,
                    aa * (active and 255 or 223))
            end
            local py = y + ph - 24; local fill = inner * visual.progress
            rect(x + pad, py, x + pw - pad, py + 2, 191, 165, 228, aa * 37, 1)
            rect(x + pad, py, x + pad + fill, py + 2, 181, 129, 238, aa * 238, 1)
            if fill > 2 then circle(x + pad + fill, py + 1, 2, 214, 184, 250, aa * 230, true) end
        end
        if finale > 0 then
            local aa = opacity * finale; local cx = w * .5
            local radius = math.min(64, h * .082); local cy = h * .5 - 64 - exit * 7
            local assembly = state.quick and 1 or ease((ra - 160) / 660)
            local settle = state.quick and 1 or ease((ra - 650) / 700)
            -- Soft medallion, orbit hairline and twelve engraved ticks give the
            -- recovered finale depth without blocking the surrounding game.
            circle(cx, cy, radius + 19, 17, 13, 29, aa * 88, true)
            circle(cx, cy, radius + 19, 171, 126, 225, aa * 40, false, 1)
            circle(cx, cy, radius + 27, 171, 126, 225, aa * 18, false, 1)
            for i, p in ipairs(ticks) do
                local reveal = ease(assembly * 1.7 - (i - 1) * .05)
                line(cx + p[1] * (radius + 23), cy + p[2] * (radius + 23), cx + p[1] * (radius + 26), cy +
                    p[2] * (radius + 26), 196, 156, 239, aa * 67 * reveal, 1)
            end
            mark(cx, cy, radius, aa, assembly, settle * .55)
            local title_alpha = aa * (state.quick and 1 or ease((ra - 430) / 380))
            local ty = cy + radius + 48
            wordmark(cx, ty, math.min(30, font * 1.8), title_alpha * 255)
            local caption_y = ty + 49
            centered(cx, caption_y, "Your workspace is ready", w - 40, 221, 211, 237, title_alpha * 245)
            centered(cx, caption_y + font + 13, visual.identity, w - 40, 171, 156, 192, title_alpha * 225)
            if state.dismiss_supported then
                centered(cx, caption_y + 2 * (font + 13), "Enter to continue", w - 40, 167,
                    154, 186, title_alpha * 205)
            end
            local spread = 56 * settle
            line(cx - spread, cy - radius - 44, cx - 8, cy - radius - 44, 190, 145, 239, aa * 50 * settle, 1)
            line(cx + 8, cy - radius - 44, cx + spread, cy - radius - 44, 190, 145, 239, aa * 50 * settle, 1)
            circle(cx, cy - radius - 44, 2, 203, 167, 243, aa * 150 * settle, true)
        end
    end
    return {
        Duration = function(quick, hold) return quick and 240 or 1000 + hold_ms(hold) end,
        PublishAt = function(quick, hold) return 0 end,
        Draw = draw
    }
end
-- END SHARED STARTUP PRESENTATION
local startup_presentation = create_startup_presentation()
local function render_welcome_intro(api, welcome, now, width, height)
    if not welcome or ((not welcome.enabled) and (not welcome.preview)) or welcome.started_seconds == 0 then return end
    local started = tonumber(welcome.started_seconds) or 0
    if started < 0 then
        started = math.max(now, .000001); api.SetWelcomeStartSeconds(started)
    end
    local elapsed = math.max(0, (now - started) * 1000)
    local quick = false
    local ready_at = 3600
    local snapshot = {
        started_ms = started * 1000,
        ready_ms = 0,
        stage = "HOST CONTRACT",
        progress = 0,
        preview = welcome.preview == true,
        session_pid = 0,
        quick = quick,
        hold_ms = 2000,
        dismiss_supported = false
    }
    if welcome.preview then
        -- Simulation is local presentation state. It never calls a startup owner,
        -- changes welcome_gate, loads preferences, publishes a tab or sends a toast.
        local stages = { "HOST CONTRACT", "VERIFYING MODULE SOURCES", "DEEP SOURCE INTEGRITY",
            "INDEXING NATIVE CATALOG", "SCANNING GTA IMAGE", "FINGERPRINTING RUNTIME",
            "BINDING SESSION CONTEXT", "ACTIVATING MODULE GRAPH", "CSCRIPT READY" }
        snapshot.stage = stages[math.min(9, 1 + math.floor(elapsed / 400))]
        snapshot.progress = math.min(.98, elapsed / ready_at)
        if elapsed >= ready_at then snapshot.ready_ms = started * 1000 + ready_at end
        if elapsed >= ready_at + startup_presentation.Duration(quick, 2000) then
            api.StopWelcome(); return
        end
    else
        snapshot.stage = welcome.phase or "HOST CONTRACT"
        snapshot.progress = tonumber(welcome.progress) or 0
        if welcome.ready then
            if (tonumber(State.welcome_ready_render_seconds) or 0) <= 0 then State.welcome_ready_render_seconds = now end
            snapshot.ready_ms = State.welcome_ready_render_seconds * 1000
        end
    end
    log_startup_render_once("compact", snapshot.progress, snapshot.preview and "SIMULATED PRESENTATION" or snapshot
        .stage)
    startup_presentation.Draw(snapshot, width, height, now * 1000, BUILD_UI_LABEL)
end

local function compact_money(value)
    value = math.max(0, tonumber(value) or 0)
    if value >= 1000000 then return ("$%.1fM"):format(value / 1000000):gsub("%.0M", "M") end
    if value >= 1000 then return ("$%.1fK"):format(value / 1000):gsub("%.0K", "K") end
    return "$" .. tostring(math.floor(value))
end

local function render_economy_hud(snapshot, width, height)
    if not snapshot or snapshot.enabled ~= true then return end
    local panel_width, panel_height = 270, 70
    local x, y = math.max(12, width - panel_width - 22), math.max(12, height - panel_height - 28)
    ImGui.BgAddRectFilled(x, y, x + panel_width, y + panel_height, 10, 12, 18, 218, 7)
    ImGui.BgAddRectFilled(x, y, x + 3, y + panel_height, 169, 78, 255, 235, 3)
    ImGui.BgAddText(x + 14, y + 10, "ECONOMY ACTIVITY", 190, 151, 255, 245)
    ImGui.BgAddText(x + 14, y + 32, ("24H  %s / %s  %d%%"):format(
        compact_money(snapshot.last24), compact_money(snapshot.daily_limit),
        math.floor((tonumber(snapshot.daily_percentage) or 0) + 0.5)), 238, 240, 246, 245)
    ImGui.BgAddText(x + 14, y + 50, ("7D    %s / %s  %d%%"):format(
        compact_money(snapshot.last7), compact_money(snapshot.weekly_limit),
        math.floor((tonumber(snapshot.weekly_percentage) or 0) + 0.5)), 238, 240, 246, 245)
end

-- Messiah owns gameplay and targeting state. ON_PRESENT consumes only a
-- bounded snapshot so the HUD cannot register controls, advance combat state,
-- or become a second runtime owner.
local MESSIAH_HUD_ROWS = {
    { ability = "ORB",       key = "LMB", label = "AURORA ORB" },
    { ability = "LANCE",     key = "RMB", label = "VOID LANCE" },
    { ability = "RUPTURE",   key = "Q",   label = "GROUND RUPTURE" },
    { ability = "SHOCKWAVE", key = "E",   label = "DIVINE SHOCKWAVE" },
    { ability = "SUPER",     key = "R",   label = "JUDGMENT [SUPER]" },
}
local messiah_reticle_backend_logged = false

-- Render geometry is detached by player.lua. This renderer deliberately has no
-- entity/control/input work. The player adapter projects immutable world rows
-- with current read-only render-camera data before this drawing-only consumer.
local messiah_visual_render_state = {
    epoch = -1,
    action_serial = -1,
    generation = -1,
    frames = 0,
    last_now_ms = -1,
    stale_frames = 0,
    next_log_ms = 0
}
local messiah_visual_cached_snapshot

local function read_messiah_visual_snapshot()
    local player = module_context and module_context.CScript and module_context.CScript.Player
    local getter = player and player.MessiahVisualSnapshot
    if type(getter) ~= "function" then
        messiah_visual_cached_snapshot = nil
        return nil
    end
    local known = messiah_visual_cached_snapshot and messiah_visual_cached_snapshot.generation
    local ok, snapshot, unchanged = pcall(getter, known)
    if ok and unchanged == true then snapshot = messiah_visual_cached_snapshot end
    if not ok or type(snapshot) ~= "table" or snapshot.active ~= true then
        messiah_visual_cached_snapshot = nil
        return nil
    end
    messiah_visual_cached_snapshot = snapshot
    -- Cache immutable world geometry, then project against this render frame.
    -- Never cache last frame's projected coordinates as the world snapshot.
    local project = player.ProjectMessiahVisualSnapshot
    if type(project) ~= "function" then return nil end
    local projected_ok, projected = pcall(project, snapshot)
    return projected_ok and type(projected) == "table" and projected or nil
end

local function messiah_visual_finite(value)
    return type(value) == "number" and value == value and value > -math.huge and value < math.huge
end

local function render_messiah_visuals(snapshot, width, height)
    local tracker = messiah_visual_render_state
    if not snapshot or snapshot.active ~= true then
        tracker.stale_frames = 0
        return 0
    end
    if not (ImGui and type(ImGui.BgAddLine) == "function"
            and type(ImGui.BgAddCircle) == "function" and type(ImGui.BgAddCircleFilled) == "function")
    then
        return 0
    end
    for _, name in ipairs({ "epoch", "action_serial", "generation", "now_ms" }) do
        if not messiah_visual_finite(snapshot[name]) then return 0 end
    end
    if not messiah_visual_finite(width) or not messiah_visual_finite(height)
        or width < 1 or width > 16384 or height < 1 or height > 16384 then
        return 0
    end
    if snapshot.epoch < tracker.epoch or (snapshot.epoch == tracker.epoch
            and (snapshot.generation < tracker.generation or snapshot.action_serial < tracker.action_serial)) then
        return 0
    end
    -- A stopped gameplay publisher must not leave a permanent beam. This is
    -- bounded renderer bookkeeping, not a second gameplay scheduler or clock.
    if snapshot.epoch == tracker.epoch and snapshot.generation == tracker.generation then
        tracker.stale_frames = tracker.stale_frames + 1
        if snapshot.projection_phase ~= "render" and tracker.stale_frames > 30 then return 0 end
    else
        tracker.stale_frames = 0
    end
    tracker.epoch, tracker.generation = snapshot.epoch, snapshot.generation
    tracker.action_serial = snapshot.action_serial
    local submitted, lance_core_submitted = 0, 0
    local function normal(value) return messiah_visual_finite(value) and value >= 0 and value <= 1 end
    local function colour(row)
        return messiah_visual_finite(row.r) and row.r >= 0 and row.r <= 255
            and messiah_visual_finite(row.g) and row.g >= 0 and row.g <= 255
            and messiah_visual_finite(row.b) and row.b >= 0 and row.b <= 255
            and messiah_visual_finite(row.a) and row.a >= 0 and row.a <= 255
    end
    local lines = type(snapshot.lines) == "table" and snapshot.lines or {}
    local discs = type(snapshot.discs) == "table" and snapshot.discs or {}
    local visual_scale = math.max(0.75, math.min(2.0, height / 720.0))
    for index = 1, math.min(128, #lines) do
        local row = snapshot.lines[index]
        if type(row) == "table" and normal(row.x1) and normal(row.y1) and normal(row.x2) and normal(row.y2)
            and colour(row) and messiah_visual_finite(row.thickness) and row.thickness >= 0.5
            and row.thickness <= 96 then
            ImGui.BgAddLine(row.x1 * width, row.y1 * height, row.x2 * width, row.y2 * height,
                row.r, row.g, row.b, row.a, row.thickness * visual_scale)
            submitted = submitted + 1
            if row.role == "lance-core" or row.role == "lance-strand:1" then
                lance_core_submitted = lance_core_submitted + 1
            end
        end
    end
    for index = 1, math.min(48, #discs) do
        local row = snapshot.discs[index]
        if type(row) == "table" and normal(row.x) and normal(row.y) and colour(row)
            and messiah_visual_finite(row.radius) and row.radius >= 1 and row.radius <= 64
            and messiah_visual_finite(row.thickness) and row.thickness >= 0.5 and row.thickness <= 4 then
            if row.filled == true then
                ImGui.BgAddCircleFilled(row.x * width, row.y * height, row.radius * visual_scale,
                    row.r, row.g, row.b, row.a, 16)
            else
                ImGui.BgAddCircle(row.x * width, row.y * height, row.radius * visual_scale,
                    row.r, row.g, row.b, row.a, 16, row.thickness * visual_scale)
            end
            submitted = submitted + 1
        end
    end
    if submitted > 0 then tracker.frames = tracker.frames + 1 end
    if (snapshot.debug or lance_core_submitted > 0) and snapshot.now_ms >= tracker.next_log_ms then
        tracker.next_log_ms = snapshot.now_ms + 1000
        if dependencies and type(dependencies.log_info) == "function" then
            dependencies.log_info(("Messiah ON_PRESENT draw submitted: epoch=%d actionSerial=%d "
                    .. "generation=%d primitives=%d frames=%d lanceCoreSubmitted=%d visibility=live-unverified.")
                :format(snapshot.epoch, snapshot.action_serial, snapshot.generation, submitted, tracker.frames,
                    lance_core_submitted))
        end
    end
    return submitted
end

local function read_messiah_hud_snapshot()
    local player = module_context and module_context.CScript and module_context.CScript.Player
    local getter = player and player.MessiahHudSnapshot
    if type(getter) ~= "function" then return nil end
    local ok, snapshot = pcall(getter)
    if not ok or type(snapshot) ~= "table" or snapshot.active ~= true then return nil end
    local project = player.ProjectMessiahHudSnapshot
    if type(project) ~= "function" then return nil end
    local projected_ok, projected = pcall(project, snapshot)
    return projected_ok and type(projected) == "table" and projected or nil
end

local function messiah_gui_open(snapshot)
    if type(snapshot) == "table" and type(snapshot.menu_open) == "boolean" then
        return snapshot.menu_open
    end
    if not (GUI and type(GUI.IsOpen) == "function") then return false end
    local ok, open = pcall(GUI.IsOpen)
    return ok and open == true
end

local function bounded_hud_text(value, maximum)
    local text = tostring(value or ""):gsub("[%c]+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    maximum = math.max(1, tonumber(maximum) or 18)
    if #text > maximum then text = text:sub(1, maximum - 1) .. "~" end
    return text
end

local function messiah_ability_entry(snapshot, ability)
    local abilities = type(snapshot.abilities) == "table" and snapshot.abilities or nil
    local entry = abilities and (abilities[ability] or abilities[ability:lower()]) or nil
    if type(entry) ~= "table" then
        local rows = type(snapshot.rows) == "table" and snapshot.rows or nil
        if rows then
            for _, row in ipairs(rows) do
                if type(row) == "table" and tostring(row.ability or row.id or ""):upper() == ability then
                    entry = row
                    break
                end
            end
        end
    end
    if type(entry) == "table" then return entry end
    local direct = snapshot[ability] or snapshot[ability:lower()]
    return type(direct) == "table" and direct or {}
end

local function messiah_status_text(snapshot, ability)
    local entry = messiah_ability_entry(snapshot, ability)
    local status = bounded_hud_text(entry.status or entry.state, 16):upper()
    if entry.active == true and status == "" then status = "ACTIVE" end
    if entry.ready == true then status = "READY" end
    if status == "" then status = "READY" end
    return status
end

local function messiah_no_ground_target(snapshot)
    if snapshot.no_ground_target == true or snapshot.no_ground == true then return true end
    local until_ms = tonumber(snapshot.no_ground_until_ms)
    local now_ms = tonumber(snapshot.now_ms)
    return until_ms ~= nil and now_ms ~= nil and until_ms > now_ms
end

local function render_messiah_hud(snapshot, width, height)
    if not snapshot or snapshot.active ~= true then return end
    local menu_open = messiah_gui_open(snapshot)
    local opacity = menu_open and 0.30 or 1.0
    local function alpha(value) return math.floor(math.max(0, math.min(255, value * opacity))) end

    local no_ground = messiah_no_ground_target(snapshot)
    local panel_width = math.max(270, math.min(318, (tonumber(width) or 1280) - 44))
    local locked_ground = type(snapshot.reticle) == "table" and snapshot.reticle.locked_ground == true
    local panel_height = (no_ground or locked_ground) and 194 or 172
    local x = 22
    -- Leave room above the panel for GTA's help messages.
    local y = math.max(150, math.min(278, (tonumber(height) or 720) * 0.258))

    -- A filled outer shell plus inset surface gives a reliable border on the
    -- Cherax draw-list API without depending on an unverified BgAddRect call.
    ImGui.BgAddRectFilled(x, y, x + panel_width, y + panel_height,
        91, 62, 178, alpha(235), 8)
    ImGui.BgAddRectFilled(x + 2, y + 2, x + panel_width - 2, y + panel_height - 2,
        9, 11, 18, alpha(224), 7)
    ImGui.BgAddRectFilled(x + 2, y + 2, x + panel_width - 2, y + 32,
        43, 30, 84, alpha(242), 7)
    ImGui.BgAddRectFilled(x + 2, y + 29, x + panel_width - 2, y + 33,
        86, 210, 222, alpha(220), 0)
    ImGui.BgAddText(x + 14, y + 10, "MESSIAH", 239, 235, 255, alpha(255))
    ImGui.BgAddText(x + panel_width - 75, y + 10, "DOMINION", 100, 224, 232, alpha(245))

    for index, row in ipairs(MESSIAH_HUD_ROWS) do
        local row_y = y + 39 + (index - 1) * 21
        local status = messiah_status_text(snapshot, row.ability)
        local ready = status == "READY"
        local active = status == "ACTIVE" or status == "CASTING" or status == "QUEUED"
            or status == "PENDING" or status == "WINDUP" or status == "RELEASE"
            or status == "RECOVER" or status == "CHANNELING"
        ImGui.BgAddRectFilled(x + 11, row_y - 2, x + 49, row_y + 15,
            30, 39, 70, alpha(225), 4)
        ImGui.BgAddText(x + 18, row_y, row.key, 91, 225, 230, alpha(255))
        ImGui.BgAddText(x + 58, row_y, row.label, 224, 226, 239, alpha(245))
        local status_x = x + panel_width - 13 - math.min(86, #status * 7)
        if ready then
            ImGui.BgAddText(status_x, row_y, status, 91, 225, 230, alpha(255))
        elseif active then
            ImGui.BgAddText(status_x, row_y, status, 199, 150, 255, alpha(255))
        else
            ImGui.BgAddText(status_x, row_y, status, 145, 150, 177, alpha(235))
        end
    end

    local movement_y = y + 146
    ImGui.BgAddText(x + 13, movement_y, "SPACE / CTRL", 100, 224, 232, alpha(230))
    ImGui.BgAddText(x + 108, movement_y, "ASCEND / DESCEND", 142, 147, 171, alpha(225))
    if no_ground then
        ImGui.BgAddRectFilled(x + 10, y + 167, x + panel_width - 10, y + 188,
            67, 40, 78, alpha(238), 4)
        ImGui.BgAddText(x + 68, y + 171, "NO GROUND TARGET", 245, 174, 226, alpha(255))
    elseif locked_ground then
        local reticle = snapshot.reticle
        local visible = messiah_visual_finite(reticle.screen_x) and messiah_visual_finite(reticle.screen_y)
            and reticle.screen_x >= 0 and reticle.screen_x <= 1 and reticle.screen_y >= 0 and reticle.screen_y <= 1
        ImGui.BgAddText(x + 13, y + 171,
            visible and "GROUND LOCK" or "GROUND LOCK / OUT OF VIEW", 100, 238, 206, alpha(245))
    end
end

local function render_messiah_reticle(snapshot, width, height)
    local reticle = type(snapshot.reticle) == "table" and snapshot.reticle or nil
    if not reticle or reticle.visible ~= true then return end
    if not (ImGui and type(ImGui.BgAddLine) == "function"
            and type(ImGui.BgAddCircle) == "function"
            and type(ImGui.BgAddCircleFilled) == "function") then
        return
    end
    if not messiah_reticle_backend_logged then
        messiah_reticle_backend_logged = true
        if dependencies and type(dependencies.log_info) == "function" then
            dependencies.log_info(
                "Messiah reticle backend: ImGui.ON_PRESENT BgAddLine+BgAddCircle visualOnly=true persistentEntities=0.")
        end
    end
    local menu_open = messiah_gui_open(snapshot)
    local opacity = menu_open and 0.18 or 1.0
    local mode = tostring(reticle.mode or "DIRECT_MISS"):upper()
    if mode == "GROUND_INVALID" then opacity = opacity * 0.48 end
    local colour = mode == "GROUND_INVALID" and { 142, 105, 125 }
        or mode == "GROUND_VALID" and { 100, 238, 206 }
        or mode == "CHANNEL" and { 232, 250, 255 }
        or mode == "DIRECT_HIT" and { 80, 224, 244 }
        or { 151, 108, 224 }
    local function alpha(value) return math.floor(math.max(0, math.min(255, value * opacity))) end
    local viewport_width, viewport_height = tonumber(width) or 1280, tonumber(height) or 720
    local cx, cy = viewport_width * 0.5, viewport_height * 0.5
    -- Q/R keep the existing Arcane Reticle styling, but while their immutable
    -- ground target is locked the reticle follows that exact projected point.
    -- This is presentation-only: player.lua remains the sole target owner.
    if reticle.locked_ground == true or reticle.projected_contact == true then
        -- Hide an off-screen Q/R lock instead of moving its marker to the camera centre.
        if not (messiah_visual_finite(reticle.screen_x) and messiah_visual_finite(reticle.screen_y))
            or reticle.screen_x < 0 or reticle.screen_x > 1
            or reticle.screen_y < 0 or reticle.screen_y > 1 then
            return
        end
        cx = math.max(0.0, math.min(viewport_width,
            tonumber(reticle.screen_x) * viewport_width))
        cy = math.max(0.0, math.min(viewport_height,
            tonumber(reticle.screen_y) * viewport_height))
    end
    local pulse = reticle.pulse == true and 3.0 or 0.0
    local diamond = 6.0 + pulse
    local ring = mode == "CHANNEL" and 10.5
        or mode == "DIRECT_HIT" and 13.0
        or (mode == "GROUND_VALID" or mode == "GROUND_INVALID") and 17.0
        or 16.0
    ring = ring + pulse
    local outer = mode == "CHANNEL" and 28.0
        or (mode == "GROUND_VALID" or mode == "GROUND_INVALID") and 25.0 or 22.0
    ImGui.BgAddLine(cx, cy - diamond, cx + diamond, cy, colour[1], colour[2], colour[3], alpha(245), 1.8)
    ImGui.BgAddLine(cx + diamond, cy, cx, cy + diamond, colour[1], colour[2], colour[3], alpha(245), 1.8)
    ImGui.BgAddLine(cx, cy + diamond, cx - diamond, cy, colour[1], colour[2], colour[3], alpha(245), 1.8)
    ImGui.BgAddLine(cx - diamond, cy, cx, cy - diamond, colour[1], colour[2], colour[3], alpha(245), 1.8)
    ImGui.BgAddCircle(cx, cy, ring, colour[1], colour[2], colour[3], alpha(185), 32, 1.3)
    ImGui.BgAddCircle(cx, cy, outer, 116, 78, 218, alpha(145), 32, 1.0)
    local bracket = outer + 5.0
    ImGui.BgAddLine(cx - bracket - 7, cy - 7, cx - bracket, cy - 7, colour[1], colour[2], colour[3], alpha(220), 1.6)
    ImGui.BgAddLine(cx - bracket, cy - 7, cx - bracket, cy + 7, colour[1], colour[2], colour[3], alpha(220), 1.6)
    ImGui.BgAddLine(cx + bracket, cy - 7, cx + bracket + 7, cy - 7, colour[1], colour[2], colour[3], alpha(220), 1.6)
    ImGui.BgAddLine(cx + bracket, cy - 7, cx + bracket, cy + 7, colour[1], colour[2], colour[3], alpha(220), 1.6)
    if reticle.direct_hit == true or mode == "CHANNEL" then
        ImGui.BgAddCircleFilled(cx, cy, mode == "CHANNEL" and 2.8 or 2.1,
            244, 252, 255, alpha(245), 16)
    end
    if mode == "GROUND_VALID" or mode == "GROUND_INVALID" then
        local gy = cy + outer + 8
        ImGui.BgAddLine(cx - 6, gy, cx, gy + 5, colour[1], colour[2], colour[3], alpha(235), 1.7)
        ImGui.BgAddLine(cx, gy + 5, cx + 6, gy, colour[1], colour[2], colour[3], alpha(235), 1.7)
    elseif mode == "CHANNEL" then
        ImGui.BgAddCircle(cx, cy, outer + 6, 80, 224, 244, alpha(205), 40, 2.0)
    end
end

-- Small always-visible status panel, with a bounded one-player-at-a-time
-- local scan. The client never uploads identities or infers a definite menu.
-- A detected action can have many sources, including built-in protections.
local modder_overlay_state = {cursor=1,next_probe_ms=0,last_roster_ms=-100000,
    roster={},results={},available=false}
local function modder_overlay_snapshot(now)
    local state=modder_overlay_state
    local session=dependencies and dependencies.Session
    local db=module_context and module_context.Raw and module_context.Raw.ModderDB
    if not session or type(session.GetPlayersSnapshot)~="function" then
        state.available=false;state.results={}
        return {available=false,entries={}}
    end
    state.available=true
    if now-state.last_roster_ms>=1000 or now<state.last_roster_ms then
        local ok,snapshot=pcall(session.GetPlayersSnapshot)
        if ok and type(snapshot)=="table" and type(snapshot.rows)=="table" then
            state.roster=snapshot.rows
            state.last_roster_ms=now
        end
    end
    local roster=state.roster
    local identities={}
    for _,row in ipairs(roster)do
        if type(row)=="table" then
            local id=tonumber(row.id)
            if id and id%1==0 and id>=0 and id<=31
                and row.local_player~=true and row.rid~=nil then
                identities[id]=tostring(row.rid)
            end
        end
    end
    for id,record in pairs(state.results)do
        if identities[id]~=record.rid then state.results[id]=nil end
    end
    if now>=(state.next_probe_ms or 0) or now<state.next_probe_ms-2000 then
        state.next_probe_ms=now+400
        local n=#roster
        if n>0 then
            state.cursor=((state.cursor-1)%n)+1
            local row=roster[state.cursor]
            state.cursor=state.cursor+1
            local id=type(row)=="table" and tonumber(row.id) or nil
            if id and identities[id] then
                local signal=db and selected_modder_signal(id) or nil
                local owner=CScriptUI.OwnerLabels
                owner.Poll(now,identities[id])
                local label=owner.Get(identities[id],now)
                -- An identity recycled into the same lobby slot cannot inherit
                -- another Rockstar ID's owner label or Cherax DB flags.
                state.results[id]={rid=identities[id],
                    name=tostring(row.name or ("Player "..id)):gsub("%c"," "):sub(1,28),
                    signal=signal,owner_label=label,checked=now}
            end
        end
    end
    local entries={}
    for _,record in pairs(state.results)do
        local found=record.signal
        if type(found)=="table" and (found.count or 0)>0 or record.owner_label then
            entries[#entries+1]={name=record.name,
                count=type(found)=="table"and (found.count or 0)or 0,
                classification=type(found)=="table"and found.classification or "owner_label",
                owner_label=record.owner_label,
                hint=type(found)=="table"and (
                    found.crash_count>0 and "Possible Cherax/Lexis"
                    or found.trolling_count>0 and "Possible Cherax" or "Other/unknown")
                    or "No Cherax DB matches"}
        end
    end
    table.sort(entries,function(a,b)
        if a.count==b.count then return a.name<b.name end
        return a.count>b.count
    end)
    return {available=true,entries=entries,scanned=#roster}
end
local function render_modder_overlay(snapshot,width,height)
    if type(snapshot)~="table" or snapshot.available~=true
        or type(ImGui.BgAddRectFilled)~="function"
        or type(ImGui.BgAddText)~="function" then return end
    local entries=snapshot.entries or {}
    -- No idle overlay. Only display a notification when an actual
    -- detection exists; ordinary gameplay stays clean.
    if #entries==0 then return end
    local max_rows=math.min(#entries,5)
    local w=math.min(390,math.max(240,(tonumber(width)or 1280)-36))
    local x=math.max(8,(tonumber(width) or 1280)-w-18)
    local y=math.max(115,math.min(160,(tonumber(height) or 720)*0.17))
    local h=49+max_rows*19+(#entries>max_rows and 17 or 0)
    ImGui.BgAddRectFilled(x,y,x+w,y+h,22,24,32,210,5)
    ImGui.BgAddRectFilled(x+1,y+1,x+w-1,y+26,39,42,55,231,4)
    local detected=false
    for _,entry in ipairs(entries) do
        if (tonumber(entry.count) or 0)>0 then detected=true; break end
    end
    ImGui.BgAddText(x+10,y+7,
        detected and "CSCRIPT | NOTES & DETECTIONS" or "CSCRIPT | PLAYER NOTES",
        230,231,238,245)
    if max_rows==0 then
        ImGui.BgAddText(x+10,y+31,"Monitoring local Cherax detections",164,168,182,235)
    else
        ImGui.BgAddText(x+10,y+31,
            tostring(#entries).." player(s) noted",205,209,222,238)
        for i=1,max_rows do
            local item=entries[i]
            -- Keep custom notes as entered; clip only for the compact HUD.
            local label
            if item.owner_label then
                local note=input_byte_cap(item.owner_label,34)
                if #note<#item.owner_label then note=note.."..." end
                label=note
            else
                label=tostring(item.hint).." ["..tostring(item.count).."]"
            end
            ImGui.BgAddText(x+10,y+31+i*19,
                item.name:sub(1,16).."  "..label,213,215,226,235)
        end
        if #entries>max_rows then
            ImGui.BgAddText(x+10,y+31+(max_rows+1)*19,
                "+"..tostring(#entries-max_rows).." additional players",157,162,175,220)
        end
    end
end

local EMPTY_PRESENT_ITEMS = {}
local function render_present()
    if not started then return end
    local api = compat_ui()
    if not api then return end
    if State and State.welcome_gate == true then refresh_welcome_gate() end
    local overlay = type(api.GetOverlaySnapshot) == "function" and api.GetOverlaySnapshot() or nil
    -- The configured welcome option remains enabled after boot. Its completed
    -- presentation does not need snapshots, registry counts or draw preparation.
    local welcome_active = State and (tonumber(State.welcome_started_seconds) or 0) ~= 0
    local welcome = welcome_active and type(api.GetWelcomeSnapshot) == "function" and api.GetWelcomeSnapshot() or nil
    local economy = module_context and module_context.CScript and module_context.CScript.Economy
    local economy_hud = economy and type(economy.HudSnapshot) == "function" and economy.HudSnapshot() or nil
    local player = module_context and module_context.CScript and module_context.CScript.Player
    local hud_active = player and (type(player.MessiahHudActive) ~= "function" or player.MessiahHudActive())
    local visuals_active = player and (type(player.MessiahVisualsActive) ~= "function" or player.MessiahVisualsActive())
    local messiah_hud = hud_active and read_messiah_hud_snapshot() or nil
    local messiah_visuals = visuals_active and read_messiah_visual_snapshot() or nil
    local has_overlay = overlay and (overlay.cinematic_bars or overlay.vip or #(overlay.lines or {}) > 0)
    local has_welcome = welcome and (welcome.enabled or welcome.preview) and welcome.started_seconds ~= 0
    local has_economy_hud = economy_hud and economy_hud.enabled == true
    local has_messiah_hud = messiah_hud and messiah_hud.active == true
    if not (ImGui and type(ImGui.GetDisplaySize) == "function" and type(ImGui.GetTime) == "function"
            and type(ImGui.BgAddRectFilled) == "function" and type(ImGui.BgAddText) == "function") then
        return
    end
    local modder_monitor=modder_overlay_snapshot(ui_clock_ms())
    local has_modder_monitor=modder_monitor and modder_monitor.available
    local notifications = module_context and module_context.Notifications
    if notifications and State.SettingsFeaturesRegistered and dependencies and dependencies.is_on then
        if notifications.SetEnabled then notifications.SetEnabled(dependencies.is_on("notifications_enabled")) end
        if notifications.SetProtectionEnabled then notifications.SetProtectionEnabled(dependencies.is_on("protection_notifications")) end
    end
    local has_notifications = notifications and type(notifications.Snapshot) == "function"
        and (type(notifications.Count) ~= "function" or notifications.Count() > 0)
    if not has_overlay and not has_welcome and not has_economy_hud and not has_messiah_hud
        and not messiah_visuals and not has_modder_monitor and not has_notifications then
        return
    end
    local width, height = ImGui.GetDisplaySize()
    local now = ImGui.GetTime()
    local notification_items = has_notifications and notifications.Snapshot(now, 4) or EMPTY_PRESENT_ITEMS
    if not has_overlay and not has_welcome and not has_economy_hud and not has_messiah_hud and not messiah_visuals
        and not has_modder_monitor and #notification_items == 0 then
        return
    end
    render_messiah_visuals(messiah_visuals, width, height)
    if has_modder_monitor then
        local drawn,why=pcall(render_modder_overlay,modder_monitor,width,height)
        if not drawn then log_error_once("modder_overlay",why) end
    end
    if has_overlay then render_cached_overlay(overlay, width, height) end
    if has_welcome then render_welcome_intro(api, welcome, now, width, height) end
    if has_economy_hud then render_economy_hud(economy_hud, width, height) end
    if has_messiah_hud then
        render_messiah_hud(messiah_hud, width, height)
        render_messiah_reticle(messiah_hud, width, height)
    end
    if #notification_items > 0 then
        render_notification_stack(notification_items, width, 24)
    end
end


local function require_binding(name, value)
    if value == nil then error("ui compatibility binding missing " .. name, 3) end
    return value
end

local function stop_camera_effects()
    if not bound then return true end
    dependencies.invoke_void(dependencies.H.CLEAR_TIMECYCLE_MODIFIER)
    dependencies.invoke_void(dependencies.H.STOP_GAMEPLAY_CAM_SHAKING, true)
    dependencies.invoke_void(dependencies.H.ANIMPOSTFX_STOP_ALL)
    return true
end

local function set_cscript_feature_visibility(visible)
    if not bound or not dependencies or not dependencies.FeatureMgr then return 0 end
    local registry = module_context and module_context.CScript and module_context.CScript.FeatureKeys or {}
    State.welcome_hidden_features = State.welcome_hidden_features or {}
    local count = 0
    for key, hash in pairs(registry) do
        hash = tonumber(hash)
        if hash then
            local ok, feature = pcall(dependencies.FeatureMgr.GetFeature, hash)
            if ok and feature and type(feature.SetVisible) == "function" then
                -- Keep the persisted compatibility key private during startup
                -- reveal/replay as well as normal registration.
                local feature_visible = visible == true and key ~= "vehicle_hunter_camera"
                local applied = pcall(function() feature:SetVisible(feature_visible) end)
                if applied then
                    if visible then
                        State.welcome_hidden_features[hash] = nil
                    else
                        State.welcome_hidden_features[hash] = true
                    end
                    count = count + 1
                end
            end
        end
    end
    return count
end

refresh_welcome_gate = function()
    if State.welcome_gate ~= true then return 0 end
    return set_cscript_feature_visibility(false)
end

local stop_welcome

local function startup_registry_count()
    local registry = module_context and module_context.CScript and module_context.CScript.FeatureKeys or {}
    local count = 0
    for _ in pairs(registry) do count = count + 1 end
    return count
end

local function startup_check(key)
    if key == "registry" then
        local count = startup_registry_count()
        -- Outer loader integrity owns completeness. Observe current metadata
        -- here without retaining an obsolete release-count requirement.
        local controls = Presentation.build_metadata().controls
        return count > 0, ("%d feature keys indexed%s"):format(count,
            controls and ("; " .. controls .. " registered controls") or "")
    end
    if key == "player" then
        local player = dependencies and dependencies.Player
        if player and type(player.ConvenienceSnapshot) == "function" then
            local ok, snapshot = pcall(player.ConvenienceSnapshot)
            if ok and type(snapshot) == "table" then
                local status = tostring(snapshot.cold_start_rearm or "IDLE")
                return status == "READY", "Cold-start player/input bridge: " .. status
            end
        end
        return false, "Waiting for the local player/input bridge"
    end
    if key == "session" then
        local pid = dependencies and dependencies.local_player_id and dependencies.local_player_id() or -1
        local ped = dependencies and dependencies.local_ped and dependencies.local_ped() or 0
        local exists = dependencies and dependencies.entity_exists and dependencies.entity_exists(ped) == true
        return tonumber(pid) and pid >= 0 and pid <= 31 and exists,
            ("Local session owner pid=%s ped=%s"):format(tostring(pid), tostring(ped))
    end
    if key == "persistence" then
        local economy = module_context and module_context.CScript and module_context.CScript.Economy
        if economy and type(economy.Snapshot) == "function" then
            local ok, snapshot = pcall(economy.Snapshot)
            if ok and type(snapshot) == "table" then
                local status = tostring(snapshot.persistence_status or "PENDING")
                local pending = status == "PENDING" or status == "PENDING_ACCOUNT"
                    or status == "INIT" or status == "START_RETRY"
                return not pending, "Economy persistence: " .. status
            end
        end
        return false, "Waiting for account/persistence services"
    end
    if key == "interface" then
        return State.ui_state_loaded == true, State.ui_state_loaded == true
            and "UI state loaded; CScript access can be released"
            or "Loading UI state and final access ownership"
    end
    return true, "Ready"
end

local function begin_startup_presentation()
    if not State or State.welcome_preview == true then return false end
    State.welcome_boot_active = true
    State.welcome_post_boot = true
    State.welcome_stage_index = 1
    State.welcome_stage_started_ms = 0
    State.welcome_sequence_started_ms = 0
    State.welcome_ready_started_ms = 0
    State.welcome_ready_render_seconds = 0
    State.welcome_render_compact_logged = false
    State.welcome_render_fullscreen_logged = false
    State.welcome_tasks = {}
    for index, spec in ipairs(STARTUP_STAGE_SPECS) do
        State.welcome_tasks[index] = { key = spec.key, label = spec.label, done = false, detail = "Queued" }
    end
    State.welcome_progress = 0.12
    State.welcome_phase = "VERIFYING REGISTRY"
    State.welcome_detail = "Confirming the CScript-owned feature registry before runtime access"
    State.welcome_ready = false
    State.welcome_status = "Loading"
    refresh_welcome_gate()
    if dependencies and dependencies.log_info then
        dependencies.log_info("Startup presentation armed: real readiness gate active; CScript access remains hidden.")
    end
    return true
end

local function update_startup_presentation(now)
    if State.welcome_gate ~= true or State.welcome_post_boot ~= true or State.welcome_preview == true then return end
    now = tonumber(now) or 0
    if State.welcome_sequence_started_ms == 0 then State.welcome_sequence_started_ms = now end
    if State.welcome_ready == true then
        if State.welcome_ready_started_ms == 0 then State.welcome_ready_started_ms = now end
        if now - State.welcome_ready_started_ms >= math.floor(WELCOME_READY_HOLD_SECONDS * 1000) then
            stop_welcome()
        end
        return
    end

    local index = math.max(1, math.min(#STARTUP_STAGE_SPECS, tonumber(State.welcome_stage_index) or 1))
    local spec = STARTUP_STAGE_SPECS[index]
    if State.welcome_stage_started_ms == 0 then State.welcome_stage_started_ms = now end
    local elapsed = math.max(0, now - State.welcome_stage_started_ms)
    local ready, detail = startup_check(spec.key)
    local timed_out = elapsed >= STARTUP_STAGE_TIMEOUT_MS
    local task = State.welcome_tasks and State.welcome_tasks[index]
    if task then task.detail = detail end

    local phase_map = {
        registry = "VERIFYING REGISTRY",
        player = "ARMING PLAYER RUNTIME",
        session = "CHECKING SESSION",
        persistence = "LOADING PERSISTENCE",
        interface = "FINALIZING INTERFACE",
    }
    State.welcome_phase = phase_map[spec.key] or spec.label
    State.welcome_detail = detail
    State.welcome_progress = math.max(0.12, math.min(spec.progress,
        (STARTUP_STAGE_SPECS[index - 1] and STARTUP_STAGE_SPECS[index - 1].progress or 0.12)
        + (spec.progress - (STARTUP_STAGE_SPECS[index - 1] and STARTUP_STAGE_SPECS[index - 1].progress or 0.12))
        * math.min(1.0, elapsed / math.max(1, spec.min_ms))))

    if (ready and elapsed >= spec.min_ms) or timed_out then
        if task then
            task.done = true
            task.degraded = not ready
            task.detail = ready and detail or ("Timed readiness window; continuing fail-safe: " .. tostring(detail))
        end
        if dependencies and dependencies.log_info then
            dependencies.log_info(("Startup gate stage=%s result=%s elapsedMs=%d detail=%s")
                :format(spec.key, ready and "READY" or "TIMEOUT", elapsed, tostring(detail)))
        end
        index = index + 1
        if index > #STARTUP_STAGE_SPECS then
            State.welcome_stage_index = #STARTUP_STAGE_SPECS
            State.welcome_progress = 1.0
            State.welcome_phase = "READY"
            State.welcome_detail = "All required startup owners are synchronized; releasing CScript access"
            State.welcome_ready = true
            State.welcome_status = "Ready"
            State.welcome_ready_started_ms = now
            State.welcome_ready_render_seconds = -1
        else
            State.welcome_stage_index = index
            State.welcome_stage_started_ms = now
        end
    end
end

local function start_welcome(preview)
    if not bound then return false end
    if preview == true and State.welcome_gate == true then return false end
    State.welcome_started_seconds = -1
    State.welcome_progress = preview == true and 0.0 or 0.02
    State.welcome_phase = preview == true and "PREVIEW" or "STARTING"
    State.welcome_detail = preview == true and "Previewing the startup presentation" or
        "Preparing the CScript-owned feature registry"
    State.welcome_ready = false
    local username = tostring(dependencies.player_name(dependencies.local_player_id()) or "")
        :gsub("^%s+", ""):gsub("%s+$", "")
    if username == "" then username = "Player" end
    State.welcome_username = username
    State.welcome_title = "Welcome back, " .. username
    State.welcome_version = BUILD_UI_LABEL
    State.welcome_status = "Loading"
    State.welcome_preview = preview == true
    State.welcome_boot_active = preview ~= true
    State.welcome_post_boot = false
    State.welcome_stage_index = 1
    State.welcome_stage_started_ms = 0
    State.welcome_sequence_started_ms = 0
    State.welcome_ready_started_ms = 0
    State.welcome_ready_render_seconds = 0
    State.welcome_render_compact_logged = false
    State.welcome_render_fullscreen_logged = false
    State.welcome_tasks = {}
    if preview ~= true then
        State.welcome_gate = true
        State.welcome_hidden_features = {}
        refresh_welcome_gate()
    end
end

local function set_welcome_stage(progress, phase, detail, ready)
    if not State then return false end
    State.welcome_progress = math.max(0.0, math.min(1.0, tonumber(progress) or State.welcome_progress or 0.0))
    State.welcome_phase = tostring(phase or State.welcome_phase or "STARTING")
    State.welcome_detail = tostring(detail or State.welcome_detail or "")
    State.welcome_ready = ready == true
    State.welcome_status = State.welcome_ready and "Ready" or "Loading"
    if State.welcome_gate == true then refresh_welcome_gate() end
    return true
end

stop_welcome = function()
    if State.welcome_gate == true then set_cscript_feature_visibility(true) end
    State.welcome_gate = false
    State.welcome_hidden_features = {}
    State.welcome_started_seconds = 0
    State.welcome_preview = false
    State.welcome_boot_active = false
    State.welcome_post_boot = false
    State.welcome_stage_started_ms = 0
    State.welcome_sequence_started_ms = 0
    State.welcome_ready_started_ms = 0
    State.welcome_ready_render_seconds = 0
    State.welcome_render_compact_logged = false
    State.welcome_render_fullscreen_logged = false
    State.welcome_status = "Ready"
    State.welcome_progress = 1.0
    State.welcome_phase = "READY"
    State.welcome_detail = "CScript runtime access released"
    State.welcome_ready = true
end

local function add_toggle(key, name, description, default, callback)
    local feature = FeatureMgr.AddFeature(
        dependencies.feature_id(key), name, eFeatureType.Toggle, feature_help(name, description) or "", callback
    )
    if not feature then
        return nil
    end
    if feature and type(feature.SetDefaultValue) == "function" then
        pcall(function()
            feature:SetDefaultValue(default == true)
            if default == true and type(feature.Toggle) == "function" and not feature:IsToggled() then
                feature:Toggle(true)
            end
        end)
    end
    State.FeatureRegisteredCount = (State.FeatureRegisteredCount or 0) + 1
    return feature
end

local function add_button(key, name, description, callback)
    local feature = FeatureMgr.AddFeature(
        dependencies.feature_id(key), name, eFeatureType.Button, feature_help(name, description) or "", callback
    )
    if not feature then
        return nil
    end
    State.FeatureRegisteredCount = (State.FeatureRegisteredCount or 0) + 1
    return feature
end

local function add_combo(key, name, description, values, default, callback)
    local feature = FeatureMgr.AddFeature(
        dependencies.feature_id(key), name, eFeatureType.Combo, feature_help(name, description) or "", callback
    )
    if not feature then
        return nil
    end
    if feature then pcall(function() feature:SetList(values):SetListIndex(default or 0) end) end
    State.FeatureRegisteredCount = (State.FeatureRegisteredCount or 0) + 1
    return feature
end

