-- SHVDN Enhanced NativeMemory.Vehicle, commit d756d479337a677cce9853b0cce63471c1fc7b7c.
-- The former RTHandlingEditor pattern is explicitly the Legacy branch there.
-- Enhanced: mov rcx,[rbx+disp32] at match+4; its displacement starts at match+7.
-- No fixed CVehicle pointer offset, Legacy fallback, or arbitrary pointer sweep.
local HANDLING_PATTERN = '48 83 C0 ? 48 8B 8B ? ? ? ? F3 0F 10 89'
local HANDLING_FIXED = {[0]=0x48,[1]=0x83,[2]=0xC0,[4]=0x48,[5]=0x8B,
    [6]=0x8B,[11]=0xF3,[12]=0x0F,[13]=0x10,[14]=0x89}
local ATTACK = {69,70,114}
local WEAPON_CYCLE_ACTIONS = {14,15,16,17,37,99,100,115,116,261,262}
local function integer(x,lo,hi)
    return type(x)=='number' and x==x and x%1==0 and x>=lo and x<=hi
end
local function pointer(x) return integer(x,0x10000,0x00007FFFFFFFEFFF) and x%8==0 end
local function u32(x) return x & 0xFFFFFFFF end
local function finite(x) return type(x)=='number' and x==x and math.abs(x)<10000000 end
-- Enumerate the registry instead of asking the host about a possibly absent hash.
-- A protected Lua call cannot turn a native fail-fast into a normal Lua error.
-- Do not retain foreign feature userdata between native ticks.
local function registered_features(manager,wanted)
    assert(manager and type(manager.GetAllFeatures)=='function',
        'Feature registry enumeration unavailable; no guessed hash lookup')
    local items=manager.GetAllFeatures()
    assert(type(items)=='table' or type(items)=='userdata','Feature registry is not iterable')
    local found,n={},0
    for key,feature in pairs(items) do
        n=n+1;assert(n<=100000,'Feature registry exceeds inspection budget')
        local key_hash=integer(key,-2147483648,4294967295) and u32(key) or nil
        local kind=type(feature)
        if kind=='table' or kind=='userdata' then
            local getter=feature.GetHash
            local fh=type(getter)=='function' and getter(feature) or key_hash
            if integer(fh,-2147483648,4294967295) then
                fh=u32(fh)
                assert(not (key_hash and wanted[key_hash] and fh~=key_hash),
                    'Feature registry identity mismatch')
                if wanted[fh] then
                    assert(found[fh]==nil,'Feature registry contains duplicate identity')
                    found[fh]=feature
                end
            elseif key_hash and wanted[key_hash] then
                error('Requested registry entry has unreadable identity')
            end
        elseif key_hash and wanted[key_hash] then
            error('Requested registry entry is not a feature')
        end
    end
    return found
end
local function create(R)
    local M,N,G,U = R.Memory,R.Natives,R.GTA,R.Utils
    local S={enabled=false,blocked=false,active=nil,status='OFF',detail='Not armed',buffer=nil,
        last_now=nil,last_frame=nil,last_command=-100000,last_input=false,burst=nil,commands=0,shutdown=false,
        select_requested=false,epoch=0,stopping=nil,check_requested=false,mapping_requested=false,
        trace=false,stage='idle',rapid_checked=false,rapid_checked_at=nil,rapid_state=nil,mapping_proof=nil,
        last_cleanup_outcome=nil,pending_messages={},pending_order={},pending_suppressed=0}
    local API={}
    local function log(status,detail)
        detail=tostring(detail or ''):gsub('[\r\n]',' ')
        if status=='RESTORE_PENDING' then
            S.status,S.detail=status,detail
            local now=S.last_now or 0
            local prior=S.pending_messages[detail]
            if prior and now>=prior and now-prior<2000 then
                S.pending_suppressed=S.pending_suppressed+1;return
            end
            if not prior then
                S.pending_order[#S.pending_order+1]=detail
                if #S.pending_order>16 then S.pending_messages[table.remove(S.pending_order,1)]=nil end
            end
            S.pending_messages[detail]=now
            if R.Logger and type(R.Logger.LogInfo)=='function' then
                pcall(R.Logger.LogInfo,('['..ID..'] %s %s'):format(status,detail))
            end
            return
        end
        if S.status~=status or S.detail~=detail then
            S.status,S.detail=status,detail
            if R.Logger and type(R.Logger.LogInfo)=='function' then
                pcall(R.Logger.LogInfo,('['..ID..'] %s %s'):format(status,detail))
            end
        end
    end
    local function stage(name)
        if S.trace then S.stage=name;log('STAGE',name) end
    end
    local function call(fn,...)
        assert(type(fn)=='function','Required Cherax API missing')
        return fn(...)
    end
    local function b(hash,...)
        local v=call(N.InvokeBool,hash,...);assert(type(v)=='boolean','Native boolean read unavailable');return v
    end
    local function i(hash,...)
        local v=call(N.InvokeInt,hash,...);assert(integer(v,-2147483648,4294967295),'Native integer read unavailable');return v
    end
    local function v(hash,...)
        local result=call(N.InvokeVoid,hash,...);assert(result~=false,'Native command rejected')
    end
    local function read(suffix,addr)
        assert(integer(addr,0x10000,0x00007FFFFFFFEFFF),'Invalid memory address')
        local x=call(M['Read'..suffix],addr)
        if suffix=='Float' then assert(finite(x),'Invalid memory float')
        else assert(integer(x,-9223372036854775807,9223372036854775807),'Invalid memory integer') end
        return x
    end
    local function hash(name) return u32(call(U.Joaat,name)) end
    local PROFILES={
        [hash('chernobog')]={name='Chernobog',model=hash('chernobog'),mass=40000.0,
            hashes={0,0,0,0,hash('VEHICLE_WEAPON_CHERNO_MISSILE'),0},seats={0,0,0,0,1,0},
            slot=4,remap_slots={4},weapon=hash('VEHICLE_WEAPON_CHERNO_MISSILE'),interval=4000,turret_speed=5.0},
        [hash('hunter')]={name='FH-1 Hunter',model=hash('hunter'),mass=6000.0,
            hashes={hash('VEHICLE_WEAPON_HUNTER_MG'),hash('VEHICLE_WEAPON_HUNTER_MISSILE'),
                hash('VEHICLE_WEAPON_HUNTER_CANNON'),0,hash('VEHICLE_WEAPON_HUNTER_BARRAGE'),0},
            seats={1,0,1,0,0,0},slot=2,remap_slots={0,2},weapon=hash('VEHICLE_WEAPON_HUNTER_CANNON'),
            interval=334,turret_speed=15.0,requires_cannon=true,
            automatic_mapping=true,native_pilot_input=true},
    }
    local function image()
        local base=call(M.GetBaseAddress,GAME);assert(pointer(base),'Enhanced executable not found')
        -- Header identification stays within the first page. Compare every typed
        -- field to its little-endian bytes; a bad reader is not a new image profile.
        local function unsigned_field(offset,width)
            assert(integer(offset,0,4096-width),'Header field outside first page')
            local suffix=width==2 and 'UShort' or 'UInt'
            local typed=read(suffix,base+offset)
            assert(integer(typed,0,2^(width*8)-1),'Unsigned header read out of range')
            local bytes=0
            for j=0,width-1 do
                local byte=read('UByte',base+offset+j)
                assert(integer(byte,0,255),'Unsigned header byte out of range')
                bytes=bytes+byte*2^(8*j)
            end
            assert(typed==bytes,'Executable header typed/byte readback mismatch')
            return typed
        end
        assert(unsigned_field(0,2)==0x5A4D,'Bad DOS header')
        local pe=unsigned_field(0x3C,4)
        assert(integer(pe,64,1024),'Bad PE header offset')
        assert(unsigned_field(pe,4)==0x4550 and unsigned_field(pe+4,2)==0x8664,
            'Not expected x64 PE')
        local optional=unsigned_field(pe+20,2)
        assert(integer(optional,112,512) and pe+24+optional<=4096,'Bad optional header size')
        assert(unsigned_field(pe+24,2)==0x20B,'Not expected x64 PE')
        local timestamp=unsigned_field(pe+8,4)
        local size=unsigned_field(pe+80,4)
        local profile
        for _,candidate in ipairs(IMAGE_PROFILES) do
            if timestamp==candidate.timestamp and size==candidate.size then profile=candidate;break end
        end
        assert(profile,('Unsupported Enhanced image: TimeDateStamp=%d SizeOfImage=%d; no seat writes made')
            :format(timestamp,size))
        assert(call(M.GetBaseAddress,GAME)==base,'Executable base changed during header read')
        return {base=base,size=size,timestamp=timestamp,pe=pe,optional=optional,
            tag=profile.tag,requires_mapping=profile.requires_mapping}
    end
    local function same_image(a,b)
        return a and b and a.base==b.base and a.size==b.size and a.timestamp==b.timestamp
            and a.pe==b.pe and a.optional==b.optional and a.tag==b.tag
    end
    local function image_pointer(a,img)
        return pointer(a) and a>=img.base and a<img.base+img.size
    end
    local function physical(h,kind)
        assert(b(H.exists,h),'Entity disappeared')
        local obj=call(G.HandleToPointer,h);assert(obj~=nil,'No physical entity')
        local a=call(obj.GetAddress,obj);assert(pointer(a),'Invalid physical address')
        assert(call(G.PointerToHandle,obj)==h,'Entity handle round trip failed')
        assert(call(obj[kind],obj)==true,'Entity type mismatch')
        return a,obj
    end
    local function check_rapid_fire()
        local now=S.last_now or 0
        if S.rapid_checked and S.rapid_checked_at and now>=S.rapid_checked_at
            and now-S.rapid_checked_at<RAPID_FIRE_RECHECK_MS then return end
        stage('dependency-registry: enumerate existing features')
        local h=hash('JinxRebound_vehicle_rapid_fire')
        local feature=registered_features(R.FeatureMgr,{[h]=true})[h]
        local state='ABSENT'
        if feature then
            assert(type(feature.GetName)=='function' and feature:GetName()=='Vehicle Rapid Fire',
                'Rapid Fire registry name does not match; no state query')
            assert(type(feature.IsToggleFeature)=='function' and feature:IsToggleFeature()==true,
                'Rapid Fire registry entry is not a toggle; no state query')
            assert(type(feature.IsToggled)=='function','Rapid Fire state reader unavailable')
            local enabled=feature:IsToggled()
            assert(type(enabled)=='boolean','Rapid Fire state is unreadable')
            state=enabled and 'ON' or 'OFF'
        end
        if S.rapid_state~=state then
            S.rapid_state=state
            log('DEPENDENCY','CScript Vehicle Rapid Fire='..state..'; enumerated registry only')
        end
        assert(state~='ON','Disable CScript Vehicle Rapid Fire for this isolated firing test')
        S.rapid_checked=true;S.rapid_checked_at=now
    end
    local function session_ok()
        if b(H.session) then
            local player_count=i(H.players)
            assert(integer(player_count,1,32),'Online session player count unavailable')
        end
    end
    local function context()
        stage('session: check local test context')
        session_ok()
        check_rapid_fire()
        stage('driver-context: player and vehicle identity')
        local pid=call(G.GetLocalPlayerId);assert(integer(pid,0,31),'No local player')
        local ped=i(H.ped,pid);assert(ped>0 and not b(H.dead,ped,false),'Local ped unavailable')
        local pa=physical(ped,'IsPed')
        local vehicle=i(H.vehicle,ped,false);assert(vehicle>0,'Enter the Chernobog or Hunter as driver')
        local va=physical(vehicle,'IsVehicle')
        assert(i(H.seat,vehicle,-1,false)==ped,'Local player must stay in driver seat')
        assert(i(H.seat,vehicle,0,false)==0,'Passenger/gunner seat is occupied')
        assert(not b(H.dead,vehicle,false),'Vehicle is destroyed')
        if b(H.networked,vehicle) then assert(b(H.control,vehicle),'Vehicle not locally controlled') end
        local model=u32(i(H.model,vehicle));local p=PROFILES[model]
        assert(p,'Only Chernobog and Hunter are supported')
        if p.requires_cannon then assert(i(H.mod,vehicle,10)==0,'Equip the Hunter explosive-cannon upgrade first') end
        return {pid=pid,ped=ped,pa=pa,vehicle=vehicle,va=va,profile=p,model=model}
    end
    local function same_context(a,c)
        return a.pid==c.pid and a.ped==c.ped and a.pa==c.pa and a.vehicle==c.vehicle
            and a.va==c.va and a.model==c.model
    end
    local function buffer()
        if not S.buffer then
            local p=call(M.AllocInt);assert(pointer(p),'Could not allocate weapon readback buffer')
            S.buffer=p
        end
        if type(M.Check)=='function' then assert(M.Check(S.buffer)==true,'Readback guard failed') end
        if type(M.SizeOf)=='function' then assert(M.SizeOf(S.buffer)>=4,'Readback buffer too short') end
        return S.buffer
    end
    local function selected(ped)
        local p=buffer();call(M.WriteInt,p,0)
        if not b(H.selected,ped,p) then return nil end
        return u32(read('UInt',p))
    end
    local function clip(vehicle)
        local p=buffer();call(M.WriteInt,p,-1)
        if not b(H.clip,vehicle,-1,p) then return nil end
        local value=read('Int',p);return integer(value,0,100000) and value or nil
    end
    local function table_ok(a,expected_seat)
        local img=image();assert(same_image(img,a.img),'Executable changed')
        assert(image_pointer(read('Long',a.handling),img),'Handling vtable is outside game image')
        assert(u32(read('UInt',a.handling+8))==a.model,'Handling name does not match vehicle')
        assert(math.abs(read('Float',a.handling+12)-a.profile.mass)<0.01,'Handling mass differs')
        assert(read('Long',a.handling+0x158)==a.array,'Subhandling array changed')
        assert(read('UShort',a.handling+0x160)==a.count,'Subhandling count changed')
        assert(read('UShort',a.handling+0x162)==a.capacity,'Subhandling capacity changed')
        assert(read('Long',a.array+a.index*8)==a.weapon_data,'Weapon subhandling identity changed')
        assert(read('Long',a.weapon_data)==a.vtable and image_pointer(a.vtable,img),'Weapon vtable changed')
        for j=0,5 do
            assert(u32(read('UInt',a.weapon_data+8+j*4))==a.profile.hashes[j+1],'Weapon hash row changed')
            local row=a.seat_rows and a.seat_rows[j]
            local value=read('Int',a.weapon_data+0x20+j*4)
            if expected_seat=='leased' and row and row.attempted then
                -- A rejected/throwing write might still have reached memory.
                -- Only this exact attempted row may be original OR desired.
                assert(value==row.original or value==row.desired,
                    'Leased weapon seat row has a foreign value: '..j)
            else
                local wanted=a.profile.seats[j+1]
                if row and type(expected_seat)=='number' then wanted=expected_seat end
                assert(value==wanted,'Weapon seat row changed outside this test: '..j)
            end
        end
        assert(math.abs(read('Float',a.weapon_data+0x50)-a.profile.turret_speed)<0.001,'Turret-layout discriminator changed')
