    local function owned_key(pointer, field)
        return ("0x%X:%s"):format(pointer, field)
    end

    function VehicleLab.metadata_guard(pointer)
        local state = VehicleLab.state
        state.metadata_guards = state.metadata_guards or {}
        if state.metadata_guards[pointer] then return state.metadata_guards[pointer] end
        local ok, hash = pcall(Memory.ReadUInt, pointer + VehicleLab.weapon_offset.name)
        if not ok or type(hash) ~= "number" or hash % 1 ~= 0 or hash == 0 then
            error("Metadata name hash unavailable before acquiring ownership", 3)
        end
        hash = hash & 0xFFFFFFFF
        -- Capture the resolved slot, not a mutable cache reference. This detects
        -- same-hash records moving to a new slot/address; same-address reuse with
        -- the same hash and slot is still not a unique allocation identity.
        local slot = state.metadata_slots and state.metadata_slots[pointer]
        local guard = function()
            if slot then
                local ok, array, record = pcall(function()
                    local a = slot.header and Memory.ReadLong(slot.header) or state.item_registry_array
                    if a ~= slot.array then return a, nil end
                    return a, Memory.ReadLong(a + slot.index * 8)
                end)
                if not ok or array == nil then return nil, "Registry identity read unavailable" end
                if array ~= slot.array or (record ~= nil and record ~= pointer) then return false end
                if record == nil then return nil, "Registry slot read unavailable" end
            end
            local read_ok, current = pcall(Memory.ReadUInt, pointer + VehicleLab.weapon_offset.name)
            if not read_ok or type(current) ~= "number" or current % 1 ~= 0 then
                return nil, "Metadata identity read unavailable"
            end
            return (current & 0xFFFFFFFF) == hash
        end
        state.metadata_guards[pointer] = guard
        return guard
    end

    local function vehicle_lab_u32(value)
        return (tonumber(value) or 0) & 0xFFFFFFFF
    end

    local function vehicle_lab_plausible_pointer(value)
        value = tonumber(value)
        -- GTA Enhanced/Cherax runs in a normal 64-bit Windows user process. Values
        -- outside canonical user-space are data, not dereferenceable pointers.
        return value ~= nil and value >= 0x10000 and value <= 0x00007FFFFFFFFFFF
    end

    local validate_weapon_runtime_target
    -- Only these live-validated Deluxo steering bits belong to Buff All. Keep
    -- handheld/vehicle identity (including bits 7 and 131) and game flags intact.
    local DELUXO_STEERING_MASKS={flags_0=0x300,flags_3=0x82,flags_4=0x3600000}
    local backend_types = {}
    for name, kind in pairs((module_context and module_context.EnhancedMetadata
            and module_context.EnhancedMetadata.weapon_record_types) or {}) do
        backend_types[Utils.Joaat(name) & 0xFFFFFFFF] = kind
    end
    -- Offsets below were checked against alexguirre's Enhanced b1158g9 parser
    -- dump (CWeaponInfo / CAmmoRocketInfo), not a Legacy C++ layout. Live name,
    -- registry slot, shape, field bounds and write readback still gate use.
    local BACKEND_FIELDS = {
        damage={0,1000000}, reload_time_mp={-1,120}, reload_time_sp={-1,120},
        vehicle_reload_time={-1,120}, time_between_shots={0,120}, cached_fire_delay={-1,120},
        alternate_wait_time={-1,120}, lock_on_range={0,100000}, weapon_range={0,100000},
        lifetime={0,120}, from_vehicle_lifetime={0,120}, player_vehicle_locked_lifetime={-1,120}, launch_speed={0.01,20000},
        time_before_homing={0,20},pitch_change_rate={0,200},yaw_change_rate={0,200},roll_change_rate={0,200},
        use_homing_params={0,1},time_before_starting_homing={0,20},time_before_angle_break={0,20},
        turn_rate_modifier={0,20},pitch_yaw_roll_clamp={0,30},break_lock_angle={-1,10},
        break_lock_angle_close={-1,10},break_lock_close_distance={0,1000},
    }
    local function metadata_gameplay_ready()
        local ok, transition, loading, switching = pcall(function()
            return Natives.InvokeBool(0x520F3282A53D26B7),
                Natives.InvokeBool(0x10D0A8F259E93EC9),Natives.InvokeBool(0xD9D2CFFF49FAB35F)
        end)
        local function off(v) return v==false or v==0 end
        return ok and off(transition) and off(loading) and off(switching)
    end
    function VehicleLab.weapon_backend()
        if VehicleLab.state.backend then return VehicleLab.state.backend end
        local function describe(owner,ptr,field,address,value_type)
            local name=field:gsub('^native_cannon_','')
            local ammo=owner:find('ammo',1,true)~=nil or owner==MEMORY_OWNERS.projectile
                or owner=='vehicle.missile_profile'
            local offsets=ammo and VehicleLab.ammo_offset or VehicleLab.weapon_offset
            local bounds=BACKEND_FIELDS[name]
            local word=name:match('^flags_(%d)$')
            local offset=offsets[name]
            if owner==MEMORY_OWNERS.weapon_buff and not ammo then
                local profile=VehicleLab.state.global_homing_weapon_profile
                local layout=profile and profile.tracking_offsets
                local tracking={buff_bullet_direction_offset=0x934,
                    buff_bullet_direction_pitch_offset=0x938,buff_bullet_direction_pitch_homing_offset=0x93C}
                if tracking[name] and VehicleLab.state.global_homing_weapon_profile_validated
                    and layout and layout.direction==0x934 and layout.pitch==0x938 and layout.homing_pitch==0x93C then
                    offset=tracking[name];bounds={-360,360}
                end
            end
            if word and not ammo and tonumber(word)<=5 then
                offset=offsets.flags+tonumber(word)*4;bounds={0,4294967295}
            end
            local redirect=owner==MEMORY_OWNERS.weapon_buff and field=="buff_ammo_info_redirect"
            if redirect then offset=offsets.ammo_info;bounds={0x10000,0x00007FFFFFFFFFFF} end
            if not bounds or not offset or address~=ptr+offset then
                return nil,'Unsupported field/address: '..field
            end
            local expected_type=redirect and 'long' or name=='use_homing_params' and 'ubyte' or (word and 'uint' or 'float')
            if value_type~=expected_type then return nil,'Field type mismatch' end
            if not metadata_gameplay_ready() then return nil,'Metadata unavailable during loading' end
            local ok,hash=pcall(Memory.ReadUInt,ptr+0x10)
            if not ok or type(hash)~='number' or hash%1~=0 then return nil,'Record identity unavailable' end
            local raw_hash=hash
            hash=hash & 0xFFFFFFFF
            local kind=backend_types[hash]
            if ammo then
                if kind~='CAmmoRocketInfo' then return nil,'Unsupported ammo class for '..name end
                if VehicleLab.find_ammo_ptr(raw_hash)~=ptr then return nil,'Ammo registry identity mismatch' end
            else
                -- Preserve the existing shape-validated weapon path for hashes
                -- absent from this source catalog, but never accept a known ammo.
                if (kind and kind~='CWeaponInfo') or not validate_weapon_runtime_target(ptr,hash) then
                    return nil,'Weapon class/shape unavailable'
                end
            end
            if redirect then
                local original=Memory.ReadLong(ptr+VehicleLab.weapon_offset.ammo_info)
                if not vehicle_lab_plausible_pointer(original)
                    or backend_types[vehicle_lab_u32(Memory.ReadUInt(original+0x10))]~="CAmmoRocketInfo" then
                    return nil,"Ammo redirect requires a verified rocket record"
                end
            end
            local identity=VehicleLab.metadata_guard(ptr)
            local guard=function()
                if not metadata_gameplay_ready() then return nil,'Loading; restoration retained' end
                if redirect then
                    local donor=VehicleLab.find_ammo_ptr(VehicleLab.ammo.deluxo_missile)
                    if donor==0 or backend_types[vehicle_lab_u32(Memory.ReadUInt(donor+0x10))]~="CAmmoRocketInfo" then
                        return nil,"Deluxo donor identity unavailable"
                    end
                end
                return identity()
            end
            return {field=name,type=value_type,min=bounds[1],max=bounds[2],hash=hash,
                mask=owner==MEMORY_OWNERS.weapon_buff and DELUXO_STEERING_MASKS[name] or nil,
                kind=ammo and 'ammo' or 'weapon',record_type=kind or 'shape-validated weapon',guard=guard,
                evidence='Inherited Enhanced candidate; class/shape and field bounds checked; live build unverified'}
        end
        local function priority(owner,field)
            if owner=='vehicle.instant_lock_ammo' then return 120 end
            if owner=='vehicle.missile_profile' then return 80 end
            if owner==MEMORY_OWNERS.ammo_speed then return 100 end
            if owner==MEMORY_OWNERS.ammo_guidance then return 40 end
            if field:find('native_cannon_',1,true)==1 then return 30 end
            return 50
        end
        VehicleLab.state.backend=create_weapon_backend({memory=OwnedMemory,describe=describe,priority=priority,
            now=now_ms,allowed=function()
                return not runtime_writes_suspended and metadata_gameplay_ready()
                    and entity_exists(local_ped())
                    and not invoke_bool(H.IS_ENTITY_DEAD,local_ped(),false)
            end})
        return VehicleLab.state.backend
    end

    local function owned_snapshot(owner, pointer, field, address, value_type)
        local ok, value = VehicleLab.weapon_backend().Snapshot(owner, pointer, field, address, value_type)
        if not ok then error(value, 3) end
        return value
    end

    local function owned_write(owner, pointer, field, address, value, value_type)
        local ok, changed = VehicleLab.weapon_backend().Write(owner, pointer, field, address, value, value_type)
        if not ok then error(changed, 3) end
        return changed
    end

    local function owned_restore(owner, pointer, field)
        local ok, restored = VehicleLab.weapon_backend().Release(owner, pointer, field)
        if not ok then error(restored, 3) end
        return restored
    end

    local function snapshot_fields(owner, pointer, offsets, fields)
        local newly_owned = {}
        local ok, err = pcall(function()
            for _, spec in ipairs(fields) do
                local field = type(spec) == "table" and spec[1] or spec
                local value_type = type(spec) == "table" and spec[2] or "float"
                local address = pointer + offsets[field]
                local current_owner, current_key = OwnedMemory.OwnerOf(address)
                local key = owned_key(pointer, field)
                if not VehicleLab.weapon_backend().Has(owner,pointer,field) then
                    newly_owned[#newly_owned + 1] = field
                end
                owned_snapshot(owner, pointer, field, address, value_type)
            end
        end)
        if ok then return true end
        for index = #newly_owned, 1, -1 do
            pcall(owned_restore, owner, pointer, newly_owned[index])
        end
        return false, tostring(err)
    end

    local function vehicle_lab_same_hash(left, right)
        return vehicle_lab_u32(left) == vehicle_lab_u32(right)
    end

    local function vehicle_lab_is_jet(model)
        return vehicle_lab_same_hash(model, VehicleLab.model.lazer)
            or vehicle_lab_same_hash(model, VehicleLab.model.hydra)
    end


    function VehicleLab.is_native_aircraft_cannon(weapon_hash)
        local hash = vehicle_lab_u32(weapon_hash)
        return hash == vehicle_lab_u32(VehicleLab.weapon.lazer)
            or hash == vehicle_lab_u32(VehicleLab.weapon.savage)
    end


    function VehicleLab.log_native_aircraft_cannon(vehicle, weapon_hash, weapon_ptr)
        weapon_ptr = tonumber(weapon_ptr) or 0
        if weapon_ptr == 0 then return end
        local ammo_hash = 0
        pcall(function()
            local ammo_ptr = Memory.ReadLong(weapon_ptr + VehicleLab.weapon_offset.ammo_info)
            if type(ammo_ptr) == "number" and ammo_ptr ~= 0 then
                ammo_hash = vehicle_lab_u32(Memory.ReadUInt(ammo_ptr + VehicleLab.ammo_offset.name))
            end
        end)
        local weapon_u32 = vehicle_lab_u32(weapon_hash)
        if ammo_hash == 0 then
            log_error_once("aircraft_cannon_ammo_unresolved_" .. tostring(weapon_u32),
                ("Aircraft cannon ammo identity is not ready for nativeWeapon=0x%08X; diagnostics will retry.")
                :format(weapon_u32))
            return
        end
        local signature = table.concat({ tostring(vehicle), tostring(weapon_u32),
            tostring(weapon_ptr), tostring(ammo_hash) }, ":")
        if VehicleLab.state.aircraft_cannon_diagnostic_signature == signature then return end
        VehicleLab.state.aircraft_cannon_diagnostic_signature = signature
        log_info(("Aircraft cannon native passthrough: vehicle=%s nativeWeapon=0x%08X "
            .. "nativeAmmo=0x%08X CScriptSpawn=disabled formerFunction=VehicleLab.fire_cannon "
            .. "formerDefaultWeapon=0x%08X."):format(
            tostring(vehicle), weapon_u32, ammo_hash, vehicle_lab_u32(VehicleLab.weapon.savage)))
    end

    function VehicleLab.restore_native_cannon_profile()
        local balance_clean=VehicleLab.restore_cannon_balance('Cannon profile released')
        local state = VehicleLab.state
        local ptr = tonumber(state.native_cannon_profile_ptr) or 0
        if ptr == 0 then
            state.cannon_active = false
            state.native_cannon_profile_signature = nil
            return balance_clean==true
        end

        local restored = true
        for _, field in ipairs(NATIVE_CANNON_OWNED_FIELDS) do
            local ok, result = pcall(owned_restore, MEMORY_OWNERS.weapon, ptr, field)
            if not ok then
                restored = false
                log_error_once("native_cannon_restore_" .. tostring(ptr) .. "_" .. field, result)
            end
        end
        if restored then
            state.cannon_active = false
            state.native_cannon_profile_ptr = 0
            state.native_cannon_profile_hash = 0
            state.native_cannon_profile_vehicle = 0
            state.native_cannon_profile_signature = nil
            state.native_cannon_profile_original_shot_delay = nil
        end
        return restored and balance_clean==true
    end

    local function restore_native_cannon_fields(ptr, fields)
        local restored = true
        for _, field in ipairs(fields) do
            local ok, result = pcall(owned_restore, MEMORY_OWNERS.weapon, ptr, field)
            if not ok then
                restored = false
                log_error_once("native_cannon_partial_restore_" .. tostring(ptr) .. "_" .. field, result)
            end
        end
        return restored
    end

    function VehicleLab.cannon_parameter_readback(ptr, hash, expected_damage, expected_interval)
        local ok, damage, interval, raw_damage, raw_interval = pcall(function()
            return Natives.InvokeFloat(0x3133B907D8B32053, hash, 0),
                Natives.InvokeFloat(0x065D2AACAD8CF7A4, hash),
                Memory.ReadFloat(ptr + VehicleLab.weapon_offset.damage),
                Memory.ReadFloat(ptr + VehicleLab.weapon_offset.time_between_shots)
        end)
        local function near(a, b, tolerance)
            return type(a) == "number" and type(b) == "number" and a == a and b == b
                and math.abs(a) < 1000000 and math.abs(b) < 1000000 and math.abs(a - b) <= tolerance
        end
        if ok and vehicle_lab_u32(hash)==vehicle_lab_u32(VehicleLab.weapon.lazer)
            and near(interval,0.125,0.0005)
            and (not near(interval,raw_interval,0.0005)
                or (expected_interval and not near(interval,expected_interval,0.0005))) then
            return false, "GTA's cannon interval still differs from the owned weapon fields"
        end
        if not ok or not near(damage, raw_damage, 0.02) or not near(interval, raw_interval, 0.0005)
            or interval <= 0 or interval > 120 or damage < 0 then
            return false, "native getters and Enhanced weapon fields disagree or are unavailable"
        end
        if expected_damage and not near(damage, expected_damage, 0.02) then
            return false, "reported weapon damage has not reached the requested value"
        end
        if expected_interval and not near(interval, expected_interval, 0.0005) then
            return false, "reported firing interval has not reached the requested value"
        end
        return true, {damage=damage, interval=interval}
    end

    function VehicleLab.cannon_profile_readback(ptr,hash,damage,interval,alternate)
        local o=VehicleLab.weapon_offset
        local ok,name,actual_damage,actual_interval,actual_alternate=pcall(function()
            return Memory.ReadUInt(ptr+o.name),Memory.ReadFloat(ptr+o.damage),
                Memory.ReadFloat(ptr+o.time_between_shots),Memory.ReadFloat(ptr+o.alternate_wait_time)
        end)
        local function near(a,b,tolerance)
            return type(a)=='number' and a==a and math.abs(a)<1000000 and math.abs(a-b)<=tolerance
        end
        if not ok or vehicle_lab_u32(name)~=vehicle_lab_u32(hash)
            or not near(actual_damage,damage,.02) or not near(actual_interval,interval,.0005)
            or not near(actual_alternate,alternate,.0005) then
            return false,'Original cannon profile field readback failed'
        end
        return true,{damage=actual_damage,interval=actual_interval,alternate=actual_alternate,basis='owned-profile-fields'}
    end

    function VehicleLab.record_cannon_block(vehicle,hash,reason)
        -- A rejected profile must not remain displayed as enabled. Independent
        -- range and rapid-fire requests keep their own state and diagnostics.
        if is_on("vehicle_lab_cannons") and dependencies and type(dependencies.set_toggle)=="function" then
            pcall(dependencies.set_toggle,"vehicle_lab_cannons",false)
        end
        local state=VehicleLab.state
        state.native_cannon_observation={status="BLOCKED",vehicle=vehicle,hash=hash,
            reason=reason,live_hits_verified=false,explosion_profile_verified=false}
        local signature=tostring(hash)..":"..tostring(reason)
        if state.native_cannon_block_notice~=signature then
            state.native_cannon_block_notice=signature
            toast("Aircraft cannon tuning blocked: "..tostring(reason))
            combat_record("Aircraft Cannons","blocked",reason,"WARN")
        end
    end

