    local rapid_gun_hashes
    function VehicleLab.rapid_requested(hash)
        if is_on("vehicle_rapid_fire") then return true end
        if not is_on("vehicle_rapid_fire_guns") then return false end
        if not rapid_gun_hashes then
            rapid_gun_hashes={}
            for _,name in ipairs(rapid_gun_names) do rapid_gun_hashes[vehicle_lab_u32(Utils.Joaat(name))]=true end
        end
        if hash==nil then hash=select(1,VehicleLab.resolve_weapon_runtime_target(local_ped())) end
        return rapid_gun_hashes[vehicle_lab_u32(hash)]==true
    end

    -- One bounded record for the current stream: pointer churn must not create
    -- an unbounded key map or bypass the global diagnostic pacing limit.
    -- This affects logging only; profile ownership and rebind decisions are unchanged.
    function VehicleLab.log_cannon_profile_event(vehicle, hash, ptr, signature,
            delay, profile, reason, restore_requested, rapid_enabled, range_requested,
            task_rebind, detail)
        local state = VehicleLab.state
        local record = state.native_cannon_log
        if not record then
            record = {suppressed=0, identity_changes=0}
            state.native_cannon_log = record
        end
        local identity = table.concat({tostring(vehicle),tostring(hash),tostring(ptr)}, ":")
        if record.identity and record.identity ~= identity then
            record.identity_changes = math.min(2147483647, record.identity_changes + 1)
        end
        record.identity = identity
        -- GET_GAME_TIMER is elapsed game milliseconds. Do not pace this with the
        -- compatibility clock's os.clock fallback, sampled clockMs, or wall time.
        local clock_ok, clock_value = pcall(invoke_int, H.GET_GAME_TIMER)
        local clock = clock_ok and tonumber(clock_value) or nil
        if not clock or clock ~= clock or clock < 0 or clock >= math.huge then
            record.suppressed = math.min(2147483647, record.suppressed + 1)
            return false
        end
        if record.seen_ms and clock < record.seen_ms then
            -- A session/reset/wrap starts a new interval without authorizing a
            -- burst; keep the last diagnostic and suppressed context until due.
            record.last_ms = clock
        end
        record.seen_ms = clock
        if record.last_ms and clock - record.last_ms < 1000 then
            record.suppressed = math.min(2147483647, record.suppressed + 1)
            return false
        end
        -- Reserve the interval before logging so a reentrant host callback cannot
        -- submit a second line at the same clock value.
        record.last_ms = clock
        local suppressed, changes = record.suppressed, record.identity_changes
        record.suppressed, record.identity_changes = 0, 0
        record.signature = signature
        log_info(("Aircraft cannon profile: vehicle=%s weapon=0x%08X ptr=%s restore=%s rapid=%s "
            .. "range=%s delay=%.3f profile=%s change=%s taskRebind=%s getterReadback=%s "
            .. "suppressed=%d identityChanges=%d; actual hits/cadence remain unverified."):format(
            tostring(vehicle), hash, tostring(ptr), tostring(restore_requested), tostring(rapid_enabled),
            tostring(range_requested), delay, tostring(profile), tostring(reason), tostring(task_rebind),
            tostring(detail), suppressed, changes))
        return true
    end

    function VehicleLab.apply_native_cannon_profile(ped, vehicle, weapon_hash, ptr)
        local state = VehicleLab.state
        ptr = tonumber(ptr) or 0
        local hash = vehicle_lab_u32(weapon_hash)
        local model = entity_exists(vehicle)
            and vehicle_lab_u32(invoke_int(H.GET_ENTITY_MODEL, vehicle)) or 0
        local jet_target = vehicle_lab_is_jet(model)
        local cannon_profile = cannon_profile_choice()
        local restore_requested = is_on("vehicle_lab_cannons") and not cannon_profile.neutral and jet_target
            and hash == vehicle_lab_u32(VehicleLab.weapon.lazer)
        local range_requested = is_on("vehicle_cannon_range") and jet_target
            and hash == vehicle_lab_u32(VehicleLab.weapon.lazer)
        local rapid_enabled = VehicleLab.rapid_requested(hash)
            and VehicleLab.is_native_aircraft_cannon(hash)
        local rapid_delay = rapid_delay_seconds()
        -- Restore-only cadence must not depend on the unrelated Rapid Fire slider.
        local effective_delay = rapid_enabled and rapid_delay
            or cannon_profile.delay or NATIVE_CANNON_PROFILE.restored_time_between_shots

        if (not restore_requested and not range_requested and not rapid_enabled)
            or not entity_exists(ped) or not entity_exists(vehicle) or ptr == 0
            or not VehicleLab.is_native_aircraft_cannon(hash) then
            local timing_ok=VehicleLab.restore_cannon_timing("cannon intent/context unavailable")
            local fields_ok=VehicleLab.restore_native_cannon_profile()
            return timing_ok and fields_ok
        end
        -- A model identifies compatible equipment, not the selected weapon slot.
        -- Recheck immediately before claiming a shared CWeaponInfo record so a
        -- missile selection or an unreadable transition never tunes the cannon.
        local selected_hash = VehicleLab.get_current_vehicle_weapon(ped)
        if not selected_hash or vehicle_lab_u32(selected_hash) ~= hash then
            VehicleLab.restore_cannon_timing("cannon selection changed")
            VehicleLab.restore_native_cannon_profile()
            return false
        end

        local same_target = state.native_cannon_profile_ptr == ptr
            and state.native_cannon_profile_hash == hash
            and state.native_cannon_profile_vehicle == vehicle
        if not same_target and state.native_cannon_profile_ptr ~= 0 then
            if not VehicleLab.restore_native_cannon_profile() then return false end
        end
        if not validate_weapon_runtime_target(ptr, hash) then
            VehicleLab.restore_cannon_timing("cannon record unavailable")
            return false
        end
        local blocked_reason
        if restore_requested then
            -- Drain a legacy cadence lease first; the data-byte candidate does
            -- not use that helper or compare engine timing getters.
            if not VehicleLab.restore_cannon_timing('Switching to the cannon balance data owner')then return false end
            local balance_ok,balance_reason=VehicleLab.ensure_cannon_balance(ped,vehicle,hash,ptr)
            if not balance_ok then
                if (tonumber(state.native_cannon_profile_ptr)or 0)~=0 then VehicleLab.restore_native_cannon_profile()end
                state.native_cannon_observation={status='BALANCE_PENDING',vehicle=vehicle,hash=hash,
                    reason=balance_reason or 'Cannon balance data owner is not active',live_hits_verified=false,
                    explosion_profile_verified=false,balance=VehicleLab.cannon_balance_snapshot()}
                return false
            end
        elseif hash==vehicle_lab_u32(VehicleLab.weapon.lazer) and rapid_enabled then
            local timing_ok,timing_status,timing_reason=VehicleLab.ensure_cannon_timing(ped,vehicle,hash,ptr,restore_requested,rapid_enabled)
            if not timing_ok and restore_requested then
                -- Original cannon metadata is independent of the optional rapid
                -- cadence service. Keep it active while Rapid Fire waits.
                rapid_enabled=false;effective_delay=cannon_profile.delay
                state.rapid_cannon_reason=timing_reason or timing_status or 'Rapid Fire support is unavailable'
            elseif not timing_ok then
                -- Pending cache/preflight keeps user intent and independent Range.
                if same_target and range_requested then
                    local tuning={}
                    for _,field in ipairs(NATIVE_CANNON_OWNED_FIELDS)do
                        if field~="native_cannon_weapon_range"then tuning[#tuning+1]=field end
                    end
                    if not restore_native_cannon_fields(ptr,tuning)then return false end
                else
                    if not VehicleLab.restore_native_cannon_profile()then return false end
                    same_target=false
                end
                blocked_reason=timing_reason or "Waiting for CScript Timing"
                state.native_cannon_observation={status=timing_status=="AUTH_FAILED"and"BLOCKED"or"WAITING_TIMING",vehicle=vehicle,hash=hash,
                    reason=blocked_reason,live_hits_verified=false,explosion_profile_verified=false}
                if not range_requested then return false end
                restore_requested,rapid_enabled=false,false
            end
        else
            VehicleLab.restore_cannon_timing("Cannon timing not requested")
            VehicleLab.restore_cannon_balance('Original cannon profile is not requested')
        end
        if rapid_enabled and not restore_requested then
            local authenticated, reason = VehicleLab.cannon_parameter_readback(ptr, hash)
            if not authenticated then
                VehicleLab.restore_cannon_timing("cannon getter authentication failed")
                VehicleLab.record_cannon_block(vehicle,hash,reason)
                VehicleLab.latch_cannon_auth_failure(hash,reason)
                if not VehicleLab.restore_native_cannon_profile() or not range_requested then return false end
                -- Range has a separate owner intent and still works while an
                -- unverified cadence/damage override is blocked.
                blocked_reason=reason
                restore_requested,rapid_enabled,same_target=false,false,false
            end
        end

        local wanted_range = math.max(180.0, math.min(5000.0,
            slider_float("vehicle_cannon_distance", 5000.0)))
        local signature = table.concat({ tostring(vehicle), tostring(ptr), tostring(hash),
            restore_requested and "1" or "0", range_requested and "1" or "0",
            rapid_enabled and "1" or "0", ("%.3f"):format(effective_delay),
            ("%.1f"):format(wanted_range), cannon_profile.name }, ":")

        state.native_cannon_profile_ptr = ptr
        state.native_cannon_profile_hash = hash
        state.native_cannon_profile_vehicle = vehicle

        local o = VehicleLab.weapon_offset
        local offsets = {
            native_cannon_damage = o.damage,
            native_cannon_reload_time_mp = o.reload_time_mp,
            native_cannon_reload_time_sp = o.reload_time_sp,
            native_cannon_vehicle_reload_time = o.vehicle_reload_time,
            native_cannon_time_between_shots = o.time_between_shots,
            native_cannon_cached_fire_delay = o.cached_fire_delay,
            native_cannon_alternate_wait_time = o.alternate_wait_time,
            native_cannon_weapon_range = o.weapon_range,
        }
        local wanted_fields, wanted_set = {}, {}
        local function want(field)
            if not wanted_set[field] then
                wanted_set[field] = true
                wanted_fields[#wanted_fields + 1] = field
            end
        end
        if restore_requested then
            for _, field in ipairs(NATIVE_CANNON_PROFILE_FIELDS) do want(field) end
        end
        if rapid_enabled then
            for _, field in ipairs(NATIVE_CANNON_RAPID_FIELDS) do want(field) end
        end
        if range_requested then want("native_cannon_weapon_range") end

        if same_target then
            for _, field in ipairs(NATIVE_CANNON_OWNED_FIELDS) do
                if not wanted_set[field] then pcall(owned_restore, MEMORY_OWNERS.weapon, ptr, field) end
            end
        end
        -- Verify ownership on the existing 50 ms maintenance pass. Unchanged
        -- values are not rewritten; external edits suspend that field instead of
        -- creating a write fight with another menu/script.
        local profile_changed = (not same_target)
            or state.native_cannon_profile_signature ~= signature

        local originals, acquired, optional_failed = {}, {}, {}
        local optional={native_cannon_cached_fire_delay=true,native_cannon_reload_time_mp=true,
            native_cannon_reload_time_sp=true,native_cannon_vehicle_reload_time=true}
        for _,field in ipairs(wanted_fields) do
            local ok,value=pcall(owned_snapshot,MEMORY_OWNERS.weapon,ptr,field,ptr+offsets[field],"float")
            if ok then originals[field]=value;acquired[#acquired+1]=field
            elseif optional[field] then
                optional_failed[field]=tostring(value)
                log_error_once("native_cannon_optional_"..tostring(hash).."_"..field,value)
            else
                for index=#acquired,1,-1 do pcall(owned_restore,MEMORY_OWNERS.weapon,ptr,acquired[index]) end
                VehicleLab.restore_cannon_timing("cannon field ownership failed")
                VehicleLab.restore_native_cannon_profile()
                log_error_once("native_cannon_ownership_"..tostring(hash),value)
                return false
            end
        end
        local function optional_write(field,value)
            if originals[field]==nil then return end
            local ok,err=pcall(owned_write,MEMORY_OWNERS.weapon,ptr,field,ptr+offsets[field],value,"float")
            if not ok then optional_failed[field]=tostring(err)
                log_error_once("native_cannon_optional_"..tostring(hash).."_"..field,err) end
        end
        local write_ok, write_err = pcall(function()
            if restore_requested then
                -- Implement the observed getter targets with the existing owned
                -- memory backend. Rapid Fire can override the shared interval;
                -- removing Rapid Fire resumes the selected profile's interval.
                owned_write(MEMORY_OWNERS.weapon, ptr, "native_cannon_damage",
                    ptr + o.damage, cannon_profile.damage, "float")
                owned_write(MEMORY_OWNERS.weapon, ptr, "native_cannon_alternate_wait_time",
                    ptr + o.alternate_wait_time, cannon_profile.alternate, "float")
                owned_write(MEMORY_OWNERS.weapon, ptr, "native_cannon_time_between_shots",
                    ptr + o.time_between_shots, effective_delay, "float")
                -- Do not retain a trigger-cache window longer than the selected
                -- firing interval when Rapid Fire is off. Preserve shorter values.
                if originals.native_cannon_cached_fire_delay ~= nil then
                    optional_write("native_cannon_cached_fire_delay",
                        math.min(originals.native_cannon_cached_fire_delay,effective_delay))
                end
            end
            if rapid_enabled then
                owned_write(MEMORY_OWNERS.weapon, ptr, "native_cannon_time_between_shots",
                    ptr + o.time_between_shots, effective_delay, "float")
                optional_write("native_cannon_cached_fire_delay",0.0)
                -- Alternating barrels have an independent wait. Accelerating
                -- only TimeBetweenShots leaves that second cadence gate intact.
                owned_write(MEMORY_OWNERS.weapon,ptr,"native_cannon_alternate_wait_time",
                    ptr+o.alternate_wait_time,math.min(restore_requested and cannon_profile.alternate or originals.native_cannon_alternate_wait_time,effective_delay),"float")
                for _,field in ipairs({"native_cannon_reload_time_mp","native_cannon_reload_time_sp","native_cannon_vehicle_reload_time"}) do
                    if originals[field]~=nil then optional_write(field,math.min(originals[field],effective_delay)) end
                end
            end
            if range_requested then
                owned_write(MEMORY_OWNERS.weapon, ptr, "native_cannon_weapon_range",
                    ptr + o.weapon_range, wanted_range, "float")
            end
        end)
        if not write_ok then
            VehicleLab.restore_cannon_timing("cannon field write failed")
            VehicleLab.restore_native_cannon_profile()
            log_error_once("native_cannon_write_" .. tostring(hash), write_err)
            return false
        end

        state.cadence_partial=(rapid_enabled or restore_requested) and next(optional_failed)~=nil
        state.cadence_failed_fields=optional_failed
        state.cannon_active = true
        state.native_cannon_profile_signature = signature
        local original_shot_delay = tonumber(originals.native_cannon_time_between_shots)
        if original_shot_delay and original_shot_delay > 0.0 and original_shot_delay < 5.0 then
            state.native_cannon_profile_original_shot_delay = original_shot_delay
        end
        if restore_requested or rapid_enabled then
            -- Check effective getter consumption on maintenance too. A field
            -- write/readback alone must never count as a working firing rate.
            local observed,detail
            if restore_requested then
                observed,detail=VehicleLab.cannon_profile_readback(ptr,hash,cannon_profile.damage,effective_delay,cannon_profile.alternate)
            else
                observed,detail=VehicleLab.cannon_parameter_readback(ptr,hash,nil,effective_delay)
            end
            if not observed then
                VehicleLab.restore_cannon_timing("cannon final getter authentication failed")
                VehicleLab.record_cannon_block(vehicle,hash,detail)
                VehicleLab.latch_cannon_auth_failure(hash,detail)
                if range_requested then
                    local tuning={}
                    for _,field in ipairs(NATIVE_CANNON_OWNED_FIELDS) do
                        if field~="native_cannon_weapon_range" then tuning[#tuning+1]=field end
                    end
                    restore_native_cannon_fields(ptr,tuning)
                    state.native_cannon_profile_signature=nil
                else VehicleLab.restore_native_cannon_profile() end
                return false
            end
            local online=invoke_bool(H.NETWORK_IS_SESSION_ACTIVE)
            state.native_cannon_observation = {status=restore_requested and "BALANCE_AND_PROFILE_APPLIED" or "GETTERS_MATCH",vehicle=vehicle,hash=hash,
                profile=cannon_profile.name, provenance=cannon_profile.provenance,
                values=detail,balance=VehicleLab.cannon_balance_snapshot(),live_hits_verified=false,hydra_observer_baseline=false,
                explosion_profile_verified=false,online_override_unverified=restore_requested and online==true,
                reason=restore_requested and "Original cannon balance data and profile applied; physical cadence, hits and Online explosion behavior remain unverified" or nil}
        elseif not blocked_reason then
            state.native_cannon_observation={status="RANGE_APPLIED",vehicle=vehicle,hash=hash}
        end
        if profile_changed then
            -- A metadata change does not require replacing the player's weapon
            -- task. Retain native selection and its normal reticle lifecycle.
            local observed=state.native_cannon_observation
            VehicleLab.log_cannon_profile_event(vehicle, hash, ptr, signature,
                effective_delay, cannon_profile.name, (not same_target) and "target" or "profile",
                restore_requested, rapid_enabled, range_requested, "native-task-preserved",
                observed and (observed.reason or observed.status) or "UNAVAILABLE")
            VehicleLab.log_native_aircraft_cannon(vehicle, hash, ptr)
        end
        return blocked_reason==nil
    end

    local function vehicle_lab_number_in_range(value, minimum, maximum)
        return type(value) == "number" and value == value and value >= minimum and value <= maximum
    end

    local function vehicle_lab_has_memory_api(names)
        if type(Memory) ~= "table" then return false end
        for _, name in ipairs(names) do
            if type(Memory[name]) ~= "function" then return false end
        end
        return true
    end

    function VehicleLab.ensure_weapon_hash_ptr()
        local state = VehicleLab.state
        if state.weapon_hash_ptr ~= 0 then return true end
        if not vehicle_lab_has_memory_api({ "AllocInt", "WriteUInt", "ReadUInt" }) then
            log_error_once("vehicle_lab_weapon_pointer", "Vehicle Lab weapon pointer APIs are unavailable.")
            return false
        end
        local ok, pointer = pcall(Memory.AllocInt)
        if not ok or type(pointer) ~= "number" or pointer == 0 then
            log_error_once("vehicle_lab_weapon_pointer", pointer or "Memory.AllocInt failed")
            return false
        end
        state.weapon_hash_ptr = pointer
        return true
    end

    function VehicleLab.get_current_vehicle_weapon(ped)
        local state = VehicleLab.state
        if ped == 0 or not VehicleLab.ensure_weapon_hash_ptr() then return nil end
        local ok, result = pcall(function()
            Memory.WriteUInt(state.weapon_hash_ptr, 0)
            local accepted=Natives.InvokeBool(H.GET_CURRENT_PED_VEHICLE_WEAPON,ped,state.weapon_hash_ptr)
            if accepted~=true and accepted~=1 then
                state.mounted_weapon_status=(accepted==false or accepted==0) and "NOT_SELECTED" or "UNREADABLE"
                return nil
            end
            local hash=Memory.ReadUInt(state.weapon_hash_ptr)
            if type(hash)~="number" or hash%1~=0 or hash==0 then
                state.mounted_weapon_status="EMPTY_OUTPUT";return nil
            end
            state.mounted_weapon_status="READ"
            return vehicle_lab_u32(hash)
        end)
        if not ok then
            state.mounted_weapon_status="NATIVE_ERROR"
            log_error_once("vehicle_lab_vehicle_weapon", result)
            return nil
        end
        return result
    end


    function VehicleLab.read_ammo_profile(ammo_ptr)
        local offset = VehicleLab.ammo_offset
        return {
            launch_speed = Memory.ReadFloat(ammo_ptr + offset.launch_speed),
            time_before_homing = Memory.ReadFloat(ammo_ptr + offset.time_before_homing),
            pitch_change_rate = Memory.ReadFloat(ammo_ptr + offset.pitch_change_rate),
            yaw_change_rate = Memory.ReadFloat(ammo_ptr + offset.yaw_change_rate),
            roll_change_rate = Memory.ReadFloat(ammo_ptr + offset.roll_change_rate),
            use_homing_params = Memory.ReadUByte(ammo_ptr + offset.use_homing_params),
            time_before_starting_homing = Memory.ReadFloat(ammo_ptr + offset.time_before_starting_homing),
            time_before_angle_break = Memory.ReadFloat(ammo_ptr + offset.time_before_angle_break),
            turn_rate_modifier = Memory.ReadFloat(ammo_ptr + offset.turn_rate_modifier),
            pitch_yaw_roll_clamp = Memory.ReadFloat(ammo_ptr + offset.pitch_yaw_roll_clamp),
            break_lock_angle = Memory.ReadFloat(ammo_ptr + offset.break_lock_angle),
            break_lock_angle_close = Memory.ReadFloat(ammo_ptr + offset.break_lock_angle_close),
            break_lock_close_distance = Memory.ReadFloat(ammo_ptr + offset.break_lock_close_distance),
        }
    end

    function VehicleLab.initialize_item_registry()
        local state = VehicleLab.state
        if state.item_registry_array ~= 0 and state.item_registry_count > 0 and state.item_registry_header then
            -- Registry storage/count can change without changing a cached record's
            -- name. Never scan an old array or reuse its negative lookup cache.
            local ok, array, count = pcall(function()
                return Memory.ReadLong(state.item_registry_header), Memory.ReadUShort(state.item_registry_header + 8)
            end)
            if not ok or not vehicle_lab_plausible_pointer(array)
                or type(count) ~= "number" or count % 1 ~= 0 or count < 100 or count > 4096 then
                state.item_registry_status = "READ_UNAVAILABLE"
                return false
            end
            if array ~= state.item_registry_array or count ~= state.item_registry_count then
                for _, cache in ipairs({state.item_ptr_cache, state.ammo_ptr_cache}) do
                    for key in pairs(cache) do cache[key] = nil end
                end
                state.item_lookup_retry = {}
                state.item_registry_generation = (state.item_registry_generation or 0) + 1
                state.item_registry_array, state.item_registry_count = array, count
            end
            state.item_registry_status = "HEADER_RECHECKED"
            return true
        end
        if state.item_registry_error ~= nil then return false end

        if not vehicle_lab_has_memory_api({
                "Scan", "Rip", "ReadLong", "ReadUShort", "ReadUInt", "ReadFloat", "ReadUByte",
                "WriteFloat", "WriteUByte",
            }) then
            state.item_registry_error = "required Memory APIs are unavailable"
            log_error_once("vehicle_lab_registry", state.item_registry_error)
            return false
        end

        local ok, item_array, item_count, item_header = pcall(function()
            local preboot = __CSCRIPT_PREBOOT_CACHE
            local cached = type(preboot) == "table" and preboot.memory and preboot.memory.item_registry or nil
            local match = type(cached) == "table" and cached.address or nil
            if type(match) ~= "number" or match == 0 then
                match = Memory.Scan(VehicleLab.item_registry_pattern, "GTA5_Enhanced.exe")
            end
            if type(match) ~= "number" or match == 0 then
                error("Enhanced CItemInfo registry signature was not found")
            end
            local registry_header = Memory.Rip(match + 3)
            if not vehicle_lab_plausible_pointer(registry_header) then
                error("CItemInfo registry RIP target was null")
            end

            local array = Memory.ReadLong(registry_header)
            local count = Memory.ReadUShort(registry_header + 8)
            if not vehicle_lab_plausible_pointer(array) then
                error("CItemInfo registry array was null")
            end
            if type(count) ~= "number" or count % 1 ~= 0 or count < 100 or count > 4096 then
                error("CItemInfo registry count failed validation: " .. tostring(count))
            end
            return array, count, registry_header
        end)

        if not ok then
            state.item_registry_error = tostring(item_array)
            log_error_once("vehicle_lab_registry", state.item_registry_error)
            return false
        end

        state.item_registry_array = item_array
        state.item_registry_count = item_count
        state.item_registry_header = item_header
        state.item_registry_status = "RESOLVED"
        state.item_registry_generation = (state.item_registry_generation or 0) + 1
        state.item_registry_error = nil
        log_info(("Vehicle Lab item registry ready: %d entries."):format(item_count))
        return true
    end

    function VehicleLab.lookup_item_hash(item_hash, cache, label)
        local state = VehicleLab.state
        local wanted = vehicle_lab_u32(item_hash)
        if wanted == 0 or not VehicleLab.initialize_item_registry() then return 0 end
        state.metadata_slots = state.metadata_slots or {}
        state.item_lookup_retry = state.item_lookup_retry or {}
        local retry_key = tostring(label) .. ":" .. tostring(wanted)
        local now = type(now_ms) == "function" and now_ms() or 0
        local cached = cache[wanted]
        if type(cached) == "number" and cached ~= 0 then
            local slot = state.metadata_slots[cached]
            local ok, observed, same_slot = pcall(function()
                local same = slot == nil or (slot.array == state.item_registry_array
                    and slot.index < state.item_registry_count
                    and Memory.ReadLong(slot.array + slot.index * 8) == cached)
                return Memory.ReadUInt(cached + VehicleLab.weapon_offset.name), same
            end)
            if ok and same_slot and type(observed) == "number" and observed % 1 == 0
                and vehicle_lab_u32(observed) == wanted then return cached end
            cache[wanted] = nil
            state.item_lookup_retry[retry_key] = nil
            log_error_once("vehicle_item_cache_" .. tostring(wanted),
                "Cached " .. label .. " metadata changed identity or registry slot; resolving again.")
        elseif cached == false then
            local retry = state.item_lookup_retry[retry_key]
            if retry and now >= retry - 1000 and now < retry then return 0 end
        end
        local ok, ptr, slot_index = pcall(function()
            for index = 0, state.item_registry_count - 1 do
                local candidate = Memory.ReadLong(state.item_registry_array + index * 8)
                if vehicle_lab_plausible_pointer(candidate) then
                    local hash = Memory.ReadUInt(candidate + VehicleLab.weapon_offset.name)
                    if type(hash) == "number" and hash % 1 == 0 and vehicle_lab_u32(hash) == wanted then
                        -- Confirm the slot still holds this record after reading it.
                        if Memory.ReadLong(state.item_registry_array + index * 8) ~= candidate then
                            error("CItemInfo slot changed during resolution")
                        end
                        return candidate, index
                    end
                end
            end
            return 0
        end)
        if not ok then
            log_error_once("vehicle_item_lookup_" .. tostring(wanted), ptr)
            cache[wanted] = false
            state.item_lookup_retry[retry_key] = now + 1000
            return 0
        end
        cache[wanted] = ptr ~= 0 and ptr or false
        state.item_lookup_retry[retry_key] = ptr == 0 and now + 1000 or nil
        if ptr ~= 0 then
            state.metadata_slots[ptr] = {header=state.item_registry_header, array=state.item_registry_array,
                index=slot_index, hash=wanted}
        end
        return ptr
    end

    function VehicleLab.find_ammo_ptr(ammo_hash)
        return VehicleLab.lookup_item_hash(ammo_hash, VehicleLab.state.ammo_ptr_cache, "ammo")
    end

    function VehicleLab.find_item_ptr(item_hash)
        local expected = vehicle_lab_u32(item_hash)
        if VehicleLab.state.invalid_weapon_info_hashes[expected] then return 0 end
        return VehicleLab.lookup_item_hash(expected, VehicleLab.state.item_ptr_cache, "weapon")
    end

    -- Populate only due weapon-cache entries from one stable registry pass.
    -- The normal per-record lookup and write guards still run after prefetch.
    function VehicleLab.prefetch_item_ptrs(hashes)
        local state=VehicleLab.state
        if not VehicleLab.initialize_item_registry() then return false end
        local header,array,count,generation=state.item_registry_header,state.item_registry_array,
            state.item_registry_count,state.item_registry_generation
        local cache=state.item_ptr_cache
        state.metadata_slots=state.metadata_slots or {}
        state.item_lookup_retry=state.item_lookup_retry or {}
        local now=type(now_ms)=="function" and now_ms() or 0
        local due,remaining={},0
        for item_hash in pairs(hashes) do
            local wanted=vehicle_lab_u32(item_hash)
            if wanted~=0 and not state.invalid_weapon_info_hashes[wanted] then
                local key="weapon:"..tostring(wanted)
                local cached=cache[wanted]
                local valid=false
                if type(cached)=="number" and cached~=0 then
                    local slot=state.metadata_slots[cached]
                    local ok,observed,same_slot=pcall(function()
                        local same=slot==nil or (slot.array==array and slot.index<count
                            and Memory.ReadLong(slot.array+slot.index*8)==cached)
                        return Memory.ReadUInt(cached+VehicleLab.weapon_offset.name),same
                    end)
                    valid=ok and same_slot and type(observed)=="number"
                        and observed%1==0 and vehicle_lab_u32(observed)==wanted
                    if not valid then cache[wanted]=nil;state.item_lookup_retry[key]=nil end
                elseif cached==false then
                    local retry=state.item_lookup_retry[key]
                    valid=retry and now>=retry-1000 and now<retry
                end
                if not valid and not due[wanted] then due[wanted]=true;remaining=remaining+1 end
            end
        end
        if remaining==0 then return true end
        local function current_header()
            return Memory.ReadLong(header)==array and Memory.ReadUShort(header+8)==count
                and state.item_registry_header==header and state.item_registry_array==array
                and state.item_registry_count==count and state.item_registry_generation==generation
        end
        local ok,found=pcall(function()
            if not current_header() then error("CItemInfo registry changed before batch resolution") end
            local result={}
            for index=0,count-1 do
                local pointer=Memory.ReadLong(array+index*8)
                if vehicle_lab_plausible_pointer(pointer) then
                    local observed=Memory.ReadUInt(pointer+VehicleLab.weapon_offset.name)
                    if type(observed)=="number" and observed%1==0 then
                        local wanted=vehicle_lab_u32(observed)
                        if due[wanted] and not result[wanted] then
                            if Memory.ReadLong(array+index*8)~=pointer then
                                error("CItemInfo slot changed during batch resolution")
                            end
                            result[wanted]={pointer=pointer,index=index}
                            remaining=remaining-1
                            if remaining==0 then break end
                        end
                    end
                end
            end
            if not current_header() then error("CItemInfo registry changed during batch resolution") end
            for wanted,row in pairs(result) do
                local observed=Memory.ReadUInt(row.pointer+VehicleLab.weapon_offset.name)
                if Memory.ReadLong(array+row.index*8)~=row.pointer or type(observed)~="number"
                    or observed%1~=0 or vehicle_lab_u32(observed)~=wanted then
                    error("CItemInfo identity changed before batch publication")
                end
            end
            if not current_header() then error("CItemInfo registry changed before batch publication") end
            return result
        end)
        if not ok then
            -- Reconcile a changed header without publishing old-generation
            -- positives or negatives. The caller retries through its normal tick.
            VehicleLab.initialize_item_registry()
            log_error_once("vehicle_item_batch",found)
            return false
        end
        for wanted in pairs(due) do
            local row=found[wanted]
            cache[wanted]=row and row.pointer or false
            state.item_lookup_retry["weapon:"..tostring(wanted)]=not row and now+1000 or nil
            if row then
                state.metadata_slots[row.pointer]={header=header,array=array,index=row.index,hash=wanted}
            end
        end
        return true
    end

    local function vehicle_weapon_flag_word(bit)
        bit = math.max(0, math.floor(tonumber(bit) or 0))
        return math.floor(bit / 32), bit % 32
    end

    function VehicleLab.read_weapon_flag(ptr, bit)
        local word, shift = vehicle_weapon_flag_word(bit)
        local value = Memory.ReadUInt(ptr + VehicleLab.weapon_offset.flags + word * 4)
        return (value & (1 << shift)) ~= 0
    end


    local function vehicle_lab_close_float(value, expected, tolerance)
        return type(value) == "number"
            and math.abs(value - expected) <= (tolerance or 0.001)
    end

    function VehicleLab.validate_deluxo_flag_layout(ptr)
        local base = VehicleLab.weapon_offset.flags
        local function flag(bit)
            local word = math.floor(bit / 32)
            local shift = bit % 32
            local value = Memory.ReadUInt(ptr + base + word * 4)
            return (value & (1 << shift)) ~= 0
        end
        local expected_true = { 6, 8, 9, 46, 47, 103, 149, 150, 152 }
        for _, bit in ipairs(expected_true) do
            if not flag(bit) then return false, "missing-source-bit-" .. tostring(bit) end
        end
        -- Enhanced metadata: Mk I carries AssistedAimVehicleWeapon (97), Deluxo does not.
        if flag(97) then return false, "unexpected-assisted-aim-bit-97" end
        if flag(153) then return false, "unexpected-alternate-guidance-bit-153" end
        return true
    end

    function VehicleLab.calibrate_deluxo_tracking_layout(ptr)
        local expected = DELUXO_WEAPON_TRACKING_PROFILE
        local function probe(layout)
            local ok, a, b, c = pcall(function()
                return Memory.ReadFloat(ptr + layout.direction),
                    Memory.ReadFloat(ptr + layout.pitch),
                    Memory.ReadFloat(ptr + layout.homing_pitch)
            end)
            if not ok then return nil end
            if vehicle_lab_close_float(a, expected.expected_direction_offset, 0.01)
                and vehicle_lab_close_float(b, expected.expected_pitch_offset, 0.01)
                and vehicle_lab_close_float(c, expected.expected_pitch_homing_offset, 0.01) then
                return {
                    direction = layout.direction,
                    pitch = layout.pitch,
                    homing_pitch = layout.homing_pitch,
                    source = layout.source,
                    direction_value = a,
                    pitch_value = b,
                    homing_pitch_value = c,
                }
            end
            return nil
        end

        for _, layout in ipairs(DELUXO_TRACKING_LAYOUT_CANDIDATES) do
            local matched = probe(layout)
            if matched then return matched end
        end

        -- Read-only bounded fallback: look only for the exact Deluxo
        -- tracking tuple on aligned floats in the CWeaponInfo tail. No address from
        -- this scan is writable unless all three values match in sequence.
        for direction = 0x880, 0x980, 4 do
            local matched = probe({
                direction = direction,
                pitch = direction + 4,
                homing_pitch = direction + 8,
                source = "live-deluxo-tail-scan",
            })
            if matched then return matched end
        end
        return nil
    end

    function VehicleLab.read_deluxo_weapon_tracking_profile()
        local state = VehicleLab.state
        if state.global_homing_weapon_profile_validated and state.global_homing_weapon_profile then
            local cached=state.global_homing_weapon_profile
            if VehicleLab.find_item_ptr(VehicleLab.weapon.deluxo_missile)==cached.ptr
                and validate_weapon_runtime_target(cached.ptr,VehicleLab.weapon.deluxo_missile) then
                return cached
            end
            state.global_homing_weapon_profile_validated=false
            state.global_homing_weapon_profile=nil
        end

        local ptr = VehicleLab.find_item_ptr(VehicleLab.weapon.deluxo_missile)
        if ptr == 0 or not validate_weapon_runtime_target(ptr, VehicleLab.weapon.deluxo_missile) then
            state.global_homing_weapon_profile_error =
            "VEHICLE_WEAPON_DELUXO_MISSILE CWeaponInfo was not available"
            return nil, state.global_homing_weapon_profile_error
        end

        local o = VehicleLab.weapon_offset
        local expected = DELUXO_WEAPON_TRACKING_PROFILE
        local ok, lock_on_range, weapon_range = pcall(function()
            local backend=VehicleLab.weapon_backend()
            return backend.Baseline(ptr,"lock_on_range",Memory.ReadFloat(ptr+o.lock_on_range)),
                backend.Baseline(ptr,"weapon_range",Memory.ReadFloat(ptr+o.weapon_range))
        end)
        if not ok or not vehicle_lab_close_float(lock_on_range, expected.expected_lock_on_range, 0.01)
            or not vehicle_lab_close_float(weapon_range, expected.expected_weapon_range, 0.01) then
            state.global_homing_weapon_profile_error =
                ("Deluxo CWeaponInfo identity validation failed (lock=%s range=%s)")
                :format(tostring(lock_on_range), tostring(weapon_range))
            return nil, state.global_homing_weapon_profile_error
        end

        -- CWeaponInfo places WeaponFlags at 0x900. The bit signature is diagnostic
        -- because bit enumeration can shift independently of field offsets;
        -- the exact pitch tuple below remains a required validation gate.
        local flags_call_ok, flags_valid, flags_reason = pcall(VehicleLab.validate_deluxo_flag_layout, ptr)
        if not flags_call_ok or flags_valid ~= true then
            local reason = flags_call_ok and flags_reason or flags_valid
            state.global_homing_weapon_profile_error="Deluxo steering flag validation failed: "..tostring(reason)
            log_error_once("vehicle_deluxo_flag_signature_diag",
                "Deluxo WeaponFlags signature diagnostic did not fully match: " .. tostring(reason))
            return nil,state.global_homing_weapon_profile_error
        end

        local layout = VehicleLab.calibrate_deluxo_tracking_layout(ptr)
        if not layout or layout.direction~=0x934 or layout.pitch~=0x938 or layout.homing_pitch~=0x93C then
            state.global_homing_weapon_profile_error =
            "Deluxo tracking tuple is not validated at the current Enhanced weapon layout"
            return nil, state.global_homing_weapon_profile_error
        end

        local profile = {
            ptr = ptr,
            lock_on_range = lock_on_range,
            weapon_range = weapon_range,
            direction_offset = layout.direction_value,
            pitch_offset = layout.pitch_value,
            pitch_homing_offset = layout.homing_pitch_value,
            tracking_offsets = layout,
            steering_flags = {
                [8] = VehicleLab.read_weapon_flag(ptr, 8),
                [9] = VehicleLab.read_weapon_flag(ptr, 9),
                [97] = VehicleLab.read_weapon_flag(ptr, 97),
                [103] = VehicleLab.read_weapon_flag(ptr, 103),
                [149] = VehicleLab.read_weapon_flag(ptr, 149),
                [150] = VehicleLab.read_weapon_flag(ptr, 150),
                [152] = VehicleLab.read_weapon_flag(ptr, 152),
                [153] = VehicleLab.read_weapon_flag(ptr, 153),
            },
        }

        state.global_homing_weapon_profile_validated = true
        state.global_homing_weapon_profile = profile
        log_info(("Deluxo weapon tracking profile LIVE validated: pitch=%.3f homingPitch=%.3f "
                .. "lock=%.1f range=%.1f offsets=0x%X/0x%X/0x%X source=%s flags=0x%X.")
            :format(profile.pitch_offset, profile.pitch_homing_offset,
                profile.lock_on_range, profile.weapon_range,
                layout.direction, layout.pitch, layout.homing_pitch,
                tostring(layout.source), VehicleLab.weapon_offset.flags))
        return profile
    end

    function VehicleLab.collect_homing_weapon_candidates(mapped_weapon, current_weapon)
        local candidates = {}

        local function add_weapon_hash(weapon_hash)
            weapon_hash = vehicle_lab_u32(weapon_hash)
            if weapon_hash == 0 then return end
            if VehicleMods and type(VehicleMods.is_projectile_weapon) == "function"
                and not VehicleMods.is_projectile_weapon(weapon_hash) then
                return
            end
            local ptr = VehicleLab.find_item_ptr(weapon_hash)
            if ptr ~= 0 and candidates[ptr] == nil
                and validate_weapon_runtime_target(ptr, weapon_hash) then
                candidates[ptr] = weapon_hash
            end
        end

        -- Reading CWeaponInfo offsets on arbitrary CItemInfo objects can crash
        -- the host. Admit only the current vehicle's mapped missile weapon and
        -- the native-selected weapon when it matches a known Enhanced missile hash.
        add_weapon_hash(mapped_weapon)
        add_weapon_hash(current_weapon)
        return candidates
    end

    function VehicleLab.apply_global_homing_weapon_profile(ptr, weapon_hash, source)
        local state = VehicleLab.state
        ptr = tonumber(ptr) or 0
        if ptr == 0 or not source then return false end
        if not validate_weapon_runtime_target(ptr, weapon_hash) then return false end

        local o = VehicleLab.weapon_offset
        if state.global_homing_weapon_ptrs[ptr] == nil then
            local acquired = {}
            local ok, err = pcall(function()
                for _, spec in ipairs(GLOBAL_HOMING_WEAPON_FLOAT_FIELDS) do
                    local owned_name, value_type, offset_key = spec[1], spec[2], spec[3]
                    local offset = source.tracking_offsets and source.tracking_offsets[offset_key]
                    if type(offset) ~= "number" then
                        error("validated Deluxo tracking offset missing: " ..
                            tostring(offset_key))
                    end
                    owned_snapshot(MEMORY_OWNERS.weapon_buff, ptr, owned_name,
                        ptr + offset, value_type)
                    acquired[#acquired + 1] = owned_name
                end
            end)
            if not ok then
                for index = #acquired, 1, -1 do
                    pcall(owned_restore, MEMORY_OWNERS.weapon_buff, ptr, acquired[index])
                end
                log_error_once("vehicle_buff_weapon_ownership_" .. tostring(ptr), err)
                return false
            end
            state.global_homing_weapon_ptrs[ptr] = vehicle_lab_u32(weapon_hash)
        end

        local ok, err = pcall(function()
            local tracking = source.tracking_offsets
            if type(tracking) ~= "table" then error("validated Deluxo tracking layout is missing") end
            owned_write(MEMORY_OWNERS.weapon_buff, ptr, "buff_bullet_direction_offset",
                ptr + tracking.direction, source.direction_offset, "float")
            owned_write(MEMORY_OWNERS.weapon_buff, ptr, "buff_bullet_direction_pitch_offset",
                ptr + tracking.pitch, source.pitch_offset, "float")
            owned_write(MEMORY_OWNERS.weapon_buff, ptr, "buff_bullet_direction_pitch_homing_offset",
                ptr + tracking.homing_pitch, source.pitch_homing_offset, "float")
            local direction = Memory.ReadFloat(ptr + tracking.direction)
            local pitch = Memory.ReadFloat(ptr + tracking.pitch)
            local homing_pitch = Memory.ReadFloat(ptr + tracking.homing_pitch)
            if not vehicle_lab_close_float(direction, source.direction_offset, 0.01)
                or not vehicle_lab_close_float(pitch, source.pitch_offset, 0.01)
                or not vehicle_lab_close_float(homing_pitch, source.pitch_homing_offset, 0.01) then
                error(("read-back mismatch direction=%.3f pitch=%.3f homingPitch=%.3f")
                    :format(direction, pitch, homing_pitch))
            end
        end)
        if not ok then
            log_error_once("vehicle_buff_weapon_write_" .. tostring(ptr), err)
            return false
        end
        return true
    end

    function VehicleLab.restore_global_homing_weapon_profiles()
        local state = VehicleLab.state
        local ptrs = {}
        for ptr in pairs(state.global_homing_weapon_ptrs) do ptrs[#ptrs + 1] = ptr end
        local restored = true
        for _, ptr in ipairs(ptrs) do
            for _, spec in ipairs(GLOBAL_HOMING_WEAPON_FLOAT_FIELDS) do
                local ok, result = pcall(owned_restore, MEMORY_OWNERS.weapon_buff, ptr, spec[1])
                if not ok then
                    restored = false
                    log_error_once("vehicle_buff_weapon_restore_" .. tostring(ptr) .. "_" .. spec[1], result)
                end
            end
            if restored then state.global_homing_weapon_ptrs[ptr] = nil end
        end
        if restored then state.global_homing_weapon_ptrs = {} end
        return restored
    end

    function VehicleLab.capture_weapon_runtime(ptr, weapon_hash)
        local state=VehicleLab.state
        if state.weapon_runtime_snapshots[ptr] then return state.weapon_runtime_snapshots[ptr] end
        if not validate_weapon_runtime_target(ptr,weapon_hash) then return nil end
        local snap={hash=vehicle_lab_u32(weapon_hash),flag_words={}}
        -- Snapshot only requested writable fields in the shared ledger. A missing
        -- reload field must not disable separately supported acquisition distance.
        for _,field in ipairs(WEAPON_FLOAT_FIELDS) do
            local ok,value=pcall(Memory.ReadFloat,ptr+VehicleLab.weapon_offset[field])
            if ok then snap[field]=VehicleLab.weapon_backend().Baseline(ptr,field,value) end
        end
        state.weapon_runtime_snapshots[ptr]=snap
        return snap
    end

    function VehicleLab.write_effective_cadence(ptr, snap, rapid_delay)
        ptr = tonumber(ptr) or 0
        if ptr == 0 or type(snap) ~= "table" then return false end
        rapid_delay = math.max(RAPID_DELAY_SAFE_FLOOR_SECONDS, tonumber(rapid_delay) or rapid_delay_seconds())
        local o = VehicleLab.weapon_offset
        local fields = {
            {"time_between_shots", rapid_delay}, {"cached_fire_delay", 0.0},
            {"alternate_wait_time"}, {"reload_time_mp"}, {"reload_time_sp"}, {"vehicle_reload_time"},
        }
        local failed, applied = {}, {}
        for _,row in ipairs(fields) do
            local field=row[1]
            local ok,err=pcall(function()
                local value=row[2]
                if value==nil then
                    assert(type(snap[field])=="number", "baseline unavailable")
                    value=math.min(snap[field],rapid_delay)
                end
                owned_write(MEMORY_OWNERS.weapon,ptr,field,ptr+o[field],value,"float")
            end)
            if ok then applied[field]=true else
                failed[field]=tostring(err)
                log_error_once("vehicle_effective_cadence_"..tostring(ptr).."_"..field,err)
            end
        end
        local state = VehicleLab.state
        state.cadence_partial=next(failed)~=nil
        state.cadence_failed_fields=failed
        state.cadence_applied_fields=applied
        state.diagnostic_stock_firing_delay = tonumber(snap.time_between_shots)
        state.diagnostic_effective_firing_delay = applied.time_between_shots and rapid_delay or nil
        state.diagnostic_cadence_ptr = ptr
        -- Supported fields remain owned even if an unrelated optional field is
        -- rejected. This is parameter application, not measured firing cadence.
        return applied.time_between_shots==true
    end

    function VehicleLab.composition_snapshot(ped, vehicle)
        local state = VehicleLab.state
        local weapon_hash, weapon_ptr = VehicleLab.resolve_weapon_runtime_target(ped)
        weapon_ptr = tonumber(weapon_ptr) or 0
        local weapon_base = state.weapon_runtime_snapshots[weapon_ptr]
        local ammo_ptr = VehicleLab.current_ammo_ptr(ped, vehicle)
        ammo_ptr = tonumber(ammo_ptr) or 0
        local ammo_base = state.runtime_ammo_snapshots[ammo_ptr]
        local effective_delay, effective_speed
        if weapon_ptr ~= 0 then
            pcall(function()
                effective_delay = Memory.ReadFloat(weapon_ptr +
                    VehicleLab.weapon_offset.time_between_shots)
            end)
        end
        if ammo_ptr ~= 0 then
            pcall(function()
                effective_speed = Memory.ReadFloat(ammo_ptr +
                    VehicleLab.ammo_offset.launch_speed)
            end)
        end
        return {
            weapon_hash = vehicle_lab_u32(weapon_hash),
            weapon_ptr = weapon_ptr,
            ammo_ptr = ammo_ptr,
            stock_firing_delay = weapon_base and weapon_base.time_between_shots or nil,
            effective_firing_delay = effective_delay,
            stock_projectile_speed = ammo_base and ammo_base.launch_speed or effective_speed,
            effective_projectile_speed = effective_speed,
            rapid_fields =
            "reload_time_mp,reload_time_sp,vehicle_reload_time,time_between_shots,cached_fire_delay,alternate_wait_time",
            buff_fields =
            "ammo_info,Deluxo launch angles,steering flags 8/9/97/103/149/150/152/153",
            buff = {complete=state.global_homing_complete==true,
                selected_hash=state.global_homing_selected_hash or 0,
                selected_ptr=state.global_homing_selected_ptr or 0,
                selected_applied=state.global_homing_selected_applied==true,
                selected_status=state.global_homing_selected_status or "UNAVAILABLE"},
            speed_fields = "launch_speed",
            range_fields = "lifetime,from_vehicle_lifetime,weapon_range",
            controller = VehicleMods and type(VehicleMods.controller_snapshot) == "function"
                and VehicleMods.controller_snapshot() or {},
        }
    end

    function VehicleLab.log_composition(ped, vehicle, force)
        local diagnostics = module_context and module_context.CScript and module_context.CScript.Diagnostics
        if force ~= true and not (diagnostics and diagnostics.DebugMode == true) then return false end
        local snap = VehicleLab.composition_snapshot(ped, vehicle)
        local signature = table.concat({ tostring(snap.weapon_ptr), tostring(snap.ammo_ptr),
            tostring(VehicleLab.rapid_requested()), tostring(is_on("vehicle_buff_all_rockets")),
            tostring(rapid_delay_ms()), ("%.3f"):format(slider_float("vehicle_rocket_speed", 1.0)) }, ":")
        if force ~= true and signature == VehicleLab.state.composition_log_signature then return false end
        VehicleLab.state.composition_log_signature = signature
        log_info(("Vehicle field composition: weapon=0x%08X weaponPtr=0x%X ammoPtr=0x%X "
                .. "firingDelay={stock=%s effective=%s owner=RapidFire} projectileSpeed={stock=%s effective=%s owner=RocketSpeed} "
                .. "BuffAllFields={%s} RapidFields={%s} rangeFields={%s}.")
            :format(snap.weapon_hash, snap.weapon_ptr, snap.ammo_ptr,
                tostring(snap.stock_firing_delay), tostring(snap.effective_firing_delay),
                tostring(snap.stock_projectile_speed), tostring(snap.effective_projectile_speed),
                snap.buff_fields, snap.rapid_fields, snap.range_fields))
        return true
    end

    function VehicleLab.restore_weapon_runtime_ptr(ptr)
        local state = VehicleLab.state
        local snap = state.weapon_runtime_snapshots[ptr]
        if not snap then return true end
        local ok, err = pcall(function()
            for _, field in ipairs(WEAPON_FLOAT_FIELDS) do
                owned_restore(MEMORY_OWNERS.weapon, ptr, field)
            end
            for word = 0, 5 do owned_restore(MEMORY_OWNERS.weapon, ptr, "flags_" .. word) end
        end)
        if not ok then
            log_error_once("vehicle_weapon_restore_" .. tostring(ptr), err)
            return false
        end
        state.weapon_runtime_snapshots[ptr] = nil
        if state.weapon_runtime_active_ptr == ptr then
            state.weapon_runtime_active_ptr = 0
            state.weapon_runtime_active_hash = 0
            state.weapon_runtime_active_vehicle = 0
            state.weapon_runtime_signature = nil
        end
        return true
    end

    function VehicleLab.restore_all_weapon_runtime()
        local state = VehicleLab.state
        local ptrs = {}
        for ptr in pairs(state.weapon_runtime_snapshots) do ptrs[#ptrs + 1] = ptr end
        local restored = true
        for _, ptr in ipairs(ptrs) do
            if not VehicleLab.restore_weapon_runtime_ptr(ptr) then restored = false end
        end
        if next(state.weapon_runtime_snapshots) == nil then
            state.weapon_runtime_active_ptr = 0
            state.weapon_runtime_active_hash = 0
            state.weapon_runtime_active_vehicle = 0
            state.weapon_runtime_signature = nil
        end
        return restored
    end

    local function restore_weapon_fields(ptr, fields)
        local restored = true
        for _, field in ipairs(fields) do
            local ok, result = pcall(owned_restore, MEMORY_OWNERS.weapon, ptr, field)
            if not ok then
                restored = false
                log_error_once("vehicle_weapon_field_restore_" .. tostring(ptr) .. "_" .. field, result)
            end
        end
        return restored
    end

    function VehicleLab.quiesce_rapid_fire_builtin()
        if not (VehicleMods and type(VehicleMods.restore_builtin) == "function") then return true end
        local restored = VehicleMods.restore_builtin("rapid_fire")
        VehicleMods.state.builtin_desired.rapid_fire = false
        return restored
    end

    function VehicleLab.resolve_weapon_runtime_target(ped)
        local weapon_hash = VehicleLab.get_current_vehicle_weapon(ped)
        if weapon_hash and vehicle_lab_u32(weapon_hash) ~= 0 then
            return weapon_hash, VehicleLab.find_item_ptr(weapon_hash)
        end

        -- Zero/unavailable selection is not evidence that this aircraft's cannon
        -- is active. Retry the native on the next pass instead of substituting a
        -- model-derived record during weapon-slot transitions.
        return 0, 0
    end

    validate_weapon_runtime_target = function(ptr, weapon_hash)
        local state = VehicleLab.state
        local expected = vehicle_lab_u32(weapon_hash)
        if expected == 0 or ptr == 0 or state.invalid_weapon_info_hashes[expected] then return false end
        -- Recheck the record even while it has a captured modification baseline.
        -- A snapshot is restoration data, not a CWeaponInfo identity proof.
        local valid_ok, name_hash, fire_type, ammo_ptr, shot_delay, weapon_range = pcall(function()
            return Memory.ReadUInt(ptr + VehicleLab.weapon_offset.name),
                Memory.ReadInt(ptr + VehicleLab.weapon_offset.fire_type),
                Memory.ReadLong(ptr + VehicleLab.weapon_offset.ammo_info),
                Memory.ReadFloat(ptr + VehicleLab.weapon_offset.time_between_shots),
                Memory.ReadFloat(ptr + VehicleLab.weapon_offset.weapon_range)
        end)
        -- Bullet/MG mounted weapons can use fire type 0/1 while rockets commonly
        -- sit in the 2-5 range. The ammo-info field may be null for some weapon
        -- classes, but a non-null value must still be a canonical user-space pointer.
        local ammo_valid = type(ammo_ptr) == "number"
            and (ammo_ptr == 0 or vehicle_lab_plausible_pointer(ammo_ptr))
        if valid_ok and vehicle_lab_u32(name_hash) == expected
            and type(fire_type) == "number" and fire_type >= 0 and fire_type <= 16
            and ammo_valid
            and vehicle_lab_number_in_range(shot_delay, 0.0, 120.0)
            and vehicle_lab_number_in_range(weapon_range, 0.0, 100000.0) then
            return true
        end

        -- Critical safety barrier: a CItemInfo hash match does not prove the object is
        -- CWeaponInfo. Quarantine the hash before any later ammo/rocket pass gets a
        -- chance to treat a garbage ammo_info value as an address.
        state.invalid_weapon_info_hashes[expected] = true
        state.item_ptr_cache[expected] = false
        log_error_once("vehicle_weapon_runtime_type_" .. tostring(expected),
            ("CItemInfo rejected as CWeaponInfo; quarantined hash=0x%08X ptr=0x%X "
                .. "name=0x%08X fireType=%s ammo=%s delay=%s range=%s")
            :format(expected, tonumber(ptr) or 0, vehicle_lab_u32(name_hash), tostring(fire_type),
                tostring(ammo_ptr), tostring(shot_delay), tostring(weapon_range)))
        return false
    end

    function VehicleLab.cannon_timing_context(ped,vehicle,hash,ptr)
        local ok,key=pcall(function()
            if not started or not bound or runtime_writes_suspended or dependencies~=deps
                or not metadata_gameplay_ready() then return nil end
            ped,vehicle=ped or local_ped(),vehicle or local_vehicle()
            if ped~=local_ped()or vehicle~=local_vehicle()or not entity_exists(ped)or not entity_exists(vehicle)then return nil end
            hash=hash or VehicleLab.get_current_vehicle_weapon(ped)
            if vehicle_lab_u32(hash)~=vehicle_lab_u32(VehicleLab.weapon.lazer)then return nil end
            local model=invoke_int(H.GET_ENTITY_MODEL,vehicle)
            if not vehicle_lab_is_jet(model)or invoke_int(H.GET_PED_IN_VEHICLE_SEAT,vehicle,-1,false)~=ped then return nil end
            local dead_ped=Natives.InvokeBool(H.IS_ENTITY_DEAD,ped,false)
            local dead_vehicle=Natives.InvokeBool(H.IS_ENTITY_DEAD,vehicle,false)
            if(dead_ped~=false and dead_ped~=0)or(dead_vehicle~=false and dead_vehicle~=0)then return nil end
            local requested=is_on("vehicle_lab_cannons")and not cannon_profile_choice().neutral
                or VehicleLab.rapid_requested(hash)
            if not requested then return nil end
            ptr=ptr or VehicleLab.find_item_ptr(hash)
            if not validate_weapon_runtime_target(ptr,hash)then return nil end
            local function address(handle)
                local object=GTA.HandleToPointer(handle)
                local value=object and object:GetAddress()
                if not vehicle_lab_plausible_pointer(value)or value%1~=0 then return nil end
                return value
            end
            local pa,va=address(ped),address(vehicle)
            local ammo=Memory.ReadLong(ptr+VehicleLab.weapon_offset.ammo_info)
            if not pa or not va or not vehicle_lab_plausible_pointer(ammo)or ammo%1~=0 then return nil end
            local generation=VehicleMods and VehicleMods.state.controller.session_generation or 0
            local runtime_generation=module_context and module_context.Runtime and module_context.Runtime.generation or 0
            if ped~=local_ped()or vehicle~=local_vehicle()
                or invoke_int(H.GET_PED_IN_VEHICLE_SEAT,vehicle,-1,false)~=ped
                or vehicle_lab_u32(VehicleLab.get_current_vehicle_weapon(ped))~=vehicle_lab_u32(hash)
                or address(ped)~=pa or address(vehicle)~=va
                or invoke_int(H.GET_ENTITY_MODEL,vehicle)~=model
                or Memory.ReadLong(ptr+VehicleLab.weapon_offset.ammo_info)~=ammo
                or(VehicleMods and VehicleMods.state.controller.session_generation or 0)~=generation
                or(module_context and module_context.Runtime and module_context.Runtime.generation or 0)~=runtime_generation
                or not started or not bound or runtime_writes_suspended or dependencies~=deps then return nil end
            return table.concat({runtime_generation,generation,ped,pa,vehicle,va,-1,model,vehicle_lab_u32(hash),ptr,ammo},":")
        end)
        return ok and key or nil
    end

    function VehicleLab.ensure_cannon_timing(ped,vehicle,hash,ptr,restore,rapid)
        local key=VehicleLab.cannon_timing_context(ped,vehicle,hash,ptr)
        if not key then VehicleLab.restore_cannon_timing("local cannon identity unavailable");return false end
        local signature=VehicleLab.cannon_auth_key(key,hash)
        local latch=VehicleLab.state.cannon_auth_failure
        if latch and latch.key==signature then return false,"AUTH_FAILED",latch.reason end
        if latch then VehicleLab.state.cannon_auth_failure=nil end
        VehicleLab.state.cannon_auth_source_key=key
        local service=VehicleLab.state.cannon_timing_service
        if not service then
            local raw=module_context and module_context.Raw or {}
            service=CannonTimingBinding.New({Memory=Memory,Time=raw.Time,FileMgr=raw.FileMgr,
                Context=function()return VehicleLab.cannon_timing_context()end,
                Cancelled=function()return module_context==nil or(module_context.Runtime and module_context.Runtime.stopping==true)or false end,
            },CannonTimingOwner)
            VehicleLab.state.cannon_timing_service=service
        end
        local active,detail=service.Ensure(key,restore,rapid)
        local status=service.Snapshot()
        return active,status.binding_status or status.phase,detail or status.binding_error or status.last_error
    end

    function VehicleLab.cannon_auth_key(source,hash)
        local profile=cannon_profile_choice()
        local rapid=VehicleLab.rapid_requested(hash)
        local delay=rapid and rapid_delay_seconds()or profile.delay or NATIVE_CANNON_PROFILE.restored_time_between_shots
        return table.concat({source,is_on("vehicle_lab_cannons")and"1"or"0",
            is_on("vehicle_rapid_fire")and"1"or"0",is_on("vehicle_rapid_fire_guns")and"1"or"0",
            tostring(profile.name),tostring(profile.neutral==true),tostring(profile.damage),tostring(profile.alternate),("%.6g"):format(delay)},":")
    end

    function VehicleLab.latch_cannon_auth_failure(hash,reason)
        local source=VehicleLab.state.cannon_auth_source_key
        if source and vehicle_lab_u32(hash)==vehicle_lab_u32(VehicleLab.weapon.lazer)then
            -- Capture after the existing Pre-Nerf auto-OFF callback returns.
            VehicleLab.state.cannon_auth_failure={key=VehicleLab.cannon_auth_key(source,hash),reason=reason}
        end
    end

    function VehicleLab.cannon_timing_intent_changed(key,value)
        local state=VehicleLab.state
        state.cannon_timing_intents=state.cannon_timing_intents or{}
        if state.cannon_timing_intents[key]~=value then
            state.cannon_auth_failure=nil
            if key=='vehicle_lab_cannons'then state.cannon_balance_epoch=(state.cannon_balance_epoch or 0)+1 end
        end
        state.cannon_timing_intents[key]=value
    end

    function VehicleLab.cannon_balance_key(ped,vehicle,hash,ptr)
        if not is_on('vehicle_lab_cannons')then return nil end
        local key=VehicleLab.cannon_timing_context(ped,vehicle,hash,ptr)
        return key and(key..':'..tostring(VehicleLab.state.cannon_balance_epoch or 0))or nil
    end
    function VehicleLab.ensure_cannon_balance(ped,vehicle,hash,ptr)
        local state=VehicleLab.state
        local key=VehicleLab.cannon_balance_key(ped,vehicle,hash,ptr)
        if not key then VehicleLab.restore_cannon_balance('Local cannon context ended');return false,'Local pilot/cannon identity is unavailable'end
        if not state.cannon_balance_owner then
            state.cannon_balance_owner=CannonBalanceOwner.New({GetBaseAddress=Memory.GetBaseAddress,
                ReadUByte=Memory.ReadUByte,ReadLong=Memory.ReadLong,WriteUByte=Memory.WriteUByte,
                CurrentKey=function()return VehicleLab.cannon_balance_key()end,
                Cancelled=function()return not started or not bound or runtime_writes_suspended
                    or module_context==nil or(module_context.Runtime and module_context.Runtime.stopping==true)or false end})
        end
        return state.cannon_balance_owner.Ensure(key)
    end
    function VehicleLab.restore_cannon_balance(reason)
        local owner=VehicleLab.state.cannon_balance_owner
        return not owner or owner.Restore(reason)
    end
    function VehicleLab.cannon_balance_snapshot()
        local owner=VehicleLab.state.cannon_balance_owner
        return owner and owner.Snapshot()or{phase='OFF',active=false,cleanup_pending=false,shared_process_scope=true,live_verified=false}
    end
    function VehicleLab.restore_cannon_timing(reason)
        local service=VehicleLab.state.cannon_timing_service
        return not service or service.Restore(reason)
    end

    function VehicleLab.unload_cannon_timing()
        local owner=VehicleLab.state.cannon_balance_owner
        local balance_ok=not owner or owner.Unload()
        local service=VehicleLab.state.cannon_timing_service
        local timing_ok=not service or service.Unload()
        return balance_ok==true and timing_ok==true
    end

    function VehicleLab.cannon_timing_cleanup_tick()
        local owner=VehicleLab.state.cannon_balance_owner
        local balance_ok=not owner or owner.CleanupTick()
        local service=VehicleLab.state.cannon_timing_service
        local timing_ok=not service or service.CleanupTick()
        return balance_ok==true and timing_ok==true
    end

    function VehicleLab.cannon_timing_needs_cleanup()
        local owner=VehicleLab.state.cannon_balance_owner
        local service=VehicleLab.state.cannon_timing_service
        return(owner and owner.NeedsCleanup()==true)or(service and service.NeedsCleanup()==true)or false
    end

    function VehicleLab.cannon_timing_snapshot()
        local service=VehicleLab.state.cannon_timing_service
        local out=service and service.Snapshot()or{phase="UNPREPARED",active=false,cleanup_pending=false,has_obligations=false}
        local balance=VehicleLab.cannon_balance_snapshot();out.balance=balance
        out.active=out.active==true or balance.active==true
        out.cleanup_pending=out.cleanup_pending==true or balance.cleanup_pending==true
        out.has_obligations=out.has_obligations==true or balance.owned==true
        if balance.active or balance.cleanup_pending then out.data_owner=true;if not service then out.phase=balance.phase end end
        return out
    end

    function VehicleLab.cannon_timing_tick_requested()
        local status=VehicleLab.cannon_timing_snapshot()
        return VehicleLab.cannon_timing_needs_cleanup() or status.active==true or status.cleanup_pending==true or status.phase=="HELLO_PENDING"or status.phase=="APPLY_PENDING"
    end

    function VehicleLab.prepare_rapid_fire_runtime(ped, vehicle, weapon_hash, ptr)
        local state = VehicleLab.state
        if not VehicleLab.rapid_requested() or not entity_exists(ped) or not entity_exists(vehicle) then
            return false
        end
        if not weapon_hash then weapon_hash, ptr = VehicleLab.resolve_weapon_runtime_target(ped) end
        ptr = tonumber(ptr) or 0
        local hash = weapon_hash and vehicle_lab_u32(weapon_hash) or 0

        if hash ~= 0 and VehicleLab.is_native_aircraft_cannon(hash) then
            VehicleLab.quiesce_rapid_fire_builtin()
            VehicleLab.restore_all_weapon_runtime()
            return VehicleLab.apply_native_cannon_profile(ped, vehicle, hash, ptr)
        end

        if ptr == 0 or hash == 0 then
            VehicleLab.quiesce_rapid_fire_builtin()
            VehicleLab.restore_all_weapon_runtime()
            return false
        end

        local target_changed = state.weapon_runtime_active_ptr ~= 0
            and (state.weapon_runtime_active_ptr ~= ptr
                or state.weapon_runtime_active_hash ~= hash
                or state.weapon_runtime_active_vehicle ~= vehicle)
        if target_changed then
            -- Cherax's optional Rapid Fire helper is restored first so the next
            -- CWeaponInfo snapshot cannot inherit a helper-modified cannon profile.
            VehicleLab.quiesce_rapid_fire_builtin()
            if not VehicleLab.restore_all_weapon_runtime() then return false end
        elseif state.weapon_runtime_active_ptr == 0
            and next(state.weapon_runtime_snapshots) ~= nil
            and state.weapon_runtime_snapshots[ptr] == nil then
            VehicleLab.quiesce_rapid_fire_builtin()
            if not VehicleLab.restore_all_weapon_runtime() then return false end
        end

        if not validate_weapon_runtime_target(ptr, weapon_hash) then return false end
        return VehicleLab.capture_weapon_runtime(ptr, weapon_hash) ~= nil
    end

    function VehicleLab.apply_weapon_runtime(ped, vehicle, resolved_hash, resolved_ptr)
        local state = VehicleLab.state
        -- These are the only CWeaponInfo owners. Target registration and Buff
        -- All must not resolve mounted metadata while both owners are disabled.
        if not is_on("vehicle_rapid_fire") and not is_on("vehicle_rapid_fire_guns")
            and not is_on("vehicle_infinite_lock_range") then
            if state.weapon_runtime_active_ptr ~= 0 or next(state.weapon_runtime_snapshots) ~= nil then
                VehicleLab.restore_all_weapon_runtime()
            end
            state.weapon_runtime_signature = nil
            return false
        end
        local rapid_delay = rapid_delay_seconds()
        local infinite_lock = is_on("vehicle_infinite_lock_range")
        local weapon_hash, ptr = resolved_hash, tonumber(resolved_ptr) or 0
        if not weapon_hash then weapon_hash, ptr = VehicleLab.resolve_weapon_runtime_target(ped) end
        local weapon_u32 = weapon_hash and vehicle_lab_u32(weapon_hash) or 0
        local rapid_requested = VehicleLab.rapid_requested(weapon_u32)

        local direct_rapid = rapid_requested and VehicleMods
            and VehicleMods.should_use_direct_rapid(weapon_u32)
        -- Aircraft rapid fire changes the mounted weapon's cadence fields while
        -- leaving the native pilot input/aim task in control.
        local rapid = rapid_requested
        -- Lock Players / Lock NPCs are target-registration features and Buff All is
        -- an AmmoInfo feature. None of them belongs to CWeaponInfo ownership.
        local wanted = rapid or infinite_lock

        if not entity_exists(ped) or not entity_exists(vehicle) or not wanted then
            if state.weapon_runtime_active_ptr ~= 0 or next(state.weapon_runtime_snapshots) ~= nil then
                VehicleLab.restore_all_weapon_runtime()
            end
            state.weapon_runtime_signature = nil
            return false
        end

        if weapon_u32 ~= 0 and VehicleLab.is_native_aircraft_cannon(weapon_u32) then
            VehicleLab.quiesce_rapid_fire_builtin()
            if VehicleMods and type(VehicleMods.restore_builtin) == "function" then
                VehicleMods.restore_builtin("infinite_weapon_range")
                VehicleMods.state.builtin_desired.infinite_weapon_range = false
            end
            VehicleLab.restore_all_weapon_runtime()
            return VehicleLab.apply_native_cannon_profile(ped, vehicle, weapon_u32, ptr)
        end
        if weapon_u32 == 0 or ptr == 0 then
            if rapid then VehicleLab.quiesce_rapid_fire_builtin() end
            VehicleLab.restore_all_weapon_runtime()
            return false
        end

        local signature = table.concat({
            tostring(vehicle), tostring(ptr), tostring(weapon_u32), rapid and "1" or "0",
            infinite_lock and "1" or "0",
            ("%.3f"):format(rapid_delay),
        }, ":")

        -- CWeaponInfo is persistent data. Rewriting the same 15+ fields five times a
        -- second did nothing useful and was one of the avoidable FPS costs in 2.0.
        local same_target = state.weapon_runtime_active_ptr == ptr
            and state.weapon_runtime_active_hash == weapon_u32
            and state.weapon_runtime_active_vehicle == vehicle
        if not validate_weapon_runtime_target(ptr,weapon_hash) then return false end
        if same_target and state.weapon_runtime_signature == signature then
            if rapid then return VehicleLab.write_effective_cadence(ptr, state.weapon_runtime_snapshots[ptr], rapid_delay) end
            return VehicleLab.weapon_backend().Verify(ptr)
        end

        if not same_target and state.weapon_runtime_active_ptr ~= 0 then
            if rapid then VehicleLab.quiesce_rapid_fire_builtin() end
            if not VehicleLab.restore_all_weapon_runtime() then return false end
        end

        if not validate_weapon_runtime_target(ptr, weapon_hash) then return false end

        local snap = VehicleLab.capture_weapon_runtime(ptr, weapon_hash)
        if not snap then return false end
        state.weapon_runtime_active_ptr = ptr
        state.weapon_runtime_active_hash = weapon_u32
        state.weapon_runtime_active_vehicle = vehicle
        state.weapon_runtime_signature = signature

        local o = VehicleLab.weapon_offset
        if not rapid then restore_weapon_fields(ptr, WEAPON_CADENCE_FIELDS) end
        if not infinite_lock then restore_weapon_fields(ptr, { "lock_on_range" }) end
        if not infinite_lock then restore_weapon_fields(ptr, { "weapon_range" }) end
        if same_target then
            local flag_fields = {}
            for word = 0, 5 do flag_fields[#flag_fields + 1] = "flags_" .. word end
            restore_weapon_fields(ptr, flag_fields)
        end
        if rapid then VehicleLab.write_effective_cadence(ptr, snap, rapid_delay) end
        if rapid then
            local rapid_log_signature = table.concat({ tostring(vehicle), tostring(ptr),
                tostring(weapon_u32), ("%.3f"):format(rapid_delay) }, ":")
            if state.rapid_runtime_log_signature ~= rapid_log_signature then
                state.rapid_runtime_log_signature = rapid_log_signature
                local fire_type = -1
                pcall(function() fire_type = Memory.ReadInt(ptr + o.fire_type) end)
                log_info(("Vehicle rapid-fire runtime active: vehicle=%s weapon=0x%08X ptr=0x%X fireType=%s delayMs=%d.")
                    :format(tostring(vehicle), weapon_u32, ptr, tostring(fire_type),
                        math.floor(rapid_delay * 1000.0 + 0.5)))
            end
        end

        if infinite_lock then
            -- Current mounted homing profiles check both acquisition ranges.
            -- Projectile travel is governed separately by AmmoInfo lifetimes.
            local range_ok = pcall(function()
                owned_write(MEMORY_OWNERS.weapon, ptr, "lock_on_range",
                    ptr + o.lock_on_range, 99999.0, "float")
                owned_write(MEMORY_OWNERS.weapon, ptr, "weapon_range",
                    ptr + o.weapon_range, 99999.0, "float")
                assert(math.abs(Memory.ReadFloat(ptr + o.lock_on_range) - 99999.0) < 0.1
                    and math.abs(Memory.ReadFloat(ptr + o.weapon_range) - 99999.0) < 0.1)
            end)
            if not range_ok then
                restore_weapon_fields(ptr, { "lock_on_range", "weapon_range" })
                state.weapon_runtime_signature = nil
                return false
            end

        end
        -- Runtime observation found no CWeaponInfo changes for Lock Players/NPCs.
        -- Keep these controls on the target-registration path without rewriting flags.
        return true
    end

    if module_context and module_context.Performance and type(module_context.Performance.Wrap)=="function" then
        VehicleLab.apply_weapon_runtime=module_context.Performance.Wrap("vehicle.weapon_runtime",VehicleLab.apply_weapon_runtime,127)
    end

    function VehicleLab.restore_ammo_range(ptr)
        local snap = VehicleLab.state.ammo_range_snapshots[ptr]
        if not snap then return true end
        local first = pcall(owned_restore, MEMORY_OWNERS.projectile, ptr, "lifetime")
        local second = pcall(owned_restore, MEMORY_OWNERS.projectile, ptr, "from_vehicle_lifetime")
        local third = pcall(owned_restore, MEMORY_OWNERS.projectile, ptr, "player_vehicle_locked_lifetime")
        if not first or not second or not third then return false end
        VehicleLab.state.ammo_range_snapshots[ptr] = nil
        return true
    end

    function VehicleLab.restore_all_ammo_ranges()
        local ptrs = {}
        local restored = true
        for ptr in pairs(VehicleLab.state.ammo_range_snapshots) do ptrs[#ptrs + 1] = ptr end
        for _, ptr in ipairs(ptrs) do
            if not VehicleLab.restore_ammo_range(ptr) then restored = false end
        end
        return restored
    end

    function VehicleLab.restore_other_ammo_ranges(active_ptr)
        local ptrs = {}
        for ptr in pairs(VehicleLab.state.ammo_range_snapshots) do
            if ptr ~= active_ptr then ptrs[#ptrs + 1] = ptr end
        end
        local restored = true
        for _, ptr in ipairs(ptrs) do
            if not VehicleLab.restore_ammo_range(ptr) then restored = false end
        end
        return restored
    end

    function VehicleLab.write_ammo_profile(ptr, profile, write_launch_speed, guidance_owner, speed_owner)
        local offset = VehicleLab.ammo_offset
        guidance_owner=guidance_owner or MEMORY_OWNERS.ammo_guidance
        speed_owner=speed_owner or MEMORY_OWNERS.ammo_speed
        if write_launch_speed == true then
            owned_snapshot(speed_owner, ptr, "launch_speed",
                ptr + offset.launch_speed, "float")
            owned_write(speed_owner, ptr, "launch_speed",
                ptr + offset.launch_speed, profile.launch_speed, "float")
        end
        owned_write(guidance_owner, ptr, "pitch_change_rate",
            ptr + offset.pitch_change_rate, profile.pitch_change_rate, "float")
        owned_write(guidance_owner, ptr, "yaw_change_rate",
            ptr + offset.yaw_change_rate, profile.yaw_change_rate, "float")
        owned_write(guidance_owner, ptr, "roll_change_rate",
            ptr + offset.roll_change_rate, profile.roll_change_rate, "float")
        owned_write(guidance_owner, ptr, "use_homing_params",
            ptr + offset.use_homing_params, profile.use_homing_params == 1 and 1 or 0, "ubyte")

        if profile.use_homing_params == 1 then
            owned_write(guidance_owner, ptr, "time_before_starting_homing",
                ptr + offset.time_before_starting_homing, profile.time_before_starting_homing, "float")
            owned_write(guidance_owner, ptr, "time_before_angle_break",
                ptr + offset.time_before_angle_break, profile.time_before_angle_break, "float")
            owned_write(guidance_owner, ptr, "turn_rate_modifier",
                ptr + offset.turn_rate_modifier, profile.turn_rate_modifier, "float")
            owned_write(guidance_owner, ptr, "pitch_yaw_roll_clamp",
                ptr + offset.pitch_yaw_roll_clamp, profile.pitch_yaw_roll_clamp, "float")
            owned_write(guidance_owner, ptr, "break_lock_angle",
                ptr + offset.break_lock_angle, profile.break_lock_angle, "float")
            owned_write(guidance_owner, ptr, "break_lock_angle_close",
                ptr + offset.break_lock_angle_close, profile.break_lock_angle_close, "float")
            owned_write(guidance_owner, ptr, "break_lock_close_distance",
                ptr + offset.break_lock_close_distance, profile.break_lock_close_distance, "float")
        end
    end

    function VehicleLab.read_source_profile(ammo_hash, label)
        local ptr = VehicleLab.find_ammo_ptr(ammo_hash)
        if ptr == 0 then
            return nil, (label or "source ammo") .. " was not found in CItemInfo"
        end

        local ok, profile = pcall(VehicleLab.read_ammo_profile, ptr)
        if not ok then return nil, tostring(profile) end

        if not vehicle_lab_number_in_range(profile.launch_speed, 50.0, 10000.0)
            or not vehicle_lab_number_in_range(profile.time_before_homing, 0.0, 20.0)
            or not vehicle_lab_number_in_range(profile.pitch_change_rate, 0.0, 200.0)
            or not vehicle_lab_number_in_range(profile.yaw_change_rate, 0.0, 200.0)
            or not vehicle_lab_number_in_range(profile.roll_change_rate, 0.0, 200.0)
            or (profile.use_homing_params ~= 0 and profile.use_homing_params ~= 1) then
            return nil, (label or "source ammo") .. " failed homing-field validation"
        end
        for _,spec in ipairs(AMMO_PROFILE_FIELDS) do
            profile[spec[1]]=VehicleLab.weapon_backend().Baseline(ptr,spec[1],profile[spec[1]])
        end
        return profile
    end

    function VehicleLab.capture_runtime_ammo_profile(ptr, ammo_hash)
        local state=VehicleLab.state
        if state.runtime_ammo_snapshots[ptr] then return state.runtime_ammo_snapshots[ptr] end
        local profile={}
        -- A missing guidance field must not disable independently supported speed
        -- or lifetime. Ownership and validation occur per requested field.
        for _,spec in ipairs(AMMO_PROFILE_FIELDS) do
            local method=spec[2]=='ubyte' and Memory.ReadUByte or Memory.ReadFloat
            local ok,value=pcall(method,ptr+VehicleLab.ammo_offset[spec[1]])
            if ok then profile[spec[1]]=VehicleLab.weapon_backend().Baseline(ptr,spec[1],value) end
        end
        if not vehicle_lab_number_in_range(profile.launch_speed,0.01,20000) then return nil end
        state.runtime_ammo_snapshots[ptr]=profile
        return profile
    end

    function VehicleLab.restore_runtime_ammo_profiles()
        local state = VehicleLab.state
        local ptrs = {}
        local restored=true
        for ptr in pairs(state.runtime_ammo_snapshots) do ptrs[#ptrs + 1] = ptr end
        for _, ptr in ipairs(ptrs) do
            local ok = VehicleLab.restore_runtime_ammo_profile_ptr(ptr)
            if not ok then restored=false end
            if not ok and metadata_gameplay_ready() then
                log_error_once("vehicle_runtime_ammo_restore_" .. tostring(ptr), "field restore failed; cleanup retained")
            end

        end
        -- Any all-missile preset pointers restored above must be rediscovered if
        -- Buff All Rockets is still enabled. This prevents a weapon-slot change
        -- from leaving the old catalog entries silently back at stock.
        if restored then state.global_homing_ptrs = {} end
        state.global_homing_active = false
        state.global_homing_signature = nil
        state.global_homing_last_count = 0
        return restored
    end

    function VehicleLab.restore_runtime_ammo_profile_ptr(ptr, restore_guidance, restore_speed)
        local state = VehicleLab.state
        ptr = tonumber(ptr) or 0
        if ptr == 0 or state.runtime_ammo_snapshots[ptr] == nil then return true end
        restore_guidance = restore_guidance ~= false
        restore_speed = restore_speed ~= false
        local success = true
        if restore_guidance then
            for _, spec in ipairs(AMMO_GUIDANCE_FIELDS) do
                local ok, result = pcall(owned_restore, MEMORY_OWNERS.ammo_guidance, ptr, spec[1])
                if not ok then
                    success = false
                    log_error_once("vehicle_runtime_ammo_restore_field_" .. tostring(ptr) .. "_" .. spec[1], result)
                end
            end
        end
        if restore_speed then
            for _, spec in ipairs(AMMO_SPEED_FIELDS) do
                local ok, result = pcall(owned_restore, MEMORY_OWNERS.ammo_speed, ptr, spec[1])
                if not ok then
                    success = false
                    log_error_once("vehicle_runtime_ammo_restore_field_" .. tostring(ptr) .. "_" .. spec[1], result)
                end
            end
        end
        if success and restore_guidance and restore_speed then
            state.runtime_ammo_snapshots[ptr] = nil
            if state.ammo_runtime_ptr == ptr then
                state.ammo_runtime_ptr = 0
                state.ammo_runtime_signature = nil
            end
        end
        if success and restore_guidance then state.global_homing_ptrs[ptr] = nil end
        return success
    end

    local function copy_homing_fields(profile, source)
        profile.time_before_homing = source.time_before_homing
        profile.pitch_change_rate = source.pitch_change_rate
        profile.yaw_change_rate = source.yaw_change_rate
        profile.roll_change_rate = source.roll_change_rate
        profile.use_homing_params = source.use_homing_params
        profile.time_before_starting_homing = source.time_before_starting_homing
        profile.time_before_angle_break = source.time_before_angle_break
        profile.turn_rate_modifier = source.turn_rate_modifier
        profile.pitch_yaw_roll_clamp = source.pitch_yaw_roll_clamp
        profile.break_lock_angle = source.break_lock_angle
        profile.break_lock_angle_close = source.break_lock_angle_close
        profile.break_lock_close_distance = source.break_lock_close_distance
    end

    function VehicleLab.restore_global_homing_redirects()
        local state = VehicleLab.state
        local ptrs = {}
        for ptr in pairs(state.global_homing_redirect_ptrs) do ptrs[#ptrs + 1] = ptr end
        local restored = true
        for _, ptr in ipairs(ptrs) do
            local settled=true
            for _,field in ipairs({"buff_ammo_info_redirect","flags_0","flags_3","flags_4"})do
                local ok,result=pcall(owned_restore,MEMORY_OWNERS.weapon_buff,ptr,field)
                if not ok then
                    restored=false;settled=false
                    log_error_once("vehicle_buff_redirect_restore_"..tostring(ptr).."_"..field,result)
                end
            end
            if settled then state.global_homing_redirect_ptrs[ptr]=nil end
        end
        if restored then state.global_homing_redirect_ptrs = {} end
        return restored
    end



    function VehicleLab.restore_global_homing_buff()
        local state = VehicleLab.state
        state.global_homing_sweep=nil
        state.global_homing_eval=nil
        local ptrs = {}
        for ptr in pairs(state.global_homing_ptrs) do ptrs[#ptrs + 1] = ptr end
        local restored = true
        for _, ptr in ipairs(ptrs) do
            -- Buff All releases only guidance. Rocket Speed has an independent
            -- owner and remains effective when the homing preset is disabled.
            if not VehicleLab.restore_runtime_ammo_profile_ptr(ptr, true, false) then restored = false end
        end
        if not VehicleLab.restore_global_homing_redirects() then restored = false end
        -- Restore the separately owned, validated weapon launch tracking fields.
        if not VehicleLab.restore_global_homing_weapon_profiles() then restored = false end
        -- Per-record restorers remove only settled leases. Keep rejected or
        -- unreadable records reachable so an OFF tick can retry their cleanup.
        if restored then
            state.global_homing_ptrs = {}
            state.global_homing_weapon_ptrs = {}
            state.global_homing_redirect_ptrs = {}
            state.global_homing_canonical_ptr = 0
        end
        state.global_homing_active = false
        state.global_homing_signature = nil
        state.global_homing_last_count = 0
        state.global_homing_last_weapon_count = 0
        state.global_homing_complete=false
        state.global_homing_selected_hash=0
        state.global_homing_selected_ptr=0
        state.global_homing_selected_applied=false
        state.global_homing_selected_status="DISABLED"
        -- Instant Lock is owned by the unified VehicleMods controller. Releasing
        -- Buff All must never independently restore that shared Cherax toggle.
        return restored
    end

    function VehicleLab.apply_deluxo_rocket(ptr,hash,donor,tracking)
        if not validate_weapon_runtime_target(ptr,hash) or not vehicle_lab_plausible_pointer(donor) then return false end
        local flags=tracking and tracking.steering_flags
        local words={{0,{8,9}},{3,{97,103}},{4,{149,150,152,153}}}
        if type(flags)~="table" then return false end
        for _,row in ipairs(words)do
            for _,bit in ipairs(row[2])do if type(flags[bit])~="boolean"then return false end end
        end
        local state,o=VehicleLab.state,VehicleLab.weapon_offset
        local original=Memory.ReadLong(ptr+o.ammo_info)
        if not vehicle_lab_plausible_pointer(original) then return false end
        -- Capture attempted ownership before dispatch so partial writes drain.
        state.global_homing_redirect_ptrs[ptr]=hash
        local ok=pcall(function()
            owned_write(MEMORY_OWNERS.weapon_buff,ptr,"buff_ammo_info_redirect",ptr+o.ammo_info,donor,"long")
            -- Match all validated guidance bits, including false donor bits.
            -- The shared backend owns only these masks, never the whole word.
            for _,row in ipairs(words)do
                local address=ptr+o.flags+row[1]*4
                local value=Memory.ReadUInt(address)
                for _,bit in ipairs(row[2])do
                    local mask=1<<(bit%32)
                    value=flags[bit] and (value|mask) or (value & (~mask))
                end
                owned_write(MEMORY_OWNERS.weapon_buff,ptr,"flags_"..row[1],address,value,"uint")
            end
        end)
        if not ok or Memory.ReadLong(ptr+o.ammo_info)~=donor then return false end
        return VehicleLab.apply_global_homing_weapon_profile(ptr,hash,tracking)
            and VehicleLab.weapon_backend().Verify(ptr)
    end

    function VehicleLab.apply_global_homing_buff(ped,vehicle)
        local state=VehicleLab.state
        -- Weapon metadata and owner-verified guidance writes persist between
        -- FastTick calls. Don't re-apply them four times per second when
        -- the selected weapon, ped, vehicle and registry are unchanged.
        -- We still react immediately to a weapon switch and revisit
        -- successful state within 850 ms, before the full 1-second sweep.
        local enabled=is_on("vehicle_buff_all_rockets")
        local ready=entity_exists(ped)
        local now=runtime_now_ms()
        local selected_hint,vehicle_hint
        if enabled and ready then
            vehicle_hint=entity_exists(vehicle) and vehicle or 0
            selected_hint=vehicle_lab_u32(vehicle_hint~=0
                and VehicleLab.get_current_vehicle_weapon(ped)
                or invoke_int(H.GET_SELECTED_PED_WEAPON,ped))
            local cached=state.global_homing_eval
            if cached and now>=cached.at
                and now-cached.at<(cached.result and 850 or 200)
                and cached.ped==ped and cached.vehicle==vehicle_hint
                and cached.selected==selected_hint
                and cached.generation==state.item_registry_generation
                and VehicleMods.state.buff_release_pending~=true then
                return cached.result
            end
        else
            state.global_homing_eval=nil
        end
        state.global_homing_complete=false
        state.global_homing_active=false
        state.global_homing_last_count=0
        state.global_homing_last_weapon_count=0
        state.global_homing_selected_hash=0
        state.global_homing_selected_ptr=0
        state.global_homing_selected_applied=false
        state.global_homing_selected_status="UNAVAILABLE"
        if not is_on("vehicle_buff_all_rockets") or not entity_exists(ped) then
            state.global_homing_sweep=nil
            if next(state.global_homing_redirect_ptrs)~=nil or next(state.global_homing_weapon_ptrs)~=nil
                or next(state.global_homing_ptrs)~=nil then
                return VehicleLab.restore_global_homing_buff()
            end
            return false
        end
        local donor=VehicleLab.find_ammo_ptr(VehicleLab.ammo.deluxo_missile)
        local donor_profile=donor~=0 and VehicleLab.read_source_profile(VehicleLab.ammo.deluxo_missile,"Deluxo rocket")
        local tracking=VehicleLab.read_deluxo_weapon_tracking_profile()
        if donor==0 or not donor_profile or not tracking then return false end
        state.global_homing_canonical_ptr=donor
        local selected=selected_hint
        local catalog={};for _,hash in ipairs(VehicleMods.projectile_weapon_catalog)do catalog[vehicle_lab_u32(hash)]=true end
        selected=vehicle_lab_u32(selected)
        local selected_required=catalog[selected]==true
        -- Background metadata persists. Revalidate the selected weapon on every
        -- tick, but refresh the complete catalog only once per second. All
        -- writes still use the existing fresh identity/ownership guards.
        local now=runtime_now_ms()
        local sweep=state.global_homing_sweep
        if not sweep or now<sweep.at or now-sweep.at>=1000
            or sweep.generation~=state.item_registry_generation or sweep.donor~=donor then
            sweep={at=now,generation=state.item_registry_generation,donor=donor,results={}}
            state.global_homing_sweep=sweep
        else catalog={} end
        local hashes=catalog
        local refresh_catalog=next(catalog)~=nil
        state.global_homing_selected_hash=selected
        state.global_homing_selected_status=selected_required and "UNAVAILABLE" or "NOT_IN_SUPPORTED_CATALOG"
        -- CAmmoRocketInfo also backs certain non-missile cannons. Selecting a
        -- mounted cannon must not silently redirect its ammo to Deluxo rockets.
        -- Only a positively catalogued homing/rocket weapon is eligible.
        if selected_required then hashes[selected]=true end
        if refresh_catalog and type(VehicleLab.prefetch_item_ptrs)=="function" then
            if not VehicleLab.prefetch_item_ptrs(hashes) then
                state.global_homing_sweep=nil
                return false
            end
        end
        if sweep.generation~=state.item_registry_generation then
            state.global_homing_sweep=nil
            return false
        end
        local lookup_generation=state.item_registry_generation
        for hash in pairs(hashes)do
            sweep.results[hash]=nil
            local ptr=VehicleLab.find_item_ptr(hash)
            if lookup_generation~=state.item_registry_generation then
                state.global_homing_sweep=nil
                return false
            end
            if hash==selected then state.global_homing_selected_ptr=ptr end
            if ptr~=0 and validate_weapon_runtime_target(ptr,hash) then
                local ammo=Memory.ReadLong(ptr+VehicleLab.weapon_offset.ammo_info)
                local ammo_hash=vehicle_lab_plausible_pointer(ammo) and Memory.ReadUInt(ammo+0x10) or 0
                if backend_types[vehicle_lab_u32(ammo_hash)]=="CAmmoRocketInfo" then
                    local applied=VehicleLab.apply_deluxo_rocket(ptr,hash,donor,tracking)
                    sweep.results[hash]=applied==true
                    if hash==selected then
                        selected_required=true
                        state.global_homing_selected_applied=applied==true
                        state.global_homing_selected_status=applied and "APPLIED" or "UNVERIFIED"
                    end
                end
            end
        end
        local count,failed=0,false
        for _,applied in pairs(sweep.results)do
            if applied then count=count+1 else failed=true end
        end
        state.global_homing_active=count>0
        state.global_homing_last_count=count;state.global_homing_last_weapon_count=count
        state.global_homing_complete=count>0 and not failed
            and (not selected_required or state.global_homing_selected_applied)
        state.global_homing_eval={at=now,ped=ped,vehicle=vehicle_hint,
            selected=selected,generation=state.item_registry_generation,
            result=state.global_homing_complete}
        return state.global_homing_complete
    end

    if module_context and module_context.Performance and type(module_context.Performance.Wrap)=="function" then
        VehicleLab.apply_global_homing_buff=module_context.Performance.Wrap("vehicle.buff_catalog",VehicleLab.apply_global_homing_buff,127)
    end

    function VehicleLab.current_ammo_ptr(ped, vehicle)
        local weapon_hash =
            VehicleLab.get_current_vehicle_weapon(ped)

        local weapon_u32 =
            weapon_hash
            and vehicle_lab_u32(weapon_hash)
            or 0

        local function resolve_weapon_ammo(hash)
            hash = vehicle_lab_u32(hash)

            if hash == 0 then
                return 0, 0
            end

            if hash ~= vehicle_lab_u32(VehicleLab.weapon.homing_launcher) and VehicleMods
                and not VehicleMods.is_projectile_weapon(hash) then
                return 0, hash
            end

            local weapon_ptr =
                VehicleLab.find_item_ptr(hash)

            if weapon_ptr == 0
                or not validate_weapon_runtime_target(
                    weapon_ptr,
                    hash
                ) then
                return 0, hash
            end

            local ok, ammo_ptr =
                pcall(
                    Memory.ReadLong,
                    weapon_ptr
                    + VehicleLab.weapon_offset.ammo_info
                )

            if not ok
                or not vehicle_lab_plausible_pointer(
                    ammo_ptr
                ) then
                return 0, hash
            end

            return tonumber(ammo_ptr) or 0,
                hash
        end

        -- Mounted weapon queries can retain a stale hash after leaving a car.
        -- On foot, only the selected Homing Launcher shares these settings.
        if not entity_exists(vehicle) then
            if not entity_exists(ped) then return 0, 0 end
            local selected = vehicle_lab_u32(invoke_int(H.GET_SELECTED_PED_WEAPON, ped))
            if not VehicleMods.is_projectile_weapon(selected) then return 0, selected end
            return resolve_weapon_ammo(selected)
        end

        -- A positively reported mounted weapon is authoritative. Never replace a
        -- real cannon/gun slot with the vehicle model's missile mapping.
        if weapon_u32 ~= 0 then
            local ptr, resolved =
                resolve_weapon_ammo(weapon_u32)

            if ptr ~= 0 then
                return ptr, resolved
            end

            if VehicleMods
                and not VehicleMods.is_projectile_weapon(
                    weapon_u32
                ) then
                return 0, weapon_u32
            end
        end

        -- Enhanced can transiently report no mounted weapon while entering or
        -- changing a missile slot. Only in that unavailable state use the verified
        -- vehicle-model missile mapping.
        if weapon_u32 == 0
            and entity_exists(vehicle)
            and VehicleMods
            and type(
                VehicleMods.projectile_weapon_by_model
            ) == "table" then
            local model =
                vehicle_lab_u32(
                    invoke_int(
                        H.GET_ENTITY_MODEL,
                        vehicle
                    )
                )

            local mapped =
                VehicleMods.projectile_weapon_by_model[
                model
                ]

            if mapped then
                local ptr, resolved =
                    resolve_weapon_ammo(mapped)

                if ptr ~= 0 then
                    return ptr, resolved
                end
            end
        end

        return 0, weapon_u32
    end

    function VehicleLab.current_ammo_context(ped, vehicle)
        local ammo_ptr, weapon_hash = VehicleLab.current_ammo_ptr(ped, vehicle)
        if ammo_ptr == 0 then return 0, weapon_hash or 0, 0 end
        local ok, ammo_hash = pcall(Memory.ReadUInt, ammo_ptr + VehicleLab.ammo_offset.name)
        if not ok or type(ammo_hash) ~= "number" then ammo_hash = 0 end
        return ammo_ptr, weapon_hash or 0, vehicle_lab_u32(ammo_hash)
    end

    function VehicleLab.projectile_lifetime(baseline_lifetime, baseline_speed, actual_speed, range_multiplier)
        if not vehicle_lab_number_in_range(baseline_lifetime, 0.0, 120.0)
            or not vehicle_lab_number_in_range(baseline_speed, 0.01, 10000.0)
            or not vehicle_lab_number_in_range(actual_speed, 0.01, 10000.0)
            or not vehicle_lab_number_in_range(range_multiplier, 0.25, 30.0) then return nil end
        -- A zero FromVehicleLifeTime is a source-data sentinel, not an invalid
        -- projectile. Leave it zero so GTA continues using LifeTime.
        if baseline_lifetime == 0.0 then return 0.0 end
        return math.max(0.005, math.min(120.0,
            baseline_lifetime * baseline_speed * range_multiplier / actual_speed))
    end

    function VehicleLab.apply_rocket_tuning(ped, vehicle)
        local state, o = VehicleLab.state, VehicleLab.ammo_offset
        local speed_mult = math.max(0.25, math.min(8.0, slider_float("vehicle_rocket_speed", 1.0)))
        -- Rocket Speed is owned by the active AmmoInfo launch_speed field.
        -- Projectile tracking is guidance-only and must not scale velocity again.
        local speed_changed = math.abs(speed_mult - 1.0) > 0.001
        local lifetime_seconds=math.max(0,math.min(120,slider_float("vehicle_rocket_lifetime",0)))
        local range_changed = lifetime_seconds>0
        local buff_homing = is_on("vehicle_buff_all_rockets")
local wanted = speed_changed or range_changed or buff_homing

if not entity_exists(ped) or invoke_bool(H.IS_ENTITY_DEAD, ped, false) or not wanted then
    if state.ammo_runtime_ptr ~= 0
        or next(state.ammo_range_snapshots) ~= nil
        or next(state.runtime_ammo_snapshots) ~= nil then
        local profiles_restored = VehicleLab.restore_runtime_ammo_profiles()
        local ranges_restored = VehicleLab.restore_all_ammo_ranges()
        if not profiles_restored or not ranges_restored then return false end
    end

    state.ammo_runtime_ptr = 0
    state.ammo_runtime_signature = nil
    return false
end

local ptr, weapon_hash = VehicleLab.current_ammo_ptr(ped, vehicle)
if ptr == 0 then
    -- A mounted cannon/gun slot must leave the supported missile catalogue
    -- intact. On-foot deselection still releases the departing launcher owner.
    if not entity_exists(vehicle) or state.ammo_runtime_on_foot then
        local profiles_restored = VehicleLab.restore_runtime_ammo_profiles()
        local ranges_restored = VehicleLab.restore_all_ammo_ranges()
        if profiles_restored and ranges_restored then
            state.ammo_runtime_ptr, state.ammo_runtime_signature = 0, nil
        end
    end
    return false
end
if not VehicleLab.restore_other_ammo_ranges(ptr) then return false end

local signature = table.concat({
    tostring(ptr),
    ("%.3f"):format(speed_mult),
    ("%.3f"):format(lifetime_seconds),
    buff_homing and "1" or "0",
}, ":")

if state.ammo_runtime_ptr == ptr
    and state.ammo_runtime_signature == signature then
    state.ammo_runtime_on_foot = not entity_exists(vehicle)
    return VehicleLab.weapon_backend().Verify(ptr)
end

if state.ammo_runtime_ptr ~= 0
    and state.ammo_runtime_ptr ~= ptr then

    if buff_homing and entity_exists(vehicle) and not state.ammo_runtime_on_foot then
        -- Buff All owns the catalogue-wide guidance state. Changing the active
        -- mounted weapon must not restore every supported ammo profile.
        -- Preserve the existing catalogue speed/guidance ownership. The observer
        -- did not establish a different per-launcher speed policy.
        if VehicleLab.restore_all_ammo_ranges() == false then return false end

        state.ammo_runtime_ptr = 0
        state.ammo_runtime_signature = nil
    else
        local profiles_restored = VehicleLab.restore_runtime_ammo_profiles()
        local ranges_restored = VehicleLab.restore_all_ammo_ranges()
        if not profiles_restored or not ranges_restored then return false end
    end
end
local base = VehicleLab.capture_runtime_ammo_profile(ptr, weapon_hash)
        if not base then return false end
        local profile = {}
        for key, value in pairs(base) do profile[key] = value end
        profile.launch_speed = math.min(10000.0, base.launch_speed * speed_mult)
        -- The catalogue owns all guidance fields. This composer owns only speed
        -- and range; it must neither overwrite nor restore a live guidance claim.
        if not speed_changed then pcall(owned_restore, MEMORY_OWNERS.ammo_speed, ptr, "launch_speed") end
        local write_ok, write_err = pcall(function()
            if speed_changed then
                owned_snapshot(MEMORY_OWNERS.ammo_speed, ptr, "launch_speed",
                    ptr + o.launch_speed, "float")
                owned_write(MEMORY_OWNERS.ammo_speed, ptr, "launch_speed",
                    ptr + o.launch_speed, profile.launch_speed, "float")
            end
        end)
        if not write_ok then
            log_error_once("vehicle_rocket_profile_" .. tostring(weapon_hash), write_err)
            return false
        end
        local verify_ok, verify = pcall(function()
            local v={launch_speed=Memory.ReadFloat(ptr+o.launch_speed)}
            if buff_homing then
                v.use_homing_params=Memory.ReadUByte(ptr+o.use_homing_params)
                v.turn_rate_modifier=Memory.ReadFloat(ptr+o.turn_rate_modifier)
                v.pitch_yaw_roll_clamp=Memory.ReadFloat(ptr+o.pitch_yaw_roll_clamp)
            end
            return v
        end)
        local verified=verify_ok and type(verify)=='table' and VehicleLab.weapon_backend().Verify(ptr)
        if not verified then
            VehicleLab.restore_runtime_ammo_profile_ptr(ptr, true, true)
            log_error_once("vehicle_rocket_profile_verify_" .. tostring(weapon_hash),
                "active native-selected AmmoInfo read-back failed")
            return false
        end

        if range_changed then
            if not state.ammo_range_snapshots[ptr] then
                local ok1, lifetime = pcall(Memory.ReadFloat, ptr + o.lifetime)
                local ok2, vehicle_lifetime = pcall(Memory.ReadFloat, ptr + o.from_vehicle_lifetime)
                local ok3, locked_lifetime = pcall(Memory.ReadFloat, ptr + o.player_vehicle_locked_lifetime)
                if ok1 and ok2 and ok3 and vehicle_lab_number_in_range(lifetime, 0.05, 120.0)
                    and vehicle_lab_number_in_range(vehicle_lifetime, 0.0, 120.0)
                    and (locked_lifetime == -1 or vehicle_lab_number_in_range(locked_lifetime, 0.0, 120.0)) then
                    local range_ok, range_err = snapshot_fields(MEMORY_OWNERS.projectile, ptr, o, {
                        { "lifetime", "float" }, { "from_vehicle_lifetime", "float" },
                        { "player_vehicle_locked_lifetime", "float" },
                    })
                    if range_ok then
                        state.ammo_range_snapshots[ptr] = {
                            lifetime = VehicleLab.weapon_backend().Baseline(ptr,"lifetime",lifetime),
                            from_vehicle_lifetime = VehicleLab.weapon_backend().Baseline(ptr,"from_vehicle_lifetime",vehicle_lifetime),
                            player_vehicle_locked_lifetime = VehicleLab.weapon_backend().Baseline(ptr,"player_vehicle_locked_lifetime",locked_lifetime),
                        }
                    else
                        log_error_once("vehicle_rocket_range_ownership_" .. tostring(ptr), range_err)
                    end
                end
            end
            local rs = state.ammo_range_snapshots[ptr]
            if not rs then return false end
            local lifetime=lifetime_seconds
            local vehicle_lifetime=rs.from_vehicle_lifetime==0 and 0 or lifetime_seconds
            local locked_lifetime=rs.player_vehicle_locked_lifetime<=0 and rs.player_vehicle_locked_lifetime or lifetime_seconds
            if lifetime == nil or vehicle_lifetime == nil or locked_lifetime == nil then return false end
            local range_ok, range_error = pcall(function()
                owned_write(MEMORY_OWNERS.projectile, ptr, "lifetime",
                    ptr + o.lifetime, lifetime, "float")
                owned_write(MEMORY_OWNERS.projectile, ptr, "from_vehicle_lifetime",
                    ptr + o.from_vehicle_lifetime, vehicle_lifetime, "float")
                owned_write(MEMORY_OWNERS.projectile, ptr, "player_vehicle_locked_lifetime",
                    ptr + o.player_vehicle_locked_lifetime, locked_lifetime, "float")
                return math.abs(Memory.ReadFloat(ptr + o.lifetime) - lifetime) < 0.001
                    and math.abs(Memory.ReadFloat(ptr + o.from_vehicle_lifetime) - vehicle_lifetime) < 0.001
                    and math.abs(Memory.ReadFloat(ptr + o.player_vehicle_locked_lifetime) - locked_lifetime) < 0.001
            end)
            if not range_ok or range_error ~= true then
                VehicleLab.restore_ammo_range(ptr)
                state.ammo_runtime_signature = nil
                log_error_once("vehicle_rocket_range_verify_" .. tostring(ptr),
                    "projectile lifetime write/read-back failed")
                return false
            end
        elseif state.ammo_range_snapshots[ptr] then
            VehicleLab.restore_ammo_range(ptr)
        end

        state.ammo_runtime_ptr = ptr
        state.ammo_runtime_signature = signature
        state.ammo_runtime_on_foot = not entity_exists(vehicle)
        return true
    end

    function VehicleLab.restore_missile_profile()
        if (VehicleLab.state.missile_profile_ptr or 0) == 0 then return true end
        local ok=VehicleLab.weapon_backend().ReleaseOwner('vehicle.missile_profile')
        if ok then VehicleLab.state.missile_profile_ptr=0 end
        VehicleLab.state.ammo_runtime_signature=nil
        return ok
    end

    function VehicleLab.frame_tick(now)
        VehicleLab.unlimited_boost_tick(now)
        local state = VehicleLab.state
        state.last_cannon_shot_ms = 0
        local restore_requested = is_on("vehicle_lab_cannons")
        local range_requested = is_on("vehicle_cannon_range")
        local rapid_requested = VehicleLab.rapid_requested()
        if not restore_requested and not rapid_requested then VehicleLab.restore_cannon_timing("timing intents off") end
        if not restore_requested and not range_requested and not rapid_requested then
            if state.native_cannon_profile_ptr ~= 0 then
                VehicleLab.restore_native_cannon_profile()
            else
                state.cannon_active = false
            end
            return
        end
        now = tonumber(now) or 0
        if now - state.native_cannon_profile_last_ms < NATIVE_CANNON_PROFILE.refresh_ms then return end
        state.native_cannon_profile_last_ms = now

        local ped = local_ped()
        local vehicle = local_vehicle()
        if not entity_exists(ped) or not entity_exists(vehicle) then
            VehicleLab.restore_cannon_timing("local cannon context lost")
            VehicleLab.restore_native_cannon_profile()
            return
        end
        local weapon_hash, ptr = VehicleLab.resolve_weapon_runtime_target(ped)
        if VehicleLab.is_native_aircraft_cannon(weapon_hash) then
            VehicleLab.apply_native_cannon_profile(ped, vehicle, weapon_hash, ptr)
            return
        end
        VehicleLab.restore_cannon_timing("selected slot is not a cannon")
        VehicleLab.restore_native_cannon_profile()
    end

    local function rocket_boost_vehicle_address(vehicle)
        if not (GTA and type(GTA.HandleToPointer)=="function") then return nil end
        local ok,pointer=pcall(GTA.HandleToPointer,vehicle)
        if not ok or (type(pointer)~="table" and type(pointer)~="userdata") then return nil end
        local address_ok,address=pcall(function() return pointer:GetAddress() end)
        address=address_ok and tonumber(address) or nil
        if not address or address<=0 or address>=math.huge or address%1~=0 then return nil end
        return address
    end

    function VehicleLab.restore_unlimited_boost(reason)
        local state=VehicleLab.state
        -- No persistent recharge override, forced-active loop or stored key.
        -- PAD ownership lasts one frame. Off/change/unload invalidates every
        -- pending command before another frame can refill or start a boost.
        state.rocket_boost_controller=nil
        state.rocket_boost_release_pending=false
        state.rocket_boost_vehicle=0
        state.rocket_boost_address=nil
        state.rocket_boost_applied=false
        state.rocket_boost_requested=false
        state.rocket_boost_input_down=nil
        state.rocket_boost_last_tick=nil
        state.rocket_boost_restore_seconds=nil
        state.rocket_boost_restore_source=nil
        state.rocket_boost_model=nil
        state.rocket_boost_control=nil
        state.rocket_boost_last_active=nil
        state.rocket_boost_cancel_pending=false
        state.rocket_boost_cancel_attempts=0
        state.rocket_boost_cancel_retry_ms=nil
        state.rocket_boost_blocked=nil
        return true
    end

    -- Enhanced PAD action indices, checked against its input enum. Legacy
    -- 351/352/354 map to replay-camera actions here; use the Enhanced boost IDs.
    local ROCKET_BOOST_INPUT = {ground=388, flight=389, bike_wings=391, horn=86}
    local ROCKET_BOOST_CONTROL_ROUTES = {
        [Utils.Joaat("scramjet") & 0xFFFFFFFF] = ROCKET_BOOST_INPUT.bike_wings,
        [Utils.Joaat("oppressor2") & 0xFFFFFFFF] = ROCKET_BOOST_INPUT.bike_wings,
        [Utils.Joaat("voltic2") & 0xFFFFFFFF] = ROCKET_BOOST_INPUT.horn,
    }

    local function rocket_boost_read_bool(hash, ...)
        if not hash or type(Natives.InvokeBool)~="function" then return nil end
        local ok,value=pcall(Natives.InvokeBool,hash,...)
        if not ok or type(value)~="boolean" then return nil end
        return value
    end

    local function rocket_boost_read_int(hash, ...)
        if not hash or type(Natives.InvokeInt)~="function" then return nil end
        local ok,value=pcall(Natives.InvokeInt,hash,...)
        if not ok or type(value)~="number" or value%1~=0 then return nil end
        return value
    end

    local function rocket_boost_write(controller, hash, ...)
        -- A newer toggle/context always wins, including a callback during a
        -- preceding native call. Never retain an entity pointer across writes.
        if VehicleLab.state.rocket_boost_controller~=controller
            or not is_on("vehicle_unlimited_rocket_boost")
            or local_vehicle()~=controller.vehicle or local_ped()~=controller.ped
            or not entity_exists(controller.vehicle)
            or rocket_boost_vehicle_address(controller.vehicle)~=controller.address
            or invoke_int(H.GET_PED_IN_VEHICLE_SEAT,controller.vehicle,-1,false)~=controller.ped
            or not hash or type(Natives.InvokeVoid)~="function" then return false end
        local ok,result=pcall(Natives.InvokeVoid,hash,...)
        -- InvokeVoid normally returns nil. An explicit false is a rejection;
        -- neither a successful call nor an active-bit readback proves motion.
        return ok and result~=false
    end

    local function rocket_boost_note(controller, action)
        controller.note=action
    end

    local function rocket_boost_flush(now, controller, active)
        local state=VehicleLab.state
        if not controller.note or now-(state.rocket_boost_note_ms or -100000)<1000 then return end
        state.rocket_boost_note_ms=now
        log_info(("Rocket boost %s: model=0x%08X control=%d binding=%s source=%s samples=%d nativeFrame=%s repeatedFrame=%d pad=%d/%d/%d nativeActive=%s start=%d cancel=%d readback=%d writes=%d lastWrite=%s; live motion unverified."):format(
            controller.note,controller.model,controller.control,controller.binding or "unavailable",
            controller.last_press_source or controller.input_source or "pending",controller.samples or 0,
            tostring(controller.frame),controller.repeated_frame or 0,controller.normal_samples or 0,
            controller.disabled_samples or 0,controller.pulse_samples or 0,
            tostring(active),controller.starts,controller.cancels,controller.readbacks,
            controller.writes,tostring(controller.last_write_ok)))
        controller.note=nil
    end

    local function rocket_boost_forget_input(controller)
        controller.down=nil
        controller.just=nil
        controller.active=nil
        controller.pending=nil
        controller.cancel_latched=false
        controller.inactive_tick=nil
        controller.fault=false
    end

    function VehicleLab.unlimited_boost_tick(now)
        local state=VehicleLab.state
        if not is_on("vehicle_unlimited_rocket_boost") then
            VehicleLab.restore_unlimited_boost("off");return
        end
        local vehicle=local_vehicle()
        local ped=local_ped()
        local address=entity_exists(vehicle) and rocket_boost_vehicle_address(vehicle) or nil
        if not address or ped==0 or invoke_int(H.GET_PED_IN_VEHICLE_SEAT,vehicle,-1,false)~=ped
            or rocket_boost_read_bool(H.IS_ENTITY_DEAD,vehicle,false)~=false
            or rocket_boost_read_bool(H.IS_ENTITY_DEAD,ped,false)~=false
            or rocket_boost_read_bool(H.GET_HAS_ROCKET_BOOST,vehicle)~=true then
            VehicleLab.restore_unlimited_boost("unsupported context");return
        end
        local controller=state.rocket_boost_controller
        if controller and (controller.vehicle~=vehicle or controller.address~=address or controller.ped~=ped) then
            VehicleLab.restore_unlimited_boost("vehicle/ped changed");controller=nil
        end
        if not controller then
            local model=rocket_boost_read_int(H.GET_ENTITY_MODEL,vehicle)
            if not model or model==0 then return end
            model=model & 0xFFFFFFFF
            local class=rocket_boost_read_int(0x29439776AAA00A62,vehicle) -- GET_VEHICLE_CLASS
            local control=ROCKET_BOOST_CONTROL_ROUTES[model]
                or ((class==15 or class==16) and ROCKET_BOOST_INPUT.flight or ROCKET_BOOST_INPUT.ground)
            controller={vehicle=vehicle,ped=ped,address=address,model=model,control=control,
                starts=0,cancels=0,readbacks=0,writes=0,revision=0,samples=0,
                normal_samples=0,disabled_samples=0,pulse_samples=0,probe_count=0,probe_due=now+2000}
            -- Read-only binding label for diagnosis; never infer a key press
            -- from a help label or add a universal keyboard binding.
            if type(Natives.InvokeString)=="function" then
                local ok,label=pcall(Natives.InvokeString,0x0499D7B09FC9B407,0,control,true)
                if ok and type(label)=="string" and #label>0 then
                    controller.binding=label:gsub("[%c]"," "):sub(1,40)
                end
            end
            state.rocket_boost_controller=controller
            state.rocket_boost_vehicle=vehicle
            state.rocket_boost_address=address
            state.rocket_boost_model=model
            state.rocket_boost_control=control
            rocket_boost_note(controller,"acquired")
        end
        -- GET_FRAME_COUNT may stay constant, so use it only for diagnostics.
        -- The scheduler owns frame work; input edges handle deduplication.
        local frame=rocket_boost_read_int(0xFC8202EFC642E6F2)
        controller.repeated_frame=frame~=nil and frame==controller.frame
            and (controller.repeated_frame or 0)+1 or 0
        controller.frame=frame
        controller.samples=controller.samples+1
        if controller.tick and (now<controller.tick or now-controller.tick>250) then
            rocket_boost_forget_input(controller)
        end
        controller.tick=now
        local active=rocket_boost_read_bool(H.IS_ROCKET_BOOST_ACTIVE,vehicle)
        local block=nil
        if rocket_boost_read_bool(0xB0034A223497FFCB)~=false then block="pause/unreadable"
        elseif rocket_boost_read_bool(0xB118AF58B5F332A1)~=false then block="text chat/unreadable"
        elseif rocket_boost_read_bool(0x49C32D60007AFA47,local_player_id())~=true then block="player control/unreadable"
        elseif rocket_boost_read_bool(H.IS_CUTSCENE_ACTIVE)~=false then block="cutscene/unreadable"
        elseif active==nil then block="boost state unreadable" end
        local down,just,normal,disabled
        if not block then
            normal=rocket_boost_read_bool(H.IS_CONTROL_PRESSED,0,controller.control)
            disabled=rocket_boost_read_bool(H.IS_DISABLED_CONTROL_PRESSED,0,controller.control)
            if normal==true or disabled==true then down=true
            elseif normal==false and disabled==false then down=false
            else block="boost input unreadable" end
            just=rocket_boost_read_bool(H.IS_CONTROL_JUST_PRESSED,0,controller.control)==true
                or rocket_boost_read_bool(0x91AEF906BCA88877,0,controller.control)==true -- IS_DISABLED_CONTROL_JUST_PRESSED
            if normal==true then controller.normal_samples=controller.normal_samples+1 end
            if disabled==true then controller.disabled_samples=controller.disabled_samples+1 end
            if just==true then controller.pulse_samples=controller.pulse_samples+1 end
        end
        if block then
            rocket_boost_forget_input(controller)
            if controller.blocked~=block then rocket_boost_note(controller,"paused: "..block) end
            controller.blocked=block
            rocket_boost_flush(now,controller,active)
            return
        end
        if controller.blocked then
            controller.blocked=nil
            rocket_boost_note(controller,"input resumed; waiting for release")
        end
        controller.input_source=normal and "normal" or (disabled and "disabled" or "released")
        -- Own the vehicle's boost action for this frame so GTA cannot process
        -- the same press again and invert the commanded state. Disabled PAD
        -- reads preserve its binding, including while the Cherax menu is open.
        if not rocket_boost_write(controller,H.DISABLE_CONTROL_ACTION,0,controller.control,true) then
            rocket_boost_forget_input(controller)
            rocket_boost_note(controller,"input ownership rejected; refill paused")
            rocket_boost_flush(now,controller,active)
            return
        end
        -- Consume a JUST_PRESSED pulse once, even if the callback runs twice
        -- in one game frame. A repeated/stuck pulse must not turn a release
        -- into another press. Real down/up edges remain independently usable.
        local pressed=controller.down==false and (down==true
            or (just==true and controller.just==false))
        local previous_active=controller.active
        controller.down=down
        controller.just=just
        controller.active=active
        if pressed then
            controller.last_press_source=normal and "normal" or (disabled and "disabled" or "pulse")
            local was_active=previous_active
            if controller.pending then was_active=controller.pending.target
            elseif controller.cancel_latched then was_active=false end
            if was_active==nil then was_active=active end
            local target=not was_active
            controller.revision=controller.revision+1
            controller.pending={target=target,revision=controller.revision,attempts=0,
                retry=now,deadline=now+400}
            controller.fault=false
            controller.cancel_latched=not target
            controller.inactive_tick=nil
            if target then controller.starts=controller.starts+1
            else controller.cancels=controller.cancels+1 end
            rocket_boost_note(controller,target and "start requested" or "cancel requested")
        elseif previous_active==nil and (down or just) then
            -- Enabling/resuming while held never manufactures an input edge.
            controller.down=true
        end
        local pending=controller.pending
        local filled=false
        if pending then
            if active==pending.target then
                controller.pending=nil
                controller.readbacks=controller.readbacks+1
                if not active then controller.inactive_tick=now end
                rocket_boost_note(controller,active and "start readback active" or "cancel readback inactive")
            elseif now>pending.deadline then
                controller.pending=nil
                controller.fault=true
                rocket_boost_note(controller,"command timed out; refill paused until next press")
            elseif pending.attempts<3 and now>=pending.retry then
                pending.attempts=pending.attempts+1
                pending.retry=now+80
                if pending.target then
                    filled=rocket_boost_write(controller,H.SET_ROCKET_BOOST_FILL or H.SET_VEHICLE_ROCKET_BOOST_PERCENTAGE,vehicle,1.0)
                end
                -- A bounded true write belongs to this fresh start press only.
                -- Once observed active, it is never continuously forced back on.
                if not pending.target or filled then
                    controller.last_write_ok=rocket_boost_write(controller,H.SET_ROCKET_BOOST_ACTIVE,vehicle,pending.target)
                    controller.writes=controller.writes+1
                else controller.last_write_ok=false end
                rocket_boost_note(controller,pending.target and "start command issued" or "cancel command issued")
            end
        end
        if controller.cancel_latched and not controller.pending and not controller.fault then
            -- Observe inactive for a whole tick and release the cancel press
            -- before refilling. A newer press may supersede this latch above.
            if active==false and down==false and not just and controller.inactive_tick
                and now>controller.inactive_tick then
                controller.cancel_latched=false
            end
        end
        local can_fill=not controller.fault and not controller.cancel_latched
            and (not controller.pending or controller.pending.target==true)
        if can_fill and not filled then
            filled=rocket_boost_write(controller,H.SET_ROCKET_BOOST_FILL or H.SET_VEHICLE_ROCKET_BOOST_PERCENTAGE,vehicle,1.0)
        end
        -- Do not reattach state invalidated by an off/change callback inside a
        -- host call. Other cleanup owners retain their existing drain behavior.
        if state.rocket_boost_controller==controller then
            state.rocket_boost_applied=filled or controller.pending~=nil
            state.rocket_boost_requested=controller.pending~=nil
            state.rocket_boost_release_pending=false
        end
        -- Three bounded health receipts after acquisition expose a silent
        -- input route/frame failure even when no press reaches the controller.
        -- Thereafter only state changes are logged, with the shared1s throttle.
        if controller.probe_count<3 and now>=controller.probe_due then
            controller.probe_count=controller.probe_count+1
            controller.probe_due=now+5000
            if not controller.note then rocket_boost_note(controller,"input health") end
        end
        rocket_boost_flush(now,controller,active)
    end

    function VehicleLab.restore(unloading)
        local state = VehicleLab.state
        local timing_restored
        if unloading==true then timing_restored=VehicleLab.unload_cannon_timing()
        else timing_restored=VehicleLab.restore_cannon_timing("Vehicle restore")end
        local backend_restored = not state.backend or state.backend.RestoreAll()
        state.missile_profile_ptr=0
        local boost_restored = VehicleLab.restore_unlimited_boost("VehicleLab restore")
        local cannon_restored = VehicleLab.restore_native_cannon_profile()
        state.last_cannon_shot_ms = 0
        state.aircraft_cannon_diagnostic_signature = nil
        state.aircraft_cannon_diagnostic_last_ms = -100000
        state.native_cannon_profile_last_ms = -100000
        state.last_maintenance_ms = 0
        VehicleLab.restore_global_homing_buff()
        VehicleLab.restore_runtime_ammo_profiles()
        state.global_homing_ptrs = {}
        state.global_homing_weapon_ptrs = {}
        state.global_homing_active = false
        state.global_homing_signature = nil
        state.global_homing_last_count = 0
        state.global_homing_last_weapon_count = 0
        VehicleLab.restore_all_ammo_ranges()
        VehicleLab.restore_all_weapon_runtime()
        state.ammo_runtime_signature = nil
        state.rapid_runtime_log_signature = nil
        state.composition_log_signature = nil
        state.diagnostic_stock_firing_delay = nil
        state.diagnostic_effective_firing_delay = nil
        state.diagnostic_cadence_ptr = 0
        state.ammo_runtime_ptr = 0
        state.weapon_runtime_signature = nil






        local owned_restored = true
        for _, owner in ipairs(MEMORY_OWNER_RESTORE_ORDER) do
            if not OwnedMemory.RestoreOwner(owner) then owned_restored = false end
        end
        return timing_restored and backend_restored and boost_restored and cannon_restored and owned_restored
    end

    function VehicleLab.shutdown()
        local restored=VehicleLab.restore(true)
        local state = VehicleLab.state
        if state.weapon_hash_ptr ~= 0 then
            local pointer = state.weapon_hash_ptr
            state.weapon_hash_ptr = 0
            if Memory and type(Memory.Free) == "function" then
                local ok, err = pcall(Memory.Free, pointer)
                if not ok then log_error_once("vehicle_lab_pointer_free", err) end
            end
        end
        return restored
    end

