    function VehicleMods.fire_control(ped, vehicle, weapon_hash)
        local controller = VehicleMods.state.controller
        local context = controller.context or {}
        if context.ped ~= ped or context.vehicle ~= vehicle
            or context.weapon_hash ~= vehicle_lab_u32(weapon_hash) then return nil end
        return context.fire_control
    end

    function VehicleMods.is_projectile_weapon(hash)
        hash = hash and vehicle_lab_u32(hash) or 0
        return hash ~= 0 and VehicleMods.projectile_weapon_set[hash] == true
    end

    -- Aircraft firearms use CScript-owned cadence with the Cherax helper off.
    -- GTA retains aim, fire commands, and input handling.
    function VehicleMods.should_use_direct_rapid(hash)
        hash = hash and vehicle_lab_u32(hash) or 0
        -- vehicles.json identifies Starling's mounted firearm as DOGFIGHTER_MG;
        -- the weapon metadata classifies that record as INSTANT_HIT /
        -- AMMO_MINIGUN. Admission still uses the current native weapon hash,
        -- never the vehicle model, a cached slot, or its missile counterpart.
        return hash ~= 0 and (VehicleLab.is_native_aircraft_cannon(hash)
            or hash == vehicle_lab_u32(Utils.Joaat("VEHICLE_WEAPON_DOGFIGHTER_MG")))
    end

    function VehicleMods.native_aircraft_cannon_active(ped, vehicle)
        local weapon_hash = VehicleLab.get_current_vehicle_weapon(ped)
        if VehicleLab.is_native_aircraft_cannon(weapon_hash) then
            return true, vehicle_lab_u32(weapon_hash)
        end
        -- The native briefly returns zero during weapon-slot transitions. Model is
        -- only a fail-closed fallback; a verified non-cannon hash remains usable.
        if (not weapon_hash or vehicle_lab_u32(weapon_hash) == 0) and entity_exists(vehicle) then
            local model = invoke_int(H.GET_ENTITY_MODEL, vehicle)
            if vehicle_lab_is_jet(model) then return true, 0 end
        end
        return false, weapon_hash and vehicle_lab_u32(weapon_hash) or 0
    end


    -- Feature.Toggle changes a value; the installed Feature API exposes
    -- TriggerCallback separately. The old Instant Lock bridge never dispatched
    -- that callback, and treated the checkbox as proof of acquisition speed.
    -- No Enhanced acquisition-timer offset is validated here. Use only this exact
    -- host workflow, with a separate subsequent-frame observation of GTA's state.
    function VehicleMods.instant_lock_state()
        local state = VehicleMods.state
        if not state.instant_lock then
            state.instant_lock = { status = "IDLE", reason = "disabled", yielded = false }
        end
        return state.instant_lock
    end

    function VehicleMods.instant_lock_status(status, reason)
        local state = VehicleMods.instant_lock_state()
        if status~="OBSERVED" and status~="DELAY_OBSERVED" then
            -- Ownership survives uncertainty; current observations do not.
            state.acquire_start,state.previous_sample,state.lock_state,state.observed_ms=nil,nil,nil,nil
            state.target_key,state.target,state.target_address=nil,nil,nil
            state.stage,state.target_registered="UNKNOWN",false
            state.pending_rearm=nil
        end
        if state.status ~= status or state.reason ~= reason then
            combat_record("Instant Lock", "acquisition state",
                "status=" .. status .. " reason=" .. tostring(reason),
                (status == "DELAY_OBSERVED" or status == "FAILED") and "WARN" or "INFO")
        end
        state.status, state.reason = status, reason
        -- Never let a checkbox suppress a separately validated backend or count
        -- as behavioral proof in the shared combat controller.
        VehicleMods.state.builtin_effective.instant_lock = false
    end

    function VehicleMods.mounted_seat(ped,vehicle)
        local ok,seat=pcall(function()
            local count=Natives.InvokeInt(H.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS,vehicle)
            if type(count)~="number" or count%1~=0 or count<0 or count>15 then return nil end
            for slot=-1,count-1 do
                if Natives.InvokeInt(H.GET_PED_IN_VEHICLE_SEAT,vehicle,slot,false)==ped then return slot end
            end
        end)
        if ok then return seat end
    end

    function VehicleMods.instant_lock_identity(ped, vehicle)
        if ped ~= local_ped() or vehicle ~= local_vehicle() or not entity_exists(ped) then
            return nil,"Local shooter context unavailable"
        end
        local mounted = entity_exists(vehicle)
        if not mounted and invoke_bool(H.IS_PED_IN_ANY_VEHICLE,ped,false) then return nil,"Vehicle context not ready" end
        local ok,dead,transition,pa,va=pcall(function()
            local p=GTA.HandleToPointer(ped)
            local v=mounted and GTA.HandleToPointer(vehicle) or nil
            return Natives.InvokeBool(H.IS_ENTITY_DEAD,ped,false),Natives.InvokeBool(0x520F3282A53D26B7),
                p:GetAddress(),v and v:GetAddress() or 0
        end)
        if not ok or (dead~=false and dead~=0) or (transition~=false and transition~=0)
            or not vehicle_lab_plausible_pointer(pa) or (mounted and not vehicle_lab_plausible_pointer(va)) then
            return nil,"Local identity unavailable, dead or transitioning"
        end
        local seat=-2
        if mounted then seat=VehicleMods.mounted_seat(ped,vehicle) end
        if seat==nil then return nil,"Mounted seat unavailable" end
        local hash
        if mounted then hash=VehicleLab.get_current_vehicle_weapon(ped)
        else hash=invoke_int(H.GET_SELECTED_PED_WEAPON,ped) end
        if not hash or vehicle_lab_u32(hash)==0 then return nil,"Selected weapon unavailable" end
        if not mounted and not VehicleMods.is_projectile_weapon(vehicle_lab_u32(hash)) then
            return nil,"Select the Homing Launcher"
        end
        local ptr=VehicleLab.find_item_ptr(hash)
        if not validate_weapon_runtime_target(ptr,hash) then return nil,"Selected weapon record unavailable" end
        local supported,projectile,homing,ammo=pcall(function()
            return Memory.ReadUInt(ptr+VehicleLab.weapon_offset.name)==vehicle_lab_u32(hash)
                and Memory.ReadInt(ptr+VehicleLab.weapon_offset.fire_type)==4,
                VehicleLab.read_weapon_flag(ptr,9),Memory.ReadLong(ptr+VehicleLab.weapon_offset.ammo_info)
        end)
        if not supported or not projectile or not vehicle_lab_plausible_pointer(ammo) then
            return nil,"Selected weapon is not a validated homing projectile"
        end
        local fresh_ok,fresh=pcall(function()
            local current_hash
            if mounted then current_hash=VehicleLab.get_current_vehicle_weapon(ped)
            else current_hash=invoke_int(H.GET_SELECTED_PED_WEAPON,ped) end
            return ped==local_ped() and vehicle==local_vehicle()
                and (not mounted or Natives.InvokeInt(H.GET_PED_IN_VEHICLE_SEAT,vehicle,seat,false)==ped)
                and vehicle_lab_u32(current_hash)==vehicle_lab_u32(hash)
                and Memory.ReadLong(ptr+VehicleLab.weapon_offset.ammo_info)==ammo
        end)
        if not fresh_ok or not fresh then return nil,"Shooter identity changed during validation" end
        local generation=tonumber(VehicleMods.state.controller.session_generation) or 0
        return {ped=ped,vehicle=vehicle,hash=vehicle_lab_u32(hash),ptr=ptr,seat=seat,ammo_ptr=ammo,on_foot=not mounted,
            key=table.concat({generation,ped,pa,vehicle,va,seat,vehicle_lab_u32(hash),ptr,ammo},":")}
    end

    -- GTA has separate eligibility, acquiring and fully acquired states.
    -- SET_PLAYER_LOCKON enables the LOCAL player's permitted lock-on only.
    -- It does not eliminate GTA's acquisition timer. The existing Engine
    -- Homing Lock state is our sole readback, not a fabricated forced lock.
    function VehicleMods.instant_ammo_sync()return false end
    function VehicleMods.instant_lock_restore()
        VehicleMods.state.instant_lock={status="IDLE",reason="disabled",yielded=false}
        return true
    end
    local function observed_lock_status(state,now,lock,target)
        state.lock_state=lock
        state.target=target
        if lock==1 then
            state.acquire_start=state.acquire_start or now
            return "PENDING","GTA is acquiring target; timer not overridden"
        end
        if lock==2 and target>0 then
            local elapsed=state.acquire_start and math.max(0,now-state.acquire_start) or nil
            state.last_acquisition_ms=elapsed
            state.acquire_start=nil
            state.observed_ms=now
            return "OBSERVED","GTA confirmed full lock"..(elapsed and " after "..elapsed.." ms" or
                " (acquisition start not observed)").."; instant timing unverified"
        end
        state.acquire_start=nil
        if lock==2 then return "PENDING","Full-lock state reported, but target readback missing" end
        if lock==0 then return "PENDING","No target acquired; waiting for GTA lock state" end
        return "PENDING","GTA lock state unavailable"
    end
    function VehicleMods.instant_lock_observe(now,ped,vehicle)
        local requested=is_on("vehicle_instant_lockon")
        local targeting=is_on("vehicle_lock_players") or is_on("vehicle_lock_npcs")
        local state=VehicleMods.instant_lock_state()
        if not requested and not targeting then
            if state.owned then VehicleMods.instant_lock_restore() end
            return false
        end
        now=tonumber(now) or now_ms()
        if not entity_exists(ped) or ped~=local_ped() then
            state.status,state.reason="PENDING","local shooter unavailable"
            return false
        end
        local pid=local_player_id()
        if type(pid)~="number" or pid<0 or pid>31 or pid%1~=0 then
            state.status,state.reason="PENDING","local player ID unavailable"
            return false
        end
        -- Reassert sparingly, and ONLY for ourselves. Do not set false on
        -- toggle-off: that would disable standard GTA lock-on for the player.
        if not state.enabled_for or state.enabled_for~=pid or
            now>=(state.next_enable_at or 0) then
            state.enabled_for=pid
            state.next_enable_at=now+1500
            state.owned=invoke_void(H.SET_PLAYER_LOCKON,pid,true)==true
        end
        if not requested then
            state.status,state.reason="IDLE","lock-on eligibility enabled for target features"
            return state.owned==true
        end
        state.backend="local-player-eligibility+native-vehicle-state"
        if state.owned~=true then
            state.status,state.reason="PENDING","local lock-on enable was not accepted"
            return false
        end
        if not entity_exists(vehicle) then
            state.status="PENDING"
            state.reason="On-foot launcher: no vehicle lock-state proof; acquisition time unmodified"
            return true
        end
        local lock=invoke_int(H.GET_VEHICLE_HOMING_LOCKON_STATE,vehicle)
        if lock~=0 and lock~=1 and lock~=2 then lock=nil end
        local target=0
        if lock==2 then
            target=VehicleMods.get_native_locked_target(vehicle)
        end
        state.status,state.reason=observed_lock_status(state,now,lock,target)
        return true
    end
    function VehicleMods.set_builtin()return false end
    function VehicleMods.restore_builtin()return true end
    function VehicleMods.restore_builtins()return true end
    function VehicleMods.sync_builtins()
        local state=VehicleMods.state
        state.combat_active=false;state.noclip_active=false
        state.controller.force_refresh=false
    end

    local COMBAT_CONTROLLER_KEYS = {
        "buff_all_rockets", "instant_lock", "lock_players", "lock_npcs",
        "infinite_lock_range", "rocket_speed", "rocket_range",
        "rapid_fire", "cannon_restoration", "vehicle_ammo",
    }

    local function controller_copy(values)
        local result = {}
        for key, value in pairs(values or {}) do result[key] = value end
        return result
    end

    function VehicleMods.controller_identity(ped, vehicle, resolved_hash, resolved_ptr)
        local controller = VehicleMods.state.controller
        local current = controller.context or {}
        local in_vehicle = entity_exists(ped) and entity_exists(vehicle)
        local hash = in_vehicle and vehicle_lab_u32(resolved_hash or VehicleLab.get_current_vehicle_weapon(ped)) or 0
        local generation = module_context and module_context.Runtime
            and tonumber(module_context.Runtime.generation) or tonumber(controller.session_generation) or 0
        local seat = -2
        if in_vehicle then
            -- Compare the cached seat first; full bounded seat search occurs only
            -- when that seat no longer contains the local ped.
            local previous = current.vehicle == vehicle and current.seat or nil
            if previous and previous >= -1 and invoke_int(H.GET_PED_IN_VEHICLE_SEAT, vehicle, previous, false) == ped then
                seat = previous
            else
                local count = math.max(0, math.min(15, invoke_int(H.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS, vehicle)))
                for candidate = -1, count - 1 do
                    if invoke_int(H.GET_PED_IN_VEHICLE_SEAT, vehicle, candidate, false) == ped then seat = candidate; break end
                end
            end
        end
        local changed = current.ped ~= ped or current.vehicle ~= vehicle or current.seat ~= seat
            or current.weapon_hash ~= hash or current.session_generation ~= generation
        if not changed and hash ~= 0 and current.weapon_ptr == 0
            and now_ms() >= (controller.identity_retry_ms or 0) then changed = true end
        if not changed then return current, false end
        controller.identity_retry_ms = now_ms() + 500
        local ptr, ammo_ptr, ammo_hash, model = 0, 0, 0, 0
        local family, fire_control = "unavailable", nil
        if in_vehicle and hash ~= 0 and seat >= -1 then
            ptr = tonumber(resolved_ptr) or VehicleLab.find_item_ptr(hash)
            if ptr ~= 0 and validate_weapon_runtime_target(ptr, hash) then
                local ok, ammo = pcall(Memory.ReadLong, ptr + VehicleLab.weapon_offset.ammo_info)
                if ok and vehicle_lab_plausible_pointer(ammo) then
                    ammo_ptr = ammo
                    local read_ok, name = pcall(Memory.ReadUInt, ammo_ptr + VehicleLab.ammo_offset.name)
                    if read_ok then ammo_hash = vehicle_lab_u32(name) end
                end
            else ptr = 0 end
            model = vehicle_lab_u32(invoke_int(H.GET_ENTITY_MODEL, vehicle))
            local aircraft = invoke_bool(H.IS_THIS_MODEL_A_PLANE or 0xA0948AB42D7BA0DE, model)
                or invoke_bool(H.IS_THIS_MODEL_A_HELI or 0xDCE4334788AF94EA, model)
            if seat == -1 and aircraft then
                family, fire_control = "aircraft-primary", VehicleMods.fire_input.aircraft_primary
            elseif seat == -1 then
                family, fire_control = "vehicle-primary", VehicleMods.fire_input.vehicle_primary
            else
                -- No verified universal passenger/turret control mapping exists.
                -- GTA keeps its ordinary input for those seats.
                family = "passenger-mounted"
            end
        end
        local context = { ped = ped, vehicle = vehicle, seat = seat, model = model,
            weapon_hash = hash, weapon_ptr = ptr, ammo_ptr = ammo_ptr, ammo_hash = ammo_hash,
            weapon_family = family, fire_control = fire_control, session_generation = generation }
        controller.context, controller.session_generation = context, generation
        controller.force_refresh = true
        controller.identity_refreshes = (controller.identity_refreshes or 0) + 1
        combat_record("Vehicle Combat", "mounted identity changed",
            "seat=" .. seat .. " family=" .. family .. " weapon=" .. hash, "INFO")
        return context, true
    end

    function VehicleMods.controller_begin(now, ped, vehicle, resolved_hash, resolved_ptr)
        local controller = VehicleMods.state.controller
        local context = VehicleMods.controller_identity(ped, vehicle, resolved_hash, resolved_ptr)
        controller.domains = controller.domains or {
            TargetEligibility = VehicleMods.state.target_entities,
            LockAcquisition = VehicleMods.instant_lock_state(),
            LockRange = { owner = MEMORY_OWNERS.weapon, fields = { "lock_on_range", "weapon_range" } },
            ProjectileSpeed = { owner = MEMORY_OWNERS.ammo_speed, field = "launch_speed" },
            ProjectileLifetime = VehicleLab.state.ammo_range_snapshots,
            FireCadence = VehicleLab.state.weapon_runtime_snapshots,
            VehicleAmmo = VehicleMods.state.ammo_snapshots,
            CannonProfile = { owner = MEMORY_OWNERS.weapon, fields = NATIVE_CANNON_OWNED_FIELDS },
        }
        context.lock_state = entity_exists(vehicle) and invoke_int(H.GET_VEHICLE_HOMING_LOCKON_STATE, vehicle) or 0
        -- Read the engine's ACTUAL acquired target, not the last projectile's
        -- stale target. Only requested targeting modes need this native read.
        if entity_exists(vehicle) and context.lock_state==2 and
            (is_on("vehicle_instant_lockon") or is_on("vehicle_lock_players")
                or is_on("vehicle_lock_npcs")) then
            local previous=VehicleMods.state.last_lock_target_scan_ms or -100000
            if now-previous>=100 or now<previous then
                VehicleMods.state.last_lock_target_scan_ms=now
                VehicleMods.get_native_locked_target(vehicle)
            end
        end
        context.lock_target = VehicleMods.state.last_lock_target or 0
        local speed = math.max(0.25, math.min(8.0, slider_float("vehicle_rocket_speed", 1.0)))
        local desired = {
            buff_all_rockets = is_on("vehicle_buff_all_rockets"),
            instant_lock = is_on("vehicle_instant_lockon"),
            lock_players = is_on("vehicle_lock_players"),
            lock_npcs = is_on("vehicle_lock_npcs"),
            infinite_lock_range = is_on("vehicle_infinite_lock_range"),
            rocket_speed = math.abs(speed - 1.0) > 0.001,
            rocket_range = slider_float("vehicle_rocket_lifetime",0)>0,
            rapid_fire = VehicleLab.rapid_requested(),
            vehicle_ammo = is_on("vehicle_infinite_ammo"),
            cannon_restoration = is_on("vehicle_lab_cannons") or is_on("vehicle_cannon_range"),
        }
        for _, key in ipairs(COMBAT_CONTROLLER_KEYS) do
            if controller.desired[key] ~= desired[key] then
                combat_record("Vehicle Combat", "desired state changed",
                    "feature=" .. key .. " desired=" .. tostring(desired[key]), "INFO")
            end
        end
        controller.desired = desired
        controller.last_begin_ms = tonumber(now) or now_ms()
        return context, desired
    end

    function VehicleMods.controller_finalize(results)
        results = type(results) == "table" and results or {}
        local state, controller = VehicleMods.state, VehicleMods.state.controller
        local desired, context = controller.desired, controller.context
        local in_vehicle = entity_exists(context.ped) and entity_exists(context.vehicle)
        local pending = {}
        local function set_result(key, effective, backend, status, reason)
            local previous = controller.status[key]
            controller.effective[key] = effective == true
            controller.backend[key] = backend or "none"
            controller.status[key] = status or "IDLE"
            if (status == "PENDING" or status == "FAILED" or status == "PARTIAL"
                or (key == "instant_lock" and status ~= "IDLE")) and reason then
                pending[#pending + 1] = key .. ": " .. reason
            end
            if previous ~= controller.status[key] then
                local severity = status == "APPLIED" and "PASS" or (status == "FAILED" and "FAIL"
                    or (status == "PENDING" and "WARN" or "INFO"))
                combat_record("Vehicle Combat", "application state",
                    "feature=" .. key .. " status=" .. tostring(status) .. " backend="
                    .. tostring(backend) .. (reason and (" reason=" .. tostring(reason)) or ""), severity)
            end
        end
        local function context_reason()
            if not entity_exists(context.ped) then return "local ped unavailable" end
            if not in_vehicle then return "waiting for vehicle weapon context" end
            if context.weapon_hash == 0 then return "mounted weapon unavailable" end
            if context.weapon_ptr == 0 then return "CWeaponInfo unavailable" end
            return "AmmoInfo unavailable or unsupported mounted weapon"
        end
        for _, key in ipairs(COMBAT_CONTROLLER_KEYS) do
            if not desired[key] then
                set_result(key, false, "none", "IDLE")
            elseif key == "lock_players" or key == "lock_npcs" then
                if results.targets == true then
                    local mounted=VehicleMods.state.mounted_targeting
                    set_result(key, true, mounted and mounted.applied
                        and 'cherax-missile-category-provider' or builtin_effective(key)
                        and "custom-target-registration+builtin-assist"
                        or "custom-target-registration", "APPLIED")
                else
                    set_result(key, false, "pending", "PENDING", context_reason())
                end
            elseif key == "instant_lock" then
                local instant = VehicleMods.instant_lock_state()
                set_result(key, false, instant.backend or "cherax-callback",
                    instant.status, instant.reason)
            elseif key == "buff_all_rockets" then
                if results.buff == true then
                    set_result(key, true, "active-ammo-owned-fields", "APPLIED")
                else
                    set_result(key, false, "pending", "PENDING", context_reason())
                end
            elseif key == "rapid_fire" then
                local cannon=VehicleLab.state.native_cannon_observation
                if cannon and cannon.status=="WAITING_TIMING"and cannon.vehicle==context.vehicle
                    and cannon.hash==context.weapon_hash then
                    set_result(key,false,"cannon-timing","PENDING",cannon.reason)
                elseif cannon and cannon.status=="BLOCKED" and cannon.vehicle==context.vehicle
                    and cannon.hash==context.weapon_hash then
                    set_result(key,false,"native-cadence-readback","FAILED",cannon.reason)
                elseif VehicleLab.state.cadence_partial then
                    set_result(key,false,"owned-cadence-fields","PARTIAL","Some cadence fields are unsupported by this weapon")
                elseif builtin_effective("rapid_fire") then
                    set_result(key, true, "builtin", "APPLIED")
                elseif results.rapid == true or results.weapon == true
                    or state.direct_rapid_active == true then
                    set_result(key, true, state.direct_rapid_active and "native-input-owned-cadence" or "custom-cadence",
                        "APPLIED")
                else
                    set_result(key, false, "pending", "PENDING", context_reason())
                end
            elseif key == "infinite_lock_range" then
                if builtin_effective(key) or (key == "infinite_lock_range"
                        and builtin_effective("disable_range_restrictions")) then
                    set_result(key, true, "builtin", "APPLIED")
                elseif results.weapon == true then
                    set_result(key, true, "custom-CWeaponInfo", "APPLIED")
                else
                    set_result(key, false, "pending", "PENDING", context_reason())
                end
            elseif key == "rocket_speed" then
                if results.ammo == true then
                    set_result(key, true, "active-AmmoInfo-launch-speed", "APPLIED")
                else
                    set_result(key, false, "pending", "PENDING", context_reason())
                end
            elseif key == "rocket_range" then
                if results.ammo == true then
                    set_result(key, true, "custom-AmmoInfo-range", "APPLIED")
                else
                    set_result(key, false, "pending", "PENDING", context_reason())
                end
            elseif key == "vehicle_ammo" then
                set_result(key, results.vehicle_ammo == true, "vehicle-counters",
                    results.vehicle_ammo == true and "APPLIED" or "PENDING",
                    results.vehicle_ammo ~= true and "vehicle counter write/read-back pending" or nil)
            elseif key == "cannon_restoration" then
                local applied = (tonumber(VehicleLab.state.native_cannon_profile_ptr) or 0) ~= 0
                local cannon=VehicleLab.state.native_cannon_observation
                if is_on("vehicle_lab_cannons")and cannon and cannon.vehicle==context.vehicle
                    and cannon.status=='BALANCE_PENDING'then
                    local balance=cannon.balance or VehicleLab.cannon_balance_snapshot()
                    local phase=balance.phase
                    local failed=phase=='BLOCKED' or phase=='LOST' or phase=='RETRY_REQUIRED' or phase=='EXTERNAL_VALUE_PRESERVED'
                    set_result(key,false,'cannon-balance-data',failed and 'FAILED' or 'PENDING',cannon.reason or balance.last_error)
                elseif is_on("vehicle_lab_cannons")and cannon and cannon.vehicle==context.vehicle
                    and cannon.status=="WAITING_TIMING"then
                    set_result(key,false,"cannon-timing","PENDING",cannon.reason)
                elseif is_on("vehicle_lab_cannons") and cannon and cannon.vehicle==context.vehicle
                    and cannon.status=="BLOCKED" then
                    set_result(key,false,"native-cannon-readback","FAILED",cannon.reason)
                elseif is_on("vehicle_lab_cannons") and cannon and cannon.vehicle==context.vehicle
                    and cannon.online_override_unverified then
                    set_result(key,false,cannon.status=='BALANCE_AND_PROFILE_APPLIED' and 'owned-cannon-balance-and-profile' or 'metadata-only',"PARTIAL",cannon.reason)
                elseif is_on("vehicle_lab_cannons") and cannon and cannon.vehicle==context.vehicle
                    and cannon.status=='BALANCE_AND_PROFILE_APPLIED' then
                    set_result(key,false,'owned-cannon-balance-and-profile','PARTIAL',cannon.reason)
                elseif applied and not is_on("vehicle_lab_cannons") and is_on("vehicle_cannon_range") then
                    set_result(key, true, "owned-cannon-range", "APPLIED", "Range only; cannon restoration is off.")
                elseif applied then
                    set_result(key, true, "owned-cannon-fields", "APPLIED")
                else
                    set_result(key, false, "pending", "PENDING", context_reason())
                end
            end
        end
        controller.pending_reason = #pending > 0 and table.concat(pending, "; ") or "none"
        controller.last_finalize_ms = now_ms()
        return #pending == 0
    end

    function VehicleMods.controller_snapshot()
        local controller = VehicleMods.state.controller
        local result = controller_copy(controller.context)
        result.desired = controller_copy(controller.desired)
        result.effective = controller_copy(controller.effective)
        result.backend = controller_copy(controller.backend)
        result.status = controller_copy(controller.status)
        result.pending_reason = controller.pending_reason or "none"
        result.session_generation = controller.session_generation or 0
        result.cannon_profile=controller_copy(VehicleLab.state.native_cannon_observation)
        result.cannon_timing=VehicleLab.cannon_timing_snapshot()
        local instant = VehicleMods.instant_lock_state()
        result.target_registration = { discovered_peds=VehicleMods.state.target_rendered_peds,
            discovered_vehicles=VehicleMods.state.target_rendered_vehicles,
            eligible=VehicleMods.state.target_requested_count or 0, registered=VehicleMods.state.target_registered_count or 0,
            cleanup_pending=VehicleMods.state.target_cleanup_pending or 0,
            registered_kind="tracked leases including pending cleanup",
            reconciled=VehicleMods.state.target_last_reconcile_ok == true,
            scan_ms=VehicleMods.state.target_scan_last_ms }
        local mounted=VehicleMods.state.mounted_targeting
        result.target_registration.mounted_provider_applied=mounted and mounted.applied==true or false
        result.target_registration.mounted_restore_pending=VehicleMods.mounted_targets_pending()
        result.instant_lock = {
            target=instant.target, target_address=instant.target_address, stage=instant.stage,
            requested = is_on("vehicle_instant_lockon"),
            backend = instant.backend or "none", status = instant.status, reason = instant.reason,
            checkbox_readback = instant.write_readback == true,
            ammo_delay_readback = instant.delay_readback == true, ammo_delay_error = instant.delay_error,
            callback_submitted_ms = instant.submitted_ms,
            dispatch_attempts=instant.dispatch_attempts or 0,retry_due_ms=instant.retry_due_ms,
            helper_redispatches=instant.rearm_count or 0,helper_redispatch_pending=instant.pending_rearm~=nil,
            mounted_weapon_read=VehicleLab.state.mounted_weapon_status,
            observed_acquisition_ms = instant.observed_ms, -- compatibility alias, see metric_kind
            sampled_transition_interval_ms = instant.observed_ms,
            metric_kind = "sampled_transition_interval",
            sample_ms = instant.previous_sample,
            target_registered = instant.target_registered == true,
            owned = instant.owned == true, yielded = instant.yielded == true,
            context = controller_copy(instant.context),
            behavior_verified = false,
        }
        return result
    end

    local function target_pointer_handle(pointer)
        if pointer == nil or not (GTA and type(GTA.PointerToHandle) == "function") then return 0 end
        local address_ok,address=pcall(function() return pointer:GetAddress() end)
        if not address_ok or not vehicle_lab_plausible_pointer(address) then return 0 end
        local ok, handle = pcall(GTA.PointerToHandle, pointer)
        handle=ok and tonumber(handle) or 0
        if handle==0 or not entity_exists(handle) then return 0 end
        local current_ok,current=pcall(function() return GTA.HandleToPointer(handle):GetAddress() end)
        return current_ok and current==address and handle or 0
    end

    local function pool_pointer_from_handle(handle)
        handle = tonumber(handle) or 0
        if handle == 0 or not (GTA and type(GTA.HandleToPointer) == "function") then return nil end
        local ok, pointer = pcall(GTA.HandleToPointer, handle)
        return ok and pointer or nil
    end

    -- Cherax builds expose either the convenience GetRendered* tables or the
    -- indexed pool contract. Keep both paths: current Enhanced builds can omit the
    -- convenience helpers even though GetC*/Get* and the pool counts are present.
    local function visit_entity_pool(rendered_name, current_name, max_name,
                                     pointer_name, handle_name, options, visitor)
        options = options or {}
        if not PoolMgr then return false, "unavailable", 0, 0 end

        local rendered = PoolMgr[rendered_name]
        if type(rendered) == "function" then
            local ok, entries = pcall(rendered)
            if ok and (type(entries) == "table" or type(entries) == "userdata") then
                local list = {}
                local enumerated = pcall(function()
                    for key, pointer in pairs(entries) do
                        list[#list + 1] = {pointer=pointer,key=key}
                        if #list >= (tonumber(options.cap) or 4096) then break end
                    end
                end)
                if enumerated then
                    local count = #list
                    if count == 0 then return true, "rendered", 0, 0 end
                    local start = math.floor(tonumber(options.start) or 0) % count
                    local budget = math.min(count, tonumber(options.budget) or count)
                    local indexed_needed=false
                    -- Keys may be array indices or entity handles. Authenticate
                    -- only this slice; use indexed live handles if any key cannot
                    -- be paired with its current address. Never assume key format.
                    for offset = 0, budget - 1 do
                        local index = (start + offset) % count
                        local entry = list[index + 1]
                        entry.handle=0
                        if type(entry.key)=="number" and entry.key%1==0 and entity_exists(entry.key) then
                            local ok,address,current=pcall(function()
                                return entry.pointer:GetAddress(),GTA.HandleToPointer(entry.key):GetAddress()
                            end)
                            if ok and vehicle_lab_plausible_pointer(address) and address==current then entry.handle=entry.key end
                        end
                        if entry.handle==0 then
                            if type(PoolMgr[handle_name])=="function" then indexed_needed=true
                            else entry.handle=target_pointer_handle(entry.pointer) end
                        end
                    end
                    if not indexed_needed then
                        for offset=0,budget-1 do
                            local index=(start+offset)%count
                            local entry=list[index+1]
                            local stop,result=visitor(entry.pointer,entry.handle)
                            if stop then return true,"rendered",offset+1,(index+1)%count,result end
                        end
                        return true,"rendered",budget,(start+budget)%count
                    end
                end -- a bad host iterator falls through to the indexed pool
            end
        end

        local pointer_getter = PoolMgr[pointer_name]
        local handle_getter = PoolMgr[handle_name]
        if type(pointer_getter) ~= "function" and type(handle_getter) ~= "function" then
            return false, "unavailable", 0, 0
        end
        local count = 0
        local count_getter = PoolMgr[max_name]
        if type(count_getter) == "function" then
            local ok, value = pcall(count_getter)
            if ok then count = tonumber(value) or 0 end
        end
        if count <= 0 then
            count_getter = PoolMgr[current_name]
            if type(count_getter) == "function" then
                local ok, value = pcall(count_getter)
                if ok then count = tonumber(value) or 0 end
            end
        end
        count = math.max(0, math.min(math.floor(count), tonumber(options.cap) or 4096))
        if count == 0 then return true, "indexed", 0, 0 end

        local start = math.floor(tonumber(options.start) or 0) % count
        local budget = math.max(1, math.min(count, math.floor(tonumber(options.budget) or count)))
        local visited = 0
        for offset = 0, budget - 1 do
            local index = (start + offset) % count
            local pointer, handle
            -- GetPed/GetVehicle return live handles. Prefer them to GetC* pool
            -- pointers, which can be obsolete before PointerToHandle is called.
            if type(handle_getter) == "function" then
                local ok, value = pcall(handle_getter, index)
                if ok and type(value)=="number" and value%1==0 and entity_exists(value) then handle=value end
                if handle then pointer=pool_pointer_from_handle(handle) end
            elseif type(pointer_getter) == "function" then
                local ok, value = pcall(pointer_getter, index)
                if ok then pointer = value end
                if pointer ~= nil then handle = target_pointer_handle(pointer) end
            end
            if pointer == nil and (tonumber(handle) or 0) ~= 0 then
                pointer = pool_pointer_from_handle(handle)
            end
            visited = visited + 1
            local stop, result = visitor(pointer, tonumber(handle) or 0)
            if stop then
                return true, "indexed", visited, (index + 1) % count, result
            end
        end
        return true, "indexed", visited, (start + budget) % count
    end



    local function target_entity_kind(target_class)
        return type(target_class) == "string" and target_class:find("vehicle", 1, true)
            and "vehicle" or "ped"
    end

    local function target_class_enabled(target_class, want_players, want_npcs)
        if target_class == "player_ped" or target_class == "player_vehicle" then return want_players end
        if target_class == "npc_ped" or target_class == "npc_vehicle" then return want_npcs end
        -- A vehicle carrying both categories is never retained by NPC-only mode:
        -- doing so would make a player's vehicle lockable through the NPC toggle.
        if target_class == "mixed_vehicle" then return want_players end
        return false
    end

    local function target_bool(hash,...)
        local ok,value=pcall(Natives.InvokeBool,hash,...)
        if not ok then return nil end
        if value==true or value==1 then return true end
        if value==false or value==0 then return false end
    end

    local function target_identity(handle)
        if cached_entity_handle_released(handle) or not entity_exists(handle) then return nil, "gone" end
        local dead=target_bool(H.IS_ENTITY_DEAD, handle, false)
        if dead==nil then return nil,"unavailable" end
        if dead then return nil, "gone" end
        local ok, address = pcall(function() return GTA.HandleToPointer(handle):GetAddress() end)
        if not ok or not vehicle_lab_plausible_pointer(address) then return nil, "unavailable" end
        return address
    end

    function VehicleMods.ensure_targetable(handle, kind)
        if handle==local_ped() or handle==local_vehicle() or target_identity(handle)==nil then return false end
        local method=kind=="ped" and "IsPed" or kind=="vehicle" and "IsVehicle" or nil
        if not method then return false end
        local ok,value=pcall(function()
            local pointer=GTA.HandleToPointer(handle)
            return pointer[method](pointer)
        end)
        return ok and (value==true or value==1)
    end

    function VehicleMods.set_targetable(handle, kind, enabled)
        local state = VehicleMods.state
        state.target_ownership = state.target_ownership or {}
        local owned = state.target_ownership[handle]
        if owned and (owned.adding or owned.removing) then
            if not enabled then owned.release_requested=true end
            return false -- A native callback cannot erase an in-flight obligation.
        end
        local address, identity_reason = target_identity(handle)
        if not address then
            if identity_reason == "gone" then
                if state.target_ownership[handle]==owned then state.target_ownership[handle]=nil end
                return enabled ~= true
            end
            return false
        end
        local pid = local_player_id()
        if enabled then
            if type(pid)~="number" or pid%1~=0 or pid<0 or pid>31 then return false end
            if not VehicleMods.ensure_targetable(handle, kind) then return false end
            if kind~="vehicle" and kind~="ped" then return false end
            if owned and owned.address~=address then
                state.target_ownership[handle]=nil;owned=nil -- Proven replacement, no old removal into it.
            end
            if owned and (owned.pid~=pid or owned.kind~=kind or owned.release_requested) then
                if not VehicleMods.set_targetable(handle,owned.kind,false) then return false end
                owned=nil
            end
            if target_identity(handle)~=address or local_player_id()~=pid then return false end
            -- ADD is a side effect even when the bridge throws afterward.
            local lease=owned or {address=address,pid=pid,kind=kind}
            state.target_ownership[handle]=lease;lease.adding=true
            local ok,result=pcall(invoke_void,H.ADD_PLAYER_TARGETABLE_ENTITY,pid,handle)
            lease.adding=false
            if state.target_ownership[handle]~=lease then return false end
            if not ok or result~=true then lease.uncertain=true;return false end
            lease.uncertain=false
            if lease.release_requested or local_player_id()~=pid or target_identity(handle)~=address then
                lease.release_requested=true
                VehicleMods.set_targetable(handle,kind,false)
                return false
            end
            return true
        end
        if not owned then return true end
        if owned.address~=address then
            if state.target_ownership[handle]==owned then state.target_ownership[handle]=nil end
            return true
        end
        owned.removing=true
        local ok,result=pcall(invoke_void,H.REMOVE_PLAYER_TARGETABLE_ENTITY,owned.pid,handle)
        owned.removing=false
        if not ok or result~=true then return false end
        if state.target_ownership[handle]==owned then state.target_ownership[handle]=nil end
        return true
    end

    function VehicleMods.target_lease_count()
        local state,seen,count=VehicleMods.state,{},0
        for handle in pairs(state.target_entities) do seen[handle]=true;count=count+1 end
        for handle in pairs(state.target_ownership or {}) do
            if not seen[handle] then count=count+1 end
        end
        return count
    end

    function VehicleMods.apply_targetable_set(wanted_peds, wanted_vehicles)
        local state = VehicleMods.state
        state.target_last_seen = state.target_last_seen or {}
        -- 192 is our bounded registry policy, not a claimed native limit. Sort
        -- within categories and round-robin them before reconciling existing leases.
        -- Player vehicles/mixed occupants share one category, never NPC-only.
        local buckets = { {}, {}, {}, {} }
        local requested, selected = 0, {}
        local function collect(wanted)
            for handle, class in pairs(wanted) do
                local group = class == "player_vehicle" or class == "mixed_vehicle"
                local index = group and 1 or class == "player_ped" and 2
                    or class == "npc_vehicle" and 3 or 4
                buckets[index][#buckets[index] + 1] = { handle=handle, class=class }
                requested = requested + 1
            end
        end
        collect(wanted_peds); collect(wanted_vehicles)
        for _, bucket in ipairs(buckets) do
            table.sort(bucket, function(a,b) return a.handle < b.handle end)
        end
        local order, cursor = {}, 1
        while #order < 192 do
            local added = false
            for _, bucket in ipairs(buckets) do
                local item = bucket[cursor]
                if item and #order < 192 then
                    order[#order+1]=item; selected[item.handle]=item.class; added=true
                end
            end
            if not added then break end
            cursor = cursor + 1
        end
        local function clear(handle)
            state.target_entities[handle], state.target_peds[handle], state.target_vehicles[handle] = nil,nil,nil
            if not selected[handle] then state.target_last_seen[handle] = nil end
        end
        local count, registered, debt, failed = 0, 0, 0, false
        for handle, class in pairs(state.target_entities) do
            if selected[handle] ~= class then
                if VehicleMods.set_targetable(handle, target_entity_kind(class), false) then clear(handle)
                else debt=debt+1 end
            end
        end
        for _ in pairs(state.target_entities) do count=count+1 end
        for _, item in ipairs(order) do
            local handle, class = item.handle, item.class
            local existing = state.target_entities[handle]
            if existing == class or (existing == nil and count < 192) then
                local kind = target_entity_kind(class)
                if VehicleMods.set_targetable(handle, kind, true) then
                    if not existing then count=count+1 end
                    state.target_entities[handle]=class
                    if kind == "ped" then state.target_peds[handle]=class
                    else state.target_vehicles[handle]=class end
                    registered=registered+1
                elseif not (state.target_ownership or {})[handle] then
                    failed=true
                    if existing then count=count-1 end
                    clear(handle)
                else
                    -- A failed read/re-registration must not discard a live lease.
                    debt=debt+1
                end
            end
        end
        state.target_cleanup_pending = debt
        state.target_registered_count = VehicleMods.target_lease_count()
        state.target_requested_count = requested
        state.target_last_reconcile_ok = (requested == 0 or registered > 0) and debt == 0 and not failed
        return state.target_last_reconcile_ok, registered, requested
    end

    function VehicleMods.prune_target_filters(want_players, want_npcs)
        local state = VehicleMods.state
        state.target_last_reconcile_ok=false
        state.target_scan_last_ms=0
        local debt=0
        for handle, target_class in pairs(state.target_entities) do
            if not target_class_enabled(target_class, want_players, want_npcs) then
                if VehicleMods.set_targetable(handle, target_entity_kind(target_class), false) then
                    state.target_entities[handle] = nil
                    state.target_peds[handle] = nil
                    state.target_vehicles[handle] = nil
                else debt=debt+1 end
            end
        end
        state.target_cleanup_pending=debt
        state.target_registered_count=VehicleMods.target_lease_count()
    end

    function VehicleMods.refresh_lockable_targets_legacy_vehicle_scan(now, own_vehicle, want_players, want_npcs)
        local state = VehicleMods.state
        if want_players == nil then want_players = is_on("vehicle_lock_players") end
        if want_npcs == nil then want_npcs = is_on("vehicle_lock_npcs") end
        local signature = (want_players and "1" or "0") .. (want_npcs and "1" or "0")
        if state.target_filter_signature ~= signature then
            state.target_filter_signature = signature
            state.last_target_vehicle_scan_ms = -100000
            VehicleMods.prune_target_filters(want_players, want_npcs)
        end
        if not want_players and not want_npcs then
            VehicleMods.restore_lockable_targets()
            state.target_rendered_peds = 0
            state.target_rendered_vehicles = 0
            state.target_eligible_peds = 0
            state.target_eligible_vehicles = 0
            state.target_player_diagnostics = {}
            state.target_scan_error = "disabled (filter=00)"
            return
        end
        -- Recheck players on foot and moving NPCs more promptly after their
        -- vehicle/ped state changes. The per-scan entity budgets remain bounded.
        local scan_interval = math.max(100, math.min(500,
            tonumber(state.target_vehicle_scan_interval_ms) or 150))

        if now - state.last_target_vehicle_scan_ms
            < scan_interval then
            return state.target_last_reconcile_ok == true
                and (state.target_cleanup_pending or 0) == 0
        end
        state.last_target_vehicle_scan_ms = now
        -- Explicit session-player handles work even when rendered pool helpers
        -- are unavailable. NPC/vehicle scans have their own fallbacks below.
        local wanted_peds, wanted_vehicles = {}, {}
        state.target_last_seen = state.target_last_seen or {}
        -- A candidate remains stable between bounded scan slices. Revalidate the
        -- live address/death state before retaining any registration.
        for handle, class in pairs(state.target_entities) do
            local lease = (state.target_ownership or {})[handle]
            local address = target_identity(handle)
            if lease and address == lease.address
                and now - (state.target_last_seen[handle] or 0) <= 8000
                and target_class_enabled(class, want_players, want_npcs)
                and VehicleMods.ensure_targetable(handle, target_entity_kind(class)) then
                if target_entity_kind(class) == "vehicle" then wanted_vehicles[handle] = class
                else wanted_peds[handle] = class end
            end
        end
        local player_rows_by_ped = {}
        local own_ped = local_ped()
        local rendered_peds, rendered_vehicles = 0, 0
        local scan_errors = {}
        local ped_read_failed, vehicle_read_failed = false, false

        local function player_row(ped_ptr, ped_handle)
            local row = player_rows_by_ped[ped_handle]
            if row then return row end
            local player_id = invoke_int(H.NETWORK_GET_PLAYER_INDEX_FROM_PED, ped_handle)
            local vehicle_handle = 0
            local ok, vehicle_ptr = pcall(function() return ped_ptr.CurVehicle end)
            if ok and vehicle_ptr then vehicle_handle = target_pointer_handle(vehicle_ptr) end
            row = {
                player_id = player_id,
                ped = ped_handle,
                vehicle = vehicle_handle,
                on_foot = vehicle_handle == 0,
                registered = false,
            }
            player_rows_by_ped[ped_handle] = row
            return row
        end

        -- Explicitly enumerate session players before the render-pool pass. Some
        -- Cherax builds omit player peds from GetRenderedPeds while they are inside
        -- a streamed vehicle, which made Lock Onto Players appear intermittent.
        if want_players and type(player_available) == "function" and type(player_ped) == "function" then
            for player_id = 0, 31 do
                if player_id ~= local_player_id() and player_available(player_id) then
                    local ped_handle = tonumber(player_ped(player_id)) or 0
                    if ped_handle ~= 0 and ped_handle ~= own_ped and entity_exists(ped_handle)
                        and invoke_int(H.GET_ENTITY_HEALTH, ped_handle) > 0
                        and target_bool(H.IS_PED_A_PLAYER, ped_handle)==true
                        and invoke_int(H.NETWORK_GET_PLAYER_INDEX_FROM_PED,ped_handle)==player_id
                        and player_ped(player_id)==ped_handle then
                        local row = player_row(nil, ped_handle)
                        row.player_id = player_id
                        local vehicle_handle = invoke_int(H.GET_VEHICLE_PED_IS_IN, ped_handle, false)
                        if vehicle_handle ~= 0 and vehicle_handle ~= own_vehicle and entity_exists(vehicle_handle) then
                            row.vehicle = vehicle_handle
                            row.on_foot = false
                            wanted_peds[ped_handle] = nil
                            state.target_last_seen[ped_handle] = nil
                            wanted_vehicles[vehicle_handle] = "player_vehicle"
                            state.target_last_seen[vehicle_handle] = now
                        else
                            row.vehicle = 0
                            row.on_foot = true
                            wanted_peds[ped_handle] = "player_ped"
                            state.target_last_seen[ped_handle] = now
                        end
                    end
                end
            end
        end

        -- Ped target eligibility is distinct from vehicle eligibility. The indexed
        -- fallback covers builds where GetRenderedPeds is not exported.
        local peds_ok, peds_source, _, ped_cursor = visit_entity_pool(
            "GetRenderedPeds", "GetCurrentPedCount", "GetMaxPedCount",
            "GetCPed", "GetPed", { cap = 1024, budget = 32, start = state.target_ped_cursor }, function(ped_ptr, handle)
                rendered_peds = rendered_peds + 1
                local ok, class = pcall(function()
                    if handle == 0 or handle == own_ped or not entity_exists(handle) then return nil end
                    local health = Natives.InvokeInt(H.GET_ENTITY_HEALTH, handle)
                    local player = target_bool(H.IS_PED_A_PLAYER, handle)
                    -- Player identity does not depend on the current ped model.
                    -- Keep the human-only restriction for NPC targets.
                    local human = player == true or target_bool(H.IS_PED_HUMAN, handle)
                    local riding = target_bool(H.IS_PED_IN_ANY_VEHICLE, handle, false)
                    if type(health) ~= "number" or type(player) ~= "boolean"
                        or type(human) ~= "boolean" or type(riding) ~= "boolean" then error("ped state unreadable") end
                    if player then player_row(ped_ptr, handle) end
                    if health > 0 and human and not riding
                        and ((player and want_players) or (not player and want_npcs)) then
                        return player and "player_ped" or "npc_ped"
                    end
                end)
                if ok then
                    wanted_peds[handle] = class
                    state.target_last_seen[handle] = class and now or nil
                else ped_read_failed=true end -- failed reads retain only the original bounded seed
                return false
            end)
        if ped_read_failed then scan_errors[#scan_errors+1]="ped state unreadable" end
        state.target_ped_cursor = ped_cursor or 0
        if not peds_ok then
            scan_errors[#scan_errors + 1] = "ped pool unavailable"

        end

        -- Vehicle eligibility examines every rendered occupant, not just the
        -- driver. This covers traffic, mission vehicles, bikes, aircraft and boats.
        local vehicles_ok, vehicles_source, _, vehicle_cursor = visit_entity_pool(
            "GetRenderedVehicles", "GetCurrentVehicleCount", "GetMaxVehicleCount",
            "GetCVehicle", "GetVehicle", { cap = 2048, budget = 64, start = state.target_vehicle_cursor }, function(vehicle_ptr, handle)
                rendered_vehicles = rendered_vehicles + 1
                local observed, class = pcall(function()
                local function boolean(hash, ...)
                    local value=target_bool(hash,...)
                    if type(value)~="boolean" then error("occupancy boolean unreadable") end
                    return value
                end
                local function integer(hash, ...)
                    local value=Natives.InvokeInt(hash,...)
                    if type(value)~="number" or value~=value or value%1~=0 then error("occupancy integer unreadable") end
                    return value
                end
                if handle ~= 0 and handle ~= own_vehicle and entity_exists(handle)
                    and not boolean(H.IS_ENTITY_DEAD, handle, false) then
                    local has_player, has_npc = false, false
                    local function inspect_occupant_handle(occupant_handle)
                        occupant_handle = tonumber(occupant_handle) or 0
                        if occupant_handle == 0 or not entity_exists(occupant_handle)
                            or integer(H.GET_ENTITY_HEALTH, occupant_handle) <= 0 then
                            return
                        end
                        if boolean(H.IS_PED_A_PLAYER, occupant_handle) then
                            has_player = true
                            local row = player_row(nil, occupant_handle)
                            row.vehicle = handle
                            row.on_foot = false
                        elseif boolean(H.IS_PED_HUMAN, occupant_handle) then
                            has_npc = true
                        end
                    end
                    local passenger_count = math.max(0, math.min(31,
                        integer(H.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS, handle)))
                    for seat = -1, passenger_count - 1 do
                        inspect_occupant_handle(integer(H.GET_PED_IN_VEHICLE_SEAT, handle, seat, false))
                        if (want_players and not want_npcs and has_player)
                            or (want_players and want_npcs and has_player and has_npc) then
                            break
                        end
                    end
                    if want_players and has_player then
                        return want_npcs and has_npc
                            and "mixed_vehicle" or "player_vehicle"
                    elseif want_npcs and has_npc and not has_player then
                        -- NPC-only mode intentionally excludes mixed-occupant
                        -- vehicles so it cannot indirectly expose a player target.
                        return "npc_vehicle"
                    end
                end
                end)
                if observed then
                    wanted_vehicles[handle] = class
                    state.target_last_seen[handle] = class and now or nil
                else vehicle_read_failed=true end
                return false
            end)
        if vehicle_read_failed then scan_errors[#scan_errors+1]="vehicle occupancy unreadable" end
        state.target_vehicle_cursor = vehicle_cursor or 0
        if not vehicles_ok then
            scan_errors[#scan_errors + 1] = "vehicle pool unavailable"

        end
        local targets_ok,
        registered_targets,
        requested_targets =
            VehicleMods.apply_targetable_set(
                wanted_peds,
                wanted_vehicles
            )
        -- Zero eligible targets is successful only when enumeration itself
        -- completed successfully. A failed empty scan must not be reported as
        -- an active targeting backend.
        targets_ok = targets_ok and (registered_targets > 0
            or (requested_targets == 0 and #scan_errors == 0))
        local eligible_peds, eligible_vehicles = 0, 0
        for _ in pairs(wanted_peds) do eligible_peds = eligible_peds + 1 end
        for _ in pairs(wanted_vehicles) do eligible_vehicles = eligible_vehicles + 1 end
        local player_rows = {}
        for _, row in pairs(player_rows_by_ped) do
            local ped_class = state.target_entities[row.ped]
            local vehicle_class = state.target_entities[row.vehicle]
            row.registered = row.on_foot and ped_class == "player_ped"
                or (not row.on_foot and row.vehicle ~= 0
                    and (vehicle_class == "player_vehicle" or vehicle_class == "mixed_vehicle"))
            player_rows[#player_rows + 1] = row
        end
        table.sort(player_rows, function(a, b)
            if a.player_id == b.player_id then return a.ped < b.ped end
            return a.player_id < b.player_id
        end)
        state.target_rendered_peds = rendered_peds
        state.target_rendered_vehicles = rendered_vehicles
        state.target_eligible_peds = eligible_peds
        state.target_eligible_vehicles = eligible_vehicles
        state.target_player_diagnostics = player_rows
        state.target_scan_last_ms = state.last_target_vehicle_scan_ms
        local scan_status =
            #scan_errors == 0
            and (
                "ok (peds="
                .. tostring(peds_source)
                .. ", vehicles="
                .. tostring(vehicles_source)
                .. ")"
            )
            or table.concat(
                scan_errors,
                "; "
            )

        state.target_scan_error =
            ("%s; registered=%d/%d"):format(
                scan_status,
                registered_targets,
                requested_targets
            )

        state.target_last_reconcile_ok = targets_ok == true
        return targets_ok
    end


    function VehicleMods.mounted_targets_pending()return false end
    function VehicleMods.restore_mounted_targets()return true end
    function VehicleMods.refresh_lockable_targets(now, own_vehicle)
        return VehicleMods.refresh_lockable_targets_legacy_vehicle_scan(now,own_vehicle,
            is_on("vehicle_lock_players"),is_on("vehicle_lock_npcs"))
    end

    function VehicleMods.restore_lockable_targets(registrations_only)
        local state = VehicleMods.state
        local restored, pending = registrations_only==true or VehicleMods.restore_mounted_targets(), {}
        for handle in pairs(state.target_entities) do pending[handle] = true end
        for handle in pairs(state.target_ownership or {}) do pending[handle] = true end
        for handle in pairs(pending) do
            local owned = state.target_ownership and state.target_ownership[handle]
            local kind = owned and owned.kind or target_entity_kind(state.target_entities[handle])
            local released = cached_entity_handle_released(handle) or not entity_exists(handle)
                or VehicleMods.set_targetable(handle, kind, false)
            if released then
                state.target_entities[handle], state.target_peds[handle], state.target_vehicles[handle] = nil, nil, nil
                if state.target_ownership then state.target_ownership[handle] = nil end
            else restored = false end
        end
        state.target_registered_count=VehicleMods.target_lease_count()
        state.target_requested_count=0
        state.target_cleanup_pending=state.target_registered_count
        state.target_last_reconcile_ok=false -- no active full scan after cleanup
        state.target_scan_last_ms=0
        state.last_target_vehicle_scan_ms=-100000
        state.target_last_seen={}
        state.target_rendered_peds,state.target_rendered_vehicles=0,0
        state.target_eligible_peds,state.target_eligible_vehicles=0,0
        state.target_player_diagnostics={}
        return restored
    end

    function VehicleMods.refresh_lockable_vehicles(now, own_vehicle)
        return VehicleMods.refresh_lockable_targets(now, own_vehicle)
    end

    function VehicleMods.restore_lockable_vehicles()
        return VehicleMods.restore_lockable_targets()
    end

    function VehicleMods.combat_features_active()
        -- A newly enabled frame owner must not be cleared while the slower
        -- builtin-state sampler is still waiting for its next maintenance tick.
        return VehicleMods.state.combat_active == true or VehicleMods.projectile_changes_requested()
    end

    -- Single backend: the documented per-frame torque native. HandleToPointer
    -- returns CPhysical, NOT CVehicle, so it cannot authorize CheatPowerIncrease
    -- member access. No pointer-backed field is read or written by this feature.
    -- The native expires when it is no longer renewed; writing 1.0 on release
    -- would instead overwrite another script's frame request. There is no
    -- supported native getter/original-state snapshot for this transient request.
    local POWER_NATIVE = {
        playing = 0x5E9564D8246B909A,
        vehicle_type = 0x6AC7003FA6E5575E,
        dead = 0x5F9532F3B5CC2551,
        driver = 0xBB40DD2270B65366,
        networked = 0xC7827959479DCC78,
        control = 0x01BF60A500E28887,
        transition = 0x520F3282A53D26B7,
        model = 0x9F47B058362C84B5,
    }

    local function power_status(status, detail)
        local state = VehicleMods.state
        local signature = status .. ":" .. tostring(detail)
        state.power_status, state.power_detail = status, detail
        if state.power_log_signature == signature then return end
        state.power_log_signature = signature
        log_info("Engine Power: " .. status .. " (" .. tostring(detail) .. ")")
    end

    local function power_number(value, maximum)
        return type(value) == "number" and value == value and value > 0
            and value < (maximum or math.huge) and value % 1 == 0
    end

    local function power_native(kind, hash, ...)
        local callable = Natives and Natives[kind]
        if type(callable) ~= "function" then return nil end
        local ok, value = pcall(callable, hash, ...)
        if not ok then return nil end
        return value
    end

    local function power_address(getter, handle)
        if not (GTA and type(GTA[getter]) == "function") then return nil end
        local ok, pointer = pcall(GTA[getter], handle)
        if not ok or (type(pointer) ~= "userdata" and type(pointer) ~= "table") then return nil end
        local address_ok, address = pcall(function() return pointer:GetAddress() end)
        if not address_ok or not power_number(address) then return nil end
        return address
    end

    local function power_context(vehicle)
        if not started or not bound or runtime_writes_suspended then return nil, "runtime unavailable" end
        local ped, pid = local_ped(), local_player_id()
        local generation = VehicleMods.state.controller.session_generation or 0
        if not power_number(vehicle, 2147483647) or not power_number(ped, 2147483647)
            or type(pid) ~= "number" or pid < 0 or pid > 31 or pid % 1 ~= 0
            or local_vehicle() ~= vehicle then return nil, "waiting for local vehicle" end
        if power_native("InvokeBool", POWER_NATIVE.playing, pid) ~= true
            or power_native("InvokeBool", POWER_NATIVE.transition) ~= false then
            return nil, "player unavailable or session transition"
        end
        -- Only current host-owned addresses are compared. Pointer wrappers are
        -- discarded immediately; none are retained across frames or dereferenced
        -- as a vehicle class. A failed/malformed conversion never reaches a write.
        local ped_address = power_address("GetLocalPed")
        local address = power_address("GetLocalVehicle")
        if not ped_address or not address
            or power_address("HandleToPointer", ped) ~= ped_address
            or power_address("HandleToPointer", vehicle) ~= address then
            return nil, "current entity identity unavailable"
        end
        if not entity_exists(ped) or not entity_exists(vehicle)
            or power_native("InvokeBool", POWER_NATIVE.vehicle_type, vehicle) ~= true
            or power_native("InvokeBool", POWER_NATIVE.dead, ped, false) ~= false
            or power_native("InvokeBool", POWER_NATIVE.dead, vehicle, false) ~= false
            or power_native("InvokeInt", POWER_NATIVE.driver, vehicle, -1, false) ~= ped then
            return nil, "live local driver required"
        end
        local networked = power_native("InvokeBool", POWER_NATIVE.networked, vehicle)
        if networked == nil or (networked ~= false and networked ~= true)
            or (networked and power_native("InvokeBool", POWER_NATIVE.control, vehicle) ~= true) then
            return nil, "vehicle control unavailable"
        end
        local model = power_native("InvokeInt", POWER_NATIVE.model, vehicle)
        if type(model) ~= "number" or model == 0 or model ~= model then return nil, "vehicle model unavailable" end
        if local_vehicle() ~= vehicle or local_ped() ~= ped or local_player_id() ~= pid
            or (VehicleMods.state.controller.session_generation or 0) ~= generation then
            return nil, "context changed during validation"
        end
        return { vehicle = vehicle, ped = ped, pid = pid, address = address,
            ped_address = ped_address, model = model,
            generation = generation }
    end

    local function same_power_context(a, b)
        return a and b and a.vehicle==b.vehicle and a.address==b.address and a.model==b.model
            and a.ped==b.ped and a.ped_address==b.ped_address and a.pid==b.pid and a.generation==b.generation
    end

    local function driving_input_available(pid)
        local gui=deps.GUI
        if gui and type(gui.IsOpen)=="function" then
            local ok,open=pcall(gui.IsOpen)
            if not ok or open then return false end
        end
        return power_native("InvokeBool",0xB0034A223497FFCB)==false -- pause
            and power_native("InvokeBool",0xB118AF58B5F332A1)==false -- chat
            and power_native("InvokeBool",0x991251AFC3981F84)==false -- cutscene
            and power_native("InvokeBool",0x49C32D60007AFA47,pid)==true
    end

    local function finite_number(value)
        return type(value)=="number" and value==value and math.abs(value)<math.huge
    end

    -- Aircraft and transformation vehicles use a mass-scaled impulse integrated
    -- by elapsed game time, once per frame. Cherax exposes no flying-handling
    -- accessor; CheatPowerIncrease does not change CFlyingHandlingData thrust.
    function VehicleMods.aircraft_power_frame(identity, wanted, now)
        local state=VehicleMods.state
        local class=power_native("InvokeInt",0x29439776AAA00A62,identity.vehicle)
        local special=(identity.model & 0xFFFFFFFF)==(Utils.Joaat("deluxo") & 0xFFFFFFFF)
            or (identity.model & 0xFFFFFFFF)==(Utils.Joaat("oppressor") & 0xFFFFFFFF)
            or (identity.model & 0xFFFFFFFF)==(Utils.Joaat("oppressor2") & 0xFFFFFFFF)
        if class~=15 and class~=16 and not special then
            state.power_assist_clock=nil; return true
        end
        local frame=power_native("InvokeInt",0xFC8202EFC642E6F2)
        local clock=state.power_assist_clock
        state.power_backend="frame-torque-native + input-thrust-assistance"
        if not finite_number(now) or not finite_number(frame) then state.power_assist_clock=nil;return false end
        if clock and clock.frame==frame then return true end
        state.power_assist_clock={identity=identity,frame=frame,now=now}
        if not clock or not same_power_context(clock.identity,identity) then return true end
        local dt=(now-clock.now)/1000
        if dt<=0 or dt>0.1 or wanted<=1.0 or not driving_input_available(identity.pid) then return true end
        local control=(class==15 or class==16) and 87 or 71
        local throttle=power_native("InvokeFloat",0xEC3C9B8D5327B563,0,control) -- GET_CONTROL_NORMAL
        local speed=power_native("InvokeFloat",0xD5037BA82E12416F,identity.vehicle) -- GET_ENTITY_SPEED
        if not finite_number(throttle) or throttle<=0 or not finite_number(speed) or speed<0 then return false end
        -- Taper added acceleration above 200m/s; never impose a target velocity.
        local impulse=math.min(40.0,(wanted-1.0)*2.0)*dt*math.min(1.0,throttle)
            * math.max(0.0,math.min(1.0,(250.0-speed)/50.0))
        if impulse<=0 or not is_on("vehicle_engine_power")
            or not same_power_context(identity,power_context(identity.vehicle)) then return false end
        return invoke_void(0xC5F68BE9613E2D18,identity.vehicle,1,
            0.0,impulse,0.0,0.0,0.0,0.0,0,true,true,true,false,true)==true
    end

    function VehicleMods.restore_power(reason)
        local state = VehicleMods.state
        local was_active = state.power_vehicle ~= 0 or state.power_pending_release
        state.power_vehicle, state.power_identity, state.power_pending_release = 0, nil, false
        state.power_accepted, state.power_readback_verified = false, false
        state.power_assist_clock, state.power_backend = nil, "frame-torque-native"
        if was_active then power_status("RELEASED", reason or "frame request stopped; no restore write") end
        return true
    end

    function VehicleMods.apply_power(vehicle, now)
        local state = VehicleMods.state
        if state.power_pending_release then
            VehicleMods.restore_power("queued release serviced")
            return false
        end
        local identity, reason = power_context(vehicle)
        if not identity then
            VehicleMods.restore_power(reason)
            power_status("WAITING", reason)
            return false
        end
        local wanted = slider_float("vehicle_engine_power_multiplier", 1.0)
        if type(wanted) ~= "number" or wanted ~= wanted or math.abs(wanted) == math.huge then
            VehicleMods.restore_power("non-finite multiplier")
            power_status("REJECTED", "multiplier must be finite")
            return false
        end
        wanted = math.max(1.0, math.min(50.0, wanted))
        local requested_power=wanted
        local fresh = power_context(vehicle)
        if not fresh or not is_on("vehicle_engine_power") or runtime_writes_suspended
            or fresh.address ~= identity.address or fresh.ped_address ~= identity.ped_address
            or fresh.model ~= identity.model or fresh.pid ~= identity.pid or fresh.ped ~= identity.ped
            or fresh.generation ~= identity.generation then
            VehicleMods.restore_power("context changed before invocation")
            return false
        end
        local ok, returned = pcall(Natives.InvokeVoid, H.SET_VEHICLE_CHEAT_POWER_INCREASE, vehicle, wanted)
        if not ok or returned == false then
            VehicleMods.restore_power("native bridge rejected invocation")
            power_status("FAILED", "native bridge rejected; no second backend attempted")
            return false
        end
        state.power_vehicle, state.power_identity = vehicle, identity
        state.power_accepted, state.power_readback_verified = true, false
        state.power_requested_value = requested_power
        state.power_effective_value = wanted
        state.power_backend="frame-torque-native"
        VehicleMods.aircraft_power_frame(identity,wanted,tonumber(now) or now_ms())
        power_status("INVOCATION ACCEPTED", string.format("%.2fx; %s; gameplay unverified", requested_power,state.power_backend))
        return true
    end

    -- The paired drift-tyre property keeps its real original state. Grip
    -- assistance projects observed horizontal velocity, without handling memory.
    local TRACTION_NATIVE={get=0x2F5A72430E78C8D3,set=0x5AC79C98C5C17F05}
    local function traction_model(value)
        if type(value)~="number"or value~=value or value%1~=0 then return nil end
        value=value%4294967296
        return value~=0 and value or nil
    end
    local function traction_physical(handle)
        local ok,id=pcall(function()
            local entity=GTA.HandleToPointer(handle)
            if not entity then return end
            local address=entity:GetAddress()
            local info=entity.ModelInfo
            local model=info and traction_model(info.Model)
            if power_number(address)and model then return{address=address,model=model}end
        end)
        return ok and id or nil
    end
    local function traction_identity(owner)
        if owner.generation~=(VehicleMods.state.controller.session_generation or 0)then return "gone"end
        if cached_entity_handle_released(owner.vehicle)or not entity_exists(owner.vehicle)then return "gone"end
        local first=traction_physical(owner.vehicle)
        if not first then return "pending"end
        if first.address~=owner.address or first.model~=traction_model(owner.model)then return "gone"end
        local networked=power_native("InvokeBool",POWER_NATIVE.networked,owner.vehicle)
        if type(networked)~="boolean"or(networked and power_native("InvokeBool",POWER_NATIVE.control,owner.vehicle)~=true)then return "pending"end
        -- Authority reads may change the allocation. Never restore a captured
        -- property into the later owner of an otherwise matching GUID.
        local final=traction_physical(owner.vehicle)
        if not final then return "pending"end
        if final.address~=owner.address or final.model~=traction_model(owner.model)
            or owner.generation~=(VehicleMods.state.controller.session_generation or 0)then return "gone"end
        -- A physical getter can invalidate the earlier control observation.
        -- Conversely, recheck allocation after that renewed authority read.
        networked=power_native("InvokeBool",POWER_NATIVE.networked,owner.vehicle)
        if type(networked)~="boolean"or(networked and power_native("InvokeBool",POWER_NATIVE.control,owner.vehicle)~=true)then return "pending"end
        local closed=traction_physical(owner.vehicle)
        if not closed then return "pending"end
        if closed.address~=owner.address or closed.model~=traction_model(owner.model)
            or owner.generation~=(VehicleMods.state.controller.session_generation or 0)then return "gone"end
        networked=power_native("InvokeBool",POWER_NATIVE.networked,owner.vehicle)
        if type(networked)~="boolean"or(networked and power_native("InvokeBool",POWER_NATIVE.control,owner.vehicle)~=true)then return "pending"end
        local last=traction_physical(owner.vehicle)
        if not last then return "pending"end
        if last.address~=owner.address or last.model~=traction_model(owner.model)
            or owner.generation~=(VehicleMods.state.controller.session_generation or 0)then return "gone"end
        return true
    end
    local function traction_contact(vehicle,ground_angle)
        -- A wheel-contact hint alone must never authorize an airborne assist.
        return power_native("InvokeBool",0x886E37EC497200B6,vehicle)==false
            and power_native("InvokeBool",0xCFB0A0D8EDD145A3,vehicle)==false
            and power_native("InvokeBool",0x5333F526F6AB19AA,vehicle,ground_angle)==true
            and power_native("InvokeBool",0xB104CD1BABF302E2,vehicle)==true
    end
    local function traction_steering(identity)
        -- Cherax exposes typed current-CVehicle properties. The held-steering
        -- capture and underlying GTA engine contract are radians-compatible;
        -- no offset, custom FiveM native or property write is used here.
        local function current_car()
            if not started or not bound or runtime_writes_suspended
                or not is_on("vehicle_disable_burnout")
                or (VehicleMods.state.controller.session_generation or 0)~=identity.generation
                or local_vehicle()~=identity.vehicle or local_ped()~=identity.ped
                or local_player_id()~=identity.pid then return end
            local car=GTA.GetLocalVehicle()
            if not car or car:GetAddress()~=identity.address then return end
            local model=car.ModelInfo
            if not model or traction_model(model.Model)~=traction_model(identity.model)
                or (VehicleMods.state.controller.session_generation or 0)~=identity.generation then return end
            return car
        end
        local ok,front,rear=pcall(function()
            local car=current_car();if not car then return end
            local first=car.SteerAngle
            car=current_car();if not car then return end
            local second=car.SecondSteerAngle
            if not current_car()then return end
            return first,second
        end)
        if not ok or not finite_number(front)or not finite_number(rear)
            or math.abs(front)>1.2 or math.abs(rear)>1.2 then return end
        return front,rear
    end
    local function traction_driver_current(identity,grip,drift,ground_angle,physics_current)
        local vehicle=identity.vehicle
        if ground_angle then
            if not driving_input_available(identity.pid)
                or not traction_contact(vehicle,ground_angle)then VehicleMods.state.grip_assist_clock=nil;return false end
        end
        -- All input/contact observations precede the final driver/authority
        -- proof. This prevents a late wheel query authorizing a stale write.
        if not same_power_context(identity,power_context(vehicle))then return false end
        if physics_current and physics_current()~=true then return false end
        local networked=power_native("InvokeBool",POWER_NATIVE.networked,vehicle)
        if type(networked)~="boolean"or(networked and power_native("InvokeBool",POWER_NATIVE.control,vehicle)~=true)
            or power_native("InvokeBool",POWER_NATIVE.transition)~=false
            or power_native("InvokeBool",POWER_NATIVE.playing,identity.pid)~=true
            or power_native("InvokeInt",POWER_NATIVE.driver,vehicle,-1,false)~=identity.ped then return false end
        local car,ped=traction_physical(vehicle),traction_physical(identity.ped)
        if not car or not ped or car.address~=identity.address or car.model~=traction_model(identity.model)
            or ped.address~=identity.ped_address then return false end
        -- The local-ped observation may have changed the seat, authority or
        -- car allocation. Close those observations before handing off a write.
        networked=power_native("InvokeBool",POWER_NATIVE.networked,vehicle)
        if type(networked)~="boolean"or(networked and power_native("InvokeBool",POWER_NATIVE.control,vehicle)~=true)
            or power_native("InvokeInt",POWER_NATIVE.driver,vehicle,-1,false)~=identity.ped then return false end
        car=traction_physical(vehicle)
        if not car or car.address~=identity.address or car.model~=traction_model(identity.model)then return false end
        networked=power_native("InvokeBool",POWER_NATIVE.networked,vehicle)
        if type(networked)~="boolean"or(networked and power_native("InvokeBool",POWER_NATIVE.control,vehicle)~=true)
            or power_native("InvokeInt",POWER_NATIVE.driver,vehicle,-1,false)~=identity.ped then return false end
        -- Finish allocation proof after renewed authority. Only cached local
        -- intent/lifecycle observations follow this final physical snapshot.
        car=traction_physical(vehicle)
        return car and car.address==identity.address and car.model==traction_model(identity.model)
            and ped.address==identity.ped_address and started and bound and not runtime_writes_suspended
            and local_vehicle()==vehicle and local_ped()==identity.ped and local_player_id()==identity.pid
            and (VehicleMods.state.controller.session_generation or 0)==identity.generation
            and grip==is_on("vehicle_disable_burnout")and drift==is_on("vehicle_drift_mode")
    end
    local function traction_vectors(vehicle)
        local vx,vy,vz=vector_components(invoke_vec3(H.GET_ENTITY_VELOCITY,vehicle))
        local fx,fy,fz=vector_components(invoke_vec3(H.GET_ENTITY_FORWARD_VECTOR,vehicle))
        return vx,vy,vz,fx,fy,fz
    end
    local function traction_grip_frame(identity,class)
        local state=VehicleMods.state
        if is_on("vehicle_fly") then state.grip_assist_clock=nil;return true end
        local frame=power_native("InvokeInt",0xFC8202EFC642E6F2)
        local now=now_ms();local clock=state.grip_assist_clock
        if not finite_number(frame)or not finite_number(now)then state.grip_assist_clock=nil;return false end
        if clock and clock.frame==frame and same_power_context(clock.identity,identity)then return true end
        local dt=clock and (now-clock.now)/1000.0 or nil
        if not clock or not same_power_context(clock.identity,identity)or not dt or dt<=0 or dt>0.1 then clock=nil end
        local vehicle=identity.vehicle
        local ground_angle=(class==8 or class==13)and 55.0 or 35.0
        if not traction_contact(vehicle,ground_angle)then
            state.grip_assist_clock=nil;return true
        end
        -- Positive all-wheel, non-airborne/upright/non-water observations
        -- are always required; partial/unknown contact grants no assist.
        local fresh={identity=identity,frame=frame,now=now,direction=clock and clock.direction or nil}
        state.grip_assist_clock=fresh
        local read,vx,vy,vz,fx,fy,fz=pcall(traction_vectors,vehicle)
        if not read or not finite_number(vx)or not finite_number(vy)or not finite_number(vz)
            or not finite_number(fx)or not finite_number(fy)or not finite_number(fz)
            or math.abs(vx)>300 or math.abs(vy)>300 or math.abs(vz)>300 then
            state.grip_assist_clock=nil;return false
        end
        local length=math.sqrt(fx*fx+fy*fy)
        local speed=math.sqrt(vx*vx+vy*vy)
        if length<0.5 or length>1.5 then state.grip_assist_clock=nil;return false end
        if speed<1.0 then fresh.direction=nil;return true end
        local raw_fx,raw_fy=fx,fy
        fx,fy=fx/length,fy/length
        local longitudinal=vx*fx+vy*fy
        local lateral=vx*fy-vy*fx
        -- Travel sign belongs to this exact driver/car/session. Near sideways
        -- retains it. Clearly longitudinal travel can update a real reversal
        -- even when the scheduler did not observe its zero-speed crossing.
        if math.abs(longitudinal)>=speed*(fresh.direction and 0.8 or 0.25)then
            fresh.direction=longitudinal<0 and -1.0 or 1.0
        end
        if not fresh.direction or math.abs(lateral)<0.08 then return true end
        local front,rear=traction_steering(identity)
        if not front then state.grip_assist_clock=nil;return false end
        -- GTA's positive steering is left. This signed travel-space cross
        -- product is positive right, for both forward and reverse motion.
        -- Keep natural turn slip between the chassis and either axle direction;
        -- the 20-degree cap is an explicit assistance policy, not wheel geometry.
        local limit=math.rad(20.0)
        local low=math.max(-limit,math.min(0.0,-front,-rear))
        local high=math.min(limit,math.max(0.0,-front,-rear))
        local angle=math.atan(lateral*fresh.direction,longitudinal*fresh.direction)
        local launch=math.max(0.0,math.min(1.0,(15.0-speed)/10.0))
        local allowance=math.rad(4.0-2.0*launch)
        low,high=low-allowance,high+allowance
        local target=math.max(low,math.min(high,angle))
        if math.abs(angle-target)<0.0001 then return true end
        -- Only dissipate excess lateral slip. Preserve longitudinal travel and
        -- allow natural cornering; never snap the full velocity direction.
        if not dt then return true end
        local lateral_target=math.tan(target)*math.abs(longitudinal)*fresh.direction
        local excess=lateral-lateral_target
        local response=8.0+10.0*launch
        local acceleration=14.0+14.0*launch
        local correction=excess*(1.0-math.exp(-response*dt))
        correction=math.max(-acceleration*dt,math.min(acceleration*dt,correction))
        local x=vx-fy*correction
        local y=vy+fx*correction
        local drift=is_on("vehicle_drift_mode")
        local function physics_current()
            -- Reject a jump, boost, heading or contact change after the sample.
            -- This observation precedes the final captured-allocation proof.
            local ok,cx,cy,cz,cfx,cfy,cfz=pcall(traction_vectors,vehicle)
            local current_front,current_rear=traction_steering(identity)
            return ok and cx==vx and cy==vy and cz==vz and cfx==raw_fx and cfy==raw_fy and cfz==fz
                and current_front==front and current_rear==rear
                and traction_contact(vehicle,ground_angle)
        end
        if not traction_driver_current(identity,true,drift,ground_angle,physics_current)then state.grip_assist_clock=nil;return false end
        -- Dissipate excess horizontal slip while preserving forward velocity and Z.
        -- Do not assign heading, steering, wheel rotation, power or position.
        return invoke_void(0x1C99BB7B6E96D16F,vehicle,x,y,vz)==true
    end

    function VehicleMods.restore_traction(preserve_frame_clock)
        local state=VehicleMods.state
        if not preserve_frame_clock then state.grip_assist_clock=nil end
        local owner=state.traction_owner
        if not owner then return true end
        local valid=traction_identity(owner)
        if valid=="gone"then state.traction_owner=nil;return true end
        if valid~=true then return false end
        local current=power_native("InvokeBool",TRACTION_NATIVE.get,owner.vehicle)
        if type(current)~="boolean"then return false end
        if current~=owner.applied or current==owner.original then state.traction_owner=nil;return true end
        if traction_identity(owner)~=true or state.traction_owner~=owner then return false end
        if invoke_void(TRACTION_NATIVE.set,owner.vehicle,owner.original)~=true then return false end
        if traction_identity(owner)~=true or power_native("InvokeBool",TRACTION_NATIVE.get,owner.vehicle)~=owner.original then return false end
        state.traction_owner=nil;return true
    end

    function VehicleMods.traction_frame(vehicle)
        local state=VehicleMods.state
        local grip,drift=is_on("vehicle_disable_burnout"),is_on("vehicle_drift_mode")
        local identity=(grip or drift)and power_context(vehicle)or nil
        local property_ready=true
        if state.traction_owner and(not identity or not same_power_context(state.traction_owner,identity))then
            property_ready=VehicleMods.restore_traction(grip and identity~=nil)
            -- An unresolved old-car property remains owned and tracked. It
            -- authorizes no new lease, but need not suppress a separate safe
            -- frame-local request for the current controlled driver vehicle.
            if not property_ready and not grip then return false end
        end
        if not identity then state.grip_assist_clock=nil;return property_ready end
        local class=power_native("InvokeInt",0x29439776AAA00A62,vehicle)
        if type(class)~="number"or class%1~=0 or class<0 or class>22
            or class==14 or class==15 or class==16 or class==21 then return VehicleMods.restore_traction()end
        local cycle=class==8 or class==13
        local ground_angle=cycle and 55.0 or 35.0
        if cycle and state.traction_owner then property_ready=VehicleMods.restore_traction(grip)end
        if not cycle and property_ready then
            local wanted=drift and not grip
            local current=power_native("InvokeBool",TRACTION_NATIVE.get,vehicle)
            if type(current)~="boolean"then
                if not grip then return false end
                -- No original-state proof means no property write or invented
                -- default. The independent grounded impulse may still run.
            else
                local owner=state.traction_owner
                if owner and current~=owner.applied then owner.original=current;owner.applied=current end
                if current~=wanted then
                    if not traction_driver_current(identity,grip,drift,grip and ground_angle or nil)then return false end
                    if not owner then owner=identity;owner.original=current;owner.applied=current;state.traction_owner=owner end
                    owner.applied=wanted
                    if invoke_void(TRACTION_NATIVE.set,vehicle,wanted)~=true then return false end
                    if not same_power_context(identity,power_context(vehicle))or power_native("InvokeBool",TRACTION_NATIVE.get,vehicle)~=wanted then return false end
                end
            end
        end
        if not grip or not driving_input_available(identity.pid)then state.grip_assist_clock=nil;return true end
        if not traction_driver_current(identity,grip,drift,ground_angle)then return false end
        if invoke_void(0xFB8794444A7D60FB,vehicle,false)~=true then return false end
        return traction_grip_frame(identity,class)
    end

