local function presentation_vehicle()
    if not bound or not dependencies then return 0 end
    local vehicle = dependencies.local_vehicle()
    if not dependencies.entity_exists(vehicle) then vehicle = ShellState.last_vehicle end
    return vehicle
end


local function restore_local_vehicle_presentation()
    if not dependencies then return true end
    local vehicle = presentation_vehicle()
    if dependencies.entity_exists(vehicle) then
        dependencies.invoke_void(dependencies.H.SET_VEHICLE_INDICATOR_LIGHTS, vehicle, 0, false)
        dependencies.invoke_void(dependencies.H.SET_VEHICLE_INDICATOR_LIGHTS, vehicle, 1, false)
        dependencies.invoke_void(dependencies.H.SET_VEHICLE_RADIO_ENABLED, vehicle, true)
        dependencies.invoke_void(dependencies.H.SET_VEHICLE_LIGHT_MULTIPLIER, vehicle, 1.0)
        dependencies.invoke_void(dependencies.H.SET_VEHICLE_FULLBEAM, vehicle, false)
    end
    ShellState.doors_locked = false
    return true
end

local suppression_generation = 0 -- retained lifecycle generation; no retired active dispatcher

-- Named control values, independent of current vehicle/model. Kept inline in the
-- vehicle owner and serviced only by its existing gameplay scheduler.
local function create_combat_setups(context, deps)
    local fields = {
        {"vehicle_driver_weapons","bool"}, {"vehicle_chernobog_driver","bool"}, {"vehicle_roof_turret","bool"},
        {"vehicle_complex_reticle","bool"}, {"vehicle_rapid_fire","bool"},
        {"vehicle_rapid_fire_guns","bool"}, {"vehicle_infinite_ammo","bool"},
        {"vehicle_instant_lockon","bool"},
        {"vehicle_lock_players","bool"}, {"vehicle_lock_npcs","bool"},
        {"vehicle_infinite_lock_range","bool"}, {"vehicle_buff_all_rockets","bool"},
        {"vehicle_cannon_range","bool"}, {"vehicle_lab_cannons","bool"},
        {"vehicle_rapid_fire_delay","int",0,500},
        {"vehicle_rocket_speed","float",0.25,8.0},
        {"vehicle_rocket_lifetime","float",0.0,120.0},
        {"vehicle_cannon_distance","float",500.0,5000.0},
        }
    local by_key = {}; for _,field in ipairs(fields) do by_key[field[1]]=field end
    -- Old saved setups may contain retired controls. Validate and discard only
    -- these known values, preserving every live field without recreating features.
    local retired_fields = {
        vehicle_auto_lock_fire={"vehicle_auto_lock_fire","bool"},
        vehicle_rocket_range_unlimited={"vehicle_rocket_range_unlimited","bool"},
        vehicle_rocket_range={"vehicle_rocket_range","float",0.5,30.0},
        vehicle_missile_profile={"vehicle_missile_profile","combo",0,3},
        vehicle_missile_turn_rate={"vehicle_missile_turn_rate","float",0.1,8.0},
        vehicle_missile_turn_limit={"vehicle_missile_turn_limit","float",0.5,15.0},

        vehicle_oppressor_rockets={"vehicle_oppressor_rockets","bool"},
        vehicle_lab_mk2_tracking={"vehicle_lab_mk2_tracking","bool"},
        vehicle_lab_mk2_profile={"vehicle_lab_mk2_profile","combo",0,2},
        vehicle_cannon_profile={"vehicle_cannon_profile","combo",0,2},
    }
    local epoch,busy=0,false
    local function current(token)
        assert(token==epoch,"Combat setup cancelled by newer lifecycle intent")
    end
    local S={rows={},pending=nil,phase="loading",detail="Combat setups awaiting gameplay tick",
        loaded=false,debt={},active_name=nil}
    local api={}
    local function valid_name(name)
        return type(name)=="string" and #name>0 and #name<=64 and name:find("%S")~=nil
            and not name:find("[%z\1-\31\127]") and utf8.len(name)~=nil
    end
    local function valid(field,value)
        if field[2]=="bool" then return type(value)=="boolean" end
        return type(value)=="number" and value==value and value>=field[3] and value<=field[4]
            and (field[2]=="float" or value%1==0)
    end
    local function equal(field,a,b)
        if field[2]=="float" and type(a)=="number" and type(b)=="number" then
            return math.abs(a-b)<=1e-6*math.max(1,math.abs(a),math.abs(b))
        end
        return a==b
    end
    local function hex(s) return (s:gsub(".",function(c)return ("%02X"):format(c:byte())end)) end
    local function unhex(s)
        assert(#s>0 and #s<=128 and #s%2==0 and not s:find("[^0-9A-F]"),"Invalid encoded name")
        local name=s:gsub("..",function(pair)return string.char(tonumber(pair,16))end)
        assert(valid_name(name),"Invalid UTF-8 setup name");return name
    end
    local function sorted(rows)
        local names={};for name in pairs(rows) do names[#names+1]=name end
        table.sort(names);assert(#names<=32,"Combat setup count exceeds 32");return names
    end
    local function encode(rows)
        local lines={"CSCRIPT_COMBAT_SETUPS_V1"}
        for _,name in ipairs(sorted(rows)) do
            assert(valid_name(name),"Invalid setup name");lines[#lines+1]="S|"..hex(name)
            for _,field in ipairs(fields) do
                local value=rows[name][field[1]];assert(valid(field,value),"Invalid field: "..field[1])
                lines[#lines+1]=field[1].."|"..field[2].."|"..(type(value)=="number" and ("%.17g"):format(value) or tostring(value))
            end
            lines[#lines+1]="E"
        end
        local bytes=table.concat(lines,"\n").."\n";assert(#bytes<=65536,"Combat store exceeds 64 KiB");return bytes
    end
    local function decode(bytes)
        assert(type(bytes)=="string" and #bytes<=65536,"Invalid combat store size")
        assert(bytes:sub(-1)=="\n","Incomplete combat store")
        local rows,current,count={},nil,0;local first=true
        for line in bytes:gmatch("([^\n]*)\n") do
            if first then assert(line=="CSCRIPT_COMBAT_SETUPS_V1","Unknown combat store format");first=false
            elseif line:sub(1,2)=="S|" then
                assert(not current,"Unfinished setup");local name=unhex(line:sub(3))
                assert(not rows[name],"Duplicate setup");count=count+1;assert(count<=32,"Too many setups")
                current={name=name,values={},seen={},count=0};rows[name]=current.values
            elseif line=="E" then
                assert(current and current.count==#fields,"Incomplete setup");current=nil
            else
                assert(current,"Unexpected combat store line")
                local key,kind,raw=line:match("^([^|]+)|([^|]+)|([^|]+)$")
                local field=by_key[key] or retired_fields[key];assert(field and kind==field[2],"Unknown combat field/type")
                assert(not current.seen[key],"Duplicate combat field");current.seen[key]=true
                local value
                if kind=="bool" then assert(raw=="true" or raw=="false","Invalid boolean");value=raw=="true"
                else value=tonumber(raw) end
                assert(valid(field,value),"Invalid combat value")
                if by_key[key] then current.values[key]=value;current.count=current.count+1 end
            end
        end
        assert(not first and not current,"Truncated combat store");return rows
    end
    local config=context.CScript.Config
    local available=type(config)=="table" and type(config.RegisterStore)=="function"
        and type(config.Load)=="function" and type(config.Save)=="function" and type(context.Root)=="string"
    if available then
        local ok,result,why=pcall(config.RegisterStore,"modules.vehicle","combat_setups",{
            path=context.Root.."\\combat_setups.txt",encode=encode,decode=decode})
        available=ok and result==true
        if not available then S.detail=tostring(why or result) end
    end
    local getters={bool="IsToggled",float="GetFloatValue",int="GetIntValue",combo="GetListIndex"}
    local setters={bool="Toggle",float="SetFloatValue",int="SetIntValue",combo="SetListIndex"}
    local function feature(field,expected)
        local key=field[1];local f=deps.feature_ref(key)
        assert(f and (not expected or f==expected),"Feature replaced/unavailable: "..key)
        -- compat's single documented virtual integer has no host metadata.
        if key~="vehicle_rapid_fire_delay" then
            assert(type(f.GetHash)=="function","Feature identity unavailable: "..key)
            local hash,id=f:GetHash(),deps.feature_id(key)
            assert(type(hash)=="number" and hash%1==0 and type(id)=="number"
                and (hash & 0xFFFFFFFF)==(id & 0xFFFFFFFF),"Feature identity mismatch: "..key)
        else assert(type(f)=="table","Virtual integer identity unavailable") end
        assert(type(f[getters[field[2]]])=="function" and type(f[setters[field[2]]])=="function","Typed feature unavailable: "..key)
        if key~="vehicle_rapid_fire_delay" then assert(type(f.TriggerCallback)=="function","Feature callback unavailable: "..key) end
        return f
    end
    local function read(field,expected,token)
        if token~=nil then current(token) end
        local f=feature(field,expected)
        if token~=nil then current(token) end
        local value=f[getters[field[2]]](f)
        if token~=nil then current(token) end
        assert(valid(field,value),"Invalid typed readback: "..field[1]);assert(feature(field,f)==f)
        if token~=nil then current(token) end
        return value,f
    end
    local function write(field,value,f,token)
        current(token);assert(valid(field,value));f=feature(field,f);current(token)
        local owned=S.debt[field[1]]
        local function remember(entry,description)
            if not entry or S.debt[description[1]]~=entry or token~=epoch or not entry.unknown then return end
            local ok,observed=pcall(read,description,entry.feature,token)
            if ok and token==epoch and S.debt[description[1]]==entry then
                -- This is an observation AFTER a failed attempt, not ownership
                -- proof. An unchanged third value remains uncertain; a later
                -- distinct change can be preserved as newer external intent.
                entry.failure_value=observed;entry.failure_known=true
            end
        end
        local ok,why=pcall(function()
            if owned and owned.feature==f then owned.unknown=true;owned.failure_known=false end
            local result=f[setters[field[2]]](f,value)
            current(token);assert(result~=false,"Setter rejected: "..field[1])
            if field[1]~="vehicle_rapid_fire_delay" then
                current(token);result=f:TriggerCallback();current(token)
                assert(result~=false,"Callback rejected: "..field[1])
            end
            local observed=read(field,f,token);assert(equal(field,observed,value),"Setter readback mismatch: "..field[1])
            if owned and S.debt[field[1]]==owned then owned.unknown=false;owned.failure_known=false end
        end)
        if not ok then
            remember(owned,field)
            error(why,0)
        end
    end
    local function capture(token)
        local values,refs={},{}
        for _,field in ipairs(fields) do values[field[1]],refs[field[1]]=read(field,nil,token) end
        return values,refs
    end
    local function restore(token)
        token=token or epoch;current(token)
        if next(S.debt)==nil then S.active_name=nil;return true,"" end
        local failures={}
        -- Re-evaluate EACH obligation just before its write. An earlier callback
        -- may have changed a later scalar; it is not an instruction to replay a
        -- stale whole-settings snapshot over the user's newer value.
        for _,field in ipairs(fields) do
            if token~=epoch then return false,"Combat restore cancelled by newer intent" end
            local key=field[1];local entry=S.debt[key]
            if entry then
                local ok,why=pcall(function()
                    local value=read(field,entry.feature,token);current(token)
                    if S.debt[key]~=entry then return end
                    if not equal(field,value,entry.applied) and not equal(field,value,entry.before) then
                        if entry.unknown and (not entry.failure_known or equal(field,value,entry.failure_value)) then
                            error("Unconfirmed write ownership: "..key,0)
                        end
                        S.debt[key]=nil -- distinct post-success or post-failure external intent wins
                        return
                    end
                    entry.unknown=false
                    if not equal(field,value,entry.before) or entry.callback_pending then
                        -- Publish debt before invoking a possibly reentrant host.
                        entry.callback_pending=true
                        write(field,entry.before,entry.feature,token)
                        current(token)
                        if S.debt[key]==entry then entry.callback_pending=false end
                    end
                    current(token)
                    if S.debt[key]==entry then S.debt[key]=nil end
                end)
                if not ok then failures[#failures+1]=tostring(why) end
            end
        end
        if token~=epoch then return false,"Combat restore cancelled by newer intent" end
        if next(S.debt)==nil then S.active_name=nil end
        return #failures==0 and next(S.debt)==nil,table.concat(failures,"; ")
    end
    local function apply(name,values,token)
        current(token);assert(next(S.debt)==nil,"Restore previous setup before applying another")
        local before,refs=capture(token);current(token)
        local ok,why=pcall(function()
            for _,field in ipairs(fields) do
                current(token)
                local key=field[1];local value=read(field,refs[key],token)
                if not equal(field,value,values[key]) then
                    local entry=S.debt[key] or {before=before[key],feature=refs[key]}
                    entry.applied=values[key];entry.callback_pending=true;S.debt[key]=entry
                    write(field,values[key],refs[key],token)
                    current(token)
                    if S.debt[key]==entry then entry.callback_pending=false end
                end
            end
            for _,field in ipairs(fields) do
                assert(equal(field,read(field,refs[field[1]],token),values[field[1]]),"Final setup readback mismatch: "..field[1])
            end
        end)
        -- Panic may have cleared some debts deliberately. Never rebuild them
        -- from an old batch snapshot after that newer intent has taken effect.
        if token~=epoch then error("Combat setup cancelled by newer lifecycle intent",0) end
        S.active_name=next(S.debt)~=nil and name or nil
        if not ok then
            local rollback,detail=restore(token)
            error(tostring(why)..(rollback and "; partial writes restored" or "; restoration pending: "..detail),0)
        end
    end
    local function persist(rows,token)
        current(token);local wanted=encode(rows)
        local ok,why=config.Save("combat_setups",rows);current(token);assert(ok==true,tostring(why or "Combat store write rejected"))
        local loaded,observed=config.Load("combat_setups",{})
        current(token);assert(loaded==true and encode(observed)==wanted,"Combat store readback failed")
        S.rows=rows
    end
    function api.Request(action,name)
        if not available then return false,"Config combat store service unavailable" end
        if action~="save" and action~="apply" and action~="restore" and action~="delete" then return false,"Unknown combat setup action" end
        if action~="restore" and not valid_name(name) then return false,"Use a nonempty UTF-8 name up to 64 bytes without control characters" end
        if S.pending or busy then return false,"Combat setup request already pending" end
        S.pending={action=action,name=name};S.phase="queued";S.detail="Combat setup "..action.." queued on gameplay tick"
        return true,S.detail
    end
    function api.Snapshot()
        local rows={};for _,name in ipairs(sorted(S.rows)) do rows[#rows+1]={name=name,field_count=#fields} end
        return {rows=rows,pending=S.pending~=nil or busy,phase=S.phase,detail=S.detail,active_name=S.active_name,restore_available=next(S.debt)~=nil}
    end
    function api.Tick()
        if not available or busy then return end
        busy=true;local token=epoch;local request
        local ok,why=pcall(function()
            if not S.loaded then
                S.loaded=true;local invoked,loaded,rows=pcall(config.Load,"combat_setups",{})
                current(token)
                if invoked and loaded==true and type(rows)=="table" then S.rows=rows;S.phase="ready";S.detail="Combat setups loaded"
                else S.load_error=tostring(invoked and rows or loaded);S.phase="failed";S.detail=S.load_error end
            end
            current(token);request=S.pending;if not request then return end;S.pending=nil
            if request.action=="restore" then local restored,detail=restore(token);assert(restored,detail);return end
            assert(not S.load_error,"Malformed/unavailable combat store: "..tostring(S.load_error))
            if request.action=="apply" then local values=S.rows[request.name];assert(values,"Combat setup does not exist");apply(request.name,values,token);return end
            local rows={};for name,values in pairs(S.rows) do rows[name]=values end
            if request.action=="save" then rows[request.name]=capture(token)
            else assert(rows[request.name],"Combat setup does not exist");rows[request.name]=nil end
            persist(rows,token)
        end)
        busy=false
        if token~=epoch then S.phase="cancelled";S.detail="Combat setup cancelled by newer lifecycle intent";return end
        if not request and ok then return end
        local phases={save="saved",apply="applied",restore="restored",delete="deleted"}
        S.phase=ok and phases[request.action] or "failed"
        S.detail=ok and ("Combat setup "..S.phase.."; control readbacks only, game effects unverified") or tostring(why)
    end
    function api.Cancel(reason)
        epoch=epoch+1;S.pending=nil;S.phase="cancelled";S.detail=reason or "Combat setup cancelled"
    end
    function api.Drain()
        api.Cancel("Combat setup drain requested")
        if busy then return false,"Combat setup operation cancelling; restoration pending" end
        busy=true
        local called,ok,why=pcall(restore,epoch)
        busy=false
        if not called then why,ok=ok,false end
        if not ok then S.phase="failed";S.detail=why end
        return ok==true,why
    end
    function api.ResetIntent()
        api.Cancel("Combat setup cancelled by Panic/Reset")
        -- Existing Panic/Reset deliberately turns these controls OFF and selects
        -- Vanilla. Even an equal-value reset is newer intent than this Apply.
        S.pending=nil
        for _,field in ipairs(fields) do
            if field[2]=="bool" or field[1]=="vehicle_missile_profile" then S.debt[field[1]]=nil end
        end
        if next(S.debt)==nil then S.active_name=nil end
    end
    return api
end

local function retirement_identity(key, handle)
    assert(type(handle)=="number" and handle%1==0 and handle>0, "Previous retired target unavailable")
    assert(dependencies.entity_exists(handle), "Previous retired target is not streamed")
    local host=dependencies.GTA
    assert(host and type(host.HandleToPointer)=="function", "Retired target identity adapter unavailable")
    local entity=host.HandleToPointer(handle)
    local kind=key=="prevent_shuffle" and "IsPed" or "IsVehicle"
    assert(entity and type(entity[kind])=="function" and entity[kind](entity)==true, "Retired target kind unavailable")
    assert(type(entity.GetAddress)=="function", "Retired target address unavailable")
    local address=entity:GetAddress()
    assert(type(address)=="number" and address%1==0 and address>=65536 and address<9007199254740991, "Retired target identity unreadable")
    return {handle=handle,address=address}
end

local function process_retired_cleanup()
    if not bound then return true end
    local ok=true
    for key in pairs(retired_cleanup) do
        local restored,result=pcall(function()
            local f=dependencies.feature_ref(key)
            if f and f:IsToggled() then
                -- A raw or late ON value never proves an effect was applied.
                -- Suppress it without manufacturing physical release ownership.
                assert(dependencies.set_toggle(key,false)~=false,"Retired toggle OFF rejected")
            end
            local lease=retired_release[key]
            if (key=="prevent_shuffle" or key=="radio_silence") and lease then
                if type(lease)~="table" then
                    -- This migration token existed at bind, before the retired
                    -- dispatcher ran. Pin its first verifiable handoff target;
                    -- failed/missing evidence remains pending, never 'restored'.
                    local handle=key=="prevent_shuffle" and dependencies.local_ped() or presentation_vehicle()
                    lease=retirement_identity(key,handle)
                    retired_release[key]=lease
                end
                local current=retirement_identity(key,lease.handle)
                assert(retired_release[key]==lease,"Retired cleanup ownership changed")
                if current.address~=lease.address then
                    -- Proven handle reuse: relinquish the old instance without
                    -- writing its baseline into the new occupant.
                    return true
                end
                if key=="prevent_shuffle" then
                    assert(dependencies.invoke_void(dependencies.H.SET_PED_CONFIG_FLAG,lease.handle,184,false)~=false)
                else
                    assert(dependencies.invoke_void(dependencies.H.SET_VEHICLE_RADIO_ENABLED,lease.handle,true)~=false)
                end
            elseif key=="vehicle_lab_continuous_repair" then VehicleLab.state.last_maintenance_ms=0 end
        end)
        if restored and result~=false then retired_cleanup[key]=nil;retired_release[key]=nil else ok=false end
    end
    return ok
end

local function register_features()
    if features_registered then return true end
    if not bound then return false end
    local feature_id = require_binding("feature_id", dependencies.feature_id)
    local feature_ref = require_binding("feature_ref", dependencies.feature_ref)
    local function add_toggle(key, name, description, default, callback)
        assert(not RETIRED_GENERAL_KEYS[key], "Retired maintenance controls cannot be registered")
        local feature = FeatureMgr.AddFeature(
            feature_id(key), name, eFeatureType.Toggle, description or "", callback
        )
        if not feature then
            return nil
        end
        if feature and type(feature.SetDefaultValue) == "function" then
            pcall(function()
                feature:SetDefaultValue(default == true)
                if default == true and type(feature.Toggle) == "function" and not feature:IsToggled() then
                    feature:Toggle(true)
                end
            end)
        end
        ShellState.registered_count = ShellState.registered_count + 1
        return feature
    end
    local function add_button(key, name, description, callback)
        local feature = FeatureMgr.AddFeature(feature_id(key), name, eFeatureType.Button, description or "", callback)
        if not feature then
            return nil
        end
        ShellState.registered_count = ShellState.registered_count + 1
        return feature
    end
    local function add_combo(key, name, description, values, default, callback)
        local feature = FeatureMgr.AddFeature(feature_id(key), name, eFeatureType.Combo, description or "", callback)
        if not feature then
            return nil
        end
        if feature then pcall(function() feature:SetList(values):SetListIndex(default or 0) end) end
        ShellState.registered_count = ShellState.registered_count + 1
        return feature
    end
    local function add_slider_float(key, name, description, minimum, maximum, step, default)
        local feature = FeatureMgr.AddFeature(feature_id(key), name, eFeatureType.SliderFloat, description or "")
        if not feature then
            return nil
        end
        if feature then
            pcall(function()
                local initial = default or minimum
                feature:SetLimitValues(minimum, maximum)
                feature:SetStepSize(step or 0.1)
                feature:SetDefaultValue(initial)
                if type(feature.SetFloatValue) == "function" then feature:SetFloatValue(initial) end
            end)
        end
        ShellState.registered_count = ShellState.registered_count + 1
        return feature
    end
    local is_on = require_binding("is_on", dependencies.is_on)
    local list_index = require_binding("list_index", dependencies.list_index)
    local local_ped = require_binding("local_ped", dependencies.local_ped)
    local local_vehicle = require_binding("local_vehicle", dependencies.local_vehicle)
    local entity_exists = require_binding("entity_exists", dependencies.entity_exists)
    local invoke_void = require_binding("invoke_void", dependencies.invoke_void)
    local invoke_bool = require_binding("invoke_bool", dependencies.invoke_bool)
    local repair_vehicle = require_binding("repair_vehicle", dependencies.repair_vehicle)
    local toast = require_binding("toast", dependencies.toast)
    local H = require_binding("H", dependencies.H)
    -- Current/local vehicle features.
    add_toggle("vehicle_damage_auto_repair", "Auto repair",
        "Repairs vehicle damage while preserving its driving and weapon state.", false, function(feature)
            if damage_auto_repair then damage_auto_repair.IntentChanged(feature:IsToggled()) end
        end)
    add_toggle("vehicle_driver_weapons", "Hunter Cannon",
        "Lets the Hunter pilot use the cannon and gun camera.", false)
    -- Legacy persisted key remains registered so old settings/control hashes stay
    -- compatible, but it is hidden and no longer owns behavior independently.
    local legacy_hunter_camera = add_toggle("vehicle_hunter_camera", "Hunter Camera (Legacy)",
        "Compatibility state only; Hunter Cannon now owns the camera.", false)
    if legacy_hunter_camera and type(legacy_hunter_camera.SetVisible) == "function" then
        pcall(function() legacy_hunter_camera:SetVisible(false) end)
    end
    add_toggle("vehicle_chernobog_driver", "Chernobog Driver Missiles",
        "Use deployed Chernobog missiles from the driver seat.", false)
    add_toggle("vehicle_roof_turret", "Remote .50 Cal Roof Turret",
        "Adds a roof turret. Aim with the camera; fire with LMB or vehicle attack.", false)
    add_toggle("vehicle_complex_reticle", "Complex Crosshair in Weaponized Vehicles",
        "Uses the Complex weapon target in armed vehicles and restores your usual choice when you leave.",
        false, function(feature)
            if not feature:IsToggled() then restore_vehicle_reticle() end
        end)
    add_toggle("vehicle_fast_enter_exit", "Fast Enter/Exit",
        "Speeds up vehicle entry and exit.",
        false, function(feature)
            ShellState.fast_enter_exit.dirty = true
            ShellState.fast_enter_exit.last_attempt_ms = -100000
            -- Existing gameplay ticks perform animation/foreign-feature cleanup.
        end)
    add_button("toggle_lock", "Toggle Current Vehicle Lock", "Toggles door lock level for the occupied vehicle.",
        function()
            local vehicle = local_vehicle()
            if not entity_exists(vehicle) then
                toast("Enter a vehicle first."); return
            end
            ShellState.doors_locked = not ShellState.doors_locked
            invoke_void(H.SET_VEHICLE_DOORS_LOCKED, vehicle, ShellState.doors_locked and 2 or 1)
            toast(ShellState.doors_locked and "Current vehicle locked." or "Current vehicle unlocked.")
        end)
    add_toggle("vehicle_quick_brake", "Quick Brake", "Adds strong, smooth braking while you hold the normal brake control.", false)
    add_toggle("vehicle_instant_brake", "Instant Brake", "Stops all vehicle momentum while braking. Takes priority over Quick Brake.", false)
    add_toggle("vehicle_bypass_player_restrictions", "Bypass Player Vehicle Restrictions", "Attempts access to the vehicle you are entering. The owner or host can still deny access.", false)
    add_button("vehicle_hop", "Vehicle Hop", "Gives the current local vehicle a small upward hop.", function()
        local vehicle = local_vehicle()
        if not entity_exists(vehicle) then
            toast("Enter a vehicle first."); return
        end
        invoke_void(H.APPLY_FORCE_TO_ENTITY, vehicle, 1,
            0.0, 0.0, 4.5, 0.0, 0.0, 0.0, 0, true, true, true, false, true)
    end)

    -- Vehicle performance controls. SuperDrive uses the normal accelerate action
    -- (W / controller RT).
    add_toggle("vehicle_fly", "Vehicle Fly",
        "Fly directly with solid collisions in every camera view. WASD and mouse/controller steering respond immediately; flight owns look input while enabled; either Shift moves toward the vehicle roof, either Ctrl toward its underside. Hold Space for double speed. Release keys to hold position. Menus hold hover; temporary control loss resumes automatically.",
        false, function() if vehicle_fly then vehicle_fly.Cancel() end end)
    add_slider_float("vehicle_fly_speed", "Flight Speed",
        "Flight speed from 0 to 10, with a stronger response at higher settings. Zero holds a hover; 10 requests 200 metres per second, or 400 while holding Space.",
        0.0, 10.0, 0.1, 2.0)
    add_toggle("vehicle_superdrive", "SuperDrive",
        "Hold accelerate for a smooth speed boost.", false)
    add_slider_float("vehicle_superdrive_multiplier", "Speed Multiplier",
        "Changes SuperDrive acceleration, up to 50.0.",
        0.1, 50.0, 0.005, 0.605)
    add_toggle("vehicle_superdrive_camera", "Use Camera Direction",
        "Steers SuperDrive toward the camera.", false)
    add_toggle("vehicle_drift_mode", "Drift Mode",
        "Reduces tyre grip for drifting. Keep Grip takes priority.", false)
    add_toggle("vehicle_disable_burnout", "Disable Burnout / Keep Grip",
        "Reduces sliding while all wheels are on the ground.", false)
    add_toggle("vehicle_engine_power", "Engine Power Multiplier",
        "Multiplies driving torque. Aircraft and flying special vehicles also receive forward thrust assistance while you accelerate.",
        false, function(feature)
            -- Feature callbacks can run during menu rendering. Only queue the
            -- release; the existing gameplay frame services it even as the last
            -- active vehicle feature. No entity write occurs in this callback.
            if not feature:IsToggled() then VehicleMods.state.power_pending_release = true end
        end)
    add_slider_float("vehicle_engine_power_multiplier", "Power Multiplier",
        "Driving torque from 1x to 50x; also scales acceleration assistance for aircraft and flying special vehicles.",
        1.0, 50.0, 0.5, 1.0)

    -- Vehicle projectile and lock-on controls. Built-in Cherax settings are
    -- captured before CScript changes them and restored on disable/unload.
    add_toggle("vehicle_rapid_fire", "Vehicle Rapid Fire",
        "Requests faster vehicle weapon fire. Lazer and Hydra cannons require CScript Timing.",
        false, function(feature)
            VehicleLab.cannon_timing_intent_changed("vehicle_rapid_fire",feature:IsToggled())
            VehicleMods.state.controller.force_refresh = true
            if not feature:IsToggled() then VehicleMods.restore_builtin("rapid_fire") end
            if public_api and type(public_api.ReapplyRapidFire) == "function" then
                public_api.ReapplyRapidFire()
            end
        end)
    add_toggle("vehicle_rapid_fire_guns", "Rapid Fire - Guns Only",
        "Speeds up mounted guns. Lazer/Hydra require CScript Timing.",
        false, function(feature)
            VehicleLab.cannon_timing_intent_changed("vehicle_rapid_fire_guns",feature:IsToggled())
            VehicleMods.state.controller.force_refresh=true;reapply_rapid_fire()
        end)
    -- Logical control only: modules.compat owns the integer state and
    -- modules.ui renders it. Do not create the Cherax SliderInt userdata;
    -- its SetLimitValues(0, 500) call is a confirmed host fail-fast boundary.
    ShellState.registered_count = ShellState.registered_count + 1
    add_toggle("vehicle_infinite_ammo", "Vehicle Infinite Ammo",
        "Keeps vehicle weapons and countermeasures supplied.",
        false, function(feature)
            if feature:IsToggled() then
                VehicleMods.state.ammo_active_vehicle = 0
                VehicleMods.state.last_ammo_refresh_ms = -100000
                VehicleMods.state.last_ammo_verify_ms = -100000
                VehicleMods.state.ammo_log_signature = nil
                local vehicle = local_vehicle()
                if entity_exists(vehicle) then
                    VehicleMods.state.ammo_active_vehicle = vehicle
                    VehicleMods.apply_infinite_ammo(vehicle, runtime_now_ms())
                end
            else
                VehicleMods.restore_ammo()
            end
        end)
    add_toggle("vehicle_instant_lockon", "Instant Lock-On",
        "Requests local lock-on eligibility and observes real acquisition (0/1/2). Full lock timer cannot currently be forced to zero.",
        false, function(feature)
            VehicleMods.state.controller.force_refresh = true
            VehicleMods.instant_lock_state().yielded = false
        end)
    add_toggle("vehicle_lock_players", "Lock Onto Players",
        "Adds players and their vehicles as homing targets. In-game missile acquisition remains unverified.",
        false, function(feature)
            VehicleMods.state.controller.force_refresh = true
            VehicleMods.state.last_target_vehicle_scan_ms = -100000
            -- Gameplay reconciliation releases leases; render callback queues only.
        end)
    add_toggle("vehicle_lock_npcs", "Lock Onto NPCs",
        "Adds NPCs and their vehicles as homing targets. In-game missile acquisition remains unverified.",
        false, function(feature)
            VehicleMods.state.controller.force_refresh = true
            VehicleMods.state.last_target_vehicle_scan_ms = -100000
            -- Gameplay reconciliation releases leases; render callback queues only.
        end)
    add_toggle("vehicle_infinite_lock_range", "Infinite Lock-On Range",
        "Extends missile lock-on range.",
        false, function(feature)
            VehicleMods.state.controller.force_refresh = true
            if not feature:IsToggled() then
                VehicleMods.restore_builtin("infinite_lock_range")
                VehicleMods.restore_builtin("disable_range_restrictions")
            end
        end)
    add_slider_float("vehicle_rocket_speed", "Rocket Speed",
        "Changes rocket speed relative to its default speed.",
        0.25, 8.0, 0.001, 1.0)
    add_slider_float("vehicle_rocket_lifetime", "Lifetime (s)",
        "New-shot duration in seconds. 0 preserves the native timer; speed does not compensate it.",
        0.0,120.0,0.5,0.0)
    add_button("vehicle_reset_rocket_speed", "Reset Rocket Speed", "Restores the default rocket speed.", function()
        local ok, detail = public_api.ResetRocketSpeed()
        toast(tostring(detail or (ok and "Rocket speed reset." or "Rocket speed reset failed.")))
    end)
    add_button("vehicle_reset_rocket_tuning", "Reset Rocket Tuning", "Restores default rocket speed and lifetime.",
        function()
            local ok, detail = public_api.ResetRocketTuning()
            toast(tostring(detail or (ok and "Rocket tuning reset." or "Rocket tuning reset failed.")))
        end)
    -- Missile guidance and native cannon customization.
    add_toggle("vehicle_buff_all_rockets", "Buff All Rockets",
        "Uses the native Deluxo rocket template for supported rocket weapons, including handheld launchers.",
        false, function(feature)
            VehicleMods.invalidate_buff_guidance()
            VehicleMods.state.controller.force_refresh = true
            if not feature:IsToggled() then VehicleMods.state.buff_release_pending=true end
            -- Session validation and physical cleanup run on the gameplay tick.
        end)
    add_toggle("vehicle_cannon_range", "Cannon Range",
        "Changes Lazer and Hydra cannon range.",
        false,
        function(feature)
            if not feature:IsToggled() then VehicleMods.restore_builtin("infinite_weapon_range") end
        end)
    add_slider_float("vehicle_cannon_distance", "Cannon Range Distance",
        "Sets Lazer and Hydra cannon range.",
        500.0, 5000.0, 100.0, 5000.0)
    -- Native cannon changes share CScript's ownership and cleanup paths.
    add_toggle("vehicle_lab_cannons", "Lazer/Hydra Pre-Nerf Cannons",
        "Applies original Lazer/Hydra cannon tuning while you pilot the aircraft.",
        false, function(feature)
            VehicleLab.cannon_timing_intent_changed("vehicle_lab_cannons",feature:IsToggled())
            if feature:IsToggled() then
                VehicleLab.state.native_cannon_profile_last_ms = -100000
                VehicleLab.state.native_cannon_block_notice=nil
            else
                VehicleLab.restore_native_cannon_profile()
            end
            VehicleLab.state.last_cannon_shot_ms = 0
        end)
    add_toggle("vehicle_unlimited_rocket_boost", "Unlimited Rocket Boost",
        "Removes the boost fuel limit. Press the normal boost button to start or stop.",
        false, function(feature)
            if not feature:IsToggled() then VehicleLab.restore_unlimited_boost("toggle callback") end
        end)
    add_toggle("vehicle_unlimited_jump", "Unlimited Jump Ability",
        "Unavailable on this game build.", false,
        function(feature)
            if feature:IsToggled() then
                feature:Toggle(false)
                dependencies.log_info("Unlimited Jump unavailable: native cooldown reset is unverified; stock jump preserved.")
            end
        end)

    -- Instant Rocket, Noclip Rockets and Disable Line of Sight are retired.
    -- Retired developer controls are absent; compatibility migration uses tombstones.
    if ShellState.registered_count ~= 39 then
        return false
    end

    features_registered = true
    return true
end

local function frame_tick(now)
    if not started or not bound then return end
    if runtime_writes_suspended then
        VehicleMods.restore_mounted_targets()
        VehicleMods.driver_assistance.Cancel("Delivery suspended.")
        VehicleMods.driver_assistance.RestoreAccess()
        if roof_turret and roof_turret.Pending() then roof_turret.Drain(tonumber(now)or runtime_now_ms())end
        return
    end
    if vehicle_fly then vehicle_fly.Tick() end
    if damage_auto_repair then damage_auto_repair.Tick(tonumber(now)or runtime_now_ms()) end
    if roof_turret then roof_turret.Tick(dependencies.is_on("vehicle_roof_turret"),tonumber(now)or runtime_now_ms())end
    if driver_weapons then
        local vehicle=dependencies.local_vehicle()
        local model=dependencies.entity_exists(vehicle) and dependencies.invoke_int(dependencies.H.GET_ENTITY_MODEL,vehicle) or 0
        local hunter=(model & 0xFFFFFFFF)==(Utils.Joaat("hunter") & 0xFFFFFFFF)
        local cherno=(model & 0xFFFFFFFF)==(Utils.Joaat("chernobog") & 0xFFFFFFFF)
        local hunter_cannon=hunter and dependencies.is_on("vehicle_driver_weapons")
        driver_weapons.Tick(hunter_cannon
            or (cherno and dependencies.is_on("vehicle_chernobog_driver")),
            hunter_cannon)
    end
    fast_enter_exit_animation_tick(
        tonumber(now) or runtime_now_ms(),
        dependencies.local_ped()
    )
    VehicleMods.driver_assistance.AccessTick(now)
    VehicleMods.driver_assistance.Tick(now)
    -- FrameRequested can tick independently of FastTick. Both must supply
    -- a CURRENT, fully resolved local shooter/vehicle rather than nil handles
    -- (which were overwriting the true acquisition readback as unavailable).
    VehicleMods.instant_lock_observe(now,dependencies.local_ped(),dependencies.local_vehicle())
    VehicleMods.frame_tick(now)
    VehicleLab.frame_tick(now)
    if not dependencies.is_on("vehicle_fly") then VehicleMods.driver_assistance.Brake(now) end
    local manager = module_context and module_context.CScript and module_context.CScript.VehicleManager
    if manager and type(manager.FrameTick) == "function" then manager.FrameTick(now) end
end

local function fast_tick(now, ped)
    if not bound then
        return
    end

    if runtime_writes_suspended then
        return
    end

    if VehicleLab.state.backend then VehicleLab.state.backend.Tick() end
    local life_ped=dependencies.local_ped()
    if not dependencies.entity_exists(life_ped)
        or dependencies.invoke_bool(dependencies.H.IS_ENTITY_DEAD,life_ped,false) then
        VehicleLab.restore()
        VehicleMods.restore()
        return
    end
    local current_rapid_delay_ms =
        configured_rapid_delay_ms()
    if ShellState.last_rapid_fire_delay_ms == nil then
        ShellState.last_rapid_fire_delay_ms = current_rapid_delay_ms
    elseif current_rapid_delay_ms ~= ShellState.last_rapid_fire_delay_ms then
        ShellState.last_rapid_fire_delay_ms = current_rapid_delay_ms
        reapply_rapid_fire()
    end
    if vehicle_reticle then
        local ok,detail=vehicle_reticle.Tick(now)
        if ok==false then dependencies.log_error_once("vehicle_reticle",detail) end
    end
    sync_fast_enter_exit(now, false)
    ped = tonumber(ped) or dependencies.local_ped()
    if not dependencies.entity_exists(ped) then
        VehicleMods.fast_tick(now, 0, 0)
        return
    end

    local vehicle = dependencies.local_vehicle()
    local in_vehicle = dependencies.entity_exists(vehicle)
    if in_vehicle then
        ShellState.last_vehicle = vehicle
    end
    ShellState.was_in_vehicle = in_vehicle
    VehicleMods.fast_tick(now, ped, vehicle)
end


local function suspend_runtime_writes()
    if vehicle_fly then vehicle_fly.Cancel() end
    if damage_auto_repair then damage_auto_repair.Invalidate() end
    if runtime_writes_suspended then
        if not bound then return true end
        local timing_ok=VehicleLab.restore_cannon_timing("Vehicle remains suspended")
        local balance_ok=VehicleLab.restore_cannon_balance('Vehicle remains suspended')
        return timing_ok and balance_ok
    end

    runtime_writes_suspended = true

    if not bound then
        return true
    end

    local lab_ok, lab_result =
        pcall(
            VehicleLab.restore
        )

    local mods_ok, mods_result =
        pcall(
            VehicleMods.restore
        )

    local presentation_ok, presentation_result =
        pcall(
            restore_local_vehicle_presentation
        )

    local fast_ok, fast_result =
        pcall(
            restore_fast_enter_exit
        )

    if not lab_ok
        or lab_result == false then
        return false,
            tostring(
                lab_result
                or "Vehicle Lab restore failed"
            )
    end

    if not mods_ok
        or mods_result == false then
        return false,
            tostring(
                mods_result
                or "Vehicle runtime restore failed"
            )
    end

    if not presentation_ok
        or presentation_result == false then
        return false,
            tostring(
                presentation_result
                or "Vehicle presentation restore failed"
            )
    end

    if not fast_ok
        or fast_result == false then
        return false,
            tostring(
                fast_result
                or "Fast Enter/Exit restore failed"
            )
    end

    return true
end

local function revalidate_runtime_state()
    if not bound then
        return false,
            "vehicle module is not compatibility-bound"
    end

    if VehicleLab.cannon_timing_needs_cleanup()and not VehicleLab.cannon_timing_cleanup_tick()then
        return false,"Cannon cleanup pending"
    end
    runtime_writes_suspended = false

    VehicleMods.state.controller.force_refresh = true

    VehicleLab.state.weapon_runtime_signature = nil
    VehicleLab.state.ammo_runtime_signature = nil

    ShellState.last_rapid_fire_delay_ms = nil
    ShellState.fast_enter_exit.dirty = true

    return true
end

local function panic_reset()
    if vehicle_fly then vehicle_fly.Cancel() end
    if damage_auto_repair then damage_auto_repair.Cancel() end
    if not bound then return true end
    if combat_setups then combat_setups.ResetIntent() end
    for _, key in ipairs(VEHICLE_TOGGLE_KEYS) do dependencies.set_toggle(key, false) end
    local lab_ok=VehicleLab.restore()
    local mods_ok=VehicleMods.restore()
    local fast_ok=restore_fast_enter_exit()
    local presentation_ok=restore_local_vehicle_presentation()
    ShellState.last_vehicle = 0
    ShellState.was_in_vehicle = false
    return lab_ok~=false and mods_ok~=false and fast_ok~=false and presentation_ok~=false
end

local function register_vehicle_change_handler()
    if handlers_registered then return true end
    if not (EventMgr and type(EventMgr.RegisterHandler) == "function"
            and eLuaEvent and eLuaEvent.ON_VEHICLE_CHANGE ~= nil) then
        return false
    end
    local ok, handler_id = pcall(EventMgr.RegisterHandler, eLuaEvent.ON_VEHICLE_CHANGE, function()
        if not (started and bound and public_api and dependencies
                and type(dependencies.local_vehicle) == "function") then
            return
        end
        local previous = ShellState.last_vehicle
        local current = dependencies.local_vehicle()
        local call_ok, result =
            pcall(
                public_api.OnVehicleChange,
                previous,
                current
            )

        if (not call_ok or result == false)
            and type(
                dependencies.log_error_once
            ) == "function" then
            dependencies.log_error_once(
                "vehicle_change_ammo",
                call_ok
                and "vehicle-change restoration/reapply returned false"
                or result
            )
        end
    end)
    if not ok
        or type(handler_id) ~= "number" then
        return false
    end

    vehicle_change_handler_id =
        handler_id

    handlers_registered =
        true
    return true
end


function Module.BindCompatibility(bindings)
    if not module_context then error("vehicle module must initialize before compatibility binding", 2) end
    if bound then return VehicleLab, VehicleMods end
    if type(bindings) ~= "table" then error("vehicle compatibility bindings must be a table", 2) end

    dependencies = bindings
    local repair_dependencies=dependencies
    local fly_dependencies=dependencies
    vehicle_fly=new_vehicle_fly({
        Try=function(kind,hash,...)return module_context.Natives.Try(kind,hash,...)end,
        Enabled=function()return started and bound and not runtime_writes_suspended
            and dependencies==fly_dependencies and dependencies.is_on("vehicle_fly")==true end,
        Speed=function()return dependencies.slider_float("vehicle_fly_speed",2.0)end,
        CameraRotation=function()
            local world=module_context.CScript and module_context.CScript.World
            if world and type(world.CameraFreedomSnapshot)=="function" then
                return world.CameraFreedomSnapshot()
            end
        end,
        LocalPlayer=dependencies.local_player_id,LocalPed=dependencies.local_ped,
        LocalVehicle=dependencies.local_vehicle,Session=function()return roof_turret_session end,
        Address=function(handle)
            local entity=dependencies.GTA.HandleToPointer(handle)
            assert(entity and entity:IsVehicle()==true,"Vehicle identity unavailable")
            return entity:GetAddress()
        end,
        KeyDown=function(vk)
            assert(Utils and type(Utils.IsKeyDown)=="function","Keyboard unavailable")
            return Utils.IsKeyDown(vk)
        end,
        GuiOpen=function()
            assert(GUI and type(GUI.IsOpen)=="function","Menu state unavailable")
            return GUI.IsOpen()
        end,
    })
    damage_auto_repair=new_damage_auto_repair({
        Natives=dependencies.Natives,GTA=dependencies.GTA,Players=Players,
        LocalPlayer=dependencies.local_player_id,LocalPed=dependencies.local_ped,LocalVehicle=dependencies.local_vehicle,
        Session=function()return roof_turret_session end,
        Report=function(detail)
            if type(repair_dependencies.log_info)=="function" then
                repair_dependencies.log_info("Auto repair: "..tostring(detail))
            end
        end,
        Enabled=function()return started and bound and not runtime_writes_suspended
            and dependencies==repair_dependencies and dependencies.is_on("vehicle_damage_auto_repair")==true end,
    })
    driver_weapons=create_driver_weapons_owner(DriverWeapons,{
        Memory=dependencies.Memory,Natives=Natives,GTA=GTA,Utils=Utils,GUI=GUI,
        Logger=Logger,FeatureMgr=FeatureMgr,NetworkObjectMgr=NetworkObjectMgr,
        Report=function(detail) dependencies.toast("Driver Weapons: "..tostring(detail),6500,"warning") end,
    })
    local roof_factory=module_context.Modules and module_context.Modules.RoofTurret
    assert(roof_factory and type(roof_factory.New)=="function","Roof turret module is unavailable")
    local roof_assets=roof_factory.CreateAssetActivator({
        Natives=Natives,Utils=Utils,
        FeatureMgr=module_context.Raw and module_context.Raw.FeatureMgr or FeatureMgr,
        FileMgr=module_context.Raw and module_context.Raw.FileMgr or FileMgr,
    })
    roof_turret=roof_factory.New({
        Memory=dependencies.Memory,Natives=Natives,GTA=GTA,Utils=Utils,GUI=GUI,
        FeatureMgr=module_context.Raw and module_context.Raw.FeatureMgr or FeatureMgr,
        FileMgr=module_context.Raw and module_context.Raw.FileMgr or FileMgr,
        Assets={
            revision="speedo50-enhanced-1158-4-runtime",
            models={base="cscript4_speedo50_base",upper="cscript4_speedo50_upper",barrel="cscript4_speedo50_barrel"},
            supportRadius=.165,
            upperOffset={x=0,y=.055046,z=.321427},barrelOffset={x=0,y=0,z=0},
            muzzle={x=.001788,y=.818553,z=.009504},
        },
        EnsureAssets=function(manifest)
            local state,detail=roof_assets.Step(manifest,runtime_now_ms())
            if state=="unsupported"then error(detail,2)end
            return state=="ready",detail
        end,
        ReleaseAssets=function()roof_assets.Stop()end,
        SessionKey=function()return roof_turret_session end,
        Report=function(status,detail)
            if status=="UNAVAILABLE" then dependencies.toast("Roof .50 Cal: "..tostring(detail),6500,"warning")
            elseif status=="ACTIVE" then dependencies.toast("Roof .50 Cal ready. Use normal vehicle attack.",5000,"info")end
            if Logger and type(Logger.LogInfo)=="function"then Logger.LogInfo("[RoofTurret] "..status..": "..tostring(detail))end
        end,
    })
    dependencies.OwnedMemory = module_context.Memory
    VehicleLab, VehicleMods = create_vehicle_system(dependencies)
    reticle_preference=create_reticle_preference(function()return dependencies.Memory end)
    vehicle_reticle=create_vehicle_reticle_controller(reticle_preference,function()
        if not dependencies.is_on("vehicle_complex_reticle") then return false,false end
        local vehicle=dependencies.local_vehicle()
        if not dependencies.entity_exists(vehicle) then return true,false end
        return true,dependencies.invoke_bool(0x25ECB9F8017D98E0,vehicle) -- DOES_VEHICLE_HAVE_WEAPONS
    end)
    if type(VehicleLab) ~= "table" or type(VehicleMods) ~= "table" then
        error("vehicle runtime factory did not return both systems", 2)
    end
    if not register_vehicle_change_handler() then
        error(
            "vehicle module could not register ON_VEHICLE_CHANGE handler",
            2
        )
    end

    bound = true
    combat_setups = create_combat_setups(module_context, dependencies)
    for key in pairs(RETIRED_GENERAL_KEYS) do
        local ok,on=pcall(dependencies.is_on,key)
        if ok and on then retired_cleanup[key]=true;retired_release[key]=true end
    end

    publish_state(
        module_context
    )

    -- SHOULD_COLLIDE stays on this direct function boundary. The preserved
    -- implementation is O(1) until a known local projectile is tracked.
    public_api.ShouldCollide = VehicleMods.should_projectile_collide
    return VehicleLab, VehicleMods
end

function Module.ReapplyRocketTuning()
    return reapply_rocket_tuning()
end

function Module.ReapplyRapidFire()
    return reapply_rapid_fire()
end

function Module.Shutdown()
    if vehicle_fly then vehicle_fly.Cancel() end
    if damage_auto_repair then damage_auto_repair.Cancel() end
    if VehicleMods and not (VehicleMods.driver_assistance.Cancel("Vehicle module unloading.")and VehicleMods.driver_assistance.RestoreAccess())then return false,"Delivery or vehicle access cleanup pending"end
    if roof_turret and roof_turret.Pending()then return false,"Roof turret cleanup is still pending"end
    local reticle_ok,reticle_error=restore_vehicle_reticle()
    if not bound then return reticle_ok,reticle_error end
    local mods_ok, mods_err = pcall(VehicleMods.shutdown)
    local lab_ok, lab_err = pcall(VehicleLab.shutdown)
    local fast_ok, fast_err = pcall(restore_fast_enter_exit)
    local memory_ok = true
    for _, owner in ipairs(MEMORY_OWNER_RESTORE_ORDER) do
        if not module_context.Memory.RestoreOwner(owner) then memory_ok = false end
    end
    if not reticle_ok then return false,tostring(reticle_error) end
    if not lab_ok or lab_err==false then return false, tostring(lab_err or "Vehicle Lab cleanup pending") end
    if not mods_ok or mods_err==false then return false, tostring(mods_err or "Vehicle state restoration pending") end
    if not fast_ok then return false, tostring(fast_err) end
    return memory_ok
end

function Module.Init(context)
    if type(context) ~= "table" or type(context.State) ~= "table"
        or type(context.Memory) ~= "table" or type(context.CScript) ~= "table" then
        error("modules.vehicle requires injected State, Memory, and CScript services")
    end
    if module_context and module_context ~= context then
        error("modules.vehicle is already initialized by another context")
    end
    module_context = context
    public_api = {
        ShouldCollide = unavailable_collision,
    }

    function public_api.RequestCombatSetup(action,name)
        if not bound or not combat_setups then return false,"Vehicle combat setup service unavailable" end
        if not started or runtime_writes_suspended then return false,"Vehicle gameplay scheduler unavailable" end
        return combat_setups.Request(action,name)
    end

    function public_api.CombatSetupSnapshot()
        if combat_setups then return combat_setups.Snapshot() end
        return {rows={},pending=false,phase="unavailable",detail="Vehicle combat setup service unavailable",restore_available=false}
    end

    function public_api.RetireGeneralFeatures()
        if not bound then return false,"Vehicle module is not compatibility-bound" end
        if not started or runtime_writes_suspended then return false,"Vehicle gameplay scheduler unavailable" end
        for key in pairs(RETIRED_GENERAL_KEYS) do retired_cleanup[key]=true end
        return true,"Retired general feature OFF/cleanup queued on gameplay tick"
    end

    function public_api.AssignDeliveryVehicle()if not bound then return false,"Vehicle controls unavailable."end;return VehicleMods.driver_assistance.Assign()end
    function public_api.CallDeliveryVehicle()if not bound then return false,"Vehicle controls unavailable."end;return VehicleMods.driver_assistance.Call()end
    function public_api.CancelDelivery()if not bound then return true end;return VehicleMods.driver_assistance.Cancel("Delivery cancelled.")end
    function public_api.DeliverySnapshot()if not bound then return {phase="unavailable",detail="Vehicle controls unavailable.",assigned=false,active=false,cleanup_pending=false}end;return VehicleMods.driver_assistance.Snapshot()end

    function public_api.GetCurrentVehicle()
        if not bound then return 0 end
        return dependencies.local_vehicle()
    end

    function public_api.RefreshPersonalVehicle()
        return queue_personal_vehicle_action("refresh")
    end

    function public_api.AuditPersonalVehicles()
        return queue_personal_vehicle_action("audit")
    end

    function public_api.PersonalVehicleSnapshot()
        return personal_vehicle_snapshot()
    end

    function public_api.SetRocketSpeed(value)
        if not bound then return false, "vehicle module is not compatibility-bound" end
        if runtime_writes_suspended then return false, "vehicle runtime writes are suspended" end
        local numeric = tonumber(value)
        if not numeric or numeric ~= numeric or numeric == math.huge or numeric == -math.huge then
            return false, "rocket speed must be finite"
        end
        numeric = math.max(0.25, math.min(8.0, numeric))
        dependencies.set_slider_float("vehicle_rocket_speed", numeric)
        return reapply_rocket_tuning()
    end

    function public_api.ResetRocketSpeed()
        return public_api.SetRocketSpeed(1.0)
    end

    function public_api.ResetRocketTuning()
        if not bound then return false, "vehicle module is not compatibility-bound" end
        dependencies.set_slider_float("vehicle_rocket_speed", 1.0)
        dependencies.set_slider_float("vehicle_rocket_lifetime", 0.0)
        return reapply_rocket_tuning()
    end

    function public_api.SetRapidFireDelay(value)
        if not bound then return false, "vehicle module is not compatibility-bound" end
        if runtime_writes_suspended then return false, "vehicle runtime writes are suspended" end
        local numeric = math.floor(tonumber(value) or -1)
        if numeric < RAPID_DELAY_MIN_MS or numeric > RAPID_DELAY_MAX_MS then
            return false, ("rapid fire delay must be between %d and %d milliseconds")
                :format(RAPID_DELAY_MIN_MS, RAPID_DELAY_MAX_MS)
        end
        dependencies.set_slider_int("vehicle_rapid_fire_delay", numeric)
        ShellState.last_rapid_fire_delay_ms = numeric
        return reapply_rapid_fire()
    end

    function public_api.GetRapidFireDelay()
        if not bound then return 45 end
        return configured_rapid_delay_ms()
    end

    function public_api.CompositionSnapshot()
        if not bound then return nil end
        local result=VehicleLab.composition_snapshot(dependencies.local_ped(), dependencies.local_vehicle())
        if result then result.cannon_timing=VehicleLab.cannon_timing_snapshot()end
        return result
    end

    function public_api.ProjectileDiagnosticsSnapshot()
        -- Export existing observations only. Never resolve handles, sample the
        -- host, or expose retained physical wrappers/pending-resolution tables.
        local state = VehicleMods and VehicleMods.state or {}
        local function scalar(value)
            local kind = type(value)
            if kind == "string" or kind == "boolean" then return value end
            if kind == "number" and value == value and math.abs(value) < math.huge then return value end
        end
        local function copy(row, fields)
            local result = {}
            for _, key in ipairs(fields) do result[key] = scalar(rawget(row, key)) end
            return result
        end
        local active_fields = {
            "address", "model", "first_seen", "last_seen", "last_guidance_ms", "last_distance",
            "buff_guided_steps", "buff_target", "buff_target_address", "buff_target_lost",
            "fire_window_id", "fire_window_ms", "fire_window_target", "fire_window_target_address",
            "launch_generation", "launch_weapon", "launch_ammo", "template_ammo_ptr",
            "buff_missile_profile", "buff_guidance_authority", "owner_verified", "native_owner_query",
            "first_loss_reason", "first_loss_ms", "first_loss_detail", "launch_sample_target", "launch_sample_target_address",
            "launch_lock_state", "launch_raw_target", "launch_target_address_known",
            "launch_pre_input_ms", "launch_pre_input_lock_state", "launch_pre_input_target", "launch_pre_input_target_address",
            "launch_pre_input_source_bound", "launch_pre_input_same_ms", "launch_fire_control", "launch_window_reason",
            "launch_window_ambiguous", "rearm_known_identity", "rearm_history_unavailable",
        }
        local history_fields = {
            "handle", "address", "model", "first_seen_ms", "last_seen_ms", "end_sample_ms",
            "fire_window_ms", "weapon", "template_ammo_ptr", "target", "guided_steps", "reason",
            "expiry_cause", "guidance_authority", "missile_profile", "projectile_ammo_record",
            "last_distance", "last_guidance_ms", "buff_target_lost",
            "first_loss_reason", "first_loss_ms", "first_loss_detail", "launch_sample_target", "launch_sample_target_address",
            "launch_lock_state", "launch_raw_target", "launch_target_address_known",
            "launch_pre_input_ms", "launch_pre_input_lock_state", "launch_pre_input_target", "launch_pre_input_target_address",
            "launch_pre_input_source_bound", "launch_pre_input_same_ms", "launch_fire_control", "launch_window_reason",
            "launch_window_ambiguous", "fire_window_target", "fire_window_target_address",
            "rearm_known_identity", "rearm_history_unavailable", "native_owner_query", "owner_verified",
        }
        local snapshot = {
            source = "cached-flight-state", live_sampled = false,
            tracked_count = scalar(state.projectile_count),
            active = {}, active_total = 0, active_limit = 16,
            history = {}, history_total = 0, history_limit = 16,
        }
        local selected = {}
        for handle, info in pairs(state.projectiles or {}) do
            snapshot.active_total = snapshot.active_total + 1
            if type(handle) == "number" and scalar(handle) and handle > 0 and handle % 1 == 0
                and type(info) == "table" then
                local at = 1
                while selected[at] and selected[at].handle < handle do at = at + 1 end
                if at <= 16 then
                    table.insert(selected, at, { handle = handle, info = info })
                    if #selected > 16 then table.remove(selected) end
                end
            end
        end
        for _, item in ipairs(selected) do
            local row = copy(item.info, active_fields)
            row.handle = item.handle
            row.pending_resolution = type(rawget(item.info, "pending_resolution")) == "table"
            row.resolution_evidence = type(rawget(item.info, "resolution_evidence")) == "table"
            snapshot.active[#snapshot.active + 1] = row
        end
        local history = state.projectile_history or {}
        snapshot.history_total = #history
        for index = math.max(1, #history - 15), #history do
            if type(history[index]) == "table" then
                snapshot.history[#snapshot.history + 1] = copy(history[index], history_fields)
            end
        end
        snapshot.active_count, snapshot.history_count = #snapshot.active, #snapshot.history
        snapshot.active_truncated = snapshot.active_total - snapshot.active_count
        snapshot.history_truncated = snapshot.history_total - snapshot.history_count
        return snapshot
    end

    function public_api.PowerSnapshot()
        local state = VehicleMods and VehicleMods.state or {}
        return { requested = bound and dependencies.is_on("vehicle_engine_power") or false,
            backend = state.power_backend or "frame-torque-native", status = state.power_status or "IDLE",
            detail = state.power_detail or "No frame request", value = state.power_requested_value,
            invocation_accepted = state.power_accepted == true, readback_verified = false,
            gameplay_verified = false, pending_release = state.power_pending_release == true }
    end

    function public_api.RevalidateCombatBackends()
        if not bound then return false, "vehicle module is not compatibility-bound" end
        VehicleMods.state.controller.force_refresh = true
        combat_record("Vehicle Combat", "built-in resolver refresh",
            "Explicit diagnostics refresh requested", "INFO")
        return true
    end

    function public_api.ReapplyRapidFire()
        return reapply_rapid_fire()
    end

    function public_api.RestoreProjectileProfile()
        if not bound then return true end
        VehicleLab.restore_global_homing_buff()
        VehicleLab.restore_runtime_ammo_profiles()
        VehicleLab.restore_all_ammo_ranges()
        VehicleLab.restore_all_weapon_runtime()
        return true
    end

    function public_api.RegisterFeatures()
        return register_features()
    end

    function public_api.RegisteredCount()
        return ShellState.registered_count
    end

    function public_api.AutoRepairSnapshot()
        return damage_auto_repair and damage_auto_repair.Snapshot()
            or {status="OFF",detail="Auto repair is unavailable",blocked=true,writes=0}
    end

    function public_api.RoofTurretSnapshot()
        return roof_turret and roof_turret.Snapshot()or{status="OFF",detail="Disabled",active=false}
    end

    function public_api.DrainUnload()
        if damage_auto_repair then damage_auto_repair.Cancel() end
        local targets_ok=not VehicleMods or VehicleMods.restore_mounted_targets()
        if VehicleMods then VehicleMods.instant_lock_state().pending_rearm=nil end
        local timing_ok,timing_detail=true,nil
        if VehicleLab then timing_ok,timing_detail=VehicleLab.unload_cannon_timing()end
        local setups_ok,setups_detail=true,nil
        if combat_setups then setups_ok,setups_detail=combat_setups.Drain() end
        local delivery_ok=VehicleMods.driver_assistance.Cancel("Vehicle cleanup.")and VehicleMods.driver_assistance.RestoreAccess()
        local retired_ok=process_retired_cleanup()
        local driver_ok,driver_detail=true,nil
        if driver_weapons then driver_ok,driver_detail=driver_weapons.Drain() end
        local roof_ok=true
        if roof_turret then roof_ok=roof_turret.Drain(runtime_now_ms())end
        -- Boost release has no native restoration work, even if identity reads
        -- are unavailable or the host worker is stopped. Other owners still drain.
        if VehicleLab then VehicleLab.restore_unlimited_boost("unload") end
        return delivery_ok==true and timing_ok==true and driver_ok==true and roof_ok==true and setups_ok==true and retired_ok==true and targets_ok==true,timing_detail or setups_detail or driver_detail or(not roof_ok and"Roof turret cleanup pending"or not targets_ok and 'Mounted targeting cleanup pending' or nil)
    end

    function public_api.CannonTimingRestoreRequested()
        return bound and VehicleLab.cannon_timing_needs_cleanup()or false
    end

    function public_api.CannonTimingRestoreTick()
        return not bound or VehicleLab.cannon_timing_cleanup_tick()
    end

    function public_api.VehicleFlySnapshot()
        return vehicle_fly and vehicle_fly.Snapshot() or {status="OFF"}
    end

    function public_api.FrameTick(now)
        return frame_tick(now)
    end

    function public_api.FrameRequested()
        if not started or not bound then return false end
        if runtime_writes_suspended then return (roof_turret and roof_turret.NeedsTick())or VehicleMods.mounted_targets_pending() or VehicleMods.driver_assistance.NeedsTick() or VehicleMods.driver_assistance.AccessPending() end
        local manager = module_context and module_context.CScript and module_context.CScript.VehicleManager
        local manager_requested = manager and type(manager.FrameRequested) == "function"
            and manager.FrameRequested() == true
        return manager_requested
            or VehicleMods.projectile_changes_requested()
            or next(VehicleMods.state.projectiles)~=nil or VehicleMods.state.projectile_window_active
            or dependencies.is_on("vehicle_damage_auto_repair")
            or VehicleMods.mounted_targets_pending()
            or VehicleLab.cannon_timing_tick_requested()
            or next(retired_cleanup)~=nil
            or dependencies.is_on("vehicle_driver_weapons")
            or dependencies.is_on("vehicle_chernobog_driver")
            or dependencies.is_on("vehicle_roof_turret")
            or(roof_turret and roof_turret.NeedsTick())
            or (driver_weapons and driver_weapons.NeedsTick())
            or dependencies.is_on("vehicle_rapid_fire")
            or dependencies.is_on("vehicle_rapid_fire_guns")
            or dependencies.is_on("vehicle_instant_lockon")
            or (VehicleMods.state.instant_lock and VehicleMods.state.instant_lock.owned == true)
            or dependencies.is_on("vehicle_fly")
            or dependencies.is_on("vehicle_superdrive")
            or dependencies.is_on("vehicle_drift_mode")
            or dependencies.is_on("vehicle_disable_burnout")
            or dependencies.is_on("vehicle_quick_brake") or dependencies.is_on("vehicle_instant_brake")
            or VehicleMods.driver_assistance.NeedsTick() or VehicleMods.driver_assistance.AccessPending()
            or dependencies.is_on("vehicle_bypass_player_restrictions")
            or dependencies.is_on("vehicle_unlimited_jump")
            or VehicleMods.state.traction_owner~=nil or VehicleMods.state.jump_controller~=nil
            or dependencies.is_on("vehicle_engine_power")
            or VehicleMods.state.power_vehicle ~= 0 or VehicleMods.state.power_pending_release == true
            or dependencies.is_on("vehicle_lab_cannons")
            or dependencies.is_on("vehicle_cannon_range")
            or VehicleMods.state.direct_rapid_active == true
            or (tonumber(VehicleLab.state.native_cannon_profile_ptr) or 0) ~= 0
            or dependencies.is_on("vehicle_fast_enter_exit")
            or ShellState.fast_enter_exit.direct_active == true
            or ShellState.fast_enter_exit.restore_pending == true
            or dependencies.is_on("vehicle_unlimited_rocket_boost")
            or VehicleLab.state.rocket_boost_applied == true
    end

    function public_api.FastTick(now, ped)
        if bound and started and not runtime_writes_suspended then
            process_retired_cleanup()
            if combat_setups then combat_setups.Tick() end
        end
        local result = fast_tick(now, ped)
        process_personal_vehicle_work(now)
        local manager = module_context and module_context.CScript and module_context.CScript.VehicleManager
        if manager and type(manager.FastTick) == "function" then manager.FastTick(now) end
        return result
    end

    function public_api.CombatFeaturesActive()
        return bound and not runtime_writes_suspended and VehicleMods.combat_features_active() or false
    end

    function public_api.CombatTick(now)
        if not bound or runtime_writes_suspended then return end
        now = tonumber(now) or 0
        if now - VehicleMods.state.last_combat_tick_ms >= 25 then
            VehicleMods.state.last_combat_tick_ms = now
            VehicleMods.combat_tick(now)
        end
    end

    function public_api.HasTrackedProjectiles()
        return bound and next(VehicleMods.state.projectiles) ~= nil
    end

    function public_api.RestoreProjectiles()
        if not bound then return true end
        return VehicleMods.restore_projectiles()
    end

    function public_api.RestorePresentation()
