        if combat_setups then combat_setups.Cancel("Vehicle runtime suspended") end
        cancel_driver_weapons("runtime suspended")
        restore_vehicle_reticle()
        return suspend_runtime_writes()
    end

    function public_api.RevalidateRuntimeState()
