        local mgr = host.NetworkObjectMgr
        local ok, key, reason = pcall(function()
            local obj = mgr.GetNetworkObject(id.native, false)
            if not same_scope() then return nil, "scope_changed" end
            if obj == nil then return nil, "object_absent" end
            if type(obj) ~= "table" and type(obj) ~= "userdata" then return nil, "object_unknown" end
            local key = obj.ObjectID
            if type(key) ~= "number" or key ~= key or key < 0 or key >= math.huge or key % 1 ~= 0 then
                return nil,
                    "object_id_unknown"
            end
            if not same_scope() then return nil, "scope_changed" end
            local entity, type_reason = registry_entity(obj, id)
            if not entity then return nil, type_reason end
            if not same_scope() then return nil, "scope_changed" end
            local found = lobby_pointer_identity(entity)
            if not same_scope() then return nil, "scope_changed" end
            if not found or found.address ~= id.address or found.model ~= id.model
                or (found.wrapper ~= nil and found.wrapper ~= key) then
                return nil, "birth_entity_disagrees"
            end
            local active, why = active_registry_identity(key, id, scope, true)
            if not active then return nil, why end
            if not same_scope() then return nil, "scope_changed" end
            return key, "matched"
        end)
        return ok and key or nil, ok and reason or "read_failed"
    end
    local function lobby_handle_identity(handle, observation_scope)
        local function in_scope() return observation_scope == nil or session_state(observation_scope) == "same" end
        if not in_scope() then return nil, "observation scope changed" end
        local present = entity_presence(handle)
        if not in_scope() then return nil, "observation scope changed" end
        if present ~= true then return nil, present == false and "local absent" or "local existence unknown" end
        if type(GTA.HandleToPointer) ~= "function" then return nil, "pointer API unavailable" end
        local ok, entity = pcall(GTA.HandleToPointer, handle)
        if not in_scope() then return nil, "observation scope changed" end
        local id = ok and lobby_pointer_identity(entity)
        if not in_scope() then return nil, "observation scope changed" end
        if not id then return nil, "pointer identity unavailable" end
        local valid, model = pcall(Natives.InvokeInt, N.GET_ENTITY_MODEL, handle)
        if not in_scope() then return nil, "observation scope changed" end
        if not valid or normalize_model(model) ~= id.model then return nil, "model read disagrees" end
        local checked, net = pcall(Natives.InvokeInt, N.NETWORK_GET_ID, handle)
        if not in_scope() then return nil, "observation scope changed" end
        id.native_read = native_read_evidence(checked, net)
        if checked and type(net) == "number" and net > 0 and net < math.huge and net % 1 == 0 then id.native = net end
        if id.wrapper == 0 then
            local entity, reason = active_registry_identity(0, id, observation_scope)
            id.registry_match = reason
            if not entity then id.wrapper = nil end
        end
        return id
    end
    -- A short enrichment window belongs to the exact allocation observed at birth.
    -- It is never restarted from a rebound handle or an enriched mutable anchor.
    local function close_creation_capture(record, reason)
        local window = record.capture_window
        if window and not window.closed then
            window.closed = true; window.reason = reason
            lobby_count("capture_closed")
        end
    end
    local function observe_creation_identity(record, id, handle)
        local window = record.capture_window
        if not window or window.closed then return end
        local native_same = id and
            (id.native == window.native or (window.allow_initial_native and (id.native == nil or window.native == nil)))
        local wrapper_same = id and
            (not window.wrapper or id.wrapper == window.wrapper or (window.allow_initial_native and id.wrapper == nil))
        if not id or handle ~= window.handle or id.address ~= window.address or id.model ~= window.model
            or not native_same or not wrapper_same then
            close_creation_capture(record, "observed_identity_interruption")
        elseif id.wrapper then
            window.wrapper = id.wrapper
        end
    end
    local function pending_birth_read(window, reason)
        return window and window.allow_initial_native
            and (reason == "birth_native_pending" or reason == "birth_wrapper_pending")
    end
    local function creation_capture_scope(record, window)
        if not window then return false, "capture_window_missing" end
        -- Native/wrapper reads may return after a callback, cleanup or a session
        -- transition. Recheck the original record and deadline after those reads,
        -- before enriching identity or publishing either cleanup authority.
        local scope = session_state(window.session_key)
        local now = Time.GetEpocheMs()
        if record.capture_window ~= window or window.closed
            or record.handle ~= window.handle or record.session_key ~= window.session_key
            or scope ~= "same" or (window.anchor and record.lobby_anchor ~= window.anchor) then
            return false, "scope_changed"
        end
        if record.capture_delete_started or record.delete_requested_at then return false, "delete_started" end
        if now < window.started or now > window.expires then return false, "window_expired" end
        return true
    end
    local function creation_capture_identity(record, window)
        local function failed(reason)
            if window then window.last_gate = reason end; return nil, reason
        end
        local valid, reason = creation_capture_scope(record, window)
        if not valid then return failed(reason) end
        local id, why = lobby_handle_identity(window.handle, window.session_key)
        valid, reason = creation_capture_scope(record, window)
        if not valid then return failed(reason) end
        if id then
            window.last_wrapper_state = id.wrapper_state; window.last_native_read = id.native_read
            id.entity_kind = window.entity_kind
        end
        if not id then return failed(why or "identity_unknown") end
        local expected_wrapper = window.wrapper or window.registry_wrapper
        local native_changed = id.native and window.native and id.native ~= window.native
        local wrapper_changed = expected_wrapper ~= nil and id.wrapper ~= nil and id.wrapper ~= expected_wrapper
        if native_changed or wrapper_changed then record.registry_birth_proof = nil end
        if id.address ~= window.address or id.model ~= window.model or native_changed then
            return failed("birth_identity_changed_or_unknown")
        end
        if wrapper_changed then return failed("wrapper_changed_or_unknown") end
        if window.object_type ~= nil and id.object_type ~= nil and id.object_type ~= window.object_type then
            record.registry_birth_proof = nil; return failed("object_type_changed")
        end
        if window.wrapper and id.wrapper ~= window.wrapper then
            return failed(window.allow_initial_native and "birth_wrapper_pending" or "wrapper_changed_or_unknown")
        end
        if window.allow_initial_native then
            -- Enrichment belongs to this original allocation, never an inverse
            -- lookup or a rebound handle. Unknown reads do not reset its deadline.
            if not id.native then return failed("birth_native_pending") end
            if window.native == nil then
                local anchor = window.anchor
                if not anchor or anchor.address ~= id.address or anchor.model ~= id.model
                    or (anchor.native and anchor.native ~= id.native)
                    or (record.head_native and record.head_native ~= id.native)
                    or (record.net_id and record.net_id > 0 and record.net_id ~= id.native) then
                    return failed("birth_native_contradiction")
                end
                window.native = id.native; anchor.native = id.native
                record.net_id = id.native
                if record.head_independent then record.head_native = id.native end
            end
        elseif id.native ~= window.native then
            return failed("birth_identity_changed_or_unknown")
        end
        if window.registry_wrapper ~= nil and id.wrapper ~= nil and id.wrapper ~= window.registry_wrapper then
            return
                failed("registry_wrapper_changed")
        end
        if id.wrapper then window.wrapper = id.wrapper end
        return id
    end
    local function capture_lobby_identity(record, retry)
        -- Preserve independent native lifetime evidence at the original allocation.
        -- This grants absence checks only, never registry ownership or a replacement
        -- handle. Native IDs and Cherax registry keys are different namespaces.
        local function capture_native_absence(record, id, window)
            if record.native_absence_proof or not window or not id or not id.native then return end
            if not creation_capture_scope(record, window) then return end
            local a, net = pcall(Natives.InvokeBool, 0x38CE16C96BD11344, id.native)
            local b, ent = pcall(Natives.InvokeBool, 0x18A47D074708FD68, id.native)
            local c, h = pcall(Natives.InvokeInt, 0xBFFEAB45A9A9094A, id.native)
            local d, g = pcall(Natives.InvokeInt, 0xCE4E5D9B0A4FF560, id.native)
            local final, reason = creation_capture_identity(record, window)
            if not final then
                if not pending_birth_read(window, reason) then close_creation_capture(record, reason) end
                return
            end
            if a and (net == true or net == 1) and b and (ent == true or ent == 1)
                and c and h == window.handle and d and g == window.handle
                and final.address == id.address and final.model == id.model and final.native == id.native
                and creation_capture_scope(record, window) then
                record.native_absence_proof = {
                    handle = window.handle,
                    address = id.address,
                    model = id.model,
                    native = id.native,
                    session_key = window.session_key
                }
            end
        end
        local window = record.capture_window
        local id, why
        if retry then
            id, why = creation_capture_identity(record, window)
            if not id then
                if not pending_birth_read(window, why) then close_creation_capture(record, why) end
                return
            end
        else
            id, why = lobby_handle_identity(record.handle)
            record.birth_evidence = { gate = why or "model_disagrees" }
            if not id or id.model ~= record.model then return end
            id.entity_kind = record.ped and "ped" or "vehicle"
            record.lobby_anchor = id
            local initial_native = record.head_independent == true or record.spawn_birth ~= nil
            if (id.native or initial_native) and record.session_key ~= nil and session_state(record.session_key) == "same" then
                local now = Time.GetEpocheMs()
                window = {
                    handle = record.handle,
                    address = id.address,
                    model = id.model,
                    native = id.native,
                    wrapper = id.wrapper,
                    object_type = id.object_type,
                    entity_kind = id.entity_kind,
                    anchor = id,
                    allow_initial_native = initial_native,
                    session_key = record.session_key,
                    started = now,
                    expires = now + 5000,
                    next_at = now + 50,
                    attempts = 1
                }
                record.capture_window = window
            end
        end
        capture_native_absence(record, id, window)
        if window and window.closed then return end
        local function evidence(value)
            value.wrapper_state = id.wrapper_state; value.native_read = id.native_read
            if retry then
                window.last_gate = value.gate; window.last_evidence = value
            else
                record.birth_evidence = value
            end
        end
        -- Proof is obtained while the original allocation is positively identified,
        -- never reconstructed from disappearance or the current owner of a net ID.
        local mgr = host.NetworkObjectMgr
        local registry_wrapper, native_alias = id.wrapper, false
        if id.native and registry_wrapper == nil and window and mgr and type(mgr.GetNetworkObject) == "function" then
            local why
            registry_wrapper, why = native_birth_registry(id, window.session_key)
            native_alias = registry_wrapper ~= nil
            if not native_alias then
                evidence({ gate = "native_registry_" .. tostring(why) }); return
            end
            if window.registry_wrapper ~= nil and window.registry_wrapper ~= registry_wrapper then
                close_creation_capture(record, "registry_key_changed"); return
            end
            window.registry_wrapper = registry_wrapper
        end
        if not (id.native and registry_wrapper ~= nil and mgr and type(mgr.GetNetworkObject) == "function") then
            evidence({
                gate = not id.native and "native_id_missing" or not id.wrapper and "wrapper_id_missing" or
                    "registry_api_missing"
            })
            return
        end
        local a, net = pcall(Natives.InvokeBool, 0x38CE16C96BD11344, id.native)
        local b, ent = pcall(Natives.InvokeBool, 0x18A47D074708FD68, id.native)
        local c, h = pcall(Natives.InvokeInt, 0xBFFEAB45A9A9094A, id.native)
        local e, g = pcall(Natives.InvokeInt, 0xCE4E5D9B0A4FF560, id.native)
        local f, obj_id, obj_state, registry_identity = pcall(function()
            local scope = window and window.session_key or record.session_key
            local function same_scope() return scope ~= nil and session_state(scope) == "same" end
            if not same_scope() then return nil, "scope_changed" end
            local obj = mgr.GetNetworkObject(registry_wrapper, false)
            if not same_scope() then return nil, "scope_changed" end
            if obj == nil then return nil, "absent" end
            if type(obj) ~= "table" and type(obj) ~= "userdata" then return nil, "unknown" end
            local key = tonumber(obj.ObjectID)
            if not same_scope() then return nil, "scope_changed" end
            local entity, type_reason = registry_entity(obj, id)
            if not entity then return nil, type_reason end
            if not same_scope() then return nil, "scope_changed" end
            local identity = lobby_pointer_identity(entity)
            if not same_scope() then return nil, "scope_changed" end
            return key, "present", identity
        end)
        local registry_matched = f and registry_identity and registry_identity.address == id.address
            and registry_identity.model == id.model
            and (registry_identity.wrapper == registry_wrapper or (native_alias and registry_identity.wrapper == nil))
            and obj_id == registry_wrapper
        local captured = a and (net == true or net == 1) and b and (ent == true or ent == 1)
            and c and h == record.handle and e and g == record.handle and registry_matched
        evidence({
            gate = "proof_incomplete",
            netObject = evidence_bool(a, net),
            netEntity = evidence_bool(b, ent),
            vehicleMatch = evidence_match(c, h, record.handle),
            entityMatch = evidence_match(e, g, record.handle),
            registryMatch = f and obj_state == "absent" and "false" or evidence_match(f, obj_id, registry_wrapper),
            registryState = f and obj_state or "unknown",
            activeRegistryMatch = registry_matched and "matched" or "not_matched",
            registryRoute = native_alias and "native_candidate_exact" or "wrapper_exact"
        })
        -- Capture independent registry authority only while the original birth
        -- window still proves continuous handle/address/model/native identity.
        if registry_matched then
            if not window or session_state(record.session_key) ~= "same" then
                close_creation_capture(record, "scope_changed_during_probe"); return
            end
            local final, reason = creation_capture_identity(record, window)
            if not final then
                if not pending_birth_read(window, reason) then close_creation_capture(record, reason) end
                return
            end
            if final.wrapper ~= id.wrapper then
                close_creation_capture(record, "wrapper_changed_during_probe"); return
            end
        end
        if retry then
            -- Validate again even after a failed probe: a query may have crossed a
            -- streaming/session boundary, which permanently ends capture eligibility.
            local final, reason = creation_capture_identity(record, window)
            if not final then
                if not pending_birth_read(window, reason) then close_creation_capture(record, reason) end
                return
            end
            if not registry_identity or registry_identity.address ~= window.address
                or registry_identity.model ~= window.model
                or (registry_identity.wrapper ~= registry_wrapper and not (native_alias and registry_identity.wrapper == nil)) then
                if registry_identity then close_creation_capture(record, "registry_identity_disagrees") end
                return
            end
            if final.wrapper ~= id.wrapper or session_state(window.session_key) ~= "same" then
                close_creation_capture(record, "scope_changed_during_probe"); return
            end
        end
        -- Publish both authorities only after EVERY continuous-identity read above,
        -- including the final retry observation, has succeeded.
        if registry_matched or captured then
            local valid, reason = creation_capture_scope(record, window)
            if not valid then
                close_creation_capture(record, reason); return
            end
        end
        if registry_matched then
            if native_alias then record.lobby_anchor.registry_wrapper = registry_wrapper end
            -- Registration may expose the first wrapper after the original birth.
            -- Publish that key only with the guarded exact registry proof; never
            -- replace a positive key already attached to the birth anchor.
            if id.wrapper ~= nil and record.lobby_anchor.wrapper == nil then
                record.lobby_anchor.wrapper = id.wrapper
            end
            record.registry_birth_proof = {
                address = id.address,
                model = id.model,
                wrapper = registry_wrapper,
                object_type = id.object_type,
                entity_kind = id.entity_kind,
                native_alias = native_alias or nil,
                session_key = record.session_key
            }
        end
        if captured then
            record.lobby_absence_proof = { native = id.native, wrapper = registry_wrapper, address = id.address }
            if retry then
                window.last_gate = "proof_captured"; window.reason = "captured_live"; window.closed = true
                lobby_count("capture_completed")
            else
                record.birth_evidence.gate = "proof_captured"
                if window then
                    window.closed = true; window.reason = "captured_at_birth"
                end
            end
        end
    end
    local function advance_creation_capture(record, presence)
        local window = record.capture_window
        if not window or window.closed then return end
        local now = Time.GetEpocheMs()
        if presence ~= true then
            close_creation_capture(record, "local_absent_or_unknown"); return
        end
        if record.capture_delete_started or record.delete_requested_at then
            close_creation_capture(record, "delete_started"); return
        end
        if now < window.started or now > window.expires then
            close_creation_capture(record, "window_expired"); return
        end
        -- Observe continuity on every identity check, including during probe backoff.
        local id, why = creation_capture_identity(record, window)
        if not id then
            if not pending_birth_read(window, why) then close_creation_capture(record, why) end
            return
        end
        if window.attempts >= 20 then
            close_creation_capture(record, "attempt_limit"); return
        end
        if now < window.next_at then return end
        -- Registration can lag model/setup completion under pool pressure. Keep
        -- the original allocation eligible briefly, with bounded, spaced probes;
        -- every probe still requires uninterrupted address/model/network identity.
        window.attempts = window.attempts + 1; window.next_at = now + 250
        lobby_count("capture_retries")
        capture_lobby_identity(record, true)
    end
    -- Selected-player setup may finish before registration becomes readable.
    -- Reuse the existing native-thread tick and cleanup batch bound; no new job,
    -- yield or spawn delay. Only still-pending birth windows perform API reads.
    local function service_creation_capture(now)
        if now < capture_tick_at and capture_tick_at - now <= LOBBY_RETENTION_MS then return end
        capture_tick_at = now + LOBBY_RETENTION_MS
        local total = #tracked_vehicles
        if total == 0 then
            capture_cursor = 0; return
        end
        local start, processed = capture_cursor, 0
        for offset = 1, total do
            local index = (start + offset - 1) % total + 1
            local record = tracked_vehicles[index]
            local window = record.capture_window
            if window and not window.closed then
                if session_state(window.session_key) ~= "same" then
                    close_creation_capture(record, "session_unknown_or_changed")
                else
                    advance_creation_capture(record, entity_presence(record.handle))
                end
                processed = processed + 1
            end
            capture_cursor = index
            if processed >= BACKGROUND_CLEANUP_BATCH then break end
        end
    end
    local function resolve_lobby_identity(record)
        local anchor = record.lobby_anchor
        if not anchor then return nil end
        -- Keep branch results, not raw pointers, for bounded transition diagnostics.
        local detail = { direct = "not read", inverse = "not read", registry = "not read" }
        record.identity_detail = detail
        local function check(id, handle)
            observe_creation_identity(record, id, handle)
            if not id then return nil, "identity unavailable" end
            if id.address ~= anchor.address then return "mismatch", "address changed" end
            if id.model ~= anchor.model then return "mismatch", "model changed" end
            local expected_wrapper = anchor.wrapper or anchor.registry_wrapper
            if expected_wrapper and id.wrapper and expected_wrapper ~= id.wrapper then
                return "mismatch",
                    "wrapper id changed"
            end
            if anchor.native and id.native and anchor.native ~= id.native then
                -- A later unknown read cannot erase this positive contradiction.
                record.registry_birth_proof = nil
                return "mismatch", "native id changed"
            end
            -- A temporarily missing network wrapper is not sufficient for rebinding.
            if handle ~= record.handle and anchor.wrapper and id.wrapper ~= anchor.wrapper then
                return "unavailable",
                    "wrapper id unavailable"
            end
            if handle ~= record.handle then
                record.handle = handle; lobby_count("rebound")
            end
            if not anchor.wrapper and id.wrapper then anchor.wrapper = id.wrapper end
            if not anchor.native and id.native then
                anchor.native = id.native; record.net_id = id.native
            end
            return "ours", "matched"
        end
        local direct_id, direct_why = lobby_handle_identity(record.handle)
        local direct, checked_why = check(direct_id, record.handle)
        detail.direct = direct_why or checked_why
        if direct_id then
            detail.wrapper_state = direct_id.wrapper_state; detail.native_read = direct_id.native_read; detail.active_registry_match =
                direct_id.registry_match
        end
        if direct == "ours" then return direct end
        -- Reuse of the OLD script handle alone does not prove the saved network
        -- entity is gone. Seek its separately captured identity before retiring it.
        local lookup_mismatch = false
        if anchor.native then
            -- Both NET_TO_ENT and NETWORK_GET_ENTITY_FROM_NETWORK_ID resolve
            -- generic entity handles; neither result grants ownership by itself.
            for _, hash in ipairs({ 0xBFFEAB45A9A9094A, 0xCE4E5D9B0A4FF560 }) do
                local ok, h = pcall(Natives.InvokeInt, hash, anchor.native)
                if ok and type(h) == "number" and h > 0 and h % 1 == 0 then
                    local id, why = lobby_handle_identity(h)
                    local result, checked = check(id, h)
                    detail.inverse = why or checked
                    if result == "ours" then return result end
                    if result == "mismatch" then lookup_mismatch = true end
                else
                    detail.inverse = ok and "no handle" or "lookup failed"
                end
            end
        end
        -- A nil-wrapper birth may have independently proved a DIFFERENT active
        -- registry key through native_birth_registry. Use that saved proof only;
        -- the native ID itself is never a registry key or rebinding authority.
        local proof = record.registry_birth_proof
        if not anchor.wrapper and proof and proof.native_alias
            and proof.wrapper == anchor.registry_wrapper
            and proof.address == anchor.address and proof.model == anchor.model
            and proof.session_key == record.session_key and record.session_key ~= nil
            and session_state(record.session_key) == "same" then
            local entity, reason = active_registry_identity(proof.wrapper, proof, record.session_key, true)
            detail.registry = "saved native alias: " .. tostring(reason)
            if entity and record.registry_birth_proof == proof and record.lobby_anchor == anchor
                and session_state(record.session_key) == "same" then
                local converted, h = pcall(GTA.PointerToHandle, entity)
                if converted and type(h) == "number" and h > 0 and h % 1 == 0
                    and record.registry_birth_proof == proof and session_state(record.session_key) == "same" then
                    local read, why = lobby_handle_identity(h, record.session_key)
                    -- Revalidate the saved active object after conversion/readback.
                    -- Only the exact original physical allocation may be rebound.
                    local final, final_reason = active_registry_identity(proof.wrapper, proof, record.session_key, true)
                    if final and record.registry_birth_proof == proof and record.lobby_anchor == anchor
                        and session_state(record.session_key) == "same" then
                        local result, checked = check(read, h)
                        detail.registry = why or checked
                        if result then return result end
                    else
                        detail.registry = "saved alias final: " .. tostring(final_reason)
                    end
                else
                    detail.registry = "saved alias conversion unavailable"
                end
            end
        end

        local mgr = host.NetworkObjectMgr
        if anchor.wrapper and mgr and type(mgr.GetNetworkObject) == "function" then
            local ok, entity = pcall(function()
                -- Only the normal active registry is eligible for handle conversion.
                -- includeAll=true additionally exposes unregistering/reassigning objects.
                local net = mgr.GetNetworkObject(anchor.wrapper, false)
                if not net then
                    detail.registry = "object unavailable"; return
                end
                if tonumber(net.ObjectID) ~= anchor.wrapper then
                    detail.registry = "wrapper id disagrees"; return
                end
                local entity, type_reason = registry_entity(net, anchor)
                detail.registry = entity and "entity returned" or type_reason
                return entity
            end)
            if not ok then detail.registry = "lookup failed" end
            local id = ok and lobby_pointer_identity(entity)
            if id then
                if id.address ~= anchor.address then
                    detail.registry = "address changed"; return "mismatch"
                end
                if id.model ~= anchor.model then
                    detail.registry = "model changed"; return "mismatch"
                end
                if id.wrapper and id.wrapper ~= anchor.wrapper then
                    detail.registry = "wrapper id changed"; return "mismatch"
                end
                if not id.wrapper then
                    detail.registry = "wrapper id unavailable"; return "unavailable"
                end
                -- Validate the allocation BEFORE asking the host to make a new handle.
                local converted, h = pcall(GTA.PointerToHandle, entity)
                if converted and type(h) == "number" and h > 0 and h % 1 == 0 then
                    local read, why = lobby_handle_identity(h)
                    local result, checked = check(read, h)
                    detail.registry = why or checked
                    if result then return result end
                else
                    detail.registry = "handle conversion failed"
                end
            elseif entity then
                detail.registry = "pointer identity unavailable"
            end
        else
            detail.registry = "lookup unavailable"
        end
        return lookup_mismatch and "mismatch" or "unavailable"
    end

    local function registry_owned_handle(record)
        local proof, anchor = record.registry_birth_proof, record.lobby_anchor
        if not proof or not anchor or proof.session_key ~= record.session_key or session_state(record.session_key) ~= "same"
            or proof.address ~= anchor.address or proof.model ~= anchor.model
            or proof.wrapper ~= (anchor.wrapper or (proof.native_alias and anchor.registry_wrapper)) then
            return false, "birth_registry_proof_missing"
        end
        local function matches(id)
            return id and id.address == proof.address and id.model == proof.model
                and (id.wrapper == proof.wrapper or (proof.native_alias and id.wrapper == nil))
        end
        local first = lobby_handle_identity(record.handle, record.session_key)
        if not matches(first) then return false, "handle_changed_or_unknown" end
        if first.native and record.net_id and record.net_id > 0 and first.native ~= record.net_id then
            record.registry_birth_proof = nil; return false, "native_contradiction"
        end
        local entity, reason = active_registry_identity(proof.wrapper, proof, record.session_key, proof.native_alias)
        if not entity then return false, reason end
        local final = lobby_handle_identity(record.handle, record.session_key)
        if not matches(final) or session_state(record.session_key) ~= "same" then return false, "final_identity_unknown" end
        if final.native and record.net_id and record.net_id > 0 and final.native ~= record.net_id then
            record.registry_birth_proof = nil; return false, "native_contradiction"
        end
        return true, "matched"
    end

    -- Distinguish unavailable local handles from independently absent
    -- network objects. Never infer a remote deletion from a single missing GUID.
    local function clear_lobby_absence(record)
        record.lobby_absent_since = nil; record.lobby_absent_last = nil
        record.lobby_absent_samples = 0
    end
    local function corroborated_lobby_absence(record)
        local proof = record.lobby_absence_proof or record.native_absence_proof
        local native_only = not record.lobby_absence_proof and proof ~= nil
        record.absence_reason = not proof and "birth_proof_missing" or "proof_scope_unavailable"
        if not proof or not record.lobby_anchor or
            record.lobby_anchor.address ~= proof.address or
            session_state(record.session_key) ~= "same" then
            return false
        end
        if native_only and (proof.session_key ~= record.session_key
                or proof.model ~= record.lobby_anchor.model or proof.native ~= record.lobby_anchor.native) then
            return false
        end
        -- ALL probes must succeed explicitly with a negative result; nil/exception
        -- is unknown, not false. We do not access a stale object as a vehicle.
        local a, local_present = pcall(Natives.InvokeBool, N.DOES_ENTITY_EXIST, record.handle)
        if not a or (local_present ~= false and local_present ~= 0) then
            record.absence_reason = "local_present_or_unknown"
            clear_lobby_absence(record); return false
        end
        local b, net = pcall(Natives.InvokeBool, 0x38CE16C96BD11344, proof.native)
        local c, entity = pcall(Natives.InvokeBool, 0x18A47D074708FD68, proof.native)
        local d, veh = pcall(Natives.InvokeInt, 0xBFFEAB45A9A9094A, proof.native)
        local e, any = pcall(Natives.InvokeInt, 0xCE4E5D9B0A4FF560, proof.native)
        local mgr = host.NetworkObjectMgr
        if not native_only and (not mgr or type(mgr.GetNetworkObject) ~= "function") then
            record.absence_reason = "registry_api_missing"
            clear_lobby_absence(record); return false
        end
        local f, obj = true, nil
        if not native_only then f, obj = pcall(mgr.GetNetworkObject, proof.wrapper, true) end
        record.absence_evidence = {
            netObject = evidence_bool(b, net),
            netEntity = evidence_bool(c, entity),
            vehicleZero = d and type(veh) == "number" and tostring(veh == 0) or "unknown",
            entityZero = e and type(any) == "number" and tostring(any == 0) or "unknown",
            registry = native_only and "not_captured" or not f and "unknown" or obj == nil and "absent" or
                (type(obj) == "table" or type(obj) == "userdata") and "present" or "unknown"
        }
        record.absence_reason = record.absence_evidence.registry == "unknown" and "registry_unknown" or
            "network_probe_unknown"
        if not (b and c and d and e and f) or
            (net ~= true and net ~= false and net ~= 0 and net ~= 1) or
            (entity ~= true and entity ~= false and entity ~= 0 and entity ~= 1) or
            type(veh) ~= "number" or type(any) ~= "number" or
            (obj ~= nil and obj ~= false and type(obj) ~= "table" and type(obj) ~= "userdata") then
            clear_lobby_absence(record); return false
        end
        if net == true or net == 1 or entity == true or entity == 1
            or veh ~= 0 or any ~= 0 or obj ~= nil then
            record.absence_reason = record.absence_evidence.registry == "unknown" and "registry_unknown" or
                "network_present"
            lobby_count("retention_network_present")
            clear_lobby_absence(record); return false
        end
        -- Confirm the missing handle and session again after all network reads.
        local g, still_present = pcall(Natives.InvokeBool, N.DOES_ENTITY_EXIST, record.handle)
        if not g or (still_present ~= false and still_present ~= 0) or
            session_state(record.session_key) ~= "same" then
            record.absence_reason = "final_local_or_session_changed"
            clear_lobby_absence(record); return false
        end
        local now = Time.GetEpocheMs()
        record.absence_reason = "absence_window_pending"
        -- A complete bounded background rotation may exceed 1500 ms. Allow its
        -- actual scheduled revisit window; unknown/present probes still reset it.
        local observation_gap = math.max(1500,
            math.ceil(#tracked_vehicles / BACKGROUND_CLEANUP_BATCH) * BACKGROUND_CLEANUP_MS + BACKGROUND_CLEANUP_MS)
        if record.lobby_absent_last and
            (now - record.lobby_absent_last > observation_gap or now < record.lobby_absent_last) then
            clear_lobby_absence(record)
        end
        if not record.lobby_absent_since then
            record.lobby_absent_since = now; record.lobby_absent_samples = 0
        end
        if not record.lobby_absent_last or now - record.lobby_absent_last >= 150 then
            record.lobby_absent_samples = (record.lobby_absent_samples or 0) + 1
            record.lobby_absent_last = now
        end
        if record.lobby_absent_samples >= 3 and
            now - record.lobby_absent_since >= 500 then
            if not record.lobby_absence_confirmed then
                record.lobby_absence_confirmed = true
                lobby_count("retired_absent")
            end
            record.absence_reason = "corroborated_absence"
            record.absence_route = native_only and "original_native_birth" or "native_and_registry_birth"
            return true
        end
        return false
    end

    local function load_saved_vehicle(preset_name, expected_model)
        local root = FileMgr.GetMenuRootPath()
        if type(root) ~= "string" or root == "" then
            return nil, "Cherax root path was unavailable"
        end
        local path = root:gsub("[/\\]+$", "") .. "\\Vehicles\\" .. preset_name .. ".json"
        if not FileMgr.DoesFileExist(path) then
            return nil, "No saved " .. preset_name .. " preset at " .. path
        end
        local ok, content = pcall(FileMgr.ReadFileContent, path)
        if not ok or type(content) ~= "string" then
            return nil, "Could not read " .. path
        end
        if not content:find('"Cherax Entity"', 1, true) or number_field(content, "type") ~= 1 then
            return nil, "The saved file is not a Cherax vehicle preset"
        end
        local model = normalize_model(number_field(content, "model"))
        if not model then return nil, "Saved " .. preset_name .. ".json has an invalid model hash" end
        if expected_model and model ~= normalize_model(expected_model) then
            return nil, "Saved " .. preset_name .. ".json has a different vehicle model"
        end

        local out = { model = model, mods = {}, extras = {}, path = path }
        local mods = object_field(content, "mods")
        local extras = object_field(content, "extras")
        if not mods then return nil, "Missing saved vehicle mods" end

        for i = 0, 49 do
            local entry = object_field(mods, "mod" .. i)
            if entry then
                out.mods[i] = { index = number_field(entry, "index"), variation = bool_field(entry, "variation") == true }
            end
        end
        for i = 0, 15 do
            out.extras[i] = bool_field(extras, "extra" .. i)
        end
        for _, name in ipairs({ "wheelType", "primaryColor", "secondaryColor", "pearlescentColor", "wheelColor", "windowTint", "plateTextIndex", "interiorColor", "dashBoardColor" }) do
            out[name] = number_field(content, name)
        end
        for _, name in ipairs({ "tyreSmokeColor", "customPrimaryColor", "customSecondaryColor" }) do
            out[name] = colour_field(content, name)
        end
        out.neons = object_field(content, "neonKits")
        out.neon_color = colour_field(out.neons, "color")
        out.primaryCustom = bool_field(content, "isPrimaryColorCustom")
        out.secondaryCustom = bool_field(content, "isSecondaryColorCustom")
        out.bulletproofTyres = bool_field(content, "bulletproofTyres")
        out.driftTyres = bool_field(content, "driftTyres")
        out.plateText = content:match('"plateText"%s*:%s*"([^\"]*)"')
        return out
    end

    local function apply_preset(veh, config)
        local v = function(hash, ...) native_void(hash, veh, ...) end
        v(N.SET_MOD_KIT, 0)
        if config.wheelType then v(N.SET_WHEEL_TYPE, config.wheelType) end

        for slot = 0, 49 do
            local mod = config.mods[slot]
            if mod and mod.index and mod.index >= -1 and mod.index % 1 == 0 then
                local index = math.floor(mod.index)
                if slot == 18 or slot == 20 then
                    v(N.TOGGLE_MOD, slot, index > 0)
                elseif slot == 22 then
                    -- Xenon enable and xenon colour are separate native calls.
                    -- SET_MOD(22, ...) does not select a headlight colour.
                    v(N.TOGGLE_MOD, slot, index >= 0)
                else
                    -- 0 is the first modification; -1 explicitly restores stock.
                    -- Both are valid for the saved cosmetic slots above 24 too.
                    v(N.SET_MOD, slot, index, mod.variation)
                end
            end
        end

        if config.primaryColor and config.secondaryColor then
            v(N.SET_COLOURS, config.primaryColor, config.secondaryColor)
        end
        if config.pearlescentColor and config.wheelColor then
            v(N.SET_EXTRA_COLOURS, config.pearlescentColor, config.wheelColor)
        end
        if config.primaryCustom and config.customPrimaryColor then
            local c = config.customPrimaryColor
            v(N.SET_CUSTOM_PRIMARY, c.r, c.g, c.b)
        end
        if config.secondaryCustom and config.customSecondaryColor then
            local c = config.customSecondaryColor
            v(N.SET_CUSTOM_SECONDARY, c.r, c.g, c.b)
        end
        if config.tyreSmokeColor then
            local c = config.tyreSmokeColor
            v(N.SET_TYRE_SMOKE_COLOUR, c.r, c.g, c.b)
        end
        if config.neons then
            for index, field in ipairs({ "left", "right", "front", "back" }) do
                local enabled = bool_field(config.neons, field)
                if enabled ~= nil then v(N.SET_NEON_ENABLED, index - 1, enabled) end
            end
            local c = config.neon_color
            if c then v(N.SET_NEON_COLOUR, c.r, c.g, c.b) end
        end
        if config.windowTint then v(N.SET_WINDOW_TINT, config.windowTint) end
        if config.plateText then v(N.SET_PLATE, config.plateText) end
        if config.plateTextIndex then v(N.SET_PLATE_STYLE, config.plateTextIndex) end
        if config.bulletproofTyres ~= nil then v(N.SET_TYRES_CAN_BURST, not config.bulletproofTyres) end
        if config.driftTyres ~= nil then v(N.SET_DRIFT_TYRES, config.driftTyres) end
        if config.interiorColor then v(N.SET_INTERIOR_COLOUR, config.interiorColor) end
        if config.dashBoardColor then v(N.SET_DASHBOARD_COLOUR, config.dashBoardColor) end
        for extra = 0, 15 do
            if config.extras[extra] ~= nil then v(N.SET_VEHICLE_EXTRA, extra, not config.extras[extra]) end
        end
    end

    local function valid_target(player_id, expected_rid)
        local player = Players.GetById(player_id)
        if not player or player:IsLocalPlayer() then return nil, "player unavailable" end
        if expected_rid then
            local ok, rid = pcall(function() return player:GetGamerInfo().RockstarId end)
            if not ok or tostring(rid) ~= tostring(expected_rid) then return nil, "player identity changed" end
        end
        local remote_ped = Players.GetCPed(player_id)
        if not remote_ped then return nil, "ped unavailable" end
        local ok, position = pcall(function() return coord_copy(remote_ped.Position) end)
        if ok and position then return position end
        return nil, "position unavailable"
    end

    local function snapshot_local()
        local ped = GTA.GetLocalPed()
        if not ped then return nil, "Local ped not available" end
        local movable = ped
        local ok, is_in_vehicle = pcall(function() return ped:IsInVehicle() end)
        if ok and is_in_vehicle then
            local vehicle = ped.CurVehicle
            if vehicle then movable = vehicle end
        end
        local handle = GTA.PointerToHandle(movable)
        if not entity_exists(handle) then return nil, "Local entity handle not valid" end
        local pos = coord_copy(movable.Position)
        if not pos then return nil, "Local position not valid" end
        local ok_h, heading = pcall(Natives.InvokeFloat, N.GET_ENTITY_HEADING, handle)
        local ok_c, collision_disabled = pcall(Natives.InvokeBool, N.GET_COLLISION_DISABLED, handle)
        local ok_i, invincible = pcall(function() return movable:IsInvincible() end)
        local ok_v, velocity = pcall(function() return coord_copy(movable:GetVelocity()) end)
        local ok_state, address, model, frozen = pcall(function()
            return movable:GetAddress(), normalize_model(Natives.InvokeInt(N.GET_ENTITY_MODEL, handle)), movable.IsFixed
        end)
        if not ok_state or type(address) ~= "number" or address <= 0 or address % 1 ~= 0 or not model or type(frozen) ~= "boolean" then
            return nil, "Local entity identity or frozen state unavailable"
        end
        return {
            handle = handle,
            identity_address = address,
            identity_model = model,
            frozen = frozen,
            on_foot = movable == ped,
            position = pos,
            heading = ok_h and heading or nil,
            collision_enabled = not (ok_c and collision_disabled),
            invincible = ok_i and invincible or false,
            velocity = ok_v and velocity or nil,
        }
    end

    -- Resolve a fresh pointer for every local hold/return. A failed engine read
    -- is not evidence that the captured entity disappeared or was replaced.
    local function local_hold_identity(state)
        if not state or not state.identity_address or not state.identity_model then return "unavailable" end
        local present = entity_presence(state.handle)
        if present == false then return "changed" end
        if present == nil then return "unavailable" end
        local ok, identity = pcall(function()
            local entity = GTA.HandleToPointer(state.handle)
            if not entity then return "unavailable" end
            local address = entity:GetAddress()
            local model = normalize_model(Natives.InvokeInt(N.GET_ENTITY_MODEL, state.handle))
            if type(address) ~= "number" or address <= 0 or address % 1 ~= 0 or not model then return "unavailable" end
            if address ~= state.identity_address or model ~= state.identity_model then return "changed" end
            if state.on_foot then
                local ped = GTA.GetLocalPed()
                if not ped then return "unavailable" end
                local ped_address, ped_handle = ped:GetAddress(), GTA.PointerToHandle(ped)
                if type(ped_address) ~= "number" or ped_address <= 0 or ped_address % 1 ~= 0
                    or type(ped_handle) ~= "number" or ped_handle <= 0 or ped_handle % 1 ~= 0 then
                    return "unavailable"
                end
                if ped_address ~= state.identity_address or ped_handle ~= state.handle then return "changed" end
                if state.require_identity and ped:IsInVehicle() then return "unavailable" end
            end
            return "same"
        end)
        return ok and identity or "unavailable"
    end

    -- Full-body static T-pose; entity freezing alone does not pause skeletal animation.
    local POSE_DICT, POSE_NAME = "mp_sleep", "bind_pose_180"
    local POSE_FLAGS = 131083 -- looping, hold frame, not interruptible, force start; full-body.
    local function hold_local(state)
        if state and session_state(state.session_key) ~= "same" then return false end
        if not state or local_hold_identity(state) ~= "same" then return false end
        local h = state.handle
        native_void(N.SET_ENTITY_INVINCIBLE, h, true)
        native_void(N.FREEZE_ENTITY_POSITION, h, true)
        native_void(N.SET_ENTITY_COLLISION, h, state.returning and state.collision_enabled or false, true)
        native_void(N.SET_ENTITY_VELOCITY, h, 0.0, 0.0, 0.0)
        if state.heading and not state.returning then native_void(N.SET_ENTITY_HEADING, h, state.heading) end
        if state.on_foot then
            -- Ignore movement input until the return collision gate releases the
            -- root, too. Otherwise normal locomotion can animate a frozen return.
            for _, group in ipairs({ 0, 2 }) do
                for _, control in ipairs({ 21, 22, 23, 24, 25, 30, 31, 37, 44, 45, 140, 141, 142, 143, 257, 263, 264 }) do
                    native_void(0xFE99B66D079CF6BC, group, control, true)
                end
            end
        end
        if state.on_foot and not state.returning then
            if not state.pose_prepared then
                local ok, ragdoll = pcall(Natives.InvokeBool, 0x128F79EDCECE4FD5, h)
                if ok and (ragdoll == true or ragdoll == false or ragdoll == 0 or ragdoll == 1) then
                    state.original_ragdoll =
                        ragdoll == true or ragdoll == 1
                end
                native_void(0xAAA34F8A7CB32098, h)
                state.pose_prepared = true
            end
            if state.original_ragdoll ~= nil then native_void(0xB128377056A54E2A, h, false) end
            if state.pose_owned then
                native_void(0x4487C259F0F70977, h, POSE_DICT, POSE_NAME, 0.0)
                native_void(0x28D1A16553C51776, h, POSE_DICT, POSE_NAME, 0.0)
            end
        end
        if state.on_foot and not state.returning and Time.GetEpocheMs() >= (state.pose_check or 0) then
            state.pose_check = Time.GetEpocheMs() + FOLLOW_EVERY_MS
            native_void(0xD3BD40951412FEF6, POSE_DICT)
            local ok, loaded = pcall(Natives.InvokeBool, 0xD031A9162D01088C, POSE_DICT)
            if ok and (loaded == true or loaded == 1) then
                local playing_ok, playing = pcall(Natives.InvokeBool, 0x1F0B79228E461EC9, h, POSE_DICT, POSE_NAME, 3)
                if not state.pose_owned or not playing_ok or (playing ~= true and playing ~= 1) then
                    state.pose_owned = native_void(0xEA47FE3719165B94, h, POSE_DICT, POSE_NAME, 1000.0, -1000.0, -1,
                        POSE_FLAGS, 0.0, true, true, true) or state.pose_owned
                end
                if state.pose_owned then
                    native_void(0x4487C259F0F70977, h, POSE_DICT, POSE_NAME, 0.0)
                    native_void(0x28D1A16553C51776, h, POSE_DICT, POSE_NAME, 0.0)
                end
            end
        end
        return true
    end
    local function place_above(local_state, remote_pos)
        if not hold_local(local_state) then return false end
        local z = remote_pos.z + (local_state.hover_height or HOVER_HEIGHT)
        if local_state.min_hold_z then z = math.max(z, local_state.min_hold_z) end
        if local_state.max_hold_z then z = math.min(z, local_state.max_hold_z) end
        local_state.hold_position = { x = remote_pos.x, y = remote_pos.y, z = z }
        local p = local_state.hold_position
        return native_void(N.SET_ENTITY_COORDS_NO_OFFSET, local_state.handle, p.x, p.y, p.z, true, true, false)
    end

    local function restore_local(state)
        if not state then return true end
        state.returning = true
        state.return_started = state.return_started or Time.GetEpocheMs()
        local function pending(reason)
            state.return_error = reason
            state.return_stalled = Time.GetEpocheMs() - state.return_started >= LOCAL_RETURN_WAIT_MS
            return false
        end
        local session = session_state(state.session_key)
        if session == "changed" then return true end
        if session == "unavailable" then return pending("Local return is waiting for session identity.") end
        local identity = local_hold_identity(state)
        if identity == "changed" then return true end
        if identity ~= "same" then return pending("Local return is waiting for entity identity.") end
        if type(state.frozen) ~= "boolean" then return pending("Original local frozen state is unavailable.") end
        if not hold_local(state) then return pending("Local return could not hold the captured entity.") end
        local h, p = state.handle, state.position
        native_void(0x07503F7948F491A7, p.x, p.y, p.z)
        if not state.return_placed then
            if not native_void(N.SET_ENTITY_COORDS_NO_OFFSET, h, p.x, p.y, p.z, true, true, false) then
                return pending("Local return could not restore its saved position.")
            end
            if state.heading then native_void(N.SET_ENTITY_HEADING, h, state.heading) end
            state.return_placed = true
        end
        if state.pose_owned then
            native_void(0x28D1A16553C51776, h, POSE_DICT, POSE_NAME, 1.0)
            native_void(0x97FF36A1D40EA00A, h, POSE_DICT, POSE_NAME, -8.0)
            state.pose_owned = false
        end
        if state.on_foot and state.pose_prepared and not state.pose_released then
            native_void(0xAAA34F8A7CB32098, h)
            state.pose_released = true
        end
        if state.original_ragdoll ~= nil then
            native_void(0xB128377056A54E2A, h, state.original_ragdoll)
            state.original_ragdoll = nil
        end
        -- Keep the return frozen and protected until local world collision exists.
        local ok, loaded = pcall(Natives.InvokeBool, 0xE9676F61BC0B3321, h)
        if not ok or (loaded ~= true and loaded ~= 1) then
            return pending(ok and "Local return is waiting for safe collision." or
                "Local return collision check is unavailable.")
        end
        if not native_void(N.SET_ENTITY_COLLISION, h, state.collision_enabled, true)
            or not native_void(N.SET_ENTITY_VELOCITY, h, 0.0, 0.0, 0.0)
            or not native_void(N.SET_ENTITY_INVINCIBLE, h, state.invincible)
            or not native_void(N.FREEZE_ENTITY_POSITION, h, state.frozen) then
            return pending("Local return could not restore its saved entity state.")
        end
        state.return_error, state.return_stalled = nil, nil
        return true
    end

    -- Yield our local hover lease to Auto-tp without teleporting the user
    -- back home. Preserve the original physical entity identity and flags.
    function baller.ReleaseLocalHoverToAutoTP(state)
        if not state then return true end
        local scope = session_state(state.session_key)
        if scope == "changed" then return true end
        if scope ~= "same" then return false end
        local identity = local_hold_identity(state)
        if identity == "changed" then return true end
        if identity ~= "same" then return false end
        local h = state.handle
        if state.pose_owned then
            if not native_void(0x28D1A16553C51776, h, POSE_DICT, POSE_NAME, 1.0)
                or not native_void(0x97FF36A1D40EA00A, h, POSE_DICT, POSE_NAME, -8.0) then
                return false
            end
            state.pose_owned = false
        end
        if state.on_foot and state.pose_prepared and not state.pose_released then
            if not native_void(0xAAA34F8A7CB32098, h) then return false end
            state.pose_released = true
        end
        if state.original_ragdoll ~= nil then
            if not native_void(0xB128377056A54E2A, h, state.original_ragdoll) then return false end
            state.original_ragdoll = nil
        end
        if not native_void(N.SET_ENTITY_COLLISION, h, state.collision_enabled, true)
            or not native_void(N.SET_ENTITY_INVINCIBLE, h, state.invincible)
            or not native_void(N.FREEZE_ENTITY_POSITION, h, state.frozen) then
            return false
        end
        return true
    end

    -- Match our actual spawned handle + network identity before modifying it.
    -- This prevents a recycled handle from freezing an unrelated vehicle.
    local function vehicle_identity(record)
        if not record then return "mismatch" end
        record.absence_reason = nil
        record.absence_evidence = nil
        record.identity_detail = nil
        local scope = session_state(record.session_key)
        -- Old-session spawned entities belong to the host's autoCleanup lease.
        -- Do not even resolve their recycled handles in a new session.
        if scope == "changed" then
            close_creation_capture(record, "session_changed"); record.absence_reason = "session_changed"; return
            "mismatch"
        end
        if scope == "unavailable" then
            close_creation_capture(record, "session_unknown"); record.absence_reason = "session_unknown"; return
            "unavailable"
        end
        if record.pickup then
            -- Pickup tokens are NOT entity handles. Never pass one to entity natives.
            local ok, exists = pcall(Natives.InvokeBool, 0xAFC1CA75AD4074D1, record.handle)
            if not ok then return "unavailable" end
            if exists == false or exists == 0 then return "mismatch" end
            local object_ok, object = pcall(Natives.InvokeInt, 0x5099BC55630B25AE, record.handle)
            if not object_ok then return "unavailable" end
            if object and object > 0 then
                if record.object and record.object ~= object then return "mismatch" end
                record.object = object
            end
            return "ours"
        end
        local presence = entity_presence(record.handle)
        advance_creation_capture(record, presence)
        if record.lobby_pid ~= nil and not record.lobby_anchor then
            -- A later matching model/network ID cannot reconstruct the physical
            -- identity missing at birth. Retain the obligation without mutating a
            -- potentially recycled handle, including during post-stop cleanup.
            record.absence_reason = "birth_anchor_missing"
            return "unavailable"
        end
        if record.lobby_anchor then
            -- A completed void invocation is only a request. Always inspect the
            -- captured network identity, including after a local handle disappears.
            local identity = resolve_lobby_identity(record)
            if session_state(record.session_key) ~= "same" then
                close_creation_capture(record, "session_unknown_or_changed"); return "unavailable"
            end
            if identity ~= "ours" then
                if presence == false and identity ~= "mismatch" and
                    corroborated_lobby_absence(record) then
                    record.identity_detail = record.identity_detail or {}
                    record.identity_detail.final = "corroborated_absence"
                    return "mismatch"
                end
                return identity or "unavailable"
            end
            clear_lobby_absence(record)
            presence = entity_presence(record.handle)
        end
        -- Without corroborating lifetime evidence, local absence stays unknown.
        if presence ~= true then
            close_creation_capture(record, "local_absent_or_unknown"); record.absence_reason = record.absence_reason or
                (not record.lobby_anchor and "birth_anchor_missing" or "local_unknown"); return "unavailable"
        end
        local ok_model, model = pcall(Natives.InvokeInt, N.GET_ENTITY_MODEL, record.handle)
        model = ok_model and normalize_model(model) or nil
        if not model then
            close_creation_capture(record, "model_unknown"); return "unavailable"
        end
        if model ~= record.model then
            close_creation_capture(record, "model_changed"); return "mismatch"
        end
        if record.net_id and record.net_id > 0 then
            local ok_net, id = pcall(Natives.InvokeInt, N.NETWORK_GET_ID, record.handle)
            if not ok_net or type(id) ~= "number" or id ~= id or id <= 0 or id >= math.huge or id % 1 ~= 0 then
                close_creation_capture(record, "native_id_unknown")
                record.identity_detail = record.identity_detail or {}
                record.identity_detail.native_read = native_read_evidence(ok_net, id)
                local verified, reason = registry_owned_handle(record)
                record.identity_detail.active_registry_match = reason
                record.identity_detail.final = verified and "active registry identity verified" or "native id unknown"
                if verified then return "ours" end
                return reason == "native_contradiction" and "mismatch" or "unavailable"
            end
            record.identity_detail = record.identity_detail or {}
            record.identity_detail.native_read = native_read_evidence(ok_net, id)
            if id ~= record.net_id then
                record.registry_birth_proof = nil
                close_creation_capture(record, "native_id_changed")
                record.identity_detail = record.identity_detail or {}
                record.identity_detail.final = "native id changed"
                return "mismatch"
            end
        end
        return "ours"
    end

    local function is_our_vehicle(record)
        return vehicle_identity(record) == "ours"
    end

    local function verified_native_id(record)
        if not is_our_vehicle(record) then return nil end
        local handle = record.handle
        local ok, id = pcall(Natives.InvokeInt, N.NETWORK_GET_ID, handle)
        local positive = ok and type(id) == "number" and id > 0 and id < math.huge and id % 1 == 0
        if positive and id ~= record.net_id then
            -- This final getter is also an ownership observation. Never let a
            -- later unknown read resurrect the registry fallback after conflict.
            record.registry_birth_proof = nil
            close_creation_capture(record, "native_id_changed")
            return nil
        end
        if not positive then return nil end
        local controlled, owned = pcall(Natives.InvokeBool, N.NETWORK_HAS_CONTROL, handle)
        if not controlled or (owned ~= true and owned ~= 1) or not is_our_vehicle(record)
            or record.handle ~= handle or session_state(record.session_key) ~= "same" then
            return nil
        end
        return id
    end

    -- Read-only evidence for three allocations per lobby activation. No pointer or
    -- handle is serialized, no new handle is made, and no old-session API is read.
    local function lifetime_fields(record)
        local t = record.lifetime_trace
        return " trace=" .. t.token .. " bornMs=" .. t.born .. " model=" .. tostring(record.model) ..
            " birthNative=" .. tostring(t.birth_native or "unknown") ..
            " birthWrapper=" .. tostring(t.birth_wrapper or "unknown")
    end
    -- A terminal note is historical bookkeeping, never a fresh entity observation.
    local function lifetime_record_event(record, phase, outcome)
        local t = record.lifetime_trace
        if not t or t.seen[phase] then return end
        t.seen[phase] = true
        pcall(function()
            log("Lifecycle record:" .. lifetime_fields(record) .. " phase=" .. phase ..
                " outcome=" ..
                tostring(outcome) ..
                " scope=" .. (record.session_key ~= nil and session_state(record.session_key) or "unknown") ..
                " evidence=cached deletion=unverified deleteCalls=" .. (t.delete_calls or 0) ..
                " firstDeleteMs=" ..
                tostring(t.first_delete or "none") .. " lastDeleteMs=" .. tostring(t.last_delete or "none") ..
                " lastInvocation=" .. tostring(t.last_invocation or "not_attempted") ..
                " lastMatchedMs=" .. tostring(t.last_matched_ms or "unknown") ..
                " lastMatchedPosition=" .. tostring(t.last_position or "unknown"))
        end)
    end
    local function lifetime_delete_attempt(record)
        local t = record.lifetime_trace
        if t then
            local now = Time.GetEpocheMs()
            t.delete_calls = (t.delete_calls or 0) + 1; t.first_delete = t.first_delete or now; t.last_delete = now
            t.last_invocation = "pending"
        end
    end
    local function lifetime_evidence(record, phase, state)
        local trace = record.lifetime_trace
        if not trace or trace.seen[phase] or record.session_key == nil or session_state(record.session_key) ~= "same" then return end
        trace.seen[phase] = true
        local ok = pcall(function()
            local function bool(hash, id)
                if session_state(record.session_key) ~= "same" then return "unknown" end
                local called, v = pcall(Natives.InvokeBool, hash, id)
                if called and (v == true or v == 1) then return "true" end
                if called and (v == false or v == 0) then return "false" end
                return "unknown"
            end
            local anchor = record.lobby_anchor
            local id = lobby_handle_identity(record.handle, record.session_key)
            if session_state(record.session_key) ~= "same" then
                lifetime_record_event(record, "scope_lost_" .. phase, "evidence_unavailable"); return
            end
            local matched = anchor and id and id.address == anchor.address and id.model == anchor.model
                and (not anchor.native or id.native == anchor.native)
                and (not anchor.wrapper or id.wrapper == anchor.wrapper)
            local position, mission, networked, control, owner, next_owner, remote = "unknown", "unknown", "unknown",
                "unknown", "unknown", "unknown", "unknown"
            local displacement = "unknown"
            local actual_position
            if matched then
                local read, actual, net = pcall(function()
                    if session_state(record.session_key) ~= "same" then return end
                    local e = GTA.HandleToPointer(record.handle)
                    if session_state(record.session_key) ~= "same" then return end
                    local check = lobby_pointer_identity(e)
                    if not check or check.address ~= anchor.address or check.model ~= anchor.model then return end
                    return coord_copy(e.Position), e.NetObject
                end)
                if read and actual then
                    actual_position = actual
                    position = string.format("%.2f,%.2f,%.2f", actual.x, actual.y, actual.z)
                    local p = phase == "configured" and actual or trace.position
                    if p then
                        displacement = string.format("%.2f",
                            math.sqrt((actual.x - p.x) ^ 2 + (actual.y - p.y) ^ 2 + (actual.z - p.z) ^ 2))
                    end
                end
                if read and net then
                    local fields, a, b, c = pcall(function() return net.PlayerId, net.PendingPlayerId, net.IsRemote end)
                    if fields then
                        if type(a) == "number" and a == a and a % 1 == 0 then owner = tostring(a) end
                        if type(b) == "number" and b == b and b % 1 == 0 then next_owner = tostring(b) end
                        if type(c) == "boolean" then remote = tostring(c) end
                    end
                end
                mission = bool(0x0A7B270912999B3C, record.handle)
                networked = bool(0xC7827959479DCC78, record.handle)
                control = bool(N.NETWORK_HAS_CONTROL, record.handle)
            end
            local function registry(all)
                if session_state(record.session_key) ~= "same" then return "unknown" end
                local mgr = host.NetworkObjectMgr
                if not anchor or not anchor.wrapper or not mgr or type(mgr.GetNetworkObject) ~= "function" then
                    return
                    "unknown"
                end
                local called, obj = pcall(mgr.GetNetworkObject, anchor.wrapper, all)
                if not called or obj == false then return "unknown" end
                if obj == nil then return "absent" end
                if type(obj) == "table" or type(obj) == "userdata" then return "present" end
                return "unknown"
            end
            local native = anchor and anchor.native
            local local_exists = bool(N.DOES_ENTITY_EXIST, record.handle)
            local net_object = native and bool(0x38CE16C96BD11344, native) or "unknown"
            local net_entity = native and bool(0x18A47D074708FD68, native) or "unknown"
            local active_registry, all_registry = registry(false), registry(true)
            if session_state(record.session_key) ~= "same" then
                lifetime_record_event(record, "scope_lost_" .. phase, "evidence_unavailable"); return
            end
            local final = matched and lobby_handle_identity(record.handle, record.session_key) or nil
            if session_state(record.session_key) ~= "same" then
                lifetime_record_event(record, "scope_lost_" .. phase, "evidence_unavailable"); return
            end
            local stable = matched and final and final.address == id.address and final.model == id.model
                and final.native == id.native and final.wrapper == id.wrapper
            local detail_identity = matched and (stable and "matched" or "changed_during_read") or "not_matched"
            if not stable then
                position, displacement, mission, networked, control, owner, next_owner, remote = "unknown", "unknown",
                    "unknown", "unknown", "unknown", "unknown", "unknown", "unknown"
            elseif actual_position then
                if phase == "configured" then trace.position = actual_position end
                trace.last_position = position; trace.last_matched_ms = Time.GetEpocheMs()
            end
            local detail = record.identity_detail or {}
            local outcome = state == "mismatch" and
                (detail.final == "corroborated_absence" and "corroborated_absence" or "identity_mismatch") or
                "unclassified"
            log("Lifetime evidence: sample=" .. trace.sample .. " slot=" .. tostring(record.lobby_pid) ..
                " phase=" ..
                phase ..
                lifetime_fields(record) ..
                " observedMs=" .. Time.GetEpocheMs() .. " ageMs=" .. math.max(0, Time.GetEpocheMs() - trace.born) ..
                " identity=" ..
                tostring(stable and "ours" or (state == "mismatch" and "mismatch" or "unavailable")) ..
                " outcome=" .. outcome ..
                " detailIdentity=" ..
                detail_identity .. " observedNative=" .. tostring(stable and final.native or "unknown") ..
                " observedWrapper=" .. tostring(stable and final.wrapper or "unknown") ..
                " anchorNative=" ..
                tostring(native or "unknown") .. " anchorWrapper=" .. tostring(anchor and anchor.wrapper or "unknown") ..
                " local=" .. local_exists .. " netObject=" .. net_object .. " netEntity=" .. net_entity ..
                " activeRegistry=" .. active_registry .. " allRegistry=" .. all_registry ..
                " mission=" .. mission .. " networked=" .. networked .. " control=" .. control ..
                " owner=" .. owner .. " nextOwner=" .. next_owner .. " remote=" .. remote ..
                " position=" .. position .. " displacement=" .. displacement ..
                " workerDone=" .. tostring(trace.worker_done == true) .. " deleteCalls=" .. (trace.delete_calls or 0))
        end)
        if not ok then
            pcall(function()
                log("Lifetime evidence: sample=" ..
                    trace.sample .. " phase=" .. phase .. lifetime_fields(record) .. " evidence=unavailable")
            end)
        end
    end

    local function protect_local_from_owned_peds()
        local ok, ped = pcall(GTA.GetLocalPed)
        if not ok or not ped then return end
        local converted, h = pcall(GTA.PointerToHandle, ped)
        if not converted or not entity_exists(h) then return end
        local position_ok, local_position = pcall(function() return coord_copy(ped.Position) end)
        local function nearby(record)
            -- A frozen independent head actor keeps its last verified world pose.
            -- Distant groups cannot collide with the local ped. This is only a
            -- read-work filter; a near pair still requires full original ownership.
            local p = record.head_independent and record.head_frozen and record.spawn_pose
            if not p or not position_ok or not local_position then return true end
            for _, axis in ipairs({ "x", "y", "z" }) do
                local a, b = p[axis], local_position[axis]
                if type(a) ~= "number" or type(b) ~= "number" or a ~= a or b ~= b
                    or math.abs(a) >= 10000000 or math.abs(b) >= 10000000 then
                    return true
                end
            end
            return (p.x - local_position.x) ^ 2 + (p.y - local_position.y) ^ 2 + (p.z - local_position.z) ^ 2 <= 25
        end
        local checked = 0
        for _, record in ipairs(tracked_vehicles) do
            -- Baller peds already have full collision disabled. Avoid issuing
            -- redundant local-pair native calls for every one of 512 peds.
            if record.ped and not record.single_kaylee and not record.head_full_collision then
                checked = checked + 1
                if checked > PED_ACTIVE_LIMIT then break end
                if record.handle ~= h and nearby(record) and is_our_vehicle(record) then
                    -- Frame-scoped, verified entity pairs only; no global ped or
                    -- world collision toggle survives cleanup or script unload.
                    native_void(0xA53ED5520C07654A, h, record.handle, true)
                end
            end
        end
    end

    -- Physical spill and legacy Deluxo use free physics; only Deluxo gets impulses.
    local function enable_physics(record)
        if not is_our_vehicle(record) then return false end
        local h = record.handle
        native_void(N.FREEZE_ENTITY_POSITION, h, true)
        native_void(N.SET_ENTITY_HAS_GRAVITY, h, false)
        if not record.ped then native_void(N.SET_VEHICLE_GRAVITY, h, false) end
        native_void(N.SET_ENTITY_COLLISION, h, true, true)
        native_void(N.SET_ENTITY_INVINCIBLE, h, false)
        native_void(N.SET_ENTITY_DYNAMIC, h, true)
        native_void(N.ACTIVATE_PHYSICS, h)
        if not record.ped then
            -- Legacy Deluxo/non-reference route also needs engines and lighting.
            -- Called again after saved appearance so presets cannot turn them off.
            native_void(N.SET_UNDRIVEABLE, h, false)
            native_void(N.KEEP_ENGINE_ON, h, true)
            native_void(N.SET_ENGINE_ON, h, true, true, false)
            native_void(N.SET_LIGHTS, h, 2)
            native_void(N.SET_FULLBEAM, h, true)
            native_void(N.TOGGLE_MOD, h, 22, true)
            local seq = record.sequence or 1
            native_void(N.SET_XENON_COLOUR, h, REFERENCE_XENON_PALETTE[(seq - 1) % #REFERENCE_XENON_PALETTE + 1])
            local r, g, b = reference_neon_colour(seq)
            native_void(N.SET_NEON_COLOUR, h, r, g, b)
            for side = 0, 3 do native_void(N.SET_NEON_ENABLED, h, side, true) end
        end
        return true
    end

    -- A gentle launch makes the heap tumble rather than just sink into a neat pile.
    -- This force only affects the vehicles created by this script.
    local function nudge_vehicle(record, phase)
        if not APPLY_MILD_IMPULSE or not is_our_vehicle(record) then return end
        if record.net_id and record.net_id > 0 then
            local ok, owned = pcall(Natives.InvokeBool, N.NETWORK_HAS_CONTROL, record.handle)
            if not ok or not owned then return end
        end
        local a = phase * 2.399963229728653
        local fx, fy, fz = math.cos(a) * 5.0, math.sin(a) * 5.0, 8.0
        native_void(N.APPLY_FORCE_CENTER, record.handle, 1, fx, fy, fz, false, false, false, false)
    end

    -- Hold alignment only inside a small movement/turn deadzone. This keeps
    -- stationary stacks tidy while new cars follow even small steps promptly.
    -- Previewing a spawn or retrying control must not consume a layer: commit
    -- the returned column only after the car has actually been placed.
    local function reference_transform(state, count, center, heading)
        if state.single_kaylee then
            local slot = ((count - 1) % BALLER_SLOT_COUNT) + 1
            return baller_slot_pose(slot, center, state.baller_ring_heading), true, nil
        end
        local loose = count <= REFERENCE_OPENING_LOOSE or count % REFERENCE_LOOSE_EVERY == 0
        local layer = 0
        local anchor_x, anchor_y, anchor_heading = center.x, center.y, heading
        local next_column = state.column
        if not loose then
            local column = state.column
            local dx = column and center.x - column.x or 0
            local dy = column and center.y - column.y or 0
            local turn = column and math.abs((heading - column.heading + 180) % 360 - 180) or 0
            if not column or column.level >= REFERENCE_COLUMN_LEVELS or
                dx * dx + dy * dy > REFERENCE_REANCHOR_DISTANCE ^ 2 or turn > REFERENCE_REANCHOR_TURN then
                column = { x = center.x, y = center.y, heading = heading, level = 0 }
            end
            anchor_x, anchor_y, anchor_heading = column.x, column.y, column.heading
            layer = column.level
            next_column = { x = column.x, y = column.y, heading = column.heading, level = layer + 1 }
        end
        local a = math.rad(anchor_heading)
        if state.formation == "tug_overlap" then
            -- Original Tug spawn: identical live target XYZ and heading on each attempt.
            -- Collision is enabled separately once the final placement is verified.
            return {
                x = center.x,
                y = center.y,
                z = center.z + REFERENCE_HEIGHT,
                heading = (heading + 180) % 360,
            }, true, nil
        end
        if state.formation == "circle" and state.circle_live == true then
            -- Unlike stationary column anchors, every new circle entry tracks
            -- the current validated ped/vehicle body. Preserve the original
            -- radius, angle order, heading and stack-layer spacing.
            local angle = math.rad(heading) + ((count - 1) % 12) * (math.pi / 6)
            return {
                x = center.x + 0.65 * math.cos(angle),
                y = center.y + 0.65 * math.sin(angle),
                z = center.z + REFERENCE_HEIGHT + layer * REFERENCE_LAYER_STEP,
                heading = (math.deg(angle) + 90) % 360
            }, not loose, next_column
        end
        if state.formation == "target_stack" then
            -- Place each new owned car at the target's CURRENT body/vehicle position,
            -- not the default 1.65m forward offset or an earlier column anchor.
            -- Earlier cars retain their verified frozen world poses.
            local phase = ((count - 1) % 8) * (math.pi / 4)
            return {
                x = center.x + 0.10 * math.cos(phase),
                y = center.y + 0.10 * math.sin(phase),
                z = center.z + REFERENCE_HEIGHT + layer * REFERENCE_LAYER_STEP,
                heading = (heading + 180) % 360
            }, not loose, next_column
        end
        if state.formation == "circle" or state.formation == "monkey" or state.formation == "duo" then
            -- Preserve the original layering and loose-car cadence; change XY and
            -- orientation only. Vehicle centers sit inside a tight 1.3m diameter.
            local angle = a + ((count - 1) % 12) * (math.pi / 6)
            local ped_circle = state.formation == "monkey" or state.formation == "duo"
            local radius = ped_circle and 0.45 or 0.65
            local step = ped_circle and 0.02 or REFERENCE_LAYER_STEP
            return {
                x = anchor_x + radius * math.cos(angle),
                y = anchor_y + radius * math.sin(angle),
                z = state.base_z + REFERENCE_HEIGHT + layer * step,
                heading = (math.deg(angle) + 90) % 360
            }, not loose, next_column
        end
        return {
            x = anchor_x - (state.forward or REFERENCE_FORWARD) * math.sin(a),
            y = anchor_y + (state.forward or REFERENCE_FORWARD) * math.cos(a),
            -- Do not feed the target's collision-induced rise into later layers.
            z = state.base_z + REFERENCE_HEIGHT + layer * REFERENCE_LAYER_STEP,
            heading = (anchor_heading + 180) % 360,
        }, not loose, next_column
    end

    local function target_heading(player_id, fallback, validated_handle)
        local ok, heading = pcall(function()
            if validated_handle then return Natives.InvokeFloat(N.GET_ENTITY_HEADING, validated_handle) end
            local ped = Players.GetCPed(player_id)
            if not ped then return fallback end
            local facing = ped
            local in_vehicle, vehicle = pcall(function()
                return ped:IsInVehicle() and ped.CurVehicle or nil
            end)
            if in_vehicle and vehicle then facing = vehicle end
            local handle = GTA.PointerToHandle(facing)
            if not handle or handle == 0 then return fallback end
            return Natives.InvokeFloat(N.GET_ENTITY_HEADING, handle)
        end)
        return ok and type(heading) == "number" and heading == heading and math.abs(heading) < 100000 and heading or
            fallback
    end

    local function target_vehicle_front(state, model)
        if state.bounds_model == model then return state.bounds_forward end
        state.bounds_model, state.bounds_forward = model, REFERENCE_FORWARD
        if not model or type(Memory.Alloc) ~= "function" or type(Memory.Free) ~= "function"
            or type(Memory.WriteFloat) ~= "function" or type(Memory.ReadFloat) ~= "function" then
            return state.bounds_forward
        end
        local allocated, pointer = pcall(Memory.Alloc, 48)
        if not allocated or type(pointer) ~= "number" or pointer <= 0 then return state.bounds_forward end
        local ok, front = pcall(function()
            for offset = 0, 40, 8 do Memory.WriteFloat(pointer + offset, 1000000.0) end
            if not native_void(N.GET_MODEL_DIMENSIONS, model, pointer, pointer + 24) then return nil end
            local lo, hi = Memory.ReadFloat(pointer + 8), Memory.ReadFloat(pointer + 32)
            if type(lo) ~= "number" or type(hi) ~= "number" or lo ~= lo or hi ~= hi
                or lo >= hi or math.abs(lo) > 500 or math.abs(hi) > 500 then
                return nil
            end
            -- Anchor near the nose of the occupied vehicle, including boats/aircraft.
            -- Very large bounds must not move the stream tens of metres away.
            return math.max(REFERENCE_FORWARD, math.min(10.0, hi + 0.35))
        end)
        pcall(Memory.Free, pointer)
        if ok and front then state.bounds_forward = front end
        return state.bounds_forward
    end

    local function sample_target_motion(state, center)
        local vehicle, handle, position, model, in_vehicle
        local ok = pcall(function()
            local ped = Players.GetCPed(state.player_id)
            if not ped then return end
            in_vehicle = ped:IsInVehicle()
            if in_vehicle ~= true then return end
            vehicle = ped.CurVehicle
            if not vehicle then return end
            local function valid_handle(h)
                return type(h) == "number" and h == h and h > 0 and h < math.huge and h % 1 == 0
            end
            local h = GTA.PointerToHandle(vehicle)
            local ped_handle = GTA.PointerToHandle(ped)
            if not valid_handle(h) or not valid_handle(ped_handle)
                or entity_presence(h) ~= true or entity_presence(ped_handle) ~= true then
                return
            end
            local expected = lobby_pointer_identity(vehicle)
            local resolved = GTA.HandleToPointer(h)
            local actual = lobby_pointer_identity(resolved)
            if not expected or not actual or expected.address ~= actual.address
                or expected.model ~= actual.model then
                return
            end
            local current = Natives.InvokeInt(0x9A9112A0FE9A4713, ped_handle, false)
            model = normalize_model(Natives.InvokeInt(N.GET_ENTITY_MODEL, h))
            if current ~= h or model ~= expected.model then return end
            -- Recheck after native reads; never use a recycled or unrelated vehicle
            -- wrapper as the target's position/heading source.
            local final = lobby_pointer_identity(GTA.HandleToPointer(h))
            if not final or final.address ~= expected.address or final.model ~= model then return end
            vehicle = resolved; position = coord_copy(vehicle.Position)
            if position then handle = h end
        end)
        if not ok or (in_vehicle ~= true and in_vehicle ~= false) then return nil end
        if in_vehicle == false then
            if state.vehicle_handle then state.column = nil end
            -- On-foot movement can change elevation without a vehicle transition.
            -- Sample the current body height for each newly created stack layer.
            state.base_z = center.z
            state.vehicle_handle, state.forward, state.motion_speed = nil, nil, 0
            state.motion_center = center
            return center
        end
        -- In a vehicle with incomplete evidence is not the on-foot case. The
        -- caller waits within its existing window, without applying a guessed pose.
        if not handle or not position then return nil end
        if state.vehicle_handle ~= handle then state.column = nil end
        state.vehicle_handle = handle
        state.forward = target_vehicle_front(state, model)
        local velocity_ok, velocity = pcall(function() return coord_copy(vehicle:GetVelocity()) end)
        local speed = velocity_ok and velocity and math.sqrt(velocity.x ^ 2 + velocity.y ^ 2 + velocity.z ^ 2) or 0
        if speed ~= speed or speed > 500 then
            speed = 0; velocity = nil
        end
        state.motion_speed, state.motion_center = speed, position
        -- Short, capped prediction compensates for spawn/native latency without
        -- stretching the column down the road. Resampled after helper yields.
        local lead = speed > 0 and math.min(0.06, 3.0 / speed) or 0
        center = {
            x = position.x + (velocity and velocity.x or 0) * lead,
            y = position.y + (velocity and velocity.y or 0) * lead,
            z = position.z + (velocity and velocity.z or 0) * lead
        }
        state.base_z = center.z
        return center
    end

    -- Observe the values used by placement; native coordinates only corroborate
    -- wrapper reads and never replace them. InvokeV3 returns three floats.
    local function pose_native_position(handle)
        if type(Natives.InvokeV3) ~= "function" or type(handle) ~= "number" or handle <= 0 then return nil end
        local ok, x, y, z = pcall(Natives.InvokeV3, 0x3FEF770D40960D5A, handle, false)
        return ok and coord_copy({ x = x, y = y, z = z }) or nil
    end

    local function sample_reference_pose(state, count, capture)
        state.pose_probe = nil
        local center = valid_target(state.player_id, state.rid)
        if not center then return nil end
        local probe = capture and { ped = coord_copy(center), base_before = state.base_z, at = Time.GetEpocheMs() }
        center = sample_target_motion(state, center)
        if probe then
            probe.source = center and (state.vehicle_handle and "vehicle" or "ped") or "unknown"
            probe.base_after = state.base_z
            if center and state.vehicle_handle then
                probe.vehicle = coord_copy(state.motion_center)
                probe.native_vehicle = pose_native_position(state.vehicle_handle)
            end
            local ok, ped_handle = pcall(function() return GTA.PointerToHandle(Players.GetCPed(state.player_id)) end)
            if ok then probe.native_ped = pose_native_position(ped_handle) end
            state.pose_probe = probe
        end
        if not center then return nil end
        state.heading = target_heading(state.player_id, state.heading, state.vehicle_handle)
        return reference_transform(state, count, center, state.heading)
    end


    -- Only original positively captured created vehicles enter this safety path.
    -- Peds, pickups and the user's original/borrowed entity keep their own lifecycle.
    local function retention_birth(record)
        if type(record) ~= "table" or record.ped or record.pickup or record.head_rigid
            or record.lobby_resolved or record.session_key == nil then
            return
        end
        local birth, proof = record.spawn_birth, record.registry_birth_proof
        if type(birth) ~= "table" or type(proof) ~= "table" or type(record.lobby_anchor) ~= "table"
            or type(birth.address) ~= "number" or birth.address ~= birth.address or birth.address <= 0 or birth.address >= math.huge
            or proof.address ~= birth.address or proof.model ~= birth.model or normalize_model(record.model) ~= birth.model
            or proof.session_key ~= record.session_key or type(proof.wrapper) ~= "number" or proof.wrapper <= 0 or proof.wrapper % 1 ~= 0
            or (record.lobby_anchor.address ~= birth.address or record.lobby_anchor.model ~= birth.model) then
            return
        end
        return birth, proof
    end
    local function retention_current(record, token, cleanup)
        local birth, proof = retention_birth(record)
        if not birth or disposed or (not cleanup and (abort_requested or generation ~= token)) then return false end
        local h, key = record.handle, record.session_key
        if session_state(key) ~= "same" or not is_our_vehicle(record) then return false end
        local registry = active_registry_identity(proof.wrapper, proof, key, proof.native_alias)
        if not registry then return false end
        local controlled, owned = pcall(Natives.InvokeBool, N.NETWORK_HAS_CONTROL, h)
        if not controlled or (owned ~= true and owned ~= 1) or session_state(key) ~= "same" then return false end
        -- End the host observations with a fresh physical snapshot; table/intent
        -- postconditions below cannot authorize a changed allocation or newer run.
        local read, identity = pcall(function() return lobby_pointer_identity(GTA.HandleToPointer(h)) end)
        return read and identity and identity.address == birth.address and identity.model == birth.model
            and (identity.wrapper == proof.wrapper or (proof.native_alias and identity.wrapper == nil))
            and record.handle == h and record.session_key == key and record.spawn_birth == birth
            and record.registry_birth_proof == proof and not record.lobby_resolved
            and not disposed and (cleanup or (not abort_requested and generation == token))
    end
    local function retention_set(record, token, cleanup, hash, ...)
        if not retention_current(record, token, cleanup) then return false end
        local ok, result = pcall(Natives.InvokeVoid, hash, record.handle, ...)
        return ok and result ~= false
    end
    local function contain_reference_vehicle(record, cleanup)
        local token = generation
        if not retention_birth(record) then return false end
        -- Tug becomes solid after placement. Cargoplane stays completely
        -- non-solid before and after placement, without affecting gravity/engine.
        local solid = record.disable_vehicle_physics == true
            and record.placed == true and record.disable_cargo_collision ~= true
        record.vehicle_retention_requested = true
        record.vehicle_retention_invocations_ok = false
        local function set(hash, ...)
            return retention_set(record, token, cleanup, hash, ...)
        end
        -- Clear the stronger no-collision override BEFORE enabling regular
        -- collision. Until placement completes, retain the old non-solid staging.
        if solid and not set(N.SET_ENTITY_FULL_NO_COLLISION, false, true) then return false end
        -- Stop on any failure. Keep the original entity tracked for cleanup.
        if not set(N.FREEZE_ENTITY_POSITION, true)
            or not set(N.SET_ENTITY_INVINCIBLE, true)
            or not set(N.SET_ENTITY_COLLISION,
                solid or (record.disable_vehicle_physics ~= true and record.tug_overlap ~= true),
                true)
            or not set(N.SET_ENTITY_VELOCITY, 0.0, 0.0, 0.0)
            or not set(N.SET_ENTITY_HAS_GRAVITY, false)
            or not set(N.SET_VEHICLE_GRAVITY,
                record.disable_vehicle_physics ~= true)
            or not set(N.SET_UNDRIVEABLE, false)
            or not set(N.SET_ENGINE_ON, true, true, false) then
            return false
        end
        -- Every CScript reference vehicle keeps its engine running, regardless
        -- of collision policy. Tug stays solid; Cargo remains non-solid.
        set(N.KEEP_ENGINE_ON, true)
        -- Physics-only hardening for our already-created, proven-controlled car.
        -- This keeps the original spawn model, positions, order and cadence intact.
        -- Ignore unsupported optional natives rather than refusing a healthy spawn.
        -- None of these writes affect peds, pickups or freely tumbling effects.
        set(N.SET_ENTITY_ANGULAR_VELOCITY, 0.0, 0.0, 0.0)
        -- Keep Cargo non-solid permanently; don't touch settled Tug collision.
        if not solid then
            set(N.SET_ENTITY_FULL_NO_COLLISION,
                record.disable_vehicle_physics == true or record.tug_overlap == false,
                record.disable_vehicle_physics ~= true and record.tug_overlap ~= true)
        else
            -- A positive disabled readback is a real setup failure, not success.
            local checked, disabled = pcall(Natives.InvokeBool, N.GET_COLLISION_DISABLED, record.handle)
            if checked and (disabled == true or disabled == 1) then return false end
        end
        record.vehicle_retention_invocations_ok = true
        return true
    end
    local function prepare_contained_reference(record, pose)
        local token = generation
        if not contain_reference_vehicle(record, false) then return false, "created vehicle containment unavailable" end
        local native_id = verified_native_id(record)
        if native_id then
            if not retention_current(record, token, false) or verified_native_id(record) ~= native_id
                or not retention_current(record, token, false) then
                return false, "created vehicle network identity changed"
            end
            local ok, value = pcall(Natives.InvokeVoid, N.NETWORK_SET_CAN_MIGRATE, native_id, false)
            if not ok or value == false then return false, "created vehicle migration request rejected" end
        end
        if not retention_set(record, token, false, N.SET_ENTITY_AS_MISSION, true, true) then
            return false,
                "created vehicle mission request rejected"
        end
        if not record.placed then
            if not pose then return false, "spawn pose missing" end
            for _, name in ipairs({ "x", "y", "z", "heading" }) do
                local n = pose[name]
                if type(n) ~= "number" or n ~= n or math.abs(n) == math.huge then return false, "spawn pose unavailable" end
            end
            if not retention_set(record, token, false, N.SET_ENTITY_COORDS_NO_OFFSET, pose.x + 0.0, pose.y + 0.0, pose.z + 0.0, false, false, false)
                or not retention_set(record, token, false, N.SET_ENTITY_ROTATION, 0.0, 0.0, pose.heading + 0.0, 2, true) then
                return false, "contained placement invocation failed"
            end
            local ok, actual = pcall(function()
                local entity = GTA.HandleToPointer(record.handle); return entity and coord_copy(entity.Position)
            end)
            if not ok or not actual or not retention_current(record, token, false) then
                return false,
                    "contained position readback unavailable"
            end
            local dx, dy, dz = actual.x - pose.x, actual.y - pose.y, actual.z - pose.z
            if dx * dx + dy * dy + dz * dz > 0.01 then return false, "exact position not confirmed" end
            record.placed = true
            -- Re-run containment after final XYZ readback to turn collision ON.
            if record.disable_vehicle_physics == true and not contain_reference_vehicle(record, false) then
                return false, "heavy vehicle collision activation unavailable"
            end
        end
        return retention_current(record, token, false), "contained setup authority changed"
    end
    local function contained_reference_lighting(record, config)
        local token, ready = generation, true
        local heavy = record.disable_vehicle_physics == true
        local hunter = record.hunter_style == true
        if not retention_birth(record) or not retention_current(record, token, false) then
            return false, "vehicle appearance waiting for original entity control"
        end
        -- Tug and Cargo cosmetics are model-dependent. If xenon/neon/mod calls
        -- are rejected, still attempt the remaining optional calls. Ordinary
        -- reference-vehicle failure behavior stays unchanged.
        local function v(label, hash, ...)
            if not retention_set(record, token, false, hash, ...) then
                -- Unsupported cosmetic natives must not prevent later lights,
                -- neon or engine commands from being attempted on owned cars.
                config.lighting_errors = config.lighting_errors or {}
                config.lighting_errors[label] = (config.lighting_errors[label] or 0) + 1
            end
        end
        -- Force engines ON for all CScript reference vehicles, including
        -- regular car/variant spawns. Frozen position and gravity remain unchanged.
        v("vehicle driveable", N.SET_UNDRIVEABLE, false)
        v("keep engine running", N.KEEP_ENGINE_ON, true)
        v("engine on", N.SET_ENGINE_ON, true, true, false)
        local sequence = record.sequence or 1
        -- Stable per-spawn variation, offset by the current effect generation.
        -- Hunter's existing spawn count, positions and aircraft physics remain
        -- untouched; this affects appearance and running engine only.
        local styling_sequence = hunter and sequence + (record.spawn_generation or 0)*19 or sequence
        local r, g, b = reference_neon_colour(styling_sequence)
        if heavy or hunter then
            if hunter then
                -- Helicopter paint may be partly covered by liveries. Apply
                -- indexed colors AND custom RGB, rather than assuming one
                -- helicopter material supports all custom-color natives.
                local primary = (styling_sequence*17 + 7) % 160
                local secondary = (styling_sequence*29 + 23) % 160
                v("Hunter indexed paint", N.SET_COLOURS, primary, secondary)
                v("Hunter pearlescent", N.SET_EXTRA_COLOURS,
                    (styling_sequence*13 + 31) % 160, (styling_sequence*7 + 5) % 160)
            end
            v("primary paint", N.SET_CUSTOM_PRIMARY, r, g, b)
            local r2, g2, b2 = reference_neon_colour(styling_sequence + 47)
            v("secondary paint", N.SET_CUSTOM_SECONDARY, r2, g2, b2)
        end
        if hunter then
            -- Select only indices that GTA reports for the actual Hunter.
            -- Empty/unsupported livery catalogs are simply ignored.
            local function livery(count_hash, setter_hash, offset)
                if type(Natives.InvokeInt) ~= "function" then return end
                local ok, count = pcall(Natives.InvokeInt, count_hash, record.handle)
                if ok and type(count)=="number" and count%1==0
                    and count>=1 and count<=64 then
                    v("Hunter livery", setter_hash, (styling_sequence-1+offset)%count)
                end
            end
            livery(N.GET_VEHICLE_LIVERY_COUNT,N.SET_VEHICLE_LIVERY,0)
            livery(N.GET_VEHICLE_LIVERY2_COUNT,N.SET_VEHICLE_LIVERY2,2)
            -- A running helicopter with rotating blades and selectively lit
            -- searchlight. The searchlight is white; Xenon and neon colours
            -- below vary per Hunter only where the model supports them.
            v("Hunter rotor spin", N.SET_HELI_BLADES_FULL_SPEED)
            v("Hunter searchlight",N.SET_VEHICLE_SEARCHLIGHT,
                styling_sequence%3~=0,false)
        end
        v("lights on", N.SET_LIGHTS, 2)
        v("high beams", N.SET_FULLBEAM, not hunter or styling_sequence%2==0)
        v("xenon enable", N.TOGGLE_MOD, 22, true)
        local index = (styling_sequence - 1) % #REFERENCE_XENON_PALETTE + 1
        v("xenon colour", N.SET_XENON_COLOUR, REFERENCE_XENON_PALETTE[index])
        v("neon colour", N.SET_NEON_COLOUR, r, g, b)
        for side = 0, 3 do v("neon enable", N.SET_NEON_ENABLED, side, true) end
        ready = ready and retention_birth(record) and retention_current(record, token, false)
        return ready, ready and nil or "contained lighting waiting for ownership or supported native"
    end

    local function release_vehicle(record)
        if record.head_rigid then
            record.head_release_preserved = true; return true
        end
        if record.pickup then return end
        if not record.ped then
            -- Once a deletion native has accepted the request, don't
            -- immediately reapply freeze/invincibility/collision to that
            -- same pending-to-die vehicle during the post-pass release.
            -- Keep the birth record until verified absence or replacement.
            if record.delete_requested_at then return true end
            return contain_reference_vehicle(record, true)
        end
        if record.single_kaylee then
            -- This cleanup fallback deliberately UNFREEZES other ped effects.
            -- Never unfreeze Baller peds after a failed/pending delete: keep
            -- their existing collision/gravity/freeze state until retirement.
            -- Their verified deletion path above remains unchanged.
            return true
        end
        if vehicle_identity(record) == "mismatch" then
            record.release_pending = false; return true
        end
        if not is_our_vehicle(record) then return false end
        local h = record.handle
        local owned_ok, owned = pcall(Natives.InvokeBool, N.NETWORK_HAS_CONTROL, h)
        if not owned_ok or (owned ~= true and owned ~= 1) then return false end
        local ready = true
        local function release_set(hash, ...)
            local ok, control = pcall(Natives.InvokeBool, N.NETWORK_HAS_CONTROL, h)
            if not ok or (control ~= true and control ~= 1) or not is_our_vehicle(record) or record.handle ~= h then
                ready = false; return
            end
            if not native_void(hash, h, ...) then ready = false end
        end
        -- If deletion was denied, do not leave a permanent floating ghost.
        release_set(N.FREEZE_ENTITY_POSITION, false)
        if not record.ped then release_set(N.SET_VEHICLE_GRAVITY, true) end
        release_set(N.SET_ENTITY_HAS_GRAVITY, true)
        if record.ped then release_set(0x9FF447B6B6AD960A, true) end -- SET_PED_GRAVITY
        release_set(N.SET_ENTITY_COLLISION, false, true)
        release_set(N.SET_ENTITY_INVINCIBLE, false)
        release_set(N.SET_ENTITY_DYNAMIC, true)
        release_set(N.ACTIVATE_PHYSICS)
        if record.ped then
            release_set(0x9F8AA94D6D97DBF4, false)
            release_set(0xB128377056A54E2A, true)
            release_set(0xAAA34F8A7CB32098)
        end
        local native_id = verified_native_id(record)
        if native_id then
            if not native_void(N.NETWORK_SET_CAN_MIGRATE, native_id, true) then ready = false end
        end
        return ready
    end

    local function has_vehicle_control(record)
        if record.pickup then return vehicle_identity(record) == "ours" end
        local ok, owned = pcall(Natives.InvokeBool, N.NETWORK_HAS_CONTROL, record.handle)
        return ok and (owned == true or owned == 1)
    end

    local function prepare_reference_vehicle(record, pose, upright)
        if not record.ped and not record.pickup then return prepare_contained_reference(record, pose) end
        if not is_our_vehicle(record) then return false, "spawn identity unavailable" end
        if not has_vehicle_control(record) then
            pcall(Natives.InvokeBool, N.NETWORK_REQUEST_CONTROL, record.handle)
            if not is_our_vehicle(record) or not has_vehicle_control(record) then
                return false, "network control unavailable"
            end
        end
        local h = record.handle
        local native_id = verified_native_id(record)
        -- The helper can observe a conflict, control loss, or session switch. An
        -- unavailable native ID alone permits the proven handle fallback; those
        -- ownership failures do not permit subsequent mission/placement writes.
        if not is_our_vehicle(record) or not has_vehicle_control(record) or not is_our_vehicle(record)
            or record.handle ~= h then
            return false, "spawn identity or control changed"
        end
        if native_id then native_void(N.NETWORK_SET_CAN_MIGRATE, native_id, false) end
        native_void(N.SET_ENTITY_AS_MISSION, h, true, true)
        if not record.placed then
            if not pose then return false, "spawn pose missing" end
            -- A spawn helper may return after physics has already displaced or
            -- tilted the vehicle. Freeze FIRST, then commit the requested pose.
            -- Do this once at creation; never drag completed stacks after the player.
            if not native_void(N.FREEZE_ENTITY_POSITION, h, true) then return false, "initial freeze failed" end
            -- Baller teleports must preserve the stand-still task and use a
            -- true warp, not the no-warp contact/physics path.
            local preserve = record.single_kaylee == true
            if not native_void(N.SET_ENTITY_COORDS_NO_OFFSET, h, pose.x + 0.0, pose.y + 0.0, pose.z + 0.0,
                    preserve, preserve, preserve) then
                return false, "exact position failed"
            end
            if not native_void(N.SET_ENTITY_ROTATION, h, 0.0, 0.0, pose.heading + 0.0, 2, true) then
                return false, "upright rotation failed"
            end
            if not native_void(N.SET_ENTITY_VELOCITY, h, 0.0, 0.0, 0.0) then return false, "velocity reset failed" end
            -- A successful void call confirms invocation, not placement. Read the
            -- original allocation while still frozen; retries use the existing
            -- bounded setup window and never allocate a replacement vehicle.
            local read_ok, actual = pcall(function()
                local entity = GTA.HandleToPointer(h)
                return entity and coord_copy(entity.Position)
            end)
            if not is_our_vehicle(record) or record.handle ~= h then
                return false, "spawn identity unavailable after placement"
            end
            if not read_ok or not actual then return false, "position readback unavailable" end
            local dx, dy, dz = actual.x - pose.x, actual.y - pose.y, actual.z - pose.z
            -- Ten centimetres allows float roundoff without accepting a displaced car.
            if dx * dx + dy * dy + dz * dz > 0.01 then return false, "exact position not confirmed" end
            record.placed = true
        end
        -- Stationary ped circles must not push overlapping actors apart.
        -- Vehicle records use their unchanged containment/physics policies.
        if not native_void(N.SET_ENTITY_COLLISION, h, not record.ped, true) then return false, "collision state failed" end
        native_void(N.SET_ENTITY_HAS_GRAVITY, h, not record.ped)
        if not record.ped then native_void(N.SET_VEHICLE_GRAVITY, h, true) end
        native_void(N.SET_ENTITY_INVINCIBLE, h, upright)
        if upright then native_void(N.SET_ENTITY_VELOCITY, h, 0.0, 0.0, 0.0) end
        if not native_void(N.FREEZE_ENTITY_POSITION, h, upright) then return false, "final freeze failed" end
        if record.ped then
            -- Frozen overlapping peds do not need a physics restart.
            -- Optional calls may fail without changing the existing setup decision.
            if is_our_vehicle(record) and has_vehicle_control(record) then
                native_void(N.SET_ENTITY_ANGULAR_VELOCITY, h, 0.0, 0.0, 0.0)
                native_void(N.SET_ENTITY_FULL_NO_COLLISION, h, true, false)
            end
            return true
        end
        if not native_void(N.SET_ENTITY_DYNAMIC, h, true) or not native_void(N.ACTIVATE_PHYSICS, h) then
            return false, "physics activation failed"
        end
        return true
    end

    -- AI is suppressed only on peds created for Baller, and only after their
    -- original entity identity and local network control have been verified.
    -- Resetting tasks EVERY tick would cause visible twitching and falling.
    local function suppress_baller_ai(h)
        local cleared = native_void(0xAAA34F8A7CB32098, h)           -- CLEAR_PED_TASKS_IMMEDIATELY
        local blocked = native_void(0x9F8AA94D6D97DBF4, h, true)     -- block events
        native_void(0x90D2156198831D69, h, true)                     -- TASK_SET_BLOCKING_OF_NON_TEMPORARY_EVENTS
        native_void(0x6373D1349925A70E, h, false)                    -- ambient animations
        native_void(0x0EB0585D15254740, h, false)                    -- ambient base animations
        native_void(0xBAF20C5432058024, h, false)                    -- gesture animations
        native_void(0x8FD89A6240813FD0, h, true, true)               -- idle clips
        local no_ragdoll = native_void(0xB128377056A54E2A, h, false) -- ragdoll
        native_void(0xDF993EE5E90ABA25, h, false)                    -- impact ragdoll
        native_void(0xF0A4F1BBF4FA7497, h, false)                    -- ragdoll on collision
        local standing = native_void(0x919BE13EED931959, h, -1)      -- stand still indefinitely
        local retained = native_void(0x971D38760FBC02EF, h, true)    -- retain stand-still task
        return cleared and blocked and no_ragdoll and standing and retained
    end

    local function refresh_baller_ai_flags(h)
        -- Persistent flags can be reset by streamed state; refresh without
        -- clearing/restarting the stand-still task (which would animate peds).
        native_void(0x9F8AA94D6D97DBF4, h, true)
        native_void(0x6373D1349925A70E, h, false)
        native_void(0x0EB0585D15254740, h, false)
        native_void(0xBAF20C5432058024, h, false)
        native_void(0xB128377056A54E2A, h, false)
        native_void(0xDF993EE5E90ABA25, h, false)
    end

    -- The same eight poses are shared by EVERY wave. No expansion, individual
    -- layer offsets or pairwise O(n^2) collision calls. The drift round-robin
    -- also repairs peds that fall when the selected player is standing still.
    local function maintain_kaylee_records(records, allow_unplaced, follow_pose)
        local desired_by_slot
        if follow_pose and follow_pose.center then
            desired_by_slot = {}
            for slot = 1, BALLER_SLOT_COUNT do
                desired_by_slot[slot] = baller_slot_pose(slot, follow_pose.center,
                    follow_pose.ring_heading)
            end
        end
        local now = Time.GetEpocheMs()
        local total = #records
        local batch = follow_pose and math.min(total, follow_pose.probe_count or 0) or 0
        local first = follow_pose and (follow_pose.probe_start or 1) or 1
        local control_request_budget = BALLER_CONTROL_REQUESTS_PER_PASS
        for index, record in ipairs(records) do
            if record.single_kaylee and (record.placed or allow_unplaced) then
                local slot = record.baller_slot or (((record.sequence or 1) - 1) % BALLER_SLOT_COUNT) + 1
                local desired = record.placed and desired_by_slot and desired_by_slot[slot]
                local last = record.follow_pose
                local pose_changed = desired and (not last or last.x ~= desired.x
                    or last.y ~= desired.y or last.z ~= desired.z or last.heading ~= desired.heading)
                local in_probe = total > 0 and batch > 0 and ((index - first + total) % total) < batch
                local needs_harden = not record.baller_hardened_at
                    or now - record.baller_hardened_at >= BALLER_HARDEN_EVERY_MS
                local needs_ai = ((not record.baller_ai_locked)
                        and now >= (record.baller_ai_retry_at or 0))
                    or (record.baller_ai_locked and (not record.baller_ai_refreshed_at
                        or now - record.baller_ai_refreshed_at >= BALLER_AI_REFRESH_EVERY_MS))
                if needs_harden or needs_ai or pose_changed or in_probe then
                    -- A ped can lose control after the original birth. The old
                    -- hold loop simply abandoned it forever in that situation.
                    local still_ours = is_our_vehicle(record)
                    local controlled = still_ours and has_vehicle_control(record)
                    if in_probe then
                        baller_hold_trace.sampled = baller_hold_trace.sampled + 1
                        if not still_ours then
                            baller_hold_trace.identity_unknown = baller_hold_trace.identity_unknown + 1
                        elseif not controlled then
                            baller_hold_trace.denied = baller_hold_trace.denied + 1
                        end
                    end
                    if still_ours and not controlled and in_probe and control_request_budget > 0
                        and now >= (record.baller_control_retry_at or 0) then
                        -- The identity has already passed vehicle_identity's
                        -- original-model/session/network-ID checks. Recheck
                        -- again after any request, before changing the ped.
                        control_request_budget = control_request_budget - 1
                        record.baller_control_retry_at = now + BALLER_CONTROL_RETRY_MS
                        baller_hold_trace.requests = baller_hold_trace.requests + 1
                        pcall(Natives.InvokeBool, N.NETWORK_REQUEST_CONTROL, record.handle)
                        controlled = has_vehicle_control(record)
                        if controlled then
                            baller_hold_trace.recovered = baller_hold_trace.recovered + 1
                        end
                    end
                    if controlled and is_our_vehicle(record) then
                        local h = record.handle
                        if needs_harden then
                            -- Freeze before clearing AI tasks or changing pose.
                            local frozen = native_void(N.FREEZE_ENTITY_POSITION, h, true)
                            local collision_off = native_void(N.SET_ENTITY_COLLISION, h, false, true)
                            -- Optional second no-collision layer; failure must
                            -- not skip gravity and velocity suppression.
                            native_void(N.SET_ENTITY_FULL_NO_COLLISION, h, true, false)
                            local gravity_off = native_void(N.SET_ENTITY_HAS_GRAVITY, h, false)
                            local ped_gravity_off = native_void(0x9FF447B6B6AD960A, h, false)
                            local stopped = native_void(N.SET_ENTITY_VELOCITY, h, 0.0, 0.0, 0.0)
                            if frozen and collision_off and gravity_off and ped_gravity_off and stopped then
                                record.baller_hardened_at = now
                            end
                        end
                        if not record.baller_ai_locked and needs_ai then
                            record.baller_ai_locked = suppress_baller_ai(h)
                            record.baller_ai_retry_at = now + 500
                            if record.baller_ai_locked then
                                record.baller_ai_refreshed_at = now
                            end
                        elseif needs_ai then
                            refresh_baller_ai_flags(h)
                            record.baller_ai_refreshed_at = now
                        end

                        if desired then
                            local drifted = false
                            local heading_drift = false
                            if in_probe and not pose_changed then
                                local read_ok, actual = pcall(function()
                                    local ptr = GTA.HandleToPointer(h)
                                    return ptr and coord_copy(ptr.Position)
                                end)
                                if read_ok and actual then
                                    local dx, dy, dz = actual.x - desired.x, actual.y - desired.y,
                                        actual.z - desired.z
                                    drifted = dx * dx + dy * dy + dz * dz > BALLER_DRIFT_TOLERANCE_SQ
                                    if drifted then baller_hold_trace.drifted = baller_hold_trace.drifted + 1 end
                                end
                                local angle_ok, observed_heading = pcall(Natives.InvokeFloat, N.GET_ENTITY_HEADING, h)
                                if angle_ok and type(observed_heading) == "number"
                                    and observed_heading == observed_heading then
                                    heading_drift = math.abs((observed_heading - desired.heading + 180) % 360 - 180) >
                                        1.0
                                end
                            end
                            if pose_changed or drifted or heading_drift then
                                if drifted then
                                    -- Physics or streamed tasks moved this ped after
                                    -- its previous placement. Repair the freeze now.
                                    native_void(N.FREEZE_ENTITY_POSITION, h, true)
                                    native_void(N.SET_ENTITY_HAS_GRAVITY, h, false)
                                    native_void(0x9FF447B6B6AD960A, h, false)
                                    native_void(N.SET_ENTITY_VELOCITY, h, 0.0, 0.0, 0.0)
                                    record.baller_hardened_at = now
                                end
                                -- keepTasks/keepIK/doWarp = true: do not reset
                                -- the ped's stand-still task or sweep via contacts.
                                local moved = native_void(N.SET_ENTITY_COORDS_NO_OFFSET, h,
                                    desired.x, desired.y, desired.z, true, true, true)
                                local rotated = native_void(N.SET_ENTITY_ROTATION, h,
                                    0.0, 0.0, desired.heading, 2, true)
                                if moved and rotated then
                                    record.follow_pose = desired
                                    if drifted then baller_hold_trace.corrected = baller_hold_trace.corrected + 1 end
                                else
                                    baller_hold_trace.warp_failed = baller_hold_trace.warp_failed + 1
                                end
                            end
                        end
                    else
                        -- Never change an unowned/recycled handle. Recover all
                        -- locks if original control returns on a later tick.
                        record.baller_hardened_at = nil
                        record.baller_ai_locked = nil
                        record.baller_ai_refreshed_at = nil
                        record.baller_ai_retry_at = nil
                        record.follow_pose = nil
                    end
                end
            end
        end
    end

    local function apply_reference_lighting(record, config)
        if not record.ped and not record.pickup then return contained_reference_lighting(record, config) end
        if not is_our_vehicle(record) or not has_vehicle_control(record) then
            return false, "lighting setup waiting for vehicle control"
        end
        local h = record.handle
        local function v(label, hash, ...)
            local ok = native_void(hash, h, ...)
            if not ok then
                -- Cosmetic/native availability failures should not abort physics
                -- setup or flood logs once for every spawned car.
                config.lighting_errors = config.lighting_errors or {}
                config.lighting_errors[label] = (config.lighting_errors[label] or 0) + 1
            end
            return ok
        end
        v("vehicle driveable", N.SET_UNDRIVEABLE, false)
        v("keep engine running", N.KEEP_ENGINE_ON, true)
        local engine_started = v("engine start", N.SET_ENGINE_ON, true, true, false)
        v("lights on", N.SET_LIGHTS, 2)
        v("high beams", N.SET_FULLBEAM, true)
        v("xenon enable", N.TOGGLE_MOD, 22, true)
        local sequence = record.sequence or 1
        local index = (sequence - 1) % #REFERENCE_XENON_PALETTE + 1
        v("xenon colour", N.SET_XENON_COLOUR, REFERENCE_XENON_PALETTE[index])
        local r, g, b = reference_neon_colour(sequence)
        v("neon colour", N.SET_NEON_COLOUR, r, g, b)
        for side = 0, 3 do v("neon enable", N.SET_NEON_ENABLED, side, true) end
        -- Read back the actual engine state. Retry only inside the existing
        -- bounded setup window; never accept a silently failed engine start.
        local ok, running = pcall(Natives.InvokeBool, N.GET_ENGINE_RUNNING, h)
        if not engine_started or not ok or (running ~= true and running ~= 1) then
            return false, "engine start not confirmed"
        end
        return true
    end

    local function setup_reference_vehicle(record, state, count, config, stop_at)
        if record.pickup then
            -- Resolve and validate the object: pickup tokens are not entity handles.
            local object_ready = false
            for attempt = 1, REFERENCE_SETUP_ATTEMPTS do
                if abort_requested or Time.GetEpocheMs() >= stop_at then break end
                local identity = vehicle_identity(record)
                if identity == "mismatch" then return false, "pickup identity mismatch" end
                if identity == "ours" and record.object and record.object > 0 and entity_exists(record.object) then
                    object_ready = true; break
                end
                if attempt < REFERENCE_SETUP_ATTEMPTS then
                    Script.Yield(math.min(FOLLOW_EVERY_MS,
                        math.max(0, stop_at - Time.GetEpocheMs())))
                end
            end
            if not object_ready then return false, "pickup object unavailable" end
            local h = record.object
            local model_ok, model = pcall(Natives.InvokeInt, N.GET_ENTITY_MODEL, h)
            if not model_ok or normalize_model(model) ~= record.model then
                return false,
                    "pickup object identity mismatch"
            end
            if not native_void(0x4C134B4DF76025D0, record.handle, true)
                or not native_void(N.FREEZE_ENTITY_POSITION, h, false)
                or not native_void(N.SET_ENTITY_DYNAMIC, h, true)
                or not native_void(N.SET_ENTITY_HAS_GRAVITY, h, true)
                or not native_void(N.SET_ENTITY_COLLISION, h, true, true)
                or not native_void(N.ACTIVATE_PHYSICS, h) then
                return false, "pickup physics activation failed"
            end
            return true
        end
        if record.ped then
            local ready, reason
            for attempt = 1, REFERENCE_SETUP_ATTEMPTS do
                if abort_requested or Time.GetEpocheMs() >= stop_at then break end
                local pose, next_column = record.spawn_pose, nil
                if record.single_kaylee and not record.placed then
                    -- The helper can yield. Use Circle's fresh pose before placement.
                    local upright
                    pose, upright, next_column = sample_reference_pose(state, count)
                    if not pose then return false, "selected player unavailable during ped setup" end
                end
                local was_placed = record.placed
                ready, reason = prepare_reference_vehicle(record, pose, true)
                if record.single_kaylee and record.placed and not was_placed then
                    state.column = next_column; record.spawn_pose = pose
                end
                if ready then
                    if record.single_kaylee then
                        -- A freshly positioned Baller is locked again after the
                        -- initial placement and before it joins the follow loop.
                        record.baller_ai_locked = nil
                        record.baller_ai_retry_at = nil
                        record.baller_hardened_at = nil
                        maintain_kaylee_records({ record }, true)
                        if record.baller_ai_locked and record.baller_hardened_at then
                            return true
                        end
                        reason = "Baller frozen AI setup failed"
                    else
                        local h = record.handle
                        if native_void(0x9F8AA94D6D97DBF4, h, true)
                            and native_void(0xB128377056A54E2A, h, false)
                            and native_void(0x971D38760FBC02EF, h, true)
                            and native_void(0xAAA34F8A7CB32098, h)
                            and native_void(0x919BE13EED931959, h, -1)
                            and native_void(N.SET_ENTITY_HAS_GRAVITY, h, false)
                            and native_void(0x9FF447B6B6AD960A, h, false) -- SET_PED_GRAVITY
                            and native_void(N.SET_ENTITY_VELOCITY, h, 0.0, 0.0, 0.0)
                            and native_void(N.FREEZE_ENTITY_POSITION, h, true) then
                            return true
                        end
                        reason = "frozen ped setup failed"
                    end
                end
                if attempt < REFERENCE_SETUP_ATTEMPTS then
                    Script.Yield(math.min(FOLLOW_EVERY_MS,
                        math.max(0, stop_at - Time.GetEpocheMs())))
                end
            end
            return false, reason or "ped setup deadline reached"
        end
        local reason = "setup deadline reached"
        local pose, upright, next_column
        for attempt = 1, REFERENCE_SETUP_ATTEMPTS do
            if abort_requested or Time.GetEpocheMs() >= stop_at then break end
            if not record.placed then
                -- SpawnVehicle/model loading and control acquisition can yield.
                -- Aim again after those delays instead of placing at stale coords.
                pose, upright, next_column = sample_reference_pose(state, count)
                if not pose then return false, "selected player unavailable during setup" end
            end
            -- Keep the car pinned while applying appearance, including loose cars.
            local was_placed = record.placed
            local ready
            ready, reason = prepare_reference_vehicle(record, pose, true)
            if record.placed and not was_placed then state.column = next_column end
            if ready then
                if not record.preset_applied then
                    -- Apply the shared vehicle preset/customisation to boats and
                    -- planes too, without treating unsupported mods as fatal.
                    apply_preset(record.handle, config)
                    record.preset_applied = true
                end
                if not record.lighting_applied then
                    -- All reference vehicles now request engine ON and full
                    -- supported lighting; heavy-only paint remains unchanged.
                    ready, reason = apply_reference_lighting(record, config)
                    record.lighting_applied = ready
                end
                if ready then
                    ready, reason = prepare_reference_vehicle(record, nil, upright)
                    if ready then return true end
                end
            end
            if attempt < REFERENCE_SETUP_ATTEMPTS then
                -- Use quicker retries for transient placement/readback failures.
                -- Keep the original 40-ms retry when the blocker is network
                -- ownership/registration, which often takes longer to settle.
                local authority_wait = type(reason) == "string" and
                    (reason:find("containment", 1, true) or reason:find("network", 1, true)
                        or reason:find("migration", 1, true) or reason:find("authority", 1, true))
                local retry_ms = authority_wait and FOLLOW_EVERY_MS or math.min(FOLLOW_EVERY_MS, attempt * 12)
                local wait = math.min(retry_ms, stop_at - Time.GetEpocheMs())
                if wait <= 0 then break end
                Script.Yield(wait)
            end
        end
        return false, reason
    end

    -- Whole-list passes let every vehicle get a retry, without spending three
    -- blocking waits per vehicle. Always return survivors, even after an error.
    -- Summarize cached cleanup decisions only: no extra native/registry reads,
    -- no raw handles or pointers, and at most three detailed records per run.
    local function cleanup_evidence(records)
        pcall(function()
            local counts, birth_gates, capture_ends, mismatch_paths = {}, {}, {}, {}
            local function count(bucket, key) bucket[key] = (bucket[key] or 0) + 1 end
            for _, record in ipairs(records) do
                local detail = record.identity_detail or {}
                local reason = record.absence_reason or detail.final or record.cleanup_state or "not_observed"
                counts[reason] = (counts[reason] or 0) + 1
                -- Aggregate the blocked population, not just the first three births.
                -- This is cached evidence only; never issue extra entity reads here.
                if reason == "birth_proof_missing" or reason == "birth_anchor_missing" then
                    count(birth_gates, tostring((record.birth_evidence or {}).gate or "not_captured"))
                    local window = record.capture_window
                    count(capture_ends, tostring(window and (window.reason or window.last_gate) or "no_window"))
                elseif reason == "mismatch" then
                    count(mismatch_paths,
                        tostring(detail.direct) .. "/" .. tostring(detail.inverse) .. "/" .. tostring(detail.registry))
                end
                if not record.cleanup_evidence_sample and cleanup_evidence_samples < 3 then
                    cleanup_evidence_samples = cleanup_evidence_samples + 1
                    record.cleanup_evidence_sample = cleanup_evidence_samples
                    local birth, absence = record.birth_evidence or {}, record.absence_evidence or {}
                    pcall(log,
                        "Cleanup evidence: sample=" .. cleanup_evidence_samples .. " slot=" ..
                        tostring(record.lobby_pid) ..
                        " sequence=" .. tostring(record.sequence) .. " reason=" .. reason ..
                        " birthGate=" .. tostring(birth.gate or "not_captured") ..
                        " retryGate=" ..
                        tostring(record.capture_window and record.capture_window.last_gate or "not_read") ..
                        " birthWrapperState=" .. tostring(birth.wrapper_state or "not_read") ..
                        " lastWrapperState=" ..
                        tostring(detail.wrapper_state or
                            (record.capture_window and record.capture_window.last_wrapper_state) or "not_read") ..
                        " nativeGetterOk=" .. tostring(detail.native_read and detail.native_read.ok or "not_read") ..
                        " nativeGetterType=" .. tostring(detail.native_read and detail.native_read.kind or "not_read") ..
                        " nativeGetterValue=" ..
                        tostring(detail.native_read and detail.native_read.value or "not_read") ..
                        " activeRegistryMatch=" .. tostring(detail.active_registry_match or "not_read") ..
                        " captureWindow=" ..
                        tostring(record.capture_window and (record.capture_window.reason or "pending") or "ineligible") ..
                        " captureAttempts=" .. tostring(record.capture_window and record.capture_window.attempts or 0) ..
                        " birthNetObject=" ..
                        tostring(birth.netObject or "unknown") ..
                        " birthNetEntity=" .. tostring(birth.netEntity or "unknown") ..
                        " birthVehicleMatch=" ..
                        tostring(birth.vehicleMatch or "unknown") ..
                        " birthEntityMatch=" .. tostring(birth.entityMatch or "unknown") ..
                        " birthRegistryMatch=" .. tostring(birth.registryMatch or "unknown") ..
                        " birthRegistryState=" .. tostring(birth.registryState or "not_read") ..
                        " birthRegistryRoute=" ..
                        tostring(birth.registryRoute or
                            (record.capture_window and record.capture_window.last_evidence and record.capture_window.last_evidence.registryRoute) or
                            "not_read") ..
                        " direct=" ..
                        tostring(detail.direct) ..
                        " inverse=" .. tostring(detail.inverse) .. " registry=" .. tostring(detail.registry) ..
                        " netObject=" ..
                        tostring(absence.netObject or "not_read") ..
                        " netEntity=" .. tostring(absence.netEntity or "not_read") ..
                        " vehicleZero=" ..
                        tostring(absence.vehicleZero or "not_read") ..
                        " entityZero=" .. tostring(absence.entityZero or "not_read") ..
                        " allRegistry=" .. tostring(absence.registry or "not_read") ..
                        " absenceSamples=" .. tostring(record.lobby_absent_samples or 0))
                end
            end
            local parts = {}; for reason, n in pairs(counts) do parts[#parts + 1] = reason .. "=" .. n end; table.sort(
                parts)
            log("Cleanup evidence: summary retained=" .. #records .. " cachedReasons=" .. table.concat(parts, ","))
            for _, group in ipairs({ { "birthGates", birth_gates }, { "captureEnds", capture_ends }, { "mismatchPaths", mismatch_paths } }) do
                local rows = {}; for key, n in pairs(group[2]) do rows[#rows + 1] = key .. "=" .. n end; table.sort(rows)
                if #rows > 0 then log("Cleanup evidence: " .. group[1] .. "=" .. table.concat(rows, ",")) end
            end
        end)
    end
    -- New head actors keep their physical safety settings until their owned
    -- lifetime is independently terminal. Attachment order is an obligation,
    -- not an assumption about the order of a cleanup batch.
    local function head_cleanup_ready(record)
        if not record.head_rigid then return true end
        -- Deleting before delayed registration is captured destroys the only
        -- opportunity to verify network absence, leaving permanent tracker debt.
        -- vehicle_identity advances capture while this original actor is present.
        if record.capture_window and not record.capture_window.closed
            and not record.lobby_absence_proof then
            record.head_cleanup_result = "registration_pending"
            return false
        end
        local pair = record.head_pair
        local child = record.head_child or (pair and pair.child)
        if record.head_child_pending or (pair and pair.child_pending)
            or (child and child ~= record and not child.head_cleanup_terminal) then
            record.head_cleanup_result = "child_pending"
            return false
        end
        if record.head_independent == true then
            local h = record.handle
            local function owned()
                if session_state(record.session_key) ~= "same" or not is_our_vehicle(record) then return false end
                local ok, control = pcall(Natives.InvokeBool, N.NETWORK_HAS_CONTROL, h)
                return ok and (control == true or control == 1) and record.handle == h
                    and is_our_vehicle(record) and session_state(record.session_key) == "same"
            end
            local function link()
                local aok, attached = pcall(Natives.InvokeBool, 0xB346476EF1A64897, h)
                local pok, parent = pcall(Natives.InvokeInt, 0x48C2BED9180FE123, h)
                if not aok or not pok or type(parent) ~= "number" or parent ~= parent or parent < 0
                    or parent == math.huge or parent % 1 ~= 0 then
                    return "unknown"
                end
                if (attached == false or attached == 0) and parent == 0 then return "unattached" end
                if (attached == true or attached == 1) and parent > 0 then return "attached" end
                return "unknown"
            end
            if not owned() then
                if is_our_vehicle(record) and session_state(record.session_key) == "same" then
                    pcall(Natives.InvokeBool, N.NETWORK_REQUEST_CONTROL, h)
                end
                if not owned() then
                    record.head_cleanup_result = "independent_control_pending"; return false
                end
            end
            local state = link()
            if state == "unknown" or not owned() then
                record.head_cleanup_result = "independent_attachment_unknown"; return false
            end
            state = link()
            if state == "unknown" then
                record.head_cleanup_result = "independent_attachment_unknown"; return false
            end
            if state == "attached" then
                -- An external parent is never ours by implication. Detach only the
                -- original controlled child and require observed release before
                -- the shared lifetime/absence cleanup may delete that child.
                if not owned() then
                    record.head_cleanup_result = "independent_control_pending"; return false
                end
                local called = native_void(0x961AC54BF0613F5D, h, false, false)
                if not called then
                    record.head_cleanup_result = "independent_detach_unconfirmed"; return false
                end
            end
            if not owned() or link() ~= "unattached" or record.handle ~= h or record.head_independent ~= true then
                record.head_cleanup_result = "independent_detach_unconfirmed"; return false
            end
            record.head_detached = true
            return true
        end
        local parent = record.head_parent or record.head_pair_parent
        local target_attachment = record.head_target_attachment
        if not parent and not target_attachment then return true end
        local h = record.handle
        local function owned()
            if session_state(record.session_key) ~= "same" or not is_our_vehicle(record) then return false end
            local ok, control = pcall(Natives.InvokeBool, N.NETWORK_HAS_CONTROL, h)
            return ok and (control == true or control == 1) and record.handle == h
                and is_our_vehicle(record) and session_state(record.session_key) == "same"
        end
        if not owned() then
            if is_our_vehicle(record) and session_state(record.session_key) == "same" then
                pcall(Natives.InvokeBool, N.NETWORK_REQUEST_CONTROL, h)
            end
            if not owned() then
                record.head_cleanup_result = "control_or_identity_pending"; return false
            end
        end
        local ok, attached = pcall(Natives.InvokeBool, 0xB346476EF1A64897, h)
        if not ok or (attached ~= false and attached ~= 0 and attached ~= true and attached ~= 1)
            or not owned() then
            record.head_cleanup_result = "attachment_unknown"; return false
        end
        if attached == false or attached == 0 then
            record.head_detached = true; return true
        end
        if target_attachment then
            -- Only the child is ours. A missing/reused/mismatched borrowed parent
            -- revokes following, but cannot veto detaching our original controlled
            -- child. No ownership, control request or mutation targets the parent.
            local read, to = pcall(Natives.InvokeInt, 0x48C2BED9180FE123, h)
            record.head_attachment_parent_observed = read and to or nil
            if read and to ~= target_attachment.handle then
                record.head_attachment_revoked = true; record.head_follow_state = "revoked"
            end
            if not owned() then
                record.head_cleanup_result = "control_or_identity_pending"; return false
            end
            local called = native_void(0x961AC54BF0613F5D, h, false, false)
            local observed, after = pcall(Natives.InvokeBool, 0xB346476EF1A64897, h)
            if not called or not observed or (after ~= false and after ~= 0) or not owned() then
                record.head_cleanup_result = "detach_unconfirmed"; return false
            end
            record.head_detached = true
            return true
        end
        local read, to = pcall(Natives.InvokeInt, 0x48C2BED9180FE123, h)
        if not read or to ~= parent.handle or not parent.head_rigid or not is_our_vehicle(parent)
            or session_state(parent.session_key) ~= "same" or not owned() then
            record.head_cleanup_result = "attachment_identity_pending"; return false
        end
        -- Re-read the exact attachment after the other ownership observations.
        local checked, still = pcall(Natives.InvokeInt, 0x48C2BED9180FE123, h)
        if not checked or still ~= parent.handle or not owned()
            or not is_our_vehicle(parent) or not owned()
            or session_state(parent.session_key) ~= "same" or session_state(record.session_key) ~= "same" then
            record.head_cleanup_result = "attachment_identity_pending"; return false
        end
        local called = native_void(0x961AC54BF0613F5D, h, false, false)
        local observed, after = pcall(Natives.InvokeBool, 0xB346476EF1A64897, h)
        if not called or not observed or (after ~= false and after ~= 0) or not owned() then
            record.head_cleanup_result = "detach_unconfirmed"; return false
        end
        record.head_detached = true
        return true
    end

    local function cleanup_vehicles(records, passes, stop_at, options)
        options = options or {}
        local remaining = records
        local deleted, unavailable, denied, failed_calls = 0, 0, 0, 0
        local ptr
        local function note_record_error(record, reason)
            failed_calls = failed_calls + 1
            record.cleanup_error_count = math.min(65535, (record.cleanup_error_count or 0) + 1)
            record.cleanup_error = type(reason) == "string" and reason:sub(1, 240) or type(reason)
            if not record.cleanup_error_reported then
                record.cleanup_error_reported = true
                pcall(warn, "Cleanup retained one errored record; continuing other records: " .. record.cleanup_error)
            end
        end
        local ok, err = pcall(function()
            ptr = Memory.AllocInt()
            for pass = 1, passes do
                local survivors = {}
                for i = #remaining, 1, -1 do
                    if disposed or (stop_at and Time.GetEpocheMs() >= stop_at) then
                        for index = i, 1, -1 do survivors[#survivors + 1] = remaining[index] end
                        break
                    end
                    local record = remaining[i]
                    local record_ok, record_error = pcall(function()
                        if record.lifetime_trace then
                            record.lifetime_trace.cleanup_at = record.lifetime_trace
                                .cleanup_at or Time.GetEpocheMs()
                        end
                        local identity = vehicle_identity(record)
                        record.cleanup_state = identity
                        if record.head_rigid and not record.head_cleanup_terminal then
                            record.head_cleanup_result = identity == "ours" and "owned_pending" or "mismatch_or_unknown"
                        end
                        lifetime_evidence(record, "cleanup_" .. identity, identity)
                        if record.lifetime_trace then
                            for _, age in ipairs({ 200, 1000, 5000 }) do
                                local phase = "cleanup_age" .. age
                                if Time.GetEpocheMs() - record.lifetime_trace.cleanup_at >= age and not record.lifetime_trace.seen[phase] then
                                    lifetime_evidence(record, phase, identity); break
                                end
                            end
                        end
                        local removed = false
                        if record.pickup then
                            if identity == "ours" then
                                local called = native_void(0x3288D8ACAECD2AB2, record.handle)
                                removed = called and vehicle_identity(record) == "mismatch"
                                if not called then failed_calls = failed_calls + 1 end
                            end
                        elseif identity == "ours" and head_cleanup_ready(record) then
                            if not has_vehicle_control(record) then
                                pcall(Natives.InvokeBool, N.NETWORK_REQUEST_CONTROL, record.handle)
                            end
                            -- Recheck identity after requesting control, before mutation.
                            if is_our_vehicle(record) and has_vehicle_control(record) and is_our_vehicle(record) then
                                native_void(N.SET_ENTITY_AS_MISSION, record.handle, true, true)
                                record.capture_delete_started = true
                                close_creation_capture(record, "delete_started")
                                lifetime_evidence(record, "delete_requested", "ours")
                                -- Diagnostics and host callbacks may yield or change
                                -- identity. Revalidate after them, immediately before
                                -- writing the current handle into the deletion argument.
                                local called
                                if is_our_vehicle(record) and has_vehicle_control(record) and is_our_vehicle(record) then
                                    Memory.WriteInt(ptr, record.handle)
                                    lifetime_delete_attempt(record)
                                    called = native_void(record.ped and 0x9614299DCB53E54B or N.DELETE_VEHICLE, ptr)
                                    if record.head_rigid then
                                        record.head_cleanup_result = called and
                                            "delete_requested_unconfirmed" or "delete_call_failed"
                                    end
                                    if record.lifetime_trace then
                                        record.lifetime_trace.last_invocation = called and
                                            "returned" or "failed"
                                    end
                                    lifetime_evidence(record, "delete_returned")
                                    if called then record.delete_requested_at = Time.GetEpocheMs() end
                                    if not called then failed_calls = failed_calls + 1 end
                                else
                                    lifetime_record_event(record, "delete_skipped", "identity_or_control_changed")
                                end
                                -- Void calls and a missing local handle are not proof of
                                -- network destruction. The identity path below can retire
                                -- corroborated absence, separately from deletion credit.
                                if is_our_vehicle(record) then
                                    lifetime_evidence(record, "fallback_delete_requested", "ours")
                                    if is_our_vehicle(record) and has_vehicle_control(record) and is_our_vehicle(record) then
                                        Memory.WriteInt(ptr, record.handle)
                                        lifetime_delete_attempt(record)
                                        called = native_void(N.DELETE_ENTITY, ptr)
                                        if record.head_rigid then
                                            record.head_cleanup_result = called and
                                                "delete_requested_unconfirmed" or "delete_call_failed"
                                        end
                                        if record.lifetime_trace then
                                            record.lifetime_trace.last_invocation = called and
                                                "returned" or "failed"
                                        end
                                        lifetime_evidence(record, "fallback_delete_returned")
                                        if called then record.delete_requested_at = Time.GetEpocheMs() end
                                        if not called then failed_calls = failed_calls + 1 end
                                    else
                                        lifetime_record_event(record, "fallback_delete_skipped",
                                            "identity_or_control_changed")
                                    end
                                end
                            else
                                denied = denied + 1
                                if record.lobby_pid ~= nil then lobby_count("control_denials") end
                            end
                        elseif identity == "unavailable" then
                            unavailable = unavailable + 1
                            if record.lobby_pid ~= nil then lobby_count("unavailable_checks") end
                        end
                        if removed then
                            deleted = deleted + 1
                            if record.lobby_pid ~= nil then lobby_count("deleted") end
                        elseif vehicle_identity(record) ~= "mismatch" or ((record.lobby_reuse or record.head_rigid
                                    or (record.lobby_pid ~= nil and record.lobby_anchor ~= nil))
                                and session_state(record.session_key) ~= "changed" and not record.lobby_absence_confirmed) then
                            -- Streaming absence is not proof of deletion. Keep the
                            -- original handle and identity; never chase recycled IDs.
                            survivors[#survivors + 1] = record
                        else
                            if record.head_rigid then
                                record.head_cleanup_terminal = true
                                record.head_cleanup_result = record.absence_reason == "session_changed" and
                                    "session_changed" or "confirmed_absence"
                            end
                            lifetime_record_event(record, "retired",
                                record.absence_reason == "session_changed" and "session_changed" or
                                (record.identity_detail or {}).final or "identity_mismatch")
                        end
                    end)
                    if not record_ok then
                        -- One faulty host read/write must not permanently starve
                        -- the other proven-owned records in this reversed batch.
                        -- Keep this exact obligation; only its normal identity and
                        -- absence paths may later authorize deletion/retirement.
                        survivors[#survivors + 1] = record
                        note_record_error(record, record_error)
                    end
                end
                remaining = survivors
                if #remaining == 0 or abort_requested then break end
                if pass < passes then
                    local wait = CLEANUP_RETRY_MS
                    if stop_at then wait = math.min(wait, stop_at - Time.GetEpocheMs()) end
                    if wait <= 0 then break end
                    Script.Yield(wait)
                end
            end
        end)
        if ptr then pcall(Memory.Free, ptr) end
        if not ok then warn("Cleanup will retry retained records: " .. tostring(err)) end
        if #records > 0 and not options.quiet then
            log("Cleanup: deleted=" .. deleted .. ", retained=" .. #remaining ..
                ", unavailable checks=" .. unavailable .. ", control denials=" .. denied ..
                ", native errors=" .. failed_calls)
        end
        -- Only release vehicles we still own. If control is absent, keep the
        -- identity record for another attempt rather than claiming release worked.
        if options.release ~= false and not disposed then
            for _, record in ipairs(remaining) do
                if disposed then break end
                local released, release_error = pcall(function()
                    if is_our_vehicle(record) and has_vehicle_control(record) and is_our_vehicle(record) and not disposed then
                        release_vehicle(record)
                    end
                end)
                if not released then note_record_error(record, release_error) end
            end
        end
        return remaining
    end

    -- Only the post-run phase removes entities. Small, rotating batches keep
    -- cleanup bounded per frame and prevent an unavailable first record starving others.
    local function cleanup_batch(token)
        local batch, waiting = {}, {}
        for i, record in ipairs(tracked_vehicles) do
            local into = i <= 32 and batch or waiting
            into[#into + 1] = record
        end
        local remaining = cleanup_vehicles(batch, 1, cleanup_until, { quiet = true })
        if token and owner_token ~= token then return end
        for _, record in ipairs(remaining) do waiting[#waiting + 1] = record end
        tracked_vehicles = waiting
    end
    local function foreground_cleanup_ms() return FOREGROUND_CLEANUP_MS end
    local function cleanup_after_run()
        local token = owner_token
        if status.phase ~= "cleanup" or cleanup_until == 0 then
            status.phase = "cleanup"; status.started = Time.GetEpocheMs()
            cleanup_until = status.started + foreground_cleanup_ms()
        end
        cleanup_peak = math.max(cleanup_peak, pending_cleanup_count())
        if baller.pending_switch ~= nil then
            -- Complete one bounded pass, then yield the producer to the next
            -- effect. The independent tick retains all remaining records.
            cleanup_batch(token)
            return
        end
        while #tracked_vehicles > 0 and Time.GetEpocheMs() < cleanup_until and not disposed do
            if owner_token ~= token then return end
            touch_job(token, "post-run cleanup")
            cleanup_batch(token)
            if owner_token ~= token then return end
            if #tracked_vehicles == 0 then break end
            local wait = math.min(FOLLOW_EVERY_MS, cleanup_until - Time.GetEpocheMs())
            if wait <= 0 then break end
            -- Cancellation stops spawning; cleanup uses the raw yield so that
            -- the normal cancellation fence does not abort restoration/deletion.
            raw_script.Yield(wait)
        end
    end

    -- Share actual pool and network admission across the ordinary and reusable
    -- producers. Unknown counters remain distinct from a confirmed capacity limit.
    local function entity_room(kind, amount, network_headroom)
        local pool = host.PoolMgr
        local ped = kind == "ped"
        local current = ped and "GetCurrentPedCount" or "GetCurrentVehicleCount"
        local maximum = ped and "GetMaxPedCount" or "GetMaxVehicleCount"
        local reserve = ped and PED_POOL_HEADROOM or LOBBY_POOL_HEADROOM
        if not pool or type(pool[current]) ~= "function" or type(pool[maximum]) ~= "function" then
            return false, kind .. " pool counters unavailable"
        end
        local ok, used = pcall(pool[current]); local cap_ok, capacity = pcall(pool[maximum])
        if not ok or not cap_ok or type(used) ~= "number" or type(capacity) ~= "number"
            or used ~= used or capacity ~= capacity or used < 0 or used >= math.huge or used % 1 ~= 0 or capacity % 1 ~= 0
            or capacity <= reserve or capacity > 1000000 then
            return false, kind .. " pool counters unavailable"
        end
        if ped then
            lobby_diagnostics.ped_pool_used = used; lobby_diagnostics.ped_pool_capacity = capacity
        else
            lobby_diagnostics.pool_used = used; lobby_diagnostics.pool_capacity = capacity
        end
        if used + amount + lobby_inflight + reserve > capacity then
            return false, kind .. " pool headroom exhausted"
        end
        local admitted, room = pcall(Natives.InvokeBool, ped and 0xBCBF4FEF9FA5D781 or 0x7277F1F2E085EE74,
            amount + lobby_inflight + (network_headroom or 0))
        if not admitted or (room ~= true and room ~= 1 and room ~= false and room ~= 0) then
            return false, "network " .. kind .. " capacity unavailable"
        end
        if room ~= true and room ~= 1 then return false, "network " .. kind .. " capacity exhausted" end
        return true
    end
    local function release_ped_models()
        for _, model in ipairs(active_ped_models or {}) do native_void(0xE532F5D78798DAAB, model) end
        active_ped_models = nil
    end
    local function release_orphan_models(token)
        local active = {}
        for _, model in ipairs(active_ped_models or {}) do active[model] = true end
        for _, model in ipairs(orphan_model_leases[token] or {}) do
            if not active[model] then native_void(0xE532F5D78798DAAB, model) end
        end
        orphan_model_leases[token] = nil
    end
    local function load_ped_models(models, stop_at)
        active_ped_models = models
        for _, model in ipairs(models) do
            if not native_void(0x963D27A58DF860AC, model) then return false end
        end
        repeat
            local ready = true
            for _, model in ipairs(models) do
                local ok, loaded = pcall(Natives.InvokeBool, 0x98A4EB5D89A0C952, model)
                if not ok or (loaded ~= true and loaded ~= 1) then ready = false end
            end
            if ready then return true end
            if abort_requested or Time.GetEpocheMs() >= stop_at then return false end
            Script.Yield(math.min(40, stop_at - Time.GetEpocheMs()))
        until false
    end

    -- Persistent independently owned actors at one captured target-body position.
    -- Per-model targets remain subordinate to pool, network and tracker capacity.
    local function head_connection(pid)
        local ok, id = pcall(function()
            local p = Players.GetById(pid)
            if not p then return end
            local address, cxn = p:GetAddress(), p.CxnId
            local gamer = p:GetGamerInfo()
            if type(address) ~= "number" or address <= 0 or address % 1 ~= 0 or type(cxn) ~= "number" or cxn % 1 ~= 0
                or not gamer or gamer.RockstarId == nil then
                return
            end
            return { pid = pid, address = address, cxn = cxn, rid = tostring(gamer.RockstarId) }
        end)
        return ok and id or nil
    end
    function baller.Same(a, b)
        return a and b and a.pid == b.pid and a.address == b.address and a.cxn == b.cxn and a.rid == b.rid
    end

    function baller.Current(request)
        if not request or baller.intent ~= request or disposed then return false end
        local connections = request.connections
        local valid = connections and session_state(request.session) == "same"
            and baller.Same(connections.target, head_connection(request.pid))
            and baller.Same(connections.local_player, head_connection(connections.local_player.pid))
            and session_state(request.session) == "same"
        return valid and baller.intent == request and not disposed
    end

    local function run_burst(player_id, mode, reference_preset, variant, formation, token, options)
        options = options or {}
        local duration = options.lobby and LOBBY_BURST_MS or DURATION_MS
        token = token or generation
        local run_session = active_session_key
        local refresh_baller_on_yield
        local Script = {
            Yield = function(ms)
                raw_script.Yield(ms)
                if disposed or generation ~= token or abort_requested or session_state(run_session) ~= "same" then
                    error(
                        cancel_signal, 0)
                end
                -- Network registration/identity waits also yield. Keep existing
                -- Baller peds following during those waits, not just between spawns.
                if refresh_baller_on_yield then refresh_baller_on_yield() end
                touch_job(token, "spawn scheduler")
            end
        }
        reference_preset = reference_preset or REFERENCE_PRESET
        local current = Players.GetById(player_id)
        if not current or current:IsLocalPlayer() then
            log("Select another online player first")
            return
        end
        local ok_id, rid = pcall(function() return current:GetGamerInfo().RockstarId end)
        if not ok_id then rid = nil end
        local duo = formation == "duo"
        local monkey = formation == "monkey"
        local ped_effect = options.single_kaylee == true or duo or monkey
        local ped_limit = options.single_kaylee == true and baller_requested_count() or PED_ACTIVE_LIMIT
        if ped_effect and type(GTA.CreatePed) ~= "function" then
            warn("Cherax ped spawn helper unavailable"); return
        end
        local config, config_err
        if options.cached_config and options.single_kaylee ~= true then
            config = options.cached_config
        elseif ped_effect then
            local specs = options.single_kaylee == true and { { name = "ig_kaylee", kind = 4 } }
                or (monkey and PED_MODELS or
                    { { name = "player_two", kind = 4 }, { name = "player_zero", kind = 4 } })
            local models, types = {}, {}
            for i, spec in ipairs(specs) do
                models[i] = normalize_model(Utils.Joaat(spec.name)); types[i] = spec.kind
                local ok, is_ped = pcall(Natives.InvokeBool, 0x75816577FEA6DAD5, models[i] or 0)
                if not models[i] or not ok or (is_ped ~= true and is_ped ~= 1) then
                    warn("Ped model unavailable: " .. spec.name); return
                end
            end
            local room, detail = entity_room("ped", options.single_kaylee == true and 1 or 2)
            if not room then
                warn("Ped circle not started: " .. detail); return
            end
            if not load_ped_models(models, math.min(status.started + DURATION_MS, Time.GetEpocheMs() + 5000)) then
                warn("Ped circle model loading timed out"); return
            end
            config = { model = models[1], models = models, types = types }
        elseif variant and variant.preset == "" then
            local model = tonumber(variant.model)
            if not model then
                local ok, value = pcall(Utils.Joaat, variant.model)
                model = ok and value or nil
            end
            model = normalize_model(model)
            local ok, vehicle = pcall(Natives.InvokeBool, N.IS_MODEL_A_VEHICLE, model or 0)
            if model and ok and (vehicle == true or vehicle == 1) then
                config = { model = model, mods = {}, extras = {}, primaryColor = 0, secondaryColor = 0 }
            else
                config_err = "Invalid vehicle model: " .. tostring(variant.model)
            end
        elseif mode == "deluxo" then
            config, config_err = load_saved_vehicle("deluxo", Utils.Joaat("deluxo"))
        else
            config, config_err = load_saved_vehicle(reference_preset)
        end
        if not config then
            warn(config_err); return
        end
        -- Only style a real Hunter, even if the user's variant configuration
        -- points to a custom preset or another model.
        local hunter_model = options.hunter_style == true
            and normalize_model(config.model) == normalize_model(Utils.Joaat("hunter"))
        if generation ~= token or owner_token ~= token then return end
        if mode == "reference" then log("Vehicle source=" .. reference_preset .. "; model=" .. config.model) end

        -- Retained leftovers consume capacity, but are never deleted during a run.
        local requested_count = options.single_kaylee == true and baller_requested_count() or options.preview_limit or
            (options.lobby and LOBBY_BURST_LIMIT or
                (ped_effect and ped_limit or (mode == "reference"
                    and (options.optimized_vehicle == true and REGULAR_VEHICLE_TUNING.limit or REFERENCE_ACTIVE_LIMIT)
                    or MAX_VEHICLES)))
        local available_slots = math.max(0, MAX_TRACKED_VEHICLES - #tracked_vehicles - lobby_inflight)
        if ped_effect then
            local retained_peds = 0
            for _, record in ipairs(tracked_vehicles) do if record.ped then retained_peds = retained_peds + 1 end end
            available_slots = math.min(available_slots, math.max(0, ped_limit - retained_peds))
        end
        if options.partial_backlog == true then
            -- Cargo can use remaining slots without demanding an empty tracker.
            -- Retained entities still count against the legacy pool ceiling.
            available_slots = math.min(available_slots, math.max(0,
                REGULAR_VEHICLE_TUNING.legacy_tracked_limit - #tracked_vehicles - lobby_inflight))
        end
        local run_limit = math.min(requested_count, available_slots)
        -- A previous visual may still be cleaning up. Run the next effect
        -- with the verified free space instead of demanding an empty tracker.
        -- The hard entity cap and network pool checks remain authoritative.
        if run_limit == 0 then
            warn("Entity budget full; retaining cleanup ownership until a slot becomes available")
            return
        end
        if #tracked_vehicles > 0 then
            log("Cleanup backlog: retained=" .. #tracked_vehicles .. ", live limit=" .. run_limit)
        end
        -- Request the regular vehicle model before target/position preflight.
        -- This overlaps normal setup with streaming, without skipping model,
        -- identity, network-control or cleanup checks.
        local warm_model = nil
        if mode == "reference" and (formation == "target_stack" or formation == "tug_overlap"
                or options.optimized_vehicle == true) then
            local checked, loaded = pcall(Natives.InvokeBool, N.HAS_MODEL_LOADED, config.model)
            if not checked or (loaded ~= true and loaded ~= 1) then
                local requested, result = pcall(Natives.InvokeVoid, N.REQUEST_MODEL, config.model)
                if requested and result ~= false then warm_model = config.model end
            end
        end
        local function release_warm_model()
            if warm_model then
                pcall(Natives.InvokeVoid, N.RELEASE_MODEL, warm_model)
                warm_model = nil
            end
        end
        local shuttle = variant and variant.view == "shuttle"
        -- Baller is independent of the invoking user's location: do not
        -- snapshot, freeze, teleport, or later restore the local character.
        -- Other effect routes keep their original local-view lifecycle.
        local no_local_hover = options.single_kaylee == true or baller.AutoTPRequested()
        local original, original_err
        if not no_local_hover then
            original = options.origin
            if not original then original, original_err = snapshot_local() end
            if not original then
                warn(original_err); release_warm_model(); return
            end
            original.session_key = run_session
        end
        local target_pos = valid_target(player_id, rid)
        if not target_pos then
            warn("Selected player's ped is unavailable"); release_warm_model(); return
        end
        if disposed or generation ~= token or abort_requested then
            release_warm_model(); return
        end

        local spawned = {}
        local stream_active = {}
        local stream_state = {
            base_z = target_pos.z,
            player_id = player_id,
            rid = rid,
            formation = formation,
            single_kaylee = options.single_kaylee == true,
            -- Steroid/Avisa shares the circle shape but retains its own original
            -- timing and anchor. Fast following is solely Vehicle Circle.
            circle_live = options.circle_stream == true,
            heading = target_heading(player_id, original and original.heading or 0.0),
        }
        if options.single_kaylee == true then
            stream_state.baller_ring_heading = stream_state.heading
        end
        if duo then
            stream_state.fixed_pose = {
                x = target_pos.x,
                y = target_pos.y,
                z = target_pos.z + 0.15,
                heading =
                    stream_state.heading
            }
        end
        if duo then
            stream_state.ped_slot_base = 0
            for _, record in ipairs(tracked_vehicles) do
                if record.ped then stream_state.ped_slot_base = stream_state.ped_slot_base + 1 end
            end
        end
        local stream_paused = false
        local setup_failures, consecutive_setup_failures, setup_stopped = 0, 0, false
        local spawn_failures, consecutive_spawn_failures = 0, 0
        local active_limit, recycle_retry_at = run_limit, 0
        local finish_reason = "duration complete"
        local first_failure_reason
        local function stop_spawning(reason)
            setup_stopped = true
            first_failure_reason = first_failure_reason or reason
            finish_reason = first_failure_reason
        end
        if not no_local_hover then active_origin = original end
        abort_requested = false
        local count = 0
        local started = (ped_effect and options.single_kaylee ~= true) and status.started or Time.GetEpocheMs()
        local deadline = started + duration
        status.deadline = deadline
        local cleanup_at = deadline
        local next_spawn = started
        local next_kaylee_hold = started
        if options.single_kaylee == true then
            baller_hold_trace = {
                sampled = 0,
                denied = 0,
                requests = 0,
                recovered = 0,
                drifted = 0,
                corrected = 0,
                warp_failed = 0,
                identity_unknown = 0
            }
            stream_state.baller_log_at = started + BALLER_OWNERSHIP_LOG_MS
            refresh_baller_on_yield = function()
                local now = Time.GetEpocheMs()
                if now < next_kaylee_hold then return end
                local raw_center = valid_target(player_id, rid)
                local center = raw_center and sample_target_motion(stream_state, raw_center)
                local total = #spawned
                local first = (stream_state.baller_probe_cursor or 0) + 1
                stream_state.baller_probe_cursor = total > 0
                    and ((first - 1 + BALLER_DRIFT_BATCH) % total) or 0
                if center then
                    local previous = stream_state.baller_last_center
                    maintain_kaylee_records(spawned, true, {
                        center = center,
                        ring_heading = stream_state.baller_ring_heading,
                        probe_start = first,
                        probe_count = BALLER_DRIFT_BATCH,
                    })
                else
                    -- During a temporary target streaming gap, keep local owned
                    -- peds frozen without inventing a target position.
                    maintain_kaylee_records(spawned, true, {
                        probe_start = first, probe_count = BALLER_DRIFT_BATCH,
                    })
                end
                next_kaylee_hold = Time.GetEpocheMs() + BALLER_HOLD_EVERY_MS
                if now >= stream_state.baller_log_at then
                    -- No extra per-entity reads: summary uses sampled checks
                    -- already performed by the existing drift/hold pass.
                    local t = baller_hold_trace
                    log(string.format(
                        "Baller hold diagnostics: tracked=%d sampled=%d controlDenied=%d controlRequests=%d controlRecovered=%d identityUnknown=%d drifting=%d corrected=%d warpFailed=%d",
                        #spawned, t.sampled, t.denied, t.requests, t.recovered,
                        t.identity_unknown, t.drifted, t.corrected, t.warp_failed))
                    baller_hold_trace = {
                        sampled = 0,
                        denied = 0,
                        requests = 0,
                        recovered = 0,
                        drifted = 0,
                        corrected = 0,
                        warp_failed = 0,
                        identity_unknown = 0
                    }
                    stream_state.baller_log_at = Time.GetEpocheMs() + BALLER_OWNERSHIP_LOG_MS
                end
            end
        end
        local kaylee_wave_target = math.min(BALLER_FIRST_WAVE, baller_requested_count())
        local kaylee_wave_resume = nil
        local reference_mode = mode == "reference"
        local circle_stream = reference_mode and formation == "circle"
            and options.circle_stream == true
        local spawn_interval = circle_stream and CIRCLE_SPAWN_EVERY_MS or
            (ped_effect and PED_SPAWN_EVERY_MS or
                (variant and not variant.reference_timing and VARIANT_SPAWN_EVERY_MS or REFERENCE_SPAWN_EVERY_MS))
        if options.optimized_vehicle == true and not ped_effect and not options.lobby then
            -- Keep existing batches, budgets and ownership checks unchanged.
            -- Only regular vehicle effects run at a modestly tighter interval.
            spawn_interval = circle_stream and REGULAR_VEHICLE_TUNING.circle_ms
                or (variant and not variant.reference_timing
                    and REGULAR_VEHICLE_TUNING.variant_ms or REGULAR_VEHICLE_TUNING.reference_ms)
        end
        -- The time budget bounds reference attempts, including failed spawns.
        local spawn_limit = options.lobby and LOBBY_BURST_LIMIT or
            (reference_mode and math.ceil(DURATION_MS / spawn_interval) or MAX_VEHICLES)
        if duo then spawn_limit = spawn_limit * 2 end
        if options.total_spawn_limit then
            spawn_limit = math.min(spawn_limit, options.total_spawn_limit)
        end
        -- The user-editable ceiling controls attempts, tracked slots and UI.
        if options.single_kaylee == true then spawn_limit = baller_requested_count() end
        if options.partial_backlog == true then
            -- Never attempt more new births than the capacity reserved at admission.
            spawn_limit = math.min(spawn_limit, run_limit)
        end
        local function place_current_leg()
            if shuttle and math.floor((Time.GetEpocheMs() - started) / 500) % 2 == 1 then
                if not hold_local(original) then return false end
                local p = original.position
                original.hold_position = p
                native_void(0x07503F7948F491A7, p.x, p.y, p.z)
                native_void(N.SET_ENTITY_COORDS_NO_OFFSET, original.handle, p.x, p.y, p.z, true, true, false)
                return true
            end
            return place_above(original, target_pos)
        end
        local function recover_target_pose()
            local stop_at = cleanup_at
            local waiting = false
            while not abort_requested do
                local position, detail = valid_target(player_id, rid)
                if position then
                    if waiting then
                        stream_state.column = nil
                        stream_state.base_z = position.z
                        log("Selected player streamed back in; resuming within the original deadline")
                    end
                    return position
                end
                -- A connected player can briefly lose its ped during respawn or
                -- streaming. Do not confuse that with a disconnect or slot reuse.
                if detail ~= "ped unavailable" and detail ~= "position unavailable" then return nil end
                -- Continue the legs through a brief streaming gap so a home leg
                -- cannot strand us away from the target until the retry expires.
                if shuttle and not place_current_leg() then return nil end
                local remaining = stop_at - Time.GetEpocheMs()
                if remaining <= 0 then return nil end
                if not waiting then log("Spawn stream waiting briefly for the selected player's ped") end
                waiting = true
                Script.Yield(math.min(FOLLOW_EVERY_MS, remaining))
            end
        end
        local function positive_id(value)
            return type(value) == "number" and value == value and value > 0 and value < math.huge and value % 1 == 0
        end
        local function reject_birth(record, reason)
            -- A partial/contradictory observation cannot replace the original birth.
            -- Keep the immediately claimed allocation as unresolved cleanup debt.
            record.lobby_anchor = nil; record.registry_birth_proof = nil; record.lobby_absence_proof = nil
            record.native_absence_proof = nil; record.capture_window = nil
            record.birth_evidence = { gate = reason }
        end
        local function capture_burst_birth(record)
            local handle, model = record.handle, record.model
            local observed, born = pcall(function() return lobby_pointer_identity(GTA.HandleToPointer(handle)) end)
            record.spawn_birth = observed and born or nil
            local got, initial = pcall(Natives.InvokeInt, N.NETWORK_GET_ID, handle)
            record.net_id = got and positive_id(initial) and initial or 0
            if not observed or not born or born.model ~= model or session_state(run_session) ~= "same" then
                record.birth_evidence = { gate = "selected_birth_pointer_missing" }; return
            end
            local captured = pcall(function() capture_lobby_identity(record) end)
            local anchor = record.lobby_anchor
            local checked, final = pcall(function() return lobby_pointer_identity(GTA.HandleToPointer(handle)) end)
            if not (captured and anchor and anchor.address == born.address and anchor.model == born.model
                    and (not born.wrapper or anchor.wrapper == born.wrapper)
                    and checked and final and final.address == born.address and final.model == born.model
                    and (not born.wrapper or final.wrapper == born.wrapper) and session_state(run_session) == "same") then
                reject_birth(record, "selected_birth_identity_interrupted"); return
            end
            if not positive_id(anchor.native) then
                local window = record.capture_window
                if not window or window.closed or not window.allow_initial_native then
                    reject_birth(record, "selected_birth_native_missing")
                end
                return
            end
            if positive_id(anchor.native) then
                if positive_id(record.net_id) and record.net_id ~= anchor.native then
                    reject_birth(record, "selected_birth_native_changed"); return
                end
                -- An unknown preliminary getter is not a contradictory identity.
                -- Adopt only this original physical birth's captured ID. An
                -- initially missing ID can also arrive within its capture window.
                record.net_id = anchor.native
            end
        end
        local function burst_birth_state(record)
            local born, anchor = record.spawn_birth, record.lobby_anchor
            if not born or not anchor or anchor.address ~= born.address or anchor.model ~= born.model
                or (born.wrapper ~= nil and anchor.wrapper ~= born.wrapper) then
                return "terminal", "birth_identity"
            end
            local window = record.capture_window
            if not positive_id(anchor.native) then
                if window and not window.closed and window.allow_initial_native and window.native == nil
                    and window.handle == record.handle and window.address == born.address and window.model == born.model
                    and window.session_key == run_session and Time.GetEpocheMs() <= window.expires then
                    return "pending", "native_registration_pending"
                end
                return "terminal", "birth_identity"
            end
            if record.net_id ~= anchor.native then return "terminal", "birth_identity" end
            local proof, absence = record.registry_birth_proof, record.lobby_absence_proof
            local wrapper = anchor.registry_wrapper or anchor.wrapper
            if proof and absence and wrapper ~= nil and proof.address == born.address and proof.model == born.model
                and proof.wrapper == wrapper and proof.session_key == run_session
                and absence.address == born.address and absence.native == anchor.native and absence.wrapper == wrapper then
                return "ready"
            end
            local reason = window and (window.reason or window.last_gate) or
                (record.birth_evidence and record.birth_evidence.gate) or "proof_missing"
            if window and not window.closed and window.handle == record.handle and window.address == born.address
                and window.model == born.model and window.native == anchor.native and window.session_key == run_session
                and Time.GetEpocheMs() <= window.expires then
                return "pending", reason
            end
            return "terminal", reason
        end
        local function await_burst_birth(record)
            while not disposed and not abort_requested and generation == token and owner_token == token
                and session_state(run_session) == "same" and Time.GetEpocheMs() < cleanup_at do
                local state, reason = burst_birth_state(record)
                if state == "ready" then return true end
                if state == "terminal" then return false, reason end
                -- Advance only the existing continuously observed birth window.
                -- It cannot be reopened, rebound or reconstructed after a gap.
                advance_creation_capture(record, entity_presence(record.handle))
                if not record.ped and not record.vehicle_retention_invocations_ok then
                    -- If registry ownership is already proved, keep this exact car
                    -- contained while independent absence-proof probes catch up.
                    contain_reference_vehicle(record, false)
                end
                touch_job(token, "ordinary birth cleanup proof")
                Script.Yield(math.min(FOLLOW_EVERY_MS, math.max(0, cleanup_at - Time.GetEpocheMs())))
            end
            return false, "birth_scope_or_deadline"
        end
        local succeeded, reason = pcall(function()
            -- A short bounded warmup gives the pre-requested model a chance to
            -- arrive while the first vehicle is being prepared. Never wait past
            -- the normal effect budget or fail the run if streaming is delayed.
            if warm_model then
                for attempt = 1, 3 do
                    local checked, loaded = pcall(Natives.InvokeBool, N.HAS_MODEL_LOADED, warm_model)
                    if checked and (loaded == true or loaded == 1) then break end
                    if Time.GetEpocheMs() >= cleanup_at or abort_requested then break end
                    Script.Yield(math.min(12, math.max(1, cleanup_at - Time.GetEpocheMs())))
                end
            end
            if not no_local_hover then
                native_void(N.SET_ENTITY_INVINCIBLE, original.handle, true)
                native_void(N.SET_ENTITY_COLLISION, original.handle, true, false)
                native_void(N.FREEZE_ENTITY_POSITION, original.handle, true)
            end
            -- Keep the phase on the effect clock, including target streaming gaps.
            -- A delayed frame picks one current position, never a catch-up burst.
            while not abort_requested and Time.GetEpocheMs() < cleanup_at do
                touch_job(token, "spawn loop")
                target_pos = recover_target_pose()
                if not target_pos then
                    finish_reason = "selected player unavailable"; break
                end
                -- Auto-tp may be toggled ON during an ongoing spawn run.
                -- Release the prior local hold, without ending the vehicle worker.
                if not no_local_hover and baller.AutoTPHandoffReady() then
                    if active_origin == original and baller.ReleaseLocalHoverToAutoTP(original) then
                        active_origin = nil
                        no_local_hover = true
                    end
                end
                if not no_local_hover and active_origin ~= original then no_local_hover = true end
                if not no_local_hover and not baller.AutoTPRequested() and not place_current_leg() then
                    finish_reason = "local entity unavailable"; break
                end

                local now = Time.GetEpocheMs()
                if reference_mode and (not ped_effect or options.single_kaylee == true) then
                    sample_target_motion(stream_state, target_pos)
                end
                -- Wave 1: 8, wave 2: +8 => 16, wave 3: +16 => 32.
                -- The existing admission, deadline and cleanup checks bound
                -- each allocation; a missed window never causes catch-up spam.
                if options.single_kaylee == true
                    and count >= kaylee_wave_target and kaylee_wave_target < spawn_limit then
                    if kaylee_wave_resume == nil then
                        kaylee_wave_resume = now + BALLER_WAVE_PAUSE_MS
                    elseif now >= kaylee_wave_resume then
                        kaylee_wave_target = math.min(spawn_limit, kaylee_wave_target * 2)
                        kaylee_wave_resume = nil
                    end
                end
                if now >= next_spawn and count < spawn_limit and not setup_stopped
                    and (not options.single_kaylee or count < kaylee_wave_target) then
                    local batch_size = options.single_kaylee == true and 1 or circle_stream and CIRCLE_BATCH_SIZE or
                        (ped_effect and 2 or (reference_mode and REFERENCE_BATCH_SIZE or 1))
                    local batch_started = Time.GetEpocheMs()
                    local blocked = false
                    for batch_index = 1, batch_size do
                        -- The helper and identity proof may yield. Never catch up
                        -- by dumping many cars after a delayed network operation.
                        if circle_stream and batch_index > 1 and
                            Time.GetEpocheMs() - batch_started >= CIRCLE_BATCH_BUDGET_MS then
                            break
                        end
                        if abort_requested or count >= spawn_limit or Time.GetEpocheMs() >= cleanup_at then break end
                        local fresh_target = valid_target(player_id, rid)
                        if not fresh_target then
                            if not shuttle and not options.lobby then abort_requested = true end
                            if options.lobby then
                                cleanup_at = Time.GetEpocheMs(); finish_reason = "target unavailable"
                            end
                            break
                        end
                        target_pos = fresh_target
                        local model_index = ped_effect and ((count % #config.models) + 1) or nil
                        if reference_mode then
                            local room = #stream_active < active_limit and #tracked_vehicles < MAX_TRACKED_VEHICLES
                            if not room then
                                spawn_limit = count
                                blocked = true
                                finish_reason = "spawn limit reached; waiting for run end"
                                if not stream_paused then log("Spawn limit reached; cleanup starts after the run ends") end
                                stream_paused = true
                                break
                            end
                        end
                        stream_paused = false
                        if ped_effect then
                            touch_job(token, "ped capacity/model check")
                            local room, detail = entity_room("ped", batch_size - batch_index + 1)
                            if not room then
                                blocked = true
                                if not stream_state.capacity_reported then
                                    log("Ped circle paused: " .. detail); stream_state.capacity_reported = true
                                end
                                break
                            end
                            local ok, loaded = pcall(Natives.InvokeBool, 0x98A4EB5D89A0C952, config.models[model_index])
                            if not ok or (loaded ~= true and loaded ~= 1) then
                                stop_spawning("ped model unloaded"); break
                            end
                        else
                            local room, detail = entity_room("vehicle", 1)
                            if not room then
                                blocked = true
                                if stream_state.capacity_reason ~= detail then
                                    log("Vehicle stream paused: " .. detail)
                                    stream_state.capacity_reason = detail
                                end
                                break
                            end
                            stream_state.capacity_reason = nil
                        end
                        count = count + 1
                        local angle = count * 2.399963229728653 -- distribute directions, not distance
                        -- Keep the previous saved-Deluxo placement; replace it for reference mode.
                        local radius = 0.12 + (count % 6) / 6 * PILE_RADIUS
                        local x = target_pos.x + math.cos(angle) * radius
                        local y = target_pos.y + math.sin(angle) * radius
                        local z = target_pos.z + PILE_Z_BASE + (count % 7) * 0.24
                        local heading = (count * 137.5) % 360
                        local pose, next_column
                        if reference_mode then
                            local upright
                            pose, upright, next_column = sample_reference_pose(stream_state, count)
                            if not pose then
                                if options.lobby then
                                    cleanup_at = Time.GetEpocheMs(); finish_reason = "target unavailable"
                                else
                                    abort_requested = true
                                end
                                break
                            end
                            x, y, z, heading = pose.x, pose.y, pose.z, pose.heading
                        end
                        local model = ped_effect and config.models[model_index] or config.model
                        local handle, record, called, result
                        -- Resolve callback-capable progress/time/session reads
                        -- before reserving; close with a fresh, pure lease fence.
                        touch_job(token, (ped_effect and "ped" or "vehicle") .. " helper model=" .. tostring(model))
                        local helper_now = Time.GetEpocheMs()
                        local helper_session = session_state(run_session)
                        if helper_now >= cleanup_at or helper_session ~= "same" or disposed or abort_requested
                            or generation ~= token or owner_token ~= token then
                            error(cancel_signal, 0)
                        end
                        -- A yielding helper remains an admission/unload obligation
                        -- even if the independent watchdog relinquishes this job.
                        -- Helper lookup/argument access is inside pcall as well.
                        lobby_inflight = lobby_inflight + 1
                        -- Original target-relative birth pose (including Tug and Cargo).
                        -- Re-sample after helper latency; the tracked original entity
                        -- is frozen and gets collision after placement confirmation.
                        local birth_x, birth_y, birth_z = x, y, z
                        called, result = pcall(function()
                            return create_scene_entity(GTA, ped_effect, model,
                                { x = birth_x, y = birth_y, z = birth_z, heading = heading },
                                ped_effect and config.types[model_index] or nil)
                        end)
                        if called and positive_id(result) then
                            handle = result
                            if ped_effect and options.single_kaylee ~= true then stream_state.column = next_column end
                            record = {
                                handle = handle,
                                net_id = 0,
                                model = model,
                                session_key = run_session,
                                ped = ped_effect,
                                single_kaylee = options.single_kaylee == true,
                                hunter_style = hunter_model,
                                baller_slot = options.single_kaylee == true
                                    and (((count - 1) % BALLER_SLOT_COUNT) + 1) or nil,
                                monkey = monkey,
                                pickup = false,
                                sequence = #spawned + 1,
                                spawn_pose = pose,
                                tug_overlap = formation == "tug_overlap",
                                disable_vehicle_physics = options.disable_vehicle_physics == true,
                                disable_cargo_collision = options.disable_cargo_collision == false,
                                lobby_pid = player_id
                            }
                            -- Claim before ANY pointer, native-ID or capture callback.
                            -- Both ordinary cars and peds keep the original physical
                            -- birth needed by cleanup and frame-local visibility.
                            record.spawn_generation = token
                            spawned[#spawned + 1] = record; tracked_vehicles[#tracked_vehicles + 1] = record
                            if options.baller_request then options.baller_request.created = #spawned end
                            if reference_mode then stream_active[#stream_active + 1] = record end
                            local captured = pcall(capture_burst_birth, record)
                            if not captured then reject_birth(record, "selected_birth_capture_error") end
                        end
                        lobby_inflight = lobby_inflight - 1
                        if owner_token ~= token and not handle then error(cancel_signal, 0) end
                        if not handle and (spawn_failures == 0 or spawn_failures % 20 == 0) then
                            warn((ped_effect and "Ped" or "Vehicle") .. " spawn helper failed: "
                                .. (called and "returned no handle" or tostring(result))
                                .. "; model=" .. tostring(model) .. "; attempts=" .. count
                                .. "; helperMs=" .. math.max(0, Time.GetEpocheMs() - helper_now)
                                .. "; pool=" ..
                                tostring(ped_effect and lobby_diagnostics.ped_pool_used or lobby_diagnostics.pool_used)
                                .. "/" ..
                                tostring(ped_effect and lobby_diagnostics.ped_pool_capacity or
                                    lobby_diagnostics.pool_capacity))
                        end
                        if not called and not ped_effect then error(result, 0) end
                        if handle then
                            consecutive_spawn_failures = 0
                            -- A late result is already in the shared tracker. The
                            -- active/background cleanup owns its normal proof path;
                            -- do not duplicate it or let an obsolete worker mutate it.
                            if owner_token ~= token then error(cancel_signal, 0) end
                            if generation ~= token or abort_requested then error(cancel_signal, 0) end
                            -- Freeze as early as original-handle identity/control
                            -- permits, *before* the potentially slow registration
                            -- and cleanup-proof wait.
                            if record.single_kaylee then
                                maintain_kaylee_records({ record }, true)
                            end
                            local birth_ready, birth_reason = await_burst_birth(record)
                            if not birth_ready then
                                stop_spawning("spawn cleanup proof unresolved: " .. tostring(birth_reason))
                                warn(
                                    "Entity birth cleanup proof unresolved; stopping new creation and retaining record: " ..
                                    tostring(birth_reason))
                                break
                            end
                            if record.single_kaylee then
                                -- Freeze immediately after identity/control proof, before
                                -- the slower placement/setup path can yield again.
                                maintain_kaylee_records({ record }, true)
                            end
                            if reference_mode then
                                touch_job(token, "entity setup model=" .. tostring(model))
                                local ready, setup_reason = setup_reference_vehicle(record, stream_state, count, config,
                                    cleanup_at)
                                if not ready then
                                    setup_failures = setup_failures + 1
                                    consecutive_setup_failures = consecutive_setup_failures + 1
                                    -- A failed ownership/birth proof is cleanup debt,
                                    -- not permission to accumulate more unknown cars.
                                    -- Keep this record and its existing bounded proof
                                    -- window, then post-run cleanup; never reconstruct birth.
                                    if not record.ped and (not retention_birth(record)
                                            or vehicle_identity(record) ~= "ours") then
                                        stop_spawning("spawn identity unresolved")
                                        warn(
                                            "Vehicle setup identity unresolved; stopping new creation and retaining cleanup record")
                                        break
                                    end
                                    if record.single_kaylee then
                                        -- Never use the old release path: it intentionally
                                        -- unfreezes peds and restores their gravity.
                                        maintain_kaylee_records({ record }, true)
                                        stop_spawning("Kaylee placement/freeze failed: " .. tostring(setup_reason))
                                        warn("Kaylee setup failed; stopping and retaining record for verified cleanup: " ..
                                            tostring(setup_reason))
                                        break
                                    end
                                    if Time.GetEpocheMs() >= cleanup_at then break end
                                    -- Original non-Kaylee setup/physics behavior remains unchanged.
                                    pcall(release_vehicle, record)
                                    if setup_failures <= 3 or setup_failures % 20 == 0 then
                                        warn("Spawn " .. count .. " setup failed: " .. tostring(setup_reason) ..
                                            "; retained for post-run cleanup; retrying")
                                    end
                                    if consecutive_setup_failures >= REFERENCE_FAILED_CAR_LIMIT then blocked = true end
                                else
                                    consecutive_setup_failures = 0
                                end
                            else
                                if record.net_id > 0 then native_void(N.NETWORK_SET_CAN_MIGRATE, record.net_id, false) end
                                enable_physics(record)
                                apply_preset(handle, config)
                                enable_physics(record) -- apply after any saved appearance
                                if count % 3 == 0 then nudge_vehicle(record, count) end
                            end
                        else
                            spawn_failures = spawn_failures + 1
                            consecutive_spawn_failures = consecutive_spawn_failures + 1
                            -- A missing handle is not a completed Baller slot.
                            -- Retry the same slot instead of silently shifting all
                            -- later wave/slot assignments and losing exact overlap.
                            if options.single_kaylee == true then count = count - 1 end
                            local adjusted_limit = false
                            -- Give delayed slot release a chance without rapidly
                            -- deleting the entire existing formation on failure.
                            if consecutive_spawn_failures > 4 and not adjusted_limit then blocked = true end
                            if spawn_failures == 1 then
                                log(
                                    "Vehicle spawn failed; recovering within the remaining time budget")
                            end
                        end
                    end -- bounded batch; recheck deadline/target before each spawn
                    local finished = Time.GetEpocheMs()
                    if blocked then
                        next_spawn = finished + REFERENCE_SPACE_RETRY_MS
                    elseif reference_mode then
                        -- Keep a full gap after setup, including slow helper/proof
                        -- waits. A stall must not release adjacent cars back-to-back.
                        next_spawn = finished + spawn_interval
                    else
                        next_spawn = finished + SPAWN_EVERY_MS
                    end
                end
                -- The same bounded hold works during helper waits and here.
                if refresh_baller_on_yield then refresh_baller_on_yield() end
                if abort_requested then break end
                -- A lobby pass ends at the count, not the old 15-second deadline.
                if options.lobby and count >= spawn_limit then
                    finish_reason = "burst limit reached"; break
                end
                local wait = FOLLOW_EVERY_MS
                if reference_mode and count < spawn_limit and not setup_stopped then
                    wait = math.max(1,
                        math.min(wait, next_spawn - Time.GetEpocheMs()))
                end
                Script.Yield(wait)
            end
        end)
        -- Release only the lease we requested, even if a spawn/helper failed.
        -- Every early preflight return above also releases it.
        release_warm_model()

        -- Keep the target streamed during the bounded cleanup, then return home.
        if owner_token ~= token then return end
        cleanup_after_run()
        if owner_token ~= token then return end
        if not no_local_hover and baller.AutoTPHandoffReady() then
            if active_origin == original and baller.ReleaseLocalHoverToAutoTP(original) then
                active_origin = nil
                no_local_hover = true
            end
        end
        if not no_local_hover and not options.lobby and active_origin == original
            and restore_local(original) then
            active_origin = nil
        end
        if reference_mode then
            if first_failure_reason then
                finish_reason = first_failure_reason
            elseif abort_requested then
                finish_reason = "cancelled or selected player unavailable"
            elseif not succeeded then
                finish_reason = "spawn job error"
            end
            log("Reference stream: created=" ..
                #spawned .. ", attempts=" .. count .. ", setup failures=" .. setup_failures ..
                ", spawn failures=" .. spawn_failures .. ", live limit=" .. active_limit .. ", finish=" .. finish_reason)
            if config.lighting_errors then
                local failures = {}
                for label, total in pairs(config.lighting_errors) do failures[#failures + 1] = label .. "=" .. total end
                table.sort(failures)
                warn("Reference lighting native failures: " .. table.concat(failures, ", "))
            end
        end
        if not succeeded and (not options.lobby or reason ~= cancel_signal) then warn("Burst error: " .. tostring(reason)) end
        if pending_cleanup_count() > 0 then
            warn(tostring(pending_cleanup_count()) ..
                " entity record(s) unresolved after the cleanup window; unavailable records remain tracked")
        elseif options.lobby then
            log("Lobby burst: player=" .. player_id .. " created=" .. #spawned .. " cleanup resolved")
        elseif active_origin then
            warn("Spawn run and cleanup ended; waiting for local return collision")
        else
            log("Finished. Spawned " ..
                #spawned ..
                (mode == "deluxo" and " saved Deluxos" or " saved " .. reference_preset .. " vehicles") ..
                ", cleaned up, and returned to origin")
        end
    end

    -- Cancellation after a yield also fences the pre-run leftover cleanup path.
    -- Raw QueueJob is used so CScript's cooperative drain can finish this job
    -- after normal UI callbacks have been disabled.
    Script.Yield = function(ms)
        raw_script.Yield(ms)
        if abort_requested then error(cancel_signal, 0) end
    end

    local api = {}
    baller.pending_switch = nil
    function api.StartTugs(player_id)
        -- Use the same safe replacement queue as every other vehicle button.
        return api.Start(player_id, "tug_pair")
    end

    function api.TugStatus()
        local s = api.Status("tug_pair")
        return {
            active = s.phase == "executing",
            held = s.pending or 0,
            limit = LIMIT,
            reason = s.name or s.phase
        }
    end

    function api.Status(effect_key)
        settle_status()
        local snapshot_clock = Time.GetEpocheMs()
        local elapsed = math.max(0, (snapshot_clock - status.started) / 1000)
        -- A finished worker can leave cleanup debt, but that debt is not an
        -- active producer. Admit a new requested effect only while the bounded
        -- entity tracker can hold its requested allocation. Keep all existing
        -- records for verified cleanup; never erase records to unlock the UI.
        local optimized = REGULAR_VEHICLE_TUNING.is_regular(effect_key)
        local required = effect_key == "character_baller" and baller_requested_count()
            or effect_key == "tug_pair" and LIMIT
            or effect_key == "cargoplane_pile" and 1
            or (optimized and REGULAR_VEHICLE_TUNING.limit or REFERENCE_ACTIVE_LIMIT)
        local admission_limit = optimized and MAX_TRACKED_VEHICLES or REGULAR_VEHICLE_TUNING.legacy_tracked_limit
        -- Cargo has a 300-plane maximum, not a 500-plane minimum. Admit it
        -- when at least one slot remains; run_burst caps actual births to free room.
        local free_slots = math.max(0, admission_limit - #tracked_vehicles - lobby_inflight)
        -- Never ignore a true pool/ownership cap. A small but real free budget
        -- is enough to begin an effect; run_burst then bounds its allocation.
        local minimum_slots = optimized and math.min(8, required) or math.min(4, required)
        local full = free_slots < minimum_slots
        local working = busy or job_running
            or active_origin ~= nil or lobby_inflight > 0 or lobby.enabled
            or baller.intent ~= nil
        local debt = cleanup_debt_count()
        local maximum = math.max(cleanup_peak, debt)
        return {
            phase = status.phase,
            name = status.name,
            elapsed = elapsed,
            -- Presentation only: an execution deadline is not a cleanup
            -- deadline. Preserve entity ownership and retirement obligations.
            execution_remaining_ms = status.deadline and math.max(0, status.deadline - snapshot_clock) or nil,
            execution_budget_seconds = status.deadline and math.max(0, (status.deadline - status.started) / 1000) or nil,
            remaining = 0,
            cleanup_remaining = debt,
            cleanup_total = maximum,
            cleanup_fraction = maximum > 0 and math.max(0, math.min(1, debt / maximum)) or 0,
            available_slots = free_slots,
            blocked = working or full,
            background_cleanup = debt > 0,
            capacity_full = full,
            queued_switch = baller.pending_switch and baller.pending_switch.effect_key or nil,
            queued_player = baller.pending_switch and baller.pending_switch.pid or nil,
            baller_enabled = baller.intent ~= nil,
            baller_waiting = baller.intent ~= nil and not baller.intent.started,
            baller_phase = baller.intent and (baller.intent.started and "running" or "waiting") or "off",
            baller_player_id = baller.intent and baller.intent.pid or nil,
            pending = pending_cleanup_count(),
            returning = active_origin ~= nil,
            return_error = active_origin and active_origin.return_error or nil,
            lobby_enabled = lobby.enabled,
            lobby_target = lobby.target,
            lobby_completed = lobby.completed,
            lobby_batch_limit = lobby.limit or 1,
            lobby_target_count = lobby.targets or 0,
            lobby_capacity_reason = lobby.capacity_reason,
            lobby_inflight = lobby_inflight,
            lobby_worker_limit = LOBBY_MAX_INFLIGHT,
            lobby_player_failure_limit = LOBBY_PLAYER_FAILURE_LIMIT,
            lobby_backend = lobby_backend,
            lobby_spawn_timing = active_vehicle_backend and active_vehicle_backend.Snapshot() or last_spawn_timing,
            lobby_formation = "reusable_orbit",
            lobby_diagnostics = (function()
                local copy = {}
                for k, v in pairs(lobby_diagnostics) do copy[k] = v end
                return copy
            end)()
        }
    end

    function api.BallerDiagnostics()
        local request = baller.intent or baller.last
        local held, placed = 0, 0
        for _, record in ipairs(tracked_vehicles) do
            if record.single_kaylee then
                held = held + 1
                if record.placed then placed = placed + 1 end
            end
        end
        local active = baller.intent ~= nil
        local pending = not active and held or 0
        return {
            active = active,
            player_id = request and request.pid,
            phase = active and "running" or held > 0 and "cleanup" or "idle",
            maximum = baller_requested_count(),
            overall_limit = baller_requested_count(),
            target = baller_requested_count(),
            held = held,
            present = held,
            positioned = placed,
            missing = held - placed,
            waiting = pending,
            pending = pending,
            pending_cleanup = pending,
            created = request and request.created or 0,
            configured = placed,
            reason = active and "Eight networked Baller peds; one wave on an invisible platform."
                or held > 0 and "Waiting for shared entity cleanup."
                or request and request.reason or "off",
            flicker_moves = 0,
            swaps = 0
        }
    end

    baller.StartEffect = function(player_id, effect_key)
        local request
        local is_baller = effect_key == "character_baller"
        local admission_generation = generation
        local admission_revision = baller.revision
        if disposed then return false, "Vehicle effect is stopped." end
        local current_status = api.Status(effect_key)
        if current_status.capacity_full then
            return false,
                "Remaining entity capacity is insufficient for this effect (" ..
                current_status.pending .. " retained cleanup records). Background cleanup is retrying."
        end
        if current_status.blocked then
            return false, current_status.phase == "cooldown" and
                string.format("Cooldown %.2f s", current_status.remaining)
                or (current_status.phase == "cleanup" and "Vehicle effects are cleaning up." or "Vehicle effect is already running.")
        end
        if active_origin then return false, "Waiting for safe return collision." end
        local current_session = session_key()
        if type(host.session_key) == "function" and current_session == nil then
            return false,
                "Session identity is unavailable."
        end
        if is_baller and (#tracked_vehicles > 0 or lobby_inflight > 0) then
            return false, "Previous Kaylee cleanup unfinished (records=" ..
                tostring(#tracked_vehicles) .. ", inflight=" .. tostring(lobby_inflight) ..
                ", pending=" .. tostring(pending_cleanup_count()) ..
                "). No new spawn was attempted."
        end
        local preset = PRESETS[effect_key or "penis"]
        local variant
        if not preset then
            for _, entry in ipairs(variants) do
                if entry.key == effect_key then
                    variant = copy_variant(entry)
                    preset = variant.preset ~= "" and variant.preset or variant.model
                    break
                end
            end
        end
        if not preset then return false, "Unknown vehicle effect." end
        local replacement_model = REPLACEMENT_MODELS[effect_key]
        if replacement_model then
            variant = {
                model = replacement_model,
                preset = "",
                view = "hover",
                reference_timing = true,
                preview_limit = effect_key == "tug_pair" and LIMIT
                    or (effect_key == "cargoplane_pile" and 500 or nil),
                name = effect_key == "tug_pair" and "Tug Pair" or
                    effect_key == "cargoplane_pile" and "fuckass (potential crash)" or nil
            }
        end
        player_id = tonumber(player_id)
        if not player_id or player_id % 1 ~= 0 or player_id < 0 or player_id > 31 then
            return false, "Select an available player."
        end
        local target = Players.GetById(player_id)
        if not target or target:IsLocalPlayer() then return false, "Select another player." end
        local head_connections
        if is_baller then
            head_connections = {
                target = head_connection(player_id),
                local_player = head_connection(GTA.GetLocalPlayerId())
            }
            if not head_connections.target or not head_connections.local_player then
                return false,
                    "Player connection identity unavailable."
            end
        end
        local id_ok, expected_rid = pcall(function() return target:GetGamerInfo().RockstarId end)
        if not id_ok then expected_rid = nil end
        local label = variant and variant.name or ({ penis = presentation.penis_name, ruiner_pimp = presentation.name,
                vehicle_circle = presentation.circle_name, trevor_michael = presentation.duo_name, pistol_circle = presentation.pickup_name, character_baller = "Baller" })
            [effect_key or "penis"]
        local start_at = Time.GetEpocheMs()
        if disposed or generation ~= admission_generation or busy or job_running
            or (is_baller and baller.revision ~= admission_revision) then
            return false, "Another action changed the spawn context; try again."
        end
        if is_baller then
            if not baller.Same(head_connections.target, head_connection(player_id))
                or not baller.Same(head_connections.local_player, head_connection(head_connections.local_player.pid))
                or session_state(current_session) ~= "same" then
                return false, "Player connection or session changed."
            end
            if disposed or generation ~= admission_generation or busy or job_running
                or baller.revision ~= admission_revision or #tracked_vehicles > 0 or lobby_inflight > 0 or active_origin then
                return false, "Spawn setup changed or previous cleanup remains."
            end
            request = {
                pid = player_id,
                connections = head_connections,
                session = current_session,
                started = false,
                created = 0
            }
            baller.intent, baller.last = request, nil
        end
        status = { phase = "executing", name = label or tostring(effect_key), started = start_at }
        -- Every preset needs an independent stalled-helper watchdog. Preflight gets
        -- a bounded allowance; run_burst replaces this with its actual run deadline.
        status.deadline = status.started + DURATION_MS + 5000
        if effect_key == "trevor_michael" or effect_key == "pistol_circle" then
            status.deadline = status.started +
                DURATION_MS
        end
        generation = generation + 1
        local token = generation
        if request then
            request.token = token; request.started = true
        end
        owner_token = token
        active_session_key = current_session
        abort_requested, busy = false, true
        cleanup_until = 0
        local queued, queue_error = pcall(raw_script.QueueJob, function()
            if disposed or generation ~= token then return end
            job_running = true
            job_progress = { token = token, time = Time.GetEpocheMs(), phase = "preflight" }
            local ok, err = pcall(function()
                if not valid_target(player_id, expected_rid) then return end
                run_burst(player_id, "reference", preset, variant,
                    effect_key == "character_baller" and "circle"
                    or effect_key == "tug_pair" and "tug_overlap"
                    or (effect_key == nil or effect_key == "penis" or effect_key == "cargoplane_pile") and "target_stack"
                    or (effect_key == "vehicle_circle" or effect_key == "trevor_michael") and "circle" or nil,
                    token, {
                        head_connections = head_connections,
                        baller_request = request,
                        preview_limit = variant and variant.preview_limit or nil,
                        total_spawn_limit = effect_key == "tug_pair" and LIMIT or nil,
                        partial_backlog = effect_key == "cargoplane_pile",
                        circle_stream = effect_key == "vehicle_circle" or is_baller,
                        single_kaylee = is_baller,
                        hunter_style = effect_key == "vehicle_variant_2",
                        optimized_vehicle = REGULAR_VEHICLE_TUNING.is_regular(effect_key),
                        disable_vehicle_physics = effect_key == "tug_pair"
                            or effect_key == "cargoplane_pile",
                        disable_cargo_collision = effect_key == "cargoplane_pile"
                    })
            end)
            if request then baller.Clear(ok and "run_stopped" or "runtime_error", request) end
            if owner_token ~= token then
                release_orphan_models(token); return
            end
            if not ok then
                if err ~= cancel_signal then warn("Vehicle effect error: " .. tostring(err)) end
                if active_origin then
                    local restored, ready = pcall(restore_local, active_origin)
                    if restored and ready then active_origin = nil end
                end
                cleanup_after_run()
            end
            release_ped_models()
            job_running, busy = false, false
            owner_token, job_progress = nil, nil
            settle_status()
        end)
        if not queued or (is_baller and queue_error == false) then
            generation = generation + 1; abort_requested = true
            busy = false
            owner_token, job_progress = nil, nil
            status = { phase = "idle", name = "", started = 0 }
            if request then baller.Clear("queue_failed", request) end
            return false, "Could not queue vehicle effect: " .. tostring(queue_error)
        end
        return true
    end

    function api.BallerEnabled(player_id)
        return baller.intent ~= nil and baller.intent.pid == tonumber(player_id)
    end

    function api.PruneBaller()
        local request = baller.intent
        if request then
            local checked, current = pcall(baller.Current, request)
            if (not checked or not current) and baller.intent == request then
                api.Cancel("Player connection or session changed.")
            end
        end
        return baller.intent ~= nil
    end

    function api.SetBallerEnabled(player_id, enabled)
        if enabled == true and not public_vehicle_action_allowed("character_baller") then
            return false, "Supporter-only vehicle action."
        end
        player_id = tonumber(player_id)
        if enabled ~= true then
            if baller.intent and baller.intent.pid == player_id then
                api.Cancel("disabled")
            elseif baller.editing and baller.admission_pid == player_id then
                baller.revision = baller.revision + 1
            end
            return true
        end
        if disposed then return false, "Vehicle effects are stopped." end
        if baller.editing then return false, "Baller setup is already in progress." end
        if baller.intent then
            if baller.intent.pid == player_id then return true end
            return false, "Stop the current Baller cycle before selecting another player."
        end
        baller.editing, baller.admission_pid = true, player_id
        local called, accepted, why = pcall(baller.StartEffect, player_id, "character_baller")
        baller.editing, baller.admission_pid = false, nil
        if not called then
            if baller.intent and baller.intent.pid == player_id then api.Cancel("setup_error") end
            return false, tostring(accepted)
        end
        return accepted, why
    end

    function baller.SwitchIdentity(pid)
        local ok, result = pcall(function()
            local player = Players.GetById(pid)
            if not player or player:IsLocalPlayer() then return nil end
            local info = player:GetGamerInfo()
            if not info or info.RockstarId == nil or player.CxnId == nil then return nil end
            return tostring(info.RockstarId) .. ":" .. tostring(player.CxnId)
        end)
        return ok and result or nil
    end

    function api.Start(player_id, effect_key)
        if not public_vehicle_action_allowed(effect_key) then return false, "Supporter-only vehicle action." end
        if effect_key == "character_baller" then return api.SetBallerEnabled(player_id, true) end
        local pid = tonumber(player_id)
        if not pid or pid % 1 ~= 0 or pid < 0 or pid > 31 then
            return false, "Select an available player."
        end
        local identity, session = baller.SwitchIdentity(pid), session_key()
        if not identity or (type(host.session_key) == "function" and session == nil) then
            return false, "Selected player connection or session unavailable."
        end
        local snapshot = api.Status(effect_key)
        if busy or job_running or active_origin or baller.intent or snapshot.blocked
            or snapshot.capacity_full or baller.pending_switch then
            local request = {
                pid = pid,
                effect_key = effect_key,
                connection = identity,
                session = session,
                expires = Time.GetEpocheMs() + 45000
            }
            -- Cancel only the active producer. Its existing cleanup tracker and
            -- safe local return stay alive; a new job starts after they yield.
            if busy or job_running or baller.intent or snapshot.blocked then
                api.Cancel("Switching vehicle effect")
            end
            baller.pending_switch = request
            log("Queued vehicle switch to " .. tostring(effect_key) .. " for player " .. tostring(pid))
            return true, "Queued; previous effect is stopping and cleaning up"
        end
        return baller.StartEffect(pid, effect_key)
    end

    function baller.ServicePendingSwitch()
        local request = baller.pending_switch
        if not request or disposed or busy or job_running or active_origin then return end
        if not public_vehicle_action_allowed(request.effect_key) then api.Cancel("Supporter authorization ended");return end
        local now = Time.GetEpocheMs()
        if now >= request.expires or session_state(request.session) ~= "same"
            or baller.SwitchIdentity(request.pid) ~= request.connection then
            baller.pending_switch = nil
            warn("Queued vehicle switch cancelled: timeout, session or target changed")
            return
        end
        local snapshot = api.Status(request.effect_key)
        if snapshot.blocked or snapshot.capacity_full then return end
        baller.pending_switch = nil
        local ok, reason = baller.StartEffect(request.pid, request.effect_key)
        if not ok then warn("Queued vehicle switch failed: " .. tostring(reason)) end
    end

    function api.SetLobbySpawnBackend(value)
        if value ~= "native" and value ~= "helper" then return false, "Unknown spawn backend." end
        if busy or job_running or lobby.enabled or lobby_inflight > 0 or #tracked_vehicles > 0 or active_origin then
            return false, "Stop the current run and finish its cleanup first."
        end
        lobby_backend = value; return true
    end

    function api.SetLobbyEnabled(enabled)
        if enabled ~= true then
            if lobby.enabled then api.Cancel() end
            return true
        end
        return false, "Lobby Vehicle Circle has been removed."
    end

    -- Compatibility hooks only. The shared queued job is the sole producer.
    function api.HeadFollowRequested() return false end

    function api.TickHeadFollow(now, allow_scene)
        if allow_scene == false and baller.intent then api.Cancel("Player processing suspended.") end
    end

    baller.CancelExecution = function(reason)
        baller.revision = baller.revision + 1
        if active_head then
            active_head.stopped = true; active_head.reason = reason or "cancelled"; active_head = nil
        end
        if active_vehicle_backend then active_vehicle_backend.Close() end
        lobby.enabled = false; lobby.target = nil
        generation = generation + 1
        abort_requested = true
        if not job_running then busy = false end
        settle_status()
    end
    function api.Cancel(reason)
        -- Explicit cancellation also discards a queued replacement.
        baller.pending_switch = nil
        -- Remove intent before any backend, time, or UI callback can re-enter.
        local request = baller.intent
        baller.intent = nil; baller.revision = baller.revision + 1
        if request then
            request.reason = reason or "cancelled"; baller.last = request
        end
        baller.CancelExecution(reason)
        baller.Notify(request, reason or "cancelled")
    end

    function api.IsActive()
        return busy or baller.intent ~= nil or baller.editing or job_running or #tracked_vehicles > 0
            or active_origin ~= nil or lobby_inflight > 0
    end

    local authorization_cancelled=false
    function api.TickCleanup(now)
        if public_vehicle_action_allowed("character_baller") then
            authorization_cancelled=false
        elseif not authorization_cancelled and (busy or job_running or baller.pending_switch or baller.intent) then
            authorization_cancelled=true
            api.Cancel("Supporter authorization ended")
        end
        api.PruneBaller()
        if status.session_mode and (lobby.enabled or #tracked_vehicles > 0) then lobby_report(false) end
        if session_state(active_session_key) == "changed" then
            api.Cancel()
            active_session_key = session_key()
            -- The previous local entity/return coordinates cannot be restored into
            -- another session. Entity records retire through their own epoch guard.
            active_origin = nil
        end
        if not disposed then service_creation_capture(Time.GetEpocheMs()) end
        protect_local_from_owned_peds()
        -- Independent of the spawn coroutine: stop the hold if its deadline was missed.
        if status.deadline and status.phase == "executing" and Time.GetEpocheMs() >= status.deadline then
            if owner_token ~= nil and baller.intent and baller.intent.token == owner_token then
                baller.Clear("helper_or_preflight_timeout", baller.intent)
            end
            abort_requested = true
            if active_head then
                active_head.stopped = true; active_head.reason = "duration"; active_head = nil
            end
            lobby.enabled = false
            mark_cleanup()
            cleanup_until = Time.GetEpocheMs() + foreground_cleanup_ms()
            warn("Execution deadline reached; stopping spawns and starting post-run cleanup")
        end
        local clock = Time.GetEpocheMs()
        if status.deadline and job_running and job_progress and clock >= status.deadline + 2000
            and clock - job_progress.time >= 2000 then
            if owner_token ~= nil and baller.intent and baller.intent.token == owner_token then
                baller.Clear("stalled_helper", baller.intent)
            end
            local lost = owner_token
            local foreground_wait = foreground_cleanup_ms()
            if active_head then
                active_head.stopped = true; active_head.reason = "watchdog"; active_head = nil
            end
            if active_vehicle_backend then
                active_vehicle_backend.Close(); last_spawn_timing = active_vehicle_backend.Snapshot()
            end
            lobby.enabled = false; lobby.target = nil
            local phase = job_progress.phase
            orphan_model_leases[lost] = active_ped_models or {}
            active_ped_models = nil
            generation = generation + 1
            abort_requested = true
            owner_token, job_progress = nil, nil
            job_running, busy = false, false
            status.phase = "cleanup"; status.started = clock
            cleanup_until = clock + foreground_wait
            if active_origin then active_origin.returning = true end
            warn("Recovering interrupted spawn job; last phase=" .. tostring(phase) ..
                "; tracked=" .. #tracked_vehicles .. "; independent cleanup and return")
        end
        if active_origin then
            if baller.AutoTPHandoffReady() then
                if baller.ReleaseLocalHoverToAutoTP(active_origin) then active_origin = nil end
            elseif active_origin.returning or (not lobby.enabled and status.phase == "cleanup" and cleanup_until > 0 and Time.GetEpocheMs() >= cleanup_until) then
                if restore_local(active_origin) then active_origin = nil end
            else
                hold_local(active_origin)
            end
        end
        -- Never compete with the yielding spawn job or its final cleanup. Rotate
        -- unresolved records to the back so one unstreamed entity cannot starve
        -- deletable vehicles. One pass never yields on the main runtime tick.
        settle_status()
        baller.ServicePendingSwitch()
        if disposed or #tracked_vehicles == 0 then return end
        now = tonumber(now) or Time.GetEpocheMs()
        if now < cleanup_tick_at and cleanup_tick_at - now <= BACKGROUND_CLEANUP_MS then return end
        cleanup_tick_at = now + BACKGROUND_CLEANUP_MS
        -- Background cleanup may run while a NEW producer is active, but
        -- never touch records that belong to that producer. Skip the former
        -- worker's own synchronous cleanup phase to avoid tracker conflicts.
        if pending_cleanup_count() == 0 then
            if not busy and not job_running then cleanup_peak = 0 end
            return
        end
        if job_running and status.phase == "cleanup" then return end
        local before, batch, waiting = #tracked_vehicles, {}, {}
        for _, record in ipairs(tracked_vehicles) do
            local current_producer = (busy or job_running) and owner_token ~= nil
                and record.spawn_generation == owner_token
            if not current_producer and #batch < BACKGROUND_CLEANUP_BATCH then
                batch[#batch + 1] = record
            else
                waiting[#waiting + 1] = record
            end
        end
        if #batch == 0 then return end
        cleanup_peak = math.max(cleanup_peak, cleanup_debt_count())
        local remaining = cleanup_vehicles(batch, 1, nil, { quiet = true })
        for _, record in ipairs(remaining) do waiting[#waiting + 1] = record end
        tracked_vehicles = waiting
        if cleanup_debt_count() == 0 and not busy and not job_running then cleanup_peak = 0 end
        settle_status()
        -- Preserve forensic evidence only periodically. No per-batch log spam.
        if now >= cleanup_report_at or cleanup_report_at - now > 30000 then
            cleanup_evidence(waiting)
            cleanup_report_at = now + 30000
        end
    end

    function api.DrainUnload()
        api.Cancel()
        -- Cooperative unload replaces the regular runtime tick. Keep the same
        -- interrupted-job watchdog and delayed identity capture alive here too.
        api.TickCleanup(Time.GetEpocheMs())
        if job_running or lobby_inflight > 0 then return false, "Vehicle effect is returning and cleaning up." end
        if #tracked_vehicles > 0 then
            tracked_vehicles = cleanup_vehicles(tracked_vehicles, 1, nil, { quiet = true })
        end
        if active_origin and restore_local(active_origin) then active_origin = nil end
        settle_status()
        return pending_cleanup_count() == 0 and not active_origin,
            active_origin and (active_origin.return_error or "Waiting for safe return collision.") or
            (pending_cleanup_count() > 0 and "Spawned entities still await safe cleanup." or nil)
    end

    function api.RestorePersistentState()
        api.Cancel()
        if active_origin and restore_local(active_origin) then active_origin = nil end
    end

    function api.CanHandoff()
        -- Loader replacement is not a native-thread cleanup callback. Keep this
        -- check read-only and let the existing gameplay cleanup finish first.
        return not busy and not job_running and lobby_inflight == 0
            and #tracked_vehicles == 0 and active_origin == nil and baller.intent == nil and not baller.editing
    end

    function api.Stop()
        if not disposed and (#tracked_vehicles > 0 or lobby_inflight > 0 or job_running) then
            for _, record in ipairs(tracked_vehicles) do
                lifetime_record_event(record, "tracker_unload",
                    "unresolved_unload")
            end
            warn("Vehicle teardown: unresolved=" .. #tracked_vehicles ..
                "; inflight=" .. lobby_inflight .. "; deletion=unverified; " ..
                "tracker will not survive host unload. No cleanup completion claimed.")
        end
        disposed = true
        api.Cancel()
    end

    BallerPlatform8.Bind(api, host, __public_instance)
    -- The original rrer.lua now owns the only public Baller action.
    -- Retire both old implementations at the API boundary while preserving
    -- every unrelated vehicle effect and its existing cleanup controller.
    local former_start=api.Start
    api.Start=function(pid,key,...)
        if key=="character_baller"then
            return false,"Baller moved to the original rrer.lua."
        end
        return former_start(pid,key,...)
    end
    api.SetBallerEnabled=function()
        return false,"Baller moved to the original rrer.lua."
    end
    api.BallerEnabled=function()return false end
    assert(__public_live(__public_instance), "Public API construction was cancelled")
    instances[#instances + 1] = api
    return api
end

function Module.Init(context)
    assert(type(context) == "table" and type(context.Modules) == "table", "vehicle_chaos requires a module context")
    __public_bind(context)
    module_context = context
    presentation = load_presentation(context.Raw)
    variants = load_variants(context.Raw)
    context.Modules.VehicleChaos = Module
end

function Module.Start()
    assert(not __public_teardown and not __public_faulted and __public_binding ~= nil and module_context ~= nil,
        "Public API cannot start without an active context")
    __public_stopped = false
end

