    for _, api in ipairs(instances) do
        if api.CanHandoff() ~= true then return false end
    end
    return true
end

function Module.Stop()
    if __public_teardown then return false end
    __public_teardown, __public_stopped = true, true
    for _, api in ipairs(instances) do
        api.Stop()
        pcall(api.RestorePersistentState)
    end
    __public_teardown = false
end

function Module.Restore(context)
    if __public_teardown then return false end
    if context ~= nil and context ~= module_context then return false end
    __public_teardown, __public_stopped, __public_binding = true, true, nil
    for _, api in ipairs(instances) do api.Stop() end
    context = context or module_context
    if context and context.Modules and context.Modules.VehicleChaos == Module then context.Modules.VehicleChaos = nil end
    module_context, instances = nil, {}
    presentation = DEFAULT_PRESENTATION
    variants = default_variants()
    __public_teardown = false
end

local function __public_cleanup_guard(original)
    return function(...)
        local result = table.pack(pcall(original, ...))
        if result[1] ~= true then
            __public_teardown = false
            __public_stopped, __public_faulted = true, true
            error(result[2], 0)
        end
        if result[2] ~= false then __public_faulted = false end
        return table.unpack(result, 2, result.n)
    end
end
Module.Stop = __public_cleanup_guard(Module.Stop)
Module.Restore = __public_cleanup_guard(Module.Restore)
return Module
