local function closest_palette_tint(rgb)
    local best,best_distance=0,math.huge
    for index=0,160 do
        local color=PALETTE_RGB[index]
        local distance=(color[1]-rgb[1])^2+(color[2]-rgb[2])^2+(color[3]-rgb[3])^2
        if distance<best_distance then best,best_distance=index,distance end
    end
    return best
end

