local function require_binding(name, value)
    if value == nil then error("vehicle manager binding missing " .. name, 3) end
    return value
end

-- Never fill absent native fields with defaults: nil means unavailable/unknown.
local function clone_profile(value)
    if type(value) ~= "table" then return value end
    local result = {}
    for key, item in pairs(value) do result[key] = clone_profile(item) end
    return result
end
local function equal(a,b)
    if type(a) ~= type(b) then return false end
    if type(a) ~= "table" then
        if type(a)=="number" then return math.abs(a-b)<0.001 end
        return a==b
    end
    for k,v in pairs(a) do if not equal(v,b[k]) then return false end end
    for k in pairs(b) do if a[k]==nil then return false end end
    return true
end
local function finite_number(value)
    return type(value)=="number" and value==value and value~=math.huge and value~=-math.huge
end

local function create_manager(deps)
    local H = require_binding("H", deps.H)
    local invoke_void = require_binding("invoke_void", deps.invoke_void)
    local invoke_int = require_binding("invoke_int", deps.invoke_int)
    local invoke_float = require_binding("invoke_float", deps.invoke_float)
    local invoke_bool = require_binding("invoke_bool", deps.invoke_bool)
    local invoke_string = require_binding("invoke_string", deps.invoke_string)
    local invoke_vec3 = require_binding("invoke_vec3", deps.invoke_vec3)
    local vector_components = require_binding("vector_components", deps.vector_components)
    local entity_exists = require_binding("entity_exists", deps.entity_exists)
    local local_vehicle = require_binding("local_vehicle", deps.local_vehicle)
    local local_ped = require_binding("local_ped", deps.local_ped)
    local now_ms = require_binding("now_ms", deps.now_ms)
    local raw_toast = require_binding("toast", deps.toast)
    local function toast(message, duration, kind, priority)
        return raw_toast(message, duration, kind, priority, "vehicle-studio")
    end
    local log_info = require_binding("log_info", deps.log_info)
    local memory = require_binding("Memory", deps.Memory)
    local natives = require_binding("Natives", deps.Natives)
    local gta = require_binding("GTA", deps.GTA)
    local imgui = deps.ImGui

    local function alloc_int(index)
        if State.out_ptrs[index] and State.out_ptrs[index] ~= 0 then return State.out_ptrs[index] end
        if type(memory.AllocInt) ~= "function" then return 0 end
        local ok, value = pcall(memory.AllocInt)
        if not ok then return 0 end
        State.out_ptrs[index] = tonumber(value) or 0
        return State.out_ptrs[index]
    end

    -- Documented int* outputs only; sentinel catches unavailable/no-write returns.
    local function read_outputs(hash, vehicle, count)
        if not hash then return nil end
        local args, pointers = {vehicle}, {}
        for i=1,count do
            local ptr=alloc_int(i)
            if ptr==0 then return nil end
            local ok,result=pcall(memory.WriteInt,ptr,-2147483001)
            if not ok or result==false then return nil end
            args[#args+1]=ptr; pointers[i]=ptr
        end
        local ok,result=pcall(natives.InvokeVoid,hash,table.unpack(args))
        if not ok or result==false then return nil end
        local values={}
        for i,ptr in ipairs(pointers) do
            local read_ok,value=pcall(memory.ReadInt,ptr)
            if not read_ok or type(value)~="number" or value==-2147483001 then return nil end
            values[i]=value
        end
        return values
    end
    local function read_native(kind,hash,...)
        local method=natives["Invoke"..kind]
        if type(method)~="function" or not hash then return nil end
        local ok,value=pcall(method,hash,...)
        if not ok then return nil end
        if kind=="Bool" and type(value)~="boolean" then return nil end
        if (kind=="Int" or kind=="Float") and not finite_number(value) then return nil end
        if kind=="String" and type(value)~="string" then return nil end
        return value
    end
    -- Hashes/signatures verified in supplied natives_gen9.json, no memory offsets.
