    local function translated_mod_label46(label)
        if type(label)~="string" or label=="" or label=="NULL" then return nil end
        local name=read_native("String",VEHICLE_INFO_HASHES.GET_FILENAME_FOR_AUDIO_CONVERSATION,label)
        if name and name~="" and name~="NULL" and name~=label then return name end
        return nil
    end
    local function mod_choice_name46(vehicle,mod_type,index,count)
        local label=read_native("String",N.mod_label,vehicle,mod_type,index)
        local name=translated_mod_label46(label)
        if name then return name end
        if mod_type==14 then
            local identifier=read_native("Int",N.mod_identifier,vehicle,mod_type,index)
            local entry=identifier and identifier%1==0 and HORN_LABELS46[identifier & 0xFFFFFFFF]
            if entry then
                name=translated_mod_label46(entry[1])
                if name then return name..(entry[2] and " (Preview)" or "") end
            end
        elseif mod_type==15 then
            -- Suspension has model-specific low-index HSW entries. A missing
            -- model or special translation must not borrow an ordinary name.
            local model=read_native("Int",H.GET_ENTITY_MODEL,vehicle)
            if type(model)=="number" and model==model and model%1==0 and model~=0
                and model>=-0x80000000 and model<=0xFFFFFFFF then
                model=model & 0xFFFFFFFF
                local special=SUSPENSION_HSW_INDEX46[model]==index and "CMOD_SUS_HSW"
                    or model==(-938068410 & 0xFFFFFFFF) and "CMOD_SUS_0s" or nil
                if special then name=translated_mod_label46(special)
                elseif index>=0 and index<4 then
                    name=translated_mod_label46("CMOD_SUS_"..(index+1))
                end
                if name then return name end
            end
        else
            -- The shop supplies these labels itself when GET_MOD_TEXT_LABEL
            -- has no model-specific label. Stock (-1) remains a separate row.
            local prefixes={[11]="CMOD_ENG_",[12]="CMOD_BRA_",[13]="CMOD_GBX_",[16]="CMOD_ARM_"}
            local limits={[11]=4,[12]=3,[13]=3,[16]=5}
            if prefixes[mod_type] and index<limits[mod_type] then
                local suffix=mod_type==11 and (count==1 and 1 or index+2) or index+1
                name=translated_mod_label46(prefixes[mod_type]..suffix)
                if name then return name end
            end
        end
        if type(label)=="string" and label~="" and label~="NULL" then return label end
        return (MOD_NAMES[mod_type] or "Upgrade").." "..(index+1).." (name unavailable)"
    end

    local function refresh_capabilities(vehicle, model, profile, previous)
        if not entity_exists(vehicle) then return false end
        local full=not previous or State.capability_model~=model
        local wheels_changed=not full and previous.wheel_type~=profile.wheel_type
        local function option_name(hash,...)
            local label=read_native("String",hash,...)
            if not label or label=="" or label=="NULL" then return nil end
            local name=read_native("String",VEHICLE_INFO_HASHES.GET_FILENAME_FOR_AUDIO_CONVERSATION,label)
            return name and name~="" and name~="NULL" and name or label
        end
        if full then State.mod_counts = {}; State.mod_labels={}; State.mod_option_labels={}; State.livery_labels={[-1]="Factory"} end
        for mod_type = 0, 49 do
            -- Wheel families change the wheel catalog, not every bodywork,
            -- engine and paint label. Still recheck counts for dependent slots.
            local old_count=State.mod_counts[mod_type]
            if full or wheels_changed then
                State.mod_counts[mod_type]=math.max(0,invoke_int(H.GET_NUM_VEHICLE_MODS,vehicle,mod_type))
            end
            local rebuild=full or old_count~=State.mod_counts[mod_type]
                or (wheels_changed and (mod_type==23 or mod_type==24))
            if rebuild then
                local labels={[-1]="Factory"}
                for index=0,State.mod_counts[mod_type]-1 do
                    labels[index]=mod_choice_name46(vehicle,mod_type,index,State.mod_counts[mod_type])
                end
                State.mod_option_labels[mod_type]=labels
            end
            local value=profile and profile.mods and profile.mods[mod_type]
            if rebuild or value~=(previous.mods and previous.mods[mod_type]) then
                State.mod_labels[mod_type]=nil
                if value and value>=0 then
                    State.mod_labels[mod_type]=State.mod_option_labels[mod_type][value]
                end
            end
        end
        State.toggle_presence = {}
        local toggles = type(profile) == "table" and profile.toggles or nil
        local presence = type(profile) == "table" and profile.toggle_presence or nil
        for mod_type in pairs(TOGGLE_MODS) do
            if (type(toggles) == "table" and toggles[mod_type] == true)
                or ((mod_type==18 or mod_type==20 or mod_type==22)
                    and type(toggles)=="table" and toggles[mod_type]~=nil
                    and (State.mod_counts[11]>0 or State.mod_counts[23]>0))
                or State.mod_counts[mod_type]>0 then
                State.toggle_presence[mod_type] = true
            end
        end
        if full then
            State.livery_count = math.max(0, invoke_int(H.GET_VEHICLE_LIVERY_COUNT, vehicle))
            State.roof_livery_count=math.max(0,read_native("Int",N.roof_livery_count,vehicle) or 0)
            local plates=read_native("Int",N.plate_count)
            State.plate_count=plates and plates%1==0 and plates>0 and plates<=100 and plates or 6
            for index=0,State.livery_count-1 do
                State.livery_labels[index]=option_name(N.livery_label,vehicle,index) or ("Livery "..(index+1))
            end
        end
        local livery=profile and profile.livery
        if livery and livery>=0 and (full or livery~=previous.livery) then
            local label=read_native("String",N.livery_label,vehicle,livery)
            if label and label~="" and label~="NULL" then
                local name=read_native("String",VEHICLE_INFO_HASHES.GET_FILENAME_FOR_AUDIO_CONVERSATION,label)
                State.livery_labels[livery]=name and name~="" and name~="NULL" and name or label
            end
        end
        State.imani46=read_imani46(vehicle)
        State.capability_model = tonumber(model) or invoke_int(H.GET_ENTITY_MODEL, vehicle)
        return true
    end

    local function capture(vehicle, name, capabilities)
        if not entity_exists(vehicle) then return nil end
        local model=read_native("Int",H.GET_ENTITY_MODEL,vehicle)
        if not model or model==0 then return nil end
        local p={name=name or "Current Vehicle",model=model,model_name=vehicle_model_name(model),
            vehicle_class=read_native("Int",VEHICLE_INFO_HASHES.GET_VEHICLE_CLASS,vehicle),
            mods={},mod_variations={},toggles={},toggle_presence={},extras={},neon_enabled={}}
        for key,spec in pairs(SCALARS) do p[key]=read_native(spec[1],H[spec[2]],vehicle) end
        for _,spec in ipairs({{H.GET_VEHICLE_COLOURS,"primary","secondary"},
                {H.GET_VEHICLE_EXTRA_COLOURS,"pearl","wheel_color"}}) do
            local values=read_outputs(spec[1],vehicle,2)
            if values then p[spec[2]],p[spec[3]]=values[1],values[2] end
        end
        for _,spec in ipairs({{H.GET_VEHICLE_CUSTOM_PRIMARY_COLOUR,"primary_rgb"},
            {H.GET_VEHICLE_CUSTOM_SECONDARY_COLOUR,"secondary_rgb"},
            {H.GET_VEHICLE_NEON_COLOUR,"neon_rgb"},{H.GET_VEHICLE_TYRE_SMOKE_COLOR,"tyre_smoke_rgb"}}) do
            p[spec[2]]=read_outputs(spec[1],vehicle,3)
        end
        p.primary_custom=read_native("Bool",H.GET_IS_VEHICLE_PRIMARY_COLOUR_CUSTOM,vehicle)
        p.secondary_custom=read_native("Bool",H.GET_IS_VEHICLE_SECONDARY_COLOUR_CUSTOM,vehicle)
        local paint1=read_outputs(N.paint_1,vehicle,3); p.primary_finish=paint1 and paint1[1]
        local paint2=read_outputs(N.paint_2,vehicle,2); p.secondary_finish=paint2 and paint2[1]
        p.roof_livery=read_native("Int",N.roof_livery,vehicle)
        local interior=read_outputs(N.interior,vehicle,1); p.interior_color=interior and interior[1]
        local dashboard=read_outputs(N.dashboard,vehicle,1); p.dashboard_color=dashboard and dashboard[1]
        p.drift_tyres=read_native("Bool",N.drift,vehicle)
        for i=0,3 do p.neon_enabled[i]=read_native("Bool",H.GET_VEHICLE_NEON_ENABLED,vehicle,i) end
        for i=0,49 do
            if TOGGLE_MODS[i] then
                p.toggles[i]=read_native("Bool",H.IS_TOGGLE_MOD_ON,vehicle,i)
                p.toggle_presence[i]=p.toggles[i]~=nil
            else p.mods[i]=read_native("Int",H.GET_VEHICLE_MOD,vehicle,i) end
        end
        for _,i in ipairs({23,24}) do
            local value=read_native("Int",N.variation,vehicle,i)
            if value~=nil then p.mod_variations[i]=value~=0 end
        end
        for i=0,20 do
            if read_native("Bool",H.DOES_EXTRA_EXIST,vehicle,i)==true then
                p.extras[i]=read_native("Bool",H.IS_VEHICLE_EXTRA_TURNED_ON,vehicle,i)
            end
        end
        if capabilities then refresh_capabilities(vehicle,model,p) end
        return p
    end

    -- Read the changed family between writes. Full snapshots remain at the
    -- start/end of a patch, so paired values and supported side effects still
    -- enter Undo without scanning every mod/extras slot for every slider event.
    local function capture_changed(vehicle,key,previous)
        if key=="wheel_type" then return capture(vehicle) end
        local p=clone_profile(previous)
        local spec=SCALARS[key]
        if spec then p[key]=read_native(spec[1],H[spec[2]],vehicle); return p end
        if key=="primary" or key=="secondary" or key:match("^primary_") or key:match("^secondary_") then
            local values=read_outputs(H.GET_VEHICLE_COLOURS,vehicle,2)
            p.primary=values and values[1]; p.secondary=values and values[2]
            p.primary_custom=read_native("Bool",H.GET_IS_VEHICLE_PRIMARY_COLOUR_CUSTOM,vehicle)
            p.secondary_custom=read_native("Bool",H.GET_IS_VEHICLE_SECONDARY_COLOUR_CUSTOM,vehicle)
            p.primary_rgb=read_outputs(H.GET_VEHICLE_CUSTOM_PRIMARY_COLOUR,vehicle,3)
            p.secondary_rgb=read_outputs(H.GET_VEHICLE_CUSTOM_SECONDARY_COLOUR,vehicle,3)
            local paint1=read_outputs(N.paint_1,vehicle,3); p.primary_finish=paint1 and paint1[1]
            local paint2=read_outputs(N.paint_2,vehicle,2); p.secondary_finish=paint2 and paint2[1]
            local extra=read_outputs(H.GET_VEHICLE_EXTRA_COLOURS,vehicle,2)
            p.pearl=extra and extra[1];p.wheel_color=extra and extra[2]
        elseif key=="pearl" or key=="wheel_color" then
            local values=read_outputs(H.GET_VEHICLE_EXTRA_COLOURS,vehicle,2)
            p.pearl=values and values[1]; p.wheel_color=values and values[2]
        elseif key=="neon_rgb" or key=="tyre_smoke_rgb" then
            p[key]=read_outputs(key=="neon_rgb" and H.GET_VEHICLE_NEON_COLOUR or H.GET_VEHICLE_TYRE_SMOKE_COLOR,vehicle,3)
        elseif key=="interior_color" or key=="dashboard_color" then
            local values=read_outputs(key=="interior_color" and N.interior or N.dashboard,vehicle,1); p[key]=values and values[1]
        elseif key=="drift_tyres" then p[key]=read_native("Bool",N.drift,vehicle)
        elseif key=="roof_livery" then p[key]=read_native("Int",N.roof_livery,vehicle)
        else
            local group,index=key:match("^([%w_]+):(%d+)$"); index=tonumber(index)
            if group=="mods" or group=="mod_variations" then
                p.mods[index]=read_native("Int",H.GET_VEHICLE_MOD,vehicle,index)
                if index==23 or index==24 then
                    local variation=read_native("Int",N.variation,vehicle,index)
                    p.mod_variations[index]=nil
                    if variation~=nil then p.mod_variations[index]=variation~=0 end
                end
            elseif group=="toggles" then p.toggles[index]=read_native("Bool",H.IS_TOGGLE_MOD_ON,vehicle,index)
            elseif group=="extras" then p.extras[index]=read_native("Bool",H.IS_VEHICLE_EXTRA_TURNED_ON,vehicle,index)
            elseif group=="neon_enabled" then p.neon_enabled[index]=read_native("Bool",H.GET_VEHICLE_NEON_ENABLED,vehicle,index)
            else return capture(vehicle) end
        end
        return p
    end

    local function target_identity(vehicle)
        if not entity_exists(vehicle) then return nil end
        if read_native("Bool",N.transition)~=false then return nil end
        local ped=local_ped()
        if not entity_exists(ped) or read_native("Bool",H.IS_PED_DEAD_OR_DYING,ped,true)~=false then return nil end
        local model=read_native("Int",H.GET_ENTITY_MODEL,vehicle)
        local ped_model=read_native("Int",H.GET_ENTITY_MODEL,ped)
        if not model or model==0 or not ped_model then return nil end
        local address=0
        if type(gta.HandleToPointer)=="function" then
            local ok,obj=pcall(gta.HandleToPointer,vehicle)
            if ok and obj then
                local got,value=pcall(function() return obj:GetAddress() end)
                if got and type(value)=="number" then address=value end
            end
        end
        if address<=0 then return nil end
        local net=0
        if read_native("Bool",N.networked,vehicle)==true then net=read_native("Int",N.network_id,vehicle) or 0 end
        return {vehicle=vehicle,ped=ped,ped_model=ped_model,model=model,address=address,net=net,
            key=table.concat({State.generation,vehicle,ped,ped_model,model,address,net},":")}
    end
    local function target_valid(target)
        if not target or target.generation~=State.generation then return false end
        local current_vehicle=local_vehicle()
        if entity_exists(current_vehicle) and current_vehicle~=target.vehicle then return false end
        local identity=target_identity(target.vehicle)
        return identity~=nil and identity.key==target.key
    end


    -- A preview identity is separate from the live editing target. Never admit
    -- an occupied/source vehicle, its pointer alias, or a networked entity.
    local function preview_identity(vehicle)
        if type(vehicle)~="number" or vehicle<=0 or vehicle%1~=0 or not entity_exists(vehicle)
            or vehicle==local_vehicle() or vehicle==(State.target and State.target.vehicle) then return nil end
        local model=read_native("Int",H.GET_ENTITY_MODEL,vehicle)
        local ok,address=pcall(function()return gta.HandleToPointer(vehicle):GetAddress()end)
        if not model or model==0 or not ok or not finite_number(address) or address<=0 or address%1~=0 then return nil end
        return {vehicle=vehicle,address=address,model=model}
    end
    local function preview_owned(proof)
        if not proof or proof~=State.preview_proof then return false end
        local current=preview_identity(State.preview_vehicle)
        return current and current.vehicle==proof.vehicle and current.address==proof.address
            and current.model==proof.model and proof.address~=proof.source_address
            and read_native("Bool",N.networked,current.vehicle)==false
    end
    local function preview_write(hash,...)
        if not hash or not preview_owned(State.preview_proof) then return false end
        local ok,result=pcall(natives.InvokeVoid,hash,State.preview_vehicle,...)
        return ok and result~=false
    end

    local function write_property(vehicle,key,value,actual,preview_proof)
        local group,index=tostring(key):match("^([%w_]+):(%d+)$"); index=tonumber(index)
        local live_mod_count
        if group=="mods" or group=="mod_variations" then
            live_mod_count=read_native("Int",H.GET_NUM_VEHICLE_MODS,vehicle,index)
        end
        if not validate_property(key,value,live_mod_count) then return false,"Invalid property value" end
        -- Preserve the native signature at the final boundary. UI arithmetic
        -- and imported profiles can carry 10.0 even when the field requires int.
        value=native_property_value(key,value)
        local f=fields(actual); if f[key]==nil then return false,"Field could not be read" end
        local identity=not preview_proof and target_identity(vehicle) or nil
        if preview_proof then
            if vehicle~=State.preview_vehicle or not preview_owned(preview_proof) or not target_valid(State.target) then
                return false,"Preview identity could not be verified"
            end
        elseif not identity then return false,"Vehicle identity could not be verified" end
        if identity then identity.generation=State.generation end
        local function write(hash,...)
            if not hash then return false end
            if preview_proof then
                if not preview_owned(preview_proof) or not target_valid(State.target) then return false end
            elseif not target_valid(identity) then return false end
            local ok,result=pcall(natives.InvokeVoid,hash,...)
            return ok and result~=false
        end
        local spec=SCALARS[key]
        if spec then
            if spec[4] and (type(value)~="number" or value<spec[4] or value>spec[5]) then return false,"Value is out of range" end
            if key=="livery" and (value>=State.livery_count or State.livery_count<=0) then return false,"Livery unavailable" end
            if key=="plate_text" then value=tostring(value):sub(1,8) end
            if key=="wheel_type" and not write(H.SET_VEHICLE_MOD_KIT,vehicle,0) then return false,"Mod kit unavailable" end
            return write(H[spec[3]],vehicle,value)
        end
        if key=="primary" or key=="secondary" then
            if actual.primary==nil or actual.secondary==nil then return false,"Paired paint unavailable" end
            local primary=key=="primary" and value or actual.primary
            local secondary=key=="secondary" and value or actual.secondary
            local ok=write(H.SET_VEHICLE_COLOURS,vehicle,primary,secondary)
            -- A selected palette paint intentionally replaces custom paint on that side only.
            return write(key=="primary" and H.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR or H.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR,vehicle) and ok
        end
        if key=="primary_finish" or key=="secondary_finish" then
            local primary=key=="primary_finish"
            local color=actual[primary and "primary" or "secondary"]
            if color==nil or (primary and actual.pearl==nil) then return false,"Paint finish unavailable" end
            local ok
            if primary then ok=write(N.set_paint_1,vehicle,value,color,actual.pearl)
            else ok=write(N.set_paint_2,vehicle,value,color) end
            if not ok then return false,"Paint finish rejected" end
            local rgb=actual[primary and "primary_rgb" or "secondary_rgb"]
            if actual[primary and "primary_custom" or "secondary_custom"] and rgb then
                return write(primary and H.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR or H.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR,
                    vehicle,table.unpack(rgb))
            end
            return true
        end
        if key=="pearl" or key=="wheel_color" then
            if actual.pearl==nil or actual.wheel_color==nil then return false,"Paired paint unavailable" end
            return write(H.SET_VEHICLE_EXTRA_COLOURS,vehicle,key=="pearl" and value or actual.pearl,
                key=="wheel_color" and value or actual.wheel_color)
        end
        if key=="primary_custom" or key=="secondary_custom" then
            local primary=key=="primary_custom"
            if not value then return write(primary and H.CLEAR_VEHICLE_CUSTOM_PRIMARY_COLOUR or H.CLEAR_VEHICLE_CUSTOM_SECONDARY_COLOUR,vehicle) end
            local rgb=actual[primary and "primary_rgb" or "secondary_rgb"]
            if not rgb then return false,"Color channels unavailable" end
            return write(primary and H.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR or H.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR,vehicle,table.unpack(rgb))
        end
        local rgb_setters={primary_rgb=H.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR,secondary_rgb=H.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR,
            neon_rgb=H.SET_VEHICLE_NEON_COLOUR,tyre_smoke_rgb=H.SET_VEHICLE_TYRE_SMOKE_COLOR}
        if rgb_setters[key] then
            if type(value)~="table" or #value~=3 then return false,"Invalid RGB" end
            for _,channel in ipairs(value) do if type(channel)~="number" or channel<0 or channel>255 then return false,"Invalid RGB" end end
            return write(rgb_setters[key],vehicle,table.unpack(value))
        end
        if key=="interior_color" or key=="dashboard_color" then
            return write(key=="interior_color" and N.set_interior or N.set_dashboard,vehicle,value)
        end
        if key=="drift_tyres" then return write(N.set_drift,vehicle,value) end
        if key=="roof_livery" then return write(N.set_roof_livery,vehicle,value) end
        if group=="mods" or group=="mod_variations" then
            local count=read_native("Int",H.GET_NUM_VEHICLE_MODS,vehicle,index)
            local wanted=group=="mods" and value or actual.mods[index]
            if not count or count<=0 or type(wanted)~="number" or wanted< -1 or wanted>=count then return false,"Mod unavailable for this model" end
            local variation=actual.mod_variations[index]
            if group=="mod_variations" then variation=value end
            if (index==23 or index==24) and variation==nil then return false,"Wheel variation unavailable" end
            local imani=index==44 and group=="mods" and read_imani46(vehicle) or nil
            local expected_imani=index==44 and group=="mods" and State.imani46~=nil
                and (preview_proof or (State.target and State.target.vehicle==vehicle))
            if imani or expected_imani then
                if not imani or not imani.supported or wanted>1 or imani.allow_lockon==nil then
                    return false,"Imani upgrade or lock-on state could not be read"
                end
            end
            if not write(H.SET_VEHICLE_MOD_KIT,vehicle,0) then return false,"Mod kit unavailable" end
            if not write(H.SET_VEHICLE_MOD,vehicle,index,wanted,variation==true) then return false,"Mod write rejected" end
            if imani then
                -- carmod_shop func_336 / func_2822 apply this paired native
                -- after the genuine slot choice. The synced flag alone is not
                -- a saved Imani upgrade, so verify slot readback first.
                if read_native("Int",H.GET_VEHICLE_MOD,vehicle,44)~=wanted then
                    return false,"Imani upgrade was not confirmed"
                end
                local allowed=wanted~=1
                if read_native("Bool",N.imani_lockon46,vehicle)~=allowed
                    and not write(N.set_imani_lockon46,vehicle,allowed,true) then
                    return false,"Imani lock-on change was rejected"
                end
                if read_native("Bool",N.imani_lockon46,vehicle)~=allowed then
                    return false,"Imani lock-on change was not confirmed"
                end
                if preview_proof then
                    if not preview_owned(preview_proof) or not target_valid(State.target) then
                        return false,"Preview identity changed"
                    end
                elseif not target_valid(identity) then return false,"Vehicle identity changed" end
            end
            return true
        end
        if group=="toggles" then return write(H.TOGGLE_VEHICLE_MOD,vehicle,index,value==true) end
        if group=="extras" then
            if read_native("Bool",H.DOES_EXTRA_EXIST,vehicle,index)~=true then return false,"Extra unavailable" end
            return write(H.SET_VEHICLE_EXTRA,vehicle,index,value~=true)
        end
        if group=="neon_enabled" then return write(H.SET_VEHICLE_NEON_ENABLED,vehicle,index,value==true) end
        return false,"Unsupported property"
    end

    -- This compatibility entry point applies only present fields. Ordinary edits use
    -- apply_pending, which writes changed properties and verifies each result.
    local function apply(vehicle,profile)
        local actual=capture(vehicle)
        if not actual or not profile or actual.model~=profile.model then return false,"model_mismatch" end
        local failed=false
        local wanted=fields(profile)
        local keys={};for key in pairs(wanted) do keys[#keys+1]=key end
        local order={wheel_type=0,primary=1,secondary=1,primary_finish=2,secondary_finish=2,
            primary_rgb=3,secondary_rgb=3,primary_custom=4,secondary_custom=4,pearl=5,wheel_color=5}
        table.sort(keys,function(a,b)
            return (order[a] or 4)==(order[b] or 4) and a<b or (order[a] or 4)<(order[b] or 4)
        end)
        for _,key in ipairs(keys) do
            local value=wanted[key]
            if not equal(fields(actual)[key],value) or imani_needs_sync46(vehicle,key,value) then
                local ok=write_property(vehicle,key,value,actual)
                local after=capture(vehicle)
                if not ok or not after or not equal(fields(after)[key],value) then failed=true end
                actual=after or actual
            end
        end
        return not failed,failed and "readback_failed" or nil
    end

    local function profile_path()
        if not (FileMgr and type(FileMgr.GetMenuRootPath) == "function") then return nil end
        local ok, root = pcall(FileMgr.GetMenuRootPath)
        if not ok or type(root) ~= "string" or root == "" then return nil end
        local directory = root .. "\\Lua\\CScript"
        if type(FileMgr.CreateDir) == "function" then pcall(FileMgr.CreateDir, directory) end
        return directory .. "\\vehicles.txt"
    end

    local function map_encode(values, boolean_values)
        local entries = {}
        for key, value in pairs(values or {}) do
            entries[#entries + 1] = tostring(key) .. ":" .. (boolean_values and (value and "1" or "0") or tostring(value))
        end
        table.sort(entries)
        return table.concat(entries, ",")
    end

    local function map_decode(text, boolean_values)
        local result = {}
        for key, value in tostring(text or ""):gmatch("(%d+):(-?%d+)") do
            if boolean_values then result[tonumber(key)] = tonumber(value) == 1
            else result[tonumber(key)] = tonumber(value) end
        end
        return result
    end

    local function empty_vehicle_slot()
        return {name="",model=0,model_name="Vehicle",vehicle_class=-1,
            created="",modified="",created_at="",modified_at="",favorite=false,
            mods={},toggles={},toggle_presence={},extras={}}
    end

    local function vehicle_slot_has_data(slot)
        return type(slot)=="table" and ((tonumber(slot.model) or 0)~=0
            or next(slot.mods or {})~=nil or next(slot.toggles or {})~=nil or next(slot.extras or {})~=nil
            or next(slot.mod_variations or {})~=nil or next(slot.primary_rgb or {})~=nil
            or next(slot.secondary_rgb or {})~=nil or next(slot.neon_rgb or {})~=nil
            or next(slot.neon_enabled or {})~=nil or next(slot.tyre_smoke_rgb or {})~=nil)
    end

    local function vehicle_slot_factory_empty(slot)
        if vehicle_slot_has_data(slot) then return false end
        -- Old empty rows acquire these defaults while being decoded. Anything
        -- else is user data, even when its model handle was absent or zero.
        local defaults={primary=0,secondary=0,pearl=0,wheel_color=0,wheel_type=0,tint=0,plate_index=0,
            livery=-1,tyres_can_burst=true,primary_custom=false,secondary_custom=false,xenon_color=-1,
            plate_text="CSCRIPT",dirt_level=0,env_effect=1}
        for key,value in pairs(defaults)do if slot[key]~=nil and slot[key]~=value then return false end end
        for _,key in ipairs({"interior_color","dashboard_color","drift_tyres","primary_finish","secondary_finish","roof_livery"})do
            if slot[key]~=nil then return false end
        end
        return true
    end

    local function load_slots()
        if State.loaded then return end
        State.loaded=true
        State.storage_bytes,State.storage_error,State.storage_migrated=nil,nil,false
        State.slots={empty_vehicle_slot()}
        local path=profile_path()
        if not path or not FileMgr or type(FileMgr.DoesFileExist)~="function"
            or type(FileMgr.ReadFileContent)~="function" then
            State.storage_error="Local file access is unavailable";return
        end
        local exists_ok,exists=pcall(FileMgr.DoesFileExist,path)
        if not exists_ok then State.storage_error="Local file existence could not be read";return end
        if not exists then State.storage_bytes="";State.selected_slot=1;State.rename_buffer="";State.rename_buffer_slot=1;return end
        local read_ok,content=pcall(FileMgr.ReadFileContent,path)
        if not read_ok or type(content)~="string" then State.storage_error="Local presets could not be read";return end
        State.storage_bytes=content
        local header=content:match("^([^\r\n]+)")
        local legacy=header=="CSCRIPT_VEHICLES_V1" or header=="CSCRIPT_VEHICLES_V2" or header=="CSCRIPT_VEHICLES_V3"
        if not legacy and header~="CSCRIPT_VEHICLE_PRESETS_V1" then
            State.storage_error="Local presets use an unsupported format";return
        end
        local slots,rows,declared={},0,nil
        local malformed=false
        for line in content:gmatch("[^\r\n]+")do
            local values={}
            for value in (line.."|"):gmatch("([^|]*)|")do values[#values+1]=value end
            local index=tonumber(values[1])
            if line==header then
            elseif values[1]=="SLOTS" and not legacy then
                local count=tonumber(values[2])
                if declared~=nil or not count or count%1~=0 or count<1 or #values~=2 then malformed=true;break end
                declared=count
            elseif values[1]=="EXT" then
                index=tonumber(values[2]);local profile=index and slots[index]
                if not profile then malformed=true;break end
                profile.mod_variations=map_decode(values[3],true)
                profile.interior_color=tonumber(values[4]);profile.dashboard_color=tonumber(values[5])
                if values[6]~="" then profile.drift_tyres=values[6]=="1" end
                profile.primary_finish=tonumber(values[8]);profile.secondary_finish=tonumber(values[9])
                profile.roof_livery=tonumber(values[10])
                for key in tostring(values[7] or ""):gmatch("[%w_]+")do profile[key]=nil end
            elseif values[1]=="META" then
                index=tonumber(values[2]);local profile=index and slots[index]
                if not profile then malformed=true;break end
                profile.created=clean_field(values[3],24);profile.modified=clean_field(values[4],24)
                profile.created_at=profile.created;profile.modified_at=profile.modified
                profile.favorite=tonumber(values[5])==1
                profile.vehicle_class=tonumber(values[6]) or -1
                profile.model_name=clean_field(values[7],48)
                if profile.model_name=="" then profile.model_name="Vehicle" end
            elseif index and index%1==0 and index>=1 and #values>=15 then
                if slots[index] or (legacy and index>5) or (not legacy and index~=rows+1) then malformed=true;break end
                local profile={name=tostring(values[2] or ""),model=tonumber(values[3]) or 0,
                    model_name="Vehicle",vehicle_class=-1,created="",modified="",created_at="",modified_at="",favorite=false,
                    primary=tonumber(values[4]) or 0,secondary=tonumber(values[5]) or 0,
                    pearl=tonumber(values[6]) or 0,wheel_color=tonumber(values[7]) or 0,
                    wheel_type=tonumber(values[8]) or 0,tint=tonumber(values[9]) or 0,
                    plate_index=tonumber(values[10]) or 0,livery=tonumber(values[11]) or -1,
                    tyres_can_burst=tonumber(values[12])~=0,mods=map_decode(values[13],false),
                    toggles=map_decode(values[14],true),extras=map_decode(values[15],true)}
                if #values>=26 then
                    profile.primary_custom=tonumber(values[16])==1;profile.primary_rgb=map_decode(values[17],false)
                    profile.secondary_custom=tonumber(values[18])==1;profile.secondary_rgb=map_decode(values[19],false)
                    profile.neon_rgb=map_decode(values[20],false);profile.neon_enabled=map_decode(values[21],true)
                    profile.tyre_smoke_rgb=map_decode(values[22],false);profile.xenon_color=tonumber(values[23]) or -1
                    profile.plate_text=tostring(values[24] or "CSCRIPT"):sub(1,8)
                    profile.dirt_level=tonumber(values[25]) or 0.0;profile.env_effect=tonumber(values[26]) or 1.0
                end
                slots[index]=clone_profile(profile);rows=rows+1
            else malformed=true;break end
        end
        if not legacy and (declared==nil or rows~=declared) then malformed=true end
        if malformed then State.storage_error="Local preset records are incomplete; the original file was preserved";return end
        if legacy then
            local suggested={"Race Build","Drift Build","Clean Show Car","Armored","Vehicle 5"}
            local migrated={}
            for index=1,5 do
                local slot=slots[index]
                local placeholder=slot and vehicle_slot_factory_empty(slot)
                    and (slot.name==suggested[index] or slot.name=="Vehicle "..index)
                    and slot.created=="" and slot.modified=="" and slot.favorite~=true
                    and slot.vehicle_class==-1 and slot.model_name=="Vehicle"
                if slot and not placeholder then migrated[#migrated+1]=slot end
            end
            slots=migrated;State.storage_migrated=true
        end
        if #slots==0 then slots={empty_vehicle_slot()} end
        State.slots=slots
        State.selected_slot=math.max(1,math.min(#slots,math.floor(tonumber(State.selected_slot) or 1)))
        State.rename_buffer=tostring(slots[State.selected_slot].name or "")
        State.rename_buffer_slot=State.selected_slot
        State.local_confirmation=nil
    end

    local function save_slots(slot_source)
        load_slots()
        if State.storage_error then return false end
        local path=profile_path()
        if not path or not FileMgr or type(FileMgr.WriteFileContent)~="function"
            or type(FileMgr.ReadFileContent)~="function" then return false end
        slot_source=type(slot_source)=="table" and slot_source or State.slots
        if #slot_source<1 then return false end
        -- Distinct header: a previous five-slot reader must refuse this library,
        -- rather than silently discard user-added rows on its next save.
        local lines={"CSCRIPT_VEHICLE_PRESETS_V1","SLOTS|"..#slot_source}
        for index,p in ipairs(slot_source)do
            lines[#lines+1]=table.concat({index,tostring(p.name or ""):gsub("[|\r\n]"," "),p.model or 0,
                p.primary or 0,p.secondary or 0,p.pearl or 0,p.wheel_color or 0,
                p.wheel_type or 0,p.tint or 0,p.plate_index or 0,p.livery or -1,
                p.tyres_can_burst==false and 0 or 1,map_encode(p.mods,false),map_encode(p.toggles,true),
                map_encode(p.extras,true),p.primary_custom and 1 or 0,map_encode(p.primary_rgb,false),
                p.secondary_custom and 1 or 0,map_encode(p.secondary_rgb,false),map_encode(p.neon_rgb,false),
                map_encode(p.neon_enabled,true),map_encode(p.tyre_smoke_rgb,false),p.xenon_color or -1,
                tostring(p.plate_text or "CSCRIPT"):gsub("[|\r\n]",""):sub(1,8),p.dirt_level or 0.0,p.env_effect or 1.0,""},"|")
        end
        for index,p in ipairs(slot_source)do
            lines[#lines+1]="META|"..table.concat({index,clean_field(p.created,24),clean_field(p.modified,24),
                p.favorite and 1 or 0,tonumber(p.vehicle_class) or -1,clean_field(p.model_name,48),""},"|")
            local absent={}
            for key in pairs(SCALARS)do if p[key]==nil then absent[#absent+1]=key end end
            for _,key in ipairs(SIMPLE_KEYS)do if p[key]==nil then absent[#absent+1]=key end end
            table.sort(absent)
            lines[#lines+1]="EXT|"..table.concat({index,map_encode(p.mod_variations,true),
                p.interior_color~=nil and p.interior_color or "",p.dashboard_color~=nil and p.dashboard_color or "",
                p.drift_tyres==nil and "" or (p.drift_tyres and "1" or "0"),table.concat(absent,","),
                p.primary_finish~=nil and p.primary_finish or "",p.secondary_finish~=nil and p.secondary_finish or "",
                p.roof_livery~=nil and p.roof_livery or "",""},"|")
        end
        local content=table.concat(lines,"\n")
        local ok,result=pcall(FileMgr.WriteFileContent,path,content,false)
        local read_ok,readback=pcall(FileMgr.ReadFileContent,path)
        if not ok or result==false or not read_ok or readback~=content then return false end
        State.storage_bytes=content;State.storage_migrated=false
        return true
    end

    local function snapshot_slots()
        local candidate={}
        for index,slot in ipairs(State.slots)do candidate[index]=clone_profile(slot) end
        if #candidate==0 then candidate[1]=empty_vehicle_slot() end
        return candidate
    end

    local function commit_slots(candidate)
        if type(candidate)~="table" or not save_slots(candidate) then return false end
        State.slots=candidate
        return true
    end

    local function delete_preview_vehicle()
        local vehicle=tonumber(State.preview_vehicle) or 0
        local function forget()
            State.preview_vehicle,State.preview_proof,State.preview_snapshot=0,nil,nil
            State.preview_delete_pending=false
            return true
        end
        if vehicle==0 or not entity_exists(vehicle) then return forget() end
        if vehicle==local_vehicle() or vehicle==(State.target and State.target.vehicle) then return forget() end
        local proof,current=State.preview_proof,preview_identity(vehicle)
        if proof and current and (current.model~=proof.model or current.address~=proof.address) then return forget() end
        State.preview_delete_pending=true
        if not preview_owned(proof) or (tonumber(State.delete_ptr) or 0)==0 then return false end
        local ok,result=pcall(memory.WriteInt,State.delete_ptr,vehicle)
        if not ok or result==false or not preview_owned(proof) then return false end
        local accepted,value=pcall(natives.InvokeVoid,H.DELETE_ENTITY,State.delete_ptr)
        if accepted and value~=false and not entity_exists(vehicle) then return forget() end
        return false
    end

    local function camera_owned()
        local ui=module_context and module_context.CScriptUI
        if ui and type(ui.owns_studio_camera)=="function" then
            return State.camera_lease~=nil and ui.owns_studio_camera("vehicle",State.camera_lease)
        end
        local owner=module_context and module_context.State and module_context.State.UI
        return not owner or owner.PreviewCameraOwner==nil or owner.PreviewCameraOwner=="vehicle"
    end

    local function camera_write(hash,...)
        if not hash or type(natives.InvokeVoid)~="function" then return false end
        local ok,result=pcall(natives.InvokeVoid,hash,...)
        return ok and result~=false
    end

    local function stop_preview(reason)
        State.preview_orbit_x,State.preview_orbit_y,State.preview_wheel=0,0,0
        local had_preview = (tonumber(State.preview_cam) or 0) ~= 0
            or (tonumber(State.preview_vehicle) or 0) ~= 0
        if tonumber(State.preview_cam) and State.preview_cam ~= 0 and not camera_owned() then
            -- A stale lease must never destroy a camera handle now owned elsewhere.
            State.preview_cam=0
        end
        if tonumber(State.preview_cam) and State.preview_cam ~= 0 then
            local preview_owner = module_context and module_context.State and module_context.State.UI
            local rendering=read_native("Int",N.rendering_cam)
            if rendering==State.preview_cam and (not preview_owner or preview_owner.PreviewCameraOwner == nil
                or preview_owner.PreviewCameraOwner == "vehicle") then
                invoke_void(H.RENDER_SCRIPT_CAMS, false, false, 0, true, false, 0)
            end
            invoke_void(H.SET_CAM_ACTIVE, State.preview_cam, false)
            invoke_void(H.DESTROY_CAM, State.preview_cam, false)
            if read_native("Bool",H.DOES_CAM_EXIST,State.preview_cam)~=false then
                State.preview_cleanup_pending=true
                State.preview_phase="cleanup_pending"
                State.preview_hold_rotate,State.preview_hold_zoom=0,0
                return false
            end
            State.preview_cam = 0
            if preview_owner and preview_owner.PreviewCameraOwner=="vehicle" then preview_owner.PreviewCameraOwner=nil end
        end
        State.preview_cleanup_pending=false
        local ui=module_context and module_context.CScriptUI
        if State.camera_lease and ui and type(ui.release_studio_camera)=="function" then
            ui.release_studio_camera("vehicle",State.camera_lease)
        end
        State.camera_lease=nil
        local deleted = delete_preview_vehicle()
        if State.preview_model_requested and (tonumber(State.preview_model) or 0)~=0 then
            invoke_void(H.SET_MODEL_AS_NO_LONGER_NEEDED,State.preview_model)
            State.preview_model_requested=false
        end
        if not deleted then
            State.preview_cleanup_pending=true
            State.preview_phase="cleanup_pending"
            State.preview_hold_rotate,State.preview_hold_zoom=0,0
            return false
        end
        if deleted then State.preview_anchor = nil end
        State.preview_last_frame_ms = 0
        State.preview_hold_rotate, State.preview_hold_zoom = 0, 0
        State.preview_input_ping = false
        State.preview_phase = "idle"
        State.preview_render_deadline = nil
        State.preview_started_ms = 0
        State.preview_model = 0
        State.preview_model_requested = false
        State.preview_last_stage = "idle"
        if had_preview then
            local status = deleted and "VEHICLE_STUDIO preview=destroy"
                or "VEHICLE_STUDIO preview=destroy_pending"
            log_info(status .. (reason and (" reason=" .. tostring(reason)) or ""))
        end
        return deleted
    end

    local function clamp(value, minimum, maximum)
        return math.max(minimum, math.min(maximum, tonumber(value) or minimum))
    end

    local function shortest_angle_delta(from, to)
        return ((tonumber(to) - tonumber(from) + 540.0) % 360.0) - 180.0
    end

    local PREVIEW_CAMERA_PRESETS = {
        front_three_quarter = { 38.0, PREVIEW_DEFAULT_ELEVATION, 1.0 },
        rear_three_quarter = { 218.0, 0.15, 1.0 },
        side = { 90.0, 0.12, 1.0 },
        front = { 0.0, 0.13, 1.0 },
        rear = { 180.0, 0.13, 1.0 },
        high_three_quarter = { 38.0, 0.70, 1.04 },
    }

    local function pause_preview_auto(now)
        State.preview_auto_rotate=false
        State.preview_auto_pause_until_ms=0
    end

    local function set_preview_camera_preset(name, resume_auto)
        local preset = PREVIEW_CAMERA_PRESETS[tostring(name)]
        if not preset then return false end
        State.preview_angle_preset=tostring(name)
        State.preview_target_yaw = preset[1]
        State.preview_target_elevation = clamp(preset[2], PREVIEW_ELEVATION_MIN, PREVIEW_ELEVATION_MAX)
        State.preview_target_zoom = clamp(preset[3], PREVIEW_ZOOM_MIN, PREVIEW_ZOOM_MAX)
        if resume_auto == true then
            State.preview_auto_rotate = true
            State.preview_hold_rotate,State.preview_hold_zoom=0,0
        else
            pause_preview_auto(now_ms())
        end
        return true
    end

    local function preview_stage(stage, status, detail)
        State.preview_last_stage = tostring(stage or "unknown")
        local suffix = detail and detail ~= "" and (" detail=" .. tostring(detail):gsub("[%c%s]+", "_")) or ""
        log_info(("VEHICLE_STUDIO preview_stage=%s status=%s attempt=%d%s"):format(
            State.preview_last_stage, tostring(status or "begin"),
            tonumber(State.preview_attempt) or 0, suffix))
    end

    local function read_model_bounds(model)
        if not finite_number(model) or model==0 or type(memory.Alloc)~="function"
            or type(memory.Free)~="function" or type(memory.WriteFloat)~="function"
            or type(memory.ReadFloat)~="function" then return nil end
        local pointer=State.out_ptrs.model_bounds
        if not pointer then
            local ok,value=pcall(memory.Alloc,48)
            if not ok or not finite_number(value) or value<=0 then return nil end
            pointer=value; State.out_ptrs.model_bounds=pointer
        end
        -- Two scrVector24 outputs: x/y/z at 0/8/16, never packed ReadV3.
        -- A no-write native must not reuse the preceding vehicle's dimensions.
        for offset=0,40,8 do
            local ok,value=pcall(memory.WriteFloat,pointer+offset,1000000.0)
            if not ok or value==false then return nil end
        end
        local ok,value=pcall(natives.InvokeVoid,VEHICLE_INFO_HASHES.GET_MODEL_DIMENSIONS,
            model,pointer,pointer+24)
        if not ok or value==false then return nil end
        local bounds={minimum={},maximum={}}
        for axis=1,3 do
            local lo_ok,lo=pcall(memory.ReadFloat,pointer+(axis-1)*8)
            local hi_ok,hi=pcall(memory.ReadFloat,pointer+24+(axis-1)*8)
            if not lo_ok or not hi_ok or not finite_number(lo) or not finite_number(hi)
                or math.abs(lo)>500 or math.abs(hi)>500 or hi-lo<0.05 or hi-lo>500 then return nil end
            bounds.minimum[axis],bounds.maximum[axis]=lo,hi
        end
        return bounds
    end

    local function set_safe_preview_framing(profile)
        local bounds=read_model_bounds(tonumber(profile and profile.model))
        State.preview_bounds=bounds
        State.preview_fitted_distance=nil
        State.preview_focus_x,State.preview_focus_y=0,0
        if bounds then
            local lo,hi=bounds.minimum,bounds.maximum
            State.preview_focus_x,State.preview_focus_y=(lo[1]+hi[1])*0.5,(lo[2]+hi[2])*0.5
            State.preview_focus_z=(lo[3]+hi[3])*0.5
            State.preview_radius=math.sqrt((hi[1]-lo[1])^2+(hi[2]-lo[2])^2+(hi[3]-lo[3])^2)*0.5
            State.preview_fit_distance=State.preview_radius/math.sin(math.rad(24)*0.82)
            State.preview_frame_source="model-bounds-scrVector24"
        else
            local class=tonumber(profile and profile.vehicle_class) or -1
            local framing=PREVIEW_CLASS_FRAMING[class] or {6.5,0.4,2.6}
            State.preview_fit_distance,State.preview_focus_z,State.preview_radius=framing[1],framing[2],framing[3]
            State.preview_frame_source="class-fallback-"..tostring(class)
        end
        preview_stage("framing","ok",State.preview_frame_source)
        return true
    end

    -- Auto camera chooses a stable category view. The existing oriented-corner
    -- fit below keeps the actual model inside the unobscured screen rectangle.
    -- preview_auto_rotate is retained as the internal compatibility key only;
    -- it no longer requests a continuous orbit.
    local function suggest_preview_category(force)
        if State.preview_auto_rotate~=true then return false end
        local category=VEHICLE_CATEGORIES[State.selected_category] or "Bodywork"
        local key=tostring(State.target and State.target.key or "none")..":"..category
        if not force and State.preview_category_key==key then return false end
        local presets={
            ["Bodywork"]={"front_three_quarter",0.16,0.50},
            ["Paint"]={"front_three_quarter",0.32,0.50},
            ["Wheels"]={"side",0.06,0.22},
            ["Performance"]={"front",0.26,0.45},
            ["Lights & Extras"]={"front",0.08,0.35},
            ["Plate & Finish"]={"rear",0.10,0.35},
            ["Quick Builds"]={"front_three_quarter",0.18,0.50},
        }
        local preset=presets[category] or presets.Bodywork
        if not set_preview_camera_preset(preset[1],true) then return false end
        State.preview_target_elevation=clamp(preset[2],PREVIEW_ELEVATION_MIN,PREVIEW_ELEVATION_MAX)
        local bounds=State.preview_bounds
        if bounds then
            local lo,hi=bounds.minimum,bounds.maximum
            State.preview_focus_x,State.preview_focus_y=(lo[1]+hi[1])*0.5,(lo[2]+hi[2])*0.5
            State.preview_focus_z=lo[3]+(hi[3]-lo[3])*preset[3]
        end
        State.preview_category_key=key;State.preview_category=category
        State.preview_orbit_x,State.preview_orbit_y,State.preview_wheel=0,0,0
        State.preview_hold_rotate,State.preview_hold_zoom=0,0
        return true
    end

    local function fail_preview(stage, reason)
        State.preview_failure = {
            stage = tostring(stage or State.preview_last_stage or "unknown"),
            reason = tostring(reason or "operation rejected"),
            attempt = tonumber(State.preview_attempt) or 0,
            at_ms = now_ms(),
        }
        preview_stage(State.preview_failure.stage, "failed", State.preview_failure.reason)
        stop_preview("startup failure")
        State.preview_suppressed = true
        State.preview_phase = "failed"
        State.preview_last_stage = State.preview_failure.stage
        return false
    end

    local function reset_preview_attempt(reason)
        if State.preview_phase ~= "idle" or State.preview_failure then
            preview_stage("reset", "ok", reason or "retry")
        end
        State.preview_phase = "idle"
        State.preview_started_ms = 0
        State.preview_model = 0
        State.preview_model_requested = false
        State.preview_failure = nil
        State.preview_last_stage = "idle"
    end

    local function draw_preview_lighting()
        local anchor = State.preview_anchor
        if State.preview_lighting ~= true or not entity_exists(State.preview_vehicle)
            or type(anchor) ~= "table" then return false end
        local intensity = clamp(State.preview_lighting_intensity or 1.0, 0.6, 1.4)
        -- DRAW_LIGHT_WITH_RANGE is frame-local: no handle is allocated and
        -- nothing survives when preview_frame stops being requested.
        invoke_void(H.DRAW_LIGHT_WITH_RANGE,
            anchor.x + 3.8, anchor.y - 3.0, anchor.z + 3.3,
            255, 232, 210, 10.5, 3.2 * intensity)
        invoke_void(H.DRAW_LIGHT_WITH_RANGE,
            anchor.x - 3.2, anchor.y - 1.0, anchor.z + 2.0,
            205, 222, 255, 9.0, 1.8 * intensity)
        invoke_void(H.DRAW_LIGHT_WITH_RANGE,
            anchor.x, anchor.y + 3.7, anchor.z + 2.7,
            223, 198, 255, 8.5, 1.3 * intensity)
        return true
    end

    local function update_preview_camera()
        if not target_valid(State.target) then stop_preview("target lost"); return false end
        if not camera_owned() then State.preview_suppressed=true; stop_preview("camera ownership changed"); return false end
        if not preview_owned(State.preview_proof) then
            return fail_preview("copy", "Preview vehicle is no longer the owned local copy")
        end
        local anchor = State.preview_anchor
        local cam = tonumber(State.preview_cam) or 0
        if cam == 0 or type(anchor) ~= "table" then return false end
        local rendering=read_native("Int",N.rendering_cam)
        if rendering and rendering~=0 and rendering~=-1 and rendering~=cam then
            State.preview_suppressed=true; stop_preview("conflicting camera"); return false
        end
        if read_native("Bool",H.DOES_CAM_EXIST,cam)~=true then
            fail_preview("camera_liveness", "camera handle no longer exists")
            return false
        end
        if State.preview_phase=="starting" then
            if rendering==cam then
                State.preview_phase="ready"
                preview_stage("camera", "ready", "render-readback")
            elseif now_ms()>=(State.preview_render_deadline or 0) then
                return fail_preview("render", "Game did not activate the studio view")
            end
        elseif State.preview_phase=="ready" and rendering~=cam then
            return fail_preview("render", "Studio view was released by the game")
        end
        local zoom = clamp(State.preview_current_zoom or State.preview_zoom or 1.0,
            PREVIEW_ZOOM_MIN, PREVIEW_ZOOM_MAX)
        local viewport = type(State.preview_viewport)=="table" and State.preview_viewport or {}
        local aspect=clamp(tonumber(viewport.aspect) or 16/9,0.5,4)
        local width=clamp(tonumber(viewport.width_fraction) or 1,0.2,1)
        local height=clamp(tonumber(viewport.height_fraction) or 1,0.2,1)
        local center=clamp(tonumber(viewport.center_x) or .5,width*.5,1-width*.5)
        local center_y=clamp(tonumber(viewport.center_y) or .5,height*.5,1-height*.5)
        local vfov=math.tan(math.rad(24))
        local nx,ny=(2*center-1)*vfov*aspect,(1-2*center_y)*vfov
        -- Compose a level-horizon camera basis whose subject projects exactly to
        -- the free rectangle center, including a rectangle below the menu.
        local pitch=clamp(math.atan(State.preview_current_elevation or PREVIEW_DEFAULT_ELEVATION),
            math.rad(-65),math.rad(65))
        local camera_pitch=clamp(-pitch-math.atan(ny),math.rad(-80),math.rad(80))
        local cp,sp=math.cos(camera_pitch),math.sin(camera_pitch)
        local yaw=math.atan(-nx,cp-ny*sp)
        local sy,cyaw=math.sin(yaw),math.cos(yaw)
        local forward={sy*cp,cyaw*cp,sp}
        local right={cyaw,-sy,0}
        local up={-sy*sp,-cyaw*sp,cp}
        local length=math.sqrt(1+nx*nx+ny*ny)
        local ray={}
        for axis=1,3 do ray[axis]=(forward[axis]+nx*right[axis]+ny*up[axis])/length end
        local heading_degrees=(180.0-(tonumber(State.preview_current_yaw) or 0.0))%360.0
        if not preview_write(H.SET_ENTITY_HEADING,heading_degrees) then
            return fail_preview("copy", "Preview rotation was rejected")
        end
        local observed_heading=read_native("Float",H.GET_ENTITY_HEADING,State.preview_vehicle)
        if not finite_number(observed_heading) then return fail_preview("copy", "Preview heading unavailable") end
        local heading=math.rad(observed_heading)
        local ch,sh=math.cos(heading),math.sin(heading)
        local focus_x,focus_y=State.preview_focus_x or 0,State.preview_focus_y or 0
        local focus_z=tonumber(State.preview_focus_z) or 0.4
        local cx=anchor.x+focus_x*ch-focus_y*sh
        local cy=anchor.y+focus_x*sh+focus_y*ch
        local cz=anchor.z+focus_z
        local fitted=0.5
        local bounds=State.preview_bounds
        if bounds then
            -- Fit actual oriented corners instead of the all-angle bounding
            -- sphere that made front views several times smaller than necessary.
            local left,right_edge=nx-width*.88*vfov*aspect,nx+width*.88*vfov*aspect
            local bottom,top=ny-height*.88*vfov,ny+height*.88*vfov
            for xi=1,2 do for yi=1,2 do for zi=1,2 do
                local lo,hi=bounds.minimum,bounds.maximum
                local x=(xi==1 and lo[1] or hi[1])-focus_x
                local y=(yi==1 and lo[2] or hi[2])-focus_y
                local z=(zi==1 and lo[3] or hi[3])-focus_z
                local wx,wy=x*ch-y*sh,x*sh+y*ch
                local r=wx*right[1]+wy*right[2]
                local u=wx*up[1]+wy*up[2]+z*up[3]
                local f=wx*forward[1]+wy*forward[2]+z*forward[3]
                fitted=math.max(fitted,length*(r-right_edge*f)/(right_edge-nx),
                    length*(left*f-r)/(nx-left),length*(u-top*f)/(top-ny),
                    length*(bottom*f-u)/(ny-bottom),length*(.2-f))
            end end end
        else
            local half_angle=math.atan(math.min(width*vfov*aspect,height*vfov)*.75/length)
            fitted=(tonumber(State.preview_radius) or 2.6)/math.sin(half_angle)
        end
        -- Zoom remains independent of framing. Move out immediately to keep all
        -- corners visible; ease inward as an orbit exposes a narrower profile.
        local previous=State.preview_fitted_distance
        local depth_fit=not previous and fitted or math.max(fitted,previous+(fitted-previous)*.16)
        State.preview_fitted_distance=depth_fit
        local depth=math.max(.5,depth_fit*zoom)
        State.preview_viewport_width,State.preview_viewport_fit_scale=width,depth_fit/(State.preview_fit_distance or depth_fit)
        State.preview_effective_distance=depth
        local camera_x,camera_y,camera_z=cx-depth*ray[1],cy-depth*ray[2],cz-depth*ray[3]
        local positioned=camera_write(VEHICLE_INFO_HASHES.SET_CAM_COORD,cam,camera_x,camera_y,camera_z)
        local tx,ty= -depth*ray[1]+depth*forward[1],-depth*ray[2]+depth*forward[2]
        local aimed=camera_write(H.POINT_CAM_AT_ENTITY,cam,State.preview_vehicle,
            focus_x+tx*ch+ty*sh,focus_y-tx*sh+ty*ch,focus_z-depth*ray[3]+depth*forward[3],true)
        if not positioned or not aimed then return fail_preview("position", "Camera positioning was rejected") end

        return true
    end

    local function preview_frame(now)
        if State.preview_cleanup_pending then stop_preview("cleanup retry");return false end
        if (tonumber(State.preview_cam) or 0)~=0 and not preview_owned(State.preview_proof) then
            return fail_preview("copy", "Preview vehicle was lost")
        end
        if not entity_exists(State.preview_vehicle) or (tonumber(State.preview_cam) or 0) == 0 then
            State.preview_last_frame_ms = tonumber(now) or 0
            return false
        end
        now = tonumber(now) or now_ms()
        suggest_preview_category(false)
        local last = tonumber(State.preview_last_frame_ms) or 0
        State.preview_last_frame_ms = now
        local orbit_x,orbit_y,wheel=State.preview_orbit_x,State.preview_orbit_y,State.preview_wheel
        State.preview_orbit_x,State.preview_orbit_y,State.preview_wheel=0,0,0
        if not State.preview_auto_rotate and (orbit_x~=0 or orbit_y~=0 or wheel~=0) then
            State.preview_angle_preset="free"
            State.preview_target_yaw=((State.preview_target_yaw or 0)-clamp(orbit_x,-720,720)*0.24)%360
            local pitch=math.atan(State.preview_target_elevation or PREVIEW_DEFAULT_ELEVATION)
            State.preview_target_elevation=math.tan(clamp(pitch-math.rad(clamp(orbit_y,-720,720)*0.18),
                math.atan(PREVIEW_ELEVATION_MIN),math.atan(PREVIEW_ELEVATION_MAX)))
            State.preview_target_zoom=clamp((State.preview_target_zoom or 1)*math.exp(-clamp(wheel,-20,20)*0.12),
                PREVIEW_ZOOM_MIN,PREVIEW_ZOOM_MAX)
        end
        if last <= 0 or now <= last then
            local updated = update_preview_camera()
            draw_preview_lighting()
            return updated
        end
        local delta = math.min(0.05, math.max(0.001, (now - last) / 1000.0))
        local hold_rotate = tonumber(State.preview_hold_rotate) or 0
        if hold_rotate ~= 0 then
            State.preview_angle_preset="free"
            pause_preview_auto(now)
            State.preview_current_yaw = ((tonumber(State.preview_current_yaw) or 0.0)
                + hold_rotate * PREVIEW_ROTATION_RATE * delta) % 360.0
            State.preview_target_yaw = State.preview_current_yaw
        else
            local current = tonumber(State.preview_current_yaw) or 0.0
            current = (current + shortest_angle_delta(current,
                tonumber(State.preview_target_yaw) or current) * (1.0-math.exp(-delta * 11.0))) % 360.0
            State.preview_current_yaw = current
        end
        local current_elevation = clamp(State.preview_current_elevation or PREVIEW_DEFAULT_ELEVATION,
            PREVIEW_ELEVATION_MIN, PREVIEW_ELEVATION_MAX)
        current_elevation = current_elevation
            + (clamp(State.preview_target_elevation or current_elevation,
                PREVIEW_ELEVATION_MIN, PREVIEW_ELEVATION_MAX) - current_elevation)
                * (1.0-math.exp(-delta * 8.0))
        State.preview_current_elevation = current_elevation
        local hold_zoom = tonumber(State.preview_hold_zoom) or 0
        if hold_zoom ~= 0 then
            pause_preview_auto(now)
            State.preview_target_zoom = clamp((tonumber(State.preview_target_zoom) or 1.0)
                + hold_zoom * PREVIEW_ZOOM_RATE * delta, PREVIEW_ZOOM_MIN, PREVIEW_ZOOM_MAX)
        end
        local current_zoom = tonumber(State.preview_current_zoom) or 1.0
        current_zoom = current_zoom + ((tonumber(State.preview_target_zoom) or current_zoom) - current_zoom)
            * (1.0-math.exp(-delta * 10.0))
        State.preview_current_zoom = current_zoom
        State.preview_zoom = current_zoom
        local updated = update_preview_camera()
        draw_preview_lighting()
        return updated
    end


    local function sync_preview()
        if (tonumber(State.preview_vehicle) or 0)==0 then return true end
        local proof,desired=State.preview_proof,State.verified
        if not preview_owned(proof) or not target_valid(State.target) or not desired or desired.model~=proof.model then return false end
        if equal(State.preview_snapshot,desired) then return true end
        local actual=capture(State.preview_vehicle)
        if not actual then return false end
        local wanted,keys=fields(desired),{}
        local observed=fields(actual)
        for key in pairs(wanted) do keys[#keys+1]=key end
        -- Restore palette then active RGB then flags. Disabled custom colors must
        -- stay disabled; wheel family precedes the dependent wheel components.
        local order={wheel_type=0,primary=1,secondary=1,primary_finish=2,secondary_finish=2,
            primary_rgb=3,secondary_rgb=3,primary_custom=4,secondary_custom=4,pearl=5,wheel_color=5}
        table.sort(keys,function(a,b)
            return (order[a] or 4)==(order[b] or 4) and a<b or (order[a] or 4)<(order[b] or 4)
        end)
        for _,key in ipairs(keys) do
            local inactive=(key=="primary_rgb" and desired.primary_custom~=true)
                or (key=="secondary_rgb" and desired.secondary_custom~=true)
            if not inactive and wanted[key]~=nil and not equal(observed[key],wanted[key]) then
                local ok=write_property(State.preview_vehicle,key,wanted[key],actual,proof)
                local after=preview_owned(proof) and capture_changed(State.preview_vehicle,key,actual) or nil
                local after_fields=after and fields(after)
                if not ok or not after_fields or not equal(after_fields[key],wanted[key]) then return false end
                actual=after
                observed=after_fields
            end
        end
        if not preview_owned(proof) or not target_valid(State.target) then return false end
        State.preview_snapshot=clone_profile(desired)
        return true
    end
    local function create_preview_copy()
        if (tonumber(State.preview_vehicle) or 0)~=0 or not target_valid(State.target) then return false end
        local x,y,z=vector_components(invoke_vec3(H.GET_ENTITY_COORDS,State.target.vehicle,true))
        if not finite_number(x) or not finite_number(y) or not finite_number(z) then return false end
        if type(memory.AllocInt)~="function" or type(memory.WriteInt)~="function" then return false end
        if (tonumber(State.delete_ptr) or 0)==0 then
            local ok,ptr=pcall(memory.AllocInt)
            if ok and finite_number(ptr) and ptr>0 and ptr%1==0 then State.delete_ptr=ptr end
        end
        if (tonumber(State.delete_ptr) or 0)==0 then return false end
        State.preview_anchor={x=x,y=y,z=z+160.0}
        local anchor=State.preview_anchor
        local vehicle=read_native("Int",H.CREATE_VEHICLE,State.target.model,anchor.x,anchor.y,anchor.z,180.0,false,false,false)
        if not vehicle or vehicle<=0 or vehicle==local_vehicle() or vehicle==State.target.vehicle
            or not entity_exists(vehicle) then return false end
        State.preview_vehicle=vehicle
        State.preview_proof=preview_identity(vehicle)
        if State.preview_proof then State.preview_proof.source_address=State.target.address end
        if not preview_owned(State.preview_proof) or State.preview_proof.model~=State.target.model then return false end
        for _,op in ipairs({
            {H.SET_ENTITY_AS_MISSION_ENTITY,true,true},
            {H.SET_ENTITY_COLLISION,false,false},
            {H.FREEZE_ENTITY_POSITION,true},
            {H.SET_ENTITY_VISIBLE,true,false},
            {H.SET_ENTITY_INVINCIBLE,true},
            {H.SET_ENTITY_CAN_BE_DAMAGED,false},
            {H.SET_VEHICLE_MOD_KIT,0},
        }) do if not preview_write(op[1],table.unpack(op,2)) then return false end end
        State.preview_snapshot=nil
        return sync_preview()
    end

    local function start_preview()
        if State.preview_cleanup_pending then return false end
        if State.preview_suppressed or not target_valid(State.target) then return false end
        if State.preview_cam~=0 then return true end
        if not State.preview_model_requested then
            State.preview_model=State.target.model
            State.preview_started_ms=now_ms()
            if not camera_write(H.REQUEST_MODEL,State.preview_model) then return fail_preview("model", "Model request was rejected") end
            State.preview_model_requested=true
        end
        if read_native("Bool",H.HAS_MODEL_LOADED,State.preview_model)~=true then
            State.preview_phase="model_loading"
            if now_ms()-State.preview_started_ms>=PREVIEW_MODEL_TIMEOUT_MS then return fail_preview("model", "Preview model did not load") end
            return false -- Continue on the existing fast tick; never block/yield a render callback.
        end
        local ui=module_context and module_context.CScriptUI
        if ui and type(ui.claim_studio_camera)=="function" then
            State.camera_lease=ui.claim_studio_camera("vehicle",function(reason)
                State.preview_suppressed=true; State.preview_requested=false
                return stop_preview(reason)
            end)
            if not State.camera_lease then return fail_preview("ownership", "Another studio view could not close") end
        else
            local owner=module_context and module_context.State and module_context.State.UI
            if owner and owner.PreviewCameraOwner and owner.PreviewCameraOwner~="vehicle" then return false end
        end
        local existing=read_native("Int",N.rendering_cam)
        if existing and existing~=0 and existing~=-1 then
            return fail_preview("ownership", "Another game camera is active")
        end
        State.preview_attempt=State.preview_attempt+1
        if not create_preview_copy() then return fail_preview("copy", "Local preview vehicle could not be created or synchronized") end
        local cam=read_native("Int",H.CREATE_CAM,"DEFAULT_SCRIPTED_CAMERA",false)
        if not cam or cam<=0 then return fail_preview("create", "Game could not create the studio camera") end
        State.preview_cam=cam
        State.preview_is_live=false
        set_safe_preview_framing(State.current)
        suggest_preview_category(true)
        State.preview_current_yaw=State.preview_target_yaw
        State.preview_current_zoom=State.preview_target_zoom
        State.preview_current_elevation=State.preview_target_elevation
        -- The positioning helper already tears down and records its failure.
        -- A second stop here would erase the failed phase and hide the reason.
        if not update_preview_camera() then return false end
        if not camera_write(H.SET_CAM_FOV,cam,48.0) or not camera_write(H.SET_CAM_ACTIVE,cam,true)
            or not camera_write(H.RENDER_SCRIPT_CAMS,true,false,0,true,false,0) then
            return fail_preview("activate", "Game rejected the studio view")
        end
        local owner=module_context and module_context.State and module_context.State.UI
        if owner then owner.PreviewCameraOwner="vehicle" end
        State.preview_failure=nil
        State.preview_phase=read_native("Int",N.rendering_cam)==cam and "ready" or "starting"
        State.preview_render_deadline=now_ms()+500; State.preview_last_frame_ms=0
        preview_stage("camera",State.preview_phase)
        return true
    end

    local function components()
        local ui = module_context and module_context.CScript and module_context.CScript.UI
        return type(ui) == "table" and type(ui.Components) == "table" and ui.Components or nil
    end

    local function styled_button(label, id, style, tooltip, width)
        local ui = components()
        local method = style == "primary" and "primary_button"
            or style == "danger" and "danger_button"
            or style == "subtle" and "subtle_button"
            or "secondary_button"
        if ui and type(ui[method]) == "function" then
            local ok, clicked = pcall(ui[method], label, id, tooltip, width)
            if ok then return clicked == true end
        end
        if not imgui or type(imgui.Button) ~= "function" then return false end
        local ok, clicked
        if tonumber(width) then ok, clicked = pcall(imgui.Button, label .. "##" .. tostring(id), tonumber(width), 32)
        else ok, clicked = pcall(imgui.Button, label .. "##" .. tostring(id)) end
        return ok and clicked == true
    end

    local function button(label, id, primary, tooltip)
        return styled_button(label, id, primary and "primary" or "secondary", tooltip)
    end

    local function hold_button(label, id, tooltip, active)
        local ui = components()
        if ui and type(ui.hold_button) == "function" then
            local ok, clicked, held, supported = pcall(ui.hold_button, label, id, tooltip, nil, active == true)
            if ok then return clicked == true, held == true, supported == true end
        end
        local clicked = styled_button(label, id, "subtle", tooltip)
        local held, supported = false, imgui and type(imgui.IsItemActive) == "function"
        if supported then
            local ok, value = pcall(imgui.IsItemActive)
            held = ok and value == true
        end
        return clicked, held, supported == true
    end

    local function same_line()
        if imgui and type(imgui.SameLine) == "function" then pcall(imgui.SameLine) end
    end

    local function pair_fits(required_width)
        local ui = components()
        if ui and type(ui.row_can_pair) == "function" then
            local ok, value = pcall(ui.row_can_pair, required_width or 250)
            if ok then return value == true end
        end
        return false
    end

    local function pair_line(required_width)
        -- Pair measurements are remaining width, not the whole row width.
        local next_width=math.min(150,math.max(88,(tonumber(required_width) or 250)*0.52))
        if pair_fits(next_width) then same_line(); return true end
        return false
    end

    local function text(value, disabled)
        if not imgui then return end
        local method = disabled and imgui.TextDisabled or imgui.Text
        local wrapped=false
        if type(imgui.PushTextWrapPos)=="function" and type(imgui.PopTextWrapPos)=="function" then
            wrapped=pcall(imgui.PushTextWrapPos,0)
        end
        if type(method) == "function" then pcall(method, tostring(value)) end
        if wrapped then pcall(imgui.PopTextWrapPos) end
    end

    local function input_text(label, current, maximum)
        if not imgui or type(imgui.InputText) ~= "function" then return tostring(current or "") end
        local caption,id=label:match("^(.-)##(.*)$")
        if caption then
            if caption~="" then text(caption,true) end
            label="##"..id
        end
        if type(imgui.SetNextItemWidth)=="function" then pcall(imgui.SetNextItemWidth,-1) end
        local ok, first, second = pcall(imgui.InputText, label, tostring(current or ""), 0)
        if not ok then return tostring(current or "") end
        if type(first) == "string" then return first:sub(1,maximum or #first) end
        if first == true and type(second) == "string" then return second:sub(1,maximum or #second) end
        return tostring(current or "")
    end

    local function section(title, subtitle)
        local ui = components()
        if ui and type(ui.section) == "function" then
            local ok = pcall(ui.section, title, subtitle)
            if ok then return end
        end
        text(title)
        if subtitle and subtitle ~= "" then text(subtitle, true) end
        if imgui and type(imgui.Separator) == "function" then pcall(imgui.Separator) end
    end

    local function card(id, title, subtitle, renderer, height)
        local ui = components()
        if ui and type(ui.card) == "function" then
            local ok = pcall(ui.card, id, title, subtitle, renderer, height)
            if ok then return end
        end
        section(title, subtitle)
        renderer()
    end

    local function empty_state(title, guidance)
        local ui = components()
        if ui and type(ui.empty_state) == "function" then
            local ok = pcall(ui.empty_state, title, guidance)
            if ok then return end
        end
        text(title, true)
        if guidance and guidance ~= "" then text(guidance, true) end
    end

    local function status_badge(label, kind)
        local ui = components()
        if ui and type(ui.status_badge) == "function" then
            local ok = pcall(ui.status_badge, label, kind)
            if ok then return end
        end
        text(label, true)
    end

    local function category_chip(label, selected, id, tooltip)
        local ui = components()
        if ui and type(ui.category_chip) == "function" then
            local ok, clicked = pcall(ui.category_chip, label, selected, id, tooltip)
            if ok then return clicked == true end
        end
        return button((selected and "> " or "") .. label, id, false, tooltip)
    end

    local function search_box(id, current, placeholder, maximum)
        local ui = components()
        if ui and type(ui.search_box) == "function" then
            local ok, value = pcall(ui.search_box, id, current, placeholder, maximum)
            if ok and type(value) == "string" then return value end
        end
        return input_text((placeholder or "Search") .. "##" .. id, current, maximum)
    end

    local function toggle_row(label, enabled, id, tooltip)
        local ui = components()
        if ui and type(ui.toggle_row) == "function" then
            local ok, value, clicked = pcall(ui.toggle_row, label, enabled == true, id, tooltip)
            if ok then return value == true, clicked == true end
        end
        text(label)
        local clicked = button(enabled and "ON" or "OFF", id, false, tooltip)
        if clicked then return not enabled,true end
        return enabled,false
    end

    local function selection_list(id, label, index, items)
        local ui=components()
        if ui and type(ui.compact_selector)=="function" then
            local ok,selected,changed=pcall(ui.compact_selector,id,label,index,items)
            if ok and items[selected] then return selected,changed==true end
        end
        if imgui and type(imgui.Combo)=="function" then
            if type(imgui.SetNextItemWidth)=="function" then pcall(imgui.SetNextItemWidth,-1) end
            local ok,selected,changed=pcall(imgui.Combo,label.."##"..id,index-1,items,#items,12)
            if ok and type(selected)=="number" and items[selected+1] then return selected+1,changed==true end
        end
        text(label..": "..tostring(items[index] or "None"),true)
        return index,false
    end

    local selector_cache={}
    local function value_stepper(label, value, minimum, maximum, step, id, tooltip, display_value, names)
        -- Render can run at the display refresh rate. Keep immutable catalogs
        -- across frames instead of allocating hundreds of paint/wheel rows.
        local cached=selector_cache[id]
        if not cached or cached.minimum~=minimum or cached.maximum~=maximum
            or cached.step~=step or cached.names~=names then
            cached={minimum=minimum,maximum=maximum,step=step,names=names,items={},captions={}}
            for candidate=minimum,maximum+step*0.001,step do
                local integral=minimum%1==0 and maximum%1==0 and step%1==0
                local number=integral and math.floor(candidate+0.5) or math.floor(candidate*1000+0.5)/1000
                local caption=names and names[number] or tostring(number)
                cached.items[#cached.items+1]={value=number,label=caption}
                cached.captions[#cached.captions+1]=caption
            end
            selector_cache[id]=cached
        end
        local items=cached.items
        local selected=math.max(1,math.min(#items,math.floor((value-minimum)/step+1.5)))
        if cached.display_index then
            local index=cached.display_index
            local caption=names and names[items[index].value] or tostring(items[index].value)
            items[index].label=caption;cached.captions[index]=caption
            cached.display_index=nil
        end
        if items[selected] and display_value and not (names and names[items[selected].value]) then
            items[selected].label=display_value;cached.captions[selected]=display_value
            cached.display_index=selected
        end
        local ui = components()
        if ui and type(ui.compact_selector) == "function" then
            local ok,next_index,changed=pcall(ui.compact_selector,id,label,selected,items,{stepper=true,tooltip=tooltip})
            if ok then return items[next_index] and items[next_index].value or value,changed==true end
        end
        if imgui and type(imgui.Combo)=="function" then
            local captions=cached.captions
            if type(imgui.SetNextItemWidth)=="function" then pcall(imgui.SetNextItemWidth,-1) end
            local ok,index,changed=pcall(imgui.Combo,label.."##"..id,selected-1,captions,#captions,12)
            if ok and type(index)=="number" and items[index+1] then return items[index+1].value,changed==true end
        end
        text(label..": "..tostring(display_value or value),true)
        return value,false
    end

    local function begin_columns(id, count)
        local ui = components()
        if ui and type(ui.begin_columns) == "function" then
            local ok, opened = pcall(ui.begin_columns, id, count)
            return ok and opened == true
        end
        return false
    end

    local function column(index)
        local ui = components()
        if ui and type(ui.column) == "function" then pcall(ui.column, index) end
    end

    local function next_row()
        local ui = components()
        if ui and type(ui.next_row) == "function" then pcall(ui.next_row) end
    end

    local function end_columns()
        local ui = components()
        if ui and type(ui.end_columns) == "function" then pcall(ui.end_columns) end
    end

    local function debug_mode()
        local diagnostics = module_context and module_context.CScript and module_context.CScript.Diagnostics
        return diagnostics and diagnostics.DebugMode == true or false
    end

    local function queue_action(action)
        if action=="refresh_store" then
            for index=#State.pending_actions,1,-1 do
                if State.pending_actions[index].name=="refresh_store" then table.remove(State.pending_actions,index) end
            end
        end
        if #State.pending_actions>=MAX_PENDING_ACTIONS then State.status="Please wait for the previous saved action"; return false end
        local adapter=module_context and module_context.CScript and module_context.CScript.StudioStorage
        local confirmation=adapter and adapter.GetPendingConfirmation()
        State.pending_actions[#State.pending_actions+1]={name=action,slot=State.selected_slot,
            rename=clean_field(State.rename_buffer,40),generation=State.generation,
            target_key=State.target and State.target.key,revision=State.edit_revision,
            saved_id=State.saved_id,saved_garage_id=State.saved_garage_id,source=State.saved_source,
            confirmation_token=confirmation and confirmation.token,local_confirmation=State.local_confirmation}
        return true
    end

    local function refresh_preview()
        if not State.current or not State.target then return false end
        local previous=fields(State.queued_snapshot or State.verified)
        local current=fields(State.current)
        local changed=false
        for key,value in pairs(current) do
            if not equal(value,previous[key]) then
                if validate_property(key,value) then
                    State.pending_edits[key]={value=clone_profile(value),generation=State.generation,key=State.target.key}
                    changed=true
                else
                    put_field(State.current,key,previous[key])
                    State.status="Change rejected: invalid value"
                end
            end
        end
        if changed then State.edit_revision=State.edit_revision+1; State.status="Applying" end
        State.queued_snapshot=clone_profile(State.current)
        return changed
    end

    local function queue_imani_sync46()
        local info=State.imani46
        local value=State.current and State.current.mods and State.current.mods[44]
        if not info or not info.supported or not State.target
            or (value~=-1 and value~=0 and value~=1) then return false end
        State.pending_edits["mods:44"]={value=value,generation=State.generation,key=State.target.key}
        State.edit_revision=State.edit_revision+1
        State.status="Applying Imani Tech"
        return true
    end

    local function apply_pending(no_undo)
        if next(State.pending_edits)==nil then return true end
        if not target_valid(State.target) then State.pending_edits={}; State.status="Vehicle changed; pending edit cancelled"; return false end
        local pending=State.pending_edits; State.pending_edits={}
        local drained_revision=State.edit_revision
        local target=State.target
        local actual=capture(target.vehicle)
        if not actual then State.last_failed_revision=drained_revision; State.status="Could not read current vehicle"; return false end
        local before=fields(actual); local undo={}; local failures={}
        local keys={}; for key in pairs(pending) do keys[#keys+1]=key end
        -- Family/palette first, dependent wheels/custom color last.
        local priority={wheel_type=1,primary=1,secondary=1,primary_finish=2,secondary_finish=2,
            primary_rgb=3,secondary_rgb=3,primary_custom=4,secondary_custom=4,pearl=5,wheel_color=5}
        table.sort(keys,function(a,b) return (priority[a] or 4)==(priority[b] or 4) and a<b or (priority[a] or 4)<(priority[b] or 4) end)
        for _,key in ipairs(keys) do
            local edit=pending[key]
            if edit.generation~=State.generation or edit.key~=target.key or not target_valid(target) then
                failures[#failures+1]="target changed"; break
            end
            local old=fields(actual)[key]
            if not equal(old,edit.value) or imani_needs_sync46(target.vehicle,key,edit.value) then
                local wrote,reason=write_property(target.vehicle,key,edit.value,actual)
                local after=target_valid(target) and capture_changed(target.vehicle,key,actual) or nil
                if after then
                    local observed=fields(after)
                    -- Record all verified side effects of this explicit operation for Undo.
                    for affected,value in pairs(fields(actual)) do
                        if observed[affected]~=nil and not equal(value,observed[affected]) then
                            if undo[affected]==nil then undo[affected]=clone_profile(value) end
                            if State.session_fields[affected]==nil then State.session_fields[affected]=clone_profile(value) end
                        end
                    end
                    actual=after
                end
                if not wrote or not after or not equal(fields(after)[key],edit.value) then
                    failures[#failures+1]=key..(reason and (": "..reason) or " (not confirmed)")
                end
            end
        end
        if target_valid(target) then
            local complete=capture(target.vehicle)
            if complete then
                State.last_poll_ms=now_ms()
                local observed=fields(complete)
                for key,value in pairs(before) do
                    if observed[key]~=nil and not equal(value,observed[key]) then
                        if undo[key]==nil then undo[key]=clone_profile(value) end
                        if State.session_fields[key]==nil then State.session_fields[key]=clone_profile(value) end
                    end
                end
                actual=complete
            else failures[#failures+1]="final readback unavailable" end
            local previous=State.verified
            State.verified=actual; State.current=clone_profile(actual)
            for key,edit in pairs(State.pending_edits) do
                if edit.key==target.key and edit.generation==State.generation then put_field(State.current,key,edit.value) end
            end
            State.queued_snapshot=clone_profile(State.current)
            refresh_capabilities(target.vehicle,target.model,actual,previous)
            if next(undo) and not no_undo then State.undo[#State.undo+1]={fields=undo,key=target.key,generation=State.generation} end
            if #State.undo>30 then table.remove(State.undo,1) end
        end
        if #failures>0 then
            State.last_failed_revision=drained_revision
            State.status="Partial application: "..table.concat(failures,", ")
            log_info("VEHICLE_STUDIO live=partial revision="..State.edit_revision.." fields="..table.concat(failures,","))
            return false
        end
        State.applied_revision=drained_revision; State.last_failed_revision=0
        State.status=next(State.pending_edits) and "Applying" or ("Editing "..tostring(actual.model_name or "current vehicle"))
        return true
    end

    local function bind_target(vehicle)
        local ui=components(); if ui and ui.reset_repeat_input then ui.reset_repeat_input() end
        stop_preview("target change")
        State.generation=State.generation+1
        State.pending_edits={}; State.pending_actions={}; State.undo={}; State.session_fields={}
        State.edit_revision=0; State.applied_revision=0; State.last_failed_revision=0
        State.store_confirmation=nil; State.local_confirmation=nil
        State.active_color_editor=nil;State.palette_rgb_requests={}
        State.target=nil; State.current=nil; State.verified=nil; State.baseline=nil; State.queued_snapshot=nil
        local identity=target_identity(vehicle)
        if not identity then State.status="No vehicle selected"; return false end
        identity.generation=State.generation
        local actual=capture(vehicle,"Current Vehicle",true)
        if not actual or not target_valid(identity) then State.status="Vehicle could not be read safely"; return false end
        State.target=identity; State.current=actual; State.verified=clone_profile(actual)
        State.baseline=clone_profile(actual); State.queued_snapshot=clone_profile(actual)
        State.last_poll_ms=now_ms()
        State.status="Editing "..tostring(actual.model_name or "current vehicle")
        State.selected_category=math.max(1,math.min(#VEHICLE_CATEGORIES,State.selected_category))
        State.mod_filter=""; State.preview_suppressed=false
        State.preview_category_key=nil
        if State.preview_auto_rotate then suggest_preview_category(true) end
        return true
    end
    local function render_named_stepper(label, key, minimum, maximum, names, tooltip)
        if State.current[key]==nil then text(label.." unavailable",true); return end
        local current = tonumber(State.current[key]) or minimum
        local display = names and names[current] or nil
        if not display then display = label.." "..(current+1).." (name unavailable)" end
        local next_value, changed = value_stepper(label, current, minimum, maximum, 1,
            "vm_value_" .. key, tooltip, display,names or (maximum==PAINT_INDEX_MAX and PAINT_INDEX_NAMES))
        if debug_mode() then text(("Raw value  %d"):format(current), true) end
        if changed and next_value ~= current then State.current[key] = next_value; refresh_preview() end
    end

    local function render_float_stepper(label, key, minimum, maximum, step, tooltip)
        if State.current[key]==nil then text(label.." unavailable",true); return end
        local current = tonumber(State.current[key]) or minimum
        local next_value, changed = value_stepper(label, current, minimum, maximum, step,
            "vm_float_" .. key, tooltip, tostring(current))
        if changed and next_value ~= current then
            State.current[key] = math.floor(next_value * 100 + 0.5) / 100
            refresh_preview()
        end
    end

    local function render_window_tint()
        local current=State.current.tint
        if current==nil then text("Window Tint unavailable",true);return end
        -- The documented native enum is 0..6. Keep each option's native ID
        -- explicit; a negative/unknown readback is a placeholder, not an extra
        -- factory option that shifts the visible catalog or writes a guessed ID.
        local items,captions,selected={}, {},1
        if not WINDOW_TINT_NAMES[current] then
            items[1]={label="Unspecified (game value "..tostring(current)..")"}
            captions[1]=items[1].label
        end
        for value=0,6 do
            items[#items+1]={value=value,label=WINDOW_TINT_NAMES[value]}
            captions[#captions+1]=WINDOW_TINT_NAMES[value]
            if value==current then selected=#items end
        end
        local ui=components()
        local ok,index,changed
        if ui and type(ui.compact_selector)=="function" then
            ok,index,changed=pcall(ui.compact_selector,"vm_value_tint","Window Tint",selected,items,{stepper=true})
        elseif imgui and type(imgui.Combo)=="function" then
            if type(imgui.SetNextItemWidth)=="function" then pcall(imgui.SetNextItemWidth,-1) end
            ok,index,changed=pcall(imgui.Combo,"Window Tint##vm_value_tint",selected-1,captions,#captions,8)
            if ok and type(index)=="number" then index=index+1 end
        else text("Window Tint: "..items[selected].label,true) end
        local item=ok and items[index]
        if changed==true and item and item.value~=nil and item.value~=current then
            State.current.tint=item.value;refresh_preview()
        end
    end

    local function rgb_to_hsv(red, green, blue)
        red, green, blue = clamp(red, 0, 255) / 255.0,
            clamp(green, 0, 255) / 255.0, clamp(blue, 0, 255) / 255.0
        local maximum, minimum = math.max(red, green, blue), math.min(red, green, blue)
        local delta = maximum - minimum
        local hue = 0.0
        if delta > 0.00001 then
            if maximum == red then hue = ((green - blue) / delta) % 6.0
            elseif maximum == green then hue = ((blue - red) / delta) + 2.0
            else hue = ((red - green) / delta) + 4.0 end
            hue = hue / 6.0
        end
        local saturation = maximum <= 0.00001 and 0.0 or delta / maximum
        return hue, saturation, maximum
    end

    local function hsv_to_rgb(hue, saturation, value)
        hue, saturation, value = (tonumber(hue) or 0.0) % 1.0,
            clamp(saturation, 0.0, 1.0), clamp(value, 0.0, 1.0)
        local sector = hue * 6.0
        local index = math.floor(sector)
        local fraction = sector - index
        local p, q, t = value * (1.0 - saturation),
            value * (1.0 - fraction * saturation), value * (1.0 - (1.0 - fraction) * saturation)
        local red, green, blue
        if index % 6 == 0 then red, green, blue = value, t, p
        elseif index == 1 then red, green, blue = q, value, p
        elseif index == 2 then red, green, blue = p, value, t
        elseif index == 3 then red, green, blue = p, q, value
        elseif index == 4 then red, green, blue = t, p, value
        else red, green, blue = value, p, q end
        return math.floor(red * 255 + 0.5), math.floor(green * 255 + 0.5), math.floor(blue * 255 + 0.5)
    end

    local function imgui_xy(method)
        if not imgui or type(imgui[method]) ~= "function" then return nil, nil end
        local ok, first, second = pcall(imgui[method])
        if not ok then return nil, nil end
        if type(first) == "table" then
            return tonumber(first.x or first.X or first[1]), tonumber(first.y or first.Y or first[2])
        end
        return tonumber(first), tonumber(second)
    end

    local function packed_color(red, green, blue, alpha)
        local ok, value = pcall(imgui.ColorConvertRGBAToU32,
            { math.floor(red), math.floor(green), math.floor(blue), math.floor(alpha or 255) })
        return ok and value or 0xFFFFFFFF
    end

    -- The host documents these drawing calls with integer RGBA values. Avoid
    -- guessing the undocumented ColorEdit3 Lua table/return-value convention.
    -- One HSV editor is retained so hue remains selectable even from black.
    local palette_editor
    local function rgb_controls(label,key,values)
        local result={}
        for index=1,3 do result[index]=math.floor(clamp(values[index],0,255)+0.5) end
        local available=select(1,imgui_xy("GetContentRegionAvail")) or 320
        local x,y=imgui_xy("GetCursorScreenPos")
        local supported=imgui and type(imgui.InvisibleButton)=="function"
            and type(imgui.AddRectFilled)=="function" and type(imgui.AddRect)=="function"
            and type(imgui.AddText)=="function" and type(imgui.IsItemActive)=="function"
            and type(imgui.GetMousePos)=="function" and type(imgui.AddRectFilledMultiColor)=="function"
            and type(imgui.ColorConvertRGBAToU32)=="function" and type(imgui.AddCircle)=="function"
        if not supported or not finite_number(x) or not finite_number(y)
            or not finite_number(available) or available<80 then
            text(label.." (color palette unavailable)",true)
            return result,false
        end
        local width=math.min(available,430)
        local open=State.active_color_editor==key
        local ok,clicked=pcall(imgui.InvisibleButton,"##vm_color_edit_"..key,width,28)
        if ok and clicked==true then
            if open then State.active_color_editor=nil else State.active_color_editor=key end
            open=State.active_color_editor==key
            if palette_editor then palette_editor.drag=nil end
        end
        pcall(imgui.AddRectFilled,x,y,x+width,y+28,17,18,23,250,5,0)
        pcall(imgui.AddRect,x,y,x+width,y+28,open and 164 or 55,open and 67 or 56,
            open and 244 or 66,230,5,0,1)
        pcall(imgui.AddRectFilled,x+5,y+5,x+27,y+23,result[1],result[2],result[3],255,3,0)
        local suffix=("#%02X%02X%02X"):format(result[1],result[2],result[3])
        local caption=label
        if width>=300 then caption=caption.."  "..suffix end
        pcall(imgui.AddText,x+35,y+6,caption,239,238,246,255)
        if not open then return result,false end

        local cache=palette_editor
        if not cache or cache.key~=key then
            local h,s,v=rgb_to_hsv(table.unpack(result))
            cache={key=key,h=h,s=s,v=v,last=clone_profile(result)};palette_editor=cache
        elseif not equal(cache.last,result) then
            local h,s,v=rgb_to_hsv(table.unpack(result))
            if s>0 then cache.h=h end
            cache.s,cache.v=s,v;cache.last=clone_profile(result);cache.drag=nil
        end
        local total_width=math.min(available,360)
        local hue_width,gap=18,10
        local square_width=total_width-hue_width-gap
        local square_height=math.min(180,square_width)
        x,y=imgui_xy("GetCursorScreenPos")
        if not x or not y then return result,false end
        local strip_x=x+square_width+gap
        local drawn=pcall(imgui.InvisibleButton,"##vm_palette_"..key,total_width,square_height)
        local active_ok,is_active=pcall(imgui.IsItemActive)
        local edited=false
        if drawn and active_ok and is_active==true then
            local mx,my=imgui_xy("GetMousePos")
            if finite_number(mx) and finite_number(my) then
                if not cache.drag then
                    cache.drag=mx<=x+square_width and "sv" or mx>=strip_x and "hue" or "gap"
                end
                if cache.drag=="sv" then
                    cache.s=clamp((mx-x)/square_width,0,1)
                    cache.v=1-clamp((my-y)/square_height,0,1)
                    edited=true
                elseif cache.drag=="hue" then
                    cache.h=clamp((my-y)/square_height,0,0.999999)
                    edited=true
                end
            end
        else cache.drag=nil end

        local r,g,b=hsv_to_rgb(cache.h,1,1)
        -- Separate hue/white and transparent/black layers produce the actual
        -- saturation/value gradient; a single four-colour quad does not.
        pcall(imgui.AddRectFilledMultiColor,x,y,x+square_width,y+square_height,
            packed_color(255,255,255,255),packed_color(r,g,b,255),
            packed_color(r,g,b,255),packed_color(255,255,255,255))
        pcall(imgui.AddRectFilledMultiColor,x,y,x+square_width,y+square_height,
            packed_color(0,0,0,0),packed_color(0,0,0,0),
            packed_color(0,0,0,255),packed_color(0,0,0,255))
        for segment=0,5 do
            local y1=y+square_height*segment/6
            local y2=y+square_height*(segment+1)/6
            local r1,g1,b1=hsv_to_rgb(segment/6,1,1)
            local r2,g2,b2=hsv_to_rgb((segment+1)/6,1,1)
            pcall(imgui.AddRectFilledMultiColor,strip_x,y1,strip_x+hue_width,y2,
                packed_color(r1,g1,b1,255),packed_color(r1,g1,b1,255),
                packed_color(r2,g2,b2,255),packed_color(r2,g2,b2,255))
        end
        local marker_x,marker_y=x+cache.s*square_width,y+(1-cache.v)*square_height
        pcall(imgui.AddCircle,marker_x,marker_y,5,255,255,255,255,20,2)
        pcall(imgui.AddCircle,marker_x,marker_y,6.5,0,0,0,220,20,1)
        local hue_y=y+cache.h*square_height
        pcall(imgui.AddRect,strip_x-2,hue_y-2,strip_x+hue_width+2,hue_y+2,255,255,255,255,0,0,1.5)
        local next_values={hsv_to_rgb(cache.h,cache.s,cache.v)}
        local changed=edited and not equal(result,next_values)
        if changed then result=next_values end
        cache.last=clone_profile(result)
        text(("#%02X%02X%02X"):format(result[1],result[2],result[3]),true)
        return result,changed==true
    end

    local function visual_color_picker(label,key)
        local values=State.current[key]
        if type(values)~="table" then text(label.." unavailable",true);return end
        local side=key=="primary_rgb" and "primary" or key=="secondary_rgb" and "secondary" or nil
        local replaces_effect=false
        if side and State.current[side.."_custom"]~=true then
            local fixed=PALETTE_RGB[State.current[side]]
            values=fixed or values
            replaces_effect=not fixed
        end
        local next_values,changed=rgb_controls(label,key,values)
        -- Keep conditional help below the active surface: becoming custom must
        -- not move the palette under a held pointer on the following frame.
        if replaces_effect and State.active_color_editor==key then
            text("Choosing a color replaces the current paint effect.",true)
        end
        if changed then
            State.current[key]=next_values
            if side then State.current[side.."_custom"]=true end
            refresh_preview()
        end
    end

    local function render_palette_rgb(label,key)
        local index=State.current[key]
        if index==nil then text(label.." unavailable",true);return end
        local request=State.palette_rgb_requests[key]
        if not request or request.index~=index then
            request={index=index,rgb=clone_profile(PALETTE_RGB[index] or {0,0,0})}
            State.palette_rgb_requests[key]=request
        end
        local rgb,changed=rgb_controls(label,key,request.rgb)
        if changed then
            local tint=closest_palette_tint(rgb)
            request.rgb,request.index=clone_profile(rgb),tint
            State.current[key]=tint
            refresh_preview()
        end
        local applied=State.verified and PALETTE_RGB[State.verified[key]]
        if State.active_color_editor==key then
            if applied then
                text(("Closest supported color #%02X%02X%02X"):format(applied[1],applied[2],applied[3]),true)
            else text("Choosing a color replaces the current effect with a supported tint.",true) end
        end
    end

    local function render_mod_row(mod_type, conceptual_label, tooltip)
        local label = conceptual_label or MOD_NAMES[mod_type] or ("Upgrade " .. tostring(mod_type))
        if TOGGLE_MODS[mod_type] then
            if State.toggle_presence[mod_type] ~= true then return 0 end
            local enabled = State.current.toggles[mod_type] == true
            local value, changed = toggle_row(label, enabled, "vm_mod_toggle_" .. mod_type, tooltip)
            if changed then State.current.toggles[mod_type] = value; refresh_preview() end
            return 1
        end
        local count = tonumber(State.mod_counts[mod_type]) or 0
        if count <= 0 then return 0 end
        if State.current.mods[mod_type]==nil then text(label.." unavailable",true); return 0 end
        local value = math.max(-1, math.min(count - 1, tonumber(State.current.mods[mod_type]) or -1))
        local labels=mod_type==44 and State.imani46 and State.imani46.supported and IMANI_CHOICES46
            or (State.mod_option_labels and State.mod_option_labels[mod_type] or {[-1]="Factory"})
        local display = labels[value] or (label.." "..(value+1).." (name unavailable)")
        if debug_mode() then display = display .. ("  (slot %d, raw %d)"):format(mod_type, value) end
        local next_value, changed = value_stepper(label, value, -1, count - 1, 1,
            "vm_mod_" .. mod_type, tooltip, display,labels)
        if changed and next_value ~= value then State.current.mods[mod_type] = next_value; refresh_preview() end
        return 1
    end

    local function render_imani46()
        local info=State.imani46
        if not info then return end
        if not info.supported then text("Imani Tech options could not be verified",true); return end
        render_mod_row(44,"Imani Tech",
            "Install the vehicle's supported Imani upgrade. Use Remote Control through GTA's Personal Vehicle controls.")
        if not info.confirmed then
            text("Imani effect not confirmed",true)
            if button("Apply Imani upgrade","vm_imani_reapply46",false) then queue_imani_sync46() end
        end
    end

    local function render_vehicle_category(category)
        if category=="Bodywork" then
            State.mod_filter=search_box("vm_mod_filter",State.mod_filter,"Filter bodywork",32)
            local shown=0
            for i=0,49 do
                local other=(i>=11 and i<=24) or (i==44 and State.imani46~=nil)
                if not other and (State.mod_filter=="" or (MOD_NAMES[i] or ""):lower():find(State.mod_filter:lower(),1,true)) then
                    shown=shown+render_mod_row(i)
                end
            end
            if State.livery_count>0 then render_named_stepper("Livery","livery",-1,State.livery_count-1,State.livery_labels) end
            if (State.roof_livery_count or 0)>0 then render_named_stepper("Roof Livery","roof_livery",-1,State.roof_livery_count-1,{[-1]="Factory"}) end
            if shown==0 and State.livery_count==0 then text("No bodywork options for this model",true) end
        elseif category=="Paint" then
            for _,side in ipairs({"primary","secondary"}) do
                local label=side=="primary" and "Primary" or "Secondary"
                render_named_stepper(label.." Finish",side.."_finish",0,6,PAINT_FINISH_NAMES)
                visual_color_picker(label.." Color",side.."_rgb")
            end
            for _,spec in ipairs({{"Pearlescent","pearl"},{"Interior Color","interior_color"},
                    {"Dashboard Color","dashboard_color"}}) do
                render_palette_rgb(spec[1],spec[2])
            end
        elseif category=="Wheels" then
            local bike=State.current.vehicle_class==8 or State.current.vehicle_class==13
            render_named_stepper("Wheel Family","wheel_type",bike and 6 or 0,bike and 6 or 12,WHEEL_TYPE_NAMES)
            render_palette_rgb("Wheel Color","wheel_color")
            for _,i in ipairs({23,24}) do
                if render_mod_row(i)>0 and State.current.mod_variations[i]~=nil then
                    local value,changed=toggle_row(i==23 and "Custom front tyres" or "Custom rear tyres",State.current.mod_variations[i],"vm_variation_"..i)
                    if changed then State.current.mod_variations[i]=value; refresh_preview() end
                end
            end
            if State.current.tyres_can_burst~=nil then
                local value,changed=toggle_row("Bulletproof Tyres",not State.current.tyres_can_burst,"vm_tyres")
                if changed then State.current.tyres_can_burst=not value; refresh_preview() end
            end
            if State.current.drift_tyres~=nil then
                local value,changed=toggle_row("Low Grip Tyres",State.current.drift_tyres,"vm_drift_tyres")
                if changed then State.current.drift_tyres=value; refresh_preview() end
            end
        elseif category=="Performance" then
            for _,i in ipairs({11,12,13,15,16,17,18,19,21}) do render_mod_row(i) end
            render_imani46()
        elseif category=="Lights & Extras" then
            render_mod_row(14); render_mod_row(20); render_mod_row(22)
            render_named_stepper("Xenon Color","xenon_color",-1,12,XENON_COLOR_NAMES)
            visual_color_picker("Neon Color","neon_rgb")
            for i,label in ipairs({"Left Neon","Right Neon","Front Neon","Rear Neon"}) do
                if State.current.neon_enabled[i-1]~=nil then
                    local value,changed=toggle_row(label,State.current.neon_enabled[i-1],"vm_neon_"..i)
                    if changed then State.current.neon_enabled[i-1]=value; refresh_preview() end
                end
            end
            visual_color_picker("Tyre Smoke Color","tyre_smoke_rgb")
            if State.current.tyre_smoke_rgb and State.toggle_presence[20] then
                local patriot=equal(State.current.tyre_smoke_rgb,{0,0,0})
                local value,changed=toggle_row("Patriot Tyre Smoke",patriot,"vm_patriot_smoke")
                if changed then
                    State.current.tyre_smoke_rgb=value and {0,0,0} or {255,255,255}
                    if value then State.current.toggles[20]=true end
                    refresh_preview()
                end
            end
            for i=0,20 do
                if State.current.extras[i]~=nil then
                    local value,changed=toggle_row("Extra "..i,State.current.extras[i],"vm_extra_"..i)
                    if changed then State.current.extras[i]=value; refresh_preview() end
                end
            end
        elseif category=="Plate & Finish" then
            render_window_tint()
            render_named_stepper("Plate Style","plate_index",0,(State.plate_count or 6)-1,PLATE_STYLE_NAMES)
            if State.current.plate_text~=nil then
                local plate=input_text("Plate Text##vm_plate_text",State.current.plate_text,8):gsub("[^%w ]",""):sub(1,8)
                if plate~=State.current.plate_text then State.current.plate_text=plate; refresh_preview() end
            end
            render_float_stepper("Dirt (temporary)","dirt_level",0,15,1)
            render_float_stepper("Reflection (temporary)","env_effect",0,1,0.1)
        elseif category=="Quick Builds" then
            text("These change the current vehicle immediately. Undo is available.",true)
            if button("Randomize all","vm_randomize_all",true) then queue_action("randomize") end
            for _,name in ipairs({"Stock+","Race","Drift","Show","Offroad","Armored"}) do
                if button(name,"vm_template_"..name,false) then queue_action("template:"..name) end
            end
        end
    end

    local function render_category_browser()
        local selected,changed=selection_list("vm_category","Category",State.selected_category,VEHICLE_CATEGORIES)
        if changed then State.selected_category=selected; State.active_color_editor=nil end
    end
    local function render_preview_controls()
        local ui=components()
        State.preview_input_ping=true
        local view_open=State.preview_cam~=0 and State.preview_phase~="failed"
        local auto,changed=toggle_row("Auto camera",State.preview_auto_rotate,"vm_auto_rotate",
            "Frame the selected category automatically. Turn off to hold right mouse and orbit, or scroll to zoom.")
        if changed then queue_action(auto and "auto_on" or "auto_off") end
        if ui and type(ui.studio_camera_input)=="function" then
            local input=ui.studio_camera_input("vehicle",view_open and not State.preview_auto_rotate) or {}
            State.preview_viewport=input.viewport
            for _,spec in ipairs({{"orbit_x","preview_orbit_x"},{"orbit_y","preview_orbit_y"},{"wheel","preview_wheel"}}) do
                local value=tonumber(input[spec[1]])
                if finite_number(value) then State[spec[2]]=State[spec[2]]+value end
            end
        elseif ui and type(ui.studio_viewport)=="function" then
            State.preview_viewport=ui.studio_viewport()
        end
        local want_open,changed_view=toggle_row("Open view",view_open,"vm_view_toggle")
        if changed_view then
            State.preview_suppressed=not want_open
            if not want_open then queue_action("close")
            else State.preview_failure=nil;State.preview_phase="idle" end
        end
        State.preview_hold_rotate,State.preview_hold_zoom=0,0
        local lighting,lighting_changed=toggle_row("Studio lighting",State.preview_lighting,"vm_lighting")
        if lighting_changed then State.preview_lighting=lighting end
        local names={"Front","Front 3/4","Rear 3/4","Side","Rear","High","Free"}
        local keys={"front","front_three_quarter","rear_three_quarter","side","rear","high_three_quarter","free"}
        local selected=7
        for i,key in ipairs(keys) do if State.preview_angle_preset==key then selected=i end end
        local next_angle,angle_changed=selection_list("vm_angle","Angle",selected,names)
        if angle_changed and keys[next_angle] then queue_action("view:"..keys[next_angle]) end
        if State.preview_failure then text("View unavailable: "..State.preview_failure.reason,true)
        elseif State.preview_phase=="starting" then text("Opening view",true) end
    end

    local function storage()
        return module_context and module_context.CScript and module_context.CScript.StudioStorage
    end
    local function render_local_builds()
        State.local_filter=search_box("vm_local_filter",State.local_filter or "","Find local preset",40)
        local ui=components()
        local slot_labels,slot_values,selected_choice={},{},1
        for index=1,math.max(1,#State.slots)do
            local slot=State.slots[index] or empty_vehicle_slot()
            local occupied=vehicle_slot_has_data(slot)
            local name=tostring(slot.name or "")
            local display=name~="" and name or (occupied and "Unnamed preset" or "Empty slot")
            local selected=State.selected_slot==index
            if selected or State.local_filter=="" or display:lower():find(State.local_filter:lower(),1,true) then
                slot_labels[#slot_labels+1]=("%d / %s"):format(index,display)
                slot_values[#slot_values+1]=index
                if selected then selected_choice=#slot_values end
            end
        end
        if #slot_labels>0 then
            local choice,picked=selection_list("vm_local_slot","Local Slot",selected_choice,slot_labels)
            if picked and slot_values[choice] then
                local index=slot_values[choice]
                local slot=State.slots[index] or empty_vehicle_slot()
                State.selected_slot=index
                State.rename_buffer=tostring(slot.name or "")
                State.rename_buffer_slot=index
                State.local_confirmation=nil
            end
        else
            text("No matching local presets",true)
        end
        if styled_button("Add Slot","vm_local_add","secondary","Add an empty local preset slot.") then queue_action("add_slot") end
        local slot=State.slots[State.selected_slot] or empty_vehicle_slot()
        local occupied=vehicle_slot_has_data(slot)
        local name=tostring(slot.name or "")
        text(("Destination: Local slot %d  /  %s"):format(State.selected_slot,
            name~="" and name or (occupied and "Unnamed preset" or "Empty slot")),true)
        if State.rename_buffer_slot~=State.selected_slot or State.rename_buffer==nil then
            State.rename_buffer_slot=State.selected_slot;State.rename_buffer=name
        end
        local previous_name=State.rename_buffer
        State.rename_buffer=input_text("Name##vm_local_name",State.rename_buffer,40)
        if previous_name~=State.rename_buffer then State.local_confirmation=nil end
        if occupied and button("Use on Vehicle","vm_local_apply",false) then queue_action("load_slot") end
        if occupied then pair_line(250) end
        if button(occupied and "Overwrite Selected" or "Save Current","vm_local_save",true) then queue_action("save_slot") end
        pair_line(235)
        if button("Rename","vm_local_rename",false) then queue_action("rename_slot") end
        if occupied then
            pair_line(280)
            if button("Duplicate","vm_local_duplicate",false) then queue_action("duplicate_slot") end
            if button(slot.favorite and "Unfavorite" or "Favorite","vm_local_favorite",false) then queue_action("favorite_slot") end
            pair_line(235)
            if styled_button("Delete / Clear","vm_local_delete","danger") then queue_action("delete_slot") end
        end
        if State.local_confirmation then
            text(State.local_confirmation.label,true)
            if styled_button("Confirm","vm_local_confirm","danger") then queue_action("confirm_local") end
            pair_line(180)
            if styled_button("Cancel","vm_local_cancel","secondary") then State.local_confirmation=nil end
        end
        if State.storage_error then text(State.storage_error,true) end
    end

    local function render_saved_builds()
        local sources={"Cherax Saved Vehicles","GTA Personal Vehicles","Local Presets"}
        local ids={"cherax_vehicles","gta_personal_vehicles","local_presets"}
        local selected=State.saved_source==ids[2] and 2 or State.saved_source==ids[3] and 3 or 1
        local ui=components()
        local index,changed=selection_list("vm_saved_source","Source",selected,sources)
        if changed and ids[index] then
            State.saved_source=ids[index]; selected=index; State.saved_id=nil; State.saved_garage_id=nil; State.saved_filter=""
            State.store_confirmation=nil; State.local_confirmation=nil; State.personal_confirm=nil
            State.personal_save_error=nil
            State.personal_auto_browse_id=nil
            State.rename_buffer=""
            queue_action("refresh_store")
        end
        State.saved_visible_until_ms=now_ms()+1500
        if State.saved_source=="local_presets" then render_local_builds(); return end
        local adapter=storage()
        if not adapter or type(adapter.GetEntries)~="function" then text("Saved source adapter unavailable",true); return end
        State.saved_filter=search_box("vm_saved_filter",State.saved_filter,"Search saved vehicles",64)
        local all_entries=adapter.GetEntries(State.saved_source) or {}
        local entries=adapter.GetEntries(State.saved_source,State.saved_filter) or {}
        local function select_destination(entry)
            State.saved_id=entry and entry.id or nil; State.store_confirmation=nil; State.personal_confirm=nil
            State.personal_save_error=nil
            State.rename_buffer=""
            adapter.CancelVehicle()
        end
        local function entry_selector(id,label,rows,selected_id)
            local labels={"Select "..label:lower()}; local current=1
            for i,entry in ipairs(rows) do
                labels[i+1]=(entry.display_index and (entry.display_index.." / ") or "")..tostring(entry.name)
                if entry.id==selected_id then current=i+1 end
            end
            local index,changed=selection_list(id,label,current,labels)
            if changed then return rows[index-1],true end
            return nil,false
        end
        local selected_garage
        if State.saved_source=="gta_personal_vehicles" then
            local garages={}; local chosen
            for _,entry in ipairs(all_entries) do
                if entry.kind=="garage" then
                    garages[#garages+1]=entry
                    if entry.id==State.saved_garage_id then chosen=entry end
                end
            end
            if not chosen then
                for _,entry in ipairs(garages) do if entry.selected then chosen=entry; break end end
                State.saved_garage_id=chosen and chosen.id or nil
            end
            local picked,changed=entry_selector("vm_personal_garage","Garage",garages,State.saved_garage_id)
            if changed then
                chosen=picked
                State.saved_garage_id=picked and picked.id or nil
                select_destination(picked)
                -- Changing a garage must load its contents automatically.
                -- Wait for the selection-cancel request to settle first.
                State.personal_auto_browse_id=picked and picked.id or nil
            end
            selected_garage=chosen
            local vehicles={}
            for _,entry in ipairs(entries) do
                if entry.kind=="vehicle" and chosen and entry.garage_index==chosen.list_index
                    and entry.garage_revision==chosen.revision then vehicles[#vehicles+1]=entry end
            end
            if chosen and not chosen.selected then
                local snap=adapter.GetStatus()
                if State.personal_auto_browse_id or (snap and (snap.busy or snap.cancel_pending)) then
                    text("Loading vehicles...",true)
                elseif snap and snap.status and snap.status~="Garage ready" then
                    text(tostring(snap.status),true)
                end
            else
                local vehicle,vehicle_changed=entry_selector("vm_personal_vehicle","Vehicle",vehicles,State.saved_id)
                if vehicle_changed then select_destination(vehicle) end
                if #vehicles==0 then text(State.saved_filter~="" and "No matching vehicles" or "No vehicles reported for this garage",true) end
            end
        else
            local picked,changed=entry_selector("vm_saved_vehicle","Saved vehicle",entries,State.saved_id)
            if changed then select_destination(picked) end
            if #entries==0 then text("No matching saved vehicles",true) end
        end
        local selected_entry
        for _,entry in ipairs(all_entries) do if entry.id==State.saved_id then selected_entry=entry; break end end
        local destination_label=selected_entry and selected_entry.name
        if selected_entry and selected_entry.kind=="vehicle" then
            destination_label=(selected_entry.garage and (selected_entry.garage.." / ") or "")
                .."entry "..tostring(selected_entry.display_index or selected_entry.list_index).." / "..selected_entry.name
        end
        text(selected_entry and ("Selected: "..sources[selected].." / "..destination_label) or "Select a destination",true)
        if selected_entry and debug_mode() then text("Storage ID: "..selected_entry.id,true) end
        local capabilities=adapter.GetCapabilities(State.saved_source) or {}
        if State.saved_source=="gta_personal_vehicles" then
            local pending=State.personal_auto_browse_id
            if pending then
                local status=adapter.GetStatus()
                if State.saved_id~=pending or State.saved_garage_id~=pending then
                    State.personal_auto_browse_id=nil
                elseif status and not status.busy and not status.cancel_pending then
                    if queue_action("personal:browse") then
                        State.personal_auto_browse_id=nil
                    end
                end
            end
            if selected_entry and selected_entry.kind=="vehicle" and capabilities.request then
                if button("Request Vehicle","vm_personal_request",true) then queue_action("personal:request") end
            end
            if capabilities.return_current then
                pair_line(170)
                if button("Return Current Vehicle","vm_personal_return",false) then
                    queue_action("personal:return_current")
                end
            end
            -- A garage destination is independent of Vehicle Studio's editor
            -- selection. The Saved tab is frequently used while the editor has
            -- no captured vehicle, even when the player is driving in GTA.
            -- Do not hide the action behind State.current or State.target.
            if selected_garage then
                if button("Save Current to Garage","vm_personal_convert",true,
                        "Store the vehicle you are driving in the selected garage.") then
                    if capabilities.convert then
                        State.personal_save_error=nil
                        State.personal_confirm={kind="convert",id=selected_garage.id,
                            name=tostring(selected_garage.name),issued=now_ms()}
                    else
                        State.personal_save_error="Garage saving unavailable: select and load an owned garage, or check Cherax vehicle conversion support."
                    end
                end
                if State.personal_save_error then text(State.personal_save_error,true) end
            end
            if selected_entry and selected_entry.kind=="vehicle" and capabilities.delete then
                if styled_button("Delete Selected","vm_personal_delete","danger") then
                    State.personal_confirm={kind="delete",id=selected_entry.id,
                        name=tostring(selected_entry.name),issued=now_ms()}
                end
            end
            local pending=State.personal_confirm
            if pending then
                local valid=(pending.kind=="delete" and State.saved_id==pending.id)
                    or (pending.kind=="convert" and State.saved_garage_id==pending.id)
                if not valid or now_ms()-(pending.issued or 0)>30000 then
                    State.personal_confirm=nil
                else
                    text((pending.kind=="delete" and "Delete " or "Save vehicle to ")
                        ..pending.name.."?",true)
                    if styled_button("Confirm","vm_personal_confirm","danger") then
                        if queue_action("personal:"..pending.kind) then
                            State.personal_confirm=nil
                        end
                    end
                    pair_line(130)
                    if button("Cancel","vm_personal_cancel",false) then State.personal_confirm=nil end
                end
            end
            local status=adapter.GetStatus()
            if status and status.status and status.status~="Ready" and status.status~="Queued" then
                local msg=tostring(status.status)
                if (msg:lower():find("unavailable",1,true) or msg:lower():find("failed",1,true))
                    and type(status.detail)=="string" and status.detail~="" then
                    msg=msg..": "..status.detail
                end
                text(msg,true)
            end
            -- Do not turn this panel into a diagnostic readout. Individual
            -- operations report concise errors only after the user acts.
            return
        end
        State.rename_buffer=input_text("Name (optional)##vm_store_name",State.rename_buffer,64)
        if button("Save as New","vm_store_new",true) then queue_action("store:new") end
        if selected_entry then
            text("Load customization without spawning: saved mod encoding is not verified; use Local Presets for this action",true)
            if capabilities.spawn then
                if button("Spawn Selected","vm_store_spawn",false) then queue_action("store:spawn") end
            else text("Spawn unavailable: refresh Cherax's saved list and select an unambiguous current entry so its native index can be verified.",true) end
            if button("Overwrite Selected","vm_store_overwrite",false) then queue_action("store:overwrite") end
            pair_line(270)
            if button("Rename","vm_store_rename",false) then queue_action("store:rename") end
            pair_line(220); if button("Duplicate","vm_store_duplicate",false) then queue_action("store:duplicate") end
            pair_line(230)
            if styled_button("Delete","vm_store_delete","danger") then queue_action("store:delete") end
        end
        local store_status=adapter.GetStatus()
        if store_status and store_status.status then
            text(tostring(store_status.status),true)
            if debug_mode() and store_status.detail then text(store_status.detail,true) end
        end
        local confirmation=adapter.GetPendingConfirmation()
        if confirmation and confirmation.id~=State.saved_id then confirmation=nil end
        if confirmation then
            local labels={prepare_overwrite="Overwrite",overwrite="Overwrite",prepare_rename="Rename",rename="Rename",prepare_delete="Delete",delete="Delete"}
            text((labels[confirmation.operation] or "Change").." Cherax Saved Vehicles / "..tostring(confirmation.name).."?")
            if button("Confirm","vm_store_confirm",false) then queue_action("store:confirm") end
            pair_line(200); if button("Cancel","vm_store_cancel",false) then adapter.CancelVehicle() end
        end
    end
    local function render_manager()
        State.visible_ping=true
        local ui=components()
        if ui and type(ui.studio_workspace_touch)=="function" then ui.studio_workspace_touch("vehicle") end
        section("Vehicle Studio")
        if State.target==nil or (type(State.status)=="string" and
            (State.status:lower():find("fail",1,true) or State.status:lower():find("error",1,true))) then
            text(State.status,State.target==nil)
        end
        if ui and ui.studio_layout then
            local w,h,mode=ui.studio_layout(); State.layout_width=w; State.layout_height=h; State.layout_breakpoint=mode
        end
        local previous_workspace=State.workspace_tab
        -- Match the other CScript categories using Cherax's native tab row.
        if ui and type(ui.context_tabs)=="function"then
            local chosen=ui.context_tabs("vehicle_studio_workspace",{
                {key="editor",label="Customize"},{key="builds",label="Saved"}
            },State.workspace_tab)
            if chosen=="editor" or chosen=="builds"then State.workspace_tab=chosen end
        else
            text("Cherax tab bar unavailable.",true)
        end
        if previous_workspace~=State.workspace_tab then
            State.active_color_editor=nil
            if ui and ui.reset_repeat_input then ui.reset_repeat_input() end
        end
        local subject=State.workspace_tab=="builds" and "saved_library" or (State.target and State.target.key or "none")
        local function body(renderer,workspace)
            if ui and type(ui.studio_workspace_body)=="function" then
                ui.studio_workspace_body("vehicle_studio",workspace,subject,renderer)
            else renderer() end
        end
        if State.workspace_tab=="builds" then
            if ui and type(ui.studio_camera_input)=="function" then ui.studio_camera_input("vehicle",false) end
            body(render_saved_builds,"builds:"..State.saved_source); return
        end
        if not State.current then text("Enter a vehicle to edit it. Saved vehicles are available on foot.",true); return end
        -- Keep the view and category reachable while only the selected editor
        -- scrolls. Removing nested cards returns their padding to the controls.
        render_preview_controls()
        render_category_browser()
        body(function()
            if button("Undo last","vm_undo",false) then queue_action("undo") end
            pair_line(300); if button("Revert session","vm_revert",false) then queue_action("revert") end
            render_vehicle_category(VEHICLE_CATEGORIES[State.selected_category])
        end,"editor:"..tostring(State.selected_category))

    end


    local api = {
        State = State, RenderManager = render_manager, StopPreview = stop_preview,
        Capture = capture, Apply = apply, CloneProfile = clone_profile,
        GetImaniStatus=read_imani46,
        QueueEdit=function(key,value)
            if not State.current or fields(State.current)[key]==nil or not validate_property(key,value) then return false end
            put_field(State.current,key,value)
            return refresh_preview()
        end,
        QueueAction=queue_action,
    }
    local function save_ticket()
        if not State.target then return nil,"No vehicle selected" end
        if not target_valid(State.target) or next(State.pending_edits)
            or State.applied_revision~=State.edit_revision or State.last_failed_revision~=0 then
            return nil,"Save stopped: current edit is not verified"
        end
        local target=clone_profile(State.target)
        local revision=State.edit_revision
        local actual=capture(target.vehicle)
        if not actual or not target_valid(target) then return nil,"Save stopped: vehicle changed" end
        local expected=fields(State.verified)
        local observed=fields(actual)
        -- Reconcile external modifications before constructing the exact save ticket.
        State.verified=clone_profile(actual); State.current=clone_profile(actual); State.queued_snapshot=clone_profile(actual)
        return {handle=target.vehicle,subject_key=target.key,generation=State.generation,edit_revision=revision,
            applied_revision=State.applied_revision,model=actual.model,profile=actual,
            validate=function()
                if not target_valid(target) or State.edit_revision~=revision or next(State.pending_edits)
                    or State.applied_revision~=revision or State.last_failed_revision~=0 then return false end
                local fresh=capture(target.vehicle)
                return fresh~=nil and equal(fields(fresh),observed)
            end}
    end

    local function read_local_bytes()
        local path=profile_path()
        if not path or not FileMgr or type(FileMgr.ReadFileContent)~="function" then return nil end
        if type(FileMgr.DoesFileExist)=="function" then
            local ok,exists=pcall(FileMgr.DoesFileExist,path)
            if ok and not exists then return "" end
        end
        local ok,value=pcall(FileMgr.ReadFileContent,path)
        return ok and type(value)=="string" and value or nil
    end
    local function backup_local(bytes)
        local path=profile_path()
        if not path or type(bytes)~="string" then return false end
        State.local_backup_serial=(tonumber(State.local_backup_serial) or 0)+1
        local backup=path..".studio-backup-"..tostring(now_ms()).."-"..State.generation.."-"..State.local_backup_serial..".txt"
        local ok,result=pcall(FileMgr.WriteFileContent,backup,bytes,false)
        if not ok or result==false then return false end
        local read_ok,readback=pcall(FileMgr.ReadFileContent,backup)
        if not read_ok or readback~=bytes then return false end
        State.last_backup_path=backup
        return true,backup
    end
    local function persist_local(action,context,confirmed)
        if State.storage_error then State.status=State.storage_error;return end
        local index=tonumber(context.slot)
        local existing=index and State.slots[index]
        if not existing then State.status="Save cancelled: local destination changed";return end
        local bytes=read_local_bytes()
        if bytes==nil then State.status="Save failed: local library could not be read";return end
        if State.storage_bytes==nil or bytes~=State.storage_bytes then
            State.loaded=false;State.local_confirmation=nil
            State.status="Local Presets changed externally; refresh before saving"
            return
        end
        local ticket,reason
        if action=="save_slot" then
            ticket,reason=save_ticket()
            if not ticket then State.status=reason;return end
        end
        if (action=="delete_slot" or (action=="save_slot" and vehicle_slot_has_data(existing))) and not confirmed then
            local ok,backup=backup_local(bytes)
            if not ok then State.status="Save failed: recoverable backup could not be verified";return end
            State.local_confirmation={label=(action=="delete_slot" and "Clear " or "Overwrite ").."Local Presets slot "..index.." / "..tostring(existing.name).."?",
                action=action,context=clone_profile(context),bytes=bytes,ticket=ticket,backup=backup,generation=State.generation}
            return
        end
        local candidate=snapshot_slots()
        local destination=index
        if action=="add_slot" then
            destination=#candidate+1;candidate[destination]=empty_vehicle_slot()
        elseif action=="save_slot" then
            local profile=clone_profile(ticket.profile)
            profile.name=clean_field(context.rename,40)
            profile.created=existing.created~="" and existing.created or timestamp_now()
            profile.modified=timestamp_now();profile.favorite=existing.favorite==true
            candidate[index]=profile
        elseif action=="delete_slot" then
            candidate[index]=empty_vehicle_slot()
        elseif action=="rename_slot" then
            candidate[index].name=clean_field(context.rename,40);candidate[index].modified=timestamp_now()
        elseif action=="duplicate_slot" then
            if not vehicle_slot_has_data(existing) then State.status="Selected local slot is empty";return end
            local empty
            for i,slot in ipairs(State.slots)do
                if i~=index and not vehicle_slot_has_data(slot) and tostring(slot.name or "")==""
                    and tostring(slot.created or "")=="" and tostring(slot.modified or "")=="" and not slot.favorite then
                    empty=i;break
                end
            end
            destination=empty or (#candidate+1)
            candidate[destination]=clone_profile(existing)
            local name=tostring(existing.name or "")
            candidate[destination].name=name~="" and (name.." Copy"):sub(1,40) or ""
            candidate[destination].created=timestamp_now();candidate[destination].modified=candidate[destination].created
        elseif action=="favorite_slot" then
            if not vehicle_slot_has_data(existing) then return end
            candidate[index].favorite=not existing.favorite;candidate[index].modified=timestamp_now()
        else return end
        -- Every mutation of an existing library retains its exact prior bytes.
        -- FileMgr exposes no atomic rename, so a partial write is recoverable
        -- from this verified copy and must never be reported as a saved edit.
        if bytes~="" then
            local backed=backup_local(bytes)
            if not backed then State.status="Save failed: recoverable backup could not be verified";return end
        end
        if ticket and not ticket.validate() then State.status="Save cancelled: current vehicle changed";return end
        if read_local_bytes()~=bytes then State.status="Save cancelled: local library changed externally";return end
        if not commit_slots(candidate) then
            State.status=bytes~="" and "Save failed: file readback did not match; original presets remain in the verified backup"
                or "Save failed: local file write/readback"
            return
        end
        State.selected_slot=destination;State.rename_buffer=tostring(candidate[destination].name or "")
        State.rename_buffer_slot=destination;State.local_confirmation=nil
        if action=="add_slot" or action=="duplicate_slot" then State.local_filter="" end
        State.status=action=="add_slot" and "Empty slot added" or "Saved to Local Presets"
    end

    local function studio_safety(active)
        -- Keep protection until every camera/preview cleanup attempt finishes.
        -- A hidden page must not expose the real ped behind a stuck studio cam.
        if not active and (State.preview_cam~=0 or State.preview_cleanup_pending) then
            State.safety_release_pending=true
            return false
        end
        local player=module_context and module_context.CScript and module_context.CScript.Player
        local method=player and player[active and "AcquireStudioSafety" or "ReleaseStudioSafety"]
        if type(method)~="function" then
            if not active and not State.safety_acquired then State.safety_release_pending=false;return true end
            return false
        end
        local ok,result=pcall(method,"vehicle")
        if active and ok and result==true then State.safety_acquired=true end
        if not active then
            State.safety_release_pending=not (ok and result==true)
            if not State.safety_release_pending then State.safety_acquired=false end
        end
        return ok and result==true
    end

    local function workspace_visible(now)
        local ui=components()
        if ui and type(ui.studio_workspace_visible)=="function" then
            local ok,visible=pcall(ui.studio_workspace_visible,"vehicle")
            if ok and type(visible)=="boolean" then return visible end
        end
        return now-State.last_visible_ms<=650
    end

    local function randomize_vehicle()
        local before=fields(State.current)
        local family_ok=true
        local function random_bool() return math.random(0,1)==1 end
