                State.status="Saved action cancelled: destination changed"; return
            end
            if not adapter or type(adapter.QueuePersonalAction)~="function" then State.status="Personal vehicle request backend unavailable"; return end
            local operation=action:sub(10)
            if operation=="convert" and context.saved_garage_id~=State.saved_garage_id then
                State.status="Garage selection changed"; return
            end
            local id=operation=="convert" and context.saved_garage_id or context.saved_id
