            local confirmation=State.local_confirmation; State.local_confirmation=nil
            if not confirmation or confirmation~=context.local_confirmation or confirmation.generation~=State.generation
                or confirmation.context.slot~=State.selected_slot or read_local_bytes()~=confirmation.bytes
                or (confirmation.ticket and not confirmation.ticket.validate()) then
                State.status="Confirmation expired: destination or vehicle changed"; return
            end
            persist_local(confirmation.action,confirmation.context,true); return
        end
        if action=="add_slot" or action=="save_slot" or action=="delete_slot" or action=="rename_slot" or action=="duplicate_slot" or action=="favorite_slot" then
            if action=="save_slot" and (context.generation~=State.generation or context.target_key~=(State.target and State.target.key)) then
                State.status="Save cancelled: vehicle changed"; return
            end
            persist_local(action,context,false); return
        end
        if context.generation~=State.generation or context.target_key~=(State.target and State.target.key) or not target_valid(State.target) then
            State.status="Vehicle changed; action cancelled"; return
        end
        if action=="undo" or action=="revert" then
            local previous=action=="undo" and table.remove(State.undo) or {fields=State.session_fields,key=State.target.key,generation=State.generation}
            if not previous or previous.key~=State.target.key or previous.generation~=State.generation then State.status="No session change to undo"; return end
            for key,value in pairs(previous.fields) do
                State.pending_edits[key]={value=clone_profile(value),key=State.target.key,generation=State.generation}
            end
