            if not profile or (profile.model or 0)==0 then State.status="Selected local slot is empty"; return end
            if profile.model~=State.target.model then State.status="Saved build belongs to a different vehicle model"; return end
            for key,value in pairs(fields(profile)) do
                if fields(State.current)[key]~=nil then put_field(State.current,key,value) end
            end
