        AIM_CAM = 0x68EDDA28A5976D07, PAUSED = 0xB0034A223497FFCB,
        CAM_RENDERING = 0x39B5D1B10383F0C8, FRAME_TIME = 0x15C40837039FFAF7,
        CAM_COORD = 0x14D6F5678D8F1B37, CAM_ROT = 0x837765A25378F0BB,
        CAM_FOV = 0x65019750A0324133,
        GET_REL_HEAD = 0x743607648ADD4587, SET_REL_HEAD = 0xB4EC2312F4E5B1F1,
        GET_REL_PITCH = 0x3A6867B4845BEDA2, SET_REL_PITCH = 0x6D0858B8EDFD2B7D,
        BONE = 0x17C07FC640E86B4E, LOS = 0xFCDFF7B72D23A1AC,
        GHOST = 0x21D04D7BC538C146,
    }
    local function finite(v)
        return type(v) == "number" and v == v and math.abs(v) < math.huge
    end
    local function clamp(v, low, high) return math.max(low, math.min(high, v)) end
    local function wrap(v) return (v + 180) % 360 - 180 end
    local function query(kind, hash, ...)
        local fn = d["invoke_" .. kind .. "_detail"]
        if type(fn) ~= "function" then return nil end
        local ok, value, raw, err = pcall(fn, hash, ...)
        if not ok or err ~= nil then return nil end
        if kind == "bool" then
            if raw == true or raw == 1 then return true end
            if raw == false or raw == 0 then return false end
            if type(value) == "boolean" then return value end
        elseif kind == "void" then
            return value ~= false
        elseif finite(value) then
            return value
        end
    end
    local function vec(hash, ...)
        if type(d.invoke_vec3) ~= "function" or type(d.vector_components) ~= "function" then return nil end
        local ok, value = pcall(d.invoke_vec3, hash, ...)
        if not ok or not value then return nil end
        local parsed, x, y, z = pcall(d.vector_components, value)
        if parsed and finite(x) and finite(y) and finite(z) then return { x = x, y = y, z = z } end
    end
    local function clear_target()
        state.target_pid = nil
        state.target_ped = nil
        state.error = nil
    end
    function api.Reset()
        clear_target()
        state.last_tick = nil
        state.shooter = nil
        state.self_id = nil
        state.radius_degrees = nil
        state.status = "OFF"
    end
    local function target_ped(pid, self_id, shooter)
        if pid == self_id or query("bool", H.ACTIVE, pid) ~= true then return nil end
        local ped = query("int", H.PED, pid)
        if not finite(ped) or ped <= 0 or ped == shooter
            or query("bool", H.EXISTS, ped) ~= true
            or query("bool", H.DEAD, ped, false) ~= false
            or query("bool", H.GHOST, ped) == true then return nil end
        return ped
    end
    local function bearing(cam, point, rot, radius)
        local x, y, z = point.x - cam.x, point.y - cam.y, point.z - cam.z
        local horizontal = math.sqrt(x * x + y * y)
        local distance = math.sqrt(horizontal * horizontal + z * z)
        if distance <= 0.5 or distance > 1000 then return nil end
        local yaw, pitch = math.rad(rot.z), math.rad(rot.x)
        local cp = math.cos(pitch)
        local dot = (-math.sin(yaw) * cp * x + math.cos(yaw) * cp * y + math.sin(pitch) * z) / distance
        local error = math.deg(math.acos(clamp(dot, -1, 1)))
        if error > radius then return nil end
        return error, wrap(math.deg(math.atan(-x, y)) - rot.z),
            math.deg(math.atan(z, math.max(0.0001, horizontal))) - rot.x
    end
    function api.Tick(now)
        if not enabled() or not finite(now) or query("bool", H.SESSION) ~= true then api.Reset(); return end
        local config = settings and settings() or {}
        local strength = finite(config.strength) and clamp(config.strength, 0, 100) or 35
        local radius_percent = finite(config.radius) and clamp(config.radius, 1, 30) or 10
        local self_id = d.local_player_id and d.local_player_id()
        local shooter = d.local_ped and d.local_ped()
        if strength <= 0 or not finite(self_id) or not finite(shooter) or shooter <= 0
            or query("bool", H.EXISTS, shooter) ~= true
            or query("bool", H.DEAD, shooter, false) ~= false
            or query("bool", H.IN_VEHICLE, shooter, false) ~= false
            or query("bool", H.CONTROL, 0, 25) ~= true
            or query("bool", H.PAUSED) ~= false
            or query("bool", H.CAM_RENDERING) ~= true
            or (query("bool", H.AIM, self_id) ~= true and query("bool", H.AIM_CAM) ~= true) then
            api.Reset(); return
        end
        if state.shooter ~= shooter or state.self_id ~= self_id then api.Reset() end
        state.shooter, state.self_id = shooter, self_id
        local previous = state.last_tick
        state.last_tick = now
        if previous and now == previous then return end
        state.status = "SEARCHING"
        -- A stall never becomes a catch-up turn; sample a fresh frame afterward.
        if previous and (now < previous or now - previous > 100) then
            clear_target(); state.status = "PAUSED"; return
        end
        local dt = query("float", H.FRAME_TIME)
        if not finite(dt) or dt <= 0 then dt = previous and (now - previous) / 1000 or 1 / 60 end
        dt = clamp(dt, 0.001, 0.05)
        local cam, rot = vec(H.CAM_COORD), vec(H.CAM_ROT, 2)
        local fov = query("float", H.CAM_FOV)
        if not cam or not rot or not finite(fov) or fov <= 0 or fov >= 180 then
            clear_target(); state.status = "NO_CAMERA"; return
        end
        local radius = math.deg(math.atan(math.tan(math.rad(fov) * 0.5) * radius_percent / 100))
        state.radius_degrees = radius
        local function candidate(pid, expected_ped)
            local ped = target_ped(pid, self_id, shooter)
            if not ped or (expected_ped and ped ~= expected_ped) then return nil end
            local point = vec(H.BONE, ped, 24816, 0.0, 0.0, 0.0)
            if not point then return nil end
            local error, dyaw, dpitch = bearing(cam, point, rot, radius)
            if not error then return nil end
            return { pid = pid, ped = ped, error = error, yaw = dyaw, pitch = dpitch }
        end
        local chosen
        if state.target_pid ~= nil then
            chosen = candidate(state.target_pid, state.target_ped)
            if chosen and query("bool", H.LOS, shooter, chosen.ped, 17) ~= true then chosen = nil end
        end
        if not chosen then
            clear_target()
            for pid = 0, 31 do
                local next_target = candidate(pid)
                if next_target and (not chosen or next_target.error < chosen.error)
                    and query("bool", H.LOS, shooter, next_target.ped, 17) == true then
                    chosen = next_target
                end
            end
        end
        if not chosen then return end
        state.target_pid, state.target_ped = chosen.pid, chosen.ped
        state.error, state.status = chosen.error, "TRACKING"
        local dyaw, dpitch = chosen.yaw, chosen.pitch
        if strength < 100 then
            local amount = strength / 100
            local rate = 0.75 + 40 * amount * amount
            local alpha = 1 - math.exp(-rate * dt)
            dyaw, dpitch = dyaw * alpha, dpitch * alpha
            local length = math.sqrt(dyaw * dyaw + dpitch * dpitch)
            local cap = (12 + 348 * amount * amount) * dt
            if length > cap then dyaw, dpitch = dyaw * cap / length, dpitch * cap / length end
        end
        if math.abs(dyaw) < 0.00001 and math.abs(dpitch) < 0.00001 then return end
        local heading = query("float", H.GET_REL_HEAD)
        local pitch = query("float", H.GET_REL_PITCH)
        if not finite(heading) or not finite(pitch) then
            state.status = "NO_CAMERA"; return
        end
        -- These are requests to the existing gameplay camera, not shot redirection.
        -- Exact response in first-person/scoped modes must be checked in-game.
        if math.abs(dyaw) >= 0.00001 then query("void", H.SET_REL_HEAD, wrap(heading + dyaw)) end
        if math.abs(dpitch) >= 0.00001 then
            query("void", H.SET_REL_PITCH, clamp(pitch + dpitch, -89, 89), 1.0)
        end
    end
    function api.Snapshot()
        return { status = state.status, target_pid = state.target_pid, target_ped = state.target_ped,
            radius_degrees = state.radius_degrees, error_degrees = state.error }
    end
    return api
end

-- BEGIN SHOOT_FRIENDLIES44
-- BEGIN SHOOT_FRIENDLIES_RECEIVERS45
-- Permission bits on this client's copies of same-vehicle player occupants.
-- Their owning clients still decide remote damage. No migration or shots.
local function new_friendlies_receivers45(d)
    local api = {}
    local s = {generation=0,epoch=0,records={},gates={},status="OFF",busy=false}
    local H = {SESSION=0x9DE624D2FC4B603F,TRANSITION=0x68049AEFF83D8F0A,
        EXISTS=0x7239B21A38F536BA,MODEL=0x9F47B058362C84B5,ACTIVE=0xB8DFD30D6973E135,
        DEAD=0x5F9532F3B5CC2551,PLAYER_PED=0x43A66C31C68491C0,IS_PLAYER=0x12534C348C6CB68B,PLAYER_INDEX=0x6C0E2E0125610278,
        VEHICLE=0x9A9112A0FE9A4713,SITTING=0xA808AA1D79230FC2,
        GET=0x7EE53118C892B513,SET=0x1913FE4CBF41C463}
    -- Primary ePedConfigFlags / SHVDN PedConfigFlagToggles: CanBeShotInVehicle,
    -- AllowToBeTargetedInAVehicle, and the synced/nonsynced friendly fire gates.
    local flags={{1,true},{214,true},{423,false},{425,false}}
    local function integer(v)return type(v)=="number"and v==v and math.abs(v)<math.huge and v%1==0 end
    local function read(fn,...)
        if type(fn)~="function"then return nil end
        local ok,value=pcall(fn,...);if ok then return value end
    end
    local function boolean(hash,...)
        if type(d.invoke_bool_detail)~="function"then return nil end
        local ok,value,raw,err=pcall(d.invoke_bool_detail,hash,...)
        if not ok or err~=nil or(raw~=true and raw~=false and raw~=0 and raw~=1)then return nil end
        local actual=raw==true or raw==1
        if type(value)=="boolean"and value==actual then return actual end
    end
    local function number(hash,...)
        if type(d.invoke_int_detail)~="function"then return nil end
        local ok,value,raw,err=pcall(d.invoke_int_detail,hash,...)
        if ok and err==nil and integer(value)and integer(raw)and value==raw then return value end
    end
    local function dispatch(record,id,value)
        record.inflight=true
        local ok,accepted,raw,err=pcall(d.invoke_void_detail,H.SET,record.ped,id,value)
        record.inflight=false
        return ok and accepted==true and raw~=false and err==nil
    end
    local function physical(handle)
        if not integer(handle)or handle<=0 then return nil,"unknown"end
        local exists=boolean(H.EXISTS,handle)
        if exists==false then return nil,"retired"end
        if exists~=true then return nil,"unknown"end
        local result=read(function()
            local pointer=d.GTA and d.GTA.HandleToPointer(handle)
            if not pointer then return nil end
            local address=pointer:GetAddress()
            local model=pointer.ModelInfo and pointer.ModelInfo.Model
            local network=pointer.NetObject and pointer.NetObject.ObjectID
            local native=number(H.MODEL,handle)
            if not integer(address)or address<=0 or not integer(model)or not integer(native)
                or(model&0xffffffff)~=(native&0xffffffff)or not integer(network)or network<=0 then return nil end
            local again=d.GTA.HandleToPointer(handle)
            if not again or again:GetAddress()~=address or not again.NetObject or again.NetObject.ObjectID~=network
                or not again.ModelInfo or(again.ModelInfo.Model&0xffffffff)~=(model&0xffffffff)then return nil end
            return{ped=handle,address=address,model=model&0xffffffff,network=network,pointer=again}
        end)
        return result,result and "current"or "unknown"
    end
    local function same_physical(a,b)
        return a and b and a.ped==b.ped and a.address==b.address and a.model==b.model and a.network==b.network
    end
    local function player(ped,pid)
        if not integer(pid)or pid<0 or pid>31 then return nil,"unknown"end
        local proof,reason=physical(ped);if not proof then return nil,reason end
        local active=boolean(H.ACTIVE,pid)
        if active==false then return nil,"retired"end
        if active~=true or boolean(H.IS_PLAYER,ped)~=true then return nil,"unknown"end
        local native_ped=number(H.PLAYER_PED,pid)
        if native_ped and native_ped>0 and native_ped~=ped then return nil,"retired"end
        if native_ped~=ped then return nil,"unknown"end
        local identity=read(function()
            local p=d.Players and d.Players.GetById(pid)
            if not p then return nil end
            local address,connection=p:GetAddress(),p.CxnId
            if not integer(address)or address<=0 or not integer(connection)or connection<0 then return nil end
            local again=d.Players.GetById(pid)
            if not again or again:GetAddress()~=address or again.CxnId~=connection then return nil end
            return{address=address,connection=connection}
        end)
        if not identity then return nil,"unknown"end
        local final=physical(ped)
        if not same_physical(proof,final)or number(H.PLAYER_PED,pid)~=ped then return nil,"unknown"end
        local closed=read(function()
            local p=d.Players.GetById(pid)
            return p and p:GetAddress()==identity.address and p.CxnId==identity.connection
        end)
        if closed~=true then return nil,"unknown"end
        proof.pid,proof.player,proof.connection=pid,identity.address,identity.connection
        return proof,"current"
    end
    local function same_player(a,b)
        return same_physical(a,b)and a.pid==b.pid and a.player==b.player and a.connection==b.connection
    end
    local function owned(record)
        for _,entry in pairs(record.entries)do if entry.owned then return true end end
        return record.inflight==true
    end
    local function pure(record,token)
        return s.records[record.pid]==record and s.generation==token and record.epoch==s.epoch
    end
    local function current(record,token)
        if not pure(record,token)then return false,"changed"end
        if boolean(H.SESSION)==false then return false,"retired"end
        if boolean(H.SESSION)~=true or boolean(H.TRANSITION)~=false then return false,"unknown"end
        local proof,reason=player(record.ped,record.pid)
        if proof and not same_player(record,proof)then return false,"retired"end
        return proof~=nil and pure(record,token),proof and "current"or reason
    end
    local function restore_one(record,token)
        if record.inflight then return false end
        local valid,reason=current(record,token)
        if not valid then return reason=="retired"end
        for _,flag in ipairs(flags)do
            local id=flag[1];local entry=record.entries[id]
            if entry and entry.owned then
                local value=boolean(H.GET,record.ped,id,true)
                if not pure(record,token)then return false end
                if value~=nil and value~=entry.last then entry.owned=false
                elseif value==entry.last and current(record,token)then
                    local again=boolean(H.GET,record.ped,id,true)
                    if again~=nil and again~=entry.last then entry.owned=false
                    elseif again==entry.last and current(record,token)then
                        dispatch(record,id,entry.original)
                        if not pure(record,token)then return false end
                        local after=boolean(H.GET,record.ped,id,true)
                        if pure(record,token)and current(record,token)and after==entry.original then entry.owned=false end
                    end
                end
            end
            if not pure(record,token)then return false end
        end
        return not owned(record)
    end
    local function restore_inactive()
        local token=s.generation;local clean=true
        for pid,record in pairs(s.records)do
            if not record.active then
                if not owned(record)or restore_one(record,token)then
                    if pure(record,token)then s.records[pid]=nil end
                else clean=false end
            end
            if s.generation~=token then return false end
        end
        return clean
    end
    function api.Pending()
        if s.busy then return true end
        for _,record in pairs(s.records)do if owned(record)then return true end end
        return false
    end
    function api.RestoreRequested()
        for _,record in pairs(s.records)do if not record.active and owned(record)then return true end end
        return false
    end
    function api.Retire()
        s.generation=s.generation+1;s.gates={}
        for _,record in pairs(s.records)do record.active=false end
        s.status=api.Pending()and "RESTORE_PENDING"or "OFF"
    end
    function api.Restore()
        if s.busy then return false end
        s.busy=true;local ok,clean=pcall(restore_inactive);s.busy=false
        if not ok or not clean then s.status="RESTORE_PENDING"
        else
            local active=false;for _,record in pairs(s.records)do if record.active then active=true;break end end
            s.status=active and "CHECKING"or "OFF"
        end
        return ok and clean
    end
    function api.OnSessionChange()
        s.epoch=s.epoch+1;s.generation=s.generation+1;s.records={};s.gates={};s.status="SESSION"
    end
    local function scope(record,vehicle,local_ped,token,admitted)
        if read(admitted)~=true or not current(record,token)or boolean(H.DEAD,record.ped,false)~=false then return false end
        local now=physical(vehicle.ped)
        if not same_physical(vehicle,now)then return false end
        if boolean(H.SITTING,local_ped,vehicle.ped)~=true or boolean(H.SITTING,record.ped,vehicle.ped)~=true then return false end
        return read(admitted)==true and current(record,token)
            and same_physical(vehicle,physical(vehicle.ped))
    end
    local function tick(local_record,admitted,pure_intent)
        local intent=type(pure_intent)=="function"and pure_intent or admitted
        local token=s.generation;s.gates={};s.status="CHECKING"
        for _,record in pairs(s.records)do record.active=false end
        if read(admitted)~=true then s.status=restore_inactive()and "PAUSED"or "RESTORE_PENDING";return end
        local vehicle_handle=number(H.VEHICLE,local_record.ped,false)
        if vehicle_handle==0 then s.status=restore_inactive()and "NO_VEHICLE"or "RESTORE_PENDING";return end
        local vehicle=vehicle_handle and physical(vehicle_handle)
        if not vehicle or boolean(H.SITTING,local_record.ped,vehicle.ped)~=true then
            s.status=restore_inactive()and "READ_UNAVAILABLE"or "RESTORE_PENDING";return
        end
        local candidates={}
        -- Player indices have a documented 0..31 domain in this host. Enumerate
        -- those read-only, then require actual seating in this exact vehicle.
        -- Do not assume Cherax wrapper seat indices or invoke the native seat
        -- getter, which can create an ambient occupant in an empty seat.
        for pid=0,31 do
            if read(intent)~=true or s.generation~=token then return end
            if pid~=local_record.pid then
                local active=boolean(H.ACTIVE,pid)
                if active==nil then s.gates["pid_"..pid.."_active"]="READ_UNAVAILABLE"
                elseif active then
                    local ped=number(H.PLAYER_PED,pid)
                    if not integer(ped)or ped<0 then s.gates["pid_"..pid.."_identity"]="READ_UNAVAILABLE"
                    elseif ped>0 and ped~=local_record.ped then
                        local sitting=boolean(H.SITTING,ped,vehicle.ped)
                        if sitting==nil then s.gates["pid_"..pid.."_scope"]="READ_UNAVAILABLE"
                        elseif sitting then
                            local candidate=player(ped,pid)
                            if candidate then candidates[#candidates+1]=candidate
                            else s.gates["pid_"..pid.."_identity"]="READ_UNAVAILABLE"end
                        end
                    end
                    -- A positively absent local ped (0) has no clone flags to
                    -- change. Unknown/native-error results remain explicit.
                end
            end
        end
        for _,candidate in ipairs(candidates)do
            local record=s.records[candidate.pid]
            if record and not same_player(record,candidate)then
                if restore_one(record,token)and pure(record,token)then s.records[candidate.pid]=nil;record=nil
                else s.gates["pid_"..candidate.pid.."_restore"]="RESTORE_PENDING"end
            end
            if not record then
                record=candidate;record.entries={};record.epoch=s.epoch;s.records[record.pid]=record
            end
            if same_player(record,candidate)then record.active=true end
        end
        if not restore_inactive()then s.gates.restore="RESTORE_PENDING"end
        for _,candidate in ipairs(candidates)do
            local record=s.records[candidate.pid]
            if record and record.active and same_player(record,candidate)then
                local admitted_scope=scope(record,vehicle,local_record.ped,token,intent)
                for _,flag in ipairs(flags)do
                    local id,value=flag[1],flag[2];local key="pid_"..record.pid.."_flag_"..id
                    local result="READ_UNAVAILABLE"
                    if not admitted_scope then s.gates[key]="SCOPE_CHANGED";break end
                    local observed=boolean(H.GET,record.ped,id,true);local entry=record.entries[id]
                    if observed~=nil then
                        result=observed==value and "READY"or "STILL_BLOCKED"
                        if entry and entry.owned and observed~=entry.last then entry.owned=false end
                        if observed~=value and scope(record,vehicle,local_record.ped,token,admitted)then
                            local again=boolean(H.GET,record.ped,id,true)
                            if again==observed and scope(record,vehicle,local_record.ped,token,admitted)then
                                entry={original=observed,last=value,owned=true};record.entries[id]=entry
                                local accepted=dispatch(record,id,value)
                                if not pure(record,token)then return end
                                local after=boolean(H.GET,record.ped,id,true)
                                if current(record,token)and after==observed then entry.owned=false end
                                result=not accepted and "DISPATCH_FAILED"or after==nil and "READ_UNAVAILABLE"
                                    or after==value and "READY"or "STILL_BLOCKED"
                            end
                        end
                    end
                    s.gates[key]=result
                    if read(intent)~=true or not pure(record,token)then return end
                end
                for _,flag in ipairs(flags)do
                    if not pure(record,token)or read(intent)~=true then return end
                    local key="pid_"..record.pid.."_flag_"..flag[1]
                    local actual=boolean(H.GET,record.ped,flag[1],true)
                    if not pure(record,token)or read(intent)~=true then return end
                    if actual==nil then s.gates[key]="READ_UNAVAILABLE"
                    elseif actual~=flag[2]then s.gates[key]="STILL_BLOCKED"end
                end
                if not scope(record,vehicle,local_record.ped,token,intent)then
                    record.active=false;s.gates["pid_"..record.pid.."_scope"]="SCOPE_CHANGED"
                end
            end
        end
        if s.generation~=token then return end
        if not restore_inactive()then s.gates.restore="RESTORE_PENDING"end
        s.status=#candidates==0 and "NO_OCCUPANTS"or "READY"
        for _,result in pairs(s.gates)do if result~="READY"then s.status="PARTIAL";break end end
    end
    function api.Tick(local_record,admitted,pure_intent)
        if s.busy then return false end
        s.busy=true;local ok=pcall(tick,local_record,admitted,pure_intent);s.busy=false
        if not ok then api.Retire();api.Restore();s.status="READ_UNAVAILABLE"end
        return ok and(s.status=="READY"or s.status=="NO_VEHICLE"or s.status=="NO_OCCUPANTS")
    end
    function api.Snapshot()
        local gates,count,owned_count={},0,0
        for key,value in pairs(s.gates)do gates[key]=value end
        for _,record in pairs(s.records)do
            count=count+1
            for _,entry in pairs(record.entries)do if entry.owned then owned_count=owned_count+1 end end
        end
        return{status=s.status,occupants=count,owned_flags=owned_count,gates=gates,
            restore_pending=api.RestoreRequested(),local_permission_only=true,shot_verified=false,remote_damage_verified=false}
    end
    return api
end
-- END SHOOT_FRIENDLIES_RECEIVERS45

-- Local firing permissions only. Persistent ped flags use readable leases;
-- attack inputs, reset flags and the firing override expire each frame.
local function new_shoot_friendlies(d)
    local api = {}
    local Receivers = new_friendlies_receivers45(d)
    local s = { generation=0, epoch=0, intent=false, retiring=false, status="OFF" }
    local H = {
        SESSION=0x9DE624D2FC4B603F, TRANSITION=0x68049AEFF83D8F0A,
        EXISTS=0x7239B21A38F536BA, MODEL=0x9F47B058362C84B5,
        DEAD=0x5F9532F3B5CC2551, CONTROL=0x01BF60A500E28887,
        ACTIVE=0xB8DFD30D6973E135, INPUT=0x49C32D60007AFA47,
        PAUSE=0xB0034A223497FFCB, CHAT=0xB118AF58B5F332A1,
        WARNING=0xE18B138FABC53103, CUTSCENE=0x991251AFC3981F84,
        SWITCH=0xD9D2CFFF49FAB35F, GET_FLAG=0x7EE53118C892B513,
        SET_FLAG=0x1913FE4CBF41C463, FRIENDLY=0xB3B1CB349FF9C75D,
        GET_RESET=0xAF9E59B1B1FBF2A0, SET_RESET=0xC1E8A365BF3B29F2,
