    -- CanAttackFriendly and the input controls. It is a frame flag, not a
    -- persistent config flag; never restore an earlier frame's block.
    local BLOCK_WEAPON_FIRE=128
    local function finite(v)return type(v)=="number" and v==v and math.abs(v)<math.huge end
    local function integer(v)return finite(v) and v%1==0 end
    local function wanted()return type(d.enabled)=="function" and d.enabled()==true end
    local function boolean(h,...)
        if type(d.invoke_bool_detail)~="function"then return nil end
        local ok,value,raw,err=pcall(d.invoke_bool_detail,h,...)
        if not ok or err~=nil or(type(raw)~="boolean" and raw~=0 and raw~=1)then return nil end
