        if type(value)=="boolean" and value==actual then return actual end
    end
    local function number(h,...)
        if type(d.invoke_int_detail)~="function"then return nil end
        local ok,value,raw,err=pcall(d.invoke_int_detail,h,...)
        if ok and err==nil and integer(value) and integer(raw)then return value end
    end
    local function dispatch(h,...)
        if type(d.invoke_void_detail)~="function"then return false end
        local ok,value,raw,err=pcall(d.invoke_void_detail,h,...)
        return ok and value==true and raw~=false and err==nil
    end
    local function same(a,b)
        return a and b and a.epoch==b.epoch and a.pid==b.pid and a.ped==b.ped
            and a.player==b.player and a.connection==b.connection and a.address==b.address
            and a.model==b.model and a.network==b.network
    end
    local function probe()
        local session,transition=boolean(H.SESSION),boolean(H.TRANSITION)
        if session==false or transition==true then return nil,"retired" end
        if session~=true or transition~=false then return nil,"unknown" end
        local ok,identity=pcall(function()
            local pid,ped=d.local_player_id(),d.local_ped()
            if not integer(pid)or pid<0 or pid>31 or not integer(ped)or ped<=0 then return nil end
            if boolean(H.EXISTS,ped)~=true then return nil end
            local player=d.Players and d.Players.GetById(pid)
            local entity=d.GTA and d.GTA.HandleToPointer(ped)
            if not player or player:IsLocalPlayer()~=true or not entity then return nil end
            local address,connection,player_address=entity:GetAddress(),player.CxnId,player:GetAddress()
            local model=entity.ModelInfo and entity.ModelInfo.Model
            local network=entity.NetObject and entity.NetObject.ObjectID
            local native_model=number(H.MODEL,ped)
