        if type(d.input_blocked)=="function"and d.input_blocked()~=false then return false end
        if boolean(H.PAUSE)~=false or boolean(H.CHAT)~=false or boolean(H.WARNING)~=false
            or boolean(H.CUTSCENE)~=false or boolean(H.SWITCH)~=false
            or boolean(H.ACTIVE,record.pid)~=true or boolean(H.INPUT,record.pid)~=true
            or boolean(H.DEAD,record.ped,false)~=false then return false end
