    local function write_flag(record,id,value)
        -- The third argument must remain false; true has a separate persistent
        -- targeting side effect in the supplied native definition.
        if id==140 then return dispatch(H.FRIENDLY,record.ped,value,false)end
        return dispatch(H.SET_FLAG,record.ped,id,value)
