        return local_clean and recipients_clean
    end
    local function retire(reason)
        Receivers.Retire()
        s.generation=s.generation+1;s.retiring=s.lease~=nil or Receivers.Pending();s.status=reason or "OFF";s.gates=nil
    end
    function api.IntentChanged(value)
        value=value==true
        if s.intent==value then return end
        s.intent=value;retire(value and "READY"or "OFF")
    end
    function api.Reset(reason)
        retire(reason);return restore()
    end
    function api.OnSessionChange()
        -- Positive lifecycle retirement never writes through a former epoch.
        Receivers.OnSessionChange()
