        if not enabled and(s.lease or Receivers.Pending())and not s.retiring then retire("OFF")end
        if s.retiring and not restore()then return end
        if not enabled then return end
        local identity,reason=probe()
        if not identity then
            if reason=="retired"then api.OnSessionChange()
