        local function gate(key,value)
            if pure(record,token)then gates[key]=value end
        end
        for _,flag in ipairs(flags)do
            local id,value=flag[1],flag[2]
            local observed=boolean(H.GET_FLAG,record.ped,id,true)
            local entry=record.entries[id]
            local result="READ_UNAVAILABLE"
            if observed~=nil then
                result=observed==value and "READY"or "STILL_BLOCKED"
                if entry and entry.owned and observed~=entry.last then
                    -- Remember the latest external preference before applying
                    -- this enabled feature again; restore that value on exit.
                    entry.owned=false
                end
                if observed~=value and input_scope(record,token)then
                    local again=boolean(H.GET_FLAG,record.ped,id,true)
                    if again==observed and input_scope(record,token)then
                        entry={original=observed,last=value,owned=true};record.entries[id]=entry
                        local accepted=write_flag(record,id,value)
                        local actual=boolean(H.GET_FLAG,record.ped,id,true)
                        if pure(record,token)and current(record,token)and actual==observed then entry.owned=false end
                        if not accepted then result="DISPATCH_FAILED"
                        elseif actual==nil then result="READ_UNAVAILABLE"
                        elseif actual==value then result="READY"
                        else result="STILL_BLOCKED"end
                    end
                end
            end
            gate("flag_"..id,result)
            if not pure(record,token)or not wanted()or s.retiring then return end
        end
        if not input_scope(record,token)then return end
        local recipients_ready=Receivers.Tick(record,function()return input_scope(record,token)end,
            function()return wanted()and pure(record,token)and not s.retiring end)
        if not input_scope(record,token)then
            if pure(record,token)then retire("PAUSED");restore()end
            return
        end
        local blocked=boolean(H.GET_RESET,record.ped,BLOCK_WEAPON_FIRE)
        local block_result=blocked==false and "READY"or "READ_UNAVAILABLE"
        if blocked==true then
            block_result="STILL_BLOCKED"
            if not input_scope(record,token)then return end
            local again=boolean(H.GET_RESET,record.ped,BLOCK_WEAPON_FIRE)
            if again==true and input_scope(record,token)then
                local accepted=dispatch(H.SET_RESET,record.ped,BLOCK_WEAPON_FIRE,false)
                local actual=boolean(H.GET_RESET,record.ped,BLOCK_WEAPON_FIRE)
                if not accepted then block_result="DISPATCH_FAILED"
                elseif actual==nil then block_result="READ_UNAVAILABLE"
                elseif actual==false then block_result="READY"
                else block_result="STILL_BLOCKED"end
            elseif again==false then block_result="READY"
            elseif again==nil then block_result="READ_UNAVAILABLE"end
        end
        gate("block_weapon_fire",block_result)
        if not input_scope(record,token)then return end
        gate("firing_override",dispatch(H.FIRING,record.pid,false)and "DISPATCHED"or "DISPATCH_FAILED")
        for _,control in ipairs(controls)do
            if not pure(record,token)or not wanted()or s.retiring then return end
            local enabled_control=boolean(H.CONTROL_ENABLED,0,control)
            local result=enabled_control==true and "READY"or "READ_UNAVAILABLE"
            if enabled_control==false then
                if not input_scope(record,token)then return end
                result=dispatch(H.ENABLE,0,control,true)and "DISPATCHED"or "DISPATCH_FAILED"
            end
            gate("control_"..control,result)
        end
        if pure(record,token)then
            -- The last dispatch can run a host callback too. Do not carry an
            -- admitted status or owned permissions into a new input owner.
            if not input_scope(record,token)then
                if pure(record,token)then retire("PAUSED");restore()end
                return
            end
            s.status=recipients_ready and "ON"or "PARTIAL"
            for _,result in pairs(gates)do
                if result~="READY"and result~="DISPATCHED"then s.status="PARTIAL";break end
            end
        end
    end
    function api.Tick()
        local ok=pcall(tick)
        if not ok then retire("READ_UNAVAILABLE")end
    end
    return api
end
