    local function finite(v) return type(v)=="number" and v==v and math.abs(v)<math.huge end
    local function clamp(v,lo,hi) return math.max(lo,math.min(hi,v)) end
    local function enabled() return type(d.enabled)=="function" and d.enabled()==true end
    local function current_player_id()
        if type(d.local_player_id)~="function"then return nil end
        local ok,a,b=pcall(function()return d.local_player_id(),d.local_player_id()end)
        if ok and finite(a)and a%1==0 and a>=0 and a<=31 and b==a then return a end
    end
    local function boolean(h,...)
        if type(d.invoke_bool_detail)~="function" then return nil end
        local ok,value,raw,err=pcall(d.invoke_bool_detail,h,...)
        if ok and err==nil and (type(raw)=="boolean" or raw==0 or raw==1) then return value==true end
    end
    local function vector(h,...)
        if type(d.invoke_vec3)~="function" or type(d.vector_components)~="function" then return nil end
        local ok,result=pcall(d.invoke_vec3,h,...)
        if not ok or result==nil then return nil end
        local good,x,y,z=pcall(d.vector_components,result)
        if good and finite(x) and finite(y) and finite(z)
            and math.abs(x)<=3.4028234663852886e38 and math.abs(y)<=3.4028234663852886e38
            and math.abs(z)<=3.4028234663852886e38 then return {x=x,y=y,z=z} end
    end
    local function dispatch(h,...)
        if type(d.invoke_void_detail)~="function" then return false end
        local ok,value,raw,err=pcall(d.invoke_void_detail,h,...)
        return ok and value==true and raw~=false and err==nil
    end
    local function feature()
        local manager=d.feature_manager
        local access=type(d.foreign)=="function" and d.foreign() or nil
        if not manager or type(manager.GetFeature)~="function" or not access then return nil end
        local ok,f=pcall(manager.GetFeature,2688656509)
        if not ok or not f then return nil end
        -- GetType must precede EVERY typed foreign access. Method presence alone
        -- is insufficient for host userdata and can cause native fail-fast.
        local good,result,id=pcall(function()
            if access.Supports(f,"toggle")~=true then return false end
            local name=f:GetName(false)
            name=type(name)=="string" and name:lower():gsub("~[^~]*~",""):gsub("[^%w]+"," ") or ""
            name=name:gsub("^%s+",""):gsub("%s+$","")
            local hash=f:GetHash()
            return finite(hash) and hash%1==0 and hash%4294967296==2688656509
                and name=="gravity gun" and f:IsPlayerFeature()==false
                and type(f.Toggle)=="function" and type(f.TriggerCallback)=="function",f:GetId()
        end)
        if good and result==true and finite(id) then return f,id end
    end
    local function toggled(f)
        local ok,value=pcall(function()return f:IsToggled()end)
        if ok and type(value)=="boolean" then return value end
    end
    local function callback(f)
        local ok,value=pcall(function()return f:TriggerCallback()end)
        return ok and value~=false
    end
    local function write_checkbox(lease,f,wanted)
        -- Keep the last OBSERVED value, not the intended value. Toggle can throw
        -- before or after mutation; unresolved readback retains both candidates.
        lease.attempt={before=lease.last_write,target=wanted}
        lease.busy=true
        local ok,result=pcall(function()return f:Toggle(wanted)end)
        local observed=toggled(f)
        lease.busy=false
        if observed~=nil then
            lease.last_write=observed
            lease.attempt=nil
        end
        return ok and result~=false and observed==wanted
    end
    local function refresh_attempt(lease,current)
        if lease.attempt and (current==lease.attempt.before or current==lease.attempt.target) then
            lease.last_write=current;lease.attempt=nil
        end
    end
    local function drop()
        s.held,s.pending,s.previous_time,s.scan=nil,nil,nil,nil
        if s.ray then s.ray.discard=true end
        s.generation=s.generation+1
        s.released=true
    end
    local function restore(now,force)
        local lease=s.lease
        if not lease then return true end
        if lease.busy then s.status="RESTORE_PENDING";return false end
        if not lease.owned then s.lease=nil;return true end
        if not force and now<s.next_restore then return false end
        s.next_restore=now+250
        local f,id=feature()
        if not f then s.status="RESTORE_PENDING";return false end
        local current=toggled(f)
        if current==nil then s.status="RESTORE_PENDING";return false end
        refresh_attempt(lease,current)
        if id~=lease.id or current~=lease.last_write then
            -- A changed feature or externally changed value ends our ownership.
            s.lease=nil;s.status="EXTERNAL_CHANGE";return true
        end
        lease.restoring=true
        if current~=lease.original then
            if not write_checkbox(lease,f,lease.original) then s.status="RESTORE_PENDING";return false end
        end
        lease.busy=true
        local accepted=callback(f)
        local observed=toggled(f)
        lease.busy=false
        if not accepted or observed~=lease.original then s.status="RESTORE_PENDING";return false end
        s.lease=nil
        return true
    end
    local function builtin(now)
        if s.yielded then s.status="CHERAX_ACTIVE";return false end
        if s.lease and (s.lease.restoring or s.lease.busy) then return false end
        local f,id=feature()
        if not f then
            -- Cherax is an optional coexistence provider. Existing ownership must
            -- remain retryable if its provider temporarily disappears.
            if s.lease and s.lease.owned then s.status="HOST_UNAVAILABLE";return false end
            s.lease=nil
            return true
        end
        local current=toggled(f)
        if current==nil then s.status="UNAVAILABLE";return false end
        local lease=s.lease
        if lease then
            refresh_attempt(lease,current)
            if id~=lease.id or (lease.paused and current~=false) then
                s.lease=nil;s.yielded=true;drop();s.status="CHERAX_ACTIVE";return false
            end
            if lease.paused then return true end
            if current~=lease.last_write then s.yielded=true;s.lease=nil;drop();return false end
            if now<(lease.retry_at or 0) then return false end
        else
            if current and (s.held or s.pending) then
                s.yielded=true;drop();s.status="CHERAX_ACTIVE";return false
            end
            lease={id=id,original=current,last_write=current,owned=current==true,paused=current==false}
            s.lease=lease
            if not current then return true end
        end
        lease.retry_at=now+250
        if current~=false and not write_checkbox(lease,f,false) then s.status="PAUSE_PENDING";return false end
        if s.resetting or not enabled() then return false end
        lease.busy=true
        local accepted=callback(f)
        local observed=toggled(f)
        lease.busy=false
        if not accepted or observed~=false then s.status="PAUSE_PENDING";return false end
        if s.resetting or not enabled() then return false end
        lease.paused=true
        return true
    end
    local function integer(h,...)
        if type(d.invoke_int_detail)~="function" then return nil end
        local ok,value,raw,err=pcall(d.invoke_int_detail,h,...)
        if ok and err==nil and finite(value) and value%1==0 and finite(raw) then return value end
    end
    local function physical(handle)
        if not finite(handle) or handle<=0 or boolean(H.EXISTS,handle)~=true then return nil end
        local ok,result=pcall(function()
            local object=d.GTA and d.GTA.HandleToPointer(handle)
            if not object then return nil end
            local address,model=object:GetAddress(),object.ModelInfo and object.ModelInfo.Model
            local net=object.NetObject
            local network=net and net.ObjectID or nil
            if not finite(address) or address<=0 or not finite(model) or (net and not finite(network)) then return nil end
            return {handle=handle,address=address,model=model,network=network}
        end)
        return ok and result or nil
    end
    local function matches(record)
        if not record then return false end
        local fresh=physical(record.handle)
        return fresh~=nil and fresh.address==record.address and fresh.model==record.model and fresh.network==record.network
    end
    local function classify(handle)
        local record=physical(handle)
        if not record then return nil end
        if boolean(H.CAR,handle)==true then record.vehicle=true
        elseif boolean(H.OBJECT,handle)==true then record.object=true
        elseif boolean(H.PED,handle)==true then
            if handle==d.local_ped() then return nil end
            local seated=boolean(H.IN_VEHICLE,handle,false)
            if seated==true then
                local vehicle=integer(0x9A9112A0FE9A4713,handle,false)
                if not matches(record) then return nil end
                record=physical(vehicle)
                if not record or boolean(H.CAR,vehicle)~=true then return nil end
                record.vehicle=true
            elseif seated==false then record.ped=true
            else return nil end
        else return nil end
        if record.vehicle then
            local occupied=integer(0x9A9112A0FE9A4713,d.local_ped(),false)
            if occupied==nil or occupied==record.handle then return nil end
        end
        return record
    end
    local function physical_aim_down()
        local aim=d.controls and d.controls.aim
        if not finite(aim)then return nil end
        local normal,disabled=boolean(H.PRESSED,0,aim),boolean(H.DISABLED,0,aim)
        if normal==true or disabled==true then return true end
        if normal==false and disabled==false then return false end
    end
    local function input_scope(pid,allow_held_input)
        local function menu_closed()
            if d.GUI and type(d.GUI.IsOpen)=="function"then
                local ok,open=pcall(d.GUI.IsOpen)
                if not ok or open~=false then s.blocked="MENU_OPEN";return false end
            end
            return true
        end
        if not menu_closed()or boolean(H.PAUSE)~=false then return false end
        local input=boolean(H.INPUT,pid)
        if input~=true then
            if input~=false or allow_held_input~=true or not s.held
                or physical_aim_down()~=true or boolean(H.CUTSCENE)~=false
                or boolean(H.SWITCH)~=false or physical_aim_down()~=true then return false end
        end
        -- Input/scene reads can reenter UI state. This is a scope-only check;
        -- the caller finishes captured actor/local physical proof afterward.
        return menu_closed()
    end
    local function local_ready(allow_held_input)
        s.blocked=nil
        if d.GUI and type(d.GUI.IsOpen)=="function" then
            local ok,open=pcall(d.GUI.IsOpen)
            if not ok or open~=false then s.blocked="MENU_OPEN";return nil end
        end
        if boolean(H.SESSION)~=true or boolean(H.TRANSITION)~=false or boolean(H.PAUSE)~=false then
            s.blocked="SESSION_OR_PAUSE";return nil
        end
        local pid=current_player_id()
        local ped=type(d.local_ped)=="function" and d.local_ped() or nil
        if not finite(pid) or not finite(ped) or boolean(H.DEAD,ped,false)~=false then
            s.blocked="PLAYER_NOT_READY";return nil
        end
        local input=boolean(H.INPUT,pid)
        local held_input=input==false and allow_held_input==true and s.held~=nil
            and physical_aim_down()==true
            and boolean(H.CUTSCENE)==false and boolean(H.SWITCH)==false
        if input~=true and not held_input then s.blocked="PLAYER_NOT_READY";return nil end
        if not input_scope(pid,allow_held_input)then s.blocked=s.blocked or "PLAYER_NOT_READY";return nil end
        local player=physical(ped)
        -- Noclip may suppress normal movement input. Only an already held
        -- identity and two fresh positive physical RMB observations permit it.
        if player and held_input and(physical_aim_down()~=true
            or boolean(H.CUTSCENE)~=false or boolean(H.SWITCH)~=false)then
            s.blocked="PLAYER_NOT_READY";return nil
        end
        if not player then s.blocked="PLAYER_IDENTITY_UNAVAILABLE" end
        if player and current_player_id()~=pid then s.blocked="PLAYER_IDENTITY_UNAVAILABLE";return nil end
        if player then player.pid=pid end
        return player
    end
    local function weapon_target()
        local memory=d.Memory
        if not memory or type(memory.Alloc)~="function" or type(memory.Free)~="function"
            or type(memory.WriteInt)~="function" or type(memory.ReadInt)~="function" then return nil end
        local good,ptr=pcall(memory.Alloc,8)
        if not good or not finite(ptr) or ptr<=0 then return nil end
        local ok,handle=pcall(function()
            memory.WriteInt(ptr,0)
            if boolean(H.TARGET,d.local_player_id(),ptr)~=true then return nil end
            return memory.ReadInt(ptr)
        end)
        pcall(memory.Free,ptr)
        if not ok then return nil end
        return classify(handle)
    end
    local function pressed(control,edge)
        return boolean(edge and H.JUST or H.PRESSED,0,control)==true
            or boolean(edge and H.DJUST or H.DISABLED,0,control)==true
    end
    local function aiming(pid)
        local aim=d.controls and d.controls.aim
        if finite(aim)then return physical_aim_down()end
        return boolean(H.AIM,pid)
    end
    local function held_aim_state(pid)
        local logical=aiming(pid)
        if logical~=false then return logical end
        local keys=d.Utils
        if not keys or type(keys.IsKeyDown)~="function"then return logical end
        -- Windows VK_RBUTTON. A positive/unknown hardware state can retain
        -- metadata through a logical-control reset, but never grants movement.
        local ok,down=pcall(keys.IsKeyDown,0x02)
        if ok and down==false then return false end
        return nil
    end
    local function poll_ray(capture)
        local ray=s.ray
        if not ray then return true end
        local memory=d.Memory
        local allocated,ptr=pcall(memory.Alloc,64)
        if not allocated or not finite(ptr) or ptr<=0 then return false end
        local ok,state,hit,handle=pcall(function()
            local result=integer(H.RESULT,ray.handle,ptr,ptr+8,ptr+32,ptr+56)
            if result~=2 or not capture or ray.discard or ray.generation~=s.generation then return result end
            return result,memory.ReadInt(ptr),memory.ReadInt(ptr+56)
        end)
        pcall(memory.Free,ptr)
        if ok and (state==0 or state==2) then
            if s.ray==ray then s.ray=nil end
            return true,hit,handle
        end
        return false
    end
    local function acquisition_current(acquisition,player)
        if not acquisition then return true end
        if acquisition.remote_current then
            local good,current=pcall(acquisition.remote_current)
            if not good or current~=true then return false end
        end
        local owner=acquisition.player
        if acquisition.generation~=s.generation or not matches(owner) or owner.pid~=player.pid
            or owner.handle~=player.handle or owner.address~=player.address
            or owner.model~=player.model or owner.network~=player.network then return false end
        local camera,rotation=vector(H.CAMERA),vector(H.CAMROT,2)
        if not camera or not rotation then return false end
        local pitch,yaw=math.rad(rotation.x),math.rad(rotation.z)
        local direction={x=-math.sin(yaw)*math.cos(pitch),y=math.cos(yaw)*math.cos(pitch),z=math.sin(pitch)}
        local prior=acquisition.direction
        return direction.x*prior.x+direction.y*prior.y+direction.z*prior.z>=0.996
            and (camera.x-acquisition.camera.x)^2+(camera.y-acquisition.camera.y)^2+(camera.z-acquisition.camera.z)^2<=4
    end
    local function model_radius(model)
        s.bounds=s.bounds or {};local cached=s.bounds[model]
        if cached then return cached end
        local memory=d.Memory
        if not memory or type(memory.ReadV3)~="function" then return nil end
        local ok,ptr=pcall(memory.Alloc,48)
        if not ok or not finite(ptr) or ptr<=0 then return nil end
        local read,radius=pcall(function()
            if not dispatch(H.DIMENSIONS,model,ptr,ptr+24) then return nil end
            local a,b=memory.ReadV3(ptr),memory.ReadV3(ptr+24)
            local ax,ay,az=d.vector_components(a);local bx,by,bz=d.vector_components(b)
            if not(finite(ax) and finite(ay) and finite(az) and finite(bx) and finite(by) and finite(bz)) then return nil end
            local x,y,z=math.max(math.abs(ax),math.abs(bx)),math.max(math.abs(ay),math.abs(by)),math.max(math.abs(az),math.abs(bz))
            local r=math.sqrt(x*x+y*y+z*z)
            return finite(r) and r>0 and r or nil
        end)
        pcall(memory.Free,ptr)
        if read and radius then
            if (s.bounds_count or 0)>=64 then s.bounds={};s.bounds_count=0 end
            s.bounds[model]=radius;s.bounds_count=(s.bounds_count or 0)+1;return radius
        end
    end
    local function scan_score(record,camera,direction)
        local point=record and vector(H.COORD,record.handle,true)
        if not point then return nil end
        local x,y,z=point.x-camera.x,point.y-camera.y,point.z-camera.z
        local along=x*direction.x+y*direction.y+z*direction.z
        local perpendicular=math.max(0,x*x+y*y+z*z-along*along)
        if along>0 and perpendicular<=along*along*0.003 then
            local radius=model_radius(record.model)
            if radius and perpendicular<=radius*radius and matches(record) then return along end
        end
    end
    local function player_vehicle_target(camera,direction,player)
        local players,gta=d.Players,d.GTA
        if not players or type(players.GetById)~="function"or type(players.GetCPed)~="function"
            or not gta or type(gta.PointerToHandle)~="function"then return nil end
        local best,best_distance
        for pid=0,31 do
            if pid~=player.pid then
                local good,record,remote_current=pcall(function()
                    local p=players.GetById(pid)
                    if not p or p:IsLocalPlayer()~=false then return end
                    local cxn,address=p.CxnId,p:GetAddress()
                    local info=p:GetGamerInfo();local rid=info and info.RockstarId
                    if not finite(cxn)or cxn%1~=0 or not finite(address)or address<=0 or rid==nil then return end
                    rid=tostring(rid)
                    local ped=players.GetCPed(pid);local vehicle=ped and ped.CurVehicle
                    if not vehicle then return end
                    local ped_address=ped:GetAddress()
                    local vehicle_address=vehicle:GetAddress()
                    if not finite(ped_address)or ped_address<=0 or not finite(vehicle_address)or vehicle_address<=0 then return end
                    local handle=gta.PointerToHandle(vehicle)
                    local candidate=classify(handle)
                    if not candidate or not candidate.vehicle or candidate.address~=vehicle_address then return end
                    local function remote_same()
                        local current=players.GetById(pid)
                        if not current or current:IsLocalPlayer()~=false or current.CxnId~=cxn
                            or current:GetAddress()~=address then return false end
                        local gamer=current:GetGamerInfo()
                        if not gamer or tostring(gamer.RockstarId)~=rid then return false end
                        local fresh_ped=players.GetCPed(pid)
                        local fresh_vehicle=fresh_ped and fresh_ped.CurVehicle
                        return fresh_ped and fresh_ped:GetAddress()==ped_address and fresh_vehicle
                            and fresh_vehicle:GetAddress()==vehicle_address and current.CxnId==cxn
                            and matches(candidate)
                    end
                    if not remote_same()then return end
                    return candidate,remote_same
                end)
                if good and record then
                    local along=scan_score(record,camera,direction)
                    if along and(not best_distance or along<best_distance)then
                        best,best_distance=record,along
                        record.acquisition={camera=camera,direction=direction,player=player,
                            generation=s.generation,remote_current=remote_current}
                    end
                end
            end
        end
        if best and acquisition_current(best.acquisition,player)and scan_score(best,camera,direction)then return best end
    end
    local function scan_targets(camera,direction,player,now,allow_result)
        local pool=d.PoolMgr
        if not pool then return nil end
        local kinds={{"GetMaxVehicleCount","GetVehicle"},{"GetMaxPedCount","GetPed"},{"GetMaxObjectCount","GetObject"}}
        local scan=s.scan
        if scan then
            local owner=scan.player
            if scan.generation~=s.generation or not owner or owner.pid~=player.pid
                or owner.handle~=player.handle or owner.address~=player.address
                or owner.model~=player.model or owner.network~=player.network
                or not matches(owner)or current_player_id()~=player.pid then
                s.scan=nil;scan=nil
            end
        end
        if not scan then
            -- Snapshot the relevant capacities once per pass. Never commit the best
            -- candidate from a partial slice: a nearer target may be in a later slot.
            scan={camera=camera,direction=direction,player=player,generation=s.generation,
                limits={},cursors={0,0,0},kind=0}
            for i,row in ipairs(kinds)do
                local ok,count=pcall(function()return pool[row[1]]()end)
                scan.limits[i]=ok and finite(count) and type(pool[row[2]])=="function"
                    and clamp(math.floor(count),0,65536) or 0
            end
            s.scan=scan
        else
            -- Camera motion renews scoring, not progress through the pools.
            -- A prior best remains eligible only under the current reticle.
            scan.camera,scan.direction=camera,direction
            if scan.best then
                local distance=scan_score(scan.best,camera,direction)
                if distance then scan.best_distance=distance
                else scan.best,scan.best_distance=nil,nil end
            end
        end
        local started=type(d.now_ms)=="function" and d.now_ms() or nil
        for _=1,24 do
            if scan.done or (started and d.now_ms()-started>=1) then break end
            local kind
            for _=1,3 do
                scan.kind=scan.kind%3+1
                if scan.cursors[scan.kind]<scan.limits[scan.kind] then kind=scan.kind;break end
            end
            if not kind then scan.done=true;break end
            local index=scan.cursors[kind];scan.cursors[kind]=index+1
            local ok,handle=pcall(pool[kinds[kind][2]],index)
            if ok and finite(handle) and handle>0 and handle~=player.handle then
                local record=classify(handle)
                local along=scan_score(record,scan.camera,scan.direction)
                if along and (not scan.best_distance or along<scan.best_distance) then
                    scan.best,scan.best_distance=record,along
                end
            end
        end
        if not scan.done then
            scan.done=true
            for i=1,3 do if scan.cursors[i]<scan.limits[i] then scan.done=false;break end end
        end
        if not scan.done or not allow_result then return nil end
        s.scan=nil
        local record=scan.best
        local fresh_camera,fresh_rotation=vector(H.CAMERA),vector(H.CAMROT,2)
        if not fresh_camera or not fresh_rotation then return nil end
        local pitch,yaw=math.rad(fresh_rotation.x),math.rad(fresh_rotation.z)
        local fresh_direction={x=-math.sin(yaw)*math.cos(pitch),y=math.cos(yaw)*math.cos(pitch),z=math.sin(pitch)}
        scan.camera,scan.direction=fresh_camera,fresh_direction
        if record and scan_score(record,fresh_camera,fresh_direction)and acquisition_current(scan,player)then
            record.acquisition={camera=fresh_camera,direction=fresh_direction,player=scan.player,generation=scan.generation}
            return record
        end
    end
    local function target(player,now)
        local camera,rotation=vector(H.CAMERA),vector(H.CAMROT,2)
        if not camera or not rotation then return nil end
        local pitch,yaw=math.rad(rotation.x),math.rad(rotation.z)
        local direction={x=-math.sin(yaw)*math.cos(pitch),y=math.cos(yaw)*math.cos(pitch),z=math.sin(pitch)}
        -- Loaded player vehicles are a bounded32-slot direct route, independent
        -- of rendered far clip or completion of a moving-camera world pool pass.
        local vehicle=player_vehicle_target(camera,direction,player)
        if vehicle then
            if s.ray then s.ray.discard=true;poll_ray(false)end
            s.scan=nil;return vehicle
        end
        if type(d.invoke_int_detail)~="function" then return weapon_target() end
        local memory=d.Memory
        if not memory or type(memory.Alloc)~="function" or type(memory.Free)~="function"
            or type(memory.ReadInt)~="function" then return nil end
        local function fallback(allow_result)
            local record=scan_targets(camera,direction,player,now,allow_result)
            if record then
                if s.ray then s.ray.discard=true end
            end
            return record
        end
        local ray=s.ray
        if ray then
            local dot=direction.x*ray.direction.x+direction.y*ray.direction.y+direction.z*ray.direction.z
            local delta=(camera.x-ray.camera.x)^2+(camera.y-ray.camera.y)^2+(camera.z-ray.camera.z)^2
            if now-ray.started>500 or not matches(ray.player) or ray.player.address~=player.address
                or ray.player.pid~=player.pid or dot<0.996 or delta>4 then
                ray.discard=true
            end
            local complete,hit,handle=poll_ray(true)
            if not complete then return fallback(ray.discard==true) end
            if ray.discard or ray.generation~=s.generation or hit~=1 then return fallback(true) end
            local record=classify(handle)
            if not record then return fallback(true) end
            s.scan=nil
            record.acquisition=ray
            return record
        end
        local generation=s.generation
        local range=100000.0
        local handle=integer(H.RAY,camera.x,camera.y,camera.z,
            camera.x+direction.x*range,camera.y+direction.y*range,camera.z+direction.z*range,62,player.handle,7)
        if handle and handle>0 then
            s.ray={handle=handle,player=player,started=now,camera=camera,direction=direction,generation=generation,
                discard=generation~=s.generation or not enabled()}
        end
        return fallback(s.ray==nil)
    end
    local function coexist(now)
        if s.yielded then
            if now<(s.next_yield_poll or 0)then return false end
            s.next_yield_poll=now+100
            local f,id=feature()
            if not f then s.status="HOST_UNAVAILABLE";return false end
            local current=toggled(f)
            if current==nil then s.status="HOST_UNAVAILABLE";return false end
            if s.yield_owner_id and id~=s.yield_owner_id then
                s.yield_owner_id=id;s.status="CHERAX_ACTIVE";return false
            end
            s.yield_owner_id=id
            if current~=false then s.status="CHERAX_ACTIVE";return false end
            if not enabled()or s.resetting then return false end
            -- The exact typed provider is now positively off. The existing
            -- helper establishes its new paused lease; entity proof is separate.
            s.yielded=false;s.yield_owner_id=nil;s.next_yield_poll=nil
        end
        local held,player,released,generation=s.held,s.player,s.released,s.generation
        local allowed=builtin(now)
        if not allowed and s.yielded then
            -- Preserve selection metadata only. Drop inside the unchanged
            -- conflict helper still invalidates pending queries/generations.
            if held and enabled()and not s.resetting and s.generation==generation+1 then
                s.held,s.player,s.released=held,player,released
                s.previous_time=nil
            end
            local f,id=feature()
            if f and toggled(f)~=nil then s.yield_owner_id=id end
            s.next_yield_poll=now+100
        end
        return allowed
    end
    local function valid_write(record,player,generation)
        if record and record.vehicle then
            local occupied=integer(0x9A9112A0FE9A4713,player.handle,false)
            if occupied==nil or occupied==record.handle then return false end
        end
        if generation~=s.generation or not enabled() or s.yielded or s.resetting then return false end
        local owner=s.player
        if not owner or s.held~=record or owner.pid~=player.pid or owner.handle~=player.handle
            or owner.address~=player.address or owner.model~=player.model or owner.network~=player.network then return false end
        if not coexist(s.now or 0) then return false end
        local current=local_ready(s.held==record)
        return current~=nil and current.pid==owner.pid and current.handle==owner.handle
            and current.address==owner.address and current.model==owner.model and current.network==owner.network
            and aiming(player.pid)==true and matches(record)
            and boolean(H.CONTROL,record.handle)==true and matches(record)
            and input_scope(player.pid,s.held==record)
            and (not record.ped or (record.handle~=player.handle and boolean(H.PED,record.handle)==true
                and boolean(H.IN_VEHICLE,record.handle,false)==false))
            and boolean(H.SESSION)==true and boolean(H.TRANSITION)==false and boolean(H.PAUSE)==false
            and boolean(H.DEAD,player.handle,false)==false
            and boolean(H.CONTROL,record.handle)==true and matches(player)
            and matches(record)
            and current_player_id()==owner.pid and s.player==owner and s.held==record
            and generation==s.generation and enabled()
    end
    local function motion(record,player,generation,h,...)
        if not valid_write(record,player,generation) then return false end
        return dispatch(h,record.handle,...)
    end
    local function retained_pause(status)
        local terminal=not enabled()
        local online,transition=boolean(H.SESSION),boolean(H.TRANSITION)
        terminal=terminal or online==false or transition==true
        if not terminal and s.player then
            local pid=current_player_id()
            if pid~=nil and pid~=s.player.pid then terminal=true end
        end
        if not terminal and online==true and transition==false and s.player then
            local handle=type(d.local_ped)=="function"and d.local_ped()or nil
            if finite(handle)then
                if boolean(H.DEAD,handle,false)==true then terminal=true
                else
                    local fresh=physical(handle)
                    if fresh and(fresh.handle~=s.player.handle or fresh.address~=s.player.address
                        or fresh.model~=s.player.model or fresh.network~=s.player.network)then terminal=true end
                end
            end
        end
        if terminal then drop();s.status="SCOPE_CHANGED";return end
        s.previous_time=nil
        local record=s.held
        if record then
            record.last_target=nil;record.last_distance=nil
            record.pressure_axis=nil;record.pressure_time=nil;record.contact_until=nil
            record.scroll_speed=nil;record.scroll_time=nil;record.scrolling=nil
        end
        if s.ray then s.ray.discard=true;poll_ray(false)end
        s.status=s.yielded and "CHERAX_ACTIVE"or status or "PAUSED"
    end
    local function capture_held_inputs(player,controls)
        local held_controls={controls.attack,controls.wheel_next,controls.wheel_prev,controls.context}
        for _,key in ipairs({"scroll_up","scroll_down","tumble","select_next","select_prev",
            "radio_next","radio_prev","radio_track_next","radio_track_prev"})do
            if finite(controls[key])then held_controls[#held_controls+1]=controls[key]end
        end
        for _,control in ipairs({39,40,41,42,43})do held_controls[#held_controls+1]=control end
        for _,control in ipairs(held_controls)do
            if not dispatch(H.DISABLE,0,control,true)then return false end
        end
        return current_player_id()==player.pid and dispatch(H.NO_FIRE,player.pid,true)
    end
    function api.Drop() drop();s.status="RELEASED" end
    function api.ResetDistance()s.distance=12 end
    function api.Reset(reason)
        drop();s.resetting=true;s.yielded=false;s.yield_owner_id=nil;s.next_yield_poll=nil
        local now=s.now or 0
        local query_clean=poll_ray(false)
        local restored=restore(now,true)
        restored=restored and query_clean
        if restored then s.resetting=false;s.status=reason or "OFF" end
        return restored
    end
    function api.Requested()return enabled() or s.ray~=nil or (s.lease~=nil and s.lease.owned==true) end
    function api.RestoreRequested()
        return (s.ray~=nil and s.ray.discard==true) or (s.resetting==true and s.lease~=nil and s.lease.owned==true)
    end
    function api.RestoreTick(now)
        -- Called outside domain dispatch for cleanup only; cannot acquire or move.
        if not api.RestoreRequested() then return true end
        now=finite(now) and now or s.now or 0;s.now=now
        local query_clean=poll_ray(false)
        local restored=true
        if s.resetting then restored=restore(now,false) end
        restored=restored and query_clean
        if restored then s.resetting=false end
        return restored
    end
    function api.Snapshot()
        return {status=s.status,blocked=s.blocked,distance=s.distance,held=s.held and s.held.handle or nil,
            restore_pending=api.RestoreRequested(),
            power=clamp(tonumber(type(d.power)=="function" and d.power() or 1) or 1,1,20)}
    end
    local function tick(now)
        now=finite(now) and now or 0;s.now=now
        if not enabled() then
            drop();s.yielded=false;s.yield_owner_id=nil;s.next_yield_poll=nil;s.resetting=true
            local query_clean=poll_ray(false)
            local restored=restore(now,false)
            if restored and query_clean then s.resetting=false;s.status="OFF" end
            return
        end
        if s.resetting then
            local query_clean=poll_ray(false)
            local restored=restore(now,false)
            if not restored or not query_clean then return end
            s.resetting=false
        end
        local controls=d.controls
        if not controls or not finite(controls.attack) or not finite(controls.wheel_next)
            or not finite(controls.wheel_prev) or not finite(controls.context) then s.status="INPUT_UNAVAILABLE";return end
        local inputs_captured=false
        -- Explicit selection belongs to GTA, including while aim is held.
        for _,key in ipairs({"weapon_wheel","radio_wheel","character_wheel"})do
            local control=controls[key]
            if finite(control) and pressed(control,false) then
                drop();poll_ray(false);s.released=true;s.status="RELEASE_AIM";return
            end
        end
        -- Release is independent of GUI/control eligibility, and unknown input
        -- cannot silently turn an established lock into a new acquisition.
        if s.held then
            local aim=held_aim_state(s.player and s.player.pid)
            if aim==false then drop();poll_ray(false);s.released=false;s.status="READY";return end
            if aim~=true then retained_pause("AIM_UNAVAILABLE");return end
        end
        local player=local_ready(s.held~=nil)
        if not player then
            local ped=type(d.local_ped)=="function"and d.local_ped()or nil
            local terminal=boolean(H.SESSION)==false or boolean(H.TRANSITION)==true
                or(finite(ped)and boolean(H.DEAD,ped,false)==true)
            if s.held and not terminal then retained_pause("PAUSED");return end
            drop()
            local pid=s.player and s.player.pid or(type(d.local_player_id)=="function"and d.local_player_id()or nil)
            if aiming(pid)==false then s.released=false end
            s.resetting=true;restore(now,false);s.status="PAUSED";return
        end
        if not coexist(now) then
            if s.held then retained_pause(s.status)
            else drop();if aiming(player.pid)==false then s.released=false end end;return
        end
        if aiming(player.pid)~=true then
            if s.held and held_aim_state(player.pid)~=false then
                retained_pause("AIM_UNAVAILABLE");return
            end
            drop();poll_ray(false);s.released=false;s.status="READY";return
        end
        if s.released then s.status="RELEASE_AIM";return end
        if s.held and (not s.player or s.player.pid~=player.pid or s.player.address~=player.address or s.player.handle~=player.handle
            or s.player.network~=player.network or s.player.model~=player.model) then drop();return end
        if s.held then
            -- Selection still owns throw/wheel inputs through a presence gap;
            -- an unavailable target must not turn Fire into a weapon shot.
            if not capture_held_inputs(player,controls)then retained_pause("INPUT_UNAVAILABLE");return end
            inputs_captured=true
            if not matches(s.held)then retained_pause("TARGET_UNAVAILABLE");return end
        end
        if not s.held then
            if not s.pending then
                local generation=s.generation
                local record,reason=target(player,now)
                if generation~=s.generation or not enabled() then return end
                if not record then s.status=reason or "AIM_AT_TARGET";return end
                record.started=now;record.next_request=now;record.epoch=s.generation;s.pending=record
            end
            local record=s.pending
            if record.epoch~=s.generation then s.pending=nil;return end
            if not acquisition_current(record.acquisition,player) then s.pending=nil;s.status="AIM_AT_TARGET";return end
            if not matches(record) then drop();s.status="TARGET_CHANGED";return end
            if boolean(H.CONTROL,record.handle)~=true then
                if now-record.started>750 then drop();s.status="NO_CONTROL";return end
                if now>=record.next_request then
                    record.next_request=now+200
                    if matches(record)and current_player_id()==player.pid then boolean(H.REQUEST,record.handle) end
                end
                s.status="REQUESTING_CONTROL";return
            end
            if not acquisition_current(record.acquisition,player) then s.pending=nil;s.status="AIM_AT_TARGET";return end
            if not matches(record) then drop();return end
            if record.epoch~=s.generation then s.pending=nil;return end
            s.held,s.pending,s.player=record,nil,player
            record.pickup=true
        end
        local record=s.held
        local generation=s.generation
        if not inputs_captured and not capture_held_inputs(player,controls)then retained_pause("INPUT_UNAVAILABLE");return end
        if record.pickup then
            local camera,position=vector(H.CAMERA),vector(H.COORD,record.handle,true)
            if not camera or not position then retained_pause("CAMERA_UNAVAILABLE");return end
            local x,y,z=position.x-camera.x,position.y-camera.y,position.z-camera.z
            s.distance=math.max(3,math.sqrt(x*x+y*y+z*z))
            record.pickup=nil
        end
        local outward=controls.scroll_up and pressed(controls.scroll_up,true) or false
        local inward=controls.scroll_down and pressed(controls.scroll_down,true) or false
        if not inward and not outward then
            outward=pressed(controls.wheel_prev,true) or (finite(controls.select_prev) and pressed(controls.select_prev,true))
            inward=pressed(controls.wheel_next,true) or (finite(controls.select_next) and pressed(controls.select_next,true))
        end
        local camera,rotation=vector(H.CAMERA),vector(H.CAMROT,2)
        local position=vector(H.COORD,record.handle,true)
        if not camera or not rotation or not position then retained_pause("CAMERA_UNAVAILABLE");return end
        local pitch,yaw=math.rad(rotation.x),math.rad(rotation.z)
        local direction={x=-math.sin(yaw)*math.cos(pitch),y=math.cos(yaw)*math.cos(pitch),z=math.sin(pitch)}
        local along=(position.x-camera.x)*direction.x+(position.y-camera.y)*direction.y+(position.z-camera.z)*direction.z
        if not finite(along) then retained_pause("CAMERA_UNAVAILABLE");return end
        local power=tonumber(type(d.power)=="function" and d.power() or 1) or 1
        power=finite(power) and clamp(power,1,20) or 1
        local elapsed=now-(s.previous_time or now-16)
        local dt=clamp(elapsed/1000,1/240,0.1)
        local rate=35
        local response=(1-math.exp(-rate*dt))/dt
        local launching=pressed(controls.attack,true)
        local near=3
        if not launching then
            local radius=model_radius(record.model)
            local actor_position=vector(H.COORD,player.handle,true)
            if not radius or not actor_position then retained_pause("BOUNDS_UNAVAILABLE");return end
            local actor_along=(actor_position.x-camera.x)*direction.x
                +(actor_position.y-camera.y)*direction.y+(actor_position.z-camera.z)*direction.z
            if not finite(actor_along)then retained_pause("BOUNDS_UNAVAILABLE");return end
            -- Keep the complete model beyond a plane in front of the player,
            -- including third-person camera offset. Clearance is an active
            -- hold policy, not a collision guarantee or an independent throw gate.
            near=math.max(3,actor_along+radius+1)
            s.distance=math.max(near,s.distance)
        end
        -- Each physical/disabled wheel-edge updates the REQUESTED hold depth
        -- exactly once. Do not rebase that depth from observed entity position:
        -- when a heavy vehicle stalls, physics readbacks may remain unchanged
        -- for many frames and would cancel the user's scroll requests.
        -- This is a destination adjustment, not an increase in force/velocity.
        if outward~=inward then
            local notch=(record.ped and 5.0 or 8.0)*math.sqrt(power)
            s.distance=math.max(near,s.distance+(outward and notch or -notch))
            record.last_wheel_ms=now
            record.scroll_notches=math.min(999999,(record.scroll_notches or 0)+1)
        end
        -- Never queue or replay an old notch after a control or camera gap.
        record.scrolling=nil
        record.scroll_speed=nil
        record.scroll_time=nil
        if generation~=s.generation or not enabled() or not matches(record) then return end
        if matches(record) and boolean(H.CONTROL,record.handle)==false then
            record.pressure_axis=nil;record.pressure_time=nil
            record.contact_until=nil
            if now>=(record.next_request or 0) then
                record.next_request=now+200
                if matches(record)and current_player_id()==player.pid then boolean(H.REQUEST,record.handle) end
            end
            s.status="REACQUIRING_CONTROL";return
        end
        if not valid_write(record,player,generation) then retained_pause("NO_CONTROL");return end
        if record.ped and now>=(record.next_ragdoll or 0) then
            if boolean(H.RAG_STATE,record.handle)~=true then
                if boolean(H.CAN_RAGDOLL,record.handle)~=true or not valid_write(record,player,generation)
                    or boolean(H.RAGDOLL,record.handle,1000,1000,0,false,false,false)~=true then
                    retained_pause("NPC_RAGDOLL_UNAVAILABLE");return
                end
            elseif not motion(record,player,generation,H.RAG_RESET) then
                retained_pause("PED_RAGDOLL_UNAVAILABLE");return
            end
            record.next_ragdoll=now+250
        end
        if launching then
            local accepted=motion(record,player,generation,H.SETVEL,direction.x*70*power,direction.y*70*power,direction.z*70*power)
            if accepted then drop();s.status="THROWN"else retained_pause("THROW_REJECTED")end;return
        end
        local target={x=camera.x+direction.x*s.distance,y=camera.y+direction.y*s.distance,z=camera.z+direction.z*s.distance}
        local dx,dy,dz=target.x-position.x,target.y-position.y,target.z-position.z
        local distance=math.sqrt(dx*dx+dy*dy+dz*dz)
        local velocity=vector(H.VELOCITY,record.handle)
        if not velocity then retained_pause("VELOCITY_UNAVAILABLE");return end
        -- Direct following in clear space; collision contacts retain a softer correction.
        local limit=math.max(600*math.sqrt(power),math.abs(record.scroll_speed or 0))
        if record.ped and distance<0.15 then dx,dy,dz,distance=0,0,0,0 end
        local speed=distance>0 and math.min(limit,distance*response)/distance or 0
        local vx,vy,vz=dx*speed,dy*speed,dz*speed
        if record.last_target and s.previous_time and elapsed>0 and elapsed<=100 then
            local old=record.last_target
            -- Differentiate camera motion at the previous depth. Wheel depth
            -- changes already enter position error and must not add a kick.
            local depth=record.last_distance or s.distance
            local tx,ty,tz=(camera.x+direction.x*depth-old.x)/dt,
                (camera.y+direction.y*depth-old.y)/dt,(camera.z+direction.z*depth-old.z)/dt
            local length=math.sqrt(tx*tx+ty*ty+tz*tz)
            local scale=(length>limit and limit/length or 1)*math.exp(-rate*dt)
            vx,vy,vz=vx+tx*scale,vy+ty*scale,vz+tz*scale
        end
        local desired_speed=math.sqrt(vx*vx+vy*vy+vz*vz)
        local desired_scale=desired_speed>limit and limit/desired_speed or 1
        local touching=boolean(H.CONTACT,record.handle)
        if touching~=false then record.contact_until=now+150 end
        local contact=now<(record.contact_until or 0)
        local budget=400
        if touching==true and distance>0.5 then
            local axis={x=dx/distance,y=dy/distance,z=dz/distance}
            local old=record.pressure_axis
            local continuing=elapsed<=100 and old and axis.x*old.x+axis.y*old.y+axis.z*old.z>0.5
            record.pressure_time=continuing and (record.pressure_time or 0)+dt or 0
            record.pressure_axis=axis
            budget=400+math.min(record.pressure_time/0.18,1)*(math.min(2400*power,12000)-400)
        else
            record.pressure_axis=nil;record.pressure_time=nil
        end
        local moved
        if record.ped and contact then
            -- Preserve the ragdoll's impact response without a force on its root.
            local x,y,z=vx*desired_scale-velocity.x,vy*desired_scale-velocity.y,vz*desired_scale-velocity.z
            local length=math.sqrt(x*x+y*y+z*z)
            local step=90*math.min(power,4)*dt
            local scale=length>step and step/length or 1
            moved=motion(record,player,generation,H.SETVEL,velocity.x+x*scale,velocity.y+y*scale,velocity.z+z*scale+9.81*dt)
        elseif contact then
            -- Keep impact rebound instead of replacing its velocity with the full follow command.
            local correction=(1-math.exp(-120*dt))/dt
            local fx=(vx*desired_scale-velocity.x)*correction
            local fy=(vy*desired_scale-velocity.y)*correction
            local fz=(vz*desired_scale-velocity.z)*correction+9.81
            local length=math.sqrt(fx*fx+fy*fy+fz*fz)
            local scale=length>budget and budget/length or 1
            moved=motion(record,player,generation,H.FORCE,0,fx*scale,fy*scale,fz*scale,0,false,true,false)
        else
            local move_x,move_y,move_z=vx*desired_scale,vy*desired_scale,vz*desired_scale+9.81*dt
            -- Camera feedforward and gravity compensation must not bypass
            -- inward braking. Keep tangential motion and outward speed intact.
            local radial=move_x*direction.x+move_y*direction.y+move_z*direction.z
            local minimum=-math.max(0,along-near)*response
            if radial<minimum then
                local brake=minimum-radial
                move_x,move_y,move_z=move_x+direction.x*brake,move_y+direction.y*brake,move_z+direction.z*brake
            end
            moved=motion(record,player,generation,H.SETVEL,move_x,move_y,move_z)
        end
        if not moved then
            retained_pause("MOTION_REJECTED");return
        end
        s.previous_time=now;record.last_target=target;record.last_distance=s.distance
        local tumble=record.vehicle and finite(controls.tumble) and pressed(controls.tumble,false)
        if tumble then
            if not record.tumble_active then
                record.spin_seed=record.spin_seed or ((math.floor(now)+record.handle)&0xffffffff)
                local function random_component()
                    record.spin_seed=(1664525*record.spin_seed+1013904223)&0xffffffff
                    return ((record.spin_seed>>8)&65535)/32767.5-1
                end
                local x,y,z=random_component(),random_component(),random_component()
                local length=math.sqrt(x*x+y*y+z*z)
                if length<0.01 then x,y,z,length=1,1,1,math.sqrt(3) end
                local scale=math.pi*4/length
                record.tumble_axis={x=x*scale,y=y*scale,z=z*scale}
                local axis=record.tumble_axis
                if not motion(record,player,generation,H.ANGULAR,axis.x,axis.y,axis.z) then
                    retained_pause("TUMBLE_REJECTED");return
                end
                record.tumble_active=true
            end
            record.spinning="Q"
        elseif record.vehicle and pressed(controls.context,false) then
            record.tumble_axis=nil;record.tumble_active=nil
            local pose=vector(H.ROT,record.handle,2)
            if pose then
                local function level(angle)
                    angle=(angle+180)%360-180
                    local step=1080*dt
                    return math.abs(angle)<=step and 0 or angle+(angle>0 and -step or step)
                end
                if not motion(record,player,generation,H.SETROT,level(pose.x),level(pose.y),pose.z,2,true) then
                    retained_pause("LEVEL_REJECTED");return
                end
                if not motion(record,player,generation,H.ANGULAR,0.0,0.0,math.pi*4) then
                    retained_pause("LEVEL_REJECTED");return
                end
                record.spinning="E"
            end
        else
            record.tumble_axis=nil;record.tumble_active=nil
            if record.spinning=="E" and not motion(record,player,generation,H.ANGULAR,0.0,0.0,0.0) then
                retained_pause("SPIN_STOP_REJECTED");return
            end
            -- Q is a one-shot angular launch. Release leaves its momentum and
            -- subsequent contacts to physics; only E owns a commanded stop.
            record.spinning=nil
        end
        if generation==s.generation and enabled() then s.status="HOLDING" end
    end
    function api.Tick(now)
        tick(now)
        local status=s.status..(s.status=="PAUSED" and s.blocked and ":"..s.blocked or "")
        if type(d.log_info)=="function" and status~=s.logged_status and (s.now or 0)>=(s.next_log or 0) then
            s.logged_status=status;s.next_log=(s.now or 0)+1000
            d.log_info("Gravity Gun status="..status.." distance="..string.format("%.1f",s.distance))
        end
    end
    return api
end

local function create_weapon_system(deps)
local log_info = require_binding("log_info", deps.log_info)
local log_warn = require_binding("log_warn", deps.log_warn)
local log_error_once = require_binding("log_error_once", deps.log_error_once)
local toast = require_binding("toast", deps.toast)
local invoke_void = require_binding("invoke_void", deps.invoke_void)
local invoke_int = require_binding("invoke_int", deps.invoke_int)
local invoke_bool = require_binding("invoke_bool", deps.invoke_bool)
local now_ms = require_binding("now_ms", deps.now_ms)
local local_ped = require_binding("local_ped", deps.local_ped)
local local_vehicle = require_binding("local_vehicle", deps.local_vehicle)
local entity_exists = require_binding("entity_exists", deps.entity_exists)
local feature_id = require_binding("feature_id", deps.feature_id)
local H = require_binding("H", deps.H)

-- Session-local inventory helpers. These reconcile only the current ped.
local REMOVE_WEAPON_FROM_PED_NATIVE = 0x4899CB088EDF59B8
local GET_AMMO_IN_PED_WEAPON_NATIVE = 0x015A522136D7F951

local Ammo = {last={status="NOT_SAMPLED",verified=false}}
Ammo.H={ammo_type=0x7FEAD38B326B9F74,set_type=0x5FD1E1F011E76D7E,read_type=0x39D22031557946C1,
    max_type=0x585847C5E4E11709,max_weapon=0xDC16122C7A20C933,max_clip=0xA38DCFFCEA8962FA,
    read_clip=0x2E1202248937775C,set_clip=0xDCD2A934D65CB497,reload=0x20AE33F3AC9C0033,
    refill=0x8C0D57EA686FAD87}
function Ammo.Try(kind,hash,...)
    local native=module_context and module_context.Natives
    if not native or type(native.Try)~="function" then return false end
    local ok,called,value=pcall(native.Try,kind,hash,...)
    return ok and called==true,value
end
function Ammo.Count(value,maximum)
    if type(value)=="number" and value==value and value%1==0
        and value>=0 and value<=(maximum or 9999) then return value end
end
function Ammo.Type(ped,weapon)
    local ok,value=Ammo.Try("int",Ammo.H.ammo_type,ped,weapon)
    if ok and type(value)=="number" and value==value and value%1==0
        and value>=-0x80000000 and value<=0xffffffff then return value&0xffffffff end
end
function Ammo.Total(ped,weapon,ammo_type)
    ammo_type=ammo_type or Ammo.Type(ped,weapon)
    if ammo_type==nil then return nil end
    local ok,value
    if ammo_type~=0 then ok,value=Ammo.Try("int",Ammo.H.read_type,ped,ammo_type)
    else ok,value=Ammo.Try("int",GET_AMMO_IN_PED_WEAPON_NATIVE,ped,weapon) end
    return ok and Ammo.Count(value,1000000) or nil
end
function Ammo.Output(hash,ped,weapon)
    local memory=deps.Memory
    if not memory then return nil end
    for _,name in ipairs({"AllocInt","WriteInt","ReadInt","Free"})do
        if type(memory[name])~="function"then return nil end
    end
    local allocated,pointer=pcall(memory.AllocInt)
    if not allocated or type(pointer)~="number" or pointer<=0 then return nil end
    local ok,value=pcall(function()
        memory.WriteInt(pointer,-1)
        local called,accepted=Ammo.Try("bool",hash,ped,weapon,pointer)
        if not called or (accepted~=true and accepted~=1)then return nil end
        return Ammo.Count(memory.ReadInt(pointer),1000000)
    end)
    pcall(memory.Free,pointer)
    return ok and value or nil
end
function Ammo.Snapshot()
    local out={}
    for _,key in ipairs({"status","requested","total","clip","ammo_type","reported_max","verified","limited","method"})do
        out[key]=Ammo.last[key]
    end
    return out
end
function Ammo.Equipped(ped,weapon,ammo_type)
    if ped~=local_ped() or Ammo.Type(ped,weapon)~=ammo_type then return false end
    local ok,selected=Ammo.Try("int",H.GET_SELECTED_PED_WEAPON,ped)
    return ok and type(selected)=="number" and selected%1==0
        and (selected&0xffffffff)==(weapon&0xffffffff)
end
function Ammo.Set(ped,weapon,requested,options)
    local row={status="INVALID_REQUEST",verified=false,limited=false,method="current_ammo_type"}
    Ammo.last=row
    if Ammo.Count(requested)==nil then return false end
    row.requested=requested
    if not entity_exists(ped) or ped~=local_ped() then row.status="PED_UNAVAILABLE";return false end
    local owned,has=Ammo.Try("bool",H.HAS_PED_GOT_WEAPON,ped,weapon,false)
    if not owned or (has~=true and has~=1)then row.status="WEAPON_UNAVAILABLE";return false end
    local ammo_type=Ammo.Type(ped,weapon)
    if ammo_type==nil then row.status="TYPE_UNREADABLE";return false end
    row.ammo_type=ammo_type
    row.reported_max=Ammo.Output(ammo_type~=0 and Ammo.H.max_type or Ammo.H.max_weapon,
        ped,ammo_type~=0 and ammo_type or weapon)
    -- GET_MAX_AMMO(_BY_TYPE) returns BOOL + int*. An unreadable output is
    -- never a zero-ammo instruction, and the request remains exactly 9999.
    if ped~=local_ped() or Ammo.Type(ped,weapon)~=ammo_type then row.status="IDENTITY_CHANGED";return false end
    -- Independent setters: an optional type-based failure must not erase a
    -- successful weapon-specific write. Ammo/clip readback still decides success.
    local wrote_weapon=Ammo.Try("void",H.SET_PED_AMMO,ped,weapon,requested,false)
    if ped~=local_ped() or Ammo.Type(ped,weapon)~=ammo_type then row.status="IDENTITY_CHANGED";return false end
    local wrote_type=false
    if ammo_type~=0 then wrote_type=Ammo.Try("void",Ammo.H.set_type,ped,ammo_type,requested) end
    if not wrote_weapon and not wrote_type then row.status="WRITE_FAILED";return false end
    if ped~=local_ped() or Ammo.Type(ped,weapon)~=ammo_type then row.status="IDENTITY_CHANGED";return false end
    local equipped=Ammo.Equipped(ped,weapon,ammo_type)
    local clip_ok,clip_max=Ammo.Try("int",Ammo.H.max_clip,ped,weapon,true)
    clip_max=clip_ok and Ammo.Count(clip_max) or nil
    local clip_target=clip_max and math.min(requested,clip_max) or nil
    local reserve_only=type(options)=="table" and options.reserve_only==true
    if clip_target~=nil and not reserve_only then Ammo.Try("bool",Ammo.H.set_clip,ped,weapon,clip_target) end
    row.clip=Ammo.Output(Ammo.H.read_clip,ped,weapon)
    if not reserve_only and equipped and clip_target and clip_target>0 and row.clip~=clip_target
        and Ammo.Equipped(ped,weapon,ammo_type) then
        -- Mk II pools can ignore direct clip writes. Reload only the current
        -- weapon; never switch the player's selection to fill a holstered gun.
        local called,accepted=Ammo.Try("bool",Ammo.H.reload,ped)
        if called and (accepted==true or accepted==1)then
            row.method="current_ammo_type_reload_requested"
            -- Reload itself can run callbacks or change selection. The instant
            -- completion must retain its own current-weapon identity check.
            if Ammo.Equipped(ped,weapon,ammo_type) then
                Ammo.Try("bool",Ammo.H.refill,ped)
                row.method="current_ammo_type_reload"
            end
        end
        row.clip=Ammo.Output(Ammo.H.read_clip,ped,weapon)
    end
    if ped~=local_ped() or Ammo.Type(ped,weapon)~=ammo_type then row.status="IDENTITY_CHANGED";return false end
    row.total=Ammo.Total(ped,weapon,ammo_type)
    local expected=requested
    if row.reported_max and row.reported_max>0 then expected=math.min(expected,row.reported_max) end
    local reserve_ok=row.total~=nil and row.total==expected
        and (requested==0 or expected>0)
    local clip_verified=reserve_only or not equipped or (row.clip~=nil and (requested==0 and row.clip==0 or requested>0 and row.clip>0))
    row.verified=reserve_ok and clip_verified
    row.limited=row.total~=nil and row.total<requested
    row.status=not row.verified and "AMMO_UNVERIFIED" or row.limited and "LIMITED" or "VERIFIED"
    return row.verified
end
function Ammo.MaxTick(ped,weapon,enabled,now)
    if not enabled then Ammo.target=nil;return end
    local ammo_type=Ammo.Type(ped,weapon)
    local target=Ammo.target
    if not target or target.ped~=ped or target.weapon~=weapon or target.ammo_type~=ammo_type then
        target={ped=ped,weapon=weapon,ammo_type=ammo_type,attempts=0,done=false}
        Ammo.target=target
    end
    local total=Ammo.Total(ped,weapon,ammo_type)
    if target.done and total~=nil and total>0 then return end
    local clip=Ammo.Output(Ammo.H.read_clip,ped,weapon)
    -- Never reload/rewrite a partially used magazine just because reserve
    -- readback temporarily reports empty or the ammo type is recalculating.
    if target.done and clip~=nil and clip>0 then return end
    if target.done and total==0 and clip==0 then target.done=false;target.attempts=0 end
    now=tonumber(now) or now_ms()
    if target.attempts>=4 then
        if now<(target.retry_after or 0)then return end
        target.attempts=0
    end
    target.attempts=target.attempts+1
    target.done=Ammo.Set(ped,weapon,9999,
        clip~=nil and clip>0 and {reserve_only=true} or nil)
    if not target.done and target.attempts>=4 then target.retry_after=now+5000 end
end
local function set_weapon_ammo(ped,weapon,requested)
    return Ammo.Set(ped,weapon,requested)
end

local function is_on(key)
    local feature =
        F[key]

    if feature
        and type(feature.IsToggled) == "function" then

        local ok, enabled =
            pcall(
                feature.IsToggled,
                feature
            )

        if ok then
            ToggleState[key] =
                enabled == true

            return enabled == true
        end
    end

    return ToggleState[key] == true
end

local function list_index(key)
    local feature = F[key]
    if not feature then return 0 end
    local ok, value = pcall(function() return feature:GetListIndex() end)
    return ok and type(value) == "number" and value or 0
end

local function input_text(key, fallback)
    local feature = F[key]
    if not feature then return fallback or "" end
    local ok, value = pcall(function() return feature:GetStringValue() end)
    return ok and type(value) == "string" and value or (fallback or "")
end


local function set_toggle(key, enabled)
    local feature =
        F[key]

    if not feature
        or type(feature.IsToggled) ~= "function"
        or type(feature.Toggle) ~= "function" then

        return false
    end

    local wanted =
        enabled == true

    local read_ok, current =
        pcall(
            feature.IsToggled,
            feature
        )

    if not read_ok then
        return false
    end

    if (current == true) ~= wanted then
        local toggle_ok =
            pcall(
                feature.Toggle,
                feature,
                wanted
            )

        if not toggle_ok then
            return false
        end
    end

    local verify_ok, observed =
        pcall(
            feature.IsToggled,
            feature
        )

    if not verify_ok
        or (observed == true) ~= wanted then

        return false
    end

    ToggleState[key] =
        wanted

    return true
end

local function add_toggle(key, name, description, default, callback)
    ToggleState[key] = default == true
    local function on_toggle(feature)
        local ok, enabled = pcall(function() return feature:IsToggled() end)
        if ok then ToggleState[key] = enabled == true end
        if callback then callback(feature) end
    end
    local feature = FeatureMgr.AddFeature(feature_id(key), name, eFeatureType.Toggle,
        description or "", on_toggle)
    if feature and type(feature.SetDefaultValue) == "function" then
        pcall(function()
            feature:SetDefaultValue(default == true)
            if default == true and type(feature.Toggle) == "function" and not feature:IsToggled() then
                feature:Toggle(true)
            end
        end)
    end
    F[key] = feature
    if feature then
        local ok, enabled = pcall(function() return feature:IsToggled() end)
        if ok then ToggleState[key] = enabled == true end
        State.registered_count = State.registered_count + 1
    end
    return feature
end


local function add_button(key, name, description, callback)
    local feature = FeatureMgr.AddFeature(feature_id(key), name, eFeatureType.Button,
        description or "", callback)
    F[key] = feature
    if feature then State.registered_count = State.registered_count + 1 end
    return feature
end

local function add_combo(key, name, description, values, default, callback)
    local feature = FeatureMgr.AddFeature(feature_id(key), name, eFeatureType.Combo,
        description or "", callback)
    if feature then pcall(function() feature:SetList(values):SetListIndex(default or 0) end) end
    F[key] = feature
    if feature then State.registered_count = State.registered_count + 1 end
    return feature
end

local function add_input_text(key, name, description, default)
    local feature = FeatureMgr.AddFeature(feature_id(key), name, eFeatureType.InputText, description or "")
    if feature and type(feature.SetStringValue) == "function" then
        pcall(function() feature:SetStringValue(default or "") end)
    end
    F[key] = feature
    if feature then State.registered_count = State.registered_count + 1 end
    return feature
end

local function add_slider_float(key, name, description, minimum, maximum, default, step)
    local feature=FeatureMgr.AddFeature(feature_id(key),name,eFeatureType.SliderFloat,description or "")
    if feature then
        feature:SetLimitValues(minimum,maximum):SetStepSize(step or 0.25):SetDefaultValue(default)
        F[key]=feature
        State.registered_count=State.registered_count+1
    end
    return feature
end

