local WEAPON_BY_HASH = {}
local WEAPON_HASH_BY_INTERNAL = {}
local WEAPON_COUNT = 0
local function weapon_hash_key(value)
    value = tonumber(value)
    if not value then return nil end
    return tostring(value & 0xFFFFFFFF)
end

for _, category in ipairs(WEAPON_CATEGORIES) do
    for _, weapon in ipairs(category.weapons) do
        weapon.category = category.name
        weapon.key = "loadout_pick_" .. weapon[2]
        weapon.hash = Utils.Joaat(weapon[2]) & 0xFFFFFFFF
        weapon.ui_label = weapon[1] .. "##weapon_" .. tostring(weapon.hash)
        weapon.ui_label_selected = "> " .. weapon[1] .. "##weapon_" .. tostring(weapon.hash)
        WEAPON_BY_HASH[weapon_hash_key(weapon.hash)] = weapon
        WEAPON_HASH_BY_INTERNAL[weapon[2]] = weapon.hash
        WEAPON_COUNT = WEAPON_COUNT + 1
    end
end

local WEAPON_VARIANT_COUNTERPART = {}
for internal_name, mk2_hash in pairs(WEAPON_HASH_BY_INTERNAL) do
    if internal_name:sub(-4) == "_mk2" then
        local base_hash = WEAPON_HASH_BY_INTERNAL[internal_name:sub(1, -5)]
        if base_hash then
            WEAPON_VARIANT_COUNTERPART[weapon_hash_key(mk2_hash)] = base_hash & 0xFFFFFFFF
            WEAPON_VARIANT_COUNTERPART[weapon_hash_key(base_hash)] = mk2_hash & 0xFFFFFFFF
        end
    end
end

