do
    function FastMelee.rate(phase)
        -- Keep a wide stock-speed interval around native contact events.
        if phase<0.18 then return FastMelee.RATE end
        if phase<0.68 then return 1.0 end
        return FastMelee.RECOVERY_RATE
    end
    local function finite(v)
        return type(v)=="number" and v==v and math.abs(v)<math.huge
    end
    function FastMelee.query(binding, kind, hash, ...)
        local fn=binding and binding["invoke_"..kind.."_detail"]
        if type(fn)~="function" then return nil end
        local ok,value,raw,err=pcall(fn,hash,...)
        if not ok or err~=nil then return nil end
        if kind=="bool" then
            if raw==true or raw==false or raw==0 or raw==1 then return value==true end
        elseif finite(value) and finite(raw) then return value end
    end
    function FastMelee.address(binding,ped)
        local api=binding and binding.GTA
        if not api or type(api.HandleToPointer)~="function" then return nil end
        local ok,address=pcall(function()
            local object=api.HandleToPointer(ped)
            return object and object:GetAddress()
        end)
        if ok and finite(address) and address>=0x10000 and address<=0x7FFFFFFFFFFF
            and address%1==0 then return address end
    end
    function FastMelee.release()
        local clip=State.fast_melee_clip
        if not clip then return true end
        if State.fast_melee_writing or State.fast_melee_restoring then return false end
        -- Release only the exact instance we changed. A recycled handle must
        -- never inherit a delayed restore. Death/weapon/session changes do not
        -- prevent restoring the old clip if that original ped still exists.
        local d=clip.binding
        local exists=FastMelee.query(d,"bool",H.DOES_ENTITY_EXIST,clip.ped)
        if exists==false then State.fast_melee_clip=nil; return true end
        if exists~=true then return false end
        local address=FastMelee.address(d,clip.ped)
        if not address then return false end
        if address~=clip.address then State.fast_melee_clip=nil; return true end
        local playing=FastMelee.query(d,"bool",FastMelee.PLAYING,clip.ped,clip.dict,clip.name,3)
        if playing==false then State.fast_melee_clip=nil; return true end
        if playing~=true or type(d.invoke_void)~="function" then return false end
        -- Keep debt on native failure, including a host call that may have
        -- applied its write before throwing. Pending restoration runs OFF too.
        if FastMelee.address(d,clip.ped)~=clip.address then return false end
        State.fast_melee_restoring=true
        local ok,wrote=pcall(d.invoke_void,FastMelee.SPEED,clip.ped,clip.dict,clip.name,1.0)
        State.fast_melee_restoring=false
        if ok and wrote==true then
            if State.fast_melee_clip==clip then State.fast_melee_clip=nil end
            return true
        end
        return false
    end
    FastMelee.unarmed,FastMelee.armed={},{}
    for _,family in ipairs({"unarmed","knife","large_wpn","small_wpn"}) do
        for _,suffix in ipairs({"","_fps"}) do
            for _,name in ipairs(FastMelee.families[family]) do
                local list=family=="unarmed" and FastMelee.unarmed or FastMelee.armed
                list[#list+1]={dict="melee@"..family.."@streamed_core"..suffix,name=name}
            end
        end
    end
    for _,name in ipairs({"heavy_punch_a_var_1","heavy_punch_b_var_1","heavy_punch_b_var_2","heavy_punch_c_var_1","vehicle_kick_var_a"})do
        FastMelee.unarmed[#FastMelee.unarmed+1]={dict="melee@unarmed@streamed_variations",name=name}
    end
end

local function reset_fast_melee()
    State.fast_melee_requested=false
    State.fast_melee_epoch=(State.fast_melee_epoch or 0)+1
    State.fast_melee_scan=1
    return FastMelee.release()
end

local function set_fast_melee_requested(wanted)
    reset_fast_melee()
    State.fast_melee_requested=wanted==true and State.runtime_writes_suspended~=true
        and State.host_cleanup_done~=true
end

local function fast_melee_tick(now)
    -- The common OFF path has no native calls. An owned restore debt is the
    -- sole exception and cannot be discarded by toggling or suspension.
    if not State.fast_melee_requested then return FastMelee.release() and false end
    local binding,context=deps,module_context
    local epoch,generation=State.fast_melee_epoch,State.job_generation
    local runtime=context and context.Runtime
    local coordinator=context and context.CScript and context.CScript.Runtime
    local coordinator_state=coordinator and coordinator.State
    local combat=coordinator_state and coordinator_state.combat
    local session=combat and combat.generation
    local function current()
        return State.fast_melee_requested==true and State.fast_melee_epoch==epoch
            and State.job_generation==generation and dependencies==binding
            and module_context==context and started and bound
            and not State.runtime_writes_suspended and not State.host_cleanup_done
            and runtime and context.Runtime==runtime and runtime.stopping~=true
            and coordinator and context.CScript.Runtime==coordinator and coordinator.State==coordinator_state
            and combat and coordinator_state.combat==combat and combat.generation==session
    end
    local function stop()
        State.fast_melee_scan=1
        FastMelee.release()
        return false
    end
    if not current() or type(binding.invoke_void)~="function"
        or type(binding.local_ped)~="function" or type(binding.local_player_id)~="function" then return stop() end
    local function call(fn,...)
        if not current() then return nil end
        local values=table.pack(pcall(fn,...))
        if not values[1] or not current() then return nil end
        return table.unpack(values,2,values.n)
    end
    local function integer(v,minimum,maximum)
        return type(v)=="number" and v==v and v%1==0 and v>=minimum and v<=maximum
    end
    local function query(kind,hash,...)
        if not current() then return nil end
        local value=FastMelee.query(binding,kind,hash,...)
        if current() then return value end
    end
    local function confirmed(hash,wanted,...)
        return hash~=nil and query("bool",hash,...)==wanted
    end
    if type(runtime)~="table" or not integer(session,0,9007199254740991)
        or not integer(generation,0,9007199254740991) then return stop() end
    local ped=call(binding.local_ped)
    local pid=call(binding.local_player_id)
    if not integer(ped,1,2147483646) or not integer(pid,0,31)
        or not confirmed(H.DOES_ENTITY_EXIST,true,ped) then return stop() end
    local selected=query("int",H.GET_SELECTED_PED_WEAPON,ped)
    if not integer(selected,-2147483648,4294967295) then return stop() end
    selected=selected&0xFFFFFFFF
    local group=query("int",0xC3287EE3050FB74C,selected)
    if not integer(group,-2147483648,4294967295) then return stop() end
    group=group&0xFFFFFFFF
    if group~=2685387236 and group~=3566412244 then return stop() end
    local function same_weapon()
        local value=query("int",H.GET_SELECTED_PED_WEAPON,ped)
        return integer(value,-2147483648,4294967295) and (value&0xFFFFFFFF)==selected
    end
    local address=FastMelee.address(binding,ped)
    if not address then return stop() end
    local function eligible()
        return current() and call(binding.local_ped)==ped and call(binding.local_player_id)==pid
            and FastMelee.address(binding,ped)==address
            and confirmed(H.NETWORK_IS_SESSION_STARTED,true)
            and confirmed(0x68049AEFF83D8F0A,false) -- network session transition
            and confirmed(0x5E9564D8246B909A,true,pid) -- player active
            and confirmed(0x49C32D60007AFA47,true,pid) -- player control
            and confirmed(0x01FEE67DB37F59B2,true,ped) -- on foot
            and confirmed(H.IS_ENTITY_DEAD,false,ped,false)
            and confirmed(H.IS_PED_DEAD_OR_DYING,false,ped,true)
            and confirmed(H.IS_PED_RAGDOLL,false,ped)
            and confirmed(H.IS_PED_RELOADING,false,ped)
            and confirmed(H.IS_PED_IN_COVER,false,ped,false)
            and confirmed(H.IS_PED_PERFORMING_MELEE_ACTION,true,ped)
            and same_weapon()
            and FastMelee.address(binding,ped)==address and current()
    end
    if not eligible() then return stop() end
    -- At low frame rates leave the collision/event sampling window at stock
    -- timing. Never compensate a slow frame by advancing extra AI updates.
    local dt=query("float",FastMelee.FRAME_TIME)
    if not dt or dt<=0 or dt>1/45 then return stop() end
    local owned=State.fast_melee_clip
    if owned then
        local phase=query("float",FastMelee.PHASE,ped,owned.dict,owned.name)
        local same=owned.binding==binding and owned.ped==ped and owned.address==address
            and owned.weapon==selected and owned.session==session and owned.generation==generation
            and confirmed(FastMelee.PLAYING,true,ped,owned.dict,owned.name,3)
            and phase and phase>=0 and phase<=1 and phase+0.01>=owned.phase
        -- Change speed without seeking/replaying the task or its hit events.
        if same and phase<0.95 then
            local rate=FastMelee.rate(phase)
            if owned.rate~=rate then
                if not eligible() then return stop() end
                State.fast_melee_writing=true
                local ok,wrote=pcall(binding.invoke_void,FastMelee.SPEED,ped,owned.dict,owned.name,rate)
                State.fast_melee_writing=false
                if not ok or wrote~=true or not current() then return stop() end
                owned.rate=rate
            end
            owned.phase=phase;return true
        end
        if not FastMelee.release() then return false end
        if same then return false end
    end
    local list=(selected==0xA2719263 or selected==0xD8DF3C3C) and FastMelee.unarmed or FastMelee.armed
    local cursor=State.fast_melee_scan or 1
    for _=1,math.min(FastMelee.SCAN_BUDGET,#list) do
        local clip=list[cursor]
        cursor=cursor%#list+1
        State.fast_melee_scan=cursor
        if confirmed(FastMelee.PLAYING,true,ped,clip.dict,clip.name,3) then
            local phase=query("float",FastMelee.PHASE,ped,clip.dict,clip.name)
            -- A rotating scan may discover an attack during contact or recovery.
            -- Adopting its current phase must never jump or replay the swing.
            if not phase or phase<0 or phase>=0.95 then return false end
            if not eligible() or not confirmed(FastMelee.PLAYING,true,ped,clip.dict,clip.name,3) then return stop() end
            local lease={binding=binding,ped=ped,address=address,weapon=selected,
                session=session,generation=generation,dict=clip.dict,name=clip.name,phase=phase,rate=FastMelee.rate(phase)}
            State.fast_melee_clip=lease -- reserve before dispatch/reentrant callbacks
            State.fast_melee_writing=true
            local ok,wrote=pcall(binding.invoke_void,FastMelee.SPEED,ped,clip.dict,clip.name,lease.rate)
            State.fast_melee_writing=false
            if not ok or wrote~=true or not current() then FastMelee.release(); return false end
            return true -- dispatch accepted, not proof of Enhanced playback/hits
        end
        if not current() then return stop() end
    end
    return false
end
-- Fast Melee end

local function fast_hands_tick(now)
    reset_fast_hands(0)
    local generation=State.job_generation
    local ped=local_ped()
    local function current()
        return started and bound and dependencies==deps
            and not State.runtime_writes_suspended and not State.host_cleanup_done
            and State.job_generation==generation and local_ped()==ped
            and is_on("fast_hands") and not is_on("instant_weapon_switch")
            and started and bound and State.job_generation==generation
            and not State.runtime_writes_suspended and not State.host_cleanup_done
    end
    local function identity()
        if not current() or not entity_exists(ped) or not current() then return nil end
        local api=deps.GTA
        if not api or type(api.GetLocalPed)~="function" or type(api.HandleToPointer)~="function" then return nil end
        local ok,address=pcall(function()
            local owner=api.GetLocalPed()
            if not current() then return nil end
            local entity=api.HandleToPointer(ped)
            if not current() then return nil end
            local a=owner and owner:GetAddress()
            if not current() then return nil end
            local b=entity and entity:GetAddress()
            if type(a)=="number" and a>0 and a<math.huge and a%1==0 and a==b then return a end
        end)
        if ok and current() then return address end
    end
    local address=identity()
    if not address or type(deps.invoke_bool_detail)~="function"
        or type(deps.advance_local_animation)~="function" then return end
    local function confirmed(hash,expected,...)
        if not hash or not current() then return false end
        local value,_,err=deps.invoke_bool_detail(hash,...)
        return err==nil and value==expected and current()
    end
    local function eligible()
        return identity()==address
            and confirmed(0x5E9564D8246B909A,true,deps.local_player_id())
            and confirmed(H.IS_ENTITY_DEAD,false,ped,false)
            and confirmed(H.IS_PED_DEAD_OR_DYING,false,ped,true)
            and confirmed(H.IS_PED_RAGDOLL,false,ped)
            and confirmed(H.IS_PED_RELOADING,false,ped)
            -- GTA melee/shooting tasks own their animation phases. Do not
            -- advance the local ped's animation while those tasks are active.
            and confirmed(H.IS_PED_PERFORMING_MELEE_ACTION,false,ped)
            and confirmed(H.IS_PED_IN_MELEE_COMBAT,false,ped)
            and confirmed(H.IS_PED_SHOOTING,false,ped)
            and confirmed(H.IS_PED_IN_ANY_VEHICLE,false,ped,false)
            and confirmed(0xB0760331C7AA4155,true,ped,56)
            and identity()==address
    end
    -- TASK_SWAP_WEAPON: preserve the engine's natural swap; no forced weapon
    -- selection, clip guessing, task cancellation or animation-rate write.
    local accepted=deps.advance_local_animation(ped,eligible)
    if current() then State.fast_hands_status=accepted and "UPDATE_REQUESTED" or "IDLE" end
end

local function reset_instant_switch()
    State.instant_switch_weapon, State.instant_switch_ped, State.instant_switch_identity = 0, nil, nil
end

local function instant_weapon_switch_tick(now)
    if not is_on("instant_weapon_switch") then reset_instant_switch();return end
    local generation = State.job_generation
    local ped=local_ped()
    local function identity()
        if State.job_generation ~= generation or local_ped() ~= ped then return nil end
        if not deps.GTA or type(deps.GTA.HandleToPointer) ~= "function" then return nil end
        local ok,address=pcall(function()
            local entity=deps.GTA.HandleToPointer(ped)
            return entity and entity:GetAddress()
        end)
        if ok and type(address)=="number" and address==address and address>0
            and address<math.huge and address%1==0 then return address end
    end
    if not entity_exists(ped) or entity_exists(local_vehicle()) then reset_instant_switch();return end
    local address=identity()
    if not address or type(deps.invoke_bool_detail)~="function" then reset_instant_switch();return end
    for _,query in ipairs({{H.IS_ENTITY_DEAD,false},{H.IS_PED_RAGDOLL},
            {H.IS_PED_RELOADING},{H.IS_PED_IN_COVER,false},{H.IS_PED_IN_ANY_VEHICLE,false}}) do
        if not query[1] then reset_instant_switch();return end
        local value,raw,err=deps.invoke_bool_detail(query[1],ped,table.unpack(query,2))
        if err or (type(raw)~="boolean" and type(raw)~="number") or value~=false then
            reset_instant_switch();return
        end
    end
    if type(deps.invoke_int_detail)~="function" then reset_instant_switch();return end
    local _,raw,err=deps.invoke_int_detail(H.GET_SELECTED_PED_WEAPON,ped)
    if err or type(raw)~="number" or raw~=raw or raw%1~=0
        or raw < -2147483648 or raw > 4294967295 then reset_instant_switch();return end
    local weapon=raw&0xFFFFFFFF
    if weapon==0 or identity()~=address then reset_instant_switch();return end
    if State.instant_switch_ped~=ped or State.instant_switch_identity~=address
        or not State.instant_switch_weapon or State.instant_switch_weapon==0 then
        State.instant_switch_ped,State.instant_switch_identity,State.instant_switch_weapon=ped,address,weapon
        return
    end
    if weapon~=State.instant_switch_weapon then
        State.instant_switch_weapon=weapon
        local function set(hash,...)
            if identity()~=address then reset_instant_switch();return false end
            return invoke_void(hash,...)
        end
        if not set(H.SET_PED_CAN_SWITCH_WEAPON,ped,true) then return end
        if not set(H.SET_CURRENT_PED_WEAPON,ped,weapon,true) then return end
        if not set(H.SET_PED_CURRENT_WEAPON_VISIBLE,ped,true,false,false,false) then return end
        -- Commit the selection without cancelling unrelated secondary tasks.
        if identity()==address then apply_weapon_transition_readiness(ped,true,set) end
    end
end

local function remove_all_local_weapons()
    local ped = local_ped()

    if not entity_exists(ped) then
        toast("Local ped is unavailable.")
        return false
    end

    -- Cancel any previously queued give/equip/component/tint work so it
    -- cannot recreate inventory after an explicit Remove All Weapons.
    State.job_generation =
        (tonumber(State.job_generation) or 0) + 1

    -- An explicit inventory clean is authoritative for this session.
    -- two automatic loadout sources and discard maintenance/snapshot state so an
    -- unload or later repair tick cannot silently recreate the removed weapons.
    set_toggle("auto_custom_loadout", false)
    State.active_custom_loadout_slot = 0
    State.custom_loadout_ped = 0
    State.loadout_respawn_due = 0
    State.loadout_verify_due = 0
    State.loadout_verify_attempts = 0
    State.session_weapon_keep = {}
    State.session_weapon_removed = {}
    State.session_component_targets = {}
    State.session_tint_targets = {}
    State.session_variant_overrides = {}
    State.variant_family_snapshots = {}
    State.session_weapon_drop_stats = {}
    clear_picker_equip()

    local unarmed = Utils.Joaat("weapon_unarmed")
    invoke_void(H.SET_CURRENT_PED_WEAPON, ped, unarmed, true)
    invoke_void(H.REMOVE_ALL_PED_WEAPONS, ped, true)
    invoke_void(H.SET_CURRENT_PED_WEAPON, ped, unarmed, true)

    State.last_weapon = unarmed & 0xFFFFFFFF
    WeaponCustomizer.has_weapon = false
    WeaponCustomizer.is_equipped = false
    WeaponCustomizer.installed = {}
    WeaponCustomizer.pending_components = {}
    WeaponCustomizer.dirty = true
    log_info("Removed all local ped weapons and cleared session loadout maintenance.")
    toast("Current weapon loadout cleared.")
    return true
end


local function imgui_clicked(method, ...)
    if not ImGui or type(ImGui[method]) ~= "function" then return false end
    local ok, result = pcall(ImGui[method], ...)
    return ok and result == true
end

local function ui_spacing(count)
    if not ImGui or type(ImGui.Spacing) ~= "function" then return end
    for _ = 1, count or 1 do pcall(ImGui.Spacing) end
end

local function soft_aim_requested()
    return not State.runtime_writes_suspended and not State.host_cleanup_done and is_on("near_miss_assist")
end
local function aim_settings()
    local function value(key, fallback)
        local feature = F[key]
        local ok, result = pcall(function() return feature and feature:GetFloatValue() end)
        return ok and type(result) == "number" and result or fallback
    end
    return { strength = value("aim_strength", 35.0), radius = value("aim_radius", 10.0) }
end
local SoftAimCamera = new_soft_aim_camera(deps, soft_aim_requested, aim_settings)

