local function fps_snapshot()
    local service = module_context and module_context.FPSLimiter
    if service and type(service.Snapshot) == "function" then return service.Snapshot() end
    return { phase = "unavailable", active = false, owned = false, busy = false,
        detail = "FPS limiter bridge is unavailable." }
end

local function fps_restore()
    local service = module_context and module_context.FPSLimiter
    if service and type(service.Restore) == "function" then return service.Restore() end
    return true
end

