local OWNED_TOGGLES = {
    "aggressive_world",
    "low_traffic", "low_peds", "disable_decals", "suppress_postfx",
    "freeze_clock", "skip_entry_cutscenes",
    "unlock_fps",
    "disable_tips_notifications", "first_person_pitch", "mute_traffic_ambience", "mute_npc_voices", "mute_active_sirens",
    "mute_tv_audio", "mute_phone_ringtone", "mute_environment_ambience", "mute_music",
}

local function feature_id(key)
    if not ID[key] then
        ID[key] = Utils.Joaat(FEATURE_ID_NAMESPACE .. tostring(key))
    end
    -- World registers before compat publishes its feature registry. Publish
    -- the canonical identity before the Public registration guard captures it.
    local cs = module_context and module_context.CScript
    if cs then
        cs.FeatureKeys = cs.FeatureKeys or {}
        local existing = cs.FeatureKeys[tostring(key)]
        assert(existing == nil or existing == ID[key], "World feature identity collision")
        cs.FeatureKeys[tostring(key)] = ID[key]
    end
    return ID[key]
end

local function invoke_native(kind, hash, ...)
    if not started or not current_callback(lifecycle) or lifecycle.gameplay_owner ~= true
        or lifecycle.failed == true then error("World native called outside its gameplay owner", 0) end
    local natives = module_context and module_context.Natives
    if not natives then error("World native adapter is unavailable", 0) end
    local accepted, value
    if type(natives.Try) == "function" then
        accepted, value = natives.Try(kind, hash, ...)
    elseif kind == "void" and type(natives.Void) == "function" then
        accepted, value = natives.Void(hash, ...)
    elseif kind == "int" and type(natives.Int) == "function" then
        accepted, value = true, natives.Int(hash, ...)
    elseif kind == "bool" and type(natives.Bool) == "function" then
        accepted, value = true, natives.Bool(hash, ...)
    end
    if accepted ~= true then
        error("World native failed at " .. tostring(hash) .. ": " .. tostring(value), 0)
    end
    if kind == "int" and (type(value) ~= "number" or value ~= value
        or value == math.huge or value == -math.huge or value % 1 ~= 0) then
        error("World native returned an invalid integer at " .. tostring(hash), 0)
    elseif kind == "bool" and type(value) ~= "boolean" then
        error("World native returned an invalid boolean at " .. tostring(hash), 0)
    end
    return value
end

local function invoke_void(hash, ...)
    return invoke_native("void", hash, ...)
end

local function invoke_int(hash, ...)
    return invoke_native("int", hash, ...)
end

local function invoke_bool(hash, ...)
    return invoke_native("bool", hash, ...)
end

local function now_ms()
    local value = invoke_int(H.GET_GAME_TIMER)
    if value > 0 then return value end
    return math.floor(os.clock() * 1000)
end

local function toast(message, duration)
    if module_context and module_context.Cherax and type(module_context.Cherax.Toast) == "function" then
        module_context.Cherax.Toast(message, duration or 4500, "CScript")
    end
end

local function log_entry(message)
    local logger = module_context and module_context.Logger
    if logger and type(logger.Info) == "function" then
        pcall(logger.Info, tostring(message), "World")
    end
end

-- BEGIN CLEAR AREA WORLD SCANNER
-- Only Cherax's locally streamed pools are visible here. One gameplay owner
-- scans and retries bounded identity records; no background tasks are created.
-- Players, vehicles carrying players and their occupants/attachments are excluded.
local ClearArea=(function()
    local M={}
    local H={
        EXISTS=0x7239B21A38F536BA,MODEL=0x9F47B058362C84B5,
        TYPE=0x8ACD366038D14505,NETWORKED=0xC7827959479DCC78,
        HAS_CONTROL=0x01BF60A500E28887,REQUEST_CONTROL=0xB69317BF5E782347,
        MAX_PASSENGERS=0xA7C4F2C6E744A550,SEAT=0xBB40DD2270B65366,
        IS_PLAYER_PED=0x12534C348C6CB68B,PLAYER_PED_ID=0xD80958FC74E988A6,
        PED_VEHICLE=0x9A9112A0FE9A4713,ATTACHED_TO=0x48C2BED9180FE123,
        MISSION=0xAD738C3085FE7E11,DELETE_VEHICLE=0xEA386986E786A54F,
        DELETE_OBJECT=0x539E0AE3E6634B9F,DELETE_PED=0x9614299DCB53E54B,
        DELETE_ENTITY=0xAE3CBE5BF394C9C9,
    }
    local defs={
        {key="vehicles",pool="GetVehicle",limit="GetMaxVehicleCount",entity_type=2,del=H.DELETE_VEHICLE},
        {key="objects",pool="GetObject",limit="GetMaxObjectCount",entity_type=3,del=H.DELETE_OBJECT},
        {key="peds",pool="GetPed",limit="GetMaxPedCount",entity_type=1,del=H.DELETE_PED},
    }
    local MAX_RECORDS,MAX_DELETE_ATTEMPTS,MAX_CONTROL_REQUESTS=8192,3,4
    local RETRY_MS,CONTROL_RETRY_MS,FINAL_VERIFY_MS=150,125,500
    local function new_state(generation)
        return {active=false,generation=generation or 0,status="Idle",reason="Idle",started=0,
            pass=1,max_passes=2,scanned=0,capacity=0,candidates=0,requested=0,verified_gone=0,
            pending=0,pending_confirmation=0,pending_control=0,cancelled_pending=0,
            remaining=0,failed=0,unverified=0,already_gone=0,protected=0,
            skipped_control=0,skipped_identity=0,skipped_replaced=0,skipped_player=0,
            skipped_current_vehicle=0,skipped_occupied=0,skipped_attachment=0,occupied_seen=0,
            control_requests=0,delete_attempts=0,native_errors=0,pool_read_errors=0,scan_limited=false,
            submitted_calls=0,failed_no_submission=0,failed_survived=0,failure_samples={},
            stage_errors={mission=0,allocation=0,write=0,typed=0,generic=0,control=0,free=0},
            by_type={vehicles={scanned=0,found=0,requested=0,verified=0},
                objects={scanned=0,found=0,requested=0,verified=0},
                peds={scanned=0,found=0,requested=0,verified=0}}}
    end
    local state=new_state()
    local pools,pool_cursor,seen={},1,{}
    local queue,queue_head,queue_tail,queue_count={},1,0,0
    local scan_finished,rescan_at=false,nil
    local function raw() return module_context and module_context.Raw end
    local function read(method,...)
        if type(method)~="function" then return nil end
        local ok,value=pcall(method,...)
        if ok then return value end
    end
    local function integer(value,minimum)
        return type(value)=="number" and value==value and value<math.huge
            and value%1==0 and value>=(minimum or 0)
    end
    local function bool(method,hash,...)
        local value=read(method,hash,...)
        if value==true or value==1 then return true end
        if value==false or value==0 then return false end
    end
    local function available(current)
        local n=current and current.Natives
        local m=current and current.Memory
        return n and type(n.InvokeBool)=="function" and type(n.InvokeInt)=="function"
            and type(n.InvokeVoid)=="function" and m and type(m.AllocInt)=="function"
            and type(m.WriteInt)=="function" and type(m.Free)=="function"
            and current.GTA and type(current.GTA.HandleToPointer)=="function"
            and current.PoolMgr
    end
    local function identity(current,handle,kind)
        if not integer(handle,1) then return nil,"identity" end
        local exists=bool(current.Natives.InvokeBool,H.EXISTS,handle)
        if exists==false then return nil,"absent" end
        if exists~=true then return nil,"identity" end
        local category=read(current.Natives.InvokeInt,H.TYPE,handle)
        if category~=kind.entity_type then return nil,"replaced" end
        local ptr=read(current.GTA.HandleToPointer,handle)
        local address=ptr and read(function()return ptr:GetAddress()end)
        local model=read(current.Natives.InvokeInt,H.MODEL,handle)
        if not integer(address,1) or not integer(model,-2147483648) then return nil,"identity" end
        return {handle=handle,address=address,model=model%4294967296,category=category}
    end
    local function player_context(current)
        local n=current.Natives
        local ped=read(n.InvokeInt,H.PLAYER_PED_ID)
        if not integer(ped,1) or bool(n.InvokeBool,H.EXISTS,ped)~=true then return nil end
        local vehicle=read(n.InvokeInt,H.PED_VEHICLE,ped,false)
        if not integer(vehicle,0) then return nil end
        return ped,vehicle
    end
    local function vehicle_block(current,handle,ownped,ownveh)
        if handle==ownveh then return "local_vehicle" end
        local n=current.Natives
        local maximum=read(n.InvokeInt,H.MAX_PASSENGERS,handle)
        if not integer(maximum,0) or maximum>31 then return "identity" end
        for seat=-1,maximum-1 do
            local passenger=read(n.InvokeInt,H.SEAT,handle,seat,false)
            if not integer(passenger,0) then return "identity" end
            if passenger==ownped then return "local_vehicle" end
            if passenger~=0 then
                local player=bool(n.InvokeBool,H.IS_PLAYER_PED,passenger)
                if player==true then return "occupied" end
                if player~=false then return "identity" end
            end
        end
    end
    local function ped_block(current,handle,ownped,ownveh)
        if handle==ownped then return "player" end
        local n=current.Natives
        local player=bool(n.InvokeBool,H.IS_PLAYER_PED,handle)
        if player==true then return "player" end
        if player~=false then return "identity" end
        local vehicle=read(n.InvokeInt,H.PED_VEHICLE,handle,false)
        if not integer(vehicle,0) then return "identity" end
        if vehicle~=0 then
            local blocked=vehicle_block(current,vehicle,ownped,ownveh)
            if blocked then return blocked=="identity" and blocked or "occupied" end
        end
    end
    local function protection(current,handle,kind)
        local ownped,ownveh=player_context(current)
        if not ownped then return "identity" end
        local blocked
        if kind.entity_type==2 then blocked=vehicle_block(current,handle,ownped,ownveh)
        elseif kind.entity_type==1 then blocked=ped_block(current,handle,ownped,ownveh) end
        if blocked then return blocked end
        -- Preserve attachments used by players or vehicles carrying players.
        -- Unknown/cyclic attachment chains are not safe to alter.
        local n=current.Natives
        local visited={[handle]=true}
        for _=1,6 do
            local attached=read(n.InvokeInt,H.ATTACHED_TO,handle)
            if not integer(attached,0) then return "identity" end
            if attached==0 then return nil end
            if visited[attached] or bool(n.InvokeBool,H.EXISTS,attached)~=true then return "identity" end
            visited[attached]=true
            local category=read(n.InvokeInt,H.TYPE,attached)
            if category==1 then blocked=ped_block(current,attached,ownped,ownveh)
            elseif category==2 then blocked=vehicle_block(current,attached,ownped,ownveh)
            elseif category~=3 then return "identity" end
            if blocked then return blocked=="identity" and blocked or "attachment" end
            handle=attached
        end
        return "identity"
    end
    local function authority(current,handle)
        local n=current.Natives
        local networked=bool(n.InvokeBool,H.NETWORKED,handle)
        if networked==false then return nil end
        if networked~=true then return "identity" end
        local controlled=bool(n.InvokeBool,H.HAS_CONTROL,handle)
        if controlled==true then return nil end
        return controlled==false and "control" or "identity"
    end
    local function live(record)
        return state.active and record.generation==state.generation and not record.done
    end
    local function note_error(record,stage,detail,fallback)
        if not live(record) then return end
        state.native_errors=state.native_errors+1
        state.stage_errors[stage]=state.stage_errors[stage]+1
        record.last_stage=stage
        local message=type(detail)=="string" and detail or fallback
        record.last_error=message:gsub("%c"," "):gsub("^.-:%d+: ",""):sub(1,120)
    end
    local function terminal_authority(current,record)
        local networked=bool(current.Natives.InvokeBool,H.NETWORKED,record.handle)
        if not live(record) then return nil end
        if networked==false then return "local" end
        if networked~=true then return "unreadable" end
        local controlled=bool(current.Natives.InvokeBool,H.HAS_CONTROL,record.handle)
        if not live(record) then return nil end
        if controlled==true then return "controlled" end
        return controlled==false and "no_control" or "unreadable"
    end
    local function check_identity(current,record)
        if not live(record) then return "cancelled" end
        local fresh,why=identity(current,record.handle,record.kind)
        if not fresh then return why end
        local original=record.original
        if fresh.address~=original.address or fresh.model~=original.model
            or fresh.category~=original.category then return "replaced" end
        if not live(record) then return "cancelled" end
    end
    local function validate(current,record)
        local why=check_identity(current,record)
        if why then return why end
        why=protection(current,record.handle,record.kind)
        if not live(record) then return "cancelled" end
        return why
    end
    local function mutation_guard(current,record)
        local why=validate(current,record) or authority(current,record.handle)
        if why then return why end
        -- Close the identity proof after the ownership/occupancy queries too.
        -- A host callback may have revoked this run or recycled its handle.
        return check_identity(current,record)
    end
    local function phase(record,value)
        if record.phase=="verify" then state.pending_confirmation=state.pending_confirmation-1 end
        if record.phase=="control" then state.pending_control=state.pending_control-1 end
        record.phase=value
        if value=="verify" then state.pending_confirmation=state.pending_confirmation+1 end
        if value=="control" then state.pending_control=state.pending_control+1 end
    end
    local function finish(record,why,observed_authority)
        if not live(record) then return end
        phase(record,nil);record.done=true;state.pending=state.pending-1
        if why=="absent" then
            if record.sent then
                state.verified_gone=state.verified_gone+1
                state.by_type[record.kind.key].verified=state.by_type[record.kind.key].verified+1
            else state.already_gone=state.already_gone+1 end
        elseif why=="control" then
            state.skipped_control=state.skipped_control+1;state.remaining=state.remaining+1
        elseif why=="failed" then
            state.failed=state.failed+1;state.remaining=state.remaining+1
            local calls=record.submitted_calls or 0
            local key=calls>0 and "failed_survived" or "failed_no_submission"
            state[key]=state[key]+1
            if #state.failure_samples<8 then
                state.failure_samples[#state.failure_samples+1]={kind=record.kind.key,
                    handle=record.handle,model=record.original.model,attempts=record.attempts,
                    submitted=record.sent==true,submitted_calls=calls,
                    last_stage=record.last_stage or (calls>0 and "verification" or "preparation"),
                    last_error=record.last_error,authority=observed_authority or "unreadable"}
            end
        elseif why=="identity" or why=="replaced" then
            local key=why=="replaced" and "skipped_replaced" or "skipped_identity"
            state[key]=state[key]+1;state.unverified=state.unverified+1
        else
            local key=({player="skipped_player",local_vehicle="skipped_current_vehicle",
                occupied="skipped_occupied",attachment="skipped_attachment"})[why]
            if key then
                state[key]=state[key]+1;state.protected=state.protected+1
                if why=="occupied" then state.occupied_seen=state.occupied_seen+1 end
            end
        end
    end
    local function push(record)
        queue_tail=queue_tail%MAX_RECORDS+1;queue[queue_tail]=record;queue_count=queue_count+1
    end
    local function pop()
        local record=queue[queue_head];queue[queue_head]=nil
        queue_head=queue_head%MAX_RECORDS+1;queue_count=queue_count-1
        return record
    end
    local function discard_work()
        queue,queue_head,queue_tail,queue_count={},1,0,0
        pools,pool_cursor,seen={},1,{}
        scan_finished,rescan_at=true,nil
    end
    local function stop(status,reason)
        state.cancelled_pending=state.cancelled_pending+state.pending
        state.pending,state.pending_confirmation,state.pending_control=0,0,0
        state.active=false;state.status=status;state.reason=reason
        state.generation=state.generation+1
        discard_work()
    end
    local function defer(record,now,waiting_control)
        if not live(record) then return end
        phase(record,waiting_control and "control" or (record.sent and "verify" or "retry"))
        record.next_at=now+(waiting_control and CONTROL_RETRY_MS
            or (record.attempts>=MAX_DELETE_ATTEMPTS and FINAL_VERIFY_MS or RETRY_MS))
    end
    local function submit(current,record,ptr,hash)
        local why=mutation_guard(current,record)
        if why then return why end
        -- Delete natives consume an in/out handle. Restore the original handle
        -- before EVERY call, including generic fallback after a typed delete.
        local ok,result=pcall(current.Memory.WriteInt,ptr,record.handle)
        if not live(record) then return "cancelled" end
        if not ok or result==false then
            note_error(record,"write",result,"Handle buffer write returned false");return "native"
        end
        why=mutation_guard(current,record)
        if why then return why end
        ok,result=pcall(current.Natives.InvokeVoid,hash,ptr)
        if not live(record) then return "cancelled" end
        state.delete_attempts=state.delete_attempts+1
        if not ok or result==false then
            note_error(record,hash==H.DELETE_ENTITY and "generic" or "typed",result,
                "Deletion call returned false");return "native"
        end
        record.submitted_calls=(record.submitted_calls or 0)+1
        state.submitted_calls=state.submitted_calls+1
        if not record.sent then
            record.sent=true;state.requested=state.requested+1
            local row=state.by_type[record.kind.key];row.requested=row.requested+1
        end
    end
    local function step(current,record,now)
        local why=validate(current,record)
        if why then finish(record,why);return end
        if record.attempts>=MAX_DELETE_ATTEMPTS then
            local observed=terminal_authority(current,record)
            if not live(record) then return end
            local final=check_identity(current,record)
            if final then finish(record,final) else finish(record,"failed",observed) end
            return
        end
        why=authority(current,record.handle)
        if why=="control" then
            if record.control_attempts>=MAX_CONTROL_REQUESTS then finish(record,"control");return end
            -- A normal request is bounded and occurs only after all identity,
            -- player/occupancy and attachment guards pass. Never force ownership.
            why=validate(current,record) or check_identity(current,record)
            if why then finish(record,why);return end
            record.control_attempts=record.control_attempts+1
            local called,result=pcall(current.Natives.InvokeBool,H.REQUEST_CONTROL,record.handle)
            if not live(record) then return end
            state.control_requests=state.control_requests+1
            if not called or (result~=true and result~=false and result~=0 and result~=1) then
                note_error(record,"control",result,"Control request returned no boolean result")
            end
            defer(record,now,true);return
        elseif why then finish(record,why);return end
        record.attempts=record.attempts+1
        why=mutation_guard(current,record)
        if why then
            if why=="control" then defer(record,now,true) else finish(record,why) end
            return
        end
        local marked,result=pcall(current.Natives.InvokeVoid,H.MISSION,record.handle,true,true)
        if not live(record) then return end
        if not marked or result==false then
            note_error(record,"mission",result,"Mission preparation returned false");defer(record,now);return
        end
        why=mutation_guard(current,record)
        if why then
            if why=="control" then defer(record,now,true) else finish(record,why) end
            return
        end
        local allocated,ptr=pcall(current.Memory.AllocInt)
        if not live(record) then
            if allocated and integer(ptr,1) then pcall(current.Memory.Free,ptr) end
            return
        end
        if not allocated or not integer(ptr,1) then
            note_error(record,"allocation",ptr,"Allocation returned no valid buffer");defer(record,now);return
        end
        why=submit(current,record,ptr,record.kind.del)
        if live(record) then
            local after=validate(current,record)
            if after then why=after
            elseif why==nil or why=="native" then
                -- Wrecked vehicles need the same controlled generic fallback
                -- already intended for props/peds; fresh guards and buffer apply.
                why=submit(current,record,ptr,H.DELETE_ENTITY)
            end
        end
        local freed,free_result=pcall(current.Memory.Free,ptr)
        if not live(record) then return end
        if not freed or free_result==false then
            note_error(record,"free",free_result,"Cleanup buffer release returned false")
            stop("UNAVAILABLE","Stopped because a cleanup buffer could not be released")
            return
        end
        local after=validate(current,record)
        if after then finish(record,after)
        elseif why=="control" then defer(record,now,true)
        elseif why and why~="native" then finish(record,why)
        else defer(record,now) end
    end
    local function next_slot(now)
        if scan_finished then return nil end
        if rescan_at then
            if now<rescan_at then return nil end
            rescan_at=nil;state.pass=state.pass+1;pool_cursor=1
            for _,pool in ipairs(pools) do pool.cursor=0 end
        end
        for _=1,#pools do
            local pool=pools[pool_cursor];pool_cursor=pool_cursor%#pools+1
            if pool.cursor<pool.capacity then
                local slot=pool.cursor;pool.cursor=slot+1
                return pool,slot
            end
        end
        if state.pass<state.max_passes then rescan_at=now+175
        else scan_finished=true end
    end
    function M.Start()
        if state.active then return false,"A cleanup pass is already active." end
        state=new_state(state.generation+1);discard_work();scan_finished=false
        local generation=state.generation
        local current=raw()
        if not available(current) then
            stop("UNAVAILABLE","Required Cherax entity APIs unavailable.")
            return false,state.reason
        end
        for _,kind in ipairs(defs) do
            local count=read(current.PoolMgr[kind.limit])
            if state.generation~=generation then return false,"Cleanup owner changed during setup." end
            if not integer(count,0) or count>65536 or type(current.PoolMgr[kind.pool])~="function" then
                stop("UNAVAILABLE","Missing or invalid "..kind.key.." pool API.")
                return false,state.reason
            end
            pools[#pools+1]={kind=kind,cursor=0,capacity=count}
            state.capacity=state.capacity+count
        end
        local started_at=now_ms()
        if state.generation~=generation then return false,"Cleanup owner changed during setup." end
        state.active=true;state.started=started_at;state.status="SCANNING"
        state.reason="Scanning streamed vehicles, objects and NPC peds"
        return true
    end
    function M.Requested() return state.active==true end
    function M.Snapshot()
        local snapshot={}
        for key,value in pairs(state) do if type(value)~="table" then snapshot[key]=value end end
        snapshot.stage_errors={}
        for key,value in pairs(state.stage_errors) do snapshot.stage_errors[key]=value end
        snapshot.failure_samples={}
        for index,item in ipairs(state.failure_samples) do
            local copy={};for key,value in pairs(item) do copy[key]=value end
            snapshot.failure_samples[index]=copy
        end
        snapshot.by_type={}
        for key,row in pairs(state.by_type) do
            local copy={};for field,value in pairs(row) do copy[field]=value end
            snapshot.by_type[key]=copy
        end
        return snapshot
    end
    function M.Cancel(why) stop("STOPPED",tostring(why or "Cancelled")) end
    function M.Tick()
        if not state.active then return false end
        local generation=state.generation
        local current=raw()
        if not available(current) then stop("UNAVAILABLE","Entity APIs became unavailable.");return true end
        local now=now_ms()
        if not state.active or state.generation~=generation then return true end
        if now<state.started then stop("STOPPED","Game timer changed during cleanup");return true end
        if now-state.started>=30000 then
            stop("TIMED_OUT","Stopped at the 30-second cleanup budget");return true
        end
        local visited,operations=0,0
        local waiting=queue_count
        while waiting>0 and visited<36 and operations<3 and state.active do
            if visited>0 then
                local clock=now_ms()
                if not state.active or state.generation~=generation then return true end
                if clock-now>=3 then break end
            end
            waiting=waiting-1;visited=visited+1
            local record=pop()
            if now>=record.next_at then operations=operations+1;step(current,record,now) end
            if not state.active or state.generation~=generation then return true end
            if not record.done then push(record) end
        end
        while visited<36 and operations<3 and state.active do
            if visited>0 then
                local clock=now_ms()
                if not state.active or state.generation~=generation then return true end
                if clock-now>=3 then break end
            end
            local pool,slot=next_slot(now)
            if not pool then break end
            visited=visited+1;state.scanned=state.scanned+1
            local kind=pool.kind;local row=state.by_type[kind.key];row.scanned=row.scanned+1
            local handle=read(current.PoolMgr[kind.pool],slot)
            if not state.active or state.generation~=generation then return true end
            if not integer(handle,0) then state.pool_read_errors=state.pool_read_errors+1 end
            if integer(handle,1) and not seen[handle] then
                if state.candidates>=MAX_RECORDS then
                    state.scan_limited=true;scan_finished=true;break
                end
                -- A handle is considered once per operation, even across the
                -- second scan. Replacements cannot inherit a stale retry.
                seen[handle]=true;operations=operations+1
                state.candidates=state.candidates+1;row.found=row.found+1
                local proof,why=identity(current,handle,kind)
                if not state.active or state.generation~=generation then return true end
                local record={handle=handle,kind=kind,original=proof,generation=generation,
                    attempts=0,control_attempts=0,next_at=now}
                state.pending=state.pending+1
                if proof then step(current,record,now) else finish(record,why) end
                if not state.active or state.generation~=generation then return true end
                if not record.done then push(record) end
            end
        end
        if scan_finished and state.pending==0 then
            local partial=state.remaining>0 or state.unverified>0 or state.pool_read_errors>0 or state.scan_limited
            stop(partial and "PARTIAL" or "COMPLETE",state.scan_limited
                and "Stopped scanning at the bounded entity limit"
                or (partial and "Finished; some entities remain or could not be verified"
                    or "Streamed cleanup and deletion checks finished"))
            return true
        end
        state.status=not scan_finished and "SCANNING"
            or (state.pending_control>0 and "WAITING_CONTROL" or "VERIFYING")
        return false
    end
    return M
end)()
-- END CLEAR AREA WORLD SCANNER

local function feature_ref(key)
    if F[key] then return F[key] end
    if FeatureMgr and type(FeatureMgr.GetFeature) == "function" then
        local ok, feature = pcall(FeatureMgr.GetFeature, feature_id(key))
        if ok then return feature end
    end
    return nil
end

local function is_on(key)
    if F[key] then return ToggleState[key] == true end
    local feature = feature_ref(key)
    if not feature or type(feature.IsToggled) ~= "function" then return false end
    local ok, enabled = pcall(function() return feature:IsToggled() end)
    return ok and enabled == true
end

local function set_toggle(key, enabled)
    local feature = feature_ref(key)
    if not feature then return false end
    local wanted = enabled == true
    if F[key] then ToggleState[key] = wanted end
    local ok = pcall(function()
        if feature:IsToggled() ~= wanted then feature:Toggle(wanted) end
    end)
    return ok
end

-- Reflect bridge status without queuing a user disable that would erase its
-- rejection/restore-failure detail on the following scheduler tick.
local function sync_fps_toggle(enabled)
    syncing_fps_toggle = true
    local ok = set_toggle("unlock_fps", enabled)
    syncing_fps_toggle = false
    return ok
end

local function restore_fps_unlock()
    -- Revoke an enable that has not reached the bridge as well as its active
    -- lease, including when an unrelated runtime domain aborts a reset chain.
    if lifecycle then lifecycle.pending.unlock_fps = nil end
    sync_fps_toggle(false)
    return fps_restore()
end

local function slider_int(key, fallback)
    local feature = feature_ref(key)
    if not feature then return fallback end
    local ok, value = pcall(function() return feature:GetIntValue() end)
    return ok and type(value) == "number" and value or fallback
end


local function add_toggle(key, name, description, default, callback)
    ToggleState[key] = default == true
    local token = lifecycle
    local function on_toggle(feature)
        if not current_callback(token) then return end
        local ok, enabled = pcall(function() return feature:IsToggled() end)
        local changed = ok and ToggleState[key] ~= (enabled == true)
        if ok then ToggleState[key] = enabled == true end
        -- A deferred acknowledgement of our own FPS checkbox reset must not
        -- enqueue another disable and erase the bridge's rejection details.
        if callback and (key ~= "unlock_fps" or changed) then callback(feature) end
    end
    local feature = FeatureMgr.AddFeature(
        feature_id(key), name, eFeatureType.Toggle, description or "", on_toggle
    )
    if feature and type(feature.SetDefaultValue) == "function" then
        pcall(function()
            feature:SetDefaultValue(default == true)
            if default == true and type(feature.Toggle) == "function" and not feature:IsToggled() then
                feature:Toggle(true)
            end
        end)
    end
    F[key] = feature
    if feature then
        local ok, enabled = pcall(function() return feature:IsToggled() end)
        if ok then ToggleState[key] = enabled == true end
        State.registered_count = State.registered_count + 1
    end
    return feature
end

local function add_button(key, name, description, callback)
    local token = lifecycle
    local function on_press(...)
        if not started or not current_callback(token) then return false end
        return callback(...)
    end
    local feature = FeatureMgr.AddFeature(
        feature_id(key), name, eFeatureType.Button, description or "", on_press
    )
    F[key] = feature
    if feature then State.registered_count = State.registered_count + 1 end
    return feature
end

local function add_slider_int(key, name, description, minimum, maximum, step, default)
    local feature = FeatureMgr.AddFeature(
        feature_id(key), name, eFeatureType.SliderInt, description or ""
    )
    if feature then
        pcall(function()
            local initial = default or minimum
            feature:SetLimitValues(minimum, maximum)
            feature:SetStepSize(step or 1)
            feature:SetDefaultValue(initial)
            if type(feature.SetIntValue) == "function" then feature:SetIntValue(initial) end
        end)
        State.registered_count = State.registered_count + 1
    end
    F[key] = feature
    return feature
end



local WEATHER_PRESETS = {
    EXTRASUNNY = true, CLEAR = true, CLOUDS = true, OVERCAST = true,
    RAIN = true, THUNDER = true, FOGGY = true, SNOW = true, XMAS = true,
}

local function weather_snapshot()
    return {
        active = State.weather_override ~= nil,
        preset = State.weather_override,
        presets = { "EXTRASUNNY", "CLEAR", "CLOUDS", "OVERCAST", "RAIN", "THUNDER", "FOGGY", "SNOW", "XMAS" },
        local_only = true,
    }
end

local function apply_weather(name)
    name = tostring(name or ""):upper()
    if not WEATHER_PRESETS[name] then
        return false, "Choose a supported local weather preset."
    end
    if not queue_command("weather", name) then return false, "World runtime is stopped." end
    State.weather_override = name
    toast("Local weather selected: " .. name .. ".")
    return true, "Local weather override selected."
end

local function clear_weather()
    if not queue_command("weather", false) then return false, "World runtime is stopped." end
    State.weather_override = nil
    toast("Local weather reset requested.")
    return true, "Local weather reset requested."
end

local function stop_visual_effects_now()
    invoke_void(H.CLEAR_TIMECYCLE_MODIFIER)
    invoke_void(H.CLEAR_EXTRA_TIMECYCLE_MODIFIER)
    invoke_bool(H.TRIGGER_SCREENBLUR_FADE_OUT, 0.0)
    invoke_void(H.STOP_GAMEPLAY_CAM_SHAKING, true)
    invoke_void(H.ANIMPOSTFX_STOP_ALL)
end

local function stop_visual_effects()
    return queue_command("stop_visual_effects", true)
end

local function current_local_interior()
    local ped = invoke_int(H.PLAYER_PED_ID)
    if ped == 0 or not invoke_bool(H.DOES_ENTITY_EXIST, ped) then return 0, 0 end
    return invoke_int(H.GET_INTERIOR_FROM_ENTITY, ped), ped
end

local function screen_is_dark()
    return invoke_bool(H.IS_SCREEN_FADED_OUT) or invoke_bool(H.IS_SCREEN_FADING_OUT)
end

local function cancel_entry_suppression(reason)
    local state = State.cutscene_skip
    if state.phase == "idle" then return false end
    -- Consume fade ownership before a fallible native so cancellation cannot
    -- re-enter the same cleanup after an error or a second callback.
    local fade_owned = state.fade_owned == true
    state.fade_owned = false
    if fade_owned and screen_is_dark() then invoke_void(H.DO_SCREEN_FADE_IN, 250) end
    log_entry(("EntrySkip phase=cancelled reason=%s origin=%d destination=%d elapsed=%dms"):format(
        tostring(reason or "reset"), tonumber(state.origin_interior) or 0,
        tonumber(state.destination_interior) or 0,
        math.max(0, now_ms() - (tonumber(state.entry_started_ms) or now_ms()))))
    state.phase = "idle"
    state.signal_started_ms = -100000
    state.origin_interior = 0
    state.destination_interior = 0
    state.entry_started_ms = -100000
    state.entry_deadline_ms = -100000
    state.destination_ready_ms = -100000
    state.fade_owned = false
    state.camera_suppressed = false
    return true
end

local function reset_cutscene_skip_tracking()
    local previous = State.cutscene_skip or new_cutscene_skip_state()
    local count = tonumber(previous.count) or 0
    local last_kind = tostring(previous.last_kind or "None")
    local last_detail = tostring(previous.last_detail or "No cutscene or entry transition has been skipped.")
    local last_action_ms = tonumber(previous.last_action_ms) or -100000
    local interior = current_local_interior()
    State.cutscene_skip = new_cutscene_skip_state()
    State.cutscene_skip.initialized = true
    State.cutscene_skip.last_interior = interior
    State.cutscene_skip.count = count
    State.cutscene_skip.last_kind = last_kind
    State.cutscene_skip.last_detail = last_detail
    State.cutscene_skip.last_action_ms = last_action_ms
end

-- Native stop requests are asynchronous. Keep their receipt until playback ends;
-- an accepted Void call is not completion. None of this owns a property camera,
-- collision/placement, tasks, control, or the property's script state machine.
local CUTSCENE_DEADLINE_MS = 2600
local CUTSCENE_MAX_SAMPLE_GAP_MS = 250
-- These are native cutscene asset names, not ordinary hangar-entry protocols.
-- HAS_THIS_CUTSCENE_LOADED is only a cancellation hint. It cannot identify a
-- playback instance; even identical names/timelines cannot authorize a retry.
local CUTSCENE_NAMES = { "HANG_INT", "HANG_INT_PLANE" }

local function cutscene_sample(ped, now)
    local name
    for _, candidate in ipairs(CUTSCENE_NAMES) do
        if invoke_bool(H.HAS_THIS_CUTSCENE_LOADED, candidate) then
            if name then name = nil; break end -- Ambiguous loaded asset set.
            name = candidate
        end
    end
    return { ped = ped, model = invoke_int(H.GET_ENTITY_MODEL, ped),
        name = name, time = invoke_int(H.GET_CUTSCENE_TIME),
        duration = invoke_int(H.GET_CUTSCENE_TOTAL_DURATION),
        section = invoke_int(H.GET_CUTSCENE_SECTION_PLAYING), at = now }
end

local cutscene_cancel
local function cutscene_receipt_current(state, pending)
    if not pending or not started or not current_callback(lifecycle)
        or not is_on("skip_entry_cutscenes") or state ~= State.cutscene_skip
        or state.native_pending ~= pending or pending.epoch ~= lifecycle_epoch
        or pending.request_epoch ~= cutscene_request_epoch then return false end
    local ped = invoke_int(H.PLAYER_PED_ID)
    if ped ~= pending.sample.ped or ped == 0 or not invoke_bool(H.DOES_ENTITY_EXIST, ped)
        or invoke_bool(H.IS_ENTITY_DEAD, ped, false)
        or pending.sample.model ~= invoke_int(H.GET_ENTITY_MODEL, ped) then return false end
    return started and current_callback(lifecycle) and is_on("skip_entry_cutscenes")
        and state == State.cutscene_skip and state.native_pending == pending
        and pending.epoch == lifecycle_epoch and pending.request_epoch == cutscene_request_epoch
end

local function cutscene_finish(state)
    local pending = state.native_pending
    if not cutscene_receipt_current(state, pending) then
        cutscene_cancel(state, "Character or request changed before completion observation")
        return
    end
    state.native_pending = nil
    state.native_blocked = true -- Must observe an inactive boundary before rearming.
    if not pending or pending.accepted ~= true then return end
    state.native_status, state.playback_ended = "PLAYBACK_ENDED", true
    state.last_kind = "Cutscene stopped"
    state.last_detail = "Playback became inactive after the stop request. Unique scene completion, causation and property placement are not verified."
    state.count = (tonumber(state.count) or 0) + 1
    log_entry(("CutsceneSkip status=PLAYBACK_ENDED requests=%d property_completed=false"):format(pending.requests))
end

cutscene_cancel = function(state, reason, status)
    state.native_pending = nil
    state.native_blocked = true
    state.native_status = status or "CANCELLED"
    state.last_kind = status == "TIMEOUT" and "Cutscene stop timed out" or "Cutscene request cancelled"
    state.last_detail = reason .. ". No further stop request will be sent until playback becomes inactive."
    log_entry("CutsceneSkip status=" .. state.native_status .. " reason=" .. reason)
end

local function cutscene_request(state, pending, now)
    -- Sampling can call into the host. Revalidate after all sample reads and
    -- immediately before submission, including off/on during a yielded call.
    if not started or not current_callback(lifecycle) or not is_on("skip_entry_cutscenes")
        or state ~= State.cutscene_skip or state.native_pending ~= pending
        or pending.epoch ~= lifecycle_epoch or pending.request_epoch ~= cutscene_request_epoch then
        cutscene_cancel(state, "Cutscene request revoked before submission")
        return
    end
    local ped = invoke_int(H.PLAYER_PED_ID)
    if ped ~= pending.sample.ped or ped == 0 or not invoke_bool(H.DOES_ENTITY_EXIST, ped)
        or invoke_bool(H.IS_ENTITY_DEAD, ped, false)
        or pending.sample.model ~= invoke_int(H.GET_ENTITY_MODEL, ped) then
        cutscene_cancel(state, "Character changed before submission")
        return
    end
    if not (invoke_bool(H.IS_CUTSCENE_ACTIVE) or invoke_bool(H.IS_CUTSCENE_PLAYING)) then
        cutscene_cancel(state, "Playback ended before submission")
        return
    end
    if not is_on("skip_entry_cutscenes") or pending.request_epoch ~= cutscene_request_epoch then
        cutscene_cancel(state, "Cutscene request revoked at submission")
        return
    end
    pending.requests = pending.requests + 1
    pending.last_request_ms = now
    state.native_requests = pending.requests
    state.last_action_ms = now
    local stop_result = invoke_void(H.STOP_CUTSCENE_IMMEDIATELY)
    if not cutscene_receipt_current(state, pending) then
        cutscene_cancel(state, "Character or request changed during stop submission")
        return
    end
    if stop_result == false then
        state.native_pending, state.native_blocked = nil, true
        state.native_status = "REJECTED"
        state.last_kind = "Cutscene skip rejected"
        state.last_detail = "The native cutscene-stop request was rejected; no completion was recorded."
        return
    end
    pending.accepted = true
    state.native_status = "REQUEST_ACCEPTED"
    state.last_kind = "Cutscene skip requested"
    state.last_detail = "GTA accepted the stop request; waiting for playback to end."
    log_entry(("CutsceneSkip status=REQUEST_ACCEPTED request=%d named_asset=%s"):format(pending.requests, tostring(pending.sample.name or "unknown")))
    if not (invoke_bool(H.IS_CUTSCENE_ACTIVE) or invoke_bool(H.IS_CUTSCENE_PLAYING)) then
        cutscene_finish(state)
    end
end

local function cutscene_skip_tick()
    local state = State.cutscene_skip
    local request_epoch = cutscene_request_epoch
    local now = now_ms()
    local interior, ped = current_local_interior()
    if ped == 0 or invoke_bool(H.IS_ENTITY_DEAD, ped, false) then
        cancel_entry_suppression("local ped unavailable")
        if state.native_pending then cutscene_cancel(state, "Local character unavailable") end
        state.initialized = false
        return
    end
    state.initialized, state.last_interior = true, interior
    if state.phase ~= "idle" then cancel_entry_suppression("unrecognized entry ownership") end
    local active = invoke_bool(H.IS_CUTSCENE_ACTIVE) or invoke_bool(H.IS_CUTSCENE_PLAYING)
    -- An MP presentation flag does not prove a native cutscene or give this Lua
    -- ownership of the property controller. Failed observation stays UNKNOWN.
    local mp_ok, mp = pcall(invoke_bool, H.NETWORK_IS_IN_MP_CUTSCENE)
    state.mp_status = not mp_ok and "UNKNOWN" or (mp and "ACTIVE" or "INACTIVE")
    local kind = active and "NATIVE_CUTSCENE"
        or (PropertyEntry.pending and "PROPERTY_CONTROLLER")
        or (EntrySkip.pending and "SIMPLE_INTERIOR_CONTROLLER")
        or (mp_ok and mp and "MP_PRESENTATION_UNRESOLVED")
        or (not mp_ok and "MP_STATE_UNKNOWN") or "NONE"
    state.presentation_kind = kind
    state.mp_detail = kind == "MP_PRESENTATION_UNRESOLVED"
        and "MP flag is active without native playback or a recognized entry owner; no generic release write was attempted."
        or kind == "MP_STATE_UNKNOWN" and "MP state read failed; no completion or state release is inferred."
        or "Native playback and source-backed property controllers are handled separately."
    if not active then
        local pending = state.native_pending
        if pending then
            if pending.sample.ped ~= ped or pending.sample.model ~= invoke_int(H.GET_ENTITY_MODEL, ped)
                or pending.epoch ~= lifecycle_epoch or pending.request_epoch ~= cutscene_request_epoch or now < pending.sample.at
                or now - pending.sample.at > CUTSCENE_MAX_SAMPLE_GAP_MS then
                cutscene_cancel(state, "Character, lifecycle or observation continuity changed")
            else cutscene_finish(state) end
        end
        state.native_blocked = false
        return
    end
    if state.native_blocked then return end
    local sample = cutscene_sample(ped, now)
    local pending = state.native_pending
    if not pending then
        pending = { sample = sample, epoch = lifecycle_epoch, request_epoch = request_epoch, started_ms = now,
            last_request_ms = now, requests = 0, accepted = false }
        state.native_pending = pending
        state.playback_ended, state.property_completed = false, false
        cutscene_request(state, pending, now)
        return
    end
    local previous, elapsed = pending.sample, now - pending.sample.at
    if pending.epoch ~= lifecycle_epoch or pending.request_epoch ~= cutscene_request_epoch
        or previous.ped ~= sample.ped or previous.model ~= sample.model
        or elapsed < 0 or elapsed > CUTSCENE_MAX_SAMPLE_GAP_MS
        or sample.time < previous.time or sample.time - previous.time > elapsed + 250
        or sample.duration ~= previous.duration or sample.section ~= previous.section
        or sample.name ~= previous.name then
        cutscene_cancel(state, "Scene, character or playback continuity changed")
        return
    end
    pending.sample = sample
    if now - pending.started_ms >= CUTSCENE_DEADLINE_MS then
        cutscene_cancel(state, "Playback remained active after the bounded observation window", "TIMEOUT")
        return
    end
    -- Playback name/time cannot identify a unique scene instance. Observe until
    -- the deadline without retrying STOP, which could stop a replacement scene.
end

-- Enhanced 1158.13 simple-interior entry via AM_MP_SMPL_INTERIOR_EXT.
-- Global_1951218.f_5402 == active property makes func_1917(property) true,
-- suppressing the fade in func_7367 and allowing func_7067 to transfer at phase 10.
-- SET_NO_LOADING_SCREEN and Global_1951218 bit 0 follow GTA's loading-screen
-- ownership contract and are consumed/restored by its cleanup. Admission requires
-- one controller, a stable property/family/entrance descriptor, phase 2, no
-- presentation resources, and exact readback. Clear descriptor bit 6 only if set.
-- Controller phases, completion flags, interior IDs, coordinates, cameras, and
-- player state remain GTA-owned. Bespoke interior controllers are unsupported.
local ENTRY_EXT, ENTRY_INT, ENTRY_ROOT = 3769087917, 93794601, 1951218
local PROPERTY_EXT, PROPERTY_INT = 1928202738, 2511739708 -- am_mp_property_ext / am_mp_property_int
local ENTRY_DIRECT_MARKER = ENTRY_ROOT + 5402
local ENTRY_LOADING_FLAGS = ENTRY_ROOT
local ARRIVAL_PRESENTATION_FAMILIES = {[4]=true,[9]=true,[20]=true} -- bunker / facility / submarine
local ENTRY_DIRECT_EXCLUDED_FAMILIES = {[35]="mansion/property family uses a bespoke arrival controller"}
local ARRIVAL_CAMERA_BANKS = {ENTRY_ROOT+4326+387, ENTRY_ROOT+4761+387}
local function entry_integer(v,lo,hi)
    return type(v)=="number" and v==v and v%1==0 and v>=lo and v<=hi
end
local function entry_api_ready()
    return Memory and type(Memory.GetBaseAddress)=="function" and type(Memory.ReadUInt)=="function"
        and type(Memory.ReadUShort)=="function" and ScriptLocal and type(ScriptLocal.GetPtr)=="function"
        and type(ScriptLocal.GetInt)=="function" and type(ScriptLocal.SetInt)=="function"
        and ScriptGlobal and type(ScriptGlobal.GetInt)=="function" and type(ScriptGlobal.SetInt)=="function"
        and type(ScriptGlobal.AreValid)=="function"
end
local function entry_image()
    -- A PE64 header is not a script-layout version. Gate script-local/global
    -- interpretation independently; ordinary native-cutscene STOP stays separate.
    local natives=module_context and module_context.Natives
    local version_ok,version=false,nil
    if natives and type(natives.Try)=="function" then
        version_ok,version=natives.Try("string",0xFCA9373EF340AC0A)
    elseif natives and type(natives.String)=="function" then
        version_ok,version=true,natives.String(0xFCA9373EF340AC0A)
    end
    if version_ok~=true or version~="1.73" then return false end
    local base=Memory.GetBaseAddress("GTA5_Enhanced.exe")
    if not entry_integer(base,65536,0x00007FFFFFFFEFFF) or base%4096~=0 then return false end
    if Memory.ReadUShort(base)~=0x5A4D then return false end
    local offset=Memory.ReadUInt(base+0x3C)
    if not entry_integer(offset,64,1024) then return false end
    local pe=base+offset
    if Memory.ReadUInt(pe)~=0x4550 or Memory.ReadUShort(pe+4)~=0x8664
        or Memory.ReadUShort(pe+24)~=0x20B then return false,base end
    local image_size=Memory.ReadUInt(pe+24+56)
    if not entry_integer(image_size,32*1024*1024,256*1024*1024) then return false,base end
    return true,base
end
local function entry_read(hash,index)
    local v=ScriptLocal.GetInt(hash,index)
    if not entry_integer(v,-2147483648,4294967295) then error("invalid entry local read",0) end
    return v
end
local function entry_global(index)
    local v=ScriptGlobal.GetInt(index)
    if not entry_integer(v,-2147483648,4294967295) then error("invalid entry global read",0) end
    return v
end
local function entry_set_global(index,value)
    local ok,result=pcall(ScriptGlobal.SetInt,index,value)
    return ok and result~=false
end
local function entry_threads(hash) return invoke_int(0x2C83A9DA6BFFC4F9,hash) end
local function entry_pointer(hash,root)
    local p=ScriptLocal.GetPtr(hash,root)
    if not entry_integer(p,65536,0x00007FFFFFFFEFFF) or p%8~=0 then return nil end
    return p
end
local function entry_context()
    if not started or not current_callback(lifecycle) or lifecycle.gameplay_owner~=true then return nil end
    if not invoke_bool(0xD83C2B94E7508980) or invoke_bool(0x68049AEFF83D8F0A)
        or ScriptGlobal.AreValid()~=true then return nil end
    local ped=invoke_int(H.PLAYER_PED_ID)
    if ped<=0 or not invoke_bool(H.DOES_ENTITY_EXIST,ped) or invoke_bool(H.IS_ENTITY_DEAD,ped,false) then return nil end
    return {ped=ped,model=invoke_int(H.GET_ENTITY_MODEL,ped)}
end
local function entry_ext_snapshot()
    if entry_threads(ENTRY_EXT)~=1 then return nil end
    local ptr=entry_pointer(ENTRY_EXT,245)
    if not ptr then return nil end
    local s={ptr=ptr,property=entry_read(ENTRY_EXT,246),family=entry_read(ENTRY_EXT,247),
        phase=entry_read(ENTRY_EXT,786),entrance=entry_read(ENTRY_EXT,728),
        descriptor=entry_read(ENTRY_EXT,729),descriptor_entrance=entry_read(ENTRY_EXT,730),
        flags=entry_read(ENTRY_EXT,732),presentation=entry_read(ENTRY_EXT,257),
        progress=entry_read(ENTRY_EXT,458),view=entry_read(ENTRY_EXT,268),
        camera=entry_global(ENTRY_ROOT+4326+386),shots=entry_global(ENTRY_ROOT+4326+372)}
    if entry_pointer(ENTRY_EXT,245)~=ptr or entry_threads(ENTRY_EXT)~=1 then return nil end
    return s
end
local function entry_identity(a,b)
    return a and b and a.ptr==b.ptr and a.property==b.property and a.family==b.family
        and a.entrance==b.entrance and a.descriptor==b.descriptor and a.descriptor_entrance==b.descriptor_entrance
end
local function entry_before_presentation(s)
    return s and entry_integer(s.property,1,4095) and entry_integer(s.family,0,63)
        and entry_integer(s.entrance,0,63)
        and s.descriptor==s.property and s.descriptor_entrance==s.entrance and s.phase==2
        and s.presentation==0 and s.progress==0 and s.view==0 and s.camera==0 and s.shots==0
        and entry_integer(s.flags,0,0x7FFFFFFF)
end

local function entry_release_direct(pending,reason)
    if not pending or pending.direct_released or not (pending.direct_armed or pending.direct_marker_owned
        or pending.loading_bit_owned or pending.no_loading_owned) then return true end
    local marker_ok,bit_ok,noload_ok=true,true,true
    local ok=pcall(function()
        if not entry_api_ready() or ScriptGlobal.AreValid()~=true or pending.lifecycle~=lifecycle_epoch then
            marker_ok,bit_ok,noload_ok=false,false,false
            return
        end
        local image,base=entry_image()
        local subject=entry_context()
        if not image or base~=pending.base or not subject
            or subject.ped~=pending.ped or subject.model~=pending.model then
            marker_ok,bit_ok,noload_ok=false,false,false
            return
        end
        local marker=entry_global(ENTRY_DIRECT_MARKER)
        if marker==pending.before.property then
            marker_ok=entry_set_global(ENTRY_DIRECT_MARKER,pending.direct_marker_before)
                and entry_global(ENTRY_DIRECT_MARKER)==pending.direct_marker_before
        elseif marker~=pending.direct_marker_before then
            marker_ok=false
        end
        local flags=entry_global(ENTRY_LOADING_FLAGS)
        if pending.loading_bit_owned and (flags & 1)~=0 then
            local target=flags & (~1)
            bit_ok=entry_set_global(ENTRY_LOADING_FLAGS,target)
                and (entry_global(ENTRY_LOADING_FLAGS) & 1)==0
        end
        if pending.no_loading_owned and invoke_bool(H.GET_NO_LOADING_SCREEN) then
            invoke_void(H.SET_NO_LOADING_SCREEN,false)
            noload_ok=not invoke_bool(H.GET_NO_LOADING_SCREEN)
        end
    end)
    if not ok then marker_ok,bit_ok,noload_ok=false,false,false end
    pending.direct_released=marker_ok and bit_ok and noload_ok
    if not pending.direct_released then EntrySkip.cleanup=pending end
    log_entry("InteriorEntry direct_release marker="..tostring(marker_ok).." loading_bit="..tostring(bit_ok)
        .." no_loading="..tostring(noload_ok).." reason="..tostring(reason))
    return marker_ok and bit_ok and noload_ok
end

local function entry_arm_direct(pending)
    if not pending or not entry_api_ready() or ScriptGlobal.AreValid()~=true then return false,"direct APIs unavailable" end
    local excluded=ENTRY_DIRECT_EXCLUDED_FAMILIES[pending.before and pending.before.family]
    if excluded then return false,"direct seamless lease excluded: "..tostring(excluded) end
    local marker=entry_global(ENTRY_DIRECT_MARKER)
    local loading_flags=entry_global(ENTRY_LOADING_FLAGS)
    local no_loading=invoke_bool(H.GET_NO_LOADING_SCREEN)
    pending.direct_marker_before=marker
    pending.loading_flags_before=loading_flags
    pending.no_loading_before=no_loading
    -- Refuse to steal a seamless/loading-screen lease already owned by GTA or
    -- another script. The regular camera-bit bypass remains available as fallback.
    if marker~=-1 then return false,"Rockstar seamless marker is already owned ("..tostring(marker)..")" end
    if (loading_flags & 1)~=0 or no_loading then return false,"Rockstar no-loading-screen state is already owned" end

    if not entry_set_global(ENTRY_DIRECT_MARKER,pending.before.property)
        or entry_global(ENTRY_DIRECT_MARKER)~=pending.before.property then
        return false,"seamless marker write/readback failed"
    end
    pending.direct_marker_owned=true

    local flags_applied=loading_flags | 1
    if not entry_set_global(ENTRY_LOADING_FLAGS,flags_applied)
        or (entry_global(ENTRY_LOADING_FLAGS) & 1)==0 then
        local rollback_ok=entry_release_direct(pending,"arm rollback: loading ownership bit")
        pending.direct_rollback_failed=not rollback_ok
        return false,"loading ownership bit write/readback failed"
    end
    pending.loading_bit_owned=true
    pending.loading_flags_applied=flags_applied

    invoke_void(H.SET_NO_LOADING_SCREEN,true)
    if not invoke_bool(H.GET_NO_LOADING_SCREEN) then
        local rollback_ok=entry_release_direct(pending,"arm rollback: no-loading readback")
        pending.direct_rollback_failed=not rollback_ok
        return false,"SET_NO_LOADING_SCREEN readback failed"
    end
    pending.no_loading_owned=true
    pending.direct_armed=true
    log_entry("InteriorEntry status=DIRECT_ARMED property="..pending.before.property
        .." seamless_before="..marker.." loading_flags_before="..loading_flags.." no_loading_before="..tostring(no_loading))
    return true
end

local function entry_cancel(reason,allow_restore)
    local pending=EntrySkip.pending
    if not pending then return end
    EntrySkip.pending=nil
    local restored=false
    if allow_restore and entry_api_ready() then
        local ok=pcall(function()
            local image,base=entry_image()
            if not image or base~=pending.base then return end
            local subject=entry_context()
            if not subject or subject.ped~=pending.ped or subject.model~=pending.model then return end
            local s=entry_ext_snapshot()
            if entry_identity(s,pending.before) and s.phase==2 and s.presentation==0 and s.progress==0
                and s.camera==0 and s.shots==0 and s.view==0 and s.flags==pending.applied then
                ScriptLocal.SetInt(ENTRY_EXT,732,pending.before.flags)
                local after=entry_ext_snapshot()
                restored=entry_identity(after,pending.before) and after.phase==2 and after.flags==pending.before.flags
            end
        end)
        if not ok then restored=false end
    end
    local direct_restored=entry_release_direct(pending,"cancel: "..tostring(reason))
    EntrySkip.status="CANCELLED"
    EntrySkip.detail=tostring(reason)..(restored and "; unconsumed entry choice restored." or "; GTA retains its current transition.")
        ..(pending.direct_armed and (direct_restored and " Direct no-loading state released." or " Direct state release incomplete.") or "")
    log_entry("InteriorEntry status=CANCELLED restored="..tostring(restored).." direct_restored="..tostring(direct_restored).." reason="..tostring(reason))
end
