-- The arrival presentation uses local clones (facility func_5664 f_153[]).
-- The real ped need not occupy the destination until func_8164 cleans it up.
-- Controller target/owner + a ready interior authorize presentation; physical
-- placement remains mandatory only for COMPLETED.
local function entry_arrival_target(property,interior)
    local pid=invoke_int(H.PLAYER_ID)
    return entry_integer(pid,0,31) and entry_global(ENTRY_ROOT+759)==property
        and entry_global(2658296+1+pid*468+325+11)==pid
        and entry_integer(interior,1,0x7FFFFFFF) and invoke_bool(H.IS_INTERIOR_READY,interior)
end
-- func_5664 owns the lowering loop in Global_1951218.f_757. Its stop/release
-- branch runs only after f_196[0] reaches .75, independently of the camera.
-- Verify allocation, cleanup and camera-completion bytecode in the same function.
local FACILITY_AUDIO_SIGNATURES = {
    {0,"2D 02 27 00 00 61 F2 C5 1D 46 99 12 71 5D C6 4E 00 56 E4 07 38 01 41 C9 71 82 06 56 F0 02"},
    {666,"61 F2 C5 1D 40 02 25 17 2C 08 00 92 38 01 41 C9 25 16 82 56 3F 00 61 F2 C5 1D 47 F5 02 70 57 31 00 2C 01 00 39 61 F2 C5 1D 48 F5 02 70 64 2A 0A 01 66 64 B2 09 01 66 72 2C 10 04 51 61 F2 C5 1D 47 F5 02 64 96 0C 01 66 64 B2 09 01 66 72 2C 10 04 51 55 00"},
    {1518,"01 40 C4 35 01 2C 01 03 C3 29 00 00 80 3D 10 0E 71 38 01 40 C4 36 01 71 38 01 40 C4 35 01 7A 7B 5D C6 4B 12 71 38 01 40 C4 36 01 71 38 01 40 BD 34 01 71 38 01 40 C4 35 01 29 00 00 80 3E 0E 71 5D E4 48 19 55 29 00 61 F2 C5 1D 47 F5 02 70 58 1E 00 61 F2 C5 1D 47 F5 02 2C 04 01 5E 61 F2 C5 1D 47 F5 02 2C 04 00 34 70 61 F2 C5 1D 48 F5 02"},
    {2040,"61 F2 C5 1D 46 99 12 47 82 01 06 56 04 00 72 2E 02 01 71 2E 02 01"},
}
local function entry_facility_audio_guard(pending)
    if pending.facility_audio_guard~=nil then return pending.facility_audio_guard end
    pending.facility_audio_guard=false
    if not Memory or type(Memory.ScanScript)~="function" or type(Memory.ReadUByte)~="function" then return false end
    local ok,verified=pcall(function()
        local ptr=Memory.ScanScript(ENTRY_INT,FACILITY_AUDIO_SIGNATURES[1][2])
        if not entry_integer(ptr,65536,0x00007FFFFFFFEFFF-2062) then return false end
        for _,segment in ipairs(FACILITY_AUDIO_SIGNATURES) do
            local offset=segment[1]
            for byte in segment[2]:gmatch("%x%x") do
                if Memory.ReadUByte(ptr+offset)~=tonumber(byte,16) then return false end
                offset=offset+1
            end
        end
        return true
    end)
    pending.facility_audio_guard=ok and verified==true
    return pending.facility_audio_guard
end
local function entry_finish_facility_audio(pending,phase,bank,owns_target)
    if pending.before.family~=9 or bank~=ENTRY_ROOT+4761 then return true end
    -- local263.f_12.f_6.f_201 bit0 proves func_5664 initialized the presentation.
    -- Without it GTA could allocate/start the loop after our timer was expired.
    if phase~=24 or not entry_facility_audio_guard(pending) or not owns_target() then return false end
    local flags=entry_read(ENTRY_INT,482)
    if (flags & 1)==0 then return false end
    local index=ENTRY_ROOT+757
    local sound=entry_global(index)
    if sound==-1 then return true end
    if not entry_integer(sound,0,0x7FFFFFFF) or (flags & (1<<22))==0 then return false end
    if not owns_target() or entry_read(ENTRY_INT,482)~=flags or entry_global(index)~=sound then return false end
    invoke_void(0xA3B0C41BA5CC0BB5,sound) -- STOP_SOUND: only this controller's lowering loop.
    -- Retire the slot before RELEASE_SOUND_ID can make its numeric ID reusable.
    -- If STOP or sentinel publication fails, leave the camera alone and let GTA
    -- finish its normal lifetime; never release a handle still published by GTA.
    if not owns_target() or entry_global(index)~=sound then return false end
    if not entry_set_global(index,-1) or entry_global(index)~=-1 then return false end
    invoke_void(0x353FC880830B88FA,sound) -- RELEASE_SOUND_ID
    log_entry("InteriorEntry status=FACILITY_AUDIO_RELEASED property="..pending.before.property
        .." source=func_5664 slot=Global_1951218.f_757")
    return owns_target() and entry_global(index)==-1
end
local function entry_suppress_arrival_presentation(pending,subject,phase,interior)
    if not pending or not subject then return end
    local family=pending.before and pending.before.family
    if not (pending.direct_armed or pending.arrival_only or (pending.fast_path and (family==9 or family==17))) then return end
    if family==7 or ENTRY_DIRECT_EXCLUDED_FAMILIES[family] then return end -- Hangar uses its own arrival path.
    -- Enhanced main phase 24 -> func_8161 -> event117 -> func_5664 is
    -- the facility platform arrival. It completes when this same camera bank
    -- finishes; excluding 24 left the lowering platform entirely untouched.
    if not ((phase>=2 and phase<=7) or (family==9 and phase==24))
        or not entry_integer(interior,1,0x7FFFFFFF) then return end
    local function owns_target()
        local current=entry_context()
        return current and current.ped==subject.ped and current.model==subject.model
            and is_on("skip_entry_cutscenes") and started and current_callback(lifecycle)
            and pending.epoch==cutscene_request_epoch and pending.lifecycle==lifecycle_epoch
            and pending.int_bound and entry_threads(ENTRY_INT)==1 and entry_pointer(ENTRY_INT,263)==pending.int_ptr
            and entry_read(ENTRY_INT,265)==pending.before.property and entry_read(ENTRY_INT,266)==family
            and entry_read(ENTRY_INT,267)==phase and entry_read(ENTRY_INT,271)==interior
            and entry_arrival_target(pending.before.property,interior)
    end
    if not owns_target() or not entry_arrival_guard(pending) then return end
    -- func_8312 advances and cleans each camera shot when now-f_374 >= duration.
    -- Advance only that elapsed timer after shot initialization and ready destination.
    -- GTA retains shot events, camera destruction, control restoration and all phase writes.
    pending.arrival_shots=pending.arrival_shots or {}
    local now=now_ms()
    for _,camera_index in ipairs(ARRIVAL_CAMERA_BANKS) do
        local bank=camera_index-387
        local count,shot=entry_global(bank+372),entry_global(bank+382)
        local setup,start,cam=entry_global(bank+379),entry_global(bank+374),entry_global(camera_index)
        if entry_global(bank+386)==1 and entry_integer(count,1,10) and entry_integer(shot,0,count-1)
            and entry_integer(setup,0,0x7FFFFFFF) and (setup & (1<<shot))~=0
            and entry_integer(cam,1,0x7FFFFFFF) and invoke_bool(H.DOES_CAM_EXIST,cam) then
            local duration_index=bank+18+1+shot*36
            local duration=entry_global(duration_index)
            local key=tostring(bank)..":"..shot
            if not pending.arrival_shots[key] and entry_integer(duration,1,60000) and now>=duration
                and entry_integer(start,0,0x7FFFFFFF) and now>=start and now-start<duration then
                if owns_target() and entry_global(bank+386)==1 and entry_global(bank+382)==shot
                    and entry_global(camera_index)==cam and entry_global(bank+374)==start
                    and entry_global(duration_index)==duration and entry_global(bank+379)==setup
                    and entry_finish_facility_audio(pending,phase,bank,owns_target) then
                    pending.arrival_shots[key]=true -- A rejected backend is not retried against a later scene.
                    local target=now-duration
                    local accepted=entry_set_global(bank+374,target) and entry_global(bank+374)==target
                    log_entry("InteriorEntry status="..(accepted and "ARRIVAL_TIMER_SHORTENED" or "ARRIVAL_TIMER_REJECTED")
                        .." property="..pending.before.property.." family="..family.." shot="..shot
                        .." controller=am_mp_smpl_interior_int phase_owned_by_gta=true")
                end
