function Audio.enabled(key)
    -- Read the control itself: deferred callbacks and config loads must not
    -- leave an enabled audio checkbox disconnected from its native owner.
    local feature=feature_ref(key)
    if not feature or type(feature.IsToggled)~="function" then return false end
    local ok,value=pcall(function() return feature:IsToggled() end)
    if ok and type(value)=="boolean" then return value end
    Audio.failure("toggle:"..tostring(key),value)
    return false
