function Audio.frame_requested()
    return not Audio.clean() or Audio.diag.probe_pending
        or Audio.enabled("mute_traffic_ambience") or Audio.enabled("mute_npc_voices")
        or Audio.enabled("mute_active_sirens") or Audio.enabled("mute_tv_audio")
        or Audio.enabled("mute_phone_ringtone") or Audio.enabled("mute_environment_ambience")
        or Audio.enabled("mute_music")
end
function Audio.frame_tick()
    local serviced=Audio.tick(false)
    if serviced or Audio.stopping or Audio.reset then return end
    -- Reassert a bounded rotating slice between discovery scans. Recreated
    -- handles are checked again, and only acquired flags get persistent writes.
    Audio.frame_cursor=Audio.frame_cursor or {Ped=0,Vehicle=0}
    for _,spec in ipairs({{Audio.peds,"Ped","mute_npc_voices"},
                          {Audio.vehicles,"Vehicle","mute_active_sirens"}}) do
        if Audio.enabled(spec[3]) then
            -- Ledger membership changes during discovery or a siren release.
            -- Retain one stable rotation between those events, without sorting
            -- and allocating both handle arrays on every rendered frame.
            Audio.frame_handles=Audio.frame_handles or {}
            local cached=Audio.frame_handles[spec[2]]
            if not cached or cached.entries~=spec[1] then
                cached={entries=spec[1],handles={}}
                for handle in pairs(spec[1]) do cached.handles[#cached.handles+1]=handle end
                Audio.frame_handles[spec[2]]=cached
            end
            local handles=cached.handles
            local count=#handles
            if count>0 then
                local first=Audio.frame_cursor[spec[2]]%count
                local visited=math.min(16,count)
                for i=0,visited-1 do
                    local handle=handles[(first+i)%count+1]
                    local p=spec[1][handle]
                    if p and Audio.same(p)==true and Audio.near(p) then
                        if spec[2]=="Ped" then Audio.stop_speech(p)
                        else Audio.service_siren(p) end
                    end
                end
                Audio.frame_cursor[spec[2]]=(first+visited)%count
            end
        end
    end
end

-- End local audio owner.

-- Current Enhanced 1158.16 camera resource adapter. The Gen9 parser and
-- Enhanced gameplay-director locators come from rage-parser-dumps and Menyoo.
-- Current-process traces prove the constructor/type getter, selected-camera
-- method and FPS metadata getter. All displacements below are re-read from
-- those typed structures/instructions; no Legacy camera layout is used.
local FirstPersonPitch = {phase="OFF",detail="First-person camera limits are off.",busy=false}
function FirstPersonPitch.Snapshot()
    local l=FirstPersonPitch.lease
    return {phase=FirstPersonPitch.phase,detail=FirstPersonPitch.detail,
        owned=l~=nil and (l.fields[1].touched or l.fields[2].touched)or false,
        restore_pending=FirstPersonPitch.restore_pending==true,
        original_min=l and l.fields[1].original or nil,original_max=l and l.fields[2].original or nil,
        min_pitch=l and l.fields[1].wanted or nil,max_pitch=l and l.fields[2].wanted or nil,
        metadata=l and ("0x%X"):format(l.address)or nil}
end
function FirstPersonPitch.status(phase,detail)
    FirstPersonPitch.phase,FirstPersonPitch.detail=phase,tostring(detail)
    State.first_person_pitch=FirstPersonPitch.Snapshot()
end
function FirstPersonPitch.Clean()
    return FirstPersonPitch.lease==nil and not FirstPersonPitch.busy
end
function FirstPersonPitch.domain_allowed()
    local runtime=module_context and module_context.CScript and module_context.CScript.Runtime
    if runtime and type(runtime.RuntimeWriteAllowed)=="function" then
        local ok,allowed=pcall(runtime.RuntimeWriteAllowed,"World")
        return ok and allowed==true
    end
    return true
end
function FirstPersonPitch.discover()
    local m=module_context and module_context.Raw and module_context.Raw.Memory or Memory
    for _,name in ipairs({"GetBaseAddress","Scan","ReadUInt","ReadUShort","ReadUByte","ReadInt","ReadLong","ReadFloat","WriteFloat"})do
        assert(type(m)=="table" and type(m[name])=="function","Camera memory API unavailable: "..name)
    end
