        local value=m[kind](a)
        assert(type(value)=="number" and value==value and value~=math.huge and value~=-math.huge,"Camera reader returned invalid value")
        return value
    end
    local r=p.read
    p.base=m.GetBaseAddress("GTA5_Enhanced.exe");local base=p.base
    assert(p.pointer(base) and r("ReadUShort",base)==0x5A4D,"Enhanced camera image unavailable")
    local pe=r("ReadUInt",base+0x3C)
    assert(pe>0 and pe<0x1000 and r("ReadUInt",base+pe)==0x4550
        and r("ReadUShort",base+pe+4)==0x8664 and r("ReadUShort",base+pe+24)==0x20B,"Camera PE identity mismatch")
    assert(r("ReadUInt",base+pe+8)==1789157136 and r("ReadUInt",base+pe+24+56)==0x5B45200,
        "Camera backend does not support this Enhanced executable build")
