        for _,s in ipairs(sections)do if s.name==name and a>=s.first and a+n<=s.last then return true end end
        return false
    end
    function p.data(a,n)return p.inside(a,n,".data")or p.inside(a,n,".rdata")end
    function p.matches(a,pattern)
