    local manager=r("ReadLong",slot);assert(p.pointer(manager),"Camera parser manager unavailable")
    local buckets,n,entries=r("ReadLong",manager+0x30),r("ReadUShort",manager+0x38),r("ReadUShort",manager+0x3A)
    assert(p.pointer(buckets)and n>=1 and n<=65535 and entries>=1 and entries<=65535,"Camera parser map invalid")
