                or ClearArea.Requested()
                or is_on("low_peds") or is_on("low_traffic")
                or is_on("disable_decals") or is_on("suppress_postfx") or is_on("skip_entry_cutscenes")
                or is_on("first_person_pitch") or Tips.enabled() or Audio.frame_requested())
        end,
        FastTick = function(...) return gameplay_callback(token, fast_tick, ...) end,
        RestoreWorld = restore_world,
        OnSessionChange = on_session_change,
        StopVisualEffects = stop_visual_effects,
        ClearAreaSnapshot = ClearArea.Snapshot,
        State = State,
        WeatherSnapshot = weather_snapshot,
        ApplyWeather = apply_weather,
        ClearWeather = clear_weather,
        CutsceneSkipSnapshot = cutscene_skip_snapshot,
        FPSUnlockSnapshot = fps_snapshot,
        RestoreFPSUnlock = restore_fps_unlock,
