        Audio.tick = perf.Wrap("world.audio_tick", Audio.tick, 127)
        entry_tick = perf.Wrap("world.entry", entry_tick, 127)
        property_entry_tick = perf.Wrap("world.property_entry", property_entry_tick, 127)
        stop_visual_effects_now = perf.Wrap("world.postfx", stop_visual_effects_now, 127)
        first_person_pitch_tick = perf.Wrap("world.firstperson_pitch", first_person_pitch_tick, 127)
    end
