-- Pure lease check. Native restoration stays on FrameTick/FastTick/DrainUnload.
function Module.CanHandoff()
    if not Audio.clean() or not FirstPersonPitch.Clean() then return false end
    local owned=lifecycle and lifecycle.owned or {}
