            centered(cx,caption_y+font+13,visual.identity,w-40,171,156,192,title_alpha*225)
            if state.dismiss_supported then centered(cx,caption_y+2*(font+13),"Enter to continue",w-40,167,154,186,title_alpha*205) end
            local spread=56*settle
