local SESSION_BIND_MIN_MS = 700
local MENU_REVEAL_MS = 300
local ACTIVATION_ARM_MS = 440
local HEAVY_STAGE_HOLD_MS = 160

-- The child remains visible while this file is compiled and initialized.
-- Retain only this session's shared, presentation-only handoff.
local bridge_loading=rawget(_G,"__CSCRIPT_BRIDGE_LOADING")
