    if not bridge_loading then return end
    local owned=bridge_loading
    bridge_loading=nil
    if rawget(_G,"__CSCRIPT_BRIDGE_LOADING")~=owned then return end
    if owned.Active==true then pcall(owned.Close) end
    if rawget(_G,"__CSCRIPT_BRIDGE_LOADING")==owned then rawset(_G,"__CSCRIPT_BRIDGE_LOADING",nil) end
end

local SOURCE_ORDER = {
