local FPS_PATTERN = "84 C0 74 79 48 29 FE 78 0A 0F 57 FF F3 48 0F 2A FE EB 18 48 89 F0"
local FPS_PATCHED_PATTERN = "84 C0 74 00 48 29 FE 78 0A 0F 57 FF F3 48 0F 2A FE EB 18 48 89 F0"
local ITEM_REGISTRY_PATTERN =
    "4C 8B 05 ? ? ? ? EB ? 66 2E 0F 1F 84 00 00 00 00 00 " ..
    "FF C2 89 D1 39 F1 7F ? 8D 14 31 D1 FA 49 8B 1C D0 " ..
    "8B 7B 10 39 F8 74 ? 73 ? FF CA 89 D6 39 F1 7E ? 31 C9 EB ?"
