-- Keep startup failures observable. The previous no-op logger discarded the
-- only explanation whenever the graphical loader entered BOOT FAILED.
local function safe_log(level, message)
    if Logger and type(Logger[level]) == "function" then
        local ok = pcall(Logger[level], "[CScript preboot] " .. tostring(message))
        return ok
    end
    return false
end

local function fail_host(message)
    safe_log("LogError", message)
    if GUI and type(GUI.AddToast) == "function" and eToastPos and eToastPos.TOP_RIGHT ~= nil then
