    end
    return nil
end

local ROOT = menu_root()
if not ROOT then
    fail_host("FileMgr.GetMenuRootPath is unavailable")
    return
end
local PROJECT = ROOT .. "\\Lua\\CScript"
local RUNTIME_PATH = ROOT .. "\\Lua\\" .. RUNTIME_RELATIVE
local CRC_MANIFEST_PATH = ROOT .. "\\Lua\\" .. CRC_MANIFEST_RELATIVE
local NATIVE_INDEX_PATH = ROOT .. "\\Lua\\" .. NATIVE_INDEX_RELATIVE

if rawget(_G, "CScript") ~= nil then
    fail_host("CScript is already running. Unload it before loading this version.")
    return
end

if FeatureMgr and type(FeatureMgr.GetFeature) == "function"
    and Utils and type(Utils.Joaat) == "function" then
    local ok, existing = pcall(function()
        return FeatureMgr.GetFeature(Utils.Joaat("JinxRebound_about"))
