-- Clear stale tabs before starting a new runtime.
if ClickGUI and type(ClickGUI.RemoveTab) == "function" then pcall(ClickGUI.RemoveTab, "CScript") end
if ClickGUI and type(ClickGUI.RemovePlayerTab) == "function" then pcall(ClickGUI.RemovePlayerTab, "CScript") end

local cache = {
    version = PRELOADER_VERSION,
    native_catalog = nil,
    memory = {},
    integrity = {},
    telemetry = {},
}
rawset(_G, "__CSCRIPT_PREBOOT_CACHE", cache)
rawset(_G, "__CSCRIPT_PREBOOT_SUPPRESS_NOTIFICATIONS", true)

local state = {
    started_ms = 0,
    stage = "HOST CONTRACT",
    detail = "Preparing CScript",
    progress = 0.01,
    source_index = 0,
    source_ok = 0,
    source_compile_passes = 0,
    integrity_index = 0,
    integrity_ok = 0,
    integrity_modified = 0,
    integrity_crc_passes = 0,
    current_source = "waiting",
    compile_next_ms = 0,
    integrity_next_ms = 0,
    stage_enter_ms = 0,
    runtime_chunk = nil,
    runtime_compiled = false,
    runtime_crc = nil,
    runtime_bytes = 0,
    activation_armed_ms = 0,
    runtime_started = false,
    ready_ms = 0,
    failed = false,
    error = nil,
    recent = {},
    host_checks = {},
    session_pid = -1,
    draw_mode = "compact",
    crc_manifest = {},
    bytes_processed = 0,
    native_count = 0,
    native_namespaces = 0,
    native_index_pass = 0,
    native_next_ms = 0,
    memory_probe_index = 0,
    memory_probe_work = 0,
    memory_probe_next_ms = 0,
    memory_probe_hits = 0,
    memory_probe_status = "queued",
    runtime_verify_pass = 0,
    runtime_next_ms = 0,
}
rawset(_G, "__CSCRIPT_PREBOOT_STATE", state)

local function now_ms()
    if ImGui and type(ImGui.GetTime) == "function" then
        local ok, value = pcall(ImGui.GetTime)
        if ok and type(value) == "number" then return math.floor(value * 1000) end
    end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

local function enter_stage(name, detail, progress, now)
    state.stage = name
    state.detail = detail or state.detail
    if progress then state.progress = progress end
    state.stage_enter_ms = now or now_ms()
end

local function add_recent(text, status)
    state.recent[#state.recent + 1] = { text = tostring(text), status = tostring(status or "OK") }
    while #state.recent > 8 do table.remove(state.recent, 1) end
end

local function set_failed(message)
    if state.failed then return end
    state.failed_stage = state.stage
    state.failed = true
    state.error = tostring(message)
    state.stage = "BOOT FAILED"
    state.detail = "Boot failed at " .. tostring(state.failed_stage) .. ". Details saved in Cherax diagnostics."
    rawset(_G, "__CSCRIPT_PREBOOT_SUPPRESS_NOTIFICATIONS", nil)
    safe_log("LogError", "stage=" .. tostring(state.failed_stage) .. " reason=" .. state.error)
    -- Local, bounded failure receipt. The account UID, entitlement keys and
    -- backend secrets never enter this diagnostic. A failed file write must
    -- never make CScript's failure recovery worse.
    if FileMgr and type(FileMgr.WriteFileContent) == "function" then
        local diagnostics_dir = ROOT .. "\\Lua\\CScriptData\\Diagnostics"
        if type(FileMgr.CreateDir) == "function" then
            pcall(FileMgr.CreateDir, ROOT .. "\\Lua\\CScriptData")
            pcall(FileMgr.CreateDir, diagnostics_dir)
        end
        local receipt = "CSCRIPT_PREBOOT_FAILURE_V1\n"
            .. "phase=" .. tostring(state.failed_stage) .. "\n"
            .. "reason=" .. tostring(state.error):sub(1,3000) .. "\n"
            .. "compiled=" .. tostring(state.source_ok) .. "/" .. tostring(#SOURCE_ORDER) .. "\n"
            .. "verified=" .. tostring(state.integrity_ok) .. "/" .. tostring(#SOURCE_ORDER) .. "\n"
            .. "native_count=" .. tostring(state.native_count) .. "\n"
            .. "runtime_compiled=" .. tostring(state.runtime_compiled) .. "\n"
            .. "runtime_started=" .. tostring(state.runtime_started) .. "\n"
        pcall(FileMgr.WriteFileContent, diagnostics_dir .. "\\CScript_BootFailure.txt", receipt, false)
    end
end

local function read_file(path)
    if not (FileMgr and type(FileMgr.ReadFileContent) == "function") then return nil, "FileMgr.ReadFileContent unavailable" end
    local ok, value = pcall(FileMgr.ReadFileContent, path)
    if not ok or type(value) ~= "string" then return nil, ok and "read returned non-string" or tostring(value) end
    return value
end

local CRC_TABLE = {}
do
    for n = 0, 255 do
        local c = n
        for _ = 1, 8 do
            if (c & 1) ~= 0 then c = (c >> 1) ~ 0xEDB88320 else c = c >> 1 end
        end
        CRC_TABLE[n] = c & 0xFFFFFFFF
    end
end
local function crc32(data)
    local crc = 0xFFFFFFFF
    for i = 1, #data do
        local b = string.byte(data, i)
        crc = ((crc >> 8) ~ CRC_TABLE[(crc ~ b) & 0xFF]) & 0xFFFFFFFF
    end
    return (~crc) & 0xFFFFFFFF
end
local function crc_hex(v) return string.format("%08X", v & 0xFFFFFFFF) end

local function load_crc_manifest()
    local raw, err = read_file(CRC_MANIFEST_PATH)
    if not raw then return false, err end
    local out = {}
    for line in raw:gmatch("[^\r\n]+") do
        local path, crc, size = line:match("^([^|]+)|([0-9A-Fa-f]+)|(%d+)$")
        if path and crc and size then out[path:gsub("\\", "/")] = { crc = crc:upper(), size = tonumber(size) or 0 } end
    end
    if not out["CScript/dist/loader.lua"] then return false, "runtime entry missing from CRC manifest" end
    state.crc_manifest = out
    return true
end

local function host_contract()
    local checks = {
        { "ImGui present renderer", ImGui and type(ImGui.BgAddRectFilled) == "function" and type(ImGui.BgAddText) == "function" },
        { "ON_PRESENT event", EventMgr and type(EventMgr.RegisterHandler) == "function" and eLuaEvent and eLuaEvent.ON_PRESENT ~= nil },
        { "Lua compiler", type(loadfile) == "function" },
        { "File streaming", FileMgr and type(FileMgr.ReadFileContent) == "function" },
        { "Feature registry", FeatureMgr and type(FeatureMgr.AddFeature) == "function" },
        { "ClickGUI bridge", ClickGUI and type(ClickGUI.AddTab) == "function" },
        { "GTA bridge", GTA ~= nil },
        { "Runtime bundle", FileMgr and type(FileMgr.DoesFileExist) == "function" and (function() local ok,v=pcall(FileMgr.DoesFileExist,RUNTIME_PATH); return ok and v==true end)() },
        { "Integrity manifest", FileMgr and type(FileMgr.DoesFileExist) == "function" and (function() local ok,v=pcall(FileMgr.DoesFileExist,CRC_MANIFEST_PATH); return ok and v==true end)() },
        { "Native catalog", FileMgr and type(FileMgr.DoesFileExist) == "function" and (function() local ok,v=pcall(FileMgr.DoesFileExist,NATIVE_INDEX_PATH); return ok and v==true end)() },
    }
    state.host_checks = checks
    for _, item in ipairs(checks) do if item[2] ~= true then return false, item[1] end end
    local ok, why = load_crc_manifest()
    if not ok then return false, "integrity manifest: " .. tostring(why) end
    return true
end

local function compile_source(relative)
    local path = PROJECT .. "\\" .. tostring(relative):gsub("/", "\\")
    local env = setmetatable({}, { __index = _G })
    local chunk, err = loadfile(path, "t", env)
    if not chunk then return false, err end
    state.source_compile_passes = state.source_compile_passes + 1
    return true
end

local function verify_source_integrity(relative)
    local package_path = "CScript/" .. relative
    local expected = state.crc_manifest[package_path]
    if not expected then return false, "manifest missing " .. package_path end
    local absolute = PROJECT .. "\\" .. relative:gsub("/", "\\")
    local raw, err = read_file(absolute)
    if not raw then return false, err end
    local got = crc_hex(crc32(raw))
    state.integrity_crc_passes = state.integrity_crc_passes + 1
    state.bytes_processed = state.bytes_processed + #raw
    cache.integrity[relative] = { crc = got, bytes = #raw, expected = expected.crc, match = got == expected.crc }
    if got == expected.crc and #raw == expected.size then return true, got, #raw end
    return true, got, #raw, "modified"
end

local function index_native_catalog()
    local raw, err = read_file(NATIVE_INDEX_PATH)
    if not raw then return false, err end
    local by_name, by_hash, namespaces = {}, {}, {}
    local count = 0
    for line in raw:gmatch("[^\r\n]+") do
        local ns, hash, name, ret = line:match("^([^|]*)|([^|]*)|([^|]*)|([^|]*)$")
        if ns and hash and name and name ~= "" then
            count = count + 1
            namespaces[ns] = true
            by_name[name] = { hash = hash, namespace = ns, return_type = ret }
            by_hash[hash] = { name = name, namespace = ns, return_type = ret }
        end
    end
    local ns_count = 0; for _ in pairs(namespaces) do ns_count = ns_count + 1 end
    cache.native_catalog = { by_name = by_name, by_hash = by_hash, count = count, namespaces = ns_count }
    state.native_count, state.native_namespaces = count, ns_count
    state.bytes_processed = state.bytes_processed + #raw
    return count >= 6000, count
end

local MEMORY_PROBES = {
    { key = "fps_limiter", label = "Enhanced FPS/audio limiter", patterns = { FPS_PATTERN, FPS_PATCHED_PATTERN } },
    { key = "item_registry", label = "CItemInfo registry", patterns = { ITEM_REGISTRY_PATTERN } },
}
local function run_memory_probe(index)
    local spec = MEMORY_PROBES[index]
    if not spec then return false, "no probe" end
    if not (Memory and type(Memory.Scan) == "function") then
        cache.memory[spec.key] = { status = "unavailable", address = nil }
        return true, "Memory.Scan unavailable"
    end
    local found = nil
    for _, pattern in ipairs(spec.patterns) do
        local ok, value = pcall(Memory.Scan, pattern, GAME_IMAGE)
        if ok and type(value) == "number" and value > 0 then found = value; break end
    end
    local previous = cache.memory[spec.key]
    cache.memory[spec.key] = { status = found and "ready" or "not-found", address = found, label = spec.label }
    if found and not (previous and previous.status == "ready") then state.memory_probe_hits = state.memory_probe_hits + 1 end
    return true, found and string.format("0x%X", found) or "not found"
end

local function compile_runtime_and_fingerprint(keep_chunk)
    local raw, err = read_file(RUNTIME_PATH)
    if not raw then return false, err end
    local expected = state.crc_manifest["CScript/dist/loader.lua"]
    local got = crc_hex(crc32(raw))
    state.runtime_crc, state.runtime_bytes = got, #raw
    state.bytes_processed = state.bytes_processed + #raw
    local match = expected and got == expected.crc and #raw == expected.size or false
    cache.integrity.runtime = { crc = got, bytes = #raw, expected = expected and expected.crc or nil, match = match }
    if not match then
        add_recent("Runtime package fingerprint differs from release manifest", "MODIFIED")
        safe_log("LogWarning", ("runtime fingerprint differs expected=%s/%s got=%s/%d; compile/activation will still decide usability"):format(tostring(expected and expected.crc), tostring(expected and expected.size), got, #raw))
    end
    local chunk, compile_err = loadfile(RUNTIME_PATH, "t", _G)
    if not chunk then return false, compile_err end
    state.runtime_verify_pass = state.runtime_verify_pass + 1
    if keep_chunk then
        state.runtime_chunk = chunk
        state.runtime_compiled = true
    end
    return true
end

local function local_session_ready()
    if GTA and type(GTA.GetLocalPlayerId) == "function" then
        local ok, value = pcall(GTA.GetLocalPlayerId)
        if ok and type(value) == "number" and value >= 0 and value <= 31 then state.session_pid = value; return true end
    end
    return false
end

local function perform_activation()
    if state.runtime_started or state.failed then return end
    state.runtime_started = true
    enter_stage("ACTIVATING MODULE GRAPH", "Starting modules and loading settings", 0.94)
    safe_log("LogInfo", "Starting runtime")
    rawset(_G, "__CSCRIPT_PREBOOT_HANDOFF", true)
    local ok, err = xpcall(state.runtime_chunk, function(value)
        if debug and type(debug.traceback) == "function" then return debug.traceback(tostring(value), 2) end
        return tostring(value)
    end)
    rawset(_G, "__CSCRIPT_PREBOOT_HANDOFF", nil)
    if not ok then set_failed("runtime activation failed: " .. tostring(err)); return end
    local runtime = rawget(_G, "CScript")
    local diag = runtime and runtime.Diagnostics
    if type(runtime) ~= "table" or type(diag) ~= "table" or tostring(diag.Phase or ""):lower() ~= "ready" then
        set_failed("runtime returned without READY diagnostics"); return
    end
    cache.telemetry.runtime_ready = true
    -- Cache readiness once; rendering does not poll game state.
    if runtime.UI and type(runtime.UI.GetHandoffPresentation)=="function" then
        local got,presentation=pcall(runtime.UI.GetHandoffPresentation)
        if got and type(presentation)=="table" then state.handoff_presentation=presentation end
    end
    enter_stage("CSCRIPT READY", "Opening CScript", 0.98)
    state.ready_ms = now_ms()
    state.runtime_ready = true
    state.quick = state.handoff_presentation and state.handoff_presentation.quick == true or false
    state.hold_ms=state.handoff_presentation and state.handoff_presentation.hold_ms or 2000
    state.dismiss_supported = Utils and type(Utils.IsKeyDown)=="function" or false
    -- A held key from loading cannot dismiss; require release then a fresh press.
    state.dismiss_armed = false
    add_recent("Runtime modules started", "READY")
    safe_log("LogInfo", "Runtime ready; opening the menu")
end

local function advance(now)
    if state.failed or state.ready_ms > 0 then return end
    if state.started_ms == 0 then state.started_ms = now; state.stage_enter_ms = now end

    if state.stage == "HOST CONTRACT" then
        local ok, detail = host_contract()
        if not ok then set_failed("host contract missing: " .. tostring(detail)); return end
        enter_stage("VERIFYING MODULE SOURCES", "Compiling installed modules", 0.06, now)
        state.compile_next_ms = now
        add_recent("Host + asset contract verified", "READY")
        safe_log("LogInfo", "Startup requirements verified")
        return
    end

    if state.stage == "VERIFYING MODULE SOURCES" then
        if state.source_index < #SOURCE_ORDER and now >= state.compile_next_ms then
            state.source_index = state.source_index + 1
            local relative = SOURCE_ORDER[state.source_index]
            state.current_source = relative
            local ok, err = compile_source(relative)
            if not ok then set_failed(("source compile failed %s: %s"):format(relative, tostring(err))); return end
            state.source_ok = state.source_ok + 1
            add_recent(relative, "COMPILED")
            state.progress = 0.06 + 0.22 * (state.source_ok / #SOURCE_ORDER)
            state.detail = ("Compiling %d/%d  |  %s"):format(state.source_ok, #SOURCE_ORDER, relative)
            state.compile_next_ms = now + SOURCE_INTERVAL_MS
        end
        if state.source_index >= #SOURCE_ORDER then
            enter_stage("DEEP SOURCE INTEGRITY", "Comparing source files with the release manifest", 0.30, now)
            state.integrity_index = 0
            state.integrity_next_ms = now
        end
        return
    end

    if state.stage == "DEEP SOURCE INTEGRITY" then
        if state.integrity_index < #SOURCE_ORDER and now >= state.integrity_next_ms then
            state.integrity_index = state.integrity_index + 1
            local relative = SOURCE_ORDER[state.integrity_index]
            state.current_source = relative
            local ok, crc, bytes, status = verify_source_integrity(relative)
            if not ok then set_failed(("integrity read failed %s: %s"):format(relative, tostring(crc))); return end
            if status == "modified" then state.integrity_modified = state.integrity_modified + 1 else state.integrity_ok = state.integrity_ok + 1 end
            add_recent(relative, status == "modified" and "MODIFIED" or ("CRC " .. tostring(crc)))
            state.progress = 0.30 + 0.20 * (state.integrity_index / #SOURCE_ORDER)
            state.detail = ("Checking %d/%d  |  %s"):format(state.integrity_index, #SOURCE_ORDER, relative)
            state.integrity_next_ms = now + INTEGRITY_INTERVAL_MS
            return
        end
        if state.integrity_index >= #SOURCE_ORDER and now - state.stage_enter_ms >= HEAVY_STAGE_HOLD_MS then
            enter_stage("INDEXING NATIVE CATALOG", "Loading the GTA native catalog", 0.52, now)
            state.native_index_pass = 0
            state.native_next_ms = now
        end
        return
    end

    if state.stage == "INDEXING NATIVE CATALOG" then
        if state.native_index_pass < NATIVE_INDEX_PASSES and now >= state.native_next_ms then
            local ok, why = index_native_catalog()
            if not ok then set_failed("native catalog indexing failed: " .. tostring(why)); return end
            state.native_index_pass = state.native_index_pass + 1
            add_recent(("Native catalog: %d entries"):format(state.native_count), "INDEXED")
            state.progress = 0.52 + 0.11 * (state.native_index_pass / NATIVE_INDEX_PASSES)
            state.detail = ("Loaded %d natives in %d namespaces"):format(state.native_count,state.native_namespaces)
            state.native_next_ms = now + NATIVE_PASS_INTERVAL_MS
            return
        end
        if state.native_index_pass >= NATIVE_INDEX_PASSES then
            enter_stage("SCANNING GTA IMAGE", "Locating game data", 0.65, now)
            state.memory_probe_index = 0
            state.memory_probe_work = 0
            state.memory_probe_next_ms = now
            state.memory_probe_status = "running"
        end
        return
    end

    if state.stage == "SCANNING GTA IMAGE" then
        local total = #MEMORY_PROBES * MEMORY_PROBE_PASSES
        if state.memory_probe_work < total and now >= state.memory_probe_next_ms then
            state.memory_probe_work = state.memory_probe_work + 1
            local probe_index = ((state.memory_probe_work - 1) % #MEMORY_PROBES) + 1
            state.memory_probe_index = probe_index
            local spec = MEMORY_PROBES[probe_index]
            state.detail = ("Locating %d/%d  |  %s"):format(probe_index,#MEMORY_PROBES,spec.label)
            local _, why = run_memory_probe(probe_index)
            add_recent(("%s | %s"):format(spec.label,tostring(why)), cache.memory[spec.key] and cache.memory[spec.key].status:upper() or "DONE")
            state.progress = 0.65 + 0.10 * (state.memory_probe_work / total)
            state.memory_probe_next_ms = now + MEMORY_PROBE_INTERVAL_MS
            return
        end
        if state.memory_probe_work >= total and now - state.stage_enter_ms >= HEAVY_STAGE_HOLD_MS then
            enter_stage("FINGERPRINTING RUNTIME", "Checking and compiling the runtime bundle", 0.77, now)
            state.runtime_verify_pass = 0
            state.runtime_next_ms = now
        end
        return
    end

    if state.stage == "FINGERPRINTING RUNTIME" then
        if state.runtime_verify_pass < RUNTIME_VERIFY_PASSES and now >= state.runtime_next_ms then
            local final = state.runtime_verify_pass + 1 >= RUNTIME_VERIFY_PASSES
            local ok, err = compile_runtime_and_fingerprint(final)
            if not ok then set_failed("runtime verification failed: " .. tostring(err)); return end
            add_recent(("Runtime: %.2f MB | CRC %s"):format(state.runtime_bytes/1048576,tostring(state.runtime_crc)), "VERIFIED")
            state.progress = 0.77 + 0.09 * (state.runtime_verify_pass / RUNTIME_VERIFY_PASSES)
            state.detail = "Runtime bundle checked and compiled"
            state.runtime_next_ms = now + RUNTIME_PASS_INTERVAL_MS
            return
        end
        if state.runtime_compiled and state.runtime_verify_pass >= RUNTIME_VERIFY_PASSES then
            enter_stage("BINDING SESSION CONTEXT", "Checking the current session", 0.87, now)
            state.activation_armed_ms = now
        end
        return
    end

    if state.stage == "BINDING SESSION CONTEXT" then
        local ready = local_session_ready()
        local elapsed = now - (state.activation_armed_ms or now)
        state.progress = ready and 0.91 or 0.87 -- progress follows the session probe, never the waiting clock
        if elapsed >= SESSION_BIND_MIN_MS and (ready or elapsed >= 1100) then
            add_recent(ready and ("Local session pid=" .. tostring(state.session_pid)) or "Session context deferred to runtime", ready and "READY" or "DEFERRED")
            enter_stage("ACTIVATION ARMED", "Checks complete; preparing runtime activation", 0.92, now)
            state.activation_armed_ms = now
        end
        return
    end

    if state.stage == "ACTIVATION ARMED" then
        if now - state.activation_armed_ms >= ACTIVATION_ARM_MS then perform_activation() end
    end
end

-- BEGIN SHARED STARTUP PRESENTATION
local function create_startup_presentation()
    -- Readiness follows the loader state; animation only controls presentation.
    local function clamp(v,a,b) return math.max(a,math.min(b,v)) end
    local function ease(v) v=clamp(v,0,1);return v*v*(3-2*v) end
    local function hold_ms(v) return clamp(tonumber(v) or 2000,1500,3500) end
    local function rgba(v) return math.floor(clamp(v,0,255)) end
    local visible_rect,visible_text=false,false
    local function rect(x,y,xx,yy,r,g,b,a,round)
        if a<1 or xx<=x or yy<=y then return end
        if ImGui and type(ImGui.BgAddRectFilled)=="function" then
            local ok,result=pcall(ImGui.BgAddRectFilled,x,y,xx,yy,rgba(r),rgba(g),rgba(b),rgba(a),round or 0)
            if ok and result~=false then visible_rect=true end
