    local function line(x,y,xx,yy,r,g,b,a,thick)
        if a<1 then return end
        if ImGui and type(ImGui.BgAddLine)=="function" then
            pcall(ImGui.BgAddLine,x,y,xx,yy,rgba(r),rgba(g),rgba(b),rgba(a),thick or 1)
