        if type(fn)=="function" then
            if filled then pcall(fn,x,y,radius,rgba(r),rgba(g),rgba(b),rgba(a),16)
            else pcall(fn,x,y,radius,rgba(r),rgba(g),rgba(b),rgba(a),64,thick or 1) end
        end
    end
    local function text(x,y,s,r,g,b,a)
