            local ok,result=pcall(ImGui.BgAddText,x,y,s,rgba(r),rgba(g),rgba(b),rgba(a))
            if ok and result~=false then visible_text=true end
        end
    end
    local phases={
        {"Setup","Checking your setup","Preparing the CScript runtime.", ["HOST CONTRACT"]=true},
        {"Sources","Preparing CScript","Compiling the installed modules.", ["VERIFYING MODULE SOURCES"]=true},
        {"Integrity","Checking files","Checking the runtime sources.", ["DEEP SOURCE INTEGRITY"]=true},
        {"Services","Loading game services","Preparing the game function catalog.", ["INDEXING NATIVE CATALOG"]=true},
        {"Game","Reading game data","Connecting to the current game.", ["SCANNING GTA IMAGE"]=true},
        {"Runtime","Validating the runtime","Checking the runtime bundle.", ["FINGERPRINTING RUNTIME"]=true},
        {"Session","Checking your session","Reading the current session state.", ["BINDING SESSION CONTEXT"]=true,["ACTIVATION ARMED"]=true},
        {"Settings","Loading settings","Loading your saved preferences.", ["ACTIVATING MODULE GRAPH"]=true,["VERIFYING REGISTRY"]=true,["ARMING PLAYER RUNTIME"]=true,["CHECKING SESSION"]=true,["LOADING PERSISTENCE"]=true},
        {"Interface","Preparing your interface","Finishing menu setup.", ["FINALIZING INTERFACE"]=true,["CSCRIPT READY"]=true},
    }
