    end
    local ticks={}
    for i=0,11 do local a=math.rad(15+i*30);ticks[#ticks+1]={math.cos(a),math.sin(a)} end
    local glyphs={
        C={{{1,0},{.2,0},{0,.2},{0,.8},{.2,1},{1,1}}},
        S={{{1,0},{.15,0},{0,.15},{0,.4},{1,.6},{1,.85},{.85,1},{0,1}}},
        R={{{0,1},{0,0},{.8,0},{1,.2},{1,.35},{.8,.5},{0,.5}},{{.5,.5},{1,1}}},
        I={{{.5,0},{.5,1}}},P={{{0,1},{0,0},{.8,0},{1,.2},{1,.35},{.8,.5},{0,.5}}},
        T={{{0,0},{1,0}},{{.5,0},{.5,1}}},
    }
    local visual={start=nil,last=nil,progress=0,font=0,widths={},fits={},fit_count=0,version=nil,identity="CScript",phase=1,pending=1,phase_at=0}
    local function font_size()
        local f=15
