                if row<2 then line(xx+3,yy+font*.5+6,xx+3,yy+lh+font*.5-6,177,137,216,aa*(done and 59 or 22),1) end
                circle(xx+3,yy+font*.5,active and 3 or 2,done and 188 or 174,done and 162 or 120,231,aa*(active and 245 or done and 170 or 58),not active,1.2)
                text(xx+15,yy,fit(p[1],colw-38),active and 210 or done and 205 or 142,active and 169 or done and 192 or 132,active and 249 or done and 225 or 161,aa*(active and 255 or 223))
