            line(cx+8,cy-radius-44,cx+spread,cy-radius-44,190,145,239,aa*50*settle,1)
            circle(cx,cy-radius-44,2,203,167,243,aa*150*settle,true)
        end
        return visible_rect and visible_text and opacity>=.25
    end
    return {Duration=function(quick,hold)return quick and 240 or 1000+hold_ms(hold) end,
        PublishAt=function(quick,hold)return 0 end,Draw=draw}
