-- END SHARED STARTUP PRESENTATION
local startup_presentation=create_startup_presentation()
local function render(now)
    if not (ImGui and type(ImGui.GetDisplaySize)=="function") then return end
    local ok,w,h=pcall(ImGui.GetDisplaySize)
    if ok and startup_presentation.Draw(state,w,h,now,"CScript " .. PRELOADER_VERSION)==true then
        finish_bridge_presentation()
    end
end

local function release_interface_handoff()
    local runtime=rawget(_G,"CScript")
    local ui=runtime and runtime.UI
    if type(ui)~="table" or type(ui.PublishMainTab)~="function" then
        return false,"runtime UI publication bridge unavailable"
    end
    local ok,result,detail=pcall(ui.PublishMainTab)
    if not ok or result==false then return false,tostring(detail or result) end
    if type(ui.BeginShellReveal)=="function" then pcall(ui.BeginShellReveal,MENU_REVEAL_MS) end
    return true
end

local handler_id
