        path = path:gsub("\\", "/")
        local prefix = path:match("^([A-Za-z]:)/") or (path:sub(1, 1) == "/" and "/" or "")
        if prefix ~= "" then path = path:sub(#prefix + (prefix == "/" and 1 or 2)) end
        local parts = {}
        for part in path:gmatch("[^/]+") do
            if part == ".." then
                if #parts == 0 then return nil end
                parts[#parts] = nil
            elseif part ~= "." then
                parts[#parts + 1] = part
            end
        end
        return (prefix .. "/" .. table.concat(parts, "/")):lower()
    end
    local base = assert(canonical(root), "Invalid Cherax Lua directory")
    local indexed, names = {}, {}
    for path, content in pairs(files) do
        local key = assert(canonical(root .. "/" .. path))
        assert(indexed[key] == nil, "Duplicate virtual source path: " .. path)
        indexed[key], names[key] = content, path
    end
    local function lookup(path)
        if type(path) ~= "string" then return nil end
        local absolute = path:match("^[A-Za-z]:[/\\]") or path:match("^[/\\]")
        return canonical(absolute and path or root .. "/" .. path)
    end
