    function file_mgr.ReadFileContent(path, ...)
        local key = lookup(path)
        if key and indexed[key] ~= nil then return indexed[key] end
        if host.FileMgr and type(host.FileMgr.ReadFileContent) == "function" then
            return host.FileMgr.ReadFileContent(path, ...)
        end
        return nil, "FileMgr.ReadFileContent is unavailable"
    end
    function file_mgr.DoesFileExist(path, ...)
        local key = lookup(path)
        if key and indexed[key] ~= nil then return true end
        if host.FileMgr and type(host.FileMgr.DoesFileExist) == "function" then
            return host.FileMgr.DoesFileExist(path, ...)
        end
        return false
    end
    env.FileMgr = file_mgr
    function env.loadfile(path, mode, target)
        local key = lookup(path)
        if key and indexed[key] ~= nil then
            -- Explicit environments and load modes are part of Lua's contract.
            return host.load(indexed[key], "@" .. root .. "/" .. names[key], mode or "t", target or env)
        end
        -- Never pick up an old installed CScript module after a packaging error.
        if key and (key == base .. "/loader.lua" or key:sub(1, #base + 9) == base .. "/cscript/") then
            return nil, "CScript source not embedded: " .. tostring(path)
        end
        if type(host.loadfile) == "function" then return host.loadfile(path, mode, target or env) end
        return nil, "External loadfile is unavailable: " .. tostring(path)
    end
    function env.dofile(path)
        local chunk, why = env.loadfile(path, "t", env)
        if not chunk then error(why, 2) end
        return chunk()
    end
    return env
end

end)()
assert(FileMgr and type(FileMgr.GetMenuRootPath) == "function", "Cherax menu root unavailable")
local menu_root = FileMgr.GetMenuRootPath()
assert(type(menu_root) == "string" and menu_root ~= "" and not menu_root:find("%z"),
    "Cherax menu root is invalid")
local root = menu_root:gsub("[/\\]+$", "") .. "/Lua"
local environment = make_environment(host, root, files)
environment.SetShouldUnload = lifecycle.RequestUnload
local original_loadfile = environment.loadfile
local function normalized(path) return type(path) == "string" and path:gsub("\\", "/"):lower() or "" end
local bootstrap_path = normalized(root .. "/CScript/bootstrap.lua")
local runtime_bundle_path = normalized(root .. "/CScript/dist/loader.lua")
environment.loadfile = function(path, mode, target)
    local chunk, why = original_loadfile(path, mode, target)
    if not chunk then return nil, why end
    local key = normalized(path)
    if key == bootstrap_path or key == runtime_bundle_path then
        -- Caller-supplied arguments cannot replace the captured authorization.
        return function()
            assert(is_live() == true, "Public runtime authorization expired before bootstrap")
            return chunk(access)
        end
    end
    return chunk
end
local entry, why = environment.loadfile(root .. "/Loader.lua", "t", environment)
if not entry then error(why, 0) end
assert(is_live() == true, "Public runtime authorization expired before startup")
return entry()
end
local ok, result = pcall(start_runtime)
if not ok then
    lifecycle.Close()
    if Logger and type(Logger.LogError) == "function" then
        pcall(Logger.LogError, "[CScript standalone] " .. tostring(result))
    end
    error(result, 0)
end
return result
